(* ========================================================================= *)
(* Relative consistency of the negation of CH with ZFC, via Cohen forcing    *)
(* over Godel's constructible universe L, in Boolean-valued form.            *)
(*                                                                           *)
(* Builds on godel_gch.ml (object language, semantics, internal set theory,  *)
(* L, AC, and the object-language axiom ch_ax expressing CH). Inside a model *)
(* of ZF + V=L we construct the Cohen poset of finite partial functions from *)
(* aleph_2 x omega to a two-element set, its regular-open completion B (an   *)
(* internal complete Boolean algebra, shown to be ccc), the Boolean-valued   *)
(* universe of B-names with Boolean truth values [[p]], and show that every  *)
(* axiom of ZFC, and the negation of CH, has value top. The quotient by an   *)
(* internal ultrafilter on B is then a two-valued model (Los's theorem).     *)
(* Applying this to L inside an arbitrary model gives the main theorem       *)
(* ZF_MODEL_NOT_CH_MODEL: any model of ZF over a type A yields a model over  *)
(* A of ZF + AC + not CH.                                                    *)
(*                                                                           *)
(* As in godel_gch.ml, this is a semantic statement about set-theoretic      *)
(* structures (D,E) in HOL; it is not a syntactic relative-consistency       *)
(* proof Con(ZF) ==> Con(ZFC + not CH) about formal derivations.             *)
(* ========================================================================= *)

needs "Autoformalization/godel_gch.ml";;

(* ===================================================================== *)
(* F1: posets and Boolean algebras in a model W.                          *)
(*                                                                        *)
(* Order-theoretic representation.  A structure is TWO W-objects: a       *)
(* carrier p and an order-set leq (a set-coded binary relation, via      *)
(* erel).  A partial order is eporder; a lattice adds binary meets/joins; *)
(* a Boolean algebra (ebalg) is a bounded, distributive, complemented     *)
(* lattice; a complete BA (ecba) additionally has least upper bounds of   *)
(* every W-subset of the carrier.  The Boolean operations 0,1,meet,join,  *)
(* comp and the arbitrary sup/inf are all DERIVED from (p,leq) via         *)
(* least/greatest/glb/lub, and are unique by antisymmetry -- so a         *)
(* structure carries no operation objects, only p and leq.                *)
(*                                                                        *)
(* NOTE on carriers (a standard forcing subtlety).  ecompat/eantichain/   *)
(* edense are POSET notions (common lower bound / pairwise-no-common-lower *)
(* bound / cofinal-below).  They are non-degenerate only on a poset with  *)
(* NO least element: a bottom 0 sits below everything, so with a bottom    *)
(* all pairs are ecompat and antichains collapse.  They are meant for the *)
(* Cohen forcing poset P (F2, bottomless) and for B+ = B\{0} (the nonzero  *)
(* part of a BA, used for ccc).  efilter/eultra, by contrast, apply to the *)
(* FULL BA carrier: the downward-directed clause is witnessed by the meet, *)
(* and properness (0 not in the filter) is imposed in eultra.             *)
(* ===================================================================== *)

(* -- partial order: leq lives on p, reflexive/antisym/transitive ------ *)
let eporder = new_definition
  `eporder D (E:A->A->bool) p leq <=>
        p IN D /\ leq IN D /\
        (!u v. erel D E leq u v ==> u IN D /\ v IN D /\ E u p /\ E v p) /\
        (!u. u IN D /\ E u p ==> erel D E leq u u) /\
        (!u v. u IN D /\ v IN D /\ E u p /\ E v p /\
               erel D E leq u v /\ erel D E leq v u ==> u = v) /\
        (!u v w. u IN D /\ v IN D /\ w IN D /\
                 E u p /\ E v p /\ E w p /\
                 erel D E leq u v /\ erel D E leq v w
                 ==> erel D E leq u w)`;;

(* -- upper/lower bounds and least-upper / greatest-lower bounds ------- *)
let eubound = new_definition
  `eubound D (E:A->A->bool) p leq s u <=>
        u IN D /\ E u p /\
        (!x. x IN D /\ E x s ==> erel D E leq x u)`;;

let elbound = new_definition
  `elbound D (E:A->A->bool) p leq s u <=>
        u IN D /\ E u p /\
        (!x. x IN D /\ E x s ==> erel D E leq u x)`;;

let elub = new_definition
  `elub D (E:A->A->bool) p leq s u <=>
        eubound D E p leq s u /\
        (!w. eubound D E p leq s w ==> erel D E leq u w)`;;

let eglb = new_definition
  `eglb D (E:A->A->bool) p leq s u <=>
        elbound D E p leq s u /\
        (!w. elbound D E p leq s w ==> erel D E leq w u)`;;

(* -- least (0) and greatest (1) elements of the whole carrier --------- *)
let ebot = new_definition
  `ebot D (E:A->A->bool) p leq z <=>
        z IN D /\ E z p /\ (!x. x IN D /\ E x p ==> erel D E leq z x)`;;

let etop = new_definition
  `etop D (E:A->A->bool) p leq u <=>
        u IN D /\ E u p /\ (!x. x IN D /\ E x p ==> erel D E leq x u)`;;

(* -- binary meet (glb) and join (lub) --------------------------------- *)
let emeet = new_definition
  `emeet D (E:A->A->bool) p leq x y z <=>
        z IN D /\ E z p /\
        erel D E leq z x /\ erel D E leq z y /\
        (!w. w IN D /\ E w p /\ erel D E leq w x /\ erel D E leq w y
             ==> erel D E leq w z)`;;

let ejoin = new_definition
  `ejoin D (E:A->A->bool) p leq x y z <=>
        z IN D /\ E z p /\
        erel D E leq x z /\ erel D E leq y z /\
        (!w. w IN D /\ E w p /\ erel D E leq x w /\ erel D E leq y w
             ==> erel D E leq z w)`;;

(* -- complement of x: meet with x is bot, join with x is top ---------- *)
let ecompl = new_definition
  `ecompl D (E:A->A->bool) p leq x y <=>
        y IN D /\ E y p /\
        (?z u. ebot D E p leq z /\ etop D E p leq u /\
               emeet D E p leq x y z /\ ejoin D E p leq x y u)`;;

(* -- lattice: every pair has a meet and a join ------------------------ *)
let elattice = new_definition
  `elattice D (E:A->A->bool) p leq <=>
        eporder D E p leq /\
        (!x y. x IN D /\ y IN D /\ E x p /\ E y p
               ==> (?z. emeet D E p leq x y z)) /\
        (!x y. x IN D /\ y IN D /\ E x p /\ E y p
               ==> (?z. ejoin D E p leq x y z))`;;

(* -- Boolean algebra: bounded, distributive, complemented lattice ----- *)
(* One distributive law x/\(y\/w) = (x/\y)\/(x/\w) suffices (in any       *)
(* lattice it implies its dual); with boundedness + complements this is a *)
(* Boolean algebra and complements are unique.                           *)
let ebalg = new_definition
  `ebalg D (E:A->A->bool) p leq <=>
        elattice D E p leq /\
        (?z. ebot D E p leq z) /\ (?u. etop D E p leq u) /\
        (!x y w a b c d e.
             x IN D /\ y IN D /\ w IN D /\
             E x p /\ E y p /\ E w p /\
             ejoin D E p leq y w a /\ emeet D E p leq x a b /\
             emeet D E p leq x y c /\ emeet D E p leq x w d /\
             ejoin D E p leq c d e
             ==> b = e) /\
        (!x. x IN D /\ E x p ==> (?y. ecompl D E p leq x y))`;;

(* -- complete Boolean algebra: every W-subset has a least upper bound - *)
let ecba = new_definition
  `ecba D (E:A->A->bool) p leq <=>
        ebalg D E p leq /\
        (!s. s IN D /\ esubset D E s p ==> (?u. elub D E p leq s u))`;;

(* -- compatibility, antichains, dense sets, filters, ultrafilters ----- *)
(* (ecompat/eantichain/edense: poset notions -- see the carrier note.)   *)
let ecompat = new_definition
  `ecompat D (E:A->A->bool) p leq x y <=>
        ?w. w IN D /\ E w p /\ erel D E leq w x /\ erel D E leq w y`;;

let eantichain = new_definition
  `eantichain D (E:A->A->bool) p leq a <=>
        a IN D /\ esubset D E a p /\
        (!x y. x IN D /\ y IN D /\ E x a /\ E y a /\ ~(x = y)
               ==> ~(ecompat D E p leq x y))`;;

let efilter = new_definition
  `efilter D (E:A->A->bool) p leq g <=>
        g IN D /\ esubset D E g p /\ (?x. x IN D /\ E x g) /\
        (!x y. x IN D /\ y IN D /\ E x g /\ E y p /\ erel D E leq x y
               ==> E y g) /\
        (!x y. x IN D /\ y IN D /\ E x g /\ E y g
               ==> (?z. z IN D /\ E z g /\
                        erel D E leq z x /\ erel D E leq z y))`;;

let eultra = new_definition
  `eultra D (E:A->A->bool) p leq g <=>
        efilter D E p leq g /\
        ~(?z. ebot D E p leq z /\ E z g) /\
        (!x. x IN D /\ E x p
             ==> E x g \/ (?y. ecompl D E p leq x y /\ E y g))`;;

(* ---- F1 basic lemmas: destructors, domain facts, uniqueness --------- *)

let EBALG_IMP_LATTICE = prove
 (`!D (E:A->A->bool) p leq. ebalg D E p leq ==> elattice D E p leq`,
  SIMP_TAC[ebalg]);;

let ELATTICE_IMP_PORDER = prove
 (`!D (E:A->A->bool) p leq. elattice D E p leq ==> eporder D E p leq`,
  SIMP_TAC[elattice]);;

let EBALG_IMP_PORDER = prove
 (`!D (E:A->A->bool) p leq. ebalg D E p leq ==> eporder D E p leq`,
  MESON_TAC[EBALG_IMP_LATTICE; ELATTICE_IMP_PORDER]);;

let ECBA_IMP_BALG = prove
 (`!D (E:A->A->bool) p leq. ecba D E p leq ==> ebalg D E p leq`,
  SIMP_TAC[ecba]);;

let ECBA_IMP_PORDER = prove
 (`!D (E:A->A->bool) p leq. ecba D E p leq ==> eporder D E p leq`,
  MESON_TAC[ECBA_IMP_BALG; EBALG_IMP_PORDER]);;

let EBOT_IN = prove
 (`!D (E:A->A->bool) p leq z. ebot D E p leq z ==> z IN D /\ E z p`,
  SIMP_TAC[ebot]);;

let ETOP_IN = prove
 (`!D (E:A->A->bool) p leq u. etop D E p leq u ==> u IN D /\ E u p`,
  SIMP_TAC[etop]);;

let EMEET_IN = prove
 (`!D (E:A->A->bool) p leq x y z. emeet D E p leq x y z ==> z IN D /\ E z p`,
  SIMP_TAC[emeet]);;

let EJOIN_IN = prove
 (`!D (E:A->A->bool) p leq x y z. ejoin D E p leq x y z ==> z IN D /\ E z p`,
  SIMP_TAC[ejoin]);;

let ELUB_IN = prove
 (`!D (E:A->A->bool) p leq s u. elub D E p leq s u ==> u IN D /\ E u p`,
  SIMP_TAC[elub; eubound]);;

let EGLB_IN = prove
 (`!D (E:A->A->bool) p leq s u. eglb D E p leq s u ==> u IN D /\ E u p`,
  SIMP_TAC[eglb; elbound]);;

let ECOMPL_IN = prove
 (`!D (E:A->A->bool) p leq x y. ecompl D E p leq x y ==> y IN D /\ E y p`,
  SIMP_TAC[ecompl]);;

let EBOT_UNIQUE = prove
 (`!D (E:A->A->bool) p leq z z'.
        eporder D E p leq /\ ebot D E p leq z /\ ebot D E p leq z'
        ==> z = z'`,
  REWRITE_TAC[eporder; ebot] THEN REPEAT STRIP_TAC THEN
  FIRST_X_ASSUM MATCH_MP_TAC THEN ASM_MESON_TAC[]);;

let ETOP_UNIQUE = prove
 (`!D (E:A->A->bool) p leq u u'.
        eporder D E p leq /\ etop D E p leq u /\ etop D E p leq u'
        ==> u = u'`,
  REWRITE_TAC[eporder; etop] THEN REPEAT STRIP_TAC THEN
  FIRST_X_ASSUM MATCH_MP_TAC THEN ASM_MESON_TAC[]);;

let ELUB_UNIQUE = prove
 (`!D (E:A->A->bool) p leq s u u'.
        eporder D E p leq /\ elub D E p leq s u /\ elub D E p leq s u'
        ==> u = u'`,
  REWRITE_TAC[elub; eubound; eporder] THEN REPEAT STRIP_TAC THEN
  FIRST_X_ASSUM MATCH_MP_TAC THEN ASM_MESON_TAC[]);;

let EGLB_UNIQUE = prove
 (`!D (E:A->A->bool) p leq s u u'.
        eporder D E p leq /\ eglb D E p leq s u /\ eglb D E p leq s u'
        ==> u = u'`,
  REWRITE_TAC[eglb; elbound; eporder] THEN REPEAT STRIP_TAC THEN
  FIRST_X_ASSUM MATCH_MP_TAC THEN ASM_MESON_TAC[]);;

let EMEET_UNIQUE = prove
 (`!D (E:A->A->bool) p leq x y z z'.
        eporder D E p leq /\
        emeet D E p leq x y z /\ emeet D E p leq x y z'
        ==> z = z'`,
  REWRITE_TAC[emeet; eporder] THEN REPEAT STRIP_TAC THEN
  FIRST_X_ASSUM MATCH_MP_TAC THEN ASM_MESON_TAC[]);;

let EJOIN_UNIQUE = prove
 (`!D (E:A->A->bool) p leq x y z z'.
        eporder D E p leq /\
        ejoin D E p leq x y z /\ ejoin D E p leq x y z'
        ==> z = z'`,
  REWRITE_TAC[ejoin; eporder] THEN REPEAT STRIP_TAC THEN
  FIRST_X_ASSUM MATCH_MP_TAC THEN ASM_MESON_TAC[]);;

let EBALG_BOT = prove
 (`!D (E:A->A->bool) p leq. ebalg D E p leq ==> ?z. ebot D E p leq z`,
  REWRITE_TAC[ebalg] THEN MESON_TAC[]);;

let EBALG_TOP = prove
 (`!D (E:A->A->bool) p leq. ebalg D E p leq ==> ?u. etop D E p leq u`,
  REWRITE_TAC[ebalg] THEN MESON_TAC[]);;

let EBALG_MEET = prove
 (`!D (E:A->A->bool) p leq x y.
        ebalg D E p leq /\ x IN D /\ y IN D /\ E x p /\ E y p
        ==> ?z. emeet D E p leq x y z`,
  REWRITE_TAC[ebalg; elattice] THEN MESON_TAC[]);;

let EBALG_JOIN = prove
 (`!D (E:A->A->bool) p leq x y.
        ebalg D E p leq /\ x IN D /\ y IN D /\ E x p /\ E y p
        ==> ?z. ejoin D E p leq x y z`,
  REWRITE_TAC[ebalg; elattice] THEN MESON_TAC[]);;

let EBALG_COMPL = prove
 (`!D (E:A->A->bool) p leq x.
        ebalg D E p leq /\ x IN D /\ E x p
        ==> ?y. ecompl D E p leq x y`,
  REWRITE_TAC[ebalg] THEN MESON_TAC[]);;

let ECBA_SUP = prove
 (`!D (E:A->A->bool) p leq s.
        ecba D E p leq /\ s IN D /\ esubset D E s p
        ==> ?u. elub D E p leq s u`,
  REWRITE_TAC[ecba] THEN MESON_TAC[]);;

(* ---- F1 order/lattice projection lemmas ----------------------------- *)

let EPORDER_REFL = prove
 (`!D (E:A->A->bool) p leq x.
        eporder D E p leq /\ x IN D /\ E x p ==> erel D E leq x x`,
  REWRITE_TAC[eporder] THEN MESON_TAC[]);;

let EPORDER_ANTISYM = prove
 (`!D (E:A->A->bool) p leq u v.
        eporder D E p leq /\ u IN D /\ v IN D /\ E u p /\ E v p /\
        erel D E leq u v /\ erel D E leq v u ==> u = v`,
  REWRITE_TAC[eporder] THEN MESON_TAC[]);;

let EPORDER_TRANS = prove
 (`!D (E:A->A->bool) p leq u v w.
        eporder D E p leq /\ u IN D /\ v IN D /\ w IN D /\
        E u p /\ E v p /\ E w p /\
        erel D E leq u v /\ erel D E leq v w ==> erel D E leq u w`,
  REWRITE_TAC[eporder] THEN MESON_TAC[]);;

let EPORDER_FIELD = prove
 (`!D (E:A->A->bool) p leq u v.
        eporder D E p leq /\ erel D E leq u v
        ==> u IN D /\ v IN D /\ E u p /\ E v p`,
  REWRITE_TAC[eporder] THEN MESON_TAC[]);;
let EREL_IN = prove
 (`!D (E:A->A->bool) r u v. erel D E r u v ==> u IN D /\ v IN D`,
  REPEAT GEN_TAC THEN REWRITE_TAC[erel] THEN STRIP_TAC THEN
  ASM_REWRITE_TAC[]);;

let EBOT_LE = prove
 (`!D (E:A->A->bool) p leq z x.
        ebot D E p leq z /\ x IN D /\ E x p ==> erel D E leq z x`,
  REWRITE_TAC[ebot] THEN MESON_TAC[]);;

let ETOP_GE = prove
 (`!D (E:A->A->bool) p leq u x.
        etop D E p leq u /\ x IN D /\ E x p ==> erel D E leq x u`,
  REWRITE_TAC[etop] THEN MESON_TAC[]);;

let EMEET_LE = prove
 (`!D (E:A->A->bool) p leq x y z.
        emeet D E p leq x y z ==> erel D E leq z x /\ erel D E leq z y`,
  SIMP_TAC[emeet]);;

let EMEET_GREATEST = prove
 (`!D (E:A->A->bool) p leq x y z w.
        emeet D E p leq x y z /\ w IN D /\ E w p /\
        erel D E leq w x /\ erel D E leq w y ==> erel D E leq w z`,
  REWRITE_TAC[emeet] THEN MESON_TAC[]);;

let EJOIN_GE = prove
 (`!D (E:A->A->bool) p leq x y z.
        ejoin D E p leq x y z ==> erel D E leq x z /\ erel D E leq y z`,
  SIMP_TAC[ejoin]);;

let EJOIN_LEAST = prove
 (`!D (E:A->A->bool) p leq x y z w.
        ejoin D E p leq x y z /\ w IN D /\ E w p /\
        erel D E leq x w /\ erel D E leq y w ==> erel D E leq z w`,
  REWRITE_TAC[ejoin] THEN MESON_TAC[]);;

let ELUB_UB = prove
 (`!D (E:A->A->bool) p leq s u x.
        elub D E p leq s u /\ x IN D /\ E x s ==> erel D E leq x u`,
  REWRITE_TAC[elub; eubound] THEN MESON_TAC[]);;

let ELUB_LEAST = prove
 (`!D (E:A->A->bool) p leq s u w.
        elub D E p leq s u /\ eubound D E p leq s w ==> erel D E leq u w`,
  REWRITE_TAC[elub] THEN MESON_TAC[]);;

let EGLB_LB = prove
 (`!D (E:A->A->bool) p leq s u x.
        eglb D E p leq s u /\ x IN D /\ E x s ==> erel D E leq u x`,
  REWRITE_TAC[eglb; elbound] THEN MESON_TAC[]);;

let EGLB_GREATEST = prove
 (`!D (E:A->A->bool) p leq s u w.
        eglb D E p leq s u /\ elbound D E p leq s w ==> erel D E leq w u`,
  REWRITE_TAC[eglb] THEN MESON_TAC[]);;

(* ========================================================================= *)
(* F3a: the Boolean-name hierarchy  V^B_alpha.                               *)
(* Structural twin of the L hierarchy (elstage):                             *)
(* run the SAME ordinal-recursion engine (erec) with a name-step that carves *)
(* the PARTIAL functions dom SUBSET w, range SUBSET B out of P(w x B) by     *)
(* single-valuedness -- the cumulative "sets of pairs (name, b in B)".       *)
(*                                                                           *)
(*   ebnmem/ebnfuns  <->  edefmem/edef        (the step's carving operator)  *)
(*   bnmem_form      <->  defmem_form         (its object-formula)           *)
(*   bnstep/bname_step_form <-> elstep/lstep_form                            *)
(*   ebnstage        <->  elstage  (= erec bname_step_form)                  *)
(*                                                                           *)
(* B is a FIXED parameter threaded through valuation slot 2 (FV of the step  *)
(* SUBSET {0,1,2}; erec keeps the slots it does not build, so v 2 = B holds  *)
(* throughout the recursion).                                                *)
(* ------------------------------------------------------------------------- *)

(* ---- F3a.1: ebnmem / ebnfuns (partial functions w -> B) ---------------- *)

let ebnmem = new_definition
  `ebnmem D (E:A->A->bool) B w f <=>
        eisfun D E f /\
        ?cr. cr IN D /\ ecross D E w B cr /\ esubset D E f cr`;;

let ebnfuns = new_definition
  `ebnfuns D (E:A->A->bool) B w y <=>
        y IN D /\ !f. f IN D ==> (E f y <=> ebnmem D E B w f)`;;

let EBNFUNS_IN = prove
 (`!D (E:A->A->bool) B w y. ebnfuns D E B w y ==> y IN D`,
  SIMP_TAC[ebnfuns]);;

let EBNFUNS_UNIQUE = prove
 (`!D (E:A->A->bool) B w y y'.
        model D E ZF_AX /\ ebnfuns D E B w y /\ ebnfuns D E B w y'
        ==> y = y'`,
  REWRITE_TAC[ebnfuns] THEN REPEAT STRIP_TAC THEN
  FIRST_ASSUM(MATCH_MP_TAC o MATCH_MP ZF_EXTENSIONALITY) THEN
  ASM_SIMP_TAC[]);;

let EBNFUNS_EXISTS = prove
 (`!D (E:A->A->bool) B w.
        model D E ZF_AX /\ B IN D /\ w IN D ==> ?y. ebnfuns D E B w y`,
  REPEAT STRIP_TAC THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `w:A`; `B:A`] ECROSS_EXISTS) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `cr:A`) THEN
  SUBGOAL_THEN `(cr:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[ecross]; ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `cr:A`] EPOW_EXISTS) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `pc:A`) THEN
  SUBGOAL_THEN `(pc:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[EPOW_IN]; ALL_TAC] THEN
  FIRST_ASSUM(X_CHOOSE_TAC `v0:num->A` o MATCH_MP VALUATION_EXISTS o
              MATCH_MP MODEL_NONEMPTY) THEN
  FIRST_ASSUM(MP_TAC o SPECL
    [`fun_form 0`; `0`; `v0:num->A`; `pc:A`] o
    MATCH_MP ZF_SEPARATION) THEN
  ASM_REWRITE_TAC[] THEN
  MATCH_MP_TAC MONO_EXISTS THEN X_GEN_TAC `y:A` THEN STRIP_TAC THEN
  ASM_REWRITE_TAC[ebnfuns] THEN X_GEN_TAC `f:A` THEN DISCH_TAC THEN
  SUBGOAL_THEN `valuation D ((0 |-> (f:A)) v0)` ASSUME_TAC THENL
   [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
  ASM_SIMP_TAC[] THEN
  SUBGOAL_THEN
   `holds D E ((0 |-> (f:A)) v0) (fun_form 0) <=> eisfun D E f`
  (fun th -> REWRITE_TAC[th]) THENL
   [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `(0 |-> (f:A)) v0`; `0`]
          HOLDS_FUN_FORM) THEN
    ASM_REWRITE_TAC[] THEN DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    REWRITE_TAC[VALMOD];
    ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) f pc <=> esubset D E f cr`
  (fun th -> REWRITE_TAC[th]) THENL
   [ASM_MESON_TAC[epow]; ALL_TAC] THEN
  REWRITE_TAC[ebnmem] THEN EQ_TAC THEN STRIP_TAC THEN ASM_REWRITE_TAC[] THENL
   [EXISTS_TAC `cr:A` THEN ASM_REWRITE_TAC[];
    SUBGOAL_THEN `cr':A = cr` (fun th -> ASM_MESON_TAC[th]) THEN
    ASM_MESON_TAC[ECROSS_UNIQUE]]);;

let bnmem_form = new_definition
  `bnmem_form i j k =
     fun_form i &&
     ?? (MAX (MAX i j) k + 6)
        (cross_form j k (MAX (MAX i j) k + 6) &&
         subset_form i (MAX (MAX i j) k + 6))`;;

let FV_BNMEM_FORM = prove
 (`!i j k. FV(bnmem_form i j k) = {i,j,k}`,
  REPEAT GEN_TAC THEN
  REWRITE_TAC[bnmem_form; FV; FV_CLAUSES; FV_FUN_FORM; FV_CROSS_FORM;
              FV_SUBSET_FORM] THEN
  REWRITE_TAC[EXTENSION; IN_DELETE; IN_UNION; IN_INSERT; NOT_IN_EMPTY] THEN
  ARITH_TAC);;

let HOLDS_BNMEM_FORM = prove
 (`!D (E:A->A->bool) v i j k.
        valuation D v
        ==> (holds D E v (bnmem_form i j k) <=>
             ebnmem D E (v k) (v j) (v i))`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `!x. (v:num->A) x IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[valuation]; ALL_TAC] THEN
  REWRITE_TAC[bnmem_form; HOLDS_AND; HOLDS_EX; ebnmem] THEN
  ASM_SIMP_TAC[HOLDS_FUN_FORM] THEN
  MATCH_MP_TAC(TAUT `(b <=> b') ==> ((a /\ b) <=> (a /\ b'))`) THEN
  MATCH_MP_TAC(MESON[]
    `(!a:A. a IN D ==> (P a <=> Q a))
     ==> ((?a. a IN D /\ P a) <=> (?a. a IN D /\ Q a))`) THEN
  X_GEN_TAC `a:A` THEN DISCH_TAC THEN
  SUBGOAL_THEN
   `valuation D (((MAX (MAX i j) k + 6) |-> (a:A)) v)`
  ASSUME_TAC THENL [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
  ASM_SIMP_TAC[HOLDS_CROSS_FORM; HOLDS_SUBSET_FORM] THEN
  SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER; ARITH_RULE
    `~(MAX (MAX i j) k + 6 = i) /\ ~(MAX (MAX i j) k + 6 = j) /\
     ~(MAX (MAX i j) k + 6 = k)`]);;

let bnstep = new_definition
  `bnstep D (E:A->A->bool) B g y <=>
        ?w. w IN D /\ eranu D E g w /\ ebnfuns D E B w y`;;

let BNSTEP_FUN = prove
 (`!D (E:A->A->bool) B g y y'.
        model D E ZF_AX /\ bnstep D E B g y /\ bnstep D E B g y'
        ==> y = y'`,
  REWRITE_TAC[bnstep] THEN REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `w:A = w'` SUBST_ALL_TAC THENL
   [ASM_MESON_TAC[ERANU_UNIQUE]; ALL_TAC] THEN
  ASM_MESON_TAC[EBNFUNS_UNIQUE]);;

let BNSTEP_TOTAL = prove
 (`!D (E:A->A->bool) B g.
      model D E ZF_AX /\ B IN D /\ g IN D ==> ?y. bnstep D E B g y`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[bnstep] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `g:A`] ERANU_EXISTS) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `w:A`) THEN
  SUBGOAL_THEN `(w:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[eranu]; ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `B:A`; `w:A`] EBNFUNS_EXISTS) THEN
  ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[]);;

let bname_step_form = new_definition
  `bname_step_form =
     ?? 3 ((!! 4 (4 %% 3 <-> ranmem_form 4 0)) &&
           (!! 4 (4 %% 1 <-> bnmem_form 4 3 2)))`;;

let FV_BNAME_STEP_FORM_SUB = prove
 (`FV bname_step_form SUBSET {0,1,2}`,
  REWRITE_TAC[bname_step_form; FV; FV_CLAUSES; FV_RANMEM_FORM;
              FV_BNMEM_FORM] THEN
  REWRITE_TAC[SUBSET; IN_DELETE; IN_UNION; IN_INSERT; NOT_IN_EMPTY] THEN
  ARITH_TAC);;

let FVLT_BNAME_STEP_FORM = prove
 (`!m. m IN FV bname_step_form ==> m < 3`,
  GEN_TAC THEN DISCH_TAC THEN
  MP_TAC(REWRITE_RULE[SUBSET] FV_BNAME_STEP_FORM_SUB) THEN
  DISCH_THEN(MP_TAC o SPEC `m:num`) THEN
  ASM_REWRITE_TAC[IN_INSERT; NOT_IN_EMPTY] THEN ARITH_TAC);;

let HOLDS_BNAME_STEP_FORM = prove
 (`!D (E:A->A->bool) v g y.
      model D E ZF_AX /\ valuation D v /\ g IN D /\ y IN D
      ==> (holds D E ((1 |-> y) ((0 |-> g) v)) bname_step_form <=>
           bnstep D E (v 2) g y)`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `!x. (v:num->A) x IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[valuation]; ALL_TAC] THEN
  REWRITE_TAC[bname_step_form; holds; HOLDS_IFF; HOLDS_EX; HOLDS_AND;
              bnstep] THEN
  SUBGOAL_THEN
   `!w u:A. w IN D /\ u IN D
      ==> (holds D E
            ((4 |-> u) ((3 |-> w) ((1 |-> y) ((0 |-> g) v))))
            (ranmem_form 4 0) <=>
           eranmem D E u g) /\
          (holds D E
            ((4 |-> u) ((3 |-> w) ((1 |-> y) ((0 |-> g) v))))
            (bnmem_form 4 3 2) <=>
           ebnmem D E (v 2) w u)`
  (LABEL_TAC "piles") THENL
   [REPEAT GEN_TAC THEN DISCH_TAC THEN
    SUBGOAL_THEN
     `valuation D
       ((4 |-> (u:A)) ((3 |-> w) ((1 |-> y) ((0 |-> g) v))))`
    ASSUME_TAC THENL [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
    CONJ_TAC THENL
     [ASM_SIMP_TAC[HOLDS_RANMEM_FORM] THEN
      REWRITE_TAC[VALMOD; ARITH_EQ];
      ASM_SIMP_TAC[HOLDS_BNMEM_FORM] THEN
      REWRITE_TAC[VALMOD; ARITH_EQ]];
    ALL_TAC] THEN
  REWRITE_TAC[VALMOD; ARITH_EQ] THEN
  MATCH_MP_TAC(MESON[]
    `(!w:A. w IN D ==> (P w <=> Q w))
     ==> ((?w. w IN D /\ P w) <=> (?w. w IN D /\ Q w))`) THEN
  X_GEN_TAC `w:A` THEN DISCH_TAC THEN
  SUBGOAL_THEN
   `(eranu D (E:A->A->bool) g w <=>
     !u. u IN D ==> (E u w <=> eranmem D E u g)) /\
    (ebnfuns D (E:A->A->bool) (v 2) w y <=>
     !u. u IN D ==> (E u y <=> ebnmem D E (v 2) w u))`
  (fun th -> REWRITE_TAC[th]) THENL
   [ASM_REWRITE_TAC[eranu; ebnfuns]; ALL_TAC] THEN
  MATCH_MP_TAC(TAUT
    `(a <=> a') /\ (b <=> b') ==> ((a /\ b) <=> (a' /\ b'))`) THEN
  CONJ_TAC THEN
  (MATCH_MP_TAC(MESON[]
    `(!u:A. u IN D ==> (P u <=> Q u))
     ==> ((!u. u IN D ==> P u) <=> (!u. u IN D ==> Q u))`) THEN
   X_GEN_TAC `u:A` THEN DISCH_TAC THEN
   USE_THEN "piles" (fun th -> MP_TAC(SPECL [`w:A`; `u:A`] th)) THEN
   ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
   DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
   REWRITE_TAC[VALMOD; ARITH_EQ]));;

let BNSTEP_QFUN = prove
 (`!D (E:A->A->bool) v.
        model D E ZF_AX /\ valuation D v
        ==> !r w w'. r IN D /\ w IN D /\ w' IN D /\
                     holds D E ((1 |-> w) ((0 |-> r) v)) bname_step_form /\
                     holds D E ((1 |-> w') ((0 |-> r) v)) bname_step_form
                     ==> w = w'`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN REPEAT GEN_TAC THEN STRIP_TAC THEN
  MATCH_MP_TAC BNSTEP_FUN THEN
  MAP_EVERY EXISTS_TAC
    [`D:A->bool`; `E:A->A->bool`; `(v:num->A) 2`; `r:A`] THEN
  ASM_MESON_TAC[HOLDS_BNAME_STEP_FORM]);;

let BNSTEP_QTOTAL = prove
 (`!D (E:A->A->bool) v.
        model D E ZF_AX /\ valuation D v
        ==> !x. x IN D
                ==> ?y. y IN D /\
                        holds D E ((1 |-> y) ((0 |-> x) v)) bname_step_form`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `(v:num->A) 2 IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[valuation]; ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `(v:num->A) 2`; `x:A`]
        BNSTEP_TOTAL) THEN
  ASM_REWRITE_TAC[] THEN
  MATCH_MP_TAC MONO_EXISTS THEN X_GEN_TAC `y:A` THEN DISCH_TAC THEN
  SUBGOAL_THEN `(y:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[bnstep; EBNFUNS_IN]; ALL_TAC] THEN
  ASM_MESON_TAC[HOLDS_BNAME_STEP_FORM]);;

(* Twin of elstage; erec engine reused verbatim, only the step differs.      *)
(* B is a FIXED parameter threaded through valuation slot 2 (FV              *)
(* bname_step_form SUBSET {0,1,2}; erec keeps slots it does not build, so v  *)
(* 2 = B persists).                                                          *)

let ebnstage = new_definition
  `ebnstage D (E:A->A->bool) B a y <=>
        ?v. valuation D v /\ v 2 = B /\ erec D E bname_step_form v a y`;;

let EBNSTAGE_EREC = prove
 (`!D (E:A->A->bool) B a y v.
        model D E ZF_AX /\ valuation D v /\ v 2 = B
        ==> (ebnstage D E B a y <=> erec D E bname_step_form v a y)`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[ebnstage] THEN EQ_TAC THENL
   [DISCH_THEN(X_CHOOSE_THEN `v':num->A` STRIP_ASSUME_TAC) THEN
    SUBGOAL_THEN
     `erec D (E:A->A->bool) bname_step_form v' a y <=>
      erec D E bname_step_form v a y`
    (fun th -> ASM_MESON_TAC[th]) THEN
    MATCH_MP_TAC EREC_VALUATION THEN
    X_GEN_TAC `m:num` THEN STRIP_TAC THEN
    MP_TAC(SPEC `m:num` FVLT_BNAME_STEP_FORM) THEN
    ASM_REWRITE_TAC[] THEN DISCH_TAC THEN
    SUBGOAL_THEN `m = 2` ASSUME_TAC THENL
     [ASM_ARITH_TAC; ASM_MESON_TAC[]];
    ASM_MESON_TAC[]]);;

let EBNSTAGE_UNIQUE = prove
 (`!D (E:A->A->bool) B a y y'.
        model D E ZF_AX /\ B IN D /\ a IN D /\ y IN D /\ y' IN D /\
        ebnstage D E B a y /\ ebnstage D E B a y'
        ==> y = y'`,
  REPEAT STRIP_TAC THEN
  FIRST_ASSUM(X_CHOOSE_TAC `v0:num->A` o MATCH_MP VALUATION_EXISTS o
              MATCH_MP MODEL_NONEMPTY) THEN
  ABBREV_TAC `v = (2 |-> (B:A)) v0` THEN
  SUBGOAL_THEN `valuation D (v:num->A) /\ (v:num->A) 2 = B`
  STRIP_ASSUME_TAC THENL
   [EXPAND_TAC "v" THEN ASM_SIMP_TAC[VALUATION_VALMOD; VALMOD]; ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `bname_step_form`; `v:num->A`;
                `a:A`; `y:A`; `y':A`] EREC_UNIQUE) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN MATCH_MP_TAC THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `v:num->A`] BNSTEP_QFUN) THEN
  ASM_REWRITE_TAC[] THEN DISCH_TAC THEN ASM_REWRITE_TAC[] THEN
  ASM_MESON_TAC[EBNSTAGE_EREC]);;

let EBNSTAGE_EXISTS = prove
 (`!D (E:A->A->bool) B a.
        model D E ZF_AX /\ B IN D /\ eordinal D E a
        ==> ?y. y IN D /\ ebnstage D E B a y`,
  REPEAT STRIP_TAC THEN
  FIRST_ASSUM(X_CHOOSE_TAC `v0:num->A` o MATCH_MP VALUATION_EXISTS o
              MATCH_MP MODEL_NONEMPTY) THEN
  ABBREV_TAC `v = (2 |-> (B:A)) v0` THEN
  SUBGOAL_THEN `valuation D (v:num->A) /\ (v:num->A) 2 = B`
  STRIP_ASSUME_TAC THENL
   [EXPAND_TAC "v" THEN ASM_SIMP_TAC[VALUATION_VALMOD; VALMOD]; ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `bname_step_form`; `v:num->A`;
                `a:A`] EREC_EXISTS) THEN
  ASM_REWRITE_TAC[] THEN ANTS_TAC THENL
   [ASM_MESON_TAC[BNSTEP_QFUN; BNSTEP_QTOTAL]; ALL_TAC] THEN
  MATCH_MP_TAC MONO_EXISTS THEN X_GEN_TAC `y:A` THEN STRIP_TAC THEN
  ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[EBNSTAGE_EREC]);;

let EBNSTAGE_CHAR = prove
 (`!D (E:A->A->bool) B a y.
      model D E ZF_AX /\ B IN D /\ eordinal D E a /\ y IN D /\
      ebnstage D E B a y
      ==> ?w. w IN D /\
              (!u. u IN D
                   ==> (E u w <=>
                        ?b z. b IN D /\ z IN D /\ E b a /\
                              ebnstage D E B b z /\ E u z)) /\
              ebnfuns D E B w y`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `(a:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[EORDINAL_IN]; ALL_TAC] THEN
  FIRST_ASSUM(X_CHOOSE_TAC `v0:num->A` o MATCH_MP VALUATION_EXISTS o
              MATCH_MP MODEL_NONEMPTY) THEN
  ABBREV_TAC `v = (2 |-> (B:A)) v0` THEN
  SUBGOAL_THEN `valuation D (v:num->A) /\ (v:num->A) 2 = B`
  STRIP_ASSUME_TAC THENL
   [EXPAND_TAC "v" THEN ASM_SIMP_TAC[VALUATION_VALMOD; VALMOD]; ALL_TAC] THEN
  SUBGOAL_THEN `?r:A. erecres D (E:A->A->bool) bname_step_form v a r`
  STRIP_ASSUME_TAC THENL
   [MATCH_MP_TAC ERECRES_EXISTS THEN ASM_REWRITE_TAC[] THEN
    ASM_MESON_TAC[BNSTEP_QFUN; BNSTEP_QTOTAL];
    ALL_TAC] THEN
  SUBGOAL_THEN `(r:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[erecres]; ALL_TAC] THEN
  SUBGOAL_THEN `bnstep D (E:A->A->bool) B r y` MP_TAC THENL
   [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `v:num->A`; `r:A`; `y:A`]
          HOLDS_BNAME_STEP_FORM) THEN
    ASM_REWRITE_TAC[] THEN DISCH_THEN(SUBST1_TAC o SYM) THEN
    MATCH_MP_TAC EREC_EQUATION THEN
    EXISTS_TAC `a:A` THEN ASM_REWRITE_TAC[] THEN
    ASM_MESON_TAC[BNSTEP_QFUN; EBNSTAGE_EREC];
    ALL_TAC] THEN
  REWRITE_TAC[bnstep] THEN
  MATCH_MP_TAC MONO_EXISTS THEN X_GEN_TAC `w:A` THEN STRIP_TAC THEN
  ASM_REWRITE_TAC[] THEN
  SUBGOAL_THEN
   `!b z:A. erec D (E:A->A->bool) bname_step_form v b z <=>
            ebnstage D E B b z`
  (LABEL_TAC "conv") THENL
   [ASM_MESON_TAC[EBNSTAGE_EREC]; ALL_TAC] THEN
  X_GEN_TAC `u:A` THEN DISCH_TAC THEN
  SUBGOAL_THEN `(E:A->A->bool) u w <=> eranmem D E u r`
  (fun th -> REWRITE_TAC[th]) THENL
   [ASM_MESON_TAC[eranu]; ALL_TAC] THEN
  REWRITE_TAC[eranmem] THEN EQ_TAC THENL
   [DISCH_THEN(X_CHOOSE_THEN `vl:A` (X_CHOOSE_THEN `pr:A`
      (X_CHOOSE_THEN `ord:A`
        (fun th -> MAP_EVERY ASSUME_TAC (CONJUNCTS th))))) THEN
    SUBGOAL_THEN
     `?b z:A. b IN D /\ z IN D /\ E b a /\
              erec D (E:A->A->bool) bname_step_form v b z /\
              eopair D E b z pr`
    STRIP_ASSUME_TAC THENL
     [FIRST_ASSUM(MP_TAC o SPEC `pr:A` o CONJUNCT2 o
        GEN_REWRITE_RULE I [erecres]) THEN
      ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    SUBGOAL_THEN `ord:A = b /\ vl:A = z` STRIP_ASSUME_TAC THENL
     [ASM_MESON_TAC[EOPAIR_INJ]; ALL_TAC] THEN
    MAP_EVERY EXISTS_TAC [`b:A`; `z:A`] THEN
    ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[];
    DISCH_THEN(X_CHOOSE_THEN `b:A` (X_CHOOSE_THEN `z:A`
      (fun th -> MAP_EVERY ASSUME_TAC (CONJUNCTS th)))) THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `b:A`; `z:A`]
          EOPAIR_EXISTS) THEN
    ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `pr:A`) THEN
    SUBGOAL_THEN `(pr:A) IN D` ASSUME_TAC THENL
     [ASM_MESON_TAC[EOPAIR_IN]; ALL_TAC] THEN
    MAP_EVERY EXISTS_TAC [`z:A`; `pr:A`; `b:A`] THEN
    ASM_REWRITE_TAC[] THEN
    FIRST_ASSUM(MP_TAC o SPEC `pr:A` o CONJUNCT2 o
      GEN_REWRITE_RULE I [erecres]) THEN
    ASM_REWRITE_TAC[] THEN DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    ASM_MESON_TAC[]]);;

(* ========================================================================= *)
(* F3b: the B-name CLASS and its                                             *)
(* cumulativity / directedness.                                              *)
(*                                                                           *)
(* `bname D E B u` = "u is a Boolean-valued name over B" = u lies in some    *)
(* stage V^B_a of the F3a hierarchy (ebnstage).  Structural twin of          *)
(* `elmem` (the L-membership class), with ebnstage in place of               *)
(* elstage.  IMPORTANT DISANALOGY: a member of a B-name is a PAIR (name, b)  *)
(* with b IN B, NOT itself a name -- so the stages are NOT transitive and    *)
(* there is NO ELMEM_MEMBER-style transitivity lemma (deliberately absent).  *)
(*                                                                           *)
(* Cumulativity is instead proved via the PARTIAL-FUNCTION design of F3a: a  *)
(* name in V^B_b is a partial function dom SUBSET w_b (w_b = UNION of the    *)
(* stages below b); since w_b SUBSET w_a whenever b < a (ordinal             *)
(* transitivity), the same partial function is dom SUBSET w_a too, hence     *)
(* also a member of V^B_a.  EBNSTAGE_MONO makes this precise; BNAME_DIRECTED *)
(* (twin of ELMEM_DIRECTED) is the consequence needed by F5.                 *)
(* ========================================================================= *)

let bname = new_definition
  `bname D (E:A->A->bool) B u <=>
        ?a y. a IN D /\ y IN D /\ eordinal D E a /\
              ebnstage D E B a y /\ E u y`;;

let BNAME_STAGE = prove
 (`!D (E:A->A->bool) B a y u.
        a IN D /\ y IN D /\ eordinal D E a /\ ebnstage D E B a y /\ E u y
        ==> bname D E B u`,
  REWRITE_TAC[bname] THEN MESON_TAC[]);;

(* cross w B is monotone in its first argument: w SUBSET w' => (w x B)       *)
(* SUBSET (w' x B).  (The characterization is built into ecross's            *)
(* definition.)                                                              *)

let ECROSS_MONO_SUBSET = prove
 (`!D (E:A->A->bool) wb wa B cr cr'.
        model D E ZF_AX /\ esubset D E wb wa /\
        ecross D E wb B cr /\ ecross D E wa B cr'
        ==> esubset D E cr cr'`,
  REWRITE_TAC[ecross; esubset] THEN MESON_TAC[]);;

(* Cumulativity: every member of the earlier stage V^B_b (b < a) is a member *)
(* of the later stage V^B_a.  Proof: the stage-union w_b SUBSET w_a (ordinal *)
(* transitivity of a), so cross w_b B SUBSET cross w_a B, so a partial       *)
(* function u SUBSET cross w_b B is also SUBSET cross w_a B, i.e. ebnmem at  *)
(* w_a.                                                                      *)

let EBNSTAGE_MONO = prove
 (`!D (E:A->A->bool) B a b ya yb u.
        model D E ZF_AX /\ B IN D /\ eordinal D E a /\ E b a /\ b IN D /\
        ya IN D /\ yb IN D /\ ebnstage D E B a ya /\ ebnstage D E B b yb /\
        u IN D /\ E u yb
        ==> E u ya`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `eordinal D (E:A->A->bool) b` ASSUME_TAC THENL
   [ASM_MESON_TAC[EORDINAL_MEMBER]; ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `B:A`; `a:A`; `ya:A`]
        EBNSTAGE_CHAR) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `wa:A` (CONJUNCTS_THEN2 ASSUME_TAC
    (CONJUNCTS_THEN2 (LABEL_TAC "wa") ASSUME_TAC))) THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `B:A`; `b:A`; `yb:A`]
        EBNSTAGE_CHAR) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `wb:A` (CONJUNCTS_THEN2 ASSUME_TAC
    (CONJUNCTS_THEN2 (LABEL_TAC "wb") ASSUME_TAC))) THEN
  (* stage-unions: w_b SUBSET w_a, since b < a and a is an ordinal.  Proved  *)
  (* directly from the two stage-characterizations + EORDINAL_TRANS_MEM.     *)
  (* (An explicit SPEC/ASM_REWRITE/DISCH chain here collapses the            *)
  (* existential antecedent to nothing -- DISCH_TAC then fails; MESON is     *)
  (* robust.)                                                                *)
  SUBGOAL_THEN `esubset D (E:A->A->bool) wb wa` ASSUME_TAC THENL
   [REWRITE_TAC[esubset] THEN ASM_MESON_TAC[EORDINAL_TRANS_MEM];
    ALL_TAC] THEN
  SUBGOAL_THEN `ebnmem D (E:A->A->bool) B wb u` MP_TAC THENL
   [UNDISCH_TAC `ebnfuns D (E:A->A->bool) B wb yb` THEN
    REWRITE_TAC[ebnfuns] THEN STRIP_TAC THEN ASM_MESON_TAC[];
    ALL_TAC] THEN
  REWRITE_TAC[ebnmem] THEN
  DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC (X_CHOOSE_THEN `cr:A`
    (fun th -> MAP_EVERY ASSUME_TAC (CONJUNCTS th)))) THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `wa:A`; `B:A`] ECROSS_EXISTS) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `cr':A`) THEN
  SUBGOAL_THEN `(cr':A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[ecross]; ALL_TAC] THEN
  SUBGOAL_THEN `esubset D (E:A->A->bool) cr cr'` ASSUME_TAC THENL
   [MATCH_MP_TAC ECROSS_MONO_SUBSET THEN
    MAP_EVERY EXISTS_TAC [`wb:A`; `wa:A`; `B:A`] THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  UNDISCH_TAC `ebnfuns D (E:A->A->bool) B wa ya` THEN
  REWRITE_TAC[ebnfuns] THEN
  DISCH_THEN(MP_TAC o SPEC `u:A` o CONJUNCT2) THEN ASM_REWRITE_TAC[] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  REWRITE_TAC[ebnmem] THEN ASM_REWRITE_TAC[] THEN
  EXISTS_TAC `cr':A` THEN ASM_REWRITE_TAC[] THEN
  ASM_MESON_TAC[esubset]);;

(* Directedness (twin of ELMEM_DIRECTED): any two B-names lie in a           *)
(* common stage.  Trichotomy on their stage-indices + EBNSTAGE_MONO to push  *)
(* the lower into the higher (equal case: EBNSTAGE_UNIQUE).                  *)

let BNAME_DIRECTED = prove
 (`!D (E:A->A->bool) B u u'.
        model D E ZF_AX /\ B IN D /\ u IN D /\ u' IN D /\
        bname D E B u /\ bname D E B u'
        ==> ?a y. a IN D /\ y IN D /\ eordinal D E a /\
                  ebnstage D E B a y /\ E u y /\ E u' y`,
  REPEAT GEN_TAC THEN REWRITE_TAC[bname] THEN
  DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC (CONJUNCTS_THEN2 ASSUME_TAC
    (CONJUNCTS_THEN2 ASSUME_TAC (CONJUNCTS_THEN2 ASSUME_TAC (CONJUNCTS_THEN2
      (X_CHOOSE_THEN `a:A` (X_CHOOSE_THEN `y:A`
        (fun th -> MAP_EVERY ASSUME_TAC (CONJUNCTS th))))
      (X_CHOOSE_THEN `a':A` (X_CHOOSE_THEN `y':A`
        (fun th -> MAP_EVERY ASSUME_TAC (CONJUNCTS th))))))))) THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `a:A`; `a':A`]
        EORDINAL_TRICHOTOMY) THEN
  ASM_REWRITE_TAC[] THEN STRIP_TAC THENL
   [MAP_EVERY EXISTS_TAC [`a':A`; `y':A`] THEN ASM_REWRITE_TAC[] THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `B:A`; `a':A`; `a:A`;
                  `y':A`; `y:A`; `u:A`] EBNSTAGE_MONO) THEN
    ASM_REWRITE_TAC[] THEN DISCH_THEN MATCH_MP_TAC THEN
    ASM_MESON_TAC[EORDINAL_IN];
    MAP_EVERY EXISTS_TAC [`a':A`; `y':A`] THEN ASM_REWRITE_TAC[] THEN
    SUBGOAL_THEN `y:A = y'` (fun th -> ASM_MESON_TAC[th]) THEN
    ASM_MESON_TAC[EBNSTAGE_UNIQUE; EORDINAL_IN];
    MAP_EVERY EXISTS_TAC [`a:A`; `y:A`] THEN ASM_REWRITE_TAC[] THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `B:A`; `a:A`; `a':A`;
                  `y:A`; `y':A`; `u':A`] EBNSTAGE_MONO) THEN
    ASM_REWRITE_TAC[] THEN DISCH_THEN MATCH_MP_TAC THEN
    ASM_MESON_TAC[EORDINAL_IN]]);;

(* ======================================================================== *)
(* F3c: CHECK-NAMES.                                                        *)
(*                                                                           *)
(* For x a set, the canonical (check) name x^ = { (y^, 1_B) : y IN x } is    *)
(* the B-name whose Boolean value reproduces x in every quotient.  It is     *)
(* built by transfinite recursion on rank, stratified by the erec engine:    *)
(* the stage value at ordinal a is the graph cd_a = { (x, x^) : x SUBSET     *)
(* w_a }, where gacc = UNION of the check-graphs below a (eranu) and w_a =   *)
(* dom(gacc) (edomain) is the set of already-checked sets.  x^ itself is     *)
(* the tagged image { (gacc(y), 1_B) : y IN x } (chkimg).  onebee (=1_B) is  *)
(* a FIXED parameter threaded through valuation slot 2, exactly as B in the  *)
(* F3a name hierarchy (ebnstage).  Structural mirror of the Mostowski        *)
(* collapse tower ecolltower/ecollstep.                                      *)
(* ======================================================================== *)
(* F3c: chkimg_form -- inner image with 1_B tagging.
   E z (v iimg) <=> ?y vy. E y (v ix) /\ eapply gacc y vy /\ eopair vy onebee z
   Mirror of imgset_form with extra existential vy=77 and opair tagging. *)

let chkimg_form = new_definition
  `chkimg_form iimg ix igacc ione =
     !! 75 ((75 %% iimg) <->
        ?? 76 (?? 77
               ((76 %% ix) && apply_form igacc 76 77 &&
                opair_form 77 ione 75)))`;;

let HOLDS_CHKIMG = prove
 (`!D (E:A->A->bool) v iimg ix igacc ione.
     valuation D v /\
     ~(iimg=75)/\ ~(iimg=76)/\ ~(iimg=77)/\
     ~(ix=75)/\ ~(ix=76)/\ ~(ix=77)/\
     ~(igacc=75)/\ ~(igacc=76)/\ ~(igacc=77)/\
     ~(ione=75)/\ ~(ione=76)/\ ~(ione=77)
     ==> (holds D E v (chkimg_form iimg ix igacc ione) <=>
          !z. z IN D
              ==> (E z (v iimg) <=>
                   ?y. y IN D /\ ?vy. vy IN D /\
                       E y (v ix) /\ eapply D E (v igacc) y vy /\
                       eopair D E vy (v ione) z))`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `!x. (v:num->A) x IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[valuation]; ALL_TAC] THEN
  REWRITE_TAC[chkimg_form; holds; HOLDS_EX; HOLDS_AND; HOLDS_IFF] THEN
  ASM_REWRITE_TAC[VALMOD; ARITH_EQ] THEN
  SUBGOAL_THEN
   `!z y vy:A. z IN D /\ y IN D /\ vy IN D
     ==> (holds D E ((77 |-> vy)((76 |-> y)((75 |-> z) v)))
            (apply_form igacc 76 77) <=>
          eapply D E (v igacc) y vy) /\
         (holds D E ((77 |-> vy)((76 |-> y)((75 |-> z) v)))
            (opair_form 77 ione 75) <=>
          eopair D E vy (v ione) z)`
  (LABEL_TAC "piles") THENL
   [REPEAT GEN_TAC THEN STRIP_TAC THEN
    SUBGOAL_THEN
     `valuation D ((77 |-> (vy:A))((76 |-> y)((75 |-> z) v)))`
    ASSUME_TAC THENL [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
    CONJ_TAC THENL
     [ASM_SIMP_TAC[HOLDS_APPLY_FORM] THEN ASM_SIMP_TAC[VALMOD; ARITH_EQ];
      ASM_SIMP_TAC[HOLDS_OPAIR_FORM] THEN ASM_SIMP_TAC[VALMOD; ARITH_EQ]];
    ALL_TAC] THEN
  MATCH_MP_TAC(MESON[]
    `(!z:A. z IN D ==> (P z <=> Q z))
     ==> ((!z. z IN D ==> P z) <=> (!z. z IN D ==> Q z))`) THEN
  X_GEN_TAC `z:A` THEN DISCH_TAC THEN
  MATCH_MP_TAC(TAUT `(y <=> z) ==> ((x <=> y) <=> (x <=> z))`) THEN
  MATCH_MP_TAC(MESON[]
    `(!y:A. y IN D ==> (P y <=> Q y))
     ==> ((?y. y IN D /\ P y) <=> (?y. y IN D /\ Q y))`) THEN
  X_GEN_TAC `y:A` THEN DISCH_TAC THEN
  MATCH_MP_TAC(MESON[]
    `(!vy:A. vy IN D ==> (P vy <=> Q vy))
     ==> ((?vy. vy IN D /\ P vy) <=> (?vy. vy IN D /\ Q vy))`) THEN
  X_GEN_TAC `vy:A` THEN DISCH_TAC THEN
  USE_THEN "piles" (MP_TAC o SPECL [`z:A`;`y:A`;`vy:A`]) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  STRIP_TAC THEN ASM_REWRITE_TAC[]);;

(* F3c lemma 1b: chkgraph_form -- the per-stage check GRAPH
   { (x, x^) : x SUBSET w } where x^ = {(y^,1_B):y in x} (via chkimg).
   Mirror of collgraph_form: gate `subset_form 71 iw` (rank-strat)
   replaces the two membership gates (71%%iX)&&(71%%ild); inner chkimg_form
   replaces imgset_form.  Params igd,iw,igacc,ione;
   bound 70,71,72 (+chkimg 75,76,77). *)

let chkgraph_form = new_definition
  `chkgraph_form igd iw igacc ione =
     !! 70 ((70 %% igd) <->
        ?? 71 (?? 72
          (opair_form 71 72 70 && subset_form 71 iw &&
           chkimg_form 72 71 igacc ione)))`;;

let HOLDS_CHKGRAPH = prove
 (`!D (E:A->A->bool) v igd iw igacc ione.
     valuation D v /\
     ~(igd=70)/\ ~(igd=71)/\ ~(igd=72)/\ ~(igd=75)/\ ~(igd=76)/\ ~(igd=77)/\
     ~(iw=70)/\ ~(iw=71)/\ ~(iw=72)/\ ~(iw=75)/\ ~(iw=76)/\ ~(iw=77)/\
     ~(igacc=70)/\ ~(igacc=71)/\ ~(igacc=72)/\ ~(igacc=75)/\ ~(igacc=76)/\
       ~(igacc=77)/\
     ~(ione=70)/\ ~(ione=71)/\ ~(ione=72)/\ ~(ione=75)/\
       ~(ione=76)/\ ~(ione=77)
     ==> (holds D E v (chkgraph_form igd iw igacc ione) <=>
          !pp. pp IN D
               ==> (E pp (v igd) <=>
                    ?x. x IN D /\ ?img. img IN D /\
                        eopair D E x img pp /\ esubset D E x (v iw) /\
                        (!z. z IN D
                             ==> (E z img <=>
                                  ?y. y IN D /\ ?vy. vy IN D /\
                                      E y x /\ eapply D E (v igacc) y vy /\
                                      eopair D E vy (v ione) z))))`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `!x. (v:num->A) x IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[valuation]; ALL_TAC] THEN
  REWRITE_TAC[chkgraph_form; holds; HOLDS_EX; HOLDS_AND; HOLDS_IFF] THEN
  ASM_REWRITE_TAC[VALMOD; ARITH_EQ] THEN
  SUBGOAL_THEN
   `!pp x img:A. pp IN D /\ x IN D /\ img IN D
     ==> (holds D E ((72 |-> img)((71 |-> x)((70 |-> pp) v)))
            (opair_form 71 72 70) <=> eopair D E x img pp) /\
         (holds D E ((72 |-> img)((71 |-> x)((70 |-> pp) v)))
            (subset_form 71 iw) <=> esubset D E x (v iw)) /\
         (holds D E ((72 |-> img)((71 |-> x)((70 |-> pp) v)))
            (chkimg_form 72 71 igacc ione) <=>
          (!z. z IN D ==> (E z img <=>
               ?y. y IN D /\ ?vy. vy IN D /\
                   E y x /\ eapply D E (v igacc) y vy /\
                   eopair D E vy (v ione) z)))`
  (LABEL_TAC "piles") THENL
   [REPEAT GEN_TAC THEN STRIP_TAC THEN
    SUBGOAL_THEN `valuation D ((72 |-> (img:A))((71 |-> x)((70 |-> pp) v)))`
    ASSUME_TAC THENL [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
    CONJ_TAC THENL
     [ASM_SIMP_TAC[HOLDS_OPAIR_FORM] THEN ASM_SIMP_TAC[VALMOD; ARITH_EQ];
      ALL_TAC] THEN
    CONJ_TAC THENL
     [ASM_SIMP_TAC[HOLDS_SUBSET_FORM] THEN ASM_SIMP_TAC[VALMOD; ARITH_EQ];
      ALL_TAC] THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
                  `(72 |-> (img:A))((71 |-> x)((70 |-> pp) v))`;
                  `72`; `71`; `igacc:num`; `ione:num`] HOLDS_CHKIMG) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[ARITH_EQ]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN ASM_SIMP_TAC[VALMOD; ARITH_EQ];
    ALL_TAC] THEN
  MATCH_MP_TAC(MESON[]
    `(!pp:A. pp IN D ==> (P pp <=> Q pp)) ==>
     ((!pp. pp IN D ==> P pp) <=> (!pp. pp IN D ==> Q pp))`) THEN
  X_GEN_TAC `pp:A` THEN DISCH_TAC THEN
  MATCH_MP_TAC(TAUT `(y <=> z) ==> ((x <=> y) <=> (x <=> z))`) THEN
  MATCH_MP_TAC(MESON[]
    `(!x:A. x IN D ==> (P x <=> Q x)) ==>
     ((?x. x IN D /\ P x) <=> (?x. x IN D /\ Q x))`) THEN
  X_GEN_TAC `x:A` THEN DISCH_TAC THEN
  MATCH_MP_TAC(MESON[]
    `(!img:A. img IN D ==> (P img <=> Q img)) ==>
     ((?img. img IN D /\ P img) <=> (?img. img IN D /\ Q img))`) THEN
  X_GEN_TAC `img:A` THEN DISCH_TAC THEN
  USE_THEN "piles" (MP_TAC o SPECL [`pp:A`;`x:A`;`img:A`]) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  STRIP_TAC THEN ASM_REWRITE_TAC[]);;

(* F3c lemma 2a: the check step -- semantic predicate + step formula + FV.
   RANK-STRATIFIED: gacc = UNION range(r) (accumulated check-graph),
   w = dom(gacc)
   (accumulated domain); out = { (x,
   x^) : x SUBSET w } where x^ = {(y^,1_B):y in x}.
   Threads onebee (=1_B) at valuation slot 2, exactly as B at slot 2 in F3a.
   Mirror of ecollstep (drops defof/ld: rank-strat, not L-strat). *)

let checkstep = new_definition
  `checkstep D (E:A->A->bool) onebee g out <=>
     ?gacc. gacc IN D /\ ?w. w IN D /\
        eranu D E g gacc /\
        edomain D E gacc w /\
        (!pp. pp IN D
              ==> (E pp out <=>
                   ?x. x IN D /\ ?img. img IN D /\
                       eopair D E x img pp /\ esubset D E x w /\
                       (!z. z IN D
                            ==> (E z img <=>
                                 ?y. y IN D /\ ?vy. vy IN D /\
                                     E y x /\ eapply D E gacc y vy /\
                                     eopair D E vy onebee z))))`;;

let check_step_form = new_definition
  `check_step_form =
     ?? 3 (?? 4 ((!! 5 (5 %% 3 <-> ranmem_form 5 0)) &&
                 domain_form 3 4 &&
                 chkgraph_form 1 4 3 2))`;;

let FV_CHKIMG_FORM_SUB = prove
 (`!iimg ix igacc ione.
      FV(chkimg_form iimg ix igacc ione) SUBSET {iimg,ix,igacc,ione}`,
  REPEAT GEN_TAC THEN
  REWRITE_TAC[chkimg_form; FV; FV_CLAUSES; FV_APPLY_FORM; FV_OPAIR_FORM] THEN
  REWRITE_TAC[SUBSET; IN_DELETE; IN_UNION; IN_INSERT; NOT_IN_EMPTY] THEN
  ARITH_TAC);;

let FV_CHKGRAPH_FORM_SUB = prove
 (`!igd iw igacc ione.
      FV(chkgraph_form igd iw igacc ione) SUBSET {igd,iw,igacc,ione}`,
  REPEAT GEN_TAC THEN
  REWRITE_TAC[chkgraph_form; FV; FV_CLAUSES; FV_OPAIR_FORM;
              FV_SUBSET_FORM] THEN
  REWRITE_TAC[SUBSET; IN_DELETE; IN_UNION; IN_INSERT; NOT_IN_EMPTY] THEN
  MESON_TAC[REWRITE_RULE[SUBSET; IN_INSERT; NOT_IN_EMPTY]
              (SPECL [`72`;`71`;`igacc:num`;`ione:num`] FV_CHKIMG_FORM_SUB)]);;

let FV_CHECK_STEP_FORM_SUB = prove
 (`FV check_step_form SUBSET {0,1,2}`,
  REWRITE_TAC[check_step_form; FV; FV_CLAUSES; FV_RANMEM_FORM;
              FV_DOMAIN_FORM] THEN
  REWRITE_TAC[SUBSET; IN_DELETE; IN_UNION; IN_INSERT; NOT_IN_EMPTY] THEN
  MESON_TAC[REWRITE_RULE[SUBSET; IN_INSERT; NOT_IN_EMPTY]
              (SPECL [`1`;`4`;`3`;`2`] FV_CHKGRAPH_FORM_SUB)]);;

let FVLT_CHECK_STEP_FORM = prove
 (`!m. m IN FV check_step_form ==> m < 3`,
  GEN_TAC THEN DISCH_TAC THEN
  MP_TAC(REWRITE_RULE[SUBSET] FV_CHECK_STEP_FORM_SUB) THEN
  DISCH_THEN(MP_TAC o SPEC `m:num`) THEN
  ASM_REWRITE_TAC[IN_INSERT; NOT_IN_EMPTY] THEN ARITH_TAC);;

(* F3c lemma 2b: HOLDS_CHECK_STEP -- holds check_step_form <=> checkstep.
   Mirror of HOLDS_BNAME_STEP_FORM, but two existentials (gacc=3, w=4)
   and the domain/chkgraph clauses instead of the single ranmem/bnmem pair.
   VV = (4|->w)((3|->gacc)((1|->out)((0|->g)v))). *)

let HOLDS_CHECK_STEP = prove
 (`!D (E:A->A->bool) v g out.
      model D E ZF_AX /\ valuation D v /\ g IN D /\ out IN D
      ==> (holds D E ((1 |-> out) ((0 |-> g) v)) check_step_form <=>
           checkstep D E (v 2) g out)`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `!x. (v:num->A) x IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[valuation]; ALL_TAC] THEN
  REWRITE_TAC[check_step_form; holds; HOLDS_IFF; HOLDS_EX; HOLDS_AND;
              checkstep] THEN
  REWRITE_TAC[VALMOD; ARITH_EQ] THEN
  MATCH_MP_TAC(MESON[]
    `(!gacc:A. gacc IN D ==> (P gacc <=> Q gacc))
     ==> ((?gacc. gacc IN D /\ P gacc) <=> (?gacc. gacc IN D /\ Q gacc))`) THEN
  X_GEN_TAC `gacc:A` THEN DISCH_TAC THEN
  MATCH_MP_TAC(MESON[]
    `(!w:A. w IN D ==> (P w <=> Q w))
     ==> ((?w. w IN D /\ P w) <=> (?w. w IN D /\ Q w))`) THEN
  X_GEN_TAC `w:A` THEN DISCH_TAC THEN
  SUBGOAL_THEN
   `valuation D ((4 |-> (w:A))((3 |-> gacc)((1 |-> out)((0 |-> g) v))))`
  ASSUME_TAC THENL [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
  SUBGOAL_THEN
   `holds D E ((4 |-> (w:A))((3 |-> gacc)((1 |-> out)((0 |-> g) v))))
      (domain_form 3 4) <=> edomain D E gacc w`
  ASSUME_TAC THENL
   [MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;
                  `(4 |-> (w:A))((3 |-> gacc)((1 |-> out)((0 |-> g) v)))`;
                  `3`;`4`] HOLDS_DOMAIN_FORM) THEN
    ASM_REWRITE_TAC[] THEN DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    REWRITE_TAC[VALMOD; ARITH_EQ]; ALL_TAC] THEN
  SUBGOAL_THEN
   `holds D E ((4 |-> (w:A))((3 |-> gacc)((1 |-> out)((0 |-> g) v))))
      (chkgraph_form 1 4 3 2) <=>
    (!pp. pp IN D
          ==> (E pp out <=>
               ?x. x IN D /\ ?img. img IN D /\
                   eopair D E x img pp /\ esubset D E x w /\
                   (!z. z IN D
                        ==> (E z img <=>
                             ?y. y IN D /\ ?vy. vy IN D /\
                                 E y x /\ eapply D E gacc y vy /\
                                 eopair D E vy (v 2) z))))`
  ASSUME_TAC THENL
   [MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;
                  `(4 |-> (w:A))((3 |-> gacc)((1 |-> out)((0 |-> g) v)))`;
                  `1`;`4`;`3`;`2`] HOLDS_CHKGRAPH) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[ARITH_EQ]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    REWRITE_TAC[VALMOD; ARITH_EQ]; ALL_TAC] THEN
  ASM_REWRITE_TAC[] THEN
  MATCH_MP_TAC(TAUT `(p <=> q) ==> ((p /\ r) <=> (q /\ r))`) THEN
  REWRITE_TAC[eranu] THEN ASM_REWRITE_TAC[] THEN
  MATCH_MP_TAC(MESON[]
    `(!u:A. u IN D ==> (P u <=> Q u))
     ==> ((!u. u IN D ==> P u) <=> (!u. u IN D ==> Q u))`) THEN
  X_GEN_TAC `u:A` THEN DISCH_TAC THEN
  MATCH_MP_TAC(TAUT `(y <=> z) ==> ((x <=> y) <=> (x <=> z))`) THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;
                `(5 |-> (u:A))
                 ((4 |-> w)((3 |-> gacc)((1 |-> out)((0 |-> g) v))))`;
                `5`;`0`] HOLDS_RANMEM_FORM) THEN
  ANTS_TAC THENL [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN REWRITE_TAC[VALMOD; ARITH_EQ]);;

(* F3c lemma 3: CHECKSTEP_FUN -- functionality of the check step.
   gacc unique by ERANU_UNIQUE, w unique by EDOMAIN_UNIQUE, then out by
   ZF_EXTENSIONALITY (identical membership bodies).  out/out' IN D come from
   the engine's QFUN wrapper. Mirror BNSTEP_FUN / ECOLLSTEP_FUN. *)

let CHECKSTEP_FUN = prove
 (`!D (E:A->A->bool) onebee g out out'.
        model D E ZF_AX /\ out IN D /\ out' IN D /\
        checkstep D E onebee g out /\ checkstep D E onebee g out'
        ==> out = out'`,
  REWRITE_TAC[checkstep] THEN REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `gacc:A = gacc'` SUBST_ALL_TAC THENL
   [ASM_MESON_TAC[ERANU_UNIQUE]; ALL_TAC] THEN
  SUBGOAL_THEN `w:A = w'` SUBST_ALL_TAC THENL
   [ASM_MESON_TAC[EDOMAIN_UNIQUE]; ALL_TAC] THEN
  FIRST_ASSUM(MATCH_MP_TAC o MATCH_MP ZF_EXTENSIONALITY) THEN
  ASM_REWRITE_TAC[] THEN X_GEN_TAC `z:A` THEN DISCH_TAC THEN ASM_SIMP_TAC[]);;

(* F3c TOTAL support, Load A:
   EDOMAIN_EXISTS  -- domain of a set-relation exists (dom g on double union).
   chkimgpred_form/HOLDS_CHKIMGPRED -- the membership PREDICATE for the tagged
       image {(gacc(y),onebee):y in x} (free z-slot; = inner of chkimg_form).
   ECHKIMG_EXISTS  -- that image exists (separation on ran(gacc) x
     {onebee}). *)

(* ---- domain existence: dom(g) = {u IN UU g : eindom g u} ---- *)
let EDOMAIN_EXISTS = prove
 (`!D (E:A->A->bool) g.
        model D E ZF_AX /\ g IN D ==> ?a. edomain D E g a`,
  REPEAT STRIP_TAC THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `g:A`] EUNION_EXISTS) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `u1:A`) THEN
  SUBGOAL_THEN `(u1:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[EUNION_IN]; ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `u1:A`] EUNION_EXISTS) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `u2:A`) THEN
  SUBGOAL_THEN `(u2:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[EUNION_IN]; ALL_TAC] THEN
  SUBGOAL_THEN
   `!u:A. u IN D /\ eindom D (E:A->A->bool) g u ==> E u u2`
  (LABEL_TAC "bound") THENL
   [X_GEN_TAC `u:A` THEN REWRITE_TAC[eindom; eapply] THEN
    DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC
      (X_CHOOSE_THEN `p:A` (CONJUNCTS_THEN2 ASSUME_TAC
        (X_CHOOSE_THEN `zpair:A` STRIP_ASSUME_TAC)))) THEN
    SUBGOAL_THEN `(zpair:A) IN D` ASSUME_TAC THENL
     [ASM_MESON_TAC[EOPAIR_IN]; ALL_TAC] THEN
    FIRST_X_ASSUM(MP_TAC o GEN_REWRITE_RULE I [eopair]) THEN
    DISCH_THEN(X_CHOOSE_THEN `s:A`
               (X_CHOOSE_THEN `pr:A` STRIP_ASSUME_TAC)) THEN
    SUBGOAL_THEN `(s:A) IN D /\ (pr:A) IN D` STRIP_ASSUME_TAC THENL
     [ASM_MESON_TAC[EPAIR_IN]; ALL_TAC] THEN
    SUBGOAL_THEN `(E:A->A->bool) u s` ASSUME_TAC THENL
     [ASM_MESON_TAC[epair]; ALL_TAC] THEN
    SUBGOAL_THEN `(E:A->A->bool) s zpair` ASSUME_TAC THENL
     [ASM_MESON_TAC[epair]; ALL_TAC] THEN
    SUBGOAL_THEN `(E:A->A->bool) s u1` ASSUME_TAC THENL
     [ASM_MESON_TAC[eunion]; ALL_TAC] THEN
    ASM_MESON_TAC[eunion]; ALL_TAC] THEN
  FIRST_ASSUM(X_CHOOSE_TAC `v0:num->A` o MATCH_MP VALUATION_EXISTS o
              MATCH_MP MODEL_NONEMPTY) THEN
  SUBGOAL_THEN `valuation D ((1 |-> (g:A)) v0)` ASSUME_TAC THENL
   [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
  FIRST_ASSUM(MP_TAC o SPECL
    [`?? 2 (apply_form 1 0 2)`; `0`; `(1 |-> (g:A)) v0`; `u2:A`] o
    MATCH_MP ZF_SEPARATION) THEN
  ASM_REWRITE_TAC[] THEN
  MATCH_MP_TAC MONO_EXISTS THEN X_GEN_TAC `a:A` THEN STRIP_TAC THEN
  ASM_REWRITE_TAC[edomain] THEN X_GEN_TAC `u:A` THEN DISCH_TAC THEN
  SUBGOAL_THEN `valuation D ((0 |-> (u:A)) ((1 |-> g) v0))` ASSUME_TAC THENL
   [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
  ASM_SIMP_TAC[] THEN
  SUBGOAL_THEN
   `holds D E ((0 |-> (u:A)) ((1 |-> g) v0)) (?? 2 (apply_form 1 0 2)) <=>
    eindom D E g u`
  (fun th -> REWRITE_TAC[th]) THENL
   [REWRITE_TAC[eindom; HOLDS_EX] THEN
    MATCH_MP_TAC(MESON[]
      `(!a:A. a IN D ==> (P a <=> Q a))
       ==> ((?a. a IN D /\ P a) <=> (?a. a IN D /\ Q a))`) THEN
    X_GEN_TAC `ww:A` THEN DISCH_TAC THEN
    SUBGOAL_THEN `valuation D ((2 |-> (ww:A)) ((0 |-> u) ((1 |-> g) v0)))`
    ASSUME_TAC THENL [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
    ASM_SIMP_TAC[HOLDS_APPLY_FORM] THEN REWRITE_TAC[VALMOD; ARITH_EQ];
    ALL_TAC] THEN
  EQ_TAC THENL [MESON_TAC[]; ALL_TAC] THEN
  DISCH_TAC THEN ASM_REWRITE_TAC[] THEN
  USE_THEN "bound" (fun th -> MP_TAC(SPEC `u:A` th)) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC]);;

(* ---- tagged-image membership predicate (free z at iz; y=76, vy=77) ---- *)
let chkimgpred_form = new_definition
  `chkimgpred_form iz ix igacc ione =
     ?? 76 (?? 77
            ((76 %% ix) && apply_form igacc 76 77 && opair_form 77 ione iz))`;;

let HOLDS_CHKIMGPRED = prove
 (`!D (E:A->A->bool) v iz ix igacc ione.
     valuation D v /\
     ~(ix=76)/\ ~(ix=77)/\ ~(igacc=76)/\ ~(igacc=77)/\
     ~(ione=76)/\ ~(ione=77)/\ ~(iz=76)/\ ~(iz=77)
     ==> (holds D E v (chkimgpred_form iz ix igacc ione) <=>
          ?y. y IN D /\ ?vy. vy IN D /\
              E y (v ix) /\ eapply D E (v igacc) y vy /\
              eopair D E vy (v ione) (v iz))`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `!x. (v:num->A) x IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[valuation]; ALL_TAC] THEN
  REWRITE_TAC[chkimgpred_form; holds; HOLDS_EX; HOLDS_AND] THEN
  ASM_REWRITE_TAC[VALMOD; ARITH_EQ] THEN
  SUBGOAL_THEN
   `!y vy:A. y IN D /\ vy IN D
     ==> (holds D E ((77 |-> vy)((76 |-> y) v)) (apply_form igacc 76 77) <=>
          eapply D E (v igacc) y vy) /\
         (holds D E ((77 |-> vy)((76 |-> y) v)) (opair_form 77 ione iz) <=>
          eopair D E vy (v ione) (v iz))`
  (LABEL_TAC "piles") THENL
   [REPEAT GEN_TAC THEN STRIP_TAC THEN
    SUBGOAL_THEN `valuation D ((77 |-> (vy:A))((76 |-> y) v))` ASSUME_TAC THENL
     [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
    CONJ_TAC THENL
     [ASM_SIMP_TAC[HOLDS_APPLY_FORM] THEN ASM_SIMP_TAC[VALMOD; ARITH_EQ];
      ASM_SIMP_TAC[HOLDS_OPAIR_FORM] THEN ASM_SIMP_TAC[VALMOD; ARITH_EQ]];
    ALL_TAC] THEN
  MATCH_MP_TAC(MESON[]
    `(!y:A. y IN D ==> (P y <=> Q y))
     ==> ((?y. y IN D /\ P y) <=> (?y. y IN D /\ Q y))`) THEN
  X_GEN_TAC `y:A` THEN DISCH_TAC THEN
  MATCH_MP_TAC(MESON[]
    `(!vy:A. vy IN D ==> (P vy <=> Q vy))
     ==> ((?vy. vy IN D /\ P vy) <=> (?vy. vy IN D /\ Q vy))`) THEN
  X_GEN_TAC `vy:A` THEN DISCH_TAC THEN
  USE_THEN "piles" (MP_TAC o SPECL [`y:A`;`vy:A`]) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  STRIP_TAC THEN ASM_REWRITE_TAC[]);;

(* ---- image existence: img = {z IN ran(gacc)x{onebee} : chkimgpred z} ---- *)
let ECHKIMG_EXISTS = prove
 (`!D (E:A->A->bool) x gacc onebee.
     model D E ZF_AX /\ x IN D /\ gacc IN D /\ onebee IN D
     ==> ?img. img IN D /\
               !z. z IN D
                   ==> (E z img <=>
                        ?y. y IN D /\ ?vy. vy IN D /\
                            E y x /\ eapply D E gacc y vy /\
                            eopair D E vy onebee z)`,
  REPEAT STRIP_TAC THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`gacc:A`] EUNION_EXISTS) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `u1:A`) THEN
  SUBGOAL_THEN `(u1:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[EUNION_IN]; ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`u1:A`] EUNION_EXISTS) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `u2:A`) THEN
  SUBGOAL_THEN `(u2:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[EUNION_IN]; ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`onebee:A`;`onebee:A`]
         EPAIR_EXISTS) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `so:A`) THEN
  SUBGOAL_THEN `(so:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[EPAIR_IN]; ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`u2:A`;`so:A`] ECROSS_EXISTS) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `cr:A`) THEN
  SUBGOAL_THEN `(cr:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[ecross]; ALL_TAC] THEN
  SUBGOAL_THEN
   `!z:A. z IN D /\
          (?y. y IN D /\ ?vy. vy IN D /\
               E y x /\ eapply D E gacc y vy /\ eopair D E vy onebee z)
          ==> E z cr`
  (LABEL_TAC "bound") THENL
   [X_GEN_TAC `z:A` THEN
    DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC
      (X_CHOOSE_THEN `y:A` (CONJUNCTS_THEN2 ASSUME_TAC
        (X_CHOOSE_THEN `vy:A` STRIP_ASSUME_TAC)))) THEN
    SUBGOAL_THEN `(E:A->A->bool) vy u2` ASSUME_TAC THENL
     [UNDISCH_TAC `eapply D (E:A->A->bool) gacc y vy` THEN
      REWRITE_TAC[eapply] THEN
      DISCH_THEN(X_CHOOSE_THEN `wpair:A` STRIP_ASSUME_TAC) THEN
      SUBGOAL_THEN `(wpair:A) IN D` ASSUME_TAC THENL
       [ASM_MESON_TAC[EOPAIR_IN]; ALL_TAC] THEN
      UNDISCH_TAC `eopair D (E:A->A->bool) y vy wpair` THEN
      REWRITE_TAC[eopair] THEN
      DISCH_THEN(X_CHOOSE_THEN `s1:A`
                 (X_CHOOSE_THEN `pp:A` STRIP_ASSUME_TAC)) THEN
      SUBGOAL_THEN `(s1:A) IN D /\ (pp:A) IN D` STRIP_ASSUME_TAC THENL
       [ASM_MESON_TAC[EPAIR_IN]; ALL_TAC] THEN
      SUBGOAL_THEN `(E:A->A->bool) pp wpair` ASSUME_TAC THENL
       [ASM_MESON_TAC[epair]; ALL_TAC] THEN
      SUBGOAL_THEN `(E:A->A->bool) vy pp` ASSUME_TAC THENL
       [ASM_MESON_TAC[epair]; ALL_TAC] THEN
      SUBGOAL_THEN `(E:A->A->bool) pp u1` ASSUME_TAC THENL
       [ASM_MESON_TAC[eunion]; ALL_TAC] THEN
      ASM_MESON_TAC[eunion]; ALL_TAC] THEN
    SUBGOAL_THEN `(E:A->A->bool) onebee so` ASSUME_TAC THENL
     [ASM_MESON_TAC[epair]; ALL_TAC] THEN
    ASM_MESON_TAC[ecross]; ALL_TAC] THEN
  FIRST_ASSUM(X_CHOOSE_TAC `v0:num->A` o MATCH_MP VALUATION_EXISTS o
              MATCH_MP MODEL_NONEMPTY) THEN
  SUBGOAL_THEN
   `valuation D ((71 |-> (x:A)) ((72 |-> (gacc:A)) ((73 |-> (onebee:A)) v0)))`
  ASSUME_TAC THENL [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
  FIRST_ASSUM(MP_TAC o SPECL
    [`chkimgpred_form 70 71 72 73`; `70`;
     `(71 |-> (x:A)) ((72 |-> (gacc:A)) ((73 |-> (onebee:A)) v0))`; `cr:A`] o
    MATCH_MP ZF_SEPARATION) THEN
  ASM_REWRITE_TAC[] THEN MATCH_MP_TAC MONO_EXISTS THEN
  X_GEN_TAC `img:A` THEN STRIP_TAC THEN ASM_REWRITE_TAC[] THEN
  X_GEN_TAC `z:A` THEN DISCH_TAC THEN
  SUBGOAL_THEN
   `valuation D
    ((70 |-> (z:A)) ((71 |-> x) ((72 |-> gacc) ((73 |-> onebee) v0))))`
  ASSUME_TAC THENL [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
  ASM_SIMP_TAC[] THEN
  SUBGOAL_THEN
   `holds D E
    ((70 |-> (z:A)) ((71 |-> x) ((72 |-> gacc) ((73 |-> onebee) v0))))
      (chkimgpred_form 70 71 72 73) <=>
    ?y. y IN D /\ ?vy. vy IN D /\ E y x /\ eapply D E gacc y vy /\
        eopair D E vy onebee z`
  (fun th -> REWRITE_TAC[th]) THENL
   [MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;
      `(70 |-> (z:A)) ((71 |-> x) ((72 |-> gacc) ((73 |-> onebee) v0)))`;
      `70`;`71`;`72`;`73`] HOLDS_CHKIMGPRED) THEN
    ASM_REWRITE_TAC[ARITH_EQ] THEN DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    ASM_REWRITE_TAC[VALMOD; ARITH_EQ]; ALL_TAC] THEN
  EQ_TAC THENL [MESON_TAC[]; ALL_TAC] THEN
  DISCH_TAC THEN ASM_REWRITE_TAC[] THEN
  USE_THEN "bound" (fun th -> MP_TAC(SPEC `z:A` th)) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC]);;
(* F3c lemma 4a: checkmap_form -- the REPLACEMENT map x |-> (x, x^) where
   x^ = {(gacc(y),onebee):y in x} (via chkimg).  NO gate conjunct: the
   `x SUBSET w` gate comes from replacing over pw=P(w), not from the formula.
   img=72 (bound), ix=x, igacc=gacc, ione=onebee, ipp=pp.
   Mirror of collmap_form (drops the (71%%68) gate; chkimg not imgset). *)

let checkmap_form = new_definition
  `checkmap_form ipp ix igacc ione =
     ?? 72 (chkimg_form 72 ix igacc ione && opair_form ix 72 ipp)`;;
(* HOLDS_CHECKMAP (re-run; checkmap_form already bound). *)
let HOLDS_CHECKMAP = prove
 (`!D (E:A->A->bool) v ipp ix igacc ione.
     valuation D v /\
     ~(ix=72)/\ ~(igacc=72)/\ ~(ione=72)/\ ~(ipp=72)/\
     ~(ix=75)/\ ~(ix=76)/\ ~(ix=77)/\
     ~(igacc=75)/\ ~(igacc=76)/\ ~(igacc=77)/\
     ~(ione=75)/\ ~(ione=76)/\ ~(ione=77)
     ==> (holds D E v (checkmap_form ipp ix igacc ione) <=>
          ?img. img IN D /\
                (!z. z IN D
                     ==> (E z img <=>
                          ?y. y IN D /\ ?vy. vy IN D /\
                              E y (v ix) /\ eapply D E (v igacc) y vy /\
                              eopair D E vy (v ione) z)) /\
                eopair D E (v ix) img (v ipp))`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `!x. (v:num->A) x IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[valuation]; ALL_TAC] THEN
  REWRITE_TAC[checkmap_form; holds; HOLDS_EX; HOLDS_AND] THEN
  ASM_REWRITE_TAC[VALMOD; ARITH_EQ] THEN
  MATCH_MP_TAC(MESON[]
    `(!img:A. img IN D ==> (P img <=> Q img))
     ==> ((?img. img IN D /\ P img) <=> (?img. img IN D /\ Q img))`) THEN
  X_GEN_TAC `img:A` THEN DISCH_TAC THEN
  SUBGOAL_THEN `valuation D ((72 |-> (img:A)) v)` ASSUME_TAC THENL
   [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `(72 |-> (img:A)) v`;
                `72`; `ix:num`; `igacc:num`; `ione:num`] HOLDS_CHKIMG) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[ARITH_EQ]; ALL_TAC] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  ASM_SIMP_TAC[HOLDS_OPAIR_FORM] THEN
  ASM_REWRITE_TAC[VALMOD; ARITH_EQ]);;
(* F3c lemma 4b: ECHKGRAPH_EXISTS -- the per-stage check graph exists.
   gd = { (x, x^) : x SUBSET w }, x^ = tagged image, built by REPLACEMENT over
   pw=P(w); each x in pw satisfies E x pw <=> esubset x w (epow), giving the
   rank gate for free.  Mirror of ECOLLGRAPH_EXISTS (a:=pw not X;
   functional witness via ECHKIMG_EXISTS+EOPAIR; E x pw -> esubset x w). *)

let ECHKGRAPH_EXISTS = prove
 (`!D (E:A->A->bool) gacc onebee w.
     model D E ZF_AX /\ gacc IN D /\ onebee IN D /\ w IN D
     ==> ?gd. gd IN D /\
              !pp. pp IN D
                   ==> (E pp gd <=>
                        ?x. x IN D /\ ?img. img IN D /\
                            eopair D E x img pp /\ esubset D E x w /\
                            (!z. z IN D
                                 ==> (E z img <=>
                                      ?y. y IN D /\ ?vy. vy IN D /\
                                          E y x /\ eapply D E gacc y vy /\
                                          eopair D E vy onebee z)))`,
  REPEAT STRIP_TAC THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`w:A`] EPOW_EXISTS) THEN
  ASM_REWRITE_TAC[] THEN REWRITE_TAC[epow] THEN
  DISCH_THEN(X_CHOOSE_THEN `pw:A`
    (CONJUNCTS_THEN2 ASSUME_TAC (LABEL_TAC "pwc"))) THEN
  FIRST_ASSUM(X_CHOOSE_TAC `v0:num->A` o MATCH_MP VALUATION_EXISTS o
              MATCH_MP MODEL_NONEMPTY) THEN
  SUBGOAL_THEN
   `valuation D ((69 |-> (gacc:A)) ((68 |-> (onebee:A)) v0))`
  ASSUME_TAC THENL [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
  FIRST_ASSUM(MP_TAC o SPECL
    [`checkmap_form 70 71 69 68`; `71`; `70`;
     `(69 |-> (gacc:A)) ((68 |-> (onebee:A)) v0)`; `pw:A`] o
    MATCH_MP ZF_REPLACEMENT) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[ARITH_EQ] THEN
    X_GEN_TAC `u:A` THEN STRIP_TAC THEN
    MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`u:A`;`gacc:A`;`onebee:A`]
      ECHKIMG_EXISTS) THEN
    ASM_REWRITE_TAC[] THEN
    DISCH_THEN(X_CHOOSE_THEN `img0:A`
      (CONJUNCTS_THEN2 ASSUME_TAC (LABEL_TAC "i0"))) THEN
    MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`u:A`;`img0:A`]
           EOPAIR_EXISTS) THEN
    ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `w0:A`) THEN
    SUBGOAL_THEN `(w0:A) IN D` ASSUME_TAC THENL
     [ASM_MESON_TAC[EOPAIR_IN]; ALL_TAC] THEN
    EXISTS_TAC `w0:A` THEN ASM_REWRITE_TAC[] THEN
    X_GEN_TAC `w':A` THEN
    DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC MP_TAC) THEN
    SUBGOAL_THEN
     `valuation D ((70 |-> (w':A)) ((71 |-> u)
        ((69 |-> gacc) ((68 |-> onebee) v0))))`
    ASSUME_TAC THENL [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
    MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;
      `(70 |-> (w':A)) ((71 |-> u) ((69 |-> gacc) ((68 |-> onebee) v0)))`;
      `70`;`71`;`69`;`68`] HOLDS_CHECKMAP) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[ARITH_EQ]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    REWRITE_TAC[VALMOD; ARITH_EQ] THEN
    DISCH_THEN(X_CHOOSE_THEN `img:A` (CONJUNCTS_THEN2 ASSUME_TAC
      (CONJUNCTS_THEN2 (LABEL_TAC "i1") ASSUME_TAC))) THEN
    SUBGOAL_THEN `img:A = img0` SUBST_ALL_TAC THENL
     [FIRST_ASSUM(MATCH_MP_TAC o MATCH_MP ZF_EXTENSIONALITY) THEN
      ASM_REWRITE_TAC[] THEN X_GEN_TAC `z:A` THEN DISCH_TAC THEN
      ASM_SIMP_TAC[]; ALL_TAC] THEN
    MATCH_MP_TAC EOPAIR_UNIQUE THEN
    MAP_EVERY EXISTS_TAC [`D:A->bool`;`E:A->A->bool`;`u:A`;`img0:A`] THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `gd:A`
    (CONJUNCTS_THEN2 ASSUME_TAC (LABEL_TAC "gdc"))) THEN
  EXISTS_TAC `gd:A` THEN ASM_REWRITE_TAC[] THEN
  X_GEN_TAC `pp:A` THEN DISCH_TAC THEN
  USE_THEN "gdc" (MP_TAC o SPEC `pp:A`) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  MATCH_MP_TAC(MESON[]
    `(!s:A. s IN D ==> (P s <=> Q s))
     ==> ((?s. s IN D /\ P s) <=> (?s. s IN D /\ Q s))`) THEN
  X_GEN_TAC `x:A` THEN DISCH_TAC THEN
  SUBGOAL_THEN
   `valuation D ((70 |-> (pp:A)) ((71 |-> x)
      ((69 |-> gacc) ((68 |-> onebee) v0))))`
  ASSUME_TAC THENL [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;
    `(70 |-> (pp:A)) ((71 |-> x) ((69 |-> gacc) ((68 |-> onebee) v0)))`;
    `70`;`71`;`69`;`68`] HOLDS_CHECKMAP) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[ARITH_EQ]; ALL_TAC] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  REWRITE_TAC[VALMOD; ARITH_EQ] THEN
  SUBGOAL_THEN `E (x:A) pw <=> esubset D E x w`
    (fun th -> REWRITE_TAC[th]) THENL
   [ASM_MESON_TAC[]; ALL_TAC] THEN
  EQ_TAC THENL
   [DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC
      (X_CHOOSE_THEN `img:A` STRIP_ASSUME_TAC)) THEN
    EXISTS_TAC `img:A` THEN ASM_REWRITE_TAC[];
    DISCH_THEN(X_CHOOSE_THEN `img:A` STRIP_ASSUME_TAC) THEN
    ASM_REWRITE_TAC[] THEN EXISTS_TAC `img:A` THEN ASM_REWRITE_TAC[]]);;

(* F3c lemma 5: CHECKSTEP_TOTAL -- the check step is total.
   gacc = ran(g) (ERANU), w = dom(gacc) (EDOMAIN), gd = graph (ECHKGRAPH);
   assemble into checkstep.  Mirror of ECOLLSTEP_TOTAL. *)

let CHECKSTEP_TOTAL = prove
 (`!D (E:A->A->bool) onebee g.
     model D E ZF_AX /\ onebee IN D /\ g IN D
     ==> ?out. out IN D /\ checkstep D E onebee g out`,
  REPEAT STRIP_TAC THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`g:A`] ERANU_EXISTS) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `gacc:A`) THEN
  SUBGOAL_THEN `(gacc:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[eranu]; ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`gacc:A`] EDOMAIN_EXISTS) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `w:A`) THEN
  SUBGOAL_THEN `(w:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[edomain]; ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`gacc:A`;`onebee:A`;`w:A`]
    ECHKGRAPH_EXISTS) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `gd:A`
    (CONJUNCTS_THEN2 ASSUME_TAC (LABEL_TAC "gdc"))) THEN
  EXISTS_TAC `gd:A` THEN ASM_REWRITE_TAC[checkstep] THEN
  EXISTS_TAC `gacc:A` THEN CONJ_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  EXISTS_TAC `w:A` THEN ASM_REWRITE_TAC[]);;
(* F3c Load C: check-step erec wrappers + the check-tower and its engine
   bridge/uniqueness/existence.  Verbatim structural mirror of the F3a block
   BNSTEP_QFUN / BNSTEP_QTOTAL / ebnstage / EBNSTAGE_EREC /
   EBNSTAGE_UNIQUE / EBNSTAGE_EXISTS,
   swapping bname_step_form -> check_step_form,
   FVLT_BNAME_STEP_FORM -> FVLT_CHECK_STEP_FORM,
   bnstep-side lemmas -> checkstep-
   side (CHECKSTEP_FUN/CHECKSTEP_TOTAL/HOLDS_CHECK_STEP), B -> onebee (=1_B,
   threaded at valuation slot 2 since FV check_step_form SUBSET {0,1,2}). *)

let CHECKSTEP_QFUN = prove
 (`!D (E:A->A->bool) v.
        model D E ZF_AX /\ valuation D v
        ==> !r w w'. r IN D /\ w IN D /\ w' IN D /\
                     holds D E ((1 |-> w) ((0 |-> r) v)) check_step_form /\
                     holds D E ((1 |-> w') ((0 |-> r) v)) check_step_form
                     ==> w = w'`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN REPEAT GEN_TAC THEN STRIP_TAC THEN
  MATCH_MP_TAC CHECKSTEP_FUN THEN
  MAP_EVERY EXISTS_TAC
    [`D:A->bool`; `E:A->A->bool`; `(v:num->A) 2`; `r:A`] THEN
  ASM_MESON_TAC[HOLDS_CHECK_STEP]);;

let CHECKSTEP_QTOTAL = prove
 (`!D (E:A->A->bool) v.
        model D E ZF_AX /\ valuation D v
        ==> !x. x IN D
                ==> ?y. y IN D /\
                        holds D E ((1 |-> y) ((0 |-> x) v)) check_step_form`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `(v:num->A) 2 IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[valuation]; ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `(v:num->A) 2`; `x:A`]
        CHECKSTEP_TOTAL) THEN
  ASM_REWRITE_TAC[] THEN
  MATCH_MP_TAC MONO_EXISTS THEN X_GEN_TAC `y:A` THEN STRIP_TAC THEN
  ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[HOLDS_CHECK_STEP]);;

(* Twin of ebnstage / elstage; erec engine reused verbatim, only the
   step form differs.  onebee (=1_B) is a FIXED parameter threaded through
   valuation slot 2 (FV check_step_form SUBSET {0,1,2};
   erec keeps slots it does
   not build, so v 2 = onebee persists).  Stage value y = the check graph
   { (x, x^) : x SUBSET w_a } (w_a = UNION of the stages below a). *)

let echecktower = new_definition
  `echecktower D (E:A->A->bool) onebee a y <=>
        ?v. valuation D v /\ v 2 = onebee /\ erec D E check_step_form v a y`;;

let ECHECKTOWER_EREC = prove
 (`!D (E:A->A->bool) onebee a y v.
        model D E ZF_AX /\ valuation D v /\ v 2 = onebee
        ==> (echecktower D E onebee a y <=> erec D E check_step_form v a y)`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[echecktower] THEN EQ_TAC THENL
   [DISCH_THEN(X_CHOOSE_THEN `v':num->A` STRIP_ASSUME_TAC) THEN
    SUBGOAL_THEN
     `erec D (E:A->A->bool) check_step_form v' a y <=>
      erec D E check_step_form v a y`
    (fun th -> ASM_MESON_TAC[th]) THEN
    MATCH_MP_TAC EREC_VALUATION THEN
    X_GEN_TAC `m:num` THEN STRIP_TAC THEN
    MP_TAC(SPEC `m:num` FVLT_CHECK_STEP_FORM) THEN
    ASM_REWRITE_TAC[] THEN DISCH_TAC THEN
    SUBGOAL_THEN `m = 2` ASSUME_TAC THENL
     [ASM_ARITH_TAC; ASM_MESON_TAC[]];
    ASM_MESON_TAC[]]);;

let ECHECKTOWER_UNIQUE = prove
 (`!D (E:A->A->bool) onebee a y y'.
        model D E ZF_AX /\ onebee IN D /\ a IN D /\ y IN D /\ y' IN D /\
        echecktower D E onebee a y /\ echecktower D E onebee a y'
        ==> y = y'`,
  REPEAT STRIP_TAC THEN
  FIRST_ASSUM(X_CHOOSE_TAC `v0:num->A` o MATCH_MP VALUATION_EXISTS o
              MATCH_MP MODEL_NONEMPTY) THEN
  ABBREV_TAC `v = (2 |-> (onebee:A)) v0` THEN
  SUBGOAL_THEN `valuation D (v:num->A) /\ (v:num->A) 2 = onebee`
  STRIP_ASSUME_TAC THENL
   [EXPAND_TAC "v" THEN ASM_SIMP_TAC[VALUATION_VALMOD; VALMOD]; ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `check_step_form`; `v:num->A`;
                `a:A`; `y:A`; `y':A`] EREC_UNIQUE) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN MATCH_MP_TAC THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `v:num->A`] CHECKSTEP_QFUN) THEN
  ASM_REWRITE_TAC[] THEN DISCH_TAC THEN ASM_REWRITE_TAC[] THEN
  ASM_MESON_TAC[ECHECKTOWER_EREC]);;

let ECHECKTOWER_EXISTS = prove
 (`!D (E:A->A->bool) onebee a.
        model D E ZF_AX /\ onebee IN D /\ eordinal D E a
        ==> ?y. y IN D /\ echecktower D E onebee a y`,
  REPEAT STRIP_TAC THEN
  FIRST_ASSUM(X_CHOOSE_TAC `v0:num->A` o MATCH_MP VALUATION_EXISTS o
              MATCH_MP MODEL_NONEMPTY) THEN
  ABBREV_TAC `v = (2 |-> (onebee:A)) v0` THEN
  SUBGOAL_THEN `valuation D (v:num->A) /\ (v:num->A) 2 = onebee`
  STRIP_ASSUME_TAC THENL
   [EXPAND_TAC "v" THEN ASM_SIMP_TAC[VALUATION_VALMOD; VALMOD]; ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `check_step_form`; `v:num->A`;
                `a:A`] EREC_EXISTS) THEN
  ASM_REWRITE_TAC[] THEN ANTS_TAC THENL
   [ASM_MESON_TAC[CHECKSTEP_QFUN; CHECKSTEP_QTOTAL]; ALL_TAC] THEN
  MATCH_MP_TAC MONO_EXISTS THEN X_GEN_TAC `y:A` THEN STRIP_TAC THEN
  ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[ECHECKTOWER_EREC]);;
(* F3c Load D: ECHECKTOWER_CHAR -- stage characterization (mirror of
   EBNSTAGE_CHAR).  Exposes gacc = ran(attempt) = UNION of the check
   stages below a (with its lower-stage membership char, identical to
   EBNSTAGE_CHAR's eranmem dance), w = dom(gacc), and the check-graph relation
   for the stage value ya.  Stage value named `ya` (not y) so the graph body's
   inner bound var `y` -- taken verbatim from checkstep -- does not clash, and
   the graph conjunct is syntactically identical to checkstep's. *)

let ECHECKTOWER_CHAR = prove
 (`!D (E:A->A->bool) onebee a ya.
      model D E ZF_AX /\ onebee IN D /\ eordinal D E a /\ ya IN D /\
      echecktower D E onebee a ya
      ==> ?gacc w. gacc IN D /\ w IN D /\
              (!u. u IN D
                   ==> (E u gacc <=>
                        ?b z. b IN D /\ z IN D /\ E b a /\
                              echecktower D E onebee b z /\ E u z)) /\
              edomain D E gacc w /\
              (!pp. pp IN D
                    ==> (E pp ya <=>
                         ?x. x IN D /\
                             ?img. img IN D /\
                                   eopair D E x img pp /\ esubset D E x w /\
                                   (!z. z IN D
                                        ==> (E z img <=>
                                             ?y. y IN D /\
                                                 ?vy. vy IN D /\
                                                      E y x /\
                                                      eapply D E gacc y vy /\
                                                      eopair D E vy
                                                        onebee z))))`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `(a:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[EORDINAL_IN]; ALL_TAC] THEN
  FIRST_ASSUM(X_CHOOSE_TAC `v0:num->A` o MATCH_MP VALUATION_EXISTS o
              MATCH_MP MODEL_NONEMPTY) THEN
  ABBREV_TAC `v = (2 |-> (onebee:A)) v0` THEN
  SUBGOAL_THEN `valuation D (v:num->A) /\ (v:num->A) 2 = onebee`
  STRIP_ASSUME_TAC THENL
   [EXPAND_TAC "v" THEN ASM_SIMP_TAC[VALUATION_VALMOD; VALMOD]; ALL_TAC] THEN
  SUBGOAL_THEN `?r:A. erecres D (E:A->A->bool) check_step_form v a r`
  STRIP_ASSUME_TAC THENL
   [MATCH_MP_TAC ERECRES_EXISTS THEN ASM_REWRITE_TAC[] THEN
    ASM_MESON_TAC[CHECKSTEP_QFUN; CHECKSTEP_QTOTAL];
    ALL_TAC] THEN
  SUBGOAL_THEN `(r:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[erecres]; ALL_TAC] THEN
  SUBGOAL_THEN `checkstep D (E:A->A->bool) onebee r ya` MP_TAC THENL
   [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `v:num->A`; `r:A`; `ya:A`]
          HOLDS_CHECK_STEP) THEN
    ASM_REWRITE_TAC[] THEN DISCH_THEN(SUBST1_TAC o SYM) THEN
    MATCH_MP_TAC EREC_EQUATION THEN
    EXISTS_TAC `a:A` THEN ASM_REWRITE_TAC[] THEN
    ASM_MESON_TAC[CHECKSTEP_QFUN; ECHECKTOWER_EREC];
    ALL_TAC] THEN
  REWRITE_TAC[checkstep] THEN
  DISCH_THEN(X_CHOOSE_THEN `gacc:A` (CONJUNCTS_THEN2 ASSUME_TAC
    (X_CHOOSE_THEN `w:A`
     (fun th -> MAP_EVERY ASSUME_TAC (CONJUNCTS th))))) THEN
  MAP_EVERY EXISTS_TAC [`gacc:A`; `w:A`] THEN
  ASM_REWRITE_TAC[] THEN
  (* remaining: the gacc-membership characterization (verbatim mirror of the *)
  (* eranmem branch in EBNSTAGE_CHAR: E u gacc <=> eranmem u r <=> lower     *)
  (* stage)                                                                  *)
  SUBGOAL_THEN
   `!b z:A. erec D (E:A->A->bool) check_step_form v b z <=>
            echecktower D E onebee b z`
  (LABEL_TAC "conv") THENL
   [ASM_MESON_TAC[ECHECKTOWER_EREC]; ALL_TAC] THEN
  X_GEN_TAC `u:A` THEN DISCH_TAC THEN
  SUBGOAL_THEN `(E:A->A->bool) u gacc <=> eranmem D E u r`
  (fun th -> REWRITE_TAC[th]) THENL
   [ASM_MESON_TAC[eranu]; ALL_TAC] THEN
  REWRITE_TAC[eranmem] THEN EQ_TAC THENL
   [DISCH_THEN(X_CHOOSE_THEN `vl:A` (X_CHOOSE_THEN `pr:A`
      (X_CHOOSE_THEN `ord:A`
        (fun th -> MAP_EVERY ASSUME_TAC (CONJUNCTS th))))) THEN
    SUBGOAL_THEN
     `?b z:A. b IN D /\ z IN D /\ E b a /\
              erec D (E:A->A->bool) check_step_form v b z /\
              eopair D E b z pr`
    STRIP_ASSUME_TAC THENL
     [FIRST_ASSUM(MP_TAC o SPEC `pr:A` o CONJUNCT2 o
        GEN_REWRITE_RULE I [erecres]) THEN
      ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    SUBGOAL_THEN `ord:A = b /\ vl:A = z` STRIP_ASSUME_TAC THENL
     [ASM_MESON_TAC[EOPAIR_INJ]; ALL_TAC] THEN
    MAP_EVERY EXISTS_TAC [`b:A`; `z:A`] THEN
    ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[];
    DISCH_THEN(X_CHOOSE_THEN `b:A` (X_CHOOSE_THEN `z:A`
      (fun th -> MAP_EVERY ASSUME_TAC (CONJUNCTS th)))) THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `b:A`; `z:A`]
          EOPAIR_EXISTS) THEN
    ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `pr:A`) THEN
    SUBGOAL_THEN `(pr:A) IN D` ASSUME_TAC THENL
     [ASM_MESON_TAC[EOPAIR_IN]; ALL_TAC] THEN
    MAP_EVERY EXISTS_TAC [`z:A`; `pr:A`; `b:A`] THEN
    ASM_REWRITE_TAC[] THEN
    FIRST_ASSUM(MP_TAC o SPEC `pr:A` o CONJUNCT2 o
      GEN_REWRITE_RULE I [erecres]) THEN
    ASM_REWRITE_TAC[] THEN DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    ASM_MESON_TAC[]]);;

(* ========================================================================= *)
(* F3d: CHECK-NAME COHERENCE + well-defn.                                    *)
(*                                                                           *)
(* The check tower echecktower is stratified by the erec engine, so its      *)
(* stage value cd_a is only meaningful once we know the accumulated graph    *)
(* gacc_a = UNION_{b<a} stage_b is COHERENT (single-valued): a later stage   *)
(* must extend an earlier one, never disagree.  This is the exact analogue   *)
(* of the Mostowski-collapse coherence ECOLLTOWER_COHERE, but SIMPLER:       *)
(* the check stage value is a BARE graph cd_a (not an <L(a),ga> pair), so no *)
(* ECOLLTOWER_SND/goodf/FST arm is needed -- the object formula goodf2check  *)
(* reads the stage value directly as the graph.  As there, coherence is      *)
(* proved by an INTERNAL least-counterexample argument (EORDINAL_LEAST on    *)
(* Not goodf2check), never by meta-induction: the model may be non-          *)
(* wellfounded.  Coherence delivers cross-stage single-valuedness            *)
(* ECHECKTOWER_SV, whence the check-name class map echeck is well defined    *)
(* (ECHECK_SV): each x has AT MOST ONE check-name x^.                        *)
(* ========================================================================= *)

let ECHECKTOWER_OPAIR = prove
 (`!D (E:A->A->bool) onebee a ya pp.
        model D E ZF_AX /\ onebee IN D /\ eordinal D E a /\ ya IN D /\
        echecktower D E onebee a ya /\ pp IN D /\ E pp ya
        ==> ?x img. x IN D /\ img IN D /\ eopair D E x img pp`,
  REPEAT STRIP_TAC THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `onebee:A`; `a:A`; `ya:A`]
        ECHECKTOWER_CHAR) THEN
  ASM_REWRITE_TAC[] THEN
  INTRO_TAC "@gacc w. gaccD wD h h2 yac" THEN
  USE_THEN "yac" (MP_TAC o SPEC `pp:A`) THEN
  REWRITE_TAC[ASSUME `(pp:A) IN D`; ASSUME `(E:A->A->bool) pp ya`] THEN
  DISCH_THEN(X_CHOOSE_THEN `x:A` (CONJUNCTS_THEN2 ASSUME_TAC
    (X_CHOOSE_THEN `img:A`
     (fun th -> MAP_EVERY ASSUME_TAC (CONJUNCTS th))))) THEN
  MAP_EVERY EXISTS_TAC [`x:A`; `img:A`] THEN ASM_REWRITE_TAC[]);;

let ECHECKTOWER_VALUE = prove
 (`!D (E:A->A->bool) onebee a ya pp.
      model D E ZF_AX /\ onebee IN D /\ eordinal D E a /\ ya IN D /\
      echecktower D E onebee a ya /\ pp IN D /\ E pp ya
      ==> ?gacc w x img.
              gacc IN D /\ w IN D /\ x IN D /\ img IN D /\
              (!u. u IN D
                   ==> (E u gacc <=>
                        ?b z. b IN D /\ z IN D /\ E b a /\
                              echecktower D E onebee b z /\ E u z)) /\
              edomain D E gacc w /\
              eopair D E x img pp /\ esubset D E x w /\
              (!z. z IN D
                   ==> (E z img <=>
                        ?y. y IN D /\ ?vy. vy IN D /\ E y x /\
                            eapply D E gacc y vy /\ eopair D E vy onebee z))`,
  REPEAT STRIP_TAC THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `onebee:A`; `a:A`; `ya:A`]
        ECHECKTOWER_CHAR) THEN
  ASM_REWRITE_TAC[] THEN
  INTRO_TAC "@gacc w. gaccD wD gaccc h yac" THEN
  USE_THEN "yac" (MP_TAC o SPEC `pp:A`) THEN
  REWRITE_TAC[ASSUME `(pp:A) IN D`; ASSUME `(E:A->A->bool) pp ya`] THEN
  DISCH_THEN(X_CHOOSE_THEN `x:A` (CONJUNCTS_THEN2 ASSUME_TAC
    (X_CHOOSE_THEN `img:A`
     (fun th -> MAP_EVERY ASSUME_TAC (CONJUNCTS th))))) THEN
  MAP_EVERY EXISTS_TAC [`gacc:A`; `w:A`; `x:A`; `img:A`] THEN
  ASM_REWRITE_TAC[]);;

let ECHECKTOWER_STAGE_SV = prove
 (`!D (E:A->A->bool) onebee a ya x img img' pp pp'.
      model D E ZF_AX /\ onebee IN D /\ eordinal D E a /\ ya IN D /\
      echecktower D E onebee a ya /\
      x IN D /\ img IN D /\ img' IN D /\ pp IN D /\ pp' IN D /\
      eopair D E x img pp /\ eopair D E x img' pp' /\ E pp ya /\ E pp' ya
      ==> img = img'`,
  REPEAT STRIP_TAC THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `onebee:A`; `a:A`; `ya:A`]
        ECHECKTOWER_CHAR) THEN
  ASM_REWRITE_TAC[] THEN
  INTRO_TAC "@gacc w. gaccD wD h h2 yac" THEN
  USE_THEN "yac" (MP_TAC o SPEC `pp:A`) THEN
  REWRITE_TAC[ASSUME `(pp:A) IN D`; ASSUME `(E:A->A->bool) pp ya`] THEN
  DISCH_THEN(X_CHOOSE_THEN `x1:A` (CONJUNCTS_THEN2 ASSUME_TAC
    (X_CHOOSE_THEN `img1:A`
     (fun th -> MAP_EVERY ASSUME_TAC (CONJUNCTS th))))) THEN
  SUBGOAL_THEN `x1:A = x /\ img1:A = img`
   (CONJUNCTS_THEN2 SUBST_ALL_TAC SUBST_ALL_TAC) THENL
   [ASM_MESON_TAC[EOPAIR_INJ]; ALL_TAC] THEN
  USE_THEN "yac" (MP_TAC o SPEC `pp':A`) THEN
  REWRITE_TAC[ASSUME `(pp':A) IN D`; ASSUME `(E:A->A->bool) pp' ya`] THEN
  DISCH_THEN(X_CHOOSE_THEN `x2:A` (CONJUNCTS_THEN2 ASSUME_TAC
    (X_CHOOSE_THEN `img2:A`
     (fun th -> MAP_EVERY ASSUME_TAC (CONJUNCTS th))))) THEN
  SUBGOAL_THEN `x2:A = x /\ img2:A = img'`
   (CONJUNCTS_THEN2 SUBST_ALL_TAC SUBST_ALL_TAC) THENL
   [ASM_MESON_TAC[EOPAIR_INJ]; ALL_TAC] THEN
  FIRST_ASSUM(MATCH_MP_TAC o MATCH_MP ZF_EXTENSIONALITY) THEN
  ASM_REWRITE_TAC[] THEN X_GEN_TAC `z:A` THEN DISCH_TAC THEN
  ASM_SIMP_TAC[]);;

let ECHECKTOWER_RESGRAPH = prove
 (`!D (E:A->A->bool) onebee aa.
      model D E ZF_AX /\ onebee IN D /\ eordinal D E aa
      ==> ?rc. rc IN D /\
               !pp. pp IN D
                    ==> (E pp rc <=>
                         ?b z. b IN D /\ z IN D /\ E b aa /\
                               echecktower D E onebee b z /\
                                 eopair D E b z pp)`,
  REPEAT STRIP_TAC THEN
  FIRST_ASSUM(X_CHOOSE_TAC `v0:num->A` o MATCH_MP VALUATION_EXISTS o
              MATCH_MP MODEL_NONEMPTY) THEN
  SUBGOAL_THEN `valuation D ((2 |-> (onebee:A)) v0)` ASSUME_TAC THENL
   [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
  SUBGOAL_THEN `((2 |-> (onebee:A)) v0) 2 = onebee` ASSUME_TAC THENL
   [REWRITE_TAC[VALMOD]; ALL_TAC] THEN
  SUBGOAL_THEN
   `!b z:A. erec D (E:A->A->bool) check_step_form
    ((2 |-> (onebee:A)) v0) b z <=>
            echecktower D E onebee b z`
  (LABEL_TAC "conv") THENL
   [ASM_MESON_TAC[ECHECKTOWER_EREC]; ALL_TAC] THEN
  SUBGOAL_THEN
   `?rc:A. erecres D (E:A->A->bool) check_step_form
    ((2 |-> (onebee:A)) v0) aa rc`
  STRIP_ASSUME_TAC THENL
   [MATCH_MP_TAC ERECRES_EXISTS THEN ASM_REWRITE_TAC[] THEN
    ASM_MESON_TAC[CHECKSTEP_QFUN; CHECKSTEP_QTOTAL];
    ALL_TAC] THEN
  SUBGOAL_THEN `(rc:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[erecres]; ALL_TAC] THEN
  EXISTS_TAC `rc:A` THEN ASM_REWRITE_TAC[] THEN
  X_GEN_TAC `pp:A` THEN DISCH_TAC THEN
  FIRST_ASSUM(MP_TAC o SPEC `pp:A` o CONJUNCT2 o
    GEN_REWRITE_RULE I [erecres]) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  USE_THEN "conv" (fun th -> REWRITE_TAC[th]));;

let goodf2check = new_definition
  `goodf2check =
     ?? 87 (apply_form 81 0 87 &&
       !!- 86 0 (?? 90 (apply_form 81 86 90 && subset_form 90 87)))`;;

let HOLDS_GOODF2CHECK = prove
 (`!D (E:A->A->bool) v.
     valuation D v
     ==> (holds D E v goodf2check <=>
          ?zb. zb IN D /\
               eapply D E (v 81) (v 0) zb /\
               !c. c IN D /\ E c (v 0)
                   ==> ?zc. zc IN D /\ eapply D E (v 81) c zc /\
                            esubset D E zc zb)`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `!x. (v:num->A) x IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[valuation]; ALL_TAC] THEN
  REWRITE_TAC[goodf2check; holds; HOLDS_EX; HOLDS_AND] THEN
  SIMP_TAC[HOLDS_FORALLMEM; ARITH_RULE `~(86 = 0)`] THEN
  REWRITE_TAC[holds; HOLDS_EX; HOLDS_AND] THEN
  ASM_REWRITE_TAC[VALMOD; ARITH_EQ] THEN
  SUBGOAL_THEN
   `!zb:A. zb IN D
      ==> (holds D E ((87 |-> zb) v) (apply_form 81 0 87) <=>
           eapply D E (v 81) (v 0) zb)`
  (LABEL_TAC "pileb") THENL
   [REPEAT GEN_TAC THEN STRIP_TAC THEN
    SUBGOAL_THEN `valuation D ((87 |-> (zb:A)) v)` ASSUME_TAC THENL
     [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
    ASM_SIMP_TAC[HOLDS_APPLY_FORM] THEN ASM_SIMP_TAC[VALMOD; ARITH_EQ];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!zb c zc:A. zb IN D /\ c IN D /\ zc IN D
      ==> (holds D E ((90 |-> zc)((86 |-> c)((87 |-> zb) v)))
             (apply_form 81 86 90) <=> eapply D E (v 81) c zc) /\
          (holds D E ((90 |-> zc)((86 |-> c)((87 |-> zb) v)))
             (subset_form 90 87) <=> esubset D E zc zb)`
  (LABEL_TAC "pilec") THENL
   [REPEAT GEN_TAC THEN STRIP_TAC THEN
    SUBGOAL_THEN `valuation D ((90 |-> (zc:A))((86 |-> c)((87 |-> zb) v)))`
    ASSUME_TAC THENL [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
    ASM_SIMP_TAC[HOLDS_APPLY_FORM; HOLDS_SUBSET_FORM] THEN
    ASM_SIMP_TAC[VALMOD; ARITH_EQ]; ALL_TAC] THEN
  MATCH_MP_TAC(MESON[]
    `(!s:A. s IN D ==> (P s <=> Q s)) ==>
     ((?s. s IN D /\ P s) <=> (?s. s IN D /\ Q s))`) THEN
  X_GEN_TAC `zb:A` THEN DISCH_TAC THEN
