let GOODF2CHECK_SEM = prove
 (`!D (E:A->A->bool) onebee sa rc v0 b.
      model D E ZF_AX /\ onebee IN D /\ eordinal D E sa /\
      rc IN D /\ valuation D v0 /\
      (!pp. pp IN D
            ==> (E pp rc <=>
                 ?b' z'. b' IN D /\ z' IN D /\ E b' sa /\
                         echecktower D E onebee b' z' /\
                           eopair D E b' z' pp)) /\
      b IN D /\ E b sa
      ==> (holds D E ((0 |-> b) ((81 |-> rc) v0)) goodf2check <=>
           !c zc zb.
              c IN D /\ zc IN D /\ zb IN D /\
              E c b /\ echecktower D E onebee c zc /\
                echecktower D E onebee b zb
              ==> esubset D E zc zb)`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "zf onebeeD ordsa rcD valv0 rcc bD bsa" THEN
  SUBGOAL_THEN `eordinal D (E:A->A->bool) b` ASSUME_TAC THENL
   [ASM_MESON_TAC[EORDINAL_MEMBER]; ALL_TAC] THEN
  SUBGOAL_THEN `valuation D ((0 |-> (b:A)) ((81 |-> (rc:A)) v0))`
  ASSUME_TAC THENL [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;
    `(0 |-> (b:A)) ((81 |-> (rc:A)) v0)`] HOLDS_GOODF2CHECK) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  REWRITE_TAC[VALMOD; ARITH_EQ] THEN
  EQ_TAC THENL
   [DISCH_THEN(X_CHOOSE_THEN `zb0:A` (CONJUNCTS_THEN2 ASSUME_TAC
      (CONJUNCTS_THEN2 ASSUME_TAC (LABEL_TAC "allc")))) THEN
    SUBGOAL_THEN `echecktower D (E:A->A->bool) onebee b zb0` ASSUME_TAC THENL
     [MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;
        `echecktower D (E:A->A->bool) onebee`;`sa:A`;`rc:A`;`b:A`;`zb0:A`]
        EGRAPH_APPLY) THEN
