        (ASSUME `eapply D (E:A->A->bool) rc b zb0`))) THEN
      DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC ACCEPT_TAC);
      ALL_TAC] THEN
    MAP_EVERY X_GEN_TAC [`c:A`;`zc:A`;`zb:A`] THEN STRIP_TAC THEN
