let ECHECK_GACC_MONO = prove
 (`!D (E:A->A->bool) onebee c d gaccc gaccd u.
    model D E ZF_AX /\ eordinal D E d /\ c IN D /\ E c d /\
    gaccc IN D /\ gaccd IN D /\ u IN D /\
    (!t. t IN D
         ==> (E t gaccc <=>
              ?e z. e IN D /\ z IN D /\ E e c /\
                    echecktower D E onebee e z /\ E t z)) /\
    (!t. t IN D
         ==> (E t gaccd <=>
              ?e z. e IN D /\ z IN D /\ E e d /\
                    echecktower D E onebee e z /\ E t z)) /\
    E u gaccc
    ==> E u gaccd`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "zf ordd cD cd gacccD gaccdD uD charc chard ugaccc" THEN
  USE_THEN "chard"
    (fun th -> REWRITE_TAC[MATCH_MP th (ASSUME `(u:A) IN D`)]) THEN
  USE_THEN "charc" (MP_TAC o C MATCH_MP (ASSUME `(u:A) IN D`)) THEN
  REWRITE_TAC[ASSUME `(E:A->A->bool) u gaccc`] THEN
  DISCH_THEN(X_CHOOSE_THEN `e:A` (X_CHOOSE_THEN `z:A` STRIP_ASSUME_TAC)) THEN
  MAP_EVERY EXISTS_TAC [`e:A`;`z:A`] THEN ASM_REWRITE_TAC[] THEN
  ASM_MESON_TAC[EORDINAL_TRANS_E]);;

let ECHECK_GACC_ISFUN = prove
 (`!D (E:A->A->bool) onebee d gaccd.
    model D E ZF_AX /\ onebee IN D /\ eordinal D E d /\ gaccd IN D /\
    (!t. t IN D
         ==> (E t gaccd <=>
              ?e z. e IN D /\ z IN D /\ E e d /\
                    echecktower D E onebee e z /\ E t z)) /\
    (!c c' zc zc'.
         c IN D /\ c' IN D /\ zc IN D /\ zc' IN D /\
         E c d /\ E c' d /\ E c c' /\
         echecktower D E onebee c zc /\ echecktower D E onebee c' zc'
         ==> esubset D E zc zc')
    ==> eisfun D E gaccd`,
