    DISCH_THEN(X_CHOOSE_THEN `e:A`
               (X_CHOOSE_THEN `ze:A` STRIP_ASSUME_TAC)) THEN
    USE_THEN "char" (MP_TAC o C MATCH_MP (ASSUME `(z':A) IN D`)) THEN
