       [ASM_MESON_TAC[ECHECKTOWER_UNIQUE]; ALL_TAC] THEN
      MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`onebee:A`;`e':A`;`ze':A`;
                    `u:A`;`w:A`;`w':A`;`z:A`;`z':A`] ECHECKTOWER_STAGE_SV) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC];
      SUBGOAL_THEN `(E:A->A->bool) z' ze` ASSUME_TAC THENL
       [USE_THEN "coh" (MP_TAC o SPECL [`e':A`;`e:A`;`ze':A`;`ze:A`]) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
        REWRITE_TAC[esubset] THEN ASM_MESON_TAC[]; ALL_TAC] THEN
      MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`onebee:A`;`e:A`;`ze:A`;
                    `u:A`;`w:A`;`w':A`;`z:A`;`z':A`] ECHECKTOWER_STAGE_SV) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC]]]);;

let ECHECKTOWER_COHERE_STEP = prove
 (`!D (E:A->A->bool) onebee d.
    model D E ZF_AX /\ onebee IN D /\ eordinal D E d /\
