      ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC]; ALL_TAC] THEN
    SUBGOAL_THEN `vy:A = vy'` SUBST_ALL_TAC THENL
     [MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`gaccd:A`;`y:A`;`vy:A`;`vy':A`]
        EAPPLY_UNIQUE) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC]; ALL_TAC] THEN
    FIRST_ASSUM ACCEPT_TAC]);;

let ECHECKTOWER_COHERE = prove
 (`!D (E:A->A->bool) onebee a c zc za.
      model D E ZF_AX /\ onebee IN D /\ eordinal D E a /\
      c IN D /\ zc IN D /\ za IN D /\
      E c a /\ echecktower D E onebee c zc /\ echecktower D E onebee a za
      ==> esubset D E zc za`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `(a:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[EORDINAL_IN]; ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`a:A`] ESUC_EXISTS) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_TAC `sa:A`) THEN
  SUBGOAL_THEN `(sa:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[ESUC_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `eordinal D (E:A->A->bool) sa` ASSUME_TAC THENL
   [ASM_MESON_TAC[EORDINAL_ESUC]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) a sa` ASSUME_TAC THENL
   [ASM_MESON_TAC[ESUC_MEMBER]; ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`onebee:A`;`sa:A`]
    ECHECKTOWER_RESGRAPH) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `rc:A` (CONJUNCTS_THEN2 ASSUME_TAC
    (LABEL_TAC "rcc"))) THEN
  FIRST_ASSUM(X_CHOOSE_TAC `v0:num->A` o MATCH_MP VALUATION_EXISTS o
              MATCH_MP MODEL_NONEMPTY) THEN
  SUBGOAL_THEN `valuation D ((81 |-> (rc:A)) v0)`
  ASSUME_TAC THENL [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
  SUBGOAL_THEN
   `!dd. dd IN D /\ E dd sa
         ==> holds D E ((0 |-> dd) ((81 |-> (rc:A)) v0)) goodf2check`
  (LABEL_TAC "good") THENL
   [GEN_TAC THEN STRIP_TAC THEN
    MATCH_MP_TAC(TAUT `(~p ==> F) ==> p`) THEN
    DISCH_THEN(LABEL_TAC "bad0") THEN
    SUBGOAL_THEN `eordinal D (E:A->A->bool) dd` ASSUME_TAC THENL
     [ASM_MESON_TAC[EORDINAL_MEMBER]; ALL_TAC] THEN
    MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`Not goodf2check`;
                  `(81 |-> (rc:A)) v0`;`dd:A`]
      EORDINAL_LEAST) THEN
    ASM_REWRITE_TAC[HOLDS_NOT] THEN
    DISCH_THEN(X_CHOOSE_THEN `d:A` (CONJUNCTS_THEN2 ASSUME_TAC
      (CONJUNCTS_THEN2 ASSUME_TAC (CONJUNCTS_THEN2 (LABEL_TAC "dbad")
        (LABEL_TAC "dmin"))))) THEN
    SUBGOAL_THEN `(d:A) IN D` ASSUME_TAC THENL
     [ASM_MESON_TAC[EORDINAL_IN]; ALL_TAC] THEN
    SUBGOAL_THEN `(E:A->A->bool) d sa` ASSUME_TAC THENL
     [MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`d:A`;`dd:A`]
        EORDINAL_TRICHOTOMY) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(REPEAT_TCL DISJ_CASES_THEN ASSUME_TAC) THENL
       [ASM_MESON_TAC[EORDINAL_TRANS_E];
        ASM_MESON_TAC[];
        USE_THEN "dmin" (MP_TAC o SPEC `dd:A`) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
        USE_THEN "bad0" (fun th -> REWRITE_TAC[th])];
      ALL_TAC] THEN
    SUBGOAL_THEN
     `!b'. b' IN D /\ E b' d
           ==> !c zc zb.
                  c IN D /\ zc IN D /\ zb IN D /\
                  E c b' /\ echecktower D (E:A->A->bool) onebee c zc /\
                  echecktower D E onebee b' zb
                  ==> esubset D E zc zb`
    ASSUME_TAC THENL
     [X_GEN_TAC `b':A` THEN STRIP_TAC THEN
      SUBGOAL_THEN `(E:A->A->bool) b' sa` ASSUME_TAC THENL
       [ASM_MESON_TAC[EORDINAL_TRANS_E]; ALL_TAC] THEN
      MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`onebee:A`;`sa:A`;`rc:A`;
                    `v0:num->A`;`b':A`] GOODF2CHECK_SEM) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(MP_TAC o fst o EQ_IMP_RULE) THEN
      ANTS_TAC THENL
       [USE_THEN "dmin" (MP_TAC o SPEC `b':A`) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC];
        DISCH_THEN ACCEPT_TAC];
      ALL_TAC] THEN
    SUBGOAL_THEN
     `holds D E ((0 |-> (d:A)) ((81 |-> (rc:A)) v0)) goodf2check`
    MP_TAC THENL
     [MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`onebee:A`;`sa:A`;`rc:A`;
                    `v0:num->A`;`d:A`] GOODF2CHECK_SEM) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
      MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`onebee:A`;`d:A`]
        ECHECKTOWER_COHERE_STEP) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC];
      USE_THEN "dbad" (fun th -> REWRITE_TAC[th])];
    ALL_TAC] THEN
  USE_THEN "good" (MP_TAC o SPEC `a:A`) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_TAC THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`onebee:A`;`sa:A`;`rc:A`;
                `v0:num->A`;`a:A`] GOODF2CHECK_SEM) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(MP_TAC o fst o EQ_IMP_RULE) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(MP_TAC o SPECL [`c:A`;`zc:A`;`za:A`]) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC]);;

let ECHECKTOWER_SV = prove
 (`!D (E:A->A->bool) onebee a b za zb x img img' pp pp'.
      model D E ZF_AX /\ onebee IN D /\
      eordinal D E a /\ eordinal D E b /\
      za IN D /\ zb IN D /\
      echecktower D E onebee a za /\ echecktower D E onebee b zb /\
      x IN D /\ img IN D /\ img' IN D /\ pp IN D /\ pp' IN D /\
      eopair D E x img pp /\ eopair D E x img' pp' /\
      E pp za /\ E pp' zb
      ==> img = img'`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `(a:A) IN D /\ (b:A) IN D` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[EORDINAL_IN]; ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`a:A`;`b:A`]
         EORDINAL_TRICHOTOMY) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(REPEAT_TCL DISJ_CASES_THEN ASSUME_TAC) THENL
   [MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`onebee:A`;`b:A`;`a:A`;
                  `za:A`;`zb:A`] ECHECKTOWER_COHERE) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    REWRITE_TAC[esubset] THEN DISCH_THEN(MP_TAC o SPEC `pp:A`) THEN
    ASM_REWRITE_TAC[] THEN DISCH_TAC THEN
    MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`onebee:A`;`b:A`;`zb:A`;
                  `x:A`;`img:A`;`img':A`;`pp:A`;`pp':A`]
      ECHECKTOWER_STAGE_SV) THEN
    ASM_REWRITE_TAC[];
    SUBGOAL_THEN `za:A = zb` SUBST_ALL_TAC THENL
     [ASM_MESON_TAC[ECHECKTOWER_UNIQUE]; ALL_TAC] THEN
    MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`onebee:A`;`b:A`;`zb:A`;
                  `x:A`;`img:A`;`img':A`;`pp:A`;`pp':A`]
      ECHECKTOWER_STAGE_SV) THEN
    ASM_REWRITE_TAC[];
    MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`onebee:A`;`a:A`;`b:A`;
                  `zb:A`;`za:A`] ECHECKTOWER_COHERE) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    REWRITE_TAC[esubset] THEN DISCH_THEN(MP_TAC o SPEC `pp':A`) THEN
    ASM_REWRITE_TAC[] THEN DISCH_TAC THEN
    MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`onebee:A`;`a:A`;`za:A`;
                  `x:A`;`img:A`;`img':A`;`pp:A`;`pp':A`]
      ECHECKTOWER_STAGE_SV) THEN
    ASM_REWRITE_TAC[]]);;

let echeck = new_definition
 `echeck D (E:A->A->bool) onebee x v <=>
    x IN D /\ v IN D /\
    ?a cd pp. a IN D /\ eordinal D E a /\ echecktower D E onebee a cd /\
              cd IN D /\ pp IN D /\ eopair D E x v pp /\ E pp cd`;;

let ECHECK_IMP = prove
 (`!D (E:A->A->bool) onebee x v. echeck D E onebee x v ==> x IN D /\ v IN D`,
  SIMP_TAC[echeck]);;

let ECHECK_STAGE = prove
 (`!D (E:A->A->bool) onebee a cd x v pp.
      model D E ZF_AX /\ onebee IN D /\ eordinal D E a /\ cd IN D /\
      echecktower D E onebee a cd /\
      x IN D /\ v IN D /\ pp IN D /\ eopair D E x v pp /\ E pp cd
      ==> echeck D E onebee x v`,
  REWRITE_TAC[echeck] THEN MESON_TAC[EORDINAL_IN]);;

let ECHECK_SV = prove
 (`!D (E:A->A->bool) onebee x v v'.
      model D E ZF_AX /\ onebee IN D /\
      echeck D E onebee x v /\ echeck D E onebee x v'
      ==> v = v'`,
  REPEAT GEN_TAC THEN REWRITE_TAC[echeck] THEN STRIP_TAC THEN
  ASM_MESON_TAC[ECHECKTOWER_SV]);;

(* ===================================================================== *)
(* F3d: STRUCTURE of the check-name x^.                                  *)
(* The recursion equation z IN x^ <=> ?y IN x. z = (y^,onebee), and its  *)
(* two immediate corollaries: x^ is single-valued (eisfun) and every     *)
(* value of x^ is onebee (ran x^ SUBSET {onebee}).  All non-inductive:    *)
(* pure consequences of ECHECKTOWER_VALUE + ECHECK_STAGE + ECHECK_SV.     *)
(* (Totality/exhaustion is deferred to a dedicated follow-up: an          *)
(* ELCARD-scale object-formula transfinite induction under the V=L        *)
(* hypothesis.  ECHECK_IS_BNAME is proved below, in increment #4.)        *)
(* ===================================================================== *)

(* Recursion equation:  z IN x^  <=>  ?y IN x. z = (y^, onebee).          *)
let ECHECK_MEM = prove
 (`!D (E:A->A->bool) onebee x v z.
     model D E ZF_AX /\ onebee IN D /\ echeck D E onebee x v /\ z IN D
     ==> (E z v <=>
          ?y vy. y IN D /\ vy IN D /\ E y x /\
                 echeck D E onebee y vy /\ eopair D E vy onebee z)`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "modl oneD chk zD" THEN
  USE_THEN "chk" (MP_TAC o REWRITE_RULE[echeck]) THEN
  DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "xD")
    (CONJUNCTS_THEN2 (LABEL_TAC "vD")
     (X_CHOOSE_THEN `a:A` (X_CHOOSE_THEN `cd:A` (X_CHOOSE_THEN `pp:A`
       (fun th -> MAP_EVERY ASSUME_TAC (CONJUNCTS th))))))) THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`onebee:A`;`a:A`;`cd:A`;`pp:A`]
        ECHECKTOWER_VALUE) THEN
  ASM_REWRITE_TAC[] THEN
  INTRO_TAC "@gacc w x2 img. gaccD wD x2D imgD gaccch domn pairx subxw \
             imgch" THEN
  SUBGOAL_THEN `x2:A = x /\ img:A = v`
    (CONJUNCTS_THEN2 SUBST_ALL_TAC SUBST_ALL_TAC) THENL
   [MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`x2:A`;`img:A`;`x:A`;`v:A`;`pp:A`]
      EOPAIR_INJ) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN
   `!yy vyy:A. yy IN D /\ vyy IN D /\ eapply D E gacc yy vyy
               ==> echeck D E onebee yy vyy`
  (LABEL_TAC "conn") THENL
   [MAP_EVERY X_GEN_TAC [`yy:A`;`vyy:A`] THEN STRIP_TAC THEN
    UNDISCH_TAC `eapply D (E:A->A->bool) gacc yy vyy` THEN
    REWRITE_TAC[eapply] THEN
    DISCH_THEN(X_CHOOSE_THEN `p:A`
      (CONJUNCTS_THEN2 (LABEL_TAC "pairp") (LABEL_TAC "pgacc"))) THEN
    SUBGOAL_THEN `(p:A) IN D` (LABEL_TAC "pD") THENL
     [ASM_MESON_TAC[EOPAIR_IN]; ALL_TAC] THEN
    USE_THEN "gaccch" (MP_TAC o C MATCH_MP (ASSUME `(p:A) IN D`)) THEN
    REWRITE_TAC[ASSUME `(E:A->A->bool) p gacc`] THEN
    DISCH_THEN(X_CHOOSE_THEN `b:A`
               (X_CHOOSE_THEN `zz:A` STRIP_ASSUME_TAC)) THEN
    MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`onebee:A`;`b:A`;`zz:A`;
                   `yy:A`;`vyy:A`;`p:A`] ECHECK_STAGE) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[EORDINAL_MEMBER]; ALL_TAC] THEN
    DISCH_THEN ACCEPT_TAC; ALL_TAC] THEN
  SUBGOAL_THEN
   `!yy:A. yy IN D /\ E yy x ==> ?vyy. vyy IN D /\ eapply D E gacc yy vyy`
  (LABEL_TAC "dom") THENL
   [X_GEN_TAC `yy:A` THEN STRIP_TAC THEN
    SUBGOAL_THEN `(E:A->A->bool) yy w` ASSUME_TAC THENL
     [UNDISCH_TAC `esubset D (E:A->A->bool) x w` THEN REWRITE_TAC[esubset] THEN
      DISCH_THEN MATCH_MP_TAC THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    USE_THEN "domn" (fun th ->
      MP_TAC(SPEC `yy:A` (CONJUNCT2 (REWRITE_RULE[edomain] th)))) THEN
    ASM_REWRITE_TAC[eindom]; ALL_TAC] THEN
  USE_THEN "imgch" (MP_TAC o C MATCH_MP (ASSUME `(z:A) IN D`)) THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  EQ_TAC THENL
   [DISCH_THEN(X_CHOOSE_THEN `y:A` (CONJUNCTS_THEN2 (LABEL_TAC "yD")
      (X_CHOOSE_THEN `vy:A`
       (fun th -> MAP_EVERY ASSUME_TAC (CONJUNCTS th))))) THEN
    ASM_MESON_TAC[];
    DISCH_THEN(X_CHOOSE_THEN `y:A` (X_CHOOSE_THEN `vy:A`
      (fun th -> MAP_EVERY ASSUME_TAC (CONJUNCTS th)))) THEN
    USE_THEN "dom" (MP_TAC o SPEC `y:A`) THEN ANTS_TAC THENL
     [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(X_CHOOSE_THEN `vy':A`
      (CONJUNCTS_THEN2 (LABEL_TAC "vy'D") (LABEL_TAC "app"))) THEN
    SUBGOAL_THEN `vy':A = vy` SUBST_ALL_TAC THENL
     [MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`onebee:A`;`y:A`;`vy':A`;`vy:A`]
        ECHECK_SV) THEN ANTS_TAC THENL
       [ASM_REWRITE_TAC[] THEN USE_THEN "conn" MATCH_MP_TAC THEN
        ASM_REWRITE_TAC[];
        DISCH_THEN ACCEPT_TAC]; ALL_TAC] THEN
    ASM_MESON_TAC[]]);;

(* x^ is single-valued: it is a set of pairs (name, onebee), so functional. *)
let ECHECK_ISFUN = prove
 (`!D (E:A->A->bool) onebee x v.
     model D E ZF_AX /\ onebee IN D /\ echeck D E onebee x v
     ==> eisfun D E v`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `(v:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[ECHECK_IMP]; ALL_TAC] THEN
  REWRITE_TAC[eisfun] THEN ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
   [X_GEN_TAC `z:A` THEN STRIP_TAC THEN
    MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`onebee:A`;`x:A`;`v:A`;`z:A`]
      ECHECK_MEM) THEN
    ASM_REWRITE_TAC[] THEN
    DISCH_THEN(X_CHOOSE_THEN `y:A`
               (X_CHOOSE_THEN `vy:A` STRIP_ASSUME_TAC)) THEN
    MAP_EVERY EXISTS_TAC [`vy:A`;`onebee:A`] THEN ASM_REWRITE_TAC[];
    MAP_EVERY X_GEN_TAC [`u:A`;`ww:A`;`ww':A`;`z:A`;`z':A`] THEN STRIP_TAC THEN
    SUBGOAL_THEN `(z:A) IN D /\ (z':A) IN D` STRIP_ASSUME_TAC THENL
     [ASM_MESON_TAC[EOPAIR_IN]; ALL_TAC] THEN
    MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`onebee:A`;`x:A`;`v:A`;`z:A`]
      ECHECK_MEM) THEN
    ASM_REWRITE_TAC[] THEN
    DISCH_THEN(X_CHOOSE_THEN `y:A`
               (X_CHOOSE_THEN `vy:A` STRIP_ASSUME_TAC)) THEN
    MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`onebee:A`;`x:A`;`v:A`;`z':A`]
      ECHECK_MEM) THEN
    ASM_REWRITE_TAC[] THEN
    DISCH_THEN(X_CHOOSE_THEN `y':A`
               (X_CHOOSE_THEN `vy':A` STRIP_ASSUME_TAC)) THEN
    SUBGOAL_THEN `ww:A = onebee /\ ww':A = onebee`
      (fun th -> REWRITE_TAC[CONJUNCT1 th; CONJUNCT2 th]) THEN
    CONJ_TAC THENL
     [MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`u:A`;`ww:A`;`vy:A`;`onebee:A`;
                    `z:A`] EOPAIR_INJ) THEN ASM_REWRITE_TAC[] THEN
      DISCH_THEN(ACCEPT_TAC o CONJUNCT2);
      MP_TAC(SPECL
             [`D:A->bool`;`E:A->A->bool`;`u:A`;`ww':A`;`vy':A`;`onebee:A`;
              `z':A`] EOPAIR_INJ) THEN ASM_REWRITE_TAC[] THEN
      DISCH_THEN(ACCEPT_TAC o CONJUNCT2)]]);;

(* ===================================================================== *)
(* F3d: REDUCTION of "x^ is a B-name" to a bounding                       *)
(* step.  Non-inductive "landing" lemmas: given that the domain elements  *)
(* of x^ already sit at B-name stages below some ordinal a, x^ itself is  *)
(* a B-name at stage a.  (The remaining inductive core -- BNAME_BOUND and *)
(* the recursion "each y^ is a B-name" -- needs object-formula            *)
(* internalisation of the towers and is deferred.)                        *)
(* ===================================================================== *)

(* If every member u of dom(x^) (i.e. every first coordinate of a member  *)
(* of x^) lands in a fixed set w, then x^ = v is a B-name-member at w:     *)
(* eisfun (ECHECK_ISFUN) + v SUBSET (w x B) (each member is a pair         *)
(* (y^, onebee) with y^ in w and onebee in B).                            *)
let ECHECK_EBNMEM = prove
 (`!D (E:A->A->bool) B onebee x v w.
     model D E ZF_AX /\ B IN D /\ onebee IN D /\ E onebee B /\
     echeck D E onebee x v /\ w IN D /\
     (!u ww z. u IN D /\ ww IN D /\ eopair D E u ww z /\ E z v ==> E u w)
     ==> ebnmem D E B w v`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `(v:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[ECHECK_IMP]; ALL_TAC] THEN
  REWRITE_TAC[ebnmem] THEN CONJ_TAC THENL
   [ASM_MESON_TAC[ECHECK_ISFUN]; ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`w:A`;`B:A`] ECROSS_EXISTS) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `cr:A` (LABEL_TAC "cross")) THEN
  EXISTS_TAC `cr:A` THEN
  SUBGOAL_THEN `(cr:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[ecross]; ALL_TAC] THEN
  ASM_REWRITE_TAC[esubset] THEN
  X_GEN_TAC `z:A` THEN STRIP_TAC THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`onebee:A`;`x:A`;`v:A`;`z:A`]
        ECHECK_MEM) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `y:A` (X_CHOOSE_THEN `vy:A` STRIP_ASSUME_TAC)) THEN
  SUBGOAL_THEN `(vy:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[ECHECK_IMP]; ALL_TAC] THEN
  USE_THEN "cross"
    (MP_TAC o SPEC `z:A` o CONJUNCT2 o REWRITE_RULE[ecross]) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  MAP_EVERY EXISTS_TAC [`vy:A`;`onebee:A`] THEN
  ASM_REWRITE_TAC[] THEN
  ASM_MESON_TAC[]);;

(* If every domain element of x^ sits at a B-name stage strictly below a,  *)
(* then x^ = v lies in the a-th B-name stage ya.                           *)
let ECHECK_BNAME_STEP = prove
 (`!D (E:A->A->bool) B onebee x v a ya.
     model D E ZF_AX /\ B IN D /\ onebee IN D /\ E onebee B /\
     eordinal D E a /\ ya IN D /\ ebnstage D E B a ya /\
     echeck D E onebee x v /\
     (!u ww z. u IN D /\ ww IN D /\ eopair D E u ww z /\ E z v
               ==> ?b yb. b IN D /\ E b a /\ yb IN D /\
                          ebnstage D E B b yb /\ E u yb)
     ==> E v ya`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `(v:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[ECHECK_IMP]; ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`a:A`;`ya:A`]
         EBNSTAGE_CHAR) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `w:A` (CONJUNCTS_THEN2 (LABEL_TAC "wD")
    (CONJUNCTS_THEN2 (LABEL_TAC "wchar") (LABEL_TAC "funs")))) THEN
  SUBGOAL_THEN `ebnmem D (E:A->A->bool) B w v` ASSUME_TAC THENL
   [MATCH_MP_TAC ECHECK_EBNMEM THEN
    MAP_EVERY EXISTS_TAC [`onebee:A`;`x:A`] THEN
    ASM_REWRITE_TAC[] THEN
    REPEAT STRIP_TAC THEN ASM_MESON_TAC[]; ALL_TAC] THEN
  USE_THEN "funs" (fun th ->
    MP_TAC(SPEC `v:A` (CONJUNCT2 (REWRITE_RULE[ebnfuns] th)))) THEN
  ASM_REWRITE_TAC[]);;

(* Consequently x^ = v is a B-name (bname D E B v).                        *)
let ECHECK_BNAME_SUCC = prove
 (`!D (E:A->A->bool) B onebee x v a ya.
     model D E ZF_AX /\ B IN D /\ onebee IN D /\ E onebee B /\
     eordinal D E a /\ ya IN D /\ ebnstage D E B a ya /\
     echeck D E onebee x v /\
     (!u ww z. u IN D /\ ww IN D /\ eopair D E u ww z /\ E z v
               ==> ?b yb. b IN D /\ E b a /\ yb IN D /\
                          ebnstage D E B b yb /\ E u yb)
     ==> bname D E B v`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `(E:A->A->bool) v ya` ASSUME_TAC THENL
   [MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`onebee:A`;`x:A`;`v:A`;
                  `a:A`;`ya:A`] ECHECK_BNAME_STEP) THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  ASM_MESON_TAC[BNAME_STAGE; EORDINAL_IN]);;

(* Every domain element of x^ is the check-name of some element of x.      *)
(* (Bridges the recursion IH "each y^ is a B-name" to "dom(x^) is a set    *)
(* of B-names" for the eventual bounding step.)                            *)
let ECHECK_DOM_ELT = prove
 (`!D (E:A->A->bool) onebee x v u.
     model D E ZF_AX /\ onebee IN D /\ echeck D E onebee x v /\
     u IN D /\ eindom D E v u
     ==> ?y. y IN D /\ E y x /\ echeck D E onebee y u`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  UNDISCH_TAC `eindom D (E:A->A->bool) v u` THEN REWRITE_TAC[eindom] THEN
  DISCH_THEN(X_CHOOSE_THEN `ww:A` (CONJUNCTS_THEN2 (LABEL_TAC "wwD")
    (LABEL_TAC "app"))) THEN
  UNDISCH_TAC `eapply D (E:A->A->bool) v u ww` THEN REWRITE_TAC[eapply] THEN
  DISCH_THEN(X_CHOOSE_THEN `z:A` (CONJUNCTS_THEN2 (LABEL_TAC "pr")
    (LABEL_TAC "ez"))) THEN
  SUBGOAL_THEN `(z:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[EOPAIR_IN]; ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`onebee:A`;`x:A`;`v:A`;`z:A`]
        ECHECK_MEM) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `y:A` (X_CHOOSE_THEN `vy:A` STRIP_ASSUME_TAC)) THEN
  SUBGOAL_THEN `(vy:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[ECHECK_IMP]; ALL_TAC] THEN
  SUBGOAL_THEN `u:A = vy` ASSUME_TAC THENL
   [MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`u:A`;`ww:A`;`vy:A`;`onebee:A`;
                  `z:A`] EOPAIR_INJ) THEN
    ASM_REWRITE_TAC[] THEN DISCH_THEN(ACCEPT_TAC o CONJUNCT1); ALL_TAC] THEN
  EXISTS_TAC `y:A` THEN ASM_MESON_TAC[]);;

(* ===================================================================== *)
(* F3d: BNAME_BOUND -- the B-name analogue of                             *)
(* ELMEM_BOUND.  A D-set all of whose members are B-names has a           *)
(* common bounding B-name stage.  Built via a bespoke high-slot           *)
(* recursion-application wrapper recapp3_form (binds slots 3,4, leaving   *)
(* the B-parameter at slot 2 untouched -- the generic recapp_form would   *)
(* capture it), then bnrank_form (rank in the B-name tower) and the       *)
(* replacement+union assembly, mirroring rank_form/ELMEM_RANK/ELMEM_BOUND *)
(* verbatim with elstage -> ebnstage and B threaded at slot 2.            *)
(* ===================================================================== *)

(* High-slot recursion-application wrapper: binds slots 3,4 (the argument *)
(* /value slots of rec_form _ 3), NOT 2,3 -- so B at slot 2 is preserved. *)
(* Mirror of recapp6_form/HOLDS_RECAPP6_FORM.                              *)
let recapp3_form = new_definition
  `recapp3_form q i j = !! 3 (!! 4 ((Eq 3 i && Eq 4 j) --> q))`;;

let HOLDS_RECAPP3_FORM = prove
 (`!D (E:A->A->bool) v q i j.
        valuation D v /\ ~(i = 3) /\ ~(i = 4) /\ ~(j = 3) /\
        ~(j = 4)
        ==> (holds D E v (recapp3_form q i j) <=>
             holds D E ((4 |-> v j) ((3 |-> v i) v)) q)`,
  REPEAT STRIP_TAC THEN
  REWRITE_TAC[recapp3_form; holds; HOLDS_AND] THEN
  ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER; ARITH_RULE `~(3 = 4)`] THEN
  SUBGOAL_THEN `!x. (v:num->A) x IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[valuation]; ALL_TAC] THEN
  EQ_TAC THENL
   [DISCH_THEN(MP_TAC o SPEC `(v:num->A) i`) THEN ASM_SIMP_TAC[] THEN
    DISCH_THEN(MP_TAC o SPEC `(v:num->A) j`) THEN ASM_SIMP_TAC[];
    MESON_TAC[]]);;

(* Bridge to the B-name tower: recapp3 of the bname recursion at slots i,j *)
(* is exactly ebnstage at (v 2 = B) (v i) (v j).  Mirror HOLDS_RECAPP_LSTEP *)
(* (ELSTAGE_EREC -> EBNSTAGE_EREC, which threads B at slot 2).             *)
let HOLDS_RECAPP3_BNSTEP = prove
 (`!D (E:A->A->bool) v i j.
        model D E ZF_AX /\ valuation D v /\
        ~(i = 3) /\ ~(i = 4) /\ ~(j = 3) /\ ~(j = 4)
        ==> (holds D E v (recapp3_form (rec_form bname_step_form 3) i j) <=>
             ebnstage D E (v 2) (v i) (v j))`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `!x. (v:num->A) x IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[valuation]; ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `v:num->A`;
                `rec_form bname_step_form 3`; `i:num`; `j:num`]
        HOLDS_RECAPP3_FORM) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `v:num->A`;
                `bname_step_form`; `3`; `(v:num->A) i`; `(v:num->A) j`]
        HOLDS_REC_FORM) THEN
  ASM_REWRITE_TAC[FVLT_BNAME_STEP_FORM; ARITH_RULE `1 < 3`;
                  ARITH_RULE `3 + 1 = 4`] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `(v:num->A) 2`;
                `(v:num->A) i`; `(v:num->A) j`; `v:num->A`]
        EBNSTAGE_EREC) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]));;

(* "element (v 1) is in the B-name stage (v 0)".  Mirror instage_form.       *)
let instage_bn_form = new_definition
  `instage_bn_form = ?? 11 (recapp3_form (rec_form bname_step_form 3) 0 11 &&
                            1 %% 11)`;;

let HOLDS_INSTAGE_BN_FORM = prove
 (`!D (E:A->A->bool) v.
        model D E ZF_AX /\ valuation D v
        ==> (holds D E v instage_bn_form <=>
             ?y. y IN D /\ ebnstage D E (v 2) (v 0) y /\ E (v 1) y)`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `!x. (v:num->A) x IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[valuation]; ALL_TAC] THEN
  REWRITE_TAC[instage_bn_form; HOLDS_EX; HOLDS_AND; holds] THEN
  SUBGOAL_THEN
   `!y:A. y IN D
      ==> (holds D E ((11 |-> y) v)
             (recapp3_form (rec_form bname_step_form 3) 0 11) <=>
           ebnstage D E (v 2) (v 0) y)`
  ASSUME_TAC THENL
   [X_GEN_TAC `y:A` THEN DISCH_TAC THEN
    SUBGOAL_THEN `valuation D ((11 |-> (y:A)) v)` ASSUME_TAC THENL
     [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `(11 |-> (y:A)) v`;
                  `0`; `11`] HOLDS_RECAPP3_BNSTEP) THEN
    ASM_REWRITE_TAC[ARITH_RULE
      `~(0 = 3) /\ ~(0 = 4) /\ ~(11 = 3) /\ ~(11 = 4)`] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    REWRITE_TAC[VALMOD; ARITH_EQ];
    ALL_TAC] THEN
  REWRITE_TAC[VALMOD; ARITH_EQ] THEN ASM_MESON_TAC[]);;

(* Rank in the B-name tower: v 1 is the least stage-index whose B-name     *)
(* stage contains v 0.  Mirror rank_form/HOLDS_RANK_FORM; witness          *)
(* slots 4,5,6 relocated to 11,12,13 (4 is now the rec value slot).        *)
let bnrank_form = new_definition
  `bnrank_form = ordinal_form 1 &&
                 (?? 11 (recapp3_form (rec_form bname_step_form 3) 1 11 &&
                         0 %% 11)) &&
                 (!!- 12 1 (Not(?? 13
                                (recapp3_form (rec_form bname_step_form 3)
                                 12 13 && 0 %% 13))))`;;

let HOLDS_BNRANK_FORM = prove
 (`!D (E:A->A->bool) v.
        model D E ZF_AX /\ valuation D v
        ==> (holds D E v bnrank_form <=>
             eordinal D E (v 1) /\
             (?y. y IN D /\ ebnstage D E (v 2) (v 1) y /\ E (v 0) y) /\
             (!c. c IN D /\ E c (v 1)
                  ==> ~(?y. y IN D /\ ebnstage D E (v 2) c y /\ E (v 0) y)))`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `!x. (v:num->A) x IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[valuation]; ALL_TAC] THEN
  REWRITE_TAC[bnrank_form] THEN
  SIMP_TAC[HOLDS_AND; HOLDS_EX; HOLDS_NOT; HOLDS_FORALLMEM;
           ARITH_RULE `~(12 = 1)`] THEN
  ASM_SIMP_TAC[HOLDS_ORDINAL_FORM] THEN
  REWRITE_TAC[holds] THEN
  SUBGOAL_THEN
   `!y:A. y IN D
      ==> (holds D E ((11 |-> y) v)
             (recapp3_form (rec_form bname_step_form 3) 1 11) <=>
           ebnstage D E (v 2) (v 1) y)`
  ASSUME_TAC THENL
   [X_GEN_TAC `y:A` THEN DISCH_TAC THEN
    SUBGOAL_THEN `valuation D ((11 |-> (y:A)) v)` ASSUME_TAC THENL
     [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `(11 |-> (y:A)) v`;
                  `1`; `11`] HOLDS_RECAPP3_BNSTEP) THEN
    ASM_REWRITE_TAC[ARITH_RULE
      `~(1 = 3) /\ ~(1 = 4) /\ ~(11 = 3) /\ ~(11 = 4)`] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    REWRITE_TAC[VALMOD; ARITH_EQ];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!c y:A. c IN D /\ y IN D
      ==> (holds D E ((13 |-> y) ((12 |-> c) v))
             (recapp3_form (rec_form bname_step_form 3) 12 13) <=>
           ebnstage D E (v 2) c y)`
  ASSUME_TAC THENL
   [REPEAT GEN_TAC THEN STRIP_TAC THEN
    SUBGOAL_THEN `valuation D ((13 |-> (y:A)) ((12 |-> (c:A)) v))`
    ASSUME_TAC THENL
     [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
                  `(13 |-> (y:A)) ((12 |-> (c:A)) v)`;
                  `12`; `13`] HOLDS_RECAPP3_BNSTEP) THEN
    ASM_REWRITE_TAC[ARITH_RULE
      `~(12 = 3) /\ ~(12 = 4) /\ ~(13 = 3) /\ ~(13 = 4)`] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    REWRITE_TAC[VALMOD; ARITH_EQ];
    ALL_TAC] THEN
  REWRITE_TAC[VALMOD; ARITH_EQ] THEN ASM_MESON_TAC[]);;

(* Every B-name has a (least) B-name-tower rank.  Mirror ELMEM_RANK;        *)
(* valuation carries B at slot 2 (vB = (2|->B)v0) so instage_bn/bnrank read *)
(* B correctly.                                                             *)
let BNAME_RANK = prove
 (`!D (E:A->A->bool) B x.
        model D E ZF_AX /\ B IN D /\ bname D E B x /\ x IN D
        ==> ?a. a IN D /\ eordinal D E a /\
                (?y. y IN D /\ ebnstage D E B a y /\ E x y) /\
                (!c. c IN D /\ E c a
                     ==> ~(?y. y IN D /\ ebnstage D E B c y /\ E x y))`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  FIRST_ASSUM(MP_TAC o GEN_REWRITE_RULE I [bname]) THEN
  DISCH_THEN(X_CHOOSE_THEN `a0:A` (X_CHOOSE_THEN `y0:A`
    (fun th -> MAP_EVERY ASSUME_TAC (CONJUNCTS th)))) THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `a0:A`] ESUC_EXISTS) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_TAC `sa0:A`) THEN
  SUBGOAL_THEN `(sa0:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[ESUC_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `eordinal D (E:A->A->bool) sa0` ASSUME_TAC THENL
   [ASM_MESON_TAC[EORDINAL_ESUC]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) a0 sa0` ASSUME_TAC THENL
   [ASM_MESON_TAC[ESUC_MEMBER]; ALL_TAC] THEN
  SUBGOAL_THEN `?v0:num->A. valuation D v0` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[VALUATION_EXISTS; MODEL_NONEMPTY]; ALL_TAC] THEN
  ABBREV_TAC `vB = (2 |-> (B:A)) v0` THEN
  SUBGOAL_THEN `valuation D (vB:num->A) /\ (vB:num->A) 2 = B`
  STRIP_ASSUME_TAC THENL
   [EXPAND_TAC "vB" THEN ASM_SIMP_TAC[VALUATION_VALMOD; VALMOD]; ALL_TAC] THEN
  SUBGOAL_THEN `valuation D ((1 |-> (x:A)) vB)` ASSUME_TAC THENL
   [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`] ZF_SEPARATION) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(MP_TAC o SPECL
    [`instage_bn_form`; `0`; `(1 |-> (x:A)) vB`; `sa0:A`]) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `ss:A` (CONJUNCTS_THEN2 ASSUME_TAC
    (LABEL_TAC "sch"))) THEN
  SUBGOAL_THEN
   `!t:A. t IN D
      ==> ((E:A->A->bool) t ss <=>
           E t sa0 /\ ?y. y IN D /\ ebnstage D E B t y /\ E x y)`
  (LABEL_TAC "sch2") THENL
   [X_GEN_TAC `t:A` THEN DISCH_TAC THEN
    USE_THEN "sch" (MP_TAC o SPEC `t:A`) THEN ANTS_TAC THENL
     [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
                  `(0 |-> (t:A)) ((1 |-> (x:A)) vB)`]
          HOLDS_INSTAGE_BN_FORM) THEN
    ANTS_TAC THENL
     [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    ASM_REWRITE_TAC[VALMOD; ARITH_EQ];
    ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`] ZF_FOUNDATION) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(MP_TAC o SPEC `ss:A`) THEN ANTS_TAC THENL
   [ASM_REWRITE_TAC[] THEN EXISTS_TAC `a0:A` THEN
    SUBGOAL_THEN `(a0:A) IN D` ASSUME_TAC THENL
     [ASM_MESON_TAC[EORDINAL_IN]; ALL_TAC] THEN
    ASM_REWRITE_TAC[] THEN
    USE_THEN "sch2" (MP_TAC o SPEC `a0:A`) THEN ANTS_TAC THENL
     [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[];
    ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `a:A` (CONJUNCTS_THEN2 ASSUME_TAC
    (CONJUNCTS_THEN2 ASSUME_TAC (LABEL_TAC "min")))) THEN
  SUBGOAL_THEN
   `(E:A->A->bool) a sa0 /\ ?y. y IN D /\ ebnstage D E B a y /\ E x y`
  STRIP_ASSUME_TAC THENL
   [USE_THEN "sch2" (MP_TAC o SPEC `a:A`) THEN ANTS_TAC THENL
     [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> MP_TAC(fst(EQ_IMP_RULE th))) THEN
    DISCH_THEN MATCH_MP_TAC THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  EXISTS_TAC `a:A` THEN ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
   [ASM_MESON_TAC[EORDINAL_MEMBER]; ALL_TAC] THEN
  CONJ_TAC THENL [ASM_MESON_TAC[]; ALL_TAC] THEN
  X_GEN_TAC `c:A` THEN STRIP_TAC THEN
  SUBGOAL_THEN `(E:A->A->bool) c sa0` ASSUME_TAC THENL
   [ASM_MESON_TAC[eordinal; etransitive; esubset]; ALL_TAC] THEN
  USE_THEN "min" (MP_TAC o SPEC `c:A`) THEN ASM_REWRITE_TAC[] THEN
  DISCH_TAC THEN
  USE_THEN "sch2" (MP_TAC o SPEC `c:A`) THEN ANTS_TAC THENL
   [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_TAC THEN ASM_MESON_TAC[]);;

(* Rank is unique.  Mirror ELMEM_RANK_UNIQUE verbatim.                     *)
let BNAME_RANK_UNIQUE = prove
 (`!D (E:A->A->bool) B x a a'.
        model D E ZF_AX /\
        eordinal D E a /\
        (?y. y IN D /\ ebnstage D E B a y /\ E x y) /\
        (!c. c IN D /\ E c a
             ==> ~(?y. y IN D /\ ebnstage D E B c y /\ E x y)) /\
        eordinal D E a' /\
        (?y. y IN D /\ ebnstage D E B a' y /\ E x y) /\
        (!c. c IN D /\ E c a'
             ==> ~(?y. y IN D /\ ebnstage D E B c y /\ E x y))
        ==> a = a'`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `a:A`; `a':A`]
        EORDINAL_TRICHOTOMY) THEN
  ASM_REWRITE_TAC[] THEN STRIP_TAC THEN ASM_REWRITE_TAC[] THEN
  ASM_MESON_TAC[EORDINAL_IN]);;

(* BNAME_BOUND: a D-set all of whose members are B-names has a common      *)
(* bounding B-name stage.  Mirror ELMEM_BOUND: rank function               *)
(* (REPLACEMENT along bnrank_form) -> union of ranks -> its stage          *)
(* (EBNSTAGE_EXISTS) -> EBNSTAGE_MONO places every element there.          *)
let BNAME_BOUND = prove
 (`!D (E:A->A->bool) B pl.
        model D E ZF_AX /\ B IN D /\ pl IN D /\
        (!z. z IN D /\ E z pl ==> bname D E B z)
        ==> ?c yc. c IN D /\ yc IN D /\ eordinal D E c /\
                   ebnstage D E B c yc /\
                   !z. z IN D /\ E z pl ==> E z yc`,
  REPEAT GEN_TAC THEN INTRO_TAC "zf BD plD allc" THEN
  SUBGOAL_THEN `?v0:num->A. valuation D v0` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[VALUATION_EXISTS; MODEL_NONEMPTY]; ALL_TAC] THEN
  ABBREV_TAC `vB = (2 |-> (B:A)) v0` THEN
  SUBGOAL_THEN `valuation D (vB:num->A) /\ (vB:num->A) 2 = B`
  STRIP_ASSUME_TAC THENL
   [EXPAND_TAC "vB" THEN ASM_SIMP_TAC[VALUATION_VALMOD; VALMOD]; ALL_TAC] THEN
  SUBGOAL_THEN
   `!z w:A. z IN D /\ w IN D
        ==> (holds D E ((1 |-> w) ((0 |-> z) vB)) bnrank_form <=>
             eordinal D E w /\
             (?y. y IN D /\ ebnstage D E B w y /\ E z y) /\
             (!c. c IN D /\ E c w
                  ==> ~(?y. y IN D /\ ebnstage D E B c y /\ E z y)))`
  (LABEL_TAC "hrk") THENL
   [REPEAT GEN_TAC THEN STRIP_TAC THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
                  `(1 |-> (w:A)) ((0 |-> (z:A)) vB)`]
          HOLDS_BNRANK_FORM) THEN
    ANTS_TAC THENL
     [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    ASM_REWRITE_TAC[VALMOD; ARITH_EQ];
    ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`] ZF_REPLACEMENT) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(MP_TAC o SPECL
    [`bnrank_form`; `0`; `1`; `vB:num->A`; `pl:A`]) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[ARITH_EQ] THEN
    X_GEN_TAC `z:A` THEN STRIP_TAC THEN
    SUBGOAL_THEN `bname D (E:A->A->bool) B z` ASSUME_TAC THENL
     [ASM_MESON_TAC[]; ALL_TAC] THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `B:A`; `z:A`] BNAME_RANK) THEN
    ASM_REWRITE_TAC[] THEN
    DISCH_THEN(X_CHOOSE_THEN `a:A` (fun th ->
      MAP_EVERY ASSUME_TAC (CONJUNCTS th))) THEN
    EXISTS_TAC `a:A` THEN ASM_REWRITE_TAC[] THEN
    X_GEN_TAC `w':A` THEN STRIP_TAC THEN
    SUBGOAL_THEN
     `eordinal D (E:A->A->bool) w' /\
      (?y. y IN D /\ ebnstage D E B w' y /\ E z y) /\
      (!c. c IN D /\ E c w'
           ==> ~(?y. y IN D /\ ebnstage D E B c y /\ E z y))`
    STRIP_ASSUME_TAC THENL
     [USE_THEN "hrk" (MP_TAC o SPECL [`z:A`; `w':A`]) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> MP_TAC(fst(EQ_IMP_RULE th))) THEN
      DISCH_THEN MATCH_MP_TAC THEN ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `B:A`; `z:A`; `w':A`; `a:A`]
          BNAME_RANK_UNIQUE) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[];
      DISCH_THEN ACCEPT_TAC];
    ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `bb:A` (CONJUNCTS_THEN2 ASSUME_TAC
    (LABEL_TAC "bch"))) THEN
  SUBGOAL_THEN
   `!w:A. w IN D /\ (E:A->A->bool) w bb ==> eordinal D E w`
  (LABEL_TAC "bord") THENL
   [X_GEN_TAC `w:A` THEN STRIP_TAC THEN
    USE_THEN "bch" (MP_TAC o SPEC `w:A`) THEN ANTS_TAC THENL
     [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> MP_TAC(fst(EQ_IMP_RULE th))) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(X_CHOOSE_THEN `z:A` STRIP_ASSUME_TAC) THEN
    USE_THEN "hrk" (MP_TAC o SPECL [`z:A`; `w:A`]) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> MP_TAC(fst(EQ_IMP_RULE th))) THEN
    ASM_REWRITE_TAC[] THEN
    DISCH_THEN(fun th -> MAP_EVERY ASSUME_TAC (CONJUNCTS th)) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `?b0:A. eunion D (E:A->A->bool) bb b0`
  STRIP_ASSUME_TAC THENL [ASM_MESON_TAC[EUNION_EXISTS]; ALL_TAC] THEN
  SUBGOAL_THEN `(b0:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[EUNION_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `eordinal D (E:A->A->bool) b0` ASSUME_TAC THENL
   [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `bb:A`; `b0:A`]
          EORDINAL_EUNION) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[];
      DISCH_THEN ACCEPT_TAC];
    ALL_TAC] THEN
  SUBGOAL_THEN `?yb:A. yb IN D /\ ebnstage D (E:A->A->bool) B b0 yb`
  STRIP_ASSUME_TAC THENL [ASM_MESON_TAC[EBNSTAGE_EXISTS]; ALL_TAC] THEN
  MAP_EVERY EXISTS_TAC [`b0:A`; `yb:A`] THEN ASM_REWRITE_TAC[] THEN
  X_GEN_TAC `z:A` THEN STRIP_TAC THEN
  SUBGOAL_THEN `bname D (E:A->A->bool) B z` ASSUME_TAC THENL
   [ASM_MESON_TAC[]; ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `B:A`; `z:A`] BNAME_RANK) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `a:A` (CONJUNCTS_THEN2 ASSUME_TAC
    (CONJUNCTS_THEN2 ASSUME_TAC (CONJUNCTS_THEN2
      (X_CHOOSE_THEN `ya:A` STRIP_ASSUME_TAC)
      (LABEL_TAC "amin"))))) THEN
  SUBGOAL_THEN `(E:A->A->bool) a bb` ASSUME_TAC THENL
   [USE_THEN "bch" (MP_TAC o SPEC `a:A`) THEN ANTS_TAC THENL
     [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    EXISTS_TAC `z:A` THEN ASM_REWRITE_TAC[] THEN
    USE_THEN "hrk" (MP_TAC o SPECL [`z:A`; `a:A`]) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `esubset D (E:A->A->bool) a b0` ASSUME_TAC THENL
   [REWRITE_TAC[esubset] THEN X_GEN_TAC `t:A` THEN STRIP_TAC THEN
    FIRST_ASSUM(MP_TAC o GEN_REWRITE_RULE I [eunion]) THEN
    DISCH_THEN(CONJUNCTS_THEN2 (K ALL_TAC) (MP_TAC o SPEC `t:A`)) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    EXISTS_TAC `a:A` THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `a:A`; `b0:A`]
        EORDINAL_SUBSET_MEMBER) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  STRIP_TAC THENL
   [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `B:A`; `b0:A`; `a:A`;
                  `yb:A`; `ya:A`; `z:A`] EBNSTAGE_MONO) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC];
    ASM_MESON_TAC[EBNSTAGE_UNIQUE; EORDINAL_IN]]);;

(* ===================================================================== *)
(* F3d: every check-name is a B-name.                                     *)
(* bname_form/HOLDS_BNAME_FORM read the B-name predicate as an object    *)
(* formula (rec_form bname_step_form 3, slot 2 = B); goodcheck is the     *)
(* object formula "every pair (x,v) in the check-stage read via the      *)
(* resolvent graph at slot 81 has a B-name 2nd coordinate", with         *)
(* HOLDS_GOODCHECK/GOODCHECK_SEM its semantic reading.  GOODCHECK_STEP is *)
(* the transfinite-induction step (pure semantics), and ECHECK_IS_BNAME  *)
(* closes it by least-counterexample (EORDINAL_LEAST on Not goodcheck --  *)
(* the model may be non-wellfounded, so the induction is over an object   *)
(* formula, never meta-level HOL induction).                             *)
(* ===================================================================== *)

let bname_form = new_definition
  `bname_form k =
     ?? 30 (ordinal_form 30 &&
            ?? 31 (recapp3_form (rec_form bname_step_form 3) 30 31 &&
                   k %% 31))`;;

let HOLDS_BNAME_FORM = prove
 (`!D (E:A->A->bool) v k.
        model D E ZF_AX /\ valuation D v /\ ~(k = 30) /\ ~(k = 31)
        ==> (holds D E v (bname_form k) <=> bname D E (v 2) (v k))`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `!x. (v:num->A) x IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[valuation]; ALL_TAC] THEN
  REWRITE_TAC[bname_form] THEN
  SUBGOAL_THEN
   `!a y:A. a IN D /\ y IN D
      ==> (holds D E ((31 |-> y) ((30 |-> a) v))
             (recapp3_form (rec_form bname_step_form 3) 30 31) <=>
           ebnstage D E (v 2) a y)`
  (LABEL_TAC "rc") THENL
   [REPEAT GEN_TAC THEN STRIP_TAC THEN
    SUBGOAL_THEN `valuation D ((31 |-> (y:A)) ((30 |-> (a:A)) v))`
      ASSUME_TAC THENL
      [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
                  `(31 |-> (y:A)) ((30 |-> (a:A)) v)`; `30`; `31`]
          HOLDS_RECAPP3_BNSTEP) THEN
    ASM_REWRITE_TAC[ARITH_RULE
      `~(30 = 3) /\ ~(30 = 4) /\ ~(31 = 3) /\ ~(31 = 4)`] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    REWRITE_TAC[VALMOD; ARITH_EQ];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!a:A. a IN D
      ==> (holds D E ((30 |-> a) v)
             (ordinal_form 30 &&
              ?? 31 (recapp3_form (rec_form bname_step_form 3) 30 31 &&
                     k %% 31)) <=>
           eordinal D E a /\
           (?y. y IN D /\ ebnstage D E (v 2) a y /\ E (v k) y))`
  (LABEL_TAC "step") THENL
   [X_GEN_TAC `a:A` THEN DISCH_TAC THEN
    SUBGOAL_THEN `valuation D ((30 |-> (a:A)) v)` ASSUME_TAC THENL
     [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
    REWRITE_TAC[HOLDS_AND] THEN
    ASM_SIMP_TAC[HOLDS_ORDINAL_FORM; VALMOD; ARITH_EQ] THEN
    MATCH_MP_TAC(TAUT `(y <=> z) ==> ((x /\ y) <=> (x /\ z))`) THEN
    REWRITE_TAC[HOLDS_EX; HOLDS_AND; holds] THEN
    MATCH_MP_TAC(MESON[]
      `(!y:A. y IN D ==> (P y <=> Q y))
       ==> ((?y. y IN D /\ P y) <=> (?y. y IN D /\ Q y))`) THEN
    X_GEN_TAC `y:A` THEN DISCH_TAC THEN
    USE_THEN "rc" (MP_TAC o SPECL [`a:A`; `y:A`]) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    ASM_REWRITE_TAC[VALMOD; ARITH_EQ];
    ALL_TAC] THEN
  REWRITE_TAC[bname; HOLDS_EX] THEN
  MATCH_MP_TAC(MESON[]
   `(!a:A. a IN D ==> (P a <=> S a /\ (?y. y IN D /\ R a y)))
    ==> ((?a. a IN D /\ P a) <=>
         (?a y. a IN D /\ y IN D /\ S a /\ R a y))`) THEN
  USE_THEN "step" ACCEPT_TAC);;

(* goodcheck(d): every pair (x,v) in the check-stage cd_d has bname 2nd coord.
   Reads the check-stage via the resolvent graph rc at slot 81 (apply_form 81 0
   82), so the check-tower engine never enters the object formula; the B-name
   predicate is read via bname_form (rec_form bname_step_form 3, slot 2 = B).
   Index d at slot 0 (for EORDINAL_LEAST).  Slots: 82=stage, 88=pair, 89=x,
   90=v.  apply_form 81 0 82 binds 83,84,85 internally; opair_form 89 90 88
   binds 91,92; bname_form 90 binds 30,31 -- all distinct,
   and none is 0/2/81. *)
let goodcheck = new_definition
  `goodcheck =
     ?? 82 (apply_form 81 0 82 &&
            !!- 88 82 (!! 89
                       (!! 90 (opair_form 89 90 88 --> bname_form 90))))`;;

let HOLDS_GOODCHECK = prove
 (`!D (E:A->A->bool) v.
     model D E ZF_AX /\ valuation D v
     ==> (holds D E v goodcheck <=>
          ?stg. stg IN D /\ eapply D E (v 81) (v 0) stg /\
                !pp. pp IN D /\ E pp stg
                     ==> !x vv. x IN D /\ vv IN D /\ eopair D E x vv pp
                                ==> bname D E (v 2) vv)`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `!n. (v:num->A) n IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[valuation]; ALL_TAC] THEN
  REWRITE_TAC[goodcheck; HOLDS_EX; HOLDS_AND] THEN
  MATCH_MP_TAC(MESON[]
    `(!s:A. s IN D ==> (P s <=> Q s))
     ==> ((?s. s IN D /\ P s) <=> (?s. s IN D /\ Q s))`) THEN
  X_GEN_TAC `stg:A` THEN DISCH_TAC THEN
  SUBGOAL_THEN `valuation D ((82 |-> (stg:A)) v)` ASSUME_TAC THENL
   [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
  SUBGOAL_THEN
   `holds D E ((82 |-> (stg:A)) v) (apply_form 81 0 82) <=>
    eapply D E (v 81) (v 0) stg`
  (fun th -> REWRITE_TAC[th]) THENL
   [ASM_SIMP_TAC[HOLDS_APPLY_FORM] THEN REWRITE_TAC[VALMOD; ARITH_EQ];
    ALL_TAC] THEN
  MATCH_MP_TAC(TAUT `(y <=> z) ==> ((x /\ y) <=> (x /\ z))`) THEN
  ASM_SIMP_TAC[HOLDS_FORALLMEM; ARITH_RULE `~(88 = 82)`] THEN
  REWRITE_TAC[VALMOD; ARITH_EQ] THEN
  MATCH_MP_TAC(MESON[]
    `(!pp:A. M pp ==> (P pp <=> Q pp))
     ==> ((!pp. M pp ==> P pp) <=> (!pp. M pp ==> Q pp))`) THEN
  X_GEN_TAC `pp:A` THEN STRIP_TAC THEN
  SUBGOAL_THEN `valuation D ((88 |-> (pp:A)) ((82 |-> (stg:A)) v))`
    ASSUME_TAC THENL
   [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
  REWRITE_TAC[holds] THEN
  MATCH_MP_TAC(MESON[]
    `(!x vv:A. x IN D /\ vv IN D ==> (H x vv <=> (R x vv ==> S vv)))
     ==> ((!x. x IN D ==> !vv. vv IN D ==> H x vv) <=>
          (!x vv. x IN D /\ vv IN D /\ R x vv ==> S vv))`) THEN
  MAP_EVERY X_GEN_TAC [`x:A`; `vv:A`] THEN STRIP_TAC THEN
  SUBGOAL_THEN
   `valuation D
    ((90 |-> (vv:A)) ((89 |-> (x:A)) ((88 |-> (pp:A)) ((82 |-> (stg:A)) v))))`
  ASSUME_TAC THENL [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
  MATCH_MP_TAC(TAUT
               `(a <=> c) /\ (b <=> d) ==> ((a ==> b) <=> (c ==> d))`) THEN
  CONJ_TAC THENL
   [ASM_SIMP_TAC[HOLDS_OPAIR_FORM] THEN REWRITE_TAC[VALMOD; ARITH_EQ];
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
      `(90 |-> (vv:A))
       ((89 |-> (x:A)) ((88 |-> (pp:A)) ((82 |-> (stg:A)) v)))`;
      `90`] HOLDS_BNAME_FORM) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[ARITH_RULE `~(90 = 30) /\ ~(90 = 31)`]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    REWRITE_TAC[VALMOD; ARITH_EQ]]);;

(* GOODCHECK_SEM: semantic reading of `holds goodcheck` at index b, via the
   check-tower resolvent graph rc at slot 81.  Mirror of GOODF2CHECK_SEM.
   Slot 2 of v0 carries B (the Boolean algebra), read by bname_form; the
   check-tower's onebee lives only inside rc (semantic) and as the pair tag. *)
let GOODCHECK_SEM = prove
 (`!D (E:A->A->bool) onebee B sa rc v0 b.
      model D E ZF_AX /\ onebee IN D /\ B IN D /\ eordinal D E sa /\
      rc IN D /\ valuation D v0 /\ v0 2 = B /\
      (!pp. pp IN D
            ==> (E pp rc <=>
                 ?b' z'. b' IN D /\ z' IN D /\ E b' sa /\
                         echecktower D E onebee b' z' /\
                           eopair D E b' z' pp)) /\
      b IN D /\ E b sa
      ==> (holds D E ((0 |-> b) ((81 |-> rc) v0)) goodcheck <=>
           !zb pp x vv.
              zb IN D /\ pp IN D /\ x IN D /\ vv IN D /\
              echecktower D E onebee b zb /\ E pp zb /\ eopair D E x vv pp
              ==> bname D E B vv)`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "zf onebeeD BD ordsa rcD valv0 v02 rcc bD bsa" THEN
  SUBGOAL_THEN `eordinal D (E:A->A->bool) b` ASSUME_TAC THENL
   [ASM_MESON_TAC[EORDINAL_MEMBER]; ALL_TAC] THEN
  SUBGOAL_THEN `valuation D ((0 |-> (b:A)) ((81 |-> (rc:A)) v0))`
  ASSUME_TAC THENL [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;
    `(0 |-> (b:A)) ((81 |-> (rc:A)) v0)`] HOLDS_GOODCHECK) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  REWRITE_TAC[VALMOD; ARITH_EQ] THEN
  USE_THEN "v02" (fun th -> REWRITE_TAC[th]) THEN
  EQ_TAC THENL
   [DISCH_THEN(X_CHOOSE_THEN `stg:A` (CONJUNCTS_THEN2 ASSUME_TAC
      (CONJUNCTS_THEN2 ASSUME_TAC (LABEL_TAC "allp")))) THEN
    SUBGOAL_THEN `echecktower D (E:A->A->bool) onebee b stg` ASSUME_TAC THENL
     [MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;
        `echecktower D (E:A->A->bool) onebee`;`sa:A`;`rc:A`;`b:A`;`stg:A`]
        EGRAPH_APPLY) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> MP_TAC(EQ_MP th
        (ASSUME `eapply D (E:A->A->bool) rc b stg`))) THEN
      DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC ACCEPT_TAC);
      ALL_TAC] THEN
    MAP_EVERY X_GEN_TAC [`zb:A`;`pp:A`;`x:A`;`vv:A`] THEN STRIP_TAC THEN
    SUBGOAL_THEN `zb:A = stg` SUBST_ALL_TAC THENL
     [ASM_MESON_TAC[ECHECKTOWER_UNIQUE]; ALL_TAC] THEN
    USE_THEN "allp" (MP_TAC o SPEC `pp:A`) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(MP_TAC o SPECL [`x:A`;`vv:A`]) THEN
    ASM_REWRITE_TAC[];
    DISCH_THEN(LABEL_TAC "sem") THEN
    MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`onebee:A`;`b:A`]
      ECHECKTOWER_EXISTS) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(X_CHOOSE_THEN `stg0:A` STRIP_ASSUME_TAC) THEN
    EXISTS_TAC `stg0:A` THEN ASM_REWRITE_TAC[] THEN
    SUBGOAL_THEN `eapply D (E:A->A->bool) rc b stg0` ASSUME_TAC THENL
     [MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;
        `echecktower D (E:A->A->bool) onebee`;`sa:A`;`rc:A`;`b:A`;`stg0:A`]
        EGRAPH_APPLY) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    ASM_REWRITE_TAC[] THEN
    X_GEN_TAC `pp:A` THEN STRIP_TAC THEN
    MAP_EVERY X_GEN_TAC [`x:A`;`vv:A`] THEN STRIP_TAC THEN
    USE_THEN "sem" (MP_TAC o SPECL [`stg0:A`;`pp:A`;`x:A`;`vv:A`]) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC]]);;

(* GOODCHECK_STEP: the transfinite induction step for "every 2nd coordinate of
   a pair in a check-stage is a B-name".  Pure semantics (no object formula):
   given the IH at all earlier ordinals b'<d, it holds at d.  Assembled from
   ECHECKTOWER_VALUE (expose the accumulator gacc and image vv), the IH (each
   earlier value is a B-name), BNAME_BOUND (common bounding B-name stage of
   dom(vv)) and ECHECK_BNAME_SUCC (vv lands at that stage).  All IN-D / ordinal
   side facts derived MESON-free (junk-heavy recursion context blows
     MESON up). *)
let GOODCHECK_STEP = prove
 (`!D (E:A->A->bool) onebee B d.
      model D E ZF_AX /\ onebee IN D /\ B IN D /\ E onebee B /\
      eordinal D E d /\
      (!b'. b' IN D /\ E b' d
            ==> !zb pp x vv.
                   zb IN D /\ pp IN D /\ x IN D /\ vv IN D /\
                   echecktower D E onebee b' zb /\ E pp zb /\
                   eopair D E x vv pp
                   ==> bname D E B vv)
      ==> !zd pp x vv.
             zd IN D /\ pp IN D /\ x IN D /\ vv IN D /\
             echecktower D E onebee d zd /\ E pp zd /\ eopair D E x vv pp
             ==> bname D E B vv`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "modl oneD BD oneB dord IH" THEN
  MAP_EVERY X_GEN_TAC [`zd:A`;`pp:A`;`x:A`;`vv:A`] THEN
  INTRO_TAC "zdD ppD xD vvD tow ppzd pairp" THEN
  (* echeck onebee x vv (needed by ECHECK_BNAME_SUCC at the end) *)
  MP_TAC(SPECL
         [`D:A->bool`;`E:A->A->bool`;`onebee:A`;`d:A`;`zd:A`;`x:A`;`vv:A`;
          `pp:A`] ECHECK_STAGE) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(LABEL_TAC "chk") THEN
  (* expose the accumulator gacc and (pinned) image vv via ECHECKTOWER_VALUE *)
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`onebee:A`;`d:A`;`zd:A`;`pp:A`]
        ECHECKTOWER_VALUE) THEN
  ASM_REWRITE_TAC[] THEN
  INTRO_TAC "@gacc w x2 img. gaccD wD x2D imgD gaccch domn pairx subxw \
             imgch" THEN
  SUBGOAL_THEN `x2:A = x /\ img:A = vv`
    (CONJUNCTS_THEN2 SUBST_ALL_TAC SUBST_ALL_TAC) THENL
   [MP_TAC(SPECL
           [`D:A->bool`;`E:A->A->bool`;`x2:A`;`img:A`;`x:A`;`vv:A`;`pp:A`]
           EOPAIR_INJ) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* CORE: every domain element u of vv is a B-name (via the IH at b'<d) *)
  SUBGOAL_THEN `!u:A. u IN D /\ eindom D E vv u ==> bname D E B u`
  (LABEL_TAC "core") THENL
   [X_GEN_TAC `u:A` THEN
    DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "uD")
      (MP_TAC o REWRITE_RULE[eindom])) THEN
    DISCH_THEN(X_CHOOSE_THEN `ww:A` (CONJUNCTS_THEN2 (LABEL_TAC "wwD")
      (MP_TAC o REWRITE_RULE[eapply]))) THEN
    DISCH_THEN(X_CHOOSE_THEN `z:A` (CONJUNCTS_THEN2 (LABEL_TAC "pruwz")
      (LABEL_TAC "ezvv"))) THEN
    SUBGOAL_THEN `(z:A) IN D` (LABEL_TAC "zD") THENL
     [MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`u:A`;`ww:A`;`z:A`]
             EOPAIR_IN) THEN
      ASM_REWRITE_TAC[]; ALL_TAC] THEN
    USE_THEN "imgch" (MP_TAC o C MATCH_MP (ASSUME `(z:A) IN D`)) THEN
    REWRITE_TAC[ASSUME `(E:A->A->bool) z vv`] THEN
    DISCH_THEN(X_CHOOSE_THEN `y:A` (CONJUNCTS_THEN2 (LABEL_TAC "yD")
      (X_CHOOSE_THEN `vy:A`
       (fun th -> MAP_EVERY ASSUME_TAC (CONJUNCTS th))))) THEN
    SUBGOAL_THEN `u:A = vy /\ ww:A = onebee`
      (CONJUNCTS_THEN2 SUBST_ALL_TAC (K ALL_TAC)) THENL
     [MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`u:A`;`ww:A`;`vy:A`;`onebee:A`;
                    `z:A`] EOPAIR_INJ) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    UNDISCH_TAC `eapply D (E:A->A->bool) gacc y vy` THEN
    REWRITE_TAC[eapply] THEN
    DISCH_THEN(X_CHOOSE_THEN `p:A` (CONJUNCTS_THEN2 (LABEL_TAC "pairyp")
      (LABEL_TAC "pgacc"))) THEN
    SUBGOAL_THEN `(p:A) IN D` (LABEL_TAC "pD") THENL
     [MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`y:A`;`vy:A`;`p:A`]
             EOPAIR_IN) THEN
      ASM_REWRITE_TAC[]; ALL_TAC] THEN
    USE_THEN "gaccch" (MP_TAC o C MATCH_MP (ASSUME `(p:A) IN D`)) THEN
    REWRITE_TAC[ASSUME `(E:A->A->bool) p gacc`] THEN
    DISCH_THEN(X_CHOOSE_THEN `b:A` (X_CHOOSE_THEN `zb:A`
      (fun th -> MAP_EVERY ASSUME_TAC (CONJUNCTS th)))) THEN
    USE_THEN "IH" (MP_TAC o SPEC `b:A`) THEN ANTS_TAC THENL
     [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(MP_TAC o SPECL [`zb:A`;`p:A`;`y:A`;`vy:A`]) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  (* materialize dom(vv), all of whose members are B-names *)
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`vv:A`] EDOMAIN_EXISTS) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `dv:A` (LABEL_TAC "domvv")) THEN
  SUBGOAL_THEN `(dv:A) IN D` (LABEL_TAC "dvD") THENL
   [USE_THEN "domvv" (ACCEPT_TAC o CONJUNCT1 o REWRITE_RULE[edomain]);
    ALL_TAC] THEN
  SUBGOAL_THEN `!t:A. t IN D /\ E t dv ==> bname D E B t`
    (LABEL_TAC "allbn") THENL
   [X_GEN_TAC `t:A` THEN STRIP_TAC THEN
    USE_THEN "core" MATCH_MP_TAC THEN ASM_REWRITE_TAC[] THEN
    USE_THEN "domvv"
      (MP_TAC o SPEC `t:A` o CONJUNCT2 o REWRITE_RULE[edomain]) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[GSYM th]) THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  (* common bounding B-name stage of dom(vv) *)
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`dv:A`] BNAME_BOUND) THEN
  ASM_REWRITE_TAC[] THEN
  INTRO_TAC "@c0 yc0. c0D yc0D c0ord bnc0 bnd" THEN
  (* a2 = esuc c0, ya2 its B-name stage *)
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`c0:A`] ESUC_EXISTS) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `a2:A` (LABEL_TAC "suc")) THEN
  SUBGOAL_THEN `(a2:A) IN D` (LABEL_TAC "a2D") THENL
   [MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`c0:A`;`a2:A`] ESUC_IN) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `eordinal D (E:A->A->bool) a2` (LABEL_TAC "a2ord") THENL
   [MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`c0:A`;`a2:A`] EORDINAL_ESUC) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) c0 a2` (LABEL_TAC "c0a2") THENL
   [MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`c0:A`;`a2:A`] ESUC_MEMBER) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`a2:A`] EBNSTAGE_EXISTS) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `ya2:A` (CONJUNCTS_THEN2 (LABEL_TAC "ya2D")
    (LABEL_TAC "bnstga2"))) THEN
  (* land vv at stage a2 via ECHECK_BNAME_SUCC *)
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`onebee:A`;`x:A`;`vv:A`;
                `a2:A`;`ya2:A`] ECHECK_BNAME_SUCC) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[] THEN
    MAP_EVERY X_GEN_TAC [`u:A`;`ww:A`;`z:A`] THEN STRIP_TAC THEN
    MAP_EVERY EXISTS_TAC [`c0:A`;`yc0:A`] THEN ASM_REWRITE_TAC[] THEN
    USE_THEN "bnd" MATCH_MP_TAC THEN ASM_REWRITE_TAC[] THEN
    USE_THEN "domvv"
      (MP_TAC o SPEC `u:A` o CONJUNCT2 o REWRITE_RULE[edomain]) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    REWRITE_TAC[eindom] THEN EXISTS_TAC `ww:A` THEN
    ASM_REWRITE_TAC[eapply] THEN EXISTS_TAC `z:A` THEN ASM_REWRITE_TAC[];
    DISCH_THEN ACCEPT_TAC]);;

(* ECHECK_IS_BNAME: every check-name v (= x-check) is a B-name.
  Structural twin
   of ECHECKTOWER_COHERE: build the check-tower resolvent graph rc at
   sa = esuc a, then prove the goodcheck-semantic statement holds at every
   ordinal < sa by least-counterexample (EORDINAL_LEAST on `Not goodcheck`,
   GOODCHECK_SEM to bridge holds<->semantic, GOODCHECK_STEP for the step);
   instantiate at a and feed the (x,v)-pair from echeck.  The valuation carries
   B at slot 2 (read by bname_form) via (2 |-> B) v0. *)
let ECHECK_IS_BNAME = prove
 (`!D (E:A->A->bool) onebee B x v.
      model D E ZF_AX /\ onebee IN D /\ B IN D /\ E onebee B /\
      x IN D /\ v IN D /\ echeck D E onebee x v
      ==> bname D E B v`,
  REPEAT GEN_TAC THEN
  DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "modl")
   (CONJUNCTS_THEN2 (LABEL_TAC "oneD")
    (CONJUNCTS_THEN2 (LABEL_TAC "BD")
     (CONJUNCTS_THEN2 (LABEL_TAC "oneB")
      (CONJUNCTS_THEN2 (LABEL_TAC "xD")
       (CONJUNCTS_THEN2 (LABEL_TAC "vD")
         (MP_TAC o REWRITE_RULE[echeck]))))))) THEN
  DISCH_THEN(CONJUNCTS_THEN2 (K ALL_TAC)
   (CONJUNCTS_THEN2 (K ALL_TAC)
    (X_CHOOSE_THEN `a:A` (X_CHOOSE_THEN `cd:A` (X_CHOOSE_THEN `pp:A`
      (fun th -> MAP_EVERY ASSUME_TAC (CONJUNCTS th))))))) THEN
  (* sa = esuc a *)
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`a:A`] ESUC_EXISTS) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_TAC `sa:A`) THEN
  SUBGOAL_THEN `(sa:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[ESUC_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `eordinal D (E:A->A->bool) sa` ASSUME_TAC THENL
   [ASM_MESON_TAC[EORDINAL_ESUC]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) a sa` ASSUME_TAC THENL
   [ASM_MESON_TAC[ESUC_MEMBER]; ALL_TAC] THEN
  (* resolvent graph rc for the check-tower at sa *)
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`onebee:A`;`sa:A`]
    ECHECKTOWER_RESGRAPH) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `rc:A` (CONJUNCTS_THEN2 ASSUME_TAC
    (LABEL_TAC "rcc"))) THEN
  FIRST_ASSUM(X_CHOOSE_TAC `v0:num->A` o MATCH_MP VALUATION_EXISTS o
              MATCH_MP MODEL_NONEMPTY) THEN
  SUBGOAL_THEN `valuation D ((2 |-> (B:A)) v0)` ASSUME_TAC THENL
   [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
  SUBGOAL_THEN `((2 |-> (B:A)) v0) 2 = B` ASSUME_TAC THENL
   [REWRITE_TAC[VALMOD]; ALL_TAC] THEN
  SUBGOAL_THEN `valuation D ((81 |-> (rc:A)) ((2 |-> (B:A)) v0))`
  ASSUME_TAC THENL [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
  (* goodcheck-semantic holds at every ordinal below sa *)
  SUBGOAL_THEN
   `!dd. dd IN D /\ E dd sa
         ==> holds D E ((0 |-> dd) ((81 |-> (rc:A)) ((2 |-> (B:A)) v0)))
                       goodcheck`
  (LABEL_TAC "good") THENL
   [GEN_TAC THEN STRIP_TAC THEN
    MATCH_MP_TAC(TAUT `(~p ==> F) ==> p`) THEN
    DISCH_THEN(LABEL_TAC "bad0") THEN
    SUBGOAL_THEN `eordinal D (E:A->A->bool) dd` ASSUME_TAC THENL
     [ASM_MESON_TAC[EORDINAL_MEMBER]; ALL_TAC] THEN
    MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`Not goodcheck`;
                  `(81 |-> (rc:A)) ((2 |-> (B:A)) v0)`;`dd:A`]
      EORDINAL_LEAST) THEN
    ASM_REWRITE_TAC[HOLDS_NOT] THEN
    DISCH_THEN(X_CHOOSE_THEN `d:A` (CONJUNCTS_THEN2 ASSUME_TAC
      (CONJUNCTS_THEN2 ASSUME_TAC (CONJUNCTS_THEN2 (LABEL_TAC "dbad")
        (LABEL_TAC "dmin"))))) THEN
    SUBGOAL_THEN `(d:A) IN D` ASSUME_TAC THENL
     [ASM_MESON_TAC[EORDINAL_IN]; ALL_TAC] THEN
    SUBGOAL_THEN `(E:A->A->bool) d sa` ASSUME_TAC THENL
     [MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`d:A`;`dd:A`]
        EORDINAL_TRICHOTOMY) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(REPEAT_TCL DISJ_CASES_THEN ASSUME_TAC) THENL
       [ASM_MESON_TAC[EORDINAL_TRANS_E];
        ASM_MESON_TAC[];
        USE_THEN "dmin" (MP_TAC o SPEC `dd:A`) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
        USE_THEN "bad0" (fun th -> REWRITE_TAC[th])];
      ALL_TAC] THEN
    (* IH: the semantic statement holds at every b' < d *)
    SUBGOAL_THEN
     `!b'. b' IN D /\ E b' d
           ==> !zb pp x vv.
                  zb IN D /\ pp IN D /\ x IN D /\ vv IN D /\
                  echecktower D (E:A->A->bool) onebee b' zb /\ E pp zb /\
                  eopair D E x vv pp
                  ==> bname D E B vv`
    ASSUME_TAC THENL
     [X_GEN_TAC `b':A` THEN STRIP_TAC THEN
      SUBGOAL_THEN `(E:A->A->bool) b' sa` ASSUME_TAC THENL
       [ASM_MESON_TAC[EORDINAL_TRANS_E]; ALL_TAC] THEN
      MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`onebee:A`;`B:A`;`sa:A`;`rc:A`;
                    `(2 |-> (B:A)) v0`;`b':A`] GOODCHECK_SEM) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(MP_TAC o fst o EQ_IMP_RULE) THEN
      ANTS_TAC THENL
       [USE_THEN "dmin" (MP_TAC o SPEC `b':A`) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC];
        DISCH_THEN ACCEPT_TAC];
      ALL_TAC] THEN
    (* holds at d, contradicting dbad *)
    SUBGOAL_THEN
     `holds D E ((0 |-> (d:A)) ((81 |-> (rc:A)) ((2 |-> (B:A)) v0))) goodcheck`
    MP_TAC THENL
     [MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`onebee:A`;`B:A`;`sa:A`;`rc:A`;
                    `(2 |-> (B:A)) v0`;`d:A`] GOODCHECK_SEM) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
      MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`onebee:A`;`B:A`;`d:A`]
        GOODCHECK_STEP) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC];
      USE_THEN "dbad" (fun th -> REWRITE_TAC[th])];
    ALL_TAC] THEN
  (* instantiate at a and feed the (x,v)-pair from echeck *)
  USE_THEN "good" (MP_TAC o SPEC `a:A`) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_TAC THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`onebee:A`;`B:A`;`sa:A`;`rc:A`;
                `(2 |-> (B:A)) v0`;`a:A`] GOODCHECK_SEM) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(MP_TAC o fst o EQ_IMP_RULE) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(MP_TAC o SPECL [`cd:A`;`pp:A`;`x:A`;`v:A`]) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC]);;

(* ===================================================================== *)
(* F3d: EXHAUSTION -- every x IN D has a check-name.                      *)
(* cover_form internalises the coverage invariant INV(a):                 *)
(*   every u in L(a) is in the domain of the check-stage cd_a             *)
(*     (i.e. u has a check-name at stage a).                              *)
(* Both towers are read SEMANTICALLY via resolvent graphs (rL at slot 80, *)
(* rc at slot 81) so the check-engine's slot-2=onebee never collides with *)
(* the L-engine's slots 2,3 -- exactly the ECHECK_IS_BNAME dodge.  Index  *)
(* a at slot 0.  L(a) landed in slot 95 (apply 80 0 95 binds 96,97,98),   *)
(* cd_a in slot 82 (apply 81 0 82 binds 83,84,85); forallmem var 88 over  *)
(* L(a); the check-name pair (img=89, pp=90) with opair_form 88 89 90     *)
(* (binds 91,92) and pp in cd_a.  All slots pairwise disjoint.            *)
(* ===================================================================== *)
let cover_form = new_definition
  `cover_form =
     ?? 95 (apply_form 80 0 95 &&
            ?? 82 (apply_form 81 0 82 &&
                   !!- 88 95 (?? 89 (?? 90 (opair_form 88 89 90 &&
                                            90 %% 82)))))`;;

let HOLDS_COVER_FORM = prove
 (`!D (E:A->A->bool) v.
     model D E ZF_AX /\ valuation D v
     ==> (holds D E v cover_form <=>
          ?yL. yL IN D /\ eapply D E (v 80) (v 0) yL /\
               ?stg. stg IN D /\ eapply D E (v 81) (v 0) stg /\
                     !u. u IN D /\ E u yL
                         ==> ?img. img IN D /\ ?pp. pp IN D /\
                                   eopair D E u img pp /\ E pp stg)`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `!n. (v:num->A) n IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[valuation]; ALL_TAC] THEN
  REWRITE_TAC[cover_form; HOLDS_EX; HOLDS_AND] THEN
  MATCH_MP_TAC(MESON[]
    `(!s:A. s IN D ==> (P s <=> Q s))
     ==> ((?s. s IN D /\ P s) <=> (?s. s IN D /\ Q s))`) THEN
  X_GEN_TAC `yL:A` THEN DISCH_TAC THEN
  SUBGOAL_THEN `valuation D ((95 |-> (yL:A)) v)` ASSUME_TAC THENL
   [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
  SUBGOAL_THEN
   `holds D E ((95 |-> (yL:A)) v) (apply_form 80 0 95) <=>
    eapply D E (v 80) (v 0) yL`
  (fun th -> REWRITE_TAC[th]) THENL
   [ASM_SIMP_TAC[HOLDS_APPLY_FORM] THEN REWRITE_TAC[VALMOD; ARITH_EQ];
    ALL_TAC] THEN
  MATCH_MP_TAC(TAUT `(y <=> z) ==> ((x /\ y) <=> (x /\ z))`) THEN
  REWRITE_TAC[HOLDS_EX; HOLDS_AND] THEN
  MATCH_MP_TAC(MESON[]
    `(!s:A. s IN D ==> (P s <=> Q s))
     ==> ((?s. s IN D /\ P s) <=> (?s. s IN D /\ Q s))`) THEN
  X_GEN_TAC `stg:A` THEN DISCH_TAC THEN
  SUBGOAL_THEN `valuation D ((82 |-> (stg:A)) ((95 |-> (yL:A)) v))`
  ASSUME_TAC THENL [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
  SUBGOAL_THEN
   `holds D E ((82 |-> (stg:A)) ((95 |-> (yL:A)) v)) (apply_form 81 0 82) <=>
    eapply D E (v 81) (v 0) stg`
  (fun th -> REWRITE_TAC[th]) THENL
   [ASM_SIMP_TAC[HOLDS_APPLY_FORM] THEN REWRITE_TAC[VALMOD; ARITH_EQ];
    ALL_TAC] THEN
  MATCH_MP_TAC(TAUT `(y <=> z) ==> ((x /\ y) <=> (x /\ z))`) THEN
  ASM_SIMP_TAC[HOLDS_FORALLMEM; ARITH_RULE `~(88 = 95)`] THEN
  REWRITE_TAC[VALMOD; ARITH_EQ] THEN
  MATCH_MP_TAC(MESON[]
    `(!u:A. M u ==> (P u <=> Q u))
     ==> ((!u. M u ==> P u) <=> (!u. M u ==> Q u))`) THEN
  X_GEN_TAC `u:A` THEN STRIP_TAC THEN
  SUBGOAL_THEN
    `valuation D ((88 |-> (u:A)) ((82 |-> (stg:A)) ((95 |-> (yL:A)) v)))`
  ASSUME_TAC THENL [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
  REWRITE_TAC[HOLDS_EX; HOLDS_AND] THEN
  MATCH_MP_TAC(MESON[]
    `(!s:A. s IN D ==> (P s <=> Q s))
     ==> ((?s. s IN D /\ P s) <=> (?s. s IN D /\ Q s))`) THEN
  X_GEN_TAC `img:A` THEN DISCH_TAC THEN
  SUBGOAL_THEN
   `valuation D ((89 |-> (img:A)) ((88 |-> (u:A)) ((82 |-> (stg:A))
      ((95 |-> (yL:A)) v))))`
  ASSUME_TAC THENL [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
  MATCH_MP_TAC(MESON[]
    `(!s:A. s IN D ==> (P s <=> Q s))
     ==> ((?s. s IN D /\ P s) <=> (?s. s IN D /\ Q s))`) THEN
  X_GEN_TAC `pp:A` THEN DISCH_TAC THEN
  SUBGOAL_THEN
   `valuation D ((90 |-> (pp:A)) ((89 |-> (img:A)) ((88 |-> (u:A))
      ((82 |-> (stg:A)) ((95 |-> (yL:A)) v)))))`
  ASSUME_TAC THENL [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
  MATCH_MP_TAC(TAUT `(a <=> c) /\ (b <=> d) ==> ((a /\ b) <=> (c /\ d))`) THEN
  CONJ_TAC THENL
   [ASM_SIMP_TAC[HOLDS_OPAIR_FORM] THEN REWRITE_TAC[VALMOD; ARITH_EQ];
    REWRITE_TAC[holds] THEN REWRITE_TAC[VALMOD; ARITH_EQ]]);;

(* COVER_SEM: semantic reading of `holds cover_form` at index b,
via the L-tower
   resolvent graph rL at slot 80 and the check-tower resolvent graph rc at slot
   81.  Mirror of GOODCHECK_SEM; no slot-2 hypothesis, since neither
   engine appears in cover_form (both read via their resolvent graphs). *)
let COVER_SEM = prove
 (`!D (E:A->A->bool) onebee sa rL rc v0 b.
      model D E ZF_AX /\ onebee IN D /\ eordinal D E sa /\
      rL IN D /\ rc IN D /\ valuation D v0 /\
      (!pp. pp IN D
            ==> (E pp rL <=>
                 ?b' z'. b' IN D /\ z' IN D /\ E b' sa /\
                         elstage D E b' z' /\ eopair D E b' z' pp)) /\
      (!pp. pp IN D
            ==> (E pp rc <=>
                 ?b' z'. b' IN D /\ z' IN D /\ E b' sa /\
                         echecktower D E onebee b' z' /\
                           eopair D E b' z' pp)) /\
      b IN D /\ E b sa
      ==> (holds D E ((0 |-> b) ((80 |-> rL) ((81 |-> rc) v0))) cover_form <=>
           !yb cd.
              yb IN D /\ cd IN D /\
              elstage D E b yb /\ echecktower D E onebee b cd
              ==> !u. u IN D /\ E u yb
                      ==> ?img. img IN D /\ ?pp. pp IN D /\
                                eopair D E u img pp /\ E pp cd)`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "zf onebeeD ordsa rLD rcD valv0 rLc rcc bD bsa" THEN
  SUBGOAL_THEN `eordinal D (E:A->A->bool) b` ASSUME_TAC THENL
   [ASM_MESON_TAC[EORDINAL_MEMBER]; ALL_TAC] THEN
  SUBGOAL_THEN
    `valuation D ((0 |-> (b:A)) ((80 |-> (rL:A)) ((81 |-> (rc:A)) v0)))`
  ASSUME_TAC THENL [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;
    `(0 |-> (b:A)) ((80 |-> (rL:A)) ((81 |-> (rc:A)) v0))`]
        HOLDS_COVER_FORM) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  REWRITE_TAC[VALMOD; ARITH_EQ] THEN
  EQ_TAC THENL
   [INTRO_TAC "@yL. yLD eaL @stg. stgD eac cov" THEN
    SUBGOAL_THEN `elstage D (E:A->A->bool) b yL` ASSUME_TAC THENL
     [MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`elstage D (E:A->A->bool)`;
        `sa:A`;`rL:A`;`b:A`;`yL:A`] EGRAPH_APPLY) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> MP_TAC(EQ_MP th
        (ASSUME `eapply D (E:A->A->bool) rL b yL`))) THEN
      DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC ACCEPT_TAC);
      ALL_TAC] THEN
    SUBGOAL_THEN `echecktower D (E:A->A->bool) onebee b stg` ASSUME_TAC THENL
     [MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;
        `echecktower D (E:A->A->bool) onebee`;`sa:A`;`rc:A`;`b:A`;`stg:A`]
        EGRAPH_APPLY) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> MP_TAC(EQ_MP th
        (ASSUME `eapply D (E:A->A->bool) rc b stg`))) THEN
      DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC ACCEPT_TAC);
      ALL_TAC] THEN
    MAP_EVERY X_GEN_TAC [`yb:A`;`cd:A`] THEN STRIP_TAC THEN
    SUBGOAL_THEN `yb:A = yL` SUBST_ALL_TAC THENL
     [ASM_MESON_TAC[ELSTAGE_UNIQUE]; ALL_TAC] THEN
    SUBGOAL_THEN `cd:A = stg` SUBST_ALL_TAC THENL
     [ASM_MESON_TAC[ECHECKTOWER_UNIQUE]; ALL_TAC] THEN
    USE_THEN "cov" ACCEPT_TAC;
    DISCH_THEN(LABEL_TAC "sem") THEN
    MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`b:A`] ELSTAGE_EXISTS) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(X_CHOOSE_THEN `yL:A` STRIP_ASSUME_TAC) THEN
    MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`onebee:A`;`b:A`]
      ECHECKTOWER_EXISTS) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(X_CHOOSE_THEN `stg:A` STRIP_ASSUME_TAC) THEN
    EXISTS_TAC `yL:A` THEN ASM_REWRITE_TAC[] THEN
    SUBGOAL_THEN `eapply D (E:A->A->bool) rL b yL` ASSUME_TAC THENL
     [MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`elstage D (E:A->A->bool)`;
        `sa:A`;`rL:A`;`b:A`;`yL:A`] EGRAPH_APPLY) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    ASM_REWRITE_TAC[] THEN EXISTS_TAC `stg:A` THEN ASM_REWRITE_TAC[] THEN
    SUBGOAL_THEN `eapply D (E:A->A->bool) rc b stg` ASSUME_TAC THENL
     [MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;
        `echecktower D (E:A->A->bool) onebee`;`sa:A`;`rc:A`;`b:A`;`stg:A`]
        EGRAPH_APPLY) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    ASM_REWRITE_TAC[] THEN
    USE_THEN "sem" MATCH_MP_TAC THEN ASM_REWRITE_TAC[]]);;

(* COVER_STEP: the transfinite-induction STEP for EXHAUSTION (pure semantics,
   no object formula).  Given the coverage IH at every ordinal b'<d -- every
   member of L(b') has a check-name at stage b' (i.e. lies in dom(cd_{b'})) --
   coverage holds at d.

   PROOF SKELETON (non-wf-safe; no meta-induction):
   * u IN L(d) = Def(wL),
   wL = UNION_{c<d} L(c)  (ELSTAGE_CHAR + EDEF_MEMBER_SUBSET
     => u SUBSET wL);
   * every y IN u lies in some L(c), c<d (wL char);
   by the IH y has a check-name
     at stage c, so the PAIR (y, y^) IN cd_c, hence IN gacc_d (gacc char, c<d),
     so y IN dom(gacc_d) = w_d^chk;  thus u SUBSET w_d^chk;
   * build the check-image of u over gacc_d (ECHKIMG_EXISTS), pair it (EOPAIR),
     and land the pair in cd_d by the backward direction of ECHECKTOWER_CHAR's
     stage characterisation.  Mirror in spirit of GOODCHECK_STEP. *)
let COVER_STEP = prove
 (`!D (E:A->A->bool) onebee d.
      model D E ZF_AX /\ onebee IN D /\ eordinal D E d /\
      (!b'. b' IN D /\ E b' d
            ==> !yb cd.
                   yb IN D /\ cd IN D /\
                   elstage D E b' yb /\ echecktower D E onebee b' cd
                   ==> !u. u IN D /\ E u yb
                           ==> ?img. img IN D /\ ?pp. pp IN D /\
                                     eopair D E u img pp /\ E pp cd)
      ==> !yd cd.
             yd IN D /\ cd IN D /\
             elstage D E d yd /\ echecktower D E onebee d cd
             ==> !u. u IN D /\ E u yd
                     ==> ?img. img IN D /\ ?pp. pp IN D /\
                               eopair D E u img pp /\ E pp cd`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "modl oneD dord IH" THEN
  MAP_EVERY X_GEN_TAC [`yd:A`;`cd:A`] THEN
  INTRO_TAC "ydD cdD lstg cstg" THEN
  X_GEN_TAC `u:A` THEN
  DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "uD") (LABEL_TAC "uyd")) THEN
  (* L-stage characterisation: yd = Def(wL), wL = UNION_{c<d} L(c) *)
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`d:A`;`yd:A`] ELSTAGE_CHAR) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `wL:A` (CONJUNCTS_THEN2 (LABEL_TAC "wLD")
    (CONJUNCTS_THEN2 (LABEL_TAC "wLc") (LABEL_TAC "defwL")))) THEN
  (* u SUBSET wL *)
  SUBGOAL_THEN `esubset D (E:A->A->bool) u wL` (LABEL_TAC "usub") THENL
   [MATCH_MP_TAC EDEF_MEMBER_SUBSET THEN EXISTS_TAC `yd:A` THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* check-stage characterisation at d: gacc_d, w_d = dom(gacc_d), cd graph *)
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`onebee:A`;`d:A`;`cd:A`]
        ECHECKTOWER_CHAR) THEN
  ASM_REWRITE_TAC[] THEN
  INTRO_TAC "@gacc w. gaccD wD gaccch domn cdch" THEN
  (* KEY: u SUBSET w_d^chk (= dom gacc_d), via the IH *)
  SUBGOAL_THEN `esubset D (E:A->A->bool) u w` (LABEL_TAC "uSubW") THENL
   [REWRITE_TAC[esubset] THEN X_GEN_TAC `y:A` THEN STRIP_TAC THEN
    SUBGOAL_THEN `(E:A->A->bool) y wL` (LABEL_TAC "eywL") THENL
     [UNDISCH_TAC `esubset D (E:A->A->bool) u wL` THEN
      REWRITE_TAC[esubset] THEN
      DISCH_THEN MATCH_MP_TAC THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    (* extract y IN some L(c), c<d, WITHOUT letting ASM_REWRITE use wLc to
       trivialise the biconditional -- pull RHS via EQ_MP against eywL. *)
    USE_THEN "wLc" (MP_TAC o SPEC `y:A`) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> USE_THEN "eywL" (fun e ->
      X_CHOOSE_THEN `c:A` (X_CHOOSE_THEN `z:A`
        (fun t -> MAP_EVERY ASSUME_TAC (CONJUNCTS t))) (EQ_MP th e))) THEN
    SUBGOAL_THEN `eordinal D (E:A->A->bool) c` ASSUME_TAC THENL
     [ASM_MESON_TAC[EORDINAL_MEMBER]; ALL_TAC] THEN
    MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`onebee:A`;`c:A`]
          ECHECKTOWER_EXISTS) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(X_CHOOSE_THEN `cdc:A` (CONJUNCTS_THEN2 (LABEL_TAC "cdcD")
      (LABEL_TAC "cstgc"))) THEN
    USE_THEN "IH" (MP_TAC o SPEC `c:A`) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(MP_TAC o SPECL [`z:A`;`cdc:A`]) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(MP_TAC o SPEC `y:A`) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(X_CHOOSE_THEN `imgy:A` (CONJUNCTS_THEN2 (LABEL_TAC "imgyD")
      (X_CHOOSE_THEN `ppy:A`
       (fun th -> MAP_EVERY ASSUME_TAC (CONJUNCTS th))))) THEN
    (* (y,imgy) = ppy IN cd_c, hence IN gacc_d since c<d *)
    SUBGOAL_THEN `(E:A->A->bool) ppy gacc` ASSUME_TAC THENL
     [USE_THEN "gaccch" (MP_TAC o SPEC `ppy:A`) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
      MAP_EVERY EXISTS_TAC [`c:A`;`cdc:A`] THEN ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    (* y IN dom(gacc_d) = w_d^chk *)
    USE_THEN "domn"
      (MP_TAC o SPEC `y:A` o CONJUNCT2 o REWRITE_RULE[edomain]) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    REWRITE_TAC[eindom] THEN EXISTS_TAC `imgy:A` THEN ASM_REWRITE_TAC[] THEN
    REWRITE_TAC[eapply] THEN EXISTS_TAC `ppy:A` THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  (* build the check-image of u over gacc_d, pair it, land it in cd_d *)
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`u:A`;`gacc:A`;`onebee:A`]
        ECHKIMG_EXISTS) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `img:A` (CONJUNCTS_THEN2 (LABEL_TAC "imgD")
    (LABEL_TAC "imgch"))) THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`u:A`;`img:A`] EOPAIR_EXISTS) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `pp:A` (LABEL_TAC "pairpp")) THEN
  SUBGOAL_THEN `(pp:A) IN D` (LABEL_TAC "ppD") THENL
   [ASM_MESON_TAC[EOPAIR_IN]; ALL_TAC] THEN
  EXISTS_TAC `img:A` THEN ASM_REWRITE_TAC[] THEN
  EXISTS_TAC `pp:A` THEN ASM_REWRITE_TAC[] THEN
  USE_THEN "cdch" (MP_TAC o SPEC `pp:A`) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  EXISTS_TAC `u:A` THEN ASM_REWRITE_TAC[] THEN
  EXISTS_TAC `img:A` THEN ASM_REWRITE_TAC[]);;

(* ECHECK_EXHAUSTION: every x IN D has a check-name (totality of the check-name
   map), under the V=L hypothesis `!u. u IN D ==> elmem D E u`.  This finishes
   F3d part 2 and hence milestone F3.

   Structural twin of ECHECK_IS_BNAME, but the object formula cover_form
   reads BOTH towers semantically -- the L-tower via rL at slot 80 and the
   check-tower via rc at slot 81 -- and concludes coverage (a check-name pair
   at the stage) rather than "the stage's pairs are B-names".  No
     slot 2 needed:
   onebee lives only inside rc's construction.

   x IN L(a) for some ordinal a (V=L).  Build rL, rc up to sa=esuc a; prove
   the cover-semantic statement holds at every ordinal below sa by
   least-counterexample (EORDINAL_LEAST on `Not cover_form`,
   COVER_SEM to bridge
   holds<->coverage, COVER_STEP for the step, EORDINAL_TRICHOTOMY to place the
   least counterexample below sa); instantiate at a; feed x (E x y) to get the
   pair (x,img) IN cd_a; ECHECK_STAGE lands the check-name.
   NON-WELLFOUNDED-SAFE: induction over the OBJECT formula cover_form via
   EORDINAL_LEAST, never meta-level HOL induction. *)
let ECHECK_EXHAUSTION = prove
 (`!D (E:A->A->bool) onebee x.
      model D E ZF_AX /\ onebee IN D /\
      (!u. u IN D ==> elmem D E u) /\ x IN D
      ==> ?v. echeck D E onebee x v`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "modl oneD vl xD" THEN
  (* x IN some L(a) *)
  USE_THEN "vl" (MP_TAC o SPEC `x:A`) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  REWRITE_TAC[elmem] THEN
  DISCH_THEN(X_CHOOSE_THEN `a:A` (X_CHOOSE_THEN `y:A`
    (fun th -> MAP_EVERY ASSUME_TAC (CONJUNCTS th)))) THEN
  (* sa = esuc a *)
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`a:A`] ESUC_EXISTS) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_TAC `sa:A`) THEN
  SUBGOAL_THEN `(sa:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[ESUC_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `eordinal D (E:A->A->bool) sa` ASSUME_TAC THENL
   [ASM_MESON_TAC[EORDINAL_ESUC]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) a sa` ASSUME_TAC THENL
   [ASM_MESON_TAC[ESUC_MEMBER]; ALL_TAC] THEN
  (* resolvent graph rL for the L-tower at sa *)
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`sa:A`] ELSTAGE_RESGRAPH) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `rL:A` (CONJUNCTS_THEN2 (LABEL_TAC "rLD")
    (LABEL_TAC "rLc"))) THEN
  (* resolvent graph rc for the check-tower at sa *)
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`onebee:A`;`sa:A`]
    ECHECKTOWER_RESGRAPH) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `rc:A` (CONJUNCTS_THEN2 (LABEL_TAC "rcD")
    (LABEL_TAC "rcc"))) THEN
  FIRST_ASSUM(X_CHOOSE_TAC `v0:num->A` o MATCH_MP VALUATION_EXISTS o
              MATCH_MP MODEL_NONEMPTY) THEN
  SUBGOAL_THEN `valuation D ((80 |-> (rL:A)) ((81 |-> (rc:A)) v0))`
  ASSUME_TAC THENL [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
  (* cover-semantic holds at every ordinal below sa *)
  SUBGOAL_THEN
   `!dd. dd IN D /\ E dd sa
         ==> holds D E ((0 |-> dd) ((80 |-> (rL:A)) ((81 |-> (rc:A)) v0)))
                       cover_form`
  (LABEL_TAC "cov") THENL
   [GEN_TAC THEN STRIP_TAC THEN
    MATCH_MP_TAC(TAUT `(~p ==> F) ==> p`) THEN
    DISCH_THEN(LABEL_TAC "bad0") THEN
    SUBGOAL_THEN `eordinal D (E:A->A->bool) dd` ASSUME_TAC THENL
     [ASM_MESON_TAC[EORDINAL_MEMBER]; ALL_TAC] THEN
    MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`Not cover_form`;
                  `(80 |-> (rL:A)) ((81 |-> (rc:A)) v0)`;`dd:A`]
      EORDINAL_LEAST) THEN
    ASM_REWRITE_TAC[HOLDS_NOT] THEN
    DISCH_THEN(X_CHOOSE_THEN `d:A` (CONJUNCTS_THEN2 ASSUME_TAC
      (CONJUNCTS_THEN2 ASSUME_TAC (CONJUNCTS_THEN2 (LABEL_TAC "dbad")
        (LABEL_TAC "dmin"))))) THEN
    SUBGOAL_THEN `(d:A) IN D` ASSUME_TAC THENL
     [ASM_MESON_TAC[EORDINAL_IN]; ALL_TAC] THEN
    SUBGOAL_THEN `(E:A->A->bool) d sa` ASSUME_TAC THENL
     [MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`d:A`;`dd:A`]
        EORDINAL_TRICHOTOMY) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(REPEAT_TCL DISJ_CASES_THEN ASSUME_TAC) THENL
       [ASM_MESON_TAC[EORDINAL_TRANS_E];
        ASM_MESON_TAC[];
        USE_THEN "dmin" (MP_TAC o SPEC `dd:A`) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
        USE_THEN "bad0" (fun th -> REWRITE_TAC[th])];
      ALL_TAC] THEN
    (* IH: coverage holds at every b' < d *)
    SUBGOAL_THEN
     `!b'. b' IN D /\ (E:A->A->bool) b' d
           ==> !yb cd.
                  yb IN D /\ cd IN D /\
                  elstage D E b' yb /\ echecktower D E onebee b' cd
                  ==> !u. u IN D /\ E u yb
                          ==> ?img. img IN D /\ ?pp. pp IN D /\
                                    eopair D E u img pp /\ E pp cd`
    ASSUME_TAC THENL
     [X_GEN_TAC `b':A` THEN STRIP_TAC THEN
      SUBGOAL_THEN `(E:A->A->bool) b' sa` ASSUME_TAC THENL
       [ASM_MESON_TAC[EORDINAL_TRANS_E]; ALL_TAC] THEN
      MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`onebee:A`;`sa:A`;`rL:A`;`rc:A`;
                    `v0:num->A`;`b':A`] COVER_SEM) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(MP_TAC o fst o EQ_IMP_RULE) THEN
      ANTS_TAC THENL
       [USE_THEN "dmin" (MP_TAC o SPEC `b':A`) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC];
        DISCH_THEN ACCEPT_TAC];
      ALL_TAC] THEN
    (* coverage holds at d (COVER_STEP), contradicting dbad *)
    SUBGOAL_THEN
     `holds D E ((0 |-> (d:A)) ((80 |-> (rL:A)) ((81 |-> (rc:A)) v0)))
                cover_form`
    MP_TAC THENL
     [MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`onebee:A`;`sa:A`;`rL:A`;`rc:A`;
                    `v0:num->A`;`d:A`] COVER_SEM) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
      MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`onebee:A`;`d:A`]
             COVER_STEP) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC];
      USE_THEN "dbad" (fun th -> REWRITE_TAC[th])];
    ALL_TAC] THEN
  (* instantiate coverage at a and feed x *)
  USE_THEN "cov" (MP_TAC o SPEC `a:A`) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_TAC THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`onebee:A`;`sa:A`;`rL:A`;`rc:A`;
                `v0:num->A`;`a:A`] COVER_SEM) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(MP_TAC o fst o EQ_IMP_RULE) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(LABEL_TAC "cova") THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`onebee:A`;`a:A`]
    ECHECKTOWER_EXISTS) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `cda:A` (CONJUNCTS_THEN2 (LABEL_TAC "cdaD")
    (LABEL_TAC "cstga"))) THEN
  USE_THEN "cova" (MP_TAC o SPECL [`y:A`;`cda:A`]) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(MP_TAC o SPEC `x:A`) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `img:A` (CONJUNCTS_THEN2 (LABEL_TAC "imgD")
    (X_CHOOSE_THEN `pp:A`
     (fun th -> MAP_EVERY ASSUME_TAC (CONJUNCTS th))))) THEN
  EXISTS_TAC `img:A` THEN
  MATCH_MP_TAC ECHECK_STAGE THEN
  MAP_EVERY EXISTS_TAC [`a:A`;`cda:A`;`pp:A`] THEN
  ASM_REWRITE_TAC[]);;

(* ================================================================= *)
(* F4: complete-Boolean-algebra toolkit.                              *)
(* Boolean-value recursion (F4) needs, over and above the cba block:  *)
(*  - uniqueness of complements (=> step single-valuedness later),    *)
(*  - Boolean implication  p => q := (compl p) join q,                *)
(*  - existence of GLBs (ecba only postulates LUBs).                  *)
(* All are model-internal and reused in F5 (V^B |= ZFC) and F7.       *)
(* ================================================================= *)

(* meet/join are symmetric in their two operands (glb/lub are). *)
let EMEET_SYM = prove
 (`!D (E:A->A->bool) p leq x y z.
        emeet D E p leq x y z ==> emeet D E p leq y x z`,
  REWRITE_TAC[emeet] THEN MESON_TAC[]);;

let EJOIN_SYM = prove
 (`!D (E:A->A->bool) p leq x y z.
        ejoin D E p leq x y z ==> ejoin D E p leq y x z`,
  REWRITE_TAC[ejoin] THEN MESON_TAC[]);;

(* meet with top is the element; join with bot is the element. *)
let EMEET_TOP = prove
 (`!D (E:A->A->bool) p leq u x.
        eporder D E p leq /\ etop D E p leq u /\ x IN D /\ E x p
        ==> emeet D E p leq x u x`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[emeet] THEN
  ASM_MESON_TAC[EPORDER_REFL; ETOP_GE]);;

let EJOIN_BOT = prove
 (`!D (E:A->A->bool) p leq z x.
        eporder D E p leq /\ ebot D E p leq z /\ x IN D /\ E x p
        ==> ejoin D E p leq z x x`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[ejoin] THEN
  ASM_MESON_TAC[EPORDER_REFL; EBOT_LE]);;

(* the one distributive law, projected out of ebalg. *)
let EBALG_DISTRIB = prove
 (`!D (E:A->A->bool) p leq x y w a b c d e.
        ebalg D E p leq /\
        x IN D /\ y IN D /\ w IN D /\ E x p /\ E y p /\ E w p /\
        ejoin D E p leq y w a /\ emeet D E p leq x a b /\
        emeet D E p leq x y c /\ emeet D E p leq x w d /\
        ejoin D E p leq c d e
        ==> b = e`,
  REWRITE_TAC[ebalg] THEN MESON_TAC[]);;

(* absorption: if y meets x to bot and x joins y' to top, then y meets y' to y.
   (y = y/\top = y/\(x\/y') = (y/\x)\/(y/\y') = bot\/(y/\y') =
     y/\y'.)         *)
let ECOMPL_ABSORB = prove
 (`!D (E:A->A->bool) p leq x y y' bot top.
      ebalg D E p leq /\ x IN D /\ y IN D /\ y' IN D /\
      E x p /\ E y p /\ E y' p /\
      ebot D E p leq bot /\ etop D E p leq top /\
      emeet D E p leq x y bot /\ ejoin D E p leq x y' top
      ==> emeet D E p leq y y' y`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `eporder D (E:A->A->bool) p leq` ASSUME_TAC THENL
   [ASM_MESON_TAC[EBALG_IMP_PORDER]; ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`p:A`;`leq:A`;`y:A`;`y':A`]
        EBALG_MEET) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `d:A`) THEN
  SUBGOAL_THEN `(d:A) IN D /\ (E:A->A->bool) d p` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[EMEET_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `emeet D (E:A->A->bool) p leq y x bot` ASSUME_TAC THENL
   [ASM_MESON_TAC[EMEET_SYM]; ALL_TAC] THEN
  SUBGOAL_THEN `emeet D (E:A->A->bool) p leq y top y` ASSUME_TAC THENL
   [ASM_MESON_TAC[EMEET_TOP]; ALL_TAC] THEN
  SUBGOAL_THEN `ejoin D (E:A->A->bool) p leq bot d d` ASSUME_TAC THENL
   [ASM_MESON_TAC[EJOIN_BOT]; ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`p:A`;`leq:A`;
                `y:A`;`x:A`;`y':A`;`top:A`;`y:A`;`bot:A`;`d:A`;`d:A`]
        EBALG_DISTRIB) THEN
  ASM_REWRITE_TAC[] THEN DISCH_TAC THEN ASM_MESON_TAC[]);;

(* a complement's meet is exactly bot and join is exactly top. *)
let ECOMPL_MEET_JOIN = prove
 (`!D (E:A->A->bool) p leq x y bot top.
      eporder D E p leq /\ ecompl D E p leq x y /\
      ebot D E p leq bot /\ etop D E p leq top
      ==> emeet D E p leq x y bot /\ ejoin D E p leq x y top`,
  REPEAT GEN_TAC THEN REWRITE_TAC[ecompl] THEN STRIP_TAC THEN
  SUBGOAL_THEN `z:A = bot` SUBST_ALL_TAC THENL
   [ASM_MESON_TAC[EBOT_UNIQUE]; ALL_TAC] THEN
  SUBGOAL_THEN `u:A = top` SUBST_ALL_TAC THENL
   [ASM_MESON_TAC[ETOP_UNIQUE]; ALL_TAC] THEN
  ASM_REWRITE_TAC[]);;

(* complement is unique in a Boolean algebra. *)
let ECOMPL_UNIQUE = prove
 (`!D (E:A->A->bool) p leq x y y'.
      ebalg D E p leq /\ x IN D /\ E x p /\
      ecompl D E p leq x y /\ ecompl D E p leq x y'
      ==> y = y'`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `eporder D (E:A->A->bool) p leq` ASSUME_TAC THENL
   [ASM_MESON_TAC[EBALG_IMP_PORDER]; ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`p:A`;`leq:A`] EBALG_BOT) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `bot:A`) THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`p:A`;`leq:A`] EBALG_TOP) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `top:A`) THEN
  SUBGOAL_THEN `(y:A) IN D /\ (E:A->A->bool) y p /\ (y':A) IN D /\ E y' p`
  STRIP_ASSUME_TAC THENL [ASM_MESON_TAC[ECOMPL_IN]; ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`p:A`;`leq:A`;`x:A`;`y:A`;
                `bot:A`;`top:A`] ECOMPL_MEET_JOIN) THEN
  ASM_REWRITE_TAC[] THEN STRIP_TAC THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`p:A`;`leq:A`;`x:A`;`y':A`;
                `bot:A`;`top:A`] ECOMPL_MEET_JOIN) THEN
  ASM_REWRITE_TAC[] THEN STRIP_TAC THEN
  SUBGOAL_THEN `emeet D (E:A->A->bool) p leq y y' y` ASSUME_TAC THENL
   [MATCH_MP_TAC ECOMPL_ABSORB THEN
    MAP_EVERY EXISTS_TAC [`x:A`;`bot:A`;`top:A`] THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `emeet D (E:A->A->bool) p leq y' y y'` ASSUME_TAC THENL
   [MATCH_MP_TAC ECOMPL_ABSORB THEN
    MAP_EVERY EXISTS_TAC [`x:A`;`bot:A`;`top:A`] THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `emeet D (E:A->A->bool) p leq y y' y'` ASSUME_TAC THENL
   [ASM_MESON_TAC[EMEET_SYM]; ALL_TAC] THEN
  ASM_MESON_TAC[EMEET_UNIQUE]);;

(* ---- Boolean implication  p => q := (compl p) join q ---- *)
let ebimp = new_definition
  `ebimp D (E:A->A->bool) p leq x y z <=>
        ?c. ecompl D E p leq x c /\ ejoin D E p leq c y z`;;

let EBIMP_IN = prove
 (`!D (E:A->A->bool) p leq x y z. ebimp D E p leq x y z ==> z IN D /\ E z p`,
  REWRITE_TAC[ebimp] THEN MESON_TAC[EJOIN_IN]);;

let EBIMP_EXISTS = prove
 (`!D (E:A->A->bool) p leq x y.
      ebalg D E p leq /\ x IN D /\ y IN D /\ E x p /\ E y p
      ==> ?z. ebimp D E p leq x y z`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[ebimp] THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`p:A`;`leq:A`;`x:A`]
        EBALG_COMPL) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `c:A`) THEN
  SUBGOAL_THEN `(c:A) IN D /\ (E:A->A->bool) c p` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[ECOMPL_IN]; ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`p:A`;`leq:A`;`c:A`;`y:A`]
        EBALG_JOIN) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `z:A`) THEN
  MAP_EVERY EXISTS_TAC [`z:A`;`c:A`] THEN ASM_REWRITE_TAC[]);;

let EBIMP_UNIQUE = prove
 (`!D (E:A->A->bool) p leq x y z z'.
      ebalg D E p leq /\ x IN D /\ E x p /\
      ebimp D E p leq x y z /\ ebimp D E p leq x y z'
      ==> z = z'`,
  REPEAT GEN_TAC THEN REWRITE_TAC[ebimp] THEN STRIP_TAC THEN
  SUBGOAL_THEN `eporder D (E:A->A->bool) p leq` ASSUME_TAC THENL
   [ASM_MESON_TAC[EBALG_IMP_PORDER]; ALL_TAC] THEN
  SUBGOAL_THEN `c':A = c` SUBST_ALL_TAC THENL
   [ASM_MESON_TAC[ECOMPL_UNIQUE]; ALL_TAC] THEN
  ASM_MESON_TAC[EJOIN_UNIQUE]);;

(* ecba only postulates SUP of every subset; here we derive INF from it, via
   the lower-bound set  LB = {x IN p : !y IN s. x <= y}  (carved by
   separation with the formula  !!- 5 3 (rel_form 4 1 5): slot 1 =
     x, slot 3 = s,
   slot 4 = leq) and then  glb s = lub LB
     (ECBA_SUP).                        *)
let ECBA_INF = prove
 (`!D (E:A->A->bool) p leq s.
      model D E ZF_AX /\ ecba D E p leq /\ p IN D /\ leq IN D /\
      s IN D /\ esubset D E s p
      ==> ?u. eglb D E p leq s u`,
  REPEAT STRIP_TAC THEN
  FIRST_ASSUM(X_CHOOSE_TAC `v0:num->A` o MATCH_MP VALUATION_EXISTS o
              MATCH_MP MODEL_NONEMPTY) THEN
  ABBREV_TAC `v = (3 |-> (s:A)) ((4 |-> (leq:A)) v0)` THEN
  SUBGOAL_THEN
   `valuation D (v:num->A) /\ (v:num->A) 3 = s /\ (v:num->A) 4 = leq`
  STRIP_ASSUME_TAC THENL
   [EXPAND_TAC "v" THEN REPEAT CONJ_TAC THENL
     [ASM_MESON_TAC[VALUATION_VALMOD];
      REWRITE_TAC[VALMOD];
      REWRITE_TAC[VALMOD; ARITH_EQ]];
    ALL_TAC] THEN
  MP_TAC(SPECL [`!!- 5 3 (rel_form 4 1 5)`; `1`; `v:num->A`; `p:A`]
    (MATCH_MP ZF_SEPARATION (ASSUME `model D (E:A->A->bool) ZF_AX`))) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `LB:A`
    (CONJUNCTS_THEN2 ASSUME_TAC (LABEL_TAC "lb"))) THEN
  SUBGOAL_THEN
   `!z. z IN D
        ==> (holds D E ((1 |-> (z:A)) v) (!!- 5 3 (rel_form 4 1 5)) <=>
             !a. a IN D /\ E a s ==> erel D E leq z a)`
  (LABEL_TAC "phi") THENL
   [X_GEN_TAC `z:A` THEN DISCH_TAC THEN
    SUBGOAL_THEN `valuation D ((1 |-> (z:A)) v)` ASSUME_TAC THENL
     [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
    MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`(1 |-> (z:A)) v`;`5`;`3`;
                  `rel_form 4 1 5`] HOLDS_FORALLMEM) THEN
    ANTS_TAC THENL [ARITH_TAC; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    SUBGOAL_THEN `((1 |-> (z:A)) v) 3 = s` SUBST1_TAC THENL
     [REWRITE_TAC[VALMOD; ARITH_EQ] THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN
     `!a. a IN D
          ==> (holds D E ((5 |-> (a:A)) ((1 |-> (z:A)) v)) (rel_form 4 1 5) <=>
               erel D E leq z a)`
    ASSUME_TAC THENL
     [X_GEN_TAC `a:A` THEN DISCH_TAC THEN
      SUBGOAL_THEN `valuation D ((5 |-> (a:A)) ((1 |-> (z:A)) v))`
      ASSUME_TAC THENL [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
      MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;
                    `(5 |-> (a:A)) ((1 |-> (z:A)) v)`;`4`;`1`;`5`]
            HOLDS_REL_FORM) THEN
      ASM_REWRITE_TAC[] THEN DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
      REWRITE_TAC[VALMOD; ARITH_EQ] THEN ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    ASM_MESON_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!z. z IN D
        ==> ((E:A->A->bool) z LB <=>
             E z p /\ (!a. a IN D /\ E a s ==> erel D E leq z a))`
  (LABEL_TAC "mem") THENL
   [X_GEN_TAC `z:A` THEN DISCH_TAC THEN ASM_MESON_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `esubset D (E:A->A->bool) LB p` ASSUME_TAC THENL
   [REWRITE_TAC[esubset] THEN X_GEN_TAC `z:A` THEN STRIP_TAC THEN
    ASM_MESON_TAC[]; ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`p:A`;`leq:A`;`LB:A`] ECBA_SUP) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `u:A`) THEN
  SUBGOAL_THEN `(u:A) IN D /\ (E:A->A->bool) u p` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[ELUB_IN]; ALL_TAC] THEN
  EXISTS_TAC `u:A` THEN REWRITE_TAC[eglb] THEN CONJ_TAC THENL
   [REWRITE_TAC[elbound] THEN ASM_REWRITE_TAC[] THEN
    X_GEN_TAC `x:A` THEN STRIP_TAC THEN
    SUBGOAL_THEN `(E:A->A->bool) x p` ASSUME_TAC THENL
     [ASM_MESON_TAC[esubset]; ALL_TAC] THEN
    SUBGOAL_THEN `eubound D (E:A->A->bool) p leq LB x` ASSUME_TAC THENL
     [REWRITE_TAC[eubound] THEN ASM_REWRITE_TAC[] THEN
      X_GEN_TAC `w:A` THEN STRIP_TAC THEN ASM_MESON_TAC[];
      ASM_MESON_TAC[ELUB_LEAST]];
    X_GEN_TAC `w:A` THEN REWRITE_TAC[elbound] THEN STRIP_TAC THEN
    SUBGOAL_THEN `(E:A->A->bool) w LB` ASSUME_TAC THENL
     [USE_THEN "mem" (MP_TAC o SPEC `w:A`) THEN ASM_MESON_TAC[];
      ASM_MESON_TAC[ELUB_UB]]]);;

(* ===================================================================== *)
(* F4: bmeet_form / bjoin_form.                                          *)
(*   Boolean MEET and JOIN rendered as OBJECT formulas, each with an FV  *)
(*   computation and a HOLDS_* semantic characterisation (against the    *)
(*   emeet / ejoin predicates of the INC1 Boolean-algebra toolkit).      *)
(*   Both are built solely from the five primitive constructors via the  *)
(*   macros %%, &&, --> , rel_form (the order <=) and the bounded        *)
(*   universal !!- : NO new object constructor is introduced.  A single  *)
(*   fresh witness variable  ww = MAX(MAX leq b)(MAX(MAX i j)k)+1  names  *)
(*   the bound "w" in the greatest-lower / least-upper clause; it is     *)
(*   provably distinct from leq,b,i,j,k, so FV drops it and the HOLDS    *)
(*   valuation-updates on it are transparent.                            *)
(*   Consumed by the [[u=v]]/[[u IN v]] recursion (INC3) and V^B|=ZFC.   *)
(* ===================================================================== *)

let bmeet_form = new_definition
  `bmeet_form leq b i j k =
     (k %% b) &&
     rel_form leq k i && rel_form leq k j &&
     !!- (MAX (MAX leq b) (MAX (MAX i j) k) + 1) b
         (rel_form leq (MAX (MAX leq b) (MAX (MAX i j) k) + 1) i &&
          rel_form leq (MAX (MAX leq b) (MAX (MAX i j) k) + 1) j
          --> rel_form leq (MAX (MAX leq b) (MAX (MAX i j) k) + 1) k)`;;

let FV_BMEET_FORM = prove
 (`!leq b i j k. FV(bmeet_form leq b i j k) = {leq,b,i,j,k}`,
  REPEAT GEN_TAC THEN
  REWRITE_TAC[bmeet_form] THEN
  ABBREV_TAC `ww = MAX (MAX leq b) (MAX (MAX i j) k) + 1` THEN
  SUBGOAL_THEN
   `~(ww:num = leq) /\ ~(ww = b) /\ ~(ww = i) /\ ~(ww = j) /\ ~(ww = k)`
  STRIP_ASSUME_TAC THENL
   [EXPAND_TAC "ww" THEN ARITH_TAC; ALL_TAC] THEN
  REWRITE_TAC[FV; FV_CLAUSES; FV_REL_FORM] THEN
  REWRITE_TAC[EXTENSION; IN_DELETE; IN_UNION; IN_INSERT; NOT_IN_EMPTY] THEN
  ASM_MESON_TAC[]);;

let HOLDS_BMEET_FORM = prove
 (`!D (E:A->A->bool) v leq b i j k.
        model D E ZF_AX /\ valuation D v
        ==> (holds D E v (bmeet_form leq b i j k) <=>
             emeet D E (v b) (v leq) (v i) (v j) (v k))`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `!x. (v:num->A) x IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[valuation]; ALL_TAC] THEN
  REWRITE_TAC[bmeet_form] THEN
  ABBREV_TAC `ww = MAX (MAX leq b) (MAX (MAX i j) k) + 1` THEN
  SUBGOAL_THEN
   `~(leq:num = ww) /\ ~(b = ww) /\ ~(i = ww) /\ ~(j = ww) /\ ~(k = ww) /\
    ~(ww = b)`
  STRIP_ASSUME_TAC THENL
   [EXPAND_TAC "ww" THEN ARITH_TAC; ALL_TAC] THEN
  SUBGOAL_THEN
   `holds D (E:A->A->bool) v
     (!!- ww b
         (rel_form leq ww i && rel_form leq ww j --> rel_form leq ww k)) <=>
    (!a. a IN D /\ E a (v b)
         ==> (erel D E (v leq) a (v i) /\ erel D E (v leq) a (v j)
              ==> erel D E (v leq) a (v k)))`
  (LABEL_TAC "fa") THENL
   [ASM_SIMP_TAC[HOLDS_FORALLMEM] THEN
    AP_TERM_TAC THEN ABS_TAC THEN
    ASM_CASES_TAC `(a:A) IN D` THENL
     [SUBGOAL_THEN `valuation D ((ww |-> (a:A)) v)` ASSUME_TAC THENL
       [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
      ASM_REWRITE_TAC[holds; HOLDS_AND] THEN
      ASM_SIMP_TAC[HOLDS_REL_FORM] THEN
      ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER];
      ASM_REWRITE_TAC[]];
    ALL_TAC] THEN
  REWRITE_TAC[HOLDS_AND; holds] THEN
  ASM_SIMP_TAC[HOLDS_REL_FORM] THEN
  ASM_REWRITE_TAC[] THEN
  REWRITE_TAC[emeet] THEN
  REWRITE_TAC[IMP_CONJ] THEN
  ASM_REWRITE_TAC[]);;

let bjoin_form = new_definition
  `bjoin_form leq b i j k =
     (k %% b) &&
     rel_form leq i k && rel_form leq j k &&
     !!- (MAX (MAX leq b) (MAX (MAX i j) k) + 1) b
         (rel_form leq i (MAX (MAX leq b) (MAX (MAX i j) k) + 1) &&
          rel_form leq j (MAX (MAX leq b) (MAX (MAX i j) k) + 1)
          --> rel_form leq k (MAX (MAX leq b) (MAX (MAX i j) k) + 1))`;;

let FV_BJOIN_FORM = prove
 (`!leq b i j k. FV(bjoin_form leq b i j k) = {leq,b,i,j,k}`,
  REPEAT GEN_TAC THEN
  REWRITE_TAC[bjoin_form] THEN
  ABBREV_TAC `ww = MAX (MAX leq b) (MAX (MAX i j) k) + 1` THEN
  SUBGOAL_THEN
   `~(ww:num = leq) /\ ~(ww = b) /\ ~(ww = i) /\ ~(ww = j) /\ ~(ww = k)`
  STRIP_ASSUME_TAC THENL
   [EXPAND_TAC "ww" THEN ARITH_TAC; ALL_TAC] THEN
  REWRITE_TAC[FV; FV_CLAUSES; FV_REL_FORM] THEN
  REWRITE_TAC[EXTENSION; IN_DELETE; IN_UNION; IN_INSERT; NOT_IN_EMPTY] THEN
  ASM_MESON_TAC[]);;

let HOLDS_BJOIN_FORM = prove
 (`!D (E:A->A->bool) v leq b i j k.
        model D E ZF_AX /\ valuation D v
        ==> (holds D E v (bjoin_form leq b i j k) <=>
             ejoin D E (v b) (v leq) (v i) (v j) (v k))`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `!x. (v:num->A) x IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[valuation]; ALL_TAC] THEN
  REWRITE_TAC[bjoin_form] THEN
  ABBREV_TAC `ww = MAX (MAX leq b) (MAX (MAX i j) k) + 1` THEN
  SUBGOAL_THEN
   `~(leq:num = ww) /\ ~(b = ww) /\ ~(i = ww) /\ ~(j = ww) /\ ~(k = ww) /\
    ~(ww = b)`
  STRIP_ASSUME_TAC THENL
   [EXPAND_TAC "ww" THEN ARITH_TAC; ALL_TAC] THEN
  SUBGOAL_THEN
   `holds D (E:A->A->bool) v
     (!!- ww b
         (rel_form leq i ww && rel_form leq j ww --> rel_form leq k ww)) <=>
    (!a. a IN D /\ E a (v b)
         ==> (erel D E (v leq) (v i) a /\ erel D E (v leq) (v j) a
              ==> erel D E (v leq) (v k) a))`
  (LABEL_TAC "fa") THENL
   [ASM_SIMP_TAC[HOLDS_FORALLMEM] THEN
    AP_TERM_TAC THEN ABS_TAC THEN
    ASM_CASES_TAC `(a:A) IN D` THENL
     [SUBGOAL_THEN `valuation D ((ww |-> (a:A)) v)` ASSUME_TAC THENL
       [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
      ASM_REWRITE_TAC[holds; HOLDS_AND] THEN
      ASM_SIMP_TAC[HOLDS_REL_FORM] THEN
      ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER];
      ASM_REWRITE_TAC[]];
    ALL_TAC] THEN
  REWRITE_TAC[HOLDS_AND; holds] THEN
  ASM_SIMP_TAC[HOLDS_REL_FORM] THEN
  ASM_REWRITE_TAC[] THEN
  REWRITE_TAC[ejoin] THEN
  REWRITE_TAC[IMP_CONJ] THEN
  ASM_REWRITE_TAC[]);;

(* ================================================================= *)
(* F4: the propositional Boolean                                     *)
(* operations BOTTOM, TOP, COMPLEMENT and IMPLICATION rendered as     *)
(* OBJECT formulas (bbot_form / btop_form / bcompl_form / bimp_form), *)
(* each with an FV computation and a HOLDS_* semantic characterisation *)
(* against the abstract complete-Boolean-algebra predicates            *)
(* ebot / etop / ecompl / ebimp.  Built ONLY from the five primitive   *)
(* constructors via %% (mem), && (And), --> (Imp), rel_form (the order *)
(* <=) and the bounded quantifiers !!- / ??-.  Together with           *)
(* bmeet_form / bjoin_form (INC2a) this completes the propositional    *)
(* fragment needed for the [[u=v]]/[[u IN v]] recursion (INC3).        *)
(* ================================================================= *)

(* --- BOTTOM: k is the least element of <b,leq> --- *)
let bbot_form = new_definition
  `bbot_form leq b k =
     (k %% b) && !!- (MAX (MAX leq b) k + 1) b
                     (rel_form leq k (MAX (MAX leq b) k + 1))`;;

let HOLDS_BBOT_FORM = prove
 (`!D (E:A->A->bool) v leq b k.
        model D E ZF_AX /\ valuation D v
        ==> (holds D E v (bbot_form leq b k) <=>
             ebot D E (v b) (v leq) (v k))`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `!x. (v:num->A) x IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[valuation]; ALL_TAC] THEN
  REWRITE_TAC[bbot_form] THEN
  ABBREV_TAC `ww = MAX (MAX leq b) k + 1` THEN
  SUBGOAL_THEN
   `~(leq:num = ww) /\ ~(b = ww) /\ ~(k = ww) /\ ~(ww = b)`
  STRIP_ASSUME_TAC THENL
   [EXPAND_TAC "ww" THEN ARITH_TAC; ALL_TAC] THEN
  SUBGOAL_THEN
   `holds D (E:A->A->bool) v (!!- ww b (rel_form leq k ww)) <=>
    (!a. a IN D /\ E a (v b) ==> erel D E (v leq) (v k) a)`
  (LABEL_TAC "fa") THENL
   [ASM_SIMP_TAC[HOLDS_FORALLMEM] THEN
    AP_TERM_TAC THEN ABS_TAC THEN
    ASM_CASES_TAC `(a:A) IN D` THENL
     [SUBGOAL_THEN `valuation D ((ww |-> (a:A)) v)` ASSUME_TAC THENL
       [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
      ASM_SIMP_TAC[HOLDS_REL_FORM] THEN
      ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER];
      ASM_REWRITE_TAC[]];
    ALL_TAC] THEN
  REWRITE_TAC[HOLDS_AND; holds] THEN
  ASM_REWRITE_TAC[] THEN
  REWRITE_TAC[ebot] THEN
  ASM_REWRITE_TAC[]);;

(* --- TOP: k is the greatest element of <b,leq> --- *)
let btop_form = new_definition
  `btop_form leq b k =
     (k %% b) && !!- (MAX (MAX leq b) k + 1) b
                     (rel_form leq (MAX (MAX leq b) k + 1) k)`;;

let HOLDS_BTOP_FORM = prove
 (`!D (E:A->A->bool) v leq b k.
        model D E ZF_AX /\ valuation D v
        ==> (holds D E v (btop_form leq b k) <=>
             etop D E (v b) (v leq) (v k))`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `!x. (v:num->A) x IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[valuation]; ALL_TAC] THEN
  REWRITE_TAC[btop_form] THEN
  ABBREV_TAC `ww = MAX (MAX leq b) k + 1` THEN
  SUBGOAL_THEN
   `~(leq:num = ww) /\ ~(b = ww) /\ ~(k = ww) /\ ~(ww = b)`
  STRIP_ASSUME_TAC THENL
   [EXPAND_TAC "ww" THEN ARITH_TAC; ALL_TAC] THEN
  SUBGOAL_THEN
   `holds D (E:A->A->bool) v (!!- ww b (rel_form leq ww k)) <=>
    (!a. a IN D /\ E a (v b) ==> erel D E (v leq) a (v k))`
  (LABEL_TAC "fa") THENL
   [ASM_SIMP_TAC[HOLDS_FORALLMEM] THEN
    AP_TERM_TAC THEN ABS_TAC THEN
    ASM_CASES_TAC `(a:A) IN D` THENL
     [SUBGOAL_THEN `valuation D ((ww |-> (a:A)) v)` ASSUME_TAC THENL
       [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
      ASM_SIMP_TAC[HOLDS_REL_FORM] THEN
      ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER];
      ASM_REWRITE_TAC[]];
    ALL_TAC] THEN
  REWRITE_TAC[HOLDS_AND; holds] THEN
  ASM_REWRITE_TAC[] THEN
  REWRITE_TAC[etop] THEN
  ASM_REWRITE_TAC[]);;

(* --- COMPLEMENT: k is the complement of i in <b,leq>            --- *)
(* --- (?z u. z=bot /\ u=top /\ z = i MEET k /\ u = i JOIN k)     --- *)
let bcompl_form = new_definition
  `bcompl_form leq b i k =
     (k %% b) &&
     ??- (MAX (MAX leq b) (MAX i k) + 1) b
       (??- (MAX (MAX leq b) (MAX i k) + 2) b
         (bbot_form leq b (MAX (MAX leq b) (MAX i k) + 1) &&
          btop_form leq b (MAX (MAX leq b) (MAX i k) + 2) &&
          bmeet_form leq b i k (MAX (MAX leq b) (MAX i k) + 1) &&
          bjoin_form leq b i k (MAX (MAX leq b) (MAX i k) + 2)))`;;

let HOLDS_BCOMPL_FORM = prove
 (`!D (E:A->A->bool) v leq b i k.
        model D E ZF_AX /\ valuation D v
        ==> (holds D E v (bcompl_form leq b i k) <=>
             ecompl D E (v b) (v leq) (v i) (v k))`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `!x. (v:num->A) x IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[valuation]; ALL_TAC] THEN
  REWRITE_TAC[bcompl_form] THEN
  ABBREV_TAC `zz = MAX (MAX leq b) (MAX i k) + 1` THEN
  ABBREV_TAC `uu = MAX (MAX leq b) (MAX i k) + 2` THEN
  SUBGOAL_THEN
   `~(leq:num = zz) /\ ~(b = zz) /\ ~(i = zz) /\ ~(k = zz) /\
    ~(leq = uu) /\ ~(b = uu) /\ ~(i = uu) /\ ~(k = uu) /\
    ~(zz = uu) /\ ~(uu = zz) /\ ~(zz = b) /\ ~(uu = b)`
  STRIP_ASSUME_TAC THENL
   [MAP_EVERY EXPAND_TAC ["zz";"uu"] THEN ARITH_TAC; ALL_TAC] THEN
  SUBGOAL_THEN
   `!az au:A. az IN D /\ au IN D
      ==> (holds D E ((uu |-> au)((zz |-> az) v))
            (bbot_form leq b zz && btop_form leq b uu &&
             bmeet_form leq b i k zz && bjoin_form leq b i k uu) <=>
           ebot D E (v b)(v leq) az /\ etop D E (v b)(v leq) au /\
           emeet D E (v b)(v leq)(v i)(v k) az /\
           ejoin D E (v b)(v leq)(v i)(v k) au)`
  (LABEL_TAC "body") THENL
   [REPEAT STRIP_TAC THEN
    SUBGOAL_THEN `valuation D ((uu |-> (au:A))((zz |-> (az:A)) v))`
      ASSUME_TAC THENL
      [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
    REWRITE_TAC[HOLDS_AND] THEN
    ASM_SIMP_TAC[HOLDS_BBOT_FORM; HOLDS_BTOP_FORM; HOLDS_BMEET_FORM;
                 HOLDS_BJOIN_FORM] THEN
    ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER];
    ALL_TAC] THEN
  REWRITE_TAC[HOLDS_AND; holds] THEN
  ASM_SIMP_TAC[HOLDS_EXISTSMEM] THEN
  ASM_SIMP_TAC[VALMOD_OTHER] THEN
  REWRITE_TAC[ecompl] THEN
  ASM_MESON_TAC[EBOT_IN; ETOP_IN]);;

(* --- IMPLICATION: k = (compl i) JOIN j  (Route 1)              --- *)
let bimp_form = new_definition
  `bimp_form leq b i j k =
     (k %% b) &&
     ??- (MAX (MAX leq b) (MAX (MAX i j) k) + 1) b
       (bcompl_form leq b i (MAX (MAX leq b) (MAX (MAX i j) k) + 1) &&
        bjoin_form leq b (MAX (MAX leq b) (MAX (MAX i j) k) + 1) j k)`;;

let HOLDS_BIMP_FORM = prove
 (`!D (E:A->A->bool) v leq b i j k.
        model D E ZF_AX /\ valuation D v
        ==> (holds D E v (bimp_form leq b i j k) <=>
             ebimp D E (v b) (v leq) (v i) (v j) (v k))`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `!x. (v:num->A) x IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[valuation]; ALL_TAC] THEN
  REWRITE_TAC[bimp_form] THEN
  ABBREV_TAC `cc = MAX (MAX leq b) (MAX (MAX i j) k) + 1` THEN
  SUBGOAL_THEN
   `~(leq:num = cc) /\ ~(b = cc) /\ ~(i = cc) /\ ~(j = cc) /\ ~(k = cc) /\
    ~(cc = b)`
  STRIP_ASSUME_TAC THENL
   [EXPAND_TAC "cc" THEN ARITH_TAC; ALL_TAC] THEN
  SUBGOAL_THEN
   `!ac:A. ac IN D
      ==> (holds D E ((cc |-> ac) v)
            (bcompl_form leq b i cc && bjoin_form leq b cc j k) <=>
           ecompl D E (v b)(v leq)(v i) ac /\
           ejoin D E (v b)(v leq) ac (v j)(v k))`
  (LABEL_TAC "body") THENL
   [REPEAT STRIP_TAC THEN
    SUBGOAL_THEN `valuation D ((cc |-> (ac:A)) v)` ASSUME_TAC THENL
     [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
    REWRITE_TAC[HOLDS_AND] THEN
    ASM_SIMP_TAC[HOLDS_BCOMPL_FORM; HOLDS_BJOIN_FORM] THEN
    ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER];
    ALL_TAC] THEN
  REWRITE_TAC[HOLDS_AND; holds] THEN
  ASM_SIMP_TAC[HOLDS_EXISTSMEM] THEN
  REWRITE_TAC[ebimp] THEN
  ASM_MESON_TAC[ECOMPL_IN; EJOIN_IN]);;

(* ===================================================================== *)
(* F4: the Boolean IN-value  [[u IN v]].                                 *)
(*   With a B-name  v  read as a functional set of pairs <name,B-elt>    *)
(*   (v(y) = the B-value assigned to the sub-name y), and a =-table  t   *)
(*   holding the equality values (t applied at the pair <u,y> yields     *)
(*   [[u=y]]), the membership value is                                   *)
(*        [[u IN v]] = SUP_{y IN dom v} ( v(y)  MEET  [[u=y]] ).          *)
(*   bvcomb c  =  "c is one of the combiners v(y) MEET t(<u,y>)"; the    *)
(*   image set  S = { c : bvcomb c }  (a subset of the carrier B) is     *)
(*   carved by ZF separation via the OBJECT formula bvcomb_form, and the *)
(*   value is its supremum in the complete Boolean algebra (ECBA_SUP).   *)
(*   Consumed by the [[u=v]]/[[u IN v]] recursion (INC3).                *)
(* ===================================================================== *)

(* c is a combiner value  v(y) MEET t(<u,y>)  for some name y in dom v.     *)
(* v = container B-name (functional set of pairs), u = element name,         *)
(* t = the =-table (set-object: pairs <<u,y>, [[u=y]]>). B = carrier, leq =  *)
(* the order.                                                                *)
let bvcomb = new_definition
  `bvcomb D (E:A->A->bool) B leq t v u c <=>
        ?y qy my pr.
            y IN D /\ qy IN D /\ my IN D /\ pr IN D /\
            eapply D E v y qy /\
            eopair D E u y pr /\ eapply D E t pr my /\
            emeet D E B leq qy my c`;;

(* the image set  {c IN D : bvcomb c}  (automatically a subset of B).        *)
let ebvinset = new_definition
  `ebvinset D (E:A->A->bool) B leq t v u S <=>
        S IN D /\
        !c. c IN D ==> (E c S <=> bvcomb D E B leq t v u c)`;;

(* the IN-value  [[u IN v]] = SUP over y in dom v of  v(y) MEET [[u=y]].     *)
let ebvin = new_definition
  `ebvin D (E:A->A->bool) B leq t v u z <=>
        ?S. ebvinset D E B leq t v u S /\ elub D E B leq S z`;;

(* -- cheap destructors / uniqueness ------------------------------------ *)

let BVCOMB_IN = prove
 (`!D (E:A->A->bool) B leq t v u c.
        bvcomb D E B leq t v u c ==> c IN D /\ E c B`,
  REWRITE_TAC[bvcomb] THEN MESON_TAC[EMEET_IN]);;

let EBVINSET_SUBSET = prove
 (`!D (E:A->A->bool) B leq t v u S.
        ebvinset D E B leq t v u S ==> esubset D E S B`,
  REWRITE_TAC[ebvinset; esubset] THEN MESON_TAC[BVCOMB_IN]);;

let EBVINSET_UNIQUE = prove
 (`!D (E:A->A->bool) B leq t v u S S'.
        model D E ZF_AX /\
        ebvinset D E B leq t v u S /\ ebvinset D E B leq t v u S'
        ==> S = S'`,
  REWRITE_TAC[ebvinset] THEN REPEAT STRIP_TAC THEN
  FIRST_ASSUM(MATCH_MP_TAC o MATCH_MP ZF_EXTENSIONALITY) THEN
  ASM_SIMP_TAC[]);;

let EBVIN_IN = prove
 (`!D (E:A->A->bool) B leq t v u z.
        ebvin D E B leq t v u z ==> z IN D /\ E z B`,
  REWRITE_TAC[ebvin] THEN MESON_TAC[ELUB_IN]);;

let EBVIN_UNIQUE = prove
 (`!D (E:A->A->bool) B leq t v u z z'.
        model D E ZF_AX /\ ecba D E B leq /\
        ebvin D E B leq t v u z /\ ebvin D E B leq t v u z'
        ==> z = z'`,
  REWRITE_TAC[ebvin] THEN REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `S':A = S` SUBST_ALL_TAC THENL
   [ASM_MESON_TAC[EBVINSET_UNIQUE]; ALL_TAC] THEN
  ASM_MESON_TAC[ELUB_UNIQUE; ECBA_IMP_PORDER]);;

(* -- bvcomb as an OBJECT formula, with FV and HOLDS characterisation --- *)
(* Params: ic (value c), iv (container v), it (table t), iu (element u),   *)
(* ileq (order), iB (carrier). Fresh bound vars y=MM+1, qy=MM+2, my=MM+3,  *)
(* pr=MM+4, MM = MAX-nest of the six params.                               *)
let bvcomb_form = new_definition
  `bvcomb_form ic iv it iu ileq iB =
     ?? (MAX (MAX (MAX ic iv) (MAX it iu)) (MAX ileq iB) + 1)
       (?? (MAX (MAX (MAX ic iv) (MAX it iu)) (MAX ileq iB) + 2)
         (?? (MAX (MAX (MAX ic iv) (MAX it iu)) (MAX ileq iB) + 3)
           (?? (MAX (MAX (MAX ic iv) (MAX it iu)) (MAX ileq iB) + 4)
             (apply_form iv
                (MAX (MAX (MAX ic iv) (MAX it iu)) (MAX ileq iB) + 1)
                (MAX (MAX (MAX ic iv) (MAX it iu)) (MAX ileq iB) + 2) &&
              opair_form iu
                (MAX (MAX (MAX ic iv) (MAX it iu)) (MAX ileq iB) + 1)
                (MAX (MAX (MAX ic iv) (MAX it iu)) (MAX ileq iB) + 4) &&
              apply_form it
                (MAX (MAX (MAX ic iv) (MAX it iu)) (MAX ileq iB) + 4)
                (MAX (MAX (MAX ic iv) (MAX it iu)) (MAX ileq iB) + 3) &&
              bmeet_form ileq iB
                (MAX (MAX (MAX ic iv) (MAX it iu)) (MAX ileq iB) + 2)
                (MAX (MAX (MAX ic iv) (MAX it iu)) (MAX ileq iB) + 3)
                ic))))`;;

let HOLDS_BVCOMB_FORM = prove
 (`!D (E:A->A->bool) v ic iv it iu ileq iB.
        model D E ZF_AX /\ valuation D v
        ==> (holds D E v (bvcomb_form ic iv it iu ileq iB) <=>
             bvcomb D E (v iB) (v ileq) (v it) (v iv) (v iu) (v ic))`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `!x. (v:num->A) x IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[valuation]; ALL_TAC] THEN
  REWRITE_TAC[bvcomb_form] THEN
  ABBREV_TAC `MM = MAX (MAX (MAX ic iv) (MAX it iu)) (MAX ileq iB)` THEN
  SUBGOAL_THEN
   `~(ic = MM + 1) /\ ~(ic = MM + 2) /\ ~(ic = MM + 3) /\ ~(ic = MM + 4) /\
    ~(iv = MM + 1) /\ ~(iv = MM + 2) /\ ~(iv = MM + 3) /\ ~(iv = MM + 4) /\
    ~(it = MM + 1) /\ ~(it = MM + 2) /\ ~(it = MM + 3) /\ ~(it = MM + 4) /\
    ~(iu = MM + 1) /\ ~(iu = MM + 2) /\ ~(iu = MM + 3) /\ ~(iu = MM + 4) /\
    ~(ileq = MM + 1) /\ ~(ileq = MM + 2) /\ ~(ileq = MM + 3) /\
    ~(ileq = MM + 4) /\
    ~(iB = MM + 1) /\ ~(iB = MM + 2) /\ ~(iB = MM + 3) /\ ~(iB = MM + 4) /\
    ~(MM + 1 = MM + 2) /\ ~(MM + 1 = MM + 3) /\ ~(MM + 1 = MM + 4) /\
    ~(MM + 2 = MM + 3) /\ ~(MM + 2 = MM + 4) /\ ~(MM + 3 = MM + 4)`
  STRIP_ASSUME_TAC THENL
   [EXPAND_TAC "MM" THEN ARITH_TAC; ALL_TAC] THEN
  SUBGOAL_THEN
   `!a b c d:A. a IN D /\ b IN D /\ c IN D /\ d IN D
      ==> (holds D E
             (((MM + 4) |-> d)
              (((MM + 3) |-> c) (((MM + 2) |-> b) (((MM + 1) |-> a) v))))
             (apply_form iv (MM + 1) (MM + 2) &&
              opair_form iu (MM + 1) (MM + 4) &&
              apply_form it (MM + 4) (MM + 3) &&
              bmeet_form ileq iB (MM + 2) (MM + 3) ic) <=>
           eapply D E (v iv) a b /\
           eopair D E (v iu) a d /\ eapply D E (v it) d c /\
           emeet D E (v iB) (v ileq) b c (v ic))`
  (LABEL_TAC "body") THENL
   [REPEAT STRIP_TAC THEN
    SUBGOAL_THEN
     `valuation D
        (((MM + 4) |-> (d:A))
         (((MM + 3) |-> c) (((MM + 2) |-> b) (((MM + 1) |-> a) v))))`
    ASSUME_TAC THENL [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
    REWRITE_TAC[HOLDS_AND] THEN
    ASM_SIMP_TAC[HOLDS_APPLY_FORM; HOLDS_OPAIR_FORM; HOLDS_BMEET_FORM] THEN
    ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER];
    ALL_TAC] THEN
  REWRITE_TAC[HOLDS_EX] THEN
  REWRITE_TAC[bvcomb] THEN
  REMOVE_THEN "body" (fun bth ->
    POP_ASSUM_LIST(K ALL_TAC) THEN
    EQ_TAC THENL
     [INTRO_TAC "@a. aD @b. bD @c. cD @d. dD h" THEN
      MAP_EVERY EXISTS_TAC [`a:A`; `b:A`; `c:A`; `d:A`] THEN
      ASM_MESON_TAC[bth];
      DISCH_THEN(X_CHOOSE_THEN `y:A` (X_CHOOSE_THEN `qy:A`
        (X_CHOOSE_THEN `my:A` (X_CHOOSE_THEN `pr:A` STRIP_ASSUME_TAC)))) THEN
      EXISTS_TAC `y:A` THEN ASM_REWRITE_TAC[] THEN
      EXISTS_TAC `qy:A` THEN ASM_REWRITE_TAC[] THEN
      EXISTS_TAC `my:A` THEN ASM_REWRITE_TAC[] THEN
      EXISTS_TAC `pr:A` THEN ASM_REWRITE_TAC[] THEN
      ASM_MESON_TAC[bth]]));;

(* -- existence of the image set and of the IN-value -------------------- *)
(* indices: ic=1 (the separated var c), iv=3, it=4, iu=5, ileq=6, iB=7.    *)
let EBVINSET_EXISTS = prove
 (`!D (E:A->A->bool) B leq t v u.
        model D E ZF_AX /\
        B IN D /\ leq IN D /\ t IN D /\ v IN D /\ u IN D
        ==> ?S. ebvinset D E B leq t v u S`,
  REPEAT STRIP_TAC THEN
  FIRST_ASSUM(X_CHOOSE_TAC `val0:num->A` o MATCH_MP VALUATION_EXISTS o
              MATCH_MP MODEL_NONEMPTY) THEN
  ABBREV_TAC
   `val = (3 |-> (v:A))
          ((4 |-> (t:A))
           ((5 |-> (u:A)) ((6 |-> (leq:A)) ((7 |-> (B:A)) val0))))` THEN
  SUBGOAL_THEN
   `valuation D (val:num->A) /\
    (val:num->A) 3 = v /\ (val:num->A) 4 = t /\ (val:num->A) 5 = u /\
    (val:num->A) 6 = leq /\ (val:num->A) 7 = B`
  STRIP_ASSUME_TAC THENL
   [EXPAND_TAC "val" THEN REPEAT CONJ_TAC THEN
    REWRITE_TAC[VALMOD; ARITH_EQ] THEN ASM_MESON_TAC[VALUATION_VALMOD];
    ALL_TAC] THEN
  MP_TAC(SPECL [`bvcomb_form 1 3 4 5 6 7`; `1`; `val:num->A`; `B:A`]
    (MATCH_MP ZF_SEPARATION (ASSUME `model D (E:A->A->bool) ZF_AX`))) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `S:A`
    (CONJUNCTS_THEN2 ASSUME_TAC (LABEL_TAC "sep"))) THEN
  SUBGOAL_THEN
   `!z. z IN D
        ==> (holds D E ((1 |-> (z:A)) val) (bvcomb_form 1 3 4 5 6 7) <=>
             bvcomb D E B leq t v u z)`
  (LABEL_TAC "phi") THENL
   [X_GEN_TAC `z:A` THEN DISCH_TAC THEN
    SUBGOAL_THEN `valuation D ((1 |-> (z:A)) val)` ASSUME_TAC THENL
     [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
    MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`(1 |-> (z:A)) val`;
                  `1`;`3`;`4`;`5`;`6`;`7`] HOLDS_BVCOMB_FORM) THEN
    ASM_REWRITE_TAC[] THEN DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    REWRITE_TAC[VALMOD; ARITH_EQ] THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!z. z IN D ==> ((E:A->A->bool) z S <=> bvcomb D E B leq t v u z)`
  (LABEL_TAC "mem") THENL
   [X_GEN_TAC `z:A` THEN DISCH_TAC THEN
    SUBGOAL_THEN
     `(E:A->A->bool) z S <=>
      E z B /\ holds D E ((1 |-> (z:A)) val) (bvcomb_form 1 3 4 5 6 7)`
    SUBST1_TAC THENL [ASM_MESON_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN
     `holds D E ((1 |-> (z:A)) val) (bvcomb_form 1 3 4 5 6 7) <=>
      bvcomb D E B leq t v u z`
    SUBST1_TAC THENL [ASM_MESON_TAC[]; ALL_TAC] THEN
    ASM_MESON_TAC[BVCOMB_IN];
    ALL_TAC] THEN
  EXISTS_TAC `S:A` THEN REWRITE_TAC[ebvinset] THEN CONJ_TAC THENL
   [FIRST_ASSUM ACCEPT_TAC;
    X_GEN_TAC `c:A` THEN DISCH_TAC THEN ASM_MESON_TAC[]]);;

let EBVIN_EXISTS = prove
 (`!D (E:A->A->bool) B leq t v u.
        model D E ZF_AX /\ ecba D E B leq /\
        B IN D /\ leq IN D /\ t IN D /\ v IN D /\ u IN D
        ==> ?z. ebvin D E B leq t v u z`,
  REPEAT STRIP_TAC THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`t:A`;`v:A`;`u:A`]
    EBVINSET_EXISTS) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_TAC `S:A`) THEN
  SUBGOAL_THEN `esubset D (E:A->A->bool) S B` ASSUME_TAC THENL
   [ASM_MESON_TAC[EBVINSET_SUBSET]; ALL_TAC] THEN
  SUBGOAL_THEN `(S:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[ebvinset]; ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`S:A`] ECBA_SUP) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_TAC `z:A`) THEN
  EXISTS_TAC `z:A` THEN REWRITE_TAC[ebvin] THEN
  EXISTS_TAC `S:A` THEN ASM_REWRITE_TAC[]);;

(* ===================================================================== *)
(* F4: the Boolean =-value  [[u = v]].                                   *)
(*   With B-names u,v read as functional sets of pairs <name,B-elt>      *)
(*   and an IN-table s holding the membership values (s applied at the   *)
(*   pair <a,b> yields [[a IN b]]), the equality value is                *)
(*     [[u=v]] = INF_{x in dom u}(u(x) => [[x IN v]])                     *)
(*              MEET INF_{y in dom v}(v(y) => [[y IN u]]).                *)
(*   The two INFs share ONE combiner predicate bveqcomb (the 2nd is the  *)
(*   1st with u,v swapped): bveqcomb ... u v c = "c is a combiner        *)
(*   u(x) => s<x,v> for some x in dom u".  Each image set is carved by    *)
(*   ZF separation via the OBJECT formula bveqcomb_form, its GLB is       *)
(*   ECBA_INF, and the value is the MEET of the two GLBs (EBALG_MEET).    *)
(*   Consumed by the [[u=v]]/[[u IN v]] recursion (INC3).                 *)
(* ===================================================================== *)

(* c is a combiner value  u(x) IMP s<x,v>  for some name x in dom u.        *)
(* u = the name whose domain we range over, v = the other name (2nd coord   *)
(* of the pair), s = the IN-table (pairs <<a,b>,[[a IN b]]>). B=carrier.    *)
let bveqcomb = new_definition
  `bveqcomb D (E:A->A->bool) B leq s u v c <=>
        ?x qx mx pr.
            x IN D /\ qx IN D /\ mx IN D /\ pr IN D /\
            eapply D E u x qx /\
            eopair D E x v pr /\
            eapply D E s pr mx /\
            ebimp D E B leq qx mx c`;;

let BVEQCOMB_IN = prove
 (`!D (E:A->A->bool) B leq s u v c.
        bveqcomb D E B leq s u v c ==> c IN D /\ E c B`,
  REWRITE_TAC[bveqcomb] THEN MESON_TAC[EBIMP_IN]);;

(* the image set  {c IN D : bveqcomb c}  (automatically a subset of B).      *)
let bveqcombset = new_definition
  `bveqcombset D (E:A->A->bool) B leq s u v S <=>
        S IN D /\
        !c. c IN D ==> (E c S <=> bveqcomb D E B leq s u v c)`;;

let BVEQCOMBSET_SUBSET = prove
 (`!D (E:A->A->bool) B leq s u v S.
        bveqcombset D E B leq s u v S ==> esubset D E S B`,
  REWRITE_TAC[bveqcombset; esubset] THEN MESON_TAC[BVEQCOMB_IN]);;

let BVEQCOMBSET_UNIQUE = prove
 (`!D (E:A->A->bool) B leq s u v S S'.
        model D E ZF_AX /\
        bveqcombset D E B leq s u v S /\ bveqcombset D E B leq s u v S'
        ==> S = S'`,
  REWRITE_TAC[bveqcombset] THEN REPEAT STRIP_TAC THEN
  FIRST_ASSUM(MATCH_MP_TAC o MATCH_MP ZF_EXTENSIONALITY) THEN
  ASM_SIMP_TAC[]);;

(* the =-value  [[u=v]] = (INF over dom u) MEET (INF over dom v).            *)
let ebveq = new_definition
  `ebveq D (E:A->A->bool) B leq s u v z <=>
        ?SL SR gL gR.
            bveqcombset D E B leq s u v SL /\
            bveqcombset D E B leq s v u SR /\
            eglb D E B leq SL gL /\
            eglb D E B leq SR gR /\
            emeet D E B leq gL gR z`;;

let EBVEQ_IN = prove
 (`!D (E:A->A->bool) B leq s u v z.
        ebveq D E B leq s u v z ==> z IN D /\ E z B`,
  REWRITE_TAC[ebveq] THEN MESON_TAC[EMEET_IN]);;

let EBVEQ_UNIQUE = prove
 (`!D (E:A->A->bool) B leq s u v z z'.
        model D E ZF_AX /\ ecba D E B leq /\
        ebveq D E B leq s u v z /\ ebveq D E B leq s u v z'
        ==> z = z'`,
  REPEAT GEN_TAC THEN REWRITE_TAC[ebveq] THEN
  DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC (CONJUNCTS_THEN2 ASSUME_TAC
    (CONJUNCTS_THEN2
       (X_CHOOSE_THEN `SL:A` (X_CHOOSE_THEN `SR:A` (X_CHOOSE_THEN `gL:A`
         (X_CHOOSE_THEN `gR:A` STRIP_ASSUME_TAC))))
       (X_CHOOSE_THEN `SL':A` (X_CHOOSE_THEN `SR':A` (X_CHOOSE_THEN `gL':A`
         (X_CHOOSE_THEN `gR':A` STRIP_ASSUME_TAC))))))) THEN
  SUBGOAL_THEN `eporder D (E:A->A->bool) B leq` ASSUME_TAC THENL
   [ASM_MESON_TAC[ECBA_IMP_PORDER]; ALL_TAC] THEN
  MP_TAC(ISPECL
    [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`s:A`;`u:A`;`v:A`;`SL:A`;`SL':A`]
    BVEQCOMBSET_UNIQUE) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN SUBST_ALL_TAC] THEN
  MP_TAC(ISPECL
    [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`s:A`;`v:A`;`u:A`;`SR:A`;`SR':A`]
    BVEQCOMBSET_UNIQUE) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN SUBST_ALL_TAC] THEN
  MP_TAC(ISPECL
    [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`SL':A`;`gL:A`;`gL':A`]
    EGLB_UNIQUE) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN SUBST_ALL_TAC] THEN
  MP_TAC(ISPECL
    [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`SR':A`;`gR:A`;`gR':A`]
    EGLB_UNIQUE) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN SUBST_ALL_TAC] THEN
  MP_TAC(ISPECL
    [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`gL':A`;`gR':A`;`z:A`;`z':A`]
    EMEET_UNIQUE) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC]);;

(* -- bveqcomb as an OBJECT formula, with FV and HOLDS characterisation --- *)
(* Params: ic (value c), iu (name u), iv (name v), is (IN-table s),        *)
(* ileq (order), iB (carrier). Fresh bound vars x=MM+1, qx=MM+2, mx=MM+3,   *)
(* pr=MM+4, MM = MAX-nest of the six params.                               *)
let bveqcomb_form = new_definition
  `bveqcomb_form ic iu iv is ileq iB =
     ?? (MAX (MAX (MAX ic iu) (MAX iv is)) (MAX ileq iB) + 1)
       (?? (MAX (MAX (MAX ic iu) (MAX iv is)) (MAX ileq iB) + 2)
         (?? (MAX (MAX (MAX ic iu) (MAX iv is)) (MAX ileq iB) + 3)
           (?? (MAX (MAX (MAX ic iu) (MAX iv is)) (MAX ileq iB) + 4)
             (apply_form iu
                (MAX (MAX (MAX ic iu) (MAX iv is)) (MAX ileq iB) + 1)
                (MAX (MAX (MAX ic iu) (MAX iv is)) (MAX ileq iB) + 2) &&
              opair_form
                (MAX (MAX (MAX ic iu) (MAX iv is)) (MAX ileq iB) + 1)
                iv
                (MAX (MAX (MAX ic iu) (MAX iv is)) (MAX ileq iB) + 4) &&
              apply_form is
                (MAX (MAX (MAX ic iu) (MAX iv is)) (MAX ileq iB) + 4)
                (MAX (MAX (MAX ic iu) (MAX iv is)) (MAX ileq iB) + 3) &&
              bimp_form ileq iB
                (MAX (MAX (MAX ic iu) (MAX iv is)) (MAX ileq iB) + 2)
                (MAX (MAX (MAX ic iu) (MAX iv is)) (MAX ileq iB) + 3)
                ic))))`;;

let HOLDS_BVEQCOMB_FORM = prove
 (`!D (E:A->A->bool) v ic iu iv is ileq iB.
        model D E ZF_AX /\ valuation D v
        ==> (holds D E v (bveqcomb_form ic iu iv is ileq iB) <=>
             bveqcomb D E (v iB) (v ileq) (v is) (v iu) (v iv) (v ic))`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `!x. (v:num->A) x IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[valuation]; ALL_TAC] THEN
  REWRITE_TAC[bveqcomb_form] THEN
  ABBREV_TAC `MM = MAX (MAX (MAX ic iu) (MAX iv is)) (MAX ileq iB)` THEN
  SUBGOAL_THEN
   `~(ic = MM + 1) /\ ~(ic = MM + 2) /\ ~(ic = MM + 3) /\ ~(ic = MM + 4) /\
    ~(iu = MM + 1) /\ ~(iu = MM + 2) /\ ~(iu = MM + 3) /\ ~(iu = MM + 4) /\
    ~(iv = MM + 1) /\ ~(iv = MM + 2) /\ ~(iv = MM + 3) /\ ~(iv = MM + 4) /\
    ~(is = MM + 1) /\ ~(is = MM + 2) /\ ~(is = MM + 3) /\ ~(is = MM + 4) /\
    ~(ileq = MM + 1) /\ ~(ileq = MM + 2) /\ ~(ileq = MM + 3) /\
    ~(ileq = MM + 4) /\
    ~(iB = MM + 1) /\ ~(iB = MM + 2) /\ ~(iB = MM + 3) /\ ~(iB = MM + 4) /\
    ~(MM + 1 = MM + 2) /\ ~(MM + 1 = MM + 3) /\ ~(MM + 1 = MM + 4) /\
    ~(MM + 2 = MM + 3) /\ ~(MM + 2 = MM + 4) /\ ~(MM + 3 = MM + 4)`
  STRIP_ASSUME_TAC THENL
   [EXPAND_TAC "MM" THEN ARITH_TAC; ALL_TAC] THEN
  SUBGOAL_THEN
   `!a b c d:A. a IN D /\ b IN D /\ c IN D /\ d IN D
      ==> (holds D E
             (((MM + 4) |-> d)
              (((MM + 3) |-> c) (((MM + 2) |-> b) (((MM + 1) |-> a) v))))
             (apply_form iu (MM + 1) (MM + 2) &&
              opair_form (MM + 1) iv (MM + 4) &&
              apply_form is (MM + 4) (MM + 3) &&
              bimp_form ileq iB (MM + 2) (MM + 3) ic) <=>
           eapply D E (v iu) a b /\
           eopair D E a (v iv) d /\ eapply D E (v is) d c /\
           ebimp D E (v iB) (v ileq) b c (v ic))`
  (LABEL_TAC "body") THENL
   [REPEAT STRIP_TAC THEN
    SUBGOAL_THEN
     `valuation D
        (((MM + 4) |-> (d:A))
         (((MM + 3) |-> c) (((MM + 2) |-> b) (((MM + 1) |-> a) v))))`
    ASSUME_TAC THENL [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
    REWRITE_TAC[HOLDS_AND] THEN
    ASM_SIMP_TAC[HOLDS_APPLY_FORM; HOLDS_OPAIR_FORM; HOLDS_BIMP_FORM] THEN
    ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER];
    ALL_TAC] THEN
  REWRITE_TAC[HOLDS_EX] THEN
  REWRITE_TAC[bveqcomb] THEN
  REMOVE_THEN "body" (fun bth ->
    POP_ASSUM_LIST(K ALL_TAC) THEN
    EQ_TAC THENL
     [INTRO_TAC "@a. aD @b. bD @c. cD @d. dD h" THEN
      MAP_EVERY EXISTS_TAC [`a:A`; `b:A`; `c:A`; `d:A`] THEN
      ASM_MESON_TAC[bth];
      DISCH_THEN(X_CHOOSE_THEN `x:A` (X_CHOOSE_THEN `qx:A`
        (X_CHOOSE_THEN `mx:A` (X_CHOOSE_THEN `pr:A` STRIP_ASSUME_TAC)))) THEN
      EXISTS_TAC `x:A` THEN ASM_REWRITE_TAC[] THEN
      EXISTS_TAC `qx:A` THEN ASM_REWRITE_TAC[] THEN
      EXISTS_TAC `mx:A` THEN ASM_REWRITE_TAC[] THEN
      EXISTS_TAC `pr:A` THEN ASM_REWRITE_TAC[] THEN
      ASM_MESON_TAC[bth]]));;

(* -- existence of the image set and of the =-value --------------------- *)
(* indices: ic=1 (the separated var c), iu=3, iv=4, is=5, ileq=6, iB=7.    *)
let BVEQCOMBSET_EXISTS = prove
 (`!D (E:A->A->bool) B leq s u v.
        model D E ZF_AX /\
        B IN D /\ leq IN D /\ s IN D /\ u IN D /\ v IN D
        ==> ?S. bveqcombset D E B leq s u v S`,
  REPEAT STRIP_TAC THEN
  FIRST_ASSUM(X_CHOOSE_TAC `val0:num->A` o MATCH_MP VALUATION_EXISTS o
              MATCH_MP MODEL_NONEMPTY) THEN
  ABBREV_TAC
   `val = (3 |-> (u:A))
          ((4 |-> (v:A))
           ((5 |-> (s:A)) ((6 |-> (leq:A)) ((7 |-> (B:A)) val0))))` THEN
  SUBGOAL_THEN
   `valuation D (val:num->A) /\
    (val:num->A) 3 = u /\ (val:num->A) 4 = v /\ (val:num->A) 5 = s /\
    (val:num->A) 6 = leq /\ (val:num->A) 7 = B`
  STRIP_ASSUME_TAC THENL
   [EXPAND_TAC "val" THEN REPEAT CONJ_TAC THEN
    REWRITE_TAC[VALMOD; ARITH_EQ] THEN ASM_MESON_TAC[VALUATION_VALMOD];
    ALL_TAC] THEN
  MP_TAC(SPECL [`bveqcomb_form 1 3 4 5 6 7`; `1`; `val:num->A`; `B:A`]
    (MATCH_MP ZF_SEPARATION (ASSUME `model D (E:A->A->bool) ZF_AX`))) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `S:A`
    (CONJUNCTS_THEN2 ASSUME_TAC (LABEL_TAC "sep"))) THEN
  SUBGOAL_THEN
   `!z. z IN D
        ==> (holds D E ((1 |-> (z:A)) val) (bveqcomb_form 1 3 4 5 6 7) <=>
             bveqcomb D E B leq s u v z)`
  (LABEL_TAC "phi") THENL
   [X_GEN_TAC `z:A` THEN DISCH_TAC THEN
    SUBGOAL_THEN `valuation D ((1 |-> (z:A)) val)` ASSUME_TAC THENL
     [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
    MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`(1 |-> (z:A)) val`;
                  `1`;`3`;`4`;`5`;`6`;`7`] HOLDS_BVEQCOMB_FORM) THEN
    ASM_REWRITE_TAC[] THEN DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    REWRITE_TAC[VALMOD; ARITH_EQ] THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!z. z IN D ==> ((E:A->A->bool) z S <=> bveqcomb D E B leq s u v z)`
  (LABEL_TAC "mem") THENL
   [X_GEN_TAC `z:A` THEN DISCH_TAC THEN
    SUBGOAL_THEN
     `(E:A->A->bool) z S <=>
      E z B /\ holds D E ((1 |-> (z:A)) val) (bveqcomb_form 1 3 4 5 6 7)`
    SUBST1_TAC THENL [ASM_MESON_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN
     `holds D E ((1 |-> (z:A)) val) (bveqcomb_form 1 3 4 5 6 7) <=>
      bveqcomb D E B leq s u v z`
    SUBST1_TAC THENL [ASM_MESON_TAC[]; ALL_TAC] THEN
    ASM_MESON_TAC[BVEQCOMB_IN];
    ALL_TAC] THEN
  EXISTS_TAC `S:A` THEN REWRITE_TAC[bveqcombset] THEN CONJ_TAC THENL
   [FIRST_ASSUM ACCEPT_TAC;
    X_GEN_TAC `c:A` THEN DISCH_TAC THEN ASM_MESON_TAC[]]);;

let EBVEQ_EXISTS = prove
 (`!D (E:A->A->bool) B leq s u v.
        model D E ZF_AX /\ ecba D E B leq /\
        B IN D /\ leq IN D /\ s IN D /\ u IN D /\ v IN D
        ==> ?z. ebveq D E B leq s u v z`,
  REPEAT STRIP_TAC THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`s:A`;`u:A`;`v:A`]
    BVEQCOMBSET_EXISTS) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `SL:A`) THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`s:A`;`v:A`;`u:A`]
    BVEQCOMBSET_EXISTS) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `SR:A`) THEN
  SUBGOAL_THEN
   `esubset D (E:A->A->bool) SL B /\ esubset D E SR B`
  STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[BVEQCOMBSET_SUBSET]; ALL_TAC] THEN
  SUBGOAL_THEN `(SL:A) IN D /\ (SR:A) IN D` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[bveqcombset]; ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`SL:A`] ECBA_INF) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `gL:A`) THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`SR:A`] ECBA_INF) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `gR:A`) THEN
  SUBGOAL_THEN
   `(gL:A) IN D /\ (E:A->A->bool) gL B /\ (gR:A) IN D /\ E gR B`
  STRIP_ASSUME_TAC THENL [ASM_MESON_TAC[EGLB_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `ebalg D (E:A->A->bool) B leq` ASSUME_TAC THENL
   [ASM_MESON_TAC[ECBA_IMP_BALG]; ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`gL:A`;`gR:A`]
    EBALG_MEET) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `z:A`) THEN
  EXISTS_TAC `z:A` THEN REWRITE_TAC[ebveq] THEN
  MAP_EVERY EXISTS_TAC [`SL:A`;`SR:A`;`gL:A`;`gR:A`] THEN
  ASM_REWRITE_TAC[]);;

(* ------------------------------------------------------------------------- *)
(* F4: semantic B-name rank, and the component strict-decrease               *)
(* lemma.                                                                    *)
(*                                                                           *)
(* ebnrank D E B x a  :  a is the (least ordinal) B-name rank of x, i.e. the *)
(* unique ordinal a with x IN ebnstage(a) but x NOT IN ebnstage(c) for any   *)
(* c < a.  Existence/uniqueness come straight from BNAME_RANK / _UNIQUE.     *)
(*                                                                           *)
(* EBNRANK_APPLY_LT is the keystone for the [[.=.]]/[[.IN.]] mutual          *)
(* recursion of INC3: if <y,qy> IN v (i.e. v applies at argument y) and v is *)
(* a B-name of rank rv, then y is itself a B-name whose rank is STRICTLY     *)
(* below rv. Hence every reference in Bell's SUP/INF equations lowers the    *)
(* rank-pair, which is what makes the recursion well-founded (INC3.2).       *)
(* ------------------------------------------------------------------------- *)

let ebnrank = new_definition
  `ebnrank D (E:A->A->bool) B x a <=>
        eordinal D E a /\
        (?y. y IN D /\ ebnstage D E B a y /\ E x y) /\
        (!c. c IN D /\ E c a
             ==> ~(?y. y IN D /\ ebnstage D E B c y /\ E x y))`;;

let EBNRANK_ORDINAL = prove
 (`!D (E:A->A->bool) B x a. ebnrank D E B x a ==> eordinal D E a`,
  SIMP_TAC[ebnrank]);;

let EBNRANK_IN = prove
 (`!D (E:A->A->bool) B x a. ebnrank D E B x a ==> a IN D`,
  MESON_TAC[ebnrank; EORDINAL_IN]);;

let EBNRANK_EXISTS = prove
 (`!D (E:A->A->bool) B x.
        model D E ZF_AX /\ B IN D /\ bname D E B x /\ x IN D
        ==> ?a. a IN D /\ ebnrank D E B x a`,
  REPEAT STRIP_TAC THEN
  MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `B:A`; `x:A`] BNAME_RANK) THEN
  ASM_REWRITE_TAC[] THEN REWRITE_TAC[ebnrank] THEN
  DISCH_THEN(X_CHOOSE_THEN `a:A` STRIP_ASSUME_TAC) THEN
  EXISTS_TAC `a:A` THEN ASM_REWRITE_TAC[]);;

let EBNRANK_UNIQUE = prove
 (`!D (E:A->A->bool) B x a a'.
        model D E ZF_AX /\ ebnrank D E B x a /\ ebnrank D E B x a'
        ==> a = a'`,
  REPEAT STRIP_TAC THEN
  MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `B:A`; `x:A`; `a:A`; `a':A`]
        BNAME_RANK_UNIQUE) THEN
  ANTS_TAC THENL [ASM_MESON_TAC[ebnrank]; DISCH_THEN ACCEPT_TAC]);;

let EBNRANK_APPLY_LT = prove
 (`!D (E:A->A->bool) B v y qy rv.
        model D E ZF_AX /\ B IN D /\ v IN D /\ y IN D /\ qy IN D /\
        eapply D E v y qy /\ ebnrank D E B v rv
        ==> bname D E B y /\ ?ry. ebnrank D E B y ry /\ E ry rv`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN
   `eordinal D (E:A->A->bool) rv /\
    ?ya. ya IN D /\ ebnstage D E B rv ya /\ E v ya`
   STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[ebnrank]; ALL_TAC] THEN
  SUBGOAL_THEN `(rv:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[EORDINAL_IN]; ALL_TAC] THEN
  MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `B:A`; `rv:A`; `ya:A`]
        EBNSTAGE_CHAR) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `w:A`
    (CONJUNCTS_THEN2 ASSUME_TAC
      (CONJUNCTS_THEN2 (LABEL_TAC "WCH") ASSUME_TAC))) THEN
  SUBGOAL_THEN `ebnmem D (E:A->A->bool) B w v` ASSUME_TAC THENL
   [UNDISCH_TAC `ebnfuns D (E:A->A->bool) B w ya` THEN
    REWRITE_TAC[ebnfuns] THEN
    DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC (MP_TAC o SPEC `v:A`)) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  UNDISCH_TAC `ebnmem D (E:A->A->bool) B w v` THEN
  REWRITE_TAC[ebnmem] THEN
  DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC
    (X_CHOOSE_THEN `cr:A` STRIP_ASSUME_TAC)) THEN
  UNDISCH_TAC `eapply D (E:A->A->bool) v y qy` THEN
  REWRITE_TAC[eapply] THEN
  DISCH_THEN(X_CHOOSE_THEN `pr:A` STRIP_ASSUME_TAC) THEN
  SUBGOAL_THEN `(pr:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[EOPAIR_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) pr cr` ASSUME_TAC THENL
   [ASM_MESON_TAC[esubset]; ALL_TAC] THEN
  SUBGOAL_THEN
   `?uu ww. uu IN D /\ ww IN D /\ E uu w /\ E ww B /\
            eopair D (E:A->A->bool) uu ww pr` MP_TAC THENL
   [UNDISCH_TAC `ecross D (E:A->A->bool) w B cr` THEN
    REWRITE_TAC[ecross] THEN
    DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC (MP_TAC o SPEC `pr:A`)) THEN
    ASM_REWRITE_TAC[] THEN MESON_TAC[];
    DISCH_THEN(X_CHOOSE_THEN `uu:A`
      (X_CHOOSE_THEN `ww:A` STRIP_ASSUME_TAC))] THEN
  MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `y:A`; `qy:A`; `uu:A`;
                 `ww:A`; `pr:A`] EOPAIR_INJ) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(CONJUNCTS_THEN2 (SUBST_ALL_TAC o SYM) ASSUME_TAC) THEN
  SUBGOAL_THEN
   `?bb zz. bb IN D /\ zz IN D /\ E bb rv /\
            ebnstage D (E:A->A->bool) B bb zz /\ E y zz` STRIP_ASSUME_TAC THENL
   [USE_THEN "WCH" (MP_TAC o SPEC `y:A`) THEN
    ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN(fun th -> ASM_MESON_TAC[th]); ALL_TAC] THEN
  SUBGOAL_THEN `eordinal D (E:A->A->bool) bb` ASSUME_TAC THENL
   [ASM_MESON_TAC[EORDINAL_MEMBER]; ALL_TAC] THEN
  SUBGOAL_THEN `bname D (E:A->A->bool) B y` ASSUME_TAC THENL
   [MATCH_MP_TAC BNAME_STAGE THEN
    MAP_EVERY EXISTS_TAC [`bb:A`; `zz:A`] THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `B:A`; `y:A`]
         EBNRANK_EXISTS) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `ry:A` STRIP_ASSUME_TAC) THEN
  SUBGOAL_THEN `eordinal D (E:A->A->bool) ry` ASSUME_TAC THENL
   [ASM_MESON_TAC[EBNRANK_ORDINAL]; ALL_TAC] THEN
  SUBGOAL_THEN `~((E:A->A->bool) bb ry)` ASSUME_TAC THENL
   [DISCH_TAC THEN
    UNDISCH_TAC `ebnrank D (E:A->A->bool) B y ry` THEN
    REWRITE_TAC[ebnrank] THEN
    DISCH_THEN(MP_TAC o SPEC `bb:A` o CONJUNCT2 o CONJUNCT2) THEN
    ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[]; ALL_TAC] THEN
  CONJ_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  EXISTS_TAC `ry:A` THEN ASM_REWRITE_TAC[] THEN
  MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `ry:A`; `rv:A`]
        EORDINAL_TRICHOTOMY) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(REPEAT_TCL DISJ_CASES_THEN ASSUME_TAC) THENL
   [FIRST_ASSUM ACCEPT_TAC;
    ASM_MESON_TAC[];
    MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `ry:A`; `bb:A`; `rv:A`]
          EORDINAL_TRANS_E) THEN
    ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[]]);;

(* ===================================================================== *)
(* F4: ordinal-max helpers + the three emlex strict-decrease              *)
(* lemmas for the rank-pair measure of the [[.=.]]/[[.IN.]] recursion.     *)
(* ===================================================================== *)

(* a <= b  ==>  a cup b = b   (for ordinals) *)
let EBUNION_ORD_MAX_EQ = prove
 (`!D (E:A->A->bool) a b m.
        model D E ZF_AX /\ eordinal D E a /\ eordinal D E b /\
        ebunion D E a b m /\ (E a b \/ a = b)
        ==> m = b`,
  REPEAT GEN_TAC THEN DISCH_THEN(REPEAT_TCL CONJUNCTS_THEN ASSUME_TAC) THEN
  SUBGOAL_THEN `(a:A) IN D /\ (b:A) IN D` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[EORDINAL_IN]; ALL_TAC] THEN
  SUBGOAL_THEN
   `(m:A) IN D /\
    !w:A. w IN D ==> ((E:A->A->bool) w m <=> E w a \/ E w b)`
  (CONJUNCTS_THEN2 ASSUME_TAC (LABEL_TAC "mc")) THENL
   [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `a:A`; `b:A`; `m:A`]
      EBUNION_ALT) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> MP_TAC(REWRITE_RULE[th]
      (ASSUME `ebunion D (E:A->A->bool) a b m`))) THEN
    DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC ASSUME_TAC) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  FIRST_ASSUM(MATCH_MP_TAC o MATCH_MP ZF_EXTENSIONALITY) THEN
  ASM_REWRITE_TAC[] THEN X_GEN_TAC `w:A` THEN DISCH_TAC THEN
  USE_THEN "mc" (MP_TAC o SPEC `w:A`) THEN ASM_REWRITE_TAC[] THEN
  ASM_MESON_TAC[EORDINAL_TRANS_E]);;

(* b <= a  ==>  a cup b = a   (for ordinals) *)
let EBUNION_ORD_MAX_EQ' = prove
 (`!D (E:A->A->bool) a b m.
        model D E ZF_AX /\ eordinal D E a /\ eordinal D E b /\
        ebunion D E a b m /\ (E b a \/ a = b)
        ==> m = a`,
  REPEAT GEN_TAC THEN DISCH_THEN(REPEAT_TCL CONJUNCTS_THEN ASSUME_TAC) THEN
  SUBGOAL_THEN `(a:A) IN D /\ (b:A) IN D` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[EORDINAL_IN]; ALL_TAC] THEN
  SUBGOAL_THEN
   `(m:A) IN D /\
    !w:A. w IN D ==> ((E:A->A->bool) w m <=> E w a \/ E w b)`
  (CONJUNCTS_THEN2 ASSUME_TAC (LABEL_TAC "mc")) THENL
   [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `a:A`; `b:A`; `m:A`]
      EBUNION_ALT) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> MP_TAC(REWRITE_RULE[th]
      (ASSUME `ebunion D (E:A->A->bool) a b m`))) THEN
    DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC ASSUME_TAC) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  FIRST_ASSUM(MATCH_MP_TAC o MATCH_MP ZF_EXTENSIONALITY) THEN
  ASM_REWRITE_TAC[] THEN X_GEN_TAC `w:A` THEN DISCH_TAC THEN
  USE_THEN "mc" (MP_TAC o SPEC `w:A`) THEN ASM_REWRITE_TAC[] THEN
  ASM_MESON_TAC[EORDINAL_TRANS_E]);;

(* Pattern A : (ru,ry) < (ru,rv)  when ry < rv.
   Reference [[u IN v]] -> [[u=y]], y in dom v. *)
let EMLEX_DEC_A = prove
 (`!D (E:A->A->bool) ru ry rv z z'.
        model D E ZF_AX /\
        eordinal D E ru /\ eordinal D E ry /\ eordinal D E rv /\
        E ry rv /\ eopair D E ru ry z /\ eopair D E ru rv z'
        ==> emlex D E z z'`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `(ru:A) IN D /\ (ry:A) IN D /\ (rv:A) IN D`
  STRIP_ASSUME_TAC THENL [ASM_MESON_TAC[EORDINAL_IN]; ALL_TAC] THEN
  MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `ru:A`; `ry:A`]
        EBUNION_EXISTS) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `m:A`) THEN
  MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `ru:A`; `rv:A`]
        EBUNION_EXISTS) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `m':A`) THEN
  SUBGOAL_THEN `(m:A) IN D /\ (m':A) IN D` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[EBUNION_IN]; ALL_TAC] THEN
  MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `z:A`; `z':A`;
                 `ru:A`; `ry:A`; `ru:A`; `rv:A`; `m:A`; `m':A`]
          EMLEX_CANON) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `ru:A`; `rv:A`]
        EORDINAL_TRICHOTOMY) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(REPEAT_TCL DISJ_CASES_THEN ASSUME_TAC) THENL
   [ (* E ru rv *)
    SUBGOAL_THEN `(m':A) = rv` ASSUME_TAC THENL
     [ASM_MESON_TAC[EBUNION_ORD_MAX_EQ; EBUNION_ORD_MAX_EQ']; ALL_TAC] THEN
    MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `ru:A`; `ry:A`; `m:A`]
      EBUNION_ORDINAL_MAX) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN ASM_MESON_TAC[];
     (* ru = rv *)
    SUBGOAL_THEN `(E:A->A->bool) ry ru` ASSUME_TAC THENL
     [ASM_MESON_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN `(m':A) = rv` ASSUME_TAC THENL
     [ASM_MESON_TAC[EBUNION_ORD_MAX_EQ; EBUNION_ORD_MAX_EQ']; ALL_TAC] THEN
    SUBGOAL_THEN `(m:A) = ru` ASSUME_TAC THENL
     [ASM_MESON_TAC[EBUNION_ORD_MAX_EQ; EBUNION_ORD_MAX_EQ']; ALL_TAC] THEN
    ASM_MESON_TAC[];
     (* E rv ru *)
    SUBGOAL_THEN `(E:A->A->bool) ry ru` ASSUME_TAC THENL
     [ASM_MESON_TAC[EORDINAL_TRANS_E]; ALL_TAC] THEN
    SUBGOAL_THEN `(m':A) = ru` ASSUME_TAC THENL
     [ASM_MESON_TAC[EBUNION_ORD_MAX_EQ; EBUNION_ORD_MAX_EQ']; ALL_TAC] THEN
    SUBGOAL_THEN `(m:A) = ru` ASSUME_TAC THENL
     [ASM_MESON_TAC[EBUNION_ORD_MAX_EQ; EBUNION_ORD_MAX_EQ']; ALL_TAC] THEN
    ASM_MESON_TAC[]]);;

(* Pattern B : (rx,rv) < (ru,rv)  when rx < ru.
   Reference [[u=v]] -> [[x IN v]], x in dom u. *)
let EMLEX_DEC_B = prove
 (`!D (E:A->A->bool) rx ru rv z z'.
        model D E ZF_AX /\
        eordinal D E rx /\ eordinal D E ru /\ eordinal D E rv /\
        E rx ru /\ eopair D E rx rv z /\ eopair D E ru rv z'
        ==> emlex D E z z'`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `(rx:A) IN D /\ (ru:A) IN D /\ (rv:A) IN D`
  STRIP_ASSUME_TAC THENL [ASM_MESON_TAC[EORDINAL_IN]; ALL_TAC] THEN
  MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `rx:A`; `rv:A`]
        EBUNION_EXISTS) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `m:A`) THEN
  MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `ru:A`; `rv:A`]
        EBUNION_EXISTS) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `m':A`) THEN
  SUBGOAL_THEN `(m:A) IN D /\ (m':A) IN D` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[EBUNION_IN]; ALL_TAC] THEN
  MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `z:A`; `z':A`;
                 `rx:A`; `rv:A`; `ru:A`; `rv:A`; `m:A`; `m':A`]
          EMLEX_CANON) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `ru:A`; `rv:A`]
        EORDINAL_TRICHOTOMY) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(REPEAT_TCL DISJ_CASES_THEN ASSUME_TAC) THENL
   [ (* E ru rv *)
    SUBGOAL_THEN `(E:A->A->bool) rx rv` ASSUME_TAC THENL
     [ASM_MESON_TAC[EORDINAL_TRANS_E]; ALL_TAC] THEN
    SUBGOAL_THEN `(m':A) = rv` ASSUME_TAC THENL
     [ASM_MESON_TAC[EBUNION_ORD_MAX_EQ; EBUNION_ORD_MAX_EQ']; ALL_TAC] THEN
    SUBGOAL_THEN `(m:A) = rv` ASSUME_TAC THENL
     [ASM_MESON_TAC[EBUNION_ORD_MAX_EQ; EBUNION_ORD_MAX_EQ']; ALL_TAC] THEN
    ASM_MESON_TAC[];
     (* ru = rv *)
    SUBGOAL_THEN `(E:A->A->bool) rx rv` ASSUME_TAC THENL
     [ASM_MESON_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN `(m':A) = rv` ASSUME_TAC THENL
     [ASM_MESON_TAC[EBUNION_ORD_MAX_EQ; EBUNION_ORD_MAX_EQ']; ALL_TAC] THEN
    SUBGOAL_THEN `(m:A) = rv` ASSUME_TAC THENL
     [ASM_MESON_TAC[EBUNION_ORD_MAX_EQ; EBUNION_ORD_MAX_EQ']; ALL_TAC] THEN
    ASM_MESON_TAC[];
     (* E rv ru *)
    SUBGOAL_THEN `(m':A) = ru` ASSUME_TAC THENL
     [ASM_MESON_TAC[EBUNION_ORD_MAX_EQ; EBUNION_ORD_MAX_EQ']; ALL_TAC] THEN
    MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `rx:A`; `rv:A`; `m:A`]
      EBUNION_ORDINAL_MAX) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN ASM_MESON_TAC[]]);;

(* Pattern C : (ry,ru) < (ru,rv)  when ry < rv.
   Reference [[u=v]] -> [[y IN u]], y in dom v. *)
let EMLEX_DEC_C = prove
 (`!D (E:A->A->bool) ry ru rv z z'.
        model D E ZF_AX /\
        eordinal D E ry /\ eordinal D E ru /\ eordinal D E rv /\
        E ry rv /\ eopair D E ry ru z /\ eopair D E ru rv z'
        ==> emlex D E z z'`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `(ry:A) IN D /\ (ru:A) IN D /\ (rv:A) IN D`
  STRIP_ASSUME_TAC THENL [ASM_MESON_TAC[EORDINAL_IN]; ALL_TAC] THEN
  MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `ry:A`; `ru:A`]
        EBUNION_EXISTS) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `m:A`) THEN
  MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `ru:A`; `rv:A`]
        EBUNION_EXISTS) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `m':A`) THEN
  SUBGOAL_THEN `(m:A) IN D /\ (m':A) IN D` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[EBUNION_IN]; ALL_TAC] THEN
  MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `z:A`; `z':A`;
                 `ry:A`; `ru:A`; `ru:A`; `rv:A`; `m:A`; `m':A`]
          EMLEX_CANON) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `ru:A`; `rv:A`]
        EORDINAL_TRICHOTOMY) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(REPEAT_TCL DISJ_CASES_THEN ASSUME_TAC) THENL
   [ (* E ru rv *)
    SUBGOAL_THEN `(m':A) = rv` ASSUME_TAC THENL
     [ASM_MESON_TAC[EBUNION_ORD_MAX_EQ; EBUNION_ORD_MAX_EQ']; ALL_TAC] THEN
    MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `ry:A`; `ru:A`; `m:A`]
      EBUNION_ORDINAL_MAX) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN ASM_MESON_TAC[];
     (* ru = rv *)
    SUBGOAL_THEN `(E:A->A->bool) ry ru` ASSUME_TAC THENL
     [ASM_MESON_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN `(m':A) = rv` ASSUME_TAC THENL
     [ASM_MESON_TAC[EBUNION_ORD_MAX_EQ; EBUNION_ORD_MAX_EQ']; ALL_TAC] THEN
    SUBGOAL_THEN `(m:A) = ru` ASSUME_TAC THENL
     [ASM_MESON_TAC[EBUNION_ORD_MAX_EQ; EBUNION_ORD_MAX_EQ']; ALL_TAC] THEN
    ASM_MESON_TAC[];
     (* E rv ru *)
    SUBGOAL_THEN `(E:A->A->bool) ry ru` ASSUME_TAC THENL
     [ASM_MESON_TAC[EORDINAL_TRANS_E]; ALL_TAC] THEN
    SUBGOAL_THEN `(m':A) = ru` ASSUME_TAC THENL
     [ASM_MESON_TAC[EBUNION_ORD_MAX_EQ; EBUNION_ORD_MAX_EQ']; ALL_TAC] THEN
    SUBGOAL_THEN `(m:A) = ru` ASSUME_TAC THENL
     [ASM_MESON_TAC[EBUNION_ORD_MAX_EQ; EBUNION_ORD_MAX_EQ']; ALL_TAC] THEN
    ASM_MESON_TAC[]]);;

(* ------------------------------------------------------------------ *)
(* F4: the DISAGREEMENT object-formula `disagree_form`, plus           *)
(* its reusable engine HOLDS_FNEQ_AT (= fneq_form generalized to       *)
(* arbitrary graph slots ig,ig',ia and fresh value-vars b1,b2, with    *)
(* freshness as explicit arithmetic hypotheses).                       *)
(*                                                                     *)
(* HOLDS_FNEQ_AT ig ig' ia b1 b2 : the object formula                  *)
(*    Not(!!b1 (!!b2 ((apply_form ig ia b1 && apply_form ig' ia b2)    *)
(*                    --> Eq b1 b2)))                                  *)
(* holds  iff  the graphs ig,ig' (read as eapply-relations, both       *)
(* looked up at the common argument ia) FAIL to be jointly             *)
(* single-valued-and-equal there -- i.e. they DISAGREE at ia.          *)
(*                                                                     *)
(* disagree_form ipr isIN isIN' isEQ isEQ' = the OR of two such blocks *)
(* -- the IN pair (isIN,isIN') and the EQ pair (isEQ,isEQ'), both      *)
(* looked up at pair-slot ipr -- "the two candidate (IN,EQ) tables     *)
(* disagree at the pair pr".  Fresh bound vars MM+1,MM+2 with MM the    *)
(* MAX of the 5 argument slots.  This is the fused disagreement        *)
(* side-condition of the rank-code image replacement in INC3.1d.       *)
(* Built only from %%,&&,-->,Eq,!! (via apply_form) + Not,|| -- no new *)
(* constructor, no formula-substitution operation.                     *)
(* ------------------------------------------------------------------ *)

let HOLDS_FNEQ_AT = prove
 (`!D (E:A->A->bool) v ig ig' ia b1 b2.
        model D E ZF_AX /\ valuation D v /\
        ~(b1 = b2) /\
        ~(ig = b1) /\ ~(ig = b2) /\ ~(ig' = b1) /\ ~(ig' = b2) /\
        ~(ia = b1) /\ ~(ia = b2)
        ==> (holds D E v
               (Not(!! b1 (!! b2
                  ((apply_form ig ia b1 && apply_form ig' ia b2) -->
                   Eq b1 b2)))) <=>
             ~(!w w'. w IN D /\ w' IN D /\
                      eapply D E (v ig) (v ia) w /\
                      eapply D E (v ig') (v ia) w'
                      ==> w = w'))`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `!x. (v:num->A) x IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[valuation]; ALL_TAC] THEN
  SUBGOAL_THEN
   `!w w':A. w IN D /\ w' IN D
      ==> (holds D E ((b2 |-> w') ((b1 |-> w) (v:num->A)))
             (apply_form ig ia b1) <=>
           eapply D (E:A->A->bool) (v ig) (v ia) w) /\
          (holds D E ((b2 |-> w') ((b1 |-> w) (v:num->A)))
             (apply_form ig' ia b2) <=>
           eapply D E (v ig') (v ia) w')`
  (LABEL_TAC "ap") THENL
   [REPEAT GEN_TAC THEN STRIP_TAC THEN CONJ_TAC THENL
     [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
        `(b2 |-> (w':A)) ((b1 |-> (w:A)) (v:num->A))`; `ig:num`;
        `ia:num`; `b1:num`]
        HOLDS_APPLY_FORM);
      MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
        `(b2 |-> (w':A)) ((b1 |-> (w:A)) (v:num->A))`; `ig':num`;
        `ia:num`; `b2:num`]
        HOLDS_APPLY_FORM)] THEN
    (ANTS_TAC THENL
      [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
     DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
     ASM_REWRITE_TAC[VALMOD]);
    ALL_TAC] THEN
  REWRITE_TAC[HOLDS_NOT; HOLDS_AND; holds] THEN
  ASM_REWRITE_TAC[VALMOD] THEN
  AP_TERM_TAC THEN REWRITE_TAC[IMP_CONJ] THEN
  REWRITE_TAC[RIGHT_IMP_FORALL_THM] THEN
  MATCH_MP_TAC(MESON[]
   `(!x:A. P x <=> Q x) ==> ((!x. P x) <=> (!x. Q x))`) THEN
  X_GEN_TAC `w:A` THEN
  MATCH_MP_TAC(MESON[]
   `(!x:A. P x <=> Q x) ==> ((!x. P x) <=> (!x. Q x))`) THEN
  X_GEN_TAC `w':A` THEN
  MATCH_MP_TAC(TAUT
   `(a ==> (p <=> q)) ==> ((a ==> p) <=> (a ==> q))`) THEN
  DISCH_TAC THEN
  MATCH_MP_TAC(TAUT
   `(a ==> (p <=> q)) ==> ((a ==> p) <=> (a ==> q))`) THEN
  DISCH_TAC THEN
  USE_THEN "ap" (fun th -> ASM_SIMP_TAC[th]));;

let disagree_form = new_definition
  `disagree_form ipr isIN isIN' isEQ isEQ' =
     Not(!! (MAX (MAX (MAX ipr isIN) (MAX isIN' isEQ)) isEQ' + 1)
            (!! (MAX (MAX (MAX ipr isIN) (MAX isIN' isEQ)) isEQ' + 2)
               ((apply_form isIN ipr
                   (MAX (MAX (MAX ipr isIN) (MAX isIN' isEQ)) isEQ' + 1) &&
                 apply_form isIN' ipr
                   (MAX (MAX (MAX ipr isIN) (MAX isIN' isEQ)) isEQ' + 2)) -->
                Eq (MAX (MAX (MAX ipr isIN) (MAX isIN' isEQ)) isEQ' + 1)
                   (MAX (MAX (MAX ipr isIN) (MAX isIN' isEQ)) isEQ' + 2))))
     ||
     Not(!! (MAX (MAX (MAX ipr isIN) (MAX isIN' isEQ)) isEQ' + 1)
            (!! (MAX (MAX (MAX ipr isIN) (MAX isIN' isEQ)) isEQ' + 2)
               ((apply_form isEQ ipr
                   (MAX (MAX (MAX ipr isIN) (MAX isIN' isEQ)) isEQ' + 1) &&
                 apply_form isEQ' ipr
                   (MAX (MAX (MAX ipr isIN) (MAX isIN' isEQ)) isEQ' + 2)) -->
                Eq (MAX (MAX (MAX ipr isIN) (MAX isIN' isEQ)) isEQ' + 1)
                   (MAX (MAX (MAX ipr isIN) (MAX isIN' isEQ)) isEQ' + 2))))`;;

let HOLDS_DISAGREE_FORM = prove
 (`!D (E:A->A->bool) v ipr isIN isIN' isEQ isEQ'.
        model D E ZF_AX /\ valuation D v
        ==> (holds D E v (disagree_form ipr isIN isIN' isEQ isEQ') <=>
             ~(!w w'. w IN D /\ w' IN D /\
                      eapply D E (v isIN) (v ipr) w /\
                      eapply D E (v isIN') (v ipr) w'
                      ==> w = w') \/
             ~(!w w'. w IN D /\ w' IN D /\
                      eapply D E (v isEQ) (v ipr) w /\
                      eapply D E (v isEQ') (v ipr) w'
                      ==> w = w'))`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  REWRITE_TAC[disagree_form; HOLDS_OR] THEN
  ABBREV_TAC `MM = MAX (MAX (MAX ipr isIN) (MAX isIN' isEQ)) isEQ'` THEN
  SUBGOAL_THEN
   `~(MM + 1 = ipr) /\ ~(MM + 1 = isIN) /\ ~(MM + 1 = isIN') /\
    ~(MM + 1 = isEQ) /\ ~(MM + 1 = isEQ') /\
    ~(MM + 2 = ipr) /\ ~(MM + 2 = isIN) /\ ~(MM + 2 = isIN') /\
    ~(MM + 2 = isEQ) /\ ~(MM + 2 = isEQ') /\
    ~(MM + 1 = MM + 2)`
  STRIP_ASSUME_TAC THENL
   [EXPAND_TAC "MM" THEN ARITH_TAC; ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`v:num->A`;`isIN:num`;`isIN':num`;
     `ipr:num`; `MM + 1`; `MM + 2`] HOLDS_FNEQ_AT) THEN
  ANTS_TAC THENL [ASM_MESON_TAC[]; ALL_TAC] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`v:num->A`;`isEQ:num`;`isEQ':num`;
     `ipr:num`; `MM + 1`; `MM + 2`] HOLDS_FNEQ_AT) THEN
  ANTS_TAC THENL [ASM_MESON_TAC[]; ALL_TAC] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]));;

(* ===================================================================== *)
(* F4: RG = the bname-rank GRAPH on a set ws all of whose                 *)
(* members are B-names.  RG = { <x, rank_B(x)> : x IN ws }, a functional  *)
(* graph.  ONE ZF replacement along  ?? 1 (bnrank_form && opair_form 0 1  *)
(* 3): input slot 0 = x, the rank rebound existentially at slot 1, output *)
(* slot 3 = the Kuratowski pair, B parked at slot 2.  Single-valued via   *)
(* EBNRANK_UNIQUE (rank unique) + EOPAIR_UNIQUE (pair unique).  This       *)
(* sidesteps bnrank_form's hardcoded slots 0/1/2 so that INC3.1d can look  *)
(* ranks up via apply_form at flexible slots (NO bnrank_form there).       *)
(* ===================================================================== *)

let EBNRANK_GRAPH_EXISTS = prove
 (`!D (E:A->A->bool) B ws.
        model D E ZF_AX /\ B IN D /\ ws IN D /\
        (!z. z IN D /\ E z ws ==> bname D E B z)
        ==> ?RG. RG IN D /\ eisfun D E RG /\ edomain D E RG ws /\
                 (!x r. x IN D /\ E x ws /\ ebnrank D E B x r
                        ==> eapply D E RG x r) /\
                 (!z. z IN D
                      ==> (E z RG <=>
                           ?x r. x IN D /\ r IN D /\ E x ws /\
                                 ebnrank D E B x r /\
                                 eopair D (E:A->A->bool) x r z))`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "zf BD wsD allc" THEN
  SUBGOAL_THEN `?v0:num->A. valuation D v0` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[VALUATION_EXISTS; MODEL_NONEMPTY]; ALL_TAC] THEN
  ABBREV_TAC `vB = (2 |-> (B:A)) v0` THEN
  SUBGOAL_THEN `valuation D (vB:num->A) /\ (vB:num->A) 2 = B`
  STRIP_ASSUME_TAC THENL
   [EXPAND_TAC "vB" THEN ASM_SIMP_TAC[VALUATION_VALMOD; VALMOD]; ALL_TAC] THEN
  SUBGOAL_THEN
   `!el ot:A. el IN D /\ ot IN D
      ==> (holds D E ((3 |-> ot) ((0 |-> el) vB))
             (?? 1 (bnrank_form && opair_form 0 1 3)) <=>
           ?r. r IN D /\ ebnrank D E B el r /\
               eopair D (E:A->A->bool) el r ot)`
  (LABEL_TAC "hrk") THENL
   [REPEAT GEN_TAC THEN STRIP_TAC THEN
    REWRITE_TAC[HOLDS_EX; HOLDS_AND] THEN
    MATCH_MP_TAC(MESON[]
     `(!r:A. P r <=> Q r) ==> ((?r:A. P r) <=> (?r:A. Q r))`) THEN
    X_GEN_TAC `r:A` THEN
    MATCH_MP_TAC(TAUT `(a ==> (p <=> q)) ==> ((a /\ p) <=> (a /\ q))`) THEN
    DISCH_TAC THEN
    SUBGOAL_THEN
     `valuation D ((1 |-> (r:A)) ((3 |-> (ot:A)) ((0 |-> (el:A)) vB)))`
    ASSUME_TAC THENL
     [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
      `(1 |-> (r:A)) ((3 |-> (ot:A)) ((0 |-> (el:A)) vB))`]
      HOLDS_BNRANK_FORM) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
      `(1 |-> (r:A)) ((3 |-> (ot:A)) ((0 |-> (el:A)) vB))`;
      `0`; `1`; `3`] HOLDS_OPAIR_FORM) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    ASM_REWRITE_TAC[VALMOD; ARITH_EQ; ebnrank];
    ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`] ZF_REPLACEMENT) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(MP_TAC o SPECL
    [`?? 1 (bnrank_form && opair_form 0 1 3)`;
     `0`; `3`; `vB:num->A`; `ws:A`]) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[ARITH_EQ] THEN
    X_GEN_TAC `u:A` THEN STRIP_TAC THEN
    SUBGOAL_THEN `bname D (E:A->A->bool) B u` ASSUME_TAC THENL
     [ASM_MESON_TAC[]; ALL_TAC] THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `B:A`; `u:A`]
      EBNRANK_EXISTS) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(X_CHOOSE_THEN `r:A` STRIP_ASSUME_TAC) THEN
    SUBGOAL_THEN `(r:A) IN D` ASSUME_TAC THENL
     [ASM_MESON_TAC[EBNRANK_IN]; ALL_TAC] THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `u:A`; `r:A`]
      EOPAIR_EXISTS) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(X_CHOOSE_TAC `pv:A`) THEN
    SUBGOAL_THEN `(pv:A) IN D` ASSUME_TAC THENL
     [ASM_MESON_TAC[EOPAIR_IN]; ALL_TAC] THEN
    EXISTS_TAC `pv:A` THEN ASM_REWRITE_TAC[] THEN
    X_GEN_TAC `w':A` THEN
    DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC MP_TAC) THEN
    USE_THEN "hrk" (MP_TAC o SPECL [`u:A`; `w':A`]) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    DISCH_THEN(X_CHOOSE_THEN `r':A` STRIP_ASSUME_TAC) THEN
    SUBGOAL_THEN `(r':A) = r` SUBST_ALL_TAC THENL
     [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `B:A`; `u:A`; `r':A`; `r:A`]
        EBNRANK_UNIQUE) THEN ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `u:A`; `r:A`; `w':A`; `pv:A`]
      EOPAIR_UNIQUE) THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `RG:A` (CONJUNCTS_THEN2 ASSUME_TAC
    (LABEL_TAC "raw"))) THEN
  SUBGOAL_THEN
   `!z. z IN D
        ==> (E z RG <=>
             ?x r. x IN D /\ r IN D /\ E x ws /\
                   ebnrank D E B x r /\ eopair D (E:A->A->bool) x r z)`
  (LABEL_TAC "RGc") THENL
   [X_GEN_TAC `z:A` THEN DISCH_TAC THEN
    USE_THEN "raw" (MP_TAC o SPEC `z:A`) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    EQ_TAC THENL
     [DISCH_THEN(X_CHOOSE_THEN `u:A` (CONJUNCTS_THEN2 ASSUME_TAC
        (CONJUNCTS_THEN2 ASSUME_TAC MP_TAC))) THEN
      USE_THEN "hrk" (MP_TAC o SPECL [`u:A`; `z:A`]) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
      DISCH_THEN(X_CHOOSE_THEN `r:A` STRIP_ASSUME_TAC) THEN
      MAP_EVERY EXISTS_TAC [`u:A`; `r:A`] THEN ASM_REWRITE_TAC[];
      DISCH_THEN(X_CHOOSE_THEN `x:A` (X_CHOOSE_THEN `r:A`
        STRIP_ASSUME_TAC)) THEN
      EXISTS_TAC `x:A` THEN ASM_REWRITE_TAC[] THEN
      USE_THEN "hrk" (MP_TAC o SPECL [`x:A`; `z:A`]) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
      EXISTS_TAC `r:A` THEN ASM_REWRITE_TAC[]];
    ALL_TAC] THEN
  EXISTS_TAC `RG:A` THEN REPEAT CONJ_TAC THENL
   [FIRST_ASSUM ACCEPT_TAC;
    REWRITE_TAC[eisfun] THEN REPEAT CONJ_TAC THENL
     [FIRST_ASSUM ACCEPT_TAC;
      X_GEN_TAC `z:A` THEN STRIP_TAC THEN
      SUBGOAL_THEN
       `?x r. x IN D /\ r IN D /\ E x ws /\ ebnrank D E B x r /\
              eopair D (E:A->A->bool) x r z`
      STRIP_ASSUME_TAC THENL [ASM_MESON_TAC[]; ALL_TAC] THEN
      MAP_EVERY EXISTS_TAC [`x:A`; `r:A`] THEN ASM_REWRITE_TAC[];
      REPEAT GEN_TAC THEN STRIP_TAC THEN
      SUBGOAL_THEN `(z:A) IN D /\ (z':A) IN D` STRIP_ASSUME_TAC THENL
       [ASM_MESON_TAC[EOPAIR_IN]; ALL_TAC] THEN
      SUBGOAL_THEN
       `?x1 r1. x1 IN D /\ r1 IN D /\ E x1 ws /\ ebnrank D E B x1 r1 /\
                eopair D (E:A->A->bool) x1 r1 z`
      STRIP_ASSUME_TAC THENL [ASM_MESON_TAC[]; ALL_TAC] THEN
      SUBGOAL_THEN
       `?x2 r2. x2 IN D /\ r2 IN D /\ E x2 ws /\ ebnrank D E B x2 r2 /\
                eopair D (E:A->A->bool) x2 r2 z'`
      STRIP_ASSUME_TAC THENL [ASM_MESON_TAC[]; ALL_TAC] THEN
      SUBGOAL_THEN `(u:A) = x1 /\ (w:A) = r1` STRIP_ASSUME_TAC THENL
       [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `u:A`; `w:A`;
          `x1:A`; `r1:A`; `z:A`] EOPAIR_INJ) THEN ASM_REWRITE_TAC[];
        ALL_TAC] THEN
      SUBGOAL_THEN `(u:A) = x2 /\ (w':A) = r2` STRIP_ASSUME_TAC THENL
       [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `u:A`; `w':A`;
          `x2:A`; `r2:A`; `z':A`] EOPAIR_INJ) THEN ASM_REWRITE_TAC[];
        ALL_TAC] THEN
      SUBGOAL_THEN `(x2:A) = x1` ASSUME_TAC THENL
       [ASM_MESON_TAC[]; ALL_TAC] THEN
      MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `B:A`; `x1:A`;
        `r1:A`; `r2:A`] EBNRANK_UNIQUE) THEN
      ANTS_TAC THENL [ASM_MESON_TAC[]; ASM_MESON_TAC[]]];
    REWRITE_TAC[edomain] THEN CONJ_TAC THENL
     [FIRST_ASSUM ACCEPT_TAC;
      X_GEN_TAC `u:A` THEN DISCH_TAC THEN REWRITE_TAC[eindom] THEN
      EQ_TAC THENL
       [DISCH_TAC THEN
        SUBGOAL_THEN `bname D (E:A->A->bool) B u` ASSUME_TAC THENL
         [ASM_MESON_TAC[]; ALL_TAC] THEN
        MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `B:A`; `u:A`]
          EBNRANK_EXISTS) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
        DISCH_THEN(X_CHOOSE_THEN `r:A` STRIP_ASSUME_TAC) THEN
        SUBGOAL_THEN `(r:A) IN D` ASSUME_TAC THENL
         [ASM_MESON_TAC[EBNRANK_IN]; ALL_TAC] THEN
        MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `u:A`; `r:A`]
          EOPAIR_EXISTS) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
        DISCH_THEN(X_CHOOSE_TAC `zz:A`) THEN
        SUBGOAL_THEN `(zz:A) IN D` ASSUME_TAC THENL
         [ASM_MESON_TAC[EOPAIR_IN]; ALL_TAC] THEN
        EXISTS_TAC `r:A` THEN CONJ_TAC THENL
         [FIRST_ASSUM ACCEPT_TAC;
          REWRITE_TAC[eapply] THEN EXISTS_TAC `zz:A` THEN CONJ_TAC THENL
           [FIRST_ASSUM ACCEPT_TAC; ASM_MESON_TAC[]]];
        DISCH_THEN(X_CHOOSE_THEN `wv:A` (CONJUNCTS_THEN2 ASSUME_TAC
          MP_TAC)) THEN
        REWRITE_TAC[eapply] THEN
        DISCH_THEN(X_CHOOSE_THEN `zz:A` STRIP_ASSUME_TAC) THEN
        SUBGOAL_THEN `(zz:A) IN D` ASSUME_TAC THENL
         [ASM_MESON_TAC[EOPAIR_IN]; ALL_TAC] THEN
        SUBGOAL_THEN
         `?x1 r1. x1 IN D /\ r1 IN D /\ E x1 ws /\ ebnrank D E B x1 r1 /\
                  eopair D (E:A->A->bool) x1 r1 zz`
        STRIP_ASSUME_TAC THENL [ASM_MESON_TAC[]; ALL_TAC] THEN
        SUBGOAL_THEN `(u:A) = x1` ASSUME_TAC THENL
         [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `u:A`; `wv:A`;
            `x1:A`; `r1:A`; `zz:A`] EOPAIR_INJ) THEN ASM_MESON_TAC[];
          ALL_TAC] THEN
        ASM_MESON_TAC[]]];
    REPEAT GEN_TAC THEN STRIP_TAC THEN
    SUBGOAL_THEN `(r:A) IN D` ASSUME_TAC THENL
     [ASM_MESON_TAC[EBNRANK_IN]; ALL_TAC] THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `x:A`; `r:A`]
      EOPAIR_EXISTS) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(X_CHOOSE_TAC `zz:A`) THEN
    SUBGOAL_THEN `(zz:A) IN D` ASSUME_TAC THENL
     [ASM_MESON_TAC[EOPAIR_IN]; ALL_TAC] THEN
    REWRITE_TAC[eapply] THEN EXISTS_TAC `zz:A` THEN CONJ_TAC THENL
     [FIRST_ASSUM ACCEPT_TAC; ASM_MESON_TAC[]];
    USE_THEN "RGc" ACCEPT_TAC]);;

(* ===== F4-INC3.1d: Boolean-value attempt disagreement bad-set ===== *)
(* bvdisagree + EBVBAD_BRIDGE + EBVBADSET_EXISTS + EBVBAD_LEAST:      *)
(* the rank-code image set of table-disagreement pairs and its       *)
(* emlex-least element (the minimal-counterexample tool for          *)
(* EBVATT_UNIQUE).                                                    *)

(* INC3.1d step 1: bvdisagree abbreviation + parameterized HOLDS bridge. *)

let bvdisagree = new_definition
  `bvdisagree D (E:A->A->bool) s s' pr <=>
       ~(!a a'. a IN D /\ a' IN D /\
                eapply D E s pr a /\ eapply D E s' pr a' ==> a = a')`;;

let EBVBAD_BRIDGE = prove
 (`!D (E:A->A->bool) vv RG sIN sIN' sEQ sEQ' pr code.
        model D E ZF_AX /\ valuation D vv /\ pr IN D /\ code IN D /\
        vv 6 = RG /\ vv 7 = sIN /\ vv 8 = sIN' /\ vv 9 = sEQ /\ vv 10 = sEQ'
        ==> (holds D E ((1 |-> code) ((0 |-> pr) vv))
               (?? 2 (?? 3 (?? 4 (?? 5
                  (opair_form 2 3 0 &&
                   apply_form 6 2 4 &&
                   apply_form 6 3 5 &&
                   opair_form 4 5 1 &&
                   disagree_form 0 7 8 9 10))))) <=>
             ?u. u IN D /\ ?v. v IN D /\ ?ru. ru IN D /\ ?rv. rv IN D /\
                 eopair D E u v pr /\
                 eapply D E RG u ru /\ eapply D E RG v rv /\
                 eopair D E ru rv code /\
                 (bvdisagree D E sIN sIN' pr \/ bvdisagree D E sEQ sEQ' pr))`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  REWRITE_TAC[bvdisagree] THEN
  REWRITE_TAC[HOLDS_EX] THEN
  MATCH_MP_TAC(MESON[]
               `(!u:A. P u <=> Q u) ==> ((?u:A. P u) <=> (?u:A. Q u))`) THEN
  X_GEN_TAC `u:A` THEN
  MATCH_MP_TAC(TAUT `(a ==> (p <=> q)) ==> ((a /\ p) <=> (a /\ q))`) THEN
  DISCH_TAC THEN
  MATCH_MP_TAC(MESON[]
               `(!v:A. P v <=> Q v) ==> ((?v:A. P v) <=> (?v:A. Q v))`) THEN
  X_GEN_TAC `v':A` THEN
  MATCH_MP_TAC(TAUT `(a ==> (p <=> q)) ==> ((a /\ p) <=> (a /\ q))`) THEN
  DISCH_TAC THEN
  MATCH_MP_TAC(MESON[]
               `(!ru:A. P ru <=> Q ru) ==>
                ((?ru:A. P ru) <=> (?ru:A. Q ru))`) THEN
  X_GEN_TAC `ru:A` THEN
  MATCH_MP_TAC(TAUT `(a ==> (p <=> q)) ==> ((a /\ p) <=> (a /\ q))`) THEN
  DISCH_TAC THEN
  MATCH_MP_TAC(MESON[]
               `(!rv:A. P rv <=> Q rv) ==>
                ((?rv:A. P rv) <=> (?rv:A. Q rv))`) THEN
  X_GEN_TAC `rv:A` THEN
  MATCH_MP_TAC(TAUT `(a ==> (p <=> q)) ==> ((a /\ p) <=> (a /\ q))`) THEN
  DISCH_TAC THEN
  SUBGOAL_THEN
   `valuation D ((5 |-> (rv:A)) ((4 |-> (ru:A)) ((3 |-> (v':A)) ((2 |-> (u:A))
      ((1 |-> (code:A)) ((0 |-> (pr:A)) (vv:num->A)))))))`
  ASSUME_TAC THENL
   [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
  REWRITE_TAC[HOLDS_AND] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
    `(5 |-> (rv:A)) ((4 |-> (ru:A)) ((3 |-> (v':A)) ((2 |-> (u:A))
      ((1 |-> (code:A)) ((0 |-> (pr:A)) (vv:num->A))))))`;
    `2`; `3`; `0`] HOLDS_OPAIR_FORM) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
    `(5 |-> (rv:A)) ((4 |-> (ru:A)) ((3 |-> (v':A)) ((2 |-> (u:A))
      ((1 |-> (code:A)) ((0 |-> (pr:A)) (vv:num->A))))))`;
    `6`; `2`; `4`] HOLDS_APPLY_FORM) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
    `(5 |-> (rv:A)) ((4 |-> (ru:A)) ((3 |-> (v':A)) ((2 |-> (u:A))
      ((1 |-> (code:A)) ((0 |-> (pr:A)) (vv:num->A))))))`;
    `6`; `3`; `5`] HOLDS_APPLY_FORM) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
    `(5 |-> (rv:A)) ((4 |-> (ru:A)) ((3 |-> (v':A)) ((2 |-> (u:A))
      ((1 |-> (code:A)) ((0 |-> (pr:A)) (vv:num->A))))))`;
    `4`; `5`; `1`] HOLDS_OPAIR_FORM) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
    `(5 |-> (rv:A)) ((4 |-> (ru:A)) ((3 |-> (v':A)) ((2 |-> (u:A))
      ((1 |-> (code:A)) ((0 |-> (pr:A)) (vv:num->A))))))`;
    `0`; `7`; `8`; `9`; `10`] HOLDS_DISAGREE_FORM) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  ASM_REWRITE_TAC[VALMOD; ARITH_EQ]);;

(* INC3.1d step 2: EBVBADSET_EXISTS -- the rank-code image set
   S = { <rank u, rank v> : <u,v> IN w x w, tables disagree at <u,v> },
   via a 2nd ZF replacement along the composite formula, using apply_form
   lookups on RG (flexible slots, NO bnrank_form) fused with disagree_form. *)

let EBVBADSET_EXISTS = prove
 (`!D (E:A->A->bool) B w RG sIN sIN' sEQ sEQ'.
        model D E ZF_AX /\ B IN D /\ w IN D /\
        (!z. z IN D /\ E z w ==> bname D E B z) /\
        RG IN D /\ eisfun D E RG /\ edomain D E RG w /\
        (!x r. x IN D /\ E x w /\ ebnrank D E B x r ==> eapply D E RG x r) /\
        (!z. z IN D
             ==> (E z RG <=>
                  ?x r. x IN D /\ r IN D /\ E x w /\
                        ebnrank D E B x r /\ eopair D E x r z)) /\
        sIN IN D /\ sIN' IN D /\ sEQ IN D /\ sEQ' IN D
        ==> ?S. S IN D /\
                (!z. z IN D
                     ==> (E z S <=>
                          ?u v ru rv pr.
                             u IN D /\ v IN D /\ ru IN D /\ rv IN D /\
                             pr IN D /\
                             E u w /\ E v w /\
                             ebnrank D E B u ru /\ ebnrank D E B v rv /\
                             eopair D E u v pr /\ eopair D E ru rv z /\
                             (bvdisagree D E sIN sIN' pr \/
                              bvdisagree D E sEQ sEQ' pr)))`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "zf BD wD allc RGD funRG h look RGmem sIND sIND2 sEQD sEQD2" THEN
  (* -- eapply RG lookup implies ebnrank -- *)
  SUBGOAL_THEN
   `!x r:A. x IN D /\ r IN D /\ eapply D E RG x r ==> ebnrank D E B x r`
  (LABEL_TAC "e2r") THENL
   [REPEAT GEN_TAC THEN REWRITE_TAC[eapply] THEN
    DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC (CONJUNCTS_THEN2 ASSUME_TAC
      (X_CHOOSE_THEN `zz:A` STRIP_ASSUME_TAC))) THEN
    SUBGOAL_THEN `(zz:A) IN D` ASSUME_TAC THENL
     [ASM_MESON_TAC[EOPAIR_IN]; ALL_TAC] THEN
    USE_THEN "RGmem" (MP_TAC o SPEC `zz:A`) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    ASM_REWRITE_TAC[] THEN
    DISCH_THEN(X_CHOOSE_THEN `x':A` (X_CHOOSE_THEN `r':A`
      STRIP_ASSUME_TAC)) THEN
    SUBGOAL_THEN `(x':A) = x /\ (r':A) = r` STRIP_ASSUME_TAC THENL
     [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `x':A`; `r':A`;
        `x:A`; `r:A`; `zz:A`] EOPAIR_INJ) THEN ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    ASM_MESON_TAC[]; ALL_TAC] THEN
  (* -- rank exists for members of w -- *)
  SUBGOAL_THEN
   `!x:A. x IN D /\ E x w ==> ?r. r IN D /\ ebnrank D E B x r`
  (LABEL_TAC "rk") THENL
   [REPEAT STRIP_TAC THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `B:A`; `x:A`]
      EBNRANK_EXISTS) THEN
    ASM_MESON_TAC[]; ALL_TAC] THEN
  (* -- base valuation and P = w x w -- *)
  SUBGOAL_THEN `?v0:num->A. valuation D v0` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[VALUATION_EXISTS; MODEL_NONEMPTY]; ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `w:A`; `w:A`] ECROSS_EXISTS) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `P:A` MP_TAC) THEN REWRITE_TAC[ecross] THEN
  DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC (LABEL_TAC "Pc")) THEN
  (* -- parked data valuation -- *)
  ABBREV_TAC
   `vv = (10 |-> (sEQ':A)) ((9 |-> (sEQ:A)) ((8 |-> (sIN':A))
      ((7 |-> (sIN:A)) ((6 |-> (RG:A)) (v0:num->A)))))` THEN
  SUBGOAL_THEN
   `valuation D (vv:num->A) /\
    (vv:num->A) 6 = RG /\ vv 7 = sIN /\ vv 8 = sIN' /\
    vv 9 = sEQ /\ vv 10 = sEQ'`
  STRIP_ASSUME_TAC THENL
   [EXPAND_TAC "vv" THEN
    REWRITE_TAC[VALMOD; ARITH_EQ] THEN
    ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
  (* -- the HOLDS bridge for the composite formula -- *)
  SUBGOAL_THEN
   `!pr code:A. pr IN D /\ code IN D
      ==> (holds D E ((1 |-> code) ((0 |-> pr) vv))
             (?? 2 (?? 3 (?? 4 (?? 5
                (opair_form 2 3 0 &&
                 apply_form 6 2 4 &&
                 apply_form 6 3 5 &&
                 opair_form 4 5 1 &&
                 disagree_form 0 7 8 9 10))))) <=>
           ?u. u IN D /\ ?v. v IN D /\ ?ru. ru IN D /\ ?rv. rv IN D /\
               eopair D E u v pr /\
               eapply D E RG u ru /\ eapply D E RG v rv /\
               eopair D E ru rv code /\
               (bvdisagree D E sIN sIN' pr \/ bvdisagree D E sEQ sEQ' pr))`
  (LABEL_TAC "hb") THENL
   [REPEAT GEN_TAC THEN STRIP_TAC THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `vv:num->A`; `RG:A`;
      `sIN:A`; `sIN':A`; `sEQ:A`; `sEQ':A`; `pr:A`; `code:A`]
      EBVBAD_BRIDGE) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC]; ALL_TAC] THEN
  (* -- ZF replacement builds S -- *)
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`] ZF_REPLACEMENT) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(MP_TAC o SPECL
    [`?? 2 (?? 3 (?? 4 (?? 5
        (opair_form 2 3 0 &&
         apply_form 6 2 4 &&
         apply_form 6 3 5 &&
         opair_form 4 5 1 &&
         disagree_form 0 7 8 9 10))))`;
     `0`; `1`; `vv:num->A`; `P:A`]) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[ARITH_EQ] THEN
    X_GEN_TAC `pr:A` THEN STRIP_TAC THEN
    SUBGOAL_THEN
     `?u1 v1:A. u1 IN D /\ v1 IN D /\ E u1 w /\ E v1 w /\
                eopair D E u1 v1 pr`
    STRIP_ASSUME_TAC THENL
     [REMOVE_THEN "Pc" (MP_TAC o SPEC `pr:A`) THEN
      ASM_REWRITE_TAC[] THEN MESON_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN `?ru1:A. ru1 IN D /\ ebnrank D E B (u1:A) ru1`
    STRIP_ASSUME_TAC THENL [ASM_MESON_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN `?rv1:A. rv1 IN D /\ ebnrank D E B (v1:A) rv1`
    STRIP_ASSUME_TAC THENL [ASM_MESON_TAC[]; ALL_TAC] THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `ru1:A`; `rv1:A`]
      EOPAIR_EXISTS) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(X_CHOOSE_TAC `z1:A`) THEN
    SUBGOAL_THEN `(z1:A) IN D` ASSUME_TAC THENL
     [ASM_MESON_TAC[EOPAIR_IN]; ALL_TAC] THEN
    EXISTS_TAC `z1:A` THEN ASM_REWRITE_TAC[] THEN
    X_GEN_TAC `w':A` THEN
    DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC MP_TAC) THEN
    USE_THEN "hb" (MP_TAC o SPECL [`pr:A`; `w':A`]) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    INTRO_TAC "@u'. uD @v'. vD @ru'. ruD @rv'. rvD oppr apru aprv opw h" THEN
    SUBGOAL_THEN `(u':A) = u1 /\ (v':A) = v1`
      (CONJUNCTS_THEN SUBST_ALL_TAC) THENL
     [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `u':A`; `v':A`;
        `u1:A`; `v1:A`; `pr:A`] EOPAIR_INJ) THEN ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    SUBGOAL_THEN `ebnrank D E B (u1:A) (ru':A)` ASSUME_TAC THENL
     [USE_THEN "e2r" MATCH_MP_TAC THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN `ebnrank D E B (v1:A) (rv':A)` ASSUME_TAC THENL
     [USE_THEN "e2r" MATCH_MP_TAC THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN `(ru':A) = ru1 /\ (rv':A) = rv1`
      (CONJUNCTS_THEN SUBST_ALL_TAC) THENL
     [CONJ_TAC THENL
       [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `B:A`; `u1:A`;
          `ru':A`; `ru1:A`] EBNRANK_UNIQUE) THEN ASM_REWRITE_TAC[];
        MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `B:A`; `v1:A`;
          `rv':A`; `rv1:A`] EBNRANK_UNIQUE) THEN ASM_REWRITE_TAC[]];
      ALL_TAC] THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `ru1:A`; `rv1:A`;
      `w':A`; `z1:A`] EOPAIR_UNIQUE) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `S:A` (CONJUNCTS_THEN2 ASSUME_TAC
    (LABEL_TAC "raw"))) THEN
  EXISTS_TAC `S:A` THEN ASM_REWRITE_TAC[] THEN
  X_GEN_TAC `z:A` THEN DISCH_TAC THEN
  USE_THEN "raw" (MP_TAC o SPEC `z:A`) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  EQ_TAC THENL
   [DISCH_THEN(X_CHOOSE_THEN `pr0:A` (CONJUNCTS_THEN2 ASSUME_TAC
      (CONJUNCTS_THEN2 ASSUME_TAC MP_TAC))) THEN
    USE_THEN "hb" (MP_TAC o SPECL [`pr0:A`; `z:A`]) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    INTRO_TAC "@u. uD @v. vD @ru. ruD @rv. rvD oppr0 apru aprv opz h" THEN
    SUBGOAL_THEN `E (u:A) (w:A) /\ E (v:A) (w:A)` STRIP_ASSUME_TAC THENL
     [SUBGOAL_THEN
       `?u2 v2:A. u2 IN D /\ v2 IN D /\ E u2 w /\ E v2 w /\
                  eopair D E u2 v2 pr0`
      STRIP_ASSUME_TAC THENL
       [REMOVE_THEN "Pc" (MP_TAC o SPEC `pr0:A`) THEN
        ASM_REWRITE_TAC[] THEN MESON_TAC[]; ALL_TAC] THEN
      SUBGOAL_THEN `(u:A) = u2 /\ (v:A) = v2` STRIP_ASSUME_TAC THENL
       [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `u:A`; `v:A`;
          `u2:A`; `v2:A`; `pr0:A`] EOPAIR_INJ) THEN ASM_REWRITE_TAC[];
        ALL_TAC] THEN
      ASM_REWRITE_TAC[]; ALL_TAC] THEN
    MAP_EVERY EXISTS_TAC [`u:A`; `v:A`; `ru:A`; `rv:A`; `pr0:A`] THEN
    REPEAT CONJ_TAC THENL
     [FIRST_ASSUM ACCEPT_TAC;
      FIRST_ASSUM ACCEPT_TAC;
      FIRST_ASSUM ACCEPT_TAC;
      FIRST_ASSUM ACCEPT_TAC;
      FIRST_ASSUM ACCEPT_TAC;
      FIRST_ASSUM ACCEPT_TAC;
      FIRST_ASSUM ACCEPT_TAC;
      USE_THEN "e2r" MATCH_MP_TAC THEN ASM_REWRITE_TAC[];
      USE_THEN "e2r" MATCH_MP_TAC THEN ASM_REWRITE_TAC[];
      FIRST_ASSUM ACCEPT_TAC;
      FIRST_ASSUM ACCEPT_TAC;
      FIRST_ASSUM ACCEPT_TAC];
    INTRO_TAC "@u v ru rv pr. uD vD ruD rvD prD uw vw h h2 oppr opz h3" THEN
    EXISTS_TAC `pr:A` THEN ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
     [USE_THEN "Pc" (MP_TAC o SPEC `pr:A`) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
      MAP_EVERY EXISTS_TAC [`u:A`; `v:A`] THEN ASM_REWRITE_TAC[];
      USE_THEN "hb" (MP_TAC o SPECL [`pr:A`; `z:A`]) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
      EXISTS_TAC `u:A` THEN ASM_REWRITE_TAC[] THEN
      EXISTS_TAC `v:A` THEN ASM_REWRITE_TAC[] THEN
      EXISTS_TAC `ru:A` THEN ASM_REWRITE_TAC[] THEN
      EXISTS_TAC `rv:A` THEN ASM_REWRITE_TAC[] THEN
      REPEAT CONJ_TAC THEN
      TRY(USE_THEN "look" MATCH_MP_TAC) THEN ASM_REWRITE_TAC[]]]);;

(* INC3.1d step 3: EBVBAD_LEAST -- EMLEX_LEAST wrapper on the bad-set.
   If the tables disagree at some pair in w x w, there is an emlex-least
   bad rank-code z0 = <rank u0, rank v0> with a witnessing bad pair (u0,v0),
   and every other bad pair's code is emlex-above z0. *)

let EBVBAD_LEAST = prove
 (`!D (E:A->A->bool) B w RG sIN sIN' sEQ sEQ'.
        model D E ZF_AX /\ B IN D /\ w IN D /\
        (!z. z IN D /\ E z w ==> bname D E B z) /\
        RG IN D /\ eisfun D E RG /\ edomain D E RG w /\
        (!x r. x IN D /\ E x w /\ ebnrank D E B x r ==> eapply D E RG x r) /\
        (!z. z IN D
             ==> (E z RG <=>
                  ?x r. x IN D /\ r IN D /\ E x w /\
                        ebnrank D E B x r /\ eopair D E x r z)) /\
        sIN IN D /\ sIN' IN D /\ sEQ IN D /\ sEQ' IN D /\
        (?u v pr. u IN D /\ v IN D /\ pr IN D /\ E u w /\ E v w /\
                  eopair D E u v pr /\
                  (bvdisagree D E sIN sIN' pr \/ bvdisagree D E sEQ sEQ' pr))
        ==> ?u0 v0 ru0 rv0 pr0 z0.
               u0 IN D /\ v0 IN D /\ ru0 IN D /\ rv0 IN D /\
               pr0 IN D /\ z0 IN D /\
               E u0 w /\ E v0 w /\
               ebnrank D E B u0 ru0 /\ ebnrank D E B v0 rv0 /\
               eopair D E u0 v0 pr0 /\ eopair D E ru0 rv0 z0 /\
               (bvdisagree D E sIN sIN' pr0 \/ bvdisagree D E sEQ sEQ' pr0) /\
               (!u v ru rv pr z.
                    u IN D /\ v IN D /\ ru IN D /\ rv IN D /\
                    pr IN D /\ z IN D /\
                    E u w /\ E v w /\
                    ebnrank D E B u ru /\ ebnrank D E B v rv /\
                    eopair D E u v pr /\ eopair D E ru rv z /\
                    (bvdisagree D E sIN sIN' pr \/
                     bvdisagree D E sEQ sEQ' pr) /\
                    ~(z = z0)
                    ==> emlex D E z0 z)`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "zf BD wD bn RGD funRG h look RGmem sIND sIND2 sEQD sEQD2 \
             @ua va pra. praD vD prD uw vw oppr h2" THEN
  (* -- small rank/pair facts, established BEFORE the big bad-set        *)
  (* -- characterization Sc enters the assumptions (Sc would make MESON  *)
  (* -- diverge on its 5-existential biconditional RHS)                  *)
  SUBGOAL_THEN `bname D (E:A->A->bool) B (ua:A) /\ bname D E B (va:A)`
  STRIP_ASSUME_TAC THENL
   [CONJ_TAC THEN USE_THEN "bn" MATCH_MP_TAC THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `?rua:A. rua IN D /\ ebnrank D E B (ua:A) rua`
  STRIP_ASSUME_TAC THENL
   [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `B:A`; `ua:A`]
      EBNRANK_EXISTS) THEN ASM_MESON_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `?rva:A. rva IN D /\ ebnrank D E B (va:A) rva`
  STRIP_ASSUME_TAC THENL
   [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `B:A`; `va:A`]
      EBNRANK_EXISTS) THEN ASM_MESON_TAC[]; ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `rua:A`; `rva:A`]
    EOPAIR_EXISTS) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_TAC `za:A`) THEN
  SUBGOAL_THEN `(za:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[EOPAIR_IN]; ALL_TAC] THEN
  (* -- recover the bad-set S and its membership characterization Sc -- *)
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `B:A`; `w:A`; `RG:A`;
    `sIN:A`; `sIN':A`; `sEQ:A`; `sEQ':A`] EBVBADSET_EXISTS) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `S:A` (CONJUNCTS_THEN2 ASSUME_TAC
    (LABEL_TAC "Sc"))) THEN
  (* -- the given bad pair's code za lies in S -- *)
  SUBGOAL_THEN `(E:A->A->bool) (za:A) (S:A)` ASSUME_TAC THENL
   [USE_THEN "Sc" (MP_TAC o SPEC `za:A`) THEN
    ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    MAP_EVERY EXISTS_TAC [`ua:A`; `va:A`; `rua:A`; `rva:A`; `pra:A`] THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* -- least bad code via EMLEX_LEAST -- *)
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `S:A`] EMLEX_LEAST) THEN
  ANTS_TAC THENL
   [REPEAT CONJ_TAC THENL
     [FIRST_ASSUM ACCEPT_TAC;
      FIRST_ASSUM ACCEPT_TAC;
      X_GEN_TAC `z:A` THEN STRIP_TAC THEN
      SUBGOAL_THEN
       `?u v ru rv pr:A.
           u IN D /\ v IN D /\ ru IN D /\ rv IN D /\ pr IN D /\
           E u w /\ E v w /\
           ebnrank D E B u ru /\ ebnrank D E B v rv /\
           eopair D E u v pr /\ eopair D E ru rv z /\
           (bvdisagree D E sIN sIN' pr \/ bvdisagree D E sEQ sEQ' pr)`
      (X_CHOOSE_THEN `u:A` (X_CHOOSE_THEN `v:A` (X_CHOOSE_THEN `ru:A`
       (X_CHOOSE_THEN `rv:A` (X_CHOOSE_THEN `pr:A`
         (REPEAT_TCL CONJUNCTS_THEN ASSUME_TAC)))))) THENL
       [USE_THEN "Sc" (MP_TAC o SPEC `z:A`) THEN
        ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
        DISCH_THEN(fun th -> FIRST_ASSUM(ACCEPT_TAC o EQ_MP th));
        ALL_TAC] THEN
      MAP_EVERY EXISTS_TAC [`ru:A`; `rv:A`] THEN
      ASM_REWRITE_TAC[] THEN
      CONJ_TAC THEN
      FIRST_ASSUM(fun th -> ACCEPT_TAC(MATCH_MP EBNRANK_ORDINAL th));
      EXISTS_TAC `za:A` THEN CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC];
    ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `z0:A` (CONJUNCTS_THEN2 ASSUME_TAC
    (CONJUNCTS_THEN2 ASSUME_TAC (LABEL_TAC "Mc")))) THEN
  (* -- recover the witnessing bad pair for z0 -- *)
  SUBGOAL_THEN
   `?u0 v0 ru0 rv0 pr0:A.
       u0 IN D /\ v0 IN D /\ ru0 IN D /\ rv0 IN D /\ pr0 IN D /\
       E u0 w /\ E v0 w /\
       ebnrank D E B u0 ru0 /\ ebnrank D E B v0 rv0 /\
       eopair D E u0 v0 pr0 /\ eopair D E ru0 rv0 z0 /\
       (bvdisagree D E sIN sIN' pr0 \/ bvdisagree D E sEQ sEQ' pr0)`
  (X_CHOOSE_THEN `u0:A` (X_CHOOSE_THEN `v0:A` (X_CHOOSE_THEN `ru0:A`
   (X_CHOOSE_THEN `rv0:A` (X_CHOOSE_THEN `pr0:A`
     (REPEAT_TCL CONJUNCTS_THEN ASSUME_TAC)))))) THENL
   [USE_THEN "Sc" (MP_TAC o SPEC `z0:A`) THEN
    ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN(fun th -> FIRST_ASSUM(ACCEPT_TAC o EQ_MP th));
    ALL_TAC] THEN
  MAP_EVERY EXISTS_TAC
   [`u0:A`; `v0:A`; `ru0:A`; `rv0:A`; `pr0:A`; `z0:A`] THEN
  ASM_REWRITE_TAC[] THEN
  (* -- minimality over bad pairs -- *)
  MAP_EVERY X_GEN_TAC [`u:A`; `v:A`; `ru:A`; `rv:A`; `pr:A`; `z:A`] THEN
  DISCH_THEN(REPEAT_TCL CONJUNCTS_THEN ASSUME_TAC) THEN
  USE_THEN "Mc" MATCH_MP_TAC THEN
  REPEAT CONJ_TAC THENL
   [FIRST_ASSUM ACCEPT_TAC;
    USE_THEN "Sc" (MP_TAC o SPEC `z:A`) THEN
    ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    MAP_EVERY EXISTS_TAC [`u:A`; `v:A`; `ru:A`; `rv:A`; `pr:A`] THEN
    ASM_REWRITE_TAC[];
    FIRST_ASSUM ACCEPT_TAC]);;

(* ===== F4-INC3.1e plumbing: function-graph agreement lemmas ===== *)
(* A Kuratowski pair with an off-domain 2nd component collapses to the      *)
(* diagonal (the my-disjunct in epair vanishes for w IN D when my NOTIN D). *)
(* Hence two function-graphs that agree in VALUE at a slot agree as GRAPHS  *)
(* there (full iff, incl. spurious off-domain values) -- the form the       *)
(* EBVIN_CONG/EBVEQ_CONG congruence hypotheses want.                        *)

let EPAIR_COLLAPSE = prove
 (`!D (E:A->A->bool) pr my p.
      ~(my IN D) ==> (epair D E pr my p <=> epair D E pr pr p)`,
  REPEAT GEN_TAC THEN REWRITE_TAC[epair] THEN MESON_TAC[]);;

let EOPAIR_COLLAPSE = prove
 (`!D (E:A->A->bool) pr my z.
      ~(my IN D) ==> (eopair D E pr my z <=> eopair D E pr pr z)`,
  REPEAT GEN_TAC THEN DISCH_TAC THEN REWRITE_TAC[eopair] THEN
  ASM_MESON_TAC[EPAIR_COLLAPSE]);;

let GRAPH_AGREE_IFF = prove
 (`!D (E:A->A->bool) f g pr a.
      model D E ZF_AX /\ eisfun D E f /\ eisfun D E g /\
      pr IN D /\ a IN D /\ eapply D E f pr a /\ eapply D E g pr a
      ==> (!m. eapply D E f pr m <=> eapply D E g pr m)`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN X_GEN_TAC `m:A` THEN
  ASM_CASES_TAC `(m:A) IN D` THENL
   [SUBGOAL_THEN `eapply D E f pr m <=> (m:A) = a` SUBST1_TAC THENL
     [EQ_TAC THENL
       [DISCH_TAC THEN
        MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `f:A`; `pr:A`; `m:A`;
          `a:A`] EAPPLY_UNIQUE) THEN ASM_REWRITE_TAC[];
        DISCH_THEN SUBST_ALL_TAC THEN ASM_REWRITE_TAC[]];
      ALL_TAC] THEN
    SUBGOAL_THEN `eapply D E g pr m <=> (m:A) = a` SUBST1_TAC THENL
     [EQ_TAC THENL
       [DISCH_TAC THEN
        MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `g:A`; `pr:A`; `m:A`;
          `a:A`] EAPPLY_UNIQUE) THEN ASM_REWRITE_TAC[];
        DISCH_THEN SUBST_ALL_TAC THEN ASM_REWRITE_TAC[]];
      ALL_TAC] THEN
    REWRITE_TAC[];
    SUBGOAL_THEN `eapply D (E:A->A->bool) f pr m <=> eapply D E f pr pr`
    SUBST1_TAC THENL
     [REWRITE_TAC[eapply] THEN ASM_MESON_TAC[EOPAIR_COLLAPSE]; ALL_TAC] THEN
    SUBGOAL_THEN `eapply D (E:A->A->bool) g pr m <=> eapply D E g pr pr`
    SUBST1_TAC THENL
     [REWRITE_TAC[eapply] THEN ASM_MESON_TAC[EOPAIR_COLLAPSE]; ALL_TAC] THEN
    SUBGOAL_THEN `eapply D E f pr pr <=> (pr:A) = a` SUBST1_TAC THENL
     [EQ_TAC THENL
       [DISCH_TAC THEN
        MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `f:A`; `pr:A`; `pr:A`;
          `a:A`] EAPPLY_UNIQUE) THEN ASM_REWRITE_TAC[];
        DISCH_THEN SUBST_ALL_TAC THEN ASM_REWRITE_TAC[]];
      ALL_TAC] THEN
    SUBGOAL_THEN `eapply D E g pr pr <=> (pr:A) = a` SUBST1_TAC THENL
     [EQ_TAC THENL
       [DISCH_TAC THEN
        MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `g:A`; `pr:A`; `pr:A`;
          `a:A`] EAPPLY_UNIQUE) THEN ASM_REWRITE_TAC[];
        DISCH_THEN SUBST_ALL_TAC THEN ASM_REWRITE_TAC[]];
      ALL_TAC] THEN
    REWRITE_TAC[]]);;

(* ===== F4-INC3.1e: ebvatt definition + minimal-counterexample kit ===== *)
(* ebvatt: the twin B-value attempt (two function-graphs sIN [IN-table]  *)
(* and sEQ [=-table] over w x w, each reading the OTHER via ebvin/ebveq). *)

let ebvatt = new_definition
  `ebvatt D (E:A->A->bool) B leq w sIN sEQ <=>
      eisfun D E sIN /\ eisfun D E sEQ /\
      (?c. ecross D E w w c /\ edomain D E sIN c /\ edomain D E sEQ c) /\
      (!u v. u IN D /\ v IN D /\ E u w /\ E v w
             ==> ?pr val. eopair D E u v pr /\ eapply D E sIN pr val /\
                          ebvin D E B leq sEQ v u val) /\
      (!u v. u IN D /\ v IN D /\ E u w /\ E v w
             ==> ?pr val. eopair D E u v pr /\ eapply D E sEQ pr val /\
                          ebveq D E B leq sIN u v val)`;;

let EAPPLY_DVAL = prove
 (`!D (E:A->A->bool) f y qy.
      model D E ZF_AX /\ y IN D /\ eapply D E f y qy
      ==> ?q0. q0 IN D /\ eapply D E f y q0`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  ASM_CASES_TAC `(qy:A) IN D` THENL
   [EXISTS_TAC `qy:A` THEN ASM_REWRITE_TAC[];
    EXISTS_TAC `y:A` THEN ASM_REWRITE_TAC[] THEN
    REWRITE_TAC[eapply] THEN
    UNDISCH_TAC `eapply D (E:A->A->bool) f y qy` THEN REWRITE_TAC[eapply] THEN
    DISCH_THEN(X_CHOOSE_THEN `z:A` STRIP_ASSUME_TAC) THEN
    EXISTS_TAC `z:A` THEN ASM_REWRITE_TAC[] THEN
    MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `y:A`; `qy:A`; `z:A`]
      EOPAIR_COLLAPSE) THEN ASM_REWRITE_TAC[]]);;

let EBVATT_PAIR_IFF = prove
 (`!D (E:A->A->bool) sIN sIN' sEQ sEQ' pr.
      model D E ZF_AX /\
      eisfun D E sIN /\ eisfun D E sIN' /\ eisfun D E sEQ /\ eisfun D E sEQ' /\
      pr IN D /\
      (?vi. vi IN D /\ eapply D E sIN pr vi) /\
      (?vj. vj IN D /\ eapply D E sIN' pr vj) /\
      (?ve. ve IN D /\ eapply D E sEQ pr ve) /\
      (?vf. vf IN D /\ eapply D E sEQ' pr vf) /\
      ~bvdisagree D E sIN sIN' pr /\ ~bvdisagree D E sEQ sEQ' pr
      ==> (!m. eapply D E sIN pr m <=> eapply D E sIN' pr m) /\
          (!m. eapply D E sEQ pr m <=> eapply D E sEQ' pr m)`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN CONJ_TAC THENL
   [MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `sIN:A`; `sIN':A`; `pr:A`;
      `vi:A`] GRAPH_AGREE_IFF) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[] THEN
      SUBGOAL_THEN `(vi:A) = vj` SUBST1_TAC THENL
       [UNDISCH_TAC `~bvdisagree D (E:A->A->bool) sIN sIN' pr` THEN
        REWRITE_TAC[bvdisagree] THEN
        DISCH_THEN(MP_TAC o SPECL [`vi:A`; `vj:A`]) THEN ASM_REWRITE_TAC[];
        FIRST_ASSUM ACCEPT_TAC];
      DISCH_THEN ACCEPT_TAC];
    MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `sEQ:A`; `sEQ':A`; `pr:A`;
      `ve:A`] GRAPH_AGREE_IFF) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[] THEN
      SUBGOAL_THEN `(ve:A) = vf` SUBST1_TAC THENL
       [UNDISCH_TAC `~bvdisagree D (E:A->A->bool) sEQ sEQ' pr` THEN
        REWRITE_TAC[bvdisagree] THEN
        DISCH_THEN(MP_TAC o SPECL [`ve:A`; `vf:A`]) THEN ASM_REWRITE_TAC[];
        FIRST_ASSUM ACCEPT_TAC];
      DISCH_THEN ACCEPT_TAC]]);;

let EBVATT_VAL = prove
 (`!D (E:A->A->bool) B leq w sIN sEQ u v pr.
      model D E ZF_AX /\ ecba D E B leq /\ ebvatt D E B leq w sIN sEQ /\
      u IN D /\ v IN D /\ E u w /\ E v w /\ eopair D E u v pr
      ==> (?vi. vi IN D /\ eapply D E sIN pr vi /\
           ebvin D E B leq sEQ v u vi) /\
          (?ve. ve IN D /\ eapply D E sEQ pr ve /\
           ebveq D E B leq sIN u v ve)`,
  REPEAT GEN_TAC THEN
  DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC (CONJUNCTS_THEN2 ASSUME_TAC
    (CONJUNCTS_THEN2 (LABEL_TAC "att") STRIP_ASSUME_TAC))) THEN
  USE_THEN "att" (MP_TAC o REWRITE_RULE[ebvatt]) THEN
  INTRO_TAC "funsIN funsEQ h rdI rdE" THEN
  CONJ_TAC THENL
   [REMOVE_THEN "rdI" (MP_TAC o SPECL [`u:A`; `v:A`]) THEN
    ASM_REWRITE_TAC[] THEN
    DISCH_THEN(X_CHOOSE_THEN `prI:A` (X_CHOOSE_THEN `vali:A`
      STRIP_ASSUME_TAC)) THEN
    SUBGOAL_THEN `(prI:A) = pr` SUBST_ALL_TAC THENL
     [MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `u:A`; `v:A`; `prI:A`;
        `pr:A`] EOPAIR_UNIQUE) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    FIRST_ASSUM(STRIP_ASSUME_TAC o MATCH_MP EBVIN_IN) THEN
    EXISTS_TAC `vali:A` THEN ASM_REWRITE_TAC[];
    REMOVE_THEN "rdE" (MP_TAC o SPECL [`u:A`; `v:A`]) THEN
    ASM_REWRITE_TAC[] THEN
    DISCH_THEN(X_CHOOSE_THEN `prE:A` (X_CHOOSE_THEN `vale:A`
      STRIP_ASSUME_TAC)) THEN
    SUBGOAL_THEN `(prE:A) = pr` SUBST_ALL_TAC THENL
     [MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `u:A`; `v:A`; `prE:A`;
        `pr:A`] EOPAIR_UNIQUE) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    FIRST_ASSUM(STRIP_ASSUME_TAC o MATCH_MP EBVEQ_IN) THEN
    EXISTS_TAC `vale:A` THEN ASM_REWRITE_TAC[]]);;

(* ===================================================================== *)
(* F4: existence of a Boolean-value attempt at every bname-stage.         *)
(* Sub-lemma e2a -- EBVATT_RANKBOUND: every element u of a stage           *)
(* w = ebnstage k has bname-rank ru strictly below esuc k.  Hence all     *)
(* rank-codes <bnrank u, bnrank v> of pairs from w x w live in            *)
(* (esuc k) x (esuc k), and EPRODK_ENUM (esuc k) linearises them under    *)
(* mlex into an ordinal order type d, driving the erec recursion.         *)
(* Proof: ebnrank's minimality clause (no c < ru has u in ebnstage c),    *)
(* taken at c := k, contradicts u IN w = ebnstage k, so ~(E k ru);        *)
(* EORDINAL_TRICHOTOMY then gives ru <= k, and ESUC_E lifts that to        *)
(* E ru (esuc k).                                                          *)
(* ===================================================================== *)

let EBVATT_RANKBOUND = prove
 (`!D (E:A->A->bool) B k w u ru z.
      model D E ZF_AX /\ B IN D /\ k IN D /\ eordinal D E k /\ w IN D /\
      ebnstage D E B k w /\ E u w /\ ebnrank D E B u ru /\ esuc D E k z
      ==> E ru z`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `(ru:A) IN D` ASSUME_TAC THENL
   [FIRST_ASSUM(ACCEPT_TAC o MATCH_MP EBNRANK_IN); ALL_TAC] THEN
  SUBGOAL_THEN `eordinal D (E:A->A->bool) ru` ASSUME_TAC THENL
   [FIRST_ASSUM(ACCEPT_TAC o MATCH_MP EBNRANK_ORDINAL); ALL_TAC] THEN
  SUBGOAL_THEN `(z:A) IN D` ASSUME_TAC THENL
   [MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `k:A`; `z:A`] ESUC_ALT) THEN
    ASM_REWRITE_TAC[] THEN MESON_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `?y:A. y IN D /\ ebnstage D E B k y /\ E u y`
   (LABEL_TAC "wit") THENL
   [EXISTS_TAC `w:A` THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `~((E:A->A->bool) k ru)` ASSUME_TAC THENL
   [UNDISCH_TAC `ebnrank D (E:A->A->bool) B u ru` THEN
    REWRITE_TAC[ebnrank] THEN
    DISCH_THEN(MP_TAC o SPEC `k:A` o CONJUNCT2 o CONJUNCT2) THEN
    ASM_MESON_TAC[]; ALL_TAC] THEN
  MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `ru:A`; `k:A`]
    EORDINAL_TRICHOTOMY) THEN
  ASM_REWRITE_TAC[] THEN
  MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `k:A`; `z:A`; `ru:A`]
         ESUC_E) THEN
  ASM_REWRITE_TAC[] THEN
  ASM_MESON_TAC[]);;

(* Sub-lemma e2a(cont): the rank-code <bnrank u, bnrank v> of any pair       *)
(* <u,v> from w x w (w = ebnstage k) lands in the EPRODK_ENUM (esuc k) set q *)
(* = { <a,b> : a,b IN esuc k }.  Two RANKBOUND hits + q's membership clause. *)
(* This is the first half of "every w x w pair's code = f(delta) for some    *)
(* delta IN d", the coverage fact the e2e assembly needs.                    *)

let EBVATT_RANKCODE_IN_Q = prove
 (`!D (E:A->A->bool) B k kk w u v ru rv code q.
      model D E ZF_AX /\ B IN D /\ k IN D /\ eordinal D E k /\ w IN D /\
      ebnstage D E B k w /\ esuc D E k kk /\
      E u w /\ E v w /\
      ebnrank D E B u ru /\ ebnrank D E B v rv /\ eopair D E ru rv code /\
      q IN D /\
      (!z. z IN D
           ==> (E z q <=> ?a b. a IN D /\ b IN D /\ E a kk /\ E b kk /\
                                eopair D E a b z))
      ==> E code q`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `(E:A->A->bool) ru kk` ASSUME_TAC THENL
   [MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `B:A`; `k:A`; `w:A`; `u:A`;
      `ru:A`; `kk:A`] EBVATT_RANKBOUND) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) rv kk` ASSUME_TAC THENL
   [MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `B:A`; `k:A`; `w:A`; `v:A`;
      `rv:A`; `kk:A`] EBVATT_RANKBOUND) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(ru:A) IN D /\ (rv:A) IN D` STRIP_ASSUME_TAC THENL
   [CONJ_TAC THEN FIRST_ASSUM(ACCEPT_TAC o MATCH_MP EBNRANK_IN); ALL_TAC] THEN
  SUBGOAL_THEN `(code:A) IN D` ASSUME_TAC THENL
   [FIRST_ASSUM(ACCEPT_TAC o MATCH_MP EOPAIR_IN); ALL_TAC] THEN
  UNDISCH_TAC
   `!z. z IN D
        ==> ((E:A->A->bool) z q <=> ?a b. a IN D /\ b IN D /\ E a kk /\
                                          E b kk /\ eopair D E a b z)` THEN
  DISCH_THEN(MP_TAC o SPEC `code:A`) THEN ASM_REWRITE_TAC[] THEN
  DISCH_THEN SUBST1_TAC THEN
  MAP_EVERY EXISTS_TAC [`ru:A`; `rv:A`] THEN ASM_REWRITE_TAC[]);;

(* ===================================================================== *)
(* F4: projection of the accumulated packed blob.                         *)
(* A stage entry is <pr,<ival,eval>> (pr = <u,v>, ival = [[u IN v]],       *)
(* eval = [[u=v]]).  T = eranu(g) accumulates them.  The recursion's step  *)
(* feeds ebvin/ebveq genuine <key,value> sub-tables, so we carve from T    *)
(* by ZF replacement:                                                       *)
(*   SEQ_acc = { <pr,eval> : <pr,<ival,eval>> IN T }   (projeq_form)        *)
(*   SIN_acc = { <pr,ival> : <pr,<ival,eval>> IN T }   (projin_form).       *)
(* EXISTS_AND_CONG peels a 4-existential HOLDS; the proj_*_form bridges are *)
(* kept TOP-LEVEL (not assumptions) so the quantified biconditional never   *)
(* poisons a later ASM_REWRITE/ASM_MESON.  REPL_SV_WITNESS packages         *)
(* "single-valued relation + nonempty D ==> replacement witness exists".    *)
(* ===================================================================== *)

(* Congruence helpers for bounded quantifiers (they keep MESON away from  *)
(* the large holds-terms).                                                *)
let FORALL_IMP_CONG = MESON[]
 `(!x:A. R x ==> (P x <=> Q x))
  ==> ((!x. R x ==> P x) <=> (!x. R x ==> Q x))`;;

let EXISTS_AND_CONG = MESON[]
 `(!x:A. R x ==> (P x <=> Q x))
  ==> ((?x. R x /\ P x) <=> (?x. R x /\ Q x))`;;

let projeq_form = new_definition
 `projeq_form =
    ?? 1 (?? 2 (?? 4 (?? 5 (opair_form 1 2 0 && opair_form 4 5 2 &&
                            opair_form 1 5 3))))`;;
let projin_form = new_definition
 `projin_form =
    ?? 1 (?? 2 (?? 4 (?? 5 (opair_form 1 2 0 && opair_form 4 5 2 &&
                            opair_form 1 4 3))))`;;
let HOLDS_PROJEQ_FORM = prove
 (`!D (E:A->A->bool) v u ot.
      valuation D v /\ u IN D /\ ot IN D
      ==> (holds D E ((3 |-> ot) ((0 |-> u) v)) projeq_form <=>
           ?pr. pr IN D /\ ?inner. inner IN D /\ ?ival. ival IN D /\
                ?eval. eval IN D /\
                eopair D E pr inner u /\ eopair D E ival eval inner /\
                eopair D E pr eval ot)`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN REWRITE_TAC[projeq_form; HOLDS_EX] THEN
  MATCH_MP_TAC EXISTS_AND_CONG THEN X_GEN_TAC `pr:A` THEN DISCH_TAC THEN
  MATCH_MP_TAC EXISTS_AND_CONG THEN X_GEN_TAC `inner:A` THEN DISCH_TAC THEN
  MATCH_MP_TAC EXISTS_AND_CONG THEN X_GEN_TAC `ival:A` THEN DISCH_TAC THEN
  MATCH_MP_TAC EXISTS_AND_CONG THEN X_GEN_TAC `eval:A` THEN DISCH_TAC THEN
  ABBREV_TAC
   `VV = (5 |-> (eval:A)) ((4 |-> (ival:A)) ((2 |-> (inner:A))
      ((1 |-> (pr:A)) ((3 |-> (ot:A)) ((0 |-> (u:A)) v)))))` THEN
  SUBGOAL_THEN `valuation D (VV:num->A)` ASSUME_TAC THENL
   [EXPAND_TAC "VV" THEN
    REPEAT(MATCH_MP_TAC VALUATION_VALMOD THEN CONJ_TAC THENL
            [ALL_TAC; FIRST_ASSUM ACCEPT_TAC]) THEN
    FIRST_ASSUM ACCEPT_TAC;
    ALL_TAC] THEN
  ASM_SIMP_TAC[HOLDS_AND; HOLDS_OPAIR_FORM] THEN
  EXPAND_TAC "VV" THEN REWRITE_TAC[VALMOD; ARITH_EQ]);;
let HOLDS_PROJIN_FORM = prove
 (`!D (E:A->A->bool) v u ot.
      valuation D v /\ u IN D /\ ot IN D
      ==> (holds D E ((3 |-> ot) ((0 |-> u) v)) projin_form <=>
           ?pr. pr IN D /\ ?inner. inner IN D /\ ?ival. ival IN D /\
                ?eval. eval IN D /\
                eopair D E pr inner u /\ eopair D E ival eval inner /\
                eopair D E pr ival ot)`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN REWRITE_TAC[projin_form; HOLDS_EX] THEN
  MATCH_MP_TAC EXISTS_AND_CONG THEN X_GEN_TAC `pr:A` THEN DISCH_TAC THEN
  MATCH_MP_TAC EXISTS_AND_CONG THEN X_GEN_TAC `inner:A` THEN DISCH_TAC THEN
  MATCH_MP_TAC EXISTS_AND_CONG THEN X_GEN_TAC `ival:A` THEN DISCH_TAC THEN
  MATCH_MP_TAC EXISTS_AND_CONG THEN X_GEN_TAC `eval:A` THEN DISCH_TAC THEN
  ABBREV_TAC
   `VV = (5 |-> (eval:A)) ((4 |-> (ival:A)) ((2 |-> (inner:A))
      ((1 |-> (pr:A)) ((3 |-> (ot:A)) ((0 |-> (u:A)) v)))))` THEN
  SUBGOAL_THEN `valuation D (VV:num->A)` ASSUME_TAC THENL
   [EXPAND_TAC "VV" THEN
    REPEAT(MATCH_MP_TAC VALUATION_VALMOD THEN CONJ_TAC THENL
            [ALL_TAC; FIRST_ASSUM ACCEPT_TAC]) THEN
    FIRST_ASSUM ACCEPT_TAC;
    ALL_TAC] THEN
  ASM_SIMP_TAC[HOLDS_AND; HOLDS_OPAIR_FORM] THEN
  EXPAND_TAC "VV" THEN REWRITE_TAC[VALMOD; ARITH_EQ]);;

let REPL_SV_WITNESS = prove
 (`!D (P:A->bool).
      (?d. d IN D) /\
      (!w1 w2. w1 IN D /\ w2 IN D /\ P w1 /\ P w2 ==> w1 = w2)
      ==> ?w. w IN D /\ (!w'. w' IN D /\ P w' ==> w' = w)`,
  REPEAT GEN_TAC THEN
  DISCH_THEN(CONJUNCTS_THEN2 (X_CHOOSE_TAC `d:A`) (LABEL_TAC "sv")) THEN
  ASM_CASES_TAC `?w:A. w IN D /\ P w` THENL
   [FIRST_X_ASSUM(X_CHOOSE_THEN `w:A` STRIP_ASSUME_TAC) THEN
    EXISTS_TAC `w:A` THEN ASM_REWRITE_TAC[] THEN
    X_GEN_TAC `w':A` THEN STRIP_TAC THEN
    USE_THEN "sv" MATCH_MP_TAC THEN ASM_REWRITE_TAC[];
    EXISTS_TAC `d:A` THEN ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[]]);;

let EBVSUBEQ_EXISTS = prove
 (`!D (E:A->A->bool) tab.
      model D E ZF_AX /\ tab IN D
      ==> ?s. s IN D /\
              (!z. z IN D
                   ==> (E z s <=>
                        ?u. u IN D /\ E u tab /\
                            ?pr. pr IN D /\ ?inner. inner IN D /\
                                 ?ival. ival IN D /\ ?eval. eval IN D /\
                                 eopair D E pr inner u /\
                                 eopair D E ival eval inner /\
                                 eopair D E pr eval z))`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `?v0:num->A. valuation D v0` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[VALUATION_EXISTS; MODEL_NONEMPTY]; ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`] ZF_REPLACEMENT) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(MP_TAC o SPECL
             [`projeq_form`; `0`; `3`; `v0:num->A`; `tab:A`]) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[ARITH_EQ] THEN
    X_GEN_TAC `u:A` THEN STRIP_TAC THEN
    MATCH_MP_TAC REPL_SV_WITNESS THEN CONJ_TAC THENL
     [ASM_MESON_TAC[]; ALL_TAC] THEN
    MAP_EVERY X_GEN_TAC [`w1:A`; `w2:A`] THEN STRIP_TAC THEN
    MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `v0:num->A`; `u:A`; `w1:A`]
      HOLDS_PROJEQ_FORM) THEN
    ASM_REWRITE_TAC[] THEN DISCH_THEN STRIP_ASSUME_TAC THEN
    MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `v0:num->A`; `u:A`; `w2:A`]
      HOLDS_PROJEQ_FORM) THEN
    ASM_REWRITE_TAC[] THEN DISCH_THEN STRIP_ASSUME_TAC THEN
    ASM_MESON_TAC[EOPAIR_INJ; EOPAIR_UNIQUE];
    ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `s:A`
             (CONJUNCTS_THEN2 ASSUME_TAC (LABEL_TAC "raw"))) THEN
  EXISTS_TAC `s:A` THEN CONJ_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  X_GEN_TAC `z:A` THEN DISCH_TAC THEN
  REMOVE_THEN "raw" (MP_TAC o SPEC `z:A`) THEN ASM_REWRITE_TAC[] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  EQ_TAC THENL
   [DISCH_THEN(X_CHOOSE_THEN `u:A` STRIP_ASSUME_TAC) THEN
    EXISTS_TAC `u:A` THEN ASM_REWRITE_TAC[] THEN
    UNDISCH_TAC
      `holds D (E:A->A->bool) ((3 |-> z) ((0 |-> u) v0)) projeq_form` THEN
      ASM_SIMP_TAC[HOLDS_PROJEQ_FORM];
    DISCH_THEN(X_CHOOSE_THEN `u:A` STRIP_ASSUME_TAC) THEN
    EXISTS_TAC `u:A` THEN ASM_REWRITE_TAC[] THEN
    ASM_SIMP_TAC[HOLDS_PROJEQ_FORM] THEN ASM_MESON_TAC[]]);;
let EBVSUBIN_EXISTS = prove
 (`!D (E:A->A->bool) tab.
      model D E ZF_AX /\ tab IN D
      ==> ?s. s IN D /\
              (!z. z IN D
                   ==> (E z s <=>
                        ?u. u IN D /\ E u tab /\
                            ?pr. pr IN D /\ ?inner. inner IN D /\
                                 ?ival. ival IN D /\ ?eval. eval IN D /\
                                 eopair D E pr inner u /\
                                 eopair D E ival eval inner /\
                                 eopair D E pr ival z))`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `?v0:num->A. valuation D v0` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[VALUATION_EXISTS; MODEL_NONEMPTY]; ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`] ZF_REPLACEMENT) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(MP_TAC o SPECL
             [`projin_form`; `0`; `3`; `v0:num->A`; `tab:A`]) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[ARITH_EQ] THEN
    X_GEN_TAC `u:A` THEN STRIP_TAC THEN
    MATCH_MP_TAC REPL_SV_WITNESS THEN CONJ_TAC THENL
     [ASM_MESON_TAC[]; ALL_TAC] THEN
    MAP_EVERY X_GEN_TAC [`w1:A`; `w2:A`] THEN STRIP_TAC THEN
    MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `v0:num->A`; `u:A`; `w1:A`]
      HOLDS_PROJIN_FORM) THEN
    ASM_REWRITE_TAC[] THEN DISCH_THEN STRIP_ASSUME_TAC THEN
    MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `v0:num->A`; `u:A`; `w2:A`]
      HOLDS_PROJIN_FORM) THEN
    ASM_REWRITE_TAC[] THEN DISCH_THEN STRIP_ASSUME_TAC THEN
    ASM_MESON_TAC[EOPAIR_INJ; EOPAIR_UNIQUE];
    ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `s:A`
             (CONJUNCTS_THEN2 ASSUME_TAC (LABEL_TAC "raw"))) THEN
  EXISTS_TAC `s:A` THEN CONJ_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  X_GEN_TAC `z:A` THEN DISCH_TAC THEN
  REMOVE_THEN "raw" (MP_TAC o SPEC `z:A`) THEN ASM_REWRITE_TAC[] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  EQ_TAC THENL
   [DISCH_THEN(X_CHOOSE_THEN `u:A` STRIP_ASSUME_TAC) THEN
    EXISTS_TAC `u:A` THEN ASM_REWRITE_TAC[] THEN
    UNDISCH_TAC
      `holds D (E:A->A->bool) ((3 |-> z) ((0 |-> u) v0)) projin_form` THEN
      ASM_SIMP_TAC[HOLDS_PROJIN_FORM];
    DISCH_THEN(X_CHOOSE_THEN `u:A` STRIP_ASSUME_TAC) THEN
    EXISTS_TAC `u:A` THEN ASM_REWRITE_TAC[] THEN
    ASM_SIMP_TAC[HOLDS_PROJIN_FORM] THEN ASM_MESON_TAC[]]);;

(* ===================================================================== *)
(* F4: the set-supremum / set-infimum object                             *)
(* formulas.  ebvin = elub(ebvinset), ebveq = meet(eglb SL, eglb SR); the *)
(* set-sup/inf are NOT object-atomic, so we build them here as object     *)
(* formulas over a set-slot iS, a carrier iB and an order-relation ileq   *)
(* (read via rel_form).  eubound/elbound = "iu bounds iS above/below";    *)
(* elub/eglb add the least/greatest clause (an unbounded !! over D, whose  *)
(* meta ARE all in D via [E/EL]BOUND_IN).  Bridges kept TOP-LEVEL.  These  *)
(* feed ebvin_form/ebveq_form next.                                        *)
(* Tactic notes: the bounded "!x in s" uses !!- (GSYM Forallmem_DEF folds  *)
(* the plain !! back) + HOLDS_FORALLMEM (keeps the body holds intact for a *)
(* body-lemma, no curry, no MESON poison); the unbounded least/greatest    *)
(* !! is unfolded by last(CONJUNCTS holds), its body rewritten by a        *)
(* body-lemma via SIMP_TAC (contextual: discharges a IN D from the binder),*)
(* then closed by ASM_MESON[E/EL]BOUND_IN.                                 *)
(* ===================================================================== *)

let EUBOUND_IN = prove
 (`!D (E:A->A->bool) p leq s u. eubound D E p leq s u ==> u IN D`,
  REWRITE_TAC[eubound] THEN MESON_TAC[]);;

let eubound_form = new_definition
 `eubound_form iB ileq iS iu =
    (iu %% iB) &&
    !! (MAX iB (MAX ileq (MAX iS iu)) + 1)
       ((MAX iB (MAX ileq (MAX iS iu)) + 1) %% iS -->
        rel_form ileq (MAX iB (MAX ileq (MAX iS iu)) + 1) iu)`;;

let HOLDS_EUBOUND_FORM = prove
 (`!D (E:A->A->bool) v iB ileq iS iu.
      model D E ZF_AX /\ valuation D v
      ==> (holds D E v (eubound_form iB ileq iS iu) <=>
           eubound D E (v iB) (v ileq) (v iS) (v iu))`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `!x. (v:num->A) x IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[valuation]; ALL_TAC] THEN
  REWRITE_TAC[eubound_form] THEN
  ABBREV_TAC `ix = MAX iB (MAX ileq (MAX iS iu)) + 1` THEN
  SUBGOAL_THEN `~(ix:num = iB) /\ ~(ix = ileq) /\ ~(ix = iS) /\ ~(ix = iu)`
  STRIP_ASSUME_TAC THENL [EXPAND_TAC "ix" THEN ARITH_TAC; ALL_TAC] THEN
  REWRITE_TAC[GSYM Forallmem_DEF] THEN
  SUBGOAL_THEN
   `!a:A. a IN D
      ==> (holds D E ((ix |-> a) v) (rel_form ileq ix iu) <=>
           erel D E (v ileq) a (v iu))`
  (LABEL_TAC "body") THENL
   [REPEAT STRIP_TAC THEN
    SUBGOAL_THEN `valuation D ((ix |-> (a:A)) v)` ASSUME_TAC THENL
     [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
    ASM_SIMP_TAC[HOLDS_REL_FORM] THEN
    ASM_SIMP_TAC[VALMOD; ARITH_EQ]; ALL_TAC] THEN
  REWRITE_TAC[HOLDS_AND] THEN
  ASM_SIMP_TAC[HOLDS_FORALLMEM] THEN
  REWRITE_TAC[holds] THEN
  REWRITE_TAC[eubound] THEN
  REMOVE_THEN "body" (fun th -> REWRITE_TAC[th]) THEN
  ASM_MESON_TAC[]);;

let elub_form = new_definition
 `elub_form iB ileq iS iu =
    eubound_form iB ileq iS iu &&
    !! (MAX iB (MAX ileq (MAX iS iu)) + 1)
       (eubound_form iB ileq iS (MAX iB (MAX ileq (MAX iS iu)) + 1) -->
        rel_form ileq iu (MAX iB (MAX ileq (MAX iS iu)) + 1))`;;

let HOLDS_ELUB_FORM = prove
 (`!D (E:A->A->bool) v iB ileq iS iu.
      model D E ZF_AX /\ valuation D v
      ==> (holds D E v (elub_form iB ileq iS iu) <=>
           elub D E (v iB) (v ileq) (v iS) (v iu))`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `!x. (v:num->A) x IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[valuation]; ALL_TAC] THEN
  REWRITE_TAC[elub_form] THEN
  ABBREV_TAC `iw = MAX iB (MAX ileq (MAX iS iu)) + 1` THEN
  SUBGOAL_THEN `~(iw:num = iB) /\ ~(iw = ileq) /\ ~(iw = iS) /\ ~(iw = iu)`
  STRIP_ASSUME_TAC THENL [EXPAND_TAC "iw" THEN ARITH_TAC; ALL_TAC] THEN
  SUBGOAL_THEN
   `!b:A. b IN D
      ==> (holds D E ((iw |-> b) v)
             (eubound_form iB ileq iS iw --> rel_form ileq iu iw) <=>
           (eubound D E (v iB) (v ileq) (v iS) b ==>
            erel D E (v ileq) (v iu) b))`
  (LABEL_TAC "body") THENL
   [REPEAT STRIP_TAC THEN
    SUBGOAL_THEN `valuation D ((iw |-> (b:A)) v)` ASSUME_TAC THENL
     [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
    REWRITE_TAC[holds] THEN
    ASM_SIMP_TAC[HOLDS_EUBOUND_FORM; HOLDS_REL_FORM] THEN
    ASM_SIMP_TAC[VALMOD; ARITH_EQ]; ALL_TAC] THEN
  REWRITE_TAC[HOLDS_AND] THEN
  ASM_SIMP_TAC[HOLDS_EUBOUND_FORM] THEN
  REWRITE_TAC[last(CONJUNCTS holds)] THEN
  REWRITE_TAC[elub] THEN
  REMOVE_THEN "body" (fun th -> SIMP_TAC[th]) THEN
  MATCH_MP_TAC(TAUT `(q <=> q') ==> (p /\ q <=> p /\ q')`) THEN
  ASM_MESON_TAC[EUBOUND_IN]);;

let ELBOUND_IN = prove
 (`!D (E:A->A->bool) p leq s u. elbound D E p leq s u ==> u IN D`,
  REWRITE_TAC[elbound] THEN MESON_TAC[]);;

let elbound_form = new_definition
 `elbound_form iB ileq iS iu =
    (iu %% iB) &&
    !! (MAX iB (MAX ileq (MAX iS iu)) + 1)
       ((MAX iB (MAX ileq (MAX iS iu)) + 1) %% iS -->
        rel_form ileq iu (MAX iB (MAX ileq (MAX iS iu)) + 1))`;;
let HOLDS_ELBOUND_FORM = prove
 (`!D (E:A->A->bool) v iB ileq iS iu.
      model D E ZF_AX /\ valuation D v
      ==> (holds D E v (elbound_form iB ileq iS iu) <=>
           elbound D E (v iB) (v ileq) (v iS) (v iu))`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `!x. (v:num->A) x IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[valuation]; ALL_TAC] THEN
  REWRITE_TAC[elbound_form] THEN
  ABBREV_TAC `ix = MAX iB (MAX ileq (MAX iS iu)) + 1` THEN
  SUBGOAL_THEN `~(ix:num = iB) /\ ~(ix = ileq) /\ ~(ix = iS) /\ ~(ix = iu)`
  STRIP_ASSUME_TAC THENL [EXPAND_TAC "ix" THEN ARITH_TAC; ALL_TAC] THEN
  REWRITE_TAC[GSYM Forallmem_DEF] THEN
  SUBGOAL_THEN
   `!a:A. a IN D
      ==> (holds D E ((ix |-> a) v) (rel_form ileq iu ix) <=>
           erel D E (v ileq) (v iu) a)`
  (LABEL_TAC "body") THENL
   [REPEAT STRIP_TAC THEN
    SUBGOAL_THEN `valuation D ((ix |-> (a:A)) v)` ASSUME_TAC THENL
     [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
    ASM_SIMP_TAC[HOLDS_REL_FORM] THEN
    ASM_SIMP_TAC[VALMOD; ARITH_EQ]; ALL_TAC] THEN
  REWRITE_TAC[HOLDS_AND] THEN
  ASM_SIMP_TAC[HOLDS_FORALLMEM] THEN
  REWRITE_TAC[holds] THEN
  REWRITE_TAC[elbound] THEN
  REMOVE_THEN "body" (fun th -> REWRITE_TAC[th]) THEN
  ASM_MESON_TAC[]);;

let eglb_form = new_definition
 `eglb_form iB ileq iS iu =
    elbound_form iB ileq iS iu &&
    !! (MAX iB (MAX ileq (MAX iS iu)) + 1)
       (elbound_form iB ileq iS (MAX iB (MAX ileq (MAX iS iu)) + 1) -->
        rel_form ileq (MAX iB (MAX ileq (MAX iS iu)) + 1) iu)`;;
let HOLDS_EGLB_FORM = prove
 (`!D (E:A->A->bool) v iB ileq iS iu.
      model D E ZF_AX /\ valuation D v
      ==> (holds D E v (eglb_form iB ileq iS iu) <=>
           eglb D E (v iB) (v ileq) (v iS) (v iu))`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `!x. (v:num->A) x IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[valuation]; ALL_TAC] THEN
  REWRITE_TAC[eglb_form] THEN
  ABBREV_TAC `iw = MAX iB (MAX ileq (MAX iS iu)) + 1` THEN
  SUBGOAL_THEN `~(iw:num = iB) /\ ~(iw = ileq) /\ ~(iw = iS) /\ ~(iw = iu)`
  STRIP_ASSUME_TAC THENL [EXPAND_TAC "iw" THEN ARITH_TAC; ALL_TAC] THEN
  SUBGOAL_THEN
   `!b:A. b IN D
      ==> (holds D E ((iw |-> b) v)
             (elbound_form iB ileq iS iw --> rel_form ileq iw iu) <=>
           (elbound D E (v iB) (v ileq) (v iS) b ==>
            erel D E (v ileq) b (v iu)))`
  (LABEL_TAC "body") THENL
   [REPEAT STRIP_TAC THEN
    SUBGOAL_THEN `valuation D ((iw |-> (b:A)) v)` ASSUME_TAC THENL
     [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
    REWRITE_TAC[holds] THEN
    ASM_SIMP_TAC[HOLDS_ELBOUND_FORM; HOLDS_REL_FORM] THEN
    ASM_SIMP_TAC[VALMOD; ARITH_EQ]; ALL_TAC] THEN
  REWRITE_TAC[HOLDS_AND] THEN
  ASM_SIMP_TAC[HOLDS_ELBOUND_FORM] THEN
  REWRITE_TAC[last(CONJUNCTS holds)] THEN
  REWRITE_TAC[eglb] THEN
  REMOVE_THEN "body" (fun th -> SIMP_TAC[th]) THEN
  MATCH_MP_TAC(TAUT `(q <=> q') ==> (p /\ q <=> p /\ q')`) THEN
  ASM_MESON_TAC[ELBOUND_IN]);;

(* ===================================================================== *)
(* F4: the Boolean IN-value [[u IN v]] as an                              *)
(* OBJECT formula.  ebvin t v u z <=> ?S. ebvinset t v u S /\ elub B leq   *)
(* S z.  ebvin_form iz it iv iu ileq iB existentially introduces the       *)
(* image-set slot iS, says iS = ebvinset via a bounded !! over the         *)
(* combiner bvcomb_form (IBODY bridges that to ebvinset), and pins iz =    *)
(* elub iS via elub_form (layer 1).  EBVINSET_IN (S IN D) bridges the      *)
(* unbounded ?S of ebvin to the ?a IN D of holds's ??.  IBODY/MBODY are    *)
(* the per-element and per-witness bodies; EXISTS_AND_CONG aligns the     *)
(* existentials.                                                         *)
(* ===================================================================== *)

let EBVINSET_IN = prove
 (`!D (E:A->A->bool) B leq t v u S. ebvinset D E B leq t v u S ==> S IN D`,
  REWRITE_TAC[ebvinset] THEN MESON_TAC[]);;

let IBODY = prove
 (`!D (E:A->A->bool) v iS ic it iv iu ileq iB a.
      model D E ZF_AX /\ valuation D v /\ a IN D /\
      ~(ic = iS) /\ ~(ic = it) /\ ~(ic = iv) /\ ~(ic = iu) /\ ~(ic = ileq) /\
      ~(ic = iB) /\ ~(iS = it) /\ ~(iS = iv) /\ ~(iS = iu) /\ ~(iS = ileq) /\
      ~(iS = iB)
      ==> (holds D E ((iS |-> a) v)
             (!! ic (ic %% iS <-> bvcomb_form ic iv it iu ileq iB)) <=>
           ebvinset D E (v iB) (v ileq) (v it) (v iv) (v iu) a)`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `!x. (v:num->A) x IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[valuation]; ALL_TAC] THEN
  SUBGOAL_THEN `valuation D ((iS |-> (a:A)) v)` ASSUME_TAC THENL
   [ASM_SIMP_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
  SUBGOAL_THEN
   `!c:A. c IN D
      ==> (holds D E ((ic |-> c) ((iS |-> a) v))
             (ic %% iS <-> bvcomb_form ic iv it iu ileq iB) <=>
           (E c a <=> bvcomb D E (v iB) (v ileq) (v it) (v iv) (v iu) c))`
  (LABEL_TAC "cbody") THENL
   [REPEAT STRIP_TAC THEN
    SUBGOAL_THEN `valuation D ((ic |-> (c:A)) ((iS |-> (a:A)) v))`
      ASSUME_TAC THENL
      [ASM_SIMP_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
    REWRITE_TAC[HOLDS_IFF] THEN
    REWRITE_TAC[holds] THEN
    ASM_SIMP_TAC[HOLDS_BVCOMB_FORM] THEN
    ASM_SIMP_TAC[VALMOD; ARITH_EQ]; ALL_TAC] THEN
  REWRITE_TAC[last(CONJUNCTS holds)] THEN
  REWRITE_TAC[ebvinset] THEN
  REMOVE_THEN "cbody" (fun th -> SIMP_TAC[th]) THEN
  ASM_REWRITE_TAC[]);;

let MBODY = prove
 (`!D (E:A->A->bool) v iS ic iz it iv iu ileq iB a.
      model D E ZF_AX /\ valuation D v /\ a IN D /\
      ~(ic = iS) /\ ~(ic = it) /\ ~(ic = iv) /\ ~(ic = iu) /\ ~(ic = ileq) /\
      ~(ic = iB) /\ ~(iS = it) /\ ~(iS = iv) /\ ~(iS = iu) /\ ~(iS = ileq) /\
      ~(iS = iB) /\ ~(iS = iz)
      ==> (holds D E ((iS |-> a) v)
             ((!! ic (ic %% iS <-> bvcomb_form ic iv it iu ileq iB)) &&
              elub_form iB ileq iS iz) <=>
           ebvinset D E (v iB) (v ileq) (v it) (v iv) (v iu) a /\
           elub D E (v iB) (v ileq) a (v iz))`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `!x. (v:num->A) x IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[valuation]; ALL_TAC] THEN
  SUBGOAL_THEN `valuation D ((iS |-> (a:A)) v)` ASSUME_TAC THENL
   [ASM_SIMP_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
  REWRITE_TAC[HOLDS_AND] THEN
  MATCH_MP_TAC(TAUT
               `(p <=> p') /\ (q <=> q') ==> ((p /\ q) <=> (p' /\ q'))`) THEN
  CONJ_TAC THENL
   [ASM_SIMP_TAC[IBODY];
    ASM_SIMP_TAC[HOLDS_ELUB_FORM] THEN ASM_SIMP_TAC[VALMOD; ARITH_EQ]]);;

let ebvin_form = new_definition
 `ebvin_form iz it iv iu ileq iB =
    ?? (MAX iz (MAX it (MAX iv (MAX iu (MAX ileq iB)))) + 1)
       ((!! (MAX iz (MAX it (MAX iv (MAX iu (MAX ileq iB)))) + 2)
            ((MAX iz (MAX it (MAX iv (MAX iu (MAX ileq iB)))) + 2) %%
             (MAX iz (MAX it (MAX iv (MAX iu (MAX ileq iB)))) + 1) <->
             bvcomb_form (MAX iz (MAX it (MAX iv (MAX iu (MAX ileq iB)))) + 2)
                         iv it iu ileq iB)) &&
        elub_form iB ileq
          (MAX iz (MAX it (MAX iv (MAX iu (MAX ileq iB)))) + 1) iz)`;;

let HOLDS_EBVIN_FORM = prove
 (`!D (E:A->A->bool) v iz it iv iu ileq iB.
      model D E ZF_AX /\ valuation D v
      ==> (holds D E v (ebvin_form iz it iv iu ileq iB) <=>
           ebvin D E (v iB) (v ileq) (v it) (v iv) (v iu) (v iz))`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `!x. (v:num->A) x IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[valuation]; ALL_TAC] THEN
  REWRITE_TAC[ebvin_form] THEN
  ABBREV_TAC `iS = MAX iz (MAX it (MAX iv (MAX iu (MAX ileq iB)))) + 1` THEN
  ABBREV_TAC `ic = MAX iz (MAX it (MAX iv (MAX iu (MAX ileq iB)))) + 2` THEN
  SUBGOAL_THEN
   `~((ic:num) = iS) /\ ~(ic = it) /\ ~(ic = iv) /\ ~(ic = iu) /\
    ~(ic = ileq) /\
    ~(ic = iB) /\ ~((iS:num) = it) /\ ~(iS = iv) /\ ~(iS = iu) /\
      ~(iS = ileq) /\
    ~(iS = iB) /\ ~(iS = iz)`
  STRIP_ASSUME_TAC THENL
   [MAP_EVERY EXPAND_TAC ["iS"; "ic"] THEN ARITH_TAC; ALL_TAC] THEN
  REWRITE_TAC[HOLDS_EX] THEN
  SUBGOAL_THEN
   `(?a:A. a IN D /\
           holds D E ((iS |-> a) v)
             ((!! ic (ic %% iS <-> bvcomb_form ic iv it iu ileq iB)) &&
              elub_form iB ileq iS iz)) <=>
    (?a:A. a IN D /\
           (ebvinset D E (v iB) (v ileq) (v it) (v iv) (v iu) a /\
            elub D E (v iB) (v ileq) a (v iz)))`
  SUBST1_TAC THENL
   [MATCH_MP_TAC EXISTS_AND_CONG THEN X_GEN_TAC `a:A` THEN DISCH_TAC THEN
    ASM_SIMP_TAC[MBODY]; ALL_TAC] THEN
  REWRITE_TAC[ebvin] THEN
  ASM_MESON_TAC[EBVINSET_IN]);;

(* ===================================================================== *)
(* F4: the Boolean =-value [[u = v]] as an                                *)
(* OBJECT formula.  ebveq s u v z = meet(eglb(bveqcombset s u v),          *)
(* eglb(bveqcombset s v u)).  bvhalf_form iz is ia ib ileq iB object-      *)
(* expresses ONE half "iz = eglb(bveqcombset s ia ib)" (a single ??S, twin *)
(* of ebvin_form using eglb_form + bveqcomb_form; JBODY/KBODY are its per- *)
(* element / per-witness bodies, BVEQCOMBSET_IN bridges the ?S).  Then     *)
(* ebveq_form = ??igL ??igR (bvhalf_form igL s u v && bvhalf_form igR s v u *)
(* && bmeet_form igL igR iz); nested EXISTS_AND_CONG aligns the 2        *)
(* existentials,                                                         *)
(* EGLB_IN regroups to ebveq's ?SL SR gL gR.                               *)
(* ===================================================================== *)

let BVEQCOMBSET_IN = prove
 (`!D (E:A->A->bool) B leq s u v S. bveqcombset D E B leq s u v S ==> S IN D`,
  REWRITE_TAC[bveqcombset] THEN MESON_TAC[]);;

let JBODY = prove
 (`!D (E:A->A->bool) v iS ic ia ib is ileq iB a.
      model D E ZF_AX /\ valuation D v /\ a IN D /\
      ~(ic = iS) /\ ~(ic = ia) /\ ~(ic = ib) /\ ~(ic = is) /\ ~(ic = ileq) /\
      ~(ic = iB) /\ ~(iS = ia) /\ ~(iS = ib) /\ ~(iS = is) /\ ~(iS = ileq) /\
      ~(iS = iB)
      ==> (holds D E ((iS |-> a) v)
             (!! ic (ic %% iS <-> bveqcomb_form ic ia ib is ileq iB)) <=>
           bveqcombset D E (v iB) (v ileq) (v is) (v ia) (v ib) a)`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `!x. (v:num->A) x IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[valuation]; ALL_TAC] THEN
  SUBGOAL_THEN `valuation D ((iS |-> (a:A)) v)` ASSUME_TAC THENL
   [ASM_SIMP_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
  SUBGOAL_THEN
   `!c:A. c IN D
      ==> (holds D E ((ic |-> c) ((iS |-> a) v))
             (ic %% iS <-> bveqcomb_form ic ia ib is ileq iB) <=>
           (E c a <=> bveqcomb D E (v iB) (v ileq) (v is) (v ia) (v ib) c))`
  (LABEL_TAC "cbody") THENL
   [REPEAT STRIP_TAC THEN
    SUBGOAL_THEN `valuation D ((ic |-> (c:A)) ((iS |-> (a:A)) v))`
      ASSUME_TAC THENL
      [ASM_SIMP_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
    REWRITE_TAC[HOLDS_IFF] THEN REWRITE_TAC[holds] THEN
    ASM_SIMP_TAC[HOLDS_BVEQCOMB_FORM] THEN
    ASM_SIMP_TAC[VALMOD; ARITH_EQ]; ALL_TAC] THEN
  REWRITE_TAC[last(CONJUNCTS holds)] THEN
  REWRITE_TAC[bveqcombset] THEN
  REMOVE_THEN "cbody" (fun th -> SIMP_TAC[th]) THEN
  ASM_REWRITE_TAC[]);;
let KBODY = prove
 (`!D (E:A->A->bool) v iS ic iz is ia ib ileq iB a.
      model D E ZF_AX /\ valuation D v /\ a IN D /\
      ~(ic = iS) /\ ~(ic = ia) /\ ~(ic = ib) /\ ~(ic = is) /\ ~(ic = ileq) /\
      ~(ic = iB) /\ ~(iS = ia) /\ ~(iS = ib) /\ ~(iS = is) /\ ~(iS = ileq) /\
      ~(iS = iB) /\ ~(iS = iz)
      ==> (holds D E ((iS |-> a) v)
             ((!! ic (ic %% iS <-> bveqcomb_form ic ia ib is ileq iB)) &&
              eglb_form iB ileq iS iz) <=>
           bveqcombset D E (v iB) (v ileq) (v is) (v ia) (v ib) a /\
           eglb D E (v iB) (v ileq) a (v iz))`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `!x. (v:num->A) x IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[valuation]; ALL_TAC] THEN
  SUBGOAL_THEN `valuation D ((iS |-> (a:A)) v)` ASSUME_TAC THENL
   [ASM_SIMP_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
  REWRITE_TAC[HOLDS_AND] THEN
  MATCH_MP_TAC(TAUT
               `(p <=> p') /\ (q <=> q') ==> ((p /\ q) <=> (p' /\ q'))`) THEN
  CONJ_TAC THENL
   [ASM_SIMP_TAC[JBODY];
    ASM_SIMP_TAC[HOLDS_EGLB_FORM] THEN ASM_SIMP_TAC[VALMOD; ARITH_EQ]]);;
let bvhalf_form = new_definition
 `bvhalf_form iz is ia ib ileq iB =
    ?? (MAX iz (MAX is (MAX ia (MAX ib (MAX ileq iB)))) + 1)
       ((!! (MAX iz (MAX is (MAX ia (MAX ib (MAX ileq iB)))) + 2)
            ((MAX iz (MAX is (MAX ia (MAX ib (MAX ileq iB)))) + 2) %%
             (MAX iz (MAX is (MAX ia (MAX ib (MAX ileq iB)))) + 1) <->
             bveqcomb_form
               (MAX iz (MAX is (MAX ia (MAX ib (MAX ileq iB)))) + 2)
               ia ib is ileq iB)) &&
        eglb_form iB ileq
          (MAX iz (MAX is (MAX ia (MAX ib (MAX ileq iB)))) + 1) iz)`;;
let HOLDS_BVHALF_FORM = prove
 (`!D (E:A->A->bool) v iz is ia ib ileq iB.
      model D E ZF_AX /\ valuation D v
      ==> (holds D E v (bvhalf_form iz is ia ib ileq iB) <=>
           (?S. bveqcombset D E (v iB) (v ileq) (v is) (v ia) (v ib) S /\
                eglb D E (v iB) (v ileq) S (v iz)))`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `!x. (v:num->A) x IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[valuation]; ALL_TAC] THEN
  REWRITE_TAC[bvhalf_form] THEN
  ABBREV_TAC `iS = MAX iz (MAX is (MAX ia (MAX ib (MAX ileq iB)))) + 1` THEN
  ABBREV_TAC `ic = MAX iz (MAX is (MAX ia (MAX ib (MAX ileq iB)))) + 2` THEN
  SUBGOAL_THEN
   `~((ic:num) = iS) /\ ~(ic = ia) /\ ~(ic = ib) /\ ~(ic = is) /\
    ~(ic = ileq) /\
    ~(ic = iB) /\ ~((iS:num) = ia) /\ ~(iS = ib) /\ ~(iS = is) /\
      ~(iS = ileq) /\
    ~(iS = iB) /\ ~(iS = iz)`
  STRIP_ASSUME_TAC THENL
   [MAP_EVERY EXPAND_TAC ["iS"; "ic"] THEN ARITH_TAC; ALL_TAC] THEN
  REWRITE_TAC[HOLDS_EX] THEN
  SUBGOAL_THEN
   `(?a:A. a IN D /\
           holds D E ((iS |-> a) v)
             ((!! ic (ic %% iS <-> bveqcomb_form ic ia ib is ileq iB)) &&
              eglb_form iB ileq iS iz)) <=>
    (?a:A. a IN D /\
           (bveqcombset D E (v iB) (v ileq) (v is) (v ia) (v ib) a /\
            eglb D E (v iB) (v ileq) a (v iz)))`
  SUBST1_TAC THENL
   [MATCH_MP_TAC EXISTS_AND_CONG THEN X_GEN_TAC `a:A` THEN DISCH_TAC THEN
    ASM_SIMP_TAC[KBODY]; ALL_TAC] THEN
  ASM_MESON_TAC[BVEQCOMBSET_IN]);;

let ebveq_form = new_definition
 `ebveq_form iz is iu iv ileq iB =
    ?? (MAX iz (MAX is (MAX iu (MAX iv (MAX ileq iB)))) + 1)
       (?? (MAX iz (MAX is (MAX iu (MAX iv (MAX ileq iB)))) + 2)
          (bvhalf_form (MAX iz (MAX is (MAX iu (MAX iv (MAX ileq iB)))) + 1)
                       is iu iv ileq iB &&
           bvhalf_form (MAX iz (MAX is (MAX iu (MAX iv (MAX ileq iB)))) + 2)
                       is iv iu ileq iB &&
           bmeet_form ileq iB
                      (MAX iz (MAX is (MAX iu (MAX iv (MAX ileq iB)))) + 1)
                      (MAX iz (MAX is
                               (MAX iu (MAX iv (MAX ileq iB)))) + 2) iz))`;;
let HOLDS_EBVEQ_FORM = prove
 (`!D (E:A->A->bool) v iz is iu iv ileq iB.
      model D E ZF_AX /\ valuation D v
      ==> (holds D E v (ebveq_form iz is iu iv ileq iB) <=>
           ebveq D E (v iB) (v ileq) (v is) (v iu) (v iv) (v iz))`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `!x. (v:num->A) x IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[valuation]; ALL_TAC] THEN
  REWRITE_TAC[ebveq_form] THEN
  ABBREV_TAC `igL = MAX iz (MAX is (MAX iu (MAX iv (MAX ileq iB)))) + 1` THEN
  ABBREV_TAC `igR = MAX iz (MAX is (MAX iu (MAX iv (MAX ileq iB)))) + 2` THEN
  SUBGOAL_THEN
   `~((igL:num) = iz) /\ ~(igL = is) /\ ~(igL = iu) /\ ~(igL = iv) /\
    ~(igL = ileq) /\ ~(igL = iB) /\ ~((igR:num) = iz) /\ ~(igR = is) /\
    ~(igR = iu) /\ ~(igR = iv) /\ ~(igR = ileq) /\ ~(igR = iB) /\ ~(igR = igL)`
  STRIP_ASSUME_TAC THENL
   [MAP_EVERY EXPAND_TAC ["igL"; "igR"] THEN ARITH_TAC; ALL_TAC] THEN
  REWRITE_TAC[HOLDS_EX] THEN
  SUBGOAL_THEN
   `(?gL:A. gL IN D /\ (?gR:A. gR IN D /\
        holds D E ((igR |-> gR) ((igL |-> gL) v))
          (bvhalf_form igL is iu iv ileq iB &&
           bvhalf_form igR is iv iu ileq iB &&
           bmeet_form ileq iB igL igR iz))) <=>
    (?gL:A. gL IN D /\ (?gR:A. gR IN D /\
        (((?SL. bveqcombset D E (v iB) (v ileq) (v is) (v iu) (v iv) SL /\
                eglb D E (v iB) (v ileq) SL gL)) /\
         ((?SR. bveqcombset D E (v iB) (v ileq) (v is) (v iv) (v iu) SR /\
                eglb D E (v iB) (v ileq) SR gR)) /\
         emeet D E (v iB) (v ileq) gL gR (v iz))))`
  SUBST1_TAC THENL
   [MATCH_MP_TAC EXISTS_AND_CONG THEN X_GEN_TAC `gL:A` THEN DISCH_TAC THEN
    MATCH_MP_TAC EXISTS_AND_CONG THEN X_GEN_TAC `gR:A` THEN DISCH_TAC THEN
    SUBGOAL_THEN `valuation D ((igR |-> (gR:A)) ((igL |-> (gL:A)) v))`
    ASSUME_TAC THENL
     [REPEAT(MATCH_MP_TAC VALUATION_VALMOD THEN CONJ_TAC THENL
              [ALL_TAC; FIRST_ASSUM ACCEPT_TAC]) THEN FIRST_ASSUM ACCEPT_TAC;
      ALL_TAC] THEN
    REWRITE_TAC[HOLDS_AND] THEN
    MATCH_MP_TAC(TAUT
     `(a <=> a') /\ (b <=> b') /\ (c <=> c')
      ==> ((a /\ b /\ c) <=> (a' /\ b' /\ c'))`) THEN
    REPEAT CONJ_TAC THENL
     [ASM_SIMP_TAC[HOLDS_BVHALF_FORM] THEN ASM_SIMP_TAC[VALMOD; ARITH_EQ];
      ASM_SIMP_TAC[HOLDS_BVHALF_FORM] THEN ASM_SIMP_TAC[VALMOD; ARITH_EQ];
      ASM_SIMP_TAC[HOLDS_BMEET_FORM] THEN ASM_SIMP_TAC[VALMOD; ARITH_EQ]];
    ALL_TAC] THEN
  REWRITE_TAC[ebveq] THEN
  ASM_MESON_TAC[EGLB_IN]);;

(* ===================================================================== *)
(* F4: the per-rank-code ENTRY object formula.                            *)
(* entry_form is the replacement relation pr |-> <pr,<ival,eval>> used to  *)
(* build one rank-code's entry-set: slot 0 = pr (input), slot 1 = e        *)
(* (output), params slots 2=B 3=leq 4=RG(rank-graph) 5=SEQ_acc 6=SIN_acc   *)
(* 7=rc; existentials 8..14 = u,v,ru,rv,ival,eval,ivev.  It decomposes     *)
(* pr=<u,v>, looks up the ranks via apply_form on the rank-graph, FILTERS   *)
(* by <ru,rv>=rc (opair_form .. 7), computes ival=[[u IN v]] via ebvin_form *)
(* against SEQ_acc and eval=[[u=v]] via ebveq_form against SIN_acc, and     *)
(* repacks <pr,<ival,eval>>.  KEY: since each HOLDS_*_FORM fixes its        *)
(* subformula's meaning to its explicit arg slots only (internal temps      *)
(* abstracted), the eight conjuncts compose with NO slot-clash worry.       *)
(* (FV_ENTRY_FORM deferred: ARITH_TAC on the 15-numeral set is too slow.)   *)
(* ===================================================================== *)

let entry_form = new_definition
 `entry_form =
    ?? 8 (?? 9 (?? 10 (?? 11 (?? 12 (?? 13 (?? 14 (
       opair_form 8 9 0 &&
       apply_form 4 8 10 &&
       apply_form 4 9 11 &&
       opair_form 10 11 7 &&
       ebvin_form 12 5 9 8 3 2 &&
       ebveq_form 13 6 8 9 3 2 &&
       opair_form 12 13 14 &&
       opair_form 0 14 1)))))))`;;
let HOLDS_ENTRY_FORM = prove
 (`!D (E:A->A->bool) v.
      model D E ZF_AX /\ valuation D v
      ==> (holds D E v entry_form <=>
           ?uu. uu IN D /\ ?vv. vv IN D /\ ?ru. ru IN D /\ ?rv. rv IN D /\
                ?iva. iva IN D /\ ?eva. eva IN D /\ ?ive. ive IN D /\
                eopair D E uu vv (v 0) /\
                eapply D E (v 4) uu ru /\ eapply D E (v 4) vv rv /\
                eopair D E ru rv (v 7) /\
                ebvin D E (v 2) (v 3) (v 5) vv uu iva /\
                ebveq D E (v 2) (v 3) (v 6) uu vv eva /\
                eopair D E iva eva ive /\
                eopair D E (v 0) ive (v 1))`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `!x. (v:num->A) x IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[valuation]; ALL_TAC] THEN
  REWRITE_TAC[entry_form; HOLDS_EX] THEN
  MATCH_MP_TAC EXISTS_AND_CONG THEN X_GEN_TAC `uu:A` THEN DISCH_TAC THEN
  MATCH_MP_TAC EXISTS_AND_CONG THEN X_GEN_TAC `vv:A` THEN DISCH_TAC THEN
  MATCH_MP_TAC EXISTS_AND_CONG THEN X_GEN_TAC `ru:A` THEN DISCH_TAC THEN
  MATCH_MP_TAC EXISTS_AND_CONG THEN X_GEN_TAC `rv:A` THEN DISCH_TAC THEN
  MATCH_MP_TAC EXISTS_AND_CONG THEN X_GEN_TAC `iva:A` THEN DISCH_TAC THEN
  MATCH_MP_TAC EXISTS_AND_CONG THEN X_GEN_TAC `eva:A` THEN DISCH_TAC THEN
  MATCH_MP_TAC EXISTS_AND_CONG THEN X_GEN_TAC `ive:A` THEN DISCH_TAC THEN
  ABBREV_TAC
   `VV = (14 |-> (ive:A)) ((13 |-> eva) ((12 |-> iva) ((11 |-> rv)
      ((10 |-> ru) ((9 |-> vv) ((8 |-> (uu:A)) v))))))` THEN
  SUBGOAL_THEN `valuation D (VV:num->A)` ASSUME_TAC THENL
   [EXPAND_TAC "VV" THEN
    REPEAT(MATCH_MP_TAC VALUATION_VALMOD THEN CONJ_TAC THENL
            [ALL_TAC; FIRST_ASSUM ACCEPT_TAC]) THEN FIRST_ASSUM ACCEPT_TAC;
    ALL_TAC] THEN
  REWRITE_TAC[HOLDS_AND] THEN
  ASM_SIMP_TAC[HOLDS_OPAIR_FORM; HOLDS_APPLY_FORM; HOLDS_EBVIN_FORM;
               HOLDS_EBVEQ_FORM] THEN
  EXPAND_TAC "VV" THEN REWRITE_TAC[VALMOD; ARITH_EQ]);;

(* ===================================================================== *)
(* F4: the rank-code entry-SET exists.                                    *)
(* HOLDS_ENTRY_CONV bridges holds((1|->e)((0|->pr)v0)) entry_form to a     *)
(* clean entry-relation (params B/leq/RG/SEQ_acc/SIN_acc/rc read off v0).  *)
(* ENTRY_SV is single-valuedness by an EXPLICIT uniqueness chain           *)
(* (EOPAIR_INJ, EAPPLY_UNIQUE x2, EBVIN_UNIQUE, EBVEQ_UNIQUE, EOPAIR_UNIQUE *)
(* x2) -- NOT ASM_MESON, which blows up on the multi-premise *_UNIQUE       *)
(* lemmas.  EBVATTSTEP_ENTRY_EXISTS: for any params (w-pair-set c, rank-    *)
(* graph RG functional, sub-tables SEQ_acc/SIN_acc, rank-code rc all in D) *)
(* the set y = { <pr,<[[u IN v]],[[u=v]]>> : <u,v> in c, rankcode = rc }    *)
(* exists in D, by ZF_REPLACEMENT along entry_form (REPL_SV_WITNESS+ENTRY_SV*)
(* for single-valuedness, HOLDS_ENTRY_CONV for the membership char).       *)
(* ===================================================================== *)

(* Object-language characterization of entry_form. *)
let HOLDS_ENTRY_CONV = prove
 (`!D (E:A->A->bool) B leq RG SEQ_acc SIN_acc rc v0 ee pr.
      model D E ZF_AX /\ valuation D v0 /\
      v0 2 = B /\ v0 3 = leq /\ v0 4 = RG /\ v0 5 = SEQ_acc /\
        v0 6 = SIN_acc /\
      v0 7 = rc /\ ee IN D /\ pr IN D
      ==> (holds D E ((1 |-> ee) ((0 |-> pr) v0)) entry_form <=>
           ?uu vv ru rv iva eva ive.
              uu IN D /\ vv IN D /\ ru IN D /\ rv IN D /\
                iva IN D /\ eva IN D /\
              ive IN D /\ eopair D E uu vv pr /\ eapply D E RG uu ru /\
              eapply D E RG vv rv /\ eopair D E ru rv rc /\
              ebvin D E B leq SEQ_acc vv uu iva /\
              ebveq D E B leq SIN_acc uu vv eva /\
              eopair D E iva eva ive /\ eopair D E pr ive ee)`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `valuation D ((1 |-> (ee:A)) ((0 |-> (pr:A)) v0))`
    ASSUME_TAC THENL
   [MATCH_MP_TAC VALUATION_VALMOD THEN CONJ_TAC THENL
     [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[];
      FIRST_ASSUM ACCEPT_TAC];
    ALL_TAC] THEN
  MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`;
    `(1 |-> (ee:A)) ((0 |-> (pr:A)) v0)`] HOLDS_ENTRY_FORM) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  ASM_REWRITE_TAC[VALMOD; ARITH_EQ] THEN ASM_MESON_TAC[]);;

(* --- ENTRY_SV: single-valuedness by EXPLICIT uniqueness chain (no MESON) *)
(* --- *)
let ENTRY_SV = prove
 (`!D (E:A->A->bool) B leq RG SEQ_acc SIN_acc rc pr e1 e2.
      model D E ZF_AX /\ ecba D E B leq /\ eisfun D E RG /\
      (?uu vv ru rv iva eva ive.
          uu IN D /\ vv IN D /\ ru IN D /\ rv IN D /\ iva IN D /\ eva IN D /\
          ive IN D /\ eopair D E uu vv pr /\ eapply D E RG uu ru /\
          eapply D E RG vv rv /\ eopair D E ru rv rc /\
          ebvin D E B leq SEQ_acc vv uu iva /\
          ebveq D E B leq SIN_acc uu vv eva /\
          eopair D E iva eva ive /\ eopair D E pr ive e1) /\
      (?uu vv ru rv iva eva ive.
          uu IN D /\ vv IN D /\ ru IN D /\ rv IN D /\ iva IN D /\ eva IN D /\
          ive IN D /\ eopair D E uu vv pr /\ eapply D E RG uu ru /\
          eapply D E RG vv rv /\ eopair D E ru rv rc /\
          ebvin D E B leq SEQ_acc vv uu iva /\
          ebveq D E B leq SIN_acc uu vv eva /\
          eopair D E iva eva ive /\ eopair D E pr ive e2)
      ==> e1 = e2`,
  REPEAT GEN_TAC THEN
  DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC (CONJUNCTS_THEN2 ASSUME_TAC
    (CONJUNCTS_THEN2 ASSUME_TAC (CONJUNCTS_THEN2
      (X_CHOOSE_THEN `uu1:A` (X_CHOOSE_THEN `vv1:A` (X_CHOOSE_THEN `ru1:A`
       (X_CHOOSE_THEN `rv1:A` (X_CHOOSE_THEN `iva1:A` (X_CHOOSE_THEN `eva1:A`
       (X_CHOOSE_THEN `ive1:A` STRIP_ASSUME_TAC)))))))
      (X_CHOOSE_THEN `uu2:A` (X_CHOOSE_THEN `vv2:A` (X_CHOOSE_THEN `ru2:A`
       (X_CHOOSE_THEN `rv2:A` (X_CHOOSE_THEN `iva2:A` (X_CHOOSE_THEN `eva2:A`
       (X_CHOOSE_THEN `ive2:A` STRIP_ASSUME_TAC))))))))))) THEN
  SUBGOAL_THEN `(uu1:A) = uu2 /\ (vv1:A) = vv2` STRIP_ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `uu1:A`; `vv1:A`;
      `uu2:A`; `vv2:A`; `pr:A`] EOPAIR_INJ) THEN ASM_REWRITE_TAC[];
      ALL_TAC] THEN
  SUBGOAL_THEN `(ru1:A) = ru2` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `RG:A`; `uu1:A`;
      `ru1:A`; `ru2:A`] EAPPLY_UNIQUE) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(rv1:A) = rv2` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `RG:A`; `vv1:A`;
      `rv1:A`; `rv2:A`] EAPPLY_UNIQUE) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(iva1:A) = iva2` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `B:A`; `leq:A`;
      `SEQ_acc:A`; `vv1:A`; `uu1:A`; `iva1:A`; `iva2:A`] EBVIN_UNIQUE) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(eva1:A) = eva2` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `B:A`; `leq:A`;
      `SIN_acc:A`; `uu1:A`; `vv1:A`; `eva1:A`; `eva2:A`] EBVEQ_UNIQUE) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(ive1:A) = ive2` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `iva1:A`; `eva1:A`;
      `ive1:A`; `ive2:A`] EOPAIR_UNIQUE) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MATCH_MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `pr:A`; `ive1:A`;
    `e1:A`; `e2:A`] EOPAIR_UNIQUE) THEN ASM_REWRITE_TAC[]);;

(* --- EBVATTSTEP_ENTRY_EXISTS: the entry-set for rank-code rc (via *)
(* replacement) --- *)
let EBVATTSTEP_ENTRY_EXISTS = prove
 (`!D (E:A->A->bool) B leq c RG SEQ_acc SIN_acc rc.
      model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\ c IN D /\
      RG IN D /\ eisfun D E RG /\ SEQ_acc IN D /\ SIN_acc IN D /\ rc IN D
      ==> ?y. y IN D /\
              (!e. e IN D
                   ==> (E e y <=>
                        ?pr. pr IN D /\ E pr c /\
                             ?uu vv ru rv iva eva ive.
                                uu IN D /\ vv IN D /\ ru IN D /\ rv IN D /\
                                iva IN D /\ eva IN D /\ ive IN D /\
                                eopair D E uu vv pr /\ eapply D E RG uu ru /\
                                eapply D E RG vv rv /\ eopair D E ru rv rc /\
                                ebvin D E B leq SEQ_acc vv uu iva /\
                                ebveq D E B leq SIN_acc uu vv eva /\
                                eopair D E iva eva ive /\
                                  eopair D E pr ive e))`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `?vb:num->A. valuation D vb` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[VALUATION_EXISTS; MODEL_NONEMPTY]; ALL_TAC] THEN
  ABBREV_TAC `v0 = (2 |-> (B:A)) ((3 |-> leq) ((4 |-> RG) ((5 |-> SEQ_acc)
     ((6 |-> SIN_acc) ((7 |-> rc) (vb:num->A))))))` THEN
  SUBGOAL_THEN `valuation D (v0:num->A)` ASSUME_TAC THENL
   [EXPAND_TAC "v0" THEN
    REPEAT(MATCH_MP_TAC VALUATION_VALMOD THEN CONJ_TAC THENL
            [ALL_TAC; FIRST_ASSUM ACCEPT_TAC]) THEN FIRST_ASSUM ACCEPT_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN
   `(v0:num->A) 2 = B /\ v0 3 = leq /\ v0 4 = RG /\ v0 5 = SEQ_acc /\
    v0 6 = SIN_acc /\ v0 7 = rc`
  STRIP_ASSUME_TAC THENL
   [EXPAND_TAC "v0" THEN REWRITE_TAC[VALMOD; ARITH_EQ]; ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`] ZF_REPLACEMENT) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(MP_TAC o SPECL [`entry_form`; `0`; `1`; `v0:num->A`; `c:A`]) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[ARITH_EQ] THEN
    X_GEN_TAC `pr:A` THEN STRIP_TAC THEN
    MATCH_MP_TAC REPL_SV_WITNESS THEN CONJ_TAC THENL
     [ASM_MESON_TAC[]; ALL_TAC] THEN
    MAP_EVERY X_GEN_TAC [`e1:A`; `e2:A`] THEN STRIP_TAC THEN
    MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `B:A`; `leq:A`; `RG:A`;
      `SEQ_acc:A`; `SIN_acc:A`; `rc:A`; `v0:num->A`; `e1:A`; `pr:A`]
      HOLDS_ENTRY_CONV) THEN
    ASM_REWRITE_TAC[] THEN DISCH_TAC THEN
    MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `B:A`; `leq:A`; `RG:A`;
      `SEQ_acc:A`; `SIN_acc:A`; `rc:A`; `v0:num->A`; `e2:A`; `pr:A`]
      HOLDS_ENTRY_CONV) THEN
    ASM_REWRITE_TAC[] THEN DISCH_TAC THEN
    MATCH_MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `B:A`; `leq:A`; `RG:A`;
      `SEQ_acc:A`; `SIN_acc:A`; `rc:A`; `pr:A`; `e1:A`; `e2:A`] ENTRY_SV) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `y:A`
             (CONJUNCTS_THEN2 ASSUME_TAC (LABEL_TAC "raw"))) THEN
  EXISTS_TAC `y:A` THEN CONJ_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  X_GEN_TAC `e:A` THEN DISCH_TAC THEN
  REMOVE_THEN "raw" (MP_TAC o SPEC `e:A`) THEN ASM_REWRITE_TAC[] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  MATCH_MP_TAC EXISTS_AND_CONG THEN X_GEN_TAC `pr:A` THEN DISCH_TAC THEN
  ASM_SIMP_TAC[HOLDS_ENTRY_CONV]);;

(* ===================================================================== *)
(* F4: per-STAGE entry-set (bundles the ecross + rank-graph).             *)
(* EBVATTSTAGE_ENTRY_EXISTS specialises EBVATTSTEP_ENTRY_EXISTS to an      *)
(* actual bname-stage w: it builds c = ecross w w (ECROSS_EXISTS) and RG = *)
(* the bname-rank graph on w (EBNRANK_GRAPH_EXISTS, functional), then the  *)
(* rank-code-rc entry-set exists in D.  This is the per-stage engine the   *)
(* recursion invokes (the RG rank-lookup property is exposed so a caller   *)
(* can read ranks off RG via ebnrank).                                     *)
(* ===================================================================== *)

(* ===================================================================== *)
(* F4: projection PREDICATES ebvsubeq / ebvsubin.                         *)
(* Named forms of the b0 sub-table projections of an accumulated blob:    *)
(*   ebvsubeq D E tab s  <=>  s = { <pr,eval> : <pr,<ival,eval>> IN tab }  *)
(*   ebvsubin D E tab s  <=>  s = { <pr,ival> : <pr,<ival,eval>> IN tab }. *)
(* _PRED_EXISTS fold EBVSUBEQ/EBVSUBIN_EXISTS (b0) into the predicate;     *)
(* _UNIQUE give single-valuedness (same E-members => equal, via            *)
(* ESUBSET_ANTISYM; membership transferred by CONV_TAC TAUT with the       *)
(* eopair-char as an opaque atom -- no ASM_MESON, no eopair blowup).       *)
(* These name the accumulated tables SEQ_acc/SIN_acc for the erec step.    *)
(* ===================================================================== *)

let ebvsubeq = new_definition
 `ebvsubeq D (E:A->A->bool) tab s <=>
    s IN D /\
    (!z. z IN D
         ==> (E z s <=>
              ?u. u IN D /\ E u tab /\
                  ?pr. pr IN D /\ ?inner. inner IN D /\ ?ival. ival IN D /\
                       ?eval. eval IN D /\
                       eopair D E pr inner u /\ eopair D E ival eval inner /\
                       eopair D E pr eval z))`;;
let ebvsubin = new_definition
 `ebvsubin D (E:A->A->bool) tab s <=>
    s IN D /\
    (!z. z IN D
         ==> (E z s <=>
              ?u. u IN D /\ E u tab /\
                  ?pr. pr IN D /\ ?inner. inner IN D /\ ?ival. ival IN D /\
                       ?eval. eval IN D /\
                       eopair D E pr inner u /\ eopair D E ival eval inner /\
                       eopair D E pr ival z))`;;
let EBVSUBEQ_PRED_EXISTS = prove
 (`!D (E:A->A->bool) tab. model D E ZF_AX /\ tab IN D ==>
   ?s. ebvsubeq D E tab s`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[ebvsubeq] THEN
  MATCH_MP_TAC EBVSUBEQ_EXISTS THEN ASM_REWRITE_TAC[]);;
let EBVSUBIN_PRED_EXISTS = prove
 (`!D (E:A->A->bool) tab. model D E ZF_AX /\ tab IN D ==>
   ?s. ebvsubin D E tab s`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[ebvsubin] THEN
  MATCH_MP_TAC EBVSUBIN_EXISTS THEN ASM_REWRITE_TAC[]);;

let EBVSUBEQ_UNIQUE = prove
 (`!D (E:A->A->bool) tab s s'.
      model D E ZF_AX /\ ebvsubeq D E tab s /\ ebvsubeq D E tab s' ==> s = s'`,
  REPEAT GEN_TAC THEN REWRITE_TAC[ebvsubeq] THEN
  INTRO_TAC "zf (sD cs) sD2 cs2" THEN
  SUBGOAL_THEN `!z:A. z IN D ==> ((E:A->A->bool) z s <=> E z s')`
    ASSUME_TAC THENL
   [X_GEN_TAC `z:A` THEN DISCH_TAC THEN
    USE_THEN "cs"
      (fun c -> MP_TAC(MATCH_MP (SPEC `z:A` c) (ASSUME `(z:A) IN D`))) THEN
      USE_THEN "cs2"
        (fun c -> MP_TAC(MATCH_MP (SPEC `z:A` c) (ASSUME `(z:A) IN D`))) THEN
        CONV_TAC TAUT; ALL_TAC] THEN
  MATCH_MP_TAC ESUBSET_ANTISYM THEN ASM_REWRITE_TAC[esubset] THEN
  ASM_MESON_TAC[]);;
let EBVSUBIN_UNIQUE = prove
 (`!D (E:A->A->bool) tab s s'.
      model D E ZF_AX /\ ebvsubin D E tab s /\ ebvsubin D E tab s' ==> s = s'`,
  REPEAT GEN_TAC THEN REWRITE_TAC[ebvsubin] THEN
  INTRO_TAC "zf (sD cs) sD2 cs2" THEN
  SUBGOAL_THEN `!z:A. z IN D ==> ((E:A->A->bool) z s <=> E z s')`
    ASSUME_TAC THENL
   [X_GEN_TAC `z:A` THEN DISCH_TAC THEN
    USE_THEN "cs"
      (fun c -> MP_TAC(MATCH_MP (SPEC `z:A` c) (ASSUME `(z:A) IN D`))) THEN
      USE_THEN "cs2"
        (fun c -> MP_TAC(MATCH_MP (SPEC `z:A` c) (ASSUME `(z:A) IN D`))) THEN
        CONV_TAC TAUT; ALL_TAC] THEN
  MATCH_MP_TAC ESUBSET_ANTISYM THEN ASM_REWRITE_TAC[esubset] THEN
  ASM_MESON_TAC[]);;

(* ==================================================================== *)
(* the SEMANTIC recursion step  ebvattstep                              *)
(*                                                                      *)
(* One transfinite-recursion stage of the Boolean IN/EQ value.  Reads   *)
(* the partial table g (a function delta |-> stage-value); its domain   *)
(* delta is the ordinal reached so far and its range-union tabr holds    *)
(* every entry <pr,<ival,eval>> produced so far.  Projecting tabr gives  *)
(* the accumulated =-value table sEQ (ebvsubeq) and IN-value table sIN   *)
(* (ebvsubin).  The step's output y is the entry-SET for rank-code       *)
(* rc = f(delta): { <pr,<[[u IN v]],[[u=v]]>> : <u,v> in c, rankcode=rc }.*)
(* The f-lookup is placed INSIDE e-membership, so an undefined f(delta)  *)
(* yields the empty set -- the step is TOTAL for every g.                *)
(* ==================================================================== *)

let ebvattstep = new_definition
 `ebvattstep D (E:A->A->bool) B leq c RG f g y <=>
    ?delta tabr sEQ sIN.
       edomain D E g delta /\ eranu D E g tabr /\
       ebvsubeq D E tabr sEQ /\ ebvsubin D E tabr sIN /\
       y IN D /\
       (!e. e IN D
            ==> (E e y <=>
                 ?rc. eapply D E f delta rc /\
                      ?pr. pr IN D /\ E pr c /\
                           ?uu vv ru rv iva eva ive.
                              uu IN D /\ vv IN D /\ ru IN D /\ rv IN D /\
                              iva IN D /\ eva IN D /\ ive IN D /\
                              eopair D E uu vv pr /\ eapply D E RG uu ru /\
                              eapply D E RG vv rv /\ eopair D E ru rv rc /\
                              ebvin D E B leq sEQ vv uu iva /\
                              ebveq D E B leq sIN uu vv eva /\
                              eopair D E iva eva ive /\
                                eopair D E pr ive e))`;;

(* --- ebvattstep single-valuedness --- *)
let EBVATTSTEP_UNIQUE = prove
 (`!D (E:A->A->bool) B leq c RG f g y y'.
      model D E ZF_AX /\ ebvattstep D E B leq c RG f g y /\
      ebvattstep D E B leq c RG f g y'
      ==> y = y'`,
  REPEAT GEN_TAC THEN REWRITE_TAC[ebvattstep] THEN
  DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC
     (CONJUNCTS_THEN2 (LABEL_TAC "Hy") (LABEL_TAC "Hz"))) THEN
  REMOVE_THEN "Hy" (X_CHOOSE_THEN `d1:A` (X_CHOOSE_THEN `t1:A`
    (X_CHOOSE_THEN `q1:A` (X_CHOOSE_THEN `n1:A`
     (CONJUNCTS_THEN2 (LABEL_TAC "edy")
      (CONJUNCTS_THEN2 (LABEL_TAC "eru")
       (CONJUNCTS_THEN2 (LABEL_TAC "beq")
        (CONJUNCTS_THEN2 (LABEL_TAC "bin")
         (CONJUNCTS_THEN2 ASSUME_TAC (LABEL_TAC "chy")))))))))) THEN
  REMOVE_THEN "Hz" (X_CHOOSE_THEN `d2:A` (X_CHOOSE_THEN `t2:A`
    (X_CHOOSE_THEN `q2:A` (X_CHOOSE_THEN `n2:A`
     (CONJUNCTS_THEN2 (LABEL_TAC "edp")
      (CONJUNCTS_THEN2 (LABEL_TAC "erp")
       (CONJUNCTS_THEN2 (LABEL_TAC "bep")
        (CONJUNCTS_THEN2 (LABEL_TAC "bip")
         (CONJUNCTS_THEN2 ASSUME_TAC (LABEL_TAC "chp")))))))))) THEN
  SUBGOAL_THEN `(d1:A) = d2` SUBST_ALL_TAC THENL
   [MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`g:A`;`d1:A`;`d2:A`]
      EDOMAIN_UNIQUE) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(t1:A) = t2` SUBST_ALL_TAC THENL
   [MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`g:A`;`t1:A`;`t2:A`]
      ERANU_UNIQUE) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(q1:A) = q2` SUBST_ALL_TAC THENL
   [MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`t2:A`;`q1:A`;`q2:A`]
      EBVSUBEQ_UNIQUE) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(n1:A) = n2` SUBST_ALL_TAC THENL
   [MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`t2:A`;`n1:A`;`n2:A`]
      EBVSUBIN_UNIQUE) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `!e:A. e IN D ==> ((E:A->A->bool) e y <=> E e y')`
    ASSUME_TAC THENL
   [X_GEN_TAC `e:A` THEN DISCH_TAC THEN
    USE_THEN "chy" (MP_TAC o C MATCH_MP (ASSUME `(e:A) IN D`)) THEN
    USE_THEN "chp" (MP_TAC o C MATCH_MP (ASSUME `(e:A) IN D`)) THEN
    CONV_TAC TAUT;
    ALL_TAC] THEN
  MATCH_MP_TAC ESUBSET_ANTISYM THEN ASM_REWRITE_TAC[esubset] THEN
  ASM_MESON_TAC[]);;

(* --- ebvattstep totality (any g): entry-set when f(delta) defined, else *)
(* empty --- *)
let EBVATTSTEP_TOTAL = prove
 (`!D (E:A->A->bool) B leq c RG f g.
      model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\ c IN D /\
      RG IN D /\ eisfun D E RG /\ f IN D /\ eisfun D E f /\ g IN D
      ==> ?y. ebvattstep D E B leq c RG f g y`,
  REPEAT STRIP_TAC THEN
  MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`g:A`] EDOMAIN_EXISTS) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `delta:A` (fun th ->
    ASSUME_TAC th THEN ASSUME_TAC(CONJUNCT1(REWRITE_RULE[edomain] th)))) THEN
  MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`g:A`] ERANU_EXISTS) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `tabr:A` (fun th ->
    ASSUME_TAC th THEN ASSUME_TAC(CONJUNCT1(REWRITE_RULE[eranu] th)))) THEN
  MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`tabr:A`] EBVSUBEQ_PRED_EXISTS) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `seqt:A` (fun th ->
    ASSUME_TAC th THEN ASSUME_TAC(CONJUNCT1(REWRITE_RULE[ebvsubeq] th)))) THEN
  MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`tabr:A`] EBVSUBIN_PRED_EXISTS) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `sint:A` (fun th ->
    ASSUME_TAC th THEN ASSUME_TAC(CONJUNCT1(REWRITE_RULE[ebvsubin] th)))) THEN
  ASM_CASES_TAC `?rc:A. rc IN D /\ eapply D E f delta rc` THENL
   [(* --- f(delta) defined: y = entry-set for that rank-code --- *)
    FIRST_X_ASSUM(X_CHOOSE_THEN `rc0:A` STRIP_ASSUME_TAC) THEN
    MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`c:A`;`RG:A`;
      `seqt:A`;`sint:A`;`rc0:A`] EBVATTSTEP_ENTRY_EXISTS) THEN
    ASM_REWRITE_TAC[] THEN
    DISCH_THEN(X_CHOOSE_THEN `y:A`
               (CONJUNCTS_THEN2 ASSUME_TAC (LABEL_TAC "ymem"))) THEN
    EXISTS_TAC `y:A` THEN REWRITE_TAC[ebvattstep] THEN
    MAP_EVERY EXISTS_TAC [`delta:A`;`tabr:A`;`seqt:A`;`sint:A`] THEN
    ASM_REWRITE_TAC[] THEN
    X_GEN_TAC `e:A` THEN DISCH_TAC THEN
    USE_THEN "ymem" (fun th ->
      REWRITE_TAC[MATCH_MP (SPEC `e:A` th) (ASSUME `(e:A) IN D`)]) THEN
    EQ_TAC THENL
     [DISCH_TAC THEN EXISTS_TAC `rc0:A` THEN
      CONJ_TAC THENL [FIRST_ASSUM ACCEPT_TAC; FIRST_ASSUM ACCEPT_TAC];
      DISCH_THEN(X_CHOOSE_THEN `rc:A`
        (CONJUNCTS_THEN2 (LABEL_TAC "eap") (LABEL_TAC "bod"))) THEN
      SUBGOAL_THEN `(rc:A) = rc0` ASSUME_TAC THENL
       [MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`f:A`;`delta:A`;
          `rc:A`;`rc0:A`] EAPPLY_UNIQUE) THEN ASM_REWRITE_TAC[] THEN
        USE_THEN "bod" (REPEAT_TCL CHOOSE_THEN STRIP_ASSUME_TAC) THEN
        ASM_MESON_TAC[EOPAIR_IN];
        ALL_TAC] THEN
      UNDISCH_THEN `(rc:A) = rc0` SUBST_ALL_TAC THEN
      USE_THEN "bod" ACCEPT_TAC];
    (* --- f(delta) undefined: y = empty set --- *)
    MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`] EEMPTY_EXISTS) THEN
    ASM_REWRITE_TAC[] THEN
    DISCH_THEN(X_CHOOSE_THEN `y:A` (fun th ->
      CONJUNCTS_THEN2 ASSUME_TAC (LABEL_TAC "yemp")
        (REWRITE_RULE[eempty] th))) THEN
    EXISTS_TAC `y:A` THEN REWRITE_TAC[ebvattstep] THEN
    MAP_EVERY EXISTS_TAC [`delta:A`;`tabr:A`;`seqt:A`;`sint:A`] THEN
    ASM_REWRITE_TAC[] THEN
    X_GEN_TAC `e:A` THEN DISCH_TAC THEN
    MATCH_MP_TAC(TAUT `~a /\ ~b ==> (a <=> b)`) THEN CONJ_TAC THENL
     [USE_THEN "yemp" (fun th ->
        ACCEPT_TAC(MATCH_MP (SPEC `e:A` th) (ASSUME `(e:A) IN D`)));
      DISCH_THEN(X_CHOOSE_THEN `rc:A`
        (CONJUNCTS_THEN2 (LABEL_TAC "eap") (LABEL_TAC "bod"))) THEN
      SUBGOAL_THEN `(rc:A) IN D` ASSUME_TAC THENL
       [USE_THEN "bod" (REPEAT_TCL CHOOSE_THEN STRIP_ASSUME_TAC) THEN
        ASM_MESON_TAC[EOPAIR_IN];
        ALL_TAC] THEN
      ASM_MESON_TAC[]]]);;

(* ===================================================================== *)
(* F4: OBJECT forms for the step's sub-ops.                               *)
(* eranu_form (range-union, extensional via ranmem_form), ebvsubeq_form / *)
(* ebvsubin_form (the =/IN projections of the entry-table, via opair_form),*)
(* each with FV + a HOLDS_* bridge.  HOLDS_ALL/HOLDS_MEM peel just the     *)
(* outer !!/membership atom so the inner ?? body is handled by            *)
(* EXISTS_AND_CONG.                                                      *)
(* ===================================================================== *)
(* eranu_form i j : "v j is the range-union of the function v i".
   Extensional characterization via ranmem_form (the range-member
     predicate). *)
let eranu_form = new_definition
  `eranu_form i j =
     !! (MAX i j + 1)
        (((MAX i j + 1) %% j) <-> ranmem_form (MAX i j + 1) i)`;;

let HOLDS_ERANU_FORM = prove
 (`!D (E:A->A->bool) v i j.
        valuation D v
        ==> (holds D E v (eranu_form i j) <=> eranu D E (v i) (v j))`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `!x. (v:num->A) x IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[valuation]; ALL_TAC] THEN
  SUBGOAL_THEN
   `!a:A. a IN D
        ==> (holds D E (((MAX i j + 1) |-> a) v)
             (ranmem_form (MAX i j + 1) i) <=>
             eranmem D E a (v i))`
  ASSUME_TAC THENL
   [REPEAT STRIP_TAC THEN
    MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`;
      `((MAX i j + 1) |-> (a:A)) v`; `MAX i j + 1`; `i:num`]
               HOLDS_RANMEM_FORM) THEN
    ANTS_TAC THENL [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
    SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER; ARITH_RULE `~(i = MAX i j + 1)`];
    ALL_TAC] THEN
  REWRITE_TAC[eranu_form; holds; HOLDS_IFF] THEN
  ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER;
               ARITH_RULE `~(j = MAX i j + 1)`] THEN
  ASM_SIMP_TAC[] THEN
  REWRITE_TAC[eranu] THEN ASM_REWRITE_TAC[]);;

let HOLDS_ALL = prove
 (`!D (E:A->A->bool) v n p.
      holds D E v (!! n p) <=> (!a. a IN D ==> holds D E ((n |-> a) v) p)`,
  REWRITE_TAC[holds]);;

let HOLDS_MEM = prove
 (`!D (E:A->A->bool) v i j. holds D E v (i %% j) <=> E (v i) (v j)`,
  REWRITE_TAC[holds]);;

let ebvsubeq_form = new_definition
  `ebvsubeq_form i j =
     !! (MAX i j + 1) (
        ((MAX i j + 1) %% j) <->
        ?? (MAX i j + 2) (
           ((MAX i j + 2) %% i) &&
           ?? (MAX i j + 3)
             (?? (MAX i j + 4) (?? (MAX i j + 5) (?? (MAX i j + 6) (
              opair_form (MAX i j + 3) (MAX i j + 4) (MAX i j + 2) &&
              opair_form (MAX i j + 5) (MAX i j + 6) (MAX i j + 4) &&
              opair_form (MAX i j + 3) (MAX i j + 6) (MAX i j + 1)))))))`;;

let ebvsubin_form = new_definition
  `ebvsubin_form i j =
     !! (MAX i j + 1) (
        ((MAX i j + 1) %% j) <->
        ?? (MAX i j + 2) (
           ((MAX i j + 2) %% i) &&
           ?? (MAX i j + 3)
             (?? (MAX i j + 4) (?? (MAX i j + 5) (?? (MAX i j + 6) (
              opair_form (MAX i j + 3) (MAX i j + 4) (MAX i j + 2) &&
              opair_form (MAX i j + 5) (MAX i j + 6) (MAX i j + 4) &&
              opair_form (MAX i j + 3) (MAX i j + 5) (MAX i j + 1)))))))`;;

let HOLDS_EBVSUBEQ_FORM = prove
 (`!D (E:A->A->bool) v i j.
        valuation D v
        ==> (holds D E v (ebvsubeq_form i j) <=> ebvsubeq D E (v i) (v j))`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `!x. (v:num->A) x IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[valuation]; ALL_TAC] THEN
  SUBGOAL_THEN
   `!a:A. a IN D ==>
      (holds D E (((MAX i j + 1) |-> a) v)
        (?? (MAX i j + 2) (((MAX i j + 2) %% i) &&
           ?? (MAX i j + 3)
             (?? (MAX i j + 4) (?? (MAX i j + 5) (?? (MAX i j + 6) (
              opair_form (MAX i j + 3) (MAX i j + 4) (MAX i j + 2) &&
              opair_form (MAX i j + 5) (MAX i j + 6) (MAX i j + 4) &&
              opair_form (MAX i j + 3) (MAX i j + 6) (MAX i j + 1))))))) <=>
       (?u. u IN D /\ E u (v i) /\ ?pr. pr IN D /\ ?inn. inn IN D /\
            ?iv. iv IN D /\ ?ev. ev IN D /\
            eopair D E pr inn u /\ eopair D E iv ev inn /\
              eopair D E pr ev a))`
  ASSUME_TAC THENL
   [X_GEN_TAC `a:A` THEN DISCH_TAC THEN
    REWRITE_TAC[HOLDS_EX] THEN
    MATCH_MP_TAC EXISTS_AND_CONG THEN X_GEN_TAC `u:A` THEN DISCH_TAC THEN
    REWRITE_TAC[HOLDS_AND] THEN
    MATCH_MP_TAC(TAUT `(a <=> c) /\ (b <=> d) ==> (a /\ b <=> c /\ d)`) THEN
    CONJ_TAC THENL
     [REWRITE_TAC[HOLDS_MEM] THEN
      ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER; ARITH_RULE
        `~(i = MAX i j + 1) /\ ~(i = MAX i j + 2)`];
      ALL_TAC] THEN
    REWRITE_TAC[HOLDS_EX] THEN
    MATCH_MP_TAC EXISTS_AND_CONG THEN X_GEN_TAC `pr:A` THEN DISCH_TAC THEN
    MATCH_MP_TAC EXISTS_AND_CONG THEN X_GEN_TAC `inn:A` THEN DISCH_TAC THEN
    MATCH_MP_TAC EXISTS_AND_CONG THEN X_GEN_TAC `iv:A` THEN DISCH_TAC THEN
    MATCH_MP_TAC EXISTS_AND_CONG THEN X_GEN_TAC `ev:A` THEN DISCH_TAC THEN
    ABBREV_TAC
     `VV = ((MAX i j + 6) |-> (ev:A)) (((MAX i j + 5) |-> iv)
        (((MAX i j + 4) |-> inn) (((MAX i j + 3) |-> pr)
         (((MAX i j + 2) |-> u) (((MAX i j + 1) |-> a) v)))))` THEN
    SUBGOAL_THEN `valuation D (VV:num->A)` ASSUME_TAC THENL
     [EXPAND_TAC "VV" THEN
      REPEAT(MATCH_MP_TAC VALUATION_VALMOD THEN CONJ_TAC THENL
              [ALL_TAC; FIRST_ASSUM ACCEPT_TAC]) THEN FIRST_ASSUM ACCEPT_TAC;
      ALL_TAC] THEN
    REWRITE_TAC[HOLDS_AND] THEN
    ASM_SIMP_TAC[HOLDS_OPAIR_FORM] THEN
    EXPAND_TAC "VV" THEN
    SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER; ARITH_RULE
      `~(MAX i j + 1 = MAX i j + 2) /\ ~(MAX i j + 1 = MAX i j + 3) /\
       ~(MAX i j + 1 = MAX i j + 4) /\ ~(MAX i j + 1 = MAX i j + 5) /\
       ~(MAX i j + 1 = MAX i j + 6) /\ ~(MAX i j + 2 = MAX i j + 3) /\
       ~(MAX i j + 2 = MAX i j + 4) /\ ~(MAX i j + 2 = MAX i j + 5) /\
       ~(MAX i j + 2 = MAX i j + 6) /\ ~(MAX i j + 3 = MAX i j + 4) /\
       ~(MAX i j + 3 = MAX i j + 5) /\ ~(MAX i j + 3 = MAX i j + 6) /\
       ~(MAX i j + 4 = MAX i j + 5) /\ ~(MAX i j + 4 = MAX i j + 6) /\
       ~(MAX i j + 5 = MAX i j + 6)`];
    ALL_TAC] THEN
  REWRITE_TAC[ebvsubeq_form; HOLDS_ALL; HOLDS_IFF; HOLDS_MEM] THEN
  ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER;
               ARITH_RULE `~(j = MAX i j + 1)`] THEN
  ASM_SIMP_TAC[] THEN
  REWRITE_TAC[ebvsubeq] THEN ASM_REWRITE_TAC[]);;

let HOLDS_EBVSUBIN_FORM = prove
 (`!D (E:A->A->bool) v i j.
        valuation D v
        ==> (holds D E v (ebvsubin_form i j) <=> ebvsubin D E (v i) (v j))`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `!x. (v:num->A) x IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[valuation]; ALL_TAC] THEN
  SUBGOAL_THEN
   `!a:A. a IN D ==>
      (holds D E (((MAX i j + 1) |-> a) v)
        (?? (MAX i j + 2) (((MAX i j + 2) %% i) &&
           ?? (MAX i j + 3)
             (?? (MAX i j + 4) (?? (MAX i j + 5) (?? (MAX i j + 6) (
              opair_form (MAX i j + 3) (MAX i j + 4) (MAX i j + 2) &&
              opair_form (MAX i j + 5) (MAX i j + 6) (MAX i j + 4) &&
              opair_form (MAX i j + 3) (MAX i j + 5) (MAX i j + 1))))))) <=>
       (?u. u IN D /\ E u (v i) /\ ?pr. pr IN D /\ ?inn. inn IN D /\
            ?iv. iv IN D /\ ?ev. ev IN D /\
            eopair D E pr inn u /\ eopair D E iv ev inn /\
              eopair D E pr iv a))`
  ASSUME_TAC THENL
   [X_GEN_TAC `a:A` THEN DISCH_TAC THEN
    REWRITE_TAC[HOLDS_EX] THEN
    MATCH_MP_TAC EXISTS_AND_CONG THEN X_GEN_TAC `u:A` THEN DISCH_TAC THEN
    REWRITE_TAC[HOLDS_AND] THEN
    MATCH_MP_TAC(TAUT `(a <=> c) /\ (b <=> d) ==> (a /\ b <=> c /\ d)`) THEN
    CONJ_TAC THENL
     [REWRITE_TAC[HOLDS_MEM] THEN
      ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER; ARITH_RULE
        `~(i = MAX i j + 1) /\ ~(i = MAX i j + 2)`];
      ALL_TAC] THEN
    REWRITE_TAC[HOLDS_EX] THEN
    MATCH_MP_TAC EXISTS_AND_CONG THEN X_GEN_TAC `pr:A` THEN DISCH_TAC THEN
    MATCH_MP_TAC EXISTS_AND_CONG THEN X_GEN_TAC `inn:A` THEN DISCH_TAC THEN
    MATCH_MP_TAC EXISTS_AND_CONG THEN X_GEN_TAC `iv:A` THEN DISCH_TAC THEN
    MATCH_MP_TAC EXISTS_AND_CONG THEN X_GEN_TAC `ev:A` THEN DISCH_TAC THEN
    ABBREV_TAC
     `VV = ((MAX i j + 6) |-> (ev:A)) (((MAX i j + 5) |-> iv)
        (((MAX i j + 4) |-> inn) (((MAX i j + 3) |-> pr)
         (((MAX i j + 2) |-> u) (((MAX i j + 1) |-> a) v)))))` THEN
    SUBGOAL_THEN `valuation D (VV:num->A)` ASSUME_TAC THENL
     [EXPAND_TAC "VV" THEN
      REPEAT(MATCH_MP_TAC VALUATION_VALMOD THEN CONJ_TAC THENL
              [ALL_TAC; FIRST_ASSUM ACCEPT_TAC]) THEN FIRST_ASSUM ACCEPT_TAC;
      ALL_TAC] THEN
    REWRITE_TAC[HOLDS_AND] THEN
    ASM_SIMP_TAC[HOLDS_OPAIR_FORM] THEN
    EXPAND_TAC "VV" THEN
    SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER; ARITH_RULE
      `~(MAX i j + 1 = MAX i j + 2) /\ ~(MAX i j + 1 = MAX i j + 3) /\
       ~(MAX i j + 1 = MAX i j + 4) /\ ~(MAX i j + 1 = MAX i j + 5) /\
       ~(MAX i j + 1 = MAX i j + 6) /\ ~(MAX i j + 2 = MAX i j + 3) /\
       ~(MAX i j + 2 = MAX i j + 4) /\ ~(MAX i j + 2 = MAX i j + 5) /\
       ~(MAX i j + 2 = MAX i j + 6) /\ ~(MAX i j + 3 = MAX i j + 4) /\
       ~(MAX i j + 3 = MAX i j + 5) /\ ~(MAX i j + 3 = MAX i j + 6) /\
       ~(MAX i j + 4 = MAX i j + 5) /\ ~(MAX i j + 4 = MAX i j + 6) /\
       ~(MAX i j + 5 = MAX i j + 6)`];
    ALL_TAC] THEN
  REWRITE_TAC[ebvsubin_form; HOLDS_ALL; HOLDS_IFF; HOLDS_MEM] THEN
  ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER;
               ARITH_RULE `~(j = MAX i j + 1)`] THEN
  ASM_SIMP_TAC[] THEN
  REWRITE_TAC[ebvsubin] THEN ASM_REWRITE_TAC[]);;

(* ===================================================================== *)
(* F4 assembly (part 1): the erec STEP object formula                     *)
(* ebvattstep_form (slots 0=r 1=w 2=B 3=leq 4=c 5=RG 6=f; ex 7=delta      *)
(* 8=tabr 9=sEQ 10=sIN, membership e=11 rc=12 pr=13 tuple 14-20), and     *)
(* HOLDS_ATTSTEP_MEMB: the membership !!11 body bridged to the clean       *)
(* entry-relation (interleaved existentials, matching HOLDS_EX and        *)
(* EXISTS_AND_CONG).                                                     *)
(* ===================================================================== *)
let ebvattstep_form = new_definition
 `ebvattstep_form =
    ?? 7 (?? 8 (?? 9 (?? 10 (
       domain_form 0 7 &&
       eranu_form 0 8 &&
       ebvsubeq_form 8 9 &&
       ebvsubin_form 8 10 &&
       !! 11 ((11 %% 1) <->
          ?? 12 (
             apply_form 6 7 12 &&
             ?? 13 ((13 %% 4) &&
                ?? 14 (?? 15 (?? 16 (?? 17 (?? 18 (?? 19 (?? 20 (
                   opair_form 14 15 13 &&
                   apply_form 5 14 16 &&
                   apply_form 5 15 17 &&
                   opair_form 16 17 12 &&
                   ebvin_form 18 9 15 14 3 2 &&
                   ebveq_form 19 10 14 15 3 2 &&
                   opair_form 18 19 20 &&
                   opair_form 13 20 11))))))))))))))`;;

let HOLDS_ATTSTEP_MEMB = prove
 (`!D (E:A->A->bool) VV.
     model D E ZF_AX /\ valuation D VV
     ==> (holds D E VV
            (!! 11 ((11 %% 1) <->
               ?? 12 (apply_form 6 7 12 &&
                  ?? 13 ((13 %% 4) &&
                     ?? 14 (?? 15 (?? 16 (?? 17 (?? 18 (?? 19 (?? 20 (
                        opair_form 14 15 13 &&
                        apply_form 5 14 16 &&
                        apply_form 5 15 17 &&
                        opair_form 16 17 12 &&
                        ebvin_form 18 9 15 14 3 2 &&
                        ebveq_form 19 10 14 15 3 2 &&
                        opair_form 18 19 20 &&
                        opair_form 13 20 11))))))))))) <=>
          (!a. a IN D ==> (E a (VV 1) <=>
             ?rc. rc IN D /\ eapply D E (VV 6) (VV 7) rc /\
                  ?pr. pr IN D /\ E pr (VV 4) /\
                       ?uu. uu IN D /\ ?vv. vv IN D /\ ?ru. ru IN D /\
                       ?rv. rv IN D /\ ?iva. iva IN D /\ ?eva. eva IN D /\
                       ?ive. ive IN D /\
                          eopair D E uu vv pr /\ eapply D E (VV 5) uu ru /\
                          eapply D E (VV 5) vv rv /\ eopair D E ru rv rc /\
                          ebvin D E (VV 2) (VV 3) (VV 9) vv uu iva /\
                          ebveq D E (VV 2) (VV 3) (VV 10) uu vv eva /\
                          eopair D E iva eva ive /\ eopair D E pr ive a)))`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `!x. (VV:num->A) x IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[valuation]; ALL_TAC] THEN
  REWRITE_TAC[HOLDS_ALL] THEN AP_TERM_TAC THEN ABS_TAC THEN
  MATCH_MP_TAC(TAUT `(p ==> (q <=> r)) ==> ((p ==> q) <=> (p ==> r))`) THEN
  DISCH_TAC THEN
  REWRITE_TAC[HOLDS_IFF; HOLDS_MEM] THEN
  REWRITE_TAC[VALMOD; ARITH_EQ] THEN
  MATCH_MP_TAC(TAUT `(b <=> c) ==> ((z <=> b) <=> (z <=> c))`) THEN
  REWRITE_TAC[HOLDS_EX] THEN
  MATCH_MP_TAC EXISTS_AND_CONG THEN X_GEN_TAC `rc:A` THEN DISCH_TAC THEN
  REWRITE_TAC[HOLDS_AND] THEN
  MATCH_MP_TAC(TAUT `(x <=> z) /\ (y <=> w) ==> (x /\ y <=> z /\ w)`) THEN
  CONJ_TAC THENL
   [SUBGOAL_THEN `valuation D ((12 |-> (rc:A)) ((11 |-> (a:A)) VV))`
    ASSUME_TAC THENL
    [REPEAT(MATCH_MP_TAC VALUATION_VALMOD THEN CONJ_TAC THENL
              [ALL_TAC; FIRST_ASSUM ACCEPT_TAC]) THEN FIRST_ASSUM ACCEPT_TAC;
      ALL_TAC] THEN
    ASM_SIMP_TAC[HOLDS_APPLY_FORM] THEN REWRITE_TAC[VALMOD; ARITH_EQ];
    ALL_TAC] THEN
  REWRITE_TAC[HOLDS_EX] THEN
  MATCH_MP_TAC EXISTS_AND_CONG THEN X_GEN_TAC `pr:A` THEN DISCH_TAC THEN
  REWRITE_TAC[HOLDS_AND] THEN
  MATCH_MP_TAC(TAUT `(x <=> z) /\ (y <=> w) ==> (x /\ y <=> z /\ w)`) THEN
  CONJ_TAC THENL
   [REWRITE_TAC[HOLDS_MEM] THEN REWRITE_TAC[VALMOD; ARITH_EQ];
    ALL_TAC] THEN
  REWRITE_TAC[HOLDS_EX] THEN
  MATCH_MP_TAC EXISTS_AND_CONG THEN X_GEN_TAC `uu:A` THEN DISCH_TAC THEN
  MATCH_MP_TAC EXISTS_AND_CONG THEN X_GEN_TAC `vv:A` THEN DISCH_TAC THEN
  MATCH_MP_TAC EXISTS_AND_CONG THEN X_GEN_TAC `ru:A` THEN DISCH_TAC THEN
  MATCH_MP_TAC EXISTS_AND_CONG THEN X_GEN_TAC `rv:A` THEN DISCH_TAC THEN
  MATCH_MP_TAC EXISTS_AND_CONG THEN X_GEN_TAC `iva:A` THEN DISCH_TAC THEN
  MATCH_MP_TAC EXISTS_AND_CONG THEN X_GEN_TAC `eva:A` THEN DISCH_TAC THEN
  MATCH_MP_TAC EXISTS_AND_CONG THEN X_GEN_TAC `ive:A` THEN DISCH_TAC THEN
  ABBREV_TAC
   `WW = (20 |-> (ive:A)) ((19 |-> eva) ((18 |-> iva) ((17 |-> rv)
      ((16 |-> ru) ((15 |-> vv) ((14 |-> uu) ((13 |-> pr) ((12 |-> rc)
       ((11 |-> (a:A)) VV)))))))))` THEN
  SUBGOAL_THEN `valuation D (WW:num->A)` ASSUME_TAC THENL
   [EXPAND_TAC "WW" THEN
    REPEAT(MATCH_MP_TAC VALUATION_VALMOD THEN CONJ_TAC THENL
            [ALL_TAC; FIRST_ASSUM ACCEPT_TAC]) THEN FIRST_ASSUM ACCEPT_TAC;
    ALL_TAC] THEN
  REWRITE_TAC[HOLDS_AND] THEN
  ASM_SIMP_TAC[HOLDS_OPAIR_FORM; HOLDS_APPLY_FORM; HOLDS_EBVIN_FORM;
               HOLDS_EBVEQ_FORM] THEN
  EXPAND_TAC "WW" THEN REWRITE_TAC[VALMOD; ARITH_EQ]);;

(* ===================================================================== *)
(* F4 assembly (part 2): HOLDS_EBVATTSTEP_FORM.                           *)
(* ebvattstep_alt = the interleaved (HOLDS_EX-shaped) twin of ebvattstep; *)
(* HOLDS_EBVATTSTEP_ALT bridges holds(ebvattstep_form) to it by clean     *)
(* EXISTS_AND_CONG over the 4 outer existentials + the sub-form/membership *)
(* bridges.  EBVATTSTEP_ALT_EQ (y IN D) reshuffles alt <-> ebvattstep     *)
(* (MEMB_RESHUF for the tuple via EOPAIR_IN; *_IN for the redundant outer *)
(* domain/ranu/proj IN D).  HOLDS_EBVATTSTEP_FORM composes the two: the   *)
(* erec STEP relation q with holds q <=> ebvattstep, ready for EREC.      *)
(* ===================================================================== *)
let ebvattstep_alt = new_definition
 `ebvattstep_alt D (E:A->A->bool) B leq c RG f g y <=>
    ?delta. delta IN D /\ ?tabr. tabr IN D /\ ?sEQ. sEQ IN D /\
      ?sIN. sIN IN D /\
       edomain D E g delta /\ eranu D E g tabr /\
       ebvsubeq D E tabr sEQ /\ ebvsubin D E tabr sIN /\
       (!a. a IN D ==> (E a y <=>
          ?rc. rc IN D /\ eapply D E f delta rc /\
               ?pr. pr IN D /\ E pr c /\
               ?uu. uu IN D /\ ?vv. vv IN D /\ ?ru. ru IN D /\ ?rv. rv IN D /\
               ?iva. iva IN D /\ ?eva. eva IN D /\ ?ive. ive IN D /\
               eopair D E uu vv pr /\ eapply D E RG uu ru /\
               eapply D E RG vv rv /\ eopair D E ru rv rc /\
               ebvin D E B leq sEQ vv uu iva /\
                 ebveq D E B leq sIN uu vv eva /\
               eopair D E iva eva ive /\ eopair D E pr ive a))`;;

let HOLDS_EBVATTSTEP_ALT = prove
 (`!D (E:A->A->bool) v.
     model D E ZF_AX /\ valuation D v
     ==> (holds D E v ebvattstep_form <=>
          ebvattstep_alt D E (v 2) (v 3) (v 4) (v 5) (v 6) (v 0) (v 1))`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `!x. (v:num->A) x IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[valuation]; ALL_TAC] THEN
  REWRITE_TAC[ebvattstep_form; ebvattstep_alt; HOLDS_EX] THEN
  MATCH_MP_TAC EXISTS_AND_CONG THEN X_GEN_TAC `d:A` THEN DISCH_TAC THEN
  MATCH_MP_TAC EXISTS_AND_CONG THEN X_GEN_TAC `t:A` THEN DISCH_TAC THEN
  MATCH_MP_TAC EXISTS_AND_CONG THEN X_GEN_TAC `sq:A` THEN DISCH_TAC THEN
  MATCH_MP_TAC EXISTS_AND_CONG THEN X_GEN_TAC `si:A` THEN DISCH_TAC THEN
  REWRITE_TAC[HOLDS_AND] THEN
  ABBREV_TAC
   `stk = (10 |-> (si:A)) ((9 |-> sq) ((8 |-> t) ((7 |-> (d:A)) v)))` THEN
  SUBGOAL_THEN `valuation D (stk:num->A)` ASSUME_TAC THENL
   [EXPAND_TAC "stk" THEN
    REPEAT(MATCH_MP_TAC VALUATION_VALMOD THEN CONJ_TAC THENL
            [ALL_TAC; FIRST_ASSUM ACCEPT_TAC]) THEN FIRST_ASSUM ACCEPT_TAC;
    ALL_TAC] THEN
  ASM_SIMP_TAC[HOLDS_DOMAIN_FORM; HOLDS_ERANU_FORM; HOLDS_EBVSUBEQ_FORM;
               HOLDS_EBVSUBIN_FORM; HOLDS_ATTSTEP_MEMB] THEN
  EXPAND_TAC "stk" THEN REWRITE_TAC[VALMOD; ARITH_EQ]);;

let EDOMAIN_IN = prove
 (`!D (E:A->A->bool) g a. edomain D E g a ==> a IN D`,
  REWRITE_TAC[edomain] THEN SIMP_TAC[]);;
let ERANU_IN = prove
 (`!D (E:A->A->bool) g w. eranu D E g w ==> w IN D`,
  REWRITE_TAC[eranu] THEN SIMP_TAC[]);;
let EBVSUBEQ_IN = prove
 (`!D (E:A->A->bool) tab s. ebvsubeq D E tab s ==> s IN D`,
  REWRITE_TAC[ebvsubeq] THEN SIMP_TAC[]);;
let EBVSUBIN_IN = prove
 (`!D (E:A->A->bool) tab s. ebvsubin D E tab s ==> s IN D`,
  REWRITE_TAC[ebvsubin] THEN SIMP_TAC[]);;

let MEMB_RESHUF = prove
 (`!D (E:A->A->bool) B leq c RG f delta sEQ sIN a.
     (?rc. rc IN D /\ eapply D E f delta rc /\ ?pr. pr IN D /\ E pr c /\
        ?uu. uu IN D /\ ?vv. vv IN D /\ ?ru. ru IN D /\ ?rv. rv IN D /\
        ?iva. iva IN D /\ ?eva. eva IN D /\ ?ive. ive IN D /\
        eopair D E uu vv pr /\ eapply D E RG uu ru /\ eapply D E RG vv rv /\
        eopair D E ru rv rc /\ ebvin D E B leq sEQ vv uu iva /\
        ebveq D E B leq sIN uu vv eva /\ eopair D E iva eva ive /\
        eopair D E pr ive a)
   <=>
   (?rc. eapply D E f delta rc /\ ?pr. pr IN D /\ E pr c /\
         ?uu vv ru rv iva eva ive. uu IN D /\ vv IN D /\ ru IN D /\ rv IN D /\
         iva IN D /\ eva IN D /\ ive IN D /\
         eopair D E uu vv pr /\ eapply D E RG uu ru /\ eapply D E RG vv rv /\
         eopair D E ru rv rc /\ ebvin D E B leq sEQ vv uu iva /\
         ebveq D E B leq sIN uu vv eva /\ eopair D E iva eva ive /\
         eopair D E pr ive a)`,
  REPEAT GEN_TAC THEN EQ_TAC THEN STRIP_TAC THEN ASM_MESON_TAC[EOPAIR_IN]);;

let EBVATTSTEP_ALT_EQ = prove
 (`!D (E:A->A->bool) B leq c RG f g y.
     y IN D
     ==> (ebvattstep_alt D E B leq c RG f g y <=>
          ebvattstep D E B leq c RG f g y)`,
  REPEAT GEN_TAC THEN DISCH_TAC THEN
  REWRITE_TAC[ebvattstep_alt; ebvattstep] THEN
  REWRITE_TAC[MEMB_RESHUF] THEN
  EQ_TAC THENL
   [STRIP_TAC THEN
    MAP_EVERY EXISTS_TAC [`delta:A`; `tabr:A`; `sEQ:A`; `sIN:A`] THEN
    ASM_REWRITE_TAC[];
    STRIP_TAC THEN
    EXISTS_TAC `delta:A` THEN CONJ_TAC THENL
    [ASM_MESON_TAC[EDOMAIN_IN]; ALL_TAC] THEN
    EXISTS_TAC `tabr:A` THEN CONJ_TAC THENL
    [ASM_MESON_TAC[ERANU_IN]; ALL_TAC] THEN
    EXISTS_TAC `sEQ:A` THEN CONJ_TAC THENL
    [ASM_MESON_TAC[EBVSUBEQ_IN]; ALL_TAC] THEN
    EXISTS_TAC `sIN:A` THEN CONJ_TAC THENL
    [ASM_MESON_TAC[EBVSUBIN_IN]; ALL_TAC] THEN
    ASM_REWRITE_TAC[]]);;

let HOLDS_EBVATTSTEP_FORM = prove
 (`!D (E:A->A->bool) v.
     model D E ZF_AX /\ valuation D v
     ==> (holds D E v ebvattstep_form <=>
          ebvattstep D E (v 2) (v 3) (v 4) (v 5) (v 6) (v 0) (v 1))`,
  REPEAT STRIP_TAC THEN
  ASM_SIMP_TAC[HOLDS_EBVATTSTEP_ALT] THEN
  MATCH_MP_TAC EBVATTSTEP_ALT_EQ THEN
  ASM_MESON_TAC[valuation]);;

(* ===================================================================== *)
(* F4: the recursion function's GRAPH exists.                             *)
(* EBVATT_ERECRES_EXISTS applies ERECRES_EXISTS with q=ebvattstep_form*)
(* and a base valuation carrying B/leq/c/RG/f at slots 2-6: the SV hyp is *)
(* discharged via HOLDS_EBVATTSTEP_FORM + EBVATTSTEP_UNIQUE, the TOTAL hyp *)
(* via HOLDS_EBVATTSTEP_FORM + EBVATTSTEP_TOTAL, yielding r = the attempt  *)
(* graph { <b, erec-value-at-b> : b < a }.  (EBVATTSTEP_IN: value IN D.)   *)
(* ===================================================================== *)
let EBVATTSTEP_IN = prove
 (`!D (E:A->A->bool) B leq c RG f g y.
     ebvattstep D E B leq c RG f g y ==> y IN D`,
  REWRITE_TAC[ebvattstep] THEN REPEAT STRIP_TAC THEN ASM_REWRITE_TAC[]);;

let EBVATT_ERECRES_EXISTS = prove
 (`!D (E:A->A->bool) B leq c RG f a.
     model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\ c IN D /\
     RG IN D /\ eisfun D E RG /\ f IN D /\ eisfun D E f /\ eordinal D E a
     ==> ?v r. valuation D v /\
               v 2 = B /\ v 3 = leq /\ v 4 = c /\ v 5 = RG /\ v 6 = f /\
               erecres D E ebvattstep_form v a r`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `?v0:num->A. valuation D v0` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[VALUATION_EXISTS; MODEL_NONEMPTY]; ALL_TAC] THEN
  ABBREV_TAC
   `v = (2 |-> B)
    ((3 |-> leq) ((4 |-> c) ((5 |-> RG) ((6 |-> (f:A)) v0))))` THEN
  SUBGOAL_THEN `valuation D (v:num->A)` ASSUME_TAC THENL
   [EXPAND_TAC "v" THEN
    REPEAT(MATCH_MP_TAC VALUATION_VALMOD THEN CONJ_TAC THENL
            [ALL_TAC; FIRST_ASSUM ACCEPT_TAC]) THEN FIRST_ASSUM ACCEPT_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN
   `(v:num->A) 2 = B /\ v 3 = leq /\ v 4 = c /\ v 5 = RG /\ v 6 = f`
  STRIP_ASSUME_TAC THENL
   [EXPAND_TAC "v" THEN REWRITE_TAC[VALMOD; ARITH_EQ]; ALL_TAC] THEN
  MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `ebvattstep_form`; `v:num->A`;
    `a:A`] ERECRES_EXISTS) THEN
  ASM_REWRITE_TAC[] THEN
  ANTS_TAC THENL
   [CONJ_TAC THENL
     [MAP_EVERY X_GEN_TAC [`r:A`; `w:A`; `w':A`] THEN STRIP_TAC THEN
      SUBGOAL_THEN `valuation D ((1 |-> (w:A)) ((0 |-> (r:A)) v)) /\
                    valuation D ((1 |-> (w':A)) ((0 |-> (r:A)) v))`
      STRIP_ASSUME_TAC THENL
       [CONJ_TAC THEN
        REPEAT(MATCH_MP_TAC VALUATION_VALMOD THEN CONJ_TAC THENL
                [ALL_TAC; FIRST_ASSUM ACCEPT_TAC]) THEN FIRST_ASSUM ACCEPT_TAC;
        ALL_TAC] THEN
      SUBGOAL_THEN
       `!z:A. ((1 |-> z) ((0 |-> (r:A)) v)) 0 = r /\
        ((1 |-> z) ((0 |-> r) v)) 1 = z /\
              ((1 |-> z) ((0 |-> r) v)) 2 = B /\
                ((1 |-> z) ((0 |-> r) v)) 3 = leq /\
              ((1 |-> z) ((0 |-> r) v)) 4 = c /\
                ((1 |-> z) ((0 |-> r) v)) 5 = RG /\
              ((1 |-> z) ((0 |-> r) v)) 6 = f`
      ASSUME_TAC THENL
       [GEN_TAC THEN ASM_REWRITE_TAC[VALMOD; ARITH_EQ]; ALL_TAC] THEN
      SUBGOAL_THEN `ebvattstep D (E:A->A->bool) B leq c RG f r w /\
                    ebvattstep D E B leq c RG f r w'`
      STRIP_ASSUME_TAC THENL
       [CONJ_TAC THENL
         [MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`;
            `(1 |-> (w:A)) ((0 |-> (r:A)) v)`] HOLDS_EBVATTSTEP_FORM);
          MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`;
            `(1 |-> (w':A)) ((0 |-> (r:A)) v)`] HOLDS_EBVATTSTEP_FORM)] THEN
        ASM_REWRITE_TAC[] THEN DISCH_THEN(fun th -> REWRITE_TAC[GSYM th]) THEN
        FIRST_ASSUM ACCEPT_TAC;
        ALL_TAC] THEN
      MATCH_MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `B:A`; `leq:A`; `c:A`;
        `RG:A`; `f:A`; `r:A`; `w:A`; `w':A`] EBVATTSTEP_UNIQUE) THEN
      ASM_REWRITE_TAC[];
      X_GEN_TAC `x:A` THEN DISCH_TAC THEN
      SUBGOAL_THEN `?y:A. ebvattstep D E B leq c RG f x y`
        STRIP_ASSUME_TAC THENL
        [MATCH_MP_TAC EBVATTSTEP_TOTAL THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
      EXISTS_TAC `y:A` THEN
      SUBGOAL_THEN `(y:A) IN D` ASSUME_TAC THENL
       [ASM_MESON_TAC[EBVATTSTEP_IN]; ALL_TAC] THEN
      ASM_REWRITE_TAC[] THEN
      SUBGOAL_THEN `valuation D ((1 |-> (y:A)) ((0 |-> (x:A)) v))`
        ASSUME_TAC THENL
        [REPEAT(MATCH_MP_TAC VALUATION_VALMOD THEN CONJ_TAC THENL
                [ALL_TAC; FIRST_ASSUM ACCEPT_TAC]) THEN FIRST_ASSUM ACCEPT_TAC;
        ALL_TAC] THEN
      SUBGOAL_THEN
       `((1 |-> (y:A)) ((0 |-> (x:A)) v)) 0 = x /\
        ((1 |-> y) ((0 |-> x) v)) 1 = y /\
        ((1 |-> y) ((0 |-> x) v)) 2 = B /\ ((1 |-> y) ((0 |-> x) v)) 3 = leq /\
        ((1 |-> y) ((0 |-> x) v)) 4 = c /\ ((1 |-> y) ((0 |-> x) v)) 5 = RG /\
        ((1 |-> y) ((0 |-> x) v)) 6 = f`
      STRIP_ASSUME_TAC THENL
       [ASM_REWRITE_TAC[VALMOD; ARITH_EQ]; ALL_TAC] THEN
      MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`;
        `(1 |-> (y:A)) ((0 |-> (x:A)) v)`] HOLDS_EBVATTSTEP_FORM) THEN
      ASM_REWRITE_TAC[] THEN DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
      ASM_REWRITE_TAC[]];
    ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `r:A` ASSUME_TAC) THEN
  MAP_EVERY EXISTS_TAC [`v:num->A`; `r:A`] THEN ASM_REWRITE_TAC[]);;

(* ===================================================================== *)
(* F4: ENUM_CLEAN turns a functional graph f on ordinal                  *)
(* d into an eisfun graph fc = { <u, f-val u> : u IN d } (same eapply     *)
(* values).  Resolves the eisfun-f gap (EPRODK_ENUM's f exposes only its  *)
(* eapply-char, not eisfun's pair clause) by rebuilding fc as pairs via   *)
(* ZF_REPLACEMENT along ?? 1 (apply_form 3 0 1 && opair_form 0 1 2),       *)
(* mirroring EBNRANK_GRAPH_EXISTS.                                         *)
(* ===================================================================== *)
let ENUM_CLEAN = prove
 (`!D (E:A->A->bool) f d.
     model D E ZF_AX /\ d IN D /\ f IN D /\
     (!u w w'. u IN D /\ w IN D /\ w' IN D /\
               eapply D E f u w /\ eapply D E f u w' ==> w = w')
     ==> ?fc. fc IN D /\ eisfun D E fc /\
              (!u w. u IN D /\ w IN D
                     ==> (eapply D E fc u w <=> E u d /\ eapply D E f u w))`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "zf dD fD fun" THEN
  SUBGOAL_THEN `?v0:num->A. valuation D v0` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[VALUATION_EXISTS; MODEL_NONEMPTY]; ALL_TAC] THEN
  ABBREV_TAC `vf = (3 |-> (f:A)) v0` THEN
  SUBGOAL_THEN `valuation D (vf:num->A) /\ (vf:num->A) 3 = f`
  STRIP_ASSUME_TAC THENL
   [EXPAND_TAC "vf" THEN ASM_SIMP_TAC[VALUATION_VALMOD; VALMOD]; ALL_TAC] THEN
  SUBGOAL_THEN
   `!el ot:A. el IN D /\ ot IN D
      ==> (holds D E ((2 |-> ot) ((0 |-> el) vf))
             (?? 1 (apply_form 3 0 1 && opair_form 0 1 2)) <=>
           ?w. w IN D /\ eapply D E f el w /\ eopair D (E:A->A->bool) el w ot)`
  (LABEL_TAC "hrk") THENL
   [REPEAT GEN_TAC THEN STRIP_TAC THEN
    REWRITE_TAC[HOLDS_EX; HOLDS_AND] THEN
    MATCH_MP_TAC(MESON[]
     `(!w:A. P w <=> Q w) ==> ((?w:A. P w) <=> (?w:A. Q w))`) THEN
    X_GEN_TAC `w:A` THEN
    MATCH_MP_TAC(TAUT `(a ==> (p <=> q)) ==> ((a /\ p) <=> (a /\ q))`) THEN
    DISCH_TAC THEN
    SUBGOAL_THEN
     `valuation D ((1 |-> (w:A)) ((2 |-> (ot:A)) ((0 |-> (el:A)) vf)))`
    ASSUME_TAC THENL
     [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
      `(1 |-> (w:A)) ((2 |-> (ot:A)) ((0 |-> (el:A)) vf))`; `3`; `0`; `1`]
      HOLDS_APPLY_FORM) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
      `(1 |-> (w:A)) ((2 |-> (ot:A)) ((0 |-> (el:A)) vf))`; `0`; `1`; `2`]
      HOLDS_OPAIR_FORM) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    ASM_REWRITE_TAC[VALMOD; ARITH_EQ];
    ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`] ZF_REPLACEMENT) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(MP_TAC o SPECL
    [`?? 1 (apply_form 3 0 1 && opair_form 0 1 2)`;
     `0`; `2`; `vf:num->A`; `d:A`]) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[ARITH_EQ] THEN
    X_GEN_TAC `u:A` THEN STRIP_TAC THEN
    MATCH_MP_TAC REPL_SV_WITNESS THEN CONJ_TAC THENL
     [EXISTS_TAC `u:A` THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    MAP_EVERY X_GEN_TAC [`ot1:A`; `ot2:A`] THEN STRIP_TAC THEN
    SUBGOAL_THEN
     `?wa:A. wa IN D /\ eapply D E f u wa /\ eopair D (E:A->A->bool) u wa ot1`
    STRIP_ASSUME_TAC THENL
     [USE_THEN "hrk" (fun hr ->
        MP_TAC(EQ_MP (MATCH_MP hr (CONJ (ASSUME `(u:A) IN D`)
                                        (ASSUME `(ot1:A) IN D`)))
                     (ASSUME `holds D E ((2 |-> ot1) ((0 |-> (u:A)) vf))
                                (?? 1 (apply_form 3 0 1 &&
                                       opair_form 0 1 2))`))) THEN
      REWRITE_TAC[];
      ALL_TAC] THEN
    SUBGOAL_THEN
     `?wb:A. wb IN D /\ eapply D E f u wb /\ eopair D (E:A->A->bool) u wb ot2`
    STRIP_ASSUME_TAC THENL
     [USE_THEN "hrk" (fun hr ->
        MP_TAC(EQ_MP (MATCH_MP hr (CONJ (ASSUME `(u:A) IN D`)
                                        (ASSUME `(ot2:A) IN D`)))
                     (ASSUME `holds D E ((2 |-> ot2) ((0 |-> (u:A)) vf))
                                (?? 1 (apply_form 3 0 1 &&
                                       opair_form 0 1 2))`))) THEN
      REWRITE_TAC[];
      ALL_TAC] THEN
    SUBGOAL_THEN `(wa:A) = wb` SUBST_ALL_TAC THENL
     [REMOVE_THEN "fun" (MP_TAC o SPECL [`u:A`; `wa:A`; `wb:A`]) THEN
      ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `u:A`; `wb:A`; `ot1:A`; `ot2:A`]
      EOPAIR_UNIQUE) THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `fc:A` (CONJUNCTS_THEN2 ASSUME_TAC
    (LABEL_TAC "raw"))) THEN
  SUBGOAL_THEN
   `!z. z IN D
        ==> (E z fc <=>
             ?u w. u IN D /\ w IN D /\ E u d /\ eapply D E f u w /\
                   eopair D (E:A->A->bool) u w z)`
  (LABEL_TAC "fcc") THENL
   [X_GEN_TAC `z:A` THEN DISCH_TAC THEN
    USE_THEN "raw" (MP_TAC o SPEC `z:A`) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    EQ_TAC THENL
     [DISCH_THEN(X_CHOOSE_THEN `u:A` (CONJUNCTS_THEN2 ASSUME_TAC
        (CONJUNCTS_THEN2 ASSUME_TAC MP_TAC))) THEN
      USE_THEN "hrk" (MP_TAC o SPECL [`u:A`; `z:A`]) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
      DISCH_THEN(X_CHOOSE_THEN `w:A` STRIP_ASSUME_TAC) THEN
      MAP_EVERY EXISTS_TAC [`u:A`; `w:A`] THEN ASM_REWRITE_TAC[];
      DISCH_THEN(X_CHOOSE_THEN `u:A` (X_CHOOSE_THEN `w:A`
        STRIP_ASSUME_TAC)) THEN
      EXISTS_TAC `u:A` THEN ASM_REWRITE_TAC[] THEN
      USE_THEN "hrk" (MP_TAC o SPECL [`u:A`; `z:A`]) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
      EXISTS_TAC `w:A` THEN ASM_REWRITE_TAC[]];
    ALL_TAC] THEN
  EXISTS_TAC `fc:A` THEN REPEAT CONJ_TAC THENL
   [FIRST_ASSUM ACCEPT_TAC;
    REWRITE_TAC[eisfun] THEN REPEAT CONJ_TAC THENL
     [FIRST_ASSUM ACCEPT_TAC;
      X_GEN_TAC `z:A` THEN STRIP_TAC THEN
      SUBGOAL_THEN
       `?u w. u IN D /\ w IN D /\ E u d /\ eapply D E f u w /\
              eopair D (E:A->A->bool) u w z`
      STRIP_ASSUME_TAC THENL [ASM_MESON_TAC[]; ALL_TAC] THEN
      MAP_EVERY EXISTS_TAC [`u:A`; `w:A`] THEN ASM_REWRITE_TAC[];
      MAP_EVERY X_GEN_TAC [`u:A`; `w:A`; `w':A`; `z:A`; `z':A`] THEN
      STRIP_TAC THEN
      SUBGOAL_THEN `(z:A) IN D /\ (z':A) IN D` STRIP_ASSUME_TAC THENL
       [ASM_MESON_TAC[EOPAIR_IN]; ALL_TAC] THEN
      SUBGOAL_THEN
       `?u1 w1. u1 IN D /\ w1 IN D /\ E u1 d /\ eapply D E f u1 w1 /\
                eopair D (E:A->A->bool) u1 w1 z`
      STRIP_ASSUME_TAC THENL [ASM_MESON_TAC[]; ALL_TAC] THEN
      SUBGOAL_THEN
       `?u2 w2. u2 IN D /\ w2 IN D /\ E u2 d /\ eapply D E f u2 w2 /\
                eopair D (E:A->A->bool) u2 w2 z'`
      STRIP_ASSUME_TAC THENL [ASM_MESON_TAC[]; ALL_TAC] THEN
      SUBGOAL_THEN `(u:A) = u1 /\ (w:A) = w1` STRIP_ASSUME_TAC THENL
       [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `u:A`; `w:A`;
          `u1:A`; `w1:A`; `z:A`] EOPAIR_INJ) THEN ASM_REWRITE_TAC[];
        ALL_TAC] THEN
      SUBGOAL_THEN `(u:A) = u2 /\ (w':A) = w2` STRIP_ASSUME_TAC THENL
       [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `u:A`; `w':A`;
          `u2:A`; `w2:A`; `z':A`] EOPAIR_INJ) THEN ASM_REWRITE_TAC[];
        ALL_TAC] THEN
      REMOVE_THEN "fun" (MP_TAC o SPECL [`u1:A`; `w1:A`; `w2:A`]) THEN
      ASM_MESON_TAC[]];
    MAP_EVERY X_GEN_TAC [`u:A`; `w:A`] THEN STRIP_TAC THEN
    GEN_REWRITE_TAC (LAND_CONV) [eapply] THEN EQ_TAC THENL
     [DISCH_THEN(X_CHOOSE_THEN `z:A`
                 (CONJUNCTS_THEN2 ASSUME_TAC ASSUME_TAC)) THEN
      SUBGOAL_THEN `(z:A) IN D` ASSUME_TAC THENL
       [ASM_MESON_TAC[EOPAIR_IN]; ALL_TAC] THEN
      SUBGOAL_THEN
       `?u1 w1. u1 IN D /\ w1 IN D /\ E u1 d /\ eapply D E f u1 w1 /\
                eopair D (E:A->A->bool) u1 w1 z`
      STRIP_ASSUME_TAC THENL
       [USE_THEN "fcc" (fun fc ->
          MP_TAC(EQ_MP (MATCH_MP fc (ASSUME `(z:A) IN D`))
                       (ASSUME `(E:A->A->bool) z fc`))) THEN REWRITE_TAC[];
        ALL_TAC] THEN
      SUBGOAL_THEN `(u:A) = u1 /\ (w:A) = w1` STRIP_ASSUME_TAC THENL
       [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `u:A`; `w:A`;
          `u1:A`; `w1:A`; `z:A`] EOPAIR_INJ) THEN ASM_REWRITE_TAC[];
        ALL_TAC] THEN
      ASM_REWRITE_TAC[];
      STRIP_TAC THEN
      MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `u:A`; `w:A`]
             EOPAIR_EXISTS) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(X_CHOOSE_TAC `z:A`) THEN
      SUBGOAL_THEN `(z:A) IN D` ASSUME_TAC THENL
       [ASM_MESON_TAC[EOPAIR_IN]; ALL_TAC] THEN
      EXISTS_TAC `z:A` THEN ASM_REWRITE_TAC[] THEN
      USE_THEN "fcc"
        (fun fc -> REWRITE_TAC[MATCH_MP fc (ASSUME `(z:A) IN D`)]) THEN
        MAP_EVERY EXISTS_TAC [`u:A`; `w:A`] THEN ASM_REWRITE_TAC[]]]);;

(* ------------------------------------------------------------------ *)
(* EPRODK_ENUM_CLEAN: package EPRODK_ENUM's ordinal enumeration of the *)
(* rank-code product q with an eisfun witness f (via ENUM_CLEAN),      *)
(* ready to feed EBVATT_ERECRES_EXISTS in the e2e stage setup.         *)
(* ------------------------------------------------------------------ *)

let EPRODK_ENUM_CLEAN = prove
 (`!D (E:A->A->bool) k.
     model D E ZF_AX /\ eordinal D E k
     ==> ?q r d f.
           q IN D /\
           (!z. z IN D
                ==> (E z q <=>
                     ?a b. a IN D /\ b IN D /\ E a k /\ E b k /\
                           eopair D E a b z)) /\
           r IN D /\
           (!z z'. z IN D /\ z' IN D
                   ==> (erel D E r z z' <=>
                        E z q /\ E z' q /\ emlex D E z z')) /\
           d IN D /\ eordinal D E d /\
           f IN D /\ eisfun D E f /\
           (!w t. w IN D /\ t IN D
                  ==> (eapply D E f w t <=> E w d /\ eoenum D E q r w t)) /\
           (!z t. z IN D /\ t IN D /\ eapply D E f z t ==> E z d /\ E t q) /\
           (!z. z IN D /\ E z d ==> ?t. t IN D /\ E t q /\ eapply D E f z t) /\
           (!t. t IN D /\ E t q ==> ?z. z IN D /\ E z d /\ eapply D E f z t)`,
  REPEAT STRIP_TAC THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `k:A`] EPRODK_ENUM) THEN
  ASM_REWRITE_TAC[] THEN
  INTRO_TAC "@q r d f0. qIN qc rIN rc dIN dord fIN fac fval fontod finj \
             fontoq" THEN
  SUBGOAL_THEN
   `!z z'. z IN D /\ z' IN D /\ erel D (E:A->A->bool) r z z' ==>
    ~erel D E r z' z`
  (LABEL_TAC "rirr") THENL
   [MAP_EVERY X_GEN_TAC [`z:A`; `z':A`] THEN STRIP_TAC THEN
    SUBGOAL_THEN `E z q /\ E z' q /\ emlex D (E:A->A->bool) z z'`
    STRIP_ASSUME_TAC THENL
     [USE_THEN "rc" (fun rc ->
        MP_TAC(EQ_MP (MATCH_MP (SPECL [`z:A`; `z':A`] rc)
                               (CONJ (ASSUME `(z:A) IN D`)
                                (ASSUME `(z':A) IN D`)))
                     (ASSUME `erel D (E:A->A->bool) r z z'`))) THEN
      REWRITE_TAC[];
      ALL_TAC] THEN
    SUBGOAL_THEN
     `?a b. a IN D /\ b IN D /\ E a k /\ E b k /\
      eopair D (E:A->A->bool) a b z`
    STRIP_ASSUME_TAC THENL
     [USE_THEN "qc" (fun qc ->
        MP_TAC(EQ_MP (MATCH_MP (SPEC `z:A` qc) (ASSUME `(z:A) IN D`))
                     (ASSUME `(E:A->A->bool) z q`))) THEN REWRITE_TAC[];
      ALL_TAC] THEN
    SUBGOAL_THEN
     `?c g. c IN D /\ g IN D /\ E c k /\ E g k /\
      eopair D (E:A->A->bool) c g z'`
    STRIP_ASSUME_TAC THENL
     [USE_THEN "qc" (fun qc ->
        MP_TAC(EQ_MP (MATCH_MP (SPEC `z':A` qc) (ASSUME `(z':A) IN D`))
                     (ASSUME `(E:A->A->bool) z' q`))) THEN REWRITE_TAC[];
      ALL_TAC] THEN
    SUBGOAL_THEN
     `eordinal D E a /\ eordinal D E b /\ eordinal D E c /\
      eordinal D (E:A->A->bool) g`
    STRIP_ASSUME_TAC THENL
     [REPEAT CONJ_TAC THENL
       [MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`k:A`;`a:A`] EORDINAL_MEMBER);
        MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`k:A`;`b:A`] EORDINAL_MEMBER);
        MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`k:A`;`c:A`] EORDINAL_MEMBER);
        MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`k:A`;`g:A`]
               EORDINAL_MEMBER)] THEN
      DISCH_THEN MATCH_MP_TAC THEN ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `a:A`; `b:A`; `c:A`; `g:A`;
      `z:A`; `z':A`] EMLEX_ASYM) THEN
    ASM_REWRITE_TAC[] THEN DISCH_TAC THEN
    USE_THEN "rc" (fun rc ->
      REWRITE_TAC[MATCH_MP (SPECL [`z':A`; `z:A`] rc)
                          (CONJ (ASSUME `(z':A) IN D`)
                           (ASSUME `(z:A) IN D`))]) THEN
    ASM_REWRITE_TAC[] THEN DISCH_TAC THEN
    UNDISCH_TAC `~(emlex D (E:A->A->bool) z z' /\ emlex D E z' z)` THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!u w w'. u IN D /\ w IN D /\ w' IN D /\
             eapply D (E:A->A->bool) f0 u w /\ eapply D E f0 u w' ==> w = w'`
  (LABEL_TAC "f0fun") THENL
   [MAP_EVERY X_GEN_TAC [`u:A`; `w:A`; `w':A`] THEN STRIP_TAC THEN
    SUBGOAL_THEN `eoenum D E q r u w /\ eoenum D (E:A->A->bool) q r u w'`
    STRIP_ASSUME_TAC THENL
     [CONJ_TAC THENL
       [USE_THEN "fac" (fun fc ->
          MP_TAC(EQ_MP (MATCH_MP (SPECL [`u:A`; `w:A`] fc)
                                 (CONJ (ASSUME `(u:A) IN D`)
                                  (ASSUME `(w:A) IN D`)))
                       (ASSUME `eapply D (E:A->A->bool) f0 u w`)));
        USE_THEN "fac" (fun fc ->
          MP_TAC(EQ_MP (MATCH_MP (SPECL [`u:A`; `w':A`] fc)
                                 (CONJ (ASSUME `(u:A) IN D`)
                                  (ASSUME `(w':A) IN D`)))
                       (ASSUME `eapply D (E:A->A->bool) f0 u w'`)))] THEN
      REWRITE_TAC[] THEN STRIP_TAC THEN ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `q:A`; `r:A`; `u:A`; `w:A`;
      `w':A`] EOENUM_UNIQUE) THEN DISCH_THEN MATCH_MP_TAC THEN
    ASM_REWRITE_TAC[] THEN USE_THEN "rirr" ACCEPT_TAC;
    ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `f0:A`; `d:A`] ENUM_CLEAN) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[] THEN USE_THEN "f0fun" ACCEPT_TAC; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `f:A` (CONJUNCTS_THEN2 (LABEL_TAC "fcIN")
    (CONJUNCTS_THEN2 (LABEL_TAC "fceis") (LABEL_TAC "fcac")))) THEN
  SUBGOAL_THEN
   `!u w. u IN D /\ w IN D ==>
    (eapply D (E:A->A->bool) f u w <=> eapply D E f0 u w)`
  (LABEL_TAC "agree") THENL
   [MAP_EVERY X_GEN_TAC [`u:A`; `w:A`] THEN STRIP_TAC THEN
    USE_THEN "fcac" (fun fc ->
      REWRITE_TAC[MATCH_MP fc
                  (CONJ (ASSUME `(u:A) IN D`) (ASSUME `(w:A) IN D`))]) THEN
    EQ_TAC THENL [SIMP_TAC[]; ALL_TAC] THEN DISCH_TAC THEN
    ASM_REWRITE_TAC[] THEN
    USE_THEN "fval" (fun fv ->
      MP_TAC(MATCH_MP fv (CONJ (ASSUME `(u:A) IN D`)
                               (CONJ (ASSUME `(w:A) IN D`)
                                (ASSUME `eapply D (E:A->A->bool) f0 u
                                         w`))))) THEN
    SIMP_TAC[];
    ALL_TAC] THEN
  MAP_EVERY EXISTS_TAC [`q:A`; `r:A`; `d:A`; `f:A`] THEN
  ASM_REWRITE_TAC[] THEN REPEAT CONJ_TAC THENL
   [MAP_EVERY X_GEN_TAC [`w:A`; `t:A`] THEN STRIP_TAC THEN
    USE_THEN "agree" (fun a ->
      REWRITE_TAC[MATCH_MP a
                  (CONJ (ASSUME `(w:A) IN D`) (ASSUME `(t:A) IN D`))]) THEN
    USE_THEN "fac" (fun fc ->
      REWRITE_TAC[MATCH_MP fc
                  (CONJ (ASSUME `(w:A) IN D`) (ASSUME `(t:A) IN D`))]);
    MAP_EVERY X_GEN_TAC [`z:A`; `t:A`] THEN STRIP_TAC THEN
    USE_THEN "fval" MATCH_MP_TAC THEN ASM_REWRITE_TAC[] THEN
    UNDISCH_TAC `eapply D (E:A->A->bool) f z t` THEN
    USE_THEN "agree" (fun a ->
      REWRITE_TAC[MATCH_MP a
                  (CONJ (ASSUME `(z:A) IN D`) (ASSUME `(t:A) IN D`))]);
    X_GEN_TAC `z:A` THEN STRIP_TAC THEN
    USE_THEN "fontod" (fun fo ->
      MP_TAC(MATCH_MP fo
             (CONJ (ASSUME `(z:A) IN D`) (ASSUME `(E:A->A->bool) z d`)))) THEN
    DISCH_THEN(X_CHOOSE_THEN `t:A` STRIP_ASSUME_TAC) THEN
    EXISTS_TAC `t:A` THEN ASM_REWRITE_TAC[] THEN
    USE_THEN "agree" (fun a ->
      REWRITE_TAC[MATCH_MP a
                  (CONJ (ASSUME `(z:A) IN D`) (ASSUME `(t:A) IN D`))]) THEN
    ASM_REWRITE_TAC[];
    X_GEN_TAC `t:A` THEN STRIP_TAC THEN
    USE_THEN "fontoq" (fun fo ->
      MP_TAC(MATCH_MP fo
             (CONJ (ASSUME `(t:A) IN D`) (ASSUME `(E:A->A->bool) t q`)))) THEN
    DISCH_THEN(X_CHOOSE_THEN `z:A` STRIP_ASSUME_TAC) THEN
    EXISTS_TAC `z:A` THEN ASM_REWRITE_TAC[] THEN
    USE_THEN "agree" (fun a ->
      REWRITE_TAC[MATCH_MP a
                  (CONJ (ASSUME `(z:A) IN D`) (ASSUME `(t:A) IN D`))]) THEN
    ASM_REWRITE_TAC[]]);;

(* ================================================================== *)
(* F4: the erec bridge + tabr characterization                         *)
(* ================================================================== *)

(* EBVATTSTEP_SVTOTAL: the single-valued + total conditions for the    *)
(* ebvattstep_form recursion step (extracted from EBVATT_ERECRES_EXISTS *)
(* so EREC_EXISTS/ERECRES_EXISTS/EREC_EQUATION can all reuse them).     *)
let EBVATTSTEP_SVTOTAL = prove
 (`!D (E:A->A->bool) B leq c RG f v.
     model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\ c IN D /\
     RG IN D /\ eisfun D E RG /\ f IN D /\ eisfun D E f /\
     valuation D v /\ v 2 = B /\ v 3 = leq /\ v 4 = c /\ v 5 = RG /\ v 6 = f
     ==> (!r w w'. r IN D /\ w IN D /\ w' IN D /\
                   holds D E ((1 |-> w) ((0 |-> r) v)) ebvattstep_form /\
                   holds D E ((1 |-> w') ((0 |-> r) v)) ebvattstep_form
                   ==> w = w') /\
         (!x. x IN D
              ==> ?y. y IN D /\
                      holds D E ((1 |-> y) ((0 |-> x) v)) ebvattstep_form)`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN CONJ_TAC THENL
     [MAP_EVERY X_GEN_TAC [`r:A`; `w:A`; `w':A`] THEN STRIP_TAC THEN
      SUBGOAL_THEN `valuation D ((1 |-> (w:A)) ((0 |-> (r:A)) v)) /\
                    valuation D ((1 |-> (w':A)) ((0 |-> (r:A)) v))`
      STRIP_ASSUME_TAC THENL
       [CONJ_TAC THEN
        REPEAT(MATCH_MP_TAC VALUATION_VALMOD THEN CONJ_TAC THENL
                [ALL_TAC; FIRST_ASSUM ACCEPT_TAC]) THEN FIRST_ASSUM ACCEPT_TAC;
        ALL_TAC] THEN
      SUBGOAL_THEN
       `!z:A. ((1 |-> z) ((0 |-> (r:A)) v)) 0 = r /\
        ((1 |-> z) ((0 |-> r) v)) 1 = z /\
              ((1 |-> z) ((0 |-> r) v)) 2 = B /\
                ((1 |-> z) ((0 |-> r) v)) 3 = leq /\
              ((1 |-> z) ((0 |-> r) v)) 4 = c /\
                ((1 |-> z) ((0 |-> r) v)) 5 = RG /\
              ((1 |-> z) ((0 |-> r) v)) 6 = f`
      ASSUME_TAC THENL
       [GEN_TAC THEN ASM_REWRITE_TAC[VALMOD; ARITH_EQ]; ALL_TAC] THEN
      SUBGOAL_THEN `ebvattstep D (E:A->A->bool) B leq c RG f r w /\
                    ebvattstep D E B leq c RG f r w'`
      STRIP_ASSUME_TAC THENL
       [CONJ_TAC THENL
         [MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`;
            `(1 |-> (w:A)) ((0 |-> (r:A)) v)`] HOLDS_EBVATTSTEP_FORM);
          MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`;
            `(1 |-> (w':A)) ((0 |-> (r:A)) v)`] HOLDS_EBVATTSTEP_FORM)] THEN
        ASM_REWRITE_TAC[] THEN DISCH_THEN(fun th -> REWRITE_TAC[GSYM th]) THEN
        FIRST_ASSUM ACCEPT_TAC;
        ALL_TAC] THEN
      MATCH_MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `B:A`; `leq:A`; `c:A`;
        `RG:A`; `f:A`; `r:A`; `w:A`; `w':A`] EBVATTSTEP_UNIQUE) THEN
      ASM_REWRITE_TAC[];
      X_GEN_TAC `x:A` THEN DISCH_TAC THEN
      SUBGOAL_THEN `?y:A. ebvattstep D E B leq c RG f x y`
        STRIP_ASSUME_TAC THENL
        [MATCH_MP_TAC EBVATTSTEP_TOTAL THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
      EXISTS_TAC `y:A` THEN
      SUBGOAL_THEN `(y:A) IN D` ASSUME_TAC THENL
       [ASM_MESON_TAC[EBVATTSTEP_IN]; ALL_TAC] THEN
      ASM_REWRITE_TAC[] THEN
      SUBGOAL_THEN `valuation D ((1 |-> (y:A)) ((0 |-> (x:A)) v))`
        ASSUME_TAC THENL
        [REPEAT(MATCH_MP_TAC VALUATION_VALMOD THEN CONJ_TAC THENL
                [ALL_TAC; FIRST_ASSUM ACCEPT_TAC]) THEN FIRST_ASSUM ACCEPT_TAC;
        ALL_TAC] THEN
      SUBGOAL_THEN
       `((1 |-> (y:A)) ((0 |-> (x:A)) v)) 0 = x /\
        ((1 |-> y) ((0 |-> x) v)) 1 = y /\
        ((1 |-> y) ((0 |-> x) v)) 2 = B /\ ((1 |-> y) ((0 |-> x) v)) 3 = leq /\
        ((1 |-> y) ((0 |-> x) v)) 4 = c /\ ((1 |-> y) ((0 |-> x) v)) 5 = RG /\
        ((1 |-> y) ((0 |-> x) v)) 6 = f`
      STRIP_ASSUME_TAC THENL
       [ASM_REWRITE_TAC[VALMOD; ARITH_EQ]; ALL_TAC] THEN
      MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`;
        `(1 |-> (y:A)) ((0 |-> (x:A)) v)`] HOLDS_EBVATTSTEP_FORM) THEN
      ASM_REWRITE_TAC[] THEN DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
      ASM_REWRITE_TAC[]]);;

(* EBVATT_VALUE_AT: the erec bridge -- at each delta IN d the attempt   *)
(* value y = G(delta) IS the ebvattstep entry-set built from the        *)
(* restriction r_delta of the attempt below delta.                      *)
let EBVATT_VALUE_AT = prove
 (`!D (E:A->A->bool) B leq c RG f v d r_att delta.
     model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\ c IN D /\
     RG IN D /\ eisfun D E RG /\ f IN D /\ eisfun D E f /\
     valuation D v /\ v 2 = B /\ v 3 = leq /\ v 4 = c /\ v 5 = RG /\ v 6 = f /\
     eordinal D E d /\ erecres D E ebvattstep_form v d r_att /\
     delta IN D /\ E delta d
     ==> ?y r_delta.
           y IN D /\ eapply D E r_att delta y /\
           erecres D E ebvattstep_form v delta r_delta /\
           ebvattstep D E B leq c RG f r_delta y`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `B:A`; `leq:A`; `c:A`; `RG:A`;
    `f:A`; `v:num->A`] EBVATTSTEP_SVTOTAL) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "sv") (LABEL_TAC "tot")) THEN
  SUBGOAL_THEN `eordinal D (E:A->A->bool) delta` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `d:A`; `delta:A`]
      EORDINAL_MEMBER) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `?y:A. y IN D /\ erec D E ebvattstep_form v delta y`
  STRIP_ASSUME_TAC THENL
   [MATCH_MP_TAC EREC_EXISTS THEN REPEAT CONJ_TAC THENL
     [FIRST_ASSUM ACCEPT_TAC; FIRST_ASSUM ACCEPT_TAC;
      USE_THEN "sv" ACCEPT_TAC; USE_THEN "tot" ACCEPT_TAC;
      FIRST_ASSUM ACCEPT_TAC];
    ALL_TAC] THEN
  SUBGOAL_THEN `eapply D (E:A->A->bool) r_att delta y` ASSUME_TAC THENL
   [MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `ebvattstep_form`; `v:num->A`;
      `d:A`; `r_att:A`; `delta:A`; `y:A`] ERECRES_APPLY) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `?r_delta:A. erecres D E ebvattstep_form v delta r_delta`
  STRIP_ASSUME_TAC THENL
   [MATCH_MP_TAC ERECRES_EXISTS THEN REPEAT CONJ_TAC THENL
     [FIRST_ASSUM ACCEPT_TAC; FIRST_ASSUM ACCEPT_TAC;
      USE_THEN "sv" ACCEPT_TAC; USE_THEN "tot" ACCEPT_TAC;
      FIRST_ASSUM ACCEPT_TAC];
    ALL_TAC] THEN
  SUBGOAL_THEN `(r_delta:A) IN D` ASSUME_TAC THENL
   [FIRST_ASSUM(ACCEPT_TAC o CONJUNCT1 o REWRITE_RULE[erecres]); ALL_TAC] THEN
  SUBGOAL_THEN
   `holds D E ((1 |-> (y:A)) ((0 |-> (r_delta:A)) v)) ebvattstep_form`
  ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `ebvattstep_form`;
      `v:num->A`; `delta:A`; `y:A`; `r_delta:A`] EREC_EQUATION) THEN
    REPEAT CONJ_TAC THENL
     [FIRST_ASSUM ACCEPT_TAC; FIRST_ASSUM ACCEPT_TAC;
      USE_THEN "sv" ACCEPT_TAC; FIRST_ASSUM ACCEPT_TAC;
      FIRST_ASSUM ACCEPT_TAC; FIRST_ASSUM ACCEPT_TAC; FIRST_ASSUM ACCEPT_TAC];
    ALL_TAC] THEN
  SUBGOAL_THEN `valuation D ((1 |-> (y:A)) ((0 |-> (r_delta:A)) v))`
  ASSUME_TAC THENL
   [REPEAT(MATCH_MP_TAC VALUATION_VALMOD THEN CONJ_TAC THENL
            [ALL_TAC; FIRST_ASSUM ACCEPT_TAC]) THEN FIRST_ASSUM ACCEPT_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN
   `((1 |-> (y:A)) ((0 |-> (r_delta:A)) v)) 0 = r_delta /\
    ((1 |-> (y:A)) ((0 |-> (r_delta:A)) v)) 1 = y /\
    ((1 |-> (y:A)) ((0 |-> (r_delta:A)) v)) 2 = B /\
    ((1 |-> (y:A)) ((0 |-> (r_delta:A)) v)) 3 = leq /\
    ((1 |-> (y:A)) ((0 |-> (r_delta:A)) v)) 4 = c /\
    ((1 |-> (y:A)) ((0 |-> (r_delta:A)) v)) 5 = RG /\
    ((1 |-> (y:A)) ((0 |-> (r_delta:A)) v)) 6 = f`
  STRIP_ASSUME_TAC THENL
   [ASM_REWRITE_TAC[VALMOD; ARITH_EQ]; ALL_TAC] THEN
  SUBGOAL_THEN `ebvattstep D (E:A->A->bool) B leq c RG f r_delta y`
  ASSUME_TAC THENL
   [MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`;
      `(1 |-> (y:A)) ((0 |-> (r_delta:A)) v)`] HOLDS_EBVATTSTEP_FORM) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    ASM_REWRITE_TAC[] THEN DISCH_THEN(fun th -> REWRITE_TAC[GSYM th]) THEN
    FIRST_ASSUM ACCEPT_TAC;
    ALL_TAC] THEN
  MAP_EVERY EXISTS_TAC [`y:A`; `r_delta:A`] THEN ASM_REWRITE_TAC[]);;

(* TABR_MEM: the accumulated blob tabr = eranu r_att is exactly the     *)
(* union over b IN d of the recursion values G(b): E z tabr <=>         *)
(* ?b y. E b d /\ erec ebvattstep_form v b y /\ E z y.                   *)
let TABR_MEM = prove
 (`!D (E:A->A->bool) v d r_att tabr z.
     model D E ZF_AX /\ erecres D E ebvattstep_form v d r_att /\
     eranu D E r_att tabr /\ z IN D
     ==> (E z tabr <=>
          ?b y. b IN D /\ y IN D /\ E b d /\
                erec D E ebvattstep_form v b y /\ E z y)`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `(E:A->A->bool) z tabr <=> eranmem D E z r_att`
   (fun th -> REWRITE_TAC[th]) THENL
   [FIRST_ASSUM(MP_TAC o SPEC `z:A` o CONJUNCT2 o REWRITE_RULE[eranu]) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  REWRITE_TAC[eranmem] THEN EQ_TAC THENL
   [DISCH_THEN(X_CHOOSE_THEN `val:A` (X_CHOOSE_THEN `pr:A`
      (X_CHOOSE_THEN `ord:A` STRIP_ASSUME_TAC))) THEN
    FIRST_ASSUM(MP_TAC o SPEC `pr:A` o CONJUNCT2 o REWRITE_RULE[erecres]) THEN
    ASM_REWRITE_TAC[] THEN
    DISCH_THEN(X_CHOOSE_THEN `b:A` (X_CHOOSE_THEN `y:A` STRIP_ASSUME_TAC)) THEN
    MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `ord:A`; `val:A`; `b:A`; `y:A`;
      `pr:A`] EOPAIR_INJ) THEN ASM_REWRITE_TAC[] THEN STRIP_TAC THEN
    MAP_EVERY EXISTS_TAC [`b:A`; `y:A`] THEN ASM_REWRITE_TAC[] THEN
    ASM_MESON_TAC[];
    DISCH_THEN(X_CHOOSE_THEN `b:A` (X_CHOOSE_THEN `y:A` STRIP_ASSUME_TAC)) THEN
    MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `b:A`; `y:A`]
           EOPAIR_EXISTS) THEN
    ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `pr:A`) THEN
    SUBGOAL_THEN `(pr:A) IN D` ASSUME_TAC THENL
     [ASM_MESON_TAC[EOPAIR_IN]; ALL_TAC] THEN
    MAP_EVERY EXISTS_TAC [`y:A`; `pr:A`; `b:A`] THEN ASM_REWRITE_TAC[] THEN
    FIRST_ASSUM(MP_TAC o SPEC `pr:A` o CONJUNCT2 o REWRITE_RULE[erecres]) THEN
    ASM_REWRITE_TAC[] THEN DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    MAP_EVERY EXISTS_TAC [`b:A`; `y:A`] THEN ASM_REWRITE_TAC[]]);;

(* EBVSUBIN_APPLY / EBVSUBEQ_APPLY: reading the projected sub-tables    *)
(* via eapply.  eapply sIN pr ival <=> the entry <pr,<ival,eval>> lies  *)
(* in tab (for some eval); dually eapply sEQ pr eval picks the eval     *)
(* component.  The bridge from tabr-membership to the sIN/sEQ graphs.   *)
let EBVSUBIN_APPLY = prove
 (`!D (E:A->A->bool) tab s pr ival.
     model D E ZF_AX /\ ebvsubin D E tab s /\ pr IN D /\ ival IN D
     ==> (eapply D E s pr ival <=>
          ?eval inner u. eval IN D /\ inner IN D /\ u IN D /\
                         eopair D E ival eval inner /\
                         eopair D E pr inner u /\ E u tab)`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN
   `!z. z IN D
        ==> ((E:A->A->bool) z s <=>
             ?u. u IN D /\ E u tab /\
                 ?pr. pr IN D /\
                 ?inner. inner IN D /\
                 ?ival. ival IN D /\
                 ?eval. eval IN D /\
                        eopair D E pr inner u /\
                        eopair D E ival eval inner /\
                        eopair D E pr ival z)`
  (LABEL_TAC "sc") THENL
   [FIRST_ASSUM(ACCEPT_TAC o CONJUNCT2 o REWRITE_RULE[ebvsubin]); ALL_TAC] THEN
  REWRITE_TAC[eapply] THEN EQ_TAC THENL
   [DISCH_THEN(X_CHOOSE_THEN `z:A` STRIP_ASSUME_TAC) THEN
    SUBGOAL_THEN `(z:A) IN D` ASSUME_TAC THENL
     [ASM_MESON_TAC[EOPAIR_IN]; ALL_TAC] THEN
    USE_THEN "sc"(fun th ->
      MP_TAC(EQ_MP (MATCH_MP th (ASSUME `(z:A) IN D`))
                   (ASSUME `(E:A->A->bool) z s`))) THEN
    DISCH_THEN(X_CHOOSE_THEN `u:A` (CONJUNCTS_THEN2 ASSUME_TAC
     (CONJUNCTS_THEN2 ASSUME_TAC
      (X_CHOOSE_THEN `pr2:A` (CONJUNCTS_THEN2 ASSUME_TAC
       (X_CHOOSE_THEN `inner:A` (CONJUNCTS_THEN2 ASSUME_TAC
        (X_CHOOSE_THEN `ival2:A` (CONJUNCTS_THEN2 ASSUME_TAC
         (X_CHOOSE_THEN `eval2:A` STRIP_ASSUME_TAC)))))))))) THEN
    SUBGOAL_THEN `pr2:A = pr /\ ival2:A = ival`
    (CONJUNCTS_THEN SUBST_ALL_TAC) THENL
     [MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `pr2:A`; `ival2:A`; `pr:A`;
        `ival:A`; `z:A`] EOPAIR_INJ) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    MAP_EVERY EXISTS_TAC [`eval2:A`; `inner:A`; `u:A`] THEN ASM_REWRITE_TAC[];
    DISCH_THEN(X_CHOOSE_THEN `eval:A` (X_CHOOSE_THEN `inner:A`
      (X_CHOOSE_THEN `u:A` STRIP_ASSUME_TAC))) THEN
    MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `pr:A`; `ival:A`]
           EOPAIR_EXISTS) THEN
    ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `z:A`) THEN
    SUBGOAL_THEN `(z:A) IN D` ASSUME_TAC THENL
     [ASM_MESON_TAC[EOPAIR_IN]; ALL_TAC] THEN
    EXISTS_TAC `z:A` THEN ASM_REWRITE_TAC[] THEN
    USE_THEN "sc"(fun th ->
      REWRITE_TAC[MATCH_MP th (ASSUME `(z:A) IN D`)]) THEN
    EXISTS_TAC `u:A` THEN ASM_REWRITE_TAC[] THEN
    EXISTS_TAC `pr:A` THEN ASM_REWRITE_TAC[] THEN
    EXISTS_TAC `inner:A` THEN ASM_REWRITE_TAC[] THEN
    EXISTS_TAC `ival:A` THEN ASM_REWRITE_TAC[] THEN
    EXISTS_TAC `eval:A` THEN ASM_REWRITE_TAC[]]);;

let EBVSUBEQ_APPLY = prove
 (`!D (E:A->A->bool) tab s pr eval.
     model D E ZF_AX /\ ebvsubeq D E tab s /\ pr IN D /\ eval IN D
     ==> (eapply D E s pr eval <=>
          ?ival inner u. ival IN D /\ inner IN D /\ u IN D /\
                         eopair D E ival eval inner /\
                         eopair D E pr inner u /\ E u tab)`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN
   `!z. z IN D
        ==> ((E:A->A->bool) z s <=>
             ?u. u IN D /\ E u tab /\
                 ?pr. pr IN D /\
                 ?inner. inner IN D /\
                 ?ival. ival IN D /\
                 ?eval. eval IN D /\
                        eopair D E pr inner u /\
                        eopair D E ival eval inner /\
                        eopair D E pr eval z)`
  (LABEL_TAC "sc") THENL
   [FIRST_ASSUM(ACCEPT_TAC o CONJUNCT2 o REWRITE_RULE[ebvsubeq]); ALL_TAC] THEN
  REWRITE_TAC[eapply] THEN EQ_TAC THENL
   [DISCH_THEN(X_CHOOSE_THEN `z:A` STRIP_ASSUME_TAC) THEN
    SUBGOAL_THEN `(z:A) IN D` ASSUME_TAC THENL
     [ASM_MESON_TAC[EOPAIR_IN]; ALL_TAC] THEN
    USE_THEN "sc"(fun th ->
      MP_TAC(EQ_MP (MATCH_MP th (ASSUME `(z:A) IN D`))
                   (ASSUME `(E:A->A->bool) z s`))) THEN
    DISCH_THEN(X_CHOOSE_THEN `u:A` (CONJUNCTS_THEN2 ASSUME_TAC
     (CONJUNCTS_THEN2 ASSUME_TAC
      (X_CHOOSE_THEN `pr2:A` (CONJUNCTS_THEN2 ASSUME_TAC
       (X_CHOOSE_THEN `inner:A` (CONJUNCTS_THEN2 ASSUME_TAC
        (X_CHOOSE_THEN `ival2:A` (CONJUNCTS_THEN2 ASSUME_TAC
         (X_CHOOSE_THEN `eval2:A` STRIP_ASSUME_TAC)))))))))) THEN
    SUBGOAL_THEN `pr2:A = pr /\ eval2:A = eval`
    (CONJUNCTS_THEN SUBST_ALL_TAC) THENL
     [MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `pr2:A`; `eval2:A`; `pr:A`;
        `eval:A`; `z:A`] EOPAIR_INJ) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    MAP_EVERY EXISTS_TAC [`ival2:A`; `inner:A`; `u:A`] THEN ASM_REWRITE_TAC[];
    DISCH_THEN(X_CHOOSE_THEN `ival:A` (X_CHOOSE_THEN `inner:A`
      (X_CHOOSE_THEN `u:A` STRIP_ASSUME_TAC))) THEN
    MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `pr:A`; `eval:A`]
           EOPAIR_EXISTS) THEN
    ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `z:A`) THEN
    SUBGOAL_THEN `(z:A) IN D` ASSUME_TAC THENL
     [ASM_MESON_TAC[EOPAIR_IN]; ALL_TAC] THEN
    EXISTS_TAC `z:A` THEN ASM_REWRITE_TAC[] THEN
    USE_THEN "sc"(fun th ->
      REWRITE_TAC[MATCH_MP th (ASSUME `(z:A) IN D`)]) THEN
    EXISTS_TAC `u:A` THEN ASM_REWRITE_TAC[] THEN
    EXISTS_TAC `pr:A` THEN ASM_REWRITE_TAC[] THEN
    EXISTS_TAC `inner:A` THEN ASM_REWRITE_TAC[] THEN
    EXISTS_TAC `ival:A` THEN ASM_REWRITE_TAC[] THEN
    EXISTS_TAC `eval:A` THEN ASM_REWRITE_TAC[]]);;

(* ================================================================== *)
(* F4: entry-membership + recursion-domain + order-iso                 *)
(* converse -- the pieces the ebvatt reading-equations assemble from.  *)
(* ================================================================== *)

(* ERECRES_EDOMAIN: the recursion graph erecres q v a r has domain a.  *)
let ERECRES_EDOMAIN = prove
 (`!D (E:A->A->bool) q v a r.
     model D E ZF_AX /\ valuation D v /\
     (!rr w w'. rr IN D /\ w IN D /\ w' IN D /\
                holds D E ((1 |-> w) ((0 |-> rr) v)) q /\
                holds D E ((1 |-> w') ((0 |-> rr) v)) q ==> w = w') /\
     (!x. x IN D ==> ?w. w IN D /\ holds D E ((1 |-> w) ((0 |-> x) v)) q) /\
     eordinal D E a /\ erecres D E q v a r
     ==> edomain D E r a`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `(a:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[EORDINAL_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `(r:A) IN D` ASSUME_TAC THENL
   [FIRST_ASSUM(ACCEPT_TAC o CONJUNCT1 o REWRITE_RULE[erecres]); ALL_TAC] THEN
  REWRITE_TAC[edomain] THEN ASM_REWRITE_TAC[] THEN
  X_GEN_TAC `u:A` THEN DISCH_TAC THEN REWRITE_TAC[eindom] THEN EQ_TAC THENL
   [DISCH_TAC THEN
    SUBGOAL_THEN `eordinal D (E:A->A->bool) u` ASSUME_TAC THENL
     [MATCH_MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `a:A`; `u:A`]
        EORDINAL_MEMBER) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN `?w:A. w IN D /\ erec D E q v u w` STRIP_ASSUME_TAC THENL
     [MATCH_MP_TAC EREC_EXISTS THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    EXISTS_TAC `w:A` THEN ASM_REWRITE_TAC[] THEN
    MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `q:form`; `v:num->A`; `a:A`;
      `r:A`; `u:A`; `w:A`] ERECRES_APPLY) THEN ASM_REWRITE_TAC[];
    DISCH_THEN(X_CHOOSE_THEN `w:A` STRIP_ASSUME_TAC) THEN
    MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `q:form`; `v:num->A`; `a:A`;
      `r:A`; `u:A`; `w:A`] ERECRES_APPLY) THEN ASM_REWRITE_TAC[] THEN
    MESON_TAC[]]);;

(* EBVATTSTEP_ENTRY: ebvattstep membership BACKWARD -- given the rank   *)
(* data and iva=[[u in v]], eva=[[u=v]], the entry <pr,<iva,eva>> is    *)
(* in the stage value y.  Internal witnesses pinned via *_UNIQUE.       *)
let EBVATTSTEP_ENTRY = prove
 (`!D (E:A->A->bool) B leq c RG f g y delta tabr sEQ sIN
      u v pr ru rv rc iva eva ive e.
     model D E ZF_AX /\
     ebvattstep D E B leq c RG f g y /\
     edomain D E g delta /\ eranu D E g tabr /\
     ebvsubeq D E tabr sEQ /\ ebvsubin D E tabr sIN /\
     eapply D E f delta rc /\ pr IN D /\ E pr c /\
     u IN D /\ v IN D /\ ru IN D /\ rv IN D /\
     iva IN D /\ eva IN D /\ ive IN D /\ e IN D /\
     eopair D E u v pr /\ eapply D E RG u ru /\ eapply D E RG v rv /\
     eopair D E ru rv rc /\
     ebvin D E B leq sEQ v u iva /\ ebveq D E B leq sIN u v eva /\
     eopair D E iva eva ive /\ eopair D E pr ive e
     ==> E e y`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  UNDISCH_TAC `ebvattstep D (E:A->A->bool) B leq c RG f g y` THEN
  REWRITE_TAC[ebvattstep] THEN
  INTRO_TAC "@dl tb sq si. h ranutabr h2 h3 yD M" THEN
  SUBGOAL_THEN `dl:A = delta` SUBST_ALL_TAC THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `g:A`; `dl:A`; `delta:A`]
      EDOMAIN_UNIQUE) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `tb:A = tabr` SUBST_ALL_TAC THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `g:A`; `tb:A`; `tabr:A`]
      ERANU_UNIQUE) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `sq:A = sEQ` SUBST_ALL_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`; `E:A->A->bool`; `tabr:A`; `sq:A`; `sEQ:A`]
                 EBVSUBEQ_UNIQUE) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `si:A = sIN` SUBST_ALL_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`; `E:A->A->bool`; `tabr:A`; `si:A`; `sIN:A`]
                 EBVSUBIN_UNIQUE) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  USE_THEN "M"(fun th -> REWRITE_TAC[MATCH_MP th (ASSUME `(e:A) IN D`)]) THEN
  EXISTS_TAC `rc:A` THEN ASM_REWRITE_TAC[] THEN
  EXISTS_TAC `pr:A` THEN ASM_REWRITE_TAC[] THEN
  MAP_EVERY EXISTS_TAC
   [`u:A`; `v:A`; `ru:A`; `rv:A`; `iva:A`; `eva:A`; `ive:A`] THEN
  ASM_REWRITE_TAC[]);;

(* CONVERSE_ORDER: the f-order-iso converse -- emlex rc' rc ==> delta'  *)
(* < delta (referenced rank-codes are processed at earlier stages).     *)
let CONVERSE_ORDER = prove
 (`!D (E:A->A->bool) q rr d delta delta' rc rc'.
     model D E ZF_AX /\ q IN D /\ rr IN D /\ eordinal D E d /\
     (!u u'. u IN D /\ u' IN D /\ erel D E rr u u' ==> ~erel D E rr u' u) /\
     (!z z'. z IN D /\ z' IN D
             ==> (erel D E rr z z' <=> E z q /\ E z' q /\ emlex D E z z')) /\
     delta IN D /\ delta' IN D /\ E delta d /\ E delta' d /\
     eoenum D E q rr delta rc /\ eoenum D E q rr delta' rc' /\
     rc IN D /\ rc' IN D /\ ~(rc = q) /\ ~(rc' = q) /\
     E rc q /\ E rc' q /\ emlex D E rc' rc
     ==> E delta' delta`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `eordinal D (E:A->A->bool) delta` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `d:A`; `delta:A`]
      EORDINAL_MEMBER) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `eordinal D (E:A->A->bool) delta'` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `d:A`; `delta':A`]
      EORDINAL_MEMBER) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) rr rc' rc` ASSUME_TAC THENL
   [UNDISCH_TAC
     `!z z'. z IN D /\ z' IN D
             ==> (erel D (E:A->A->bool) rr z z' <=>
                  E z q /\ E z' q /\ emlex D E z z')` THEN
    DISCH_THEN(MP_TAC o SPECL [`rc':A`; `rc:A`]) THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `delta':A`; `delta:A`]
    EORDINAL_TRICHOTOMY) THEN
  ASM_REWRITE_TAC[] THEN STRIP_TAC THENL
   [UNDISCH_TAC `delta':A = delta` THEN DISCH_THEN SUBST_ALL_TAC THEN
    SUBGOAL_THEN `rc':A = rc` SUBST_ALL_TAC THENL
     [MATCH_MP_TAC(ISPECL
                   [`D:A->bool`; `E:A->A->bool`; `q:A`; `rr:A`; `delta:A`;
                    `rc':A`; `rc:A`] EOENUM_UNIQUE) THEN
      REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
      ALL_TAC] THEN
    UNDISCH_TAC
     `!u u'. u IN D /\ u' IN D /\ erel D (E:A->A->bool) rr u u'
             ==> ~erel D E rr u' u` THEN
    DISCH_THEN(MP_TAC o SPECL [`rc:A`; `rc:A`]) THEN ASM_REWRITE_TAC[];
    SUBGOAL_THEN `erel D (E:A->A->bool) rr rc rc'` ASSUME_TAC THENL
     [MATCH_MP_TAC(ISPECL
                   [`D:A->bool`; `E:A->A->bool`; `q:A`; `rr:A`; `delta:A`;
                    `delta':A`; `rc:A`; `rc':A`] EOENUM_ORDER) THEN
      REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
      ALL_TAC] THEN
    UNDISCH_TAC
     `!u u'. u IN D /\ u' IN D /\ erel D (E:A->A->bool) rr u u'
             ==> ~erel D E rr u' u` THEN
    DISCH_THEN(MP_TAC o SPECL [`rc:A`; `rc':A`]) THEN ASM_REWRITE_TAC[]]);;

(* PAIR_COVERAGE: every w x w pair <u,v0> is processed at some stage    *)
(* delta < d -- its rank-code rc=<bnrank u, bnrank v0> lands in q        *)
(* (EBVATT_RANKCODE_IN_Q) and f, being onto q, hits it: eapply f delta rc.*)
let PAIR_COVERAGE = prove
 (`!D (E:A->A->bool) B c kk yc w q d f RG cc u v0.
     model D E ZF_AX /\ B IN D /\ c IN D /\ eordinal D E c /\ w IN D /\
     yc IN D /\ ebnstage D E B c yc /\ esuc D E c kk /\
     (!z. z IN D /\ E z w ==> E z yc) /\
     q IN D /\
     (!z. z IN D
          ==> (E z q <=>
               ?a b. a IN D /\ b IN D /\ E a kk /\ E b kk /\
                 eopair D E a b z)) /\
     eordinal D E d /\
     (!t. t IN D /\ E t q ==> ?zz. zz IN D /\ E zz d /\ eapply D E f zz t) /\
     RG IN D /\
     (!x r. x IN D /\ E x w /\ ebnrank D E B x r ==> eapply D E RG x r) /\
     cc IN D /\ ecross D E w w cc /\
     u IN D /\ v0 IN D /\ E u w /\ E v0 w /\
     (!z. z IN D /\ E z w ==> bname D E B z)
     ==> ?pr ru rv rc delta.
           pr IN D /\ ru IN D /\ rv IN D /\ rc IN D /\ delta IN D /\
           eopair D E u v0 pr /\ E pr cc /\
           ebnrank D E B u ru /\ ebnrank D E B v0 rv /\
           eopair D E ru rv rc /\
           eapply D E RG u ru /\ eapply D E RG v0 rv /\
           E delta d /\ eapply D E f delta rc`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `bname D E B u /\ bname D (E:A->A->bool) B v0`
  STRIP_ASSUME_TAC THENL
   [UNDISCH_TAC `!z. z IN D /\ E z w ==> bname D (E:A->A->bool) B z` THEN
    DISCH_THEN(fun th -> CONJ_TAC THENL
      [MP_TAC(SPEC `u:A` th); MP_TAC(SPEC `v0:A` th)]) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `?ru:A. ru IN D /\ ebnrank D E B u ru` STRIP_ASSUME_TAC THENL
   [MATCH_MP_TAC EBNRANK_EXISTS THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `?rv:A. rv IN D /\ ebnrank D E B v0 rv` STRIP_ASSUME_TAC THENL
   [MATCH_MP_TAC EBNRANK_EXISTS THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `?rc:A. eopair D E ru rv rc` STRIP_ASSUME_TAC THENL
   [MATCH_MP_TAC EOPAIR_EXISTS THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(rc:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[EOPAIR_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `?pr:A. eopair D E u v0 pr` STRIP_ASSUME_TAC THENL
   [MATCH_MP_TAC EOPAIR_EXISTS THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(pr:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[EOPAIR_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `eapply D E RG u ru /\ eapply D (E:A->A->bool) RG v0 rv`
  STRIP_ASSUME_TAC THENL
   [UNDISCH_TAC
     `!x r. x IN D /\ E x w /\ ebnrank D (E:A->A->bool) B x r
            ==> eapply D E RG x r` THEN
    DISCH_THEN(fun th -> CONJ_TAC THENL
      [MP_TAC(SPECL [`u:A`; `ru:A`] th);
       MP_TAC(SPECL [`v0:A`; `rv:A`] th)]) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) u yc /\ E v0 yc` STRIP_ASSUME_TAC THENL
   [UNDISCH_TAC `!z. z IN D /\ (E:A->A->bool) z w ==> E z yc` THEN
    DISCH_THEN(fun th -> CONJ_TAC THENL
      [MP_TAC(SPEC `u:A` th); MP_TAC(SPEC `v0:A` th)]) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) pr cc` ASSUME_TAC THENL
   [UNDISCH_TAC `ecross D (E:A->A->bool) w w cc` THEN REWRITE_TAC[ecross] THEN
    DISCH_THEN(MP_TAC o SPEC `pr:A` o CONJUNCT2) THEN ASM_REWRITE_TAC[] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    MAP_EVERY EXISTS_TAC [`u:A`; `v0:A`] THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) rc q` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `B:A`; `c:A`; `kk:A`;
      `yc:A`; `u:A`; `v0:A`; `ru:A`; `rv:A`; `rc:A`; `q:A`]
        EBVATT_RANKCODE_IN_Q) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `?delta:A. delta IN D /\ E delta d /\ eapply D E f delta rc`
  STRIP_ASSUME_TAC THENL
   [UNDISCH_TAC
     `!t. t IN D /\ E t q
          ==> ?zz. zz IN D /\ E zz d /\ eapply D (E:A->A->bool) f zz t` THEN
    DISCH_THEN(MP_TAC o SPEC `rc:A`) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MAP_EVERY EXISTS_TAC [`pr:A`; `ru:A`; `rv:A`; `rc:A`; `delta:A`] THEN
  ASM_REWRITE_TAC[]);;

(* EBVATTSTEP_ENTRY_FWD: the ebvattstep membership FORWARD -- an entry   *)
(* e in the stage value y decomposes as <pr,<iva,eva>>, pr=<uu,vv>,      *)
(* with rank-code rc = f(edomain g).  (Mirror of EBVATTSTEP_ENTRY; used  *)
(* to recover a referenced entry's stage-index for the 3c congruence.)   *)
let EBVATTSTEP_ENTRY_FWD = prove
 (`!D (E:A->A->bool) B leq c RG f g y e.
     ebvattstep D E B leq c RG f g y /\ e IN D /\ E e y
     ==> ?delta tabr sEQ sIN rc pr uu vv ru rv iva eva ive.
           edomain D E g delta /\ eranu D E g tabr /\
           ebvsubeq D E tabr sEQ /\ ebvsubin D E tabr sIN /\
           eapply D E f delta rc /\ pr IN D /\ E pr c /\
           uu IN D /\ vv IN D /\ ru IN D /\ rv IN D /\
           iva IN D /\ eva IN D /\ ive IN D /\
           eopair D E uu vv pr /\ eapply D E RG uu ru /\ eapply D E RG vv rv /\
           eopair D E ru rv rc /\
           ebvin D E B leq sEQ vv uu iva /\ ebveq D E B leq sIN uu vv eva /\
           eopair D E iva eva ive /\ eopair D E pr ive e`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  UNDISCH_TAC `ebvattstep D (E:A->A->bool) B leq c RG f g y` THEN
  REWRITE_TAC[ebvattstep] THEN
  INTRO_TAC "@dl tb sq si. h ranutabr h2 h3 yD M" THEN
  USE_THEN "M"(fun th ->
    MP_TAC(EQ_MP (MATCH_MP th (ASSUME `(e:A) IN D`))
                 (ASSUME `(E:A->A->bool) e y`))) THEN
  DISCH_THEN(X_CHOOSE_THEN `rc:A` (CONJUNCTS_THEN2 ASSUME_TAC
    (X_CHOOSE_THEN `pr:A`
     (CONJUNCTS_THEN2 ASSUME_TAC (CONJUNCTS_THEN2 ASSUME_TAC
                                  (X_CHOOSE_THEN `uu:A`
                                   (X_CHOOSE_THEN `vv:A` (X_CHOOSE_THEN `ru:A`
      (X_CHOOSE_THEN `rv:A` (X_CHOOSE_THEN `iva:A` (X_CHOOSE_THEN `eva:A`
       (X_CHOOSE_THEN `ive:A` STRIP_ASSUME_TAC)))))))))))) THEN
  MAP_EVERY EXISTS_TAC
   [`dl:A`; `tb:A`; `sq:A`; `si:A`; `rc:A`; `pr:A`; `uu:A`; `vv:A`; `ru:A`;
    `rv:A`; `iva:A`; `eva:A`; `ive:A`] THEN
  ASM_REWRITE_TAC[]);;

(* ================================================================== *)
(* F4: congruence prerequisites: extended stage-tables (full           *)
(* enum spec incl rr-char/fval/fontod), rr-irreflexivity, and the      *)
(* easy half of the entry-agreement (eranu r_delta entries IN tabr).   *)
(* ================================================================== *)

(* RR_IRREFL: the EPRODK order-relation rr is irreflexive (from its     *)
(* char + q-char decomposing codes into ordinal pairs + EMLEX_ASYM).    *)
let RR_IRREFL = prove
 (`!D (E:A->A->bool) q rr kk.
     model D E ZF_AX /\ eordinal D E kk /\ q IN D /\ rr IN D /\
     (!z. z IN D
          ==> (E z q <=>
               ?a b. a IN D /\ b IN D /\ E a kk /\ E b kk /\
                 eopair D E a b z)) /\
     (!z z'. z IN D /\ z' IN D
             ==> (erel D E rr z z' <=> E z q /\ E z' q /\ emlex D E z z'))
     ==> (!u u'. u IN D /\ u' IN D /\ erel D E rr u u' ==> ~erel D E rr u' u)`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "zf ordkk qD rrD qc rc" THEN
  MAP_EVERY X_GEN_TAC [`z:A`; `z':A`] THEN STRIP_TAC THEN
  SUBGOAL_THEN `E z q /\ E z' q /\ emlex D (E:A->A->bool) z z'`
  STRIP_ASSUME_TAC THENL
   [USE_THEN "rc" (fun rc ->
      MP_TAC(EQ_MP (MATCH_MP (SPECL [`z:A`; `z':A`] rc)
                             (CONJ (ASSUME `(z:A) IN D`)
                              (ASSUME `(z':A) IN D`)))
                   (ASSUME `erel D (E:A->A->bool) rr z z'`))) THEN
    REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `?a b. a IN D /\ b IN D /\ E a kk /\ E b kk /\
    eopair D (E:A->A->bool) a b z`
  STRIP_ASSUME_TAC THENL
   [USE_THEN "qc" (fun qc ->
      MP_TAC(EQ_MP (MATCH_MP (SPEC `z:A` qc) (ASSUME `(z:A) IN D`))
                   (ASSUME `(E:A->A->bool) z q`))) THEN REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `?c g. c IN D /\ g IN D /\ E c kk /\ E g kk /\
    eopair D (E:A->A->bool) c g z'`
  STRIP_ASSUME_TAC THENL
   [USE_THEN "qc" (fun qc ->
      MP_TAC(EQ_MP (MATCH_MP (SPEC `z':A` qc) (ASSUME `(z':A) IN D`))
                   (ASSUME `(E:A->A->bool) z' q`))) THEN REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `eordinal D E a /\ eordinal D E b /\ eordinal D E c /\
    eordinal D (E:A->A->bool) g`
  STRIP_ASSUME_TAC THENL
   [REPEAT CONJ_TAC THENL
     [MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`kk:A`;`a:A`] EORDINAL_MEMBER);
      MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`kk:A`;`b:A`] EORDINAL_MEMBER);
      MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`kk:A`;`c:A`] EORDINAL_MEMBER);
      MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`kk:A`;`g:A`]
             EORDINAL_MEMBER)] THEN
    DISCH_THEN MATCH_MP_TAC THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `a:A`; `b:A`; `c:A`; `g:A`;
    `z:A`; `z':A`] EMLEX_ASYM) THEN
  ASM_REWRITE_TAC[] THEN DISCH_TAC THEN
  USE_THEN "rc" (fun rc ->
    REWRITE_TAC[MATCH_MP (SPECL [`z':A`; `z:A`] rc)
                        (CONJ (ASSUME `(z':A) IN D`)
                         (ASSUME `(z:A) IN D`))]) THEN
  ASM_REWRITE_TAC[] THEN DISCH_TAC THEN
  UNDISCH_TAC `~(emlex D (E:A->A->bool) z z' /\ emlex D E z' z)` THEN
  ASM_REWRITE_TAC[]);;

(* ERANU_DELTA_IN_TABR: entries of the below-delta accumulation eranu   *)
(* r_delta are in the full tabr=eranu r_att (TABR_MEM both + ordinal    *)
(* transitivity b<delta<d).  The easy half of the 3c agreement.         *)
let ERANU_DELTA_IN_TABR = prove
 (`!D (E:A->A->bool) v d delta r_att tabr r_delta tabr_d z.
     model D E ZF_AX /\ eordinal D E d /\ delta IN D /\ E delta d /\
     erecres D E ebvattstep_form v d r_att /\ eranu D E r_att tabr /\
     erecres D E ebvattstep_form v delta r_delta /\
     eranu D E r_delta tabr_d /\
     z IN D /\ E z tabr_d
     ==> E z tabr`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  MP_TAC(ISPECL
         [`D:A->bool`; `E:A->A->bool`; `v:num->A`; `delta:A`; `r_delta:A`;
          `tabr_d:A`; `z:A`] TABR_MEM) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `b:A` (X_CHOOSE_THEN `Y:A` STRIP_ASSUME_TAC)) THEN
  SUBGOAL_THEN `(E:A->A->bool) b d` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `d:A`; `b:A`; `delta:A`]
      EORDINAL_TRANS_E) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `v:num->A`; `d:A`; `r_att:A`;
    `tabr:A`; `z:A`] TABR_MEM) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  MAP_EVERY EXISTS_TAC [`b:A`; `Y:A`] THEN ASM_REWRITE_TAC[]);;

(* ================================================================== *)
(* STAGE_RANKCODE: from an entry z=<pr,<ival,eval>> (pr=<u,y>) in a     *)
(* stage value Y = ebvattstep..g Y, recover eapply f (edomain g)        *)
(* <bnrank u, bnrank y> -- i.e. the stage index enumerates the entry's  *)
(* rank-code.  Composes EBVATTSTEP_ENTRY_FWD + ecross-decompose +       *)
(* RG-lookup + EAPPLY_UNIQUE/EOPAIR_UNIQUE matching.  The reusable core  *)
(* of the 3c congruence's hard direction and of 3a eisfun.              *)
(* ================================================================== *)

let STAGE_RANKCODE = prove
 (`!D (E:A->A->bool) B leq cc RG f g Y w u y pr ive ru ry rc z.
     model D E ZF_AX /\ B IN D /\ RG IN D /\ eisfun D E RG /\ w IN D /\
     (!x r. x IN D /\ E x w /\ ebnrank D E B x r ==> eapply D E RG x r) /\
     ecross D E w w cc /\
     ebvattstep D E B leq cc RG f g Y /\
     u IN D /\ y IN D /\ pr IN D /\ ive IN D /\ ru IN D /\
       ry IN D /\ rc IN D /\
     z IN D /\
     ebnrank D E B u ru /\ ebnrank D E B y ry /\
     eopair D E u y pr /\ eopair D E pr ive z /\ eopair D E ru ry rc /\
     E z Y
     ==> ?delta. edomain D E g delta /\ eapply D E f delta rc`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `B:A`; `leq:A`; `cc:A`; `RG:A`;
    `f:A`; `g:A`; `Y:A`; `z:A`] EBVATTSTEP_ENTRY_FWD) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `dd:A` (X_CHOOSE_THEN `tt:A` (X_CHOOSE_THEN `ss:A`
    (X_CHOOSE_THEN `si:A` (X_CHOOSE_THEN `cf:A` (X_CHOOSE_THEN `pf:A`
     (X_CHOOSE_THEN `a1:A` (X_CHOOSE_THEN `a2:A` (X_CHOOSE_THEN `r1:A`
      (X_CHOOSE_THEN `r2:A` (X_CHOOSE_THEN `i1:A` (X_CHOOSE_THEN `i2:A`
       (X_CHOOSE_THEN `i3:A` STRIP_ASSUME_TAC))))))))))))) THEN
  SUBGOAL_THEN `pf:A = pr /\ i3:A = ive` (CONJUNCTS_THEN SUBST_ALL_TAC) THENL
   [MP_TAC(ISPECL
           [`D:A->bool`; `E:A->A->bool`; `pf:A`; `i3:A`; `pr:A`; `ive:A`;
            `z:A`] EOPAIR_INJ) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `a1:A = u /\ a2:A = y` (CONJUNCTS_THEN SUBST_ALL_TAC) THENL
   [MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `a1:A`; `a2:A`; `u:A`; `y:A`;
      `pr:A`] EOPAIR_INJ) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) u w /\ E y w` STRIP_ASSUME_TAC THENL
   [UNDISCH_TAC `ecross D (E:A->A->bool) w w cc` THEN REWRITE_TAC[ecross] THEN
    DISCH_THEN(MP_TAC o SPEC `pr:A` o CONJUNCT2) THEN ASM_REWRITE_TAC[] THEN
    DISCH_THEN(X_CHOOSE_THEN `aa:A`
               (X_CHOOSE_THEN `bb:A` STRIP_ASSUME_TAC)) THEN
    SUBGOAL_THEN `aa:A = u /\ bb:A = y` (CONJUNCTS_THEN SUBST_ALL_TAC) THENL
     [MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `aa:A`; `bb:A`; `u:A`; `y:A`;
        `pr:A`] EOPAIR_INJ) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `eapply D E RG u ru /\ eapply D (E:A->A->bool) RG y ry`
  STRIP_ASSUME_TAC THENL
   [UNDISCH_TAC
     `!x r. x IN D /\ E x w /\ ebnrank D (E:A->A->bool) B x r
            ==> eapply D E RG x r` THEN
    DISCH_THEN(fun th -> CONJ_TAC THENL
      [MP_TAC(SPECL [`u:A`; `ru:A`] th);
       MP_TAC(SPECL [`y:A`; `ry:A`] th)]) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `r1:A = ru` SUBST_ALL_TAC THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `RG:A`; `u:A`; `r1:A`;
      `ru:A`] EAPPLY_UNIQUE) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `r2:A = ry` SUBST_ALL_TAC THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `RG:A`; `y:A`; `r2:A`;
      `ry:A`] EAPPLY_UNIQUE) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `cf:A = rc` SUBST_ALL_TAC THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `ru:A`; `ry:A`; `cf:A`;
      `rc:A`] EOPAIR_UNIQUE) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  EXISTS_TAC `dd:A` THEN ASM_REWRITE_TAC[]);;

(* ENTRY_TABR_IN_DELTA: the HARD half of the 3c congruence agreement.  *)
(* An entry z=<pr,ive> (pr=<u,y>, bnrank y < rv) that is in the full    *)
(* tabr = eranu r_att is already in the below-delta accumulation        *)
(* tabr_d = eranu r_delta.  Chain: TABR_MEM(r_att) fwd -> EBVATT_VALUE_AT*)
(* -> EREC_UNIQUE -> STAGE_RANKCODE (f(b)=rankcode) -> ERECRES_EDOMAIN   *)
(* -> EMLEX_DEC_A -> CONVERSE_ORDER (b < delta) -> TABR_MEM(r_delta) bwd.*)
let ENTRY_TABR_IN_DELTA = prove
 (`!D (E:A->A->bool) B leq cc RG f v d r_att tabr delta r_delta
   tabr_d q rr kk w
     u y pr ive ru ry rv rc rcd z.
     model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\ cc IN D /\
     RG IN D /\ eisfun D E RG /\ f IN D /\ eisfun D E f /\
     valuation D v /\ v 2 = B /\ v 3 = leq /\ v 4 = cc /\
       v 5 = RG /\ v 6 = f /\
     w IN D /\
     (!x r. x IN D /\ E x w /\ ebnrank D E B x r ==> eapply D E RG x r) /\
     ecross D E w w cc /\
     eordinal D E d /\ erecres D E ebvattstep_form v d r_att /\
     eranu D E r_att tabr /\
     delta IN D /\ E delta d /\ erecres D E ebvattstep_form v delta r_delta /\
     eranu D E r_delta tabr_d /\
     q IN D /\ rr IN D /\ eordinal D E kk /\
     (!zz. zz IN D
           ==> (E zz q <=>
                ?a b. a IN D /\ b IN D /\ E a kk /\ E b kk /\
                  eopair D E a b zz)) /\
     (!z1 z2. z1 IN D /\ z2 IN D
              ==> (erel D E rr z1 z2 <=> E z1 q /\ E z2 q /\
                   emlex D E z1 z2)) /\
     (!zz t. zz IN D /\ t IN D
             ==> (eapply D E f zz t <=> E zz d /\ eoenum D E q rr zz t)) /\
     (!z1 t. z1 IN D /\ t IN D /\ eapply D E f z1 t ==> E z1 d /\ E t q) /\
     (!r1 w1 w2. r1 IN D /\ w1 IN D /\ w2 IN D /\
                 holds D E ((1 |-> w1) ((0 |-> r1) v)) ebvattstep_form /\
                 holds D E ((1 |-> w2) ((0 |-> r1) v))
                   ebvattstep_form ==> w1 = w2) /\
     (!x. x IN D ==> ?yy. yy IN D /\
                          holds D E ((1 |-> yy) ((0 |-> x) v))
                            ebvattstep_form) /\
     u IN D /\ y IN D /\ pr IN D /\ ive IN D /\ ru IN D /\
       ry IN D /\ rv IN D /\
     rc IN D /\ rcd IN D /\ z IN D /\
     ebnrank D E B u ru /\ ebnrank D E B y ry /\ E ry rv /\
     eordinal D E ru /\ eordinal D E ry /\ eordinal D E rv /\
     eopair D E u y pr /\ eopair D E pr ive z /\ eopair D E ru ry rc /\
     eopair D E ru rv rcd /\ eapply D E f delta rcd /\
     E z tabr
     ==> E z tabr_d`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN
   `!u1 u2. u1 IN D /\ u2 IN D /\ erel D (E:A->A->bool) rr u1 u2
            ==> ~erel D E rr u2 u1` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `q:A`; `rr:A`; `kk:A`]
      RR_IRREFL) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `v:num->A`; `d:A`; `r_att:A`;
    `tabr:A`; `z:A`] TABR_MEM) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `b:A` (X_CHOOSE_THEN `Yv:A` STRIP_ASSUME_TAC)) THEN
  MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `B:A`; `leq:A`; `cc:A`; `RG:A`;
    `f:A`; `v:num->A`; `d:A`; `r_att:A`; `b:A`] EBVATT_VALUE_AT) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `Yb:A` (X_CHOOSE_THEN `rb:A` STRIP_ASSUME_TAC)) THEN
  SUBGOAL_THEN `Yv:A = Yb` SUBST_ALL_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`; `E:A->A->bool`; `ebvattstep_form`; `v:num->A`;
                  `b:A`; `Yv:A`; `Yb:A`] EREC_UNIQUE) THEN
            ASM_REWRITE_TAC[] THEN
            MP_TAC(ISPECL
                   [`D:A->bool`; `E:A->A->bool`; `ebvattstep_form`; `v:num->A`;
                    `d:A`; `r_att:A`; `b:A`; `Yb:A`] ERECRES_APPLY) THEN
            ASM_REWRITE_TAC[];
            ALL_TAC] THEN
  MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `B:A`; `leq:A`; `cc:A`; `RG:A`;
    `f:A`; `rb:A`; `Yb:A`; `w:A`; `u:A`; `y:A`; `pr:A`; `ive:A`;
    `ru:A`; `ry:A`;
    `rc:A`; `z:A`] STAGE_RANKCODE) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_THEN `db:A` STRIP_ASSUME_TAC) THEN
  SUBGOAL_THEN `eordinal D (E:A->A->bool) b` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `d:A`; `b:A`]
      EORDINAL_MEMBER) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `edomain D (E:A->A->bool) rb b` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`; `E:A->A->bool`; `ebvattstep_form`; `v:num->A`;
                  `b:A`; `rb:A`] ERECRES_EDOMAIN) THEN ASM_REWRITE_TAC[];
            ALL_TAC] THEN
  SUBGOAL_THEN `db:A = b` SUBST_ALL_TAC THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `rb:A`; `db:A`; `b:A`]
      EDOMAIN_UNIQUE) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN
   `eoenum D E q rr b rc /\ eoenum D (E:A->A->bool) q rr delta rcd`
  STRIP_ASSUME_TAC THENL
   [UNDISCH_TAC
     `!zz t. zz IN D /\ t IN D
             ==> (eapply D (E:A->A->bool) f zz t <=>
                  E zz d /\ eoenum D E q rr zz t)` THEN
    DISCH_THEN(fun th -> CONJ_TAC THENL
      [MP_TAC(SPECL [`b:A`; `rc:A`] th);
       MP_TAC(SPECL [`delta:A`; `rcd:A`] th)]) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) rc q /\ E rcd q` STRIP_ASSUME_TAC THENL
   [UNDISCH_TAC
     `!z1 t. z1 IN D /\ t IN D /\ eapply D (E:A->A->bool) f z1 t
             ==> E z1 d /\ E t q` THEN
    DISCH_THEN(fun th -> CONJ_TAC THENL
      [MP_TAC(SPECL [`b:A`; `rc:A`] th);
       MP_TAC(SPECL [`delta:A`; `rcd:A`] th)]) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `~(rc:A = q) /\ ~(rcd:A = q)` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[E_IRREFL]; ALL_TAC] THEN
  SUBGOAL_THEN `emlex D (E:A->A->bool) rc rcd` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `ru:A`; `ry:A`; `rv:A`;
      `rc:A`; `rcd:A`] EMLEX_DEC_A) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) b delta` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `q:A`; `rr:A`; `d:A`;
      `delta:A`; `b:A`; `rcd:A`; `rc:A`] CONVERSE_ORDER) THEN
    REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  MP_TAC(ISPECL
         [`D:A->bool`; `E:A->A->bool`; `v:num->A`; `delta:A`; `r_delta:A`;
          `tabr_d:A`; `z:A`] TABR_MEM) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  MAP_EVERY EXISTS_TAC [`b:A`; `Yb:A`] THEN ASM_REWRITE_TAC[]);;

(* ENTRY_TABR_IFF: the full 3c congruence agreement -- for an entry z    *)
(* keyed by pr=<u,y> with bnrank y < rv, membership in the below-delta   *)
(* table tabr_d is equivalent to membership in the full tabr.  Combines  *)
(* ERANU_DELTA_IN_TABR (==>) and ENTRY_TABR_IN_DELTA (<==).  This is the  *)
(* per-entry fact the EBVIN_CONG/EBVEQ_CONG congruence hypotheses need.   *)
let ENTRY_TABR_IFF = prove
 (`!D (E:A->A->bool) B leq cc RG f v d r_att tabr delta r_delta
   tabr_d q rr kk w
     u y pr ive ru ry rv rc rcd z.
     model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\ cc IN D /\
     RG IN D /\ eisfun D E RG /\ f IN D /\ eisfun D E f /\
     valuation D v /\ v 2 = B /\ v 3 = leq /\ v 4 = cc /\
       v 5 = RG /\ v 6 = f /\
     w IN D /\
     (!x r. x IN D /\ E x w /\ ebnrank D E B x r ==> eapply D E RG x r) /\
     ecross D E w w cc /\
     eordinal D E d /\ erecres D E ebvattstep_form v d r_att /\
     eranu D E r_att tabr /\
     delta IN D /\ E delta d /\ erecres D E ebvattstep_form v delta r_delta /\
     eranu D E r_delta tabr_d /\
     q IN D /\ rr IN D /\ eordinal D E kk /\
     (!zz. zz IN D
           ==> (E zz q <=>
                ?a b. a IN D /\ b IN D /\ E a kk /\ E b kk /\
                  eopair D E a b zz)) /\
     (!z1 z2. z1 IN D /\ z2 IN D
              ==> (erel D E rr z1 z2 <=> E z1 q /\ E z2 q /\
                   emlex D E z1 z2)) /\
     (!zz t. zz IN D /\ t IN D
             ==> (eapply D E f zz t <=> E zz d /\ eoenum D E q rr zz t)) /\
     (!z1 t. z1 IN D /\ t IN D /\ eapply D E f z1 t ==> E z1 d /\ E t q) /\
     (!r1 w1 w2. r1 IN D /\ w1 IN D /\ w2 IN D /\
                 holds D E ((1 |-> w1) ((0 |-> r1) v)) ebvattstep_form /\
                 holds D E ((1 |-> w2) ((0 |-> r1) v))
                   ebvattstep_form ==> w1 = w2) /\
     (!x. x IN D ==> ?yy. yy IN D /\
                          holds D E ((1 |-> yy) ((0 |-> x) v))
                            ebvattstep_form) /\
     u IN D /\ y IN D /\ pr IN D /\ ive IN D /\ ru IN D /\
       ry IN D /\ rv IN D /\
     rc IN D /\ rcd IN D /\ z IN D /\
     ebnrank D E B u ru /\ ebnrank D E B y ry /\ E ry rv /\
     eordinal D E ru /\ eordinal D E ry /\ eordinal D E rv /\
     eopair D E u y pr /\ eopair D E pr ive z /\ eopair D E ru ry rc /\
     eopair D E ru rv rcd /\ eapply D E f delta rcd
     ==> (E z tabr_d <=> E z tabr)`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN EQ_TAC THENL
   [DISCH_TAC THEN
    MATCH_MP_TAC(ISPECL
                 [`D:A->bool`; `E:A->A->bool`; `v:num->A`; `d:A`; `delta:A`;
                  `r_att:A`; `tabr:A`; `r_delta:A`; `tabr_d:A`; `z:A`]
                   ERANU_DELTA_IN_TABR) THEN
    ASM_REWRITE_TAC[];
    DISCH_TAC THEN
    MATCH_MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `B:A`; `leq:A`; `cc:A`;
      `RG:A`; `f:A`; `v:num->A`; `d:A`; `r_att:A`; `tabr:A`; `delta:A`;
      `r_delta:A`;
      `tabr_d:A`; `q:A`; `rr:A`; `kk:A`; `w:A`; `u:A`; `y:A`; `pr:A`; `ive:A`;
      `ru:A`; `ry:A`; `rv:A`; `rc:A`; `rcd:A`; `z:A`] ENTRY_TABR_IN_DELTA) THEN
    REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC]);;

(* ================================================================== *)
(* F4: the reading-equation congruence hypotheses.                     *)
(* ================================================================== *)

(* ENTRY_TABR_IN_DELTA_GEN: as ENTRY_TABR_IN_DELTA but takes emlex rc    *)
(* rcd as a hypothesis (rather than deriving it via EMLEX_DEC_A) -- so   *)
(* it applies to ALL three decrease patterns (DEC_A/B/C), for both the   *)
(* IN and the two EQ congruence families.                               *)
let ENTRY_TABR_IN_DELTA_GEN = prove
 (`!D (E:A->A->bool) B leq cc RG f v d r_att tabr delta r_delta
   tabr_d q rr kk w
     u y pr ive ru ry rv rc rcd z.
     model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\ cc IN D /\
     RG IN D /\ eisfun D E RG /\ f IN D /\ eisfun D E f /\
     valuation D v /\ v 2 = B /\ v 3 = leq /\ v 4 = cc /\
       v 5 = RG /\ v 6 = f /\
     w IN D /\
     (!x r. x IN D /\ E x w /\ ebnrank D E B x r ==> eapply D E RG x r) /\
     ecross D E w w cc /\
     eordinal D E d /\ erecres D E ebvattstep_form v d r_att /\
     eranu D E r_att tabr /\
     delta IN D /\ E delta d /\ erecres D E ebvattstep_form v delta r_delta /\
     eranu D E r_delta tabr_d /\
     q IN D /\ rr IN D /\ eordinal D E kk /\
     (!zz. zz IN D
           ==> (E zz q <=>
                ?a b. a IN D /\ b IN D /\ E a kk /\ E b kk /\
                  eopair D E a b zz)) /\
     (!z1 z2. z1 IN D /\ z2 IN D
              ==> (erel D E rr z1 z2 <=> E z1 q /\ E z2 q /\
                   emlex D E z1 z2)) /\
     (!zz t. zz IN D /\ t IN D
             ==> (eapply D E f zz t <=> E zz d /\ eoenum D E q rr zz t)) /\
     (!z1 t. z1 IN D /\ t IN D /\ eapply D E f z1 t ==> E z1 d /\ E t q) /\
     (!r1 w1 w2. r1 IN D /\ w1 IN D /\ w2 IN D /\
                 holds D E ((1 |-> w1) ((0 |-> r1) v)) ebvattstep_form /\
                 holds D E ((1 |-> w2) ((0 |-> r1) v))
                   ebvattstep_form ==> w1 = w2) /\
     (!x. x IN D ==> ?yy. yy IN D /\
                          holds D E ((1 |-> yy) ((0 |-> x) v))
                            ebvattstep_form) /\
     u IN D /\ y IN D /\ pr IN D /\ ive IN D /\ ru IN D /\
       ry IN D /\ rv IN D /\
     rc IN D /\ rcd IN D /\ z IN D /\
     ebnrank D E B u ru /\ ebnrank D E B y ry /\
     eordinal D E ru /\ eordinal D E ry /\
     eopair D E u y pr /\ eopair D E pr ive z /\ eopair D E ru ry rc /\
     emlex D E rc rcd /\ eapply D E f delta rcd /\
     E z tabr
     ==> E z tabr_d`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN
   `!u1 u2. u1 IN D /\ u2 IN D /\ erel D (E:A->A->bool) rr u1 u2
            ==> ~erel D E rr u2 u1` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `q:A`; `rr:A`; `kk:A`]
      RR_IRREFL) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `v:num->A`; `d:A`; `r_att:A`;
    `tabr:A`; `z:A`] TABR_MEM) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `b:A` (X_CHOOSE_THEN `Yv:A` STRIP_ASSUME_TAC)) THEN
  MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `B:A`; `leq:A`; `cc:A`; `RG:A`;
    `f:A`; `v:num->A`; `d:A`; `r_att:A`; `b:A`] EBVATT_VALUE_AT) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `Yb:A` (X_CHOOSE_THEN `rb:A` STRIP_ASSUME_TAC)) THEN
  SUBGOAL_THEN `Yv:A = Yb` SUBST_ALL_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`; `E:A->A->bool`; `ebvattstep_form`; `v:num->A`;
                  `b:A`; `Yv:A`; `Yb:A`] EREC_UNIQUE) THEN
            ASM_REWRITE_TAC[] THEN
            MP_TAC(ISPECL
                   [`D:A->bool`; `E:A->A->bool`; `ebvattstep_form`; `v:num->A`;
                    `d:A`; `r_att:A`; `b:A`; `Yb:A`] ERECRES_APPLY) THEN
            ASM_REWRITE_TAC[];
            ALL_TAC] THEN
  MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `B:A`; `leq:A`; `cc:A`; `RG:A`;
    `f:A`; `rb:A`; `Yb:A`; `w:A`; `u:A`; `y:A`; `pr:A`; `ive:A`;
    `ru:A`; `ry:A`;
    `rc:A`; `z:A`] STAGE_RANKCODE) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_THEN `db:A` STRIP_ASSUME_TAC) THEN
  SUBGOAL_THEN `eordinal D (E:A->A->bool) b` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `d:A`; `b:A`]
      EORDINAL_MEMBER) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `edomain D (E:A->A->bool) rb b` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`; `E:A->A->bool`; `ebvattstep_form`; `v:num->A`;
                  `b:A`; `rb:A`] ERECRES_EDOMAIN) THEN ASM_REWRITE_TAC[];
            ALL_TAC] THEN
  SUBGOAL_THEN `db:A = b` SUBST_ALL_TAC THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `rb:A`; `db:A`; `b:A`]
      EDOMAIN_UNIQUE) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN
   `eoenum D E q rr b rc /\ eoenum D (E:A->A->bool) q rr delta rcd`
  STRIP_ASSUME_TAC THENL
   [UNDISCH_TAC
     `!zz t. zz IN D /\ t IN D
             ==> (eapply D (E:A->A->bool) f zz t <=>
                  E zz d /\ eoenum D E q rr zz t)` THEN
    DISCH_THEN(fun th -> CONJ_TAC THENL
      [MP_TAC(SPECL [`b:A`; `rc:A`] th);
       MP_TAC(SPECL [`delta:A`; `rcd:A`] th)]) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) rc q /\ E rcd q` STRIP_ASSUME_TAC THENL
   [UNDISCH_TAC
     `!z1 t. z1 IN D /\ t IN D /\ eapply D (E:A->A->bool) f z1 t
             ==> E z1 d /\ E t q` THEN
    DISCH_THEN(fun th -> CONJ_TAC THENL
      [MP_TAC(SPECL [`b:A`; `rc:A`] th);
       MP_TAC(SPECL [`delta:A`; `rcd:A`] th)]) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `~(rc:A = q) /\ ~(rcd:A = q)` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[E_IRREFL]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) b delta` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `q:A`; `rr:A`; `d:A`;
      `delta:A`; `b:A`; `rcd:A`; `rc:A`] CONVERSE_ORDER) THEN
    REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  MP_TAC(ISPECL
         [`D:A->bool`; `E:A->A->bool`; `v:num->A`; `delta:A`; `r_delta:A`;
          `tabr_d:A`; `z:A`] TABR_MEM) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  MAP_EVERY EXISTS_TAC [`b:A`; `Yb:A`] THEN ASM_REWRITE_TAC[]);;

(* AGREE_IN: the EBVIN_CONG congruence hypothesis -- sEQ_d and sEQ agree *)
(* at the pairs <u,y> (y in dom v0) that [[u in v0]] reads.  Per-entry   *)
(* iff via ENTRY_TABR_IFF (bnrank y < rv from EBNRANK_APPLY_LT), glued   *)
(* by EBVSUBEQ_APPLY both sides + an exists-congruence.                  *)
let AGREE_IN = prove
 (`!D (E:A->A->bool) B leq cc RG f v d r_att tabr sEQ delta r_delta
   tabr_d sEQ_d
     q rr kk w u v0 ru rv rcd.
     model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\ cc IN D /\
     RG IN D /\ eisfun D E RG /\ f IN D /\ eisfun D E f /\
     valuation D v /\ v 2 = B /\ v 3 = leq /\ v 4 = cc /\
       v 5 = RG /\ v 6 = f /\
     w IN D /\
     (!x r. x IN D /\ E x w /\ ebnrank D E B x r ==> eapply D E RG x r) /\
     ecross D E w w cc /\
     eordinal D E d /\ erecres D E ebvattstep_form v d r_att /\
     eranu D E r_att tabr /\ ebvsubeq D E tabr sEQ /\
     delta IN D /\ E delta d /\ erecres D E ebvattstep_form v delta r_delta /\
     eranu D E r_delta tabr_d /\ ebvsubeq D E tabr_d sEQ_d /\
     q IN D /\ rr IN D /\ eordinal D E kk /\
     (!zz. zz IN D
           ==> (E zz q <=>
                ?a b. a IN D /\ b IN D /\ E a kk /\ E b kk /\
                  eopair D E a b zz)) /\
     (!z1 z2. z1 IN D /\ z2 IN D
              ==> (erel D E rr z1 z2 <=> E z1 q /\ E z2 q /\
                   emlex D E z1 z2)) /\
     (!zz t. zz IN D /\ t IN D
             ==> (eapply D E f zz t <=> E zz d /\ eoenum D E q rr zz t)) /\
     (!z1 t. z1 IN D /\ t IN D /\ eapply D E f z1 t ==> E z1 d /\ E t q) /\
     (!r1 w1 w2. r1 IN D /\ w1 IN D /\ w2 IN D /\
                 holds D E ((1 |-> w1) ((0 |-> r1) v)) ebvattstep_form /\
                 holds D E ((1 |-> w2) ((0 |-> r1) v))
                   ebvattstep_form ==> w1 = w2) /\
     (!x. x IN D ==> ?yy. yy IN D /\
                          holds D E ((1 |-> yy) ((0 |-> x) v))
                            ebvattstep_form) /\
     u IN D /\ v0 IN D /\ ru IN D /\ rv IN D /\ rcd IN D /\
     ebnrank D E B u ru /\ ebnrank D E B v0 rv /\
     eordinal D E ru /\ eordinal D E rv /\
     eopair D E ru rv rcd /\ eapply D E f delta rcd
     ==> (!y qy pr my.
              y IN D /\ qy IN D /\ pr IN D /\ my IN D /\
              eapply D E v0 y qy /\ eopair D E u y pr
              ==> (eapply D E sEQ_d pr my <=> eapply D E sEQ pr my))`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  MAP_EVERY X_GEN_TAC [`y:A`; `qy:A`; `pr:A`; `my:A`] THEN STRIP_TAC THEN
  MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `B:A`; `v0:A`; `y:A`; `qy:A`;
    `rv:A`] EBNRANK_APPLY_LT) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC
    (X_CHOOSE_THEN `ry:A` STRIP_ASSUME_TAC)) THEN
  SUBGOAL_THEN `(ry:A) IN D /\ eordinal D (E:A->A->bool) ry`
    STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[EBNRANK_IN; EBNRANK_ORDINAL]; ALL_TAC] THEN
  SUBGOAL_THEN `?rc:A. eopair D E ru ry rc` STRIP_ASSUME_TAC THENL
   [MATCH_MP_TAC EOPAIR_EXISTS THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(rc:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[EOPAIR_IN]; ALL_TAC] THEN
  SUBGOAL_THEN
   `!ival inner uu. ival IN D /\ inner IN D /\ uu IN D /\
                    eopair D E ival my inner /\
                      eopair D (E:A->A->bool) pr inner uu
                    ==> (E uu tabr_d <=> E uu tabr)`
  (LABEL_TAC "peq") THENL
   [MAP_EVERY X_GEN_TAC [`ival:A`; `inner:A`; `uu:A`] THEN STRIP_TAC THEN
    MATCH_MP_TAC(ISPECL
     [`D:A->bool`; `E:A->A->bool`; `B:A`; `leq:A`; `cc:A`; `RG:A`; `f:A`;
      `v:num->A`; `d:A`; `r_att:A`; `tabr:A`; `delta:A`;
      `r_delta:A`; `tabr_d:A`;
      `q:A`; `rr:A`; `kk:A`; `w:A`; `u:A`; `y:A`; `pr:A`; `inner:A`; `ru:A`;
      `ry:A`; `rv:A`; `rc:A`; `rcd:A`; `uu:A`] ENTRY_TABR_IFF) THEN
    REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  MP_TAC(ISPECL
         [`D:A->bool`; `E:A->A->bool`; `tabr_d:A`; `sEQ_d:A`; `pr:A`; `my:A`]
         EBVSUBEQ_APPLY) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  MP_TAC(ISPECL
         [`D:A->bool`; `E:A->A->bool`; `tabr:A`; `sEQ:A`; `pr:A`; `my:A`]
         EBVSUBEQ_APPLY) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  MATCH_MP_TAC(MESON[]
   `(!ival inner uu. ival IN D /\ inner IN D /\ uu IN D /\
                     eopair D (E:A->A->bool) ival my inner /\
                     eopair D E pr inner uu ==> (E uu tabr_d <=> E uu tabr))
    ==> ((?ival inner uu. ival IN D /\ inner IN D /\ uu IN D /\
                          eopair D E ival my inner /\ eopair D E pr inner uu /\
                          E uu tabr_d) <=>
         (?ival inner uu. ival IN D /\ inner IN D /\ uu IN D /\
                          eopair D E ival my inner /\ eopair D E pr inner uu /\
                          E uu tabr))`) THEN
  USE_THEN "peq" ACCEPT_TAC);;

(* ENTRY_TABR_IFF_GEN: as ENTRY_TABR_IFF but with emlex rc rcd as a     *)
(* hypothesis (via ENTRY_TABR_IN_DELTA_GEN) -- for the EQ congruence     *)
(* families that decrease in the first component (EMLEX_DEC_B/_C).       *)
let ENTRY_TABR_IFF_GEN = prove
 (`!D (E:A->A->bool) B leq cc RG f v d r_att tabr delta r_delta
   tabr_d q rr kk w
     u y pr ive ru ry rv rc rcd z.
     model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\ cc IN D /\
     RG IN D /\ eisfun D E RG /\ f IN D /\ eisfun D E f /\
     valuation D v /\ v 2 = B /\ v 3 = leq /\ v 4 = cc /\
       v 5 = RG /\ v 6 = f /\
     w IN D /\
     (!x r. x IN D /\ E x w /\ ebnrank D E B x r ==> eapply D E RG x r) /\
     ecross D E w w cc /\
     eordinal D E d /\ erecres D E ebvattstep_form v d r_att /\
     eranu D E r_att tabr /\
     delta IN D /\ E delta d /\ erecres D E ebvattstep_form v delta r_delta /\
     eranu D E r_delta tabr_d /\
     q IN D /\ rr IN D /\ eordinal D E kk /\
     (!zz. zz IN D
           ==> (E zz q <=>
                ?a b. a IN D /\ b IN D /\ E a kk /\ E b kk /\
                  eopair D E a b zz)) /\
     (!z1 z2. z1 IN D /\ z2 IN D
              ==> (erel D E rr z1 z2 <=> E z1 q /\ E z2 q /\
                   emlex D E z1 z2)) /\
     (!zz t. zz IN D /\ t IN D
             ==> (eapply D E f zz t <=> E zz d /\ eoenum D E q rr zz t)) /\
     (!z1 t. z1 IN D /\ t IN D /\ eapply D E f z1 t ==> E z1 d /\ E t q) /\
     (!r1 w1 w2. r1 IN D /\ w1 IN D /\ w2 IN D /\
                 holds D E ((1 |-> w1) ((0 |-> r1) v)) ebvattstep_form /\
                 holds D E ((1 |-> w2) ((0 |-> r1) v))
                   ebvattstep_form ==> w1 = w2) /\
     (!x. x IN D ==> ?yy. yy IN D /\
                          holds D E ((1 |-> yy) ((0 |-> x) v))
                            ebvattstep_form) /\
     u IN D /\ y IN D /\ pr IN D /\ ive IN D /\ ru IN D /\
       ry IN D /\ rv IN D /\
     rc IN D /\ rcd IN D /\ z IN D /\
     ebnrank D E B u ru /\ ebnrank D E B y ry /\
     eordinal D E ru /\ eordinal D E ry /\
     eopair D E u y pr /\ eopair D E pr ive z /\ eopair D E ru ry rc /\
     emlex D E rc rcd /\ eapply D E f delta rcd
     ==> (E z tabr_d <=> E z tabr)`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN EQ_TAC THENL
   [DISCH_TAC THEN
    MATCH_MP_TAC(ISPECL
                 [`D:A->bool`; `E:A->A->bool`; `v:num->A`; `d:A`; `delta:A`;
                  `r_att:A`; `tabr:A`; `r_delta:A`; `tabr_d:A`; `z:A`]
                   ERANU_DELTA_IN_TABR) THEN
    ASM_REWRITE_TAC[];
    DISCH_TAC THEN
    MATCH_MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `B:A`; `leq:A`; `cc:A`;
      `RG:A`; `f:A`; `v:num->A`; `d:A`; `r_att:A`; `tabr:A`; `delta:A`;
      `r_delta:A`;
      `tabr_d:A`; `q:A`; `rr:A`; `kk:A`; `w:A`; `u:A`; `y:A`; `pr:A`; `ive:A`;
      `ru:A`; `ry:A`; `rv:A`; `rc:A`; `rcd:A`; `z:A`]
                     ENTRY_TABR_IN_DELTA_GEN) THEN
    REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC]);;

(* AGREE_EQ_L / AGREE_EQ_R: the two EBVEQ_CONG congruence families for   *)
(* [[u=v0]] -- sIN_d and sIN agree at the pairs <x,v0> (x in dom u, via  *)
(* EMLEX_DEC_B) and <y,u> (y in dom v0, via EMLEX_DEC_C).  Same shape as  *)
(* AGREE_IN but reading the IN-table (EBVSUBIN_APPLY) and using the       *)
(* emlex-generalized ENTRY_TABR_IFF_GEN.                                 *)
let AGREE_EQ_L = prove
 (`!D (E:A->A->bool) B leq cc RG f v d r_att tabr sIN delta r_delta
   tabr_d sIN_d
     q rr kk w u v0 ru rv rcd.
     model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\ cc IN D /\
     RG IN D /\ eisfun D E RG /\ f IN D /\ eisfun D E f /\
     valuation D v /\ v 2 = B /\ v 3 = leq /\ v 4 = cc /\
       v 5 = RG /\ v 6 = f /\
     w IN D /\
     (!x r. x IN D /\ E x w /\ ebnrank D E B x r ==> eapply D E RG x r) /\
     ecross D E w w cc /\
     eordinal D E d /\ erecres D E ebvattstep_form v d r_att /\
     eranu D E r_att tabr /\ ebvsubin D E tabr sIN /\
     delta IN D /\ E delta d /\ erecres D E ebvattstep_form v delta r_delta /\
     eranu D E r_delta tabr_d /\ ebvsubin D E tabr_d sIN_d /\
     q IN D /\ rr IN D /\ eordinal D E kk /\
     (!zz. zz IN D
           ==> (E zz q <=>
                ?a b. a IN D /\ b IN D /\ E a kk /\ E b kk /\
                  eopair D E a b zz)) /\
     (!z1 z2. z1 IN D /\ z2 IN D
              ==> (erel D E rr z1 z2 <=> E z1 q /\ E z2 q /\
                   emlex D E z1 z2)) /\
     (!zz t. zz IN D /\ t IN D
             ==> (eapply D E f zz t <=> E zz d /\ eoenum D E q rr zz t)) /\
     (!z1 t. z1 IN D /\ t IN D /\ eapply D E f z1 t ==> E z1 d /\ E t q) /\
     (!r1 w1 w2. r1 IN D /\ w1 IN D /\ w2 IN D /\
                 holds D E ((1 |-> w1) ((0 |-> r1) v)) ebvattstep_form /\
                 holds D E ((1 |-> w2) ((0 |-> r1) v))
                   ebvattstep_form ==> w1 = w2) /\
     (!x. x IN D ==> ?yy. yy IN D /\
                          holds D E ((1 |-> yy) ((0 |-> x) v))
                            ebvattstep_form) /\
     u IN D /\ v0 IN D /\ ru IN D /\ rv IN D /\ rcd IN D /\
     ebnrank D E B u ru /\ ebnrank D E B v0 rv /\
     eordinal D E ru /\ eordinal D E rv /\
     eopair D E ru rv rcd /\ eapply D E f delta rcd
     ==> (!x qx pr mx.
              x IN D /\ qx IN D /\ pr IN D /\ mx IN D /\
              eapply D E u x qx /\ eopair D E x v0 pr
              ==> (eapply D E sIN_d pr mx <=> eapply D E sIN pr mx))`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  MAP_EVERY X_GEN_TAC [`x:A`; `qx:A`; `pr:A`; `mx:A`] THEN STRIP_TAC THEN
  MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `B:A`; `u:A`; `x:A`; `qx:A`;
    `ru:A`] EBNRANK_APPLY_LT) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC
    (X_CHOOSE_THEN `rx:A` STRIP_ASSUME_TAC)) THEN
  SUBGOAL_THEN `(rx:A) IN D /\ eordinal D (E:A->A->bool) rx`
    STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[EBNRANK_IN; EBNRANK_ORDINAL]; ALL_TAC] THEN
  SUBGOAL_THEN `?rc:A. eopair D E rx rv rc` STRIP_ASSUME_TAC THENL
   [MATCH_MP_TAC EOPAIR_EXISTS THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(rc:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[EOPAIR_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `emlex D (E:A->A->bool) rc rcd` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `rx:A`; `ru:A`; `rv:A`;
      `rc:A`; `rcd:A`] EMLEX_DEC_B) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN
   `!eval inner uu. eval IN D /\ inner IN D /\ uu IN D /\
                    eopair D E mx eval inner /\
                      eopair D (E:A->A->bool) pr inner uu
                    ==> (E uu tabr_d <=> E uu tabr)`
  (LABEL_TAC "peq") THENL
   [MAP_EVERY X_GEN_TAC [`eval:A`; `inner:A`; `uu:A`] THEN STRIP_TAC THEN
    MATCH_MP_TAC(ISPECL
     [`D:A->bool`; `E:A->A->bool`; `B:A`; `leq:A`; `cc:A`; `RG:A`; `f:A`;
      `v:num->A`; `d:A`; `r_att:A`; `tabr:A`; `delta:A`;
      `r_delta:A`; `tabr_d:A`;
      `q:A`; `rr:A`; `kk:A`; `w:A`; `x:A`; `v0:A`; `pr:A`; `inner:A`; `rx:A`;
      `rv:A`; `rv:A`; `rc:A`; `rcd:A`; `uu:A`] ENTRY_TABR_IFF_GEN) THEN
    REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  MP_TAC(ISPECL
         [`D:A->bool`; `E:A->A->bool`; `tabr_d:A`; `sIN_d:A`; `pr:A`; `mx:A`]
         EBVSUBIN_APPLY) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  MP_TAC(ISPECL
         [`D:A->bool`; `E:A->A->bool`; `tabr:A`; `sIN:A`; `pr:A`; `mx:A`]
         EBVSUBIN_APPLY) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  MATCH_MP_TAC(MESON[]
   `(!eval inner uu. eval IN D /\ inner IN D /\ uu IN D /\
                     eopair D (E:A->A->bool) mx eval inner /\
                     eopair D E pr inner uu ==> (E uu tabr_d <=> E uu tabr))
    ==> ((?eval inner uu. eval IN D /\ inner IN D /\ uu IN D /\
                          eopair D E mx eval inner /\ eopair D E pr inner uu /\
                          E uu tabr_d) <=>
         (?eval inner uu. eval IN D /\ inner IN D /\ uu IN D /\
                          eopair D E mx eval inner /\ eopair D E pr inner uu /\
                          E uu tabr))`) THEN
  USE_THEN "peq" ACCEPT_TAC);;

let AGREE_EQ_R = prove
 (`!D (E:A->A->bool) B leq cc RG f v d r_att tabr sIN delta r_delta
   tabr_d sIN_d
     q rr kk w u v0 ru rv rcd.
