    `rv:A`] EBNRANK_APPLY_LT) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC
    (X_CHOOSE_THEN `ry:A` STRIP_ASSUME_TAC)) THEN
  SUBGOAL_THEN `(ry:A) IN D /\ eordinal D (E:A->A->bool) ry`
    STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[EBNRANK_IN; EBNRANK_ORDINAL]; ALL_TAC] THEN
  SUBGOAL_THEN `?rc:A. eopair D E ry ru rc` STRIP_ASSUME_TAC THENL
   [MATCH_MP_TAC EOPAIR_EXISTS THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(rc:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[EOPAIR_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `emlex D (E:A->A->bool) rc rcd` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `ry:A`; `ru:A`; `rv:A`;
      `rc:A`; `rcd:A`] EMLEX_DEC_C) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN
   `!eval inner uu. eval IN D /\ inner IN D /\ uu IN D /\
                    eopair D E my eval inner /\
                      eopair D (E:A->A->bool) pr inner uu
                    ==> (E uu tabr_d <=> E uu tabr)`
  (LABEL_TAC "peq") THENL
   [MAP_EVERY X_GEN_TAC [`eval:A`; `inner:A`; `uu:A`] THEN STRIP_TAC THEN
    MATCH_MP_TAC(ISPECL
     [`D:A->bool`; `E:A->A->bool`; `B:A`; `leq:A`; `cc:A`; `RG:A`; `f:A`;
      `v:num->A`; `d:A`; `r_att:A`; `tabr:A`; `delta:A`;
      `r_delta:A`; `tabr_d:A`;
      `q:A`; `rr:A`; `kk:A`; `w:A`; `y:A`; `u:A`; `pr:A`; `inner:A`; `ry:A`;
      `ru:A`; `ru:A`; `rc:A`; `rcd:A`; `uu:A`] ENTRY_TABR_IFF_GEN) THEN
    REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  MP_TAC(ISPECL
         [`D:A->bool`; `E:A->A->bool`; `tabr_d:A`; `sIN_d:A`; `pr:A`; `my:A`]
         EBVSUBIN_APPLY) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  MP_TAC(ISPECL
         [`D:A->bool`; `E:A->A->bool`; `tabr:A`; `sIN:A`; `pr:A`; `my:A`]
         EBVSUBIN_APPLY) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  MATCH_MP_TAC(MESON[]
   `(!eval inner uu. eval IN D /\ inner IN D /\ uu IN D /\
                     eopair D (E:A->A->bool) my eval inner /\
                     eopair D E pr inner uu ==> (E uu tabr_d <=> E uu tabr))
    ==> ((?eval inner uu. eval IN D /\ inner IN D /\ uu IN D /\
                          eopair D E my eval inner /\ eopair D E pr inner uu /\
                          E uu tabr_d) <=>
         (?eval inner uu. eval IN D /\ inner IN D /\ uu IN D /\
                          eopair D E my eval inner /\ eopair D E pr inner uu /\
                          E uu tabr))`) THEN
  USE_THEN "peq" ACCEPT_TAC);;

(* ================================================================== *)
(* eisfun-first arc, step 0: FINJ_STAGE -- the EPRODK enum iso f is     *)
(* injective (eapply f b1 rc /\ eapply f b2 rc ==> b1=b2), via          *)
(* fac->eoenum + EOENUM_ORDER + RR_IRREFL + trichotomy (same shape as   *)
(* CONVERSE_ORDER).  Needed so two same-key tabr entries land in the     *)
(* SAME recursion stage (for eisfun of the projected tables).           *)
(* ================================================================== *)

let FINJ_STAGE = prove
 (`!D (E:A->A->bool) q rr d kk f b1 b2 rc.
     model D E ZF_AX /\ q IN D /\ rr IN D /\ eordinal D E d /\
       eordinal D E kk /\
     (!u u'. u IN D /\ u' IN D /\ erel D E rr u u' ==> ~erel D E rr u' u) /\
     (!z z'. z IN D /\ z' IN D
             ==> (erel D E rr z z' <=> E z q /\ E z' q /\ emlex D E z z')) /\
     (!zz t. zz IN D /\ t IN D
             ==> (eapply D E f zz t <=> E zz d /\ eoenum D E q rr zz t)) /\
     (!z1 t. z1 IN D /\ t IN D /\ eapply D E f z1 t ==> E z1 d /\ E t q) /\
     (!z. z IN D
          ==> (E z q <=>
               ?a b. a IN D /\ b IN D /\ E a kk /\ E b kk /\
                 eopair D E a b z)) /\
     b1 IN D /\ b2 IN D /\ rc IN D /\ E b1 d /\ E b2 d /\
     eapply D E f b1 rc /\ eapply D E f b2 rc
     ==> b1 = b2`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `eoenum D E q rr b1 rc /\ eoenum D (E:A->A->bool) q rr b2 rc`
  STRIP_ASSUME_TAC THENL
   [UNDISCH_TAC
     `!zz t. zz IN D /\ t IN D
             ==> (eapply D (E:A->A->bool) f zz t <=> E zz d /\
                  eoenum D E q rr zz t)` THEN
    DISCH_THEN(fun th -> CONJ_TAC THENL
      [MP_TAC(SPECL [`b1:A`; `rc:A`] th);
       MP_TAC(SPECL [`b2:A`; `rc:A`] th)]) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) rc q` ASSUME_TAC THENL
   [UNDISCH_TAC
     `!z1 t. z1 IN D /\ t IN D /\ eapply D (E:A->A->bool) f z1 t
             ==> E z1 d /\ E t q` THEN
    DISCH_THEN(MP_TAC o SPECL [`b1:A`; `rc:A`]) THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `~(rc:A = q)` ASSUME_TAC THENL
   [ASM_MESON_TAC[E_IRREFL]; ALL_TAC] THEN
  SUBGOAL_THEN `eordinal D E b1 /\ eordinal D (E:A->A->bool) b2`
    STRIP_ASSUME_TAC THENL
   [CONJ_TAC THENL
     [MATCH_MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `d:A`; `b1:A`]
        EORDINAL_MEMBER);
      MATCH_MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `d:A`; `b2:A`]
        EORDINAL_MEMBER)] THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `b1:A`; `b2:A`]
    EORDINAL_TRICHOTOMY) THEN
  ASM_REWRITE_TAC[] THEN STRIP_TAC THENL
   [SUBGOAL_THEN `erel D (E:A->A->bool) rr rc rc` ASSUME_TAC THENL
     [MATCH_MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `q:A`; `rr:A`; `b1:A`;
        `b2:A`; `rc:A`; `rc:A`] EOENUM_ORDER) THEN
      REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    UNDISCH_TAC
     `!u u'. u IN D /\ u' IN D /\ erel D (E:A->A->bool) rr u u'
             ==> ~erel D E rr u' u` THEN
    DISCH_THEN(MP_TAC o SPECL [`rc:A`; `rc:A`]) THEN ASM_REWRITE_TAC[];
    SUBGOAL_THEN `erel D (E:A->A->bool) rr rc rc` ASSUME_TAC THENL
     [MATCH_MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `q:A`; `rr:A`; `b2:A`;
        `b1:A`; `rc:A`; `rc:A`] EOENUM_ORDER) THEN
      REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    UNDISCH_TAC
     `!u u'. u IN D /\ u' IN D /\ erel D (E:A->A->bool) rr u u'
             ==> ~erel D E rr u' u` THEN
    DISCH_THEN(MP_TAC o SPECL [`rc:A`; `rc:A`]) THEN ASM_REWRITE_TAC[]]);;

(* ------------------------------------------------------------------ *)
(* STAGE_ENTRY_UNIQUE: within ONE ebvattstep stage value, two entries    *)
(* sharing a key pr are equal (eisfun-first arc, step 1a).               *)
let STAGE_ENTRY_UNIQUE = prove
 (`!D (E:A->A->bool) B leq c RG f g Y u1 u2 pr ive1 ive2.
     model D E ZF_AX /\ ecba D E B leq /\
     ebvattstep D E B leq c RG f g Y /\
     u1 IN D /\ u2 IN D /\ pr IN D /\ ive1 IN D /\ ive2 IN D /\
     eopair D E pr ive1 u1 /\ eopair D E pr ive2 u2 /\
     E u1 Y /\ E u2 Y
     ==> u1 = u2`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`c:A`;`RG:A`;`f:A`;
    `g:A`;`Y:A`;`u1:A`] EBVATTSTEP_ENTRY_FWD) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `d1:A`
             (X_CHOOSE_THEN `t1:A`
              (X_CHOOSE_THEN `sE1:A`
               (X_CHOOSE_THEN `sI1:A`
                (X_CHOOSE_THEN `rc1:A`
                 (X_CHOOSE_THEN `pr1:A`
                  (X_CHOOSE_THEN `uu1:A`
                   (X_CHOOSE_THEN `vv1:A`
                    (X_CHOOSE_THEN `ru1:A`
                     (X_CHOOSE_THEN `rv1:A`
                      (X_CHOOSE_THEN `iva1:A`
                       (X_CHOOSE_THEN `eva1:A`
                        (X_CHOOSE_THEN `ive1f:A`
                         STRIP_ASSUME_TAC))))))))))))) THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`c:A`;`RG:A`;`f:A`;
    `g:A`;`Y:A`;`u2:A`] EBVATTSTEP_ENTRY_FWD) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `d2:A`
             (X_CHOOSE_THEN `t2:A`
              (X_CHOOSE_THEN `sE2:A`
               (X_CHOOSE_THEN `sI2:A`
                (X_CHOOSE_THEN `rc2:A`
                 (X_CHOOSE_THEN `pr2:A`
                  (X_CHOOSE_THEN `uu2:A`
                   (X_CHOOSE_THEN `vv2:A`
                    (X_CHOOSE_THEN `ru2:A`
                     (X_CHOOSE_THEN `rv2:A`
                      (X_CHOOSE_THEN `iva2:A`
                       (X_CHOOSE_THEN `eva2:A`
                        (X_CHOOSE_THEN `ive2f:A`
                         STRIP_ASSUME_TAC))))))))))))) THEN
  (* t1 = t2 (ranu of same g) *)
  SUBGOAL_THEN `(t1:A) = t2` SUBST_ALL_TAC THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`g:A`;`t1:A`;`t2:A`]
      ERANU_UNIQUE) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* sE1 = sE2, sI1 = sI2 (subeq/subin of same tabr) *)
  SUBGOAL_THEN `(sE1:A) = sE2` SUBST_ALL_TAC THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`t2:A`;`sE1:A`;`sE2:A`]
      EBVSUBEQ_UNIQUE) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(sI1:A) = sI2` SUBST_ALL_TAC THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`t2:A`;`sI1:A`;`sI2:A`]
      EBVSUBIN_UNIQUE) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* pr1 = pr, ive1f = ive1 (opair-inj on u1) *)
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`pr1:A`;`ive1f:A`;`pr:A`;`ive1:A`;
    `u1:A`] EOPAIR_INJ) THEN ASM_REWRITE_TAC[] THEN
  DISCH_THEN(CONJUNCTS_THEN2 SUBST_ALL_TAC SUBST_ALL_TAC) THEN
  (* pr2 = pr, ive2f = ive2 (opair-inj on u2) *)
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`pr2:A`;`ive2f:A`;`pr:A`;`ive2:A`;
    `u2:A`] EOPAIR_INJ) THEN ASM_REWRITE_TAC[] THEN
  DISCH_THEN(CONJUNCTS_THEN2 SUBST_ALL_TAC SUBST_ALL_TAC) THEN
  (* uu1 = uu2, vv1 = vv2 (opair-inj on shared key pr) *)
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`uu1:A`;`vv1:A`;`uu2:A`;`vv2:A`;
    `pr:A`] EOPAIR_INJ) THEN ASM_REWRITE_TAC[] THEN
  DISCH_THEN(CONJUNCTS_THEN2 SUBST_ALL_TAC SUBST_ALL_TAC) THEN
  (* iva1 = iva2 (ebvin unique, same table/args) *)
  SUBGOAL_THEN `(iva1:A) = iva2` SUBST_ALL_TAC THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`sE2:A`;
      `vv2:A`;`uu2:A`;`iva1:A`;`iva2:A`] EBVIN_UNIQUE) THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  (* eva1 = eva2 (ebveq unique) *)
  SUBGOAL_THEN `(eva1:A) = eva2` SUBST_ALL_TAC THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`sI2:A`;
      `uu2:A`;`vv2:A`;`eva1:A`;`eva2:A`] EBVEQ_UNIQUE) THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  (* ive1 = ive2 (opair unique on <iva2,eva2>) *)
  SUBGOAL_THEN `(ive1:A) = ive2` SUBST_ALL_TAC THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`iva2:A`;`eva2:A`;`ive1:A`;
      `ive2:A`] EOPAIR_UNIQUE) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* u1 = u2 (opair unique on <pr,ive2>) *)
  MATCH_MP_TAC(ISPECL
               [`D:A->bool`;`E:A->A->bool`;`pr:A`;`ive2:A`;`u1:A`;`u2:A`]
               EOPAIR_UNIQUE) THEN ASM_REWRITE_TAC[]);;

(* ------------------------------------------------------------------ *)
(* TABR_ENTRY_STAGE (eisfun-first 1b): every entry of tabr=eranu r_att   *)
(* lives in a UNIQUE recursion stage b (E b d) with eapply f b rc, where  *)
(* rc is the rank-code of its key; delta=edomain(r_b)=b.                  *)
let TABR_ENTRY_STAGE = prove
 (`!D (E:A->A->bool) B leq cc RG f v d r_att tabr u pr ive.
     model D E ZF_AX /\ ecba D E B leq /\
     B IN D /\ leq IN D /\ cc IN D /\ RG IN D /\ eisfun D E RG /\
     f IN D /\ eisfun D E f /\
     valuation D v /\ v 2 = B /\ v 3 = leq /\ v 4 = cc /\
       v 5 = RG /\ v 6 = f /\
     eordinal D E d /\
     erecres D E ebvattstep_form v d r_att /\ eranu D E r_att tabr /\
     u IN D /\ pr IN D /\ ive IN D /\ eopair D E pr ive u /\ E u tabr
     ==> ?b rb Y rc uu vv ru rv.
           b IN D /\ E b d /\ erecres D E ebvattstep_form v b rb /\
           ebvattstep D E B leq cc RG f rb Y /\ E u Y /\ Y IN D /\
           erec D E ebvattstep_form v b Y /\
           uu IN D /\ vv IN D /\ ru IN D /\ rv IN D /\ rc IN D /\
           eopair D E uu vv pr /\ eapply D E RG uu ru /\ eapply D E RG vv rv /\
           eopair D E ru rv rc /\ eapply D E f b rc`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`cc:A`;`RG:A`;
    `f:A`;`v:num->A`] EBVATTSTEP_SVTOTAL) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "sv") (LABEL_TAC "tot")) THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`v:num->A`;`d:A`;`r_att:A`;
    `tabr:A`;`u:A`] TABR_MEM) THEN ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `b:A` (X_CHOOSE_THEN `y:A` STRIP_ASSUME_TAC)) THEN
  SUBGOAL_THEN `eordinal D (E:A->A->bool) b` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`d:A`;`b:A`]
                 EORDINAL_MEMBER) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `eapply D (E:A->A->bool) r_att b y` ASSUME_TAC THENL
   [MP_TAC(ISPECL
           [`D:A->bool`;`E:A->A->bool`;`ebvattstep_form`;`v:num->A`;`d:A`;
            `r_att:A`;`b:A`;`y:A`] ERECRES_APPLY) THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`cc:A`;`RG:A`;
    `f:A`;`v:num->A`;`d:A`;`r_att:A`;`b:A`] EBVATT_VALUE_AT) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `Yv:A` (X_CHOOSE_THEN `rb:A` STRIP_ASSUME_TAC)) THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`ebvattstep_form`;`v:num->A`;
    `d:A`;`r_att:A`;`b:A`;`Yv:A`] ERECRES_APPLY) THEN ASM_REWRITE_TAC[] THEN
  DISCH_TAC THEN
  SUBGOAL_THEN `y:A = Yv` SUBST_ALL_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`ebvattstep_form`;`v:num->A`;
                  `b:A`;`y:A`;`Yv:A`] EREC_UNIQUE) THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`cc:A`;
    `RG:A`;`f:A`;`rb:A`;`Yv:A`;`u:A`] EBVATTSTEP_ENTRY_FWD) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `dl:A`
             (X_CHOOSE_THEN `tb:A`
              (X_CHOOSE_THEN `sE:A`
               (X_CHOOSE_THEN `sI:A`
                (X_CHOOSE_THEN `rc:A`
                 (X_CHOOSE_THEN `pr0:A`
                  (X_CHOOSE_THEN `uu:A`
                   (X_CHOOSE_THEN `vv:A`
                    (X_CHOOSE_THEN `ru:A`
                     (X_CHOOSE_THEN `rv:A`
                      (X_CHOOSE_THEN `iva:A`
                       (X_CHOOSE_THEN `eva:A`
                        (X_CHOOSE_THEN `ivf:A`
                         STRIP_ASSUME_TAC))))))))))))) THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`pr0:A`;`ivf:A`;`pr:A`;`ive:A`;
    `u:A`] EOPAIR_INJ) THEN ASM_REWRITE_TAC[] THEN
  DISCH_THEN(CONJUNCTS_THEN2 SUBST_ALL_TAC SUBST_ALL_TAC) THEN
  SUBGOAL_THEN `edomain D (E:A->A->bool) rb b` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`ebvattstep_form`;`v:num->A`;
                  `b:A`;`rb:A`] ERECRES_EDOMAIN) THEN ASM_REWRITE_TAC[];
             ALL_TAC] THEN
  SUBGOAL_THEN `dl:A = b` SUBST_ALL_TAC THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`rb:A`;`dl:A`;`b:A`]
                 EDOMAIN_UNIQUE) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(rc:A) IN D` ASSUME_TAC THENL
   [FIRST_ASSUM(fun th -> ACCEPT_TAC(MATCH_MP EOPAIR_IN th)); ALL_TAC] THEN
  MAP_EVERY EXISTS_TAC
   [`b:A`;`rb:A`;`Yv:A`;`rc:A`;`uu:A`;`vv:A`;`ru:A`;`rv:A`] THEN
   ASM_REWRITE_TAC[]);;

(* ------------------------------------------------------------------ *)
(* TABR_KEY_UNIQUE (eisfun-first 1b, the fixpoint crux): two entries of  *)
(* tabr sharing a key pr are equal.  Same rank-code -> (finj) same stage  *)
(* b -> same stage value -> STAGE_ENTRY_UNIQUE.  finj is an abstract      *)
(* injectivity hyp on f, discharged later by FINJ_STAGE.                  *)
let TABR_KEY_UNIQUE = prove
 (`!D (E:A->A->bool) B leq cc RG f v d r_att tabr u1 u2 pr ive1 ive2.
     model D E ZF_AX /\ ecba D E B leq /\
     B IN D /\ leq IN D /\ cc IN D /\ RG IN D /\ eisfun D E RG /\
     f IN D /\ eisfun D E f /\
     valuation D v /\ v 2 = B /\ v 3 = leq /\ v 4 = cc /\
       v 5 = RG /\ v 6 = f /\
     eordinal D E d /\
     erecres D E ebvattstep_form v d r_att /\ eranu D E r_att tabr /\
     (!a1 a2 rc. a1 IN D /\ a2 IN D /\ rc IN D /\ E a1 d /\ E a2 d /\
                 eapply D E f a1 rc /\ eapply D E f a2 rc ==> a1 = a2) /\
     u1 IN D /\ u2 IN D /\ pr IN D /\ ive1 IN D /\ ive2 IN D /\
     eopair D E pr ive1 u1 /\ eopair D E pr ive2 u2 /\
     E u1 tabr /\ E u2 tabr
     ==> u1 = u2`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  FIRST_X_ASSUM(fun th -> if is_forall(concl th) then LABEL_TAC "finj" th
                          else failwith "nf") THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`cc:A`;`RG:A`;
    `f:A`;`v:num->A`] EBVATTSTEP_SVTOTAL) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "sv") (LABEL_TAC "tot")) THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`cc:A`;`RG:A`;
    `f:A`;`v:num->A`;`d:A`;`r_att:A`;`tabr:A`;`u1:A`;`pr:A`;`ive1:A`]
                            TABR_ENTRY_STAGE) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `b1:A`
             (X_CHOOSE_THEN `rb1:A`
              (X_CHOOSE_THEN `Y1:A`
               (X_CHOOSE_THEN `rc1:A`
                (X_CHOOSE_THEN `uu1:A`
                 (X_CHOOSE_THEN `vv1:A`
                  (X_CHOOSE_THEN `ru1:A`
                   (X_CHOOSE_THEN `rv1:A` STRIP_ASSUME_TAC)))))))) THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`cc:A`;`RG:A`;
    `f:A`;`v:num->A`;`d:A`;`r_att:A`;`tabr:A`;`u2:A`;`pr:A`;`ive2:A`]
               TABR_ENTRY_STAGE) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `b2:A`
             (X_CHOOSE_THEN `rb2:A`
              (X_CHOOSE_THEN `Y2:A`
               (X_CHOOSE_THEN `rc2:A`
                (X_CHOOSE_THEN `uu2:A`
                 (X_CHOOSE_THEN `vv2:A`
                  (X_CHOOSE_THEN `ru2:A`
                   (X_CHOOSE_THEN `rv2:A` STRIP_ASSUME_TAC)))))))) THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`uu1:A`;`vv1:A`;`uu2:A`;`vv2:A`;
    `pr:A`] EOPAIR_INJ) THEN ASM_REWRITE_TAC[] THEN
  DISCH_THEN(CONJUNCTS_THEN2 SUBST_ALL_TAC SUBST_ALL_TAC) THEN
  SUBGOAL_THEN `ru1:A = ru2` SUBST_ALL_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`RG:A`;`uu2:A`;`ru1:A`;`ru2:A`]
                 EAPPLY_UNIQUE) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `rv1:A = rv2` SUBST_ALL_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`RG:A`;`vv2:A`;`rv1:A`;`rv2:A`]
                 EAPPLY_UNIQUE) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `rc1:A = rc2` SUBST_ALL_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`ru2:A`;`rv2:A`;`rc1:A`;`rc2:A`]
                 EOPAIR_UNIQUE) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  USE_THEN "finj" (MP_TAC o SPECL [`b1:A`;`b2:A`;`rc2:A`]) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN SUBST_ALL_TAC] THEN
  SUBGOAL_THEN `Y1:A = Y2` SUBST_ALL_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`ebvattstep_form`;`v:num->A`;
                  `b2:A`;`Y1:A`;`Y2:A`] EREC_UNIQUE) THEN ASM_REWRITE_TAC[];
             ALL_TAC] THEN
  MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`cc:A`;
    `RG:A`;`f:A`;`rb2:A`;`Y2:A`;`u1:A`;`u2:A`;`pr:A`;`ive1:A`;`ive2:A`]
    STAGE_ENTRY_UNIQUE) THEN ASM_REWRITE_TAC[]);;

(* ------------------------------------------------------------------ *)
(* DESTR5: thm-tactic combinator to destruct the 5-nested existential   *)
(* body of an ebvsubeq/ebvsubin membership fact (u,pr,inner,ival,eval).  *)
let DESTR5 uu pp ii iv ev =
  X_CHOOSE_THEN uu (CONJUNCTS_THEN2 ASSUME_TAC (CONJUNCTS_THEN2 ASSUME_TAC
   (X_CHOOSE_THEN pp
    (CONJUNCTS_THEN2 ASSUME_TAC (X_CHOOSE_THEN ii (CONJUNCTS_THEN2 ASSUME_TAC
    (X_CHOOSE_THEN iv
     (CONJUNCTS_THEN2 ASSUME_TAC (X_CHOOSE_THEN ev STRIP_ASSUME_TAC)))))))));;

(* EBVSUBEQ_ISFUN / EBVSUBIN_ISFUN (eisfun-first 1c): the projected      *)
(* tables sEQ=ebvsubeq tabr, sIN=ebvsubin tabr are FUNCTIONAL.  Elements  *)
(* are pairs; two entries with the same key come (TABR_KEY_UNIQUE) from   *)
(* the same tabr entry, hence agree.                                     *)
let EBVSUBEQ_ISFUN = prove
 (`!D (E:A->A->bool) B leq cc RG f v d r_att tabr sEQ.
     model D E ZF_AX /\ ecba D E B leq /\
     B IN D /\ leq IN D /\ cc IN D /\ RG IN D /\ eisfun D E RG /\
     f IN D /\ eisfun D E f /\
     valuation D v /\ v 2 = B /\ v 3 = leq /\ v 4 = cc /\
       v 5 = RG /\ v 6 = f /\
     eordinal D E d /\
     erecres D E ebvattstep_form v d r_att /\ eranu D E r_att tabr /\
     (!a1 a2 rc. a1 IN D /\ a2 IN D /\ rc IN D /\ E a1 d /\ E a2 d /\
                 eapply D E f a1 rc /\ eapply D E f a2 rc ==> a1 = a2) /\
     ebvsubeq D E tabr sEQ
     ==> eisfun D E sEQ`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  FIRST_X_ASSUM(fun th -> if is_forall(concl th) then LABEL_TAC "finj" th
                          else failwith "nf") THEN
  SUBGOAL_THEN `(sEQ:A) IN D` ASSUME_TAC THENL
   [FIRST_ASSUM(fun th -> ACCEPT_TAC(MATCH_MP EBVSUBEQ_IN th)); ALL_TAC] THEN
  FIRST_ASSUM(fun th -> let th2 = REWRITE_RULE[ebvsubeq] th in
                if is_conj(concl th2) then LABEL_TAC "mem" (CONJUNCT2 th2)
                else failwith "x") THEN
  REWRITE_TAC[eisfun] THEN REPEAT CONJ_TAC THENL
   [FIRST_ASSUM ACCEPT_TAC;
    GEN_TAC THEN STRIP_TAC THEN
    USE_THEN "mem"
      (fun m -> MP_TAC(EQ_MP (MP (SPEC `z:A` m) (ASSUME `(z:A) IN D`))
                             (ASSUME `(E:A->A->bool) (z:A) sEQ`))) THEN
    DISCH_THEN(DESTR5 `Uz:A` `prz:A` `innerz:A` `ivalz:A` `evalz:A`) THEN
    MAP_EVERY EXISTS_TAC [`prz:A`;`evalz:A`] THEN ASM_REWRITE_TAC[];
    REPEAT GEN_TAC THEN STRIP_TAC THEN
    SUBGOAL_THEN `(z:A) IN D /\ (z':A) IN D` STRIP_ASSUME_TAC THENL
     [CONJ_TAC THEN FIRST_ASSUM(fun th -> ACCEPT_TAC(MATCH_MP EOPAIR_IN th));
      ALL_TAC] THEN
    USE_THEN "mem"
      (fun m -> MP_TAC(EQ_MP (MP (SPEC `z:A` m) (ASSUME `(z:A) IN D`))
                             (ASSUME `(E:A->A->bool) (z:A) sEQ`))) THEN
    DISCH_THEN(DESTR5 `Uz:A` `prz:A` `innerz:A` `ivalz:A` `evalz:A`) THEN
    USE_THEN "mem"
      (fun m -> MP_TAC(EQ_MP (MP (SPEC `z':A` m) (ASSUME `(z':A) IN D`))
                             (ASSUME `(E:A->A->bool) (z':A) sEQ`))) THEN
    DISCH_THEN(DESTR5 `Up:A` `prp:A` `innerp:A` `ivalp:A` `evalp:A`) THEN
    MP_TAC(ISPECL
           [`D:A->bool`;`E:A->A->bool`;`u:A`;`w:A`;`prz:A`;`evalz:A`;`z:A`]
           EOPAIR_INJ) THEN ASM_REWRITE_TAC[] THEN
    DISCH_THEN(CONJUNCTS_THEN2 SUBST_ALL_TAC SUBST_ALL_TAC) THEN
    MP_TAC(ISPECL
           [`D:A->bool`;`E:A->A->bool`;`prz:A`;`w':A`;`prp:A`;`evalp:A`;`z':A`]
           EOPAIR_INJ) THEN ASM_REWRITE_TAC[] THEN
    DISCH_THEN(CONJUNCTS_THEN2 SUBST_ALL_TAC SUBST_ALL_TAC) THEN
    SUBGOAL_THEN `Uz:A = Up` SUBST_ALL_TAC THENL
     [MATCH_MP_TAC(ISPECL
                   [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`cc:A`;
                    `RG:A`;`f:A`;
                    `v:num->A`;`d:A`;`r_att:A`;`tabr:A`;`Uz:A`;`Up:A`;`prp:A`;
                    `innerz:A`;`innerp:A`]
        TABR_KEY_UNIQUE) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    MP_TAC(ISPECL
           [`D:A->bool`;`E:A->A->bool`;`prp:A`;`innerz:A`;`prp:A`;`innerp:A`;
            `Up:A`] EOPAIR_INJ) THEN ASM_REWRITE_TAC[] THEN
    DISCH_THEN SUBST_ALL_TAC THEN
    MP_TAC(ISPECL
           [`D:A->bool`;`E:A->A->bool`;`ivalz:A`;`evalz:A`;`ivalp:A`;`evalp:A`;
            `innerp:A`] EOPAIR_INJ) THEN ASM_REWRITE_TAC[] THEN
    DISCH_THEN(CONJUNCTS_THEN2 (K ALL_TAC) ACCEPT_TAC)]);;

let EBVSUBIN_ISFUN = prove
 (`!D (E:A->A->bool) B leq cc RG f v d r_att tabr sIN.
     model D E ZF_AX /\ ecba D E B leq /\
     B IN D /\ leq IN D /\ cc IN D /\ RG IN D /\ eisfun D E RG /\
     f IN D /\ eisfun D E f /\
     valuation D v /\ v 2 = B /\ v 3 = leq /\ v 4 = cc /\
       v 5 = RG /\ v 6 = f /\
     eordinal D E d /\
     erecres D E ebvattstep_form v d r_att /\ eranu D E r_att tabr /\
     (!a1 a2 rc. a1 IN D /\ a2 IN D /\ rc IN D /\ E a1 d /\ E a2 d /\
                 eapply D E f a1 rc /\ eapply D E f a2 rc ==> a1 = a2) /\
     ebvsubin D E tabr sIN
     ==> eisfun D E sIN`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  FIRST_X_ASSUM(fun th -> if is_forall(concl th) then LABEL_TAC "finj" th
                          else failwith "nf") THEN
  SUBGOAL_THEN `(sIN:A) IN D` ASSUME_TAC THENL
   [FIRST_ASSUM(fun th -> ACCEPT_TAC(MATCH_MP EBVSUBIN_IN th)); ALL_TAC] THEN
  FIRST_ASSUM(fun th -> let th2 = REWRITE_RULE[ebvsubin] th in
                if is_conj(concl th2) then LABEL_TAC "mem" (CONJUNCT2 th2)
                else failwith "x") THEN
  REWRITE_TAC[eisfun] THEN REPEAT CONJ_TAC THENL
   [FIRST_ASSUM ACCEPT_TAC;
    GEN_TAC THEN STRIP_TAC THEN
    USE_THEN "mem"
      (fun m -> MP_TAC(EQ_MP (MP (SPEC `z:A` m) (ASSUME `(z:A) IN D`))
                             (ASSUME `(E:A->A->bool) (z:A) sIN`))) THEN
    DISCH_THEN(DESTR5 `Uz:A` `prz:A` `innerz:A` `ivalz:A` `evalz:A`) THEN
    MAP_EVERY EXISTS_TAC [`prz:A`;`ivalz:A`] THEN ASM_REWRITE_TAC[];
    REPEAT GEN_TAC THEN STRIP_TAC THEN
    SUBGOAL_THEN `(z:A) IN D /\ (z':A) IN D` STRIP_ASSUME_TAC THENL
     [CONJ_TAC THEN FIRST_ASSUM(fun th -> ACCEPT_TAC(MATCH_MP EOPAIR_IN th));
      ALL_TAC] THEN
    USE_THEN "mem"
      (fun m -> MP_TAC(EQ_MP (MP (SPEC `z:A` m) (ASSUME `(z:A) IN D`))
                             (ASSUME `(E:A->A->bool) (z:A) sIN`))) THEN
    DISCH_THEN(DESTR5 `Uz:A` `prz:A` `innerz:A` `ivalz:A` `evalz:A`) THEN
    USE_THEN "mem"
      (fun m -> MP_TAC(EQ_MP (MP (SPEC `z':A` m) (ASSUME `(z':A) IN D`))
                             (ASSUME `(E:A->A->bool) (z':A) sIN`))) THEN
    DISCH_THEN(DESTR5 `Up:A` `prp:A` `innerp:A` `ivalp:A` `evalp:A`) THEN
    MP_TAC(ISPECL
           [`D:A->bool`;`E:A->A->bool`;`u:A`;`w:A`;`prz:A`;`ivalz:A`;`z:A`]
           EOPAIR_INJ) THEN ASM_REWRITE_TAC[] THEN
    DISCH_THEN(CONJUNCTS_THEN2 SUBST_ALL_TAC SUBST_ALL_TAC) THEN
    MP_TAC(ISPECL
           [`D:A->bool`;`E:A->A->bool`;`prz:A`;`w':A`;`prp:A`;`ivalp:A`;`z':A`]
           EOPAIR_INJ) THEN ASM_REWRITE_TAC[] THEN
    DISCH_THEN(CONJUNCTS_THEN2 SUBST_ALL_TAC SUBST_ALL_TAC) THEN
    SUBGOAL_THEN `Uz:A = Up` SUBST_ALL_TAC THENL
     [MATCH_MP_TAC(ISPECL
                   [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`cc:A`;
                    `RG:A`;`f:A`;
                    `v:num->A`;`d:A`;`r_att:A`;`tabr:A`;`Uz:A`;`Up:A`;`prp:A`;
                    `innerz:A`;`innerp:A`]
        TABR_KEY_UNIQUE) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    MP_TAC(ISPECL
           [`D:A->bool`;`E:A->A->bool`;`prp:A`;`innerz:A`;`prp:A`;`innerp:A`;
            `Up:A`] EOPAIR_INJ) THEN ASM_REWRITE_TAC[] THEN
    DISCH_THEN SUBST_ALL_TAC THEN
    MP_TAC(ISPECL
           [`D:A->bool`;`E:A->A->bool`;`ivalz:A`;`evalz:A`;`ivalp:A`;`evalp:A`;
            `innerp:A`] EOPAIR_INJ) THEN ASM_REWRITE_TAC[] THEN
    DISCH_THEN(CONJUNCTS_THEN2 ACCEPT_TAC (K ALL_TAC))]);;

(* ------------------------------------------------------------------------- *)
(* eisfun-first step 2: IN D-GUARDED congruence variants. The reading-eqn    *)
(* AGREE_IN/AGREE_EQ_L/AGREE_EQ_R establish the table-agreement iff only     *)
(* for values my/mx IN D (EBVSUBEQ_APPLY needs my IN D), and my NOT IN D     *)
(* cannot be excluded (eopair injectivity needs all 4 comps IN D). Since     *)
(* bvcomb / bveqcomb already IN D-guard their y,qy,my,pr, an IN D-guarded    *)
(* congruence hypothesis threads through the whole EBVIN_CONG/EBVEQ_CONG     *)
(* chain, so these _D variants accept the banked AGREE_* directly.           *)
let BVCOMB_CONG_D = prove
 (`!D (E:A->A->bool) B leq t t' v u c.
        (!y qy pr my. y IN D /\ qy IN D /\ pr IN D /\ my IN D /\
                      eapply D E v y qy /\ eopair D E u y pr
                      ==> (eapply D E t pr my <=> eapply D E t' pr my))
        ==> (bvcomb D E B leq t v u c <=> bvcomb D E B leq t' v u c)`,
  REPEAT GEN_TAC THEN REWRITE_TAC[bvcomb] THEN DISCH_TAC THEN
  ASM_MESON_TAC[]);;
let EBVINSET_CONG_D = prove
 (`!D (E:A->A->bool) B leq t t' v u S.
        (!y qy pr my. y IN D /\ qy IN D /\ pr IN D /\ my IN D /\
                      eapply D E v y qy /\ eopair D E u y pr
                      ==> (eapply D E t pr my <=> eapply D E t' pr my)) /\
        ebvinset D E B leq t v u S
        ==> ebvinset D E B leq t' v u S`,
  REPEAT GEN_TAC THEN
  DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "cong") MP_TAC) THEN
  REWRITE_TAC[ebvinset] THEN
  DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC (LABEL_TAC "mem")) THEN
  ASM_REWRITE_TAC[] THEN X_GEN_TAC `c:A` THEN DISCH_TAC THEN
  SUBGOAL_THEN `bvcomb D (E:A->A->bool) B leq t v u c <=>
                bvcomb D E B leq t' v u c`
   (SUBST1_TAC o SYM) THENL
   [MATCH_MP_TAC BVCOMB_CONG_D THEN USE_THEN "cong" ACCEPT_TAC;
    USE_THEN "mem" MATCH_MP_TAC THEN ASM_REWRITE_TAC[]]);;
let EBVIN_CONG_D = prove
 (`!D (E:A->A->bool) B leq t t' v u z z'.
        model D E ZF_AX /\ ecba D E B leq /\
        (!y qy pr my. y IN D /\ qy IN D /\ pr IN D /\ my IN D /\
                      eapply D E v y qy /\ eopair D E u y pr
                      ==> (eapply D E t pr my <=> eapply D E t' pr my)) /\
        ebvin D E B leq t v u z /\ ebvin D E B leq t' v u z'
        ==> z = z'`,
  REPEAT GEN_TAC THEN REWRITE_TAC[ebvin] THEN
  DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC (CONJUNCTS_THEN2 ASSUME_TAC
    (CONJUNCTS_THEN2 (LABEL_TAC "cong")
      (CONJUNCTS_THEN2 (X_CHOOSE_THEN `S:A` STRIP_ASSUME_TAC)
                       (X_CHOOSE_THEN `S':A` STRIP_ASSUME_TAC))))) THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`t:A`;`t':A`;
                 `v:A`;`u:A`;`S:A`] EBVINSET_CONG_D) THEN
  ANTS_TAC THENL
   [CONJ_TAC THENL [USE_THEN "cong" ACCEPT_TAC; FIRST_ASSUM ACCEPT_TAC];
    DISCH_TAC] THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`t':A`;`v:A`;`u:A`;
                 `S:A`;`S':A`] EBVINSET_UNIQUE) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN SUBST_ALL_TAC] THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`S':A`;`z:A`;`z':A`]
                ELUB_UNIQUE) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[] THEN MATCH_MP_TAC ECBA_IMP_PORDER THEN ASM_REWRITE_TAC[];
    DISCH_THEN ACCEPT_TAC]);;
let BVEQCOMB_CONG_D = prove
 (`!D (E:A->A->bool) B leq s s' u v c.
        (!x qx pr mx. x IN D /\ qx IN D /\ pr IN D /\ mx IN D /\
                      eapply D E u x qx /\ eopair D E x v pr
                      ==> (eapply D E s pr mx <=> eapply D E s' pr mx))
        ==> (bveqcomb D E B leq s u v c <=> bveqcomb D E B leq s' u v c)`,
  REPEAT GEN_TAC THEN REWRITE_TAC[bveqcomb] THEN DISCH_TAC THEN
  ASM_MESON_TAC[]);;
let BVEQCOMBSET_CONG_D = prove
 (`!D (E:A->A->bool) B leq s s' u v S.
        (!x qx pr mx. x IN D /\ qx IN D /\ pr IN D /\ mx IN D /\
                      eapply D E u x qx /\ eopair D E x v pr
                      ==> (eapply D E s pr mx <=> eapply D E s' pr mx)) /\
        bveqcombset D E B leq s u v S
        ==> bveqcombset D E B leq s' u v S`,
  REPEAT GEN_TAC THEN
  DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "cong") MP_TAC) THEN
  REWRITE_TAC[bveqcombset] THEN
  DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC (LABEL_TAC "mem")) THEN
  ASM_REWRITE_TAC[] THEN X_GEN_TAC `c:A` THEN DISCH_TAC THEN
  SUBGOAL_THEN `bveqcomb D (E:A->A->bool) B leq s u v c <=>
                bveqcomb D E B leq s' u v c`
   (SUBST1_TAC o SYM) THENL
   [MATCH_MP_TAC BVEQCOMB_CONG_D THEN USE_THEN "cong" ACCEPT_TAC;
    USE_THEN "mem" MATCH_MP_TAC THEN ASM_REWRITE_TAC[]]);;
let EBVEQ_CONG_D = prove
 (`!D (E:A->A->bool) B leq s s' u v z z'.
        model D E ZF_AX /\ ecba D E B leq /\
        (!x qx pr mx. x IN D /\ qx IN D /\ pr IN D /\ mx IN D /\
                      eapply D E u x qx /\ eopair D E x v pr
                      ==> (eapply D E s pr mx <=> eapply D E s' pr mx)) /\
        (!y qy pr my. y IN D /\ qy IN D /\ pr IN D /\ my IN D /\
                      eapply D E v y qy /\ eopair D E y u pr
                      ==> (eapply D E s pr my <=> eapply D E s' pr my)) /\
        ebveq D E B leq s u v z /\ ebveq D E B leq s' u v z'
        ==> z = z'`,
  REPEAT GEN_TAC THEN REWRITE_TAC[ebveq] THEN
  DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC (CONJUNCTS_THEN2 ASSUME_TAC
    (CONJUNCTS_THEN2 (LABEL_TAC "congL") (CONJUNCTS_THEN2 (LABEL_TAC "congR")
      (CONJUNCTS_THEN2
        (X_CHOOSE_THEN `SL:A` (X_CHOOSE_THEN `SR:A` (X_CHOOSE_THEN `gL:A`
          (X_CHOOSE_THEN `gR:A` STRIP_ASSUME_TAC))))
        (X_CHOOSE_THEN `SL':A` (X_CHOOSE_THEN `SR':A` (X_CHOOSE_THEN `gL':A`
          (X_CHOOSE_THEN `gR':A` STRIP_ASSUME_TAC))))))))) THEN
  SUBGOAL_THEN `eporder D (E:A->A->bool) B leq` ASSUME_TAC THENL
   [MATCH_MP_TAC ECBA_IMP_PORDER THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`s:A`;`s':A`;
                 `u:A`;`v:A`;`SL:A`] BVEQCOMBSET_CONG_D) THEN
  ANTS_TAC THENL
   [CONJ_TAC THENL [USE_THEN "congL" ACCEPT_TAC; FIRST_ASSUM ACCEPT_TAC];
    DISCH_TAC] THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`s:A`;`s':A`;
                 `v:A`;`u:A`;`SR:A`] BVEQCOMBSET_CONG_D) THEN
  ANTS_TAC THENL
   [CONJ_TAC THENL [USE_THEN "congR" ACCEPT_TAC; FIRST_ASSUM ACCEPT_TAC];
    DISCH_TAC] THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`s':A`;`u:A`;`v:A`;
                 `SL:A`;`SL':A`] BVEQCOMBSET_UNIQUE) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN SUBST_ALL_TAC] THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`s':A`;`v:A`;`u:A`;
                 `SR:A`;`SR':A`] BVEQCOMBSET_UNIQUE) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN SUBST_ALL_TAC] THEN
  MP_TAC(ISPECL
         [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`SL':A`;`gL:A`;`gL':A`]
         EGLB_UNIQUE) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN SUBST_ALL_TAC] THEN
  MP_TAC(ISPECL
         [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`SR':A`;`gR:A`;`gR':A`]
         EGLB_UNIQUE) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN SUBST_ALL_TAC] THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`gL':A`;`gR':A`;
                 `z:A`;`z':A`] EMEET_UNIQUE) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC]);;

(* ------------------------------------------------------------------ *)
(* eisfun-first step 3: the two READING EQUATIONS. At key <u,v0> the      *)
(* fixpoint tables read as the intended Boolean values:                   *)
(*   sIN@<u,v0> = ebvin(sEQ) v0 u   (READING_IN)                          *)
(*   sEQ@<u,v0> = ebveq(sIN) u v0   (READING_EQ)                          *)
(* via PAIR_COVERAGE + EBVATT_VALUE_AT + EBVATTSTEP_ENTRY + EBVSUB*_APPLY  *)
(* + AGREE_* fed to EBVIN_CONG_D / EBVEQ_CONG_D.                          *)
let EBVATT_READING_IN = prove
 (`!D (E:A->A->bool) B leq cc RG f v d r_att tabr sIN sEQ c yc kk q rr w u v0.
     model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\ cc IN D /\
     RG IN D /\ eisfun D E RG /\ f IN D /\ eisfun D E f /\
     valuation D v /\ v 2 = B /\ v 3 = leq /\ v 4 = cc /\
       v 5 = RG /\ v 6 = f /\
     w IN D /\
     (!x r. x IN D /\ E x w /\ ebnrank D E B x r ==> eapply D E RG x r) /\
     ecross D E w w cc /\
     eordinal D E d /\ erecres D E ebvattstep_form v d r_att /\
     eranu D E r_att tabr /\ ebvsubin D E tabr sIN /\ ebvsubeq D E tabr sEQ /\
     c IN D /\ yc IN D /\ eordinal D E c /\ ebnstage D E B c yc /\
     esuc D E c kk /\ eordinal D E kk /\
     (!z. z IN D /\ E z w ==> E z yc) /\
     q IN D /\ rr IN D /\
     (!z. z IN D
          ==> (E z q <=>
               ?a b. a IN D /\ b IN D /\ E a kk /\ E b kk /\
                 eopair D E a b z)) /\
     (!z1 z2. z1 IN D /\ z2 IN D
              ==> (erel D E rr z1 z2 <=> E z1 q /\ E z2 q /\
                   emlex D E z1 z2)) /\
     (!zz t. zz IN D /\ t IN D
             ==> (eapply D E f zz t <=> E zz d /\ eoenum D E q rr zz t)) /\
     (!z1 t. z1 IN D /\ t IN D /\ eapply D E f z1 t ==> E z1 d /\ E t q) /\
     (!t. t IN D /\ E t q ==> ?zz. zz IN D /\ E zz d /\ eapply D E f zz t) /\
     (!z. z IN D /\ E z w ==> bname D E B z) /\
     u IN D /\ v0 IN D /\ E u w /\ E v0 w
     ==> ?pr val. eopair D E u v0 pr /\ eapply D E sIN pr val /\
                  ebvin D E B leq sEQ v0 u val`,
  (REPEAT GEN_TAC THEN STRIP_TAC) THEN
  (SUBGOAL_THEN `(sEQ:A) IN D` ASSUME_TAC THENL
   [FIRST_ASSUM(fun th -> ACCEPT_TAC(MATCH_MP EBVSUBEQ_IN th)); ALL_TAC]) THEN
  (MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `B:A`; `c:A`; `kk:A`;
    `yc:A`; `w:A`; `q:A`; `d:A`; `f:A`; `RG:A`; `cc:A`; `u:A`; `v0:A`]
    PAIR_COVERAGE) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `pr:A` (X_CHOOSE_THEN `ru:A` (X_CHOOSE_THEN `rv:A`
    (X_CHOOSE_THEN `rc:A` (X_CHOOSE_THEN `delta:A` STRIP_ASSUME_TAC)))))) THEN
  (MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `B:A`; `leq:A`; `cc:A`;
    `RG:A`; `f:A`; `v:num->A`; `d:A`; `r_att:A`; `delta:A`]
      EBVATT_VALUE_AT) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `G:A`
             (X_CHOOSE_THEN `r_delta:A` STRIP_ASSUME_TAC))) THEN
  (MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `B:A`; `leq:A`; `cc:A`;
    `RG:A`; `f:A`; `v:num->A`] EBVATTSTEP_SVTOTAL) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "sv") (LABEL_TAC "tot"))) THEN
  (SUBGOAL_THEN `eordinal D (E:A->A->bool) delta` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `d:A`; `delta:A`]
      EORDINAL_MEMBER) THEN ASM_REWRITE_TAC[]; ALL_TAC]) THEN
  (SUBGOAL_THEN `edomain D (E:A->A->bool) r_delta delta` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`; `E:A->A->bool`; `ebvattstep_form`; `v:num->A`;
                  `delta:A`; `r_delta:A`] ERECRES_EDOMAIN) THEN
    REPEAT CONJ_TAC THENL
     [FIRST_ASSUM ACCEPT_TAC; FIRST_ASSUM ACCEPT_TAC; USE_THEN "sv" ACCEPT_TAC;
      USE_THEN "tot" ACCEPT_TAC; FIRST_ASSUM ACCEPT_TAC;
      FIRST_ASSUM ACCEPT_TAC];
    ALL_TAC]) THEN
  (SUBGOAL_THEN `(r_delta:A) IN D` ASSUME_TAC THENL
   [FIRST_ASSUM(ACCEPT_TAC o CONJUNCT1 o REWRITE_RULE[erecres]); ALL_TAC]) THEN
  (MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `r_delta:A`] ERANU_EXISTS) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `tabr_d:A`)) THEN
  (MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `tabr_d:A`]
          EBVSUBEQ_PRED_EXISTS) THEN
   ANTS_TAC THENL [ASM_MESON_TAC[ERANU_IN]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_TAC `sEQ_d:A`)) THEN
  (MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `tabr_d:A`]
          EBVSUBIN_PRED_EXISTS) THEN
   ANTS_TAC THENL [ASM_MESON_TAC[ERANU_IN]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_TAC `sIN_d:A`)) THEN
  (SUBGOAL_THEN `(sEQ_d:A) IN D /\ (sIN_d:A) IN D` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[EBVSUBEQ_IN; EBVSUBIN_IN]; ALL_TAC]) THEN
  (SUBGOAL_THEN `?iva:A. ebvin D E B leq sEQ_d v0 u iva` STRIP_ASSUME_TAC THENL
   [MATCH_MP_TAC EBVIN_EXISTS THEN ASM_REWRITE_TAC[]; ALL_TAC]) THEN
  (SUBGOAL_THEN `(iva:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[EBVIN_IN]; ALL_TAC]) THEN
  (SUBGOAL_THEN `?eva:A. ebveq D E B leq sIN_d u v0 eva` STRIP_ASSUME_TAC THENL
   [MATCH_MP_TAC EBVEQ_EXISTS THEN ASM_REWRITE_TAC[]; ALL_TAC]) THEN
  (SUBGOAL_THEN `(eva:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[EBVEQ_IN]; ALL_TAC]) THEN
  (SUBGOAL_THEN `?ive:A. eopair D E iva eva ive` STRIP_ASSUME_TAC THENL
   [MATCH_MP_TAC EOPAIR_EXISTS THEN ASM_REWRITE_TAC[]; ALL_TAC]) THEN
  (SUBGOAL_THEN `(ive:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[EOPAIR_IN]; ALL_TAC]) THEN
  (SUBGOAL_THEN `?e:A. eopair D E pr ive e` STRIP_ASSUME_TAC THENL
   [MATCH_MP_TAC EOPAIR_EXISTS THEN ASM_REWRITE_TAC[]; ALL_TAC]) THEN
  (SUBGOAL_THEN `(e:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[EOPAIR_IN]; ALL_TAC]) THEN
  (SUBGOAL_THEN `(E:A->A->bool) e G` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL
     [`D:A->bool`; `E:A->A->bool`; `B:A`; `leq:A`; `cc:A`; `RG:A`; `f:A`;
      `r_delta:A`; `G:A`; `delta:A`; `tabr_d:A`; `sEQ_d:A`; `sIN_d:A`; `u:A`;
      `v0:A`; `pr:A`; `ru:A`; `rv:A`; `rc:A`; `iva:A`; `eva:A`; `ive:A`; `e:A`]
      EBVATTSTEP_ENTRY) THEN
    REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC]) THEN
  (SUBGOAL_THEN `eordinal D E ru /\ eordinal D (E:A->A->bool) rv`
  STRIP_ASSUME_TAC THENL [ASM_MESON_TAC[EBNRANK_ORDINAL]; ALL_TAC]) THEN
  (SUBGOAL_THEN `(E:A->A->bool) e tabr` ASSUME_TAC THENL
   [MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `v:num->A`; `d:A`; `r_att:A`;
      `tabr:A`; `e:A`] TABR_MEM) THEN
    ASM_REWRITE_TAC[] THEN DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    MAP_EVERY EXISTS_TAC [`delta:A`; `G:A`] THEN ASM_REWRITE_TAC[] THEN
    MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `ebvattstep_form`; `v:num->A`;
      `d:A`; `r_att:A`; `delta:A`; `G:A`] ERECRES_APPLY) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC]) THEN
  (SUBGOAL_THEN `eapply D (E:A->A->bool) sIN pr iva` ASSUME_TAC THENL
   [MP_TAC(ISPECL
           [`D:A->bool`; `E:A->A->bool`; `tabr:A`; `sIN:A`; `pr:A`; `iva:A`]
           EBVSUBIN_APPLY) THEN
    ASM_REWRITE_TAC[] THEN DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    MAP_EVERY EXISTS_TAC [`eva:A`; `ive:A`; `e:A`] THEN ASM_REWRITE_TAC[];
    ALL_TAC]) THEN
  (SUBGOAL_THEN
   `!y qy pr my.
        y IN D /\ qy IN D /\ pr IN D /\ my IN D /\
        eapply D E v0 y qy /\ eopair D E u y pr
        ==> (eapply D E sEQ_d pr my <=> eapply D (E:A->A->bool) sEQ pr my)`
  (LABEL_TAC "agr") THENL
   [MATCH_MP_TAC(ISPECL
     [`D:A->bool`; `E:A->A->bool`; `B:A`; `leq:A`; `cc:A`; `RG:A`; `f:A`;
      `v:num->A`; `d:A`; `r_att:A`; `tabr:A`; `sEQ:A`; `delta:A`; `r_delta:A`;
      `tabr_d:A`; `sEQ_d:A`; `q:A`; `rr:A`; `kk:A`; `w:A`; `u:A`;
      `v0:A`; `ru:A`;
      `rv:A`; `rc:A`] AGREE_IN) THEN
    REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC]) THEN
  (SUBGOAL_THEN `?iva2:A. ebvin D E B leq sEQ v0 u iva2` STRIP_ASSUME_TAC THENL
   [MATCH_MP_TAC EBVIN_EXISTS THEN ASM_REWRITE_TAC[]; ALL_TAC]) THEN
  (SUBGOAL_THEN `iva:A = iva2` SUBST_ALL_TAC THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`sEQ_d:A`;
      `sEQ:A`;`v0:A`;`u:A`;`iva:A`;`iva2:A`] EBVIN_CONG_D) THEN
    REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC]) THEN
  (MAP_EVERY EXISTS_TAC [`pr:A`; `iva2:A`] THEN ASM_REWRITE_TAC[]));;

let EBVATT_READING_EQ = prove
 (`!D (E:A->A->bool) B leq cc RG f v d r_att tabr sIN sEQ c yc kk q rr w u v0.
     model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\ cc IN D /\
     RG IN D /\ eisfun D E RG /\ f IN D /\ eisfun D E f /\
     valuation D v /\ v 2 = B /\ v 3 = leq /\ v 4 = cc /\
       v 5 = RG /\ v 6 = f /\
     w IN D /\
     (!x r. x IN D /\ E x w /\ ebnrank D E B x r ==> eapply D E RG x r) /\
     ecross D E w w cc /\
     eordinal D E d /\ erecres D E ebvattstep_form v d r_att /\
     eranu D E r_att tabr /\ ebvsubin D E tabr sIN /\ ebvsubeq D E tabr sEQ /\
     c IN D /\ yc IN D /\ eordinal D E c /\ ebnstage D E B c yc /\
     esuc D E c kk /\ eordinal D E kk /\
     (!z. z IN D /\ E z w ==> E z yc) /\
     q IN D /\ rr IN D /\
     (!z. z IN D
          ==> (E z q <=>
               ?a b. a IN D /\ b IN D /\ E a kk /\ E b kk /\
                 eopair D E a b z)) /\
     (!z1 z2. z1 IN D /\ z2 IN D
              ==> (erel D E rr z1 z2 <=> E z1 q /\ E z2 q /\
                   emlex D E z1 z2)) /\
     (!zz t. zz IN D /\ t IN D
             ==> (eapply D E f zz t <=> E zz d /\ eoenum D E q rr zz t)) /\
     (!z1 t. z1 IN D /\ t IN D /\ eapply D E f z1 t ==> E z1 d /\ E t q) /\
     (!t. t IN D /\ E t q ==> ?zz. zz IN D /\ E zz d /\ eapply D E f zz t) /\
     (!z. z IN D /\ E z w ==> bname D E B z) /\
     u IN D /\ v0 IN D /\ E u w /\ E v0 w
     ==>
     ?pr val. eopair D E u v0 pr /\ eapply D E sEQ pr val /\
       ebveq D E B leq sIN u v0 val`,
  (REPEAT GEN_TAC THEN STRIP_TAC) THEN
  (SUBGOAL_THEN `(sIN:A) IN D` ASSUME_TAC THENL
   [FIRST_ASSUM(fun th -> ACCEPT_TAC(MATCH_MP EBVSUBIN_IN th)); ALL_TAC]) THEN
  (MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `B:A`; `c:A`; `kk:A`;
    `yc:A`; `w:A`; `q:A`; `d:A`; `f:A`; `RG:A`; `cc:A`; `u:A`; `v0:A`]
