  (LABEL_TAC "agrL") THENL
   [MATCH_MP_TAC(ISPECL
     [`D:A->bool`; `E:A->A->bool`; `B:A`; `leq:A`; `cc:A`; `RG:A`; `f:A`;
      `v:num->A`; `d:A`; `r_att:A`; `tabr:A`; `sIN:A`; `delta:A`; `r_delta:A`;
      `tabr_d:A`; `sIN_d:A`; `q:A`; `rr:A`; `kk:A`; `w:A`; `u:A`;
      `v0:A`; `ru:A`;
      `rv:A`; `rc:A`] AGREE_EQ_L) THEN
    REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC]) THEN
  (SUBGOAL_THEN
   `!y qy pr my. y IN D /\ qy IN D /\ pr IN D /\ my IN D /\
        eapply D E v0 y qy /\ eopair D E y u pr
        ==> (eapply D E sIN_d pr my <=> eapply D (E:A->A->bool) sIN pr my)`
  (LABEL_TAC "agrR") THENL
   [MATCH_MP_TAC(ISPECL
     [`D:A->bool`; `E:A->A->bool`; `B:A`; `leq:A`; `cc:A`; `RG:A`; `f:A`;
      `v:num->A`; `d:A`; `r_att:A`; `tabr:A`; `sIN:A`; `delta:A`; `r_delta:A`;
      `tabr_d:A`; `sIN_d:A`; `q:A`; `rr:A`; `kk:A`; `w:A`; `u:A`;
      `v0:A`; `ru:A`;
      `rv:A`; `rc:A`] AGREE_EQ_R) THEN
    REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC]) THEN
  (SUBGOAL_THEN `?eva2:A. ebveq D E B leq sIN u v0 eva2` STRIP_ASSUME_TAC THENL
   [MATCH_MP_TAC EBVEQ_EXISTS THEN ASM_REWRITE_TAC[]; ALL_TAC]) THEN
  (SUBGOAL_THEN `eva:A = eva2` SUBST_ALL_TAC THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`sIN_d:A`;
      `sIN:A`;`u:A`;`v0:A`;`eva:A`;`eva2:A`] EBVEQ_CONG_D) THEN
    REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC]) THEN
  (MAP_EVERY EXISTS_TAC [`pr:A`; `eva2:A`] THEN ASM_REWRITE_TAC[]));;

(* ------------------------------------------------------------------ *)
(* eisfun-first step 4: DOMAIN of the fixpoint tables = cc = w x w.       *)
(* edomain sIN cc / edomain sEQ cc.  FWD: ecross-member + READING_*.      *)
(* BWD: EBVSUBIN/EQ_APPLY -> tabr entry -> TABR_ENTRY_STAGE (no finj) ->   *)
(* EBVATTSTEP_ENTRY_FWD (E pr' c) -> EOPAIR_INJ.                            *)
let EBVATT_DOMAIN_IN = prove
 (`!D (E:A->A->bool) B leq cc RG f v d r_att tabr sIN sEQ c yc kk q rr w u v0.
     model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\ cc IN D /\
     RG IN D /\ eisfun D E RG /\ f IN D /\ eisfun D E f /\
     valuation D v /\ v 2 = B /\ v 3 = leq /\ v 4 = cc /\
       v 5 = RG /\ v 6 = f /\
     w IN D /\
     (!x r. x IN D /\ E x w /\ ebnrank D E B x r ==> eapply D E RG x r) /\
     ecross D E w w cc /\
     eordinal D E d /\ erecres D E ebvattstep_form v d r_att /\
     eranu D E r_att tabr /\ ebvsubin D E tabr sIN /\ ebvsubeq D E tabr sEQ /\
     c IN D /\ yc IN D /\ eordinal D E c /\ ebnstage D E B c yc /\
     esuc D E c kk /\ eordinal D E kk /\
     (!z. z IN D /\ E z w ==> E z yc) /\
     q IN D /\ rr IN D /\
     (!z. z IN D
          ==> (E z q <=>
               ?a b. a IN D /\ b IN D /\ E a kk /\ E b kk /\
                 eopair D E a b z)) /\
     (!z1 z2. z1 IN D /\ z2 IN D
              ==> (erel D E rr z1 z2 <=> E z1 q /\ E z2 q /\
                   emlex D E z1 z2)) /\
     (!zz t. zz IN D /\ t IN D
             ==> (eapply D E f zz t <=> E zz d /\ eoenum D E q rr zz t)) /\
     (!z1 t. z1 IN D /\ t IN D /\ eapply D E f z1 t ==> E z1 d /\ E t q) /\
     (!t. t IN D /\ E t q ==> ?zz. zz IN D /\ E zz d /\ eapply D E f zz t) /\
     (!z. z IN D /\ E z w ==> bname D E B z) /\
     u IN D /\ v0 IN D /\ E u w /\ E v0 w
     ==> edomain D E sIN cc`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  REWRITE_TAC[edomain] THEN CONJ_TAC THENL
   [(FIRST_ASSUM(ACCEPT_TAC o CONJUNCT1 o REWRITE_RULE[ecross]));
    X_GEN_TAC `uu:A` THEN DISCH_TAC THEN EQ_TAC THENL
     [(DISCH_TAC) THEN
     (MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`w:A`;`w:A`;`cc:A`;`uu:A`]
    ECROSS_MEMBER) THEN ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `a:A` (X_CHOOSE_THEN `b:A` STRIP_ASSUME_TAC))) THEN
     (MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`cc:A`;`RG:A`;
    `f:A`;`v:num->A`;`d:A`;`r_att:A`;`tabr:A`;`sIN:A`;`sEQ:A`;`c:A`;
    `yc:A`;`kk:A`;
    `q:A`;`rr:A`;`w:A`;`a:A`;`b:A`] EBVATT_READING_IN) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `prr:A`
             (X_CHOOSE_THEN `vl:A` STRIP_ASSUME_TAC))) THEN
     (SUBGOAL_THEN `prr:A = uu` SUBST_ALL_TAC THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`a:A`;`b:A`;`prr:A`;`uu:A`]
      EOPAIR_UNIQUE) THEN ASM_REWRITE_TAC[]; ALL_TAC]) THEN
     (REWRITE_TAC[eindom] THEN EXISTS_TAC `vl:A` THEN
  CONJ_TAC THENL [ASM_MESON_TAC[EBVIN_IN]; FIRST_ASSUM ACCEPT_TAC]);
      (REWRITE_TAC[eindom] THEN
  DISCH_THEN(X_CHOOSE_THEN `vl:A` STRIP_ASSUME_TAC)) THEN
     (MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`tabr:A`;`sIN:A`;`uu:A`;`vl:A`]
    EBVSUBIN_APPLY) THEN ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `evl:A`
             (X_CHOOSE_THEN `innr:A` (X_CHOOSE_THEN `uE:A`
                                      STRIP_ASSUME_TAC)))) THEN
     (MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`cc:A`;`RG:A`;
    `f:A`;`v:num->A`;`d:A`;`r_att:A`;`tabr:A`;`uE:A`;`uu:A`;`innr:A`]
               TABR_ENTRY_STAGE) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `bb:A` (X_CHOOSE_THEN `rbb:A` (X_CHOOSE_THEN `YY:A`
    (X_CHOOSE_THEN `rcc:A` (X_CHOOSE_THEN `uu2:A` (X_CHOOSE_THEN `vv2:A`
    (X_CHOOSE_THEN `ru2:A`
     (X_CHOOSE_THEN `rv2:A` STRIP_ASSUME_TAC))))))))) THEN
     (MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`cc:A`;`RG:A`;
    `f:A`;`rbb:A`;`YY:A`;`uE:A`] EBVATTSTEP_ENTRY_FWD) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `dl2:A`
             (X_CHOOSE_THEN `tb2:A`
              (X_CHOOSE_THEN `sE2:A`
               (X_CHOOSE_THEN `sI2:A`
                (X_CHOOSE_THEN `rc2b:A`
                 (X_CHOOSE_THEN `pr2:A`
                  (X_CHOOSE_THEN `uA:A`
                   (X_CHOOSE_THEN `vA:A`
                    (X_CHOOSE_THEN `rA:A`
                     (X_CHOOSE_THEN `rB:A`
                      (X_CHOOSE_THEN `ivaA:A`
                       (X_CHOOSE_THEN `evaA:A`
                        (X_CHOOSE_THEN `iveA:A`
                         STRIP_ASSUME_TAC)))))))))))))) THEN
     (MP_TAC(ISPECL
             [`D:A->bool`;`E:A->A->bool`;`pr2:A`;`iveA:A`;`uu:A`;`innr:A`;
              `uE:A`] EOPAIR_INJ) THEN ASM_REWRITE_TAC[] THEN
  DISCH_THEN(CONJUNCTS_THEN2 (SUBST_ALL_TAC o SYM) (K ALL_TAC))) THEN
     (FIRST_ASSUM ACCEPT_TAC)]]);;

let EBVATT_DOMAIN_EQ = prove
 (`!D (E:A->A->bool) B leq cc RG f v d r_att tabr sIN sEQ c yc kk q rr w u v0.
     model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\ cc IN D /\
     RG IN D /\ eisfun D E RG /\ f IN D /\ eisfun D E f /\
     valuation D v /\ v 2 = B /\ v 3 = leq /\ v 4 = cc /\
       v 5 = RG /\ v 6 = f /\
     w IN D /\
     (!x r. x IN D /\ E x w /\ ebnrank D E B x r ==> eapply D E RG x r) /\
     ecross D E w w cc /\
     eordinal D E d /\ erecres D E ebvattstep_form v d r_att /\
     eranu D E r_att tabr /\ ebvsubin D E tabr sIN /\ ebvsubeq D E tabr sEQ /\
     c IN D /\ yc IN D /\ eordinal D E c /\ ebnstage D E B c yc /\
     esuc D E c kk /\ eordinal D E kk /\
     (!z. z IN D /\ E z w ==> E z yc) /\
     q IN D /\ rr IN D /\
     (!z. z IN D
          ==> (E z q <=>
               ?a b. a IN D /\ b IN D /\ E a kk /\ E b kk /\
                 eopair D E a b z)) /\
     (!z1 z2. z1 IN D /\ z2 IN D
              ==> (erel D E rr z1 z2 <=> E z1 q /\ E z2 q /\
                   emlex D E z1 z2)) /\
     (!zz t. zz IN D /\ t IN D
             ==> (eapply D E f zz t <=> E zz d /\ eoenum D E q rr zz t)) /\
     (!z1 t. z1 IN D /\ t IN D /\ eapply D E f z1 t ==> E z1 d /\ E t q) /\
     (!t. t IN D /\ E t q ==> ?zz. zz IN D /\ E zz d /\ eapply D E f zz t) /\
     (!z. z IN D /\ E z w ==> bname D E B z) /\
     u IN D /\ v0 IN D /\ E u w /\ E v0 w
     ==> edomain D E sEQ cc`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  REWRITE_TAC[edomain] THEN CONJ_TAC THENL
   [(FIRST_ASSUM(ACCEPT_TAC o CONJUNCT1 o REWRITE_RULE[ecross]));
    X_GEN_TAC `uu:A` THEN DISCH_TAC THEN EQ_TAC THENL
     [(DISCH_TAC) THEN
     (MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`w:A`;`w:A`;`cc:A`;`uu:A`]
    ECROSS_MEMBER) THEN ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `a:A` (X_CHOOSE_THEN `b:A` STRIP_ASSUME_TAC))) THEN
     (MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`cc:A`;`RG:A`;
    `f:A`;`v:num->A`;`d:A`;`r_att:A`;`tabr:A`;`sIN:A`;`sEQ:A`;`c:A`;
    `yc:A`;`kk:A`;
    `q:A`;`rr:A`;`w:A`;`a:A`;`b:A`] EBVATT_READING_EQ) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `prr:A`
             (X_CHOOSE_THEN `vl:A` STRIP_ASSUME_TAC))) THEN
     (SUBGOAL_THEN `prr:A = uu` SUBST_ALL_TAC THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`a:A`;`b:A`;`prr:A`;`uu:A`]
      EOPAIR_UNIQUE) THEN ASM_REWRITE_TAC[]; ALL_TAC]) THEN
     (REWRITE_TAC[eindom] THEN EXISTS_TAC `vl:A` THEN
  CONJ_TAC THENL [ASM_MESON_TAC[EBVEQ_IN]; FIRST_ASSUM ACCEPT_TAC]);
      (REWRITE_TAC[eindom] THEN
  DISCH_THEN(X_CHOOSE_THEN `vl:A` STRIP_ASSUME_TAC)) THEN
     (MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`tabr:A`;`sEQ:A`;`uu:A`;`vl:A`]
    EBVSUBEQ_APPLY) THEN ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `evl:A`
             (X_CHOOSE_THEN `innr:A` (X_CHOOSE_THEN `uE:A`
                                      STRIP_ASSUME_TAC)))) THEN
     (MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`cc:A`;`RG:A`;
    `f:A`;`v:num->A`;`d:A`;`r_att:A`;`tabr:A`;`uE:A`;`uu:A`;`innr:A`]
               TABR_ENTRY_STAGE) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `bb:A` (X_CHOOSE_THEN `rbb:A` (X_CHOOSE_THEN `YY:A`
    (X_CHOOSE_THEN `rcc:A` (X_CHOOSE_THEN `uu2:A` (X_CHOOSE_THEN `vv2:A`
    (X_CHOOSE_THEN `ru2:A`
     (X_CHOOSE_THEN `rv2:A` STRIP_ASSUME_TAC))))))))) THEN
     (MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`cc:A`;`RG:A`;
    `f:A`;`rbb:A`;`YY:A`;`uE:A`] EBVATTSTEP_ENTRY_FWD) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `dl2:A`
             (X_CHOOSE_THEN `tb2:A`
              (X_CHOOSE_THEN `sE2:A`
               (X_CHOOSE_THEN `sI2:A`
                (X_CHOOSE_THEN `rc2b:A`
                 (X_CHOOSE_THEN `pr2:A`
                  (X_CHOOSE_THEN `uA:A`
                   (X_CHOOSE_THEN `vA:A`
                    (X_CHOOSE_THEN `rA:A`
                     (X_CHOOSE_THEN `rB:A`
                      (X_CHOOSE_THEN `ivaA:A`
                       (X_CHOOSE_THEN `evaA:A`
                        (X_CHOOSE_THEN `iveA:A`
                         STRIP_ASSUME_TAC)))))))))))))) THEN
     (MP_TAC(ISPECL
             [`D:A->bool`;`E:A->A->bool`;`pr2:A`;`iveA:A`;`uu:A`;`innr:A`;
              `uE:A`] EOPAIR_INJ) THEN ASM_REWRITE_TAC[] THEN
  DISCH_THEN(CONJUNCTS_THEN2 (SUBST_ALL_TAC o SYM) (K ALL_TAC))) THEN
     (FIRST_ASSUM ACCEPT_TAC)]]);;

(* ------------------------------------------------------------------ *)
(* eisfun-first step 5 CORE: ebvatt from the tables. Given the reading    *)
(* context + f-injectivity (finj), the fixpoint tables sIN,sEQ form a     *)
(* Boolean-value attempt: clauses 1/2 = EBVSUBIN/EQ_ISFUN, clause 3 =     *)
(* EBVATT_DOMAIN_IN/EQ, clauses 4/5 = EBVATT_READING_IN/EQ.               *)
let EBVATT_FROM_TABLES = prove
 (`!D (E:A->A->bool) B leq cc RG f v d r_att tabr sIN sEQ c yc kk q rr w u v0.
     model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\ cc IN D /\
     RG IN D /\ eisfun D E RG /\ f IN D /\ eisfun D E f /\
     valuation D v /\ v 2 = B /\ v 3 = leq /\ v 4 = cc /\
       v 5 = RG /\ v 6 = f /\
     w IN D /\
     (!x r. x IN D /\ E x w /\ ebnrank D E B x r ==> eapply D E RG x r) /\
     ecross D E w w cc /\
     eordinal D E d /\ erecres D E ebvattstep_form v d r_att /\
     eranu D E r_att tabr /\ ebvsubin D E tabr sIN /\ ebvsubeq D E tabr sEQ /\
     c IN D /\ yc IN D /\ eordinal D E c /\ ebnstage D E B c yc /\
     esuc D E c kk /\ eordinal D E kk /\
     (!z. z IN D /\ E z w ==> E z yc) /\
     q IN D /\ rr IN D /\
     (!z. z IN D
          ==> (E z q <=>
               ?a b. a IN D /\ b IN D /\ E a kk /\ E b kk /\
                 eopair D E a b z)) /\
     (!z1 z2. z1 IN D /\ z2 IN D
              ==> (erel D E rr z1 z2 <=> E z1 q /\ E z2 q /\
                   emlex D E z1 z2)) /\
     (!zz t. zz IN D /\ t IN D
             ==> (eapply D E f zz t <=> E zz d /\ eoenum D E q rr zz t)) /\
     (!z1 t. z1 IN D /\ t IN D /\ eapply D E f z1 t ==> E z1 d /\ E t q) /\
     (!t. t IN D /\ E t q ==> ?zz. zz IN D /\ E zz d /\ eapply D E f zz t) /\
     (!z. z IN D /\ E z w ==> bname D E B z) /\
     u IN D /\ v0 IN D /\ E u w /\ E v0 w/\
     (!a1 a2 rcx. a1 IN D /\ a2 IN D /\ rcx IN D /\ E a1 d /\ E a2 d /\
                  eapply D E f a1 rcx /\ eapply D E f a2 rcx ==> a1 = a2)
     ==> ebvatt D E B leq w sIN sEQ`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  REWRITE_TAC[ebvatt] THEN REPEAT CONJ_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`cc:A`;`RG:A`;`f:A`;
                  `v:num->A`;`d:A`;`r_att:A`;`tabr:A`;`sIN:A`]
                 EBVSUBIN_ISFUN) THEN ASM_REWRITE_TAC[];
    MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`cc:A`;`RG:A`;`f:A`;
                  `v:num->A`;`d:A`;`r_att:A`;`tabr:A`;`sEQ:A`]
                 EBVSUBEQ_ISFUN) THEN ASM_REWRITE_TAC[];
    EXISTS_TAC `cc:A` THEN REPEAT CONJ_TAC THENL
     [FIRST_ASSUM ACCEPT_TAC;
      MATCH_MP_TAC(ISPECL
                   [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`cc:A`;`RG:A`;
                    `f:A`;`v:num->A`;`d:A`;`r_att:A`;`tabr:A`;`sIN:A`;`sEQ:A`;
                    `c:A`;`yc:A`;`kk:A`;`q:A`;`rr:A`;`w:A`;`u:A`;`v0:A`]
                   EBVATT_DOMAIN_IN) THEN ASM_REWRITE_TAC[];
      MATCH_MP_TAC(ISPECL
                   [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`cc:A`;`RG:A`;
                    `f:A`;`v:num->A`;`d:A`;`r_att:A`;`tabr:A`;`sIN:A`;`sEQ:A`;
                    `c:A`;`yc:A`;`kk:A`;`q:A`;`rr:A`;`w:A`;`u:A`;`v0:A`]
                   EBVATT_DOMAIN_EQ) THEN ASM_REWRITE_TAC[]];
    MAP_EVERY X_GEN_TAC [`ua:A`;`va:A`] THEN STRIP_TAC THEN
     MP_TAC(ISPECL
            [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`cc:A`;`RG:A`;`f:A`;
             `v:num->A`;`d:A`;`r_att:A`;`tabr:A`;`sIN:A`;`sEQ:A`;`c:A`;`yc:A`;
             `kk:A`;`q:A`;`rr:A`;`w:A`;`ua:A`;`va:A`] EBVATT_READING_IN) THEN
     ASM_REWRITE_TAC[];
     MAP_EVERY X_GEN_TAC [`ua:A`;`va:A`] THEN STRIP_TAC THEN
     MP_TAC(ISPECL
            [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`cc:A`;`RG:A`;`f:A`;
             `v:num->A`;`d:A`;`r_att:A`;`tabr:A`;`sIN:A`;`sEQ:A`;`c:A`;`yc:A`;
             `kk:A`;`q:A`;`rr:A`;`w:A`;`ua:A`;`va:A`] EBVATT_READING_EQ) THEN
     ASM_REWRITE_TAC[]]);;

(* ------------------------------------------------------------------ *)
(* EBVATT_STAGE_TABLES: the full stage-attempt setup.  It also exports   *)
(* c IN D and yc IN D (from BNAME_BOUND), since yc IN D is NOT derivable *)
(* from ebnstage/erec.                                                    *)
let EBVATT_STAGE_TABLES = prove
 (`!D (E:A->A->bool) B leq w.
     model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\ w IN D /\
     (!z. z IN D /\ E z w ==> bname D E B z)
     ==> ?c yc kk q rr d f cc RG v r_att tabr sIN sEQ.
           c IN D /\ yc IN D /\
           eordinal D E c /\ ebnstage D E B c yc /\
           (!z. z IN D /\ E z w ==> E z yc) /\
           esuc D E c kk /\ eordinal D E kk /\ kk IN D /\
           q IN D /\
           (!z. z IN D
                ==> (E z q <=>
                     ?a b. a IN D /\ b IN D /\ E a kk /\ E b kk /\
                           eopair D E a b z)) /\
           d IN D /\ eordinal D E d /\
           f IN D /\ eisfun D E f /\
           (!zz t. zz IN D /\ t IN D
                   ==> (eapply D E f zz t <=> E zz d /\
                        eoenum D E q rr zz t)) /\
           (!t. t IN D /\ E t q ==> ?zz. zz IN D /\ E zz d /\
            eapply D E f zz t) /\
           rr IN D /\
           (!z z'. z IN D /\ z' IN D
                   ==> (erel D E rr z z' <=>
                        E z q /\ E z' q /\ emlex D E z z')) /\
           (!z t. z IN D /\ t IN D /\ eapply D E f z t ==> E z d /\ E t q) /\
           (!z. z IN D /\ E z d ==> ?t. t IN D /\ E t q /\ eapply D E f z t) /\
           cc IN D /\ ecross D E w w cc /\
           RG IN D /\ eisfun D E RG /\ edomain D E RG w /\
           (!x r. x IN D /\ E x w /\ ebnrank D E B x r ==>
            eapply D E RG x r) /\
           valuation D v /\ v 2 = B /\ v 3 = leq /\ v 4 = cc /\ v 5 = RG /\
           v 6 = f /\
           r_att IN D /\ erecres D E ebvattstep_form v d r_att /\
           eranu D E r_att tabr /\ tabr IN D /\
           ebvsubin D E tabr sIN /\ sIN IN D /\
           ebvsubeq D E tabr sEQ /\ sEQ IN D`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `B:A`; `w:A`] BNAME_BOUND) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `c:A` (X_CHOOSE_THEN `yc:A` STRIP_ASSUME_TAC)) THEN
  MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `c:A`] ESUC_EXISTS) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_THEN `kk:A` ASSUME_TAC) THEN
  SUBGOAL_THEN `eordinal D (E:A->A->bool) kk` ASSUME_TAC THENL
   [MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `c:A`; `kk:A`]
           EORDINAL_ESUC) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(kk:A) IN D` ASSUME_TAC THENL
   [MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `c:A`; `kk:A`] ESUC_ALT) THEN
    ASM_REWRITE_TAC[] THEN MESON_TAC[]; ALL_TAC] THEN
  MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `kk:A`] EPRODK_ENUM_CLEAN) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `q:A` (X_CHOOSE_THEN `rr:A`
    (X_CHOOSE_THEN `d:A` (X_CHOOSE_THEN `f:A` STRIP_ASSUME_TAC)))) THEN
  MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `w:A`; `w:A`] ECROSS_EXISTS) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_THEN `cc:A` ASSUME_TAC) THEN
  SUBGOAL_THEN `(cc:A) IN D` ASSUME_TAC THENL
   [FIRST_ASSUM(ACCEPT_TAC o CONJUNCT1 o REWRITE_RULE[ecross]); ALL_TAC] THEN
  MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `B:A`; `w:A`]
    EBNRANK_GRAPH_EXISTS) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_THEN `RG:A` STRIP_ASSUME_TAC) THEN
  MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `B:A`; `leq:A`; `cc:A`; `RG:A`;
    `f:A`; `d:A`] EBVATT_ERECRES_EXISTS) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `v:num->A` (X_CHOOSE_THEN `r_att:A`
    STRIP_ASSUME_TAC)) THEN
  SUBGOAL_THEN `(r_att:A) IN D` ASSUME_TAC THENL
   [FIRST_ASSUM(ACCEPT_TAC o CONJUNCT1 o REWRITE_RULE[erecres]); ALL_TAC] THEN
  MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `r_att:A`] ERANU_EXISTS) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_THEN `tabr:A` ASSUME_TAC) THEN
  SUBGOAL_THEN `(tabr:A) IN D` ASSUME_TAC THENL
   [FIRST_ASSUM(ACCEPT_TAC o MATCH_MP ERANU_IN); ALL_TAC] THEN
  MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `tabr:A`]
         EBVSUBIN_PRED_EXISTS) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_THEN `sIN:A` ASSUME_TAC) THEN
  MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `tabr:A`]
         EBVSUBEQ_PRED_EXISTS) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_THEN `sEQ:A` ASSUME_TAC) THEN
  SUBGOAL_THEN `(sIN:A) IN D` ASSUME_TAC THENL
   [FIRST_ASSUM(ACCEPT_TAC o MATCH_MP EBVSUBIN_IN); ALL_TAC] THEN
  SUBGOAL_THEN `(sEQ:A) IN D` ASSUME_TAC THENL
   [FIRST_ASSUM(ACCEPT_TAC o MATCH_MP EBVSUBEQ_IN); ALL_TAC] THEN
  MAP_EVERY EXISTS_TAC
   [`c:A`; `yc:A`; `kk:A`; `q:A`; `rr:A`; `d:A`; `f:A`; `cc:A`; `RG:A`;
    `v:num->A`; `r_att:A`; `tabr:A`; `sIN:A`; `sEQ:A`] THEN
  REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC);;

(* ================================================================== *)
(* F4: EBVATT_EXISTS.  For any bname-domain w (nonempty),                *)
(* the Boolean-value attempt exists: ?sIN sEQ. ebvatt D E B leq w sIN sEQ*)
(* = STAGE_TABLES_FULL2 (setup) + RR_IRREFL + FINJ_STAGE (finj) +         *)
(* EBVATT_FROM_TABLES.  [w-nonemptiness supplies the u,v0 witness that    *)
(* the DOMAIN lemmas inherited from the READING antecedent.]              *)
let EBVATT_EXISTS = prove
 (`!D (E:A->A->bool) B leq w.
     model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\ w IN D /\
     (!z. z IN D /\ E z w ==> bname D E B z) /\
     (?z0. z0 IN D /\ E z0 w)
     ==> ?sIN sEQ. ebvatt D E B leq w sIN sEQ`,
  (REPEAT GEN_TAC THEN STRIP_TAC) THEN
  (MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`w:A`]
    EBVATT_STAGE_TABLES) THEN ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `c:A`
             (X_CHOOSE_THEN `yc:A`
              (X_CHOOSE_THEN `kk:A`
               (X_CHOOSE_THEN `q:A`
                (X_CHOOSE_THEN `rr:A`
                 (X_CHOOSE_THEN `d:A`
                  (X_CHOOSE_THEN `f:A`
                   (X_CHOOSE_THEN `cc:A`
                    (X_CHOOSE_THEN `RG:A`
                     (X_CHOOSE_THEN `vv:num->A`
                      (X_CHOOSE_THEN `r_att:A`
                       (X_CHOOSE_THEN `tabr:A`
                        (X_CHOOSE_THEN `sIN:A`
                         (X_CHOOSE_THEN `sEQ:A`
                          STRIP_ASSUME_TAC))))))))))))))) THEN
  (SUBGOAL_THEN
   `!u u'. u IN D /\ u' IN D /\ erel D E rr u u' ==>
    ~erel D (E:A->A->bool) rr u' u`
   ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`q:A`;`rr:A`;`kk:A`]
                 RR_IRREFL) THEN
    ASM_REWRITE_TAC[]; ALL_TAC]) THEN
  (SUBGOAL_THEN
   `!a1 a2 rcx. a1 IN D /\ a2 IN D /\ rcx IN D /\ E a1 d /\ E a2 d /\
                eapply D E f a1 rcx /\
                  eapply D (E:A->A->bool) f a2 rcx ==> a1 = a2`
   ASSUME_TAC THENL
   [REPEAT GEN_TAC THEN STRIP_TAC THEN
    MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`q:A`;`rr:A`;`d:A`;`kk:A`;`f:A`;
                  `a1:A`;`a2:A`;`rcx:A`] FINJ_STAGE) THEN ASM_REWRITE_TAC[];
    ALL_TAC]) THEN
  (MAP_EVERY EXISTS_TAC [`sIN:A`;`sEQ:A`] THEN
  MATCH_MP_TAC(ISPECL
               [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`cc:A`;`RG:A`;`f:A`;
                `vv:num->A`;`d:A`;`r_att:A`;`tabr:A`;`sIN:A`;`sEQ:A`;`c:A`;
                `yc:A`;`kk:A`;`q:A`;
                `rr:A`;`w:A`;`z0:A`;`z0:A`] EBVATT_FROM_TABLES) THEN
  ASM_REWRITE_TAC[]));;

(* ================================================================== *)
(* F4: the TOTAL Boolean membership/equality relations.                  *)
(* ebv_in/ebv_eq D E B leq u v z : z = [[u IN v]] / [[u = v]], read off    *)
(* the attempt on ANY bname-stage w containing u,v (well-defined by       *)
(* cross-w coherence, proved separately).                                *)
let ebv_in = new_definition
 `ebv_in D (E:A->A->bool) B leq u v z <=>
    ?a w sIN sEQ pr.
        a IN D /\ eordinal D E a /\ ebnstage D E B a w /\ w IN D /\
        E u w /\ E v w /\ ebvatt D E B leq w sIN sEQ /\
        eopair D E u v pr /\ eapply D E sIN pr z`;;
let ebv_eq = new_definition
 `ebv_eq D (E:A->A->bool) B leq u v z <=>
    ?a w sIN sEQ pr.
        a IN D /\ eordinal D E a /\ ebnstage D E B a w /\ w IN D /\
        E u w /\ E v w /\ ebvatt D E B leq w sIN sEQ /\
        eopair D E u v pr /\ eapply D E sEQ pr z`;;

(* EBV_TOTAL: for bnames u,v the values exist (BNAME_DIRECTED gives a     *)
(* common stage; EBVATT_EXISTS + EBVATT_VAL read off the values).         *)
let EBV_TOTAL = prove
 (`!D (E:A->A->bool) B leq u v.
     model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
     u IN D /\ v IN D /\ bname D E B u /\ bname D E B v
     ==> (?zi. zi IN D /\ ebv_in D E B leq u v zi) /\
         (?ze. ze IN D /\ ebv_eq D E B leq u v ze)`,
  (REPEAT GEN_TAC THEN STRIP_TAC) THEN
  (MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`u:A`;`v:A`]
    BNAME_DIRECTED) THEN ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `a:A` (X_CHOOSE_THEN `w:A` STRIP_ASSUME_TAC))) THEN
  (SUBGOAL_THEN `!z. z IN D /\ E z w ==> bname D (E:A->A->bool) B z`
   ASSUME_TAC THENL
   [REPEAT STRIP_TAC THEN
    MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;
                         `a:A`;`w:A`;`z:A`] BNAME_STAGE) THEN
    ASM_REWRITE_TAC[]; ALL_TAC]) THEN
  (MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`w:A`]
    EBVATT_EXISTS) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[] THEN EXISTS_TAC `u:A` THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `sIN:A` (X_CHOOSE_THEN `sEQ:A` ASSUME_TAC))) THEN
  (MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`u:A`;`v:A`] EOPAIR_EXISTS) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `pr:A`)) THEN
  (MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`w:A`;`sIN:A`;
    `sEQ:A`;`u:A`;`v:A`;`pr:A`] EBVATT_VAL) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(CONJUNCTS_THEN2 (X_CHOOSE_THEN `vi:A` STRIP_ASSUME_TAC)
    (X_CHOOSE_THEN `ve:A` STRIP_ASSUME_TAC))) THEN
  (CONJ_TAC THENL
   [EXISTS_TAC `vi:A` THEN ASM_REWRITE_TAC[ebv_in] THEN
    MAP_EVERY EXISTS_TAC [`a:A`;`w:A`;`sIN:A`;`sEQ:A`;`pr:A`] THEN
    ASM_REWRITE_TAC[];
    EXISTS_TAC `ve:A` THEN ASM_REWRITE_TAC[ebv_eq] THEN
    MAP_EVERY EXISTS_TAC [`a:A`;`w:A`;`sIN:A`;`sEQ:A`;`pr:A`] THEN
    ASM_REWRITE_TAC[]]));;

(* ------------------------------------------------------------------ *)
(* STAGE_DOM_CLOSED (INC3.3 coherence prereq = H2 for bname-stages): for  *)
(* a name v in stage w and a domain-name y (y IN D, eapply v y qy), y IN w.*)
(* The IN D wall is sidestepped since bvcomb/bveqcomb guard y IN D.  Chain:  *)
(* BNAME_STAGE -> EBNRANK_EXISTS(rv) -> EBNRANK_APPLY_LT (ry<rv, bname y) ->*)
(* EBVATT_RANKBOUND (rv<=a) -> ESUC_ALT -> EORDINAL_TRANS_E (ry<a) ->       *)
(* ebnrank y ry gives y in stage ry -> EBNSTAGE_MONO (stage ry subseteq w).*)
let STAGE_DOM_CLOSED = prove
 (`!D (E:A->A->bool) B a w v y qy.
     model D E ZF_AX /\ B IN D /\ a IN D /\ eordinal D E a /\
     ebnstage D E B a w /\ w IN D /\
     v IN D /\ E v w /\ y IN D /\ qy IN D /\ eapply D E v y qy
     ==> E y w`,
  (REPEAT GEN_TAC THEN STRIP_TAC) THEN
  (SUBGOAL_THEN `bname D (E:A->A->bool) B v` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`a:A`;`w:A`;`v:A`]
      BNAME_STAGE) THEN ASM_REWRITE_TAC[]; ALL_TAC]) THEN
  (MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`v:A`] EBNRANK_EXISTS) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `rv:A` STRIP_ASSUME_TAC)) THEN
  (MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`v:A`;`y:A`;`qy:A`;
    `rv:A`] EBNRANK_APPLY_LT) THEN ASM_REWRITE_TAC[] THEN
  DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC
    (X_CHOOSE_THEN `ry:A` STRIP_ASSUME_TAC))) THEN
  (SUBGOAL_THEN
   `(rv:A) IN D /\ eordinal D E rv /\ (ry:A) IN D /\
    eordinal D (E:A->A->bool) ry`
   STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[EBNRANK_IN; EBNRANK_ORDINAL]; ALL_TAC]) THEN
  (MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`a:A`] ESUC_EXISTS) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `kk:A`)) THEN
  (SUBGOAL_THEN `(E:A->A->bool) (rv:A) kk` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`B:A`;`a:A`;`w:A`;`v:A`;`rv:A`;
                  `kk:A`] EBVATT_RANKBOUND) THEN ASM_REWRITE_TAC[];
    ALL_TAC]) THEN
  (SUBGOAL_THEN `(E:A->A->bool) (rv:A) a \/ rv = a` ASSUME_TAC THENL
   [MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`a:A`;`kk:A`] ESUC_ALT) THEN
    ASM_REWRITE_TAC[] THEN DISCH_THEN(MP_TAC o SPEC `rv:A` o CONJUNCT2) THEN
    ASM_REWRITE_TAC[]; ALL_TAC]) THEN
  (SUBGOAL_THEN `(E:A->A->bool) (ry:A) a` ASSUME_TAC THENL
   [UNDISCH_TAC `(E:A->A->bool) rv a \/ rv = a` THEN STRIP_TAC THENL
     [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`a:A`;`ry:A`;`rv:A`]
        EORDINAL_TRANS_E) THEN ASM_REWRITE_TAC[];
      ASM_MESON_TAC[]]; ALL_TAC]) THEN
  (UNDISCH_TAC `ebnrank D (E:A->A->bool) B y ry` THEN
  REWRITE_TAC[ebnrank] THEN
  DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC (CONJUNCTS_THEN2
    (X_CHOOSE_THEN `yy:A` STRIP_ASSUME_TAC) ASSUME_TAC))) THEN
  (MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`a:A`;`ry:A`;
    `w:A`;`yy:A`;`y:A`] EBNSTAGE_MONO) THEN ASM_REWRITE_TAC[]));;

(* ------------------------------------------------------------------ *)
(* CROSS_W_REFIFF (INC3.3 coherence): below-agreement of two attempts on  *)
(* w1 subseteq w2 (second on the larger w2) upgrades ~bvdisagree-below to  *)
(* the eapply-iff INEQ/EQEQ need.  Mirror of EBVATT_REFIFF; no H1/H2 (uses *)
(* EBVATT_VAL per-attempt + EBVATT_PAIR_IFF); IN D-guarded sub.              *)
let CROSS_W_REFIFF = prove
 (`!D (E:A->A->bool) B leq w1 w2 sIN sEQ sIN' sEQ' z0.
      model D E ZF_AX /\ ecba D E B leq /\
      (!z. z IN D /\ E z w1 ==> E z w2) /\
      eisfun D E sIN /\ eisfun D E sEQ /\ eisfun D E sIN' /\ eisfun D E sEQ' /\
      ebvatt D E B leq w1 sIN sEQ /\ ebvatt D E B leq w2 sIN' sEQ' /\
      (!a b ra rb pab zc.
         E a w1 /\ E b w1 /\ a IN D /\ b IN D /\ ra IN D /\ rb IN D /\
         pab IN D /\ zc IN D /\
         ebnrank D E B a ra /\ ebnrank D E B b rb /\ eopair D E a b pab /\
         eopair D E ra rb zc /\ emlex D E zc z0
         ==> ~(bvdisagree D E sIN sIN' pab \/ bvdisagree D E sEQ sEQ' pab))
      ==> !a b ra rb pab zab.
            a IN D /\ b IN D /\ E a w1 /\ E b w1 /\ ra IN D /\ rb IN D /\
            pab IN D /\ zab IN D /\
            ebnrank D E B a ra /\ ebnrank D E B b rb /\
            eopair D E a b pab /\ eopair D E ra rb zab /\ emlex D E zab z0
            ==> (!m. eapply D E sIN pab m <=> eapply D E sIN' pab m) /\
                (!m. eapply D E sEQ pab m <=> eapply D E sEQ' pab m)`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "zf cba sub funsIN funsEQ funsIN2 funsEQ2 att attp below" THEN
  MAP_EVERY X_GEN_TAC [`a:A`; `b:A`; `ra:A`; `rb:A`; `pab:A`; `zab:A`] THEN
  DISCH_THEN(REPEAT_TCL CONJUNCTS_THEN ASSUME_TAC) THEN
  SUBGOAL_THEN
   `~bvdisagree D (E:A->A->bool) sIN sIN' pab /\
    ~bvdisagree D E sEQ sEQ' pab`
  STRIP_ASSUME_TAC THENL
   [REWRITE_TAC[GSYM DE_MORGAN_THM] THEN USE_THEN "below" MATCH_MP_TAC THEN
    MAP_EVERY EXISTS_TAC [`a:A`; `b:A`; `ra:A`; `rb:A`; `zab:A`] THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) (a:A) w2 /\ (E:A->A->bool) (b:A) w2`
    STRIP_ASSUME_TAC THENL
   [CONJ_TAC THEN USE_THEN "sub" MATCH_MP_TAC THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `B:A`; `leq:A`; `w1:A`;
    `sIN:A`; `sEQ:A`; `a:A`; `b:A`; `pab:A`] EBVATT_VAL) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(CONJUNCTS_THEN2 (X_CHOOSE_THEN `vi:A` STRIP_ASSUME_TAC)
    (X_CHOOSE_THEN `ve:A` STRIP_ASSUME_TAC)) THEN
  MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `B:A`; `leq:A`; `w2:A`;
    `sIN':A`; `sEQ':A`; `a:A`; `b:A`; `pab:A`] EBVATT_VAL) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(CONJUNCTS_THEN2 (X_CHOOSE_THEN `vj:A` STRIP_ASSUME_TAC)
    (X_CHOOSE_THEN `vf:A` STRIP_ASSUME_TAC)) THEN
  MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `sIN:A`; `sIN':A`; `sEQ:A`;
    `sEQ':A`; `pab:A`] EBVATT_PAIR_IFF) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[] THEN REPEAT CONJ_TAC THENL
     [EXISTS_TAC `vi:A`; EXISTS_TAC `vj:A`; EXISTS_TAC `ve:A`;
      EXISTS_TAC `vf:A`] THEN
    ASM_REWRITE_TAC[];
    DISCH_THEN ACCEPT_TAC]);;

(* ===================================================================== *)
(* F4: total ebv_in / ebv_eq are SINGLE-VALUED (coherent across          *)
(* stages).  Guarded-H2 / weak-H1 variants of the bad-pair machinery     *)
(* (EBVATT_INEQ_G, EBVATT_EQEQ_G, EBVBAD_BELOW_G, CROSS_W_AGREE_G) feed   *)
(* EBV_IN_UNIQUE / EBV_EQ_UNIQUE: for outputs in D the Boolean IN/=       *)
(* value at <u,v> is independent of the bname-stage witness.  H1 is       *)
(* discharged via BNAME_STAGE, guarded-H2 via STAGE_DOM_CLOSED, the       *)
(* stage-nesting SUBSET via EBNSTAGE_MONO / EBNSTAGE_UNIQUE.              *)
(* ===================================================================== *)

let EBVATT_INEQ_G = prove
 (`!D (E:A->A->bool) B leq w sIN sIN' sEQ sEQ' u0 v0 ru0 rv0 z0 valI valJ.
      model D E ZF_AX /\ B IN D /\ ecba D E B leq /\
      (!u. u IN D /\ E u w ==> bname D E B u) /\
      (!v y q. v IN D /\ y IN D /\ q IN D /\ E v w /\
       eapply D E v y q ==> E y w) /\
      E u0 w /\ E v0 w /\ u0 IN D /\ v0 IN D /\
      ebnrank D E B u0 ru0 /\ ebnrank D E B v0 rv0 /\ eopair D E ru0 rv0 z0 /\
      (!a b ra rb pab zab.
         a IN D /\ b IN D /\ E a w /\ E b w /\ ra IN D /\ rb IN D /\
         pab IN D /\ zab IN D /\
         ebnrank D E B a ra /\ ebnrank D E B b rb /\ eopair D E a b pab /\
         eopair D E ra rb zab /\ emlex D E zab z0
         ==> (!m. eapply D E sIN pab m <=> eapply D E sIN' pab m) /\
             (!m. eapply D E sEQ pab m <=> eapply D E sEQ' pab m)) /\
      ebvin D E B leq sEQ v0 u0 valI /\ ebvin D E B leq sEQ' v0 u0 valJ
      ==> valI = valJ`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "zf BD cba H1 H2 u0w v0w u0D v0D h h2 opz0 refiff h3 h4" THEN
  SUBGOAL_THEN `bname D (E:A->A->bool) B u0` ASSUME_TAC THENL
