      SUBGOAL_THEN `?cry:A. eopair D E ry ru0 cry` (X_CHOOSE_TAC `cry:A`) THENL
       [MATCH_MP_TAC EOPAIR_EXISTS THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
