let EBVBAD_BELOW_G = prove
 (`!D (E:A->A->bool) B w sIN sIN' sEQ sEQ' ru0 rv0 z0.
      model D E ZF_AX /\ B IN D /\ w IN D /\
      (!u. u IN D /\ E u w ==> bname D E B u) /\
      eordinal D E ru0 /\ eordinal D E rv0 /\ eopair D E ru0 rv0 z0 /\
      (!u v ru rv pr z.
           u IN D /\ v IN D /\ ru IN D /\ rv IN D /\ pr IN D /\ z IN D /\
           E u w /\ E v w /\
           ebnrank D E B u ru /\ ebnrank D E B v rv /\
           eopair D E u v pr /\ eopair D E ru rv z /\
           (bvdisagree D E sIN sIN' pr \/ bvdisagree D E sEQ sEQ' pr) /\
           ~(z = z0)
           ==> emlex D E z0 z)
      ==> !a b ra rb pab zc.
             E a w /\ E b w /\ a IN D /\ b IN D /\
             ra IN D /\ rb IN D /\ pab IN D /\ zc IN D /\
             ebnrank D E B a ra /\ ebnrank D E B b rb /\
             eopair D E a b pab /\ eopair D E ra rb zc /\ emlex D E zc z0
             ==> ~(bvdisagree D E sIN sIN' pab \/
                   bvdisagree D E sEQ sEQ' pab)`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "zf BD wD H1 ordru0 ordrv0 opz0 Mc" THEN
  MAP_EVERY X_GEN_TAC [`a:A`; `b:A`; `ra:A`; `rb:A`; `pab:A`; `zc:A`] THEN
  DISCH_THEN(REPEAT_TCL CONJUNCTS_THEN ASSUME_TAC) THEN
  DISCH_TAC THEN
  SUBGOAL_THEN `(a:A) IN D /\ bname D E B a` STRIP_ASSUME_TAC THENL
   [CONJ_TAC THENL
     [FIRST_ASSUM ACCEPT_TAC;
      USE_THEN "H1" MATCH_MP_TAC THEN ASM_REWRITE_TAC[]]; ALL_TAC] THEN
  SUBGOAL_THEN `(b:A) IN D /\ bname D E B b` STRIP_ASSUME_TAC THENL
   [CONJ_TAC THENL
     [FIRST_ASSUM ACCEPT_TAC;
      USE_THEN "H1" MATCH_MP_TAC THEN ASM_REWRITE_TAC[]]; ALL_TAC] THEN
  SUBGOAL_THEN `emlex D (E:A->A->bool) z0 zc` ASSUME_TAC THENL
   [ASM_CASES_TAC `(zc:A) = z0` THENL
     [POP_ASSUM SUBST_ALL_TAC THEN FIRST_ASSUM ACCEPT_TAC;
      USE_THEN "Mc" MATCH_MP_TAC THEN
      MAP_EVERY EXISTS_TAC [`a:A`; `b:A`; `ra:A`; `rb:A`; `pab:A`] THEN
      ASM_REWRITE_TAC[]];
    ALL_TAC] THEN
  SUBGOAL_THEN `eordinal D (E:A->A->bool) ra /\ eordinal D E rb`
  STRIP_ASSUME_TAC THENL
   [CONJ_TAC THEN
    FIRST_ASSUM(fun th -> ACCEPT_TAC(MATCH_MP EBNRANK_ORDINAL th));
    ALL_TAC] THEN
  MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `ra:A`; `rb:A`; `ru0:A`;
    `rv0:A`; `zc:A`; `z0:A`] EMLEX_ASYM) THEN
  ASM_REWRITE_TAC[]);;
let CROSS_W_AGREE_G = prove
 (`!D (E:A->A->bool) B leq w1 w2 sIN sIN' sEQ sEQ'.
      model D E ZF_AX /\ B IN D /\ ecba D E B leq /\ w1 IN D /\ w2 IN D /\
      (!u. u IN D /\ E u w1 ==> bname D E B u) /\
      (!v y q. v IN D /\ y IN D /\ q IN D /\ E v w1 /\ eapply D E v y q
               ==> E y w1) /\
      (!z. z IN D /\ E z w1 ==> E z w2) /\
      ebvatt D E B leq w1 sIN sEQ /\ ebvatt D E B leq w2 sIN' sEQ'
      ==> !u v pr. u IN D /\ v IN D /\ E u w1 /\ E v w1 /\ eopair D E u v pr
                   ==> ~bvdisagree D E sIN sIN' pr /\
                       ~bvdisagree D E sEQ sEQ' pr`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "zf BD cba w1D w2D H1 H2 sub att attp" THEN
  SUBGOAL_THEN `eisfun D (E:A->A->bool) sIN /\ eisfun D E sEQ`
  STRIP_ASSUME_TAC THENL
   [USE_THEN "att" (MP_TAC o REWRITE_RULE[ebvatt]) THEN
    DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC (CONJUNCTS_THEN2 ASSUME_TAC
      (K ALL_TAC))) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `eisfun D (E:A->A->bool) sIN' /\ eisfun D E sEQ'`
  STRIP_ASSUME_TAC THENL
   [USE_THEN "attp" (MP_TAC o REWRITE_RULE[ebvatt]) THEN
    DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC (CONJUNCTS_THEN2 ASSUME_TAC
      (K ALL_TAC))) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN
   `(sIN:A) IN D /\ sEQ IN D /\ sIN' IN D /\ sEQ' IN D`
  STRIP_ASSUME_TAC THENL
   [REPEAT CONJ_TAC THEN
    FIRST_ASSUM(fun th -> ACCEPT_TAC(CONJUNCT1(REWRITE_RULE[eisfun] th)));
    ALL_TAC] THEN
  SUBGOAL_THEN `!z. z IN D /\ E z w1 ==> bname D (E:A->A->bool) B z`
  (LABEL_TAC "bnc") THENL [USE_THEN "H1" ACCEPT_TAC; ALL_TAC] THEN
  MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `B:A`; `w1:A`]
