  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  INTRO_TAC "@RG. RGD funRG h look RGmem" THEN
  SUBGOAL_THEN
   `~(?u v pr. u IN D /\ v IN D /\ pr IN D /\ E u w1 /\ E v w1 /\
              eopair D (E:A->A->bool) u v pr /\
              (bvdisagree D E sIN sIN' pr \/ bvdisagree D E sEQ sEQ' pr))`
  (LABEL_TAC "nobad") THENL
   [DISCH_TAC THEN
    MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `B:A`; `w1:A`; `RG:A`;
      `sIN:A`; `sIN':A`; `sEQ:A`; `sEQ':A`] EBVBAD_LEAST) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    INTRO_TAC "@u0 v0 ru0 rv0 pr0 z0. u0D v0D ru0D rv0D pr0D z0D u0w1 \
               v0w1 h h2 oppr0 opz0 bad Mc" THEN
    SUBGOAL_THEN `eordinal D (E:A->A->bool) ru0` ASSUME_TAC THENL
     [FIRST_ASSUM(ACCEPT_TAC o MATCH_MP EBNRANK_ORDINAL); ALL_TAC] THEN
    SUBGOAL_THEN `eordinal D (E:A->A->bool) rv0` ASSUME_TAC THENL
     [FIRST_ASSUM(ACCEPT_TAC o MATCH_MP EBNRANK_ORDINAL); ALL_TAC] THEN
    MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `B:A`; `w1:A`; `sIN:A`;
      `sIN':A`; `sEQ:A`; `sEQ':A`; `ru0:A`; `rv0:A`; `z0:A`]
                EBVBAD_BELOW_G) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN(LABEL_TAC "below")] THEN
