      STRIP_TAC THEN USE_THEN "below" MATCH_MP_TAC THEN
      MAP_EVERY EXISTS_TAC [`a:A`; `b:A`; `ra:A`; `rb:A`; `zc:A`] THEN
      ASM_REWRITE_TAC[];
      DISCH_TAC] THEN
    MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `B:A`; `leq:A`; `w1:A`;
      `sIN:A`; `sEQ:A`; `u0:A`; `v0:A`; `pr0:A`] EBVATT_VAL) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(CONJUNCTS_THEN2 (X_CHOOSE_THEN `valI:A` STRIP_ASSUME_TAC)
