      [CONJ_TAC THEN USE_THEN "sub" MATCH_MP_TAC THEN ASM_REWRITE_TAC[];
       ALL_TAC] THEN
    MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `B:A`; `leq:A`; `w2:A`;
      `sIN':A`; `sEQ':A`; `u0:A`; `v0:A`; `pr0:A`] EBVATT_VAL) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
