      MAP_EVERY X_GEN_TAC [`a:A`; `a':A`] THEN STRIP_TAC THEN
      SUBGOAL_THEN `(a:A) = valE` SUBST_ALL_TAC THENL
       [MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `sEQ:A`; `pr0:A`; `a:A`;
          `valE:A`] EAPPLY_UNIQUE) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
      SUBGOAL_THEN `(a':A) = valG` SUBST_ALL_TAC THENL
       [MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `sEQ':A`; `pr0:A`; `a':A`;
          `valG:A`] EAPPLY_UNIQUE) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
      ASM_REWRITE_TAC[]; ALL_TAC] THEN
    UNDISCH_TAC `bvdisagree D (E:A->A->bool) sIN sIN' pr0 \/
                 bvdisagree D E sEQ sEQ' pr0` THEN
    ASM_REWRITE_TAC[];
    MAP_EVERY X_GEN_TAC [`u:A`; `v:A`; `pr:A`] THEN STRIP_TAC THEN
    SUBGOAL_THEN `(pr:A) IN D` ASSUME_TAC THENL
     [FIRST_ASSUM(ACCEPT_TAC o MATCH_MP EOPAIR_IN); ALL_TAC] THEN
    USE_THEN "nobad" MP_TAC THEN REWRITE_TAC[NOT_EXISTS_THM] THEN
    DISCH_THEN(MP_TAC o SPECL [`u:A`; `v:A`; `pr:A`]) THEN
    ASM_REWRITE_TAC[] THEN REWRITE_TAC[DE_MORGAN_THM]]);;

let EBV_IN_UNIQUE = prove
 (`!D (E:A->A->bool) B leq u v z1 z2.
      model D E ZF_AX /\ B IN D /\ ecba D E B leq /\
      u IN D /\ v IN D /\ z1 IN D /\ z2 IN D /\
      ebv_in D E B leq u v z1 /\ ebv_in D E B leq u v z2
      ==> z1 = z2`,
  REPEAT GEN_TAC THEN REWRITE_TAC[ebv_in] THEN
  DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC (CONJUNCTS_THEN2 ASSUME_TAC
    (CONJUNCTS_THEN2 ASSUME_TAC (CONJUNCTS_THEN2 ASSUME_TAC
    (CONJUNCTS_THEN2 ASSUME_TAC (CONJUNCTS_THEN2 ASSUME_TAC
