    ANTS_TAC THENL
     [REPEAT CONJ_TAC THENL
       [FIRST_ASSUM ACCEPT_TAC; FIRST_ASSUM ACCEPT_TAC; FIRST_ASSUM ACCEPT_TAC;
        FIRST_ASSUM ACCEPT_TAC; FIRST_ASSUM ACCEPT_TAC;
        X_GEN_TAC `uu:A` THEN STRIP_TAC THEN
        MATCH_MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `B:A`; `a1:A`;
          `w1:A`; `uu:A`] BNAME_STAGE) THEN ASM_REWRITE_TAC[];
        MAP_EVERY X_GEN_TAC [`vv:A`; `yy:A`; `qq:A`] THEN STRIP_TAC THEN
