    (* Case a1 = a2 (subst) : w1 = w2 *)
    SUBGOAL_THEN `w1:A = w2` SUBST_ALL_TAC THENL
     [MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `B:A`; `a2:A`; `w1:A`;
