        ASM_REWRITE_TAC[];
        FIRST_ASSUM ACCEPT_TAC; FIRST_ASSUM ACCEPT_TAC];
      DISCH_THEN(MP_TAC o SPECL [`u:A`; `v:A`; `pr2:A`]) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(LABEL_TAC "nd" o REWRITE_RULE[bvdisagree] o CONJUNCT1) THEN
      CONV_TAC SYM_CONV THEN
      USE_THEN "nd" (MATCH_MP_TAC o SPECL [`z2:A`; `z1:A`]) THEN
      ASM_REWRITE_TAC[]]]);;

