      DISCH_THEN(LABEL_TAC "nd" o REWRITE_RULE[bvdisagree] o CONJUNCT2) THEN
      CONV_TAC SYM_CONV THEN
      USE_THEN "nd" (MATCH_MP_TAC o SPECL [`z2:A`; `z1:A`]) THEN
      ASM_REWRITE_TAC[]]]);;

(* ===================================================================== *)
(* F4 local<->global bridges: any covering bname-stage computes           *)
(* the total relation.  EBV_IN/EQ_AT_STAGE: a local attempt's ebvin/ebveq *)
(* value IS ebv_in/ebv_eq (via EBVATT_VAL + EBVIN/EBVEQ_UNIQUE + the def). *)
(* EBV_IN/EQ_TABLE_ENTRY: a raw table entry (eapply sIN/sEQ pr z, z IN D)  *)
(* IS the global value (+ EAPPLY_UNIQUE).  Ingredients for the SUP/INF     *)
(* equations (sEQ<u,y> = ebv_eq(u,y) for y in dom v).                     *)
(* ===================================================================== *)

let EBV_IN_AT_STAGE = prove
 (`!D (E:A->A->bool) B leq a w sIN sEQ u v z.
      model D E ZF_AX /\ ecba D E B leq /\ B IN D /\
      a IN D /\ eordinal D E a /\ ebnstage D E B a w /\ w IN D /\
      u IN D /\ v IN D /\ E u w /\ E v w /\
      ebvatt D E B leq w sIN sEQ /\ ebvin D E B leq sEQ v u z
      ==> ebv_in D E B leq u v z`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN REWRITE_TAC[ebv_in] THEN
  SUBGOAL_THEN `?pr:A. eopair D E u v pr` (X_CHOOSE_TAC `pr:A`) THENL
   [MATCH_MP_TAC EOPAIR_EXISTS THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `B:A`; `leq:A`; `w:A`; `sIN:A`;
    `sEQ:A`; `u:A`; `v:A`; `pr:A`] EBVATT_VAL) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(CONJUNCTS_THEN2 (X_CHOOSE_THEN `vi:A` STRIP_ASSUME_TAC)
    (K ALL_TAC)) THEN
  SUBGOAL_THEN `(z:A) = vi` SUBST_ALL_TAC THENL
   [MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `B:A`; `leq:A`; `sEQ:A`;
      `v:A`; `u:A`; `z:A`; `vi:A`] EBVIN_UNIQUE) THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  MAP_EVERY EXISTS_TAC [`a:A`; `w:A`; `sIN:A`; `sEQ:A`; `pr:A`] THEN
  ASM_REWRITE_TAC[]);;
let EBV_EQ_AT_STAGE = prove
 (`!D (E:A->A->bool) B leq a w sIN sEQ u v z.
      model D E ZF_AX /\ ecba D E B leq /\ B IN D /\
      a IN D /\ eordinal D E a /\ ebnstage D E B a w /\ w IN D /\
      u IN D /\ v IN D /\ E u w /\ E v w /\
      ebvatt D E B leq w sIN sEQ /\ ebveq D E B leq sIN u v z
      ==> ebv_eq D E B leq u v z`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN REWRITE_TAC[ebv_eq] THEN
  SUBGOAL_THEN `?pr:A. eopair D E u v pr` (X_CHOOSE_TAC `pr:A`) THENL
   [MATCH_MP_TAC EOPAIR_EXISTS THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `B:A`; `leq:A`; `w:A`; `sIN:A`;
    `sEQ:A`; `u:A`; `v:A`; `pr:A`] EBVATT_VAL) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(CONJUNCTS_THEN2 (K ALL_TAC)
    (X_CHOOSE_THEN `ve:A` STRIP_ASSUME_TAC)) THEN
  SUBGOAL_THEN `(z:A) = ve` SUBST_ALL_TAC THENL
   [MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `B:A`; `leq:A`; `sIN:A`;
      `u:A`; `v:A`; `z:A`; `ve:A`] EBVEQ_UNIQUE) THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  MAP_EVERY EXISTS_TAC [`a:A`; `w:A`; `sIN:A`; `sEQ:A`; `pr:A`] THEN
  ASM_REWRITE_TAC[]);;

let EBV_IN_TABLE_ENTRY = prove
 (`!D (E:A->A->bool) B leq a w sIN sEQ u v pr z.
      model D E ZF_AX /\ ecba D E B leq /\ B IN D /\
      a IN D /\ eordinal D E a /\ ebnstage D E B a w /\ w IN D /\
      u IN D /\ v IN D /\ E u w /\ E v w /\
      ebvatt D E B leq w sIN sEQ /\ eopair D E u v pr /\
      eapply D E sIN pr z /\ z IN D
      ==> ebv_in D E B leq u v z`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `eisfun D (E:A->A->bool) sIN` ASSUME_TAC THENL
   [FIRST_ASSUM(ACCEPT_TAC o CONJUNCT1 o REWRITE_RULE[ebvatt]); ALL_TAC] THEN
  SUBGOAL_THEN `(pr:A) IN D` ASSUME_TAC THENL
   [FIRST_ASSUM(ACCEPT_TAC o MATCH_MP EOPAIR_IN); ALL_TAC] THEN
  MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `B:A`; `leq:A`; `w:A`; `sIN:A`;
    `sEQ:A`; `u:A`; `v:A`; `pr:A`] EBVATT_VAL) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(CONJUNCTS_THEN2 (X_CHOOSE_THEN `vi:A` STRIP_ASSUME_TAC)
    (K ALL_TAC)) THEN
  SUBGOAL_THEN `(z:A) = vi` SUBST_ALL_TAC THENL
   [MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `sIN:A`; `pr:A`; `z:A`;
      `vi:A`] EAPPLY_UNIQUE) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MATCH_MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `B:A`; `leq:A`; `a:A`;
    `w:A`; `sIN:A`; `sEQ:A`; `u:A`; `v:A`; `vi:A`] EBV_IN_AT_STAGE) THEN
  ASM_REWRITE_TAC[]);;
let EBV_EQ_TABLE_ENTRY = prove
 (`!D (E:A->A->bool) B leq a w sIN sEQ u v pr z.
      model D E ZF_AX /\ ecba D E B leq /\ B IN D /\
      a IN D /\ eordinal D E a /\ ebnstage D E B a w /\ w IN D /\
      u IN D /\ v IN D /\ E u w /\ E v w /\
      ebvatt D E B leq w sIN sEQ /\ eopair D E u v pr /\
      eapply D E sEQ pr z /\ z IN D
      ==> ebv_eq D E B leq u v z`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `eisfun D (E:A->A->bool) sEQ` ASSUME_TAC THENL
   [FIRST_ASSUM(ACCEPT_TAC o CONJUNCT1 o CONJUNCT2 o REWRITE_RULE[ebvatt]);
    ALL_TAC] THEN
  SUBGOAL_THEN `(pr:A) IN D` ASSUME_TAC THENL
   [FIRST_ASSUM(ACCEPT_TAC o MATCH_MP EOPAIR_IN); ALL_TAC] THEN
  MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `B:A`; `leq:A`; `w:A`; `sIN:A`;
    `sEQ:A`; `u:A`; `v:A`; `pr:A`] EBVATT_VAL) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(CONJUNCTS_THEN2 (K ALL_TAC)
    (X_CHOOSE_THEN `ve:A` STRIP_ASSUME_TAC)) THEN
  SUBGOAL_THEN `(z:A) = ve` SUBST_ALL_TAC THENL
   [MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `sEQ:A`; `pr:A`; `z:A`;
      `ve:A`] EAPPLY_UNIQUE) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MATCH_MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `B:A`; `leq:A`; `a:A`;
    `w:A`; `sIN:A`; `sEQ:A`; `u:A`; `v:A`; `ve:A`] EBV_EQ_AT_STAGE) THEN
  ASM_REWRITE_TAC[]);;

(* ===================================================================== *)
(* F4: ebv_in/ebv_eq as B-VALUED FUNCTIONS.                               *)
(* EBV_IN/EQ_IN_B: for outputs in D the value is in the Boolean algebra B *)
(* (via EBVATT_VAL + EAPPLY_UNIQUE + EBVIN/EBVEQ_IN).  ebvinf/ebveqf: the  *)
(* functional [[u IN v]]/[[u=v]] = the unique in-D value (Hilbert @).      *)
(* EBVINF/EBVEQF_SPEC (satisfies the relation, in D, via EBV_TOTAL +       *)
(* SELECT_RULE + EBV_IN/EQ_UNIQUE for well-definedness) + _IN_B.  These    *)
(* are the atomic building blocks for INC4 bval (i%%j, Eq i j).           *)
(* ===================================================================== *)

let EBV_IN_IN_B = prove
 (`!D (E:A->A->bool) B leq u v z.
      model D E ZF_AX /\ ecba D E B leq /\ B IN D /\
      u IN D /\ v IN D /\ z IN D /\ ebv_in D E B leq u v z
      ==> E z B`,
  REPEAT GEN_TAC THEN
  DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC (CONJUNCTS_THEN2 ASSUME_TAC
    (CONJUNCTS_THEN2 ASSUME_TAC (CONJUNCTS_THEN2 ASSUME_TAC
    (CONJUNCTS_THEN2 ASSUME_TAC (CONJUNCTS_THEN2 ASSUME_TAC
    (fun th -> MP_TAC(REWRITE_RULE[ebv_in] th)))))))) THEN
  DISCH_THEN(X_CHOOSE_THEN `a:A` (X_CHOOSE_THEN `w:A` (X_CHOOSE_THEN `sIN:A`
    (X_CHOOSE_THEN `sEQ:A` (X_CHOOSE_THEN `pr:A` STRIP_ASSUME_TAC))))) THEN
  SUBGOAL_THEN `eisfun D (E:A->A->bool) sIN` ASSUME_TAC THENL
   [FIRST_ASSUM(ACCEPT_TAC o CONJUNCT1 o REWRITE_RULE[ebvatt]); ALL_TAC] THEN
  SUBGOAL_THEN `(pr:A) IN D` ASSUME_TAC THENL
   [FIRST_ASSUM(ACCEPT_TAC o MATCH_MP EOPAIR_IN); ALL_TAC] THEN
  MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `B:A`; `leq:A`; `w:A`; `sIN:A`;
    `sEQ:A`; `u:A`; `v:A`; `pr:A`] EBVATT_VAL) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(CONJUNCTS_THEN2 (X_CHOOSE_THEN `vi:A` STRIP_ASSUME_TAC)
    (K ALL_TAC)) THEN
  SUBGOAL_THEN `(z:A) = vi` SUBST_ALL_TAC THENL
   [MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `sIN:A`; `pr:A`; `z:A`;
      `vi:A`] EAPPLY_UNIQUE) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  FIRST_ASSUM(fun th -> ACCEPT_TAC(CONJUNCT2(MATCH_MP EBVIN_IN th))));;
let EBV_EQ_IN_B = prove
 (`!D (E:A->A->bool) B leq u v z.
      model D E ZF_AX /\ ecba D E B leq /\ B IN D /\
      u IN D /\ v IN D /\ z IN D /\ ebv_eq D E B leq u v z
      ==> E z B`,
  REPEAT GEN_TAC THEN
  DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC (CONJUNCTS_THEN2 ASSUME_TAC
    (CONJUNCTS_THEN2 ASSUME_TAC (CONJUNCTS_THEN2 ASSUME_TAC
    (CONJUNCTS_THEN2 ASSUME_TAC (CONJUNCTS_THEN2 ASSUME_TAC
    (fun th -> MP_TAC(REWRITE_RULE[ebv_eq] th)))))))) THEN
  DISCH_THEN(X_CHOOSE_THEN `a:A` (X_CHOOSE_THEN `w:A` (X_CHOOSE_THEN `sIN:A`
    (X_CHOOSE_THEN `sEQ:A` (X_CHOOSE_THEN `pr:A` STRIP_ASSUME_TAC))))) THEN
  SUBGOAL_THEN `eisfun D (E:A->A->bool) sEQ` ASSUME_TAC THENL
   [FIRST_ASSUM(ACCEPT_TAC o CONJUNCT1 o CONJUNCT2 o REWRITE_RULE[ebvatt]);
    ALL_TAC] THEN
  SUBGOAL_THEN `(pr:A) IN D` ASSUME_TAC THENL
   [FIRST_ASSUM(ACCEPT_TAC o MATCH_MP EOPAIR_IN); ALL_TAC] THEN
  MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `B:A`; `leq:A`; `w:A`; `sIN:A`;
    `sEQ:A`; `u:A`; `v:A`; `pr:A`] EBVATT_VAL) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(CONJUNCTS_THEN2 (K ALL_TAC)
    (X_CHOOSE_THEN `ve:A` STRIP_ASSUME_TAC)) THEN
  SUBGOAL_THEN `(z:A) = ve` SUBST_ALL_TAC THENL
   [MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `sEQ:A`; `pr:A`; `z:A`;
      `ve:A`] EAPPLY_UNIQUE) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  FIRST_ASSUM(fun th -> ACCEPT_TAC(CONJUNCT2(MATCH_MP EBVEQ_IN th))));;

(* ===================================================================== *)
(* F4 SUP/INF equations (stage-relative form): the functional             *)
(* value ebvinf/ebveqf, at ANY covering bname-stage, IS the local table's  *)
(* ebvin/ebveq value.  ebvinf u v = ebvin sEQ v u = SUP_{y in dom v}       *)
(* (v(y) MEET sEQ<u,y>); with EBV_EQ_TABLE_ENTRY (sEQ<u,y>=ebv_eq(u,y))    *)
(* this is the Bell/Jech SUP over ebv_eq.  Via EBVATT_VAL + EBV_IN/EQ_AT_   *)
(* STAGE + EBVINF/EBVEQF_SPEC + EBV_IN/EQ_UNIQUE.                          *)
(* ===================================================================== *)

(* ===================================================================== *)
(* F4 (object forms for the Boolean value; first component).              *)
(* ebnstage_form = rec_form bname_step_form 3: the bname-STAGE as an       *)
(* object formula (input ordinal at slot 3, output at slot 4, B at slot 2).*)
(* HOLDS_EBNSTAGE_FORM bridges it to ebnstage (v 2) via HOLDS_REC_FORM +   *)
(* EBNSTAGE_EREC.  A reusable piece for ebv_in_form/ebv_eq_form (the       *)
(* object formula for the global atomic Boolean value).                   *)
(* ===================================================================== *)

(* ===================================================================== *)
(* F4: eisfun_form -- the eisfun predicate as an                           *)
(* OBJECT formula (for ebvatt_form -> ebv_in_form).  EISFUN_ALT gives the  *)
(* apply-based characterisation (single-valued via eapply); eisfun_form    *)
(* isf = (elements-are-pairs) && (apply-single-valued), fresh slots        *)
(* isf+1..isf+4.  Body lemmas EISFUN_B1I/B1/B2; HOLDS_EISFUN_FORM bridges   *)
(* holds v (eisfun_form isf) <=> eisfun D E (v isf).                       *)
(* ===================================================================== *)

let EISFUN_ALT = prove
 (`!D (E:A->A->bool) f.
      eisfun D E f <=>
        f IN D /\
        (!z. z IN D /\ E z f ==> ?u w. u IN D /\ w IN D /\ eopair D E u w z) /\
        (!u w w'. u IN D /\ w IN D /\ w' IN D /\
                  eapply D E f u w /\ eapply D E f u w' ==> w = w')`,
  REPEAT GEN_TAC THEN REWRITE_TAC[eisfun; eapply] THEN
  MATCH_MP_TAC(TAUT `(c <=> d) ==> (a /\ b /\ c <=> a /\ b /\ d)`) THEN
  EQ_TAC THEN DISCH_TAC THENL
   [MAP_EVERY X_GEN_TAC [`u:A`; `w:A`; `w':A`] THEN
    DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC (CONJUNCTS_THEN2 ASSUME_TAC
      (CONJUNCTS_THEN2 ASSUME_TAC (CONJUNCTS_THEN2
        (X_CHOOSE_THEN `z:A` STRIP_ASSUME_TAC)
        (X_CHOOSE_THEN `z':A` STRIP_ASSUME_TAC))))) THEN
    FIRST_X_ASSUM(fun th -> MATCH_MP_TAC(SPECL
      [`u:A`; `w:A`; `w':A`; `z:A`; `z':A`] th)) THEN
    ASM_REWRITE_TAC[];
    MAP_EVERY X_GEN_TAC [`u:A`; `w:A`; `w':A`; `z:A`; `z':A`] THEN
    STRIP_TAC THEN
    FIRST_X_ASSUM(MATCH_MP_TAC o SPECL [`u:A`; `w:A`; `w':A`]) THEN
    ASM_REWRITE_TAC[] THEN
    CONJ_TAC THENL [EXISTS_TAC `z:A`; EXISTS_TAC `z':A`] THEN
    ASM_REWRITE_TAC[]]);;

let eisfun_form = new_definition
 `eisfun_form isf =
    (!! (isf + 1) (((isf + 1) %% isf)
        --> ?? (isf + 2)
          (?? (isf + 3) (opair_form (isf + 2) (isf + 3) (isf + 1)))))
    && (!! (isf + 2) (!! (isf + 3) (!! (isf + 4)
         ((apply_form isf (isf + 2) (isf + 3) &&
           apply_form isf (isf + 2) (isf + 4))
          --> Eq (isf + 3) (isf + 4)))))`;;

let EISFUN_B1I = prove
 (`!D (E:A->A->bool) v isf a b c.
      model D E ZF_AX /\ valuation D v /\ a IN D /\ b IN D /\ c IN D
      ==> (holds D E
           (((isf + 3) |-> c) (((isf + 2) |-> b) (((isf + 1) |-> a) v)))
           (opair_form (isf + 2) (isf + 3) (isf + 1)) <=> eopair D E b c a)`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN
    `~(isf + 2 = isf + 3) /\ ~(isf + 1 = isf + 3) /\ ~(isf + 1 = isf + 2)`
  STRIP_ASSUME_TAC THENL [ARITH_TAC; ALL_TAC] THEN
  SUBGOAL_THEN
   `valuation D
    (((isf + 3) |-> c) (((isf + 2) |-> b) (((isf + 1) |-> (a:A)) v)))`
  ASSUME_TAC THENL [ASM_SIMP_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
  ASM_SIMP_TAC[HOLDS_OPAIR_FORM] THEN
  ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER]);;

let EISFUN_B1 = prove
 (`!D (E:A->A->bool) v isf a.
      model D E ZF_AX /\ valuation D v /\ a IN D
      ==> (holds D E (((isf + 1) |-> a) v)
             (((isf + 1) %% isf)
              --> ?? (isf + 2) (?? (isf + 3)
                     (opair_form (isf + 2) (isf + 3) (isf + 1))))
           <=> (E a (v isf) ==> ?u w. u IN D /\ w IN D /\ eopair D E u w a))`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `~(isf = isf + 1)` ASSUME_TAC THENL [ARITH_TAC; ALL_TAC] THEN
  SUBGOAL_THEN `valuation D (((isf + 1) |-> (a:A)) v)` ASSUME_TAC THENL
   [ASM_SIMP_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
  REWRITE_TAC[el 3 (CONJUNCTS holds); HOLDS_MEM; HOLDS_EX] THEN
  ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER] THEN
  MATCH_MP_TAC(TAUT `(q1 <=> q2) ==> ((p ==> q1) <=> (p ==> q2))`) THEN
  EQ_TAC THENL
   [DISCH_THEN(X_CHOOSE_THEN `b:A` (CONJUNCTS_THEN2 ASSUME_TAC
      (X_CHOOSE_THEN `c:A` (CONJUNCTS_THEN2 ASSUME_TAC ASSUME_TAC)))) THEN
    MAP_EVERY EXISTS_TAC [`b:A`; `c:A`] THEN ASM_REWRITE_TAC[] THEN
    MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `v:num->A`; `isf:num`; `a:A`;
      `b:A`; `c:A`] EISFUN_B1I) THEN ASM_REWRITE_TAC[];
    DISCH_THEN(X_CHOOSE_THEN `b:A` (X_CHOOSE_THEN `c:A`
      (CONJUNCTS_THEN2 ASSUME_TAC
       (CONJUNCTS_THEN2 ASSUME_TAC ASSUME_TAC)))) THEN
    EXISTS_TAC `b:A` THEN ASM_REWRITE_TAC[] THEN
    EXISTS_TAC `c:A` THEN ASM_REWRITE_TAC[] THEN
    MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `v:num->A`; `isf:num`; `a:A`;
      `b:A`; `c:A`] EISFUN_B1I) THEN ASM_REWRITE_TAC[]]);;

let EISFUN_B2 = prove
 (`!D (E:A->A->bool) v isf a2 a3 a4.
      model D E ZF_AX /\ valuation D v /\ a2 IN D /\ a3 IN D /\ a4 IN D
      ==> (holds D E
           (((isf + 4) |-> a4) (((isf + 3) |-> a3) (((isf + 2) |-> a2) v)))
           ((apply_form isf (isf + 2) (isf + 3) &&
               apply_form isf (isf + 2) (isf + 4)) --> Eq (isf + 3) (isf + 4))
           <=> (eapply D E (v isf) a2 a3 /\
                eapply D E (v isf) a2 a4 ==> a3 = a4))`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN
   `~(isf = isf + 2) /\ ~(isf = isf + 3) /\ ~(isf = isf + 4) /\
    ~(isf + 2 = isf + 3) /\ ~(isf + 2 = isf + 4) /\ ~(isf + 3 = isf + 4)`
  STRIP_ASSUME_TAC THENL [ARITH_TAC; ALL_TAC] THEN
  SUBGOAL_THEN
   `valuation D
    (((isf + 4) |-> a4) (((isf + 3) |-> a3) (((isf + 2) |-> (a2:A)) v)))`
  ASSUME_TAC THENL [ASM_SIMP_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
  REWRITE_TAC[el 3 (CONJUNCTS holds); HOLDS_AND; el 2 (CONJUNCTS holds)] THEN
  ASM_SIMP_TAC[HOLDS_APPLY_FORM] THEN
  ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER]);;

let HOLDS_EISFUN_FORM = prove
 (`!D (E:A->A->bool) v isf.
      model D E ZF_AX /\ valuation D v
      ==> (holds D E v (eisfun_form isf) <=> eisfun D E (v isf))`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `!x. (v:num->A) x IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[valuation]; ALL_TAC] THEN
  REWRITE_TAC[eisfun_form; HOLDS_AND] THEN
  REWRITE_TAC[last(CONJUNCTS holds)] THEN
  ASM_SIMP_TAC[EISFUN_B1; EISFUN_B2] THEN
  REWRITE_TAC[EISFUN_ALT] THEN
  SUBGOAL_THEN `(v:num->A) isf IN D` (fun th -> REWRITE_TAC[th]) THENL
   [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MATCH_MP_TAC(TAUT
               `((x <=> a) /\ (y <=> b)) ==> ((x /\ y) <=> (a /\ b))`) THEN
  CONJ_TAC THEN MESON_TAC[]);;

(* ===================================================================== *)
(* F4: ebvatt_form -- the ebvatt (Boolean-value attempt) predicate         *)
(* as an OBJECT formula.  eisfun_form sIN && eisfun_form sEQ &&             *)
(* (?c cross_form&domain&domain) && reading-IN && reading-EQ clauses.       *)
(* Body-lemma chain per reading clause: _INNER (opair&&apply&&ebvin/eq_form *)
(* leaf) -> _BODY (?pr?val, EOPAIR_IN/EBVIN/EBVEQ_IN for backward in-D) ->   *)
(* the !!-clause; _CDOM for the cross/domain clause.  HOLDS_EBVATT_FORM      *)
(* composes all via HOLDS_EISFUN_FORM + the clause bridges + REWRITE[ebvatt].*)
(* ===================================================================== *)

let ebvatt_form = new_definition
 `ebvatt_form iw isIN isEQ ileq iB =
    eisfun_form isIN
    && eisfun_form isEQ
    && (?? ((MAX iw (MAX isIN (MAX isEQ (MAX ileq iB)))) + 1)
          (cross_form iw iw ((MAX iw (MAX isIN (MAX isEQ (MAX ileq iB)))) + 1)
           && domain_form isIN
             ((MAX iw (MAX isIN (MAX isEQ (MAX ileq iB)))) + 1)
           && domain_form isEQ
             ((MAX iw (MAX isIN (MAX isEQ (MAX ileq iB)))) + 1)))
    && (!! ((MAX iw (MAX isIN (MAX isEQ (MAX ileq iB)))) + 2)
        (!! ((MAX iw (MAX isIN (MAX isEQ (MAX ileq iB)))) + 3)
         ((((MAX iw (MAX isIN (MAX isEQ (MAX ileq iB)))) + 2) %% iw &&
           ((MAX iw (MAX isIN (MAX isEQ (MAX ileq iB)))) + 3) %% iw)
          --> ?? ((MAX iw (MAX isIN (MAX isEQ (MAX ileq iB)))) + 4)
            (?? ((MAX iw (MAX isIN (MAX isEQ (MAX ileq iB)))) + 5)
             (opair_form ((MAX iw (MAX isIN (MAX isEQ (MAX ileq iB)))) + 2)
              ((MAX iw (MAX isIN (MAX isEQ (MAX ileq iB)))) + 3)
              ((MAX iw (MAX isIN (MAX isEQ (MAX ileq iB)))) + 4)
              && apply_form isIN
                ((MAX iw (MAX isIN (MAX isEQ (MAX ileq iB)))) + 4)
                ((MAX iw (MAX isIN (MAX isEQ (MAX ileq iB)))) + 5)
                && ebvin_form
                  ((MAX iw (MAX isIN (MAX isEQ (MAX ileq iB)))) + 5) isEQ
                  ((MAX iw (MAX isIN (MAX isEQ (MAX ileq iB)))) + 3)
                  ((MAX iw (MAX isIN (MAX isEQ (MAX ileq iB)))) + 2)
                  ileq iB)))))
    && (!! ((MAX iw (MAX isIN (MAX isEQ (MAX ileq iB)))) + 2)
        (!! ((MAX iw (MAX isIN (MAX isEQ (MAX ileq iB)))) + 3)
         ((((MAX iw (MAX isIN (MAX isEQ (MAX ileq iB)))) + 2) %% iw &&
           ((MAX iw (MAX isIN (MAX isEQ (MAX ileq iB)))) + 3) %% iw)
          --> ?? ((MAX iw (MAX isIN (MAX isEQ (MAX ileq iB)))) + 4)
            (?? ((MAX iw (MAX isIN (MAX isEQ (MAX ileq iB)))) + 5)
             (opair_form ((MAX iw (MAX isIN (MAX isEQ (MAX ileq iB)))) + 2)
              ((MAX iw (MAX isIN (MAX isEQ (MAX ileq iB)))) + 3)
              ((MAX iw (MAX isIN (MAX isEQ (MAX ileq iB)))) + 4)
              && apply_form isEQ
                ((MAX iw (MAX isIN (MAX isEQ (MAX ileq iB)))) + 4)
                ((MAX iw (MAX isIN (MAX isEQ (MAX ileq iB)))) + 5)
                && ebveq_form
                  ((MAX iw (MAX isIN (MAX isEQ (MAX ileq iB)))) + 5) isIN
                  ((MAX iw (MAX isIN (MAX isEQ (MAX ileq iB)))) + 2)
                  ((MAX iw (MAX isIN (MAX isEQ (MAX ileq iB)))) + 3)
                  ileq iB)))))`;;

let EBVATT_RIN_INNER = prove
 (`!D (E:A->A->bool) v iw isIN isEQ ileq iB uu vv pr' val'.
      model D E ZF_AX /\ valuation D v /\
      uu IN D /\ vv IN D /\ pr' IN D /\ val' IN D
      ==> (holds D E
           ((((MAX iw (MAX isIN (MAX isEQ (MAX ileq iB)))) + 5) |-> val')
            ((((MAX iw (MAX isIN (MAX isEQ (MAX ileq iB)))) + 4) |-> pr')
             ((((MAX iw (MAX isIN (MAX isEQ (MAX ileq iB)))) + 3) |-> vv)
              ((((MAX iw (MAX isIN (MAX isEQ (MAX ileq iB)))) + 2)
                |-> uu) v))))
           (opair_form ((MAX iw (MAX isIN (MAX isEQ (MAX ileq iB)))) + 2)
            ((MAX iw (MAX isIN (MAX isEQ (MAX ileq iB)))) + 3)
            ((MAX iw (MAX isIN (MAX isEQ (MAX ileq iB)))) + 4)
            && apply_form isIN
              ((MAX iw (MAX isIN (MAX isEQ (MAX ileq iB)))) + 4)
              ((MAX iw (MAX isIN (MAX isEQ (MAX ileq iB)))) + 5)
              && ebvin_form ((MAX iw (MAX isIN (MAX isEQ (MAX ileq iB)))) + 5)
                isEQ ((MAX iw (MAX isIN (MAX isEQ (MAX ileq iB)))) + 3)
                ((MAX iw (MAX isIN (MAX isEQ (MAX ileq iB)))) + 2) ileq iB)
           <=> (eopair D E uu vv pr' /\ eapply D E (v isIN) pr' val' /\
                ebvin D E (v iB) (v ileq) (v isEQ) vv uu val'))`,
  REPEAT STRIP_TAC THEN
  ABBREV_TAC `M = (MAX iw (MAX isIN (MAX isEQ (MAX ileq iB))))` THEN
  SUBGOAL_THEN
   `~((isIN) = (M + 2)) /\
    ~((isIN) = (M + 3)) /\
    ~((isIN) = (M + 4)) /\
    ~((isIN) = (M + 5)) /\
    ~((isEQ) = (M + 2)) /\
    ~((isEQ) = (M + 3)) /\
    ~((isEQ) = (M + 4)) /\
    ~((isEQ) = (M + 5)) /\
    ~((ileq) = (M + 2)) /\
    ~((ileq) = (M + 3)) /\
    ~((ileq) = (M + 4)) /\
    ~((ileq) = (M + 5)) /\
    ~((iB) = (M + 2)) /\
    ~((iB) = (M + 3)) /\
    ~((iB) = (M + 4)) /\
    ~((iB) = (M + 5)) /\
    ~((M + 2) = (M + 3)) /\
    ~((M + 2) = (M + 4)) /\
    ~((M + 2) = (M + 5)) /\
    ~((M + 3) = (M + 2)) /\
    ~((M + 3) = (M + 4)) /\
    ~((M + 3) = (M + 5)) /\
    ~((M + 4) = (M + 2)) /\
    ~((M + 4) = (M + 3)) /\
    ~((M + 4) = (M + 5))`
  STRIP_ASSUME_TAC THENL [EXPAND_TAC "M" THEN ARITH_TAC; ALL_TAC] THEN
  SUBGOAL_THEN
    `valuation D
     (((M + 5) |-> val')
      (((M + 4) |-> pr') (((M + 3) |-> vv) (((M + 2) |-> (uu:A)) v))))`
    ASSUME_TAC THENL
   [REPEAT(MATCH_MP_TAC VALUATION_VALMOD THEN CONJ_TAC THENL
      [ALL_TAC; FIRST_ASSUM ACCEPT_TAC]) THEN FIRST_ASSUM ACCEPT_TAC;
    ALL_TAC] THEN
  REWRITE_TAC[HOLDS_AND] THEN
  ASM_SIMP_TAC[HOLDS_OPAIR_FORM; HOLDS_APPLY_FORM; HOLDS_EBVIN_FORM] THEN
  ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER]);;

let EBVATT_RIN_BODY = prove
 (`!D (E:A->A->bool) v iw isIN isEQ ileq iB uu vv.
      model D E ZF_AX /\ valuation D v /\ uu IN D /\ vv IN D
      ==> (holds D E
           ((((MAX iw (MAX isIN (MAX isEQ (MAX ileq iB)))) + 3) |-> vv)
            ((((MAX iw (MAX isIN (MAX isEQ (MAX ileq iB)))) + 2) |-> uu) v))
           (((((MAX iw (MAX isIN (MAX isEQ (MAX ileq iB)))) + 2) %% iw &&
              ((MAX iw (MAX isIN (MAX isEQ (MAX ileq iB)))) + 3) %% iw)
             --> ?? ((MAX iw (MAX isIN (MAX isEQ (MAX ileq iB)))) + 4)
               (?? ((MAX iw (MAX isIN (MAX isEQ (MAX ileq iB)))) + 5)
                (opair_form ((MAX iw (MAX isIN (MAX isEQ (MAX ileq iB)))) + 2)
                 ((MAX iw (MAX isIN (MAX isEQ (MAX ileq iB)))) + 3)
                 ((MAX iw (MAX isIN (MAX isEQ (MAX ileq iB)))) + 4)
                 && apply_form isIN
                   ((MAX iw (MAX isIN (MAX isEQ (MAX ileq iB)))) + 4)
                   ((MAX iw (MAX isIN (MAX isEQ (MAX ileq iB)))) + 5)
                && ebvin_form
                  ((MAX iw (MAX isIN (MAX isEQ (MAX ileq iB)))) + 5) isEQ
                  ((MAX iw (MAX isIN (MAX isEQ (MAX ileq iB)))) + 3)
                  ((MAX iw (MAX isIN (MAX isEQ (MAX ileq iB)))) +
                   2) ileq iB))))
           <=> (E uu (v iw) /\ E vv (v iw)
                ==> ?pr val. eopair D E uu vv pr /\
                  eapply D E (v isIN) pr val /\
                             ebvin D E (v iB) (v ileq) (v isEQ) vv uu val))`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN
    `~(((MAX iw (MAX isIN (MAX isEQ (MAX ileq iB)))) + 2) =
       ((MAX iw (MAX isIN (MAX isEQ (MAX ileq iB)))) + 3)) /\
     ~(iw = ((MAX iw (MAX isIN (MAX isEQ (MAX ileq iB)))) + 2)) /\
     ~(iw = ((MAX iw (MAX isIN (MAX isEQ (MAX ileq iB)))) + 3))`
  STRIP_ASSUME_TAC THENL [ARITH_TAC; ALL_TAC] THEN
  SUBGOAL_THEN
    `valuation D
     ((((MAX iw (MAX isIN (MAX isEQ (MAX ileq iB)))) + 2) |-> (uu:A)) v)`
    ASSUME_TAC THENL
   [ASM_SIMP_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
  SUBGOAL_THEN
    `valuation D
     ((((MAX iw (MAX isIN (MAX isEQ (MAX ileq iB)))) + 3) |-> vv)
      ((((MAX iw (MAX isIN (MAX isEQ (MAX ileq iB)))) + 2) |-> (uu:A)) v))`
    ASSUME_TAC THENL
   [ASM_SIMP_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
  REWRITE_TAC[el 3 (CONJUNCTS holds); HOLDS_AND; HOLDS_MEM] THEN
  ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER] THEN
  MATCH_MP_TAC(TAUT `(q1 <=> q2) ==> ((p ==> q1) <=> (p ==> q2))`) THEN
  REWRITE_TAC[HOLDS_EX] THEN
  EQ_TAC THENL
   [DISCH_THEN(X_CHOOSE_THEN `pr':A` (CONJUNCTS_THEN2 ASSUME_TAC
      (X_CHOOSE_THEN `val':A` (CONJUNCTS_THEN2 ASSUME_TAC ASSUME_TAC)))) THEN
    MAP_EVERY EXISTS_TAC [`pr':A`; `val':A`] THEN
    MP_TAC(ISPECL
           [`D:A->bool`; `E:A->A->bool`; `v:num->A`; `iw:num`; `isIN:num`;
            `isEQ:num`; `ileq:num`; `iB:num`; `uu:A`; `vv:A`;
            `pr':A`; `val':A`]
      EBVATT_RIN_INNER) THEN ASM_REWRITE_TAC[];
    DISCH_THEN(X_CHOOSE_THEN `pr':A` (X_CHOOSE_THEN `val':A`
      (CONJUNCTS_THEN2 ASSUME_TAC
       (CONJUNCTS_THEN2 ASSUME_TAC ASSUME_TAC)))) THEN
    SUBGOAL_THEN `(pr':A) IN D` ASSUME_TAC THENL
     [FIRST_ASSUM(ACCEPT_TAC o MATCH_MP EOPAIR_IN); ALL_TAC] THEN
    SUBGOAL_THEN `(val':A) IN D` ASSUME_TAC THENL
     [FIRST_ASSUM(ACCEPT_TAC o CONJUNCT1 o MATCH_MP EBVIN_IN); ALL_TAC] THEN
    EXISTS_TAC `pr':A` THEN ASM_REWRITE_TAC[] THEN
    EXISTS_TAC `val':A` THEN ASM_REWRITE_TAC[] THEN
    MP_TAC(ISPECL
           [`D:A->bool`; `E:A->A->bool`; `v:num->A`; `iw:num`; `isIN:num`;
            `isEQ:num`; `ileq:num`; `iB:num`; `uu:A`; `vv:A`;
            `pr':A`; `val':A`]
      EBVATT_RIN_INNER) THEN ASM_REWRITE_TAC[]]);;

let EBVATT_RIN = prove
 (`!D (E:A->A->bool) v iw isIN isEQ ileq iB.
      model D E ZF_AX /\ valuation D v
      ==> (holds D E v
           (!! ((MAX iw (MAX isIN (MAX isEQ (MAX ileq iB)))) + 2)
            (!! ((MAX iw (MAX isIN (MAX isEQ (MAX ileq iB)))) + 3)
             ((((MAX iw (MAX isIN (MAX isEQ (MAX ileq iB)))) + 2) %% iw &&
               ((MAX iw (MAX isIN (MAX isEQ (MAX ileq iB)))) + 3) %% iw)
              --> ?? ((MAX iw (MAX isIN (MAX isEQ (MAX ileq iB)))) + 4)
                (?? ((MAX iw (MAX isIN (MAX isEQ (MAX ileq iB)))) + 5)
                 (opair_form ((MAX iw (MAX isIN (MAX isEQ (MAX ileq iB)))) + 2)
                  ((MAX iw (MAX isIN (MAX isEQ (MAX ileq iB)))) + 3)
                  ((MAX iw (MAX isIN (MAX isEQ (MAX ileq iB)))) + 4)
                  && apply_form isIN
                    ((MAX iw (MAX isIN (MAX isEQ (MAX ileq iB)))) + 4)
                    ((MAX iw (MAX isIN (MAX isEQ (MAX ileq iB)))) + 5)
                && ebvin_form
                  ((MAX iw (MAX isIN (MAX isEQ (MAX ileq iB)))) + 5) isEQ
                  ((MAX iw (MAX isIN (MAX isEQ (MAX ileq iB)))) + 3)
                  ((MAX iw (MAX isIN (MAX isEQ (MAX ileq iB)))) + 2)
                  ileq iB)))))
           <=> (!u v'. u IN D /\ v' IN D /\ E u (v iw) /\ E v' (v iw)
                       ==> ?pr val. eopair D E u v' pr /\
                         eapply D E (v isIN) pr val /\
                                    ebvin D E (v iB) (v ileq) (v isEQ)
                                      v' u val))`,
  REPEAT STRIP_TAC THEN
  REWRITE_TAC[last(CONJUNCTS holds)] THEN
  ASM_SIMP_TAC[EBVATT_RIN_BODY] THEN
  MESON_TAC[]);;

let EBVATT_REQ_INNER = prove
 (`!D (E:A->A->bool) v iw isIN isEQ ileq iB uu vv pr' val'.
      model D E ZF_AX /\ valuation D v /\
      uu IN D /\ vv IN D /\ pr' IN D /\ val' IN D
      ==> (holds D E
           ((((MAX iw (MAX isIN (MAX isEQ (MAX ileq iB)))) + 5) |-> val')
            ((((MAX iw (MAX isIN (MAX isEQ (MAX ileq iB)))) + 4) |-> pr')
             ((((MAX iw (MAX isIN (MAX isEQ (MAX ileq iB)))) + 3) |-> vv)
              ((((MAX iw (MAX isIN (MAX isEQ (MAX ileq iB)))) + 2)
                |-> uu) v))))
           (opair_form ((MAX iw (MAX isIN (MAX isEQ (MAX ileq iB)))) + 2)
            ((MAX iw (MAX isIN (MAX isEQ (MAX ileq iB)))) + 3)
            ((MAX iw (MAX isIN (MAX isEQ (MAX ileq iB)))) + 4)
            && apply_form isEQ
              ((MAX iw (MAX isIN (MAX isEQ (MAX ileq iB)))) + 4)
              ((MAX iw (MAX isIN (MAX isEQ (MAX ileq iB)))) + 5)
              && ebveq_form ((MAX iw (MAX isIN (MAX isEQ (MAX ileq iB)))) + 5)
                isIN ((MAX iw (MAX isIN (MAX isEQ (MAX ileq iB)))) + 2)
                ((MAX iw (MAX isIN (MAX isEQ (MAX ileq iB)))) + 3) ileq iB)
           <=> (eopair D E uu vv pr' /\ eapply D E (v isEQ) pr' val' /\
                ebveq D E (v iB) (v ileq) (v isIN) uu vv val'))`,
  REPEAT STRIP_TAC THEN
  ABBREV_TAC `M = (MAX iw (MAX isIN (MAX isEQ (MAX ileq iB))))` THEN
  SUBGOAL_THEN `~((isIN) = (M + 2)) /\
    ~((isIN) = (M + 3)) /\
    ~((isIN) = (M + 4)) /\
    ~((isIN) = (M + 5)) /\
    ~((isEQ) = (M + 2)) /\
    ~((isEQ) = (M + 3)) /\
    ~((isEQ) = (M + 4)) /\
    ~((isEQ) = (M + 5)) /\
    ~((ileq) = (M + 2)) /\
    ~((ileq) = (M + 3)) /\
    ~((ileq) = (M + 4)) /\
    ~((ileq) = (M + 5)) /\
    ~((iB) = (M + 2)) /\
    ~((iB) = (M + 3)) /\
    ~((iB) = (M + 4)) /\
    ~((iB) = (M + 5)) /\
    ~((M + 2) = (M + 3)) /\
    ~((M + 2) = (M + 4)) /\
    ~((M + 2) = (M + 5)) /\
    ~((M + 3) = (M + 2)) /\
    ~((M + 3) = (M + 4)) /\
    ~((M + 3) = (M + 5)) /\
    ~((M + 4) = (M + 2)) /\
    ~((M + 4) = (M + 3)) /\
    ~((M + 4) = (M + 5))` STRIP_ASSUME_TAC THENL
  [EXPAND_TAC "M" THEN ARITH_TAC; ALL_TAC] THEN
  SUBGOAL_THEN
    `valuation D
     (((M + 5) |-> val')
      (((M + 4) |-> pr') (((M + 3) |-> vv) (((M + 2) |-> (uu:A)) v))))`
    ASSUME_TAC THENL
   [REPEAT(MATCH_MP_TAC VALUATION_VALMOD THEN CONJ_TAC THENL
      [ALL_TAC; FIRST_ASSUM ACCEPT_TAC]) THEN FIRST_ASSUM ACCEPT_TAC;
     ALL_TAC] THEN
  REWRITE_TAC[HOLDS_AND] THEN
  ASM_SIMP_TAC[HOLDS_OPAIR_FORM; HOLDS_APPLY_FORM; HOLDS_EBVEQ_FORM] THEN
  ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER]);;

