            `pr':A`; `val':A`]
      EBVATT_REQ_INNER) THEN ASM_REWRITE_TAC[]]);;

let EBVATT_REQ = prove
 (`!D (E:A->A->bool) v iw isIN isEQ ileq iB.
      model D E ZF_AX /\ valuation D v
      ==> (holds D E v
           (!! ((MAX iw (MAX isIN (MAX isEQ (MAX ileq iB)))) + 2)
            (!! ((MAX iw (MAX isIN (MAX isEQ (MAX ileq iB)))) + 3)
             ((((MAX iw (MAX isIN (MAX isEQ (MAX ileq iB)))) + 2) %% iw &&
               ((MAX iw (MAX isIN (MAX isEQ (MAX ileq iB)))) + 3) %% iw)
              --> ?? ((MAX iw (MAX isIN (MAX isEQ (MAX ileq iB)))) + 4)
                (?? ((MAX iw (MAX isIN (MAX isEQ (MAX ileq iB)))) + 5)
                 (opair_form ((MAX iw (MAX isIN (MAX isEQ (MAX ileq iB)))) + 2)
                  ((MAX iw (MAX isIN (MAX isEQ (MAX ileq iB)))) + 3)
                  ((MAX iw (MAX isIN (MAX isEQ (MAX ileq iB)))) + 4)
                  && apply_form isEQ
                    ((MAX iw (MAX isIN (MAX isEQ (MAX ileq iB)))) + 4)
                    ((MAX iw (MAX isIN (MAX isEQ (MAX ileq iB)))) + 5)
                && ebveq_form
                  ((MAX iw (MAX isIN (MAX isEQ (MAX ileq iB)))) + 5) isIN
                  ((MAX iw (MAX isIN (MAX isEQ (MAX ileq iB)))) + 2)
                  ((MAX iw (MAX isIN (MAX isEQ (MAX ileq iB)))) + 3)
                  ileq iB)))))
           <=> (!u v'. u IN D /\ v' IN D /\ E u (v iw) /\ E v' (v iw)
                       ==> ?pr val. eopair D E u v' pr /\
                         eapply D E (v isEQ) pr val /\
                                    ebveq D E (v iB) (v ileq) (v isIN)
                                      u v' val))`,
  REPEAT STRIP_TAC THEN
  REWRITE_TAC[last(CONJUNCTS holds)] THEN
  ASM_SIMP_TAC[EBVATT_REQ_BODY] THEN
  MESON_TAC[]);;

let EBVATT_CDOM_BODY = prove
 (`!D (E:A->A->bool) v iw isIN isEQ ileq iB cc.
      model D E ZF_AX /\ valuation D v /\ cc IN D
      ==> (holds D E
           (((((MAX iw (MAX isIN (MAX isEQ (MAX ileq iB)))) + 1)) |-> cc) v)
           (cross_form iw iw ((MAX iw (MAX isIN (MAX isEQ (MAX ileq iB)))) + 1)
            && domain_form isIN
            ((MAX iw (MAX isIN (MAX isEQ (MAX ileq iB)))) + 1) &&
            domain_form isEQ
            ((MAX iw (MAX isIN (MAX isEQ (MAX ileq iB)))) + 1))
           <=> ecross D E (v iw) (v iw) cc /\ edomain D E (v isIN) cc /\
               edomain D E (v isEQ) cc)`,
  REPEAT STRIP_TAC THEN
  ABBREV_TAC `M = (MAX iw (MAX isIN (MAX isEQ (MAX ileq iB))))` THEN
  SUBGOAL_THEN `~(iw = M + 1) /\ ~(isIN = M + 1) /\ ~(isEQ = M + 1)`
  STRIP_ASSUME_TAC THENL [EXPAND_TAC "M" THEN ARITH_TAC; ALL_TAC] THEN
  SUBGOAL_THEN `valuation D (((M + 1) |-> (cc:A)) v)` ASSUME_TAC THENL
   [ASM_SIMP_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
  REWRITE_TAC[HOLDS_AND] THEN
  ASM_SIMP_TAC[HOLDS_CROSS_FORM; HOLDS_DOMAIN_FORM] THEN
  ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER]);;

let EBVATT_CDOM = prove
 (`!D (E:A->A->bool) v iw isIN isEQ ileq iB.
      model D E ZF_AX /\ valuation D v
      ==> (holds D E v
             (?? ((MAX iw (MAX isIN (MAX isEQ (MAX ileq iB)))) + 1)
              (cross_form iw iw
               ((MAX iw (MAX isIN (MAX isEQ (MAX ileq iB)))) + 1) &&
               domain_form isIN
               ((MAX iw (MAX isIN (MAX isEQ (MAX ileq iB)))) + 1)
               && domain_form isEQ
                 ((MAX iw (MAX isIN (MAX isEQ (MAX ileq iB)))) + 1)))
           <=> (?c. ecross D E (v iw) (v iw) c /\
                    edomain D E (v isIN) c /\ edomain D E (v isEQ) c))`,
  REPEAT STRIP_TAC THEN
  REWRITE_TAC[HOLDS_EX] THEN
  EQ_TAC THENL
   [DISCH_THEN(X_CHOOSE_THEN `cc:A`
               (CONJUNCTS_THEN2 ASSUME_TAC ASSUME_TAC)) THEN
    EXISTS_TAC `cc:A` THEN
    MP_TAC(ISPECL
           [`D:A->bool`; `E:A->A->bool`; `v:num->A`; `iw:num`; `isIN:num`;
            `isEQ:num`; `ileq:num`; `iB:num`; `cc:A`] EBVATT_CDOM_BODY) THEN
    ASM_REWRITE_TAC[];
    DISCH_THEN(X_CHOOSE_THEN `cc:A` STRIP_ASSUME_TAC) THEN
    SUBGOAL_THEN `(cc:A) IN D` ASSUME_TAC THENL
     [FIRST_ASSUM(ACCEPT_TAC o CONJUNCT1 o REWRITE_RULE[ecross]); ALL_TAC] THEN
    EXISTS_TAC `cc:A` THEN ASM_REWRITE_TAC[] THEN
    MP_TAC(ISPECL
           [`D:A->bool`; `E:A->A->bool`; `v:num->A`; `iw:num`; `isIN:num`;
            `isEQ:num`; `ileq:num`; `iB:num`; `cc:A`] EBVATT_CDOM_BODY) THEN
    ASM_REWRITE_TAC[]]);;

let HOLDS_EBVATT_FORM = prove
 (`!D (E:A->A->bool) v iw isIN isEQ ileq iB.
      model D E ZF_AX /\ valuation D v
      ==> (holds D E v (ebvatt_form iw isIN isEQ ileq iB) <=>
           ebvatt D E (v iB) (v ileq) (v iw) (v isIN) (v isEQ))`,
  REPEAT STRIP_TAC THEN
  REWRITE_TAC[ebvatt_form; HOLDS_AND] THEN
  ASM_SIMP_TAC[HOLDS_EISFUN_FORM; EBVATT_CDOM; EBVATT_RIN; EBVATT_REQ] THEN
  REWRITE_TAC[ebvatt]);;

(* ===================================================================== *)
(* F4: ebv_in_form / ebv_eq_form -- the GLOBAL atomic                       *)
(* Boolean value [[u in v]] / [[u = v]] as an OBJECT formula.  Composes     *)
(* ordinal_form + rec_form bname_step_form (ebnstage, via HOLDS_REC_FORM    *)
(* with base valuation + EBNSTAGE_EREC) + %% + ebvatt_form + opair_form +   *)
(* apply_form.  B fixed at slot 2; fresh sIN=M+1,sEQ=M+2,pr=M+3,a=M+4,w=M+5 *)
(* (a,w bound INNERMOST so rec_form's ordinal/output top the stack).        *)
(* EBV_IN/EQ_INNER = per-in-D body; HOLDS_EBV_IN/EQ_FORM = the bridge        *)
(* (EQ_TAC + X_CHOOSE 5 exists; backward sIN/sEQ IN D via EBVATT_ISFUN_IN,   *)
(* pr IN D via EOPAIR_IN).  These are the atomic cases for INC4 bval.        *)
(* ===================================================================== *)

let ebv_in_form = new_definition
 `ebv_in_form iz iu iv ileq =
    ?? ((MAX iz (MAX iu (MAX iv (MAX ileq 2)))) + 1)
      (?? ((MAX iz (MAX iu (MAX iv (MAX ileq 2)))) + 2)
       (?? ((MAX iz (MAX iu (MAX iv (MAX ileq 2)))) + 3)
        (?? ((MAX iz (MAX iu (MAX iv (MAX ileq 2)))) + 4)
         (?? ((MAX iz (MAX iu (MAX iv (MAX ileq 2)))) + 5) (
    ordinal_form ((MAX iz (MAX iu (MAX iv (MAX ileq 2)))) + 4)
    && rec_form bname_step_form ((MAX iz (MAX iu (MAX iv (MAX ileq 2)))) + 4)
    && (iu %% ((MAX iz (MAX iu (MAX iv (MAX ileq 2)))) + 5)) &&
      (iv %% ((MAX iz (MAX iu (MAX iv (MAX ileq 2)))) + 5))
    && ebvatt_form ((MAX iz (MAX iu (MAX iv (MAX ileq 2)))) + 5)
      ((MAX iz (MAX iu (MAX iv (MAX ileq 2)))) + 1)
      ((MAX iz (MAX iu (MAX iv (MAX ileq 2)))) + 2) ileq 2
    && opair_form iu iv ((MAX iz (MAX iu (MAX iv (MAX ileq 2)))) + 3)
    && apply_form ((MAX iz (MAX iu (MAX iv (MAX ileq 2)))) + 1)
      ((MAX iz (MAX iu (MAX iv (MAX ileq 2)))) + 3) iz)))))`;;

let ebv_eq_form = new_definition
 `ebv_eq_form iz iu iv ileq =
    ?? ((MAX iz (MAX iu (MAX iv (MAX ileq 2)))) + 1)
      (?? ((MAX iz (MAX iu (MAX iv (MAX ileq 2)))) + 2)
       (?? ((MAX iz (MAX iu (MAX iv (MAX ileq 2)))) + 3)
        (?? ((MAX iz (MAX iu (MAX iv (MAX ileq 2)))) + 4)
         (?? ((MAX iz (MAX iu (MAX iv (MAX ileq 2)))) + 5) (
    ordinal_form ((MAX iz (MAX iu (MAX iv (MAX ileq 2)))) + 4)
    && rec_form bname_step_form ((MAX iz (MAX iu (MAX iv (MAX ileq 2)))) + 4)
    && (iu %% ((MAX iz (MAX iu (MAX iv (MAX ileq 2)))) + 5)) &&
      (iv %% ((MAX iz (MAX iu (MAX iv (MAX ileq 2)))) + 5))
    && ebvatt_form ((MAX iz (MAX iu (MAX iv (MAX ileq 2)))) + 5)
      ((MAX iz (MAX iu (MAX iv (MAX ileq 2)))) + 1)
      ((MAX iz (MAX iu (MAX iv (MAX ileq 2)))) + 2) ileq 2
    && opair_form iu iv ((MAX iz (MAX iu (MAX iv (MAX ileq 2)))) + 3)
    && apply_form ((MAX iz (MAX iu (MAX iv (MAX ileq 2)))) + 2)
      ((MAX iz (MAX iu (MAX iv (MAX ileq 2)))) + 3) iz)))))`;;

let EBVATT_ISFUN_IN = prove
 (`!D (E:A->A->bool) B leq w sIN sEQ.
      ebvatt D E B leq w sIN sEQ ==> sIN IN D /\ sEQ IN D`,
  REWRITE_TAC[ebvatt; eisfun] THEN MESON_TAC[]);;

let EBV_IN_INNER = prove
 (`!D (E:A->A->bool) v iz iu iv ileq sIN sEQ pr a w.
      model D E ZF_AX /\ valuation D v /\
      sIN IN D /\ sEQ IN D /\ pr IN D /\ a IN D /\ w IN D
      ==> (holds D E
           ((((((MAX iz (MAX iu (MAX iv (MAX ileq 2))))) + 5)) |-> w)
            ((((((MAX iz (MAX iu (MAX iv (MAX ileq 2))))) + 4)) |-> a)
             ((((((MAX iz (MAX iu (MAX iv (MAX ileq 2))))) + 3)) |-> pr)
              ((((((MAX iz (MAX iu (MAX iv (MAX ileq 2))))) + 2)) |-> sEQ)
               ((((((MAX iz (MAX iu (MAX iv (MAX ileq 2))))) + 1)) |->
                 (sIN:A)) v)))))
           (ordinal_form ((((MAX iz (MAX iu (MAX iv (MAX ileq 2))))) + 4))
    && rec_form bname_step_form
      ((((MAX iz (MAX iu (MAX iv (MAX ileq 2))))) + 4))
    && (iu %% ((((MAX iz (MAX iu (MAX iv (MAX ileq 2))))) + 5))) &&
      (iv %% ((((MAX iz (MAX iu (MAX iv (MAX ileq 2))))) + 5)))
    && ebvatt_form ((((MAX iz (MAX iu (MAX iv (MAX ileq 2))))) + 5))
      ((((MAX iz (MAX iu (MAX iv (MAX ileq 2))))) + 1))
      ((((MAX iz (MAX iu (MAX iv (MAX ileq 2))))) + 2)) ileq 2
    && opair_form iu iv ((((MAX iz (MAX iu (MAX iv (MAX ileq 2))))) + 3))
    && apply_form ((((MAX iz (MAX iu (MAX iv (MAX ileq 2))))) + 1))
      ((((MAX iz (MAX iu (MAX iv (MAX ileq 2))))) + 3)) iz)
           <=> (eordinal D E a /\ ebnstage D E (v 2) a w /\
                E (v iu) w /\ E (v iv) w /\
                ebvatt D E (v 2) (v ileq) w sIN sEQ /\
                eopair D E (v iu) (v iv) pr /\ eapply D E sIN pr (v iz)))`,
  REPEAT STRIP_TAC THEN
  ABBREV_TAC `M = (MAX iz (MAX iu (MAX iv (MAX ileq 2))))` THEN
  SUBGOAL_THEN `~((iu) = (M + 1)) /\
    ~((iu) = (M + 2)) /\
    ~((iu) = (M + 3)) /\
    ~((iu) = (M + 4)) /\
    ~((iu) = (M + 5)) /\
    ~((iv) = (M + 1)) /\
    ~((iv) = (M + 2)) /\
    ~((iv) = (M + 3)) /\
    ~((iv) = (M + 4)) /\
    ~((iv) = (M + 5)) /\
    ~((iz) = (M + 1)) /\
    ~((iz) = (M + 2)) /\
    ~((iz) = (M + 3)) /\
    ~((iz) = (M + 4)) /\
    ~((iz) = (M + 5)) /\
    ~((ileq) = (M + 1)) /\
    ~((ileq) = (M + 2)) /\
    ~((ileq) = (M + 3)) /\
    ~((ileq) = (M + 4)) /\
    ~((ileq) = (M + 5)) /\
    ~((2) = (M + 1)) /\
    ~((2) = (M + 2)) /\
    ~((2) = (M + 3)) /\
    ~((2) = (M + 4)) /\
    ~((2) = (M + 5)) /\
    ~((M + 1) = (M + 2)) /\
    ~((M + 1) = (M + 3)) /\
    ~((M + 1) = (M + 4)) /\
    ~((M + 1) = (M + 5)) /\
    ~((M + 2) = (M + 1)) /\
    ~((M + 2) = (M + 3)) /\
    ~((M + 2) = (M + 4)) /\
    ~((M + 2) = (M + 5)) /\
    ~((M + 3) = (M + 1)) /\
    ~((M + 3) = (M + 2)) /\
    ~((M + 3) = (M + 4)) /\
    ~((M + 3) = (M + 5)) /\
    ~((M + 4) = (M + 1)) /\
    ~((M + 4) = (M + 2)) /\
    ~((M + 4) = (M + 3)) /\
    ~((M + 4) = (M + 5))` STRIP_ASSUME_TAC THENL
  [EXPAND_TAC "M" THEN ARITH_TAC; ALL_TAC] THEN
  SUBGOAL_THEN
    `valuation D
     (((((M) + 3)) |-> pr)
      (((((M) + 2)) |-> sEQ) (((((M) + 1)) |-> (sIN:A)) v)))` ASSUME_TAC THENL
   [REPEAT(MATCH_MP_TAC VALUATION_VALMOD THEN CONJ_TAC THENL
      [ALL_TAC; FIRST_ASSUM ACCEPT_TAC]) THEN FIRST_ASSUM ACCEPT_TAC;
     ALL_TAC] THEN
  SUBGOAL_THEN
    `valuation D
     (((((M) + 5)) |-> w)
      (((((M) + 4)) |-> a)
       (((((M) + 3)) |-> pr)
        (((((M) + 2)) |-> sEQ) (((((M) + 1)) |-> (sIN:A)) v)))))`
    ASSUME_TAC THENL
   [REPEAT(MATCH_MP_TAC VALUATION_VALMOD THEN CONJ_TAC THENL
      [ALL_TAC; FIRST_ASSUM ACCEPT_TAC]) THEN FIRST_ASSUM ACCEPT_TAC;
     ALL_TAC] THEN
  REWRITE_TAC[HOLDS_AND] THEN
  SUBGOAL_THEN
   `holds D E
    (((((M) + 5)) |-> w)
     (((((M) + 4)) |-> a)
      (((((M) + 3)) |-> pr)
       (((((M) + 2)) |-> sEQ) (((((M) + 1)) |-> (sIN:A)) v)))))
    (rec_form bname_step_form (M + 4)) <=>
    ebnstage D E (v 2) a w`
  SUBST1_TAC THENL
   [MP_TAC(ISPECL
           [`D:A->bool`; `E:A->A->bool`;
            `((((M) + 3)) |-> pr)
             (((((M) + 2)) |-> sEQ) (((((M) + 1)) |-> (sIN:A)) v))`;
            `bname_step_form`; `M + 4`; `a:A`; `w:A`] HOLDS_REC_FORM) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
       [ARITH_TAC;
        GEN_TAC THEN DISCH_TAC THEN
        FIRST_ASSUM(MP_TAC o MATCH_MP FVLT_BNAME_STEP_FORM) THEN ARITH_TAC];
      ALL_TAC] THEN
    REWRITE_TAC[ARITH_RULE `(M + 4) + 1 = M + 5`] THEN
    DISCH_THEN SUBST1_TAC THEN
    CONV_TAC SYM_CONV THEN MATCH_MP_TAC EBNSTAGE_EREC THEN
    ASM_REWRITE_TAC[] THEN ASM_SIMP_TAC[VALMOD_OTHER];
    ALL_TAC] THEN
  ASM_SIMP_TAC[HOLDS_ORDINAL_FORM; HOLDS_MEM; HOLDS_EBVATT_FORM;
    HOLDS_OPAIR_FORM; HOLDS_APPLY_FORM] THEN
  ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER]);;

let HOLDS_EBV_IN_FORM = prove
 (`!D (E:A->A->bool) v iz iu iv ileq.
      model D E ZF_AX /\ valuation D v
      ==> (holds D E v (ebv_in_form iz iu iv ileq) <=>
           ebv_in D E (v 2) (v ileq) (v iu) (v iv) (v iz))`,
  REPEAT STRIP_TAC THEN
  REWRITE_TAC[ebv_in_form; HOLDS_EX] THEN
  REWRITE_TAC[ebv_in] THEN
  EQ_TAC THENL
   [INTRO_TAC "@sIN. aD @sEQ. sEQD @pr. prD @a. aD2 @w. wD h" THEN
    MAP_EVERY EXISTS_TAC [`a:A`; `w:A`; `sIN:A`; `sEQ:A`; `pr:A`] THEN
    MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `v:num->A`; `iz:num`; `iu:num`;
      `iv:num`; `ileq:num`; `sIN:A`; `sEQ:A`; `pr:A`; `a:A`; `w:A`]
      EBV_IN_INNER) THEN
    ASM_REWRITE_TAC[];
    DISCH_THEN(X_CHOOSE_THEN `a:A` (X_CHOOSE_THEN `w:A` (X_CHOOSE_THEN `sIN:A`
     (X_CHOOSE_THEN `sEQ:A` (X_CHOOSE_THEN `pr:A` STRIP_ASSUME_TAC))))) THEN
    SUBGOAL_THEN `(sIN:A) IN D /\ (sEQ:A) IN D` STRIP_ASSUME_TAC THENL
     [FIRST_ASSUM(ACCEPT_TAC o MATCH_MP EBVATT_ISFUN_IN); ALL_TAC] THEN
    SUBGOAL_THEN `(pr:A) IN D` ASSUME_TAC THENL
     [FIRST_ASSUM(ACCEPT_TAC o MATCH_MP EOPAIR_IN); ALL_TAC] THEN
    EXISTS_TAC `sIN:A` THEN ASM_REWRITE_TAC[] THEN
    EXISTS_TAC `sEQ:A` THEN ASM_REWRITE_TAC[] THEN
    EXISTS_TAC `pr:A` THEN ASM_REWRITE_TAC[] THEN
    EXISTS_TAC `a:A` THEN ASM_REWRITE_TAC[] THEN
    EXISTS_TAC `w:A` THEN ASM_REWRITE_TAC[] THEN
    MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `v:num->A`; `iz:num`; `iu:num`;
      `iv:num`; `ileq:num`; `sIN:A`; `sEQ:A`; `pr:A`; `a:A`; `w:A`]
      EBV_IN_INNER) THEN
    ASM_REWRITE_TAC[]]);;

