let HOLDS_EBV_EQ_FORM = prove
 (`!D (E:A->A->bool) v iz iu iv ileq.
      model D E ZF_AX /\ valuation D v
      ==> (holds D E v (ebv_eq_form iz iu iv ileq) <=>
           ebv_eq D E (v 2) (v ileq) (v iu) (v iv) (v iz))`,
  REPEAT STRIP_TAC THEN
  REWRITE_TAC[ebv_eq_form; HOLDS_EX] THEN
  REWRITE_TAC[ebv_eq] THEN
  EQ_TAC THENL
   [INTRO_TAC "@sIN. aD @sEQ. sEQD @pr. prD @a. aD2 @w. wD h" THEN
    MAP_EVERY EXISTS_TAC [`a:A`; `w:A`; `sIN:A`; `sEQ:A`; `pr:A`] THEN
    MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `v:num->A`; `iz:num`; `iu:num`;
      `iv:num`; `ileq:num`; `sIN:A`; `sEQ:A`; `pr:A`; `a:A`; `w:A`]
      EBV_EQ_INNER) THEN
    ASM_REWRITE_TAC[];
    DISCH_THEN(X_CHOOSE_THEN `a:A` (X_CHOOSE_THEN `w:A` (X_CHOOSE_THEN `sIN:A`
     (X_CHOOSE_THEN `sEQ:A` (X_CHOOSE_THEN `pr:A` STRIP_ASSUME_TAC))))) THEN
    SUBGOAL_THEN `(sIN:A) IN D /\ (sEQ:A) IN D` STRIP_ASSUME_TAC THENL
     [FIRST_ASSUM(ACCEPT_TAC o MATCH_MP EBVATT_ISFUN_IN); ALL_TAC] THEN
    SUBGOAL_THEN `(pr:A) IN D` ASSUME_TAC THENL
     [FIRST_ASSUM(ACCEPT_TAC o MATCH_MP EOPAIR_IN); ALL_TAC] THEN
    EXISTS_TAC `sIN:A` THEN ASM_REWRITE_TAC[] THEN
    EXISTS_TAC `sEQ:A` THEN ASM_REWRITE_TAC[] THEN
    EXISTS_TAC `pr:A` THEN ASM_REWRITE_TAC[] THEN
    EXISTS_TAC `a:A` THEN ASM_REWRITE_TAC[] THEN
    EXISTS_TAC `w:A` THEN ASM_REWRITE_TAC[] THEN
    MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `v:num->A`; `iz:num`; `iu:num`;
      `iv:num`; `ileq:num`; `sIN:A`; `sEQ:A`; `pr:A`; `a:A`; `w:A`]
      EBV_EQ_INNER) THEN
    ASM_REWRITE_TAC[]]);;

(* ------------------------------------------------------------------ *)
(* F4: the Boolean value [[p]]_v of a meta-formula p (a value in       *)
(* the complete Boolean algebra B), by recursion on the HOL form type  *)
(* -- the twin of `holds`.  False |-> bottom; atomics |-> ebv_in/eq;   *)
(* --> |-> ebimp; !! n p |-> glb over {[[p]]_{(n|->a)v} : a a bname}.   *)
(* The !!-value-set is stated via an existential inner set S (its      *)
(* existence as an M-set is discharged later via separation on B).     *)
(* ------------------------------------------------------------------ *)

let bval = new_recursive_definition form_RECURSION
 `(bval D (E:A->A->bool) B leq v False z <=> ebot D E B leq z) /\
  (bval D E B leq v (i %% j) z <=> ebv_in D E B leq (v i) (v j) z) /\
  (bval D E B leq v (Eq i j) z <=> ebv_eq D E B leq (v i) (v j) z) /\
  (bval D E B leq v (p --> q) z <=>
       ?zp zq. zp IN D /\ zq IN D /\
               bval D E B leq v p zp /\ bval D E B leq v q zq /\
               ebimp D E B leq zp zq z) /\
  (bval D E B leq v (!! n p) z <=>
       ?S. S IN D /\
           (!zz. zz IN D
                 ==> (E zz S <=>
                      ?a. a IN D /\ bname D E B a /\
                          bval D E B leq ((n |-> a) v) p zz)) /\
           eglb D E B leq S z)`;;

(* lower bounds (hence glbs) of a set live in the algebra carrier p    *)
let EGLB_MEM_ALG = prove
 (`!D (E:A->A->bool) p leq s u. eglb D E p leq s u ==> E u p`,
  REPEAT GEN_TAC THEN REWRITE_TAC[eglb; elbound] THEN STRIP_TAC THEN
  ASM_REWRITE_TAC[]);;

(* every Boolean value lies in B (given z IN D; ebv_in/eq are not      *)
(* single-valued off D, so z IN D is a genuine hypothesis)             *)
let BVAL_IN_B = prove
 (`!p D (E:A->A->bool) B leq v z.
      model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
      valuation D v /\ z IN D /\ bval D E B leq v p z ==> E z B`,
  MATCH_MP_TAC form_INDUCT THEN REPEAT CONJ_TAC THENL
   [REPEAT GEN_TAC THEN REWRITE_TAC[bval; ebot] THEN STRIP_TAC THEN
    ASM_REWRITE_TAC[];
    MAP_EVERY X_GEN_TAC [`i:num`; `j:num`] THEN REPEAT GEN_TAC THEN
    REWRITE_TAC[bval] THEN STRIP_TAC THEN
    SUBGOAL_THEN `!x. (v:num->A) x IN D` ASSUME_TAC THENL
     [ASM_MESON_TAC[valuation]; ALL_TAC] THEN
    MATCH_MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `B:A`; `leq:A`;
      `(v:num->A) i`; `(v:num->A) j`; `z:A`] EBV_IN_IN_B) THEN
    ASM_REWRITE_TAC[];
    MAP_EVERY X_GEN_TAC [`i:num`; `j:num`] THEN REPEAT GEN_TAC THEN
    REWRITE_TAC[bval] THEN STRIP_TAC THEN
    SUBGOAL_THEN `!x. (v:num->A) x IN D` ASSUME_TAC THENL
     [ASM_MESON_TAC[valuation]; ALL_TAC] THEN
    MATCH_MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `B:A`; `leq:A`;
      `(v:num->A) i`; `(v:num->A) j`; `z:A`] EBV_EQ_IN_B) THEN
    ASM_REWRITE_TAC[];
    REPEAT GEN_TAC THEN DISCH_TAC THEN REPEAT GEN_TAC THEN
    REWRITE_TAC[bval] THEN STRIP_TAC THEN
    FIRST_ASSUM(ACCEPT_TAC o CONJUNCT2 o MATCH_MP EBIMP_IN);
    REPEAT GEN_TAC THEN DISCH_TAC THEN REPEAT GEN_TAC THEN
    REWRITE_TAC[bval] THEN STRIP_TAC THEN
    FIRST_ASSUM(ACCEPT_TAC o MATCH_MP EGLB_MEM_ALG)]);;

(* value depends only on the valuation at the free variables of p        *)
let BVAL_FV = prove
 (`!p D (E:A->A->bool) B leq v w z.
      (!i. i IN FV p ==> v i = w i)
      ==> (bval D E B leq v p z <=> bval D E B leq w p z)`,
  MATCH_MP_TAC form_INDUCT THEN REPEAT CONJ_TAC THENL
   [REWRITE_TAC[bval];
    MAP_EVERY X_GEN_TAC [`i:num`; `j:num`] THEN REPEAT GEN_TAC THEN
    REWRITE_TAC[FV; IN_INSERT; NOT_IN_EMPTY] THEN DISCH_TAC THEN
    REWRITE_TAC[bval] THEN
    SUBGOAL_THEN `(v:num->A) i = w i /\ (v:num->A) j = w j`
      (fun th -> REWRITE_TAC[th]) THEN ASM_MESON_TAC[];
    MAP_EVERY X_GEN_TAC [`i:num`; `j:num`] THEN REPEAT GEN_TAC THEN
    REWRITE_TAC[FV; IN_INSERT; NOT_IN_EMPTY] THEN DISCH_TAC THEN
    REWRITE_TAC[bval] THEN
    SUBGOAL_THEN `(v:num->A) i = w i /\ (v:num->A) j = w j`
      (fun th -> REWRITE_TAC[th]) THEN ASM_MESON_TAC[];
    MAP_EVERY X_GEN_TAC [`p:form`; `q:form`] THEN
    DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC ASSUME_TAC) THEN
    REPEAT GEN_TAC THEN REWRITE_TAC[FV; IN_UNION] THEN DISCH_TAC THEN
    SUBGOAL_THEN
      `!z. bval D (E:A->A->bool) B leq v p z <=> bval D E B leq w p z`
      ASSUME_TAC THENL
     [GEN_TAC THEN FIRST_ASSUM MATCH_MP_TAC THEN ASM_MESON_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN
      `!z. bval D (E:A->A->bool) B leq v q z <=> bval D E B leq w q z`
      ASSUME_TAC THENL
     [GEN_TAC THEN FIRST_ASSUM MATCH_MP_TAC THEN ASM_MESON_TAC[]; ALL_TAC] THEN
    REWRITE_TAC[bval] THEN ASM_REWRITE_TAC[];
    MAP_EVERY X_GEN_TAC [`m:num`; `p:form`] THEN DISCH_TAC THEN
    REPEAT GEN_TAC THEN REWRITE_TAC[FV; IN_DELETE] THEN DISCH_TAC THEN
    SUBGOAL_THEN
     `!a zz. bval D (E:A->A->bool) B leq ((m |-> a) v) p zz <=>
             bval D E B leq ((m |-> a) w) p zz` ASSUME_TAC THENL
     [REPEAT GEN_TAC THEN FIRST_ASSUM MATCH_MP_TAC THEN
      X_GEN_TAC `k:num` THEN DISCH_TAC THEN
      ASM_CASES_TAC `k:num = m` THEN
      ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER] THEN ASM_MESON_TAC[];
      ALL_TAC] THEN
    REWRITE_TAC[bval] THEN ASM_REWRITE_TAC[]]);;

(* ------------------------------------------------------------------ *)
(* BVAL_DEFINABLE: the Boolean value [[p]]_v of a meta-formula p is     *)
(* uniformly definable by an object formula f, reading p's variable i  *)
(* from the SHIFTED slot 32+i (so B@2 and the bname internals @30,31    *)
(* stay clear of p's variables).  This is the object formula whose      *)
(* satisfaction the !!-value-set separation (BVAL_TOTAL) will use.      *)
(* The congruence helpers FORALL_IMP_CONG / EXISTS_AND_CONG avoid MESON *)
(* blow-up on the large holds-terms in the !! case.                     *)
(* ------------------------------------------------------------------ *)

let BVAL_DEFINABLE = prove
 (`!p r ileq. ?f. !D (E:A->A->bool) v.
      model D E ZF_AX /\ valuation D v /\ ileq < 32
      ==> (holds D E v f <=>
           bval D E (v 2) (v ileq) (\i. v (32 + i)) p (v r))`,
  MATCH_MP_TAC form_INDUCT THEN REPEAT CONJ_TAC THENL
   [MAP_EVERY X_GEN_TAC [`r:num`; `ileq:num`] THEN
    EXISTS_TAC `bbot_form ileq 2 r` THEN REPEAT STRIP_TAC THEN
    ASM_SIMP_TAC[HOLDS_BBOT_FORM] THEN REWRITE_TAC[bval];
    MAP_EVERY X_GEN_TAC [`i:num`; `j:num`; `r:num`; `ileq:num`] THEN
    EXISTS_TAC `ebv_in_form r (32 + i) (32 + j) ileq` THEN
    REPEAT STRIP_TAC THEN
    ASM_SIMP_TAC[HOLDS_EBV_IN_FORM] THEN REWRITE_TAC[bval];
    MAP_EVERY X_GEN_TAC [`i:num`; `j:num`; `r:num`; `ileq:num`] THEN
    EXISTS_TAC `ebv_eq_form r (32 + i) (32 + j) ileq` THEN
    REPEAT STRIP_TAC THEN
    ASM_SIMP_TAC[HOLDS_EBV_EQ_FORM] THEN REWRITE_TAC[bval];
    (* --> *)
    MAP_EVERY X_GEN_TAC [`p:form`; `q:form`] THEN
    DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "ihp") (LABEL_TAC "ihq")) THEN
    MAP_EVERY X_GEN_TAC [`r:num`; `ileq:num`] THEN
    ABBREV_TAC
      `S0 = {2, r, ileq} UNION IMAGE (\k. 32 + k) (FV p UNION FV q)` THEN
      SUBGOAL_THEN `FINITE (S0:num->bool)` ASSUME_TAC THENL
     [EXPAND_TAC "S0" THEN
      SIMP_TAC[FINITE_UNION; FINITE_INSERT; FINITE_EMPTY; FINITE_IMAGE;
               FV_FINITE]; ALL_TAC] THEN
    SUBGOAL_THEN `?op. ~(op IN (S0:num->bool))` (X_CHOOSE_TAC `op:num`) THENL
     [MATCH_MP_TAC num_FINITE_AVOID THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN `?oq. ~(oq IN (op:num) INSERT S0)`
      (X_CHOOSE_TAC `oq:num`) THENL
      [MATCH_MP_TAC num_FINITE_AVOID THEN ASM_SIMP_TAC[FINITE_INSERT];
      ALL_TAC] THEN
    SUBGOAL_THEN
     `~(op = 2) /\ ~(op = r) /\ ~(op = ileq) /\
      ~(oq = 2) /\ ~(oq = r) /\ ~(oq = ileq) /\ ~(op = oq) /\
      (!i. i IN FV p \/ i IN FV q ==> ~(op = 32 + i) /\ ~(oq = 32 + i))`
    STRIP_ASSUME_TAC THENL
     [UNDISCH_TAC `~((op:num) IN S0)` THEN
      UNDISCH_TAC `~((oq:num) IN (op:num) INSERT S0)` THEN
      EXPAND_TAC "S0" THEN
      REWRITE_TAC[IN_UNION; IN_INSERT; NOT_IN_EMPTY; IN_IMAGE] THEN
      MESON_TAC[];
      ALL_TAC] THEN
    USE_THEN "ihp" (X_CHOOSE_THEN `fp:form` (LABEL_TAC "fpb") o
      SPECL [`op:num`; `ileq:num`]) THEN
    USE_THEN "ihq" (X_CHOOSE_THEN `fq:form` (LABEL_TAC "fqb") o
      SPECL [`oq:num`; `ileq:num`]) THEN
    EXISTS_TAC `?? op (?? oq (fp && fq && bimp_form ileq 2 op oq r))` THEN
    REPEAT GEN_TAC THEN STRIP_TAC THEN
    SUBGOAL_THEN
     `!a b:A. a IN D /\ b IN D
        ==> (holds D E ((oq |-> (b:A)) ((op |-> (a:A)) (v:num->A))) fp <=>
             bval D E (v 2) (v ileq) (\i. v (32 + i)) p a) /\
            (holds D E ((oq |-> (b:A)) ((op |-> (a:A)) (v:num->A))) fq <=>
             bval D E (v 2) (v ileq) (\i. v (32 + i)) q b) /\
            (holds D E ((oq |-> (b:A)) ((op |-> (a:A)) (v:num->A)))
                (bimp_form ileq 2 op oq r) <=>
             ebimp D E (v 2) (v ileq) a b (v r))`
    (LABEL_TAC "step") THENL
     [MAP_EVERY X_GEN_TAC [`a:A`; `b:A`] THEN STRIP_TAC THEN
      SUBGOAL_THEN
        `valuation D ((oq |-> (b:A)) ((op |-> (a:A)) (v:num->A)))`
          ASSUME_TAC THENL
          [ASM_SIMP_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
      REPEAT CONJ_TAC THENL
       [USE_THEN "fpb" (MP_TAC o SPECL
          [`D:A->bool`; `E:A->A->bool`;
           `(oq |-> (b:A)) ((op |-> (a:A)) (v:num->A))`]) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
        DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
        ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER] THEN
        MATCH_MP_TAC BVAL_FV THEN X_GEN_TAC `i:num` THEN DISCH_TAC THEN
        ASM_SIMP_TAC[VALMOD_OTHER];
        USE_THEN "fqb" (MP_TAC o SPECL
          [`D:A->bool`; `E:A->A->bool`;
           `(oq |-> (b:A)) ((op |-> (a:A)) (v:num->A))`]) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
        DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
        ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER] THEN
        MATCH_MP_TAC BVAL_FV THEN X_GEN_TAC `i:num` THEN DISCH_TAC THEN
        ASM_SIMP_TAC[VALMOD_OTHER];
        ASM_SIMP_TAC[HOLDS_BIMP_FORM] THEN
        ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER]];
      ALL_TAC] THEN
    REMOVE_THEN "fpb" (K ALL_TAC) THEN REMOVE_THEN "fqb" (K ALL_TAC) THEN
    REWRITE_TAC[HOLDS_EX; HOLDS_AND] THEN REWRITE_TAC[bval] THEN
    EQ_TAC THENL
     [DISCH_THEN(X_CHOOSE_THEN `a:A` (CONJUNCTS_THEN2 ASSUME_TAC
        (X_CHOOSE_THEN `b:A` (CONJUNCTS_THEN2 ASSUME_TAC MP_TAC)))) THEN
      USE_THEN "step" (fun sth -> ASM_SIMP_TAC[SPECL [`a:A`; `b:A`] sth]) THEN
      STRIP_TAC THEN MAP_EVERY EXISTS_TAC [`a:A`; `b:A`] THEN
      ASM_REWRITE_TAC[];
      DISCH_THEN(X_CHOOSE_THEN `zp:A`
                 (X_CHOOSE_THEN `zq:A` STRIP_ASSUME_TAC)) THEN
      EXISTS_TAC `zp:A` THEN ASM_REWRITE_TAC[] THEN
      EXISTS_TAC `zq:A` THEN ASM_REWRITE_TAC[] THEN
      USE_THEN "step" (fun sth -> ASM_SIMP_TAC[SPECL [`zp:A`; `zq:A`] sth])];
    (* !! m p *)
    MAP_EVERY X_GEN_TAC [`m:num`; `p:form`] THEN
    DISCH_THEN(LABEL_TAC "ihp") THEN
    MAP_EVERY X_GEN_TAC [`r:num`; `ileq:num`] THEN
    ABBREV_TAC
      `S1 = {2, r, ileq, 30, 31, 32 + m} UNION IMAGE (\k. 32 + k) (FV p)` THEN
    SUBGOAL_THEN `FINITE (S1:num->bool)` ASSUME_TAC THENL
     [EXPAND_TAC "S1" THEN
      SIMP_TAC[FINITE_UNION; FINITE_INSERT; FINITE_EMPTY; FINITE_IMAGE;
               FV_FINITE]; ALL_TAC] THEN
    SUBGOAL_THEN `?iS. ~(iS IN (S1:num->bool))` (X_CHOOSE_TAC `iS:num`) THENL
     [MATCH_MP_TAC num_FINITE_AVOID THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN `?izz. ~(izz IN (iS:num) INSERT S1)`
      (X_CHOOSE_TAC `izz:num`) THENL
     [MATCH_MP_TAC num_FINITE_AVOID THEN ASM_SIMP_TAC[FINITE_INSERT];
      ALL_TAC] THEN
    SUBGOAL_THEN
     `~(iS = 2) /\ ~(iS = r) /\ ~(iS = ileq) /\ ~(iS = 30) /\ ~(iS = 31) /\
      ~(iS = 32 + m) /\ ~(izz = 2) /\ ~(izz = r) /\ ~(izz = ileq) /\
      ~(izz = 30) /\ ~(izz = 31) /\ ~(izz = 32 + m) /\ ~(izz = iS) /\
      (!i. i IN FV p ==> ~(iS = 32 + i) /\ ~(izz = 32 + i))`
    STRIP_ASSUME_TAC THENL
     [UNDISCH_TAC `~((iS:num) IN S1)` THEN
      UNDISCH_TAC `~((izz:num) IN (iS:num) INSERT S1)` THEN
      EXPAND_TAC "S1" THEN
      REWRITE_TAC[IN_UNION; IN_INSERT; NOT_IN_EMPTY; IN_IMAGE] THEN
      MESON_TAC[];
      ALL_TAC] THEN
    USE_THEN "ihp" (X_CHOOSE_THEN `fp:form` (LABEL_TAC "fpb") o
      SPECL [`izz:num`; `ileq:num`]) THEN
    EXISTS_TAC
     `?? iS ((!! izz ((izz %% iS) <->
                      ?? (32 + m) (bname_form (32 + m) && fp))) &&
             eglb_form 2 ileq iS r)` THEN
    REPEAT GEN_TAC THEN STRIP_TAC THEN
    SUBGOAL_THEN `~(32 + m = 2) /\ ~(32 + m = ileq) /\
                  ~(2 = 32 + m) /\ ~(ileq = 32 + m)`
      STRIP_ASSUME_TAC THENL [ASM_ARITH_TAC; ALL_TAC] THEN
    SUBGOAL_THEN
     `!s zz a:A. s IN D /\ zz IN D /\ a IN D
        ==> (holds D E
             (((32 + m) |-> a) ((izz |-> zz) ((iS |-> s) (v:num->A))))
             (bname_form (32 + m) && fp) <=>
             bname D E (v 2) a /\
             bval D E (v 2) (v ileq) ((m |-> a) (\i. v (32 + i))) p zz)`
    (LABEL_TAC "gstep") THENL
     [MAP_EVERY X_GEN_TAC [`s:A`; `zz:A`; `a:A`] THEN STRIP_TAC THEN
      SUBGOAL_THEN
        `valuation D (((32 + m) |-> a) ((izz |-> zz) ((iS |-> s) (v:num->A))))`
        ASSUME_TAC THENL [ASM_SIMP_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
      SUBGOAL_THEN
        `holds D E (((32 + m) |-> a) ((izz |-> zz) ((iS |-> s) (v:num->A))))
           (bname_form (32 + m)) <=> bname D E (v 2) a`
        ASSUME_TAC THENL
       [ASM_SIMP_TAC[HOLDS_BNAME_FORM; ARITH_RULE
          `~(32 + m = 30) /\ ~(32 + m = 31)`] THEN
        ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER]; ALL_TAC] THEN
      SUBGOAL_THEN
        `holds D E
         (((32 + m) |-> a) ((izz |-> zz) ((iS |-> s) (v:num->A)))) fp <=>
         bval D E (v 2) (v ileq) ((m |-> a) (\i. v (32 + i))) p zz`
        ASSUME_TAC THENL
       [USE_THEN "fpb" (MP_TAC o SPECL
          [`D:A->bool`; `E:A->A->bool`;
           `((32 + m) |-> a) ((izz |-> zz) ((iS |-> s) (v:num->A)))`]) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
        DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
        ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER] THEN
        MATCH_MP_TAC BVAL_FV THEN X_GEN_TAC `i:num` THEN DISCH_TAC THEN
        ASM_CASES_TAC `i:num = m` THEN
        ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER;
                     ARITH_RULE `~(i = m) ==> ~(32 + i = 32 + m)`];
        ALL_TAC] THEN
      ASM_REWRITE_TAC[HOLDS_AND];
      ALL_TAC] THEN
    SUBGOAL_THEN
     `!s:A. s IN D
        ==> (holds D E ((iS |-> s) (v:num->A))
               (!! izz ((izz %% iS) <->
                        ?? (32 + m) (bname_form (32 + m) && fp))) <=>
             (!zz. zz IN D
                   ==> (E zz s <=>
                        ?a. a IN D /\ bname D E (v 2) a /\
                            bval D E (v 2) (v ileq)
                              ((m |-> a) (\i. v (32 + i)))
                                p zz))) /\
            (holds D E ((iS |-> s) v) (eglb_form 2 ileq iS r) <=>
             eglb D E (v 2) (v ileq) s (v r))`
    (LABEL_TAC "step") THENL
     [X_GEN_TAC `s:A` THEN DISCH_TAC THEN
      SUBGOAL_THEN `valuation D ((iS |-> s) (v:num->A))` ASSUME_TAC THENL
       [ASM_SIMP_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
      CONJ_TAC THENL
       [REWRITE_TAC[last(CONJUNCTS holds)] THEN
        MATCH_MP_TAC FORALL_IMP_CONG THEN X_GEN_TAC `zz:A` THEN DISCH_TAC THEN
        SUBGOAL_THEN `valuation D ((izz |-> zz) ((iS |-> s) (v:num->A)))`
          ASSUME_TAC THENL [ASM_SIMP_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
        REWRITE_TAC[HOLDS_IFF; HOLDS_MEM; HOLDS_EX] THEN
        ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER] THEN
        MATCH_MP_TAC(TAUT `(x <=> y) ==> ((p <=> x) <=> (p <=> y))`) THEN
        MATCH_MP_TAC EXISTS_AND_CONG THEN X_GEN_TAC `a:A` THEN DISCH_TAC THEN
        USE_THEN "gstep"
          (fun g -> ASM_SIMP_TAC[SPECL [`s:A`; `zz:A`; `a:A`] g]);
          ASM_SIMP_TAC[HOLDS_EGLB_FORM] THEN
        ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER]];
      ALL_TAC] THEN
    REMOVE_THEN "fpb" (K ALL_TAC) THEN REMOVE_THEN "gstep" (K ALL_TAC) THEN
    REWRITE_TAC[HOLDS_EX; HOLDS_AND] THEN REWRITE_TAC[bval] THEN
    EQ_TAC THENL
     [DISCH_THEN(X_CHOOSE_THEN `s:A` (CONJUNCTS_THEN2 ASSUME_TAC MP_TAC)) THEN
      USE_THEN "step" (fun sth -> ASM_SIMP_TAC[SPEC `s:A` sth]) THEN
      STRIP_TAC THEN EXISTS_TAC `s:A` THEN ASM_REWRITE_TAC[];
      DISCH_THEN(X_CHOOSE_THEN `sv:A` STRIP_ASSUME_TAC) THEN
      EXISTS_TAC `sv:A` THEN ASM_REWRITE_TAC[] THEN
      USE_THEN "step" (fun sth -> ASM_SIMP_TAC[SPEC `sv:A` sth])]]);;

(* ------------------------------------------------------------------ *)
(* BVAL_TOTAL: for a bname-valuation v, the Boolean value [[p]]_v EXISTS *)
(* in D (hence in B).  Induction on p: False from ebalg's bottom;        *)
(* atomics from EBV_TOTAL; --> from EBIMP_EXISTS on the IH values; !! by  *)
(* carving the value-set {z IN B : ?a. bname a /\ [[p]]_{(m|->a)v}=z} via *)
(* ZF_SEPARATION on B along ??(32+m)(bname_form(32+m) && f) where f is    *)
(* BVAL_DEFINABLE's object formula for p, then eglb via ECBA_INF.  The    *)
(* separation's redundant `E z B` conjunct is absorbed by BVAL_IN_B.      *)
(* ------------------------------------------------------------------ *)

let BVAL_TOTAL = prove
 (`!p D (E:A->A->bool) B leq v.
      model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
      valuation D v /\ (!i. bname D E B (v i))
      ==> ?z. z IN D /\ bval D E B leq v p z`,
  MATCH_MP_TAC form_INDUCT THEN REPEAT CONJ_TAC THENL
   [REPEAT GEN_TAC THEN STRIP_TAC THEN REWRITE_TAC[bval] THEN
  SUBGOAL_THEN `?zb:A. ebot D E B leq zb` STRIP_ASSUME_TAC THENL
   [FIRST_ASSUM(ACCEPT_TAC o CONJUNCT1 o CONJUNCT2 o REWRITE_RULE[ebalg] o
      CONJUNCT1 o REWRITE_RULE[ecba]); ALL_TAC] THEN
  EXISTS_TAC `zb:A` THEN ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[EBOT_IN];

MAP_EVERY X_GEN_TAC [`i:num`; `j:num`] THEN REPEAT GEN_TAC THEN STRIP_TAC THEN
  REWRITE_TAC[bval] THEN
  SUBGOAL_THEN `!x. (v:num->A) x IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[valuation]; ALL_TAC] THEN
  MP_TAC(ISPECL
         [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`(v:num->A) i`;
          `(v:num->A) j`]
         EBV_TOTAL) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `zi:A` STRIP_ASSUME_TAC o CONJUNCT1) THEN
  EXISTS_TAC `zi:A` THEN ASM_REWRITE_TAC[];

MAP_EVERY X_GEN_TAC [`i:num`; `j:num`] THEN REPEAT GEN_TAC THEN STRIP_TAC THEN
  REWRITE_TAC[bval] THEN
  SUBGOAL_THEN `!x. (v:num->A) x IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[valuation]; ALL_TAC] THEN
  MP_TAC(ISPECL
         [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`(v:num->A) i`;
          `(v:num->A) j`]
         EBV_TOTAL) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `ze:A` STRIP_ASSUME_TAC o CONJUNCT2) THEN
  EXISTS_TAC `ze:A` THEN ASM_REWRITE_TAC[];

MAP_EVERY X_GEN_TAC [`p:form`; `q:form`] THEN
  DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "ihp") (LABEL_TAC "ihq")) THEN
  REPEAT GEN_TAC THEN STRIP_TAC THEN REWRITE_TAC[bval] THEN
  SUBGOAL_THEN `ebalg D (E:A->A->bool) B leq` ASSUME_TAC THENL
   [FIRST_ASSUM(ACCEPT_TAC o CONJUNCT1 o REWRITE_RULE[ecba]); ALL_TAC] THEN
  USE_THEN "ihp"
    (MP_TAC o SPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`v:num->A`]) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `zp:A` STRIP_ASSUME_TAC) THEN
  USE_THEN "ihq"
    (MP_TAC o SPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`v:num->A`]) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `zq:A` STRIP_ASSUME_TAC) THEN
  SUBGOAL_THEN `E (zp:A) (B:A) /\ E (zq:A) (B:A)` STRIP_ASSUME_TAC THENL
   [CONJ_TAC THENL
     [MATCH_MP_TAC(ISPECL [`p:form`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
        `v:num->A`;`zp:A`] BVAL_IN_B);
      MATCH_MP_TAC(ISPECL [`q:form`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
        `v:num->A`;`zq:A`] BVAL_IN_B)] THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`zp:A`;`zq:A`]
         EBIMP_EXISTS) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `zr:A` ASSUME_TAC) THEN
  EXISTS_TAC `zr:A` THEN CONJ_TAC THENL
   [ASM_MESON_TAC[EBIMP_IN];
    MAP_EVERY EXISTS_TAC [`zp:A`; `zq:A`] THEN ASM_REWRITE_TAC[]];

MAP_EVERY X_GEN_TAC [`m:num`; `p:form`] THEN DISCH_TAC THEN
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `!x. (v:num->A) x IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[valuation]; ALL_TAC] THEN
  SUBGOAL_THEN `ebalg D (E:A->A->bool) B leq` ASSUME_TAC THENL
   [FIRST_ASSUM(ACCEPT_TAC o CONJUNCT1 o REWRITE_RULE[ecba]); ALL_TAC] THEN
  SUBGOAL_THEN
    `?izz. ~(izz IN ({2, 3, 30, 31, 32 + m} UNION IMAGE (\k. 32 + k) (FV p)))`
    (X_CHOOSE_TAC `izz:num`) THENL
   [MATCH_MP_TAC num_FINITE_AVOID THEN
    SIMP_TAC[FINITE_UNION; FINITE_INSERT; FINITE_EMPTY;
             FINITE_IMAGE; FV_FINITE];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `~(izz = 2) /\ ~(izz = 3) /\ ~(izz = 30) /\ ~(izz = 31) /\
    ~(izz = 32 + m) /\
    (!i. i IN FV p ==> ~(izz = 32 + i))`
   STRIP_ASSUME_TAC THENL
   [UNDISCH_TAC
     `~(izz IN ({2, 3, 30, 31, 32 + m} UNION IMAGE (\k. 32 + k) (FV p)))` THEN
    REWRITE_TAC[IN_UNION; IN_INSERT; NOT_IN_EMPTY; IN_IMAGE] THEN MESON_TAC[];
    ALL_TAC] THEN
  X_CHOOSE_TAC `fp:form`
    (ISPECL [`p:form`; `izz:num`; `3`] BVAL_DEFINABLE) THEN
    ABBREV_TAC `w0 = (2 |-> B) ((3 |-> leq) (\k. (v:num->A) (k - 32)))` THEN
  SUBGOAL_THEN
   `valuation D (w0:num->A) /\ w0 2 = B /\ w0 3 = leq /\
    (!i. w0 (32 + i) = (v:num->A) i)`
   STRIP_ASSUME_TAC THENL
   [EXPAND_TAC "w0" THEN REPEAT CONJ_TAC THENL
     [REPEAT(MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[]) THEN
      REWRITE_TAC[valuation] THEN ASM_REWRITE_TAC[];
      SIMP_TAC[VALMOD_BASIC];
      SIMP_TAC[VALMOD_OTHER; VALMOD_BASIC; ARITH_RULE `~(3 = 2)`];
      GEN_TAC THEN
      SIMP_TAC[VALMOD_OTHER; ARITH_RULE `~(32 + i = 2) /\ ~(32 + i = 3)`] THEN
      AP_TERM_TAC THEN ARITH_TAC];
    ALL_TAC] THEN
SUBGOAL_THEN
   `!zz. zz IN D
      ==> (holds D E ((izz |-> zz) (w0:num->A))
             (?? (32 + m) (bname_form (32 + m) && fp)) <=>
           (?a. a IN D /\ bname D E B a /\
                bval D E B leq ((m |-> a) v) p zz))`
   (LABEL_TAC "bridge") THENL
   [X_GEN_TAC `zz:A` THEN DISCH_TAC THEN
    SUBGOAL_THEN `valuation D ((izz |-> zz) (w0:num->A))` ASSUME_TAC THENL
     [ASM_SIMP_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
    REWRITE_TAC[HOLDS_EX] THEN
    MATCH_MP_TAC EXISTS_AND_CONG THEN X_GEN_TAC `a:A` THEN DISCH_TAC THEN
    SUBGOAL_THEN `valuation D (((32 + m) |-> a) ((izz |-> zz) (w0:num->A)))`
      ASSUME_TAC THENL [ASM_SIMP_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
    SUBGOAL_THEN
      `holds D E (((32 + m) |-> a) ((izz |-> zz) (w0:num->A)))
         (bname_form (32 + m)) <=> bname D E B a`
      ASSUME_TAC THENL
     [ASM_SIMP_TAC[HOLDS_BNAME_FORM; VALMOD_BASIC; VALMOD_OTHER;
        ARITH_RULE `~(32 + m = 30) /\ ~(32 + m = 31) /\ ~(2 = 32 + m)`];
      ALL_TAC] THEN
    SUBGOAL_THEN
      `holds D E (((32 + m) |-> a) ((izz |-> zz) (w0:num->A))) fp <=>
       bval D E B leq ((m |-> a) v) p zz`
      ASSUME_TAC THENL
     [FIRST_X_ASSUM(fun th -> MP_TAC(SPECL
        [`D:A->bool`; `E:A->A->bool`;
         `((32 + m) |-> a) ((izz |-> zz) (w0:num->A))`] th) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[] THEN ARITH_TAC; ALL_TAC]) THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
      ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER;
        ARITH_RULE `~(2 = 32 + m) /\ ~(3 = 32 + m)`] THEN
      MATCH_MP_TAC BVAL_FV THEN X_GEN_TAC `i:num` THEN DISCH_TAC THEN
      ASM_CASES_TAC `i:num = m` THEN
      ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER;
        ARITH_RULE `~(i = m) ==> ~(32 + i = 32 + m)`]; ALL_TAC] THEN
    REWRITE_TAC[HOLDS_AND] THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`] ZF_SEPARATION) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(MP_TAC o SPECL
    [`?? (32 + m) (bname_form (32 + m) && fp)`; `izz:num`; `w0:num->A`;
     `B:A`]) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `S:A` STRIP_ASSUME_TAC) THEN
  SUBGOAL_THEN
   `!zz. zz IN D
      ==> (E zz S <=> ?a. a IN D /\ bname D (E:A->A->bool) B a /\
                          bval D (E:A->A->bool) B leq ((m |-> (a:A)) v) p zz)`
   ASSUME_TAC THENL
   [X_GEN_TAC `zz:A` THEN DISCH_TAC THEN
    SUBGOAL_THEN
     `(?a. a IN D /\ bname D (E:A->A->bool) B a /\
       bval D (E:A->A->bool) B leq ((m |-> (a:A)) v) p zz)
       ==> E zz B` ASSUME_TAC THENL
     [DISCH_THEN(X_CHOOSE_THEN `a:A` STRIP_ASSUME_TAC) THEN
      MATCH_MP_TAC(ISPECL [`p:form`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
        `(m |-> (a:A)) (v:num->A)`;`zz:A`] BVAL_IN_B) THEN
      ASM_REWRITE_TAC[] THEN MATCH_MP_TAC VALUATION_VALMOD THEN
      ASM_REWRITE_TAC[]; ALL_TAC] THEN
    FIRST_X_ASSUM(fun sep -> MP_TAC(SPEC `zz:A` sep)) THEN
    ASM_REWRITE_TAC[] THEN
    USE_THEN "bridge"(MP_TAC o SPEC `zz:A`) THEN ASM_REWRITE_TAC[] THEN
    ASM_MESON_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `esubset D (E:A->A->bool) S B` ASSUME_TAC THENL
   [REWRITE_TAC[esubset] THEN ASM_MESON_TAC[]; ALL_TAC] THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`S:A`] ECBA_INF) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `u:A` ASSUME_TAC) THEN
  EXISTS_TAC `u:A` THEN CONJ_TAC THENL
   [ASM_MESON_TAC[EGLB_IN]; ALL_TAC] THEN
  REWRITE_TAC[bval] THEN EXISTS_TAC `S:A` THEN ASM_REWRITE_TAC[]]);;

(* ------------------------------------------------------------------ *)
(* BVAL_UNIQUE: the Boolean value is single-valued (all values in D).   *)
(* False=EBOT_UNIQUE; atomics=EBV_IN/EQ_UNIQUE; -->=EBIMP_UNIQUE on the  *)
(* IH-equal sub-values; !!=ZF_EXTENSIONALITY (the two value-sets have    *)
(* the same members) + EGLB_UNIQUE.                                     *)
(* ------------------------------------------------------------------ *)

let BVAL_UNIQUE = prove
 (`!p D (E:A->A->bool) B leq v z1 z2.
      model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
        valuation D v /\
      z1 IN D /\ z2 IN D /\ bval D E B leq v p z1 /\ bval D E B leq v p z2
      ==> z1 = z2`,
  MATCH_MP_TAC form_INDUCT THEN REPEAT CONJ_TAC THENL
   [(* False *)
    REPEAT GEN_TAC THEN REWRITE_TAC[bval] THEN STRIP_TAC THEN
    SUBGOAL_THEN `eporder D (E:A->A->bool) B leq` ASSUME_TAC THENL
     [FIRST_ASSUM(ACCEPT_TAC o CONJUNCT1 o REWRITE_RULE[elattice] o CONJUNCT1 o
        REWRITE_RULE[ebalg] o CONJUNCT1 o REWRITE_RULE[ecba]); ALL_TAC] THEN
    MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`z1:A`;`z2:A`]
                 EBOT_UNIQUE) THEN ASM_REWRITE_TAC[];
    (* i %% j *)
    MAP_EVERY X_GEN_TAC [`i:num`;`j:num`] THEN REPEAT GEN_TAC THEN
    REWRITE_TAC[bval] THEN STRIP_TAC THEN
    SUBGOAL_THEN `!x. (v:num->A) x IN D` ASSUME_TAC THENL
     [ASM_MESON_TAC[valuation]; ALL_TAC] THEN
    MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
      `(v:num->A) i`;`(v:num->A) j`;`z1:A`;`z2:A`] EBV_IN_UNIQUE) THEN
    ASM_REWRITE_TAC[];
    (* Eq i j *)
    MAP_EVERY X_GEN_TAC [`i:num`;`j:num`] THEN REPEAT GEN_TAC THEN
    REWRITE_TAC[bval] THEN STRIP_TAC THEN
    SUBGOAL_THEN `!x. (v:num->A) x IN D` ASSUME_TAC THENL
     [ASM_MESON_TAC[valuation]; ALL_TAC] THEN
    MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
      `(v:num->A) i`;`(v:num->A) j`;`z1:A`;`z2:A`] EBV_EQ_UNIQUE) THEN
    ASM_REWRITE_TAC[];
    (* p --> q *)
    MAP_EVERY X_GEN_TAC [`p:form`;`q:form`] THEN
    DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "ihp") (LABEL_TAC "ihq")) THEN
    REPEAT GEN_TAC THEN STRIP_TAC THEN
    SUBGOAL_THEN `ebalg D (E:A->A->bool) B leq` ASSUME_TAC THENL
     [FIRST_ASSUM(ACCEPT_TAC o CONJUNCT1 o REWRITE_RULE[ecba]); ALL_TAC] THEN
    FIRST_X_ASSUM(X_CHOOSE_THEN `zp2:A`
                  (X_CHOOSE_THEN `zq2:A` STRIP_ASSUME_TAC) o
                  REWRITE_RULE[bval]) THEN
    FIRST_X_ASSUM(X_CHOOSE_THEN `zp1:A`
                  (X_CHOOSE_THEN `zq1:A` STRIP_ASSUME_TAC) o
                  REWRITE_RULE[bval]) THEN
    SUBGOAL_THEN `(zp1:A) = zp2 /\ (zq1:A) = zq2` STRIP_ASSUME_TAC THENL
     [CONJ_TAC THENL
       [USE_THEN "ihp"(MATCH_MP_TAC o SPECL
          [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`v:num->A`]);
        USE_THEN "ihq"(MATCH_MP_TAC o SPECL
          [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`v:num->A`])] THEN
      ASM_REWRITE_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN `(E:A->A->bool) (zp1:A) (B:A) /\ E (zp2:A) B`
      STRIP_ASSUME_TAC THENL
      [CONJ_TAC THENL
       [MATCH_MP_TAC(ISPECL [`p:form`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
          `v:num->A`;`zp1:A`] BVAL_IN_B);
        MATCH_MP_TAC(ISPECL [`p:form`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
          `v:num->A`;`zp2:A`] BVAL_IN_B)] THEN
      ASM_REWRITE_TAC[]; ALL_TAC] THEN
    MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`zp1:A`;`zq1:A`;
                  `z1:A`;`z2:A`] EBIMP_UNIQUE) THEN
    ASM_REWRITE_TAC[];
    (* !! m p *)
    MAP_EVERY X_GEN_TAC [`m:num`;`p:form`] THEN DISCH_TAC THEN
    REPEAT GEN_TAC THEN STRIP_TAC THEN
    SUBGOAL_THEN `eporder D (E:A->A->bool) B leq` ASSUME_TAC THENL
     [FIRST_ASSUM(ACCEPT_TAC o CONJUNCT1 o REWRITE_RULE[elattice] o CONJUNCT1 o
        REWRITE_RULE[ebalg] o CONJUNCT1 o REWRITE_RULE[ecba]); ALL_TAC] THEN
    FIRST_X_ASSUM(X_CHOOSE_THEN `ss2:A` STRIP_ASSUME_TAC o
                  REWRITE_RULE[bval]) THEN
    FIRST_X_ASSUM(X_CHOOSE_THEN `ss1:A` STRIP_ASSUME_TAC o
                  REWRITE_RULE[bval]) THEN
    SUBGOAL_THEN `(ss1:A) = ss2` SUBST_ALL_TAC THENL
     [FIRST_ASSUM(MATCH_MP_TAC o MATCH_MP ZF_EXTENSIONALITY) THEN
      ASM_REWRITE_TAC[] THEN X_GEN_TAC `zz:A` THEN DISCH_TAC THEN
      ASM_MESON_TAC[]; ALL_TAC] THEN
    MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`ss2:A`;
      `z1:A`;`z2:A`] EGLB_UNIQUE) THEN ASM_REWRITE_TAC[]]);;

(* ------------------------------------------------------------------ *)
(* bvalf: the Boolean value packaged as a B-valued FUNCTION.           *)
(* Well-defined on bname-valuations via BVAL_TOTAL + BVAL_UNIQUE.      *)
(* ------------------------------------------------------------------ *)

let bvalf = new_definition
 `bvalf D (E:A->A->bool) B leq v p = @z. z IN D /\ bval D E B leq v p z`;;

let BVALF_SPEC = prove
 (`!p D (E:A->A->bool) B leq v.
      model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
      valuation D v /\ (!i. bname D E B (v i))
      ==> (bvalf D E B leq v p) IN D /\
          bval D E B leq v p (bvalf D E B leq v p)`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN REWRITE_TAC[bvalf] THEN
  CONV_TAC SELECT_CONV THEN MATCH_MP_TAC BVAL_TOTAL THEN ASM_REWRITE_TAC[]);;

let BVALF_IN_B = prove
 (`!p D (E:A->A->bool) B leq v.
      model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
      valuation D v /\ (!i. bname D E B (v i))
      ==> E (bvalf D E B leq v p) B`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  MP_TAC(ISPECL [`p:form`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`v:num->A`]
    BVALF_SPEC) THEN ASM_REWRITE_TAC[] THEN STRIP_TAC THEN
  MATCH_MP_TAC(ISPECL
               [`p:form`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`v:num->A`;
                `bvalf D (E:A->A->bool) B leq v p`] BVAL_IN_B) THEN
  ASM_REWRITE_TAC[]);;

let BVALF_EQ = prove
 (`!p D (E:A->A->bool) B leq v z.
      model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
      valuation D v /\ (!i. bname D E B (v i)) /\
      z IN D /\ bval D E B leq v p z
      ==> z = bvalf D E B leq v p`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  MP_TAC(ISPECL [`p:form`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`v:num->A`]
    BVALF_SPEC) THEN ASM_REWRITE_TAC[] THEN STRIP_TAC THEN
  MATCH_MP_TAC(ISPECL
               [`p:form`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`v:num->A`;
                `z:A`;`bvalf D (E:A->A->bool) B leq v p`] BVAL_UNIQUE) THEN
  ASM_REWRITE_TAC[]);;

(* ------------------------------------------------------------------ *)
(* F5 groundwork -- bvalf is a Boolean-algebra homomorphism from the   *)
(* object connectives to B: False|->bottom, %%|->ebv_in, Eq|->ebv_eq,  *)
(* -->|->ebimp.  (bval commutes with the connectives, via BVALF_SPEC/  *)
(* BVALF_EQ.)  Workhorses for the per-axiom [[axiom]]=etop proofs.      *)
(* ------------------------------------------------------------------ *)

let BVALF_FALSE = prove
 (`!D (E:A->A->bool) B leq v.
      model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
      valuation D v /\ (!i. bname D E B (v i))
      ==> ebot D E B leq (bvalf D E B leq v False)`,
  REPEAT STRIP_TAC THEN
  MP_TAC(ISPECL [`False`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`v:num->A`]
    BVALF_SPEC) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  REWRITE_TAC[bval] THEN SIMP_TAC[]);;
let BVALF_MEM = prove
 (`!i j D (E:A->A->bool) B leq v.
      model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
      valuation D v /\ (!k. bname D E B (v k))
      ==> ebv_in D E B leq (v i) (v j) (bvalf D E B leq v (i %% j))`,
  REPEAT STRIP_TAC THEN
  MP_TAC(ISPECL
         [`(i:num) %% j`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`v:num->A`]
         BVALF_SPEC) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  REWRITE_TAC[bval] THEN SIMP_TAC[]);;
let BVALF_EQ2 = prove
 (`!i j D (E:A->A->bool) B leq v.
      model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
      valuation D v /\ (!k. bname D E B (v k))
      ==> ebv_eq D E B leq (v i) (v j) (bvalf D E B leq v (Eq i j))`,
  REPEAT STRIP_TAC THEN
  MP_TAC(ISPECL [`Eq i j`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`v:num->A`]
    BVALF_SPEC) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  REWRITE_TAC[bval] THEN SIMP_TAC[]);;
let BVALF_IMP = prove
 (`!p q D (E:A->A->bool) B leq v.
      model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
      valuation D v /\ (!i. bname D E B (v i))
      ==> ebimp D E B leq (bvalf D E B leq v p) (bvalf D E B leq v q)
                          (bvalf D E B leq v (p --> q))`,
  REPEAT STRIP_TAC THEN
  MP_TAC(ISPECL [`p --> q`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`v:num->A`]
    BVALF_SPEC) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  REWRITE_TAC[bval] THEN
  DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC
    (X_CHOOSE_THEN `zp:A` (X_CHOOSE_THEN `zq:A` STRIP_ASSUME_TAC))) THEN
  SUBGOAL_THEN `bvalf D (E:A->A->bool) B leq v p = zp /\
                bvalf D E B leq v q = zq` STRIP_ASSUME_TAC THENL
   [CONJ_TAC THEN CONV_TAC SYM_CONV THENL
     [MATCH_MP_TAC(ISPECL [`p:form`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
        `v:num->A`;`zp:A`] BVALF_EQ);
      MATCH_MP_TAC(ISPECL [`q:form`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
        `v:num->A`;`zq:A`] BVALF_EQ)] THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  ASM_REWRITE_TAC[]);;

(* ===================================================================== *)
(* F5 groundwork: "[[.]] = top" reduction lemmas.                         *)
(*   The Boolean value of an implication/universal equals the top of B    *)
(*   iff a simple order/quantified condition holds -- the bridge from the  *)
(*   Boolean-valued semantics to "V^B satisfies the axiom".                *)
(* --------------------------------------------------------------------- *)
(* glb of a subset of B is top  <=>  every member of the subset is top.   *)
let EGLB_TOP = prove
 (`!D (E:A->A->bool) B leq s u.
      eporder D E B leq /\ (?t. etop D E B leq t) /\ esubset D E s B /\
      eglb D E B leq s u
      ==> (etop D E B leq u <=>
           (!w. w IN D /\ E w s ==> etop D E B leq w))`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  FIRST_ASSUM(STRIP_ASSUME_TAC o REWRITE_RULE[eglb; elbound]) THEN
  SUBGOAL_THEN `(t:A) IN D /\ (E:A->A->bool) t B` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[ETOP_IN]; ALL_TAC] THEN
  EQ_TAC THENL
   [DISCH_TAC THEN X_GEN_TAC `w:A` THEN STRIP_TAC THEN
    SUBGOAL_THEN `w:A = u` (fun th -> ASM_MESON_TAC[th]) THEN
    MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`w:A`;`u:A`]
      EPORDER_ANTISYM) THEN
    ASM_REWRITE_TAC[] THEN REPEAT CONJ_TAC THENL
     [ASM_MESON_TAC[esubset];
      MATCH_MP_TAC(ISPECL
                   [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`u:A`;`w:A`]
                   ETOP_GE) THEN ASM_MESON_TAC[esubset];
      FIRST_X_ASSUM MATCH_MP_TAC THEN ASM_REWRITE_TAC[]];
    DISCH_TAC THEN
    SUBGOAL_THEN `u:A = t` (fun th -> ASM_MESON_TAC[th]) THEN
    MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`u:A`;`t:A`]
      EPORDER_ANTISYM) THEN
    ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
     [MATCH_MP_TAC(ISPECL
                   [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`t:A`;`u:A`]
                   ETOP_GE) THEN ASM_REWRITE_TAC[];
      FIRST_X_ASSUM MATCH_MP_TAC THEN ASM_REWRITE_TAC[] THEN
      X_GEN_TAC `x:A` THEN STRIP_TAC THEN
      SUBGOAL_THEN `x:A = t` (fun th -> ASM_MESON_TAC[th; EPORDER_REFL]) THEN
      MATCH_MP_TAC(ISPECL
                   [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`x:A`;`t:A`]
                   ETOP_UNIQUE) THEN ASM_REWRITE_TAC[] THEN
      FIRST_X_ASSUM MATCH_MP_TAC THEN ASM_REWRITE_TAC[]]]);;

(* Boolean implication  x=>y  is top  <=>  x <= y  (in the order of B).   *)
let EBIMP_TOP = prove
 (`!D (E:A->A->bool) p leq x y z.
      ebalg D E p leq /\ x IN D /\ y IN D /\ E x p /\ E y p /\
      ebimp D E p leq x y z
      ==> (etop D E p leq z <=> erel D E leq x y)`,
  REPEAT GEN_TAC THEN REWRITE_TAC[ebimp] THEN STRIP_TAC THEN
  SUBGOAL_THEN `eporder D (E:A->A->bool) p leq` ASSUME_TAC THENL
   [ASM_MESON_TAC[EBALG_IMP_PORDER]; ALL_TAC] THEN
  SUBGOAL_THEN `(c:A) IN D /\ (E:A->A->bool) c p` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[ECOMPL_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `(z:A) IN D /\ (E:A->A->bool) z p` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[EJOIN_IN]; ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`p:A`;`leq:A`] EBALG_BOT) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `bot:A`) THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`p:A`;`leq:A`] EBALG_TOP) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `top:A`) THEN
  SUBGOAL_THEN
   `(bot:A) IN D /\ (E:A->A->bool) bot p /\ (top:A) IN D /\ E top p`
  STRIP_ASSUME_TAC THENL [ASM_MESON_TAC[EBOT_IN; ETOP_IN]; ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`p:A`;`leq:A`;`x:A`;`c:A`;
                `bot:A`;`top:A`] ECOMPL_MEET_JOIN) THEN
  ASM_REWRITE_TAC[] THEN STRIP_TAC THEN
  EQ_TAC THENL
   [DISCH_TAC THEN
    SUBGOAL_THEN `emeet D (E:A->A->bool) p leq x z x` ASSUME_TAC THENL
     [MATCH_MP_TAC EMEET_TOP THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`p:A`;`leq:A`;`x:A`;`y:A`]
          EBALG_MEET) THEN
    ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `d:A`) THEN
    SUBGOAL_THEN `(d:A) IN D /\ (E:A->A->bool) d p` STRIP_ASSUME_TAC THENL
     [ASM_MESON_TAC[EMEET_IN]; ALL_TAC] THEN
    SUBGOAL_THEN `ejoin D (E:A->A->bool) p leq bot d d` ASSUME_TAC THENL
     [MATCH_MP_TAC EJOIN_BOT THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`p:A`;`leq:A`;`x:A`;`c:A`;`y:A`;
                  `z:A`;`x:A`;`bot:A`;`d:A`;`d:A`] EBALG_DISTRIB) THEN
    ASM_REWRITE_TAC[] THEN DISCH_TAC THEN
    FIRST_X_ASSUM(SUBST_ALL_TAC o SYM) THEN
    MP_TAC(MATCH_MP EMEET_LE
      (ASSUME `emeet D (E:A->A->bool) p leq x y x`)) THEN
    ASM_REWRITE_TAC[] THEN DISCH_THEN(ACCEPT_TAC o CONJUNCT2);
    DISCH_TAC THEN
    SUBGOAL_THEN `ejoin D (E:A->A->bool) p leq c x top` ASSUME_TAC THENL
     [MATCH_MP_TAC EJOIN_SYM THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN `erel D E leq (c:A) z` ASSUME_TAC THENL
     [ASM_MESON_TAC[EJOIN_GE]; ALL_TAC] THEN
    SUBGOAL_THEN `erel D E leq (y:A) z` ASSUME_TAC THENL
     [ASM_MESON_TAC[EJOIN_GE]; ALL_TAC] THEN
    SUBGOAL_THEN `erel D E leq (x:A) z` ASSUME_TAC THENL
     [MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`p:A`;`leq:A`;`x:A`;`y:A`;`z:A`]
            EPORDER_TRANS) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN `erel D E leq (top:A) z` ASSUME_TAC THENL
     [MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`p:A`;`leq:A`;`c:A`;`x:A`;
                    `top:A`;`z:A`] EJOIN_LEAST) THEN ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    SUBGOAL_THEN `erel D E leq (z:A) top` ASSUME_TAC THENL
     [MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`p:A`;`leq:A`;`top:A`;`z:A`]
            ETOP_GE) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN `z:A = top` SUBST1_TAC THENL
     [MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`p:A`;`leq:A`;`z:A`;`top:A`]
            EPORDER_ANTISYM) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    ASM_REWRITE_TAC[]]);;

(* bname is preserved by valuation-modification with a bname value.       *)
let BNAMEVAL_VALMOD = prove
 (`!D (E:A->A->bool) B n a (v:num->A).
      bname D E B a /\ (!i. bname D E B (v i))
      ==> (!i. bname D E B (((n |-> a) v) i))`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN GEN_TAC THEN
  ASM_CASES_TAC `i:num = n` THEN ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER]);;

(* [[!!n p]]_v = top  <=>  [[p]]_((n|->a)v) = top for every bname a.       *)
let BVALF_ALL_TOP = prove
 (`!n p D (E:A->A->bool) B leq v.
      model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
      valuation D v /\ (!i. bname D E B (v i))
      ==> (etop D E B leq (bvalf D (E:A->A->bool) B leq v (!! n p)) <=>
           (!a. a IN D /\ bname D E B a
                ==> etop D E B leq
                  (bvalf D (E:A->A->bool) B leq
                   ((n |-> (a:A)) (v:num->A)) p)))`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `eporder D (E:A->A->bool) B leq` ASSUME_TAC THENL
   [FIRST_ASSUM(ACCEPT_TAC o CONJUNCT1 o REWRITE_RULE[elattice] o CONJUNCT1 o
      REWRITE_RULE[ebalg] o CONJUNCT1 o REWRITE_RULE[ecba]); ALL_TAC] THEN
  SUBGOAL_THEN `?t. etop D (E:A->A->bool) B leq t` ASSUME_TAC THENL
   [MATCH_MP_TAC EBALG_TOP THEN
    FIRST_ASSUM(ACCEPT_TAC o CONJUNCT1 o REWRITE_RULE[ecba]); ALL_TAC] THEN
  MP_TAC(ISPECL [`!! n p`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`v:num->A`]
    BVALF_SPEC) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  REWRITE_TAC[bval] THEN
  DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC
             (X_CHOOSE_THEN `sv:A` STRIP_ASSUME_TAC)) THEN
  (* sv IN D, membership !zz., eglb sv (bvalf(!!n p)) *)
  SUBGOAL_THEN `esubset D (E:A->A->bool) sv B` ASSUME_TAC THENL
   [REWRITE_TAC[esubset] THEN X_GEN_TAC `zz:A` THEN STRIP_TAC THEN
    FIRST_X_ASSUM(fun th -> MP_TAC(SPEC `zz:A` th) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC]) THEN
    ASM_REWRITE_TAC[] THEN
    DISCH_THEN(X_CHOOSE_THEN `a:A` STRIP_ASSUME_TAC) THEN
    MATCH_MP_TAC(ISPECL [`p:form`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
      `(n |-> (a:A)) (v:num->A)`;`zz:A`] BVAL_IN_B) THEN
    ASM_REWRITE_TAC[] THEN MATCH_MP_TAC VALUATION_VALMOD THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`sv:A`;
    `bvalf D (E:A->A->bool) B leq v (!! n p)`] EGLB_TOP) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN SUBST1_TAC THEN
  EQ_TAC THENL
   [DISCH_TAC THEN X_GEN_TAC `a:A` THEN STRIP_TAC THEN
    SUBGOAL_THEN `!i. bname D E B (((n |-> (a:A)) (v:num->A)) i)`
      ASSUME_TAC THENL
      [MATCH_MP_TAC BNAMEVAL_VALMOD THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    FIRST_X_ASSUM MATCH_MP_TAC THEN
    MP_TAC(ISPECL
           [`p:form`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
            `(n |-> (a:A)) (v:num->A)`]
           BVALF_SPEC) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[] THEN MATCH_MP_TAC VALUATION_VALMOD THEN
      ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    STRIP_TAC THEN ASM_REWRITE_TAC[] THEN
    FIRST_X_ASSUM(fun th ->
                  MP_TAC(SPEC
                         `bvalf D (E:A->A->bool) B leq
                          ((n |-> (a:A)) (v:num->A)) p` th) THEN
                  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC]) THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    MAP_EVERY EXISTS_TAC [`a:A`] THEN ASM_REWRITE_TAC[];
    DISCH_TAC THEN X_GEN_TAC `w:A` THEN STRIP_TAC THEN
    FIRST_X_ASSUM(fun th ->
      if is_forall(concl th) && mem `sv:A` (frees(concl th))
      then (MP_TAC(SPEC `w:A` th) THEN
            ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC])
      else failwith "skip") THEN
    ASM_REWRITE_TAC[] THEN
    DISCH_THEN(X_CHOOSE_THEN `a:A` STRIP_ASSUME_TAC) THEN
    SUBGOAL_THEN `!i. bname D E B (((n |-> (a:A)) (v:num->A)) i)`
      ASSUME_TAC THENL
      [MATCH_MP_TAC BNAMEVAL_VALMOD THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN
      `w:A = bvalf D (E:A->A->bool) B leq ((n |-> (a:A)) (v:num->A)) p`
      SUBST1_TAC THENL
      [MATCH_MP_TAC(ISPECL [`p:form`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
        `(n |-> (a:A)) (v:num->A)`;`w:A`] BVALF_EQ) THEN
      ASM_REWRITE_TAC[] THEN MATCH_MP_TAC VALUATION_VALMOD THEN
      ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    FIRST_X_ASSUM MATCH_MP_TAC THEN ASM_REWRITE_TAC[]]);;

(* [[p-->q]]_v = top  <=>  [[p]]_v <= [[q]]_v  (in the order of B).        *)
let BVALF_IMP_TOP = prove
 (`!p q D (E:A->A->bool) B leq v.
      model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
      valuation D v /\ (!i. bname D E B (v i))
      ==> (etop D E B leq (bvalf D E B leq v (p --> q)) <=>
           erel D E leq (bvalf D E B leq v p) (bvalf D E B leq v q))`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `ebalg D (E:A->A->bool) B leq` ASSUME_TAC THENL
   [FIRST_ASSUM(ACCEPT_TAC o CONJUNCT1 o REWRITE_RULE[ecba]); ALL_TAC] THEN
  MP_TAC(ISPECL [`p:form`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`v:num->A`]
    BVALF_SPEC) THEN ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  STRIP_TAC THEN
  MP_TAC(ISPECL [`q:form`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`v:num->A`]
    BVALF_SPEC) THEN ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  STRIP_TAC THEN
  MP_TAC(ISPECL [`p:form`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`v:num->A`]
    BVALF_IN_B) THEN ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_TAC THEN
  MP_TAC(ISPECL [`q:form`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`v:num->A`]
    BVALF_IN_B) THEN ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_TAC THEN
  MP_TAC(ISPECL
         [`p:form`;`q:form`;`D:A->bool`;`E:A->A->bool`;`B:A`;
          `leq:A`;`v:num->A`]
         BVALF_IMP) THEN ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_TAC THEN
  MATCH_MP_TAC EBIMP_TOP THEN ASM_REWRITE_TAC[]);;

(* ===================================================================== *)
(* F5 connective layer (part A): complement / negation.                  *)
(*   bvalf is a homomorphism on Not (=> Boolean complement); plus the    *)
(*   complement facts (symmetry, involution, compl-of-top-is-bottom) and *)
(*   the resulting "[[Not p]] = top <=> [[p]] = bottom" characterization.  *)
(* --------------------------------------------------------------------- *)
(* complement is symmetric: y complements x  =>  x complements y.        *)
let ECOMPL_SYM = prove
 (`!D (E:A->A->bool) p leq x y.
      ecompl D E p leq x y /\ x IN D /\ E x p ==> ecompl D E p leq y x`,
  REPEAT GEN_TAC THEN REWRITE_TAC[ecompl] THEN STRIP_TAC THEN
  ASM_REWRITE_TAC[] THEN MAP_EVERY EXISTS_TAC [`z:A`;`u:A`] THEN
  ASM_REWRITE_TAC[] THEN
  CONJ_TAC THENL [MATCH_MP_TAC EMEET_SYM; MATCH_MP_TAC EJOIN_SYM] THEN
  ASM_REWRITE_TAC[]);;

(* complement is involutive: the complement of the complement is x.      *)
let ECOMPL_INVOL = prove
 (`!D (E:A->A->bool) p leq x y w.
      ebalg D E p leq /\ x IN D /\ E x p /\
      ecompl D E p leq x y /\ ecompl D E p leq y w ==> w = x`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `(y:A) IN D /\ (E:A->A->bool) y p` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[ECOMPL_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `ecompl D (E:A->A->bool) p leq y x` ASSUME_TAC THENL
   [MATCH_MP_TAC ECOMPL_SYM THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`p:A`;`leq:A`;`y:A`;`w:A`;`x:A`]
    ECOMPL_UNIQUE) THEN ASM_REWRITE_TAC[]);;

(* the complement of x is the top  <=>  x is the bottom.                 *)
let ECOMPL_TOP_BOT = prove
 (`!D (E:A->A->bool) p leq x y.
      eporder D E p leq /\ x IN D /\ E x p /\ ecompl D E p leq x y
      ==> (etop D E p leq y <=> ebot D E p leq x)`,
  REPEAT GEN_TAC THEN REWRITE_TAC[ecompl] THEN
  DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC (CONJUNCTS_THEN2 ASSUME_TAC
    (CONJUNCTS_THEN2 ASSUME_TAC
     (CONJUNCTS_THEN2 ASSUME_TAC (CONJUNCTS_THEN2 ASSUME_TAC
      (X_CHOOSE_THEN `zz:A` (X_CHOOSE_THEN `uu:A` STRIP_ASSUME_TAC))))))) THEN
  EQ_TAC THEN DISCH_TAC THENL
   [SUBGOAL_THEN `y:A = uu` SUBST_ALL_TAC THENL
     [MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`p:A`;`leq:A`;`y:A`;`uu:A`]
        ETOP_UNIQUE) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN `emeet D (E:A->A->bool) p leq x uu x` ASSUME_TAC THENL
     [MATCH_MP_TAC EMEET_TOP THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN `x:A = zz` SUBST_ALL_TAC THENL
     [MP_TAC(SPECL
             [`D:A->bool`;`E:A->A->bool`;`p:A`;`leq:A`;`x:A`;`uu:A`;
              `x:A`;`zz:A`]
             EMEET_UNIQUE) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    ASM_REWRITE_TAC[];
    SUBGOAL_THEN `x:A = zz` SUBST_ALL_TAC THENL
     [MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`p:A`;`leq:A`;`x:A`;`zz:A`]
        EBOT_UNIQUE) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN `ejoin D (E:A->A->bool) p leq zz y y` ASSUME_TAC THENL
     [MATCH_MP_TAC EJOIN_BOT THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN `y:A = uu` SUBST_ALL_TAC THENL
     [MP_TAC(SPECL
             [`D:A->bool`;`E:A->A->bool`;`p:A`;`leq:A`;`zz:A`;`y:A`;
              `y:A`;`uu:A`]
             EJOIN_UNIQUE) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    ASM_REWRITE_TAC[]]);;

(* bvalf(Not p) is the Boolean complement of bvalf(p).                   *)
let BVALF_NOT = prove
 (`!p D (E:A->A->bool) B leq v.
      model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
      valuation D v /\ (!i. bname D E B (v i))
      ==> ecompl D E B leq (bvalf D E B leq v p) (bvalf D E B leq v (Not p))`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[Not_DEF] THEN
  SUBGOAL_THEN `ebalg D (E:A->A->bool) B leq` ASSUME_TAC THENL
   [FIRST_ASSUM(ACCEPT_TAC o CONJUNCT1 o REWRITE_RULE[ecba]); ALL_TAC] THEN
  SUBGOAL_THEN `eporder D (E:A->A->bool) B leq` ASSUME_TAC THENL
   [ASM_MESON_TAC[EBALG_IMP_PORDER]; ALL_TAC] THEN
  SUBGOAL_THEN `ebot D (E:A->A->bool) B leq (bvalf D E B leq v False)`
    ASSUME_TAC THENL
   [MP_TAC(ISPECL [`False`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`v:num->A`]
      BVALF_SPEC) THEN ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    REWRITE_TAC[bval] THEN STRIP_TAC THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MP_TAC(ISPECL [`p:form`;`False`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
                 `v:num->A`] BVALF_IMP) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  REWRITE_TAC[ebimp] THEN
  DISCH_THEN(X_CHOOSE_THEN `c:A` STRIP_ASSUME_TAC) THEN
  SUBGOAL_THEN `(c:A) IN D /\ (E:A->A->bool) c B` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[ECOMPL_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `ejoin D (E:A->A->bool) B leq c (bvalf D E B leq v False) c`
  ASSUME_TAC THENL
   [MATCH_MP_TAC EJOIN_SYM THEN MATCH_MP_TAC EJOIN_BOT THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `bvalf D (E:A->A->bool) B leq v (p --> False) = c`
    SUBST1_TAC THENL
   [MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`c:A`;
      `bvalf D (E:A->A->bool) B leq v False`;
      `bvalf D (E:A->A->bool) B leq v (p --> False)`;`c:A`] EJOIN_UNIQUE) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  ASM_REWRITE_TAC[]);;

(* [[Not p]]_v = top  <=>  [[p]]_v = bottom.                             *)
let BVALF_NOT_TOP = prove
 (`!p D (E:A->A->bool) B leq v.
      model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
      valuation D v /\ (!i. bname D E B (v i))
      ==> (etop D E B leq (bvalf D E B leq v (Not p)) <=>
           ebot D E B leq (bvalf D E B leq v p))`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `ebalg D (E:A->A->bool) B leq` ASSUME_TAC THENL
   [FIRST_ASSUM(ACCEPT_TAC o CONJUNCT1 o REWRITE_RULE[ecba]); ALL_TAC] THEN
  SUBGOAL_THEN `eporder D (E:A->A->bool) B leq` ASSUME_TAC THENL
   [ASM_MESON_TAC[EBALG_IMP_PORDER]; ALL_TAC] THEN
  MP_TAC(ISPECL [`p:form`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`v:num->A`]
    BVALF_SPEC) THEN ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  STRIP_TAC THEN
  MP_TAC(ISPECL [`p:form`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`v:num->A`]
    BVALF_IN_B) THEN ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_TAC THEN
  MP_TAC(ISPECL [`p:form`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`v:num->A`]
    BVALF_NOT) THEN ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_TAC THEN
  MATCH_MP_TAC ECOMPL_TOP_BOT THEN ASM_REWRITE_TAC[]);;

(* ===================================================================== *)
(* F5 connective layer (part B): the =bottom duals + conjunction/dis-    *)
(*   junction.  With these, a subformula's Boolean value composes as the *)
(*   expected Boolean operation, and "[[p&&q]] = top" reduces to both      *)
(*   conjuncts being top -- the shape ZF-axiom validation consumes.       *)
(* --------------------------------------------------------------------- *)
(* the complement of x is the bottom  <=>  x is the top (dual of _TOP_BOT). *)
let ECOMPL_BOT_TOP = prove
 (`!D (E:A->A->bool) p leq x y.
      eporder D E p leq /\ x IN D /\ E x p /\ ecompl D E p leq x y
      ==> (ebot D E p leq y <=> etop D E p leq x)`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `(y:A) IN D /\ (E:A->A->bool) y p` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[ECOMPL_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `ecompl D (E:A->A->bool) p leq y x` ASSUME_TAC THENL
   [MATCH_MP_TAC ECOMPL_SYM THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`p:A`;`leq:A`;`y:A`;`x:A`]
    ECOMPL_TOP_BOT) THEN ASM_REWRITE_TAC[] THEN MESON_TAC[]);;

(* Boolean implication x=>y is bottom  <=>  x is top and y is bottom.     *)
let EBIMP_BOT = prove
 (`!D (E:A->A->bool) p leq x y z.
      ebalg D E p leq /\ x IN D /\ y IN D /\ E x p /\ E y p /\
      ebimp D E p leq x y z
      ==> (ebot D E p leq z <=> etop D E p leq x /\ ebot D E p leq y)`,
  REPEAT GEN_TAC THEN REWRITE_TAC[ebimp] THEN STRIP_TAC THEN
  SUBGOAL_THEN `eporder D (E:A->A->bool) p leq` ASSUME_TAC THENL
   [ASM_MESON_TAC[EBALG_IMP_PORDER]; ALL_TAC] THEN
  SUBGOAL_THEN `(c:A) IN D /\ (E:A->A->bool) c p` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[ECOMPL_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `(z:A) IN D /\ (E:A->A->bool) z p` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[EJOIN_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `ebot D (E:A->A->bool) p leq c <=> etop D E p leq x`
    ASSUME_TAC THENL
   [MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`p:A`;`leq:A`;`x:A`;`c:A`]
      ECOMPL_BOT_TOP) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `erel D E leq (c:A) z /\ erel D E leq (y:A) z`
    STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[EJOIN_GE]; ALL_TAC] THEN
  EQ_TAC THENL
   [DISCH_TAC THEN
    SUBGOAL_THEN `erel D E leq (z:A) c /\ erel D E leq (z:A) y`
      STRIP_ASSUME_TAC THENL
      [ASM_MESON_TAC[EBOT_LE]; ALL_TAC] THEN
    SUBGOAL_THEN `c:A = z` ASSUME_TAC THENL
     [MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`p:A`;`leq:A`;`c:A`;`z:A`]
        EPORDER_ANTISYM) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN `y:A = z` ASSUME_TAC THENL
     [MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`p:A`;`leq:A`;`y:A`;`z:A`]
        EPORDER_ANTISYM) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    CONJ_TAC THENL
     [FIRST_X_ASSUM(fun th -> MP_TAC th THEN
        DISCH_THEN(SUBST1_TAC o SYM) THEN NO_TAC) ORELSE ALL_TAC THEN
      ASM_MESON_TAC[]; ASM_MESON_TAC[]];
    STRIP_TAC THEN
    SUBGOAL_THEN `ebot D (E:A->A->bool) p leq c` ASSUME_TAC THENL
     [ASM_MESON_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN `ejoin D (E:A->A->bool) p leq c y y` ASSUME_TAC THENL
     [MATCH_MP_TAC EJOIN_BOT THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN `z:A = y` ASSUME_TAC THENL
     [MP_TAC(SPECL
             [`D:A->bool`;`E:A->A->bool`;`p:A`;`leq:A`;`c:A`;`y:A`;`z:A`;`y:A`]
             EJOIN_UNIQUE) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    ASM_MESON_TAC[]]);;

(* [[p-->q]]_v = bottom  <=>  [[p]]_v = top and [[q]]_v = bottom.         *)
let BVALF_IMP_BOT = prove
 (`!p q D (E:A->A->bool) B leq v.
      model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
      valuation D v /\ (!i. bname D E B (v i))
      ==> (ebot D E B leq (bvalf D E B leq v (p --> q)) <=>
           etop D E B leq (bvalf D E B leq v p) /\
           ebot D E B leq (bvalf D E B leq v q))`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `ebalg D (E:A->A->bool) B leq` ASSUME_TAC THENL
   [FIRST_ASSUM(ACCEPT_TAC o CONJUNCT1 o REWRITE_RULE[ecba]); ALL_TAC] THEN
  MP_TAC(ISPECL [`p:form`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`v:num->A`]
    BVALF_SPEC) THEN ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  STRIP_TAC THEN
  MP_TAC(ISPECL [`q:form`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`v:num->A`]
    BVALF_SPEC) THEN ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  STRIP_TAC THEN
  MP_TAC(ISPECL [`p:form`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`v:num->A`]
    BVALF_IN_B) THEN ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_TAC THEN
  MP_TAC(ISPECL [`q:form`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`v:num->A`]
    BVALF_IN_B) THEN ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_TAC THEN
  MP_TAC(ISPECL
         [`p:form`;`q:form`;`D:A->bool`;`E:A->A->bool`;`B:A`;
          `leq:A`;`v:num->A`]
         BVALF_IMP) THEN ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_TAC THEN
  MATCH_MP_TAC EBIMP_BOT THEN ASM_REWRITE_TAC[]);;

(* [[Not p]]_v = bottom  <=>  [[p]]_v = top.                             *)
let BVALF_NOT_BOT = prove
 (`!p D (E:A->A->bool) B leq v.
      model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
      valuation D v /\ (!i. bname D E B (v i))
      ==> (ebot D E B leq (bvalf D E B leq v (Not p)) <=>
           etop D E B leq (bvalf D E B leq v p))`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `ebalg D (E:A->A->bool) B leq` ASSUME_TAC THENL
   [FIRST_ASSUM(ACCEPT_TAC o CONJUNCT1 o REWRITE_RULE[ecba]); ALL_TAC] THEN
  SUBGOAL_THEN `eporder D (E:A->A->bool) B leq` ASSUME_TAC THENL
   [ASM_MESON_TAC[EBALG_IMP_PORDER]; ALL_TAC] THEN
  MP_TAC(ISPECL [`p:form`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`v:num->A`]
    BVALF_SPEC) THEN ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  STRIP_TAC THEN
  MP_TAC(ISPECL [`p:form`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`v:num->A`]
    BVALF_IN_B) THEN ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_TAC THEN
  MP_TAC(ISPECL [`p:form`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`v:num->A`]
    BVALF_NOT) THEN ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_TAC THEN
  MATCH_MP_TAC ECOMPL_BOT_TOP THEN ASM_REWRITE_TAC[]);;

(* [[p&&q]]_v = top  <=>  [[p]]_v = top and [[q]]_v = top.               *)
let BVALF_AND_TOP = prove
 (`!p q D (E:A->A->bool) B leq v.
      model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
      valuation D v /\ (!i. bname D E B (v i))
      ==> (etop D E B leq (bvalf D E B leq v (p && q)) <=>
           etop D E B leq (bvalf D E B leq v p) /\
           etop D E B leq (bvalf D E B leq v q))`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[And_DEF] THEN
  MP_TAC(ISPECL
         [`p --> Not q`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`v:num->A`]
         BVALF_NOT_TOP) THEN ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  MP_TAC(ISPECL
         [`p:form`;`Not q`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`v:num->A`]
         BVALF_IMP_BOT) THEN ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  MP_TAC(ISPECL [`q:form`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`v:num->A`]
    BVALF_NOT_BOT) THEN ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]));;

(* bvalf(p||q) is the Boolean join of bvalf(p) and bvalf(q).             *)
let BVALF_OR = prove
 (`!p q D (E:A->A->bool) B leq v.
      model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
      valuation D v /\ (!i. bname D E B (v i))
      ==> ejoin D E B leq (bvalf D E B leq v p) (bvalf D E B leq v q)
                          (bvalf D E B leq v (p || q))`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[Or_DEF] THEN
  SUBGOAL_THEN `ebalg D (E:A->A->bool) B leq` ASSUME_TAC THENL
   [FIRST_ASSUM(ACCEPT_TAC o CONJUNCT1 o REWRITE_RULE[ecba]); ALL_TAC] THEN
  MP_TAC(ISPECL [`p:form`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`v:num->A`]
    BVALF_SPEC) THEN ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  STRIP_TAC THEN
  MP_TAC(ISPECL [`p:form`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`v:num->A`]
    BVALF_IN_B) THEN ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_TAC THEN
  MP_TAC(ISPECL [`p:form`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`v:num->A`]
    BVALF_NOT) THEN ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_TAC THEN
  MP_TAC(ISPECL
         [`Not p`;`q:form`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`v:num->A`]
         BVALF_IMP) THEN ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  REWRITE_TAC[ebimp] THEN
  DISCH_THEN(X_CHOOSE_THEN `c:A` STRIP_ASSUME_TAC) THEN
  SUBGOAL_THEN `c:A = bvalf D (E:A->A->bool) B leq v p` SUBST_ALL_TAC THENL
   [MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
      `bvalf D (E:A->A->bool) B leq v p`;
      `bvalf D (E:A->A->bool) B leq v (Not p)`;`c:A`] ECOMPL_INVOL) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  ASM_REWRITE_TAC[]);;

(* ===================================================================== *)
(* F5 derived-form characterizations: True, <->, bounded !!-.            *)
(*   The remaining shapes ZF-axiom bodies are built from.                *)
(* --------------------------------------------------------------------- *)
(* [[True]]_v = top.                                                     *)

(* [[p<->q]]_v = top  <=>  [[p]]_v = [[q]]_v.                            *)
let BVALF_IFF_TOP = prove
 (`!p q D (E:A->A->bool) B leq v.
      model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
      valuation D v /\ (!i. bname D E B (v i))
      ==> (etop D E B leq (bvalf D E B leq v (p <-> q)) <=>
           bvalf D E B leq v p = bvalf D E B leq v q)`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[Iff_DEF] THEN
  SUBGOAL_THEN `eporder D (E:A->A->bool) B leq` ASSUME_TAC THENL
   [ASM_MESON_TAC[EBALG_IMP_PORDER; ECBA_IMP_BALG]; ALL_TAC] THEN
  MP_TAC(ISPECL [`p --> q`;`q --> p`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
                 `v:num->A`] BVALF_AND_TOP) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  MP_TAC(ISPECL [`p:form`;`q:form`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
                 `v:num->A`] BVALF_IMP_TOP) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  MP_TAC(ISPECL [`q:form`;`p:form`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
                 `v:num->A`] BVALF_IMP_TOP) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  MP_TAC(ISPECL [`p:form`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`v:num->A`]
    BVALF_SPEC) THEN ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  STRIP_TAC THEN
  MP_TAC(ISPECL [`q:form`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`v:num->A`]
    BVALF_SPEC) THEN ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  STRIP_TAC THEN
  MP_TAC(ISPECL [`p:form`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`v:num->A`]
    BVALF_IN_B) THEN ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_TAC THEN
  MP_TAC(ISPECL [`q:form`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`v:num->A`]
    BVALF_IN_B) THEN ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_TAC THEN
  EQ_TAC THENL
   [STRIP_TAC THEN
    MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
      `bvalf D (E:A->A->bool) B leq v p`;`bvalf D (E:A->A->bool) B leq v q`]
      EPORDER_ANTISYM) THEN ASM_REWRITE_TAC[];
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
      `bvalf D (E:A->A->bool) B leq v q`] EPORDER_REFL) THEN
    ASM_REWRITE_TAC[]]);;

(* [[!!- x y p]]_v = top  <=>  for every bname a, [[a IN y]] <= [[p(a)]]. *)
let BVALF_FORALLMEM_TOP = prove
 (`!x y p D (E:A->A->bool) B leq v.
      model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
      valuation D v /\ (!i. bname D E B (v i))
      ==> (etop D E B leq (bvalf D E B leq v (!!- x y p)) <=>
           (!a. a IN D /\ bname D E B a
                ==> erel D E leq
                      (bvalf D E B leq ((x |-> a) v) (x %% y))
                      (bvalf D E B leq ((x |-> a) v) p)))`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[Forallmem_DEF] THEN
  MP_TAC(ISPECL [`x:num`; `(x %% y) --> p`; `D:A->bool`;`E:A->A->bool`;`B:A`;
                 `leq:A`;`v:num->A`] BVALF_ALL_TOP) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  MATCH_MP_TAC FORALL_IMP_CONG THEN
  X_GEN_TAC `a:A` THEN STRIP_TAC THEN
  SUBGOAL_THEN `valuation D ((x |-> (a:A)) v)` ASSUME_TAC THENL
   [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `!i. bname D E B (((x |-> (a:A)) (v:num->A)) i)`
    ASSUME_TAC THENL
   [MATCH_MP_TAC BNAMEVAL_VALMOD THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MATCH_MP_TAC BVALF_IMP_TOP THEN ASM_REWRITE_TAC[]);;

(* ===================================================================== *)
(* F5 Bell-equation phase, step 1: the IN-value as a supremum.           *)
(*   [[u IN v]] = SUP over y in dom v of (v(y) MEET [[u=y]]).  Exposed    *)
(*   as order facts: each combiner <= the value (EBVIN_UB) and the value  *)
(*   is the least upper bound (EBVIN_LEAST); plus the bridge from the      *)
(*   tower value ebv_in to the combiner-SUP ebvin at a common stage.      *)
(* --------------------------------------------------------------------- *)
(* each combiner v(y) MEET t(<u,y>) is below the IN-value.               *)
let EBVIN_UB = prove
 (`!D (E:A->A->bool) B leq t v u z c.
      ebvin D E B leq t v u z /\ bvcomb D E B leq t v u c
      ==> erel D E leq c z`,
  REPEAT GEN_TAC THEN REWRITE_TAC[ebvin] THEN STRIP_TAC THEN
  SUBGOAL_THEN `(c:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[BVCOMB_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) c S` ASSUME_TAC THENL
   [FIRST_X_ASSUM(MP_TAC o SPEC `c:A` o CONJUNCT2 o
                  REWRITE_RULE[ebvinset]) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`S:A`;`z:A`;`c:A`]
    ELUB_UB) THEN ASM_REWRITE_TAC[]);;

(* the IN-value is the least upper bound of the combiners.               *)
let EBVIN_LEAST = prove
 (`!D (E:A->A->bool) B leq t v u z w.
      ebvin D E B leq t v u z /\ w IN D /\ E w B /\
      (!c. bvcomb D E B leq t v u c ==> erel D E leq c w)
      ==> erel D E leq z w`,
  REPEAT GEN_TAC THEN REWRITE_TAC[ebvin] THEN STRIP_TAC THEN
  SUBGOAL_THEN `eubound D (E:A->A->bool) B leq S w` ASSUME_TAC THENL
   [REWRITE_TAC[eubound] THEN ASM_REWRITE_TAC[] THEN
    X_GEN_TAC `x:A` THEN STRIP_TAC THEN
    SUBGOAL_THEN `bvcomb D (E:A->A->bool) B leq t v u x` ASSUME_TAC THENL
     [FIRST_X_ASSUM(MP_TAC o SPEC `x:A` o CONJUNCT2 o
                    REWRITE_RULE[ebvinset]) THEN
      ASM_REWRITE_TAC[]; ALL_TAC] THEN
    FIRST_X_ASSUM MATCH_MP_TAC THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`S:A`;`z:A`;`w:A`]
    ELUB_LEAST) THEN ASM_REWRITE_TAC[]);;

(* ===================================================================== *)
(* F5 Bell-equation phase, step 2: the two-sided membership bounds.      *)
(*   At a common B-name stage, [[u IN v]] (= the combiner-SUP ebvin) is   *)
(*   bounded below by each v(y) MEET [[u=y]] (EBV_IN_GE_TERM) and above   *)
(*   by any common upper bound of those terms (EBV_IN_LE).  These consume *)
(*   the stage witnesses (w IN D etc.) that axiom proofs already build    *)
(*   via BNAME_DIRECTED + EBNSTAGE_EXISTS -- so the value IN D / w IN D    *)
(*   extraction issue is sidestepped.  The table entry sEQ(<u,y>) is      *)
(*   identified with [[u=y]] via STAGE_DOM_CLOSED + EBV_EQ_TABLE_ENTRY.   *)
(* --------------------------------------------------------------------- *)
(* v(y) MEET [[u=y]] <= [[u IN v]]  for y in dom v.                       *)
let EBV_IN_GE_TERM = prove
 (`!D (E:A->A->bool) B leq a w sIN sEQ u v z y qy ey c.
      model D E ZF_AX /\ ecba D E B leq /\ B IN D /\
      a IN D /\ eordinal D E a /\ ebnstage D E B a w /\ w IN D /\
      u IN D /\ v IN D /\ E u w /\ E v w /\ ebvatt D E B leq w sIN sEQ /\
      ebvin D E B leq sEQ v u z /\
      y IN D /\ qy IN D /\ ey IN D /\ c IN D /\
      eapply D E v y qy /\ ebv_eq D E B leq u y ey /\ emeet D E B leq qy ey c
      ==> erel D E leq c z`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `(E:A->A->bool) y w` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`B:A`;`a:A`;`w:A`;`v:A`;`y:A`;
                  `qy:A`] STAGE_DOM_CLOSED) THEN ASM_REWRITE_TAC[];
      ALL_TAC] THEN
  SUBGOAL_THEN `?pr:A. eopair D E u y pr` (X_CHOOSE_TAC `pr:A`) THENL
   [MATCH_MP_TAC EOPAIR_EXISTS THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(pr:A) IN D` ASSUME_TAC THENL
   [FIRST_ASSUM(ACCEPT_TAC o MATCH_MP EOPAIR_IN); ALL_TAC] THEN
  MP_TAC(ISPECL
         [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`w:A`;`sIN:A`;`sEQ:A`;
          `u:A`;`y:A`;`pr:A`] EBVATT_VAL) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(CONJUNCTS_THEN2 (K ALL_TAC)
    (X_CHOOSE_THEN `ve:A` STRIP_ASSUME_TAC)) THEN
  SUBGOAL_THEN `ebv_eq D (E:A->A->bool) B leq u y ve` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`a:A`;`w:A`;
      `sIN:A`;`sEQ:A`;`u:A`;`y:A`;`pr:A`;`ve:A`] EBV_EQ_TABLE_ENTRY) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `ey:A = ve` SUBST_ALL_TAC THENL
   [MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`u:A`;`y:A`;`ey:A`;
      `ve:A`] EBV_EQ_UNIQUE) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `bvcomb D (E:A->A->bool) B leq sEQ v u c` ASSUME_TAC THENL
   [REWRITE_TAC[bvcomb] THEN
    MAP_EVERY EXISTS_TAC [`y:A`;`qy:A`;`ve:A`;`pr:A`] THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`sEQ:A`;`v:A`;`u:A`;
    `z:A`;`c:A`] EBVIN_UB) THEN ASM_REWRITE_TAC[]);;

(* [[u IN v]] <= w0  when every v(y) MEET [[u=y]] <= w0.                  *)
let EBV_IN_LE = prove
 (`!D (E:A->A->bool) B leq a w sIN sEQ u v z w0.
      model D E ZF_AX /\ ecba D E B leq /\ B IN D /\
      a IN D /\ eordinal D E a /\ ebnstage D E B a w /\ w IN D /\
      u IN D /\ v IN D /\ E u w /\ E v w /\ ebvatt D E B leq w sIN sEQ /\
      ebvin D E B leq sEQ v u z /\ w0 IN D /\ E w0 B /\
      (!y qy ey c.
          y IN D /\ qy IN D /\ ey IN D /\ c IN D /\
          eapply D E v y qy /\ ebv_eq D E B leq u y ey /\
            emeet D E B leq qy ey c
          ==> erel D E leq c w0)
      ==> erel D E leq z w0`,
  REPEAT STRIP_TAC THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`sEQ:A`;`v:A`;`u:A`;
    `z:A`;`w0:A`] EBVIN_LEAST) THEN ASM_REWRITE_TAC[] THEN
  DISCH_THEN MATCH_MP_TAC THEN
  X_GEN_TAC `c:A` THEN
  REWRITE_TAC[bvcomb] THEN
  DISCH_THEN(X_CHOOSE_THEN `y:A` (X_CHOOSE_THEN `qy:A` (X_CHOOSE_THEN `my:A`
    (X_CHOOSE_THEN `pr:A` STRIP_ASSUME_TAC)))) THEN
  SUBGOAL_THEN `(E:A->A->bool) y w` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`B:A`;`a:A`;`w:A`;`v:A`;`y:A`;
                  `qy:A`] STAGE_DOM_CLOSED) THEN ASM_REWRITE_TAC[];
      ALL_TAC] THEN
  SUBGOAL_THEN `ebv_eq D (E:A->A->bool) B leq u y my` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`a:A`;`w:A`;
      `sIN:A`;`sEQ:A`;`u:A`;`y:A`;`pr:A`;`my:A`] EBV_EQ_TABLE_ENTRY) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(c:A) IN D` ASSUME_TAC THENL
   [FIRST_ASSUM(ACCEPT_TAC o CONJUNCT1 o MATCH_MP EMEET_IN); ALL_TAC] THEN
  FIRST_X_ASSUM(MP_TAC o SPECL [`y:A`;`qy:A`;`my:A`;`c:A`]) THEN
  ASM_REWRITE_TAC[]);;

(* ===================================================================== *)
(* F5 Bell-equation phase, step 3: the =-value as a meet of two infima.  *)
(*   [[u=v]] = (INF_{x in dom u} (u(x) => [[x in v]]))                    *)
(*             MEET (INF_{y in dom v} (v(y) => [[y in u]])).              *)
(*   Combiner-level order facts: [[u=v]] is below each combiner (both    *)
(*   directions, EBVEQ_LB / EBVEQ_LB_R) and is the greatest lower bound   *)
(*   (EBVEQ_GLB) -- the latter is what proves  X <= [[u=v]]  (the shape   *)
(*   extensionality needs).                                              *)
(* --------------------------------------------------------------------- *)
(* [[u=v]] <= (u(x) => s(<x,v>))  for each u->v combiner.                 *)
let EBVEQ_LB = prove
 (`!D (E:A->A->bool) B leq s u v z c.
      ecba D E B leq /\ ebveq D E B leq s u v z /\ bveqcomb D E B leq s u v c
      ==> erel D E leq z c`,
  REPEAT GEN_TAC THEN REWRITE_TAC[ebveq] THEN
  INTRO_TAC "cba (@SL SR gL gR. csL csR glL glR mt) h" THEN
  SUBGOAL_THEN `eporder D (E:A->A->bool) B leq` ASSUME_TAC THENL
   [FIRST_ASSUM(ACCEPT_TAC o MATCH_MP ECBA_IMP_PORDER); ALL_TAC] THEN
  SUBGOAL_THEN `(c:A) IN D /\ (E:A->A->bool) c B` STRIP_ASSUME_TAC THENL
   [FIRST_ASSUM(ACCEPT_TAC o MATCH_MP BVEQCOMB_IN); ALL_TAC] THEN
  SUBGOAL_THEN `(z:A) IN D /\ (E:A->A->bool) z B` STRIP_ASSUME_TAC THENL
   [USE_THEN "mt" (ACCEPT_TAC o MATCH_MP EMEET_IN); ALL_TAC] THEN
  SUBGOAL_THEN `(gL:A) IN D /\ (E:A->A->bool) gL B` STRIP_ASSUME_TAC THENL
   [USE_THEN "glL" (ACCEPT_TAC o MATCH_MP EGLB_IN); ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) c SL` ASSUME_TAC THENL
   [USE_THEN "csL"
    (MP_TAC o SPEC `c:A` o CONJUNCT2 o REWRITE_RULE[bveqcombset]) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `erel D E leq (gL:A) c` ASSUME_TAC THENL
   [MP_TAC(ISPECL
           [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`SL:A`;`gL:A`;`c:A`]
           EGLB_LB) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `erel D E leq (z:A) gL` ASSUME_TAC THENL
   [USE_THEN "mt" (fun th -> ACCEPT_TAC(CONJUNCT1(MATCH_MP EMEET_LE th)));
    ALL_TAC] THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`z:A`;`gL:A`;`c:A`]
    EPORDER_TRANS) THEN ASM_REWRITE_TAC[]);;

(* [[u=v]] <= (v(y) => s(<y,u>))  for each v->u combiner.                 *)
let EBVEQ_LB_R = prove
 (`!D (E:A->A->bool) B leq s u v z c.
      ecba D E B leq /\ ebveq D E B leq s u v z /\ bveqcomb D E B leq s v u c
      ==> erel D E leq z c`,
  REPEAT GEN_TAC THEN REWRITE_TAC[ebveq] THEN
  INTRO_TAC "cba (@SL SR gL gR. csL csR glL glR mt) h" THEN
  SUBGOAL_THEN `eporder D (E:A->A->bool) B leq` ASSUME_TAC THENL
   [FIRST_ASSUM(ACCEPT_TAC o MATCH_MP ECBA_IMP_PORDER); ALL_TAC] THEN
  SUBGOAL_THEN `(c:A) IN D /\ (E:A->A->bool) c B` STRIP_ASSUME_TAC THENL
   [FIRST_ASSUM(ACCEPT_TAC o MATCH_MP BVEQCOMB_IN); ALL_TAC] THEN
  SUBGOAL_THEN `(z:A) IN D /\ (E:A->A->bool) z B` STRIP_ASSUME_TAC THENL
   [USE_THEN "mt" (ACCEPT_TAC o MATCH_MP EMEET_IN); ALL_TAC] THEN
  SUBGOAL_THEN `(gR:A) IN D /\ (E:A->A->bool) gR B` STRIP_ASSUME_TAC THENL
   [USE_THEN "glR" (ACCEPT_TAC o MATCH_MP EGLB_IN); ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) c SR` ASSUME_TAC THENL
   [USE_THEN "csR"
    (MP_TAC o SPEC `c:A` o CONJUNCT2 o REWRITE_RULE[bveqcombset]) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `erel D E leq (gR:A) c` ASSUME_TAC THENL
   [MP_TAC(ISPECL
           [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`SR:A`;`gR:A`;`c:A`]
           EGLB_LB) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `erel D E leq (z:A) gR` ASSUME_TAC THENL
   [USE_THEN "mt" (fun th -> ACCEPT_TAC(CONJUNCT2(MATCH_MP EMEET_LE th)));
    ALL_TAC] THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`z:A`;`gR:A`;`c:A`]
    EPORDER_TRANS) THEN ASM_REWRITE_TAC[]);;

(* [[u=v]] is the greatest lower bound of all combiners (both directions).*)
let EBVEQ_GLB = prove
 (`!D (E:A->A->bool) B leq s u v z w0.
      ecba D E B leq /\ ebveq D E B leq s u v z /\ w0 IN D /\ E w0 B /\
      (!c. bveqcomb D E B leq s u v c ==> erel D E leq w0 c) /\
      (!c. bveqcomb D E B leq s v u c ==> erel D E leq w0 c)
      ==> erel D E leq w0 z`,
  REPEAT GEN_TAC THEN REWRITE_TAC[ebveq] THEN
  INTRO_TAC "cba (@SL SR gL gR. csL csR glL glR mt) w0D w0B hu hv" THEN
  SUBGOAL_THEN `elbound D (E:A->A->bool) B leq SL w0` ASSUME_TAC THENL
   [REWRITE_TAC[elbound] THEN ASM_REWRITE_TAC[] THEN
    X_GEN_TAC `x:A` THEN STRIP_TAC THEN
    SUBGOAL_THEN `bveqcomb D (E:A->A->bool) B leq s u v x` ASSUME_TAC THENL
     [USE_THEN "csL"(MP_TAC o SPEC `x:A` o CONJUNCT2 o
                     REWRITE_RULE[bveqcombset]) THEN
      ASM_REWRITE_TAC[]; ALL_TAC] THEN
    USE_THEN "hu" MATCH_MP_TAC THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `erel D E leq w0 (gL:A)` ASSUME_TAC THENL
   [MP_TAC(ISPECL
           [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`SL:A`;`gL:A`;`w0:A`]
           EGLB_GREATEST) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `elbound D (E:A->A->bool) B leq SR w0` ASSUME_TAC THENL
   [REWRITE_TAC[elbound] THEN ASM_REWRITE_TAC[] THEN
    X_GEN_TAC `x:A` THEN STRIP_TAC THEN
    SUBGOAL_THEN `bveqcomb D (E:A->A->bool) B leq s v u x` ASSUME_TAC THENL
     [USE_THEN "csR"(MP_TAC o SPEC `x:A` o CONJUNCT2 o
                     REWRITE_RULE[bveqcombset]) THEN
      ASM_REWRITE_TAC[]; ALL_TAC] THEN
    USE_THEN "hv" MATCH_MP_TAC THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `erel D E leq w0 (gR:A)` ASSUME_TAC THENL
   [MP_TAC(ISPECL
           [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`SR:A`;`gR:A`;`w0:A`]
           EGLB_GREATEST) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MP_TAC(ISPECL
         [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`gL:A`;`gR:A`;`z:A`;`w0:A`]
         EMEET_GREATEST) THEN ASM_REWRITE_TAC[]);;

(* ===================================================================== *)
(* F5 Bell-equation phase, step 4: stage-level =-value greatest lower    *)
(*   bound -- the direct EXTENSIONALITY tool.  If w0 is below every       *)
(*   u(x) => [[x in v]] (x in dom u) and every v(y) => [[y in u]]         *)
(*   (y in dom v), then w0 <= [[u=v]].                                    *)
(* --------------------------------------------------------------------- *)
let EBV_EQ_GLB_STAGE = prove
 (`!D (E:A->A->bool) B leq a w sIN sEQ u v z w0.
      model D E ZF_AX /\ ecba D E B leq /\ B IN D /\
      a IN D /\ eordinal D E a /\ ebnstage D E B a w /\ w IN D /\
      u IN D /\ v IN D /\ E u w /\ E v w /\ ebvatt D E B leq w sIN sEQ /\
      ebveq D E B leq sIN u v z /\ w0 IN D /\ E w0 B /\
      (!x qx exv c.
          x IN D /\ qx IN D /\ exv IN D /\ c IN D /\
          eapply D E u x qx /\ ebv_in D E B leq x v exv /\
            ebimp D E B leq qx exv c
          ==> erel D E leq w0 c) /\
      (!y qy eyu c.
          y IN D /\ qy IN D /\ eyu IN D /\ c IN D /\
          eapply D E v y qy /\ ebv_in D E B leq y u eyu /\
            ebimp D E B leq qy eyu c
          ==> erel D E leq w0 c)
      ==> erel D E leq w0 z`,
  REPEAT GEN_TAC THEN INTRO_TAC "zf cba BD aD orda h wD uD vD uw vw h2 \
                                 h3 w0D w0B hu hv" THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`sIN:A`;`u:A`;`v:A`;
    `z:A`;`w0:A`] EBVEQ_GLB) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
     [
      X_GEN_TAC `c:A` THEN REWRITE_TAC[bveqcomb] THEN
      DISCH_THEN(X_CHOOSE_THEN `x0:A`
                 (X_CHOOSE_THEN `qx0:A` (X_CHOOSE_THEN `mx0:A`
                                         (X_CHOOSE_THEN `pr0:A`
                                          STRIP_ASSUME_TAC)))) THEN
      SUBGOAL_THEN `(E:A->A->bool) x0 w` ASSUME_TAC THENL
       [MATCH_MP_TAC(ISPECL
                     [`D:A->bool`;`E:A->A->bool`;`B:A`;`a:A`;`w:A`;`u:A`;
                      `x0:A`;`qx0:A`] STAGE_DOM_CLOSED) THEN ASM_REWRITE_TAC[];
                 ALL_TAC] THEN
      SUBGOAL_THEN `ebv_in D (E:A->A->bool) B leq x0 v mx0` ASSUME_TAC THENL
       [MATCH_MP_TAC(ISPECL
                     [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`a:A`;`w:A`;
                      `sIN:A`;`sEQ:A`;`x0:A`;`v:A`;`pr0:A`;`mx0:A`]
                       EBV_IN_TABLE_ENTRY) THEN
        ASM_REWRITE_TAC[]; ALL_TAC] THEN
      SUBGOAL_THEN `(c:A) IN D` ASSUME_TAC THENL
       [FIRST_ASSUM(ACCEPT_TAC o CONJUNCT1 o MATCH_MP EBIMP_IN); ALL_TAC] THEN
      USE_THEN "hu" MATCH_MP_TAC THEN
      MAP_EVERY EXISTS_TAC [`x0:A`;`qx0:A`;`mx0:A`] THEN ASM_REWRITE_TAC[];
      X_GEN_TAC `c:A` THEN REWRITE_TAC[bveqcomb] THEN
      DISCH_THEN(X_CHOOSE_THEN `y0:A`
                 (X_CHOOSE_THEN `qy0:A` (X_CHOOSE_THEN `my0:A`
                                         (X_CHOOSE_THEN `pr1:A`
                                          STRIP_ASSUME_TAC)))) THEN
      SUBGOAL_THEN `(E:A->A->bool) y0 w` ASSUME_TAC THENL
       [MATCH_MP_TAC(ISPECL
                     [`D:A->bool`;`E:A->A->bool`;`B:A`;`a:A`;`w:A`;`v:A`;
                      `y0:A`;`qy0:A`] STAGE_DOM_CLOSED) THEN ASM_REWRITE_TAC[];
                 ALL_TAC] THEN
      SUBGOAL_THEN `ebv_in D (E:A->A->bool) B leq y0 u my0` ASSUME_TAC THENL
       [MATCH_MP_TAC(ISPECL
                     [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`a:A`;`w:A`;
                      `sIN:A`;`sEQ:A`;`y0:A`;`u:A`;`pr1:A`;`my0:A`]
                       EBV_IN_TABLE_ENTRY) THEN
        ASM_REWRITE_TAC[]; ALL_TAC] THEN
      SUBGOAL_THEN `(c:A) IN D` ASSUME_TAC THENL
       [FIRST_ASSUM(ACCEPT_TAC o CONJUNCT1 o MATCH_MP EBIMP_IN); ALL_TAC] THEN
      USE_THEN "hv" MATCH_MP_TAC THEN
      MAP_EVERY EXISTS_TAC [`y0:A`;`qy0:A`;`my0:A`] THEN ASM_REWRITE_TAC[]];
    DISCH_THEN ACCEPT_TAC]);;

(* ===================================================================== *)
(* F5 connective layer (part C): conjunction value bounds.              *)
(*   Completes the connective <= layer: bvalf(p&&q) is below each        *)
(*   conjunct.  With p&&q = Not(p-->Not q), the argument needs only       *)
(*   complement antitonicity + involution (NOT full De Morgan).  These    *)
(*   give [[p<->q]] <= [[p-->q]] / [[q-->p]] -- the shape extensionality   *)
(*   consumes ([[z in x <-> z in y]] <= ([[z in x]] => [[z in y]])).      *)
(* --------------------------------------------------------------------- *)
(* complement is order-reversing:  x <= y  =>  ~y <= ~x.                  *)
let ECOMPL_ANTITONE = prove
 (`!D (E:A->A->bool) p leq x y cx cy.
      ebalg D E p leq /\ x IN D /\ y IN D /\ E x p /\ E y p /\
      ecompl D E p leq x cx /\ ecompl D E p leq y cy /\ erel D E leq x y
      ==> erel D E leq cy cx`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `eporder D (E:A->A->bool) p leq` ASSUME_TAC THENL
   [ASM_MESON_TAC[EBALG_IMP_PORDER]; ALL_TAC] THEN
  SUBGOAL_THEN `(cx:A) IN D /\ (E:A->A->bool) cx p` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[ECOMPL_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `(cy:A) IN D /\ (E:A->A->bool) cy p` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[ECOMPL_IN]; ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`p:A`;`leq:A`] EBALG_BOT) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `bot:A`) THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`p:A`;`leq:A`] EBALG_TOP) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `top:A`) THEN
  SUBGOAL_THEN
   `(bot:A) IN D /\ (E:A->A->bool) bot p /\ (top:A) IN D /\ E top p`
  STRIP_ASSUME_TAC THENL [ASM_MESON_TAC[EBOT_IN; ETOP_IN]; ALL_TAC] THEN
  MP_TAC(SPECL
         [`D:A->bool`;`E:A->A->bool`;`p:A`;`leq:A`;`x:A`;`cx:A`;
          `bot:A`;`top:A`]
         ECOMPL_MEET_JOIN) THEN ASM_REWRITE_TAC[] THEN STRIP_TAC THEN
  MP_TAC(SPECL
         [`D:A->bool`;`E:A->A->bool`;`p:A`;`leq:A`;`y:A`;`cy:A`;
          `bot:A`;`top:A`]
         ECOMPL_MEET_JOIN) THEN ASM_REWRITE_TAC[] THEN STRIP_TAC THEN
  SUBGOAL_THEN `emeet D (E:A->A->bool) p leq x cy bot` ASSUME_TAC THENL
   [REWRITE_TAC[emeet] THEN ASM_REWRITE_TAC[] THEN REPEAT CONJ_TAC THENL
     [MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`p:A`;`leq:A`;`bot:A`;`x:A`]
        EBOT_LE) THEN ASM_REWRITE_TAC[];
      MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`p:A`;`leq:A`;`bot:A`;`cy:A`]
        EBOT_LE) THEN ASM_REWRITE_TAC[];
      X_GEN_TAC `w:A` THEN STRIP_TAC THEN
      SUBGOAL_THEN `erel D E leq (w:A) y` ASSUME_TAC THENL
       [MP_TAC(SPECL
               [`D:A->bool`;`E:A->A->bool`;`p:A`;`leq:A`;`w:A`;`x:A`;`y:A`]
               EPORDER_TRANS) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
      MP_TAC(SPECL
             [`D:A->bool`;`E:A->A->bool`;`p:A`;`leq:A`;`y:A`;`cy:A`;
              `bot:A`;`w:A`]
             EMEET_GREATEST) THEN ASM_REWRITE_TAC[]];
    ALL_TAC] THEN
  SUBGOAL_THEN `emeet D (E:A->A->bool) p leq cy cx cy` ASSUME_TAC THENL
   [MATCH_MP_TAC ECOMPL_ABSORB THEN
    MAP_EVERY EXISTS_TAC [`x:A`;`bot:A`;`top:A`] THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  FIRST_ASSUM(ACCEPT_TAC o CONJUNCT2 o MATCH_MP EMEET_LE));;

(* bvalf(p&&q) <= bvalf(p).                                              *)
let BVALF_AND_LE_L = prove
 (`!p q D (E:A->A->bool) B leq v.
      model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
      valuation D v /\ (!i. bname D E B (v i))
      ==> erel D E leq (bvalf D E B leq v (p && q)) (bvalf D E B leq v p)`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[And_DEF] THEN
  SUBGOAL_THEN `ebalg D (E:A->A->bool) B leq` ASSUME_TAC THENL
   [FIRST_ASSUM(ACCEPT_TAC o CONJUNCT1 o REWRITE_RULE[ecba]); ALL_TAC] THEN
  MP_TAC(ISPECL [`p:form`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`v:num->A`]
    BVALF_SPEC) THEN ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  STRIP_TAC THEN
  MP_TAC(ISPECL [`p:form`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`v:num->A`]
    BVALF_IN_B) THEN ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_TAC THEN
  MP_TAC(ISPECL [`Not p`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`v:num->A`]
    BVALF_SPEC) THEN ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  STRIP_TAC THEN
  MP_TAC(ISPECL [`Not p`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`v:num->A`]
    BVALF_IN_B) THEN ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_TAC THEN
  MP_TAC(ISPECL
         [`p --> Not q`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`v:num->A`]
         BVALF_SPEC) THEN ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  STRIP_TAC THEN
  MP_TAC(ISPECL
         [`p --> Not q`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`v:num->A`]
         BVALF_IN_B) THEN ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_TAC THEN
  (* ecompl (bvalf p) (bvalf (Not p)) *)
  MP_TAC(ISPECL [`p:form`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`v:num->A`]
    BVALF_NOT) THEN ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_TAC THEN
  (* ecompl (bvalf (p-->Not q)) (bvalf (Not(p-->Not q))) *)
  MP_TAC(ISPECL
         [`p --> Not q`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`v:num->A`]
         BVALF_NOT) THEN ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_TAC THEN
  (* ebimp (bvalf p) (bvalf (Not q)) (bvalf (p-->Not q)) *)
  MP_TAC(ISPECL
         [`p:form`;`Not q`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`v:num->A`]
         BVALF_IMP) THEN ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  REWRITE_TAC[ebimp] THEN
  DISCH_THEN(X_CHOOSE_THEN `c:A` STRIP_ASSUME_TAC) THEN
  (* c = bvalf(Not p) via ECOMPL_UNIQUE *)
  SUBGOAL_THEN `c:A = bvalf D (E:A->A->bool) B leq v (Not p)`
    SUBST_ALL_TAC THENL
   [MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
      `bvalf D (E:A->A->bool) B leq v p`;`c:A`;
      `bvalf D (E:A->A->bool) B leq v (Not p)`] ECOMPL_UNIQUE) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* erel (bvalf(Not p)) (bvalf(p-->Not q)) via EJOIN_GE *)
  SUBGOAL_THEN
   `erel D E leq (bvalf D (E:A->A->bool) B leq v (Not p))
                 (bvalf D E B leq v (p --> Not q))` ASSUME_TAC THENL
   [FIRST_ASSUM(ACCEPT_TAC o CONJUNCT1 o MATCH_MP EJOIN_GE); ALL_TAC] THEN
  (* ecompl (bvalf(Not p)) (bvalf p) via ECOMPL_SYM *)
  SUBGOAL_THEN
   `ecompl D (E:A->A->bool) B leq (bvalf D E B leq v (Not p))
    (bvalf D E B leq v p)`
  ASSUME_TAC THENL
   [MATCH_MP_TAC ECOMPL_SYM THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
    `bvalf D (E:A->A->bool) B leq v (Not p)`;
    `bvalf D (E:A->A->bool) B leq v (p --> Not q)`;
    `bvalf D (E:A->A->bool) B leq v p`;
    `bvalf D (E:A->A->bool) B leq v (Not(p --> Not q))`] ECOMPL_ANTITONE) THEN
  ASM_REWRITE_TAC[]);;

(* bvalf(p&&q) <= bvalf(q).                                              *)
let BVALF_AND_LE_R = prove
 (`!p q D (E:A->A->bool) B leq v.
      model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
      valuation D v /\ (!i. bname D E B (v i))
      ==> erel D E leq (bvalf D E B leq v (p && q)) (bvalf D E B leq v q)`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[And_DEF] THEN
  SUBGOAL_THEN `ebalg D (E:A->A->bool) B leq` ASSUME_TAC THENL
   [FIRST_ASSUM(ACCEPT_TAC o CONJUNCT1 o REWRITE_RULE[ecba]); ALL_TAC] THEN
  MAP_EVERY (fun t ->
     MP_TAC(ISPECL [t;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`v:num->A`]
       BVALF_SPEC) THEN ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
     STRIP_TAC THEN
     MP_TAC(ISPECL [t;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`v:num->A`]
       BVALF_IN_B) THEN ANTS_TAC THENL
     [ASM_REWRITE_TAC[]; ALL_TAC] THEN DISCH_TAC)
   [`p:form`; `Not p`; `q:form`; `Not q`; `p --> Not q`] THEN
  MP_TAC(ISPECL [`p:form`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`v:num->A`]
    BVALF_NOT) THEN ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_TAC THEN
  MP_TAC(ISPECL [`q:form`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`v:num->A`]
    BVALF_NOT) THEN ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_TAC THEN
  MP_TAC(ISPECL
         [`p --> Not q`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`v:num->A`]
         BVALF_NOT) THEN ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_TAC THEN
  MP_TAC(ISPECL
         [`p:form`;`Not q`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`v:num->A`]
         BVALF_IMP) THEN ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  REWRITE_TAC[ebimp] THEN
  DISCH_THEN(X_CHOOSE_THEN `c:A` STRIP_ASSUME_TAC) THEN
  SUBGOAL_THEN `c:A = bvalf D (E:A->A->bool) B leq v (Not p)`
    SUBST_ALL_TAC THENL
   [MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
      `bvalf D (E:A->A->bool) B leq v p`;`c:A`;
      `bvalf D (E:A->A->bool) B leq v (Not p)`] ECOMPL_UNIQUE) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN
   `erel D E leq (bvalf D (E:A->A->bool) B leq v (Not q))
                 (bvalf D E B leq v (p --> Not q))` ASSUME_TAC THENL
   [FIRST_ASSUM(ACCEPT_TAC o CONJUNCT2 o MATCH_MP EJOIN_GE); ALL_TAC] THEN
  SUBGOAL_THEN
   `ecompl D (E:A->A->bool) B leq (bvalf D E B leq v (Not q))
    (bvalf D E B leq v q)`
  ASSUME_TAC THENL
   [MATCH_MP_TAC ECOMPL_SYM THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
    `bvalf D (E:A->A->bool) B leq v (Not q)`;
    `bvalf D (E:A->A->bool) B leq v (p --> Not q)`;
    `bvalf D (E:A->A->bool) B leq v q`;
    `bvalf D (E:A->A->bool) B leq v (Not(p --> Not q))`] ECOMPL_ANTITONE) THEN
  ASM_REWRITE_TAC[]);;

(* ===================================================================== *)
(* F5 assembly prerequisites: BA monotonicity + universal lower bound.   *)
(*   join is monotone; Boolean implication is ANTITONE in its antecedent  *)
(*   (p<=p' => (p'=>q)<=(p=>q)); and [[!!n p]]_v <= [[p]]_((n|->c)v) for    *)
(*   each bname c (the eglb lower bound).  These drive the EXTENSIONALITY  *)
(*   assembly (W0 <= [[c in a <-> c in b]] <= ([[c in a]]=>[[c in b]]) <=  *)
(*   (a(c)=>[[c in b]])).                                                  *)
(* --------------------------------------------------------------------- *)
(* a <= a'  =>  a \/ b <= a' \/ b.                                        *)
let EJOIN_MONO = prove
 (`!D (E:A->A->bool) p leq a a' b j j'.
      eporder D E p leq /\ a IN D /\ a' IN D /\ b IN D /\
      E a p /\ E a' p /\ E b p /\
      ejoin D E p leq a b j /\ ejoin D E p leq a' b j' /\ erel D E leq a a'
      ==> erel D E leq j j'`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `(j':A) IN D /\ (E:A->A->bool) j' p` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[EJOIN_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `erel D E leq (a':A) j' /\ erel D E leq (b:A) j'`
  STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[EJOIN_GE]; ALL_TAC] THEN
  SUBGOAL_THEN `erel D E leq (a:A) j'` ASSUME_TAC THENL
   [MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`p:A`;`leq:A`;`a:A`;`a':A`;`j':A`]
      EPORDER_TRANS) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MP_TAC(SPECL
         [`D:A->bool`;`E:A->A->bool`;`p:A`;`leq:A`;`a:A`;`b:A`;`j:A`;`j':A`]
         EJOIN_LEAST) THEN ASM_REWRITE_TAC[]);;

(* x <= y  =>  (y => q) <= (x => q)   (antitone in the antecedent).      *)
let EBIMP_ANT = prove
 (`!D (E:A->A->bool) pp leq x y q z z'.
      ebalg D E pp leq /\ x IN D /\ y IN D /\ q IN D /\
      E x pp /\ E y pp /\ E q pp /\
      ebimp D E pp leq x q z /\ ebimp D E pp leq y q z' /\ erel D E leq x y
      ==> erel D E leq z' z`,
  REPEAT GEN_TAC THEN REWRITE_TAC[ebimp] THEN STRIP_TAC THEN
  SUBGOAL_THEN `eporder D (E:A->A->bool) pp leq` ASSUME_TAC THENL
   [ASM_MESON_TAC[EBALG_IMP_PORDER]; ALL_TAC] THEN
  SUBGOAL_THEN `(c:A) IN D /\ (E:A->A->bool) c pp` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[ECOMPL_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `(c':A) IN D /\ (E:A->A->bool) c' pp` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[ECOMPL_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `erel D E leq (c':A) c` ASSUME_TAC THENL
   [MP_TAC(SPECL
           [`D:A->bool`;`E:A->A->bool`;`pp:A`;`leq:A`;`x:A`;`y:A`;`c:A`;`c':A`]
           ECOMPL_ANTITONE) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MP_TAC(SPECL
         [`D:A->bool`;`E:A->A->bool`;`pp:A`;`leq:A`;`c':A`;`c:A`;`q:A`;
          `z':A`;`z:A`]
         EJOIN_MONO) THEN ASM_REWRITE_TAC[]);;

(* [[!!n p]]_v <= [[p]]_((n|->c)v)  for every bname c.                    *)
let BVALF_ALL_LB = prove
 (`!n p D (E:A->A->bool) B leq v c.
      model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
      valuation D v /\ (!i. bname D E B (v i)) /\ c IN D /\ bname D E B c
      ==> erel D E leq (bvalf D E B leq v (!! n p))
                       (bvalf D E B leq ((n |-> c) v) p)`,
  REPEAT STRIP_TAC THEN
  MP_TAC(ISPECL [`!! n p`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`v:num->A`]
    BVALF_SPEC) THEN ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  REWRITE_TAC[bval] THEN
  DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC
    (X_CHOOSE_THEN `sv:A` STRIP_ASSUME_TAC)) THEN
  SUBGOAL_THEN `!i. bname D E B (((n |-> (c:A)) (v:num->A)) i)`
    ASSUME_TAC THENL
   [MATCH_MP_TAC BNAMEVAL_VALMOD THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MP_TAC(ISPECL [`p:form`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
    `(n |-> (c:A)) (v:num->A)`] BVALF_SPEC) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[] THEN MATCH_MP_TAC VALUATION_VALMOD THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN STRIP_TAC THEN
  SUBGOAL_THEN
    `(E:A->A->bool)
     (bvalf D (E:A->A->bool) B leq ((n |-> (c:A)) (v:num->A)) p) sv`
  ASSUME_TAC THENL
   [FIRST_X_ASSUM(fun th ->
      if is_forall(concl th) && mem `sv:A` (frees(concl th))
      then (MP_TAC(SPEC
                   `bvalf D (E:A->A->bool) B leq
                    ((n |-> (c:A)) (v:num->A)) p` th) THEN
            ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC])
      else failwith "skip") THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    EXISTS_TAC `c:A` THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`sv:A`;
    `bvalf D (E:A->A->bool) B leq v (!! n p)`;
    `bvalf D (E:A->A->bool) B leq ((n |-> (c:A)) (v:num->A)) p`] EGLB_LB) THEN
  ASM_REWRITE_TAC[]);;

(* ===================================================================== *)
(* F5 reflexivity core: [[a=a]] = top.                                   *)
(*   BNAME_APPLY_IN_B: a B-name's values lie in B (u(x) IN B).           *)
(*   EBV_EQ_REFL_STEP: the transfinite-induction STEP -- if [[x=x]]=top   *)
(*   for every dom-element x of u, then [[u=u]]=top.  (For each combiner  *)
(*   u(x)=>[[x in u]]: u(x) MEET [[x=x]] = u(x) MEET top = u(x) <= [[x in  *)
(*   u]] (EBV_IN_GE_TERM), so the impl is top (EBIMP_TOP); EBVEQ_GLB with  *)
(*   w0:=top gives top <= [[u=u]].)  The least-counterexample assembly     *)
(*   into full reflexivity is the next step.                             *)
(* --------------------------------------------------------------------- *)
(* a B-name's values are in the carrier B.                               *)
let BNAME_APPLY_IN_B = prove
 (`!D (E:A->A->bool) B u x qx.
      model D E ZF_AX /\ B IN D /\ u IN D /\ bname D E B u /\
        x IN D /\ qx IN D /\
      eapply D E u x qx
      ==> E qx B`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  FIRST_X_ASSUM(X_CHOOSE_THEN `ao:A` (X_CHOOSE_THEN `y:A` STRIP_ASSUME_TAC) o
                REWRITE_RULE[bname]) THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`ao:A`;`y:A`]
         EBNSTAGE_CHAR) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `ww:A` STRIP_ASSUME_TAC) THEN
  SUBGOAL_THEN `ebnmem D (E:A->A->bool) B ww u` STRIP_ASSUME_TAC THENL
   [UNDISCH_TAC `ebnfuns D (E:A->A->bool) B ww y` THEN
    REWRITE_TAC[ebnfuns] THEN
    DISCH_THEN(MP_TAC o SPEC `u:A` o CONJUNCT2) THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  UNDISCH_TAC `ebnmem D (E:A->A->bool) B ww u` THEN REWRITE_TAC[ebnmem] THEN
  DISCH_THEN(CONJUNCTS_THEN2 (K ALL_TAC)
    (X_CHOOSE_THEN `cr:A` STRIP_ASSUME_TAC)) THEN
  UNDISCH_TAC `eapply D (E:A->A->bool) u x qx` THEN REWRITE_TAC[eapply] THEN
  DISCH_THEN(X_CHOOSE_THEN `z:A` STRIP_ASSUME_TAC) THEN
  SUBGOAL_THEN `(z:A) IN D` ASSUME_TAC THENL
   [FIRST_ASSUM(ACCEPT_TAC o MATCH_MP EOPAIR_IN); ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) z cr` ASSUME_TAC THENL
   [UNDISCH_TAC `esubset D (E:A->A->bool) u cr` THEN REWRITE_TAC[esubset] THEN
    DISCH_THEN(MP_TAC o SPEC `z:A`) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  UNDISCH_TAC `ecross D (E:A->A->bool) ww B cr` THEN REWRITE_TAC[ecross] THEN
  DISCH_THEN(MP_TAC o SPEC `z:A` o CONJUNCT2) THEN ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `u1:A` (X_CHOOSE_THEN `w1:A` STRIP_ASSUME_TAC)) THEN
  SUBGOAL_THEN `qx:A = w1` SUBST1_TAC THENL
   [MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`x:A`;`qx:A`;`u1:A`;`w1:A`;`z:A`]
      EOPAIR_INJ) THEN ASM_REWRITE_TAC[] THEN MESON_TAC[]; ALL_TAC] THEN
  ASM_REWRITE_TAC[]);;

(* reflexivity for dom-elements  =>  reflexivity for u.                  *)
let EBV_EQ_REFL_STEP = prove
 (`!D (E:A->A->bool) B leq ao w sIN sEQ u z.
      model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
      ao IN D /\ eordinal D E ao /\ ebnstage D E B ao w /\ w IN D /\
      u IN D /\ E u w /\ ebvatt D E B leq w sIN sEQ /\
      ebveq D E B leq sIN u u z /\
      (!x qx. x IN D /\ qx IN D /\ eapply D E u x qx
              ==> !zx. zx IN D /\ ebv_eq D E B leq x x zx ==>
                etop D E B leq zx)
      ==> etop D E B leq z`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `ebalg D (E:A->A->bool) B leq` ASSUME_TAC THENL
   [FIRST_ASSUM(ACCEPT_TAC o CONJUNCT1 o REWRITE_RULE[ecba]); ALL_TAC] THEN
  SUBGOAL_THEN `eporder D (E:A->A->bool) B leq` ASSUME_TAC THENL
   [ASM_MESON_TAC[EBALG_IMP_PORDER]; ALL_TAC] THEN
  SUBGOAL_THEN `eisfun D (E:A->A->bool) sIN` ASSUME_TAC THENL
   [FIRST_ASSUM(ACCEPT_TAC o CONJUNCT1 o REWRITE_RULE[ebvatt]); ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`] EBALG_TOP) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `top:A`) THEN
  SUBGOAL_THEN `(top:A) IN D /\ (E:A->A->bool) top B` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[ETOP_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `(z:A) IN D /\ (E:A->A->bool) z B` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[EBVEQ_IN]; ALL_TAC] THEN
  (* the combiner bound: every bveqcomb sIN u u c has erel top c *)
  SUBGOAL_THEN
    `!c. bveqcomb D (E:A->A->bool) B leq sIN u u c ==> erel D E leq top c`
  ASSUME_TAC THENL
   [X_GEN_TAC `c:A` THEN REWRITE_TAC[bveqcomb] THEN
    DISCH_THEN(X_CHOOSE_THEN `x:A` (X_CHOOSE_THEN `qx:A` (X_CHOOSE_THEN `mx:A`
      (X_CHOOSE_THEN `pr:A` STRIP_ASSUME_TAC)))) THEN
    SUBGOAL_THEN `(E:A->A->bool) x w` ASSUME_TAC THENL
     [MATCH_MP_TAC(ISPECL
                   [`D:A->bool`;`E:A->A->bool`;`B:A`;`ao:A`;`w:A`;`u:A`;`x:A`;
                    `qx:A`] STAGE_DOM_CLOSED) THEN ASM_REWRITE_TAC[];
                ALL_TAC] THEN
    SUBGOAL_THEN `bname D (E:A->A->bool) B x` ASSUME_TAC THENL
     [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`ao:A`;`w:A`;`x:A`]
        BNAME_STAGE) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN `bname D (E:A->A->bool) B u` ASSUME_TAC THENL
     [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`ao:A`;`w:A`;`u:A`]
        BNAME_STAGE) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN `(E:A->A->bool) qx B` ASSUME_TAC THENL
     [MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`u:A`;`x:A`;`qx:A`]
        BNAME_APPLY_IN_B) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    (* [[x=x]] exists *)
    MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`x:A`;`x:A`]
           EBV_TOTAL) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(CONJUNCTS_THEN2 (K ALL_TAC)
      (X_CHOOSE_THEN `ex:A` STRIP_ASSUME_TAC)) THEN
    SUBGOAL_THEN `etop D E B leq (ex:A)` ASSUME_TAC THENL
     [FIRST_X_ASSUM(fun th -> MP_TAC(SPECL [`x:A`;`qx:A`] th)) THEN
      ASM_REWRITE_TAC[] THEN DISCH_THEN MATCH_MP_TAC THEN ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    (* mx = sIN<x,u> = ebvin sEQ u x mx *)
    MP_TAC(ISPECL
           [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`w:A`;`sIN:A`;`sEQ:A`;
            `x:A`;`u:A`;`pr:A`] EBVATT_VAL) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(CONJUNCTS_THEN2 (X_CHOOSE_THEN `vi:A` STRIP_ASSUME_TAC)
               (K ALL_TAC)) THEN
    SUBGOAL_THEN `mx:A = vi` SUBST_ALL_TAC THENL
     [MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`sIN:A`;`pr:A`;`mx:A`;`vi:A`]
        EAPPLY_UNIQUE) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    (* emeet qx ex qx (qx meet top) *)
    SUBGOAL_THEN `emeet D (E:A->A->bool) B leq qx ex qx` ASSUME_TAC THENL
     [MATCH_MP_TAC EMEET_TOP THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    (* erel qx vi via EBV_IN_GE_TERM *)
    SUBGOAL_THEN `erel D E leq (qx:A) vi` ASSUME_TAC THENL
     [MP_TAC(ISPECL
             [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`ao:A`;`w:A`;`sIN:A`;
              `sEQ:A`;`x:A`;`u:A`;`vi:A`;`x:A`;`qx:A`;`ex:A`;`qx:A`]
               EBV_IN_GE_TERM) THEN
      ASM_REWRITE_TAC[]; ALL_TAC] THEN
    (* etop c via EBIMP_TOP (qx <= vi) *)
    SUBGOAL_THEN `etop D E B leq (c:A)` ASSUME_TAC THENL
     [MP_TAC(ISPECL
             [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`qx:A`;`vi:A`;`c:A`]
             EBIMP_TOP) THEN
      ANTS_TAC THENL
       [ASM_REWRITE_TAC[] THEN
        FIRST_ASSUM(ACCEPT_TAC o CONJUNCT2 o MATCH_MP EBVIN_IN); ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`c:A`;`top:A`]
           ETOP_GE) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* now EBVEQ_GLB with w0:=top *)
  SUBGOAL_THEN `erel D E leq top (z:A)` ASSUME_TAC THENL
   [MP_TAC(ISPECL
           [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`sIN:A`;`u:A`;`u:A`;
            `z:A`;`top:A`] EBVEQ_GLB) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* z <= top; antisym => z = top => etop z *)
  SUBGOAL_THEN `erel D E leq (z:A) top` ASSUME_TAC THENL
   [MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`top:A`;`z:A`]
           ETOP_GE) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `z:A = top` SUBST1_TAC THENL
   [MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`z:A`;`top:A`]
      EPORDER_ANTISYM) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  ASM_REWRITE_TAC[]);;

(* ===================================================================== *)
(* F5 reflexivity assembly, piece 1: the object formula "[[a=a]] = top".  *)
(*   refltop_form ia ileq holds (at v) iff the =-value [[v_ia = v_ia]] is  *)
(*   the top of B -- built from ebv_eq_form + btop_form.  Consumed by the  *)
(*   internal least-counterexample that discharges EBV_EQ_REFL_STEP's IH.  *)
(* --------------------------------------------------------------------- *)
let refltop_form = new_definition
  `refltop_form ia ileq =
     ?? (MAX (MAX ia ileq) 2 + 1)
        (ebv_eq_form (MAX (MAX ia ileq) 2 + 1) ia ia ileq &&
         btop_form ileq 2 (MAX (MAX ia ileq) 2 + 1))`;;
let HOLDS_REFLTOP_FORM = prove
 (`!D (E:A->A->bool) v ia ileq.
      model D E ZF_AX /\ valuation D v
      ==> (holds D E v (refltop_form ia ileq) <=>
           ?zz. zz IN D /\ ebv_eq D E (v 2) (v ileq) (v ia) (v ia) zz /\
                etop D E (v 2) (v ileq) zz)`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[refltop_form] THEN
  ABBREV_TAC `iz = MAX (MAX ia ileq) 2 + 1` THEN
  SUBGOAL_THEN `~(iz = ia) /\ ~(iz = ileq) /\ ~(iz:num = 2)`
    STRIP_ASSUME_TAC THENL
   [EXPAND_TAC "iz" THEN ARITH_TAC; ALL_TAC] THEN
  REWRITE_TAC[HOLDS_EX] THEN
  MATCH_MP_TAC EXISTS_AND_CONG THEN
  X_GEN_TAC `zz:A` THEN DISCH_TAC THEN
  SUBGOAL_THEN `valuation D ((iz |-> (zz:A)) (v:num->A))` ASSUME_TAC THENL
   [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
  REWRITE_TAC[HOLDS_AND] THEN
  MP_TAC(ISPECL
         [`D:A->bool`;`E:A->A->bool`;`(iz |-> (zz:A)) (v:num->A)`;
          `iz:num`;`ia:num`;
          `ia:num`;`ileq:num`] HOLDS_EBV_EQ_FORM) THEN ASM_REWRITE_TAC[] THEN
  DISCH_THEN SUBST1_TAC THEN
  MP_TAC(ISPECL
         [`D:A->bool`;`E:A->A->bool`;`(iz |-> (zz:A)) (v:num->A)`;`ileq:num`;
          `2`;`iz:num`]
         HOLDS_BTOP_FORM) THEN ASM_REWRITE_TAC[] THEN
  DISCH_THEN SUBST1_TAC THEN
  ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER]);;

(* --------------------------------------------------------------------- *)
(* F5 reflexivity endpoint:  ebv_eq a a z  ==>  etop z   ([[a=a]] = top). *)
(* refl_bad_form n  codes "some bname in stage n has non-top self-equality*)
(* value"; EBV_EQ_REFL runs the internal least-counterexample (via        *)
(* EORDINAL_LEAST) : were there a bad bname, the least-rank one a0 would   *)
(* have all its members' self-equalities = top (EBV_EQ_REFL_STEP), forcing *)
(* [[a0=a0]] = top, contradicting a0 bad.  (z IN D supplied by callers,    *)
(* who build z via EBV_TOTAL.)                                            *)
(* --------------------------------------------------------------------- *)

let refl_bad_form = new_definition
  `refl_bad_form = ?? 1
   (instage_bn_form && bname_form 1 && Not(refltop_form 1 5))`;;
let HOLDS_REFL_BAD_FORM = prove
 (`!D (E:A->A->bool) v.
      model D E ZF_AX /\ valuation D v
      ==> (holds D E v refl_bad_form <=>
           ?a. a IN D /\ (?y. y IN D /\ ebnstage D E (v 2) (v 0) y /\ E a y) /\
               bname D E (v 2) a /\
               ~(?zz. zz IN D /\ ebv_eq D E (v 2) (v 5) a a zz /\
                      etop D E (v 2) (v 5) zz))`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[refl_bad_form] THEN
  REWRITE_TAC[HOLDS_EX] THEN
  MATCH_MP_TAC EXISTS_AND_CONG THEN
  X_GEN_TAC `a:A` THEN DISCH_TAC THEN
  SUBGOAL_THEN `valuation D ((1 |-> (a:A)) (v:num->A))` ASSUME_TAC THENL
   [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
  REWRITE_TAC[HOLDS_AND; HOLDS_NOT] THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`(1 |-> (a:A)) (v:num->A)`]
    HOLDS_INSTAGE_BN_FORM) THEN ASM_REWRITE_TAC[] THEN
  DISCH_THEN SUBST1_TAC THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`(1 |-> (a:A)) (v:num->A)`;`1`]
    HOLDS_BNAME_FORM) THEN ANTS_TAC THENL
  [ASM_REWRITE_TAC[] THEN ARITH_TAC; ALL_TAC] THEN
  DISCH_THEN SUBST1_TAC THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`(1 |-> (a:A)) (v:num->A)`;`1`;`5`]
    HOLDS_REFLTOP_FORM) THEN ASM_REWRITE_TAC[] THEN DISCH_THEN SUBST1_TAC THEN
  REWRITE_TAC[VALMOD_BASIC] THEN
  ASM_SIMP_TAC[VALMOD_OTHER; ARITH_EQ]);;

let EBV_EQ_REFL = prove
 (`!D (E:A->A->bool) B leq a z.
      model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
      a IN D /\ bname D E B a /\ z IN D /\ ebv_eq D E B leq a a z
      ==> etop D E B leq z`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  FIRST_ASSUM(X_CHOOSE_TAC `v0:num->A` o MATCH_MP VALUATION_EXISTS o
              MATCH_MP MODEL_NONEMPTY) THEN
  ABBREV_TAC `v = (5 |-> (leq:A)) ((2 |-> (B:A)) v0)` THEN
  SUBGOAL_THEN
   `valuation D (v:num->A) /\ (v:num->A) 2 = B /\ (v:num->A) 5 = leq`
  STRIP_ASSUME_TAC THENL
   [EXPAND_TAC "v" THEN REPEAT CONJ_TAC THENL
     [ASM_MESON_TAC[VALUATION_VALMOD]; REWRITE_TAC[VALMOD; ARITH_EQ];
      REWRITE_TAC[VALMOD]]; ALL_TAC] THEN
  REFUTE_THEN ASSUME_TAC THEN
  SUBGOAL_THEN
   `~(?zz:A. zz IN D /\ ebv_eq D E B leq a a zz /\ etop D E B leq zz)`
  ASSUME_TAC THENL
   [DISCH_THEN(X_CHOOSE_THEN `zz:A` STRIP_ASSUME_TAC) THEN
    SUBGOAL_THEN `zz:A = z` SUBST_ALL_TAC THENL
     [MP_TAC(ISPECL
             [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`a:A`;`a:A`;
              `zz:A`;`z:A`]
             EBV_EQ_UNIQUE) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    UNDISCH_TAC `~(etop D E B leq (z:A))` THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`a:A`] EBNRANK_EXISTS) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_THEN `ra:A` STRIP_ASSUME_TAC) THEN
  SUBGOAL_THEN `(ra:A) IN D /\ eordinal D (E:A->A->bool) ra`
    STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[EBNRANK_IN; EBNRANK_ORDINAL]; ALL_TAC] THEN
  SUBGOAL_THEN `holds D (E:A->A->bool) ((0 |-> ra) (v:num->A)) refl_bad_form`
    ASSUME_TAC THENL
   [MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`(0 |-> ra) (v:num->A)`]
      HOLDS_REFL_BAD_FORM) THEN
    ANTS_TAC THENL
    [ASM_REWRITE_TAC[] THEN MATCH_MP_TAC VALUATION_VALMOD THEN
     ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN SUBST1_TAC THEN
    ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER; ARITH_EQ] THEN
    EXISTS_TAC `a:A` THEN ASM_REWRITE_TAC[] THEN
    UNDISCH_TAC `ebnrank D (E:A->A->bool) B a ra` THEN
    REWRITE_TAC[ebnrank] THEN
    MESON_TAC[]; ALL_TAC] THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`refl_bad_form`;`v:num->A`;`ra:A`]
    EORDINAL_LEAST) THEN ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `d:A` (CONJUNCTS_THEN2 ASSUME_TAC (CONJUNCTS_THEN2
    ASSUME_TAC (CONJUNCTS_THEN2 (LABEL_TAC "badd") (LABEL_TAC "min"))))) THEN
  SUBGOAL_THEN
   `?a0. a0 IN D /\
    (?y. y IN D /\ ebnstage D (E:A->A->bool) B d y /\ E a0 y) /\
         bname D E B a0 /\
         ~(?zz. zz IN D /\ ebv_eq D (E:A->A->bool) B leq a0 a0 zz /\
           etop D E B leq zz)`
  STRIP_ASSUME_TAC THENL
   [MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`(0 |-> d) (v:num->A)`]
      HOLDS_REFL_BAD_FORM) THEN
    ANTS_TAC THENL
    [ASM_REWRITE_TAC[] THEN MATCH_MP_TAC VALUATION_VALMOD THEN
     ASM_REWRITE_TAC[]; ALL_TAC] THEN
    ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER; ARITH_EQ] THEN
    DISCH_THEN(fun th -> USE_THEN "badd" (ACCEPT_TAC o EQ_MP th));
    ALL_TAC] THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`a0:A`] EBNRANK_EXISTS) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `ra0:A` STRIP_ASSUME_TAC) THEN
  SUBGOAL_THEN `(ra0:A) IN D /\ eordinal D (E:A->A->bool) ra0`
    STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[EBNRANK_IN; EBNRANK_ORDINAL]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) (ra0:A) d \/ ra0 = d` ASSUME_TAC THENL
   [SUBGOAL_THEN `~((E:A->A->bool) (d:A) ra0)` ASSUME_TAC THENL
     [DISCH_TAC THEN UNDISCH_TAC `ebnrank D (E:A->A->bool) B a0 ra0` THEN
      REWRITE_TAC[ebnrank] THEN
      DISCH_THEN(MP_TAC o SPEC `d:A` o CONJUNCT2 o CONJUNCT2) THEN
      ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[]; ALL_TAC] THEN
    MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`ra0:A`;`d:A`]
           EORDINAL_TRICHOTOMY) THEN
    ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[]; ALL_TAC] THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`a0:A`;`a0:A`]
         BNAME_DIRECTED) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `aw:A` (X_CHOOSE_THEN `w:A` STRIP_ASSUME_TAC)) THEN
  SUBGOAL_THEN `!zt. zt IN D /\ E zt w ==> bname D (E:A->A->bool) B zt`
    ASSUME_TAC THENL
   [REPEAT STRIP_TAC THEN
    MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;
                         `aw:A`;`w:A`;`zt:A`] BNAME_STAGE) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`w:A`]
         EBVATT_EXISTS) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[] THEN EXISTS_TAC `a0:A` THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `sIN:A` (X_CHOOSE_THEN `sEQ:A` ASSUME_TAC)) THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`a0:A`;`a0:A`] EOPAIR_EXISTS) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `pr:A`) THEN
  MP_TAC(ISPECL
         [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`w:A`;`sIN:A`;`sEQ:A`;
          `a0:A`;`a0:A`;`pr:A`] EBVATT_VAL) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(CONJUNCTS_THEN2 (K ALL_TAC)
    (X_CHOOSE_THEN `vev:A` STRIP_ASSUME_TAC)) THEN
  SUBGOAL_THEN `etop D (E:A->A->bool) B leq (vev:A)` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`aw:A`;`w:A`;
      `sIN:A`;`sEQ:A`;`a0:A`;`vev:A`] EBV_EQ_REFL_STEP) THEN
    ASM_REWRITE_TAC[] THEN
    MAP_EVERY X_GEN_TAC [`xx:A`;`qx:A`] THEN STRIP_TAC THEN
    X_GEN_TAC `zx:A` THEN STRIP_TAC THEN REFUTE_THEN ASSUME_TAC THEN
    SUBGOAL_THEN
     `~(?zz:A. zz IN D /\ ebv_eq D (E:A->A->bool) B leq xx xx zz /\
        etop D E B leq zz)`
    ASSUME_TAC THENL
     [DISCH_THEN(X_CHOOSE_THEN `zz:A` STRIP_ASSUME_TAC) THEN
      SUBGOAL_THEN `zz:A = zx` SUBST_ALL_TAC THENL
       [MP_TAC(ISPECL
               [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`xx:A`;`xx:A`;`zz:A`;
                `zx:A`] EBV_EQ_UNIQUE) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
      UNDISCH_TAC `~(etop D E B leq (zx:A))` THEN ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    MP_TAC(ISPECL
           [`D:A->bool`;`E:A->A->bool`;`B:A`;`a0:A`;`xx:A`;`qx:A`;`ra0:A`]
           EBNRANK_APPLY_LT) THEN ASM_REWRITE_TAC[] THEN
    DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC
               (X_CHOOSE_THEN `rx:A` STRIP_ASSUME_TAC)) THEN
    SUBGOAL_THEN `(rx:A) IN D /\ eordinal D (E:A->A->bool) rx`
      STRIP_ASSUME_TAC THENL
      [ASM_MESON_TAC[EBNRANK_IN; EBNRANK_ORDINAL]; ALL_TAC] THEN
    SUBGOAL_THEN `(E:A->A->bool) (rx:A) d` ASSUME_TAC THENL
     [UNDISCH_TAC `(E:A->A->bool) (ra0:A) d \/ ra0 = d` THEN STRIP_TAC THENL
       [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`d:A`;`rx:A`;`ra0:A`]
          EORDINAL_TRANS_E) THEN ASM_REWRITE_TAC[];
        ASM_MESON_TAC[]]; ALL_TAC] THEN
    SUBGOAL_THEN `holds D (E:A->A->bool) ((0 |-> rx) (v:num->A)) refl_bad_form`
      ASSUME_TAC THENL
      [MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`(0 |-> rx) (v:num->A)`]
        HOLDS_REFL_BAD_FORM) THEN
      ANTS_TAC THENL
      [ASM_REWRITE_TAC[] THEN MATCH_MP_TAC VALUATION_VALMOD THEN
       ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN SUBST1_TAC THEN
      ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER; ARITH_EQ] THEN
      EXISTS_TAC `xx:A` THEN ASM_REWRITE_TAC[] THEN
      UNDISCH_TAC `ebnrank D (E:A->A->bool) B xx rx` THEN
      REWRITE_TAC[ebnrank] THEN
      MESON_TAC[]; ALL_TAC] THEN
    USE_THEN "min" (fun th -> MP_TAC(MATCH_MP th
      (CONJ (ASSUME `(rx:A) IN D`) (ASSUME `(E:A->A->bool) rx d`)))) THEN
    REWRITE_TAC[ASSUME
                `holds D (E:A->A->bool) ((0 |-> rx) (v:num->A))
                 refl_bad_form`];
    ALL_TAC] THEN
  SUBGOAL_THEN `ebv_eq D (E:A->A->bool) B leq a0 a0 vev` ASSUME_TAC THENL
   [MP_TAC(ISPECL
           [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`aw:A`;`w:A`;`sIN:A`;
            `sEQ:A`;`a0:A`;`a0:A`;`vev:A`] EBV_EQ_AT_STAGE) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  UNDISCH_TAC
    `~(?zz. zz IN D /\ ebv_eq D (E:A->A->bool) B leq a0 a0 zz /\
       etop D E B leq zz)` THEN
  REWRITE_TAC[] THEN EXISTS_TAC `vev:A` THEN ASM_REWRITE_TAC[]);;

(* --------------------------------------------------------------------- *)
(* EBV_IN_MEMBER:  v(u) <= [[u in v]]  for u in dom v (at a stage).       *)
(* Bell : [[u in v]] = SUP_{y in dom v}(v(y) MEET [[u=y]]); take y:=u,     *)
(* then [[u=u]] = top (EBV_EQ_REFL) so the term is v(u) MEET top = v(u).   *)
(* This is the EBV_EQ_REFL_STEP combiner-bound, now unconditional.        *)
(* --------------------------------------------------------------------- *)

let EBV_IN_MEMBER = prove
 (`!D (E:A->A->bool) B leq ao w sIN sEQ u v qu z.
      model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
      ao IN D /\ eordinal D E ao /\ ebnstage D E B ao w /\ w IN D /\
      u IN D /\ v IN D /\ E u w /\ E v w /\ ebvatt D E B leq w sIN sEQ /\
      qu IN D /\ eapply D E v u qu /\ ebvin D E B leq sEQ v u z
      ==> erel D E leq qu z`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `ebalg D (E:A->A->bool) B leq` ASSUME_TAC THENL
   [FIRST_ASSUM(ACCEPT_TAC o CONJUNCT1 o REWRITE_RULE[ecba]); ALL_TAC] THEN
  SUBGOAL_THEN `eporder D (E:A->A->bool) B leq` ASSUME_TAC THENL
   [ASM_MESON_TAC[EBALG_IMP_PORDER]; ALL_TAC] THEN
  SUBGOAL_THEN `bname D (E:A->A->bool) B u` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`ao:A`;`w:A`;`u:A`]
      BNAME_STAGE) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `bname D (E:A->A->bool) B v` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`ao:A`;`w:A`;`v:A`]
      BNAME_STAGE) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`u:A`;`u:A`]
         EBV_TOTAL) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(CONJUNCTS_THEN2 (K ALL_TAC)
    (X_CHOOSE_THEN `eu:A` STRIP_ASSUME_TAC)) THEN
  SUBGOAL_THEN `etop D (E:A->A->bool) B leq eu` ASSUME_TAC THENL
   [MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`u:A`;`eu:A`]
      EBV_EQ_REFL) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) qu B` ASSUME_TAC THENL
   [MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`v:A`;`u:A`;`qu:A`]
      BNAME_APPLY_IN_B) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `emeet D (E:A->A->bool) B leq qu eu qu` ASSUME_TAC THENL
   [MATCH_MP_TAC EMEET_TOP THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`ao:A`;`w:A`;`sIN:A`;
    `sEQ:A`;`u:A`;`v:A`;`z:A`;`u:A`;`qu:A`;`eu:A`;`qu:A`] EBV_IN_GE_TERM) THEN
  ASM_REWRITE_TAC[]);;

(* ------------------------------------------------------------------------- *)
(* F5, V^B |= ZFC, axiom 1/9 -- EXTENSIONALITY:  [[ext_ax]] = top.           *)
(*   ext_ax = !!0 !!1 ((!!2 (2%%0 <-> 2%%1)) --> Eq 0 1).                    *)
(* BVALF_ALL_TOP x2 + BVALF_IMP_TOP reduce to  w0 <= [[a0=a1]]  where        *)
(* w0 = [[!!z(z in a0 <-> z in a1)]].  Build one common stage for a0,a1      *)
(* (BNAME_DIRECTED gives w IN D); EBV_EQ_GLB_STAGE reduces to per-member     *)
(* bounds  w0 <= (a_i(s) => [[s in a_j]]) : glb-lower-bound (BVALF_ALL_LB)   *)
(* + iff-conjunct (BVALF_AND_LE_L/R) gives w0 <= ([[s in a_i]]=>[[s in       *)
(* a_j]]), then s(a_i) <= [[s in a_i]] (EBV_IN_MEMBER) + ebimp antitone      *)
(* (EBIMP_ANT). Requires the bname-valuation invariant (!i. bname (v i)).    *)
(* ------------------------------------------------------------------------- *)

let BVALF_EXTENSIONALITY = prove
 (`!D (E:A->A->bool) B leq v.
      model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
      valuation D v /\ (!i. bname D E B (v i))
      ==> etop D E B leq (bvalf D E B leq v extensionality_ax)`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `eporder D (E:A->A->bool) B leq` ASSUME_TAC THENL
   [ASM_MESON_TAC[EBALG_IMP_PORDER; ECBA_IMP_BALG]; ALL_TAC] THEN
  REWRITE_TAC[extensionality_ax] THEN
  MP_TAC(ISPECL [`0`; `!! 1 ((!! 2 ((2 %% 0) <-> (2 %% 1))) --> Eq 0 1)`;
    `D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`v:num->A`] BVALF_ALL_TOP) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  X_GEN_TAC `a0:A` THEN STRIP_TAC THEN
  SUBGOAL_THEN `valuation D ((0 |-> (a0:A)) (v:num->A)) /\
                (!i. bname D E B (((0 |-> (a0:A)) (v:num->A)) i))`
  STRIP_ASSUME_TAC THENL
   [CONJ_TAC THENL
     [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[];
      MATCH_MP_TAC BNAMEVAL_VALMOD THEN ASM_REWRITE_TAC[]]; ALL_TAC] THEN
  MP_TAC(ISPECL [`1`; `(!! 2 ((2 %% 0) <-> (2 %% 1))) --> Eq 0 1`;
    `D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`(0 |-> (a0:A)) (v:num->A)`]
    BVALF_ALL_TOP) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  X_GEN_TAC `a1:A` THEN STRIP_TAC THEN
  SUBGOAL_THEN `valuation D ((1 |-> (a1:A)) ((0 |-> (a0:A)) (v:num->A))) /\
                (!i. bname D E B
                 (((1 |-> (a1:A)) ((0 |-> (a0:A)) (v:num->A))) i))`
  STRIP_ASSUME_TAC THENL
   [CONJ_TAC THENL
     [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[];
      MATCH_MP_TAC BNAMEVAL_VALMOD THEN ASM_REWRITE_TAC[]]; ALL_TAC] THEN
  ABBREV_TAC `v01 = (1 |-> (a1:A)) ((0 |-> (a0:A)) (v:num->A))` THEN
  SUBGOAL_THEN `(v01:num->A) 0 = a0 /\ (v01:num->A) 1 = a1`
    STRIP_ASSUME_TAC THENL
   [EXPAND_TAC "v01" THEN SIMP_TAC[VALMOD_OTHER; VALMOD_BASIC; ARITH_EQ];
    ALL_TAC] THEN
  MP_TAC(ISPECL [`!! 2 ((2 %% 0) <-> (2 %% 1))`; `Eq 0 1`;
    `D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`v01:num->A`] BVALF_IMP_TOP) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  ABBREV_TAC
    `w0 = bvalf D (E:A->A->bool) B leq (v01:num->A)
     (!! 2 ((2 %% 0) <-> (2 %% 1)))` THEN
  ABBREV_TAC `zeq = bvalf D (E:A->A->bool) B leq (v01:num->A) (Eq 0 1)` THEN
  (* zeq = [[a0=a1]] *)
  SUBGOAL_THEN `ebv_eq D (E:A->A->bool) B leq a0 a1 zeq` ASSUME_TAC THENL
   [MP_TAC(ISPECL
           [`0`;`1`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`v01:num->A`]
           BVALF_EQ2) THEN ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* w0 IN D, E w0 B *)
  SUBGOAL_THEN `(w0:A) IN D /\ (E:A->A->bool) w0 B` STRIP_ASSUME_TAC THENL
   [EXPAND_TAC "w0" THEN CONJ_TAC THENL
     [MP_TAC(ISPECL [`!! 2 ((2 %% 0) <-> (2 %% 1))`;`D:A->bool`;`E:A->A->bool`;
        `B:A`;`leq:A`;`v01:num->A`] BVALF_SPEC) THEN ASM_SIMP_TAC[];
      MP_TAC(ISPECL [`!! 2 ((2 %% 0) <-> (2 %% 1))`;`D:A->bool`;`E:A->A->bool`;
        `B:A`;`leq:A`;`v01:num->A`] BVALF_IN_B) THEN ASM_SIMP_TAC[]];
     ALL_TAC] THEN
  SUBGOAL_THEN `(zeq:A) IN D` ASSUME_TAC THENL
   [EXPAND_TAC "zeq" THEN
    MP_TAC(ISPECL
           [`Eq 0 1`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`v01:num->A`]
           BVALF_SPEC) THEN ASM_SIMP_TAC[]; ALL_TAC] THEN
  (* common stage for a0,a1 *)
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`a0:A`;`a1:A`]
         BNAME_DIRECTED) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `ao:A` (X_CHOOSE_THEN `w:A` STRIP_ASSUME_TAC)) THEN
  SUBGOAL_THEN `!zt. zt IN D /\ E zt w ==> bname D (E:A->A->bool) B zt`
    ASSUME_TAC THENL
   [REPEAT STRIP_TAC THEN
    MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;
                         `ao:A`;`w:A`;`zt:A`] BNAME_STAGE) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`w:A`]
         EBVATT_EXISTS) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[] THEN EXISTS_TAC `a0:A` THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `sIN:A` (X_CHOOSE_THEN `sEQ:A` ASSUME_TAC)) THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`a0:A`;`a1:A`] EOPAIR_EXISTS) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `pr01:A`) THEN
  MP_TAC(ISPECL
         [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`w:A`;`sIN:A`;`sEQ:A`;
          `a0:A`;`a1:A`;`pr01:A`] EBVATT_VAL) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(CONJUNCTS_THEN2 (K ALL_TAC)
    (X_CHOOSE_THEN `zc:A` STRIP_ASSUME_TAC)) THEN
  (* zeq = zc *)
  SUBGOAL_THEN `ebv_eq D (E:A->A->bool) B leq a0 a1 zc` ASSUME_TAC THENL
   [MP_TAC(ISPECL
           [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`ao:A`;`w:A`;`sIN:A`;
            `sEQ:A`;`a0:A`;`a1:A`;`zc:A`] EBV_EQ_AT_STAGE) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `zeq:A = zc` SUBST_ALL_TAC THENL
   [MP_TAC(ISPECL
           [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`a0:A`;`a1:A`;`zeq:A`;
            `zc:A`] EBV_EQ_UNIQUE) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* apply EBV_EQ_GLB_STAGE *)
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`ao:A`;`w:A`;`sIN:A`;
    `sEQ:A`;`a0:A`;`a1:A`;`zc:A`;`w0:A`] EBV_EQ_GLB_STAGE) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
     [ (* (hu): x in dom a0 *)
      MAP_EVERY X_GEN_TAC [`x:A`;`qx:A`;`exv:A`;`c:A`] THEN STRIP_TAC THEN
      SUBGOAL_THEN `(E:A->A->bool) x w` ASSUME_TAC THENL
       [MATCH_MP_TAC(ISPECL
                     [`D:A->bool`;`E:A->A->bool`;`B:A`;`ao:A`;`w:A`;`a0:A`;
                      `x:A`;`qx:A`] STAGE_DOM_CLOSED) THEN ASM_REWRITE_TAC[];
            ALL_TAC] THEN
      SUBGOAL_THEN `bname D (E:A->A->bool) B x` ASSUME_TAC THENL
       [FIRST_ASSUM MATCH_MP_TAC THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
      SUBGOAL_THEN `valuation D ((2 |-> (x:A)) (v01:num->A)) /\
                    (!i. bname D E B (((2 |-> (x:A)) (v01:num->A)) i))`
      STRIP_ASSUME_TAC THENL
       [CONJ_TAC THENL
         [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[];
          MATCH_MP_TAC BNAMEVAL_VALMOD THEN ASM_REWRITE_TAC[]]; ALL_TAC] THEN
      SUBGOAL_THEN `((2 |-> (x:A)) (v01:num->A)) 0 = a0 /\
                    ((2 |-> (x:A)) (v01:num->A)) 1 = a1 /\
                    ((2 |-> (x:A)) (v01:num->A)) 2 = x` STRIP_ASSUME_TAC THENL
       [ASM_SIMP_TAC[VALMOD_OTHER; VALMOD_BASIC; ARITH_EQ]; ALL_TAC] THEN
      (* inx0 = [[x in a0]], inx1 = [[x in a1]] *)
      ABBREV_TAC
        `inx0 = bvalf D (E:A->A->bool) B leq ((2 |-> (x:A)) (v01:num->A))
         (2 %% 0)` THEN
      ABBREV_TAC
        `inx1 = bvalf D (E:A->A->bool) B leq ((2 |-> (x:A)) (v01:num->A))
         (2 %% 1)` THEN
      SUBGOAL_THEN `ebv_in D (E:A->A->bool) B leq x a0 inx0` ASSUME_TAC THENL
       [EXPAND_TAC "inx0" THEN
        MP_TAC(ISPECL [`2`;`0`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
          `(2 |-> (x:A)) (v01:num->A)`] BVALF_MEM) THEN
        ASM_SIMP_TAC[]; ALL_TAC] THEN
      SUBGOAL_THEN `ebv_in D (E:A->A->bool) B leq x a1 inx1` ASSUME_TAC THENL
       [EXPAND_TAC "inx1" THEN
        MP_TAC(ISPECL [`2`;`1`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
          `(2 |-> (x:A)) (v01:num->A)`] BVALF_MEM) THEN
        ASM_SIMP_TAC[]; ALL_TAC] THEN
      SUBGOAL_THEN `(inx0:A) IN D /\ (E:A->A->bool) inx0 B`
        STRIP_ASSUME_TAC THENL
        [EXPAND_TAC "inx0" THEN CONJ_TAC THENL
         [MP_TAC(ISPECL
                 [`2 %% 0`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
                  `(2 |-> (x:A)) (v01:num->A)`] BVALF_SPEC) THEN
          ASM_SIMP_TAC[];
          MP_TAC(ISPECL
                 [`2 %% 0`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
                  `(2 |-> (x:A)) (v01:num->A)`] BVALF_IN_B) THEN
          ASM_SIMP_TAC[]]; ALL_TAC] THEN
      SUBGOAL_THEN `(inx1:A) IN D /\ (E:A->A->bool) inx1 B`
        STRIP_ASSUME_TAC THENL
        [EXPAND_TAC "inx1" THEN CONJ_TAC THENL
         [MP_TAC(ISPECL
                 [`2 %% 1`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
                  `(2 |-> (x:A)) (v01:num->A)`] BVALF_SPEC) THEN
          ASM_SIMP_TAC[];
          MP_TAC(ISPECL
                 [`2 %% 1`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
                  `(2 |-> (x:A)) (v01:num->A)`] BVALF_IN_B) THEN
          ASM_SIMP_TAC[]]; ALL_TAC] THEN
      (* exv = inx1 *)
      SUBGOAL_THEN `exv:A = inx1` SUBST_ALL_TAC THENL
       [MP_TAC(ISPECL
               [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`x:A`;`a1:A`;`exv:A`;
                `inx1:A`] EBV_IN_UNIQUE) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
      (* impval = [[x in a0]] ==> [[x in a1]] *)
      ABBREV_TAC
        `impval = bvalf D (E:A->A->bool) B leq ((2 |-> (x:A)) (v01:num->A))
         ((2 %% 0) --> (2 %% 1))` THEN
      SUBGOAL_THEN `ebimp D (E:A->A->bool) B leq inx0 inx1 impval`
        ASSUME_TAC THENL
        [MAP_EVERY EXPAND_TAC ["inx0";"inx1";"impval"] THEN
        MP_TAC(ISPECL
               [`2 %% 0`;`2 %% 1`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
                `(2 |-> (x:A)) (v01:num->A)`] BVALF_IMP) THEN ASM_SIMP_TAC[];
        ALL_TAC] THEN
      (* stage membership value s0 for [[x in a0]] : erel qx inx0 *)
      MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`x:A`;`a0:A`]
             EOPAIR_EXISTS) THEN
      ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `prx0:A`) THEN
      MP_TAC(ISPECL
             [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`w:A`;`sIN:A`;`sEQ:A`;
              `x:A`;`a0:A`;`prx0:A`] EBVATT_VAL) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(CONJUNCTS_THEN2
        (X_CHOOSE_THEN `s0:A` STRIP_ASSUME_TAC) (K ALL_TAC)) THEN
      SUBGOAL_THEN `ebv_in D (E:A->A->bool) B leq x a0 s0` ASSUME_TAC THENL
       [MP_TAC(ISPECL
               [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`ao:A`;`w:A`;`sIN:A`;
                `sEQ:A`;`x:A`;`a0:A`;`s0:A`] EBV_IN_AT_STAGE) THEN
        ASM_REWRITE_TAC[]; ALL_TAC] THEN
      SUBGOAL_THEN `s0:A = inx0` SUBST_ALL_TAC THENL
       [MP_TAC(ISPECL
               [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`x:A`;`a0:A`;`s0:A`;
                `inx0:A`] EBV_IN_UNIQUE) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
      SUBGOAL_THEN `erel D (E:A->A->bool) leq qx inx0` ASSUME_TAC THENL
       [MP_TAC(ISPECL
               [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`ao:A`;`w:A`;`sIN:A`;
                `sEQ:A`;`x:A`;`a0:A`;`qx:A`;`inx0:A`] EBV_IN_MEMBER) THEN
        ASM_REWRITE_TAC[]; ALL_TAC] THEN
      (* impval <= c via EBIMP_ANT *)
      SUBGOAL_THEN `(E:A->A->bool) qx B` ASSUME_TAC THENL
       [MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`a0:A`;`x:A`;`qx:A`]
          BNAME_APPLY_IN_B) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
      SUBGOAL_THEN `erel D (E:A->A->bool) leq impval c` ASSUME_TAC THENL
       [MP_TAC(ISPECL
               [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`qx:A`;`inx0:A`;
                `inx1:A`;`c:A`;`impval:A`] EBIMP_ANT) THEN
        ASM_REWRITE_TAC[] THEN DISCH_THEN MATCH_MP_TAC THEN
        FIRST_ASSUM(ACCEPT_TAC o CONJUNCT1 o REWRITE_RULE[ecba]); ALL_TAC] THEN
      (* w0 <= iffval <= impval <= c *)
      SUBGOAL_THEN `(impval:A) IN D /\ (E:A->A->bool) impval B`
        STRIP_ASSUME_TAC THENL
        [EXPAND_TAC "impval" THEN CONJ_TAC THENL
         [MP_TAC(ISPECL
                 [`(2 %% 0) --> (2 %% 1)`;`D:A->bool`;`E:A->A->bool`;`B:A`;
                  `leq:A`;`(2 |-> (x:A)) (v01:num->A)`] BVALF_SPEC) THEN
          ASM_SIMP_TAC[];
          MP_TAC(ISPECL
                 [`(2 %% 0) --> (2 %% 1)`;`D:A->bool`;`E:A->A->bool`;`B:A`;
                  `leq:A`;`(2 |-> (x:A)) (v01:num->A)`] BVALF_IN_B) THEN
          ASM_SIMP_TAC[]]; ALL_TAC] THEN
      SUBGOAL_THEN
        `(bvalf D (E:A->A->bool) B leq ((2 |-> (x:A)) (v01:num->A))
          ((2 %% 0) <-> (2 %% 1))) IN D /\
         (E:A->A->bool)
         (bvalf D (E:A->A->bool) B leq ((2 |-> (x:A)) (v01:num->A))
          ((2 %% 0) <-> (2 %% 1))) B` STRIP_ASSUME_TAC THENL
       [CONJ_TAC THENL
         [MP_TAC(ISPECL
                 [`(2 %% 0) <-> (2 %% 1)`;`D:A->bool`;`E:A->A->bool`;`B:A`;
                  `leq:A`;`(2 |-> (x:A)) (v01:num->A)`] BVALF_SPEC) THEN
          ASM_SIMP_TAC[];
          MP_TAC(ISPECL
                 [`(2 %% 0) <-> (2 %% 1)`;`D:A->bool`;`E:A->A->bool`;`B:A`;
                  `leq:A`;`(2 |-> (x:A)) (v01:num->A)`] BVALF_IN_B) THEN
          ASM_SIMP_TAC[]]; ALL_TAC] THEN
      SUBGOAL_THEN `(E:A->A->bool) c B` ASSUME_TAC THENL
       [MP_TAC(ISPECL
               [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`qx:A`;`inx1:A`;`c:A`]
               EBIMP_IN) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
      SUBGOAL_THEN
        `erel D (E:A->A->bool) leq w0
         (bvalf D (E:A->A->bool) B leq ((2 |-> (x:A)) (v01:num->A))
          ((2 %% 0) <-> (2 %% 1)))`
      ASSUME_TAC THENL
       [EXPAND_TAC "w0" THEN
        MP_TAC(ISPECL
               [`2`;`(2 %% 0) <-> (2 %% 1)`;`D:A->bool`;`E:A->A->bool`;`B:A`;
                `leq:A`;`v01:num->A`;`x:A`] BVALF_ALL_LB) THEN ASM_SIMP_TAC[];
        ALL_TAC] THEN
      SUBGOAL_THEN
        `erel D (E:A->A->bool) leq
           (bvalf D (E:A->A->bool) B leq ((2 |-> (x:A)) (v01:num->A))
            ((2 %% 0) <-> (2 %% 1)))
           impval`
      ASSUME_TAC THENL
       [EXPAND_TAC "impval" THEN REWRITE_TAC[Iff_DEF] THEN
        MP_TAC(ISPECL
               [`(2 %% 0) --> (2 %% 1)`;`(2 %% 1) --> (2 %% 0)`;`D:A->bool`;
                `E:A->A->bool`;`B:A`;`leq:A`;`(2 |-> (x:A)) (v01:num->A)`]
                 BVALF_AND_LE_L) THEN
        ASM_SIMP_TAC[]; ALL_TAC] THEN
      MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`w0:A`;
        `bvalf D (E:A->A->bool) B leq ((2 |-> (x:A)) (v01:num->A))
         ((2 %% 0) <-> (2 %% 1))`;
        `impval:A`] EPORDER_TRANS) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN DISCH_TAC THEN
      MP_TAC(ISPECL
             [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`w0:A`;`impval:A`;
              `c:A`] EPORDER_TRANS) THEN ASM_REWRITE_TAC[];
      (* (hv): y in dom a1 -- mirror, AND_LE_R *)
      MAP_EVERY X_GEN_TAC [`y:A`;`qy:A`;`eyu:A`;`c:A`] THEN STRIP_TAC THEN
      SUBGOAL_THEN `(E:A->A->bool) y w` ASSUME_TAC THENL
       [MATCH_MP_TAC(ISPECL
                     [`D:A->bool`;`E:A->A->bool`;`B:A`;`ao:A`;`w:A`;`a1:A`;
                      `y:A`;`qy:A`] STAGE_DOM_CLOSED) THEN ASM_REWRITE_TAC[];
             ALL_TAC] THEN
      SUBGOAL_THEN `bname D (E:A->A->bool) B y` ASSUME_TAC THENL
       [FIRST_ASSUM MATCH_MP_TAC THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
      SUBGOAL_THEN `valuation D ((2 |-> (y:A)) (v01:num->A)) /\
                    (!i. bname D E B (((2 |-> (y:A)) (v01:num->A)) i))`
      STRIP_ASSUME_TAC THENL
       [CONJ_TAC THENL
         [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[];
          MATCH_MP_TAC BNAMEVAL_VALMOD THEN ASM_REWRITE_TAC[]]; ALL_TAC] THEN
      SUBGOAL_THEN `((2 |-> (y:A)) (v01:num->A)) 0 = a0 /\
                    ((2 |-> (y:A)) (v01:num->A)) 1 = a1 /\
                    ((2 |-> (y:A)) (v01:num->A)) 2 = y` STRIP_ASSUME_TAC THENL
       [ASM_SIMP_TAC[VALMOD_OTHER; VALMOD_BASIC; ARITH_EQ]; ALL_TAC] THEN
      ABBREV_TAC
        `iny0 = bvalf D (E:A->A->bool) B leq ((2 |-> (y:A)) (v01:num->A))
         (2 %% 0)` THEN
      ABBREV_TAC
        `iny1 = bvalf D (E:A->A->bool) B leq ((2 |-> (y:A)) (v01:num->A))
         (2 %% 1)` THEN
      SUBGOAL_THEN `ebv_in D (E:A->A->bool) B leq y a0 iny0` ASSUME_TAC THENL
       [EXPAND_TAC "iny0" THEN
        MP_TAC(ISPECL [`2`;`0`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
          `(2 |-> (y:A)) (v01:num->A)`] BVALF_MEM) THEN ASM_SIMP_TAC[];
        ALL_TAC] THEN
      SUBGOAL_THEN `ebv_in D (E:A->A->bool) B leq y a1 iny1` ASSUME_TAC THENL
       [EXPAND_TAC "iny1" THEN
        MP_TAC(ISPECL [`2`;`1`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
          `(2 |-> (y:A)) (v01:num->A)`] BVALF_MEM) THEN ASM_SIMP_TAC[];
        ALL_TAC] THEN
      SUBGOAL_THEN `(iny0:A) IN D /\ (E:A->A->bool) iny0 B`
        STRIP_ASSUME_TAC THENL
        [EXPAND_TAC "iny0" THEN CONJ_TAC THENL
         [MP_TAC(ISPECL
                 [`2 %% 0`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
                  `(2 |-> (y:A)) (v01:num->A)`] BVALF_SPEC) THEN
          ASM_SIMP_TAC[];
          MP_TAC(ISPECL
                 [`2 %% 0`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
                  `(2 |-> (y:A)) (v01:num->A)`] BVALF_IN_B) THEN
          ASM_SIMP_TAC[]]; ALL_TAC] THEN
      SUBGOAL_THEN `(iny1:A) IN D /\ (E:A->A->bool) iny1 B`
        STRIP_ASSUME_TAC THENL
        [EXPAND_TAC "iny1" THEN CONJ_TAC THENL
         [MP_TAC(ISPECL
                 [`2 %% 1`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
                  `(2 |-> (y:A)) (v01:num->A)`] BVALF_SPEC) THEN
          ASM_SIMP_TAC[];
          MP_TAC(ISPECL
                 [`2 %% 1`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
                  `(2 |-> (y:A)) (v01:num->A)`] BVALF_IN_B) THEN
          ASM_SIMP_TAC[]]; ALL_TAC] THEN
      SUBGOAL_THEN `eyu:A = iny0` SUBST_ALL_TAC THENL
       [MP_TAC(ISPECL
               [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`y:A`;`a0:A`;`eyu:A`;
                `iny0:A`] EBV_IN_UNIQUE) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
      ABBREV_TAC
        `impvy = bvalf D (E:A->A->bool) B leq ((2 |-> (y:A)) (v01:num->A))
         ((2 %% 1) --> (2 %% 0))` THEN
      SUBGOAL_THEN `ebimp D (E:A->A->bool) B leq iny1 iny0 impvy`
        ASSUME_TAC THENL
        [MAP_EVERY EXPAND_TAC ["iny0";"iny1";"impvy"] THEN
        MP_TAC(ISPECL
               [`2 %% 1`;`2 %% 0`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
                `(2 |-> (y:A)) (v01:num->A)`] BVALF_IMP) THEN ASM_SIMP_TAC[];
        ALL_TAC] THEN
      MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`y:A`;`a1:A`]
             EOPAIR_EXISTS) THEN
      ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `pry1:A`) THEN
      MP_TAC(ISPECL
             [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`w:A`;`sIN:A`;`sEQ:A`;
              `y:A`;`a1:A`;`pry1:A`] EBVATT_VAL) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(CONJUNCTS_THEN2
        (X_CHOOSE_THEN `t0:A` STRIP_ASSUME_TAC) (K ALL_TAC)) THEN
      SUBGOAL_THEN `ebv_in D (E:A->A->bool) B leq y a1 t0` ASSUME_TAC THENL
       [MP_TAC(ISPECL
               [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`ao:A`;`w:A`;`sIN:A`;
                `sEQ:A`;`y:A`;`a1:A`;`t0:A`] EBV_IN_AT_STAGE) THEN
        ASM_REWRITE_TAC[]; ALL_TAC] THEN
      SUBGOAL_THEN `t0:A = iny1` SUBST_ALL_TAC THENL
       [MP_TAC(ISPECL
               [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`y:A`;`a1:A`;`t0:A`;
                `iny1:A`] EBV_IN_UNIQUE) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
      SUBGOAL_THEN `erel D (E:A->A->bool) leq qy iny1` ASSUME_TAC THENL
       [MP_TAC(ISPECL
               [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`ao:A`;`w:A`;`sIN:A`;
                `sEQ:A`;`y:A`;`a1:A`;`qy:A`;`iny1:A`] EBV_IN_MEMBER) THEN
        ASM_REWRITE_TAC[]; ALL_TAC] THEN
      SUBGOAL_THEN `(E:A->A->bool) qy B` ASSUME_TAC THENL
       [MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`a1:A`;`y:A`;`qy:A`]
          BNAME_APPLY_IN_B) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
      SUBGOAL_THEN `erel D (E:A->A->bool) leq impvy c` ASSUME_TAC THENL
       [MP_TAC(ISPECL
               [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`qy:A`;`iny1:A`;
                `iny0:A`;`c:A`;`impvy:A`] EBIMP_ANT) THEN
        ASM_REWRITE_TAC[] THEN DISCH_THEN MATCH_MP_TAC THEN
        FIRST_ASSUM(ACCEPT_TAC o CONJUNCT1 o REWRITE_RULE[ecba]); ALL_TAC] THEN
      SUBGOAL_THEN `(impvy:A) IN D /\ (E:A->A->bool) impvy B`
        STRIP_ASSUME_TAC THENL
        [EXPAND_TAC "impvy" THEN CONJ_TAC THENL
         [MP_TAC(ISPECL
                 [`(2 %% 1) --> (2 %% 0)`;`D:A->bool`;`E:A->A->bool`;`B:A`;
                  `leq:A`;`(2 |-> (y:A)) (v01:num->A)`] BVALF_SPEC) THEN
          ASM_SIMP_TAC[];
          MP_TAC(ISPECL
                 [`(2 %% 1) --> (2 %% 0)`;`D:A->bool`;`E:A->A->bool`;`B:A`;
                  `leq:A`;`(2 |-> (y:A)) (v01:num->A)`] BVALF_IN_B) THEN
          ASM_SIMP_TAC[]]; ALL_TAC] THEN
      SUBGOAL_THEN
        `(bvalf D (E:A->A->bool) B leq ((2 |-> (y:A)) (v01:num->A))
          ((2 %% 0) <-> (2 %% 1))) IN D /\
         (E:A->A->bool)
         (bvalf D (E:A->A->bool) B leq ((2 |-> (y:A)) (v01:num->A))
          ((2 %% 0) <-> (2 %% 1))) B` STRIP_ASSUME_TAC THENL
       [CONJ_TAC THENL
         [MP_TAC(ISPECL
                 [`(2 %% 0) <-> (2 %% 1)`;`D:A->bool`;`E:A->A->bool`;`B:A`;
                  `leq:A`;`(2 |-> (y:A)) (v01:num->A)`] BVALF_SPEC) THEN
          ASM_SIMP_TAC[];
          MP_TAC(ISPECL
                 [`(2 %% 0) <-> (2 %% 1)`;`D:A->bool`;`E:A->A->bool`;`B:A`;
                  `leq:A`;`(2 |-> (y:A)) (v01:num->A)`] BVALF_IN_B) THEN
          ASM_SIMP_TAC[]]; ALL_TAC] THEN
      SUBGOAL_THEN `(E:A->A->bool) c B` ASSUME_TAC THENL
       [MP_TAC(ISPECL
               [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`qy:A`;`iny0:A`;`c:A`]
               EBIMP_IN) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
      SUBGOAL_THEN
        `erel D (E:A->A->bool) leq w0
         (bvalf D (E:A->A->bool) B leq ((2 |-> (y:A)) (v01:num->A))
          ((2 %% 0) <-> (2 %% 1)))`
      ASSUME_TAC THENL
       [EXPAND_TAC "w0" THEN
        MP_TAC(ISPECL
               [`2`;`(2 %% 0) <-> (2 %% 1)`;`D:A->bool`;`E:A->A->bool`;`B:A`;
                `leq:A`;`v01:num->A`;`y:A`] BVALF_ALL_LB) THEN ASM_SIMP_TAC[];
        ALL_TAC] THEN
      SUBGOAL_THEN
        `erel D (E:A->A->bool) leq
           (bvalf D (E:A->A->bool) B leq ((2 |-> (y:A)) (v01:num->A))
            ((2 %% 0) <-> (2 %% 1)))
           impvy`
      ASSUME_TAC THENL
       [EXPAND_TAC "impvy" THEN REWRITE_TAC[Iff_DEF] THEN
        MP_TAC(ISPECL
               [`(2 %% 0) --> (2 %% 1)`;`(2 %% 1) --> (2 %% 0)`;`D:A->bool`;
                `E:A->A->bool`;`B:A`;`leq:A`;`(2 |-> (y:A)) (v01:num->A)`]
                 BVALF_AND_LE_R) THEN
        ASM_SIMP_TAC[]; ALL_TAC] THEN
      MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`w0:A`;
        `bvalf D (E:A->A->bool) B leq ((2 |-> (y:A)) (v01:num->A))
         ((2 %% 0) <-> (2 %% 1))`;
        `impvy:A`] EPORDER_TRANS) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN DISCH_TAC THEN
      MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`w0:A`;`impvy:A`;
        `c:A`] EPORDER_TRANS) THEN ASM_REWRITE_TAC[]];
    DISCH_THEN ACCEPT_TAC]);;

(* --------------------------------------------------------------------- *)
(* F5 EXISTENTIAL-WITNESS layer: a single bname witness makes [[?x .]]=top.*)
(* ?? n p = Not(!! n (Not p)); if [[p(a)]]=top for a bname a then          *)
(* [[Not p(a)]]=bot, so glb [[!!n Not p]] <= bot = bot, hence [[??n p]] =   *)
(* ecompl(bot) = top.  BVALF_EXISTSMEM_TOP = the bounded twin              *)
(* (??- x y p = ?? x ((x%%y)&&p)) via BVALF_EX_TOP + BVALF_AND_TOP.        *)
(* These unlock the canonical-name Exists-axioms (pairing/union/sep/inf).  *)
(* --------------------------------------------------------------------- *)

let BVALF_EX_TOP = prove
 (`!n p D (E:A->A->bool) B leq v a.
      model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
      valuation D v /\ (!i. bname D E B (v i)) /\ a IN D /\ bname D E B a /\
      etop D E B leq (bvalf D E B leq ((n |-> a) v) p)
      ==> etop D E B leq (bvalf D E B leq v (?? n p))`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `ebalg D (E:A->A->bool) B leq` ASSUME_TAC THENL
   [ASM_MESON_TAC[ECBA_IMP_BALG]; ALL_TAC] THEN
  SUBGOAL_THEN `eporder D (E:A->A->bool) B leq` ASSUME_TAC THENL
   [ASM_MESON_TAC[EBALG_IMP_PORDER]; ALL_TAC] THEN
  SUBGOAL_THEN `valuation D ((n |-> (a:A)) (v:num->A)) /\
                (!i. bname D E B (((n |-> (a:A)) (v:num->A)) i))`
  STRIP_ASSUME_TAC THENL
   [CONJ_TAC THENL
     [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[];
      MATCH_MP_TAC BNAMEVAL_VALMOD THEN ASM_REWRITE_TAC[]]; ALL_TAC] THEN
  REWRITE_TAC[Exists_DEF] THEN
  MP_TAC(ISPECL [`p:form`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
    `(n |-> (a:A)) (v:num->A)`] BVALF_NOT) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN DISCH_TAC THEN
  MP_TAC(ISPECL
         [`!! n (Not p)`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`v:num->A`]
         BVALF_NOT) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN DISCH_TAC THEN
  ABBREV_TAC
    `pa = bvalf D (E:A->A->bool) B leq ((n |-> (a:A)) (v:num->A)) p` THEN
  ABBREV_TAC
    `npa = bvalf D (E:A->A->bool) B leq ((n |-> (a:A)) (v:num->A))
     (Not p)` THEN
  ABBREV_TAC
    `glb = bvalf D (E:A->A->bool) B leq (v:num->A) (!! n (Not p))` THEN
  ABBREV_TAC
    `cc = bvalf D (E:A->A->bool) B leq (v:num->A) (Not(!! n (Not p)))` THEN
  SUBGOAL_THEN `(pa:A) IN D /\ (E:A->A->bool) pa B` STRIP_ASSUME_TAC THENL
   [EXPAND_TAC "pa" THEN CONJ_TAC THENL
     [MP_TAC(ISPECL
             [`p:form`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
              `(n |-> (a:A)) (v:num->A)`] BVALF_SPEC) THEN ASM_SIMP_TAC[];
      MP_TAC(ISPECL
             [`p:form`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
              `(n |-> (a:A)) (v:num->A)`] BVALF_IN_B) THEN ASM_SIMP_TAC[]];
     ALL_TAC] THEN
  SUBGOAL_THEN `(npa:A) IN D /\ (E:A->A->bool) npa B` STRIP_ASSUME_TAC THENL
   [EXPAND_TAC "npa" THEN CONJ_TAC THENL
     [MP_TAC(ISPECL
             [`Not p`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
              `(n |-> (a:A)) (v:num->A)`] BVALF_SPEC) THEN ASM_SIMP_TAC[];
      MP_TAC(ISPECL
             [`Not p`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
              `(n |-> (a:A)) (v:num->A)`] BVALF_IN_B) THEN ASM_SIMP_TAC[]];
     ALL_TAC] THEN
  SUBGOAL_THEN `(glb:A) IN D /\ (E:A->A->bool) glb B` STRIP_ASSUME_TAC THENL
   [EXPAND_TAC "glb" THEN CONJ_TAC THENL
     [MP_TAC(ISPECL
             [`!! n (Not p)`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
              `v:num->A`] BVALF_SPEC) THEN ASM_SIMP_TAC[];
      MP_TAC(ISPECL
             [`!! n (Not p)`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
              `v:num->A`] BVALF_IN_B) THEN ASM_SIMP_TAC[]]; ALL_TAC] THEN
  SUBGOAL_THEN `ecompl D (E:A->A->bool) B leq npa pa` ASSUME_TAC THENL
   [MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`pa:A`;`npa:A`]
           ECOMPL_SYM) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `ebot D (E:A->A->bool) B leq npa` ASSUME_TAC THENL
   [MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`npa:A`;`pa:A`]
           ECOMPL_TOP_BOT) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq glb npa` ASSUME_TAC THENL
   [MAP_EVERY EXPAND_TAC ["glb";"npa"] THEN
    MP_TAC(ISPECL
           [`n:num`;`Not p`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
            `v:num->A`;`a:A`] BVALF_ALL_LB) THEN
    ASM_SIMP_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq npa glb` ASSUME_TAC THENL
   [MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`npa:A`;`glb:A`]
           EBOT_LE) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `ebot D (E:A->A->bool) B leq glb` ASSUME_TAC THENL
   [SUBGOAL_THEN `glb:A = npa` (fun th -> ASM_REWRITE_TAC[th]) THEN
    MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`glb:A`;`npa:A`]
           EPORDER_ANTISYM) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`glb:A`;`cc:A`]
         ECOMPL_TOP_BOT) THEN
  ASM_REWRITE_TAC[]);;

let BVALF_EXISTSMEM_TOP = prove
 (`!x y p D (E:A->A->bool) B leq v a.
      model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
      valuation D v /\ (!i. bname D E B (v i)) /\ a IN D /\ bname D E B a /\
      etop D E B leq (bvalf D E B leq ((x |-> a) v) (x %% y)) /\
      etop D E B leq (bvalf D E B leq ((x |-> a) v) p)
      ==> etop D E B leq (bvalf D E B leq v (??- x y p))`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `valuation D ((x |-> (a:A)) (v:num->A)) /\
                (!i. bname D E B (((x |-> (a:A)) (v:num->A)) i))`
  STRIP_ASSUME_TAC THENL
   [CONJ_TAC THENL
     [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[];
      MATCH_MP_TAC BNAMEVAL_VALMOD THEN ASM_REWRITE_TAC[]]; ALL_TAC] THEN
  REWRITE_TAC[Existsmem_DEF] THEN
  MP_TAC(ISPECL
         [`x:num`;`(x %% y) && p`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
          `v:num->A`;`a:A`] BVALF_EX_TOP) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[] THEN
    MP_TAC(ISPECL [`x %% y`;`p:form`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
      `(x |-> (a:A)) (v:num->A)`] BVALF_AND_TOP) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN ASM_REWRITE_TAC[];
    DISCH_THEN ACCEPT_TAC]);;

(* --------------------------------------------------------------------- *)
(* Pairing NAME.  For bnames a,b the pair-name up = {<a,top>,<b,top>}      *)
(* (built by ZF_PAIRING on the two Kuratowski pairs) is a bname with       *)
(* up(a)=up(b)=top and dom(up) SUBSET {a,b}.  bname up: up is a functional *)
(* subset of w x B where w is the stage-union at esuc(common stage of a,b) *)
(* (BNAME_DIRECTED + ESUC + EBNSTAGE_CHAR), so up lies in that stage.      *)
(* --------------------------------------------------------------------- *)

let EUPAIRNAME_EXISTS = prove
 (`!D (E:A->A->bool) B leq a b.
      model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ a IN D /\ b IN D /\
      bname D E B a /\ bname D E B b
      ==> ?up top. up IN D /\ bname D E B up /\
                   top IN D /\ etop D E B leq top /\
                   eapply D E up a top /\ eapply D E up b top /\
                   (!t q. t IN D /\ q IN D /\ eapply D E up t q ==>
                    t = a \/ t = b)`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `ebalg D (E:A->A->bool) B leq` ASSUME_TAC THENL
   [ASM_MESON_TAC[ECBA_IMP_BALG]; ALL_TAC] THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`] EBALG_TOP) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `top:A`) THEN
  SUBGOAL_THEN `(top:A) IN D /\ (E:A->A->bool) top B` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[ETOP_IN]; ALL_TAC] THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`a:A`;`top:A`] EOPAIR_EXISTS) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `pa:A`) THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`b:A`;`top:A`] EOPAIR_EXISTS) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `pb:A`) THEN
  SUBGOAL_THEN `(pa:A) IN D /\ (pb:A) IN D` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[EOPAIR_IN]; ALL_TAC] THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`] ZF_PAIRING) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(MP_TAC o SPECL [`pa:A`;`pb:A`]) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `up:A`
             (CONJUNCTS_THEN2 ASSUME_TAC (LABEL_TAC "upmem"))) THEN
  (* common stage for a,b, then its successor stage *)
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`a:A`;`b:A`]
         BNAME_DIRECTED) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `ao:A` (X_CHOOSE_THEN `y0:A` STRIP_ASSUME_TAC)) THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`ao:A`] ESUC_EXISTS) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `sao:A`) THEN
  SUBGOAL_THEN
    `(sao:A) IN D /\ eordinal D (E:A->A->bool) sao /\ (E:A->A->bool) ao sao`
  STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[ESUC_IN; EORDINAL_ESUC; ESUC_MEMBER]; ALL_TAC] THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`sao:A`]
         EBNSTAGE_EXISTS) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `ysao:A` STRIP_ASSUME_TAC) THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`sao:A`;`ysao:A`]
         EBNSTAGE_CHAR) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `w:A` (CONJUNCTS_THEN2 ASSUME_TAC
    (CONJUNCTS_THEN2 (LABEL_TAC "wch") ASSUME_TAC))) THEN
  SUBGOAL_THEN `(E:A->A->bool) a w` ASSUME_TAC THENL
   [USE_THEN "wch" (MP_TAC o SPEC `a:A`) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    MAP_EVERY EXISTS_TAC [`ao:A`;`y0:A`] THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) b w` ASSUME_TAC THENL
   [USE_THEN "wch" (MP_TAC o SPEC `b:A`) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    MAP_EVERY EXISTS_TAC [`ao:A`;`y0:A`] THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* cross w B *)
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`w:A`;`B:A`] ECROSS_EXISTS) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `cr:A` (LABEL_TAC "cr")) THEN
  SUBGOAL_THEN `(cr:A) IN D` ASSUME_TAC THENL
   [USE_THEN "cr" (MP_TAC o REWRITE_RULE[ecross]) THEN SIMP_TAC[];
    ALL_TAC] THEN
  (* "all values are top" helper *)
  SUBGOAL_THEN
   `!uu ww zz. uu IN D /\ ww IN D /\ eopair D (E:A->A->bool) uu ww zz /\
    E zz up ==> ww = top`
  (LABEL_TAC "vtop") THENL
   [REPEAT STRIP_TAC THEN
    SUBGOAL_THEN `(zz:A) IN D` ASSUME_TAC THENL
    [ASM_MESON_TAC[EOPAIR_IN]; ALL_TAC] THEN
    SUBGOAL_THEN `(zz:A) = pa \/ zz = pb` MP_TAC THENL
     [USE_THEN "upmem" (MP_TAC o SPEC `zz:A`) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[GSYM th]) THEN ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    DISCH_THEN(DISJ_CASES_THEN SUBST_ALL_TAC) THENL
     [MP_TAC(ISPECL
             [`D:A->bool`;`E:A->A->bool`;`uu:A`;`ww:A`;`a:A`;`top:A`;`pa:A`]
             EOPAIR_INJ) THEN ASM_REWRITE_TAC[] THEN STRIP_TAC THEN
      ASM_REWRITE_TAC[];
      MP_TAC(ISPECL
             [`D:A->bool`;`E:A->A->bool`;`uu:A`;`ww:A`;`b:A`;`top:A`;`pb:A`]
             EOPAIR_INJ) THEN ASM_REWRITE_TAC[] THEN STRIP_TAC THEN
      ASM_REWRITE_TAC[]]; ALL_TAC] THEN
  (* eisfun up *)
  SUBGOAL_THEN `eisfun D (E:A->A->bool) up` ASSUME_TAC THENL
   [REWRITE_TAC[eisfun] THEN ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
     [X_GEN_TAC `z:A` THEN STRIP_TAC THEN
      SUBGOAL_THEN `(z:A) = pa \/ z = pb` MP_TAC THENL
       [USE_THEN "upmem" (MP_TAC o SPEC `z:A`) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
        DISCH_THEN(fun th -> REWRITE_TAC[GSYM th]) THEN ASM_REWRITE_TAC[];
        ALL_TAC] THEN
      DISCH_THEN(DISJ_CASES_THEN SUBST_ALL_TAC) THENL
       [MAP_EVERY EXISTS_TAC [`a:A`;`top:A`] THEN ASM_REWRITE_TAC[];
        MAP_EVERY EXISTS_TAC [`b:A`;`top:A`] THEN ASM_REWRITE_TAC[]];
      MAP_EVERY X_GEN_TAC [`uu:A`;`ww:A`;`ww':A`;`zz:A`;`zz':A`] THEN
      STRIP_TAC THEN
      SUBGOAL_THEN `ww:A = top /\ ww':A = top` (fun th -> MESON_TAC[th]) THEN
      CONJ_TAC THEN USE_THEN "vtop" MATCH_MP_TAC THENL
       [MAP_EVERY EXISTS_TAC [`uu:A`;`zz:A`];
        MAP_EVERY EXISTS_TAC [`uu:A`;`zz':A`]] THEN
      ASM_REWRITE_TAC[]]; ALL_TAC] THEN
  (* up SUBSET cross w B *)
  SUBGOAL_THEN `esubset D (E:A->A->bool) up cr` ASSUME_TAC THENL
   [REWRITE_TAC[esubset] THEN X_GEN_TAC `z:A` THEN STRIP_TAC THEN
    USE_THEN "cr" (MP_TAC o SPEC `z:A` o CONJUNCT2 o REWRITE_RULE[ecross]) THEN
    ASM_REWRITE_TAC[] THEN DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    SUBGOAL_THEN `(z:A) = pa \/ z = pb` MP_TAC THENL
     [USE_THEN "upmem" (MP_TAC o SPEC `z:A`) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[GSYM th]) THEN ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    DISCH_THEN(DISJ_CASES_THEN SUBST_ALL_TAC) THENL
     [MAP_EVERY EXISTS_TAC [`a:A`;`top:A`] THEN ASM_REWRITE_TAC[];
      MAP_EVERY EXISTS_TAC [`b:A`;`top:A`] THEN ASM_REWRITE_TAC[]];
     ALL_TAC] THEN
  (* ebnmem, then E up ysao, then bname up *)
  SUBGOAL_THEN `ebnmem D (E:A->A->bool) B w up` ASSUME_TAC THENL
   [REWRITE_TAC[ebnmem] THEN ASM_REWRITE_TAC[] THEN
    EXISTS_TAC `cr:A` THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) up ysao` ASSUME_TAC THENL
   [UNDISCH_TAC `ebnfuns D (E:A->A->bool) B w ysao` THEN
    REWRITE_TAC[ebnfuns] THEN
    DISCH_THEN(MP_TAC o SPEC `up:A` o CONJUNCT2) THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `bname D (E:A->A->bool) B up` ASSUME_TAC THENL
   [REWRITE_TAC[bname] THEN MAP_EVERY EXISTS_TAC [`sao:A`;`ysao:A`] THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* assemble *)
  MAP_EVERY EXISTS_TAC [`up:A`;`top:A`] THEN ASM_REWRITE_TAC[] THEN
  REPEAT CONJ_TAC THENL
   [REWRITE_TAC[eapply] THEN EXISTS_TAC `pa:A` THEN ASM_REWRITE_TAC[] THEN
    USE_THEN "upmem" (MP_TAC o SPEC `pa:A`) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]);
    REWRITE_TAC[eapply] THEN EXISTS_TAC `pb:A` THEN ASM_REWRITE_TAC[] THEN
    USE_THEN "upmem" (MP_TAC o SPEC `pb:A`) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]);
    MAP_EVERY X_GEN_TAC [`t:A`;`q:A`] THEN REWRITE_TAC[eapply] THEN
    DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC (CONJUNCTS_THEN2 ASSUME_TAC
      (X_CHOOSE_THEN `p:A` STRIP_ASSUME_TAC))) THEN
    SUBGOAL_THEN `(p:A) IN D` ASSUME_TAC THENL
    [ASM_MESON_TAC[EOPAIR_IN]; ALL_TAC] THEN
    SUBGOAL_THEN `(p:A) = pa \/ p = pb` MP_TAC THENL
     [USE_THEN "upmem" (MP_TAC o SPEC `p:A`) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[GSYM th]) THEN ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    DISCH_THEN(DISJ_CASES_THEN SUBST_ALL_TAC) THENL
     [DISJ1_TAC THEN
      MP_TAC(ISPECL
             [`D:A->bool`;`E:A->A->bool`;`t:A`;`q:A`;`a:A`;`top:A`;`pa:A`]
             EOPAIR_INJ) THEN ASM_REWRITE_TAC[] THEN STRIP_TAC THEN
      ASM_REWRITE_TAC[];
      DISJ2_TAC THEN
      MP_TAC(ISPECL
             [`D:A->bool`;`E:A->A->bool`;`t:A`;`q:A`;`b:A`;`top:A`;`pb:A`]
             EOPAIR_INJ) THEN ASM_REWRITE_TAC[] THEN STRIP_TAC THEN
      ASM_REWRITE_TAC[]]]);;

(* --------------------------------------------------------------------- *)
(* Pairing MEMBERSHIP: [[w in up]] = [[w=a]] JOIN [[w=b]]  (up the pair-   *)
(* name of a,b).  At a common stage for w,up (BNAME_DIRECTED): the SUP over *)
(* dom(up)={a,b} of up(t) MEET [[w=t]].  Lower: [[w=a]],[[w=b]] <= [[w in  *)
(* up]] (EBV_IN_GE_TERM, up(a)=up(b)=top so the meet-with-top = [[w=.]]) => *)
(* join <= (EJOIN_LEAST).  Upper: every combiner up(t) MEET [[w=t]] <=      *)
(* [[w=t]] (EMEET_LE) and t in {a,b} => <= join (EBV_IN_LE).                *)
(* --------------------------------------------------------------------- *)

let EBV_IN_UPAIR = prove
 (`!D (E:A->A->bool) B leq a b up top w zin za zb zj.
      model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
      a IN D /\ b IN D /\ bname D E B a /\ bname D E B b /\ w IN D /\
        bname D E B w /\
      up IN D /\ bname D E B up /\ top IN D /\ etop D E B leq top /\
      eapply D E up a top /\ eapply D E up b top /\
      (!t q. t IN D /\ q IN D /\ eapply D E up t q ==> t = a \/ t = b) /\
      zin IN D /\ za IN D /\ zb IN D /\
      ebv_in D E B leq w up zin /\ ebv_eq D E B leq w a za /\
      ebv_eq D E B leq w b zb /\ ejoin D E B leq za zb zj
      ==> zin = zj`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `ebalg D (E:A->A->bool) B leq` ASSUME_TAC THENL
   [ASM_MESON_TAC[ECBA_IMP_BALG]; ALL_TAC] THEN
  SUBGOAL_THEN `eporder D (E:A->A->bool) B leq` ASSUME_TAC THENL
   [ASM_MESON_TAC[EBALG_IMP_PORDER]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) za B /\ (E:A->A->bool) zb B`
    STRIP_ASSUME_TAC THENL
   [CONJ_TAC THENL
     [MP_TAC(ISPECL
             [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`w:A`;`a:A`;`za:A`]
             EBV_EQ_IN_B) THEN ASM_REWRITE_TAC[];
      MP_TAC(ISPECL
             [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`w:A`;`b:A`;`zb:A`]
             EBV_EQ_IN_B) THEN ASM_REWRITE_TAC[]]; ALL_TAC] THEN
  SUBGOAL_THEN `(zj:A) IN D /\ (E:A->A->bool) zj B` STRIP_ASSUME_TAC THENL
   [MP_TAC(ISPECL
           [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`za:A`;`zb:A`;`zj:A`]
           EJOIN_IN) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN
    `erel D (E:A->A->bool) leq za zj /\ erel D (E:A->A->bool) leq zb zj`
  STRIP_ASSUME_TAC THENL
   [MP_TAC(ISPECL
           [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`za:A`;`zb:A`;`zj:A`]
           EJOIN_GE) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* common stage for w, up *)
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`w:A`;`up:A`]
         BNAME_DIRECTED) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `ao:A` (X_CHOOSE_THEN `y0:A` STRIP_ASSUME_TAC)) THEN
  SUBGOAL_THEN `!zt. zt IN D /\ E zt y0 ==> bname D (E:A->A->bool) B zt`
    ASSUME_TAC THENL
   [REPEAT STRIP_TAC THEN
    MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;
                         `ao:A`;`y0:A`;`zt:A`] BNAME_STAGE) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`y0:A`]
         EBVATT_EXISTS) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[] THEN EXISTS_TAC `w:A` THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `sIN:A` (X_CHOOSE_THEN `sEQ:A` ASSUME_TAC)) THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`w:A`;`up:A`] EOPAIR_EXISTS) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `pr:A`) THEN
  MP_TAC(ISPECL
         [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`y0:A`;`sIN:A`;`sEQ:A`;
          `w:A`;`up:A`;`pr:A`] EBVATT_VAL) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(CONJUNCTS_THEN2 (X_CHOOSE_THEN `zst:A` STRIP_ASSUME_TAC)
             (K ALL_TAC)) THEN
  SUBGOAL_THEN `(E:A->A->bool) zst B` ASSUME_TAC THENL
   [FIRST_ASSUM(ACCEPT_TAC o CONJUNCT2 o MATCH_MP EBVIN_IN); ALL_TAC] THEN
  SUBGOAL_THEN `ebv_in D (E:A->A->bool) B leq w up zst` ASSUME_TAC THENL
   [MP_TAC(ISPECL
           [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`ao:A`;`y0:A`;`sIN:A`;
            `sEQ:A`;`w:A`;`up:A`;`zst:A`] EBV_IN_AT_STAGE) THEN
             ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `zin:A = zst` SUBST_ALL_TAC THENL
   [MP_TAC(ISPECL
           [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`w:A`;`up:A`;
            `zin:A`;`zst:A`]
           EBV_IN_UNIQUE) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* a,b IN stage y0 *)
  SUBGOAL_THEN `(E:A->A->bool) a y0` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`B:A`;`ao:A`;`y0:A`;`up:A`;`a:A`;
                  `top:A`] STAGE_DOM_CLOSED) THEN ASM_REWRITE_TAC[];
             ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) b y0` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`B:A`;`ao:A`;`y0:A`;`up:A`;`b:A`;
                  `top:A`] STAGE_DOM_CLOSED) THEN ASM_REWRITE_TAC[];
             ALL_TAC] THEN
  (* meets top za za, top zb zb *)
  SUBGOAL_THEN `emeet D (E:A->A->bool) B leq top za za` ASSUME_TAC THENL
   [MATCH_MP_TAC EMEET_SYM THEN MATCH_MP_TAC EMEET_TOP THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `emeet D (E:A->A->bool) B leq top zb zb` ASSUME_TAC THENL
   [MATCH_MP_TAC EMEET_SYM THEN MATCH_MP_TAC EMEET_TOP THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  (* lower bounds: za<=zst, zb<=zst *)
  SUBGOAL_THEN `erel D (E:A->A->bool) leq za zst` ASSUME_TAC THENL
   [MP_TAC(ISPECL
           [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`ao:A`;`y0:A`;`sIN:A`;
            `sEQ:A`;`w:A`;`up:A`;`zst:A`;`a:A`;`top:A`;`za:A`;`za:A`]
             EBV_IN_GE_TERM) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq zb zst` ASSUME_TAC THENL
   [MP_TAC(ISPECL
           [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`ao:A`;`y0:A`;`sIN:A`;
            `sEQ:A`;`w:A`;`up:A`;`zst:A`;`b:A`;`top:A`;`zb:A`;`zb:A`]
             EBV_IN_GE_TERM) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq zj zst` ASSUME_TAC THENL
   [MP_TAC(ISPECL
           [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`za:A`;`zb:A`;
            `zj:A`;`zst:A`]
           EJOIN_LEAST) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* upper bound: zst<=zj *)
  SUBGOAL_THEN `erel D (E:A->A->bool) leq zst zj` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`ao:A`;
                  `y0:A`;`sIN:A`;
                  `sEQ:A`;`w:A`;`up:A`;`zst:A`;`zj:A`] EBV_IN_LE) THEN
    ASM_REWRITE_TAC[] THEN
    MAP_EVERY X_GEN_TAC [`y:A`;`qy:A`;`ey:A`;`c:A`] THEN STRIP_TAC THEN
    SUBGOAL_THEN `(y:A) = a \/ y = b` MP_TAC THENL
     [FIRST_X_ASSUM(fun th -> MP_TAC(SPECL [`y:A`;`qy:A`] th)) THEN
      ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(DISJ_CASES_THEN SUBST_ALL_TAC) THENL
     [SUBGOAL_THEN `ey:A = za` SUBST_ALL_TAC THENL
       [MP_TAC(ISPECL
               [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`w:A`;`a:A`;
                `ey:A`;`za:A`]
               EBV_EQ_UNIQUE) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
      SUBGOAL_THEN `(E:A->A->bool) c B` ASSUME_TAC THENL
       [FIRST_ASSUM(ACCEPT_TAC o CONJUNCT2 o MATCH_MP EMEET_IN); ALL_TAC] THEN
      SUBGOAL_THEN `erel D (E:A->A->bool) leq c za` ASSUME_TAC THENL
       [FIRST_ASSUM(ACCEPT_TAC o CONJUNCT2 o MATCH_MP EMEET_LE); ALL_TAC] THEN
      MP_TAC(ISPECL
             [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`c:A`;`za:A`;`zj:A`]
             EPORDER_TRANS) THEN ASM_REWRITE_TAC[];
      SUBGOAL_THEN `ey:A = zb` SUBST_ALL_TAC THENL
       [MP_TAC(ISPECL
               [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`w:A`;`b:A`;
                `ey:A`;`zb:A`]
               EBV_EQ_UNIQUE) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
      SUBGOAL_THEN `(E:A->A->bool) c B` ASSUME_TAC THENL
       [FIRST_ASSUM(ACCEPT_TAC o CONJUNCT2 o MATCH_MP EMEET_IN); ALL_TAC] THEN
      SUBGOAL_THEN `erel D (E:A->A->bool) leq c zb` ASSUME_TAC THENL
       [FIRST_ASSUM(ACCEPT_TAC o CONJUNCT2 o MATCH_MP EMEET_LE); ALL_TAC] THEN
      MP_TAC(ISPECL
             [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`c:A`;`zb:A`;`zj:A`]
             EPORDER_TRANS) THEN ASM_REWRITE_TAC[]]; ALL_TAC] THEN
  (* zst = zj *)
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`zst:A`;`zj:A`]
         EPORDER_ANTISYM) THEN
  ASM_REWRITE_TAC[]);;

(* --------------------------------------------------------------------- *)
(* F5, V^B |= ZFC, AXIOM 2 of 9 -- PAIRING:  [[pairing_ax]] = top.        *)
(*   pairing_ax = !!0 !!1 ?? 2 !!3 ((3%%2) <-> Eq 3 0 || Eq 3 1).         *)
(* BVALF_ALL_TOP x2 (all a0,a1) then BVALF_EX_TOP with witness up = the    *)
(* pair-name (EUPAIRNAME_EXISTS) reduces to [[!!3(3 in up <-> 3=a0|3=a1)]] *)
(* = top; BVALF_ALL_TOP (all w) + BVALF_IFF_TOP -> [[w in up]]=[[w=a0]]    *)
(* JOIN [[w=a1]] (BVALF_MEM/EQ2/OR), closed by EBV_IN_UPAIR.               *)
(* --------------------------------------------------------------------- *)

let BVALF_PAIRING = prove
 (`!D (E:A->A->bool) B leq v.
      model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
      valuation D v /\ (!i. bname D E B (v i))
      ==> etop D E B leq (bvalf D E B leq v pairing_ax)`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  REWRITE_TAC[pairing_ax] THEN
  MP_TAC(ISPECL [`0`; `!! 1 (?? 2 (!! 3 ((3 %% 2) <-> Eq 3 0 || Eq 3 1)))`;
    `D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`v:num->A`] BVALF_ALL_TOP) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  X_GEN_TAC `a0:A` THEN STRIP_TAC THEN
  SUBGOAL_THEN `valuation D ((0 |-> (a0:A)) (v:num->A)) /\
                (!i. bname D E B (((0 |-> (a0:A)) (v:num->A)) i))`
  STRIP_ASSUME_TAC THENL
   [CONJ_TAC THENL
     [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[];
      MATCH_MP_TAC BNAMEVAL_VALMOD THEN ASM_REWRITE_TAC[]]; ALL_TAC] THEN
  MP_TAC(ISPECL [`1`; `?? 2 (!! 3 ((3 %% 2) <-> Eq 3 0 || Eq 3 1))`;
    `D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`(0 |-> (a0:A)) (v:num->A)`]
       BVALF_ALL_TOP) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  X_GEN_TAC `a1:A` THEN STRIP_TAC THEN
  SUBGOAL_THEN `valuation D ((1 |-> (a1:A)) ((0 |-> (a0:A)) (v:num->A))) /\
                (!i. bname D E B
                 (((1 |-> (a1:A)) ((0 |-> (a0:A)) (v:num->A))) i))`
  STRIP_ASSUME_TAC THENL
   [CONJ_TAC THENL
     [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[];
      MATCH_MP_TAC BNAMEVAL_VALMOD THEN ASM_REWRITE_TAC[]]; ALL_TAC] THEN
  ABBREV_TAC `v01 = (1 |-> (a1:A)) ((0 |-> (a0:A)) (v:num->A))` THEN
  (* witness: the pair-name of a0,a1 *)
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`a0:A`;`a1:A`]
         EUPAIRNAME_EXISTS) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `up:A`
             (X_CHOOSE_THEN `top:A` STRIP_ASSUME_TAC)) THEN
  MATCH_MP_TAC(ISPECL [`2`; `!! 3 ((3 %% 2) <-> Eq 3 0 || Eq 3 1)`;
    `D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`v01:num->A`;`up:A`]
               BVALF_EX_TOP) THEN
  ASM_REWRITE_TAC[] THEN
  SUBGOAL_THEN `valuation D ((2 |-> (up:A)) (v01:num->A)) /\
                (!i. bname D E B (((2 |-> (up:A)) (v01:num->A)) i))`
  STRIP_ASSUME_TAC THENL
   [CONJ_TAC THENL
     [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[];
      MATCH_MP_TAC BNAMEVAL_VALMOD THEN ASM_REWRITE_TAC[]]; ALL_TAC] THEN
  MP_TAC(ISPECL [`3`; `(3 %% 2) <-> Eq 3 0 || Eq 3 1`;
    `D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`(2 |-> (up:A)) (v01:num->A)`]
       BVALF_ALL_TOP) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  X_GEN_TAC `w:A` THEN STRIP_TAC THEN
  SUBGOAL_THEN `valuation D ((3 |-> (w:A)) ((2 |-> (up:A)) (v01:num->A))) /\
                (!i. bname D E B
                 (((3 |-> (w:A)) ((2 |-> (up:A)) (v01:num->A))) i))`
  STRIP_ASSUME_TAC THENL
   [CONJ_TAC THENL
     [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[];
      MATCH_MP_TAC BNAMEVAL_VALMOD THEN ASM_REWRITE_TAC[]]; ALL_TAC] THEN
  ABBREV_TAC `vv = (3 |-> (w:A)) ((2 |-> (up:A)) (v01:num->A))` THEN
  SUBGOAL_THEN
    `(vv:num->A) 0 = a0 /\ (vv:num->A) 1 = a1 /\ (vv:num->A) 2 = up /\
     (vv:num->A) 3 = w`
  STRIP_ASSUME_TAC THENL
   [MAP_EVERY EXPAND_TAC ["vv";"v01"] THEN
    SIMP_TAC[VALMOD_OTHER; VALMOD_BASIC; ARITH_EQ]; ALL_TAC] THEN
  MP_TAC(ISPECL [`3 %% 2`; `Eq 3 0 || Eq 3 1`;
    `D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`vv:num->A`] BVALF_IFF_TOP) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  (* now goal: bvalf vv (3%%2) = bvalf vv (Eq 3 0 || Eq 3 1) *)
  ABBREV_TAC `zin = bvalf D (E:A->A->bool) B leq (vv:num->A) (3 %% 2)` THEN
  ABBREV_TAC `za = bvalf D (E:A->A->bool) B leq (vv:num->A) (Eq 3 0)` THEN
  ABBREV_TAC `zb = bvalf D (E:A->A->bool) B leq (vv:num->A) (Eq 3 1)` THEN
  ABBREV_TAC
    `zj = bvalf D (E:A->A->bool) B leq (vv:num->A) (Eq 3 0 || Eq 3 1)` THEN
  SUBGOAL_THEN `ebv_in D (E:A->A->bool) B leq w up zin` ASSUME_TAC THENL
   [EXPAND_TAC "zin" THEN
    MP_TAC(ISPECL
           [`3`;`2`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`vv:num->A`]
           BVALF_MEM) THEN
    ASM_SIMP_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `ebv_eq D (E:A->A->bool) B leq w a0 za` ASSUME_TAC THENL
   [EXPAND_TAC "za" THEN
    MP_TAC(ISPECL
           [`3`;`0`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`vv:num->A`]
           BVALF_EQ2) THEN
    ASM_SIMP_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `ebv_eq D (E:A->A->bool) B leq w a1 zb` ASSUME_TAC THENL
   [EXPAND_TAC "zb" THEN
    MP_TAC(ISPECL
           [`3`;`1`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`vv:num->A`]
           BVALF_EQ2) THEN
    ASM_SIMP_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `ejoin D (E:A->A->bool) B leq za zb zj` ASSUME_TAC THENL
   [MAP_EVERY EXPAND_TAC ["za";"zb";"zj"] THEN
    MP_TAC(ISPECL
           [`Eq 3 0`;`Eq 3 1`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
            `vv:num->A`] BVALF_OR) THEN
    ASM_SIMP_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(zin:A) IN D` ASSUME_TAC THENL
   [EXPAND_TAC "zin" THEN
    MP_TAC(ISPECL
           [`3 %% 2`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`vv:num->A`]
           BVALF_SPEC) THEN ASM_SIMP_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(za:A) IN D` ASSUME_TAC THENL
   [EXPAND_TAC "za" THEN
    MP_TAC(ISPECL
           [`Eq 3 0`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`vv:num->A`]
           BVALF_SPEC) THEN ASM_SIMP_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(zb:A) IN D` ASSUME_TAC THENL
   [EXPAND_TAC "zb" THEN
    MP_TAC(ISPECL
           [`Eq 3 1`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`vv:num->A`]
           BVALF_SPEC) THEN ASM_SIMP_TAC[]; ALL_TAC] THEN
  MP_TAC(ISPECL
         [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`a0:A`;`a1:A`;
          `up:A`;`top:A`;
          `w:A`;`zin:A`;`za:A`;`zb:A`;`zj:A`] EBV_IN_UPAIR) THEN
  ASM_REWRITE_TAC[]);;

(* ------------------------------------------------------------------ *)
(* F5, V^B |= ZFC: UNION axiom -- the union-name domain.              *)
(* W = domain of the union name = {t : ?w. w in dom(x) /\ t in dom(w)}.*)
(* Built by ZF_REPLACEMENT (S |-> dom S over dom x) then eunion.       *)
(* ------------------------------------------------------------------ *)
let EUNIONDOM_EXISTS = prove
 (`!D (E:A->A->bool) x.
      model D E ZF_AX /\ x IN D
      ==> ?W. W IN D /\
              (!t. t IN D
                   ==> (E t W <=> ?w. w IN D /\ eindom D E x w /\
                        eindom D E w t))`,
  REPEAT STRIP_TAC THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`x:A`] EDOMAIN_EXISTS) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `dx:A`) THEN
  SUBGOAL_THEN `(dx:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[edomain]; ALL_TAC] THEN
  FIRST_ASSUM(X_CHOOSE_TAC `v0:num->A` o MATCH_MP VALUATION_EXISTS o
              MATCH_MP MODEL_NONEMPTY) THEN
  SUBGOAL_THEN
   `?FAM. FAM IN D /\
          !S. S IN D ==>
            ((E:A->A->bool) S FAM <=> ?u. u IN D /\ (E:A->A->bool) u dx /\
             edomain D E u S)`
  (X_CHOOSE_THEN `FAM:A` (CONJUNCTS_THEN2 ASSUME_TAC (LABEL_TAC "fmc"))) THENL
   [SUBGOAL_THEN
     `~(0 = 1) /\ valuation D (v0:num->A) /\ dx IN D /\
      (!u. u IN D /\ (E:A->A->bool) u dx
           ==> ?w. w IN D /\
                   !w'. w' IN D /\
                        holds D E ((1 |-> w') ((0 |-> u) (v0:num->A)))
                          (domain_form 0 1)
                        ==> w' = w)`
    (fun fth -> MP_TAC(MATCH_MP
       (SPECL [`domain_form 0 1`;`0`;`1`;`v0:num->A`;`dx:A`]
              (MATCH_MP ZF_REPLACEMENT
               (ASSUME `model D (E:A->A->bool) ZF_AX`))) fth))
    THENL
     [CONJ_TAC THENL [ARITH_TAC; ALL_TAC] THEN
      CONJ_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      CONJ_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      X_GEN_TAC `u:A` THEN STRIP_TAC THEN
        MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`u:A`] EDOMAIN_EXISTS) THEN
        ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `du:A`) THEN
        SUBGOAL_THEN `(du:A) IN D` ASSUME_TAC THENL
         [ASM_MESON_TAC[edomain]; ALL_TAC] THEN
        EXISTS_TAC `du:A` THEN ASM_REWRITE_TAC[] THEN
        X_GEN_TAC `w':A` THEN STRIP_TAC THEN
        MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;
          `(1 |-> (w':A)) ((0 |-> (u:A)) (v0:num->A))`;`0`;`1`]
         HOLDS_DOMAIN_FORM) THEN
        ANTS_TAC THENL [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
        ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER; ARITH_EQ] THEN DISCH_TAC THEN
        MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`u:A`;`w':A`;`du:A`]
               EDOMAIN_UNIQUE) THEN
        ASM_MESON_TAC[];
      DISCH_THEN(X_CHOOSE_THEN `FAM:A`
                 (CONJUNCTS_THEN2 ASSUME_TAC (LABEL_TAC "famc"))) THEN
      EXISTS_TAC `FAM:A` THEN ASM_REWRITE_TAC[] THEN
      X_GEN_TAC `S:A` THEN DISCH_TAC THEN
      USE_THEN "famc"
        (fun th ->
         REWRITE_TAC[MATCH_MP (SPEC `S:A` th) (ASSUME `(S:A) IN D`)]) THEN
      AP_TERM_TAC THEN ABS_TAC THEN
      ASM_CASES_TAC `(u:A) IN D` THEN ASM_REWRITE_TAC[] THEN
      MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;
        `(1 |-> (S:A)) ((0 |-> (u:A)) (v0:num->A))`;`0`;`1`]
           HOLDS_DOMAIN_FORM) THEN
      ANTS_TAC THENL [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
      ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER; ARITH_EQ]]; ALL_TAC] THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`FAM:A`] EUNION_EXISTS) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `W:A` (MP_TAC o REWRITE_RULE[eunion])) THEN
  DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC (LABEL_TAC "wc")) THEN
  EXISTS_TAC `W:A` THEN ASM_REWRITE_TAC[] THEN
  X_GEN_TAC `t:A` THEN DISCH_TAC THEN
  USE_THEN "wc"
    (fun th ->
     REWRITE_TAC[MATCH_MP (SPEC `t:A` th) (ASSUME `(t:A) IN D`)]) THEN
  EQ_TAC THENL
   [DISCH_THEN(X_CHOOSE_THEN `S:A` STRIP_ASSUME_TAC) THEN
    USE_THEN "fmc"
      (fun th -> MP_TAC(MATCH_MP (SPEC `S:A` th) (ASSUME `(S:A) IN D`))) THEN
      REWRITE_TAC[ASSUME `(E:A->A->bool) S FAM`] THEN
    DISCH_THEN(X_CHOOSE_THEN `u:A` STRIP_ASSUME_TAC) THEN
    EXISTS_TAC `u:A` THEN ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
     [UNDISCH_TAC `edomain D (E:A->A->bool) x dx` THEN
      REWRITE_TAC[edomain] THEN
      DISCH_THEN(MP_TAC o SPEC `u:A` o CONJUNCT2) THEN ASM_REWRITE_TAC[];
      UNDISCH_TAC `edomain D (E:A->A->bool) u S` THEN REWRITE_TAC[edomain] THEN
      DISCH_THEN(MP_TAC o SPEC `t:A` o CONJUNCT2) THEN ASM_REWRITE_TAC[]];
    DISCH_THEN(X_CHOOSE_THEN `w:A` STRIP_ASSUME_TAC) THEN
    MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`w:A`] EDOMAIN_EXISTS) THEN
    ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `dw:A`) THEN
    SUBGOAL_THEN `(dw:A) IN D` ASSUME_TAC THENL
     [UNDISCH_TAC `edomain D (E:A->A->bool) w dw` THEN
      REWRITE_TAC[edomain] THEN
      STRIP_TAC THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    EXISTS_TAC `dw:A` THEN REPEAT CONJ_TAC THENL
     [ASM_REWRITE_TAC[];
      USE_THEN "fmc"
        (fun th ->
         MP_TAC(MATCH_MP (SPEC `dw:A` th) (ASSUME `(dw:A) IN D`))) THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
      EXISTS_TAC `w:A` THEN ASM_REWRITE_TAC[] THEN
      UNDISCH_TAC `edomain D (E:A->A->bool) x dx` THEN
      REWRITE_TAC[edomain] THEN
      DISCH_THEN(MP_TAC o SPEC `w:A` o CONJUNCT2) THEN ASM_REWRITE_TAC[];
      UNDISCH_TAC `edomain D (E:A->A->bool) w dw` THEN
      REWRITE_TAC[edomain] THEN
      DISCH_THEN(MP_TAC o SPEC `t:A` o CONJUNCT2) THEN ASM_REWRITE_TAC[]]]);;

(* ------------------------------------------------------------------ *)
(* F5 Boolean-equality congruence, piece 1: SYMMETRY  [[u=v]] = [[v=u]].*)
(* ebveq s u v z = meet(glb combset(u,v), glb combset(v,u)); swapping   *)
(* u,v swaps SL<->SR so the meet is unchanged (EMEET_SYM) -- combiner    *)
(* symmetry EBVEQ_SYM.  Lifted to ebv_eq via EBVATT_VAL (z = sEQ<u,v>)   *)
(* + EBV_EQ_AT_STAGE at the SAME stage w (which contains both u,v).      *)
(* z IN D is a hypothesis (callers supply via EBV_TOTAL, as elsewhere).  *)
(* ------------------------------------------------------------------ *)
let EBVEQ_SYM = prove
 (`!D (E:A->A->bool) B leq s u v z.
      ebveq D E B leq s u v z ==> ebveq D E B leq s v u z`,
  REPEAT GEN_TAC THEN REWRITE_TAC[ebveq] THEN
  DISCH_THEN(X_CHOOSE_THEN `SL:A` (X_CHOOSE_THEN `SR:A` (X_CHOOSE_THEN `gL:A`
    (X_CHOOSE_THEN `gR:A` STRIP_ASSUME_TAC)))) THEN
  MAP_EVERY EXISTS_TAC [`SR:A`;`SL:A`;`gR:A`;`gL:A`] THEN
  ASM_REWRITE_TAC[] THEN MATCH_MP_TAC EMEET_SYM THEN ASM_REWRITE_TAC[]);;
let EBV_EQ_SYM = prove
 (`!D (E:A->A->bool) B leq u v z.
      model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
      u IN D /\ v IN D /\ z IN D /\ ebv_eq D E B leq u v z
      ==> ebv_eq D E B leq v u z`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  UNDISCH_TAC `ebv_eq D (E:A->A->bool) B leq u v z` THEN
  DISCH_THEN(fun th ->
    (X_CHOOSE_THEN `a:A` (X_CHOOSE_THEN `w:A` (X_CHOOSE_THEN `sIN:A`
      (X_CHOOSE_THEN `sEQ:A` (X_CHOOSE_THEN `pr:A` STRIP_ASSUME_TAC)))))
    (REWRITE_RULE[ebv_eq] th)) THEN
  SUBGOAL_THEN `eisfun D (E:A->A->bool) sEQ` ASSUME_TAC THENL
   [FIRST_ASSUM(ACCEPT_TAC o CONJUNCT1 o CONJUNCT2 o REWRITE_RULE[ebvatt]);
    ALL_TAC] THEN
  SUBGOAL_THEN `(pr:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[EOPAIR_IN]; ALL_TAC] THEN
  MP_TAC(ISPECL
         [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`w:A`;`sIN:A`;`sEQ:A`;
          `u:A`;`v:A`;`pr:A`] EBVATT_VAL) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(CONJUNCTS_THEN2 (K ALL_TAC)
    (X_CHOOSE_THEN `ve:A` STRIP_ASSUME_TAC)) THEN
  SUBGOAL_THEN `z:A = ve` SUBST_ALL_TAC THENL
   [MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`sEQ:A`;`pr:A`;`z:A`;`ve:A`]
           EAPPLY_UNIQUE) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MP_TAC(ISPECL
         [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`sIN:A`;`u:A`;`v:A`;`ve:A`]
         EBVEQ_SYM) THEN
  ASM_REWRITE_TAC[] THEN DISCH_TAC THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`a:A`;`w:A`;`sIN:A`;
    `sEQ:A`;`v:A`;`u:A`;`ve:A`] EBV_EQ_AT_STAGE) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC]);;

(* ------------------------------------------------------------------ *)
(* Boolean residuation (adjunction  a<=(b=>c)  <=>  a MEET b <= c).    *)
(* Reusable atoms for the F5 congruence reductions, which repeatedly   *)
(* turn EBVEQ_LB bounds  [[u=v]]<=(u(x)=>[[x in v]])  into meet bounds  *)
(* u(x) MEET [[u=v]] <= [[x in v]]  and back.  Pure Boolean algebra     *)
(* (ebimp x y = ~x JOIN y; EBALG_DISTRIB + ECOMPL_MEET_JOIN).          *)
(* ------------------------------------------------------------------ *)
let EBIMP_MEET_LE = prove
 (`!D (E:A->A->bool) p leq a b c i m.
      ebalg D E p leq /\ a IN D /\ b IN D /\ c IN D /\
      E a p /\ E b p /\ E c p /\
      ebimp D E p leq b c i /\ emeet D E p leq a b m /\ erel D E leq a i
      ==> erel D E leq m c`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `eporder D (E:A->A->bool) p leq` ASSUME_TAC THENL
   [ASM_MESON_TAC[EBALG_IMP_PORDER]; ALL_TAC] THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`p:A`;`leq:A`] EBALG_BOT) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `bot:A`) THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`p:A`;`leq:A`] EBALG_TOP) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `top:A`) THEN
  SUBGOAL_THEN
    `(bot:A) IN D /\ (E:A->A->bool) bot p /\ (top:A) IN D /\ E top p`
    STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[EBOT_IN; ETOP_IN]; ALL_TAC] THEN
  UNDISCH_TAC `ebimp D (E:A->A->bool) p leq b c i` THEN REWRITE_TAC[ebimp] THEN
  DISCH_THEN(X_CHOOSE_THEN `cb:A` STRIP_ASSUME_TAC) THEN
  SUBGOAL_THEN `(cb:A) IN D /\ (E:A->A->bool) cb p` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[ECOMPL_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `(i:A) IN D /\ (E:A->A->bool) i p` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[EJOIN_IN]; ALL_TAC] THEN
  MP_TAC(ISPECL
         [`D:A->bool`;`E:A->A->bool`;`p:A`;`leq:A`;`b:A`;`cb:A`;
          `bot:A`;`top:A`]
         ECOMPL_MEET_JOIN) THEN ASM_REWRITE_TAC[] THEN STRIP_TAC THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`p:A`;`leq:A`;`b:A`;`i:A`]
         EBALG_MEET) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `bi:A`) THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`p:A`;`leq:A`;`b:A`;`c:A`]
         EBALG_MEET) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `mbc:A`) THEN
  SUBGOAL_THEN `(bi:A) IN D /\ (E:A->A->bool) bi p /\ (mbc:A) IN D /\ E mbc p`
    STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[EMEET_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `ejoin D (E:A->A->bool) p leq bot mbc mbc` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`p:A`;`leq:A`;`bot:A`;`mbc:A`]
                 EJOIN_BOT) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `bi:A = mbc` SUBST_ALL_TAC THENL
   [MP_TAC(ISPECL
           [`D:A->bool`;`E:A->A->bool`;`p:A`;`leq:A`;`b:A`;`cb:A`;`c:A`;`i:A`;
            `bi:A`;`bot:A`;`mbc:A`;`mbc:A`] EBALG_DISTRIB) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq m a /\ erel D E leq m b`
    STRIP_ASSUME_TAC THENL
   [MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`p:A`;`leq:A`;`a:A`;`b:A`;`m:A`]
           EMEET_LE) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(m:A) IN D /\ (E:A->A->bool) m p` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[EMEET_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq m i` ASSUME_TAC THENL
   [MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`p:A`;`leq:A`;`m:A`;`a:A`;`i:A`]
           EPORDER_TRANS) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq m mbc` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`p:A`;`leq:A`;`b:A`;`i:A`;
                  `mbc:A`;`m:A`]
                 EMEET_GREATEST) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq mbc c` ASSUME_TAC THENL
   [MP_TAC(ISPECL
           [`D:A->bool`;`E:A->A->bool`;`p:A`;`leq:A`;`b:A`;`c:A`;`mbc:A`]
           EMEET_LE) THEN
    ASM_REWRITE_TAC[] THEN STRIP_TAC THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`p:A`;`leq:A`;`m:A`;`mbc:A`;`c:A`]
         EPORDER_TRANS) THEN
  ASM_REWRITE_TAC[]);;

let EBIMP_LE_IMP = prove
 (`!D (E:A->A->bool) p leq a b c i m.
      ebalg D E p leq /\ a IN D /\ b IN D /\ c IN D /\
      E a p /\ E b p /\ E c p /\
      ebimp D E p leq b c i /\ emeet D E p leq a b m /\ erel D E leq m c
      ==> erel D E leq a i`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `eporder D (E:A->A->bool) p leq` ASSUME_TAC THENL
   [ASM_MESON_TAC[EBALG_IMP_PORDER]; ALL_TAC] THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`p:A`;`leq:A`] EBALG_BOT) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `bot:A`) THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`p:A`;`leq:A`] EBALG_TOP) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `top:A`) THEN
  SUBGOAL_THEN
    `(bot:A) IN D /\ (E:A->A->bool) bot p /\ (top:A) IN D /\ E top p`
    STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[EBOT_IN; ETOP_IN]; ALL_TAC] THEN
  UNDISCH_TAC `ebimp D (E:A->A->bool) p leq b c i` THEN REWRITE_TAC[ebimp] THEN
  DISCH_THEN(X_CHOOSE_THEN `cb:A` STRIP_ASSUME_TAC) THEN
  SUBGOAL_THEN `(cb:A) IN D /\ (E:A->A->bool) cb p` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[ECOMPL_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `(i:A) IN D /\ (E:A->A->bool) i p` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[EJOIN_IN]; ALL_TAC] THEN
  MP_TAC(ISPECL
         [`D:A->bool`;`E:A->A->bool`;`p:A`;`leq:A`;`b:A`;`cb:A`;
          `bot:A`;`top:A`]
         ECOMPL_MEET_JOIN) THEN ASM_REWRITE_TAC[] THEN STRIP_TAC THEN
  SUBGOAL_THEN `(m:A) IN D /\ (E:A->A->bool) m p` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[EMEET_IN]; ALL_TAC] THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`p:A`;`leq:A`;`a:A`;`cb:A`]
         EBALG_MEET) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `acb:A`) THEN
  SUBGOAL_THEN `(acb:A) IN D /\ (E:A->A->bool) acb p` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[EMEET_IN]; ALL_TAC] THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`p:A`;`leq:A`;`m:A`;`acb:A`]
         EBALG_JOIN) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `am:A`) THEN
  SUBGOAL_THEN `(am:A) IN D /\ (E:A->A->bool) am p` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[EJOIN_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `emeet D (E:A->A->bool) p leq a top a` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`p:A`;`leq:A`;`top:A`;`a:A`]
                 EMEET_TOP) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `a:A = am` ASSUME_TAC THENL
   [MP_TAC(ISPECL
           [`D:A->bool`;`E:A->A->bool`;`p:A`;`leq:A`;`a:A`;`b:A`;
            `cb:A`;`top:A`;
            `a:A`;`m:A`;`acb:A`;`am:A`] EBALG_DISTRIB) THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq cb i /\ erel D E leq c i`
    STRIP_ASSUME_TAC THENL
   [MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`p:A`;`leq:A`;`cb:A`;`c:A`;`i:A`]
           EJOIN_GE) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq m i` ASSUME_TAC THENL
   [MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`p:A`;`leq:A`;`m:A`;`c:A`;`i:A`]
           EPORDER_TRANS) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq acb cb` ASSUME_TAC THENL
   [MP_TAC(ISPECL
           [`D:A->bool`;`E:A->A->bool`;`p:A`;`leq:A`;`a:A`;`cb:A`;`acb:A`]
           EMEET_LE) THEN
    ASM_REWRITE_TAC[] THEN STRIP_TAC THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq acb i` ASSUME_TAC THENL
   [MP_TAC(ISPECL
           [`D:A->bool`;`E:A->A->bool`;`p:A`;`leq:A`;`acb:A`;`cb:A`;`i:A`]
           EPORDER_TRANS) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq am i` ASSUME_TAC THENL
   [MP_TAC(ISPECL
           [`D:A->bool`;`E:A->A->bool`;`p:A`;`leq:A`;`m:A`;`acb:A`;
            `am:A`;`i:A`]
           EJOIN_LEAST) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  ASM_REWRITE_TAC[]);;

(* ------------------------------------------------------------------ *)
(* F5 congruence reduction algebra (pure Boolean algebra, measure-     *)
(* independent).  The three per-term obligations of EBV_IN_LE /        *)
(* EBV_EQ_GLB_STAGE that the congruence reductions produce, each a      *)
(* composition of residuation (EBIMP_MEET_LE / EBIMP_LE_IMP) with ONE   *)
(* combiner bound (EBVEQ_LB) and ONE lower-rank IH instance:            *)
(*   C2_TERM  qt MEET et <= (zeq => zin2)   [C2 <- C1-instance]          *)
(*   C1_TERM  qr MEET ar <= (zeq => zin2)   [C1 <- C3-instance]          *)
(*   C3_TERM  m12 <= (qp => pw)             [C3 <- C2-instance]          *)
(* These are the reusable cores of the C*_STEP stage lemmas.            *)
(* ------------------------------------------------------------------ *)
let C2_TERM = prove
 (`!D (E:A->A->bool) p leq qt et tv zeq zin2 imp w0 m1 m2.
      ebalg D E p leq /\
      qt IN D /\ et IN D /\ tv IN D /\ zeq IN D /\ zin2 IN D /\
      E qt p /\ E et p /\ E tv p /\ E zeq p /\ E zin2 p /\
      emeet D E p leq qt et m1 /\
      emeet D E p leq et tv m2 /\ erel D E leq m2 zin2 /\
      ebimp D E p leq qt tv imp /\ erel D E leq zeq imp /\
      ebimp D E p leq zeq zin2 w0
      ==> erel D E leq m1 w0`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `eporder D (E:A->A->bool) p leq` ASSUME_TAC THENL
   [ASM_MESON_TAC[EBALG_IMP_PORDER]; ALL_TAC] THEN
  SUBGOAL_THEN `(m1:A) IN D /\ (E:A->A->bool) m1 p` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[EMEET_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `(m2:A) IN D /\ (E:A->A->bool) m2 p` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[EMEET_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `(imp:A) IN D /\ (E:A->A->bool) imp p` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[EBIMP_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `(w0:A) IN D /\ (E:A->A->bool) w0 p` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[EBIMP_IN]; ALL_TAC] THEN
  (* m4 = zeq MEET qt ; m4 <= tv via residuation *)
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`p:A`;`leq:A`;`zeq:A`;`qt:A`]
         EBALG_MEET) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `m4:A`) THEN
  SUBGOAL_THEN `(m4:A) IN D /\ (E:A->A->bool) m4 p` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[EMEET_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq m4 tv` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`p:A`;`leq:A`;`zeq:A`;
                  `qt:A`;`tv:A`;
                  `imp:A`;`m4:A`] EBIMP_MEET_LE) THEN ASM_REWRITE_TAC[];
         ALL_TAC] THEN
  (* m3 = m1 MEET zeq *)
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`p:A`;`leq:A`;`m1:A`;`zeq:A`]
         EBALG_MEET) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `m3:A`) THEN
  SUBGOAL_THEN `(m3:A) IN D /\ (E:A->A->bool) m3 p` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[EMEET_IN]; ALL_TAC] THEN
  (* order facts *)
  SUBGOAL_THEN `erel D (E:A->A->bool) leq m3 m1 /\ erel D E leq m3 zeq`
    STRIP_ASSUME_TAC THENL
   [MP_TAC(ISPECL
           [`D:A->bool`;`E:A->A->bool`;`p:A`;`leq:A`;`m1:A`;`zeq:A`;`m3:A`]
           EMEET_LE) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq m1 qt /\ erel D E leq m1 et`
    STRIP_ASSUME_TAC THENL
   [MP_TAC(ISPECL
           [`D:A->bool`;`E:A->A->bool`;`p:A`;`leq:A`;`qt:A`;`et:A`;`m1:A`]
           EMEET_LE) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq m3 qt` ASSUME_TAC THENL
   [MP_TAC(ISPECL
           [`D:A->bool`;`E:A->A->bool`;`p:A`;`leq:A`;`m3:A`;`m1:A`;`qt:A`]
           EPORDER_TRANS) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq m3 et` ASSUME_TAC THENL
   [MP_TAC(ISPECL
           [`D:A->bool`;`E:A->A->bool`;`p:A`;`leq:A`;`m3:A`;`m1:A`;`et:A`]
           EPORDER_TRANS) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* m3 <= m4 = zeq MEET qt *)
  SUBGOAL_THEN `erel D (E:A->A->bool) leq m3 m4` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`p:A`;`leq:A`;`zeq:A`;`qt:A`;
                  `m4:A`;`m3:A`]
                 EMEET_GREATEST) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq m3 tv` ASSUME_TAC THENL
   [MP_TAC(ISPECL
           [`D:A->bool`;`E:A->A->bool`;`p:A`;`leq:A`;`m3:A`;`m4:A`;`tv:A`]
           EPORDER_TRANS) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* m3 <= m2 = et MEET tv, then <= zin2 *)
  SUBGOAL_THEN `erel D (E:A->A->bool) leq m3 m2` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`p:A`;`leq:A`;`et:A`;`tv:A`;
                  `m2:A`;`m3:A`]
                 EMEET_GREATEST) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq m3 zin2` ASSUME_TAC THENL
   [MP_TAC(ISPECL
           [`D:A->bool`;`E:A->A->bool`;`p:A`;`leq:A`;`m3:A`;`m2:A`;`zin2:A`]
           EPORDER_TRANS) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* conclude erel m1 w0 via converse residuation *)
  MATCH_MP_TAC(ISPECL
               [`D:A->bool`;`E:A->A->bool`;`p:A`;`leq:A`;`m1:A`;
                `zeq:A`;`zin2:A`;
                `w0:A`;`m3:A`] EBIMP_LE_IMP) THEN ASM_REWRITE_TAC[]);;

let C1_TERM = prove
 (`!D (E:A->A->bool) p leq qr ar br zeq zin2 w0 m1 mza mgb.
      ebalg D E p leq /\
      qr IN D /\ ar IN D /\ br IN D /\ zeq IN D /\ zin2 IN D /\
      E qr p /\ E ar p /\ E br p /\ E zeq p /\ E zin2 p /\
      emeet D E p leq qr ar m1 /\
      emeet D E p leq zeq ar mza /\ erel D E leq mza br /\
      emeet D E p leq qr br mgb /\ erel D E leq mgb zin2 /\
      ebimp D E p leq zeq zin2 w0
      ==> erel D E leq m1 w0`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `eporder D (E:A->A->bool) p leq` ASSUME_TAC THENL
   [ASM_MESON_TAC[EBALG_IMP_PORDER]; ALL_TAC] THEN
  SUBGOAL_THEN `(m1:A) IN D /\ (E:A->A->bool) m1 p` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[EMEET_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `(mza:A) IN D /\ (E:A->A->bool) mza p` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[EMEET_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `(mgb:A) IN D /\ (E:A->A->bool) mgb p` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[EMEET_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `(w0:A) IN D /\ (E:A->A->bool) w0 p` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[EBIMP_IN]; ALL_TAC] THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`p:A`;`leq:A`;`m1:A`;`zeq:A`]
         EBALG_MEET) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `m3:A`) THEN
  SUBGOAL_THEN `(m3:A) IN D /\ (E:A->A->bool) m3 p` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[EMEET_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq m3 m1 /\ erel D E leq m3 zeq`
    STRIP_ASSUME_TAC THENL
   [MP_TAC(ISPECL
           [`D:A->bool`;`E:A->A->bool`;`p:A`;`leq:A`;`m1:A`;`zeq:A`;`m3:A`]
           EMEET_LE) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq m1 qr /\ erel D E leq m1 ar`
    STRIP_ASSUME_TAC THENL
   [MP_TAC(ISPECL
           [`D:A->bool`;`E:A->A->bool`;`p:A`;`leq:A`;`qr:A`;`ar:A`;`m1:A`]
           EMEET_LE) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq m3 qr` ASSUME_TAC THENL
   [MP_TAC(ISPECL
           [`D:A->bool`;`E:A->A->bool`;`p:A`;`leq:A`;`m3:A`;`m1:A`;`qr:A`]
           EPORDER_TRANS) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq m3 ar` ASSUME_TAC THENL
   [MP_TAC(ISPECL
           [`D:A->bool`;`E:A->A->bool`;`p:A`;`leq:A`;`m3:A`;`m1:A`;`ar:A`]
           EPORDER_TRANS) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq m3 mza` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`p:A`;`leq:A`;`zeq:A`;`ar:A`;
                  `mza:A`;`m3:A`]
                 EMEET_GREATEST) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq m3 br` ASSUME_TAC THENL
   [MP_TAC(ISPECL
           [`D:A->bool`;`E:A->A->bool`;`p:A`;`leq:A`;`m3:A`;`mza:A`;`br:A`]
           EPORDER_TRANS) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq m3 mgb` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`p:A`;`leq:A`;`qr:A`;`br:A`;
                  `mgb:A`;`m3:A`]
                 EMEET_GREATEST) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq m3 zin2` ASSUME_TAC THENL
   [MP_TAC(ISPECL
           [`D:A->bool`;`E:A->A->bool`;`p:A`;`leq:A`;`m3:A`;`mgb:A`;`zin2:A`]
           EPORDER_TRANS) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MATCH_MP_TAC(ISPECL
               [`D:A->bool`;`E:A->A->bool`;`p:A`;`leq:A`;`m1:A`;
                `zeq:A`;`zin2:A`;
                `w0:A`;`m3:A`] EBIMP_LE_IMP) THEN ASM_REWRITE_TAC[]);;

let C3_TERM = prove
 (`!D (E:A->A->bool) p leq qp pv pw zeq1 zeq2 m12 imp1 w0 mpv2.
      ebalg D E p leq /\
      qp IN D /\ pv IN D /\ pw IN D /\ zeq1 IN D /\ zeq2 IN D /\
      E qp p /\ E pv p /\ E pw p /\ E zeq1 p /\ E zeq2 p /\
      emeet D E p leq zeq1 zeq2 m12 /\
      ebimp D E p leq qp pv imp1 /\ erel D E leq zeq1 imp1 /\
      emeet D E p leq pv zeq2 mpv2 /\ erel D E leq mpv2 pw /\
      ebimp D E p leq qp pw w0
      ==> erel D E leq m12 w0`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `eporder D (E:A->A->bool) p leq` ASSUME_TAC THENL
   [ASM_MESON_TAC[EBALG_IMP_PORDER]; ALL_TAC] THEN
  SUBGOAL_THEN `(m12:A) IN D /\ (E:A->A->bool) m12 p` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[EMEET_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `(mpv2:A) IN D /\ (E:A->A->bool) mpv2 p` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[EMEET_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `(imp1:A) IN D /\ (E:A->A->bool) imp1 p` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[EBIMP_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `(w0:A) IN D /\ (E:A->A->bool) w0 p` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[EBIMP_IN]; ALL_TAC] THEN
  (* m = m12 MEET qp *)
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`p:A`;`leq:A`;`m12:A`;`qp:A`]
         EBALG_MEET) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `m:A`) THEN
  SUBGOAL_THEN `(m:A) IN D /\ (E:A->A->bool) m p` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[EMEET_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq m m12 /\ erel D E leq m qp`
    STRIP_ASSUME_TAC THENL
   [MP_TAC(ISPECL
           [`D:A->bool`;`E:A->A->bool`;`p:A`;`leq:A`;`m12:A`;`qp:A`;`m:A`]
           EMEET_LE) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq m12 zeq1 /\ erel D E leq m12 zeq2`
    STRIP_ASSUME_TAC THENL
   [MP_TAC(ISPECL
           [`D:A->bool`;`E:A->A->bool`;`p:A`;`leq:A`;`zeq1:A`;`zeq2:A`;`m12:A`]
           EMEET_LE) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq m zeq1` ASSUME_TAC THENL
   [MP_TAC(ISPECL
           [`D:A->bool`;`E:A->A->bool`;`p:A`;`leq:A`;`m:A`;`m12:A`;`zeq1:A`]
           EPORDER_TRANS) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq m zeq2` ASSUME_TAC THENL
   [MP_TAC(ISPECL
           [`D:A->bool`;`E:A->A->bool`;`p:A`;`leq:A`;`m:A`;`m12:A`;`zeq2:A`]
           EPORDER_TRANS) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* m <= zeq1 MEET qp <= pv  via EBIMP_MEET_LE *)
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`p:A`;`leq:A`;`zeq1:A`;`qp:A`]
         EBALG_MEET) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `mzq:A`) THEN
  SUBGOAL_THEN `(mzq:A) IN D /\ (E:A->A->bool) mzq p` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[EMEET_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq mzq pv` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`p:A`;`leq:A`;`zeq1:A`;
                  `qp:A`;`pv:A`;
                  `imp1:A`;`mzq:A`] EBIMP_MEET_LE) THEN ASM_REWRITE_TAC[];
         ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq m mzq` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`p:A`;`leq:A`;`zeq1:A`;`qp:A`;
                  `mzq:A`;`m:A`]
                 EMEET_GREATEST) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq m pv` ASSUME_TAC THENL
   [MP_TAC(ISPECL
           [`D:A->bool`;`E:A->A->bool`;`p:A`;`leq:A`;`m:A`;`mzq:A`;`pv:A`]
           EPORDER_TRANS) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* m <= pv MEET zeq2 = mpv2 <= pw *)
  SUBGOAL_THEN `erel D (E:A->A->bool) leq m mpv2` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`p:A`;`leq:A`;`pv:A`;`zeq2:A`;
                  `mpv2:A`;`m:A`]
                 EMEET_GREATEST) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq m pw` ASSUME_TAC THENL
   [MP_TAC(ISPECL
           [`D:A->bool`;`E:A->A->bool`;`p:A`;`leq:A`;`m:A`;`mpv2:A`;`pw:A`]
           EPORDER_TRANS) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MATCH_MP_TAC(ISPECL
               [`D:A->bool`;`E:A->A->bool`;`p:A`;`leq:A`;`m12:A`;`qp:A`;`pw:A`;
                `w0:A`;`m:A`] EBIMP_LE_IMP) THEN ASM_REWRITE_TAC[]);;

(* ------------------------------------------------------------------ *)
(* F5 congruence reduction STEP lemmas (stage-level).  Each takes the  *)
(* lower-rank IH instances as an EXPLICIT dom-membership hypothesis     *)
(* (measure-agnostic, twin of EBV_EQ_REFL_STEP), plugging the *_TERM    *)
(* cores into EBV_IN_LE (C1/C2) or EBV_EQ_GLB_STAGE (C3):               *)
(*   C2_STEP  [[u=v]] MEET [[ww in u]] <= [[ww in v]]   from C1-instances *)
(*   C1_STEP  [[a=b]] MEET [[a in W]]  <= [[b in W]]    from C3-instances *)
(*   C3_STEP  [[u=v]] MEET [[v=w]]     <= [[u=w]]       from C2-instances *)
(* Only the mutual-induction wrapper (needing the natural-sum measure)  *)
(* remains to assemble the fundamental congruence C1/C2/C3.             *)
(* ------------------------------------------------------------------ *)
let C2_STEP = prove
 (`!D (E:A->A->bool) B leq a w sIN sEQ u v ww zeq zin zin2.
      model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
      a IN D /\ eordinal D E a /\ ebnstage D E B a w /\ w IN D /\
      u IN D /\ v IN D /\ ww IN D /\ E u w /\ E v w /\ E ww w /\
      ebvatt D E B leq w sIN sEQ /\
      ebveq D E B leq sIN u v zeq /\
      ebvin D E B leq sEQ u ww zin /\
      zin2 IN D /\ E zin2 B /\
      (!y qy ey tv m.
          y IN D /\ eapply D E u y qy /\
          ebv_eq D E B leq ww y ey /\ ebv_in D E B leq y v tv /\
          emeet D E B leq ey tv m
          ==> erel D E leq m zin2)
      ==> !m. m IN D /\ emeet D E B leq zeq zin m ==> erel D E leq m zin2`,
  REPEAT GEN_TAC THEN REPEAT STRIP_TAC THEN
  FIRST_X_ASSUM(fun th -> if is_forall(concl th) then LABEL_TAC "ih" th else
                failwith "no") THEN
  SUBGOAL_THEN `ebalg D (E:A->A->bool) B leq` ASSUME_TAC THENL
   [ASM_MESON_TAC[ECBA_IMP_BALG]; ALL_TAC] THEN
  SUBGOAL_THEN `eporder D (E:A->A->bool) B leq` ASSUME_TAC THENL
   [ASM_MESON_TAC[EBALG_IMP_PORDER]; ALL_TAC] THEN
  SUBGOAL_THEN `bname D (E:A->A->bool) B u` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`a:A`;`w:A`;`u:A`]
                 BNAME_STAGE) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(zeq:A) IN D /\ (E:A->A->bool) zeq B` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[EBVEQ_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `(zin:A) IN D /\ (E:A->A->bool) zin B` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[EBVIN_IN]; ALL_TAC] THEN
  (* w0 = zeq => zin2 *)
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`zeq:A`;`zin2:A`]
         EBIMP_EXISTS) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `w0:A`) THEN
  SUBGOAL_THEN `(w0:A) IN D /\ (E:A->A->bool) w0 B` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[EBIMP_IN]; ALL_TAC] THEN
  (* erel zin w0 via EBV_IN_LE *)
  SUBGOAL_THEN `erel D (E:A->A->bool) leq zin w0` ASSUME_TAC THENL
   [MP_TAC(ISPECL
           [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`a:A`;`w:A`;
            `sIN:A`;`sEQ:A`;
            `ww:A`;`u:A`;`zin:A`;`w0:A`] EBV_IN_LE) THEN
    ASM_REWRITE_TAC[] THEN DISCH_THEN MATCH_MP_TAC THEN
    MAP_EVERY X_GEN_TAC [`y:A`;`qy:A`;`ey:A`;`c:A`] THEN STRIP_TAC THEN
    SUBGOAL_THEN `(E:A->A->bool) y w` ASSUME_TAC THENL
     [MATCH_MP_TAC(ISPECL
                   [`D:A->bool`;`E:A->A->bool`;`B:A`;`a:A`;`w:A`;`u:A`;
                    `y:A`;`qy:A`]
                   STAGE_DOM_CLOSED) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    (* pr = <y,v>, val = sIN<y,v> = [[y in v]] *)
    MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`y:A`;`v:A`] EOPAIR_EXISTS) THEN
    ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `pr:A`) THEN
    SUBGOAL_THEN `(pr:A) IN D` ASSUME_TAC THENL
     [ASM_MESON_TAC[EOPAIR_IN]; ALL_TAC] THEN
    MP_TAC(ISPECL
           [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`w:A`;`sIN:A`;`sEQ:A`;
            `y:A`;`v:A`;`pr:A`] EBVATT_VAL) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(CONJUNCTS_THEN2 (X_CHOOSE_THEN `tv:A` STRIP_ASSUME_TAC)
               (K ALL_TAC)) THEN
    SUBGOAL_THEN `ebv_in D (E:A->A->bool) B leq y v tv` ASSUME_TAC THENL
     [MATCH_MP_TAC(ISPECL
                   [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`a:A`;
                    `w:A`;`sIN:A`;
                    `sEQ:A`;`y:A`;`v:A`;`tv:A`] EBV_IN_AT_STAGE) THEN
               ASM_REWRITE_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN `(tv:A) IN D /\ (E:A->A->bool) tv B` STRIP_ASSUME_TAC THENL
     [ASM_MESON_TAC[EBVIN_IN]; ALL_TAC] THEN
    SUBGOAL_THEN `(E:A->A->bool) qy B` ASSUME_TAC THENL
     [MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`u:A`;`y:A`;`qy:A`]
             BNAME_APPLY_IN_B) THEN
      ASM_REWRITE_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN `(E:A->A->bool) ey B` ASSUME_TAC THENL
     [MP_TAC(ISPECL
             [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`ww:A`;`y:A`;`ey:A`]
             EBV_EQ_IN_B) THEN
      ASM_REWRITE_TAC[]; ALL_TAC] THEN
    (* combiner c' = qy => tv, and EBVEQ_LB gives zeq <= c' *)
    MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`qy:A`;`tv:A`]
           EBIMP_EXISTS) THEN
    ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `cpr:A`) THEN
    SUBGOAL_THEN `bveqcomb D (E:A->A->bool) B leq sIN u v cpr` ASSUME_TAC THENL
     [REWRITE_TAC[bveqcomb] THEN
      MAP_EVERY EXISTS_TAC [`y:A`;`qy:A`;`tv:A`;`pr:A`] THEN ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    SUBGOAL_THEN `erel D (E:A->A->bool) leq zeq cpr` ASSUME_TAC THENL
     [MP_TAC(ISPECL
             [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`sIN:A`;`u:A`;
              `v:A`;`zeq:A`;
              `cpr:A`] EBVEQ_LB) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    (* C1 instance: ey MEET tv <= zin2 *)
    MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`ey:A`;`tv:A`]
           EBALG_MEET) THEN
    ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `m2:A`) THEN
    SUBGOAL_THEN `erel D (E:A->A->bool) leq m2 zin2` ASSUME_TAC THENL
     [USE_THEN "ih"
      (fun th ->
       MATCH_MP_TAC(ISPECL [`y:A`;`qy:A`;`ey:A`;`tv:A`;`m2:A`] th)) THEN
      ASM_REWRITE_TAC[]; ALL_TAC] THEN
    (* apply C2_TERM *)
    MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`qy:A`;
                  `ey:A`;`tv:A`;
                  `zeq:A`;`zin2:A`;`cpr:A`;`w0:A`;`c:A`;`m2:A`] C2_TERM) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* conclude: for m = zeq MEET zin, erel m zin2 via residuation *)
  SUBGOAL_THEN `emeet D (E:A->A->bool) B leq zin zeq m` ASSUME_TAC THENL
   [MATCH_MP_TAC EMEET_SYM THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MATCH_MP_TAC(ISPECL
               [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`zin:A`;
                `zeq:A`;`zin2:A`;
                `w0:A`;`m:A`] EBIMP_MEET_LE) THEN ASM_REWRITE_TAC[]);;

(* ------------------------------------------------------------------ *)
(* Ordinal MIN (binary intersection).  ebinter x y z : z = x INTER y   *)
(* (via ZF_SEPARATION on x along "w in y").  For ordinals a,b, z is an  *)
(* ordinal and z = a \/ z = b (the ORDINAL MIN) -- the companion of     *)
(* ebunion/EBUNION_ORDINAL_MAX.  First lemma of the congruence-wrapper  *)
(* MEASURE (the multiset/natural-sum order on rank-triples needs        *)
(* max=ebunion, median, min=ebinter).                                  *)
(* ------------------------------------------------------------------ *)
let ebinter = new_definition
  `ebinter D (E:A->A->bool) x y z <=>
        z IN D /\ !w. w IN D ==> (E w z <=> E w x /\ E w y)`;;
let EBINTER_IN = prove
 (`!D (E:A->A->bool) x y z. ebinter D E x y z ==> z IN D`,
  SIMP_TAC[ebinter]);;
let EBINTER_LB = prove
 (`!D (E:A->A->bool) x y z w.
      ebinter D E x y z /\ w IN D /\ E w z ==> E w x /\ E w y`,
  REWRITE_TAC[ebinter] THEN MESON_TAC[]);;
let EBINTER_EXISTS = prove
 (`!D (E:A->A->bool) x y.
      model D E ZF_AX /\ x IN D /\ y IN D ==> ?z. ebinter D E x y z`,
  REPEAT STRIP_TAC THEN
  FIRST_ASSUM(X_CHOOSE_TAC `v0:num->A` o MATCH_MP VALUATION_EXISTS o
              MATCH_MP MODEL_NONEMPTY) THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`] ZF_SEPARATION) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(MP_TAC o SPECL
             [`0 %% 1`;`0`;`(1 |-> (y:A)) (v0:num->A)`;`x:A`]) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[] THEN MATCH_MP_TAC VALUATION_VALMOD THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `z:A` STRIP_ASSUME_TAC) THEN
  EXISTS_TAC `z:A` THEN REWRITE_TAC[ebinter] THEN ASM_REWRITE_TAC[] THEN
  X_GEN_TAC `w:A` THEN DISCH_TAC THEN
  FIRST_X_ASSUM(MP_TAC o SPEC `w:A`) THEN ASM_REWRITE_TAC[holds] THEN
  SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER; ARITH_EQ]);;
let EBINTER_ORDINAL_MEM = prove
 (`!D (E:A->A->bool) a b z.
      model D E ZF_AX /\ eordinal D E a /\ eordinal D E b /\ ebinter D E a b z
      ==> z = a \/ z = b`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `(a:A) IN D /\ (b:A) IN D /\ (z:A) IN D` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[EORDINAL_IN; EBINTER_IN]; ALL_TAC] THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`a:A`;`b:A`]
         EORDINAL_TRICHOTOMY) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(REPEAT_TCL DISJ_CASES_THEN ASSUME_TAC) THENL
   [ (* E a b: z = a *)
    DISJ1_TAC THEN
    SUBGOAL_THEN `esubset D (E:A->A->bool) a b` ASSUME_TAC THENL
     [UNDISCH_TAC `eordinal D (E:A->A->bool) b` THEN
      REWRITE_TAC[eordinal; etransitive] THEN
      STRIP_TAC THEN FIRST_X_ASSUM(MP_TAC o SPEC `a:A`) THEN ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    FIRST_ASSUM(MATCH_MP_TAC o MATCH_MP ZF_EXTENSIONALITY) THEN
    ASM_REWRITE_TAC[] THEN
    X_GEN_TAC `w:A` THEN DISCH_TAC THEN
    MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`a:A`;`b:A`;`z:A`;`w:A`]
           EBINTER_LB) THEN
    ASM_REWRITE_TAC[] THEN
    UNDISCH_TAC `ebinter D (E:A->A->bool) a b z` THEN REWRITE_TAC[ebinter] THEN
    DISCH_THEN(MP_TAC o SPEC `w:A` o CONJUNCT2) THEN ASM_REWRITE_TAC[] THEN
    UNDISCH_TAC `esubset D (E:A->A->bool) a b` THEN REWRITE_TAC[esubset] THEN
    ASM_MESON_TAC[];
    (* a = b: z = a *)
    DISJ1_TAC THEN
    FIRST_ASSUM(MATCH_MP_TAC o MATCH_MP ZF_EXTENSIONALITY) THEN
    ASM_REWRITE_TAC[] THEN
    UNDISCH_TAC `ebinter D (E:A->A->bool) a b z` THEN
    ASM_REWRITE_TAC[ebinter] THEN
    MESON_TAC[];
    (* E b a: z = b *)
    DISJ2_TAC THEN
    SUBGOAL_THEN `esubset D (E:A->A->bool) b a` ASSUME_TAC THENL
     [UNDISCH_TAC `eordinal D (E:A->A->bool) a` THEN
      REWRITE_TAC[eordinal; etransitive] THEN
      STRIP_TAC THEN FIRST_X_ASSUM(MP_TAC o SPEC `b:A`) THEN ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    FIRST_ASSUM(MATCH_MP_TAC o MATCH_MP ZF_EXTENSIONALITY) THEN
    ASM_REWRITE_TAC[] THEN
    X_GEN_TAC `w:A` THEN DISCH_TAC THEN
    MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`a:A`;`b:A`;`z:A`;`w:A`]
           EBINTER_LB) THEN
    ASM_REWRITE_TAC[] THEN
    UNDISCH_TAC `ebinter D (E:A->A->bool) a b z` THEN REWRITE_TAC[ebinter] THEN
    DISCH_THEN(MP_TAC o SPEC `w:A` o CONJUNCT2) THEN ASM_REWRITE_TAC[] THEN
    UNDISCH_TAC `esubset D (E:A->A->bool) b a` THEN REWRITE_TAC[esubset] THEN
    ASM_MESON_TAC[]]);;

let EBINTER_ORDINAL = prove
 (`!D (E:A->A->bool) a b z.
      model D E ZF_AX /\ eordinal D E a /\ eordinal D E b /\ ebinter D E a b z
      ==> eordinal D E z`,
  REPEAT STRIP_TAC THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`a:A`;`b:A`;`z:A`]
         EBINTER_ORDINAL_MEM) THEN
  ASM_REWRITE_TAC[] THEN STRIP_TAC THEN ASM_REWRITE_TAC[]);;

(* ------------------------------------------------------------------ *)
(* Ordinal MIN, precise value given the ordering (duals of             *)
(* EBUNION_ORD_MAX_EQ / EBUNION_ORD_MAX_EQ'): a<=b => a INTER b = a;    *)
(* b<=a => a INTER b = b.  Completes the ordinal min/max toolkit for    *)
(* the sorted-rank-triple measure (max=ebunion, min=ebinter).          *)
(* ------------------------------------------------------------------ *)

(* ------------------------------------------------------------------ *)
(* Monotonicity of union/intersection (ordinal <= = esubset), one- and *)
(* both-argument.  Foundation for the sorted-rank-triple measure:      *)
(* max3/med3/min3 monotone in each rank ==> the componentwise-<= half   *)
(* (H1-H3) of the multiset-decrease.  Clean via the E-characterization  *)
(* (EBUNION_ALT / ebinter def), no case analysis.                      *)
(* ------------------------------------------------------------------ *)
let EBUNION_MONO = prove
 (`!D (E:A->A->bool) a a' b m m'.
      model D E ZF_AX /\ a IN D /\ a' IN D /\ b IN D /\
      ebunion D E a b m /\ ebunion D E a' b m' /\ esubset D E a a'
      ==> esubset D E m m'`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `!w:A. w IN D ==> ((E:A->A->bool) w m <=> E w a \/ E w b)`
    (LABEL_TAC "mc") THENL
   [MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`a:A`;`b:A`;`m:A`]
           EBUNION_ALT) THEN
    ASM_REWRITE_TAC[] THEN
    DISCH_THEN(fun th -> ACCEPT_TAC(CONJUNCT2 th)); ALL_TAC] THEN
  SUBGOAL_THEN `!w:A. w IN D ==> ((E:A->A->bool) w m' <=> E w a' \/ E w b)`
    (LABEL_TAC "mc'") THENL
   [MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`a':A`;`b:A`;`m':A`]
           EBUNION_ALT) THEN
    ASM_REWRITE_TAC[] THEN
    DISCH_THEN(fun th -> ACCEPT_TAC(CONJUNCT2 th)); ALL_TAC] THEN
  REWRITE_TAC[esubset] THEN X_GEN_TAC `w:A` THEN STRIP_TAC THEN
  USE_THEN "mc'" (fun th -> MP_TAC(SPEC `w:A` th)) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  USE_THEN "mc" (fun th -> MP_TAC(SPEC `w:A` th)) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(fun th -> MP_TAC(EQ_MP th (ASSUME `(E:A->A->bool) w m`))) THEN
  DISCH_THEN(DISJ_CASES_THEN ASSUME_TAC) THENL
   [DISJ1_TAC THEN UNDISCH_TAC `esubset D (E:A->A->bool) a a'` THEN
    REWRITE_TAC[esubset] THEN
    DISCH_THEN(MP_TAC o SPEC `w:A`) THEN ASM_REWRITE_TAC[];
    DISJ2_TAC THEN ASM_REWRITE_TAC[]]);;

let EBINTER_MONO = prove
 (`!D (E:A->A->bool) a a' b m m'.
      a IN D /\ a' IN D /\ b IN D /\
      ebinter D E a b m /\ ebinter D E a' b m' /\ esubset D E a a'
      ==> esubset D E m m'`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  REWRITE_TAC[esubset] THEN X_GEN_TAC `w:A` THEN STRIP_TAC THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`a:A`;`b:A`;`m:A`;`w:A`]
         EBINTER_LB) THEN
  ASM_REWRITE_TAC[] THEN STRIP_TAC THEN
  UNDISCH_TAC `ebinter D (E:A->A->bool) a' b m'` THEN REWRITE_TAC[ebinter] THEN
  DISCH_THEN(MP_TAC o SPEC `w:A` o CONJUNCT2) THEN ASM_REWRITE_TAC[] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  UNDISCH_TAC `esubset D (E:A->A->bool) a a'` THEN REWRITE_TAC[esubset] THEN
  ASM_MESON_TAC[]);;

let EBUNION_MONO_BOTH = prove
 (`!D (E:A->A->bool) x y x' y' m m'.
      model D E ZF_AX /\ x IN D /\ y IN D /\ x' IN D /\ y' IN D /\
      ebunion D E x y m /\ ebunion D E x' y' m' /\ esubset D E x x' /\
        esubset D E y y'
      ==> esubset D E m m'`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `!w:A. w IN D ==> ((E:A->A->bool) w m <=> E w x \/ E w y)`
    (LABEL_TAC "mc") THENL
   [MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`x:A`;`y:A`;`m:A`]
           EBUNION_ALT) THEN
    ASM_REWRITE_TAC[] THEN DISCH_THEN(fun th -> ACCEPT_TAC(CONJUNCT2 th));
    ALL_TAC] THEN
  SUBGOAL_THEN `!w:A. w IN D ==> ((E:A->A->bool) w m' <=> E w x' \/ E w y')`
    (LABEL_TAC "mc'") THENL
   [MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`x':A`;`y':A`;`m':A`]
           EBUNION_ALT) THEN
    ASM_REWRITE_TAC[] THEN DISCH_THEN(fun th -> ACCEPT_TAC(CONJUNCT2 th));
    ALL_TAC] THEN
  REWRITE_TAC[esubset] THEN X_GEN_TAC `w:A` THEN STRIP_TAC THEN
  USE_THEN "mc'" (fun th -> MP_TAC(SPEC `w:A` th)) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  USE_THEN "mc" (fun th -> MP_TAC(SPEC `w:A` th)) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(fun th -> MP_TAC(EQ_MP th (ASSUME `(E:A->A->bool) w m`))) THEN
  DISCH_THEN(DISJ_CASES_THEN ASSUME_TAC) THENL
   [DISJ1_TAC THEN UNDISCH_TAC `esubset D (E:A->A->bool) x x'` THEN
    REWRITE_TAC[esubset] THEN
    DISCH_THEN(MP_TAC o SPEC `w:A`) THEN ASM_REWRITE_TAC[];
    DISJ2_TAC THEN UNDISCH_TAC `esubset D (E:A->A->bool) y y'` THEN
    REWRITE_TAC[esubset] THEN
    DISCH_THEN(MP_TAC o SPEC `w:A`) THEN ASM_REWRITE_TAC[]]);;

let EBINTER_MONO_BOTH = prove
 (`!D (E:A->A->bool) x y x' y' m m'.
      x IN D /\ y IN D /\ x' IN D /\ y' IN D /\
      ebinter D E x y m /\ ebinter D E x' y' m' /\ esubset D E x x' /\
        esubset D E y y'
      ==> esubset D E m m'`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  REWRITE_TAC[esubset] THEN X_GEN_TAC `w:A` THEN STRIP_TAC THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`x:A`;`y:A`;`m:A`;`w:A`]
         EBINTER_LB) THEN
  ASM_REWRITE_TAC[] THEN STRIP_TAC THEN
  UNDISCH_TAC `ebinter D (E:A->A->bool) x' y' m'` THEN
  REWRITE_TAC[ebinter] THEN
  DISCH_THEN(MP_TAC o SPEC `w:A` o CONJUNCT2) THEN ASM_REWRITE_TAC[] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN CONJ_TAC THENL
   [UNDISCH_TAC `esubset D (E:A->A->bool) x x'` THEN REWRITE_TAC[esubset] THEN
    DISCH_THEN(MP_TAC o SPEC `w:A`) THEN ASM_REWRITE_TAC[];
    UNDISCH_TAC `esubset D (E:A->A->bool) y y'` THEN REWRITE_TAC[esubset] THEN
    DISCH_THEN(MP_TAC o SPEC `w:A`) THEN ASM_REWRITE_TAC[]]);;

(* ------------------------------------------------------------------ *)
(* Sorted rank-triple for the congruence-wrapper MEASURE.  For ordinals*)
(* a,b,c: emax3 = a U b U c (max), emin3 = a INTER b INTER c (min),     *)
(* emed3 = (aINTERb) U (aINTERc) U (bINTERc) (median).  Each EXISTS +   *)
(* is an ordinal + is MONOTONE in the varied argument (H1-H3: the       *)
(* componentwise-<= half of the multiset-decrease, clean via the        *)
(* monotonicity toolkit).  Remaining: H4 (not-all-equal) + MULTISET_DEC.*)
(* ------------------------------------------------------------------ *)
let ESUBSET_REFL = prove
 (`!D (E:A->A->bool) x. esubset D E x x`, REWRITE_TAC[esubset] THEN
  MESON_TAC[]);;
let emax3 = new_definition
  `emax3 D (E:A->A->bool) a b c M <=> ?p. ebunion D E a b p /\
   ebunion D E p c M`;;
let emin3 = new_definition
  `emin3 D (E:A->A->bool) a b c m <=> ?p. ebinter D E a b p /\
   ebinter D E p c m`;;
let emed3 = new_definition
  `emed3 D (E:A->A->bool) a b c d <=>
     ?rab rac rbc u. ebinter D E a b rab /\ ebinter D E a c rac /\
       ebinter D E b c rbc /\
                     ebunion D E rab rac u /\ ebunion D E u rbc d`;;
let EMAX3_EXISTS = prove
 (`!D (E:A->A->bool) a b c.
      model D E ZF_AX /\ a IN D /\ b IN D /\ c IN D ==> ?M. emax3 D E a b c M`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[emax3] THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`a:A`;`b:A`] EBUNION_EXISTS) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `p:A`) THEN
  SUBGOAL_THEN `(p:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[EBUNION_IN]; ALL_TAC] THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`p:A`;`c:A`] EBUNION_EXISTS) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `M:A`) THEN
  EXISTS_TAC `M:A` THEN EXISTS_TAC `p:A` THEN ASM_REWRITE_TAC[]);;
let EMIN3_EXISTS = prove
 (`!D (E:A->A->bool) a b c.
      model D E ZF_AX /\ a IN D /\ b IN D /\ c IN D ==> ?m. emin3 D E a b c m`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[emin3] THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`a:A`;`b:A`] EBINTER_EXISTS) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `p:A`) THEN
  SUBGOAL_THEN `(p:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[EBINTER_IN]; ALL_TAC] THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`p:A`;`c:A`] EBINTER_EXISTS) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `m:A`) THEN
  EXISTS_TAC `m:A` THEN EXISTS_TAC `p:A` THEN ASM_REWRITE_TAC[]);;
let EMED3_EXISTS = prove
 (`!D (E:A->A->bool) a b c.
      model D E ZF_AX /\ a IN D /\ b IN D /\ c IN D ==> ?d. emed3 D E a b c d`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[emed3] THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`a:A`;`b:A`] EBINTER_EXISTS) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_TAC `rab:A`) THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`a:A`;`c:A`] EBINTER_EXISTS) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_TAC `rac:A`) THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`b:A`;`c:A`] EBINTER_EXISTS) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_TAC `rbc:A`) THEN
  SUBGOAL_THEN `(rab:A) IN D /\ (rac:A) IN D /\ (rbc:A) IN D`
    STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[EBINTER_IN]; ALL_TAC] THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`rab:A`;`rac:A`]
         EBUNION_EXISTS) THEN ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_TAC `u:A`) THEN
  SUBGOAL_THEN `(u:A) IN D` ASSUME_TAC THENL
  [ASM_MESON_TAC[EBUNION_IN]; ALL_TAC] THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`u:A`;`rbc:A`] EBUNION_EXISTS) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_TAC `d:A`) THEN
  MAP_EVERY EXISTS_TAC [`d:A`;`rab:A`;`rac:A`;`rbc:A`;`u:A`] THEN
  ASM_REWRITE_TAC[]);;
let EMAX3_ORDINAL = prove
 (`!D (E:A->A->bool) a b c M.
      model D E ZF_AX /\ eordinal D E a /\ eordinal D E b /\ eordinal D E c /\
      emax3 D E a b c M ==> eordinal D E M`,
  REPEAT GEN_TAC THEN REWRITE_TAC[emax3] THEN STRIP_TAC THEN
  SUBGOAL_THEN `eordinal D (E:A->A->bool) p` ASSUME_TAC THENL
   [MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`a:A`;`b:A`;`p:A`]
           EBUNION_ORDINAL_MAX) THEN
    ASM_REWRITE_TAC[] THEN STRIP_TAC THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`p:A`;`c:A`;`M:A`]
         EBUNION_ORDINAL_MAX) THEN
  ASM_REWRITE_TAC[] THEN STRIP_TAC THEN ASM_REWRITE_TAC[]);;
let EMIN3_ORDINAL = prove
 (`!D (E:A->A->bool) a b c m.
      model D E ZF_AX /\ eordinal D E a /\ eordinal D E b /\ eordinal D E c /\
      emin3 D E a b c m ==> eordinal D E m`,
  REPEAT GEN_TAC THEN REWRITE_TAC[emin3] THEN STRIP_TAC THEN
  SUBGOAL_THEN `eordinal D (E:A->A->bool) p` ASSUME_TAC THENL
   [ASM_MESON_TAC[EBINTER_ORDINAL]; ALL_TAC] THEN
  ASM_MESON_TAC[EBINTER_ORDINAL]);;
let EMED3_ORDINAL = prove
 (`!D (E:A->A->bool) a b c d.
      model D E ZF_AX /\ eordinal D E a /\ eordinal D E b /\ eordinal D E c /\
      emed3 D E a b c d ==> eordinal D E d`,
  REPEAT GEN_TAC THEN REWRITE_TAC[emed3] THEN STRIP_TAC THEN
  SUBGOAL_THEN
    `eordinal D (E:A->A->bool) rab /\ eordinal D E rac /\ eordinal D E rbc`
  STRIP_ASSUME_TAC THENL [ASM_MESON_TAC[EBINTER_ORDINAL]; ALL_TAC] THEN
  SUBGOAL_THEN `eordinal D (E:A->A->bool) u` ASSUME_TAC THENL
   [MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`rab:A`;`rac:A`;`u:A`]
           EBUNION_ORDINAL_MAX) THEN
    ASM_REWRITE_TAC[] THEN STRIP_TAC THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`u:A`;`rbc:A`;`d:A`]
         EBUNION_ORDINAL_MAX) THEN
  ASM_REWRITE_TAC[] THEN STRIP_TAC THEN ASM_REWRITE_TAC[]);;
let EMAX3_MONO = prove
 (`!D (E:A->A->bool) a a' b c M M'.
      model D E ZF_AX /\ a IN D /\ a' IN D /\ b IN D /\ c IN D /\
      emax3 D E a b c M /\ emax3 D E a' b c M' /\ esubset D E a' a
      ==> esubset D E M' M`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  UNDISCH_TAC `emax3 D (E:A->A->bool) a b c M` THEN REWRITE_TAC[emax3] THEN
  DISCH_THEN(X_CHOOSE_THEN `p:A` STRIP_ASSUME_TAC) THEN
  UNDISCH_TAC `emax3 D (E:A->A->bool) a' b c M'` THEN REWRITE_TAC[emax3] THEN
  DISCH_THEN(X_CHOOSE_THEN `p':A` STRIP_ASSUME_TAC) THEN
  SUBGOAL_THEN `(p:A) IN D /\ (p':A) IN D` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[EBUNION_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `esubset D (E:A->A->bool) p' p` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`a':A`;`a:A`;`b:A`;`p':A`;`p:A`]
                 EBUNION_MONO) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MATCH_MP_TAC(ISPECL
               [`D:A->bool`;`E:A->A->bool`;`p':A`;`c:A`;`p:A`;`c:A`;`M':A`;
                `M:A`] EBUNION_MONO_BOTH) THEN
  ASM_REWRITE_TAC[ESUBSET_REFL]);;
let EMIN3_MONO = prove
 (`!D (E:A->A->bool) a a' b c m m'.
      model D E ZF_AX /\ a IN D /\ a' IN D /\ b IN D /\ c IN D /\
      emin3 D E a b c m /\ emin3 D E a' b c m' /\ esubset D E a' a
      ==> esubset D E m' m`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  UNDISCH_TAC `emin3 D (E:A->A->bool) a b c m` THEN REWRITE_TAC[emin3] THEN
  DISCH_THEN(X_CHOOSE_THEN `p:A` STRIP_ASSUME_TAC) THEN
  UNDISCH_TAC `emin3 D (E:A->A->bool) a' b c m'` THEN REWRITE_TAC[emin3] THEN
  DISCH_THEN(X_CHOOSE_THEN `p':A` STRIP_ASSUME_TAC) THEN
  SUBGOAL_THEN `(p:A) IN D /\ (p':A) IN D` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[EBINTER_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `esubset D (E:A->A->bool) p' p` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`a':A`;`a:A`;`b:A`;`p':A`;`p:A`]
                 EBINTER_MONO) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MATCH_MP_TAC(ISPECL
               [`D:A->bool`;`E:A->A->bool`;`p':A`;`c:A`;`p:A`;`c:A`;`m':A`;
                `m:A`] EBINTER_MONO_BOTH) THEN
  ASM_REWRITE_TAC[ESUBSET_REFL]);;
let EMED3_MONO = prove
 (`!D (E:A->A->bool) a a' b c d d'.
      model D E ZF_AX /\ a IN D /\ a' IN D /\ b IN D /\ c IN D /\
      emed3 D E a b c d /\ emed3 D E a' b c d' /\ esubset D E a' a
      ==> esubset D E d' d`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  UNDISCH_TAC `emed3 D (E:A->A->bool) a b c d` THEN REWRITE_TAC[emed3] THEN
  DISCH_THEN(X_CHOOSE_THEN `rab:A`
             (X_CHOOSE_THEN `rac:A` (X_CHOOSE_THEN `rbc:A`
                                     (X_CHOOSE_THEN `u:A`
                                      STRIP_ASSUME_TAC)))) THEN
  UNDISCH_TAC `emed3 D (E:A->A->bool) a' b c d'` THEN REWRITE_TAC[emed3] THEN
  DISCH_THEN(X_CHOOSE_THEN `rab':A`
             (X_CHOOSE_THEN `rac':A` (X_CHOOSE_THEN `rbc':A`
                                      (X_CHOOSE_THEN `u':A`
                                       STRIP_ASSUME_TAC)))) THEN
  SUBGOAL_THEN `(rab:A) IN D /\ (rac:A) IN D /\ (rbc:A) IN D /\ (u:A) IN D /\
                (rab':A) IN D /\ (rac':A) IN D /\ (rbc':A) IN D /\ (u':A) IN D`
  STRIP_ASSUME_TAC THENL [ASM_MESON_TAC[EBINTER_IN; EBUNION_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `esubset D (E:A->A->bool) rab' rab` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`a':A`;`a:A`;`b:A`;`rab':A`;
                  `rab:A`] EBINTER_MONO) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `esubset D (E:A->A->bool) rac' rac` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`a':A`;`a:A`;`c:A`;`rac':A`;
                  `rac:A`] EBINTER_MONO) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `esubset D (E:A->A->bool) rbc' rbc` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`b:A`;`c:A`;`b:A`;`c:A`;`rbc':A`;
                  `rbc:A`] EBINTER_MONO_BOTH) THEN
    ASM_REWRITE_TAC[ESUBSET_REFL]; ALL_TAC] THEN
  SUBGOAL_THEN `esubset D (E:A->A->bool) u' u` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`rab':A`;`rac':A`;`rab:A`;`rac:A`;
                  `u':A`;`u:A`] EBUNION_MONO_BOTH) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MATCH_MP_TAC(ISPECL
               [`D:A->bool`;`E:A->A->bool`;`u':A`;`rbc':A`;`u:A`;`rbc:A`;
                `d':A`;`d:A`] EBUNION_MONO_BOTH) THEN
  ASM_REWRITE_TAC[]);;

(* ------------------------------------------------------------------ *)
(* Measure-decrease for the congruence wrapper.  E-characterizations   *)
(* EMAX3/EMIN3/EMED3_ALT (E w (max3/min3/med3) <=> the disjunction/     *)
(* conjunction of memberships); H4 = EMEASURE3_NEQ (dropping a to a'<a  *)
(* changes the sorted triple, via w0=a': a' lies in exactly one of b,c  *)
(* so a' IN med3 but a' NOTIN med3'); and MULTISET_DEC: E a' a ==>       *)
(* the sorted (max3,med3,min3) triple strictly lex-DECREASES.  This is  *)
(* the well-founded measure the least-counterexample wrapper inducts on.*)
(* ------------------------------------------------------------------ *)
let EMAX3_ALT = prove
 (`!D (E:A->A->bool) a b c M w.
      model D E ZF_AX /\ a IN D /\ b IN D /\ c IN D /\ w IN D /\
        emax3 D E a b c M
      ==> (E w M <=> E w a \/ E w b \/ E w c)`,
  REPEAT GEN_TAC THEN REWRITE_TAC[emax3] THEN STRIP_TAC THEN
  SUBGOAL_THEN `(p:A) IN D` ASSUME_TAC THENL
  [ASM_MESON_TAC[EBUNION_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `!z:A. z IN D ==> ((E:A->A->bool) z M <=> E z p \/ E z c)`
    (LABEL_TAC "Mc") THENL
   [MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`p:A`;`c:A`;`M:A`]
           EBUNION_ALT) THEN
    ASM_REWRITE_TAC[] THEN DISCH_THEN(fun th -> ACCEPT_TAC(CONJUNCT2 th));
    ALL_TAC] THEN
  SUBGOAL_THEN `!z:A. z IN D ==> ((E:A->A->bool) z p <=> E z a \/ E z b)`
    (LABEL_TAC "pc") THENL
   [MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`a:A`;`b:A`;`p:A`]
           EBUNION_ALT) THEN
    ASM_REWRITE_TAC[] THEN DISCH_THEN(fun th -> ACCEPT_TAC(CONJUNCT2 th));
    ALL_TAC] THEN
  USE_THEN "Mc" (fun th -> MP_TAC(SPEC `w:A` th)) THEN ANTS_TAC THENL
  [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  USE_THEN "pc" (fun th -> MP_TAC(SPEC `w:A` th)) THEN ANTS_TAC THENL
  [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th; DISJ_ASSOC]));;

let EMIN3_ALT = prove
 (`!D (E:A->A->bool) a b c m w.
      a IN D /\ b IN D /\ c IN D /\ w IN D /\ emin3 D E a b c m
      ==> (E w m <=> E w a /\ E w b /\ E w c)`,
  REPEAT GEN_TAC THEN REWRITE_TAC[emin3] THEN STRIP_TAC THEN
  SUBGOAL_THEN `(p:A) IN D` ASSUME_TAC THENL
  [ASM_MESON_TAC[EBINTER_IN]; ALL_TAC] THEN
  UNDISCH_TAC `ebinter D (E:A->A->bool) p c m` THEN REWRITE_TAC[ebinter] THEN
  DISCH_THEN(MP_TAC o SPEC `w:A` o CONJUNCT2) THEN ASM_REWRITE_TAC[] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  UNDISCH_TAC `ebinter D (E:A->A->bool) a b p` THEN REWRITE_TAC[ebinter] THEN
  DISCH_THEN(MP_TAC o SPEC `w:A` o CONJUNCT2) THEN ASM_REWRITE_TAC[] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th; CONJ_ASSOC]));;

let EMED3_ALT = prove
 (`!D (E:A->A->bool) a b c d w.
      model D E ZF_AX /\ a IN D /\ b IN D /\ c IN D /\ w IN D /\
        emed3 D E a b c d
      ==> (E w d <=> (E w a /\ E w b) \/ (E w a /\ E w c) \/
           (E w b /\ E w c))`,
  REPEAT GEN_TAC THEN REWRITE_TAC[emed3] THEN STRIP_TAC THEN
  SUBGOAL_THEN `(rab:A) IN D /\ (rac:A) IN D /\ (rbc:A) IN D /\ (u:A) IN D`
  STRIP_ASSUME_TAC THENL [ASM_MESON_TAC[EBINTER_IN; EBUNION_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `!z:A. z IN D ==> ((E:A->A->bool) z d <=> E z u \/ E z rbc)`
    (LABEL_TAC "dc") THENL
   [MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`u:A`;`rbc:A`;`d:A`]
           EBUNION_ALT) THEN
    ASM_REWRITE_TAC[] THEN DISCH_THEN(fun th -> ACCEPT_TAC(CONJUNCT2 th));
    ALL_TAC] THEN
  SUBGOAL_THEN `!z:A. z IN D ==> ((E:A->A->bool) z u <=> E z rab \/ E z rac)`
    (LABEL_TAC "uc") THENL
   [MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`rab:A`;`rac:A`;`u:A`]
           EBUNION_ALT) THEN
    ASM_REWRITE_TAC[] THEN DISCH_THEN(fun th -> ACCEPT_TAC(CONJUNCT2 th));
    ALL_TAC] THEN
  SUBGOAL_THEN
    `((E:A->A->bool) w rab <=> E w a /\ E w b) /\
     (E w rac <=> E w a /\ E w c) /\
     (E w rbc <=> E w b /\ E w c)` STRIP_ASSUME_TAC THENL
   [REPEAT CONJ_TAC THENL
     [UNDISCH_TAC `ebinter D (E:A->A->bool) a b rab`;
      UNDISCH_TAC `ebinter D (E:A->A->bool) a c rac`;
      UNDISCH_TAC `ebinter D (E:A->A->bool) b c rbc`] THEN
    REWRITE_TAC[ebinter] THEN DISCH_THEN(MP_TAC o SPEC `w:A` o CONJUNCT2) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  USE_THEN "dc" (fun th -> MP_TAC(SPEC `w:A` th)) THEN ANTS_TAC THENL
  [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  USE_THEN "uc" (fun th -> MP_TAC(SPEC `w:A` th)) THEN ANTS_TAC THENL
  [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN ASM_REWRITE_TAC[DISJ_ASSOC]);;

let EMEASURE3_NEQ = prove
 (`!D (E:A->A->bool) a a' b c M d m M' d' m'.
      model D E ZF_AX /\ eordinal D E a /\ eordinal D E a' /\ eordinal D E b /\
      eordinal D E c /\ E a' a /\
      emax3 D E a b c M /\ emed3 D E a b c d /\ emin3 D E a b c m /\
      emax3 D E a' b c M' /\ emed3 D E a' b c d' /\ emin3 D E a' b c m'
      ==> ~(M' = M /\ d' = d /\ m' = m)`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `(a:A) IN D /\ (a':A) IN D /\ (b:A) IN D /\ (c:A) IN D`
    STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[EORDINAL_IN]; ALL_TAC] THEN
  DISCH_THEN(CONJUNCTS_THEN2 SUBST_ALL_TAC
             (CONJUNCTS_THEN2 SUBST_ALL_TAC SUBST_ALL_TAC)) THEN
  SUBGOAL_THEN `~((E:A->A->bool) a' a')` ASSUME_TAC THENL
   [ASM_MESON_TAC[E_IRREFL]; ALL_TAC] THEN
  (* E a' M  (M = max3 a b c), and E a' M since E a' a *)
  SUBGOAL_THEN `(E:A->A->bool) a' M` ASSUME_TAC THENL
   [MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`a:A`;`b:A`;`c:A`;`M:A`;`a':A`]
           EMAX3_ALT) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* E a' b \/ E a' c  (from E a' M = E a' M' and M' = max3 a' b c) *)
  SUBGOAL_THEN `(E:A->A->bool) a' b \/ E a' c` ASSUME_TAC THENL
   [MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`a':A`;`b:A`;`c:A`;`M:A`;`a':A`]
           EMAX3_ALT) THEN
    ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[]; ALL_TAC] THEN
  (* ~E a' m  (m = m' = min3 a' b c; E a' a' false) *)
  SUBGOAL_THEN `~((E:A->A->bool) a' m)` ASSUME_TAC THENL
   [MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`a':A`;`b:A`;`c:A`;`m:A`;`a':A`]
           EMIN3_ALT) THEN
    ASM_REWRITE_TAC[] THEN CONV_TAC TAUT; ALL_TAC] THEN
  (* ~(E a' b /\ E a' c)  (m = min3 a b c; E a' a true, ~E a' m) *)
  SUBGOAL_THEN `~((E:A->A->bool) a' b /\ E a' c)` ASSUME_TAC THENL
   [MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`a:A`;`b:A`;`c:A`;`m:A`;`a':A`]
           EMIN3_ALT) THEN
    ASM_REWRITE_TAC[] THEN CONV_TAC TAUT; ALL_TAC] THEN
  (* E a' d  (d = med3 a b c): E a' a /\ (E a' b \/ E a' c) *)
  SUBGOAL_THEN `(E:A->A->bool) a' d` ASSUME_TAC THENL
   [MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`a:A`;`b:A`;`c:A`;`d:A`;`a':A`]
           EMED3_ALT) THEN
    ASM_REWRITE_TAC[] THEN CONV_TAC TAUT; ALL_TAC] THEN
  (* ~E a' d  (d = med3 a' b c since d'=d): E a' a' false, so needs E a' b *)
  (* /\ E a' c *)
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`a':A`;`b:A`;`c:A`;`d:A`;`a':A`]
         EMED3_ALT) THEN
  ASM_REWRITE_TAC[] THEN CONV_TAC TAUT);;

let MULTISET_DEC = prove
 (`!D (E:A->A->bool) a a' b c M d m M' d' m'.
      model D E ZF_AX /\ eordinal D E a /\ eordinal D E a' /\ eordinal D E b /\
      eordinal D E c /\ E a' a /\
      emax3 D E a b c M /\ emed3 D E a b c d /\ emin3 D E a b c m /\
      emax3 D E a' b c M' /\ emed3 D E a' b c d' /\ emin3 D E a' b c m'
      ==> E M' M \/ (M' = M /\ E d' d) \/ (M' = M /\ d' = d /\ E m' m)`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `(a:A) IN D /\ (a':A) IN D /\ (b:A) IN D /\ (c:A) IN D`
    STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[EORDINAL_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `esubset D (E:A->A->bool) a' a` ASSUME_TAC THENL
   [UNDISCH_TAC `eordinal D (E:A->A->bool) a` THEN
    REWRITE_TAC[eordinal; etransitive] THEN
    STRIP_TAC THEN FIRST_X_ASSUM(MP_TAC o SPEC `a':A`) THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
    `eordinal D (E:A->A->bool) M /\ eordinal D E M' /\ eordinal D E d /\
     eordinal D E d' /\ eordinal D E m /\ eordinal D E m'`
      STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[EMAX3_ORDINAL; EMED3_ORDINAL; EMIN3_ORDINAL]; ALL_TAC] THEN
  SUBGOAL_THEN `esubset D (E:A->A->bool) M' M` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`a:A`;`a':A`;`b:A`;`c:A`;`M:A`;
                  `M':A`] EMAX3_MONO) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `esubset D (E:A->A->bool) d' d` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`a:A`;`a':A`;`b:A`;`c:A`;`d:A`;
                  `d':A`] EMED3_MONO) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `esubset D (E:A->A->bool) m' m` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`a:A`;`a':A`;`b:A`;`c:A`;`m:A`;
                  `m':A`] EMIN3_MONO) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MP_TAC(ISPECL
         [`D:A->bool`;`E:A->A->bool`;`a:A`;`a':A`;`b:A`;`c:A`;`M:A`;
          `d:A`;`m:A`;
          `M':A`;`d':A`;`m':A`] EMEASURE3_NEQ) THEN ASM_REWRITE_TAC[] THEN
  DISCH_TAC THEN
  ASM_CASES_TAC `M':A = M` THENL
   [ASM_CASES_TAC `d':A = d` THENL
     [ (* DISJ3: M'=M /\ d'=d /\ E m' m *)
      DISJ2_TAC THEN DISJ2_TAC THEN ASM_REWRITE_TAC[] THEN
      SUBGOAL_THEN `~(m':A = m)` ASSUME_TAC THENL
       [UNDISCH_TAC `~((M':A) = M /\ (d':A) = d /\ (m':A) = m)` THEN
        ASM_REWRITE_TAC[]; ALL_TAC] THEN
      MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`m':A`;`m:A`]
             EORDINAL_SUBSET_MEMBER) THEN
      ASM_REWRITE_TAC[];
      (* DISJ2: M'=M /\ E d' d *)
      DISJ2_TAC THEN DISJ1_TAC THEN ASM_REWRITE_TAC[] THEN
      MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`d':A`;`d:A`]
             EORDINAL_SUBSET_MEMBER) THEN
      ASM_REWRITE_TAC[]];
    (* DISJ1: E M' M *)
    DISJ1_TAC THEN
    MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`M':A`;`M:A`]
           EORDINAL_SUBSET_MEMBER) THEN
    ASM_REWRITE_TAC[]]);;

(* ------------------------------------------------------------------ *)
(* Object forms for the congruence-wrapper measure.  binter_form =     *)
(* ebinter (dual of bunion_form); bmax3_form / bmin3_form encode the    *)
(* sorted rank-triple's max3 / min3 (compositions of bunion/binter with *)
(* one fresh intermediate slot).  For cong_bad_form's sorted-bnrank     *)
(* conditions.  (bmed3_form next.)                                     *)
(* ------------------------------------------------------------------ *)
let binter_form = new_definition
  `binter_form i j k =
     !! (MAX (MAX i j) k + 1)
        (((MAX (MAX i j) k + 1) %% k) <->
         (((MAX (MAX i j) k + 1) %% i) &&
          ((MAX (MAX i j) k + 1) %% j)))`;;

let HOLDS_BINTER_FORM = prove
 (`!D (E:A->A->bool) v i j k.
     model D E ZF_AX /\ valuation D v
     ==> (holds D E v (binter_form i j k) <=>
          ebinter D E (v i) (v j) (v k))`,
  REPEAT STRIP_TAC THEN
  FIRST_ASSUM(ASSUME_TAC o REWRITE_RULE[valuation]) THEN
  REWRITE_TAC[binter_form; holds; HOLDS_IFF; HOLDS_AND] THEN
  SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER;
           ARITH_RULE `~(i = MAX (MAX i j) k + 1) /\
                       ~(j = MAX (MAX i j) k + 1) /\
                       ~(k = MAX (MAX i j) k + 1)`] THEN
  REWRITE_TAC[ebinter] THEN ASM_MESON_TAC[]);;

let bmax3_form = new_definition
  `bmax3_form i j k kk =
     ?? (MAX (MAX (MAX i j) k) kk + 1)
        (bunion_form i j (MAX (MAX (MAX i j) k) kk + 1) &&
         bunion_form (MAX (MAX (MAX i j) k) kk + 1) k kk)`;;

let HOLDS_BMAX3_FORM = prove
 (`!D (E:A->A->bool) v i j k kk.
     model D E ZF_AX /\ valuation D v
     ==> (holds D E v (bmax3_form i j k kk) <=>
          emax3 D E (v i) (v j) (v k) (v kk))`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[bmax3_form] THEN
  ABBREV_TAC `pp = MAX (MAX (MAX i j) k) kk + 1` THEN
  SUBGOAL_THEN `~(i = pp) /\ ~(j = pp) /\ ~(k:num = pp) /\ ~(kk = pp)`
    STRIP_ASSUME_TAC THENL
   [EXPAND_TAC "pp" THEN ARITH_TAC; ALL_TAC] THEN
  REWRITE_TAC[HOLDS_EX; HOLDS_AND] THEN REWRITE_TAC[emax3] THEN EQ_TAC THENL
   [DISCH_THEN(X_CHOOSE_THEN `a:A` STRIP_ASSUME_TAC) THEN EXISTS_TAC `a:A` THEN
    MP_TAC(ISPECL
           [`D:A->bool`;`E:A->A->bool`;`((pp:num) |-> (a:A)) (v:num->A)`;
            `i:num`;`j:num`;`pp:num`] HOLDS_BUNION_FORM) THEN
    ANTS_TAC THENL [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
    ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER] THEN DISCH_TAC THEN
    MP_TAC(ISPECL
           [`D:A->bool`;`E:A->A->bool`;`((pp:num) |-> (a:A)) (v:num->A)`;
            `pp:num`;`k:num`;`kk:num`] HOLDS_BUNION_FORM) THEN
    ANTS_TAC THENL [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
    ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER] THEN ASM_MESON_TAC[];
    DISCH_THEN(X_CHOOSE_THEN `p:A` STRIP_ASSUME_TAC) THEN
    SUBGOAL_THEN `(p:A) IN D` ASSUME_TAC THENL
    [ASM_MESON_TAC[EBUNION_IN]; ALL_TAC] THEN
    EXISTS_TAC `p:A` THEN ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
     [MP_TAC(ISPECL
             [`D:A->bool`;`E:A->A->bool`;`((pp:num) |-> (p:A)) (v:num->A)`;
              `i:num`;`j:num`;`pp:num`] HOLDS_BUNION_FORM) THEN
      ANTS_TAC THENL [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
      ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER];
      MP_TAC(ISPECL
             [`D:A->bool`;`E:A->A->bool`;`((pp:num) |-> (p:A)) (v:num->A)`;
              `pp:num`;`k:num`;`kk:num`] HOLDS_BUNION_FORM) THEN
      ANTS_TAC THENL [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
      ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER]]]);;

let bmin3_form = new_definition
  `bmin3_form i j k kk =
     ?? (MAX (MAX (MAX i j) k) kk + 1)
        (binter_form i j (MAX (MAX (MAX i j) k) kk + 1) &&
         binter_form (MAX (MAX (MAX i j) k) kk + 1) k kk)`;;

let HOLDS_BMIN3_FORM = prove
 (`!D (E:A->A->bool) v i j k kk.
     model D E ZF_AX /\ valuation D v
     ==> (holds D E v (bmin3_form i j k kk) <=>
          emin3 D E (v i) (v j) (v k) (v kk))`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[bmin3_form] THEN
  ABBREV_TAC `pp = MAX (MAX (MAX i j) k) kk + 1` THEN
  SUBGOAL_THEN `~(i = pp) /\ ~(j = pp) /\ ~(k:num = pp) /\ ~(kk = pp)`
    STRIP_ASSUME_TAC THENL
   [EXPAND_TAC "pp" THEN ARITH_TAC; ALL_TAC] THEN
  REWRITE_TAC[HOLDS_EX; HOLDS_AND] THEN REWRITE_TAC[emin3] THEN EQ_TAC THENL
   [DISCH_THEN(X_CHOOSE_THEN `a:A` STRIP_ASSUME_TAC) THEN EXISTS_TAC `a:A` THEN
    MP_TAC(ISPECL
           [`D:A->bool`;`E:A->A->bool`;`((pp:num) |-> (a:A)) (v:num->A)`;
            `i:num`;`j:num`;`pp:num`] HOLDS_BINTER_FORM) THEN
    ANTS_TAC THENL [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
    ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER] THEN DISCH_TAC THEN
    MP_TAC(ISPECL
           [`D:A->bool`;`E:A->A->bool`;`((pp:num) |-> (a:A)) (v:num->A)`;
            `pp:num`;`k:num`;`kk:num`] HOLDS_BINTER_FORM) THEN
    ANTS_TAC THENL [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
    ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER] THEN ASM_MESON_TAC[];
    DISCH_THEN(X_CHOOSE_THEN `p:A` STRIP_ASSUME_TAC) THEN
    SUBGOAL_THEN `(p:A) IN D` ASSUME_TAC THENL
    [ASM_MESON_TAC[EBINTER_IN]; ALL_TAC] THEN
    EXISTS_TAC `p:A` THEN ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
     [MP_TAC(ISPECL
             [`D:A->bool`;`E:A->A->bool`;`((pp:num) |-> (p:A)) (v:num->A)`;
              `i:num`;`j:num`;`pp:num`] HOLDS_BINTER_FORM) THEN
      ANTS_TAC THENL [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
      ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER];
      MP_TAC(ISPECL
             [`D:A->bool`;`E:A->A->bool`;`((pp:num) |-> (p:A)) (v:num->A)`;
              `pp:num`;`k:num`;`kk:num`] HOLDS_BINTER_FORM) THEN
      ANTS_TAC THENL [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
      ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER]]]);;

(* ------------------------------------------------------------------ *)
(* bmed3_form : object form for the median med3 (4 fresh slots -- three *)
(* pairwise binter_form then two bunion_form).  Completes the sorted-   *)
(* rank object forms (bmax3/bmin3/bmed3) for cong_bad_form.  VV/conv are *)
(* proof-local helpers (the 4-deep valmod and the per-slot form         *)
(* converter via HOLDS_BINTER/BUNION_FORM + VALMOD simp).               *)
(* ------------------------------------------------------------------ *)
let bmed3_form = new_definition
  `bmed3_form i j k kk =
     ?? (MAX (MAX (MAX i j) k) kk + 1)
      (?? (MAX (MAX (MAX i j) k) kk + 2)
       (?? (MAX (MAX (MAX i j) k) kk + 3)
        (?? (MAX (MAX (MAX i j) k) kk + 4)
         (binter_form i j (MAX (MAX (MAX i j) k) kk + 1) &&
          binter_form i k (MAX (MAX (MAX i j) k) kk + 2) &&
          binter_form j k (MAX (MAX (MAX i j) k) kk + 3) &&
          bunion_form (MAX (MAX (MAX i j) k) kk + 1)
            (MAX (MAX (MAX i j) k) kk + 2)
                      (MAX (MAX (MAX i j) k) kk + 4) &&
          bunion_form (MAX (MAX (MAX i j) k) kk + 4)
            (MAX (MAX (MAX i j) k) kk + 3) kk))))`;;
let HOLDS_BMED3_FORM =
  let VV = `(s4 |-> (w4:A)) ((s3 |-> (w3:A))
             ((s2 |-> (w2:A)) ((s1 |-> (w1:A)) (v:num->A))))` in
  let conv bic a b c =
    MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`; VV; a; b; c] bic) THEN
    ANTS_TAC THENL [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
    ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER] in
  prove
 (`!D (E:A->A->bool) v i j k kk.
     model D E ZF_AX /\ valuation D v
     ==> (holds D E v (bmed3_form i j k kk) <=>
          emed3 D E (v i) (v j) (v k) (v kk))`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[bmed3_form] THEN
  ABBREV_TAC `s1 = MAX (MAX (MAX i j) k) kk + 1` THEN
  ABBREV_TAC `s2 = MAX (MAX (MAX i j) k) kk + 2` THEN
  ABBREV_TAC `s3 = MAX (MAX (MAX i j) k) kk + 3` THEN
  ABBREV_TAC `s4 = MAX (MAX (MAX i j) k) kk + 4` THEN
  SUBGOAL_THEN
   `~(i=s1)/\ ~(j=s1)/\ ~(k:num=s1)/\ ~(kk=s1)/\ ~(i=s2)/\ ~(j=s2)/\
    ~(k=s2)/\ ~(kk=s2)/\
    ~(i=s3)/\ ~(j=s3)/\ ~(k=s3)/\ ~(kk=s3)/\ ~(i=s4)/\ ~(j=s4)/\
      ~(k=s4)/\ ~(kk=s4)/\
    ~(s1=i)/\ ~(s1=j)/\ ~(s1=k)/\ ~(s1=kk)/\ ~(s2=i)/\ ~(s2=j)/\
      ~(s2=k)/\ ~(s2=kk)/\
    ~(s3=i)/\ ~(s3=j)/\ ~(s3=k)/\ ~(s3=kk)/\ ~(s4=i)/\ ~(s4=j)/\
      ~(s4=k)/\ ~(s4=kk)/\
    ~(s1=s2)/\ ~(s1=s3)/\ ~(s1=s4)/\ ~(s2=s3)/\ ~(s2=s4)/\ ~(s3=s4)/\
    ~(s2=s1)/\ ~(s3=s1)/\ ~(s4=s1)/\ ~(s3=s2)/\ ~(s4=s2)/\ ~(s4=s3)`
  STRIP_ASSUME_TAC THENL
   [MAP_EVERY EXPAND_TAC ["s1";"s2";"s3";"s4"] THEN ARITH_TAC; ALL_TAC] THEN
  REWRITE_TAC[HOLDS_EX; HOLDS_AND] THEN REWRITE_TAC[emed3] THEN EQ_TAC THENL
   [DISCH_THEN(X_CHOOSE_THEN `w1:A` (CONJUNCTS_THEN2 ASSUME_TAC
      (X_CHOOSE_THEN `w2:A` (CONJUNCTS_THEN2 ASSUME_TAC
       (X_CHOOSE_THEN `w3:A` (CONJUNCTS_THEN2 ASSUME_TAC
        (X_CHOOSE_THEN `w4:A`
         (CONJUNCTS_THEN2 ASSUME_TAC STRIP_ASSUME_TAC)))))))) THEN
    SUBGOAL_THEN
      `valuation D
       ((s4 |-> (w4:A))
        ((s3 |-> (w3:A)) ((s2 |-> (w2:A)) ((s1 |-> (w1:A)) (v:num->A)))))`
    ASSUME_TAC THENL [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
    MAP_EVERY EXISTS_TAC [`w1:A`;`w2:A`;`w3:A`;`w4:A`] THEN
    REPEAT CONJ_TAC THENL
    [conv HOLDS_BINTER_FORM `i:num` `j:num` `s1:num` THEN ASM_REWRITE_TAC[];
      conv HOLDS_BINTER_FORM `i:num` `k:num` `s2:num` THEN ASM_REWRITE_TAC[];
      conv HOLDS_BINTER_FORM `j:num` `k:num` `s3:num` THEN ASM_REWRITE_TAC[];
      conv HOLDS_BUNION_FORM `s1:num` `s2:num` `s4:num` THEN ASM_REWRITE_TAC[];
      conv HOLDS_BUNION_FORM `s4:num` `s3:num` `kk:num` THEN
      ASM_REWRITE_TAC[]];
    DISCH_THEN(X_CHOOSE_THEN `w1:A` (X_CHOOSE_THEN `w2:A` (X_CHOOSE_THEN `w3:A`
      (X_CHOOSE_THEN `w4:A` STRIP_ASSUME_TAC)))) THEN
    SUBGOAL_THEN `(w1:A) IN D /\ (w2:A) IN D /\ (w3:A) IN D /\ (w4:A) IN D`
      STRIP_ASSUME_TAC THENL
      [ASM_MESON_TAC[EBINTER_IN; EBUNION_IN]; ALL_TAC] THEN
    SUBGOAL_THEN
      `valuation D
       ((s4 |-> (w4:A))
        ((s3 |-> (w3:A)) ((s2 |-> (w2:A)) ((s1 |-> (w1:A)) (v:num->A)))))`
    ASSUME_TAC THENL [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
    EXISTS_TAC `w1:A` THEN ASM_REWRITE_TAC[] THEN
    EXISTS_TAC `w2:A` THEN ASM_REWRITE_TAC[] THEN
    EXISTS_TAC `w3:A` THEN ASM_REWRITE_TAC[] THEN
    EXISTS_TAC `w4:A` THEN ASM_REWRITE_TAC[] THEN REPEAT CONJ_TAC THENL
     [conv HOLDS_BINTER_FORM `i:num` `j:num` `s1:num` THEN ASM_REWRITE_TAC[];
      conv HOLDS_BINTER_FORM `i:num` `k:num` `s2:num` THEN ASM_REWRITE_TAC[];
      conv HOLDS_BINTER_FORM `j:num` `k:num` `s3:num` THEN ASM_REWRITE_TAC[];
      conv HOLDS_BUNION_FORM `s1:num` `s2:num` `s4:num` THEN ASM_REWRITE_TAC[];
      conv HOLDS_BUNION_FORM `s4:num` `s3:num` `kk:num` THEN
      ASM_REWRITE_TAC[]]]);;

(* ------------------------------------------------------------------ *)
(* bnrankp_form n r : parameterized canonical B-name-rank object form  *)
(* (name slot n, rank slot r; B at slot 2).  Generalizes bnrank_form   *)
(* [hardcoded slots 0/1] so cong_bad_form can put three ranks          *)
(* in ordinal slots for the sorted-rank forms.  HOLDS asserts v r is   *)
(* the least stage-index whose B-name stage contains v n.  Freshness:  *)
(* r avoids the recursion slots 3,4 and temps 11,12; n avoids 11,12,13.*)
(* ------------------------------------------------------------------ *)
let bnrankp_form = new_definition
  `bnrankp_form n r =
     ordinal_form r &&
     (?? 11 (recapp3_form (rec_form bname_step_form 3) r 11 && n %% 11)) &&
     (!!- 12 r (Not(?? 13 (recapp3_form (rec_form bname_step_form 3) 12 13 &&
                           n %% 13))))`;;

let HOLDS_BNRANKP_FORM = prove
 (`!D (E:A->A->bool) v n r.
        model D E ZF_AX /\ valuation D v /\
        ~(r = 3) /\ ~(r = 4) /\ ~(r = 11) /\ ~(r = 12) /\
        ~(n = 11) /\ ~(n = 12) /\ ~(n = 13)
        ==> (holds D E v (bnrankp_form n r) <=>
             eordinal D E (v r) /\
             (?y. y IN D /\ ebnstage D E (v 2) (v r) y /\ E (v n) y) /\
             (!c. c IN D /\ E c (v r)
                  ==> ~(?y. y IN D /\ ebnstage D E (v 2) c y /\ E (v n) y)))`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `!x. (v:num->A) x IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[valuation]; ALL_TAC] THEN
  SUBGOAL_THEN
   `~(11 = n) /\ ~(12 = n) /\ ~(13 = n) /\ ~(11 = r) /\ ~(12 = r) /\
    ~(r = 3) /\ ~(r = 4) /\ ~(11 = (2:num)) /\ ~(12 = (2:num)) /\
      ~(13 = (2:num))`
  STRIP_ASSUME_TAC THENL [ASM_ARITH_TAC; ALL_TAC] THEN
  REWRITE_TAC[bnrankp_form] THEN
  REWRITE_TAC[HOLDS_AND; HOLDS_EX] THEN
  ASM_SIMP_TAC[HOLDS_FORALLMEM] THEN
  REWRITE_TAC[HOLDS_AND; HOLDS_EX; HOLDS_NOT; holds] THEN
  ASM_SIMP_TAC[HOLDS_ORDINAL_FORM] THEN
  SUBGOAL_THEN
   `!y:A. y IN D
      ==> (holds D E ((11 |-> y) v)
             (recapp3_form (rec_form bname_step_form 3) r 11) <=>
           ebnstage D E (v 2) (v r) y)`
  ASSUME_TAC THENL
   [X_GEN_TAC `y:A` THEN DISCH_TAC THEN
    SUBGOAL_THEN `valuation D ((11 |-> (y:A)) v)` ASSUME_TAC THENL
     [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `(11 |-> (y:A)) v`;
                  `r:num`; `11`] HOLDS_RECAPP3_BNSTEP) THEN
    ASM_SIMP_TAC[ARITH_RULE `~(11 = 3) /\ ~(11 = 4)`] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER; ARITH_EQ];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!c y:A. c IN D /\ y IN D
      ==> (holds D E ((13 |-> y) ((12 |-> c) v))
             (recapp3_form (rec_form bname_step_form 3) 12 13) <=>
           ebnstage D E (v 2) c y)`
  ASSUME_TAC THENL
   [REPEAT GEN_TAC THEN STRIP_TAC THEN
    SUBGOAL_THEN `valuation D ((13 |-> (y:A)) ((12 |-> (c:A)) v))`
    ASSUME_TAC THENL
     [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
                  `(13 |-> (y:A)) ((12 |-> (c:A)) v)`;
                  `12`; `13`] HOLDS_RECAPP3_BNSTEP) THEN
    ASM_REWRITE_TAC[ARITH_RULE
      `~(12 = 3) /\ ~(12 = 4) /\ ~(13 = 3) /\ ~(13 = 4)`] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER; ARITH_EQ];
    ALL_TAC] THEN
  ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER; ARITH_EQ] THEN
  POP_ASSUM_LIST(fun ths ->
                 MESON_TAC(filter (fun th -> is_forall(concl th)) ths)));;

(* ------------------------------------------------------------------ *)
(* cfails_form : object formula "C1 or C2 or C3 fails" for the triple  *)
(* of B-names at slots 6,7,8 (B=slot 2, leq=slot 5).  Each Ck says     *)
(* meet(X,Y) <= Z FAILS, encoded via bmeet_form then bimp_form then    *)
(* Not(btop_form) (using A<=B <=> ebimp A B = top).  Value slots 20-24. *)
(*   C1: meet([[6=7]],[[6 in 8]]) <= [[7 in 8]]                         *)
(*   C2: meet([[6=7]],[[8 in 6]]) <= [[8 in 7]]                         *)
(*   C3: meet([[6=7]],[[7=8]])    <= [[6=8]]                            *)
(* Wrapper lemma 2 for the fundamental congruence.                     *)
(* ------------------------------------------------------------------ *)
let cfails_form = new_definition
  `cfails_form =
     (?? 20 (?? 21 (?? 22 (?? 23 (?? 24 (
        ebv_eq_form 20 6 7 5 && ebv_in_form 21 6 8 5 && ebv_in_form 22 7 8 5 &&
        bmeet_form 5 2 20 21 23 && bimp_form 5 2 23 22 24 &&
        Not(btop_form 5 2 24))))))) ||
     (?? 20 (?? 21 (?? 22 (?? 23 (?? 24 (
        ebv_eq_form 20 6 7 5 && ebv_in_form 21 8 6 5 && ebv_in_form 22 8 7 5 &&
        bmeet_form 5 2 20 21 23 && bimp_form 5 2 23 22 24 &&
        Not(btop_form 5 2 24))))))) ||
     (?? 20 (?? 21 (?? 22 (?? 23 (?? 24 (
        ebv_eq_form 20 6 7 5 && ebv_eq_form 21 7 8 5 && ebv_eq_form 22 6 8 5 &&
        bmeet_form 5 2 20 21 23 && bimp_form 5 2 23 22 24 &&
        Not(btop_form 5 2 24)))))))`;;

let HOLDS_CFAILS_FORM =
  let blk_tac =
    REPEAT GEN_TAC THEN STRIP_TAC THEN
    SUBGOAL_THEN
     `valuation D ((24 |-> z24) ((23 |-> z23) ((22 |-> z22) ((21 |-> z21)
        ((20 |-> z20) (v:num->A))))))`
    ASSUME_TAC THENL [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
    ASM_SIMP_TAC[HOLDS_AND; HOLDS_NOT; HOLDS_EBV_EQ_FORM; HOLDS_EBV_IN_FORM;
                 HOLDS_BMEET_FORM; HOLDS_BIMP_FORM; HOLDS_BTOP_FORM] THEN
    ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER; ARITH_EQ]
  and use_tac =
    REWRITE_TAC[HOLDS_EX] THEN EQ_TAC THENL
     [INTRO_TAC "@z20. z20D @z21. z21D @z22. z22D @z23. z23D @z24. \
                 z24D h" THEN
      MAP_EVERY EXISTS_TAC [`z20:A`;`z21:A`;`z22:A`;`z23:A`;`z24:A`] THEN
      ASM_REWRITE_TAC[] THEN
      USE_THEN "blk"(fun b -> MP_TAC(SPECL
        [`z20:A`;`z21:A`;`z22:A`;`z23:A`;`z24:A`] b)) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(SUBST1_TAC o SYM) THEN ASM_REWRITE_TAC[];
      DISCH_THEN(X_CHOOSE_THEN `z20:A` (X_CHOOSE_THEN `z21:A`
        (X_CHOOSE_THEN `z22:A` (X_CHOOSE_THEN `z23:A`
          (X_CHOOSE_THEN `z24:A` STRIP_ASSUME_TAC))))) THEN
      EXISTS_TAC `z20:A` THEN ASM_REWRITE_TAC[] THEN
      EXISTS_TAC `z21:A` THEN ASM_REWRITE_TAC[] THEN
      EXISTS_TAC `z22:A` THEN ASM_REWRITE_TAC[] THEN
      EXISTS_TAC `z23:A` THEN ASM_REWRITE_TAC[] THEN
      EXISTS_TAC `z24:A` THEN ASM_REWRITE_TAC[] THEN
      USE_THEN "blk"(fun b -> MP_TAC(SPECL
        [`z20:A`;`z21:A`;`z22:A`;`z23:A`;`z24:A`] b)) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN SUBST1_TAC THEN ASM_REWRITE_TAC[]] in
  prove
 (`!D (E:A->A->bool) v.
      model D E ZF_AX /\ valuation D v
      ==> (holds D E v cfails_form <=>
           (?z20 z21 z22 z23 z24.
              z20 IN D /\ z21 IN D /\ z22 IN D /\ z23 IN D /\ z24 IN D /\
              ebv_eq D E (v 2) (v 5) (v 6) (v 7) z20 /\
              ebv_in D E (v 2) (v 5) (v 6) (v 8) z21 /\
              ebv_in D E (v 2) (v 5) (v 7) (v 8) z22 /\
              emeet D E (v 2) (v 5) z20 z21 z23 /\
              ebimp D E (v 2) (v 5) z23 z22 z24 /\
              ~etop D E (v 2) (v 5) z24) \/
           (?z20 z21 z22 z23 z24.
              z20 IN D /\ z21 IN D /\ z22 IN D /\ z23 IN D /\ z24 IN D /\
              ebv_eq D E (v 2) (v 5) (v 6) (v 7) z20 /\
              ebv_in D E (v 2) (v 5) (v 8) (v 6) z21 /\
              ebv_in D E (v 2) (v 5) (v 8) (v 7) z22 /\
              emeet D E (v 2) (v 5) z20 z21 z23 /\
              ebimp D E (v 2) (v 5) z23 z22 z24 /\
              ~etop D E (v 2) (v 5) z24) \/
           (?z20 z21 z22 z23 z24.
              z20 IN D /\ z21 IN D /\ z22 IN D /\ z23 IN D /\ z24 IN D /\
              ebv_eq D E (v 2) (v 5) (v 6) (v 7) z20 /\
              ebv_eq D E (v 2) (v 5) (v 7) (v 8) z21 /\
              ebv_eq D E (v 2) (v 5) (v 6) (v 8) z22 /\
              emeet D E (v 2) (v 5) z20 z21 z23 /\
              ebimp D E (v 2) (v 5) z23 z22 z24 /\
              ~etop D E (v 2) (v 5) z24))`,
  REPEAT STRIP_TAC THEN
  REWRITE_TAC[cfails_form; HOLDS_OR] THEN
  MATCH_MP_TAC(TAUT
    `(a <=> d) /\ (b <=> e) /\ (c <=> f)
     ==> (a \/ b \/ c <=> d \/ e \/ f)`) THEN
  REPEAT CONJ_TAC THENL
   [SUBGOAL_THEN
     `!z20 z21 z22 z23 z24:A.
        z20 IN D /\ z21 IN D /\ z22 IN D /\ z23 IN D /\ z24 IN D
        ==> (holds D E
               ((24 |-> z24) ((23 |-> z23) ((22 |-> z22) ((21 |-> z21)
                 ((20 |-> z20) (v:num->A))))))
               (ebv_eq_form 20 6 7 5 && ebv_in_form 21 6 8 5 &&
                ebv_in_form 22 7 8 5 &&
                bmeet_form 5 2 20 21 23 && bimp_form 5 2 23 22 24 &&
                Not(btop_form 5 2 24)) <=>
             ebv_eq D E (v 2) (v 5) (v 6) (v 7) z20 /\
             ebv_in D E (v 2) (v 5) (v 6) (v 8) z21 /\
             ebv_in D E (v 2) (v 5) (v 7) (v 8) z22 /\
             emeet D E (v 2) (v 5) z20 z21 z23 /\
             ebimp D E (v 2) (v 5) z23 z22 z24 /\
             ~etop D E (v 2) (v 5) z24)`
    (LABEL_TAC "blk") THENL [blk_tac; use_tac];
    SUBGOAL_THEN
     `!z20 z21 z22 z23 z24:A.
        z20 IN D /\ z21 IN D /\ z22 IN D /\ z23 IN D /\ z24 IN D
        ==> (holds D E
               ((24 |-> z24) ((23 |-> z23) ((22 |-> z22) ((21 |-> z21)
                 ((20 |-> z20) (v:num->A))))))
               (ebv_eq_form 20 6 7 5 && ebv_in_form 21 8 6 5 &&
                ebv_in_form 22 8 7 5 &&
                bmeet_form 5 2 20 21 23 && bimp_form 5 2 23 22 24 &&
                Not(btop_form 5 2 24)) <=>
             ebv_eq D E (v 2) (v 5) (v 6) (v 7) z20 /\
             ebv_in D E (v 2) (v 5) (v 8) (v 6) z21 /\
             ebv_in D E (v 2) (v 5) (v 8) (v 7) z22 /\
             emeet D E (v 2) (v 5) z20 z21 z23 /\
             ebimp D E (v 2) (v 5) z23 z22 z24 /\
             ~etop D E (v 2) (v 5) z24)`
    (LABEL_TAC "blk") THENL [blk_tac; use_tac];
    SUBGOAL_THEN
     `!z20 z21 z22 z23 z24:A.
        z20 IN D /\ z21 IN D /\ z22 IN D /\ z23 IN D /\ z24 IN D
        ==> (holds D E
               ((24 |-> z24) ((23 |-> z23) ((22 |-> z22) ((21 |-> z21)
                 ((20 |-> z20) (v:num->A))))))
               (ebv_eq_form 20 6 7 5 && ebv_eq_form 21 7 8 5 &&
                ebv_eq_form 22 6 8 5 &&
                bmeet_form 5 2 20 21 23 && bimp_form 5 2 23 22 24 &&
                Not(btop_form 5 2 24)) <=>
             ebv_eq D E (v 2) (v 5) (v 6) (v 7) z20 /\
             ebv_eq D E (v 2) (v 5) (v 7) (v 8) z21 /\
             ebv_eq D E (v 2) (v 5) (v 6) (v 8) z22 /\
             emeet D E (v 2) (v 5) z20 z21 z23 /\
             ebimp D E (v 2) (v 5) z23 z22 z24 /\
             ~etop D E (v 2) (v 5) z24)`
    (LABEL_TAC "blk") THENL [blk_tac; use_tac]]);;

(* ========================================================================= *)
(* Wrapper lemma 3 for the fundamental congruence: the semantic              *)
(* cfails predicate ccfl, and the three progressive "bad-triple"             *)
(* object forms cong_bad_{max,med,min}_form for the 3-fold-nested            *)
(* EORDINAL_LEAST on the sorted rank-triple (max3,med3,min3).                *)
(* Names are exists-bound at slots 6,7,8; ranks at 9,10,1; the level's       *)
(* minimized sorted-rank goes to slot 0; earlier levels' values are          *)
(* read from param slots 15 (=d1*=max3) and 16 (=d2*=med3).                  *)
(* ========================================================================= *)
(* Semantic "congruence-fails": C1 or C2 or C3 fails for the B-name triple   *)
(* u,v,w.  Matches HOLDS_CFAILS_FORM's RHS with B=v2,leq=v5,u=v6,v=v7,w=v8.  *)
let ccfl = new_definition
  `ccfl D (E:A->A->bool) B leq u v w <=>
     (?z20 z21 z22 z23 z24.
        z20 IN D /\ z21 IN D /\ z22 IN D /\ z23 IN D /\ z24 IN D /\
        ebv_eq D E B leq u v z20 /\ ebv_in D E B leq u w z21 /\
        ebv_in D E B leq v w z22 /\ emeet D E B leq z20 z21 z23 /\
        ebimp D E B leq z23 z22 z24 /\ ~etop D E B leq z24) \/
     (?z20 z21 z22 z23 z24.
        z20 IN D /\ z21 IN D /\ z22 IN D /\ z23 IN D /\ z24 IN D /\
        ebv_eq D E B leq u v z20 /\ ebv_in D E B leq w u z21 /\
        ebv_in D E B leq w v z22 /\ emeet D E B leq z20 z21 z23 /\
        ebimp D E B leq z23 z22 z24 /\ ~etop D E B leq z24) \/
     (?z20 z21 z22 z23 z24.
        z20 IN D /\ z21 IN D /\ z22 IN D /\ z23 IN D /\ z24 IN D /\
        ebv_eq D E B leq u v z20 /\ ebv_eq D E B leq v w z21 /\
        ebv_eq D E B leq u w z22 /\ emeet D E B leq z20 z21 z23 /\
        ebimp D E B leq z23 z22 z24 /\ ~etop D E B leq z24)`;;

let HOLDS_CFAILS_CCFL = prove
 (`!D (E:A->A->bool) v.
      model D E ZF_AX /\ valuation D v
      ==> (holds D E v cfails_form <=>
           ccfl D E (v 2) (v 5) (v 6) (v 7) (v 8))`,
  REPEAT STRIP_TAC THEN ASM_SIMP_TAC[HOLDS_CFAILS_FORM] THEN
  REWRITE_TAC[ccfl]);;

let cong_bad_max_form = new_definition
  `cong_bad_max_form =
     ?? 6 (?? 7 (?? 8 (?? 9 (?? 10 (?? 1 (
        bname_form 6 && bname_form 7 && bname_form 8 &&
        bnrankp_form 6 9 && bnrankp_form 7 10 && bnrankp_form 8 1 &&
        bmax3_form 9 10 1 0 && cfails_form))))))`;;

let HOLDS_CONG_BAD_MAX_FORM = prove
 (`!D (E:A->A->bool) v.
      model D E ZF_AX /\ valuation D v
      ==> (holds D E v cong_bad_max_form <=>
           (?a b c ra rb rc.
              a IN D /\ b IN D /\ c IN D /\ ra IN D /\ rb IN D /\ rc IN D /\
              bname D E (v 2) a /\ bname D E (v 2) b /\ bname D E (v 2) c /\
              ebnrank D E (v 2) a ra /\ ebnrank D E (v 2) b rb /\
              ebnrank D E (v 2) c rc /\
              emax3 D E ra rb rc (v 0) /\
              ccfl D E (v 2) (v 5) a b c))`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN
   `!a b c ra rb rc:A.
      a IN D /\ b IN D /\ c IN D /\ ra IN D /\ rb IN D /\ rc IN D
      ==> (holds D E
             ((1 |-> rc) ((10 |-> rb) ((9 |-> ra) ((8 |-> c) ((7 |-> b)
               ((6 |-> a) (v:num->A)))))))
             (bname_form 6 && bname_form 7 && bname_form 8 &&
              bnrankp_form 6 9 && bnrankp_form 7 10 && bnrankp_form 8 1 &&
              bmax3_form 9 10 1 0 && cfails_form) <=>
           bname D E (v 2) a /\ bname D E (v 2) b /\ bname D E (v 2) c /\
           ebnrank D E (v 2) a ra /\ ebnrank D E (v 2) b rb /\
           ebnrank D E (v 2) c rc /\
           emax3 D E ra rb rc (v 0) /\
           ccfl D E (v 2) (v 5) a b c)`
  (LABEL_TAC "blk") THENL
   [REPEAT GEN_TAC THEN STRIP_TAC THEN
    SUBGOAL_THEN
     `valuation D ((1 |-> rc) ((10 |-> rb) ((9 |-> ra) ((8 |-> c) ((7 |-> b)
        ((6 |-> a) (v:num->A)))))))`
    ASSUME_TAC THENL [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
    ASM_SIMP_TAC[HOLDS_AND; HOLDS_BNAME_FORM; HOLDS_BNRANKP_FORM;
                 HOLDS_BMAX3_FORM; HOLDS_CFAILS_CCFL; ARITH_EQ] THEN
    ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER; ARITH_EQ] THEN
    REWRITE_TAC[GSYM ebnrank];
    REWRITE_TAC[cong_bad_max_form; HOLDS_EX] THEN EQ_TAC THENL
     [INTRO_TAC "@a. aD @b. bD @c. cD @ra. raD @rb. rbD @rc. rcD h" THEN
      MAP_EVERY EXISTS_TAC [`a:A`;`b:A`;`c:A`;`ra:A`;`rb:A`;`rc:A`] THEN
      ASM_REWRITE_TAC[] THEN
      USE_THEN "blk"(fun t -> MP_TAC(SPECL
        [`a:A`;`b:A`;`c:A`;`ra:A`;`rb:A`;`rc:A`] t)) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(SUBST1_TAC o SYM) THEN ASM_REWRITE_TAC[];
      DISCH_THEN(X_CHOOSE_THEN `a:A` (X_CHOOSE_THEN `b:A`
        (X_CHOOSE_THEN `c:A` (X_CHOOSE_THEN `ra:A` (X_CHOOSE_THEN `rb:A`
          (X_CHOOSE_THEN `rc:A` STRIP_ASSUME_TAC)))))) THEN
      EXISTS_TAC `a:A` THEN ASM_REWRITE_TAC[] THEN
      EXISTS_TAC `b:A` THEN ASM_REWRITE_TAC[] THEN
      EXISTS_TAC `c:A` THEN ASM_REWRITE_TAC[] THEN
      EXISTS_TAC `ra:A` THEN ASM_REWRITE_TAC[] THEN
      EXISTS_TAC `rb:A` THEN ASM_REWRITE_TAC[] THEN
      EXISTS_TAC `rc:A` THEN ASM_REWRITE_TAC[] THEN
      USE_THEN "blk"(fun t -> MP_TAC(SPECL
        [`a:A`;`b:A`;`c:A`;`ra:A`;`rb:A`;`rc:A`] t)) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN SUBST1_TAC THEN ASM_REWRITE_TAC[]]]);;

let cong_bad_med_form = new_definition
  `cong_bad_med_form =
     ?? 6 (?? 7 (?? 8 (?? 9 (?? 10 (?? 1 (
        bname_form 6 && bname_form 7 && bname_form 8 &&
        bnrankp_form 6 9 && bnrankp_form 7 10 && bnrankp_form 8 1 &&
        bmax3_form 9 10 1 15 && bmed3_form 9 10 1 0 && cfails_form))))))`;;

let HOLDS_CONG_BAD_MED_FORM = prove
 (`!D (E:A->A->bool) v.
      model D E ZF_AX /\ valuation D v
      ==> (holds D E v cong_bad_med_form <=>
           (?a b c ra rb rc.
              a IN D /\ b IN D /\ c IN D /\ ra IN D /\ rb IN D /\ rc IN D /\
              bname D E (v 2) a /\ bname D E (v 2) b /\ bname D E (v 2) c /\
              ebnrank D E (v 2) a ra /\ ebnrank D E (v 2) b rb /\
              ebnrank D E (v 2) c rc /\
              emax3 D E ra rb rc (v 15) /\ emed3 D E ra rb rc (v 0) /\
              ccfl D E (v 2) (v 5) a b c))`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN
   `!a b c ra rb rc:A.
      a IN D /\ b IN D /\ c IN D /\ ra IN D /\ rb IN D /\ rc IN D
      ==> (holds D E
             ((1 |-> rc) ((10 |-> rb) ((9 |-> ra) ((8 |-> c) ((7 |-> b)
               ((6 |-> a) (v:num->A)))))))
             (bname_form 6 && bname_form 7 && bname_form 8 &&
              bnrankp_form 6 9 && bnrankp_form 7 10 && bnrankp_form 8 1 &&
              bmax3_form 9 10 1 15 && bmed3_form 9 10 1 0 && cfails_form) <=>
           bname D E (v 2) a /\ bname D E (v 2) b /\ bname D E (v 2) c /\
           ebnrank D E (v 2) a ra /\ ebnrank D E (v 2) b rb /\
           ebnrank D E (v 2) c rc /\
           emax3 D E ra rb rc (v 15) /\ emed3 D E ra rb rc (v 0) /\
           ccfl D E (v 2) (v 5) a b c)`
  (LABEL_TAC "blk") THENL
   [REPEAT GEN_TAC THEN STRIP_TAC THEN
    SUBGOAL_THEN
     `valuation D ((1 |-> rc) ((10 |-> rb) ((9 |-> ra) ((8 |-> c) ((7 |-> b)
        ((6 |-> a) (v:num->A)))))))`
    ASSUME_TAC THENL [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
    ASM_SIMP_TAC[HOLDS_AND; HOLDS_BNAME_FORM; HOLDS_BNRANKP_FORM;
                 HOLDS_BMAX3_FORM; HOLDS_BMED3_FORM; HOLDS_CFAILS_CCFL;
                 ARITH_EQ] THEN
    ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER; ARITH_EQ] THEN
    REWRITE_TAC[GSYM ebnrank];
    REWRITE_TAC[cong_bad_med_form; HOLDS_EX] THEN EQ_TAC THENL
     [INTRO_TAC "@a. aD @b. bD @c. cD @ra. raD @rb. rbD @rc. rcD h" THEN
      MAP_EVERY EXISTS_TAC [`a:A`;`b:A`;`c:A`;`ra:A`;`rb:A`;`rc:A`] THEN
      ASM_REWRITE_TAC[] THEN
      USE_THEN "blk"(fun t -> MP_TAC(SPECL
        [`a:A`;`b:A`;`c:A`;`ra:A`;`rb:A`;`rc:A`] t)) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(SUBST1_TAC o SYM) THEN ASM_REWRITE_TAC[];
      DISCH_THEN(X_CHOOSE_THEN `a:A` (X_CHOOSE_THEN `b:A`
        (X_CHOOSE_THEN `c:A` (X_CHOOSE_THEN `ra:A` (X_CHOOSE_THEN `rb:A`
          (X_CHOOSE_THEN `rc:A` STRIP_ASSUME_TAC)))))) THEN
      EXISTS_TAC `a:A` THEN ASM_REWRITE_TAC[] THEN
      EXISTS_TAC `b:A` THEN ASM_REWRITE_TAC[] THEN
      EXISTS_TAC `c:A` THEN ASM_REWRITE_TAC[] THEN
      EXISTS_TAC `ra:A` THEN ASM_REWRITE_TAC[] THEN
      EXISTS_TAC `rb:A` THEN ASM_REWRITE_TAC[] THEN
      EXISTS_TAC `rc:A` THEN ASM_REWRITE_TAC[] THEN
      USE_THEN "blk"(fun t -> MP_TAC(SPECL
        [`a:A`;`b:A`;`c:A`;`ra:A`;`rb:A`;`rc:A`] t)) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN SUBST1_TAC THEN ASM_REWRITE_TAC[]]]);;

let cong_bad_min_form = new_definition
  `cong_bad_min_form =
     ?? 6 (?? 7 (?? 8 (?? 9 (?? 10 (?? 1 (
        bname_form 6 && bname_form 7 && bname_form 8 &&
        bnrankp_form 6 9 && bnrankp_form 7 10 && bnrankp_form 8 1 &&
        bmax3_form 9 10 1 15 && bmed3_form 9 10 1 16 && bmin3_form 9 10 1 0 &&
        cfails_form))))))`;;

let HOLDS_CONG_BAD_MIN_FORM = prove
 (`!D (E:A->A->bool) v.
      model D E ZF_AX /\ valuation D v
      ==> (holds D E v cong_bad_min_form <=>
           (?a b c ra rb rc.
              a IN D /\ b IN D /\ c IN D /\ ra IN D /\ rb IN D /\ rc IN D /\
              bname D E (v 2) a /\ bname D E (v 2) b /\ bname D E (v 2) c /\
              ebnrank D E (v 2) a ra /\ ebnrank D E (v 2) b rb /\
              ebnrank D E (v 2) c rc /\
              emax3 D E ra rb rc (v 15) /\ emed3 D E ra rb rc (v 16) /\
              emin3 D E ra rb rc (v 0) /\
              ccfl D E (v 2) (v 5) a b c))`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN
   `!a b c ra rb rc:A.
      a IN D /\ b IN D /\ c IN D /\ ra IN D /\ rb IN D /\ rc IN D
      ==> (holds D E
             ((1 |-> rc) ((10 |-> rb) ((9 |-> ra) ((8 |-> c) ((7 |-> b)
               ((6 |-> a) (v:num->A)))))))
             (bname_form 6 && bname_form 7 && bname_form 8 &&
              bnrankp_form 6 9 && bnrankp_form 7 10 && bnrankp_form 8 1 &&
              bmax3_form 9 10 1 15 && bmed3_form 9 10 1 16 &&
              bmin3_form 9 10 1 0 && cfails_form) <=>
           bname D E (v 2) a /\ bname D E (v 2) b /\ bname D E (v 2) c /\
           ebnrank D E (v 2) a ra /\ ebnrank D E (v 2) b rb /\
           ebnrank D E (v 2) c rc /\
           emax3 D E ra rb rc (v 15) /\ emed3 D E ra rb rc (v 16) /\
           emin3 D E ra rb rc (v 0) /\
           ccfl D E (v 2) (v 5) a b c)`
  (LABEL_TAC "blk") THENL
   [REPEAT GEN_TAC THEN STRIP_TAC THEN
    SUBGOAL_THEN
     `valuation D ((1 |-> rc) ((10 |-> rb) ((9 |-> ra) ((8 |-> c) ((7 |-> b)
        ((6 |-> a) (v:num->A)))))))`
    ASSUME_TAC THENL [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
    ASM_SIMP_TAC[HOLDS_AND; HOLDS_BNAME_FORM; HOLDS_BNRANKP_FORM;
                 HOLDS_BMAX3_FORM; HOLDS_BMED3_FORM; HOLDS_BMIN3_FORM;
                 HOLDS_CFAILS_CCFL; ARITH_EQ] THEN
    ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER; ARITH_EQ] THEN
    REWRITE_TAC[GSYM ebnrank];
    REWRITE_TAC[cong_bad_min_form; HOLDS_EX] THEN EQ_TAC THENL
     [INTRO_TAC "@a. aD @b. bD @c. cD @ra. raD @rb. rbD @rc. rcD h" THEN
      MAP_EVERY EXISTS_TAC [`a:A`;`b:A`;`c:A`;`ra:A`;`rb:A`;`rc:A`] THEN
      ASM_REWRITE_TAC[] THEN
      USE_THEN "blk"(fun t -> MP_TAC(SPECL
        [`a:A`;`b:A`;`c:A`;`ra:A`;`rb:A`;`rc:A`] t)) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(SUBST1_TAC o SYM) THEN ASM_REWRITE_TAC[];
      DISCH_THEN(X_CHOOSE_THEN `a:A` (X_CHOOSE_THEN `b:A`
        (X_CHOOSE_THEN `c:A` (X_CHOOSE_THEN `ra:A` (X_CHOOSE_THEN `rb:A`
          (X_CHOOSE_THEN `rc:A` STRIP_ASSUME_TAC)))))) THEN
      EXISTS_TAC `a:A` THEN ASM_REWRITE_TAC[] THEN
      EXISTS_TAC `b:A` THEN ASM_REWRITE_TAC[] THEN
      EXISTS_TAC `c:A` THEN ASM_REWRITE_TAC[] THEN
      EXISTS_TAC `ra:A` THEN ASM_REWRITE_TAC[] THEN
      EXISTS_TAC `rb:A` THEN ASM_REWRITE_TAC[] THEN
      EXISTS_TAC `rc:A` THEN ASM_REWRITE_TAC[] THEN
      USE_THEN "blk"(fun t -> MP_TAC(SPECL
        [`a:A`;`b:A`;`c:A`;`ra:A`;`rb:A`;`rc:A`] t)) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN SUBST1_TAC THEN ASM_REWRITE_TAC[]]]);;

(* ========================================================================= *)
(* Lemma 4a for the fundamental congruence: the three levels of the          *)
(* lex-least bad-triple search.  badmax/badmed/badmin package "some          *)
(* bad triple has this (max3 / max3,med3 / max3,med3,min3) sorted-rank"      *)
(* HOLDS_BAD{MAX,MED,MIN} bridge each to holds cong_bad_*_form on            *)
(* (0|->d)v (v2=B,v5=leq,v15=d1,v16=d2), and LBT1/LBT2/LBT3 run one          *)
(* EORDINAL_LEAST each to minimize that level's ordinal (slot 0).            *)
(* ========================================================================= *)
(* "some bad triple has max-rank d" -- matches HOLDS_CONG_BAD_MAX_FORM's     *)
(* char.                                                                     *)
let badmax = new_definition
  `badmax D (E:A->A->bool) B leq d <=>
     (?a b c ra rb rc.
        a IN D /\ b IN D /\ c IN D /\ ra IN D /\ rb IN D /\ rc IN D /\
        bname D E B a /\ bname D E B b /\ bname D E B c /\
        ebnrank D E B a ra /\ ebnrank D E B b rb /\ ebnrank D E B c rc /\
        emax3 D E ra rb rc d /\ ccfl D E B leq a b c)`;;

let HOLDS_BADMAX = prove
 (`!D (E:A->A->bool) B leq v d.
      model D E ZF_AX /\ valuation D v /\ v 2 = B /\ v 5 = leq /\ d IN D
      ==> (holds D E ((0 |-> d) v) cong_bad_max_form <=> badmax D E B leq d)`,
  REPEAT STRIP_TAC THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`(0 |-> (d:A)) v`]
    HOLDS_CONG_BAD_MAX_FORM) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[] THEN MATCH_MP_TAC VALUATION_VALMOD THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  DISCH_THEN SUBST1_TAC THEN
  ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER; ARITH_EQ] THEN
  REWRITE_TAC[badmax]);;

(* Level 1 of the lex-least search: least max-rank of a bad triple. *)
let LBT1 = prove
 (`!D (E:A->A->bool) B leq v.
      model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
      valuation D v /\ v 2 = B /\ v 5 = leq /\
      (?M0. M0 IN D /\ eordinal D E M0 /\ badmax D E B leq M0)
      ==> (?d1. d1 IN D /\ eordinal D E d1 /\ badmax D E B leq d1 /\
                (!c. c IN D /\ E c d1 ==> ~badmax D E B leq c))`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `holds D (E:A->A->bool) ((0 |-> M0) v) cong_bad_max_form`
  ASSUME_TAC THENL
   [ASM_MESON_TAC[HOLDS_BADMAX]; ALL_TAC] THEN
  MP_TAC(ISPECL
         [`D:A->bool`;`E:A->A->bool`;`cong_bad_max_form`;`v:num->A`;`M0:A`]
         EORDINAL_LEAST) THEN
  ASM_REWRITE_TAC[] THEN
  INTRO_TAC "@d1. d1D ordd badd min" THEN
  EXISTS_TAC `d1:A` THEN ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
   [ASM_MESON_TAC[HOLDS_BADMAX];
    X_GEN_TAC `c:A` THEN STRIP_TAC THEN
    USE_THEN "min" (fun th -> MP_TAC(MATCH_MP th
      (CONJ (ASSUME `(c:A) IN D`) (ASSUME `(E:A->A->bool) c d1`)))) THEN
    ASM_MESON_TAC[HOLDS_BADMAX]]);;

let badmed = new_definition
  `badmed D (E:A->A->bool) B leq d1 d <=>
     (?a b c ra rb rc.
        a IN D /\ b IN D /\ c IN D /\ ra IN D /\ rb IN D /\ rc IN D /\
        bname D E B a /\ bname D E B b /\ bname D E B c /\
        ebnrank D E B a ra /\ ebnrank D E B b rb /\ ebnrank D E B c rc /\
        emax3 D E ra rb rc d1 /\ emed3 D E ra rb rc d /\
          ccfl D E B leq a b c)`;;

let HOLDS_BADMED = prove
 (`!D (E:A->A->bool) B leq v d1 d.
      model D E ZF_AX /\ valuation D v /\ v 2 = B /\ v 5 = leq /\ v 15 = d1 /\
      d IN D
      ==> (holds D E ((0 |-> d) v) cong_bad_med_form <=>
           badmed D E B leq d1 d)`,
  REPEAT STRIP_TAC THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`(0 |-> (d:A)) v`]
    HOLDS_CONG_BAD_MED_FORM) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[] THEN MATCH_MP_TAC VALUATION_VALMOD THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  DISCH_THEN SUBST1_TAC THEN
  ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER; ARITH_EQ] THEN
  REWRITE_TAC[badmed]);;

let LBT2 = prove
 (`!D (E:A->A->bool) B leq v d1.
      model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
      valuation D v /\ v 2 = B /\ v 5 = leq /\ v 15 = d1 /\
      (?M0. M0 IN D /\ eordinal D E M0 /\ badmed D E B leq d1 M0)
      ==> (?d2. d2 IN D /\ eordinal D E d2 /\ badmed D E B leq d1 d2 /\
                (!c. c IN D /\ E c d2 ==> ~badmed D E B leq d1 c))`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `holds D (E:A->A->bool) ((0 |-> M0) v) cong_bad_med_form`
  ASSUME_TAC THENL
   [ASM_MESON_TAC[HOLDS_BADMED]; ALL_TAC] THEN
  MP_TAC(ISPECL
         [`D:A->bool`;`E:A->A->bool`;`cong_bad_med_form`;`v:num->A`;`M0:A`]
         EORDINAL_LEAST) THEN
  ASM_REWRITE_TAC[] THEN
  INTRO_TAC "@d2. d2D ordd badd min" THEN
  EXISTS_TAC `d2:A` THEN ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
   [ASM_MESON_TAC[HOLDS_BADMED];
    X_GEN_TAC `c:A` THEN STRIP_TAC THEN
    USE_THEN "min" (fun th -> MP_TAC(MATCH_MP th
      (CONJ (ASSUME `(c:A) IN D`) (ASSUME `(E:A->A->bool) c d2`)))) THEN
    ASM_MESON_TAC[HOLDS_BADMED]]);;

let badmin = new_definition
  `badmin D (E:A->A->bool) B leq d1 d2 d <=>
     (?a b c ra rb rc.
        a IN D /\ b IN D /\ c IN D /\ ra IN D /\ rb IN D /\ rc IN D /\
        bname D E B a /\ bname D E B b /\ bname D E B c /\
        ebnrank D E B a ra /\ ebnrank D E B b rb /\ ebnrank D E B c rc /\
        emax3 D E ra rb rc d1 /\ emed3 D E ra rb rc d2 /\
        emin3 D E ra rb rc d /\ ccfl D E B leq a b c)`;;

let HOLDS_BADMIN = prove
 (`!D (E:A->A->bool) B leq v d1 d2 d.
      model D E ZF_AX /\ valuation D v /\ v 2 = B /\ v 5 = leq /\
      v 15 = d1 /\ v 16 = d2 /\ d IN D
      ==> (holds D E ((0 |-> d) v) cong_bad_min_form <=>
           badmin D E B leq d1 d2 d)`,
  REPEAT STRIP_TAC THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`(0 |-> (d:A)) v`]
    HOLDS_CONG_BAD_MIN_FORM) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[] THEN MATCH_MP_TAC VALUATION_VALMOD THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  DISCH_THEN SUBST1_TAC THEN
  ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER; ARITH_EQ] THEN
  REWRITE_TAC[badmin]);;

let LBT3 = prove
 (`!D (E:A->A->bool) B leq v d1 d2.
      model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
      valuation D v /\ v 2 = B /\ v 5 = leq /\ v 15 = d1 /\ v 16 = d2 /\
      (?M0. M0 IN D /\ eordinal D E M0 /\ badmin D E B leq d1 d2 M0)
      ==> (?d3. d3 IN D /\ eordinal D E d3 /\ badmin D E B leq d1 d2 d3 /\
                (!c. c IN D /\ E c d3 ==> ~badmin D E B leq d1 d2 c))`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `holds D (E:A->A->bool) ((0 |-> M0) v) cong_bad_min_form`
  ASSUME_TAC THENL
   [ASM_MESON_TAC[HOLDS_BADMIN]; ALL_TAC] THEN
  MP_TAC(ISPECL
         [`D:A->bool`;`E:A->A->bool`;`cong_bad_min_form`;`v:num->A`;`M0:A`]
         EORDINAL_LEAST) THEN
  ASM_REWRITE_TAC[] THEN
  INTRO_TAC "@d3. d3D ordd badd min" THEN
  EXISTS_TAC `d3:A` THEN ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
   [ASM_MESON_TAC[HOLDS_BADMIN];
    X_GEN_TAC `c:A` THEN STRIP_TAC THEN
    USE_THEN "min" (fun th -> MP_TAC(MATCH_MP th
      (CONJ (ASSUME `(c:A) IN D`) (ASSUME `(E:A->A->bool) c d3`)))) THEN
    ASM_MESON_TAC[HOLDS_BADMIN]]);;

(* ================================================================== *)
(* Lemma 4b: LEAST_BAD_TRIPLE composes the three EORDINAL_LEAST levels *)
(* (LBT1;LBT2;LBT3) into a single lex-least bad triple with all three  *)
(* leastness facts; REDUCED_GOOD turns those into "any triple whose    *)
(* sorted rank-triple is lex-strictly-below (d1,d2,d3) is not ccfl".   *)
(* ================================================================== *)
let LEAST_BAD_TRIPLE = prove
 (`!D (E:A->A->bool) B leq.
      model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
      (?a b c. a IN D /\ b IN D /\ c IN D /\
               bname D E B a /\ bname D E B b /\ bname D E B c /\
               ccfl D E B leq a b c)
      ==> (?d1 d2 d3.
             d1 IN D /\ d2 IN D /\ d3 IN D /\
             eordinal D E d1 /\ eordinal D E d2 /\ eordinal D E d3 /\
             badmin D E B leq d1 d2 d3 /\
             (!c. c IN D /\ E c d1 ==> ~badmax D E B leq c) /\
             (!c. c IN D /\ E c d2 ==> ~badmed D E B leq d1 c) /\
             (!c. c IN D /\ E c d3 ==> ~badmin D E B leq d1 d2 c))`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  FIRST_ASSUM(X_CHOOSE_TAC `v0:num->A` o MATCH_MP VALUATION_EXISTS o
              MATCH_MP MODEL_NONEMPTY) THEN
  ABBREV_TAC `v = (5 |-> (leq:A)) ((2 |-> (B:A)) v0)` THEN
  SUBGOAL_THEN
    `valuation D (v:num->A) /\ (v:num->A) 2 = B /\ (v:num->A) 5 = leq`
  STRIP_ASSUME_TAC THENL
   [EXPAND_TAC "v" THEN REPEAT CONJ_TAC THENL
     [ASM_MESON_TAC[VALUATION_VALMOD]; REWRITE_TAC[VALMOD; ARITH_EQ];
      REWRITE_TAC[VALMOD]]; ALL_TAC] THEN
  (* ranks + max3 of the initial bad triple *)
  SUBGOAL_THEN `?ra:A. ra IN D /\ ebnrank D E B a ra`
    (X_CHOOSE_TAC `ra:A`) THENL
   [ASM_MESON_TAC[EBNRANK_EXISTS]; ALL_TAC] THEN
  SUBGOAL_THEN `?rb:A. rb IN D /\ ebnrank D E B b rb`
    (X_CHOOSE_TAC `rb:A`) THENL
   [ASM_MESON_TAC[EBNRANK_EXISTS]; ALL_TAC] THEN
  SUBGOAL_THEN `?rc:A. rc IN D /\ ebnrank D E B c rc`
    (X_CHOOSE_TAC `rc:A`) THENL
   [ASM_MESON_TAC[EBNRANK_EXISTS]; ALL_TAC] THEN
  SUBGOAL_THEN
    `eordinal D (E:A->A->bool) ra /\ eordinal D E rb /\ eordinal D E rc`
  STRIP_ASSUME_TAC THENL [ASM_MESON_TAC[EBNRANK_ORDINAL]; ALL_TAC] THEN
  SUBGOAL_THEN `?M0:A. emax3 D E ra rb rc M0` (X_CHOOSE_TAC `M0:A`) THENL
   [ASM_MESON_TAC[EMAX3_EXISTS]; ALL_TAC] THEN
  SUBGOAL_THEN `eordinal D (E:A->A->bool) M0 /\ M0 IN D` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[EMAX3_ORDINAL; EORDINAL_IN]; ALL_TAC] THEN
  (* LBT1 *)
  MP_TAC(ISPECL
         [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`v:num->A`] LBT1) THEN
  ASM_REWRITE_TAC[] THEN
  ANTS_TAC THENL
   [EXISTS_TAC `M0:A` THEN ASM_REWRITE_TAC[badmax] THEN
    MAP_EVERY EXISTS_TAC [`a:A`;`b:A`;`c:A`;`ra:A`;`rb:A`;`rc:A`] THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  INTRO_TAC "@d1. d1D ordd1 bad1 min1" THEN
  (* extract level-1 witness, compute its med3 *)
  USE_THEN "bad1" (MP_TAC o REWRITE_RULE[badmax]) THEN
  DISCH_THEN(X_CHOOSE_THEN `pa:A` (X_CHOOSE_THEN `pb:A` (X_CHOOSE_THEN `pc:A`
    (X_CHOOSE_THEN `pra:A` (X_CHOOSE_THEN `prb:A` (X_CHOOSE_THEN `prc:A`
      STRIP_ASSUME_TAC)))))) THEN
  SUBGOAL_THEN `?M1:A. emed3 D E pra prb prc M1` (X_CHOOSE_TAC `M1:A`) THENL
   [ASM_MESON_TAC[EMED3_EXISTS]; ALL_TAC] THEN
  SUBGOAL_THEN `eordinal D (E:A->A->bool) M1 /\ M1 IN D` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[EMED3_ORDINAL; EORDINAL_IN; EBNRANK_ORDINAL]; ALL_TAC] THEN
  (* v' carries d1 at slot 15 *)
  ABBREV_TAC `v' = (15 |-> (d1:A)) (v:num->A)` THEN
  SUBGOAL_THEN
   `valuation D (v':num->A) /\ (v':num->A) 2 = B /\ (v':num->A) 5 = leq /\
    (v':num->A) 15 = d1`
  STRIP_ASSUME_TAC THENL
   [EXPAND_TAC "v'" THEN REPEAT CONJ_TAC THEN
    ASM_SIMP_TAC[VALUATION_VALMOD; VALMOD_BASIC; VALMOD_OTHER; ARITH_EQ];
    ALL_TAC] THEN
  (* LBT2 *)
  MP_TAC(ISPECL
         [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`v':num->A`;
          `d1:A`] LBT2) THEN
  ASM_REWRITE_TAC[] THEN
  ANTS_TAC THENL
   [EXISTS_TAC `M1:A` THEN ASM_REWRITE_TAC[badmed] THEN
    MAP_EVERY EXISTS_TAC [`pa:A`;`pb:A`;`pc:A`;`pra:A`;`prb:A`;`prc:A`] THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  INTRO_TAC "@d2. d2D ordd2 bad2 min2" THEN
  (* extract level-2 witness, compute its min3 *)
  USE_THEN "bad2" (MP_TAC o REWRITE_RULE[badmed]) THEN
  DISCH_THEN(X_CHOOSE_THEN `qa:A` (X_CHOOSE_THEN `qb:A` (X_CHOOSE_THEN `qc:A`
    (X_CHOOSE_THEN `qra:A` (X_CHOOSE_THEN `qrb:A` (X_CHOOSE_THEN `qrc:A`
      STRIP_ASSUME_TAC)))))) THEN
  SUBGOAL_THEN `?M2:A. emin3 D E qra qrb qrc M2` (X_CHOOSE_TAC `M2:A`) THENL
   [ASM_MESON_TAC[EMIN3_EXISTS]; ALL_TAC] THEN
  SUBGOAL_THEN `eordinal D (E:A->A->bool) M2 /\ M2 IN D` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[EMIN3_ORDINAL; EORDINAL_IN; EBNRANK_ORDINAL]; ALL_TAC] THEN
  (* v'' carries d2 at slot 16 *)
  ABBREV_TAC `v'' = (16 |-> (d2:A)) (v':num->A)` THEN
  SUBGOAL_THEN
   `valuation D (v'':num->A) /\ (v'':num->A) 2 = B /\ (v'':num->A) 5 = leq /\
    (v'':num->A) 15 = d1 /\ (v'':num->A) 16 = d2`
  STRIP_ASSUME_TAC THENL
   [EXPAND_TAC "v''" THEN REPEAT CONJ_TAC THEN
    ASM_SIMP_TAC[VALUATION_VALMOD; VALMOD_BASIC; VALMOD_OTHER; ARITH_EQ];
    ALL_TAC] THEN
  (* LBT3 *)
  MP_TAC(ISPECL
         [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`v'':num->A`;`d1:A`;`d2:A`]
         LBT3) THEN
  ASM_REWRITE_TAC[] THEN
  ANTS_TAC THENL
   [EXISTS_TAC `M2:A` THEN ASM_REWRITE_TAC[badmin] THEN
    MAP_EVERY EXISTS_TAC [`qa:A`;`qb:A`;`qc:A`;`qra:A`;`qrb:A`;`qrc:A`] THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  INTRO_TAC "@d3. d3D ordd3 bad3 min3" THEN
  MAP_EVERY EXISTS_TAC [`d1:A`;`d2:A`;`d3:A`] THEN ASM_REWRITE_TAC[]);;

(* Any triple whose sorted rank-triple is lex-strictly-below (d1,d2,d3) is   *)
(* not bad, given the three leastness facts from LEAST_BAD_TRIPLE.           *)
let REDUCED_GOOD = prove
 (`!D (E:A->A->bool) B leq d1 d2 d3.
      (!c. c IN D /\ E c d1 ==> ~badmax D E B leq c) /\
      (!c. c IN D /\ E c d2 ==> ~badmed D E B leq d1 c) /\
      (!c. c IN D /\ E c d3 ==> ~badmin D E B leq d1 d2 c)
      ==> !u v w ra rb rc M' Dp m'.
            u IN D /\ v IN D /\ w IN D /\ ra IN D /\ rb IN D /\ rc IN D /\
            M' IN D /\ Dp IN D /\ m' IN D /\
            bname D E B u /\ bname D E B v /\ bname D E B w /\
            ebnrank D E B u ra /\ ebnrank D E B v rb /\ ebnrank D E B w rc /\
            emax3 D E ra rb rc M' /\ emed3 D E ra rb rc Dp /\
            emin3 D E ra rb rc m' /\
            (E M' d1 \/ M' = d1 /\ E Dp d2 \/ M' = d1 /\ Dp = d2 /\ E m' d3)
            ==> ~ccfl D E B leq u v w`,
  REPEAT GEN_TAC THEN
  DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "m1") (CONJUNCTS_THEN2
    (LABEL_TAC "m2") (LABEL_TAC "m3"))) THEN
  REPEAT STRIP_TAC THENL
   [SUBGOAL_THEN `badmax D (E:A->A->bool) B leq M'` ASSUME_TAC THENL
     [REWRITE_TAC[badmax] THEN
      MAP_EVERY EXISTS_TAC [`u:A`;`v:A`;`w:A`;`ra:A`;`rb:A`;`rc:A`] THEN
      ASM_REWRITE_TAC[]; ALL_TAC] THEN
    USE_THEN "m1" (fun th -> MP_TAC(SPEC `M':A` th)) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN ASM_REWRITE_TAC[];
    SUBGOAL_THEN `badmed D (E:A->A->bool) B leq d1 Dp` ASSUME_TAC THENL
     [REWRITE_TAC[badmed] THEN
      MAP_EVERY EXISTS_TAC [`u:A`;`v:A`;`w:A`;`ra:A`;`rb:A`;`rc:A`] THEN
      ASM_MESON_TAC[]; ALL_TAC] THEN
    USE_THEN "m2" (fun th -> MP_TAC(SPEC `Dp:A` th)) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN ASM_REWRITE_TAC[];
    SUBGOAL_THEN `badmin D (E:A->A->bool) B leq d1 d2 m'` ASSUME_TAC THENL
     [REWRITE_TAC[badmin] THEN
      MAP_EVERY EXISTS_TAC [`u:A`;`v:A`;`w:A`;`ra:A`;`rb:A`;`rc:A`] THEN
      ASM_MESON_TAC[]; ALL_TAC] THEN
    USE_THEN "m3" (fun th -> MP_TAC(SPEC `m':A` th)) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN ASM_REWRITE_TAC[]]);;

(* ------------------------------------------------------------------ *)
(* BNAME_DIRECTED3 : a common B-name stage for THREE B-names (needed by *)
(* each NO_BAD case to invoke the stage-level C*_STEP lemmas).  Built  *)
(* from BNAME_DIRECTED (u,v) and (w,w), lifting both stages into the   *)
(* stage at ESUC(ebunion a1 a2) via EBNSTAGE_MONO.                      *)
(* ------------------------------------------------------------------ *)
let BNAME_DIRECTED3 = prove
 (`!D (E:A->A->bool) B u v w.
      model D E ZF_AX /\ B IN D /\ u IN D /\ v IN D /\ w IN D /\
      bname D E B u /\ bname D E B v /\ bname D E B w
      ==> ?a y. a IN D /\ y IN D /\ eordinal D E a /\ ebnstage D E B a y /\
                E u y /\ E v y /\ E w y`,
  REPEAT STRIP_TAC THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`u:A`;`v:A`]
         BNAME_DIRECTED) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `a1:A` (X_CHOOSE_THEN `y1:A` STRIP_ASSUME_TAC)) THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`w:A`;`w:A`]
         BNAME_DIRECTED) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `a2:A` (X_CHOOSE_THEN `y2:A` STRIP_ASSUME_TAC)) THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`a1:A`;`a2:A`] EBUNION_EXISTS) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `eb:A`) THEN
  SUBGOAL_THEN `(eb:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[EBUNION_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `eordinal D (E:A->A->bool) eb` ASSUME_TAC THENL
   [MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`a1:A`;`a2:A`;`eb:A`]
      EBUNION_ORDINAL_MAX) THEN ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[];
         ALL_TAC] THEN
  SUBGOAL_THEN `!c. c IN D /\ E c a1 ==> (E:A->A->bool) c eb` ASSUME_TAC THENL
   [MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`a1:A`;`a2:A`;`eb:A`]
           EBUNION_ALT) THEN
    ASM_REWRITE_TAC[] THEN MESON_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `!c. c IN D /\ E c a2 ==> (E:A->A->bool) c eb` ASSUME_TAC THENL
   [MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`a1:A`;`a2:A`;`eb:A`]
           EBUNION_ALT) THEN
    ASM_REWRITE_TAC[] THEN MESON_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) a1 eb \/ a1 = eb` ASSUME_TAC THENL
   [MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`a1:A`;`eb:A`]
           EORDINAL_SUBSET_MEMBER) THEN
    ASM_REWRITE_TAC[esubset] THEN ASM_MESON_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) a2 eb \/ a2 = eb` ASSUME_TAC THENL
   [MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`a2:A`;`eb:A`]
           EORDINAL_SUBSET_MEMBER) THEN
    ASM_REWRITE_TAC[esubset] THEN ASM_MESON_TAC[]; ALL_TAC] THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`eb:A`] ESUC_EXISTS) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `seb:A`) THEN
  SUBGOAL_THEN `(seb:A) IN D /\ eordinal D (E:A->A->bool) seb /\ E eb seb`
  STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[ESUC_IN; EORDINAL_ESUC; ESUC_MEMBER]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) a1 seb /\ (E:A->A->bool) a2 seb`
    STRIP_ASSUME_TAC THENL
   [CONJ_TAC THEN ASM_MESON_TAC[EORDINAL_TRANS_E]; ALL_TAC] THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`seb:A`]
         EBNSTAGE_EXISTS) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_THEN `y:A` STRIP_ASSUME_TAC) THEN
  MAP_EVERY EXISTS_TAC [`seb:A`;`y:A`] THEN ASM_REWRITE_TAC[] THEN
  REPEAT CONJ_TAC THENL
   [MP_TAC(ISPECL
           [`D:A->bool`;`E:A->A->bool`;`B:A`;`seb:A`;`a1:A`;`y:A`;`y1:A`;`u:A`]
           EBNSTAGE_MONO) THEN ASM_REWRITE_TAC[];
    MP_TAC(ISPECL
           [`D:A->bool`;`E:A->A->bool`;`B:A`;`seb:A`;`a1:A`;`y:A`;`y1:A`;`v:A`]
           EBNSTAGE_MONO) THEN ASM_REWRITE_TAC[];
    MP_TAC(ISPECL
           [`D:A->bool`;`E:A->A->bool`;`B:A`;`seb:A`;`a2:A`;`y:A`;`y2:A`;`w:A`]
           EBNSTAGE_MONO) THEN ASM_REWRITE_TAC[]]);;

(* ================================================================== *)
(* F5 CONGRUENCE -- well-founded-induction WRAPPER.                     *)
(* Sorted-rank-triple (max3,med3,min3) SYM lemmas; LEXDROP rank-drop;  *)
(* NOT_CCFL De-Morgan unfolding; C1_STEP2/C3_STEP2; IH-dischargers;    *)
(* NO_BAD_C1/C2/C3 case lemmas; NO_BAD (no lex-least bad triple); and  *)
(* the usable corollary NO_CCFL (for bnames u,v,w: ~ccfl).             *)
(* ================================================================== *)

(* emax3/emed3/emin3 depend only on the MULTISET {a,b,c}: two triples whose  *)
(* element-membership disjunction/conjunction agree pointwise give the same  *)
(* value (via the ALT E-characterizations + set extensionality).  At use     *)
(* sites the pointwise-equivalence hypothesis is a permutation tautology.    *)
let EMAX3_SYM = prove
 (`!D (E:A->A->bool) a b c a2 b2 c2 M M2.
      model D E ZF_AX /\ eordinal D E a /\ eordinal D E b /\ eordinal D E c /\
      eordinal D E a2 /\ eordinal D E b2 /\ eordinal D E c2 /\
      emax3 D E a b c M /\ emax3 D E a2 b2 c2 M2 /\
      (!w. w IN D ==> (E w a \/ E w b \/ E w c <=> E w a2 \/ E w b2 \/ E w c2))
      ==> M = M2`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  FIRST_ASSUM(LABEL_TAC "eqv" o check(is_forall o concl)) THEN
  SUBGOAL_THEN `(a:A) IN D /\ (b:A) IN D /\ (c:A) IN D /\
                (a2:A) IN D /\ (b2:A) IN D /\ (c2:A) IN D`
    STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[EORDINAL_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `(M:A) IN D /\ (M2:A) IN D` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[EMAX3_ORDINAL; EORDINAL_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `!w:A. w IN D ==> (E w M <=> E w (a:A) \/ E w b \/ E w c)`
  (LABEL_TAC "eM") THENL
   [REPEAT STRIP_TAC THEN
    MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`a:A`;`b:A`;`c:A`;`M:A`;`w:A`]
                 EMAX3_ALT) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `!w:A. w IN D ==> (E w M2 <=> E w (a2:A) \/ E w b2 \/ E w c2)`
  (LABEL_TAC "eM2") THENL
   [REPEAT STRIP_TAC THEN
    MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`a2:A`;`b2:A`;`c2:A`;`M2:A`;`w:A`]
                 EMAX3_ALT) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `!w:A. w IN D ==> (E w (M:A) <=> E w M2)` (fun th ->
    MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`M:A`;`M2:A`]
                 ESUBSET_ANTISYM) THEN
    ASM_REWRITE_TAC[esubset] THEN ASM_MESON_TAC[th]) THEN
  X_GEN_TAC `w:A` THEN DISCH_TAC THEN
  USE_THEN "eM2" (fun th -> MP_TAC(MATCH_MP th (ASSUME `(w:A) IN D`))) THEN
  USE_THEN "eM" (fun th -> MP_TAC(MATCH_MP th (ASSUME `(w:A) IN D`))) THEN
  USE_THEN "eqv" (fun th -> MP_TAC(MATCH_MP th (ASSUME `(w:A) IN D`))) THEN
  CONV_TAC TAUT);;

let EMIN3_SYM = prove
 (`!D (E:A->A->bool) a b c a2 b2 c2 m m2.
      model D E ZF_AX /\ eordinal D E a /\ eordinal D E b /\ eordinal D E c /\
      eordinal D E a2 /\ eordinal D E b2 /\ eordinal D E c2 /\
      emin3 D E a b c m /\ emin3 D E a2 b2 c2 m2 /\
      (!w. w IN D ==> (E w a /\ E w b /\ E w c <=> E w a2 /\ E w b2 /\ E w c2))
      ==> m = m2`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  FIRST_ASSUM(LABEL_TAC "eqv" o check(is_forall o concl)) THEN
  SUBGOAL_THEN `(a:A) IN D /\ (b:A) IN D /\ (c:A) IN D /\
                (a2:A) IN D /\ (b2:A) IN D /\ (c2:A) IN D`
    STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[EORDINAL_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `(m:A) IN D /\ (m2:A) IN D` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[EMIN3_ORDINAL; EORDINAL_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `!w:A. w IN D ==> (E w m <=> E w (a:A) /\ E w b /\ E w c)`
  (LABEL_TAC "eM") THENL
   [REPEAT STRIP_TAC THEN
    MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`a:A`;`b:A`;`c:A`;`m:A`;`w:A`]
                 EMIN3_ALT) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `!w:A. w IN D ==> (E w m2 <=> E w (a2:A) /\ E w b2 /\ E w c2)`
  (LABEL_TAC "eM2") THENL
   [REPEAT STRIP_TAC THEN
    MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`a2:A`;`b2:A`;`c2:A`;`m2:A`;`w:A`]
                 EMIN3_ALT) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `!w:A. w IN D ==> (E w (m:A) <=> E w m2)` (fun th ->
    MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`m:A`;`m2:A`]
                 ESUBSET_ANTISYM) THEN
    ASM_REWRITE_TAC[esubset] THEN ASM_MESON_TAC[th]) THEN
  X_GEN_TAC `w:A` THEN DISCH_TAC THEN
  USE_THEN "eM2" (fun th -> MP_TAC(MATCH_MP th (ASSUME `(w:A) IN D`))) THEN
  USE_THEN "eM" (fun th -> MP_TAC(MATCH_MP th (ASSUME `(w:A) IN D`))) THEN
  USE_THEN "eqv" (fun th -> MP_TAC(MATCH_MP th (ASSUME `(w:A) IN D`))) THEN
  CONV_TAC TAUT);;

let EMED3_SYM = prove
 (`!D (E:A->A->bool) a b c a2 b2 c2 d d2.
      model D E ZF_AX /\ eordinal D E a /\ eordinal D E b /\ eordinal D E c /\
      eordinal D E a2 /\ eordinal D E b2 /\ eordinal D E c2 /\
      emed3 D E a b c d /\ emed3 D E a2 b2 c2 d2 /\
      (!w. w IN D
           ==> ((E w a /\ E w b) \/ (E w a /\ E w c) \/ (E w b /\ E w c) <=>
                (E w a2 /\ E w b2) \/ (E w a2 /\ E w c2) \/
                  (E w b2 /\ E w c2)))
      ==> d = d2`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  FIRST_ASSUM(LABEL_TAC "eqv" o check(is_forall o concl)) THEN
  SUBGOAL_THEN `(a:A) IN D /\ (b:A) IN D /\ (c:A) IN D /\
                (a2:A) IN D /\ (b2:A) IN D /\ (c2:A) IN D`
    STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[EORDINAL_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `(d:A) IN D /\ (d2:A) IN D` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[EMED3_ORDINAL; EORDINAL_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `!w:A. w IN D ==> (E w d <=>
                  (E w (a:A) /\ E w b) \/ (E w a /\ E w c) \/
                    (E w b /\ E w c))`
  (LABEL_TAC "eM") THENL
   [REPEAT STRIP_TAC THEN
    MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`a:A`;`b:A`;`c:A`;`d:A`;`w:A`]
                 EMED3_ALT) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `!w:A. w IN D ==> (E w d2 <=>
                  (E w (a2:A) /\ E w b2) \/ (E w a2 /\ E w c2) \/
                    (E w b2 /\ E w c2))`
  (LABEL_TAC "eM2") THENL
   [REPEAT STRIP_TAC THEN
    MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`a2:A`;`b2:A`;`c2:A`;`d2:A`;`w:A`]
                 EMED3_ALT) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `!w:A. w IN D ==> (E w (d:A) <=> E w d2)` (fun th ->
    MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`d:A`;`d2:A`]
                 ESUBSET_ANTISYM) THEN
    ASM_REWRITE_TAC[esubset] THEN ASM_MESON_TAC[th]) THEN
  X_GEN_TAC `w:A` THEN DISCH_TAC THEN
  USE_THEN "eM2" (fun th -> MP_TAC(MATCH_MP th (ASSUME `(w:A) IN D`))) THEN
  USE_THEN "eM" (fun th -> MP_TAC(MATCH_MP th (ASSUME `(w:A) IN D`))) THEN
  USE_THEN "eqv" (fun th -> MP_TAC(MATCH_MP th (ASSUME `(w:A) IN D`))) THEN
  CONV_TAC TAUT);;

(* SYMEQ lem spec: uses one of EMAX3/EMED3/EMIN3_SYM to prove an equality of *)
(* two same-multiset sort-values (the pointwise hyp is a permutation TAUT),  *)
(* leaving the equality (M = M2, with M the LEFT arg of the spec) in ASM.    *)
let SYMEQ lem spec =
  MP_TAC(ISPECL spec lem) THEN ANTS_TAC THENL
   [ASM_REWRITE_TAC[] THEN GEN_TAC THEN DISCH_TAC THEN CONV_TAC TAUT;
    ALL_TAC] THEN
  DISCH_TAC;;

(* Reduced triple in RG name-order (rb,ra,rr); drop rc -> rr (E rr rc).      *)
let LEXDROP_C1 = prove
 (`!D (E:A->A->bool) ra rb rc rr d1 d2 d3 M' Dp m'.
      model D E ZF_AX /\
      eordinal D E ra /\ eordinal D E rb /\ eordinal D E rc /\
        eordinal D E rr /\
      E rr rc /\
      emax3 D E ra rb rc d1 /\ emed3 D E ra rb rc d2 /\
        emin3 D E ra rb rc d3 /\
      emax3 D E rb ra rr M' /\ emed3 D E rb ra rr Dp /\ emin3 D E rb ra rr m'
      ==> E M' d1 \/ M' = d1 /\ E Dp d2 \/ M' = d1 /\ Dp = d2 /\ E m' d3`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `(ra:A) IN D /\ (rb:A) IN D /\ (rc:A) IN D /\ (rr:A) IN D`
  STRIP_ASSUME_TAC THENL [ASM_MESON_TAC[EORDINAL_IN]; ALL_TAC] THEN
  (* MULTISET_DEC-order values: least (rc,rb,ra), reduced (rr,rb,ra) *)
  SUBGOAL_THEN `?ML:A. emax3 D E rc rb ra ML` (X_CHOOSE_TAC `ML:A`) THENL
   [ASM_MESON_TAC[EMAX3_EXISTS]; ALL_TAC] THEN
  SUBGOAL_THEN `?dL:A. emed3 D E rc rb ra dL` (X_CHOOSE_TAC `dL:A`) THENL
   [ASM_MESON_TAC[EMED3_EXISTS]; ALL_TAC] THEN
  SUBGOAL_THEN `?mL:A. emin3 D E rc rb ra mL` (X_CHOOSE_TAC `mL:A`) THENL
   [ASM_MESON_TAC[EMIN3_EXISTS]; ALL_TAC] THEN
  SUBGOAL_THEN `?MR:A. emax3 D E rr rb ra MR` (X_CHOOSE_TAC `MR:A`) THENL
   [ASM_MESON_TAC[EMAX3_EXISTS]; ALL_TAC] THEN
  SUBGOAL_THEN `?dR:A. emed3 D E rr rb ra dR` (X_CHOOSE_TAC `dR:A`) THENL
   [ASM_MESON_TAC[EMED3_EXISTS]; ALL_TAC] THEN
  SUBGOAL_THEN `?mR:A. emin3 D E rr rb ra mR` (X_CHOOSE_TAC `mR:A`) THENL
   [ASM_MESON_TAC[EMIN3_EXISTS]; ALL_TAC] THEN
  (* identify: d1=ML, d2=dL, d3=mL, M'=MR, Dp=dR, m'=mR *)
  SYMEQ EMAX3_SYM
    [`D:A->bool`;`E:A->A->bool`;`ra:A`;`rb:A`;`rc:A`;`rc:A`;`rb:A`;`ra:A`;
     `d1:A`;`ML:A`] THEN
  SYMEQ EMED3_SYM
    [`D:A->bool`;`E:A->A->bool`;`ra:A`;`rb:A`;`rc:A`;`rc:A`;`rb:A`;`ra:A`;
     `d2:A`;`dL:A`] THEN
  SYMEQ EMIN3_SYM
    [`D:A->bool`;`E:A->A->bool`;`ra:A`;`rb:A`;`rc:A`;`rc:A`;`rb:A`;`ra:A`;
     `d3:A`;`mL:A`] THEN
  SYMEQ EMAX3_SYM
    [`D:A->bool`;`E:A->A->bool`;`rb:A`;`ra:A`;`rr:A`;`rr:A`;`rb:A`;`ra:A`;
     `M':A`;`MR:A`] THEN
  SYMEQ EMED3_SYM
    [`D:A->bool`;`E:A->A->bool`;`rb:A`;`ra:A`;`rr:A`;`rr:A`;`rb:A`;`ra:A`;
     `Dp:A`;`dR:A`] THEN
  SYMEQ EMIN3_SYM
    [`D:A->bool`;`E:A->A->bool`;`rb:A`;`ra:A`;`rr:A`;`rr:A`;`rb:A`;`ra:A`;
     `m':A`;`mR:A`] THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`rc:A`;`rr:A`;`rb:A`;`ra:A`;
                 `ML:A`;`dL:A`;`mL:A`;`MR:A`;`dR:A`;`mR:A`] MULTISET_DEC) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_TAC] THEN
  ASM_REWRITE_TAC[]);;

(* Reduced triple in RG name-order (ry,rc,rb); drop ra -> ry (E ry ra).      *)
(* Reduced side already in MULTISET_DEC order (a'=ry,b=rc,c=rb): no reduced  *)
(* SYM.                                                                      *)
let LEXDROP_C2 = prove
 (`!D (E:A->A->bool) ra rb rc ry d1 d2 d3 M' Dp m'.
      model D E ZF_AX /\
      eordinal D E ra /\ eordinal D E rb /\ eordinal D E rc /\
        eordinal D E ry /\
      E ry ra /\
      emax3 D E ra rb rc d1 /\ emed3 D E ra rb rc d2 /\
        emin3 D E ra rb rc d3 /\
      emax3 D E ry rc rb M' /\ emed3 D E ry rc rb Dp /\ emin3 D E ry rc rb m'
      ==> E M' d1 \/ M' = d1 /\ E Dp d2 \/ M' = d1 /\ Dp = d2 /\ E m' d3`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `(ra:A) IN D /\ (rb:A) IN D /\ (rc:A) IN D /\ (ry:A) IN D`
  STRIP_ASSUME_TAC THENL [ASM_MESON_TAC[EORDINAL_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `?ML:A. emax3 D E ra rc rb ML` (X_CHOOSE_TAC `ML:A`) THENL
   [ASM_MESON_TAC[EMAX3_EXISTS]; ALL_TAC] THEN
  SUBGOAL_THEN `?dL:A. emed3 D E ra rc rb dL` (X_CHOOSE_TAC `dL:A`) THENL
   [ASM_MESON_TAC[EMED3_EXISTS]; ALL_TAC] THEN
  SUBGOAL_THEN `?mL:A. emin3 D E ra rc rb mL` (X_CHOOSE_TAC `mL:A`) THENL
   [ASM_MESON_TAC[EMIN3_EXISTS]; ALL_TAC] THEN
  SYMEQ EMAX3_SYM
    [`D:A->bool`;`E:A->A->bool`;`ra:A`;`rb:A`;`rc:A`;`ra:A`;`rc:A`;`rb:A`;
     `d1:A`;`ML:A`] THEN
  SYMEQ EMED3_SYM
    [`D:A->bool`;`E:A->A->bool`;`ra:A`;`rb:A`;`rc:A`;`ra:A`;`rc:A`;`rb:A`;
     `d2:A`;`dL:A`] THEN
  SYMEQ EMIN3_SYM
    [`D:A->bool`;`E:A->A->bool`;`ra:A`;`rb:A`;`rc:A`;`ra:A`;`rc:A`;`rb:A`;
     `d3:A`;`mL:A`] THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`ra:A`;`ry:A`;`rc:A`;`rb:A`;
                 `ML:A`;`dL:A`;`mL:A`;`M':A`;`Dp:A`;`m':A`] MULTISET_DEC) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_TAC] THEN
  ASM_REWRITE_TAC[]);;

(* Reduced triple in RG name-order (rb,rc,rx); drop ra -> rx (E rx ra).      *)
(* Least side already in MULTISET_DEC order (a=ra,b=rb,c=rc): no least SYM.  *)
let LEXDROP_C3U = prove
 (`!D (E:A->A->bool) ra rb rc rx d1 d2 d3 M' Dp m'.
      model D E ZF_AX /\
      eordinal D E ra /\ eordinal D E rb /\ eordinal D E rc /\
        eordinal D E rx /\
      E rx ra /\
      emax3 D E ra rb rc d1 /\ emed3 D E ra rb rc d2 /\
        emin3 D E ra rb rc d3 /\
      emax3 D E rb rc rx M' /\ emed3 D E rb rc rx Dp /\ emin3 D E rb rc rx m'
      ==> E M' d1 \/ M' = d1 /\ E Dp d2 \/ M' = d1 /\ Dp = d2 /\ E m' d3`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `(ra:A) IN D /\ (rb:A) IN D /\ (rc:A) IN D /\ (rx:A) IN D`
  STRIP_ASSUME_TAC THENL [ASM_MESON_TAC[EORDINAL_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `?MR:A. emax3 D E rx rb rc MR` (X_CHOOSE_TAC `MR:A`) THENL
   [ASM_MESON_TAC[EMAX3_EXISTS]; ALL_TAC] THEN
  SUBGOAL_THEN `?dR:A. emed3 D E rx rb rc dR` (X_CHOOSE_TAC `dR:A`) THENL
   [ASM_MESON_TAC[EMED3_EXISTS]; ALL_TAC] THEN
  SUBGOAL_THEN `?mR:A. emin3 D E rx rb rc mR` (X_CHOOSE_TAC `mR:A`) THENL
   [ASM_MESON_TAC[EMIN3_EXISTS]; ALL_TAC] THEN
  SYMEQ EMAX3_SYM
    [`D:A->bool`;`E:A->A->bool`;`rb:A`;`rc:A`;`rx:A`;`rx:A`;`rb:A`;`rc:A`;
     `M':A`;`MR:A`] THEN
  SYMEQ EMED3_SYM
    [`D:A->bool`;`E:A->A->bool`;`rb:A`;`rc:A`;`rx:A`;`rx:A`;`rb:A`;`rc:A`;
     `Dp:A`;`dR:A`] THEN
  SYMEQ EMIN3_SYM
    [`D:A->bool`;`E:A->A->bool`;`rb:A`;`rc:A`;`rx:A`;`rx:A`;`rb:A`;`rc:A`;
     `m':A`;`mR:A`] THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`ra:A`;`rx:A`;`rb:A`;`rc:A`;
                 `d1:A`;`d2:A`;`d3:A`;`MR:A`;`dR:A`;`mR:A`] MULTISET_DEC) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_TAC] THEN
  ASM_REWRITE_TAC[]);;

(* ~ccfl gives the three congruence inequalities, each as "the imp-value is  *)
(* top" (De Morgan on the ccfl disjunction).  Consumed via EBIMP_TOP.        *)
let NOT_CCFL = prove
 (`!D (E:A->A->bool) B leq u v w.
      ~ccfl D E B leq u v w
      ==> (!z20 z21 z22 z23 z24.
              z20 IN D /\ z21 IN D /\ z22 IN D /\ z23 IN D /\ z24 IN D /\
              ebv_eq D E B leq u v z20 /\ ebv_in D E B leq u w z21 /\
              ebv_in D E B leq v w z22 /\ emeet D E B leq z20 z21 z23 /\
              ebimp D E B leq z23 z22 z24 ==> etop D E B leq z24) /\
           (!z20 z21 z22 z23 z24.
              z20 IN D /\ z21 IN D /\ z22 IN D /\ z23 IN D /\ z24 IN D /\
              ebv_eq D E B leq u v z20 /\ ebv_in D E B leq w u z21 /\
              ebv_in D E B leq w v z22 /\ emeet D E B leq z20 z21 z23 /\
              ebimp D E B leq z23 z22 z24 ==> etop D E B leq z24) /\
           (!z20 z21 z22 z23 z24.
              z20 IN D /\ z21 IN D /\ z22 IN D /\ z23 IN D /\ z24 IN D /\
              ebv_eq D E B leq u v z20 /\ ebv_eq D E B leq v w z21 /\
              ebv_eq D E B leq u w z22 /\ emeet D E B leq z20 z21 z23 /\
              ebimp D E B leq z23 z22 z24 ==> etop D E B leq z24)`,
  REWRITE_TAC[ccfl; DE_MORGAN_THM; NOT_EXISTS_THM] THEN MESON_TAC[]);;

let C1_STEP2 = prove
 (`!D (E:A->A->bool) B leq a w sIN sEQ aa bb ww zeq zin zin2.
      model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
      a IN D /\ eordinal D E a /\ ebnstage D E B a w /\ w IN D /\
      aa IN D /\ bb IN D /\ ww IN D /\ E aa w /\ E bb w /\ E ww w /\
      ebvatt D E B leq w sIN sEQ /\
      ebveq D E B leq sIN aa bb zeq /\
      ebvin D E B leq sEQ ww aa zin /\
      ebvin D E B leq sEQ ww bb zin2 /\
      (!r qr ar br mza.
          r IN D /\ eapply D E ww r qr /\
          ebv_eq D E B leq aa r ar /\ ebv_eq D E B leq bb r br /\
          emeet D E B leq zeq ar mza /\ br IN D
          ==> erel D E leq mza br)
      ==> !m. m IN D /\ emeet D E B leq zeq zin m ==> erel D E leq m zin2`,
  REPEAT GEN_TAC THEN REPEAT STRIP_TAC THEN
  FIRST_X_ASSUM(fun th -> if is_forall(concl th) then LABEL_TAC "ih" th else
                failwith "no") THEN
  SUBGOAL_THEN `ebalg D (E:A->A->bool) B leq` ASSUME_TAC THENL
   [ASM_MESON_TAC[ECBA_IMP_BALG]; ALL_TAC] THEN
  SUBGOAL_THEN `eporder D (E:A->A->bool) B leq` ASSUME_TAC THENL
   [ASM_MESON_TAC[EBALG_IMP_PORDER]; ALL_TAC] THEN
  SUBGOAL_THEN `bname D (E:A->A->bool) B bb` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`a:A`;`w:A`;`bb:A`]
                 BNAME_STAGE) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `bname D (E:A->A->bool) B ww` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`a:A`;`w:A`;`ww:A`]
                 BNAME_STAGE) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(zeq:A) IN D /\ (E:A->A->bool) zeq B` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[EBVEQ_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `(zin:A) IN D /\ (E:A->A->bool) zin B` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[EBVIN_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `(zin2:A) IN D /\ (E:A->A->bool) zin2 B` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[EBVIN_IN]; ALL_TAC] THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`zeq:A`;`zin2:A`]
         EBIMP_EXISTS) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `w0:A`) THEN
  SUBGOAL_THEN `(w0:A) IN D /\ (E:A->A->bool) w0 B` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[EBIMP_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq zin w0` ASSUME_TAC THENL
   [MP_TAC(ISPECL
           [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`a:A`;`w:A`;
            `sIN:A`;`sEQ:A`;
            `aa:A`;`ww:A`;`zin:A`;`w0:A`] EBV_IN_LE) THEN
    ASM_REWRITE_TAC[] THEN DISCH_THEN MATCH_MP_TAC THEN
    MAP_EVERY X_GEN_TAC [`r:A`;`qr:A`;`ar:A`;`c:A`] THEN STRIP_TAC THEN
    SUBGOAL_THEN `(E:A->A->bool) r w` ASSUME_TAC THENL
     [MATCH_MP_TAC(ISPECL
                   [`D:A->bool`;`E:A->A->bool`;`B:A`;`a:A`;`w:A`;`ww:A`;
                    `r:A`;`qr:A`]
                   STAGE_DOM_CLOSED) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    (* br = [[bb = r]] via table *)
    MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`bb:A`;`r:A`] EOPAIR_EXISTS) THEN
    ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `pr:A`) THEN
    SUBGOAL_THEN `(pr:A) IN D` ASSUME_TAC THENL
     [ASM_MESON_TAC[EOPAIR_IN]; ALL_TAC] THEN
    MP_TAC(ISPECL
           [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`w:A`;`sIN:A`;`sEQ:A`;
            `bb:A`;`r:A`;`pr:A`] EBVATT_VAL) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(CONJUNCTS_THEN2 (K ALL_TAC)
               (X_CHOOSE_THEN `br:A` STRIP_ASSUME_TAC)) THEN
    SUBGOAL_THEN `ebv_eq D (E:A->A->bool) B leq bb r br` ASSUME_TAC THENL
     [MATCH_MP_TAC(ISPECL
                   [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`a:A`;
                    `w:A`;`sIN:A`;
                    `sEQ:A`;`bb:A`;`r:A`;`br:A`] EBV_EQ_AT_STAGE) THEN
               ASM_REWRITE_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN `(E:A->A->bool) br B` ASSUME_TAC THENL
     [MP_TAC(ISPECL
             [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`bb:A`;`r:A`;`br:A`]
             EBV_EQ_IN_B) THEN
      ASM_REWRITE_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN `(E:A->A->bool) qr B` ASSUME_TAC THENL
     [MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`ww:A`;`r:A`;`qr:A`]
             BNAME_APPLY_IN_B) THEN
      ASM_REWRITE_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN `(E:A->A->bool) ar B` ASSUME_TAC THENL
     [MP_TAC(ISPECL
             [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`aa:A`;`r:A`;`ar:A`]
             EBV_EQ_IN_B) THEN
      ASM_REWRITE_TAC[]; ALL_TAC] THEN
    (* mza = zeq MEET ar ; C3-instance mza <= br *)
    MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`zeq:A`;`ar:A`]
           EBALG_MEET) THEN
    ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `mza:A`) THEN
    SUBGOAL_THEN `erel D (E:A->A->bool) leq mza br` ASSUME_TAC THENL
     [USE_THEN "ih"
      (fun th ->
       MATCH_MP_TAC(ISPECL [`r:A`;`qr:A`;`ar:A`;`br:A`;`mza:A`] th)) THEN
      ASM_REWRITE_TAC[]; ALL_TAC] THEN
    (* mgb = qr MEET br ; EBV_IN_GE_TERM : mgb <= zin2 *)
    MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`qr:A`;`br:A`]
           EBALG_MEET) THEN
    ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `mgb:A`) THEN
    SUBGOAL_THEN `(mgb:A) IN D /\ (E:A->A->bool) mgb B` STRIP_ASSUME_TAC THENL
     [ASM_MESON_TAC[EMEET_IN]; ALL_TAC] THEN
    SUBGOAL_THEN `erel D (E:A->A->bool) leq mgb zin2` ASSUME_TAC THENL
     [MP_TAC(ISPECL
             [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`a:A`;`w:A`;
              `sIN:A`;`sEQ:A`;
              `bb:A`;`ww:A`;`zin2:A`;`r:A`;`qr:A`;`br:A`;`mgb:A`]
               EBV_IN_GE_TERM) THEN
      ASM_REWRITE_TAC[]; ALL_TAC] THEN
    (* apply C1_TERM *)
    MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`qr:A`;
                  `ar:A`;`br:A`;
                  `zeq:A`;`zin2:A`;`w0:A`;`c:A`;`mza:A`;`mgb:A`] C1_TERM) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `emeet D (E:A->A->bool) B leq zin zeq m` ASSUME_TAC THENL
   [MATCH_MP_TAC EMEET_SYM THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MATCH_MP_TAC(ISPECL
               [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`zin:A`;
                `zeq:A`;`zin2:A`;
                `w0:A`;`m:A`] EBIMP_MEET_LE) THEN ASM_REWRITE_TAC[]);;

let C3_STEP2 = prove
 (`!D (E:A->A->bool) B leq a w sIN sEQ uu vv ww zeq1 zeq2 zuw.
      model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
      a IN D /\ eordinal D E a /\ ebnstage D E B a w /\ w IN D /\
      uu IN D /\ vv IN D /\ ww IN D /\ E uu w /\ E vv w /\ E ww w /\
      ebvatt D E B leq w sIN sEQ /\
      ebveq D E B leq sIN uu vv zeq1 /\
      ebveq D E B leq sIN vv ww zeq2 /\
      ebveq D E B leq sIN uu ww zuw /\
      (!x qx pv pw mpv2.
          x IN D /\ eapply D E uu x qx /\ ebv_in D E B leq x vv pv /\
          ebv_in D E B leq x ww pw /\ emeet D E B leq pv zeq2 mpv2 /\ pw IN D
          ==> erel D E leq mpv2 pw) /\
      (!y qy pv pu mpv1.
          y IN D /\ eapply D E ww y qy /\ ebv_in D E B leq y vv pv /\
          ebv_in D E B leq y uu pu /\ emeet D E B leq pv zeq1 mpv1 /\ pu IN D
          ==> erel D E leq mpv1 pu)
      ==> !m. m IN D /\ emeet D E B leq zeq1 zeq2 m ==> erel D E leq m zuw`,
  REPEAT GEN_TAC THEN DISCH_THEN(fun th ->
    let cs = CONJUNCTS th in
    MAP_EVERY ASSUME_TAC (butlast(butlast cs)) THEN
    LABEL_TAC "ihu" (el (length cs - 2) cs) THEN
    LABEL_TAC "ihw" (last cs)) THEN
  GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `ebalg D (E:A->A->bool) B leq` ASSUME_TAC THENL
   [ASM_MESON_TAC[ECBA_IMP_BALG]; ALL_TAC] THEN
  SUBGOAL_THEN `eporder D (E:A->A->bool) B leq` ASSUME_TAC THENL
   [ASM_MESON_TAC[EBALG_IMP_PORDER]; ALL_TAC] THEN
  SUBGOAL_THEN `bname D (E:A->A->bool) B uu /\ bname D E B ww`
    STRIP_ASSUME_TAC THENL
   [CONJ_TAC THENL
     [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`a:A`;`w:A`;`uu:A`]
                   BNAME_STAGE);
      MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`a:A`;`w:A`;`ww:A`]
                   BNAME_STAGE)] THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(zeq1:A) IN D /\ (E:A->A->bool) zeq1 B` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[EBVEQ_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `(zeq2:A) IN D /\ (E:A->A->bool) zeq2 B` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[EBVEQ_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `(zuw:A) IN D /\ (E:A->A->bool) zuw B` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[EBVEQ_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `(m:A) IN D /\ (E:A->A->bool) m B` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[EMEET_IN]; ALL_TAC] THEN
  MP_TAC(ISPECL
         [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`a:A`;`w:A`;`sIN:A`;`sEQ:A`;
          `uu:A`;`ww:A`;`zuw:A`;`m:A`] EBV_EQ_GLB_STAGE) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
     [ (* u-side: m <= (uu(x) => [[x in ww]]) *)
      MAP_EVERY X_GEN_TAC [`x:A`;`qx:A`;`exv:A`;`c:A`] THEN STRIP_TAC THEN
      SUBGOAL_THEN `(E:A->A->bool) x w` ASSUME_TAC THENL
       [MATCH_MP_TAC(ISPECL
                     [`D:A->bool`;`E:A->A->bool`;`B:A`;`a:A`;`w:A`;`uu:A`;
                      `x:A`;`qx:A`]
                     STAGE_DOM_CLOSED) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
      MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`x:A`;`vv:A`]
             EOPAIR_EXISTS) THEN
      ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `pr:A`) THEN
      SUBGOAL_THEN `(pr:A) IN D` ASSUME_TAC THENL
      [ASM_MESON_TAC[EOPAIR_IN]; ALL_TAC] THEN
      MP_TAC(ISPECL
             [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`w:A`;`sIN:A`;`sEQ:A`;
              `x:A`;`vv:A`;`pr:A`] EBVATT_VAL) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(CONJUNCTS_THEN2 (X_CHOOSE_THEN `pv:A` STRIP_ASSUME_TAC)
                 (K ALL_TAC)) THEN
      SUBGOAL_THEN `ebv_in D (E:A->A->bool) B leq x vv pv` ASSUME_TAC THENL
       [MATCH_MP_TAC(ISPECL
                     [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`a:A`;
                      `w:A`;`sIN:A`;
                      `sEQ:A`;`x:A`;`vv:A`;`pv:A`] EBV_IN_AT_STAGE) THEN
                 ASM_REWRITE_TAC[]; ALL_TAC] THEN
      SUBGOAL_THEN `(pv:A) IN D /\ (E:A->A->bool) pv B` STRIP_ASSUME_TAC THENL
       [ASM_MESON_TAC[EBVIN_IN]; ALL_TAC] THEN
      SUBGOAL_THEN `(E:A->A->bool) qx B` ASSUME_TAC THENL
       [MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`uu:A`;`x:A`;`qx:A`]
               BNAME_APPLY_IN_B) THEN
        ASM_REWRITE_TAC[]; ALL_TAC] THEN
      SUBGOAL_THEN `(E:A->A->bool) exv B` ASSUME_TAC THENL
       [MP_TAC(ISPECL
               [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`x:A`;`ww:A`;`exv:A`]
               EBV_IN_IN_B) THEN
        ASM_REWRITE_TAC[]; ALL_TAC] THEN
      MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`qx:A`;`pv:A`]
             EBIMP_EXISTS) THEN
      ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `cpr:A`) THEN
      SUBGOAL_THEN `bveqcomb D (E:A->A->bool) B leq sIN uu vv cpr`
        ASSUME_TAC THENL
        [REWRITE_TAC[bveqcomb] THEN
        MAP_EVERY EXISTS_TAC [`x:A`;`qx:A`;`pv:A`;`pr:A`] THEN
        ASM_REWRITE_TAC[]; ALL_TAC] THEN
      SUBGOAL_THEN `erel D (E:A->A->bool) leq zeq1 cpr` ASSUME_TAC THENL
       [MP_TAC(ISPECL
               [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`sIN:A`;`uu:A`;
                `vv:A`;`zeq1:A`;
                `cpr:A`] EBVEQ_LB) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
      MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`pv:A`;`zeq2:A`]
             EBALG_MEET) THEN
      ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `mpv2:A`) THEN
      SUBGOAL_THEN `erel D (E:A->A->bool) leq mpv2 exv` ASSUME_TAC THENL
       [USE_THEN "ihu"
        (fun th ->
         MATCH_MP_TAC(ISPECL [`x:A`;`qx:A`;`pv:A`;`exv:A`;`mpv2:A`] th)) THEN
        ASM_REWRITE_TAC[]; ALL_TAC] THEN
      MATCH_MP_TAC(ISPECL
                   [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`qx:A`;
                    `pv:A`;`exv:A`;
                    `zeq1:A`;`zeq2:A`;`m:A`;`cpr:A`;`c:A`;`mpv2:A`]
                     C3_TERM) THEN ASM_REWRITE_TAC[];
      (* w-side: m <= (ww(y) => [[y in uu]]) *)
      MAP_EVERY X_GEN_TAC [`y:A`;`qy:A`;`eyu:A`;`c:A`] THEN STRIP_TAC THEN
      SUBGOAL_THEN `(E:A->A->bool) y w` ASSUME_TAC THENL
       [MATCH_MP_TAC(ISPECL
                     [`D:A->bool`;`E:A->A->bool`;`B:A`;`a:A`;`w:A`;`ww:A`;
                      `y:A`;`qy:A`]
                     STAGE_DOM_CLOSED) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
      MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`y:A`;`vv:A`]
             EOPAIR_EXISTS) THEN
      ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `pr:A`) THEN
      SUBGOAL_THEN `(pr:A) IN D` ASSUME_TAC THENL
      [ASM_MESON_TAC[EOPAIR_IN]; ALL_TAC] THEN
      MP_TAC(ISPECL
             [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`w:A`;`sIN:A`;`sEQ:A`;
              `y:A`;`vv:A`;`pr:A`] EBVATT_VAL) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(CONJUNCTS_THEN2 (X_CHOOSE_THEN `pv:A` STRIP_ASSUME_TAC)
                 (K ALL_TAC)) THEN
      SUBGOAL_THEN `ebv_in D (E:A->A->bool) B leq y vv pv` ASSUME_TAC THENL
       [MATCH_MP_TAC(ISPECL
                     [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`a:A`;
                      `w:A`;`sIN:A`;
                      `sEQ:A`;`y:A`;`vv:A`;`pv:A`] EBV_IN_AT_STAGE) THEN
                 ASM_REWRITE_TAC[]; ALL_TAC] THEN
      SUBGOAL_THEN `(pv:A) IN D /\ (E:A->A->bool) pv B` STRIP_ASSUME_TAC THENL
       [ASM_MESON_TAC[EBVIN_IN]; ALL_TAC] THEN
      SUBGOAL_THEN `(E:A->A->bool) qy B` ASSUME_TAC THENL
       [MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`ww:A`;`y:A`;`qy:A`]
               BNAME_APPLY_IN_B) THEN
        ASM_REWRITE_TAC[]; ALL_TAC] THEN
      SUBGOAL_THEN `(E:A->A->bool) eyu B` ASSUME_TAC THENL
       [MP_TAC(ISPECL
               [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`y:A`;`uu:A`;`eyu:A`]
               EBV_IN_IN_B) THEN
        ASM_REWRITE_TAC[]; ALL_TAC] THEN
      MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`qy:A`;`pv:A`]
             EBIMP_EXISTS) THEN
      ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `cpr:A`) THEN
      SUBGOAL_THEN `bveqcomb D (E:A->A->bool) B leq sIN ww vv cpr`
        ASSUME_TAC THENL
        [REWRITE_TAC[bveqcomb] THEN
        MAP_EVERY EXISTS_TAC [`y:A`;`qy:A`;`pv:A`;`pr:A`] THEN
        ASM_REWRITE_TAC[]; ALL_TAC] THEN
      SUBGOAL_THEN `erel D (E:A->A->bool) leq zeq2 cpr` ASSUME_TAC THENL
       [MP_TAC(ISPECL
               [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`sIN:A`;`vv:A`;
                `ww:A`;`zeq2:A`;
                `cpr:A`] EBVEQ_LB_R) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
      SUBGOAL_THEN `emeet D (E:A->A->bool) B leq zeq2 zeq1 m` ASSUME_TAC THENL
       [MATCH_MP_TAC EMEET_SYM THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
      MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`pv:A`;`zeq1:A`]
             EBALG_MEET) THEN
      ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `mpv1:A`) THEN
      SUBGOAL_THEN `erel D (E:A->A->bool) leq mpv1 eyu` ASSUME_TAC THENL
       [USE_THEN "ihw"
        (fun th ->
         MATCH_MP_TAC(ISPECL [`y:A`;`qy:A`;`pv:A`;`eyu:A`;`mpv1:A`] th)) THEN
        ASM_REWRITE_TAC[]; ALL_TAC] THEN
      MATCH_MP_TAC(ISPECL
                   [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`qy:A`;
                    `pv:A`;`eyu:A`;
                    `zeq2:A`;`zeq1:A`;`m:A`;`cpr:A`;`c:A`;`mpv1:A`]
                     C3_TERM) THEN ASM_REWRITE_TAC[]];
    DISCH_THEN ACCEPT_TAC]);;

(* Discharge C1_STEP2's IH: for r in dom(w), [[u=v]] MEET [[u=r]] <=         *)
(* [[v=r]]. This is C3 (transitivity) at the reduced triple (v,u,r), whose   *)
(* sorted rank triple lex-drops below (d1,d2,d3) because rank(r) <           *)
(* rank(w)=rc.  Hence ~ccfl(v,u,r) by REDUCED_GOOD, and NOT_CCFL conj3 gives *)
(* the inequality.                                                           *)
let IHD_C1 = prove
 (`!D (E:A->A->bool) B leq d1 d2 d3 u v w ra rb rc zeq.
      model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
      (!c. c IN D /\ E c d1 ==> ~badmax D E B leq c) /\
      (!c. c IN D /\ E c d2 ==> ~badmed D E B leq d1 c) /\
      (!c. c IN D /\ E c d3 ==> ~badmin D E B leq d1 d2 c) /\
      u IN D /\ v IN D /\ w IN D /\
      bname D E B u /\ bname D E B v /\ bname D E B w /\
      ra IN D /\ rb IN D /\ rc IN D /\
      eordinal D E ra /\ eordinal D E rb /\ eordinal D E rc /\
      ebnrank D E B u ra /\ ebnrank D E B v rb /\ ebnrank D E B w rc /\
      emax3 D E ra rb rc d1 /\ emed3 D E ra rb rc d2 /\
        emin3 D E ra rb rc d3 /\
      zeq IN D /\ ebv_eq D E B leq u v zeq
      ==> !r qr ar br mza.
            r IN D /\ eapply D E w r qr /\
            ebv_eq D E B leq u r ar /\ ebv_eq D E B leq v r br /\
            emeet D E B leq zeq ar mza /\ br IN D
            ==> erel D E leq mza br`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`d1:A`;`d2:A`;`d3:A`]
    REDUCED_GOOD) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(LABEL_TAC "RG") THEN
  SUBGOAL_THEN `ebalg D (E:A->A->bool) B leq` ASSUME_TAC THENL
   [ASM_MESON_TAC[ECBA_IMP_BALG]; ALL_TAC] THEN
  SUBGOAL_THEN `eporder D (E:A->A->bool) B leq` ASSUME_TAC THENL
   [ASM_MESON_TAC[EBALG_IMP_PORDER]; ALL_TAC] THEN
  SUBGOAL_THEN `ebv_eq D (E:A->A->bool) B leq v u zeq` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`u:A`;`v:A`;`zeq:A`]
                 EBV_EQ_SYM) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MAP_EVERY X_GEN_TAC [`r:A`;`qr:A`;`ar:A`;`br:A`;`mza:A`] THEN STRIP_TAC THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq mza ar` ASSUME_TAC THENL
   [ASM_MESON_TAC[EMEET_LE]; ALL_TAC] THEN
  SUBGOAL_THEN `(mza:A) IN D /\ (ar:A) IN D /\ (E:A->A->bool) mza B /\ E ar B`
  STRIP_ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`mza:A`;`ar:A`]
                 EPORDER_FIELD) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) br B` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`v:A`;`r:A`;`br:A`]
                 EBV_EQ_IN_B) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* canonical value + rank of r *)
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`w:A`;`r:A`;`qr:A`]
         EAPPLY_DVAL) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_THEN `q0:A` STRIP_ASSUME_TAC) THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`w:A`;`r:A`;`q0:A`;`rc:A`]
    EBNRANK_APPLY_LT) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC
             (X_CHOOSE_THEN `rr:A` STRIP_ASSUME_TAC)) THEN
  SUBGOAL_THEN `(rr:A) IN D /\ eordinal D (E:A->A->bool) rr`
    STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[EBNRANK_IN; EBNRANK_ORDINAL]; ALL_TAC] THEN
  SUBGOAL_THEN `?M':A. emax3 D E rb ra rr M'` (X_CHOOSE_TAC `M':A`) THENL
   [ASM_MESON_TAC[EMAX3_EXISTS]; ALL_TAC] THEN
  SUBGOAL_THEN `?Dp:A. emed3 D E rb ra rr Dp` (X_CHOOSE_TAC `Dp:A`) THENL
   [ASM_MESON_TAC[EMED3_EXISTS]; ALL_TAC] THEN
  SUBGOAL_THEN `?m2:A. emin3 D E rb ra rr m2` (X_CHOOSE_TAC `m2:A`) THENL
   [ASM_MESON_TAC[EMIN3_EXISTS]; ALL_TAC] THEN
  SUBGOAL_THEN `(M':A) IN D /\ (Dp:A) IN D /\ (m2:A) IN D`
    STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[EMAX3_ORDINAL; EMED3_ORDINAL; EMIN3_ORDINAL; EORDINAL_IN];
    ALL_TAC] THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`ra:A`;`rb:A`;`rc:A`;`rr:A`;
                 `d1:A`;`d2:A`;`d3:A`;`M':A`;`Dp:A`;`m2:A`] LEXDROP_C1) THEN
  ASM_REWRITE_TAC[] THEN DISCH_TAC THEN
  SUBGOAL_THEN `~ccfl D (E:A->A->bool) B leq v u r` ASSUME_TAC THENL
   [USE_THEN "RG" (fun th -> MATCH_MP_TAC(ISPECL
      [`v:A`;`u:A`;`r:A`;`rb:A`;`ra:A`;`rr:A`;`M':A`;`Dp:A`;`m2:A`] th)) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`v:A`;`u:A`;`r:A`]
    NOT_CCFL) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(LABEL_TAC "nc" o CONJUNCT2 o CONJUNCT2) THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`mza:A`;`br:A`]
         EBIMP_EXISTS) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `cc:A`) THEN
  SUBGOAL_THEN `(cc:A) IN D /\ (E:A->A->bool) cc B` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[EBIMP_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `etop D (E:A->A->bool) B leq cc` ASSUME_TAC THENL
   [USE_THEN "nc" (fun th -> MATCH_MP_TAC(ISPECL
      [`zeq:A`;`ar:A`;`br:A`;`mza:A`;`cc:A`] th)) THEN ASM_REWRITE_TAC[];
         ALL_TAC] THEN
  MP_TAC(ISPECL
         [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`mza:A`;`br:A`;`cc:A`]
         EBIMP_TOP) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(fun th -> ASM_MESON_TAC[th]));;

(* ------------------------------------------------------------------ *)
(* IHD_C2 : discharge C2_STEP's IH.  For y in dom(u),                  *)
(*   [[w=y]] MEET [[y in v]] <= [[w in v]] = zin2.                     *)
(* This is C1 (element-cong) at reduced triple (y,w,v): rank(y)<ra so  *)
(* the sorted rank-triple lex-drops (LEXDROP_C2), giving ~ccfl y w v.  *)
(* NOT_CCFL conj1 then yields the inequality.                          *)
(* ------------------------------------------------------------------ *)
let IHD_C2 = prove
 (`!D (E:A->A->bool) B leq d1 d2 d3 u v w ra rb rc zin2.
      model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
      (!c. c IN D /\ E c d1 ==> ~badmax D E B leq c) /\
      (!c. c IN D /\ E c d2 ==> ~badmed D E B leq d1 c) /\
      (!c. c IN D /\ E c d3 ==> ~badmin D E B leq d1 d2 c) /\
      u IN D /\ v IN D /\ w IN D /\
      bname D E B u /\ bname D E B v /\ bname D E B w /\
      ra IN D /\ rb IN D /\ rc IN D /\
      eordinal D E ra /\ eordinal D E rb /\ eordinal D E rc /\
      ebnrank D E B u ra /\ ebnrank D E B v rb /\ ebnrank D E B w rc /\
      emax3 D E ra rb rc d1 /\ emed3 D E ra rb rc d2 /\
        emin3 D E ra rb rc d3 /\
      zin2 IN D /\ ebv_in D E B leq w v zin2
      ==> !y qy ey tv m.
            y IN D /\ eapply D E u y qy /\
            ebv_eq D E B leq w y ey /\ ebv_in D E B leq y v tv /\
            emeet D E B leq ey tv m
            ==> erel D E leq m zin2`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`d1:A`;`d2:A`;`d3:A`]
    REDUCED_GOOD) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(LABEL_TAC "RG") THEN
  SUBGOAL_THEN `ebalg D (E:A->A->bool) B leq` ASSUME_TAC THENL
   [ASM_MESON_TAC[ECBA_IMP_BALG]; ALL_TAC] THEN
  SUBGOAL_THEN `eporder D (E:A->A->bool) B leq` ASSUME_TAC THENL
   [ASM_MESON_TAC[EBALG_IMP_PORDER]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) zin2 B` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`w:A`;
                  `v:A`;`zin2:A`]
                 EBV_IN_IN_B) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MAP_EVERY X_GEN_TAC [`y:A`;`qy:A`;`ey:A`;`tv:A`;`m:A`] THEN STRIP_TAC THEN
  SUBGOAL_THEN `(m:A) IN D /\ (ey:A) IN D /\ (tv:A) IN D /\
                (E:A->A->bool) m B /\ E ey B /\ E tv B` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[EMEET_LE; EPORDER_FIELD]; ALL_TAC] THEN
  SUBGOAL_THEN `ebv_eq D (E:A->A->bool) B leq y w ey` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`w:A`;`y:A`;`ey:A`]
                 EBV_EQ_SYM) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`u:A`;`y:A`;`qy:A`]
         EAPPLY_DVAL) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_THEN `q0:A` STRIP_ASSUME_TAC) THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`u:A`;`y:A`;`q0:A`;`ra:A`]
    EBNRANK_APPLY_LT) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC
             (X_CHOOSE_THEN `ry:A` STRIP_ASSUME_TAC)) THEN
  SUBGOAL_THEN `(ry:A) IN D /\ eordinal D (E:A->A->bool) ry`
    STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[EBNRANK_IN; EBNRANK_ORDINAL]; ALL_TAC] THEN
  SUBGOAL_THEN `?M':A. emax3 D E ry rc rb M'` (X_CHOOSE_TAC `M':A`) THENL
   [ASM_MESON_TAC[EMAX3_EXISTS]; ALL_TAC] THEN
  SUBGOAL_THEN `?Dp:A. emed3 D E ry rc rb Dp` (X_CHOOSE_TAC `Dp:A`) THENL
   [ASM_MESON_TAC[EMED3_EXISTS]; ALL_TAC] THEN
  SUBGOAL_THEN `?m2:A. emin3 D E ry rc rb m2` (X_CHOOSE_TAC `m2:A`) THENL
   [ASM_MESON_TAC[EMIN3_EXISTS]; ALL_TAC] THEN
  SUBGOAL_THEN `(M':A) IN D /\ (Dp:A) IN D /\ (m2:A) IN D`
    STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[EMAX3_ORDINAL; EMED3_ORDINAL; EMIN3_ORDINAL; EORDINAL_IN];
    ALL_TAC] THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`ra:A`;`rb:A`;`rc:A`;`ry:A`;
                 `d1:A`;`d2:A`;`d3:A`;`M':A`;`Dp:A`;`m2:A`] LEXDROP_C2) THEN
  ASM_REWRITE_TAC[] THEN DISCH_TAC THEN
  SUBGOAL_THEN `~ccfl D (E:A->A->bool) B leq y w v` ASSUME_TAC THENL
   [USE_THEN "RG" (fun th -> MATCH_MP_TAC(ISPECL
      [`y:A`;`w:A`;`v:A`;`ry:A`;`rc:A`;`rb:A`;`M':A`;`Dp:A`;`m2:A`] th)) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`y:A`;`w:A`;`v:A`]
    NOT_CCFL) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(LABEL_TAC "nc" o CONJUNCT1) THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`m:A`;`zin2:A`]
         EBIMP_EXISTS) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `cc:A`) THEN
  SUBGOAL_THEN `(cc:A) IN D /\ (E:A->A->bool) cc B` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[EBIMP_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `etop D (E:A->A->bool) B leq cc` ASSUME_TAC THENL
   [USE_THEN "nc" (fun th -> MATCH_MP_TAC(ISPECL
      [`ey:A`;`tv:A`;`zin2:A`;`m:A`;`cc:A`] th)) THEN ASM_REWRITE_TAC[];
         ALL_TAC] THEN
  MP_TAC(ISPECL
         [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`m:A`;`zin2:A`;`cc:A`]
         EBIMP_TOP) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(fun th -> ASM_MESON_TAC[th]));;

(* ------------------------------------------------------------------ *)
(* IHD_C3U : discharge C3_STEP2's ihu.  For x in dom(u),              *)
(*   [[x in v]] MEET [[v=w]] <= [[x in w]] = pw.                       *)
(* This is C2 (container-cong) at reduced triple (v,w,x): rank(x)<ra   *)
(* (LEXDROP_C3U), giving ~ccfl v w x.  NOT_CCFL conj2 yields it;       *)
(* meet order swapped via EMEET_SYM.                                   *)
(* ------------------------------------------------------------------ *)
let IHD_C3U = prove
 (`!D (E:A->A->bool) B leq d1 d2 d3 u v w ra rb rc zeq2.
      model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
      (!c. c IN D /\ E c d1 ==> ~badmax D E B leq c) /\
      (!c. c IN D /\ E c d2 ==> ~badmed D E B leq d1 c) /\
      (!c. c IN D /\ E c d3 ==> ~badmin D E B leq d1 d2 c) /\
      u IN D /\ v IN D /\ w IN D /\
      bname D E B u /\ bname D E B v /\ bname D E B w /\
      ra IN D /\ rb IN D /\ rc IN D /\
      eordinal D E ra /\ eordinal D E rb /\ eordinal D E rc /\
      ebnrank D E B u ra /\ ebnrank D E B v rb /\ ebnrank D E B w rc /\
      emax3 D E ra rb rc d1 /\ emed3 D E ra rb rc d2 /\
        emin3 D E ra rb rc d3 /\
      zeq2 IN D /\ ebv_eq D E B leq v w zeq2
      ==> !x qx pv pw mpv2.
            x IN D /\ eapply D E u x qx /\
            ebv_in D E B leq x v pv /\ ebv_in D E B leq x w pw /\
            emeet D E B leq pv zeq2 mpv2 /\ pw IN D
            ==> erel D E leq mpv2 pw`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`d1:A`;`d2:A`;`d3:A`]
    REDUCED_GOOD) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(LABEL_TAC "RG") THEN
  SUBGOAL_THEN `ebalg D (E:A->A->bool) B leq` ASSUME_TAC THENL
   [ASM_MESON_TAC[ECBA_IMP_BALG]; ALL_TAC] THEN
  SUBGOAL_THEN `eporder D (E:A->A->bool) B leq` ASSUME_TAC THENL
   [ASM_MESON_TAC[EBALG_IMP_PORDER]; ALL_TAC] THEN
  MAP_EVERY X_GEN_TAC [`x:A`;`qx:A`;`pv:A`;`pw:A`;`mpv2:A`] THEN STRIP_TAC THEN
  SUBGOAL_THEN `(mpv2:A) IN D /\ (pv:A) IN D /\
                (E:A->A->bool) mpv2 B /\ E pv B` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[EMEET_LE; EPORDER_FIELD]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) pw B` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`x:A`;`w:A`;`pw:A`]
                 EBV_IN_IN_B) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `emeet D (E:A->A->bool) B leq zeq2 pv mpv2` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`pv:A`;
                  `zeq2:A`;`mpv2:A`]
                 EMEET_SYM) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`u:A`;`x:A`;`qx:A`]
         EAPPLY_DVAL) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_THEN `q0:A` STRIP_ASSUME_TAC) THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`u:A`;`x:A`;`q0:A`;`ra:A`]
    EBNRANK_APPLY_LT) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC
             (X_CHOOSE_THEN `rx:A` STRIP_ASSUME_TAC)) THEN
  SUBGOAL_THEN `(rx:A) IN D /\ eordinal D (E:A->A->bool) rx`
    STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[EBNRANK_IN; EBNRANK_ORDINAL]; ALL_TAC] THEN
  SUBGOAL_THEN `?M':A. emax3 D E rb rc rx M'` (X_CHOOSE_TAC `M':A`) THENL
   [ASM_MESON_TAC[EMAX3_EXISTS]; ALL_TAC] THEN
  SUBGOAL_THEN `?Dp:A. emed3 D E rb rc rx Dp` (X_CHOOSE_TAC `Dp:A`) THENL
   [ASM_MESON_TAC[EMED3_EXISTS]; ALL_TAC] THEN
  SUBGOAL_THEN `?m2:A. emin3 D E rb rc rx m2` (X_CHOOSE_TAC `m2:A`) THENL
   [ASM_MESON_TAC[EMIN3_EXISTS]; ALL_TAC] THEN
  SUBGOAL_THEN `(M':A) IN D /\ (Dp:A) IN D /\ (m2:A) IN D`
    STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[EMAX3_ORDINAL; EMED3_ORDINAL; EMIN3_ORDINAL; EORDINAL_IN];
    ALL_TAC] THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`ra:A`;`rb:A`;`rc:A`;`rx:A`;
                 `d1:A`;`d2:A`;`d3:A`;`M':A`;`Dp:A`;`m2:A`] LEXDROP_C3U) THEN
  ASM_REWRITE_TAC[] THEN DISCH_TAC THEN
  SUBGOAL_THEN `~ccfl D (E:A->A->bool) B leq v w x` ASSUME_TAC THENL
   [USE_THEN "RG" (fun th -> MATCH_MP_TAC(ISPECL
      [`v:A`;`w:A`;`x:A`;`rb:A`;`rc:A`;`rx:A`;`M':A`;`Dp:A`;`m2:A`] th)) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`v:A`;`w:A`;`x:A`]
    NOT_CCFL) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(LABEL_TAC "nc" o CONJUNCT1 o CONJUNCT2) THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`mpv2:A`;`pw:A`]
         EBIMP_EXISTS) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `cc:A`) THEN
  SUBGOAL_THEN `(cc:A) IN D /\ (E:A->A->bool) cc B` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[EBIMP_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `etop D (E:A->A->bool) B leq cc` ASSUME_TAC THENL
   [USE_THEN "nc" (fun th -> MATCH_MP_TAC(ISPECL
      [`zeq2:A`;`pv:A`;`pw:A`;`mpv2:A`;`cc:A`] th)) THEN ASM_REWRITE_TAC[];
         ALL_TAC] THEN
  MP_TAC(ISPECL
         [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`mpv2:A`;`pw:A`;`cc:A`]
         EBIMP_TOP) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(fun th -> ASM_MESON_TAC[th]));;

(* ------------------------------------------------------------------ *)
(* IHD_C3W : discharge C3_STEP2's ihw.  For y in dom(w),              *)
(*   [[y in v]] MEET [[u=v]] <= [[y in u]] = pu.                       *)
(* This is C2 (container-cong) at reduced triple (v,u,y): rank(y)<rc   *)
(* so drop rc (LEXDROP_C1 with rr:=ry), giving ~ccfl v u y.  NOT_CCFL  *)
(* conj2 yields it; equality swapped via EBV_EQ_SYM, meet via EMEET_SYM.*)
(* ------------------------------------------------------------------ *)
let IHD_C3W = prove
 (`!D (E:A->A->bool) B leq d1 d2 d3 u v w ra rb rc zeq1.
      model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
      (!c. c IN D /\ E c d1 ==> ~badmax D E B leq c) /\
      (!c. c IN D /\ E c d2 ==> ~badmed D E B leq d1 c) /\
      (!c. c IN D /\ E c d3 ==> ~badmin D E B leq d1 d2 c) /\
      u IN D /\ v IN D /\ w IN D /\
      bname D E B u /\ bname D E B v /\ bname D E B w /\
      ra IN D /\ rb IN D /\ rc IN D /\
      eordinal D E ra /\ eordinal D E rb /\ eordinal D E rc /\
      ebnrank D E B u ra /\ ebnrank D E B v rb /\ ebnrank D E B w rc /\
      emax3 D E ra rb rc d1 /\ emed3 D E ra rb rc d2 /\
        emin3 D E ra rb rc d3 /\
      zeq1 IN D /\ ebv_eq D E B leq u v zeq1
      ==> !y qy pv pu mpv1.
            y IN D /\ eapply D E w y qy /\
            ebv_in D E B leq y v pv /\ ebv_in D E B leq y u pu /\
            emeet D E B leq pv zeq1 mpv1 /\ pu IN D
            ==> erel D E leq mpv1 pu`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`d1:A`;`d2:A`;`d3:A`]
    REDUCED_GOOD) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(LABEL_TAC "RG") THEN
  SUBGOAL_THEN `ebalg D (E:A->A->bool) B leq` ASSUME_TAC THENL
   [ASM_MESON_TAC[ECBA_IMP_BALG]; ALL_TAC] THEN
  SUBGOAL_THEN `eporder D (E:A->A->bool) B leq` ASSUME_TAC THENL
   [ASM_MESON_TAC[EBALG_IMP_PORDER]; ALL_TAC] THEN
  SUBGOAL_THEN `ebv_eq D (E:A->A->bool) B leq v u zeq1` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`u:A`;
                  `v:A`;`zeq1:A`]
                 EBV_EQ_SYM) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MAP_EVERY X_GEN_TAC [`y:A`;`qy:A`;`pv:A`;`pu:A`;`mpv1:A`] THEN STRIP_TAC THEN
  SUBGOAL_THEN `(mpv1:A) IN D /\ (pv:A) IN D /\
                (E:A->A->bool) mpv1 B /\ E pv B` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[EMEET_LE; EPORDER_FIELD]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) pu B` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`y:A`;`u:A`;`pu:A`]
                 EBV_IN_IN_B) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `emeet D (E:A->A->bool) B leq zeq1 pv mpv1` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`pv:A`;
                  `zeq1:A`;`mpv1:A`]
                 EMEET_SYM) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`w:A`;`y:A`;`qy:A`]
         EAPPLY_DVAL) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_THEN `q0:A` STRIP_ASSUME_TAC) THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`w:A`;`y:A`;`q0:A`;`rc:A`]
    EBNRANK_APPLY_LT) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC
             (X_CHOOSE_THEN `ry:A` STRIP_ASSUME_TAC)) THEN
  SUBGOAL_THEN `(ry:A) IN D /\ eordinal D (E:A->A->bool) ry`
    STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[EBNRANK_IN; EBNRANK_ORDINAL]; ALL_TAC] THEN
  SUBGOAL_THEN `?M':A. emax3 D E rb ra ry M'` (X_CHOOSE_TAC `M':A`) THENL
   [ASM_MESON_TAC[EMAX3_EXISTS]; ALL_TAC] THEN
  SUBGOAL_THEN `?Dp:A. emed3 D E rb ra ry Dp` (X_CHOOSE_TAC `Dp:A`) THENL
   [ASM_MESON_TAC[EMED3_EXISTS]; ALL_TAC] THEN
  SUBGOAL_THEN `?m2:A. emin3 D E rb ra ry m2` (X_CHOOSE_TAC `m2:A`) THENL
   [ASM_MESON_TAC[EMIN3_EXISTS]; ALL_TAC] THEN
  SUBGOAL_THEN `(M':A) IN D /\ (Dp:A) IN D /\ (m2:A) IN D`
    STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[EMAX3_ORDINAL; EMED3_ORDINAL; EMIN3_ORDINAL; EORDINAL_IN];
    ALL_TAC] THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`ra:A`;`rb:A`;`rc:A`;`ry:A`;
                 `d1:A`;`d2:A`;`d3:A`;`M':A`;`Dp:A`;`m2:A`] LEXDROP_C1) THEN
  ASM_REWRITE_TAC[] THEN DISCH_TAC THEN
  SUBGOAL_THEN `~ccfl D (E:A->A->bool) B leq v u y` ASSUME_TAC THENL
   [USE_THEN "RG" (fun th -> MATCH_MP_TAC(ISPECL
      [`v:A`;`u:A`;`y:A`;`rb:A`;`ra:A`;`ry:A`;`M':A`;`Dp:A`;`m2:A`] th)) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`v:A`;`u:A`;`y:A`]
    NOT_CCFL) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(LABEL_TAC "nc" o CONJUNCT1 o CONJUNCT2) THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`mpv1:A`;`pu:A`]
         EBIMP_EXISTS) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `cc:A`) THEN
  SUBGOAL_THEN `(cc:A) IN D /\ (E:A->A->bool) cc B` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[EBIMP_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `etop D (E:A->A->bool) B leq cc` ASSUME_TAC THENL
   [USE_THEN "nc" (fun th -> MATCH_MP_TAC(ISPECL
      [`zeq1:A`;`pv:A`;`pu:A`;`mpv1:A`;`cc:A`] th)) THEN ASM_REWRITE_TAC[];
         ALL_TAC] THEN
  MP_TAC(ISPECL
         [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`mpv1:A`;`pu:A`;`cc:A`]
         EBIMP_TOP) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(fun th -> ASM_MESON_TAC[th]));;

(* ------------------------------------------------------------------------- *)
(* NO_BAD_C1 : the C1 (left-argument IN -congruence) case of NO_BAD.         *)
(* Given the lex-least bad triple's leastness facts, its witness             *)
(* (u,v,w) at a common stage sw, and the disjunct-1 Boolean values           *)
(* z20=[[u=v]], z21=[[u IN w]], z22=[[v IN w]], z23=z20 /\ z21, z24=z23 ==>  *)
(* z22, show etop z24 (so NO_BAD's ~etop z24 gives a contradiction).         *)
(* Route: build the three values as STAGE values, bridge to global,          *)
(* identify with z20/z21/z22 (UNIQUE), discharge C1_STEP2's IH via           *)
(* IHD_C1, apply C1_STEP2 to get z23 <= z22, then EBIMP_TOP.                 *)
(* ------------------------------------------------------------------------- *)
let NO_BAD_C1 = prove
 (`!D (E:A->A->bool) B leq d1 d2 d3 u v w ra rb rc aw sw sIN sEQ
      z20 z21 z22 z23 z24.
      model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
      (!c. c IN D /\ E c d1 ==> ~badmax D E B leq c) /\
      (!c. c IN D /\ E c d2 ==> ~badmed D E B leq d1 c) /\
      (!c. c IN D /\ E c d3 ==> ~badmin D E B leq d1 d2 c) /\
      u IN D /\ v IN D /\ w IN D /\
      bname D E B u /\ bname D E B v /\ bname D E B w /\
      ra IN D /\ rb IN D /\ rc IN D /\
      eordinal D E ra /\ eordinal D E rb /\ eordinal D E rc /\
      ebnrank D E B u ra /\ ebnrank D E B v rb /\ ebnrank D E B w rc /\
      emax3 D E ra rb rc d1 /\ emed3 D E ra rb rc d2 /\
        emin3 D E ra rb rc d3 /\
      aw IN D /\ sw IN D /\ eordinal D E aw /\ ebnstage D E B aw sw /\
      E u sw /\ E v sw /\ E w sw /\ ebvatt D E B leq sw sIN sEQ /\
      z20 IN D /\ z21 IN D /\ z22 IN D /\ z23 IN D /\ z24 IN D /\
      ebv_eq D E B leq u v z20 /\ ebv_in D E B leq u w z21 /\
      ebv_in D E B leq v w z22 /\ emeet D E B leq z20 z21 z23 /\
      ebimp D E B leq z23 z22 z24
      ==> etop D E B leq z24`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `ebalg D (E:A->A->bool) B leq` ASSUME_TAC THENL
   [ASM_MESON_TAC[ECBA_IMP_BALG]; ALL_TAC] THEN
  SUBGOAL_THEN `eporder D (E:A->A->bool) B leq` ASSUME_TAC THENL
   [ASM_MESON_TAC[EBALG_IMP_PORDER]; ALL_TAC] THEN
  (* --- stage value zeqs = [[u=v]] --- *)
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`u:A`;`v:A`] EOPAIR_EXISTS) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `pruv:A`) THEN
  SUBGOAL_THEN `(pruv:A) IN D` ASSUME_TAC THENL
  [ASM_MESON_TAC[EOPAIR_IN]; ALL_TAC] THEN
  MP_TAC(ISPECL
         [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`sw:A`;`sIN:A`;`sEQ:A`;
          `u:A`;`v:A`;`pruv:A`] EBVATT_VAL) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(CONJUNCTS_THEN2 (K ALL_TAC)
    (X_CHOOSE_THEN `zeqs:A` STRIP_ASSUME_TAC)) THEN
  SUBGOAL_THEN `ebv_eq D (E:A->A->bool) B leq u v zeqs` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`aw:A`;
                  `sw:A`;`sIN:A`;
                  `sEQ:A`;`u:A`;`v:A`;`zeqs:A`] EBV_EQ_AT_STAGE) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `z20:A = zeqs` SUBST_ALL_TAC THENL
   [MP_TAC(ISPECL
           [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`u:A`;`v:A`;
            `z20:A`;`zeqs:A`]
           EBV_EQ_UNIQUE) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* --- stage value zins = [[u in w]] --- *)
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`u:A`;`w:A`] EOPAIR_EXISTS) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `pruw:A`) THEN
  SUBGOAL_THEN `(pruw:A) IN D` ASSUME_TAC THENL
  [ASM_MESON_TAC[EOPAIR_IN]; ALL_TAC] THEN
  MP_TAC(ISPECL
         [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`sw:A`;`sIN:A`;`sEQ:A`;
          `u:A`;`w:A`;`pruw:A`] EBVATT_VAL) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(CONJUNCTS_THEN2
    (X_CHOOSE_THEN `zins:A` STRIP_ASSUME_TAC) (K ALL_TAC)) THEN
  SUBGOAL_THEN `ebv_in D (E:A->A->bool) B leq u w zins` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`aw:A`;
                  `sw:A`;`sIN:A`;
                  `sEQ:A`;`u:A`;`w:A`;`zins:A`] EBV_IN_AT_STAGE) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `z21:A = zins` SUBST_ALL_TAC THENL
   [MP_TAC(ISPECL
           [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`u:A`;`w:A`;
            `z21:A`;`zins:A`]
           EBV_IN_UNIQUE) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* --- stage value zin2s = [[v in w]] --- *)
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`v:A`;`w:A`] EOPAIR_EXISTS) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `prvw:A`) THEN
  SUBGOAL_THEN `(prvw:A) IN D` ASSUME_TAC THENL
  [ASM_MESON_TAC[EOPAIR_IN]; ALL_TAC] THEN
  MP_TAC(ISPECL
         [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`sw:A`;`sIN:A`;`sEQ:A`;
          `v:A`;`w:A`;`prvw:A`] EBVATT_VAL) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(CONJUNCTS_THEN2
    (X_CHOOSE_THEN `zin2s:A` STRIP_ASSUME_TAC) (K ALL_TAC)) THEN
  SUBGOAL_THEN `ebv_in D (E:A->A->bool) B leq v w zin2s` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`aw:A`;
                  `sw:A`;`sIN:A`;
                  `sEQ:A`;`v:A`;`w:A`;`zin2s:A`] EBV_IN_AT_STAGE) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `z22:A = zin2s` SUBST_ALL_TAC THENL
   [MP_TAC(ISPECL
           [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`v:A`;`w:A`;
            `z22:A`;`zin2s:A`]
           EBV_IN_UNIQUE) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* --- discharge C1_STEP2's IH via IHD_C1 --- *)
  SUBGOAL_THEN
   `!r qr ar br mza.
       r IN D /\ eapply D (E:A->A->bool) w r qr /\
       ebv_eq D E B leq u r ar /\ ebv_eq D E B leq v r br /\
       emeet D E B leq zeqs ar mza /\ br IN D
       ==> erel D E leq mza br`
  (LABEL_TAC "ih1") THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`d1:A`;
                  `d2:A`;`d3:A`;
                  `u:A`;`v:A`;`w:A`;`ra:A`;`rb:A`;`rc:A`;`zeqs:A`] IHD_C1) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* --- apply C1_STEP2 --- *)
  MP_TAC(ISPECL
         [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`aw:A`;`sw:A`;
          `sIN:A`;`sEQ:A`;
          `u:A`;`v:A`;`w:A`;`zeqs:A`;`zins:A`;`zin2s:A`] C1_STEP2) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(MP_TAC o SPEC `z23:A`) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_TAC THEN
  (* --- EBIMP_TOP : etop z24 --- *)
  SUBGOAL_THEN `(E:A->A->bool) z23 B` ASSUME_TAC THENL
   [ASM_MESON_TAC[EMEET_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) zin2s B` ASSUME_TAC THENL
   [ASM_MESON_TAC[EBVIN_IN]; ALL_TAC] THEN
  MP_TAC(ISPECL
         [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`z23:A`;`zin2s:A`;`z24:A`]
         EBIMP_TOP) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  ASM_MESON_TAC[]);;

(* ------------------------------------------------------------------ *)
(* NO_BAD_C2 : the C2 (right-argument IN -congruence) case.              *)
(* disj2 values z20=[[u=v]], z21=[[w IN u]], z22=[[w IN v]].  Uses C2_STEP.  *)
(* ------------------------------------------------------------------ *)
let NO_BAD_C2 = prove
 (`!D (E:A->A->bool) B leq d1 d2 d3 u v w ra rb rc aw sw sIN sEQ
      z20 z21 z22 z23 z24.
      model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
      (!c. c IN D /\ E c d1 ==> ~badmax D E B leq c) /\
      (!c. c IN D /\ E c d2 ==> ~badmed D E B leq d1 c) /\
      (!c. c IN D /\ E c d3 ==> ~badmin D E B leq d1 d2 c) /\
      u IN D /\ v IN D /\ w IN D /\
      bname D E B u /\ bname D E B v /\ bname D E B w /\
      ra IN D /\ rb IN D /\ rc IN D /\
      eordinal D E ra /\ eordinal D E rb /\ eordinal D E rc /\
      ebnrank D E B u ra /\ ebnrank D E B v rb /\ ebnrank D E B w rc /\
      emax3 D E ra rb rc d1 /\ emed3 D E ra rb rc d2 /\
        emin3 D E ra rb rc d3 /\
      aw IN D /\ sw IN D /\ eordinal D E aw /\ ebnstage D E B aw sw /\
      E u sw /\ E v sw /\ E w sw /\ ebvatt D E B leq sw sIN sEQ /\
      z20 IN D /\ z21 IN D /\ z22 IN D /\ z23 IN D /\ z24 IN D /\
      ebv_eq D E B leq u v z20 /\ ebv_in D E B leq w u z21 /\
      ebv_in D E B leq w v z22 /\ emeet D E B leq z20 z21 z23 /\
      ebimp D E B leq z23 z22 z24
      ==> etop D E B leq z24`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `ebalg D (E:A->A->bool) B leq` ASSUME_TAC THENL
   [ASM_MESON_TAC[ECBA_IMP_BALG]; ALL_TAC] THEN
  SUBGOAL_THEN `eporder D (E:A->A->bool) B leq` ASSUME_TAC THENL
   [ASM_MESON_TAC[EBALG_IMP_PORDER]; ALL_TAC] THEN
  (* --- stage value zeqs = [[u=v]] --- *)
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`u:A`;`v:A`] EOPAIR_EXISTS) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `pruv:A`) THEN
  SUBGOAL_THEN `(pruv:A) IN D` ASSUME_TAC THENL
  [ASM_MESON_TAC[EOPAIR_IN]; ALL_TAC] THEN
  MP_TAC(ISPECL
         [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`sw:A`;`sIN:A`;`sEQ:A`;
          `u:A`;`v:A`;`pruv:A`] EBVATT_VAL) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(CONJUNCTS_THEN2 (K ALL_TAC)
    (X_CHOOSE_THEN `zeqs:A` STRIP_ASSUME_TAC)) THEN
  SUBGOAL_THEN `ebv_eq D (E:A->A->bool) B leq u v zeqs` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`aw:A`;
                  `sw:A`;`sIN:A`;
                  `sEQ:A`;`u:A`;`v:A`;`zeqs:A`] EBV_EQ_AT_STAGE) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `z20:A = zeqs` SUBST_ALL_TAC THENL
   [MP_TAC(ISPECL
           [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`u:A`;`v:A`;
            `z20:A`;`zeqs:A`]
           EBV_EQ_UNIQUE) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* --- stage value zins = [[w in u]] : pair(w,u), 1st conjunct ebvin sEQ u *)
  (* w --- *)
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`w:A`;`u:A`] EOPAIR_EXISTS) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `prwu:A`) THEN
  SUBGOAL_THEN `(prwu:A) IN D` ASSUME_TAC THENL
  [ASM_MESON_TAC[EOPAIR_IN]; ALL_TAC] THEN
  MP_TAC(ISPECL
         [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`sw:A`;`sIN:A`;`sEQ:A`;
          `w:A`;`u:A`;`prwu:A`] EBVATT_VAL) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(CONJUNCTS_THEN2
    (X_CHOOSE_THEN `zins:A` STRIP_ASSUME_TAC) (K ALL_TAC)) THEN
  SUBGOAL_THEN `ebv_in D (E:A->A->bool) B leq w u zins` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`aw:A`;
                  `sw:A`;`sIN:A`;
                  `sEQ:A`;`w:A`;`u:A`;`zins:A`] EBV_IN_AT_STAGE) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `z21:A = zins` SUBST_ALL_TAC THENL
   [MP_TAC(ISPECL
           [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`w:A`;`u:A`;
            `z21:A`;`zins:A`]
           EBV_IN_UNIQUE) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* --- stage value zin2s = [[w in v]] : pair(w,v), 1st conjunct ebvin sEQ *)
  (* v w --- *)
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`w:A`;`v:A`] EOPAIR_EXISTS) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `prwv:A`) THEN
  SUBGOAL_THEN `(prwv:A) IN D` ASSUME_TAC THENL
  [ASM_MESON_TAC[EOPAIR_IN]; ALL_TAC] THEN
  MP_TAC(ISPECL
         [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`sw:A`;`sIN:A`;`sEQ:A`;
          `w:A`;`v:A`;`prwv:A`] EBVATT_VAL) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(CONJUNCTS_THEN2
    (X_CHOOSE_THEN `zin2s:A` STRIP_ASSUME_TAC) (K ALL_TAC)) THEN
  SUBGOAL_THEN `ebv_in D (E:A->A->bool) B leq w v zin2s` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`aw:A`;
                  `sw:A`;`sIN:A`;
                  `sEQ:A`;`w:A`;`v:A`;`zin2s:A`] EBV_IN_AT_STAGE) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `z22:A = zin2s` SUBST_ALL_TAC THENL
   [MP_TAC(ISPECL
           [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`w:A`;`v:A`;
            `z22:A`;`zin2s:A`]
           EBV_IN_UNIQUE) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* --- C2_STEP requires E zin2 B explicitly (unlike C1_STEP2) --- *)
  SUBGOAL_THEN `(E:A->A->bool) zin2s B` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`w:A`;
                  `v:A`;`zin2s:A`]
                 EBV_IN_IN_B) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* --- discharge C2_STEP's IH via IHD_C2 --- *)
  SUBGOAL_THEN
   `!y qy ey tv m.
       y IN D /\ eapply D (E:A->A->bool) u y qy /\
       ebv_eq D E B leq w y ey /\ ebv_in D E B leq y v tv /\
       emeet D E B leq ey tv m
       ==> erel D E leq m zin2s`
  (LABEL_TAC "ih2") THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`d1:A`;
                  `d2:A`;`d3:A`;
                  `u:A`;`v:A`;`w:A`;`ra:A`;`rb:A`;`rc:A`;`zin2s:A`]
                   IHD_C2) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* --- apply C2_STEP --- *)
  MP_TAC(ISPECL
         [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`aw:A`;`sw:A`;
          `sIN:A`;`sEQ:A`;
          `u:A`;`v:A`;`w:A`;`zeqs:A`;`zins:A`;`zin2s:A`] C2_STEP) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(MP_TAC o SPEC `z23:A`) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_TAC THEN
  (* --- EBIMP_TOP : etop z24 --- *)
  SUBGOAL_THEN `(E:A->A->bool) z23 B` ASSUME_TAC THENL
   [ASM_MESON_TAC[EMEET_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) zin2s B` ASSUME_TAC THENL
   [ASM_MESON_TAC[EBVIN_IN]; ALL_TAC] THEN
  MP_TAC(ISPECL
         [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`z23:A`;`zin2s:A`;`z24:A`]
         EBIMP_TOP) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  ASM_MESON_TAC[]);;

(* ------------------------------------------------------------------ *)
(* NO_BAD_C3 : the C3 (transitivity) case.                             *)
(* disj3 values z20=[[u=v]], z21=[[v=w]], z22=[[u=w]].  Uses C3_STEP2. *)
(* ------------------------------------------------------------------ *)
let NO_BAD_C3 = prove
 (`!D (E:A->A->bool) B leq d1 d2 d3 u v w ra rb rc aw sw sIN sEQ
      z20 z21 z22 z23 z24.
      model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
      (!c. c IN D /\ E c d1 ==> ~badmax D E B leq c) /\
      (!c. c IN D /\ E c d2 ==> ~badmed D E B leq d1 c) /\
      (!c. c IN D /\ E c d3 ==> ~badmin D E B leq d1 d2 c) /\
      u IN D /\ v IN D /\ w IN D /\
      bname D E B u /\ bname D E B v /\ bname D E B w /\
      ra IN D /\ rb IN D /\ rc IN D /\
      eordinal D E ra /\ eordinal D E rb /\ eordinal D E rc /\
      ebnrank D E B u ra /\ ebnrank D E B v rb /\ ebnrank D E B w rc /\
      emax3 D E ra rb rc d1 /\ emed3 D E ra rb rc d2 /\
        emin3 D E ra rb rc d3 /\
      aw IN D /\ sw IN D /\ eordinal D E aw /\ ebnstage D E B aw sw /\
      E u sw /\ E v sw /\ E w sw /\ ebvatt D E B leq sw sIN sEQ /\
      z20 IN D /\ z21 IN D /\ z22 IN D /\ z23 IN D /\ z24 IN D /\
      ebv_eq D E B leq u v z20 /\ ebv_eq D E B leq v w z21 /\
      ebv_eq D E B leq u w z22 /\ emeet D E B leq z20 z21 z23 /\
      ebimp D E B leq z23 z22 z24
      ==> etop D E B leq z24`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `ebalg D (E:A->A->bool) B leq` ASSUME_TAC THENL
   [ASM_MESON_TAC[ECBA_IMP_BALG]; ALL_TAC] THEN
  SUBGOAL_THEN `eporder D (E:A->A->bool) B leq` ASSUME_TAC THENL
   [ASM_MESON_TAC[EBALG_IMP_PORDER]; ALL_TAC] THEN
  (* --- stage value zeqs1 = [[u=v]] --- *)
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`u:A`;`v:A`] EOPAIR_EXISTS) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `pruv:A`) THEN
  SUBGOAL_THEN `(pruv:A) IN D` ASSUME_TAC THENL
  [ASM_MESON_TAC[EOPAIR_IN]; ALL_TAC] THEN
  MP_TAC(ISPECL
         [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`sw:A`;`sIN:A`;`sEQ:A`;
          `u:A`;`v:A`;`pruv:A`] EBVATT_VAL) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(CONJUNCTS_THEN2 (K ALL_TAC)
    (X_CHOOSE_THEN `zeqs1:A` STRIP_ASSUME_TAC)) THEN
  SUBGOAL_THEN `ebv_eq D (E:A->A->bool) B leq u v zeqs1` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`aw:A`;
                  `sw:A`;`sIN:A`;
                  `sEQ:A`;`u:A`;`v:A`;`zeqs1:A`] EBV_EQ_AT_STAGE) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `z20:A = zeqs1` SUBST_ALL_TAC THENL
   [MP_TAC(ISPECL
           [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`u:A`;`v:A`;
            `z20:A`;`zeqs1:A`]
           EBV_EQ_UNIQUE) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* --- stage value zeqs2 = [[v=w]] --- *)
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`v:A`;`w:A`] EOPAIR_EXISTS) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `prvw:A`) THEN
  SUBGOAL_THEN `(prvw:A) IN D` ASSUME_TAC THENL
  [ASM_MESON_TAC[EOPAIR_IN]; ALL_TAC] THEN
  MP_TAC(ISPECL
         [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`sw:A`;`sIN:A`;`sEQ:A`;
          `v:A`;`w:A`;`prvw:A`] EBVATT_VAL) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(CONJUNCTS_THEN2 (K ALL_TAC)
    (X_CHOOSE_THEN `zeqs2:A` STRIP_ASSUME_TAC)) THEN
  SUBGOAL_THEN `ebv_eq D (E:A->A->bool) B leq v w zeqs2` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`aw:A`;
                  `sw:A`;`sIN:A`;
                  `sEQ:A`;`v:A`;`w:A`;`zeqs2:A`] EBV_EQ_AT_STAGE) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `z21:A = zeqs2` SUBST_ALL_TAC THENL
   [MP_TAC(ISPECL
           [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`v:A`;`w:A`;
            `z21:A`;`zeqs2:A`]
           EBV_EQ_UNIQUE) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* --- stage value zuws = [[u=w]] --- *)
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`u:A`;`w:A`] EOPAIR_EXISTS) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `pruw:A`) THEN
  SUBGOAL_THEN `(pruw:A) IN D` ASSUME_TAC THENL
  [ASM_MESON_TAC[EOPAIR_IN]; ALL_TAC] THEN
  MP_TAC(ISPECL
         [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`sw:A`;`sIN:A`;`sEQ:A`;
          `u:A`;`w:A`;`pruw:A`] EBVATT_VAL) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(CONJUNCTS_THEN2 (K ALL_TAC)
    (X_CHOOSE_THEN `zuws:A` STRIP_ASSUME_TAC)) THEN
  SUBGOAL_THEN `ebv_eq D (E:A->A->bool) B leq u w zuws` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`aw:A`;
                  `sw:A`;`sIN:A`;
                  `sEQ:A`;`u:A`;`w:A`;`zuws:A`] EBV_EQ_AT_STAGE) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `z22:A = zuws` SUBST_ALL_TAC THENL
   [MP_TAC(ISPECL
           [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`u:A`;`w:A`;
            `z22:A`;`zuws:A`]
           EBV_EQ_UNIQUE) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* --- discharge C3_STEP2's ihu via IHD_C3U --- *)
  SUBGOAL_THEN
   `!x qx pv pw mpv2.
       x IN D /\ eapply D (E:A->A->bool) u x qx /\ ebv_in D E B leq x v pv /\
       ebv_in D E B leq x w pw /\ emeet D E B leq pv zeqs2 mpv2 /\ pw IN D
       ==> erel D E leq mpv2 pw`
  (LABEL_TAC "ihu") THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`d1:A`;
                  `d2:A`;`d3:A`;
                  `u:A`;`v:A`;`w:A`;`ra:A`;`rb:A`;`rc:A`;`zeqs2:A`]
                   IHD_C3U) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* --- discharge C3_STEP2's ihw via IHD_C3W --- *)
  SUBGOAL_THEN
   `!y qy pv pu mpv1.
       y IN D /\ eapply D (E:A->A->bool) w y qy /\ ebv_in D E B leq y v pv /\
       ebv_in D E B leq y u pu /\ emeet D E B leq pv zeqs1 mpv1 /\ pu IN D
       ==> erel D E leq mpv1 pu`
  (LABEL_TAC "ihw") THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`d1:A`;
                  `d2:A`;`d3:A`;
                  `u:A`;`v:A`;`w:A`;`ra:A`;`rb:A`;`rc:A`;`zeqs1:A`]
                   IHD_C3W) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* --- apply C3_STEP2 --- *)
  MP_TAC(ISPECL
         [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`aw:A`;`sw:A`;
          `sIN:A`;`sEQ:A`;
          `u:A`;`v:A`;`w:A`;`zeqs1:A`;`zeqs2:A`;`zuws:A`] C3_STEP2) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(MP_TAC o SPEC `z23:A`) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_TAC THEN
  (* --- EBIMP_TOP : etop z24 --- *)
  SUBGOAL_THEN `(E:A->A->bool) z23 B` ASSUME_TAC THENL
   [ASM_MESON_TAC[EMEET_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) zuws B` ASSUME_TAC THENL
   [ASM_MESON_TAC[EBVEQ_IN]; ALL_TAC] THEN
  MP_TAC(ISPECL
         [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`z23:A`;`zuws:A`;`z24:A`]
         EBIMP_TOP) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  ASM_MESON_TAC[]);;

(* ------------------------------------------------------------------ *)
(* NO_BAD : no bad triple of bnames exists.  The crux of the           *)
(* fundamental Boolean-equality congruence.  Assume one exists; take   *)
(* the lex-least (LEAST_BAD_TRIPLE); extract its witness (u,v,w) with   *)
(* ranks and common stage; whichever ccfl disjunct holds, the matching *)
(* NO_BAD_C* forces etop z24, contradicting ccfl's ~etop z24.          *)
(* ------------------------------------------------------------------ *)
let NO_BAD = prove
 (`!D (E:A->A->bool) B leq.
      model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D
      ==> ~(?u v w. u IN D /\ v IN D /\ w IN D /\
                    bname D E B u /\ bname D E B v /\ bname D E B w /\
                    ccfl D E B leq u v w)`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  MATCH_MP_TAC(TAUT `(a ==> F) ==> ~a`) THEN
  DISCH_THEN(X_CHOOSE_THEN `u0:A` (X_CHOOSE_THEN `v0:A`
    (X_CHOOSE_THEN `w0:A` STRIP_ASSUME_TAC))) THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`]
         LEAST_BAD_TRIPLE) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[] THEN MAP_EVERY EXISTS_TAC [`u0:A`;`v0:A`;`w0:A`] THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `d1:A` (X_CHOOSE_THEN `d2:A`
    (X_CHOOSE_THEN `d3:A` STRIP_ASSUME_TAC))) THEN
  UNDISCH_TAC `badmin D (E:A->A->bool) B leq d1 d2 d3` THEN
  REWRITE_TAC[badmin] THEN
  DISCH_THEN(X_CHOOSE_THEN `u:A` (X_CHOOSE_THEN `v:A` (X_CHOOSE_THEN `w:A`
    (X_CHOOSE_THEN `ra:A` (X_CHOOSE_THEN `rb:A` (X_CHOOSE_THEN `rc:A`
     STRIP_ASSUME_TAC)))))) THEN
  SUBGOAL_THEN
    `eordinal D (E:A->A->bool) ra /\ eordinal D E rb /\ eordinal D E rc`
  STRIP_ASSUME_TAC THENL [ASM_MESON_TAC[EBNRANK_ORDINAL]; ALL_TAC] THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`u:A`;`v:A`;`w:A`]
         BNAME_DIRECTED3) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `aw:A` (X_CHOOSE_THEN `sw:A` STRIP_ASSUME_TAC)) THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`sw:A`]
         EBVATT_EXISTS) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
     [X_GEN_TAC `zt:A` THEN STRIP_TAC THEN
      MATCH_MP_TAC(ISPECL
                   [`D:A->bool`;`E:A->A->bool`;`B:A`;`aw:A`;`sw:A`;`zt:A`]
                   BNAME_STAGE) THEN ASM_REWRITE_TAC[];
      EXISTS_TAC `u:A` THEN ASM_REWRITE_TAC[]]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `sIN:A` (X_CHOOSE_THEN `sEQ:A` ASSUME_TAC)) THEN
  UNDISCH_TAC `ccfl D (E:A->A->bool) B leq u v w` THEN
  REWRITE_TAC[ccfl] THEN
  DISCH_THEN(DISJ_CASES_THEN2
    (X_CHOOSE_THEN `z20:A` (X_CHOOSE_THEN `z21:A` (X_CHOOSE_THEN `z22:A`
      (X_CHOOSE_THEN `z23:A` (X_CHOOSE_THEN `z24:A` STRIP_ASSUME_TAC)))))
    (DISJ_CASES_THEN2
      (X_CHOOSE_THEN `z20:A` (X_CHOOSE_THEN `z21:A` (X_CHOOSE_THEN `z22:A`
        (X_CHOOSE_THEN `z23:A` (X_CHOOSE_THEN `z24:A` STRIP_ASSUME_TAC)))))
      (X_CHOOSE_THEN `z20:A` (X_CHOOSE_THEN `z21:A` (X_CHOOSE_THEN `z22:A`
        (X_CHOOSE_THEN `z23:A`
         (X_CHOOSE_THEN `z24:A` STRIP_ASSUME_TAC))))))) THENL
   [SUBGOAL_THEN `etop D (E:A->A->bool) B leq z24` ASSUME_TAC THENL
     [MATCH_MP_TAC(ISPECL
                   [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`d1:A`;
                    `d2:A`;`d3:A`;
                    `u:A`;`v:A`;`w:A`;`ra:A`;`rb:A`;`rc:A`;`aw:A`;`sw:A`;
                    `sIN:A`;`sEQ:A`;
                    `z20:A`;`z21:A`;`z22:A`;`z23:A`;`z24:A`] NO_BAD_C1) THEN
      ASM_REWRITE_TAC[]; ALL_TAC] THEN
    ASM_MESON_TAC[];
    SUBGOAL_THEN `etop D (E:A->A->bool) B leq z24` ASSUME_TAC THENL
     [MATCH_MP_TAC(ISPECL
                   [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`d1:A`;
                    `d2:A`;`d3:A`;
                    `u:A`;`v:A`;`w:A`;`ra:A`;`rb:A`;`rc:A`;`aw:A`;`sw:A`;
                    `sIN:A`;`sEQ:A`;
                    `z20:A`;`z21:A`;`z22:A`;`z23:A`;`z24:A`] NO_BAD_C2) THEN
      ASM_REWRITE_TAC[]; ALL_TAC] THEN
    ASM_MESON_TAC[];
    SUBGOAL_THEN `etop D (E:A->A->bool) B leq z24` ASSUME_TAC THENL
     [MATCH_MP_TAC(ISPECL
                   [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`d1:A`;
                    `d2:A`;`d3:A`;
                    `u:A`;`v:A`;`w:A`;`ra:A`;`rb:A`;`rc:A`;`aw:A`;`sw:A`;
                    `sIN:A`;`sEQ:A`;
                    `z20:A`;`z21:A`;`z22:A`;`z23:A`;`z24:A`] NO_BAD_C3) THEN
      ASM_REWRITE_TAC[]; ALL_TAC] THEN
    ASM_MESON_TAC[]]);;

(* ------------------------------------------------------------------ *)
(* NO_CCFL : the usable corollary -- for any bnames u,v,w, ~ccfl.       *)
(* ------------------------------------------------------------------ *)
let NO_CCFL = prove
 (`!D (E:A->A->bool) B leq u v w.
      model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
      u IN D /\ v IN D /\ w IN D /\
      bname D E B u /\ bname D E B v /\ bname D E B w
      ==> ~ccfl D E B leq u v w`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  MATCH_MP_TAC(TAUT `(a ==> F) ==> ~a`) THEN DISCH_TAC THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`] NO_BAD) THEN
  ASM_REWRITE_TAC[] THEN
  MAP_EVERY EXISTS_TAC [`u:A`;`v:A`;`w:A`] THEN ASM_REWRITE_TAC[]);;

(* =================================================================== *)
(* F5 fundamental congruences (top level, Leibniz form).               *)
(*                                                                     *)
(* Peel NO_CCFL (~ccfl of any three B-names) via NOT_CCFL into the     *)
(* three semantic congruence inequalities.  In each, z23 = the MEET of *)
(* the two premise-values and the conclusion is  z23 <= z22 :          *)
(*                                                                     *)
(*   EBV_EQ_CONG   [[u=v]] MEET [[v=w]] <= [[u=w]]   (transitivity)     *)
(*   EBV_IN_CONG_L [[u=v]] MEET [[u in w]] <= [[v in w]]  (left arg)    *)
(*   EBV_IN_CONG_R [[u=v]] MEET [[w in u]] <= [[w in v]]  (right arg)   *)
(*                                                                     *)
(* Proof pattern (identical up to the z22-membership lemma and which   *)
(* NOT_CCFL conjunct): build z24 = z23 IMP z22 (EBIMP_EXISTS); rewrite  *)
(* the goal erel z23 z22 to etop z24 (EBIMP_TOP); obtain etop z24 from  *)
(* NO_CCFL + NOT_CCFL's matching conjunct specialised to z20..z24.      *)
(* These are the Leibniz congruences (distinct from the                *)
(* combiner-agreement lemmas EBVEQ_CONG / EBVIN_CONG).                 *)
(* =================================================================== *)

(* C3 : transitivity of Boolean equality. *)
let EBV_EQ_CONG = prove
 (`!D (E:A->A->bool) B leq u v w z20 z21 z22 z23.
      model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
      u IN D /\ v IN D /\ w IN D /\
      bname D E B u /\ bname D E B v /\ bname D E B w /\
      z20 IN D /\ z21 IN D /\ z22 IN D /\ z23 IN D /\
      ebv_eq D E B leq u v z20 /\ ebv_eq D E B leq v w z21 /\
      ebv_eq D E B leq u w z22 /\ emeet D E B leq z20 z21 z23
      ==> erel D E leq z23 z22`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `ebalg D (E:A->A->bool) B leq` ASSUME_TAC THENL
   [ASM_MESON_TAC[ECBA_IMP_BALG]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) z22 B` ASSUME_TAC THENL
   [ASM_MESON_TAC[EBV_EQ_IN_B]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) z23 B` ASSUME_TAC THENL
   [ASM_MESON_TAC[EMEET_IN]; ALL_TAC] THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`z23:A`;`z22:A`]
    EBIMP_EXISTS) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `z24:A`) THEN
  SUBGOAL_THEN `(z24:A) IN D /\ (E:A->A->bool) z24 B` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[EBIMP_IN]; ALL_TAC] THEN
  MP_TAC(ISPECL
         [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`z23:A`;`z22:A`;`z24:A`]
         EBIMP_TOP) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(SUBST1_TAC o SYM) THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`u:A`;`v:A`;`w:A`]
    NO_CCFL) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(MP_TAC o SPECL [`z20:A`;`z21:A`;`z22:A`;`z23:A`;`z24:A`] o
            CONJUNCT2 o CONJUNCT2 o MATCH_MP NOT_CCFL) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC]);;

(* C1 : left-argument membership congruence. *)
let EBV_IN_CONG_L = prove
 (`!D (E:A->A->bool) B leq u v w z20 z21 z22 z23.
      model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
      u IN D /\ v IN D /\ w IN D /\
      bname D E B u /\ bname D E B v /\ bname D E B w /\
      z20 IN D /\ z21 IN D /\ z22 IN D /\ z23 IN D /\
      ebv_eq D E B leq u v z20 /\ ebv_in D E B leq u w z21 /\
      ebv_in D E B leq v w z22 /\ emeet D E B leq z20 z21 z23
      ==> erel D E leq z23 z22`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `ebalg D (E:A->A->bool) B leq` ASSUME_TAC THENL
   [ASM_MESON_TAC[ECBA_IMP_BALG]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) z22 B` ASSUME_TAC THENL
   [ASM_MESON_TAC[EBV_IN_IN_B]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) z23 B` ASSUME_TAC THENL
   [ASM_MESON_TAC[EMEET_IN]; ALL_TAC] THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`z23:A`;`z22:A`]
    EBIMP_EXISTS) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `z24:A`) THEN
  SUBGOAL_THEN `(z24:A) IN D /\ (E:A->A->bool) z24 B` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[EBIMP_IN]; ALL_TAC] THEN
  MP_TAC(ISPECL
         [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`z23:A`;`z22:A`;`z24:A`]
         EBIMP_TOP) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(SUBST1_TAC o SYM) THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`u:A`;`v:A`;`w:A`]
    NO_CCFL) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(MP_TAC o SPECL [`z20:A`;`z21:A`;`z22:A`;`z23:A`;`z24:A`] o
            CONJUNCT1 o MATCH_MP NOT_CCFL) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC]);;

(* C2 : right-argument membership congruence (the union/separation      *)
(* consumer: [[w=s]] MEET [[z in w]] <= [[z in s]] is this at (w,s,z)). *)
let EBV_IN_CONG_R = prove
 (`!D (E:A->A->bool) B leq u v w z20 z21 z22 z23.
      model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
      u IN D /\ v IN D /\ w IN D /\
      bname D E B u /\ bname D E B v /\ bname D E B w /\
      z20 IN D /\ z21 IN D /\ z22 IN D /\ z23 IN D /\
      ebv_eq D E B leq u v z20 /\ ebv_in D E B leq w u z21 /\
      ebv_in D E B leq w v z22 /\ emeet D E B leq z20 z21 z23
      ==> erel D E leq z23 z22`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `ebalg D (E:A->A->bool) B leq` ASSUME_TAC THENL
   [ASM_MESON_TAC[ECBA_IMP_BALG]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) z22 B` ASSUME_TAC THENL
   [ASM_MESON_TAC[EBV_IN_IN_B]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) z23 B` ASSUME_TAC THENL
   [ASM_MESON_TAC[EMEET_IN]; ALL_TAC] THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`z23:A`;`z22:A`]
    EBIMP_EXISTS) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `z24:A`) THEN
  SUBGOAL_THEN `(z24:A) IN D /\ (E:A->A->bool) z24 B` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[EBIMP_IN]; ALL_TAC] THEN
  MP_TAC(ISPECL
         [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`z23:A`;`z22:A`;`z24:A`]
         EBIMP_TOP) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(SUBST1_TAC o SYM) THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`u:A`;`v:A`;`w:A`]
    NO_CCFL) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(MP_TAC o SPECL [`z20:A`;`z21:A`;`z22:A`;`z23:A`;`z24:A`] o
            CONJUNCT1 o CONJUNCT2 o MATCH_MP NOT_CCFL) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC]);;

(* ===================================================================== *)
(* F5 UNION axiom: the union-value infrastructure.                       *)
(*   For a B-name x (functional set of pairs <w, x(w)>), the union name   *)
(*   un has domain W = U{dom w : w in dom x} and value                    *)
(*        un(s) = SUP_{w in dom x} ( x(w) MEET w(s) ).                    *)
(*   euucomb c = "c is a union-combiner x(w) MEET w(s)"; the image set    *)
(*   S = {c : euucomb c} (subset of B) is carved by ZF separation via the *)
(*   OBJECT formula euucomb_form; euuval = its supremum (ECBA_SUP).       *)
(*   Mirrors bvcomb/ebvinset/ebvin.                                       *)
(* ===================================================================== *)

(* c is a union-combiner  x(w) MEET w(s)  for some name w in dom x with   *)
(* s in dom w.  x = container B-name, s = candidate element name.         *)
let euucomb = new_definition
  `euucomb D (E:A->A->bool) B leq x s c <=>
        ?w qw ws.
            w IN D /\ qw IN D /\ ws IN D /\
            eapply D E x w qw /\ eapply D E w s ws /\
            emeet D E B leq qw ws c`;;

let EUUCOMB_IN = prove
 (`!D (E:A->A->bool) B leq x s c.
        euucomb D E B leq x s c ==> c IN D /\ E c B`,
  REWRITE_TAC[euucomb] THEN MESON_TAC[EMEET_IN]);;

(* the image set  {c IN D : euucomb c}  (a subset of B).                  *)
let euucombset = new_definition
  `euucombset D (E:A->A->bool) B leq x s S <=>
        S IN D /\
        !c. c IN D ==> (E c S <=> euucomb D E B leq x s c)`;;

let EUUCOMBSET_SUBSET = prove
 (`!D (E:A->A->bool) B leq x s S.
        euucombset D E B leq x s S ==> esubset D E S B`,
  REWRITE_TAC[euucombset; esubset] THEN MESON_TAC[EUUCOMB_IN]);;

let EUUCOMBSET_UNIQUE = prove
 (`!D (E:A->A->bool) B leq x s S S'.
        model D E ZF_AX /\
        euucombset D E B leq x s S /\ euucombset D E B leq x s S'
        ==> S = S'`,
  REWRITE_TAC[euucombset] THEN REPEAT STRIP_TAC THEN
  FIRST_ASSUM(MATCH_MP_TAC o MATCH_MP ZF_EXTENSIONALITY) THEN
  ASM_SIMP_TAC[]);;

(* the union-value  un(s) = SUP over w in dom x of  x(w) MEET w(s).       *)
let euuval = new_definition
  `euuval D (E:A->A->bool) B leq x s z <=>
        ?S. euucombset D E B leq x s S /\ elub D E B leq S z`;;

let EUUVAL_IN = prove
 (`!D (E:A->A->bool) B leq x s z.
        euuval D E B leq x s z ==> z IN D /\ E z B`,
  REWRITE_TAC[euuval] THEN MESON_TAC[ELUB_IN]);;

let EUUVAL_UNIQUE = prove
 (`!D (E:A->A->bool) B leq x s z z'.
        model D E ZF_AX /\ ecba D E B leq /\
        euuval D E B leq x s z /\ euuval D E B leq x s z'
        ==> z = z'`,
  REWRITE_TAC[euuval] THEN REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `S':A = S` SUBST_ALL_TAC THENL
   [ASM_MESON_TAC[EUUCOMBSET_UNIQUE]; ALL_TAC] THEN
  ASM_MESON_TAC[ELUB_UNIQUE; ECBA_IMP_PORDER]);;

(* -- euucomb as an OBJECT formula, with FV and HOLDS characterisation -- *)
(* Params: ic (value c), ix (container x), isv (element s), ileq (order),  *)
(* iB (carrier). Fresh bound vars w=MM+1, qw=MM+2, ws=MM+3, MM = MAX-nest. *)
let euucomb_form = new_definition
  `euucomb_form ic ix isv ileq iB =
     ?? (MAX (MAX (MAX ic ix) (MAX isv ileq)) iB + 1)
       (?? (MAX (MAX (MAX ic ix) (MAX isv ileq)) iB + 2)
         (?? (MAX (MAX (MAX ic ix) (MAX isv ileq)) iB + 3)
           (apply_form ix
              (MAX (MAX (MAX ic ix) (MAX isv ileq)) iB + 1)
              (MAX (MAX (MAX ic ix) (MAX isv ileq)) iB + 2) &&
            apply_form (MAX (MAX (MAX ic ix) (MAX isv ileq)) iB + 1) isv
              (MAX (MAX (MAX ic ix) (MAX isv ileq)) iB + 3) &&
            bmeet_form ileq iB
              (MAX (MAX (MAX ic ix) (MAX isv ileq)) iB + 2)
              (MAX (MAX (MAX ic ix) (MAX isv ileq)) iB + 3)
              ic)))`;;

let HOLDS_EUUCOMB_FORM = prove
 (`!D (E:A->A->bool) v ic ix isv ileq iB.
        model D E ZF_AX /\ valuation D v
        ==> (holds D E v (euucomb_form ic ix isv ileq iB) <=>
             euucomb D E (v iB) (v ileq) (v ix) (v isv) (v ic))`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `!x. (v:num->A) x IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[valuation]; ALL_TAC] THEN
  REWRITE_TAC[euucomb_form] THEN
  ABBREV_TAC `MM = MAX (MAX (MAX ic ix) (MAX isv ileq)) iB` THEN
  SUBGOAL_THEN
   `~(ic = MM + 1) /\ ~(ic = MM + 2) /\ ~(ic = MM + 3) /\
    ~(ix = MM + 1) /\ ~(ix = MM + 2) /\ ~(ix = MM + 3) /\
    ~(isv = MM + 1) /\ ~(isv = MM + 2) /\ ~(isv = MM + 3) /\
    ~(ileq = MM + 1) /\ ~(ileq = MM + 2) /\ ~(ileq = MM + 3) /\
    ~(iB = MM + 1) /\ ~(iB = MM + 2) /\ ~(iB = MM + 3) /\
    ~(MM + 1 = MM + 2) /\ ~(MM + 1 = MM + 3) /\ ~(MM + 2 = MM + 3)`
  STRIP_ASSUME_TAC THENL
   [EXPAND_TAC "MM" THEN ARITH_TAC; ALL_TAC] THEN
  SUBGOAL_THEN
   `!a b c:A. a IN D /\ b IN D /\ c IN D
      ==> (holds D E
             (((MM + 3) |-> c) (((MM + 2) |-> b) (((MM + 1) |-> a) v)))
             (apply_form ix (MM + 1) (MM + 2) &&
              apply_form (MM + 1) isv (MM + 3) &&
              bmeet_form ileq iB (MM + 2) (MM + 3) ic) <=>
           eapply D E (v ix) a b /\
           eapply D E a (v isv) c /\
           emeet D E (v iB) (v ileq) b c (v ic))`
  (LABEL_TAC "body") THENL
   [REPEAT STRIP_TAC THEN
    SUBGOAL_THEN
     `valuation D
        (((MM + 3) |-> (c:A)) (((MM + 2) |-> b) (((MM + 1) |-> a) v)))`
    ASSUME_TAC THENL [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
    REWRITE_TAC[HOLDS_AND] THEN
    ASM_SIMP_TAC[HOLDS_APPLY_FORM; HOLDS_BMEET_FORM] THEN
    ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER];
    ALL_TAC] THEN
  REWRITE_TAC[HOLDS_EX] THEN
  REWRITE_TAC[euucomb] THEN
  REMOVE_THEN "body" (fun bth ->
    POP_ASSUM_LIST(K ALL_TAC) THEN
    EQ_TAC THENL
     [INTRO_TAC "@a. aD @b. bD @c. cD h" THEN
      MAP_EVERY EXISTS_TAC [`a:A`; `b:A`; `c:A`] THEN
      ASM_MESON_TAC[bth];
      DISCH_THEN(X_CHOOSE_THEN `w:A` (X_CHOOSE_THEN `qw:A`
        (X_CHOOSE_THEN `ws:A` STRIP_ASSUME_TAC))) THEN
      EXISTS_TAC `w:A` THEN ASM_REWRITE_TAC[] THEN
      EXISTS_TAC `qw:A` THEN ASM_REWRITE_TAC[] THEN
      EXISTS_TAC `ws:A` THEN ASM_REWRITE_TAC[] THEN
      ASM_MESON_TAC[bth]]));;

(* -- existence of the image set and of the union-value ----------------- *)
(* indices: ic=1 (the separated var c), ix=3, isv=4, ileq=6, iB=7.        *)
let EUUCOMBSET_EXISTS = prove
 (`!D (E:A->A->bool) B leq x s.
        model D E ZF_AX /\
        B IN D /\ leq IN D /\ x IN D /\ s IN D
        ==> ?S. euucombset D E B leq x s S`,
  REPEAT STRIP_TAC THEN
  FIRST_ASSUM(X_CHOOSE_TAC `val0:num->A` o MATCH_MP VALUATION_EXISTS o
              MATCH_MP MODEL_NONEMPTY) THEN
  ABBREV_TAC
   `val = (3 |-> (x:A))
          ((4 |-> (s:A)) ((6 |-> (leq:A)) ((7 |-> (B:A)) val0)))` THEN
  SUBGOAL_THEN
   `valuation D (val:num->A) /\
    (val:num->A) 3 = x /\ (val:num->A) 4 = s /\
    (val:num->A) 6 = leq /\ (val:num->A) 7 = B`
  STRIP_ASSUME_TAC THENL
   [EXPAND_TAC "val" THEN REPEAT CONJ_TAC THEN
    REWRITE_TAC[VALMOD; ARITH_EQ] THEN ASM_MESON_TAC[VALUATION_VALMOD];
    ALL_TAC] THEN
  MP_TAC(SPECL [`euucomb_form 1 3 4 6 7`; `1`; `val:num->A`; `B:A`]
    (MATCH_MP ZF_SEPARATION (ASSUME `model D (E:A->A->bool) ZF_AX`))) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `S:A`
    (CONJUNCTS_THEN2 ASSUME_TAC (LABEL_TAC "sep"))) THEN
  SUBGOAL_THEN
   `!z. z IN D
        ==> (holds D E ((1 |-> (z:A)) val) (euucomb_form 1 3 4 6 7) <=>
             euucomb D E B leq x s z)`
  (LABEL_TAC "phi") THENL
   [X_GEN_TAC `z:A` THEN DISCH_TAC THEN
    SUBGOAL_THEN `valuation D ((1 |-> (z:A)) val)` ASSUME_TAC THENL
     [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
    MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`(1 |-> (z:A)) val`;
                  `1`;`3`;`4`;`6`;`7`] HOLDS_EUUCOMB_FORM) THEN
    ASM_REWRITE_TAC[] THEN DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    REWRITE_TAC[VALMOD; ARITH_EQ] THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!z. z IN D ==> ((E:A->A->bool) z S <=> euucomb D E B leq x s z)`
  (LABEL_TAC "mem") THENL
   [X_GEN_TAC `z:A` THEN DISCH_TAC THEN
    SUBGOAL_THEN
     `(E:A->A->bool) z S <=>
      E z B /\ holds D E ((1 |-> (z:A)) val) (euucomb_form 1 3 4 6 7)`
    SUBST1_TAC THENL [ASM_MESON_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN
     `holds D E ((1 |-> (z:A)) val) (euucomb_form 1 3 4 6 7) <=>
      euucomb D E B leq x s z`
    SUBST1_TAC THENL [ASM_MESON_TAC[]; ALL_TAC] THEN
    ASM_MESON_TAC[EUUCOMB_IN];
    ALL_TAC] THEN
  EXISTS_TAC `S:A` THEN REWRITE_TAC[euucombset] THEN CONJ_TAC THENL
   [FIRST_ASSUM ACCEPT_TAC;
    X_GEN_TAC `c:A` THEN DISCH_TAC THEN ASM_MESON_TAC[]]);;

let EUUVAL_EXISTS = prove
 (`!D (E:A->A->bool) B leq x s.
        model D E ZF_AX /\ ecba D E B leq /\
        B IN D /\ leq IN D /\ x IN D /\ s IN D
        ==> ?z. euuval D E B leq x s z`,
  REPEAT STRIP_TAC THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`x:A`;`s:A`]
    EUUCOMBSET_EXISTS) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_TAC `S:A`) THEN
  SUBGOAL_THEN `esubset D (E:A->A->bool) S B` ASSUME_TAC THENL
   [ASM_MESON_TAC[EUUCOMBSET_SUBSET]; ALL_TAC] THEN
  SUBGOAL_THEN `(S:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[euucombset]; ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`S:A`] ECBA_SUP) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_TAC `z:A`) THEN
  EXISTS_TAC `z:A` THEN REWRITE_TAC[euuval] THEN
  EXISTS_TAC `S:A` THEN ASM_REWRITE_TAC[]);;

(* --------------------------------------------------------------------- *)
(* F5 UNION axiom: euucombset and euuval as OBJECT formulas,              *)
(* so the union name can be built internally (ZF replacement) in 2b-ii.   *)
(*   euucombset_form iS ix isv ileq iB  =  "iS names {c : euucomb c}"     *)
(*     = !! N. (N %% iS  <->  euucomb_form N ix isv ileq iB)              *)
(*   euuval_form iz ix isv ileq iB  =  "iz names euuval x s"              *)
(*     = ?? N. (euucombset_form N ix isv ileq iB && elub_form iB ileq N iz)*)
(* Each gets FV = {params} and a HOLDS_* semantic bridge.                 *)
(* --------------------------------------------------------------------- *)

let euucombset_form = new_definition
  `euucombset_form iS ix isv ileq iB =
     !! (MAX iS (MAX ix (MAX isv (MAX ileq iB))) + 1)
        (((MAX iS (MAX ix (MAX isv (MAX ileq iB))) + 1) %% iS) <->
         euucomb_form (MAX iS (MAX ix (MAX isv (MAX ileq iB))) + 1)
           ix isv ileq iB)`;;

let HOLDS_EUUCOMBSET_FORM = prove
 (`!D (E:A->A->bool) v iS ix isv ileq iB.
      model D E ZF_AX /\ valuation D v
      ==> (holds D E v (euucombset_form iS ix isv ileq iB) <=>
           euucombset D E (v iB) (v ileq) (v ix) (v isv) (v iS))`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `!x. (v:num->A) x IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[valuation]; ALL_TAC] THEN
  REWRITE_TAC[euucombset_form] THEN
  ABBREV_TAC `ic = MAX iS (MAX ix (MAX isv (MAX ileq iB))) + 1` THEN
  SUBGOAL_THEN
   `~(iS:num = ic) /\ ~(ix = ic) /\ ~(isv = ic) /\ ~(ileq = ic) /\ ~(iB = ic)`
  STRIP_ASSUME_TAC THENL [EXPAND_TAC "ic" THEN ARITH_TAC; ALL_TAC] THEN
  REWRITE_TAC[euucombset] THEN ASM_REWRITE_TAC[] THEN
  REWRITE_TAC[holds; HOLDS_IFF] THEN
  MATCH_MP_TAC(MESON[]
    `(!a:A. a IN D ==> (P a <=> Q a))
     ==> ((!a. a IN D ==> P a) <=> (!a. a IN D ==> Q a))`) THEN
  X_GEN_TAC `c:A` THEN DISCH_TAC THEN
  SUBGOAL_THEN `valuation D (((ic:num) |-> (c:A)) v)` ASSUME_TAC THENL
   [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`((ic:num) |-> (c:A)) v`;
                `ic:num`;`ix:num`;`isv:num`;`ileq:num`;`iB:num`]
    HOLDS_EUUCOMB_FORM) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  ASM_SIMP_TAC[VALMOD; ARITH_EQ]);;

let euuval_form = new_definition
  `euuval_form iz ix isv ileq iB =
     ?? (MAX iz (MAX ix (MAX isv (MAX ileq iB))) + 1)
        (euucombset_form (MAX iz (MAX ix (MAX isv (MAX ileq iB))) + 1)
           ix isv ileq iB &&
         elub_form iB ileq (MAX iz (MAX ix (MAX isv (MAX ileq iB))) + 1) iz)`;;

let HOLDS_EUUVAL_FORM = prove
 (`!D (E:A->A->bool) v iz ix isv ileq iB.
      model D E ZF_AX /\ valuation D v
      ==> (holds D E v (euuval_form iz ix isv ileq iB) <=>
           euuval D E (v iB) (v ileq) (v ix) (v isv) (v iz))`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `!x. (v:num->A) x IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[valuation]; ALL_TAC] THEN
  REWRITE_TAC[euuval_form; euuval] THEN
  ABBREV_TAC `iSS = MAX iz (MAX ix (MAX isv (MAX ileq iB))) + 1` THEN
  SUBGOAL_THEN
   `~(iz:num = iSS) /\ ~(ix = iSS) /\ ~(isv = iSS) /\ ~(ileq = iSS) /\
    ~(iB = iSS)`
  STRIP_ASSUME_TAC THENL [EXPAND_TAC "iSS" THEN ARITH_TAC; ALL_TAC] THEN
  REWRITE_TAC[HOLDS_EX; HOLDS_AND] THEN
  EQ_TAC THENL
   [DISCH_THEN(X_CHOOSE_THEN `S:A` (CONJUNCTS_THEN2 ASSUME_TAC MP_TAC)) THEN
    SUBGOAL_THEN `valuation D (((iSS:num) |-> (S:A)) v)` ASSUME_TAC THENL
     [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
    MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`((iSS:num) |-> (S:A)) v`;
                  `iSS:num`;`ix:num`;`isv:num`;`ileq:num`;`iB:num`]
      HOLDS_EUUCOMBSET_FORM) THEN
    ASM_REWRITE_TAC[] THEN DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`((iSS:num) |-> (S:A)) v`;
                  `iB:num`;`ileq:num`;`iSS:num`;`iz:num`] HOLDS_ELUB_FORM) THEN
    ASM_REWRITE_TAC[] THEN DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    ASM_SIMP_TAC[VALMOD; ARITH_EQ] THEN STRIP_TAC THEN
    EXISTS_TAC `S:A` THEN ASM_REWRITE_TAC[];
    DISCH_THEN(X_CHOOSE_THEN `S:A` STRIP_ASSUME_TAC) THEN
    EXISTS_TAC `S:A` THEN
    SUBGOAL_THEN `(S:A) IN D` ASSUME_TAC THENL
     [ASM_MESON_TAC[euucombset]; ALL_TAC] THEN
    ASM_REWRITE_TAC[] THEN
    SUBGOAL_THEN `valuation D (((iSS:num) |-> (S:A)) v)` ASSUME_TAC THENL
     [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
    MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`((iSS:num) |-> (S:A)) v`;
                  `iSS:num`;`ix:num`;`isv:num`;`ileq:num`;`iB:num`]
      HOLDS_EUUCOMBSET_FORM) THEN
    ASM_REWRITE_TAC[] THEN DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`((iSS:num) |-> (S:A)) v`;
                  `iB:num`;`ileq:num`;`iSS:num`;`iz:num`] HOLDS_ELUB_FORM) THEN
    ASM_REWRITE_TAC[] THEN DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    ASM_SIMP_TAC[VALMOD; ARITH_EQ]]);;

(* --------------------------------------------------------------------- *)
(* F5 UNION axiom: the union NAME as a functional graph.                  *)
(*   un = { <s, euuval(x,s)> : s IN W }  built by ZF replacement along     *)
(*   the object formula  ?? 1 (euuval_form 1 4 0 6 7 && opair_form 0 1 3), *)
(*   input s = var 0 (over a = W), output pair = var 3, value = var 1,     *)
(*   params x = var 4, leq = var 6, B = var 7.  Mirrors EBNRANK_GRAPH.     *)
(* --------------------------------------------------------------------- *)

let EUNIONNAME_EXISTS = prove
 (`!D (E:A->A->bool) B leq x W.
        model D E ZF_AX /\ ecba D E B leq /\
        B IN D /\ leq IN D /\ x IN D /\ W IN D
        ==> ?un. un IN D /\ eisfun D E un /\ edomain D E un W /\
                 (!s q. s IN D /\ E s W /\ euuval D E B leq x s q
                        ==> eapply D E un s q) /\
                 (!z. z IN D
                      ==> (E z un <=>
                           ?s q. s IN D /\ q IN D /\ E s W /\
                                 euuval D E B leq x s q /\
                                 eopair D (E:A->A->bool) s q z))`,
  REPEAT GEN_TAC THEN
  STRIP_TAC THEN
  SUBGOAL_THEN `?v0:num->A. valuation D v0` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[VALUATION_EXISTS; MODEL_NONEMPTY]; ALL_TAC] THEN
  ABBREV_TAC `vP = (4 |-> (x:A)) ((6 |-> (leq:A)) ((7 |-> (B:A)) v0))` THEN
  SUBGOAL_THEN
   `valuation D (vP:num->A) /\
    (vP:num->A) 4 = x /\ (vP:num->A) 6 = leq /\ (vP:num->A) 7 = B`
  STRIP_ASSUME_TAC THENL
   [EXPAND_TAC "vP" THEN
    ASM_SIMP_TAC[VALUATION_VALMOD; VALMOD; ARITH_EQ]; ALL_TAC] THEN
  SUBGOAL_THEN
   `!el ot:A. el IN D /\ ot IN D
      ==> (holds D E ((3 |-> ot) ((0 |-> el) vP))
             (?? 1 (euuval_form 1 4 0 6 7 && opair_form 0 1 3)) <=>
           ?q. q IN D /\ euuval D E B leq x el q /\
               eopair D (E:A->A->bool) el q ot)`
  (LABEL_TAC "hrk") THENL
   [REPEAT GEN_TAC THEN STRIP_TAC THEN
    REWRITE_TAC[HOLDS_EX; HOLDS_AND] THEN
    MATCH_MP_TAC(MESON[]
     `(!q:A. P q <=> Q q) ==> ((?q:A. P q) <=> (?q:A. Q q))`) THEN
    X_GEN_TAC `q:A` THEN
    MATCH_MP_TAC(TAUT `(a ==> (p <=> q)) ==> ((a /\ p) <=> (a /\ q))`) THEN
    DISCH_TAC THEN
    SUBGOAL_THEN
     `valuation D ((1 |-> (q:A)) ((3 |-> (ot:A)) ((0 |-> (el:A)) vP)))`
    ASSUME_TAC THENL
     [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
      `(1 |-> (q:A)) ((3 |-> (ot:A)) ((0 |-> (el:A)) vP))`;
      `1`; `4`; `0`; `6`; `7`] HOLDS_EUUVAL_FORM) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
      `(1 |-> (q:A)) ((3 |-> (ot:A)) ((0 |-> (el:A)) vP))`;
      `0`; `1`; `3`] HOLDS_OPAIR_FORM) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    ASM_REWRITE_TAC[VALMOD; ARITH_EQ];
    ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`] ZF_REPLACEMENT) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(MP_TAC o SPECL
    [`?? 1 (euuval_form 1 4 0 6 7 && opair_form 0 1 3)`;
     `0`; `3`; `vP:num->A`; `W:A`]) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[ARITH_EQ] THEN
    X_GEN_TAC `u:A` THEN STRIP_TAC THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `B:A`; `leq:A`; `x:A`; `u:A`]
      EUUVAL_EXISTS) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(X_CHOOSE_THEN `q:A` STRIP_ASSUME_TAC) THEN
    SUBGOAL_THEN `(q:A) IN D` ASSUME_TAC THENL
     [ASM_MESON_TAC[EUUVAL_IN]; ALL_TAC] THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `u:A`; `q:A`]
      EOPAIR_EXISTS) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(X_CHOOSE_TAC `pv:A`) THEN
    SUBGOAL_THEN `(pv:A) IN D` ASSUME_TAC THENL
     [ASM_MESON_TAC[EOPAIR_IN]; ALL_TAC] THEN
    EXISTS_TAC `pv:A` THEN ASM_REWRITE_TAC[] THEN
    X_GEN_TAC `w':A` THEN
    DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC MP_TAC) THEN
    USE_THEN "hrk" (MP_TAC o SPECL [`u:A`; `w':A`]) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    DISCH_THEN(X_CHOOSE_THEN `q':A` STRIP_ASSUME_TAC) THEN
    SUBGOAL_THEN `(q':A) = q` SUBST_ALL_TAC THENL
     [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `B:A`; `leq:A`; `x:A`;
        `u:A`; `q':A`; `q:A`] EUUVAL_UNIQUE) THEN ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `u:A`; `q:A`; `w':A`; `pv:A`]
      EOPAIR_UNIQUE) THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `un:A` (CONJUNCTS_THEN2 ASSUME_TAC
    (LABEL_TAC "raw"))) THEN
  SUBGOAL_THEN
   `!z. z IN D
        ==> (E z un <=>
             ?s q. s IN D /\ q IN D /\ E s W /\
                   euuval D E B leq x s q /\
                   eopair D (E:A->A->bool) s q z)`
  (LABEL_TAC "UNc") THENL
   [X_GEN_TAC `z:A` THEN DISCH_TAC THEN
    USE_THEN "raw" (MP_TAC o SPEC `z:A`) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    EQ_TAC THENL
     [DISCH_THEN(X_CHOOSE_THEN `s:A` (CONJUNCTS_THEN2 ASSUME_TAC
        (CONJUNCTS_THEN2 ASSUME_TAC MP_TAC))) THEN
      USE_THEN "hrk" (MP_TAC o SPECL [`s:A`; `z:A`]) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
      DISCH_THEN(X_CHOOSE_THEN `q:A` STRIP_ASSUME_TAC) THEN
      MAP_EVERY EXISTS_TAC [`s:A`; `q:A`] THEN ASM_REWRITE_TAC[];
      DISCH_THEN(X_CHOOSE_THEN `s:A` (X_CHOOSE_THEN `q:A`
        STRIP_ASSUME_TAC)) THEN
      EXISTS_TAC `s:A` THEN ASM_REWRITE_TAC[] THEN
      USE_THEN "hrk" (MP_TAC o SPECL [`s:A`; `z:A`]) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
      EXISTS_TAC `q:A` THEN ASM_REWRITE_TAC[]];
    ALL_TAC] THEN
  EXISTS_TAC `un:A` THEN REPEAT CONJ_TAC THENL
   [FIRST_ASSUM ACCEPT_TAC;
    REWRITE_TAC[eisfun] THEN REPEAT CONJ_TAC THENL
     [FIRST_ASSUM ACCEPT_TAC;
      X_GEN_TAC `z:A` THEN STRIP_TAC THEN
      SUBGOAL_THEN
       `?s q. s IN D /\ q IN D /\ E s W /\ euuval D E B leq x s q /\
              eopair D (E:A->A->bool) s q z`
      STRIP_ASSUME_TAC THENL [ASM_MESON_TAC[]; ALL_TAC] THEN
      MAP_EVERY EXISTS_TAC [`s:A`; `q:A`] THEN ASM_REWRITE_TAC[];
      REPEAT GEN_TAC THEN STRIP_TAC THEN
      SUBGOAL_THEN `(z:A) IN D /\ (z':A) IN D` STRIP_ASSUME_TAC THENL
       [ASM_MESON_TAC[EOPAIR_IN]; ALL_TAC] THEN
      SUBGOAL_THEN
       `?s1 q1. s1 IN D /\ q1 IN D /\ E s1 W /\ euuval D E B leq x s1 q1 /\
                eopair D (E:A->A->bool) s1 q1 z`
      STRIP_ASSUME_TAC THENL [ASM_MESON_TAC[]; ALL_TAC] THEN
      SUBGOAL_THEN
       `?s2 q2. s2 IN D /\ q2 IN D /\ E s2 W /\ euuval D E B leq x s2 q2 /\
                eopair D (E:A->A->bool) s2 q2 z'`
      STRIP_ASSUME_TAC THENL [ASM_MESON_TAC[]; ALL_TAC] THEN
      SUBGOAL_THEN `(u:A) = s1 /\ (w:A) = q1` STRIP_ASSUME_TAC THENL
       [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `u:A`; `w:A`;
          `s1:A`; `q1:A`; `z:A`] EOPAIR_INJ) THEN ASM_REWRITE_TAC[];
        ALL_TAC] THEN
      SUBGOAL_THEN `(u:A) = s2 /\ (w':A) = q2` STRIP_ASSUME_TAC THENL
       [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `u:A`; `w':A`;
          `s2:A`; `q2:A`; `z':A`] EOPAIR_INJ) THEN ASM_REWRITE_TAC[];
        ALL_TAC] THEN
      SUBGOAL_THEN `(s2:A) = s1` ASSUME_TAC THENL
       [ASM_MESON_TAC[]; ALL_TAC] THEN
      MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `B:A`; `leq:A`; `x:A`;
        `s1:A`; `q1:A`; `q2:A`] EUUVAL_UNIQUE) THEN
      ANTS_TAC THENL [ASM_MESON_TAC[]; ASM_MESON_TAC[]]];
    REWRITE_TAC[edomain] THEN CONJ_TAC THENL
     [FIRST_ASSUM ACCEPT_TAC;
      X_GEN_TAC `u:A` THEN DISCH_TAC THEN REWRITE_TAC[eindom] THEN
      EQ_TAC THENL
       [DISCH_TAC THEN
        MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `B:A`; `leq:A`; `x:A`;
          `u:A`] EUUVAL_EXISTS) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
        DISCH_THEN(X_CHOOSE_THEN `q:A` STRIP_ASSUME_TAC) THEN
        SUBGOAL_THEN `(q:A) IN D` ASSUME_TAC THENL
         [ASM_MESON_TAC[EUUVAL_IN]; ALL_TAC] THEN
        MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `u:A`; `q:A`]
          EOPAIR_EXISTS) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
        DISCH_THEN(X_CHOOSE_TAC `zz:A`) THEN
        SUBGOAL_THEN `(zz:A) IN D` ASSUME_TAC THENL
         [ASM_MESON_TAC[EOPAIR_IN]; ALL_TAC] THEN
        EXISTS_TAC `q:A` THEN CONJ_TAC THENL
         [FIRST_ASSUM ACCEPT_TAC;
          REWRITE_TAC[eapply] THEN EXISTS_TAC `zz:A` THEN CONJ_TAC THENL
           [FIRST_ASSUM ACCEPT_TAC; ASM_MESON_TAC[]]];
        DISCH_THEN(X_CHOOSE_THEN `wv:A` (CONJUNCTS_THEN2 ASSUME_TAC
          MP_TAC)) THEN
        REWRITE_TAC[eapply] THEN
        DISCH_THEN(X_CHOOSE_THEN `zz:A` STRIP_ASSUME_TAC) THEN
        SUBGOAL_THEN `(zz:A) IN D` ASSUME_TAC THENL
         [ASM_MESON_TAC[EOPAIR_IN]; ALL_TAC] THEN
        SUBGOAL_THEN
         `?s1 q1. s1 IN D /\ q1 IN D /\ E s1 W /\ euuval D E B leq x s1 q1 /\
                  eopair D (E:A->A->bool) s1 q1 zz`
        STRIP_ASSUME_TAC THENL [ASM_MESON_TAC[]; ALL_TAC] THEN
        SUBGOAL_THEN `(u:A) = s1` ASSUME_TAC THENL
         [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `u:A`; `wv:A`;
            `s1:A`; `q1:A`; `zz:A`] EOPAIR_INJ) THEN ASM_MESON_TAC[];
          ALL_TAC] THEN
        ASM_MESON_TAC[]]];
    REPEAT GEN_TAC THEN STRIP_TAC THEN
    SUBGOAL_THEN `(q:A) IN D` ASSUME_TAC THENL
     [ASM_MESON_TAC[EUUVAL_IN]; ALL_TAC] THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `s:A`; `q:A`]
      EOPAIR_EXISTS) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(X_CHOOSE_TAC `zz:A`) THEN
    SUBGOAL_THEN `(zz:A) IN D` ASSUME_TAC THENL
     [ASM_MESON_TAC[EOPAIR_IN]; ALL_TAC] THEN
    REWRITE_TAC[eapply] THEN EXISTS_TAC `zz:A` THEN CONJ_TAC THENL
     [FIRST_ASSUM ACCEPT_TAC; ASM_MESON_TAC[]];
    USE_THEN "UNc" ACCEPT_TAC]);;

(* ===================================================================== *)
(* F5 UNION axiom: bounded-existential value = supremum.                  *)
(*                                                                         *)
(* The Boolean value of a (meta-level) existential  ?? n p  is the least  *)
(* upper bound, in the algebra B, of the disjunct values                  *)
(*   { [[p]]_{(n|->a)v} : a a bname of D } .                              *)
(* BVALF_EX_UB gives the upper-bound half (each disjunct value <= the      *)
(* existential value); BVALF_EX_LEAST gives the least-upper-bound half     *)
(* (anything in B dominating every disjunct value dominates the           *)
(* existential value).  Both go through  ?? n p = Not(!! n (Not p))  and   *)
(* the fact that the universal's value is the glb of the {[[Not p]]}, with *)
(* ECOMPL_ANTITONE turning glb<->lub.  These are the reusable engine for   *)
(* the union-axiom equality (lemma 3), separation, and later Los.          *)
(* ===================================================================== *)

let BVALF_EX_UB = prove
 (`!n p D (E:A->A->bool) B leq v a.
      model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
      valuation D v /\ (!i. bname D E B (v i)) /\ a IN D /\ bname D E B a
      ==> erel D E leq (bvalf D E B leq ((n |-> a) v) p)
                       (bvalf D E B leq v (?? n p))`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `ebalg D (E:A->A->bool) B leq` ASSUME_TAC THENL
   [ASM_MESON_TAC[ECBA_IMP_BALG]; ALL_TAC] THEN
  SUBGOAL_THEN `eporder D (E:A->A->bool) B leq` ASSUME_TAC THENL
   [ASM_MESON_TAC[EBALG_IMP_PORDER]; ALL_TAC] THEN
  SUBGOAL_THEN `valuation D ((n |-> (a:A)) (v:num->A)) /\
                (!i. bname D E B (((n |-> (a:A)) (v:num->A)) i))`
  STRIP_ASSUME_TAC THENL
   [CONJ_TAC THENL
     [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[];
      MATCH_MP_TAC BNAMEVAL_VALMOD THEN ASM_REWRITE_TAC[]]; ALL_TAC] THEN
  REWRITE_TAC[Exists_DEF] THEN
  MP_TAC(ISPECL [`p:form`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
    `(n |-> (a:A)) (v:num->A)`] BVALF_NOT) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN DISCH_TAC THEN
  MP_TAC(ISPECL
         [`!! n (Not p)`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`v:num->A`]
         BVALF_NOT) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN DISCH_TAC THEN
  ABBREV_TAC
    `pa = bvalf D (E:A->A->bool) B leq ((n |-> (a:A)) (v:num->A)) p` THEN
  ABBREV_TAC
    `npa = bvalf D (E:A->A->bool) B leq ((n |-> (a:A)) (v:num->A))
     (Not p)` THEN
  ABBREV_TAC
    `glb = bvalf D (E:A->A->bool) B leq (v:num->A) (!! n (Not p))` THEN
  ABBREV_TAC
    `cc = bvalf D (E:A->A->bool) B leq (v:num->A) (Not(!! n (Not p)))` THEN
  SUBGOAL_THEN `(pa:A) IN D /\ (E:A->A->bool) pa B` STRIP_ASSUME_TAC THENL
   [EXPAND_TAC "pa" THEN CONJ_TAC THENL
     [MP_TAC(ISPECL
             [`p:form`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
              `(n |-> (a:A)) (v:num->A)`] BVALF_SPEC) THEN ASM_SIMP_TAC[];
      MP_TAC(ISPECL
             [`p:form`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
              `(n |-> (a:A)) (v:num->A)`] BVALF_IN_B) THEN ASM_SIMP_TAC[]];
     ALL_TAC] THEN
  SUBGOAL_THEN `(npa:A) IN D /\ (E:A->A->bool) npa B` STRIP_ASSUME_TAC THENL
   [EXPAND_TAC "npa" THEN CONJ_TAC THENL
     [MP_TAC(ISPECL
             [`Not p`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
              `(n |-> (a:A)) (v:num->A)`] BVALF_SPEC) THEN ASM_SIMP_TAC[];
      MP_TAC(ISPECL
             [`Not p`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
              `(n |-> (a:A)) (v:num->A)`] BVALF_IN_B) THEN ASM_SIMP_TAC[]];
     ALL_TAC] THEN
  SUBGOAL_THEN `(glb:A) IN D /\ (E:A->A->bool) glb B` STRIP_ASSUME_TAC THENL
   [EXPAND_TAC "glb" THEN CONJ_TAC THENL
     [MP_TAC(ISPECL
             [`!! n (Not p)`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
              `v:num->A`] BVALF_SPEC) THEN ASM_SIMP_TAC[];
      MP_TAC(ISPECL
             [`!! n (Not p)`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
              `v:num->A`] BVALF_IN_B) THEN ASM_SIMP_TAC[]]; ALL_TAC] THEN
  SUBGOAL_THEN `(cc:A) IN D /\ (E:A->A->bool) cc B` STRIP_ASSUME_TAC THENL
   [EXPAND_TAC "cc" THEN CONJ_TAC THENL
     [MP_TAC(ISPECL
             [`Not(!! n (Not p))`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
              `v:num->A`] BVALF_SPEC) THEN ASM_SIMP_TAC[];
      MP_TAC(ISPECL
             [`Not(!! n (Not p))`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
              `v:num->A`] BVALF_IN_B) THEN ASM_SIMP_TAC[]]; ALL_TAC] THEN
  SUBGOAL_THEN `ecompl D (E:A->A->bool) B leq npa pa` ASSUME_TAC THENL
   [MATCH_MP_TAC ECOMPL_SYM THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq glb npa` ASSUME_TAC THENL
   [MAP_EVERY EXPAND_TAC ["glb";"npa"] THEN
    MP_TAC(ISPECL
           [`n:num`;`Not p`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
            `v:num->A`;`a:A`]
           BVALF_ALL_LB) THEN ASM_SIMP_TAC[]; ALL_TAC] THEN
  MP_TAC(ISPECL
         [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`glb:A`;`npa:A`;
          `cc:A`;`pa:A`]
         ECOMPL_ANTITONE) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC]);;

let BVALF_EX_LEAST = prove
 (`!n p D (E:A->A->bool) B leq v w0.
      model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
      valuation D v /\ (!i. bname D E B (v i)) /\
      w0 IN D /\ E w0 B /\
      (!a. a IN D /\ bname D E B a
           ==> erel D E leq (bvalf D E B leq ((n |-> a) v) p) w0)
      ==> erel D E leq (bvalf D E B leq v (?? n p)) w0`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `ebalg D (E:A->A->bool) B leq` ASSUME_TAC THENL
   [ASM_MESON_TAC[ECBA_IMP_BALG]; ALL_TAC] THEN
  SUBGOAL_THEN `eporder D (E:A->A->bool) B leq` ASSUME_TAC THENL
   [ASM_MESON_TAC[EBALG_IMP_PORDER]; ALL_TAC] THEN
  REWRITE_TAC[Exists_DEF] THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`w0:A`]
         EBALG_COMPL) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_TAC `cw0:A`) THEN
  SUBGOAL_THEN `(cw0:A) IN D /\ (E:A->A->bool) cw0 B` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[ECOMPL_IN]; ALL_TAC] THEN
  MP_TAC(ISPECL
         [`!! n (Not p)`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`v:num->A`]
         BVALF_NOT) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN DISCH_TAC THEN
  SUBGOAL_THEN `(bvalf D (E:A->A->bool) B leq v (!! n (Not p))) IN D /\
                (E:A->A->bool) (bvalf D E B leq v (!! n (Not p))) B`
  STRIP_ASSUME_TAC THENL
   [CONJ_TAC THENL
     [MP_TAC(ISPECL
             [`!! n (Not p)`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
              `v:num->A`] BVALF_SPEC) THEN ASM_SIMP_TAC[];
      MP_TAC(ISPECL
             [`!! n (Not p)`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
              `v:num->A`] BVALF_IN_B) THEN ASM_SIMP_TAC[]]; ALL_TAC] THEN
  SUBGOAL_THEN `(bvalf D (E:A->A->bool) B leq v (Not(!! n (Not p)))) IN D /\
                (E:A->A->bool) (bvalf D E B leq v (Not(!! n (Not p)))) B`
  STRIP_ASSUME_TAC THENL
   [CONJ_TAC THENL
     [MP_TAC(ISPECL
             [`Not(!! n (Not p))`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
              `v:num->A`] BVALF_SPEC) THEN ASM_SIMP_TAC[];
      MP_TAC(ISPECL
             [`Not(!! n (Not p))`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
              `v:num->A`] BVALF_IN_B) THEN ASM_SIMP_TAC[]]; ALL_TAC] THEN
  MP_TAC(ISPECL
         [`!! n (Not p)`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`v:num->A`]
         BVALF_SPEC) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(MP_TAC o CONJUNCT2) THEN REWRITE_TAC[bval] THEN
  DISCH_THEN(X_CHOOSE_THEN `S:A` (CONJUNCTS_THEN2 ASSUME_TAC
    (CONJUNCTS_THEN2 (LABEL_TAC "Schar") ASSUME_TAC))) THEN
  SUBGOAL_THEN `elbound D (E:A->A->bool) B leq S cw0` ASSUME_TAC THENL
   [REWRITE_TAC[elbound] THEN ASM_REWRITE_TAC[] THEN
    X_GEN_TAC `zz:A` THEN STRIP_TAC THEN
    SUBGOAL_THEN `?a:A. a IN D /\ bname D (E:A->A->bool) B a /\
                        bval D E B leq ((n |-> a) v) (Not p) zz`
    (X_CHOOSE_THEN `a:A` STRIP_ASSUME_TAC) THENL
     [USE_THEN "Schar" (MP_TAC o SPEC `zz:A`) THEN
      ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[GSYM th]) THEN FIRST_ASSUM ACCEPT_TAC;
      ALL_TAC] THEN
    SUBGOAL_THEN `valuation D ((n |-> (a:A)) (v:num->A)) /\
                  (!i. bname D E B (((n |-> (a:A)) (v:num->A)) i))`
    STRIP_ASSUME_TAC THENL
     [CONJ_TAC THENL
       [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[];
        MATCH_MP_TAC BNAMEVAL_VALMOD THEN ASM_REWRITE_TAC[]]; ALL_TAC] THEN
    SUBGOAL_THEN
      `zz:A = bvalf D (E:A->A->bool) B leq ((n |-> (a:A)) (v:num->A)) (Not p)`
      SUBST_ALL_TAC THENL
     [MATCH_MP_TAC BVALF_EQ THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    MP_TAC(ISPECL [`p:form`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
      `(n |-> (a:A)) (v:num->A)`] BVALF_NOT) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN DISCH_TAC THEN
    SUBGOAL_THEN
      `(bvalf D (E:A->A->bool) B leq ((n |-> (a:A)) (v:num->A)) p) IN D /\
       (E:A->A->bool) (bvalf D E B leq ((n |-> (a:A)) (v:num->A)) p) B`
    STRIP_ASSUME_TAC THENL
     [CONJ_TAC THENL
       [MP_TAC(ISPECL
               [`p:form`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
                `(n |-> (a:A)) (v:num->A)`] BVALF_SPEC) THEN ASM_SIMP_TAC[];
        MP_TAC(ISPECL
               [`p:form`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
                `(n |-> (a:A)) (v:num->A)`] BVALF_IN_B) THEN ASM_SIMP_TAC[]];
       ALL_TAC] THEN
    SUBGOAL_THEN `erel D (E:A->A->bool) leq
        (bvalf D E B leq ((n |-> (a:A)) (v:num->A)) p) w0` ASSUME_TAC THENL
     [FIRST_X_ASSUM MATCH_MP_TAC THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
      `bvalf D (E:A->A->bool) B leq ((n |-> (a:A)) (v:num->A)) p`;`w0:A`;
      `bvalf D (E:A->A->bool) B leq ((n |-> (a:A)) (v:num->A))
       (Not p)`;`cw0:A`]
      ECOMPL_ANTITONE) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC];
    ALL_TAC] THEN
  SUBGOAL_THEN
    `erel D (E:A->A->bool) leq cw0 (bvalf D E B leq v (!! n (Not p)))`
  ASSUME_TAC THENL
   [MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`S:A`;
      `bvalf D (E:A->A->bool) B leq v (!! n (Not p))`;`cw0:A`]
        EGLB_GREATEST) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `ecompl D (E:A->A->bool) B leq cw0 w0` ASSUME_TAC THENL
   [MATCH_MP_TAC ECOMPL_SYM THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
    `cw0:A`;`bvalf D (E:A->A->bool) B leq v (!! n (Not p))`;`w0:A`;
    `bvalf D (E:A->A->bool) B leq v (Not(!! n (Not p)))`] ECOMPL_ANTITONE) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC]);;

(* ===================================================================== *)
(* F5 UNION axiom -- lemma-3 prerequisites (helpers, all proved separately *)
(* and cold-verified as a group before lemma 3 EBV_IN_UNION).             *)
(* ===================================================================== *)

(* --------------------------------------------------------------------- *)
(* euuval as least upper bound of the union-combiner set (twins of        *)
(* EBVIN_UB / EBVIN_LEAST).  EUUVAL_UB: each combiner x(w) MEET w(s) is    *)
(* <= the union value un(s); EUUVAL_LEAST: un(s) is the least such bound.  *)
(* These package euuval = SUP_{w in dom x} (x(w) MEET w(s)) for lemma 3.   *)
(* --------------------------------------------------------------------- *)

let EUUVAL_UB = prove
 (`!D (E:A->A->bool) B leq x s z c.
      euuval D E B leq x s z /\ euucomb D E B leq x s c
      ==> erel D E leq c z`,
  REPEAT GEN_TAC THEN REWRITE_TAC[euuval] THEN STRIP_TAC THEN
  SUBGOAL_THEN `(c:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[EUUCOMB_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) c S` ASSUME_TAC THENL
   [FIRST_X_ASSUM(MP_TAC o SPEC `c:A` o CONJUNCT2 o
                  REWRITE_RULE[euucombset]) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`S:A`;`z:A`;`c:A`]
    ELUB_UB) THEN ASM_REWRITE_TAC[]);;

let EUUVAL_LEAST = prove
 (`!D (E:A->A->bool) B leq x s z w.
      euuval D E B leq x s z /\ w IN D /\ E w B /\
      (!c. euucomb D E B leq x s c ==> erel D E leq c w)
      ==> erel D E leq z w`,
  REPEAT GEN_TAC THEN REWRITE_TAC[euuval] THEN STRIP_TAC THEN
  SUBGOAL_THEN `eubound D (E:A->A->bool) B leq S w` ASSUME_TAC THENL
   [REWRITE_TAC[eubound] THEN ASM_REWRITE_TAC[] THEN
    X_GEN_TAC `xx:A` THEN STRIP_TAC THEN
    SUBGOAL_THEN `euucomb D (E:A->A->bool) B leq x s xx` ASSUME_TAC THENL
     [FIRST_X_ASSUM(MP_TAC o SPEC `xx:A` o CONJUNCT2 o
                    REWRITE_RULE[euucombset]) THEN
      ASM_REWRITE_TAC[]; ALL_TAC] THEN
    FIRST_X_ASSUM MATCH_MP_TAC THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`S:A`;`z:A`;`w:A`]
    ELUB_LEAST) THEN ASM_REWRITE_TAC[]);;

(* --------------------------------------------------------------------- *)
(* F5: the Boolean value of a conjunction formula is the MEET of the two  *)
(* values.  [[p && q]] = [[p]] MEET [[q]].  (p && q = Not(p --> Not q), so *)
(* [[p&&q]] = compl(join(compl[[p]], compl[[q]])) = meet.)  Needed by the  *)
(* union axiom (lemma 3): decomposes [[(w%%x) && (z%%w)]] into the meet.   *)
(* --------------------------------------------------------------------- *)

let BVALF_AND_MEET = prove
 (`!p q D (E:A->A->bool) B leq v.
      model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
      valuation D v /\ (!i. bname D E B (v i))
      ==> emeet D E B leq (bvalf D E B leq v p) (bvalf D E B leq v q)
                          (bvalf D E B leq v (p && q))`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `ebalg D (E:A->A->bool) B leq` ASSUME_TAC THENL
   [ASM_MESON_TAC[ECBA_IMP_BALG]; ALL_TAC] THEN
  SUBGOAL_THEN `eporder D (E:A->A->bool) B leq` ASSUME_TAC THENL
   [ASM_MESON_TAC[EBALG_IMP_PORDER]; ALL_TAC] THEN
  SUBGOAL_THEN `(bvalf D (E:A->A->bool) B leq v p) IN D /\
                (E:A->A->bool) (bvalf D E B leq v p) B`
  STRIP_ASSUME_TAC THENL
   [CONJ_TAC THENL
     [MP_TAC(ISPECL
             [`p:form`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`v:num->A`]
             BVALF_SPEC) THEN ASM_SIMP_TAC[];
      MP_TAC(ISPECL
             [`p:form`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`v:num->A`]
             BVALF_IN_B) THEN ASM_SIMP_TAC[]]; ALL_TAC] THEN
  SUBGOAL_THEN `(bvalf D (E:A->A->bool) B leq v q) IN D /\
                (E:A->A->bool) (bvalf D E B leq v q) B`
  STRIP_ASSUME_TAC THENL
   [CONJ_TAC THENL
     [MP_TAC(ISPECL
             [`q:form`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`v:num->A`]
             BVALF_SPEC) THEN ASM_SIMP_TAC[];
      MP_TAC(ISPECL
             [`q:form`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`v:num->A`]
             BVALF_IN_B) THEN ASM_SIMP_TAC[]]; ALL_TAC] THEN
  SUBGOAL_THEN `(bvalf D (E:A->A->bool) B leq v (p && q)) IN D /\
                (E:A->A->bool) (bvalf D E B leq v (p && q)) B`
  STRIP_ASSUME_TAC THENL
   [CONJ_TAC THENL
     [MP_TAC(ISPECL
             [`p && q`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`v:num->A`]
             BVALF_SPEC) THEN ASM_SIMP_TAC[];
      MP_TAC(ISPECL
             [`p && q`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`v:num->A`]
             BVALF_IN_B) THEN ASM_SIMP_TAC[]]; ALL_TAC] THEN
  SUBGOAL_THEN `(bvalf D (E:A->A->bool) B leq v (p --> Not q)) IN D /\
                (E:A->A->bool) (bvalf D E B leq v (p --> Not q)) B`
  STRIP_ASSUME_TAC THENL
   [CONJ_TAC THENL
     [MP_TAC(ISPECL
             [`p --> Not q`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
              `v:num->A`] BVALF_SPEC) THEN ASM_SIMP_TAC[];
      MP_TAC(ISPECL
             [`p --> Not q`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
              `v:num->A`] BVALF_IN_B) THEN ASM_SIMP_TAC[]]; ALL_TAC] THEN
  SUBGOAL_THEN
    `erel D (E:A->A->bool) leq (bvalf D E B leq v (p && q))
     (bvalf D E B leq v p)` ASSUME_TAC THENL
   [MATCH_MP_TAC BVALF_AND_LE_L THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN
    `erel D (E:A->A->bool) leq (bvalf D E B leq v (p && q))
     (bvalf D E B leq v q)` ASSUME_TAC THENL
   [MATCH_MP_TAC BVALF_AND_LE_R THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN
    `ecompl D (E:A->A->bool) B leq (bvalf D E B leq v q)
     (bvalf D E B leq v (Not q))` ASSUME_TAC THENL
   [MATCH_MP_TAC BVALF_NOT THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN
    `ecompl D (E:A->A->bool) B leq (bvalf D E B leq v (p --> Not q))
     (bvalf D E B leq v (Not(p --> Not q)))` ASSUME_TAC THENL
   [MATCH_MP_TAC BVALF_NOT THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MP_TAC(ISPECL
         [`p:form`;`Not q`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`v:num->A`]
         BVALF_IMP) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  REWRITE_TAC[ebimp] THEN
  DISCH_THEN(X_CHOOSE_THEN `c:A` STRIP_ASSUME_TAC) THEN
  REWRITE_TAC[emeet] THEN ASM_REWRITE_TAC[] THEN
  X_GEN_TAC `w:A` THEN STRIP_TAC THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`w:A`]
         EBALG_COMPL) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `cw:A`) THEN
  SUBGOAL_THEN `(cw:A) IN D /\ (E:A->A->bool) cw B` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[ECOMPL_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq c cw` ASSUME_TAC THENL
   [MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`w:A`;
      `bvalf D (E:A->A->bool) B leq v p`;`cw:A`;`c:A`] ECOMPL_ANTITONE) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq (bvalf D E B leq v (Not q)) cw`
    ASSUME_TAC THENL
   [MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`w:A`;
      `bvalf D (E:A->A->bool) B leq v q`;`cw:A`;
      `bvalf D (E:A->A->bool) B leq v (Not q)`] ECOMPL_ANTITONE) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq (bvalf D E B leq v (p --> Not q)) cw`
    ASSUME_TAC THENL
   [MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`c:A`;
      `bvalf D (E:A->A->bool) B leq v (Not q)`;
      `bvalf D (E:A->A->bool) B leq v (p --> Not q)`;`cw:A`] EJOIN_LEAST) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `ecompl D (E:A->A->bool) B leq cw w` ASSUME_TAC THENL
   [MATCH_MP_TAC ECOMPL_SYM THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `bvalf D (E:A->A->bool) B leq v (p && q) =
                bvalf D E B leq v (Not(p --> Not q))`
  (fun th -> REWRITE_TAC[th]) THENL [REWRITE_TAC[And_DEF]; ALL_TAC] THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
    `bvalf D (E:A->A->bool) B leq v (p --> Not q)`;`cw:A`;
    `bvalf D (E:A->A->bool) B leq v (Not(p --> Not q))`;`w:A`]
                  ECOMPL_ANTITONE) THEN
  ASM_REWRITE_TAC[]);;

(* --------------------------------------------------------------------- *)
(* The union NAME is a B-name.  For a B-name x, the union-name un has      *)
(* domain W = U{dom w : w in dom x}.  Since x sits in a stage yx          *)
(* (bname x), STAGE_DOM_CLOSED applied twice puts all of W inside yx;      *)
(* un's values are Boolean (E q B, EUUVAL_IN), so un SUBSET ecross yx B,   *)
(* hence un is a B-name at the successor stage (ebnmem/ebnfuns), exactly   *)
(* as EUPAIRNAME_EXISTS builds bname up.  Feeds EBV_IN_UNION (lemma 3).    *)
(* --------------------------------------------------------------------- *)

let EUNIONNAME_BNAME = prove
 (`!D (E:A->A->bool) B leq x W un.
      model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
      x IN D /\ bname D E B x /\ W IN D /\
      (!t. t IN D
           ==> (E t W <=> ?w. w IN D /\ eindom D E x w /\ eindom D E w t)) /\
      un IN D /\ eisfun D E un /\
      (!z. z IN D
           ==> (E z un <=>
                ?s q. s IN D /\ q IN D /\ E s W /\
                      euuval D E B leq x s q /\ eopair D (E:A->A->bool) s q z))
      ==> bname D E B un`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "modl ecba BD leqD xD bnx WD Wch unD isf unch" THEN
  USE_THEN "bnx"
    (X_CHOOSE_THEN `ax:A` (X_CHOOSE_THEN `yx:A` STRIP_ASSUME_TAC) o
     REWRITE_RULE[bname]) THEN
  SUBGOAL_THEN `!s:A. s IN D /\ (E:A->A->bool) s W ==> E s yx`
    (LABEL_TAC "Wsub") THENL
   [X_GEN_TAC `s:A` THEN STRIP_TAC THEN
    SUBGOAL_THEN `?w. w IN D /\ eindom D (E:A->A->bool) x w /\ eindom D E w s`
    STRIP_ASSUME_TAC THENL
     [USE_THEN "Wch" (MP_TAC o SPEC `s:A`) THEN
      ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[GSYM th]) THEN FIRST_ASSUM ACCEPT_TAC;
      ALL_TAC] THEN
    UNDISCH_TAC `eindom D (E:A->A->bool) x w` THEN REWRITE_TAC[eindom] THEN
    DISCH_THEN(X_CHOOSE_THEN `qw:A` STRIP_ASSUME_TAC) THEN
    UNDISCH_TAC `eindom D (E:A->A->bool) w s` THEN REWRITE_TAC[eindom] THEN
    DISCH_THEN(X_CHOOSE_THEN `qs:A` STRIP_ASSUME_TAC) THEN
    SUBGOAL_THEN `(E:A->A->bool) w yx` ASSUME_TAC THENL
     [MATCH_MP_TAC(ISPECL
                   [`D:A->bool`;`E:A->A->bool`;`B:A`;`ax:A`;`yx:A`;`x:A`;
                    `w:A`;`qw:A`] STAGE_DOM_CLOSED) THEN ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`ax:A`;`yx:A`;`w:A`;
      `s:A`;`qs:A`] STAGE_DOM_CLOSED) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`ax:A`] ESUC_EXISTS) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `sa:A`) THEN
  SUBGOAL_THEN
    `(sa:A) IN D /\ eordinal D (E:A->A->bool) sa /\ (E:A->A->bool) ax sa`
  STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[ESUC_IN; EORDINAL_ESUC; ESUC_MEMBER]; ALL_TAC] THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`sa:A`] EBNSTAGE_EXISTS) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `ysa:A` STRIP_ASSUME_TAC) THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`sa:A`;`ysa:A`]
         EBNSTAGE_CHAR) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `w1:A` (CONJUNCTS_THEN2 ASSUME_TAC
    (CONJUNCTS_THEN2 (LABEL_TAC "w1ch") ASSUME_TAC))) THEN
  SUBGOAL_THEN `!u:A. u IN D /\ (E:A->A->bool) u yx ==> E u w1`
    (LABEL_TAC "Ysub") THENL
   [X_GEN_TAC `u:A` THEN STRIP_TAC THEN
    USE_THEN "w1ch" (MP_TAC o SPEC `u:A`) THEN
    ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    MAP_EVERY EXISTS_TAC [`ax:A`;`yx:A`] THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`w1:A`;`B:A`] ECROSS_EXISTS) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `cr:A` (LABEL_TAC "cr")) THEN
  SUBGOAL_THEN `(cr:A) IN D` ASSUME_TAC THENL
   [USE_THEN "cr" (MP_TAC o REWRITE_RULE[ecross]) THEN SIMP_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `esubset D (E:A->A->bool) un cr` ASSUME_TAC THENL
   [REWRITE_TAC[esubset] THEN X_GEN_TAC `z:A` THEN STRIP_TAC THEN
    USE_THEN "cr" (MP_TAC o SPEC `z:A` o CONJUNCT2 o REWRITE_RULE[ecross]) THEN
    ASM_REWRITE_TAC[] THEN DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    USE_THEN "unch" (MP_TAC o SPEC `z:A`) THEN
    ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN(fun th -> MP_TAC(EQ_MP th (ASSUME `(E:A->A->bool) z un`))) THEN
    DISCH_THEN(X_CHOOSE_THEN `s:A` (X_CHOOSE_THEN `q:A` STRIP_ASSUME_TAC)) THEN
    SUBGOAL_THEN `(E:A->A->bool) s w1` ASSUME_TAC THENL
     [USE_THEN "Ysub" MATCH_MP_TAC THEN CONJ_TAC THENL
       [FIRST_ASSUM ACCEPT_TAC;
        USE_THEN "Wsub" MATCH_MP_TAC THEN ASM_REWRITE_TAC[]]; ALL_TAC] THEN
    SUBGOAL_THEN `(E:A->A->bool) q B` ASSUME_TAC THENL
     [MP_TAC(ISPECL
             [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`x:A`;`s:A`;`q:A`]
             EUUVAL_IN) THEN
      ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
      STRIP_TAC THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    MAP_EVERY EXISTS_TAC [`s:A`;`q:A`] THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `ebnmem D (E:A->A->bool) B w1 un` ASSUME_TAC THENL
   [REWRITE_TAC[ebnmem] THEN ASM_REWRITE_TAC[] THEN
    EXISTS_TAC `cr:A` THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) un ysa` ASSUME_TAC THENL
   [UNDISCH_TAC `ebnfuns D (E:A->A->bool) B w1 ysa` THEN
    REWRITE_TAC[ebnfuns] THEN
    DISCH_THEN(MP_TAC o SPEC `un:A` o CONJUNCT2) THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  REWRITE_TAC[bname] THEN MAP_EVERY EXISTS_TAC [`sa:A`;`ysa:A`] THEN
  ASM_REWRITE_TAC[]);;

(* ===================================================================== *)
(* F5, V^B |= ZFC:  UNION axiom.   [[union_ax]] = top.                    *)
(* Value-level membership bounds (EBV_IN_GE_TERM_V / EBV_IN_LE_V), value  *)
(* existence (EBV_IN_VAL_EXISTS / EBV_EQ_VAL_EXISTS), MEET monotonicity   *)
(* (EMEET_MONO), domain names are B-names (UNION_DOM_BNAME); union-name   *)
(* application inversion (UNION_APPLY_INV); the two value-equality        *)
(* directions EBV_IN_UNION_LE (with the dom-x helper UNION_GE_DOMX) and   *)
(* EBV_IN_UNION_GE; the two SUP directions UNION_SUP_LE / UNION_SUP_GE;    *)
(* and the assembled BVALF_UNION ([[union_ax]] = top).                    *)
(* ===================================================================== *)

(* --------------------------------------------------------------------- *)
(* VALUE-LEVEL membership bounds: lift EBV_IN_GE_TERM / EBV_IN_LE from the *)
(* stage-level form (needing the ordinal a, stage w, tables sIN,sEQ and    *)
(* the combiner-SUP  ebvin sEQ v u z ) to the value-level form needing     *)
(* only  ebv_in D E B leq u v z.   We unfold ebv_in ourselves -- so we      *)
(* keep the  w IN D  conjunct that EBV_IN_EBVIN discards -- then convert    *)
(* the raw table read  eapply sIN <u,v> z  into the combiner-SUP           *)
(* ebvin sEQ v u z (EBVATT_VAL + EAPPLY_UNIQUE), exactly as EBV_IN_EBVIN.   *)
(* These are the workhorses of the union value-equality (lemma 3): every   *)
(*   v(y) MEET [[u=y]] <= [[u IN v]]   (GE_TERM_V)                          *)
(*   [[u IN v]] <= w0   when all those terms are <= w0   (LE_V).            *)
(* --------------------------------------------------------------------- *)

let EBV_IN_GE_TERM_V = prove
 (`!D (E:A->A->bool) B leq u v z y qy ey c.
      model D E ZF_AX /\ ecba D E B leq /\ B IN D /\
      u IN D /\ v IN D /\ z IN D /\ ebv_in D E B leq u v z /\
      y IN D /\ qy IN D /\ ey IN D /\ c IN D /\
      eapply D E v y qy /\ ebv_eq D E B leq u y ey /\ emeet D E B leq qy ey c
      ==> erel D E leq c z`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  UNDISCH_TAC `ebv_in D (E:A->A->bool) B leq u v z` THEN
  REWRITE_TAC[ebv_in] THEN
  DISCH_THEN(X_CHOOSE_THEN `aa:A` (X_CHOOSE_THEN `ww:A` (X_CHOOSE_THEN `sI:A`
    (X_CHOOSE_THEN `sE:A` (X_CHOOSE_THEN `pr0:A` STRIP_ASSUME_TAC))))) THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`ww:A`;`sI:A`;`sE:A`;
    `u:A`;`v:A`;`pr0:A`] EBVATT_VAL) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(CONJUNCTS_THEN2 (X_CHOOSE_THEN `vi:A` STRIP_ASSUME_TAC)
             (K ALL_TAC)) THEN
  SUBGOAL_THEN `eisfun D (E:A->A->bool) sI` ASSUME_TAC THENL
   [FIRST_ASSUM(ACCEPT_TAC o CONJUNCT1 o REWRITE_RULE[ebvatt]); ALL_TAC] THEN
  SUBGOAL_THEN `(pr0:A) IN D` ASSUME_TAC THENL
   [FIRST_ASSUM(ACCEPT_TAC o MATCH_MP EOPAIR_IN); ALL_TAC] THEN
  SUBGOAL_THEN `z:A = vi` SUBST_ALL_TAC THENL
   [MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`sI:A`;`pr0:A`;`z:A`;`vi:A`]
      EAPPLY_UNIQUE) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`aa:A`;`ww:A`;`sI:A`;
    `sE:A`;`u:A`;`v:A`;`vi:A`;`y:A`;`qy:A`;`ey:A`;`c:A`] EBV_IN_GE_TERM) THEN
  ASM_REWRITE_TAC[]);;

let EBV_IN_LE_V = prove
 (`!D (E:A->A->bool) B leq u v z w0.
      model D E ZF_AX /\ ecba D E B leq /\ B IN D /\
      u IN D /\ v IN D /\ z IN D /\ ebv_in D E B leq u v z /\
      w0 IN D /\ E w0 B /\
      (!y qy ey c.
          y IN D /\ qy IN D /\ ey IN D /\ c IN D /\
          eapply D E v y qy /\ ebv_eq D E B leq u y ey /\
            emeet D E B leq qy ey c
          ==> erel D E leq c w0)
      ==> erel D E leq z w0`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  UNDISCH_TAC `ebv_in D (E:A->A->bool) B leq u v z` THEN
  REWRITE_TAC[ebv_in] THEN
  DISCH_THEN(X_CHOOSE_THEN `aa:A` (X_CHOOSE_THEN `ww:A` (X_CHOOSE_THEN `sI:A`
    (X_CHOOSE_THEN `sE:A` (X_CHOOSE_THEN `pr0:A` STRIP_ASSUME_TAC))))) THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`ww:A`;`sI:A`;`sE:A`;
    `u:A`;`v:A`;`pr0:A`] EBVATT_VAL) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(CONJUNCTS_THEN2 (X_CHOOSE_THEN `vi:A` STRIP_ASSUME_TAC)
             (K ALL_TAC)) THEN
  SUBGOAL_THEN `eisfun D (E:A->A->bool) sI` ASSUME_TAC THENL
   [FIRST_ASSUM(ACCEPT_TAC o CONJUNCT1 o REWRITE_RULE[ebvatt]); ALL_TAC] THEN
  SUBGOAL_THEN `(pr0:A) IN D` ASSUME_TAC THENL
   [FIRST_ASSUM(ACCEPT_TAC o MATCH_MP EOPAIR_IN); ALL_TAC] THEN
  SUBGOAL_THEN `z:A = vi` SUBST_ALL_TAC THENL
   [MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`sI:A`;`pr0:A`;`z:A`;`vi:A`]
      EAPPLY_UNIQUE) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`aa:A`;`ww:A`;`sI:A`;
    `sE:A`;`u:A`;`v:A`;`vi:A`;`w0:A`] EBV_IN_LE) THEN
  ASM_REWRITE_TAC[]);;

(* --------------------------------------------------------------------- *)
(* Existence of the Boolean IN/EQ VALUES for a pair of B-names.  At a      *)
(* common stage (BNAME_DIRECTED) the attainment tables (EBVATT_EXISTS)     *)
(* read off  [[u IN v]]  and  [[u = v]]  as genuine domain elements of B.  *)
(* (bvalf would give them too, but via a valuation; the stage route is     *)
(* self-contained.)  Used throughout the union value-equality to name the  *)
(* intermediate values [[t IN w]], [[w IN x]], [[w=w]].                    *)
(* --------------------------------------------------------------------- *)

let EBV_IN_VAL_EXISTS = prove
 (`!D (E:A->A->bool) B leq u v.
      model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
      u IN D /\ v IN D /\ bname D E B u /\ bname D E B v
      ==> ?z. z IN D /\ E z B /\ ebv_in D E B leq u v z`,
  REPEAT STRIP_TAC THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`u:A`;`v:A`]
         BNAME_DIRECTED) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `ao:A` (X_CHOOSE_THEN `y0:A` STRIP_ASSUME_TAC)) THEN
  SUBGOAL_THEN `!zt. zt IN D /\ (E:A->A->bool) zt y0 ==> bname D E B zt`
    ASSUME_TAC THENL
   [REPEAT STRIP_TAC THEN
    MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;
                         `ao:A`;`y0:A`;`zt:A`] BNAME_STAGE) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`y0:A`]
         EBVATT_EXISTS) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[] THEN EXISTS_TAC `u:A` THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `sIN:A` (X_CHOOSE_THEN `sEQ:A` ASSUME_TAC)) THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`u:A`;`v:A`] EOPAIR_EXISTS) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `pr:A`) THEN
  MP_TAC(ISPECL
         [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`y0:A`;`sIN:A`;`sEQ:A`;
          `u:A`;`v:A`;`pr:A`] EBVATT_VAL) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(CONJUNCTS_THEN2 (X_CHOOSE_THEN `vi:A` STRIP_ASSUME_TAC)
             (K ALL_TAC)) THEN
  EXISTS_TAC `vi:A` THEN ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
   [FIRST_ASSUM(ACCEPT_TAC o CONJUNCT2 o MATCH_MP EBVIN_IN);
    MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`ao:A`;`y0:A`;
                  `sIN:A`;`sEQ:A`;`u:A`;`v:A`;`vi:A`] EBV_IN_AT_STAGE) THEN
    ASM_REWRITE_TAC[]]);;

let EBV_EQ_VAL_EXISTS = prove
 (`!D (E:A->A->bool) B leq u v.
      model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
      u IN D /\ v IN D /\ bname D E B u /\ bname D E B v
      ==> ?z. z IN D /\ E z B /\ ebv_eq D E B leq u v z`,
  REPEAT STRIP_TAC THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`u:A`;`v:A`]
         BNAME_DIRECTED) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `ao:A` (X_CHOOSE_THEN `y0:A` STRIP_ASSUME_TAC)) THEN
  SUBGOAL_THEN `!zt. zt IN D /\ (E:A->A->bool) zt y0 ==> bname D E B zt`
    ASSUME_TAC THENL
   [REPEAT STRIP_TAC THEN
    MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;
                         `ao:A`;`y0:A`;`zt:A`] BNAME_STAGE) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`y0:A`]
         EBVATT_EXISTS) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[] THEN EXISTS_TAC `u:A` THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `sIN:A` (X_CHOOSE_THEN `sEQ:A` ASSUME_TAC)) THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`u:A`;`v:A`] EOPAIR_EXISTS) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `pr:A`) THEN
  MP_TAC(ISPECL
         [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`y0:A`;`sIN:A`;`sEQ:A`;
          `u:A`;`v:A`;`pr:A`] EBVATT_VAL) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(CONJUNCTS_THEN2 (K ALL_TAC)
             (X_CHOOSE_THEN `ve:A` STRIP_ASSUME_TAC)) THEN
  EXISTS_TAC `ve:A` THEN ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
   [FIRST_ASSUM(ACCEPT_TAC o CONJUNCT2 o MATCH_MP EBVEQ_IN);
    MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`ao:A`;`y0:A`;
                  `sIN:A`;`sEQ:A`;`u:A`;`v:A`;`ve:A`] EBV_EQ_AT_STAGE) THEN
    ASM_REWRITE_TAC[]]);;

(* --------------------------------------------------------------------- *)
(* Two-sided monotonicity of MEET:  a<=a' and b<=b' give a MEET b <=       *)
(* a' MEET b'.  (m <= a <= a' and m <= b <= b', so m is below both a',b',  *)
(* hence below their meet m'.)                                             *)
(* --------------------------------------------------------------------- *)

let EMEET_MONO = prove
 (`!D (E:A->A->bool) B leq a b a' b' m m'.
      eporder D E B leq /\
      a IN D /\ b IN D /\ a' IN D /\ b' IN D /\
      E a B /\ E b B /\ E a' B /\ E b' B /\
      emeet D E B leq a b m /\ emeet D E B leq a' b' m' /\
      erel D E leq a a' /\ erel D E leq b b'
      ==> erel D E leq m m'`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `(m:A) IN D /\ (E:A->A->bool) m B` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[EMEET_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq m a /\ erel D E leq m b`
  STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[EMEET_LE]; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq m a'` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`m:A`;`a:A`;`a':A`]
                 EPORDER_TRANS) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq m b'` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`m:A`;`b:A`;`b':A`]
                 EPORDER_TRANS) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MATCH_MP_TAC(ISPECL
               [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`a':A`;`b':A`;`m':A`;
                `m:A`] EMEET_GREATEST) THEN ASM_REWRITE_TAC[]);;

(* --------------------------------------------------------------------- *)
(* Domain elements of a B-name are B-names.  If x is a B-name (x lies in   *)
(* stage yx = ebnstage ax) and w in dom x (eapply x w q for some q), then  *)
(* STAGE_DOM_CLOSED puts w in the stage yx, so BNAME_STAGE gives bname w.   *)
(* Needed by both directions of the union value-equality EBV_IN_UNION:     *)
(* the domain names w of x (and the union stages s in dom w) must be        *)
(* B-names to serve as existential witnesses (BVALF_EX_UB) / bound points.  *)
(* --------------------------------------------------------------------- *)

let UNION_DOM_BNAME = prove
 (`!D (E:A->A->bool) B x w.
      model D E ZF_AX /\ B IN D /\ x IN D /\ bname D E B x /\ w IN D /\
      eindom D E x w
      ==> bname D E B w`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "m BD xD bnx wD ind" THEN
  USE_THEN "bnx"
    (X_CHOOSE_THEN `ax:A` (X_CHOOSE_THEN `yx:A` STRIP_ASSUME_TAC) o
     REWRITE_RULE[bname]) THEN
  USE_THEN "ind"
    (X_CHOOSE_THEN `q:A` STRIP_ASSUME_TAC o REWRITE_RULE[eindom]) THEN
  MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`ax:A`;`yx:A`;`w:A`]
    BNAME_STAGE) THEN
  ASM_REWRITE_TAC[] THEN
  MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`ax:A`;`yx:A`;`x:A`;
    `w:A`;`q:A`] STAGE_DOM_CLOSED) THEN
  ASM_REWRITE_TAC[]);;

(* --------------------------------------------------------------------- *)
(* Inversion of the union-name application.  From un's membership          *)
(* characterisation (E z un <=> ?s q. E s W /\ euuval x s q /\ <s,q>=z)     *)
(* and eapply un s qs, recover  E s W  and  euuval x s qs .  This is the    *)
(* INV hypothesis that EBV_IN_UNION_LE (direction <=) consumes; here we     *)
(* derive it from the raw un-characterisation, so the final EBV_IN_UNION    *)
(* only needs to carry the char.  Proof: eapply gives a pair p=<s,qs> in    *)
(* un; the char yields s2,q2 with <s2,q2>=p and E s2 W /\ euuval x s2 q2;    *)
(* EOPAIR_INJ forces s2=s, q2=qs.                                           *)
(* --------------------------------------------------------------------- *)

let UNION_APPLY_INV = prove
 (`!D (E:A->A->bool) B leq x W un s qs.
      model D E ZF_AX /\ x IN D /\ W IN D /\ un IN D /\
      (!z. z IN D
           ==> (E z un <=>
                ?s2 q2. s2 IN D /\ q2 IN D /\ E s2 W /\
                        euuval D E B leq x s2 q2 /\
                          eopair D (E:A->A->bool) s2 q2 z)) /\
      s IN D /\ qs IN D /\ eapply D E un s qs
      ==> E s W /\ euuval D E B leq x s qs`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "modl xD WD unD unch sD qsD ap" THEN
  USE_THEN "ap"
    (X_CHOOSE_THEN `p:A` STRIP_ASSUME_TAC o REWRITE_RULE[eapply]) THEN
  SUBGOAL_THEN `(p:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[EOPAIR_IN]; ALL_TAC] THEN
  USE_THEN "unch" (MP_TAC o SPEC `p:A`) THEN
  ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  DISCH_THEN(fun th -> MP_TAC(EQ_MP th (ASSUME `(E:A->A->bool) p un`))) THEN
  DISCH_THEN(X_CHOOSE_THEN `s2:A` (X_CHOOSE_THEN `q2:A` STRIP_ASSUME_TAC)) THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`s2:A`;`q2:A`;`s:A`;`qs:A`;`p:A`]
    EOPAIR_INJ) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(CONJUNCTS_THEN2 SUBST_ALL_TAC SUBST_ALL_TAC) THEN
  ASM_REWRITE_TAC[]);;

(* --------------------------------------------------------------------- *)
(* UNION value-equality, DIRECTION B (<=):  [[t in un]] <= r, where       *)
(* r is any upper bound of the combiner set { [[w in x]] MEET [[t in w]] : *)
(* w a B-name }.  We break [[t in un]] as SUP over s in dom un of          *)
(* un(s) MEET [[t=s]] (EBV_IN_LE_V); invert eapply un s qs to euuval x s qs *)
(* (INV hyp); EUUVAL_LEAST reduces to each combiner x(w) MEET w(s); then   *)
(* (x(w) MEET w(s)) MEET [[t=s]] <= [[w in x]] MEET [[t in w]] <= r via     *)
(* x(w)<=[[w in x]] (EBV_IN_GE_TERM_V, [[w=w]]=top) and                     *)
(* w(s) MEET [[t=s]] <= [[t in w]] (EBV_IN_GE_TERM_V), with residuation     *)
(* (EBIMP_MEET_LE / EBIMP_LE_IMP) turning the MEET-with-[[t=s]] into <=.    *)
(* --------------------------------------------------------------------- *)

let EBV_IN_UNION_LE = prove
 (`!D (E:A->A->bool) B leq x t un zun r.
      model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
      x IN D /\ bname D E B x /\ t IN D /\ bname D E B t /\
      un IN D /\
      (!s qs. s IN D /\ qs IN D /\ eapply D E un s qs
              ==> euuval D E B leq x s qs) /\
      zun IN D /\ ebv_in D E B leq t un zun /\
      r IN D /\ E r B /\
      (!w zwx ztw m.
          w IN D /\ bname D E B w /\ zwx IN D /\ ztw IN D /\ m IN D /\
          ebv_in D E B leq w x zwx /\ ebv_in D E B leq t w ztw /\
          emeet D E B leq zwx ztw m
          ==> erel D E leq m r)
      ==> erel D E leq zun r`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `ebalg D (E:A->A->bool) B leq` ASSUME_TAC THENL
   [ASM_MESON_TAC[ECBA_IMP_BALG]; ALL_TAC] THEN
  SUBGOAL_THEN `eporder D (E:A->A->bool) B leq` ASSUME_TAC THENL
   [ASM_MESON_TAC[EBALG_IMP_PORDER]; ALL_TAC] THEN
  MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`t:A`;`un:A`;
    `zun:A`;`r:A`] EBV_IN_LE_V) THEN
  ASM_REWRITE_TAC[] THEN
  MAP_EVERY X_GEN_TAC [`s:A`;`qs:A`;`es:A`;`c:A`] THEN STRIP_TAC THEN
  (* qs = un(s) is a euuval; get its B-membership *)
  SUBGOAL_THEN `euuval D (E:A->A->bool) B leq x s qs` ASSUME_TAC THENL
   [FIRST_ASSUM MATCH_MP_TAC THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(qs:A) IN D /\ (E:A->A->bool) qs B` STRIP_ASSUME_TAC THENL
   [MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`x:A`;`s:A`;`qs:A`]
      EUUVAL_IN) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) es B` ASSUME_TAC THENL
   [MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`t:A`;`s:A`;`es:A`]
      EBV_EQ_IN_B) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* residuation: build imp = es ==> r ; reduce  c=qs MEET es <= r  to  qs *)
  (* <= imp *)
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`es:A`;`r:A`]
    EBIMP_EXISTS) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `imp:A`) THEN
  SUBGOAL_THEN `(imp:A) IN D /\ (E:A->A->bool) imp B` STRIP_ASSUME_TAC THENL
   [MP_TAC(ISPECL
           [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`es:A`;`r:A`;`imp:A`]
           EBIMP_IN) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`qs:A`;`es:A`;
    `r:A`;`imp:A`;`c:A`] EBIMP_MEET_LE) THEN
  ASM_REWRITE_TAC[] THEN
  (* now goal:  erel leq qs imp ;  EUUVAL_LEAST reduces to per-combiner *)
  MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`x:A`;`s:A`;
    `qs:A`;`imp:A`] EUUVAL_LEAST) THEN
  ASM_REWRITE_TAC[] THEN
  X_GEN_TAC `cc:A` THEN
  DISCH_THEN(X_CHOOSE_THEN `w:A` (X_CHOOSE_THEN `qw:A` (X_CHOOSE_THEN `ws:A`
    STRIP_ASSUME_TAC)) o REWRITE_RULE[euucomb]) THEN
  (* cc = x(w) MEET w(s) ;  its B-membership *)
  SUBGOAL_THEN `(cc:A) IN D /\ (E:A->A->bool) cc B` STRIP_ASSUME_TAC THENL
   [MP_TAC(ISPECL
           [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`qw:A`;`ws:A`;`cc:A`]
           EMEET_IN) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* dm = cc MEET es ;  reduce  cc <= imp  to  dm <= r  (EBIMP_LE_IMP) *)
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`cc:A`;`es:A`]
    EBALG_MEET) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `dm:A`) THEN
  SUBGOAL_THEN `(dm:A) IN D /\ (E:A->A->bool) dm B` STRIP_ASSUME_TAC THENL
   [MP_TAC(ISPECL
           [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`cc:A`;`es:A`;`dm:A`]
           EMEET_IN) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`cc:A`;`es:A`;
    `r:A`;`imp:A`;`dm:A`] EBIMP_LE_IMP) THEN
  ASM_REWRITE_TAC[] THEN
  (* goal now:  erel leq dm r .  Establish bname w, [[w in x]], [[t in w]]. *)
  SUBGOAL_THEN `bname D (E:A->A->bool) B w` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`x:A`;`w:A`]
      UNION_DOM_BNAME) THEN
    ASM_REWRITE_TAC[] THEN REWRITE_TAC[eindom] THEN
    EXISTS_TAC `qw:A` THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) qw B` ASSUME_TAC THENL
   [MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`x:A`;`w:A`;`qw:A`]
      BNAME_APPLY_IN_B) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) ws B` ASSUME_TAC THENL
   [MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`w:A`;`s:A`;`ws:A`]
      BNAME_APPLY_IN_B) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`w:A`;`x:A`]
    EBV_IN_VAL_EXISTS) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `zwx:A` STRIP_ASSUME_TAC) THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`t:A`;`w:A`]
    EBV_IN_VAL_EXISTS) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `ztw:A` STRIP_ASSUME_TAC) THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`w:A`;`w:A`]
    EBV_EQ_VAL_EXISTS) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `eww:A` STRIP_ASSUME_TAC) THEN
  SUBGOAL_THEN `etop D (E:A->A->bool) B leq eww` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`w:A`;`eww:A`]
                 EBV_EQ_REFL) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `emeet D (E:A->A->bool) B leq qw eww qw` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`eww:A`;`qw:A`]
                 EMEET_TOP) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* term bound 1:  x(w) = qw <= [[w in x]] = zwx *)
  SUBGOAL_THEN `erel D (E:A->A->bool) leq qw zwx` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`w:A`;`x:A`;
      `zwx:A`;`w:A`;`qw:A`;`eww:A`;`qw:A`] EBV_IN_GE_TERM_V) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* term bound 2:  w(s) MEET [[t=s]] = wse <= [[t in w]] = ztw *)
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`ws:A`;`es:A`]
    EBALG_MEET) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `wse:A`) THEN
  SUBGOAL_THEN `(wse:A) IN D /\ (E:A->A->bool) wse B` STRIP_ASSUME_TAC THENL
   [MP_TAC(ISPECL
           [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`ws:A`;`es:A`;`wse:A`]
           EMEET_IN) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq wse ztw` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`t:A`;`w:A`;
      `ztw:A`;`s:A`;`ws:A`;`es:A`;`wse:A`] EBV_IN_GE_TERM_V) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* dm <= cc <= qw <= zwx  and  dm <= ws, dm <= es => dm <= wse <= ztw *)
  SUBGOAL_THEN `erel D (E:A->A->bool) leq dm cc /\ erel D E leq dm es`
  STRIP_ASSUME_TAC THENL
   [MP_TAC(ISPECL
           [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`cc:A`;`es:A`;`dm:A`]
           EMEET_LE) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq cc qw /\ erel D E leq cc ws`
  STRIP_ASSUME_TAC THENL
   [MP_TAC(ISPECL
           [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`qw:A`;`ws:A`;`cc:A`]
           EMEET_LE) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq dm qw` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`dm:A`;`cc:A`;
                  `qw:A`] EPORDER_TRANS) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq dm zwx` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`dm:A`;`qw:A`;
                  `zwx:A`] EPORDER_TRANS) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq dm ws` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`dm:A`;`cc:A`;
                  `ws:A`] EPORDER_TRANS) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq dm wse` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`ws:A`;`es:A`;
                  `wse:A`;`dm:A`] EMEET_GREATEST) THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq dm ztw` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`dm:A`;`wse:A`;
                  `ztw:A`] EPORDER_TRANS) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* mfull = [[w in x]] MEET [[t in w]] ;  dm <= mfull <= r *)
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`zwx:A`;`ztw:A`]
    EBALG_MEET) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `mfull:A`) THEN
  SUBGOAL_THEN `(mfull:A) IN D /\ (E:A->A->bool) mfull B`
    STRIP_ASSUME_TAC THENL
   [MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`zwx:A`;`ztw:A`;
      `mfull:A`] EMEET_IN) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq dm mfull` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`zwx:A`;`ztw:A`;
                  `mfull:A`;`dm:A`] EMEET_GREATEST) THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq mfull r` ASSUME_TAC THENL
   [FIRST_ASSUM(fun th ->
                MP_TAC(SPECL [`w:A`;`zwx:A`;`ztw:A`;`mfull:A`] th)) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC]; ALL_TAC] THEN
  MATCH_MP_TAC(ISPECL
               [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`dm:A`;`mfull:A`;
                `r:A`] EPORDER_TRANS) THEN ASM_REWRITE_TAC[]);;

(* --------------------------------------------------------------------- *)
(* UNION direction >=, the  w in dom x  case:  x(w) MEET [[t in w]] <= zun. *)
(* Residuate x(w)=qwx out of m = qwx MEET ztw (EBIMP_MEET_LE), then bound   *)
(* ztw=[[t in w]] <= (qwx ==> zun) by EBV_IN_LE_V over dom w: for each       *)
(* s in dom w with w(s)=ws and [[t=s]]=ets, the term ws MEET ets, residuated *)
(* against qwx (EBIMP_LE_IMP), reduces to  (ws MEET ets) MEET qwx <= zun.    *)
(* Now s in W (W-char, witness w), so cw = qwx MEET ws is a union-combiner   *)
(* (euucomb x s cw), hence cw <= un(s)=uq (EUUVAL_UB) with eapply un s uq    *)
(* (forward map); and uq MEET ets <= [[t in un]]=zun (EBV_IN_GE_TERM_V).     *)
(* The meet dm2 = (ws MEET ets) MEET qwx sits below both uq (via cw) and     *)
(* ets, hence below uq MEET ets <= zun.                                      *)
(* --------------------------------------------------------------------- *)

let UNION_GE_DOMX = prove
 (`!D (E:A->A->bool) B leq x t un W zun w qwx ztw m.
      model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
      x IN D /\ bname D E B x /\ t IN D /\ bname D E B t /\
      un IN D /\ W IN D /\
      (!sd. sd IN D
            ==> (E sd W <=> ?w'. w' IN D /\ eindom D E x w' /\
                 eindom D E w' sd)) /\
      (!sd q. sd IN D /\ E sd W /\ euuval D E B leq x sd q ==>
       eapply D E un sd q) /\
      zun IN D /\ ebv_in D E B leq t un zun /\
      w IN D /\ bname D E B w /\ qwx IN D /\ eapply D E x w qwx /\
      ztw IN D /\ ebv_in D E B leq t w ztw /\
      m IN D /\ emeet D E B leq qwx ztw m
      ==> erel D E leq m zun`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `ebalg D (E:A->A->bool) B leq` ASSUME_TAC THENL
   [ASM_MESON_TAC[ECBA_IMP_BALG]; ALL_TAC] THEN
  SUBGOAL_THEN `eporder D (E:A->A->bool) B leq` ASSUME_TAC THENL
   [ASM_MESON_TAC[EBALG_IMP_PORDER]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) qwx B` ASSUME_TAC THENL
   [MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`x:A`;`w:A`;`qwx:A`]
      BNAME_APPLY_IN_B) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) zun B` ASSUME_TAC THENL
   [MP_TAC(ISPECL
           [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`t:A`;`un:A`;`zun:A`]
           EBV_IN_IN_B) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) ztw B` ASSUME_TAC THENL
   [MP_TAC(ISPECL
           [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`t:A`;`w:A`;`ztw:A`]
           EBV_IN_IN_B) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* imp = qwx ==> zun *)
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`qwx:A`;`zun:A`]
    EBIMP_EXISTS) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `imp:A`) THEN
  SUBGOAL_THEN `(imp:A) IN D /\ (E:A->A->bool) imp B` STRIP_ASSUME_TAC THENL
   [MP_TAC(ISPECL
           [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`qwx:A`;`zun:A`;`imp:A`]
           EBIMP_IN) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* emeet ztw qwx m by symmetry, then EBIMP_MEET_LE reduces goal to *)
  (* ztw<=imp *)
  SUBGOAL_THEN `emeet D (E:A->A->bool) B leq ztw qwx m` ASSUME_TAC THENL
   [FIRST_ASSUM(fun th -> ACCEPT_TAC(MATCH_MP EMEET_SYM th)); ALL_TAC] THEN
  MATCH_MP_TAC(ISPECL
               [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`ztw:A`;`qwx:A`;
                `zun:A`;`imp:A`;`m:A`] EBIMP_MEET_LE) THEN
  ASM_REWRITE_TAC[] THEN
  (* goal: erel leq ztw imp ; EBV_IN_LE_V over dom w *)
  MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`t:A`;`w:A`;
    `ztw:A`;`imp:A`] EBV_IN_LE_V) THEN
  ASM_REWRITE_TAC[] THEN
  MAP_EVERY X_GEN_TAC [`s:A`;`ws:A`;`ets:A`;`cc:A`] THEN STRIP_TAC THEN
  (* cc = ws MEET ets ;  B-membership *)
  SUBGOAL_THEN `(E:A->A->bool) cc B` ASSUME_TAC THENL
   [MP_TAC(ISPECL
           [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`ws:A`;`ets:A`;`cc:A`]
           EMEET_IN) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) ws B` ASSUME_TAC THENL
   [MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`w:A`;`s:A`;`ws:A`]
      BNAME_APPLY_IN_B) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) ets B` ASSUME_TAC THENL
   [MP_TAC(ISPECL
           [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`t:A`;`s:A`;`ets:A`]
           EBV_EQ_IN_B) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* dm2 = cc MEET qwx ;  residuate qwx back (EBIMP_LE_IMP): goal dm2<=zun *)
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`cc:A`;`qwx:A`]
    EBALG_MEET) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `dm2:A`) THEN
  SUBGOAL_THEN `(dm2:A) IN D /\ (E:A->A->bool) dm2 B` STRIP_ASSUME_TAC THENL
   [MP_TAC(ISPECL
           [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`cc:A`;`qwx:A`;`dm2:A`]
           EMEET_IN) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`cc:A`;`qwx:A`;
    `zun:A`;`imp:A`;`dm2:A`] EBIMP_LE_IMP) THEN
  ASM_REWRITE_TAC[] THEN
  (* goal: erel leq dm2 zun *)
  (* s in W : witness w, via W-char (derive the iff instance, then REWRITE) *)
  SUBGOAL_THEN `(E:A->A->bool) s W` ASSUME_TAC THENL
   [REWRITE_TAC[MP (SPEC `s:A`
        (ASSUME `!sd. sd IN D ==> ((E:A->A->bool) sd W <=>
                 ?w'. w' IN D /\ eindom D E x w' /\ eindom D E w' sd)`))
        (ASSUME `(s:A) IN D`)] THEN
    EXISTS_TAC `w:A` THEN ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
     [REWRITE_TAC[eindom] THEN EXISTS_TAC `qwx:A` THEN ASM_REWRITE_TAC[];
      REWRITE_TAC[eindom] THEN EXISTS_TAC `ws:A` THEN ASM_REWRITE_TAC[]];
    ALL_TAC] THEN
  (* cw = qwx MEET ws  is a union combiner *)
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`qwx:A`;`ws:A`]
    EBALG_MEET) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `cw:A`) THEN
  SUBGOAL_THEN `(cw:A) IN D /\ (E:A->A->bool) cw B` STRIP_ASSUME_TAC THENL
   [MP_TAC(ISPECL
           [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`qwx:A`;`ws:A`;`cw:A`]
           EMEET_IN) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `euucomb D (E:A->A->bool) B leq x s cw` ASSUME_TAC THENL
   [REWRITE_TAC[euucomb] THEN
    MAP_EVERY EXISTS_TAC [`w:A`;`qwx:A`;`ws:A`] THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  (* un(s) = uq via EUUVAL_EXISTS; eapply un s uq via forward map *)
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`x:A`;`s:A`]
    EUUVAL_EXISTS) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `uq:A`) THEN
  SUBGOAL_THEN `(uq:A) IN D /\ (E:A->A->bool) uq B` STRIP_ASSUME_TAC THENL
   [MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`x:A`;`s:A`;`uq:A`]
      EUUVAL_IN) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* forward map: discharge antecedent by ACCEPT, NOT ASM_REWRITE, else the
     Wch quantified-iff assumption rewrites  E s W  to its existential RHS. *)
  SUBGOAL_THEN `eapply D (E:A->A->bool) un s uq` ASSUME_TAC THENL
   [FIRST_ASSUM MATCH_MP_TAC THEN REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
    ALL_TAC] THEN
  (* cw <= uq via EUUVAL_UB *)
  SUBGOAL_THEN `erel D (E:A->A->bool) leq cw uq` ASSUME_TAC THENL
   [MP_TAC(ISPECL
           [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`x:A`;`s:A`;`uq:A`;`cw:A`]
           EUUVAL_UB) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* umets = uq MEET ets ;  umets <= zun via EBV_IN_GE_TERM_V *)
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`uq:A`;`ets:A`]
    EBALG_MEET) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `umets:A`) THEN
  SUBGOAL_THEN `(umets:A) IN D /\ (E:A->A->bool) umets B`
    STRIP_ASSUME_TAC THENL
   [MP_TAC(ISPECL
           [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`uq:A`;`ets:A`;`umets:A`]
           EMEET_IN) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq umets zun` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`t:A`;`un:A`;
      `zun:A`;`s:A`;`uq:A`;`ets:A`;`umets:A`] EBV_IN_GE_TERM_V) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* <=-assembly: dm2 <= umets <= zun *)
  SUBGOAL_THEN `erel D (E:A->A->bool) leq dm2 cc /\ erel D E leq dm2 qwx`
  STRIP_ASSUME_TAC THENL
   [MP_TAC(ISPECL
           [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`cc:A`;`qwx:A`;`dm2:A`]
           EMEET_LE) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq cc ws /\ erel D E leq cc ets`
  STRIP_ASSUME_TAC THENL
   [MP_TAC(ISPECL
           [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`ws:A`;`ets:A`;`cc:A`]
           EMEET_LE) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq dm2 ws` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`dm2:A`;`cc:A`;
                  `ws:A`] EPORDER_TRANS) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq dm2 cw` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`qwx:A`;`ws:A`;
                  `cw:A`;`dm2:A`] EMEET_GREATEST) THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq dm2 uq` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`dm2:A`;`cw:A`;
                  `uq:A`] EPORDER_TRANS) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq dm2 ets` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`dm2:A`;`cc:A`;
                  `ets:A`] EPORDER_TRANS) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq dm2 umets` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`uq:A`;`ets:A`;
                  `umets:A`;`dm2:A`] EMEET_GREATEST) THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  MATCH_MP_TAC(ISPECL
               [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`dm2:A`;`umets:A`;
                `zun:A`] EPORDER_TRANS) THEN ASM_REWRITE_TAC[]);;

(* --------------------------------------------------------------------- *)
(* UNION value-equality, DIRECTION >= :  for a GENERIC B-name a,          *)
(*   [[a in x]] MEET [[t in a]] <= [[t in un]] = zun.                      *)
(* Residuate [[t in a]]=zta out of m=za MEET zta (EBIMP_MEET_LE), reducing *)
(* to [[a in x]]=za <= (zta ==> zun). Decompose [[a in x]] over dom x      *)
(* (EBV_IN_LE_V): each w in dom x with x(w)=qwx, [[a=w]]=eaw contributes   *)
(* cc = qwx MEET eaw <= (zta ==> zun), i.e. (via EBIMP_LE_IMP)             *)
(* dm = cc MEET zta <= zun.  Now C2 (EBV_IN_CONG_R at (a,w,t)) gives       *)
(* em = eaw MEET zta <= [[t in w]] = ztw, collapsing the generic a to the  *)
(* dom-x name w; and dm <= qwx MEET ztw = mfull <= zun by UNION_GE_DOMX.   *)
(* --------------------------------------------------------------------- *)

let EBV_IN_UNION_GE = prove
 (`!D (E:A->A->bool) B leq x t un W zun a za zta m.
      model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
      x IN D /\ bname D E B x /\ t IN D /\ bname D E B t /\
      un IN D /\ W IN D /\
      (!sd. sd IN D
            ==> (E sd W <=> ?w'. w' IN D /\ eindom D E x w' /\
                 eindom D E w' sd)) /\
      (!sd q. sd IN D /\ E sd W /\ euuval D E B leq x sd q ==>
       eapply D E un sd q) /\
      zun IN D /\ ebv_in D E B leq t un zun /\
      a IN D /\ bname D E B a /\
      za IN D /\ ebv_in D E B leq a x za /\
      zta IN D /\ ebv_in D E B leq t a zta /\
      m IN D /\ emeet D E B leq za zta m
      ==> erel D E leq m zun`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `ebalg D (E:A->A->bool) B leq` ASSUME_TAC THENL
   [ASM_MESON_TAC[ECBA_IMP_BALG]; ALL_TAC] THEN
  SUBGOAL_THEN `eporder D (E:A->A->bool) B leq` ASSUME_TAC THENL
   [ASM_MESON_TAC[EBALG_IMP_PORDER]; ALL_TAC] THEN
  (* B-memberships of za, zta, zun *)
  SUBGOAL_THEN `(E:A->A->bool) za B` ASSUME_TAC THENL
   [MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`a:A`;`x:A`;`za:A`]
      EBV_IN_IN_B) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) zta B` ASSUME_TAC THENL
   [MP_TAC(ISPECL
           [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`t:A`;`a:A`;`zta:A`]
           EBV_IN_IN_B) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) zun B` ASSUME_TAC THENL
   [MP_TAC(ISPECL
           [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`t:A`;`un:A`;`zun:A`]
           EBV_IN_IN_B) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* imp = zta ==> zun ; residuate zta out of m: goal erel m zun -> erel za *)
  (* imp *)
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`zta:A`;`zun:A`]
    EBIMP_EXISTS) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `imp:A`) THEN
  SUBGOAL_THEN `(imp:A) IN D /\ (E:A->A->bool) imp B` STRIP_ASSUME_TAC THENL
   [MP_TAC(ISPECL
           [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`zta:A`;`zun:A`;`imp:A`]
           EBIMP_IN) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`za:A`;`zta:A`;
    `zun:A`;`imp:A`;`m:A`] EBIMP_MEET_LE) THEN
  ASM_REWRITE_TAC[] THEN
  (* goal: erel leq za imp ;  EBV_IN_LE_V on [[a in x]] over dom x *)
  MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`a:A`;`x:A`;
    `za:A`;`imp:A`] EBV_IN_LE_V) THEN
  ASM_REWRITE_TAC[] THEN
  MAP_EVERY X_GEN_TAC [`w:A`;`qwx:A`;`eaw:A`;`cc:A`] THEN STRIP_TAC THEN
  (* w is a dom-x name -> bname w ; B-memberships *)
  SUBGOAL_THEN `bname D (E:A->A->bool) B w` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`x:A`;`w:A`]
      UNION_DOM_BNAME) THEN
    ASM_REWRITE_TAC[] THEN REWRITE_TAC[eindom] THEN
    EXISTS_TAC `qwx:A` THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) qwx B` ASSUME_TAC THENL
   [MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`x:A`;`w:A`;`qwx:A`]
      BNAME_APPLY_IN_B) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) eaw B` ASSUME_TAC THENL
   [MP_TAC(ISPECL
           [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`a:A`;`w:A`;`eaw:A`]
           EBV_EQ_IN_B) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) cc B` ASSUME_TAC THENL
   [MP_TAC(ISPECL
           [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`qwx:A`;`eaw:A`;`cc:A`]
           EMEET_IN) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* dm = cc MEET zta ; residuate zta back: goal erel cc imp -> erel dm zun *)
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`cc:A`;`zta:A`]
    EBALG_MEET) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `dm:A`) THEN
  SUBGOAL_THEN `(dm:A) IN D /\ (E:A->A->bool) dm B` STRIP_ASSUME_TAC THENL
   [MP_TAC(ISPECL
           [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`cc:A`;`zta:A`;`dm:A`]
           EMEET_IN) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`cc:A`;`zta:A`;
    `zun:A`;`imp:A`;`dm:A`] EBIMP_LE_IMP) THEN
  ASM_REWRITE_TAC[] THEN
  (* goal: erel leq dm zun *)
  (* ztw = [[t in w]] *)
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`t:A`;`w:A`]
    EBV_IN_VAL_EXISTS) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `ztw:A` STRIP_ASSUME_TAC) THEN
  (* em = eaw MEET zta ;  C2 (EBV_IN_CONG_R at (a,w,t)):  em <= [[t in w]] = *)
  (* ztw *)
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`eaw:A`;`zta:A`]
    EBALG_MEET) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `em:A`) THEN
  SUBGOAL_THEN `(em:A) IN D /\ (E:A->A->bool) em B` STRIP_ASSUME_TAC THENL
   [MP_TAC(ISPECL
           [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`eaw:A`;`zta:A`;`em:A`]
           EMEET_IN) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq em ztw` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`a:A`;`w:A`;
      `t:A`;`eaw:A`;`zta:A`;`ztw:A`;`em:A`] EBV_IN_CONG_R) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* mfull = qwx MEET ztw = x(w) MEET [[t in w]] <= zun  via UNION_GE_DOMX *)
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`qwx:A`;`ztw:A`]
    EBALG_MEET) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `mfull:A`) THEN
  SUBGOAL_THEN `(mfull:A) IN D /\ (E:A->A->bool) mfull B`
    STRIP_ASSUME_TAC THENL
   [MP_TAC(ISPECL
           [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`qwx:A`;`ztw:A`;`mfull:A`]
           EMEET_IN) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq mfull zun` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`x:A`;`t:A`;
      `un:A`;`W:A`;`zun:A`;`w:A`;`qwx:A`;`ztw:A`;`mfull:A`] UNION_GE_DOMX) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* <=-chain: dm<=cc,zta ; cc<=qwx,eaw ; dm<=qwx ; dm<=eaw ; dm<=em<=ztw ;
     dm<=mfull<=zun *)
  SUBGOAL_THEN `erel D (E:A->A->bool) leq dm cc /\ erel D E leq dm zta`
  STRIP_ASSUME_TAC THENL
   [MP_TAC(ISPECL
           [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`cc:A`;`zta:A`;`dm:A`]
           EMEET_LE) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq cc qwx /\ erel D E leq cc eaw`
  STRIP_ASSUME_TAC THENL
   [MP_TAC(ISPECL
           [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`qwx:A`;`eaw:A`;`cc:A`]
           EMEET_LE) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq dm qwx` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`dm:A`;`cc:A`;
                  `qwx:A`] EPORDER_TRANS) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq dm eaw` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`dm:A`;`cc:A`;
                  `eaw:A`] EPORDER_TRANS) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq dm em` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`eaw:A`;`zta:A`;
                  `em:A`;`dm:A`] EMEET_GREATEST) THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq dm ztw` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`dm:A`;`em:A`;
                  `ztw:A`] EPORDER_TRANS) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq dm mfull` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`qwx:A`;`ztw:A`;
                  `mfull:A`;`dm:A`] EMEET_GREATEST) THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  MATCH_MP_TAC(ISPECL
               [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`dm:A`;`mfull:A`;
                `zun:A`] EPORDER_TRANS) THEN ASM_REWRITE_TAC[]);;

(* ------------------------------------------------------------------------- *)
(* UNION SUP, direction >= :  the Boolean value of the bounded existential   *)
(*   [[?w. w in xx /\ tt in w]] = SUP_{a bname} ([[a in xx]] MEET [[tt in    *)
(* a]]) is <= zun = [[tt in un]].  BVALF_EX_LEAST reduces to: each B-name    *)
(* a's term [[a in xx]] MEET [[tt in a]] <= zun, which is EBV_IN_UNION_GE.   *)
(* vv is the ambient valuation with vv 0 = xx (container), vv 2 = tt (elt).  *)
(* ------------------------------------------------------------------------- *)

let UNION_SUP_GE = prove
 (`!D (E:A->A->bool) B leq vv xx un tt W zun.
      model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
      valuation D vv /\ (!i. bname D E B (vv i)) /\
      vv 0 = xx /\ vv 2 = tt /\
      xx IN D /\ bname D E B xx /\ tt IN D /\ bname D E B tt /\
      un IN D /\ W IN D /\
      (!s. s IN D
           ==> (E s W <=> ?w. w IN D /\ eindom D E xx w /\ eindom D E w s)) /\
      (!s q. s IN D /\ E s W /\ euuval D E B leq xx s q ==>
       eapply D E un s q) /\
      zun IN D /\ ebv_in D E B leq tt un zun
      ==> erel D E leq (bvalf D E B leq vv (?? 3 ((3 %% 0) && (2 %% 3)))) zun`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `(E:A->A->bool) zun B` ASSUME_TAC THENL
   [MP_TAC(ISPECL
           [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`tt:A`;`un:A`;`zun:A`]
           EBV_IN_IN_B) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MATCH_MP_TAC(ISPECL [`3`; `(3 %% 0) && (2 %% 3)`;
    `D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`vv:num->A`;`zun:A`]
        BVALF_EX_LEAST) THEN
  ASM_REWRITE_TAC[] THEN
  X_GEN_TAC `a:A` THEN STRIP_TAC THEN
  SUBGOAL_THEN `valuation D ((3 |-> (a:A)) (vv:num->A)) /\
                (!i. bname D E B (((3 |-> (a:A)) (vv:num->A)) i))`
  STRIP_ASSUME_TAC THENL
   [CONJ_TAC THENL
     [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[];
      MATCH_MP_TAC BNAMEVAL_VALMOD THEN ASM_REWRITE_TAC[]]; ALL_TAC] THEN
  SUBGOAL_THEN `((3 |-> (a:A)) (vv:num->A)) 0 = xx /\
                ((3 |-> (a:A)) (vv:num->A)) 2 = tt /\
                ((3 |-> (a:A)) (vv:num->A)) 3 = a`
  STRIP_ASSUME_TAC THENL
   [ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER; ARITH_EQ]; ALL_TAC] THEN
  ABBREV_TAC
    `za = bvalf D (E:A->A->bool) B leq ((3 |-> (a:A)) (vv:num->A))
     (3 %% 0)` THEN
  ABBREV_TAC
    `zta = bvalf D (E:A->A->bool) B leq ((3 |-> (a:A)) (vv:num->A))
     (2 %% 3)` THEN
  ABBREV_TAC
    `mm = bvalf D (E:A->A->bool) B leq ((3 |-> (a:A)) (vv:num->A))
     ((3 %% 0) && (2 %% 3))` THEN
  SUBGOAL_THEN `ebv_in D (E:A->A->bool) B leq a xx za` ASSUME_TAC THENL
   [EXPAND_TAC "za" THEN
    MP_TAC(ISPECL [`3`;`0`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
      `(3 |-> (a:A)) (vv:num->A)`] BVALF_MEM) THEN ASM_SIMP_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `ebv_in D (E:A->A->bool) B leq tt a zta` ASSUME_TAC THENL
   [EXPAND_TAC "zta" THEN
    MP_TAC(ISPECL [`2`;`3`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
      `(3 |-> (a:A)) (vv:num->A)`] BVALF_MEM) THEN ASM_SIMP_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `emeet D (E:A->A->bool) B leq za zta mm` ASSUME_TAC THENL
   [MAP_EVERY EXPAND_TAC ["za";"zta";"mm"] THEN
    MP_TAC(ISPECL [`3 %% 0`;`2 %% 3`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
      `(3 |-> (a:A)) (vv:num->A)`] BVALF_AND_MEET) THEN ASM_SIMP_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `(za:A) IN D` ASSUME_TAC THENL
   [EXPAND_TAC "za" THEN
    MP_TAC(ISPECL [`3 %% 0`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
      `(3 |-> (a:A)) (vv:num->A)`] BVALF_SPEC) THEN ASM_SIMP_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `(zta:A) IN D` ASSUME_TAC THENL
   [EXPAND_TAC "zta" THEN
    MP_TAC(ISPECL [`2 %% 3`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
      `(3 |-> (a:A)) (vv:num->A)`] BVALF_SPEC) THEN ASM_SIMP_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `(mm:A) IN D` ASSUME_TAC THENL
   [EXPAND_TAC "mm" THEN
    MP_TAC(ISPECL
           [`(3 %% 0) && (2 %% 3)`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
            `(3 |-> (a:A)) (vv:num->A)`] BVALF_SPEC) THEN ASM_SIMP_TAC[];
    ALL_TAC] THEN
  MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`xx:A`;`tt:A`;
    `un:A`;`W:A`;`zun:A`;`a:A`;`za:A`;`zta:A`;`mm:A`] EBV_IN_UNION_GE) THEN
  ASM_REWRITE_TAC[]);;

(* ------------------------------------------------------------------------- *)
(* UNION SUP, direction <= :  zun = [[tt in un]] <= [[?w. w in xx /\ tt in   *)
(* w]] = SUP_{a bname} ([[a in xx]] MEET [[tt in a]]).  EBV_IN_UNION_LE      *)
(* (with r the SUP term) reduces to: for each B-name w, [[w in xx]] MEET     *)
(* [[tt in w]] <= r, and r = bvalf vv (?? 3 (...)) is exactly the SUP, so    *)
(* BVALF_EX_UB at witness w gives that bound once zwx/ztw/m are identified   *)
(* with the bvalf values at (3|->w) vv (EBV_IN_UNIQUE / EMEET_UNIQUE).       *)
(* ------------------------------------------------------------------------- *)

let UNION_SUP_LE = prove
 (`!D (E:A->A->bool) B leq vv xx un tt zun.
      model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
      valuation D vv /\ (!i. bname D E B (vv i)) /\
      vv 0 = xx /\ vv 2 = tt /\
      xx IN D /\ bname D E B xx /\ tt IN D /\ bname D E B tt /\
      un IN D /\
      (!s qs. s IN D /\ qs IN D /\ eapply D E un s qs
              ==> euuval D E B leq xx s qs) /\
      zun IN D /\ ebv_in D E B leq tt un zun
      ==> erel D E leq zun (bvalf D E B leq vv (?? 3 ((3 %% 0) && (2 %% 3))))`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `ebalg D (E:A->A->bool) B leq` ASSUME_TAC THENL
   [ASM_MESON_TAC[ECBA_IMP_BALG]; ALL_TAC] THEN
  SUBGOAL_THEN `eporder D (E:A->A->bool) B leq` ASSUME_TAC THENL
   [ASM_MESON_TAC[EBALG_IMP_PORDER]; ALL_TAC] THEN
  SUBGOAL_THEN
    `(bvalf D (E:A->A->bool) B leq vv (?? 3 ((3 %% 0) && (2 %% 3)))) IN D`
  ASSUME_TAC THENL
   [MP_TAC(ISPECL
           [`?? 3 ((3 %% 0) && (2 %% 3))`;`D:A->bool`;`E:A->A->bool`;`B:A`;
            `leq:A`;`vv:num->A`] BVALF_SPEC) THEN ASM_SIMP_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN
    `(E:A->A->bool) (bvalf D E B leq vv (?? 3 ((3 %% 0) && (2 %% 3)))) B`
  ASSUME_TAC THENL
   [MP_TAC(ISPECL
           [`?? 3 ((3 %% 0) && (2 %% 3))`;`D:A->bool`;`E:A->A->bool`;`B:A`;
            `leq:A`;`vv:num->A`] BVALF_IN_B) THEN ASM_SIMP_TAC[]; ALL_TAC] THEN
  MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`xx:A`;`tt:A`;
    `un:A`;`zun:A`;
    `bvalf (D:A->bool) (E:A->A->bool) (B:A) (leq:A) (vv:num->A)
           (?? 3 ((3 %% 0) && (2 %% 3)))`]
    EBV_IN_UNION_LE) THEN
  ASM_REWRITE_TAC[] THEN
  MAP_EVERY X_GEN_TAC [`w:A`;`zwx:A`;`ztw:A`;`m:A`] THEN STRIP_TAC THEN
  SUBGOAL_THEN `valuation D ((3 |-> (w:A)) (vv:num->A)) /\
                (!i. bname D E B (((3 |-> (w:A)) (vv:num->A)) i))`
  STRIP_ASSUME_TAC THENL
   [CONJ_TAC THENL
     [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[];
      MATCH_MP_TAC BNAMEVAL_VALMOD THEN ASM_REWRITE_TAC[]]; ALL_TAC] THEN
  SUBGOAL_THEN `((3 |-> (w:A)) (vv:num->A)) 0 = xx /\
                ((3 |-> (w:A)) (vv:num->A)) 2 = tt /\
                ((3 |-> (w:A)) (vv:num->A)) 3 = w`
  STRIP_ASSUME_TAC THENL
   [ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER; ARITH_EQ]; ALL_TAC] THEN
  SUBGOAL_THEN `ebv_in D (E:A->A->bool) B leq w xx
                  (bvalf D E B leq ((3 |-> (w:A)) (vv:num->A)) (3 %% 0))`
  ASSUME_TAC THENL
   [MP_TAC(ISPECL [`3`;`0`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
      `(3 |-> (w:A)) (vv:num->A)`] BVALF_MEM) THEN ASM_SIMP_TAC[];
                  ALL_TAC] THEN
  SUBGOAL_THEN `ebv_in D (E:A->A->bool) B leq tt w
                  (bvalf D E B leq ((3 |-> (w:A)) (vv:num->A)) (2 %% 3))`
  ASSUME_TAC THENL
   [MP_TAC(ISPECL [`2`;`3`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
      `(3 |-> (w:A)) (vv:num->A)`] BVALF_MEM) THEN ASM_SIMP_TAC[];
                  ALL_TAC] THEN
  SUBGOAL_THEN `emeet D (E:A->A->bool) B leq
                  (bvalf D E B leq ((3 |-> (w:A)) (vv:num->A)) (3 %% 0))
                  (bvalf D E B leq ((3 |-> (w:A)) (vv:num->A)) (2 %% 3))
                  (bvalf D E B leq ((3 |-> (w:A)) (vv:num->A))
                   ((3 %% 0) && (2 %% 3)))`
  ASSUME_TAC THENL
   [MP_TAC(ISPECL [`3 %% 0`;`2 %% 3`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
      `(3 |-> (w:A)) (vv:num->A)`] BVALF_AND_MEET) THEN ASM_SIMP_TAC[];
                  ALL_TAC] THEN
  SUBGOAL_THEN
    `(bvalf D (E:A->A->bool) B leq ((3 |-> (w:A)) (vv:num->A)) (3 %% 0)) IN D`
  ASSUME_TAC THENL
   [MP_TAC(ISPECL [`3 %% 0`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
      `(3 |-> (w:A)) (vv:num->A)`] BVALF_SPEC) THEN ASM_SIMP_TAC[];
                  ALL_TAC] THEN
  SUBGOAL_THEN
    `(bvalf D (E:A->A->bool) B leq ((3 |-> (w:A)) (vv:num->A)) (2 %% 3)) IN D`
  ASSUME_TAC THENL
   [MP_TAC(ISPECL [`2 %% 3`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
      `(3 |-> (w:A)) (vv:num->A)`] BVALF_SPEC) THEN ASM_SIMP_TAC[];
                  ALL_TAC] THEN
  SUBGOAL_THEN `zwx:A = bvalf D E B leq ((3 |-> (w:A)) (vv:num->A)) (3 %% 0)`
  SUBST_ALL_TAC THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`w:A`;`xx:A`;
      `zwx:A`;`bvalf D E B leq ((3 |-> (w:A)) (vv:num->A)) (3 %% 0)`]
                     EBV_IN_UNIQUE) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `ztw:A = bvalf D E B leq ((3 |-> (w:A)) (vv:num->A)) (2 %% 3)`
  SUBST_ALL_TAC THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`tt:A`;`w:A`;
      `ztw:A`;`bvalf D E B leq ((3 |-> (w:A)) (vv:num->A)) (2 %% 3)`]
                       EBV_IN_UNIQUE) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN
    `m:A = bvalf D E B leq ((3 |-> (w:A)) (vv:num->A)) ((3 %% 0) && (2 %% 3))`
  SUBST_ALL_TAC THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
      `bvalf D E B leq ((3 |-> (w:A)) (vv:num->A)) (3 %% 0)`;
      `bvalf D E B leq ((3 |-> (w:A)) (vv:num->A)) (2 %% 3)`;
      `m:A`;
      `bvalf D E B leq ((3 |-> (w:A)) (vv:num->A)) ((3 %% 0) && (2 %% 3))`]
      EMEET_UNIQUE) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MATCH_MP_TAC(ISPECL [`3`; `(3 %% 0) && (2 %% 3)`;
    `D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`vv:num->A`;`w:A`]
      BVALF_EX_UB) THEN
  ASM_REWRITE_TAC[]);;

(* ------------------------------------------------------------------ *)
(* F5, V^B |= ZFC:  UNION axiom.   [[union_ax]] = top.                 *)
(* union_ax = !!0 ?!1 !!2. (2 in 1) <-> ?- 3 in 0. (2 in 3).           *)
(* Peel !!0 (container xx), witness the union name un (EUNIONDOM +      *)
(* EUNIONNAME + EUNIONNAME_BNAME), peel !!2 (test elt tt); the IFF      *)
(* reduces to a value-equality  [[tt in un]] = [[?w in xx. tt in w]],   *)
(* which is antisymmetry glued from the two SUP directions             *)
(* UNION_SUP_LE / UNION_SUP_GE.                                        *)
(* ------------------------------------------------------------------ *)

let BVALF_UNION = prove
 (`!D (E:A->A->bool) B leq v.
      model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
      valuation D v /\ (!i. bname D E B (v i))
      ==> etop D E B leq (bvalf D E B leq v union_ax)`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `eporder D (E:A->A->bool) B leq` ASSUME_TAC THENL
   [ASM_MESON_TAC[ECBA_IMP_BALG; EBALG_IMP_PORDER]; ALL_TAC] THEN
  REWRITE_TAC[union_ax] THEN
  (* peel !!0 -> xx (the container / family) *)
  MP_TAC(ISPECL [`0`; `?? 1 (!! 2 ((2 %% 1) <-> ??- 3 0 (2 %% 3)))`;
    `D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`v:num->A`] BVALF_ALL_TOP) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  X_GEN_TAC `xx:A` THEN STRIP_TAC THEN
  SUBGOAL_THEN `valuation D ((0 |-> (xx:A)) (v:num->A)) /\
                (!i. bname D E B (((0 |-> (xx:A)) (v:num->A)) i))`
  STRIP_ASSUME_TAC THENL
   [CONJ_TAC THENL
     [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[];
      MATCH_MP_TAC BNAMEVAL_VALMOD THEN ASM_REWRITE_TAC[]]; ALL_TAC] THEN
  ABBREV_TAC `v0 = (0 |-> (xx:A)) (v:num->A)` THEN
  (* build the union-name domain W and the union name un *)
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`xx:A`] EUNIONDOM_EXISTS) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `W:A` STRIP_ASSUME_TAC) THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`xx:A`;`W:A`]
    EUNIONNAME_EXISTS) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `un:A` STRIP_ASSUME_TAC) THEN
  SUBGOAL_THEN `bname D (E:A->A->bool) B un` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`xx:A`;`W:A`;`un:A`]
                 EUNIONNAME_BNAME) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* witness un for  ??1 *)
  MATCH_MP_TAC(ISPECL [`1`; `!! 2 ((2 %% 1) <-> ??- 3 0 (2 %% 3))`;
    `D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`v0:num->A`;`un:A`]
      BVALF_EX_TOP) THEN
  ASM_REWRITE_TAC[] THEN
  SUBGOAL_THEN `valuation D ((1 |-> (un:A)) (v0:num->A)) /\
                (!i. bname D E B (((1 |-> (un:A)) (v0:num->A)) i))`
  STRIP_ASSUME_TAC THENL
   [CONJ_TAC THENL
     [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[];
      MATCH_MP_TAC BNAMEVAL_VALMOD THEN ASM_REWRITE_TAC[]]; ALL_TAC] THEN
  ABBREV_TAC `v1 = (1 |-> (un:A)) (v0:num->A)` THEN
  (* peel !!2 -> tt (the test element) *)
  MP_TAC(ISPECL [`2`; `(2 %% 1) <-> ??- 3 0 (2 %% 3)`;
    `D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`v1:num->A`] BVALF_ALL_TOP) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  X_GEN_TAC `tt:A` THEN STRIP_TAC THEN
  SUBGOAL_THEN `valuation D ((2 |-> (tt:A)) (v1:num->A)) /\
                (!i. bname D E B (((2 |-> (tt:A)) (v1:num->A)) i))`
  STRIP_ASSUME_TAC THENL
   [CONJ_TAC THENL
     [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[];
      MATCH_MP_TAC BNAMEVAL_VALMOD THEN ASM_REWRITE_TAC[]]; ALL_TAC] THEN
  ABBREV_TAC `vv = (2 |-> (tt:A)) (v1:num->A)` THEN
  SUBGOAL_THEN `(vv:num->A) 0 = xx /\ (vv:num->A) 1 = un /\ (vv:num->A) 2 = tt`
  STRIP_ASSUME_TAC THENL
   [MAP_EVERY EXPAND_TAC ["vv";"v1";"v0"] THEN
    SIMP_TAC[VALMOD_OTHER; VALMOD_BASIC; ARITH_EQ]; ALL_TAC] THEN
  (* IFF_TOP -> value-equality *)
  MP_TAC(ISPECL [`2 %% 1`; `??- 3 0 (2 %% 3)`;
    `D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`vv:num->A`] BVALF_IFF_TOP) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  REWRITE_TAC[Existsmem_DEF] THEN
  (* goal: bvalf vv (2%%1) = bvalf vv (?? 3 ((3%%0)&&(2%%3))) *)
  ABBREV_TAC `zun = bvalf D (E:A->A->bool) B leq (vv:num->A) (2 %% 1)` THEN
  SUBGOAL_THEN `ebv_in D (E:A->A->bool) B leq tt un zun` ASSUME_TAC THENL
   [EXPAND_TAC "zun" THEN
    MP_TAC(ISPECL
           [`2`;`1`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`vv:num->A`]
           BVALF_MEM) THEN ASM_SIMP_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(zun:A) IN D` ASSUME_TAC THENL
   [EXPAND_TAC "zun" THEN
    MP_TAC(ISPECL
           [`2 %% 1`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`vv:num->A`]
           BVALF_SPEC) THEN ASM_SIMP_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) zun B` ASSUME_TAC THENL
   [MP_TAC(ISPECL
           [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`tt:A`;`un:A`;`zun:A`]
           EBV_IN_IN_B) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN
    `(bvalf D (E:A->A->bool) B leq vv (?? 3 ((3 %% 0) && (2 %% 3)))) IN D`
  ASSUME_TAC THENL
   [MP_TAC(ISPECL
           [`?? 3 ((3 %% 0) && (2 %% 3))`;`D:A->bool`;`E:A->A->bool`;`B:A`;
            `leq:A`;`vv:num->A`] BVALF_SPEC) THEN ASM_SIMP_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN
    `(E:A->A->bool) (bvalf D E B leq vv (?? 3 ((3 %% 0) && (2 %% 3)))) B`
  ASSUME_TAC THENL
   [MP_TAC(ISPECL
           [`?? 3 ((3 %% 0) && (2 %% 3))`;`D:A->bool`;`E:A->A->bool`;`B:A`;
            `leq:A`;`vv:num->A`] BVALF_IN_B) THEN ASM_SIMP_TAC[]; ALL_TAC] THEN
  (* INV form for UNION_SUP_LE *)
  SUBGOAL_THEN `!s qs. s IN D /\ qs IN D /\ eapply D (E:A->A->bool) un s qs
                       ==> euuval D E B leq xx s qs`
  ASSUME_TAC THENL
   [REPEAT STRIP_TAC THEN
    MP_TAC(ISPECL
           [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`xx:A`;`W:A`;`un:A`;
            `s:A`;`qs:A`] UNION_APPLY_INV) THEN
    ASM_REWRITE_TAC[] THEN STRIP_TAC THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* antisymmetry: zun = SUP *)
  MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`zun:A`;
    `bvalf (D:A->bool) (E:A->A->bool) (B:A) (leq:A) (vv:num->A)
           (?? 3 ((3 %% 0) && (2 %% 3)))`] EPORDER_ANTISYM) THEN
  ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`vv:num->A`;
      `xx:A`;`un:A`;`tt:A`;`zun:A`] UNION_SUP_LE) THEN ASM_REWRITE_TAC[];
    MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`vv:num->A`;
      `xx:A`;`un:A`;`tt:A`;`W:A`;`zun:A`] UNION_SUP_GE) THEN
    ASM_REWRITE_TAC[]]);;

(* ================================================================== *)
(* F5, V^B:  general substitution / Leibniz congruence for bval.       *)
(* If w,t are B-names with Boolean equality value ewt = [[w=t]], then  *)
(* for every formula p,   ewt MEET [[p]]_{x:=w} <= [[p]]_{x:=t}.        *)
(* (Prerequisite for the SEPARATION V^B axiom.)                        *)
(* ------------------------------------------------------------------ *)

(* --- small helpers not yet in the file --- *)

let VALMOD_VALMOD = prove
 (`!(v:num->A) x a b. (x |-> a) ((x |-> b) v) = (x |-> a) v`,
  REPEAT GEN_TAC THEN REWRITE_TAC[FUN_EQ_THM] THEN X_GEN_TAC `i:num` THEN
  ASM_CASES_TAC `i:num = x` THENL
   [ASM_SIMP_TAC[VALMOD_BASIC]; ASM_SIMP_TAC[VALMOD_OTHER]]);;

let BVALF_IND = prove
 (`!p D (E:A->A->bool) B leq v.
      model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
      valuation D v /\ (!i. bname D E B (v i))
      ==> bvalf D E B leq v p IN D`,
  MESON_TAC[BVALF_SPEC]);;

(* --- shared per-case setup tactic (introduces D..m, derives the       *)
(*     structural side-conditions common to all five induction cases) --- *)

let BVAL_SUBST_CONG =
  let SUBST_SETUP =
    REPEAT GEN_TAC THEN STRIP_TAC THEN
    SUBGOAL_THEN
     `ebalg D (E:A->A->bool) B leq /\ eporder D (E:A->A->bool) B leq`
      STRIP_ASSUME_TAC THENL
     [ASM_MESON_TAC[ECBA_IMP_BALG; EBALG_IMP_PORDER]; ALL_TAC] THEN
    SUBGOAL_THEN `(E:A->A->bool) ewt B` ASSUME_TAC THENL
     [ASM_MESON_TAC[EBV_EQ_IN_B]; ALL_TAC] THEN
    SUBGOAL_THEN
      `(valuation D ((x |-> w) (v:num->A)) /\
        (!i. bname D (E:A->A->bool) B (((x |-> w) (v:num->A)) i))) /\
       (valuation D ((x |-> t) (v:num->A)) /\
        (!i. bname D (E:A->A->bool) B (((x |-> t) (v:num->A)) i)))`
      STRIP_ASSUME_TAC THENL
     [REPEAT CONJ_TAC THEN
      (MATCH_MP_TAC VALUATION_VALMOD ORELSE MATCH_MP_TAC BNAMEVAL_VALMOD) THEN
      ASM_REWRITE_TAC[]; ALL_TAC] THEN
    FIRST_ASSUM(STRIP_ASSUME_TAC o MATCH_MP EMEET_LE) THEN
    FIRST_ASSUM(STRIP_ASSUME_TAC o MATCH_MP EMEET_IN) in
  prove
 (`!p D (E:A->A->bool) B leq v x w t ewt m.
      model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
      valuation D v /\ (!i. bname D E B (v i)) /\
      w IN D /\ t IN D /\ bname D E B w /\ bname D E B t /\
      ewt IN D /\ ebv_eq D E B leq w t ewt /\
      emeet D E B leq ewt (bvalf D E B leq ((x |-> w) v) p) m
      ==> erel D E leq m (bvalf D E B leq ((x |-> t) v) p)`,
  MATCH_MP_TAC form_INDUCT THEN REPEAT CONJ_TAC THENL
   [ (* ============================ False ============================ *)
    SUBST_SETUP THEN
    SUBGOAL_THEN
      `bvalf D (E:A->A->bool) B leq ((x |-> t) v) False =
       bvalf D (E:A->A->bool) B leq ((x |-> w) v) False`
      (fun th -> REWRITE_TAC[th]) THENL
     [SUBGOAL_THEN
        `ebot D (E:A->A->bool) B leq (bvalf D E B leq ((x |-> w) v) False) /\
         ebot D (E:A->A->bool) B leq (bvalf D E B leq ((x |-> t) v) False)`
        STRIP_ASSUME_TAC THENL
       [CONJ_TAC THEN MATCH_MP_TAC BVALF_FALSE THEN ASM_REWRITE_TAC[];
        ASM_MESON_TAC[EBOT_UNIQUE]];
      ASM_REWRITE_TAC[]];
    (* ============================ i %% j ============================ *)
    SUBST_SETUP THEN
    SUBGOAL_THEN `!i. (v:num->A) i IN D` ASSUME_TAC THENL
     [ASM_MESON_TAC[valuation]; ALL_TAC] THEN
    ASM_CASES_TAC `a0:num = x` THEN ASM_CASES_TAC `a1:num = x` THENL
     [ (* a0 = x, a1 = x : x %% x *)
      UNDISCH_THEN `a1:num = x` SUBST_ALL_TAC THEN
      UNDISCH_THEN `a0:num = x` SUBST_ALL_TAC THEN
      SUBGOAL_THEN `bvalf D (E:A->A->bool) B leq ((x|->w)v) (x %% x) IN D /\
                    bvalf D (E:A->A->bool) B leq ((x|->t)v) (x %% x) IN D`
        STRIP_ASSUME_TAC THENL
       [CONJ_TAC THENL
         [MP_TAC(ISPECL[`x %% x`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
                        `(x|->w)(v:num->A)`] BVALF_SPEC);
          MP_TAC(ISPECL[`x %% x`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
                        `(x|->t)(v:num->A)`] BVALF_SPEC)] THEN
        ASM_REWRITE_TAC[] THEN STRIP_TAC THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
      SUBGOAL_THEN
        `ebv_in D (E:A->A->bool) B leq w w
         (bvalf D E B leq ((x|->w)v) (x %% x))`
        ASSUME_TAC THENL
       [MP_TAC(ISPECL[`x:num`;`x:num`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
                      `(x|->w)(v:num->A)`] BVALF_MEM) THEN
        ASM_SIMP_TAC[VALMOD_BASIC]; ALL_TAC] THEN
      SUBGOAL_THEN
        `ebv_in D (E:A->A->bool) B leq t t
         (bvalf D E B leq ((x|->t)v) (x %% x))`
        ASSUME_TAC THENL
       [MP_TAC(ISPECL[`x:num`;`x:num`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
                      `(x|->t)(v:num->A)`] BVALF_MEM) THEN
        ASM_SIMP_TAC[VALMOD_BASIC]; ALL_TAC] THEN
      MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`t:A`;`w:A`]
             EBV_TOTAL) THEN
      ASM_REWRITE_TAC[] THEN
      DISCH_THEN(CONJUNCTS_THEN2 (X_CHOOSE_THEN `h:A` STRIP_ASSUME_TAC)
                 (K ALL_TAC)) THEN
      SUBGOAL_THEN `(E:A->A->bool) h B` ASSUME_TAC THENL
       [MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`t:A`;
                            `w:A`;`h:A`] EBV_IN_IN_B) THEN
        ASM_REWRITE_TAC[]; ALL_TAC] THEN
      SUBGOAL_THEN `?m2. emeet D (E:A->A->bool) B leq ewt h m2`
        (X_CHOOSE_THEN `m2:A` ASSUME_TAC) THENL
        [MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`ewt:A`;
                             `h:A`] EBALG_MEET) THEN
         ASM_REWRITE_TAC[]; ALL_TAC] THEN
      MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`ewt:A`;`h:A`;
                    `m2:A`] EMEET_IN) THEN
      ASM_REWRITE_TAC[] THEN STRIP_TAC THEN
      SUBGOAL_THEN `erel D (E:A->A->bool) leq m h` ASSUME_TAC THENL
       [MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
          `w:A`;`t:A`;`w:A`;`ewt:A`;
          `bvalf D (E:A->A->bool) B leq ((x|->w)v) (x %% x)`;`h:A`;`m:A`]
                      EBV_IN_CONG_L) THEN
        ASM_REWRITE_TAC[]; ALL_TAC] THEN
      SUBGOAL_THEN
        `erel D (E:A->A->bool) leq m2 (bvalf D E B leq ((x|->t)v) (x %% x))`
        ASSUME_TAC THENL
        [MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
          `w:A`;`t:A`;`t:A`;`ewt:A`;`h:A`;
          `bvalf D (E:A->A->bool) B leq ((x|->t)v) (x %% x)`;`m2:A`]
                        EBV_IN_CONG_R) THEN
        ASM_REWRITE_TAC[]; ALL_TAC] THEN
      SUBGOAL_THEN `erel D (E:A->A->bool) leq m m2` ASSUME_TAC THENL
       [MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
          `ewt:A`;`h:A`;`m2:A`;`m:A`] EMEET_GREATEST) THEN
        ASM_REWRITE_TAC[]; ALL_TAC] THEN
      MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
                          `m:A`;`m2:A`;
                          `bvalf D (E:A->A->bool) B leq ((x|->t)v) (x %% x)`]
          EPORDER_TRANS) THEN
      ASM_REWRITE_TAC[] THEN
      MATCH_MP_TAC(ISPECL[`x %% x`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
                          `(x|->t)(v:num->A)`] BVALF_IN_B) THEN
      ASM_REWRITE_TAC[];
      (* a0 = x, a1 <> x : x %% a1 *)
      UNDISCH_THEN `a0:num = x` SUBST_ALL_TAC THEN
      SUBGOAL_THEN `bvalf D (E:A->A->bool) B leq ((x|->w)v) (x %% a1) IN D /\
                    bvalf D (E:A->A->bool) B leq ((x|->t)v) (x %% a1) IN D`
        STRIP_ASSUME_TAC THENL
       [CONJ_TAC THENL
         [MP_TAC(ISPECL[`x %% a1`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
