      `?z. emeet D (E:A->A->bool) B leq ewt (bvalf D E B leq ((x|->w)v) a1) z`
      (X_CHOOSE_THEN `m6:A` ASSUME_TAC) THENL
     [MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`ewt:A`;
                          `bvalf D (E:A->A->bool) B leq ((x|->w)v) a1`]
                   EBALG_MEET) THEN
      ASM_REWRITE_TAC[]; ALL_TAC] THEN
    MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`ewt:A`;
                  `bvalf D (E:A->A->bool) B leq ((x|->w)v) a1`;`m6:A`]
           EMEET_IN) THEN
    ASM_REWRITE_TAC[] THEN STRIP_TAC THEN
    SUBGOAL_THEN
      `?z. emeet D (E:A->A->bool) B leq mm (bvalf D E B leq ((x|->w)v) a0) z`
      (X_CHOOSE_THEN `m5:A` ASSUME_TAC) THENL
     [MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`mm:A`;
                          `bvalf D (E:A->A->bool) B leq ((x|->w)v) a0`]
                   EBALG_MEET) THEN
      ASM_REWRITE_TAC[]; ALL_TAC] THEN
    MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`mm:A`;
                  `bvalf D (E:A->A->bool) B leq ((x|->w)v) a0`;`m5:A`]
           EMEET_IN) THEN
    ASM_REWRITE_TAC[] THEN STRIP_TAC THEN
    SUBGOAL_THEN `bvalf D (E:A->A->bool) B leq ((x|->w)v)(a0-->a1) IN D /\
                  E (bvalf D E B leq ((x|->w)v)(a0-->a1)) B /\
                  bvalf D E B leq ((x|->t)v)(a0-->a1) IN D /\
                  E (bvalf D E B leq ((x|->t)v)(a0-->a1)) B`
      STRIP_ASSUME_TAC THENL
     [REPEAT CONJ_TAC THEN
      (MATCH_MP_TAC BVALF_IND ORELSE MATCH_MP_TAC BVALF_IN_B) THEN
      ASM_REWRITE_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN `erel D (E:A->A->bool) leq mm mm` ASSUME_TAC THENL
     [MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`mm:A`]
                   EPORDER_REFL) THEN
      ASM_REWRITE_TAC[]; ALL_TAC] THEN
    MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`m:A`;
                  `bvalf D (E:A->A->bool) B leq ((x|->t)v) a0`;`mm:A`]
           EMEET_LE) THEN
    ASM_REWRITE_TAC[] THEN STRIP_TAC THEN
    SUBGOAL_THEN `erel D (E:A->A->bool) leq mm ewt` ASSUME_TAC THENL
     [MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`mm:A`;
                          `m:A`;`ewt:A`] EPORDER_TRANS) THEN
      ASM_REWRITE_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN
      `erel D (E:A->A->bool) leq mm (bvalf D E B leq ((x|->w)v)(a0-->a1))`
      ASSUME_TAC THENL
      [MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`mm:A`;
                           `m:A`;`bvalf D (E:A->A->bool) B leq ((x|->w)v)
                                  (a0-->a1)`] EPORDER_TRANS) THEN
       ASM_REWRITE_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN `erel D (E:A->A->bool) leq m3 (bvalf D E B leq ((x|->w)v) a0)`
      ASSUME_TAC THENL
      [USE_THEN "IH0"
       (MATCH_MP_TAC o
        ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`v:num->A`;`x:num`;
               `t:A`;`w:A`;`ewt:A`;`m3:A`]) THEN
       ASM_REWRITE_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN `erel D (E:A->A->bool) leq mm m3` ASSUME_TAC THENL
     [MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`ewt:A`;
                          `bvalf D (E:A->A->bool) B leq ((x|->t)v) a0`;`m3:A`;
                          `mm:A`] EMEET_GREATEST) THEN
      ASM_REWRITE_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN `erel D (E:A->A->bool) leq mm (bvalf D E B leq ((x|->w)v) a0)`
      ASSUME_TAC THENL
      [MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`mm:A`;
                           `m3:A`;`bvalf D (E:A->A->bool) B leq ((x|->w)v) a0`]
                    EPORDER_TRANS) THEN
       ASM_REWRITE_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN `erel D (E:A->A->bool) leq m5 (bvalf D E B leq ((x|->w)v) a1)`
      ASSUME_TAC THENL
      [MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`mm:A`;
        `bvalf D (E:A->A->bool) B leq ((x|->w)v) a0`;
        `bvalf D (E:A->A->bool) B leq ((x|->w)v) a1`;
        `bvalf D (E:A->A->bool) B leq ((x|->w)v)(a0-->a1)`;`m5:A`]
                      EBIMP_MEET_LE) THEN
      ASM_REWRITE_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN `erel D (E:A->A->bool) leq mm m5` ASSUME_TAC THENL
     [MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`mm:A`;
                          `bvalf D (E:A->A->bool) B leq ((x|->w)v) a0`;`m5:A`;
                          `mm:A`] EMEET_GREATEST) THEN
      ASM_REWRITE_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN `erel D (E:A->A->bool) leq mm (bvalf D E B leq ((x|->w)v) a1)`
      ASSUME_TAC THENL
      [MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`mm:A`;
                           `m5:A`;`bvalf D (E:A->A->bool) B leq ((x|->w)v) a1`]
                    EPORDER_TRANS) THEN
       ASM_REWRITE_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN `erel D (E:A->A->bool) leq m6 (bvalf D E B leq ((x|->t)v) a1)`
      ASSUME_TAC THENL
      [USE_THEN "IH1"
       (MATCH_MP_TAC o
        ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`v:num->A`;`x:num`;
               `w:A`;`t:A`;`ewt:A`;`m6:A`]) THEN
       ASM_REWRITE_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN `erel D (E:A->A->bool) leq mm m6` ASSUME_TAC THENL
     [MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`ewt:A`;
                          `bvalf D (E:A->A->bool) B leq ((x|->w)v) a1`;`m6:A`;
                          `mm:A`] EMEET_GREATEST) THEN
      ASM_REWRITE_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN `erel D (E:A->A->bool) leq mm (bvalf D E B leq ((x|->t)v) a1)`
      ASSUME_TAC THENL
      [MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`mm:A`;
                           `m6:A`;`bvalf D (E:A->A->bool) B leq ((x|->t)v) a1`]
                    EPORDER_TRANS) THEN
       ASM_REWRITE_TAC[]; ALL_TAC] THEN
    MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`m:A`;
      `bvalf D (E:A->A->bool) B leq ((x|->t)v) a0`;
      `bvalf D (E:A->A->bool) B leq ((x|->t)v) a1`;
      `bvalf D (E:A->A->bool) B leq ((x|->t)v)(a0-->a1)`;`mm:A`]
         EBIMP_LE_IMP) THEN
    ASM_REWRITE_TAC[];
    (* ============================ !! n p ============================ *)
    X_GEN_TAC `a0:num` THEN X_GEN_TAC `a1:form` THEN
    DISCH_THEN(LABEL_TAC "IHP") THEN
    SUBST_SETUP THEN
    SUBGOAL_THEN `!i. (v:num->A) i IN D` ASSUME_TAC THENL
     [ASM_MESON_TAC[valuation]; ALL_TAC] THEN
    ASM_CASES_TAC `a0:num = x` THENL
     [ (* shadowed: a0 = x -- outer binder shadows x, no dependence *)
      UNDISCH_THEN `a0:num = x` SUBST_ALL_TAC THEN
      SUBGOAL_THEN
        `bvalf D (E:A->A->bool) B leq ((x|->t)v)(!! x a1) = bvalf D E B leq
         ((x|->w)v)(!! x a1)`
        ASSUME_TAC THENL
       [REWRITE_TAC[bvalf] THEN AP_TERM_TAC THEN REWRITE_TAC[FUN_EQ_THM] THEN
        GEN_TAC THEN
        REWRITE_TAC[bval] THEN REWRITE_TAC[VALMOD_VALMOD]; ALL_TAC] THEN
      ASM_REWRITE_TAC[];
      (* a0 <> x : genuine bound variable, use lower-bound + IHP *)
      SUBGOAL_THEN `bvalf D (E:A->A->bool) B leq ((x|->w)v)(!! a0 a1) IN D /\
                    E (bvalf D E B leq ((x|->w)v)(!! a0 a1)) B`
        STRIP_ASSUME_TAC THENL
        [CONJ_TAC THENL [MATCH_MP_TAC BVALF_IND; MATCH_MP_TAC BVALF_IN_B] THEN
         ASM_REWRITE_TAC[]; ALL_TAC] THEN
      MP_TAC(ISPECL[`!! a0 a1`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
                    `(x|->t)(v:num->A)`] BVALF_SPEC) THEN
      ASM_REWRITE_TAC[] THEN DISCH_THEN(MP_TAC o CONJUNCT2) THEN
      REWRITE_TAC[bval] THEN
      DISCH_THEN(X_CHOOSE_THEN `St:A`
                 (CONJUNCTS_THEN2 ASSUME_TAC
                  (CONJUNCTS_THEN2 (LABEL_TAC "CHARt") ASSUME_TAC))) THEN
      MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`St:A`;
         `bvalf D (E:A->A->bool) B leq ((x|->t)v)(!! a0 a1)`;`m:A`]
                   EGLB_GREATEST) THEN
      ASM_REWRITE_TAC[] THEN REWRITE_TAC[elbound] THEN ASM_REWRITE_TAC[] THEN
      X_GEN_TAC `zz:A` THEN STRIP_TAC THEN
      USE_THEN "CHARt" (fun ch ->
        X_CHOOSE_THEN `a:A` STRIP_ASSUME_TAC
          (EQ_MP (MP (SPEC `zz:A` ch) (ASSUME `(zz:A) IN (D:A->bool)`))
                 (ASSUME `(E:A->A->bool) (zz:A) (St:A)`))) THEN
      SUBGOAL_THEN
        `valuation D ((a0|->a)(v:num->A)) /\
         (!i. bname D (E:A->A->bool) B (((a0|->a)(v:num->A)) i))`
        STRIP_ASSUME_TAC THENL
       [CONJ_TAC THENL
        [MATCH_MP_TAC VALUATION_VALMOD; MATCH_MP_TAC BNAMEVAL_VALMOD] THEN
        ASM_REWRITE_TAC[]; ALL_TAC] THEN
      SUBGOAL_THEN
        `(valuation D ((x|->t)((a0|->a)v)) /\
          (!i. bname D (E:A->A->bool) B (((x|->t)((a0|->a)(v:num->A))) i))) /\
         (valuation D ((x|->w)((a0|->a)v)) /\
          (!i. bname D (E:A->A->bool) B (((x|->w)((a0|->a)(v:num->A))) i)))`
        STRIP_ASSUME_TAC THENL
       [REPEAT CONJ_TAC THEN
        (MATCH_MP_TAC VALUATION_VALMOD ORELSE
         MATCH_MP_TAC BNAMEVAL_VALMOD) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
      MP_TAC(ISPECL[`v:num->A`;`a0:num`;`x:num`;`a:A`;`t:A`] VALMOD_SWAP) THEN
      ASM_REWRITE_TAC[] THEN DISCH_TAC THEN
      MP_TAC(ISPECL[`v:num->A`;`a0:num`;`x:num`;`a:A`;`w:A`] VALMOD_SWAP) THEN
      ASM_REWRITE_TAC[] THEN DISCH_TAC THEN
      SUBGOAL_THEN `zz = bvalf D (E:A->A->bool) B leq ((x|->t)((a0|->a)v)) a1`
        SUBST_ALL_TAC THENL
        [MATCH_MP_TAC(ISPECL[`a1:form`;`D:A->bool`;`E:A->A->bool`;`B:A`;
                             `leq:A`;`(x|->t)((a0|->a)(v:num->A))`;`zz:A`]
                      BVALF_EQ) THEN
         ASM_REWRITE_TAC[] THEN
        UNDISCH_TAC
          `bval D (E:A->A->bool) B leq ((a0|->a)((x|->t)v)) a1 zz` THEN
        ASM_REWRITE_TAC[]; ALL_TAC] THEN
      SUBGOAL_THEN
        `erel D (E:A->A->bool) leq (bvalf D E B leq ((x|->w)v)(!! a0 a1))
         (bvalf D E B leq ((x|->w)((a0|->a)v)) a1)`
        ASSUME_TAC THENL
       [MP_TAC(ISPECL[`a0:num`;`a1:form`;`D:A->bool`;`E:A->A->bool`;`B:A`;
                      `leq:A`;`(x|->w)(v:num->A)`;`a:A`] BVALF_ALL_LB) THEN
        ASM_REWRITE_TAC[]; ALL_TAC] THEN
      SUBGOAL_THEN
        `bvalf D (E:A->A->bool) B leq ((x|->w)((a0|->a)v)) a1 IN D /\
         E (bvalf D E B leq ((x|->w)((a0|->a)v)) a1) B` STRIP_ASSUME_TAC THENL
       [CONJ_TAC THENL [MATCH_MP_TAC BVALF_IND; MATCH_MP_TAC BVALF_IN_B] THEN
        ASM_REWRITE_TAC[]; ALL_TAC] THEN
      SUBGOAL_THEN
        `?z. emeet D (E:A->A->bool) B leq ewt
         (bvalf D E B leq ((x|->w)((a0|->a)v)) a1) z`
        (X_CHOOSE_THEN `mya:A` ASSUME_TAC) THENL
       [MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`ewt:A`;
                            `bvalf D (E:A->A->bool) B leq ((x|->w)((a0|->a)v))
                             a1`] EBALG_MEET) THEN
        ASM_REWRITE_TAC[]; ALL_TAC] THEN
      MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`ewt:A`;
                    `bvalf D (E:A->A->bool) B leq ((x|->w)((a0|->a)v)) a1`;
                    `mya:A`] EMEET_IN) THEN
      ASM_REWRITE_TAC[] THEN STRIP_TAC THEN
      SUBGOAL_THEN `erel D (E:A->A->bool) leq ewt ewt` ASSUME_TAC THENL
       [MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`ewt:A`]
                     EPORDER_REFL) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
      SUBGOAL_THEN `erel D (E:A->A->bool) leq m mya` ASSUME_TAC THENL
       [MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`ewt:A`;
          `bvalf D (E:A->A->bool) B leq ((x|->w)v)(!! a0 a1)`;`ewt:A`;
          `bvalf D (E:A->A->bool) B leq ((x|->w)((a0|->a)v)) a1`;`m:A`;`mya:A`]
                       EMEET_MONO) THEN
        ASM_REWRITE_TAC[]; ALL_TAC] THEN
      SUBGOAL_THEN
        `erel D (E:A->A->bool) leq mya
         (bvalf D E B leq ((x|->t)((a0|->a)v)) a1)` ASSUME_TAC THENL
       [USE_THEN "IHP"
        (MATCH_MP_TAC o
         ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`(a0|->a)(v:num->A)`;
                `x:num`;`w:A`;`t:A`;`ewt:A`;`mya:A`]) THEN
        ASM_REWRITE_TAC[]; ALL_TAC] THEN
      SUBGOAL_THEN `E (bvalf D (E:A->A->bool) B leq ((x|->t)((a0|->a)v)) a1) B`
        ASSUME_TAC THENL
        [MATCH_MP_TAC BVALF_IN_B THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
      MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`m:A`;
                          `mya:A`;`bvalf D (E:A->A->bool) B leq
                                   ((x|->t)((a0|->a)v)) a1`]
                   EPORDER_TRANS) THEN
      ASM_REWRITE_TAC[]]]);;

(* ------------------------------------------------------------------------- *)
(* SEPARATION V^B axiom, sub-lemma B: value-equality                         *)
(*   [[tt IN sn]] = [[tt IN aa]] MEET [[p]]_{x:=tt}                          *)
(* for a separation-name sn with dom sn = dom aa and                         *)
(*   sn(w) = aa(w) MEET [[p]]_{x:=w}.  Proved LE + GE, combined by ANTISYM.  *)
(* ------------------------------------------------------------------------- *)

let EBV_IN_SEP_LE = prove
 (`!D (E:A->A->bool) B leq v p x aa tt sn zin zia rhs.
      model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
      valuation D v /\ (!i. bname D E B (v i)) /\
      aa IN D /\ tt IN D /\ sn IN D /\
      bname D E B aa /\ bname D E B tt /\ bname D E B sn /\
      eisfun D E sn /\
      (!w. w IN D ==> (eindom D E sn w <=> eindom D E aa w)) /\
      (!w q m. w IN D /\ q IN D /\ eindom D E aa w /\ eapply D E aa w q /\
               emeet D E B leq q (bvalf D E B leq ((x |-> w) v) p) m
               ==> eapply D E sn w m) /\
      zin IN D /\ zia IN D /\
      ebv_in D E B leq tt sn zin /\
      ebv_in D E B leq tt aa zia /\
      emeet D E B leq zia (bvalf D E B leq ((x |-> tt) v) p) rhs
      ==> erel D E leq zin rhs`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `ebalg D (E:A->A->bool) B leq` ASSUME_TAC THENL
   [ASM_MESON_TAC[ECBA_IMP_BALG]; ALL_TAC] THEN
  SUBGOAL_THEN `eporder D (E:A->A->bool) B leq` ASSUME_TAC THENL
   [ASM_MESON_TAC[EBALG_IMP_PORDER]; ALL_TAC] THEN
  SUBGOAL_THEN `valuation D ((x |-> tt) (v:num->A))` ASSUME_TAC THENL
   [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `!i. bname D (E:A->A->bool) B (((x |-> tt) (v:num->A)) i)`
    ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`B:A`;`x:num`;`tt:A`;`v:num->A`]
                 BNAMEVAL_VALMOD) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) (bvalf D E B leq ((x |-> tt) v) p) B`
    ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL [`p:form`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
      `(x |-> tt) (v:num->A)`] BVALF_IN_B) THEN ASM_REWRITE_TAC[];
      ALL_TAC] THEN
  SUBGOAL_THEN `(bvalf D (E:A->A->bool) B leq ((x |-> tt) v) p) IN D`
    ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL [`p:form`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
      `(x |-> tt) (v:num->A)`] BVALF_IND) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(rhs:A) IN D /\ (E:A->A->bool) rhs B` STRIP_ASSUME_TAC THENL
   [MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`zia:A`;
      `bvalf D (E:A->A->bool) B leq ((x |-> tt) v) p`;`rhs:A`] EMEET_IN) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`tt:A`;`sn:A`;
    `zin:A`;`rhs:A`] EBV_IN_LE_V) THEN
  ASM_REWRITE_TAC[] THEN
  MAP_EVERY X_GEN_TAC [`y:A`;`qy:A`;`ey:A`;`c:A`] THEN STRIP_TAC THEN
  SUBGOAL_THEN `eindom D (E:A->A->bool) sn y` ASSUME_TAC THENL
   [REWRITE_TAC[eindom] THEN EXISTS_TAC `qy:A` THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `eindom D (E:A->A->bool) aa y` ASSUME_TAC THENL
   [UNDISCH_TAC
    `!w:A. w IN D ==> (eindom D (E:A->A->bool) sn w <=> eindom D E aa w)` THEN
    UNDISCH_TAC `eindom D (E:A->A->bool) sn y` THEN
    UNDISCH_TAC `(y:A) IN D` THEN MESON_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `?q0:A. q0 IN D /\ eapply D (E:A->A->bool) aa y q0`
    (X_CHOOSE_THEN `q0:A` STRIP_ASSUME_TAC) THENL
   [UNDISCH_TAC `eindom D (E:A->A->bool) aa y` THEN REWRITE_TAC[eindom] THEN
    MESON_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `bname D (E:A->A->bool) B y` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`aa:A`;`y:A`]
      UNION_DOM_BNAME) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
