                 [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`tt:A`;`sn:A`;
                  `zin:A`] EBV_IN_IN_B) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) zia B` ASSUME_TAC THENL
