      `bvalf D (E:A->A->bool) B leq ((x |-> tt) v) p`;`zin:A`;`imp:A`]
      EBIMP_IN) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`zia:A`;
    `bvalf D (E:A->A->bool) B leq ((x |-> tt) v) p`;`zin:A`;`imp:A`;`rhs:A`]
    EBIMP_MEET_LE) THEN
  ASM_REWRITE_TAC[] THEN
