    `bvalf D (E:A->A->bool) B leq ((x |-> tt) v) p`] EBALG_MEET) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `eypt:A`) THEN
  SUBGOAL_THEN `(eypt:A) IN D /\ (E:A->A->bool) eypt B` STRIP_ASSUME_TAC THENL
   [MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`ey:A`;
      `bvalf D (E:A->A->bool) B leq ((x |-> tt) v) p`;`eypt:A`] EMEET_IN) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq eypt
                  (bvalf D E B leq ((x |-> y) v) p)` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL [`p:form`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
      `v:num->A`;`x:num`;`tt:A`;`y:A`;`ey:A`;`eypt:A`] BVAL_SUBST_CONG) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq dm c /\
                erel D E leq dm (bvalf D E B leq ((x |-> tt) v) p)`
  STRIP_ASSUME_TAC THENL
   [MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`c:A`;
      `bvalf D (E:A->A->bool) B leq ((x |-> tt) v) p`;`dm:A`] EMEET_LE) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq c qy /\ erel D E leq c ey`
  STRIP_ASSUME_TAC THENL
   [MP_TAC(ISPECL
           [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`qy:A`;`ey:A`;`c:A`]
           EMEET_LE) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq dm qy` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`dm:A`;`c:A`;
      `qy:A`] EPORDER_TRANS) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq dm ey` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`dm:A`;`c:A`;
      `ey:A`] EPORDER_TRANS) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq dm eypt` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`ey:A`;
      `bvalf D (E:A->A->bool) B leq ((x |-> tt) v) p`;`eypt:A`;`dm:A`]
      EMEET_GREATEST) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq dm (bvalf D E B leq ((x |-> y) v) p)`
  ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`dm:A`;`eypt:A`;
                  `bvalf D (E:A->A->bool) B leq ((x |-> y) v) p`]
                   EPORDER_TRANS) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq dm snw` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`qy:A`;
      `bvalf D (E:A->A->bool) B leq ((x |-> y) v) p`;`snw:A`;`dm:A`]
      EMEET_GREATEST) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq dm msn` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`snw:A`;`ey:A`;
                  `msn:A`;`dm:A`] EMEET_GREATEST) THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`dm:A`;`msn:A`;
    `zin:A`] EPORDER_TRANS) THEN ASM_REWRITE_TAC[]);;

let EBV_IN_SEP = prove
 (`!D (E:A->A->bool) B leq v p x aa tt sn zin zia rhs.
      model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
      valuation D v /\ (!i. bname D E B (v i)) /\
      aa IN D /\ tt IN D /\ sn IN D /\
      bname D E B aa /\ bname D E B tt /\ bname D E B sn /\
      eisfun D E sn /\
      (!w. w IN D ==> (eindom D E sn w <=> eindom D E aa w)) /\
      (!w q m. w IN D /\ q IN D /\ eindom D E aa w /\ eapply D E aa w q /\
               emeet D E B leq q (bvalf D E B leq ((x |-> w) v) p) m
               ==> eapply D E sn w m) /\
      zin IN D /\ zia IN D /\
      ebv_in D E B leq tt sn zin /\
      ebv_in D E B leq tt aa zia /\
      emeet D E B leq zia (bvalf D E B leq ((x |-> tt) v) p) rhs
      ==> zin = rhs`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `ebalg D (E:A->A->bool) B leq` ASSUME_TAC THENL
   [ASM_MESON_TAC[ECBA_IMP_BALG]; ALL_TAC] THEN
  SUBGOAL_THEN `eporder D (E:A->A->bool) B leq` ASSUME_TAC THENL
   [ASM_MESON_TAC[EBALG_IMP_PORDER]; ALL_TAC] THEN
  SUBGOAL_THEN `valuation D ((x |-> tt) (v:num->A))` ASSUME_TAC THENL
   [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `!i. bname D (E:A->A->bool) B (((x |-> tt) (v:num->A)) i)`
    ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`B:A`;`x:num`;`tt:A`;`v:num->A`]
                 BNAMEVAL_VALMOD) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) (bvalf D E B leq ((x |-> tt) v) p) B`
    ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL [`p:form`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
      `(x |-> tt) (v:num->A)`] BVALF_IN_B) THEN ASM_REWRITE_TAC[];
      ALL_TAC] THEN
  SUBGOAL_THEN `(rhs:A) IN D /\ (E:A->A->bool) rhs B` STRIP_ASSUME_TAC THENL
   [MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`zia:A`;
      `bvalf D (E:A->A->bool) B leq ((x |-> tt) v) p`;`rhs:A`] EMEET_IN) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) zin B` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`tt:A`;`sn:A`;
                  `zin:A`] EBV_IN_IN_B) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MATCH_MP_TAC(ISPECL
               [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`zin:A`;`rhs:A`]
               EPORDER_ANTISYM) THEN
  ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`v:num->A`;`p:form`;
                  `x:num`;`aa:A`;`tt:A`;`sn:A`;`zin:A`;`zia:A`;`rhs:A`]
                   EBV_IN_SEP_LE) THEN
    ASM_REWRITE_TAC[];
    MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`v:num->A`;`p:form`;
                  `x:num`;`aa:A`;`tt:A`;`sn:A`;`zin:A`;`zia:A`;`rhs:A`]
                   EBV_IN_SEP_GE) THEN
    ASM_REWRITE_TAC[]]);;

(* ------------------------------------------------------------------------- *)
(* SEPARATION V^B axiom, sub-lemma A: the separation B-name.                 *)
(*   ESEPNAME_RAW builds the raw separated set via replacement;              *)
(*   ESEPNAME_EXISTS packages it as a function sn with dom sn = dom aa and   *)
(*     sn(w) = aa(w) MEET [[p]]_{x:=w}; ESEPNAME_BNAME shows sn is a B-name. *)
(*   Helpers: BNAME_MEM_PAIR (members of a B-name are opairs (w,q), E q B),  *)
(*   BNAME_ISFUN (a B-name is a function).                                   *)
(* ------------------------------------------------------------------------- *)

let BNAME_MEM_PAIR = prove
 (`!D (E:A->A->bool) B aa u.
     model D E ZF_AX /\ B IN D /\ aa IN D /\ bname D E B aa /\ u IN D /\ E u aa
     ==> ?w q. w IN D /\ q IN D /\ E q B /\ eopair D (E:A->A->bool) w q u`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  FIRST_X_ASSUM(X_CHOOSE_THEN `ao:A` (X_CHOOSE_THEN `y:A` STRIP_ASSUME_TAC) o
                REWRITE_RULE[bname]) THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`ao:A`;`y:A`]
         EBNSTAGE_CHAR) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `ww:A` STRIP_ASSUME_TAC) THEN
  SUBGOAL_THEN `ebnmem D (E:A->A->bool) B ww aa` STRIP_ASSUME_TAC THENL
   [UNDISCH_TAC `ebnfuns D (E:A->A->bool) B ww y` THEN
    REWRITE_TAC[ebnfuns] THEN
    DISCH_THEN(MP_TAC o SPEC `aa:A` o CONJUNCT2) THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  UNDISCH_TAC `ebnmem D (E:A->A->bool) B ww aa` THEN REWRITE_TAC[ebnmem] THEN
  DISCH_THEN(CONJUNCTS_THEN2 (K ALL_TAC)
    (X_CHOOSE_THEN `cr:A` STRIP_ASSUME_TAC)) THEN
  SUBGOAL_THEN `(E:A->A->bool) u cr` ASSUME_TAC THENL
   [UNDISCH_TAC `esubset D (E:A->A->bool) aa cr` THEN REWRITE_TAC[esubset] THEN
    DISCH_THEN(MP_TAC o SPEC `u:A`) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  UNDISCH_TAC `ecross D (E:A->A->bool) ww B cr` THEN REWRITE_TAC[ecross] THEN
  DISCH_THEN(MP_TAC o SPEC `u:A` o CONJUNCT2) THEN ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `u1:A` (X_CHOOSE_THEN `w1:A` STRIP_ASSUME_TAC)) THEN
  MAP_EVERY EXISTS_TAC [`u1:A`;`w1:A`] THEN ASM_REWRITE_TAC[]);;

let BNAME_ISFUN = prove
 (`!D (E:A->A->bool) B u.
        model D E ZF_AX /\ B IN D /\ u IN D /\ bname D E B u
        ==> eisfun D E u`,
  REPEAT GEN_TAC THEN REWRITE_TAC[bname] THEN
  DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC (CONJUNCTS_THEN2 ASSUME_TAC
    (CONJUNCTS_THEN2 ASSUME_TAC
     (X_CHOOSE_THEN `a:A` (X_CHOOSE_THEN `y:A` STRIP_ASSUME_TAC))))) THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`a:A`;`y:A`]
         EBNSTAGE_CHAR) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `w:A` STRIP_ASSUME_TAC) THEN
  SUBGOAL_THEN `ebnmem D (E:A->A->bool) B w u` MP_TAC THENL
   [UNDISCH_TAC `ebnfuns D (E:A->A->bool) B w y` THEN REWRITE_TAC[ebnfuns] THEN
    ASM_MESON_TAC[]; ALL_TAC] THEN
  REWRITE_TAC[ebnmem] THEN STRIP_TAC);;

let ESEPNAME_RAW = prove
 (`!D (E:A->A->bool) B leq v p x aa.
      model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
      valuation D v /\ (!i. bname D E B (v i)) /\
      aa IN D /\ bname D E B aa
      ==> ?sn. sn IN D /\
               (!z. z IN D
                    ==> (E z sn <=>
                         ?w q e m. w IN D /\ q IN D /\ e IN D /\ m IN D /\
                                   eapply D E aa w q /\
                                   bval D E B leq ((x |-> w) v) p e /\
                                   emeet D E B leq q e m /\
                                   eopair D (E:A->A->bool) w m z))`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `!xx. (v:num->A) xx IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[valuation]; ALL_TAC] THEN
  SUBGOAL_THEN `ebalg D (E:A->A->bool) B leq` ASSUME_TAC THENL
   [ASM_MESON_TAC[ECBA_IMP_BALG]; ALL_TAC] THEN
  SUBGOAL_THEN `eporder D (E:A->A->bool) B leq` ASSUME_TAC THENL
   [ASM_MESON_TAC[EBALG_IMP_PORDER]; ALL_TAC] THEN
  X_CHOOSE_THEN `fp:form` (LABEL_TAC "fpdef")
    (ISPECL [`p:form`; `5`; `1`] BVAL_DEFINABLE) THEN
  ABBREV_TAC
    `vP = (2 |-> (B:A)) ((1 |-> (leq:A)) (\k. (v:num->A) (k - 32)))` THEN
  SUBGOAL_THEN
   `valuation D (vP:num->A) /\ (vP:num->A) 1 = leq /\ (vP:num->A) 2 = B /\
    (!i. (vP:num->A) (32 + i) = (v:num->A) i)`
  STRIP_ASSUME_TAC THENL
   [EXPAND_TAC "vP" THEN REPEAT CONJ_TAC THENL
     [REPEAT(MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[]) THEN
      REWRITE_TAC[valuation] THEN ASM_REWRITE_TAC[];
      SIMP_TAC[VALMOD_OTHER; VALMOD_BASIC; ARITH_RULE `~(1 = 2)`];
      SIMP_TAC[VALMOD_BASIC];
      GEN_TAC THEN
      SIMP_TAC[VALMOD_OTHER; ARITH_RULE `~(32 + i = 2) /\ ~(32 + i = 1)`] THEN
      AP_TERM_TAC THEN ARITH_TAC];
    ALL_TAC] THEN
  (* ---- the bridge hrk ---- *)
  SUBGOAL_THEN
   `!el ot:A. el IN D /\ ot IN D
      ==> (holds D E ((3 |-> ot) ((0 |-> el) (vP:num->A)))
             (?? (32 + x) (?? 4 (?? 5 (?? 6
                (opair_form (32 + x) 4 0 && fp && bmeet_form 1 2 4 5 6 &&
                 opair_form (32 + x) 6 3))))) <=>
           ?w. w IN D /\ ?q. q IN D /\ ?e. e IN D /\ ?m. m IN D /\
               eopair D E w q el /\
               bval D E B leq ((x |-> w) v) p e /\
               emeet D E B leq q e m /\
               eopair D (E:A->A->bool) w m ot)`
   (LABEL_TAC "hrk") THENL
   [REPEAT GEN_TAC THEN STRIP_TAC THEN
    REWRITE_TAC[HOLDS_EX] THEN
    MATCH_MP_TAC EXISTS_AND_CONG THEN X_GEN_TAC `w:A` THEN DISCH_TAC THEN
    MATCH_MP_TAC EXISTS_AND_CONG THEN X_GEN_TAC `q:A` THEN DISCH_TAC THEN
    MATCH_MP_TAC EXISTS_AND_CONG THEN X_GEN_TAC `e:A` THEN DISCH_TAC THEN
    MATCH_MP_TAC EXISTS_AND_CONG THEN X_GEN_TAC `m:A` THEN DISCH_TAC THEN
    ABBREV_TAC
     `Vp = (6 |-> (m:A)) ((5 |-> (e:A)) ((4 |-> (q:A)) (((32 + x) |-> (w:A))
           ((3 |-> (ot:A)) ((0 |-> (el:A)) (vP:num->A))))))` THEN
    SUBGOAL_THEN
     `valuation D (Vp:num->A) /\
      (Vp:num->A) (32 + x) = w /\ Vp 4 = q /\ Vp 0 = el /\ Vp 2 = B /\
      Vp 1 = leq /\ Vp 5 = e /\ Vp 6 = m /\ Vp 3 = ot /\
      (!i. (Vp:num->A) (32 + i) = ((x |-> w) (v:num->A)) i)`
    STRIP_ASSUME_TAC THENL
     [EXPAND_TAC "Vp" THEN REPEAT CONJ_TAC THENL
       [REPEAT(MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[]);
        SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER;
          ARITH_RULE `~(32 + x = 6) /\ ~(32 + x = 5) /\ ~(32 + x = 4)`];
        SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER; ARITH_EQ];
        SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER; ARITH_EQ;
          ARITH_RULE `~(0 = 32 + x)`];
        SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER; ARITH_EQ;
          ARITH_RULE `~(2 = 32 + x)`] THEN ASM_REWRITE_TAC[];
        SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER; ARITH_EQ;
          ARITH_RULE `~(1 = 32 + x)`] THEN ASM_REWRITE_TAC[];
        SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER; ARITH_EQ];
        SIMP_TAC[VALMOD_BASIC];
        SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER; ARITH_EQ;
          ARITH_RULE `~(3 = 32 + x)`];
        GEN_TAC THEN ASM_CASES_TAC `i:num = x` THEN
        ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER; ARITH_EQ;
          ARITH_RULE `~(32 + i = 6) /\ ~(32 + i = 5) /\ ~(32 + i = 4) /\
                      ~(32 + i = 3) /\ ~(32 + i = 0)`;
          ARITH_RULE `~(i = x) ==> ~(32 + i = 32 + x)`]];
      ALL_TAC] THEN
    REWRITE_TAC[HOLDS_AND] THEN
    MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `Vp:num->A`;
      `32 + x`; `4`; `0`] HOLDS_OPAIR_FORM) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `Vp:num->A`;
      `32 + x`; `6`; `3`] HOLDS_OPAIR_FORM) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `Vp:num->A`;
      `1`; `2`; `4`; `5`; `6`] HOLDS_BMEET_FORM) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    USE_THEN "fpdef" (MP_TAC o SPECL
      [`D:A->bool`; `E:A->A->bool`; `Vp:num->A`]) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[] THEN ARITH_TAC; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    SUBGOAL_THEN
     `bval D E B leq (\i. (Vp:num->A) (32 + i)) p e <=>
      bval D E B leq ((x |-> w) (v:num->A)) p e`
     (fun th -> REWRITE_TAC[th]) THENL
     [MATCH_MP_TAC BVAL_FV THEN X_GEN_TAC `i:num` THEN DISCH_TAC THEN
      ASM_REWRITE_TAC[]; ALL_TAC] THEN
    ASM_REWRITE_TAC[ETA_AX];
    ALL_TAC] THEN
  (* ---- apply replacement ---- *)
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`] ZF_REPLACEMENT) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(MP_TAC o SPECL
    [`?? (32 + x) (?? 4 (?? 5 (?? 6
        (opair_form (32 + x) 4 0 && fp && bmeet_form 1 2 4 5 6 &&
         opair_form (32 + x) 6 3))))`;
     `0`; `3`; `vP:num->A`; `aa:A`]) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[ARITH_EQ] THEN
    X_GEN_TAC `u:A` THEN STRIP_TAC THEN
    MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `B:A`; `aa:A`; `u:A`]
      BNAME_MEM_PAIR) THEN
    ASM_REWRITE_TAC[] THEN
    DISCH_THEN(X_CHOOSE_THEN `w:A` (X_CHOOSE_THEN `q:A` STRIP_ASSUME_TAC)) THEN
    SUBGOAL_THEN `eapply D (E:A->A->bool) aa w q` ASSUME_TAC THENL
     [REWRITE_TAC[eapply] THEN EXISTS_TAC `u:A` THEN ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    SUBGOAL_THEN `eindom D (E:A->A->bool) aa w` ASSUME_TAC THENL
     [REWRITE_TAC[eindom] THEN EXISTS_TAC `q:A` THEN ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    SUBGOAL_THEN `bname D (E:A->A->bool) B w` ASSUME_TAC THENL
     [MATCH_MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `B:A`; `aa:A`; `w:A`]
        UNION_DOM_BNAME) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN
     `valuation D ((x |-> w) (v:num->A)) /\
      (!i. bname D (E:A->A->bool) B (((x |-> w) (v:num->A)) i))`
    STRIP_ASSUME_TAC THENL
     [CONJ_TAC THENL
       [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[];
        MATCH_MP_TAC BNAMEVAL_VALMOD THEN ASM_REWRITE_TAC[]]; ALL_TAC] THEN
    MP_TAC(ISPECL [`p:form`; `D:A->bool`; `E:A->A->bool`; `B:A`; `leq:A`;
      `(x |-> w) (v:num->A)`] BVAL_TOTAL) THEN
    ASM_REWRITE_TAC[] THEN
    DISCH_THEN(X_CHOOSE_THEN `e:A` STRIP_ASSUME_TAC) THEN
    SUBGOAL_THEN `(E:A->A->bool) e B` ASSUME_TAC THENL
     [MATCH_MP_TAC(ISPECL
                   [`p:form`; `D:A->bool`; `E:A->A->bool`; `B:A`; `leq:A`;
                    `(x |-> w) (v:num->A)`; `e:A`] BVAL_IN_B) THEN
       ASM_REWRITE_TAC[]; ALL_TAC] THEN
    MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `B:A`; `leq:A`; `q:A`; `e:A`]
      EBALG_MEET) THEN
    ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `m:A`) THEN
    SUBGOAL_THEN `(m:A) IN D /\ (E:A->A->bool) m B` STRIP_ASSUME_TAC THENL
     [MP_TAC(ISPECL
             [`D:A->bool`; `E:A->A->bool`; `B:A`; `leq:A`; `q:A`; `e:A`; `m:A`]
             EMEET_IN) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `w:A`; `m:A`]
           EOPAIR_EXISTS) THEN
    ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `z:A`) THEN
    SUBGOAL_THEN `(z:A) IN D` ASSUME_TAC THENL
     [ASM_MESON_TAC[EOPAIR_IN]; ALL_TAC] THEN
    EXISTS_TAC `z:A` THEN ASM_REWRITE_TAC[] THEN
    X_GEN_TAC `z':A` THEN
    DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC MP_TAC) THEN
    USE_THEN "hrk" (MP_TAC o SPECL [`u:A`; `z':A`]) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    DISCH_THEN(X_CHOOSE_THEN `w2:A` (CONJUNCTS_THEN2 ASSUME_TAC
      (X_CHOOSE_THEN `q2:A` (CONJUNCTS_THEN2 ASSUME_TAC
       (X_CHOOSE_THEN `e2:A` (CONJUNCTS_THEN2 ASSUME_TAC
        (X_CHOOSE_THEN `m2:A` STRIP_ASSUME_TAC))))))) THEN
    SUBGOAL_THEN `(w2:A) = w /\ (q2:A) = q` STRIP_ASSUME_TAC THENL
     [MP_TAC(ISPECL
             [`D:A->bool`; `E:A->A->bool`; `w2:A`; `q2:A`; `w:A`; `q:A`; `u:A`]
             EOPAIR_INJ) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    REPEAT(FIRST_X_ASSUM(SUBST_ALL_TAC o check (fun th ->
      (is_eq (concl th)) &&
        (rand(concl th) = `w:A` || rand(concl th) = `q:A`)))) THEN
    SUBGOAL_THEN `(e2:A) = e` SUBST_ALL_TAC THENL
     [MP_TAC(ISPECL [`p:form`; `D:A->bool`; `E:A->A->bool`; `B:A`; `leq:A`;
        `(x |-> w) (v:num->A)`; `e2:A`; `e:A`] BVAL_UNIQUE) THEN
           ASM_REWRITE_TAC[];
           ALL_TAC] THEN
    SUBGOAL_THEN `(m2:A) = m` SUBST_ALL_TAC THENL
     [MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `B:A`; `leq:A`; `q:A`; `e:A`;
        `m2:A`; `m:A`] EMEET_UNIQUE) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `w:A`; `m:A`; `z':A`; `z:A`]
      EOPAIR_UNIQUE) THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `sn:A`
             (CONJUNCTS_THEN2 ASSUME_TAC (LABEL_TAC "raw"))) THEN
  EXISTS_TAC `sn:A` THEN ASM_REWRITE_TAC[] THEN
  X_GEN_TAC `z:A` THEN DISCH_TAC THEN
  USE_THEN "raw" (fun th ->
    REWRITE_TAC[MATCH_MP th (ASSUME `(z:A) IN D`)]) THEN
  EQ_TAC THENL
   [DISCH_THEN(X_CHOOSE_THEN `u:A` (CONJUNCTS_THEN2 ASSUME_TAC
      (CONJUNCTS_THEN2 ASSUME_TAC MP_TAC))) THEN
    USE_THEN "hrk" (MP_TAC o SPECL [`u:A`; `z:A`]) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    DISCH_THEN(X_CHOOSE_THEN `w:A` (CONJUNCTS_THEN2 ASSUME_TAC
      (X_CHOOSE_THEN `q:A` (CONJUNCTS_THEN2 ASSUME_TAC
       (X_CHOOSE_THEN `e:A` (CONJUNCTS_THEN2 ASSUME_TAC
        (X_CHOOSE_THEN `m:A` STRIP_ASSUME_TAC))))))) THEN
    MAP_EVERY EXISTS_TAC [`w:A`; `q:A`; `e:A`; `m:A`] THEN
    ASM_REWRITE_TAC[] THEN
    REWRITE_TAC[eapply] THEN EXISTS_TAC `u:A` THEN ASM_REWRITE_TAC[];
    DISCH_THEN(X_CHOOSE_THEN `w:A` (X_CHOOSE_THEN `q:A` (X_CHOOSE_THEN `e:A`
      (X_CHOOSE_THEN `m:A` STRIP_ASSUME_TAC)))) THEN
    UNDISCH_TAC `eapply D (E:A->A->bool) aa w q` THEN REWRITE_TAC[eapply] THEN
    DISCH_THEN(X_CHOOSE_THEN `u:A` STRIP_ASSUME_TAC) THEN
    SUBGOAL_THEN `(u:A) IN D` ASSUME_TAC THENL
     [ASM_MESON_TAC[EOPAIR_IN]; ALL_TAC] THEN
    EXISTS_TAC `u:A` THEN ASM_REWRITE_TAC[] THEN
    USE_THEN "hrk" (MP_TAC o SPECL [`u:A`; `z:A`]) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    EXISTS_TAC `w:A` THEN ASM_REWRITE_TAC[] THEN
    EXISTS_TAC `q:A` THEN ASM_REWRITE_TAC[] THEN
    EXISTS_TAC `e:A` THEN ASM_REWRITE_TAC[] THEN
    EXISTS_TAC `m:A` THEN ASM_REWRITE_TAC[]]);;

let ESEPNAME_EXISTS = prove
 (`!D (E:A->A->bool) B leq v p x aa.
        model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
        valuation D v /\ (!i. bname D E B (v i)) /\
        aa IN D /\ bname D E B aa
        ==> ?sn. sn IN D /\ eisfun D E sn /\
                 (!w. w IN D ==> (eindom D E sn w <=> eindom D E aa w)) /\
                 (!w q m. w IN D /\ q IN D /\ eindom D E aa w /\
                          eapply D E aa w q /\
                          emeet D E B leq q (bvalf D E B leq ((x |-> w) v) p) m
                          ==> eapply D E sn w m) /\
                 (!z. z IN D
                      ==> (E z sn <=>
                           ?w q e m. w IN D /\ q IN D /\ e IN D /\ m IN D /\
                                     eapply D E aa w q /\
                                     bval D E B leq ((x |-> w) v) p e /\
                                     emeet D E B leq q e m /\
                                     eopair D (E:A->A->bool) w m z))`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `ebalg D (E:A->A->bool) B leq` ASSUME_TAC THENL
   [ASM_MESON_TAC[ECBA_IMP_BALG]; ALL_TAC] THEN
  SUBGOAL_THEN `eporder D (E:A->A->bool) B leq` ASSUME_TAC THENL
   [ASM_MESON_TAC[EBALG_IMP_PORDER]; ALL_TAC] THEN
  SUBGOAL_THEN `eisfun D (E:A->A->bool) aa` (LABEL_TAC "aisf") THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`aa:A`]
                 BNAME_ISFUN) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`v:num->A`;`p:form`;
    `x:num`;`aa:A`] ESEPNAME_RAW) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `sn:A`
             (CONJUNCTS_THEN2 ASSUME_TAC (LABEL_TAC "raw"))) THEN
  SUBGOAL_THEN
   `!w:A. w IN D /\ eindom D (E:A->A->bool) aa w
          ==> bname D E B w /\
              valuation D ((x |-> w) (v:num->A)) /\
              (!i. bname D E B (((x |-> w) (v:num->A)) i)) /\
              (bvalf D E B leq ((x |-> w) v) p) IN D /\
              E (bvalf D E B leq ((x |-> w) v) p) B /\
              bval D E B leq ((x |-> w) v) p (bvalf D E B leq ((x |-> w) v) p)`
   (LABEL_TAC "wprops") THENL
   [X_GEN_TAC `w:A` THEN STRIP_TAC THEN
    SUBGOAL_THEN `bname D (E:A->A->bool) B w` ASSUME_TAC THENL
     [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`aa:A`;`w:A`]
        UNION_DOM_BNAME) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN
     `valuation D ((x |-> w) (v:num->A)) /\
      (!i. bname D (E:A->A->bool) B (((x |-> w) (v:num->A)) i))`
    STRIP_ASSUME_TAC THENL
     [CONJ_TAC THENL
       [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[];
        MATCH_MP_TAC BNAMEVAL_VALMOD THEN ASM_REWRITE_TAC[]]; ALL_TAC] THEN
    ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
     [MP_TAC(ISPECL [`p:form`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
        `(x |-> w) (v:num->A)`] BVALF_SPEC) THEN ASM_SIMP_TAC[];
      CONJ_TAC THENL
       [MP_TAC(ISPECL [`p:form`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
          `(x |-> w) (v:num->A)`] BVALF_IN_B) THEN ASM_SIMP_TAC[];
        MP_TAC(ISPECL [`p:form`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
          `(x |-> w) (v:num->A)`] BVALF_SPEC) THEN ASM_SIMP_TAC[]]];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!w q m. w IN D /\ q IN D /\ eindom D (E:A->A->bool) aa w /\
            eapply D E aa w q /\
            emeet D E B leq q (bvalf D E B leq ((x |-> w) v) p) m
            ==> eapply D E sn w m`
   (LABEL_TAC "link") THENL
   [REPEAT GEN_TAC THEN STRIP_TAC THEN
    USE_THEN "wprops" (MP_TAC o SPEC `w:A`) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN STRIP_TAC THEN
    SUBGOAL_THEN `(m:A) IN D` ASSUME_TAC THENL
     [ASM_MESON_TAC[EMEET_IN]; ALL_TAC] THEN
    MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`w:A`;`m:A`] EOPAIR_EXISTS) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(X_CHOOSE_TAC `z:A`) THEN
    SUBGOAL_THEN `(z:A) IN D` ASSUME_TAC THENL
     [ASM_MESON_TAC[EOPAIR_IN]; ALL_TAC] THEN
    REWRITE_TAC[eapply] THEN EXISTS_TAC `z:A` THEN ASM_REWRITE_TAC[] THEN
    USE_THEN "raw" (MP_TAC o SPEC `z:A`) THEN
    ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    MAP_EVERY EXISTS_TAC [`w:A`;`q:A`;
      `bvalf D (E:A->A->bool) B leq ((x |-> w) v) p`;`m:A`] THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  EXISTS_TAC `sn:A` THEN REPEAT CONJ_TAC THENL
   [FIRST_ASSUM ACCEPT_TAC;
    REWRITE_TAC[eisfun] THEN REPEAT CONJ_TAC THENL
     [FIRST_ASSUM ACCEPT_TAC;
      X_GEN_TAC `z:A` THEN STRIP_TAC THEN
      USE_THEN "raw" (MP_TAC o SPEC `z:A`) THEN
      ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
      DISCH_THEN(fun th ->
                 MP_TAC(EQ_MP th (ASSUME `(E:A->A->bool) z sn`))) THEN
      DISCH_THEN(X_CHOOSE_THEN `w:A` (X_CHOOSE_THEN `q:A`
        (X_CHOOSE_THEN `e:A` (X_CHOOSE_THEN `m:A` STRIP_ASSUME_TAC)))) THEN
      MAP_EVERY EXISTS_TAC [`w:A`;`m:A`] THEN ASM_REWRITE_TAC[];
      REPEAT GEN_TAC THEN STRIP_TAC THEN
      SUBGOAL_THEN `(z:A) IN D /\ (z':A) IN D` STRIP_ASSUME_TAC THENL
       [ASM_MESON_TAC[EOPAIR_IN]; ALL_TAC] THEN
      SUBGOAL_THEN
       `?w1 q1 e1 m1. w1 IN D /\ q1 IN D /\ e1 IN D /\ m1 IN D /\
                      eapply D (E:A->A->bool) aa w1 q1 /\
                      bval D E B leq ((x |-> w1) v) p e1 /\
                      emeet D E B leq q1 e1 m1 /\ eopair D E w1 m1 z`
      STRIP_ASSUME_TAC THENL
       [USE_THEN "raw" (fun th -> ACCEPT_TAC(EQ_MP
          (MATCH_MP th (ASSUME `(z:A) IN D`)) (ASSUME `(E:A->A->bool) z sn`)));
        ALL_TAC] THEN
      SUBGOAL_THEN
       `?w2 q2 e2 m2. w2 IN D /\ q2 IN D /\ e2 IN D /\ m2 IN D /\
                      eapply D (E:A->A->bool) aa w2 q2 /\
                      bval D E B leq ((x |-> w2) v) p e2 /\
                      emeet D E B leq q2 e2 m2 /\ eopair D E w2 m2 z'`
      STRIP_ASSUME_TAC THENL
       [USE_THEN "raw" (fun th -> ACCEPT_TAC(EQ_MP
          (MATCH_MP th (ASSUME `(z':A) IN D`))
            (ASSUME `(E:A->A->bool) z' sn`)));
        ALL_TAC] THEN
      SUBGOAL_THEN `(u:A) = w1 /\ (w:A) = m1` STRIP_ASSUME_TAC THENL
       [MP_TAC(ISPECL
               [`D:A->bool`;`E:A->A->bool`;`u:A`;`w:A`;`w1:A`;`m1:A`;`z:A`]
               EOPAIR_INJ) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
      SUBGOAL_THEN `(u:A) = w2 /\ (w':A) = m2` STRIP_ASSUME_TAC THENL
       [MP_TAC(ISPECL
               [`D:A->bool`;`E:A->A->bool`;`u:A`;`w':A`;`w2:A`;`m2:A`;`z':A`]
               EOPAIR_INJ) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
      SUBGOAL_THEN `(w2:A) = w1` SUBST_ALL_TAC THENL
       [ASM_MESON_TAC[]; ALL_TAC] THEN
      SUBGOAL_THEN `valuation D ((x |-> w1) (v:num->A))` ASSUME_TAC THENL
       [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
      SUBGOAL_THEN `(q2:A) = q1` SUBST_ALL_TAC THENL
       [MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`aa:A`;`w1:A`;`q2:A`;`q1:A`]
          EAPPLY_UNIQUE) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
      SUBGOAL_THEN `(e2:A) = e1` SUBST_ALL_TAC THENL
       [MP_TAC(ISPECL [`p:form`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
          `(x |-> w1) (v:num->A)`;`e2:A`;`e1:A`] BVAL_UNIQUE) THEN
        ASM_REWRITE_TAC[]; ALL_TAC] THEN
      SUBGOAL_THEN `(m2:A) = m1` SUBST_ALL_TAC THENL
       [MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`q1:A`;`e1:A`;
          `m2:A`;`m1:A`] EMEET_UNIQUE) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
      ASM_REWRITE_TAC[]];
    X_GEN_TAC `w:A` THEN DISCH_TAC THEN REWRITE_TAC[eindom] THEN EQ_TAC THENL
     [DISCH_THEN(X_CHOOSE_THEN `mm:A` (CONJUNCTS_THEN2 ASSUME_TAC
        (MP_TAC o REWRITE_RULE[eapply]))) THEN
      DISCH_THEN(X_CHOOSE_THEN `z:A`
                 (CONJUNCTS_THEN2 ASSUME_TAC ASSUME_TAC)) THEN
      SUBGOAL_THEN `(z:A) IN D` ASSUME_TAC THENL
       [ASM_MESON_TAC[EOPAIR_IN]; ALL_TAC] THEN
      SUBGOAL_THEN
       `?w1 q1 e1 m1. w1 IN D /\ q1 IN D /\ e1 IN D /\ m1 IN D /\
                      eapply D (E:A->A->bool) aa w1 q1 /\
                      bval D E B leq ((x |-> w1) v) p e1 /\
                      emeet D E B leq q1 e1 m1 /\ eopair D E w1 m1 z`
      STRIP_ASSUME_TAC THENL
       [USE_THEN "raw" (fun th -> ACCEPT_TAC(EQ_MP
          (MATCH_MP th (ASSUME `(z:A) IN D`)) (ASSUME `(E:A->A->bool) z sn`)));
        ALL_TAC] THEN
      SUBGOAL_THEN `(w:A) = w1 /\ (mm:A) = m1` STRIP_ASSUME_TAC THENL
       [MP_TAC(ISPECL
               [`D:A->bool`;`E:A->A->bool`;`w:A`;`mm:A`;`w1:A`;`m1:A`;`z:A`]
               EOPAIR_INJ) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
      EXISTS_TAC `q1:A` THEN ASM_REWRITE_TAC[];
      DISCH_THEN(X_CHOOSE_THEN `q:A`
                 (CONJUNCTS_THEN2 ASSUME_TAC ASSUME_TAC)) THEN
      SUBGOAL_THEN `eindom D (E:A->A->bool) aa w` ASSUME_TAC THENL
       [REWRITE_TAC[eindom] THEN EXISTS_TAC `q:A` THEN ASM_REWRITE_TAC[];
        ALL_TAC] THEN
      USE_THEN "wprops" (MP_TAC o SPEC `w:A`) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN STRIP_TAC THEN
      SUBGOAL_THEN `(E:A->A->bool) q B` ASSUME_TAC THENL
       [UNDISCH_TAC `eapply D (E:A->A->bool) aa w q` THEN
        REWRITE_TAC[eapply] THEN
        DISCH_THEN(X_CHOOSE_THEN `z:A` STRIP_ASSUME_TAC) THEN
        SUBGOAL_THEN `(z:A) IN D` ASSUME_TAC THENL
         [ASM_MESON_TAC[EOPAIR_IN]; ALL_TAC] THEN
        MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`aa:A`;`z:A`]
          BNAME_MEM_PAIR) THEN
        ASM_REWRITE_TAC[] THEN
        DISCH_THEN(X_CHOOSE_THEN `w'':A`
                   (X_CHOOSE_THEN `q'':A` STRIP_ASSUME_TAC)) THEN
        SUBGOAL_THEN `(w:A) = w'' /\ (q:A) = q''` STRIP_ASSUME_TAC THENL
         [MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`w:A`;`q:A`;`w'':A`;`q'':A`;`z:A`]
                 EOPAIR_INJ) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
        ASM_MESON_TAC[]; ALL_TAC] THEN
      MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`q:A`;
        `bvalf D (E:A->A->bool) B leq ((x |-> w) v) p`] EBALG_MEET) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(X_CHOOSE_TAC `m:A`) THEN
      SUBGOAL_THEN `(m:A) IN D` ASSUME_TAC THENL
       [ASM_MESON_TAC[EMEET_IN]; ALL_TAC] THEN
      EXISTS_TAC `m:A` THEN ASM_REWRITE_TAC[] THEN
      USE_THEN "link" (MATCH_MP_TAC o SPECL [`w:A`;`q:A`;`m:A`]) THEN
      ASM_REWRITE_TAC[]];
    USE_THEN "link" ACCEPT_TAC;
    USE_THEN "raw" ACCEPT_TAC]);;

let ESEPNAME_BNAME = prove
 (`!D (E:A->A->bool) B leq v p x aa sn.
        model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
        aa IN D /\ bname D E B aa /\
        sn IN D /\ eisfun D E sn /\
        (!z. z IN D
             ==> (E z sn <=>
                  ?w q e m. w IN D /\ q IN D /\ e IN D /\ m IN D /\
                            eapply D E aa w q /\
                            bval D E B leq ((x |-> w) v) p e /\
                            emeet D E B leq q e m /\
                            eopair D (E:A->A->bool) w m z))
        ==> bname D E B sn`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "modl ecba BD leqD aaD bnaa snD isf snch" THEN
  USE_THEN "bnaa"
    (X_CHOOSE_THEN `ax:A` (X_CHOOSE_THEN `yx:A` STRIP_ASSUME_TAC) o
    REWRITE_RULE[bname]) THEN
  SUBGOAL_THEN `!wi:A. wi IN D /\ eindom D (E:A->A->bool) aa wi ==> E wi yx`
   (LABEL_TAC "Wsub") THENL
   [X_GEN_TAC `wi:A` THEN STRIP_TAC THEN
    UNDISCH_TAC `eindom D (E:A->A->bool) aa wi` THEN REWRITE_TAC[eindom] THEN
    DISCH_THEN(X_CHOOSE_THEN `qw:A` STRIP_ASSUME_TAC) THEN
    MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`ax:A`;`yx:A`;`aa:A`;
      `wi:A`;`qw:A`] STAGE_DOM_CLOSED) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`ax:A`] ESUC_EXISTS) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `sa:A`) THEN
  SUBGOAL_THEN
    `(sa:A) IN D /\ eordinal D (E:A->A->bool) sa /\ (E:A->A->bool) ax sa`
  STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[ESUC_IN; EORDINAL_ESUC; ESUC_MEMBER]; ALL_TAC] THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`sa:A`] EBNSTAGE_EXISTS) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `ysa:A` STRIP_ASSUME_TAC) THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`sa:A`;`ysa:A`]
         EBNSTAGE_CHAR) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `w1:A` (CONJUNCTS_THEN2 ASSUME_TAC
    (CONJUNCTS_THEN2 (LABEL_TAC "w1ch") ASSUME_TAC))) THEN
  SUBGOAL_THEN `!u:A. u IN D /\ (E:A->A->bool) u yx ==> E u w1`
    (LABEL_TAC "Ysub") THENL
   [X_GEN_TAC `u:A` THEN STRIP_TAC THEN
    USE_THEN "w1ch" (MP_TAC o SPEC `u:A`) THEN
    ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    MAP_EVERY EXISTS_TAC [`ax:A`;`yx:A`] THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`w1:A`;`B:A`] ECROSS_EXISTS) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `cr:A` (LABEL_TAC "cr")) THEN
  SUBGOAL_THEN `(cr:A) IN D` ASSUME_TAC THENL
   [USE_THEN "cr" (MP_TAC o REWRITE_RULE[ecross]) THEN SIMP_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `esubset D (E:A->A->bool) sn cr` ASSUME_TAC THENL
   [REWRITE_TAC[esubset] THEN X_GEN_TAC `z:A` THEN STRIP_TAC THEN
    USE_THEN "cr" (MP_TAC o SPEC `z:A` o CONJUNCT2 o REWRITE_RULE[ecross]) THEN
    ASM_REWRITE_TAC[] THEN DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    USE_THEN "snch" (MP_TAC o SPEC `z:A`) THEN
    ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN(fun th -> MP_TAC(EQ_MP th (ASSUME `(E:A->A->bool) z sn`))) THEN
    DISCH_THEN(X_CHOOSE_THEN `wi:A` (X_CHOOSE_THEN `qi:A`
      (X_CHOOSE_THEN `ei:A` (X_CHOOSE_THEN `mi:A` STRIP_ASSUME_TAC)))) THEN
    SUBGOAL_THEN `eindom D (E:A->A->bool) aa wi` ASSUME_TAC THENL
     [REWRITE_TAC[eindom] THEN EXISTS_TAC `qi:A` THEN ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    SUBGOAL_THEN `(E:A->A->bool) wi w1` ASSUME_TAC THENL
     [USE_THEN "Ysub" MATCH_MP_TAC THEN CONJ_TAC THENL
       [FIRST_ASSUM ACCEPT_TAC;
        USE_THEN "Wsub" MATCH_MP_TAC THEN ASM_REWRITE_TAC[]]; ALL_TAC] THEN
    SUBGOAL_THEN `(E:A->A->bool) mi B` ASSUME_TAC THENL
     [ASM_MESON_TAC[EMEET_IN]; ALL_TAC] THEN
    MAP_EVERY EXISTS_TAC [`wi:A`;`mi:A`] THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `ebnmem D (E:A->A->bool) B w1 sn` ASSUME_TAC THENL
   [REWRITE_TAC[ebnmem] THEN ASM_REWRITE_TAC[] THEN
    EXISTS_TAC `cr:A` THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) sn ysa` ASSUME_TAC THENL
   [UNDISCH_TAC `ebnfuns D (E:A->A->bool) B w1 ysa` THEN
    REWRITE_TAC[ebnfuns] THEN
    DISCH_THEN(MP_TAC o SPEC `sn:A` o CONJUNCT2) THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  REWRITE_TAC[bname] THEN MAP_EVERY EXISTS_TAC [`sa:A`;`ysa:A`] THEN
  ASM_REWRITE_TAC[]);;

(* ================================================================== *)
(* F5, V^B:  SEPARATION axiom  [[separation_ax x a s p]] = top.        *)
(* separation_ax x a s p = !!a(??s(!!x((x%%s) <-> (x%%a)&&p))).        *)
(* Assembled from the separation-name machinery (ESEPNAME_EXISTS /     *)
(* ESEPNAME_BNAME) and the membership value-equality EBV_IN_SEP:       *)
(* [[t in sn]] = [[t in aa]] MEET [[p]]_{x:=t}.  A bvalf-level free-    *)
(* variable congruence (BVALF_FV_CONG) reconciles the p-value evaluated *)
(* at the full valuation vv with the one EBV_IN_SEP delivers at         *)
(* (x|->tt)v0 (they differ only at the fresh slot s, s not in FV p).    *)
(* ------------------------------------------------------------------ *)

let BVALF_FV_CONG = prove
 (`!p D (E:A->A->bool) B leq v w.
      model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
      valuation D v /\ (!i. bname D E B (v i)) /\
      valuation D w /\ (!i. bname D E B (w i)) /\
      (!i. i IN FV p ==> v i = w i)
      ==> bvalf D E B leq v p = bvalf D E B leq w p`,
  REPEAT STRIP_TAC THEN
  MP_TAC(ISPECL [`p:form`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`v:num->A`]
    BVALF_SPEC) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN STRIP_TAC THEN
  MP_TAC(ISPECL [`p:form`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`w:num->A`]
    BVALF_SPEC) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN STRIP_TAC THEN
  SUBGOAL_THEN `bval D (E:A->A->bool) B leq (v:num->A) (p:form)
                     (bvalf D E B leq (w:num->A) (p:form))` ASSUME_TAC THENL
   [MP_TAC(ISPECL
           [`p:form`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`v:num->A`;
            `w:num->A`; `bvalf D (E:A->A->bool) B leq (w:num->A) (p:form)`]
             BVAL_FV) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN FIRST_ASSUM ACCEPT_TAC;
    ALL_TAC] THEN
  MATCH_MP_TAC(ISPECL
               [`p:form`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`v:num->A`;
                `bvalf D (E:A->A->bool) B leq (v:num->A) (p:form)`;
    `bvalf D (E:A->A->bool) B leq (w:num->A) (p:form)`] BVAL_UNIQUE) THEN
  ASM_REWRITE_TAC[]);;

let BVALF_SEPARATION = prove
 (`!D (E:A->A->bool) B leq v x a s p.
      model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
      valuation D v /\ (!i. bname D E B (v i)) /\
      ~(a IN FV p) /\ ~(s IN FV p) /\
      ~(a = x) /\ ~(s = x) /\ ~(a = s)
      ==> etop D E B leq (bvalf D E B leq v (separation_ax x a s p))`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `eporder D (E:A->A->bool) B leq` ASSUME_TAC THENL
   [ASM_MESON_TAC[ECBA_IMP_BALG; EBALG_IMP_PORDER]; ALL_TAC] THEN
  REWRITE_TAC[separation_ax] THEN
  (* peel !!a -> aa *)
  MP_TAC(ISPECL [`a:num`; `?? s (!! x ((x %% s) <-> (x %% a) && p))`;
    `D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`v:num->A`] BVALF_ALL_TOP) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  X_GEN_TAC `aa:A` THEN STRIP_TAC THEN
  SUBGOAL_THEN `valuation D ((a |-> (aa:A)) (v:num->A)) /\
                (!i. bname D E B (((a |-> (aa:A)) (v:num->A)) i))`
  STRIP_ASSUME_TAC THENL
   [CONJ_TAC THENL
     [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[];
      MATCH_MP_TAC BNAMEVAL_VALMOD THEN ASM_REWRITE_TAC[]]; ALL_TAC] THEN
  ABBREV_TAC `v0 = (a |-> (aa:A)) (v:num->A)` THEN
  (* build the separation name sn at v0 *)
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`v0:num->A`;`p:form`;
    `x:num`;`aa:A`] ESEPNAME_EXISTS) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `sn:A` STRIP_ASSUME_TAC) THEN
  SUBGOAL_THEN `bname D (E:A->A->bool) B sn` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`v0:num->A`;
      `p:form`;`x:num`;`aa:A`;`sn:A`] ESEPNAME_BNAME) THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  (* witness sn for ??s *)
  MATCH_MP_TAC(ISPECL [`s:num`; `!! x ((x %% s) <-> (x %% a) && p)`;
    `D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`v0:num->A`;`sn:A`]
      BVALF_EX_TOP) THEN
  ASM_REWRITE_TAC[] THEN
  SUBGOAL_THEN `valuation D ((s |-> (sn:A)) (v0:num->A)) /\
                (!i. bname D E B (((s |-> (sn:A)) (v0:num->A)) i))`
  STRIP_ASSUME_TAC THENL
   [CONJ_TAC THENL
     [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[];
      MATCH_MP_TAC BNAMEVAL_VALMOD THEN ASM_REWRITE_TAC[]]; ALL_TAC] THEN
  ABBREV_TAC `v1 = (s |-> (sn:A)) (v0:num->A)` THEN
  (* peel !!x -> tt *)
  MP_TAC(ISPECL [`x:num`; `(x %% s) <-> (x %% a) && p`;
    `D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`v1:num->A`] BVALF_ALL_TOP) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  X_GEN_TAC `tt:A` THEN STRIP_TAC THEN
  SUBGOAL_THEN `valuation D ((x |-> (tt:A)) (v1:num->A)) /\
                (!i. bname D E B (((x |-> (tt:A)) (v1:num->A)) i))`
  STRIP_ASSUME_TAC THENL
   [CONJ_TAC THENL
     [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[];
      MATCH_MP_TAC BNAMEVAL_VALMOD THEN ASM_REWRITE_TAC[]]; ALL_TAC] THEN
  ABBREV_TAC `vv = (x |-> (tt:A)) (v1:num->A)` THEN
  (* vv lookups *)
  SUBGOAL_THEN `(vv:num->A) x = tt /\ (vv:num->A) s = sn /\ (vv:num->A) a = aa`
  STRIP_ASSUME_TAC THENL
   [MAP_EVERY EXPAND_TAC ["vv";"v1";"v0"] THEN
    ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER]; ALL_TAC] THEN
  (* IFF_TOP -> value-equality *)
  MP_TAC(ISPECL [`(x %% s):form`; `((x %% a) && p):form`;
    `D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`vv:num->A`] BVALF_IFF_TOP) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  (* goal: bvalf vv (x%%s) = bvalf vv ((x%%a)&&p) *)
  SUBGOAL_THEN `ebv_in D (E:A->A->bool) B leq tt sn
                  (bvalf D E B leq (vv:num->A) (x %% s))`
    (LABEL_TAC "eins") THENL
   [MP_TAC(ISPECL
           [`x:num`;`s:num`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
            `vv:num->A`]
           BVALF_MEM) THEN ASM_SIMP_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `ebv_in D (E:A->A->bool) B leq tt aa
                  (bvalf D E B leq (vv:num->A) (x %% a))`
    (LABEL_TAC "eina") THENL
   [MP_TAC(ISPECL
           [`x:num`;`a:num`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
            `vv:num->A`]
           BVALF_MEM) THEN ASM_SIMP_TAC[]; ALL_TAC] THEN
  (* p-value congruence: bvalf vv p = bvalf ((x|->tt)v0) p  (s not in FV p) *)
  SUBGOAL_THEN `bvalf D (E:A->A->bool) B leq (vv:num->A) (p:form) =
                bvalf D E B leq ((x |-> (tt:A)) (v0:num->A)) (p:form)`
    (LABEL_TAC "pveq") THENL
   [MATCH_MP_TAC(ISPECL
                 [`p:form`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
                  `vv:num->A`;
                  `(x |-> (tt:A)) (v0:num->A)`] BVALF_FV_CONG) THEN
    ASM_REWRITE_TAC[] THEN REPEAT CONJ_TAC THENL
     [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[];
      MATCH_MP_TAC BNAMEVAL_VALMOD THEN ASM_REWRITE_TAC[];
      X_GEN_TAC `i:num` THEN DISCH_TAC THEN
      SUBGOAL_THEN `~(i:num = s)` ASSUME_TAC THENL
      [ASM_MESON_TAC[]; ALL_TAC] THEN
      EXPAND_TAC "vv" THEN EXPAND_TAC "v1" THEN
      ASM_CASES_TAC `i:num = x` THEN
      ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER]]; ALL_TAC] THEN
  (* and-meet: raw form, then rewrite the middle by pveq *)
  SUBGOAL_THEN
    `emeet D (E:A->A->bool) B leq (bvalf D E B leq (vv:num->A) (x %% a))
       (bvalf D E B leq (vv:num->A) (p:form))
                  (bvalf D E B leq (vv:num->A) ((x %% a) && p))`
      (LABEL_TAC "emt0") THENL
   [MATCH_MP_TAC(ISPECL
                 [`(x %% a):form`;`p:form`;`D:A->bool`;`E:A->A->bool`;`B:A`;
                  `leq:A`;`vv:num->A`] BVALF_AND_MEET) THEN ASM_REWRITE_TAC[];
                  ALL_TAC] THEN
  SUBGOAL_THEN
    `emeet D (E:A->A->bool) B leq (bvalf D E B leq (vv:num->A) (x %% a))
       (bvalf D E B leq ((x |-> (tt:A)) (v0:num->A)) (p:form))
                  (bvalf D E B leq (vv:num->A) ((x %% a) && p))`
      (LABEL_TAC "emt") THENL
   [USE_THEN "pveq" (fun th -> ONCE_REWRITE_TAC[GSYM th]) THEN
    USE_THEN "emt0" ACCEPT_TAC; ALL_TAC] THEN
  (* value-in-D facts *)
  SUBGOAL_THEN `(bvalf D (E:A->A->bool) B leq (vv:num->A) (x %% s)) IN D`
    (LABEL_TAC "zinD") THENL
   [MP_TAC(ISPECL
           [`(x %% s):form`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
            `vv:num->A`]
           BVALF_SPEC) THEN ASM_SIMP_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(bvalf D (E:A->A->bool) B leq (vv:num->A) (x %% a)) IN D`
    (LABEL_TAC "ziaD") THENL
   [MP_TAC(ISPECL
           [`(x %% a):form`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
            `vv:num->A`]
           BVALF_SPEC) THEN ASM_SIMP_TAC[]; ALL_TAC] THEN
  (* assemble via EBV_IN_SEP *)
  MP_TAC(ISPECL
         [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`v0:num->A`;
          `p:form`;`x:num`;
          `aa:A`;`tt:A`;`sn:A`;
    `bvalf D (E:A->A->bool) B leq (vv:num->A) (x %% s)`;
    `bvalf D (E:A->A->bool) B leq (vv:num->A) (x %% a)`;
    `bvalf D (E:A->A->bool) B leq (vv:num->A) ((x %% a) && p)`]
           EBV_IN_SEP) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN ACCEPT_TAC);;

(* ================================================================== *)
(* F5/F8, check-name atomic value TOP-transfer.                        *)
(* For check-names va = a^, vb = b^ (echeck with onebee = top of B):   *)
(*   a = b   ==> [[ va = vb ]] = top    (ECHECK_EQ_TOP)                 *)
(*   E a b   ==> [[ va IN vb ]] = top   (ECHECK_IN_TOP)                 *)
(* These are the positive half of the canonical-embedding transfer     *)
(* (Bell): true atomic facts of N get Boolean value top.  Induction-   *)
(* free: EQ from ECHECK_SV (a=b forces va=vb) + EBV_EQ_REFL; IN from   *)
(* EBV_IN_GE_TERM_V with the domain witness (va, onebee) of vb          *)
(* (ECHECK_MEM backward, since a IN b) and [[va=va]] = top.  Needed by  *)
(* the INFINITY axiom (witness omega^) and by F8/Los (elementarity of   *)
(* the check embedding N -> V^B).  onebee = top carried as hypothesis   *)
(* (etop D E B leq onebee), dischargeable since ecba B has a top.       *)
(* ------------------------------------------------------------------ *)

let ECHECK_EQ_TOP = prove
 (`!D (E:A->A->bool) B leq onebee a b va vb z.
      model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
      onebee IN D /\ E onebee B /\
      echeck D E onebee a va /\ echeck D E onebee b vb /\ a = b /\
      z IN D /\ ebv_eq D E B leq va vb z
      ==> etop D E B leq z`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  UNDISCH_TAC `a:A = b` THEN DISCH_THEN SUBST_ALL_TAC THEN
  SUBGOAL_THEN `b IN D /\ (va:A) IN D` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[ECHECK_IMP]; ALL_TAC] THEN
  SUBGOAL_THEN `(va:A) = vb` SUBST_ALL_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`onebee:A`;`b:A`;`va:A`;`vb:A`]
                 ECHECK_SV) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `bname D (E:A->A->bool) B vb` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`onebee:A`;`B:A`;`b:A`;`vb:A`]
                 ECHECK_IS_BNAME) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`vb:A`;`z:A`]
    EBV_EQ_REFL) THEN ASM_REWRITE_TAC[]);;

let ECHECK_IN_TOP = prove
 (`!D (E:A->A->bool) B leq onebee a b va vb z.
      model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
      onebee IN D /\ E onebee B /\ etop D E B leq onebee /\
      echeck D E onebee a va /\ echeck D E onebee b vb /\ E a b /\
      z IN D /\ ebv_in D E B leq va vb z
      ==> etop D E B leq z`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `eporder D (E:A->A->bool) B leq` ASSUME_TAC THENL
   [ASM_MESON_TAC[ECBA_IMP_BALG; EBALG_IMP_PORDER]; ALL_TAC] THEN
  SUBGOAL_THEN `a IN D /\ (va:A) IN D` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[ECHECK_IMP]; ALL_TAC] THEN
  SUBGOAL_THEN `b IN D /\ (vb:A) IN D` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[ECHECK_IMP]; ALL_TAC] THEN
  SUBGOAL_THEN `bname D (E:A->A->bool) B va` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`onebee:A`;`B:A`;`a:A`;`va:A`]
                 ECHECK_IS_BNAME) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `bname D (E:A->A->bool) B vb` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`onebee:A`;`B:A`;`b:A`;`vb:A`]
                 ECHECK_IS_BNAME) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `?pr:A. eopair D (E:A->A->bool) va onebee pr`
    (X_CHOOSE_TAC `pr:A`) THENL
   [MATCH_MP_TAC EOPAIR_EXISTS THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(pr:A) IN D` ASSUME_TAC THENL
   [FIRST_ASSUM(ACCEPT_TAC o MATCH_MP EOPAIR_IN); ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) pr vb` ASSUME_TAC THENL
   [MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`onebee:A`;`b:A`;`vb:A`;`pr:A`]
      ECHECK_MEM) THEN ASM_REWRITE_TAC[] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    MAP_EVERY EXISTS_TAC [`a:A`;`va:A`] THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `eapply D (E:A->A->bool) vb va onebee` ASSUME_TAC THENL
   [REWRITE_TAC[eapply] THEN EXISTS_TAC `pr:A` THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`va:A`;`va:A`]
    EBV_EQ_VAL_EXISTS) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `ey:A` STRIP_ASSUME_TAC) THEN
  SUBGOAL_THEN `etop D (E:A->A->bool) B leq ey` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`va:A`;`ey:A`]
                 EBV_EQ_REFL) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `emeet D (E:A->A->bool) B leq onebee ey ey` ASSUME_TAC THENL
   [MATCH_MP_TAC EMEET_SYM THEN MATCH_MP_TAC EMEET_TOP THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq ey z` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`va:A`;`vb:A`;`z:A`;
                  `va:A`;`onebee:A`;`ey:A`;`ey:A`] EBV_IN_GE_TERM_V) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) z B` ASSUME_TAC THENL
   [MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`va:A`;`vb:A`]
      EBV_IN_VAL_EXISTS) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(X_CHOOSE_THEN `zz:A` STRIP_ASSUME_TAC) THEN
    SUBGOAL_THEN `z:A = zz` SUBST1_TAC THENL
     [MATCH_MP_TAC(ISPECL
                   [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`va:A`;`vb:A`;
                    `z:A`;`zz:A`] EBV_IN_UNIQUE) THEN ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq z ey` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`ey:A`;`z:A`]
      ETOP_GE) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `z:A = ey` SUBST1_TAC THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`z:A`;`ey:A`]
      EPORDER_ANTISYM) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  ASM_REWRITE_TAC[]);;

(* ================================================================== *)
(* F5/F8, check-name MEMBERSHIP value computation.                     *)
(* For a check-name b^ = echeck D E onebee b vb (Bell canonical name,  *)
(* onebee = top of B), the membership value of any B-name t is the     *)
(* supremum of the equality values against the checks of the elements  *)
(* of b:                                                               *)
(*     [[ t IN b^ ]]  =  sup_{c IN b} [[ t = c^ ]].                     *)
(* Expressed by its universal property: each element's equality value  *)
(* is a lower bound (ECHECK_IN_GE_ELT), and the membership value is     *)
(* below every upper bound (ECHECK_IN_LE_SUP).  Degenerate and         *)
(* successor instances:                                                *)
(*     [[ t IN emptyset^ ]] = bot                    (ECHECK_IN_EMPTY)  *)
(*     [[ t IN (c u {c})^ ]] = [[t IN c^]] \/ [[t=c^]] (ECHECK_IN_SUCC) *)
(* These are the set-theoretic core of the INFINITY V^B axiom (witness  *)
(* w := omega^) and of F8/Los (elementarity of the check embedding).    *)
(* All induction-free: GE from EBV_IN_GE_TERM_V at a domain witness     *)
(* (c^, onebee) of b^ (ECHECK_MEM backward); LE from EBV_IN_LE_V, whose *)
(* domain premise ranges exactly over the checks of elements of b       *)
(* (ECHECK_DOM_ELT); EMPTY = LE with an empty domain premise; SUCC =    *)
(* GE/LE + join laws under  d IN (c u {c}) <=> d IN c \/ d = c.         *)
(* ------------------------------------------------------------------ *)

let ECHECK_IN_EMPTY = prove
 (`!D (E:A->A->bool) B leq onebee emp vemp t z.
      model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
      onebee IN D /\ E onebee B /\
      echeck D E onebee emp vemp /\ (!c. c IN D ==> ~(E c emp)) /\
      bname D E B t /\ t IN D /\ z IN D /\ ebv_in D E B leq t vemp z
      ==> ebot D E B leq z`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `emp IN D /\ (vemp:A) IN D` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[ECHECK_IMP]; ALL_TAC] THEN
  SUBGOAL_THEN `bname D (E:A->A->bool) B vemp` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`onebee:A`;`B:A`;`emp:A`;`vemp:A`]
                 ECHECK_IS_BNAME) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) z B` ASSUME_TAC THENL
   [MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`t:A`;`vemp:A`]
      EBV_IN_VAL_EXISTS) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(X_CHOOSE_THEN `zz:A` STRIP_ASSUME_TAC) THEN
    SUBGOAL_THEN `z:A = zz` SUBST1_TAC THENL
     [MATCH_MP_TAC(ISPECL
                   [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`t:A`;`vemp:A`;
                    `z:A`;`zz:A`] EBV_IN_UNIQUE) THEN ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  REWRITE_TAC[ebot] THEN ASM_REWRITE_TAC[] THEN
  X_GEN_TAC `x:A` THEN STRIP_TAC THEN
  MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`t:A`;`vemp:A`;
    `z:A`;`x:A`] EBV_IN_LE_V) THEN
  ASM_REWRITE_TAC[] THEN
  MAP_EVERY X_GEN_TAC [`y:A`;`qy:A`;`ey:A`;`c:A`] THEN STRIP_TAC THEN
  UNDISCH_TAC `eapply D (E:A->A->bool) vemp y qy` THEN
  REWRITE_TAC[eapply] THEN
  DISCH_THEN(X_CHOOSE_THEN `pr:A` STRIP_ASSUME_TAC) THEN
  SUBGOAL_THEN `(pr:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[EOPAIR_IN]; ALL_TAC] THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`onebee:A`;`emp:A`;`vemp:A`;`pr:A`]
    ECHECK_MEM) THEN
  ASM_REWRITE_TAC[] THEN STRIP_TAC THEN ASM_MESON_TAC[]);;

let ECHECK_IN_GE_ELT = prove
 (`!D (E:A->A->bool) B leq onebee b vb c vc t z ec.
      model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
      onebee IN D /\ E onebee B /\ etop D E B leq onebee /\
      echeck D E onebee b vb /\ E c b /\ echeck D E onebee c vc /\
      bname D E B t /\ t IN D /\
      z IN D /\ ebv_in D E B leq t vb z /\
      ec IN D /\ ebv_eq D E B leq t vc ec
      ==> erel D E leq ec z`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `eporder D (E:A->A->bool) B leq` ASSUME_TAC THENL
   [ASM_MESON_TAC[ECBA_IMP_BALG; EBALG_IMP_PORDER]; ALL_TAC] THEN
  SUBGOAL_THEN `b IN D /\ (vb:A) IN D` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[ECHECK_IMP]; ALL_TAC] THEN
  SUBGOAL_THEN `c IN D /\ (vc:A) IN D` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[ECHECK_IMP]; ALL_TAC] THEN
  SUBGOAL_THEN `bname D (E:A->A->bool) B vc` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`onebee:A`;`B:A`;`c:A`;`vc:A`]
                 ECHECK_IS_BNAME) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `?pr:A. eopair D (E:A->A->bool) vc onebee pr`
    (X_CHOOSE_TAC `pr:A`) THENL
   [MATCH_MP_TAC EOPAIR_EXISTS THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(pr:A) IN D` ASSUME_TAC THENL
   [FIRST_ASSUM(ACCEPT_TAC o MATCH_MP EOPAIR_IN); ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) pr vb` ASSUME_TAC THENL
   [MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`onebee:A`;`b:A`;`vb:A`;`pr:A`]
      ECHECK_MEM) THEN ASM_REWRITE_TAC[] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    MAP_EVERY EXISTS_TAC [`c:A`;`vc:A`] THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `eapply D (E:A->A->bool) vb vc onebee` ASSUME_TAC THENL
   [REWRITE_TAC[eapply] THEN EXISTS_TAC `pr:A` THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) ec B` ASSUME_TAC THENL
   [MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`t:A`;`vc:A`]
      EBV_EQ_VAL_EXISTS) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(X_CHOOSE_THEN `ee:A` STRIP_ASSUME_TAC) THEN
    SUBGOAL_THEN `ec:A = ee` SUBST1_TAC THENL
     [MATCH_MP_TAC(ISPECL
                   [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`t:A`;`vc:A`;
                    `ec:A`;`ee:A`] EBV_EQ_UNIQUE) THEN ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `emeet D (E:A->A->bool) B leq onebee ec ec` ASSUME_TAC THENL
   [MATCH_MP_TAC EMEET_SYM THEN MATCH_MP_TAC EMEET_TOP THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  MATCH_MP_TAC(ISPECL
               [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`t:A`;`vb:A`;`z:A`;
                `vc:A`;`onebee:A`;`ec:A`;`ec:A`] EBV_IN_GE_TERM_V) THEN
  ASM_REWRITE_TAC[]);;

let ECHECK_IN_LE_SUP = prove
 (`!D (E:A->A->bool) B leq onebee b vb t z w0.
      model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
      onebee IN D /\ E onebee B /\
      echeck D E onebee b vb /\
      bname D E B t /\ t IN D /\
      z IN D /\ ebv_in D E B leq t vb z /\
      w0 IN D /\ E w0 B /\
      (!c vc ec. E c b /\ echeck D E onebee c vc /\ ec IN D /\
                 ebv_eq D E B leq t vc ec ==> erel D E leq ec w0)
      ==> erel D E leq z w0`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `eporder D (E:A->A->bool) B leq` ASSUME_TAC THENL
   [ASM_MESON_TAC[ECBA_IMP_BALG; EBALG_IMP_PORDER]; ALL_TAC] THEN
  SUBGOAL_THEN `(vb:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[ECHECK_IMP]; ALL_TAC] THEN
  MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`t:A`;`vb:A`;
    `z:A`;`w0:A`] EBV_IN_LE_V) THEN
  ASM_REWRITE_TAC[] THEN
  MAP_EVERY X_GEN_TAC [`y:A`;`qy:A`;`ey:A`;`cc:A`] THEN STRIP_TAC THEN
  SUBGOAL_THEN `eindom D (E:A->A->bool) vb y` ASSUME_TAC THENL
   [REWRITE_TAC[eindom] THEN EXISTS_TAC `qy:A` THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`onebee:A`;`b:A`;`vb:A`;`y:A`]
    ECHECK_DOM_ELT) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `cy:A` STRIP_ASSUME_TAC) THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq ey w0` ASSUME_TAC THENL
   [FIRST_X_ASSUM(MP_TAC o SPECL [`cy:A`;`y:A`;`ey:A`]) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq cc ey` ASSUME_TAC THENL
   [UNDISCH_TAC `emeet D (E:A->A->bool) B leq qy ey cc` THEN
    REWRITE_TAC[emeet] THEN STRIP_TAC THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) ey B` ASSUME_TAC THENL
   [ASM_MESON_TAC[EPORDER_FIELD]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) cc B` ASSUME_TAC THENL
   [ASM_MESON_TAC[EPORDER_FIELD]; ALL_TAC] THEN
  MATCH_MP_TAC(ISPECL
               [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`cc:A`;`ey:A`;`w0:A`]
               EPORDER_TRANS) THEN ASM_REWRITE_TAC[]);;

let ECHECK_IN_SUCC = prove
 (`!D (E:A->A->bool) B leq onebee c vc sc vsc t z zc ec j.
      model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
      onebee IN D /\ E onebee B /\ etop D E B leq onebee /\
      echeck D E onebee c vc /\ echeck D E onebee sc vsc /\
      (!dd. dd IN D ==> (E dd sc <=> E dd c \/ dd = c)) /\
      bname D E B t /\ t IN D /\
      z IN D /\ ebv_in D E B leq t vsc z /\
      zc IN D /\ ebv_in D E B leq t vc zc /\
      ec IN D /\ ebv_eq D E B leq t vc ec /\
      ejoin D E B leq zc ec j
      ==> z = j`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `eporder D (E:A->A->bool) B leq` ASSUME_TAC THENL
   [ASM_MESON_TAC[ECBA_IMP_BALG; EBALG_IMP_PORDER]; ALL_TAC] THEN
  SUBGOAL_THEN `c IN D /\ (vc:A) IN D` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[ECHECK_IMP]; ALL_TAC] THEN
  SUBGOAL_THEN `sc IN D /\ (vsc:A) IN D` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[ECHECK_IMP]; ALL_TAC] THEN
  SUBGOAL_THEN `bname D (E:A->A->bool) B vc` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`onebee:A`;`B:A`;`c:A`;`vc:A`]
                 ECHECK_IS_BNAME) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `bname D (E:A->A->bool) B vsc` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`onebee:A`;`B:A`;`sc:A`;`vsc:A`]
                 ECHECK_IS_BNAME) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) c sc` ASSUME_TAC THENL
   [UNDISCH_TAC
    `!dd. dd IN D ==> ((E:A->A->bool) dd sc <=> E dd c \/ dd = c)` THEN
    DISCH_THEN(MP_TAC o SPEC `c:A`) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(j:A) IN D /\ (E:A->A->bool) j B` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[EJOIN_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) z B` ASSUME_TAC THENL
   [MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`t:A`;`vsc:A`]
      EBV_IN_VAL_EXISTS) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(X_CHOOSE_THEN `q:A` STRIP_ASSUME_TAC) THEN
    SUBGOAL_THEN `z:A = q` SUBST1_TAC THENL
     [MATCH_MP_TAC(ISPECL
                   [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`t:A`;`vsc:A`;
                    `z:A`;`q:A`] EBV_IN_UNIQUE) THEN ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) zc B` ASSUME_TAC THENL
   [MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`t:A`;`vc:A`]
      EBV_IN_VAL_EXISTS) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(X_CHOOSE_THEN `q:A` STRIP_ASSUME_TAC) THEN
    SUBGOAL_THEN `zc:A = q` SUBST1_TAC THENL
     [MATCH_MP_TAC(ISPECL
                   [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`t:A`;`vc:A`;
                    `zc:A`;`q:A`] EBV_IN_UNIQUE) THEN ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) ec B` ASSUME_TAC THENL
   [MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`t:A`;`vc:A`]
      EBV_EQ_VAL_EXISTS) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(X_CHOOSE_THEN `q:A` STRIP_ASSUME_TAC) THEN
    SUBGOAL_THEN `ec:A = q` SUBST1_TAC THENL
     [MATCH_MP_TAC(ISPECL
                   [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`t:A`;`vc:A`;
                    `ec:A`;`q:A`] EBV_EQ_UNIQUE) THEN ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq z j` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`onebee:A`;
      `sc:A`;`vsc:A`;`t:A`;`z:A`;`j:A`] ECHECK_IN_LE_SUP) THEN
    ASM_REWRITE_TAC[] THEN
    MAP_EVERY X_GEN_TAC [`cp:A`;`vcp:A`;`ecp:A`] THEN STRIP_TAC THEN
    SUBGOAL_THEN `(cp:A) IN D` ASSUME_TAC THENL
     [ASM_MESON_TAC[ECHECK_IMP]; ALL_TAC] THEN
    SUBGOAL_THEN `(E:A->A->bool) cp c \/ cp = c` MP_TAC THENL
     [UNDISCH_TAC `(E:A->A->bool) cp sc` THEN
      UNDISCH_TAC
        `!dd. dd IN D ==> ((E:A->A->bool) dd sc <=> E dd c \/ dd = c)` THEN
        DISCH_THEN(MP_TAC o SPEC `cp:A`) THEN ASM_REWRITE_TAC[] THEN
        MESON_TAC[];
        ALL_TAC] THEN
    STRIP_TAC THENL
     [SUBGOAL_THEN `erel D (E:A->A->bool) leq ecp zc` ASSUME_TAC THENL
       [MATCH_MP_TAC(ISPECL
                     [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`onebee:A`;
                      `c:A`;`vc:A`;`cp:A`;`vcp:A`;`t:A`;`zc:A`;`ecp:A`]
                       ECHECK_IN_GE_ELT) THEN
        ASM_REWRITE_TAC[]; ALL_TAC] THEN
      SUBGOAL_THEN `erel D (E:A->A->bool) leq zc j` ASSUME_TAC THENL
       [ASM_MESON_TAC[EJOIN_GE]; ALL_TAC] THEN
      SUBGOAL_THEN `(E:A->A->bool) ecp B` ASSUME_TAC THENL
       [ASM_MESON_TAC[EPORDER_FIELD]; ALL_TAC] THEN
      MATCH_MP_TAC(ISPECL
                   [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`ecp:A`;`zc:A`;
                    `j:A`] EPORDER_TRANS) THEN ASM_REWRITE_TAC[];
      UNDISCH_TAC `cp:A = c` THEN DISCH_THEN SUBST_ALL_TAC THEN
      SUBGOAL_THEN `(vcp:A) = vc` SUBST_ALL_TAC THENL
       [MATCH_MP_TAC(ISPECL
                     [`D:A->bool`;`E:A->A->bool`;`onebee:A`;`c:A`;`vcp:A`;
                      `vc:A`] ECHECK_SV) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
      SUBGOAL_THEN `ecp:A = ec` SUBST_ALL_TAC THENL
       [MATCH_MP_TAC(ISPECL
                     [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`t:A`;`vc:A`;
                      `ecp:A`;`ec:A`] EBV_EQ_UNIQUE) THEN ASM_REWRITE_TAC[];
                   ALL_TAC] THEN
      ASM_MESON_TAC[EJOIN_GE]];
    ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq ec z` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`onebee:A`;
      `sc:A`;`vsc:A`;`c:A`;`vc:A`;`t:A`;`z:A`;`ec:A`] ECHECK_IN_GE_ELT) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq zc z` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`onebee:A`;
      `c:A`;`vc:A`;`t:A`;`zc:A`;`z:A`] ECHECK_IN_LE_SUP) THEN
    ASM_REWRITE_TAC[] THEN
    MAP_EVERY X_GEN_TAC [`d:A`;`vd:A`;`ed:A`] THEN STRIP_TAC THEN
    SUBGOAL_THEN `(d:A) IN D` ASSUME_TAC THENL
     [ASM_MESON_TAC[ECHECK_IMP]; ALL_TAC] THEN
    SUBGOAL_THEN `(E:A->A->bool) d sc` ASSUME_TAC THENL
     [UNDISCH_TAC `(E:A->A->bool) d c` THEN
      UNDISCH_TAC
        `!dd. dd IN D ==> ((E:A->A->bool) dd sc <=> E dd c \/ dd = c)` THEN
        DISCH_THEN(MP_TAC o SPEC `d:A`) THEN ASM_REWRITE_TAC[] THEN
        MESON_TAC[];
        ALL_TAC] THEN
    MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`onebee:A`;
      `sc:A`;`vsc:A`;`d:A`;`vd:A`;`t:A`;`z:A`;`ed:A`] ECHECK_IN_GE_ELT) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq j z` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`zc:A`;`ec:A`;
                  `j:A`;`z:A`] EJOIN_LEAST) THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`z:A`;`j:A`]
    EPORDER_ANTISYM) THEN ASM_REWRITE_TAC[]);;

(* ===================================================================== *)
(* BVALF_INFINITY lemma: [[infinity_ax]] = top in V^B.                     *)
(* infinity_ax = ?? 0 (EMPTY_CLAUSE && SUCC_CLAUSE), witnessed by the      *)
(* check-name of the model's omega. EMPTY_CLAUSE = ??- 1 0 (!!2 ~(2%%1));  *)
(* SUCC_CLAUSE = !!- 1 0 (??- 2 0 (!!3 (3%%2 <-> (3%%1 || Eq 3 1)))).       *)
(* Dependency chain: BVALF_ALL_GLB, EBV_SUCC_BICOND -> INF_SUCC_PERB ->    *)
(* INF_SUCC_PERC -> BVALF_INF_SUCC; BVALF_INF_EMPTY; then BVALF_INFINITY.  *)
(* ===================================================================== *)

(* GLB introduction for !! : x below every instance ==> x below the glb. *)
let BVALF_ALL_GLB = prove
 (`!n p D (E:A->A->bool) B leq v x.
      model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
      valuation D v /\ (!i. bname D E B (v i)) /\
      x IN D /\ E x B /\
      (!c. c IN D /\ bname D E B c
           ==> erel D E leq x (bvalf D E B leq ((n |-> c) v) p))
      ==> erel D E leq x (bvalf D E B leq v (!! n p))`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  MP_TAC(ISPECL [`!! n p`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`v:num->A`]
    BVALF_SPEC) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  REWRITE_TAC[bval] THEN
  INTRO_TAC "h @S. SD mem glb" THEN
  MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`S:A`;
    `bvalf D (E:A->A->bool) B leq v (!! n p)`;`x:A`] EGLB_GREATEST) THEN
  ASM_REWRITE_TAC[] THEN
  REWRITE_TAC[elbound] THEN ASM_REWRITE_TAC[] THEN
  X_GEN_TAC `zz:A` THEN STRIP_TAC THEN
  USE_THEN "mem" (fun th -> MP_TAC(SPEC `zz:A` th) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC]) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `a:A` STRIP_ASSUME_TAC) THEN
  SUBGOAL_THEN `!i. bname D E B (((n |-> (a:A)) (v:num->A)) i)`
    ASSUME_TAC THENL
   [MATCH_MP_TAC BNAMEVAL_VALMOD THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN
    `zz:A = bvalf D (E:A->A->bool) B leq ((n |-> (a:A)) (v:num->A)) p`
  SUBST1_TAC THENL
   [MATCH_MP_TAC(ISPECL [`p:form`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
      `(n |-> (a:A)) (v:num->A)`;`zz:A`] BVALF_EQ) THEN
    ASM_REWRITE_TAC[] THEN MATCH_MP_TAC VALUATION_VALMOD THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  FIRST_X_ASSUM MATCH_MP_TAC THEN ASM_REWRITE_TAC[]);;

(* Successor biconditional value bound: eac <= [[b IN sc^ <-> b IN c^ | *)
(* b=c^]]. *)
let EBV_SUCC_BICOND = prove
 (`!D (E:A->A->bool) B leq a b cv scv eac zbsc zbc ebcv zba eba dj
   ibic1 ibic2 bic.
      model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
      a IN D /\ b IN D /\ cv IN D /\ scv IN D /\
      bname D E B a /\ bname D E B b /\ bname D E B cv /\ bname D E B scv /\
      eac IN D /\ ebv_eq D E B leq a cv eac /\
      zbsc IN D /\ ebv_in D E B leq b scv zbsc /\
      zbc IN D /\ ebv_in D E B leq b cv zbc /\
      ebcv IN D /\ ebv_eq D E B leq b cv ebcv /\
      zba IN D /\ ebv_in D E B leq b a zba /\
      eba IN D /\ ebv_eq D E B leq b a eba /\
      ejoin D E B leq zbc ebcv zbsc /\
      dj IN D /\ ejoin D E B leq zba eba dj /\
      ibic1 IN D /\ ebimp D E B leq zbsc dj ibic1 /\
      ibic2 IN D /\ ebimp D E B leq dj zbsc ibic2 /\
      bic IN D /\ emeet D E B leq ibic1 ibic2 bic
      ==> erel D E leq eac bic`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `ebalg D (E:A->A->bool) B leq` ASSUME_TAC THENL
   [ASM_MESON_TAC[ECBA_IMP_BALG]; ALL_TAC] THEN
  SUBGOAL_THEN `eporder D (E:A->A->bool) B leq` ASSUME_TAC THENL
   [ASM_MESON_TAC[EBALG_IMP_PORDER]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) eac B` ASSUME_TAC THENL
   [ASM_MESON_TAC[EBV_EQ_IN_B]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) zbsc B` ASSUME_TAC THENL
   [ASM_MESON_TAC[EBV_IN_IN_B]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) zbc B` ASSUME_TAC THENL
   [ASM_MESON_TAC[EBV_IN_IN_B]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) ebcv B` ASSUME_TAC THENL
   [ASM_MESON_TAC[EBV_EQ_IN_B]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) zba B` ASSUME_TAC THENL
   [ASM_MESON_TAC[EBV_IN_IN_B]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) eba B` ASSUME_TAC THENL
   [ASM_MESON_TAC[EBV_EQ_IN_B]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) dj B` ASSUME_TAC THENL
   [ASM_MESON_TAC[EJOIN_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) ibic1 B` ASSUME_TAC THENL
   [ASM_MESON_TAC[EBIMP_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) ibic2 B` ASSUME_TAC THENL
   [ASM_MESON_TAC[EBIMP_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) bic B` ASSUME_TAC THENL
   [ASM_MESON_TAC[EMEET_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `ebv_eq D (E:A->A->bool) B leq cv a eac` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`a:A`;
                  `cv:A`;`eac:A`]
                 EBV_EQ_SYM) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* ===== direction (i): meet(eac,zbsc) <= dj ===== *)
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`eac:A`;`zbc:A`]
         EBALG_MEET) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `mac:A`) THEN
  SUBGOAL_THEN `(mac:A) IN D /\ (E:A->A->bool) mac B` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[EMEET_IN]; ALL_TAC] THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`eac:A`;`ebcv:A`]
         EBALG_MEET) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `mad:A`) THEN
  SUBGOAL_THEN `(mad:A) IN D /\ (E:A->A->bool) mad B` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[EMEET_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq mac zba` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`cv:A`;`a:A`;`b:A`;
                  `eac:A`;`zbc:A`;`zba:A`;`mac:A`] EBV_IN_CONG_R) THEN
         ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `emeet D (E:A->A->bool) B leq ebcv eac mad` ASSUME_TAC THENL
   [MATCH_MP_TAC EMEET_SYM THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq mad eba` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`b:A`;`cv:A`;`a:A`;
                  `ebcv:A`;`eac:A`;`eba:A`;`mad:A`] EBV_EQ_CONG) THEN
         ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`eac:A`;`zbsc:A`]
         EBALG_MEET) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `mI:A`) THEN
  SUBGOAL_THEN `(mI:A) IN D /\ (E:A->A->bool) mI B` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[EMEET_IN]; ALL_TAC] THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`mac:A`;`mad:A`]
         EBALG_JOIN) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `jmi:A`) THEN
  SUBGOAL_THEN `(jmi:A) IN D /\ (E:A->A->bool) jmi B` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[EJOIN_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `mI:A = jmi` SUBST_ALL_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`eac:A`;
                  `zbc:A`;`ebcv:A`;
                  `zbsc:A`;`mI:A`;`mac:A`;`mad:A`;`jmi:A`] EBALG_DISTRIB) THEN
         ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq mac dj` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`mac:A`;
                  `zba:A`;`dj:A`]
                 EPORDER_TRANS) THEN ASM_REWRITE_TAC[] THEN
         ASM_MESON_TAC[EJOIN_GE]; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq mad dj` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`mad:A`;
                  `eba:A`;`dj:A`]
                 EPORDER_TRANS) THEN ASM_REWRITE_TAC[] THEN
         ASM_MESON_TAC[EJOIN_GE]; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq jmi dj` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`mac:A`;`mad:A`;
                  `jmi:A`;`dj:A`]
                 EJOIN_LEAST) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq eac ibic1` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`eac:A`;
                  `zbsc:A`;`dj:A`;
                  `ibic1:A`;`jmi:A`] EBIMP_LE_IMP) THEN ASM_REWRITE_TAC[];
         ALL_TAC] THEN
  (* ===== direction (ii): meet(eac,dj) <= zbsc ===== *)
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`eac:A`;`zba:A`]
         EBALG_MEET) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `mba:A`) THEN
  SUBGOAL_THEN `(mba:A) IN D /\ (E:A->A->bool) mba B` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[EMEET_IN]; ALL_TAC] THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`eac:A`;`eba:A`]
         EBALG_MEET) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `mea:A`) THEN
  SUBGOAL_THEN `(mea:A) IN D /\ (E:A->A->bool) mea B` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[EMEET_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq mba zbc` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`a:A`;`cv:A`;`b:A`;
                  `eac:A`;`zba:A`;`zbc:A`;`mba:A`] EBV_IN_CONG_R) THEN
         ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `emeet D (E:A->A->bool) B leq eba eac mea` ASSUME_TAC THENL
   [MATCH_MP_TAC EMEET_SYM THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq mea ebcv` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`b:A`;`a:A`;`cv:A`;
                  `eba:A`;`eac:A`;`ebcv:A`;`mea:A`] EBV_EQ_CONG) THEN
         ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`eac:A`;`dj:A`]
         EBALG_MEET) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `mII:A`) THEN
  SUBGOAL_THEN `(mII:A) IN D /\ (E:A->A->bool) mII B` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[EMEET_IN]; ALL_TAC] THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`mba:A`;`mea:A`]
         EBALG_JOIN) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `jmii:A`) THEN
  SUBGOAL_THEN `(jmii:A) IN D /\ (E:A->A->bool) jmii B` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[EJOIN_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `mII:A = jmii` SUBST_ALL_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`eac:A`;
                  `zba:A`;`eba:A`;
                  `dj:A`;`mII:A`;`mba:A`;`mea:A`;`jmii:A`] EBALG_DISTRIB) THEN
         ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq mba zbsc` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`mba:A`;
                  `zbc:A`;`zbsc:A`]
                 EPORDER_TRANS) THEN ASM_REWRITE_TAC[] THEN
         ASM_MESON_TAC[EJOIN_GE]; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq mea zbsc` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`mea:A`;
                  `ebcv:A`;`zbsc:A`]
                 EPORDER_TRANS) THEN ASM_REWRITE_TAC[] THEN
         ASM_MESON_TAC[EJOIN_GE]; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq jmii zbsc` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`mba:A`;`mea:A`;
                  `jmii:A`;`zbsc:A`]
                 EJOIN_LEAST) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq eac ibic2` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`eac:A`;
                  `dj:A`;`zbsc:A`;
                  `ibic2:A`;`jmii:A`] EBIMP_LE_IMP) THEN ASM_REWRITE_TAC[];
         ALL_TAC] THEN
  MATCH_MP_TAC(ISPECL
               [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`ibic1:A`;`ibic2:A`;
                `bic:A`;`eac:A`]
               EMEET_GREATEST) THEN ASM_REWRITE_TAC[]);;

(* Per-b successor clause: eac <= [[(3%%2)<->(3%%1)||Eq 3 *)
(* 1]]_{1:=a,2:=scv,3:=b}. *)
let INF_SUCC_PERB = prove
 (`!D (E:A->A->bool) B leq onebee a b c sc cv scv eac w.
      model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
      onebee IN D /\ E onebee B /\ etop D E B leq onebee /\
      a IN D /\ bname D E B a /\ b IN D /\ bname D E B b /\
      c IN D /\ sc IN D /\ esuc D E c sc /\
      echeck D E onebee c cv /\ echeck D E onebee sc scv /\
      cv IN D /\ scv IN D /\ bname D E B cv /\ bname D E B scv /\
      eac IN D /\ ebv_eq D E B leq a cv eac /\
      valuation D w /\ (!i. bname D E B (w i)) /\
      w 1 = a /\ w 2 = scv /\ w 3 = b
      ==> erel D E leq eac
            (bvalf D E B leq w ((3 %% 2) <-> (3 %% 1) || Eq 3 1))`,
  let insimp p =
    MP_TAC(ISPECL [p;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`w:num->A`]
                  BVALF_SPEC) THEN ASM_SIMP_TAC[] in
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `ebalg D (E:A->A->bool) B leq` ASSUME_TAC THENL
   [ASM_MESON_TAC[ECBA_IMP_BALG]; ALL_TAC] THEN
  SUBGOAL_THEN `eporder D (E:A->A->bool) B leq` ASSUME_TAC THENL
   [ASM_MESON_TAC[EBALG_IMP_PORDER]; ALL_TAC] THEN
  (* successor characterization  E dd sc <=> E dd c \/ dd = c *)
  SUBGOAL_THEN `!dd:A. dd IN D ==> ((E:A->A->bool) dd sc <=> E dd c \/ dd = c)`
  ASSUME_TAC THENL
   [UNDISCH_TAC `esuc D (E:A->A->bool) c sc` THEN ASM_SIMP_TAC[ESUC_ALT] THEN
    STRIP_TAC THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* atomic Boolean values, folded to b,a,scv via w 1=a,w 2=scv,w 3=b *)
  MP_TAC(ISPECL [`3`;`2`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`w:num->A`]
    BVALF_MEM) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN ASM_REWRITE_TAC[] THEN
  DISCH_TAC THEN
  MP_TAC(ISPECL [`3`;`1`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`w:num->A`]
    BVALF_MEM) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN ASM_REWRITE_TAC[] THEN
  DISCH_TAC THEN
  MP_TAC(ISPECL [`3`;`1`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`w:num->A`]
    BVALF_EQ2) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN ASM_REWRITE_TAC[] THEN
  DISCH_TAC THEN
  MP_TAC(ISPECL [`3 %% 1`;`Eq 3 1`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
    `w:num->A`] BVALF_OR) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN DISCH_TAC THEN
  MP_TAC(ISPECL
         [`3 %% 2`;`(3 %% 1) || Eq 3 1`;`D:A->bool`;`E:A->A->bool`;`B:A`;
          `leq:A`;`w:num->A`] BVALF_IMP) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN DISCH_TAC THEN
  MP_TAC(ISPECL
         [`(3 %% 1) || Eq 3 1`;`3 %% 2`;`D:A->bool`;`E:A->A->bool`;`B:A`;
          `leq:A`;`w:num->A`] BVALF_IMP) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN DISCH_TAC THEN
  MP_TAC(ISPECL [`(3 %% 2) --> (3 %% 1) || Eq 3 1`;
    `((3 %% 1) || Eq 3 1) --> (3 %% 2)`;`D:A->bool`;`E:A->A->bool`;`B:A`;
    `leq:A`;`w:num->A`] BVALF_AND_MEET) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN DISCH_TAC THEN
  (* zbc = [[b IN cv]], ebcv = [[b = cv]] *)
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`b:A`;`cv:A`]
    EBV_IN_VAL_EXISTS) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `zbc:A` STRIP_ASSUME_TAC) THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`b:A`;`cv:A`]
    EBV_EQ_VAL_EXISTS) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `ebcv:A` STRIP_ASSUME_TAC) THEN
  (* j0 = zbc \/ ebcv *)
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`zbc:A`;`ebcv:A`]
    EBALG_JOIN) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_TAC `j0:A`) THEN
  SUBGOAL_THEN `(j0:A) IN D /\ (E:A->A->bool) j0 B` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[EJOIN_IN]; ALL_TAC] THEN
  (* IN D for all the bvalf values -- MUST precede the successor equation,
     since ECHECK_IN_SUCC requires z IN D = bvalf w (3 %% 2) IN D *)
  SUBGOAL_THEN
   `(bvalf D (E:A->A->bool) B leq w (3 %% 2)) IN D /\
    (bvalf D (E:A->A->bool) B leq w (3 %% 1)) IN D /\
    (bvalf D (E:A->A->bool) B leq w (Eq 3 1)) IN D /\
    (bvalf D (E:A->A->bool) B leq w ((3 %% 1) || Eq 3 1)) IN D /\
    (bvalf D (E:A->A->bool) B leq w ((3 %% 2) --> (3 %% 1) || Eq 3 1)) IN D /\
    (bvalf D (E:A->A->bool) B leq w
     (((3 %% 1) || Eq 3 1) --> (3 %% 2))) IN D /\
    (bvalf D (E:A->A->bool) B leq w
       (((3 %% 2) --> (3 %% 1) || Eq 3 1) &&
        (((3 %% 1) || Eq 3 1) --> (3 %% 2)))) IN D`
   STRIP_ASSUME_TAC THENL
   [REPEAT CONJ_TAC THENL
     [insimp `3 %% 2`; insimp `3 %% 1`; insimp `Eq 3 1`;
      insimp `(3 %% 1) || Eq 3 1`;
      insimp `(3 %% 2) --> (3 %% 1) || Eq 3 1`;
      insimp `((3 %% 1) || Eq 3 1) --> (3 %% 2)`;
      insimp `((3 %% 2) --> (3 %% 1) || Eq 3 1) &&
              (((3 %% 1) || Eq 3 1) --> (3 %% 2))`];
    ALL_TAC] THEN
  (* successor value equation  [[b IN sc^]] = j0 *)
  SUBGOAL_THEN `(bvalf D (E:A->A->bool) B leq w (3 %% 2)) = j0`
    ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`onebee:A`;
      `c:A`;`cv:A`;`sc:A`;`scv:A`;`b:A`;
      `bvalf D (E:A->A->bool) B leq w (3 %% 2)`;`zbc:A`;`ebcv:A`;`j0:A`]
      ECHECK_IN_SUCC) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN
    `ejoin D (E:A->A->bool) B leq zbc ebcv (bvalf D E B leq w (3 %% 2))`
  ASSUME_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* assemble via EBV_SUCC_BICOND *)
  REWRITE_TAC[Iff_DEF] THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
    `a:A`;`b:A`;`cv:A`;`scv:A`;`eac:A`;
    `bvalf D (E:A->A->bool) B leq w (3 %% 2)`;`zbc:A`;`ebcv:A`;
    `bvalf D (E:A->A->bool) B leq w (3 %% 1)`;
    `bvalf D (E:A->A->bool) B leq w (Eq 3 1)`;
    `bvalf D (E:A->A->bool) B leq w ((3 %% 1) || Eq 3 1)`;
    `bvalf D (E:A->A->bool) B leq w ((3 %% 2) --> (3 %% 1) || Eq 3 1)`;
    `bvalf D (E:A->A->bool) B leq w (((3 %% 1) || Eq 3 1) --> (3 %% 2))`;
    `bvalf D (E:A->A->bool) B leq w
       (((3 %% 2) --> (3 %% 1) || Eq 3 1) &&
        (((3 %% 1) || Eq 3 1) --> (3 %% 2)))`]
    EBV_SUCC_BICOND) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC]);;

(* Per-c successor clause: eac <= [[??- 2 0 (!! 3 ...)]]_u  (witness scv). *)
let INF_SUCC_PERC = prove
 (`!D (E:A->A->bool) B leq onebee om vom a c sc cv scv eac u.
      model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
      onebee IN D /\ E onebee B /\ etop D E B leq onebee /\
      eomega D E om /\ echeck D E onebee om vom /\
      a IN D /\ bname D E B a /\
      c IN D /\ E c om /\ esuc D E c sc /\
      echeck D E onebee c cv /\ echeck D E onebee sc scv /\
      cv IN D /\ scv IN D /\ bname D E B cv /\ bname D E B scv /\
      eac IN D /\ ebv_eq D E B leq a cv eac /\
      valuation D u /\ (!i. bname D E B (u i)) /\ u 0 = vom /\ u 1 = a
      ==> erel D E leq eac
            (bvalf D E B leq u
             (??- 2 0 (!! 3 ((3 %% 2) <-> (3 %% 1) || Eq 3 1))))`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `ebalg D (E:A->A->bool) B leq` ASSUME_TAC THENL
   [ASM_MESON_TAC[ECBA_IMP_BALG]; ALL_TAC] THEN
  SUBGOAL_THEN `eporder D (E:A->A->bool) B leq` ASSUME_TAC THENL
   [ASM_MESON_TAC[EBALG_IMP_PORDER]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) sc om` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`om:A`;`c:A`;`sc:A`]
                 EOMEGA_SUC) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(sc:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[ECHECK_IMP]; ALL_TAC] THEN
  SUBGOAL_THEN `valuation D ((2 |-> (scv:A)) u) /\
                (!i. bname D E B (((2 |-> (scv:A)) u) i))`
  STRIP_ASSUME_TAC THENL
   [CONJ_TAC THENL
     [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[];
      MATCH_MP_TAC BNAMEVAL_VALMOD THEN ASM_REWRITE_TAC[]]; ALL_TAC] THEN
  SUBGOAL_THEN `((2 |-> (scv:A)) u) 0 = vom /\ ((2 |-> (scv:A)) u) 1 = a /\
                ((2 |-> (scv:A)) u) 2 = scv`
  STRIP_ASSUME_TAC THENL
   [ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER; ARITH_EQ]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) eac B` ASSUME_TAC THENL
   [ASM_MESON_TAC[EBV_EQ_IN_B]; ALL_TAC] THEN
  SUBGOAL_THEN
    `ebv_in D (E:A->A->bool) B leq scv vom
     (bvalf D E B leq ((2 |-> scv) u) (2 %% 0))`
  ASSUME_TAC THENL
   [MP_TAC(ISPECL
           [`2`;`0`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
            `(2 |-> (scv:A)) u`]
           BVALF_MEM) THEN ASM_SIMP_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(bvalf D (E:A->A->bool) B leq ((2 |-> scv) u) (2 %% 0)) IN D`
  ASSUME_TAC THENL
   [MP_TAC(ISPECL
           [`2 %% 0`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
            `(2 |-> (scv:A)) u`]
           BVALF_SPEC) THEN ASM_SIMP_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN
    `etop D (E:A->A->bool) B leq (bvalf D E B leq ((2 |-> scv) u) (2 %% 0))`
  ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`onebee:A`;`sc:A`;
                  `om:A`;`scv:A`;`vom:A`;
                  `bvalf D (E:A->A->bool) B leq ((2 |-> scv) u) (2 %% 0)`]
      ECHECK_IN_TOP) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN
    `erel D (E:A->A->bool) leq eac
       (bvalf D E B leq ((2 |-> scv) u)
        (!! 3 ((3 %% 2) <-> (3 %% 1) || Eq 3 1)))`
  ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL [`3`; `(3 %% 2) <-> (3 %% 1) || Eq 3 1`;
      `D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`(2 |-> (scv:A)) u`;`eac:A`]
      BVALF_ALL_GLB) THEN
    ASM_REWRITE_TAC[] THEN
    X_GEN_TAC `bb:A` THEN STRIP_TAC THEN
    SUBGOAL_THEN `valuation D ((3 |-> (bb:A)) ((2 |-> scv) u)) /\
                  (!i. bname D E B (((3 |-> (bb:A)) ((2 |-> scv) u)) i))`
    STRIP_ASSUME_TAC THENL
     [CONJ_TAC THENL
       [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[];
        MATCH_MP_TAC BNAMEVAL_VALMOD THEN ASM_REWRITE_TAC[]]; ALL_TAC] THEN
    SUBGOAL_THEN `((3 |-> (bb:A)) ((2 |-> scv) u)) 1 = a /\
                  ((3 |-> (bb:A)) ((2 |-> scv) u)) 2 = scv /\
                  ((3 |-> (bb:A)) ((2 |-> scv) u)) 3 = bb`
    STRIP_ASSUME_TAC THENL
     [ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER; ARITH_EQ]; ALL_TAC] THEN
    MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`onebee:A`;
      `a:A`;`bb:A`;`c:A`;`sc:A`;`cv:A`;`scv:A`;`eac:A`;
      `(3 |-> (bb:A)) ((2 |-> scv) u)`] INF_SUCC_PERB) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN
    `emeet D (E:A->A->bool) B leq
       (bvalf D E B leq ((2 |-> scv) u) (2 %% 0))
       (bvalf D E B leq ((2 |-> scv) u)
        (!! 3 ((3 %% 2) <-> (3 %% 1) || Eq 3 1)))
       (bvalf D E B leq ((2 |-> scv) u)
          ((2 %% 0) && (!! 3 ((3 %% 2) <-> (3 %% 1) || Eq 3 1))))`
  ASSUME_TAC THENL
   [MP_TAC(ISPECL [`2 %% 0`; `!! 3 ((3 %% 2) <-> (3 %% 1) || Eq 3 1)`;
      `D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`(2 |-> (scv:A)) u`]
            BVALF_AND_MEET) THEN
    ASM_SIMP_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN
    `(bvalf D (E:A->A->bool) B leq ((2 |-> scv) u)
        ((2 %% 0) && (!! 3 ((3 %% 2) <-> (3 %% 1) || Eq 3 1)))) IN D /\
     (E:A->A->bool) (bvalf D E B leq ((2 |-> scv) u)
        ((2 %% 0) && (!! 3 ((3 %% 2) <-> (3 %% 1) || Eq 3 1)))) B`
  STRIP_ASSUME_TAC THENL
   [CONJ_TAC THENL
     [MP_TAC(ISPECL [`(2 %% 0) && (!! 3 ((3 %% 2) <-> (3 %% 1) || Eq 3 1))`;
        `D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`(2 |-> (scv:A)) u`]
        BVALF_SPEC) THEN
      ASM_SIMP_TAC[];
      MP_TAC(ISPECL [`(2 %% 0) && (!! 3 ((3 %% 2) <-> (3 %% 1) || Eq 3 1))`;
        `D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`(2 |-> (scv:A)) u`]
        BVALF_IN_B) THEN
      ASM_SIMP_TAC[]]; ALL_TAC] THEN
  SUBGOAL_THEN
    `erel D (E:A->A->bool) leq eac
       (bvalf D E B leq ((2 |-> scv) u)
          ((2 %% 0) && (!! 3 ((3 %% 2) <-> (3 %% 1) || Eq 3 1))))`
  ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
      `bvalf D (E:A->A->bool) B leq ((2 |-> scv) u) (2 %% 0)`;
      `bvalf D (E:A->A->bool) B leq ((2 |-> scv) u)
         (!! 3 ((3 %% 2) <-> (3 %% 1) || Eq 3 1))`;
      `bvalf D (E:A->A->bool) B leq ((2 |-> scv) u)
         ((2 %% 0) && (!! 3 ((3 %% 2) <-> (3 %% 1) || Eq 3 1)))`;
      `eac:A`] EMEET_GREATEST) THEN
    ASM_REWRITE_TAC[] THEN
    MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
      `bvalf D (E:A->A->bool) B leq ((2 |-> scv) u) (2 %% 0)`;`eac:A`]
            ETOP_GE) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  REWRITE_TAC[Existsmem_DEF] THEN
  MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`eac:A`;
    `bvalf D (E:A->A->bool) B leq ((2 |-> scv) u)
       ((2 %% 0) && (!! 3 ((3 %% 2) <-> (3 %% 1) || Eq 3 1)))`;
    `bvalf D (E:A->A->bool) B leq u
       (?? 2 ((2 %% 0) && (!! 3 ((3 %% 2) <-> (3 %% 1) || Eq 3 1))))`]
    EPORDER_TRANS) THEN
  ASM_REWRITE_TAC[] THEN
  REPEAT CONJ_TAC THENL
   [MP_TAC(ISPECL
           [`?? 2 ((2 %% 0) && (!! 3 ((3 %% 2) <-> (3 %% 1) || Eq 3 1)))`;
            `D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`u:num->A`]
             BVALF_SPEC) THEN ASM_SIMP_TAC[];
    MP_TAC(ISPECL
           [`?? 2 ((2 %% 0) && (!! 3 ((3 %% 2) <-> (3 %% 1) || Eq 3 1)))`;
            `D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`u:num->A`]
             BVALF_IN_B) THEN ASM_SIMP_TAC[];
    MATCH_MP_TAC(ISPECL
                 [`2`; `(2 %% 0) && (!! 3 ((3 %% 2) <-> (3 %% 1) || Eq 3 1))`;
                  `D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`u:num->A`;`scv:A`]
                   BVALF_EX_UB) THEN
    ASM_REWRITE_TAC[]]);;

(* SUCC_CLAUSE value = top. *)
let BVALF_INF_SUCC = prove
 (`!D (E:A->A->bool) B leq onebee om vom v.
      model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
      onebee IN D /\ E onebee B /\ etop D E B leq onebee /\
      (!u. u IN D ==> elmem D E u) /\
      eomega D E om /\ echeck D E onebee om vom /\
      valuation D v /\ (!i. bname D E B (v i)) /\ v 0 = vom
      ==> etop D E B leq
            (bvalf D E B leq v
               (!!- 1 0 (??- 2 0 (!! 3 ((3 %% 2) <-> (3 %% 1) || Eq 3 1)))))`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `ebalg D (E:A->A->bool) B leq` ASSUME_TAC THENL
   [ASM_MESON_TAC[ECBA_IMP_BALG]; ALL_TAC] THEN
  SUBGOAL_THEN `eporder D (E:A->A->bool) B leq` ASSUME_TAC THENL
   [ASM_MESON_TAC[EBALG_IMP_PORDER]; ALL_TAC] THEN
  MP_TAC(ISPECL [`1`;`0`;`??- 2 0 (!! 3 ((3 %% 2) <-> (3 %% 1) || Eq 3 1))`;
    `D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`v:num->A`]
              BVALF_FORALLMEM_TOP) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  X_GEN_TAC `a:A` THEN STRIP_TAC THEN
  SUBGOAL_THEN `valuation D ((1 |-> (a:A)) v) /\
                (!i. bname D E B (((1 |-> (a:A)) v) i))`
  STRIP_ASSUME_TAC THENL
   [CONJ_TAC THENL
     [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[];
      MATCH_MP_TAC BNAMEVAL_VALMOD THEN ASM_REWRITE_TAC[]]; ALL_TAC] THEN
  SUBGOAL_THEN `((1 |-> (a:A)) v) 0 = vom /\ ((1 |-> (a:A)) v) 1 = a`
  STRIP_ASSUME_TAC THENL
   [ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER; ARITH_EQ]; ALL_TAC] THEN
  SUBGOAL_THEN
    `ebv_in D (E:A->A->bool) B leq a vom
     (bvalf D E B leq ((1 |-> a) v) (1 %% 0))`
  ASSUME_TAC THENL
   [MP_TAC(ISPECL
           [`1`;`0`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`(1 |-> (a:A)) v`]
           BVALF_MEM) THEN ASM_SIMP_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(bvalf D (E:A->A->bool) B leq ((1 |-> a) v) (1 %% 0)) IN D`
  ASSUME_TAC THENL
   [MP_TAC(ISPECL
           [`1 %% 0`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
            `(1 |-> (a:A)) v`]
           BVALF_SPEC) THEN ASM_SIMP_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN
    `(bvalf D (E:A->A->bool) B leq ((1 |-> a) v)
        (??- 2 0 (!! 3 ((3 %% 2) <-> (3 %% 1) || Eq 3 1)))) IN D /\
     (E:A->A->bool) (bvalf D E B leq ((1 |-> a) v)
        (??- 2 0 (!! 3 ((3 %% 2) <-> (3 %% 1) || Eq 3 1)))) B`
  STRIP_ASSUME_TAC THENL
   [CONJ_TAC THENL
     [MP_TAC(ISPECL [`??- 2 0 (!! 3 ((3 %% 2) <-> (3 %% 1) || Eq 3 1))`;
        `D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`(1 |-> (a:A)) v`]
              BVALF_SPEC) THEN
      ASM_SIMP_TAC[];
      MP_TAC(ISPECL [`??- 2 0 (!! 3 ((3 %% 2) <-> (3 %% 1) || Eq 3 1))`;
        `D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`(1 |-> (a:A)) v`]
                BVALF_IN_B) THEN
      ASM_SIMP_TAC[]]; ALL_TAC] THEN
  MATCH_MP_TAC(ISPECL
               [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`onebee:A`;
                `om:A`;`vom:A`;
                `a:A`;
    `bvalf D (E:A->A->bool) B leq ((1 |-> a) v) (1 %% 0)`;
    `bvalf D (E:A->A->bool) B leq ((1 |-> a) v)
       (??- 2 0 (!! 3 ((3 %% 2) <-> (3 %% 1) || Eq 3 1)))`]
    ECHECK_IN_LE_SUP) THEN
  ASM_REWRITE_TAC[] THEN
  MAP_EVERY X_GEN_TAC [`c:A`;`vc:A`;`ec:A`] THEN STRIP_TAC THEN
  SUBGOAL_THEN `c IN D /\ (vc:A) IN D` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[ECHECK_IMP]; ALL_TAC] THEN
  SUBGOAL_THEN `bname D (E:A->A->bool) B vc` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`onebee:A`;`B:A`;`c:A`;`vc:A`]
                 ECHECK_IS_BNAME) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `?sc:A. esuc D (E:A->A->bool) c sc` (X_CHOOSE_TAC `sc:A`) THENL
   [MATCH_MP_TAC ESUC_EXISTS THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(sc:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[ESUC_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `?scv:A. echeck D (E:A->A->bool) onebee sc scv`
    (X_CHOOSE_TAC `scv:A`) THENL
   [MATCH_MP_TAC ECHECK_EXHAUSTION THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(scv:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[ECHECK_IMP]; ALL_TAC] THEN
  SUBGOAL_THEN `bname D (E:A->A->bool) B scv` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`onebee:A`;`B:A`;`sc:A`;`scv:A`]
                 ECHECK_IS_BNAME) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MATCH_MP_TAC(ISPECL
               [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`onebee:A`;
                `om:A`;`vom:A`;
                `a:A`;`c:A`;`sc:A`;`vc:A`;`scv:A`;`ec:A`;`(1 |-> (a:A)) v`]
                 INF_SUCC_PERC) THEN
  ASM_REWRITE_TAC[]);;

(* EMPTY_CLAUSE value = top (empty check-name has empty domain). *)
let BVALF_INF_EMPTY = prove
 (`!D (E:A->A->bool) B leq onebee om vom v.
      model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
      onebee IN D /\ E onebee B /\ etop D E B leq onebee /\
      (!u. u IN D ==> elmem D E u) /\
      eomega D E om /\ echeck D E onebee om vom /\
      valuation D v /\ (!i. bname D E B (v i)) /\ v 0 = vom
      ==> etop D E B leq
            (bvalf D E B leq v (??- 1 0 (!! 2 (Not(2 %% 1)))))`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `ebalg D (E:A->A->bool) B leq` ASSUME_TAC THENL
   [ASM_MESON_TAC[ECBA_IMP_BALG]; ALL_TAC] THEN
  SUBGOAL_THEN `eporder D (E:A->A->bool) B leq` ASSUME_TAC THENL
   [ASM_MESON_TAC[EBALG_IMP_PORDER]; ALL_TAC] THEN
  SUBGOAL_THEN `?emp:A. eempty D (E:A->A->bool) emp`
    (X_CHOOSE_TAC `emp:A`) THENL
   [MATCH_MP_TAC EEMPTY_EXISTS THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(emp:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[EEMPTY_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `!c:A. c IN D ==> ~((E:A->A->bool) c emp)` ASSUME_TAC THENL
   [ASM_MESON_TAC[eempty]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) emp om` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`om:A`;`emp:A`]
                 EOMEGA_EMPTY) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `?vemp:A. echeck D (E:A->A->bool) onebee emp vemp`
    (X_CHOOSE_TAC `vemp:A`) THENL
   [MATCH_MP_TAC ECHECK_EXHAUSTION THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(vemp:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[ECHECK_IMP]; ALL_TAC] THEN
  SUBGOAL_THEN `bname D (E:A->A->bool) B vemp` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`onebee:A`;`B:A`;`emp:A`;`vemp:A`]
                 ECHECK_IS_BNAME) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `valuation D ((1 |-> (vemp:A)) v) /\
                (!i. bname D E B (((1 |-> (vemp:A)) v) i))`
  STRIP_ASSUME_TAC THENL
   [CONJ_TAC THENL
     [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[];
      MATCH_MP_TAC BNAMEVAL_VALMOD THEN ASM_REWRITE_TAC[]]; ALL_TAC] THEN
  SUBGOAL_THEN `((1 |-> (vemp:A)) v) 0 = vom /\ ((1 |-> (vemp:A)) v) 1 = vemp`
  STRIP_ASSUME_TAC THENL
   [ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER; ARITH_EQ]; ALL_TAC] THEN
  MATCH_MP_TAC(ISPECL [`1`;`0`;`!! 2 (Not(2 %% 1))`;
    `D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`v:num->A`;`vemp:A`]
    BVALF_EXISTSMEM_TOP) THEN
  ASM_REWRITE_TAC[] THEN
  CONJ_TAC THENL
   [SUBGOAL_THEN
      `ebv_in D (E:A->A->bool) B leq vemp vom
       (bvalf D E B leq ((1 |-> vemp) v) (1 %% 0))`
    ASSUME_TAC THENL
     [MP_TAC(ISPECL
             [`1`;`0`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
              `(1 |-> (vemp:A)) v`]
             BVALF_MEM) THEN ASM_SIMP_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN
      `(bvalf D (E:A->A->bool) B leq ((1 |-> vemp) v) (1 %% 0)) IN D`
      ASSUME_TAC THENL
     [MP_TAC(ISPECL
             [`1 %% 0`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
              `(1 |-> (vemp:A)) v`]
             BVALF_SPEC) THEN ASM_SIMP_TAC[]; ALL_TAC] THEN
    MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`onebee:A`;
                  `emp:A`;`om:A`;
                  `vemp:A`;`vom:A`;
                  `bvalf D (E:A->A->bool) B leq ((1 |-> vemp) v) (1 %% 0)`]
      ECHECK_IN_TOP) THEN ASM_REWRITE_TAC[];
    MP_TAC(ISPECL [`2`;`Not(2 %% 1)`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
      `(1 |-> (vemp:A)) v`] BVALF_ALL_TOP) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    X_GEN_TAC `bb:A` THEN STRIP_TAC THEN
    SUBGOAL_THEN `valuation D ((2 |-> (bb:A)) ((1 |-> vemp) v)) /\
                  (!i. bname D E B (((2 |-> (bb:A)) ((1 |-> vemp) v)) i))`
    STRIP_ASSUME_TAC THENL
     [CONJ_TAC THENL
       [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[];
        MATCH_MP_TAC BNAMEVAL_VALMOD THEN ASM_REWRITE_TAC[]]; ALL_TAC] THEN
    SUBGOAL_THEN `((2 |-> (bb:A)) ((1 |-> vemp) v)) 1 = vemp /\
                  ((2 |-> (bb:A)) ((1 |-> vemp) v)) 2 = bb`
    STRIP_ASSUME_TAC THENL
     [ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER; ARITH_EQ]; ALL_TAC] THEN
    MP_TAC(ISPECL [`2 %% 1`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
      `(2 |-> (bb:A)) ((1 |-> vemp) v)`] BVALF_NOT_TOP) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    SUBGOAL_THEN
      `ebv_in D (E:A->A->bool) B leq bb vemp
         (bvalf D E B leq ((2 |-> bb) ((1 |-> vemp) v)) (2 %% 1))`
    ASSUME_TAC THENL
     [MP_TAC(ISPECL [`2`;`1`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
        `(2 |-> (bb:A)) ((1 |-> vemp) v)`] BVALF_MEM) THEN ASM_SIMP_TAC[];
         ALL_TAC] THEN
    SUBGOAL_THEN
      `(bvalf D (E:A->A->bool) B leq ((2 |-> bb) ((1 |-> vemp) v))
        (2 %% 1)) IN D`
    ASSUME_TAC THENL
     [MP_TAC(ISPECL [`2 %% 1`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
        `(2 |-> (bb:A)) ((1 |-> vemp) v)`] BVALF_SPEC) THEN ASM_SIMP_TAC[];
         ALL_TAC] THEN
    MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`onebee:A`;
                  `emp:A`;`vemp:A`;
                  `bb:A`;`bvalf D (E:A->A->bool) B leq
                          ((2 |-> bb) ((1 |-> vemp) v)) (2 %% 1)`]
      ECHECK_IN_EMPTY) THEN ASM_REWRITE_TAC[]]);;

(* [[infinity_ax]] = top. *)
let BVALF_INFINITY = prove
 (`!D (E:A->A->bool) B leq onebee om vom v.
      model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
      onebee IN D /\ E onebee B /\ etop D E B leq onebee /\
      (!u. u IN D ==> elmem D E u) /\
      eomega D E om /\ echeck D E onebee om vom /\
      valuation D v /\ (!i. bname D E B (v i))
      ==> etop D E B leq (bvalf D E B leq v infinity_ax)`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `ebalg D (E:A->A->bool) B leq` ASSUME_TAC THENL
   [ASM_MESON_TAC[ECBA_IMP_BALG]; ALL_TAC] THEN
  SUBGOAL_THEN `eporder D (E:A->A->bool) B leq` ASSUME_TAC THENL
   [ASM_MESON_TAC[EBALG_IMP_PORDER]; ALL_TAC] THEN
  SUBGOAL_THEN `(om:A) IN D /\ (vom:A) IN D` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[ECHECK_IMP]; ALL_TAC] THEN
  SUBGOAL_THEN `bname D (E:A->A->bool) B vom` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`onebee:A`;`B:A`;`om:A`;`vom:A`]
                 ECHECK_IS_BNAME) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  REWRITE_TAC[infinity_ax] THEN
  MATCH_MP_TAC(ISPECL [`0`;
    `(??- 1 0 (!! 2 (Not(2 %% 1)))) &&
     (!!- 1 0 (??- 2 0 (!! 3 ((3 %% 2) <-> (3 %% 1) || Eq 3 1))))`;
    `D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`v:num->A`;`vom:A`]
    BVALF_EX_TOP) THEN
  ASM_REWRITE_TAC[] THEN
  SUBGOAL_THEN `valuation D ((0 |-> (vom:A)) v) /\
                (!i. bname D E B (((0 |-> (vom:A)) v) i))`
  STRIP_ASSUME_TAC THENL
   [CONJ_TAC THENL
     [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[];
      MATCH_MP_TAC BNAMEVAL_VALMOD THEN ASM_REWRITE_TAC[]]; ALL_TAC] THEN
  SUBGOAL_THEN `((0 |-> (vom:A)) v) 0 = vom`
  ASSUME_TAC THENL
   [ASM_SIMP_TAC[VALMOD_BASIC]; ALL_TAC] THEN
  MP_TAC(ISPECL [`??- 1 0 (!! 2 (Not(2 %% 1)))`;
    `!!- 1 0 (??- 2 0 (!! 3 ((3 %% 2) <-> (3 %% 1) || Eq 3 1)))`;
    `D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`(0 |-> (vom:A)) v`]
       BVALF_AND_TOP) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  CONJ_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`onebee:A`;
                  `om:A`;`vom:A`;
                  `(0 |-> (vom:A)) v`] BVALF_INF_EMPTY) THEN
    ASM_REWRITE_TAC[];
    MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`onebee:A`;
                  `om:A`;`vom:A`;
                  `(0 |-> (vom:A)) v`] BVALF_INF_SUCC) THEN
    ASM_REWRITE_TAC[]]);;

(* ===================================================================== *)
(* F5, V^B:  FOUNDATION axiom    [[ foundation_ax ]]_v = top.            *)
(*                                                                       *)
(* Sixth ZFC axiom proved true in the Boolean-valued model V^B (after    *)
(* EXTENSIONALITY, PAIRING, UNION, INFINITY; SEPARATION machinery banked).*)
(* Proof is epsilon-induction on bnrank, internalised through the object  *)
(* formula found_bad_form so that M-s own separation+foundation           *)
(* (EORDINAL_LEAST) supplies an epsilon-minimal counterexample name.      *)
(* ===================================================================== *)

(* --- EMEET_BOT_COMPL: m /\ x = bot  ==>  m <= ~x. --- *)
let EMEET_BOT_COMPL = prove
 (`!D (E:A->A->bool) p leq m x cx mm bot.
      ebalg D E p leq /\ m IN D /\ x IN D /\ E m p /\ E x p /\
      ecompl D E p leq x cx /\ ebot D E p leq bot /\
      emeet D E p leq m x mm /\ erel D E leq mm bot
      ==> erel D E leq m cx`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `eporder D (E:A->A->bool) p leq` ASSUME_TAC THENL
   [ASM_MESON_TAC[EBALG_IMP_PORDER]; ALL_TAC] THEN
  SUBGOAL_THEN `(cx:A) IN D /\ (E:A->A->bool) cx p` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[ECOMPL_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `(bot:A) IN D /\ (E:A->A->bool) bot p` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[EBOT_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `ebimp D (E:A->A->bool) p leq x bot cx` ASSUME_TAC THENL
   [REWRITE_TAC[ebimp] THEN EXISTS_TAC `cx:A` THEN ASM_REWRITE_TAC[] THEN
    MATCH_MP_TAC EJOIN_SYM THEN MATCH_MP_TAC EJOIN_BOT THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`p:A`;`leq:A`;
    `m:A`;`x:A`;`bot:A`;`cx:A`;`mm:A`] EBIMP_LE_IMP) THEN
  ASM_REWRITE_TAC[]);;

(* --- FOUND_KBOT: the "k <= bot" Boolean step for the induction. --- *)
let FOUND_KBOT = prove
 (`!D (E:A->A->bool) B leq c b aa u0 y qy ey cc zba eyk g cg cyk bot.
      model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
      c IN D /\ E c B /\ b IN D /\ aa IN D /\ u0 IN D /\ y IN D /\
      bname D E B b /\ bname D E B aa /\ bname D E B u0 /\ bname D E B y /\
      qy IN D /\ ey IN D /\ cc IN D /\ zba IN D /\ eyk IN D /\
      g IN D /\ cg IN D /\ cyk IN D /\ bot IN D /\
      eapply D E u0 y qy /\
      ebv_eq D E B leq b y ey /\ ebv_in D E B leq b aa zba /\
      ebv_in D E B leq y aa eyk /\
      emeet D E B leq qy ey cc /\ emeet D E B leq c zba g /\
      ecompl D E B leq g cg /\ ecompl D E B leq eyk cyk /\
        ebot D E B leq bot /\
      erel D E leq c cyk
      ==> erel D E leq cc cg`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `ebalg D (E:A->A->bool) B leq` ASSUME_TAC THENL
   [ASM_MESON_TAC[ECBA_IMP_BALG]; ALL_TAC] THEN
  SUBGOAL_THEN `eporder D (E:A->A->bool) B leq` ASSUME_TAC THENL
   [ASM_MESON_TAC[EBALG_IMP_PORDER]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) qy B` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`u0:A`;`y:A`;`qy:A`]
      BNAME_APPLY_IN_B) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) ey B` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`b:A`;`y:A`;`ey:A`]
                 EBV_EQ_IN_B) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) zba B` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`b:A`;
                  `aa:A`;`zba:A`]
                 EBV_IN_IN_B) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) eyk B` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`y:A`;
                  `aa:A`;`eyk:A`]
                 EBV_IN_IN_B) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) cc B` ASSUME_TAC THENL
   [ASM_MESON_TAC[EMEET_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) g B` ASSUME_TAC THENL
   [ASM_MESON_TAC[EMEET_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) cg B` ASSUME_TAC THENL
   [ASM_MESON_TAC[ECOMPL_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) cyk B` ASSUME_TAC THENL
   [ASM_MESON_TAC[ECOMPL_IN]; ALL_TAC] THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`ey:A`;`zba:A`]
         EBALG_MEET) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_TAC `mby:A`) THEN
  SUBGOAL_THEN `(mby:A) IN D /\ (E:A->A->bool) mby B` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[EMEET_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq mby eyk` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`b:A`;`y:A`;`aa:A`;
                  `ey:A`;`zba:A`;`eyk:A`;`mby:A`] EBV_IN_CONG_L) THEN
         ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`cc:A`;`g:A`]
         EBALG_MEET) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_TAC `mm2:A`) THEN
  SUBGOAL_THEN `(mm2:A) IN D /\ (E:A->A->bool) mm2 B` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[EMEET_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq mm2 cc /\ erel D E leq mm2 g`
    STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[EMEET_LE]; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq cc qy /\ erel D E leq cc ey`
    STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[EMEET_LE]; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq g c /\ erel D E leq g zba`
    STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[EMEET_LE]; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq mm2 ey` ASSUME_TAC THENL
   [ASM_MESON_TAC[EPORDER_TRANS]; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq mm2 zba` ASSUME_TAC THENL
   [ASM_MESON_TAC[EPORDER_TRANS]; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq mm2 c` ASSUME_TAC THENL
   [ASM_MESON_TAC[EPORDER_TRANS]; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq mm2 mby` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`ey:A`;`zba:A`;
                  `mby:A`;`mm2:A`]
                 EMEET_GREATEST) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq mm2 eyk` ASSUME_TAC THENL
   [ASM_MESON_TAC[EPORDER_TRANS]; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq mm2 cyk` ASSUME_TAC THENL
   [ASM_MESON_TAC[EPORDER_TRANS]; ALL_TAC] THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`] EBALG_TOP) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `top:A`) THEN
  SUBGOAL_THEN `emeet D (E:A->A->bool) B leq eyk cyk bot` ASSUME_TAC THENL
   [MP_TAC(ISPECL
           [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`eyk:A`;`cyk:A`;
            `bot:A`;`top:A`]
           ECOMPL_MEET_JOIN) THEN ASM_REWRITE_TAC[] THEN STRIP_TAC THEN
         ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq mm2 bot` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`eyk:A`;`cyk:A`;
                  `bot:A`;`mm2:A`]
                 EMEET_GREATEST) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MATCH_MP_TAC(ISPECL
               [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`cc:A`;`g:A`;`cg:A`;
                `mm2:A`;`bot:A`]
               EMEET_BOT_COMPL) THEN
  ASM_REWRITE_TAC[]);;

(* --- FOUND_ZBU0_CG: [[b IN u0]] <= ~g under the induction hypothesis. --- *)
let FOUND_ZBU0_CG = prove
 (`!D (E:A->A->bool) B leq c aa u0 b zbu0 zba g cg vv.
      model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
      c IN D /\ E c B /\ aa IN D /\ u0 IN D /\ b IN D /\
      bname D E B aa /\ bname D E B u0 /\ bname D E B b /\
      valuation D vv /\ (!i. bname D E B (vv i)) /\ vv 0 = aa /\
      zbu0 IN D /\ zba IN D /\ g IN D /\ cg IN D /\
      ebv_in D E B leq b u0 zbu0 /\ ebv_in D E B leq b aa zba /\
      emeet D E B leq c zba g /\ ecompl D E B leq g cg /\
      (!y. y IN D /\ bname D E B y /\ eindom D E u0 y
           ==> erel D E leq c (bvalf D E B leq ((1 |-> y) vv) (Not(1 %% 0))))
      ==> erel D E leq zbu0 cg`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `ebalg D (E:A->A->bool) B leq` ASSUME_TAC THENL
   [ASM_MESON_TAC[ECBA_IMP_BALG]; ALL_TAC] THEN
  SUBGOAL_THEN `eporder D (E:A->A->bool) B leq` ASSUME_TAC THENL
   [ASM_MESON_TAC[EBALG_IMP_PORDER]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) cg B` ASSUME_TAC THENL
   [ASM_MESON_TAC[ECOMPL_IN]; ALL_TAC] THEN
  MATCH_MP_TAC(ISPECL
               [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`b:A`;`u0:A`;
                `zbu0:A`;`cg:A`]
               EBV_IN_LE_V) THEN
  ASM_REWRITE_TAC[] THEN
  MAP_EVERY X_GEN_TAC [`yv:A`;`qyv:A`;`eyv:A`;`ccv:A`] THEN STRIP_TAC THEN
  SUBGOAL_THEN `eindom D (E:A->A->bool) u0 yv` ASSUME_TAC THENL
   [REWRITE_TAC[eindom] THEN EXISTS_TAC `qyv:A` THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `bname D (E:A->A->bool) B yv` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`u0:A`;`yv:A`]
                 UNION_DOM_BNAME) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN
    `valuation D ((1 |-> (yv:A)) vv) /\
     (!i. bname D E B (((1 |-> (yv:A)) vv) i))`
  STRIP_ASSUME_TAC THENL
   [CONJ_TAC THENL
     [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[];
      MATCH_MP_TAC BNAMEVAL_VALMOD THEN ASM_REWRITE_TAC[]]; ALL_TAC] THEN
  SUBGOAL_THEN `((1 |-> (yv:A)) vv) 1 = yv /\ ((1 |-> (yv:A)) vv) 0 = aa`
  STRIP_ASSUME_TAC THENL
   [ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER; ARITH_EQ]; ALL_TAC] THEN
  SUBGOAL_THEN `ebv_in D (E:A->A->bool) B leq yv aa
                  (bvalf D E B leq ((1 |-> (yv:A)) vv) (1 %% 0))`
    ASSUME_TAC THENL
   [MP_TAC(ISPECL
           [`1`;`0`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
            `(1 |-> (yv:A)) vv`]
           BVALF_MEM) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN
    `(bvalf D (E:A->A->bool) B leq ((1 |-> (yv:A)) vv) (1 %% 0)) IN D`
  ASSUME_TAC THENL
   [MP_TAC(ISPECL
           [`1 %% 0`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
            `(1 |-> (yv:A)) vv`]
           BVALF_SPEC) THEN ASM_SIMP_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN
    `(bvalf D (E:A->A->bool) B leq ((1 |-> (yv:A)) vv) (Not(1 %% 0))) IN D`
  ASSUME_TAC THENL
   [MP_TAC(ISPECL
           [`Not(1 %% 0)`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
            `(1 |-> (yv:A)) vv`]
           BVALF_SPEC) THEN ASM_SIMP_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `ecompl D (E:A->A->bool) B leq
                  (bvalf D E B leq ((1 |-> (yv:A)) vv) (1 %% 0))
                  (bvalf D E B leq ((1 |-> (yv:A)) vv) (Not(1 %% 0)))`
    ASSUME_TAC THENL
   [MP_TAC(ISPECL
           [`1 %% 0`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
            `(1 |-> (yv:A)) vv`]
           BVALF_NOT) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq c
                  (bvalf D E B leq ((1 |-> (yv:A)) vv) (Not(1 %% 0)))`
    ASSUME_TAC THENL
   [FIRST_ASSUM MATCH_MP_TAC THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`] EBALG_BOT) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `bot:A`) THEN
  SUBGOAL_THEN `(bot:A) IN D` ASSUME_TAC THENL
  [ASM_MESON_TAC[EBOT_IN]; ALL_TAC] THEN
  MATCH_MP_TAC(ISPECL
               [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`c:A`;`b:A`;
                `aa:A`;`u0:A`;
                `yv:A`;`qyv:A`;`eyv:A`;`ccv:A`;`zba:A`;
    `bvalf D (E:A->A->bool) B leq ((1 |-> (yv:A)) vv) (1 %% 0)`;`g:A`;`cg:A`;
    `bvalf D (E:A->A->bool) B leq ((1 |-> (yv:A)) vv) (Not(1 %% 0))`;`bot:A`]
                 FOUND_KBOT) THEN
  ASM_REWRITE_TAC[]);;

(* --- FOUND_IMP_BA: Boolean-algebra core of the implication clause. --- *)
let FOUND_IMP_BA = prove
 (`!D (E:A->A->bool) B leq c zbu0 zba ncba imp g cg.
      ecba D E B leq /\ B IN D /\
      c IN D /\ E c B /\ zbu0 IN D /\ E zbu0 B /\ zba IN D /\ E zba B /\
      ncba IN D /\ imp IN D /\ g IN D /\ cg IN D /\
      ecompl D E B leq zba ncba /\ ebimp D E B leq zbu0 ncba imp /\
      emeet D E B leq c zba g /\ ecompl D E B leq g cg /\
      erel D E leq zbu0 cg
      ==> erel D E leq c imp`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `ebalg D (E:A->A->bool) B leq` ASSUME_TAC THENL
   [ASM_MESON_TAC[ECBA_IMP_BALG]; ALL_TAC] THEN
  SUBGOAL_THEN `eporder D (E:A->A->bool) B leq` ASSUME_TAC THENL
   [ASM_MESON_TAC[EBALG_IMP_PORDER]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) ncba B` ASSUME_TAC THENL
   [ASM_MESON_TAC[ECOMPL_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) g B` ASSUME_TAC THENL
   [ASM_MESON_TAC[EMEET_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) cg B` ASSUME_TAC THENL
   [ASM_MESON_TAC[ECOMPL_IN]; ALL_TAC] THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`c:A`;`zbu0:A`]
         EBALG_MEET) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `m1:A`) THEN
  SUBGOAL_THEN `(m1:A) IN D /\ (E:A->A->bool) m1 B` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[EMEET_IN]; ALL_TAC] THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`m1:A`;`zba:A`]
         EBALG_MEET) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `mm2:A`) THEN
  SUBGOAL_THEN `(mm2:A) IN D /\ (E:A->A->bool) mm2 B` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[EMEET_IN]; ALL_TAC] THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`] EBALG_BOT) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `bot:A`) THEN
  SUBGOAL_THEN `(bot:A) IN D` ASSUME_TAC THENL
  [ASM_MESON_TAC[EBOT_IN]; ALL_TAC] THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`] EBALG_TOP) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `top:A`) THEN
  SUBGOAL_THEN `(top:A) IN D` ASSUME_TAC THENL
  [ASM_MESON_TAC[ETOP_IN]; ALL_TAC] THEN
  SUBGOAL_THEN
    `emeet D (E:A->A->bool) B leq g cg bot /\ ejoin D E B leq g cg top`
  STRIP_ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`g:A`;`cg:A`;
                  `bot:A`;`top:A`]
                 ECOMPL_MEET_JOIN) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq mm2 m1 /\ erel D E leq mm2 zba`
    STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[EMEET_LE]; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq m1 c /\ erel D E leq m1 zbu0`
    STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[EMEET_LE]; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq mm2 c` ASSUME_TAC THENL
   [ASM_MESON_TAC[EPORDER_TRANS]; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq mm2 zbu0` ASSUME_TAC THENL
   [ASM_MESON_TAC[EPORDER_TRANS]; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq mm2 g` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`c:A`;`zba:A`;
                  `g:A`;`mm2:A`]
                 EMEET_GREATEST) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq mm2 cg` ASSUME_TAC THENL
   [ASM_MESON_TAC[EPORDER_TRANS]; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq mm2 bot` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`g:A`;`cg:A`;
                  `bot:A`;`mm2:A`]
                 EMEET_GREATEST) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq m1 ncba` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`m1:A`;
                  `zba:A`;`ncba:A`;
                  `mm2:A`;`bot:A`] EMEET_BOT_COMPL) THEN ASM_REWRITE_TAC[];
         ALL_TAC] THEN
  MATCH_MP_TAC(ISPECL
               [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`c:A`;
                `zbu0:A`;`ncba:A`;
                `imp:A`;`m1:A`] EBIMP_LE_IMP) THEN
  ASM_REWRITE_TAC[]);;

(* --- FOUND_PERB: per-element  c <= [[ (2 IN 1) --> ~(2 IN 0) ]]. --- *)
let FOUND_PERB = prove
 (`!D (E:A->A->bool) B leq c aa u0 b vv.
      model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
      c IN D /\ E c B /\ aa IN D /\ u0 IN D /\ b IN D /\
      bname D E B aa /\ bname D E B u0 /\ bname D E B b /\
      valuation D vv /\ (!i. bname D E B (vv i)) /\ vv 0 = aa /\
      (!y. y IN D /\ bname D E B y /\ eindom D E u0 y
           ==> erel D E leq c (bvalf D E B leq ((1 |-> y) vv) (Not(1 %% 0))))
      ==> erel D E leq c
            (bvalf D E B leq ((2 |-> b) ((1 |-> u0) vv))
             ((2 %% 1) --> Not(2 %% 0)))`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `ebalg D (E:A->A->bool) B leq` ASSUME_TAC THENL
   [ASM_MESON_TAC[ECBA_IMP_BALG]; ALL_TAC] THEN
  SUBGOAL_THEN `eporder D (E:A->A->bool) B leq` ASSUME_TAC THENL
   [ASM_MESON_TAC[EBALG_IMP_PORDER]; ALL_TAC] THEN
  SUBGOAL_THEN
    `valuation D ((1 |-> (u0:A)) vv) /\
     (!i. bname D E B (((1 |-> (u0:A)) vv) i))`
  STRIP_ASSUME_TAC THENL
   [CONJ_TAC THENL
     [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[];
      MATCH_MP_TAC BNAMEVAL_VALMOD THEN ASM_REWRITE_TAC[]]; ALL_TAC] THEN
  SUBGOAL_THEN `valuation D ((2 |-> (b:A)) ((1 |-> u0) vv)) /\
                (!i. bname D E B (((2 |-> (b:A)) ((1 |-> u0) vv)) i))`
  STRIP_ASSUME_TAC THENL
   [CONJ_TAC THENL
     [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[];
      MATCH_MP_TAC BNAMEVAL_VALMOD THEN ASM_REWRITE_TAC[]]; ALL_TAC] THEN
  SUBGOAL_THEN `((2 |-> (b:A)) ((1 |-> u0) vv)) 2 = b /\
                ((2 |-> (b:A)) ((1 |-> u0) vv)) 1 = u0 /\
                ((2 |-> (b:A)) ((1 |-> u0) vv)) 0 = aa`
  STRIP_ASSUME_TAC THENL
   [ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER; ARITH_EQ]; ALL_TAC] THEN
  SUBGOAL_THEN `ebv_in D (E:A->A->bool) B leq b u0
                  (bvalf D E B leq ((2 |-> (b:A)) ((1 |-> u0) vv)) (2 %% 1))`
    ASSUME_TAC THENL
   [MP_TAC(ISPECL [`2`;`1`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
      `(2 |-> (b:A)) ((1 |-> u0) vv)`] BVALF_MEM) THEN ASM_REWRITE_TAC[];
                  ALL_TAC] THEN
  SUBGOAL_THEN
    `(bvalf D (E:A->A->bool) B leq ((2 |-> (b:A)) ((1 |-> u0) vv))
      (2 %% 1)) IN D`
  ASSUME_TAC THENL
   [MP_TAC(ISPECL [`2 %% 1`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
      `(2 |-> (b:A)) ((1 |-> u0) vv)`] BVALF_SPEC) THEN ASM_SIMP_TAC[];
                  ALL_TAC] THEN
  SUBGOAL_THEN
    `(E:A->A->bool)
     (bvalf D E B leq ((2 |-> (b:A)) ((1 |-> u0) vv)) (2 %% 1)) B`
  ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`b:A`;`u0:A`;
      `bvalf D (E:A->A->bool) B leq ((2 |-> (b:A)) ((1 |-> u0) vv)) (2 %% 1)`]
        EBV_IN_IN_B) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `ebv_in D (E:A->A->bool) B leq b aa
                  (bvalf D E B leq ((2 |-> (b:A)) ((1 |-> u0) vv)) (2 %% 0))`
    ASSUME_TAC THENL
   [MP_TAC(ISPECL [`2`;`0`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
      `(2 |-> (b:A)) ((1 |-> u0) vv)`] BVALF_MEM) THEN ASM_REWRITE_TAC[];
                  ALL_TAC] THEN
  SUBGOAL_THEN
    `(bvalf D (E:A->A->bool) B leq ((2 |-> (b:A)) ((1 |-> u0) vv))
      (2 %% 0)) IN D`
  ASSUME_TAC THENL
   [MP_TAC(ISPECL [`2 %% 0`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
      `(2 |-> (b:A)) ((1 |-> u0) vv)`] BVALF_SPEC) THEN ASM_SIMP_TAC[];
                  ALL_TAC] THEN
  SUBGOAL_THEN
    `(E:A->A->bool)
     (bvalf D E B leq ((2 |-> (b:A)) ((1 |-> u0) vv)) (2 %% 0)) B`
  ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`b:A`;`aa:A`;
      `bvalf D (E:A->A->bool) B leq ((2 |-> (b:A)) ((1 |-> u0) vv)) (2 %% 0)`]
        EBV_IN_IN_B) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `ecompl D (E:A->A->bool) B leq
                  (bvalf D E B leq ((2 |-> (b:A)) ((1 |-> u0) vv)) (2 %% 0))
                  (bvalf D E B leq ((2 |-> (b:A)) ((1 |-> u0) vv))
                   (Not(2 %% 0)))` ASSUME_TAC THENL
   [MP_TAC(ISPECL [`2 %% 0`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
      `(2 |-> (b:A)) ((1 |-> u0) vv)`] BVALF_NOT) THEN ASM_REWRITE_TAC[];
                  ALL_TAC] THEN
  SUBGOAL_THEN
    `(bvalf D (E:A->A->bool) B leq ((2 |-> (b:A)) ((1 |-> u0) vv))
      (Not(2 %% 0))) IN D`
  ASSUME_TAC THENL
   [ASM_MESON_TAC[ECOMPL_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `ebimp D (E:A->A->bool) B leq
                  (bvalf D E B leq ((2 |-> (b:A)) ((1 |-> u0) vv)) (2 %% 1))
                  (bvalf D E B leq ((2 |-> (b:A)) ((1 |-> u0) vv))
                   (Not(2 %% 0)))
                  (bvalf D E B leq ((2 |-> (b:A)) ((1 |-> u0) vv))
                   ((2 %% 1) --> Not(2 %% 0)))`
  ASSUME_TAC THENL
   [MP_TAC(ISPECL
           [`2 %% 1`;`Not(2 %% 0)`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
            `(2 |-> (b:A)) ((1 |-> u0) vv)`] BVALF_IMP) THEN ASM_REWRITE_TAC[];
                  ALL_TAC] THEN
  SUBGOAL_THEN `(bvalf D (E:A->A->bool) B leq ((2 |-> (b:A)) ((1 |-> u0) vv))
                  ((2 %% 1) --> Not(2 %% 0))) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[EBIMP_IN]; ALL_TAC] THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`c:A`;
    `bvalf D (E:A->A->bool) B leq ((2 |-> (b:A)) ((1 |-> u0) vv)) (2 %% 0)`]
                    EBALG_MEET) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `g:A`) THEN
  SUBGOAL_THEN `(g:A) IN D /\ (E:A->A->bool) g B` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[EMEET_IN]; ALL_TAC] THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`g:A`]
         EBALG_COMPL) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `cg:A`) THEN
  SUBGOAL_THEN `(cg:A) IN D` ASSUME_TAC THENL
  [ASM_MESON_TAC[ECOMPL_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq
                  (bvalf D E B leq ((2 |-> (b:A)) ((1 |-> u0) vv)) (2 %% 1))
                    cg` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`c:A`;`aa:A`;
                  `u0:A`;`b:A`;
                  `bvalf D (E:A->A->bool) B leq
                   ((2 |-> (b:A)) ((1 |-> u0) vv)) (2 %% 1)`;
      `bvalf D (E:A->A->bool) B leq ((2 |-> (b:A)) ((1 |-> u0) vv)) (2 %% 0)`;
      `g:A`;`cg:A`;`vv:num->A`] FOUND_ZBU0_CG) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`c:A`;
    `bvalf D (E:A->A->bool) B leq ((2 |-> (b:A)) ((1 |-> u0) vv)) (2 %% 1)`;
    `bvalf D (E:A->A->bool) B leq ((2 |-> (b:A)) ((1 |-> u0) vv)) (2 %% 0)`;
    `bvalf D (E:A->A->bool) B leq ((2 |-> (b:A)) ((1 |-> u0) vv))
     (Not(2 %% 0))`;
    `bvalf D (E:A->A->bool) B leq ((2 |-> (b:A)) ((1 |-> u0) vv))
     ((2 %% 1) --> Not(2 %% 0))`;
    `g:A`;`cg:A`] FOUND_IMP_BA) THEN
  ASM_REWRITE_TAC[]);;

(* --- FOUND_MINL: c <= [[ !!- 2 1 ~(2 IN 0) ]] (u0 is epsilon-minimal). --- *)
let FOUND_MINL = prove
 (`!D (E:A->A->bool) B leq c aa u0 vv.
      model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
      c IN D /\ E c B /\ aa IN D /\ u0 IN D /\
      bname D E B aa /\ bname D E B u0 /\
      valuation D vv /\ (!i. bname D E B (vv i)) /\ vv 0 = aa /\
      (!y. y IN D /\ bname D E B y /\ eindom D E u0 y
           ==> erel D E leq c (bvalf D E B leq ((1 |-> y) vv) (Not(1 %% 0))))
      ==> erel D E leq c
            (bvalf D E B leq ((1 |-> u0) vv) (!!- 2 1 (Not(2 %% 0))))`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN
    `valuation D ((1 |-> (u0:A)) vv) /\
     (!i. bname D E B (((1 |-> (u0:A)) vv) i))`
  STRIP_ASSUME_TAC THENL
   [CONJ_TAC THENL
     [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[];
      MATCH_MP_TAC BNAMEVAL_VALMOD THEN ASM_REWRITE_TAC[]]; ALL_TAC] THEN
  REWRITE_TAC[Forallmem_DEF] THEN
  MATCH_MP_TAC(ISPECL
               [`2`;`(2 %% 1) --> Not(2 %% 0)`;`D:A->bool`;`E:A->A->bool`;
                `B:A`;`leq:A`;
                `(1 |-> (u0:A)) vv`;`c:A`] BVALF_ALL_GLB) THEN
  ASM_REWRITE_TAC[] THEN
  X_GEN_TAC `a:A` THEN STRIP_TAC THEN
  MATCH_MP_TAC(ISPECL
               [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`c:A`;`aa:A`;
                `u0:A`;`a:A`;
                `vv:num->A`] FOUND_PERB) THEN
  ASM_REWRITE_TAC[]);;

(* --- FOUND_STEP_BA: c<=s /\ c<=~(m/\s) ==> c<=~m  (Boolean step). --- *)
let FOUND_STEP_BA = prove
 (`!D (E:A->A->bool) B leq c m s ms nms ncm.
      ecba D E B leq /\ B IN D /\
      c IN D /\ E c B /\ m IN D /\ E m B /\ s IN D /\ E s B /\
      ms IN D /\ E ms B /\ nms IN D /\ ncm IN D /\
      emeet D E B leq m s ms /\ ecompl D E B leq ms nms /\
        ecompl D E B leq m ncm /\
      erel D E leq c s /\ erel D E leq c nms
      ==> erel D E leq c ncm`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `ebalg D (E:A->A->bool) B leq` ASSUME_TAC THENL
   [ASM_MESON_TAC[ECBA_IMP_BALG]; ALL_TAC] THEN
  SUBGOAL_THEN `eporder D (E:A->A->bool) B leq` ASSUME_TAC THENL
   [ASM_MESON_TAC[EBALG_IMP_PORDER]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) nms B` ASSUME_TAC THENL
   [ASM_MESON_TAC[ECOMPL_IN]; ALL_TAC] THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`c:A`;`m:A`]
         EBALG_MEET) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `cm:A`) THEN
  SUBGOAL_THEN `(cm:A) IN D /\ (E:A->A->bool) cm B` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[EMEET_IN]; ALL_TAC] THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`] EBALG_BOT) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `bot:A`) THEN
  SUBGOAL_THEN `(bot:A) IN D` ASSUME_TAC THENL
  [ASM_MESON_TAC[EBOT_IN]; ALL_TAC] THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`] EBALG_TOP) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `top:A`) THEN
  SUBGOAL_THEN `(top:A) IN D` ASSUME_TAC THENL
  [ASM_MESON_TAC[ETOP_IN]; ALL_TAC] THEN
  SUBGOAL_THEN
    `emeet D (E:A->A->bool) B leq ms nms bot /\ ejoin D E B leq ms nms top`
  STRIP_ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`ms:A`;`nms:A`;
                  `bot:A`;`top:A`]
                 ECOMPL_MEET_JOIN) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq cm c /\ erel D E leq cm m`
    STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[EMEET_LE]; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq cm s` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`cm:A`;`c:A`;`s:A`]
                 EPORDER_TRANS) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq cm nms` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`cm:A`;
                  `c:A`;`nms:A`]
                 EPORDER_TRANS) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq cm ms` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`m:A`;`s:A`;
                  `ms:A`;`cm:A`]
                 EMEET_GREATEST) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq cm bot` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`ms:A`;`nms:A`;
                  `bot:A`;`cm:A`]
                 EMEET_GREATEST) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MATCH_MP_TAC(ISPECL
               [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`c:A`;`m:A`;`ncm:A`;
                `cm:A`;`bot:A`] EMEET_BOT_COMPL) THEN
  ASM_REWRITE_TAC[]);;

(* --- FOUND_STEP: IH + c<=[[~(1IN0 && minimal)]]  ==>  c<=[[~(1 IN 0)]]. *)
(* --- *)
let FOUND_STEP = prove
 (`!D (E:A->A->bool) B leq c aa u0 vv.
      model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
      c IN D /\ E c B /\ aa IN D /\ u0 IN D /\
      bname D E B aa /\ bname D E B u0 /\
      valuation D vv /\ (!i. bname D E B (vv i)) /\ vv 0 = aa /\
      (!y. y IN D /\ bname D E B y /\ eindom D E u0 y
           ==> erel D E leq c
             (bvalf D E B leq ((1 |-> y) vv) (Not(1 %% 0)))) /\
      erel D E leq c
        (bvalf D E B leq ((1 |-> u0) vv)
           (Not((1 %% 0) && (!!- 2 1 (Not(2 %% 0))))))
      ==> erel D E leq c (bvalf D E B leq ((1 |-> u0) vv) (Not(1 %% 0)))`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `ebalg D (E:A->A->bool) B leq` ASSUME_TAC THENL
   [ASM_MESON_TAC[ECBA_IMP_BALG]; ALL_TAC] THEN
  SUBGOAL_THEN `eporder D (E:A->A->bool) B leq` ASSUME_TAC THENL
   [ASM_MESON_TAC[EBALG_IMP_PORDER]; ALL_TAC] THEN
  SUBGOAL_THEN `valuation D ((1 |-> (u0:A)) vv) /\
                (!i. bname D (E:A->A->bool) B (((1 |-> (u0:A)) vv) i))`
  STRIP_ASSUME_TAC THENL
   [CONJ_TAC THENL
     [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[];
      MATCH_MP_TAC BNAMEVAL_VALMOD THEN ASM_REWRITE_TAC[]]; ALL_TAC] THEN
  MP_TAC(ISPECL [`(1 %% 0)`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
    `(1 |-> (u0:A)) vv`] BVALF_SPEC) THEN
  ASM_REWRITE_TAC[] THEN STRIP_TAC THEN
  MP_TAC(ISPECL [`(1 %% 0)`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
    `(1 |-> (u0:A)) vv`] BVALF_IN_B) THEN
  ASM_REWRITE_TAC[] THEN DISCH_TAC THEN
  MP_TAC(ISPECL
         [`!!- 2 1 (Not(2 %% 0))`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
          `(1 |-> (u0:A)) vv`] BVALF_SPEC) THEN
  ASM_REWRITE_TAC[] THEN STRIP_TAC THEN
  MP_TAC(ISPECL
         [`!!- 2 1 (Not(2 %% 0))`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
          `(1 |-> (u0:A)) vv`] BVALF_IN_B) THEN
  ASM_REWRITE_TAC[] THEN DISCH_TAC THEN
  MP_TAC(ISPECL
         [`(1 %% 0)`;`!!- 2 1 (Not(2 %% 0))`;`D:A->bool`;`E:A->A->bool`;
          `B:A`;`leq:A`;
          `(1 |-> (u0:A)) vv`] BVALF_AND_MEET) THEN
  ASM_REWRITE_TAC[] THEN DISCH_TAC THEN
  SUBGOAL_THEN
    `(bvalf D (E:A->A->bool) B leq ((1 |-> (u0:A)) vv)
        ((1 %% 0) && (!!- 2 1 (Not(2 %% 0))))) IN D /\
     (E:A->A->bool) (bvalf D E B leq ((1 |-> (u0:A)) vv)
        ((1 %% 0) && (!!- 2 1 (Not(2 %% 0))))) B`
  STRIP_ASSUME_TAC THENL [ASM_MESON_TAC[EMEET_IN]; ALL_TAC] THEN
  MP_TAC(ISPECL
         [`(1 %% 0) && (!!- 2 1 (Not(2 %% 0)))`;`D:A->bool`;`E:A->A->bool`;
          `B:A`;`leq:A`;
          `(1 |-> (u0:A)) vv`] BVALF_NOT) THEN
  ASM_REWRITE_TAC[] THEN DISCH_TAC THEN
  SUBGOAL_THEN
    `(bvalf D (E:A->A->bool) B leq ((1 |-> (u0:A)) vv)
        (Not((1 %% 0) && (!!- 2 1 (Not(2 %% 0)))))) IN D`
  ASSUME_TAC THENL [ASM_MESON_TAC[ECOMPL_IN]; ALL_TAC] THEN
  MP_TAC(ISPECL [`(1 %% 0)`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
    `(1 |-> (u0:A)) vv`] BVALF_NOT) THEN
  ASM_REWRITE_TAC[] THEN DISCH_TAC THEN
  SUBGOAL_THEN
    `(bvalf D (E:A->A->bool) B leq ((1 |-> (u0:A)) vv) (Not(1 %% 0))) IN D`
  ASSUME_TAC THENL [ASM_MESON_TAC[ECOMPL_IN]; ALL_TAC] THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`c:A`;`aa:A`;`u0:A`;
    `vv:num->A`] FOUND_MINL) THEN
  ASM_REWRITE_TAC[] THEN DISCH_TAC THEN
  MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`c:A`;
    `bvalf D E B leq ((1 |-> (u0:A)) vv) (1 %% 0)`;
    `bvalf D E B leq ((1 |-> (u0:A)) vv) (!!- 2 1 (Not(2 %% 0)))`;
    `bvalf D E B leq ((1 |-> (u0:A)) vv)
     ((1 %% 0) && (!!- 2 1 (Not(2 %% 0))))`;
    `bvalf D E B leq ((1 |-> (u0:A)) vv)
     (Not((1 %% 0) && (!!- 2 1 (Not(2 %% 0)))))`;
    `bvalf D E B leq ((1 |-> (u0:A)) vv) (Not(1 %% 0))`] FOUND_STEP_BA) THEN
  ASM_REWRITE_TAC[]);;

(* --- found_val_form/found_bad_form + HOLDS_* : object-formula encoding *)
(*     of "u is an epsilon-minimal bad name", for EORDINAL_LEAST. --- *)
let found_val_form = new_definition
  `found_val_form =
     ?? 20 (?? 21 (?? 24 (
        ebv_in_form 20 1 6 5 && bcompl_form 5 2 20 21 &&
        bimp_form 5 2 7 21 24 && Not(btop_form 5 2 24))))`;;
let HOLDS_FOUND_VAL_FORM = prove
 (`!D (E:A->A->bool) v.
      model D E ZF_AX /\ valuation D v
      ==> (holds D E v found_val_form <=>
           ?z20 z21 z24. z20 IN D /\ z21 IN D /\ z24 IN D /\
             ebv_in D E (v 2) (v 5) (v 1) (v 6) z20 /\
             ecompl D E (v 2) (v 5) z20 z21 /\
             ebimp D E (v 2) (v 5) (v 7) z21 z24 /\
             ~etop D E (v 2) (v 5) z24)`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[found_val_form] THEN
  SUBGOAL_THEN
   `!z20 z21 z24:A. z20 IN D /\ z21 IN D /\ z24 IN D
      ==> (holds D E
             ((24 |-> z24) ((21 |-> z21) ((20 |-> z20) (v:num->A))))
             (ebv_in_form 20 1 6 5 && bcompl_form 5 2 20 21 &&
              bimp_form 5 2 7 21 24 && Not(btop_form 5 2 24)) <=>
           ebv_in D E (v 2) (v 5) (v 1) (v 6) z20 /\
           ecompl D E (v 2) (v 5) z20 z21 /\
           ebimp D E (v 2) (v 5) (v 7) z21 z24 /\
           ~etop D E (v 2) (v 5) z24)`
  (LABEL_TAC "blk") THENL
   [REPEAT GEN_TAC THEN STRIP_TAC THEN
    SUBGOAL_THEN
     `valuation D ((24 |-> z24) ((21 |-> z21) ((20 |-> z20) (v:num->A))))`
    ASSUME_TAC THENL [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
    ASM_SIMP_TAC[HOLDS_AND; HOLDS_NOT; HOLDS_EBV_IN_FORM; HOLDS_BCOMPL_FORM;
                 HOLDS_BIMP_FORM; HOLDS_BTOP_FORM] THEN
    ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER; ARITH_EQ]; ALL_TAC] THEN
  REWRITE_TAC[HOLDS_EX] THEN EQ_TAC THENL
   [INTRO_TAC "@z20. z20D @z21. z21D @z24. z24D h" THEN
    MAP_EVERY EXISTS_TAC [`z20:A`;`z21:A`;`z24:A`] THEN ASM_REWRITE_TAC[] THEN
    USE_THEN "blk"(fun b -> MP_TAC(SPECL [`z20:A`;`z21:A`;`z24:A`] b)) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(SUBST1_TAC o SYM) THEN ASM_REWRITE_TAC[];
    DISCH_THEN(X_CHOOSE_THEN `z20:A` (X_CHOOSE_THEN `z21:A`
      (X_CHOOSE_THEN `z24:A` STRIP_ASSUME_TAC))) THEN
    EXISTS_TAC `z20:A` THEN ASM_REWRITE_TAC[] THEN
    EXISTS_TAC `z21:A` THEN ASM_REWRITE_TAC[] THEN
    EXISTS_TAC `z24:A` THEN ASM_REWRITE_TAC[] THEN
    USE_THEN "blk"(fun b -> MP_TAC(SPECL [`z20:A`;`z21:A`;`z24:A`] b)) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN SUBST1_TAC THEN ASM_REWRITE_TAC[]]);;
let found_bad_form = new_definition
  `found_bad_form =
     ?? 1 (instage_bn_form && bname_form 1 && found_val_form)`;;
let HOLDS_FOUND_BAD_FORM = prove
 (`!D (E:A->A->bool) v.
      model D E ZF_AX /\ valuation D v
      ==> (holds D E v found_bad_form <=>
           ?a. a IN D /\ (?y. y IN D /\ ebnstage D E (v 2) (v 0) y /\ E a y) /\
               bname D E (v 2) a /\
               (?z20 z21 z24. z20 IN D /\ z21 IN D /\ z24 IN D /\
                  ebv_in D E (v 2) (v 5) a (v 6) z20 /\
                  ecompl D E (v 2) (v 5) z20 z21 /\
                  ebimp D E (v 2) (v 5) (v 7) z21 z24 /\
                  ~etop D E (v 2) (v 5) z24))`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[found_bad_form] THEN
  REWRITE_TAC[HOLDS_EX] THEN
  MATCH_MP_TAC EXISTS_AND_CONG THEN
  X_GEN_TAC `a:A` THEN DISCH_TAC THEN
  SUBGOAL_THEN `valuation D ((1 |-> (a:A)) (v:num->A))` ASSUME_TAC THENL
   [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
  REWRITE_TAC[HOLDS_AND] THEN
  MATCH_MP_TAC(TAUT
    `(a <=> a') /\ (b <=> b') /\ (c <=> c')
     ==> (a /\ b /\ c <=> a' /\ b' /\ c')`) THEN
  REPEAT CONJ_TAC THENL
   [MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`(1 |-> (a:A)) (v:num->A)`]
      HOLDS_INSTAGE_BN_FORM) THEN ASM_REWRITE_TAC[] THEN
    DISCH_THEN SUBST1_TAC THEN
    ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER; ARITH_EQ];
    MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`(1 |-> (a:A)) (v:num->A)`;`1`]
      HOLDS_BNAME_FORM) THEN ANTS_TAC THENL
    [ASM_REWRITE_TAC[] THEN ARITH_TAC; ALL_TAC] THEN
    DISCH_THEN SUBST1_TAC THEN
    ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER; ARITH_EQ];
    MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`(1 |-> (a:A)) (v:num->A)`]
      HOLDS_FOUND_VAL_FORM) THEN ASM_REWRITE_TAC[] THEN
    DISCH_THEN SUBST1_TAC THEN
    ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER; ARITH_EQ]]);;

(* --- found_cform + FOUND_BADEQ: "aa has no epsilon-minimal element",    *)
(*     and the Boolean criterion for a name failing epsilon-minimality. --- *)
let found_cform = new_definition
  `found_cform = !! 1 (Not((1 %% 0) && (!!- 2 1 (Not(2 %% 0)))))`;;
let FOUND_BADEQ = prove
 (`!D (E:A->A->bool) B leq c aa b vv.
      model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
      c IN D /\ E c B /\ aa IN D /\ b IN D /\
      bname D E B aa /\ bname D E B b /\
      valuation D vv /\ (!i. bname D E B (vv i)) /\ vv 0 = aa
      ==> (~(erel D E leq c (bvalf D E B leq ((1 |-> b) vv) (Not(1 %% 0)))) <=>
           (?z20 z21 z24. z20 IN D /\ z21 IN D /\ z24 IN D /\
              ebv_in D E B leq b aa z20 /\
              ecompl D E B leq z20 z21 /\
              ebimp D E B leq c z21 z24 /\
              ~etop D E B leq z24))`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `ebalg D (E:A->A->bool) B leq` ASSUME_TAC THENL
   [ASM_MESON_TAC[ECBA_IMP_BALG]; ALL_TAC] THEN
  SUBGOAL_THEN `valuation D ((1 |-> (b:A)) vv) /\
                (!i. bname D (E:A->A->bool) B (((1 |-> (b:A)) vv) i))`
  STRIP_ASSUME_TAC THENL
   [CONJ_TAC THENL
     [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[];
      MATCH_MP_TAC BNAMEVAL_VALMOD THEN ASM_REWRITE_TAC[]]; ALL_TAC] THEN
  SUBGOAL_THEN `ebv_in D (E:A->A->bool) B leq b aa
                  (bvalf D E B leq ((1 |-> (b:A)) vv) (1 %% 0))`
  ASSUME_TAC THENL
   [MP_TAC(ISPECL
           [`1`;`0`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
            `(1 |-> (b:A)) vv`]
           BVALF_MEM) THEN ASM_REWRITE_TAC[] THEN
    ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER; ARITH_EQ]; ALL_TAC] THEN
  SUBGOAL_THEN
    `(bvalf D (E:A->A->bool) B leq ((1 |-> (b:A)) vv) (1 %% 0)) IN D /\
     (E:A->A->bool) (bvalf D E B leq ((1 |-> (b:A)) vv) (1 %% 0)) B`
  STRIP_ASSUME_TAC THENL
   [CONJ_TAC THENL
     [MP_TAC(ISPECL
             [`(1 %% 0)`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
              `(1 |-> (b:A)) vv`]
             BVALF_SPEC) THEN ASM_REWRITE_TAC[] THEN
           DISCH_THEN(ACCEPT_TAC o CONJUNCT1);
           MATCH_MP_TAC(ISPECL
                        [`(1 %% 0)`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
                         `(1 |-> (b:A)) vv`]
                        BVALF_IN_B) THEN ASM_REWRITE_TAC[]]; ALL_TAC] THEN
  SUBGOAL_THEN `ecompl D (E:A->A->bool) B leq
                  (bvalf D E B leq ((1 |-> (b:A)) vv) (1 %% 0))
                  (bvalf D E B leq ((1 |-> (b:A)) vv) (Not(1 %% 0)))`
  ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`(1 %% 0)`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
                  `(1 |-> (b:A)) vv`]
                 BVALF_NOT) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN
    `(bvalf D (E:A->A->bool) B leq ((1 |-> (b:A)) vv) (Not(1 %% 0))) IN D /\
     (E:A->A->bool) (bvalf D E B leq ((1 |-> (b:A)) vv) (Not(1 %% 0))) B`
  STRIP_ASSUME_TAC THENL
   [CONJ_TAC THENL
     [MP_TAC(ISPECL
             [`(Not(1 %% 0))`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
              `(1 |-> (b:A)) vv`]
             BVALF_SPEC) THEN ASM_REWRITE_TAC[] THEN
                 DISCH_THEN(ACCEPT_TAC o CONJUNCT1);
                 MATCH_MP_TAC(ISPECL
                              [`(Not(1 %% 0))`;`D:A->bool`;`E:A->A->bool`;
                               `B:A`;`leq:A`;`(1 |-> (b:A)) vv`]
                              BVALF_IN_B) THEN ASM_REWRITE_TAC[]];
     ALL_TAC] THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`c:A`;
    `bvalf D E B leq ((1 |-> (b:A)) vv) (Not(1 %% 0))`] EBIMP_EXISTS) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `z24:A`) THEN
  SUBGOAL_THEN `(z24:A) IN D /\ (E:A->A->bool) z24 B` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[EBIMP_IN]; ALL_TAC] THEN
  SUBGOAL_THEN
   `etop D (E:A->A->bool) B leq z24 <=>
    erel D E leq c (bvalf D E B leq ((1 |-> (b:A)) vv) (Not(1 %% 0)))`
  ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`c:A`;
      `bvalf D E B leq ((1 |-> (b:A)) vv) (Not(1 %% 0))`;`z24:A`]
      EBIMP_TOP) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  EQ_TAC THENL
   [DISCH_TAC THEN
    MAP_EVERY EXISTS_TAC
     [`bvalf D E B leq ((1 |-> (b:A)) vv) (1 %% 0)`;
      `bvalf D E B leq ((1 |-> (b:A)) vv) (Not(1 %% 0))`;`z24:A`] THEN
    ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[];
    DISCH_THEN(X_CHOOSE_THEN `z20:A` (X_CHOOSE_THEN `z21:A`
      (X_CHOOSE_THEN `z24':A` STRIP_ASSUME_TAC))) THEN
    SUBGOAL_THEN `z20:A = bvalf D E B leq ((1 |-> (b:A)) vv) (1 %% 0)`
    SUBST_ALL_TAC THENL
     [MATCH_MP_TAC(ISPECL
                   [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`b:A`;
                    `aa:A`;`z20:A`;
                    `bvalf D E B leq ((1 |-> (b:A)) vv) (1 %% 0)`]
                     EBV_IN_UNIQUE) THEN
      ASM_REWRITE_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN `z21:A = bvalf D E B leq ((1 |-> (b:A)) vv) (Not(1 %% 0))`
    SUBST_ALL_TAC THENL
     [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
        `bvalf D E B leq ((1 |-> (b:A)) vv) (1 %% 0)`;`z21:A`;
        `bvalf D E B leq ((1 |-> (b:A)) vv) (Not(1 %% 0))`] ECOMPL_UNIQUE) THEN
      ASM_REWRITE_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN
     `etop D (E:A->A->bool) B leq z24' <=>
      erel D E leq c (bvalf D E B leq ((1 |-> (b:A)) vv) (Not(1 %% 0)))`
    ASSUME_TAC THENL
     [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`c:A`;
        `bvalf D E B leq ((1 |-> (b:A)) vv) (Not(1 %% 0))`;`z24':A`]
                       EBIMP_TOP) THEN
      ASM_REWRITE_TAC[]; ALL_TAC] THEN
    ASM_MESON_TAC[]]);;

(* --- FOUND_KEY: epsilon-induction on bnrank  ==>  c <= [[u NOTIN aa]]. --- *)
let FOUND_KEY = prove
 (`!D (E:A->A->bool) B leq c aa vv.
      model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
      c IN D /\ E c B /\ aa IN D /\ bname D E B aa /\
      valuation D vv /\ (!i. bname D E B (vv i)) /\ vv 0 = aa /\
      c = bvalf D E B leq vv found_cform
      ==> !u. u IN D /\ bname D E B u
              ==> erel D E leq c
                (bvalf D E B leq ((1 |-> u) vv) (Not(1 %% 0)))`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  UNDISCH_TAC `(c:A) = bvalf D (E:A->A->bool) B leq vv found_cform` THEN
  DISCH_THEN(ASSUME_TAC o SYM) THEN
  ABBREV_TAC
    `wv = (7 |-> (c:A))
     ((6 |-> (aa:A)) ((5 |-> (leq:A)) ((2 |-> (B:A)) vv)))` THEN
  SUBGOAL_THEN
    `valuation D (wv:num->A) /\ (wv:num->A) 2 = B /\ (wv:num->A) 5 = leq /\
     (wv:num->A) 6 = aa /\ (wv:num->A) 7 = c`
  STRIP_ASSUME_TAC THENL
   [EXPAND_TAC "wv" THEN REPEAT CONJ_TAC THENL
     [ASM_MESON_TAC[VALUATION_VALMOD];
      REWRITE_TAC[VALMOD; ARITH_EQ]; REWRITE_TAC[VALMOD; ARITH_EQ];
      REWRITE_TAC[VALMOD; ARITH_EQ]; REWRITE_TAC[VALMOD; ARITH_EQ]];
     ALL_TAC] THEN
  X_GEN_TAC `u:A` THEN STRIP_TAC THEN REFUTE_THEN ASSUME_TAC THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`u:A`] EBNRANK_EXISTS) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_THEN `ru:A` STRIP_ASSUME_TAC) THEN
  SUBGOAL_THEN `(ru:A) IN D /\ eordinal D (E:A->A->bool) ru`
    STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[EBNRANK_IN; EBNRANK_ORDINAL]; ALL_TAC] THEN
  SUBGOAL_THEN `holds D (E:A->A->bool) ((0 |-> ru) (wv:num->A)) found_bad_form`
    ASSUME_TAC THENL
   [MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`(0 |-> ru) (wv:num->A)`]
           HOLDS_FOUND_BAD_FORM) THEN
    ANTS_TAC THENL
    [ASM_REWRITE_TAC[] THEN MATCH_MP_TAC VALUATION_VALMOD THEN
     ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN SUBST1_TAC THEN
    ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER; ARITH_EQ] THEN
    EXISTS_TAC `u:A` THEN ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
     [UNDISCH_TAC `ebnrank D (E:A->A->bool) B u ru` THEN
      REWRITE_TAC[ebnrank] THEN MESON_TAC[];
      MP_TAC(ISPECL
             [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`c:A`;`aa:A`;`u:A`;
              `vv:num->A`] FOUND_BADEQ) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[GSYM th]) THEN ASM_REWRITE_TAC[]];
     ALL_TAC] THEN
  MP_TAC(ISPECL
         [`D:A->bool`;`E:A->A->bool`;`found_bad_form`;`wv:num->A`;`ru:A`]
         EORDINAL_LEAST) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `d:A` (CONJUNCTS_THEN2 ASSUME_TAC (CONJUNCTS_THEN2
    ASSUME_TAC (CONJUNCTS_THEN2 (LABEL_TAC "badd") (LABEL_TAC "min"))))) THEN
  SUBGOAL_THEN
   `?a0. a0 IN D /\
    (?y. y IN D /\ ebnstage D (E:A->A->bool) B d y /\ E a0 y) /\
         bname D E B a0 /\
         (?z20 z21 z24. z20 IN D /\ z21 IN D /\ z24 IN D /\
            ebv_in D E B leq a0 aa z20 /\ ecompl D E B leq z20 z21 /\
            ebimp D E B leq c z21 z24 /\ ~etop D E B leq z24)`
  STRIP_ASSUME_TAC THENL
   [MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`(0 |-> d) (wv:num->A)`]
           HOLDS_FOUND_BAD_FORM) THEN
    ANTS_TAC THENL
    [ASM_REWRITE_TAC[] THEN MATCH_MP_TAC VALUATION_VALMOD THEN
     ASM_REWRITE_TAC[]; ALL_TAC] THEN
    ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER; ARITH_EQ] THEN
    DISCH_THEN(fun th -> USE_THEN "badd" (ACCEPT_TAC o EQ_MP th));
    ALL_TAC] THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`a0:A`] EBNRANK_EXISTS) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `ra0:A` STRIP_ASSUME_TAC) THEN
  SUBGOAL_THEN `(ra0:A) IN D /\ eordinal D (E:A->A->bool) ra0`
    STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[EBNRANK_IN; EBNRANK_ORDINAL]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) (ra0:A) d \/ ra0 = d` ASSUME_TAC THENL
   [SUBGOAL_THEN `~((E:A->A->bool) (d:A) ra0)` ASSUME_TAC THENL
     [DISCH_TAC THEN UNDISCH_TAC `ebnrank D (E:A->A->bool) B a0 ra0` THEN
      REWRITE_TAC[ebnrank] THEN
      DISCH_THEN(MP_TAC o SPEC `d:A` o CONJUNCT2 o CONJUNCT2) THEN
      ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[]; ALL_TAC] THEN
    MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`ra0:A`;`d:A`]
           EORDINAL_TRICHOTOMY) THEN
    ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN
   `erel D (E:A->A->bool) leq c
    (bvalf D E B leq ((1 |-> a0) vv) (Not(1 %% 0 && !!- 2 1 (Not(2 %% 0)))))`
  ASSUME_TAC THENL
   [SUBST1_TAC(SYM(ASSUME
                   `bvalf D (E:A->A->bool) B leq vv found_cform = c`)) THEN
    REWRITE_TAC[found_cform] THEN
    MATCH_MP_TAC(ISPECL [`1`; `Not(1 %% 0 && !!- 2 1 (Not(2 %% 0)))`;
      `D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`vv:num->A`;`a0:A`]
             BVALF_ALL_LB) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
