    ALL_TAC] THEN
  SUBGOAL_THEN
    `erel D (E:A->A->bool) leq c
     (bvalf D E B leq ((1 |-> a0) vv) (Not(1 %% 0)))` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`c:A`;`aa:A`;`a0:A`;
                  `vv:num->A`] FOUND_STEP) THEN
    ASM_REWRITE_TAC[] THEN
    X_GEN_TAC `yy:A` THEN STRIP_TAC THEN REFUTE_THEN ASSUME_TAC THEN
    UNDISCH_TAC `eindom D (E:A->A->bool) a0 yy` THEN REWRITE_TAC[eindom] THEN
    DISCH_THEN(X_CHOOSE_THEN `qy:A` STRIP_ASSUME_TAC) THEN
    MP_TAC(ISPECL
           [`D:A->bool`;`E:A->A->bool`;`B:A`;`a0:A`;`yy:A`;`qy:A`;`ra0:A`]
           EBNRANK_APPLY_LT) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(X_CHOOSE_THEN `ry:A` STRIP_ASSUME_TAC o CONJUNCT2) THEN
    SUBGOAL_THEN `(ry:A) IN D /\ eordinal D (E:A->A->bool) ry`
      STRIP_ASSUME_TAC THENL
      [ASM_MESON_TAC[EBNRANK_IN; EBNRANK_ORDINAL]; ALL_TAC] THEN
