       [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`d:A`;`ry:A`;`ra0:A`]
                     EORDINAL_TRANS_E) THEN
        ASM_REWRITE_TAC[];
        ASM_MESON_TAC[]]; ALL_TAC] THEN
