              (CONJ (ASSUME `(ry:A) IN D`)
               (ASSUME `(E:A->A->bool) ry d`)))) THEN
    REWRITE_TAC[ASSUME
                `holds D (E:A->A->bool) ((0 |-> ry) (wv:num->A))
                 found_bad_form`]; ALL_TAC] THEN
  UNDISCH_TAC
    `~(erel D (E:A->A->bool) leq c
       (bvalf D E B leq ((1 |-> a0) vv) (Not(1 %% 0))))` THEN
