(* --- BVALF_FOUNDATION: assembly  [[ foundation_ax ]]_v = top. --- *)
let BVALF_FOUNDATION = prove
 (`!D (E:A->A->bool) B leq v.
      model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
      valuation D v /\ (!i. bname D E B (v i))
      ==> etop D E B leq (bvalf D E B leq v foundation_ax)`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `ebalg D (E:A->A->bool) B leq` ASSUME_TAC THENL
   [ASM_MESON_TAC[ECBA_IMP_BALG]; ALL_TAC] THEN
  REWRITE_TAC[foundation_ax; Existsmem_DEF; Exists_DEF; GSYM found_cform] THEN
  MP_TAC(ISPECL [`0`; `Not(!! 1 (Not(1 %% 0))) --> Not found_cform`;
    `D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`v:num->A`] BVALF_ALL_TOP) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN SUBST1_TAC THEN
  X_GEN_TAC `aa:A` THEN STRIP_TAC THEN
  ABBREV_TAC `w = (0 |-> (aa:A)) v` THEN
  SUBGOAL_THEN
    `valuation D (w:num->A) /\ (!i. bname D (E:A->A->bool) B ((w:num->A) i)) /\
     (w:num->A) 0 = aa`
  STRIP_ASSUME_TAC THENL
   [EXPAND_TAC "w" THEN REPEAT CONJ_TAC THENL
     [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[];
      MATCH_MP_TAC BNAMEVAL_VALMOD THEN ASM_REWRITE_TAC[];
      ASM_SIMP_TAC[VALMOD_BASIC]]; ALL_TAC] THEN
  MP_TAC(ISPECL [`Not(!! 1 (Not(1 %% 0)))`; `Not found_cform`;
    `D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`w:num->A`] BVALF_IMP_TOP) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN SUBST1_TAC THEN
  SUBGOAL_THEN `(bvalf D (E:A->A->bool) B leq (w:num->A) found_cform) IN D`
  ASSUME_TAC THENL
   [MP_TAC(ISPECL[`found_cform`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
                  `w:num->A`] BVALF_SPEC) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(ACCEPT_TAC o CONJUNCT1); ALL_TAC] THEN
  SUBGOAL_THEN `E (bvalf D (E:A->A->bool) B leq (w:num->A) found_cform) B`
  ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL[`found_cform`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
                        `w:num->A`] BVALF_IN_B) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN
    `(bvalf D (E:A->A->bool) B leq (w:num->A) (!! 1 (Not(1 %% 0)))) IN D`
  ASSUME_TAC THENL
   [MP_TAC(ISPECL[`!! 1 (Not(1 %% 0))`;`D:A->bool`;`E:A->A->bool`;`B:A`;
                  `leq:A`;`w:num->A`] BVALF_SPEC) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(ACCEPT_TAC o CONJUNCT1); ALL_TAC] THEN
  SUBGOAL_THEN
    `E (bvalf D (E:A->A->bool) B leq (w:num->A) (!! 1 (Not(1 %% 0)))) B`
  ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL[`!! 1 (Not(1 %% 0))`;`D:A->bool`;`E:A->A->bool`;`B:A`;
                        `leq:A`;`w:num->A`] BVALF_IN_B) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `ecompl D (E:A->A->bool) B leq
      (bvalf D E B leq (w:num->A) found_cform)
      (bvalf D E B leq (w:num->A) (Not found_cform))`
  ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL[`found_cform`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
                        `w:num->A`] BVALF_NOT) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `ecompl D (E:A->A->bool) B leq
      (bvalf D E B leq (w:num->A) (!! 1 (Not(1 %% 0))))
      (bvalf D E B leq (w:num->A) (Not(!! 1 (Not(1 %% 0)))))`
  ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL[`!! 1 (Not(1 %% 0))`;`D:A->bool`;`E:A->A->bool`;`B:A`;
                        `leq:A`;`w:num->A`] BVALF_NOT) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq
      (bvalf D E B leq (w:num->A) found_cform)
      (bvalf D E B leq (w:num->A) (!! 1 (Not(1 %% 0))))`
  ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL [`1`; `Not(1 %% 0)`;
      `D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`w:num->A`;
      `bvalf D E B leq (w:num->A) found_cform`] BVALF_ALL_GLB) THEN
    ASM_REWRITE_TAC[] THEN
    X_GEN_TAC `u:A` THEN STRIP_TAC THEN
    MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
      `bvalf D E B leq (w:num->A) found_cform`;`aa:A`;`w:num->A`]
      FOUND_KEY) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(MP_TAC o SPEC `u:A`) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
    `bvalf D E B leq (w:num->A) found_cform`;
    `bvalf D E B leq (w:num->A) (!! 1 (Not(1 %% 0)))`;
    `bvalf D E B leq (w:num->A) (Not found_cform)`;
    `bvalf D E B leq (w:num->A) (Not(!! 1 (Not(1 %% 0))))`]
      ECOMPL_ANTITONE) THEN
  ASM_REWRITE_TAC[]);;

(* ===================================================================== *)
(* F5 POWER axiom: the SUBSET Boolean value  esubval.                    *)
(*   [[ f SUBSET x ]] = GLB over v in dom f of  ( f(v) IMP [[ v in x ]] ).*)
(* Structural twin of the UNION value euuval (@euucomb..euuval), with the *)
(* combiner  f(v) IMP [[v in x]]  in place of  x(w) MEET w(s):  eapply on *)
(* f, ebv_in for the membership value, ebimp (not emeet) to combine, and  *)
(* the GLB (ECBA_INF / eglb) in place of the SUP.  The GLB ranges over    *)
(* dom f only -- the standard collapse of the bounded-forall subset value *)
(* to the candidate's own domain (proved via EBV_IN_MEMBER + C1 in P1b).  *)
(* esubval is the P(f) slot of the power name.  Object form esubcomb_form *)
(* carries the carrier B at the FIXED slot 2 (forced by ebv_in_form).     *)
(* ===================================================================== *)

(* c is a subset-combiner  f(v) IMP [[v in x]]  for some v in dom f.        *)
(* x = container B-name, f = subset-candidate function name.                *)
let esubcomb = new_definition
  `esubcomb D (E:A->A->bool) B leq x f c <=>
        ?v qv z2.
            v IN D /\ qv IN D /\ z2 IN D /\
            eapply D E f v qv /\ ebv_in D E B leq v x z2 /\
            ebimp D E B leq qv z2 c`;;

let ESUBCOMB_IN = prove
 (`!D (E:A->A->bool) B leq x f c.
        esubcomb D E B leq x f c ==> c IN D /\ E c B`,
  REWRITE_TAC[esubcomb] THEN MESON_TAC[EBIMP_IN]);;

(* the image set  {c IN D : esubcomb c}  (a subset of B).                   *)
let esubcombset = new_definition
  `esubcombset D (E:A->A->bool) B leq x f S <=>
        S IN D /\
        !c. c IN D ==> (E c S <=> esubcomb D E B leq x f c)`;;

let ESUBCOMBSET_SUBSET = prove
 (`!D (E:A->A->bool) B leq x f S.
        esubcombset D E B leq x f S ==> esubset D E S B`,
  REWRITE_TAC[esubcombset; esubset] THEN MESON_TAC[ESUBCOMB_IN]);;

let ESUBCOMBSET_UNIQUE = prove
 (`!D (E:A->A->bool) B leq x f S S'.
        model D E ZF_AX /\
        esubcombset D E B leq x f S /\ esubcombset D E B leq x f S'
        ==> S = S'`,
  REWRITE_TAC[esubcombset] THEN REPEAT STRIP_TAC THEN
  FIRST_ASSUM(MATCH_MP_TAC o MATCH_MP ZF_EXTENSIONALITY) THEN
  ASM_SIMP_TAC[]);;

(* the subset-value  [[f SUB x]] = GLB over v in dom f of  f(v) IMP [[v in *)
(* x]]. *)
let esubval = new_definition
  `esubval D (E:A->A->bool) B leq x f z <=>
        ?S. esubcombset D E B leq x f S /\ eglb D E B leq S z`;;

let ESUBVAL_IN = prove
 (`!D (E:A->A->bool) B leq x f z.
        esubval D E B leq x f z ==> z IN D /\ E z B`,
  REWRITE_TAC[esubval; eglb; elbound] THEN MESON_TAC[]);;

let ESUBVAL_UNIQUE = prove
 (`!D (E:A->A->bool) B leq x f z z'.
        model D E ZF_AX /\ ecba D E B leq /\
        esubval D E B leq x f z /\ esubval D E B leq x f z'
        ==> z = z'`,
  REWRITE_TAC[esubval] THEN REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `S':A = S` SUBST_ALL_TAC THENL
   [ASM_MESON_TAC[ESUBCOMBSET_UNIQUE]; ALL_TAC] THEN
  ASM_MESON_TAC[EGLB_UNIQUE; ECBA_IMP_PORDER]);;

(* -- esubcomb as an OBJECT formula, with HOLDS characterisation --------- *)
(* Params: ic (value c), iff (function name f), ix (container x),          *)
(* ileq (order). Carrier B is the FIXED slot 2 (forced by ebv_in_form).    *)
(* Fresh bound vars v=MM+1, qv=MM+2, z2=MM+3, MM = 4-way MAX incl slot 2.   *)
let esubcomb_form = new_definition
  `esubcomb_form ic iff ix ileq =
     ?? (MAX (MAX (MAX ic iff) (MAX ix ileq)) 2 + 1)
       (?? (MAX (MAX (MAX ic iff) (MAX ix ileq)) 2 + 2)
         (?? (MAX (MAX (MAX ic iff) (MAX ix ileq)) 2 + 3)
           (apply_form iff
              (MAX (MAX (MAX ic iff) (MAX ix ileq)) 2 + 1)
              (MAX (MAX (MAX ic iff) (MAX ix ileq)) 2 + 2) &&
            ebv_in_form
              (MAX (MAX (MAX ic iff) (MAX ix ileq)) 2 + 3)
              (MAX (MAX (MAX ic iff) (MAX ix ileq)) 2 + 1)
              ix ileq &&
            bimp_form ileq 2
              (MAX (MAX (MAX ic iff) (MAX ix ileq)) 2 + 2)
              (MAX (MAX (MAX ic iff) (MAX ix ileq)) 2 + 3)
              ic)))`;;

let HOLDS_ESUBCOMB_FORM = prove
 (`!D (E:A->A->bool) v ic iff ix ileq.
        model D E ZF_AX /\ valuation D v
        ==> (holds D E v (esubcomb_form ic iff ix ileq) <=>
             esubcomb D E (v 2) (v ileq) (v ix) (v iff) (v ic))`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `!x. (v:num->A) x IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[valuation]; ALL_TAC] THEN
  REWRITE_TAC[esubcomb_form] THEN
  ABBREV_TAC `MM = MAX (MAX (MAX ic iff) (MAX ix ileq)) 2` THEN
  SUBGOAL_THEN
   `~(ic = MM + 1) /\ ~(ic = MM + 2) /\ ~(ic = MM + 3) /\
    ~(iff = MM + 1) /\ ~(iff = MM + 2) /\ ~(iff = MM + 3) /\
    ~(ix = MM + 1) /\ ~(ix = MM + 2) /\ ~(ix = MM + 3) /\
    ~(ileq = MM + 1) /\ ~(ileq = MM + 2) /\ ~(ileq = MM + 3) /\
    ~(2 = MM + 1) /\ ~(2 = MM + 2) /\ ~(2 = MM + 3) /\
    ~(MM + 1 = MM + 2) /\ ~(MM + 1 = MM + 3) /\ ~(MM + 2 = MM + 3)`
  STRIP_ASSUME_TAC THENL
   [EXPAND_TAC "MM" THEN ARITH_TAC; ALL_TAC] THEN
  SUBGOAL_THEN
   `!a b cc:A. a IN D /\ b IN D /\ cc IN D
      ==> (holds D E
             (((MM + 3) |-> cc) (((MM + 2) |-> b) (((MM + 1) |-> a) v)))
             (apply_form iff (MM + 1) (MM + 2) &&
              ebv_in_form (MM + 3) (MM + 1) ix ileq &&
              bimp_form ileq 2 (MM + 2) (MM + 3) ic) <=>
           eapply D E (v iff) a b /\
           ebv_in D E (v 2) (v ileq) a (v ix) cc /\
           ebimp D E (v 2) (v ileq) b cc (v ic))`
  (LABEL_TAC "body") THENL
   [REPEAT STRIP_TAC THEN
    SUBGOAL_THEN
     `valuation D
        (((MM + 3) |-> (cc:A)) (((MM + 2) |-> b) (((MM + 1) |-> a) v)))`
    ASSUME_TAC THENL [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
    REWRITE_TAC[HOLDS_AND] THEN
    ASM_SIMP_TAC[HOLDS_APPLY_FORM; HOLDS_EBV_IN_FORM; HOLDS_BIMP_FORM] THEN
    ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER];
    ALL_TAC] THEN
  REWRITE_TAC[HOLDS_EX] THEN
  REWRITE_TAC[esubcomb] THEN
  REMOVE_THEN "body" (fun bth ->
    POP_ASSUM_LIST(K ALL_TAC) THEN
    EQ_TAC THENL
     [INTRO_TAC "@a. aD @b. bD @cc. ccD h" THEN
      MAP_EVERY EXISTS_TAC [`a:A`; `b:A`; `cc:A`] THEN
      ASM_MESON_TAC[bth];
      DISCH_THEN(X_CHOOSE_THEN `vv:A` (X_CHOOSE_THEN `qv:A`
        (X_CHOOSE_THEN `z2:A` STRIP_ASSUME_TAC))) THEN
      EXISTS_TAC `vv:A` THEN ASM_REWRITE_TAC[] THEN
      EXISTS_TAC `qv:A` THEN ASM_REWRITE_TAC[] THEN
      EXISTS_TAC `z2:A` THEN ASM_REWRITE_TAC[] THEN
      ASM_MESON_TAC[bth]]));;

let ESUBCOMBSET_EXISTS = prove
 (`!D (E:A->A->bool) B leq x f.
        model D E ZF_AX /\
        B IN D /\ leq IN D /\ x IN D /\ f IN D
        ==> ?S. esubcombset D E B leq x f S`,
  REPEAT STRIP_TAC THEN
  FIRST_ASSUM(X_CHOOSE_TAC `val0:num->A` o MATCH_MP VALUATION_EXISTS o
              MATCH_MP MODEL_NONEMPTY) THEN
  ABBREV_TAC
   `val = (2 |-> (B:A))
          ((3 |-> (f:A)) ((4 |-> (x:A)) ((6 |-> (leq:A)) val0)))` THEN
  SUBGOAL_THEN
   `valuation D (val:num->A) /\
    (val:num->A) 2 = B /\ (val:num->A) 3 = f /\
    (val:num->A) 4 = x /\ (val:num->A) 6 = leq`
  STRIP_ASSUME_TAC THENL
   [EXPAND_TAC "val" THEN REPEAT CONJ_TAC THEN
    REWRITE_TAC[VALMOD; ARITH_EQ] THEN ASM_MESON_TAC[VALUATION_VALMOD];
    ALL_TAC] THEN
  MP_TAC(SPECL [`esubcomb_form 1 3 4 6`; `1`; `val:num->A`; `B:A`]
    (MATCH_MP ZF_SEPARATION (ASSUME `model D (E:A->A->bool) ZF_AX`))) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `S:A`
    (CONJUNCTS_THEN2 ASSUME_TAC (LABEL_TAC "sep"))) THEN
  SUBGOAL_THEN
   `!z. z IN D
        ==> (holds D E ((1 |-> (z:A)) val) (esubcomb_form 1 3 4 6) <=>
             esubcomb D E B leq x f z)`
  (LABEL_TAC "phi") THENL
   [X_GEN_TAC `z:A` THEN DISCH_TAC THEN
    SUBGOAL_THEN `valuation D ((1 |-> (z:A)) val)` ASSUME_TAC THENL
     [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
    MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`(1 |-> (z:A)) val`;
                  `1`;`3`;`4`;`6`] HOLDS_ESUBCOMB_FORM) THEN
    ASM_REWRITE_TAC[] THEN DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    REWRITE_TAC[VALMOD; ARITH_EQ] THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!z. z IN D ==> ((E:A->A->bool) z S <=> esubcomb D E B leq x f z)`
  (LABEL_TAC "mem") THENL
   [X_GEN_TAC `z:A` THEN DISCH_TAC THEN
    SUBGOAL_THEN
     `(E:A->A->bool) z S <=>
      E z B /\ holds D E ((1 |-> (z:A)) val) (esubcomb_form 1 3 4 6)`
    SUBST1_TAC THENL [ASM_MESON_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN
     `holds D E ((1 |-> (z:A)) val) (esubcomb_form 1 3 4 6) <=>
      esubcomb D E B leq x f z`
    SUBST1_TAC THENL [ASM_MESON_TAC[]; ALL_TAC] THEN
    ASM_MESON_TAC[ESUBCOMB_IN];
    ALL_TAC] THEN
  EXISTS_TAC `S:A` THEN REWRITE_TAC[esubcombset] THEN CONJ_TAC THENL
   [FIRST_ASSUM ACCEPT_TAC;
    X_GEN_TAC `c:A` THEN DISCH_TAC THEN ASM_MESON_TAC[]]);;

let ESUBVAL_EXISTS = prove
 (`!D (E:A->A->bool) B leq x f.
        model D E ZF_AX /\ ecba D E B leq /\
        B IN D /\ leq IN D /\ x IN D /\ f IN D
        ==> ?z. esubval D E B leq x f z`,
  REPEAT STRIP_TAC THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`x:A`;`f:A`]
    ESUBCOMBSET_EXISTS) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_TAC `S:A`) THEN
  SUBGOAL_THEN `esubset D (E:A->A->bool) S B` ASSUME_TAC THENL
   [ASM_MESON_TAC[ESUBCOMBSET_SUBSET]; ALL_TAC] THEN
  SUBGOAL_THEN `(S:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[esubcombset]; ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`S:A`] ECBA_INF) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_TAC `z:A`) THEN
  EXISTS_TAC `z:A` THEN REWRITE_TAC[esubval] THEN
  EXISTS_TAC `S:A` THEN ASM_REWRITE_TAC[]);;

(* esubval as GREATEST lower bound of the subset-combiner set (glb duals   *)
(* of EUUVAL_UB / EUUVAL_LEAST).  ESUBVAL_LB: the subset value is <= each   *)
(* combiner f(v) IMP [[v in x]]; ESUBVAL_GREATEST: it is the greatest such  *)
(* lower bound.  Packages esubval = GLB_{v in dom f}(f(v) IMP [[v in x]]).  *)
let ESUBVAL_LB = prove
 (`!D (E:A->A->bool) B leq x f z c.
      esubval D E B leq x f z /\ esubcomb D E B leq x f c
      ==> erel D E leq z c`,
  REPEAT GEN_TAC THEN REWRITE_TAC[esubval] THEN STRIP_TAC THEN
  SUBGOAL_THEN `(c:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[ESUBCOMB_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) c S` ASSUME_TAC THENL
   [FIRST_X_ASSUM(MP_TAC o SPEC `c:A` o CONJUNCT2 o
                  REWRITE_RULE[esubcombset]) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`S:A`;`z:A`;`c:A`]
    EGLB_LB) THEN ASM_REWRITE_TAC[]);;

let ESUBVAL_GREATEST = prove
 (`!D (E:A->A->bool) B leq x f z w.
      esubval D E B leq x f z /\ w IN D /\ E w B /\
      (!c. esubcomb D E B leq x f c ==> erel D E leq w c)
      ==> erel D E leq w z`,
  REPEAT GEN_TAC THEN REWRITE_TAC[esubval] THEN STRIP_TAC THEN
  SUBGOAL_THEN `elbound D (E:A->A->bool) B leq S w` ASSUME_TAC THENL
   [REWRITE_TAC[elbound] THEN ASM_REWRITE_TAC[] THEN
    X_GEN_TAC `xx:A` THEN STRIP_TAC THEN
    SUBGOAL_THEN `esubcomb D (E:A->A->bool) B leq x f xx` ASSUME_TAC THENL
     [FIRST_X_ASSUM(MP_TAC o SPEC `xx:A` o CONJUNCT2 o
                    REWRITE_RULE[esubcombset]) THEN
      ASM_REWRITE_TAC[]; ALL_TAC] THEN
    FIRST_X_ASSUM MATCH_MP_TAC THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`S:A`;`z:A`;`w:A`]
    EGLB_GREATEST) THEN ASM_REWRITE_TAC[]);;

(* ===================================================================== *)
(* F5 POWER axiom:  esubval  IS  the subset Boolean value.                *)
(*   esubval D E B leq x f  =  [[ f SUBSET x ]]                           *)
(*                          =  GLB over ALL bnames w of ([[w in f]] IMP   *)
(*                             [[w in x]]).                               *)
(* esubval is defined as the GLB over dom f only (f(v) IMP [[v in x]]).   *)
(* The two GLBs coincide -- the standard domain collapse of the bounded-  *)
(* forall subset value.  This is stated against an abstractly GLB-        *)
(* characterised witness zsub (lower-bound + greatest clauses over all    *)
(* bnames), which P4 instantiates with the bvalf of the subset formula.   *)
(* Twin of the union value-equality lemmas EBV_IN_UNION_LE/_GE.           *)
(* ===================================================================== *)

(* member <= membership, TOTAL-value form:  f(v) <= [[v in f]].            *)
(* If  eapply f v qv  (v maps to qv under f) and  z = [[v in f]], then      *)
(* qv <= z: the membership value dominates each domain contribution.       *)
let EBV_MEMBER_LE_V = prove
 (`!D (E:A->A->bool) B leq f v qv z.
      model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
      f IN D /\ v IN D /\ bname D E B v /\
      qv IN D /\ E qv B /\ z IN D /\
      eapply D E f v qv /\ ebv_in D E B leq v f z
      ==> erel D E leq qv z`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `eporder D (E:A->A->bool) B leq` ASSUME_TAC THENL
   [ASM_MESON_TAC[ECBA_IMP_PORDER]; ALL_TAC] THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`v:A`;`v:A`]
    EBV_EQ_VAL_EXISTS) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `ey:A` STRIP_ASSUME_TAC) THEN
  SUBGOAL_THEN `etop D (E:A->A->bool) B leq ey` ASSUME_TAC THENL
   [MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`v:A`;`ey:A`]
      EBV_EQ_REFL) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `emeet D (E:A->A->bool) B leq qv ey qv` ASSUME_TAC THENL
   [MATCH_MP_TAC EMEET_TOP THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`v:A`;`f:A`;`z:A`;
    `v:A`;`qv:A`;`ey:A`;`qv:A`] EBV_IN_GE_TERM_V) THEN
  ASM_REWRITE_TAC[]);;

(* esubval x f <= ([[w in f]] IMP [[w in x]])  for EVERY bname w.            *)
(* The hard >= direction of the domain-collapse identity  esubval = [[f SUB  *)
(* x]].  Residuate  z <= (zwf IMP zwx)  to  z MEET [[w in f]] <= [[w in x]]; *)
(* bound [[w in f]] <= (z IMP [[w in x]]) by EBV_IN_LE_V, per combiner       *)
(*  f(y) MEET [[w=y]]  using  z <= (f(y) IMP [[y in x]]) (ESUBVAL_LB) + C1   *)
(* congruence [[y in x]] MEET [[w=y]] <= [[w in x]].                         *)
let ESUBVAL_ALLW_LB = prove
 (`!D (E:A->A->bool) B leq x f z w zwf zwx i.
      model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
      x IN D /\ bname D E B x /\ f IN D /\ bname D E B f /\
      esubval D E B leq x f z /\ z IN D /\
      w IN D /\ bname D E B w /\
      zwf IN D /\ zwx IN D /\ i IN D /\
      ebv_in D E B leq w f zwf /\ ebv_in D E B leq w x zwx /\
      ebimp D E B leq zwf zwx i
      ==> erel D E leq z i`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `ebalg D (E:A->A->bool) B leq` ASSUME_TAC THENL
   [ASM_MESON_TAC[ECBA_IMP_BALG]; ALL_TAC] THEN
  SUBGOAL_THEN `eporder D (E:A->A->bool) B leq` ASSUME_TAC THENL
   [ASM_MESON_TAC[EBALG_IMP_PORDER]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) z B` ASSUME_TAC THENL
   [ASM_MESON_TAC[ESUBVAL_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) zwf B` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`w:A`;`f:A`;
      `zwf:A`] EBV_IN_IN_B) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) zwx B` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`w:A`;`x:A`;
      `zwx:A`] EBV_IN_IN_B) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) i B` ASSUME_TAC THENL
   [ASM_MESON_TAC[EBIMP_IN]; ALL_TAC] THEN
  (* zimp = z IMP zwx *)
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`z:A`;`zwx:A`]
    EBIMP_EXISTS) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `zimp:A`) THEN
  SUBGOAL_THEN `(zimp:A) IN D /\ (E:A->A->bool) zimp B` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[EBIMP_IN]; ALL_TAC] THEN
  (* Claim1 :  [[w in f]] = zwf <= zimp = (z IMP zwx)  via EBV_IN_LE_V *)
  SUBGOAL_THEN `erel D (E:A->A->bool) leq zwf zimp` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`w:A`;`f:A`;
      `zwf:A`;`zimp:A`] EBV_IN_LE_V) THEN
    ASM_REWRITE_TAC[] THEN
    MAP_EVERY X_GEN_TAC [`y:A`;`qy:A`;`ey:A`;`c:A`] THEN STRIP_TAC THEN
    SUBGOAL_THEN `eindom D (E:A->A->bool) f y` ASSUME_TAC THENL
     [REWRITE_TAC[eindom] THEN EXISTS_TAC `qy:A` THEN ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    SUBGOAL_THEN `bname D (E:A->A->bool) B y` ASSUME_TAC THENL
     [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`f:A`;`y:A`]
        UNION_DOM_BNAME) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN `(E:A->A->bool) qy B` ASSUME_TAC THENL
     [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`f:A`;`y:A`;`qy:A`]
        BNAME_APPLY_IN_B) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN `(E:A->A->bool) ey B` ASSUME_TAC THENL
     [MATCH_MP_TAC(ISPECL
                   [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`w:A`;`y:A`;
                    `ey:A`] EBV_EQ_IN_B) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN `(E:A->A->bool) c B` ASSUME_TAC THENL
     [MP_TAC(ISPECL
             [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`qy:A`;`ey:A`;`c:A`]
             EMEET_IN) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    (* zyx = [[y in x]] *)
    MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`y:A`;`x:A`]
      EBV_IN_VAL_EXISTS) THEN
    ASM_REWRITE_TAC[] THEN
    DISCH_THEN(X_CHOOSE_THEN `zyx:A` STRIP_ASSUME_TAC) THEN
    (* c0 = qy IMP zyx *)
    MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`qy:A`;`zyx:A`]
      EBIMP_EXISTS) THEN
    ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `c0:A`) THEN
    SUBGOAL_THEN `(c0:A) IN D /\ (E:A->A->bool) c0 B` STRIP_ASSUME_TAC THENL
     [ASM_MESON_TAC[EBIMP_IN]; ALL_TAC] THEN
    SUBGOAL_THEN `esubcomb D (E:A->A->bool) B leq x f c0` ASSUME_TAC THENL
     [REWRITE_TAC[esubcomb] THEN
      MAP_EVERY EXISTS_TAC [`y:A`;`qy:A`;`zyx:A`] THEN ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    SUBGOAL_THEN `erel D (E:A->A->bool) leq z c0` ASSUME_TAC THENL
     [MATCH_MP_TAC(ISPECL
                   [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`x:A`;`f:A`;
                    `z:A`;`c0:A`] ESUBVAL_LB) THEN ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    (* m0 = z MEET qy , m0 <= zyx *)
    MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`z:A`;`qy:A`]
      EBALG_MEET) THEN
    ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `m0:A`) THEN
    SUBGOAL_THEN `(m0:A) IN D /\ (E:A->A->bool) m0 B` STRIP_ASSUME_TAC THENL
     [MP_TAC(ISPECL
             [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`z:A`;`qy:A`;`m0:A`]
             EMEET_IN) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN `erel D (E:A->A->bool) leq m0 zyx` ASSUME_TAC THENL
     [MATCH_MP_TAC(ISPECL
                   [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`z:A`;`qy:A`;
                    `zyx:A`;`c0:A`;`m0:A`] EBIMP_MEET_LE) THEN
      ASM_REWRITE_TAC[]; ALL_TAC] THEN
    (* symmetric equality  ebv_eq y w ey *)
    SUBGOAL_THEN `ebv_eq D (E:A->A->bool) B leq y w ey` ASSUME_TAC THENL
     [MATCH_MP_TAC(ISPECL
                   [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`w:A`;`y:A`;
                    `ey:A`] EBV_EQ_SYM) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    (* cong23 = ey MEET [[y in x]] <= [[w in x]]  (C1 congruence) *)
    MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`ey:A`;`zyx:A`]
      EBALG_MEET) THEN
    ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `cong23:A`) THEN
    SUBGOAL_THEN `(cong23:A) IN D /\ (E:A->A->bool) cong23 B`
      STRIP_ASSUME_TAC THENL
      [MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`ey:A`;`zyx:A`;
        `cong23:A`] EMEET_IN) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN `erel D (E:A->A->bool) leq cong23 zwx` ASSUME_TAC THENL
     [MATCH_MP_TAC(ISPECL
                   [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`y:A`;`w:A`;
                    `x:A`;`ey:A`;`zyx:A`;`zwx:A`;`cong23:A`]
                     EBV_IN_CONG_L) THEN
      ASM_REWRITE_TAC[]; ALL_TAC] THEN
    (* mc = c MEET z <= zwx *)
    MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`c:A`;`z:A`]
      EBALG_MEET) THEN
    ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `mc:A`) THEN
    SUBGOAL_THEN `(mc:A) IN D /\ (E:A->A->bool) mc B` STRIP_ASSUME_TAC THENL
     [MP_TAC(ISPECL
             [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`c:A`;`z:A`;`mc:A`]
             EMEET_IN) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN `erel D (E:A->A->bool) leq c qy /\ erel D E leq c ey`
    STRIP_ASSUME_TAC THENL
     [MP_TAC(ISPECL
             [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`qy:A`;`ey:A`;`c:A`]
             EMEET_LE) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN `erel D (E:A->A->bool) leq mc c /\ erel D E leq mc z`
    STRIP_ASSUME_TAC THENL
     [MP_TAC(ISPECL
             [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`c:A`;`z:A`;`mc:A`]
             EMEET_LE) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN `erel D (E:A->A->bool) leq mc qy` ASSUME_TAC THENL
     [MATCH_MP_TAC(ISPECL
                   [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`mc:A`;`c:A`;
                    `qy:A`] EPORDER_TRANS) THEN ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    SUBGOAL_THEN `erel D (E:A->A->bool) leq mc ey` ASSUME_TAC THENL
     [MATCH_MP_TAC(ISPECL
                   [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`mc:A`;`c:A`;
                    `ey:A`] EPORDER_TRANS) THEN ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    SUBGOAL_THEN `erel D (E:A->A->bool) leq mc m0` ASSUME_TAC THENL
     [MATCH_MP_TAC(ISPECL
                   [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`z:A`;`qy:A`;
                    `m0:A`;`mc:A`] EMEET_GREATEST) THEN ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    SUBGOAL_THEN `erel D (E:A->A->bool) leq mc zyx` ASSUME_TAC THENL
     [MATCH_MP_TAC(ISPECL
                   [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`mc:A`;`m0:A`;
                    `zyx:A`] EPORDER_TRANS) THEN ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    SUBGOAL_THEN `erel D (E:A->A->bool) leq mc cong23` ASSUME_TAC THENL
     [MATCH_MP_TAC(ISPECL
                   [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`ey:A`;`zyx:A`;
                    `cong23:A`;`mc:A`] EMEET_GREATEST) THEN ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    SUBGOAL_THEN `erel D (E:A->A->bool) leq mc zwx` ASSUME_TAC THENL
     [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`mc:A`;
        `cong23:A`;`zwx:A`] EPORDER_TRANS) THEN ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`c:A`;`z:A`;
      `zwx:A`;`zimp:A`;`mc:A`] EBIMP_LE_IMP) THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  (* main:  z <= i  via EBIMP_LE_IMP with m = z MEET zwf <= zwx *)
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`z:A`;`zwf:A`]
    EBALG_MEET) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `m:A`) THEN
  SUBGOAL_THEN `(m:A) IN D /\ (E:A->A->bool) m B` STRIP_ASSUME_TAC THENL
   [MP_TAC(ISPECL
           [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`z:A`;`zwf:A`;`m:A`]
           EMEET_IN) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq m z /\ erel D E leq m zwf`
  STRIP_ASSUME_TAC THENL
   [MP_TAC(ISPECL
           [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`z:A`;`zwf:A`;`m:A`]
           EMEET_LE) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq m zimp` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`m:A`;`zwf:A`;
                  `zimp:A`] EPORDER_TRANS) THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  (* mm = z MEET zimp <= zwx  (modus ponens) *)
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`z:A`;`zimp:A`]
    EBALG_MEET) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `mm:A`) THEN
  SUBGOAL_THEN `(mm:A) IN D /\ (E:A->A->bool) mm B` STRIP_ASSUME_TAC THENL
   [MP_TAC(ISPECL
           [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`z:A`;`zimp:A`;`mm:A`]
           EMEET_IN) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `emeet D (E:A->A->bool) B leq zimp z mm` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`z:A`;`zimp:A`;
                  `mm:A`] EMEET_SYM) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq zimp zimp` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`zimp:A`]
      EPORDER_REFL) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq mm zwx` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`zimp:A`;`z:A`;
                  `zwx:A`;`zimp:A`;`mm:A`] EBIMP_MEET_LE) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq m mm` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`z:A`;`zimp:A`;
                  `mm:A`;`m:A`] EMEET_GREATEST) THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq m zwx` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`m:A`;`mm:A`;
      `zwx:A`] EPORDER_TRANS) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`z:A`;`zwf:A`;
    `zwx:A`;`i:A`;`m:A`] EBIMP_LE_IMP) THEN ASM_REWRITE_TAC[]);;

(* esubval x f = [[ f SUBSET x ]]:  the dom-f GLB equals the all-bnames GLB. *)
(* zsub abstracts [[f SUBSET x]] = GLB over all bnames w of ([[w in f]] IMP  *)
(* [[w in x]]).  <=: ESUBVAL_ALLW_LB shows z lower-bounds every W-combiner,  *)
(* so z <= zsub by zsub's greatest clause.  >=: ESUBVAL_GREATEST reduces to  *)
(* zsub <= (f(v) IMP [[v in x]]) for each v in dom f; take ii = [[v in f]]   *)
(* IMP [[v in x]] (zsub <= ii by zsub's lb clause with w:=v), then ii <=     *)
(* (f(v) IMP [[v in x]]) since f(v) <= [[v in f]] makes IMP antitone.        *)
let ESUBVAL_EQ_SUBSETVAL = prove
 (`!D (E:A->A->bool) B leq x f z zsub.
      model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
      x IN D /\ bname D E B x /\ f IN D /\ bname D E B f /\
      esubval D E B leq x f z /\ z IN D /\
      zsub IN D /\ E zsub B /\
      (!w zwf zwx ii.
          w IN D /\ bname D E B w /\ zwf IN D /\ zwx IN D /\ ii IN D /\
          ebv_in D E B leq w f zwf /\ ebv_in D E B leq w x zwx /\
          ebimp D E B leq zwf zwx ii
          ==> erel D E leq zsub ii) /\
      (!lb. lb IN D /\ E lb B /\
           (!w zwf zwx ii.
               w IN D /\ bname D E B w /\ zwf IN D /\ zwx IN D /\ ii IN D /\
               ebv_in D E B leq w f zwf /\ ebv_in D E B leq w x zwx /\
               ebimp D E B leq zwf zwx ii
               ==> erel D E leq lb ii)
           ==> erel D E leq lb zsub)
      ==> z = zsub`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `ebalg D (E:A->A->bool) B leq` ASSUME_TAC THENL
   [ASM_MESON_TAC[ECBA_IMP_BALG]; ALL_TAC] THEN
  SUBGOAL_THEN `eporder D (E:A->A->bool) B leq` ASSUME_TAC THENL
   [ASM_MESON_TAC[EBALG_IMP_PORDER]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) z B` ASSUME_TAC THENL
   [ASM_MESON_TAC[ESUBVAL_IN]; ALL_TAC] THEN
  MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`z:A`;`zsub:A`]
    EPORDER_ANTISYM) THEN
  ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
   [(* z <= zsub : zsub is greatest lower bound,
    z lower-bounds all W-combiners *)
    FIRST_X_ASSUM MATCH_MP_TAC THEN ASM_REWRITE_TAC[] THEN
    MAP_EVERY X_GEN_TAC [`w:A`;`zwf:A`;`zwx:A`;`ii:A`] THEN STRIP_TAC THEN
    MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`x:A`;`f:A`;
      `z:A`;`w:A`;`zwf:A`;`zwx:A`;`ii:A`] ESUBVAL_ALLW_LB) THEN
    ASM_REWRITE_TAC[];
    (* zsub <= z : ESUBVAL_GREATEST + zsub <= each dom-f combiner *)
    MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`x:A`;`f:A`;
      `z:A`;`zsub:A`] ESUBVAL_GREATEST) THEN
    ASM_REWRITE_TAC[] THEN
    X_GEN_TAC `c:A` THEN DISCH_TAC THEN
    POP_ASSUM(STRIP_ASSUME_TAC o REWRITE_RULE[esubcomb]) THEN
    SUBGOAL_THEN `eindom D (E:A->A->bool) f v` ASSUME_TAC THENL
     [REWRITE_TAC[eindom] THEN EXISTS_TAC `qv:A` THEN ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    SUBGOAL_THEN `bname D (E:A->A->bool) B v` ASSUME_TAC THENL
     [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`f:A`;`v:A`]
        UNION_DOM_BNAME) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN `(E:A->A->bool) qv B` ASSUME_TAC THENL
     [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`f:A`;`v:A`;`qv:A`]
        BNAME_APPLY_IN_B) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN `(E:A->A->bool) z2 B` ASSUME_TAC THENL
     [MATCH_MP_TAC(ISPECL
                   [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`v:A`;`x:A`;
                    `z2:A`] EBV_IN_IN_B) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN `(c:A) IN D /\ (E:A->A->bool) c B` STRIP_ASSUME_TAC THENL
     [ASM_MESON_TAC[EBIMP_IN]; ALL_TAC] THEN
    MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`v:A`;`f:A`]
      EBV_IN_VAL_EXISTS) THEN
    ASM_REWRITE_TAC[] THEN
    DISCH_THEN(X_CHOOSE_THEN `zvf:A` STRIP_ASSUME_TAC) THEN
    SUBGOAL_THEN `erel D (E:A->A->bool) leq qv zvf` ASSUME_TAC THENL
     [MATCH_MP_TAC(ISPECL
                   [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`f:A`;`v:A`;
                    `qv:A`;`zvf:A`] EBV_MEMBER_LE_V) THEN ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`zvf:A`;`z2:A`]
      EBIMP_EXISTS) THEN
    ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `ii:A`) THEN
    SUBGOAL_THEN `(ii:A) IN D /\ (E:A->A->bool) ii B` STRIP_ASSUME_TAC THENL
     [ASM_MESON_TAC[EBIMP_IN]; ALL_TAC] THEN
    SUBGOAL_THEN `erel D (E:A->A->bool) leq zsub ii` ASSUME_TAC THENL
     [FIRST_X_ASSUM MATCH_MP_TAC THEN
      MAP_EVERY EXISTS_TAC [`v:A`;`zvf:A`;`z2:A`] THEN ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    SUBGOAL_THEN `erel D (E:A->A->bool) leq ii c` ASSUME_TAC THENL
     [MATCH_MP_TAC(ISPECL
                   [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`qv:A`;`zvf:A`;
                    `z2:A`;`c:A`;`ii:A`] EBIMP_ANT) THEN ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`zsub:A`;`ii:A`;
                  `c:A`] EPORDER_TRANS) THEN ASM_REWRITE_TAC[]]);;

(* ===================================================================== *)
(* F5 / V^B POWERSET axiom -- lemma P2 (power name) + P3a/P3c (value LE   *)
(* + congruence) + GE helper.  Appended after P1/P1b (esubval layer).    *)
(*                                                                        *)
(*   esubval D E B leq x f  =  [[ f SUBSET x ]]  (built P1).              *)
(*   pn = { <f, esubval(x,f)> : f IN FS }  is the power name of x.        *)
(*   Target value equation (P3d/e, next):  [[ t IN pn ]] = [[ t SUBSET x ]].*)
(* ===================================================================== *)

(* --- object forms: esubcombset_form / esubval_form + HOLDS ----------- *)
(* esubcombset as an OBJECT formula: S is the set of subset-combiners.       *)
(* Carrier B is the FIXED slot 2 (inherited from esubcomb_form/ebv_in_form). *)
let esubcombset_form = new_definition
  `esubcombset_form iS iff ix ileq =
     !! (MAX iS (MAX iff (MAX ix (MAX ileq 2))) + 1)
        (((MAX iS (MAX iff (MAX ix (MAX ileq 2))) + 1) %% iS) <->
         esubcomb_form (MAX iS (MAX iff (MAX ix (MAX ileq 2))) + 1)
           iff ix ileq)`;;

let HOLDS_ESUBCOMBSET_FORM = prove
 (`!D (E:A->A->bool) v iS iff ix ileq.
      model D E ZF_AX /\ valuation D v
      ==> (holds D E v (esubcombset_form iS iff ix ileq) <=>
           esubcombset D E (v 2) (v ileq) (v ix) (v iff) (v iS))`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `!x. (v:num->A) x IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[valuation]; ALL_TAC] THEN
  REWRITE_TAC[esubcombset_form] THEN
  ABBREV_TAC `ic = MAX iS (MAX iff (MAX ix (MAX ileq 2))) + 1` THEN
  SUBGOAL_THEN
   `~(iS:num = ic) /\ ~(iff = ic) /\ ~(ix = ic) /\ ~(ileq = ic) /\ ~(2 = ic)`
  STRIP_ASSUME_TAC THENL [EXPAND_TAC "ic" THEN ARITH_TAC; ALL_TAC] THEN
  REWRITE_TAC[esubcombset] THEN ASM_REWRITE_TAC[] THEN
  REWRITE_TAC[holds; HOLDS_IFF] THEN
  MATCH_MP_TAC(MESON[]
    `(!a:A. a IN D ==> (P a <=> Q a))
     ==> ((!a. a IN D ==> P a) <=> (!a. a IN D ==> Q a))`) THEN
  X_GEN_TAC `c:A` THEN DISCH_TAC THEN
  SUBGOAL_THEN `valuation D (((ic:num) |-> (c:A)) v)` ASSUME_TAC THENL
   [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`((ic:num) |-> (c:A)) v`;
                `ic:num`;`iff:num`;`ix:num`;`ileq:num`]
    HOLDS_ESUBCOMB_FORM) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  ASM_SIMP_TAC[VALMOD; ARITH_EQ]);;
(* esubval as an OBJECT formula: iz is the GLB of the esubcombset (slot-2 *)
(* B). *)
let esubval_form = new_definition
  `esubval_form iz iff ix ileq =
     ?? (MAX iz (MAX iff (MAX ix (MAX ileq 2))) + 1)
        (esubcombset_form (MAX iz (MAX iff (MAX ix (MAX ileq 2))) + 1)
           iff ix ileq &&
         eglb_form 2 ileq (MAX iz (MAX iff (MAX ix (MAX ileq 2))) + 1) iz)`;;

let HOLDS_ESUBVAL_FORM = prove
 (`!D (E:A->A->bool) v iz iff ix ileq.
      model D E ZF_AX /\ valuation D v
      ==> (holds D E v (esubval_form iz iff ix ileq) <=>
           esubval D E (v 2) (v ileq) (v ix) (v iff) (v iz))`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `!x. (v:num->A) x IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[valuation]; ALL_TAC] THEN
  REWRITE_TAC[esubval_form; esubval] THEN
  ABBREV_TAC `iSS = MAX iz (MAX iff (MAX ix (MAX ileq 2))) + 1` THEN
  SUBGOAL_THEN
   `~(iz:num = iSS) /\ ~(iff = iSS) /\ ~(ix = iSS) /\ ~(ileq = iSS) /\
    ~(2 = iSS)`
  STRIP_ASSUME_TAC THENL [EXPAND_TAC "iSS" THEN ARITH_TAC; ALL_TAC] THEN
  REWRITE_TAC[HOLDS_EX; HOLDS_AND] THEN
  EQ_TAC THENL
   [DISCH_THEN(X_CHOOSE_THEN `S:A` (CONJUNCTS_THEN2 ASSUME_TAC MP_TAC)) THEN
    SUBGOAL_THEN `valuation D (((iSS:num) |-> (S:A)) v)` ASSUME_TAC THENL
     [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
    MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`((iSS:num) |-> (S:A)) v`;
                  `iSS:num`;`iff:num`;`ix:num`;`ileq:num`]
      HOLDS_ESUBCOMBSET_FORM) THEN
    ASM_REWRITE_TAC[] THEN DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`((iSS:num) |-> (S:A)) v`;
                  `2`;`ileq:num`;`iSS:num`;`iz:num`] HOLDS_EGLB_FORM) THEN
    ASM_REWRITE_TAC[] THEN DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    ASM_SIMP_TAC[VALMOD; ARITH_EQ] THEN STRIP_TAC THEN
    EXISTS_TAC `S:A` THEN ASM_REWRITE_TAC[];
    DISCH_THEN(X_CHOOSE_THEN `S:A` STRIP_ASSUME_TAC) THEN
    EXISTS_TAC `S:A` THEN
    SUBGOAL_THEN `(S:A) IN D` ASSUME_TAC THENL
     [ASM_MESON_TAC[esubcombset]; ALL_TAC] THEN
    ASM_REWRITE_TAC[] THEN
    SUBGOAL_THEN `valuation D (((iSS:num) |-> (S:A)) v)` ASSUME_TAC THENL
     [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
    MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`((iSS:num) |-> (S:A)) v`;
                  `iSS:num`;`iff:num`;`ix:num`;`ileq:num`]
      HOLDS_ESUBCOMBSET_FORM) THEN
    ASM_REWRITE_TAC[] THEN DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`((iSS:num) |-> (S:A)) v`;
                  `2`;`ileq:num`;`iSS:num`;`iz:num`] HOLDS_EGLB_FORM) THEN
    ASM_REWRITE_TAC[] THEN DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    ASM_SIMP_TAC[VALMOD; ARITH_EQ]]);;

(* --- P2: EPOWERNAME_EXISTS (power name as functional graph) --------- *)
(* --------------------------------------------------------------------- *)
(* F5 POWER axiom: the power NAME as a functional graph.                  *)
(*   pn = { <f, esubval(x,f)> : f IN FS }  built by ZF replacement along   *)
(*   the object formula  ?? 1 (esubval_form 1 0 4 6 && opair_form 0 1 3),  *)
(*   input f = var 0 (over a = FS), output pair = var 3, value = var 1,    *)
(*   params x = var 4, leq = var 6, B = var 2 (carrier slot).  Mirrors      *)
(*   EUNIONNAME_EXISTS, but with esubval (subset value) and B at slot 2.   *)
(* --------------------------------------------------------------------- *)

let EPOWERNAME_EXISTS = prove
 (`!D (E:A->A->bool) B leq x FS.
        model D E ZF_AX /\ ecba D E B leq /\
        B IN D /\ leq IN D /\ x IN D /\ FS IN D
        ==> ?pn. pn IN D /\ eisfun D E pn /\ edomain D E pn FS /\
                 (!s q. s IN D /\ E s FS /\ esubval D E B leq x s q
                        ==> eapply D E pn s q) /\
                 (!z. z IN D
                      ==> (E z pn <=>
                           ?s q. s IN D /\ q IN D /\ E s FS /\
                                 esubval D E B leq x s q /\
                                 eopair D (E:A->A->bool) s q z))`,
  REPEAT GEN_TAC THEN
  STRIP_TAC THEN
  SUBGOAL_THEN `?v0:num->A. valuation D v0` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[VALUATION_EXISTS; MODEL_NONEMPTY]; ALL_TAC] THEN
  ABBREV_TAC `vP = (4 |-> (x:A)) ((6 |-> (leq:A)) ((2 |-> (B:A)) v0))` THEN
  SUBGOAL_THEN
   `valuation D (vP:num->A) /\
    (vP:num->A) 4 = x /\ (vP:num->A) 6 = leq /\ (vP:num->A) 2 = B`
  STRIP_ASSUME_TAC THENL
   [EXPAND_TAC "vP" THEN
    ASM_SIMP_TAC[VALUATION_VALMOD; VALMOD; ARITH_EQ]; ALL_TAC] THEN
  SUBGOAL_THEN
   `!el ot:A. el IN D /\ ot IN D
      ==> (holds D E ((3 |-> ot) ((0 |-> el) vP))
             (?? 1 (esubval_form 1 0 4 6 && opair_form 0 1 3)) <=>
           ?q. q IN D /\ esubval D E B leq x el q /\
               eopair D (E:A->A->bool) el q ot)`
  (LABEL_TAC "hrk") THENL
   [REPEAT GEN_TAC THEN STRIP_TAC THEN
    REWRITE_TAC[HOLDS_EX; HOLDS_AND] THEN
    MATCH_MP_TAC(MESON[]
     `(!q:A. P q <=> Q q) ==> ((?q:A. P q) <=> (?q:A. Q q))`) THEN
    X_GEN_TAC `q:A` THEN
    MATCH_MP_TAC(TAUT `(a ==> (p <=> q)) ==> ((a /\ p) <=> (a /\ q))`) THEN
    DISCH_TAC THEN
    SUBGOAL_THEN
     `valuation D ((1 |-> (q:A)) ((3 |-> (ot:A)) ((0 |-> (el:A)) vP)))`
    ASSUME_TAC THENL
     [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
      `(1 |-> (q:A)) ((3 |-> (ot:A)) ((0 |-> (el:A)) vP))`;
      `1`; `0`; `4`; `6`] HOLDS_ESUBVAL_FORM) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
      `(1 |-> (q:A)) ((3 |-> (ot:A)) ((0 |-> (el:A)) vP))`;
      `0`; `1`; `3`] HOLDS_OPAIR_FORM) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    ASM_REWRITE_TAC[VALMOD; ARITH_EQ];
    ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`] ZF_REPLACEMENT) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(MP_TAC o SPECL
    [`?? 1 (esubval_form 1 0 4 6 && opair_form 0 1 3)`;
     `0`; `3`; `vP:num->A`; `FS:A`]) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[ARITH_EQ] THEN
    X_GEN_TAC `u:A` THEN STRIP_TAC THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `B:A`; `leq:A`; `x:A`; `u:A`]
      ESUBVAL_EXISTS) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(X_CHOOSE_THEN `q:A` STRIP_ASSUME_TAC) THEN
    SUBGOAL_THEN `(q:A) IN D` ASSUME_TAC THENL
     [ASM_MESON_TAC[ESUBVAL_IN]; ALL_TAC] THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `u:A`; `q:A`]
      EOPAIR_EXISTS) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(X_CHOOSE_TAC `pv:A`) THEN
    SUBGOAL_THEN `(pv:A) IN D` ASSUME_TAC THENL
     [ASM_MESON_TAC[EOPAIR_IN]; ALL_TAC] THEN
    EXISTS_TAC `pv:A` THEN ASM_REWRITE_TAC[] THEN
    X_GEN_TAC `w':A` THEN
    DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC MP_TAC) THEN
    USE_THEN "hrk" (MP_TAC o SPECL [`u:A`; `w':A`]) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    DISCH_THEN(X_CHOOSE_THEN `q':A` STRIP_ASSUME_TAC) THEN
    SUBGOAL_THEN `(q':A) = q` SUBST_ALL_TAC THENL
     [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `B:A`; `leq:A`; `x:A`;
        `u:A`; `q':A`; `q:A`] ESUBVAL_UNIQUE) THEN ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `u:A`; `q:A`; `w':A`; `pv:A`]
      EOPAIR_UNIQUE) THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `pn:A` (CONJUNCTS_THEN2 ASSUME_TAC
    (LABEL_TAC "raw"))) THEN
  SUBGOAL_THEN
   `!z. z IN D
        ==> (E z pn <=>
             ?s q. s IN D /\ q IN D /\ E s FS /\
                   esubval D E B leq x s q /\
                   eopair D (E:A->A->bool) s q z)`
  (LABEL_TAC "PNc") THENL
   [X_GEN_TAC `z:A` THEN DISCH_TAC THEN
    USE_THEN "raw" (MP_TAC o SPEC `z:A`) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    EQ_TAC THENL
     [DISCH_THEN(X_CHOOSE_THEN `s:A` (CONJUNCTS_THEN2 ASSUME_TAC
        (CONJUNCTS_THEN2 ASSUME_TAC MP_TAC))) THEN
      USE_THEN "hrk" (MP_TAC o SPECL [`s:A`; `z:A`]) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
      DISCH_THEN(X_CHOOSE_THEN `q:A` STRIP_ASSUME_TAC) THEN
      MAP_EVERY EXISTS_TAC [`s:A`; `q:A`] THEN ASM_REWRITE_TAC[];
      DISCH_THEN(X_CHOOSE_THEN `s:A` (X_CHOOSE_THEN `q:A`
        STRIP_ASSUME_TAC)) THEN
      EXISTS_TAC `s:A` THEN ASM_REWRITE_TAC[] THEN
      USE_THEN "hrk" (MP_TAC o SPECL [`s:A`; `z:A`]) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
      EXISTS_TAC `q:A` THEN ASM_REWRITE_TAC[]];
    ALL_TAC] THEN
  EXISTS_TAC `pn:A` THEN REPEAT CONJ_TAC THENL
   [FIRST_ASSUM ACCEPT_TAC;
    REWRITE_TAC[eisfun] THEN REPEAT CONJ_TAC THENL
     [FIRST_ASSUM ACCEPT_TAC;
      X_GEN_TAC `z:A` THEN STRIP_TAC THEN
      SUBGOAL_THEN
       `?s q. s IN D /\ q IN D /\ E s FS /\ esubval D E B leq x s q /\
              eopair D (E:A->A->bool) s q z`
      STRIP_ASSUME_TAC THENL [ASM_MESON_TAC[]; ALL_TAC] THEN
      MAP_EVERY EXISTS_TAC [`s:A`; `q:A`] THEN ASM_REWRITE_TAC[];
      REPEAT GEN_TAC THEN STRIP_TAC THEN
      SUBGOAL_THEN `(z:A) IN D /\ (z':A) IN D` STRIP_ASSUME_TAC THENL
       [ASM_MESON_TAC[EOPAIR_IN]; ALL_TAC] THEN
      SUBGOAL_THEN
       `?s1 q1. s1 IN D /\ q1 IN D /\ E s1 FS /\ esubval D E B leq x s1 q1 /\
                eopair D (E:A->A->bool) s1 q1 z`
      STRIP_ASSUME_TAC THENL [ASM_MESON_TAC[]; ALL_TAC] THEN
      SUBGOAL_THEN
       `?s2 q2. s2 IN D /\ q2 IN D /\ E s2 FS /\ esubval D E B leq x s2 q2 /\
                eopair D (E:A->A->bool) s2 q2 z'`
      STRIP_ASSUME_TAC THENL [ASM_MESON_TAC[]; ALL_TAC] THEN
      SUBGOAL_THEN `(u:A) = s1 /\ (w:A) = q1` STRIP_ASSUME_TAC THENL
       [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `u:A`; `w:A`;
          `s1:A`; `q1:A`; `z:A`] EOPAIR_INJ) THEN ASM_REWRITE_TAC[];
        ALL_TAC] THEN
      SUBGOAL_THEN `(u:A) = s2 /\ (w':A) = q2` STRIP_ASSUME_TAC THENL
       [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `u:A`; `w':A`;
          `s2:A`; `q2:A`; `z':A`] EOPAIR_INJ) THEN ASM_REWRITE_TAC[];
        ALL_TAC] THEN
      SUBGOAL_THEN `(s2:A) = s1` ASSUME_TAC THENL
       [ASM_MESON_TAC[]; ALL_TAC] THEN
      MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `B:A`; `leq:A`; `x:A`;
        `s1:A`; `q1:A`; `q2:A`] ESUBVAL_UNIQUE) THEN
      ANTS_TAC THENL [ASM_MESON_TAC[]; ASM_MESON_TAC[]]];
    REWRITE_TAC[edomain] THEN CONJ_TAC THENL
     [FIRST_ASSUM ACCEPT_TAC;
      X_GEN_TAC `u:A` THEN DISCH_TAC THEN REWRITE_TAC[eindom] THEN
      EQ_TAC THENL
       [DISCH_TAC THEN
        MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `B:A`; `leq:A`; `x:A`;
          `u:A`] ESUBVAL_EXISTS) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
        DISCH_THEN(X_CHOOSE_THEN `q:A` STRIP_ASSUME_TAC) THEN
        SUBGOAL_THEN `(q:A) IN D` ASSUME_TAC THENL
         [ASM_MESON_TAC[ESUBVAL_IN]; ALL_TAC] THEN
        MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `u:A`; `q:A`]
          EOPAIR_EXISTS) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
        DISCH_THEN(X_CHOOSE_TAC `zz:A`) THEN
        SUBGOAL_THEN `(zz:A) IN D` ASSUME_TAC THENL
         [ASM_MESON_TAC[EOPAIR_IN]; ALL_TAC] THEN
        EXISTS_TAC `q:A` THEN CONJ_TAC THENL
         [FIRST_ASSUM ACCEPT_TAC;
          REWRITE_TAC[eapply] THEN EXISTS_TAC `zz:A` THEN CONJ_TAC THENL
           [FIRST_ASSUM ACCEPT_TAC; ASM_MESON_TAC[]]];
        DISCH_THEN(X_CHOOSE_THEN `wv:A` (CONJUNCTS_THEN2 ASSUME_TAC
          MP_TAC)) THEN
        REWRITE_TAC[eapply] THEN
        DISCH_THEN(X_CHOOSE_THEN `zz:A` STRIP_ASSUME_TAC) THEN
        SUBGOAL_THEN `(zz:A) IN D` ASSUME_TAC THENL
         [ASM_MESON_TAC[EOPAIR_IN]; ALL_TAC] THEN
        SUBGOAL_THEN
         `?s1 q1. s1 IN D /\ q1 IN D /\ E s1 FS /\ esubval D E B leq x s1 q1 /\
                  eopair D (E:A->A->bool) s1 q1 zz`
        STRIP_ASSUME_TAC THENL [ASM_MESON_TAC[]; ALL_TAC] THEN
        SUBGOAL_THEN `(u:A) = s1` ASSUME_TAC THENL
         [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `u:A`; `wv:A`;
            `s1:A`; `q1:A`; `zz:A`] EOPAIR_INJ) THEN ASM_MESON_TAC[];
          ALL_TAC] THEN
        ASM_MESON_TAC[]]];
    REPEAT GEN_TAC THEN STRIP_TAC THEN
    SUBGOAL_THEN `(q:A) IN D` ASSUME_TAC THENL
     [ASM_MESON_TAC[ESUBVAL_IN]; ALL_TAC] THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `s:A`; `q:A`]
      EOPAIR_EXISTS) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(X_CHOOSE_TAC `zz:A`) THEN
    SUBGOAL_THEN `(zz:A) IN D` ASSUME_TAC THENL
     [ASM_MESON_TAC[EOPAIR_IN]; ALL_TAC] THEN
    REWRITE_TAC[eapply] THEN EXISTS_TAC `zz:A` THEN CONJ_TAC THENL
     [FIRST_ASSUM ACCEPT_TAC; ASM_MESON_TAC[]];
    USE_THEN "PNc" ACCEPT_TAC]);;

(* --------------------------------------------------------------------- *)
(* F5 POWER axiom: the power NAME is a B-name.                            *)
(* pn = { <f, esubval(x,f)> : f IN FS }.  Its members are pairs <f,q>     *)
(* with f IN FS and q IN B.  When FS sits inside a B-name stage table fy   *)
(* (ebnstage fa fy), every f IN FS is E-below fy, hence below the         *)
(* next-stage domain-table w1 (EBNSTAGE_CHAR), so pn SUBSET w1 x B; thus  *)
(* ebnmem w1 pn and pn IN ysa = bnstage(sa=fa+1).  Twin ESEPNAME_BNAME     *)
(* but the FS-in-stage containment is a HYPOTHESIS (the power             *)
(* domain FS = x's own stage table, supplied at the P4 call site) rather  *)
(* than derived from a bname via STAGE_DOM_CLOSED.                        *)
(* --------------------------------------------------------------------- *)

let EPOWERNAME_BNAME = prove
 (`!D (E:A->A->bool) B leq x FS fa fy pn.
      model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
      x IN D /\ FS IN D /\
      fa IN D /\ fy IN D /\ eordinal D E fa /\ ebnstage D E B fa fy /\
      (!f. f IN D /\ E f FS ==> E f fy) /\
      pn IN D /\ eisfun D E pn /\
      (!z. z IN D
           ==> (E z pn <=>
                ?s q. s IN D /\ q IN D /\ E s FS /\
                      esubval D E B leq x s q /\
                      eopair D (E:A->A->bool) s q z))
      ==> bname D E B pn`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "zf cba BD leqD xD FSD faD fyD ordfa h Wsub pnD funpn pnch" THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`fa:A`] ESUC_EXISTS) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `sa:A`) THEN
  SUBGOAL_THEN
    `(sa:A) IN D /\ eordinal D (E:A->A->bool) sa /\ (E:A->A->bool) fa sa`
  STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[ESUC_IN; EORDINAL_ESUC; ESUC_MEMBER]; ALL_TAC] THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`sa:A`] EBNSTAGE_EXISTS) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `ysa:A` STRIP_ASSUME_TAC) THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`sa:A`;`ysa:A`]
         EBNSTAGE_CHAR) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `w1:A` (CONJUNCTS_THEN2 ASSUME_TAC
    (CONJUNCTS_THEN2 (LABEL_TAC "w1ch") ASSUME_TAC))) THEN
  SUBGOAL_THEN `!u:A. u IN D /\ (E:A->A->bool) u fy ==> E u w1`
    (LABEL_TAC "Ysub") THENL
   [X_GEN_TAC `u:A` THEN STRIP_TAC THEN
    USE_THEN "w1ch" (MP_TAC o SPEC `u:A`) THEN
    ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    MAP_EVERY EXISTS_TAC [`fa:A`;`fy:A`] THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`w1:A`;`B:A`] ECROSS_EXISTS) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `cr:A` (LABEL_TAC "cr")) THEN
  SUBGOAL_THEN `(cr:A) IN D` ASSUME_TAC THENL
   [USE_THEN "cr" (MP_TAC o REWRITE_RULE[ecross]) THEN SIMP_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `esubset D (E:A->A->bool) pn cr` ASSUME_TAC THENL
   [REWRITE_TAC[esubset] THEN X_GEN_TAC `z:A` THEN STRIP_TAC THEN
    USE_THEN "cr" (MP_TAC o SPEC `z:A` o CONJUNCT2 o REWRITE_RULE[ecross]) THEN
    ASM_REWRITE_TAC[] THEN DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    USE_THEN "pnch" (MP_TAC o SPEC `z:A`) THEN
    ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN(fun th -> MP_TAC(EQ_MP th (ASSUME `(E:A->A->bool) z pn`))) THEN
    DISCH_THEN(X_CHOOSE_THEN `s:A` (X_CHOOSE_THEN `q:A` STRIP_ASSUME_TAC)) THEN
    SUBGOAL_THEN `(E:A->A->bool) s fy` ASSUME_TAC THENL
     [USE_THEN "Wsub" MATCH_MP_TAC THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN `(E:A->A->bool) s w1` ASSUME_TAC THENL
     [USE_THEN "Ysub" MATCH_MP_TAC THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN `(E:A->A->bool) q B` ASSUME_TAC THENL
     [ASM_MESON_TAC[ESUBVAL_IN]; ALL_TAC] THEN
    MAP_EVERY EXISTS_TAC [`s:A`;`q:A`] THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `ebnmem D (E:A->A->bool) B w1 pn` ASSUME_TAC THENL
   [REWRITE_TAC[ebnmem] THEN ASM_REWRITE_TAC[] THEN
    EXISTS_TAC `cr:A` THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) pn ysa` ASSUME_TAC THENL
   [UNDISCH_TAC `ebnfuns D (E:A->A->bool) B w1 ysa` THEN
    REWRITE_TAC[ebnfuns] THEN
    DISCH_THEN(MP_TAC o SPEC `pn:A` o CONJUNCT2) THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  REWRITE_TAC[bname] THEN MAP_EVERY EXISTS_TAC [`sa:A`;`ysa:A`] THEN
  ASM_REWRITE_TAC[]);;

(* --- P3a: ESUBVAL_CONG (SUBSET congruence under Boolean =) ---------- *)
(* --------------------------------------------------------------------- *)
(* F5 POWER axiom:  congruence of SUBSET under Boolean =.                 *)
(*   [[ u = v ]] MEET [[ v SUBSET x ]]  <=  [[ u SUBSET x ]]              *)
(* i.e. zeq MEET zvx <= zux.  Proved via ESUBVAL_GREATEST on the u-side:  *)
(* m = zeq MEET zvx lower-bounds every u-combiner  qa IMP [[a in x]]      *)
(* (a in dom u, qa=u(a)).  Per combiner, residuate to  m MEET qa <= z2:   *)
(*   qa <= [[a in u]] (EBV_MEMBER_LE_V);                                  *)
(*   zeq MEET [[a in u]] <= [[a in v]]  (C2 congruence EBV_IN_CONG_R);     *)
(*   zvx <= ([[a in v]] IMP [[a in x]]) (ESUBVAL_ALLW_LB) so              *)
(*   zvx MEET [[a in v]] <= [[a in x]]=z2 (modus ponens EBIMP_MEET_LE).   *)
(* The meet-chain assembles  m MEET qa <= z2, then EBIMP_LE_IMP.          *)
(* --------------------------------------------------------------------- *)

let ESUBVAL_CONG = prove
 (`!D (E:A->A->bool) B leq x u v zeq zvx zux m.
      model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
      x IN D /\ bname D E B x /\ u IN D /\ bname D E B u /\
      v IN D /\ bname D E B v /\
      zeq IN D /\ zvx IN D /\ zux IN D /\ m IN D /\
      ebv_eq D E B leq u v zeq /\
      esubval D E B leq x v zvx /\ esubval D E B leq x u zux /\
      emeet D E B leq zeq zvx m
      ==> erel D E leq m zux`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `ebalg D (E:A->A->bool) B leq` ASSUME_TAC THENL
   [ASM_MESON_TAC[ECBA_IMP_BALG]; ALL_TAC] THEN
  SUBGOAL_THEN `eporder D (E:A->A->bool) B leq` ASSUME_TAC THENL
   [ASM_MESON_TAC[EBALG_IMP_PORDER]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) zeq B` ASSUME_TAC THENL
   [ASM_MESON_TAC[EBV_EQ_IN_B]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) zvx B` ASSUME_TAC THENL
   [ASM_MESON_TAC[ESUBVAL_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) zux B` ASSUME_TAC THENL
   [ASM_MESON_TAC[ESUBVAL_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) m B` ASSUME_TAC THENL
   [ASM_MESON_TAC[EMEET_IN]; ALL_TAC] THEN
  MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`x:A`;`u:A`;
    `zux:A`;`m:A`] ESUBVAL_GREATEST) THEN
  ASM_REWRITE_TAC[] THEN
  X_GEN_TAC `c:A` THEN REWRITE_TAC[esubcomb] THEN
  DISCH_THEN(X_CHOOSE_THEN `a:A` (X_CHOOSE_THEN `qa:A`
    (X_CHOOSE_THEN `z2:A` STRIP_ASSUME_TAC))) THEN
  (* a in dom u, hence a bname; type the intermediate values. *)
  SUBGOAL_THEN `eindom D (E:A->A->bool) u a` ASSUME_TAC THENL
   [REWRITE_TAC[eindom] THEN EXISTS_TAC `qa:A` THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `bname D (E:A->A->bool) B a` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`u:A`;`a:A`]
      UNION_DOM_BNAME) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) qa B` ASSUME_TAC THENL
   [MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`u:A`;`a:A`;`qa:A`]
      BNAME_APPLY_IN_B) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) z2 B` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`a:A`;`x:A`;
      `z2:A`] EBV_IN_IN_B) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) c B` ASSUME_TAC THENL
   [ASM_MESON_TAC[EBIMP_IN]; ALL_TAC] THEN
  (* zau = [[a in u]] , zav = [[a in v]] *)
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`a:A`;`u:A`]
    EBV_IN_VAL_EXISTS) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `zau:A` STRIP_ASSUME_TAC) THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`a:A`;`v:A`]
    EBV_IN_VAL_EXISTS) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `zav:A` STRIP_ASSUME_TAC) THEN
  (* qa <= [[a in u]] *)
  SUBGOAL_THEN `erel D (E:A->A->bool) leq qa zau` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`u:A`;`a:A`;
      `qa:A`;`zau:A`] EBV_MEMBER_LE_V) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* z23 = zeq MEET [[a in u]] <= [[a in v]]  (C2 congruence) *)
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`zeq:A`;`zau:A`]
    EBALG_MEET) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `z23:A`) THEN
  SUBGOAL_THEN `(z23:A) IN D /\ (E:A->A->bool) z23 B` STRIP_ASSUME_TAC THENL
   [MP_TAC(ISPECL
           [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`zeq:A`;`zau:A`;`z23:A`]
           EMEET_IN) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq z23 zav` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`u:A`;`v:A`;
      `a:A`;`zeq:A`;`zau:A`;`zav:A`;`z23:A`] EBV_IN_CONG_R) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* ii = [[a in v]] IMP z2 ; zvx <= ii *)
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`zav:A`;`z2:A`]
    EBIMP_EXISTS) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `ii:A`) THEN
  SUBGOAL_THEN `(ii:A) IN D /\ (E:A->A->bool) ii B` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[EBIMP_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq zvx ii` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`x:A`;`v:A`;
      `zvx:A`;`a:A`;`zav:A`;`z2:A`;`ii:A`] ESUBVAL_ALLW_LB) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* mq = m MEET qa *)
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`m:A`;`qa:A`]
    EBALG_MEET) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `mq:A`) THEN
  SUBGOAL_THEN `(mq:A) IN D /\ (E:A->A->bool) mq B` STRIP_ASSUME_TAC THENL
   [MP_TAC(ISPECL
           [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`m:A`;`qa:A`;`mq:A`]
           EMEET_IN) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq mq m /\ erel D E leq mq qa`
  STRIP_ASSUME_TAC THENL
   [MP_TAC(ISPECL
           [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`m:A`;`qa:A`;`mq:A`]
           EMEET_LE) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq m zeq /\ erel D E leq m zvx`
  STRIP_ASSUME_TAC THENL
   [MP_TAC(ISPECL
           [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`zeq:A`;`zvx:A`;`m:A`]
           EMEET_LE) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq mq zeq` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`mq:A`;`m:A`;
      `zeq:A`] EPORDER_TRANS) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq mq zvx` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`mq:A`;`m:A`;
      `zvx:A`] EPORDER_TRANS) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq mq zau` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`mq:A`;`qa:A`;
                  `zau:A`] EPORDER_TRANS) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq mq z23` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`zeq:A`;`zau:A`;
                  `z23:A`;`mq:A`] EMEET_GREATEST) THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq mq zav` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`mq:A`;`z23:A`;
                  `zav:A`] EPORDER_TRANS) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* zvxav = zvx MEET [[a in v]] <= z2  (modus ponens) *)
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`zvx:A`;`zav:A`]
    EBALG_MEET) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `zvxav:A`) THEN
  SUBGOAL_THEN `(zvxav:A) IN D /\ (E:A->A->bool) zvxav B`
    STRIP_ASSUME_TAC THENL
   [MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`zvx:A`;`zav:A`;
      `zvxav:A`] EMEET_IN) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq mq zvxav` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`zvx:A`;`zav:A`;
                  `zvxav:A`;`mq:A`] EMEET_GREATEST) THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq zvxav z2` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`zvx:A`;`zav:A`;
                  `z2:A`;`ii:A`;`zvxav:A`] EBIMP_MEET_LE) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq mq z2` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`mq:A`;`zvxav:A`;
                  `z2:A`] EPORDER_TRANS) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* m <= c = (qa IMP z2)  via EBIMP_LE_IMP *)
  MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`m:A`;`qa:A`;
    `z2:A`;`c:A`;`mq:A`] EBIMP_LE_IMP) THEN ASM_REWRITE_TAC[]);;

(* --- P3c: EBV_IN_POW_LE ([[t in pn]] <= [[t SUBSET x]]) ------------- *)
(* --------------------------------------------------------------------- *)
(* F5 POWER axiom:  [[ tt in pn ]]  <=  [[ tt SUBSET x ]].                *)
(* pn is the power name of x (dom pn = FS, pn(f) = esubval x f).  By       *)
(* EBV_IN_LE_V it suffices that each dom-pn term  pn(y) MEET [[tt=y]]      *)
(* under-bounds ztx = esubval x tt.  Invert pn(y): y in FS => bname y =>   *)
(* esubval x y exists => (value-char + EAPPLY_UNIQUE) qy = esubval x y.    *)
(* Then the term  esubval x y MEET [[tt=y]] <= esubval x tt  is exactly    *)
(* ESUBVAL_CONG (subset congruence under =).                              *)
(* --------------------------------------------------------------------- *)

let EBV_IN_POW_LE = prove
 (`!D (E:A->A->bool) B leq x FS tt pn zin ztx.
      model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
      x IN D /\ bname D E B x /\ FS IN D /\
      tt IN D /\ bname D E B tt /\ pn IN D /\ eisfun D E pn /\
      (!f. f IN D /\ E f FS ==> bname D E B f) /\
      (!f q. f IN D /\ E f FS /\ esubval D E B leq x f q ==>
       eapply D E pn f q) /\
      (!f. f IN D ==> (eindom D E pn f <=> E f FS)) /\
      zin IN D /\ ztx IN D /\
      ebv_in D E B leq tt pn zin /\ esubval D E B leq x tt ztx
      ==> erel D E leq zin ztx`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `ebalg D (E:A->A->bool) B leq` ASSUME_TAC THENL
   [ASM_MESON_TAC[ECBA_IMP_BALG]; ALL_TAC] THEN
  SUBGOAL_THEN `eporder D (E:A->A->bool) B leq` ASSUME_TAC THENL
   [ASM_MESON_TAC[EBALG_IMP_PORDER]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) ztx B` ASSUME_TAC THENL
   [ASM_MESON_TAC[ESUBVAL_IN]; ALL_TAC] THEN
  MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`tt:A`;`pn:A`;
    `zin:A`;`ztx:A`] EBV_IN_LE_V) THEN
  ASM_REWRITE_TAC[] THEN
  MAP_EVERY X_GEN_TAC [`y:A`;`qy:A`;`ey:A`;`c:A`] THEN STRIP_TAC THEN
  SUBGOAL_THEN `eindom D (E:A->A->bool) pn y` ASSUME_TAC THENL
   [REWRITE_TAC[eindom] THEN EXISTS_TAC `qy:A` THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) y FS` ASSUME_TAC THENL
   [UNDISCH_TAC
    `!f:A. f IN D ==> (eindom D (E:A->A->bool) pn f <=> E f FS)` THEN
    DISCH_THEN(MP_TAC o SPEC `y:A`) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `bname D (E:A->A->bool) B y` ASSUME_TAC THENL
   [UNDISCH_TAC `!f:A. f IN D /\ (E:A->A->bool) f FS ==> bname D E B f` THEN
    DISCH_THEN(MATCH_MP_TAC o SPEC `y:A`) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`x:A`;`y:A`]
    ESUBVAL_EXISTS) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `q:A`) THEN
  SUBGOAL_THEN `(q:A) IN D /\ (E:A->A->bool) q B` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[ESUBVAL_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `eapply D (E:A->A->bool) pn y q` ASSUME_TAC THENL
   [UNDISCH_TAC `!f q:A. f IN D /\ (E:A->A->bool) f FS /\
                   esubval D E B leq x f q ==> eapply D E pn f q` THEN
    DISCH_THEN(MATCH_MP_TAC o SPECL [`y:A`;`q:A`]) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `qy:A = q` SUBST_ALL_TAC THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`pn:A`;`y:A`;`qy:A`;`q:A`]
      EAPPLY_UNIQUE) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) ey B` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`tt:A`;`y:A`;
      `ey:A`] EBV_EQ_IN_B) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `emeet D (E:A->A->bool) B leq ey q c` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`q:A`;`ey:A`;
      `c:A`] EMEET_SYM) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`x:A`;`tt:A`;
    `y:A`;`ey:A`;`q:A`;`ztx:A`;`c:A`] ESUBVAL_CONG) THEN
  ASM_REWRITE_TAC[]);;

(* ===================================================================== *)
(* V^B POWER axiom: the power value equation                             *)
(*   [[ t IN pn ]] = [[ t SUBSET x ]]  = esubval x t.                     *)
(* The LE direction is EBV_IN_POW_LE; the results below prove GE and combine *)
(* them.                                                                *)
(* ===================================================================== *)

(* SUBSET_GE_OF_SMALLER: the pointwise hypothesis carries qw IN D.  Without *)
(* it the hypothesis would not be dischargeable for a general trace name,  *)
(* since eapply sn w qw can hold for a junk qw NOTIN D, for which erel leq  *)
(* qw qx is false.                                                         *)
let SUBSET_GE_OF_SMALLER = prove
 (`!D (E:A->A->bool) B leq x sn zsub qy.
      model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
      x IN D /\ bname D E B x /\ sn IN D /\ bname D E B sn /\
      (!w qw. w IN D /\ qw IN D /\ bname D E B w /\ eapply D E sn w qw
              ==> ?qx. qx IN D /\ eapply D E x w qx /\ erel D E leq qw qx) /\
      esubval D E B leq x sn qy /\ zsub IN D /\ E zsub B
      ==> erel D E leq zsub qy`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `ebalg D (E:A->A->bool) B leq` ASSUME_TAC THENL
   [ASM_MESON_TAC[ECBA_IMP_BALG]; ALL_TAC] THEN
  SUBGOAL_THEN `eporder D (E:A->A->bool) B leq` ASSUME_TAC THENL
   [ASM_MESON_TAC[EBALG_IMP_PORDER]; ALL_TAC] THEN
  MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`x:A`;`sn:A`;
    `qy:A`;`zsub:A`] ESUBVAL_GREATEST) THEN
  ASM_REWRITE_TAC[] THEN
  X_GEN_TAC `c:A` THEN REWRITE_TAC[esubcomb] THEN
  DISCH_THEN(X_CHOOSE_THEN `w:A` (X_CHOOSE_THEN `qw:A`
    (X_CHOOSE_THEN `z2:A` STRIP_ASSUME_TAC))) THEN
  SUBGOAL_THEN `eindom D (E:A->A->bool) sn w` ASSUME_TAC THENL
   [REWRITE_TAC[eindom] THEN EXISTS_TAC `qw:A` THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `bname D (E:A->A->bool) B w` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`sn:A`;`w:A`]
      UNION_DOM_BNAME) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  UNDISCH_TAC `!w qw:A. w IN D /\ qw IN D /\ bname D (E:A->A->bool) B w /\
                eapply D E sn w qw
                ==> ?qx. qx IN D /\ eapply D E x w qx /\
                  erel D E leq qw qx` THEN
  DISCH_THEN(MP_TAC o SPECL [`w:A`;`qw:A`]) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `qx:A` STRIP_ASSUME_TAC) THEN
  SUBGOAL_THEN `(E:A->A->bool) qw B /\ (E:A->A->bool) qx B`
    STRIP_ASSUME_TAC THENL
   [MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`qw:A`;`qx:A`]
      EPORDER_FIELD) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) z2 B` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`w:A`;`x:A`;
      `z2:A`] EBV_IN_IN_B) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq qx z2` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`x:A`;`w:A`;
      `qx:A`;`z2:A`] EBV_MEMBER_LE_V) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq qw z2` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`qw:A`;`qx:A`;
                  `z2:A`] EPORDER_TRANS) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `etop D (E:A->A->bool) B leq c` ASSUME_TAC THENL
   [MP_TAC(ISPECL
           [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`qw:A`;`z2:A`;`c:A`]
           EBIMP_TOP) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`c:A`;`zsub:A`]
    ETOP_GE) THEN ASM_REWRITE_TAC[]);;

(* --------------------------------------------------------------------- *)
(* F5 POWER axiom direction (B):  ztx = [[t SUBSET x]]                    *)
(* under-bounds ey = [[t = ft]] where ft is the trace name of t against x *)
(* (ft(w) = x(w) MEET [[w in t]], dom ft = dom x, [[w in ft]] =           *)
(* [[w in x]] MEET [[w in t]]).  ft is kept ABSTRACT via apply-char /     *)
(* member-char hyps; EBV_IN_POW_GE will build the concrete ft.            *)
(* Proof: common stage for (t,ft); EBV_EQ_GLB_STAGE with w0 = ztx.        *)
(*   (hu) x0 in dom t:  ztx MEET t(x0) <= [[x0 in x]] (ESUBVAL_LB) and     *)
(*        <= t(x0) <= [[x0 in t]]; so <= [[x0 in ft]] = exv, giving        *)
(*        ztx <= (t(x0) IMP exv) = c.                                      *)
(*   (hv) y0 in dom ft = dom x:  ft(y0) = x(y0) MEET [[y0 in t]] <=        *)
(*        [[y0 in t]] = eyu, so (ft(y0) IMP eyu) = c is TOP, ztx <= c.     *)
(* --------------------------------------------------------------------- *)

let POW_GE_EQ = prove
 (`!D (E:A->A->bool) B leq x t ft ztx ey.
      model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
      x IN D /\ bname D E B x /\ t IN D /\ bname D E B t /\
      ft IN D /\ bname D E B ft /\ eisfun D E ft /\
      (!w. w IN D ==> (eindom D E ft w <=> eindom D E x w)) /\
      (!w q zwt m. w IN D /\ q IN D /\ zwt IN D /\ m IN D /\
                   eapply D E x w q /\ ebv_in D E B leq w t zwt /\
                   emeet D E B leq q zwt m ==> eapply D E ft w m) /\
      (!w zwx zwt r. w IN D /\ zwx IN D /\ zwt IN D /\ r IN D /\
                     bname D E B w /\
                     ebv_in D E B leq w x zwx /\ ebv_in D E B leq w t zwt /\
                     emeet D E B leq zwx zwt r ==> ebv_in D E B leq w ft r) /\
      ztx IN D /\ esubval D E B leq x t ztx /\
      ey IN D /\ ebv_eq D E B leq t ft ey
      ==> erel D E leq ztx ey`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `ebalg D (E:A->A->bool) B leq` ASSUME_TAC THENL
   [ASM_MESON_TAC[ECBA_IMP_BALG]; ALL_TAC] THEN
  SUBGOAL_THEN `eporder D (E:A->A->bool) B leq` ASSUME_TAC THENL
   [ASM_MESON_TAC[EBALG_IMP_PORDER]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) ztx B` ASSUME_TAC THENL
   [ASM_MESON_TAC[ESUBVAL_IN]; ALL_TAC] THEN
  (* common stage for t, ft *)
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`t:A`;`ft:A`]
         BNAME_DIRECTED) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `ao:A`
             (X_CHOOSE_THEN `stg:A` STRIP_ASSUME_TAC)) THEN
  SUBGOAL_THEN `!zt. zt IN D /\ (E:A->A->bool) zt stg ==> bname D E B zt`
    ASSUME_TAC THENL
   [REPEAT STRIP_TAC THEN
    MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;
                         `ao:A`;`stg:A`;`zt:A`] BNAME_STAGE) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`stg:A`]
         EBVATT_EXISTS) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[] THEN EXISTS_TAC `t:A` THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `sIN:A` (X_CHOOSE_THEN `sEQ:A` ASSUME_TAC)) THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`t:A`;`ft:A`] EOPAIR_EXISTS) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `pr:A`) THEN
  MP_TAC(ISPECL
         [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`stg:A`;`sIN:A`;`sEQ:A`;
          `t:A`;`ft:A`;`pr:A`] EBVATT_VAL) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(CONJUNCTS_THEN2 (K ALL_TAC)
    (X_CHOOSE_THEN `zc:A` STRIP_ASSUME_TAC)) THEN
  SUBGOAL_THEN `ebv_eq D (E:A->A->bool) B leq t ft zc` ASSUME_TAC THENL
   [MP_TAC(ISPECL
           [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`ao:A`;`stg:A`;`sIN:A`;
            `sEQ:A`;`t:A`;`ft:A`;`zc:A`] EBV_EQ_AT_STAGE) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `ey:A = zc` SUBST_ALL_TAC THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`t:A`;`ft:A`;
      `ey:A`;`zc:A`] EBV_EQ_UNIQUE) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MP_TAC(ISPECL
         [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`ao:A`;`stg:A`;`sIN:A`;
          `sEQ:A`;`t:A`;`ft:A`;`zc:A`;`ztx:A`] EBV_EQ_GLB_STAGE) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
     [ (* ---------------- (hu): x0 in dom t ---------------- *)
      MAP_EVERY X_GEN_TAC [`xu:A`;`qu:A`;`exv:A`;`cu:A`] THEN STRIP_TAC THEN
      SUBGOAL_THEN `eindom D (E:A->A->bool) t xu` ASSUME_TAC THENL
       [REWRITE_TAC[eindom] THEN EXISTS_TAC `qu:A` THEN ASM_REWRITE_TAC[];
        ALL_TAC] THEN
      SUBGOAL_THEN `bname D (E:A->A->bool) B xu` ASSUME_TAC THENL
       [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`t:A`;`xu:A`]
          UNION_DOM_BNAME) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
      SUBGOAL_THEN `(E:A->A->bool) qu B` ASSUME_TAC THENL
       [MATCH_MP_TAC(ISPECL
                     [`D:A->bool`;`E:A->A->bool`;`B:A`;`t:A`;`xu:A`;`qu:A`]
                     BNAME_APPLY_IN_B) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
      MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`xu:A`;`x:A`]
        EBV_IN_VAL_EXISTS) THEN ASM_REWRITE_TAC[] THEN
      DISCH_THEN(X_CHOOSE_THEN `zxx:A` STRIP_ASSUME_TAC) THEN
      MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`xu:A`;`t:A`]
        EBV_IN_VAL_EXISTS) THEN ASM_REWRITE_TAC[] THEN
      DISCH_THEN(X_CHOOSE_THEN `zxt:A` STRIP_ASSUME_TAC) THEN
      MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`zxx:A`;`zxt:A`]
        EBALG_MEET) THEN ASM_REWRITE_TAC[] THEN
      DISCH_THEN(X_CHOOSE_TAC `r:A`) THEN
      SUBGOAL_THEN `(r:A) IN D /\ (E:A->A->bool) r B` STRIP_ASSUME_TAC THENL
       [ASM_MESON_TAC[EMEET_IN]; ALL_TAC] THEN
      SUBGOAL_THEN `ebv_in D (E:A->A->bool) B leq xu ft r` ASSUME_TAC THENL
       [UNDISCH_TAC `!w zwx zwt r. w IN D /\ zwx IN D /\ zwt IN D /\ r IN D /\
                     bname D (E:A->A->bool) B w /\
                     ebv_in D E B leq w x zwx /\ ebv_in D E B leq w t zwt /\
                     emeet D E B leq zwx zwt r ==>
                       ebv_in D E B leq w ft r` THEN
        DISCH_THEN(MP_TAC o SPECL [`xu:A`;`zxx:A`;`zxt:A`;`r:A`]) THEN
        ASM_REWRITE_TAC[]; ALL_TAC] THEN
      SUBGOAL_THEN `exv:A = r` SUBST_ALL_TAC THENL
       [MATCH_MP_TAC(ISPECL
                     [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`xu:A`;`ft:A`;
                      `exv:A`;`r:A`] EBV_IN_UNIQUE) THEN ASM_REWRITE_TAC[];
        ALL_TAC] THEN
      MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`ztx:A`;`qu:A`]
        EBALG_MEET) THEN ASM_REWRITE_TAC[] THEN
      DISCH_THEN(X_CHOOSE_TAC `m0:A`) THEN
      SUBGOAL_THEN `(m0:A) IN D /\ (E:A->A->bool) m0 B` STRIP_ASSUME_TAC THENL
       [ASM_MESON_TAC[EMEET_IN]; ALL_TAC] THEN
      MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`qu:A`;`zxx:A`]
        EBIMP_EXISTS) THEN ASM_REWRITE_TAC[] THEN
      DISCH_THEN(X_CHOOSE_TAC `icomb:A`) THEN
      SUBGOAL_THEN `(icomb:A) IN D /\ (E:A->A->bool) icomb B`
        STRIP_ASSUME_TAC THENL
        [ASM_MESON_TAC[EBIMP_IN]; ALL_TAC] THEN
      SUBGOAL_THEN `esubcomb D (E:A->A->bool) B leq x t icomb` ASSUME_TAC THENL
       [REWRITE_TAC[esubcomb] THEN
        MAP_EVERY EXISTS_TAC [`xu:A`;`qu:A`;`zxx:A`] THEN
        ASM_REWRITE_TAC[]; ALL_TAC] THEN
      SUBGOAL_THEN `erel D (E:A->A->bool) leq ztx icomb` ASSUME_TAC THENL
       [MATCH_MP_TAC(ISPECL
                     [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`x:A`;`t:A`;
                      `ztx:A`;`icomb:A`] ESUBVAL_LB) THEN ASM_REWRITE_TAC[];
        ALL_TAC] THEN
      SUBGOAL_THEN `erel D (E:A->A->bool) leq m0 zxx` ASSUME_TAC THENL
       [MATCH_MP_TAC(ISPECL
                     [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`ztx:A`;`qu:A`;
                      `zxx:A`;`icomb:A`;`m0:A`] EBIMP_MEET_LE) THEN
        ASM_REWRITE_TAC[]; ALL_TAC] THEN
      SUBGOAL_THEN `erel D (E:A->A->bool) leq qu zxt` ASSUME_TAC THENL
       [MATCH_MP_TAC(ISPECL
                     [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`t:A`;`xu:A`;
                      `qu:A`;`zxt:A`] EBV_MEMBER_LE_V) THEN ASM_REWRITE_TAC[];
        ALL_TAC] THEN
      SUBGOAL_THEN `erel D (E:A->A->bool) leq m0 qu` ASSUME_TAC THENL
       [ASM_MESON_TAC[EMEET_LE]; ALL_TAC] THEN
      SUBGOAL_THEN `erel D (E:A->A->bool) leq m0 zxt` ASSUME_TAC THENL
       [MATCH_MP_TAC(ISPECL
                     [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`m0:A`;`qu:A`;
                      `zxt:A`] EPORDER_TRANS) THEN ASM_REWRITE_TAC[];
        ALL_TAC] THEN
      SUBGOAL_THEN `erel D (E:A->A->bool) leq m0 r` ASSUME_TAC THENL
       [MATCH_MP_TAC(ISPECL
                     [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`zxx:A`;`zxt:A`;
                      `r:A`;`m0:A`] EMEET_GREATEST) THEN ASM_REWRITE_TAC[];
        ALL_TAC] THEN
      MATCH_MP_TAC(ISPECL
                   [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`ztx:A`;`qu:A`;
                    `r:A`;`cu:A`;`m0:A`] EBIMP_LE_IMP) THEN ASM_REWRITE_TAC[];
      (* ---------------- (hv): y0 in dom ft = dom x ---------------- *)
      MAP_EVERY X_GEN_TAC [`yv:A`;`qyv:A`;`eyu:A`;`cv:A`] THEN STRIP_TAC THEN
      SUBGOAL_THEN `eindom D (E:A->A->bool) ft yv` ASSUME_TAC THENL
       [REWRITE_TAC[eindom] THEN EXISTS_TAC `qyv:A` THEN ASM_REWRITE_TAC[];
        ALL_TAC] THEN
      SUBGOAL_THEN `eindom D (E:A->A->bool) x yv` ASSUME_TAC THENL
       [UNDISCH_TAC
        `!w. w IN D ==> (eindom D (E:A->A->bool) ft w <=> eindom D E x w)` THEN
        DISCH_THEN(MP_TAC o SPEC `yv:A`) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
      SUBGOAL_THEN `bname D (E:A->A->bool) B yv` ASSUME_TAC THENL
       [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`x:A`;`yv:A`]
          UNION_DOM_BNAME) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
      UNDISCH_TAC `eindom D (E:A->A->bool) x yv` THEN REWRITE_TAC[eindom] THEN
      DISCH_THEN(X_CHOOSE_THEN `qx0:A` STRIP_ASSUME_TAC) THEN
      SUBGOAL_THEN `(E:A->A->bool) qx0 B` ASSUME_TAC THENL
       [MATCH_MP_TAC(ISPECL
                     [`D:A->bool`;`E:A->A->bool`;`B:A`;`x:A`;`yv:A`;`qx0:A`]
                     BNAME_APPLY_IN_B) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
      MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`yv:A`;`t:A`]
        EBV_IN_VAL_EXISTS) THEN ASM_REWRITE_TAC[] THEN
      DISCH_THEN(X_CHOOSE_THEN `zyt:A` STRIP_ASSUME_TAC) THEN
      MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`qx0:A`;`zyt:A`]
        EBALG_MEET) THEN ASM_REWRITE_TAC[] THEN
      DISCH_THEN(X_CHOOSE_TAC `mq:A`) THEN
      SUBGOAL_THEN `(mq:A) IN D /\ (E:A->A->bool) mq B` STRIP_ASSUME_TAC THENL
       [ASM_MESON_TAC[EMEET_IN]; ALL_TAC] THEN
      SUBGOAL_THEN `eapply D (E:A->A->bool) ft yv mq` ASSUME_TAC THENL
       [UNDISCH_TAC `!w q zwt m. w IN D /\ q IN D /\ zwt IN D /\ m IN D /\
                     eapply D (E:A->A->bool) x w q /\
                       ebv_in D E B leq w t zwt /\
                     emeet D E B leq q zwt m ==> eapply D E ft w m` THEN
        DISCH_THEN(MP_TAC o SPECL [`yv:A`;`qx0:A`;`zyt:A`;`mq:A`]) THEN
        ASM_REWRITE_TAC[]; ALL_TAC] THEN
      SUBGOAL_THEN `qyv:A = mq` SUBST_ALL_TAC THENL
       [MATCH_MP_TAC(ISPECL
                     [`D:A->bool`;`E:A->A->bool`;`ft:A`;`yv:A`;`qyv:A`;`mq:A`]
                     EAPPLY_UNIQUE) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
      SUBGOAL_THEN `eyu:A = zyt` SUBST_ALL_TAC THENL
       [MATCH_MP_TAC(ISPECL
                     [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`yv:A`;`t:A`;
                      `eyu:A`;`zyt:A`] EBV_IN_UNIQUE) THEN ASM_REWRITE_TAC[];
        ALL_TAC] THEN
      SUBGOAL_THEN `erel D (E:A->A->bool) leq mq zyt` ASSUME_TAC THENL
       [ASM_MESON_TAC[EMEET_LE]; ALL_TAC] THEN
      SUBGOAL_THEN `etop D (E:A->A->bool) B leq cv` ASSUME_TAC THENL
       [SUBGOAL_THEN `etop D (E:A->A->bool) B leq cv <=>
                      erel D (E:A->A->bool) leq mq zyt`
           (fun th -> ASM_REWRITE_TAC[th]) THEN
        MATCH_MP_TAC(ISPECL
                     [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`mq:A`;`zyt:A`;
                      `cv:A`] EBIMP_TOP) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
      MATCH_MP_TAC(ISPECL
                   [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`cv:A`;`ztx:A`]
                   ETOP_GE) THEN ASM_REWRITE_TAC[]];
    DISCH_THEN ACCEPT_TAC]);;

(* --------------------------------------------------------------------- *)
(* F5 POWER axiom:  [[ tt SUBSET x ]] <= [[ tt IN pn ]].                  *)
(* pn = power name of x (dom pn = FS, pn(f) = esubval x f).  Build the     *)
(* trace name ft of tt against x (ft = separation of x by "0 %% 1" at      *)
(* base valuation \i.tt, slot 0; so ft(w) = x(w) MEET [[w in tt]], dom ft  *)
(* = dom x, [[w in ft]] = [[w in x]] MEET [[w in tt]]).                     *)
(*   (A) ztx = [[tt SUBSET x]] <= [[ft SUBSET x]] = qf  (SUBSET_GE_OF_      *)
(*       SMALLER, since ft(w) <= x(w) pointwise).                           *)
(*   (B) ztx <= [[tt = ft]] = ey  (POW_GE_EQ, direction B).                 *)
(*   pn(ft) = qf (FS closure gives E ft FS, then pn-apply clause), so       *)
(*   EBV_IN_GE_TERM_V gives  qf MEET ey <= zin = [[tt IN pn]]; with         *)
(*   ztx <= qf and ztx <= ey, EMEET_GREATEST + trans give ztx <= zin.       *)
(* --------------------------------------------------------------------- *)

let EBV_IN_POW_GE = prove
 (`!D (E:A->A->bool) B leq x FS tt pn zin ztx.
      model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
      x IN D /\ bname D E B x /\ FS IN D /\
      tt IN D /\ bname D E B tt /\ pn IN D /\ eisfun D E pn /\
      (!f. f IN D /\ E f FS ==> bname D E B f) /\
      (!f q. f IN D /\ E f FS /\ esubval D E B leq x f q ==>
       eapply D E pn f q) /\
      (!f. f IN D ==> (eindom D E pn f <=> E f FS)) /\
      (!f. f IN D /\ bname D E B f /\ eisfun D E f /\
           (!w. w IN D ==> (eindom D E f w <=> eindom D E x w)) ==> E f FS) /\
      zin IN D /\ ztx IN D /\
      ebv_in D E B leq tt pn zin /\ esubval D E B leq x tt ztx
      ==> erel D E leq ztx zin`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `ebalg D (E:A->A->bool) B leq` ASSUME_TAC THENL
   [ASM_MESON_TAC[ECBA_IMP_BALG]; ALL_TAC] THEN
  SUBGOAL_THEN `eporder D (E:A->A->bool) B leq` ASSUME_TAC THENL
   [ASM_MESON_TAC[EBALG_IMP_PORDER]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) ztx B` ASSUME_TAC THENL
   [ASM_MESON_TAC[ESUBVAL_IN]; ALL_TAC] THEN
  (* base valuation facts *)
  SUBGOAL_THEN `valuation D (\i:num. tt:A)` ASSUME_TAC THENL
   [REWRITE_TAC[valuation] THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `!i:num. bname D (E:A->A->bool) B ((\i:num. tt:A) i)`
    ASSUME_TAC THENL
   [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* BVEQ : bvalf ((0|->w)(\i.tt)) (0%%1) = [[w in tt]] *)
  SUBGOAL_THEN
   `!w z. w IN D /\ z IN D /\ bname D (E:A->A->bool) B w /\
          ebv_in D E B leq w tt z
          ==> bvalf D E B leq ((0 |-> w) (\i:num. tt:A)) (0 %% 1) = z`
   (LABEL_TAC "bveq") THENL
   [REPEAT STRIP_TAC THEN
    SUBGOAL_THEN `valuation D ((0 |-> w) (\i:num. tt:A)) /\
                  (!i. bname D (E:A->A->bool) B
                   (((0 |-> w) (\i:num. tt:A)) i))`
    STRIP_ASSUME_TAC THENL
     [CONJ_TAC THENL
       [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[];
        MATCH_MP_TAC BNAMEVAL_VALMOD THEN ASM_REWRITE_TAC[]]; ALL_TAC] THEN
    SUBGOAL_THEN
     `(bvalf D (E:A->A->bool) B leq ((0 |-> w) (\i:num. tt:A)) (0 %% 1)) IN D`
      ASSUME_TAC THENL
     [MP_TAC(ISPECL [`0 %% 1`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
        `(0 |-> w) (\i:num. tt:A)`] BVALF_SPEC) THEN
      ASM_REWRITE_TAC[] THEN STRIP_TAC THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    MP_TAC(ISPECL [`0`;`1`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
      `(0 |-> w) (\i:num. tt:A)`] BVALF_MEM) THEN
    ASM_REWRITE_TAC[] THEN
    SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER; ARITH_EQ] THEN DISCH_TAC THEN
    MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`w:A`;`tt:A`;
      `bvalf D (E:A->A->bool) B leq ((0 |-> w) (\i:num. tt:A)) (0 %% 1)`;`z:A`]
      EBV_IN_UNIQUE) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* build the trace name ft = separation of x by (0%%1) at (\i.tt), slot 0 *)
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`(\i:num. tt:A)`;
    `0 %% 1`;`0`;`x:A`] ESEPNAME_EXISTS) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `ft:A` STRIP_ASSUME_TAC) THEN
  SUBGOAL_THEN `bname D (E:A->A->bool) B ft` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`(\i:num. tt:A)`;
                  `0 %% 1`;`0`;`x:A`;`ft:A`] ESEPNAME_BNAME) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* --- POW_GE_EQ char-hyp: member-char --- *)
  SUBGOAL_THEN
   `!w zwx zwt r. w IN D /\ zwx IN D /\ zwt IN D /\ r IN D /\
                  bname D (E:A->A->bool) B w /\
                  ebv_in D E B leq w x zwx /\ ebv_in D E B leq w tt zwt /\
                  emeet D E B leq zwx zwt r ==> ebv_in D E B leq w ft r`
   (LABEL_TAC "memchar") THENL
   [REPEAT STRIP_TAC THEN
    MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`w:A`;`ft:A`]
      EBV_IN_VAL_EXISTS) THEN ASM_REWRITE_TAC[] THEN
    DISCH_THEN(X_CHOOSE_THEN `zwf:A` STRIP_ASSUME_TAC) THEN
    SUBGOAL_THEN `emeet D (E:A->A->bool) B leq zwx
                    (bvalf D E B leq ((0 |-> w) (\i:num. tt:A)) (0 %% 1)) r`
      ASSUME_TAC THENL
     [SUBGOAL_THEN
        `bvalf D (E:A->A->bool) B leq ((0 |-> w) (\i:num. tt:A))
         (0 %% 1) = zwt`
        (fun th -> REWRITE_TAC[th]) THENL
       [USE_THEN "bveq" MATCH_MP_TAC THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
      ASM_REWRITE_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN `(zwf:A) = r` SUBST_ALL_TAC THENL
     [MATCH_MP_TAC(ISPECL
                   [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`(\i:num. tt:A)`;
                    `0 %% 1`;`0`;`x:A`;`w:A`;`ft:A`;`zwf:A`;`zwx:A`;`r:A`]
                     EBV_IN_SEP) THEN
      ASM_REWRITE_TAC[];
      ASM_REWRITE_TAC[]]; ALL_TAC] THEN
  (* --- POW_GE_EQ char-hyp: apply-char --- *)
  SUBGOAL_THEN
   `!w q zwt m. w IN D /\ q IN D /\ zwt IN D /\ m IN D /\
                eapply D (E:A->A->bool) x w q /\ ebv_in D E B leq w tt zwt /\
                emeet D E B leq q zwt m ==> eapply D E ft w m`
   (LABEL_TAC "applychar") THENL
   [REPEAT STRIP_TAC THEN
    SUBGOAL_THEN `eindom D (E:A->A->bool) x w` ASSUME_TAC THENL
     [REWRITE_TAC[eindom] THEN EXISTS_TAC `q:A` THEN ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    SUBGOAL_THEN `bname D (E:A->A->bool) B w` ASSUME_TAC THENL
     [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`x:A`;`w:A`]
        UNION_DOM_BNAME) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN `emeet D (E:A->A->bool) B leq q
                    (bvalf D E B leq ((0 |-> w) (\i:num. tt:A)) (0 %% 1)) m`
      ASSUME_TAC THENL
     [SUBGOAL_THEN
        `bvalf D (E:A->A->bool) B leq ((0 |-> w) (\i:num. tt:A))
         (0 %% 1) = zwt`
        (fun th -> REWRITE_TAC[th]) THENL
       [USE_THEN "bveq" MATCH_MP_TAC THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
      ASM_REWRITE_TAC[]; ALL_TAC] THEN
    UNDISCH_TAC `!w q m. w IN D /\ q IN D /\ eindom D (E:A->A->bool) x w /\
                    eapply D E x w q /\
                    emeet D E B leq q
                      (bvalf D E B leq ((0 |-> w) (\i:num. tt:A)) (0 %% 1)) m
                    ==> eapply D E ft w m` THEN
    DISCH_THEN(MP_TAC o SPECL [`w:A`;`q:A`;`m:A`]) THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  (* ey = [[tt = ft]] *)
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`tt:A`;`ft:A`]
    EBV_EQ_VAL_EXISTS) THEN ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `ey:A` STRIP_ASSUME_TAC) THEN
  (* direction (B): ztx <= ey *)
  SUBGOAL_THEN `erel D (E:A->A->bool) leq ztx ey` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`x:A`;`tt:A`;
      `ft:A`;`ztx:A`;`ey:A`] POW_GE_EQ) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* qf = [[ft SUBSET x]] *)
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`x:A`;`ft:A`]
    ESUBVAL_EXISTS) THEN ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_TAC `qf:A`) THEN
  SUBGOAL_THEN `(qf:A) IN D /\ (E:A->A->bool) qf B` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[ESUBVAL_IN]; ALL_TAC] THEN
  (* direction (A): ztx <= qf via SUBSET_GE_OF_SMALLER *)
  SUBGOAL_THEN `erel D (E:A->A->bool) leq ztx qf` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`x:A`;`ft:A`;
      `ztx:A`;`qf:A`] SUBSET_GE_OF_SMALLER) THEN
    ASM_REWRITE_TAC[] THEN
    (* pointwise smaller: ft(w) <= x(w) *)
    MAP_EVERY X_GEN_TAC [`w:A`;`qw:A`] THEN STRIP_TAC THEN
    SUBGOAL_THEN `eindom D (E:A->A->bool) ft w` ASSUME_TAC THENL
     [REWRITE_TAC[eindom] THEN EXISTS_TAC `qw:A` THEN ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    SUBGOAL_THEN `eindom D (E:A->A->bool) x w` ASSUME_TAC THENL
     [UNDISCH_TAC `!w. w IN D
                       ==> (eindom D (E:A->A->bool) ft w <=>
                            eindom D E x w)` THEN
      DISCH_THEN(MP_TAC o SPEC `w:A`) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    UNDISCH_TAC `eindom D (E:A->A->bool) x w` THEN REWRITE_TAC[eindom] THEN
    DISCH_THEN(X_CHOOSE_THEN `qx0:A` STRIP_ASSUME_TAC) THEN
    SUBGOAL_THEN `(E:A->A->bool) qx0 B` ASSUME_TAC THENL
     [MATCH_MP_TAC(ISPECL
                   [`D:A->bool`;`E:A->A->bool`;`B:A`;`x:A`;`w:A`;`qx0:A`]
                   BNAME_APPLY_IN_B) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`w:A`;`tt:A`]
      EBV_IN_VAL_EXISTS) THEN ASM_REWRITE_TAC[] THEN
    DISCH_THEN(X_CHOOSE_THEN `zwt:A` STRIP_ASSUME_TAC) THEN
    MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`qx0:A`;`zwt:A`]
      EBALG_MEET) THEN ASM_REWRITE_TAC[] THEN
    DISCH_THEN(X_CHOOSE_TAC `mq:A`) THEN
    SUBGOAL_THEN `(mq:A) IN D /\ (E:A->A->bool) mq B` STRIP_ASSUME_TAC THENL
     [ASM_MESON_TAC[EMEET_IN]; ALL_TAC] THEN
    SUBGOAL_THEN `eapply D (E:A->A->bool) ft w mq` ASSUME_TAC THENL
     [USE_THEN "applychar" (fun th -> MATCH_MP_TAC th) THEN
      MAP_EVERY EXISTS_TAC [`qx0:A`;`zwt:A`] THEN ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    SUBGOAL_THEN `qw:A = mq` SUBST_ALL_TAC THENL
     [MATCH_MP_TAC(ISPECL
                   [`D:A->bool`;`E:A->A->bool`;`ft:A`;`w:A`;`qw:A`;`mq:A`]
                   EAPPLY_UNIQUE) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    EXISTS_TAC `qx0:A` THEN ASM_REWRITE_TAC[] THEN
    ASM_MESON_TAC[EMEET_LE]; ALL_TAC] THEN
  (* pn(ft) = qf *)
  SUBGOAL_THEN `(E:A->A->bool) ft FS` ASSUME_TAC THENL
   [UNDISCH_TAC `!f. f IN D /\ bname D (E:A->A->bool) B f /\ eisfun D E f /\
                     (!w. w IN D ==> (eindom D E f w <=> eindom D E x w))
                     ==> E f FS` THEN
    DISCH_THEN(MATCH_MP_TAC o SPEC `ft:A`) THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `eapply D (E:A->A->bool) pn ft qf` ASSUME_TAC THENL
   [UNDISCH_TAC `!f q. f IN D /\ (E:A->A->bool) f FS /\ esubval D E B leq x f q
                       ==> eapply D E pn f q` THEN
    DISCH_THEN(MP_TAC o SPECL [`ft:A`;`qf:A`]) THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  (* c = qf MEET ey, then EBV_IN_GE_TERM_V gives c <= zin *)
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`qf:A`;`ey:A`]
    EBALG_MEET) THEN ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_TAC `c:A`) THEN
  SUBGOAL_THEN `(c:A) IN D /\ (E:A->A->bool) c B` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[EMEET_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq c zin` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`tt:A`;`pn:A`;
                  `zin:A`;`ft:A`;`qf:A`;`ey:A`;`c:A`] EBV_IN_GE_TERM_V) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* ztx <= c, then trans *)
  SUBGOAL_THEN `erel D (E:A->A->bool) leq ztx c` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`qf:A`;`ey:A`;
                  `c:A`;`ztx:A`] EMEET_GREATEST) THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) zin B` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`tt:A`;`pn:A`;
                  `zin:A`] EBV_IN_IN_B) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`ztx:A`;`c:A`;
    `zin:A`] EPORDER_TRANS) THEN ASM_REWRITE_TAC[]);;

(* --------------------------------------------------------------------- *)
(* F5 POWER axiom:  [[ t IN pn ]] = [[ t SUBSET x ]].                     *)
(* Combine EBV_IN_POW_LE (zin <= ztx) and EBV_IN_POW_GE (ztx <= zin)      *)
(* via EPORDER_ANTISYM.  Hypotheses = GE's (the superset; the extra       *)
(* FS-closure clause is unused by LE but harmless).                       *)
(* --------------------------------------------------------------------- *)

let EBV_IN_POW = prove
 (`!D (E:A->A->bool) B leq x FS tt pn zin ztx.
      model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
      x IN D /\ bname D E B x /\ FS IN D /\
      tt IN D /\ bname D E B tt /\ pn IN D /\ eisfun D E pn /\
      (!f. f IN D /\ E f FS ==> bname D E B f) /\
      (!f q. f IN D /\ E f FS /\ esubval D E B leq x f q ==>
       eapply D E pn f q) /\
      (!f. f IN D ==> (eindom D E pn f <=> E f FS)) /\
      (!f. f IN D /\ bname D E B f /\ eisfun D E f /\
           (!w. w IN D ==> (eindom D E f w <=> eindom D E x w)) ==> E f FS) /\
      zin IN D /\ ztx IN D /\
      ebv_in D E B leq tt pn zin /\ esubval D E B leq x tt ztx
      ==> zin = ztx`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `ebalg D (E:A->A->bool) B leq` ASSUME_TAC THENL
   [ASM_MESON_TAC[ECBA_IMP_BALG]; ALL_TAC] THEN
  SUBGOAL_THEN `eporder D (E:A->A->bool) B leq` ASSUME_TAC THENL
   [ASM_MESON_TAC[EBALG_IMP_PORDER]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) ztx B` ASSUME_TAC THENL
   [ASM_MESON_TAC[ESUBVAL_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) zin B` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`tt:A`;`pn:A`;
                  `zin:A`] EBV_IN_IN_B) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MATCH_MP_TAC(ISPECL
               [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`zin:A`;`ztx:A`]
               EPORDER_ANTISYM) THEN
  ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`x:A`;`FS:A`;
      `tt:A`;`pn:A`;`zin:A`;`ztx:A`] EBV_IN_POW_LE) THEN ASM_REWRITE_TAC[];
    MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`x:A`;`FS:A`;
      `tt:A`;`pn:A`;`zin:A`;`ztx:A`] EBV_IN_POW_GE) THEN ASM_REWRITE_TAC[]]);;

(* --------------------------------------------------------------------- *)
(* POWER axiom: the RHS bridge.                                           *)
(*   [[ !!- 3 2 (3 %% 0) ]]_vv  =  esubval xx tt   (= [[ tt SUBSET xx ]]) *)
(* when vv 2 = tt, vv 0 = xx.  !!- 3 2 (3%%0) = !!3 ((3%%2)-->(3%%0)),     *)
(* whose value is the GLB over bnames c of ([[c IN tt]] IMP [[c IN xx]]), *)
(* which ESUBVAL_EQ_SUBSETVAL identifies with esubval xx tt.              *)
(* --------------------------------------------------------------------- *)

let POW_RHS_SUBVAL = prove
 (`!D (E:A->A->bool) B leq vv xx tt zr.
      model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
      valuation D vv /\ (!i. bname D E B (vv i)) /\
      vv 2 = tt /\ vv 0 = xx /\
      xx IN D /\ bname D E B xx /\ tt IN D /\ bname D E B tt /\
      esubval D E B leq xx tt zr /\ zr IN D
      ==> bvalf D E B leq vv (!!- 3 2 (3 %% 0)) = zr`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `ebalg D (E:A->A->bool) B leq` ASSUME_TAC THENL
   [ASM_MESON_TAC[ECBA_IMP_BALG]; ALL_TAC] THEN
  SUBGOAL_THEN `eporder D (E:A->A->bool) B leq` ASSUME_TAC THENL
   [ASM_MESON_TAC[EBALG_IMP_PORDER]; ALL_TAC] THEN
  REWRITE_TAC[Forallmem_DEF] THEN
  SUBGOAL_THEN
   `bvalf D (E:A->A->bool) B leq vv (!! 3 ((3 %% 2) --> (3 %% 0))) IN D /\
    (E:A->A->bool) (bvalf D E B leq vv (!! 3 ((3 %% 2) --> (3 %% 0)))) B`
  STRIP_ASSUME_TAC THENL
   [CONJ_TAC THENL
     [MP_TAC(ISPECL [`!! 3 ((3 %% 2) --> (3 %% 0))`;`D:A->bool`;`E:A->A->bool`;
        `B:A`;`leq:A`;`vv:num->A`] BVALF_SPEC) THEN ASM_SIMP_TAC[];
      MP_TAC(ISPECL [`!! 3 ((3 %% 2) --> (3 %% 0))`;`D:A->bool`;`E:A->A->bool`;
        `B:A`;`leq:A`;`vv:num->A`] BVALF_IN_B) THEN ASM_SIMP_TAC[]];
    ALL_TAC] THEN
  (* per-bname body-value characterization used by both GLB directions *)
  SUBGOAL_THEN
   `!c zwf zwx ii.
        c IN D /\ bname D E B c /\ zwf IN D /\ zwx IN D /\ ii IN D /\
        ebv_in D E B leq c tt zwf /\ ebv_in D E B leq c xx zwx /\
        ebimp D E B leq zwf zwx ii
        ==> bvalf D (E:A->A->bool) B leq ((3 |-> c) vv)
          ((3 %% 2) --> (3 %% 0)) = ii`
  (LABEL_TAC "body") THENL
   [REPEAT GEN_TAC THEN STRIP_TAC THEN
    SUBGOAL_THEN `valuation D ((3 |-> (c:A)) (vv:num->A)) /\
                  (!i. bname D E B (((3 |-> (c:A)) (vv:num->A)) i))`
    STRIP_ASSUME_TAC THENL
     [CONJ_TAC THENL
       [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[];
        MATCH_MP_TAC BNAMEVAL_VALMOD THEN ASM_REWRITE_TAC[]]; ALL_TAC] THEN
    SUBGOAL_THEN `((3 |-> (c:A)) (vv:num->A)) 3 = c /\
                  ((3 |-> (c:A)) (vv:num->A)) 2 = tt /\
                  ((3 |-> (c:A)) (vv:num->A)) 0 = xx`
    STRIP_ASSUME_TAC THENL
     [ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER; ARITH_EQ]; ALL_TAC] THEN
    SUBGOAL_THEN `(E:A->A->bool) zwf B` ASSUME_TAC THENL
     [MATCH_MP_TAC(ISPECL
                   [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`c:A`;`tt:A`;
                    `zwf:A`] EBV_IN_IN_B) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN
      `bvalf D (E:A->A->bool) B leq ((3 |-> (c:A)) (vv:num->A))
       (3 %% 2) IN D /\
       bvalf D (E:A->A->bool) B leq ((3 |-> (c:A)) (vv:num->A)) (3 %% 0) IN D`
    STRIP_ASSUME_TAC THENL
     [CONJ_TAC THENL
       [MP_TAC(ISPECL [`(3:num) %% 2`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
          `(3 |-> (c:A)) (vv:num->A)`] BVALF_SPEC) THEN ASM_SIMP_TAC[];
        MP_TAC(ISPECL [`(3:num) %% 0`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
          `(3 |-> (c:A)) (vv:num->A)`] BVALF_SPEC) THEN ASM_SIMP_TAC[]];
      ALL_TAC] THEN
    SUBGOAL_THEN
      `ebv_in D (E:A->A->bool) B leq c tt
          (bvalf D E B leq ((3 |-> (c:A)) (vv:num->A)) (3 %% 2)) /\
       ebv_in D (E:A->A->bool) B leq c xx
          (bvalf D E B leq ((3 |-> (c:A)) (vv:num->A)) (3 %% 0))`
    STRIP_ASSUME_TAC THENL
     [CONJ_TAC THENL
       [MP_TAC(ISPECL [`3`;`2`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
          `(3 |-> (c:A)) (vv:num->A)`] BVALF_MEM) THEN ASM_REWRITE_TAC[];
        MP_TAC(ISPECL [`3`;`0`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
          `(3 |-> (c:A)) (vv:num->A)`] BVALF_MEM) THEN ASM_REWRITE_TAC[]];
      ALL_TAC] THEN
    SUBGOAL_THEN
      `bvalf D (E:A->A->bool) B leq ((3 |-> (c:A)) (vv:num->A))
       (3 %% 2) = zwf /\
       bvalf D (E:A->A->bool) B leq ((3 |-> (c:A)) (vv:num->A)) (3 %% 0) = zwx`
    STRIP_ASSUME_TAC THENL
     [CONJ_TAC THENL
       [MATCH_MP_TAC(ISPECL
                     [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`c:A`;`tt:A`;
                      `bvalf D (E:A->A->bool) B leq
                       ((3 |-> (c:A)) (vv:num->A)) (3 %% 2)`;
          `zwf:A`] EBV_IN_UNIQUE) THEN ASM_REWRITE_TAC[];
        MATCH_MP_TAC(ISPECL
                     [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`c:A`;`xx:A`;
                      `bvalf D (E:A->A->bool) B leq
                       ((3 |-> (c:A)) (vv:num->A)) (3 %% 0)`;
          `zwx:A`] EBV_IN_UNIQUE) THEN ASM_REWRITE_TAC[]];
      ALL_TAC] THEN
    MP_TAC(ISPECL
           [`(3:num) %% 2`;`(3:num) %% 0`;`D:A->bool`;`E:A->A->bool`;`B:A`;
            `leq:A`;`(3 |-> (c:A)) (vv:num->A)`] BVALF_IMP) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    ASM_REWRITE_TAC[] THEN DISCH_TAC THEN
    MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`zwf:A`;`zwx:A`;
                  `bvalf D (E:A->A->bool) B leq ((3 |-> (c:A)) (vv:num->A))
             ((3 %% 2) --> (3 %% 0))`;
      `ii:A`] EBIMP_UNIQUE) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  (* reduce to ESUBVAL_EQ_SUBSETVAL with candidate = the RHS bvalf *)
  CONV_TAC SYM_CONV THEN
  MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`xx:A`;`tt:A`;
    `zr:A`;
    `bvalf D (E:A->A->bool) B leq vv (!! 3 ((3 %% 2) --> (3 %% 0)))`]
    ESUBVAL_EQ_SUBSETVAL) THEN
  ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
   [(* lower-bound clause: RHS <= each combiner *)
    MAP_EVERY X_GEN_TAC [`w:A`;`zwf:A`;`zwx:A`;`ii:A`] THEN STRIP_TAC THEN
    SUBGOAL_THEN
      `bvalf D (E:A->A->bool) B leq ((3 |-> (w:A)) (vv:num->A))
             ((3 %% 2) --> (3 %% 0)) = ii`
    ASSUME_TAC THENL
     [USE_THEN "body"
      (fun th -> MATCH_MP_TAC(SPECL [`w:A`;`zwf:A`;`zwx:A`;`ii:A`] th)) THEN
      ASM_REWRITE_TAC[]; ALL_TAC] THEN
    MP_TAC(ISPECL
           [`3`;`(3 %% 2) --> (3 %% 0)`;`D:A->bool`;`E:A->A->bool`;`B:A`;
            `leq:A`;`vv:num->A`;`w:A`] BVALF_ALL_LB) THEN
    ASM_REWRITE_TAC[];
    (* greatest clause: any common lower bound <= RHS *)
    X_GEN_TAC `lb:A` THEN
    DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC (CONJUNCTS_THEN2 ASSUME_TAC
      (LABEL_TAC "lbh"))) THEN
    MATCH_MP_TAC(ISPECL
                 [`3`;`(3 %% 2) --> (3 %% 0)`;`D:A->bool`;`E:A->A->bool`;
                  `B:A`;`leq:A`;`vv:num->A`;`lb:A`] BVALF_ALL_GLB) THEN
    ASM_REWRITE_TAC[] THEN
    X_GEN_TAC `c:A` THEN STRIP_TAC THEN
    MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`c:A`;`tt:A`]
      EBV_IN_VAL_EXISTS) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(X_CHOOSE_THEN `zwf:A` STRIP_ASSUME_TAC) THEN
    MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`c:A`;`xx:A`]
      EBV_IN_VAL_EXISTS) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(X_CHOOSE_THEN `zwx:A` STRIP_ASSUME_TAC) THEN
    MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`zwf:A`;`zwx:A`]
      EBIMP_EXISTS) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(X_CHOOSE_TAC `ii:A`) THEN
    SUBGOAL_THEN `(ii:A) IN D /\ (E:A->A->bool) ii B` STRIP_ASSUME_TAC THENL
     [ASM_MESON_TAC[EBIMP_IN]; ALL_TAC] THEN
    SUBGOAL_THEN
      `bvalf D (E:A->A->bool) B leq ((3 |-> (c:A)) (vv:num->A))
             ((3 %% 2) --> (3 %% 0)) = ii`
    ASSUME_TAC THENL
     [USE_THEN "body"
      (fun th -> MATCH_MP_TAC(SPECL [`c:A`;`zwf:A`;`zwx:A`;`ii:A`] th)) THEN
      ASM_REWRITE_TAC[]; ALL_TAC] THEN
    ASM_REWRITE_TAC[] THEN
    USE_THEN "lbh"
      (fun th -> MATCH_MP_TAC(SPECL [`c:A`;`zwf:A`;`zwx:A`;`ii:A`] th)) THEN
      ASM_REWRITE_TAC[]]);;

(* --------------------------------------------------------------------- *)
(* V^B POWER axiom:  [[ powerset_ax ]]_v = TOP for every v.               *)
(*   powerset_ax = !!0 (??1 (!!2 ((2%%1) <-> !!- 3 2 (3%%0))))            *)
(* FS := xx's OWN bname stage ya_x (no successor).  pn = power name over  *)
(* FS.  LHS [[tt IN pn]] = esubval xx tt  (EBV_IN_POW);  RHS             *)
(* [[!!- 3 2 (3%%0)]] = esubval xx tt  (POW_RHS_SUBVAL);  combine.        *)
(* --------------------------------------------------------------------- *)

let BVALF_POWERSET = prove
 (`!D (E:A->A->bool) B leq v.
      model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
      valuation D v /\ (!i. bname D E B (v i))
      ==> etop D E B leq (bvalf D E B leq v powerset_ax)`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `eporder D (E:A->A->bool) B leq` ASSUME_TAC THENL
   [ASM_MESON_TAC[ECBA_IMP_BALG; EBALG_IMP_PORDER]; ALL_TAC] THEN
  REWRITE_TAC[powerset_ax] THEN
  (* peel !!0 -> xx *)
  MP_TAC(ISPECL [`0`; `?? 1 (!! 2 ((2 %% 1) <-> !!- 3 2 (3 %% 0)))`;
    `D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`v:num->A`] BVALF_ALL_TOP) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  X_GEN_TAC `xx:A` THEN STRIP_TAC THEN
  SUBGOAL_THEN `valuation D ((0 |-> (xx:A)) (v:num->A)) /\
                (!i. bname D E B (((0 |-> (xx:A)) (v:num->A)) i))`
  STRIP_ASSUME_TAC THENL
   [CONJ_TAC THENL
     [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[];
      MATCH_MP_TAC BNAMEVAL_VALMOD THEN ASM_REWRITE_TAC[]]; ALL_TAC] THEN
  ABBREV_TAC `v0 = (0 |-> (xx:A)) (v:num->A)` THEN
  (* ---- FS := xx's OWN bname stage ya_x ---- *)
  FIRST_ASSUM(X_CHOOSE_THEN `ax:A` (X_CHOOSE_THEN `yax:A` STRIP_ASSUME_TAC) o
    REWRITE_RULE[bname]) THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`ax:A`;`yax:A`]
         EBNSTAGE_CHAR) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `W:A` (CONJUNCTS_THEN2 ASSUME_TAC
    (CONJUNCTS_THEN2 (LABEL_TAC "Wch") ASSUME_TAC))) THEN
  (* clause 1: E f yax ==> bname f *)
  SUBGOAL_THEN `!f:A. f IN D /\ E f yax ==> bname D E B f`
    (LABEL_TAC "cl1") THENL
   [REPEAT STRIP_TAC THEN
    MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`ax:A`;`yax:A`;`f:A`]
      BNAME_STAGE) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* ebnmem B W xx and dom xx SUBSET W *)
  SUBGOAL_THEN `ebnmem D (E:A->A->bool) B W xx` ASSUME_TAC THENL
   [UNDISCH_TAC `ebnfuns D (E:A->A->bool) B W yax` THEN
    REWRITE_TAC[ebnfuns] THEN
    DISCH_THEN(MP_TAC o SPEC `xx:A` o CONJUNCT2) THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `?crx. crx IN D /\ ecross D (E:A->A->bool) W B crx /\
                      esubset D E xx crx`
  STRIP_ASSUME_TAC THENL
   [UNDISCH_TAC `ebnmem D (E:A->A->bool) B W xx` THEN REWRITE_TAC[ebnmem] THEN
    MESON_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `!u:A. u IN D /\ eindom D (E:A->A->bool) xx u ==> E u W`
  (LABEL_TAC "domxxW") THENL
   [X_GEN_TAC `u:A` THEN STRIP_TAC THEN
    UNDISCH_TAC `eindom D (E:A->A->bool) xx u` THEN
    REWRITE_TAC[eindom; eapply] THEN
    DISCH_THEN(X_CHOOSE_THEN `vu:A` (CONJUNCTS_THEN2 ASSUME_TAC
      (X_CHOOSE_THEN `zu:A` STRIP_ASSUME_TAC))) THEN
    SUBGOAL_THEN `(zu:A) IN D` ASSUME_TAC THENL
     [ASM_MESON_TAC[EOPAIR_IN]; ALL_TAC] THEN
    SUBGOAL_THEN `(E:A->A->bool) zu crx` ASSUME_TAC THENL
     [UNDISCH_TAC `esubset D (E:A->A->bool) xx crx` THEN
      REWRITE_TAC[esubset] THEN
      DISCH_THEN(MP_TAC o SPEC `zu:A`) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`W:A`;`B:A`;`crx:A`;`zu:A`]
      ECROSS_MEMBER) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    ASM_REWRITE_TAC[] THEN
    DISCH_THEN(X_CHOOSE_THEN `u2:A`
               (X_CHOOSE_THEN `w2:A` STRIP_ASSUME_TAC)) THEN
    SUBGOAL_THEN `(u:A) = u2` ASSUME_TAC THENL
     [MP_TAC(ISPECL
             [`D:A->bool`;`E:A->A->bool`;`u:A`;`vu:A`;`u2:A`;`w2:A`;`zu:A`]
             EOPAIR_INJ) THEN ASM_REWRITE_TAC[] THEN SIMP_TAC[]; ALL_TAC] THEN
    ASM_MESON_TAC[]; ALL_TAC] THEN
  (* clause 4: functional bname f with dom f = dom xx  ==>  E f yax *)
  SUBGOAL_THEN
    `!f:A. f IN D /\ bname D E B f /\ eisfun D E f /\
           (!w. w IN D ==> (eindom D E f w <=> eindom D E xx w)) ==> E f yax`
  (LABEL_TAC "cl4") THENL
   [X_GEN_TAC `f:A` THEN
    INTRO_TAC "fD bnf funf domeq" THEN
    SUBGOAL_THEN `ebnmem D (E:A->A->bool) B W f` MP_TAC THENL
     [REWRITE_TAC[ebnmem] THEN ASM_REWRITE_TAC[] THEN
      MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`W:A`;`B:A`]
             ECROSS_EXISTS) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(X_CHOOSE_THEN `crf:A` ASSUME_TAC) THEN
      SUBGOAL_THEN `(crf:A) IN D` ASSUME_TAC THENL
       [ASM_MESON_TAC[ecross]; ALL_TAC] THEN
      EXISTS_TAC `crf:A` THEN ASM_REWRITE_TAC[] THEN
      REWRITE_TAC[esubset] THEN X_GEN_TAC `z:A` THEN STRIP_TAC THEN
      MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`f:A`;`z:A`]
        BNAME_MEM_PAIR) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(X_CHOOSE_THEN `w:A`
                 (X_CHOOSE_THEN `q:A` STRIP_ASSUME_TAC)) THEN
      SUBGOAL_THEN `eindom D (E:A->A->bool) f w` ASSUME_TAC THENL
       [REWRITE_TAC[eindom; eapply] THEN EXISTS_TAC `q:A` THEN
        ASM_REWRITE_TAC[] THEN EXISTS_TAC `z:A` THEN ASM_REWRITE_TAC[];
        ALL_TAC] THEN
      SUBGOAL_THEN `eindom D (E:A->A->bool) xx w` ASSUME_TAC THENL
       [REMOVE_THEN "domeq" (MP_TAC o SPEC `w:A`) THEN ASM_REWRITE_TAC[];
        ALL_TAC] THEN
      SUBGOAL_THEN `(E:A->A->bool) w W` ASSUME_TAC THENL
       [USE_THEN "domxxW" MATCH_MP_TAC THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
      MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`W:A`;`B:A`;`crf:A`;`z:A`]
        ECROSS_MEMBER) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
      MAP_EVERY EXISTS_TAC [`w:A`;`q:A`] THEN ASM_REWRITE_TAC[];
      DISCH_TAC THEN
      UNDISCH_TAC `ebnfuns D (E:A->A->bool) B W yax` THEN
      REWRITE_TAC[ebnfuns] THEN
      DISCH_THEN(MP_TAC o SPEC `f:A` o CONJUNCT2) THEN ASM_REWRITE_TAC[]];
    ALL_TAC] THEN
  (* build the power name pn over FS = yax *)
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`xx:A`;`yax:A`]
    EPOWERNAME_EXISTS) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `pn:A` STRIP_ASSUME_TAC) THEN
  SUBGOAL_THEN `bname D (E:A->A->bool) B pn` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`xx:A`;`yax:A`;
                  `ax:A`;`yax:A`;`pn:A`] EPOWERNAME_BNAME) THEN
    ASM_REWRITE_TAC[] THEN MESON_TAC[]; ALL_TAC] THEN
  (* clause 3: eindom pn f <=> E f yax *)
  SUBGOAL_THEN `!f:A. f IN D ==> (eindom D (E:A->A->bool) pn f <=> E f yax)`
  (LABEL_TAC "cl3") THENL
   [UNDISCH_TAC `edomain D (E:A->A->bool) pn yax` THEN
    REWRITE_TAC[edomain] THEN
    MESON_TAC[]; ALL_TAC] THEN
  (* witness pn for ??1 *)
  MATCH_MP_TAC(ISPECL [`1`; `!! 2 ((2 %% 1) <-> !!- 3 2 (3 %% 0))`;
    `D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`v0:num->A`;`pn:A`]
      BVALF_EX_TOP) THEN
  ASM_REWRITE_TAC[] THEN
  SUBGOAL_THEN `valuation D ((1 |-> (pn:A)) (v0:num->A)) /\
                (!i. bname D E B (((1 |-> (pn:A)) (v0:num->A)) i))`
  STRIP_ASSUME_TAC THENL
   [CONJ_TAC THENL
     [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[];
      MATCH_MP_TAC BNAMEVAL_VALMOD THEN ASM_REWRITE_TAC[]]; ALL_TAC] THEN
  ABBREV_TAC `v1 = (1 |-> (pn:A)) (v0:num->A)` THEN
  (* peel !!2 -> tt *)
  MP_TAC(ISPECL [`2`; `(2 %% 1) <-> !!- 3 2 (3 %% 0)`;
    `D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`v1:num->A`] BVALF_ALL_TOP) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  X_GEN_TAC `tt:A` THEN STRIP_TAC THEN
  SUBGOAL_THEN `valuation D ((2 |-> (tt:A)) (v1:num->A)) /\
                (!i. bname D E B (((2 |-> (tt:A)) (v1:num->A)) i))`
  STRIP_ASSUME_TAC THENL
   [CONJ_TAC THENL
     [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[];
      MATCH_MP_TAC BNAMEVAL_VALMOD THEN ASM_REWRITE_TAC[]]; ALL_TAC] THEN
  ABBREV_TAC `vv = (2 |-> (tt:A)) (v1:num->A)` THEN
  SUBGOAL_THEN `(vv:num->A) 0 = xx /\ (vv:num->A) 1 = pn /\ (vv:num->A) 2 = tt`
  STRIP_ASSUME_TAC THENL
   [MAP_EVERY EXPAND_TAC ["vv";"v1";"v0"] THEN
    SIMP_TAC[VALMOD_OTHER; VALMOD_BASIC; ARITH_EQ]; ALL_TAC] THEN
  (* IFF_TOP -> value-equality *)
  MP_TAC(ISPECL [`2 %% 1`; `!!- 3 2 (3 %% 0)`;
    `D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`vv:num->A`] BVALF_IFF_TOP) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  (* ztx = esubval xx tt *)
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`xx:A`;`tt:A`]
    ESUBVAL_EXISTS) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_TAC `ztx:A`) THEN
  SUBGOAL_THEN `(ztx:A) IN D /\ (E:A->A->bool) ztx B` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[ESUBVAL_IN]; ALL_TAC] THEN
  (* RHS = ztx via POW_RHS_SUBVAL *)
  SUBGOAL_THEN `bvalf D (E:A->A->bool) B leq vv (!!- 3 2 (3 %% 0)) = ztx`
  SUBST1_TAC THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`vv:num->A`;
      `xx:A`;`tt:A`;`ztx:A`] POW_RHS_SUBVAL) THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  (* LHS: zin = [[tt IN pn]] *)
  ABBREV_TAC `zin = bvalf D (E:A->A->bool) B leq (vv:num->A) (2 %% 1)` THEN
  SUBGOAL_THEN `ebv_in D (E:A->A->bool) B leq tt pn zin` ASSUME_TAC THENL
   [EXPAND_TAC "zin" THEN
    MP_TAC(ISPECL
           [`2`;`1`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`vv:num->A`]
           BVALF_MEM) THEN ASM_SIMP_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(zin:A) IN D` ASSUME_TAC THENL
   [EXPAND_TAC "zin" THEN
    MP_TAC(ISPECL
           [`2 %% 1`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`vv:num->A`]
           BVALF_SPEC) THEN ASM_SIMP_TAC[]; ALL_TAC] THEN
  (* EBV_IN_POW: zin = ztx *)
  MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`xx:A`;`yax:A`;
    `tt:A`;`pn:A`;`zin:A`;`ztx:A`] EBV_IN_POW) THEN
  ASM_REWRITE_TAC[]);;

(* ===================================================================== *)
(* Bounded-quantifier Boolean-value bounds (toward V^B replacement).     *)
(* Values of  ??- x a p = ?? x (x%%a && p)  and  !!- x a p =             *)
(* !! x (x%%a --> p): a witness/instance contributes a bound; a common   *)
(* bound over all B-names bounds the quantified value.  These feed the   *)
(* collection step of replacement (image bounded via separation).        *)
(* ===================================================================== *)

(* [[x%%a]]_{x:=ss} MEET [[p]]_{x:=ss}  <=  [[ ??- x a p ]]_v            *)
let EBVALF_EXMEM_GE = prove
 (`!D (E:A->A->bool) B leq v x a p ss m.
      model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
      valuation D v /\ (!i. bname D E B (v i)) /\
      ~(a = x) /\ ss IN D /\ bname D E B ss /\
      emeet D E B leq (bvalf D E B leq ((x |-> ss) v) (x %% a))
                      (bvalf D E B leq ((x |-> ss) v) p) m
      ==> erel D E leq m (bvalf D E B leq v (??- x a p))`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `valuation D ((x |-> ss)(v:num->A)) /\
                (!i. bname D E B (((x |-> ss)(v:num->A)) i))`
    STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[VALUATION_VALMOD; BNAMEVAL_VALMOD]; ALL_TAC] THEN
  SUBGOAL_THEN `bvalf D (E:A->A->bool) B leq ((x |-> ss) v) (x %% a && p) = m`
    ASSUME_TAC THENL
   [MP_TAC(ISPECL
           [`x %% a`; `p:form`; `D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
           `(x |-> ss)(v:num->A)`] BVALF_AND_MEET) THEN
    ASM_REWRITE_TAC[] THEN DISCH_TAC THEN
    MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
                  `bvalf D (E:A->A->bool) B leq ((x |-> ss) v) (x %% a)`;
                  `bvalf D (E:A->A->bool) B leq ((x |-> ss) v) p`;
                  `bvalf D (E:A->A->bool) B leq ((x |-> ss) v) (x %% a && p)`;
                  `m:A`] EMEET_UNIQUE) THEN
    ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[ECBA_IMP_PORDER];
    ALL_TAC] THEN
  REWRITE_TAC[Existsmem_DEF] THEN
  MP_TAC(ISPECL [`x:num`; `x %% a && p`; `D:A->bool`;`E:A->A->bool`;
                 `B:A`;`leq:A`;`v:num->A`;`ss:A`] BVALF_EX_UB) THEN
  ASM_REWRITE_TAC[]);;

(* if w0 bounds [[x%%a]]_{x:=ss} MEET [[p]]_{x:=ss} for every B-name ss,  *)
(* then [[ ??- x a p ]]_v <= w0.                                         *)
let EBVALF_EXMEM_LE = prove
 (`!D (E:A->A->bool) B leq v x a p w0.
      model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
      valuation D v /\ (!i. bname D E B (v i)) /\
      ~(a = x) /\ w0 IN D /\ E w0 B /\
      (!ss m. ss IN D /\ bname D E B ss /\
              emeet D E B leq (bvalf D E B leq ((x |-> ss) v) (x %% a))
                              (bvalf D E B leq ((x |-> ss) v) p) m
              ==> erel D E leq m w0)
      ==> erel D E leq (bvalf D E B leq v (??- x a p)) w0`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  REWRITE_TAC[Existsmem_DEF] THEN
  MATCH_MP_TAC(ISPECL [`x:num`; `x %% a && p`; `D:A->bool`;`E:A->A->bool`;
                       `B:A`;`leq:A`;`v:num->A`;`w0:A`] BVALF_EX_LEAST) THEN
  ASM_REWRITE_TAC[] THEN
  X_GEN_TAC `ss:A` THEN STRIP_TAC THEN
  SUBGOAL_THEN `valuation D ((x |-> ss)(v:num->A)) /\
                (!i. bname D E B (((x |-> ss)(v:num->A)) i))`
    STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[VALUATION_VALMOD; BNAMEVAL_VALMOD]; ALL_TAC] THEN
  MP_TAC(ISPECL [`x %% a`; `p:form`; `D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
                 `(x |-> ss)(v:num->A)`] BVALF_AND_MEET) THEN
  ASM_REWRITE_TAC[] THEN DISCH_TAC THEN
  FIRST_X_ASSUM(MP_TAC o SPECL
    [`ss:A`; `bvalf D (E:A->A->bool) B leq ((x |-> ss) v) (x %% a && p)`]) THEN
  ASM_REWRITE_TAC[]);;

(* [[ !!- x a p ]]_v  <=  [[ x%%a --> p ]]_{x:=ss}  for any B-name ss.   *)
let EBVALF_ALLMEM_LE = prove
 (`!D (E:A->A->bool) B leq v x a p ss.
      model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
      valuation D v /\ (!i. bname D E B (v i)) /\
      ss IN D /\ bname D E B ss
      ==> erel D E leq (bvalf D E B leq v (!!- x a p))
                       (bvalf D E B leq ((x |-> ss) v) (x %% a --> p))`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  REWRITE_TAC[Forallmem_DEF] THEN
  MATCH_MP_TAC(ISPECL [`x:num`; `x %% a --> p`; `D:A->bool`;`E:A->A->bool`;
                       `B:A`;`leq:A`;`v:num->A`;`ss:A`] BVALF_ALL_LB) THEN
  ASM_REWRITE_TAC[]);;

(* if x0 <= [[ x%%a --> p ]]_{x:=ss} for every B-name ss, then           *)
(* x0 <= [[ !!- x a p ]]_v.                                              *)
let EBVALF_ALLMEM_GE = prove
 (`!D (E:A->A->bool) B leq v x a p x0.
      model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
      valuation D v /\ (!i. bname D E B (v i)) /\
      x0 IN D /\ E x0 B /\
      (!ss. ss IN D /\ bname D E B ss
            ==> erel D E leq x0
                  (bvalf D E B leq ((x |-> ss) v) (x %% a --> p)))
      ==> erel D E leq x0 (bvalf D E B leq v (!!- x a p))`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  REWRITE_TAC[Forallmem_DEF] THEN
  MATCH_MP_TAC(ISPECL [`x:num`; `x %% a --> p`; `D:A->bool`;`E:A->A->bool`;
                       `B:A`;`leq:A`;`v:num->A`;`x0:A`] BVALF_ALL_GLB) THEN
  ASM_REWRITE_TAC[]);;

(* ===================================================================== *)
(* F5 REPLACEMENT axiom: the constant-value "full name"                    *)
(* C = { <s, onebee> : s IN dd }.  A B-name whose extension is dd with     *)
(* every value equal to the fixed Boolean onebee (used with onebee = top   *)
(* to build the bounding name over a B-name stage W_lambda).  Existence     *)
(* + graph structure (EFULLNAME_EXISTS, via ZF_REPLACEMENT with formula     *)
(* opair_form 0 4 3), bname-hood under a staging bound (EFULLNAME_BNAME,     *)
(* mirror EPOWERNAME_BNAME), and the membership VALUE as a sup of equality  *)
(* values [[t IN C]] = sup_{s IN dd} [[t = s]] (EFULLNAME_IN_GE_ELT /        *)
(* EFULLNAME_IN_LE_SUP, mirror ECHECK_IN_GE_ELT / ECHECK_IN_LE_SUP).        *)
(* ===================================================================== *)

(* ===== EFULLNAME_EXISTS: constant-value name C = {<s,onebee> : s IN dd} =====
   A B-name whose graph is dd paired componentwise with the fixed value
   onebee.  Simpler variant of EPOWERNAME_EXISTS: no esubval layer, the value
   is the constant onebee and the replacement formula is opair_form 0 4 3
   (input var 0, param onebee = var 4, output var 3). *)
let EFULLNAME_EXISTS = prove
 (`!D (E:A->A->bool) onebee dd.
        model D E ZF_AX /\ onebee IN D /\ dd IN D
        ==> ?cn. cn IN D /\ eisfun D E cn /\ edomain D E cn dd /\
                 (!s. s IN D /\ E s dd ==> eapply D E cn s onebee) /\
                 (!z. z IN D
                      ==> (E z cn <=>
                           ?s. s IN D /\ E s dd /\
                               eopair D (E:A->A->bool) s onebee z))`,
  REPEAT GEN_TAC THEN
  DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC
    (CONJUNCTS_THEN2 ASSUME_TAC ASSUME_TAC)) THEN
  SUBGOAL_THEN `?v0:num->A. valuation D v0` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[VALUATION_EXISTS; MODEL_NONEMPTY]; ALL_TAC] THEN
  ABBREV_TAC `vP = (4 |-> (onebee:A)) v0` THEN
  SUBGOAL_THEN
   `valuation D (vP:num->A) /\ (vP:num->A) 4 = onebee`
  STRIP_ASSUME_TAC THENL
   [EXPAND_TAC "vP" THEN
    ASM_SIMP_TAC[VALUATION_VALMOD; VALMOD; ARITH_EQ]; ALL_TAC] THEN
  SUBGOAL_THEN
   `!el ot:A. el IN D /\ ot IN D
      ==> (holds D E ((3 |-> ot) ((0 |-> el) vP)) (opair_form 0 4 3) <=>
           eopair D (E:A->A->bool) el onebee ot)`
  (LABEL_TAC "hrk") THENL
   [REPEAT GEN_TAC THEN STRIP_TAC THEN
    SUBGOAL_THEN
     `valuation D ((3 |-> (ot:A)) ((0 |-> (el:A)) vP))`
    ASSUME_TAC THENL
     [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
      `(3 |-> (ot:A)) ((0 |-> (el:A)) vP)`;
      `0`; `4`; `3`] HOLDS_OPAIR_FORM) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    ASM_REWRITE_TAC[VALMOD; ARITH_EQ];
    ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`] ZF_REPLACEMENT) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(MP_TAC o SPECL
    [`opair_form 0 4 3`; `0`; `3`; `vP:num->A`; `dd:A`]) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[ARITH_EQ] THEN
    X_GEN_TAC `u:A` THEN STRIP_TAC THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `u:A`; `onebee:A`]
      EOPAIR_EXISTS) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(X_CHOOSE_TAC `pv:A`) THEN
    SUBGOAL_THEN `(pv:A) IN D` ASSUME_TAC THENL
     [ASM_MESON_TAC[EOPAIR_IN]; ALL_TAC] THEN
    EXISTS_TAC `pv:A` THEN ASM_REWRITE_TAC[] THEN
    X_GEN_TAC `w':A` THEN
    DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC MP_TAC) THEN
    USE_THEN "hrk" (MP_TAC o SPECL [`u:A`; `w':A`]) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    DISCH_TAC THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `u:A`; `onebee:A`;
      `w':A`; `pv:A`] EOPAIR_UNIQUE) THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `cn:A` (CONJUNCTS_THEN2 ASSUME_TAC
    (LABEL_TAC "raw"))) THEN
  SUBGOAL_THEN
   `!z. z IN D
        ==> (E z cn <=>
             ?s. s IN D /\ E s dd /\
                 eopair D (E:A->A->bool) s onebee z)`
  (LABEL_TAC "CNc") THENL
   [X_GEN_TAC `z:A` THEN DISCH_TAC THEN
    USE_THEN "raw" (MP_TAC o SPEC `z:A`) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    MATCH_MP_TAC(MESON[]
     `(!s:A. P s <=> Q s) ==> ((?s:A. P s) <=> (?s:A. Q s))`) THEN
    X_GEN_TAC `s:A` THEN
    MATCH_MP_TAC(TAUT `(a ==> (p <=> q)) ==> ((a /\ p) <=> (a /\ q))`) THEN
    STRIP_TAC THEN
    USE_THEN "hrk" (MP_TAC o SPECL [`s:A`; `z:A`]) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]);
    ALL_TAC] THEN
  EXISTS_TAC `cn:A` THEN REPEAT CONJ_TAC THENL
   [FIRST_ASSUM ACCEPT_TAC;
    REWRITE_TAC[eisfun] THEN REPEAT CONJ_TAC THENL
     [FIRST_ASSUM ACCEPT_TAC;
      X_GEN_TAC `z:A` THEN STRIP_TAC THEN
      SUBGOAL_THEN
       `?s. s IN D /\ E s dd /\ eopair D (E:A->A->bool) s onebee z`
      STRIP_ASSUME_TAC THENL [ASM_MESON_TAC[]; ALL_TAC] THEN
      MAP_EVERY EXISTS_TAC [`s:A`; `onebee:A`] THEN ASM_REWRITE_TAC[];
      REPEAT GEN_TAC THEN STRIP_TAC THEN
      SUBGOAL_THEN `(z:A) IN D /\ (z':A) IN D` STRIP_ASSUME_TAC THENL
       [ASM_MESON_TAC[EOPAIR_IN]; ALL_TAC] THEN
      SUBGOAL_THEN
       `?s1. s1 IN D /\ E s1 dd /\ eopair D (E:A->A->bool) s1 onebee z`
      STRIP_ASSUME_TAC THENL [ASM_MESON_TAC[]; ALL_TAC] THEN
      SUBGOAL_THEN
       `?s2. s2 IN D /\ E s2 dd /\ eopair D (E:A->A->bool) s2 onebee z'`
      STRIP_ASSUME_TAC THENL [ASM_MESON_TAC[]; ALL_TAC] THEN
      SUBGOAL_THEN `(u:A) = s1 /\ (w:A) = onebee` STRIP_ASSUME_TAC THENL
       [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `u:A`; `w:A`;
          `s1:A`; `onebee:A`; `z:A`] EOPAIR_INJ) THEN ASM_REWRITE_TAC[];
        ALL_TAC] THEN
      SUBGOAL_THEN `(u:A) = s2 /\ (w':A) = onebee` STRIP_ASSUME_TAC THENL
       [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `u:A`; `w':A`;
          `s2:A`; `onebee:A`; `z':A`] EOPAIR_INJ) THEN ASM_REWRITE_TAC[];
        ALL_TAC] THEN
      ASM_REWRITE_TAC[]];
    REWRITE_TAC[edomain] THEN CONJ_TAC THENL
     [FIRST_ASSUM ACCEPT_TAC;
      X_GEN_TAC `u:A` THEN DISCH_TAC THEN REWRITE_TAC[eindom] THEN
      EQ_TAC THENL
       [DISCH_TAC THEN
        MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `u:A`; `onebee:A`]
          EOPAIR_EXISTS) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
        DISCH_THEN(X_CHOOSE_TAC `zz:A`) THEN
        SUBGOAL_THEN `(zz:A) IN D` ASSUME_TAC THENL
         [ASM_MESON_TAC[EOPAIR_IN]; ALL_TAC] THEN
        EXISTS_TAC `onebee:A` THEN CONJ_TAC THENL
         [FIRST_ASSUM ACCEPT_TAC;
          REWRITE_TAC[eapply] THEN EXISTS_TAC `zz:A` THEN CONJ_TAC THENL
           [FIRST_ASSUM ACCEPT_TAC; ASM_MESON_TAC[]]];
        DISCH_THEN(X_CHOOSE_THEN `wv:A` (CONJUNCTS_THEN2 ASSUME_TAC
          MP_TAC)) THEN
        REWRITE_TAC[eapply] THEN
        DISCH_THEN(X_CHOOSE_THEN `zz:A` STRIP_ASSUME_TAC) THEN
        SUBGOAL_THEN `(zz:A) IN D` ASSUME_TAC THENL
         [ASM_MESON_TAC[EOPAIR_IN]; ALL_TAC] THEN
        SUBGOAL_THEN
         `?s1. s1 IN D /\ E s1 dd /\ eopair D (E:A->A->bool) s1 onebee zz`
        STRIP_ASSUME_TAC THENL [ASM_MESON_TAC[]; ALL_TAC] THEN
        SUBGOAL_THEN `(u:A) = s1` ASSUME_TAC THENL
         [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `u:A`; `wv:A`;
            `s1:A`; `onebee:A`; `zz:A`] EOPAIR_INJ) THEN ASM_MESON_TAC[];
          ALL_TAC] THEN
        ASM_MESON_TAC[]]];
    REPEAT GEN_TAC THEN STRIP_TAC THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `s:A`; `onebee:A`]
      EOPAIR_EXISTS) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(X_CHOOSE_TAC `zz:A`) THEN
    SUBGOAL_THEN `(zz:A) IN D` ASSUME_TAC THENL
     [ASM_MESON_TAC[EOPAIR_IN]; ALL_TAC] THEN
    REWRITE_TAC[eapply] THEN EXISTS_TAC `zz:A` THEN CONJ_TAC THENL
     [FIRST_ASSUM ACCEPT_TAC; ASM_MESON_TAC[]];
    USE_THEN "CNc" ACCEPT_TAC]);;

(* ===== EFULLNAME_BNAME: the full-name C = {<s,onebee> : s IN dd} is a bname
   whenever dd's elements are all E-below a B-name stage fy
     (ebnstage fa fy) and
   onebee IN B.  Mirrors EPOWERNAME_BNAME (constant value onebee in place
   of esubval q; E onebee B replaces ESUBVAL_IN).  STRIP_TAC form: the Wsub and
   membership clauses are used through ASM_MESON, not labels. *)
let EFULLNAME_BNAME = prove
 (`!D (E:A->A->bool) B leq onebee dd fa fy cn.
      model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
      onebee IN D /\ E onebee B /\ dd IN D /\
      fa IN D /\ fy IN D /\ eordinal D E fa /\ ebnstage D E B fa fy /\
      (!f. f IN D /\ E f dd ==> E f fy) /\
      cn IN D /\ eisfun D E cn /\
      (!z. z IN D
           ==> (E z cn <=>
                ?s. s IN D /\ E s dd /\
                    eopair D (E:A->A->bool) s onebee z))
      ==> bname D E B cn`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`fa:A`] ESUC_EXISTS) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `sa:A`) THEN
  SUBGOAL_THEN
    `(sa:A) IN D /\ eordinal D (E:A->A->bool) sa /\ (E:A->A->bool) fa sa`
  STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[ESUC_IN; EORDINAL_ESUC; ESUC_MEMBER]; ALL_TAC] THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`sa:A`] EBNSTAGE_EXISTS) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `ysa:A` STRIP_ASSUME_TAC) THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`sa:A`;`ysa:A`]
         EBNSTAGE_CHAR) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `w1:A` (CONJUNCTS_THEN2 ASSUME_TAC
    (CONJUNCTS_THEN2 (LABEL_TAC "w1ch") ASSUME_TAC))) THEN
  SUBGOAL_THEN `!u:A. u IN D /\ (E:A->A->bool) u fy ==> E u w1`
    (LABEL_TAC "Ysub") THENL
   [X_GEN_TAC `u:A` THEN STRIP_TAC THEN
    USE_THEN "w1ch" (MP_TAC o SPEC `u:A`) THEN
    ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    MAP_EVERY EXISTS_TAC [`fa:A`;`fy:A`] THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`w1:A`;`B:A`] ECROSS_EXISTS) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `cr:A` (LABEL_TAC "cr")) THEN
  SUBGOAL_THEN `(cr:A) IN D` ASSUME_TAC THENL
   [USE_THEN "cr" (MP_TAC o REWRITE_RULE[ecross]) THEN SIMP_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `esubset D (E:A->A->bool) cn cr` ASSUME_TAC THENL
   [REWRITE_TAC[esubset] THEN X_GEN_TAC `z:A` THEN STRIP_TAC THEN
    USE_THEN "cr" (MP_TAC o SPEC `z:A` o CONJUNCT2 o REWRITE_RULE[ecross]) THEN
    ASM_REWRITE_TAC[] THEN DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    SUBGOAL_THEN
     `?s. s IN D /\ E s dd /\ eopair D (E:A->A->bool) s onebee z`
    STRIP_ASSUME_TAC THENL [ASM_MESON_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN `(E:A->A->bool) s fy` ASSUME_TAC THENL
     [ASM_MESON_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN `(E:A->A->bool) s w1` ASSUME_TAC THENL
     [USE_THEN "Ysub" MATCH_MP_TAC THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    MAP_EVERY EXISTS_TAC [`s:A`;`onebee:A`] THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `ebnmem D (E:A->A->bool) B w1 cn` ASSUME_TAC THENL
   [REWRITE_TAC[ebnmem] THEN ASM_REWRITE_TAC[] THEN
    EXISTS_TAC `cr:A` THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) cn ysa` ASSUME_TAC THENL
   [UNDISCH_TAC `ebnfuns D (E:A->A->bool) B w1 ysa` THEN
    REWRITE_TAC[ebnfuns] THEN
    DISCH_THEN(MP_TAC o SPEC `cn:A` o CONJUNCT2) THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  REWRITE_TAC[bname] THEN MAP_EVERY EXISTS_TAC [`sa:A`;`ysa:A`] THEN
  ASM_REWRITE_TAC[]);;

(* ===== EFULLNAME_IN_GE_ELT: each element s of dd gives [[t=s]] <= [[t IN C]].
   Mirrors ECHECK_IN_GE_ELT with domain witness (s, onebee) supplied
   directly by eapply (no ECHECK_MEM needed). *)
let EFULLNAME_IN_GE_ELT = prove
 (`!D (E:A->A->bool) B leq onebee cn s t z es.
      model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
      onebee IN D /\ E onebee B /\ etop D E B leq onebee /\
      cn IN D /\ s IN D /\ bname D E B s /\ eapply D E cn s onebee /\
      bname D E B t /\ t IN D /\
      z IN D /\ ebv_in D E B leq t cn z /\
      es IN D /\ ebv_eq D E B leq t s es
      ==> erel D E leq es z`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `eporder D (E:A->A->bool) B leq` ASSUME_TAC THENL
   [ASM_MESON_TAC[ECBA_IMP_BALG; EBALG_IMP_PORDER]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) es B` ASSUME_TAC THENL
   [MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`t:A`;`s:A`]
      EBV_EQ_VAL_EXISTS) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(X_CHOOSE_THEN `ee:A` STRIP_ASSUME_TAC) THEN
    SUBGOAL_THEN `es:A = ee` SUBST1_TAC THENL
     [MATCH_MP_TAC(ISPECL
                   [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`t:A`;`s:A`;
                    `es:A`;`ee:A`] EBV_EQ_UNIQUE) THEN ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `emeet D (E:A->A->bool) B leq onebee es es` ASSUME_TAC THENL
   [MATCH_MP_TAC EMEET_SYM THEN MATCH_MP_TAC EMEET_TOP THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  MATCH_MP_TAC(ISPECL
               [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`t:A`;`cn:A`;`z:A`;
                `s:A`;`onebee:A`;`es:A`;`es:A`] EBV_IN_GE_TERM_V) THEN
  ASM_REWRITE_TAC[]);;

(* ===== EFULLNAME_IN_LE_SUP: [[t IN C]] is below any common upper bound of the
   equality values [[t=s]] over s IN dd.  Mirrors ECHECK_IN_LE_SUP;
   the domain->dd inversion (ECHECK_DOM_ELT there) is done inline by inverting
   eapply cn y qy through the membership characterization + EOPAIR_INJ. *)

(* ===================================================================== *)
(* V^B REPLACEMENT axiom: abstract Boolean-algebra cores for the          *)
(* collection step.  Pure poset/cba reasoning (no formulas, no           *)
(* valuations): the formula/valuation peeling that instantiates these    *)
(* is done by the caller at assembly time.                                *)
(*                                                                        *)
(*   EBV_MP_LE         modus-ponens bound   d<=b /\ d<=(b=>c) ==> d<=c     *)
(*   EBV_FUNC_EQ       functional-premise equality bound (d-form)          *)
(*   EBV_PERWITNESS_LE per-witness collection bound (the STABILIZATION     *)
(*                     <-> collection contract), by PURE RESIDUATION --    *)
(*                     no complement, no infinite distributive law.        *)
(* ===================================================================== *)

(* ===== EBV_MP_LE: if d <= b and d <= (b ==> c) then d <= c.  The forward
   modus-ponens convenience atop residuation (EBIMP_MEET_LE): d <= b gives
   meet(d,b) = d-below, d <= i = (b==>c) gives meet(d,b) <= c, so d <= c.
   Workhorse of the residuation route (the collection reduction and the
   functional-eq assembly repeatedly need exactly this shape). *)
let EBV_MP_LE = prove
 (`!D (E:A->A->bool) B leq d b c i.
      ecba D E B leq /\ B IN D /\ leq IN D /\
      d IN D /\ b IN D /\ c IN D /\ i IN D /\
      E d B /\ E b B /\ E c B /\
      ebimp D E B leq b c i /\
      erel D E leq d b /\ erel D E leq d i
      ==> erel D E leq d c`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `ebalg D (E:A->A->bool) B leq` ASSUME_TAC THENL
   [ASM_MESON_TAC[ECBA_IMP_BALG]; ALL_TAC] THEN
  SUBGOAL_THEN `eporder D (E:A->A->bool) B leq` ASSUME_TAC THENL
   [ASM_MESON_TAC[EBALG_IMP_PORDER]; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq d d` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`d:A`]
                 EPORDER_REFL) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`d:A`;`b:A`]
         EBALG_MEET) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `m:A`) THEN
  SUBGOAL_THEN `(m:A) IN D /\ (E:A->A->bool) m B` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[EMEET_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq d m` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`d:A`;`b:A`;
                  `m:A`;`d:A`]
                 EMEET_GREATEST) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq m c` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`d:A`;`b:A`;`c:A`;
                  `i:A`;`m:A`] EBIMP_MEET_LE) THEN ASM_REWRITE_TAC[];
         ALL_TAC] THEN
  MATCH_MP_TAC(ISPECL
               [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`d:A`;`m:A`;`c:A`]
               EPORDER_TRANS) THEN ASM_REWRITE_TAC[]);;

(* ===== EBV_FUNC_EQ (abstract d-form): the functional-premise equality bound.
   If d is below the per-witness functional value fv = [[!y(p-->Eq y zz)]] and
   below both image values pt = [[p(ss,tt)]], ps = [[p(ss,s)]], and fv is below
   both material implications (pt ==> [tt=zz]) = i1 and (ps ==> [s=zz]) = i2,
   then d is below the equality value [tt=s] = ets.  Pure Boolean-algebra core;
   the formula/valuation peeling that produces i1,i2,fv is done by the caller
   (BVALF_ALL_LB + BVALF_IMP + BVALF_EQ at the assembly). *)
let EBV_FUNC_EQ = prove
 (`!D (E:A->A->bool) B leq d fv pt ps zz tt s etz esz ets i1 i2.
      model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
      d IN D /\ fv IN D /\ pt IN D /\ ps IN D /\
      zz IN D /\ tt IN D /\ s IN D /\
      etz IN D /\ esz IN D /\ ets IN D /\ i1 IN D /\ i2 IN D /\
      bname D E B tt /\ bname D E B zz /\ bname D E B s /\
      ebv_eq D E B leq tt zz etz /\
      ebv_eq D E B leq s zz esz /\
      ebv_eq D E B leq tt s ets /\
      ebimp D E B leq pt etz i1 /\
      ebimp D E B leq ps esz i2 /\
      erel D E leq d fv /\ erel D E leq d pt /\ erel D E leq d ps /\
      erel D E leq fv i1 /\ erel D E leq fv i2
      ==> erel D E leq d ets`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `ebalg D (E:A->A->bool) B leq` ASSUME_TAC THENL
   [ASM_MESON_TAC[ECBA_IMP_BALG]; ALL_TAC] THEN
  SUBGOAL_THEN `eporder D (E:A->A->bool) B leq` ASSUME_TAC THENL
   [ASM_MESON_TAC[EBALG_IMP_PORDER]; ALL_TAC] THEN
  SUBGOAL_THEN
   `(E:A->A->bool) d B /\ E fv B /\ E pt B /\ E ps B /\ E i1 B /\ E i2 B`
  STRIP_ASSUME_TAC THENL [ASM_MESON_TAC[EPORDER_FIELD]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) etz B /\ E esz B /\ E ets B`
    STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[EBV_EQ_IN_B]; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq d i1` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`d:A`;`fv:A`;`i1:A`]
                 EPORDER_TRANS) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq d i2` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`d:A`;`fv:A`;`i2:A`]
                 EPORDER_TRANS) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq d d` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`d:A`]
                 EPORDER_REFL) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`d:A`;`pt:A`]
         EBALG_MEET) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `m1:A`) THEN
  SUBGOAL_THEN `(m1:A) IN D /\ (E:A->A->bool) m1 B` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[EMEET_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq d m1` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`d:A`;`pt:A`;
                  `m1:A`;`d:A`]
                 EMEET_GREATEST) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq m1 etz` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`d:A`;
                  `pt:A`;`etz:A`;
                  `i1:A`;`m1:A`] EBIMP_MEET_LE) THEN ASM_REWRITE_TAC[];
         ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq d etz` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`d:A`;
                  `m1:A`;`etz:A`]
                 EPORDER_TRANS) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`d:A`;`ps:A`]
         EBALG_MEET) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `m2:A`) THEN
  SUBGOAL_THEN `(m2:A) IN D /\ (E:A->A->bool) m2 B` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[EMEET_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq d m2` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`d:A`;`ps:A`;
                  `m2:A`;`d:A`]
                 EMEET_GREATEST) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq m2 esz` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`d:A`;
                  `ps:A`;`esz:A`;
                  `i2:A`;`m2:A`] EBIMP_MEET_LE) THEN ASM_REWRITE_TAC[];
         ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq d esz` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`d:A`;
                  `m2:A`;`esz:A`]
                 EPORDER_TRANS) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `ebv_eq D (E:A->A->bool) B leq zz s esz` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`s:A`;
                  `zz:A`;`esz:A`]
                 EBV_EQ_SYM) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`etz:A`;`esz:A`]
         EBALG_MEET) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `m3:A`) THEN
  SUBGOAL_THEN `(m3:A) IN D /\ (E:A->A->bool) m3 B` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[EMEET_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq m3 ets` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`tt:A`;`zz:A`;`s:A`;
                  `etz:A`;`esz:A`;`ets:A`;`m3:A`] EBV_EQ_CONG) THEN
         ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq d m3` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`etz:A`;`esz:A`;
                  `m3:A`;`d:A`]
                 EMEET_GREATEST) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MATCH_MP_TAC(ISPECL
               [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`d:A`;`m3:A`;`ets:A`]
               EPORDER_TRANS) THEN ASM_REWRITE_TAC[]);;

(* ===== EBV_PERWITNESS_LE (abstract): the per-witness collection bound, the
   clean contract between STABILIZATION and the collection step.
     Given a B-name
   value m (= prem MEET [[ss in aa]] MEET [[p(ss,tt)]]),
   a target K (= [[tt in C]]),
   the image value ptt (= [[p(ss,tt)]]), a SET SS of B-values (= {[[p(ss,s)]] :
   s in W_lambda}) with least upper bound g, and the material implication
   i0 = (m ==> K):
     - m <= ptt  and  ptt <= g          (m below its own conjunct;
     STABILIZATION)
     - every meet(m,pS) <= K  for pS in SS   (FUNCTIONAL-EQ + [[tt=s]] <=
       [[tt in C]])
   then m <= K.  PURE RESIDUATION, no complement / infinite-distributive law:
   meet(m,pS)<=K  ==> pS<=i0 (EBIMP_LE_IMP), so i0 bounds SS,
   so g<=i0 (ELUB_LEAST);
   ptt<=g<=i0 and m<=ptt give m<=i0,
   whence meet(m,m)<=K (EBIMP_MEET_LE) and m<=K. *)
let EBV_PERWITNESS_LE = prove
 (`!D (E:A->A->bool) B leq m K g ptt SS i0.
      ecba D E B leq /\ B IN D /\ leq IN D /\
      m IN D /\ K IN D /\ g IN D /\ ptt IN D /\ SS IN D /\ i0 IN D /\
      E m B /\ E K B /\ E ptt B /\ E i0 B /\
      esubset D E SS B /\
      elub D E B leq SS g /\
      ebimp D E B leq m K i0 /\
      erel D E leq m ptt /\ erel D E leq ptt g /\
      (!pS mm. pS IN D /\ E pS SS /\ emeet D E B leq m pS mm
               ==> erel D E leq mm K)
      ==> erel D E leq m K`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `ebalg D (E:A->A->bool) B leq` ASSUME_TAC THENL
   [ASM_MESON_TAC[ECBA_IMP_BALG]; ALL_TAC] THEN
  SUBGOAL_THEN `eporder D (E:A->A->bool) B leq` ASSUME_TAC THENL
   [ASM_MESON_TAC[EBALG_IMP_PORDER]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) g B` ASSUME_TAC THENL
   [ASM_MESON_TAC[ELUB_IN]; ALL_TAC] THEN
  (* i0 bounds SS: for pS in SS, meet(m,pS)<=K gives pS<=i0 by residuation *)
  SUBGOAL_THEN `eubound D (E:A->A->bool) B leq SS i0` ASSUME_TAC THENL
   [REWRITE_TAC[eubound] THEN ASM_REWRITE_TAC[] THEN
    X_GEN_TAC `pS:A` THEN STRIP_TAC THEN
    SUBGOAL_THEN `(E:A->A->bool) pS B` ASSUME_TAC THENL
     [UNDISCH_TAC `esubset D (E:A->A->bool) SS B` THEN
      REWRITE_TAC[esubset] THEN DISCH_THEN MATCH_MP_TAC THEN ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`m:A`;`pS:A`]
           EBALG_MEET) THEN
    ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `mm:A`) THEN
    SUBGOAL_THEN `(mm:A) IN D /\ (E:A->A->bool) mm B` STRIP_ASSUME_TAC THENL
     [ASM_MESON_TAC[EMEET_IN]; ALL_TAC] THEN
    SUBGOAL_THEN `erel D (E:A->A->bool) leq mm K` ASSUME_TAC THENL
     [FIRST_X_ASSUM(MP_TAC o SPECL [`pS:A`;`mm:A`]) THEN ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    SUBGOAL_THEN `emeet D (E:A->A->bool) B leq pS m mm` ASSUME_TAC THENL
     [MATCH_MP_TAC EMEET_SYM THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`pS:A`;`m:A`;`K:A`;
                  `i0:A`;`mm:A`] EBIMP_LE_IMP) THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  (* g <= i0, so m <= ptt <= g <= i0 *)
  SUBGOAL_THEN `erel D (E:A->A->bool) leq g i0` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`SS:A`;`g:A`;`i0:A`]
                 ELUB_LEAST) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq ptt i0` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`ptt:A`;
                  `g:A`;`i0:A`]
                 EPORDER_TRANS) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq m i0` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`m:A`;
                  `ptt:A`;`i0:A`]
                 EPORDER_TRANS) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* meet(m,m)<=K by residuation from m<=i0, and m<=meet(m,m), so m<=K *)
  SUBGOAL_THEN `erel D (E:A->A->bool) leq m m` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`m:A`]
                 EPORDER_REFL) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`m:A`;`m:A`]
         EBALG_MEET) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `mm2:A`) THEN
  SUBGOAL_THEN `(mm2:A) IN D /\ (E:A->A->bool) mm2 B` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[EMEET_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq m mm2` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`m:A`;`m:A`;
                  `mm2:A`;`m:A`]
                 EMEET_GREATEST) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq mm2 K` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`m:A`;`m:A`;`K:A`;
                  `i0:A`;`mm2:A`] EBIMP_MEET_LE) THEN ASM_REWRITE_TAC[];
         ALL_TAC] THEN
  MATCH_MP_TAC(ISPECL
               [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`m:A`;`mm2:A`;`K:A`]
               EPORDER_TRANS) THEN ASM_REWRITE_TAC[]);;

(* ===== BVAL_VALUESET_EXISTS: the value-set {z in B : ?bname a. z =
  [[p]]_{(m|->a)v}}
   exists as an M-set.  Lifted verbatim from BVAL_TOTAL's !! case,
   which never uses its induction hypothesis: the value-set formation rests on
   BVAL_DEFINABLE (bval internalised as object formula fp) +
     ZF_SEPARATION over B
   along  ??(32+m)(bname_form(32+m) && fp).  Stabilization Step 1 (V_ss). *)
let BVAL_VALUESET_EXISTS = prove
 (`!p m D (E:A->A->bool) B leq v.
      model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
      valuation D v /\ (!i. bname D E B (v i))
      ==> ?S. S IN D /\ esubset D E S B /\
              (!z. z IN D
                   ==> (E z S <=>
                        ?a. a IN D /\ bname D E B a /\
                            bval D E B leq ((m |-> a) v) p z))`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `!x. (v:num->A) x IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[valuation]; ALL_TAC] THEN
  SUBGOAL_THEN `ebalg D (E:A->A->bool) B leq` ASSUME_TAC THENL
   [FIRST_ASSUM(ACCEPT_TAC o CONJUNCT1 o REWRITE_RULE[ecba]); ALL_TAC] THEN
  SUBGOAL_THEN
    `?izz. ~(izz IN ({2, 3, 30, 31, 32 + m} UNION IMAGE (\k. 32 + k) (FV p)))`
    (X_CHOOSE_TAC `izz:num`) THENL
   [MATCH_MP_TAC num_FINITE_AVOID THEN
    SIMP_TAC[FINITE_UNION; FINITE_INSERT; FINITE_EMPTY;
             FINITE_IMAGE; FV_FINITE];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `~(izz = 2) /\ ~(izz = 3) /\ ~(izz = 30) /\ ~(izz = 31) /\
    ~(izz = 32 + m) /\
    (!i. i IN FV p ==> ~(izz = 32 + i))`
   STRIP_ASSUME_TAC THENL
   [UNDISCH_TAC
     `~(izz IN ({2, 3, 30, 31, 32 + m} UNION IMAGE (\k. 32 + k) (FV p)))` THEN
    REWRITE_TAC[IN_UNION; IN_INSERT; NOT_IN_EMPTY; IN_IMAGE] THEN MESON_TAC[];
    ALL_TAC] THEN
  X_CHOOSE_TAC `fp:form`
    (ISPECL [`p:form`; `izz:num`; `3`] BVAL_DEFINABLE) THEN
  ABBREV_TAC `w0 = (2 |-> B) ((3 |-> leq) (\k. (v:num->A) (k - 32)))` THEN
  SUBGOAL_THEN
   `valuation D (w0:num->A) /\ w0 2 = B /\ w0 3 = leq /\
    (!i. w0 (32 + i) = (v:num->A) i)`
   STRIP_ASSUME_TAC THENL
   [EXPAND_TAC "w0" THEN REPEAT CONJ_TAC THENL
     [REPEAT(MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[]) THEN
      REWRITE_TAC[valuation] THEN ASM_REWRITE_TAC[];
      SIMP_TAC[VALMOD_BASIC];
      SIMP_TAC[VALMOD_OTHER; VALMOD_BASIC; ARITH_RULE `~(3 = 2)`];
      GEN_TAC THEN
      SIMP_TAC[VALMOD_OTHER; ARITH_RULE `~(32 + i = 2) /\ ~(32 + i = 3)`] THEN
      AP_TERM_TAC THEN ARITH_TAC];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!zz. zz IN D
      ==> (holds D E ((izz |-> zz) (w0:num->A))
             (?? (32 + m) (bname_form (32 + m) && fp)) <=>
           (?a. a IN D /\ bname D E B a /\
                bval D E B leq ((m |-> a) v) p zz))`
   (LABEL_TAC "bridge") THENL
   [X_GEN_TAC `zz:A` THEN DISCH_TAC THEN
    SUBGOAL_THEN `valuation D ((izz |-> zz) (w0:num->A))` ASSUME_TAC THENL
     [ASM_SIMP_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
    REWRITE_TAC[HOLDS_EX] THEN
    MATCH_MP_TAC EXISTS_AND_CONG THEN X_GEN_TAC `a:A` THEN DISCH_TAC THEN
    SUBGOAL_THEN `valuation D (((32 + m) |-> a) ((izz |-> zz) (w0:num->A)))`
      ASSUME_TAC THENL [ASM_SIMP_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
    SUBGOAL_THEN
      `holds D E (((32 + m) |-> a) ((izz |-> zz) (w0:num->A)))
         (bname_form (32 + m)) <=> bname D E B a`
      ASSUME_TAC THENL
     [ASM_SIMP_TAC[HOLDS_BNAME_FORM; VALMOD_BASIC; VALMOD_OTHER;
        ARITH_RULE `~(32 + m = 30) /\ ~(32 + m = 31) /\ ~(2 = 32 + m)`];
      ALL_TAC] THEN
    SUBGOAL_THEN
      `holds D E (((32 + m) |-> a) ((izz |-> zz) (w0:num->A))) fp <=>
       bval D E B leq ((m |-> a) v) p zz`
      ASSUME_TAC THENL
     [FIRST_X_ASSUM(fun th -> MP_TAC(SPECL
        [`D:A->bool`; `E:A->A->bool`;
         `((32 + m) |-> a) ((izz |-> zz) (w0:num->A))`] th) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[] THEN ARITH_TAC; ALL_TAC]) THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
      ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER;
        ARITH_RULE `~(2 = 32 + m) /\ ~(3 = 32 + m)`] THEN
      MATCH_MP_TAC BVAL_FV THEN X_GEN_TAC `i:num` THEN DISCH_TAC THEN
      ASM_CASES_TAC `i:num = m` THEN
      ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER;
        ARITH_RULE `~(i = m) ==> ~(32 + i = 32 + m)`]; ALL_TAC] THEN
    REWRITE_TAC[HOLDS_AND] THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`] ZF_SEPARATION) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(MP_TAC o SPECL
    [`?? (32 + m) (bname_form (32 + m) && fp)`; `izz:num`; `w0:num->A`;
     `B:A`]) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `S:A` STRIP_ASSUME_TAC) THEN
  SUBGOAL_THEN
   `!zz. zz IN D
      ==> (E zz S <=> ?a. a IN D /\ bname D (E:A->A->bool) B a /\
                          bval D (E:A->A->bool) B leq ((m |-> (a:A)) v) p zz)`
   ASSUME_TAC THENL
   [X_GEN_TAC `zz:A` THEN DISCH_TAC THEN
    SUBGOAL_THEN
     `(?a. a IN D /\ bname D (E:A->A->bool) B a /\
       bval D (E:A->A->bool) B leq ((m |-> (a:A)) v) p zz)
       ==> E zz B` ASSUME_TAC THENL
     [DISCH_THEN(X_CHOOSE_THEN `a:A` STRIP_ASSUME_TAC) THEN
      MATCH_MP_TAC(ISPECL [`p:form`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
        `(m |-> (a:A)) (v:num->A)`;`zz:A`] BVAL_IN_B) THEN
      ASM_REWRITE_TAC[] THEN MATCH_MP_TAC VALUATION_VALMOD THEN
      ASM_REWRITE_TAC[]; ALL_TAC] THEN
    FIRST_X_ASSUM(fun sep -> MP_TAC(SPEC `zz:A` sep)) THEN
    ASM_REWRITE_TAC[] THEN
    USE_THEN "bridge"(MP_TAC o SPEC `zz:A`) THEN ASM_REWRITE_TAC[] THEN
    ASM_MESON_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `esubset D (E:A->A->bool) S B` ASSUME_TAC THENL
   [REWRITE_TAC[esubset] THEN ASM_MESON_TAC[]; ALL_TAC] THEN
  EXISTS_TAC `S:A` THEN ASM_REWRITE_TAC[]);;

(* ===== BVAL_REPLIMG_EXISTS: the replacement image
  {[[p]]_{(iy|->s)vbase} : s in dd}
   exists as an M-set.  Dual of BVAL_VALUESET_EXISTS: there the
     value var ranged
   over ALL bnames (via ??);
   here var iy ranges over the SET dd via ZF_REPLACEMENT
   (input slot 32+iy, output/value slot izz fresh;
   functionality by BVAL_TOTAL +
   BVAL_UNIQUE,
   using that dd's elements + vbase are bnames).  Stabilization Step 2
   (S_lambda = image of the stage W_lambda). *)
let BVAL_REPLIMG_EXISTS = prove
 (`!p iy D (E:A->A->bool) B leq vbase dd.
      model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
      valuation D vbase /\ (!i. bname D E B (vbase i)) /\
      dd IN D /\ (!s. s IN D /\ E s dd ==> bname D E B s)
      ==> ?S. S IN D /\ esubset D E S B /\
              (!z. z IN D
                   ==> (E z S <=>
                        ?s. s IN D /\ E s dd /\
                            bval D E B leq ((iy |-> s) vbase) p z))`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `!x. (vbase:num->A) x IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[valuation]; ALL_TAC] THEN
  SUBGOAL_THEN `ebalg D (E:A->A->bool) B leq` ASSUME_TAC THENL
   [FIRST_ASSUM(ACCEPT_TAC o CONJUNCT1 o REWRITE_RULE[ecba]); ALL_TAC] THEN
  SUBGOAL_THEN
    `?izz. ~(izz IN ({2, 3, 30, 31, 32 + iy} UNION IMAGE (\k. 32 + k) (FV p)))`
    (X_CHOOSE_TAC `izz:num`) THENL
   [MATCH_MP_TAC num_FINITE_AVOID THEN
    SIMP_TAC[FINITE_UNION; FINITE_INSERT; FINITE_EMPTY;
             FINITE_IMAGE; FV_FINITE];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `~(izz = 2) /\ ~(2 = izz) /\ ~(izz = 3) /\ ~(3 = izz) /\
    ~(izz = 30) /\ ~(izz = 31) /\ ~(izz = 32 + iy) /\ ~(32 + iy = izz) /\
    (!i. i IN FV p ==> ~(izz = 32 + i) /\ ~(32 + i = izz))`
   STRIP_ASSUME_TAC THENL
   [UNDISCH_TAC
     `~(izz IN ({2, 3, 30, 31, 32 + iy} UNION IMAGE (\k. 32 + k) (FV p)))` THEN
    REWRITE_TAC[IN_UNION; IN_INSERT; NOT_IN_EMPTY; IN_IMAGE] THEN MESON_TAC[];
    ALL_TAC] THEN
  X_CHOOSE_TAC `fp:form`
    (ISPECL [`p:form`; `izz:num`; `3`] BVAL_DEFINABLE) THEN
  ABBREV_TAC `w0 = (2 |-> B) ((3 |-> leq) (\k. (vbase:num->A) (k - 32)))` THEN
  SUBGOAL_THEN
   `valuation D (w0:num->A) /\ w0 2 = B /\ w0 3 = leq /\
    (!i. w0 (32 + i) = (vbase:num->A) i)`
   STRIP_ASSUME_TAC THENL
   [EXPAND_TAC "w0" THEN REPEAT CONJ_TAC THENL
     [REPEAT(MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[]) THEN
      REWRITE_TAC[valuation] THEN ASM_REWRITE_TAC[];
      SIMP_TAC[VALMOD_BASIC];
      SIMP_TAC[VALMOD_OTHER; VALMOD_BASIC; ARITH_RULE `~(3 = 2)`];
      GEN_TAC THEN
      SIMP_TAC[VALMOD_OTHER; ARITH_RULE `~(32 + i = 2) /\ ~(32 + i = 3)`] THEN
      AP_TERM_TAC THEN ARITH_TAC];
    ALL_TAC] THEN
  (* BRIDGE *)
  SUBGOAL_THEN
   `!s w. s IN D /\ w IN D
      ==> (holds D E ((izz |-> w) (((32 + iy) |-> s) (w0:num->A))) fp <=>
           bval D E B leq ((iy |-> s) vbase) p w)`
   (LABEL_TAC "bridge") THENL
   [MAP_EVERY X_GEN_TAC [`s:A`; `w:A`] THEN STRIP_TAC THEN
    SUBGOAL_THEN `valuation D ((izz |-> w) (((32 + iy) |-> s) (w0:num->A)))`
      ASSUME_TAC THENL [ASM_SIMP_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
    FIRST_X_ASSUM(fun th -> MP_TAC(SPECL
      [`D:A->bool`; `E:A->A->bool`;
       `(izz |-> w) (((32 + iy) |-> s) (w0:num->A))`] th) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[] THEN ARITH_TAC; ALL_TAC]) THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER;
      ARITH_RULE `~(2 = 32 + iy) /\ ~(3 = 32 + iy)`] THEN
    MATCH_MP_TAC BVAL_FV THEN X_GEN_TAC `i:num` THEN DISCH_TAC THEN
    ASM_CASES_TAC `i:num = iy` THEN
    ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER;
      ARITH_RULE `~(i = iy) ==> ~(32 + i = 32 + iy)`]; ALL_TAC] THEN
  (* apply ZF_REPLACEMENT *)
  MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`] ZF_REPLACEMENT) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(MP_TAC o SPECL
    [`fp:form`; `32 + iy`; `izz:num`; `w0:num->A`; `dd:A`]) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[] THEN
    X_GEN_TAC `u:A` THEN STRIP_TAC THEN
    SUBGOAL_THEN `bname D (E:A->A->bool) B u` ASSUME_TAC THENL
     [UNDISCH_TAC `!s. s IN D /\ E s dd ==> bname D (E:A->A->bool) B s` THEN
      DISCH_THEN MATCH_MP_TAC THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN `valuation D ((iy |-> u) (vbase:num->A))` ASSUME_TAC THENL
     [ASM_SIMP_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
    SUBGOAL_THEN `!i. bname D (E:A->A->bool) B (((iy |-> u) (vbase:num->A)) i)`
      ASSUME_TAC THENL
     [X_GEN_TAC `i:num` THEN ASM_CASES_TAC `i:num = iy` THEN
      ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER]; ALL_TAC] THEN
    MP_TAC(ISPECL [`p:form`; `D:A->bool`; `E:A->A->bool`; `B:A`; `leq:A`;
      `(iy |-> u) (vbase:num->A)`] BVAL_TOTAL) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(X_CHOOSE_THEN `w:A` STRIP_ASSUME_TAC) THEN
    EXISTS_TAC `w:A` THEN ASM_REWRITE_TAC[] THEN
    X_GEN_TAC `w':A` THEN STRIP_TAC THEN
    MATCH_MP_TAC(ISPECL [`p:form`; `D:A->bool`; `E:A->A->bool`; `B:A`; `leq:A`;
      `(iy |-> u) (vbase:num->A)`; `w':A`; `w:A`] BVAL_UNIQUE) THEN
    ASM_REWRITE_TAC[] THEN
    USE_THEN "bridge" (MP_TAC o SPECL [`u:A`; `w':A`]) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[];
      DISCH_THEN(fun th -> REWRITE_TAC[GSYM th]) THEN ASM_REWRITE_TAC[]];
    ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `S:A` STRIP_ASSUME_TAC) THEN
  SUBGOAL_THEN
   `!z. z IN D
      ==> (E z S <=> ?s. s IN D /\ E s dd /\
                         bval D (E:A->A->bool) B leq
                           ((iy |-> (s:A)) vbase) p z)`
   ASSUME_TAC THENL
   [X_GEN_TAC `z:A` THEN DISCH_TAC THEN
    FIRST_X_ASSUM(fun th -> MP_TAC(SPEC `z:A` th)) THEN ASM_REWRITE_TAC[] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    MATCH_MP_TAC EXISTS_AND_CONG THEN X_GEN_TAC `s:A` THEN STRIP_TAC THEN
    USE_THEN "bridge" (MP_TAC o SPECL [`s:A`; `z:A`]) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[];
      DISCH_THEN(fun th -> REWRITE_TAC[th])];
    ALL_TAC] THEN
  SUBGOAL_THEN `esubset D (E:A->A->bool) S B` ASSUME_TAC THENL
   [REWRITE_TAC[esubset] THEN X_GEN_TAC `z:A` THEN STRIP_TAC THEN
    FIRST_X_ASSUM(fun th -> MP_TAC(SPEC `z:A` th)) THEN ASM_REWRITE_TAC[] THEN
    DISCH_THEN(X_CHOOSE_THEN `s:A` STRIP_ASSUME_TAC) THEN
    MATCH_MP_TAC(ISPECL [`p:form`; `D:A->bool`; `E:A->A->bool`; `B:A`; `leq:A`;
      `(iy |-> (s:A)) (vbase:num->A)`; `z:A`] BVAL_IN_B) THEN
    ASM_REWRITE_TAC[] THEN MATCH_MP_TAC VALUATION_VALMOD THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  EXISTS_TAC `S:A` THEN ASM_REWRITE_TAC[]);;

(* ================================================================== *)
(* V^B REPLACEMENT axiom: stabilization, step 3.                      *)
(* Object-formula layer for the rank function rho used to bound the    *)
(* B-name-stage at which each forcing value [[p(ss,tt)]] is achieved.  *)
(*                                                                     *)
(*   ach_form f iy r  = "there is s in the B-name stage W_{v r} with   *)
(*                       Q s", where Q s <=> holds ..f.. (witness slot  *)
(*                       32+iy = s, stage slot 11).                     *)
(*   achrank_form ff iy r = Phi_least: "v r is the LEAST ordinal alpha  *)
(*                       at which the value read by ff is achieved by a *)
(*                       stage-alpha witness".                          *)
(*                                                                     *)
(* Templates: instage_bn_form / HOLDS_INSTAGE_BN_FORM for              *)
(* ach_form (recapp3_form relocates the stage recursion to slots        *)
(* r,11 while KEEPING B in slot 2); bnrankp_form /                      *)
(* HOLDS_BNRANKP_FORM for achrank_form.  See                            *)
(* [[forcing-replacement-design]] STABILIZATION Steps 3-tail..5.        *)
(* ================================================================== *)

(* ----- ach_form: exists s in the B-name stage W_{v r} with Q s ----- *)
(* NB the top REWRITE[HOLDS_EX;HOLDS_AND;holds] expands BOTH the outer  *)
(* ??11 and the inner ??(32+iy); so "inner" is stated in EXPANDED form. *)

let ach_form = new_definition
  `ach_form f iy r =
     ?? 11 (recapp3_form (rec_form bname_step_form 3) r 11 &&
            ?? (32 + iy) (((32 + iy) %% 11) && f))`;;

let HOLDS_ACH_FORM = prove
 (`!D (E:A->A->bool) v f iy r Q.
      model D E ZF_AX /\ valuation D v /\
      ~(r = 3) /\ ~(r = 4) /\ ~(r = 11) /\ ~(32 + iy = 11) /\
      (!s y. s IN D /\ y IN D
             ==> (holds D E (((32 + iy) |-> s) ((11 |-> y) v)) f <=> Q s))
      ==> (holds D E v (ach_form f iy r) <=>
           ?y. y IN D /\ ebnstage D E (v 2) (v r) y /\
               (?s. s IN D /\ E s y /\ Q s))`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `!x. (v:num->A) x IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[valuation]; ALL_TAC] THEN
  REWRITE_TAC[ach_form] THEN
  REWRITE_TAC[HOLDS_EX; HOLDS_AND; holds] THEN
  (* recapp3 conjunct semantics at (11|->y)v *)
  SUBGOAL_THEN
   `!y:A. y IN D
      ==> (holds D E ((11 |-> y) v)
             (recapp3_form (rec_form bname_step_form 3) r 11) <=>
           ebnstage D E (v 2) (v r) y)`
  (LABEL_TAC "rec") THENL
   [X_GEN_TAC `y:A` THEN DISCH_TAC THEN
    SUBGOAL_THEN `valuation D ((11 |-> (y:A)) v)` ASSUME_TAC THENL
     [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `(11 |-> (y:A)) v`;
                  `r:num`; `11`] HOLDS_RECAPP3_BNSTEP) THEN
    ASM_REWRITE_TAC[ARITH_RULE `~(11 = 3) /\ ~(11 = 4)`] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER; ARITH_RULE `~(11 = 2)`];
    ALL_TAC] THEN
  (* inner exists-s, EXPANDED to match the post-REWRITE goal *)
  SUBGOAL_THEN
   `!y:A. y IN D
      ==> ((?s. s IN D /\
                (E ((((32 + iy) |-> s) ((11 |-> y) v)) (32 + iy))
                   ((((32 + iy) |-> s) ((11 |-> y) v)) 11) /\
                 holds D E (((32 + iy) |-> s) ((11 |-> y) v)) f)) <=>
           (?s. s IN D /\ E s y /\ Q s))`
  (LABEL_TAC "inner") THENL
   [X_GEN_TAC `y:A` THEN DISCH_TAC THEN
    MATCH_MP_TAC(MESON[]
     `(!s:A. s IN D ==> (P s <=> R s))
      ==> ((?s. s IN (D:A->bool) /\ P s) <=> (?s. s IN D /\ R s))`) THEN
    X_GEN_TAC `s:A` THEN DISCH_TAC THEN
    ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER; ARITH_RULE `~(11 = 32 + iy)`];
    ALL_TAC] THEN
  (* combine via exists-y congruence *)
  MATCH_MP_TAC(MESON[]
   `(!y:A. y IN D ==> (P y <=> R y))
    ==> ((?y. y IN (D:A->bool) /\ P y) <=> (?y. y IN D /\ R y))`) THEN
  X_GEN_TAC `y:A` THEN DISCH_TAC THEN
  USE_THEN "rec" (fun th -> ASSUME_TAC(MATCH_MP th (ASSUME `(y:A) IN D`))) THEN
  USE_THEN "inner"
    (fun th -> ASSUME_TAC(MATCH_MP th (ASSUME `(y:A) IN D`))) THEN
  ASM_REWRITE_TAC[]);;

(* ----- achrank_form: v r is the LEAST ordinal alpha achieving the value *)
(* ----- *)

let achrank_form = new_definition
  `achrank_form ff iy r =
     ordinal_form r &&
     ach_form ff iy r &&
     (!!- 12 r (Not (ach_form ff iy 12)))`;;

let HOLDS_ACHRANK_FORM = prove
 (`!D (E:A->A->bool) v ff iy r Q.
      model D E ZF_AX /\ valuation D v /\
      ~(r = 3) /\ ~(r = 4) /\ ~(r = 11) /\ ~(r = 12) /\
      (!s y. s IN D /\ y IN D
             ==> (holds D E (((32 + iy) |-> s) ((11 |-> y) v)) ff <=> Q s)) /\
      (!s y c. s IN D /\ y IN D /\ c IN D
             ==> (holds D E (((32 + iy) |-> s) ((11 |-> y) ((12 |-> c) v))) ff
                  <=> Q s))
      ==> (holds D E v (achrank_form ff iy r) <=>
           eordinal D E (v r) /\
           (?y. y IN D /\ ebnstage D E (v 2) (v r) y /\
                (?s. s IN D /\ E s y /\ Q s)) /\
           (!c. c IN D /\ E c (v r)
                ==> ~(?y. y IN D /\ ebnstage D E (v 2) c y /\
                          (?s. s IN D /\ E s y /\ Q s))))`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `!x. (v:num->A) x IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[valuation]; ALL_TAC] THEN
  REWRITE_TAC[achrank_form] THEN REWRITE_TAC[HOLDS_AND] THEN
  ASM_SIMP_TAC[HOLDS_ORDINAL_FORM] THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`v:num->A`;`ff:form`;
               `iy:num`;`r:num`;`Q:A->bool`] HOLDS_ACH_FORM) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[] THEN ARITH_TAC; ALL_TAC] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  SUBGOAL_THEN
   `holds (D:A->bool) E (v:num->A) (!!- 12 r (Not(ach_form ff iy 12))) <=>
    (!c. c IN D /\ E c (v r)
         ==> ~(?y. y IN D /\ ebnstage D E (v 2) c y /\
                   (?s. s IN D /\ E s y /\ Q s)))`
  ASSUME_TAC THENL
   [MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`v:num->A`;`12`;`r:num`;
                   `Not(ach_form ff iy 12)`] HOLDS_FORALLMEM) THEN
    ANTS_TAC THENL [ASM_ARITH_TAC; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    REWRITE_TAC[HOLDS_NOT] THEN
    MATCH_MP_TAC(MESON[]
     `(!a:A. G a ==> (P a <=> R a))
      ==> ((!a. G a ==> ~(P a)) <=> (!c. G c ==> ~(R c)))`) THEN
    X_GEN_TAC `c:A` THEN STRIP_TAC THEN
    MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`(12 |-> (c:A)) v`;`ff:form`;
                 `iy:num`;`12`;`Q:A->bool`] HOLDS_ACH_FORM) THEN
    ANTS_TAC THENL
     [ASM_SIMP_TAC[VALUATION_VALMOD] THEN REPEAT CONJ_TAC THEN
      TRY ARITH_TAC THEN
      REPEAT GEN_TAC THEN STRIP_TAC THEN
      FIRST_X_ASSUM(fun th -> MP_TAC(SPECL [`s:A`;`y:A`;`c:A`] th)) THEN
      ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER; ARITH_EQ];
    ALL_TAC] THEN
  ASM_REWRITE_TAC[]);;

(* The E-least ordinal with a property P is unique (P opaque, so MESON   *)
(* stays shallow).                                                        *)
let LEAST_ORD_UNIQUE = prove
 (`!D (E:A->A->bool) (P:A->bool) a a'.
      model D E ZF_AX /\
      eordinal D E a /\ P a /\ (!c. c IN D /\ E c a ==> ~P c) /\
      eordinal D E a' /\ P a' /\ (!c. c IN D /\ E c a' ==> ~P c)
      ==> a = a'`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `(a:A) IN D /\ (a':A) IN D` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[EORDINAL_IN]; ALL_TAC] THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`a:A`;`a':A`]
         EORDINAL_TRICHOTOMY) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  STRIP_TAC THEN ASM_MESON_TAC[]);;

(* Optimized ACHRANK_HOLDS_BRIDGE.
   Perf fix: plain ARITH_TAC (no auto-pull) with only needed hyps UNDISCH'd,
   all disequality arithmetic hoisted into two up-front lemmas.
   Correctness fix: v is ABBREV'd, so ASM_SIMP cannot reduce v(32+i) on its
   own; add the up-front fact  !j. v(32+j) = vbase j  (holds unconditionally
   since r<32, r_val<32 force 32+j <> r, 32+j <> r_val, then the w0 hyp). *)
let ACHRANK_HOLDS_BRIDGE = prove
 (`!D (E:A->A->bool) B leq vbase p fp iy r_val r w0 b alpha.
      model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
      valuation D vbase /\ valuation D w0 /\
      w0 2 = B /\ w0 3 = leq /\ (!i. w0 (32 + i) = vbase i) /\
      ~(r_val = 2) /\ ~(r_val = 3) /\ ~(r_val = 4) /\ ~(r_val = 11) /\
        ~(r_val = 12) /\
      ~(r = 2) /\ ~(r = 3) /\ ~(r = 4) /\ ~(r = 11) /\ ~(r = 12) /\
        ~(r = r_val) /\
      ~(32 + iy = 11) /\ ~(32 + iy = r_val) /\ ~(32 + iy = r) /\
      r_val < 32 /\ r < 32 /\
      (!v. valuation D v
           ==> (holds D E v fp <=>
                bval D E (v 2) (v 3) (\i. v (32 + i)) p (v r_val))) /\
      b IN D /\ alpha IN D
      ==> (holds D E ((r |-> alpha) ((r_val |-> b) w0))
           (achrank_form fp iy r) <=>
           eordinal D E alpha /\
           (?y. y IN D /\ ebnstage D E B alpha y /\
                (?s. s IN D /\ E s y /\
                 bval D E B leq ((iy |-> s) vbase) p b)) /\
           (!c. c IN D /\ E c alpha
                ==> ~(?y. y IN D /\ ebnstage D E B c y /\
                          (?s. s IN D /\ E s y /\
                               bval D E B leq ((iy |-> s) vbase) p b))))`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  (* --- constant/r/r_val disequality batch: plain ARITH, only needed hyps *)
  (* --- *)
  SUBGOAL_THEN
   `~(2 = r) /\ ~(2 = r_val) /\ ~(3 = r) /\ ~(3 = r_val) /\ ~(r_val = r) /\
    ~(2 = 32 + iy) /\ ~(2 = 11) /\ ~(2 = 12) /\
    ~(3 = 32 + iy) /\ ~(3 = 11) /\ ~(3 = 12) /\
    ~(r_val = 32 + iy) /\ ~(r_val = 11) /\ ~(r_val = 12)`
   STRIP_ASSUME_TAC THENL
   [MAP_EVERY UNDISCH_TAC
     [`~(r = 2)`; `~(r_val = 2)`; `~(r = 3)`; `~(r_val = 3)`;
      `~(r = r_val:num)`;
      `~(r_val = 11)`; `~(r_val = 12)`; `r_val < 32`] THEN
    ARITH_TAC;
    ALL_TAC] THEN
  (* --- universal-i disequality lemma, one plain-ARITH call --- *)
  SUBGOAL_THEN
   `!i:num. ~(i = iy)
       ==> ~(32 + i = 32 + iy) /\ ~(32 + i = 11) /\ ~(32 + i = 12) /\
           ~(32 + i = r) /\ ~(32 + i = r_val)`
   ASSUME_TAC THENL
   [GEN_TAC THEN DISCH_TAC THEN
    UNDISCH_TAC `~(i:num = iy)` THEN UNDISCH_TAC `r < 32` THEN
    UNDISCH_TAC `r_val < 32` THEN ARITH_TAC;
    ALL_TAC] THEN
  ABBREV_TAC `v = (r |-> (alpha:A)) ((r_val |-> (b:A)) (w0:num->A))` THEN
  SUBGOAL_THEN `valuation D (v:num->A)` ASSUME_TAC THENL
   [EXPAND_TAC "v" THEN ASM_SIMP_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
  SUBGOAL_THEN `(v:num->A) 2 = B /\ (v:num->A) 3 = leq /\
                (v:num->A) r = alpha /\ (v:num->A) r_val = b`
    STRIP_ASSUME_TAC THENL
   [EXPAND_TAC "v" THEN ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER]; ALL_TAC] THEN
  (* --- the crux helper: v(32+j) collapses to vbase j (32+j is never *)
  (* r/r_val) --- *)
  SUBGOAL_THEN `!j:num. (v:num->A) (32 + j) = vbase j` ASSUME_TAC THENL
   [GEN_TAC THEN EXPAND_TAC "v" THEN
    SUBGOAL_THEN `~(32 + j = r) /\ ~(32 + j = r_val)` STRIP_ASSUME_TAC THENL
     [UNDISCH_TAC `r < 32` THEN UNDISCH_TAC `r_val < 32` THEN ARITH_TAC;
      ALL_TAC] THEN
    ASM_SIMP_TAC[VALMOD_OTHER];
    ALL_TAC] THEN
  MP_TAC(ISPECL
    [`D:A->bool`; `E:A->A->bool`; `v:num->A`; `fp:form`; `iy:num`; `r:num`;
     `\s:A. bval D E B leq ((iy |-> s) vbase) p b`] HOLDS_ACHRANK_FORM) THEN
  ANTS_TAC THENL
   [REPEAT CONJ_TAC THEN TRY(FIRST_ASSUM ACCEPT_TAC) THENL
     [(* conjunct 1: W = v *)
      MAP_EVERY X_GEN_TAC [`s:A`; `y:A`] THEN STRIP_TAC THEN
      FIRST_X_ASSUM(fun th ->
        MP_TAC(SPEC
               `((32 + iy) |-> (s:A)) ((11 |-> (y:A)) (v:num->A))` th)) THEN
      ANTS_TAC THENL [ASM_SIMP_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
      ASM_SIMP_TAC[VALMOD_OTHER] THEN
      MATCH_MP_TAC BVAL_FV THEN X_GEN_TAC `i:num` THEN DISCH_TAC THEN
      BETA_TAC THEN
      ASM_CASES_TAC `i:num = iy` THENL
       [ASM_REWRITE_TAC[VALMOD_BASIC];
        FIRST_ASSUM(fun th ->
          STRIP_ASSUME_TAC(MATCH_MP th (ASSUME `~(i:num = iy)`))) THEN
        ASM_SIMP_TAC[VALMOD_OTHER]];
      (* conjunct 2: W = (12|->c)v *)
      MAP_EVERY X_GEN_TAC [`s:A`; `y:A`; `c:A`] THEN STRIP_TAC THEN
      FIRST_X_ASSUM(fun th ->
        MP_TAC(SPEC
               `((32 + iy) |-> (s:A))
                ((11 |-> (y:A)) ((12 |-> (c:A)) (v:num->A)))` th)) THEN
      ANTS_TAC THENL [ASM_SIMP_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
      ASM_SIMP_TAC[VALMOD_OTHER] THEN
      MATCH_MP_TAC BVAL_FV THEN X_GEN_TAC `i:num` THEN DISCH_TAC THEN
      BETA_TAC THEN
      ASM_CASES_TAC `i:num = iy` THENL
       [ASM_REWRITE_TAC[VALMOD_BASIC];
        FIRST_ASSUM(fun th ->
          STRIP_ASSUME_TAC(MATCH_MP th (ASSUME `~(i:num = iy)`))) THEN
        ASM_SIMP_TAC[VALMOD_OTHER]]];
    ALL_TAC] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN ASM_REWRITE_TAC[]);;
(* Existence of the least achieving B-name stage rank for a value b that is
   realized by some bname a0 (i.e. bval((iy|->a0)vbase) p b holds).
   BNAME_RANK gives an ordinal seed ra with a0 in W_ra, so the "achieving"
   predicate holds at ra; EORDINAL_LEAST on ach_form fp iy 0 then picks the
   least such ordinal, whose HOLDS_ACH_FORM reading is exactly the achrank
   semantics.  Discharges clause (ii) of the rho-image (every b in V_ss has a
   least achiever, which will land in A = rho[V_ss]). *)
let ACHRANK_EXISTS = prove
 (`!D (E:A->A->bool) B leq vbase p fp iy r_val w0 b a0.
      model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
      valuation D vbase /\ valuation D w0 /\
      w0 2 = B /\ w0 3 = leq /\ (!i. w0 (32 + i) = vbase i) /\
      ~(r_val = 0) /\ ~(r_val = 2) /\ ~(r_val = 3) /\ ~(r_val = 4) /\
      ~(r_val = 11) /\ ~(r_val = 12) /\
      ~(32 + iy = 11) /\ ~(32 + iy = r_val) /\
      r_val < 32 /\
      (!v. valuation D v
           ==> (holds D E v fp <=>
                bval D E (v 2) (v 3) (\i. v (32 + i)) p (v r_val))) /\
      b IN D /\ a0 IN D /\ bname D E B a0 /\
      bval D E B leq ((iy |-> a0) vbase) p b
      ==> ?alpha. alpha IN D /\ eordinal D E alpha /\
                  (?y. y IN D /\ ebnstage D E B alpha y /\
                       (?s. s IN D /\ E s y /\
                        bval D E B leq ((iy |-> s) vbase) p b)) /\
                  (!c. c IN D /\ E c alpha
                       ==> ~(?y. y IN D /\ ebnstage D E B c y /\
                                 (?s. s IN D /\ E s y /\
                                      bval D E B leq
                                        ((iy |-> s) vbase) p b)))`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `~(0 = 3) /\ ~(0 = 4) /\ ~(0:num = 11)` STRIP_ASSUME_TAC THENL
   [ARITH_TAC; ALL_TAC] THEN
  SUBGOAL_THEN
   `~(2 = r_val) /\ ~(3 = r_val) /\ ~(2 = 0) /\ ~(3 = 0) /\
    ~(2 = 32 + iy) /\ ~(2 = 11) /\ ~(3 = 32 + iy) /\ ~(3 = 11) /\
    ~(r_val = 32 + iy) /\ ~(r_val = 11) /\ ~(0 = 32 + iy) /\ ~(0 = 11) /\
    ~(0 = r_val)`
   STRIP_ASSUME_TAC THENL
   [MAP_EVERY UNDISCH_TAC
     [`~(r_val = 0)`; `~(r_val = 2)`; `~(r_val = 3)`; `~(r_val = 11)`;
      `~(32 + iy = r_val)`] THEN ARITH_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!i:num. ~(i = iy)
       ==> ~(32 + i = 32 + iy) /\ ~(32 + i = 11) /\ ~(32 + i = 0) /\
           ~(32 + i = r_val)`
   ASSUME_TAC THENL
   [GEN_TAC THEN DISCH_TAC THEN UNDISCH_TAC `~(i:num = iy)` THEN
    UNDISCH_TAC `r_val < 32` THEN ARITH_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN `!j:num. ~(32 + j = 0) /\ ~(32 + j = r_val)` ASSUME_TAC THENL
   [GEN_TAC THEN UNDISCH_TAC `r_val < 32` THEN ARITH_TAC; ALL_TAC] THEN
  ABBREV_TAC `vv = (r_val |-> (b:A)) (w0:num->A)` THEN
  SUBGOAL_THEN `valuation D (vv:num->A)` ASSUME_TAC THENL
   [EXPAND_TAC "vv" THEN ASM_SIMP_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
  SUBGOAL_THEN
    `(vv:num->A) 2 = B /\ (vv:num->A) 3 = leq /\ (vv:num->A) r_val = b`
    STRIP_ASSUME_TAC THENL
   [EXPAND_TAC "vv" THEN ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER];
    ALL_TAC] THEN
  SUBGOAL_THEN `!j:num. (vv:num->A) (32 + j) = vbase j` ASSUME_TAC THENL
   [GEN_TAC THEN EXPAND_TAC "vv" THEN ASM_SIMP_TAC[VALMOD_OTHER]; ALL_TAC] THEN
  (* the ach_form reading at any ordinal argument d *)
  SUBGOAL_THEN
   `!d:A. d IN D
      ==> (holds D E ((0 |-> d) vv) (ach_form fp iy 0) <=>
           ?y. y IN D /\ ebnstage D E B d y /\
               (?s. s IN D /\ E s y /\ bval D E B leq ((iy |-> s) vbase) p b))`
   (LABEL_TAC "achP") THENL
   [X_GEN_TAC `d:A` THEN DISCH_TAC THEN
    SUBGOAL_THEN `valuation D ((0 |-> (d:A)) vv)` ASSUME_TAC THENL
     [ASM_SIMP_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
    MP_TAC(ISPECL
      [`D:A->bool`; `E:A->A->bool`; `(0 |-> (d:A)) vv`; `fp:form`;
       `iy:num`; `0`;
       `\s:A. bval D E B leq ((iy |-> s) vbase) p b`] HOLDS_ACH_FORM) THEN
    ANTS_TAC THENL
     [REPEAT CONJ_TAC THEN TRY(FIRST_ASSUM ACCEPT_TAC) THEN
      MAP_EVERY X_GEN_TAC [`s:A`; `y:A`] THEN STRIP_TAC THEN
      FIRST_X_ASSUM(fun th ->
        MP_TAC(SPEC
               `((32 + iy) |-> (s:A))
                ((11 |-> (y:A)) ((0 |-> (d:A)) vv))` th)) THEN
      ANTS_TAC THENL [ASM_SIMP_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
      ASM_SIMP_TAC[VALMOD_OTHER] THEN
      MATCH_MP_TAC BVAL_FV THEN X_GEN_TAC `i:num` THEN DISCH_TAC THEN
      BETA_TAC THEN
      ASM_CASES_TAC `i:num = iy` THENL
       [ASM_REWRITE_TAC[VALMOD_BASIC];
        FIRST_ASSUM(fun th ->
          STRIP_ASSUME_TAC(MATCH_MP th (ASSUME `~(i:num = iy)`))) THEN
        ASM_SIMP_TAC[VALMOD_OTHER]];
      ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER];
    ALL_TAC] THEN
  (* seed the least-ordinal search with ra = the B-name rank of a0 *)
  MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `B:A`; `a0:A`] BNAME_RANK) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `ra:A`
    (CONJUNCTS_THEN2 ASSUME_TAC
     (CONJUNCTS_THEN2 ASSUME_TAC
      (CONJUNCTS_THEN2 (X_CHOOSE_THEN `y0:A` STRIP_ASSUME_TAC)
       ASSUME_TAC)))) THEN
  SUBGOAL_THEN `holds D E ((0 |-> (ra:A)) vv) (ach_form fp iy 0)`
    ASSUME_TAC THENL
   [USE_THEN "achP" (MP_TAC o SPEC `ra:A`) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    EXISTS_TAC `y0:A` THEN ASM_REWRITE_TAC[] THEN
    EXISTS_TAC `a0:A` THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  MP_TAC(ISPECL
    [`D:A->bool`; `E:A->A->bool`; `ach_form fp iy 0`; `vv:num->A`; `ra:A`]
    EORDINAL_LEAST) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `alpha:A` STRIP_ASSUME_TAC) THEN
  EXISTS_TAC `alpha:A` THEN ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
   [USE_THEN "achP" (MP_TAC o SPEC `alpha:A`) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[GSYM th]) THEN ASM_REWRITE_TAC[];
    X_GEN_TAC `c:A` THEN STRIP_TAC THEN
    USE_THEN "achP" (MP_TAC o SPEC `c:A`) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[GSYM th]) THEN
    FIRST_X_ASSUM(MP_TAC o SPEC `c:A`) THEN ASM_REWRITE_TAC[]]);;

(* RHO_IMAGE_EXISTS: A = rho[V_ss], the set of least-achieving B-name stage
   ranks of the forcing values in V_ss.  Built by ZF_REPLACEMENT along
   achrank_form (functional by LEAST_ORD_UNIQUE); each value's achiever
   exists by ACHRANK_EXISTS; the holds<->rho-semantics bridge is
   ACHRANK_HOLDS_BRIDGE.  Delivers: A is a set of ordinals, and every value
   b in V_ss has an achieving rank alpha in A with a stage-alpha witness s
   realizing b. *)
let RHO_IMAGE_EXISTS = prove
 (`!D (E:A->A->bool) B leq vbase p fp iy r_val r w0 Vss.
      model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
      valuation D vbase /\ valuation D w0 /\
      w0 2 = B /\ w0 3 = leq /\ (!i. w0 (32 + i) = vbase i) /\
      ~(r_val = 0) /\ ~(r_val = 2) /\ ~(r_val = 3) /\ ~(r_val = 4) /\
      ~(r_val = 11) /\ ~(r_val = 12) /\
      ~(r = 2) /\ ~(r = 3) /\ ~(r = 4) /\ ~(r = 11) /\ ~(r = 12) /\
        ~(r = r_val) /\
      ~(32 + iy = 11) /\ ~(32 + iy = r_val) /\ ~(32 + iy = r) /\
      r_val < 32 /\ r < 32 /\
      (!v. valuation D v
           ==> (holds D E v fp <=>
                bval D E (v 2) (v 3) (\i. v (32 + i)) p (v r_val))) /\
      Vss IN D /\
      (!b. b IN D
           ==> (E b Vss <=>
                ?a. a IN D /\ bname D E B a /\
                    bval D E B leq ((iy |-> a) vbase) p b))
      ==> ?A. A IN D /\
              (!alpha. alpha IN D /\ E alpha A ==> eordinal D E alpha) /\
              (!b. b IN D /\ E b Vss
                   ==> ?alpha. alpha IN D /\ E alpha A /\
                               (?y. y IN D /\ ebnstage D E B alpha y /\
                                    (?s. s IN D /\ E s y /\
                                         bval D E B leq
                                           ((iy |-> s) vbase) p b)))`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `~(r_val:num = r)` ASSUME_TAC THENL
   [UNDISCH_TAC `~(r = r_val:num)` THEN ARITH_TAC; ALL_TAC] THEN
  (* ---------------- apply ZF_REPLACEMENT along achrank_form *)
  (* ---------------- *)
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`] ZF_REPLACEMENT) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(MP_TAC o SPECL
    [`achrank_form fp iy r`; `r_val:num`; `r:num`; `w0:num->A`; `Vss:A`]) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[] THEN
    (* functionality: each value bb in Vss has a unique achieving rank *)
    X_GEN_TAC `bb:A` THEN STRIP_TAC THEN
    SUBGOAL_THEN
     `?a:A. a IN D /\ bname D E B a /\ bval D E B leq ((iy |-> a) vbase) p bb`
     (X_CHOOSE_THEN `a0:A` STRIP_ASSUME_TAC) THENL
     [FIRST_ASSUM(fun th ->
        FIRST_ASSUM(fun h ->
          ACCEPT_TAC(EQ_MP
                     (MATCH_MP (SPEC `bb:A` th) (ASSUME `(bb:A) IN D`)) h)));
      ALL_TAC] THEN
    MP_TAC(ISPECL
      [`D:A->bool`; `E:A->A->bool`; `B:A`; `leq:A`; `vbase:num->A`; `p:form`;
       `fp:form`; `iy:num`; `r_val:num`; `w0:num->A`; `bb:A`; `a0:A`]
      ACHRANK_EXISTS) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    INTRO_TAC "@alpha. alphaD ordalpha h h2" THEN
    EXISTS_TAC `alpha:A` THEN CONJ_TAC THENL
    [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    X_GEN_TAC `w':A` THEN STRIP_TAC THEN
    MP_TAC(ISPECL
      [`D:A->bool`; `E:A->A->bool`; `B:A`; `leq:A`; `vbase:num->A`; `p:form`;
       `fp:form`; `iy:num`; `r_val:num`; `r:num`; `w0:num->A`; `bb:A`; `w':A`]
      ACHRANK_HOLDS_BRIDGE) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun bridge ->
      FIRST_X_ASSUM(fun h ->
        (CONJUNCTS_THEN2 ASSUME_TAC
         (CONJUNCTS_THEN2 ASSUME_TAC ASSUME_TAC))(EQ_MP bridge h))) THEN
    MP_TAC(BETA_RULE(ISPECL
      [`D:A->bool`; `E:A->A->bool`;
       `\c:A. ?y. y IN D /\ ebnstage D E B c y /\
                 (?s. s IN D /\ E s y /\
                      bval D E B leq ((iy |-> s) vbase) p bb)`;
       `w':A`; `alpha:A`]
      LEAST_ORD_UNIQUE)) THEN
    ANTS_TAC THENL
     [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
      DISCH_THEN ACCEPT_TAC];
    ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `Aset:A`
             (CONJUNCTS_THEN2 ASSUME_TAC (LABEL_TAC "Ach"))) THEN
  EXISTS_TAC `Aset:A` THEN ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
   [(* ---- A is a set of ordinals ---- *)
    X_GEN_TAC `alpha:A` THEN STRIP_TAC THEN
    USE_THEN "Ach" (MP_TAC o SPEC `alpha:A`) THEN
    ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN(fun th ->
      FIRST_ASSUM(fun h -> X_CHOOSE_THEN `u:A` STRIP_ASSUME_TAC
                  (EQ_MP th h))) THEN
    MP_TAC(ISPECL
      [`D:A->bool`; `E:A->A->bool`; `B:A`; `leq:A`; `vbase:num->A`; `p:form`;
       `fp:form`; `iy:num`; `r_val:num`; `r:num`; `w0:num->A`;
       `u:A`; `alpha:A`]
      ACHRANK_HOLDS_BRIDGE) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun bridge ->
      FIRST_X_ASSUM(fun h -> STRIP_ASSUME_TAC(EQ_MP bridge h))) THEN
    FIRST_ASSUM ACCEPT_TAC;
    (* ---- every value b in Vss has an achieving rank in A ---- *)
    X_GEN_TAC `bb:A` THEN STRIP_TAC THEN
    SUBGOAL_THEN
     `?a:A. a IN D /\ bname D E B a /\ bval D E B leq ((iy |-> a) vbase) p bb`
     (X_CHOOSE_THEN `a0:A` STRIP_ASSUME_TAC) THENL
     [FIRST_ASSUM(fun th ->
        FIRST_ASSUM(fun h ->
          ACCEPT_TAC(EQ_MP
                     (MATCH_MP (SPEC `bb:A` th) (ASSUME `(bb:A) IN D`)) h)));
      ALL_TAC] THEN
    MP_TAC(ISPECL
      [`D:A->bool`; `E:A->A->bool`; `B:A`; `leq:A`; `vbase:num->A`; `p:form`;
       `fp:form`; `iy:num`; `r_val:num`; `w0:num->A`; `bb:A`; `a0:A`]
      ACHRANK_EXISTS) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    INTRO_TAC "@alpha. alphaD ordalpha achv h" THEN
    EXISTS_TAC `alpha:A` THEN REPEAT CONJ_TAC THENL
     [FIRST_ASSUM ACCEPT_TAC;
      (* alpha IN A via the image characterization *)
      USE_THEN "Ach" (MP_TAC o SPEC `alpha:A`) THEN
      ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
      EXISTS_TAC `bb:A` THEN REPEAT CONJ_TAC THENL
       [FIRST_ASSUM ACCEPT_TAC;
        FIRST_ASSUM ACCEPT_TAC;
        MP_TAC(ISPECL
          [`D:A->bool`; `E:A->A->bool`; `B:A`; `leq:A`;
           `vbase:num->A`; `p:form`;
           `fp:form`; `iy:num`; `r_val:num`; `r:num`; `w0:num->A`;
           `bb:A`; `alpha:A`]
          ACHRANK_HOLDS_BRIDGE) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
        DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
        REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC];
      USE_THEN "achv" ACCEPT_TAC]]);;
(* STABILIZE_LAMBDA: the collection/stabilization bound.  From RHO_IMAGE_EXISTS
   (A = rho[V_ss],
   a set of achieving ranks with an achiever in A for every value
   in V_ss) take lam = UNION A (an ordinal, EORDINAL_EUNION) and dd = W_lam
   (EBNSTAGE_EXISTS).  Every achiever rank alpha in A satisfies
     alpha SUBSET lam
   (EUNION_MEM), hence E alpha lam \/ alpha = lam (EORDINAL_SUBSET_MEMBER),
   so W_alpha SUBSET W_lam = dd (EBNSTAGE_MONO / EBNSTAGE_UNIQUE).  Therefore
   every value b in V_ss is realized by a witness s in the single stage dd. *)
let STABILIZE_LAMBDA = prove
 (`!D (E:A->A->bool) B leq vbase p fp iy r_val r w0 Vss.
      model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
      valuation D vbase /\ valuation D w0 /\
      w0 2 = B /\ w0 3 = leq /\ (!i. w0 (32 + i) = vbase i) /\
      ~(r_val = 0) /\ ~(r_val = 2) /\ ~(r_val = 3) /\ ~(r_val = 4) /\
      ~(r_val = 11) /\ ~(r_val = 12) /\
      ~(r = 2) /\ ~(r = 3) /\ ~(r = 4) /\ ~(r = 11) /\ ~(r = 12) /\
        ~(r = r_val) /\
      ~(32 + iy = 11) /\ ~(32 + iy = r_val) /\ ~(32 + iy = r) /\
      r_val < 32 /\ r < 32 /\
      (!v. valuation D v
           ==> (holds D E v fp <=>
                bval D E (v 2) (v 3) (\i. v (32 + i)) p (v r_val))) /\
      Vss IN D /\
      (!b. b IN D
           ==> (E b Vss <=>
                ?a. a IN D /\ bname D E B a /\
                    bval D E B leq ((iy |-> a) vbase) p b))
      ==> ?lam dd.
              eordinal D E lam /\ lam IN D /\
              dd IN D /\ ebnstage D E B lam dd /\
              (!b. b IN D /\ E b Vss
                   ==> ?s. s IN D /\ E s dd /\
                           bval D E B leq ((iy |-> s) vbase) p b)`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  MP_TAC(ISPECL
    [`D:A->bool`; `E:A->A->bool`; `B:A`; `leq:A`; `vbase:num->A`; `p:form`;
     `fp:form`; `iy:num`; `r_val:num`; `r:num`; `w0:num->A`; `Vss:A`]
    RHO_IMAGE_EXISTS) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `Aset:A`
    (CONJUNCTS_THEN2 ASSUME_TAC
     (CONJUNCTS_THEN2 (LABEL_TAC "Aord") (LABEL_TAC "Aach")))) THEN
  (* lam = UNION Aset *)
  MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `Aset:A`] EUNION_EXISTS) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `lam:A` (LABEL_TAC "un")) THEN
  SUBGOAL_THEN `(lam:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[EUNION_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `eordinal D (E:A->A->bool) lam` ASSUME_TAC THENL
   [MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `Aset:A`; `lam:A`]
      EORDINAL_EUNION) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC];
    ALL_TAC] THEN
  (* dd = W_lam *)
  MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `B:A`; `lam:A`]
         EBNSTAGE_EXISTS) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `dd:A` STRIP_ASSUME_TAC) THEN
  MAP_EVERY EXISTS_TAC [`lam:A`; `dd:A`] THEN
  REPEAT CONJ_TAC THEN TRY(FIRST_ASSUM ACCEPT_TAC) THEN
  (* the bounding property *)
  X_GEN_TAC `b:A` THEN STRIP_TAC THEN
  USE_THEN "Aach" (MP_TAC o SPEC `b:A`) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `alpha:A`
   (CONJUNCTS_THEN2 ASSUME_TAC
    (CONJUNCTS_THEN2 ASSUME_TAC
     (X_CHOOSE_THEN `y:A`
      (CONJUNCTS_THEN2 ASSUME_TAC
       (CONJUNCTS_THEN2 ASSUME_TAC
        (X_CHOOSE_THEN `s:A` STRIP_ASSUME_TAC))))))) THEN
  EXISTS_TAC `s:A` THEN ASM_REWRITE_TAC[] THEN
  (* remaining goal: E s dd *)
  SUBGOAL_THEN `eordinal D (E:A->A->bool) alpha` ASSUME_TAC THENL
   [USE_THEN "Aord" MATCH_MP_TAC THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `esubset D (E:A->A->bool) alpha lam` ASSUME_TAC THENL
   [REWRITE_TAC[esubset] THEN X_GEN_TAC `w:A` THEN STRIP_TAC THEN
    MP_TAC(ISPECL
           [`D:A->bool`; `E:A->A->bool`; `Aset:A`; `lam:A`; `alpha:A`; `w:A`]
           EUNION_MEM) THEN
    ASM_REWRITE_TAC[] THEN DISCH_THEN MATCH_ACCEPT_TAC;
    ALL_TAC] THEN
  MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `alpha:A`; `lam:A`]
    EORDINAL_SUBSET_MEMBER) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  STRIP_TAC THENL
   [(* E alpha lam : W_alpha SUBSET W_lam = dd via EBNSTAGE_MONO *)
    MP_TAC(ISPECL
      [`D:A->bool`; `E:A->A->bool`; `B:A`; `lam:A`; `alpha:A`; `dd:A`;
       `y:A`; `s:A`]
      EBNSTAGE_MONO) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC];
    (* alpha = lam : W_alpha = W_lam = dd via EBNSTAGE_UNIQUE *)
    FIRST_X_ASSUM SUBST_ALL_TAC THEN
    SUBGOAL_THEN `(y:A) = dd` ASSUME_TAC THENL
     [MP_TAC(ISPECL
        [`D:A->bool`; `E:A->A->bool`; `B:A`; `lam:A`; `y:A`; `dd:A`]
        EBNSTAGE_UNIQUE) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC];
      ALL_TAC] THEN
    ASM_MESON_TAC[]]);;

(* FUNC_EQ_FULL: formula-level wrap of the abstract EBV_FUNC_EQ.
   The functional premise of replacement, prem_ss = [[?? z (!! y (p -->
     Eq y z))]]_v0,
   is an upper bound on d;
   together with d <= [[p(ss,tt)]] and d <= [[p(ss,s)]] it
   forces d <= [[tt = s]] = ets.  Route:
     - per bname zz, fv(zz) = [[!! y (p --> Eq y z)]]_{(z|->zz)v0};
       BVALF_ALL_LB @ y:=tt/s + BVALF_IMP + BVALF_EQ2 + BVALF_FV_CONG (z
         not in FV p)
       give fv(zz) <= (pt ==> [tt=zz]) = i1 and fv(zz) <= (ps ==> [s=zz]) = i2;
     - EBV_FUNC_EQ @ d:=meet(fv(zz),w), w=meet(pt,ps),
     gives meet(fv(zz),w) <= ets;
     - EBIMP_LE_IMP lifts to fv(zz) <= (w ==> ets) = wimp;
     - BVALF_EX_LEAST lifts over zz to prem_ss <= wimp;
     - d <= prem_ss <= wimp, EBIMP_MEET_LE + EMEET_GREATEST give d <= ets. *)
let FUNC_EQ_FULL = prove
 (`!D (E:A->A->bool) B leq v0 p y z tt s d ets.
      model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
      valuation D v0 /\ (!i. bname D E B (v0 i)) /\
      bname D E B tt /\ bname D E B s /\ tt IN D /\ s IN D /\
      ~(z IN FV p) /\ ~(y = z) /\
      d IN D /\ E d B /\ ets IN D /\
      ebv_eq D E B leq tt s ets /\
      erel D E leq d (bvalf D E B leq v0 (?? z (!! y (p --> Eq y z)))) /\
      erel D E leq d (bvalf D E B leq ((y |-> tt) v0) p) /\
      erel D E leq d (bvalf D E B leq ((y |-> s) v0) p)
      ==> erel D E leq d ets`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `ebalg D (E:A->A->bool) B leq` ASSUME_TAC THENL
   [ASM_MESON_TAC[ECBA_IMP_BALG]; ALL_TAC] THEN
  SUBGOAL_THEN `eporder D (E:A->A->bool) B leq` ASSUME_TAC THENL
   [ASM_MESON_TAC[ECBA_IMP_PORDER]; ALL_TAC] THEN
  (* valuation + bname for the two image valuations *)
  SUBGOAL_THEN
   `valuation D ((y |-> tt) (v0:num->A)) /\
    (!i. bname D E B (((y |-> tt) (v0:num->A)) i)) /\
    valuation D ((y |-> s) (v0:num->A)) /\
    (!i. bname D E B (((y |-> s) (v0:num->A)) i))`
  STRIP_ASSUME_TAC THENL
   [REPEAT CONJ_TAC THENL
     [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[];
      MATCH_MP_TAC BNAMEVAL_VALMOD THEN ASM_REWRITE_TAC[];
      MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[];
      MATCH_MP_TAC BNAMEVAL_VALMOD THEN ASM_REWRITE_TAC[]];
    ALL_TAC] THEN
  (* pt, ps in D and in B *)
  SUBGOAL_THEN
   `(bvalf D (E:A->A->bool) B leq ((y |-> tt) v0) p) IN D /\
    (E:A->A->bool) (bvalf D E B leq ((y |-> tt) v0) p) B /\
    (bvalf D (E:A->A->bool) B leq ((y |-> s) v0) p) IN D /\
    (E:A->A->bool) (bvalf D E B leq ((y |-> s) v0) p) B`
  STRIP_ASSUME_TAC THENL
   [REPEAT CONJ_TAC THENL
     [MP_TAC(ISPECL [`p:form`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
        `(y |-> (tt:A)) (v0:num->A)`] BVALF_SPEC) THEN ASM_SIMP_TAC[];
      MP_TAC(ISPECL [`p:form`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
        `(y |-> (tt:A)) (v0:num->A)`] BVALF_IN_B) THEN ASM_SIMP_TAC[];
      MP_TAC(ISPECL [`p:form`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
        `(y |-> (s:A)) (v0:num->A)`] BVALF_SPEC) THEN ASM_SIMP_TAC[];
      MP_TAC(ISPECL [`p:form`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
        `(y |-> (s:A)) (v0:num->A)`] BVALF_IN_B) THEN ASM_SIMP_TAC[]];
    ALL_TAC] THEN
  (* E ets B *)
  SUBGOAL_THEN `(E:A->A->bool) ets B` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`tt:A`;
                  `s:A`;`ets:A`]
                 EBV_EQ_IN_B) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* w = meet(pt,ps) *)
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
    `bvalf D (E:A->A->bool) B leq ((y |-> tt) v0) p`;
    `bvalf D (E:A->A->bool) B leq ((y |-> s) v0) p`] EBALG_MEET) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `w:A` (LABEL_TAC "wmeet")) THEN
  SUBGOAL_THEN `(w:A) IN D /\ (E:A->A->bool) w B` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[EMEET_IN]; ALL_TAC] THEN
  SUBGOAL_THEN
   `erel D (E:A->A->bool) leq w (bvalf D E B leq ((y |-> tt) v0) p) /\
    erel D (E:A->A->bool) leq w (bvalf D E B leq ((y |-> s) v0) p)`
  STRIP_ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
      `bvalf D (E:A->A->bool) B leq ((y |-> tt) v0) p`;
      `bvalf D (E:A->A->bool) B leq ((y |-> s) v0) p`;`w:A`] EMEET_LE) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* wimp = (w ==> ets) *)
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`w:A`;`ets:A`]
         EBIMP_EXISTS) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `wimp:A` (LABEL_TAC "wimp")) THEN
  SUBGOAL_THEN `(wimp:A) IN D /\ (E:A->A->bool) wimp B` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[EBIMP_IN]; ALL_TAC] THEN
  (* ===== PERZ: for every bname zz, fv(zz) <= wimp ===== *)
  SUBGOAL_THEN
   `!zz. zz IN D /\ bname D E B zz
         ==> erel D (E:A->A->bool) leq
                (bvalf D E B leq ((z |-> zz) v0) (!! y (p --> Eq y z))) wimp`
  (LABEL_TAC "perz") THENL
   [X_GEN_TAC `zz:A` THEN STRIP_TAC THEN
    (* valuation/bname for (z|->zz)v0, (y|->tt)(z|->zz)v0, (y|->s)(z|->zz)v0 *)
    SUBGOAL_THEN
     `valuation D ((z |-> zz) (v0:num->A)) /\
      (!i. bname D E B (((z |-> zz) (v0:num->A)) i))`
    STRIP_ASSUME_TAC THENL
     [CONJ_TAC THENL
       [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[];
        MATCH_MP_TAC BNAMEVAL_VALMOD THEN ASM_REWRITE_TAC[]]; ALL_TAC] THEN
    SUBGOAL_THEN
     `valuation D ((y |-> tt) ((z |-> zz) (v0:num->A))) /\
      (!i. bname D E B (((y |-> tt) ((z |-> zz) (v0:num->A))) i)) /\
      valuation D ((y |-> s) ((z |-> zz) (v0:num->A))) /\
      (!i. bname D E B (((y |-> s) ((z |-> zz) (v0:num->A))) i))`
    STRIP_ASSUME_TAC THENL
     [REPEAT CONJ_TAC THENL
       [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[];
        MATCH_MP_TAC BNAMEVAL_VALMOD THEN ASM_REWRITE_TAC[];
        MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[];
        MATCH_MP_TAC BNAMEVAL_VALMOD THEN ASM_REWRITE_TAC[]]; ALL_TAC] THEN
    (* value slots of the two output valuations at y and z *)
    SUBGOAL_THEN
     `((y |-> tt) ((z |-> zz) (v0:num->A))) y = tt /\
      ((y |-> tt) ((z |-> zz) (v0:num->A))) z = zz /\
      ((y |-> s) ((z |-> zz) (v0:num->A))) y = s /\
      ((y |-> s) ((z |-> zz) (v0:num->A))) z = zz`
    STRIP_ASSUME_TAC THENL
     [REPEAT CONJ_TAC THEN
      ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER]; ALL_TAC] THEN
    (* congruence: bvalf ((y|->tt)(z|->zz)v0) p = bvalf ((y|->tt)v0) p *)
    SUBGOAL_THEN
     `bvalf D (E:A->A->bool) B leq ((y |-> tt) ((z |-> zz) v0)) p =
      bvalf D E B leq ((y |-> tt) v0) p`
    (LABEL_TAC "cgt") THENL
     [MATCH_MP_TAC(ISPECL [`p:form`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
        `(y |-> (tt:A)) ((z |-> zz) (v0:num->A))`;`(y |-> (tt:A)) (v0:num->A)`]
          BVALF_FV_CONG) THEN
      ASM_REWRITE_TAC[] THEN
      X_GEN_TAC `i:num` THEN DISCH_TAC THEN
      SUBGOAL_THEN `~(i:num = z)` ASSUME_TAC THENL
      [ASM_MESON_TAC[]; ALL_TAC] THEN
      REWRITE_TAC[VALMOD] THEN ASM_CASES_TAC `i:num = y` THEN
      ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    SUBGOAL_THEN
     `bvalf D (E:A->A->bool) B leq ((y |-> s) ((z |-> zz) v0)) p =
      bvalf D E B leq ((y |-> s) v0) p`
    (LABEL_TAC "cgs") THENL
     [MATCH_MP_TAC(ISPECL [`p:form`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
        `(y |-> (s:A)) ((z |-> zz) (v0:num->A))`;`(y |-> (s:A)) (v0:num->A)`]
            BVALF_FV_CONG) THEN
      ASM_REWRITE_TAC[] THEN
      X_GEN_TAC `i:num` THEN DISCH_TAC THEN
      SUBGOAL_THEN `~(i:num = z)` ASSUME_TAC THENL
      [ASM_MESON_TAC[]; ALL_TAC] THEN
      REWRITE_TAC[VALMOD] THEN ASM_CASES_TAC `i:num = y` THEN
      ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    (* fv(zz), i1, etz and the two clauses fv<=i1, ebv_eq tt zz etz, ebimp *)
    (* pt etz i1 *)
    SUBGOAL_THEN
     `erel D (E:A->A->bool) leq
        (bvalf D E B leq ((z |-> zz) v0) (!! y (p --> Eq y z)))
        (bvalf D E B leq ((y |-> tt) ((z |-> zz) v0)) (p --> Eq y z))`
    (LABEL_TAC "lb1") THENL
     [MP_TAC(ISPECL
             [`y:num`;`(p --> Eq y z):form`;`D:A->bool`;`E:A->A->bool`;`B:A`;
              `leq:A`;`(z |-> zz) (v0:num->A)`;`tt:A`] BVALF_ALL_LB) THEN
      ASM_SIMP_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN
     `erel D (E:A->A->bool) leq
        (bvalf D E B leq ((z |-> zz) v0) (!! y (p --> Eq y z)))
        (bvalf D E B leq ((y |-> s) ((z |-> zz) v0)) (p --> Eq y z))`
    (LABEL_TAC "lb2") THENL
     [MP_TAC(ISPECL
             [`y:num`;`(p --> Eq y z):form`;`D:A->bool`;`E:A->A->bool`;`B:A`;
              `leq:A`;`(z |-> zz) (v0:num->A)`;`s:A`] BVALF_ALL_LB) THEN
      ASM_SIMP_TAC[]; ALL_TAC] THEN
    (* ebv_eq tt zz etz where etz = bvalf ((y|->tt)(z|->zz)v0) (Eq y z) *)
    SUBGOAL_THEN
     `ebv_eq D (E:A->A->bool) B leq tt zz
        (bvalf D E B leq ((y |-> tt) ((z |-> zz) v0)) (Eq y z))`
    (LABEL_TAC "eqt") THENL
     [MP_TAC(ISPECL [`y:num`;`z:num`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
        `(y |-> (tt:A)) ((z |-> zz) (v0:num->A))`] BVALF_EQ2) THEN
      ASM_REWRITE_TAC[] THEN
      SUBGOAL_THEN
       `((y |-> tt) ((z |-> zz) (v0:num->A))) y = tt /\
        ((y |-> tt) ((z |-> zz) (v0:num->A))) z = zz`
       (fun th -> REWRITE_TAC[th]) THENL
       [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN ACCEPT_TAC; ALL_TAC] THEN
    SUBGOAL_THEN
     `ebv_eq D (E:A->A->bool) B leq s zz
        (bvalf D E B leq ((y |-> s) ((z |-> zz) v0)) (Eq y z))`
    (LABEL_TAC "eqs") THENL
     [MP_TAC(ISPECL [`y:num`;`z:num`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
        `(y |-> (s:A)) ((z |-> zz) (v0:num->A))`] BVALF_EQ2) THEN
      ASM_REWRITE_TAC[] THEN
      SUBGOAL_THEN
       `((y |-> s) ((z |-> zz) (v0:num->A))) y = s /\
        ((y |-> s) ((z |-> zz) (v0:num->A))) z = zz`
       (fun th -> REWRITE_TAC[th]) THENL
       [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN ACCEPT_TAC; ALL_TAC] THEN
    (* ebimp pt etz i1 and ebimp ps esz i2 *)
    SUBGOAL_THEN
     `ebimp D (E:A->A->bool) B leq
        (bvalf D E B leq ((y |-> tt) v0) p)
        (bvalf D E B leq ((y |-> tt) ((z |-> zz) v0)) (Eq y z))
        (bvalf D E B leq ((y |-> tt) ((z |-> zz) v0)) (p --> Eq y z))`
    (LABEL_TAC "imp1") THENL
     [MP_TAC(ISPECL
             [`p:form`;`(Eq y z):form`;`D:A->bool`;`E:A->A->bool`;
              `B:A`;`leq:A`;
              `(y |-> (tt:A)) ((z |-> zz) (v0:num->A))`] BVALF_IMP) THEN
      ASM_REWRITE_TAC[] THEN
      DISCH_THEN(MP_TAC o ONCE_REWRITE_RULE[GSYM(ASSUME
        `bvalf D (E:A->A->bool) B leq ((y |-> tt) ((z |-> zz) v0)) p =
         bvalf D E B leq ((y |-> tt) v0) p`)]) THEN
      REWRITE_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN
     `ebimp D (E:A->A->bool) B leq
        (bvalf D E B leq ((y |-> s) v0) p)
        (bvalf D E B leq ((y |-> s) ((z |-> zz) v0)) (Eq y z))
        (bvalf D E B leq ((y |-> s) ((z |-> zz) v0)) (p --> Eq y z))`
    (LABEL_TAC "imp2") THENL
     [MP_TAC(ISPECL
             [`p:form`;`(Eq y z):form`;`D:A->bool`;`E:A->A->bool`;
              `B:A`;`leq:A`;
              `(y |-> (s:A)) ((z |-> zz) (v0:num->A))`] BVALF_IMP) THEN
      ASM_REWRITE_TAC[] THEN
      DISCH_THEN(MP_TAC o ONCE_REWRITE_RULE[GSYM(ASSUME
        `bvalf D (E:A->A->bool) B leq ((y |-> s) ((z |-> zz) v0)) p =
         bvalf D E B leq ((y |-> s) v0) p`)]) THEN
      REWRITE_TAC[]; ALL_TAC] THEN
    (* IN D facts for fv(zz), etz, esz, i1, i2 *)
    SUBGOAL_THEN
     `(bvalf D (E:A->A->bool) B leq ((z |-> zz) v0)
       (!! y (p --> Eq y z))) IN D /\
      (bvalf D (E:A->A->bool) B leq ((y |-> tt) ((z |-> zz) v0))
       (Eq y z)) IN D /\
      (bvalf D (E:A->A->bool) B leq ((y |-> s) ((z |-> zz) v0))
       (Eq y z)) IN D /\
      (bvalf D (E:A->A->bool) B leq ((y |-> tt) ((z |-> zz) v0))
       (p --> Eq y z)) IN D /\
      (bvalf D (E:A->A->bool) B leq ((y |-> s) ((z |-> zz) v0))
       (p --> Eq y z)) IN D`
    STRIP_ASSUME_TAC THENL
     [REPEAT CONJ_TAC THENL
       [MP_TAC(ISPECL
               [`(!! y (p --> Eq y z)):form`;`D:A->bool`;`E:A->A->bool`;
                `B:A`;`leq:A`;
                `(z |-> zz) (v0:num->A)`] BVALF_SPEC) THEN ASM_SIMP_TAC[];
        MP_TAC(ISPECL
               [`(Eq y z):form`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
                `(y |-> (tt:A)) ((z |-> zz) (v0:num->A))`] BVALF_SPEC) THEN
        ASM_SIMP_TAC[];
        MP_TAC(ISPECL
               [`(Eq y z):form`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
                `(y |-> (s:A)) ((z |-> zz) (v0:num->A))`] BVALF_SPEC) THEN
        ASM_SIMP_TAC[];
        MP_TAC(ISPECL
               [`(p --> Eq y z):form`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
                `(y |-> (tt:A)) ((z |-> zz) (v0:num->A))`] BVALF_SPEC) THEN
        ASM_SIMP_TAC[];
        MP_TAC(ISPECL
               [`(p --> Eq y z):form`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
                `(y |-> (s:A)) ((z |-> zz) (v0:num->A))`] BVALF_SPEC) THEN
        ASM_SIMP_TAC[]];
      ALL_TAC] THEN
    (* m = meet(fv(zz), w) *)
    MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
      `bvalf D (E:A->A->bool) B leq ((z |-> zz) v0)
       (!! y (p --> Eq y z))`;`w:A`]
      EBALG_MEET) THEN
    ASM_REWRITE_TAC[] THEN
    ANTS_TAC THENL
     [MP_TAC(ISPECL
             [`(!! y (p --> Eq y z)):form`;`D:A->bool`;`E:A->A->bool`;
              `B:A`;`leq:A`;
              `(z |-> zz) (v0:num->A)`] BVALF_IN_B) THEN ASM_SIMP_TAC[];
      ALL_TAC] THEN
    DISCH_THEN(X_CHOOSE_THEN `m:A` (LABEL_TAC "mmeet")) THEN
    SUBGOAL_THEN `(m:A) IN D /\ (E:A->A->bool) m B` STRIP_ASSUME_TAC THENL
     [ASM_MESON_TAC[EMEET_IN]; ALL_TAC] THEN
    SUBGOAL_THEN
     `erel D (E:A->A->bool) leq m
        (bvalf D E B leq ((z |-> zz) v0) (!! y (p --> Eq y z))) /\
      erel D (E:A->A->bool) leq m w`
    STRIP_ASSUME_TAC THENL
     [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
        `bvalf D (E:A->A->bool) B leq ((z |-> zz) v0) (!! y (p --> Eq y z))`;
        `w:A`;`m:A`]
        EMEET_LE) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    (* m <= pt, m <= ps via w <= pt, w <= ps *)
    SUBGOAL_THEN
      `erel D (E:A->A->bool) leq m (bvalf D E B leq ((y |-> tt) v0) p)`
      ASSUME_TAC THENL
     [MATCH_MP_TAC(ISPECL
                   [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`m:A`;`w:A`;
                    `bvalf D (E:A->A->bool) B leq ((y |-> tt) v0) p`]
                     EPORDER_TRANS) THEN
      ASM_REWRITE_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN
      `erel D (E:A->A->bool) leq m (bvalf D E B leq ((y |-> s) v0) p)`
      ASSUME_TAC THENL
     [MATCH_MP_TAC(ISPECL
                   [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`m:A`;`w:A`;
                    `bvalf D (E:A->A->bool) B leq ((y |-> s) v0) p`]
                     EPORDER_TRANS) THEN
      ASM_REWRITE_TAC[]; ALL_TAC] THEN
    (* EBV_FUNC_EQ: m <= ets *)
    SUBGOAL_THEN `erel D (E:A->A->bool) leq m ets` ASSUME_TAC THENL
     [MATCH_MP_TAC(ISPECL
        [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`m:A`;
         `bvalf D (E:A->A->bool) B leq ((z |-> zz) v0) (!! y (p --> Eq y z))`;
         `bvalf D (E:A->A->bool) B leq ((y |-> tt) v0) p`;
         `bvalf D (E:A->A->bool) B leq ((y |-> s) v0) p`;
         `zz:A`;`tt:A`;`s:A`;
         `bvalf D (E:A->A->bool) B leq ((y |-> tt) ((z |-> zz) v0)) (Eq y z)`;
         `bvalf D (E:A->A->bool) B leq ((y |-> s) ((z |-> zz) v0)) (Eq y z)`;
         `ets:A`;
         `bvalf D (E:A->A->bool) B leq ((y |-> tt) ((z |-> zz) v0))
          (p --> Eq y z)`;
         `bvalf D (E:A->A->bool) B leq ((y |-> s) ((z |-> zz) v0))
          (p --> Eq y z)`]
        EBV_FUNC_EQ) THEN
      ASM_REWRITE_TAC[]; ALL_TAC] THEN
    (* E fv(zz) B  -- needed by EBIMP_LE_IMP's E a B (persist it now) *)
    SUBGOAL_THEN
     `(E:A->A->bool) (bvalf D E B leq ((z |-> zz) v0) (!! y (p --> Eq y z))) B`
    ASSUME_TAC THENL
     [MP_TAC(ISPECL
             [`(!! y (p --> Eq y z)):form`;`D:A->bool`;`E:A->A->bool`;
              `B:A`;`leq:A`;
              `(z |-> zz) (v0:num->A)`] BVALF_IN_B) THEN ASM_SIMP_TAC[];
      ALL_TAC] THEN
    (* EBIMP_LE_IMP: fv(zz) <= wimp *)
    MATCH_MP_TAC(ISPECL
      [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
       `bvalf D (E:A->A->bool) B leq ((z |-> zz) v0) (!! y (p --> Eq y z))`;
       `w:A`;`ets:A`;`wimp:A`;`m:A`] EBIMP_LE_IMP) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  (* ===== assemble via BVALF_EX_LEAST ===== *)
  SUBGOAL_THEN
   `erel D (E:A->A->bool) leq
      (bvalf D E B leq v0 (?? z (!! y (p --> Eq y z)))) wimp`
  (LABEL_TAC "prem_le") THENL
   [MATCH_MP_TAC(ISPECL
                 [`z:num`;`(!! y (p --> Eq y z)):form`;`D:A->bool`;
                  `E:A->A->bool`;
                  `B:A`;`leq:A`;`v0:num->A`;`wimp:A`] BVALF_EX_LEAST) THEN
    ASM_REWRITE_TAC[] THEN USE_THEN "perz" ACCEPT_TAC; ALL_TAC] THEN
  (* d <= prem <= wimp *)
  SUBGOAL_THEN `erel D (E:A->A->bool) leq d wimp` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`d:A`;
      `bvalf D (E:A->A->bool) B leq v0 (?? z (!! y (p --> Eq y z)))`;`wimp:A`]
      EPORDER_TRANS) THEN
    ASM_REWRITE_TAC[] THEN
    MP_TAC(ISPECL
           [`(?? z (!! y (p --> Eq y z))):form`;`D:A->bool`;
            `E:A->A->bool`;`B:A`;
            `leq:A`;`v0:num->A`] BVALF_IN_B) THEN
    ASM_SIMP_TAC[] THEN DISCH_TAC THEN
    MP_TAC(ISPECL
           [`(?? z (!! y (p --> Eq y z))):form`;`D:A->bool`;
            `E:A->A->bool`;`B:A`;
            `leq:A`;`v0:num->A`] BVALF_SPEC) THEN ASM_SIMP_TAC[]; ALL_TAC] THEN
  (* d <= w *)
  SUBGOAL_THEN `erel D (E:A->A->bool) leq d w` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
      `bvalf D (E:A->A->bool) B leq ((y |-> tt) v0) p`;
      `bvalf D (E:A->A->bool) B leq ((y |-> s) v0) p`;`w:A`;`d:A`]
             EMEET_GREATEST) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* md = meet(d,w) *)
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`d:A`;`w:A`]
         EBALG_MEET) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `md:A` (LABEL_TAC "mdmeet")) THEN
  SUBGOAL_THEN `(md:A) IN D /\ (E:A->A->bool) md B` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[EMEET_IN]; ALL_TAC] THEN
  (* EBIMP_MEET_LE: md <= ets *)
  SUBGOAL_THEN `erel D (E:A->A->bool) leq md ets` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`d:A`;`w:A`;`ets:A`;
                  `wimp:A`;`md:A`] EBIMP_MEET_LE) THEN ASM_REWRITE_TAC[];
         ALL_TAC] THEN
  (* d <= md *)
  SUBGOAL_THEN `erel D (E:A->A->bool) leq d md` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`d:A`;`w:A`;
                  `md:A`;`d:A`]
                 EMEET_GREATEST) THEN
    ASM_REWRITE_TAC[] THEN
    MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`d:A`]
                 EPORDER_REFL) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* d <= md <= ets *)
  MATCH_MP_TAC(ISPECL
               [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`d:A`;`md:A`;`ets:A`]
               EPORDER_TRANS) THEN
  ASM_REWRITE_TAC[]);;

(* ===== EBV_PERWITNESS_FULL: per-(ss,tt) V^B replacement collection bound *)
(* ===== *)
(* EBV_PERWITNESS_FULL: the per-(ss,tt) collection bound.
   m = prem AND [[ss in a]] AND [[p(ss,tt)]] (given via its three <= bounds);
   K = [[tt in C]] (C = EFULLNAME dd, given via ebv_in tt cn K);
   SS = {[[p(ss,s)]] : s in dd}, g = sup SS (STABILIZE_SUP outputs);
   ptt = [[p(ss,tt)]] <= g (STABILIZE_SUP last clause at b:=ptt in V_ss).
   Conclusion: m <= K.  Route: EBV_PERWITNESS_LE (pure residuation) whose
   per-pS hypothesis meet(m,pS) <= K is discharged by FUNC_EQ_FULL
     (mm<=[[tt=s]])
   + EFULLNAME_IN_GE_ELT ([[tt=s]]<=[[tt in C]]=K). *)
let EBV_PERWITNESS_FULL = prove
 (`!D (E:A->A->bool) B leq v x y z a p ss tt dd cn onebee SS g K m.
      model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
      valuation D v /\ (!i. bname D E B (v i)) /\
      bname D E B ss /\ ss IN D /\ bname D E B tt /\ tt IN D /\
      ~(z IN FV p) /\ ~(y = z) /\ ~(x = y) /\ ~(x = a) /\
      dd IN D /\ (!s. s IN D /\ E s dd ==> bname D E B s) /\
      onebee IN D /\ E onebee B /\ etop D E B leq onebee /\
      cn IN D /\ (!s. s IN D /\ E s dd ==> eapply D E cn s onebee) /\
      K IN D /\ E K B /\ ebv_in D E B leq tt cn K /\
      SS IN D /\ esubset D E SS B /\ elub D E B leq SS g /\ g IN D /\
      (!w. w IN D
           ==> (E w SS <=>
                ?s. s IN D /\ E s dd /\
                    bval D E B leq ((y |-> s) ((x |-> ss) v)) p w)) /\
      m IN D /\ E m B /\
      erel D E leq m
        (bvalf D E B leq v (!!- x a (?? z (!! y (p --> Eq y z))))) /\
      erel D E leq m (bvalf D E B leq ((x |-> ss) v) (x %% a)) /\
      erel D E leq m (bvalf D E B leq ((y |-> tt) ((x |-> ss) v)) p) /\
      erel D E leq (bvalf D E B leq ((y |-> tt) ((x |-> ss) v)) p) g
      ==> erel D E leq m K`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `ebalg D (E:A->A->bool) B leq` ASSUME_TAC THENL
   [ASM_MESON_TAC[ECBA_IMP_BALG]; ALL_TAC] THEN
  SUBGOAL_THEN `eporder D (E:A->A->bool) B leq` ASSUME_TAC THENL
   [ASM_MESON_TAC[ECBA_IMP_PORDER]; ALL_TAC] THEN
  (* v0 = (x|->ss)v valuation + bname slots *)
  SUBGOAL_THEN
   `valuation D ((x |-> ss) (v:num->A)) /\
    (!i. bname D E B (((x |-> ss) (v:num->A)) i))`
  STRIP_ASSUME_TAC THENL
   [CONJ_TAC THENL
     [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[];
      MATCH_MP_TAC BNAMEVAL_VALMOD THEN ASM_REWRITE_TAC[]]; ALL_TAC] THEN
  (* (y|->tt)v0 valuation + bname slots *)
  SUBGOAL_THEN
   `valuation D ((y |-> tt) ((x |-> ss) (v:num->A))) /\
    (!i. bname D E B (((y |-> tt) ((x |-> ss) (v:num->A))) i))`
  STRIP_ASSUME_TAC THENL
   [CONJ_TAC THENL
     [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[];
      MATCH_MP_TAC BNAMEVAL_VALMOD THEN ASM_REWRITE_TAC[]]; ALL_TAC] THEN
  (* IN D / E B facts for prem, ain, premss, i0, ptt *)
  SUBGOAL_THEN
   `(bvalf D (E:A->A->bool) B leq v
     (!!- x a (?? z (!! y (p --> Eq y z))))) IN D /\
    (E:A->A->bool)
      (bvalf D E B leq v (!!- x a (?? z (!! y (p --> Eq y z))))) B /\
    (bvalf D (E:A->A->bool) B leq ((x |-> ss) v) (x %% a)) IN D /\
    (E:A->A->bool) (bvalf D E B leq ((x |-> ss) v) (x %% a)) B /\
    (bvalf D (E:A->A->bool) B leq ((x |-> ss) v)
     (?? z (!! y (p --> Eq y z)))) IN D /\
    (E:A->A->bool)
      (bvalf D E B leq ((x |-> ss) v) (?? z (!! y (p --> Eq y z)))) B /\
    (bvalf D (E:A->A->bool) B leq ((x |-> ss) v)
        (x %% a --> (?? z (!! y (p --> Eq y z))))) IN D /\
    (E:A->A->bool) (bvalf D E B leq ((x |-> ss) v)
        (x %% a --> (?? z (!! y (p --> Eq y z))))) B /\
    (bvalf D (E:A->A->bool) B leq ((y |-> tt) ((x |-> ss) v)) p) IN D /\
    (E:A->A->bool) (bvalf D E B leq ((y |-> tt) ((x |-> ss) v)) p) B`
  STRIP_ASSUME_TAC THENL
   [REPEAT CONJ_TAC THENL
     [MP_TAC(ISPECL
             [`(!!- x a (?? z (!! y (p --> Eq y z)))):form`;`D:A->bool`;
              `E:A->A->bool`;`B:A`;`leq:A`;`v:num->A`] BVALF_SPEC) THEN
      ASM_SIMP_TAC[];
      MP_TAC(ISPECL
             [`(!!- x a (?? z (!! y (p --> Eq y z)))):form`;`D:A->bool`;
              `E:A->A->bool`;`B:A`;`leq:A`;`v:num->A`] BVALF_IN_B) THEN
      ASM_SIMP_TAC[];
      MP_TAC(ISPECL
             [`(x %% a):form`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
              `(x |-> (ss:A)) (v:num->A)`] BVALF_SPEC) THEN ASM_SIMP_TAC[];
      MP_TAC(ISPECL
             [`(x %% a):form`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
              `(x |-> (ss:A)) (v:num->A)`] BVALF_IN_B) THEN ASM_SIMP_TAC[];
      MP_TAC(ISPECL
             [`(?? z (!! y (p --> Eq y z))):form`;`D:A->bool`;`E:A->A->bool`;
              `B:A`;`leq:A`;`(x |-> (ss:A)) (v:num->A)`] BVALF_SPEC) THEN
      ASM_SIMP_TAC[];
      MP_TAC(ISPECL
             [`(?? z (!! y (p --> Eq y z))):form`;`D:A->bool`;`E:A->A->bool`;
              `B:A`;`leq:A`;`(x |-> (ss:A)) (v:num->A)`] BVALF_IN_B) THEN
      ASM_SIMP_TAC[];
      MP_TAC(ISPECL
             [`(x %% a --> (?? z (!! y (p --> Eq y z)))):form`;`D:A->bool`;
              `E:A->A->bool`;`B:A`;`leq:A`;`(x |-> (ss:A)) (v:num->A)`]
             BVALF_SPEC) THEN ASM_SIMP_TAC[];
      MP_TAC(ISPECL
             [`(x %% a --> (?? z (!! y (p --> Eq y z)))):form`;`D:A->bool`;
              `E:A->A->bool`;`B:A`;`leq:A`;`(x |-> (ss:A)) (v:num->A)`]
             BVALF_IN_B) THEN ASM_SIMP_TAC[];
      MP_TAC(ISPECL
             [`p:form`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
              `(y |-> (tt:A)) ((x |-> (ss:A)) (v:num->A))`] BVALF_SPEC) THEN
      ASM_SIMP_TAC[];
      MP_TAC(ISPECL
             [`p:form`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
              `(y |-> (tt:A)) ((x |-> (ss:A)) (v:num->A))`] BVALF_IN_B) THEN
      ASM_SIMP_TAC[]];
    ALL_TAC] THEN
  (* ebimp ain premss i0 via BVALF_IMP *)
  SUBGOAL_THEN
   `ebimp D (E:A->A->bool) B leq
      (bvalf D E B leq ((x |-> ss) v) (x %% a))
      (bvalf D E B leq ((x |-> ss) v) (?? z (!! y (p --> Eq y z))))
      (bvalf D E B leq ((x |-> ss) v)
       (x %% a --> (?? z (!! y (p --> Eq y z)))))`
  (LABEL_TAC "imp0") THENL
   [MP_TAC(ISPECL
           [`(x %% a):form`;`(?? z (!! y (p --> Eq y z))):form`;`D:A->bool`;
            `E:A->A->bool`;`B:A`;`leq:A`;`(x |-> (ss:A)) (v:num->A)`]
           BVALF_IMP) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* prem <= i0 via EBVALF_ALLMEM_LE *)
  SUBGOAL_THEN
   `erel D (E:A->A->bool) leq
      (bvalf D E B leq v (!!- x a (?? z (!! y (p --> Eq y z)))))
      (bvalf D E B leq ((x |-> ss) v)
       (x %% a --> (?? z (!! y (p --> Eq y z)))))`
  (LABEL_TAC "premi0") THENL
   [MP_TAC(ISPECL
           [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`v:num->A`;
            `x:num`;`a:num`;
            `(?? z (!! y (p --> Eq y z))):form`;`ss:A`] EBVALF_ALLMEM_LE) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* m <= i0 (TRANS m,prem,i0) *)
  SUBGOAL_THEN
   `erel D (E:A->A->bool) leq m
      (bvalf D E B leq ((x |-> ss) v)
       (x %% a --> (?? z (!! y (p --> Eq y z)))))`
  (LABEL_TAC "mi0") THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`m:A`;
      `bvalf D (E:A->A->bool) B leq v (!!- x a (?? z (!! y (p --> Eq y z))))`;
      `bvalf D (E:A->A->bool) B leq ((x |-> ss) v)
       (x %% a --> (?? z (!! y (p --> Eq y z))))`]
      EPORDER_TRANS) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* m <= premss via EBV_MP_LE *)
  SUBGOAL_THEN
   `erel D (E:A->A->bool) leq m
      (bvalf D E B leq ((x |-> ss) v) (?? z (!! y (p --> Eq y z))))`
  (LABEL_TAC "mpremss") THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`m:A`;
      `bvalf D (E:A->A->bool) B leq ((x |-> ss) v) (x %% a)`;
      `bvalf D (E:A->A->bool) B leq ((x |-> ss) v)
       (?? z (!! y (p --> Eq y z)))`;
      `bvalf D (E:A->A->bool) B leq ((x |-> ss) v)
       (x %% a --> (?? z (!! y (p --> Eq y z))))`]
      EBV_MP_LE) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* i0' = ebimp m K *)
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`m:A`;`K:A`]
         EBIMP_EXISTS) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `imK:A` (LABEL_TAC "imK")) THEN
  SUBGOAL_THEN `(imK:A) IN D /\ (E:A->A->bool) imK B` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[EBIMP_IN]; ALL_TAC] THEN
  (* ===== per-pS discharge ===== *)
  SUBGOAL_THEN
   `!pS mm. pS IN D /\ E pS SS /\ emeet D (E:A->A->bool) B leq m pS mm
            ==> erel D E leq mm K`
  (LABEL_TAC "perpS") THENL
   [MAP_EVERY X_GEN_TAC [`pS:A`;`mm:A`] THEN STRIP_TAC THEN
    (* s in dd with pS = bvalf ((y|->s)v0) p *)
    SUBGOAL_THEN
     `?s:A. s IN D /\ E s dd /\
            bval D (E:A->A->bool) B leq
              ((y |-> s) ((x |-> (ss:A)) (v:num->A))) p (pS:A)`
    STRIP_ASSUME_TAC THENL
     [SUBGOAL_THEN
       `(E:A->A->bool) pS SS <=>
        (?s:A. s IN D /\ E s dd /\
               bval D (E:A->A->bool) B leq
                 ((y |-> s) ((x |-> (ss:A)) (v:num->A))) p (pS:A))`
       ASSUME_TAC THENL
       [FIRST_ASSUM MATCH_MP_TAC THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
      ASM_MESON_TAC[];
      ALL_TAC] THEN
    (* bname s *)
    SUBGOAL_THEN `bname D (E:A->A->bool) B s` ASSUME_TAC THENL
     [ASM_MESON_TAC[]; ALL_TAC] THEN
    (* (y|->s)v0 valuation + bname *)
    SUBGOAL_THEN
     `valuation D ((y |-> s) ((x |-> ss) (v:num->A))) /\
      (!i. bname D E B (((y |-> s) ((x |-> ss) (v:num->A))) i))`
    STRIP_ASSUME_TAC THENL
     [CONJ_TAC THENL
       [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[];
        MATCH_MP_TAC BNAMEVAL_VALMOD THEN ASM_REWRITE_TAC[]]; ALL_TAC] THEN
    (* pS = bvalf ((y|->s)v0) p *)
    SUBGOAL_THEN
      `pS = bvalf D (E:A->A->bool) B leq ((y |-> s) ((x |-> ss) v)) p`
      (LABEL_TAC "pSval") THENL
     [MP_TAC(ISPECL [`p:form`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
        `(y |-> (s:A)) ((x |-> (ss:A)) (v:num->A))`] BVALF_SPEC) THEN
      ASM_REWRITE_TAC[] THEN STRIP_TAC THEN
      MATCH_MP_TAC(ISPECL [`p:form`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
        `(y |-> (s:A)) ((x |-> (ss:A)) (v:num->A))`;`pS:A`;
        `bvalf D (E:A->A->bool) B leq ((y |-> s) ((x |-> ss) v)) p`]
          BVAL_UNIQUE) THEN
      ASM_REWRITE_TAC[]; ALL_TAC] THEN
    (* ets = [[tt=s]] *)
    MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`tt:A`;`s:A`]
           EBV_EQ_VAL_EXISTS) THEN
    ASM_REWRITE_TAC[] THEN
    DISCH_THEN(X_CHOOSE_THEN `ets:A` STRIP_ASSUME_TAC) THEN
    (* mm facts *)
    SUBGOAL_THEN `(mm:A) IN D /\ (E:A->A->bool) mm B` STRIP_ASSUME_TAC THENL
     [ASM_MESON_TAC[EMEET_IN]; ALL_TAC] THEN
    SUBGOAL_THEN
     `erel D (E:A->A->bool) leq mm m /\ erel D (E:A->A->bool) leq mm pS`
    STRIP_ASSUME_TAC THENL
     [MATCH_MP_TAC(ISPECL
                   [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`m:A`;
                    `pS:A`;`mm:A`]
                   EMEET_LE) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    (* mm <= premss *)
    SUBGOAL_THEN
     `erel D (E:A->A->bool) leq mm
        (bvalf D E B leq ((x |-> ss) v) (?? z (!! y (p --> Eq y z))))`
    ASSUME_TAC THENL
     [MATCH_MP_TAC(ISPECL
                   [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`mm:A`;`m:A`;
                    `bvalf D (E:A->A->bool) B leq ((x |-> ss) v)
                     (?? z (!! y (p --> Eq y z)))`]
        EPORDER_TRANS) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    (* mm <= ptt *)
    SUBGOAL_THEN
     `erel D (E:A->A->bool) leq mm
        (bvalf D E B leq ((y |-> tt) ((x |-> ss) v)) p)`
    ASSUME_TAC THENL
     [MATCH_MP_TAC(ISPECL
                   [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`mm:A`;`m:A`;
                    `bvalf D (E:A->A->bool) B leq
                     ((y |-> tt) ((x |-> ss) v)) p`]
        EPORDER_TRANS) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    (* mm <= pS = bvalf ((y|->s)v0) p *)
    SUBGOAL_THEN
     `erel D (E:A->A->bool) leq mm
        (bvalf D E B leq ((y |-> s) ((x |-> ss) v)) p)`
    ASSUME_TAC THENL
     [ASM_MESON_TAC[]; ALL_TAC] THEN
    (* FUNC_EQ_FULL: mm <= ets = [[tt=s]] *)
    SUBGOAL_THEN `erel D (E:A->A->bool) leq mm ets` ASSUME_TAC THENL
     [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
        `(x |-> (ss:A)) (v:num->A)`;`p:form`;`y:num`;`z:num`;`tt:A`;`s:A`;
        `mm:A`;`ets:A`]
        FUNC_EQ_FULL) THEN
      ASM_REWRITE_TAC[]; ALL_TAC] THEN
    (* eapply cn s onebee (from the EFULLNAME dd-clause) *)
    SUBGOAL_THEN `eapply D (E:A->A->bool) cn s onebee` ASSUME_TAC THENL
     [ASM_MESON_TAC[]; ALL_TAC] THEN
    (* EFULLNAME_IN_GE_ELT: ets <= K *)
    SUBGOAL_THEN `erel D (E:A->A->bool) leq ets K` ASSUME_TAC THENL
     [MATCH_MP_TAC(ISPECL
                   [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`onebee:A`;`cn:A`;
                    `s:A`;`tt:A`;`K:A`;`ets:A`] EFULLNAME_IN_GE_ELT) THEN
      ASM_REWRITE_TAC[]; ALL_TAC] THEN
    (* mm <= ets <= K *)
    MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`mm:A`;
                  `ets:A`;`K:A`]
                 EPORDER_TRANS) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  (* ===== EBV_PERWITNESS_LE ===== *)
  MATCH_MP_TAC(ISPECL
               [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`m:A`;`K:A`;`g:A`;
                `bvalf D (E:A->A->bool) B leq ((y |-> tt) ((x |-> ss) v)) p`;
                `SS:A`;`imK:A`]
    EBV_PERWITNESS_LE) THEN
  ASM_REWRITE_TAC[]);;

(* ===== EBV_MEMRED: replacement membership-reduction (all-bname ss -> *)
(* dom(aa) members) ===== *)
(* EBV_MEMRED: membership-reduction lemma for V^B REPLACEMENT collection.
   EBVALF_EXMEM_LE gives a per-witness bound quantified over ALL bnames ss,
   but the stabilization / uniform-lambda* machinery only bounds witnesses
   over dom(aa) (uniform stabilization over ALL bnames is FALSE -
     proper class).
   This lemma bridges the gap: GIVEN the dom-member per-witness bound (as a
   3-bounds hypothesis over yy in dom(aa) = eapply (v a) yy qy), it derives the
   SAME 3-bounds bound for an ARBITRARY bname ss.
     prem = [[!!- x a (?? ...)]]_v  (functional premise,
     a fixed parameter here)
     K    = [[tt in C]]             (fixed parameter)
   Both per-witness bounds are stated in "3-bounds" interface form:
     m0 <= prem  /\  m0 <= [[ss in aa]]  /\  m0 <= [[p(ss,tt)]]  ==>  m0 <= K,
   where [[ss in aa]] = bvalf ((x|->ss)v) (x%%a) and [[p(ss,tt)]] = bvalf
     ((x|->ss)v) p
   (v already carries y:=tt and a:=aa; tt/y do not appear explicitly).
   Route: for arbitrary bname ss, residuate [[ss in aa]] via EBV_IN_LE_V's LUB
   over dom(aa)-elements y; for each y (bname via EBNRANK_APPLY_LT) build
   m0y = meet(cc,m0) [cc=meet(qy,[[ss=y]])],
   show it meets the 3 dom-member bounds
   at yy:=y (qy<=[[y in aa]] via EBV_IN_GE_TERM_V+refl+EMEET_TOP;
   [[p(y,tt)]] via
   BVAL_SUBST_CONG on the x-slot),
   apply the dom-member hypothesis to get m0y<=K,
   then EBIMP_LE_IMP lifts cc<=(m0=>K);
   EBV_IN_LE_V yields [[ss in aa]]<=(m0=>K),
   and m0<=[[ss in aa]] + EBIMP_MEET_LE close m0<=K. *)
let EBV_MEMRED = prove
 (`!D (E:A->A->bool) B leq v x a p prem K.
      model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
      valuation D v /\ (!i. bname D E B (v i)) /\
      ~(a = x) /\
      prem IN D /\ E prem B /\ K IN D /\ E K B /\
      (!yy qy m0.
          yy IN D /\ eapply D E (v a) yy qy /\ m0 IN D /\ E m0 B /\
          erel D E leq m0 prem /\
          erel D E leq m0 (bvalf D E B leq ((x |-> yy) v) (x %% a)) /\
          erel D E leq m0 (bvalf D E B leq ((x |-> yy) v) p)
          ==> erel D E leq m0 K)
      ==> (!ss m0.
              ss IN D /\ bname D E B ss /\ m0 IN D /\ E m0 B /\
              erel D E leq m0 prem /\
              erel D E leq m0 (bvalf D E B leq ((x |-> ss) v) (x %% a)) /\
              erel D E leq m0 (bvalf D E B leq ((x |-> ss) v) p)
              ==> erel D E leq m0 K)`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  MAP_EVERY X_GEN_TAC [`ss:A`;`m0:A`] THEN STRIP_TAC THEN
  SUBGOAL_THEN `ebalg D (E:A->A->bool) B leq` ASSUME_TAC THENL
   [ASM_MESON_TAC[ECBA_IMP_BALG]; ALL_TAC] THEN
  SUBGOAL_THEN `eporder D (E:A->A->bool) B leq` ASSUME_TAC THENL
   [ASM_MESON_TAC[ECBA_IMP_PORDER]; ALL_TAC] THEN
  SUBGOAL_THEN `~(x:num = a)` ASSUME_TAC THENL [ASM_MESON_TAC[]; ALL_TAC] THEN
  (* bname (v a) and (v a) IN D *)
  SUBGOAL_THEN
   `bname D (E:A->A->bool) B ((v:num->A) a) /\ ((v:num->A) a) IN D`
  STRIP_ASSUME_TAC THENL
   [CONJ_TAC THENL [ASM_MESON_TAC[]; ASM_MESON_TAC[valuation]]; ALL_TAC] THEN
  (* valuation (x|->ss)v + all-bname *)
  SUBGOAL_THEN
   `valuation D ((x |-> ss) (v:num->A)) /\
    (!i. bname D E B (((x |-> ss) (v:num->A)) i))`
  STRIP_ASSUME_TAC THENL
   [CONJ_TAC THENL
     [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[];
      MATCH_MP_TAC BNAMEVAL_VALMOD THEN ASM_REWRITE_TAC[]]; ALL_TAC] THEN
  (* MEMSS, PVALSS IN D / E B *)
  SUBGOAL_THEN
   `(bvalf D (E:A->A->bool) B leq ((x |-> ss) v) (x %% a)) IN D /\
    (E:A->A->bool) (bvalf D E B leq ((x |-> ss) v) (x %% a)) B /\
    (bvalf D (E:A->A->bool) B leq ((x |-> ss) v) p) IN D /\
    (E:A->A->bool) (bvalf D E B leq ((x |-> ss) v) p) B`
  STRIP_ASSUME_TAC THENL
   [REPEAT CONJ_TAC THENL
     [MP_TAC(ISPECL
             [`(x %% a):form`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
              `(x |-> (ss:A)) (v:num->A)`] BVALF_SPEC) THEN ASM_SIMP_TAC[];
      MP_TAC(ISPECL
             [`(x %% a):form`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
              `(x |-> (ss:A)) (v:num->A)`] BVALF_IN_B) THEN ASM_SIMP_TAC[];
      MP_TAC(ISPECL
             [`p:form`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
              `(x |-> (ss:A)) (v:num->A)`] BVALF_SPEC) THEN ASM_SIMP_TAC[];
      MP_TAC(ISPECL
             [`p:form`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
              `(x |-> (ss:A)) (v:num->A)`] BVALF_IN_B) THEN ASM_SIMP_TAC[]];
    ALL_TAC] THEN
  (* ebv_in ss (v a) MEMSS *)
  SUBGOAL_THEN
   `ebv_in D (E:A->A->bool) B leq ss ((v:num->A) a)
      (bvalf D E B leq ((x |-> ss) v) (x %% a))`
  ASSUME_TAC THENL
   [MP_TAC(ISPECL [`x:num`;`a:num`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
      `(x |-> (ss:A)) (v:num->A)`] BVALF_MEM) THEN
    ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER]; ALL_TAC] THEN
  (* w1 = ebimp m0 K *)
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`m0:A`;`K:A`]
         EBIMP_EXISTS) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_THEN `w1:A` (LABEL_TAC "w1")) THEN
  SUBGOAL_THEN `(w1:A) IN D /\ (E:A->A->bool) w1 B` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[EBIMP_IN]; ALL_TAC] THEN
  (* rank rv of (v a) *)
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`(v:num->A) a`]
         EBNRANK_EXISTS) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `rv:A` (LABEL_TAC "rvrank")) THEN
  (* ===== MAIN: [[ss in aa]] <= w1 via EBV_IN_LE_V ===== *)
  SUBGOAL_THEN
   `erel D (E:A->A->bool) leq (bvalf D E B leq ((x |-> ss) v) (x %% a)) w1`
  ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`ss:A`;
                  `(v:num->A) a`;
                  `bvalf D (E:A->A->bool) B leq ((x |-> ss) v) (x %% a)`;
                  `w1:A`] EBV_IN_LE_V) THEN
    ASM_REWRITE_TAC[] THEN
    MAP_EVERY X_GEN_TAC [`yv:A`;`qy:A`;`ey:A`;`cc:A`] THEN STRIP_TAC THEN
    (* cc facts *)
    SUBGOAL_THEN `(E:A->A->bool) cc B` ASSUME_TAC THENL
     [ASM_MESON_TAC[EMEET_IN]; ALL_TAC] THEN
    (* E ey B (the ebv_eq value [[ss=yv]]) - needed by EPORDER_TRANS target
       and EBALG_MEET(ey,PVALSS);
       ey has no E-fact from EBV_IN_LE_V's universal *)
       SUBGOAL_THEN `(E:A->A->bool) ey B` ASSUME_TAC THENL
     [MATCH_MP_TAC(ISPECL
                   [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`ss:A`;
                    `yv:A`;`ey:A`]
                   EBV_EQ_IN_B) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN
     `erel D (E:A->A->bool) leq cc qy /\ erel D (E:A->A->bool) leq cc ey`
    STRIP_ASSUME_TAC THENL
     [MATCH_MP_TAC(ISPECL
                   [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`qy:A`;
                    `ey:A`;`cc:A`]
                   EMEET_LE) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    (* E qy B *)
    SUBGOAL_THEN `(E:A->A->bool) qy B` ASSUME_TAC THENL
     [MATCH_MP_TAC(ISPECL
                   [`D:A->bool`;`E:A->A->bool`;`B:A`;`(v:num->A) a`;
                    `yv:A`;`qy:A`]
                   BNAME_APPLY_IN_B) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    (* bname yv *)
    SUBGOAL_THEN `bname D (E:A->A->bool) B yv` ASSUME_TAC THENL
     [MP_TAC(ISPECL
             [`D:A->bool`;`E:A->A->bool`;`B:A`;`(v:num->A) a`;`yv:A`;
              `qy:A`;`rv:A`]
             EBNRANK_APPLY_LT) THEN ASM_REWRITE_TAC[] THEN MESON_TAC[];
                 ALL_TAC] THEN
    (* valuation (x|->yv)v + all-bname *)
    SUBGOAL_THEN
     `valuation D ((x |-> yv) (v:num->A)) /\
      (!i. bname D E B (((x |-> yv) (v:num->A)) i))`
    STRIP_ASSUME_TAC THENL
     [CONJ_TAC THENL
       [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[];
        MATCH_MP_TAC BNAMEVAL_VALMOD THEN ASM_REWRITE_TAC[]]; ALL_TAC] THEN
    (* MEMV(yv), PVAL(yv) IN D / E B *)
    SUBGOAL_THEN
     `(bvalf D (E:A->A->bool) B leq ((x |-> yv) v) (x %% a)) IN D /\
      (E:A->A->bool) (bvalf D E B leq ((x |-> yv) v) (x %% a)) B /\
      (bvalf D (E:A->A->bool) B leq ((x |-> yv) v) p) IN D /\
      (E:A->A->bool) (bvalf D E B leq ((x |-> yv) v) p) B`
    STRIP_ASSUME_TAC THENL
     [REPEAT CONJ_TAC THENL
       [MP_TAC(ISPECL
               [`(x %% a):form`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
                `(x |-> (yv:A)) (v:num->A)`] BVALF_SPEC) THEN ASM_SIMP_TAC[];
        MP_TAC(ISPECL
               [`(x %% a):form`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
                `(x |-> (yv:A)) (v:num->A)`] BVALF_IN_B) THEN ASM_SIMP_TAC[];
        MP_TAC(ISPECL
               [`p:form`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
                `(x |-> (yv:A)) (v:num->A)`] BVALF_SPEC) THEN ASM_SIMP_TAC[];
        MP_TAC(ISPECL
               [`p:form`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
                `(x |-> (yv:A)) (v:num->A)`] BVALF_IN_B) THEN ASM_SIMP_TAC[]];
      ALL_TAC] THEN
    (* ebv_in yv (v a) MEMV(yv) *)
    SUBGOAL_THEN
     `ebv_in D (E:A->A->bool) B leq yv ((v:num->A) a)
        (bvalf D E B leq ((x |-> yv) v) (x %% a))`
    ASSUME_TAC THENL
     [MP_TAC(ISPECL [`x:num`;`a:num`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
        `(x |-> (yv:A)) (v:num->A)`] BVALF_MEM) THEN
      ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER]; ALL_TAC] THEN
    (* eyy = [[yv=yv]] *)
    MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`yv:A`;`yv:A`]
           EBV_EQ_VAL_EXISTS) THEN
    ASM_REWRITE_TAC[] THEN
    DISCH_THEN(X_CHOOSE_THEN `eyy:A` STRIP_ASSUME_TAC) THEN
    (* etop eyy *)
    SUBGOAL_THEN `etop D (E:A->A->bool) B leq eyy` ASSUME_TAC THENL
     [MATCH_MP_TAC(ISPECL
                   [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`yv:A`;`eyy:A`]
                   EBV_EQ_REFL) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    (* emeet qy eyy qy *)
    SUBGOAL_THEN `emeet D (E:A->A->bool) B leq qy eyy qy` ASSUME_TAC THENL
     [MATCH_MP_TAC(ISPECL
                   [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`eyy:A`;`qy:A`]
                   EMEET_TOP) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    (* qy <= MEMV(yv) *)
    SUBGOAL_THEN
     `erel D (E:A->A->bool) leq qy (bvalf D E B leq ((x |-> yv) v) (x %% a))`
    ASSUME_TAC THENL
     [MATCH_MP_TAC(ISPECL
                   [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`yv:A`;
                    `(v:num->A) a`;
                    `bvalf D (E:A->A->bool) B leq ((x |-> yv) v) (x %% a)`;
                    `yv:A`;`qy:A`;`eyy:A`;`qy:A`]
        EBV_IN_GE_TERM_V) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    (* m0y = meet(cc, m0) *)
    MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`cc:A`;`m0:A`]
           EBALG_MEET) THEN
    ASM_REWRITE_TAC[] THEN
    DISCH_THEN(X_CHOOSE_THEN `m0y:A` (LABEL_TAC "m0ymeet")) THEN
    SUBGOAL_THEN `(m0y:A) IN D /\ (E:A->A->bool) m0y B` STRIP_ASSUME_TAC THENL
     [ASM_MESON_TAC[EMEET_IN]; ALL_TAC] THEN
    SUBGOAL_THEN
     `erel D (E:A->A->bool) leq m0y cc /\ erel D (E:A->A->bool) leq m0y m0`
    STRIP_ASSUME_TAC THENL
     [MATCH_MP_TAC(ISPECL
                   [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`cc:A`;
                    `m0:A`;`m0y:A`]
                   EMEET_LE) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    (* m0y <= qy, m0y <= ey (via cc) *)
    SUBGOAL_THEN `erel D (E:A->A->bool) leq m0y qy` ASSUME_TAC THENL
     [MATCH_MP_TAC(ISPECL
                   [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`m0y:A`;
                    `cc:A`;`qy:A`]
                   EPORDER_TRANS) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN `erel D (E:A->A->bool) leq m0y ey` ASSUME_TAC THENL
     [MATCH_MP_TAC(ISPECL
                   [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`m0y:A`;
                    `cc:A`;`ey:A`]
                   EPORDER_TRANS) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    (* m0y <= prem (via m0) *)
    SUBGOAL_THEN `erel D (E:A->A->bool) leq m0y prem` ASSUME_TAC THENL
     [MATCH_MP_TAC(ISPECL
                   [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`m0y:A`;
                    `m0:A`;`prem:A`]
                   EPORDER_TRANS) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    (* m0y <= MEMV(yv) (via qy) *)
    SUBGOAL_THEN
     `erel D (E:A->A->bool) leq m0y (bvalf D E B leq ((x |-> yv) v) (x %% a))`
    ASSUME_TAC THENL
     [MATCH_MP_TAC(ISPECL
                   [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`m0y:A`;`qy:A`;
                    `bvalf D (E:A->A->bool) B leq ((x |-> yv) v) (x %% a)`]
                     EPORDER_TRANS) THEN
      ASM_REWRITE_TAC[]; ALL_TAC] THEN
    (* m0y <= PVALSS (via m0) *)
    SUBGOAL_THEN
     `erel D (E:A->A->bool) leq m0y (bvalf D E B leq ((x |-> ss) v) p)`
    ASSUME_TAC THENL
     [MATCH_MP_TAC(ISPECL
                   [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`m0y:A`;`m0:A`;
                    `bvalf D (E:A->A->bool) B leq ((x |-> ss) v) p`]
                     EPORDER_TRANS) THEN
      ASM_REWRITE_TAC[]; ALL_TAC] THEN
    (* mc = meet(ey, PVALSS) *)
    MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`ey:A`;
      `bvalf D (E:A->A->bool) B leq ((x |-> ss) v) p`] EBALG_MEET) THEN
    ASM_REWRITE_TAC[] THEN
    DISCH_THEN(X_CHOOSE_THEN `mc:A` (LABEL_TAC "mcmeet")) THEN
    SUBGOAL_THEN `(mc:A) IN D /\ (E:A->A->bool) mc B` STRIP_ASSUME_TAC THENL
     [ASM_MESON_TAC[EMEET_IN]; ALL_TAC] THEN
    (* mc <= PVAL(yv) via BVAL_SUBST_CONG (x-slot: ss -> yv) *)
    SUBGOAL_THEN
     `erel D (E:A->A->bool) leq mc (bvalf D E B leq ((x |-> yv) v) p)`
    ASSUME_TAC THENL
     [MATCH_MP_TAC(ISPECL
                   [`p:form`;`D:A->bool`;`E:A->A->bool`;`B:A`;
                    `leq:A`;`v:num->A`;
                    `x:num`;`ss:A`;`yv:A`;`ey:A`;`mc:A`] BVAL_SUBST_CONG) THEN
      ASM_REWRITE_TAC[]; ALL_TAC] THEN
    (* m0y <= mc via EMEET_GREATEST (m0y<=ey, m0y<=PVALSS) *)
    SUBGOAL_THEN `erel D (E:A->A->bool) leq m0y mc` ASSUME_TAC THENL
     [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`ey:A`;
        `bvalf D (E:A->A->bool) B leq ((x |-> ss) v) p`;`mc:A`;`m0y:A`]
                     EMEET_GREATEST) THEN
      ASM_REWRITE_TAC[]; ALL_TAC] THEN
    (* m0y <= PVAL(yv) (via mc) *)
    SUBGOAL_THEN
     `erel D (E:A->A->bool) leq m0y (bvalf D E B leq ((x |-> yv) v) p)`
    ASSUME_TAC THENL
     [MATCH_MP_TAC(ISPECL
                   [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`m0y:A`;`mc:A`;
                    `bvalf D (E:A->A->bool) B leq ((x |-> yv) v) p`]
                     EPORDER_TRANS) THEN
      ASM_REWRITE_TAC[]; ALL_TAC] THEN
    (* dom-member hypothesis at yv, qy, m0y: m0y <= K *)
    SUBGOAL_THEN `erel D (E:A->A->bool) leq m0y K` ASSUME_TAC THENL
     [FIRST_ASSUM(MATCH_MP_TAC o SPECL [`yv:A`;`qy:A`;`m0y:A`]) THEN
      ASM_REWRITE_TAC[]; ALL_TAC] THEN
    (* cc <= w1 via EBIMP_LE_IMP *)
    MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`cc:A`;`m0:A`;`K:A`;
                  `w1:A`;`m0y:A`] EBIMP_LE_IMP) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  (* ===== final: m0 <= [[ss in aa]] <= w1, then m0 <= K ===== *)
  SUBGOAL_THEN `erel D (E:A->A->bool) leq m0 w1` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`m0:A`;
      `bvalf D (E:A->A->bool) B leq ((x |-> ss) v) (x %% a)`;`w1:A`]
                   EPORDER_TRANS) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* mm2 = meet(m0,m0) *)
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`m0:A`;`m0:A`]
         EBALG_MEET) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `mm2:A` (LABEL_TAC "mm2meet")) THEN
  SUBGOAL_THEN `(mm2:A) IN D /\ (E:A->A->bool) mm2 B` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[EMEET_IN]; ALL_TAC] THEN
  (* mm2 <= K via EBIMP_MEET_LE *)
  SUBGOAL_THEN `erel D (E:A->A->bool) leq mm2 K` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`m0:A`;`m0:A`;`K:A`;
                  `w1:A`;`mm2:A`] EBIMP_MEET_LE) THEN ASM_REWRITE_TAC[];
         ALL_TAC] THEN
  (* m0 <= mm2 *)
  SUBGOAL_THEN `erel D (E:A->A->bool) leq m0 mm2` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`m0:A`;`m0:A`;
                  `mm2:A`;`m0:A`]
                 EMEET_GREATEST) THEN
    ASM_REWRITE_TAC[] THEN
    MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`m0:A`]
                 EPORDER_REFL) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* m0 <= mm2 <= K *)
  MATCH_MP_TAC(ISPECL
               [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`m0:A`;`mm2:A`;`K:A`]
               EPORDER_TRANS) THEN
  ASM_REWRITE_TAC[]);;
(* ================================================================== *)
(* RF1 (uniform lambda-star for V^B REPLACEMENT):                     *)
(* stabachieves_form + HOLDS_STABACHIEVES_FORM.                       *)
(*                                                                    *)
(* stabachieves_form fvb fva y ivb iva r  says, at a valuation whose  *)
(* p-valuation slot 32+x already carries the replacement input ss and *)
(* with gamma at slot r:  "exists dd=W_gamma. forall B-name tt.       *)
(* exists s in dd. [[p]]_{y:=s} = [[p]]_{y:=tt}"  -- i.e. the stage   *)
(* W_gamma already achieves EVERY forcing value that p(ss,-) takes as *)
(* its y-argument ranges over all B-names (V_ss is achieved by dd).   *)
(* fvb,fva are BVAL_DEFINABLE forms for p reading its value at slots  *)
(* ivb,iva; the abstract PVAL:A->A packages the two bval readings     *)
(* PVAL t = [[p]]_{y:=t} (all other p-vars from the base valuation).  *)
(* The tt/s slot-sharing (both are p's y-argument, slot 32+y) is      *)
(* resolved by CAPTURING vb=[[p(ss,tt)]] into value-slot ivb BEFORE   *)
(* the inner ??(32+y) rebinds 32+y:=s, then comparing va=[[p(ss,s)]]  *)
(* at slot iva against ivb via Eq iva ivb.                            *)
(* Templates: HOLDS_ACH_FORM (recapp3 stage bridge),                  *)
(* HOLDS_BNAME_FORM, BVAL_DEFINABLE (fvb/fva bridges                   *)
(* discharged by the consumer).  See [[forcing-replacement-design]].  *)
(* ================================================================== *)

let stabachieves_form = new_definition
  `stabachieves_form fvb fva y ivb iva r =
     ?? 11 (recapp3_form (rec_form bname_step_form 3) r 11 &&
            !! (32 + y) (bname_form (32 + y) -->
               ?? ivb (fvb &&
                  ?? (32 + y) (((32 + y) %% 11) &&
                     ?? iva (fva && Eq iva ivb)))))`;;

(* NOTE: the fvb/fva bridges and PVAL totality are GUARDED by
  bname D E (v 2) -
   the bval-choice PVAL used by the consumer is only meaningful at
     B-names (bval's
   value-graph is EMPTY off the B-names), so an all-D bridge would be
   un-instantiable.  The RHS compares PVAL only at B-names (tt under its guard,
   s in the stage dd hence a B-name),
   so the guards lose nothing.  eordinal(v r)
   is needed so that BNAME_STAGE can certify members of the stage dd
     as B-names. *)
let HOLDS_STABACHIEVES_FORM = prove
 (`!D (E:A->A->bool) v fvb fva y ivb iva r PVAL.
     model D E ZF_AX /\ valuation D v /\ eordinal D E (v r) /\
     ~(r = 3) /\ ~(r = 4) /\ ~(r = 11) /\
     ~(11 = 32 + y) /\ ~(ivb = 11) /\ ~(ivb = 32 + y) /\
     ~(iva = 11) /\ ~(iva = 32 + y) /\ ~(iva = ivb) /\
     (!t. t IN D /\ bname D E (v 2) t ==> (PVAL:A->A) t IN D) /\
     (!dd tt vb. dd IN D /\ tt IN D /\ bname D E (v 2) tt /\ vb IN D
        ==> (holds D E
             ((ivb |-> vb) (((32 + y) |-> tt) ((11 |-> dd) v))) fvb <=>
             vb = PVAL tt)) /\
     (!dd tt vb s va. dd IN D /\ tt IN D /\ vb IN D /\
                      s IN D /\ bname D E (v 2) s /\ va IN D
        ==> (holds D E ((iva |-> va)
                          (((32 + y) |-> s)
                            ((ivb |-> vb)
                              (((32 + y) |-> tt) ((11 |-> dd) v))))) fva <=>
             va = PVAL s))
     ==> (holds D E v (stabachieves_form fvb fva y ivb iva r) <=>
          ?dd. dd IN D /\ ebnstage D E (v 2) (v r) dd /\
               (!tt. tt IN D /\ bname D E (v 2) tt
                     ==> ?s. s IN D /\ E s dd /\ (PVAL:A->A) s = PVAL tt))`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `!x. (v:num->A) x IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[valuation]; ALL_TAC] THEN
  SUBGOAL_THEN
   `~(11 = ivb) /\ ~(ivb = iva) /\ ~((2:num) = 11) /\ ~((32 + y) = 11) /\
    ~((2:num) = 32 + y)`
  STRIP_ASSUME_TAC THENL [ASM_ARITH_TAC; ALL_TAC] THEN
  REWRITE_TAC[stabachieves_form; HOLDS_EX] THEN
  MATCH_MP_TAC(MESON[]
   `(!dd:A. dd IN D ==> (P dd <=> Q dd))
    ==> ((?dd. dd IN (D:A->bool) /\ P dd) <=> (?dd. dd IN D /\ Q dd))`) THEN
  X_GEN_TAC `dd:A` THEN DISCH_TAC THEN
  SUBGOAL_THEN `valuation D ((11 |-> (dd:A)) v)` ASSUME_TAC THENL
   [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
  REWRITE_TAC[HOLDS_AND] THEN
  SUBGOAL_THEN
   `holds D E ((11 |-> (dd:A)) v)
       (recapp3_form (rec_form bname_step_form 3) r 11) <=>
    ebnstage D E (v 2) (v r) dd`
  (LABEL_TAC "rec") THENL
   [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `(11 |-> (dd:A)) v`;
                  `r:num`; `11`] HOLDS_RECAPP3_BNSTEP) THEN
    ASM_REWRITE_TAC[ARITH_RULE `~(11 = 3) /\ ~(11 = 4)`] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER];
    ALL_TAC] THEN
  (* dd is generic; the equivalence only holds when dd is a genuine stage.
     Case-split on ebnstage: TRUE => members of dd are bnames (BNAME_STAGE);
     FALSE => holds(recapp3)<=>ebnstage=F kills the LHS,
     RHS conjunct also F. *)
  ASM_CASES_TAC `ebnstage D E ((v:num->A) 2) ((v:num->A) r) dd` THENL
   [ALL_TAC; ASM_REWRITE_TAC[]] THEN
  SUBGOAL_THEN `!s:A. s IN D /\ E s dd ==> bname D E ((v:num->A) 2) s`
  (LABEL_TAC "bns") THENL
   [X_GEN_TAC `s:A` THEN STRIP_TAC THEN
    MATCH_MP_TAC BNAME_STAGE THEN
    MAP_EVERY EXISTS_TAC [`(v:num->A) r`; `dd:A`] THEN
    ASM_MESON_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN
   `!tt:A. tt IN D /\ bname D E ((v:num->A) 2) tt
      ==> (holds D E (((32 + y) |-> tt) ((11 |-> (dd:A)) v))
             (?? ivb (fvb &&
                ?? (32 + y) (((32 + y) %% 11) &&
                   ?? iva (fva && Eq iva ivb)))) <=>
           ?s. s IN D /\ E s dd /\ (PVAL:A->A) s = PVAL tt)`
  (LABEL_TAC "inner") THENL
   [X_GEN_TAC `tt:A` THEN STRIP_TAC THEN
    (* specialize the fvb bridge (bname tt discharged) into a clean rewrite *)
    SUBGOAL_THEN
     `!vb:A. vb IN D
        ==> (holds D E
             ((ivb |-> vb) (((32 + y) |-> tt) ((11 |-> (dd:A)) v))) fvb <=>
             vb = (PVAL:A->A) tt)`
    (LABEL_TAC "fvbi") THENL
     [GEN_TAC THEN DISCH_TAC THEN FIRST_X_ASSUM MATCH_MP_TAC THEN
      ASM_REWRITE_TAC[]; ALL_TAC] THEN
    (* specialize the fva bridge (bname s discharged from E s dd) *)
    SUBGOAL_THEN
     `!vb s va:A. vb IN D /\ s IN D /\ E s dd /\ va IN D
        ==> (holds D E ((iva |-> va)
                          (((32 + y) |-> s)
                            ((ivb |-> vb)
                              (((32 + y) |-> tt)
                               ((11 |-> (dd:A)) v))))) fva <=>
             va = (PVAL:A->A) s)`
    (LABEL_TAC "fvai") THENL
     [REPEAT GEN_TAC THEN STRIP_TAC THEN FIRST_X_ASSUM MATCH_MP_TAC THEN
      ASM_MESON_TAC[]; ALL_TAC] THEN
    (* PVAL lands in D on the bnames we use *)
    SUBGOAL_THEN `(PVAL:A->A) tt IN D` ASSUME_TAC THENL
     [FIRST_ASSUM MATCH_MP_TAC THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN
      `!s:A. s IN D /\ (E:A->A->bool) s (dd:A) ==> (PVAL:A->A) s IN D`
      ASSUME_TAC THENL
     [X_GEN_TAC `s:A` THEN STRIP_TAC THEN FIRST_ASSUM MATCH_MP_TAC THEN
      ASM_MESON_TAC[]; ALL_TAC] THEN
    REWRITE_TAC[HOLDS_EX; HOLDS_AND; holds] THEN
    ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER] THEN
    ASM_MESON_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN
   `holds D E ((11 |-> (dd:A)) v)
       (!! (32 + y) (bname_form (32 + y) -->
          ?? ivb (fvb &&
             ?? (32 + y) (((32 + y) %% 11) &&
                ?? iva (fva && Eq iva ivb))))) <=>
    (!tt. tt IN D /\ bname D E (v 2) tt
          ==> ?s. s IN D /\ E s dd /\ (PVAL:A->A) s = PVAL tt)`
  (LABEL_TAC "allc") THENL
   [REWRITE_TAC[HOLDS_ALL] THEN
    MATCH_MP_TAC(MESON[]
     `(!tt:A. tt IN D ==> (P tt <=> (R tt ==> S tt)))
      ==> ((!tt. tt IN (D:A->bool) ==> P tt) <=>
           (!tt. tt IN D /\ R tt ==> S tt))`) THEN
    X_GEN_TAC `tt:A` THEN DISCH_TAC THEN
    SUBGOAL_THEN `valuation D (((32 + y) |-> tt) ((11 |-> (dd:A)) v))`
    ASSUME_TAC THENL [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
    REWRITE_TAC[holds] THEN
    SUBGOAL_THEN
     `holds D E (((32 + y) |-> tt) ((11 |-> (dd:A)) v))
      (bname_form (32 + y)) <=>
      bname D E (v 2) tt`
    (fun th -> REWRITE_TAC[th]) THENL
     [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
                    `((32 + y) |-> tt) ((11 |-> (dd:A)) v)`; `32 + y`]
            HOLDS_BNAME_FORM) THEN
      ASM_REWRITE_TAC[ARITH_RULE `~(32 + y = 30) /\ ~(32 + y = 31)`] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
      ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER]; ALL_TAC] THEN
    ASM_CASES_TAC `bname D E ((v:num->A) 2) tt` THENL
     [USE_THEN "inner" (fun th ->
        REWRITE_TAC[MATCH_MP th
          (CONJ (ASSUME `(tt:A) IN D`)
                (ASSUME `bname D E ((v:num->A) 2) tt`))]);
      ASM_REWRITE_TAC[]];
    ALL_TAC] THEN
  ASM_REWRITE_TAC[]);;

(* ================================================================== *)
(* RF2 (uniform lambda-star for V^B REPLACEMENT):                     *)
(* stabrank_form + HOLDS_STABRANK_FORM.                               *)
(*                                                                    *)
(* stabrank_form fvb fva y ivb iva r  is the canonical LEAST          *)
(* stabilizing stage: r is an ordinal, W_{v r} already achieves every *)
(* value p(ss,-) takes over B-names (stabachieves_form@r), and NO     *)
(* smaller ordinal c<v r does (the below-clause !!- 12 r ...).  Its   *)
(* HOLDS bridge composes HOLDS_ORDINAL_FORM (ordinal clause),         *)
(* HOLDS_STABACHIEVES_FORM (RF1, at stage-slot r and, under the below *)
(* forallmem, at stage-slot 12) and HOLDS_FORALLMEM (the bounded !!-  *)
(* over c).  eordinal(v r) is not a hypothesis -- it emerges from the *)
(* ordinal_form clause; the main stabachieves clause is dispatched    *)
(* inside an ASM_CASES on eordinal(v r) (FALSE branch collapses both  *)
(* sides via the shared eordinal conjunct), and the below-clause at   *)
(* stage-slot 12 gets eordinal c from EORDINAL_MEMBER (c IN D,         *)
(* E c (v r), eordinal(v r)) with the (12|->c)v-shifted guards reduced *)
(* to (v 2)/c by VALMOD.  Templates: HOLDS_ACHRANK_FORM.              *)
(* See [[forcing-replacement-design]].                                *)
(* ================================================================== *)

let stabrank_form = new_definition
  `stabrank_form fvb fva y ivb iva r =
     ordinal_form r &&
     stabachieves_form fvb fva y ivb iva r &&
     (!!- 12 r (Not (stabachieves_form fvb fva y ivb iva 12)))`;;

let HOLDS_STABRANK_FORM = prove
 (`!D (E:A->A->bool) v fvb fva y ivb iva r PVAL.
      model D E ZF_AX /\ valuation D v /\
      ~(r = 3) /\ ~(r = 4) /\ ~(r = 11) /\ ~(r = 12) /\
      ~(11 = 32 + y) /\ ~(ivb = 11) /\ ~(ivb = 32 + y) /\ ~(ivb = 12) /\
      ~(iva = 11) /\ ~(iva = 32 + y) /\ ~(iva = ivb) /\ ~(iva = 12) /\
      ~(32 + y = 12) /\
      (!t. t IN D /\ bname D E (v 2) t ==> (PVAL:A->A) t IN D) /\
      (!dd tt vb. dd IN D /\ tt IN D /\ bname D E (v 2) tt /\ vb IN D
         ==> (holds D E
              ((ivb |-> vb) (((32 + y) |-> tt) ((11 |-> dd) v))) fvb <=>
              vb = (PVAL:A->A) tt)) /\
      (!dd tt vb s va. dd IN D /\ tt IN D /\ vb IN D /\
                       s IN D /\ bname D E (v 2) s /\ va IN D
         ==> (holds D E ((iva |-> va)
                           (((32 + y) |-> s)
                             ((ivb |-> vb)
                               (((32 + y) |-> tt) ((11 |-> dd) v))))) fva <=>
              va = (PVAL:A->A) s)) /\
      (!c dd tt vb. c IN D /\ dd IN D /\ tt IN D /\
       bname D E (v 2) tt /\ vb IN D
       ==> (holds D E ((ivb |-> vb)
                           (((32 + y) |-> tt)
                            ((11 |-> dd) ((12 |-> c) v)))) fvb <=>
              vb = (PVAL:A->A) tt)) /\
      (!c dd tt vb s va. c IN D /\ dd IN D /\ tt IN D /\ vb IN D /\
                         s IN D /\ bname D E (v 2) s /\ va IN D
         ==> (holds D E ((iva |-> va)
                           (((32 + y) |-> s)
                             ((ivb |-> vb)
                               (((32 + y) |-> tt)
                                ((11 |-> dd) ((12 |-> c) v)))))) fva <=>
              va = (PVAL:A->A) s))
      ==> (holds D E v (stabrank_form fvb fva y ivb iva r) <=>
           eordinal D E (v r) /\
           (?dd. dd IN D /\ ebnstage D E (v 2) (v r) dd /\
                 (!tt. tt IN D /\ bname D E (v 2) tt
                       ==> ?s. s IN D /\ E s dd /\ (PVAL:A->A) s = PVAL tt)) /\
           (!c. c IN D /\ E c (v r)
                ==> ~(?dd. dd IN D /\ ebnstage D E (v 2) c dd /\
                           (!tt. tt IN D /\ bname D E (v 2) tt
                                 ==> ?s. s IN D /\ E s dd /\
                                         (PVAL:A->A) s = PVAL tt))))`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `!x. (v:num->A) x IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[valuation]; ALL_TAC] THEN
  REWRITE_TAC[stabrank_form] THEN REWRITE_TAC[HOLDS_AND] THEN
  ASM_SIMP_TAC[HOLDS_ORDINAL_FORM] THEN
  (* eordinal(v r) case-split: FALSE branch collapses both sides via the
     eordinal conjunct; TRUE branch has eordinal(v r) available to discharge
     the guarded HOLDS_STABACHIEVES_FORM's eordinal hypothesis. *)
  ASM_CASES_TAC `eordinal D E ((v:num->A) r)` THENL
   [ALL_TAC; ASM_REWRITE_TAC[]] THEN
  (* ----- main stabachieves clause at stage-slot r ----- *)
  MP_TAC(SPECL
         [`D:A->bool`; `E:A->A->bool`; `v:num->A`; `fvb:form`; `fva:form`;
         `y:num`; `ivb:num`; `iva:num`; `r:num`; `PVAL:A->A`]
        HOLDS_STABACHIEVES_FORM) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  (* ----- below-clause: !!- 12 r (Not stabachieves@12) ----- *)
  SUBGOAL_THEN
   `holds (D:A->bool) E (v:num->A)
      (!!- 12 r (Not(stabachieves_form fvb fva y ivb iva 12))) <=>
    (!c. c IN D /\ E c (v r)
         ==> ~(?dd. dd IN D /\ ebnstage D E (v 2) c dd /\
                    (!tt. tt IN D /\ bname D E (v 2) tt
                          ==> ?s. s IN D /\ E s dd /\
                            (PVAL:A->A) s = PVAL tt)))`
  ASSUME_TAC THENL
   [MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `v:num->A`; `12`; `r:num`;
                   `Not(stabachieves_form fvb fva y ivb iva 12)`]
           HOLDS_FORALLMEM) THEN
    ANTS_TAC THENL [ASM_ARITH_TAC; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    REWRITE_TAC[HOLDS_NOT] THEN
    MATCH_MP_TAC(MESON[]
     `(!a:A. G a ==> (P a <=> R a))
      ==> ((!a. G a ==> ~(P a)) <=> (!c. G c ==> ~(R c)))`) THEN
    X_GEN_TAC `c:A` THEN STRIP_TAC THEN
    SUBGOAL_THEN `eordinal D E (c:A)` ASSUME_TAC THENL
     [MATCH_MP_TAC EORDINAL_MEMBER THEN EXISTS_TAC `(v:num->A) r` THEN
      ASM_REWRITE_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN `valuation D ((12 |-> (c:A)) v)` ASSUME_TAC THENL
     [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
    (* valmod reductions used to match the shifted guards / stage args *)
    SUBGOAL_THEN
     `((12 |-> (c:A)) v) 2 = (v:num->A) 2 /\ ((12 |-> (c:A)) v) 12 = c`
    (LABEL_TAC "vmc") THENL
     [ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER; ARITH_EQ]; ALL_TAC] THEN
    (* specialize the (12|->c)v bridges at this c, as clean labeled facts;
       MATCH_MP_TAC disambiguates fvb-vs-fva and base-(12|->c) structurally *)
    SUBGOAL_THEN
     `!dd tt vb. dd IN D /\ tt IN D /\ bname D E (v 2) tt /\ vb IN D
        ==> (holds D E ((ivb |-> vb)
                          (((32 + y) |-> tt)
                           ((11 |-> dd) ((12 |-> (c:A)) v)))) fvb <=>
             vb = (PVAL:A->A) tt)`
    (LABEL_TAC "fvbc") THENL
     [REPEAT GEN_TAC THEN STRIP_TAC THEN FIRST_X_ASSUM MATCH_MP_TAC THEN
      ASM_REWRITE_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN
     `!dd tt vb s va. dd IN D /\ tt IN D /\ vb IN D /\
                      s IN D /\ bname D E (v 2) s /\ va IN D
        ==> (holds D E ((iva |-> va)
                          (((32 + y) |-> s)
                            ((ivb |-> vb)
                              (((32 + y) |-> tt)
                                ((11 |-> dd) ((12 |-> (c:A)) v)))))) fva <=>
             va = (PVAL:A->A) s)`
    (LABEL_TAC "fvac") THENL
     [REPEAT GEN_TAC THEN STRIP_TAC THEN FIRST_X_ASSUM MATCH_MP_TAC THEN
      ASM_REWRITE_TAC[]; ALL_TAC] THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `(12 |-> (c:A)) v`; `fvb:form`;
                 `fva:form`; `y:num`; `ivb:num`; `iva:num`; `12`; `PVAL:A->A`]
          HOLDS_STABACHIEVES_FORM) THEN
    USE_THEN "vmc" (fun th -> REWRITE_TAC[th]) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[ARITH_RULE `~(12 = 3) /\ ~(12 = 4) /\ ~(12 = 11)`];
      ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]);
    ALL_TAC] THEN
  ASM_REWRITE_TAC[]);;

(* ==================================================================== *)
(* RF2b: STABRANK_HOLDS_BRIDGE                                          *)
(* Instantiate HOLDS_STABRANK_FORM's opaque guarded bridge hypotheses   *)
(* by the actual bval readings: fvb,fva are BVAL_DEFINABLE forms for p   *)
(* reading the value at slots ivb,iva (leq-slot 3), and PVAL is ANY     *)
(* function computing the (unique) Boolean value [[p]]_{iy:=t} on        *)
(* B-names.  Output: holds (stabrank_form ...) reads as: alpha is the    *)
(* least B-name stage achieving every value p takes over the            *)
(* y-argument.  Mirrors ACHRANK_HOLDS_BRIDGE but with two-slot           *)
(* PVAL-equality bridges and B-name guards.                             *)
(* -------------------------------------------------------------------- *)
(* Helper tactics for the index-disequality bookkeeping lemma.          *)

let STABRANK_DISEQS =
  let CLEAN_KEEP v =
    POP_ASSUM_LIST(fun asl -> MAP_EVERY ASSUME_TAC (filter (fun th ->
      let t = concl th in
      forall (fun x -> type_of x = `:num`) (frees t)
      && (not(is_neg t && is_eq(dest_neg t)) || mem v (frees t))) asl)) in
  let DISEQ_BATCH_TAC =
    REPEAT CONJ_TAC THEN
    FIRST[ ARITH_TAC;
           FIRST_ASSUM ACCEPT_TAC;
           ONCE_REWRITE_TAC[EQ_SYM_EQ] THEN FIRST_ASSUM ACCEPT_TAC ] in
  prove
 (`!iy ivb iva r.
     ~(ivb = 2) /\ ~(ivb = 3) /\ ~(ivb = 11) /\ ~(ivb = 12) /\
     ~(ivb = 32 + iy) /\ ivb < 32 /\
     ~(iva = 2) /\ ~(iva = 3) /\ ~(iva = 11) /\ ~(iva = 12) /\
     ~(iva = 32 + iy) /\ ~(iva = ivb) /\ iva < 32 /\
     ~(r = 2) /\ ~(r = 3) /\ ~(r = 4) /\ ~(r = 11) /\ ~(r = 12) /\ r < 32 /\
     ~(11 = 32 + iy)
     ==> (~(2 = r) /\ ~(3 = r) /\ ~(2 = ivb) /\ ~(3 = ivb) /\ ~(2 = iva) /\
          ~(3 = iva) /\ ~(2 = 11) /\ ~(2 = 12) /\ ~(3 = 11) /\ ~(3 = 12) /\
          ~(2 = 32 + iy) /\ ~(3 = 32 + iy) /\ ~(11 = 12) /\ ~(ivb = iva) /\
          ~(11 = 32 + iy) /\ ~(12 = 32 + iy) /\ ~(32 + iy = 12) /\
          ~(ivb = 32 + iy) /\ ~(iva = 32 + iy) /\
          ~(32 + iy = ivb) /\ ~(32 + iy = iva) /\ ~(32 + iy = 11)) /\
         (!i:num. ~(i = iy)
             ==> ~(32 + i = 32 + iy) /\ ~(32 + i = ivb) /\ ~(32 + i = iva) /\
                 ~(32 + i = 11) /\ ~(32 + i = 12) /\ ~(32 + i = r) /\
                 ~(32 + i = 2) /\ ~(32 + i = 3)) /\
         (!j:num. ~(32 + j = r) /\ ~(32 + j = 2) /\ ~(32 + j = 3))`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN CONJ_TAC THENL
   [DISEQ_BATCH_TAC;
    CONJ_TAC THENL
     [GEN_TAC THEN DISCH_TAC THEN CLEAN_KEEP `i:num` THEN
      REPEAT CONJ_TAC THEN ASM_ARITH_TAC;
      GEN_TAC THEN CLEAN_KEEP `j:num` THEN
      REPEAT CONJ_TAC THEN ASM_ARITH_TAC]]);;

let STABRANK_HOLDS_BRIDGE = prove
 (`!(D:A->bool) (E:A->A->bool) (B:A) (leq:A) (vbase:num->A) p fvb fva
    iy ivb iva r (w0:num->A) (alpha:A) (PVAL:A->A).
      model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
      valuation D vbase /\ valuation D w0 /\ (!i. bname D E B (vbase i)) /\
      w0 2 = B /\ w0 3 = leq /\ (!i. w0 (32 + i) = vbase i) /\
      ~(ivb = 2) /\ ~(ivb = 3) /\ ~(ivb = 11) /\ ~(ivb = 12) /\
      ~(ivb = 32 + iy) /\ ivb < 32 /\
      ~(iva = 2) /\ ~(iva = 3) /\ ~(iva = 11) /\ ~(iva = 12) /\
      ~(iva = 32 + iy) /\ ~(iva = ivb) /\ iva < 32 /\
      ~(r = 2) /\ ~(r = 3) /\ ~(r = 4) /\ ~(r = 11) /\ ~(r = 12) /\ r < 32 /\
      ~(11 = 32 + iy) /\
      (!DD (EE:A->A->bool) v. model DD EE ZF_AX /\ valuation DD v /\ 3 < 32
           ==> (holds DD EE v fvb <=>
                bval DD EE (v 2) (v 3) (\i. v (32 + i)) p (v ivb))) /\
      (!DD (EE:A->A->bool) v. model DD EE ZF_AX /\ valuation DD v /\ 3 < 32
           ==> (holds DD EE v fva <=>
                bval DD EE (v 2) (v 3) (\i. v (32 + i)) p (v iva))) /\
      (!t. t IN D /\ bname D E B t
           ==> (PVAL:A->A) t IN D /\
               bval D E B leq ((iy |-> t) vbase) p (PVAL t)) /\
      alpha IN D
      ==> (holds D E ((r |-> alpha) w0)
           (stabrank_form fvb fva iy ivb iva r) <=>
           eordinal D E alpha /\
           (?dd. dd IN D /\ ebnstage D E B alpha dd /\
                 (!tt. tt IN D /\ bname D E B tt
                       ==> ?s. s IN D /\ E s dd /\ (PVAL:A->A) s = PVAL tt)) /\
           (!c. c IN D /\ E c alpha
                ==> ~(?dd. dd IN D /\ ebnstage D E B c dd /\
                           (!tt. tt IN D /\ bname D E B tt
                                 ==> ?s. s IN D /\ E s dd /\
                                         (PVAL:A->A) s = PVAL tt))))`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  MP_TAC(SPECL [`iy:num`;`ivb:num`;`iva:num`;`r:num`] STABRANK_DISEQS) THEN
  ANTS_TAC THENL
   [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
    DISCH_THEN STRIP_ASSUME_TAC] THEN
  ABBREV_TAC `v = (r |-> (alpha:A)) (w0:num->A)` THEN
  SUBGOAL_THEN `valuation D (v:num->A)` ASSUME_TAC THENL
   [EXPAND_TAC "v" THEN ASM_SIMP_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
  SUBGOAL_THEN `(v:num->A) 2 = B /\ (v:num->A) 3 = leq /\ (v:num->A) r = alpha`
   STRIP_ASSUME_TAC THENL
   [EXPAND_TAC "v" THEN ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER]; ALL_TAC] THEN
  SUBGOAL_THEN `!j:num. (v:num->A) (32 + j) = vbase j` ASSUME_TAC THENL
   [GEN_TAC THEN EXPAND_TAC "v" THEN ASM_SIMP_TAC[VALMOD_OTHER]; ALL_TAC] THEN
  (* -------- pveq: bval((iy|->t)vbase) p vv <=> vv = PVAL t (bnames) *)
  (* -------- *)
  SUBGOAL_THEN
   `!t vv:A. t IN (D:A->bool) /\ bname D (E:A->A->bool) (B:A) t /\ vv IN D
        ==> (bval D E B (leq:A) ((iy |-> t) (vbase:num->A)) p vv <=>
             vv = (PVAL:A->A) t)`
   (LABEL_TAC "pveq") THENL
   [MAP_EVERY X_GEN_TAC [`t:A`; `vv:A`] THEN STRIP_TAC THEN
    FIRST_X_ASSUM(fun th -> STRIP_ASSUME_TAC(MATCH_MP th
      (CONJ (ASSUME `(t:A) IN D`) (ASSUME `bname D E B (t:A)`)))) THEN
    EQ_TAC THENL
     [DISCH_TAC THEN MATCH_MP_TAC BVAL_UNIQUE THEN
      MAP_EVERY EXISTS_TAC
       [`p:form`; `D:A->bool`; `E:A->A->bool`; `B:A`; `leq:A`;
        `(iy |-> (t:A)) (vbase:num->A)`] THEN
      ASM_SIMP_TAC[VALUATION_VALMOD];
      DISCH_THEN(fun th -> ASM_REWRITE_TAC[th])];
    ALL_TAC] THEN
  (* -------- hb: generic bridge, given the bval reading at W -------- *)
  SUBGOAL_THEN
   `!fg islot t vv W.
       (holds (D:A->bool) (E:A->A->bool) W fg <=>
        bval D E ((W:num->A) 2) (W 3) (\i. W (32 + i)) p (W islot)) /\
       (W:num->A) 2 = (B:A) /\ W 3 = (leq:A) /\
       (!i. (W:num->A) (32 + i) = ((iy |-> t) (vbase:num->A)) i) /\
       (W:num->A) islot = vv /\
       t IN D /\ bname D E B t /\ vv IN D
       ==> (holds D E W fg <=> vv = (PVAL:A->A) t)`
   (LABEL_TAC "hb") THENL
   [REPEAT GEN_TAC THEN STRIP_TAC THEN ASM_REWRITE_TAC[ETA_AX] THEN
    USE_THEN "pveq" (fun th -> MP_TAC(SPECL [`t:A`; `vv:A`] th)) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]); ALL_TAC] THEN
  (* -------- specialized bridges bb (fvb) / ba (fva) at any valuation *)
  (* -------- *)
  SUBGOAL_THEN
   `!vq. valuation D vq
      ==> (holds D E vq fvb <=>
           bval D E ((vq:num->A) 2) (vq 3) (\i. vq (32 + i)) p (vq ivb))`
   (LABEL_TAC "bb") THENL
   [GEN_TAC THEN DISCH_TAC THEN FIRST_X_ASSUM MATCH_MP_TAC THEN
    ASM_REWRITE_TAC[] THEN ARITH_TAC; ALL_TAC] THEN
  SUBGOAL_THEN
   `!vq. valuation D vq
      ==> (holds D E vq fva <=>
           bval D E ((vq:num->A) 2) (vq 3) (\i. vq (32 + i)) p (vq iva))`
   (LABEL_TAC "ba") THENL
   [GEN_TAC THEN DISCH_TAC THEN FIRST_X_ASSUM MATCH_MP_TAC THEN
    ASM_REWRITE_TAC[] THEN ARITH_TAC; ALL_TAC] THEN
  (* ======== the five bridge facts for HOLDS_STABRANK_FORM ======== *)
  (* PVAL totality *)
  SUBGOAL_THEN `!t. t IN D /\ bname D E B t ==> (PVAL:A->A) t IN D`
   (LABEL_TAC "ptot") THENL
   [REPEAT STRIP_TAC THEN FIRST_X_ASSUM(fun th -> MP_TAC(MATCH_MP th
      (CONJ (ASSUME `(t:A) IN D`) (ASSUME `bname D E B (t:A)`)))) THEN
    SIMP_TAC[]; ALL_TAC] THEN
  (* --- fvb base bridge --- *)
  SUBGOAL_THEN
   `!dd tt vb. dd IN D /\ tt IN D /\ bname D E B tt /\ vb IN D
      ==> (holds D E
           ((ivb |-> vb) (((32 + iy) |-> tt) ((11 |-> dd) v))) fvb <=>
           vb = (PVAL:A->A) tt)`
   (LABEL_TAC "brb") THENL
   [MAP_EVERY X_GEN_TAC [`dd:A`; `tt:A`; `vb:A`] THEN STRIP_TAC THEN
    ABBREV_TAC `W = (ivb |-> vb) (((32 + iy) |-> tt) ((11 |-> (dd:A)) v))` THEN
    SUBGOAL_THEN `valuation D (W:num->A)` ASSUME_TAC THENL
     [EXPAND_TAC "W" THEN
      REPEAT(MATCH_MP_TAC VALUATION_VALMOD THEN CONJ_TAC THENL
              [ALL_TAC; FIRST_ASSUM ACCEPT_TAC]) THEN
      FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    USE_THEN "hb" MATCH_MP_TAC THEN
    EXISTS_TAC `ivb:num` THEN
    REPEAT CONJ_TAC THENL
     [USE_THEN "bb" MATCH_MP_TAC THEN FIRST_ASSUM ACCEPT_TAC;
      EXPAND_TAC "W" THEN ASM_SIMP_TAC[VALMOD_OTHER];
      EXPAND_TAC "W" THEN ASM_SIMP_TAC[VALMOD_OTHER];
      X_GEN_TAC `i:num` THEN
      ASM_CASES_TAC `i:num = iy` THENL
       [ASM_REWRITE_TAC[] THEN EXPAND_TAC "W" THEN
        ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER];
        FIRST_X_ASSUM(fun th ->
          STRIP_ASSUME_TAC(MATCH_MP th (ASSUME `~(i:num = iy)`))) THEN
        EXPAND_TAC "W" THEN ASM_SIMP_TAC[VALMOD_OTHER; VALMOD_BASIC]];
      EXPAND_TAC "W" THEN ASM_SIMP_TAC[VALMOD_BASIC];
      FIRST_ASSUM ACCEPT_TAC;
      FIRST_ASSUM ACCEPT_TAC;
      FIRST_ASSUM ACCEPT_TAC];
    ALL_TAC] THEN
  (* --- fva base bridge --- *)
  SUBGOAL_THEN
   `!dd tt vb s va. dd IN D /\ tt IN D /\ vb IN D /\
                    s IN D /\ bname D E B s /\ va IN D
      ==> (holds D E ((iva |-> va)
                        (((32 + iy) |-> s)
                          ((ivb |-> vb)
                            (((32 + iy) |-> tt) ((11 |-> dd) v))))) fva <=>
           va = (PVAL:A->A) s)`
   (LABEL_TAC "bra") THENL
   [MAP_EVERY X_GEN_TAC [`dd:A`; `tt:A`; `vb:A`; `s:A`; `va:A`] THEN
    STRIP_TAC THEN
    ABBREV_TAC `W = (iva |-> va)
                      (((32 + iy) |-> s)
                        ((ivb |-> vb)
                          (((32 + iy) |-> tt) ((11 |-> (dd:A)) v))))` THEN
    SUBGOAL_THEN `valuation D (W:num->A)` ASSUME_TAC THENL
     [EXPAND_TAC "W" THEN
      REPEAT(MATCH_MP_TAC VALUATION_VALMOD THEN CONJ_TAC THENL
              [ALL_TAC; FIRST_ASSUM ACCEPT_TAC]) THEN
      FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    USE_THEN "hb" MATCH_MP_TAC THEN
    EXISTS_TAC `iva:num` THEN
    REPEAT CONJ_TAC THENL
     [USE_THEN "ba" MATCH_MP_TAC THEN FIRST_ASSUM ACCEPT_TAC;
      EXPAND_TAC "W" THEN ASM_SIMP_TAC[VALMOD_OTHER];
      EXPAND_TAC "W" THEN ASM_SIMP_TAC[VALMOD_OTHER];
      X_GEN_TAC `i:num` THEN
      ASM_CASES_TAC `i:num = iy` THENL
       [ASM_REWRITE_TAC[] THEN EXPAND_TAC "W" THEN
        ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER];
        FIRST_X_ASSUM(fun th ->
          STRIP_ASSUME_TAC(MATCH_MP th (ASSUME `~(i:num = iy)`))) THEN
        EXPAND_TAC "W" THEN ASM_SIMP_TAC[VALMOD_OTHER; VALMOD_BASIC]];
      EXPAND_TAC "W" THEN ASM_SIMP_TAC[VALMOD_BASIC];
      FIRST_ASSUM ACCEPT_TAC;
      FIRST_ASSUM ACCEPT_TAC;
      FIRST_ASSUM ACCEPT_TAC];
    ALL_TAC] THEN
  (* --- fvb (12|->c) bridge --- *)
  SUBGOAL_THEN
   `!c dd tt vb. c IN D /\ dd IN D /\ tt IN D /\ bname D E B tt /\ vb IN D
      ==> (holds D E ((ivb |-> vb)
                        (((32 + iy) |-> tt)
                         ((11 |-> dd) ((12 |-> c) v)))) fvb <=>
           vb = (PVAL:A->A) tt)`
   (LABEL_TAC "brbc") THENL
   [MAP_EVERY X_GEN_TAC [`c:A`; `dd:A`; `tt:A`; `vb:A`] THEN STRIP_TAC THEN
    ABBREV_TAC `W = (ivb |-> vb)
                      (((32 + iy) |-> tt)
                       ((11 |-> dd) ((12 |-> (c:A)) v)))` THEN
    SUBGOAL_THEN `valuation D (W:num->A)` ASSUME_TAC THENL
     [EXPAND_TAC "W" THEN
      REPEAT(MATCH_MP_TAC VALUATION_VALMOD THEN CONJ_TAC THENL
              [ALL_TAC; FIRST_ASSUM ACCEPT_TAC]) THEN
      FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    USE_THEN "hb" MATCH_MP_TAC THEN
    EXISTS_TAC `ivb:num` THEN
    REPEAT CONJ_TAC THENL
     [USE_THEN "bb" MATCH_MP_TAC THEN FIRST_ASSUM ACCEPT_TAC;
      EXPAND_TAC "W" THEN ASM_SIMP_TAC[VALMOD_OTHER];
      EXPAND_TAC "W" THEN ASM_SIMP_TAC[VALMOD_OTHER];
      X_GEN_TAC `i:num` THEN
      ASM_CASES_TAC `i:num = iy` THENL
       [ASM_REWRITE_TAC[] THEN EXPAND_TAC "W" THEN
        ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER];
        FIRST_X_ASSUM(fun th ->
          STRIP_ASSUME_TAC(MATCH_MP th (ASSUME `~(i:num = iy)`))) THEN
        EXPAND_TAC "W" THEN ASM_SIMP_TAC[VALMOD_OTHER; VALMOD_BASIC]];
      EXPAND_TAC "W" THEN ASM_SIMP_TAC[VALMOD_BASIC];
      FIRST_ASSUM ACCEPT_TAC;
      FIRST_ASSUM ACCEPT_TAC;
      FIRST_ASSUM ACCEPT_TAC];
    ALL_TAC] THEN
  (* --- fva (12|->c) bridge --- *)
  SUBGOAL_THEN
   `!c dd tt vb s va. c IN D /\ dd IN D /\ tt IN D /\ vb IN D /\
                      s IN D /\ bname D E B s /\ va IN D
      ==> (holds D E ((iva |-> va)
                        (((32 + iy) |-> s)
                          ((ivb |-> vb)
                            (((32 + iy) |-> tt)
                             ((11 |-> dd) ((12 |-> c) v)))))) fva <=>
           va = (PVAL:A->A) s)`
   (LABEL_TAC "brac") THENL
   [MAP_EVERY X_GEN_TAC [`c:A`; `dd:A`; `tt:A`; `vb:A`; `s:A`; `va:A`] THEN
    STRIP_TAC THEN
    ABBREV_TAC `W = (iva |-> va)
                      (((32 + iy) |-> s)
                        ((ivb |-> vb)
                          (((32 + iy) |-> tt)
                           ((11 |-> dd) ((12 |-> (c:A)) v)))))` THEN
    SUBGOAL_THEN `valuation D (W:num->A)` ASSUME_TAC THENL
     [EXPAND_TAC "W" THEN
      REPEAT(MATCH_MP_TAC VALUATION_VALMOD THEN CONJ_TAC THENL
              [ALL_TAC; FIRST_ASSUM ACCEPT_TAC]) THEN
      FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    USE_THEN "hb" MATCH_MP_TAC THEN
    EXISTS_TAC `iva:num` THEN
    REPEAT CONJ_TAC THENL
     [USE_THEN "ba" MATCH_MP_TAC THEN FIRST_ASSUM ACCEPT_TAC;
      EXPAND_TAC "W" THEN ASM_SIMP_TAC[VALMOD_OTHER];
      EXPAND_TAC "W" THEN ASM_SIMP_TAC[VALMOD_OTHER];
      X_GEN_TAC `i:num` THEN
      ASM_CASES_TAC `i:num = iy` THENL
       [ASM_REWRITE_TAC[] THEN EXPAND_TAC "W" THEN
        ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER];
        FIRST_X_ASSUM(fun th ->
          STRIP_ASSUME_TAC(MATCH_MP th (ASSUME `~(i:num = iy)`))) THEN
        EXPAND_TAC "W" THEN ASM_SIMP_TAC[VALMOD_OTHER; VALMOD_BASIC]];
      EXPAND_TAC "W" THEN ASM_SIMP_TAC[VALMOD_BASIC];
      FIRST_ASSUM ACCEPT_TAC;
      FIRST_ASSUM ACCEPT_TAC;
      FIRST_ASSUM ACCEPT_TAC];
    ALL_TAC] THEN
  (* ======== assemble via HOLDS_STABRANK_FORM ======== *)
  MP_TAC(SPECL
         [`D:A->bool`; `E:A->A->bool`; `v:num->A`; `fvb:form`; `fva:form`;
         `iy:num`; `ivb:num`; `iva:num`; `r:num`; `PVAL:A->A`]
        HOLDS_STABRANK_FORM) THEN
  ANTS_TAC THENL
   [REWRITE_TAC[ASSUME `(v:num->A) 2 = (B:A)`] THEN
    REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
    ALL_TAC] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN ASM_REWRITE_TAC[]);;

(* ------------------------------------------------------------------ *)
(* RF3: stabilizing-rank uniqueness and existence.                     *)
(*                                                                     *)
(* stabrank_form fvb fva iy ivb iva r picks, at ordinal (v r), the     *)
(* LEAST B-name stage ordinal whose stage dd "achieves all values":    *)
(* every B-name tt has a member s of dd with the same forcing value    *)
(* PVAL s = PVAL tt.  STABRANK_UNIQUE (functionality) and              *)
(* STABRANK_EXISTS (a least such ordinal exists for every parameter)   *)
(* are the two facts ZF_REPLACEMENT needs to form the image LAMS in    *)
(* RF4.                                                                *)
(* ------------------------------------------------------------------ *)

let STABRANK_UNIQUE = prove
 (`!D (E:A->A->bool) B2 (PVAL:A->A) a a'.
      model D E ZF_AX /\
      eordinal D E a /\
      (?dd. dd IN D /\ ebnstage D E B2 a dd /\
            (!tt. tt IN D /\ bname D E B2 tt
                  ==> ?s. s IN D /\ E s dd /\ PVAL s = PVAL tt)) /\
      (!c. c IN D /\ E c a
           ==> ~(?dd. dd IN D /\ ebnstage D E B2 c dd /\
                      (!tt. tt IN D /\ bname D E B2 tt
                            ==> ?s. s IN D /\ E s dd /\ PVAL s = PVAL tt))) /\
      eordinal D E a' /\
      (?dd. dd IN D /\ ebnstage D E B2 a' dd /\
            (!tt. tt IN D /\ bname D E B2 tt
                  ==> ?s. s IN D /\ E s dd /\ PVAL s = PVAL tt)) /\
      (!c. c IN D /\ E c a'
           ==> ~(?dd. dd IN D /\ ebnstage D E B2 c dd /\
                      (!tt. tt IN D /\ bname D E B2 tt
                            ==> ?s. s IN D /\ E s dd /\ PVAL s = PVAL tt)))
      ==> a = a'`,
  REPEAT GEN_TAC THEN DISCH_TAC THEN
  MATCH_MP_TAC(ISPECL
    [`D:A->bool`; `E:A->A->bool`;
     `\x:A. ?dd. dd IN D /\ ebnstage D E B2 x dd /\
                 (!tt. tt IN D /\ bname D E B2 tt
                       ==> ?s. s IN D /\ E s dd /\ (PVAL:A->A) s = PVAL tt)`;
     `a:A`; `a':A`] LEAST_ORD_UNIQUE) THEN
  BETA_TAC THEN FIRST_ASSUM ACCEPT_TAC);;

(* STAB_PRED_OF_LAMBDA: STABILIZE_LAMBDA's V_ss-realization, repackaged as   *)
(* the stab-predicate (every B-name has a same-value member of the stage).  *)
let STAB_PRED_OF_LAMBDA = prove
 (`!D (E:A->A->bool) B leq vbase p fp iy r_val r w0 Vss (PVAL:A->A).
      model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
      valuation D vbase /\ valuation D w0 /\
      w0 2 = B /\ w0 3 = leq /\ (!i. w0 (32 + i) = vbase i) /\
      ~(r_val = 0) /\ ~(r_val = 2) /\ ~(r_val = 3) /\ ~(r_val = 4) /\
      ~(r_val = 11) /\ ~(r_val = 12) /\
      ~(r = 2) /\ ~(r = 3) /\ ~(r = 4) /\ ~(r = 11) /\ ~(r = 12) /\
        ~(r = r_val) /\
      ~(32 + iy = 11) /\ ~(32 + iy = r_val) /\ ~(32 + iy = r) /\
      r_val < 32 /\ r < 32 /\
      (!v. valuation D v
           ==> (holds D E v fp <=>
                bval D E (v 2) (v 3) (\i. v (32 + i)) p (v r_val))) /\
      Vss IN D /\
      (!b. b IN D
           ==> (E b Vss <=>
                ?a. a IN D /\ bname D E B a /\
                    bval D E B leq ((iy |-> a) vbase) p b)) /\
      (!t. t IN D /\ bname D E B t
           ==> (PVAL:A->A) t IN D /\
             bval D E B leq ((iy |-> t) vbase) p (PVAL t))
      ==> ?lam. eordinal D E lam /\ lam IN D /\
                (?dd. dd IN D /\ ebnstage D E B lam dd /\
                      (!tt. tt IN D /\ bname D E B tt
                            ==> ?s. s IN D /\ E s dd /\
                              (PVAL:A->A) s = PVAL tt))`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  MP_TAC(ISPECL
    [`D:A->bool`; `E:A->A->bool`; `B:A`; `leq:A`; `vbase:num->A`; `p:form`;
     `fp:form`; `iy:num`; `r_val:num`; `r:num`; `w0:num->A`; `Vss:A`]
    STABILIZE_LAMBDA) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `lam:A`
             (X_CHOOSE_THEN `dd:A` STRIP_ASSUME_TAC)) THEN
  EXISTS_TAC `lam:A` THEN ASM_REWRITE_TAC[] THEN
  EXISTS_TAC `dd:A` THEN ASM_REWRITE_TAC[] THEN
  X_GEN_TAC `tt:A` THEN STRIP_TAC THEN
  SUBGOAL_THEN
    `(PVAL:A->A) tt IN D /\ bval D E B leq ((iy |-> tt) vbase) p (PVAL tt)`
  STRIP_ASSUME_TAC THENL
   [FIRST_X_ASSUM(fun th -> MATCH_MP_TAC th) THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) ((PVAL:A->A) tt) (Vss:A)` ASSUME_TAC THENL
   [FIRST_X_ASSUM(fun th ->
      MP_TAC(SPEC `(PVAL:A->A) tt` th) THEN
      ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC]) THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    EXISTS_TAC `tt:A` THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  FIRST_X_ASSUM(fun th ->
    MP_TAC(SPEC `(PVAL:A->A) tt` th) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC]) THEN
  DISCH_THEN(X_CHOOSE_THEN `s:A` STRIP_ASSUME_TAC) THEN
  EXISTS_TAC `s:A` THEN ASM_REWRITE_TAC[] THEN
  SUBGOAL_THEN `bname D E B (s:A)` ASSUME_TAC THENL
   [MATCH_MP_TAC BNAME_STAGE THEN
    MAP_EVERY EXISTS_TAC [`lam:A`; `dd:A`] THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
    `(PVAL:A->A) s IN D /\ bval D E B leq ((iy |-> s) vbase) p (PVAL s)`
  STRIP_ASSUME_TAC THENL
   [FIRST_X_ASSUM(fun th -> MATCH_MP_TAC th) THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  MATCH_MP_TAC(ISPECL
    [`p:form`; `D:A->bool`; `E:A->A->bool`; `B:A`; `leq:A`;
     `((iy:num) |-> (s:A)) (vbase:num->A)`;
     `(PVAL:A->A) s`; `(PVAL:A->A) tt`] BVAL_UNIQUE) THEN
  ASM_REWRITE_TAC[] THEN
  MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[]);;

(* STABACHIEVES_HOLDS_BRIDGE: from the two general fvb/fva bridges, read     *)
(* holds(stabachieves_form) at any valuation v as the stab-predicate at the  *)
(* stage ordinal (v r).  (RF2b prefix minus the (12|->c) shifts, closed by   *)
(* HOLDS_STABACHIEVES_FORM.)                                                 *)
let STABACHIEVES_HOLDS_BRIDGE = prove
 (`!(D:A->bool) (E:A->A->bool) (B:A) (leq:A) (vbase:num->A) p fvb fva
    iy ivb iva r (v:num->A) (PVAL:A->A).
      model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
      valuation D vbase /\ valuation D v /\
      v 2 = B /\ v 3 = leq /\ (!i. v (32 + i) = vbase i) /\
      eordinal D E (v r) /\
      ~(ivb = 2) /\ ~(ivb = 3) /\ ~(ivb = 11) /\ ~(ivb = 12) /\
      ~(ivb = 32 + iy) /\ ivb < 32 /\
      ~(iva = 2) /\ ~(iva = 3) /\ ~(iva = 11) /\ ~(iva = 12) /\
      ~(iva = 32 + iy) /\ ~(iva = ivb) /\ iva < 32 /\
      ~(r = 2) /\ ~(r = 3) /\ ~(r = 4) /\ ~(r = 11) /\ ~(r = 12) /\ r < 32 /\
      ~(11 = 32 + iy) /\
      (!DD (EE:A->A->bool) w. model DD EE ZF_AX /\ valuation DD w /\ 3 < 32
           ==> (holds DD EE w fvb <=>
                bval DD EE (w 2) (w 3) (\i. w (32 + i)) p (w ivb))) /\
      (!DD (EE:A->A->bool) w. model DD EE ZF_AX /\ valuation DD w /\ 3 < 32
           ==> (holds DD EE w fva <=>
                bval DD EE (w 2) (w 3) (\i. w (32 + i)) p (w iva))) /\
      (!t. t IN D /\ bname D E B t
           ==> (PVAL:A->A) t IN D /\
               bval D E B leq ((iy |-> t) vbase) p (PVAL t))
      ==> (holds D E v (stabachieves_form fvb fva iy ivb iva r) <=>
           ?dd. dd IN D /\ ebnstage D E B (v r) dd /\
                (!tt. tt IN D /\ bname D E B tt
                      ==> ?s. s IN D /\ E s dd /\ (PVAL:A->A) s = PVAL tt))`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  MP_TAC(SPECL [`iy:num`;`ivb:num`;`iva:num`;`r:num`] STABRANK_DISEQS) THEN
  ANTS_TAC THENL
   [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
    DISCH_THEN STRIP_ASSUME_TAC] THEN
  SUBGOAL_THEN `!j:num. (v:num->A) (32 + j) = vbase j` ASSUME_TAC THENL
   [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN
   `!t vv:A. t IN (D:A->bool) /\ bname D (E:A->A->bool) (B:A) t /\ vv IN D
        ==> (bval D E B (leq:A) ((iy |-> t) (vbase:num->A)) p vv <=>
             vv = (PVAL:A->A) t)`
   (LABEL_TAC "pveq") THENL
   [MAP_EVERY X_GEN_TAC [`t:A`; `vv:A`] THEN STRIP_TAC THEN
    FIRST_X_ASSUM(fun th -> STRIP_ASSUME_TAC(MATCH_MP th
      (CONJ (ASSUME `(t:A) IN D`) (ASSUME `bname D E B (t:A)`)))) THEN
    EQ_TAC THENL
     [DISCH_TAC THEN MATCH_MP_TAC BVAL_UNIQUE THEN
      MAP_EVERY EXISTS_TAC
       [`p:form`; `D:A->bool`; `E:A->A->bool`; `B:A`; `leq:A`;
        `(iy |-> (t:A)) (vbase:num->A)`] THEN
      ASM_SIMP_TAC[VALUATION_VALMOD];
      DISCH_THEN(fun th -> ASM_REWRITE_TAC[th])];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!fg islot t vv W.
       (holds (D:A->bool) (E:A->A->bool) W fg <=>
        bval D E ((W:num->A) 2) (W 3) (\i. W (32 + i)) p (W islot)) /\
       (W:num->A) 2 = (B:A) /\ W 3 = (leq:A) /\
       (!i. (W:num->A) (32 + i) = ((iy |-> t) (vbase:num->A)) i) /\
       (W:num->A) islot = vv /\
       t IN D /\ bname D E B t /\ vv IN D
       ==> (holds D E W fg <=> vv = (PVAL:A->A) t)`
   (LABEL_TAC "hb") THENL
   [REPEAT GEN_TAC THEN STRIP_TAC THEN ASM_REWRITE_TAC[ETA_AX] THEN
    USE_THEN "pveq" (fun th -> MP_TAC(SPECL [`t:A`; `vv:A`] th)) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]); ALL_TAC] THEN
  SUBGOAL_THEN
   `!vq. valuation D vq
      ==> (holds D E vq fvb <=>
           bval D E ((vq:num->A) 2) (vq 3) (\i. vq (32 + i)) p (vq ivb))`
   (LABEL_TAC "bb") THENL
   [GEN_TAC THEN DISCH_TAC THEN FIRST_X_ASSUM MATCH_MP_TAC THEN
    ASM_REWRITE_TAC[] THEN ARITH_TAC; ALL_TAC] THEN
  SUBGOAL_THEN
   `!vq. valuation D vq
      ==> (holds D E vq fva <=>
           bval D E ((vq:num->A) 2) (vq 3) (\i. vq (32 + i)) p (vq iva))`
   (LABEL_TAC "ba") THENL
   [GEN_TAC THEN DISCH_TAC THEN FIRST_X_ASSUM MATCH_MP_TAC THEN
    ASM_REWRITE_TAC[] THEN ARITH_TAC; ALL_TAC] THEN
  SUBGOAL_THEN `!t. t IN D /\ bname D E B t ==> (PVAL:A->A) t IN D`
   (LABEL_TAC "ptot") THENL
   [REPEAT STRIP_TAC THEN FIRST_X_ASSUM(fun th -> MP_TAC(MATCH_MP th
      (CONJ (ASSUME `(t:A) IN D`) (ASSUME `bname D E B (t:A)`)))) THEN
    SIMP_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN
   `!dd tt vb. dd IN D /\ tt IN D /\ bname D E B tt /\ vb IN D
      ==> (holds D E
           ((ivb |-> vb) (((32 + iy) |-> tt) ((11 |-> dd) v))) fvb <=>
           vb = (PVAL:A->A) tt)`
   (LABEL_TAC "brb") THENL
   [MAP_EVERY X_GEN_TAC [`dd:A`; `tt:A`; `vb:A`] THEN STRIP_TAC THEN
    ABBREV_TAC `W = (ivb |-> vb) (((32 + iy) |-> tt) ((11 |-> (dd:A)) v))` THEN
    SUBGOAL_THEN `valuation D (W:num->A)` ASSUME_TAC THENL
     [EXPAND_TAC "W" THEN
      REPEAT(MATCH_MP_TAC VALUATION_VALMOD THEN CONJ_TAC THENL
              [ALL_TAC; FIRST_ASSUM ACCEPT_TAC]) THEN
      FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    USE_THEN "hb" MATCH_MP_TAC THEN
    EXISTS_TAC `ivb:num` THEN
    REPEAT CONJ_TAC THENL
     [USE_THEN "bb" MATCH_MP_TAC THEN FIRST_ASSUM ACCEPT_TAC;
      EXPAND_TAC "W" THEN ASM_SIMP_TAC[VALMOD_OTHER];
      EXPAND_TAC "W" THEN ASM_SIMP_TAC[VALMOD_OTHER];
      X_GEN_TAC `i:num` THEN
      ASM_CASES_TAC `i:num = iy` THENL
       [ASM_REWRITE_TAC[] THEN EXPAND_TAC "W" THEN
        ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER];
        FIRST_X_ASSUM(fun th ->
          STRIP_ASSUME_TAC(MATCH_MP th (ASSUME `~(i:num = iy)`))) THEN
        EXPAND_TAC "W" THEN ASM_SIMP_TAC[VALMOD_OTHER; VALMOD_BASIC]];
      EXPAND_TAC "W" THEN ASM_SIMP_TAC[VALMOD_BASIC];
      FIRST_ASSUM ACCEPT_TAC;
      FIRST_ASSUM ACCEPT_TAC;
      FIRST_ASSUM ACCEPT_TAC];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!dd tt vb s va. dd IN D /\ tt IN D /\ vb IN D /\
                    s IN D /\ bname D E B s /\ va IN D
      ==> (holds D E ((iva |-> va)
                        (((32 + iy) |-> s)
                          ((ivb |-> vb)
                            (((32 + iy) |-> tt) ((11 |-> dd) v))))) fva <=>
           va = (PVAL:A->A) s)`
   (LABEL_TAC "bra") THENL
   [MAP_EVERY X_GEN_TAC [`dd:A`; `tt:A`; `vb:A`; `s:A`; `va:A`] THEN
    STRIP_TAC THEN
    ABBREV_TAC `W = (iva |-> va)
                      (((32 + iy) |-> s)
                        ((ivb |-> vb)
                          (((32 + iy) |-> tt) ((11 |-> (dd:A)) v))))` THEN
    SUBGOAL_THEN `valuation D (W:num->A)` ASSUME_TAC THENL
     [EXPAND_TAC "W" THEN
      REPEAT(MATCH_MP_TAC VALUATION_VALMOD THEN CONJ_TAC THENL
              [ALL_TAC; FIRST_ASSUM ACCEPT_TAC]) THEN
      FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    USE_THEN "hb" MATCH_MP_TAC THEN
    EXISTS_TAC `iva:num` THEN
    REPEAT CONJ_TAC THENL
     [USE_THEN "ba" MATCH_MP_TAC THEN FIRST_ASSUM ACCEPT_TAC;
      EXPAND_TAC "W" THEN ASM_SIMP_TAC[VALMOD_OTHER];
      EXPAND_TAC "W" THEN ASM_SIMP_TAC[VALMOD_OTHER];
      X_GEN_TAC `i:num` THEN
      ASM_CASES_TAC `i:num = iy` THENL
       [ASM_REWRITE_TAC[] THEN EXPAND_TAC "W" THEN
        ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER];
        FIRST_X_ASSUM(fun th ->
          STRIP_ASSUME_TAC(MATCH_MP th (ASSUME `~(i:num = iy)`))) THEN
        EXPAND_TAC "W" THEN ASM_SIMP_TAC[VALMOD_OTHER; VALMOD_BASIC]];
      EXPAND_TAC "W" THEN ASM_SIMP_TAC[VALMOD_BASIC];
      FIRST_ASSUM ACCEPT_TAC;
      FIRST_ASSUM ACCEPT_TAC;
      FIRST_ASSUM ACCEPT_TAC];
    ALL_TAC] THEN
  MP_TAC(SPECL
         [`D:A->bool`; `E:A->A->bool`; `v:num->A`; `fvb:form`; `fva:form`;
         `iy:num`; `ivb:num`; `iva:num`; `r:num`; `PVAL:A->A`]
        HOLDS_STABACHIEVES_FORM) THEN
  ANTS_TAC THENL
   [REWRITE_TAC[ASSUME `(v:num->A) 2 = (B:A)`] THEN
    REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
    ALL_TAC] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN ASM_REWRITE_TAC[]);;

(* STABRANK_EXISTS: for every parameter there is a LEAST stabilizing rank.   *)
(* Seed via STAB_PRED_OF_LAMBDA, achP bridge via STABACHIEVES_HOLDS_BRIDGE   *)
(* at slot 0, then EORDINAL_LEAST (mirrors ACHRANK_EXISTS).                  *)
let STABRANK_EXISTS = prove
 (`!D (E:A->A->bool) B leq vbase p fp fvb fva iy ivb iva r_val r w0 Vss
   (PVAL:A->A).
      model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
      valuation D vbase /\ valuation D w0 /\
      w0 2 = B /\ w0 3 = leq /\ (!i. w0 (32 + i) = vbase i) /\
      ~(r_val = 0) /\ ~(r_val = 2) /\ ~(r_val = 3) /\ ~(r_val = 4) /\
      ~(r_val = 11) /\ ~(r_val = 12) /\
      ~(r = 2) /\ ~(r = 3) /\ ~(r = 4) /\ ~(r = 11) /\ ~(r = 12) /\
        ~(r = r_val) /\
      ~(32 + iy = 11) /\ ~(32 + iy = r_val) /\ ~(32 + iy = r) /\
      r_val < 32 /\ r < 32 /\
      ~(ivb = 2) /\ ~(ivb = 3) /\ ~(ivb = 11) /\ ~(ivb = 12) /\
      ~(ivb = 32 + iy) /\ ivb < 32 /\
      ~(iva = 2) /\ ~(iva = 3) /\ ~(iva = 11) /\ ~(iva = 12) /\
      ~(iva = 32 + iy) /\ ~(iva = ivb) /\ iva < 32 /\
      ~(11 = 32 + iy) /\
      (!v. valuation D v
           ==> (holds D E v fp <=>
                bval D E (v 2) (v 3) (\i. v (32 + i)) p (v r_val))) /\
      (!DD (EE:A->A->bool) w. model DD EE ZF_AX /\ valuation DD w /\ 3 < 32
           ==> (holds DD EE w fvb <=>
                bval DD EE (w 2) (w 3) (\i. w (32 + i)) p (w ivb))) /\
      (!DD (EE:A->A->bool) w. model DD EE ZF_AX /\ valuation DD w /\ 3 < 32
           ==> (holds DD EE w fva <=>
                bval DD EE (w 2) (w 3) (\i. w (32 + i)) p (w iva))) /\
      Vss IN D /\
      (!b. b IN D
           ==> (E b Vss <=>
                ?a. a IN D /\ bname D E B a /\
                    bval D E B leq ((iy |-> a) vbase) p b)) /\
      (!t. t IN D /\ bname D E B t
           ==> (PVAL:A->A) t IN D /\
               bval D E B leq ((iy |-> t) vbase) p (PVAL t))
      ==> ?alpha. alpha IN D /\ eordinal D E alpha /\
                  (?dd. dd IN D /\ ebnstage D E B alpha dd /\
                        (!tt. tt IN D /\ bname D E B tt
                              ==> ?s. s IN D /\ E s dd /\
                                (PVAL:A->A) s = PVAL tt)) /\
                  (!c. c IN D /\ E c alpha
                       ==> ~(?dd. dd IN D /\ ebnstage D E B c dd /\
                                  (!tt. tt IN D /\ bname D E B tt
                                        ==> ?s. s IN D /\ E s dd /\
                                                (PVAL:A->A) s = PVAL tt)))`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN
   `~(0 = 2) /\ ~(0 = 3) /\ ~(0 = 4) /\ ~(0:num = 11) /\ ~(0 = 12) /\ 0 < 32 /\
    ~(2:num = 0) /\ ~(3:num = 0)`
   STRIP_ASSUME_TAC THENL [ARITH_TAC; ALL_TAC] THEN
  SUBGOAL_THEN `!i:num. ~(32 + i = 0)` ASSUME_TAC THENL
   [GEN_TAC THEN ARITH_TAC; ALL_TAC] THEN
  SUBGOAL_THEN
   `!d:A. d IN D /\ eordinal D E d
      ==> (holds D E ((0 |-> d) w0)
           (stabachieves_form fvb fva iy ivb iva 0) <=>
           (?dd. dd IN D /\ ebnstage D E B d dd /\
                 (!tt. tt IN D /\ bname D E B tt
                       ==> ?s. s IN D /\ E s dd /\ (PVAL:A->A) s = PVAL tt)))`
   (LABEL_TAC "achP") THENL
   [X_GEN_TAC `d:A` THEN STRIP_TAC THEN
    SUBGOAL_THEN
     `valuation D ((0 |-> (d:A)) w0) /\
      ((0 |-> (d:A)) w0) 2 = B /\ ((0 |-> (d:A)) w0) 3 = leq /\
      (!i. ((0 |-> (d:A)) w0) (32 + i) = vbase i) /\
      ((0 |-> (d:A)) w0) 0 = d`
     STRIP_ASSUME_TAC THENL
     [ASM_SIMP_TAC[VALUATION_VALMOD; VALMOD_BASIC; VALMOD_OTHER]; ALL_TAC] THEN
    MP_TAC(SPECL
      [`D:A->bool`; `E:A->A->bool`; `B:A`; `leq:A`; `vbase:num->A`; `p:form`;
       `fvb:form`; `fva:form`; `iy:num`; `ivb:num`; `iva:num`; `0`;
       `(0 |-> (d:A)) w0`; `PVAL:A->A`] STABACHIEVES_HOLDS_BRIDGE) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[] THEN REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
      ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  MP_TAC(ISPECL
    [`D:A->bool`; `E:A->A->bool`; `B:A`; `leq:A`; `vbase:num->A`; `p:form`;
     `fp:form`; `iy:num`; `r_val:num`; `r:num`; `w0:num->A`; `Vss:A`;
     `PVAL:A->A`]
    STAB_PRED_OF_LAMBDA) THEN
  ANTS_TAC THENL
   [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `lam:A`
    (CONJUNCTS_THEN2 ASSUME_TAC (CONJUNCTS_THEN2 ASSUME_TAC ASSUME_TAC))) THEN
  SUBGOAL_THEN
   `holds D E ((0 |-> (lam:A)) w0) (stabachieves_form fvb fva iy ivb iva 0)`
   ASSUME_TAC THENL
   [USE_THEN "achP" (MP_TAC o SPEC `lam:A`) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN FIRST_ASSUM ACCEPT_TAC;
    ALL_TAC] THEN
  MP_TAC(ISPECL
    [`D:A->bool`; `E:A->A->bool`; `stabachieves_form fvb fva iy ivb iva 0`;
     `w0:num->A`; `lam:A`] EORDINAL_LEAST) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `alpha:A` STRIP_ASSUME_TAC) THEN
  EXISTS_TAC `alpha:A` THEN ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
   [USE_THEN "achP" (MP_TAC o SPEC `alpha:A`) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[GSYM th]) THEN ASM_REWRITE_TAC[];
    X_GEN_TAC `c:A` THEN STRIP_TAC THEN
    SUBGOAL_THEN `eordinal D E (c:A)` ASSUME_TAC THENL
     [ASM_MESON_TAC[EORDINAL_MEMBER]; ALL_TAC] THEN
    USE_THEN "achP" (MP_TAC o SPEC `c:A`) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[GSYM th]) THEN
    FIRST_X_ASSUM(MP_TAC o SPEC `c:A`) THEN ASM_REWRITE_TAC[]]);;

(* ================================================================== *)
(* RF4: LAMS_EXISTS.  ZF_REPLACEMENT over dm=dom(aa) along stabrank_form *)
(* gives LAMS = { lambda_u : u in dm }, an M-set of ordinals, with an   *)
(* achiever alpha in LAMS whose stage W_alpha "achieves all values" of  *)
(* p(u,-) for every u in dm.  Mirrors RHO_IMAGE_EXISTS, but per-u it    *)
(* builds Vss_u (BVAL_VALUESET_EXISTS) and PVAL_u := bvalf(...) (its own *)
(* totality via BVALF_SPEC) to feed STABRANK_EXISTS; functionality via  *)
(* STABRANK_HOLDS_BRIDGE + STABRANK_UNIQUE.                             *)
(* ================================================================== *)

let LAMS_EXISTS = prove
 (`!D (E:A->A->bool) B leq vbase p fp fvb fva iy ivb iva xs r_val r w0 dm.
      model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
      valuation D vbase /\ valuation D w0 /\
      w0 2 = B /\ w0 3 = leq /\ (!i. w0 (32 + i) = vbase i) /\
      (!i. bname D E B (vbase i)) /\
      ~(r_val = 0) /\ ~(r_val = 2) /\ ~(r_val = 3) /\ ~(r_val = 4) /\
      ~(r_val = 11) /\ ~(r_val = 12) /\
      ~(r = 2) /\ ~(r = 3) /\ ~(r = 4) /\ ~(r = 11) /\ ~(r = 12) /\
        ~(r = r_val) /\
      ~(32 + iy = 11) /\ ~(32 + iy = r_val) /\ ~(32 + iy = r) /\
      r_val < 32 /\ r < 32 /\
      ~(ivb = 2) /\ ~(ivb = 3) /\ ~(ivb = 11) /\ ~(ivb = 12) /\
      ~(ivb = 32 + iy) /\ ivb < 32 /\
      ~(iva = 2) /\ ~(iva = 3) /\ ~(iva = 11) /\ ~(iva = 12) /\
      ~(iva = 32 + iy) /\ ~(iva = ivb) /\ iva < 32 /\
      ~(11 = 32 + iy) /\ ~(xs = iy) /\
      (!v. valuation D v
           ==> (holds D E v fp <=>
                bval D E (v 2) (v 3) (\i. v (32 + i)) p (v r_val))) /\
      (!DD (EE:A->A->bool) w. model DD EE ZF_AX /\ valuation DD w /\ 3 < 32
           ==> (holds DD EE w fvb <=>
                bval DD EE (w 2) (w 3) (\i. w (32 + i)) p (w ivb))) /\
      (!DD (EE:A->A->bool) w. model DD EE ZF_AX /\ valuation DD w /\ 3 < 32
           ==> (holds DD EE w fva <=>
                bval DD EE (w 2) (w 3) (\i. w (32 + i)) p (w iva))) /\
      dm IN D /\
      (!u. u IN D /\ E u dm ==> bname D E B u)
      ==> ?A. A IN D /\
              (!alpha. alpha IN D /\ E alpha A ==> eordinal D E alpha) /\
              (!u. u IN D /\ E u dm
                   ==> ?alpha. alpha IN D /\ E alpha A /\
                               (?dd. dd IN D /\ ebnstage D E B alpha dd /\
                                     (!tt. tt IN D /\ bname D E B tt
                                           ==> ?s. s IN D /\ E s dd /\
                                                   bvalf D E B leq
                                                     ((iy |-> s)
                                                ((xs |-> u) vbase)) p =
                                                   bvalf D E B leq
                                                     ((iy |-> tt)
                                                ((xs |-> u) vbase)) p)))`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `~(32 + xs = r)` ASSUME_TAC THENL
   [UNDISCH_TAC `r < 32` THEN ARITH_TAC; ALL_TAC] THEN
  (* ---------------- tk: per-u valuation/slot/PVAL toolkit ---------------- *)
  SUBGOAL_THEN
   `!u:A. u IN D /\ E u dm
      ==> valuation D ((xs |-> u) vbase) /\
          valuation D (((32 + xs) |-> u) w0) /\
          (!i. bname D E B (((xs |-> u) vbase) i)) /\
          (((32 + xs) |-> u) w0) 2 = B /\
          (((32 + xs) |-> u) w0) 3 = leq /\
          (!i. (((32 + xs) |-> u) w0) (32 + i) = ((xs |-> u) vbase) i) /\
          (!t. t IN D /\ bname D E B t
               ==> bvalf D E B leq ((iy |-> t) ((xs |-> u) vbase)) p IN D /\
                   bval D E B leq ((iy |-> t) ((xs |-> u) vbase)) p
                        (bvalf D E B leq ((iy |-> t) ((xs |-> u) vbase)) p))`
   (LABEL_TAC "tk") THENL
   [X_GEN_TAC `u:A` THEN STRIP_TAC THEN
    SUBGOAL_THEN `bname D E B (u:A)` ASSUME_TAC THENL
     [FIRST_X_ASSUM MATCH_MP_TAC THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN `valuation D ((xs |-> (u:A)) (vbase:num->A))` ASSUME_TAC THENL
     [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN `valuation D (((32 + xs) |-> (u:A)) w0)` ASSUME_TAC THENL
     [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN `!i. bname D E B (((xs |-> (u:A)) (vbase:num->A)) i)`
     (LABEL_TAC "bnvu") THENL
     [GEN_TAC THEN ASM_CASES_TAC `i:num = xs` THENL
       [ASM_REWRITE_TAC[VALMOD_BASIC];
        SUBGOAL_THEN `((xs |-> (u:A)) (vbase:num->A)) i = vbase i`
         (fun th -> REWRITE_TAC[th]) THENL
         [MATCH_MP_TAC VALMOD_OTHER THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
        ASM_REWRITE_TAC[]];
      ALL_TAC] THEN
    ASM_REWRITE_TAC[] THEN REPEAT CONJ_TAC THENL
     [ASM_SIMP_TAC[VALMOD_OTHER; ARITH_RULE `~((2:num) = 32 + xs)`];
      ASM_SIMP_TAC[VALMOD_OTHER; ARITH_RULE `~((3:num) = 32 + xs)`];
      GEN_TAC THEN ASM_CASES_TAC `i:num = xs` THENL
       [ASM_REWRITE_TAC[VALMOD_BASIC];
        SUBGOAL_THEN `~(32 + i = 32 + xs)` ASSUME_TAC THENL
         [UNDISCH_TAC `~(i:num = xs)` THEN ARITH_TAC; ALL_TAC] THEN
        ASM_SIMP_TAC[VALMOD_OTHER] THEN ASM_REWRITE_TAC[]];
      X_GEN_TAC `t:A` THEN STRIP_TAC THEN
      MATCH_MP_TAC(ISPECL
        [`p:form`; `D:A->bool`; `E:A->A->bool`; `B:A`; `leq:A`;
         `(iy |-> (t:A)) ((xs |-> (u:A)) (vbase:num->A))`] BVALF_SPEC) THEN
      ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
       [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[];
        GEN_TAC THEN ASM_CASES_TAC `i:num = iy` THENL
         [ASM_REWRITE_TAC[VALMOD_BASIC];
          SUBGOAL_THEN
           `((iy |-> (t:A)) ((xs |-> (u:A)) (vbase:num->A))) i =
            ((xs |-> (u:A)) (vbase:num->A)) i`
           (fun th -> REWRITE_TAC[th]) THENL
           [MATCH_MP_TAC VALMOD_OTHER THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
          ASM_REWRITE_TAC[]]]];
    ALL_TAC] THEN
  (* ---------------- brdg: per-u STABRANK_HOLDS_BRIDGE ---------------- *)
  SUBGOAL_THEN
   `!u alpha:A. u IN D /\ E u dm /\ alpha IN D
      ==> (holds D E ((r |-> alpha) (((32 + xs) |-> u) w0))
             (stabrank_form fvb fva iy ivb iva r) <=>
           eordinal D E alpha /\
           (?dd. dd IN D /\ ebnstage D E B alpha dd /\
                 (!tt. tt IN D /\ bname D E B tt
                       ==> ?s. s IN D /\ E s dd /\
                               bvalf D E B leq
                                 ((iy |-> s) ((xs |-> u) vbase)) p =
                               bvalf D E B leq
                                 ((iy |-> tt) ((xs |-> u) vbase)) p)) /\
           (!c. c IN D /\ E c alpha
                ==> ~(?dd. dd IN D /\ ebnstage D E B c dd /\
                           (!tt. tt IN D /\ bname D E B tt
                                 ==> ?s. s IN D /\ E s dd /\
                                         bvalf D E B leq
                                           ((iy |-> s) ((xs |-> u) vbase)) p =
                                         bvalf D E B leq
                                           ((iy |-> tt)
                                            ((xs |-> u) vbase)) p))))`
   (LABEL_TAC "brdg") THENL
   [MAP_EVERY X_GEN_TAC [`u:A`; `alpha:A`] THEN STRIP_TAC THEN
    USE_THEN "tk" (fun th -> STRIP_ASSUME_TAC(MATCH_MP th
      (CONJ (ASSUME `(u:A) IN D`)
       (ASSUME `(E:A->A->bool) (u:A) (dm:A)`)))) THEN
    MP_TAC(BETA_RULE(ISPECL
      [`D:A->bool`; `E:A->A->bool`; `B:A`; `leq:A`;
       `(xs |-> (u:A)) (vbase:num->A)`; `p:form`; `fvb:form`; `fva:form`;
       `iy:num`; `ivb:num`; `iva:num`; `r:num`; `((32 + xs) |-> (u:A)) w0`;
       `alpha:A`;
       `\t:A. bvalf D E B leq ((iy |-> t) ((xs |-> (u:A)) (vbase:num->A))) p`]
      STABRANK_HOLDS_BRIDGE)) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[] THEN REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
      DISCH_THEN(fun th -> REWRITE_TAC[th])];
    ALL_TAC] THEN
  (* ---------------- perU: per-u least stabilizing rank exists *)
  (* ---------------- *)
  SUBGOAL_THEN
   `!u:A. u IN D /\ E u dm
      ==> ?alpha. alpha IN D /\ eordinal D E alpha /\
                  (?dd. dd IN D /\ ebnstage D E B alpha dd /\
                        (!tt. tt IN D /\ bname D E B tt
                              ==> ?s. s IN D /\ E s dd /\
                                      bvalf D E B leq
                                        ((iy |-> s) ((xs |-> u) vbase)) p =
                                      bvalf D E B leq
                                        ((iy |-> tt) ((xs |-> u) vbase)) p)) /\
                  (!c. c IN D /\ E c alpha
                       ==> ~(?dd. dd IN D /\ ebnstage D E B c dd /\
                                  (!tt. tt IN D /\ bname D E B tt
                                        ==> ?s. s IN D /\ E s dd /\
                                                bvalf D E B leq
                                                  ((iy |-> s)
                                                ((xs |-> u) vbase)) p =
                                                bvalf D E B leq
                                                  ((iy |-> tt)
                                                ((xs |-> u) vbase)) p)))`
   (LABEL_TAC "perU") THENL
   [X_GEN_TAC `u:A` THEN STRIP_TAC THEN
    USE_THEN "tk" (fun th -> STRIP_ASSUME_TAC(MATCH_MP th
      (CONJ (ASSUME `(u:A) IN D`)
       (ASSUME `(E:A->A->bool) (u:A) (dm:A)`)))) THEN
    MP_TAC(ISPECL
      [`p:form`; `iy:num`; `D:A->bool`; `E:A->A->bool`; `B:A`; `leq:A`;
       `(xs |-> (u:A)) (vbase:num->A)`] BVAL_VALUESET_EXISTS) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(X_CHOOSE_THEN `Vss:A` STRIP_ASSUME_TAC) THEN
    MP_TAC(BETA_RULE(ISPECL
      [`D:A->bool`; `E:A->A->bool`; `B:A`; `leq:A`;
       `(xs |-> (u:A)) (vbase:num->A)`; `p:form`; `fp:form`;
       `fvb:form`; `fva:form`;
       `iy:num`; `ivb:num`; `iva:num`; `r_val:num`; `r:num`;
       `((32 + xs) |-> (u:A)) w0`; `Vss:A`;
       `\t:A. bvalf D E B leq ((iy |-> t) ((xs |-> (u:A)) (vbase:num->A))) p`]
      STABRANK_EXISTS)) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[] THEN REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
      DISCH_THEN(fun th -> ACCEPT_TAC th)];
    ALL_TAC] THEN
  (* ---------------- apply ZF_REPLACEMENT along stabrank_form *)
  (* ---------------- *)
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`] ZF_REPLACEMENT) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(MP_TAC o SPECL
    [`stabrank_form fvb fva iy ivb iva r`; `32 + xs`; `r:num`; `w0:num->A`;
     `dm:A`]) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[] THEN
    (* functionality: each u in dm has a unique achieving rank *)
    X_GEN_TAC `u:A` THEN STRIP_TAC THEN
    USE_THEN "perU" (fun th -> MP_TAC(MATCH_MP th
      (CONJ (ASSUME `(u:A) IN D`)
       (ASSUME `(E:A->A->bool) (u:A) (dm:A)`)))) THEN
    DISCH_THEN(X_CHOOSE_THEN `alpha:A`
               (REPEAT_TCL CONJUNCTS_THEN ASSUME_TAC)) THEN
    EXISTS_TAC `alpha:A` THEN CONJ_TAC THENL
    [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    X_GEN_TAC `w':A` THEN STRIP_TAC THEN
    USE_THEN "brdg" (fun th -> MP_TAC(MATCH_MP th
      (end_itlist CONJ
       [ASSUME `(u:A) IN D`; ASSUME `(E:A->A->bool) (u:A) (dm:A)`;
        ASSUME `(w':A) IN D`]))) THEN
    DISCH_THEN(fun bridge ->
      FIRST_X_ASSUM(fun h -> REPEAT_TCL CONJUNCTS_THEN ASSUME_TAC
                    (EQ_MP bridge h))) THEN
    MATCH_MP_TAC(ISPECL
      [`D:A->bool`; `E:A->A->bool`; `B:A`;
       `\t:A. bvalf D E B leq ((iy |-> t) ((xs |-> (u:A)) (vbase:num->A))) p`;
       `w':A`; `alpha:A`] STABRANK_UNIQUE) THEN
    ASM_REWRITE_TAC[] THEN BETA_TAC THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `Aset:A`
             (CONJUNCTS_THEN2 ASSUME_TAC (LABEL_TAC "Ach"))) THEN
  EXISTS_TAC `Aset:A` THEN ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
   [(* ---- A is a set of ordinals ---- *)
    X_GEN_TAC `alpha:A` THEN STRIP_TAC THEN
    USE_THEN "Ach" (MP_TAC o SPEC `alpha:A`) THEN
    ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN(fun th ->
      FIRST_ASSUM(fun h -> X_CHOOSE_THEN `u:A` STRIP_ASSUME_TAC
                  (EQ_MP th h))) THEN
    USE_THEN "brdg" (fun th -> MP_TAC(MATCH_MP th
      (end_itlist CONJ
       [ASSUME `(u:A) IN D`; ASSUME `(E:A->A->bool) (u:A) (dm:A)`;
        ASSUME `(alpha:A) IN D`]))) THEN
    DISCH_THEN(fun bridge ->
      FIRST_X_ASSUM(fun h -> REPEAT_TCL CONJUNCTS_THEN ASSUME_TAC
                    (EQ_MP bridge h))) THEN
    FIRST_ASSUM ACCEPT_TAC;
    (* ---- every u in dm has an achiever rank in A ---- *)
    X_GEN_TAC `u:A` THEN STRIP_TAC THEN
    USE_THEN "perU" (fun th -> MP_TAC(MATCH_MP th
      (CONJ (ASSUME `(u:A) IN D`)
       (ASSUME `(E:A->A->bool) (u:A) (dm:A)`)))) THEN
    DISCH_THEN(X_CHOOSE_THEN `alpha:A`
               (REPEAT_TCL CONJUNCTS_THEN ASSUME_TAC)) THEN
    EXISTS_TAC `alpha:A` THEN REPEAT CONJ_TAC THENL
     [FIRST_ASSUM ACCEPT_TAC;
      (* alpha IN A via the image characterization *)
      USE_THEN "Ach" (MP_TAC o SPEC `alpha:A`) THEN
      ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
      EXISTS_TAC `u:A` THEN REPEAT CONJ_TAC THENL
       [FIRST_ASSUM ACCEPT_TAC;
        FIRST_ASSUM ACCEPT_TAC;
        USE_THEN "brdg" (fun th -> MP_TAC(MATCH_MP th
          (end_itlist CONJ
           [ASSUME `(u:A) IN D`; ASSUME `(E:A->A->bool) (u:A) (dm:A)`;
            ASSUME `(alpha:A) IN D`]))) THEN
        DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
        REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC];
      (* the achiever dd *)
      FIRST_ASSUM ACCEPT_TAC]]);;

(* ================================================================== *)
(* RF5a: UNIF_STAGE.  From LAMS_EXISTS's output (A = set of stabilizing *)
(* ranks, with a per-u achiever alpha_u in A and its stage W_{alpha_u} *)
(* achieving every value vf u tt), take lam = UNION A (an ordinal) and   *)
(* ddstar = W_lam (EBNSTAGE_EXISTS).  Each alpha_u SUBSET lam           *)
(* (EUNION_MEM), so W_{alpha_u} SUBSET ddstar (EBNSTAGE_MONO/UNIQUE),   *)
(* hence the achiever s lands in the SINGLE stage ddstar for every u.   *)
(* Abstract in vf:A->A->A (vf u t = the forcing value bvalf(...)).        *)
(* Mirrors STABILIZE_LAMBDA but dom-indexed (per-u achiever).           *)
(* ================================================================== *)

let UNIF_STAGE = prove
 (`!D (E:A->A->bool) B A dm (vf:A->A->A).
      model D E ZF_AX /\ B IN D /\ A IN D /\ dm IN D /\
      (!alpha. alpha IN D /\ E alpha A ==> eordinal D E alpha) /\
      (!u. u IN D /\ E u dm
           ==> ?alpha. alpha IN D /\ E alpha A /\
                       (?dd. dd IN D /\ ebnstage D E B alpha dd /\
                             (!tt. tt IN D /\ bname D E B tt
                                   ==> ?s. s IN D /\ E s dd /\
                                     vf u s = vf u tt)))
      ==> ?lam ddstar.
              eordinal D E lam /\ lam IN D /\
              ddstar IN D /\ ebnstage D E B lam ddstar /\
              (!u. u IN D /\ E u dm
                   ==> !tt. tt IN D /\ bname D E B tt
                            ==> ?s. s IN D /\ E s ddstar /\ vf u s = vf u tt)`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "zf BD AD dmD Aord Aach" THEN
  (* lam = UNION A *)
  MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `A:A`] EUNION_EXISTS) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `lam:A` (LABEL_TAC "un")) THEN
  SUBGOAL_THEN `(lam:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[EUNION_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `eordinal D (E:A->A->bool) lam` ASSUME_TAC THENL
   [MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `A:A`; `lam:A`]
      EORDINAL_EUNION) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC];
    ALL_TAC] THEN
  (* ddstar = W_lam *)
  MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `B:A`; `lam:A`]
         EBNSTAGE_EXISTS) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `ddstar:A` (LABEL_TAC "ddstar")) THEN
  MAP_EVERY EXISTS_TAC [`lam:A`; `ddstar:A`] THEN
  ASM_REWRITE_TAC[] THEN
  (* the uniform achiever property *)
  X_GEN_TAC `u:A` THEN STRIP_TAC THEN X_GEN_TAC `tt:A` THEN STRIP_TAC THEN
  USE_THEN "Aach" (MP_TAC o SPEC `u:A`) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  INTRO_TAC "@alpha. alin alA @dd. ddin ddstg ddach" THEN
  (* choose the achiever s in dd for this tt *)
  USE_THEN "ddach" (MP_TAC o SPEC `tt:A`) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `s:A` STRIP_ASSUME_TAC) THEN
  EXISTS_TAC `s:A` THEN ASM_REWRITE_TAC[] THEN
  (* remaining goal: E s ddstar.  W_alpha SUBSET W_lam = ddstar. *)
  SUBGOAL_THEN `eordinal D (E:A->A->bool) alpha` ASSUME_TAC THENL
   [USE_THEN "Aord" MATCH_MP_TAC THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `esubset D (E:A->A->bool) alpha lam` ASSUME_TAC THENL
   [REWRITE_TAC[esubset] THEN X_GEN_TAC `w:A` THEN STRIP_TAC THEN
    MP_TAC(ISPECL
           [`D:A->bool`; `E:A->A->bool`; `A:A`; `lam:A`; `alpha:A`; `w:A`]
           EUNION_MEM) THEN
    ASM_REWRITE_TAC[] THEN DISCH_THEN MATCH_ACCEPT_TAC;
    ALL_TAC] THEN
  MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `alpha:A`; `lam:A`]
    EORDINAL_SUBSET_MEMBER) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  STRIP_TAC THENL
   [(* E alpha lam : W_alpha SUBSET W_lam = ddstar via EBNSTAGE_MONO *)
    MP_TAC(ISPECL
      [`D:A->bool`; `E:A->A->bool`; `B:A`; `lam:A`; `alpha:A`; `ddstar:A`;
       `dd:A`; `s:A`]
      EBNSTAGE_MONO) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC];
    (* alpha = lam : W_alpha = W_lam = ddstar via EBNSTAGE_UNIQUE *)
    FIRST_X_ASSUM SUBST_ALL_TAC THEN
    SUBGOAL_THEN `(dd:A) = ddstar` ASSUME_TAC THENL
     [MP_TAC(ISPECL
        [`D:A->bool`; `E:A->A->bool`; `B:A`; `lam:A`; `dd:A`; `ddstar:A`]
        EBNSTAGE_UNIQUE) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC];
      ALL_TAC] THEN
    ASM_MESON_TAC[]]);;

(* ================================================================== *)
(* RF5b: PERU_SUP.  For a single dom-member u with the uniform-stage    *)
(* achiever property (every value bvalf((y|->tt)(x|->u)v0)p is realized *)
(* by some s in the FIXED stage dd = ddstar), build SS_u = S_dd at      *)
(* (x|->u)v0 (BVAL_REPLIMG_EXISTS) and g_u = sup SS_u (ECBA_SUP), and    *)
(* show every witness value ptt = [[p(u,tt)]] <= g_u: the achiever s    *)
(* gives [[p(u,s)]] = [[p(u,tt)]] with [[p(u,s)]] in SS_u, so <= g_u.    *)
(* This (SS,g,ptt<=g) triple is exactly what EBV_PERWITNESS_FULL wants.  *)
(* Mirrors STABILIZE_SUP tail but keyed to the prescribed dd.            *)
(* ================================================================== *)

let PERU_SUP = prove
 (`!D (E:A->A->bool) B leq v0 p x y u dd.
      model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
      valuation D v0 /\ (!i. bname D E B (v0 i)) /\
      ~(x = y) /\
      u IN D /\ bname D E B u /\
      dd IN D /\ (!s. s IN D /\ E s dd ==> bname D E B s) /\
      (!tt. tt IN D /\ bname D E B tt
            ==> ?s. s IN D /\ E s dd /\
                    bvalf D E B leq ((y |-> s) ((x |-> u) v0)) p =
                    bvalf D E B leq ((y |-> tt) ((x |-> u) v0)) p)
      ==> ?SS g. SS IN D /\ esubset D E SS B /\
        elub D E B leq SS g /\ g IN D /\
                 (!w. w IN D
                      ==> (E w SS <=>
                           ?s. s IN D /\ E s dd /\
                               bval D E B leq
                                 ((y |-> s) ((x |-> u) v0)) p w)) /\
                 (!tt. tt IN D /\ bname D E B tt
                       ==> erel D E leq
                             (bvalf D E B leq
                              ((y |-> tt) ((x |-> u) v0)) p) g)`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "zf cba BD leqD valv0 h xney uD bnu ddD h2 ach" THEN
  (* valuation (x|->u)v0 + all-bname slots *)
  SUBGOAL_THEN
   `valuation D ((x |-> u) (v0:num->A)) /\
    (!i. bname D E B (((x |-> u) (v0:num->A)) i))`
  STRIP_ASSUME_TAC THENL
   [CONJ_TAC THENL
     [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[];
      MATCH_MP_TAC BNAMEVAL_VALMOD THEN ASM_REWRITE_TAC[]]; ALL_TAC] THEN
  (* SS = S_dd via BVAL_REPLIMG_EXISTS *)
  MP_TAC(ISPECL
    [`p:form`; `y:num`; `D:A->bool`; `E:A->A->bool`; `B:A`; `leq:A`;
     `(x |-> u) (v0:num->A)`; `dd:A`] BVAL_REPLIMG_EXISTS) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `SS:A`
    (CONJUNCTS_THEN2 (LABEL_TAC "ssin")
     (CONJUNCTS_THEN2 (LABEL_TAC "sssub") (LABEL_TAC "ssmem")))) THEN
  (* g = elub SS *)
  MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `B:A`; `leq:A`; `SS:A`]
         ECBA_SUP) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `g:A` (LABEL_TAC "glub")) THEN
  SUBGOAL_THEN `(g:A) IN D` (LABEL_TAC "gin") THENL
   [ASM_MESON_TAC[ELUB_IN]; ALL_TAC] THEN
  MAP_EVERY EXISTS_TAC [`SS:A`; `g:A`] THEN
  ASM_REWRITE_TAC[] THEN
  (* remaining goal: !tt bname. [[p(u,tt)]] <= g *)
  X_GEN_TAC `tt:A` THEN STRIP_TAC THEN
  USE_THEN "ach" (MP_TAC o SPEC `tt:A`) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `s:A`
    (CONJUNCTS_THEN2 (LABEL_TAC "sin")
     (CONJUNCTS_THEN2 (LABEL_TAC "sdd") (LABEL_TAC "aeq")))) THEN
  SUBGOAL_THEN `bname D (E:A->A->bool) B s` ASSUME_TAC THENL
   [FIRST_X_ASSUM MATCH_MP_TAC THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN
   `valuation D ((y |-> s) ((x |-> u) (v0:num->A))) /\
    (!i. bname D E B (((y |-> s) ((x |-> u) (v0:num->A))) i))`
  STRIP_ASSUME_TAC THENL
   [CONJ_TAC THENL
     [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[];
      MATCH_MP_TAC BNAMEVAL_VALMOD THEN ASM_REWRITE_TAC[]]; ALL_TAC] THEN
  (* bvalf((y|->s)(x|->u)v0) p IN D + a bval-witness of itself *)
  MP_TAC(ISPECL [`p:form`; `D:A->bool`; `E:A->A->bool`; `B:A`; `leq:A`;
    `(y |-> s) ((x |-> u) (v0:num->A))`] BVALF_SPEC) THEN
  ASM_REWRITE_TAC[] THEN STRIP_TAC THEN
  (* E [[p(u,s)]] SS via the SS characterization, witness s *)
  SUBGOAL_THEN
   `(E:A->A->bool) (bvalf D E B leq ((y |-> s) ((x |-> u) v0)) p) SS`
  ASSUME_TAC THENL
   [USE_THEN "ssmem"
      (MP_TAC o SPEC
       `bvalf D (E:A->A->bool) B leq ((y |-> s) ((x |-> u) v0)) p`) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    EXISTS_TAC `s:A` THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* goal: erel leq [[p(u,tt)]] g ; rewrite [[p(u,tt)]] = [[p(u,s)]] (GSYM *)
  (* aeq) *)
  USE_THEN "aeq" (SUBST1_TAC o SYM) THEN
  (* ELUB_UB: [[p(u,s)]] <= g *)
  MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `B:A`; `leq:A`; `SS:A`; `g:A`;
    `bvalf D (E:A->A->bool) B leq ((y |-> s) ((x |-> u) v0)) p`] ELUB_UB) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC]);;

(* ================================================================== *)
(* RF5c: EBV_REPL_CORE.  The COLLECTION-reduction crux for            *)
(* [[replacement_ax]] = TT.  Given the uniform stage ddstar (every     *)
(* dom-member u and bname t2 has a stage-witness s with equal forcing  *)
(* value), the class name cn (= onebee on ddstar), K = [[tt IN cn]],   *)
(* and the collection meet mm of the functional premise with           *)
(* [[??- x a p]] at (y|->tt)v, conclude mm <= K.  Route F: residuation *)
(* (EBIMP_LE_IMP / EBIMP_MEET_LE) + EBVALF_EXMEM_LE reduce to a         *)
(* PER-WITNESS bound; EBV_MEMRED lifts dom-member -> arbitrary bname;   *)
(* PERU_SUP supplies (SS,g); EBV_PERWITNESS_FULL is the per-witness     *)
(* consumer.                                                            *)
(* ================================================================== *)

let EBV_REPL_CORE =
  let repl_prem_tm =
    `bvalf (D:A->bool) (E:A->A->bool) (B:A) (leq:A) (v:num->A)
       (!!- x a (?? z (!! y (p --> Eq y z))))` in
  let r_tm =
    `bvalf (D:A->bool) (E:A->A->bool) (B:A) (leq:A) (vm:num->A)
       (??- x a p)` in
  prove
 (`!D (E:A->A->bool) B leq v x y z a p tt dm ddstar onebee cn K mm.
    model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
    valuation D v /\ (!i. bname D E B (v i)) /\
    ~(x = a) /\ ~(x = y) /\ ~(y = z) /\ ~(a = y) /\ ~(z IN FV p) /\
    tt IN D /\ bname D E B tt /\
    dm IN D /\ (!u. u IN D ==> (E u dm <=> eindom D E (v a) u)) /\
    ddstar IN D /\ (!s. s IN D /\ E s ddstar ==> bname D E B s) /\
    (!u. u IN D /\ E u dm
         ==> !t2. t2 IN D /\ bname D E B t2
                  ==> ?s. s IN D /\ E s ddstar /\
                          bvalf D E B leq ((y |-> s) ((x |-> u) v)) p =
                          bvalf D E B leq ((y |-> t2) ((x |-> u) v)) p) /\
    onebee IN D /\ E onebee B /\ etop D E B leq onebee /\
    cn IN D /\ eisfun D E cn /\
    (!s. s IN D /\ E s ddstar ==> eapply D E cn s onebee) /\
    K IN D /\ E K B /\ ebv_in D E B leq tt cn K /\
    emeet D E B leq
      (bvalf D E B leq v (!!- x a (?? z (!! y (p --> Eq y z)))))
      (bvalf D E B leq ((y |-> tt) v) (??- x a p)) mm
    ==> erel D E leq mm K`,
  (* ===== setup ===== *)
  REPEAT GEN_TAC THEN
  ABBREV_TAC `vm = (y |-> tt) (v:num->A)` THEN
  ABBREV_TAC `aa = (v:num->A) a` THEN
  INTRO_TAC "zf cba BD leqD val h xnea xney ynez aney znfv ttD bntt dmD \
             dmch ddstarD ddbn ach onebeeD onebeeB toponebee cnD funcn \
             cnap KD KB ebvin meet" THEN
  SUBGOAL_THEN `ebalg D (E:A->A->bool) B leq` ASSUME_TAC THENL
   [ASM_MESON_TAC[ECBA_IMP_BALG]; ALL_TAC] THEN
  SUBGOAL_THEN `eporder D (E:A->A->bool) B leq` ASSUME_TAC THENL
   [ASM_MESON_TAC[ECBA_IMP_PORDER]; ALL_TAC] THEN
  SUBGOAL_THEN `bname D (E:A->A->bool) B aa /\ aa IN D` STRIP_ASSUME_TAC THENL
   [EXPAND_TAC "aa" THEN ASM_MESON_TAC[valuation]; ALL_TAC] THEN
  SUBGOAL_THEN `valuation D vm /\ (!i. bname D (E:A->A->bool) B (vm i))`
    STRIP_ASSUME_TAC THENL
   [EXPAND_TAC "vm" THEN CONJ_TAC THENL
     [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[];
      MATCH_MP_TAC BNAMEVAL_VALMOD THEN ASM_REWRITE_TAC[]]; ALL_TAC] THEN
  SUBGOAL_THEN `(vm:num->A) a = aa` (LABEL_TAC "vma") THENL
   [EXPAND_TAC "vm" THEN EXPAND_TAC "aa" THEN ASM_SIMP_TAC[VALMOD_OTHER];
    ALL_TAC] THEN
  SUBGOAL_THEN `~(a:num = x)` (LABEL_TAC "axne") THENL
   [ASM_MESON_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN
    `bvalf (D:A->bool) (E:A->A->bool) (B:A) (leq:A) (v:num->A)
     (!!- x a (?? z (!! y (p --> Eq y z)))) IN D`
    (LABEL_TAC "premD") THENL
   [MP_TAC(ISPECL[`!!- x a (?? z (!! y (p --> Eq y z)))`;`D:A->bool`;
                  `E:A->A->bool`;`B:A`;`leq:A`;`v:num->A`] BVALF_SPEC) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN(ACCEPT_TAC o CONJUNCT1)];
    ALL_TAC] THEN
  SUBGOAL_THEN
    `(E:A->A->bool)
     (bvalf (D:A->bool) E (B:A) (leq:A) (v:num->A)
      (!!- x a (?? z (!! y (p --> Eq y z))))) B`
    (LABEL_TAC "premB") THENL
   [MATCH_MP_TAC BVALF_IN_B THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN
    `bvalf (D:A->bool) (E:A->A->bool) (B:A) (leq:A) (vm:num->A)
     (??- x a p) IN D`
    (LABEL_TAC "RD") THENL
   [MP_TAC(ISPECL[`??- x a p`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
                  `vm:num->A`] BVALF_SPEC) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN(ACCEPT_TAC o CONJUNCT1)];
    ALL_TAC] THEN
  SUBGOAL_THEN
    `(E:A->A->bool)
     (bvalf (D:A->bool) E (B:A) (leq:A) (vm:num->A) (??- x a p)) B`
    (LABEL_TAC "RB") THENL
   [MATCH_MP_TAC BVALF_IN_B THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* ===== memred SUBGOAL ===== *)
  SUBGOAL_THEN
   `!ss m0. ss IN D /\ bname (D:A->bool) (E:A->A->bool) (B:A) ss /\
      m0 IN D /\ E m0 (B:A) /\
      erel D E leq m0
        (bvalf D E B (leq:A) (v:num->A)
         (!!- x a (?? z (!! y (p --> Eq y z))))) /\
      erel D E leq m0 (bvalf D E B leq ((x |-> ss) (vm:num->A)) (x %% a)) /\
      erel D E leq m0 (bvalf D E B leq ((x |-> ss) vm) p)
      ==> erel D E leq m0 (K:A)`
   (LABEL_TAC "memred") THENL
   [ (* ----- branch 1: prove memred (EBV_MEMRED reduction + dom-member
    proof) ----- *)
    MATCH_MP_TAC EBV_MEMRED THEN ASM_REWRITE_TAC[] THEN
    (* c3bi_a: enter the dom-member witness yy and its data *)
    X_GEN_TAC `yy:A` THEN X_GEN_TAC `qy:A` THEN X_GEN_TAC `m0:A` THEN
    INTRO_TAC "yyD eap m0D m0B hprem hxa hp" THEN
    (* c3bi_b: eind = eindom aa yy *)
    SUBGOAL_THEN `eindom D (E:A->A->bool) aa yy` (LABEL_TAC "eind") THENL
     [MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`aa:A`;`yy:A`;`qy:A`]
             EAPPLY_DVAL) THEN
      ASM_REWRITE_TAC[] THEN
      DISCH_THEN(X_CHOOSE_THEN `q0:A` STRIP_ASSUME_TAC) THEN
      REWRITE_TAC[eindom] THEN EXISTS_TAC `q0:A` THEN ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    (* c3bi_c: bnyy = bname yy *)
    SUBGOAL_THEN `bname D (E:A->A->bool) B yy` (LABEL_TAC "bnyy") THENL
     [MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`aa:A`;`yy:A`]
             UNION_DOM_BNAME) THEN
      ASM_REWRITE_TAC[]; ALL_TAC] THEN
    (* eyydm: E yy dm, via dmch SPEC yy rewritten by eind (targeted, no *)
    (* MESON) *)
    SUBGOAL_THEN `(E:A->A->bool) yy dm` (LABEL_TAC "eyydm") THENL
     [USE_THEN "dmch" (MP_TAC o SPEC `yy:A`) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
      USE_THEN "eind" ACCEPT_TAC;
      ALL_TAC] THEN
    (* helper valuations for (x|->yy)v and (x|->yy)vm *)
    SUBGOAL_THEN
      `valuation D ((x|->yy)(v:num->A)) /\
       (!i. bname D (E:A->A->bool) B (((x|->yy)v) i))` STRIP_ASSUME_TAC THENL
     [CONJ_TAC THENL
      [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[];
       MATCH_MP_TAC BNAMEVAL_VALMOD THEN ASM_REWRITE_TAC[]]; ALL_TAC] THEN
    SUBGOAL_THEN
      `valuation D ((x|->yy)(vm:num->A)) /\
       (!i. bname D (E:A->A->bool) B (((x|->yy)vm) i))` STRIP_ASSUME_TAC THENL
     [CONJ_TAC THENL
      [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[];
       MATCH_MP_TAC BNAMEVAL_VALMOD THEN ASM_REWRITE_TAC[]]; ALL_TAC] THEN
    (* c3bii: PERU_SUP gives SS,g with the stage-sup bound *)
    MP_TAC(ISPECL
           [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`v:num->A`;`p:form`;
            `x:num`;`y:num`;`yy:A`;`ddstar:A`] PERU_SUP) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[] THEN USE_THEN "ach" MATCH_MP_TAC THEN
      ASM_REWRITE_TAC[];
      INTRO_TAC "@SS g. ssin sssub sselub gin sschar glast"] THEN
    (* c3biii: three bridges xaeq, hp3, greq *)
    SUBGOAL_THEN
      `bvalf (D:A->bool) (E:A->A->bool) (B:A) (leq:A) ((x|->yy)(v:num->A))
       (x%%a) = bvalf D E B leq ((x|->yy)(vm:num->A))(x%%a)`
      (LABEL_TAC "xaeq") THENL
      [MATCH_MP_TAC BVALF_FV_CONG THEN ASM_REWRITE_TAC[] THEN
      REWRITE_TAC[FV;IN_INSERT;NOT_IN_EMPTY] THEN REPEAT STRIP_TAC THEN
      EXPAND_TAC "vm" THEN ASM_REWRITE_TAC[VALMOD];
      ALL_TAC] THEN
    SUBGOAL_THEN
      `erel (D:A->bool) (E:A->A->bool) leq m0
       (bvalf D E B leq ((y|->tt)((x|->yy)(v:num->A))) p)`
      (LABEL_TAC "hp3") THENL
      [SUBGOAL_THEN `(y|->tt)((x|->yy)(v:num->A)) = (x|->yy)vm`
       SUBST1_TAC THENL
       [EXPAND_TAC "vm" THEN CONV_TAC SYM_CONV THEN
        MATCH_MP_TAC VALMOD_SWAP THEN ASM_REWRITE_TAC[];
        ASM_REWRITE_TAC[]];
      ALL_TAC] THEN
    SUBGOAL_THEN
      `erel (D:A->bool) (E:A->A->bool) leq
       (bvalf D E B leq ((y|->tt)((x|->yy)(v:num->A))) p) g`
      (LABEL_TAC "greq") THENL
      [USE_THEN "glast" MATCH_MP_TAC THEN ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    (* c3biv: EBV_PERWITNESS_FULL closes the dom-member bound *)
    MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`v:num->A`;
     `x:num`;`y:num`;`z:num`;`a:num`;`p:form`;`yy:A`;`tt:A`;`ddstar:A`;
     `cn:A`;`onebee:A`;`SS:A`;`g:A`;`K:A`;`m0:A`] EBV_PERWITNESS_FULL) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC];
    (* ----- branch 2: main goal (residuation to the per-witness bound) *)
    (* ----- g2a: w0 = [[prem]] ==> K ; Rle = [[R]] <= w0 (per-ss bound, g2b *)
    (* folded in) *)
    MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
      repl_prem_tm; `K:A`] EBIMP_EXISTS) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(X_CHOOSE_THEN `w0:A` (LABEL_TAC "w0def")) THEN
    USE_THEN "w0def" (STRIP_ASSUME_TAC o MATCH_MP EBIMP_IN) THEN
    SUBGOAL_THEN
      `erel (D:A->bool) (E:A->A->bool) leq
       (bvalf D E B leq (vm:num->A) (??- x a p)) w0`
      (LABEL_TAC "Rle") THENL
     [MATCH_MP_TAC EBVALF_EXMEM_LE THEN ASM_REWRITE_TAC[] THEN
      MAP_EVERY X_GEN_TAC [`ss:A`;`msm:A`] THEN STRIP_TAC THEN
      SUBGOAL_THEN `valuation D ((x|->ss) (vm:num->A)) /\
                    (!i. bname (D:A->bool) (E:A->A->bool) (B:A)
                     (((x|->ss) vm) i))`
        STRIP_ASSUME_TAC THENL
       [ASM_MESON_TAC[VALUATION_VALMOD; BNAMEVAL_VALMOD]; ALL_TAC] THEN
      SUBGOAL_THEN `(msm:A) IN D /\ E msm (B:A)` STRIP_ASSUME_TAC THENL
       [ASM_MESON_TAC[EMEET_IN]; ALL_TAC] THEN
      SUBGOAL_THEN
        `bvalf (D:A->bool) (E:A->A->bool) (B:A) (leq:A) ((x|->ss) (vm:num->A))
         (x%%a) IN D /\
         E (bvalf D E B leq ((x|->ss) vm) (x%%a)) B /\
         bvalf D E B leq ((x|->ss) vm) p IN D /\
         E (bvalf D E B leq ((x|->ss) vm) p) B`
        STRIP_ASSUME_TAC THENL
       [REPEAT CONJ_TAC THENL
         [MP_TAC(ISPECL
                 [`x%%a`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
                  `(x|->ss) (vm:num->A)`] BVALF_SPEC) THEN
          ASM_REWRITE_TAC[] THEN STRIP_TAC THEN ASM_REWRITE_TAC[];
          MATCH_MP_TAC BVALF_IN_B THEN ASM_REWRITE_TAC[];
          MP_TAC(ISPECL
                 [`p:form`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
                  `(x|->ss) (vm:num->A)`] BVALF_SPEC) THEN
          ASM_REWRITE_TAC[] THEN STRIP_TAC THEN ASM_REWRITE_TAC[];
          MATCH_MP_TAC BVALF_IN_B THEN ASM_REWRITE_TAC[]];
        ALL_TAC] THEN
      (* g2b: build mp = msm /\ prem, lower-bound facts, memred, *)
      (* EBIMP_LE_IMP *)
      MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
        `msm:A`; repl_prem_tm] EBALG_MEET) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(X_CHOOSE_THEN `mp:A` (LABEL_TAC "mpmeet")) THEN
      SUBGOAL_THEN `(mp:A) IN D /\ E mp (B:A)` STRIP_ASSUME_TAC THENL
       [ASM_MESON_TAC[EMEET_IN]; ALL_TAC] THEN
      SUBGOAL_THEN `erel (D:A->bool) (E:A->A->bool) leq mp msm /\
                    erel D E leq mp
                      (bvalf D E B leq (v:num->A)
                       (!!- x a (?? z (!! y (p --> Eq y z)))))`
        STRIP_ASSUME_TAC THENL
       [ASM_MESON_TAC[EMEET_LE]; ALL_TAC] THEN
      SUBGOAL_THEN
        `erel (D:A->bool) (E:A->A->bool) leq msm
         (bvalf D E B leq ((x|->ss) (vm:num->A)) (x%%a)) /\
         erel D E leq msm (bvalf D E B leq ((x|->ss) vm) p)`
        STRIP_ASSUME_TAC THENL
       [ASM_MESON_TAC[EMEET_LE]; ALL_TAC] THEN
      SUBGOAL_THEN
        `erel (D:A->bool) (E:A->A->bool) leq mp
         (bvalf D E B leq ((x|->ss) (vm:num->A)) (x%%a))`
        ASSUME_TAC THENL
       [MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`mp:A`;`msm:A`;
          `bvalf D E B leq ((x|->ss) (vm:num->A)) (x%%a):A`]
                         EPORDER_TRANS) THEN
        ASM_REWRITE_TAC[]; ALL_TAC] THEN
      SUBGOAL_THEN
        `erel (D:A->bool) (E:A->A->bool) leq mp
         (bvalf D E B leq ((x|->ss) (vm:num->A)) p)`
        ASSUME_TAC THENL
       [MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`mp:A`;`msm:A`;
          `bvalf D E B leq ((x|->ss) (vm:num->A)) p:A`] EPORDER_TRANS) THEN
        ASM_REWRITE_TAC[]; ALL_TAC] THEN
      SUBGOAL_THEN `erel (D:A->bool) (E:A->A->bool) leq mp (K:A)`
        ASSUME_TAC THENL
        [USE_THEN "memred" MATCH_MP_TAC THEN EXISTS_TAC `ss:A` THEN
         ASM_REWRITE_TAC[]; ALL_TAC] THEN
      MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
        `msm:A`; repl_prem_tm; `K:A`;`w0:A`;`mp:A`]
        EBIMP_LE_IMP) THEN
      ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    (* g2c: flip the meet (EMEET_SYM) and residuate (EBIMP_MEET_LE) *)
    SUBGOAL_THEN `emeet (D:A->bool) (E:A->A->bool) B leq
        (bvalf D E B leq (vm:num->A) (??- x a p))
        (bvalf D E B leq (v:num->A) (!!- x a (?? z (!! y (p --> Eq y z))))) mm`
      ASSUME_TAC THENL
     [MATCH_MP_TAC EMEET_SYM THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    MATCH_MP_TAC EBIMP_MEET_LE THEN
    MAP_EVERY EXISTS_TAC [`B:A`; r_tm; repl_prem_tm; `w0:A`] THEN
    ASM_REWRITE_TAC[]]);;

(* ================================================================== *)
(* REPL_STABILIZE.  For a replacement instance p with element-var y     *)
(* and dom-var x over a set dm of B-names, build ONE uniform bounding    *)
(* stage ddstar = W_lam (lam an ordinal) such that for every dom-member  *)
(* u and every bname tt, some s in ddstar realizes the SAME forcing      *)
(* value  [[p]]_{(y|->s)(x|->u)v} = [[p]]_{(y|->tt)(x|->u)v}.            *)
(* AC-free: fp/fvb/fva are the internalised bval formula codes           *)
(* (BVAL_DEFINABLE); LAMS_EXISTS collects a per-u stabilizing rank via    *)
(* ZF_REPLACEMENT; UNIF_STAGE unions them into the single stage.  The     *)
(* ddstar members are B-names (BNAME_STAGE).  Feeds EBV_REPL_CORE.        *)
(* Mirrors STABILIZE_SUP but dom-indexed via LAMS_EXISTS/UNIF.            *)
(* ================================================================== *)

let REPL_STABILIZE = prove
 (`!D (E:A->A->bool) B leq v x y p dm.
      model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
      valuation D v /\ (!i. bname D E B (v i)) /\
      ~(x = y) /\
      dm IN D /\ (!u. u IN D /\ E u dm ==> bname D E B u)
      ==> ?lam ddstar.
              eordinal D E lam /\ lam IN D /\
              ddstar IN D /\ ebnstage D E B lam ddstar /\
              (!s. s IN D /\ E s ddstar ==> bname D E B s) /\
              (!u. u IN D /\ E u dm
                   ==> !tt. tt IN D /\ bname D E B tt
                            ==> ?s. s IN D /\ E s ddstar /\
                                    bvalf D E B leq
                                      ((y |-> s) ((x |-> u) v)) p =
                                    bvalf D E B leq
                                      ((y |-> tt) ((x |-> u) v)) p)`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `!n. (v:num->A) n IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[valuation]; ALL_TAC] THEN
  (* ---- build the three bval formula codes fp/fvb/fva ---- *)
  X_CHOOSE_THEN `fp:form` (LABEL_TAC "fpdef")
    (ISPECL [`p:form`; `5`; `3`] BVAL_DEFINABLE) THEN
  X_CHOOSE_THEN `fvb:form` (LABEL_TAC "fvbdef")
    (ISPECL [`p:form`; `7`; `3`] BVAL_DEFINABLE) THEN
  X_CHOOSE_THEN `fva:form` (LABEL_TAC "fvadef")
    (ISPECL [`p:form`; `8`; `3`] BVAL_DEFINABLE) THEN
  (* ---- w0 = the 32-shifted valuation with B at 2, leq at 3 ---- *)
  ABBREV_TAC `w0 = (2 |-> B) ((3 |-> leq) (\k. (v:num->A) (k - 32)))` THEN
  SUBGOAL_THEN
   `valuation D (w0:num->A) /\ w0 2 = B /\ w0 3 = leq /\
    (!i. w0 (32 + i) = (v:num->A) i)`
   STRIP_ASSUME_TAC THENL
   [EXPAND_TAC "w0" THEN REPEAT CONJ_TAC THENL
     [REPEAT(MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[]) THEN
      REWRITE_TAC[valuation] THEN ASM_REWRITE_TAC[];
      SIMP_TAC[VALMOD_BASIC];
      SIMP_TAC[VALMOD_OTHER; VALMOD_BASIC; ARITH_RULE `~(3 = 2)`];
      GEN_TAC THEN
      SIMP_TAC[VALMOD_OTHER; ARITH_RULE `~(32 + i = 2) /\ ~(32 + i = 3)`] THEN
      AP_TERM_TAC THEN ARITH_TAC];
    ALL_TAC] THEN
  (* ---- fp bridge (fvbdef/fvadef already in LAMS shape) ---- *)
  SUBGOAL_THEN
   `!vv:num->A. valuation D vv
        ==> (holds D E vv fp <=>
             bval D E (vv 2) (vv 3) (\i. vv (32 + i)) p (vv 5))`
   (LABEL_TAC "fpbr") THENL
   [X_GEN_TAC `vv:num->A` THEN DISCH_TAC THEN
    USE_THEN "fpdef" (fun th ->
      MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `vv:num->A`] th)) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[] THEN ARITH_TAC; DISCH_THEN ACCEPT_TAC];
    ALL_TAC] THEN
  (* ---- LAMS_EXISTS: A = set of per-u stabilizing ranks ---- *)
  MP_TAC(ISPECL
    [`D:A->bool`; `E:A->A->bool`; `B:A`; `leq:A`; `v:num->A`; `p:form`;
     `fp:form`; `fvb:form`; `fva:form`; `y:num`; `7`; `8`; `x:num`;
     `5`; `6`; `w0:num->A`; `dm:A`] LAMS_EXISTS) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[] THEN REPEAT CONJ_TAC THEN
    TRY(FIRST_ASSUM ACCEPT_TAC) THEN TRY ARITH_TAC;
    ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `Aset:A`
    (CONJUNCTS_THEN2 (LABEL_TAC "AsetD")
     (CONJUNCTS_THEN2 (LABEL_TAC "Aord") (LABEL_TAC "Aach")))) THEN
  (* ---- UNIF_STAGE: union into single stage ddstar = W_lam ---- *)
  MP_TAC(BETA_RULE(ISPECL
    [`D:A->bool`; `E:A->A->bool`; `B:A`; `Aset:A`; `dm:A`;
     `\(u:A) (t:A). bvalf D E B leq ((y |-> t) ((x |-> u) (v:num->A))) p`]
    UNIF_STAGE)) THEN
  ANTS_TAC THENL
   [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
    ALL_TAC] THEN
  INTRO_TAC "@lam ddstar. lamord lamin ddin ddstage unifach" THEN
  (* ---- ddstar members are B-names ---- *)
  SUBGOAL_THEN `!s:A. s IN D /\ E s ddstar ==> bname D E B s`
    (LABEL_TAC "ddbn") THENL
   [X_GEN_TAC `s:A` THEN STRIP_TAC THEN MATCH_MP_TAC BNAME_STAGE THEN
    MAP_EVERY EXISTS_TAC [`lam:A`; `ddstar:A`] THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  MAP_EVERY EXISTS_TAC [`lam:A`; `ddstar:A`] THEN ASM_REWRITE_TAC[]);;

(* ================================================================== *)
(* BVALF_REPLACEMENT.  The 8th V^B ZFC axiom: [[replacement_ax]] = TT. *)
(* Mirrors BVALF_SEPARATION (peel !!a, residuate the functional         *)
(* premise, witness bb=SEP(cn,??-x a p) with cn=EFULLNAME of the        *)
(* uniform bounding stage ddstar).  Endgame per image-cand tt reduces    *)
(* to EBV_REPL_CORE (mm=meet(PREM,rr) <= K=[[tt IN cn]]).                *)
(* ================================================================== *)

let BVALF_REPLACEMENT =
  let funcf_tm = `!!- x a (?? z (!! y (p --> Eq y z)))` in
  let exb_tm   = `?? b (!! y ((y %% b) <-> ??- x a p))` in
  let collb_tm = `!! y ((y %% b) <-> ??- x a p)` in
  let prem_tm =
    `bvalf (D:A->bool) (E:A->A->bool) (B:A) (leq:A) (v0:num->A)
       (!!- x a (?? z (!! y (p --> Eq y z))))` in
  let rr_tm =
    `bvalf (D:A->bool) (E:A->A->bool) (B:A) (leq:A) ((y |-> tt) (v0:num->A))
       (??- x a p)` in
  let pval_tm =
    `bvalf (D:A->bool) (E:A->A->bool) (B:A) (leq:A) (vv2:num->A) (y %% b)` in
  let qval_tm =
    `bvalf (D:A->bool) (E:A->A->bool) (B:A) (leq:A) (vv2:num->A)
       (??- x a p)` in
  let i1_tm =
    `bvalf (D:A->bool) (E:A->A->bool) (B:A) (leq:A) (vv2:num->A)
       ((y %% b) --> ??- x a p)` in
  let i2_tm =
    `bvalf (D:A->bool) (E:A->A->bool) (B:A) (leq:A) (vv2:num->A)
       ((??- x a p) --> (y %% b))` in
  let and_tm =
    `bvalf (D:A->bool) (E:A->A->bool) (B:A) (leq:A) (vv2:num->A)
       (((y %% b) --> ??- x a p) && ((??- x a p) --> (y %% b)))` in
  let collv1_tm =
    `bvalf (D:A->bool) (E:A->A->bool) (B:A) (leq:A) (v1:num->A)
       (!! y ((y %% b) <-> ??- x a p))` in
  let exbv0_tm =
    `bvalf (D:A->bool) (E:A->A->bool) (B:A) (leq:A) (v0:num->A)
       (?? b (!! y ((y %% b) <-> ??- x a p)))` in
  let erel_tm a b =
    list_mk_comb(`erel (D:A->bool) (E:A->A->bool) (leq:A)`,[a;b])
  and ebimp_tm a b c =
    list_mk_comb(`ebimp (D:A->bool) (E:A->A->bool) (B:A) (leq:A)`,[a;b;c])
  and emeet_tm a b c =
    list_mk_comb(`emeet (D:A->bool) (E:A->A->bool) (B:A) (leq:A)`,[a;b;c])
  and inD_tm t = mk_comb(mk_comb(`(IN):A->(A->bool)->bool`,t),`D:A->bool`) in
  let inDB_tm t = mk_conj(inD_tm t,list_mk_comb(`E:A->A->bool`,[t;`B:A`])) in
  prove
 (`!D (E:A->A->bool) B leq v x y z a b p.
      model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
      valuation D v /\ (!i. bname D E B (v i)) /\
      ~(z IN FV p) /\ ~(a IN FV p) /\ ~(b IN FV p) /\
      ~(x = y) /\ ~(x = z) /\ ~(x = a) /\ ~(x = b) /\
      ~(y = z) /\ ~(y = a) /\ ~(y = b) /\
      ~(z = a) /\ ~(z = b) /\ ~(a = b)
      ==> etop D E B leq (bvalf D E B leq v (replacement_ax x y z a b p))`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `ebalg D (E:A->A->bool) B leq` ASSUME_TAC THENL
   [ASM_MESON_TAC[ECBA_IMP_BALG]; ALL_TAC] THEN
  SUBGOAL_THEN `eporder D (E:A->A->bool) B leq` ASSUME_TAC THENL
   [ASM_MESON_TAC[ECBA_IMP_BALG; EBALG_IMP_PORDER]; ALL_TAC] THEN
  SUBGOAL_THEN `~(a:num = y) /\ ~(b:num = y)` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[]; ALL_TAC] THEN
  REWRITE_TAC[replacement_ax] THEN
  (* ---- peel !!a -> aa ---- *)
  MP_TAC(ISPECL [`a:num`;
    `(!!- x a (?? z (!! y (p --> Eq y z)))) -->
     ?? b (!! y ((y %% b) <-> ??- x a p))`;
    `D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`v:num->A`] BVALF_ALL_TOP) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  X_GEN_TAC `aa:A` THEN STRIP_TAC THEN
  SUBGOAL_THEN `valuation D ((a |-> (aa:A)) (v:num->A)) /\
                (!i. bname D E B (((a |-> (aa:A)) (v:num->A)) i))`
  STRIP_ASSUME_TAC THENL
   [CONJ_TAC THENL
     [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[];
      MATCH_MP_TAC BNAMEVAL_VALMOD THEN ASM_REWRITE_TAC[]]; ALL_TAC] THEN
  ABBREV_TAC `v0 = (a |-> (aa:A)) (v:num->A)` THEN
  SUBGOAL_THEN `(v0:num->A) a = aa` (LABEL_TAC "v0a") THENL
   [EXPAND_TAC "v0" THEN REWRITE_TAC[VALMOD_BASIC]; ALL_TAC] THEN
  (* ---- IMP_TOP : goal becomes  PREM <= [[?? b collb]]_v0 ---- *)
  MP_TAC(ISPECL [funcf_tm; exb_tm;
    `D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`v0:num->A`] BVALF_IMP_TOP) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  (* ---- PREM in D, E PREM B ---- *)
  SUBGOAL_THEN (inDB_tm prem_tm)
    STRIP_ASSUME_TAC THENL
   [CONJ_TAC THENL
     [MP_TAC(ISPECL
             [funcf_tm;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`v0:num->A`]
             BVALF_SPEC) THEN ASM_REWRITE_TAC[] THEN STRIP_TAC THEN
    ASM_REWRITE_TAC[];
    MATCH_MP_TAC BVALF_IN_B THEN ASM_REWRITE_TAC[]]; ALL_TAC] THEN
  (* ---- dm = domain of aa ---- *)
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`aa:A`] EDOMAIN_EXISTS) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `dm:A`
             (STRIP_ASSUME_TAC o REWRITE_RULE[edomain])) THEN
  SUBGOAL_THEN
    `dm IN D /\
     (!u. u IN D ==> (E u dm <=> eindom D (E:A->A->bool) ((v0:num->A) a) u))`
    (LABEL_TAC "dmch") THENL
   [ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `!u:A. u IN D /\ E u dm ==> bname D (E:A->A->bool) B u`
    (LABEL_TAC "dmbn") THENL
   [X_GEN_TAC `u:A` THEN STRIP_TAC THEN
    MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`aa:A`;`u:A`]
      UNION_DOM_BNAME) THEN ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[];
    ALL_TAC] THEN
  (* ---- REPL_STABILIZE : uniform stage ddstar = W_lam ---- *)
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`v0:num->A`;
    `x:num`;`y:num`;`p:form`;`dm:A`] REPL_STABILIZE) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  INTRO_TAC "@lam ddstar. lamord lamin ddin ddstage ddbn achv0" THEN
  (* ---- onebee = top of B ---- *)
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`] EBALG_TOP) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `onebee:A` (LABEL_TAC "onetop")) THEN
  SUBGOAL_THEN `onebee IN D /\ (E:A->A->bool) onebee B` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[ETOP_IN]; ALL_TAC] THEN
  (* ---- cn = EFULLNAME(onebee, ddstar) ---- *)
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`onebee:A`;`ddstar:A`]
    EFULLNAME_EXISTS) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  INTRO_TAC "@cn. cnin cnfun cndom cnap cnmem" THEN
  SUBGOAL_THEN `bname D (E:A->A->bool) B cn` (LABEL_TAC "cnbn") THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`onebee:A`;
      `ddstar:A`;`lam:A`;`ddstar:A`;`cn:A`] EFULLNAME_BNAME) THEN
    ASM_REWRITE_TAC[] THEN MESON_TAC[]; ALL_TAC] THEN
  (* ---- bb = ESEPNAME(cn, ??- x a p) with sep-var y ---- *)
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`v0:num->A`;
    `??- x a p`;`y:num`;`cn:A`] ESEPNAME_EXISTS) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  INTRO_TAC "@bb. bbin bbfun bbdom bbap bbmem" THEN
  SUBGOAL_THEN `bname D (E:A->A->bool) B bb` (LABEL_TAC "bbbn") THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`v0:num->A`;
      `??- x a p`;`y:num`;`cn:A`;`bb:A`] ESEPNAME_BNAME) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* ---- v1 = (b|->bb)v0 ---- *)
  SUBGOAL_THEN `valuation D ((b |-> (bb:A)) (v0:num->A)) /\
                (!i. bname D E B (((b |-> (bb:A)) (v0:num->A)) i))`
  STRIP_ASSUME_TAC THENL
   [CONJ_TAC THENL
     [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[];
      MATCH_MP_TAC BNAMEVAL_VALMOD THEN ASM_REWRITE_TAC[]]; ALL_TAC] THEN
  ABBREV_TAC `v1 = (b |-> (bb:A)) (v0:num->A)` THEN
  (* ---- exub : [[collb]]_v1 <= [[?? b collb]]_v0 ---- *)
  SUBGOAL_THEN (erel_tm collv1_tm exbv0_tm)
    (LABEL_TAC "exub") THENL
   [SUBGOAL_THEN `(v1:num->A) = (b |-> (bb:A)) (v0:num->A)` SUBST1_TAC THENL
     [CONV_TAC SYM_CONV THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    MATCH_MP_TAC(ISPECL [`b:num`;collb_tm;`D:A->bool`;`E:A->A->bool`;`B:A`;
      `leq:A`;`v0:num->A`;`bb:A`] BVALF_EX_UB) THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  (* ---- premle : PREM <= [[collb]]_v1  (the endgame) ---- *)
  SUBGOAL_THEN (erel_tm prem_tm collv1_tm)
    (LABEL_TAC "premle") THENL
   [MATCH_MP_TAC(ISPECL [`y:num`;`(y %% b) <-> ??- x a p`;`D:A->bool`;
      `E:A->A->bool`;`B:A`;`leq:A`;`v1:num->A`;prem_tm] BVALF_ALL_GLB) THEN
    ASM_REWRITE_TAC[] THEN
    X_GEN_TAC `tt:A` THEN STRIP_TAC THEN
    SUBGOAL_THEN `valuation D ((y |-> (tt:A)) (v1:num->A)) /\
                  (!i. bname D E B (((y |-> (tt:A)) (v1:num->A)) i))`
    STRIP_ASSUME_TAC THENL
     [CONJ_TAC THENL
       [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[];
        MATCH_MP_TAC BNAMEVAL_VALMOD THEN ASM_REWRITE_TAC[]]; ALL_TAC] THEN
    ABBREV_TAC `vv2 = (y |-> (tt:A)) (v1:num->A)` THEN
    (* vv2 lookups *)
    SUBGOAL_THEN `(vv2:num->A) y = tt /\ (vv2:num->A) b = bb`
      STRIP_ASSUME_TAC THENL
     [MAP_EVERY EXPAND_TAC ["vv2";"v1"] THEN
      ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER]; ALL_TAC] THEN
    (* helper valuation (y|->tt)v0 *)
    SUBGOAL_THEN `valuation D ((y |-> (tt:A)) (v0:num->A)) /\
                  (!i. bname D E B (((y |-> (tt:A)) (v0:num->A)) i))`
    STRIP_ASSUME_TAC THENL
     [CONJ_TAC THENL
       [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[];
        MATCH_MP_TAC BNAMEVAL_VALMOD THEN ASM_REWRITE_TAC[]]; ALL_TAC] THEN
    REWRITE_TAC[Iff_DEF] THEN
    (* K = [[tt IN cn]] *)
    MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`tt:A`;`cn:A`]
      EBV_IN_VAL_EXISTS) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(X_CHOOSE_THEN `K:A`
      (CONJUNCTS_THEN2 (LABEL_TAC "kkin")
       (CONJUNCTS_THEN2 (LABEL_TAC "kkB") (LABEL_TAC "kkev")))) THEN
    (* rr in D, E rr B *)
    SUBGOAL_THEN (inDB_tm rr_tm)
      STRIP_ASSUME_TAC THENL
     [CONJ_TAC THENL
       [MP_TAC(ISPECL [`??- x a p`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
          `(y |-> (tt:A)) (v0:num->A)`] BVALF_SPEC) THEN
        ASM_REWRITE_TAC[] THEN STRIP_TAC THEN ASM_REWRITE_TAC[];
        MATCH_MP_TAC BVALF_IN_B THEN ASM_REWRITE_TAC[]]; ALL_TAC] THEN
    (* qeq : [[??- x a p]]_vv2 = rr  (b not in FV) *)
    SUBGOAL_THEN (mk_eq(qval_tm,rr_tm)) (LABEL_TAC "qeq") THENL
     [MATCH_MP_TAC(ISPECL
                   [`??- x a p`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
                    `vv2:num->A`;`(y |-> (tt:A)) (v0:num->A)`]
                     BVALF_FV_CONG) THEN
      ASM_REWRITE_TAC[] THEN
      X_GEN_TAC `i:num` THEN
      REWRITE_TAC[FV_CLAUSES; IN_DELETE; IN_INSERT] THEN DISCH_TAC THEN
      SUBGOAL_THEN `~(i:num = b)` ASSUME_TAC THENL
       [ASM_MESON_TAC[]; ALL_TAC] THEN
      MAP_EVERY EXPAND_TAC ["vv2";"v1"] THEN
      ASM_CASES_TAC `i:num = y` THEN
      ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER]; ALL_TAC] THEN
    (* pval = [[y IN b]]_vv2, ebv_in tt bb pval *)
    SUBGOAL_THEN
     `ebv_in D (E:A->A->bool) B leq tt bb (bvalf D E B leq vv2 (y %% b))`
      (LABEL_TAC "pmem") THENL
     [MP_TAC(ISPECL [`y:num`;`b:num`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
        `vv2:num->A`] BVALF_MEM) THEN ASM_REWRITE_TAC[] THEN
      ASM_SIMP_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN (inDB_tm pval_tm)
      STRIP_ASSUME_TAC THENL
     [CONJ_TAC THENL
       [MP_TAC(ISPECL
               [`(y %% b):form`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
                `vv2:num->A`] BVALF_SPEC) THEN ASM_REWRITE_TAC[] THEN
                     STRIP_TAC THEN ASM_REWRITE_TAC[];
                     MATCH_MP_TAC BVALF_IN_B THEN ASM_REWRITE_TAC[]];
       ALL_TAC] THEN
    (* rhs = meet(K,rr) *)
    MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`K:A`;rr_tm]
      EBALG_MEET) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(X_CHOOSE_THEN `rhs:A` (LABEL_TAC "rhsmeet")) THEN
    (* pvaleq : pval = rhs  (EBV_IN_SEP) *)
    SUBGOAL_THEN (mk_eq(pval_tm,`rhs:A`)) (LABEL_TAC "pvaleq") THENL
     [MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`v0:num->A`;
        `??- x a p`;`y:num`;`cn:A`;`tt:A`;`bb:A`;pval_tm;`K:A`;`rhs:A`]
        EBV_IN_SEP) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC]; ALL_TAC] THEN
    (* emKrr : emeet K rr pval *)
    SUBGOAL_THEN (emeet_tm `K:A` rr_tm pval_tm)
      (LABEL_TAC "emKrr") THENL
     [USE_THEN "pvaleq" (fun th -> ONCE_REWRITE_TAC[th]) THEN
      USE_THEN "rhsmeet" ACCEPT_TAC; ALL_TAC] THEN
    (* mm = meet(PREM,rr) *)
    MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;prem_tm;rr_tm]
      EBALG_MEET) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(X_CHOOSE_THEN `mm:A` (LABEL_TAC "mmmeet")) THEN
    SUBGOAL_THEN `(mm:A) IN D /\ (E:A->A->bool) mm B` STRIP_ASSUME_TAC THENL
     [ASM_MESON_TAC[EMEET_IN]; ALL_TAC] THEN
    (* core : mm <= K  (EBV_REPL_CORE) *)
    SUBGOAL_THEN `erel (D:A->bool) (E:A->A->bool) leq mm (K:A)`
      (LABEL_TAC "core") THENL
      [MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`v0:num->A`;
        `x:num`;`y:num`;`z:num`;`a:num`;`p:form`;`tt:A`;`dm:A`;`ddstar:A`;
        `onebee:A`;`cn:A`;`K:A`;`mm:A`] EBV_REPL_CORE) THEN
      ANTS_TAC THENL
      [ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[]; DISCH_THEN ACCEPT_TAC];
      ALL_TAC] THEN
    (* mm <= rr *)
    SUBGOAL_THEN (erel_tm `mm:A` rr_tm)
      (LABEL_TAC "mmrr") THENL
     [ASM_MESON_TAC[EMEET_LE]; ALL_TAC] THEN
    (* mm <= pval  (EMEET_GREATEST on emKrr) *)
    SUBGOAL_THEN (erel_tm `mm:A` pval_tm)
      (LABEL_TAC "mmpval") THENL
     [MATCH_MP_TAC(ISPECL
                   [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`K:A`;rr_tm;
                    pval_tm;`mm:A`] EMEET_GREATEST) THEN ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    (* i1 : ebimp pval qval i1  (BVALF_IMP), then qeq -> ebimp pval rr i1 *)
    SUBGOAL_THEN (ebimp_tm pval_tm rr_tm i1_tm) (LABEL_TAC "imp1") THENL
     [MP_TAC(ISPECL
             [`(y %% b):form`;`??- x a p`;`D:A->bool`;`E:A->A->bool`;`B:A`;
              `leq:A`;`vv2:num->A`] BVALF_IMP) THEN ASM_REWRITE_TAC[] THEN
      USE_THEN "qeq" (fun th -> REWRITE_TAC[th]); ALL_TAC] THEN
    (* m1 = meet(PREM,pval) *)
    MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;prem_tm;pval_tm]
      EBALG_MEET) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(X_CHOOSE_THEN `m1:A` (LABEL_TAC "m1meet")) THEN
    SUBGOAL_THEN `(m1:A) IN D /\ (E:A->A->bool) m1 B` STRIP_ASSUME_TAC THENL
     [ASM_MESON_TAC[EMEET_IN]; ALL_TAC] THEN
    (* pval <= rr *)
    SUBGOAL_THEN (erel_tm pval_tm rr_tm)
      (LABEL_TAC "pvalrr") THENL
     [ASM_MESON_TAC[EMEET_LE]; ALL_TAC] THEN
    (* m1 <= rr *)
    SUBGOAL_THEN (erel_tm `m1:A` rr_tm)
      (LABEL_TAC "m1rr") THENL
     [MP_TAC(ISPECL
             [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`m1:A`;pval_tm;rr_tm]
             EPORDER_TRANS) THEN ASM_REWRITE_TAC[] THEN
      DISCH_THEN MATCH_MP_TAC THEN ASM_MESON_TAC[EMEET_LE]; ALL_TAC] THEN
    (* prem <= i1  (EBIMP_LE_IMP) *)
    SUBGOAL_THEN (erel_tm prem_tm i1_tm)
      (LABEL_TAC "prem_i1") THENL
     [MP_TAC(ISPECL
             [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;prem_tm;pval_tm;rr_tm;
              i1_tm;`m1:A`] EBIMP_LE_IMP) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    (* i2 : ebimp qval pval i2, then qeq -> ebimp rr pval i2 *)
    SUBGOAL_THEN (ebimp_tm rr_tm pval_tm i2_tm) (LABEL_TAC "imp2") THENL
     [MP_TAC(ISPECL
             [`??- x a p`;`(y %% b):form`;`D:A->bool`;`E:A->A->bool`;`B:A`;
              `leq:A`;`vv2:num->A`] BVALF_IMP) THEN ASM_REWRITE_TAC[] THEN
      USE_THEN "qeq" (fun th -> REWRITE_TAC[th]); ALL_TAC] THEN
    (* prem <= i2  (EBIMP_LE_IMP, m=mm) *)
    SUBGOAL_THEN (erel_tm prem_tm i2_tm)
      (LABEL_TAC "prem_i2") THENL
     [MP_TAC(ISPECL
             [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;prem_tm;rr_tm;pval_tm;
              i2_tm;`mm:A`] EBIMP_LE_IMP) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    (* andmeet : emeet i1 i2 andval *)
    SUBGOAL_THEN (emeet_tm i1_tm i2_tm and_tm) (LABEL_TAC "andmeet") THENL
     [MP_TAC(ISPECL [`(y %% b) --> ??- x a p`;`(??- x a p) --> (y %% b)`;
        `D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`vv2:num->A`]
               BVALF_AND_MEET) THEN
      ASM_REWRITE_TAC[]; ALL_TAC] THEN
    (* finish : PREM <= andval *)
    MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;i1_tm;i2_tm;
      and_tm;prem_tm] EMEET_GREATEST) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* ---- collv1, exbv0 values in D (transitivity membership side conds) *)
  (* ---- *)
  SUBGOAL_THEN (inD_tm collv1_tm)
    ASSUME_TAC THENL
   [MP_TAC(ISPECL
           [collb_tm;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`v1:num->A`]
           BVALF_SPEC) THEN ASM_REWRITE_TAC[] THEN STRIP_TAC THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN (inD_tm exbv0_tm)
    ASSUME_TAC THENL
   [MP_TAC(ISPECL [exb_tm;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`v0:num->A`]
      BVALF_SPEC) THEN ASM_REWRITE_TAC[] THEN STRIP_TAC THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  (* ---- combine premle + exub via transitivity ---- *)
  MP_TAC(ISPECL
         [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;prem_tm;collv1_tm;exbv0_tm]
         EPORDER_TRANS) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN MATCH_MP_TAC THEN
  ASM_REWRITE_TAC[] THEN REPEAT CONJ_TAC THEN
  MATCH_MP_TAC BVALF_IN_B THEN ASM_REWRITE_TAC[]);;

(* ================================================================== *)
(* ===== V^B CHOICE axiom (9th ZFC axiom): abstract Boolean cores ===== *)
(* The V^B choice axiom is forced via a definable boolean LEAST-ELEMENT *)
(* selector  first(m,p) = [[p in m]] /\ ~s_p, where s_p is the sup of   *)
(* [[p' in m]] over p' strictly below p in L's definable wellorder ra.  *)
(* These two lemmas are the pure Boolean-algebra kernels of that        *)
(* construction, independent of the model / order / boolean-value       *)
(* machinery:                                                           *)
(*   FST_DISJOINT_ABS -- the ANTICHAIN property (F-AC): two first-values *)
(*     of names on opposite sides of a complement meet to bot.  Drives  *)
(*     "at most one element of each member is selected" (uniqueness).   *)
(*   FST_SPLIT_ABS    -- the SPLIT identity b = (b/\~s)\/(b/\s) (F-SUP): *)
(*     b_p = first(m,p) \/ (b_p /\ s_p); drives, by wellorder induction, *)
(*     sup_p first(m,p) = sup_p [[p in m]] = [[m nonempty]] (existence). *)
(* ================================================================== *)

let FST_DISJOINT_ABS = prove
 (`!D (E:A->A->bool) B leq bq cq fstp fstq m bot.
      ebalg D E B leq /\
      bq IN D /\ E bq B /\ cq IN D /\ E cq B /\
      fstp IN D /\ E fstp B /\ fstq IN D /\ E fstq B /\
      ecompl D E B leq bq cq /\
      erel D E leq fstp cq /\
      erel D E leq fstq bq /\
      emeet D E B leq fstp fstq m /\
      ebot D E B leq bot
      ==> m = bot`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `eporder D (E:A->A->bool) B leq` ASSUME_TAC THENL
   [ASM_MESON_TAC[EBALG_IMP_PORDER]; ALL_TAC] THEN
  SUBGOAL_THEN `(m:A) IN D /\ (E:A->A->bool) m B` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[EMEET_IN]; ALL_TAC] THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`] EBALG_TOP) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `top:A`) THEN
  SUBGOAL_THEN `(top:A) IN D /\ (E:A->A->bool) top B` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[ETOP_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `(bot:A) IN D /\ (E:A->A->bool) bot B` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[EBOT_IN]; ALL_TAC] THEN
  MP_TAC(ISPECL
         [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`bq:A`;`cq:A`;
          `bot:A`;`top:A`]
         ECOMPL_MEET_JOIN) THEN ASM_REWRITE_TAC[] THEN STRIP_TAC THEN
  SUBGOAL_THEN
    `erel D (E:A->A->bool) leq m fstp /\ erel D (E:A->A->bool) leq m fstq`
    STRIP_ASSUME_TAC THENL [ASM_MESON_TAC[EMEET_LE]; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq m cq` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`m:A`;
                  `fstp:A`;`cq:A`]
                 EPORDER_TRANS) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq m bq` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`m:A`;
                  `fstq:A`;`bq:A`]
                 EPORDER_TRANS) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq m bot` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`bq:A`;`cq:A`;
                  `bot:A`;`m:A`]
                 EMEET_GREATEST) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq bot m` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`bot:A`;`m:A`]
                 EBOT_LE) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`m:A`;`bot:A`]
    EPORDER_ANTISYM) THEN
  ASM_REWRITE_TAC[]);;

let FST_SPLIT_ABS = prove
 (`!D (E:A->A->bool) B leq b s cs fp m2 j.
      ebalg D E B leq /\
      b IN D /\ E b B /\ s IN D /\ E s B /\
      ecompl D E B leq s cs /\
      emeet D E B leq b cs fp /\
      emeet D E B leq b s m2 /\
      ejoin D E B leq fp m2 j
      ==> j = b`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `eporder D (E:A->A->bool) B leq` ASSUME_TAC THENL
   [ASM_MESON_TAC[EBALG_IMP_PORDER]; ALL_TAC] THEN
  SUBGOAL_THEN `(cs:A) IN D /\ (E:A->A->bool) cs B` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[ECOMPL_IN]; ALL_TAC] THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`] EBALG_TOP) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `top:A`) THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`] EBALG_BOT) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `bot:A`) THEN
  SUBGOAL_THEN `(top:A) IN D /\ (E:A->A->bool) top B` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[ETOP_IN]; ALL_TAC] THEN
  MP_TAC(ISPECL
         [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`s:A`;`cs:A`;
          `bot:A`;`top:A`]
         ECOMPL_MEET_JOIN) THEN ASM_REWRITE_TAC[] THEN STRIP_TAC THEN
  SUBGOAL_THEN `ejoin D (E:A->A->bool) B leq cs s top` ASSUME_TAC THENL
   [ASM_MESON_TAC[EJOIN_SYM]; ALL_TAC] THEN
  SUBGOAL_THEN `emeet D (E:A->A->bool) B leq b top b` ASSUME_TAC THENL
   [MATCH_MP_TAC EMEET_TOP THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
                 `b:A`;`cs:A`;`s:A`;`top:A`;`b:A`;`fp:A`;`m2:A`;`j:A`]
    EBALG_DISTRIB) THEN
  ASM_REWRITE_TAC[] THEN DISCH_TAC THEN ASM_MESON_TAC[]);;

(* ===================================================================== *)
(* CHOICE (9th V^B ZFC axiom) -- value-core lemmas C-A/C-B (algebraic).    *)
(* first(m,p) = [[p in m]] /\ ~s_p, s_p = sup{[[q in m]]:q in dom m,q<_ra p}.*)
(* EDOWNSET_SUP_EXISTS builds s_p; FST_LE_COMPL_ABS + FST_DISJOINT_ABS =    *)
(* F-AC antichain; FST_SUP_STEP_ABS + FST_SPLIT_ABS = F-SUP >= step.        *)
(* ===================================================================== *)

(* CHOICE lemma C-A concrete: EDOWNSET_SUP_EXISTS.
   Given a bname m, its domain-set dm (of bnames),
   L-order ra as a set of pairs,
   and an element p, build:
     dd  = { q IN dm : <q,p> IN ra }                (ZF_SEPARATION by rel_form)
     Sp  = { [[q in m]] : q IN dd }                 (BVAL_REPLIMG_EXISTS)
     sp  = elub Sp                                  (ECBA_SUP)
   These are the pieces of the least-element selector first(m,p)=[[p in
     m]] /\ ~sp. *)

(* the constant-m all-bname valuation reads slot 1 as m, slot 0 as the arg *)
let BVAL_CONST_MEM = prove
 (`!D (E:A->A->bool) B leq m s z.
      bval D E B leq ((0 |-> s) (\i:num. m)) (0 %% 1) z <=>
      ebv_in D E B leq s m z`,
  REPEAT GEN_TAC THEN REWRITE_TAC[bval; VALMOD; ARITH_EQ]);;

let EDOWNSET_SUP_EXISTS = prove
 (`!D (E:A->A->bool) B leq m dm ra p.
      model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
      m IN D /\ bname D E B m /\
      dm IN D /\ (!q. q IN D /\ E q dm ==> bname D E B q) /\
      ra IN D /\ p IN D
      ==> ?dd Sp sp.
            dd IN D /\
            (!q. q IN D ==> (E q dd <=> E q dm /\ erel D E ra q p)) /\
            Sp IN D /\ esubset D E Sp B /\
            (!z. z IN D
                 ==> (E z Sp <=> ?q. q IN D /\ E q dd /\
                      ebv_in D E B leq q m z)) /\
            elub D E B leq Sp sp /\ sp IN D /\ E sp B`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `?v0:num->A. valuation D v0` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[VALUATION_EXISTS; MODEL_NONEMPTY]; ALL_TAC] THEN
  ABBREV_TAC `vp = (1 |-> (ra:A)) ((2 |-> (p:A)) (v0:num->A))` THEN
  SUBGOAL_THEN `valuation D (vp:num->A)` ASSUME_TAC THENL
   [EXPAND_TAC "vp" THEN MATCH_MP_TAC VALUATION_VALMOD THEN
    ASM_REWRITE_TAC[] THEN
    MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN
   `!z:A. z IN D
          ==> (holds D E ((0 |-> z) (vp:num->A)) (rel_form 1 0 2) <=>
               erel D (E:A->A->bool) ra z p)`
   (LABEL_TAC "hunpack") THENL
   [X_GEN_TAC `z:A` THEN DISCH_TAC THEN
    MP_TAC(ISPECL
           [`D:A->bool`;`E:A->A->bool`;`(0 |-> z) (vp:num->A)`;`1`;`0`;`2`]
           HOLDS_REL_FORM) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[] THEN MATCH_MP_TAC VALUATION_VALMOD THEN
      ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    EXPAND_TAC "vp" THEN REWRITE_TAC[VALMOD; ARITH_EQ]; ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`] ZF_SEPARATION) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(MP_TAC o SPECL [`rel_form 1 0 2`;`0`;`vp:num->A`;`dm:A`]) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `dd:A` STRIP_ASSUME_TAC) THEN
  SUBGOAL_THEN
   `!q. q IN D ==> (E q (dd:A) <=> E q dm /\ erel D (E:A->A->bool) ra q p)`
   ASSUME_TAC THENL
   [ASM_MESON_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `valuation D (\i:num. m:A)` ASSUME_TAC THENL
   [REWRITE_TAC[valuation] THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `!i. bname D (E:A->A->bool) B ((\i:num. m:A) i)`
    ASSUME_TAC THENL
   [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `!s. s IN D /\ E s (dd:A) ==> bname D (E:A->A->bool) B s`
   ASSUME_TAC THENL
   [ASM_MESON_TAC[]; ALL_TAC] THEN
  MP_TAC(ISPECL [`(0:num) %% 1`;`0`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
                 `(\i:num. m:A)`;`dd:A`] BVAL_REPLIMG_EXISTS) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `Sp:A` STRIP_ASSUME_TAC) THEN
  RULE_ASSUM_TAC(REWRITE_RULE[BVAL_CONST_MEM]) THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`Sp:A`]
         ECBA_SUP) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `sp:A` ASSUME_TAC) THEN
  SUBGOAL_THEN `(sp:A) IN D /\ (E:A->A->bool) sp B` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[ELUB_IN]; ALL_TAC] THEN
  MAP_EVERY EXISTS_TAC [`dd:A`;`Sp:A`;`sp:A`] THEN
  ASM_REWRITE_TAC[]);;

(* CHOICE lemma C-A glue: FST_LE_COMPL_ABS -- derives F-AC's "fstp <= ~bq"
   hypothesis of FST_DISJOINT_ABS.  With fp = bp /\ ~sp and bq <= sp (q in the
   downset of p, so [[q in m]] <= s_p),
   we get fp <= ~sp <= ~bq.  Pure algebra. *)

let FST_LE_COMPL_ABS = prove
 (`!D (E:A->A->bool) B leq bp sp csp fp bq cq.
      ebalg D E B leq /\
      bp IN D /\ E bp B /\ sp IN D /\ E sp B /\ bq IN D /\ E bq B /\
      ecompl D E B leq sp csp /\ ecompl D E B leq bq cq /\
      emeet D E B leq bp csp fp /\
      erel D E leq bq sp
      ==> erel D E leq fp cq`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `eporder D (E:A->A->bool) B leq` ASSUME_TAC THENL
   [ASM_MESON_TAC[EBALG_IMP_PORDER]; ALL_TAC] THEN
  SUBGOAL_THEN `(csp:A) IN D /\ (E:A->A->bool) csp B` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[ECOMPL_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `(cq:A) IN D /\ (E:A->A->bool) cq B` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[ECOMPL_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `(fp:A) IN D /\ (E:A->A->bool) fp B` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[EMEET_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq fp csp` ASSUME_TAC THENL
   [ASM_MESON_TAC[EMEET_LE]; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq csp cq` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
                        `bq:A`;`sp:A`;`cq:A`;`csp:A`] ECOMPL_ANTITONE) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
                      `fp:A`;`csp:A`;`cq:A`] EPORDER_TRANS) THEN
  ASM_REWRITE_TAC[]);;

(* CHOICE lemma C-B core: FST_SUP_STEP_ABS -- the algebraic heart of
  the F-SUP >=
   induction step.  With bp=[[p in m]], fp=first(m,p)=bp/\~sp, m2=bp/\sp, and
   RHS = sup_p first(m,p): FST_SPLIT_ABS gives bp = fp \/ m2;
   if fp<=RHS (fp is a
   sup term) and sp<=RHS (induction: all q<_ra p already good),
   then m2<=sp<=RHS
   and bp = fp\/m2 <= RHS.  This is the whole least-counterexample
     contradiction
   minus the wellorder/bad-set glue.  Pure Boolean algebra. *)

let FST_SUP_STEP_ABS = prove
 (`!D (E:A->A->bool) B leq bp sp csp fp m2 j rhs.
      ebalg D E B leq /\
      bp IN D /\ E bp B /\ sp IN D /\ E sp B /\ rhs IN D /\ E rhs B /\
      ecompl D E B leq sp csp /\
      emeet D E B leq bp csp fp /\ emeet D E B leq bp sp m2 /\
      ejoin D E B leq fp m2 j /\
      erel D E leq fp rhs /\ erel D E leq sp rhs
      ==> erel D E leq bp rhs`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `eporder D (E:A->A->bool) B leq` ASSUME_TAC THENL
   [ASM_MESON_TAC[EBALG_IMP_PORDER]; ALL_TAC] THEN
  SUBGOAL_THEN `(m2:A) IN D /\ (E:A->A->bool) m2 B` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[EMEET_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `(fp:A) IN D /\ (E:A->A->bool) fp B` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[EMEET_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `(j:A) IN D /\ (E:A->A->bool) j B` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[EJOIN_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq m2 sp` ASSUME_TAC THENL
   [ASM_MESON_TAC[EMEET_LE]; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq m2 rhs` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
                        `m2:A`;`sp:A`;`rhs:A`] EPORDER_TRANS) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq j rhs` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
                        `fp:A`;`m2:A`;`j:A`;`rhs:A`] EJOIN_LEAST) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(j:A) = bp` (fun th -> ASSUME_TAC(SYM th)) THENL
   [MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
                  `bp:A`;`sp:A`;`csp:A`;`fp:A`;`m2:A`;`j:A`]
                        FST_SPLIT_ABS) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  ASM_MESON_TAC[]);;

(* ===================================================================== *)
(* CHOICE (9th V^B ZFC axiom) -- lemmas batch 2: value packaging + the      *)
(* [[p in m]] internalization that builds the F-SUP bad set as an M-set.   *)
(* Depends on EDOWNSET_SUP_EXISTS (batch 1).                               *)
(* ===================================================================== *)

(* EFIRST_EXISTS: bundle bp=[[p in m]] (EBV_IN_VAL_EXISTS), the downset sup
   sp=s_p (EDOWNSET_SUP_EXISTS), csp=~sp (EBALG_COMPL), fp=first(m,p)=bp/\~sp
   (EBALG_MEET) into one existence lemma, exposing the dd/Sp/elub structure
   needed by F-AC (sup-membership) and F-SUP (least-counterexample). *)

let EFIRST_EXISTS = prove
 (`!D (E:A->A->bool) B leq m dm ra p.
      model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
      m IN D /\ bname D E B m /\
      dm IN D /\ (!q. q IN D /\ E q dm ==> bname D E B q) /\
      ra IN D /\ p IN D /\ bname D E B p
      ==> ?bp dd Sp sp csp fp.
            bp IN D /\ E bp B /\ ebv_in D E B leq p m bp /\
            dd IN D /\
            (!q. q IN D ==> (E q dd <=> E q dm /\ erel D E ra q p)) /\
            Sp IN D /\ esubset D E Sp B /\
            (!z. z IN D
                 ==> (E z Sp <=> ?q. q IN D /\ E q dd /\
                      ebv_in D E B leq q m z)) /\
            elub D E B leq Sp sp /\ sp IN D /\ E sp B /\
            ecompl D E B leq sp csp /\ csp IN D /\ E csp B /\
            emeet D E B leq bp csp fp /\ fp IN D /\ E fp B`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `ebalg D (E:A->A->bool) B leq` ASSUME_TAC THENL
   [ASM_MESON_TAC[ECBA_IMP_BALG]; ALL_TAC] THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`p:A`;`m:A`]
    EBV_IN_VAL_EXISTS) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `bp:A` STRIP_ASSUME_TAC) THEN
  MP_TAC(ISPECL
         [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`m:A`;`dm:A`;`ra:A`;`p:A`]
         EDOWNSET_SUP_EXISTS) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `dd:A`
    (X_CHOOSE_THEN `Sp:A` (X_CHOOSE_THEN `sp:A` STRIP_ASSUME_TAC))) THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`sp:A`]
         EBALG_COMPL) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `csp:A` ASSUME_TAC) THEN
  SUBGOAL_THEN `(csp:A) IN D /\ (E:A->A->bool) csp B` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[ECOMPL_IN]; ALL_TAC] THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`bp:A`;`csp:A`]
         EBALG_MEET) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `fp:A` ASSUME_TAC) THEN
  SUBGOAL_THEN `(fp:A) IN D /\ (E:A->A->bool) fp B` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[EMEET_IN]; ALL_TAC] THEN
  MAP_EVERY EXISTS_TAC [`bp:A`;`dd:A`;`Sp:A`;`sp:A`;`csp:A`;`fp:A`] THEN
  ASM_REWRITE_TAC[]);;

(* EBADSET_EXISTS: internalize [[p in m]] to build the bad set
   {p in dm : ~([[p in m]] <= rhs)} as an M-set,
   via ZF_SEPARATION on the object
   formula  ?? 5 (ebv_in_form 5 0 3 1 &&
     Not(rel_form 1 5 4))  with sep-var 0=p,
   params 1=leq,2=B,3=m,4=rhs, value bound at 5.  HOLDS_EBV_IN_FORM fixes B at
   slot 2 and reads ebv_in (v 2)(v 1)(v 0)(v 3)(v 5).  This is the shared crux
   plumbing (F-SUP >= wrapper + selector name c). *)

let EBADSET_EXISTS = prove
 (`!D (E:A->A->bool) B leq m dm rhs.
      model D E ZF_AX /\ B IN D /\ leq IN D /\ m IN D /\ dm IN D /\ rhs IN D
      ==> ?bad. bad IN D /\
            !p. p IN D
                ==> (E p bad <=>
                     E p dm /\
                     ?z. z IN D /\ ebv_in D E B leq p m z /\
                         ~(erel D E leq z rhs))`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `?v0:num->A. valuation D v0` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[VALUATION_EXISTS; MODEL_NONEMPTY]; ALL_TAC] THEN
  ABBREV_TAC
   `vp = (1 |-> (leq:A))
    ((2 |-> (B:A)) ((3 |-> (m:A)) ((4 |-> (rhs:A)) (v0:num->A))))` THEN
  SUBGOAL_THEN `valuation D (vp:num->A)` ASSUME_TAC THENL
   [EXPAND_TAC "vp" THEN
    REPEAT(MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[]); ALL_TAC] THEN
  ABBREV_TAC `phi = ?? 5 (ebv_in_form 5 0 3 1 && Not(rel_form 1 5 4))` THEN
  SUBGOAL_THEN
   `!p:A. p IN D
          ==> (holds D E ((0 |-> p) (vp:num->A)) phi <=>
               ?z. z IN D /\ ebv_in D E B leq p m z /\
                   ~(erel D (E:A->A->bool) leq z rhs))`
   (LABEL_TAC "hchar") THENL
   [X_GEN_TAC `p:A` THEN DISCH_TAC THEN
    SUBGOAL_THEN `valuation D ((0 |-> p) (vp:num->A))` ASSUME_TAC THENL
     [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    EXPAND_TAC "phi" THEN REWRITE_TAC[HOLDS_EX] THEN
    SUBGOAL_THEN
     `!a:A. a IN D
            ==> (holds D E ((5 |-> a) ((0 |-> p) (vp:num->A)))
                   (ebv_in_form 5 0 3 1 && Not(rel_form 1 5 4)) <=>
                 ebv_in D E B leq p m a /\ ~(erel D (E:A->A->bool) leq a rhs))`
     (fun th -> ASM_MESON_TAC[th]) THEN
    X_GEN_TAC `a:A` THEN DISCH_TAC THEN
    SUBGOAL_THEN `valuation D ((5 |-> a) ((0 |-> p) (vp:num->A)))`
      ASSUME_TAC THENL
      [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    REWRITE_TAC[HOLDS_AND; HOLDS_NOT] THEN
    MP_TAC(ISPECL
           [`D:A->bool`;`E:A->A->bool`;`(5 |-> a) ((0 |-> p) (vp:num->A))`;
            `5`;`0`;`3`;`1`] HOLDS_EBV_IN_FORM) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN SUBST1_TAC THEN
    MP_TAC(ISPECL
           [`D:A->bool`;`E:A->A->bool`;`(5 |-> a) ((0 |-> p) (vp:num->A))`;
            `1`;`5`;`4`] HOLDS_REL_FORM) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN SUBST1_TAC THEN
    EXPAND_TAC "vp" THEN REWRITE_TAC[VALMOD; ARITH_EQ]; ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`] ZF_SEPARATION) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(MP_TAC o SPECL [`phi:form`;`0`;`vp:num->A`;`dm:A`]) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `bad:A` STRIP_ASSUME_TAC) THEN
  EXISTS_TAC `bad:A` THEN ASM_REWRITE_TAC[] THEN
  X_GEN_TAC `p:A` THEN DISCH_TAC THEN ASM_SIMP_TAC[]);;
(* CHOICE F-SUP wrapper sub-step: if every downset value [[q in m]]
  (q in dd) is
   <= rhs, then the downset sup sp <= rhs.  Pure ELUB_LEAST over the
     value-set Sp. *)

let FSUP_SP_LE = prove
 (`!D (E:A->A->bool) B leq m dd Sp sp rhs.
      B IN D /\ leq IN D /\ rhs IN D /\ E rhs B /\
      dd IN D /\ Sp IN D /\
      (!z. z IN D
           ==> (E z Sp <=> ?q. q IN D /\ E q dd /\ ebv_in D E B leq q m z)) /\
      elub D E B leq Sp sp /\
      (!q z. q IN D /\ E q dd /\ z IN D /\ ebv_in D E B leq q m z
             ==> erel D E leq z rhs)
      ==> erel D E leq sp rhs`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  MP_TAC(ISPECL
         [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`Sp:A`;`sp:A`;`rhs:A`]
         ELUB_LEAST) THEN
  DISCH_THEN MATCH_MP_TAC THEN
  ASM_REWRITE_TAC[eubound] THEN
  X_GEN_TAC `z:A` THEN STRIP_TAC THEN
  SUBGOAL_THEN `?q. q IN D /\ E q dd /\ ebv_in D (E:A->A->bool) B leq q m z`
    STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[]; ALL_TAC] THEN
  ASM_MESON_TAC[]);;
(* CHOICE lemma C-B: F-SUP >= wrapper (abstract in ra).  Given rhs
  an upper bound
   of all first(m,q) (q in dm) and a well-founded ra on dm-subsets, every value
   [[p in m]] (p in dm) is <= rhs.  Route: bad set (EBADSET_EXISTS) nonempty =>
   ra-least p0 => downset of p0 all good => s_{p0} <= rhs (FSUP_SP_LE)
     => first(m,p0)
   <= rhs (upper-bound hyp) => [[p0 in m]] <= rhs
     (FST_SUP_STEP_ABS), contra. *)

(* CHOICE lemma C-B glue: RA_FOR_DOM -- under V=L,
any set dm carries an L-wellorder
   object ra IN D that is asymmetric and well-founded on D-subsets of dm.  This
   discharges exactly the two order hypotheses of FST_SUP_GE.  Route = the
   ELMEM_CHOICE access pattern: elmem dm -> ordinal a / stage ya covering dm
   (transitivity); ELWOU_EXISTS -> ra;
   ELWOU_INVARIANT + ELWOINVU_NORM -> asymmetry
   (3rd conjunct) + least-element (7th conjunct). *)

let RA_FOR_DOM = prove
 (`!D (E:A->A->bool) dm.
      model D E ZF_AX /\ (!u. u IN D ==> elmem D E u) /\ dm IN D
      ==> ?ra. ra IN D /\
              (!u u'. u IN D /\ u' IN D /\ erel D E ra u u'
                      ==> ~(erel D E ra u' u)) /\
              (!z. z IN D /\ (!t. t IN D /\ E t z ==> E t dm) /\
                   (?t. t IN D /\ E t z)
                   ==> ?p0. p0 IN D /\ E p0 z /\
                           !q. q IN D /\ E q z /\ ~(q = p0) ==>
                             erel D E ra p0 q)`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `elmem D (E:A->A->bool) dm` MP_TAC THENL
   [ASM_MESON_TAC[]; ALL_TAC] THEN
  REWRITE_TAC[elmem] THEN
  DISCH_THEN(X_CHOOSE_THEN `a:A` (X_CHOOSE_THEN `ya:A` STRIP_ASSUME_TAC)) THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`a:A`] ELWOU_EXISTS) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `ra:A` STRIP_ASSUME_TAC) THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`a:A`] ELWOU_INVARIANT) THEN
  ASM_REWRITE_TAC[] THEN DISCH_TAC THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`a:A`;`ra:A`;`ya:A`]
         ELWOINVU_NORM) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(fun th ->
    LABEL_TAC "c3" (CONJUNCT1(CONJUNCT2(CONJUNCT2 th))) THEN
    LABEL_TAC "c7" (CONJUNCT2(CONJUNCT2(CONJUNCT2(CONJUNCT2(CONJUNCT2
                     (CONJUNCT2 th))))))) THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`a:A`;`ya:A`]
         ELSTAGE_TRANSITIVE) THEN
  ASM_REWRITE_TAC[] THEN REWRITE_TAC[etransitive; esubset] THEN DISCH_TAC THEN
  EXISTS_TAC `ra:A` THEN REPEAT CONJ_TAC THENL
   [FIRST_ASSUM ACCEPT_TAC;
    USE_THEN "c3" ACCEPT_TAC;
    X_GEN_TAC `z:A` THEN STRIP_TAC THEN
    SUBGOAL_THEN
     `?p0:A. p0 IN D /\ (E:A->A->bool) p0 z /\
             (!q. q IN D /\ E q z /\ ~(q = p0) ==> erel D E ra p0 q)`
     STRIP_ASSUME_TAC THENL
     [USE_THEN "c7" MATCH_MP_TAC THEN REPEAT CONJ_TAC THENL
       [FIRST_ASSUM ACCEPT_TAC;
        X_GEN_TAC `tt:A` THEN STRIP_TAC THEN ASM_MESON_TAC[];
        ASM_MESON_TAC[]];
      ALL_TAC] THEN
    EXISTS_TAC `p0:A` THEN ASM_REWRITE_TAC[]]);;
(* CHOICE C-E piece: the EXISTENCE-side transport  [[m=t]] /\
  first(m,p) <= [[p in t]].
   first(m,p) <= [[p in m]] (F-LE = EMEET_LE), and [[m=t]] /\
     [[p in m]] <= [[p in t]]
   (EBV_IN_CONG_R).  Meet-monotone in the 2nd arg gives [[m=t]]/\first <=
     [[m=t]]/\[[p in m]]
   = z23 <= [[p in t]].  Pure algebra + F5 congruence; firstsel_form-free. *)

let FST_CONG_MEM = prove
 (`!D (E:A->A->bool) B leq m t p z20 bp fp mf z22.
      model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
      m IN D /\ t IN D /\ p IN D /\
      bname D E B m /\ bname D E B t /\ bname D E B p /\
      z20 IN D /\ bp IN D /\ fp IN D /\ mf IN D /\ z22 IN D /\
      E fp B /\
      ebv_eq D E B leq m t z20 /\
      ebv_in D E B leq p m bp /\
      erel D E leq fp bp /\
      emeet D E B leq z20 fp mf /\
      ebv_in D E B leq p t z22
      ==> erel D E leq mf z22`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `ebalg D (E:A->A->bool) B leq` ASSUME_TAC THENL
   [ASM_MESON_TAC[ECBA_IMP_BALG]; ALL_TAC] THEN
  SUBGOAL_THEN `eporder D (E:A->A->bool) B leq` ASSUME_TAC THENL
   [ASM_MESON_TAC[EBALG_IMP_PORDER]; ALL_TAC] THEN
  SUBGOAL_THEN
   `(E:A->A->bool) z20 B /\ (E:A->A->bool) bp B /\
    (E:A->A->bool) mf B /\ (E:A->A->bool) z22 B`
   STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[EBV_EQ_IN_B; EBV_IN_IN_B; EMEET_IN]; ALL_TAC] THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`z20:A`;`bp:A`]
    EBALG_MEET) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `z23:A`) THEN
  SUBGOAL_THEN `(z23:A) IN D /\ (E:A->A->bool) z23 B` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[EMEET_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq z23 z22` ASSUME_TAC THENL
   [MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
                  `m:A`;`t:A`;`p:A`;`z20:A`;`bp:A`;`z22:A`;`z23:A`]
      EBV_IN_CONG_R) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC]; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq mf z23` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
                        `z20:A`;`bp:A`;`z23:A`;`mf:A`] EMEET_GREATEST) THEN
    ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
     [ASM_MESON_TAC[EMEET_LE];
      MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
                          `mf:A`;`fp:A`;`bp:A`] EPORDER_TRANS) THEN
      ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[EMEET_LE]];
    ALL_TAC] THEN
  MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
                      `mf:A`;`z23:A`;`z22:A`] EPORDER_TRANS) THEN
  ASM_REWRITE_TAC[]);;

(* ===================================================================== *)
(* CHOICE (C-C): the object formula firstsel_fm internalizing the         *)
(* least-element selector value                                            *)
(*     first(m,p) = [[p in m]] MEET ~s_p,                                  *)
(*     s_p = elub { [[q in m]] : q in dm, erel ra q p }  (definite ground  *)
(*                                          downset value-set).            *)
(* Slot map (free vars of firstsel_fm): 0=p, 1=leq, 2=B (fixed by          *)
(* HOLDS_EBV_IN_FORM), 3=m, 4=ra, 5=dm(domain-cover), 6=first-output.      *)
(* Internal bound vars: ??7=Sp, ??8=sp, ??9=csp, ??10=bp; comprehension    *)
(* !!11=iz, ??12=iq.  The comprehension builds Sp semantically as the      *)
(* DEFINITE ground downset value-set (the design's "correct route": the    *)
(* naive bval-over-wellorder quantifier gives a wrong value because        *)
(* [[q<p]] is non-definite for arbitrary bnames).                          *)
(* ===================================================================== *)

let firstsel_fm = new_definition
 `firstsel_fm =
    ?? 7 (?? 8 (?? 9 (?? 10 (
      (!! 11 ((11 %% 7) <->
              (?? 12 ((12 %% 5) && rel_form 4 12 0 &&
                      ebv_in_form 11 12 3 1)))) &&
      elub_form 2 1 7 8 &&
      bcompl_form 1 2 8 9 &&
      ebv_in_form 10 0 3 1 &&
      bmeet_form 1 2 10 9 6))))`;;

(* Atomic body of the comprehension, under the two comprehension binders    *)
(* 11 (=iz) and 12 (=iq).  Reads slots off vv, with the two bound points a  *)
(* (=iz value) and a12 (=iq value).                                         *)
let FIRSTSEL_ATOM = prove
 (`!D (E:A->A->bool) vv a a12.
     model D E ZF_AX /\ valuation D vv /\ a IN D /\ a12 IN D
     ==> (holds D E ((12|->a12)((11|->a)vv))
              ((12 %% 5) && rel_form 4 12 0 && ebv_in_form 11 12 3 1)
          <=> E a12 (vv 5) /\ erel D E (vv 4) a12 (vv 0) /\
              ebv_in D E (vv 2) (vv 1) a12 (vv 3) a)`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `valuation D ((12|->a12)((11|->a)(vv:num->A)))` ASSUME_TAC THENL
   [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
  ASM_SIMP_TAC[HOLDS_AND; HOLDS_REL_FORM; HOLDS_EBV_IN_FORM; HOLDS_MEM] THEN
  REWRITE_TAC[VALMOD; ARITH_EQ]);;

(* The full comprehension  !!11 (11%%7 <-> ??12 body)  characterizes slot 7 *)
(* (=Sp) as the ground downset value-set.                                   *)
let FIRSTSEL_COMP = prove
 (`!D (E:A->A->bool) vv.
     model D E ZF_AX /\ valuation D vv
     ==> (holds D E vv
            (!! 11 ((11 %% 7) <->
                    (?? 12 ((12 %% 5) && rel_form 4 12 0 &&
                            ebv_in_form 11 12 3 1))))
          <=> (!z. z IN D ==> (E z (vv 7) <=>
                ?q. q IN D /\ E q (vv 5) /\ erel D E (vv 4) q (vv 0) /\
                    ebv_in D E (vv 2) (vv 1) q (vv 3) z)))`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  ASM_SIMP_TAC[HOLDS_ALL] THEN
  REWRITE_TAC[HOLDS_IFF; HOLDS_MEM; HOLDS_EX] THEN
  REWRITE_TAC[VALMOD; ARITH_EQ] THEN
  ASM_MESON_TAC[FIRSTSEL_ATOM]);;

(* The 5-way body under the four existential binders 7,8,9,10.              *)
let FIRSTSEL_BODY = prove
 (`!D (E:A->A->bool) v a7 a8 a9 a10.
     model D E ZF_AX /\ valuation D v /\
     a7 IN D /\ a8 IN D /\ a9 IN D /\ a10 IN D
     ==> (holds D E ((10|->a10)((9|->a9)((8|->a8)((7|->a7)v))))
            ((!! 11 ((11 %% 7) <->
                     (?? 12 ((12 %% 5) && rel_form 4 12 0 &&
                             ebv_in_form 11 12 3 1)))) &&
             elub_form 2 1 7 8 &&
             bcompl_form 1 2 8 9 &&
             ebv_in_form 10 0 3 1 &&
             bmeet_form 1 2 10 9 6)
          <=>
          (!z. z IN D ==> (E z a7 <=>
                ?q. q IN D /\ E q (v 5) /\ erel D E (v 4) q (v 0) /\
                    ebv_in D E (v 2) (v 1) q (v 3) z)) /\
          elub D E (v 2) (v 1) a7 a8 /\
          ecompl D E (v 2) (v 1) a8 a9 /\
          ebv_in D E (v 2) (v 1) (v 0) (v 3) a10 /\
          emeet D E (v 2) (v 1) a10 a9 (v 6))`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN
   `valuation D ((10|->a10)((9|->a9)((8|->a8)((7|->a7)(v:num->A)))))`
   ASSUME_TAC THENL [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
  ASM_SIMP_TAC[HOLDS_AND; HOLDS_ELUB_FORM; HOLDS_BCOMPL_FORM;
               HOLDS_EBV_IN_FORM; HOLDS_BMEET_FORM] THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;
     `(10|->a10)((9|->a9)((8|->a8)((7|->a7)(v:num->A))))`] FIRSTSEL_COMP) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN SUBST1_TAC THEN
  REWRITE_TAC[VALMOD; ARITH_EQ]);;

(* The holds-characterization of firstsel_fm: exposes the four semantic     *)
(* ingredients Sp (ground downset value-set), sp=elub Sp, csp=~sp,          *)
(* bp=[[p in m]], with the output slot 6 = emeet bp csp.                    *)
let FIRSTSEL_HOLDS = prove
 (`!D (E:A->A->bool) v.
     model D E ZF_AX /\ valuation D v
     ==> (holds D E v firstsel_fm <=>
          ?Sp sp csp bp.
            Sp IN D /\ sp IN D /\ csp IN D /\ bp IN D /\
            (!z. z IN D ==> (E z Sp <=>
                ?q. q IN D /\ E q (v 5) /\ erel D E (v 4) q (v 0) /\
                    ebv_in D E (v 2) (v 1) q (v 3) z)) /\
            elub D E (v 2) (v 1) Sp sp /\
            ecompl D E (v 2) (v 1) sp csp /\
            ebv_in D E (v 2) (v 1) (v 0) (v 3) bp /\
            emeet D E (v 2) (v 1) bp csp (v 6))`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  REWRITE_TAC[firstsel_fm; HOLDS_EX] THEN
  EQ_TAC THENL
   [INTRO_TAC "@a7. a7D @a8. a8D @a9. a9D @a10. a10D H" THEN
    MAP_EVERY EXISTS_TAC [`a7:A`;`a8:A`;`a9:A`;`a10:A`] THEN
    MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`v:num->A`;
                   `a7:A`;`a8:A`;`a9:A`;`a10:A`] FIRSTSEL_BODY) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> USE_THEN "H" (fun h -> ASSUME_TAC(EQ_MP th h))) THEN
    ASM_REWRITE_TAC[];
    DISCH_THEN(X_CHOOSE_THEN `Sp:A`
               (X_CHOOSE_THEN `sp:A` (X_CHOOSE_THEN `csp:A`
                                      (X_CHOOSE_THEN `bp:A`
                                       STRIP_ASSUME_TAC)))) THEN
    EXISTS_TAC `Sp:A` THEN CONJ_TAC THENL
    [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    EXISTS_TAC `sp:A` THEN CONJ_TAC THENL
    [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    EXISTS_TAC `csp:A` THEN CONJ_TAC THENL
    [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    EXISTS_TAC `bp:A` THEN CONJ_TAC THENL
    [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`v:num->A`;
                   `Sp:A`;`sp:A`;`csp:A`;`bp:A`] FIRSTSEL_BODY) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN SUBST1_TAC THEN ASM_REWRITE_TAC[]]);;

(* Existence of the first-value output fp (in D, an element of B): take     *)
(* EFIRST_EXISTS's witnesses and run FIRSTSEL_HOLDS backwards.  Requires     *)
(* the valuation to carry the standard slots 1..5 = leq,B,m,ra,dm and slot   *)
(* 0 = p a bname.                                                            *)
let FIRSTSEL_EXISTS = prove
 (`!D (E:A->A->bool) B leq m dm ra v.
      model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
      m IN D /\ bname D E B m /\ dm IN D /\
      (!q. q IN D /\ E q dm ==> bname D E B q) /\ ra IN D /\
      valuation D v /\ v 1 = leq /\ v 2 = B /\ v 3 = m /\
        v 4 = ra /\ v 5 = dm /\
      bname D E B (v 0)
      ==> ?fp. fp IN D /\ E fp B /\ holds D E ((6 |-> fp) v) firstsel_fm`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `(v:num->A) 0 IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[valuation]; ALL_TAC] THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`m:A`;`dm:A`;`ra:A`;
                 `(v:num->A) 0`] EFIRST_EXISTS) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `bp:A` (X_CHOOSE_THEN `dd:A` (X_CHOOSE_THEN `Sp:A`
    (X_CHOOSE_THEN `sp:A` (X_CHOOSE_THEN `csp:A` (X_CHOOSE_THEN `fp:A`
       STRIP_ASSUME_TAC)))))) THEN
  EXISTS_TAC `fp:A` THEN ASM_REWRITE_TAC[] THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`(6 |-> (fp:A)) (v:num->A)`]
    FIRSTSEL_HOLDS) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[] THEN MATCH_MP_TAC VALUATION_VALMOD THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN SUBST1_TAC THEN
  MAP_EVERY EXISTS_TAC [`Sp:A`;`sp:A`;`csp:A`;`bp:A`] THEN
  REWRITE_TAC[VALMOD; ARITH_EQ] THEN
  SUBGOAL_THEN
   `(v:num->A) 1 = leq /\ v 2 = B /\ v 3 = m /\ v 4 = ra /\ v 5 = dm`
   (fun th -> REWRITE_TAC[th]) THENL
   [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  REPEAT CONJ_TAC THENL
   [FIRST_ASSUM ACCEPT_TAC;
    FIRST_ASSUM ACCEPT_TAC;
    FIRST_ASSUM ACCEPT_TAC;
    FIRST_ASSUM ACCEPT_TAC;
    X_GEN_TAC `z:A` THEN DISCH_TAC THEN ASM_MESON_TAC[];
    FIRST_ASSUM ACCEPT_TAC;
    FIRST_ASSUM ACCEPT_TAC;
    FIRST_ASSUM ACCEPT_TAC;
    FIRST_ASSUM ACCEPT_TAC]);;

(* Destructor: any output g with holds ((6|->g)v) firstsel_fm exposes the   *)
(* four semantic ingredients with slots already reduced to v 0..v 5, g.     *)
let FIRSTSEL_DEST = prove
 (`!D (E:A->A->bool) B leq v g.
      model D E ZF_AX /\ valuation D v /\ v 1 = leq /\ v 2 = B /\ g IN D /\
      holds D E ((6 |-> g) v) firstsel_fm
      ==> ?Sp sp csp bp.
            Sp IN D /\ sp IN D /\ csp IN D /\ bp IN D /\
            (!z. z IN D
                 ==> (E z Sp <=>
                      ?q. q IN D /\ E q (v 5) /\ erel D E (v 4) q (v 0) /\
                          ebv_in D E B leq q (v 3) z)) /\
            elub D E B leq Sp sp /\ ecompl D E B leq sp csp /\
            ebv_in D E B leq (v 0) (v 3) bp /\ emeet D E B leq bp csp g`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`(6 |-> (g:A)) (v:num->A)`]
    FIRSTSEL_HOLDS) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[] THEN MATCH_MP_TAC VALUATION_VALMOD THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  REWRITE_TAC[VALMOD; ARITH_EQ] THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN ACCEPT_TAC);;

(* ===================================================================== *)
(* CHOICE (C-C): valuation-agreement corollary for firstsel_fm,           *)
(* the phi_c c-graph replacement formula, and its holds/destructor/       *)
(* functionality/existence layer.                                         *)
(* ===================================================================== *)

(* Valuation-agreement: holds firstsel_fm depends only on slots 0..6.     *)
let FIRSTSEL_HOLDS_AGREE = prove
 (`!D (E:A->A->bool) v v'.
     model D E ZF_AX /\ valuation D v /\ valuation D v' /\
     v 0 = v' 0 /\ v 1 = v' 1 /\ v 2 = v' 2 /\ v 3 = v' 3 /\
     v 4 = v' 4 /\ v 5 = v' 5 /\ v 6 = v' 6
     ==> (holds D E v firstsel_fm <=> holds D E v' firstsel_fm)`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  ASM_SIMP_TAC[FIRSTSEL_HOLDS] THEN
  ASM_REWRITE_TAC[]);;

(* Functionality tool reading outputs as slot 6 for two valuations that   *)
(* agree on 0..5 (slot 6 may sit nested under higher slots in phi_c).     *)
let FIRSTSEL_UNIQUE_GEN = prove
 (`!D (E:A->A->bool) B leq v v'.
      model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
      valuation D v /\ valuation D v' /\
      v 1 = leq /\ v 2 = B /\ v' 1 = leq /\ v' 2 = B /\
      v 0 = v' 0 /\ v 3 = v' 3 /\ v 4 = v' 4 /\ v 5 = v' 5 /\
      holds D E v firstsel_fm /\ holds D E v' firstsel_fm
      ==> v 6 = v' 6`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `ebalg D (E:A->A->bool) B leq` ASSUME_TAC THENL
   [ASM_MESON_TAC[ECBA_IMP_BALG]; ALL_TAC] THEN
  SUBGOAL_THEN `eporder D (E:A->A->bool) B leq` ASSUME_TAC THENL
   [ASM_MESON_TAC[ECBA_IMP_BALG; EBALG_IMP_PORDER]; ALL_TAC] THEN
  SUBGOAL_THEN `(v:num->A) 0 IN D /\ (v:num->A) 3 IN D /\
                (v:num->A) 6 IN D /\ (v':num->A) 6 IN D` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[valuation]; ALL_TAC] THEN
  MP_TAC(ISPECL
         [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`v:num->A`;`(v:num->A) 6`]
         FIRSTSEL_DEST) THEN
  SUBGOAL_THEN `(6 |-> (v:num->A) 6) v = v` (fun th -> REWRITE_TAC[th]) THENL
   [REWRITE_TAC[FUN_EQ_THM; VALMOD] THEN GEN_TAC THEN COND_CASES_TAC THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `Sp1:A`
             (X_CHOOSE_THEN `sp1:A` (X_CHOOSE_THEN `csp1:A`
                                     (X_CHOOSE_THEN `bp1:A`
                                      STRIP_ASSUME_TAC)))) THEN
  MP_TAC(ISPECL
         [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`v':num->A`;`(v':num->A) 6`]
         FIRSTSEL_DEST) THEN
  SUBGOAL_THEN `(6 |-> (v':num->A) 6) v' = v'`
    (fun th -> REWRITE_TAC[th]) THENL
   [REWRITE_TAC[FUN_EQ_THM; VALMOD] THEN GEN_TAC THEN COND_CASES_TAC THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `Sp2:A`
             (X_CHOOSE_THEN `sp2:A` (X_CHOOSE_THEN `csp2:A`
                                     (X_CHOOSE_THEN `bp2:A`
                                      STRIP_ASSUME_TAC)))) THEN
  SUBGOAL_THEN `Sp1:A = Sp2` SUBST_ALL_TAC THENL
   [FIRST_ASSUM(MATCH_MP_TAC o MATCH_MP ZF_EXTENSIONALITY) THEN
    ASM_REWRITE_TAC[] THEN X_GEN_TAC `z:A` THEN DISCH_TAC THEN
    ASM_MESON_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `sp1:A = sp2` SUBST_ALL_TAC THENL
   [ASM_MESON_TAC[ELUB_UNIQUE]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) sp2 B` ASSUME_TAC THENL
   [ASM_MESON_TAC[ELUB_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `csp1:A = csp2` SUBST_ALL_TAC THENL
   [ASM_MESON_TAC[ECOMPL_UNIQUE]; ALL_TAC] THEN
  SUBGOAL_THEN `bp1:A = bp2` SUBST_ALL_TAC THENL
   [ASM_MESON_TAC[EBV_IN_UNIQUE]; ALL_TAC] THEN
  ASM_MESON_TAC[EMEET_UNIQUE]);;

(* The c-graph replacement formula phi_c: input pair u=<m,p> at slot 16,  *)
(* output pair w=<p,[[m in x]] MEET first(m,p)> at slot 20; x-family=15.  *)
let phi_c = new_definition
 `phi_c =
    ?? 3 (?? 0 (?? 6 (?? 13 (?? 14 (
      opair_form 3 0 16 &&
      firstsel_fm &&
      ebv_in_form 13 3 15 1 &&
      bmeet_form 1 2 13 6 14 &&
      opair_form 0 14 20)))))`;;

let PHI_C_BODY = prove
 (`!D (E:A->A->bool) v a3 a0 a6 a13 a14.
     model D E ZF_AX /\ valuation D v /\
     a3 IN D /\ a0 IN D /\ a6 IN D /\ a13 IN D /\ a14 IN D
     ==> (holds D E ((14|->a14)((13|->a13)((6|->a6)((0|->a0)((3|->a3)v)))))
            (opair_form 3 0 16 && firstsel_fm && ebv_in_form 13 3 15 1 &&
             bmeet_form 1 2 13 6 14 && opair_form 0 14 20)
          <=>
          eopair D E a3 a0 (v 16) /\
          holds D E ((14|->a14)((13|->a13)((6|->a6)((0|->a0)((3|->a3)v)))))
                firstsel_fm /\
          ebv_in D E (v 2) (v 1) a3 (v 15) a13 /\
          emeet D E (v 2) (v 1) a13 a6 a14 /\
          eopair D E a0 a14 (v 20))`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN
   `valuation D
    ((14|->a14)((13|->a13)((6|->a6)((0|->a0)((3|->a3)(v:num->A))))))`
   ASSUME_TAC THENL [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
  ASM_SIMP_TAC[HOLDS_AND; HOLDS_OPAIR_FORM; HOLDS_EBV_IN_FORM;
               HOLDS_BMEET_FORM] THEN
  REWRITE_TAC[VALMOD; ARITH_EQ]);;

let PHI_C_HOLDS = prove
 (`!D (E:A->A->bool) v.
     model D E ZF_AX /\ valuation D v
     ==> (holds D E v phi_c <=>
          ?m p ifp imx ival.
            m IN D /\ p IN D /\ ifp IN D /\ imx IN D /\ ival IN D /\
            eopair D E m p (v 16) /\
            holds D E ((14 |-> ival)
                       ((13 |-> imx)((6 |-> ifp)((0 |-> p)((3 |-> m) v)))))
                  firstsel_fm /\
            ebv_in D E (v 2) (v 1) m (v 15) imx /\
            emeet D E (v 2) (v 1) imx ifp ival /\
            eopair D E p ival (v 20))`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  REWRITE_TAC[phi_c; HOLDS_EX] THEN
  EQ_TAC THENL
   [INTRO_TAC "@a3. a3D @a0. a0D @a6. a6D @a13. a13D @a14. a14D H" THEN
    MAP_EVERY EXISTS_TAC [`a3:A`;`a0:A`;`a6:A`;`a13:A`;`a14:A`] THEN
    MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`v:num->A`;
                   `a3:A`;`a0:A`;`a6:A`;`a13:A`;`a14:A`] PHI_C_BODY) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> USE_THEN "H" (fun h -> ASSUME_TAC(EQ_MP th h))) THEN
    ASM_REWRITE_TAC[];
    DISCH_THEN(X_CHOOSE_THEN `m:A` (X_CHOOSE_THEN `p:A` (X_CHOOSE_THEN `ifp:A`
      (X_CHOOSE_THEN `imx:A` (X_CHOOSE_THEN `ival:A` STRIP_ASSUME_TAC))))) THEN
    EXISTS_TAC `m:A` THEN CONJ_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    EXISTS_TAC `p:A` THEN CONJ_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    EXISTS_TAC `ifp:A` THEN CONJ_TAC THENL
    [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    EXISTS_TAC `imx:A` THEN CONJ_TAC THENL
    [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    EXISTS_TAC `ival:A` THEN CONJ_TAC THENL
    [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`v:num->A`;
                   `m:A`;`p:A`;`ifp:A`;`imx:A`;`ival:A`] PHI_C_BODY) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN SUBST1_TAC THEN ASM_REWRITE_TAC[]]);;

let PHI_C_DEST = prove
 (`!D (E:A->A->bool) v u w.
      model D E ZF_AX /\ valuation D v /\ u IN D /\ w IN D /\
      holds D E ((20 |-> w) ((16 |-> u) v)) phi_c
      ==> ?m p ifp imx ival.
            m IN D /\ p IN D /\ ifp IN D /\ imx IN D /\ ival IN D /\
            eopair D E m p u /\
            holds D E ((14 |-> ival)
                       ((13 |-> imx)((6 |-> ifp)((0 |-> p)((3 |-> m)
                       ((20 |-> w)((16 |-> u) v))))))) firstsel_fm /\
            ebv_in D E (v 2) (v 1) m (v 15) imx /\
            emeet D E (v 2) (v 1) imx ifp ival /\
            eopair D E p ival w`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `valuation D ((20 |-> w) ((16 |-> u) (v:num->A)))`
    ASSUME_TAC THENL
   [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;
                 `(20 |-> w) ((16 |-> u) (v:num->A))`] PHI_C_HOLDS) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  REWRITE_TAC[VALMOD; ARITH_EQ] THEN
  DISCH_THEN(fun th -> FIRST_ASSUM(fun h -> ACCEPT_TAC(EQ_MP th h))));;

let PHI_C_UNIQUE = prove
 (`!D (E:A->A->bool) B leq v u w w'.
      model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
      valuation D v /\ v 1 = leq /\ v 2 = B /\
      u IN D /\ w IN D /\ w' IN D /\
      holds D E ((20 |-> w) ((16 |-> u) v)) phi_c /\
      holds D E ((20 |-> w') ((16 |-> u) v)) phi_c
      ==> w = w'`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `eporder D (E:A->A->bool) B leq` ASSUME_TAC THENL
   [ASM_MESON_TAC[ECBA_IMP_BALG; EBALG_IMP_PORDER]; ALL_TAC] THEN
  SUBGOAL_THEN `(v:num->A) 15 IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[valuation]; ALL_TAC] THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`v:num->A`;`u:A`;`w:A`]
         PHI_C_DEST) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `m:A` (X_CHOOSE_THEN `p:A` (X_CHOOSE_THEN `ifp:A`
    (X_CHOOSE_THEN `imx:A` (X_CHOOSE_THEN `ival:A` STRIP_ASSUME_TAC))))) THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`v:num->A`;`u:A`;`w':A`]
         PHI_C_DEST) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `m':A` (X_CHOOSE_THEN `p':A` (X_CHOOSE_THEN `ifp':A`
    (X_CHOOSE_THEN `imx':A` (X_CHOOSE_THEN `ival':A` STRIP_ASSUME_TAC))))) THEN
  SUBGOAL_THEN `m:A = m' /\ p:A = p'` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[EOPAIR_INJ]; ALL_TAC] THEN
  SUBGOAL_THEN `imx:A = imx'` ASSUME_TAC THENL
   [ASM_MESON_TAC[EBV_IN_UNIQUE]; ALL_TAC] THEN
  SUBGOAL_THEN `ifp:A = ifp'` ASSUME_TAC THENL
   [MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
      `(14 |-> ival)((13 |-> imx)((6 |-> ifp)((0 |-> p)((3 |-> m)
         ((20 |-> w)((16 |-> u)(v:num->A)))))))`;
      `(14 |-> ival')((13 |-> imx')((6 |-> ifp')((0 |-> p')((3 |-> m')
         ((20 |-> w')((16 |-> u)(v:num->A)))))))`] FIRSTSEL_UNIQUE_GEN) THEN
    ANTS_TAC THENL
     [REWRITE_TAC[VALMOD; ARITH_EQ] THEN ASM_REWRITE_TAC[] THEN
      CONJ_TAC THEN ASM_MESON_TAC[VALUATION_VALMOD];
      DISCH_THEN(fun th -> REWRITE_TAC[REWRITE_RULE[VALMOD; ARITH_EQ] th])];
    ALL_TAC] THEN
  SUBGOAL_THEN `ival:A = ival'` ASSUME_TAC THENL
   [ASM_MESON_TAC[EMEET_UNIQUE]; ALL_TAC] THEN
  ASM_MESON_TAC[EOPAIR_UNIQUE]);;

let PHI_C_EXISTS = prove
 (`!D (E:A->A->bool) B leq ra dm x m p u v.
      model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
      m IN D /\ p IN D /\ x IN D /\ dm IN D /\ ra IN D /\ u IN D /\
      bname D E B m /\ bname D E B p /\ bname D E B x /\
      (!q. q IN D /\ E q dm ==> bname D E B q) /\
      valuation D v /\ v 1 = leq /\ v 2 = B /\ v 4 = ra /\
        v 5 = dm /\ v 15 = x /\
      eopair D E m p u
      ==> ?w. w IN D /\ holds D E ((20 |-> w)((16 |-> u) v)) phi_c`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `ebalg D (E:A->A->bool) B leq` ASSUME_TAC THENL
   [ASM_MESON_TAC[ECBA_IMP_BALG]; ALL_TAC] THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`m:A`;`x:A`]
    EBV_IN_VAL_EXISTS) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `imx:A` STRIP_ASSUME_TAC) THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`m:A`;`dm:A`;`ra:A`;
                 `(3 |-> m)((0 |-> p)((16 |-> u)(v:num->A)))`]
      FIRSTSEL_EXISTS) THEN
  ANTS_TAC THENL
   [REWRITE_TAC[VALMOD; ARITH_EQ] THEN ASM_REWRITE_TAC[] THEN
    REPEAT CONJ_TAC THEN ASM_MESON_TAC[VALUATION_VALMOD];
    ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `ifp:A` STRIP_ASSUME_TAC) THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`imx:A`;`ifp:A`]
    EBALG_MEET) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `ival:A` ASSUME_TAC) THEN
  SUBGOAL_THEN `ival:A IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[EMEET_IN]; ALL_TAC] THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`p:A`;`ival:A`] EOPAIR_EXISTS) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `w:A` ASSUME_TAC) THEN
  SUBGOAL_THEN `w:A IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[EOPAIR_IN]; ALL_TAC] THEN
  EXISTS_TAC `w:A` THEN ASM_REWRITE_TAC[] THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`(20 |-> w)((16 |-> u)(v:num->A))`]
    PHI_C_HOLDS) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
  DISCH_THEN SUBST1_TAC THEN
  REWRITE_TAC[VALMOD; ARITH_EQ] THEN
  MAP_EVERY EXISTS_TAC [`m:A`;`p:A`;`ifp:A`;`imx:A`;`ival:A`] THEN
  ASM_REWRITE_TAC[] THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;
    `(6 |-> ifp)((3 |-> m)((0 |-> p)((16 |-> u)(v:num->A))))`;
    `(14 |-> ival)((13 |-> imx)((6 |-> ifp)((0 |-> p)((3 |-> m)
        ((20 |-> w)((16 |-> u)(v:num->A)))))))`] FIRSTSEL_HOLDS_AGREE) THEN
  ANTS_TAC THENL
   [REWRITE_TAC[VALMOD; ARITH_EQ] THEN ASM_REWRITE_TAC[] THEN
    REPEAT CONJ_TAC THEN ASM_MESON_TAC[VALUATION_VALMOD];
    DISCH_THEN(fun th -> FIRST_ASSUM(fun h -> ACCEPT_TAC(EQ_MP th h)))]);;

(* ===================================================================== *)
(* V^B CHOICE axiom (9th ZFC axiom) -- lemma C-C part 3 / C-D scaffolding: *)
(* the double-domain index (W, DD), the multivalued value-graph g via     *)
(* phi_c, and the funcval_fm functionalization layer c(p)=elub(section g). *)
(* ===================================================================== *)

(* ---- CGRAPH_EXISTS: the multivalued value-graph                          *)
(*   g = { <p, [[m in x]] MEET first(m,p)> : <m,p> in DD }                   *)
(* via ZF_REPLACEMENT along phi_c (functional per-input by PHI_C_UNIQUE,     *)
(* nonempty per-input by PHI_C_EXISTS).  g is NOT a bname (multivalued in    *)
(* p); it is the VALUE LAYER, functionalized by funcval_fm below.           *)
let CGRAPH_EXISTS = prove
 (`!D (E:A->A->bool) B leq ra W x DD v.
      model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
      x IN D /\ bname D E B x /\ W IN D /\ ra IN D /\ DD IN D /\
      (!q. q IN D /\ E q W ==> bname D E B q) /\
      (!u. u IN D /\ E u DD
           ==> ?m p. m IN D /\ p IN D /\ bname D E B m /\ bname D E B p /\
                     eopair D E m p u) /\
      valuation D v /\ v 1 = leq /\ v 2 = B /\ v 4 = ra /\ v 5 = W /\ v 15 = x
      ==> ?c. c IN D /\
              !w. w IN D
                  ==> (E w c <=>
                       ?u. u IN D /\ E u DD /\
                           holds D E ((20 |-> w)((16 |-> u) v)) phi_c)`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`] ZF_REPLACEMENT) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(MP_TAC o SPECL
    [`phi_c`; `16`; `20`; `v:num->A`; `DD:A`]) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[ARITH_EQ] THEN
    X_GEN_TAC `u:A` THEN STRIP_TAC THEN
    SUBGOAL_THEN
     `?m p:A. m IN D /\ p IN D /\ bname D E B m /\ bname D E B p /\
              eopair D E m p u`
     STRIP_ASSUME_TAC THENL
     [FIRST_ASSUM MATCH_MP_TAC THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`ra:A`;`W:A`;`x:A`;
                   `m:A`;`p:A`;`u:A`;`v:num->A`] PHI_C_EXISTS) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(X_CHOOSE_THEN `w0:A` STRIP_ASSUME_TAC) THEN
    EXISTS_TAC `w0:A` THEN ASM_REWRITE_TAC[] THEN
    X_GEN_TAC `w':A` THEN STRIP_TAC THEN
    ASM_MESON_TAC[PHI_C_UNIQUE];
    ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `c:A` STRIP_ASSUME_TAC) THEN
  EXISTS_TAC `c:A` THEN ASM_REWRITE_TAC[]);;

(* ===================================================================== *)
(* CHOICE: funcval_fm functionalizes the c-graph g by                      *)
(* reading g's SECTION at p and taking its elub:                           *)
(*     c(p) = elub { b : <p,b> in g }.                                     *)
(* Slot map (free vars): 16=p(input), 15=g(param), 1=leq, 2=B, 6=val(out). *)
(* Bound: 7=VS(section set), 8=b, 9=pair<p,b>.                             *)
(* ===================================================================== *)

let funcval_fm = new_definition
 `funcval_fm =
    ?? 7 (
      (!! 8 ((8 %% 7) <-> (?? 9 (opair_form 16 8 9 && (9 %% 15))))) &&
      elub_form 2 1 7 6 )`;;

(* Atomic body of the section comprehension, under binders 8 (=b) and       *)
(* 9 (=pair).                                                               *)
let FUNCVAL_ATOM = prove
 (`!D (E:A->A->bool) vv a apr.
     model D E ZF_AX /\ valuation D vv /\ a IN D /\ apr IN D
     ==> (holds D E ((9|->apr)((8|->a)vv)) (opair_form 16 8 9 && (9 %% 15))
          <=> eopair D E (vv 16) a apr /\ E apr (vv 15))`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `valuation D ((9|->apr)((8|->a)(vv:num->A)))` ASSUME_TAC THENL
   [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
  ASM_SIMP_TAC[HOLDS_AND; HOLDS_OPAIR_FORM; HOLDS_MEM] THEN
  REWRITE_TAC[VALMOD; ARITH_EQ]);;

(* The section comprehension  !!8 (8%%7 <-> ??9(opair 16 8 9 && 9%%15))     *)
(* characterizes slot 7 (=VS) as the section {b : <p,b> in g}.              *)
let FUNCVAL_COMP = prove
 (`!D (E:A->A->bool) vv.
     model D E ZF_AX /\ valuation D vv
     ==> (holds D E vv
            (!! 8 ((8 %% 7) <-> (?? 9 (opair_form 16 8 9 && (9 %% 15)))))
          <=> (!b. b IN D ==> (E b (vv 7) <=>
                ?pr. pr IN D /\ eopair D E (vv 16) b pr /\ E pr (vv 15))))`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  ASM_SIMP_TAC[HOLDS_ALL] THEN
  REWRITE_TAC[HOLDS_IFF; HOLDS_MEM; HOLDS_EX] THEN
  REWRITE_TAC[VALMOD; ARITH_EQ] THEN
  ASM_MESON_TAC[FUNCVAL_ATOM]);;

(* The conjunctive body under the single binder 7 (=VS).                    *)
let FUNCVAL_CONJ = prove
 (`!D (E:A->A->bool) v a7.
     model D E ZF_AX /\ valuation D v /\ a7 IN D
     ==> (holds D E ((7|->a7)v)
            ((!! 8 ((8 %% 7) <-> (?? 9 (opair_form 16 8 9 && (9 %% 15))))) &&
             elub_form 2 1 7 6)
          <=>
          (!b. b IN D ==> (E b a7 <=>
                ?pr. pr IN D /\ eopair D E (v 16) b pr /\ E pr (v 15))) /\
          elub D E (v 2) (v 1) a7 (v 6))`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `valuation D ((7|->a7)(v:num->A))` ASSUME_TAC THENL
   [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
  ASM_SIMP_TAC[HOLDS_AND; HOLDS_ELUB_FORM] THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`(7|->a7)(v:num->A)`]
         FUNCVAL_COMP) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN SUBST1_TAC THEN
  REWRITE_TAC[VALMOD; ARITH_EQ]);;

(* Full holds-characterization of funcval_fm.                               *)
let FUNCVAL_HOLDS = prove
 (`!D (E:A->A->bool) v.
     model D E ZF_AX /\ valuation D v
     ==> (holds D E v funcval_fm <=>
          ?VS. VS IN D /\
               (!b. b IN D ==> (E b VS <=>
                     ?pr. pr IN D /\ eopair D E (v 16) b pr /\ E pr (v 15))) /\
               elub D E (v 2) (v 1) VS (v 6))`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  REWRITE_TAC[funcval_fm; HOLDS_EX] THEN
  EQ_TAC THENL
   [DISCH_THEN(X_CHOOSE_THEN `a7:A` (CONJUNCTS_THEN2 ASSUME_TAC MP_TAC)) THEN
    MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`v:num->A`;`a7:A`]
           FUNCVAL_CONJ) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN SUBST1_TAC THEN STRIP_TAC THEN
    EXISTS_TAC `a7:A` THEN ASM_REWRITE_TAC[];
    DISCH_THEN(X_CHOOSE_THEN `VS:A` STRIP_ASSUME_TAC) THEN
    EXISTS_TAC `VS:A` THEN CONJ_TAC THENL
    [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`v:num->A`;`VS:A`]
           FUNCVAL_CONJ) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN SUBST1_TAC THEN ASM_REWRITE_TAC[]]);;

(* Existence of the funcval output: given the graph g (with 2nd coords in B  *)
(* on the p-section), build VS = section via ZF_SEPARATION on B, sup via     *)
(* ECBA_SUP, run FUNCVAL_HOLDS backwards.                                    *)
let FUNCVAL_EXISTS = prove
 (`!D (E:A->A->bool) B leq g v.
      model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
      g IN D /\ valuation D v /\ v 1 = leq /\ v 2 = B /\ v 15 = g /\
      (!b pr. b IN D /\ pr IN D /\ eopair D E (v 16) b pr /\ E pr g ==> E b B)
      ==> ?val. val IN D /\ E val B /\ holds D E ((6 |-> val) v) funcval_fm`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`] ZF_SEPARATION) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(MP_TAC o SPECL
    [`?? 9 (opair_form 16 8 9 && (9 %% 15))`;`8`;`v:num->A`;`B:A`]) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `s:A`
             (CONJUNCTS_THEN2 ASSUME_TAC (LABEL_TAC "sdef"))) THEN
  SUBGOAL_THEN
   `!z:A. z IN D ==> (E z s <=>
        ?apr. apr IN D /\ eopair D E ((v:num->A) 16) z apr /\ E apr g)`
   (LABEL_TAC "sec") THENL
   [X_GEN_TAC `z:A` THEN DISCH_THEN(LABEL_TAC "zin") THEN
    USE_THEN "sdef" (fun sd -> USE_THEN "zin" (fun zi ->
      SUBST1_TAC(MP (SPEC `z:A` sd) zi))) THEN
    SUBGOAL_THEN
     `holds D E ((8|->z)(v:num->A)) (?? 9 (opair_form 16 8 9 && (9 %% 15)))
      <=> ?apr. apr IN D /\ eopair D E ((v:num->A) 16) z apr /\ E apr g`
     SUBST1_TAC THENL
     [REWRITE_TAC[HOLDS_EX] THEN ASM_MESON_TAC[FUNCVAL_ATOM]; ALL_TAC] THEN
    EQ_TAC THENL
     [MESON_TAC[];
      DISCH_TAC THEN ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[]]; ALL_TAC] THEN
  SUBGOAL_THEN `esubset D (E:A->A->bool) s B` ASSUME_TAC THENL
   [REWRITE_TAC[esubset] THEN X_GEN_TAC `w:A` THEN STRIP_TAC THEN
    ASM_MESON_TAC[]; ALL_TAC] THEN
  REMOVE_THEN "sdef" (K ALL_TAC) THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`s:A`] ECBA_SUP) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `val:A` ASSUME_TAC) THEN
  SUBGOAL_THEN `(val:A) IN D /\ (E:A->A->bool) val B` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[ELUB_IN]; ALL_TAC] THEN
  EXISTS_TAC `val:A` THEN ASM_REWRITE_TAC[] THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`(6 |-> (val:A)) (v:num->A)`]
    FUNCVAL_HOLDS) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[] THEN MATCH_MP_TAC VALUATION_VALMOD THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  DISCH_THEN SUBST1_TAC THEN
  EXISTS_TAC `s:A` THEN REWRITE_TAC[VALMOD; ARITH_EQ] THEN
  REPEAT CONJ_TAC THENL
   [FIRST_ASSUM ACCEPT_TAC;
    X_GEN_TAC `b:A` THEN DISCH_TAC THEN
    REMOVE_THEN "sec" (fun th -> MP_TAC(SPEC `b:A` th)) THEN
    ASM_REWRITE_TAC[] THEN DISCH_THEN SUBST1_TAC THEN ASM_REWRITE_TAC[];
    ASM_REWRITE_TAC[]]);;

(* Destructor. *)
let FUNCVAL_DEST = prove
 (`!D (E:A->A->bool) B leq v val.
      model D E ZF_AX /\ valuation D v /\ v 1 = leq /\ v 2 = B /\ val IN D /\
      holds D E ((6 |-> val) v) funcval_fm
      ==> ?VS. VS IN D /\
               (!b. b IN D ==> (E b VS <=>
                     ?pr. pr IN D /\ eopair D E (v 16) b pr /\ E pr (v 15))) /\
               elub D E B leq VS val`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`(6 |-> (val:A)) (v:num->A)`]
    FUNCVAL_HOLDS) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[] THEN MATCH_MP_TAC VALUATION_VALMOD THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  REWRITE_TAC[VALMOD; ARITH_EQ] THEN ASM_REWRITE_TAC[] THEN
  DISCH_THEN ACCEPT_TAC);;

(* ===================================================================== *)
(* CHOICE: phi_func / CSEL existence layer.                               *)
(* Functionalizes the multivalued value-graph g (CGRAPH_EXISTS) into a    *)
(* single-valued selector name c via funcval_fm, then packages c as a     *)
(* genuine bname.  phi_func = ??6 (funcval_fm && opair_form 16 6 20):      *)
(*   16=p(input), 20=<p,c(p)>(output), 6=c(p)(bound), params 15=g,2=B,1=leq*)
(* ===================================================================== *)

(* Valuation-agreement for funcval_fm: its holds depends only on the      *)
(* slots 1,2,6,15,16, so any two valuations agreeing there agree on it.   *)
let FUNCVAL_AGREE = prove
 (`!D (E:A->A->bool) v v'.
     model D E ZF_AX /\ valuation D v /\ valuation D v' /\
     v 16 = v' 16 /\ v 15 = v' 15 /\ v 2 = v' 2 /\ v 1 = v' 1 /\ v 6 = v' 6
     ==> (holds D E v funcval_fm <=> holds D E v' funcval_fm)`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`v:num->A`] FUNCVAL_HOLDS) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN DISCH_THEN SUBST1_TAC THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`v':num->A`] FUNCVAL_HOLDS) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN DISCH_THEN SUBST1_TAC THEN
  ASM_REWRITE_TAC[]);;

let phi_func = new_definition
 `phi_func = ?? 6 (funcval_fm && opair_form 16 6 20)`;;

let PHI_FUNC_HOLDS = prove
 (`!D (E:A->A->bool) v.
     model D E ZF_AX /\ valuation D v
     ==> (holds D E v phi_func <=>
          ?val. val IN D /\ holds D E ((6 |-> val) v) funcval_fm /\
                eopair D E (v 16) val (v 20))`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  REWRITE_TAC[phi_func; HOLDS_EX] THEN
  EQ_TAC THENL
   [DISCH_THEN(X_CHOOSE_THEN `a:A` (CONJUNCTS_THEN2 ASSUME_TAC MP_TAC)) THEN
    SUBGOAL_THEN `valuation D ((6|->a)(v:num->A))` ASSUME_TAC THENL
     [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
    ASM_SIMP_TAC[HOLDS_AND; HOLDS_OPAIR_FORM] THEN
    REWRITE_TAC[VALMOD; ARITH_EQ] THEN STRIP_TAC THEN
    EXISTS_TAC `a:A` THEN ASM_REWRITE_TAC[];
    DISCH_THEN(X_CHOOSE_THEN `a:A` STRIP_ASSUME_TAC) THEN
    EXISTS_TAC `a:A` THEN
    SUBGOAL_THEN `valuation D ((6|->a)(v:num->A))` ASSUME_TAC THENL
     [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
    ASM_SIMP_TAC[HOLDS_AND; HOLDS_OPAIR_FORM] THEN
    REWRITE_TAC[VALMOD; ARITH_EQ] THEN ASM_REWRITE_TAC[]]);;

let PHI_FUNC_DEST = prove
 (`!D (E:A->A->bool) v u w.
     model D E ZF_AX /\ valuation D v /\ u IN D /\ w IN D /\
     holds D E ((20 |-> w)((16 |-> u) v)) phi_func
     ==> ?val. val IN D /\
               holds D E ((6 |-> val)((20 |-> w)((16 |-> u) v))) funcval_fm /\
               eopair D E u val w`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `valuation D ((20|->w)((16|->u)(v:num->A)))` ASSUME_TAC THENL
   [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`(20|->w)((16|->u)(v:num->A))`]
    PHI_FUNC_HOLDS) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(fun th ->
    MP_TAC(EQ_MP th
           (ASSUME `holds D E ((20|->w)((16|->u)(v:num->A))) phi_func`))) THEN
  REWRITE_TAC[VALMOD; ARITH_EQ] THEN
  DISCH_THEN(X_CHOOSE_THEN `val:A` STRIP_ASSUME_TAC) THEN
  EXISTS_TAC `val:A` THEN ASM_REWRITE_TAC[]);;

let PHI_FUNC_UNIQUE = prove
 (`!D (E:A->A->bool) B leq v u w w'.
     model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
     valuation D v /\ v 1 = leq /\ v 2 = B /\
     u IN D /\ w IN D /\ w' IN D /\
     holds D E ((20 |-> w)((16 |-> u) v)) phi_func /\
     holds D E ((20 |-> w')((16 |-> u) v)) phi_func
     ==> w = w'`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `eporder D (E:A->A->bool) B leq` ASSUME_TAC THENL
   [ASM_MESON_TAC[ECBA_IMP_BALG; EBALG_IMP_PORDER]; ALL_TAC] THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`v:num->A`;`u:A`;`w:A`]
         PHI_FUNC_DEST) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `val:A` STRIP_ASSUME_TAC) THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`v:num->A`;`u:A`;`w':A`]
         PHI_FUNC_DEST) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `val':A` STRIP_ASSUME_TAC) THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
     `(20|->w)((16|->u)(v:num->A))`;`val:A`] FUNCVAL_DEST) THEN
  ANTS_TAC THENL
   [REWRITE_TAC[VALMOD; ARITH_EQ] THEN ASM_REWRITE_TAC[] THEN
    ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `VS:A` STRIP_ASSUME_TAC) THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
     `(20|->w')((16|->u)(v:num->A))`;`val':A`] FUNCVAL_DEST) THEN
  ANTS_TAC THENL
   [REWRITE_TAC[VALMOD; ARITH_EQ] THEN ASM_REWRITE_TAC[] THEN
    ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `VS':A` STRIP_ASSUME_TAC) THEN
  RULE_ASSUM_TAC(REWRITE_RULE[VALMOD; ARITH_EQ]) THEN
  SUBGOAL_THEN `VS:A = VS'` SUBST_ALL_TAC THENL
   [FIRST_ASSUM(MATCH_MP_TAC o MATCH_MP ZF_EXTENSIONALITY) THEN
    ASM_REWRITE_TAC[] THEN X_GEN_TAC `z:A` THEN DISCH_TAC THEN
    ASM_MESON_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `val:A = val'` SUBST_ALL_TAC THENL
   [ASM_MESON_TAC[ELUB_UNIQUE]; ALL_TAC] THEN
  ASM_MESON_TAC[EOPAIR_UNIQUE]);;

let PHI_FUNC_EXISTS = prove
 (`!D (E:A->A->bool) B leq g p v.
     model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
     g IN D /\ p IN D /\
     (!q b pr. q IN D /\ b IN D /\ pr IN D /\
               eopair D E q b pr /\ E pr g ==> E b B) /\
     valuation D v /\ v 1 = leq /\ v 2 = B /\ v 15 = g
     ==> ?w. w IN D /\ holds D E ((20 |-> w)((16 |-> p) v)) phi_func`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`g:A`;
     `(16|->p)(v:num->A)`] FUNCVAL_EXISTS) THEN
  ANTS_TAC THENL
   [REWRITE_TAC[VALMOD; ARITH_EQ] THEN ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
     [ASM_MESON_TAC[VALUATION_VALMOD]; ASM_MESON_TAC[]];
    ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `val:A` STRIP_ASSUME_TAC) THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`p:A`;`val:A`] EOPAIR_EXISTS) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `w0:A` ASSUME_TAC) THEN
  SUBGOAL_THEN `(w0:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[EOPAIR_IN]; ALL_TAC] THEN
  EXISTS_TAC `w0:A` THEN ASM_REWRITE_TAC[] THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`(20|->w0)((16|->p)(v:num->A))`]
    PHI_FUNC_HOLDS) THEN
  ANTS_TAC THENL
  [ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
  DISCH_THEN SUBST1_TAC THEN
  REWRITE_TAC[VALMOD; ARITH_EQ] THEN
  EXISTS_TAC `val:A` THEN ASM_REWRITE_TAC[] THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;
     `(6|->val)((20|->w0)((16|->p)(v:num->A)))`;
     `(6|->val)((16|->p)(v:num->A))`] FUNCVAL_AGREE) THEN
  ANTS_TAC THENL
   [REWRITE_TAC[VALMOD; ARITH_EQ] THEN ASM_REWRITE_TAC[] THEN
    CONJ_TAC THEN ASM_MESON_TAC[VALUATION_VALMOD];
    DISCH_THEN(fun th -> ONCE_REWRITE_TAC[th]) THEN ASM_REWRITE_TAC[]]);;

(* The selector name c = { <p, funcval-of-g at p> : p in W }, via         *)
(* ZF_REPLACEMENT along phi_func over the union-domain W.                  *)
let CSEL_EXISTS = prove
 (`!D (E:A->A->bool) B leq g W v.
     model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
     g IN D /\ W IN D /\
     (!q b pr. q IN D /\ b IN D /\ pr IN D /\
               eopair D E q b pr /\ E pr g ==> E b B) /\
     valuation D v /\ v 1 = leq /\ v 2 = B /\ v 15 = g
     ==> ?c. c IN D /\
             !w. w IN D
                 ==> (E w c <=>
                      ?p. p IN D /\ E p W /\
                          holds D E ((20 |-> w)((16 |-> p) v)) phi_func)`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`] ZF_REPLACEMENT) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(MP_TAC o SPECL [`phi_func`; `16`; `20`; `v:num->A`; `W:A`]) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[ARITH_EQ] THEN
    X_GEN_TAC `p:A` THEN STRIP_TAC THEN
    MP_TAC(ISPECL
           [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`g:A`;`p:A`;`v:num->A`]
           PHI_FUNC_EXISTS) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(X_CHOOSE_THEN `w0:A` STRIP_ASSUME_TAC) THEN
    EXISTS_TAC `w0:A` THEN ASM_REWRITE_TAC[] THEN
    X_GEN_TAC `w':A` THEN STRIP_TAC THEN
    ASM_MESON_TAC[PHI_FUNC_UNIQUE];
    ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `c:A` STRIP_ASSUME_TAC) THEN
  EXISTS_TAC `c:A` THEN ASM_REWRITE_TAC[]);;

let CSEL_EISFUN = prove
 (`!D (E:A->A->bool) B leq W v c.
     model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
     valuation D v /\ v 1 = leq /\ v 2 = B /\ W IN D /\ c IN D /\
     (!w. w IN D ==> (E w c <=>
             ?p. p IN D /\ E p W /\
                 holds D E ((20 |-> w)((16 |-> p) v)) phi_func))
     ==> eisfun D E c`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "modl ecba BD leqD val v1 v2 WD cD cch" THEN
  REWRITE_TAC[eisfun] THEN
  CONJ_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  CONJ_TAC THENL
   [X_GEN_TAC `z:A` THEN STRIP_TAC THEN
    USE_THEN "cch" (MP_TAC o SPEC `z:A`) THEN
    ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN(fun th -> MP_TAC(EQ_MP th (ASSUME `(E:A->A->bool) z c`))) THEN
    DISCH_THEN(X_CHOOSE_THEN `p:A` STRIP_ASSUME_TAC) THEN
    MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`v:num->A`;`p:A`;`z:A`]
           PHI_FUNC_DEST) THEN
    ASM_REWRITE_TAC[] THEN
    DISCH_THEN(X_CHOOSE_THEN `val:A` STRIP_ASSUME_TAC) THEN
    MAP_EVERY EXISTS_TAC [`p:A`;`val:A`] THEN ASM_REWRITE_TAC[];
    MAP_EVERY X_GEN_TAC [`u:A`;`w:A`;`w':A`;`z:A`;`z':A`] THEN STRIP_TAC THEN
    SUBGOAL_THEN `(z:A) IN D /\ (z':A) IN D` STRIP_ASSUME_TAC THENL
     [ASM_MESON_TAC[EOPAIR_IN]; ALL_TAC] THEN
    USE_THEN "cch" (MP_TAC o SPEC `z:A`) THEN
    ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN(fun th -> MP_TAC(EQ_MP th (ASSUME `(E:A->A->bool) z c`))) THEN
    DISCH_THEN(X_CHOOSE_THEN `p1:A` STRIP_ASSUME_TAC) THEN
    MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`v:num->A`;`p1:A`;`z:A`]
           PHI_FUNC_DEST) THEN
    ASM_REWRITE_TAC[] THEN
    DISCH_THEN(X_CHOOSE_THEN `val1:A` STRIP_ASSUME_TAC) THEN
    SUBGOAL_THEN `p1:A = u` SUBST_ALL_TAC THENL
     [ASM_MESON_TAC[EOPAIR_INJ]; ALL_TAC] THEN
    USE_THEN "cch" (MP_TAC o SPEC `z':A`) THEN
    ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN(fun th -> MP_TAC(EQ_MP th (ASSUME `(E:A->A->bool) z' c`))) THEN
    DISCH_THEN(X_CHOOSE_THEN `p2:A` STRIP_ASSUME_TAC) THEN
    MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`v:num->A`;`p2:A`;`z':A`]
           PHI_FUNC_DEST) THEN
    ASM_REWRITE_TAC[] THEN
    DISCH_THEN(X_CHOOSE_THEN `val2:A` STRIP_ASSUME_TAC) THEN
    SUBGOAL_THEN `p2:A = u` SUBST_ALL_TAC THENL
     [ASM_MESON_TAC[EOPAIR_INJ]; ALL_TAC] THEN
    SUBGOAL_THEN `z:A = z'` SUBST_ALL_TAC THENL
     [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`v:num->A`;
        `u:A`;`z:A`;`z':A`] PHI_FUNC_UNIQUE) THEN ASM_REWRITE_TAC[];
           ALL_TAC] THEN
    ASM_MESON_TAC[EOPAIR_INJ]]);;

(* c is a genuine bname: mirror EUNIONNAME_BNAME, with the inner value     *)
(* step via PHI_FUNC_DEST + FUNCVAL_DEST/ELUB_IN (2nd coord in B).         *)
let CSEL_BNAME = prove
 (`!D (E:A->A->bool) B leq x W v c.
     model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
     x IN D /\ bname D E B x /\ W IN D /\
     (!t. t IN D
          ==> (E t W <=> ?w. w IN D /\ eindom D E x w /\ eindom D E w t)) /\
     valuation D v /\ v 1 = leq /\ v 2 = B /\
     c IN D /\ eisfun D E c /\
     (!w. w IN D ==> (E w c <=>
             ?p. p IN D /\ E p W /\
                 holds D E ((20 |-> w)((16 |-> p) v)) phi_func))
     ==> bname D E B c`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "modl ecba BD leqD xD bnx WD Wch val v1 v2 cD isf cch" THEN
  USE_THEN "bnx"
    (X_CHOOSE_THEN `ax:A` (X_CHOOSE_THEN `yx:A` STRIP_ASSUME_TAC) o
     REWRITE_RULE[bname]) THEN
  SUBGOAL_THEN `!s:A. s IN D /\ (E:A->A->bool) s W ==> E s yx`
    (LABEL_TAC "Wsub") THENL
   [X_GEN_TAC `s:A` THEN STRIP_TAC THEN
    SUBGOAL_THEN `?w. w IN D /\ eindom D (E:A->A->bool) x w /\ eindom D E w s`
    STRIP_ASSUME_TAC THENL
     [USE_THEN "Wch" (MP_TAC o SPEC `s:A`) THEN
      ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[GSYM th]) THEN FIRST_ASSUM ACCEPT_TAC;
      ALL_TAC] THEN
    UNDISCH_TAC `eindom D (E:A->A->bool) x w` THEN REWRITE_TAC[eindom] THEN
    DISCH_THEN(X_CHOOSE_THEN `qw:A` STRIP_ASSUME_TAC) THEN
    UNDISCH_TAC `eindom D (E:A->A->bool) w s` THEN REWRITE_TAC[eindom] THEN
    DISCH_THEN(X_CHOOSE_THEN `qs:A` STRIP_ASSUME_TAC) THEN
    SUBGOAL_THEN `(E:A->A->bool) w yx` ASSUME_TAC THENL
     [MATCH_MP_TAC(ISPECL
                   [`D:A->bool`;`E:A->A->bool`;`B:A`;`ax:A`;`yx:A`;`x:A`;
                    `w:A`;`qw:A`] STAGE_DOM_CLOSED) THEN ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`ax:A`;`yx:A`;`w:A`;
      `s:A`;`qs:A`] STAGE_DOM_CLOSED) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`ax:A`] ESUC_EXISTS) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `sa:A`) THEN
  SUBGOAL_THEN
    `(sa:A) IN D /\ eordinal D (E:A->A->bool) sa /\ (E:A->A->bool) ax sa`
  STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[ESUC_IN; EORDINAL_ESUC; ESUC_MEMBER]; ALL_TAC] THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`sa:A`] EBNSTAGE_EXISTS) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `ysa:A` STRIP_ASSUME_TAC) THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`sa:A`;`ysa:A`]
         EBNSTAGE_CHAR) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `w1:A` (CONJUNCTS_THEN2 ASSUME_TAC
    (CONJUNCTS_THEN2 (LABEL_TAC "w1ch") ASSUME_TAC))) THEN
  SUBGOAL_THEN `!u:A. u IN D /\ (E:A->A->bool) u yx ==> E u w1`
    (LABEL_TAC "Ysub") THENL
   [X_GEN_TAC `u:A` THEN STRIP_TAC THEN
    USE_THEN "w1ch" (MP_TAC o SPEC `u:A`) THEN
    ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    MAP_EVERY EXISTS_TAC [`ax:A`;`yx:A`] THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`w1:A`;`B:A`] ECROSS_EXISTS) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `cr:A` (LABEL_TAC "cr")) THEN
  SUBGOAL_THEN `(cr:A) IN D` ASSUME_TAC THENL
   [USE_THEN "cr" (MP_TAC o REWRITE_RULE[ecross]) THEN SIMP_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `esubset D (E:A->A->bool) c cr` ASSUME_TAC THENL
   [REWRITE_TAC[esubset] THEN X_GEN_TAC `z:A` THEN STRIP_TAC THEN
    USE_THEN "cr" (MP_TAC o SPEC `z:A` o CONJUNCT2 o REWRITE_RULE[ecross]) THEN
    ASM_REWRITE_TAC[] THEN DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    USE_THEN "cch" (MP_TAC o SPEC `z:A`) THEN
    ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN(fun th -> MP_TAC(EQ_MP th (ASSUME `(E:A->A->bool) z c`))) THEN
    DISCH_THEN(X_CHOOSE_THEN `s:A` STRIP_ASSUME_TAC) THEN
    MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`v:num->A`;`s:A`;`z:A`]
           PHI_FUNC_DEST) THEN
    ASM_REWRITE_TAC[] THEN
    DISCH_THEN(X_CHOOSE_THEN `q:A` STRIP_ASSUME_TAC) THEN
    SUBGOAL_THEN `(E:A->A->bool) s w1` ASSUME_TAC THENL
     [USE_THEN "Ysub" MATCH_MP_TAC THEN CONJ_TAC THENL
       [FIRST_ASSUM ACCEPT_TAC;
        USE_THEN "Wsub" MATCH_MP_TAC THEN ASM_REWRITE_TAC[]]; ALL_TAC] THEN
    SUBGOAL_THEN `(E:A->A->bool) q B` ASSUME_TAC THENL
     [MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
        `(20|->z)((16|->s)(v:num->A))`;`q:A`] FUNCVAL_DEST) THEN
      ANTS_TAC THENL
       [REWRITE_TAC[VALMOD; ARITH_EQ] THEN ASM_REWRITE_TAC[] THEN
        ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
      DISCH_THEN(X_CHOOSE_THEN `VS:A` STRIP_ASSUME_TAC) THEN
      ASM_MESON_TAC[ELUB_IN]; ALL_TAC] THEN
    MAP_EVERY EXISTS_TAC [`s:A`;`q:A`] THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `ebnmem D (E:A->A->bool) B w1 c` ASSUME_TAC THENL
   [REWRITE_TAC[ebnmem] THEN ASM_REWRITE_TAC[] THEN
    EXISTS_TAC `cr:A` THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) c ysa` ASSUME_TAC THENL
   [UNDISCH_TAC `ebnfuns D (E:A->A->bool) B w1 ysa` THEN
    REWRITE_TAC[ebnfuns] THEN
    DISCH_THEN(MP_TAC o SPEC `c:A` o CONJUNCT2) THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  REWRITE_TAC[bname] THEN MAP_EVERY EXISTS_TAC [`sa:A`;`ysa:A`] THEN
  ASM_REWRITE_TAC[]);;
(* ===================================================================== *)
(* CHOICE: CSEL value characterization (C-D).                             *)
(* Three lemmas relating the selector value to Boolean membership:        *)
(*   CSEL_SECTION_GE: every g-section value ival at p is <= val = c(p)    *)
(*                    (val = elub of the section, so it dominates each).  *)
(*   CSEL_VALUE     : dual half -- for a block <m,p> in DD,               *)
(*                    [[m in x]] MEET first(m,p) <= [[p in c]].           *)
(* ===================================================================== *)

let CSEL_SECTION_GE = prove
 (`!D (E:A->A->bool) B leq g W v c p val gpair ival.
      model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
      g IN D /\ W IN D /\ valuation D v /\ v 1 = leq /\ v 2 = B /\ v 15 = g /\
      c IN D /\
      (!w. w IN D ==> (E w c <=>
              ?p. p IN D /\ E p W /\
                  holds D E ((20 |-> w)((16 |-> p) v)) phi_func)) /\
      p IN D /\ val IN D /\ eapply D E c p val /\
      gpair IN D /\ ival IN D /\ E gpair g /\ eopair D E p ival gpair
      ==> erel D E leq ival val`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  UNDISCH_TAC `eapply D (E:A->A->bool) c p val` THEN REWRITE_TAC[eapply] THEN
  DISCH_THEN(X_CHOOSE_THEN `zz:A` STRIP_ASSUME_TAC) THEN
  SUBGOAL_THEN `(zz:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[EOPAIR_IN]; ALL_TAC] THEN
  SUBGOAL_THEN
    `?pp. pp IN D /\ E pp W /\
          holds D E ((20|->zz)((16|->pp)(v:num->A))) phi_func`
    STRIP_ASSUME_TAC THENL
   [FIRST_X_ASSUM(MP_TAC o SPEC `zz:A`) THEN
    ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN(fun th -> ACCEPT_TAC(EQ_MP th (ASSUME `(E:A->A->bool) zz c`)));
    ALL_TAC] THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`v:num->A`;`pp:A`;`zz:A`]
    PHI_FUNC_DEST) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `vv:A` STRIP_ASSUME_TAC) THEN
  SUBGOAL_THEN `pp:A = p /\ vv:A = val` (CONJUNCTS_THEN SUBST_ALL_TAC) THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`pp:A`;`vv:A`;`p:A`;`val:A`;
                  `zz:A`] EOPAIR_INJ) THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
     `(20|->zz)((16|->p)(v:num->A))`;`val:A`] FUNCVAL_DEST) THEN
  ANTS_TAC THENL
   [REWRITE_TAC[VALMOD; ARITH_EQ] THEN ASM_REWRITE_TAC[] THEN
    ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `VS:A`
    (CONJUNCTS_THEN2 (LABEL_TAC "VSD")
     (CONJUNCTS_THEN2 (LABEL_TAC "VSch") (LABEL_TAC "VSlub")))) THEN
  SUBGOAL_THEN `(E:A->A->bool) ival VS` ASSUME_TAC THENL
   [USE_THEN "VSch" (MP_TAC o SPEC `ival:A`) THEN
    ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    REWRITE_TAC[VALMOD; ARITH_EQ] THEN
    EXISTS_TAC `gpair:A` THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`VS:A`;`val:A`;
     `ival:A`] ELUB_UB) THEN
  ASM_REWRITE_TAC[]);;

(* CSEL_VALUE: the c-value lower bound (C-D dual half).  For a block <m,p>   *)
(* in DD (m in dom x, p in W), the selector value at p dominates the block   *)
(* value:   [[m in x]] MEET first(m,p)  <=  [[p in c]].                      *)
(* All identification/membership steps are explicit MP_TAC(ISPECL ...) to    *)
(* avoid MESON search blowing up on the large hypothesis context.            *)
let CSEL_VALUE = prove
 (`!D (E:A->A->bool) B leq ra W x DD g c vc vf vfs m p blk fp imx ival zc.
     model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
     x IN D /\ bname D E B x /\
     W IN D /\ ra IN D /\ DD IN D /\ g IN D /\ c IN D /\
     (!q. q IN D /\ E q W ==> bname D E B q) /\
     (!q b pr. q IN D /\ b IN D /\ pr IN D /\
               eopair D E q b pr /\ E pr g ==> E b B) /\
     m IN D /\ bname D E B m /\ p IN D /\ bname D E B p /\ E p W /\
     blk IN D /\ E blk DD /\ eopair D E m p blk /\
     valuation D vc /\ vc 1 = leq /\ vc 2 = B /\ vc 4 = ra /\ vc 5 = W /\
     vc 15 = x /\
     (!w. w IN D
          ==> (E w g <=>
               ?u. u IN D /\ E u DD /\
                   holds D E ((20 |-> w)((16 |-> u) vc)) phi_c)) /\
     valuation D vf /\ vf 1 = leq /\ vf 2 = B /\ vf 15 = g /\
     (!w. w IN D
          ==> (E w c <=>
               ?pp. pp IN D /\ E pp W /\
                    holds D E ((20 |-> w)((16 |-> pp) vf)) phi_func)) /\
     bname D E B c /\
     valuation D vfs /\ vfs 0 = p /\ vfs 1 = leq /\ vfs 2 = B /\ vfs 3 = m /\
     vfs 4 = ra /\ vfs 5 = W /\ vfs 6 = fp /\ holds D E vfs firstsel_fm /\
     fp IN D /\ E fp B /\
     imx IN D /\ E imx B /\ ebv_in D E B leq m x imx /\
     ival IN D /\ emeet D E B leq imx fp ival /\
     zc IN D /\ ebv_in D E B leq p c zc
     ==> erel D E leq ival zc`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `eporder D (E:A->A->bool) B leq` ASSUME_TAC THENL
   [ASM_MESON_TAC[ECBA_IMP_BALG; EBALG_IMP_PORDER]; ALL_TAC] THEN
  (* ---- 1. block <m,p> yields w with holds phi_c ---- *)
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`ra:A`;`W:A`;`x:A`;
                 `m:A`;`p:A`;`blk:A`;`vc:num->A`] PHI_C_EXISTS) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `w:A` STRIP_ASSUME_TAC) THEN
  (* ---- 2. w in g via the graph char (backward) ---- *)
  SUBGOAL_THEN `(E:A->A->bool) w g` ASSUME_TAC THENL
   [UNDISCH_TAC
      `!w:A. w IN D ==> (E w g <=>
           ?u. u IN D /\ E u DD /\
               holds D E ((20 |-> w)((16 |-> u) vc)) phi_c)` THEN
    DISCH_THEN(MP_TAC o SPEC `w:A`) THEN ASM_REWRITE_TAC[] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    EXISTS_TAC `blk:A` THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* ---- 3. destructure phi_c at (blk,w): m2,p2,ifp,imx2,ival2 ---- *)
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`vc:num->A`;`blk:A`;`w:A`]
    PHI_C_DEST) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `m2:A` (X_CHOOSE_THEN `p2:A` (X_CHOOSE_THEN `ifp:A`
    (X_CHOOSE_THEN `imx2:A` (X_CHOOSE_THEN `ival2:A` STRIP_ASSUME_TAC))))) THEN
  (* NB: do NOT RULE_ASSUM_TAC away vc 1=leq / vc 2=B / vc 15=x -- they are  *)
  (* needed by FIRSTSEL_UNIQUE_GEN's ANTS below.  Keep the raw PHI_C_DEST    *)
  (* facts in vc-slot form and match uniqueness lemmas via vc-form ISPECL.   *)
  (* ---- 4. m2 = m, p2 = p (EOPAIR_INJ) ----                                *)
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`m2:A`;`p2:A`;`m:A`;`p:A`;`blk:A`]
    EOPAIR_INJ) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(CONJUNCTS_THEN2 SUBST_ALL_TAC SUBST_ALL_TAC) THEN
  (* ---- 5. imx2 = imx (EBV_IN_UNIQUE, vc-form) ---- *)
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`vc 2:A`;`vc 1:A`;`m:A`;`vc 15:A`;
                 `imx2:A`;`imx:A`] EBV_IN_UNIQUE) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN SUBST_ALL_TAC THEN
  (* ---- 6. ifp = fp (FIRSTSEL_UNIQUE_GEN) ---- *)
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
    `(14 |-> ival2)((13 |-> imx)((6 |-> ifp)((0 |-> p)((3 |-> m)
        ((20 |-> w)((16 |-> blk)(vc:num->A)))))))`;
    `vfs:num->A`] FIRSTSEL_UNIQUE_GEN) THEN
  ANTS_TAC THENL
   [REWRITE_TAC[VALMOD; ARITH_EQ] THEN ASM_REWRITE_TAC[] THEN
    ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
  DISCH_THEN(ASSUME_TAC o
    REWRITE_RULE[VALMOD; ARITH_EQ; ASSUME `vfs 6 = (fp:A)`]) THEN
  SUBGOAL_THEN `ifp:A = fp` SUBST_ALL_TAC THENL
   [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  (* ---- 7. ival2 = ival (EMEET_UNIQUE, vc-form) ---- *)
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`vc 2:A`;`vc 1:A`;`imx:A`;`fp:A`;
                 `ival2:A`;`ival:A`] EMEET_UNIQUE) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN SUBST_ALL_TAC THEN
  (* now: eopair D E p ival w /\ E w g ---- *)
  (* ---- 8. selector value val = c(p) ---- *)
  MP_TAC(ISPECL
         [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`g:A`;`p:A`;`vf:num->A`]
         PHI_FUNC_EXISTS) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `zz:A` STRIP_ASSUME_TAC) THEN
  SUBGOAL_THEN `(E:A->A->bool) zz c` ASSUME_TAC THENL
   [UNDISCH_TAC
      `!w:A. w IN D ==> (E w c <=>
           ?pp. pp IN D /\ E pp W /\
                holds D E ((20 |-> w)((16 |-> pp) vf)) phi_func)` THEN
    DISCH_THEN(MP_TAC o SPEC `zz:A`) THEN ASM_REWRITE_TAC[] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    EXISTS_TAC `p:A` THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`vf:num->A`;`p:A`;`zz:A`]
    PHI_FUNC_DEST) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `val:A` STRIP_ASSUME_TAC) THEN
  (* E val B via FUNCVAL_DEST + ELUB_IN *)
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
     `(20 |-> zz)((16 |-> p)(vf:num->A))`;`val:A`] FUNCVAL_DEST) THEN
  ANTS_TAC THENL
   [REWRITE_TAC[VALMOD; ARITH_EQ] THEN ASM_REWRITE_TAC[] THEN
    ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `VS:A` STRIP_ASSUME_TAC) THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`VS:A`;`val:A`]
    ELUB_IN) THEN
  ASM_REWRITE_TAC[] THEN STRIP_TAC THEN
  (* eapply c p val *)
  SUBGOAL_THEN `eapply D (E:A->A->bool) c p val` ASSUME_TAC THENL
   [REWRITE_TAC[eapply] THEN EXISTS_TAC `zz:A` THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  (* ---- 9. ival <= val  (CSEL_SECTION_GE) ---- *)
  SUBGOAL_THEN `erel D (E:A->A->bool) leq ival val` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`g:A`;`W:A`;
       `vf:num->A`;`c:A`;`p:A`;`val:A`;`w:A`;`ival:A`] CSEL_SECTION_GE) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* ---- 10. val <= zc  (EBV_MEMBER_LE_V) ---- *)
  SUBGOAL_THEN `erel D (E:A->A->bool) leq val zc` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`c:A`;`p:A`;
       `val:A`;`zc:A`] EBV_MEMBER_LE_V) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* ---- 11. membership facts for transitivity ---- *)
  SUBGOAL_THEN `(E:A->A->bool) ival B` ASSUME_TAC THENL
   [MP_TAC(ISPECL
           [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`imx:A`;`fp:A`;`ival:A`]
           EMEET_IN) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) zc B` ASSUME_TAC THENL
   [MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`p:A`;`c:A`;`zc:A`]
      EBV_IN_IN_B) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* ---- 12. transitivity: ival <= zc ---- *)
  MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
     `ival:A`;`val:A`;`zc:A`] EPORDER_TRANS) THEN
  ASM_REWRITE_TAC[]);;

(* ===== C-E domain-supremum reduction pair ===== *)
(* EBV_IN_DOMSUP_LE + NONEMPTY_DOMSUP_LE: the LEAST direction of         *)
(*   [[?w. w in m]] = sup_{p in dom m}[[p in m]].  Composes with          *)
(*   FST_SUP_GE (rhs bounds firsts ==> rhs bounds dom-values) to bound    *)
(*   [[m nonempty]] for the CHOICE EXISTENCE reduction.                   *)

(* EBV_IN_DOMSUP_LE:  if every dom-value [[p in m]] (p in dom m) is <= rhs,  *)
(* then [[a in m]] <= rhs for ANY a.  Semantic form of                       *)
(*   [[a in m]] = sup_{y in dom m} m(y)/\[[a=y]] <= sup_y m(y) <= sup_y[[y   *)
(* in m]]. Combiner discharge: c = m(y)/\[[a=y]] <= m(y) (EMEET_LE)          *)
(*   <= [[y in m]] (EBV_MEMBER_LE_V) <= rhs (dom hyp).                       *)
let EBV_IN_DOMSUP_LE = prove
 (`!D (E:A->A->bool) B leq m a z rhs.
     model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
     m IN D /\ bname D E B m /\ a IN D /\ z IN D /\
     ebv_in D E B leq a m z /\
     rhs IN D /\ E rhs B /\
     (!p bym. p IN D /\ eindom D E m p /\ bym IN D /\
              ebv_in D E B leq p m bym ==> erel D E leq bym rhs)
     ==> erel D E leq z rhs`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `eporder D (E:A->A->bool) B leq` ASSUME_TAC THENL
   [ASM_MESON_TAC[ECBA_IMP_BALG; EBALG_IMP_PORDER]; ALL_TAC] THEN
  MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
     `a:A`;`m:A`;`z:A`;`rhs:A`] EBV_IN_LE_V) THEN
  ASM_REWRITE_TAC[] THEN
  MAP_EVERY X_GEN_TAC [`y:A`;`qy:A`;`ey:A`;`c:A`] THEN STRIP_TAC THEN
  (* eindom m y *)
  SUBGOAL_THEN `eindom D (E:A->A->bool) m y` ASSUME_TAC THENL
   [REWRITE_TAC[eindom] THEN EXISTS_TAC `qy:A` THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  (* bname y *)
  SUBGOAL_THEN `bname D (E:A->A->bool) B y` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`m:A`;`y:A`]
      UNION_DOM_BNAME) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* bym := [[y in m]] exists *)
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`y:A`;`m:A`]
    EBV_IN_VAL_EXISTS) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `bym:A` STRIP_ASSUME_TAC) THEN
  (* E qy B *)
  SUBGOAL_THEN `(E:A->A->bool) qy B` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`m:A`;`y:A`;`qy:A`]
      BNAME_APPLY_IN_B) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* qy <= bym  (EBV_MEMBER_LE_V) *)
  SUBGOAL_THEN `erel D (E:A->A->bool) leq qy bym` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`m:A`;`y:A`;
       `qy:A`;`bym:A`] EBV_MEMBER_LE_V) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* bym <= rhs  (dom-bound hyp) *)
  SUBGOAL_THEN `erel D (E:A->A->bool) leq bym rhs` ASSUME_TAC THENL
   [FIRST_X_ASSUM MATCH_MP_TAC THEN EXISTS_TAC `y:A` THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  (* c <= qy  (EMEET_LE) *)
  SUBGOAL_THEN `erel D (E:A->A->bool) leq c qy` ASSUME_TAC THENL
   [MP_TAC(ISPECL
           [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`qy:A`;`ey:A`;`c:A`]
           EMEET_LE) THEN ASM_REWRITE_TAC[] THEN
    DISCH_THEN(ACCEPT_TAC o CONJUNCT1);
    ALL_TAC] THEN
  (* E c B  (EMEET_IN) *)
  SUBGOAL_THEN `(E:A->A->bool) c B` ASSUME_TAC THENL
   [MP_TAC(ISPECL
           [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`qy:A`;`ey:A`;`c:A`]
           EMEET_IN) THEN ASM_REWRITE_TAC[] THEN
    DISCH_THEN(ACCEPT_TAC o CONJUNCT2);
    ALL_TAC] THEN
  (* qy <= rhs  (trans qy,bym,rhs) *)
  SUBGOAL_THEN `erel D (E:A->A->bool) leq qy rhs` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
       `qy:A`;`bym:A`;`rhs:A`] EPORDER_TRANS) THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  (* c <= rhs  (trans c,qy,rhs) *)
  MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
     `c:A`;`qy:A`;`rhs:A`] EPORDER_TRANS) THEN ASM_REWRITE_TAC[]);;

(* NONEMPTY_DOMSUP_LE:  object-formula wrapper of the LEAST direction of     *)
(*   [[?w. w in m]] = sup_{p in dom m}[[p in m]].                            *)
(* If rhs bounds every dom-value [[p in m]] (p in dm, dm >= dom m), then     *)
(*   [[?? n (n%%j)]]_v <= rhs   (v j = m, n<>j).                             *)
(* = BVALF_EX_LEAST o EBV_IN_DOMSUP_LE o BVALF_MEM.  Composes directly with  *)
(* FST_SUP_GE's conclusion (rhs bounds firsts ==> rhs bounds dom-values).    *)
let NONEMPTY_DOMSUP_LE = prove
 (`!D (E:A->A->bool) B leq m dm n j v rhs.
     model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
     m IN D /\ bname D E B m /\ dm IN D /\
     valuation D v /\ (!i. bname D E B (v i)) /\ v j = m /\ ~(n = j) /\
     rhs IN D /\ E rhs B /\
     (!y. y IN D /\ eindom D E m y ==> E y dm) /\
     (!p z. p IN D /\ E p dm /\ z IN D /\ ebv_in D E B leq p m z
            ==> erel D E leq z rhs)
     ==> erel D E leq (bvalf D E B leq v (?? n (n %% j))) rhs`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  MATCH_MP_TAC(ISPECL
               [`n:num`;`(n %% j):form`;`D:A->bool`;`E:A->A->bool`;`B:A`;
                `leq:A`;`v:num->A`;`rhs:A`] BVALF_EX_LEAST) THEN
  ASM_REWRITE_TAC[] THEN
  X_GEN_TAC `a:A` THEN STRIP_TAC THEN
  ABBREV_TAC `va = (n |-> (a:A)) (v:num->A)` THEN
  SUBGOAL_THEN
    `valuation D (va:num->A) /\ (!i. bname D (E:A->A->bool) B (va i))`
    STRIP_ASSUME_TAC THENL
   [EXPAND_TAC "va" THEN CONJ_TAC THENL
     [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[];
      GEN_TAC THEN REWRITE_TAC[VALMOD] THEN COND_CASES_TAC THEN
      ASM_REWRITE_TAC[]];
    ALL_TAC] THEN
  SUBGOAL_THEN `(va:num->A) n = a` ASSUME_TAC THENL
   [EXPAND_TAC "va" THEN REWRITE_TAC[VALMOD]; ALL_TAC] THEN
  SUBGOAL_THEN `(va:num->A) j = m` ASSUME_TAC THENL
   [EXPAND_TAC "va" THEN REWRITE_TAC[VALMOD] THEN
    COND_CASES_TAC THENL [ASM_MESON_TAC[]; ASM_REWRITE_TAC[]]; ALL_TAC] THEN
  (* ebv_in a m z0,  z0 := bvalf va (n%%j) *)
  SUBGOAL_THEN
    `ebv_in D (E:A->A->bool) B leq a m (bvalf D E B leq (va:num->A) (n %% j))`
    ASSUME_TAC THENL
   [SUBGOAL_THEN `a = (va:num->A) n /\ m = (va:num->A) j`
      (CONJUNCTS_THEN SUBST1_TAC) THENL
     [ASM_MESON_TAC[]; ALL_TAC] THEN
    MATCH_MP_TAC(ISPECL
                 [`n:num`;`j:num`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
                  `va:num->A`] BVALF_MEM) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* z0 IN D *)
  SUBGOAL_THEN `(bvalf D (E:A->A->bool) B leq (va:num->A) (n %% j)) IN D`
    ASSUME_TAC THENL
   [MP_TAC(ISPECL [`(n %% j):form`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
       `va:num->A`] BVALF_SPEC) THEN ASM_REWRITE_TAC[] THEN
    DISCH_THEN(ACCEPT_TAC o CONJUNCT1); ALL_TAC] THEN
  (* apply EBV_IN_DOMSUP_LE *)
  MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`m:A`;`a:A`;
     `bvalf D E B leq (va:num->A) (n %% j)`;`rhs:A`] EBV_IN_DOMSUP_LE) THEN
  ASM_REWRITE_TAC[] THEN
  (* discharge eindom-form dom bound from E-p-dm bound + bridge *)
  MAP_EVERY X_GEN_TAC [`p:A`;`bym:A`] THEN STRIP_TAC THEN
  SUBGOAL_THEN `(E:A->A->bool) p dm` ASSUME_TAC THENL
   [FIRST_X_ASSUM MATCH_MP_TAC THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  FIRST_X_ASSUM MATCH_MP_TAC THEN EXISTS_TAC `p:A` THEN ASM_REWRITE_TAC[]);;

(* ========================================================================= *)
(*  V^B CHOICE axiom (9th ZFC axiom) -- C-E EXISTENCE core, abstract lemmas. *)
(*                                                                           *)
(*  The "sup-step" reduction of [[choice_ax]]=T: for the direct disjoint-    *)
(*  family selector first(m,p), the harness-carrying per-point obligation    *)
(*  first(m,q)=fpq <= (w ==> K) that FST_SUP_GE consumes to bound            *)
(*  meet(prem,[[m in x]]) by K = [[EX s. s in t /\ s in c]].                 *)
(*                                                                           *)
(*  Dependency order within this block:                                      *)
(*    EXPAIR_UB, P1_NONEMPTY_LE, MEET_BLOCK_LE, FINAL_COMBINE_LE,            *)
(*    FIRST_OBLIG_BRIDGE  (abstract, mutually independent)                   *)
(*    CSEL_PERQ_LE        (uses EXPAIR_UB + MEET_BLOCK_LE)                   *)
(*    CSEL_QOBLIG         (uses FIRST_OBLIG_BRIDGE + CSEL_PERQ_LE +          *)
(* CSEL_VALUE)                                                               *)
(* ========================================================================= *)

(* EXPAIR_UB: a member-pair value is <= the existential over the pair.       *)
(*   [[p in v i]] MEET [[p in v j]] = [[(n%%i)&&(n%%j)]]_{n:=p}              *)
(*        <= [[?? n ((n%%i)&&(n%%j))]]_v.                                    *)
(* Abstract (no choice-construction context); instantiated i=1 (member t),   *)
(* j=4 (selector c), n=2 for the CHOICE EXISTENCE per-m core.                *)
(* = BVALF_MEM (each %% is ebv_in) + BVALF_AND_MEET (&& is meet) +           *)
(*   BVALF_EX_UB (witness p).                                                *)
let EXPAIR_UB = prove
 (`!D (E:A->A->bool) B leq v n i j p zt zc mtc.
     model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
     valuation D v /\ (!k. bname D E B (v k)) /\
     ~(n = i) /\ ~(n = j) /\
     p IN D /\ bname D E B p /\
     zt IN D /\ ebv_in D E B leq p (v i) zt /\
     zc IN D /\ ebv_in D E B leq p (v j) zc /\
     mtc IN D /\ emeet D E B leq zt zc mtc
     ==> erel D E leq mtc
           (bvalf D E B leq v (?? n ((n %% i) && (n %% j))))`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `eporder D (E:A->A->bool) B leq` ASSUME_TAC THENL
   [ASM_MESON_TAC[ECBA_IMP_BALG; EBALG_IMP_PORDER]; ALL_TAC] THEN
  ABBREV_TAC `va = (n |-> (p:A)) (v:num->A)` THEN
  (* va is a valuation whose slots are all bnames *)
  SUBGOAL_THEN
    `valuation D (va:num->A) /\ (!k. bname D (E:A->A->bool) B (va k))`
    STRIP_ASSUME_TAC THENL
   [EXPAND_TAC "va" THEN CONJ_TAC THENL
     [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[];
      GEN_TAC THEN REWRITE_TAC[VALMOD] THEN COND_CASES_TAC THEN
      ASM_REWRITE_TAC[]];
    ALL_TAC] THEN
  (* key slot values of va *)
  SUBGOAL_THEN `(va:num->A) n = p` ASSUME_TAC THENL
   [EXPAND_TAC "va" THEN REWRITE_TAC[VALMOD]; ALL_TAC] THEN
  SUBGOAL_THEN `(va:num->A) i = (v:num->A) i` ASSUME_TAC THENL
   [EXPAND_TAC "va" THEN REWRITE_TAC[VALMOD] THEN
    COND_CASES_TAC THENL [ASM_MESON_TAC[]; REFL_TAC]; ALL_TAC] THEN
  SUBGOAL_THEN `(va:num->A) j = (v:num->A) j` ASSUME_TAC THENL
   [EXPAND_TAC "va" THEN REWRITE_TAC[VALMOD] THEN
    COND_CASES_TAC THENL [ASM_MESON_TAC[]; REFL_TAC]; ALL_TAC] THEN
  (* slot elements are in D (from valuation) -- needed by EBV_IN_UNIQUE *)
  SUBGOAL_THEN `(v:num->A) i IN D /\ (v:num->A) j IN D` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[valuation]; ALL_TAC] THEN
  (* bvalf va (n%%i) = zt  and  bvalf va (n%%j) = zc *)
  SUBGOAL_THEN `(bvalf D (E:A->A->bool) B leq (va:num->A) (n %% i)) IN D /\
                (bvalf D (E:A->A->bool) B leq (va:num->A) (n %% j)) IN D`
    STRIP_ASSUME_TAC THENL
   [CONJ_TAC THEN
    (MP_TAC(ISPECL [`(n %% i):form`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
       `va:num->A`] BVALF_SPEC) THEN
     MP_TAC(ISPECL [`(n %% j):form`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
       `va:num->A`] BVALF_SPEC) THEN
     ASM_REWRITE_TAC[] THEN MESON_TAC[]);
    ALL_TAC] THEN
  SUBGOAL_THEN `bvalf D (E:A->A->bool) B leq (va:num->A) (n %% i) = zt`
    ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`p:A`;
       `(v:num->A) i`;`bvalf D E B leq (va:num->A) (n %% i)`;`zt:A`]
      EBV_IN_UNIQUE) THEN
    ASM_REWRITE_TAC[] THEN
    SUBGOAL_THEN `p = (va:num->A) n /\ (v:num->A) i = (va:num->A) i`
      (CONJUNCTS_THEN SUBST1_TAC) THENL
     [ASM_MESON_TAC[]; ALL_TAC] THEN
    MATCH_MP_TAC(ISPECL
                 [`n:num`;`i:num`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
                  `va:num->A`] BVALF_MEM) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `bvalf D (E:A->A->bool) B leq (va:num->A) (n %% j) = zc`
    ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`p:A`;
       `(v:num->A) j`;`bvalf D E B leq (va:num->A) (n %% j)`;`zc:A`]
      EBV_IN_UNIQUE) THEN
    ASM_REWRITE_TAC[] THEN
    SUBGOAL_THEN `p = (va:num->A) n /\ (v:num->A) j = (va:num->A) j`
      (CONJUNCTS_THEN SUBST1_TAC) THENL
     [ASM_MESON_TAC[]; ALL_TAC] THEN
    MATCH_MP_TAC(ISPECL
                 [`n:num`;`j:num`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
                  `va:num->A`] BVALF_MEM) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* bvalf va ((n%%i)&&(n%%j)) = mtc  (BVALF_AND_MEET + EMEET_UNIQUE) *)
  SUBGOAL_THEN
    `bvalf D (E:A->A->bool) B leq (va:num->A) ((n %% i) && (n %% j)) = mtc`
    ASSUME_TAC THENL
   [MP_TAC(ISPECL [`(n %% i):form`;`(n %% j):form`;`D:A->bool`;`E:A->A->bool`;
       `B:A`;`leq:A`;`va:num->A`] BVALF_AND_MEET) THEN
    ASM_REWRITE_TAC[] THEN DISCH_TAC THEN
    MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`zt:A`;`zc:A`;
                  `bvalf D E B leq (va:num->A) ((n %% i) && (n %% j))`;`mtc:A`]
      EMEET_UNIQUE) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* rewrite goal's mtc back to bvalf va (...&&...), expand va, hit *)
  (* BVALF_EX_UB *)
  SUBGOAL_THEN
    `mtc = bvalf D (E:A->A->bool) B leq (va:num->A) ((n %% i) && (n %% j))`
    SUBST1_TAC THENL
   [ASM_MESON_TAC[]; ALL_TAC] THEN
  EXPAND_TAC "va" THEN
  MATCH_MP_TAC(ISPECL [`n:num`;`((n %% i) && (n %% j)):form`;`D:A->bool`;
     `E:A->A->bool`;`B:A`;`leq:A`;`v:num->A`;`p:A`] BVALF_EX_UB) THEN
  ASM_REWRITE_TAC[]);;

(* P1_NONEMPTY_LE: the "every member is nonempty" instantiation.             *)
(*   prem = [[!!1 ((1%%0) --> ?? 2 (2%%1))]]_v   (P1: all members of slot 0  *)
(*   are nonempty).  Then  meet(prem, [[1%%0]]_{1:=m}) <= [[?? 2             *)
(* (2%%1)]]_{1:=m}, i.e. P1 MEET [[m in slot0]] <= [[m nonempty]].  Pure     *)
(* bvalf form; identification of [[1%%0]]_{1:=m} with [[m in x]] is done at  *)
(* the use site. = BVALF_ALL_LB (instantiate !!1 at m) + BVALF_IMP (--> is   *)
(* ebimp) +                                                                  *)
(*   EBV_MP_LE (Boolean modus ponens).                                       *)
let P1_NONEMPTY_LE = prove
 (`!D (E:A->A->bool) B leq v m dpm.
     model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
     valuation D v /\ (!k. bname D E B (v k)) /\
     m IN D /\ bname D E B m /\ dpm IN D /\
     emeet D E B leq
        (bvalf D E B leq v (!! 1 ((1 %% 0) --> (?? 2 (2 %% 1)))))
        (bvalf D E B leq ((1 |-> m) v) (1 %% 0))
        dpm
     ==> erel D E leq dpm
           (bvalf D E B leq ((1 |-> m) v) (?? 2 (2 %% 1)))`,
  REPEAT GEN_TAC THEN
  ABBREV_TAC `vm = (1 |-> (m:A)) (v:num->A)` THEN
  STRIP_TAC THEN
  SUBGOAL_THEN `eporder D (E:A->A->bool) B leq` ASSUME_TAC THENL
   [ASM_MESON_TAC[ECBA_IMP_BALG; EBALG_IMP_PORDER]; ALL_TAC] THEN
  SUBGOAL_THEN
    `valuation D (vm:num->A) /\ (!k. bname D (E:A->A->bool) B (vm k))`
    STRIP_ASSUME_TAC THENL
   [EXPAND_TAC "vm" THEN CONJ_TAC THENL
     [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[];
      MATCH_MP_TAC BNAMEVAL_VALMOD THEN ASM_REWRITE_TAC[]];
    ALL_TAC] THEN
  (* E dpm B  (from the meet hyp) *)
  SUBGOAL_THEN `(E:A->A->bool) dpm B` ASSUME_TAC THENL
   [MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
       `bvalf D E B leq (v:num->A) (!! 1 ((1 %% 0) --> (?? 2 (2 %% 1))))`;
       `bvalf D E B leq (vm:num->A) (1 %% 0)`;`dpm:A`] EMEET_IN) THEN
    ASM_REWRITE_TAC[] THEN MESON_TAC[]; ALL_TAC] THEN
  (* IN D / E _ B for the three vm-values (fa = 1%%0, fb = ?? 2 (2%%1),
     fi = (1%%0) --> ?? 2 (2%%1)) *)
  MAP_EVERY (fun q ->
    SUBGOAL_THEN
      (subst [q,`qq:form`]
        `(bvalf D (E:A->A->bool) B leq (vm:num->A) qq) IN D /\
         E (bvalf D E B leq vm qq) B`)
      STRIP_ASSUME_TAC THENL
     [CONJ_TAC THENL
       [MP_TAC(ISPECL [q;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`vm:num->A`]
          BVALF_SPEC) THEN ASM_REWRITE_TAC[] THEN
        DISCH_THEN(ACCEPT_TAC o CONJUNCT1);
        MP_TAC(ISPECL [q;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`vm:num->A`]
          BVALF_IN_B) THEN ASM_REWRITE_TAC[]];
      ALL_TAC])
   [`(1 %% 0):form`; `(?? 2 (2 %% 1)):form`;
    `((1 %% 0) --> (?? 2 (2 %% 1))):form`] THEN
  (* prem = bvalf v (!! 1 fi) is IN D and E _ B (needed by EPORDER_TRANS) *)
  SUBGOAL_THEN
    `(bvalf D (E:A->A->bool) B leq (v:num->A)
        (!! 1 ((1 %% 0) --> (?? 2 (2 %% 1))))) IN D /\
     E (bvalf D E B leq v (!! 1 ((1 %% 0) --> (?? 2 (2 %% 1))))) B`
    STRIP_ASSUME_TAC THENL
   [CONJ_TAC THENL
     [MP_TAC(ISPECL [`(!! 1 ((1 %% 0) --> (?? 2 (2 %% 1)))):form`;`D:A->bool`;
        `E:A->A->bool`;`B:A`;`leq:A`;`v:num->A`] BVALF_SPEC) THEN
      ASM_REWRITE_TAC[] THEN DISCH_THEN(ACCEPT_TAC o CONJUNCT1);
      MP_TAC(ISPECL [`(!! 1 ((1 %% 0) --> (?? 2 (2 %% 1)))):form`;`D:A->bool`;
        `E:A->A->bool`;`B:A`;`leq:A`;`v:num->A`] BVALF_IN_B) THEN
      ASM_REWRITE_TAC[]];
    ALL_TAC] THEN
  (* prem <= bvalf vm fi   (BVALF_ALL_LB) *)
  SUBGOAL_THEN
    `erel D (E:A->A->bool) leq
       (bvalf D E B leq (v:num->A) (!! 1 ((1 %% 0) --> (?? 2 (2 %% 1)))))
       (bvalf D E B leq (vm:num->A) ((1 %% 0) --> (?? 2 (2 %% 1))))`
    ASSUME_TAC THENL
   [SUBGOAL_THEN `(vm:num->A) = (1 |-> m) v` SUBST1_TAC THENL
     [ASM_MESON_TAC[]; ALL_TAC] THEN
    MATCH_MP_TAC(ISPECL [`1`;`((1 %% 0) --> (?? 2 (2 %% 1))):form`;
       `D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`v:num->A`;`m:A`]
        BVALF_ALL_LB) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* ebimp (bvalf vm fa) (bvalf vm fb) (bvalf vm fi)  (BVALF_IMP) *)
  SUBGOAL_THEN
    `ebimp D (E:A->A->bool) B leq
       (bvalf D E B leq (vm:num->A) (1 %% 0))
       (bvalf D E B leq vm (?? 2 (2 %% 1)))
       (bvalf D E B leq vm ((1 %% 0) --> (?? 2 (2 %% 1))))`
    ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL [`(1 %% 0):form`;`(?? 2 (2 %% 1)):form`;
       `D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`vm:num->A`] BVALF_IMP) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* dpm <= prem <= fi, and dpm <= fa *)
  SUBGOAL_THEN `erel D (E:A->A->bool) leq dpm
                  (bvalf D E B leq (vm:num->A) (1 %% 0)) /\
                erel D (E:A->A->bool) leq dpm
                  (bvalf D E B leq (v:num->A)
                     (!! 1 ((1 %% 0) --> (?? 2 (2 %% 1)))))`
    STRIP_ASSUME_TAC THENL
   [MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
       `bvalf D E B leq (v:num->A) (!! 1 ((1 %% 0) --> (?? 2 (2 %% 1))))`;
       `bvalf D E B leq (vm:num->A) (1 %% 0)`;`dpm:A`] EMEET_LE) THEN
    ASM_REWRITE_TAC[] THEN MESON_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq dpm
                  (bvalf D E B leq (vm:num->A) ((1 %% 0) --> (?? 2 (2 %% 1))))`
    ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`dpm:A`;
       `bvalf D E B leq (v:num->A) (!! 1 ((1 %% 0) --> (?? 2 (2 %% 1))))`;
       `bvalf D E B leq (vm:num->A) ((1 %% 0) --> (?? 2 (2 %% 1)))`]
      EPORDER_TRANS) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* Boolean modus ponens *)
  MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`dpm:A`;
     `bvalf D E B leq (vm:num->A) (1 %% 0)`;
     `bvalf D E B leq (vm:num->A) (?? 2 (2 %% 1))`;
     `bvalf D E B leq (vm:num->A) ((1 %% 0) --> (?? 2 (2 %% 1)))`]
                    EBV_MP_LE) THEN
  ASM_REWRITE_TAC[]);;

(* MEET_BLOCK_LE: abstract meet-algebra crux of the CHOICE EXISTENCE per-m   *)
(* per-block chain.  w = imx MEET z20 = [[m in x]] MEET [[m=t]];             *)
(* wf = w MEET fp = the block value.  Given the three sub-bounds             *)
(*   ival = imx MEET fp <= zc          (CSEL_VALUE:   [[m in x]]/\first<=[[p *)
(* in c]])                                                                   *)
(*   mf   = z20 MEET fp <= z22         (FST_CONG_MEM: [[m=t]]/\first<=[[p in *)
(* t]])                                                                      *)
(*   zct  = z22 MEET zc <= K           (EXPAIR_UB:    [[p in t]]/\[[p in     *)
(* c]]<=[[EX]]) conclude  wf <= K.  Pure GLB + transitivity.                 *)
let MEET_BLOCK_LE = prove
 (`!D (E:A->A->bool) B leq imx z20 fp w wf ival mf zc z22 zct K.
     ecba D E B leq /\ B IN D /\ leq IN D /\
     imx IN D /\ z20 IN D /\ fp IN D /\ w IN D /\ wf IN D /\
     ival IN D /\ mf IN D /\ zc IN D /\ z22 IN D /\ zct IN D /\ K IN D /\
     E imx B /\ E z20 B /\ E fp B /\ E w B /\ E wf B /\
     E ival B /\ E mf B /\ E zc B /\ E z22 B /\ E zct B /\ E K B /\
     emeet D E B leq imx z20 w /\
     emeet D E B leq w fp wf /\
     emeet D E B leq imx fp ival /\
     emeet D E B leq z20 fp mf /\
     emeet D E B leq z22 zc zct /\
     erel D E leq ival zc /\
     erel D E leq mf z22 /\
     erel D E leq zct K
     ==> erel D E leq wf K`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `eporder D (E:A->A->bool) B leq` ASSUME_TAC THENL
   [ASM_MESON_TAC[ECBA_IMP_BALG; EBALG_IMP_PORDER]; ALL_TAC] THEN
  (* wf <= w, wf <= fp *)
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`w:A`;`fp:A`;`wf:A`]
    EMEET_LE) THEN ASM_REWRITE_TAC[] THEN STRIP_TAC THEN
  (* w <= imx, w <= z20 *)
  MP_TAC(ISPECL
         [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`imx:A`;`z20:A`;`w:A`]
         EMEET_LE) THEN ASM_REWRITE_TAC[] THEN STRIP_TAC THEN
  (* wf <= imx, wf <= z20 (trans through w) *)
  SUBGOAL_THEN `erel D (E:A->A->bool) leq wf imx` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`wf:A`;`w:A`;
       `imx:A`] EPORDER_TRANS) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq wf z20` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`wf:A`;`w:A`;
       `z20:A`] EPORDER_TRANS) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* wf <= ival = imx MEET fp *)
  SUBGOAL_THEN `erel D (E:A->A->bool) leq wf ival` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`imx:A`;`fp:A`;
                  `ival:A`;`wf:A`] EMEET_GREATEST) THEN ASM_REWRITE_TAC[];
         ALL_TAC] THEN
  (* wf <= zc *)
  SUBGOAL_THEN `erel D (E:A->A->bool) leq wf zc` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`wf:A`;`ival:A`;
                  `zc:A`] EPORDER_TRANS) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* wf <= mf = z20 MEET fp *)
  SUBGOAL_THEN `erel D (E:A->A->bool) leq wf mf` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`z20:A`;`fp:A`;
                  `mf:A`;`wf:A`] EMEET_GREATEST) THEN ASM_REWRITE_TAC[];
         ALL_TAC] THEN
  (* wf <= z22 *)
  SUBGOAL_THEN `erel D (E:A->A->bool) leq wf z22` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`wf:A`;`mf:A`;
                  `z22:A`] EPORDER_TRANS) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* wf <= zct = z22 MEET zc *)
  SUBGOAL_THEN `erel D (E:A->A->bool) leq wf zct` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`z22:A`;`zc:A`;
                  `zct:A`;`wf:A`] EMEET_GREATEST) THEN ASM_REWRITE_TAC[];
         ALL_TAC] THEN
  (* wf <= K *)
  MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`wf:A`;`zct:A`;
     `K:A`] EPORDER_TRANS) THEN ASM_REWRITE_TAC[]);;

(* FINAL_COMBINE_LE: step-4 combine of the CHOICE EXISTENCE per-m core.      *)
(*   w = imx MEET z20   (= [[m in x]] MEET [[m=t]]);  pw = prem MEET w.      *)
(* Given                                                                     *)
(*   (A) wn = w MEET ne     <= K    (ne = [[m nonempty]]; from               *)
(* NONEMPTY_DOMSUP                                                           *)
(*                                    + residuation back through             *)
(* EBIMP_MEET_LE)                                                            *)
(*   (B) pimx = prem MEET imx <= ne  (P1_NONEMPTY_LE)                        *)
(* conclude pw = prem MEET w <= K.  Pure GLB + transitivity.                 *)
let FINAL_COMBINE_LE = prove
 (`!D (E:A->A->bool) B leq prem imx z20 ne w pw wn pimx K.
     ecba D E B leq /\ B IN D /\ leq IN D /\
     prem IN D /\ imx IN D /\ z20 IN D /\ ne IN D /\ w IN D /\ pw IN D /\
     wn IN D /\ pimx IN D /\ K IN D /\
     E prem B /\ E imx B /\ E z20 B /\ E ne B /\ E w B /\ E pw B /\
     E wn B /\ E pimx B /\ E K B /\
     emeet D E B leq imx z20 w /\
     emeet D E B leq prem w pw /\
     emeet D E B leq w ne wn /\
     emeet D E B leq prem imx pimx /\
     erel D E leq wn K /\
     erel D E leq pimx ne
     ==> erel D E leq pw K`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `eporder D (E:A->A->bool) B leq` ASSUME_TAC THENL
   [ASM_MESON_TAC[ECBA_IMP_BALG; EBALG_IMP_PORDER]; ALL_TAC] THEN
  (* pw <= prem, pw <= w *)
  MP_TAC(ISPECL
         [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`prem:A`;`w:A`;`pw:A`]
         EMEET_LE) THEN ASM_REWRITE_TAC[] THEN STRIP_TAC THEN
  (* w <= imx, w <= z20 *)
  MP_TAC(ISPECL
         [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`imx:A`;`z20:A`;`w:A`]
         EMEET_LE) THEN ASM_REWRITE_TAC[] THEN STRIP_TAC THEN
  (* pw <= imx (trans through w) *)
  SUBGOAL_THEN `erel D (E:A->A->bool) leq pw imx` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`pw:A`;`w:A`;
       `imx:A`] EPORDER_TRANS) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* pw <= pimx = prem MEET imx *)
  SUBGOAL_THEN `erel D (E:A->A->bool) leq pw pimx` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`prem:A`;`imx:A`;
                  `pimx:A`;`pw:A`] EMEET_GREATEST) THEN ASM_REWRITE_TAC[];
         ALL_TAC] THEN
  (* pw <= ne *)
  SUBGOAL_THEN `erel D (E:A->A->bool) leq pw ne` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`pw:A`;`pimx:A`;
                  `ne:A`] EPORDER_TRANS) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* pw <= wn = w MEET ne *)
  SUBGOAL_THEN `erel D (E:A->A->bool) leq pw wn` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`w:A`;`ne:A`;
       `wn:A`;`pw:A`] EMEET_GREATEST) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* pw <= K *)
  MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`pw:A`;`wn:A`;
     `K:A`] EPORDER_TRANS) THEN ASM_REWRITE_TAC[]);;

(* FIRST_OBLIG_BRIDGE: from FST_SUP_GE's explicit per-q first-term data      *)
(* (bpq,ddq,Spq,spq,cspq,fpq) build a valuation vfs (slots 0..6 = q,leq,B,m, *)
(* ra,W,fpq) satisfying  holds vfs firstsel_fm.  = FIRSTSEL_HOLDS backward.  *)
(* This is the ONLY glue between FST_SUP_GE (explicit meets) and CSEL_VALUE  *)
(* (which reads fp via firstsel_fm).  Needs NO choice-construction harness.  *)
let FIRST_OBLIG_BRIDGE = prove
 (`!D (E:A->A->bool) B leq m W ra q bpq ddq Spq spq cspq fpq vfs.
     model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
     m IN D /\ W IN D /\ ra IN D /\ q IN D /\
     bpq IN D /\ ddq IN D /\ Spq IN D /\ spq IN D /\ cspq IN D /\ fpq IN D /\
     ebv_in D E B leq q m bpq /\
     (!r. r IN D ==> (E r ddq <=> E r W /\ erel D E ra r q)) /\
     (!zz. zz IN D
           ==> (E zz Spq <=> ?r. r IN D /\ E r ddq /\
                ebv_in D E B leq r m zz)) /\
     elub D E B leq Spq spq /\ ecompl D E B leq spq cspq /\
     emeet D E B leq bpq cspq fpq /\
     valuation D vfs /\ vfs 0 = q /\ vfs 1 = leq /\ vfs 2 = B /\ vfs 3 = m /\
     vfs 4 = ra /\ vfs 5 = W /\ vfs 6 = fpq
     ==> holds D E vfs firstsel_fm`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`vfs:num->A`] FIRSTSEL_HOLDS) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN SUBST1_TAC THEN
  MAP_EVERY EXISTS_TAC [`Spq:A`;`spq:A`;`cspq:A`;`bpq:A`] THEN
  ASM_REWRITE_TAC[] THEN
  X_GEN_TAC `z:A` THEN DISCH_TAC THEN
  ASM_MESON_TAC[]);;

(* CSEL_PERQ_LE: the per-point q integration (abstract, NO choice harness).  *)
(* Given the three membership values at point q -- imx=[[m in x]]            *)
(* (abstract), z20=[[m=t]], bpq=[[q in m]], z22=[[q in t]], zc=[[q in c]] -- *)
(* the block selector value fpq (<= bpq), the meets w=imx/\z20, wf=w/\fpq,   *)
(* and CSEL_VALUE's output ival=imx/\fpq <= zc, conclude  wf = imx/\z20/\fpq *)
(* <= K = [[EX s. s in t /\ s in c]].  = FST_CONG_MEM (z20/\fpq<=z22) +      *)
(* EXPAIR_UB (z22/\zc<=K) + MEET_BLOCK_LE.  (v 1 = t, v 4 = c for the K      *)
(* existential.)                                                             *)
let CSEL_PERQ_LE = prove
 (`!D (E:A->A->bool) B leq v c m t q imx z20 bpq fpq w wf ival mf zc z22 zct.
     model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
     valuation D v /\ (!k. bname D E B (v k)) /\ v 1 = t /\ v 4 = c /\
     m IN D /\ bname D E B m /\ t IN D /\ bname D E B t /\
     q IN D /\ bname D E B q /\
     imx IN D /\ z20 IN D /\ bpq IN D /\ fpq IN D /\ w IN D /\ wf IN D /\
     ival IN D /\ mf IN D /\ zc IN D /\ z22 IN D /\ zct IN D /\
     E imx B /\ E z20 B /\ E bpq B /\ E fpq B /\ E w B /\ E wf B /\
     E ival B /\ E mf B /\ E zc B /\ E z22 B /\ E zct B /\
     ebv_eq D E B leq m t z20 /\ ebv_in D E B leq q m bpq /\
     erel D E leq fpq bpq /\
     ebv_in D E B leq q t z22 /\ ebv_in D E B leq q c zc /\
     emeet D E B leq imx z20 w /\ emeet D E B leq w fpq wf /\
     emeet D E B leq imx fpq ival /\ emeet D E B leq z20 fpq mf /\
     emeet D E B leq z22 zc zct /\
     erel D E leq ival zc
     ==> erel D E leq wf (bvalf D E B leq v (?? 2 ((2 %% 1) && (2 %% 4))))`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  ABBREV_TAC
    `K = bvalf D (E:A->A->bool) B leq (v:num->A)
     (?? 2 ((2 %% 1) && (2 %% 4)))` THEN
  (* K IN D /\ E K B *)
  SUBGOAL_THEN `(K:A) IN D /\ (E:A->A->bool) K B` STRIP_ASSUME_TAC THENL
   [EXPAND_TAC "K" THEN CONJ_TAC THENL
     [MP_TAC(ISPECL [`(?? 2 ((2 %% 1) && (2 %% 4))):form`;`D:A->bool`;
        `E:A->A->bool`;`B:A`;`leq:A`;`v:num->A`] BVALF_SPEC) THEN
      ASM_REWRITE_TAC[] THEN DISCH_THEN(ACCEPT_TAC o CONJUNCT1);
      MP_TAC(ISPECL [`(?? 2 ((2 %% 1) && (2 %% 4))):form`;`D:A->bool`;
        `E:A->A->bool`;`B:A`;`leq:A`;`v:num->A`] BVALF_IN_B) THEN
      ASM_REWRITE_TAC[]];
    ALL_TAC] THEN
  (* mf = z20 /\ fpq <= z22 = [[q in t]]   (FST_CONG_MEM) *)
  SUBGOAL_THEN `erel D (E:A->A->bool) leq mf z22` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`m:A`;`t:A`;
       `q:A`;`z20:A`;`bpq:A`;`fpq:A`;`mf:A`;`z22:A`] FST_CONG_MEM) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* zct = z22 /\ zc <= K = [[?? 2 ((2%%1)&&(2%%4))]]   (EXPAIR_UB, *)
  (* i=1,j=4,n=2) *)
  SUBGOAL_THEN `erel D (E:A->A->bool) leq zct K` ASSUME_TAC THENL
   [EXPAND_TAC "K" THEN
    MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`v:num->A`;
       `2`;`1`;`4`;`q:A`;`z22:A`;`zc:A`;`zct:A`] EXPAIR_UB) THEN
    ASM_REWRITE_TAC[ARITH_EQ] THEN
    (* zt = z22 = [[q in v 1]] = [[q in t]] ; zc = [[q in v 4]] = [[q in c]] *)
    SUBGOAL_THEN `(v:num->A) 1 = t /\ (v:num->A) 4 = c`
      (fun th -> REWRITE_TAC[th]) THENL
     [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* wf = w /\ fpq <= K   (MEET_BLOCK_LE) *)
  MATCH_MP_TAC(ISPECL
               [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`imx:A`;`z20:A`;
                `fpq:A`;`w:A`;`wf:A`;`ival:A`;`mf:A`;`zc:A`;`z22:A`;
                `zct:A`;`K:A`]
    MEET_BLOCK_LE) THEN
  ASM_REWRITE_TAC[]);;

(* CSEL_QOBLIG: the FST_SUP_GE per-point obligation, carrying the full       *)
(* choice harness.  For q in W with FST_SUP_GE's explicit first-term data    *)
(* (bpq,ddq,Spq,spq,cspq,fpq), show  first(m,q)=fpq <= rhs = (w ==> K),      *)
(* w = [[m in x]] MEET [[m=t]], K = [[EX s. s in t /\ s in c]].              *)
(* = FIRST_OBLIG_BRIDGE (build vfs) + CSEL_VALUE (harness: imx/\fpq <= [[q   *)
(* in c]])                                                                   *)
(*   + create per-q values + CSEL_PERQ_LE (wf=w/\fpq <= K) + residuate.      *)
let CSEL_QOBLIG = prove
 (`!D (E:A->A->bool) B leq ra W x DD g c vc vf v m t
      imx z20 w K rhs
      q bpq ddq Spq spq cspq fpq.
     model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
     x IN D /\ bname D E B x /\
     W IN D /\ ra IN D /\ DD IN D /\ g IN D /\ c IN D /\
     (!q. q IN D /\ E q W ==> bname D E B q) /\
     (!q b pr. q IN D /\ b IN D /\ pr IN D /\
               eopair D E q b pr /\ E pr g ==> E b B) /\
     m IN D /\ bname D E B m /\
     valuation D vc /\ vc 1 = leq /\ vc 2 = B /\ vc 4 = ra /\ vc 5 = W /\
     vc 15 = x /\
     (!w. w IN D
          ==> (E w g <=>
               ?u. u IN D /\ E u DD /\
                   holds D E ((20 |-> w)((16 |-> u) vc)) phi_c)) /\
     valuation D vf /\ vf 1 = leq /\ vf 2 = B /\ vf 15 = g /\
     (!w. w IN D
          ==> (E w c <=>
               ?pp. pp IN D /\ E pp W /\
                    holds D E ((20 |-> w)((16 |-> pp) vf)) phi_func)) /\
     bname D E B c /\
     (!qq blk. qq IN D /\ E qq W /\ eopair D E m qq blk ==> E blk DD) /\
     valuation D v /\ (!k. bname D E B (v k)) /\ v 1 = t /\ v 4 = c /\
     t IN D /\ bname D E B t /\
     imx IN D /\ E imx B /\ ebv_in D E B leq m x imx /\
     z20 IN D /\ E z20 B /\ ebv_eq D E B leq m t z20 /\
     w IN D /\ E w B /\ emeet D E B leq imx z20 w /\
     K = bvalf D E B leq v (?? 2 ((2 %% 1) && (2 %% 4))) /\
     rhs IN D /\ E rhs B /\ ebimp D E B leq w K rhs /\
     q IN D /\ E q W /\
     ebv_in D E B leq q m bpq /\ bpq IN D /\
     ddq IN D /\ (!r. r IN D ==> (E r ddq <=> E r W /\ erel D E ra r q)) /\
     Spq IN D /\
     (!zz. zz IN D
           ==> (E zz Spq <=> ?r. r IN D /\ E r ddq /\
                ebv_in D E B leq r m zz)) /\
     elub D E B leq Spq spq /\ ecompl D E B leq spq cspq /\
     emeet D E B leq bpq cspq fpq
     ==> erel D E leq fpq rhs`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `ebalg D (E:A->A->bool) B leq` ASSUME_TAC THENL
   [ASM_MESON_TAC[ECBA_IMP_BALG]; ALL_TAC] THEN
  SUBGOAL_THEN `eporder D (E:A->A->bool) B leq` ASSUME_TAC THENL
   [ASM_MESON_TAC[EBALG_IMP_PORDER]; ALL_TAC] THEN
  SUBGOAL_THEN `bname D (E:A->A->bool) B q` ASSUME_TAC THENL
   [FIRST_X_ASSUM MATCH_MP_TAC THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* fpq IN D /\ E fpq B; bpq IN D /\ E bpq B; fpq <= bpq *)
  SUBGOAL_THEN `(fpq:A) IN D /\ (E:A->A->bool) fpq B` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[EMEET_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) bpq B` ASSUME_TAC THENL
   [ASM_MESON_TAC[EBV_IN_IN_B]; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq fpq bpq` ASSUME_TAC THENL
   [MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`bpq:A`;`cspq:A`;
       `fpq:A`] EMEET_LE) THEN ASM_REWRITE_TAC[] THEN MESON_TAC[];
     ALL_TAC] THEN
  (* spq IN D /\ E spq B (from elub); cspq IN D /\ E cspq B (from ecompl) *)
  SUBGOAL_THEN `(spq:A) IN D /\ (E:A->A->bool) spq B` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[ELUB_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `(cspq:A) IN D /\ (E:A->A->bool) cspq B` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[ECOMPL_IN]; ALL_TAC] THEN
  (* K IN D /\ E K B in expanded (bvalf) form, so the final EBIMP_LE_IMP     *)
  (* residual (which ASM_REWRITE expands via K = bvalf...) is dischargeable. *)
  SUBGOAL_THEN
    `(bvalf D (E:A->A->bool) B leq (v:num->A)
      (?? 2 ((2 %% 1) && (2 %% 4)))) IN D /\
     (E:A->A->bool) (bvalf D E B leq v (?? 2 ((2 %% 1) && (2 %% 4)))) B`
    STRIP_ASSUME_TAC THENL
   [CONJ_TAC THENL
     [MP_TAC(ISPECL [`(?? 2 ((2 %% 1) && (2 %% 4))):form`;`D:A->bool`;
        `E:A->A->bool`;`B:A`;`leq:A`;`v:num->A`] BVALF_SPEC) THEN
      ASM_REWRITE_TAC[] THEN DISCH_THEN(ACCEPT_TAC o CONJUNCT1);
      MP_TAC(ISPECL [`(?? 2 ((2 %% 1) && (2 %% 4))):form`;`D:A->bool`;
        `E:A->A->bool`;`B:A`;`leq:A`;`v:num->A`] BVALF_IN_B) THEN
      ASM_REWRITE_TAC[]];
    ALL_TAC] THEN
  (* ---- build vfs on vc, slots 0..6 = q,leq,B,m,ra,W,fpq ---- *)
  ABBREV_TAC
    `vfs = (6 |-> (fpq:A))((5 |-> W)((4 |-> ra)((3 |-> m)((2 |-> B)
              ((1 |-> leq)((0 |-> q)(vc:num->A))))))) ` THEN
  SUBGOAL_THEN `valuation D (vfs:num->A)` ASSUME_TAC THENL
   [EXPAND_TAC "vfs" THEN REPEAT(MATCH_MP_TAC VALUATION_VALMOD THEN
     ASM_REWRITE_TAC[]) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN
    `(vfs:num->A) 0 = q /\ vfs 1 = leq /\ vfs 2 = B /\ vfs 3 = m /\
     vfs 4 = ra /\ vfs 5 = W /\ vfs 6 = fpq`
    STRIP_ASSUME_TAC THENL
   [EXPAND_TAC "vfs" THEN REWRITE_TAC[VALMOD; ARITH_EQ]; ALL_TAC] THEN
  (* ---- holds vfs firstsel_fm ---- *)
  SUBGOAL_THEN `holds D (E:A->A->bool) vfs firstsel_fm` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`m:A`;`W:A`;
       `ra:A`;`q:A`;`bpq:A`;`ddq:A`;`Spq:A`;`spq:A`;`cspq:A`;`fpq:A`;
       `vfs:num->A`]
      FIRST_OBLIG_BRIDGE) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* ---- blk = <m,q> in DD ---- *)
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`m:A`;`q:A`] EOPAIR_EXISTS) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `blk:A` ASSUME_TAC) THEN
  SUBGOAL_THEN `(blk:A) IN D /\ (E:A->A->bool) blk DD` STRIP_ASSUME_TAC THENL
   [CONJ_TAC THENL
     [ASM_MESON_TAC[EOPAIR_IN];
      FIRST_X_ASSUM(fun th -> MATCH_MP_TAC th) THEN
      MAP_EVERY EXISTS_TAC [`q:A`] THEN ASM_REWRITE_TAC[]];
    ALL_TAC] THEN
  (* ---- create ival = meet(imx,fpq) ---- *)
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`imx:A`;`fpq:A`]
    EBALG_MEET) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `ival:A` ASSUME_TAC) THEN
  SUBGOAL_THEN `(ival:A) IN D /\ (E:A->A->bool) ival B` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[EMEET_IN]; ALL_TAC] THEN
  (* ---- create zc = [[q in c]] ---- *)
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`q:A`;`c:A`]
    EBV_IN_VAL_EXISTS) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `zc:A` STRIP_ASSUME_TAC) THEN
  (* ---- CSEL_VALUE: ival <= zc ---- *)
  SUBGOAL_THEN `erel D (E:A->A->bool) leq ival zc` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`ra:A`;`W:A`;
       `x:A`;`DD:A`;`g:A`;`c:A`;`vc:num->A`;`vf:num->A`;`vfs:num->A`;
       `m:A`;`q:A`;
       `blk:A`;`fpq:A`;`imx:A`;`ival:A`;`zc:A`] CSEL_VALUE) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* ---- create z22 = [[q in t]] ---- *)
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`q:A`;`t:A`]
    EBV_IN_VAL_EXISTS) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `z22:A` STRIP_ASSUME_TAC) THEN
  (* ---- create mf = meet(z20,fpq) ---- *)
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`z20:A`;`fpq:A`]
    EBALG_MEET) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `mf:A` ASSUME_TAC) THEN
  SUBGOAL_THEN `(mf:A) IN D /\ (E:A->A->bool) mf B` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[EMEET_IN]; ALL_TAC] THEN
  (* ---- create zct = meet(z22,zc) ---- *)
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`z22:A`;`zc:A`]
    EBALG_MEET) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `zct:A` ASSUME_TAC) THEN
  SUBGOAL_THEN `(zct:A) IN D /\ (E:A->A->bool) zct B` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[EMEET_IN]; ALL_TAC] THEN
  (* ---- create wf = meet(w,fpq) ---- *)
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`w:A`;`fpq:A`]
    EBALG_MEET) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `wf:A` ASSUME_TAC) THEN
  SUBGOAL_THEN `(wf:A) IN D /\ (E:A->A->bool) wf B` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[EMEET_IN]; ALL_TAC] THEN
  (* ---- CSEL_PERQ_LE: wf <= K ---- *)
  SUBGOAL_THEN `erel D (E:A->A->bool) leq wf K` ASSUME_TAC THENL
   [SUBGOAL_THEN `K = bvalf D (E:A->A->bool) B leq (v:num->A)
                        (?? 2 ((2 %% 1) && (2 %% 4)))` SUBST1_TAC THENL
     [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`v:num->A`;
       `c:A`;`m:A`;`t:A`;`q:A`;`imx:A`;`z20:A`;`bpq:A`;`fpq:A`;`w:A`;`wf:A`;
       `ival:A`;`mf:A`;`zc:A`;`z22:A`;`zct:A`] CSEL_PERQ_LE) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* ---- residuate: fpq <= (w ==> K) = rhs ---- *)
  SUBGOAL_THEN `emeet D (E:A->A->bool) B leq fpq w wf` ASSUME_TAC THENL
   [MATCH_MP_TAC EMEET_SYM THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`fpq:A`;`w:A`;
     `K:A`;`rhs:A`;`wf:A`] EBIMP_LE_IMP) THEN
  ASM_REWRITE_TAC[]);;

(* ========================================================================= *)
(* CHOICE (C-E): FST_SUP_GE + the EXISTENCE per-m core CSEL_EXIST_PERM.    *)
(* ========================================================================= *)

(* FST_SUP_GE: the ub-clause hypothesis quantifies only over bpq IN D.  Over *)
(* ALL values it would include "junk" bpq NOT IN D (possible via             *)
(* EOPAIR_COLLAPSE in the degenerate case [[q in m]] = <q,m>), for which     *)
(* emeet bpq cspq fpq forces fpq = cspq, which is NOT bounded by rhs.  The   *)
(* proof applies the clause only at bp0 from EFIRST_EXISTS (bp0 IN D).       *)
let FST_SUP_GE = prove
 (`!D (E:A->A->bool) B leq m dm ra rhs.
      model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
      rhs IN D /\ E rhs B /\
      m IN D /\ bname D E B m /\
      dm IN D /\ (!q. q IN D /\ E q dm ==> bname D E B q) /\
      ra IN D /\
      (!z. z IN D /\ (!t. t IN D /\ E t z ==> E t dm) /\ (?t. t IN D /\ E t z)
           ==> ?p0. p0 IN D /\ E p0 z /\
                   !q. q IN D /\ E q z /\ ~(q = p0) ==> erel D E ra p0 q) /\
      (!u u'. u IN D /\ u' IN D /\ erel D E ra u u' ==> ~(erel D E ra u' u)) /\
      (!q bpq ddq Spq spq cspq fpq.
           q IN D /\ E q dm /\
           ebv_in D E B leq q m bpq /\ bpq IN D /\
           ddq IN D /\
           (!r. r IN D ==> (E r ddq <=> E r dm /\ erel D E ra r q)) /\
           Spq IN D /\
           (!zz. zz IN D
                 ==> (E zz Spq <=> ?r. r IN D /\ E r ddq /\
                      ebv_in D E B leq r m zz)) /\
           elub D E B leq Spq spq /\ ecompl D E B leq spq cspq /\
           emeet D E B leq bpq cspq fpq
           ==> erel D E leq fpq rhs)
      ==> !p z. p IN D /\ E p dm /\ z IN D /\ ebv_in D E B leq p m z
                ==> erel D E leq z rhs`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `ebalg D (E:A->A->bool) B leq` ASSUME_TAC THENL
   [ASM_MESON_TAC[ECBA_IMP_BALG]; ALL_TAC] THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`m:A`;`dm:A`;`rhs:A`]
    EBADSET_EXISTS) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `bad:A`
    (CONJUNCTS_THEN2 ASSUME_TAC (LABEL_TAC "badc"))) THEN
  SUBGOAL_THEN `~(?q:A. q IN D /\ (E:A->A->bool) q bad)` ASSUME_TAC THENL
   [DISCH_THEN(X_CHOOSE_THEN `q0:A` STRIP_ASSUME_TAC) THEN
    SUBGOAL_THEN
     `?p0:A. p0 IN D /\ (E:A->A->bool) p0 bad /\
             (!q. q IN D /\ E q bad /\ ~(q = p0) ==> erel D E ra p0 q)`
     STRIP_ASSUME_TAC THENL
     [FIRST_ASSUM MATCH_MP_TAC THEN REPEAT CONJ_TAC THENL
       [FIRST_ASSUM ACCEPT_TAC; ASM_MESON_TAC[]; ASM_MESON_TAC[]];
       ALL_TAC] THEN
    SUBGOAL_THEN
     `E p0 dm /\ ?z. z IN D /\ ebv_in D (E:A->A->bool) B leq p0 m z /\
                     ~(erel D E leq z rhs)`
     STRIP_ASSUME_TAC THENL [ASM_MESON_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN `bname D (E:A->A->bool) B p0` ASSUME_TAC THENL
     [ASM_MESON_TAC[]; ALL_TAC] THEN
    MP_TAC(ISPECL
           [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`m:A`;`dm:A`;
            `ra:A`;`p0:A`]
           EFIRST_EXISTS) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(X_CHOOSE_THEN `bp0:A`
               (X_CHOOSE_THEN `dd0:A` (X_CHOOSE_THEN `Sp0:A`
                                       (X_CHOOSE_THEN `sp0:A`
                                        (X_CHOOSE_THEN `csp0:A`
                                         (X_CHOOSE_THEN `fp0:A`
                                          STRIP_ASSUME_TAC)))))) THEN
    SUBGOAL_THEN
     `!r zz. r IN D /\ E r dd0 /\ zz IN D /\
      ebv_in D (E:A->A->bool) B leq r m zz
             ==> erel D E leq zz rhs`
     ASSUME_TAC THENL
     [MAP_EVERY X_GEN_TAC [`r:A`;`zz:A`] THEN STRIP_TAC THEN
      SUBGOAL_THEN `E r dm /\ erel D (E:A->A->bool) ra r p0`
        STRIP_ASSUME_TAC THENL
        [ASM_MESON_TAC[]; ALL_TAC] THEN
      SUBGOAL_THEN `~((E:A->A->bool) r bad)` ASSUME_TAC THENL
       [DISCH_TAC THEN ASM_CASES_TAC `r:A = p0` THEN ASM_MESON_TAC[];
        ALL_TAC] THEN
      ASM_MESON_TAC[]; ALL_TAC] THEN
    MP_TAC(ISPECL
           [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`m:A`;`dd0:A`;`Sp0:A`;
            `sp0:A`;`rhs:A`] FSUP_SP_LE) THEN
    ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    DISCH_TAC THEN
    FIRST_X_ASSUM(fun ub -> MP_TAC(ISPECL
      [`p0:A`;`bp0:A`;`dd0:A`;`Sp0:A`;`sp0:A`;`csp0:A`;`fp0:A`] ub)) THEN
    ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    DISCH_TAC THEN
    MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`bp0:A`;`sp0:A`]
      EBALG_MEET) THEN
    ASM_REWRITE_TAC[] THEN
    DISCH_THEN(X_CHOOSE_THEN `m2:A` ASSUME_TAC) THEN
    SUBGOAL_THEN `(m2:A) IN D /\ (E:A->A->bool) m2 B` STRIP_ASSUME_TAC THENL
     [ASM_MESON_TAC[EMEET_IN]; ALL_TAC] THEN
    MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`fp0:A`;`m2:A`]
      EBALG_JOIN) THEN
    ASM_REWRITE_TAC[] THEN
    DISCH_THEN(X_CHOOSE_THEN `j:A` ASSUME_TAC) THEN
    MP_TAC(ISPECL
           [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`bp0:A`;`sp0:A`;`csp0:A`;
            `fp0:A`;`m2:A`;`j:A`;`rhs:A`] FST_SUP_STEP_ABS) THEN
    ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    DISCH_TAC THEN
    ASM_MESON_TAC[EBV_IN_UNIQUE]; ALL_TAC] THEN
  MAP_EVERY X_GEN_TAC [`p:A`;`z:A`] THEN STRIP_TAC THEN
  ASM_MESON_TAC[]);;

(* CSEL_EXIST_PERM: the per-m core of the CHOICE EXISTENCE reduction.        *)
(* Carries the full CSEL_VALUE choice-construction harness; concludes        *)
(*   pw = meet(prem, w) <= K,   w = meet(imx,z20),  imx=[[m in x]],          *)
(* z20=[[m=t]],                                                              *)
(*   K = [[?? 2 (2%%1 && 2%%4)]]_v  (v0=x,v1=t,v4=c).                        *)
(* Steps (design C-E (1)-(6)):                                               *)
(*  (1) per-q obligation first(m,q)=fpq <= (w==>K) = CSEL_QOBLIG.            *)
(*  (2) FST_SUP_GE (dm:=W) => every [[q in m]] <= (w==>K).                   *)
(*  (3) NONEMPTY_DOMSUP_LE (dm:=W, n=2, j=1, vm=(1|->m)v) => ne=[[?w.w in    *)
(* m]]<=rhs.                                                                 *)
(*  (4) residuate back (EMEET_SYM + EBIMP_MEET_LE) => wn=meet(w,ne) <= K.    *)
(*  (5) P1-bound: pimx=meet(prem,imx) <= ne  (prem<=[[P1]] +                 *)
(* P1_NONEMPTY_LE).                                                          *)
(*  (6) FINAL_COMBINE_LE => pw=meet(prem,w) <= K.                            *)
(* The ub-clause carries `bpq IN D` (matching FST_SUP_GE) so it feeds        *)
(* directly to CSEL_QOBLIG -- no circular EBV_IN_UNIQUE derivation of bpq IN *)
(* D.                                                                        *)
let CSEL_EXIST_PERM = prove
 (`!D (E:A->A->bool) B leq ra W x DD g c vc vf v m t
      imx z20 w K prem pw.
     model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
     x IN D /\ bname D E B x /\
     W IN D /\ ra IN D /\ DD IN D /\ g IN D /\ c IN D /\
     (!q. q IN D /\ E q W ==> bname D E B q) /\
     (!q b pr. q IN D /\ b IN D /\ pr IN D /\
               eopair D E q b pr /\ E pr g ==> E b B) /\
     m IN D /\ bname D E B m /\
     valuation D vc /\ vc 1 = leq /\ vc 2 = B /\ vc 4 = ra /\ vc 5 = W /\
     vc 15 = x /\
     (!w. w IN D
          ==> (E w g <=>
               ?u. u IN D /\ E u DD /\
                   holds D E ((20 |-> w)((16 |-> u) vc)) phi_c)) /\
     valuation D vf /\ vf 1 = leq /\ vf 2 = B /\ vf 15 = g /\
     (!w. w IN D
          ==> (E w c <=>
               ?pp. pp IN D /\ E pp W /\
                    holds D E ((20 |-> w)((16 |-> pp) vf)) phi_func)) /\
     bname D E B c /\
     (!qq blk. qq IN D /\ E qq W /\ eopair D E m qq blk ==> E blk DD) /\
     valuation D v /\ (!k. bname D E B (v k)) /\
     v 0 = x /\ v 1 = t /\ v 4 = c /\
     t IN D /\ bname D E B t /\
     imx IN D /\ E imx B /\ ebv_in D E B leq m x imx /\
     z20 IN D /\ E z20 B /\ ebv_eq D E B leq m t z20 /\
     w IN D /\ E w B /\ emeet D E B leq imx z20 w /\
     K = bvalf D E B leq v (?? 2 ((2 %% 1) && (2 %% 4))) /\
     prem IN D /\ E prem B /\
     erel D E leq prem
       (bvalf D E B leq v (!! 1 ((1 %% 0) --> (?? 2 (2 %% 1))))) /\
     pw IN D /\ E pw B /\ emeet D E B leq prem w pw /\
     (!z. z IN D /\ (!s. s IN D /\ E s z ==> E s W) /\ (?s. s IN D /\ E s z)
          ==> ?p0. p0 IN D /\ E p0 z /\
                  !q. q IN D /\ E q z /\ ~(q = p0) ==> erel D E ra p0 q) /\
     (!u u'. u IN D /\ u' IN D /\ erel D E ra u u' ==> ~(erel D E ra u' u)) /\
     (!y. y IN D /\ eindom D E m y ==> E y W)
     ==> erel D E leq pw K`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `ebalg D (E:A->A->bool) B leq` ASSUME_TAC THENL
   [ASM_MESON_TAC[ECBA_IMP_BALG]; ALL_TAC] THEN
  SUBGOAL_THEN `eporder D (E:A->A->bool) B leq` ASSUME_TAC THENL
   [ASM_MESON_TAC[EBALG_IMP_PORDER]; ALL_TAC] THEN
  (* ---- K IN D /\ E K B ---- *)
  SUBGOAL_THEN `(K:A) IN D /\ (E:A->A->bool) K B` STRIP_ASSUME_TAC THENL
   [SUBGOAL_THEN `K = bvalf D (E:A->A->bool) B leq (v:num->A)
                        (?? 2 ((2 %% 1) && (2 %% 4)))` SUBST1_TAC THENL
     [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    CONJ_TAC THENL
     [MP_TAC(ISPECL [`(?? 2 ((2 %% 1) && (2 %% 4))):form`;`D:A->bool`;
        `E:A->A->bool`;`B:A`;`leq:A`;`v:num->A`] BVALF_SPEC) THEN
      ASM_REWRITE_TAC[] THEN DISCH_THEN(ACCEPT_TAC o CONJUNCT1);
      MP_TAC(ISPECL [`(?? 2 ((2 %% 1) && (2 %% 4))):form`;`D:A->bool`;
        `E:A->A->bool`;`B:A`;`leq:A`;`v:num->A`] BVALF_IN_B) THEN
      ASM_REWRITE_TAC[]];
    ALL_TAC] THEN
  (* ---- build rhs = (w ==> K) ---- *)
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`w:A`;`K:A`]
         EBIMP_EXISTS) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `rhs:A` ASSUME_TAC) THEN
  SUBGOAL_THEN `(rhs:A) IN D /\ (E:A->A->bool) rhs B` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[EBIMP_IN]; ALL_TAC] THEN
  (* ---- (1)+(2): the FST_SUP_GE upper-bound clause, via CSEL_QOBLIG ----   *)
  (* bpq IN D is now a HYPOTHESIS of the ub-clause (FST_SUP_GE), so it is    *)
  (* available directly for CSEL_QOBLIG -- no EBV_IN_UNIQUE (which would be  *)
  (* circular: it needs bpq IN D).  Junk bpq (not IN D) is excluded because  *)
  (* it would force fpq = cspq, unbounded by rhs.                            *)
  SUBGOAL_THEN
    `!q bpq ddq Spq spq cspq fpq.
        q IN D /\ E q W /\
        ebv_in D (E:A->A->bool) B leq q m bpq /\ bpq IN D /\
        ddq IN D /\
        (!r. r IN D ==> (E r ddq <=> E r W /\ erel D E ra r q)) /\
        Spq IN D /\
        (!zz. zz IN D
              ==> (E zz Spq <=> ?r. r IN D /\ E r ddq /\
                   ebv_in D E B leq r m zz)) /\
        elub D E B leq Spq spq /\ ecompl D E B leq spq cspq /\
        emeet D E B leq bpq cspq fpq
        ==> erel D E leq fpq rhs`
    (LABEL_TAC "ub") THENL
   [MAP_EVERY X_GEN_TAC
      [`q:A`;`bpq:A`;`ddq:A`;`Spq:A`;`spq:A`;`cspq:A`;`fpq:A`] THEN
    STRIP_TAC THEN
    SUBGOAL_THEN `bname D (E:A->A->bool) B q` ASSUME_TAC THENL
     [FIRST_X_ASSUM MATCH_MP_TAC THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`ra:A`;`W:A`;
       `x:A`;`DD:A`;`g:A`;`c:A`;`vc:num->A`;`vf:num->A`;`v:num->A`;`m:A`;`t:A`;
       `imx:A`;`z20:A`;`w:A`;`K:A`;`rhs:A`;`q:A`;`bpq:A`;`ddq:A`;
       `Spq:A`;`spq:A`;
       `cspq:A`;`fpq:A`] CSEL_QOBLIG) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* ---- (2): FST_SUP_GE gives dom-sup bound over W ---- *)
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`m:A`;`W:A`;`ra:A`;
     `rhs:A`] FST_SUP_GE) THEN
  ANTS_TAC THENL
  [ASM_REWRITE_TAC[] THEN USE_THEN "ub" ACCEPT_TAC; ALL_TAC] THEN
  DISCH_THEN(LABEL_TAC "domsup") THEN
  (* ---- build vm = (1|->m) v ---- *)
  ABBREV_TAC `vm = (1 |-> (m:A)) (v:num->A)` THEN
  SUBGOAL_THEN
    `valuation D (vm:num->A) /\ (!i. bname D (E:A->A->bool) B (vm i))`
    STRIP_ASSUME_TAC THENL
   [EXPAND_TAC "vm" THEN CONJ_TAC THENL
     [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[];
      MATCH_MP_TAC BNAMEVAL_VALMOD THEN ASM_REWRITE_TAC[]];
    ALL_TAC] THEN
  SUBGOAL_THEN `(vm:num->A) 1 = m /\ (vm:num->A) 0 = x` STRIP_ASSUME_TAC THENL
   [EXPAND_TAC "vm" THEN REWRITE_TAC[VALMOD; ARITH_EQ] THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  (* ---- ne = [[?? 2 (2%%1)]]_vm ;  ne IN D, E ne B ---- *)
  SUBGOAL_THEN
    `(bvalf D (E:A->A->bool) B leq (vm:num->A) (?? 2 (2 %% 1))) IN D /\
     (E:A->A->bool) (bvalf D E B leq vm (?? 2 (2 %% 1))) B`
    STRIP_ASSUME_TAC THENL
   [CONJ_TAC THENL
     [MP_TAC(ISPECL
             [`(?? 2 (2 %% 1)):form`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
              `vm:num->A`] BVALF_SPEC) THEN ASM_REWRITE_TAC[] THEN
      DISCH_THEN(ACCEPT_TAC o CONJUNCT1);
      MP_TAC(ISPECL
             [`(?? 2 (2 %% 1)):form`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
              `vm:num->A`] BVALF_IN_B) THEN ASM_REWRITE_TAC[]];
    ALL_TAC] THEN
  (* ---- (3): NONEMPTY_DOMSUP_LE => ne <= rhs ---- *)
  SUBGOAL_THEN `erel D (E:A->A->bool) leq
                  (bvalf D E B leq (vm:num->A) (?? 2 (2 %% 1))) rhs`
    (LABEL_TAC "ne_le") THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`m:A`;`W:A`;`2`;
                  `1`;`vm:num->A`;`rhs:A`] NONEMPTY_DOMSUP_LE) THEN
    ASM_REWRITE_TAC[ARITH_EQ] THEN
    CONJ_TAC THENL
     [X_GEN_TAC `y:A` THEN STRIP_TAC THEN FIRST_X_ASSUM MATCH_MP_TAC THEN
      ASM_REWRITE_TAC[];
      MAP_EVERY X_GEN_TAC [`p:A`;`z:A`] THEN STRIP_TAC THEN
      REMOVE_THEN "domsup" MATCH_MP_TAC THEN ASM_REWRITE_TAC[]];
    ALL_TAC] THEN
  (* ---- p1v = [[P1]]_v ;  p1v IN D, E p1v B ---- *)
  SUBGOAL_THEN
    `(bvalf D (E:A->A->bool) B leq (v:num->A)
        (!! 1 ((1 %% 0) --> (?? 2 (2 %% 1))))) IN D /\
     (E:A->A->bool)
       (bvalf D E B leq v (!! 1 ((1 %% 0) --> (?? 2 (2 %% 1))))) B`
    STRIP_ASSUME_TAC THENL
   [CONJ_TAC THENL
     [MP_TAC(ISPECL [`(!! 1 ((1 %% 0) --> (?? 2 (2 %% 1)))):form`;`D:A->bool`;
        `E:A->A->bool`;`B:A`;`leq:A`;`v:num->A`] BVALF_SPEC) THEN
      ASM_REWRITE_TAC[] THEN DISCH_THEN(ACCEPT_TAC o CONJUNCT1);
      MP_TAC(ISPECL [`(!! 1 ((1 %% 0) --> (?? 2 (2 %% 1)))):form`;`D:A->bool`;
        `E:A->A->bool`;`B:A`;`leq:A`;`v:num->A`] BVALF_IN_B) THEN
      ASM_REWRITE_TAC[]];
    ALL_TAC] THEN
  (* ---- [[1%%0]]_vm = imx ---- *)
  SUBGOAL_THEN `bvalf D (E:A->A->bool) B leq (vm:num->A) (1 %% 0) = imx`
    ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`m:A`;`x:A`;
       `bvalf D E B leq (vm:num->A) (1 %% 0)`;`imx:A`] EBV_IN_UNIQUE) THEN
    ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
     [MP_TAC(ISPECL [`(1 %% 0):form`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
        `vm:num->A`] BVALF_SPEC) THEN ASM_REWRITE_TAC[] THEN
      DISCH_THEN(ACCEPT_TAC o CONJUNCT1);
      SUBGOAL_THEN `m = (vm:num->A) 1 /\ x = (vm:num->A) 0`
        (CONJUNCTS_THEN SUBST1_TAC) THENL
       [ASM_MESON_TAC[]; ALL_TAC] THEN
      MATCH_MP_TAC(ISPECL [`1`;`0`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
         `vm:num->A`] BVALF_MEM) THEN ASM_REWRITE_TAC[]];
    ALL_TAC] THEN
  (* ---- dp1 = meet(p1v, imx) ;  dp1 <= ne  (P1_NONEMPTY_LE) ---- *)
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
     `bvalf D E B leq (v:num->A)
      (!! 1 ((1 %% 0) --> (?? 2 (2 %% 1))))`;`imx:A`]
    EBALG_MEET) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `dp1:A` ASSUME_TAC) THEN
  SUBGOAL_THEN `(dp1:A) IN D /\ (E:A->A->bool) dp1 B` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[EMEET_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq dp1
                  (bvalf D E B leq (vm:num->A) (?? 2 (2 %% 1)))`
    (LABEL_TAC "dp1_ne") THENL
   [MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`v:num->A`;`m:A`;
       `dp1:A`] P1_NONEMPTY_LE) THEN
    EXPAND_TAC "vm" THEN ASM_REWRITE_TAC[] THEN DISCH_THEN MATCH_MP_TAC THEN
    SUBGOAL_THEN
      `bvalf D (E:A->A->bool) B leq ((1 |-> m) (v:num->A)) (1 %% 0) = imx`
      SUBST1_TAC THENL
     [EXPAND_TAC "vm" THEN FIRST_ASSUM(fun th -> MP_TAC th THEN
        EXPAND_TAC "vm" THEN DISCH_THEN ACCEPT_TAC);
      ASM_REWRITE_TAC[]];
    ALL_TAC] THEN
  (* ---- pimx = meet(prem, imx) ;  pimx <= ne ---- *)
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`prem:A`;`imx:A`]
    EBALG_MEET) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `pimx:A` ASSUME_TAC) THEN
  SUBGOAL_THEN `(pimx:A) IN D /\ (E:A->A->bool) pimx B` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[EMEET_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq pimx prem /\
                erel D (E:A->A->bool) leq pimx imx`
    STRIP_ASSUME_TAC THENL
   [MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`prem:A`;`imx:A`;
       `pimx:A`] EMEET_LE) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq pimx
                  (bvalf D E B leq (v:num->A)
                   (!! 1 ((1 %% 0) --> (?? 2 (2 %% 1)))))`
    ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`pimx:A`;`prem:A`;
                  `bvalf D E B leq (v:num->A)
                   (!! 1 ((1 %% 0) --> (?? 2 (2 %% 1))))`]
      EPORDER_TRANS) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq pimx dp1` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
       `bvalf D E B leq (v:num->A)
        (!! 1 ((1 %% 0) --> (?? 2 (2 %% 1))))`;`imx:A`;
       `dp1:A`;`pimx:A`] EMEET_GREATEST) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq pimx
                  (bvalf D E B leq (vm:num->A) (?? 2 (2 %% 1)))`
    (LABEL_TAC "pimx_ne") THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`pimx:A`;`dp1:A`;
                  `bvalf D E B leq (vm:num->A) (?? 2 (2 %% 1))`]
                   EPORDER_TRANS) THEN
    ASM_REWRITE_TAC[] THEN USE_THEN "dp1_ne" ACCEPT_TAC; ALL_TAC] THEN
  (* ---- wn = meet(w, ne) ;  wn <= K ---- *)
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`w:A`;
     `bvalf D E B leq (vm:num->A) (?? 2 (2 %% 1))`] EBALG_MEET) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `wn:A` ASSUME_TAC) THEN
  SUBGOAL_THEN `(wn:A) IN D /\ (E:A->A->bool) wn B` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[EMEET_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `emeet D (E:A->A->bool) B leq
                  (bvalf D E B leq (vm:num->A) (?? 2 (2 %% 1))) w wn`
    ASSUME_TAC THENL
   [MATCH_MP_TAC EMEET_SYM THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq wn K` (LABEL_TAC "wn_K") THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
       `bvalf D E B leq (vm:num->A) (?? 2 (2 %% 1))`;`w:A`;`K:A`;
       `rhs:A`;`wn:A`]
      EBIMP_MEET_LE) THEN ASM_REWRITE_TAC[] THEN USE_THEN "ne_le" ACCEPT_TAC;
    ALL_TAC] THEN
  (* ---- (6): FINAL_COMBINE_LE => pw <= K ---- *)
  MATCH_MP_TAC(ISPECL
               [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`prem:A`;`imx:A`;
                `z20:A`;`bvalf D E B leq (vm:num->A) (?? 2 (2 %% 1))`;`w:A`;
                `pw:A`;`wn:A`;
                `pimx:A`;`K:A`] FINAL_COMBINE_LE) THEN
  ASM_REWRITE_TAC[] THEN USE_THEN "pimx_ne" ACCEPT_TAC);;

(* ========================================================================= *)
(* CHOICE (C-E): CSEL_EXIST (EXISTENCE outer reduction O1-O4) and the        *)
(* c-value UPPER bound CSEL_SECTION_LE (dual of CSEL_SECTION_GE,             *)
(* UNIQUENESS).                                                              *)
(* ========================================================================= *)

let CSEL_EXIST = prove
 (`!D (E:A->A->bool) B leq ra W x DD g c vc vf v t tinx prem pmt K.
     model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
     x IN D /\ bname D E B x /\
     W IN D /\ ra IN D /\ DD IN D /\ g IN D /\ c IN D /\
     (!q. q IN D /\ E q W ==> bname D E B q) /\
     (!q b pr. q IN D /\ b IN D /\ pr IN D /\
               eopair D E q b pr /\ E pr g ==> E b B) /\
     valuation D vc /\ vc 1 = leq /\ vc 2 = B /\ vc 4 = ra /\ vc 5 = W /\
     vc 15 = x /\
     (!w. w IN D
          ==> (E w g <=>
               ?u. u IN D /\ E u DD /\
                   holds D E ((20 |-> w)((16 |-> u) vc)) phi_c)) /\
     valuation D vf /\ vf 1 = leq /\ vf 2 = B /\ vf 15 = g /\
     (!w. w IN D
          ==> (E w c <=>
               ?pp. pp IN D /\ E pp W /\
                    holds D E ((20 |-> w)((16 |-> pp) vf)) phi_func)) /\
     bname D E B c /\
     valuation D v /\ (!k. bname D E B (v k)) /\
     v 0 = x /\ v 1 = t /\ v 4 = c /\
     t IN D /\ bname D E B t /\
     (!m qq blk. m IN D /\ eindom D E x m /\ qq IN D /\ E qq W /\
                 eopair D E m qq blk ==> E blk DD) /\
     (!m y. m IN D /\ eindom D E x m /\ y IN D /\ eindom D E m y ==> E y W) /\
     K = bvalf D E B leq v (?? 2 ((2 %% 1) && (2 %% 4))) /\
     prem IN D /\ E prem B /\
     erel D E leq prem
       (bvalf D E B leq v (!! 1 ((1 %% 0) --> (?? 2 (2 %% 1))))) /\
     tinx IN D /\ E tinx B /\ ebv_in D E B leq t x tinx /\
     pmt IN D /\ E pmt B /\ emeet D E B leq prem tinx pmt /\
     (!z. z IN D /\ (!s. s IN D /\ E s z ==> E s W) /\ (?s. s IN D /\ E s z)
          ==> ?p0. p0 IN D /\ E p0 z /\
                  !q. q IN D /\ E q z /\ ~(q = p0) ==> erel D E ra p0 q) /\
     (!u u'. u IN D /\ u' IN D /\ erel D E ra u u' ==> ~(erel D E ra u' u))
     ==> erel D E leq pmt K`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `ebalg D (E:A->A->bool) B leq` ASSUME_TAC THENL
   [ASM_MESON_TAC[ECBA_IMP_BALG]; ALL_TAC] THEN
  SUBGOAL_THEN `eporder D (E:A->A->bool) B leq` ASSUME_TAC THENL
   [ASM_MESON_TAC[EBALG_IMP_PORDER]; ALL_TAC] THEN
  (* ---- K IN D /\ E K B ---- *)
  SUBGOAL_THEN `(K:A) IN D /\ (E:A->A->bool) K B` STRIP_ASSUME_TAC THENL
   [SUBGOAL_THEN `K = bvalf D (E:A->A->bool) B leq (v:num->A)
                        (?? 2 ((2 %% 1) && (2 %% 4)))` SUBST1_TAC THENL
     [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    CONJ_TAC THENL
     [MP_TAC(ISPECL [`(?? 2 ((2 %% 1) && (2 %% 4))):form`;`D:A->bool`;
        `E:A->A->bool`;`B:A`;`leq:A`;`v:num->A`] BVALF_SPEC) THEN
      ASM_REWRITE_TAC[] THEN DISCH_THEN(ACCEPT_TAC o CONJUNCT1);
      MP_TAC(ISPECL [`(?? 2 ((2 %% 1) && (2 %% 4))):form`;`D:A->bool`;
        `E:A->A->bool`;`B:A`;`leq:A`;`v:num->A`] BVALF_IN_B) THEN
      ASM_REWRITE_TAC[]];
    ALL_TAC] THEN
  (* ---- build rhs = (prem ==> K) ---- *)
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`prem:A`;`K:A`]
    EBIMP_EXISTS) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `rhs:A` ASSUME_TAC) THEN
  SUBGOAL_THEN `(rhs:A) IN D /\ (E:A->A->bool) rhs B` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[EBIMP_IN]; ALL_TAC] THEN
  (* ---- O2: tinx <= rhs via EBV_IN_LE_V (u:=t,v:=x,z:=tinx,w0:=rhs) ---- *)
  SUBGOAL_THEN `erel D (E:A->A->bool) leq tinx rhs` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`t:A`;`x:A`;
       `tinx:A`;`rhs:A`] EBV_IN_LE_V) THEN
    ASM_REWRITE_TAC[] THEN
    MAP_EVERY X_GEN_TAC [`y:A`;`qy:A`;`ey:A`;`cc:A`] THEN STRIP_TAC THEN
    (* eindom x y *)
    SUBGOAL_THEN `eindom D (E:A->A->bool) x y` ASSUME_TAC THENL
     [REWRITE_TAC[eindom] THEN EXISTS_TAC `qy:A` THEN ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    (* bname y *)
    SUBGOAL_THEN `bname D (E:A->A->bool) B y` ASSUME_TAC THENL
     [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`x:A`;`y:A`]
        UNION_DOM_BNAME) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    (* E qy B  (value of the bname x) *)
    SUBGOAL_THEN `(E:A->A->bool) qy B` ASSUME_TAC THENL
     [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`x:A`;`y:A`;`qy:A`]
        BNAME_APPLY_IN_B) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    (* E ey B  (value of ebv_eq t y) *)
    SUBGOAL_THEN `(E:A->A->bool) ey B` ASSUME_TAC THENL
     [MATCH_MP_TAC(ISPECL
                   [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`t:A`;`y:A`;
                    `ey:A`] EBV_EQ_IN_B) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    (* E cc B  (cc = meet qy ey) *)
    SUBGOAL_THEN `(cc:A) IN D /\ (E:A->A->bool) cc B` STRIP_ASSUME_TAC THENL
     [ASM_MESON_TAC[EMEET_IN]; ALL_TAC] THEN
    (* imx = [[y in x]] *)
    MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`y:A`;`x:A`]
      EBV_IN_VAL_EXISTS) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(X_CHOOSE_THEN `imx:A` STRIP_ASSUME_TAC) THEN
    (* ebv_eq y t ey via EBV_EQ_SYM *)
    SUBGOAL_THEN `ebv_eq D (E:A->A->bool) B leq y t ey` ASSUME_TAC THENL
     [MATCH_MP_TAC(ISPECL
                   [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`t:A`;`y:A`;
                    `ey:A`] EBV_EQ_SYM) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    (* wm = meet(imx, ey) *)
    MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`imx:A`;`ey:A`]
      EBALG_MEET) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(X_CHOOSE_THEN `wm:A` ASSUME_TAC) THEN
    SUBGOAL_THEN `(wm:A) IN D /\ (E:A->A->bool) wm B` STRIP_ASSUME_TAC THENL
     [ASM_MESON_TAC[EMEET_IN]; ALL_TAC] THEN
    (* pwm = meet(prem, wm) *)
    MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`prem:A`;`wm:A`]
      EBALG_MEET) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(X_CHOOSE_THEN `pwm:A` ASSUME_TAC) THEN
    SUBGOAL_THEN `(pwm:A) IN D /\ (E:A->A->bool) pwm B` STRIP_ASSUME_TAC THENL
     [ASM_MESON_TAC[EMEET_IN]; ALL_TAC] THEN
    (* qy <= imx via EBV_MEMBER_LE_V (f:=x,v:=y,qv:=qy,z:=imx) *)
    SUBGOAL_THEN `erel D (E:A->A->bool) leq qy imx` ASSUME_TAC THENL
     [MATCH_MP_TAC(ISPECL
                   [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`x:A`;`y:A`;
                    `qy:A`;`imx:A`] EBV_MEMBER_LE_V) THEN ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    (* ey <= ey refl *)
    SUBGOAL_THEN `erel D (E:A->A->bool) leq ey ey` ASSUME_TAC THENL
     [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`ey:A`]
        EPORDER_REFL) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    (* cc <= wm via EMEET_MONO (a:=qy,b:=ey,a':=imx,b':=ey,m:=cc,m':=wm) *)
    SUBGOAL_THEN `erel D (E:A->A->bool) leq cc wm` ASSUME_TAC THENL
     [MATCH_MP_TAC(ISPECL
                   [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`qy:A`;`ey:A`;
                    `imx:A`;`ey:A`;`cc:A`;`wm:A`] EMEET_MONO) THEN
      ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    (* ccp = meet(cc, prem) *)
    MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`cc:A`;`prem:A`]
      EBALG_MEET) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(X_CHOOSE_THEN `ccp:A` ASSUME_TAC) THEN
    SUBGOAL_THEN `(ccp:A) IN D /\ (E:A->A->bool) ccp B` STRIP_ASSUME_TAC THENL
     [ASM_MESON_TAC[EMEET_IN]; ALL_TAC] THEN
    (* ccp <= cc, ccp <= prem *)
    SUBGOAL_THEN `erel D (E:A->A->bool) leq ccp cc /\
                  erel D (E:A->A->bool) leq ccp prem`
      STRIP_ASSUME_TAC THENL
     [MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`cc:A`;`prem:A`;
        `ccp:A`] EMEET_LE) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    (* ccp <= wm (trans ccp<=cc<=wm) *)
    SUBGOAL_THEN `erel D (E:A->A->bool) leq ccp wm` ASSUME_TAC THENL
     [MATCH_MP_TAC(ISPECL
                   [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`ccp:A`;`cc:A`;
                    `wm:A`] EPORDER_TRANS) THEN ASM_REWRITE_TAC[];
                  ALL_TAC] THEN
    (* per-member coverage clauses for CSEL_EXIST_PERM (m:=y) *)
    SUBGOAL_THEN
      `!qq blk. qq IN D /\ (E:A->A->bool) qq W /\ eopair D E y qq blk
                ==> E blk DD`
      ASSUME_TAC THENL [ASM_MESON_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN
      `!y'. y' IN D /\ eindom D (E:A->A->bool) y y' ==> E y' W`
      ASSUME_TAC THENL [ASM_MESON_TAC[]; ALL_TAC] THEN
    (* pwm <= K via CSEL_EXIST_PERM (m:=y, imx, z20:=ey, w:=wm, prem, *)
    (* pw:=pwm) *)
    SUBGOAL_THEN `erel D (E:A->A->bool) leq pwm K` ASSUME_TAC THENL
     [MATCH_MP_TAC(ISPECL
                   [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`ra:A`;`W:A`;
                    `x:A`;`DD:A`;`g:A`;`c:A`;`vc:num->A`;`vf:num->A`;
                    `v:num->A`;`y:A`;`t:A`;
                    `imx:A`;`ey:A`;`wm:A`;`K:A`;`prem:A`;`pwm:A`]
                     CSEL_EXIST_PERM) THEN
      ASM_REWRITE_TAC[]; ALL_TAC] THEN
    (* ccp <= pwm via EMEET_GREATEST(prem,wm,pwm,ccp) *)
    SUBGOAL_THEN `erel D (E:A->A->bool) leq ccp pwm` ASSUME_TAC THENL
     [MATCH_MP_TAC(ISPECL
                   [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`prem:A`;`wm:A`;
                    `pwm:A`;`ccp:A`] EMEET_GREATEST) THEN ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    (* ccp <= K trans *)
    SUBGOAL_THEN `erel D (E:A->A->bool) leq ccp K` ASSUME_TAC THENL
     [MATCH_MP_TAC(ISPECL
                   [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`ccp:A`;`pwm:A`;
                    `K:A`] EPORDER_TRANS) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    (* cc <= rhs via EBIMP_LE_IMP (a:=cc,b:=prem,c:=K,i:=rhs,m:=ccp) *)
    MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`cc:A`;`prem:A`;
                  `K:A`;`rhs:A`;`ccp:A`] EBIMP_LE_IMP) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* ---- O1-back: from tinx<=rhs derive pmt<=K ---- *)
  (* mtp = meet(tinx, prem) *)
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`tinx:A`;`prem:A`]
    EBALG_MEET) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `mtp:A` ASSUME_TAC) THEN
  SUBGOAL_THEN `(mtp:A) IN D /\ (E:A->A->bool) mtp B` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[EMEET_IN]; ALL_TAC] THEN
  (* mtp <= K via EBIMP_MEET_LE(a:=tinx,b:=prem,c:=K,i:=rhs,m:=mtp) *)
  SUBGOAL_THEN `erel D (E:A->A->bool) leq mtp K` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`tinx:A`;`prem:A`;
                  `K:A`;`rhs:A`;`mtp:A`] EBIMP_MEET_LE) THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  (* pmt = mtp  (emeet prem tinx pmt given, emeet prem tinx mtp from *)
  (* EMEET_SYM) *)
  SUBGOAL_THEN `pmt:A = mtp` SUBST1_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`prem:A`;`tinx:A`;
                  `pmt:A`;`mtp:A`] EMEET_UNIQUE) THEN
    ASM_REWRITE_TAC[] THEN MATCH_MP_TAC EMEET_SYM THEN ASM_REWRITE_TAC[];
    FIRST_ASSUM ACCEPT_TAC]);;

(* CSEL_SECTION_LE: c-value UPPER bound (dual of CSEL_SECTION_GE).           *)
(* If every g-section value ival at p (i.e. <p,ival> in g) is <= w0, then    *)
(* the selector value c(p)=val <= w0.  val = elub of the section-value set,  *)
(* so this is ELUB_LEAST against the eubound built from the per-section hyp. *)
let CSEL_SECTION_LE = prove
 (`!D (E:A->A->bool) B leq g W v c p val w0.
      model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
      g IN D /\ W IN D /\ valuation D v /\ v 1 = leq /\ v 2 = B /\ v 15 = g /\
      c IN D /\
      (!w. w IN D ==> (E w c <=>
              ?p. p IN D /\ E p W /\
                  holds D E ((20 |-> w)((16 |-> p) v)) phi_func)) /\
      p IN D /\ val IN D /\ eapply D E c p val /\
      w0 IN D /\ E w0 B /\
      (!ival gpair. gpair IN D /\ ival IN D /\ E gpair g /\
                    eopair D E p ival gpair ==> erel D E leq ival w0)
      ==> erel D E leq val w0`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  UNDISCH_TAC `eapply D (E:A->A->bool) c p val` THEN REWRITE_TAC[eapply] THEN
  DISCH_THEN(X_CHOOSE_THEN `zz:A` STRIP_ASSUME_TAC) THEN
  SUBGOAL_THEN `(zz:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[EOPAIR_IN]; ALL_TAC] THEN
  SUBGOAL_THEN
    `?pp. pp IN D /\ E pp W /\
          holds D E ((20|->zz)((16|->pp)(v:num->A))) phi_func`
    STRIP_ASSUME_TAC THENL
   [FIRST_X_ASSUM(fun th ->
        let th1 = SPEC `zz:A` (check(fun t -> free_in `c:A` (concl t)) th) in
        let th2 = MP th1 (ASSUME `(zz:A) IN D`) in
        ACCEPT_TAC(EQ_MP th2 (ASSUME `(E:A->A->bool) zz c`)));
    ALL_TAC] THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`v:num->A`;`pp:A`;`zz:A`]
    PHI_FUNC_DEST) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `vv:A` STRIP_ASSUME_TAC) THEN
  SUBGOAL_THEN `pp:A = p /\ vv:A = val` (CONJUNCTS_THEN SUBST_ALL_TAC) THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`pp:A`;`vv:A`;`p:A`;`val:A`;
                  `zz:A`] EOPAIR_INJ) THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
     `(20|->zz)((16|->p)(v:num->A))`;`val:A`] FUNCVAL_DEST) THEN
  ANTS_TAC THENL
   [REWRITE_TAC[VALMOD; ARITH_EQ] THEN ASM_REWRITE_TAC[] THEN
    ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `VS:A`
    (CONJUNCTS_THEN2 (LABEL_TAC "VSD")
     (CONJUNCTS_THEN2 (LABEL_TAC "VSch") (LABEL_TAC "VSlub")))) THEN
  SUBGOAL_THEN `eubound D (E:A->A->bool) B leq VS w0` ASSUME_TAC THENL
   [REWRITE_TAC[eubound] THEN REPEAT CONJ_TAC THENL
     [FIRST_ASSUM ACCEPT_TAC; FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    X_GEN_TAC `b:A` THEN STRIP_TAC THEN
    USE_THEN "VSch" (fun th ->
       MP_TAC(EQ_MP (MP (SPEC `b:A` th) (ASSUME `(b:A) IN D`))
                    (ASSUME `(E:A->A->bool) b VS`))) THEN
    REWRITE_TAC[VALMOD; ARITH_EQ] THEN ASM_REWRITE_TAC[] THEN
    DISCH_THEN(X_CHOOSE_THEN `pr:A` STRIP_ASSUME_TAC) THEN
    ASM_MESON_TAC[]; ALL_TAC] THEN
  MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`VS:A`;`val:A`;
     `w0:A`] ELUB_LEAST) THEN
  ASM_REWRITE_TAC[]);;

(* ========================================================================= *)
(* CHOICE (C-F): UNIQUENESS, abstract ebalg cores.                           *)
(*                                                                           *)
(* DISJ_CONTRA_ABS: the disjointness contrapositive as a pure                *)
(* Boolean-algebra                                                           *)
(*   fact.  Given a/\~eqmt <= ~exw  and  ymt <= exw,  conclude a/\ymt <=     *)
(* eqmt.                                                                     *)
(*   (Instantiated: eqmt=[[m=t]], exw=[[?w. w in m /\ w in t]],              *)
(*    ymt=[[y in m]]/\[[y in t]], a = prem/\[[m in x]]/\[[t in x]].)         *)
(*                                                                           *)
(* FST_ANTICHAIN_BOT_ABS: two ordered-antichain first-values meet to bottom, *)
(*   = FST_LE_COMPL_ABS o FST_DISJOINT_ABS packaged for the CSEL_UNIQ        *)
(* caller.                                                                   *)
(* ========================================================================= *)

let DISJ_CONTRA_ABS = prove
 (`!D (E:A->A->bool) B leq a ceqmt cexw exw eqmt ymt aceq amymt.
      ebalg D E B leq /\
      a IN D /\ E a B /\ ceqmt IN D /\ E ceqmt B /\
      cexw IN D /\ E cexw B /\ exw IN D /\ E exw B /\
      eqmt IN D /\ E eqmt B /\ ymt IN D /\ E ymt B /\
      ecompl D E B leq eqmt ceqmt /\
      ecompl D E B leq exw cexw /\
      emeet D E B leq a ceqmt aceq /\
      erel D E leq aceq cexw /\
      erel D E leq ymt exw /\
      emeet D E B leq a ymt amymt
      ==> erel D E leq amymt eqmt`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `eporder D (E:A->A->bool) B leq` ASSUME_TAC THENL
   [ASM_MESON_TAC[EBALG_IMP_PORDER]; ALL_TAC] THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`] EBALG_BOT) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `bot:A`) THEN
  SUBGOAL_THEN `(bot:A) IN D /\ (E:A->A->bool) bot B` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[EBOT_IN]; ALL_TAC] THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`] EBALG_TOP) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `top:A`) THEN
  SUBGOAL_THEN `(top:A) IN D /\ (E:A->A->bool) top B` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[ETOP_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `emeet D (E:A->A->bool) B leq exw cexw bot` ASSUME_TAC THENL
   [ASM_MESON_TAC[ECOMPL_MEET_JOIN]; ALL_TAC] THEN
  SUBGOAL_THEN
    `(aceq:A) IN D /\ (E:A->A->bool) aceq B /\ (amymt:A) IN D /\ E amymt B`
    STRIP_ASSUME_TAC THENL [ASM_MESON_TAC[EMEET_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `?t3. emeet D (E:A->A->bool) B leq amymt ceqmt t3`
    STRIP_ASSUME_TAC THENL [ASM_MESON_TAC[EBALG_MEET]; ALL_TAC] THEN
  SUBGOAL_THEN `(t3:A) IN D /\ (E:A->A->bool) t3 B` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[EMEET_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq t3 a` ASSUME_TAC THENL
   [ASM_MESON_TAC[EMEET_LE; EPORDER_TRANS]; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq t3 ceqmt` ASSUME_TAC THENL
   [ASM_MESON_TAC[EMEET_LE]; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq t3 ymt` ASSUME_TAC THENL
   [ASM_MESON_TAC[EMEET_LE; EPORDER_TRANS]; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq t3 aceq` ASSUME_TAC THENL
   [ASM_MESON_TAC[EMEET_GREATEST]; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq t3 cexw` ASSUME_TAC THENL
   [ASM_MESON_TAC[EPORDER_TRANS]; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq t3 exw` ASSUME_TAC THENL
   [ASM_MESON_TAC[EPORDER_TRANS]; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq t3 bot` ASSUME_TAC THENL
   [ASM_MESON_TAC[EMEET_GREATEST]; ALL_TAC] THEN
  SUBGOAL_THEN `ecompl D (E:A->A->bool) B leq ceqmt eqmt` ASSUME_TAC THENL
   [MATCH_MP_TAC ECOMPL_SYM THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
     `amymt:A`;`ceqmt:A`;`eqmt:A`;`t3:A`;`bot:A`] EMEET_BOT_COMPL) THEN
  ASM_REWRITE_TAC[]);;

let FST_ANTICHAIN_BOT_ABS = prove
 (`!D (E:A->A->bool) B leq bp sp csp fp bp' cp' fp' m0 bot.
      ebalg D E B leq /\
      bp IN D /\ E bp B /\ sp IN D /\ E sp B /\ bp' IN D /\ E bp' B /\
      csp IN D /\ cp' IN D /\
      ecompl D E B leq sp csp /\ ecompl D E B leq bp' cp' /\
      emeet D E B leq bp csp fp /\
      fp' IN D /\ E fp' B /\
      erel D E leq fp' bp' /\
      erel D E leq bp' sp /\
      emeet D E B leq fp fp' m0 /\
      ebot D E B leq bot
      ==> m0 = bot`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `(fp:A) IN D /\ (E:A->A->bool) fp B` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[EMEET_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `(cp':A) IN D /\ (E:A->A->bool) cp' B` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[ECOMPL_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq fp cp'` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
       `bp:A`;`sp:A`;`csp:A`;`fp:A`;`bp':A`;`cp':A`] FST_LE_COMPL_ABS) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
     `bp':A`;`cp':A`;`fp:A`;`fp':A`;`m0:A`;`bot:A`] FST_DISJOINT_ABS) THEN
  ASM_REWRITE_TAC[]);;

(* ------------------------------------------------------------------ *)
(* CHOICE (U7 core): pairwise-disjointness of the selector.            *)
(* If w0 is a common lower bound of prem, [[m in x]], [[t in x]],       *)
(* [[y in m]], [[y in t]] and prem forces the antichain formula, then  *)
(* w0 <= [[m = t]].  (Two witnessed members of x sharing an element y   *)
(* must be equal.)  Feeds CSEL_UNIQ via DISJ_CONTRA_ABS.               *)
(* ------------------------------------------------------------------ *)
let P2_DISJOINT_LE = prove
 (`!D (E:A->A->bool) B leq v x m t y prem imx itx eqmt ceqmt yim yit w0.
      model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
      valuation D v /\ (!i. bname D E B (v i)) /\ v 0 = x /\
      m IN D /\ t IN D /\ y IN D /\
      bname D E B m /\ bname D E B t /\ bname D E B y /\
      prem IN D /\ E prem B /\
      erel D E leq prem
        (bvalf D E B leq v
          (!! 1 (!! 2 (((1 %% 0) && ((2 %% 0) && Not(Eq 1 2)))
                       --> Not(?? 3 ((3 %% 1) && (3 %% 2))))))) /\
      imx IN D /\ E imx B /\ ebv_in D E B leq m x imx /\
      itx IN D /\ E itx B /\ ebv_in D E B leq t x itx /\
      eqmt IN D /\ E eqmt B /\ ebv_eq D E B leq m t eqmt /\
      ceqmt IN D /\ E ceqmt B /\ ecompl D E B leq eqmt ceqmt /\
      yim IN D /\ E yim B /\ ebv_in D E B leq y m yim /\
      yit IN D /\ E yit B /\ ebv_in D E B leq y t yit /\
      w0 IN D /\ E w0 B /\
      erel D E leq w0 prem /\ erel D E leq w0 imx /\ erel D E leq w0 itx /\
      erel D E leq w0 yim /\ erel D E leq w0 yit
      ==> erel D E leq w0 eqmt`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `ebalg D (E:A->A->bool) B leq /\ eporder D (E:A->A->bool) B leq`
   STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[ECBA_IMP_BALG; EBALG_IMP_PORDER]; ALL_TAC] THEN
  SUBGOAL_THEN
   `valuation D ((1 |-> m)(v:num->A)) /\
    (!i. bname D (E:A->A->bool) B (((1 |-> m)(v:num->A)) i))`
   STRIP_ASSUME_TAC THENL
   [CONJ_TAC THENL
     [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[];
      MATCH_MP_TAC BNAMEVAL_VALMOD THEN ASM_REWRITE_TAC[]]; ALL_TAC] THEN
  MP_TAC(ISPECL
   [`1`; `!! 2 (((1 %% 0) && ((2 %% 0) && Not(Eq 1 2)))
                --> Not(?? 3 ((3 %% 1) && (3 %% 2))))`;
    `D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`v:num->A`;`m:A`]
     BVALF_ALL_LB) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN DISCH_TAC THEN
  MP_TAC(ISPECL
   [`2`; `((1 %% 0) && ((2 %% 0) && Not(Eq 1 2)))
          --> Not(?? 3 ((3 %% 1) && (3 %% 2)))`;
    `D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`(1 |-> m)(v:num->A)`;`t:A`]
   BVALF_ALL_LB) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN DISCH_TAC THEN
  ABBREV_TAC `V0 = bvalf D (E:A->A->bool) B leq v
      (!! 1 (!! 2 (((1 %% 0) && ((2 %% 0) && Not(Eq 1 2)))
                   --> Not(?? 3 ((3 %% 1) && (3 %% 2))))))` THEN
  ABBREV_TAC `V1 = bvalf D (E:A->A->bool) B leq ((1 |-> m)(v:num->A))
      (!! 2 (((1 %% 0) && ((2 %% 0) && Not(Eq 1 2)))
             --> Not(?? 3 ((3 %% 1) && (3 %% 2)))))` THEN
  ABBREV_TAC
    `imp = bvalf D (E:A->A->bool) B leq ((2 |-> t)((1 |-> m)(v:num->A)))
      (((1 %% 0) && ((2 %% 0) && Not(Eq 1 2)))
       --> Not(?? 3 ((3 %% 1) && (3 %% 2))))` THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq prem imp` ASSUME_TAC THENL
   [ASM_MESON_TAC[EPORDER_TRANS; EPORDER_FIELD]; ALL_TAC] THEN
  SUBGOAL_THEN
   `valuation D ((2 |-> t)((1 |-> m)(v:num->A))) /\
    (!i. bname D (E:A->A->bool) B (((2 |-> t)((1 |-> m)(v:num->A))) i))`
   STRIP_ASSUME_TAC THENL
   [CONJ_TAC THENL
     [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[];
      MATCH_MP_TAC BNAMEVAL_VALMOD THEN ASM_REWRITE_TAC[]]; ALL_TAC] THEN
  MP_TAC(ISPECL
   [`(1 %% 0) && ((2 %% 0) && Not(Eq 1 2))`;
    `Not(?? 3 ((3 %% 1) && (3 %% 2)))`;
    `D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`(2 |-> t)((1 |-> m)(v:num->A))`]
   BVALF_IMP) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  ASM_REWRITE_TAC[] THEN DISCH_TAC THEN
  ABBREV_TAC
    `gv = bvalf D (E:A->A->bool) B leq ((2 |-> t)((1 |-> m)(v:num->A)))
      ((1 %% 0) && ((2 %% 0) && Not(Eq 1 2)))` THEN
  ABBREV_TAC
    `bd = bvalf D (E:A->A->bool) B leq ((2 |-> t)((1 |-> m)(v:num->A)))
      (Not(?? 3 ((3 %% 1) && (3 %% 2))))` THEN
  MP_TAC(ISPECL
   [`?? 3 ((3 %% 1) && (3 %% 2))`;
    `D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`(2 |-> t)((1 |-> m)(v:num->A))`]
   BVALF_NOT) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  ASM_REWRITE_TAC[] THEN DISCH_TAC THEN
  ABBREV_TAC
    `exw = bvalf D (E:A->A->bool) B leq ((2 |-> t)((1 |-> m)(v:num->A)))
      (?? 3 ((3 %% 1) && (3 %% 2)))` THEN
