   ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`y:A`;`m:A`;
      `bvalf D E B leq ((3 |-> y)((2 |-> t)((1 |-> m)(v:num->A))))
       ((3:num) %% 1)`;`yim:A`]
      EBV_IN_UNIQUE) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN
   `bvalf D (E:A->A->bool) B leq ((3 |-> y)((2 |-> t)((1 |-> m)(v:num->A))))
    (3 %% 2) = yit`
   ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`y:A`;`t:A`;
      `bvalf D E B leq ((3 |-> y)((2 |-> t)((1 |-> m)(v:num->A))))
       ((3:num) %% 2)`;`yit:A`]
      EBV_IN_UNIQUE) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN
   `emeet D (E:A->A->bool) B leq yim yit
      (bvalf D E B leq ((3 |-> y)((2 |-> t)((1 |-> m)(v:num->A))))
       ((3 %% 1) && (3 %% 2)))`
   ASSUME_TAC THENL
   [MP_TAC(ISPECL
           [`(3:num) %% 1`;`(3:num) %% 2`;`D:A->bool`;`E:A->A->bool`;
            `B:A`;`leq:A`;
            `(3 |-> y)((2 |-> t)((1 |-> m)(v:num->A)))`] BVALF_AND_MEET) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN
   `bvalf D (E:A->A->bool) B leq ((3 |-> y)((2 |-> t)((1 |-> m)(v:num->A))))
    ((3 %% 1) && (3 %% 2)) = ymt`
   ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`yim:A`;`yit:A`;
                  `bvalf D E B leq ((3 |-> y)((2 |-> t)((1 |-> m)(v:num->A))))
                   ((3 %% 1) && (3 %% 2))`;`ymt:A`]
      EMEET_UNIQUE) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq ymt exw` ASSUME_TAC THENL
   [MP_TAC(ISPECL
           [`3`;`(3 %% 1) && (3 %% 2)`;`D:A->bool`;`E:A->A->bool`;
            `B:A`;`leq:A`;
            `(2 |-> t)((1 |-> m)(v:num->A))`;`y:A`] BVALF_EX_UB) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq w0 ymt` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
      `yim:A`;`yit:A`;`ymt:A`;`w0:A`] EMEET_GREATEST) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `emeet D (E:A->A->bool) B leq w0 ymt w0` ASSUME_TAC THENL
   [REWRITE_TAC[emeet] THEN REPEAT CONJ_TAC THENL
     [FIRST_ASSUM ACCEPT_TAC;
      FIRST_ASSUM ACCEPT_TAC;
      MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`w0:A`]
        EPORDER_REFL) THEN ASM_REWRITE_TAC[];
      FIRST_ASSUM ACCEPT_TAC;
      REPEAT STRIP_TAC THEN FIRST_ASSUM ACCEPT_TAC];
    ALL_TAC] THEN
  MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
   `w0:A`;`ceqmt:A`;`bd:A`;`exw:A`;`eqmt:A`;`ymt:A`;`aceq:A`;`w0:A`]
   DISJ_CONTRA_ABS) THEN ASM_REWRITE_TAC[]);;

(* ========================================================================= *)
(* C-F: two-point selector UNIQUENESS (functionality half of the boolean     *)
(* least-element CHOICE selector c).  Endpoint CSEL_UNIQ.  Supporting        *)
(* lemmas: CSEL_UNIQ_CORE (antichain heart), CSEL_UNIQ_EMM2 (disjointness),  *)
(* CSEL_UNIQ_MAIN (firstsel/sup half), CSEL_UNIQ_PERPAIR (given-values       *)
(* two-point core), CSEL_MEM_REDUCE (per-point reduction) and its tactic     *)
(* helpers. Pairs with CSEL_EXIST for [[choice_ax]] = top (assembled in      *)
(* C-G).                                                                     *)
(* ========================================================================= *)

(* CSEL_UNIQ_CORE: pure-ebalg antichain heart of two-point selector uniqueness.
   Given the exposed Boolean values (first-selector structure at two
     points y,y2 of
   the common set W, the equality [[m=m2]], the two cross-memberships and their
   complements, the two transport bounds,
   the two conditional sup-bounds, the ra
   trichotomy on {y,y2}, and the diagonal fact), conclude  w0 <= [[y=y2]].
   Two symmetric FST_ANTICHAIN_BOT_ABS applications + diagonal (top).
     No bvalf. *)

let CSEL_UNIQ_CORE = prove
 (`!D (E:A->A->bool) B leq ra y y2
      bp sp csp fp bp2 sp2 csp2 fp2
      emm2 bpy2m cbpy2m bym2 cbym2 eyy2 bot w0.
     ebalg D E B leq /\ eporder D E B leq /\
     bp IN D /\ E bp B /\ sp IN D /\ E sp B /\ csp IN D /\ E csp B /\
     fp IN D /\ E fp B /\
     bp2 IN D /\ E bp2 B /\ sp2 IN D /\ E sp2 B /\ csp2 IN D /\ E csp2 B /\
     fp2 IN D /\ E fp2 B /\
     emm2 IN D /\ E emm2 B /\
     bpy2m IN D /\ E bpy2m B /\ cbpy2m IN D /\ E cbpy2m B /\
     bym2 IN D /\ E bym2 B /\ cbym2 IN D /\ E cbym2 B /\
     eyy2 IN D /\ E eyy2 B /\ bot IN D /\ E bot B /\ w0 IN D /\ E w0 B /\
     ecompl D E B leq sp csp /\ ecompl D E B leq sp2 csp2 /\
     ecompl D E B leq bpy2m cbpy2m /\ ecompl D E B leq bym2 cbym2 /\
     emeet D E B leq bp csp fp /\ emeet D E B leq bp2 csp2 fp2 /\
     ebot D E B leq bot /\
     erel D E leq w0 fp /\ erel D E leq w0 fp2 /\ erel D E leq w0 emm2 /\
     (!mt. emeet D E B leq emm2 bp2 mt ==> erel D E leq mt bpy2m) /\
     (!mt. emeet D E B leq emm2 bp mt ==> erel D E leq mt bym2) /\
     (erel D E ra y2 y ==> erel D E leq bpy2m sp) /\
     (erel D E ra y y2 ==> erel D E leq bym2 sp2) /\
     (y = y2 \/ erel D E ra y y2 \/ erel D E ra y2 y) /\
     (y = y2 ==> erel D E leq w0 eyy2)
     ==> erel D E leq w0 eyy2`,
  REPEAT GEN_TAC THEN STRIP_TAC THENL
   [(* ---- diagonal case  y = y2 ---- *)
    ASM_MESON_TAC[];
    (* ================================================================= *)
    (* CASE  erel ra y y2 :  block m2 is ra-first; bym2=[[y in m2]]<=sp2  *)
    (* ================================================================= *)
    SUBGOAL_THEN `erel D (E:A->A->bool) leq bot eyy2` ASSUME_TAC THENL
     [MATCH_MP_TAC(ISPECL
                   [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`bot:A`;`eyy2:A`]
                   EBOT_LE) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN `?g. emeet D (E:A->A->bool) B leq fp emm2 g`
      STRIP_ASSUME_TAC THENL
      [ASM_MESON_TAC[EBALG_MEET]; ALL_TAC] THEN
    SUBGOAL_THEN `(g:A) IN D /\ (E:A->A->bool) g B` STRIP_ASSUME_TAC THENL
     [ASM_MESON_TAC[EMEET_IN]; ALL_TAC] THEN
    SUBGOAL_THEN `?mt. emeet D (E:A->A->bool) B leq emm2 bp mt`
      STRIP_ASSUME_TAC THENL
      [ASM_MESON_TAC[EBALG_MEET]; ALL_TAC] THEN
    SUBGOAL_THEN `(mt:A) IN D /\ (E:A->A->bool) mt B` STRIP_ASSUME_TAC THENL
     [ASM_MESON_TAC[EMEET_IN]; ALL_TAC] THEN
    (* g <= emm2, g <= fp <= bp *)
    SUBGOAL_THEN `erel D (E:A->A->bool) leq g emm2 /\ erel D E leq g fp`
     STRIP_ASSUME_TAC THENL [ASM_MESON_TAC[EMEET_LE]; ALL_TAC] THEN
    SUBGOAL_THEN `erel D (E:A->A->bool) leq fp bp` ASSUME_TAC THENL
     [ASM_MESON_TAC[EMEET_LE]; ALL_TAC] THEN
    SUBGOAL_THEN `erel D (E:A->A->bool) leq g bp` ASSUME_TAC THENL
     [ASM_MESON_TAC[EPORDER_TRANS]; ALL_TAC] THEN
    (* g <= mt = meet(emm2,bp) *)
    SUBGOAL_THEN `erel D (E:A->A->bool) leq g mt` ASSUME_TAC THENL
     [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
         `emm2:A`;`bp:A`;`mt:A`;`g:A`] EMEET_GREATEST) THEN ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    SUBGOAL_THEN `erel D (E:A->A->bool) leq mt bym2` ASSUME_TAC THENL
     [ASM_MESON_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN `erel D (E:A->A->bool) leq g bym2` ASSUME_TAC THENL
     [ASM_MESON_TAC[EPORDER_TRANS]; ALL_TAC] THEN
    (* bym2 <= sp2 from conditional bound *)
    SUBGOAL_THEN `erel D (E:A->A->bool) leq bym2 sp2` ASSUME_TAC THENL
     [ASM_MESON_TAC[]; ALL_TAC] THEN
    (* m0 = meet(fp2,g) *)
    SUBGOAL_THEN `?m0. emeet D (E:A->A->bool) B leq fp2 g m0`
      STRIP_ASSUME_TAC THENL
      [ASM_MESON_TAC[EBALG_MEET]; ALL_TAC] THEN
    SUBGOAL_THEN `(m0:A) = bot` SUBST_ALL_TAC THENL
     [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
         `bp2:A`;`sp2:A`;`csp2:A`;`fp2:A`;`bym2:A`;`cbym2:A`;`g:A`;
         `m0:A`;`bot:A`]
        FST_ANTICHAIN_BOT_ABS) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    (* w0 <= g, w0 <= fp2 => w0 <= bot *)
    SUBGOAL_THEN `erel D (E:A->A->bool) leq w0 g` ASSUME_TAC THENL
     [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
         `fp:A`;`emm2:A`;`g:A`;`w0:A`] EMEET_GREATEST) THEN ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    SUBGOAL_THEN `erel D (E:A->A->bool) leq w0 bot` ASSUME_TAC THENL
     [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
         `fp2:A`;`g:A`;`bot:A`;`w0:A`] EMEET_GREATEST) THEN ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    ASM_MESON_TAC[EPORDER_TRANS];
    (* ================================================================= *)
    (* CASE  erel ra y2 y :  block m is ra-first; bpy2m=[[y2 in m]]<=sp   *)
    (* ================================================================= *)
    SUBGOAL_THEN `erel D (E:A->A->bool) leq bot eyy2` ASSUME_TAC THENL
     [MATCH_MP_TAC(ISPECL
                   [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`bot:A`;`eyy2:A`]
                   EBOT_LE) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN `?g2. emeet D (E:A->A->bool) B leq fp2 emm2 g2`
      STRIP_ASSUME_TAC THENL
      [ASM_MESON_TAC[EBALG_MEET]; ALL_TAC] THEN
    SUBGOAL_THEN `(g2:A) IN D /\ (E:A->A->bool) g2 B` STRIP_ASSUME_TAC THENL
     [ASM_MESON_TAC[EMEET_IN]; ALL_TAC] THEN
    SUBGOAL_THEN `?mt2. emeet D (E:A->A->bool) B leq emm2 bp2 mt2`
      STRIP_ASSUME_TAC THENL
      [ASM_MESON_TAC[EBALG_MEET]; ALL_TAC] THEN
    SUBGOAL_THEN `(mt2:A) IN D /\ (E:A->A->bool) mt2 B` STRIP_ASSUME_TAC THENL
     [ASM_MESON_TAC[EMEET_IN]; ALL_TAC] THEN
    SUBGOAL_THEN `erel D (E:A->A->bool) leq g2 emm2 /\ erel D E leq g2 fp2`
     STRIP_ASSUME_TAC THENL [ASM_MESON_TAC[EMEET_LE]; ALL_TAC] THEN
    SUBGOAL_THEN `erel D (E:A->A->bool) leq fp2 bp2` ASSUME_TAC THENL
     [ASM_MESON_TAC[EMEET_LE]; ALL_TAC] THEN
    SUBGOAL_THEN `erel D (E:A->A->bool) leq g2 bp2` ASSUME_TAC THENL
     [ASM_MESON_TAC[EPORDER_TRANS]; ALL_TAC] THEN
    SUBGOAL_THEN `erel D (E:A->A->bool) leq g2 mt2` ASSUME_TAC THENL
     [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
         `emm2:A`;`bp2:A`;`mt2:A`;`g2:A`] EMEET_GREATEST) THEN
      ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    SUBGOAL_THEN `erel D (E:A->A->bool) leq mt2 bpy2m` ASSUME_TAC THENL
     [ASM_MESON_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN `erel D (E:A->A->bool) leq g2 bpy2m` ASSUME_TAC THENL
     [ASM_MESON_TAC[EPORDER_TRANS]; ALL_TAC] THEN
    SUBGOAL_THEN `erel D (E:A->A->bool) leq bpy2m sp` ASSUME_TAC THENL
     [ASM_MESON_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN `?m0. emeet D (E:A->A->bool) B leq fp g2 m0`
      STRIP_ASSUME_TAC THENL
      [ASM_MESON_TAC[EBALG_MEET]; ALL_TAC] THEN
    SUBGOAL_THEN `(m0:A) = bot` SUBST_ALL_TAC THENL
     [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
         `bp:A`;`sp:A`;`csp:A`;`fp:A`;`bpy2m:A`;`cbpy2m:A`;`g2:A`;
         `m0:A`;`bot:A`]
        FST_ANTICHAIN_BOT_ABS) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN `erel D (E:A->A->bool) leq w0 g2` ASSUME_TAC THENL
     [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
         `fp2:A`;`emm2:A`;`g2:A`;`w0:A`] EMEET_GREATEST) THEN
      ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    SUBGOAL_THEN `erel D (E:A->A->bool) leq w0 bot` ASSUME_TAC THENL
     [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
         `fp:A`;`g2:A`;`bot:A`;`w0:A`] EMEET_GREATEST) THEN ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    ASM_MESON_TAC[EPORDER_TRANS]]);;

(* CSEL_UNIQ_EMM2: the disjointness half of two-point selector uniqueness.
   Two witnessed blocks m,m2 of x that both contain (Boolean) common elements
   y,y2 with y in t and y2 in t, must be Boolean-equal:  w0 <= [[m=m2]].
   [[y in t]] from [[p=y]]/\[[p in t]] (EBV_IN_CONG_L); ditto [[y2 in t]].
   Then P2_DISJOINT_LE twice (w0<=[[m=t]], w0<=[[m2=t]]);
   EBV_EQ_SYM + EBV_EQ_CONG. *)

let CSEL_UNIQ_EMM2 = prove
 (`!D (E:A->A->bool) B leq v x t m m2 y y2 p p2
      prem tinx imx im2x pt p2t py p2y2 bym bp2y2 emm2 w0.
     model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
     valuation D v /\ (!i. bname D E B (v i)) /\ v 0 = x /\
     t IN D /\ m IN D /\ m2 IN D /\ y IN D /\ y2 IN D /\ p IN D /\ p2 IN D /\
     bname D E B t /\ bname D E B m /\ bname D E B m2 /\
     bname D E B y /\ bname D E B y2 /\ bname D E B p /\ bname D E B p2 /\
     prem IN D /\ E prem B /\
     erel D E leq prem
       (bvalf D E B leq v
         (!! 1 (!! 2 (((1 %% 0) && ((2 %% 0) && Not(Eq 1 2)))
                      --> Not(?? 3 ((3 %% 1) && (3 %% 2))))))) /\
     tinx IN D /\ E tinx B /\ ebv_in D E B leq t x tinx /\
     imx IN D /\ E imx B /\ ebv_in D E B leq m x imx /\
     im2x IN D /\ E im2x B /\ ebv_in D E B leq m2 x im2x /\
     pt IN D /\ E pt B /\ ebv_in D E B leq p t pt /\
     p2t IN D /\ E p2t B /\ ebv_in D E B leq p2 t p2t /\
     py IN D /\ E py B /\ ebv_eq D E B leq p y py /\
     p2y2 IN D /\ E p2y2 B /\ ebv_eq D E B leq p2 y2 p2y2 /\
     bym IN D /\ E bym B /\ ebv_in D E B leq y m bym /\
     bp2y2 IN D /\ E bp2y2 B /\ ebv_in D E B leq y2 m2 bp2y2 /\
     emm2 IN D /\ E emm2 B /\ ebv_eq D E B leq m m2 emm2 /\
     w0 IN D /\ E w0 B /\
     erel D E leq w0 prem /\ erel D E leq w0 tinx /\ erel D E leq w0 imx /\
     erel D E leq w0 im2x /\ erel D E leq w0 pt /\ erel D E leq w0 p2t /\
     erel D E leq w0 py /\ erel D E leq w0 p2y2 /\
     erel D E leq w0 bym /\ erel D E leq w0 bp2y2
     ==> erel D E leq w0 emm2`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `ebalg D (E:A->A->bool) B leq /\ eporder D (E:A->A->bool) B leq`
   STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[ECBA_IMP_BALG; EBALG_IMP_PORDER]; ALL_TAC] THEN
  (* ---- yit = [[y in t]] ; w0 <= yit via EBV_IN_CONG_L(p,y,t) ---- *)
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`y:A`;`t:A`]
    EBV_IN_VAL_EXISTS) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `yit:A` STRIP_ASSUME_TAC) THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`py:A`;`pt:A`]
    EBALG_MEET) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `zpy:A` ASSUME_TAC) THEN
  SUBGOAL_THEN `(zpy:A) IN D /\ (E:A->A->bool) zpy B` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[EMEET_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq zpy yit` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
       `p:A`;`y:A`;`t:A`;`py:A`;`pt:A`;`yit:A`;`zpy:A`] EBV_IN_CONG_L) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq w0 zpy` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
       `py:A`;`pt:A`;`zpy:A`;`w0:A`] EMEET_GREATEST) THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq w0 yit` ASSUME_TAC THENL
   [ASM_MESON_TAC[EPORDER_TRANS]; ALL_TAC] THEN
  (* ---- y2t = [[y2 in t]] ; w0 <= y2t via EBV_IN_CONG_L(p2,y2,t) ---- *)
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`y2:A`;`t:A`]
    EBV_IN_VAL_EXISTS) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `y2t:A` STRIP_ASSUME_TAC) THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`p2y2:A`;`p2t:A`]
    EBALG_MEET) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `zp2y:A` ASSUME_TAC) THEN
  SUBGOAL_THEN `(zp2y:A) IN D /\ (E:A->A->bool) zp2y B` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[EMEET_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq zp2y y2t` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
       `p2:A`;`y2:A`;`t:A`;`p2y2:A`;`p2t:A`;`y2t:A`;`zp2y:A`]
           EBV_IN_CONG_L) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq w0 zp2y` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
       `p2y2:A`;`p2t:A`;`zp2y:A`;`w0:A`] EMEET_GREATEST) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq w0 y2t` ASSUME_TAC THENL
   [ASM_MESON_TAC[EPORDER_TRANS]; ALL_TAC] THEN
  (* ---- eqmt = [[m=t]] + complement, then P2_DISJOINT_LE => w0 <= eqmt *)
  (* ---- *)
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`m:A`;`t:A`]
    EBV_EQ_VAL_EXISTS) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `eqmt:A` STRIP_ASSUME_TAC) THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`eqmt:A`]
    EBALG_COMPL) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `ceqmt:A` ASSUME_TAC) THEN
  SUBGOAL_THEN `(ceqmt:A) IN D /\ (E:A->A->bool) ceqmt B`
    STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[ECOMPL_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq w0 eqmt` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`v:num->A`;`x:A`;
                  `m:A`;`t:A`;`y:A`;`prem:A`;`imx:A`;`tinx:A`;`eqmt:A`;
                  `ceqmt:A`;`bym:A`;
                  `yit:A`;`w0:A`] P2_DISJOINT_LE) THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  (* ---- em2t = [[m2=t]] + complement, then P2_DISJOINT_LE => w0 <= em2t *)
  (* ---- *)
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`m2:A`;`t:A`]
    EBV_EQ_VAL_EXISTS) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `em2t:A` STRIP_ASSUME_TAC) THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`em2t:A`]
    EBALG_COMPL) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `cem2t:A` ASSUME_TAC) THEN
  SUBGOAL_THEN `(cem2t:A) IN D /\ (E:A->A->bool) cem2t B`
    STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[ECOMPL_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq w0 em2t` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`v:num->A`;`x:A`;
                  `m2:A`;`t:A`;`y2:A`;`prem:A`;`im2x:A`;`tinx:A`;`em2t:A`;
                  `cem2t:A`;`bp2y2:A`;
                  `y2t:A`;`w0:A`] P2_DISJOINT_LE) THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  (* ---- [[t=m2]] = em2t (EBV_EQ_SYM); EBV_EQ_CONG(m,t,m2) => w0 <= emm2 *)
  (* ---- *)
  SUBGOAL_THEN `ebv_eq D (E:A->A->bool) B leq t m2 em2t` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`m2:A`;`t:A`;
       `em2t:A`] EBV_EQ_SYM) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`eqmt:A`;`em2t:A`]
    EBALG_MEET) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `zc:A` ASSUME_TAC) THEN
  SUBGOAL_THEN `(zc:A) IN D /\ (E:A->A->bool) zc B` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[EMEET_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq zc emm2` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
       `m:A`;`t:A`;`m2:A`;`eqmt:A`;`em2t:A`;`emm2:A`;`zc:A`] EBV_EQ_CONG) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq w0 zc` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
       `eqmt:A`;`em2t:A`;`zc:A`;`w0:A`] EMEET_GREATEST) THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  ASM_MESON_TAC[EPORDER_TRANS]);;

(* CSEL_UNIQ_MAIN: the firstsel/sup-bound/antichain half of two-point selector
   uniqueness.  Given the destructured first-selector data at two W-points y,y2
   for two blocks m,m2 (bp,sp,csp,fp,Sp and bp2,sp2,csp2,fp2,Sp2), the equal-
   blocks value emm2=[[m=m2]] (w0<=emm2, from CSEL_UNIQ_EMM2), and w0 below
   fp,fp2,[[p=y]],[[p2=y2]], conclude w0 <= [[p=p2]].
   Builds the cross-memberships [[y2 in m]],[[y in m2]] and
     eyy2=[[y=y2]], the two
   Leibniz transports (EBV_IN_CONG_R) and conditional sup-bounds (ELUB_UB), the
   diagonal (EBV_EQ_REFL+ETOP_GE), calls CSEL_UNIQ_CORE (trichotomy antichain),
   then lifts [[y=y2]] to [[p=p2]] (EBV_EQ_CONG twice + EBV_EQ_SYM).
   NB: the trichotomy hyp (y=y2 \/ erel ra y y2 \/
     erel ra y2 y) must reach CORE
   INTACT, so we strip the antecedent with REPEAT_TCL CONJUNCTS_THEN ASSUME_TAC
   (NOT STRIP_TAC, which would case-split the disjunction into 3 goals). *)

let CSEL_UNIQ_MAIN = prove
 (`!D (E:A->A->bool) B leq W ra m m2 y y2 p p2
      bp sp csp fp Sp bp2 sp2 csp2 fp2 Sp2 emm2 py p2y2 epp w0.
     model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
     W IN D /\ ra IN D /\
     m IN D /\ m2 IN D /\ y IN D /\ y2 IN D /\ p IN D /\ p2 IN D /\
     bname D E B m /\ bname D E B m2 /\ bname D E B y /\ bname D E B y2 /\
     bname D E B p /\ bname D E B p2 /\
     E y W /\ E y2 W /\
     bp IN D /\ E bp B /\ ebv_in D E B leq y m bp /\
     sp IN D /\ E sp B /\ csp IN D /\ E csp B /\ fp IN D /\ E fp B /\
     Sp IN D /\
     (!z. z IN D
          ==> (E z Sp <=>
               ?q. q IN D /\ E q W /\ erel D E ra q y /\
                 ebv_in D E B leq q m z)) /\
     elub D E B leq Sp sp /\ ecompl D E B leq sp csp /\
       emeet D E B leq bp csp fp /\
     bp2 IN D /\ E bp2 B /\ ebv_in D E B leq y2 m2 bp2 /\
     sp2 IN D /\ E sp2 B /\ csp2 IN D /\ E csp2 B /\ fp2 IN D /\ E fp2 B /\
     Sp2 IN D /\
     (!z. z IN D
          ==> (E z Sp2 <=>
               ?q. q IN D /\ E q W /\ erel D E ra q y2 /\
                 ebv_in D E B leq q m2 z)) /\
     elub D E B leq Sp2 sp2 /\ ecompl D E B leq sp2 csp2 /\
     emeet D E B leq bp2 csp2 fp2 /\
     emm2 IN D /\ E emm2 B /\ ebv_eq D E B leq m m2 emm2 /\
     py IN D /\ E py B /\ ebv_eq D E B leq p y py /\
     p2y2 IN D /\ E p2y2 B /\ ebv_eq D E B leq p2 y2 p2y2 /\
     epp IN D /\ E epp B /\ ebv_eq D E B leq p p2 epp /\
     (y = y2 \/ erel D E ra y y2 \/ erel D E ra y2 y) /\
     w0 IN D /\ E w0 B /\
     erel D E leq w0 fp /\ erel D E leq w0 fp2 /\ erel D E leq w0 emm2 /\
     erel D E leq w0 py /\ erel D E leq w0 p2y2
     ==> erel D E leq w0 epp`,
  REPEAT GEN_TAC THEN DISCH_THEN(REPEAT_TCL CONJUNCTS_THEN ASSUME_TAC) THEN
  SUBGOAL_THEN `ebalg D (E:A->A->bool) B leq /\ eporder D (E:A->A->bool) B leq`
   STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[ECBA_IMP_BALG; EBALG_IMP_PORDER]; ALL_TAC] THEN
  (* ---- ebv_eq m2 m emm2 (SYM), for transport 1 ---- *)
  SUBGOAL_THEN `ebv_eq D (E:A->A->bool) B leq m2 m emm2` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`m:A`;`m2:A`;
       `emm2:A`] EBV_EQ_SYM) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* ---- bpy2m = [[y2 in m]] + complement ---- *)
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`y2:A`;`m:A`]
    EBV_IN_VAL_EXISTS) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `bpy2m:A` STRIP_ASSUME_TAC) THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`bpy2m:A`]
         EBALG_COMPL) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `cbpy2m:A` ASSUME_TAC) THEN
  SUBGOAL_THEN `(cbpy2m:A) IN D /\ (E:A->A->bool) cbpy2m B`
    STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[ECOMPL_IN]; ALL_TAC] THEN
  (* ---- bym2 = [[y in m2]] + complement ---- *)
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`y:A`;`m2:A`]
    EBV_IN_VAL_EXISTS) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `bym2:A` STRIP_ASSUME_TAC) THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`bym2:A`]
         EBALG_COMPL) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `cbym2:A` ASSUME_TAC) THEN
  SUBGOAL_THEN `(cbym2:A) IN D /\ (E:A->A->bool) cbym2 B`
    STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[ECOMPL_IN]; ALL_TAC] THEN
  (* ---- eyy2 = [[y=y2]] ---- *)
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`y:A`;`y2:A`]
    EBV_EQ_VAL_EXISTS) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `eyy2:A` STRIP_ASSUME_TAC) THEN
  (* ---- bot ---- *)
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`] EBALG_BOT) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `bot:A`) THEN
  SUBGOAL_THEN `(bot:A) IN D /\ (E:A->A->bool) bot B` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[EBOT_IN]; ALL_TAC] THEN
  (* ---- transport 1: !mt. emeet emm2 bp2 mt ==> erel mt bpy2m ---- *)
  SUBGOAL_THEN
    `!mt. emeet D (E:A->A->bool) B leq emm2 bp2 mt ==> erel D E leq mt bpy2m`
    ASSUME_TAC THENL
   [X_GEN_TAC `mt:A` THEN DISCH_TAC THEN
    SUBGOAL_THEN `(mt:A) IN D /\ (E:A->A->bool) mt B` STRIP_ASSUME_TAC THENL
     [ASM_MESON_TAC[EMEET_IN]; ALL_TAC] THEN
    MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`m2:A`;`m:A`;
       `y2:A`;`emm2:A`;`bp2:A`;`bpy2m:A`;`mt:A`] EBV_IN_CONG_R) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* ---- transport 2: !mt. emeet emm2 bp mt ==> erel mt bym2 ---- *)
  SUBGOAL_THEN
    `!mt. emeet D (E:A->A->bool) B leq emm2 bp mt ==> erel D E leq mt bym2`
    ASSUME_TAC THENL
   [X_GEN_TAC `mt:A` THEN DISCH_TAC THEN
    SUBGOAL_THEN `(mt:A) IN D /\ (E:A->A->bool) mt B` STRIP_ASSUME_TAC THENL
     [ASM_MESON_TAC[EMEET_IN]; ALL_TAC] THEN
    MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`m:A`;`m2:A`;
       `y:A`;`emm2:A`;`bp:A`;`bym2:A`;`mt:A`] EBV_IN_CONG_R) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* ---- conditional sup-bound 1: erel ra y2 y ==> erel bpy2m sp ---- *)
  SUBGOAL_THEN `erel D (E:A->A->bool) ra y2 y ==> erel D E leq bpy2m sp`
    ASSUME_TAC THENL
   [DISCH_TAC THEN
    SUBGOAL_THEN `(E:A->A->bool) bpy2m Sp` ASSUME_TAC THENL
     [ASM_MESON_TAC[]; ALL_TAC] THEN
    MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`Sp:A`;`sp:A`;
                  `bpy2m:A`] ELUB_UB) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* ---- conditional sup-bound 2: erel ra y y2 ==> erel bym2 sp2 ---- *)
  SUBGOAL_THEN `erel D (E:A->A->bool) ra y y2 ==> erel D E leq bym2 sp2`
    ASSUME_TAC THENL
   [DISCH_TAC THEN
    SUBGOAL_THEN `(E:A->A->bool) bym2 Sp2` ASSUME_TAC THENL
     [ASM_MESON_TAC[]; ALL_TAC] THEN
    MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`Sp2:A`;`sp2:A`;
                  `bym2:A`] ELUB_UB) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* ---- diagonal: y = y2 ==> erel w0 eyy2 ---- *)
  SUBGOAL_THEN `y:A = y2 ==> erel D (E:A->A->bool) leq w0 eyy2`
    ASSUME_TAC THENL
   [DISCH_THEN SUBST_ALL_TAC THEN
    SUBGOAL_THEN `etop D (E:A->A->bool) B leq eyy2` ASSUME_TAC THENL
     [MATCH_MP_TAC(ISPECL
                   [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`y2:A`;`eyy2:A`]
                   EBV_EQ_REFL) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`eyy2:A`;`w0:A`]
                 ETOP_GE) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* ---- CSEL_UNIQ_CORE => erel w0 eyy2 ---- *)
  SUBGOAL_THEN `erel D (E:A->A->bool) leq w0 eyy2` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`ra:A`;`y:A`;
       `y2:A`;`bp:A`;`sp:A`;`csp:A`;`fp:A`;`bp2:A`;`sp2:A`;`csp2:A`;`fp2:A`;
       `emm2:A`;`bpy2m:A`;`cbpy2m:A`;`bym2:A`;`cbym2:A`;`eyy2:A`;
       `bot:A`;`w0:A`]
      CSEL_UNIQ_CORE) THEN
    ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[]; ALL_TAC] THEN
  (* ================= U4-lift: [[y=y2]] -> [[p=p2]] ================= *)
  (* pyy2 = [[p=y2]] ; [[p=y]]/\[[y=y2]] <= [[p=y2]] (EBV_EQ_CONG p y y2) *)
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`p:A`;`y2:A`]
    EBV_EQ_VAL_EXISTS) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `pyy2:A` STRIP_ASSUME_TAC) THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`py:A`;`eyy2:A`]
    EBALG_MEET) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `zc1:A` ASSUME_TAC) THEN
  SUBGOAL_THEN `(zc1:A) IN D /\ (E:A->A->bool) zc1 B` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[EMEET_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq zc1 pyy2` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
       `p:A`;`y:A`;`y2:A`;`py:A`;`eyy2:A`;`pyy2:A`;`zc1:A`] EBV_EQ_CONG) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq w0 zc1` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
       `py:A`;`eyy2:A`;`zc1:A`;`w0:A`] EMEET_GREATEST) THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq w0 pyy2` ASSUME_TAC THENL
   [ASM_MESON_TAC[EPORDER_TRANS]; ALL_TAC] THEN
  (* ebv_eq y2 p2 p2y2 (SYM), then [[p=y2]]/\[[y2=p2]] <= [[p=p2]] *)
  SUBGOAL_THEN `ebv_eq D (E:A->A->bool) B leq y2 p2 p2y2` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`p2:A`;`y2:A`;
                  `p2y2:A`] EBV_EQ_SYM) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`pyy2:A`;`p2y2:A`]
    EBALG_MEET) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `zc2:A` ASSUME_TAC) THEN
  SUBGOAL_THEN `(zc2:A) IN D /\ (E:A->A->bool) zc2 B` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[EMEET_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq zc2 epp` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
       `p:A`;`y2:A`;`p2:A`;`pyy2:A`;`p2y2:A`;`epp:A`;`zc2:A`] EBV_EQ_CONG) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq w0 zc2` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
       `pyy2:A`;`p2y2:A`;`zc2:A`;`w0:A`] EMEET_GREATEST) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  ASM_MESON_TAC[EPORDER_TRANS]);;

(* CSEL_UNIQ_PERPAIR: the given-values two-point core.  Given the
  two block-meets
   cc = ([[m in x]] MEET first(m,y)) MEET [[p=y]]  and
   cc2 = ([[m2 in x]] MEET first(m2,y2)) MEET [[p2=y2]] (with the firstsel data
   at y and y2 fully destructured),
   the four raw factors prem/[[t in x]]/[[p in t]]/
   [[p2 in t]], the W-trichotomy on y,y2, and w0 a common lower bound of
   {cc, cc2, prem, tinx, pt, p2t}, conclude w0 <= [[p=p2]].
   Chains w0 <= cc/cc2 down to the block components (EMEET_LE + trans), builds
   emm2=[[m=m2]],
   calls CSEL_UNIQ_EMM2 (w0<=emm2) then CSEL_UNIQ_MAIN (w0<=epp). *)
let CSEL_UNIQ_PERPAIR =
  (* CSU_TR: transitivity helper. Proves `erel D E leq w0 tgt` from
     assumptions `erel D E leq w0 mid` and `erel D E leq mid tgt`
     (EPORDER_TRANS; the eporder, IN D and E _ B side conditions all
     discharged by ASM_REWRITE). *)
  let CSU_TR mid tgt =
    MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
                         `w0:A`;mid;tgt] EPORDER_TRANS) THEN
    ASM_REWRITE_TAC[] in
  prove
 (`!D (E:A->A->bool) B leq v x t W ra m m2 y y2 p p2
      prem tinx imx im2x pt p2t py p2y2
      bp sp csp fp Sp bp2 sp2 csp2 fp2 Sp2 ival cc ival2 cc2 epp w0.
     model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
     valuation D v /\ (!i. bname D E B (v i)) /\ v 0 = x /\
     W IN D /\ ra IN D /\
     t IN D /\ m IN D /\ m2 IN D /\ y IN D /\ y2 IN D /\ p IN D /\ p2 IN D /\
     bname D E B t /\ bname D E B m /\ bname D E B m2 /\
     bname D E B y /\ bname D E B y2 /\ bname D E B p /\ bname D E B p2 /\
     E y W /\ E y2 W /\
     prem IN D /\ E prem B /\
     erel D E leq prem
       (bvalf D E B leq v
         (!! 1 (!! 2 (((1 %% 0) && ((2 %% 0) && Not(Eq 1 2)))
                      --> Not(?? 3 ((3 %% 1) && (3 %% 2))))))) /\
     tinx IN D /\ E tinx B /\ ebv_in D E B leq t x tinx /\
     imx IN D /\ E imx B /\ ebv_in D E B leq m x imx /\
     im2x IN D /\ E im2x B /\ ebv_in D E B leq m2 x im2x /\
     pt IN D /\ E pt B /\ ebv_in D E B leq p t pt /\
     p2t IN D /\ E p2t B /\ ebv_in D E B leq p2 t p2t /\
     py IN D /\ E py B /\ ebv_eq D E B leq p y py /\
     p2y2 IN D /\ E p2y2 B /\ ebv_eq D E B leq p2 y2 p2y2 /\
     bp IN D /\ E bp B /\ ebv_in D E B leq y m bp /\
     sp IN D /\ E sp B /\ csp IN D /\ E csp B /\ fp IN D /\ E fp B /\
     Sp IN D /\
     (!z. z IN D
          ==> (E z Sp <=>
               ?q. q IN D /\ E q W /\ erel D E ra q y /\
                 ebv_in D E B leq q m z)) /\
     elub D E B leq Sp sp /\ ecompl D E B leq sp csp /\
       emeet D E B leq bp csp fp /\
     bp2 IN D /\ E bp2 B /\ ebv_in D E B leq y2 m2 bp2 /\
     sp2 IN D /\ E sp2 B /\ csp2 IN D /\ E csp2 B /\ fp2 IN D /\ E fp2 B /\
     Sp2 IN D /\
     (!z. z IN D
          ==> (E z Sp2 <=>
               ?q. q IN D /\ E q W /\ erel D E ra q y2 /\
                 ebv_in D E B leq q m2 z)) /\
     elub D E B leq Sp2 sp2 /\ ecompl D E B leq sp2 csp2 /\
     emeet D E B leq bp2 csp2 fp2 /\
     ival IN D /\ E ival B /\ emeet D E B leq imx fp ival /\
     cc IN D /\ E cc B /\ emeet D E B leq ival py cc /\
     ival2 IN D /\ E ival2 B /\ emeet D E B leq im2x fp2 ival2 /\
     cc2 IN D /\ E cc2 B /\ emeet D E B leq ival2 p2y2 cc2 /\
     epp IN D /\ E epp B /\ ebv_eq D E B leq p p2 epp /\
     (y = y2 \/ erel D E ra y y2 \/ erel D E ra y2 y) /\
     w0 IN D /\ E w0 B /\
     erel D E leq w0 cc /\ erel D E leq w0 cc2 /\ erel D E leq w0 prem /\
     erel D E leq w0 tinx /\ erel D E leq w0 pt /\ erel D E leq w0 p2t
     ==> erel D E leq w0 epp`,
  REPEAT GEN_TAC THEN DISCH_THEN(REPEAT_TCL CONJUNCTS_THEN ASSUME_TAC) THEN
  SUBGOAL_THEN `ebalg D (E:A->A->bool) B leq /\ eporder D (E:A->A->bool) B leq`
   STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[ECBA_IMP_BALG; EBALG_IMP_PORDER]; ALL_TAC] THEN
  (* ---- EMEET_LE projections ---- *)
  SUBGOAL_THEN `erel D (E:A->A->bool) leq cc ival /\ erel D E leq cc py`
    STRIP_ASSUME_TAC THENL
   [MP_TAC(ISPECL
           [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`ival:A`;`py:A`;`cc:A`]
           EMEET_LE) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq ival imx /\ erel D E leq ival fp`
    STRIP_ASSUME_TAC THENL
   [MP_TAC(ISPECL
           [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`imx:A`;`fp:A`;`ival:A`]
           EMEET_LE) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq fp bp /\ erel D E leq fp csp`
    STRIP_ASSUME_TAC THENL
   [MP_TAC(ISPECL
           [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`bp:A`;`csp:A`;`fp:A`]
           EMEET_LE) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq cc2 ival2 /\ erel D E leq cc2 p2y2`
    STRIP_ASSUME_TAC THENL
   [MP_TAC(ISPECL
           [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`ival2:A`;
            `p2y2:A`;`cc2:A`]
           EMEET_LE) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq ival2 im2x /\ erel D E leq ival2 fp2`
    STRIP_ASSUME_TAC THENL
   [MP_TAC(ISPECL
           [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`im2x:A`;
            `fp2:A`;`ival2:A`]
           EMEET_LE) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq fp2 bp2 /\ erel D E leq fp2 csp2`
    STRIP_ASSUME_TAC THENL
   [MP_TAC(ISPECL
           [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`bp2:A`;`csp2:A`;`fp2:A`]
           EMEET_LE) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* ---- w0 <= block-y components ---- *)
  SUBGOAL_THEN `erel D (E:A->A->bool) leq w0 ival` ASSUME_TAC THENL
   [CSU_TR `cc:A` `ival:A`; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq w0 py` ASSUME_TAC THENL
   [CSU_TR `cc:A` `py:A`; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq w0 imx` ASSUME_TAC THENL
   [CSU_TR `ival:A` `imx:A`; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq w0 fp` ASSUME_TAC THENL
   [CSU_TR `ival:A` `fp:A`; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq w0 bp` ASSUME_TAC THENL
   [CSU_TR `fp:A` `bp:A`; ALL_TAC] THEN
  (* ---- w0 <= block-y2 components ---- *)
  SUBGOAL_THEN `erel D (E:A->A->bool) leq w0 ival2` ASSUME_TAC THENL
   [CSU_TR `cc2:A` `ival2:A`; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq w0 p2y2` ASSUME_TAC THENL
   [CSU_TR `cc2:A` `p2y2:A`; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq w0 im2x` ASSUME_TAC THENL
   [CSU_TR `ival2:A` `im2x:A`; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq w0 fp2` ASSUME_TAC THENL
   [CSU_TR `ival2:A` `fp2:A`; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq w0 bp2` ASSUME_TAC THENL
   [CSU_TR `fp2:A` `bp2:A`; ALL_TAC] THEN
  (* ---- emm2 = [[m=m2]] ---- *)
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`m:A`;`m2:A`]
    EBV_EQ_VAL_EXISTS) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `emm2:A` STRIP_ASSUME_TAC) THEN
  (* ---- CSEL_UNIQ_EMM2 => w0 <= emm2 ---- *)
  SUBGOAL_THEN `erel D (E:A->A->bool) leq w0 emm2` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`v:num->A`;`x:A`;
                  `t:A`;`m:A`;`m2:A`;`y:A`;`y2:A`;`p:A`;`p2:A`;`prem:A`;
                  `tinx:A`;`imx:A`;
                  `im2x:A`;`pt:A`;`p2t:A`;`py:A`;`p2y2:A`;`bp:A`;`bp2:A`;
                  `emm2:A`;`w0:A`]
      CSEL_UNIQ_EMM2) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* ---- CSEL_UNIQ_MAIN => w0 <= epp ---- *)
  MATCH_MP_TAC(ISPECL
               [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`W:A`;`ra:A`;`m:A`;
                `m2:A`;`y:A`;`y2:A`;`p:A`;`p2:A`;`bp:A`;`sp:A`;`csp:A`;`fp:A`;
                `Sp:A`;`bp2:A`;
                `sp2:A`;`csp2:A`;`fp2:A`;`Sp2:A`;`emm2:A`;`py:A`;`p2y2:A`;
                `epp:A`;`w0:A`]
    CSEL_UNIQ_MAIN) THEN ASM_REWRITE_TAC[]);;

(* CSEL_MEM_REDUCE: reduce [[p in c]] <= WTAR (c the selector graph) to a
   per-point (y in W) / per-g-section obligation with the block m fully
   destructured (imx=[[m in x]], firstsel Sp/sp/csp/bp, fp=first(m,y),
   ival=[[m in x]] MEET first(m,y)).  Composes EBV_IN_LE_V (peel to c-points)
   + residuation + CSEL_SECTION_LE (peel c(y) to g-sections) + PHI_C_DEST +
   DD bname-decomposition + FIRSTSEL_HOLDS_AGREE + FIRSTSEL_DEST.
   The per-instance clause receives ey=[[p=y]] and cc=ival MEET ey, and must
   bound cc <= WTAR.  Used twice (nested) by CSEL_UNIQ. *)

let CSEL_MEM_REDUCE = prove
 (`!D (E:A->A->bool) B leq ra W x DD g c vc vf p pc WTAR.
     model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
     x IN D /\ bname D E B x /\
     W IN D /\ ra IN D /\ DD IN D /\ g IN D /\ c IN D /\
     (!q. q IN D /\ E q W ==> bname D E B q) /\
     (!u. u IN D /\ E u DD
          ==> ?m p. m IN D /\ p IN D /\
                    bname D E B m /\ bname D E B p /\ eopair D E m p u) /\
     valuation D vc /\ vc 1 = leq /\ vc 2 = B /\ vc 4 = ra /\ vc 5 = W /\
     vc 15 = x /\
     (!w. w IN D
          ==> (E w g <=>
               ?u. u IN D /\ E u DD /\
                   holds D E ((20 |-> w)((16 |-> u) vc)) phi_c)) /\
     valuation D vf /\ vf 1 = leq /\ vf 2 = B /\ vf 15 = g /\
     (!w. w IN D
          ==> (E w c <=>
               ?pp. pp IN D /\ E pp W /\
                    holds D E ((20 |-> w)((16 |-> pp) vf)) phi_func)) /\
     bname D E B c /\
     p IN D /\ bname D E B p /\
     pc IN D /\ ebv_in D E B leq p c pc /\
     WTAR IN D /\ E WTAR B /\
     (!y m imx bp sp csp fp Sp ival ey cc.
          y IN D /\ E y W /\ m IN D /\ bname D E B m /\
          imx IN D /\ E imx B /\ ebv_in D E B leq m x imx /\
          bp IN D /\ E bp B /\ ebv_in D E B leq y m bp /\
          Sp IN D /\
          (!z. z IN D
               ==> (E z Sp <=>
                    ?q. q IN D /\ E q W /\ erel D E ra q y /\
                        ebv_in D E B leq q m z)) /\
          sp IN D /\ E sp B /\ elub D E B leq Sp sp /\
          csp IN D /\ E csp B /\ ecompl D E B leq sp csp /\
          fp IN D /\ E fp B /\ emeet D E B leq bp csp fp /\
          ival IN D /\ E ival B /\ emeet D E B leq imx fp ival /\
          ey IN D /\ E ey B /\ ebv_eq D E B leq p y ey /\
          cc IN D /\ E cc B /\ emeet D E B leq ival ey cc
          ==> erel D E leq cc WTAR)
     ==> erel D E leq pc WTAR`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `ebalg D (E:A->A->bool) B leq` ASSUME_TAC THENL
   [ASM_MESON_TAC[ECBA_IMP_BALG]; ALL_TAC] THEN
  SUBGOAL_THEN `eporder D (E:A->A->bool) B leq` ASSUME_TAC THENL
   [ASM_MESON_TAC[EBALG_IMP_PORDER]; ALL_TAC] THEN
  (* ---- reduce [[p in c]] to c-points via EBV_IN_LE_V ---- *)
  MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`p:A`;`c:A`;
     `pc:A`;`WTAR:A`] EBV_IN_LE_V) THEN
  ASM_REWRITE_TAC[] THEN
  MAP_EVERY X_GEN_TAC [`y:A`;`qy:A`;`ey:A`;`cc:A`] THEN STRIP_TAC THEN
  (* eapply c y qy ; extract pr0 = <y,qy> in c *)
  UNDISCH_TAC `eapply D (E:A->A->bool) c y qy` THEN REWRITE_TAC[eapply] THEN
  DISCH_THEN(X_CHOOSE_THEN `pr0:A` STRIP_ASSUME_TAC) THEN
  SUBGOAL_THEN `(pr0:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[EOPAIR_IN]; ALL_TAC] THEN
  (* c-char at pr0 => pp in W with holds phi_func *)
  SUBGOAL_THEN
    `?pp. pp IN D /\ E pp W /\
          holds D E ((20|->pr0)((16|->pp)(vf:num->A))) phi_func`
    STRIP_ASSUME_TAC THENL
   [FIRST_X_ASSUM(fun th ->
        let th1 = SPEC `pr0:A` (check(fun t -> free_in `c:A` (concl t) &&
                                               is_forall(concl t)) th) in
        let th2 = MP th1 (ASSUME `(pr0:A) IN D`) in
        ACCEPT_TAC(EQ_MP th2 (ASSUME `(E:A->A->bool) pr0 c`)));
    ALL_TAC] THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`vf:num->A`;`pp:A`;`pr0:A`]
    PHI_FUNC_DEST) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `vval:A` STRIP_ASSUME_TAC) THEN
  (* pp = y (opair injectivity) => E y W *)
  SUBGOAL_THEN `(y:A) = pp` (SUBST_ALL_TAC o SYM) THENL
   [MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`y:A`;`qy:A`;`pp:A`;`vval:A`;
      `pr0:A`] EOPAIR_INJ) THEN ASM_REWRITE_TAC[] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[CONJUNCT1 th]); ALL_TAC] THEN
  (* E qy B (c is a bname) *)
  SUBGOAL_THEN `(E:A->A->bool) qy B` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`c:A`;`y:A`;`qy:A`]
      BNAME_APPLY_IN_B) THEN ASM_REWRITE_TAC[] THEN
    REWRITE_TAC[eapply] THEN EXISTS_TAC `pr0:A` THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  (* E ey B *)
  SUBGOAL_THEN `(E:A->A->bool) ey B` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`p:A`;`y:A`;
      `ey:A`] EBV_EQ_IN_B) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) cc B` ASSUME_TAC THENL
   [ASM_MESON_TAC[EMEET_IN]; ALL_TAC] THEN
  (* ---- build WT2 = (ey ==> WTAR) ---- *)
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`ey:A`;`WTAR:A`]
    EBIMP_EXISTS) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `WT2:A` ASSUME_TAC) THEN
  SUBGOAL_THEN `(WT2:A) IN D /\ (E:A->A->bool) WT2 B` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[EBIMP_IN]; ALL_TAC] THEN
  (* ---- qy <= WT2 via CSEL_SECTION_LE (per g-section) ---- *)
  SUBGOAL_THEN `erel D (E:A->A->bool) leq qy WT2` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`g:A`;`W:A`;
       `vf:num->A`;`c:A`;`y:A`;`qy:A`;`WT2:A`] CSEL_SECTION_LE) THEN
    ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
     [REWRITE_TAC[eapply] THEN EXISTS_TAC `pr0:A` THEN ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    (* per-section: ivl,gpair with <y,ivl> in g => ivl <= WT2 *)
    MAP_EVERY X_GEN_TAC [`ivl:A`;`gpair:A`] THEN STRIP_TAC THEN
    (* decode g-membership: u in DD, holds phi_c *)
    SUBGOAL_THEN
      `?u. u IN D /\ E u DD /\
           holds D E ((20|->gpair)((16|->u)(vc:num->A))) phi_c`
      STRIP_ASSUME_TAC THENL
     [FIRST_X_ASSUM(fun th ->
          let th1 = SPEC `gpair:A` (check(fun t -> free_in `g:A` (concl t) &&
                                                   is_forall(concl t)) th) in
          let th2 = MP th1 (ASSUME `(gpair:A) IN D`) in
          ACCEPT_TAC(EQ_MP th2 (ASSUME `(E:A->A->bool) gpair g`)));
      ALL_TAC] THEN
    MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`vc:num->A`;`u:A`;`gpair:A`]
      PHI_C_DEST) THEN
    ASM_REWRITE_TAC[] THEN
    DISCH_THEN(X_CHOOSE_THEN `m:A` (X_CHOOSE_THEN `pg:A` (X_CHOOSE_THEN `ifp:A`
      (X_CHOOSE_THEN `imx:A` (X_CHOOSE_THEN `ivc:A` STRIP_ASSUME_TAC))))) THEN
    (* pg = y, ivc = ivl (opair inj on gpair); substitute globally *)
    SUBGOAL_THEN `(pg:A) = y /\ ivc:A = ivl`
      (CONJUNCTS_THEN SUBST_ALL_TAC) THENL
      [MATCH_MP_TAC(ISPECL
                    [`D:A->bool`;`E:A->A->bool`;`pg:A`;`ivc:A`;`y:A`;`ivl:A`;
                     `gpair:A`] EOPAIR_INJ) THEN ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    (* bname m from DD-decomposition + opair inj on u *)
    SUBGOAL_THEN `bname D (E:A->A->bool) B m` ASSUME_TAC THENL
     [FIRST_X_ASSUM(fun th ->
          MP_TAC(MP (SPEC `u:A` (check(fun t -> free_in `DD:A` (concl t) &&
                                               is_forall(concl t)) th))
                    (CONJ (ASSUME `(u:A) IN D`)
                     (ASSUME `(E:A->A->bool) u DD`)))) THEN
      DISCH_THEN(X_CHOOSE_THEN `md:A`
                 (X_CHOOSE_THEN `pd:A` STRIP_ASSUME_TAC)) THEN
      SUBGOAL_THEN `(md:A) = m /\ pd:A = y`
        (CONJUNCTS_THEN SUBST_ALL_TAC) THENL
        [MATCH_MP_TAC(ISPECL
                      [`D:A->bool`;`E:A->A->bool`;`md:A`;`pd:A`;`m:A`;`y:A`;
                       `u:A`] EOPAIR_INJ) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
      FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    (* firstsel holds transported to canonical valuation; FIRSTSEL_DEST *)
    SUBGOAL_THEN
      `holds D E ((6 |-> ifp)((3 |-> m)((0 |-> y)((16 |-> u)(vc:num->A)))))
              firstsel_fm`
      ASSUME_TAC THENL
     [MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;
         `(6 |-> ifp)((3 |-> m)((0 |-> y)((16 |-> u)(vc:num->A))))`;
         `(14 |-> ivl)((13 |-> imx)((6 |-> ifp)((0 |-> y)((3 |-> m)
            ((20 |-> gpair)((16 |-> u)(vc:num->A)))))))`]
                   FIRSTSEL_HOLDS_AGREE) THEN
      ANTS_TAC THENL
       [REWRITE_TAC[VALMOD; ARITH_EQ] THEN ASM_REWRITE_TAC[] THEN
        REPEAT CONJ_TAC THEN ASM_MESON_TAC[VALUATION_VALMOD];
        DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN FIRST_ASSUM ACCEPT_TAC];
      ALL_TAC] THEN
    MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
       `(3 |-> m)((0 |-> y)((16 |-> u)(vc:num->A)))`;`ifp:A`]
        FIRSTSEL_DEST) THEN
    ANTS_TAC THENL
     [REWRITE_TAC[VALMOD; ARITH_EQ] THEN ASM_REWRITE_TAC[] THEN
      ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
    REWRITE_TAC[VALMOD; ARITH_EQ] THEN ASM_REWRITE_TAC[] THEN
    DISCH_THEN(X_CHOOSE_THEN `Sp:A`
               (X_CHOOSE_THEN `sp:A` (X_CHOOSE_THEN `csp:A`
                                      (X_CHOOSE_THEN `bp:A`
                                       STRIP_ASSUME_TAC)))) THEN
    (* value facts for the block m (all IN D come free above) *)
    SUBGOAL_THEN `(E:A->A->bool) imx B` ASSUME_TAC THENL
     [MATCH_MP_TAC(ISPECL
                   [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`m:A`;`x:A`;
                    `imx:A`] EBV_IN_IN_B) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN `(E:A->A->bool) bp B` ASSUME_TAC THENL
     [MATCH_MP_TAC(ISPECL
                   [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`y:A`;`m:A`;
                    `bp:A`] EBV_IN_IN_B) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN `(E:A->A->bool) sp B` ASSUME_TAC THENL
     [ASM_MESON_TAC[ELUB_IN]; ALL_TAC] THEN
    SUBGOAL_THEN `(E:A->A->bool) csp B` ASSUME_TAC THENL
     [ASM_MESON_TAC[ECOMPL_IN]; ALL_TAC] THEN
    SUBGOAL_THEN `(E:A->A->bool) ifp B` ASSUME_TAC THENL
     [ASM_MESON_TAC[EMEET_IN]; ALL_TAC] THEN
    SUBGOAL_THEN `(E:A->A->bool) ivl B` ASSUME_TAC THENL
     [ASM_MESON_TAC[EMEET_IN]; ALL_TAC] THEN
    (* cc1 = meet(ivl, ey) *)
    MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`ivl:A`;`ey:A`]
      EBALG_MEET) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(X_CHOOSE_THEN `cc1:A` ASSUME_TAC) THEN
    SUBGOAL_THEN `(cc1:A) IN D /\ (E:A->A->bool) cc1 B` STRIP_ASSUME_TAC THENL
     [ASM_MESON_TAC[EMEET_IN]; ALL_TAC] THEN
    (* cc1 <= WTAR via the OUTER per-instance clause *)
    SUBGOAL_THEN `erel D (E:A->A->bool) leq cc1 WTAR` ASSUME_TAC THENL
     [FIRST_X_ASSUM(fun th ->
          MATCH_MP_TAC(SPECL
            [`y:A`;`m:A`;`imx:A`;`bp:A`;`sp:A`;`csp:A`;`ifp:A`;`Sp:A`;`ivl:A`;
             `ey:A`;`cc1:A`]
            (check(fun t -> free_in `WTAR:A` (concl t) &&
                            is_forall(concl t)) th))) THEN
      REPEAT CONJ_TAC THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    (* residuate: ivl <= WT2 = (ey ==> WTAR) *)
    MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`ivl:A`;`ey:A`;
                  `WTAR:A`;`WT2:A`;`cc1:A`] EBIMP_LE_IMP) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* ---- residuate back: cc = meet(qy,ey) <= WTAR ---- *)
  MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`qy:A`;`ey:A`;
     `WTAR:A`;`WT2:A`;`cc:A`] EBIMP_MEET_LE) THEN
  ASM_REWRITE_TAC[]);;

(* EPORDER_TRANS_TAC lo mid hi : proves `erel D E leq lo hi` from assumptions
   `erel D E leq lo mid` and `erel D E leq mid hi` (EPORDER_TRANS; eporder,
   IN D, E _ B side conditions discharged by ASM_REWRITE). *)
let EPORDER_TRANS_TAC lo mid hi =
  MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;lo;mid;hi]
    EPORDER_TRANS) THEN ASM_REWRITE_TAC[];;

(* EBALG_MEET_TAC a b nm : introduces nm = a MEET b, adding assumptions
   `emeet D E B leq a b nm`, `nm IN D`, `E nm B`. *)
let EBALG_MEET_TAC a b nm =
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;a;b] EBALG_MEET) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN nm (fun th ->
    ASSUME_TAC th THEN STRIP_ASSUME_TAC(MATCH_MP EMEET_IN th)));;

(* CSEL_UNIQ (C-F): two-point selector uniqueness (the
  functionality half of the
   boolean-least-element choice selector c).  Given the full
     CSEL_MEM_REDUCE harness
   (W-cover, DD reverse-char, vc/vf graph chars for phi_c/phi_func,
   bname c), the
   outer valuation v (v0=x, v1=t),
   two bnames p,p2 with their six membership values
   { prem, [[t in x]], [[p in t]], [[p in c]], [[p2 in t]], [[p2 in c]] }, the
   equality value epp=[[p=p2]], the W-trichotomy on ra,
   and w0 a common lower bound
   of those six, conclude  w0 <= [[p = p2]].
   DOUBLE PEEL: WTAR1:=(w0 ==> epp);
   CSEL_MEM_REDUCE(p,pc,WTAR1) reduces to per-point
   OUTER1 (cc <= WTAR1  <=residuation=>  meet(cc,w0)=:w0p <= epp).  Then
   WTAR2:=(w0p ==> epp); CSEL_MEM_REDUCE(p2,p2c,WTAR2) reduces OUTER2 to
   (cc2 <= WTAR2  <=>  meet(cc2,w0p)=:gw <= epp),
   discharged by CSEL_UNIQ_PERPAIR(gw)
   (gw sits below cc,cc2,prem,tinx,pt,p2t).  Unwind each peel with
     EBIMP_MEET_LE +
   EMEET_GREATEST + EPORDER_REFL (w0p<=w0<=p2c, w0<=pc). *)
let CSEL_UNIQ = prove
 (`!D (E:A->A->bool) B leq ra W x DD g c vc vf v t p p2
      prem tinx pt p2t pc p2c epp w0.
     model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
     x IN D /\ bname D E B x /\
     W IN D /\ ra IN D /\ DD IN D /\ g IN D /\ c IN D /\
     (!q. q IN D /\ E q W ==> bname D E B q) /\
     (!u. u IN D /\ E u DD
          ==> ?m p. m IN D /\ p IN D /\
                    bname D E B m /\ bname D E B p /\ eopair D E m p u) /\
     valuation D vc /\ vc 1 = leq /\ vc 2 = B /\ vc 4 = ra /\ vc 5 = W /\
     vc 15 = x /\
     (!w. w IN D
          ==> (E w g <=>
               ?u. u IN D /\ E u DD /\
                   holds D E ((20 |-> w)((16 |-> u) vc)) phi_c)) /\
     valuation D vf /\ vf 1 = leq /\ vf 2 = B /\ vf 15 = g /\
     (!w. w IN D
          ==> (E w c <=>
               ?pp. pp IN D /\ E pp W /\
                    holds D E ((20 |-> w)((16 |-> pp) vf)) phi_func)) /\
     bname D E B c /\
     valuation D v /\ (!i. bname D E B (v i)) /\ v 0 = x /\ v 1 = t /\
     t IN D /\ bname D E B t /\
     p IN D /\ bname D E B p /\ p2 IN D /\ bname D E B p2 /\
     prem IN D /\ E prem B /\
     erel D E leq prem
       (bvalf D E B leq v
         (!! 1 (!! 2 (((1 %% 0) && ((2 %% 0) && Not(Eq 1 2)))
                      --> Not(?? 3 ((3 %% 1) && (3 %% 2))))))) /\
     tinx IN D /\ E tinx B /\ ebv_in D E B leq t x tinx /\
     pt IN D /\ E pt B /\ ebv_in D E B leq p t pt /\
     p2t IN D /\ E p2t B /\ ebv_in D E B leq p2 t p2t /\
     pc IN D /\ E pc B /\ ebv_in D E B leq p c pc /\
     p2c IN D /\ E p2c B /\ ebv_in D E B leq p2 c p2c /\
     epp IN D /\ E epp B /\ ebv_eq D E B leq p p2 epp /\
     (!a b. a IN D /\ b IN D /\ E a W /\ E b W
            ==> a = b \/ erel D E ra a b \/ erel D E ra b a) /\
     w0 IN D /\ E w0 B /\
     erel D E leq w0 prem /\ erel D E leq w0 tinx /\
     erel D E leq w0 pt /\ erel D E leq w0 p2t /\
     erel D E leq w0 pc /\ erel D E leq w0 p2c
     ==> erel D E leq w0 epp`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `ebalg D (E:A->A->bool) B leq /\ eporder D (E:A->A->bool) B leq`
   STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[ECBA_IMP_BALG; EBALG_IMP_PORDER]; ALL_TAC] THEN
  (* ---- WTAR1 = (w0 ==> epp) ---- *)
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`w0:A`;`epp:A`]
    EBIMP_EXISTS) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `rhs1:A` ASSUME_TAC) THEN
  SUBGOAL_THEN `(rhs1:A) IN D /\ (E:A->A->bool) rhs1 B` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[EBIMP_IN]; ALL_TAC] THEN
  (* ================= FIRST PEEL: erel pc rhs1 ================= *)
  SUBGOAL_THEN `erel D (E:A->A->bool) leq pc rhs1` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`ra:A`;`W:A`;
       `x:A`;`DD:A`;`g:A`;`c:A`;`vc:num->A`;`vf:num->A`;`p:A`;`pc:A`;`rhs1:A`]
      CSEL_MEM_REDUCE) THEN
    ASM_REWRITE_TAC[] THEN
    (* ---- OUTER1 ---- *)
    MAP_EVERY X_GEN_TAC
     [`y:A`;`m:A`;`imx:A`;`bp:A`;`sp:A`;`csp:A`;`fp:A`;`Sp:A`;`ival:A`;`ey:A`;
      `cc:A`] THEN
    STRIP_TAC THEN
    (* w0p = cc MEET w0 ; projections *)
    EBALG_MEET_TAC `cc:A` `w0:A` `w0p:A` THEN
    MP_TAC(ISPECL
           [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`cc:A`;`w0:A`;`w0p:A`]
           EMEET_LE) THEN ASM_REWRITE_TAC[] THEN STRIP_TAC THEN
    (* inner goal: erel w0p epp *)
    SUBGOAL_THEN `erel D (E:A->A->bool) leq w0p epp` ASSUME_TAC THENL
     [(* WTAR2 = (w0p ==> epp) *)
      MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`w0p:A`;`epp:A`]
        EBIMP_EXISTS) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(X_CHOOSE_THEN `rhs2:A` ASSUME_TAC) THEN
      SUBGOAL_THEN `(rhs2:A) IN D /\ (E:A->A->bool) rhs2 B`
        STRIP_ASSUME_TAC THENL
        [ASM_MESON_TAC[EBIMP_IN]; ALL_TAC] THEN
      (* ========= SECOND PEEL: erel p2c rhs2 ========= *)
      SUBGOAL_THEN `erel D (E:A->A->bool) leq p2c rhs2` ASSUME_TAC THENL
       [MATCH_MP_TAC(ISPECL
                     [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`ra:A`;`W:A`;
                      `x:A`;`DD:A`;`g:A`;`c:A`;`vc:num->A`;`vf:num->A`;`p2:A`;
                      `p2c:A`;`rhs2:A`]
          CSEL_MEM_REDUCE) THEN
        ASM_REWRITE_TAC[] THEN
        (* ---- OUTER2 ---- *)
        MAP_EVERY X_GEN_TAC
         [`y2:A`;`m2:A`;`im2x:A`;`bp2:A`;`sp2:A`;`csp2:A`;`fp2:A`;`Sp2:A`;
          `ival2:A`;`ey2:A`;`cc2:A`] THEN
        STRIP_TAC THEN
        (* gw = cc2 MEET w0p ; projections *)
        EBALG_MEET_TAC `cc2:A` `w0p:A` `gw:A` THEN
        MP_TAC(ISPECL
               [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`cc2:A`;`w0p:A`;
                `gw:A`] EMEET_LE) THEN ASM_REWRITE_TAC[] THEN STRIP_TAC THEN
        (* gw below cc, w0, prem, tinx, pt, p2t (gw<=cc2, gw<=w0p already *)
        (* have) *)
        SUBGOAL_THEN `erel D (E:A->A->bool) leq gw cc` ASSUME_TAC THENL
         [EPORDER_TRANS_TAC `gw:A` `w0p:A` `cc:A`; ALL_TAC] THEN
        SUBGOAL_THEN `erel D (E:A->A->bool) leq gw w0` ASSUME_TAC THENL
         [EPORDER_TRANS_TAC `gw:A` `w0p:A` `w0:A`; ALL_TAC] THEN
        SUBGOAL_THEN `erel D (E:A->A->bool) leq gw prem` ASSUME_TAC THENL
         [EPORDER_TRANS_TAC `gw:A` `w0:A` `prem:A`; ALL_TAC] THEN
        SUBGOAL_THEN `erel D (E:A->A->bool) leq gw tinx` ASSUME_TAC THENL
         [EPORDER_TRANS_TAC `gw:A` `w0:A` `tinx:A`; ALL_TAC] THEN
        SUBGOAL_THEN `erel D (E:A->A->bool) leq gw pt` ASSUME_TAC THENL
         [EPORDER_TRANS_TAC `gw:A` `w0:A` `pt:A`; ALL_TAC] THEN
        SUBGOAL_THEN `erel D (E:A->A->bool) leq gw p2t` ASSUME_TAC THENL
         [EPORDER_TRANS_TAC `gw:A` `w0:A` `p2t:A`; ALL_TAC] THEN
        (* bname y, bname y2 from W-cover *)
        SUBGOAL_THEN `bname D (E:A->A->bool) B y` ASSUME_TAC THENL
         [FIRST_ASSUM MATCH_MP_TAC THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
        SUBGOAL_THEN `bname D (E:A->A->bool) B y2` ASSUME_TAC THENL
         [FIRST_ASSUM MATCH_MP_TAC THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
        (* trichotomy at (y,y2) *)
        SUBGOAL_THEN
          `y:A = y2 \/ erel D (E:A->A->bool) ra y y2 \/ erel D E ra y2 y`
          ASSUME_TAC THENL
         [FIRST_ASSUM MATCH_MP_TAC THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
        (* PERPAIR => erel gw epp *)
        SUBGOAL_THEN `erel D (E:A->A->bool) leq gw epp` ASSUME_TAC THENL
         [MATCH_MP_TAC(ISPECL
            [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`v:num->A`;`x:A`;
             `t:A`;`W:A`;
             `ra:A`;`m:A`;`m2:A`;`y:A`;`y2:A`;`p:A`;`p2:A`;`prem:A`;`tinx:A`;
             `imx:A`;`im2x:A`;`pt:A`;`p2t:A`;`ey:A`;`ey2:A`;`bp:A`;
             `sp:A`;`csp:A`;
             `fp:A`;`Sp:A`;`bp2:A`;`sp2:A`;`csp2:A`;`fp2:A`;`Sp2:A`;
             `ival:A`;`cc:A`;
             `ival2:A`;`cc2:A`;`epp:A`;`gw:A`] CSEL_UNIQ_PERPAIR) THEN
          ASM_REWRITE_TAC[]; ALL_TAC] THEN
        (* residuate: erel cc2 rhs2 *)
        MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`cc2:A`;
           `w0p:A`;`epp:A`;`rhs2:A`;`gw:A`] EBIMP_LE_IMP) THEN
        ASM_REWRITE_TAC[]; ALL_TAC] THEN
      (* unwind SECOND peel: from erel p2c rhs2 get erel w0p epp *)
      EBALG_MEET_TAC `p2c:A` `w0p:A` `mmp:A` THEN
      SUBGOAL_THEN `erel D (E:A->A->bool) leq mmp epp` ASSUME_TAC THENL
       [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`p2c:A`;
           `w0p:A`;`epp:A`;`rhs2:A`;`mmp:A`] EBIMP_MEET_LE) THEN
        ASM_REWRITE_TAC[];
        ALL_TAC] THEN
      SUBGOAL_THEN `erel D (E:A->A->bool) leq w0p p2c` ASSUME_TAC THENL
       [EPORDER_TRANS_TAC `w0p:A` `w0:A` `p2c:A`; ALL_TAC] THEN
      SUBGOAL_THEN `erel D (E:A->A->bool) leq w0p w0p` ASSUME_TAC THENL
       [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`w0p:A`]
          EPORDER_REFL) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
      SUBGOAL_THEN `erel D (E:A->A->bool) leq w0p mmp` ASSUME_TAC THENL
       [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`p2c:A`;
           `w0p:A`;`mmp:A`;`w0p:A`] EMEET_GREATEST) THEN ASM_REWRITE_TAC[];
        ALL_TAC] THEN
      EPORDER_TRANS_TAC `w0p:A` `mmp:A` `epp:A`; ALL_TAC] THEN
    (* residuate: erel cc rhs1 *)
    MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`cc:A`;`w0:A`;
                  `epp:A`;`rhs1:A`;`w0p:A`] EBIMP_LE_IMP) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* ================= unwind FIRST peel: erel w0 epp ================= *)
  EBALG_MEET_TAC `pc:A` `w0:A` `mmt:A` THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq mmt epp` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`pc:A`;`w0:A`;
                  `epp:A`;`rhs1:A`;`mmt:A`] EBIMP_MEET_LE) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq w0 w0` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`w0:A`]
      EPORDER_REFL) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq w0 mmt` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`pc:A`;`w0:A`;
                  `mmt:A`;`w0:A`] EMEET_GREATEST) THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  EPORDER_TRANS_TAC `w0:A` `mmt:A` `epp:A`);;

(* ================================================================= *)
(* CHOICE: selector harness + WF->trichotomy bridge.                 *)
(* RA_TRICH_FROM_WF: WF-least clause over subsets of W ==> ra is a    *)
(* trichotomous (linear) order on W.  CSEL_HARNESS_EXISTS: builds the *)
(* whole boolean-least-element CHOICE selector harness (W,ra,DD,g,c,  *)
(* vc,vf + all chars) that CSEL_EXIST and CSEL_UNIQ                   *)
(* consume, from the C-G top context (model/ecba/B/leq, x IN D,       *)
(* bname x, V=L).                                                     *)
(* ================================================================= *)

let RA_TRICH_FROM_WF = prove
 (`!D (E:A->A->bool) ra W.
      model D E ZF_AX /\ ra IN D /\ W IN D /\
      (!z. z IN D /\ (!s. s IN D /\ E s z ==> E s W) /\ (?s. s IN D /\ E s z)
           ==> ?p0. p0 IN D /\ E p0 z /\
                   !q. q IN D /\ E q z /\ ~(q = p0) ==> erel D E ra p0 q)
      ==> !a b. a IN D /\ b IN D /\ E a W /\ E b W
                ==> a = b \/ erel D E ra a b \/ erel D E ra b a`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  MAP_EVERY X_GEN_TAC [`a:A`;`b:A`] THEN STRIP_TAC THEN
  ASM_CASES_TAC `a:A = b` THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`a:A`;`b:A`] EPAIR_EXISTS) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `z:A` (STRIP_ASSUME_TAC o REWRITE_RULE[epair])) THEN
  SUBGOAL_THEN `?p0:A. p0 IN D /\ (E:A->A->bool) p0 z /\
                       (!q. q IN D /\ E q z /\ ~(q = p0) ==> erel D E ra p0 q)`
    STRIP_ASSUME_TAC THENL
   [FIRST_X_ASSUM MATCH_MP_TAC THEN REPEAT CONJ_TAC THENL
     [FIRST_ASSUM ACCEPT_TAC;
      X_GEN_TAC `s:A` THEN STRIP_TAC THEN ASM_MESON_TAC[];
      EXISTS_TAC `a:A` THEN ASM_MESON_TAC[]];
    ALL_TAC] THEN
  SUBGOAL_THEN `p0:A = a \/ p0:A = b` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[];
    DISJ2_TAC THEN DISJ1_TAC THEN ASM_MESON_TAC[];
    DISJ2_TAC THEN DISJ2_TAC THEN ASM_MESON_TAC[]]);;

let CSEL_HARNESS_EXISTS = prove
 (`!D (E:A->A->bool) B leq x.
     model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
     x IN D /\ bname D E B x /\ (!u. u IN D ==> elmem D E u)
     ==> ?W ra DD g c vc vf.
       W IN D /\ ra IN D /\ DD IN D /\ g IN D /\ c IN D /\
       (!q. q IN D /\ E q W ==> bname D E B q) /\
       (!u. u IN D /\ E u DD
            ==> ?m p. m IN D /\ p IN D /\
                      bname D E B m /\ bname D E B p /\ eopair D E m p u) /\
       (!q b pr. q IN D /\ b IN D /\ pr IN D /\
                 eopair D E q b pr /\ E pr g ==> E b B) /\
       valuation D vc /\ vc 1 = leq /\ vc 2 = B /\ vc 4 = ra /\ vc 5 = W /\
       vc 15 = x /\
       (!w. w IN D ==> (E w g <=>
              ?u. u IN D /\ E u DD /\
                  holds D E ((20 |-> w)((16 |-> u) vc)) phi_c)) /\
       valuation D vf /\ vf 1 = leq /\ vf 2 = B /\ vf 15 = g /\
       (!w. w IN D ==> (E w c <=>
              ?pp. pp IN D /\ E pp W /\
                   holds D E ((20 |-> w)((16 |-> pp) vf)) phi_func)) /\
       bname D E B c /\
       (!m qq blk. m IN D /\ eindom D E x m /\ qq IN D /\ E qq W /\
                   eopair D E m qq blk ==> E blk DD) /\
       (!m y. m IN D /\ eindom D E x m /\ y IN D /\ eindom D E m y
              ==> E y W) /\
       (!z. z IN D /\ (!s. s IN D /\ E s z ==> E s W) /\ (?s. s IN D /\ E s z)
            ==> ?p0. p0 IN D /\ E p0 z /\
                !q. q IN D /\ E q z /\ ~(q = p0) ==> erel D E ra p0 q) /\
       (!u u'. u IN D /\ u' IN D /\ erel D E ra u u' ==>
        ~(erel D E ra u' u)) /\
       (!a b. a IN D /\ b IN D /\ E a W /\ E b W
              ==> a = b \/ erel D E ra a b \/ erel D E ra b a)`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "modl ecba BD leqD xD bnx VL" THEN
  (* ---- S1: W = union of doms, with EUNIONDOM char ---- *)
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`x:A`] EUNIONDOM_EXISTS) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `W:A` (CONJUNCTS_THEN2 (LABEL_TAC "WD")
    (LABEL_TAC "Wch"))) THEN
  (* ---- S2: dx = dom x ---- *)
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`x:A`] EDOMAIN_EXISTS) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `dx:A` MP_TAC) THEN REWRITE_TAC[edomain] THEN
  DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "dxD") (LABEL_TAC "dxch")) THEN
  (* ---- S3: ra via RA_FOR_DOM (dm := W) ---- *)
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`W:A`] RA_FOR_DOM) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `ra:A` (CONJUNCTS_THEN2 (LABEL_TAC "raD")
    (CONJUNCTS_THEN2 (LABEL_TAC "asym") (LABEL_TAC "WFleast")))) THEN
  (* ---- S4: trichotomy on W ---- *)
  SUBGOAL_THEN `!a b:A. a IN D /\ b IN D /\ E a W /\ E b W
                        ==> a = b \/ erel D E ra a b \/ erel D E ra b a`
    (LABEL_TAC "trich") THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`ra:A`;`W:A`]
      RA_TRICH_FROM_WF) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* ---- S5: DD = dx x W ---- *)
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`dx:A`;`W:A`] EPROD_EXISTS) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `DD:A` (CONJUNCTS_THEN2 (LABEL_TAC "DDD")
    (LABEL_TAC "DDch"))) THEN
  (* ---- Wcov ---- *)
  SUBGOAL_THEN `!q:A. q IN D /\ E q W ==> bname D E B q`
    (LABEL_TAC "Wcov") THENL
   [X_GEN_TAC `q:A` THEN STRIP_TAC THEN
    USE_THEN "Wch" (MP_TAC o SPEC `q:A`) THEN
    ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN(fun th -> MP_TAC(EQ_MP th (ASSUME `(E:A->A->bool) q W`))) THEN
    DISCH_THEN(X_CHOOSE_THEN `w:A` STRIP_ASSUME_TAC) THEN
    SUBGOAL_THEN `bname D E B (w:A)` ASSUME_TAC THENL
     [MATCH_MP_TAC UNION_DOM_BNAME THEN EXISTS_TAC `x:A` THEN
      ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    MATCH_MP_TAC UNION_DOM_BNAME THEN EXISTS_TAC `w:A` THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  (* ---- Wfwd ---- *)
  SUBGOAL_THEN `!m y:A. m IN D /\ eindom D E x m /\ y IN D /\ eindom D E m y
                        ==> E y W` (LABEL_TAC "Wfwd") THENL
   [MAP_EVERY X_GEN_TAC [`m:A`;`y:A`] THEN STRIP_TAC THEN
    USE_THEN "Wch" (MP_TAC o SPEC `y:A`) THEN
    ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    EXISTS_TAC `m:A` THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* ---- DDrev ---- *)
  SUBGOAL_THEN `!u:A. u IN D /\ E u DD
                      ==> ?m p. m IN D /\ p IN D /\
                                bname D E B m /\ bname D E B p /\
                                eopair D E m p u` (LABEL_TAC "DDrev") THENL
   [X_GEN_TAC `u:A` THEN STRIP_TAC THEN
    USE_THEN "DDch" (MP_TAC o SPEC `u:A`) THEN
    ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN(fun th -> MP_TAC(EQ_MP th (ASSUME `(E:A->A->bool) u DD`))) THEN
    DISCH_THEN(X_CHOOSE_THEN `k:A` (X_CHOOSE_THEN `t:A` STRIP_ASSUME_TAC)) THEN
    SUBGOAL_THEN `eindom D (E:A->A->bool) x k` ASSUME_TAC THENL
     [USE_THEN "dxch" (MP_TAC o SPEC `k:A`) THEN
      ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[GSYM th]) THEN FIRST_ASSUM ACCEPT_TAC;
      ALL_TAC] THEN
    MAP_EVERY EXISTS_TAC [`k:A`;`t:A`] THEN ASM_REWRITE_TAC[] THEN
    CONJ_TAC THENL
     [MATCH_MP_TAC UNION_DOM_BNAME THEN EXISTS_TAC `x:A` THEN
      ASM_REWRITE_TAC[];
      USE_THEN "Wcov" MATCH_MP_TAC THEN ASM_REWRITE_TAC[]]; ALL_TAC] THEN
  (* ---- DDfwd ---- *)
  SUBGOAL_THEN `!m qq blk:A. m IN D /\ eindom D E x m /\ qq IN D /\ E qq W /\
                             eopair D E m qq blk ==> E blk DD`
    (LABEL_TAC "DDfwd") THENL
   [MAP_EVERY X_GEN_TAC [`m:A`;`qq:A`;`blk:A`] THEN STRIP_TAC THEN
    SUBGOAL_THEN `(blk:A) IN D` ASSUME_TAC THENL
     [ASM_MESON_TAC[EOPAIR_IN]; ALL_TAC] THEN
    USE_THEN "DDch" (MP_TAC o SPEC `blk:A`) THEN
    ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    MAP_EVERY EXISTS_TAC [`m:A`;`qq:A`] THEN ASM_REWRITE_TAC[] THEN
    USE_THEN "dxch" (MP_TAC o SPEC `m:A`) THEN
    ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* ---- v0 base valuation ---- *)
  FIRST_ASSUM(X_CHOOSE_TAC `v0:num->A` o MATCH_MP VALUATION_EXISTS o
              MATCH_MP MODEL_NONEMPTY) THEN
  ABBREV_TAC
   `vc = (15 |-> x)
    ((5 |-> W)((4 |-> ra)((2 |-> B)((1 |-> leq)(v0:num->A)))))` THEN
  SUBGOAL_THEN `valuation D (vc:num->A)` (LABEL_TAC "vcval") THENL
   [EXPAND_TAC "vc" THEN ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
  SUBGOAL_THEN
    `(vc:num->A) 1 = leq /\ vc 2 = B /\ vc 4 = ra /\ vc 5 = W /\ vc 15 = x`
    STRIP_ASSUME_TAC THENL
   [EXPAND_TAC "vc" THEN REWRITE_TAC[VALMOD; ARITH_EQ]; ALL_TAC] THEN
  (* ---- S7: g via CGRAPH_EXISTS ---- *)
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`ra:A`;`W:A`;`x:A`;
                 `DD:A`;`vc:num->A`] CGRAPH_EXISTS) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
     [USE_THEN "Wcov" ACCEPT_TAC; USE_THEN "DDrev" ACCEPT_TAC]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `g:A` (CONJUNCTS_THEN2 (LABEL_TAC "gD")
    (LABEL_TAC "gch"))) THEN
  (* ---- S8: gvalB (values of g are in B) ---- *)
  SUBGOAL_THEN `!q b pr:A. q IN D /\ b IN D /\ pr IN D /\
                           eopair D E q b pr /\ E pr g ==> E b B`
    (LABEL_TAC "gvalB") THENL
   [MAP_EVERY X_GEN_TAC [`q:A`;`bb:A`;`pr:A`] THEN STRIP_TAC THEN
    USE_THEN "gch" (MP_TAC o SPEC `pr:A`) THEN
    ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN(fun th -> MP_TAC(EQ_MP th (ASSUME `(E:A->A->bool) pr g`))) THEN
    DISCH_THEN(X_CHOOSE_THEN `u:A` STRIP_ASSUME_TAC) THEN
    MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`vc:num->A`;`u:A`;`pr:A`]
      PHI_C_DEST) THEN
    ASM_REWRITE_TAC[] THEN
    DISCH_THEN(X_CHOOSE_THEN `m:A` (X_CHOOSE_THEN `p:A` (X_CHOOSE_THEN `ifp:A`
      (X_CHOOSE_THEN `imx:A` (X_CHOOSE_THEN `ival:A` STRIP_ASSUME_TAC))))) THEN
    SUBGOAL_THEN `(ival:A) IN D /\ (E:A->A->bool) ival B`
      STRIP_ASSUME_TAC THENL
      [ASM_MESON_TAC[EMEET_IN]; ALL_TAC] THEN
    SUBGOAL_THEN `(bb:A) = ival` SUBST1_TAC THENL
     [ASM_MESON_TAC[EOPAIR_INJ]; ALL_TAC] THEN
    FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  (* ---- vf ---- *)
  ABBREV_TAC `vf = (15 |-> g)((2 |-> B)((1 |-> leq)(v0:num->A)))` THEN
  SUBGOAL_THEN `valuation D (vf:num->A)` (LABEL_TAC "vfval") THENL
   [EXPAND_TAC "vf" THEN ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
  SUBGOAL_THEN `(vf:num->A) 1 = leq /\ vf 2 = B /\ vf 15 = g`
    STRIP_ASSUME_TAC THENL
   [EXPAND_TAC "vf" THEN REWRITE_TAC[VALMOD; ARITH_EQ]; ALL_TAC] THEN
  (* ---- S10: c via CSEL_EXISTS ---- *)
  MP_TAC(ISPECL
         [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`g:A`;`W:A`;`vf:num->A`]
         CSEL_EXISTS) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[] THEN USE_THEN "gvalB" ACCEPT_TAC; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `c:A` (CONJUNCTS_THEN2 (LABEL_TAC "cD")
    (LABEL_TAC "cch"))) THEN
  (* ---- S11: eisfun c ---- *)
  SUBGOAL_THEN `eisfun D (E:A->A->bool) c` (LABEL_TAC "cisf") THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`W:A`;
                        `vf:num->A`;`c:A`] CSEL_EISFUN) THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  (* ---- S12: bname c ---- *)
  SUBGOAL_THEN `bname D (E:A->A->bool) B c` (LABEL_TAC "cbname") THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`x:A`;`W:A`;
                        `vf:num->A`;`c:A`] CSEL_BNAME) THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  (* ---- S13: assemble ---- *)
  MAP_EVERY EXISTS_TAC
   [`W:A`;`ra:A`;`DD:A`;`g:A`;`c:A`;`vc:num->A`;`vf:num->A`] THEN
  ASM_REWRITE_TAC[]);;

(* ===================================================================== *)
(* C-G  BVALF_CHOICE  = [[choice_ax]] = top   (9th & final V^B ZFC axiom) *)
(* Outer peel mirrors BVALF_REPLACEMENT; per-witness crux = CSEL_EXIST    *)
(* (existence, pmt<=Kex) + CSEL_UNIQ (uniqueness) via residuation.        *)
(* NB: this HOL build has NO `^` term antiquotation -- composite object   *)
(* forms are built via `subst` on placeholder form-vars pp/qq.            *)
(* Helper terms are LOCAL (let..in) so no top-level names are introduced. *)
(* ===================================================================== *)
let BVALF_CHOICE =
  let p1_tm = `!! 1 ((1 %% 0) --> (?? 2 (2 %% 1)))` in
  let p2_tm = `!! 1 (!! 2 (((1 %% 0) && ((2 %% 0) && Not(Eq 1 2)))
                           --> Not(?? 3 ((3 %% 1) && (3 %% 2)))))` in
  let inner_tm = `!! 1 ((1 %% 0) -->
                        ?? 2 ((2 %% 1) && ((2 %% 4) &&
                              !! 3 (((3 %% 1) && (3 %% 4)) --> Eq 3 2))))` in
  let fullbody_tm = `(2 %% 1) && ((2 %% 4) &&
                     !! 3 (((3 %% 1) && (3 %% 4)) --> Eq 3 2))` in
  let kexbody_tm = `(2 %% 1) && (2 %% 4)` in
  let prem_tm     = subst [p1_tm,`pp:form`; p2_tm,`qq:form`]
    `(pp:form) && (qq:form)` in
  let ex4inner_tm = subst [inner_tm,`pp:form`] `?? 4 (pp:form)` in
  let body0_tm    = subst [prem_tm,`pp:form`; ex4inner_tm,`qq:form`]
                          `(pp:form) --> (qq:form)` in
  let ex2full_tm  = subst [fullbody_tm,`pp:form`] `?? 2 (pp:form)` in
  let ex2kex_tm   = subst [kexbody_tm,`pp:form`] `?? 2 (pp:form)` in
  let impbody_tm  = subst [ex2full_tm,`pp:form`] `(1 %% 0) --> (pp:form)` in
  let bvf v p = subst [v,`vv:num->A`; p,`pp:form`]
    `bvalf D (E:A->A->bool) B leq vv pp` in
  prove
 (`!D (E:A->A->bool) B leq v.
      model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
      valuation D v /\ (!i. bname D E B (v i)) /\
      (!u. u IN D ==> elmem D E u)
      ==> etop D E B leq (bvalf D E B leq v choice_ax)`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `ebalg D (E:A->A->bool) B leq` ASSUME_TAC THENL
   [ASM_MESON_TAC[ECBA_IMP_BALG]; ALL_TAC] THEN
  SUBGOAL_THEN `eporder D (E:A->A->bool) B leq` ASSUME_TAC THENL
   [ASM_MESON_TAC[ECBA_IMP_BALG; EBALG_IMP_PORDER]; ALL_TAC] THEN
  REWRITE_TAC[choice_ax] THEN
  (* ===== S1: peel !!0 -> aa ===== *)
  MP_TAC(ISPECL [`0`; body0_tm;
    `D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`v:num->A`] BVALF_ALL_TOP) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  X_GEN_TAC `aa:A` THEN STRIP_TAC THEN
  ABBREV_TAC `v0 = (0 |-> (aa:A)) (v:num->A)` THEN
  SUBGOAL_THEN `valuation D (v0:num->A) /\ (!i. bname D E B ((v0:num->A) i))`
  STRIP_ASSUME_TAC THENL
   [EXPAND_TAC "v0" THEN CONJ_TAC THENL
     [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[];
      MATCH_MP_TAC BNAMEVAL_VALMOD THEN ASM_REWRITE_TAC[]]; ALL_TAC] THEN
  SUBGOAL_THEN `(v0:num->A) 0 = aa` (LABEL_TAC "v0x") THENL
   [EXPAND_TAC "v0" THEN REWRITE_TAC[VALMOD_BASIC]; ALL_TAC] THEN
  (* ===== S2: peel PREM--> ; premv ===== *)
  MP_TAC(ISPECL [prem_tm; ex4inner_tm;
    `D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`v0:num->A`] BVALF_IMP_TOP) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  ABBREV_TAC(subst [prem_tm,`pp:form`]
    `premv = bvalf D (E:A->A->bool) B leq v0 (pp:form)`) THEN
  SUBGOAL_THEN `(premv:A) IN D /\ (E:A->A->bool) premv B`
    STRIP_ASSUME_TAC THENL
   [EXPAND_TAC "premv" THEN CONJ_TAC THENL
     [MP_TAC(ISPECL [prem_tm;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
        `v0:num->A`] BVALF_SPEC) THEN ASM_REWRITE_TAC[] THEN
      DISCH_THEN(ACCEPT_TAC o CONJUNCT1);
      MP_TAC(ISPECL [prem_tm;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
        `v0:num->A`] BVALF_IN_B) THEN ASM_REWRITE_TAC[]]; ALL_TAC] THEN
  (* ===== harness at x:=aa ===== *)
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`aa:A`]
    CSEL_HARNESS_EXISTS) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `W:A` (X_CHOOSE_THEN `ra:A` (X_CHOOSE_THEN `DD:A`
    (X_CHOOSE_THEN `g:A` (X_CHOOSE_THEN `c:A` (X_CHOOSE_THEN `vc:num->A`
     (X_CHOOSE_THEN `vf:num->A` STRIP_ASSUME_TAC))))))) THEN
  (* ===== S5: witness c ; v1=(4|->c)v0 ; exub/premle ===== *)
  ABBREV_TAC `v1 = (4 |-> (c:A)) (v0:num->A)` THEN
  SUBGOAL_THEN `valuation D (v1:num->A) /\ (!i. bname D E B ((v1:num->A) i))`
  STRIP_ASSUME_TAC THENL
   [EXPAND_TAC "v1" THEN CONJ_TAC THENL
     [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[];
      MATCH_MP_TAC BNAMEVAL_VALMOD THEN ASM_REWRITE_TAC[]]; ALL_TAC] THEN
  SUBGOAL_THEN
    (subst [inner_tm,`pp:form`; ex4inner_tm,`qq:form`]
      `erel D (E:A->A->bool) leq (bvalf D E B leq v1 (pp:form))
                                (bvalf D E B leq v0 (qq:form))`)
    (LABEL_TAC "exub") THENL
   [SUBGOAL_THEN `(v1:num->A) = (4 |-> (c:A)) (v0:num->A)` SUBST1_TAC THENL
     [CONV_TAC SYM_CONV THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    MP_TAC(ISPECL [`4`;inner_tm;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
      `v0:num->A`;`c:A`] BVALF_EX_UB) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN (subst [inner_tm,`pp:form`]
    `erel D (E:A->A->bool) leq premv (bvalf D E B leq v1 (pp:form))`)
    (LABEL_TAC "premle") THENL
   [ALL_TAC;
    MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`premv:A`;
      bvf `v1:num->A` inner_tm;
      bvf `v0:num->A` ex4inner_tm] EPORDER_TRANS) THEN
    ASM_REWRITE_TAC[] THEN DISCH_THEN MATCH_MP_TAC THEN
    ASM_MESON_TAC[BVALF_SPEC; BVALF_IN_B]] THEN
  (* ===== S6: peel !!1 -> per bname t ; v2=(1|->t)v1 ===== *)
  MP_TAC(ISPECL [`1`; impbody_tm;
    `D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`v1:num->A`;`premv:A`]
    BVALF_ALL_GLB) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN MATCH_MP_TAC THEN
  X_GEN_TAC `t:A` THEN STRIP_TAC THEN
  ABBREV_TAC `v2 = (1 |-> (t:A)) (v1:num->A)` THEN
  SUBGOAL_THEN `valuation D (v2:num->A) /\ (!i. bname D E B ((v2:num->A) i))`
  STRIP_ASSUME_TAC THENL
   [EXPAND_TAC "v2" THEN CONJ_TAC THENL
     [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[];
      MATCH_MP_TAC BNAMEVAL_VALMOD THEN ASM_REWRITE_TAC[]]; ALL_TAC] THEN
  SUBGOAL_THEN `(v2:num->A) 0 = aa /\ v2 1 = t /\ v2 4 = c`
    STRIP_ASSUME_TAC THENL
   [EXPAND_TAC "v2" THEN EXPAND_TAC "v1" THEN
    REWRITE_TAC[VALMOD; ARITH_EQ] THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* ===== bridges B: premv <= [[P1]]_v2 and premv <= [[P2]]_v2 ===== *)
  SUBGOAL_THEN (subst [p1_tm,`pp:form`]
    `erel D (E:A->A->bool) leq premv (bvalf D E B leq v2 (pp:form))`)
    (LABEL_TAC "premP1") THENL
   [SUBGOAL_THEN (subst [p1_tm,`pp:form`]
      `bvalf D (E:A->A->bool) B leq v0 (pp:form) =
       bvalf D E B leq v2 (pp:form)`) (fun th -> REWRITE_TAC[GSYM th]) THENL
     [MATCH_MP_TAC BVALF_FV_CONG THEN ASM_REWRITE_TAC[] THEN
      REWRITE_TAC[FV; FV_CLAUSES; IN_UNION; IN_INSERT; IN_DELETE;
                  NOT_IN_EMPTY] THEN
      REPEAT STRIP_TAC THEN ASM_MESON_TAC[]; ALL_TAC] THEN
    EXPAND_TAC "premv" THEN
    MP_TAC(ISPECL [p1_tm;p2_tm;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
      `v0:num->A`] BVALF_AND_LE_L) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN (subst [p2_tm,`pp:form`]
    `erel D (E:A->A->bool) leq premv (bvalf D E B leq v2 (pp:form))`)
    (LABEL_TAC "premP2") THENL
   [SUBGOAL_THEN (subst [p2_tm,`pp:form`]
      `bvalf D (E:A->A->bool) B leq v0 (pp:form) =
       bvalf D E B leq v2 (pp:form)`) (fun th -> REWRITE_TAC[GSYM th]) THENL
     [MATCH_MP_TAC BVALF_FV_CONG THEN ASM_REWRITE_TAC[] THEN
      REWRITE_TAC[FV; FV_CLAUSES; IN_UNION; IN_INSERT; IN_DELETE;
                  NOT_IN_EMPTY] THEN
      REPEAT STRIP_TAC THEN ASM_MESON_TAC[]; ALL_TAC] THEN
    EXPAND_TAC "premv" THEN
    MP_TAC(ISPECL [p1_tm;p2_tm;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
      `v0:num->A`] BVALF_AND_LE_R) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* ===== tinx, Kv, Kex, pmt ===== *)
  ABBREV_TAC `tinx = bvalf D (E:A->A->bool) B leq v2 (1 %% 0)` THEN
  SUBGOAL_THEN `(tinx:A) IN D /\ (E:A->A->bool) tinx B` STRIP_ASSUME_TAC THENL
   [EXPAND_TAC "tinx" THEN CONJ_TAC THENL
     [MP_TAC(ISPECL [`(1 %% 0):form`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
        `v2:num->A`] BVALF_SPEC) THEN ASM_REWRITE_TAC[] THEN
      DISCH_THEN(ACCEPT_TAC o CONJUNCT1);
      MP_TAC(ISPECL [`(1 %% 0):form`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
        `v2:num->A`] BVALF_IN_B) THEN ASM_REWRITE_TAC[]]; ALL_TAC] THEN
  ABBREV_TAC(subst [ex2full_tm,`pp:form`]
    `Kv = bvalf D (E:A->A->bool) B leq v2 (pp:form)`) THEN
  SUBGOAL_THEN `(Kv:A) IN D /\ (E:A->A->bool) Kv B` STRIP_ASSUME_TAC THENL
   [EXPAND_TAC "Kv" THEN CONJ_TAC THENL
     [MP_TAC(ISPECL [ex2full_tm;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
        `v2:num->A`] BVALF_SPEC) THEN ASM_REWRITE_TAC[] THEN
      DISCH_THEN(ACCEPT_TAC o CONJUNCT1);
      MP_TAC(ISPECL [ex2full_tm;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
        `v2:num->A`] BVALF_IN_B) THEN ASM_REWRITE_TAC[]]; ALL_TAC] THEN
  ABBREV_TAC(subst [ex2kex_tm,`pp:form`]
    `Kex = bvalf D (E:A->A->bool) B leq v2 (pp:form)`) THEN
  SUBGOAL_THEN `(Kex:A) IN D /\ (E:A->A->bool) Kex B` STRIP_ASSUME_TAC THENL
   [EXPAND_TAC "Kex" THEN CONJ_TAC THENL
     [MP_TAC(ISPECL [ex2kex_tm;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
        `v2:num->A`] BVALF_SPEC) THEN ASM_REWRITE_TAC[] THEN
      DISCH_THEN(ACCEPT_TAC o CONJUNCT1);
      MP_TAC(ISPECL [ex2kex_tm;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
        `v2:num->A`] BVALF_IN_B) THEN ASM_REWRITE_TAC[]]; ALL_TAC] THEN
  EBALG_MEET_TAC `premv:A` `tinx:A` `pmt:A` THEN
  (* ebv_in t aa tinx for CSEL_EXIST *)
  SUBGOAL_THEN `ebv_in D (E:A->A->bool) B leq t aa tinx`
    (LABEL_TAC "tinxin") THENL
   [EXPAND_TAC "tinx" THEN
    MP_TAC(ISPECL
           [`1`;`0`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`v2:num->A`]
           BVALF_MEM) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* goal: erel premv (bvalf v2 ((1%%0) --> ??2 fullbody)) *)
  MP_TAC(ISPECL [`(1 %% 0):form`; ex2full_tm;
    `D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`v2:num->A`] BVALF_IMP) THEN
  ASM_REWRITE_TAC[] THEN DISCH_TAC THEN
  MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`premv:A`;
    `tinx:A`;`Kv:A`;
    bvf `v2:num->A` impbody_tm;
    `pmt:A`] EBIMP_LE_IMP) THEN
  ASM_REWRITE_TAC[] THEN
  (* remaining: erel leq pmt Kv *)
  (* ---- (i) pmt <= Kex via CSEL_EXIST ---- *)
  SUBGOAL_THEN `erel D (E:A->A->bool) leq pmt Kex` (LABEL_TAC "pmtKex") THENL
   [MATCH_MP_TAC(ISPECL
      [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`ra:A`;`W:A`;`aa:A`;`DD:A`;
       `g:A`;`c:A`;`vc:num->A`;`vf:num->A`;`v2:num->A`;`t:A`;`tinx:A`;
       `premv:A`;`pmt:A`;`Kex:A`] CSEL_EXIST) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* ---- (ii) Kex <= resid=(pmt==>Kv) ---- *)
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`pmt:A`;`Kv:A`]
    EBIMP_EXISTS) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `resid:A` ASSUME_TAC) THEN
  SUBGOAL_THEN `(resid:A) IN D /\ (E:A->A->bool) resid B`
    STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[EBIMP_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq Kex resid`
    (LABEL_TAC "KexResid") THENL
   [EXPAND_TAC "Kex" THEN
    MATCH_MP_TAC(ISPECL
                 [`2`;kexbody_tm;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
                  `v2:num->A`;`resid:A`] BVALF_EX_LEAST) THEN
    ASM_REWRITE_TAC[] THEN
    X_GEN_TAC `z:A` THEN STRIP_TAC THEN
    ABBREV_TAC `v3 = (2 |-> (z:A)) (v2:num->A)` THEN
    SUBGOAL_THEN `valuation D (v3:num->A) /\ (!i. bname D E B ((v3:num->A) i))`
    STRIP_ASSUME_TAC THENL
     [EXPAND_TAC "v3" THEN CONJ_TAC THENL
       [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[];
        MATCH_MP_TAC BNAMEVAL_VALMOD THEN ASM_REWRITE_TAC[]]; ALL_TAC] THEN
    SUBGOAL_THEN `(v3:num->A) 0 = aa /\ v3 1 = t /\ v3 2 = z /\ v3 4 = c`
    STRIP_ASSUME_TAC THENL
     [EXPAND_TAC "v3" THEN REWRITE_TAC[VALMOD; ARITH_EQ] THEN
      ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    (* Wz = [[z in t]] && [[z in c]] = bvalf v3 kexbody *)
    ABBREV_TAC `zt = bvalf D (E:A->A->bool) B leq v3 (2 %% 1)` THEN
    ABBREV_TAC `zc = bvalf D (E:A->A->bool) B leq v3 (2 %% 4)` THEN
    SUBGOAL_THEN `(zt:A) IN D /\ E zt B /\ (zc:A) IN D /\ (E:A->A->bool) zc B`
    STRIP_ASSUME_TAC THENL
     [MAP_EVERY EXPAND_TAC ["zt";"zc"] THEN REPEAT CONJ_TAC THEN
      ASM_MESON_TAC[BVALF_SPEC; BVALF_IN_B]; ALL_TAC] THEN
    (* ebv_in for zt, zc *)
    SUBGOAL_THEN `ebv_in D (E:A->A->bool) B leq z t zt`
      (LABEL_TAC "ztin") THENL
      [EXPAND_TAC "zt" THEN
      MP_TAC(ISPECL
             [`2`;`1`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`v3:num->A`]
             BVALF_MEM) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN `ebv_in D (E:A->A->bool) B leq z c zc`
      (LABEL_TAC "zcin") THENL
      [EXPAND_TAC "zc" THEN
      MP_TAC(ISPECL
             [`2`;`4`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`v3:num->A`]
             BVALF_MEM) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    ABBREV_TAC(subst [kexbody_tm,`pp:form`]
      `Wz = bvalf D (E:A->A->bool) B leq v3 (pp:form)`) THEN
    SUBGOAL_THEN `emeet D (E:A->A->bool) B leq zt zc Wz` ASSUME_TAC THENL
     [MAP_EVERY EXPAND_TAC ["zt";"zc";"Wz"] THEN
      MP_TAC(ISPECL
             [`(2 %% 1):form`;`(2 %% 4):form`;`D:A->bool`;`E:A->A->bool`;
              `B:A`;`leq:A`;`v3:num->A`] BVALF_AND_MEET) THEN
      ASM_REWRITE_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN `(Wz:A) IN D /\ (E:A->A->bool) Wz B` STRIP_ASSUME_TAC THENL
     [ASM_MESON_TAC[EMEET_IN]; ALL_TAC] THEN
    SUBGOAL_THEN `erel D (E:A->A->bool) leq Wz zt /\ erel D E leq Wz zc`
    STRIP_ASSUME_TAC THENL [ASM_MESON_TAC[EMEET_LE]; ALL_TAC] THEN
    (* gz = meet(Wz, pmt) *)
    EBALG_MEET_TAC `Wz:A` `pmt:A` `gz:A` THEN
    SUBGOAL_THEN `erel D (E:A->A->bool) leq gz Wz /\ erel D E leq gz pmt`
    STRIP_ASSUME_TAC THENL [ASM_MESON_TAC[EMEET_LE]; ALL_TAC] THEN
    SUBGOAL_THEN `erel D (E:A->A->bool) leq pmt premv /\ erel D E leq pmt tinx`
    STRIP_ASSUME_TAC THENL [ASM_MESON_TAC[EMEET_LE]; ALL_TAC] THEN
    SUBGOAL_THEN `erel D (E:A->A->bool) leq gz zt` ASSUME_TAC THENL
     [EPORDER_TRANS_TAC `gz:A` `Wz:A` `zt:A`; ALL_TAC] THEN
    SUBGOAL_THEN `erel D (E:A->A->bool) leq gz zc` ASSUME_TAC THENL
     [EPORDER_TRANS_TAC `gz:A` `Wz:A` `zc:A`; ALL_TAC] THEN
    SUBGOAL_THEN `erel D (E:A->A->bool) leq gz premv` ASSUME_TAC THENL
     [EPORDER_TRANS_TAC `gz:A` `pmt:A` `premv:A`; ALL_TAC] THEN
    SUBGOAL_THEN `erel D (E:A->A->bool) leq gz tinx` ASSUME_TAC THENL
     [EPORDER_TRANS_TAC `gz:A` `pmt:A` `tinx:A`; ALL_TAC] THEN
    (* Prove erel gz Kv, then residuate to erel Wz resid *)
    SUBGOAL_THEN `erel D (E:A->A->bool) leq gz Kv` ASSUME_TAC THENL
     [(* Fz = bvalf v3 fullbody : membership (kept for the final chain) *)
      SUBGOAL_THEN (subst [fullbody_tm,`pp:form`]
        `(bvalf D (E:A->A->bool) B leq v3 (pp:form)) IN D /\
         (E:A->A->bool) (bvalf D E B leq v3 (pp:form)) B`)
        STRIP_ASSUME_TAC THENL
       [CONJ_TAC THEN ASM_MESON_TAC[BVALF_SPEC; BVALF_IN_B]; ALL_TAC] THEN
      (* Fz <= Kv (BVALF_EX_UB) *)
      SUBGOAL_THEN (subst [fullbody_tm,`pp:form`]
       `erel D (E:A->A->bool) leq (bvalf D E B leq v3 (pp:form)) Kv`)
       ASSUME_TAC THENL
       [SUBGOAL_THEN `(v3:num->A) = (2 |-> (z:A)) (v2:num->A)` SUBST1_TAC THENL
         [CONV_TAC SYM_CONV THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
        EXPAND_TAC "Kv" THEN
        MP_TAC(ISPECL
               [`2`;fullbody_tm;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
                `v2:num->A`;`z:A`] BVALF_EX_UB) THEN ASM_REWRITE_TAC[];
        ALL_TAC] THEN
      (* gz <= Fz then trans *)
      SUBGOAL_THEN (subst [fullbody_tm,`pp:form`]
        `erel D (E:A->A->bool) leq gz (bvalf D E B leq v3 (pp:form))`)
        ASSUME_TAC THENL
       [(* Fz = meet(zt, meet(zc, uz)) *)
        ABBREV_TAC `uz = bvalf D (E:A->A->bool) B leq v3
                      (!! 3 (((3 %% 1) && (3 %% 4)) --> Eq 3 2))` THEN
        SUBGOAL_THEN `(uz:A) IN D /\ (E:A->A->bool) uz B`
          STRIP_ASSUME_TAC THENL
          [EXPAND_TAC "uz" THEN CONJ_TAC THEN
           ASM_MESON_TAC[BVALF_SPEC;BVALF_IN_B];
           ALL_TAC] THEN
        ABBREV_TAC `R1 = bvalf D (E:A->A->bool) B leq v3
                      ((2 %% 4) &&
                       (!! 3 (((3 %% 1) && (3 %% 4)) --> Eq 3 2)))` THEN
        SUBGOAL_THEN `(R1:A) IN D /\ (E:A->A->bool) R1 B`
          STRIP_ASSUME_TAC THENL
          [EXPAND_TAC "R1" THEN CONJ_TAC THEN
           ASM_MESON_TAC[BVALF_SPEC;BVALF_IN_B];
           ALL_TAC] THEN
        SUBGOAL_THEN `emeet D (E:A->A->bool) B leq zc uz R1` ASSUME_TAC THENL
         [MAP_EVERY EXPAND_TAC ["zc";"uz";"R1"] THEN
          MP_TAC(ISPECL [`(2 %% 4):form`;
            `(!! 3 (((3 %% 1) && (3 %% 4)) --> Eq 3 2)):form`;
            `D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`v3:num->A`]
                         BVALF_AND_MEET) THEN
          ASM_REWRITE_TAC[]; ALL_TAC] THEN
        SUBGOAL_THEN (subst [fullbody_tm,`pp:form`]
          `emeet D (E:A->A->bool) B leq zt R1 (bvalf D E B leq v3 (pp:form))`)
          ASSUME_TAC THENL
         [MAP_EVERY EXPAND_TAC ["zt";"R1"] THEN
          MP_TAC(ISPECL [`(2 %% 1):form`;
            `((2 %% 4) && (!! 3 (((3 %% 1) && (3 %% 4)) --> Eq 3 2))):form`;
            `D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`v3:num->A`]
                           BVALF_AND_MEET) THEN
          ASM_REWRITE_TAC[]; ALL_TAC] THEN
        (* crux: gz <= uz *)
        SUBGOAL_THEN `erel D (E:A->A->bool) leq gz uz` ASSUME_TAC THENL
         [EXPAND_TAC "uz" THEN
          MP_TAC(ISPECL [`3`;`((3 %% 1) && (3 %% 4)) --> Eq 3 2`;
            `D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`v3:num->A`;`gz:A`]
            BVALF_ALL_GLB) THEN
          ASM_REWRITE_TAC[] THEN DISCH_THEN MATCH_MP_TAC THEN
          X_GEN_TAC `zp:A` THEN STRIP_TAC THEN
          ABBREV_TAC `v4 = (3 |-> (zp:A)) (v3:num->A)` THEN
          SUBGOAL_THEN
            `valuation D (v4:num->A) /\ (!i. bname D E B ((v4:num->A) i))`
            STRIP_ASSUME_TAC THENL
           [EXPAND_TAC "v4" THEN CONJ_TAC THENL
             [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[];
              MATCH_MP_TAC BNAMEVAL_VALMOD THEN ASM_REWRITE_TAC[]];
             ALL_TAC] THEN
          SUBGOAL_THEN `(v4:num->A) 1 = t /\ v4 2 = z /\ v4 3 = zp /\ v4 4 = c`
          STRIP_ASSUME_TAC THENL
           [EXPAND_TAC "v4" THEN REWRITE_TAC[VALMOD; ARITH_EQ] THEN
            ASM_REWRITE_TAC[];
            ALL_TAC] THEN
          (* body = A' --> eqv ; A'=meet(z't,z'c); eqv=ebv_eq zp z *)
          ABBREV_TAC `zpt = bvalf D (E:A->A->bool) B leq v4 (3 %% 1)` THEN
          ABBREV_TAC `zpc = bvalf D (E:A->A->bool) B leq v4 (3 %% 4)` THEN
          ABBREV_TAC `eqv = bvalf D (E:A->A->bool) B leq v4 (Eq 3 2)` THEN
          SUBGOAL_THEN
            `(zpt:A) IN D /\ E zpt B /\ (zpc:A) IN D /\ E zpc B /\
             (eqv:A) IN D /\ (E:A->A->bool) eqv B` STRIP_ASSUME_TAC THENL
           [MAP_EVERY EXPAND_TAC ["zpt";"zpc";"eqv"] THEN REPEAT CONJ_TAC THEN
            ASM_MESON_TAC[BVALF_SPEC; BVALF_IN_B]; ALL_TAC] THEN
          SUBGOAL_THEN `ebv_in D (E:A->A->bool) B leq zp t zpt`
            (LABEL_TAC "zptin") THENL
           [EXPAND_TAC "zpt" THEN
            MP_TAC(ISPECL [`3`;`1`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
              `v4:num->A`] BVALF_MEM) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
          SUBGOAL_THEN `ebv_in D (E:A->A->bool) B leq zp c zpc`
            (LABEL_TAC "zpcin") THENL
           [EXPAND_TAC "zpc" THEN
            MP_TAC(ISPECL [`3`;`4`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
              `v4:num->A`] BVALF_MEM) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
          SUBGOAL_THEN `ebv_eq D (E:A->A->bool) B leq zp z eqv`
            (LABEL_TAC "eqvin") THENL
           [EXPAND_TAC "eqv" THEN
            MP_TAC(ISPECL [`3`;`2`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
              `v4:num->A`] BVALF_EQ2) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
          (* also need ebv_in z t (as p2t) and z c (as p2c): build fresh at *)
          (* v4 *)
          ABBREV_TAC `zt2 = bvalf D (E:A->A->bool) B leq v4 (2 %% 1)` THEN
          ABBREV_TAC `zc2 = bvalf D (E:A->A->bool) B leq v4 (2 %% 4)` THEN
          SUBGOAL_THEN
            `(zt2:A) IN D /\ E zt2 B /\ (zc2:A) IN D /\ (E:A->A->bool) zc2 B`
            STRIP_ASSUME_TAC THENL
           [MAP_EVERY EXPAND_TAC ["zt2";"zc2"] THEN REPEAT CONJ_TAC THEN
            ASM_MESON_TAC[BVALF_SPEC; BVALF_IN_B]; ALL_TAC] THEN
          SUBGOAL_THEN `ebv_in D (E:A->A->bool) B leq z t zt2`
            (LABEL_TAC "zt2in") THENL
            [EXPAND_TAC "zt2" THEN
            MP_TAC(ISPECL [`2`;`1`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
              `v4:num->A`] BVALF_MEM) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
          SUBGOAL_THEN `ebv_in D (E:A->A->bool) B leq z c zc2`
            (LABEL_TAC "zc2in") THENL
            [EXPAND_TAC "zc2" THEN
            MP_TAC(ISPECL [`2`;`4`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
              `v4:num->A`] BVALF_MEM) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
          (* A' = meet(zpt, zpc) = bvalf v4 ((3%%1)&&(3%%4)) *)
          ABBREV_TAC
            `Ap = bvalf D (E:A->A->bool) B leq v4 ((3 %% 1) && (3 %% 4))` THEN
            SUBGOAL_THEN `(Ap:A) IN D /\ (E:A->A->bool) Ap B`
              STRIP_ASSUME_TAC THENL
              [EXPAND_TAC "Ap" THEN CONJ_TAC THEN
               ASM_MESON_TAC[BVALF_SPEC;BVALF_IN_B];
               ALL_TAC] THEN
          SUBGOAL_THEN `emeet D (E:A->A->bool) B leq zpt zpc Ap`
            ASSUME_TAC THENL
            [MAP_EVERY EXPAND_TAC ["zpt";"zpc";"Ap"] THEN
            MP_TAC(ISPECL [`(3 %% 1):form`;`(3 %% 4):form`;`D:A->bool`;
              `E:A->A->bool`;`B:A`;`leq:A`;`v4:num->A`] BVALF_AND_MEET) THEN
            ASM_REWRITE_TAC[]; ALL_TAC] THEN
          SUBGOAL_THEN
            `erel D (E:A->A->bool) leq Ap zpt /\ erel D E leq Ap zpc`
            STRIP_ASSUME_TAC THENL [ASM_MESON_TAC[EMEET_LE]; ALL_TAC] THEN
          (* w0p = meet(gz, Ap) *)
          EBALG_MEET_TAC `gz:A` `Ap:A` `w0p:A` THEN
          SUBGOAL_THEN
            `erel D (E:A->A->bool) leq w0p gz /\ erel D E leq w0p Ap`
            STRIP_ASSUME_TAC THENL [ASM_MESON_TAC[EMEET_LE]; ALL_TAC] THEN
          (* body value = ebimp Ap eqv (bvalf v4 body) *)
          MP_TAC(ISPECL [`((3 %% 1) && (3 %% 4)):form`; `Eq 3 2`;
            `D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`v4:num->A`]
              BVALF_IMP) THEN
          ASM_REWRITE_TAC[] THEN
          SUBGOAL_THEN
            `bvalf D (E:A->A->bool) B leq v4 ((3 %% 1) && (3 %% 4)) = Ap /\
             bvalf D (E:A->A->bool) B leq v4 (Eq 3 2) = eqv`
            (fun th -> REWRITE_TAC[th]) THENL
           [CONJ_TAC THENL [EXPAND_TAC "Ap"; EXPAND_TAC "eqv"] THEN REFL_TAC;
            ALL_TAC] THEN
          DISCH_TAC THEN
          (* residuate goal erel gz (bvalf v4 body) to erel w0p eqv *)
          MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`gz:A`;
            `Ap:A`;`eqv:A`;
            `bvalf D (E:A->A->bool) B leq v4
             (((3 %% 1) && (3 %% 4)) --> Eq 3 2)`;
            `w0p:A`] EBIMP_LE_IMP) THEN
          ASM_REWRITE_TAC[] THEN
          (* remaining: erel w0p eqv  via CSEL_UNIQ (p:=zp,p2:=z) *)
          SUBGOAL_THEN `erel D (E:A->A->bool) leq w0p premv /\
                        erel D (E:A->A->bool) leq w0p tinx /\
                        erel D (E:A->A->bool) leq w0p zpt /\
                        erel D (E:A->A->bool) leq w0p zt2 /\
                        erel D (E:A->A->bool) leq w0p zpc /\
                        erel D (E:A->A->bool) leq w0p zc2`
          STRIP_ASSUME_TAC THENL
           [REPEAT CONJ_TAC THENL
             [EPORDER_TRANS_TAC `w0p:A` `gz:A` `premv:A`;
              EPORDER_TRANS_TAC `w0p:A` `gz:A` `tinx:A`;
              EPORDER_TRANS_TAC `w0p:A` `Ap:A` `zpt:A`;
              (* w0p <= zt2 = [[z in t]] : identify zt2 with zt via *)
              (* EBV_IN_UNIQUE *)
              SUBGOAL_THEN `zt2:A = zt` SUBST1_TAC THENL
               [MATCH_MP_TAC(ISPECL
                             [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`z:A`;
                              `t:A`;`zt2:A`;`zt:A`] EBV_IN_UNIQUE) THEN
             ASM_REWRITE_TAC[];
             EPORDER_TRANS_TAC `w0p:A` `gz:A` `zt:A`];
              EPORDER_TRANS_TAC `w0p:A` `Ap:A` `zpc:A`;
              SUBGOAL_THEN `zc2:A = zc` SUBST1_TAC THENL
               [MATCH_MP_TAC(ISPECL
                             [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`z:A`;
                              `c:A`;`zc2:A`;`zc:A`] EBV_IN_UNIQUE) THEN
             ASM_REWRITE_TAC[];
             EPORDER_TRANS_TAC `w0p:A` `gz:A` `zc:A`]]; ALL_TAC] THEN
          MATCH_MP_TAC(ISPECL
            [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`ra:A`;`W:A`;
             `aa:A`;`DD:A`;
             `g:A`;`c:A`;`vc:num->A`;`vf:num->A`;`v2:num->A`;`t:A`;
             `zp:A`;`z:A`;
             `premv:A`;`tinx:A`;`zpt:A`;`zt2:A`;`zpc:A`;`zc2:A`;
             `eqv:A`;`w0p:A`]
            CSEL_UNIQ) THEN
          ASM_REWRITE_TAC[]; ALL_TAC] THEN
        (* assemble gz <= Fz via EMEET_GREATEST twice *)
        SUBGOAL_THEN `erel D (E:A->A->bool) leq gz R1` ASSUME_TAC THENL
         [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`zc:A`;
            `uz:A`;`R1:A`;`gz:A`] EMEET_GREATEST) THEN ASM_REWRITE_TAC[];
          ALL_TAC] THEN
        MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`zt:A`;
          `R1:A`;bvf `v3:num->A` fullbody_tm;`gz:A`]
          EMEET_GREATEST) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
      EPORDER_TRANS_TAC `gz:A` (bvf `v3:num->A` fullbody_tm) `Kv:A`;
      ALL_TAC] THEN
    (* residuate erel Wz resid from erel gz Kv *)
    MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`Wz:A`;`pmt:A`;
                  `Kv:A`;`resid:A`;`gz:A`] EBIMP_LE_IMP) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* ---- pmt <= Kex <= resid, then self-MP (EBV_MP_LE) to pmt <= Kv ---- *)
  SUBGOAL_THEN `erel D (E:A->A->bool) leq pmt resid` ASSUME_TAC THENL
   [EPORDER_TRANS_TAC `pmt:A` `Kex:A` `resid:A`; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq pmt pmt` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`pmt:A`]
      EPORDER_REFL) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MATCH_MP_TAC(ISPECL
               [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`pmt:A`;`pmt:A`;
                `Kv:A`;`resid:A`] EBV_MP_LE) THEN
  ASM_REWRITE_TAC[]);;

(* ===================================================================== *)
(* F8-A: ULTRAFILTER-QUOTIENT ALGEBRA (abstract over any cba B in N).     *)
(*                                                                        *)
(* All lemmas take an internal ultrafilter `eultra D E B leq U` as a      *)
(* HYPOTHESIS; only the final F8 endpoint discharges `?U. eultra..U`.     *)
(* This isolates the (independent) ultrafilter-existence work and lets    *)
(* the whole quotient + Los machinery be built U-agnostically.            *)
(*                                                                        *)
(*   ubig D E U z        z is "U-large":  z IN D /\ E z U   (kept abstract *)
(*                       so the internal-vs-meta U switch is localized).   *)
(*   usim D E B leq U a b  ~_U on bnames: ?z. ebv_eq a b z /\ ubig z       *)
(*   umem D E B leq U a b  raw E' membership: ?z. ebv_in a b z /\ ubig z   *)
(* ===================================================================== *)

let ubig = new_definition
  `ubig D (E:A->A->bool) U z <=> z IN D /\ E z U`;;

let usim = new_definition
  `usim D (E:A->A->bool) B leq U a b <=>
     ?z. ebv_eq D E B leq a b z /\ ubig D E U z`;;

let umem = new_definition
  `umem D (E:A->A->bool) B leq U a b <=>
     ?z. ebv_in D E B leq a b z /\ ubig D E U z`;;

(* ---- F8-A lemma 1: eultra helper lemmas (pure F1 layer, reusable) ---- *)
(* NB element vars named s,t,m,u avoid x,y,z,w = efilter's bound vars,     *)
(* else STRIP_TAC's CHOOSE on the nonemptiness clause ?x.. collides.       *)

(* top is U-large *)
let EULTRA_TOP = prove
 (`!D (E:A->A->bool) B leq U u.
      eporder D E B leq /\ eultra D E B leq U /\ etop D E B leq u
      ==> E u U`,
  REPEAT GEN_TAC THEN REWRITE_TAC[eultra; efilter; esubset] THEN
  STRIP_TAC THEN ASM_MESON_TAC[ETOP_IN; ETOP_GE]);;

(* upward closure of the filter *)
let EULTRA_UP = prove
 (`!D (E:A->A->bool) B leq U s t.
      eultra D E B leq U /\ s IN D /\ t IN D /\ E s U /\ E t B /\
      erel D E leq s t
      ==> E t U`,
  REPEAT GEN_TAC THEN REWRITE_TAC[eultra; efilter; esubset] THEN
  STRIP_TAC THEN ASM_MESON_TAC[]);;

(* meet of two U-large elements is U-large *)
let EULTRA_MEET = prove
 (`!D (E:A->A->bool) B leq U s t m.
      eultra D E B leq U /\
      s IN D /\ t IN D /\ E s U /\ E t U /\ emeet D E B leq s t m
      ==> E m U`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `(m:A) IN D /\ (E:A->A->bool) m B` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[EMEET_IN]; ALL_TAC] THEN
  SUBGOAL_THEN
    `?z. z IN D /\ E z U /\ erel D (E:A->A->bool) leq z s /\ erel D E leq z t`
    STRIP_ASSUME_TAC THENL
   [UNDISCH_TAC `eultra D (E:A->A->bool) B leq U` THEN
    REWRITE_TAC[eultra; efilter] THEN STRIP_TAC THEN
    FIRST_X_ASSUM MATCH_MP_TAC THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) z B` ASSUME_TAC THENL
   [UNDISCH_TAC `eultra D (E:A->A->bool) B leq U` THEN
    REWRITE_TAC[eultra; efilter; esubset] THEN ASM_MESON_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq z m` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`s:A`;`t:A`;
      `m:A`;`z:A`] EMEET_GREATEST) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MATCH_MP_TAC(ISPECL
               [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`U:A`;`z:A`;`m:A`]
               EULTRA_UP) THEN ASM_REWRITE_TAC[]);;

(* bottom is never U-large *)
let EULTRA_NOT_BOT = prove
 (`!D (E:A->A->bool) B leq U m.
      eultra D E B leq U /\ ebot D E B leq m ==> ~E m U`,
  REPEAT GEN_TAC THEN REWRITE_TAC[eultra] THEN STRIP_TAC THEN
  ASM_MESON_TAC[]);;

(* ultra: s or its complement is U-large *)
let EULTRA_DICHOT = prove
 (`!D (E:A->A->bool) B leq U s.
      eultra D E B leq U /\ s IN D /\ E s B
      ==> E s U \/ (?t. ecompl D E B leq s t /\ E t U)`,
  REPEAT GEN_TAC THEN REWRITE_TAC[eultra] THEN STRIP_TAC THEN
  ASM_MESON_TAC[]);;

(* ---- F8-A lemma 2: ~_U is an equivalence on bnames ------------------- *)

let USIM_REFL = prove
 (`!D (E:A->A->bool) B leq U a.
      model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
      eultra D E B leq U /\ a IN D /\ bname D E B a
      ==> usim D E B leq U a a`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `eporder D (E:A->A->bool) B leq` ASSUME_TAC THENL
   [ASM_MESON_TAC[ECBA_IMP_PORDER]; ALL_TAC] THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`a:A`;`a:A`]
    EBV_TOTAL) THEN ASM_REWRITE_TAC[] THEN
  DISCH_THEN(CONJUNCTS_THEN2 (K ALL_TAC)
    (X_CHOOSE_THEN `ze:A` STRIP_ASSUME_TAC)) THEN
  REWRITE_TAC[usim; ubig] THEN EXISTS_TAC `ze:A` THEN ASM_REWRITE_TAC[] THEN
  SUBGOAL_THEN `etop D (E:A->A->bool) B leq ze` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`a:A`;`ze:A`]
      EBV_EQ_REFL) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`U:A`;`ze:A`]
    EULTRA_TOP) THEN ASM_REWRITE_TAC[]);;

let USIM_SYM = prove
 (`!D (E:A->A->bool) B leq U a b.
      model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
      a IN D /\ b IN D /\ usim D E B leq U a b
      ==> usim D E B leq U b a`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  UNDISCH_TAC `usim D (E:A->A->bool) B leq U a b` THEN
  REWRITE_TAC[usim; ubig] THEN
  DISCH_THEN(X_CHOOSE_THEN `z:A` STRIP_ASSUME_TAC) THEN
  EXISTS_TAC `z:A` THEN ASM_REWRITE_TAC[] THEN
  MATCH_MP_TAC(ISPECL
               [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`a:A`;`b:A`;`z:A`]
               EBV_EQ_SYM) THEN ASM_REWRITE_TAC[]);;

let USIM_TRANS = prove
 (`!D (E:A->A->bool) B leq U a b c.
      model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
      eultra D E B leq U /\
      a IN D /\ b IN D /\ c IN D /\
      bname D E B a /\ bname D E B b /\ bname D E B c /\
      usim D E B leq U a b /\ usim D E B leq U b c
      ==> usim D E B leq U a c`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `ebalg D (E:A->A->bool) B leq` ASSUME_TAC THENL
   [ASM_MESON_TAC[ECBA_IMP_BALG]; ALL_TAC] THEN
  UNDISCH_TAC `usim D (E:A->A->bool) B leq U b c` THEN
  UNDISCH_TAC `usim D (E:A->A->bool) B leq U a b` THEN
  REWRITE_TAC[usim; ubig] THEN
  DISCH_THEN(X_CHOOSE_THEN `z20:A` STRIP_ASSUME_TAC) THEN
  DISCH_THEN(X_CHOOSE_THEN `z21:A` STRIP_ASSUME_TAC) THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`a:A`;`c:A`]
    EBV_TOTAL) THEN ASM_REWRITE_TAC[] THEN
  DISCH_THEN(CONJUNCTS_THEN2 (K ALL_TAC)
    (X_CHOOSE_THEN `z22:A` STRIP_ASSUME_TAC)) THEN
  SUBGOAL_THEN `(E:A->A->bool) z20 (B:A)` ASSUME_TAC THENL
   [MP_TAC(ISPECL
           [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`a:A`;`b:A`;`z20:A`]
           EBV_EQ_IN_B) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) z21 (B:A)` ASSUME_TAC THENL
   [MP_TAC(ISPECL
           [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`b:A`;`c:A`;`z21:A`]
           EBV_EQ_IN_B) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) z22 (B:A)` ASSUME_TAC THENL
   [MP_TAC(ISPECL
           [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`a:A`;`c:A`;`z22:A`]
           EBV_EQ_IN_B) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  EBALG_MEET_TAC `z20:A` `z21:A` `z23:A` THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq z23 z22` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
      `a:A`;`b:A`;`c:A`;`z20:A`;`z21:A`;`z22:A`;`z23:A`] EBV_EQ_CONG) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) z23 (U:A)` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`U:A`;
      `z20:A`;`z21:A`;`z23:A`] EULTRA_MEET) THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  REWRITE_TAC[usim; ubig] THEN EXISTS_TAC `z22:A` THEN ASM_REWRITE_TAC[] THEN
  MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`U:A`;
    `z23:A`;`z22:A`] EULTRA_UP) THEN ASM_REWRITE_TAC[]);;

(* ---- F8-A lemma 3: umem is a congruence for ~_U (E' well-defined) ---- *)

let UMEM_CONG_L = prove
 (`!D (E:A->A->bool) B leq U a a' b.
      model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
      eultra D E B leq U /\
      a IN D /\ a' IN D /\ b IN D /\
      bname D E B a /\ bname D E B a' /\ bname D E B b /\
      usim D E B leq U a a' /\ umem D E B leq U a b
      ==> umem D E B leq U a' b`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `ebalg D (E:A->A->bool) B leq` ASSUME_TAC THENL
   [ASM_MESON_TAC[ECBA_IMP_BALG]; ALL_TAC] THEN
  UNDISCH_TAC `umem D (E:A->A->bool) B leq U a b` THEN
  UNDISCH_TAC `usim D (E:A->A->bool) B leq U a a'` THEN
  REWRITE_TAC[usim; umem; ubig] THEN
  DISCH_THEN(X_CHOOSE_THEN `z20:A` STRIP_ASSUME_TAC) THEN
  DISCH_THEN(X_CHOOSE_THEN `z21:A` STRIP_ASSUME_TAC) THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`a':A`;`b:A`]
    EBV_TOTAL) THEN ASM_REWRITE_TAC[] THEN
  DISCH_THEN(CONJUNCTS_THEN2
    (X_CHOOSE_THEN `z22:A` STRIP_ASSUME_TAC) (K ALL_TAC)) THEN
  SUBGOAL_THEN `(E:A->A->bool) z20 (B:A)` ASSUME_TAC THENL
   [MP_TAC(ISPECL
           [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`a:A`;`a':A`;`z20:A`]
           EBV_EQ_IN_B) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) z21 (B:A)` ASSUME_TAC THENL
   [MP_TAC(ISPECL
           [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`a:A`;`b:A`;`z21:A`]
           EBV_IN_IN_B) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) z22 (B:A)` ASSUME_TAC THENL
   [MP_TAC(ISPECL
           [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`a':A`;`b:A`;`z22:A`]
           EBV_IN_IN_B) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  EBALG_MEET_TAC `z20:A` `z21:A` `z23:A` THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq z23 z22` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
      `a:A`;`a':A`;`b:A`;`z20:A`;`z21:A`;`z22:A`;`z23:A`] EBV_IN_CONG_L) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) z23 (U:A)` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`U:A`;
      `z20:A`;`z21:A`;`z23:A`] EULTRA_MEET) THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  EXISTS_TAC `z22:A` THEN ASM_REWRITE_TAC[] THEN
  MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`U:A`;
    `z23:A`;`z22:A`] EULTRA_UP) THEN ASM_REWRITE_TAC[]);;

let UMEM_CONG_R = prove
 (`!D (E:A->A->bool) B leq U a b b'.
      model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
      eultra D E B leq U /\
      a IN D /\ b IN D /\ b' IN D /\
      bname D E B a /\ bname D E B b /\ bname D E B b' /\
      usim D E B leq U b b' /\ umem D E B leq U a b
      ==> umem D E B leq U a b'`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `ebalg D (E:A->A->bool) B leq` ASSUME_TAC THENL
   [ASM_MESON_TAC[ECBA_IMP_BALG]; ALL_TAC] THEN
  UNDISCH_TAC `umem D (E:A->A->bool) B leq U a b` THEN
  UNDISCH_TAC `usim D (E:A->A->bool) B leq U b b'` THEN
  REWRITE_TAC[usim; umem; ubig] THEN
  DISCH_THEN(X_CHOOSE_THEN `z20:A` STRIP_ASSUME_TAC) THEN
  DISCH_THEN(X_CHOOSE_THEN `z21:A` STRIP_ASSUME_TAC) THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`a:A`;`b':A`]
    EBV_TOTAL) THEN ASM_REWRITE_TAC[] THEN
  DISCH_THEN(CONJUNCTS_THEN2
    (X_CHOOSE_THEN `z22:A` STRIP_ASSUME_TAC) (K ALL_TAC)) THEN
  SUBGOAL_THEN `(E:A->A->bool) z20 (B:A)` ASSUME_TAC THENL
   [MP_TAC(ISPECL
           [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`b:A`;`b':A`;`z20:A`]
           EBV_EQ_IN_B) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) z21 (B:A)` ASSUME_TAC THENL
   [MP_TAC(ISPECL
           [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`a:A`;`b:A`;`z21:A`]
           EBV_IN_IN_B) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) z22 (B:A)` ASSUME_TAC THENL
   [MP_TAC(ISPECL
           [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`a:A`;`b':A`;`z22:A`]
           EBV_IN_IN_B) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  EBALG_MEET_TAC `z20:A` `z21:A` `z23:A` THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq z23 z22` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
      `b:A`;`b':A`;`a:A`;`z20:A`;`z21:A`;`z22:A`;`z23:A`] EBV_IN_CONG_R) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) z23 (U:A)` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`U:A`;
      `z20:A`;`z21:A`;`z23:A`] EULTRA_MEET) THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  EXISTS_TAC `z22:A` THEN ASM_REWRITE_TAC[] THEN
  MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`U:A`;
    `z23:A`;`z22:A`] EULTRA_UP) THEN ASM_REWRITE_TAC[]);;

(* ===================================================================== *)
(* F8-B: SCOTT-FREE QUOTIENT via Hilbert-choice representative.          *)
(*                                                                       *)
(* Eq is hard-wired to HOL identity in `holds`, so the quotient model    *)
(* must be normal: we need canonical representatives of the ~_U classes. *)
(* The class-membership predicate  (\b. b IN D /\ bname b /\ usim U a b)  *)
(* is ~_U-invariant (USIM_REFL/SYM/TRANS), so Hilbert choice `@` on it    *)
(* yields a canonical representative directly -- NO ranks/stages.  This   *)
(* matters because bname stages are indexed by N-INTERNAL ordinals, which *)
(* for a nonstandard N are NOT meta-wellordered, so any "least stage"     *)
(* meta-choice would be unsound.  `b IN D` is baked into the predicate so *)
(* junk x NOT IN D make the choice predicate trivially false, keeping the *)
(* representative inside D.                                               *)
(* ===================================================================== *)

let qrep = new_definition
  `qrep D (E:A->A->bool) B leq U a =
     (@b. b IN D /\ bname D E B b /\ usim D E B leq U a b)`;;

let qdom = new_definition
  `qdom D (E:A->A->bool) B leq U u <=>
     ?a. a IN D /\ bname D E B a /\ u = qrep D E B leq U a`;;

let qmem = new_definition
  `qmem D (E:A->A->bool) B leq U u w <=> umem D E B leq U u w`;;

(* choice respects extensional predicate equality *)
let SELECT_SIM_EQ = prove
 (`(!x:A. P x <=> Q x) ==> (@x:A. P x) = (@x:A. Q x)`,
  STRIP_TAC THEN AP_TERM_TAC THEN REWRITE_TAC[FUN_EQ_THM] THEN
  ASM_REWRITE_TAC[]);;

(* the chosen representative is in D, is a bname, and is ~_U to a *)
let QREP_SPEC = prove
 (`!D (E:A->A->bool) B leq U a.
      model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
      eultra D E B leq U /\ a IN D /\ bname D E B a
      ==> (qrep D E B leq U a) IN D /\
          bname D E B (qrep D E B leq U a) /\
          usim D E B leq U a (qrep D E B leq U a)`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `?b:A. b IN D /\ bname D E B b /\ usim D E B leq U a b`
    (MP_TAC o SELECT_RULE) THENL
   [EXISTS_TAC `a:A` THEN ASM_REWRITE_TAC[] THEN
    MATCH_MP_TAC USIM_REFL THEN ASM_REWRITE_TAC[];
    REWRITE_TAC[GSYM qrep] THEN DISCH_THEN ACCEPT_TAC]);;

(* canonicity: same ~_U class <=> same representative *)
let QREP_EQ = prove
 (`!D (E:A->A->bool) B leq U a c.
      model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
      eultra D E B leq U /\ a IN D /\ c IN D /\
      bname D E B a /\ bname D E B c
      ==> (usim D E B leq U a c <=>
           qrep D E B leq U a = qrep D E B leq U c)`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN EQ_TAC THENL
   [DISCH_TAC THEN REWRITE_TAC[qrep] THEN MATCH_MP_TAC SELECT_SIM_EQ THEN
    X_GEN_TAC `x:A` THEN
    ASM_CASES_TAC `(x:A) IN D` THEN ASM_REWRITE_TAC[] THEN
    ASM_CASES_TAC `bname D (E:A->A->bool) B x` THEN ASM_REWRITE_TAC[] THEN
    EQ_TAC THEN DISCH_TAC THENL
     [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`U:A`;
        `c:A`;`a:A`;`x:A`] USIM_TRANS) THEN ASM_REWRITE_TAC[] THEN
      MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`U:A`;
        `a:A`;`c:A`] USIM_SYM) THEN ASM_REWRITE_TAC[];
      MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`U:A`;
        `a:A`;`c:A`;`x:A`] USIM_TRANS) THEN ASM_REWRITE_TAC[]];
    DISCH_TAC THEN
    MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`U:A`;`a:A`]
      QREP_SPEC) THEN ASM_REWRITE_TAC[] THEN STRIP_TAC THEN
    MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`U:A`;`c:A`]
      QREP_SPEC) THEN ASM_REWRITE_TAC[] THEN STRIP_TAC THEN
    MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`U:A`;
      `a:A`;`qrep D (E:A->A->bool) B leq U a`;`c:A`] USIM_TRANS) THEN
    ASM_REWRITE_TAC[] THEN
    SUBST1_TAC(ASSUME
               `qrep D (E:A->A->bool) B leq U a = qrep D E B leq U c`) THEN
    MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`U:A`;
      `c:A`;`qrep D (E:A->A->bool) B leq U c`] USIM_SYM) THEN
    ASM_REWRITE_TAC[]]);;

(* quotient domain is nonempty (given any witnessing bname a0) *)
let QDOM_NONEMPTY = prove
 (`!D (E:A->A->bool) B leq U a0.
      model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
      eultra D E B leq U /\ a0 IN D /\ bname D E B a0
      ==> ?u. qdom D E B leq U u`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  EXISTS_TAC `qrep D (E:A->A->bool) B leq U a0` THEN REWRITE_TAC[qdom] THEN
  EXISTS_TAC `a0:A` THEN ASM_REWRITE_TAC[]);;

(* ===================================================================== *)
(* F8-C: a Boolean-value lemma feeding the MAXIMUM PRINCIPLE (pure       *)
(* BA / bval-value layer, no internal-N construction yet).               *)
(*   MAXPRIN_LEIBNIZ_STEP-- c<=[[a=astar]] /\ c<=[[p(a)]] ==>             *)
(*                          c<=[[p(astar)]]  (the C4 mixing->value step). *)
(* ===================================================================== *)

(* MAXPRIN_LEIBNIZ_STEP (C4 core): if c is below both [[a=astar]] and
   [[p(a)]], then c is below [[p(astar)]].  Leibniz/substitution via
   BVAL_SUBST_CONG.  The single value-algebra step that turns the mixture
   property ([[astar=a]]>=cond, [[p(a)]]>=cond) into [[p(astar)]]>=cond. *)
let MAXPRIN_LEIBNIZ_STEP = prove
 (`!n p D (E:A->A->bool) B leq v a astar c eas.
      model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
      valuation D v /\ (!i. bname D E B (v i)) /\
      a IN D /\ astar IN D /\ bname D E B a /\ bname D E B astar /\
      c IN D /\ E c B /\
      eas IN D /\ ebv_eq D E B leq a astar eas /\
      erel D E leq c eas /\
      erel D E leq c (bvalf D E B leq ((n |-> a) v) p)
      ==> erel D E leq c (bvalf D E B leq ((n |-> astar) v) p)`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `ebalg D (E:A->A->bool) B leq /\ eporder D (E:A->A->bool) B leq`
    STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[ECBA_IMP_BALG; EBALG_IMP_PORDER]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) eas B` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
      `a:A`;`astar:A`;`eas:A`] EBV_EQ_IN_B) THEN ASM_REWRITE_TAC[];
      ALL_TAC] THEN
  SUBGOAL_THEN `valuation D ((n |-> (a:A)) v) /\
                (!i. bname D (E:A->A->bool) B (((n |-> (a:A)) v) i))`
  STRIP_ASSUME_TAC THENL
   [CONJ_TAC THENL
     [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[];
      MATCH_MP_TAC BNAMEVAL_VALMOD THEN ASM_REWRITE_TAC[]]; ALL_TAC] THEN
  SUBGOAL_THEN `valuation D ((n |-> (astar:A)) v) /\
                (!i. bname D (E:A->A->bool) B (((n |-> (astar:A)) v) i))`
  STRIP_ASSUME_TAC THENL
   [CONJ_TAC THENL
     [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[];
      MATCH_MP_TAC BNAMEVAL_VALMOD THEN ASM_REWRITE_TAC[]]; ALL_TAC] THEN
  SUBGOAL_THEN
    `(bvalf D (E:A->A->bool) B leq ((n |-> (a:A)) v) p) IN D /\
     (E:A->A->bool) (bvalf D E B leq ((n |-> (a:A)) v) p) B`
  STRIP_ASSUME_TAC THENL
   [CONJ_TAC THENL
     [MP_TAC(ISPECL [`p:form`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
        `(n |-> (a:A)) (v:num->A)`] BVALF_SPEC) THEN ASM_SIMP_TAC[];
      MP_TAC(ISPECL [`p:form`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
        `(n |-> (a:A)) (v:num->A)`] BVALF_IN_B) THEN ASM_SIMP_TAC[]];
     ALL_TAC] THEN
  SUBGOAL_THEN
    `(bvalf D (E:A->A->bool) B leq ((n |-> (astar:A)) v) p) IN D /\
     (E:A->A->bool) (bvalf D E B leq ((n |-> (astar:A)) v) p) B`
  STRIP_ASSUME_TAC THENL
   [CONJ_TAC THENL
     [MP_TAC(ISPECL [`p:form`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
        `(n |-> (astar:A)) (v:num->A)`] BVALF_SPEC) THEN ASM_SIMP_TAC[];
      MP_TAC(ISPECL [`p:form`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
        `(n |-> (astar:A)) (v:num->A)`] BVALF_IN_B) THEN ASM_SIMP_TAC[]];
     ALL_TAC] THEN
  (* m = eas /\ [[p(a)]] *)
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`eas:A`;
    `bvalf D (E:A->A->bool) B leq ((n |-> (a:A)) v) p`] EBALG_MEET) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `m:A`) THEN
  SUBGOAL_THEN `(m:A) IN D /\ (E:A->A->bool) m B` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[EMEET_IN]; ALL_TAC] THEN
  (* c <= m *)
  SUBGOAL_THEN `erel D (E:A->A->bool) leq c m` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`eas:A`;
      `bvalf D (E:A->A->bool) B leq ((n |-> (a:A)) v) p`;`m:A`;`c:A`]
      EMEET_GREATEST) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* m <= [[p(astar)]]  (Leibniz) *)
  SUBGOAL_THEN
    `erel D (E:A->A->bool) leq m (bvalf D E B leq ((n |-> (astar:A)) v) p)`
  ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL [`p:form`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
      `v:num->A`;`n:num`;`a:A`;`astar:A`;`eas:A`;`m:A`] BVAL_SUBST_CONG) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* c <= m <= [[p(astar)]] *)
  MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`c:A`;`m:A`;
    `bvalf D (E:A->A->bool) B leq ((n |-> (astar:A)) v) p`] EPORDER_TRANS) THEN
  ASM_REWRITE_TAC[]);;

(* VALSTAGE_BOUND (F8-C C2): a single B-name stage dd (its members are all
   B-names) whose value-image set SS = { [[p]]_{(n|->s)v} : s in dd } has
   [[?? n p]]_v as its LEAST upper bound.  Via STABILIZE_LAMBDA (uniform
   stabilizing rank) + BVAL_REPLIMG_EXISTS (the image set) + the ex-sup
   sandwich BVALF_EX_UB / BVALF_EX_LEAST. *)
(* MEMNAME (F8-C C2-sep): from a B-name stage dd, build a B-name m = "the set
   { q in dd : phi(q) }" as an ESEPNAME of the FULL name C=EFULLNAME(dd), so
   that for every q in dd, [[q IN m]] = [[phi(q)]]_{(n|->q)v}.  Uses
   EFULLNAME (whose members all get value top) + ESEPNAME (Bell separation
   name) + EBV_IN_SEP value characterization.  m is a bname via ESEPNAME_BNAME
   (C bname via EFULLNAME_BNAME with fa:=lam, fy:=dd). *)
let MEMNAME = prove
 (`!n p D (E:A->A->bool) B leq v dd lam.
      model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
      valuation D v /\ (!i. bname D E B (v i)) /\
      dd IN D /\ eordinal D E lam /\ lam IN D /\ ebnstage D E B lam dd
      ==> ?m. m IN D /\ bname D E B m /\
              (!q z. q IN D /\ E q dd /\ z IN D /\ ebv_in D E B leq q m z
                     ==> z = bvalf D E B leq ((n |-> q) v) p)`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `ebalg D (E:A->A->bool) B leq /\ eporder D (E:A->A->bool) B leq`
    STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[ECBA_IMP_BALG; EBALG_IMP_PORDER]; ALL_TAC] THEN
  (* ddbn: dd's members are all B-names *)
  SUBGOAL_THEN `!s:A. s IN D /\ E s dd ==> bname D E B s`
    (LABEL_TAC "ddbn") THENL
   [X_GEN_TAC `s:A` THEN STRIP_TAC THEN MATCH_MP_TAC BNAME_STAGE THEN
    MAP_EVERY EXISTS_TAC [`lam:A`;`dd:A`] THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* onebee = top of B *)
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`] EBALG_TOP) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `onebee:A` (LABEL_TAC "topb")) THEN
  SUBGOAL_THEN `(onebee:A) IN D /\ (E:A->A->bool) onebee B`
    STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[ETOP_IN]; ALL_TAC] THEN
  (* C = EFULLNAME(dd) *)
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`onebee:A`;`dd:A`]
         EFULLNAME_EXISTS) THEN
  ASM_REWRITE_TAC[] THEN
  INTRO_TAC "@C. Cin Cisf Cdom Cap Cmem" THEN
  (* C is a bname (full name of the stage dd, via fa:=lam, fy:=dd) *)
  SUBGOAL_THEN `bname D (E:A->A->bool) B C` (LABEL_TAC "Cbn") THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`onebee:A`;`dd:A`;
                  `lam:A`;`dd:A`;`C:A`] EFULLNAME_BNAME) THEN
    ASM_REWRITE_TAC[] THEN MESON_TAC[]; ALL_TAC] THEN
  (* m = ESEPNAME(C, phi)  (sep variable = n) *)
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`v:num->A`;`p:form`;
    `n:num`;`C:A`] ESEPNAME_EXISTS) THEN
  ASM_REWRITE_TAC[] THEN
  INTRO_TAC "@m. min misf mdom map mmem" THEN
  (* m is a bname *)
  SUBGOAL_THEN `bname D (E:A->A->bool) B m` (LABEL_TAC "mbn") THENL
   [MP_TAC(ISPECL
           [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`v:num->A`;`p:form`;
            `n:num`;`C:A`;`m:A`] ESEPNAME_BNAME) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  EXISTS_TAC `m:A` THEN ASM_REWRITE_TAC[] THEN
  MAP_EVERY X_GEN_TAC [`q:A`;`z:A`] THEN STRIP_TAC THEN
  SUBGOAL_THEN `bname D (E:A->A->bool) B q` (LABEL_TAC "qbn") THENL
   [ASM_MESON_TAC[]; ALL_TAC] THEN
  (* valuation & bnames of (n|->q)v; [[phi(q)]] IN D and E .. B *)
  SUBGOAL_THEN `valuation D ((n |-> (q:A)) (v:num->A))`
    (LABEL_TAC "valq") THENL
   [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `!i. bname D (E:A->A->bool) B (((n |-> (q:A)) (v:num->A)) i)`
    (LABEL_TAC "bnq") THENL
   [MATCH_MP_TAC BNAMEVAL_VALMOD THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN
   `(bvalf D (E:A->A->bool) B leq ((n |-> q) v) p) IN D /\
    (E:A->A->bool) (bvalf D E B leq ((n |-> q) v) p) B`
   STRIP_ASSUME_TAC THENL
   [CONJ_TAC THENL
     [MP_TAC(ISPECL [`p:form`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
        `(n |-> (q:A)) (v:num->A)`] BVALF_SPEC) THEN ASM_SIMP_TAC[];
      MP_TAC(ISPECL [`p:form`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
        `(n |-> (q:A)) (v:num->A)`] BVALF_IN_B) THEN ASM_SIMP_TAC[]];
    ALL_TAC] THEN
  (* zia = [[q IN C]] *)
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`q:A`;`C:A`]
    EBV_IN_VAL_EXISTS) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `zia:A` (CONJUNCTS_THEN2 (LABEL_TAC "ziain")
    (CONJUNCTS_THEN2 (LABEL_TAC "ziaB") (LABEL_TAC "ziaeq")))) THEN
  (* es = [[q=q]], which is top *)
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`q:A`;`q:A`]
    EBV_EQ_VAL_EXISTS) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `es:A` (CONJUNCTS_THEN2 (LABEL_TAC "esin")
    (CONJUNCTS_THEN2 (LABEL_TAC "esB") (LABEL_TAC "eseq")))) THEN
  SUBGOAL_THEN `etop D (E:A->A->bool) B leq es` (LABEL_TAC "estop") THENL
   [MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`q:A`;`es:A`]
      EBV_EQ_REFL) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* eapply C q onebee *)
  SUBGOAL_THEN `eapply D (E:A->A->bool) C q onebee` (LABEL_TAC "Capq") THENL
   [USE_THEN "Cap" MATCH_MP_TAC THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* es <= zia  (EFULLNAME_IN_GE_ELT: [[q=q]] <= [[q IN C]]) *)
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`onebee:A`;`C:A`;
    `q:A`;`q:A`;`zia:A`;`es:A`] EFULLNAME_IN_GE_ELT) THEN
  ASM_REWRITE_TAC[] THEN DISCH_TAC THEN
  (* es = onebee (both top) *)
  SUBGOAL_THEN `es:A = onebee` SUBST_ALL_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`es:A`;`onebee:A`]
                 ETOP_UNIQUE) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* zia = onebee (antisymmetry) *)
  SUBGOAL_THEN `zia:A = onebee` SUBST_ALL_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`zia:A`;`onebee:A`]
                 EPORDER_ANTISYM) THEN
    ASM_REWRITE_TAC[] THEN
    MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`onebee:A`;`zia:A`]
                 ETOP_GE) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* final: EBV_IN_SEP gives z = [[phi(q)]] with zia = onebee (top) *)
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`v:num->A`;`p:form`;
    `n:num`;`C:A`;`q:A`;`m:A`;`z:A`;`onebee:A`;
    `bvalf D (E:A->A->bool) B leq ((n |-> (q:A)) v) p`] EBV_IN_SEP) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN MATCH_MP_TAC THEN
  (* remaining: emeet onebee [[phi(q)]] [[phi(q)]] *)
  MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
    `bvalf D (E:A->A->bool) B leq ((n |-> (q:A)) v) p`;`onebee:A`;
    `bvalf D (E:A->A->bool) B leq ((n |-> (q:A)) v) p`] EMEET_SYM) THEN
  MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`onebee:A`;
    `bvalf D (E:A->A->bool) B leq ((n |-> (q:A)) v) p`] EMEET_TOP) THEN
  ASM_REWRITE_TAC[]);;

(* ===================================================================== *)
(* F8-C  C3 MIXTURE NAME -- object-formula + value layer.                 *)
(* Builds the mixture a*(u) = elub { g(q) /\ ap_q(u) : q IN dd } as a      *)
(* B-name, mirroring the CHOICE funcval_fm/phi_func template.  Slot map:   *)
(*   1=leq 2=B 5=dd 6=a*(u)(out) 7=section VS 8=comp-var 9=q 10=g(q)=w_q    *)
(*   11=<q,w_q> 12=q(u) 13=<u,q(u)> 15=g(first-value graph) 16=u 20=<u,out> *)
(* ===================================================================== *)

let phi_mix = new_definition
 `phi_mix =
    ?? 7 (
      (!! 8 ((8 %% 7) <->
         (?? 9 (?? 10 (?? 11 (?? 12 (?? 13 (
            (9 %% 5) &&
            opair_form 9 10 11 && (11 %% 15) &&
            opair_form 16 12 13 && (13 %% 9) &&
            bmeet_form 1 2 10 12 8 )))))))) &&
      elub_form 2 1 7 6 )`;;

(* Atomic body under the 5 inner binders 9,10,11,12,13 (with 8=b fixed). *)
let MIX_ATOM = prove
 (`!D (E:A->A->bool) vv b a9 a10 a11 a12 a13.
     model D E ZF_AX /\ valuation D vv /\
     b IN D /\ a9 IN D /\ a10 IN D /\ a11 IN D /\ a12 IN D /\ a13 IN D
     ==> (holds D E
            ((13|->a13)
             ((12|->a12)((11|->a11)((10|->a10)((9|->a9)((8|->b)vv))))))
            ((9 %% 5) &&
             opair_form 9 10 11 && (11 %% 15) &&
             opair_form 16 12 13 && (13 %% 9) &&
             bmeet_form 1 2 10 12 8)
          <=> E a9 (vv 5) /\
              eopair D E a9 a10 a11 /\ E a11 (vv 15) /\
              eopair D E (vv 16) a12 a13 /\ E a13 a9 /\
              emeet D E (vv 2) (vv 1) a10 a12 b)`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN
   `valuation D
      ((13|->a13)
       ((12|->a12)((11|->a11)((10|->a10)((9|->a9)((8|->b)(vv:num->A)))))))`
   ASSUME_TAC THENL
   [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
  ASM_SIMP_TAC[HOLDS_AND; HOLDS_OPAIR_FORM; HOLDS_MEM; HOLDS_BMEET_FORM] THEN
  REWRITE_TAC[VALMOD; ARITH_EQ]);;

(* Flat 5-existential characterization of the section body (avoids deep *)
(* MESON). *)
let MIX_SECTION = prove
 (`!D (E:A->A->bool) v b.
     model D E ZF_AX /\ valuation D v /\ b IN D
     ==> (holds D E ((8|->b)v)
            (?? 9 (?? 10 (?? 11 (?? 12 (?? 13 (
               (9 %% 5) &&
               opair_form 9 10 11 && (11 %% 15) &&
               opair_form 16 12 13 && (13 %% 9) &&
               bmeet_form 1 2 10 12 8))))))
          <=> ?a9 a10 a11 a12 a13.
                  a9 IN D /\ a10 IN D /\ a11 IN D /\ a12 IN D /\ a13 IN D /\
                  E a9 (v 5) /\
                  eopair D E a9 a10 a11 /\ E a11 (v 15) /\
                  eopair D E (v 16) a12 a13 /\ E a13 a9 /\
                  emeet D E (v 2) (v 1) a10 a12 b)`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  REWRITE_TAC[HOLDS_EX] THEN
  EQ_TAC THENL
   [INTRO_TAC "@a9. d9 @a10. d10 @a11. d11 @a12. d12 @a13. d13 hb" THEN
    SUBGOAL_THEN
     `E a9 (v 5) /\
      eopair D (E:A->A->bool) a9 a10 a11 /\ E a11 (v 15) /\
      eopair D E (v 16) a12 a13 /\ E a13 a9 /\
      emeet D E ((v:num->A) 2) (v 1) a10 a12 b`
     STRIP_ASSUME_TAC THENL
     [MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`v:num->A`;`b:A`;
        `a9:A`;`a10:A`;`a11:A`;`a12:A`;`a13:A`] MIX_ATOM) THEN
      ASM_REWRITE_TAC[]; ALL_TAC] THEN
    MAP_EVERY EXISTS_TAC [`a9:A`;`a10:A`;`a11:A`;`a12:A`;`a13:A`] THEN
    ASM_REWRITE_TAC[];
    DISCH_THEN
     (X_CHOOSE_THEN `a9:A` (X_CHOOSE_THEN `a10:A`
     (X_CHOOSE_THEN `a11:A` (X_CHOOSE_THEN `a12:A`
     (X_CHOOSE_THEN `a13:A` STRIP_ASSUME_TAC))))) THEN
    EXISTS_TAC `a9:A` THEN ASM_REWRITE_TAC[] THEN
    EXISTS_TAC `a10:A` THEN ASM_REWRITE_TAC[] THEN
    EXISTS_TAC `a11:A` THEN ASM_REWRITE_TAC[] THEN
    EXISTS_TAC `a12:A` THEN ASM_REWRITE_TAC[] THEN
    EXISTS_TAC `a13:A` THEN ASM_REWRITE_TAC[] THEN
    MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`v:num->A`;`b:A`;
      `a9:A`;`a10:A`;`a11:A`;`a12:A`;`a13:A`] MIX_ATOM) THEN
    ASM_REWRITE_TAC[]]);;

(* Comprehension: slot 7 = the section  { b : exists q,bg,bgpr,bq,bqpr. ... *)
(* }. *)
let MIX_COMP = prove
 (`!D (E:A->A->bool) vv.
     model D E ZF_AX /\ valuation D vv
     ==> (holds D E vv
            (!! 8 ((8 %% 7) <->
               (?? 9 (?? 10 (?? 11 (?? 12 (?? 13 (
                  (9 %% 5) &&
                  opair_form 9 10 11 && (11 %% 15) &&
                  opair_form 16 12 13 && (13 %% 9) &&
                  bmeet_form 1 2 10 12 8))))))))
          <=> (!b. b IN D ==> (E b (vv 7) <=>
                ?a9 a10 a11 a12 a13.
                    a9 IN D /\ a10 IN D /\ a11 IN D /\ a12 IN D /\ a13 IN D /\
                    E a9 (vv 5) /\
                    eopair D E a9 a10 a11 /\ E a11 (vv 15) /\
                    eopair D E (vv 16) a12 a13 /\ E a13 a9 /\
                    emeet D E (vv 2) (vv 1) a10 a12 b)))`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  ASM_SIMP_TAC[HOLDS_ALL] THEN
  REWRITE_TAC[HOLDS_IFF; HOLDS_MEM] THEN
  REWRITE_TAC[VALMOD; ARITH_EQ] THEN
  EQ_TAC THEN DISCH_TAC THEN X_GEN_TAC `b:A` THEN DISCH_TAC THEN
  FIRST_X_ASSUM(MP_TAC o SPEC `b:A`) THEN ASM_REWRITE_TAC[] THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`vv:num->A`;`b:A`]
         MIX_SECTION) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN SUBST1_TAC THEN DISCH_THEN ACCEPT_TAC);;

(* Conjunctive body under binder 7 (=VS). *)
let MIX_CONJ = prove
 (`!D (E:A->A->bool) v a7.
     model D E ZF_AX /\ valuation D v /\ a7 IN D
     ==> (holds D E ((7|->a7)v)
            ((!! 8 ((8 %% 7) <->
               (?? 9 (?? 10 (?? 11 (?? 12 (?? 13 (
                  (9 %% 5) &&
                  opair_form 9 10 11 && (11 %% 15) &&
                  opair_form 16 12 13 && (13 %% 9) &&
                  bmeet_form 1 2 10 12 8))))))))
             && elub_form 2 1 7 6)
          <=>
          (!b. b IN D ==> (E b a7 <=>
                ?a9 a10 a11 a12 a13.
                    a9 IN D /\ a10 IN D /\ a11 IN D /\ a12 IN D /\ a13 IN D /\
                    E a9 (v 5) /\
                    eopair D E a9 a10 a11 /\ E a11 (v 15) /\
                    eopair D E (v 16) a12 a13 /\ E a13 a9 /\
                    emeet D E (v 2) (v 1) a10 a12 b)) /\
          elub D E (v 2) (v 1) a7 (v 6))`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `valuation D ((7|->a7)(v:num->A))` ASSUME_TAC THENL
   [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
  ASM_SIMP_TAC[HOLDS_AND; HOLDS_ELUB_FORM] THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`(7|->a7)(v:num->A)`]
         MIX_COMP) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN SUBST1_TAC THEN
  REWRITE_TAC[VALMOD; ARITH_EQ]);;

(* Full holds-characterization of phi_mix. *)
let MIX_HOLDS = prove
 (`!D (E:A->A->bool) v.
     model D E ZF_AX /\ valuation D v
     ==> (holds D E v phi_mix <=>
          ?VS. VS IN D /\
               (!b. b IN D ==> (E b VS <=>
                     ?a9 a10 a11 a12 a13.
                         a9 IN D /\ a10 IN D /\ a11 IN D /\
                           a12 IN D /\ a13 IN D /\
                         E a9 (v 5) /\
                         eopair D E a9 a10 a11 /\ E a11 (v 15) /\
                         eopair D E (v 16) a12 a13 /\ E a13 a9 /\
                         emeet D E (v 2) (v 1) a10 a12 b)) /\
               elub D E (v 2) (v 1) VS (v 6))`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  REWRITE_TAC[phi_mix; HOLDS_EX] THEN
  EQ_TAC THENL
   [DISCH_THEN(X_CHOOSE_THEN `a7:A` (CONJUNCTS_THEN2 ASSUME_TAC MP_TAC)) THEN
    MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`v:num->A`;`a7:A`] MIX_CONJ) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN SUBST1_TAC THEN STRIP_TAC THEN
    EXISTS_TAC `a7:A` THEN ASM_REWRITE_TAC[];
    DISCH_THEN(X_CHOOSE_THEN `VS:A` STRIP_ASSUME_TAC) THEN
    EXISTS_TAC `VS:A` THEN CONJ_TAC THENL
    [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`v:num->A`;`VS:A`] MIX_CONJ) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN SUBST1_TAC THEN ASM_REWRITE_TAC[]]);;

(* Existence of the mixture output at a fixed input point (v 16 = u):
   section VS = { b : the 5-existential } via ZF_SEPARATION on B; each such b
   is a meet, hence in B (EMEET_IN); sup via ECBA_SUP;
   run MIX_HOLDS backwards. *)
let MIX_EXISTS = prove
 (`!D (E:A->A->bool) B leq v.
      model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
      valuation D v /\ v 1 = leq /\ v 2 = B
      ==> ?val. val IN D /\ E val B /\ holds D E ((6 |-> val) v) phi_mix`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`] ZF_SEPARATION) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(MP_TAC o SPECL
    [`?? 9 (?? 10 (?? 11 (?? 12 (?? 13 (
        (9 %% 5) && opair_form 9 10 11 && (11 %% 15) &&
        opair_form 16 12 13 && (13 %% 9) && bmeet_form 1 2 10 12 8)))))`;
     `8`;`v:num->A`;`B:A`]) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `s:A`
             (CONJUNCTS_THEN2 ASSUME_TAC (LABEL_TAC "sdef"))) THEN
  SUBGOAL_THEN
   `!z:A. z IN D ==> (E z s <=>
        ?a9 a10 a11 a12 a13.
            a9 IN D /\ a10 IN D /\ a11 IN D /\ a12 IN D /\ a13 IN D /\
            E a9 ((v:num->A) 5) /\ eopair D E a9 a10 a11 /\ E a11 (v 15) /\
            eopair D E (v 16) a12 a13 /\ E a13 a9 /\
            emeet D E (v 2) (v 1) a10 a12 z)`
   (LABEL_TAC "sec") THENL
   [X_GEN_TAC `z:A` THEN DISCH_THEN(LABEL_TAC "zin") THEN
    USE_THEN "sdef" (fun sd -> USE_THEN "zin" (fun zi ->
      SUBST1_TAC(MP (SPEC `z:A` sd) zi))) THEN
    MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`v:num->A`;`z:A`]
           MIX_SECTION) THEN
    ASM_REWRITE_TAC[] THEN DISCH_THEN SUBST1_TAC THEN
    EQ_TAC THENL
     [MESON_TAC[];
      DISCH_TAC THEN ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[EMEET_IN]];
     ALL_TAC] THEN
  SUBGOAL_THEN `esubset D (E:A->A->bool) s B` ASSUME_TAC THENL
   [REWRITE_TAC[esubset] THEN X_GEN_TAC `w:A` THEN STRIP_TAC THEN
    ASM_MESON_TAC[EMEET_IN]; ALL_TAC] THEN
  REMOVE_THEN "sdef" (K ALL_TAC) THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`s:A`] ECBA_SUP) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `val:A` ASSUME_TAC) THEN
  SUBGOAL_THEN `(val:A) IN D /\ (E:A->A->bool) val B` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[ELUB_IN]; ALL_TAC] THEN
  EXISTS_TAC `val:A` THEN ASM_REWRITE_TAC[] THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`(6 |-> (val:A)) (v:num->A)`]
    MIX_HOLDS) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[] THEN MATCH_MP_TAC VALUATION_VALMOD THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  DISCH_THEN SUBST1_TAC THEN
  EXISTS_TAC `s:A` THEN REWRITE_TAC[VALMOD; ARITH_EQ] THEN
  REPEAT CONJ_TAC THENL
   [FIRST_ASSUM ACCEPT_TAC;
    X_GEN_TAC `b:A` THEN DISCH_TAC THEN
    REMOVE_THEN "sec" (fun th -> MP_TAC(SPEC `b:A` th)) THEN
    ASM_REWRITE_TAC[] THEN DISCH_THEN SUBST1_TAC THEN ASM_REWRITE_TAC[];
    ASM_REWRITE_TAC[]]);;

(* Destructor. *)
let MIX_DEST = prove
 (`!D (E:A->A->bool) B leq v val.
      model D E ZF_AX /\ valuation D v /\ v 1 = leq /\ v 2 = B /\ val IN D /\
      holds D E ((6 |-> val) v) phi_mix
      ==> ?VS. VS IN D /\
               (!b. b IN D ==> (E b VS <=>
                     ?a9 a10 a11 a12 a13.
                         a9 IN D /\ a10 IN D /\ a11 IN D /\
                           a12 IN D /\ a13 IN D /\
                         E a9 (v 5) /\ eopair D E a9 a10 a11 /\ E a11 (v 15) /\
                         eopair D E (v 16) a12 a13 /\ E a13 a9 /\
                         emeet D E (v 2) (v 1) a10 a12 b)) /\
               elub D E B leq VS val`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`(6 |-> (val:A)) (v:num->A)`]
    MIX_HOLDS) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[] THEN MATCH_MP_TAC VALUATION_VALMOD THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  REWRITE_TAC[VALMOD; ARITH_EQ] THEN ASM_REWRITE_TAC[] THEN
  DISCH_THEN ACCEPT_TAC);;

(* Functionality: the mixture output is unique.  The section-set equality
   VS1=VS2 is proved by explicit <=> transitivity (both have the SAME 5-nested
   existential body) -- NOT MESON, which blows up on 5 existentials. *)
let MIX_UNIQUE = prove
 (`!D (E:A->A->bool) B leq v val val'.
      model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
        valuation D v /\
      v 1 = leq /\ v 2 = B /\ val IN D /\ val' IN D /\
      holds D E ((6 |-> val) v) phi_mix /\
      holds D E ((6 |-> val') v) phi_mix
      ==> val = val'`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `eporder D (E:A->A->bool) B leq` ASSUME_TAC THENL
   [ASM_MESON_TAC[ECBA_IMP_BALG; EBALG_IMP_PORDER]; ALL_TAC] THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`v:num->A`;`val:A`]
    MIX_DEST) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `VS1:A` (CONJUNCTS_THEN2 (LABEL_TAC "vs1D")
    (CONJUNCTS_THEN2 (LABEL_TAC "ch1") (LABEL_TAC "lub1")))) THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`v:num->A`;`val':A`]
    MIX_DEST) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `VS2:A` (CONJUNCTS_THEN2 (LABEL_TAC "vs2D")
    (CONJUNCTS_THEN2 (LABEL_TAC "ch2") (LABEL_TAC "lub2")))) THEN
  SUBGOAL_THEN `VS1:A = VS2` SUBST_ALL_TAC THENL
   [FIRST_ASSUM(MATCH_MP_TAC o MATCH_MP ZF_EXTENSIONALITY) THEN
    ASM_REWRITE_TAC[] THEN X_GEN_TAC `z:A` THEN DISCH_TAC THEN
    USE_THEN "ch1" (fun h ->
       REWRITE_TAC[MATCH_MP (SPEC `z:A` h) (ASSUME `(z:A) IN D`)]) THEN
    USE_THEN "ch2" (fun h ->
       REWRITE_TAC[MATCH_MP (SPEC `z:A` h) (ASSUME `(z:A) IN D`)]);
    ALL_TAC] THEN
  ASM_MESON_TAC[ELUB_UNIQUE]);;

(* Valuation-agreement for phi_mix: holds depends only on slots *)
(* 1,2,5,6,15,16. *)
let MIX_AGREE = prove
 (`!D (E:A->A->bool) v v'.
     model D E ZF_AX /\ valuation D v /\ valuation D v' /\
     v 16 = v' 16 /\ v 15 = v' 15 /\ v 5 = v' 5 /\
     v 2 = v' 2 /\ v 1 = v' 1 /\ v 6 = v' 6
     ==> (holds D E v phi_mix <=> holds D E v' phi_mix)`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`v:num->A`] MIX_HOLDS) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN DISCH_THEN SUBST1_TAC THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`v':num->A`] MIX_HOLDS) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN DISCH_THEN SUBST1_TAC THEN
  ASM_REWRITE_TAC[]);;

(* phi_mixval = ??6 (phi_mix && opair_form 16 6 20): output slot 20 = <u, *)
(* a*(u)>. *)
let phi_mixval = new_definition
 `phi_mixval = ?? 6 (phi_mix && opair_form 16 6 20)`;;

let MIXVAL_HOLDS = prove
 (`!D (E:A->A->bool) v.
     model D E ZF_AX /\ valuation D v
     ==> (holds D E v phi_mixval <=>
          ?val. val IN D /\ holds D E ((6 |-> val) v) phi_mix /\
                eopair D E (v 16) val (v 20))`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  REWRITE_TAC[phi_mixval; HOLDS_EX] THEN
  EQ_TAC THENL
   [DISCH_THEN(X_CHOOSE_THEN `a:A` (CONJUNCTS_THEN2 ASSUME_TAC MP_TAC)) THEN
    SUBGOAL_THEN `valuation D ((6|->a)(v:num->A))` ASSUME_TAC THENL
     [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
    ASM_SIMP_TAC[HOLDS_AND; HOLDS_OPAIR_FORM] THEN
    REWRITE_TAC[VALMOD; ARITH_EQ] THEN STRIP_TAC THEN
    EXISTS_TAC `a:A` THEN ASM_REWRITE_TAC[];
    DISCH_THEN(X_CHOOSE_THEN `a:A` STRIP_ASSUME_TAC) THEN
    EXISTS_TAC `a:A` THEN
    SUBGOAL_THEN `valuation D ((6|->a)(v:num->A))` ASSUME_TAC THENL
     [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
    ASM_SIMP_TAC[HOLDS_AND; HOLDS_OPAIR_FORM] THEN
    REWRITE_TAC[VALMOD; ARITH_EQ] THEN ASM_REWRITE_TAC[]]);;

let MIXVAL_DEST = prove
 (`!D (E:A->A->bool) v u w.
     model D E ZF_AX /\ valuation D v /\ u IN D /\ w IN D /\
     holds D E ((20 |-> w)((16 |-> u) v)) phi_mixval
     ==> ?val. val IN D /\
               holds D E ((6 |-> val)((20 |-> w)((16 |-> u) v))) phi_mix /\
               eopair D E u val w`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `valuation D ((20|->w)((16|->u)(v:num->A)))` ASSUME_TAC THENL
   [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`(20|->w)((16|->u)(v:num->A))`]
    MIXVAL_HOLDS) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(fun th ->
    MP_TAC(EQ_MP th
           (ASSUME `holds D E ((20|->w)((16|->u)(v:num->A)))
                    phi_mixval`))) THEN
  REWRITE_TAC[VALMOD; ARITH_EQ] THEN
  DISCH_THEN(X_CHOOSE_THEN `val:A` STRIP_ASSUME_TAC) THEN
  EXISTS_TAC `val:A` THEN ASM_REWRITE_TAC[]);;

(* Functionality of phi_mixval: uses MIX_AGREE (strip slot 20) + MIX_UNIQUE,
   NOT extensionality-MESON on the 5-existential section. *)
let MIXVAL_UNIQUE = prove
 (`!D (E:A->A->bool) B leq v u w w'.
     model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
     valuation D v /\ v 1 = leq /\ v 2 = B /\
     u IN D /\ w IN D /\ w' IN D /\
     holds D E ((20 |-> w)((16 |-> u) v)) phi_mixval /\
     holds D E ((20 |-> w')((16 |-> u) v)) phi_mixval
     ==> w = w'`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `valuation D ((16|->u)(v:num->A))` (LABEL_TAC "valu") THENL
   [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`v:num->A`;`u:A`;`w:A`]
         MIXVAL_DEST) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `val:A` STRIP_ASSUME_TAC) THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`v:num->A`;`u:A`;`w':A`]
         MIXVAL_DEST) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `val':A` STRIP_ASSUME_TAC) THEN
  SUBGOAL_THEN `val:A = val'` SUBST_ALL_TAC THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
       `(16|->u)(v:num->A)`;`val:A`;`val':A`] MIX_UNIQUE) THEN
    ASM_REWRITE_TAC[VALMOD; ARITH_EQ] THEN CONJ_TAC THENL
     [MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;
         `(6|->val)((20|->w)((16|->u)(v:num->A)))`;
         `(6|->val)((16|->u)(v:num->A))`] MIX_AGREE) THEN
      ANTS_TAC THENL
       [REWRITE_TAC[VALMOD; ARITH_EQ] THEN ASM_REWRITE_TAC[] THEN
        CONJ_TAC THEN ASM_MESON_TAC[VALUATION_VALMOD];
        DISCH_THEN(fun th -> REWRITE_TAC[GSYM th]) THEN ASM_REWRITE_TAC[]];
      MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;
         `(6|->val')((20|->w')((16|->u)(v:num->A)))`;
         `(6|->val')((16|->u)(v:num->A))`] MIX_AGREE) THEN
      ANTS_TAC THENL
       [REWRITE_TAC[VALMOD; ARITH_EQ] THEN ASM_REWRITE_TAC[] THEN
        CONJ_TAC THEN ASM_MESON_TAC[VALUATION_VALMOD];
        DISCH_THEN(fun th -> REWRITE_TAC[GSYM th]) THEN ASM_REWRITE_TAC[]]];
    ALL_TAC] THEN
  ASM_MESON_TAC[EOPAIR_UNIQUE]);;

let MIXVAL_EXISTS = prove
 (`!D (E:A->A->bool) B leq p v.
     model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\ p IN D /\
     valuation D v /\ v 1 = leq /\ v 2 = B
     ==> ?w. w IN D /\ holds D E ((20 |-> w)((16 |-> p) v)) phi_mixval`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
     `(16|->p)(v:num->A)`] MIX_EXISTS) THEN
  ANTS_TAC THENL
   [REWRITE_TAC[VALMOD; ARITH_EQ] THEN ASM_REWRITE_TAC[] THEN
    ASM_MESON_TAC[VALUATION_VALMOD];
    ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `val:A` STRIP_ASSUME_TAC) THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`p:A`;`val:A`] EOPAIR_EXISTS) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `w0:A` ASSUME_TAC) THEN
  SUBGOAL_THEN `(w0:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[EOPAIR_IN]; ALL_TAC] THEN
  EXISTS_TAC `w0:A` THEN ASM_REWRITE_TAC[] THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`(20|->w0)((16|->p)(v:num->A))`]
    MIXVAL_HOLDS) THEN
  ANTS_TAC THENL
  [ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
  DISCH_THEN SUBST1_TAC THEN
  REWRITE_TAC[VALMOD; ARITH_EQ] THEN
  EXISTS_TAC `val:A` THEN ASM_REWRITE_TAC[] THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;
     `(6|->val)((20|->w0)((16|->p)(v:num->A)))`;
     `(6|->val)((16|->p)(v:num->A))`] MIX_AGREE) THEN
  ANTS_TAC THENL
   [REWRITE_TAC[VALMOD; ARITH_EQ] THEN ASM_REWRITE_TAC[] THEN
    CONJ_TAC THEN ASM_MESON_TAC[VALUATION_VALMOD];
    DISCH_THEN(fun th -> ONCE_REWRITE_TAC[th]) THEN ASM_REWRITE_TAC[]]);;

(* ------------------------------------------------------------------ *)
(* F8-C: the mixture name.                                              *)
(* Given a witnessed family { (q, w_q) : q IN dd } with the w_q         *)
(* pairwise disjoint below meet (via the value-graph g), build one      *)
(* B-name a* (graph name c) with  w_q <= [[a* = q]]  for every q.       *)
(* Endpoint MIX_EQ_GE; supporting layer EPORDER_FIELD, MIX_NAME_EXISTS,  *)
(* MIX_EISFUN, MIX_BNAME, MIX_APPLY_DEST, MIX_MEET_ELUB_LE,             *)
(* MIX_APPLY_EXISTS.                                                     *)
(* ------------------------------------------------------------------ *)

(* a* graph = { w : ?p. p IN W' /\ <p, a*(p)> = w }.  Mirror CSEL_EXISTS. *)
let MIX_NAME_EXISTS = prove
 (`!D (E:A->A->bool) B leq W v.
     model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
     W IN D /\
     valuation D v /\ v 1 = leq /\ v 2 = B
     ==> ?c. c IN D /\
             !w. w IN D
                 ==> (E w c <=>
                      ?p. p IN D /\ E p W /\
                          holds D E ((20 |-> w)((16 |-> p) v)) phi_mixval)`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`] ZF_REPLACEMENT) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(MP_TAC o SPECL [`phi_mixval`; `16`; `20`; `v:num->A`; `W:A`]) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[ARITH_EQ] THEN
    X_GEN_TAC `p:A` THEN STRIP_TAC THEN
    MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`p:A`;`v:num->A`]
      MIXVAL_EXISTS) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(X_CHOOSE_THEN `w0:A` STRIP_ASSUME_TAC) THEN
    EXISTS_TAC `w0:A` THEN ASM_REWRITE_TAC[] THEN
    X_GEN_TAC `w':A` THEN STRIP_TAC THEN
    ASM_MESON_TAC[MIXVAL_UNIQUE];
    ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `c:A` STRIP_ASSUME_TAC) THEN
  EXISTS_TAC `c:A` THEN ASM_REWRITE_TAC[]);;

(* a* graph is a function.  Mirror CSEL_EISFUN. *)
let MIX_EISFUN = prove
 (`!D (E:A->A->bool) B leq W v c.
     model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
     valuation D v /\ v 1 = leq /\ v 2 = B /\ W IN D /\ c IN D /\
     (!w. w IN D ==> (E w c <=>
             ?p. p IN D /\ E p W /\
                 holds D E ((20 |-> w)((16 |-> p) v)) phi_mixval))
     ==> eisfun D E c`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "modl ecba BD leqD val v1 v2 WD cD cch" THEN
  REWRITE_TAC[eisfun] THEN
  CONJ_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  CONJ_TAC THENL
   [X_GEN_TAC `z:A` THEN STRIP_TAC THEN
    USE_THEN "cch" (MP_TAC o SPEC `z:A`) THEN
    ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN(fun th -> MP_TAC(EQ_MP th (ASSUME `(E:A->A->bool) z c`))) THEN
    DISCH_THEN(X_CHOOSE_THEN `p:A` STRIP_ASSUME_TAC) THEN
    MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`v:num->A`;`p:A`;`z:A`]
           MIXVAL_DEST) THEN
    ASM_REWRITE_TAC[] THEN
    DISCH_THEN(X_CHOOSE_THEN `val:A` STRIP_ASSUME_TAC) THEN
    MAP_EVERY EXISTS_TAC [`p:A`;`val:A`] THEN ASM_REWRITE_TAC[];
    MAP_EVERY X_GEN_TAC [`u:A`;`w:A`;`w':A`;`z:A`;`z':A`] THEN STRIP_TAC THEN
    SUBGOAL_THEN `(z:A) IN D /\ (z':A) IN D` STRIP_ASSUME_TAC THENL
     [ASM_MESON_TAC[EOPAIR_IN]; ALL_TAC] THEN
    USE_THEN "cch" (MP_TAC o SPEC `z:A`) THEN
    ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN(fun th -> MP_TAC(EQ_MP th (ASSUME `(E:A->A->bool) z c`))) THEN
    DISCH_THEN(X_CHOOSE_THEN `p1:A` STRIP_ASSUME_TAC) THEN
    MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`v:num->A`;`p1:A`;`z:A`]
           MIXVAL_DEST) THEN
    ASM_REWRITE_TAC[] THEN
    DISCH_THEN(X_CHOOSE_THEN `val1:A` STRIP_ASSUME_TAC) THEN
    SUBGOAL_THEN `p1:A = u` SUBST_ALL_TAC THENL
     [ASM_MESON_TAC[EOPAIR_INJ]; ALL_TAC] THEN
    USE_THEN "cch" (MP_TAC o SPEC `z':A`) THEN
    ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN(fun th -> MP_TAC(EQ_MP th (ASSUME `(E:A->A->bool) z' c`))) THEN
    DISCH_THEN(X_CHOOSE_THEN `p2:A` STRIP_ASSUME_TAC) THEN
    MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`v:num->A`;`p2:A`;`z':A`]
           MIXVAL_DEST) THEN
    ASM_REWRITE_TAC[] THEN
    DISCH_THEN(X_CHOOSE_THEN `val2:A` STRIP_ASSUME_TAC) THEN
    SUBGOAL_THEN `p2:A = u` SUBST_ALL_TAC THENL
     [ASM_MESON_TAC[EOPAIR_INJ]; ALL_TAC] THEN
    SUBGOAL_THEN `z:A = z'` SUBST_ALL_TAC THENL
     [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`v:num->A`;
        `u:A`;`z:A`;`z':A`] MIXVAL_UNIQUE) THEN ASM_REWRITE_TAC[];
           ALL_TAC] THEN
    ASM_MESON_TAC[EOPAIR_INJ]]);;

(* a* is a bname.  Since W' subset w_lam (point-set of the SAME stage lam),  *)
(* a* subset cross(w_lam,B) lands directly in dd = ebnstage lam -- no        *)
(* successor stage needed.  Simpler than CSEL_BNAME.                         *)
let MIX_BNAME = prove
 (`!D (E:A->A->bool) B leq lam dd W v c.
     model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
     lam IN D /\ eordinal D E lam /\ dd IN D /\ ebnstage D E B lam dd /\
     W IN D /\
     (!s. s IN D /\ E s W
          ==> ?b z. b IN D /\ z IN D /\ E b lam /\
            ebnstage D E B b z /\ E s z) /\
     valuation D v /\ v 1 = leq /\ v 2 = B /\
     c IN D /\ eisfun D E c /\
     (!w. w IN D ==> (E w c <=>
             ?p. p IN D /\ E p W /\
                 holds D E ((20 |-> w)((16 |-> p) v)) phi_mixval))
     ==> bname D E B c`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "modl ecba BD leqD lamD lamord ddD ddst WD Wch val v1 v2 cD \
             isf cch" THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`lam:A`;`dd:A`]
         EBNSTAGE_CHAR) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `w1:A` (CONJUNCTS_THEN2 (LABEL_TAC "w1D")
    (CONJUNCTS_THEN2 (LABEL_TAC "w1ch") (LABEL_TAC "funs")))) THEN
  SUBGOAL_THEN `!s:A. s IN D /\ (E:A->A->bool) s W ==> E s w1`
    (LABEL_TAC "Wsub") THENL
   [X_GEN_TAC `s:A` THEN STRIP_TAC THEN
    USE_THEN "w1ch" (MP_TAC o SPEC `s:A`) THEN
    ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    USE_THEN "Wch" (MP_TAC o SPEC `s:A`) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN ACCEPT_TAC; ALL_TAC] THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`w1:A`;`B:A`] ECROSS_EXISTS) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `cr:A` (LABEL_TAC "cr")) THEN
  SUBGOAL_THEN `(cr:A) IN D` ASSUME_TAC THENL
   [USE_THEN "cr" (MP_TAC o REWRITE_RULE[ecross]) THEN SIMP_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `esubset D (E:A->A->bool) c cr` ASSUME_TAC THENL
   [REWRITE_TAC[esubset] THEN X_GEN_TAC `z:A` THEN STRIP_TAC THEN
    USE_THEN "cr" (MP_TAC o SPEC `z:A` o CONJUNCT2 o REWRITE_RULE[ecross]) THEN
    ASM_REWRITE_TAC[] THEN DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    USE_THEN "cch" (MP_TAC o SPEC `z:A`) THEN
    ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN(fun th -> MP_TAC(EQ_MP th (ASSUME `(E:A->A->bool) z c`))) THEN
    DISCH_THEN(X_CHOOSE_THEN `s:A` STRIP_ASSUME_TAC) THEN
    MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`v:num->A`;`s:A`;`z:A`]
           MIXVAL_DEST) THEN
    ASM_REWRITE_TAC[] THEN
    DISCH_THEN(X_CHOOSE_THEN `val:A` STRIP_ASSUME_TAC) THEN
    SUBGOAL_THEN `(E:A->A->bool) s w1` ASSUME_TAC THENL
     [USE_THEN "Wsub" MATCH_MP_TAC THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN `(E:A->A->bool) val B` ASSUME_TAC THENL
     [MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
        `(20|->z)((16|->s)(v:num->A))`;`val:A`] MIX_DEST) THEN
      ANTS_TAC THENL
       [REWRITE_TAC[VALMOD; ARITH_EQ] THEN ASM_REWRITE_TAC[] THEN
        ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
      DISCH_THEN(X_CHOOSE_THEN `VS:A` STRIP_ASSUME_TAC) THEN
      ASM_MESON_TAC[ELUB_IN]; ALL_TAC] THEN
    MAP_EVERY EXISTS_TAC [`s:A`;`val:A`] THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `ebnmem D (E:A->A->bool) B w1 c` ASSUME_TAC THENL
   [REWRITE_TAC[ebnmem] THEN ASM_REWRITE_TAC[] THEN
    EXISTS_TAC `cr:A` THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) c dd` ASSUME_TAC THENL
   [UNDISCH_TAC `ebnfuns D (E:A->A->bool) B w1 dd` THEN
    REWRITE_TAC[ebnfuns] THEN
    DISCH_THEN(MP_TAC o SPEC `c:A` o CONJUNCT2) THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  REWRITE_TAC[bname] THEN MAP_EVERY EXISTS_TAC [`lam:A`;`dd:A`] THEN
  ASM_REWRITE_TAC[]);;

(* Destruct  a*(x) = elub VS_x  where VS_x is the section-set of a*(x):     *)
(* the E x W hypothesis is redundant (the graph char already forces x IN W').*)
let MIX_APPLY_DEST = prove
 (`!D (E:A->A->bool) B leq dd g W v c x ax.
      model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
      dd IN D /\ g IN D /\ W IN D /\
      valuation D v /\ v 1 = leq /\ v 2 = B /\ v 5 = dd /\ v 15 = g /\
      c IN D /\
      (!w. w IN D ==> (E w c <=>
              ?p. p IN D /\ E p W /\
                  holds D E ((20 |-> w)((16 |-> p) v)) phi_mixval)) /\
      x IN D /\ ax IN D /\ eapply D E c x ax
      ==> ?VS. VS IN D /\
               (!b. b IN D ==> (E b VS <=>
                     ?a9 a10 a11 a12 a13.
                         a9 IN D /\ a10 IN D /\ a11 IN D /\
                           a12 IN D /\ a13 IN D /\
                         E a9 dd /\ eopair D E a9 a10 a11 /\ E a11 g /\
                         eopair D E x a12 a13 /\ E a13 a9 /\
                         emeet D E B leq a10 a12 b)) /\
               elub D E B leq VS ax`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  UNDISCH_TAC `eapply D (E:A->A->bool) c x ax` THEN REWRITE_TAC[eapply] THEN
  DISCH_THEN(X_CHOOSE_THEN `zz:A` STRIP_ASSUME_TAC) THEN
  SUBGOAL_THEN `(zz:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[EOPAIR_IN]; ALL_TAC] THEN
  SUBGOAL_THEN
    `?pp. pp IN D /\ E pp W /\
          holds D E ((20|->zz)((16|->pp)(v:num->A))) phi_mixval`
    STRIP_ASSUME_TAC THENL
   [FIRST_X_ASSUM(MP_TAC o SPEC `zz:A`) THEN
    ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN(fun th -> ACCEPT_TAC(EQ_MP th (ASSUME `(E:A->A->bool) zz c`)));
    ALL_TAC] THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`v:num->A`;`pp:A`;`zz:A`]
    MIXVAL_DEST) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `vv:A` STRIP_ASSUME_TAC) THEN
  SUBGOAL_THEN `pp:A = x /\ vv:A = ax` (CONJUNCTS_THEN SUBST_ALL_TAC) THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`pp:A`;`vv:A`;`x:A`;`ax:A`;
      `zz:A`] EOPAIR_INJ) THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
     `(20|->zz)((16|->x)(v:num->A))`;`ax:A`] MIX_DEST) THEN
  ANTS_TAC THENL
   [REWRITE_TAC[VALMOD; ARITH_EQ] THEN ASM_REWRITE_TAC[] THEN
    ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `VS:A` (CONJUNCTS_THEN2 (LABEL_TAC "vsd")
    (CONJUNCTS_THEN2 (LABEL_TAC "vsch") (LABEL_TAC "vslub")))) THEN
  EXISTS_TAC `VS:A` THEN REPEAT CONJ_TAC THENL
   [FIRST_ASSUM ACCEPT_TAC;
    X_GEN_TAC `b:A` THEN DISCH_TAC THEN
    USE_THEN "vsch" (MP_TAC o SPEC `b:A`) THEN
    ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN(fun th -> ACCEPT_TAC(REWRITE_RULE
       [VALMOD; ARITH_EQ; ASSUME `(v:num->A) 5 = dd`;
        ASSUME `(v:num->A) 15 = g`;
        ASSUME `(v:num->A) 2 = B`; ASSUME `(v:num->A) 1 = leq`] th));
    FIRST_ASSUM ACCEPT_TAC]);;

(* Generic: meet-with-wq distributes UNDER an elub via residuation only
   (no infinite distributive law).  If every section term t, met with wq,
   sits below Z, then wq /\ sup <= Z. *)
let MIX_MEET_ELUB_LE = prove
 (`!D (E:A->A->bool) B leq VS sp wq Z m.
      ebalg D E B leq /\
      VS IN D /\ sp IN D /\ E sp B /\ elub D E B leq VS sp /\
      wq IN D /\ E wq B /\ Z IN D /\ E Z B /\
      m IN D /\ emeet D E B leq wq sp m /\
      (!t. t IN D /\ E t VS ==> E t B) /\
      (!t mt. t IN D /\ E t VS /\ emeet D E B leq wq t mt ==>
       erel D E leq mt Z)
      ==> erel D E leq m Z`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `eporder D (E:A->A->bool) B leq` ASSUME_TAC THENL
   [ASM_MESON_TAC[EBALG_IMP_PORDER]; ALL_TAC] THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`wq:A`;`Z:A`]
         EBIMP_EXISTS) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `wZ:A`) THEN
  SUBGOAL_THEN `(wZ:A) IN D /\ (E:A->A->bool) wZ B` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[EBIMP_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `eubound D (E:A->A->bool) B leq VS wZ` ASSUME_TAC THENL
   [REWRITE_TAC[eubound] THEN ASM_REWRITE_TAC[] THEN
    X_GEN_TAC `t:A` THEN STRIP_TAC THEN
    SUBGOAL_THEN `(E:A->A->bool) t B` ASSUME_TAC THENL
     [FIRST_X_ASSUM MATCH_MP_TAC THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`wq:A`;`t:A`]
           EBALG_MEET) THEN
    ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `mt:A`) THEN
    SUBGOAL_THEN `(mt:A) IN D /\ (E:A->A->bool) mt B` STRIP_ASSUME_TAC THENL
     [ASM_MESON_TAC[EMEET_IN]; ALL_TAC] THEN
    SUBGOAL_THEN `erel D (E:A->A->bool) leq mt Z` ASSUME_TAC THENL
     [FIRST_X_ASSUM MATCH_MP_TAC THEN MAP_EVERY EXISTS_TAC [`t:A`] THEN
      ASM_REWRITE_TAC[]; ALL_TAC] THEN
    MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`t:A`;`wq:A`;`Z:A`;
                  `wZ:A`;`mt:A`] EBIMP_LE_IMP) THEN
    ASM_REWRITE_TAC[] THEN
    MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`wq:A`;`t:A`;`mt:A`]
                 EMEET_SYM) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq sp wZ` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`VS:A`;`sp:A`;
                  `wZ:A`] ELUB_LEAST) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MATCH_MP_TAC(ISPECL
               [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`sp:A`;`wq:A`;`Z:A`;
                `wZ:A`;`m:A`] EBIMP_MEET_LE) THEN
  ASM_REWRITE_TAC[] THEN
  MATCH_MP_TAC(ISPECL
               [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`wq:A`;`sp:A`;`m:A`]
               EMEET_SYM) THEN ASM_REWRITE_TAC[]);;

(* For a point y IN W', the applied value a*(y) exists (c contains <y,a*(y)>).
   MIXVAL_EXISTS gives the pair-value; graph char (backward) puts it in c. *)
let MIX_APPLY_EXISTS = prove
 (`!D (E:A->A->bool) B leq dd g W v c y.
      model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
      dd IN D /\ g IN D /\ W IN D /\
      valuation D v /\ v 1 = leq /\ v 2 = B /\ v 5 = dd /\ v 15 = g /\
      c IN D /\
      (!w. w IN D ==> (E w c <=>
              ?p. p IN D /\ E p W /\
                  holds D E ((20 |-> w)((16 |-> p) v)) phi_mixval)) /\
      y IN D /\ E y W
      ==> ?ay. ay IN D /\ eapply D E c y ay`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`y:A`;`v:num->A`]
    MIXVAL_EXISTS) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `w0:A` STRIP_ASSUME_TAC) THEN
  SUBGOAL_THEN `(E:A->A->bool) w0 c` ASSUME_TAC THENL
   [FIRST_X_ASSUM(MP_TAC o SPEC `w0:A`) THEN ASM_REWRITE_TAC[] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    EXISTS_TAC `y:A` THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`v:num->A`;`y:A`;`w0:A`]
         MIXVAL_DEST) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `ay:A` STRIP_ASSUME_TAC) THEN
  EXISTS_TAC `ay:A` THEN ASM_REWRITE_TAC[REWRITE_RULE[] eapply] THEN
  REWRITE_TAC[eapply] THEN EXISTS_TAC `w0:A` THEN ASM_REWRITE_TAC[]);;

(* ==================================================================== *)
(* F8-C: single-m first-value graph and its properties.                 *)
(*   g = { <q, first(m,q)> : q IN dm } via phi_g (Option B graph).       *)
(*   C4a: phi_g + PHI_G_* + G_GRAPH_EXISTS.                              *)
(*   C4b GPROPS: G_EAPPLY_DECOMP, G_EISFUN, G_APPLY_EXISTS, G_DISJOINT.  *)
(* ==================================================================== *)

(* ==================================================================== *)
(* C4a: single-m first-value graph  g = { <q, first(m,q)> : q IN dm }.  *)
(* phi_g wraps firstsel_fm (slot 6 = first(m,q)) with an output pair at *)
(* slot 20 = <q(slot0), first(m,q)(slot6)>.  Strictly simpler than      *)
(* phi_c: single input q (slot 0), no [[m in x]] factor, no pair input. *)
(* Slot map: 0=q(input), 1=leq, 2=B, 3=m, 4=ra, 5=dm, 6=first-out,      *)
(*           20=w-output pair.                                          *)
(* ==================================================================== *)

let phi_g = new_definition
 `phi_g = ?? 6 (firstsel_fm && opair_form 0 6 20)`;;

(* Body under the single binder 6. *)
let PHI_G_BODY = prove
 (`!D (E:A->A->bool) v a6.
     model D E ZF_AX /\ valuation D v /\ a6 IN D
     ==> (holds D E ((6|->a6)v) (firstsel_fm && opair_form 0 6 20)
          <=> holds D E ((6|->a6)v) firstsel_fm /\
              eopair D E (v 0) a6 (v 20))`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `valuation D ((6|->a6)(v:num->A))` ASSUME_TAC THENL
   [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
  ASM_SIMP_TAC[HOLDS_AND; HOLDS_OPAIR_FORM] THEN
  REWRITE_TAC[VALMOD; ARITH_EQ]);;

let PHI_G_HOLDS = prove
 (`!D (E:A->A->bool) v.
     model D E ZF_AX /\ valuation D v
     ==> (holds D E v phi_g <=>
          ?ifp. ifp IN D /\
                holds D E ((6|->ifp)v) firstsel_fm /\
                eopair D E (v 0) ifp (v 20))`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  REWRITE_TAC[phi_g; HOLDS_EX] THEN
  EQ_TAC THENL
   [DISCH_THEN(X_CHOOSE_THEN `a6:A`
               (CONJUNCTS_THEN2 ASSUME_TAC (LABEL_TAC "H"))) THEN
    EXISTS_TAC `a6:A` THEN
    MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`v:num->A`;`a6:A`]
           PHI_G_BODY) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> USE_THEN "H" (fun h -> ASSUME_TAC(EQ_MP th h))) THEN
    ASM_REWRITE_TAC[];
    DISCH_THEN(X_CHOOSE_THEN `ifp:A` STRIP_ASSUME_TAC) THEN
    EXISTS_TAC `ifp:A` THEN CONJ_TAC THENL
    [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`v:num->A`;`ifp:A`]
           PHI_G_BODY) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN SUBST1_TAC THEN ASM_REWRITE_TAC[]]);;

let PHI_G_DEST = prove
 (`!D (E:A->A->bool) v u w.
     model D E ZF_AX /\ valuation D v /\ u IN D /\ w IN D /\
     holds D E ((20|->w)((0|->u)v)) phi_g
     ==> ?ifp. ifp IN D /\
               holds D E ((6|->ifp)((20|->w)((0|->u)v))) firstsel_fm /\
               eopair D E u ifp w`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `valuation D ((20|->w)((0|->u)(v:num->A)))` ASSUME_TAC THENL
   [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;
                 `(20|->w)((0|->u)(v:num->A))`] PHI_G_HOLDS) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  REWRITE_TAC[VALMOD; ARITH_EQ] THEN
  DISCH_THEN(fun th -> FIRST_ASSUM(fun h -> ACCEPT_TAC(EQ_MP th h))));;

let PHI_G_EXISTS = prove
 (`!D (E:A->A->bool) B leq m dm ra q v.
     model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
     m IN D /\ bname D E B m /\ dm IN D /\
     (!q'. q' IN D /\ E q' dm ==> bname D E B q') /\ ra IN D /\
     q IN D /\ bname D E B q /\
     valuation D v /\ v 1 = leq /\ v 2 = B /\ v 3 = m /\ v 4 = ra /\ v 5 = dm
     ==> ?w. w IN D /\ holds D E ((20|->w)((0|->q)v)) phi_g`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`m:A`;`dm:A`;`ra:A`;
                 `(0|->q)(v:num->A)`] FIRSTSEL_EXISTS) THEN
  ANTS_TAC THENL
   [REWRITE_TAC[VALMOD; ARITH_EQ] THEN ASM_REWRITE_TAC[] THEN
    ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `ifp:A` STRIP_ASSUME_TAC) THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`q:A`;`ifp:A`] EOPAIR_EXISTS) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_TAC `w:A`) THEN
  SUBGOAL_THEN `(w:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[EOPAIR_IN]; ALL_TAC] THEN
  EXISTS_TAC `w:A` THEN ASM_REWRITE_TAC[] THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`(20|->w)((0|->q)(v:num->A))`]
    PHI_G_HOLDS) THEN
  ANTS_TAC THENL
  [ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
  DISCH_THEN SUBST1_TAC THEN
  REWRITE_TAC[VALMOD; ARITH_EQ] THEN
  EXISTS_TAC `ifp:A` THEN ASM_REWRITE_TAC[] THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;
    `(6|->ifp)((0|->q)(v:num->A))`;
    `(6|->ifp)((20|->w)((0|->q)(v:num->A)))`] FIRSTSEL_HOLDS_AGREE) THEN
  ANTS_TAC THENL
   [REWRITE_TAC[VALMOD; ARITH_EQ] THEN ASM_REWRITE_TAC[] THEN
    REPEAT CONJ_TAC THEN ASM_MESON_TAC[VALUATION_VALMOD];
    DISCH_THEN(fun th -> FIRST_ASSUM(fun h -> ACCEPT_TAC(EQ_MP th h)))]);;

let PHI_G_UNIQUE = prove
 (`!D (E:A->A->bool) B leq v u w w'.
     model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
     valuation D v /\ v 1 = leq /\ v 2 = B /\ u IN D /\ w IN D /\ w' IN D /\
     holds D E ((20|->w)((0|->u)v)) phi_g /\
     holds D E ((20|->w')((0|->u)v)) phi_g
     ==> w = w'`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`v:num->A`;`u:A`;`w:A`]
         PHI_G_DEST) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `ifp:A` STRIP_ASSUME_TAC) THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`v:num->A`;`u:A`;`w':A`]
         PHI_G_DEST) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `ifp':A` STRIP_ASSUME_TAC) THEN
  SUBGOAL_THEN `ifp:A = ifp'` ASSUME_TAC THENL
   [MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
      `(6|->ifp)((20|->w)((0|->u)(v:num->A)))`;
      `(6|->ifp')((20|->w')((0|->u)(v:num->A)))`] FIRSTSEL_UNIQUE_GEN) THEN
    ANTS_TAC THENL
     [REWRITE_TAC[VALMOD; ARITH_EQ] THEN ASM_REWRITE_TAC[] THEN
      CONJ_TAC THEN ASM_MESON_TAC[VALUATION_VALMOD];
      DISCH_THEN(fun th -> REWRITE_TAC[REWRITE_RULE[VALMOD; ARITH_EQ] th])];
    ALL_TAC] THEN
  ASM_MESON_TAC[EOPAIR_UNIQUE]);;

let G_GRAPH_EXISTS = prove
 (`!D (E:A->A->bool) B leq m ra dm v.
     model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
     m IN D /\ bname D E B m /\ ra IN D /\ dm IN D /\
     (!q. q IN D /\ E q dm ==> bname D E B q) /\
     valuation D v /\ v 1 = leq /\ v 2 = B /\ v 3 = m /\ v 4 = ra /\ v 5 = dm
     ==> ?g. g IN D /\
             !w. w IN D
                 ==> (E w g <=>
                      ?q. q IN D /\ E q dm /\
                          holds D E ((20|->w)((0|->q)v)) phi_g)`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`] ZF_REPLACEMENT) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(MP_TAC o SPECL [`phi_g`; `0`; `20`; `v:num->A`; `dm:A`]) THEN
  ANTS_TAC THENL
   [REWRITE_TAC[ARITH_EQ] THEN ASM_REWRITE_TAC[] THEN
    X_GEN_TAC `q:A` THEN STRIP_TAC THEN
    SUBGOAL_THEN `bname D E B (q:A)` ASSUME_TAC THENL
     [FIRST_ASSUM MATCH_MP_TAC THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    MP_TAC(ISPECL
           [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`m:A`;`dm:A`;`ra:A`;
            `q:A`;`v:num->A`] PHI_G_EXISTS) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(X_CHOOSE_THEN `w0:A` STRIP_ASSUME_TAC) THEN
    EXISTS_TAC `w0:A` THEN ASM_REWRITE_TAC[] THEN
    X_GEN_TAC `w':A` THEN STRIP_TAC THEN
    ASM_MESON_TAC[PHI_G_UNIQUE];
    ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `g:A` STRIP_ASSUME_TAC) THEN
  EXISTS_TAC `g:A` THEN ASM_REWRITE_TAC[]);;

(* ==================================================================== *)
(* C4b GPROPS: properties of the single-m first-value graph g.          *)
(*   g = { <q, first(m,q)> : q IN dm },  built by G_GRAPH_EXISTS.        *)
(* G_EAPPLY_DECOMP: destruct  eapply g q w  into the firstsel/EFIRST     *)
(*   decomposition of  w = first(m,q) = bp /\ csp  (bp=[[q in m]],       *)
(*   sp=elub{[[r in m]]:r in dm, ra r q}, csp=~sp).  Mirror of           *)
(*   MIX_APPLY_DEST.  Also yields  E q dm  (q ranges in the family).     *)
(* ==================================================================== *)

let G_EAPPLY_DECOMP = prove
 (`!D (E:A->A->bool) B leq m dm ra g v q w.
     model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
     m IN D /\ bname D E B m /\ dm IN D /\ ra IN D /\
     (!qq. qq IN D /\ E qq dm ==> bname D E B qq) /\
     valuation D v /\ v 1 = leq /\ v 2 = B /\ v 3 = m /\
       v 4 = ra /\ v 5 = dm /\
     g IN D /\
     (!ww. ww IN D
           ==> (E ww g <=>
                ?qq. qq IN D /\ E qq dm /\
                     holds D E ((20|->ww)((0|->qq)v)) phi_g)) /\
     q IN D /\ w IN D /\ eapply D E g q w
     ==> E q dm /\ E w B /\
         ?Sp sp csp bp.
           Sp IN D /\ sp IN D /\ csp IN D /\ bp IN D /\ E bp B /\
           (!z. z IN D
                ==> (E z Sp <=>
                     ?r. r IN D /\ E r dm /\ erel D E ra r q /\
                         ebv_in D E B leq r m z)) /\
           elub D E B leq Sp sp /\ ecompl D E B leq sp csp /\
           ebv_in D E B leq q m bp /\ emeet D E B leq bp csp w`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  UNDISCH_TAC `eapply D (E:A->A->bool) g q w` THEN REWRITE_TAC[eapply] THEN
  DISCH_THEN(X_CHOOSE_THEN `pr:A` STRIP_ASSUME_TAC) THEN
  SUBGOAL_THEN `(pr:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[EOPAIR_IN]; ALL_TAC] THEN
  SUBGOAL_THEN
    `?qq. qq IN D /\ E qq dm /\
          holds D E ((20|->pr)((0|->qq)(v:num->A))) phi_g`
    STRIP_ASSUME_TAC THENL
   [FIRST_X_ASSUM(MP_TAC o SPEC `pr:A` o
       check(fun th -> free_in `g:A` (concl th) && is_forall(concl th))) THEN
    ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN(fun th -> ACCEPT_TAC(EQ_MP th (ASSUME `(E:A->A->bool) pr g`)));
    ALL_TAC] THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`v:num->A`;`qq:A`;`pr:A`]
    PHI_G_DEST) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `ifp:A` STRIP_ASSUME_TAC) THEN
  SUBGOAL_THEN `qq:A = q /\ ifp:A = w` (CONJUNCTS_THEN SUBST_ALL_TAC) THENL
   [MP_TAC(ISPECL
           [`D:A->bool`;`E:A->A->bool`;`q:A`;`w:A`;`qq:A`;`ifp:A`;`pr:A`]
           EOPAIR_INJ) THEN ASM_REWRITE_TAC[] THEN MESON_TAC[];
    ALL_TAC] THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
     `(20|->pr)((0|->q)(v:num->A))`;`w:A`] FIRSTSEL_DEST) THEN
  ANTS_TAC THENL
   [REWRITE_TAC[VALMOD; ARITH_EQ] THEN ASM_REWRITE_TAC[] THEN
    ASM_MESON_TAC[VALUATION_VALMOD];
    ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `Sp:A` (X_CHOOSE_THEN `sp:A` (X_CHOOSE_THEN `csp:A`
     (X_CHOOSE_THEN `bp:A` (STRIP_ASSUME_TAC o
        REWRITE_RULE[VALMOD; ARITH_EQ;
          ASSUME `(v:num->A) 3 = m`; ASSUME `(v:num->A) 4 = ra`;
          ASSUME `(v:num->A) 5 = dm`]))))) THEN
  SUBGOAL_THEN `(w:A) IN D /\ (E:A->A->bool) w B` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[EMEET_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) bp B` ASSUME_TAC THENL
   [ASM_MESON_TAC[EBV_IN_IN_B]; ALL_TAC] THEN
  ASM_REWRITE_TAC[] THEN
  MAP_EVERY EXISTS_TAC [`Sp:A`;`sp:A`;`csp:A`;`bp:A`] THEN
  ASM_REWRITE_TAC[]);;

(* G_APPLY_EXISTS: for q in dm, the applied first-value exists in D.       *)
let G_APPLY_EXISTS = prove
 (`!D (E:A->A->bool) B leq m dm ra g v q.
     model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
     m IN D /\ bname D E B m /\ dm IN D /\ ra IN D /\
     (!qq. qq IN D /\ E qq dm ==> bname D E B qq) /\
     valuation D v /\ v 1 = leq /\ v 2 = B /\ v 3 = m /\
       v 4 = ra /\ v 5 = dm /\
     g IN D /\
     (!ww. ww IN D ==> (E ww g <=>
             ?qq. qq IN D /\ E qq dm /\
                  holds D E ((20|->ww)((0|->qq)v)) phi_g)) /\
     q IN D /\ E q dm
     ==> ?w. w IN D /\ eapply D E g q w`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `bname D E B (q:A)` ASSUME_TAC THENL
   [FIRST_ASSUM MATCH_MP_TAC THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`m:A`;`dm:A`;`ra:A`;
                 `q:A`;`v:num->A`] PHI_G_EXISTS) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `w0:A` STRIP_ASSUME_TAC) THEN
  SUBGOAL_THEN `(E:A->A->bool) w0 g` ASSUME_TAC THENL
   [FIRST_X_ASSUM(MP_TAC o SPEC `w0:A` o
       check(fun th -> free_in `g:A` (concl th) && is_forall(concl th))) THEN
    ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    EXISTS_TAC `q:A` THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`v:num->A`;`q:A`;`w0:A`]
         PHI_G_DEST) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `ifp:A` STRIP_ASSUME_TAC) THEN
  EXISTS_TAC `ifp:A` THEN ASM_REWRITE_TAC[] THEN
  REWRITE_TAC[eapply] THEN EXISTS_TAC `w0:A` THEN ASM_REWRITE_TAC[]);;

(* G_DISJOINT: the g-values are pairwise disjoint -- exactly MIX_EQ_GE's   *)
(* `disj' hypothesis for a fixed q0.  Proof: trichotomy of ra on dm        *)
(* (RA_TRICH_FROM_WF) puts the two distinct family members q0,q' in a      *)
(* strict ra-order; the one below sits in the OTHER's downset-sup, so      *)
(* FST_ANTICHAIN_BOT_ABS forces first(m,q0) /\ first(m,q') = bot.          *)
let G_DISJOINT = prove
 (`!D (E:A->A->bool) B leq m dm ra g v q0 wq0 q' w' mm.
     model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
     m IN D /\ bname D E B m /\ dm IN D /\ ra IN D /\
     (!qq. qq IN D /\ E qq dm ==> bname D E B qq) /\
     valuation D v /\ v 1 = leq /\ v 2 = B /\ v 3 = m /\
       v 4 = ra /\ v 5 = dm /\
     g IN D /\
     (!ww. ww IN D ==> (E ww g <=>
             ?qq. qq IN D /\ E qq dm /\
                  holds D E ((20|->ww)((0|->qq)v)) phi_g)) /\
     (!zz. zz IN D /\ (!t. t IN D /\ E t zz ==> E t dm) /\
      (?t. t IN D /\ E t zz)
      ==> ?p0. p0 IN D /\ E p0 zz /\
                   !q. q IN D /\ E q zz /\ ~(q = p0) ==> erel D E ra p0 q) /\
     q0 IN D /\ E q0 dm /\ wq0 IN D /\ eapply D E g q0 wq0 /\
     q' IN D /\ E q' dm /\ w' IN D /\ eapply D E g q' w' /\ ~(q' = q0) /\
     emeet D E B leq wq0 w' mm
     ==> ebot D E B leq mm`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `ebalg D (E:A->A->bool) B leq` ASSUME_TAC THENL
   [ASM_MESON_TAC[ECBA_IMP_BALG]; ALL_TAC] THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`] EBALG_BOT) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `bot:A`) THEN
  (* decomposition of wq0 = first(m,q0) *)
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`m:A`;`dm:A`;`ra:A`;
                 `g:A`;`v:num->A`;`q0:A`;`wq0:A`] G_EAPPLY_DECOMP) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(CONJUNCTS_THEN2 (K ALL_TAC) (CONJUNCTS_THEN2 ASSUME_TAC
    (X_CHOOSE_THEN `Sp1:A` (X_CHOOSE_THEN `sp1:A` (X_CHOOSE_THEN `csp1:A`
      (X_CHOOSE_THEN `bp1:A` STRIP_ASSUME_TAC)))))) THEN
  (* decomposition of w' = first(m,q') *)
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`m:A`;`dm:A`;`ra:A`;
                 `g:A`;`v:num->A`;`q':A`;`w':A`] G_EAPPLY_DECOMP) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(CONJUNCTS_THEN2 (K ALL_TAC) (CONJUNCTS_THEN2 ASSUME_TAC
    (X_CHOOSE_THEN `Sp2:A` (X_CHOOSE_THEN `sp2:A` (X_CHOOSE_THEN `csp2:A`
      (X_CHOOSE_THEN `bp2:A` STRIP_ASSUME_TAC)))))) THEN
  (* global carrier facts and the two meet-below-bp facts *)
  SUBGOAL_THEN `(E:A->A->bool) sp1 B /\ (E:A->A->bool) sp2 B`
    STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[ELUB_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq wq0 bp1` ASSUME_TAC THENL
   [ASM_MESON_TAC[EMEET_LE]; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq w' bp2` ASSUME_TAC THENL
   [ASM_MESON_TAC[EMEET_LE]; ALL_TAC] THEN
  (* trichotomy of ra on dm applied to q0,q' *)
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`ra:A`;`dm:A`]
         RA_TRICH_FROM_WF) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(MP_TAC o SPECL [`q0:A`;`q':A`]) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[];
    (* case  erel ra q0 q' : q0 in downset of q', so bp1 <= sp2 *)
    SUBGOAL_THEN `(E:A->A->bool) bp1 Sp2` ASSUME_TAC THENL
     [FIRST_ASSUM(MP_TAC o SPEC `bp1:A` o
         check(fun th -> free_in `Sp2:A` (concl th) &&
               is_forall(concl th))) THEN
      ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
      EXISTS_TAC `q0:A` THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN `erel D (E:A->A->bool) leq bp1 sp2` ASSUME_TAC THENL
     [ASM_MESON_TAC[ELUB_UB]; ALL_TAC] THEN
    MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`bp1:A`]
      EBALG_COMPL) THEN
    ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `cp1:A`) THEN
    SUBGOAL_THEN `(cp1:A) IN D` ASSUME_TAC THENL
     [ASM_MESON_TAC[ECOMPL_IN]; ALL_TAC] THEN
    SUBGOAL_THEN `emeet D (E:A->A->bool) B leq w' wq0 mm` ASSUME_TAC THENL
     [ASM_MESON_TAC[EMEET_SYM]; ALL_TAC] THEN
    MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
       `bp2:A`;`sp2:A`;`csp2:A`;`w':A`;`bp1:A`;`cp1:A`;`wq0:A`;`mm:A`;`bot:A`]
       FST_ANTICHAIN_BOT_ABS) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[];
      DISCH_THEN SUBST1_TAC THEN FIRST_ASSUM ACCEPT_TAC];
    (* case  erel ra q' q0 : q' in downset of q0, so bp2 <= sp1 *)
    SUBGOAL_THEN `(E:A->A->bool) bp2 Sp1` ASSUME_TAC THENL
     [FIRST_ASSUM(MP_TAC o SPEC `bp2:A` o
         check(fun th -> free_in `Sp1:A` (concl th) &&
               is_forall(concl th))) THEN
      ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
      EXISTS_TAC `q':A` THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN `erel D (E:A->A->bool) leq bp2 sp1` ASSUME_TAC THENL
     [ASM_MESON_TAC[ELUB_UB]; ALL_TAC] THEN
    MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`bp2:A`]
      EBALG_COMPL) THEN
    ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `cp2:A`) THEN
    SUBGOAL_THEN `(cp2:A) IN D` ASSUME_TAC THENL
     [ASM_MESON_TAC[ECOMPL_IN]; ALL_TAC] THEN
    MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
       `bp1:A`;`sp1:A`;`csp1:A`;`wq0:A`;`bp2:A`;`cp2:A`;`w':A`;`mm:A`;`bot:A`]
       FST_ANTICHAIN_BOT_ABS) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[];
      DISCH_THEN SUBST1_TAC THEN FIRST_ASSUM ACCEPT_TAC]]);;

(* ============================================================== *)
(* F8-C maximum principle -- lemma C4c + helpers + MIX_EQ_GE.    *)
(* ============================================================== *)

(* --- C4c: VALSTAGE_BOUND2 (value-stage + stabilizing ordinal). --- *)
(* C4c VALSTAGE_BOUND2: strengthen VALSTAGE_BOUND to ALSO expose the         *)
(*   stabilizing ordinal lam with lam IN D /\ eordinal D E lam /\            *)
(*   ebnstage D E B lam dd -- exactly the extra data MEMNAME and MIX_BNAME   *)
(*   require (same lam shared).  Proof is VALSTAGE_BOUND verbatim, only the  *)
(*   final assembly changes (EXISTS_TAC [dd;SS;lam] + 3 extra conjuncts).    *)
let VALSTAGE_BOUND2 = prove
 (`!n p D (E:A->A->bool) B leq v.
      model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
      valuation D v /\ (!i. bname D E B (v i))
      ==> ?dd SS lam.
            dd IN D /\ SS IN D /\ lam IN D /\
            eordinal D E lam /\ ebnstage D E B lam dd /\
            (!s. s IN D /\ E s dd ==> bname D E B s) /\
            esubset D E SS B /\
            elub D E B leq SS (bvalf D E B leq v (?? n p)) /\
            (!z. z IN D
                 ==> (E z SS <=>
                      ?s. s IN D /\ E s dd /\
                        bval D E B leq ((n |-> s) v) p z))`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `ebalg D (E:A->A->bool) B leq /\ eporder D (E:A->A->bool) B leq`
    STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[ECBA_IMP_BALG; EBALG_IMP_PORDER]; ALL_TAC] THEN
  (* reusable valmod fact *)
  SUBGOAL_THEN
   `!s:A. s IN D /\ bname D E B s
          ==> valuation D ((n |-> s) v) /\
              (!i. bname D E B (((n |-> s) v) i))`
   (LABEL_TAC "vm") THENL
   [X_GEN_TAC `s:A` THEN STRIP_TAC THEN CONJ_TAC THENL
     [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[];
      MATCH_MP_TAC BNAMEVAL_VALMOD THEN ASM_REWRITE_TAC[]]; ALL_TAC] THEN
  (* Vss = value-set { [[p(a)]] : bname a } *)
  MP_TAC(ISPECL
         [`p:form`;`n:num`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`v:num->A`]
         BVAL_VALUESET_EXISTS) THEN
  ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `Vss:A` (CONJUNCTS_THEN2 (LABEL_TAC "vssin")
    (CONJUNCTS_THEN2 (LABEL_TAC "vsssub") (LABEL_TAC "vssmem")))) THEN
  (* w0 = 32-shifted valuation with B at 2, leq at 3 *)
  ABBREV_TAC `w0 = (2 |-> B) ((3 |-> leq) (\k. (v:num->A) (k - 32)))` THEN
  SUBGOAL_THEN
   `valuation D (w0:num->A) /\ w0 2 = B /\ w0 3 = leq /\
    (!i. w0 (32 + i) = (v:num->A) i)`
   STRIP_ASSUME_TAC THENL
   [EXPAND_TAC "w0" THEN REPEAT CONJ_TAC THENL
     [REPEAT(MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[]) THEN
      REWRITE_TAC[valuation] THEN ASM_MESON_TAC[valuation];
      SIMP_TAC[VALMOD_BASIC];
      SIMP_TAC[VALMOD_OTHER; VALMOD_BASIC; ARITH_RULE `~(3 = 2)`];
      GEN_TAC THEN
      SIMP_TAC[VALMOD_OTHER; ARITH_RULE `~(32 + i = 2) /\ ~(32 + i = 3)`] THEN
      AP_TERM_TAC THEN ARITH_TAC];
    ALL_TAC] THEN
  (* fp = BVAL_DEFINABLE object formula reading value at slot 5 *)
  X_CHOOSE_THEN `fp:form` (LABEL_TAC "fpdef")
    (ISPECL [`p:form`; `5`; `3`] BVAL_DEFINABLE) THEN
  SUBGOAL_THEN
   `!vv:num->A. valuation D vv
        ==> (holds D E vv fp <=>
             bval D E (vv 2) (vv 3) (\i. vv (32 + i)) p (vv 5))`
   (LABEL_TAC "fpbr") THENL
   [X_GEN_TAC `vv:num->A` THEN DISCH_TAC THEN
    USE_THEN "fpdef" (fun th ->
      MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `vv:num->A`] th)) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[] THEN ARITH_TAC; DISCH_THEN ACCEPT_TAC];
    ALL_TAC] THEN
  (* STABILIZE_LAMBDA: uniform stabilizing stage (lam, dd) *)
  MP_TAC(ISPECL
    [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`v:num->A`;`p:form`;`fp:form`;
     `n:num`;`5`;`6`;`w0:num->A`;`Vss:A`] STABILIZE_LAMBDA) THEN
  ANTS_TAC THENL
   [REPEAT CONJ_TAC THEN TRY(FIRST_ASSUM ACCEPT_TAC) THEN TRY ARITH_TAC;
    ALL_TAC] THEN
  INTRO_TAC "@lam dd. lamord lamin ddin ddstage realize" THEN
  (* ddbn: dd's members are all B-names *)
  SUBGOAL_THEN `!s:A. s IN D /\ E s dd ==> bname D E B s`
    (LABEL_TAC "ddbn") THENL
   [X_GEN_TAC `s:A` THEN STRIP_TAC THEN MATCH_MP_TAC BNAME_STAGE THEN
    MAP_EVERY EXISTS_TAC [`lam:A`;`dd:A`] THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* SS = image value-set over dd *)
  MP_TAC(ISPECL [`p:form`;`n:num`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
    `v:num->A`;`dd:A`] BVAL_REPLIMG_EXISTS) THEN
  ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `SS:A` (CONJUNCTS_THEN2 (LABEL_TAC "ssin")
    (CONJUNCTS_THEN2 (LABEL_TAC "sssub") (LABEL_TAC "ssmem")))) THEN
  (* sv = [[?? n p]]_v : IN D and E .. B *)
  SUBGOAL_THEN
   `(bvalf D (E:A->A->bool) B leq v (?? n p)) IN D /\
    (E:A->A->bool) (bvalf D E B leq v (?? n p)) B`
   STRIP_ASSUME_TAC THENL
   [CONJ_TAC THENL
     [MP_TAC(ISPECL
             [`(?? n p):form`;`D:A->bool`;`E:A->A->bool`;`B:A`;
              `leq:A`;`v:num->A`]
             BVALF_SPEC) THEN ASM_SIMP_TAC[];
      MP_TAC(ISPECL
             [`(?? n p):form`;`D:A->bool`;`E:A->A->bool`;`B:A`;
              `leq:A`;`v:num->A`]
             BVALF_IN_B) THEN ASM_SIMP_TAC[]];
    ALL_TAC] THEN
  MAP_EVERY EXISTS_TAC [`dd:A`;`SS:A`;`lam:A`] THEN
  REPEAT CONJ_TAC THENL
   [FIRST_ASSUM ACCEPT_TAC;
    FIRST_ASSUM ACCEPT_TAC;
    FIRST_ASSUM ACCEPT_TAC;
    FIRST_ASSUM ACCEPT_TAC;
    FIRST_ASSUM ACCEPT_TAC;
    FIRST_ASSUM ACCEPT_TAC;
    FIRST_ASSUM ACCEPT_TAC;
    ALL_TAC;
    FIRST_ASSUM ACCEPT_TAC] THEN
  (* ===== elub SS sv ===== *)
  REWRITE_TAC[elub] THEN CONJ_TAC THENL
   [(* eubound SS sv *)
    REWRITE_TAC[eubound] THEN REPEAT CONJ_TAC THENL
     [FIRST_ASSUM ACCEPT_TAC;
      FIRST_ASSUM ACCEPT_TAC;
      X_GEN_TAC `z:A` THEN STRIP_TAC THEN
      USE_THEN "ssmem" (fun th ->
        X_CHOOSE_THEN `s:A` STRIP_ASSUME_TAC
          (EQ_MP (MATCH_MP th (ASSUME `(z:A) IN D`))
                 (ASSUME `(E:A->A->bool) z SS`))) THEN
      SUBGOAL_THEN `bname D (E:A->A->bool) B s` ASSUME_TAC THENL
       [ASM_MESON_TAC[]; ALL_TAC] THEN
      USE_THEN "vm" (fun th ->
        STRIP_ASSUME_TAC (MATCH_MP th
          (CONJ (ASSUME `(s:A) IN D`)
           (ASSUME `bname D (E:A->A->bool) B s`)))) THEN
      SUBGOAL_THEN `z:A = bvalf D E B leq ((n |-> s) v) p` SUBST1_TAC THENL
       [MATCH_MP_TAC(ISPECL [`p:form`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
          `(n |-> (s:A)) (v:num->A)`;`z:A`;
          `bvalf D (E:A->A->bool) B leq ((n |-> (s:A)) v) p`] BVAL_UNIQUE) THEN
        ASM_REWRITE_TAC[] THEN
        MP_TAC(ISPECL [`p:form`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
          `(n |-> (s:A)) (v:num->A)`] BVALF_SPEC) THEN ASM_SIMP_TAC[];
        ALL_TAC] THEN
      MP_TAC(ISPECL [`n:num`;`p:form`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
        `v:num->A`;`s:A`] BVALF_EX_UB) THEN ASM_REWRITE_TAC[]];
    (* least upper bound *)
    X_GEN_TAC `w:A` THEN REWRITE_TAC[eubound] THEN
    DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "wind")
      (CONJUNCTS_THEN2 (LABEL_TAC "web") (LABEL_TAC "wub"))) THEN
    MP_TAC(ISPECL [`n:num`;`p:form`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
      `v:num->A`;`w:A`] BVALF_EX_LEAST) THEN ASM_REWRITE_TAC[] THEN
    DISCH_THEN MATCH_MP_TAC THEN
    X_GEN_TAC `a:A` THEN STRIP_TAC THEN
    USE_THEN "vm" (fun th ->
      STRIP_ASSUME_TAC (MATCH_MP th
        (CONJ (ASSUME `(a:A) IN D`)
         (ASSUME `bname D (E:A->A->bool) B a`)))) THEN
    SUBGOAL_THEN
     `(bvalf D (E:A->A->bool) B leq ((n |-> a) v) p) IN D /\
      (E:A->A->bool) (bvalf D E B leq ((n |-> a) v) p) B /\
      bval D E B leq ((n |-> a) v) p (bvalf D E B leq ((n |-> a) v) p)`
     STRIP_ASSUME_TAC THENL
     [REPEAT CONJ_TAC THENL
       [MP_TAC(ISPECL [`p:form`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
          `(n |-> (a:A)) (v:num->A)`] BVALF_SPEC) THEN ASM_SIMP_TAC[];
        MP_TAC(ISPECL [`p:form`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
          `(n |-> (a:A)) (v:num->A)`] BVALF_IN_B) THEN ASM_SIMP_TAC[];
        MP_TAC(ISPECL [`p:form`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
          `(n |-> (a:A)) (v:num->A)`] BVALF_SPEC) THEN ASM_SIMP_TAC[]];
       ALL_TAC] THEN
    SUBGOAL_THEN `(E:A->A->bool) (bvalf D E B leq ((n |-> a) v) p) Vss`
      ASSUME_TAC THENL
      [USE_THEN "vssmem" (fun th ->
        MATCH_MP_TAC(snd(EQ_IMP_RULE(MATCH_MP th
          (ASSUME `(bvalf D (E:A->A->bool) B leq ((n |-> a) v) p) IN
                   D`))))) THEN
      EXISTS_TAC `a:A` THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    USE_THEN "realize" (fun th ->
      X_CHOOSE_THEN `s:A` STRIP_ASSUME_TAC
        (MATCH_MP th
          (CONJ (ASSUME `(bvalf D (E:A->A->bool) B leq ((n |-> a) v) p) IN D`)
                (ASSUME `(E:A->A->bool) (bvalf D E B leq ((n |-> a) v) p)
                         Vss`)))) THEN
    SUBGOAL_THEN `bname D (E:A->A->bool) B s` ASSUME_TAC THENL
     [ASM_MESON_TAC[]; ALL_TAC] THEN
    USE_THEN "vm" (fun th ->
      STRIP_ASSUME_TAC (MATCH_MP th
        (CONJ (ASSUME `(s:A) IN D`)
         (ASSUME `bname D (E:A->A->bool) B s`)))) THEN
    SUBGOAL_THEN
     `bvalf D (E:A->A->bool) B leq ((n |-> a) v) p =
      bvalf D E B leq ((n |-> s) v) p`
     ASSUME_TAC THENL
     [MATCH_MP_TAC(ISPECL [`p:form`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
        `(n |-> (s:A)) (v:num->A)`;
        `bvalf D (E:A->A->bool) B leq ((n |-> (a:A)) v) p`;
        `bvalf D (E:A->A->bool) B leq ((n |-> (s:A)) v) p`] BVAL_UNIQUE) THEN
      ASM_REWRITE_TAC[] THEN
      MP_TAC(ISPECL [`p:form`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
        `(n |-> (s:A)) (v:num->A)`] BVALF_SPEC) THEN ASM_SIMP_TAC[];
      ALL_TAC] THEN
    SUBGOAL_THEN `(E:A->A->bool) (bvalf D E B leq ((n |-> a) v) p) SS`
      ASSUME_TAC THENL
      [USE_THEN "ssmem" (fun th ->
        MATCH_MP_TAC(snd(EQ_IMP_RULE(MATCH_MP th
          (ASSUME `(bvalf D (E:A->A->bool) B leq ((n |-> a) v) p) IN
                   D`))))) THEN
      EXISTS_TAC `s:A` THEN ASM_REWRITE_TAC[] THEN
      MP_TAC(ISPECL [`p:form`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
        `(n |-> (s:A)) (v:num->A)`] BVALF_SPEC) THEN ASM_SIMP_TAC[];
      ALL_TAC] THEN
    USE_THEN "wub" MATCH_MP_TAC THEN CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC]);;

(* --- helper: eopair left-determinism (other pair fully in D). --- *)
(* Left-determinism of eopair when the OTHER pair is fully in D: if <u,w>   *)
(* and <u0,w0> are the SAME set z, with w,u0,w0 IN D (u possibly not), then *)
(* u = u0.  Handles the out-of-D first coordinate that eindom leaves open.  *)
let EOPAIR_FST_DET = prove
 (`!D (E:A->A->bool) u w z u0 w0.
     model D E ZF_AX /\ w IN D /\ u0 IN D /\ w0 IN D /\
     eopair D E u w z /\ eopair D E u0 w0 z
     ==> u = u0`,
  REPEAT GEN_TAC THEN REWRITE_TAC[eopair] THEN
  INTRO_TAC "modl wD u0D w0D (@s p. puus puwp pspz) @s0 p0. pu0s0 pu0p0 \
             ps0p0z" THEN
  SUBGOAL_THEN `(s:A) IN D /\ (p:A) IN D /\ (s0:A) IN D /\ (p0:A) IN D`
    STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[EPAIR_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) u0 s0` ASSUME_TAC THENL
   [UNDISCH_TAC `epair D (E:A->A->bool) u0 u0 s0` THEN REWRITE_TAC[epair] THEN
    ASM_MESON_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) u0 p0` ASSUME_TAC THENL
   [UNDISCH_TAC `epair D (E:A->A->bool) u0 w0 p0` THEN REWRITE_TAC[epair] THEN
    ASM_MESON_TAC[]; ALL_TAC] THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`s:A`;`p:A`;`s0:A`;`p0:A`;`z:A`]
    EPAIR_EQ) THEN
  ASM_REWRITE_TAC[] THEN STRIP_TAC THENL
   [SUBGOAL_THEN `(E:A->A->bool) u0 s` ASSUME_TAC THENL
     [ASM_MESON_TAC[]; ALL_TAC];
    SUBGOAL_THEN `(E:A->A->bool) u0 s` ASSUME_TAC THENL
     [ASM_MESON_TAC[]; ALL_TAC]] THEN
  UNDISCH_TAC `epair D (E:A->A->bool) u u s` THEN REWRITE_TAC[epair] THEN
  ASM_MESON_TAC[]);;

(* --- helper: stage domain-point lands in stage point-set. --- *)
(* Domain-point of a stage-member lands in the stage point-set: if dd is    *)
(* the ebnfuns over point-set w1 (dd = ebnstage lam via EBNSTAGE_CHAR's     *)
(* `funs') and q IN dd, then every u IN dom(q) satisfies E u w1 -- with NO  *)
(* u IN D hypothesis (it is forced by the cross-membership).  Discharges    *)
(* MIX_EQ_GE's `wcl' and MIX_BNAME's stage-membership when W := w1.         *)
let BNAME_INDOM_POINTSET = prove
 (`!D (E:A->A->bool) B w1 dd q u.
     model D E ZF_AX /\ ebnfuns D E B w1 dd /\
     q IN D /\ E q dd /\ eindom D E q u
     ==> E u w1`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  UNDISCH_TAC `eindom D (E:A->A->bool) q u` THEN REWRITE_TAC[eindom] THEN
  DISCH_THEN(X_CHOOSE_THEN `w:A`
             (CONJUNCTS_THEN2 (LABEL_TAC "wD") (LABEL_TAC "app"))) THEN
  UNDISCH_TAC `eapply D (E:A->A->bool) q u w` THEN REWRITE_TAC[eapply] THEN
  DISCH_THEN(X_CHOOSE_THEN `z:A`
             (CONJUNCTS_THEN2 (LABEL_TAC "opuwz") (LABEL_TAC "zq"))) THEN
  SUBGOAL_THEN `(z:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[EOPAIR_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `ebnmem D (E:A->A->bool) B w1 q` ASSUME_TAC THENL
   [UNDISCH_TAC `ebnfuns D (E:A->A->bool) B w1 dd` THEN
    REWRITE_TAC[ebnfuns] THEN
    STRIP_TAC THEN FIRST_X_ASSUM(MP_TAC o SPEC `q:A`) THEN
    ASM_REWRITE_TAC[] THEN
    DISCH_THEN(fun th -> MP_TAC(EQ_MP th (ASSUME `(E:A->A->bool) q dd`))) THEN
    DISCH_THEN ACCEPT_TAC; ALL_TAC] THEN
  UNDISCH_TAC `ebnmem D (E:A->A->bool) B w1 q` THEN REWRITE_TAC[ebnmem] THEN
  DISCH_THEN(CONJUNCTS_THEN2 (K ALL_TAC)
    (X_CHOOSE_THEN `cr:A` (CONJUNCTS_THEN2 (LABEL_TAC "crD")
      (CONJUNCTS_THEN2 (LABEL_TAC "cross") (LABEL_TAC "sub"))))) THEN
  SUBGOAL_THEN `(E:A->A->bool) z cr` ASSUME_TAC THENL
   [UNDISCH_TAC `esubset D (E:A->A->bool) q cr` THEN REWRITE_TAC[esubset] THEN
    DISCH_THEN MATCH_MP_TAC THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`w1:A`;`B:A`;`cr:A`;`z:A`]
         ECROSS_MEMBER) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(fun th -> MP_TAC(EQ_MP th (ASSUME `(E:A->A->bool) z cr`))) THEN
  DISCH_THEN(X_CHOOSE_THEN `u0:A` (X_CHOOSE_THEN `w0:A` STRIP_ASSUME_TAC)) THEN
  SUBGOAL_THEN `u:A = u0` SUBST1_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`u:A`;`w:A`;`z:A`;`u0:A`;`w0:A`]
                 EOPAIR_FST_DET) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  FIRST_ASSUM ACCEPT_TAC);;

(* --- MIX_EQ_GE: the disj hypothesis carries w IN D, so that     *)
(* G_DISJOINT can discharge it at the C4e call. ---                 *)
let MIX_EQ_GE = prove
 (`!D (E:A->A->bool) B leq dd g W v c q0 wq0 z.
     model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
     dd IN D /\ g IN D /\ W IN D /\
     valuation D v /\ v 1 = leq /\ v 2 = B /\ v 5 = dd /\ v 15 = g /\
     c IN D /\ bname D E B c /\
     (!w. w IN D ==> (E w c <=>
             ?p. p IN D /\ E p W /\
                 holds D E ((20 |-> w)((16 |-> p) v)) phi_mixval)) /\
     q0 IN D /\ E q0 dd /\ bname D E B q0 /\
     wq0 IN D /\ E wq0 B /\ eapply D E g q0 wq0 /\
     (!q' u'. q' IN D /\ E q' dd /\ eindom D E q' u' ==> E u' W) /\
     (!q' w' m. q' IN D /\ E q' dd /\ ~(q' = q0) /\ w' IN D /\
      eapply D E g q' w' /\
      emeet D E B leq wq0 w' m ==> ebot D E B leq m) /\
     z IN D /\ ebv_eq D E B leq c q0 z
     ==> erel D E leq wq0 z`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "modl ecba BD leqD ddD gD WD val v1 v2 v5 v15 cD bnc cch \
             q0D q0dd bnq0 wq0D wq0B gq0 wcl disj zD eqz" THEN
  SUBGOAL_THEN `eporder D (E:A->A->bool) B leq` (LABEL_TAC "epo") THENL
   [ASM_MESON_TAC[ECBA_IMP_BALG; EBALG_IMP_PORDER]; ALL_TAC] THEN
  SUBGOAL_THEN `ebalg D (E:A->A->bool) B leq` (LABEL_TAC "eba") THENL
   [ASM_MESON_TAC[ECBA_IMP_BALG]; ALL_TAC] THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`c:A`;`q0:A`]
         BNAME_DIRECTED) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `ao:A` (X_CHOOSE_THEN `w:A` STRIP_ASSUME_TAC)) THEN
  SUBGOAL_THEN `!zt. zt IN D /\ E zt w ==> bname D (E:A->A->bool) B zt`
    (LABEL_TAC "stbn") THENL
   [REPEAT STRIP_TAC THEN
    MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;
                         `ao:A`;`w:A`;`zt:A`] BNAME_STAGE) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`w:A`]
         EBVATT_EXISTS) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[] THEN EXISTS_TAC `c:A` THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `sIN:A`
             (X_CHOOSE_THEN `sEQ:A` (LABEL_TAC "att"))) THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`c:A`;`q0:A`] EOPAIR_EXISTS) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `prcq:A`) THEN
  MP_TAC(ISPECL
         [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`w:A`;`sIN:A`;`sEQ:A`;
          `c:A`;`q0:A`;`prcq:A`] EBVATT_VAL) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(CONJUNCTS_THEN2 (K ALL_TAC)
    (X_CHOOSE_THEN `zc:A` STRIP_ASSUME_TAC)) THEN
  SUBGOAL_THEN `ebv_eq D (E:A->A->bool) B leq c q0 zc` (LABEL_TAC "eqzc") THENL
   [MP_TAC(ISPECL
           [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`ao:A`;`w:A`;`sIN:A`;
            `sEQ:A`;`c:A`;`q0:A`;`zc:A`] EBV_EQ_AT_STAGE) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `z:A = zc` SUBST_ALL_TAC THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`c:A`;`q0:A`;
      `z:A`;`zc:A`] EBV_EQ_UNIQUE) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`ao:A`;`w:A`;`sIN:A`;
    `sEQ:A`;`c:A`;`q0:A`;`zc:A`;`wq0:A`] EBV_EQ_GLB_STAGE) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
     [ (* ================= hu : x in dom c ================= *)
      MAP_EVERY X_GEN_TAC [`x:A`;`qx:A`;`exv:A`;`cc:A`] THEN
      INTRO_TAC "xD qxD exvD ccD apcx invx impx" THEN
      (* bname x from  x in dom c *)
      SUBGOAL_THEN `bname D (E:A->A->bool) B x` (LABEL_TAC "bnx") THENL
       [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`c:A`;`x:A`]
          UNION_DOM_BNAME) THEN ASM_REWRITE_TAC[eindom] THEN
        EXISTS_TAC `qx:A` THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
      (* VS_x and elub via MIX_APPLY_DEST *)
      MP_TAC(ISPECL
             [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`dd:A`;`g:A`;`W:A`;
              `v:num->A`;`c:A`;`x:A`;`qx:A`] MIX_APPLY_DEST) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(X_CHOOSE_THEN `VS:A` (CONJUNCTS_THEN2 (LABEL_TAC "vsd")
        (CONJUNCTS_THEN2 (LABEL_TAC "vsch") (LABEL_TAC "vslub")))) THEN
      SUBGOAL_THEN `(E:A->A->bool) qx B` (LABEL_TAC "qxB") THENL
       [ASM_MESON_TAC[ELUB_IN]; ALL_TAC] THEN
      SUBGOAL_THEN `(E:A->A->bool) exv B` (LABEL_TAC "exvB") THENL
       [MATCH_MP_TAC(ISPECL
                     [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`x:A`;`q0:A`;
                      `exv:A`] EBV_IN_IN_B) THEN ASM_REWRITE_TAC[];
             ALL_TAC] THEN
      (* m = meet(wq0,qx) *)
      MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`wq0:A`;`qx:A`]
        EBALG_MEET) THEN ASM_REWRITE_TAC[] THEN
      DISCH_THEN(X_CHOOSE_TAC `m:A`) THEN
      SUBGOAL_THEN `(m:A) IN D /\ (E:A->A->bool) m B` STRIP_ASSUME_TAC THENL
       [ASM_MESON_TAC[EMEET_IN]; ALL_TAC] THEN
      (* crux: erel leq m exv *)
      SUBGOAL_THEN `erel D (E:A->A->bool) leq m exv` (LABEL_TAC "mexv") THENL
       [MATCH_MP_TAC(ISPECL
                     [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`VS:A`;`qx:A`;
                      `wq0:A`;`exv:A`;`m:A`] MIX_MEET_ELUB_LE) THEN
        ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
         [ (* clause A: VS terms are in B *)
          X_GEN_TAC `t:A` THEN STRIP_TAC THEN
          USE_THEN "vsch" (MP_TAC o SPEC `t:A`) THEN
          ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
          DISCH_THEN(fun th ->
                     MP_TAC(EQ_MP th (ASSUME `(E:A->A->bool) t VS`))) THEN
          DISCH_THEN(X_CHOOSE_THEN `a9:A` (X_CHOOSE_THEN `a10:A`
            (X_CHOOSE_THEN `a11:A` (X_CHOOSE_THEN `a12:A`
             (X_CHOOSE_THEN `a13:A` STRIP_ASSUME_TAC))))) THEN
          ASM_MESON_TAC[EMEET_IN];
          (* clause B: per-term  meet(wq0,t) <= exv *)
          MAP_EVERY X_GEN_TAC [`t:A`;`mt:A`] THEN STRIP_TAC THEN
          USE_THEN "vsch" (MP_TAC o SPEC `t:A`) THEN
          ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
          DISCH_THEN(fun th ->
                     MP_TAC(EQ_MP th (ASSUME `(E:A->A->bool) t VS`))) THEN
          DISCH_THEN(X_CHOOSE_THEN `a9:A` (X_CHOOSE_THEN `a10:A`
            (X_CHOOSE_THEN `a11:A` (X_CHOOSE_THEN `a12:A`
             (X_CHOOSE_THEN `a13:A` STRIP_ASSUME_TAC))))) THEN
          (* common facts *)
          SUBGOAL_THEN `(E:A->A->bool) t B` (LABEL_TAC "tB") THENL
           [ASM_MESON_TAC[EMEET_IN]; ALL_TAC] THEN
          SUBGOAL_THEN `erel D (E:A->A->bool) leq mt t /\ erel D E leq mt wq0`
            STRIP_ASSUME_TAC THENL [ASM_MESON_TAC[EMEET_LE]; ALL_TAC] THEN
          SUBGOAL_THEN `erel D (E:A->A->bool) leq t a10 /\ erel D E leq t a12`
            STRIP_ASSUME_TAC THENL [ASM_MESON_TAC[EMEET_LE]; ALL_TAC] THEN
          SUBGOAL_THEN `(E:A->A->bool) a12 B /\ (E:A->A->bool) a10 B`
            STRIP_ASSUME_TAC THENL
           [ASM_MESON_TAC[EPORDER_FIELD]; ALL_TAC] THEN
          SUBGOAL_THEN `(mt:A) IN D /\ (E:A->A->bool) mt B`
            STRIP_ASSUME_TAC THENL
            [ASM_MESON_TAC[EMEET_IN]; ALL_TAC] THEN
          ASM_CASES_TAC `a9:A = q0` THENL
           [ (* a9 = q0 : t <= a12 = q0(x) <= [[x in q0]] = exv *)
            SUBGOAL_THEN `eapply D (E:A->A->bool) q0 x a12`
              (LABEL_TAC "apq0x") THENL
              [REWRITE_TAC[eapply] THEN EXISTS_TAC `a13:A` THEN
              ASM_MESON_TAC[]; ALL_TAC] THEN
            SUBGOAL_THEN `erel D (E:A->A->bool) leq a12 exv`
              (LABEL_TAC "a12exv") THENL
              [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
                `q0:A`;`x:A`;`a12:A`;`exv:A`] EBV_MEMBER_LE_V) THEN
              ASM_REWRITE_TAC[];
              ALL_TAC] THEN
            SUBGOAL_THEN `erel D (E:A->A->bool) leq mt a12` ASSUME_TAC THENL
             [MATCH_MP_TAC(ISPECL
                           [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`mt:A`;
                            `t:A`;`a12:A`] EPORDER_TRANS) THEN
              ASM_REWRITE_TAC[]; ALL_TAC] THEN
            MATCH_MP_TAC(ISPECL
                         [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`mt:A`;
                          `a12:A`;`exv:A`] EPORDER_TRANS) THEN
            ASM_REWRITE_TAC[];
            (* a9 <> q0 : meet(wq0,a10) is bottom, so mt <= it <= exv *)
            SUBGOAL_THEN `eapply D (E:A->A->bool) g a9 a10`
              (LABEL_TAC "apga9") THENL
              [REWRITE_TAC[eapply] THEN EXISTS_TAC `a11:A` THEN
              ASM_MESON_TAC[]; ALL_TAC] THEN
            MP_TAC(ISPECL
                   [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`wq0:A`;`a10:A`]
                   EBALG_MEET) THEN ASM_REWRITE_TAC[] THEN
            DISCH_THEN(X_CHOOSE_TAC `mp:A`) THEN
            SUBGOAL_THEN `(mp:A) IN D /\ (E:A->A->bool) mp B`
              STRIP_ASSUME_TAC THENL
              [ASM_MESON_TAC[EMEET_IN]; ALL_TAC] THEN
            SUBGOAL_THEN `ebot D (E:A->A->bool) B leq mp`
              (LABEL_TAC "botmp") THENL
              [USE_THEN "disj"
               (fun d -> MP_TAC(SPECL [`a9:A`;`a10:A`;`mp:A`] d)) THEN
               ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC];
              ALL_TAC] THEN
            SUBGOAL_THEN `erel D (E:A->A->bool) leq mt a10` ASSUME_TAC THENL
             [MATCH_MP_TAC(ISPECL
                           [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`mt:A`;
                            `t:A`;`a10:A`] EPORDER_TRANS) THEN
              ASM_REWRITE_TAC[]; ALL_TAC] THEN
            SUBGOAL_THEN `erel D (E:A->A->bool) leq mt mp` ASSUME_TAC THENL
             [MATCH_MP_TAC(ISPECL
                           [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`wq0:A`;
                            `a10:A`;`mp:A`;`mt:A`] EMEET_GREATEST) THEN
              ASM_REWRITE_TAC[];
              ALL_TAC] THEN
            SUBGOAL_THEN `erel D (E:A->A->bool) leq mp exv` ASSUME_TAC THENL
             [MATCH_MP_TAC(ISPECL
                           [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`mp:A`;
                            `exv:A`] EBOT_LE) THEN ASM_REWRITE_TAC[];
              ALL_TAC] THEN
            MATCH_MP_TAC(ISPECL
                         [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`mt:A`;
                          `mp:A`;`exv:A`] EPORDER_TRANS) THEN
            ASM_REWRITE_TAC[]]];
        ALL_TAC] THEN
      (* finish hu: wq0 <= (qx ==> exv) = cc  via residuation *)
      MATCH_MP_TAC(ISPECL
                   [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`wq0:A`;`qx:A`;
                    `exv:A`;`cc:A`;`m:A`] EBIMP_LE_IMP) THEN ASM_REWRITE_TAC[];
      (* ================= hv : y in dom q0 ================= *)
      MAP_EVERY X_GEN_TAC [`y:A`;`qy:A`;`eyu:A`;`cc:A`] THEN
      INTRO_TAC "yD qyD eyuD ccD apqy inyc impy" THEN
      (* y in dom q0, hence y in W' *)
      SUBGOAL_THEN `eindom D (E:A->A->bool) q0 y` (LABEL_TAC "indq0y") THENL
       [REWRITE_TAC[eindom] THEN EXISTS_TAC `qy:A` THEN ASM_REWRITE_TAC[];
        ALL_TAC] THEN
      SUBGOAL_THEN `(E:A->A->bool) y W` (LABEL_TAC "yW") THENL
       [USE_THEN "wcl" MATCH_MP_TAC THEN EXISTS_TAC `q0:A` THEN
        ASM_REWRITE_TAC[]; ALL_TAC] THEN
      (* ay = a*(y) = c(y), and its section-set VS_y *)
      MP_TAC(ISPECL
             [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`dd:A`;`g:A`;`W:A`;
              `v:num->A`;`c:A`;`y:A`] MIX_APPLY_EXISTS) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(X_CHOOSE_THEN `ay:A` (CONJUNCTS_THEN2 (LABEL_TAC "ayD")
        (LABEL_TAC "apcy"))) THEN
      MP_TAC(ISPECL
             [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`dd:A`;`g:A`;`W:A`;
              `v:num->A`;`c:A`;`y:A`;`ay:A`] MIX_APPLY_DEST) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(X_CHOOSE_THEN `VS:A` (CONJUNCTS_THEN2 (LABEL_TAC "vsd")
        (CONJUNCTS_THEN2 (LABEL_TAC "vsch") (LABEL_TAC "vslub")))) THEN
      (* the three value memberships in B *)
      SUBGOAL_THEN `(E:A->A->bool) ay B` (LABEL_TAC "ayB") THENL
       [ASM_MESON_TAC[ELUB_IN]; ALL_TAC] THEN
      SUBGOAL_THEN `(E:A->A->bool) qy B` (LABEL_TAC "qyB") THENL
       [MATCH_MP_TAC(ISPECL
                     [`D:A->bool`;`E:A->A->bool`;`B:A`;`q0:A`;`y:A`;`qy:A`]
                     BNAME_APPLY_IN_B) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
      SUBGOAL_THEN `(E:A->A->bool) eyu B` (LABEL_TAC "eyuB") THENL
       [MATCH_MP_TAC(ISPECL
                     [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`y:A`;`c:A`;
                      `eyu:A`] EBV_IN_IN_B) THEN ASM_REWRITE_TAC[];
             ALL_TAC] THEN
      (* m0 = meet(wq0, qy) *)
      MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`wq0:A`;`qy:A`]
        EBALG_MEET) THEN ASM_REWRITE_TAC[] THEN
      DISCH_THEN(X_CHOOSE_TAC `m0:A`) THEN
      SUBGOAL_THEN `(m0:A) IN D /\ (E:A->A->bool) m0 B` STRIP_ASSUME_TAC THENL
       [ASM_MESON_TAC[EMEET_IN]; ALL_TAC] THEN
      (* pair witnesses for g(q0)=wq0 and q0(y)=qy *)
      USE_THEN "gq0" (X_CHOOSE_THEN `pg:A` STRIP_ASSUME_TAC o
        REWRITE_RULE[eapply]) THEN
      USE_THEN "apqy" (X_CHOOSE_THEN `py:A` STRIP_ASSUME_TAC o
        REWRITE_RULE[eapply]) THEN
      SUBGOAL_THEN `(pg:A) IN D /\ (py:A) IN D` STRIP_ASSUME_TAC THENL
       [ASM_MESON_TAC[EOPAIR_IN]; ALL_TAC] THEN
      (* m0 IN VS_y : witnesses q0, wq0(=g q0), qy(=q0 y) *)
      SUBGOAL_THEN `(E:A->A->bool) m0 VS` (LABEL_TAC "m0VS") THENL
       [USE_THEN "vsch" (MP_TAC o SPEC `m0:A`) THEN
        ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
        DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
        MAP_EVERY EXISTS_TAC [`q0:A`;`wq0:A`;`pg:A`;`qy:A`;`py:A`] THEN
        ASM_REWRITE_TAC[]; ALL_TAC] THEN
      (* m0 <= ay = elub VS_y *)
      SUBGOAL_THEN `erel D (E:A->A->bool) leq m0 ay` (LABEL_TAC "m0ay") THENL
       [MATCH_MP_TAC(ISPECL
                     [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`VS:A`;`ay:A`;
                      `m0:A`] ELUB_UB) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
      (* bname y (y in dom c), then ay = c(y) <= [[y in c]] = eyu *)
      SUBGOAL_THEN `bname D (E:A->A->bool) B y` (LABEL_TAC "bny") THENL
       [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`c:A`;`y:A`]
          UNION_DOM_BNAME) THEN ASM_REWRITE_TAC[eindom] THEN
        EXISTS_TAC `ay:A` THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
      SUBGOAL_THEN `erel D (E:A->A->bool) leq ay eyu` (LABEL_TAC "ayeyu") THENL
       [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
          `c:A`;`y:A`;`ay:A`;`eyu:A`] EBV_MEMBER_LE_V) THEN
        ASM_REWRITE_TAC[]; ALL_TAC] THEN
      SUBGOAL_THEN `erel D (E:A->A->bool) leq m0 eyu` (LABEL_TAC "m0eyu") THENL
       [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`m0:A`;
          `ay:A`;`eyu:A`] EPORDER_TRANS) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
      (* finish hv via residuation: wq0 <= (qy ==> eyu) = cc *)
      MATCH_MP_TAC(ISPECL
                   [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`wq0:A`;`qy:A`;
                    `eyu:A`;`cc:A`;`m0:A`] EBIMP_LE_IMP) THEN
      ASM_REWRITE_TAC[]];
    DISCH_THEN ACCEPT_TAC]);;

(* ================================================================= *)
(* F8-C: MAXPRIN_EX -- Boolean maximum principle for ??.              *)
(* Self-contained reconstruction of the interactive proof.           *)
(* ================================================================= *)
let MAXPRIN_EX = prove
 (`!n p D (E:A->A->bool) B leq v.
     model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
     valuation D v /\ (!i. bname D E B (v i)) /\
     (!u. u IN D ==> elmem D E u)
     ==> ?a. a IN D /\ bname D E B a /\
             bvalf D E B leq ((n |-> a) v) p = bvalf D E B leq v (?? n p)`,
  (* ---------- phase A : goal setup + harness dd/SS/lam/w1/m/ra ------- *)
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `ebalg D (E:A->A->bool) B leq /\ eporder D (E:A->A->bool) B leq`
    STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[ECBA_IMP_BALG; EBALG_IMP_PORDER]; ALL_TAC] THEN
  MP_TAC(ISPECL
         [`n:num`;`p:form`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`v:num->A`]
         VALSTAGE_BOUND2) THEN ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `dd:A` (X_CHOOSE_THEN `SS:A` (X_CHOOSE_THEN `lam:A`
    STRIP_ASSUME_TAC))) THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`lam:A`;`dd:A`]
         EBNSTAGE_CHAR) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `w1:A` (CONJUNCTS_THEN2 (LABEL_TAC "w1D")
    (CONJUNCTS_THEN2 (LABEL_TAC "w1ch") (LABEL_TAC "funs")))) THEN
  MP_TAC(ISPECL
         [`n:num`;`p:form`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`v:num->A`;
          `dd:A`;`lam:A`] MEMNAME) THEN ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `m:A` (CONJUNCTS_THEN2 (LABEL_TAC "mD")
    (CONJUNCTS_THEN2 (LABEL_TAC "bnm") (LABEL_TAC "memch")))) THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`dd:A`] RA_FOR_DOM) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `ra:A` (CONJUNCTS_THEN2 (LABEL_TAC "raD")
    (CONJUNCTS_THEN2 (LABEL_TAC "raasym") (LABEL_TAC "raleast")))) THEN
  (* ---------- vc : machinery valuation --------------------------------- *)
  ABBREV_TAC
    `vc = (1 |-> leq)
     ((2 |-> B)((3 |-> m)((4 |-> ra)((5 |-> dd) (v:num->A)))))` THEN
  SUBGOAL_THEN
   `valuation D (vc:num->A) /\ vc 1 = leq /\ vc 2 = B /\ vc 3 = m /\
    vc 4 = ra /\ vc 5 = dd`
   STRIP_ASSUME_TAC THENL
   [EXPAND_TAC "vc" THEN REPEAT CONJ_TAC THENL
     [REPEAT(MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[]);
      REWRITE_TAC[VALMOD_BASIC];
      SIMP_TAC[VALMOD_OTHER; VALMOD_BASIC; ARITH_EQ];
      SIMP_TAC[VALMOD_OTHER; VALMOD_BASIC; ARITH_EQ];
      SIMP_TAC[VALMOD_OTHER; VALMOD_BASIC; ARITH_EQ];
      SIMP_TAC[VALMOD_OTHER; VALMOD_BASIC; ARITH_EQ]];
    ALL_TAC] THEN
  (* ---------- phase B : g graph + vm + c mixture name ------------------ *)
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`m:A`;`ra:A`;`dd:A`;
    `vc:num->A`] G_GRAPH_EXISTS) THEN
  ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `g:A`
             (CONJUNCTS_THEN2 (LABEL_TAC "gD") (LABEL_TAC "gch"))) THEN
  ABBREV_TAC `vm = (15 |-> g) (vc:num->A)` THEN
  SUBGOAL_THEN
   `valuation D (vm:num->A) /\ vm 1 = leq /\ vm 2 = B /\
    vm 5 = dd /\ vm 15 = g`
   STRIP_ASSUME_TAC THENL
   [EXPAND_TAC "vm" THEN REPEAT CONJ_TAC THENL
     [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[];
      ASM_SIMP_TAC[VALMOD_OTHER; ARITH_EQ];
      ASM_SIMP_TAC[VALMOD_OTHER; ARITH_EQ];
      ASM_SIMP_TAC[VALMOD_OTHER; ARITH_EQ];
      REWRITE_TAC[VALMOD_BASIC]];
    ALL_TAC] THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`w1:A`;`vm:num->A`]
    MIX_NAME_EXISTS) THEN
  ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `c:A`
             (CONJUNCTS_THEN2 (LABEL_TAC "cD") (LABEL_TAC "cch"))) THEN
  MP_TAC(ISPECL
         [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`w1:A`;`vm:num->A`;`c:A`]
         MIX_EISFUN) THEN
  ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  DISCH_THEN(LABEL_TAC "isfc") THEN
  MP_TAC(ISPECL
         [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`lam:A`;`dd:A`;`w1:A`;
          `vm:num->A`;`c:A`] MIX_BNAME) THEN
  ANTS_TAC THENL
   [REPEAT CONJ_TAC THEN TRY(FIRST_ASSUM ACCEPT_TAC) THEN
    X_GEN_TAC `s:A` THEN STRIP_TAC THEN
    USE_THEN "w1ch" (MP_TAC o SPEC `s:A`) THEN
    ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN(fun th -> MP_TAC(EQ_MP th (ASSUME `(E:A->A->bool) s w1`))) THEN
    DISCH_THEN ACCEPT_TAC;
    ALL_TAC] THEN
  DISCH_THEN(LABEL_TAC "bnc") THEN
  (* ---------- qob : the per-witness bounding obligation ---------------- *)
  SUBGOAL_THEN
   `!q bpq ddq Spq spq cspq fpq.
       q IN D /\ E q dd /\
       ebv_in D (E:A->A->bool) B leq q m bpq /\ bpq IN D /\
       ddq IN D /\
       (!r. r IN D ==> (E r ddq <=> E r dd /\ erel D E ra r q)) /\
       Spq IN D /\
       (!zz. zz IN D
             ==> (E zz Spq <=> ?r. r IN D /\ E r ddq /\
                  ebv_in D E B leq r m zz)) /\
       elub D E B leq Spq spq /\ ecompl D E B leq spq cspq /\
       emeet D E B leq bpq cspq fpq
       ==> erel D E leq fpq (bvalf D E B leq ((n |-> c) v) p)`
   (LABEL_TAC "qob") THENL
   [MAP_EVERY X_GEN_TAC
    [`q:A`;`bpq:A`;`ddq:A`;`Spq:A`;`spq:A`;`cspq:A`;`fpq:A`] THEN
    STRIP_TAC THEN
    SUBGOAL_THEN `bname D (E:A->A->bool) B q` (LABEL_TAC "bnq") THENL
     [ASM_MESON_TAC[]; ALL_TAC] THEN
    (* qob2 : g q w decomposition *)
    MP_TAC(ISPECL
           [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`m:A`;`dd:A`;`ra:A`;`g:A`;
            `vc:num->A`;`q:A`] G_APPLY_EXISTS) THEN
    ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN(X_CHOOSE_THEN `w:A`
               (CONJUNCTS_THEN2 (LABEL_TAC "wD") (LABEL_TAC "apgqw"))) THEN
    MP_TAC(ISPECL
           [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`m:A`;`dd:A`;`ra:A`;`g:A`;
            `vc:num->A`;`q:A`;`w:A`] G_EAPPLY_DECOMP) THEN
    ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN(CONJUNCTS_THEN2 (K ALL_TAC) (CONJUNCTS_THEN2 (LABEL_TAC "wB")
      (X_CHOOSE_THEN `Sp:A` (X_CHOOSE_THEN `sp:A` (X_CHOOSE_THEN `csp:A`
       (X_CHOOSE_THEN `bp:A` STRIP_ASSUME_TAC)))))) THEN
    (* qob4 : bpq = bp *)
    SUBGOAL_THEN `bpq:A = bp` SUBST_ALL_TAC THENL
     [MATCH_MP_TAC(ISPECL
                   [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`q:A`;`m:A`;
                    `bpq:A`;`bp:A`]
                   EBV_IN_UNIQUE) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    (* qob5 : Spq = Sp *)
    SUBGOAL_THEN `Spq:A = Sp` SUBST_ALL_TAC THENL
     [FIRST_ASSUM(MATCH_MP_TAC o MATCH_MP ZF_EXTENSIONALITY) THEN
      REPEAT CONJ_TAC THENL
       [FIRST_ASSUM ACCEPT_TAC; FIRST_ASSUM ACCEPT_TAC;
        X_GEN_TAC `zz:A` THEN DISCH_TAC THEN
        SUBGOAL_THEN
          `E zz Spq <=>
           (?r. r IN D /\ E r ddq /\ ebv_in D (E:A->A->bool) B leq r m zz)`
          SUBST1_TAC THENL [ASM_SIMP_TAC[]; ALL_TAC] THEN
        SUBGOAL_THEN
          `E zz Sp <=>
           (?r. r IN D /\ E r dd /\ erel D (E:A->A->bool) ra r q /\
            ebv_in D E B leq r m zz)`
          SUBST1_TAC THENL [ASM_SIMP_TAC[]; ALL_TAC] THEN
        MATCH_MP_TAC(MESON[]
          `(!r:A. (r IN D /\ E r ddq /\ ebv_in D E B leq r m zz) <=>
                  (r IN D /\ E r dd /\ erel D E ra r q /\
                   ebv_in D E B leq r m zz))
           ==> ((?r. r IN D /\ E r ddq /\ ebv_in D E B leq r m zz) <=>
                (?r. r IN D /\ E r dd /\ erel D E ra r q /\
                 ebv_in D E B leq r m zz))`) THEN
        X_GEN_TAC `r:A` THEN ASM_CASES_TAC `(r:A) IN D` THEN
        ASM_SIMP_TAC[] THEN
        ASM_MESON_TAC[]];
      ALL_TAC] THEN
    (* qob6 : spq = sp, cspq = csp, fpq = w *)
    SUBGOAL_THEN `spq:A = sp` SUBST_ALL_TAC THENL
     [MATCH_MP_TAC(ISPECL
                   [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`Sp:A`;
                    `spq:A`;`sp:A`]
                   ELUB_UNIQUE) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN `(E:A->A->bool) sp B` ASSUME_TAC THENL
     [ASM_MESON_TAC[ELUB_IN]; ALL_TAC] THEN
    SUBGOAL_THEN `cspq:A = csp` SUBST_ALL_TAC THENL
     [MATCH_MP_TAC(ISPECL
                   [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`sp:A`;
                    `cspq:A`;`csp:A`]
                   ECOMPL_UNIQUE) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN `fpq:A = w` SUBST_ALL_TAC THENL
     [MATCH_MP_TAC(ISPECL
                   [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`bp:A`;`csp:A`;
                    `fpq:A`;`w:A`]
                   EMEET_UNIQUE) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    (* qob7 : w <= bp,  bp = [[p(q)]],  zcq = [[c=q]] value *)
    SUBGOAL_THEN `erel D (E:A->A->bool) leq w bp` (LABEL_TAC "wbp") THENL
     [ASM_MESON_TAC[EMEET_LE]; ALL_TAC] THEN
    SUBGOAL_THEN `bp:A = bvalf D E B leq ((n |-> q) v) p` SUBST_ALL_TAC THENL
     [USE_THEN "memch" MATCH_MP_TAC THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`c:A`;`q:A`]
           EBV_EQ_VAL_EXISTS) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(X_CHOOSE_THEN `zcq:A` (CONJUNCTS_THEN2 (LABEL_TAC "zcqD")
      (CONJUNCTS_THEN2 (LABEL_TAC "zcqB") (LABEL_TAC "eqcq")))) THEN
    (* qob8 : wcl + disj + MIX_EQ_GE + Leibniz *)
    SUBGOAL_THEN
     `!q' u'. q' IN D /\ E q' dd /\ eindom D (E:A->A->bool) q' u' ==> E u' w1`
     (LABEL_TAC "wcl") THENL
     [MAP_EVERY X_GEN_TAC [`q':A`;`u':A`] THEN STRIP_TAC THEN
      MATCH_MP_TAC(ISPECL
                   [`D:A->bool`;`E:A->A->bool`;`B:A`;`w1:A`;`dd:A`;
                    `q':A`;`u':A`]
                   BNAME_INDOM_POINTSET) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN
     `!q' w' mm. q' IN D /\ E q' dd /\ ~(q' = q) /\ w' IN D /\
                 eapply D (E:A->A->bool) g q' w' /\ emeet D E B leq w w' mm
                 ==> ebot D E B leq mm`
     (LABEL_TAC "disj") THENL
     [MAP_EVERY X_GEN_TAC [`q':A`;`w':A`;`mm:A`] THEN STRIP_TAC THEN
      MATCH_MP_TAC(ISPECL
                   [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`m:A`;
                    `dd:A`;`ra:A`;
                    `g:A`;`vc:num->A`;`q:A`;`w:A`;`q':A`;`w':A`;`mm:A`]
                     G_DISJOINT) THEN
      REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    MP_TAC(ISPECL
           [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`dd:A`;`g:A`;`w1:A`;
            `vm:num->A`;`c:A`;`q:A`;`w:A`;`zcq:A`] MIX_EQ_GE) THEN
    ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN(LABEL_TAC "wcq") THEN
    MP_TAC(ISPECL
           [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`c:A`;`q:A`;`zcq:A`]
           EBV_EQ_SYM) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN DISCH_TAC THEN
    MATCH_MP_TAC(ISPECL
                 [`n:num`;`p:form`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
                  `v:num->A`;`q:A`;`c:A`;`w:A`;`zcq:A`]
                   MAXPRIN_LEIBNIZ_STEP) THEN
    REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
    ALL_TAC] THEN
  (* ---------- final assembly : witness c + antisymmetry --------------- *)
  EXISTS_TAC `c:A` THEN CONJ_TAC THENL
   [FIRST_ASSUM ACCEPT_TAC;
    CONJ_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC]] THEN
  SUBGOAL_THEN
   `valuation D ((n |-> c) v) /\
    (!i. bname D (E:A->A->bool) B (((n |-> c) v) i))`
   STRIP_ASSUME_TAC THENL
   [CONJ_TAC THENL
     [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[];
      MATCH_MP_TAC BNAMEVAL_VALMOD THEN ASM_REWRITE_TAC[]]; ALL_TAC] THEN
  SUBGOAL_THEN
   `(bvalf D E B leq ((n |-> c) v) p) IN D /\
    (E:A->A->bool) (bvalf D E B leq ((n |-> c) v) p) B`
   STRIP_ASSUME_TAC THENL
   [CONJ_TAC THENL
     [MP_TAC(ISPECL [`p:form`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
        `(n |-> (c:A)) (v:num->A)`] BVALF_SPEC) THEN ASM_SIMP_TAC[];
      MP_TAC(ISPECL [`p:form`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
        `(n |-> (c:A)) (v:num->A)`] BVALF_IN_B) THEN ASM_SIMP_TAC[]];
     ALL_TAC] THEN
  (* fstsup : bvalf((n|->c)v) p is an upper bound of the SS terms *)
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`m:A`;`dd:A`;`ra:A`;
     `bvalf D (E:A->A->bool) B leq ((n |-> (c:A)) v) p`] FST_SUP_GE) THEN
  ANTS_TAC THENL
   [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  DISCH_THEN(LABEL_TAC "fstsup") THEN
  (* Block A : RHS value  bvalf v (?? n p)  facts *)
  SUBGOAL_THEN
   `(bvalf D (E:A->A->bool) B leq v (?? n p)) IN D /\
    (E:A->A->bool) (bvalf D E B leq v (?? n p)) B`
   STRIP_ASSUME_TAC THENL
   [CONJ_TAC THENL
     [MP_TAC(ISPECL [`(?? n p):form`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
        `v:num->A`] BVALF_SPEC) THEN ASM_SIMP_TAC[];
      MP_TAC(ISPECL [`(?? n p):form`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
        `v:num->A`] BVALF_IN_B) THEN ASM_SIMP_TAC[]]; ALL_TAC] THEN
  (* Block B : ssub = { E z SS } is bounded by bvalf((n|->c)v) p *)
  SUBGOAL_THEN
   `!z. z IN D /\ E z SS
        ==> erel D (E:A->A->bool) leq z (bvalf D E B leq ((n |-> c) v) p)`
   (LABEL_TAC "ssub") THENL
   [X_GEN_TAC `z:A` THEN STRIP_TAC THEN
    X_CHOOSE_THEN `s:A` STRIP_ASSUME_TAC
      (EQ_MP (MATCH_MP (SPEC `z:A` (ASSUME
          `!z:A. z IN D
                 ==> (E z SS <=>
                      ?s. s IN D /\ E s dd /\
                          bval D (E:A->A->bool) B leq ((n |-> s) v) p z)`))
          (ASSUME `(z:A) IN D`))
         (ASSUME `(E:A->A->bool) z SS`)) THEN
    SUBGOAL_THEN `bname D (E:A->A->bool) B s` ASSUME_TAC THENL
     [ASM_MESON_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN
      `valuation D ((n |-> s) v) /\
       (!i. bname D (E:A->A->bool) B (((n |-> s) v) i))`
      STRIP_ASSUME_TAC THENL
     [CONJ_TAC THENL
       [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[];
        MATCH_MP_TAC BNAMEVAL_VALMOD THEN ASM_REWRITE_TAC[]]; ALL_TAC] THEN
    SUBGOAL_THEN `z:A = bvalf D E B leq ((n |-> s) v) p` SUBST_ALL_TAC THENL
     [MATCH_MP_TAC(ISPECL [`p:form`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
        `(n |-> (s:A)) (v:num->A)`;`z:A`;
        `bvalf D (E:A->A->bool) B leq ((n |-> (s:A)) v) p`] BVAL_UNIQUE) THEN
      ASM_REWRITE_TAC[] THEN
      MP_TAC(ISPECL [`p:form`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
        `(n |-> (s:A)) (v:num->A)`] BVALF_SPEC) THEN ASM_SIMP_TAC[];
      ALL_TAC] THEN
    MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`s:A`;`m:A`]
      EBV_IN_VAL_EXISTS) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(X_CHOOSE_THEN `bp:A` STRIP_ASSUME_TAC) THEN
    SUBGOAL_THEN `bp:A = bvalf D E B leq ((n |-> s) v) p` SUBST_ALL_TAC THENL
     [USE_THEN "memch" MATCH_MP_TAC THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    USE_THEN "fstsup" (fun th ->
      MATCH_MP_TAC(SPECL
                   [`s:A`; `bvalf D (E:A->A->bool) B leq ((n |-> (s:A)) v)
                            p`] th)) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* Block C : antisymmetry  LHS <= RHS (BVALF_EX_UB) and RHS <= LHS (elub) *)
  SUBGOAL_THEN `erel D (E:A->A->bool) leq
      (bvalf D E B leq ((n |-> c) v) p) (bvalf D E B leq v (?? n p))`
    ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`n:num`;`p:form`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
                  `v:num->A`;`c:A`] BVALF_EX_UB) THEN ASM_REWRITE_TAC[];
      ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq
      (bvalf D E B leq v (?? n p)) (bvalf D E B leq ((n |-> c) v) p)`
    ASSUME_TAC THENL
   [MP_TAC(ASSUME
           `elub D (E:A->A->bool) B leq SS (bvalf D E B leq v (?? n p))`) THEN
    REWRITE_TAC[elub] THEN
    DISCH_THEN(MATCH_MP_TAC o CONJUNCT2) THEN
    REWRITE_TAC[eubound] THEN REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
    ALL_TAC] THEN
  MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
    `bvalf D (E:A->A->bool) B leq ((n |-> c) v) p`;
    `bvalf D (E:A->A->bool) B leq v (?? n p)`] EPORDER_ANTISYM) THEN
  ASM_REWRITE_TAC[]);;

(* ================================================================= *)
(* F8-C: BVALF_ALL_CONG -- pointwise-equal bodies                     *)
(* give equal [[!! n .]] (glb of the same bname-indexed family).      *)
(* ================================================================= *)
let BVALF_ALL_CONG = prove
 (`!n p q D (E:A->A->bool) B leq v.
      model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
      valuation D v /\ (!i. bname D E B (v i)) /\
      (!c. c IN D /\ bname D E B c
           ==> bvalf D E B leq ((n |-> c) v) p = bvalf D E B leq
             ((n |-> c) v) q)
      ==> bvalf D E B leq v (!! n p) = bvalf D E B leq v (!! n q)`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `eporder D (E:A->A->bool) B leq` ASSUME_TAC THENL
   [ASM_MESON_TAC[ECBA_IMP_BALG; EBALG_IMP_PORDER]; ALL_TAC] THEN
  SUBGOAL_THEN
   `(bvalf D (E:A->A->bool) B leq v (!! n p)) IN D /\
    (E:A->A->bool) (bvalf D E B leq v (!! n p)) B /\
    (bvalf D (E:A->A->bool) B leq v (!! n q)) IN D /\
    (E:A->A->bool) (bvalf D E B leq v (!! n q)) B`
   STRIP_ASSUME_TAC THENL
   [REPEAT CONJ_TAC THENL
     [MP_TAC(ISPECL
             [`!! n p`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`v:num->A`]
             BVALF_SPEC) THEN ASM_SIMP_TAC[];
      MP_TAC(ISPECL
             [`!! n p`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`v:num->A`]
             BVALF_IN_B) THEN ASM_SIMP_TAC[];
      MP_TAC(ISPECL
             [`!! n q`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`v:num->A`]
             BVALF_SPEC) THEN ASM_SIMP_TAC[];
      MP_TAC(ISPECL
             [`!! n q`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`v:num->A`]
             BVALF_IN_B) THEN ASM_SIMP_TAC[]];
    ALL_TAC] THEN
  MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
    `bvalf D (E:A->A->bool) B leq v (!! n p)`;
    `bvalf D (E:A->A->bool) B leq v (!! n q)`] EPORDER_ANTISYM) THEN
  ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`n:num`;`q:form`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
                  `v:num->A`; `bvalf D (E:A->A->bool) B leq v (!! n p)`]
                   BVALF_ALL_GLB) THEN
    ASM_REWRITE_TAC[] THEN X_GEN_TAC `c:A` THEN STRIP_TAC THEN
    SUBGOAL_THEN `bvalf D (E:A->A->bool) B leq ((n |-> c) v) p =
                  bvalf D E B leq ((n |-> c) v) q` (SUBST1_TAC o SYM) THENL
     [FIRST_ASSUM MATCH_MP_TAC THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    MATCH_MP_TAC(ISPECL
                 [`n:num`;`p:form`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
                  `v:num->A`;`c:A`] BVALF_ALL_LB) THEN ASM_REWRITE_TAC[];
    MATCH_MP_TAC(ISPECL
                 [`n:num`;`p:form`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
                  `v:num->A`; `bvalf D (E:A->A->bool) B leq v (!! n q)`]
                   BVALF_ALL_GLB) THEN
    ASM_REWRITE_TAC[] THEN X_GEN_TAC `c:A` THEN STRIP_TAC THEN
    SUBGOAL_THEN `bvalf D (E:A->A->bool) B leq ((n |-> c) v) p =
                  bvalf D E B leq ((n |-> c) v) q` SUBST1_TAC THENL
     [FIRST_ASSUM MATCH_MP_TAC THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    MATCH_MP_TAC(ISPECL
                 [`n:num`;`q:form`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
                  `v:num->A`;`c:A`] BVALF_ALL_LB) THEN ASM_REWRITE_TAC[]]);;

(* ================================================================= *)
(* F8-C: MAXPRIN_ALL -- Boolean maximum principle for !!.             *)
(* Dual of MAXPRIN_EX via De Morgan: apply MAXPRIN_EX to (Not p); the *)
(* same witness a works since [[?? n(Not p)]]=compl[[!! n(Not Not p)]] *)
(* =compl[[!! n p]] and [[Not p(a)]]=compl[[p(a)]], then ECOMPL_UNIQUE.*)
(* ================================================================= *)
let MAXPRIN_ALL = prove
 (`!n p D (E:A->A->bool) B leq v.
     model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
     valuation D v /\ (!i. bname D E B (v i)) /\
     (!u. u IN D ==> elmem D E u)
     ==> ?a. a IN D /\ bname D E B a /\
             bvalf D E B leq ((n |-> (a:A)) (v:num->A)) p = bvalf D E B leq
               v (!! n p)`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `ebalg D (E:A->A->bool) B leq /\ eporder D (E:A->A->bool) B leq`
    STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[ECBA_IMP_BALG; EBALG_IMP_PORDER]; ALL_TAC] THEN
  (* --- MAXPRIN_EX on (Not p): witness a with [[Not p (a)]] = [[?? n (Not *)
  (* p)]] --- *)
  MP_TAC(ISPECL
         [`n:num`;`Not p`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`v:num->A`]
         MAXPRIN_EX) THEN ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `a:A` (CONJUNCTS_THEN2 (LABEL_TAC "aD")
    (CONJUNCTS_THEN2 (LABEL_TAC "bna") (LABEL_TAC "e1")))) THEN
  EXISTS_TAC `a:A` THEN ASM_REWRITE_TAC[] THEN
  SUBGOAL_THEN `valuation D ((n |-> (a:A)) (v:num->A)) /\
                (!i. bname D (E:A->A->bool) B (((n |-> (a:A)) (v:num->A)) i))`
    STRIP_ASSUME_TAC THENL
   [CONJ_TAC THENL
     [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[];
      MATCH_MP_TAC BNAMEVAL_VALMOD THEN ASM_REWRITE_TAC[]]; ALL_TAC] THEN
  (* --- ecompl [[p(a)]] [[Not p (a)]] --- *)
  MP_TAC(ISPECL
         [`p:form`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
          `(n |-> (a:A)) (v:num->A)`]
         BVALF_NOT) THEN ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(LABEL_TAC "cPA") THEN
  (* --- ecompl [[!! n (Not(Not p))]] [[?? n (Not p)]] --- *)
  SUBGOAL_THEN `ecompl D (E:A->A->bool) B leq
     (bvalf D E B leq v (!! n (Not(Not p))))
     (bvalf D E B leq v (?? n (Not p)))` (LABEL_TAC "cAllnnp") THENL
   [SUBGOAL_THEN `(?? n (Not p)) = Not(!! n (Not(Not p)))` SUBST1_TAC THENL
     [REWRITE_TAC[Exists_DEF]; ALL_TAC] THEN
    MATCH_MP_TAC(ISPECL
                 [`!! n (Not(Not p))`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
                  `v:num->A`] BVALF_NOT) THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  (* --- [[!! n (Not(Not p))]] = [[!! n p]]  (BVALF_ALL_CONG + double *)
  (* negation) --- *)
  SUBGOAL_THEN `bvalf D (E:A->A->bool) B leq v (!! n (Not(Not p))) =
                bvalf D E B leq v (!! n p)` (LABEL_TAC "alleq") THENL
   [MATCH_MP_TAC(ISPECL
                 [`n:num`;`Not(Not p)`;`p:form`;`D:A->bool`;`E:A->A->bool`;
                  `B:A`;`leq:A`;`v:num->A`] BVALF_ALL_CONG) THEN
    ASM_REWRITE_TAC[] THEN X_GEN_TAC `c:A` THEN STRIP_TAC THEN
    SUBGOAL_THEN `valuation D ((n |-> (c:A)) (v:num->A)) /\
                  (!i. bname D (E:A->A->bool) B
                   (((n |-> (c:A)) (v:num->A)) i))`
      STRIP_ASSUME_TAC THENL
     [CONJ_TAC THENL
       [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[];
        MATCH_MP_TAC BNAMEVAL_VALMOD THEN ASM_REWRITE_TAC[]]; ALL_TAC] THEN
    MP_TAC(ISPECL
           [`p:form`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
            `(n |-> (c:A)) (v:num->A)`]
           BVALF_NOT) THEN ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_TAC THEN
    MP_TAC(ISPECL
           [`Not p`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
            `(n |-> (c:A)) (v:num->A)`]
           BVALF_NOT) THEN ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_TAC THEN
    MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
       `bvalf D (E:A->A->bool) B leq ((n |-> (c:A)) (v:num->A)) p`;
       `bvalf D (E:A->A->bool) B leq ((n |-> (c:A)) (v:num->A)) (Not p)`;
       `bvalf D (E:A->A->bool) B leq ((n |-> (c:A)) (v:num->A)) (Not(Not p))`]
             ECOMPL_INVOL) THEN
    ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
     [MP_TAC(ISPECL
             [`p:form`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
              `(n |-> (c:A)) (v:num->A)`]
             BVALF_SPEC) THEN ASM_SIMP_TAC[];
      MP_TAC(ISPECL
             [`p:form`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
              `(n |-> (c:A)) (v:num->A)`]
             BVALF_IN_B) THEN ASM_SIMP_TAC[]];
    ALL_TAC] THEN
  (* --- membership facts for PA, ALLP, EXNP --- *)
  SUBGOAL_THEN
   `(bvalf D (E:A->A->bool) B leq ((n |-> (a:A)) (v:num->A)) p) IN D /\
    (E:A->A->bool) (bvalf D E B leq ((n |-> (a:A)) (v:num->A)) p) B /\
    (bvalf D (E:A->A->bool) B leq v (!! n p)) IN D /\
    (E:A->A->bool) (bvalf D E B leq v (!! n p)) B /\
    (bvalf D (E:A->A->bool) B leq v (?? n (Not p))) IN D /\
    (E:A->A->bool) (bvalf D E B leq v (?? n (Not p))) B`
   STRIP_ASSUME_TAC THENL
   [REPEAT CONJ_TAC THENL
     [MP_TAC(ISPECL
             [`p:form`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
              `(n |-> (a:A)) (v:num->A)`]
             BVALF_SPEC) THEN ASM_SIMP_TAC[];
      MP_TAC(ISPECL
             [`p:form`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
              `(n |-> (a:A)) (v:num->A)`]
             BVALF_IN_B) THEN ASM_SIMP_TAC[];
      MP_TAC(ISPECL
             [`!! n p`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`v:num->A`]
             BVALF_SPEC) THEN ASM_SIMP_TAC[];
      MP_TAC(ISPECL
             [`!! n p`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`v:num->A`]
             BVALF_IN_B) THEN ASM_SIMP_TAC[];
      MP_TAC(ISPECL
             [`?? n (Not p)`;`D:A->bool`;`E:A->A->bool`;`B:A`;
              `leq:A`;`v:num->A`]
             BVALF_SPEC) THEN ASM_SIMP_TAC[];
      MP_TAC(ISPECL
             [`?? n (Not p)`;`D:A->bool`;`E:A->A->bool`;`B:A`;
              `leq:A`;`v:num->A`]
             BVALF_IN_B) THEN ASM_SIMP_TAC[]];
    ALL_TAC] THEN
  (* --- ecompl [[p(a)]] [[?? n (Not p)]]  (from cPA + e1) --- *)
  SUBGOAL_THEN `ecompl D (E:A->A->bool) B leq
     (bvalf D E B leq ((n |-> (a:A)) (v:num->A)) p)
       (bvalf D E B leq v (?? n (Not p)))`
   (LABEL_TAC "cPAex") THENL
   [USE_THEN "cPA" (fun cth -> USE_THEN "e1" (fun eth ->
      ACCEPT_TAC(REWRITE_RULE[eth] cth))); ALL_TAC] THEN
  (* --- ecompl [[!! n p]] [[?? n (Not p)]]  (from cAllnnp + alleq) --- *)
  SUBGOAL_THEN `ecompl D (E:A->A->bool) B leq
     (bvalf D E B leq v (!! n p)) (bvalf D E B leq v (?? n (Not p)))`
   (LABEL_TAC "cAllex") THENL
   [USE_THEN "cAllnnp" (fun cth -> USE_THEN "alleq" (fun eth ->
      ACCEPT_TAC(REWRITE_RULE[eth] cth))); ALL_TAC] THEN
  (* --- symmetrise both to base [[?? n (Not p)]], then ECOMPL_UNIQUE --- *)
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
     `bvalf D (E:A->A->bool) B leq ((n |-> (a:A)) (v:num->A)) p`;
     `bvalf D (E:A->A->bool) B leq v (?? n (Not p))`] ECOMPL_SYM) THEN
  ASM_REWRITE_TAC[] THEN DISCH_TAC THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
     `bvalf D (E:A->A->bool) B leq v (!! n p)`;
     `bvalf D (E:A->A->bool) B leq v (?? n (Not p))`] ECOMPL_SYM) THEN
  ASM_REWRITE_TAC[] THEN DISCH_TAC THEN
  MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
     `bvalf D (E:A->A->bool) B leq v (?? n (Not p))`;
     `bvalf D (E:A->A->bool) B leq ((n |-> (a:A)) (v:num->A)) p`;
     `bvalf D (E:A->A->bool) B leq v (!! n p)`] ECOMPL_UNIQUE) THEN
  ASM_REWRITE_TAC[]);;

(* ===================================================================== *)
(* F8-D  Los's theorem for the ultrafilter quotient N^B/U  (+ helpers)    *)
(* ===================================================================== *)

let EULTRA_IMP = prove
 (`!D (E:A->A->bool) B leq U a b r.
      ebalg D E B leq /\ eultra D E B leq U /\
      a IN D /\ b IN D /\ r IN D /\ E a B /\ E b B /\ E r B /\
      ebimp D E B leq a b r
      ==> (E r U <=> (E a U ==> E b U))`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `eporder D (E:A->A->bool) B leq` ASSUME_TAC THENL
   [ASM_MESON_TAC[EBALG_IMP_PORDER]; ALL_TAC] THEN
  EQ_TAC THENL
   [(* ==> : r in U  ==>  (a in U ==> b in U) *)
    REPEAT STRIP_TAC THEN
    MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`r:A`;`a:A`]
           EBALG_MEET) THEN
    ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `mra:A`) THEN
    SUBGOAL_THEN `(mra:A) IN D /\ (E:A->A->bool) mra B` STRIP_ASSUME_TAC THENL
     [ASM_MESON_TAC[EMEET_IN]; ALL_TAC] THEN
    SUBGOAL_THEN `(E:A->A->bool) mra U` ASSUME_TAC THENL
     [MATCH_MP_TAC(ISPECL
                   [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`U:A`;`r:A`;`a:A`;
                    `mra:A`] EULTRA_MEET) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN `erel D (E:A->A->bool) leq mra b` ASSUME_TAC THENL
     [MATCH_MP_TAC(ISPECL
                   [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`r:A`;`a:A`;`b:A`;
                    `r:A`;`mra:A`] EBIMP_MEET_LE) THEN
      ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[EPORDER_REFL]; ALL_TAC] THEN
    MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`U:A`;`mra:A`;`b:A`]
                 EULTRA_UP) THEN ASM_REWRITE_TAC[];
    (* <== : (a in U ==> b in U)  ==>  r in U *)
    DISCH_TAC THEN
    MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`U:A`;`a:A`]
           EULTRA_DICHOT) THEN
    ASM_REWRITE_TAC[] THEN
    DISCH_THEN(DISJ_CASES_THEN2 (LABEL_TAC "aU")
      (X_CHOOSE_THEN `ca:A` STRIP_ASSUME_TAC)) THENL
     [(* case a in U : then b in U and b <= r *)
      SUBGOAL_THEN `(E:A->A->bool) b U` ASSUME_TAC THENL
       [FIRST_X_ASSUM MATCH_MP_TAC THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
      MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`b:A`;`a:A`]
             EBALG_MEET) THEN
      ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `mba:A`) THEN
      SUBGOAL_THEN `(mba:A) IN D /\ (E:A->A->bool) mba B`
        STRIP_ASSUME_TAC THENL
        [ASM_MESON_TAC[EMEET_IN]; ALL_TAC] THEN
      SUBGOAL_THEN `erel D (E:A->A->bool) leq mba b` ASSUME_TAC THENL
       [ASM_MESON_TAC[EMEET_LE]; ALL_TAC] THEN
      SUBGOAL_THEN `erel D (E:A->A->bool) leq b r` ASSUME_TAC THENL
       [MATCH_MP_TAC(ISPECL
                     [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`b:A`;
                      `a:A`;`b:A`;
                      `r:A`;`mba:A`] EBIMP_LE_IMP) THEN ASM_REWRITE_TAC[];
             ALL_TAC] THEN
      MATCH_MP_TAC(ISPECL
                   [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`U:A`;`b:A`;`r:A`]
                   EULTRA_UP) THEN ASM_REWRITE_TAC[];
      (* case  ecompl a ca /\ ca in U : then ca <= r *)
      SUBGOAL_THEN `(ca:A) IN D /\ (E:A->A->bool) ca B` STRIP_ASSUME_TAC THENL
       [ASM_MESON_TAC[ECOMPL_IN]; ALL_TAC] THEN
      MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`] EBALG_BOT) THEN
      ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `bot:A`) THEN
      MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`] EBALG_TOP) THEN
      ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `top:A`) THEN
      SUBGOAL_THEN `(bot:A) IN D /\ (E:A->A->bool) bot B /\
                    (top:A) IN D /\ (E:A->A->bool) top B`
        STRIP_ASSUME_TAC THENL
        [ASM_MESON_TAC[EBOT_IN; ETOP_IN]; ALL_TAC] THEN
      SUBGOAL_THEN `emeet D (E:A->A->bool) B leq a ca bot` ASSUME_TAC THENL
       [MP_TAC(ISPECL
               [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`a:A`;`ca:A`;`bot:A`;
                `top:A`] ECOMPL_MEET_JOIN) THEN ASM_REWRITE_TAC[] THEN
                    STRIP_TAC THEN
                    ASM_REWRITE_TAC[]; ALL_TAC] THEN
      SUBGOAL_THEN `emeet D (E:A->A->bool) B leq ca a bot` ASSUME_TAC THENL
       [MATCH_MP_TAC(ISPECL
                     [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`a:A`;`ca:A`;
                      `bot:A`] EMEET_SYM) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
      SUBGOAL_THEN `erel D (E:A->A->bool) leq bot b` ASSUME_TAC THENL
       [MATCH_MP_TAC(ISPECL
                     [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`bot:A`;`b:A`]
                     EBOT_LE) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
      SUBGOAL_THEN `erel D (E:A->A->bool) leq ca r` ASSUME_TAC THENL
       [MATCH_MP_TAC(ISPECL
                     [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`ca:A`;
                      `a:A`;`b:A`;
                      `r:A`;`bot:A`] EBIMP_LE_IMP) THEN ASM_REWRITE_TAC[];
                    ALL_TAC] THEN
      MATCH_MP_TAC(ISPECL
                   [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`U:A`;
                    `ca:A`;`r:A`]
                   EULTRA_UP) THEN ASM_REWRITE_TAC[]]]);;

let QREP_PUSH = prove
 (`!D (E:A->A->bool) B leq U n c (v:num->A).
     (n |-> qrep D E B leq U c) (\i. qrep D E B leq U (v i)) =
     (\i. qrep D E B leq U (((n |-> c) v) i))`,
  REPEAT GEN_TAC THEN REWRITE_TAC[FUN_EQ_THM] THEN X_GEN_TAC `i:num` THEN
  ASM_CASES_TAC `i:num = n` THEN ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER]);;

(* ubig on a bvalf value collapses to plain E .. U since bvalf is always IN *)
(* D *)
let UBIG_BVALF = prove
 (`!p D (E:A->A->bool) B leq U v.
     model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
     valuation D v /\ (!i. bname D E B (v i))
     ==> (ubig D E U (bvalf D E B leq v p) <=> E (bvalf D E B leq v p) U)`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `(bvalf D (E:A->A->bool) B leq v p) IN D` ASSUME_TAC THENL
   [MP_TAC(ISPECL
           [`p:form`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`v:num->A`]
           BVALF_SPEC) THEN ASM_SIMP_TAC[]; ALL_TAC] THEN
  ASM_REWRITE_TAC[ubig]);;

(* qrep respects umem in both slots: the E'-quotient membership on *)
(* representatives *)
let UMEM_QREP = prove
 (`!D (E:A->A->bool) B leq U a b.
     model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
     eultra D E B leq U /\ a IN D /\ b IN D /\ bname D E B a /\ bname D E B b
     ==> (umem D E B leq U (qrep D E B leq U a) (qrep D E B leq U b) <=>
          umem D E B leq U a b)`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`U:A`;`a:A`]
         QREP_SPEC) THEN
  ASM_REWRITE_TAC[] THEN STRIP_TAC THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`U:A`;`b:A`]
         QREP_SPEC) THEN
  ASM_REWRITE_TAC[] THEN STRIP_TAC THEN
  EQ_TAC THEN DISCH_TAC THENL
   [(* umem (qrep a)(qrep b) ==> umem a b *)
    MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`U:A`;
      `a:A`;`qrep D (E:A->A->bool) B leq U b`;`b:A`] UMEM_CONG_R) THEN
    ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
     [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`U:A`;
        `b:A`;`qrep D (E:A->A->bool) B leq U b`] USIM_SYM) THEN
          ASM_REWRITE_TAC[];
          ALL_TAC] THEN
    MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`U:A`;
      `qrep D (E:A->A->bool) B leq U a`;`a:A`;
      `qrep D (E:A->A->bool) B leq U b`]
      UMEM_CONG_L) THEN
    ASM_REWRITE_TAC[] THEN
    MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`U:A`;
      `a:A`;`qrep D (E:A->A->bool) B leq U a`] USIM_SYM) THEN
    ASM_REWRITE_TAC[];
    (* umem a b ==> umem (qrep a)(qrep b) *)
    MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`U:A`;
      `qrep D (E:A->A->bool) B leq U a`;`b:A`;
      `qrep D (E:A->A->bool) B leq U b`]
      UMEM_CONG_R) THEN
    ASM_REWRITE_TAC[] THEN
    MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`U:A`;
      `a:A`;`qrep D (E:A->A->bool) B leq U a`;`b:A`] UMEM_CONG_L) THEN
    ASM_REWRITE_TAC[]]);;

(* range the quotient-domain universal over D-bnames via representatives *)
let QDOM_FORALL = prove
 (`!D (E:A->A->bool) B leq U (P:A->bool).
     (!a. a IN qdom D E B leq U ==> P a) <=>
     (!c. c IN D /\ bname D E B c ==> P (qrep D E B leq U c))`,
  REPEAT GEN_TAC THEN REWRITE_TAC[IN; qdom] THEN EQ_TAC THEN DISCH_TAC THENL
   [X_GEN_TAC `c:A` THEN STRIP_TAC THEN FIRST_X_ASSUM MATCH_MP_TAC THEN
    EXISTS_TAC `c:A` THEN ASM_REWRITE_TAC[];
    X_GEN_TAC `a:A` THEN DISCH_THEN(X_CHOOSE_THEN `c:A` STRIP_ASSUME_TAC) THEN
    ASM_REWRITE_TAC[] THEN FIRST_X_ASSUM MATCH_MP_TAC THEN
    ASM_REWRITE_TAC[]]);;

(* umem on valuation-atoms is the U-bigness of the atomic Boolean value *)
let UMEM_BVALF = prove
 (`!i j D (E:A->A->bool) B leq U v.
     model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
     valuation D v /\ (!k. bname D E B (v k))
     ==> (umem D E B leq U (v i) (v j) <=>
          ubig D E U (bvalf D E B leq v (i %% j)))`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[umem] THEN
  SUBGOAL_THEN
    `ebv_in D (E:A->A->bool) B leq (v i) (v j) (bvalf D E B leq v (i %% j))`
    ASSUME_TAC THENL
    [MATCH_MP_TAC BVALF_MEM THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(v:num->A) i IN D /\ (v:num->A) j IN D /\
                (bvalf D (E:A->A->bool) B leq v (i %% j)) IN D`
    STRIP_ASSUME_TAC THENL
   [REPEAT CONJ_TAC THENL
     [ASM_MESON_TAC[valuation]; ASM_MESON_TAC[valuation];
      MP_TAC(ISPECL
             [`(i:num) %% j`;`D:A->bool`;`E:A->A->bool`;`B:A`;
              `leq:A`;`v:num->A`]
             BVALF_SPEC) THEN ASM_SIMP_TAC[]]; ALL_TAC] THEN
  EQ_TAC THENL
   [DISCH_THEN(X_CHOOSE_THEN `z:A` STRIP_ASSUME_TAC) THEN
    SUBGOAL_THEN `z:A = bvalf D (E:A->A->bool) B leq v (i %% j)`
      SUBST_ALL_TAC THENL
      [MATCH_MP_TAC(ISPECL
                    [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`(v:num->A) i`;
                     `(v:num->A) j`;`z:A`;
                     `bvalf D (E:A->A->bool) B leq v (i %% j)`]
                      EBV_IN_UNIQUE) THEN
      ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[ubig]; ALL_TAC] THEN
    ASM_REWRITE_TAC[];
    DISCH_TAC THEN EXISTS_TAC `bvalf D (E:A->A->bool) B leq v (i %% j)` THEN
    ASM_REWRITE_TAC[]]);;

(* usim on valuation-atoms is the U-bigness of the atomic equality value *)
let USIM_BVALF = prove
 (`!i j D (E:A->A->bool) B leq U v.
     model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
     valuation D v /\ (!k. bname D E B (v k))
     ==> (usim D E B leq U (v i) (v j) <=>
          ubig D E U (bvalf D E B leq v (Eq i j)))`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[usim] THEN
  SUBGOAL_THEN
    `ebv_eq D (E:A->A->bool) B leq (v i) (v j) (bvalf D E B leq v (Eq i j))`
    ASSUME_TAC THENL
    [MATCH_MP_TAC BVALF_EQ2 THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(v:num->A) i IN D /\ (v:num->A) j IN D /\
                (bvalf D (E:A->A->bool) B leq v (Eq i j)) IN D`
    STRIP_ASSUME_TAC THENL
   [REPEAT CONJ_TAC THENL
     [ASM_MESON_TAC[valuation]; ASM_MESON_TAC[valuation];
      MP_TAC(ISPECL
             [`Eq i j`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`v:num->A`]
             BVALF_SPEC) THEN ASM_SIMP_TAC[]]; ALL_TAC] THEN
  EQ_TAC THENL
   [DISCH_THEN(X_CHOOSE_THEN `z:A` STRIP_ASSUME_TAC) THEN
    SUBGOAL_THEN `z:A = bvalf D (E:A->A->bool) B leq v (Eq i j)`
      SUBST_ALL_TAC THENL
      [MATCH_MP_TAC(ISPECL
                    [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`(v:num->A) i`;
                     `(v:num->A) j`;`z:A`;
                     `bvalf D (E:A->A->bool) B leq v (Eq i j)`]
                      EBV_EQ_UNIQUE) THEN
      ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[ubig]; ALL_TAC] THEN
    ASM_REWRITE_TAC[];
    DISCH_TAC THEN EXISTS_TAC `bvalf D (E:A->A->bool) B leq v (Eq i j)` THEN
    ASM_REWRITE_TAC[]]);;
(* ===================  F8-D  Los's theorem for the ultrafilter quotient *)
(* === *)
let LOS = prove
 (`!phi. !D (E:A->A->bool) B leq U v.
      model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
      eultra D E B leq U /\ valuation D v /\ (!i. bname D E B (v i)) /\
      (!u. u IN D ==> elmem D E u)
      ==> (holds (qdom D E B leq U) (qmem D E B leq U)
                 (\i. qrep D E B leq U (v i)) phi
           <=> ubig D E U (bvalf D E B leq v phi))`,
  MATCH_MP_TAC form_INDUCT THEN REPEAT CONJ_TAC THENL
  [(* ---------- False ---------- *)
   REPEAT GEN_TAC THEN TRY BETA_TAC THEN REPEAT GEN_TAC THEN STRIP_TAC THEN
   REWRITE_TAC[holds] THEN
   SUBGOAL_THEN `ebot D (E:A->A->bool) B leq (bvalf D E B leq v False)`
     ASSUME_TAC THENL
     [MATCH_MP_TAC BVALF_FALSE THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
   SUBGOAL_THEN `~((E:A->A->bool) (bvalf D E B leq v False) U)`
     ASSUME_TAC THENL
     [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`U:A`;
       `bvalf D (E:A->A->bool) B leq v False`] EULTRA_NOT_BOT) THEN
           ASM_REWRITE_TAC[];
     ALL_TAC] THEN
   ASM_REWRITE_TAC[ubig];
   (* ---------- i %% j ---------- *)
   REPEAT GEN_TAC THEN TRY BETA_TAC THEN REPEAT GEN_TAC THEN STRIP_TAC THEN
   REWRITE_TAC[holds; qmem] THEN BETA_TAC THEN
   SUBGOAL_THEN `(v:num->A) a0 IN D /\ (v:num->A) a1 IN D /\
                 bname D (E:A->A->bool) B (v a0) /\ bname D E B (v a1)`
     STRIP_ASSUME_TAC THENL
     [REPEAT CONJ_TAC THEN ASM_MESON_TAC[valuation]; ALL_TAC] THEN
     SUBGOAL_THEN
     `umem D (E:A->A->bool) B leq U (qrep D E B leq U ((v:num->A) a0))
      (qrep D E B leq U (v a1)) <=>
      umem D E B leq U (v a0) (v a1)` SUBST1_TAC THENL
    [MATCH_MP_TAC UMEM_QREP THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
   MATCH_MP_TAC(ISPECL
                [`a0:num`;`a1:num`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
                 `U:A`;`v:num->A`] UMEM_BVALF) THEN ASM_REWRITE_TAC[];
   (* ---------- Eq i j ---------- *)
   REPEAT GEN_TAC THEN TRY BETA_TAC THEN REPEAT GEN_TAC THEN STRIP_TAC THEN
   REWRITE_TAC[holds] THEN BETA_TAC THEN
   SUBGOAL_THEN `(v:num->A) a0 IN D /\ (v:num->A) a1 IN D /\
                 bname D (E:A->A->bool) B (v a0) /\ bname D E B (v a1)`
     STRIP_ASSUME_TAC THENL
     [REPEAT CONJ_TAC THEN ASM_MESON_TAC[valuation]; ALL_TAC] THEN
     MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`U:A`;
     `(v:num->A) a0`;`(v:num->A) a1`] QREP_EQ) THEN ASM_REWRITE_TAC[] THEN
   DISCH_THEN(SUBST1_TAC o SYM) THEN
   MATCH_MP_TAC(ISPECL
                [`a0:num`;`a1:num`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
                 `U:A`;`v:num->A`] USIM_BVALF) THEN ASM_REWRITE_TAC[];
   (* ---------- a0 --> a1 ---------- *)
   REPEAT GEN_TAC THEN TRY BETA_TAC THEN
   DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "ih0") (LABEL_TAC "ih1")) THEN
   REPEAT GEN_TAC THEN STRIP_TAC THEN REWRITE_TAC[holds] THEN
   SUBGOAL_THEN `holds (qdom D E B leq U) (qmem D E B leq U)
                       (\i. qrep D (E:A->A->bool) B leq U (v i)) a0
                 <=> ubig D E U (bvalf D E B leq v a0)` SUBST1_TAC THENL
    [USE_THEN "ih0" MATCH_MP_TAC THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
   SUBGOAL_THEN `holds (qdom D E B leq U) (qmem D E B leq U)
                       (\i. qrep D (E:A->A->bool) B leq U (v i)) a1
                 <=> ubig D E U (bvalf D E B leq v a1)` SUBST1_TAC THENL
    [USE_THEN "ih1" MATCH_MP_TAC THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
   SUBGOAL_THEN
    `(bvalf D (E:A->A->bool) B leq v a0) IN D /\ E (bvalf D E B leq v a0) B /\
     (bvalf D (E:A->A->bool) B leq v a1) IN D /\ E (bvalf D E B leq v a1) B /\
     (bvalf D (E:A->A->bool) B leq v (a0 --> a1)) IN D /\
     E (bvalf D E B leq v (a0 --> a1)) B`
    STRIP_ASSUME_TAC THENL
    [REPEAT CONJ_TAC THENL
      [MP_TAC(ISPECL
              [`a0:form`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`v:num->A`]
              BVALF_SPEC) THEN ASM_SIMP_TAC[];
       MP_TAC(ISPECL
              [`a0:form`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`v:num->A`]
              BVALF_IN_B) THEN ASM_SIMP_TAC[];
       MP_TAC(ISPECL
              [`a1:form`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`v:num->A`]
              BVALF_SPEC) THEN ASM_SIMP_TAC[];
       MP_TAC(ISPECL
              [`a1:form`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`v:num->A`]
              BVALF_IN_B) THEN ASM_SIMP_TAC[];
       MP_TAC(ISPECL
              [`a0 --> a1`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`v:num->A`]
              BVALF_SPEC) THEN ASM_SIMP_TAC[];
       MP_TAC(ISPECL
              [`a0 --> a1`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`v:num->A`]
              BVALF_IN_B) THEN ASM_SIMP_TAC[]]; ALL_TAC] THEN
   SUBGOAL_THEN `ubig D (E:A->A->bool) U (bvalf D E B leq v a0) <=>
                 E (bvalf D E B leq v a0) U` SUBST1_TAC THENL
    [MATCH_MP_TAC UBIG_BVALF THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
   SUBGOAL_THEN `ubig D (E:A->A->bool) U (bvalf D E B leq v a1) <=>
                 E (bvalf D E B leq v a1) U` SUBST1_TAC THENL
    [MATCH_MP_TAC UBIG_BVALF THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
   SUBGOAL_THEN `ubig D (E:A->A->bool) U (bvalf D E B leq v (a0 --> a1)) <=>
                 E (bvalf D E B leq v (a0 --> a1)) U` SUBST1_TAC THENL
    [MATCH_MP_TAC UBIG_BVALF THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
   CONV_TAC SYM_CONV THEN
   MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`U:A`;
     `bvalf D (E:A->A->bool) B leq v a0`;`bvalf D (E:A->A->bool) B leq v a1`;
     `bvalf D (E:A->A->bool) B leq v (a0 --> a1)`] EULTRA_IMP) THEN
   ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
    [ASM_MESON_TAC[ECBA_IMP_BALG];
     MATCH_MP_TAC BVALF_IMP THEN ASM_REWRITE_TAC[]];
   (* ---------- !! a0 a1 ---------- *)
   REPEAT GEN_TAC THEN TRY BETA_TAC THEN DISCH_THEN(LABEL_TAC "ih") THEN
   REPEAT GEN_TAC THEN STRIP_TAC THEN REWRITE_TAC[holds] THEN
   ONCE_REWRITE_TAC[QDOM_FORALL] THEN ONCE_REWRITE_TAC[QREP_PUSH] THEN
   SUBGOAL_THEN `ubig D (E:A->A->bool) U (bvalf D E B leq v (!! a0 a1)) <=>
                 E (bvalf D E B leq v (!! a0 a1)) U` SUBST1_TAC THENL
    [MATCH_MP_TAC UBIG_BVALF THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
   EQ_TAC THENL
    [(* ==> : maximum principle *)
     DISCH_THEN(LABEL_TAC "H") THEN
     MP_TAC(ISPECL
            [`a0:num`;`a1:form`;`D:A->bool`;`E:A->A->bool`;`B:A`;
             `leq:A`;`v:num->A`]
            MAXPRIN_ALL) THEN ASM_REWRITE_TAC[] THEN
     DISCH_THEN(X_CHOOSE_THEN `a:A` (CONJUNCTS_THEN2 (LABEL_TAC "aD")
       (CONJUNCTS_THEN2 (LABEL_TAC "bna") (LABEL_TAC "eqm")))) THEN
     SUBGOAL_THEN `valuation D ((a0 |-> (a:A)) (v:num->A)) /\
                   (!i. bname D (E:A->A->bool) B (((a0 |-> a) v) i))`
       STRIP_ASSUME_TAC THENL
      [CONJ_TAC THENL
        [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[];
         MATCH_MP_TAC BNAMEVAL_VALMOD THEN ASM_REWRITE_TAC[]]; ALL_TAC] THEN
     SUBGOAL_THEN `holds (qdom D E B leq U) (qmem D E B leq U)
                         (\i. qrep D (E:A->A->bool) B leq U
                          (((a0 |-> (a:A)) v) i)) a1`
       (LABEL_TAC "hlds") THENL
      [USE_THEN "H" (fun th -> MP_TAC(SPEC `a:A` th)) THEN
       ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC]; ALL_TAC] THEN
     SUBGOAL_THEN
       `ubig D (E:A->A->bool) U (bvalf D E B leq ((a0 |-> (a:A)) v) a1)`
       MP_TAC THENL
      [SUBGOAL_THEN
         `holds (qdom D E B leq U) (qmem D E B leq U)
                (\i. qrep D (E:A->A->bool) B leq U (((a0 |-> (a:A)) v) i)) a1
          <=> ubig D E U (bvalf D E B leq ((a0 |-> (a:A)) v) a1)`
         MP_TAC THENL
        [USE_THEN "ih" (fun ith ->
           MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`U:A`;
             `(a0 |-> (a:A)) (v:num->A)`] ith)) THEN ASM_REWRITE_TAC[];
          ALL_TAC] THEN
       USE_THEN "hlds"
         (fun h -> DISCH_THEN(fun iff -> ACCEPT_TAC(EQ_MP iff h)));
         ALL_TAC] THEN
     REWRITE_TAC[ubig] THEN USE_THEN "eqm" SUBST1_TAC THEN
     STRIP_TAC THEN ASM_REWRITE_TAC[];
     (* <== : lower-bound + upward closure *)
     DISCH_TAC THEN X_GEN_TAC `c:A` THEN STRIP_TAC THEN
     SUBGOAL_THEN `valuation D ((a0 |-> (c:A)) (v:num->A)) /\
                   (!i. bname D (E:A->A->bool) B (((a0 |-> c) v) i))`
       STRIP_ASSUME_TAC THENL
      [CONJ_TAC THENL
        [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[];
         MATCH_MP_TAC BNAMEVAL_VALMOD THEN ASM_REWRITE_TAC[]]; ALL_TAC] THEN
     SUBGOAL_THEN `holds (qdom D E B leq U) (qmem D E B leq U)
                         (\i. qrep D (E:A->A->bool) B leq U
                          (((a0 |-> (c:A)) v) i)) a1
                   <=> ubig D E U (bvalf D E B leq ((a0 |-> c) v) a1)`
       SUBST1_TAC THENL
       [USE_THEN "ih" (fun ith ->
         MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`U:A`;
           `(a0 |-> (c:A)) (v:num->A)`] ith)) THEN ASM_REWRITE_TAC[];
                   ALL_TAC] THEN
     REWRITE_TAC[ubig] THEN CONJ_TAC THENL
      [MP_TAC(ISPECL
              [`a1:form`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
               `(a0 |-> (c:A)) (v:num->A)`]
              BVALF_SPEC) THEN ASM_SIMP_TAC[]; ALL_TAC] THEN
     MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`U:A`;
       `bvalf D (E:A->A->bool) B leq v (!! a0 a1)`;
       `bvalf D (E:A->A->bool) B leq ((a0 |-> (c:A)) v) a1`] EULTRA_UP) THEN
     ASM_REWRITE_TAC[] THEN REPEAT CONJ_TAC THENL
      [MP_TAC(ISPECL
              [`!! a0 a1`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`v:num->A`]
              BVALF_SPEC) THEN ASM_SIMP_TAC[];
       MP_TAC(ISPECL
              [`a1:form`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
               `(a0 |-> (c:A)) (v:num->A)`]
              BVALF_SPEC) THEN ASM_SIMP_TAC[];
       MP_TAC(ISPECL
              [`a1:form`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
               `(a0 |-> (c:A)) (v:num->A)`]
              BVALF_IN_B) THEN ASM_SIMP_TAC[];
       MATCH_MP_TAC(ISPECL
                    [`a0:num`;`a1:form`;`D:A->bool`;`E:A->A->bool`;
                     `B:A`;`leq:A`;
                     `v:num->A`;`c:A`] BVALF_ALL_LB) THEN
       ASM_REWRITE_TAC[]]]]);;

(* ------------------------------------------------------------------------- *)
(* F8-E: the ultrafilter quotient N^B/U models ZFC.                          *)
(*                                                                           *)
(* QVAL_LIFT lifts a quotient-domain valuation to a D-valuation by bnames;   *)
(* QSAT_AX is the per-axiom bridge (if [[phi]]_c = TOP for every bname       *)
(* valuation c, the quotient satisfies phi); BVALF_INFINITY_TOP packages     *)
(* the infinity axiom; BVALF_ZFC_TOP collects [[phi]] = TOP over the whole   *)
(* axiom set; FORCE_ZFC_OVER_VL_U assembles the endpoint:                    *)
(* for ANY ultrafilter U on the cba, model (qdom..) (qmem..) (ZFC axioms).   *)
(* ------------------------------------------------------------------------- *)

let QVAL_LIFT = prove
 (`!D (E:A->A->bool) B leq U v.
      valuation (qdom D E B leq U) v
      ==> ?c. valuation D c /\ (!i. bname D E B (c i)) /\
              (!i. (v:num->A) i = qrep D E B leq U (c i))`,
  REPEAT GEN_TAC THEN REWRITE_TAC[valuation] THEN DISCH_TAC THEN
  SUBGOAL_THEN
   `!i:num. ?a:A. a IN D /\ bname D (E:A->A->bool) B a /\
                  (v:num->A) i = qrep D E B leq U a`
   MP_TAC THENL
   [X_GEN_TAC `i:num` THEN FIRST_ASSUM(MP_TAC o SPEC `i:num`) THEN
    REWRITE_TAC[IN; qdom] THEN DISCH_THEN ACCEPT_TAC;
    ALL_TAC] THEN
  REWRITE_TAC[SKOLEM_THM] THEN
  DISCH_THEN(X_CHOOSE_THEN `c:num->A` STRIP_ASSUME_TAC) THEN
  EXISTS_TAC `c:num->A` THEN REWRITE_TAC[valuation] THEN ASM_MESON_TAC[]);;

let QSAT_AX = prove
 (`!D (E:A->A->bool) B leq U phi.
      model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
      eultra D E B leq U /\ (!u. u IN D ==> elmem D E u) /\
      (!c. valuation D c /\ (!i. bname D E B (c i))
           ==> etop D E B leq (bvalf D E B leq c phi))
      ==> !v. valuation (qdom D E B leq U) v
              ==> holds (qdom D E B leq U) (qmem D E B leq U) v phi`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN X_GEN_TAC `v:num->A` THEN DISCH_TAC THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`U:A`;`v:num->A`]
    QVAL_LIFT) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `c:num->A` STRIP_ASSUME_TAC) THEN
  SUBGOAL_THEN `v:num->A = \i. qrep D (E:A->A->bool) B leq U (c i)`
    SUBST_ALL_TAC THENL
   [REWRITE_TAC[FUN_EQ_THM] THEN BETA_TAC THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MP_TAC(ISPECL [`phi:form`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`U:A`;
    `c:num->A`] LOS) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN SUBST1_TAC THEN
  REWRITE_TAC[ubig] THEN
  SUBGOAL_THEN `etop D (E:A->A->bool) B leq (bvalf D E B leq c phi)`
    ASSUME_TAC THENL
   [FIRST_X_ASSUM MATCH_MP_TAC THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  CONJ_TAC THENL
   [ASM_MESON_TAC[ETOP_IN];
    MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`U:A`;
      `bvalf D (E:A->A->bool) B leq c phi`] EULTRA_TOP) THEN
    ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[EBALG_IMP_PORDER; ECBA_IMP_BALG]]);;

let BVALF_INFINITY_TOP = prove
 (`!D (E:A->A->bool) B leq.
      model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
      (!u. u IN D ==> elmem D E u)
      ==> !c. valuation D c /\ (!i. bname D E B (c i))
              ==> etop D E B leq (bvalf D E B leq c infinity_ax)`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN
    `?onebee:A. etop (D:A->bool) (E:A->A->bool) (B:A) (leq:A) onebee`
    STRIP_ASSUME_TAC THENL
   [MATCH_MP_TAC EBALG_TOP THEN ASM_MESON_TAC[ECBA_IMP_BALG]; ALL_TAC] THEN
  SUBGOAL_THEN `(onebee:A) IN D /\ (E:A->A->bool) onebee B`
    STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[ETOP_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `?om:A. eomega (D:A->bool) (E:A->A->bool) om`
    STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[EOMEGA_EXISTS]; ALL_TAC] THEN
  SUBGOAL_THEN `(om:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[EOMEGA_IN]; ALL_TAC] THEN
  SUBGOAL_THEN
    `?vom:A. echeck (D:A->bool) (E:A->A->bool) (onebee:A) (om:A) vom`
    STRIP_ASSUME_TAC THENL
   [MATCH_MP_TAC ECHECK_EXHAUSTION THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  X_GEN_TAC `c:num->A` THEN STRIP_TAC THEN
  MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
    `onebee:A`;`om:A`;`vom:A`;`c:num->A`] BVALF_INFINITY) THEN
  ASM_REWRITE_TAC[]);;

let BNAME_IN_D_EXISTS = prove
 (`!D (E:A->A->bool) B leq.
      model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
      (!u. u IN D ==> elmem D E u)
      ==> ?a. a IN D /\ bname D E B a`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN
    `?onebee:A. etop (D:A->bool) (E:A->A->bool) (B:A) (leq:A) onebee`
    STRIP_ASSUME_TAC THENL
   [MATCH_MP_TAC EBALG_TOP THEN ASM_MESON_TAC[ECBA_IMP_BALG]; ALL_TAC] THEN
  SUBGOAL_THEN `(onebee:A) IN D /\ (E:A->A->bool) onebee B`
    STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[ETOP_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `?d0:A. (d0:A) IN (D:A->bool)` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[MODEL_NONEMPTY; MEMBER_NOT_EMPTY]; ALL_TAC] THEN
  SUBGOAL_THEN
    `?vd0:A. echeck (D:A->bool) (E:A->A->bool) (onebee:A) (d0:A) vd0`
    STRIP_ASSUME_TAC THENL
   [MATCH_MP_TAC ECHECK_EXHAUSTION THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(d0:A) IN D /\ (vd0:A) IN D` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[ECHECK_IMP]; ALL_TAC] THEN
  EXISTS_TAC `vd0:A` THEN ASM_REWRITE_TAC[] THEN
  MATCH_MP_TAC(ISPECL
               [`D:A->bool`;`E:A->A->bool`;`onebee:A`;`B:A`;`d0:A`;`vd0:A`]
               ECHECK_IS_BNAME) THEN
  ASM_REWRITE_TAC[]);;

let BVALF_ZFC_TOP = prove
 (`!D (E:A->A->bool) B leq p.
      model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
      (!u. u IN D ==> elmem D E u) /\
      p IN (choice_ax INSERT ZF_AX)
      ==> !c. valuation D c /\ (!i. bname D E B (c i))
              ==> etop D E B leq (bvalf D E B leq c p)`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  UNDISCH_TAC `p IN (choice_ax INSERT ZF_AX)` THEN
  REWRITE_TAC[IN_INSERT; ZF_AX; IN_UNION; NOT_IN_EMPTY; IN_ELIM_THM] THEN
  STRIP_TAC THEN ASM_REWRITE_TAC[] THEN
  FIRST
   [MATCH_MP_TAC BVALF_INFINITY_TOP THEN ASM_REWRITE_TAC[];
    REPEAT STRIP_TAC THEN
    FIRST (map MATCH_MP_TAC
     [BVALF_EXTENSIONALITY; BVALF_FOUNDATION; BVALF_PAIRING; BVALF_UNION;
      BVALF_POWERSET; BVALF_CHOICE; BVALF_SEPARATION; BVALF_REPLACEMENT]) THEN
    ASM_REWRITE_TAC[]]);;

let FORCE_ZFC_OVER_VL_U = prove
 (`!D (E:A->A->bool) B leq U.
      model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
      eultra D E B leq U /\ (!u. u IN D ==> elmem D E u)
      ==> model (qdom D E B leq U) (qmem D E B leq U)
        (choice_ax INSERT ZF_AX)`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  REWRITE_TAC[model; satisfies] THEN CONJ_TAC THENL
   [MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`]
      BNAME_IN_D_EXISTS) THEN
    ASM_REWRITE_TAC[] THEN
    DISCH_THEN(X_CHOOSE_THEN `a0:A` STRIP_ASSUME_TAC) THEN
    MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`U:A`;`a0:A`]
      QDOM_NONEMPTY) THEN
    ASM_REWRITE_TAC[] THEN
    DISCH_THEN(X_CHOOSE_THEN `u0:A` ASSUME_TAC) THEN
    REWRITE_TAC[GSYM MEMBER_NOT_EMPTY; IN] THEN
    EXISTS_TAC `u0:A` THEN ASM_REWRITE_TAC[];
    MAP_EVERY X_GEN_TAC [`v:num->A`; `p:form`] THEN STRIP_TAC THEN
    MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`p:form`]
      BVALF_ZFC_TOP) THEN
    ASM_REWRITE_TAC[] THEN DISCH_TAC THEN
    MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`U:A`;`p:form`]
      QSAT_AX) THEN
    ASM_REWRITE_TAC[] THEN DISCH_THEN MATCH_MP_TAC THEN ASM_REWRITE_TAC[]]);;

(* ===================================================================== *)
(* F8-0 (EULTRA_EXISTS) algebra kit: generated filters + strong-compat   *)
(* dichotomy.  These are the semantic lemmas for the internal ultra-     *)
(* filter construction (transfinite recursion over an internal well-     *)
(* ordering of B).  The generated filter gen(g,e) is given ABSTRACTLY    *)
(* by its membership characterization so it composes with the erec value *)
(* characterization (F_a = the erec value at ordinal a).                 *)
(* ===================================================================== *)

(* COMPAT_SPLIT: if z meets both b and its complement cb in bot, z=bot.  *)
let COMPAT_SPLIT = prove
 (`!D (E:A->A->bool) B leq z b cb bot.
       ebalg D E B leq /\ z IN D /\ b IN D /\ cb IN D /\
       E z B /\ E b B /\ E cb B /\
       ecompl D E B leq b cb /\ ebot D E B leq bot /\
       emeet D E B leq z b bot /\ emeet D E B leq z cb bot
       ==> ebot D E B leq z`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `eporder D (E:A->A->bool) B leq` ASSUME_TAC THENL
   [ASM_MESON_TAC[EBALG_IMP_PORDER]; ALL_TAC] THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`] EBALG_TOP) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `top:A`) THEN
  SUBGOAL_THEN `(top:A) IN D /\ (E:A->A->bool) top B` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[ETOP_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `(bot:A) IN D /\ (E:A->A->bool) bot B` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[EBOT_IN]; ALL_TAC] THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
    `b:A`;`cb:A`;`bot:A`;`top:A`] ECOMPL_MEET_JOIN) THEN
  ASM_REWRITE_TAC[] THEN STRIP_TAC THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
    `top:A`;`z:A`] EMEET_TOP) THEN
  ASM_REWRITE_TAC[] THEN DISCH_TAC THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
    `bot:A`;`bot:A`] EJOIN_BOT) THEN
  ASM_REWRITE_TAC[] THEN DISCH_TAC THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
    `z:A`;`b:A`;`cb:A`;`top:A`;`z:A`;`bot:A`;`bot:A`;`bot:A`]
         EBALG_DISTRIB) THEN
  ASM_REWRITE_TAC[] THEN DISCH_TAC THEN
  ASM_MESON_TAC[]);;

(* ELE_BOT: x <= bot forces x = bot.                                     *)
let ELE_BOT = prove
 (`!D (E:A->A->bool) B leq x bot.
       eporder D E B leq /\ x IN D /\ E x B /\
       ebot D E B leq bot /\ erel D E leq x bot
       ==> x = bot`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  ASM_MESON_TAC[EPORDER_ANTISYM; EBOT_LE; EBOT_IN]);;

(* FILTER_COMPAT_SPLIT_STRONG: for a proper filter g and b with          *)
(* complement cb, EITHER every f in g meets b off bot, OR every f in g   *)
(* meets cb off bot (strong compatibility dichotomy).                    *)
let FILTER_COMPAT_SPLIT_STRONG = prove
 (`!D (E:A->A->bool) B leq g b cb bot.
       ebalg D E B leq /\ efilter D E B leq g /\
       ~(?z. ebot D E B leq z /\ E z g) /\
       b IN D /\ cb IN D /\ E b B /\ E cb B /\
       ecompl D E B leq b cb /\ ebot D E B leq bot
       ==> (!f m. f IN D /\ E f g /\ emeet D E B leq f b m
                  ==> ~(ebot D E B leq m)) \/
           (!f m. f IN D /\ E f g /\ emeet D E B leq f cb m
                  ==> ~(ebot D E B leq m))`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `eporder D (E:A->A->bool) B leq` ASSUME_TAC THENL
   [ASM_MESON_TAC[EBALG_IMP_PORDER]; ALL_TAC] THEN
  ASM_CASES_TAC `!f m. f IN D /\ E f g /\ emeet D (E:A->A->bool) B leq f b m
                       ==> ~(ebot D E B leq m)` THEN
  ASM_REWRITE_TAC[] THEN
  MAP_EVERY X_GEN_TAC [`f2:A`;`m2:A`] THEN STRIP_TAC THEN
  ASM_CASES_TAC `ebot D (E:A->A->bool) B leq m2` THEN ASM_REWRITE_TAC[] THEN
  FIRST_X_ASSUM(X_CHOOSE_THEN `f1:A` (X_CHOOSE_THEN `m1:A` STRIP_ASSUME_TAC) o
                REWRITE_RULE[NOT_FORALL_THM; NOT_IMP]) THEN
  SUBGOAL_THEN
    `?z:A. z IN D /\ (E:A->A->bool) z g /\ erel D E leq z f1 /\
     erel D E leq z f2`
    STRIP_ASSUME_TAC THENL
   [UNDISCH_TAC `efilter D (E:A->A->bool) B leq g` THEN
    REWRITE_TAC[efilter] THEN STRIP_TAC THEN
    FIRST_X_ASSUM MATCH_MP_TAC THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) f1 B /\ E f2 B /\ E z B` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[efilter; esubset]; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq b b /\ erel D E leq cb cb`
    STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[EPORDER_REFL]; ALL_TAC] THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`z:A`;`b:A`]
    EBALG_MEET) THEN ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_TAC `zb:A`) THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`z:A`;`cb:A`]
    EBALG_MEET) THEN ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_TAC `zcb:A`) THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq zb m1` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
       `z:A`;`b:A`;`f1:A`;`b:A`;`zb:A`;`m1:A`] EMEET_MONO) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq zcb m2` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
       `z:A`;`cb:A`;`f2:A`;`cb:A`;`zcb:A`;`m2:A`] EMEET_MONO) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `zb:A = bot` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
                        `zb:A`;`bot:A`]
                 ELE_BOT) THEN ASM_REWRITE_TAC[] THEN REPEAT CONJ_TAC THENL
     [ASM_MESON_TAC[EMEET_IN]; ASM_MESON_TAC[EMEET_IN];
      ASM_MESON_TAC[EBOT_UNIQUE]]; ALL_TAC] THEN
  SUBGOAL_THEN `zcb:A = bot` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
                        `zcb:A`;`bot:A`]
                 ELE_BOT) THEN ASM_REWRITE_TAC[] THEN REPEAT CONJ_TAC THENL
     [ASM_MESON_TAC[EMEET_IN]; ASM_MESON_TAC[EMEET_IN];
      ASM_MESON_TAC[EBOT_UNIQUE]]; ALL_TAC] THEN
  SUBGOAL_THEN `ebot D (E:A->A->bool) B leq z` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
       `z:A`;`b:A`;`cb:A`;`bot:A`] COMPAT_SPLIT) THEN
    ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[]; ALL_TAC] THEN
  ASM_MESON_TAC[]);;

(* ===================================================================== *)
(* F8-0 EULTRA_EXISTS U3 layer: internalization of the                    *)
(* ultrafilter-tower recursion STEP as an object formula.                 *)
(*                                                                         *)
(* Slots: 0=r (prior-values graph / recursion accumulator) 1=y (value at  *)
(* the ordinal) 2=c (candidate element) 3=f 4=B 5=leq 6=bot 7=top 8=xi    *)
(* 9=Fv/F 10=b 11=e 12=h 13=m/hm.                                         *)
(*                                                                         *)
(* ultramem D E f B leq bot top g c : c is in the extended filter at this  *)
(* stage (c=top, or c is above h^e for some h in the prior filter-value    *)
(* Fv=g(xi), where e decides b=f(xi): e=b if b is strongly compatible with *)
(* Fv, else e = the complement of b).  ultrastep_form is the erec step     *)
(* formula: y = { c IN B | ultramem ... c }.                               *)
(* ===================================================================== *)

(* Semantic: strong compatibility of b with the filter-set Fv. *)
let ecompatset = new_definition
  `ecompatset D (E:A->A->bool) B leq bot Fv b <=>
     !h m. h IN D /\ m IN D /\ E h Fv /\ emeet D E B leq h b m ==>
       ~(m = bot)`;;

(* Object formulas.  Slots as documented above. *)
let ultra_compat_form = new_definition
  `ultra_compat_form =
     !!- 12 9 (!! 13 ((bmeet_form 5 4 12 10 13) --> Not(Eq 13 6)))`;;

let ultra_genmem_form = new_definition
  `ultra_genmem_form =
     ??- 12 9 (?? 13 ((bmeet_form 5 4 12 11 13) && (rel_form 5 13 2)))`;;

(* Sub-bridge 1: compatibility. *)
let ECOMPAT_HOLDS = prove
 (`!D (E:A->A->bool) (vv:num->A).
      model D E ZF_AX /\ valuation D vv
      ==> (holds D E vv ultra_compat_form <=>
           ecompatset D E (vv 4) (vv 5) (vv 6) (vv 9) (vv 10))`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[ultra_compat_form; ecompatset] THEN
  ASM_SIMP_TAC[HOLDS_FORALLMEM; ARITH_RULE `~(12 = 9)`] THEN
  SUBGOAL_THEN
   `!h:A. h IN D
      ==> (holds D E ((12|->h)vv)
              (!! 13 ((bmeet_form 5 4 12 10 13) --> Not(Eq 13 6))) <=>
           (!m. m IN D ==> emeet D E (vv 4) (vv 5) h (vv 10) m ==>
            ~(m = vv 6)))`
   (LABEL_TAC "hh") THENL
   [X_GEN_TAC `h:A` THEN DISCH_TAC THEN
    SUBGOAL_THEN `valuation D ((12|->(h:A))vv)` ASSUME_TAC THENL
     [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
    REWRITE_TAC[holds] THEN AP_TERM_TAC THEN ABS_TAC THEN
    ASM_CASES_TAC `(a:A) IN D` THEN ASM_REWRITE_TAC[] THEN
    SUBGOAL_THEN `valuation D ((13|->(a:A))((12|->(h:A))vv))` ASSUME_TAC THENL
     [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
    ASM_SIMP_TAC[HOLDS_NOT; HOLDS_BMEET_FORM] THEN
    REWRITE_TAC[holds] THEN REWRITE_TAC[VALMOD; ARITH_EQ]; ALL_TAC] THEN
  EQ_TAC THEN DISCH_TAC THEN ASM_MESON_TAC[]);;

(* Sub-bridge 2: generated-filter membership. *)
let GENMEM_HOLDS = prove
 (`!D (E:A->A->bool) (vv:num->A).
      model D E ZF_AX /\ valuation D vv
      ==> (holds D E vv ultra_genmem_form <=>
           ?h hm. h IN D /\ hm IN D /\ E h (vv 9) /\
                  emeet D E (vv 4) (vv 5) h (vv 11) hm /\
                  erel D E (vv 5) hm (vv 2))`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[ultra_genmem_form] THEN
  ASM_SIMP_TAC[HOLDS_EXISTSMEM; ARITH_RULE `~(12 = 9)`] THEN
  REWRITE_TAC[HOLDS_EX; HOLDS_AND] THEN
  REWRITE_TAC[RIGHT_AND_EXISTS_THM] THEN
  SUBGOAL_THEN
   `!h hm:A. h IN D /\ hm IN D
      ==> (holds D E ((13|->hm)((12|->h)vv)) (bmeet_form 5 4 12 11 13) <=>
           emeet D E (vv 4) (vv 5) h (vv 11) hm) /\
          (holds D E ((13|->hm)((12|->h)vv)) (rel_form 5 13 2) <=>
           erel D E (vv 5) hm (vv 2))`
   (LABEL_TAC "b") THENL
   [MAP_EVERY X_GEN_TAC [`h:A`;`hm:A`] THEN STRIP_TAC THEN
    SUBGOAL_THEN `valuation D ((13 |-> (hm:A)) ((12 |-> (h:A)) vv))`
      ASSUME_TAC THENL
      [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
    ASM_SIMP_TAC[HOLDS_BMEET_FORM; HOLDS_REL_FORM] THEN
    REWRITE_TAC[VALMOD; ARITH_EQ]; ALL_TAC] THEN
  EQ_TAC THENL
   [DISCH_THEN(X_CHOOSE_THEN `h:A`
               (X_CHOOSE_THEN `hm:A` STRIP_ASSUME_TAC)) THEN
    MAP_EVERY EXISTS_TAC [`h:A`;`hm:A`] THEN ASM_MESON_TAC[];
    DISCH_THEN(X_CHOOSE_THEN `h:A`
               (X_CHOOSE_THEN `hm:A` STRIP_ASSUME_TAC)) THEN
    MAP_EVERY EXISTS_TAC [`h:A`;`hm:A`] THEN ASM_MESON_TAC[]]);;

(* The recursion step body and step formula. *)
let ultrabody_form = new_definition
  `ultrabody_form =
     (2 %% 4) &&
     ((Eq 2 7) ||
      (?? 8 (?? 9 (?? 10 (?? 11 (
         (((apply_form 0 8 9) && (apply_form 3 8 10)) &&
          ((ultra_compat_form && (Eq 11 10)) ||
           ((Not ultra_compat_form) &&
            (((11 %% 4) && (bmeet_form 5 4 10 11 6)) &&
             (bjoin_form 5 4 10 11 7))))) &&
         ultra_genmem_form))))))`;;

let ultrastep_form = new_definition
  `ultrastep_form = !! 2 ((2 %% 1) <-> ultrabody_form)`;;

(* Atomic staged body under binders 8,9,10,11 (xi,Fv,b,e). *)
let ULTRA_ATOM = prove
 (`!D (E:A->A->bool) (vv:num->A) xi Fv b e.
      model D E ZF_AX /\ valuation D vv /\
      xi IN D /\ Fv IN D /\ b IN D /\ e IN D
      ==> (holds D E ((11|->e)((10|->b)((9|->Fv)((8|->xi)vv))))
             ((((apply_form 0 8 9) && (apply_form 3 8 10)) &&
               ((ultra_compat_form && (Eq 11 10)) ||
                ((Not ultra_compat_form) &&
                 (((11 %% 4) && (bmeet_form 5 4 10 11 6)) &&
                  (bjoin_form 5 4 10 11 7))))) &&
              ultra_genmem_form)
           <=>
           eapply D E (vv 0) xi Fv /\ eapply D E (vv 3) xi b /\
           ( (ecompatset D E (vv 4) (vv 5) (vv 6) Fv b /\ e = b) \/
             (~ecompatset D E (vv 4) (vv 5) (vv 6) Fv b /\ E e (vv 4) /\
              emeet D E (vv 4) (vv 5) b e (vv 6) /\
              ejoin D E (vv 4) (vv 5) b e (vv 7)) ) /\
           (?h hm. h IN D /\ hm IN D /\ E h Fv /\
                   emeet D E (vv 4) (vv 5) h e hm /\
                     erel D E (vv 5) hm (vv 2)))`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN
   `valuation D ((11|->e)((10|->b)((9|->Fv)((8|->xi)(vv:num->A)))))`
   ASSUME_TAC THENL
   [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
  ASM_SIMP_TAC[HOLDS_AND; HOLDS_OR; HOLDS_NOT; HOLDS_MEM; HOLDS_APPLY_FORM;
               HOLDS_BMEET_FORM; HOLDS_BJOIN_FORM; ECOMPAT_HOLDS;
               GENMEM_HOLDS] THEN
  REWRITE_TAC[holds] THEN
  REWRITE_TAC[VALMOD; ARITH_EQ] THEN CONV_TAC TAUT);;

(* Semantic recursion-step membership predicate. *)
let ultramem = new_definition
  `ultramem D (E:A->A->bool) f B leq bot top g c <=>
     E c B /\
     ( c = top \/
       ?xi Fv b e. xi IN D /\ Fv IN D /\ b IN D /\ e IN D /\
          eapply D E g xi Fv /\ eapply D E f xi b /\
          ( (ecompatset D E B leq bot Fv b /\ e = b) \/
            (~ecompatset D E B leq bot Fv b /\ E e B /\
             emeet D E B leq b e bot /\ ejoin D E B leq b e top) ) /\
          (?h hm. h IN D /\ hm IN D /\ E h Fv /\
                  emeet D E B leq h e hm /\ erel D E leq hm c) )`;;

(* Flat 4-existential characterization of the staged body. *)
let ULTRA_SECTION = prove
 (`!D (E:A->A->bool) (vv:num->A).
      model D E ZF_AX /\ valuation D vv
      ==> (holds D E vv
             (?? 8 (?? 9 (?? 10 (?? 11 (
               (((apply_form 0 8 9) && (apply_form 3 8 10)) &&
                 ((ultra_compat_form && (Eq 11 10)) ||
                  ((Not ultra_compat_form) &&
                   (((11 %% 4) && (bmeet_form 5 4 10 11 6)) &&
                    (bjoin_form 5 4 10 11 7))))) &&
                ultra_genmem_form)))))
           <=>
           ?xi Fv b e. xi IN D /\ Fv IN D /\ b IN D /\ e IN D /\
              eapply D E (vv 0) xi Fv /\ eapply D E (vv 3) xi b /\
              ( (ecompatset D E (vv 4) (vv 5) (vv 6) Fv b /\ e = b) \/
                (~ecompatset D E (vv 4) (vv 5) (vv 6) Fv b /\ E e (vv 4) /\
                 emeet D E (vv 4) (vv 5) b e (vv 6) /\
                 ejoin D E (vv 4) (vv 5) b e (vv 7)) ) /\
              (?h hm. h IN D /\ hm IN D /\ E h Fv /\
                      emeet D E (vv 4) (vv 5) h e hm /\
                        erel D E (vv 5) hm (vv 2)))`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  REWRITE_TAC[HOLDS_EX] THEN
  EQ_TAC THENL
   [INTRO_TAC "@xi. dxi @Fv. dFv @bb. db @ee. de hb" THEN
    SUBGOAL_THEN
     `eapply D E ((vv:num->A) 0) xi Fv /\ eapply D E (vv 3) xi bb /\
      ( (ecompatset D E (vv 4) (vv 5) (vv 6) Fv bb /\ ee = bb) \/
        (~ecompatset D E (vv 4) (vv 5) (vv 6) Fv bb /\ E ee (vv 4) /\
         emeet D E (vv 4) (vv 5) bb ee (vv 6) /\
         ejoin D E (vv 4) (vv 5) bb ee (vv 7)) ) /\
      (?h hm. h IN D /\ hm IN D /\ E h Fv /\
              emeet D E (vv 4) (vv 5) h ee hm /\ erel D E (vv 5) hm (vv 2))`
     ASSUME_TAC THENL
     [MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`vv:num->A`;
        `xi:A`;`Fv:A`;`bb:A`;`ee:A`] ULTRA_ATOM) THEN
      ASM_REWRITE_TAC[]; ALL_TAC] THEN
    MAP_EVERY EXISTS_TAC [`xi:A`;`Fv:A`;`bb:A`;`ee:A`] THEN ASM_REWRITE_TAC[];
    INTRO_TAC "@xi Fv bb ee. dxi dFv db de ap" THEN
    EXISTS_TAC `xi:A` THEN ASM_REWRITE_TAC[] THEN
    EXISTS_TAC `Fv:A` THEN ASM_REWRITE_TAC[] THEN
    EXISTS_TAC `bb:A` THEN ASM_REWRITE_TAC[] THEN
    EXISTS_TAC `ee:A` THEN ASM_REWRITE_TAC[] THEN
    MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`vv:num->A`;
      `xi:A`;`Fv:A`;`bb:A`;`ee:A`] ULTRA_ATOM) THEN
    ASM_REWRITE_TAC[]]);;

(* Body-level bridge: holds ultrabody_form <=> ultramem ... at slot 2. *)
let ULTRA_BODY = prove
 (`!D (E:A->A->bool) (vv:num->A).
      model D E ZF_AX /\ valuation D vv
      ==> (holds D E vv ultrabody_form <=>
           ultramem D E (vv 3) (vv 4) (vv 5) (vv 6) (vv 7) (vv 0) (vv 2))`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[ultrabody_form] THEN
  ASM_SIMP_TAC[HOLDS_AND; HOLDS_OR; HOLDS_MEM; ULTRA_SECTION] THEN
  REWRITE_TAC[holds; ultramem]);;

(* Step formula bridge: y is the set { c IN B | ultramem ... c }. *)
let ULTRASTEP_HOLDS = prove
 (`!D (E:A->A->bool) (vv:num->A).
      model D E ZF_AX /\ valuation D vv
      ==> (holds D E vv ultrastep_form <=>
           (!c. c IN D
                ==> (E c (vv 1) <=>
                     ultramem D E (vv 3) (vv 4) (vv 5) (vv 6) (vv 7)
                       (vv 0) c)))`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[ultrastep_form] THEN
  ASM_SIMP_TAC[HOLDS_ALL] THEN
  SUBGOAL_THEN
   `!c:A. c IN D
      ==> (holds D E ((2|->c)vv) ((2 %% 1) <-> ultrabody_form) <=>
           (E c (vv 1) <=>
            ultramem D E (vv 3) (vv 4) (vv 5) (vv 6) (vv 7) (vv 0) c))`
   ASSUME_TAC THENL
   [X_GEN_TAC `c:A` THEN DISCH_TAC THEN
    SUBGOAL_THEN `valuation D ((2|->(c:A))vv)` ASSUME_TAC THENL
     [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
    ASM_SIMP_TAC[HOLDS_IFF; HOLDS_MEM; ULTRA_BODY] THEN
    REWRITE_TAC[VALMOD; ARITH_EQ];
    ASM_MESON_TAC[]]);;

(* Membership characterization of the step value w given the holds-hyp. *)
let ULTRASTEP_MEM = prove
 (`!D (E:A->A->bool) v r w.
      model D E ZF_AX /\ valuation D v /\ r IN D /\ w IN D /\
      holds D E ((1|->w)((0|->r)v)) ultrastep_form
      ==> !c. c IN D
              ==> (E c w <=> ultramem D E (v 3) (v 4) (v 5) (v 6) (v 7) r c)`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `valuation D ((1|->(w:A))((0|->(r:A))v))` ASSUME_TAC THENL
   [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`(1|->(w:A))((0|->(r:A))v)`]
        ULTRASTEP_HOLDS) THEN
  ASM_REWRITE_TAC[] THEN
  REWRITE_TAC[VALMOD; ARITH_EQ] THEN
  DISCH_THEN ACCEPT_TAC);;

(* QFUN: the step formula is functional in slot 1 given slot 0. *)
let ULTRASTEP_QFUN = prove
 (`!D (E:A->A->bool) v.
      model D E ZF_AX /\ valuation D v
      ==> (!r w w'. r IN D /\ w IN D /\ w' IN D /\
                    holds D E ((1|->w)((0|->r)v)) ultrastep_form /\
                    holds D E ((1|->w')((0|->r)v)) ultrastep_form
                    ==> w = w')`,
  REPEAT STRIP_TAC THEN
  FIRST_ASSUM(MATCH_MP_TAC o MATCH_MP ZF_EXTENSIONALITY) THEN
  ASM_REWRITE_TAC[] THEN X_GEN_TAC `c:A` THEN DISCH_TAC THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`v:num->A`;`r:A`;`w:A`]
        ULTRASTEP_MEM) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(MP_TAC o SPEC `c:A`) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN SUBST1_TAC THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`v:num->A`;`r:A`;`w':A`]
        ULTRASTEP_MEM) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(MP_TAC o SPEC `c:A`) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN SUBST1_TAC THEN REFL_TAC);;

(* QTOTAL: for every prior-graph r there is a step value y (via Separation). *)
let ULTRASTEP_QTOTAL = prove
 (`!D (E:A->A->bool) v.
      model D E ZF_AX /\ valuation D v
      ==> (!x. x IN D
               ==> ?y. y IN D /\
                       holds D E ((1|->y)((0|->x)v)) ultrastep_form)`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `valuation D ((0|->(x:A))v)` ASSUME_TAC THENL
   [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
  SUBGOAL_THEN `(v:num->A) 4 IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[valuation]; ALL_TAC] THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`] ZF_SEPARATION) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(MP_TAC o ISPECL
    [`ultrabody_form`; `2`; `(0|->(x:A))v`; `(v:num->A) 4`]) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `s:A`
    (CONJUNCTS_THEN2 (LABEL_TAC "sD") (LABEL_TAC "sep"))) THEN
  EXISTS_TAC `s:A` THEN ASM_REWRITE_TAC[] THEN
  SUBGOAL_THEN `valuation D ((1|->(s:A))((0|->(x:A))v))` ASSUME_TAC THENL
   [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
  ASM_SIMP_TAC[ULTRASTEP_HOLDS] THEN
  REWRITE_TAC[VALMOD; ARITH_EQ] THEN
  X_GEN_TAC `c:A` THEN DISCH_TAC THEN
  SUBGOAL_THEN `valuation D ((2|->(c:A))((0|->(x:A))v))` ASSUME_TAC THENL
   [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
  SUBGOAL_THEN
   `holds D E ((2|->(c:A))((0|->(x:A))v)) ultrabody_form <=>
    ultramem D E (v 3) (v 4) (v 5) (v 6) (v 7) (x:A) (c:A)`
   (LABEL_TAC "hb") THENL
   [MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`(2|->(c:A))((0|->(x:A))v)`]
          ULTRA_BODY) THEN
    ASM_REWRITE_TAC[] THEN DISCH_THEN SUBST1_TAC THEN
    REWRITE_TAC[VALMOD; ARITH_EQ]; ALL_TAC] THEN
  SUBGOAL_THEN
   `ultramem D E (v 3) (v 4) (v 5) (v 6) (v 7) (x:A) (c:A) ==> E c (v 4)`
   ASSUME_TAC THENL
   [REWRITE_TAC[ultramem] THEN STRIP_TAC THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  USE_THEN "sep" (MP_TAC o SPEC `c:A`) THEN
  ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[]);;

(* ================= F8-0 U4: erec value existence + membership ========= *)

(* U4a: the erec value F_a exists in D for every ordinal a. *)
let EULTRAREC_EXISTS = prove
 (`!D (E:A->A->bool) v a.
      model D E ZF_AX /\ valuation D v /\ eordinal D E a
      ==> ?y. y IN D /\ erec D E ultrastep_form v a y`,
  REPEAT STRIP_TAC THEN MATCH_MP_TAC EREC_EXISTS THEN
  ASM_REWRITE_TAC[] THEN
  ASM_MESON_TAC[ULTRASTEP_QFUN; ULTRASTEP_QTOTAL]);;

(* U4b: membership characterization of F_a = the erec value at a.
   Reads prior values F_xi from the erecres graph r; F_a = { c IN B :
   ultramem ... r c }. *)
let EULTRAREC_MEM = prove
 (`!D (E:A->A->bool) v a y r.
      model D E ZF_AX /\ valuation D v /\ eordinal D E a /\ y IN D /\
      erec D E ultrastep_form v a y /\ erecres D E ultrastep_form v a r
      ==> !c. c IN D
              ==> (E c y <=>
                   ultramem D E (v 3) (v 4) (v 5) (v 6) (v 7) r c)`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `(r:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[erecres]; ALL_TAC] THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`ultrastep_form`;`v:num->A`;
                 `a:A`;`y:A`;`r:A`] EREC_EQUATION) THEN
  ASM_REWRITE_TAC[] THEN ANTS_TAC THENL
   [ASM_MESON_TAC[ULTRASTEP_QFUN]; ALL_TAC] THEN
  DISCH_TAC THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`v:num->A`;`r:A`;`y:A`]
        ULTRASTEP_MEM) THEN
  ASM_REWRITE_TAC[]);;

(* ================= F8-0 U5a: internal recursion evaluator ============= *)

(* FV of the ultrafilter recursion step is among {0,1,3,4,5,6,7}, all < 14,
   so rec_form ... 14 (with fresh slots 14..18) is capture-free.  Only the
   INCLUSION direction is ever needed; the exact-set version's
   EXTENSION+ARITH_TAC blows up (exponential case split), so we prove the
   one-directional bound by branch-and-solve.                              *)
let FV_ULTRASTEP_LT = prove
 (`!m. m IN FV ultrastep_form ==> m < 14`,
  GEN_TAC THEN
  REWRITE_TAC[ultrastep_form; ultrabody_form; ultra_compat_form;
              ultra_genmem_form; FV; FV_CLAUSES; FV_APPLY_FORM; FV_REL_FORM;
              FV_BMEET_FORM; FV_BJOIN_FORM] THEN
  REWRITE_TAC[IN_INSERT; IN_UNION; IN_DELETE; NOT_IN_EMPTY] THEN
  STRIP_TAC THEN ASM_ARITH_TAC);;

(* The internal recursion evaluator: y is the erec value F_u at ordinal u. *)
let ultraval_form = new_definition
  `ultraval_form = rec_form ultrastep_form 14`;;

let ULTRAVAL_HOLDS = prove
 (`!D (E:A->A->bool) v u y.
      model D E ZF_AX /\ valuation D v /\ u IN D /\ y IN D
      ==> (holds D E ((15 |-> y) ((14 |-> u) v)) ultraval_form <=>
           erec D E ultrastep_form v u y)`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[ultraval_form] THEN
  MP_TAC(CONV_RULE (ONCE_DEPTH_CONV NUM_REDUCE_CONV)
          (ISPECL [`D:A->bool`; `E:A->A->bool`; `v:num->A`; `ultrastep_form`;
                   `14`; `u:A`; `y:A`] HOLDS_REC_FORM)) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[] THEN ACCEPT_TAC FV_ULTRASTEP_LT;
    DISCH_THEN(fun th -> REWRITE_TAC[th])]);;

(* ================= F8-0 U5b: filter / proper-filter bridge =========== *)

(* ---- helper lemmas ---------------------------------------------------- *)
let HOLDS_IMP = prove
 (`!D (E:A->A->bool) v p q.
      holds D E v (p --> q) <=> (holds D E v p ==> holds D E v q)`,
  REWRITE_TAC[holds]);;

let DIRECTED_REORDER = prove
 (`!D Pa Pb R.
     (!a:A. a IN D ==> (!b. b IN D ==> (Pa a /\ Pb b ==> R a b))) <=>
     (!x y. x IN D /\ y IN D /\ Pa x /\ Pb y ==> R x y)`,
  MESON_TAC[]);;

let UPCLOSED_REORDER = prove
 (`!D Pa Pb Rr Q.
     (!a:A. a IN D ==> (!b. b IN D ==> (Pa a /\ Pb b /\ Rr a b ==> Q b))) <=>
     (!x y. x IN D /\ y IN D /\ Pa x /\ Pb y /\ Rr x y ==> Q y)`,
  MESON_TAC[]);;

(* ---- clause bridges: slots 4=B(=p), 5=leq, 6=bot, 15=g ------------- *)

(* subset clause: g SUBSET B *)
let FILT_SUBSET_HOLDS = prove
 (`!D (E:A->A->bool) v.
      model D E ZF_AX /\ valuation D v
      ==> (holds D E v (!!- 30 15 (30 %% 4)) <=> esubset D E (v 15) (v 4))`,
  REPEAT STRIP_TAC THEN
  ASM_SIMP_TAC[HOLDS_FORALLMEM; ARITH_RULE `~(30 = 15)`] THEN
  REWRITE_TAC[esubset] THEN
  REWRITE_TAC[HOLDS_MEM; VALMOD; ARITH_EQ]);;

(* nonempty clause *)
let FILT_NONEMPTY_HOLDS = prove
 (`!D (E:A->A->bool) v.
      model D E ZF_AX /\ valuation D v
      ==> (holds D E v (?? 30 (30 %% 15)) <=> (?x. x IN D /\ E x (v 15)))`,
  REPEAT STRIP_TAC THEN
  REWRITE_TAC[HOLDS_EX; HOLDS_MEM; VALMOD; ARITH_EQ]);;

(* up-closed clause: E x g /\ E y B /\ x <= y ==> E y g *)
let FILT_UPCLOSED_HOLDS = prove
 (`!D (E:A->A->bool) v.
      model D E ZF_AX /\ valuation D v
      ==> (holds D E v
             (!! 30 (!! 31 (((30 %% 15) && ((31 %% 4) && rel_form 5 30 31))
                            --> (31 %% 15)))) <=>
           (!x y. x IN D /\ y IN D /\ E x (v 15) /\ E y (v 4) /\
                  erel D E (v 5) x y ==> E y (v 15)))`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN
   `!a b:A. a IN D /\ b IN D
      ==> (holds D E ((31|->b)((30|->a)v))
             (((30 %% 15) && ((31 %% 4) && rel_form 5 30 31)) -->
              (31 %% 15)) <=>
           (E a (v 15) /\ E b (v 4) /\ erel D E (v 5) a b ==> E b (v 15)))`
   (LABEL_TAC "bodyU") THENL
   [MAP_EVERY X_GEN_TAC [`a:A`;`b:A`] THEN STRIP_TAC THEN
    SUBGOAL_THEN `valuation D ((31|->(b:A))((30|->(a:A))v))` ASSUME_TAC THENL
     [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
    ASM_SIMP_TAC[HOLDS_IMP; HOLDS_AND; HOLDS_MEM; HOLDS_REL_FORM] THEN
    REWRITE_TAC[VALMOD; ARITH_EQ]; ALL_TAC] THEN
  ASM_SIMP_TAC[HOLDS_ALL] THEN REWRITE_TAC[UPCLOSED_REORDER]);;

(* directed clause (= probe13) *)
let FILT_DIRECTED_HOLDS = prove
 (`!D (E:A->A->bool) v.
      model D E ZF_AX /\ valuation D v
      ==> (holds D E v
             (!! 30 (!! 31 (((30 %% 15) && (31 %% 15)) -->
                     (?? 32 ((32 %% 15) &&
                             (rel_form 5 32 30 && rel_form 5 32 31)))))) <=>
           (!x y. x IN D /\ y IN D /\ E x (v 15) /\ E y (v 15)
                  ==> (?z. z IN D /\ E z (v 15) /\
                           erel D E (v 5) z x /\ erel D E (v 5) z y)))`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN
   `!a b:A. a IN D /\ b IN D
      ==> (holds D E ((31|->b)((30|->a)v))
             (((30 %% 15) && (31 %% 15)) -->
              (?? 32 ((32 %% 15) &&
                      (rel_form 5 32 30 && rel_form 5 32 31)))) <=>
           (E a (v 15) /\ E b (v 15) ==>
            ?z. z IN D /\ E z (v 15) /\ erel D E (v 5) z a /\
              erel D E (v 5) z b))`
   (LABEL_TAC "bodyD") THENL
   [MAP_EVERY X_GEN_TAC [`a:A`;`b:A`] THEN STRIP_TAC THEN
    SUBGOAL_THEN `valuation D ((31|->(b:A))((30|->(a:A))v))` ASSUME_TAC THENL
     [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
    SUBGOAL_THEN
     `!d:A. d IN D
        ==> (holds D E ((32|->d)((31|->b)((30|->a)v)))
               ((32 %% 15) && (rel_form 5 32 30 && rel_form 5 32 31)) <=>
             E d (v 15) /\ erel D E (v 5) d a /\ erel D E (v 5) d b)`
     (LABEL_TAC "innerD") THENL
     [X_GEN_TAC `d:A` THEN DISCH_TAC THEN
      SUBGOAL_THEN `valuation D ((32|->(d:A))((31|->(b:A))((30|->(a:A))v)))`
        ASSUME_TAC THENL
        [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
      ASM_SIMP_TAC[HOLDS_AND; HOLDS_MEM; HOLDS_REL_FORM] THEN
      REWRITE_TAC[VALMOD; ARITH_EQ]; ALL_TAC] THEN
    REWRITE_TAC[HOLDS_IMP] THEN
    SUBGOAL_THEN
     `holds D E ((31|->b)((30|->a)v)) ((30 %% 15) && (31 %% 15)) <=>
      E (a:A) (v 15) /\ E (b:A) (v 15)` (LABEL_TAC "ant") THENL
     [ASM_SIMP_TAC[HOLDS_AND; HOLDS_MEM] THEN REWRITE_TAC[VALMOD; ARITH_EQ];
      ALL_TAC] THEN
    SUBGOAL_THEN
     `holds D E ((31|->b)((30|->a)v))
        (?? 32 ((32 %% 15) && (rel_form 5 32 30 && rel_form 5 32 31))) <=>
      (?z:A. z IN D /\ E z (v 15) /\ erel D E (v 5) z a /\ erel D E (v 5) z b)`
     (LABEL_TAC "cons") THENL
     [REWRITE_TAC[HOLDS_EX] THEN MATCH_MP_TAC EXISTS_AND_CONG THEN
      BETA_TAC THEN USE_THEN "innerD" ACCEPT_TAC; ALL_TAC] THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  ASM_SIMP_TAC[HOLDS_ALL] THEN REWRITE_TAC[DIRECTED_REORDER]);;

(* ---- the filter/proper-filter object formulas --------------------- *)
let filter_form = new_definition
  `filter_form =
     (!!- 30 15 (30 %% 4)) &&
     ((?? 30 (30 %% 15)) &&
      ((!! 30 (!! 31 (((30 %% 15) && ((31 %% 4) && rel_form 5 30 31))
                      --> (31 %% 15)))) &&
       (!! 30 (!! 31 (((30 %% 15) && (31 %% 15)) -->
               (?? 32 ((32 %% 15) &&
                       (rel_form 5 32 30 && rel_form 5 32 31))))))))`;;

let properfilter_form = new_definition
  `properfilter_form = filter_form && Not(6 %% 15)`;;

(* ---- assembled bridges -------------------------------------------- *)
let FILTER_HOLDS = prove
 (`!D (E:A->A->bool) v.
      model D E ZF_AX /\ valuation D v
      ==> (holds D E v filter_form <=> efilter D E (v 4) (v 5) (v 15))`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `(v:num->A) 15 IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[valuation]; ALL_TAC] THEN
  REWRITE_TAC[filter_form] THEN
  ASM_SIMP_TAC[HOLDS_AND; FILT_SUBSET_HOLDS; FILT_NONEMPTY_HOLDS;
               FILT_UPCLOSED_HOLDS; FILT_DIRECTED_HOLDS] THEN
  REWRITE_TAC[efilter] THEN ASM_REWRITE_TAC[]);;

let PROPERFILTER_HOLDS = prove
 (`!D (E:A->A->bool) v.
      model D E ZF_AX /\ valuation D v
      ==> (holds D E v properfilter_form <=>
           efilter D E (v 4) (v 5) (v 15) /\ ~(E (v 6) (v 15)))`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[properfilter_form] THEN
  SUBGOAL_THEN `holds D E v (Not(6 %% 15)) <=> ~(E ((v:num->A) 6) (v 15))`
   (LABEL_TAC "prop") THENL
   [REWRITE_TAC[HOLDS_NOT; HOLDS_MEM]; ALL_TAC] THEN
  ASM_SIMP_TAC[HOLDS_AND; FILTER_HOLDS] THEN ASM_REWRITE_TAC[]);;

(* ===================================================================== *)
(* F8-0 lemmas: internal ultrafilter existence over V=L.  Ladder:        *)
(* U5c INV_form/INV_HOLDS; U5d1 ultramem base lemmas; U5d2 UMEM_PROPER;  *)
(* filter destructors; DECISION_UNIQUE; UMEM_DIR_MEET; EULTRAREC_NEST/   *)
(* DECLATER; certificates; EULTRAREC_DIRECTED (capstone); U5D_STEP per-  *)
(* stage proper-filter assembly; EULTRAREC_PROPERFILT induction wrap;    *)
(* DEC_EXISTS + EULTRA_EXISTS + FORCE_ZFC_OVER_VL (F8 endpoint).         *)
(* ===================================================================== *)

(* ---- U5c ---- *)
let INV_form = new_definition
  `INV_form = !! 15 (ultraval_form --> properfilter_form)`;;
let INV_HOLDS = prove
 (`!D (E:A->A->bool) v u.
      model D E ZF_AX /\ valuation D v /\ u IN D
      ==> (holds D E ((14|->u)v) INV_form <=>
           (!y. y IN D /\ erec D E ultrastep_form v u y
                ==> efilter D E (v 4) (v 5) y /\ ~(E (v 6) y)))`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[INV_form] THEN
  SUBGOAL_THEN `valuation D ((14|->(u:A))v)` ASSUME_TAC THENL
   [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
  ASM_SIMP_TAC[HOLDS_ALL] THEN
  SUBGOAL_THEN
   `!y:A. y IN D
      ==> (holds D E ((15|->y)((14|->u)v))
           (ultraval_form --> properfilter_form) <=>
           (erec D E ultrastep_form v u y
            ==> efilter D E (v 4) (v 5) y /\ ~(E (v 6) y)))`
   (LABEL_TAC "pery") THENL
   [X_GEN_TAC `y:A` THEN DISCH_TAC THEN
    SUBGOAL_THEN `valuation D ((15|->(y:A))((14|->(u:A))v))` ASSUME_TAC THENL
     [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
    REWRITE_TAC[HOLDS_IMP] THEN
    ASM_SIMP_TAC[ULTRAVAL_HOLDS] THEN
    SUBGOAL_THEN
     `holds D E ((15|->(y:A))((14|->(u:A))v)) properfilter_form <=>
      efilter D E (v 4) (v 5) y /\ ~(E (v 6) y)`
     ASSUME_TAC THENL
     [ASM_SIMP_TAC[PROPERFILTER_HOLDS] THEN
      REWRITE_TAC[VALMOD; ARITH_EQ]; ALL_TAC] THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  USE_THEN "pery" (fun th -> SIMP_TAC[th]) THEN
  POP_ASSUM_LIST(K ALL_TAC) THEN MESON_TAC[]);;

(* ---- U5d1: base ultramem lemmas ---- *)
let UMEM_SUBSET = prove
 (`!D (E:A->A->bool) f B leq bot top g c.
      ultramem D E f B leq bot top g c ==> E c B`,
  REWRITE_TAC[ultramem] THEN MESON_TAC[]);;

let UMEM_TOP = prove
 (`!D (E:A->A->bool) f B leq bot top g.
      E top B ==> ultramem D E f B leq bot top g top`,
  REWRITE_TAC[ultramem] THEN MESON_TAC[]);;

let UMEM_GRAPH_MONO = prove
 (`!D (E:A->A->bool) f B leq bot top g g' c.
      (!xi Fv. xi IN D /\ Fv IN D /\ eapply D E g xi Fv ==>
       eapply D E g' xi Fv) /\
      ultramem D E f B leq bot top g c
      ==> ultramem D E f B leq bot top g' c`,
  REPEAT GEN_TAC THEN
  DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "mono") (LABEL_TAC "um")) THEN
  REWRITE_TAC[ultramem] THEN CONJ_TAC THENL
   [ASM_MESON_TAC[UMEM_SUBSET];
    USE_THEN "um" (DISJ_CASES_TAC o CONJUNCT2 o REWRITE_RULE[ultramem]) THENL
     [DISJ1_TAC THEN ASM_REWRITE_TAC[];
      DISJ2_TAC THEN
      FIRST_X_ASSUM(X_CHOOSE_THEN `xi:A` (X_CHOOSE_THEN `Fv:A`
        (X_CHOOSE_THEN `b:A` (X_CHOOSE_THEN `e:A` ASSUME_TAC)))) THEN
      MAP_EVERY EXISTS_TAC [`xi:A`;`Fv:A`;`b:A`;`e:A`] THEN
      ASM_REWRITE_TAC[] THEN
      USE_THEN "mono" MATCH_MP_TAC THEN ASM_REWRITE_TAC[]]]);;

let UMEM_UP = prove
 (`!D (E:A->A->bool) f B leq bot top g c c'.
      eporder D E B leq /\ etop D E B leq top /\
      c IN D /\ c' IN D /\ E c' B /\
      ultramem D E f B leq bot top g c /\ erel D E leq c c'
      ==> ultramem D E f B leq bot top g c'`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `(top:A) IN D /\ (E:A->A->bool) top B` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[ETOP_IN]; ALL_TAC] THEN
  REWRITE_TAC[ultramem] THEN CONJ_TAC THENL
   [ASM_REWRITE_TAC[];
    UNDISCH_TAC `ultramem D (E:A->A->bool) f B leq bot top g c` THEN
    REWRITE_TAC[ultramem] THEN
    DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC
                (DISJ_CASES_THEN2 ASSUME_TAC ASSUME_TAC)) THENL
     [DISJ1_TAC THEN ASM_MESON_TAC[EPORDER_ANTISYM; ETOP_GE];
      DISJ2_TAC THEN
      FIRST_X_ASSUM(X_CHOOSE_THEN `xi:A` (X_CHOOSE_THEN `Fv:A`
        (X_CHOOSE_THEN `b:A` (X_CHOOSE_THEN `e:A` (LABEL_TAC "bd"))))) THEN
      USE_THEN "bd"
        (X_CHOOSE_THEN `h:A` (X_CHOOSE_THEN `hm:A` STRIP_ASSUME_TAC)
           o funpow 7 CONJUNCT2) THEN
      MAP_EVERY EXISTS_TAC [`xi:A`;`Fv:A`;`b:A`;`e:A`] THEN
      ASM_REWRITE_TAC[] THEN MAP_EVERY EXISTS_TAC [`h:A`;`hm:A`] THEN
      ASM_REWRITE_TAC[] THEN
      SUBGOAL_THEN `(hm:A) IN D /\ (E:A->A->bool) hm B` STRIP_ASSUME_TAC THENL
       [ASM_MESON_TAC[EMEET_IN]; ALL_TAC] THEN
      MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
        `hm:A`;`c:A`;`c':A`] EPORDER_TRANS) THEN ASM_REWRITE_TAC[]]]);;

(* UMEM_PROPER: if every graph-value Fv is a proper filter and every statement
   b=f(xi) lies in B,
   then bot is not in the extended filter F_a.             *)
let UMEM_PROPER = prove
 (`!D (E:A->A->bool) f B leq bot top g.
      ebalg D E B leq /\ ebot D E B leq bot /\ etop D E B leq top /\
        ~(bot = top) /\
      (!xi b. xi IN D /\ b IN D /\ eapply D E f xi b ==> E b B) /\
      (!xi Fv. xi IN D /\ Fv IN D /\ eapply D E g xi Fv
               ==> efilter D E B leq Fv /\ ~(?z. ebot D E B leq z /\ E z Fv))
      ==> ~(?z. ebot D E B leq z /\ ultramem D E f B leq bot top g z)`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "ba botbot toptop botnetop stmt filt" THEN
  SUBGOAL_THEN `eporder D (E:A->A->bool) B leq` ASSUME_TAC THENL
   [ASM_MESON_TAC[EBALG_IMP_PORDER]; ALL_TAC] THEN
  REWRITE_TAC[NOT_EXISTS_THM] THEN GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `(z:A) IN D /\ (E:A->A->bool) z B` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[EBOT_IN]; ALL_TAC] THEN
  UNDISCH_TAC `ultramem D (E:A->A->bool) f B leq bot top g z` THEN
  REWRITE_TAC[ultramem] THEN
  DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC
              (DISJ_CASES_THEN2 ASSUME_TAC ASSUME_TAC)) THENL
   [ASM_MESON_TAC[EBOT_UNIQUE];
    FIRST_X_ASSUM(X_CHOOSE_THEN `xi:A` (X_CHOOSE_THEN `Fv:A`
      (X_CHOOSE_THEN `b:A` (X_CHOOSE_THEN `e:A` (LABEL_TAC "bd"))))) THEN
    USE_THEN "bd" (ASSUME_TAC o CONJUNCT1) THEN
    USE_THEN "bd" (ASSUME_TAC o CONJUNCT1 o CONJUNCT2) THEN
    USE_THEN "bd" (ASSUME_TAC o CONJUNCT1 o funpow 2 CONJUNCT2) THEN
    USE_THEN "bd" (ASSUME_TAC o CONJUNCT1 o funpow 3 CONJUNCT2) THEN
    USE_THEN "bd" (ASSUME_TAC o CONJUNCT1 o funpow 4 CONJUNCT2) THEN
    USE_THEN "bd" (ASSUME_TAC o CONJUNCT1 o funpow 5 CONJUNCT2) THEN
    USE_THEN "bd" (X_CHOOSE_THEN `h:A` (X_CHOOSE_THEN `hm:A` STRIP_ASSUME_TAC)
                     o funpow 7 CONJUNCT2) THEN
    SUBGOAL_THEN `(E:A->A->bool) (b:A) B` ASSUME_TAC THENL
     [USE_THEN "stmt" (MATCH_MP_TAC o SPECL [`xi:A`;`b:A`]) THEN
      ASM_REWRITE_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN `efilter D (E:A->A->bool) B leq Fv /\
                  ~(?z. ebot D E B leq z /\ E z Fv)` STRIP_ASSUME_TAC THENL
     [USE_THEN "filt" (MATCH_MP_TAC o SPECL [`xi:A`;`Fv:A`]) THEN
      ASM_REWRITE_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN `(hm:A) IN D /\ (E:A->A->bool) hm B` STRIP_ASSUME_TAC THENL
     [ASM_MESON_TAC[EMEET_IN]; ALL_TAC] THEN
    SUBGOAL_THEN `ebot D (E:A->A->bool) B leq hm` ASSUME_TAC THENL
     [SUBGOAL_THEN `hm:A = z` SUBST1_TAC THENL
       [MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
                            `hm:A`;`z:A`]
                     EPORDER_ANTISYM) THEN ASM_REWRITE_TAC[] THEN
        MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
                            `z:A`;`hm:A`]
                     EBOT_LE) THEN ASM_REWRITE_TAC[];
        ASM_REWRITE_TAC[]]; ALL_TAC] THEN
    USE_THEN "bd" (DISJ_CASES_THEN2
      (CONJUNCTS_THEN2 (LABEL_TAC "compat") SUBST_ALL_TAC)
      STRIP_ASSUME_TAC o CONJUNCT1 o funpow 6 CONJUNCT2) THENL
     [SUBGOAL_THEN `~(hm:A = bot)` ASSUME_TAC THENL
       [REMOVE_THEN "compat" (MP_TAC o REWRITE_RULE[ecompatset]) THEN
        DISCH_THEN(MATCH_MP_TAC o SPECL [`h:A`;`hm:A`]) THEN ASM_REWRITE_TAC[];
        ALL_TAC] THEN
      SUBGOAL_THEN `hm:A = bot` ASSUME_TAC THENL
       [MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
                            `hm:A`;`bot:A`]
                     EBOT_UNIQUE) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
      UNDISCH_TAC `~(hm:A = bot)` THEN ASM_REWRITE_TAC[];
      SUBGOAL_THEN `ecompl D (E:A->A->bool) B leq b e` ASSUME_TAC THENL
       [REWRITE_TAC[ecompl] THEN ASM_REWRITE_TAC[] THEN
        MAP_EVERY EXISTS_TAC [`bot:A`;`top:A`] THEN ASM_REWRITE_TAC[];
        ALL_TAC] THEN
      MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`Fv:A`;
                    `b:A`;`e:A`;
                    `bot:A`] FILTER_COMPAT_SPLIT_STRONG) THEN
      ASM_REWRITE_TAC[] THEN
      DISCH_THEN(DISJ_CASES_THEN2 (LABEL_TAC "d1") (LABEL_TAC "d2")) THENL
       [SUBGOAL_THEN `ecompatset D (E:A->A->bool) B leq bot Fv b`
        ASSUME_TAC THENL
        [REWRITE_TAC[ecompatset] THEN MAP_EVERY X_GEN_TAC [`ff:A`;`mm:A`] THEN
          STRIP_TAC THEN
          SUBGOAL_THEN `~(ebot D (E:A->A->bool) B leq mm)` MP_TAC THENL
           [USE_THEN "d1" (MATCH_MP_TAC o SPECL [`ff:A`;`mm:A`]) THEN
            ASM_REWRITE_TAC[]; ALL_TAC] THEN
          MATCH_MP_TAC(TAUT `(b ==> a) ==> (~a ==> ~b)`) THEN
          DISCH_THEN SUBST1_TAC THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
        UNDISCH_TAC `~ecompatset D (E:A->A->bool) B leq bot Fv b` THEN
        ASM_REWRITE_TAC[];
        REMOVE_THEN "d2" (MP_TAC o SPECL [`h:A`;`hm:A`]) THEN
        ASM_REWRITE_TAC[]]]]);;

(* filter elements lie in the carrier B.  Drive the esubset clause explicitly;
   ASM_MESON over the unfolded efilter (directed/upward quantifiers) blows the
   MESON depth limit ("solve_goal: Too deep").                              *)
let EFILTER_SUB = prove
 (`!D (E:A->A->bool) B leq g w.
      efilter D E B leq g /\ w IN D /\ E w g ==> E w B`,
  REPEAT GEN_TAC THEN REWRITE_TAC[efilter; esubset] THEN
  STRIP_TAC THEN FIRST_X_ASSUM MATCH_MP_TAC THEN ASM_REWRITE_TAC[]);;

(* Filters are closed under binary meet: x,y IN g /\ x^y=m ==> m IN g.
   directed gives z<=x,z<=y in g; EMEET_GREATEST z<=m; upward-closed m IN g. *)
let EFILTER_MEET_CLOSED = prove
 (`!D (E:A->A->bool) B leq g x y m.
      eporder D E B leq /\ efilter D E B leq g /\
      x IN D /\ y IN D /\ E x g /\ E y g /\ emeet D E B leq x y m
      ==> E m g`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `(m:A) IN D /\ (E:A->A->bool) m B` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[EMEET_IN]; ALL_TAC] THEN
  UNDISCH_TAC `efilter D (E:A->A->bool) B leq g` THEN
  REWRITE_TAC[efilter; esubset] THEN
  DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "gd")
    (CONJUNCTS_THEN2 (LABEL_TAC "sub")
     (CONJUNCTS_THEN2 (K ALL_TAC)
      (CONJUNCTS_THEN2 (LABEL_TAC "up") (LABEL_TAC "dir"))))) THEN
  SUBGOAL_THEN `?z:A. z IN D /\ E z g /\ erel D E leq z x /\ erel D E leq z y`
    STRIP_ASSUME_TAC THENL
   [USE_THEN "dir" MATCH_MP_TAC THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) z B` ASSUME_TAC THENL
   [USE_THEN "sub" MATCH_MP_TAC THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq z m` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`x:A`;`y:A`;
                        `m:A`;`z:A`]
                 EMEET_GREATEST) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  USE_THEN "up" MATCH_MP_TAC THEN EXISTS_TAC `z:A` THEN ASM_REWRITE_TAC[]);;

(* top is in every filter (nonempty + upward-closed).  Take any x IN g (from
   the nonempty clause), then x<=top (ETOP_GE) and upward-closure give top. *)
let EFILTER_TOP = prove
 (`!D (E:A->A->bool) B leq top g.
      eporder D E B leq /\ etop D E B leq top /\ efilter D E B leq g
      ==> E top g`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `(top:A) IN D /\ (E:A->A->bool) top B` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[ETOP_IN]; ALL_TAC] THEN
  UNDISCH_TAC `efilter D (E:A->A->bool) B leq g` THEN
  REWRITE_TAC[efilter; esubset] THEN
  DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "gd")
    (CONJUNCTS_THEN2 (LABEL_TAC "sub")
     (CONJUNCTS_THEN2 (X_CHOOSE_THEN `x0:A` STRIP_ASSUME_TAC)
      (CONJUNCTS_THEN2 (LABEL_TAC "up") (LABEL_TAC "dir"))))) THEN
  SUBGOAL_THEN `(E:A->A->bool) x0 B` ASSUME_TAC THENL
   [USE_THEN "sub" MATCH_MP_TAC THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq x0 top` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
                        `top:A`;`x0:A`]
                 ETOP_GE) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  USE_THEN "up" MATCH_MP_TAC THEN EXISTS_TAC `x0:A` THEN ASM_REWRITE_TAC[]);;

(* Decisions at a stage are unique: compat -> both = b; else both = compl b. *)
let DECISION_UNIQUE = prove
 (`!D (E:A->A->bool) B leq bot top Fv b e e'.
      ebalg D E B leq /\ ebot D E B leq bot /\ etop D E B leq top /\
      b IN D /\ E b B /\ e IN D /\ e' IN D /\
      ( (ecompatset D E B leq bot Fv b /\ e = b) \/
        (~ecompatset D E B leq bot Fv b /\ E e B /\
         emeet D E B leq b e bot /\ ejoin D E B leq b e top) ) /\
      ( (ecompatset D E B leq bot Fv b /\ e' = b) \/
        (~ecompatset D E B leq bot Fv b /\ E e' B /\
         emeet D E B leq b e' bot /\ ejoin D E B leq b e' top) )
      ==> e = e'`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN TRY(ASM_MESON_TAC[]) THEN
  MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`b:A`;
                      `e:A`;`e':A`]
               ECOMPL_UNIQUE) THEN
  ASM_REWRITE_TAC[] THEN CONJ_TAC THEN
  REWRITE_TAC[ecompl] THEN ASM_REWRITE_TAC[] THEN
  MAP_EVERY EXISTS_TAC [`bot:A`;`top:A`] THEN ASM_REWRITE_TAC[]);;

(* Pure directedness core, SYMMETRIC form.  Both c1,c2 dominate an element of
   the form (something IN Fv2) ^ e2, where e2 is stage xi2's decision.  Common
   lower bound c3 = (w1^h2)^e2 IN F_a via stage xi2, with c3<=c1 and c3<=c2.
   The erec layer supplies w1 (c1 lifted into Fv2: for a smaller stage xi1<xi2,
   w1=h1^e1 IN Fv2 by nesting+declater; for xi1=xi2, w1=h1 IN Fv2). *)
let UMEM_DIR_MEET = prove
 (`!D (E:A->A->bool) f B leq bot top g xi2 Fv2 b2 e2 c1 c2 w1 m1 h2 hm2.
      ebalg D E B leq /\
      c1 IN D /\ E c1 B /\ c2 IN D /\ E c2 B /\
      xi2 IN D /\ Fv2 IN D /\ b2 IN D /\ e2 IN D /\ E e2 B /\
      eapply D E g xi2 Fv2 /\ eapply D E f xi2 b2 /\
      efilter D E B leq Fv2 /\
      ( (ecompatset D E B leq bot Fv2 b2 /\ e2 = b2) \/
        (~ecompatset D E B leq bot Fv2 b2 /\ E e2 B /\
         emeet D E B leq b2 e2 bot /\ ejoin D E B leq b2 e2 top) ) /\
      w1 IN D /\ E w1 Fv2 /\ emeet D E B leq w1 e2 m1 /\ erel D E leq m1 c1 /\
      h2 IN D /\ E h2 Fv2 /\ emeet D E B leq h2 e2 hm2 /\ erel D E leq hm2 c2
      ==> ?c3. c3 IN D /\ ultramem D E f B leq bot top g c3 /\
               erel D E leq c3 c1 /\ erel D E leq c3 c2`,
  REPEAT GEN_TAC THEN REWRITE_TAC[IMP_CONJ] THEN REPEAT DISCH_TAC THEN
  SUBGOAL_THEN `eporder D (E:A->A->bool) B leq` ASSUME_TAC THENL
   [ASM_MESON_TAC[EBALG_IMP_PORDER]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) w1 B /\ (E:A->A->bool) h2 B`
    STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[EFILTER_SUB]; ALL_TAC] THEN
  (* H = w1 ^ h2 IN Fv2 *)
  SUBGOAL_THEN `?H. emeet D (E:A->A->bool) B leq w1 h2 H`
    (X_CHOOSE_TAC `H:A`) THENL
   [ASM_MESON_TAC[EBALG_MEET]; ALL_TAC] THEN
  SUBGOAL_THEN `(H:A) IN D /\ (E:A->A->bool) H B` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[EMEET_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) H Fv2` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`Fv2:A`;
                        `w1:A`;`h2:A`;`H:A`]
                 EFILTER_MEET_CLOSED) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* c3 = H ^ e2 *)
  SUBGOAL_THEN `?c3. emeet D (E:A->A->bool) B leq H e2 c3`
    (X_CHOOSE_TAC `c3:A`) THENL
   [ASM_MESON_TAC[EBALG_MEET]; ALL_TAC] THEN
  SUBGOAL_THEN `(c3:A) IN D /\ (E:A->A->bool) c3 B` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[EMEET_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `(m1:A) IN D /\ (E:A->A->bool) m1 B` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[EMEET_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `(hm2:A) IN D /\ (E:A->A->bool) hm2 B` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[EMEET_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq c3 H /\ erel D E leq c3 e2`
    STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[EMEET_LE]; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq H w1 /\ erel D E leq H h2`
    STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[EMEET_LE]; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq c3 w1` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`c3:A`;
                        `H:A`;`w1:A`]
                 EPORDER_TRANS) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq c3 h2` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`c3:A`;
                        `H:A`;`h2:A`]
                 EPORDER_TRANS) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* c3 <= m1 = w1^e2 and c3 <= hm2 = h2^e2 *)
  SUBGOAL_THEN `erel D (E:A->A->bool) leq c3 m1` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`w1:A`;`e2:A`;
                        `m1:A`;`c3:A`]
                 EMEET_GREATEST) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq c3 hm2` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`h2:A`;`e2:A`;
                        `hm2:A`;`c3:A`]
                 EMEET_GREATEST) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* c3 <= c1, c3 <= c2 *)
  SUBGOAL_THEN `erel D (E:A->A->bool) leq c3 c1` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`c3:A`;
                        `m1:A`;`c1:A`]
                 EPORDER_TRANS) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq c3 c2` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`c3:A`;
                        `hm2:A`;`c2:A`]
                 EPORDER_TRANS) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  EXISTS_TAC `c3:A` THEN REPEAT CONJ_TAC THENL
   [ASM_REWRITE_TAC[];
    REWRITE_TAC[ultramem] THEN CONJ_TAC THENL
     [ASM_REWRITE_TAC[];
      DISJ2_TAC THEN
      MAP_EVERY EXISTS_TAC [`xi2:A`;`Fv2:A`;`b2:A`;`e2:A`] THEN
      ASM_REWRITE_TAC[] THEN
      MAP_EVERY EXISTS_TAC [`H:A`;`c3:A`] THEN ASM_REWRITE_TAC[] THEN
      MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`c3:A`]
                   EPORDER_REFL) THEN
      ASM_REWRITE_TAC[]];
    ASM_REWRITE_TAC[];
    ASM_REWRITE_TAC[]]);;

(* NESTING: for xi1 < xi2 (xi2 an ordinal), F_xi1 SUBSET F_xi2, stated on
   explicit erec values y1,y2.  Graphs r1,r2 agree on {b : E b xi1} via
   ERECRES_APPLY, so UMEM_GRAPH_MONO transfers membership. *)
let EULTRAREC_NEST = prove
 (`!D (E:A->A->bool) v xi1 xi2 c y1 y2.
     model D E ZF_AX /\ valuation D v /\
     eordinal D E xi2 /\ xi1 IN D /\ E xi1 xi2 /\ c IN D /\
     y1 IN D /\ erec D E ultrastep_form v xi1 y1 /\ E c y1 /\
     y2 IN D /\ erec D E ultrastep_form v xi2 y2
     ==> E c y2`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `eordinal D (E:A->A->bool) xi1` ASSUME_TAC THENL
   [ASM_MESON_TAC[EORDINAL_MEMBER]; ALL_TAC] THEN
  SUBGOAL_THEN
   `!r w w'. r IN D /\ w IN D /\ w' IN D /\
             holds D (E:A->A->bool) ((1|->w)((0|->r)v)) ultrastep_form /\
             holds D E ((1|->w')((0|->r)v)) ultrastep_form ==> w = w'`
   (LABEL_TAC "qfun") THENL [ASM_MESON_TAC[ULTRASTEP_QFUN]; ALL_TAC] THEN
  SUBGOAL_THEN
   `!x. x IN D ==> ?y. y IN D /\
                       holds D (E:A->A->bool) ((1|->y)((0|->x)v))
                         ultrastep_form`
   (LABEL_TAC "qtot") THENL [ASM_MESON_TAC[ULTRASTEP_QTOTAL]; ALL_TAC] THEN
  SUBGOAL_THEN `?r1. erecres D (E:A->A->bool) ultrastep_form v xi1 r1`
    STRIP_ASSUME_TAC THENL
   [MATCH_MP_TAC ERECRES_EXISTS THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `?r2. erecres D (E:A->A->bool) ultrastep_form v xi2 r2`
    STRIP_ASSUME_TAC THENL
   [MATCH_MP_TAC ERECRES_EXISTS THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(r1:A) IN D /\ (r2:A) IN D` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[erecres]; ALL_TAC] THEN
  SUBGOAL_THEN `ultramem D E ((v:num->A) 3) (v 4) (v 5) (v 6) (v 7) r1 c`
    ASSUME_TAC THENL
   [MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`v:num->A`;`xi1:A`;`y1:A`;`r1:A`]
          EULTRAREC_MEM) THEN ASM_REWRITE_TAC[] THEN
    DISCH_THEN(MP_TAC o SPEC `c:A`) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`v:num->A`;`xi2:A`;`y2:A`;`r2:A`]
        EULTRAREC_MEM) THEN ASM_REWRITE_TAC[] THEN
  DISCH_THEN(MP_TAC o SPEC `c:A`) THEN ASM_REWRITE_TAC[] THEN
  DISCH_THEN SUBST1_TAC THEN
  MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`(v:num->A) 3`;`(v:num->A) 4`;
     `(v:num->A) 5`;`(v:num->A) 6`;`(v:num->A) 7`;`r1:A`;`r2:A`;`c:A`]
          UMEM_GRAPH_MONO) THEN
  ASM_REWRITE_TAC[] THEN
  MAP_EVERY X_GEN_TAC [`bb:A`;`Fbb:A`] THEN STRIP_TAC THEN
  SUBGOAL_THEN `E (bb:A) xi1 /\ erec D E ultrastep_form v bb Fbb`
    STRIP_ASSUME_TAC THENL
   [MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`ultrastep_form`;`v:num->A`;
                  `xi1:A`;`r1:A`;
                  `bb:A`;`Fbb:A`] ERECRES_APPLY) THEN ASM_REWRITE_TAC[] THEN
          ASM_MESON_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) (bb:A) (xi2:A)` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`xi2:A`;`xi1:A`;`bb:A`]
       EORDINAL_TRANS_MEM) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`ultrastep_form`;`v:num->A`;
                `xi2:A`;`r2:A`;
                `bb:A`;`Fbb:A`] ERECRES_APPLY) THEN ASM_REWRITE_TAC[] THEN
  ASM_MESON_TAC[]);;

(* DECLATER: the stage-xi1 decision e1 lands in F_xi2 for xi1 < xi2.
   Witness at stage xi1 in F_xi2's generator, with h = top (top^e1 = e1). *)
let EULTRAREC_DECLATER = prove
 (`!D (E:A->A->bool) v xi1 xi2 Fv1 b1 e1 y2 r2.
     model D E ZF_AX /\ valuation D v /\
     ebalg D E (v 4) (v 5) /\ etop D E (v 4) (v 5) (v 7) /\
     eordinal D E xi2 /\ E xi1 xi2 /\ xi1 IN D /\
     erec D E ultrastep_form v xi1 Fv1 /\ Fv1 IN D /\
     efilter D E (v 4) (v 5) Fv1 /\
     b1 IN D /\ eapply D E (v 3) xi1 b1 /\
     e1 IN D /\ E e1 (v 4) /\
     ( (ecompatset D E (v 4) (v 5) (v 6) Fv1 b1 /\ e1 = b1) \/
       (~ecompatset D E (v 4) (v 5) (v 6) Fv1 b1 /\ E e1 (v 4) /\
        emeet D E (v 4) (v 5) b1 e1 (v 6) /\
          ejoin D E (v 4) (v 5) b1 e1 (v 7)) ) /\
     y2 IN D /\ erec D E ultrastep_form v xi2 y2 /\
     erecres D E ultrastep_form v xi2 r2
     ==> E e1 y2`,
  REPEAT GEN_TAC THEN REWRITE_TAC[IMP_CONJ] THEN REPEAT DISCH_TAC THEN
  SUBGOAL_THEN `eporder D (E:A->A->bool) (v 4) (v 5)` ASSUME_TAC THENL
   [ASM_MESON_TAC[EBALG_IMP_PORDER]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) ((v:num->A) 7) (Fv1:A)` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`(v:num->A) 4`;
                        `(v:num->A) 5`;
                        `(v:num->A) 7`;`Fv1:A`] EFILTER_TOP) THEN
     ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `((v:num->A) 7) IN D /\ E ((v:num->A) 7) (v 4)`
    STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[ETOP_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `emeet D (E:A->A->bool) (v 4) (v 5) (v 7) e1 e1`
    ASSUME_TAC THENL
   [MATCH_MP_TAC EMEET_SYM THEN
    MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`(v:num->A) 4`;
                        `(v:num->A) 5`;
                        `(v:num->A) 7`;`e1:A`] EMEET_TOP) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) (v 5) e1 e1` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`(v:num->A) 4`;
                        `(v:num->A) 5`;`e1:A`]
                 EPORDER_REFL) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `eapply D (E:A->A->bool) r2 xi1 Fv1` ASSUME_TAC THENL
   [MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`ultrastep_form`;`v:num->A`;
                  `xi2:A`;`r2:A`;
                  `xi1:A`;`Fv1:A`] ERECRES_APPLY) THEN ASM_REWRITE_TAC[] THEN
    ASM_MESON_TAC[]; ALL_TAC] THEN
  MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`v:num->A`;`xi2:A`;`y2:A`;`r2:A`]
        EULTRAREC_MEM) THEN ASM_REWRITE_TAC[] THEN
  DISCH_THEN(MP_TAC o SPEC `e1:A`) THEN ASM_REWRITE_TAC[] THEN
  DISCH_THEN SUBST1_TAC THEN
  REWRITE_TAC[ultramem] THEN CONJ_TAC THENL
   [ASM_REWRITE_TAC[];
    DISJ2_TAC THEN
    MAP_EVERY EXISTS_TAC [`xi1:A`;`Fv1:A`;`b1:A`;`e1:A`] THEN
    ASM_REWRITE_TAC[] THEN
    MAP_EVERY EXISTS_TAC [`(v:num->A) 7`;`e1:A`] THEN ASM_REWRITE_TAC[]]);;

(* Decision lies in the carrier (from the DEC disjunction + E b B). *)
let DEC_IN_CARRIER = prove
 (`!D (E:A->A->bool) B leq bot top Fv b e.
      b IN D /\ E b B /\
      ( (ecompatset D E B leq bot Fv b /\ e = b) \/
        (~ecompatset D E B leq bot Fv b /\ E e B /\
         emeet D E B leq b e bot /\ ejoin D E B leq b e top) )
      ==> E e B`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN ASM_REWRITE_TAC[]);;

(* Certificate for cX = top at a host stage with filter Fv and decision e:
   w:=top IN Fv, m:=e=top^e, and m <= top. *)
let UMEM_CERT_TOP = prove
 (`!D (E:A->A->bool) B leq top Fv e.
      eporder D E B leq /\ etop D E B leq top /\ efilter D E B leq Fv /\
      e IN D /\ E e B
      ==> ?w m. w IN D /\ m IN D /\ E m B /\ E w Fv /\
                emeet D E B leq w e m /\ erel D E leq m top`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `(top:A) IN D /\ (E:A->A->bool) top B` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[ETOP_IN]; ALL_TAC] THEN
  MAP_EVERY EXISTS_TAC [`top:A`;`e:A`] THEN ASM_REWRITE_TAC[] THEN
  REPEAT CONJ_TAC THENL
   [MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
                        `top:A`;`Fv:A`]
                 EFILTER_TOP) THEN ASM_REWRITE_TAC[];
    MATCH_MP_TAC EMEET_SYM THEN
    MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`top:A`;`e:A`]
       EMEET_TOP) THEN ASM_REWRITE_TAC[];
    MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`top:A`;`e:A`]
       ETOP_GE) THEN ASM_REWRITE_TAC[]]);;

(* Certificate for cX coming from an EARLIER stage xi1 < xi2, at host stage
   xi2 with filter Fv2 and decision e2: w:=hm1=h1^e1 IN Fv2 (nesting for h1,
   declater for e1, meet-closure), m:=hm1^e2 <= hm1 (<= cX at call site). *)
let UMEM_CERT_EARLIER = prove
 (`!D (E:A->A->bool) v xi1 xi2 Fv1 Fv2 b1 e1 h1 hm1 e2.
     model D E ZF_AX /\ valuation D v /\
     ebalg D E (v 4) (v 5) /\ etop D E (v 4) (v 5) (v 7) /\
     eordinal D E xi2 /\ xi1 IN D /\ E xi1 xi2 /\
     Fv1 IN D /\ erec D E ultrastep_form v xi1 Fv1 /\
       efilter D E (v 4) (v 5) Fv1 /\
     Fv2 IN D /\ erec D E ultrastep_form v xi2 Fv2 /\
       efilter D E (v 4) (v 5) Fv2 /\
     b1 IN D /\ eapply D E (v 3) xi1 b1 /\
     e1 IN D /\ E e1 (v 4) /\
     ( (ecompatset D E (v 4) (v 5) (v 6) Fv1 b1 /\ e1 = b1) \/
       (~ecompatset D E (v 4) (v 5) (v 6) Fv1 b1 /\ E e1 (v 4) /\
        emeet D E (v 4) (v 5) b1 e1 (v 6) /\
          ejoin D E (v 4) (v 5) b1 e1 (v 7)) ) /\
     h1 IN D /\ E h1 Fv1 /\ emeet D E (v 4) (v 5) h1 e1 hm1 /\
     e2 IN D /\ E e2 (v 4)
     ==> ?w m. w IN D /\ m IN D /\ E m (v 4) /\ E w Fv2 /\
               emeet D E (v 4) (v 5) w e2 m /\ erel D E (v 5) m hm1`,
  REPEAT GEN_TAC THEN REWRITE_TAC[IMP_CONJ] THEN REPEAT DISCH_TAC THEN
  SUBGOAL_THEN `eporder D (E:A->A->bool) (v 4) (v 5)` ASSUME_TAC THENL
   [ASM_MESON_TAC[EBALG_IMP_PORDER]; ALL_TAC] THEN
  SUBGOAL_THEN
   `!r w w'. r IN D /\ w IN D /\ w' IN D /\
             holds D (E:A->A->bool) ((1|->w)((0|->r)v)) ultrastep_form /\
             holds D E ((1|->w')((0|->r)v)) ultrastep_form ==> w = w'`
   (LABEL_TAC "qfun") THENL [ASM_MESON_TAC[ULTRASTEP_QFUN]; ALL_TAC] THEN
  SUBGOAL_THEN
   `!x. x IN D ==> ?y. y IN D /\
                       holds D (E:A->A->bool) ((1|->y)((0|->x)v))
                         ultrastep_form`
   (LABEL_TAC "qtot") THENL [ASM_MESON_TAC[ULTRASTEP_QTOTAL]; ALL_TAC] THEN
  SUBGOAL_THEN `?r2. erecres D (E:A->A->bool) ultrastep_form v xi2 r2`
    STRIP_ASSUME_TAC THENL
   [MATCH_MP_TAC ERECRES_EXISTS THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(hm1:A) IN D /\ (E:A->A->bool) hm1 (v 4)`
    STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[EMEET_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) h1 Fv2` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`v:num->A`;`xi1:A`;`xi2:A`;
       `h1:A`;`Fv1:A`;`Fv2:A`] EULTRAREC_NEST) THEN ASM_REWRITE_TAC[];
                         ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) e1 Fv2` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`v:num->A`;`xi1:A`;`xi2:A`;
       `Fv1:A`;`b1:A`;`e1:A`;`Fv2:A`;`r2:A`] EULTRAREC_DECLATER) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) hm1 Fv2` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`(v:num->A) 4`;
                        `(v:num->A) 5`;
                        `Fv2:A`;`h1:A`;`e1:A`;`hm1:A`]
         EFILTER_MEET_CLOSED) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `?m. emeet D (E:A->A->bool) (v 4) (v 5) hm1 e2 m`
    (X_CHOOSE_TAC `m:A`) THENL
   [ASM_MESON_TAC[EBALG_MEET]; ALL_TAC] THEN
  SUBGOAL_THEN `(m:A) IN D /\ (E:A->A->bool) m (v 4)` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[EMEET_IN]; ALL_TAC] THEN
  MAP_EVERY EXISTS_TAC [`hm1:A`;`m:A`] THEN ASM_REWRITE_TAC[] THEN
  ASM_MESON_TAC[EMEET_LE]);;

(* Capstone: F_a is directed, given that all earlier-stage values F_xi are
   filters (IH), the enumeration f=(v3) is B-valued and functional, and the
   BA slots are ebalg(v4)(v5)/ebot(v6)/etop(v7).  Case split: c=top vs
   generator for each of c1,c2, then ordinal trichotomy on the two stages;
   every nontrivial case ends via UMEM_DIR_MEET at the later ("host") stage
   with a (w,m) certificate for the other element (UMEM_CERT_TOP /
   same-stage witness / UMEM_CERT_EARLIER).                                *)
let EULTRAREC_DIRECTED = prove
 (`!D (E:A->A->bool) v a y r c1 c2.
     model D E ZF_AX /\ valuation D v /\
     ebalg D E (v 4) (v 5) /\ ebot D E (v 4) (v 5) (v 6) /\
     etop D E (v 4) (v 5) (v 7) /\
     (!xi b. xi IN D /\ b IN D /\ eapply D E (v 3) xi b ==> E b (v 4)) /\
     (!xi b b'. xi IN D /\ b IN D /\ b' IN D /\ eapply D E (v 3) xi b /\
                eapply D E (v 3) xi b' ==> b = b') /\
     eordinal D E a /\
     (!xi y0. xi IN D /\ E xi a /\ y0 IN D /\ erec D E ultrastep_form v xi y0
              ==> efilter D E (v 4) (v 5) y0) /\
     y IN D /\ erec D E ultrastep_form v a y /\
     erecres D E ultrastep_form v a r /\
     c1 IN D /\ E c1 y /\ c2 IN D /\ E c2 y
     ==> ?c3. c3 IN D /\ E c3 y /\ erel D E (v 5) c3 c1 /\
       erel D E (v 5) c3 c2`,
  REPEAT GEN_TAC THEN
  DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC
   (CONJUNCTS_THEN2 ASSUME_TAC
    (CONJUNCTS_THEN2 ASSUME_TAC
     (CONJUNCTS_THEN2 ASSUME_TAC
      (CONJUNCTS_THEN2 ASSUME_TAC
       (CONJUNCTS_THEN2 (LABEL_TAC "frange")
        (CONJUNCTS_THEN2 (LABEL_TAC "ffun")
         (CONJUNCTS_THEN2 ASSUME_TAC
          (CONJUNCTS_THEN2 (LABEL_TAC "ih")
           STRIP_ASSUME_TAC))))))))) THEN
  SUBGOAL_THEN `eporder D (E:A->A->bool) ((v:num->A) 4) (v 5)` ASSUME_TAC THENL
   [ASM_MESON_TAC[EBALG_IMP_PORDER]; ALL_TAC] THEN
  SUBGOAL_THEN
   `!rr w w'. rr IN D /\ w IN D /\ w' IN D /\
              holds D (E:A->A->bool) ((1|->w)((0|->rr)v)) ultrastep_form /\
              holds D E ((1|->w')((0|->rr)v)) ultrastep_form ==> w = w'`
   (LABEL_TAC "qfun") THENL [ASM_MESON_TAC[ULTRASTEP_QFUN]; ALL_TAC] THEN
  SUBGOAL_THEN `((v:num->A) 7) IN D /\ (E:A->A->bool) (v 7) (v 4)`
    STRIP_ASSUME_TAC THENL [ASM_MESON_TAC[ETOP_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `(r:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[erecres]; ALL_TAC] THEN
  MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`v:num->A`;`a:A`;`y:A`;`r:A`]
        EULTRAREC_MEM) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(LABEL_TAC "memiff") THEN
  SUBGOAL_THEN
    `ultramem D (E:A->A->bool) ((v:num->A) 3) (v 4) (v 5) (v 6) (v 7) r c1`
    ASSUME_TAC THENL
   [USE_THEN "memiff" (MP_TAC o SPEC `c1:A`) THEN ANTS_TAC THENL
     [FIRST_ASSUM ACCEPT_TAC;
      DISCH_THEN(fun th -> REWRITE_TAC[GSYM th]) THEN FIRST_ASSUM ACCEPT_TAC];
    ALL_TAC] THEN
  SUBGOAL_THEN
    `ultramem D (E:A->A->bool) ((v:num->A) 3) (v 4) (v 5) (v 6) (v 7) r c2`
    ASSUME_TAC THENL
   [USE_THEN "memiff" (MP_TAC o SPEC `c2:A`) THEN ANTS_TAC THENL
     [FIRST_ASSUM ACCEPT_TAC;
      DISCH_THEN(fun th -> REWRITE_TAC[GSYM th]) THEN FIRST_ASSUM ACCEPT_TAC];
    ALL_TAC] THEN
  UNDISCH_TAC
    `ultramem D (E:A->A->bool) ((v:num->A) 3) (v 4) (v 5) (v 6)
     (v 7) r c2` THEN
  UNDISCH_TAC
    `ultramem D (E:A->A->bool) ((v:num->A) 3) (v 4) (v 5) (v 6)
     (v 7) r c1` THEN
  REWRITE_TAC[ultramem] THEN
  DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC
              (DISJ_CASES_THEN2 (LABEL_TAC "c1top") (LABEL_TAC "g1"))) THEN
  DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC
              (DISJ_CASES_THEN2 (LABEL_TAC "c2top") (LABEL_TAC "g2"))) THENL
  [ (* ============ A: c1=top, c2=top ============ *)
    SUBGOAL_THEN `(E:A->A->bool) ((v:num->A) 7) y` ASSUME_TAC THENL
     [USE_THEN "memiff" (MP_TAC o SPEC `(v:num->A) 7`) THEN ANTS_TAC THENL
       [FIRST_ASSUM ACCEPT_TAC;
        DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
        MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`(v:num->A) 3`;
                            `(v:num->A) 4`;
                            `(v:num->A) 5`;`(v:num->A) 6`;`(v:num->A) 7`;`r:A`]
        UMEM_TOP) THEN
        ASM_REWRITE_TAC[]];
      ALL_TAC] THEN
    SUBGOAL_THEN `erel D (E:A->A->bool) ((v:num->A) 5) (v 7) (v 7)`
      ASSUME_TAC THENL
      [MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`(v:num->A) 4`;
                           `(v:num->A) 5`;
                           `(v:num->A) 7`] EPORDER_REFL) THEN
      ASM_REWRITE_TAC[]; ALL_TAC] THEN
    EXISTS_TAC `(v:num->A) 7` THEN
    USE_THEN "c1top" SUBST_ALL_TAC THEN USE_THEN "c2top" SUBST_ALL_TAC THEN
    ASM_REWRITE_TAC[];

    (* ============ B: c1=top, c2 generator ============ *)
    REMOVE_THEN "g2" (X_CHOOSE_THEN `xi2:A` (X_CHOOSE_THEN `Fv2:A`
      (X_CHOOSE_THEN `b2:A` (X_CHOOSE_THEN `e2:A` (LABEL_TAC "bd2"))))) THEN
    USE_THEN "bd2" (ASSUME_TAC o CONJUNCT1) THEN
    USE_THEN "bd2" (ASSUME_TAC o CONJUNCT1 o CONJUNCT2) THEN
    USE_THEN "bd2" (ASSUME_TAC o CONJUNCT1 o funpow 2 CONJUNCT2) THEN
    USE_THEN "bd2" (ASSUME_TAC o CONJUNCT1 o funpow 3 CONJUNCT2) THEN
    USE_THEN "bd2" (ASSUME_TAC o CONJUNCT1 o funpow 4 CONJUNCT2) THEN
    USE_THEN "bd2" (ASSUME_TAC o CONJUNCT1 o funpow 5 CONJUNCT2) THEN
    USE_THEN "bd2" (LABEL_TAC "dec2" o CONJUNCT1 o funpow 6 CONJUNCT2) THEN
    USE_THEN "bd2"
      (X_CHOOSE_THEN `h2:A` (X_CHOOSE_THEN `hm2:A` STRIP_ASSUME_TAC)
        o funpow 7 CONJUNCT2) THEN
    SUBGOAL_THEN
      `E (xi2:A) a /\ erec D (E:A->A->bool) ultrastep_form v xi2 Fv2`
      STRIP_ASSUME_TAC THENL
     [MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`ultrastep_form`;
                    `v:num->A`;`a:A`;
                    `r:A`;`xi2:A`;`Fv2:A`] ERECRES_APPLY) THEN
      ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN `efilter D (E:A->A->bool) ((v:num->A) 4) (v 5) Fv2`
      ASSUME_TAC THENL
      [USE_THEN "ih" (MATCH_MP_TAC o SPECL [`xi2:A`;`Fv2:A`]) THEN
      ASM_REWRITE_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN `(E:A->A->bool) b2 ((v:num->A) 4)` ASSUME_TAC THENL
     [USE_THEN "frange" (MATCH_MP_TAC o SPECL [`xi2:A`;`b2:A`]) THEN
      ASM_REWRITE_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN `(E:A->A->bool) e2 ((v:num->A) 4)` ASSUME_TAC THENL
     [MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`(v:num->A) 4`;
                          `(v:num->A) 5`;
                          `(v:num->A) 6`;`(v:num->A) 7`;`Fv2:A`;`b2:A`;`e2:A`]
        DEC_IN_CARRIER) THEN
      ASM_REWRITE_TAC[]; ALL_TAC] THEN
    MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`(v:num->A) 4`;`(v:num->A) 5`;
      `(v:num->A) 7`;`Fv2:A`;`e2:A`] UMEM_CERT_TOP) THEN
    ASM_REWRITE_TAC[] THEN
    DISCH_THEN(X_CHOOSE_THEN `w1:A`
               (X_CHOOSE_THEN `m1:A` STRIP_ASSUME_TAC)) THEN
    USE_THEN "c1top" SUBST_ALL_TAC THEN
    MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`(v:num->A) 3`;`(v:num->A) 4`;
      `(v:num->A) 5`;`(v:num->A) 6`;`(v:num->A) 7`;`r:A`;`xi2:A`;
      `Fv2:A`;`b2:A`;
      `e2:A`;`(v:num->A) 7`;`c2:A`;`w1:A`;`m1:A`;`h2:A`;`hm2:A`]
                 UMEM_DIR_MEET) THEN
    ASM_REWRITE_TAC[] THEN
    DISCH_THEN(X_CHOOSE_THEN `c3:A` STRIP_ASSUME_TAC) THEN
    SUBGOAL_THEN `(E:A->A->bool) (c3:A) y` ASSUME_TAC THENL
     [USE_THEN "memiff" (MP_TAC o SPEC `c3:A`) THEN ANTS_TAC THENL
       [FIRST_ASSUM ACCEPT_TAC;
        DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN FIRST_ASSUM ACCEPT_TAC];
      ALL_TAC] THEN
    EXISTS_TAC `c3:A` THEN ASM_REWRITE_TAC[];

    (* ============ C: c1 generator, c2=top ============ *)
    REMOVE_THEN "g1" (X_CHOOSE_THEN `xi1:A` (X_CHOOSE_THEN `Fv1:A`
      (X_CHOOSE_THEN `b1:A` (X_CHOOSE_THEN `e1:A` (LABEL_TAC "bd1"))))) THEN
    USE_THEN "bd1" (ASSUME_TAC o CONJUNCT1) THEN
    USE_THEN "bd1" (ASSUME_TAC o CONJUNCT1 o CONJUNCT2) THEN
    USE_THEN "bd1" (ASSUME_TAC o CONJUNCT1 o funpow 2 CONJUNCT2) THEN
    USE_THEN "bd1" (ASSUME_TAC o CONJUNCT1 o funpow 3 CONJUNCT2) THEN
    USE_THEN "bd1" (ASSUME_TAC o CONJUNCT1 o funpow 4 CONJUNCT2) THEN
    USE_THEN "bd1" (ASSUME_TAC o CONJUNCT1 o funpow 5 CONJUNCT2) THEN
    USE_THEN "bd1" (LABEL_TAC "dec1" o CONJUNCT1 o funpow 6 CONJUNCT2) THEN
    USE_THEN "bd1"
      (X_CHOOSE_THEN `h1:A` (X_CHOOSE_THEN `hm1:A` STRIP_ASSUME_TAC)
        o funpow 7 CONJUNCT2) THEN
    SUBGOAL_THEN
      `E (xi1:A) a /\ erec D (E:A->A->bool) ultrastep_form v xi1 Fv1`
      STRIP_ASSUME_TAC THENL
     [MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`ultrastep_form`;
                    `v:num->A`;`a:A`;
                    `r:A`;`xi1:A`;`Fv1:A`] ERECRES_APPLY) THEN
      ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN `efilter D (E:A->A->bool) ((v:num->A) 4) (v 5) Fv1`
      ASSUME_TAC THENL
      [USE_THEN "ih" (MATCH_MP_TAC o SPECL [`xi1:A`;`Fv1:A`]) THEN
      ASM_REWRITE_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN `(E:A->A->bool) b1 ((v:num->A) 4)` ASSUME_TAC THENL
     [USE_THEN "frange" (MATCH_MP_TAC o SPECL [`xi1:A`;`b1:A`]) THEN
      ASM_REWRITE_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN `(E:A->A->bool) e1 ((v:num->A) 4)` ASSUME_TAC THENL
     [MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`(v:num->A) 4`;
                          `(v:num->A) 5`;
                          `(v:num->A) 6`;`(v:num->A) 7`;`Fv1:A`;`b1:A`;`e1:A`]
        DEC_IN_CARRIER) THEN
      ASM_REWRITE_TAC[]; ALL_TAC] THEN
    MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`(v:num->A) 4`;`(v:num->A) 5`;
      `(v:num->A) 7`;`Fv1:A`;`e1:A`] UMEM_CERT_TOP) THEN
    ASM_REWRITE_TAC[] THEN
    DISCH_THEN(X_CHOOSE_THEN `w2:A`
               (X_CHOOSE_THEN `m2:A` STRIP_ASSUME_TAC)) THEN
    USE_THEN "c2top" SUBST_ALL_TAC THEN
    MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`(v:num->A) 3`;`(v:num->A) 4`;
      `(v:num->A) 5`;`(v:num->A) 6`;`(v:num->A) 7`;`r:A`;`xi1:A`;
      `Fv1:A`;`b1:A`;
      `e1:A`;`(v:num->A) 7`;`c1:A`;`w2:A`;`m2:A`;`h1:A`;`hm1:A`]
                 UMEM_DIR_MEET) THEN
    ASM_REWRITE_TAC[] THEN
    DISCH_THEN(X_CHOOSE_THEN `c3:A` STRIP_ASSUME_TAC) THEN
    SUBGOAL_THEN `(E:A->A->bool) (c3:A) y` ASSUME_TAC THENL
     [USE_THEN "memiff" (MP_TAC o SPEC `c3:A`) THEN ANTS_TAC THENL
       [FIRST_ASSUM ACCEPT_TAC;
        DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN FIRST_ASSUM ACCEPT_TAC];
      ALL_TAC] THEN
    EXISTS_TAC `c3:A` THEN ASM_REWRITE_TAC[];

    (* ============ D: both generators ============ *)
    REMOVE_THEN "g1" (X_CHOOSE_THEN `xi1:A` (X_CHOOSE_THEN `Fv1:A`
      (X_CHOOSE_THEN `b1:A` (X_CHOOSE_THEN `e1:A` (LABEL_TAC "bd1"))))) THEN
    USE_THEN "bd1" (ASSUME_TAC o CONJUNCT1) THEN
    USE_THEN "bd1" (ASSUME_TAC o CONJUNCT1 o CONJUNCT2) THEN
    USE_THEN "bd1" (ASSUME_TAC o CONJUNCT1 o funpow 2 CONJUNCT2) THEN
    USE_THEN "bd1" (ASSUME_TAC o CONJUNCT1 o funpow 3 CONJUNCT2) THEN
    USE_THEN "bd1" (ASSUME_TAC o CONJUNCT1 o funpow 4 CONJUNCT2) THEN
    USE_THEN "bd1" (ASSUME_TAC o CONJUNCT1 o funpow 5 CONJUNCT2) THEN
    USE_THEN "bd1" (LABEL_TAC "dec1" o CONJUNCT1 o funpow 6 CONJUNCT2) THEN
    USE_THEN "bd1"
      (X_CHOOSE_THEN `h1:A` (X_CHOOSE_THEN `hm1:A` STRIP_ASSUME_TAC)
        o funpow 7 CONJUNCT2) THEN
    REMOVE_THEN "g2" (X_CHOOSE_THEN `xi2:A` (X_CHOOSE_THEN `Fv2:A`
      (X_CHOOSE_THEN `b2:A` (X_CHOOSE_THEN `e2:A` (LABEL_TAC "bd2"))))) THEN
    USE_THEN "bd2" (ASSUME_TAC o CONJUNCT1) THEN
    USE_THEN "bd2" (ASSUME_TAC o CONJUNCT1 o CONJUNCT2) THEN
    USE_THEN "bd2" (ASSUME_TAC o CONJUNCT1 o funpow 2 CONJUNCT2) THEN
    USE_THEN "bd2" (ASSUME_TAC o CONJUNCT1 o funpow 3 CONJUNCT2) THEN
    USE_THEN "bd2" (ASSUME_TAC o CONJUNCT1 o funpow 4 CONJUNCT2) THEN
    USE_THEN "bd2" (ASSUME_TAC o CONJUNCT1 o funpow 5 CONJUNCT2) THEN
    USE_THEN "bd2" (LABEL_TAC "dec2" o CONJUNCT1 o funpow 6 CONJUNCT2) THEN
    USE_THEN "bd2"
      (X_CHOOSE_THEN `h2:A` (X_CHOOSE_THEN `hm2:A` STRIP_ASSUME_TAC)
        o funpow 7 CONJUNCT2) THEN
    SUBGOAL_THEN
      `E (xi1:A) a /\ erec D (E:A->A->bool) ultrastep_form v xi1 Fv1`
      STRIP_ASSUME_TAC THENL
     [MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`ultrastep_form`;
                    `v:num->A`;`a:A`;
                    `r:A`;`xi1:A`;`Fv1:A`] ERECRES_APPLY) THEN
      ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN
      `E (xi2:A) a /\ erec D (E:A->A->bool) ultrastep_form v xi2 Fv2`
      STRIP_ASSUME_TAC THENL
     [MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`ultrastep_form`;
                    `v:num->A`;`a:A`;
                    `r:A`;`xi2:A`;`Fv2:A`] ERECRES_APPLY) THEN
      ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN `efilter D (E:A->A->bool) ((v:num->A) 4) (v 5) Fv1`
      ASSUME_TAC THENL
      [USE_THEN "ih" (MATCH_MP_TAC o SPECL [`xi1:A`;`Fv1:A`]) THEN
      ASM_REWRITE_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN `efilter D (E:A->A->bool) ((v:num->A) 4) (v 5) Fv2`
      ASSUME_TAC THENL
      [USE_THEN "ih" (MATCH_MP_TAC o SPECL [`xi2:A`;`Fv2:A`]) THEN
      ASM_REWRITE_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN `(E:A->A->bool) b1 ((v:num->A) 4)` ASSUME_TAC THENL
     [USE_THEN "frange" (MATCH_MP_TAC o SPECL [`xi1:A`;`b1:A`]) THEN
      ASM_REWRITE_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN `(E:A->A->bool) b2 ((v:num->A) 4)` ASSUME_TAC THENL
     [USE_THEN "frange" (MATCH_MP_TAC o SPECL [`xi2:A`;`b2:A`]) THEN
      ASM_REWRITE_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN `(E:A->A->bool) e1 ((v:num->A) 4)` ASSUME_TAC THENL
     [MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`(v:num->A) 4`;
                          `(v:num->A) 5`;
                          `(v:num->A) 6`;`(v:num->A) 7`;`Fv1:A`;`b1:A`;`e1:A`]
        DEC_IN_CARRIER) THEN
      ASM_REWRITE_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN `(E:A->A->bool) e2 ((v:num->A) 4)` ASSUME_TAC THENL
     [MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`(v:num->A) 4`;
                          `(v:num->A) 5`;
                          `(v:num->A) 6`;`(v:num->A) 7`;`Fv2:A`;`b2:A`;`e2:A`]
          DEC_IN_CARRIER) THEN
      ASM_REWRITE_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN `(E:A->A->bool) hm1 ((v:num->A) 4)` ASSUME_TAC THENL
     [ASM_MESON_TAC[EMEET_IN]; ALL_TAC] THEN
    SUBGOAL_THEN `(E:A->A->bool) hm2 ((v:num->A) 4)` ASSUME_TAC THENL
     [ASM_MESON_TAC[EMEET_IN]; ALL_TAC] THEN
    SUBGOAL_THEN `eordinal D (E:A->A->bool) xi1 /\ eordinal D E xi2`
      STRIP_ASSUME_TAC THENL
     [ASM_MESON_TAC[EORDINAL_MEMBER]; ALL_TAC] THEN
    MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`xi1:A`;`xi2:A`]
           EORDINAL_TRICHOTOMY) THEN
    ASM_REWRITE_TAC[] THEN
    DISCH_THEN(DISJ_CASES_THEN2 (LABEL_TAC "lt12")
                (DISJ_CASES_THEN2 (LABEL_TAC "eq12") (LABEL_TAC "lt21"))) THENL
    [ (* ---- D2: xi1 < xi2, host stage 2 ---- *)
      MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`v:num->A`;`xi1:A`;`xi2:A`;
        `Fv1:A`;`Fv2:A`;`b1:A`;`e1:A`;`h1:A`;`hm1:A`;`e2:A`]
            UMEM_CERT_EARLIER) THEN
      ASM_REWRITE_TAC[] THEN
      DISCH_THEN(X_CHOOSE_THEN `w1:A`
                 (X_CHOOSE_THEN `m1:A` STRIP_ASSUME_TAC)) THEN
      SUBGOAL_THEN `erel D (E:A->A->bool) ((v:num->A) 5) m1 c1`
        ASSUME_TAC THENL
        [MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`(v:num->A) 4`;
                             `(v:num->A) 5`;
                             `m1:A`;`hm1:A`;`c1:A`] EPORDER_TRANS) THEN
                 ASM_REWRITE_TAC[]; ALL_TAC] THEN
      MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`(v:num->A) 3`;`(v:num->A) 4`;
        `(v:num->A) 5`;`(v:num->A) 6`;`(v:num->A) 7`;`r:A`;`xi2:A`;
        `Fv2:A`;`b2:A`;
        `e2:A`;`c1:A`;`c2:A`;`w1:A`;`m1:A`;`h2:A`;`hm2:A`] UMEM_DIR_MEET) THEN
      ASM_REWRITE_TAC[] THEN
      DISCH_THEN(X_CHOOSE_THEN `c3:A` STRIP_ASSUME_TAC) THEN
      SUBGOAL_THEN `(E:A->A->bool) (c3:A) y` ASSUME_TAC THENL
       [USE_THEN "memiff" (MP_TAC o SPEC `c3:A`) THEN ANTS_TAC THENL
       [FIRST_ASSUM ACCEPT_TAC;
        DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN FIRST_ASSUM ACCEPT_TAC];
      ALL_TAC] THEN
      EXISTS_TAC `c3:A` THEN ASM_REWRITE_TAC[];
      (* ---- D1: xi1 = xi2, same stage ---- *)
      USE_THEN "eq12" SUBST_ALL_TAC THEN
      SUBGOAL_THEN `Fv1:A = Fv2` SUBST_ALL_TAC THENL
       [MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;
                            `ultrastep_form`;`v:num->A`;
                            `xi2:A`;`Fv1:A`;`Fv2:A`] EREC_UNIQUE) THEN
      ASM_REWRITE_TAC[]; ALL_TAC] THEN
      SUBGOAL_THEN `b1:A = b2` SUBST_ALL_TAC THENL
       [USE_THEN "ffun" (MATCH_MP_TAC o SPECL [`xi2:A`;`b1:A`;`b2:A`]) THEN
        ASM_REWRITE_TAC[]; ALL_TAC] THEN
      SUBGOAL_THEN `e1:A = e2` SUBST_ALL_TAC THENL
       [MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`(v:num->A) 4`;
                            `(v:num->A) 5`;
                            `(v:num->A) 6`;`(v:num->A) 7`;`Fv2:A`;`b2:A`;
                            `e1:A`;`e2:A`]
          DECISION_UNIQUE) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
      MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`(v:num->A) 3`;`(v:num->A) 4`;
        `(v:num->A) 5`;`(v:num->A) 6`;`(v:num->A) 7`;`r:A`;`xi2:A`;
        `Fv2:A`;`b2:A`;
        `e2:A`;`c1:A`;`c2:A`;`h1:A`;`hm1:A`;`h2:A`;`hm2:A`] UMEM_DIR_MEET) THEN
      ASM_REWRITE_TAC[] THEN
      DISCH_THEN(X_CHOOSE_THEN `c3:A` STRIP_ASSUME_TAC) THEN
      SUBGOAL_THEN `(E:A->A->bool) (c3:A) y` ASSUME_TAC THENL
       [USE_THEN "memiff" (MP_TAC o SPEC `c3:A`) THEN ANTS_TAC THENL
       [FIRST_ASSUM ACCEPT_TAC;
        DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN FIRST_ASSUM ACCEPT_TAC];
      ALL_TAC] THEN
      EXISTS_TAC `c3:A` THEN ASM_REWRITE_TAC[];
      (* ---- D3: xi2 < xi1, host stage 1 ---- *)
      MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`v:num->A`;`xi2:A`;`xi1:A`;
        `Fv2:A`;`Fv1:A`;`b2:A`;`e2:A`;`h2:A`;`hm2:A`;`e1:A`]
        UMEM_CERT_EARLIER) THEN
      ASM_REWRITE_TAC[] THEN
      DISCH_THEN(X_CHOOSE_THEN `w2:A`
                 (X_CHOOSE_THEN `m2:A` STRIP_ASSUME_TAC)) THEN
      SUBGOAL_THEN `erel D (E:A->A->bool) ((v:num->A) 5) m2 c2`
        ASSUME_TAC THENL
        [MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`(v:num->A) 4`;
                             `(v:num->A) 5`;
                             `m2:A`;`hm2:A`;`c2:A`] EPORDER_TRANS) THEN
                 ASM_REWRITE_TAC[]; ALL_TAC] THEN
      MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`(v:num->A) 3`;`(v:num->A) 4`;
        `(v:num->A) 5`;`(v:num->A) 6`;`(v:num->A) 7`;`r:A`;`xi1:A`;
        `Fv1:A`;`b1:A`;
        `e1:A`;`c2:A`;`c1:A`;`w2:A`;`m2:A`;`h1:A`;`hm1:A`] UMEM_DIR_MEET) THEN
      ASM_REWRITE_TAC[] THEN
      DISCH_THEN(X_CHOOSE_THEN `c3:A` STRIP_ASSUME_TAC) THEN
      SUBGOAL_THEN `(E:A->A->bool) (c3:A) y` ASSUME_TAC THENL
       [USE_THEN "memiff" (MP_TAC o SPEC `c3:A`) THEN ANTS_TAC THENL
       [FIRST_ASSUM ACCEPT_TAC;
        DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN FIRST_ASSUM ACCEPT_TAC];
      ALL_TAC] THEN
      EXISTS_TAC `c3:A` THEN ASM_REWRITE_TAC[]]]);;

(* U5D_STEP: the per-stage assembly.  If every earlier-stage value F_xi is a
   proper filter (IH carries properness), then the stage value F_a = the erec
   value y at ordinal a is itself a proper filter: efilter via UMEM_SUBSET /
   UMEM_TOP@(v7) / UMEM_UP / EULTRAREC_DIRECTED, properness via UMEM_PROPER
   with EBOT_UNIQUE bridging ~(E (v6) Fv) <-> ~(?z. ebot z /\ E z Fv).
   NOTE (learned): never ASM_REWRITE after MP_TAC of an ih-instance -- the
   standing ih assumption rewrites its own instance to T ("DISCH_TAC" failure);
   discharge with ANTS_TAC + explicit CONJ/ACCEPT
     instead.                    *)
let U5D_STEP = prove
 (`!D (E:A->A->bool) v a y.
     model D E ZF_AX /\ valuation D v /\
     ebalg D E (v 4) (v 5) /\ ebot D E (v 4) (v 5) (v 6) /\
     etop D E (v 4) (v 5) (v 7) /\ ~(v 6 = v 7) /\
     (!xi b. xi IN D /\ b IN D /\ eapply D E (v 3) xi b ==> E b (v 4)) /\
     (!xi b b'. xi IN D /\ b IN D /\ b' IN D /\ eapply D E (v 3) xi b /\
                eapply D E (v 3) xi b' ==> b = b') /\
     eordinal D E a /\
     (!xi y0. xi IN D /\ E xi a /\ y0 IN D /\ erec D E ultrastep_form v xi y0
              ==> efilter D E (v 4) (v 5) y0 /\ ~(E (v 6) y0)) /\
     y IN D /\ erec D E ultrastep_form v a y
     ==> efilter D E (v 4) (v 5) y /\ ~(E (v 6) y)`,
  REPEAT GEN_TAC THEN
  DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC
   (CONJUNCTS_THEN2 ASSUME_TAC
    (CONJUNCTS_THEN2 ASSUME_TAC
     (CONJUNCTS_THEN2 ASSUME_TAC
      (CONJUNCTS_THEN2 ASSUME_TAC
       (CONJUNCTS_THEN2 ASSUME_TAC
        (CONJUNCTS_THEN2 (LABEL_TAC "frange")
         (CONJUNCTS_THEN2 (LABEL_TAC "ffun")
          (CONJUNCTS_THEN2 ASSUME_TAC
           (CONJUNCTS_THEN2 (LABEL_TAC "ih")
            STRIP_ASSUME_TAC)))))))))) THEN
  SUBGOAL_THEN `eporder D (E:A->A->bool) ((v:num->A) 4) (v 5)` ASSUME_TAC THENL
   [ASM_MESON_TAC[EBALG_IMP_PORDER]; ALL_TAC] THEN
  SUBGOAL_THEN `((v:num->A) 7) IN D /\ (E:A->A->bool) (v 7) (v 4)`
   STRIP_ASSUME_TAC THENL [ASM_MESON_TAC[ETOP_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `((v:num->A) 6) IN D /\ (E:A->A->bool) (v 6) (v 4)`
   STRIP_ASSUME_TAC THENL [ASM_MESON_TAC[EBOT_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `?r. erecres D (E:A->A->bool) ultrastep_form v a r`
   (X_CHOOSE_THEN `r:A` (LABEL_TAC "rres")) THENL
   [MATCH_MP_TAC ERECRES_EXISTS THEN ASM_REWRITE_TAC[] THEN
    ASM_MESON_TAC[ULTRASTEP_QFUN; ULTRASTEP_QTOTAL]; ALL_TAC] THEN
  SUBGOAL_THEN `(r:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[erecres]; ALL_TAC] THEN
  MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`v:num->A`;`a:A`;`y:A`;`r:A`]
        EULTRAREC_MEM) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(LABEL_TAC "memiff") THEN
  SUBGOAL_THEN
   `!xi Fv. xi IN D /\ Fv IN D /\ eapply D (E:A->A->bool) r xi Fv
            ==> efilter D E ((v:num->A) 4) (v 5) Fv /\
                ~(?z. ebot D E (v 4) (v 5) z /\ E z Fv)`
   (LABEL_TAC "gfilt") THENL
   [MAP_EVERY X_GEN_TAC [`xi:A`;`Fv:A`] THEN STRIP_TAC THEN
    SUBGOAL_THEN `(E:A->A->bool) xi a /\ erec D E ultrastep_form v xi Fv`
     STRIP_ASSUME_TAC THENL [ASM_MESON_TAC[ERECRES_APPLY]; ALL_TAC] THEN
    USE_THEN "ih" (MP_TAC o SPECL[`xi:A`;`Fv:A`]) THEN ASM_REWRITE_TAC[] THEN
    STRIP_TAC THEN ASM_REWRITE_TAC[] THEN
    ASM_MESON_TAC[EBOT_UNIQUE];
    ALL_TAC] THEN
  SUBGOAL_THEN `esubset D (E:A->A->bool) y ((v:num->A) 4)`
    (LABEL_TAC "esub") THENL
   [REWRITE_TAC[esubset] THEN X_GEN_TAC `w:A` THEN STRIP_TAC THEN
    SUBGOAL_THEN
     `ultramem D (E:A->A->bool) ((v:num->A) 3) (v 4) (v 5) (v 6) (v 7) r w`
     ASSUME_TAC THENL
     [USE_THEN "memiff" (MP_TAC o SPEC `w:A`) THEN ANTS_TAC THENL
       [FIRST_ASSUM ACCEPT_TAC;
        DISCH_THEN(fun th -> REWRITE_TAC[GSYM th]) THEN
        FIRST_ASSUM ACCEPT_TAC];
      ALL_TAC] THEN
    ASM_MESON_TAC[UMEM_SUBSET];
    ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) ((v:num->A) 7) y` (LABEL_TAC "topmem") THENL
   [USE_THEN "memiff" (MP_TAC o SPEC `(v:num->A) 7`) THEN ANTS_TAC THENL
     [FIRST_ASSUM ACCEPT_TAC;
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
      MATCH_MP_TAC UMEM_TOP THEN FIRST_ASSUM ACCEPT_TAC];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!x w. x IN D /\ w IN D /\ (E:A->A->bool) x y /\ E w ((v:num->A) 4) /\
          erel D E (v 5) x w ==> E w y`
   (LABEL_TAC "upcl") THENL
   [MAP_EVERY X_GEN_TAC [`x:A`;`w:A`] THEN STRIP_TAC THEN
    SUBGOAL_THEN
     `ultramem D (E:A->A->bool) ((v:num->A) 3) (v 4) (v 5) (v 6) (v 7) r x`
     ASSUME_TAC THENL
     [USE_THEN "memiff" (MP_TAC o SPEC `x:A`) THEN ANTS_TAC THENL
       [FIRST_ASSUM ACCEPT_TAC;
        DISCH_THEN(fun th -> REWRITE_TAC[GSYM th]) THEN
        FIRST_ASSUM ACCEPT_TAC];
      ALL_TAC] THEN
    USE_THEN "memiff" (MP_TAC o SPEC `w:A`) THEN ANTS_TAC THENL
     [FIRST_ASSUM ACCEPT_TAC;
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
      MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`(v:num->A) 3`;`(v:num->A) 4`;
        `(v:num->A) 5`;`(v:num->A) 6`;`(v:num->A) 7`;`r:A`;`x:A`;`w:A`]
        UMEM_UP) THEN
      ASM_REWRITE_TAC[]];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!c1 c2. c1 IN D /\ c2 IN D /\ (E:A->A->bool) c1 y /\ E c2 y
            ==> ?c3. c3 IN D /\ E c3 y /\ erel D E ((v:num->A) 5) c3 c1 /\
                     erel D E (v 5) c3 c2`
   (LABEL_TAC "dir") THENL
   [MAP_EVERY X_GEN_TAC [`c1:A`;`c2:A`] THEN STRIP_TAC THEN
    MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`v:num->A`;`a:A`;`y:A`;`r:A`;
                  `c1:A`;`c2:A`] EULTRAREC_DIRECTED) THEN
    ANTS_TAC THENL
     [REPEAT CONJ_TAC THEN TRY(FIRST_ASSUM ACCEPT_TAC) THEN
      MAP_EVERY X_GEN_TAC [`xi:A`;`y0:A`] THEN STRIP_TAC THEN
      USE_THEN "ih" (MP_TAC o SPECL[`xi:A`;`y0:A`]) THEN ANTS_TAC THENL
       [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
        DISCH_THEN(ACCEPT_TAC o CONJUNCT1)];
      DISCH_THEN ACCEPT_TAC];
    ALL_TAC] THEN
  CONJ_TAC THENL
   [REWRITE_TAC[efilter] THEN REPEAT CONJ_TAC THENL
     [FIRST_ASSUM ACCEPT_TAC;
      USE_THEN "esub" ACCEPT_TAC;
      EXISTS_TAC `(v:num->A) 7` THEN CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
      USE_THEN "upcl" ACCEPT_TAC;
      USE_THEN "dir" ACCEPT_TAC];
    MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`(v:num->A) 3`;`(v:num->A) 4`;
      `(v:num->A) 5`;`(v:num->A) 6`;`(v:num->A) 7`;`r:A`] UMEM_PROPER) THEN
    ANTS_TAC THENL
     [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
      DISCH_THEN(LABEL_TAC "noprop") THEN
      SUBGOAL_THEN
       `~(ultramem D (E:A->A->bool) ((v:num->A) 3) (v 4) (v 5) (v 6)
          (v 7) r (v 6))`
       ASSUME_TAC THENL
       [USE_THEN "noprop" MP_TAC THEN REWRITE_TAC[NOT_EXISTS_THM] THEN
        DISCH_THEN(MP_TAC o SPEC `(v:num->A) 6`) THEN
        ASM_REWRITE_TAC[DE_MORGAN_THM];
        ALL_TAC] THEN
      USE_THEN "memiff" (MP_TAC o SPEC `(v:num->A) 6`) THEN ANTS_TAC THENL
       [FIRST_ASSUM ACCEPT_TAC;
        DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN FIRST_ASSUM ACCEPT_TAC]]]);;

(* EULTRAREC_PROPERFILT: the EORDINAL_INDUCT wrap of U5D_STEP via INV_form /
   INV_HOLDS.  Every erec stage value F_a (a an ordinal) is a proper filter:
   efilter + bot-free.  Ambient: ebalg/ebot/etop at slots 4,5,6,7, nontrivial
   (~(v6=v7)), enumeration f=(v3) B-valued (frange) and functional (ffun).   *)
let EULTRAREC_PROPERFILT = prove
 (`!D (E:A->A->bool) v.
     model D E ZF_AX /\ valuation D v /\
     ebalg D E (v 4) (v 5) /\ ebot D E (v 4) (v 5) (v 6) /\
     etop D E (v 4) (v 5) (v 7) /\ ~(v 6 = v 7) /\
     (!xi b. xi IN D /\ b IN D /\ eapply D E (v 3) xi b ==> E b (v 4)) /\
     (!xi b b'. xi IN D /\ b IN D /\ b' IN D /\ eapply D E (v 3) xi b /\
                eapply D E (v 3) xi b' ==> b = b')
     ==> !a y. eordinal D E a /\ y IN D /\ erec D E ultrastep_form v a y
               ==> efilter D E (v 4) (v 5) y /\ ~(E (v 6) y)`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN
   `!a. eordinal D (E:A->A->bool) a ==> holds D E ((14 |-> a) v) INV_form`
   (LABEL_TAC "main") THENL
   [MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`INV_form`;`14`;`v:num->A`]
       EORDINAL_INDUCT) THEN
    ANTS_TAC THENL
     [REPEAT CONJ_TAC THEN TRY(FIRST_ASSUM ACCEPT_TAC) THEN
      X_GEN_TAC `a:A` THEN
      DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC (LABEL_TAC "ihh")) THEN
      SUBGOAL_THEN `(a:A) IN D` ASSUME_TAC THENL
       [ASM_MESON_TAC[EORDINAL_IN]; ALL_TAC] THEN
      MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`v:num->A`;`a:A`]
             INV_HOLDS) THEN
      ANTS_TAC THENL
       [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
        DISCH_THEN(fun th -> REWRITE_TAC[th])] THEN
      X_GEN_TAC `y:A` THEN STRIP_TAC THEN
      MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`v:num->A`;`a:A`;`y:A`]
        U5D_STEP) THEN
      ANTS_TAC THENL
       [REPEAT CONJ_TAC THEN TRY(FIRST_ASSUM ACCEPT_TAC) THEN
        MAP_EVERY X_GEN_TAC [`xi:A`;`y0:A`] THEN STRIP_TAC THEN
        USE_THEN "ihh" (MP_TAC o SPEC `xi:A`) THEN ANTS_TAC THENL
         [CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
        MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`v:num->A`;`xi:A`]
          INV_HOLDS) THEN
        ANTS_TAC THENL
         [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
          DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
          DISCH_THEN(MP_TAC o SPEC `y0:A`) THEN ANTS_TAC THENL
           [CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; DISCH_THEN ACCEPT_TAC]];
        DISCH_THEN ACCEPT_TAC];
      DISCH_THEN ACCEPT_TAC];
    ALL_TAC] THEN
  MAP_EVERY X_GEN_TAC [`a:A`;`y:A`] THEN STRIP_TAC THEN
  SUBGOAL_THEN `(a:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[EORDINAL_IN]; ALL_TAC] THEN
  USE_THEN "main" (MP_TAC o SPEC `a:A`) THEN ANTS_TAC THENL
   [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`v:num->A`;`a:A`] INV_HOLDS) THEN
  ANTS_TAC THENL
   [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    DISCH_THEN(MP_TAC o SPEC `y:A`) THEN ANTS_TAC THENL
     [CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; DISCH_THEN ACCEPT_TAC]]);;

(* DEC_EXISTS: at any stage the decision e for b exists: e = b if b is
   strongly compatible with the current filter-value Fv, else e = the
   complement of b (whose meet/join with b are THE ambient bot/top via
   ECOMPL_MEET_JOIN + EBOT/ETOP_UNIQUE inside).  Fv is unconstrained.      *)
let DEC_EXISTS = prove
 (`!D (E:A->A->bool) B leq bot top Fv b.
     ebalg D E B leq /\ ebot D E B leq bot /\ etop D E B leq top /\
     b IN D /\ E b B
     ==> ?e. e IN D /\ E e B /\
             ( (ecompatset D E B leq bot Fv b /\ e = b) \/
               (~ecompatset D E B leq bot Fv b /\ E e B /\
                emeet D E B leq b e bot /\ ejoin D E B leq b e top) )`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `eporder D (E:A->A->bool) B leq` ASSUME_TAC THENL
   [ASM_MESON_TAC[EBALG_IMP_PORDER]; ALL_TAC] THEN
  ASM_CASES_TAC `ecompatset D (E:A->A->bool) B leq bot Fv b` THENL
   [EXISTS_TAC `b:A` THEN ASM_REWRITE_TAC[];
    MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`b:A`]
      EBALG_COMPL) THEN
    ASM_REWRITE_TAC[] THEN
    DISCH_THEN(X_CHOOSE_TAC `cb:A`) THEN
    SUBGOAL_THEN `(cb:A) IN D /\ (E:A->A->bool) cb B` STRIP_ASSUME_TAC THENL
     [ASM_MESON_TAC[ECOMPL_IN]; ALL_TAC] THEN
    MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`b:A`;`cb:A`;
      `bot:A`;`top:A`] ECOMPL_MEET_JOIN) THEN
    ASM_REWRITE_TAC[] THEN STRIP_TAC THEN
    EXISTS_TAC `cb:A` THEN ASM_REWRITE_TAC[]]);;

(* EULTRA_EXISTS (F8-0 endpoint): in a model of ZF + V=L, every nontrivial
   internal complete Boolean algebra carries an internal ultrafilter U IN D.
   Construction: ESET_EBIJ enumerates B by an ordinal d via an internal
   bijection f; the transfinite recursion erec/ultrastep_form builds the
   increasing chain of proper filters F_xi (EULTRAREC_PROPERFILT); at U=F_d
   every b IN B was decided at its enumeration stage (EULTRAREC_DECLATER),
   giving the ultrafilter dichotomy.  The nontriviality hyp ~(bot=top) is
   NECESSARY: a trivial algebra has no proper filter.                       *)
let EULTRA_EXISTS = prove
 (`!D (E:A->A->bool) B leq bot top.
     model D E ZF_AX /\ (!u. u IN D ==> elmem D E u) /\
     ecba D E B leq /\ B IN D /\ leq IN D /\
     ebot D E B leq bot /\ etop D E B leq top /\ ~(bot = top)
     ==> ?U. U IN D /\ eultra D E B leq U`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "zf vl cba BD leqD botbot toptop botnetop" THEN
  SUBGOAL_THEN `ebalg D (E:A->A->bool) B leq` ASSUME_TAC THENL
   [ASM_MESON_TAC[ECBA_IMP_BALG]; ALL_TAC] THEN
  SUBGOAL_THEN `eporder D (E:A->A->bool) B leq` ASSUME_TAC THENL
   [ASM_MESON_TAC[EBALG_IMP_PORDER]; ALL_TAC] THEN
  SUBGOAL_THEN `(bot:A) IN D /\ (E:A->A->bool) bot B` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[EBOT_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `(top:A) IN D /\ (E:A->A->bool) top B` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[ETOP_IN]; ALL_TAC] THEN
  MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`] ESET_EBIJ) THEN
  ANTS_TAC THENL
   [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
    DISCH_THEN(X_CHOOSE_THEN `d:A` (X_CHOOSE_THEN `f:A`
      (CONJUNCTS_THEN2 ASSUME_TAC (CONJUNCTS_THEN2 ASSUME_TAC MP_TAC)))) THEN
    REWRITE_TAC[ebij] THEN STRIP_TAC] THEN
  SUBGOAL_THEN
   `?vv:num->A. valuation D vv /\ vv 3 = f /\ vv 4 = B /\ vv 5 = leq /\
                vv 6 = bot /\ vv 7 = top`
   (X_CHOOSE_THEN `vv:num->A` STRIP_ASSUME_TAC) THENL
   [EXISTS_TAC `(3 |-> (f:A)) ((4 |-> B) ((5 |-> leq) ((6 |-> bot)
      ((7 |-> top) (\n. B)))))` THEN
    CONJ_TAC THENL
     [REPEAT(MATCH_MP_TAC VALUATION_VALMOD THEN CONJ_TAC THENL
        [ALL_TAC; FIRST_ASSUM ACCEPT_TAC]) THEN
      REWRITE_TAC[valuation] THEN ASM_REWRITE_TAC[];
      REWRITE_TAC[VALMOD; ARITH_EQ]];
    ALL_TAC] THEN
  SUBGOAL_THEN `ebalg D (E:A->A->bool) ((vv:num->A) 4) (vv 5)` ASSUME_TAC THENL
   [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `ebot D (E:A->A->bool) ((vv:num->A) 4) (vv 5) (vv 6)`
   ASSUME_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `etop D (E:A->A->bool) ((vv:num->A) 4) (vv 5) (vv 7)`
   ASSUME_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `~(((vv:num->A) 6) = vv 7)` ASSUME_TAC THENL
   [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN
   `!xi b. xi IN D /\ b IN D /\ eapply D (E:A->A->bool) ((vv:num->A) 3) xi b
           ==> E b (vv 4)`
   (LABEL_TAC "frangev") THENL
   [ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN
   `!xi b b'. xi IN D /\ b IN D /\ b' IN D /\
              eapply D (E:A->A->bool) ((vv:num->A) 3) xi b /\
              eapply D E (vv 3) xi b' ==> b = b'`
   (LABEL_TAC "ffunv") THENL
   [ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[]; ALL_TAC] THEN
  MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`vv:num->A`;`d:A`]
    EULTRAREC_EXISTS) THEN
  ANTS_TAC THENL
   [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
    DISCH_THEN(X_CHOOSE_THEN `U:A` STRIP_ASSUME_TAC)] THEN
  MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`vv:num->A`]
    EULTRAREC_PROPERFILT) THEN
  ANTS_TAC THENL
   [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
    DISCH_THEN(LABEL_TAC "pfilt")] THEN
  SUBGOAL_THEN `efilter D (E:A->A->bool) B leq U /\ ~((E:A->A->bool) bot U)`
   STRIP_ASSUME_TAC THENL
   [USE_THEN "pfilt" (MP_TAC o SPECL[`d:A`;`U:A`]) THEN ANTS_TAC THENL
     [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
      ASM_REWRITE_TAC[]];
    ALL_TAC] THEN
  SUBGOAL_THEN `?r. erecres D (E:A->A->bool) ultrastep_form vv d r`
   (X_CHOOSE_THEN `r:A` ASSUME_TAC) THENL
   [MATCH_MP_TAC ERECRES_EXISTS THEN ASM_REWRITE_TAC[] THEN
    ASM_MESON_TAC[ULTRASTEP_QFUN; ULTRASTEP_QTOTAL]; ALL_TAC] THEN
  SUBGOAL_THEN
   `!x. x IN D /\ (E:A->A->bool) x B
        ==> E x U \/ ?y. ecompl D E B leq x y /\ E y U`
   (LABEL_TAC "dich") THENL
   [X_GEN_TAC `x:A` THEN STRIP_TAC THEN
    SUBGOAL_THEN `?xi. xi IN D /\ (E:A->A->bool) xi d /\ eapply D E f xi x`
     (X_CHOOSE_THEN `xi:A` STRIP_ASSUME_TAC) THENL
     [ASM_MESON_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN `eordinal D (E:A->A->bool) xi` ASSUME_TAC THENL
     [ASM_MESON_TAC[EORDINAL_MEMBER]; ALL_TAC] THEN
    MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`vv:num->A`;`xi:A`]
      EULTRAREC_EXISTS) THEN
    ANTS_TAC THENL
     [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
      DISCH_THEN(X_CHOOSE_THEN `Fv:A` STRIP_ASSUME_TAC)] THEN
    SUBGOAL_THEN `efilter D (E:A->A->bool) ((vv:num->A) 4) (vv 5) Fv`
     ASSUME_TAC THENL
     [USE_THEN "pfilt" (MP_TAC o SPECL[`xi:A`;`Fv:A`]) THEN ANTS_TAC THENL
       [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
        DISCH_THEN(ACCEPT_TAC o CONJUNCT1)];
      ALL_TAC] THEN
    MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`bot:A`;`top:A`;
      `Fv:A`;`x:A`] DEC_EXISTS) THEN
    ANTS_TAC THENL
     [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
      DISCH_THEN(X_CHOOSE_THEN `e:A` (CONJUNCTS_THEN2 ASSUME_TAC
        (CONJUNCTS_THEN2 ASSUME_TAC (LABEL_TAC "dec"))))] THEN
    MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`vv:num->A`;`xi:A`;`d:A`;
      `Fv:A`;`x:A`;`e:A`;`U:A`;`r:A`] EULTRAREC_DECLATER) THEN
    ANTS_TAC THENL
     [REPEAT CONJ_TAC THEN TRY(FIRST_ASSUM ACCEPT_TAC) THEN
      ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[];
      DISCH_TAC] THEN
    USE_THEN "dec" (DISJ_CASES_THEN STRIP_ASSUME_TAC) THENL
     [DISJ1_TAC THEN ASM_MESON_TAC[];
      DISJ2_TAC THEN EXISTS_TAC `e:A` THEN CONJ_TAC THENL
       [REWRITE_TAC[ecompl] THEN ASM_REWRITE_TAC[] THEN
        MAP_EVERY EXISTS_TAC [`bot:A`;`top:A`] THEN ASM_REWRITE_TAC[];
        FIRST_ASSUM ACCEPT_TAC]];
    ALL_TAC] THEN
  EXISTS_TAC `U:A` THEN CONJ_TAC THENL
   [FIRST_ASSUM ACCEPT_TAC;
    REWRITE_TAC[eultra] THEN REPEAT CONJ_TAC THENL
     [FIRST_ASSUM ACCEPT_TAC;
      ASM_MESON_TAC[EBOT_UNIQUE];
      USE_THEN "dich" ACCEPT_TAC]]);;

(* F8 capstone: the eultra hypothesis of FORCE_ZFC_OVER_VL_U discharged.
   In a model of ZF + V=L, forcing with any nontrivial internal cBa yields
   a quotient model of ZFC (with the witnessing internal ultrafilter U).   *)
let FORCE_ZFC_OVER_VL = prove
 (`!D (E:A->A->bool) B leq bot top.
      model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
      ebot D E B leq bot /\ etop D E B leq top /\ ~(bot = top) /\
      (!u. u IN D ==> elmem D E u)
      ==> ?U. U IN D /\ eultra D E B leq U /\
              model (qdom D E B leq U) (qmem D E B leq U)
                    (choice_ax INSERT ZF_AX)`,
  REPEAT STRIP_TAC THEN
  MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`bot:A`;`top:A`]
    EULTRA_EXISTS) THEN
  ANTS_TAC THENL
   [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `U:A` STRIP_ASSUME_TAC) THEN
  EXISTS_TAC `U:A` THEN ASM_REWRITE_TAC[] THEN
  MATCH_MP_TAC FORCE_ZFC_OVER_VL_U THEN ASM_REWRITE_TAC[]);;

(* ===================================================================== *)
(* CCC development: the Cohen algebra satisfies the ccc.                 *)
(* F2.0: internal Kuratowski finiteness efin + closure kit (empty,      *)
(* adjoin, binary union, subset) via ZF-separation family surgeries.    *)
(* ===================================================================== *)

(* ===================================================================== *)
(* F2.0: internal finiteness in Kuratowski form.  efin p                 *)
(* quantifies over internal families of subsets of p containing empty    *)
(* and closed under adjoining elements of p; the forall-family does all  *)
(* induction internally, so NO internal arithmetic and NO meta/omega     *)
(* induction is ever needed.  Kit: eadjoin (x u {u}) + EFIN_EMPTY +      *)
(* EFIN_ADJOIN (family surgery via ZF_SEPARATION with adjfam_form).      *)
(* ===================================================================== *)
let EBUNION_MEM = prove
 (`!D (E:A->A->bool) x y z.
      model D E ZF_AX /\ x IN D /\ y IN D /\ ebunion D E x y z
      ==> z IN D /\ !w. w IN D ==> (E w z <=> E w x \/ E w y)`,
  REPEAT GEN_TAC THEN REWRITE_TAC[ebunion] THEN
  DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC (CONJUNCTS_THEN2 ASSUME_TAC
    (CONJUNCTS_THEN2 ASSUME_TAC (X_CHOOSE_THEN `p:A` STRIP_ASSUME_TAC)))) THEN
  SUBGOAL_THEN `(p:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[EPAIR_IN]; ALL_TAC] THEN
  CONJ_TAC THENL [ASM_MESON_TAC[EUNION_IN]; ALL_TAC] THEN
  X_GEN_TAC `w:A` THEN DISCH_TAC THEN
  RULE_ASSUM_TAC(REWRITE_RULE[eunion; epair]) THEN ASM_MESON_TAC[]);;

let eadjoin = new_definition
  `eadjoin D (E:A->A->bool) x u y <=>
     ?s. epair D E u u s /\ ebunion D E x s y`;;

let EADJOIN_EXISTS = prove
 (`!D (E:A->A->bool) x u.
      model D E ZF_AX /\ x IN D /\ u IN D ==> ?y. eadjoin D E x u y`,
  REWRITE_TAC[eadjoin] THEN
  MESON_TAC[EPAIR_EXISTS; EBUNION_EXISTS; EPAIR_IN]);;

let EADJOIN_IN = prove
 (`!D (E:A->A->bool) x u y. eadjoin D E x u y ==> y IN D`,
  REWRITE_TAC[eadjoin; ebunion] THEN MESON_TAC[EUNION_IN]);;

let EADJOIN_UNIQUE = prove
 (`!D (E:A->A->bool) x u y y'.
      model D E ZF_AX /\ eadjoin D E x u y /\ eadjoin D E x u y' ==> y = y'`,
  REWRITE_TAC[eadjoin] THEN MESON_TAC[EPAIR_UNIQUE; EBUNION_UNIQUE]);;

let EADJOIN_MEM = prove
 (`!D (E:A->A->bool) x u y.
      model D E ZF_AX /\ x IN D /\ u IN D /\ eadjoin D E x u y
      ==> y IN D /\ !w. w IN D ==> (E w y <=> E w x \/ w = u)`,
  REPEAT GEN_TAC THEN REWRITE_TAC[eadjoin] THEN
  DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC (CONJUNCTS_THEN2 ASSUME_TAC
    (CONJUNCTS_THEN2 ASSUME_TAC (X_CHOOSE_THEN `s:A` STRIP_ASSUME_TAC)))) THEN
  SUBGOAL_THEN `(s:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[EPAIR_IN]; ALL_TAC] THEN
  MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`x:A`;`s:A`;`y:A`] EBUNION_MEM) THEN
  ASM_REWRITE_TAC[] THEN STRIP_TAC THEN ASM_REWRITE_TAC[] THEN
  X_GEN_TAC `w:A` THEN DISCH_TAC THEN
  FIRST_X_ASSUM(MP_TAC o SPEC `w:A`) THEN ASM_REWRITE_TAC[] THEN
  DISCH_THEN SUBST1_TAC THEN
  RULE_ASSUM_TAC(REWRITE_RULE[epair]) THEN ASM_MESON_TAC[]);;

let EADJOIN_CHAR = prove
 (`!D (E:A->A->bool) x u y.
      model D E ZF_AX /\ x IN D /\ u IN D /\ y IN D
      ==> (eadjoin D E x u y <=>
           !m. m IN D ==> (E m y <=> E m x \/ m = u))`,
  REPEAT STRIP_TAC THEN EQ_TAC THENL
   [DISCH_TAC THEN
    MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`x:A`;`u:A`;`y:A`]
      EADJOIN_MEM) THEN
    ASM_REWRITE_TAC[] THEN MESON_TAC[];
    DISCH_TAC THEN
    SUBGOAL_THEN `?y'. eadjoin D (E:A->A->bool) x u y'`
     (X_CHOOSE_TAC `y':A`) THENL
     [ASM_MESON_TAC[EADJOIN_EXISTS]; ALL_TAC] THEN
    SUBGOAL_THEN `y':A = y` (fun th -> ASM_MESON_TAC[th]) THEN
    FIRST_ASSUM(MATCH_MP_TAC o MATCH_MP ZF_EXTENSIONALITY) THEN
    SUBGOAL_THEN `(y':A) IN D` ASSUME_TAC THENL
     [ASM_MESON_TAC[EADJOIN_IN]; ALL_TAC] THEN
    ASM_REWRITE_TAC[] THEN
    MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`x:A`;`u:A`;`y':A`]
      EADJOIN_MEM) THEN
    ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[]]);;

let EEMPTY_SUBSET = prove
 (`!D (E:A->A->bool) z x. eempty D E z ==> esubset D E z x`,
  REWRITE_TAC[eempty; esubset] THEN MESON_TAC[]);;

(* Kuratowski finiteness: p is in every internal family of subsets of p  *)
(* containing the empty set and closed under adjoining elements of p.    *)
let efin = new_definition
  `efin D (E:A->A->bool) p <=>
     p IN D /\
     !fam. fam IN D /\
           (!x. x IN D /\ E x fam ==> esubset D E x p) /\
           (?z. z IN D /\ eempty D E z /\ E z fam) /\
           (!x u y. x IN D /\ u IN D /\ y IN D /\ E x fam /\ E u p /\
                    eadjoin D E x u y ==> E y fam)
           ==> E p fam`;;

let EFIN_EMPTY = prove
 (`!D (E:A->A->bool) p. model D E ZF_AX /\ eempty D E p ==> efin D E p`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[efin] THEN CONJ_TAC THENL
   [ASM_MESON_TAC[EEMPTY_IN]; ALL_TAC] THEN
  X_GEN_TAC `fam:A` THEN STRIP_TAC THEN ASM_MESON_TAC[EEMPTY_UNIQUE]);;

(* Separation formula for the EFIN_ADJOIN family surgery: slot 20 = the  *)
(* separation variable w; parameters 18 = u, 19 = fam; says              *)
(* ?w'. w' = w adjoin u /\ w' IN fam.                                    *)
let adjfam_form = new_definition
  `adjfam_form =
     ?? 21 ((!! 22 ((22 %% 21) <-> ((22 %% 20) || Eq 22 18))) &&
            (21 %% 19))`;;

let ADJFAM_HOLDS = prove
 (`!D (E:A->A->bool) v w.
      model D E ZF_AX /\ valuation D v /\ w IN D
      ==> (holds D E ((20 |-> w) v) adjfam_form <=>
           ?w'. w' IN D /\
                (!m. m IN D ==> (E m w' <=> E m w \/ m = v 18)) /\
                E w' (v 19))`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[adjfam_form] THEN
  SUBGOAL_THEN `valuation D ((20 |-> (w:A)) v)` ASSUME_TAC THENL
   [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
  REWRITE_TAC[HOLDS_EX] THEN
  SUBGOAL_THEN
   `!w':A. w' IN D
      ==> (holds D E ((21 |-> w') ((20 |-> (w:A)) v))
             ((!! 22 ((22 %% 21) <-> ((22 %% 20) || Eq 22 18))) &&
              (21 %% 19)) <=>
           (!m. m IN D ==> (E m w' <=> E m w \/ m = v 18)) /\
           E w' (v 19))`
   (LABEL_TAC "body") THENL
   [X_GEN_TAC `w':A` THEN DISCH_TAC THEN
    SUBGOAL_THEN `valuation D ((21 |-> (w':A)) ((20 |-> (w:A)) v))`
     ASSUME_TAC THENL [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
    ASM_SIMP_TAC[HOLDS_AND; HOLDS_ALL] THEN
    SUBGOAL_THEN
     `!m:A. m IN D
        ==> (holds D E ((22 |-> m) ((21 |-> (w':A)) ((20 |-> (w:A)) v)))
               ((22 %% 21) <-> ((22 %% 20) || Eq 22 18)) <=>
             (E m w' <=> E m w \/ m = v 18))`
     (LABEL_TAC "inner") THENL
     [X_GEN_TAC `m:A` THEN DISCH_TAC THEN
      REWRITE_TAC[HOLDS_IFF; HOLDS_OR; HOLDS_MEM; holds] THEN
      REWRITE_TAC[VALMOD; ARITH_EQ];
      ALL_TAC] THEN
    SUBGOAL_THEN
     `holds D E ((21 |-> (w':A)) ((20 |-> (w:A)) v)) (21 %% 19) <=>
      E w' (v 19)` SUBST1_TAC THENL
     [REWRITE_TAC[HOLDS_MEM] THEN REWRITE_TAC[VALMOD; ARITH_EQ];
      ALL_TAC] THEN
    ASM_SIMP_TAC[];
    ALL_TAC] THEN
  EQ_TAC THENL
   [DISCH_THEN(X_CHOOSE_THEN `w':A` STRIP_ASSUME_TAC) THEN
    EXISTS_TAC `w':A` THEN ASM_REWRITE_TAC[] THEN
    USE_THEN "body" (MP_TAC o SPEC `w':A`) THEN ANTS_TAC THENL
     [FIRST_ASSUM ACCEPT_TAC;
      DISCH_THEN(fun th -> ASM_MESON_TAC[th])];
    DISCH_THEN(X_CHOOSE_THEN `w':A` STRIP_ASSUME_TAC) THEN
    EXISTS_TAC `w':A` THEN ASM_REWRITE_TAC[] THEN
    USE_THEN "body" (MP_TAC o SPEC `w':A`) THEN ANTS_TAC THENL
     [FIRST_ASSUM ACCEPT_TAC;
      DISCH_THEN(fun th -> ASM_MESON_TAC[th])]]);;

(* Adjoining one element preserves finiteness.  Family surgery: given a  *)
(* family fam witnessing-for q = p u {u}, separation over pow p builds   *)
(* fam' = { w SUBSET p : ?w'. w' = w adjoin u /\ w' IN fam }; the K-     *)
(* property of p applied to fam' yields p IN fam', hence q IN fam.       *)
(* LESSON: discharge fc/body instances with ANTS_TAC, never bare         *)
(* ASM_REWRITE (self-rewrite); the final iff-of-existentials goes by     *)
(* EXISTS_AND_CONG + TAUT congruence + EADJOIN_CHAR, NOT by ASM_MESON     *)
(* (diverges: 9M+ steps before interrupt).                               *)
let EFIN_ADJOIN = prove
 (`!D (E:A->A->bool) p u q.
      model D E ZF_AX /\ efin D E p /\ u IN D /\ eadjoin D E p u q
      ==> efin D E q`,
  REPEAT GEN_TAC THEN
  DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC
   (CONJUNCTS_THEN2 (CONJUNCTS_THEN2 ASSUME_TAC (LABEL_TAC "kp") o
                     REWRITE_RULE[efin])
    (CONJUNCTS_THEN2 ASSUME_TAC ASSUME_TAC))) THEN
  SUBGOAL_THEN `(q:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[EADJOIN_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `!w:A. w IN D ==> ((E:A->A->bool) w q <=> E w p \/ w = u)`
   (LABEL_TAC "qm") THENL
   [MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`p:A`;`u:A`;`q:A`]
      EADJOIN_MEM) THEN ASM_REWRITE_TAC[] THEN MESON_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) u q` ASSUME_TAC THENL
   [USE_THEN "qm" (MP_TAC o SPEC `u:A`) THEN ANTS_TAC THENL
     [FIRST_ASSUM ACCEPT_TAC; DISCH_THEN(fun th -> REWRITE_TAC[th])] THEN
    DISJ2_TAC THEN REFL_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN `!w:A. w IN D /\ (E:A->A->bool) w p ==> E w q`
   (LABEL_TAC "pq") THENL [ASM_MESON_TAC[]; ALL_TAC] THEN
  REWRITE_TAC[efin] THEN CONJ_TAC THENL
   [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  X_GEN_TAC `fam:A` THEN
  DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC
   (CONJUNCTS_THEN2 (LABEL_TAC "fsub")
    (CONJUNCTS_THEN2 (X_CHOOSE_THEN `z0:A` STRIP_ASSUME_TAC)
     (LABEL_TAC "fadj")))) THEN
  SUBGOAL_THEN `?pp. epow D (E:A->A->bool) p pp`
   (X_CHOOSE_THEN `pp:A` (LABEL_TAC "pw")) THENL
   [ASM_MESON_TAC[EPOW_EXISTS]; ALL_TAC] THEN
  SUBGOAL_THEN `(pp:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[EPOW_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `valuation D ((18 |-> (u:A)) ((19 |-> (fam:A)) (\n. u)))`
   ASSUME_TAC THENL
   [REPEAT(MATCH_MP_TAC VALUATION_VALMOD THEN CONJ_TAC THENL
      [ALL_TAC; FIRST_ASSUM ACCEPT_TAC]) THEN
    REWRITE_TAC[valuation] THEN FIRST_ASSUM ACCEPT_TAC;
    ALL_TAC] THEN
  MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`] ZF_SEPARATION) THEN
  ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  DISCH_THEN(MP_TAC o ISPECL
    [`adjfam_form`; `20`;
     `(18 |-> (u:A)) ((19 |-> (fam:A)) (\n. u))`; `pp:A`]) THEN
  ANTS_TAC THENL
   [CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
    DISCH_THEN(X_CHOOSE_THEN `fam':A`
      (CONJUNCTS_THEN2 ASSUME_TAC (LABEL_TAC "sep")))] THEN
  SUBGOAL_THEN
   `!z:A. z IN D
      ==> ((E:A->A->bool) z fam' <=>
           esubset D E z p /\
           ?w'. w' IN D /\ eadjoin D E z u w' /\ E w' fam)`
   (LABEL_TAC "fc") THENL
   [X_GEN_TAC `z:A` THEN DISCH_TAC THEN
    USE_THEN "sep" (MP_TAC o SPEC `z:A`) THEN ANTS_TAC THENL
     [FIRST_ASSUM ACCEPT_TAC; DISCH_THEN(fun th -> REWRITE_TAC[th])] THEN
    MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;
      `(18 |-> (u:A)) ((19 |-> (fam:A)) (\n. u))`;`z:A`] ADJFAM_HOLDS) THEN
    ANTS_TAC THENL
     [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
      DISCH_THEN(fun th -> REWRITE_TAC[th])] THEN
    REWRITE_TAC[VALMOD; ARITH_EQ] THEN
    USE_THEN "pw" (MP_TAC o REWRITE_RULE[epow]) THEN
    DISCH_THEN(MP_TAC o SPEC `z:A` o CONJUNCT2) THEN ANTS_TAC THENL
     [FIRST_ASSUM ACCEPT_TAC; DISCH_THEN(fun th -> REWRITE_TAC[th])] THEN
    MATCH_MP_TAC(TAUT `(b <=> c) ==> ((a /\ b) <=> (a /\ c))`) THEN
    MATCH_MP_TAC EXISTS_AND_CONG THEN
    X_GEN_TAC `w':A` THEN DISCH_TAC THEN
    MATCH_MP_TAC(TAUT `(p <=> q) ==> ((p /\ r) <=> (q /\ r))`) THEN
    MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`z:A`;`u:A`;`w':A`]
      EADJOIN_CHAR) THEN
    ANTS_TAC THENL
     [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
      DISCH_THEN(fun th -> REWRITE_TAC[GSYM th])];
    ALL_TAC] THEN
  USE_THEN "kp" (MP_TAC o SPEC `fam':A`) THEN ANTS_TAC THENL
   [CONJ_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    CONJ_TAC THENL
     [X_GEN_TAC `x:A` THEN STRIP_TAC THEN
      USE_THEN "fc" (MP_TAC o SPEC `x:A`) THEN ANTS_TAC THENL
       [FIRST_ASSUM ACCEPT_TAC;
        DISCH_THEN(fun th ->
          MP_TAC(EQ_MP th (ASSUME `(E:A->A->bool) x fam'`)))] THEN
      DISCH_THEN(ACCEPT_TAC o CONJUNCT1);
      ALL_TAC] THEN
    CONJ_TAC THENL
     [SUBGOAL_THEN `?su. eadjoin D (E:A->A->bool) z0 u su`
       (X_CHOOSE_TAC `su:A`) THENL
       [ASM_MESON_TAC[EADJOIN_EXISTS]; ALL_TAC] THEN
      SUBGOAL_THEN `(su:A) IN D` ASSUME_TAC THENL
       [ASM_MESON_TAC[EADJOIN_IN]; ALL_TAC] THEN
      SUBGOAL_THEN `(E:A->A->bool) su fam` ASSUME_TAC THENL
       [USE_THEN "fadj" (MP_TAC o SPECL[`z0:A`;`u:A`;`su:A`]) THEN
        ANTS_TAC THENL
         [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
          DISCH_THEN ACCEPT_TAC];
        ALL_TAC] THEN
      EXISTS_TAC `z0:A` THEN REPEAT CONJ_TAC THENL
       [FIRST_ASSUM ACCEPT_TAC;
        FIRST_ASSUM ACCEPT_TAC;
        USE_THEN "fc" (MP_TAC o SPEC `z0:A`) THEN ANTS_TAC THENL
         [FIRST_ASSUM ACCEPT_TAC;
          DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN CONJ_TAC THENL
           [MATCH_MP_TAC EEMPTY_SUBSET THEN FIRST_ASSUM ACCEPT_TAC;
            EXISTS_TAC `su:A` THEN REPEAT CONJ_TAC THEN
            FIRST_ASSUM ACCEPT_TAC]]];
      MAP_EVERY X_GEN_TAC [`x:A`;`v:A`;`y:A`] THEN STRIP_TAC THEN
      USE_THEN "fc" (MP_TAC o SPEC `x:A`) THEN ANTS_TAC THENL
       [FIRST_ASSUM ACCEPT_TAC;
        DISCH_THEN(fun th ->
          MP_TAC(EQ_MP th (ASSUME `(E:A->A->bool) x fam'`)))] THEN
      DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "xsub")
        (X_CHOOSE_THEN `w':A` STRIP_ASSUME_TAC)) THEN
      SUBGOAL_THEN
       `!m:A. m IN D ==> ((E:A->A->bool) m y <=> E m x \/ m = v)`
       (LABEL_TAC "ym") THENL
       [MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`x:A`;`v:A`;`y:A`]
          EADJOIN_MEM) THEN ASM_REWRITE_TAC[] THEN MESON_TAC[];
        ALL_TAC] THEN
      SUBGOAL_THEN
       `!m:A. m IN D ==> ((E:A->A->bool) m w' <=> E m x \/ m = u)`
       (LABEL_TAC "wm") THENL
       [MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`x:A`;`u:A`;`w':A`]
          EADJOIN_MEM) THEN ASM_REWRITE_TAC[] THEN MESON_TAC[];
        ALL_TAC] THEN
      SUBGOAL_THEN `esubset D (E:A->A->bool) y p` ASSUME_TAC THENL
       [REWRITE_TAC[esubset] THEN X_GEN_TAC `m:A` THEN STRIP_TAC THEN
        USE_THEN "ym" (MP_TAC o SPEC `m:A`) THEN ANTS_TAC THENL
         [FIRST_ASSUM ACCEPT_TAC;
          DISCH_THEN(fun th ->
            MP_TAC(EQ_MP th (ASSUME `(E:A->A->bool) m y`)))] THEN
        STRIP_TAC THENL
         [USE_THEN "xsub" (MP_TAC o REWRITE_RULE[esubset]) THEN
          DISCH_THEN(MP_TAC o SPEC `m:A`) THEN ASM_REWRITE_TAC[];
          ASM_REWRITE_TAC[]];
        ALL_TAC] THEN
      SUBGOAL_THEN `?y'. eadjoin D (E:A->A->bool) w' v y'`
       (X_CHOOSE_TAC `y':A`) THENL
       [ASM_MESON_TAC[EADJOIN_EXISTS]; ALL_TAC] THEN
      SUBGOAL_THEN `(y':A) IN D` ASSUME_TAC THENL
       [ASM_MESON_TAC[EADJOIN_IN]; ALL_TAC] THEN
      SUBGOAL_THEN
       `!m:A. m IN D ==> ((E:A->A->bool) m y' <=> E m w' \/ m = v)`
       (LABEL_TAC "y'm") THENL
       [MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`w':A`;`v:A`;`y':A`]
          EADJOIN_MEM) THEN ASM_REWRITE_TAC[] THEN MESON_TAC[];
        ALL_TAC] THEN
      SUBGOAL_THEN `eadjoin D (E:A->A->bool) y u y'` ASSUME_TAC THENL
       [MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`y:A`;`u:A`;`y':A`]
          EADJOIN_CHAR) THEN
        ANTS_TAC THENL
         [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
          DISCH_THEN(fun th -> REWRITE_TAC[th])] THEN
        X_GEN_TAC `m:A` THEN DISCH_TAC THEN
        USE_THEN "y'm" (MP_TAC o SPEC `m:A`) THEN ANTS_TAC THENL
         [FIRST_ASSUM ACCEPT_TAC;
          DISCH_THEN(fun th -> REWRITE_TAC[th])] THEN
        USE_THEN "wm" (MP_TAC o SPEC `m:A`) THEN ANTS_TAC THENL
         [FIRST_ASSUM ACCEPT_TAC;
          DISCH_THEN(fun th -> REWRITE_TAC[th])] THEN
        USE_THEN "ym" (MP_TAC o SPEC `m:A`) THEN ANTS_TAC THENL
         [FIRST_ASSUM ACCEPT_TAC;
          DISCH_THEN(fun th -> REWRITE_TAC[th])] THEN
        MESON_TAC[];
        ALL_TAC] THEN
      SUBGOAL_THEN `(E:A->A->bool) y' fam` ASSUME_TAC THENL
       [USE_THEN "fadj" (MP_TAC o SPECL[`w':A`;`v:A`;`y':A`]) THEN
        ANTS_TAC THENL
         [REPEAT CONJ_TAC THEN TRY(FIRST_ASSUM ACCEPT_TAC) THEN
          USE_THEN "pq" (MP_TAC o SPEC `v:A`) THEN ANTS_TAC THENL
           [CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
            DISCH_THEN ACCEPT_TAC];
          DISCH_THEN ACCEPT_TAC];
        ALL_TAC] THEN
      USE_THEN "fc" (MP_TAC o SPEC `y:A`) THEN ANTS_TAC THENL
       [FIRST_ASSUM ACCEPT_TAC;
        DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN CONJ_TAC THENL
         [FIRST_ASSUM ACCEPT_TAC;
          EXISTS_TAC `y':A` THEN REPEAT CONJ_TAC THEN
          FIRST_ASSUM ACCEPT_TAC]]];
    DISCH_TAC THEN
    USE_THEN "fc" (MP_TAC o SPEC `p:A`) THEN ANTS_TAC THENL
     [FIRST_ASSUM ACCEPT_TAC;
      DISCH_THEN(fun th ->
        MP_TAC(EQ_MP th (ASSUME `(E:A->A->bool) p fam'`)))] THEN
    DISCH_THEN(CONJUNCTS_THEN2 (K ALL_TAC)
      (X_CHOOSE_THEN `w0:A` STRIP_ASSUME_TAC)) THEN
    MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`p:A`;`u:A`;`w0:A`;`q:A`]
      EADJOIN_UNIQUE) THEN
    ANTS_TAC THENL
     [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
      DISCH_THEN SUBST_ALL_TAC] THEN
    FIRST_ASSUM ACCEPT_TAC]);;

(* F2.0 part 2: EBUNION_CHAR, the bunfam/intfam separation bridges,      *)
(* EFIN_ABSFAM (K-finite q lands in any adjoin-closed family over a      *)
(* larger carrier), EFIN_UNION2, EINTER_CHAR, EFIN_SUBSET.               *)
(* LESSON (STRIP-branch-count): STRIP_ASSUME_TAC auto-closes a case      *)
(* whose assumed disjunct equals the goal, so THENL after STRIP_TAC on   *)
(* (a \/ goal ==> goal) sees ONE subgoal, not two.                       *)
let EBUNION_CHAR = prove
 (`!D (E:A->A->bool) x y z.
      model D E ZF_AX /\ x IN D /\ y IN D /\ z IN D
      ==> (ebunion D E x y z <=>
           !m. m IN D ==> (E m z <=> E m x \/ E m y))`,
  REPEAT STRIP_TAC THEN EQ_TAC THENL
   [DISCH_TAC THEN
    MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`x:A`;`y:A`;`z:A`]
      EBUNION_MEM) THEN
    ASM_REWRITE_TAC[] THEN MESON_TAC[];
    DISCH_TAC THEN
    SUBGOAL_THEN `?z'. ebunion D (E:A->A->bool) x y z'`
     (X_CHOOSE_TAC `z':A`) THENL
     [ASM_MESON_TAC[EBUNION_EXISTS]; ALL_TAC] THEN
    SUBGOAL_THEN `z':A = z` (fun th -> ASM_MESON_TAC[th]) THEN
    FIRST_ASSUM(MATCH_MP_TAC o MATCH_MP ZF_EXTENSIONALITY) THEN
    SUBGOAL_THEN `(z':A) IN D` ASSUME_TAC THENL
     [ASM_MESON_TAC[EBUNION_IN]; ALL_TAC] THEN
    ASM_REWRITE_TAC[] THEN
    MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`x:A`;`y:A`;`z':A`]
      EBUNION_MEM) THEN
    ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[]]);;

let bunfam_form = new_definition
  `bunfam_form =
     ?? 21 ((!! 22 ((22 %% 21) <-> ((22 %% 20) || (22 %% 18)))) &&
            (21 %% 19))`;;

let BUNFAM_HOLDS = prove
 (`!D (E:A->A->bool) v w.
      model D E ZF_AX /\ valuation D v /\ w IN D
      ==> (holds D E ((20 |-> w) v) bunfam_form <=>
           ?w'. w' IN D /\
                (!m. m IN D ==> (E m w' <=> E m w \/ E m (v 18))) /\
                E w' (v 19))`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[bunfam_form] THEN
  SUBGOAL_THEN `valuation D ((20 |-> (w:A)) v)` ASSUME_TAC THENL
   [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
  REWRITE_TAC[HOLDS_EX] THEN
  SUBGOAL_THEN
   `!w':A. w' IN D
      ==> (holds D E ((21 |-> w') ((20 |-> (w:A)) v))
             ((!! 22 ((22 %% 21) <-> ((22 %% 20) || (22 %% 18)))) &&
              (21 %% 19)) <=>
           (!m. m IN D ==> (E m w' <=> E m w \/ E m (v 18))) /\
           E w' (v 19))`
   (LABEL_TAC "body") THENL
   [X_GEN_TAC `w':A` THEN DISCH_TAC THEN
    SUBGOAL_THEN `valuation D ((21 |-> (w':A)) ((20 |-> (w:A)) v))`
     ASSUME_TAC THENL [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
    ASM_SIMP_TAC[HOLDS_AND; HOLDS_ALL] THEN
    SUBGOAL_THEN
     `!m:A. m IN D
        ==> (holds D E ((22 |-> m) ((21 |-> (w':A)) ((20 |-> (w:A)) v)))
               ((22 %% 21) <-> ((22 %% 20) || (22 %% 18))) <=>
             (E m w' <=> E m w \/ E m (v 18)))`
     (LABEL_TAC "inner") THENL
     [X_GEN_TAC `m:A` THEN DISCH_TAC THEN
      REWRITE_TAC[HOLDS_IFF; HOLDS_OR; HOLDS_MEM] THEN
      REWRITE_TAC[VALMOD; ARITH_EQ];
      ALL_TAC] THEN
    SUBGOAL_THEN
     `holds D E ((21 |-> (w':A)) ((20 |-> (w:A)) v)) (21 %% 19) <=>
      E w' (v 19)` SUBST1_TAC THENL
     [REWRITE_TAC[HOLDS_MEM] THEN REWRITE_TAC[VALMOD; ARITH_EQ];
      ALL_TAC] THEN
    ASM_SIMP_TAC[];
    ALL_TAC] THEN
  EQ_TAC THENL
   [DISCH_THEN(X_CHOOSE_THEN `w':A` STRIP_ASSUME_TAC) THEN
    EXISTS_TAC `w':A` THEN ASM_REWRITE_TAC[] THEN
    USE_THEN "body" (MP_TAC o SPEC `w':A`) THEN ANTS_TAC THENL
     [FIRST_ASSUM ACCEPT_TAC;
      DISCH_THEN(fun th -> ASM_MESON_TAC[th])];
    DISCH_THEN(X_CHOOSE_THEN `w':A` STRIP_ASSUME_TAC) THEN
    EXISTS_TAC `w':A` THEN ASM_REWRITE_TAC[] THEN
    USE_THEN "body" (MP_TAC o SPEC `w':A`) THEN ANTS_TAC THENL
     [FIRST_ASSUM ACCEPT_TAC;
      DISCH_THEN(fun th -> ASM_MESON_TAC[th])]]);;

(* K-finite q is in ANY internal family (over a possibly larger carrier  *)
(* c, q SUBSET c) that contains empty and is closed under adjoining      *)
(* c-elements.  The transfer family is { w SUBSET q : w IN fam }.        *)
let EFIN_ABSFAM = prove
 (`!D (E:A->A->bool) q c fam.
      model D E ZF_AX /\ efin D E q /\ c IN D /\ fam IN D /\
      esubset D E q c /\
      (?z. z IN D /\ eempty D E z /\ E z fam) /\
      (!x u y. x IN D /\ u IN D /\ y IN D /\ E x fam /\ E u c /\
               eadjoin D E x u y ==> E y fam)
      ==> E q fam`,
  REPEAT GEN_TAC THEN
  DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC
   (CONJUNCTS_THEN2 (CONJUNCTS_THEN2 ASSUME_TAC (LABEL_TAC "kq") o
                     REWRITE_RULE[efin])
    (CONJUNCTS_THEN2 ASSUME_TAC
     (CONJUNCTS_THEN2 ASSUME_TAC
      (CONJUNCTS_THEN2 (LABEL_TAC "qc")
       (CONJUNCTS_THEN2 (X_CHOOSE_THEN `z0:A` STRIP_ASSUME_TAC)
        (LABEL_TAC "fadj"))))))) THEN
  SUBGOAL_THEN `?qq. epow D (E:A->A->bool) q qq`
   (X_CHOOSE_THEN `qq:A` (LABEL_TAC "pw")) THENL
   [ASM_MESON_TAC[EPOW_EXISTS]; ALL_TAC] THEN
  SUBGOAL_THEN `(qq:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[EPOW_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `valuation D ((19 |-> (fam:A)) (\n. fam))` ASSUME_TAC THENL
   [MATCH_MP_TAC VALUATION_VALMOD THEN CONJ_TAC THENL
     [REWRITE_TAC[valuation] THEN FIRST_ASSUM ACCEPT_TAC;
      FIRST_ASSUM ACCEPT_TAC];
    ALL_TAC] THEN
  MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`] ZF_SEPARATION) THEN
  ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  DISCH_THEN(MP_TAC o ISPECL
    [`(20 %% 19)`; `20`; `(19 |-> (fam:A)) (\n. fam)`; `qq:A`]) THEN
  ANTS_TAC THENL
   [CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
    DISCH_THEN(X_CHOOSE_THEN `famq:A`
      (CONJUNCTS_THEN2 ASSUME_TAC (LABEL_TAC "sep")))] THEN
  SUBGOAL_THEN
   `!z:A. z IN D
      ==> ((E:A->A->bool) z famq <=> esubset D E z q /\ E z fam)`
   (LABEL_TAC "fc") THENL
   [X_GEN_TAC `z:A` THEN DISCH_TAC THEN
    USE_THEN "sep" (MP_TAC o SPEC `z:A`) THEN ANTS_TAC THENL
     [FIRST_ASSUM ACCEPT_TAC; DISCH_THEN(fun th -> REWRITE_TAC[th])] THEN
    REWRITE_TAC[HOLDS_MEM] THEN REWRITE_TAC[VALMOD; ARITH_EQ] THEN
    USE_THEN "pw" (MP_TAC o REWRITE_RULE[epow]) THEN
    DISCH_THEN(MP_TAC o SPEC `z:A` o CONJUNCT2) THEN ANTS_TAC THENL
     [FIRST_ASSUM ACCEPT_TAC; DISCH_THEN(fun th -> REWRITE_TAC[th])];
    ALL_TAC] THEN
  USE_THEN "kq" (MP_TAC o SPEC `famq:A`) THEN ANTS_TAC THENL
   [CONJ_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    CONJ_TAC THENL
     [X_GEN_TAC `x:A` THEN STRIP_TAC THEN
      USE_THEN "fc" (MP_TAC o SPEC `x:A`) THEN ANTS_TAC THENL
       [FIRST_ASSUM ACCEPT_TAC;
        DISCH_THEN(fun th ->
          MP_TAC(EQ_MP th (ASSUME `(E:A->A->bool) x famq`)))] THEN
      DISCH_THEN(ACCEPT_TAC o CONJUNCT1);
      ALL_TAC] THEN
    CONJ_TAC THENL
     [EXISTS_TAC `z0:A` THEN REPEAT CONJ_TAC THENL
       [FIRST_ASSUM ACCEPT_TAC;
        FIRST_ASSUM ACCEPT_TAC;
        USE_THEN "fc" (MP_TAC o SPEC `z0:A`) THEN ANTS_TAC THENL
         [FIRST_ASSUM ACCEPT_TAC;
          DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN CONJ_TAC THENL
           [MATCH_MP_TAC EEMPTY_SUBSET THEN FIRST_ASSUM ACCEPT_TAC;
            FIRST_ASSUM ACCEPT_TAC]]];
      MAP_EVERY X_GEN_TAC [`x:A`;`v:A`;`y:A`] THEN STRIP_TAC THEN
      USE_THEN "fc" (MP_TAC o SPEC `x:A`) THEN ANTS_TAC THENL
       [FIRST_ASSUM ACCEPT_TAC;
        DISCH_THEN(fun th ->
          MP_TAC(EQ_MP th (ASSUME `(E:A->A->bool) x famq`)))] THEN
      DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "xsub") ASSUME_TAC) THEN
      SUBGOAL_THEN
       `!m:A. m IN D ==> ((E:A->A->bool) m y <=> E m x \/ m = v)`
       (LABEL_TAC "ym") THENL
       [MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`x:A`;`v:A`;`y:A`]
          EADJOIN_MEM) THEN ASM_REWRITE_TAC[] THEN MESON_TAC[];
        ALL_TAC] THEN
      SUBGOAL_THEN `esubset D (E:A->A->bool) y q` ASSUME_TAC THENL
       [REWRITE_TAC[esubset] THEN X_GEN_TAC `m:A` THEN STRIP_TAC THEN
        USE_THEN "ym" (MP_TAC o SPEC `m:A`) THEN ANTS_TAC THENL
         [FIRST_ASSUM ACCEPT_TAC;
          DISCH_THEN(fun th ->
            MP_TAC(EQ_MP th (ASSUME `(E:A->A->bool) m y`)))] THEN
        STRIP_TAC THENL
         [USE_THEN "xsub" (MP_TAC o REWRITE_RULE[esubset]) THEN
          DISCH_THEN(MP_TAC o SPEC `m:A`) THEN ASM_REWRITE_TAC[];
          ASM_REWRITE_TAC[]];
        ALL_TAC] THEN
      USE_THEN "fc" (MP_TAC o SPEC `y:A`) THEN ANTS_TAC THENL
       [FIRST_ASSUM ACCEPT_TAC;
        DISCH_THEN(fun th -> REWRITE_TAC[th])] THEN
      CONJ_TAC THENL
       [FIRST_ASSUM ACCEPT_TAC;
        USE_THEN "fadj" (MP_TAC o SPECL[`x:A`;`v:A`;`y:A`]) THEN
        ANTS_TAC THENL
         [REPEAT CONJ_TAC THEN TRY(FIRST_ASSUM ACCEPT_TAC) THEN
          USE_THEN "qc" (MP_TAC o REWRITE_RULE[esubset]) THEN
          DISCH_THEN(MP_TAC o SPEC `v:A`) THEN ASM_REWRITE_TAC[];
          DISCH_THEN ACCEPT_TAC]]];
    DISCH_TAC THEN
    USE_THEN "fc" (MP_TAC o SPEC `q:A`) THEN ANTS_TAC THENL
     [FIRST_ASSUM ACCEPT_TAC;
      DISCH_THEN(fun th ->
        MP_TAC(EQ_MP th (ASSUME `(E:A->A->bool) q famq`)))] THEN
    DISCH_THEN(ACCEPT_TAC o CONJUNCT2)]);;

let EFIN_UNION2 = prove
 (`!D (E:A->A->bool) p q pq.
      model D E ZF_AX /\ efin D E p /\ efin D E q /\ ebunion D E p q pq
      ==> efin D E pq`,
  REPEAT GEN_TAC THEN
  DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC
   (CONJUNCTS_THEN2 (CONJUNCTS_THEN2 ASSUME_TAC (LABEL_TAC "kp") o
                     REWRITE_RULE[efin])
    (CONJUNCTS_THEN2 (LABEL_TAC "finq") ASSUME_TAC))) THEN
  SUBGOAL_THEN `(q:A) IN D` ASSUME_TAC THENL
   [USE_THEN "finq" (ACCEPT_TAC o CONJUNCT1 o REWRITE_RULE[efin]);
    ALL_TAC] THEN
  SUBGOAL_THEN `(pq:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[EBUNION_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `!w:A. w IN D ==> ((E:A->A->bool) w pq <=> E w p \/ E w q)`
   (LABEL_TAC "pqm") THENL
   [MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`p:A`;`q:A`;`pq:A`]
      EBUNION_MEM) THEN ASM_REWRITE_TAC[] THEN MESON_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `esubset D (E:A->A->bool) q pq` (LABEL_TAC "qpq") THENL
   [REWRITE_TAC[esubset] THEN X_GEN_TAC `m:A` THEN STRIP_TAC THEN
    USE_THEN "pqm" (MP_TAC o SPEC `m:A`) THEN ANTS_TAC THENL
     [FIRST_ASSUM ACCEPT_TAC; DISCH_THEN(fun th -> REWRITE_TAC[th])] THEN
    DISJ2_TAC THEN FIRST_ASSUM ACCEPT_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN `!w:A. w IN D /\ (E:A->A->bool) w p ==> E w pq`
   (LABEL_TAC "ppq") THENL [ASM_MESON_TAC[]; ALL_TAC] THEN
  REWRITE_TAC[efin] THEN CONJ_TAC THENL
   [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  X_GEN_TAC `fam:A` THEN
  DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC
   (CONJUNCTS_THEN2 (LABEL_TAC "fsub")
    (CONJUNCTS_THEN2 (X_CHOOSE_THEN `z0:A` STRIP_ASSUME_TAC)
     (LABEL_TAC "fadj")))) THEN
  SUBGOAL_THEN `(E:A->A->bool) q fam` ASSUME_TAC THENL
   [MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`q:A`;`pq:A`;`fam:A`]
      EFIN_ABSFAM) THEN
    ANTS_TAC THENL
     [REPEAT CONJ_TAC THEN TRY(FIRST_ASSUM ACCEPT_TAC) THEN
      EXISTS_TAC `z0:A` THEN REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
      DISCH_THEN ACCEPT_TAC];
    ALL_TAC] THEN
  SUBGOAL_THEN `?pp. epow D (E:A->A->bool) p pp`
   (X_CHOOSE_THEN `pp:A` (LABEL_TAC "pw")) THENL
   [ASM_MESON_TAC[EPOW_EXISTS]; ALL_TAC] THEN
  SUBGOAL_THEN `(pp:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[EPOW_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `valuation D ((18 |-> (q:A)) ((19 |-> (fam:A)) (\n. q)))`
   ASSUME_TAC THENL
   [REPEAT(MATCH_MP_TAC VALUATION_VALMOD THEN CONJ_TAC THENL
      [ALL_TAC; FIRST_ASSUM ACCEPT_TAC]) THEN
    REWRITE_TAC[valuation] THEN FIRST_ASSUM ACCEPT_TAC;
    ALL_TAC] THEN
  MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`] ZF_SEPARATION) THEN
  ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  DISCH_THEN(MP_TAC o ISPECL
    [`bunfam_form`; `20`;
     `(18 |-> (q:A)) ((19 |-> (fam:A)) (\n. q))`; `pp:A`]) THEN
  ANTS_TAC THENL
   [CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
    DISCH_THEN(X_CHOOSE_THEN `fam':A`
      (CONJUNCTS_THEN2 ASSUME_TAC (LABEL_TAC "sep")))] THEN
  SUBGOAL_THEN
   `!z:A. z IN D
      ==> ((E:A->A->bool) z fam' <=>
           esubset D E z p /\
           ?w'. w' IN D /\ ebunion D E z q w' /\ E w' fam)`
   (LABEL_TAC "fc") THENL
   [X_GEN_TAC `z:A` THEN DISCH_TAC THEN
    USE_THEN "sep" (MP_TAC o SPEC `z:A`) THEN ANTS_TAC THENL
     [FIRST_ASSUM ACCEPT_TAC; DISCH_THEN(fun th -> REWRITE_TAC[th])] THEN
    MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;
      `(18 |-> (q:A)) ((19 |-> (fam:A)) (\n. q))`;`z:A`] BUNFAM_HOLDS) THEN
    ANTS_TAC THENL
     [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
      DISCH_THEN(fun th -> REWRITE_TAC[th])] THEN
    REWRITE_TAC[VALMOD; ARITH_EQ] THEN
    USE_THEN "pw" (MP_TAC o REWRITE_RULE[epow]) THEN
    DISCH_THEN(MP_TAC o SPEC `z:A` o CONJUNCT2) THEN ANTS_TAC THENL
     [FIRST_ASSUM ACCEPT_TAC; DISCH_THEN(fun th -> REWRITE_TAC[th])] THEN
    MATCH_MP_TAC(TAUT `(b <=> c) ==> ((a /\ b) <=> (a /\ c))`) THEN
    MATCH_MP_TAC EXISTS_AND_CONG THEN
    X_GEN_TAC `w':A` THEN DISCH_TAC THEN
    MATCH_MP_TAC(TAUT `(p <=> q) ==> ((p /\ r) <=> (q /\ r))`) THEN
    MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`z:A`;`q:A`;`w':A`]
      EBUNION_CHAR) THEN
    ANTS_TAC THENL
     [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
      DISCH_THEN(fun th -> REWRITE_TAC[GSYM th])];
    ALL_TAC] THEN
  USE_THEN "kp" (MP_TAC o SPEC `fam':A`) THEN ANTS_TAC THENL
   [CONJ_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    CONJ_TAC THENL
     [X_GEN_TAC `x:A` THEN STRIP_TAC THEN
      USE_THEN "fc" (MP_TAC o SPEC `x:A`) THEN ANTS_TAC THENL
       [FIRST_ASSUM ACCEPT_TAC;
        DISCH_THEN(fun th ->
          MP_TAC(EQ_MP th (ASSUME `(E:A->A->bool) x fam'`)))] THEN
      DISCH_THEN(ACCEPT_TAC o CONJUNCT1);
      ALL_TAC] THEN
    CONJ_TAC THENL
     [SUBGOAL_THEN `ebunion D (E:A->A->bool) z0 q q` ASSUME_TAC THENL
       [MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`z0:A`;`q:A`;`q:A`]
          EBUNION_CHAR) THEN
        ANTS_TAC THENL
         [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
          DISCH_THEN(fun th -> REWRITE_TAC[th])] THEN
        X_GEN_TAC `m:A` THEN DISCH_TAC THEN EQ_TAC THENL
         [DISCH_TAC THEN DISJ2_TAC THEN FIRST_ASSUM ACCEPT_TAC;
          STRIP_TAC THEN ASM_MESON_TAC[eempty]];
        ALL_TAC] THEN
      EXISTS_TAC `z0:A` THEN REPEAT CONJ_TAC THENL
       [FIRST_ASSUM ACCEPT_TAC;
        FIRST_ASSUM ACCEPT_TAC;
        USE_THEN "fc" (MP_TAC o SPEC `z0:A`) THEN ANTS_TAC THENL
         [FIRST_ASSUM ACCEPT_TAC;
          DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN CONJ_TAC THENL
           [MATCH_MP_TAC EEMPTY_SUBSET THEN FIRST_ASSUM ACCEPT_TAC;
            EXISTS_TAC `q:A` THEN REPEAT CONJ_TAC THEN
            FIRST_ASSUM ACCEPT_TAC]]];
      MAP_EVERY X_GEN_TAC [`x:A`;`v:A`;`y:A`] THEN STRIP_TAC THEN
      USE_THEN "fc" (MP_TAC o SPEC `x:A`) THEN ANTS_TAC THENL
       [FIRST_ASSUM ACCEPT_TAC;
        DISCH_THEN(fun th ->
          MP_TAC(EQ_MP th (ASSUME `(E:A->A->bool) x fam'`)))] THEN
      DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "xsub")
        (X_CHOOSE_THEN `w':A` STRIP_ASSUME_TAC)) THEN
      SUBGOAL_THEN
       `!m:A. m IN D ==> ((E:A->A->bool) m y <=> E m x \/ m = v)`
       (LABEL_TAC "ym") THENL
       [MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`x:A`;`v:A`;`y:A`]
          EADJOIN_MEM) THEN ASM_REWRITE_TAC[] THEN MESON_TAC[];
        ALL_TAC] THEN
      SUBGOAL_THEN
       `!m:A. m IN D ==> ((E:A->A->bool) m w' <=> E m x \/ E m q)`
       (LABEL_TAC "wm") THENL
       [MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`x:A`;`q:A`;`w':A`]
          EBUNION_MEM) THEN ASM_REWRITE_TAC[] THEN MESON_TAC[];
        ALL_TAC] THEN
      SUBGOAL_THEN `esubset D (E:A->A->bool) y p` ASSUME_TAC THENL
       [REWRITE_TAC[esubset] THEN X_GEN_TAC `m:A` THEN STRIP_TAC THEN
        USE_THEN "ym" (MP_TAC o SPEC `m:A`) THEN ANTS_TAC THENL
         [FIRST_ASSUM ACCEPT_TAC;
          DISCH_THEN(fun th ->
            MP_TAC(EQ_MP th (ASSUME `(E:A->A->bool) m y`)))] THEN
        STRIP_TAC THENL
         [USE_THEN "xsub" (MP_TAC o REWRITE_RULE[esubset]) THEN
          DISCH_THEN(MP_TAC o SPEC `m:A`) THEN ASM_REWRITE_TAC[];
          ASM_REWRITE_TAC[]];
        ALL_TAC] THEN
      SUBGOAL_THEN `?y'. eadjoin D (E:A->A->bool) w' v y'`
       (X_CHOOSE_TAC `y':A`) THENL
       [ASM_MESON_TAC[EADJOIN_EXISTS]; ALL_TAC] THEN
      SUBGOAL_THEN `(y':A) IN D` ASSUME_TAC THENL
       [ASM_MESON_TAC[EADJOIN_IN]; ALL_TAC] THEN
      SUBGOAL_THEN
       `!m:A. m IN D ==> ((E:A->A->bool) m y' <=> E m w' \/ m = v)`
       (LABEL_TAC "y'm") THENL
       [MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`w':A`;`v:A`;`y':A`]
          EADJOIN_MEM) THEN ASM_REWRITE_TAC[] THEN MESON_TAC[];
        ALL_TAC] THEN
      SUBGOAL_THEN `ebunion D (E:A->A->bool) y q y'` ASSUME_TAC THENL
       [MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`y:A`;`q:A`;`y':A`]
          EBUNION_CHAR) THEN
        ANTS_TAC THENL
         [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
          DISCH_THEN(fun th -> REWRITE_TAC[th])] THEN
        X_GEN_TAC `m:A` THEN DISCH_TAC THEN
        USE_THEN "y'm" (MP_TAC o SPEC `m:A`) THEN ANTS_TAC THENL
         [FIRST_ASSUM ACCEPT_TAC;
          DISCH_THEN(fun th -> REWRITE_TAC[th])] THEN
        USE_THEN "wm" (MP_TAC o SPEC `m:A`) THEN ANTS_TAC THENL
         [FIRST_ASSUM ACCEPT_TAC;
          DISCH_THEN(fun th -> REWRITE_TAC[th])] THEN
        USE_THEN "ym" (MP_TAC o SPEC `m:A`) THEN ANTS_TAC THENL
         [FIRST_ASSUM ACCEPT_TAC;
          DISCH_THEN(fun th -> REWRITE_TAC[th])] THEN
        MESON_TAC[];
        ALL_TAC] THEN
      SUBGOAL_THEN `(E:A->A->bool) y' fam` ASSUME_TAC THENL
       [USE_THEN "fadj" (MP_TAC o SPECL[`w':A`;`v:A`;`y':A`]) THEN
        ANTS_TAC THENL
         [REPEAT CONJ_TAC THEN TRY(FIRST_ASSUM ACCEPT_TAC) THEN
          USE_THEN "ppq" (MP_TAC o SPEC `v:A`) THEN ANTS_TAC THENL
           [CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
            DISCH_THEN ACCEPT_TAC];
          DISCH_THEN ACCEPT_TAC];
        ALL_TAC] THEN
      USE_THEN "fc" (MP_TAC o SPEC `y:A`) THEN ANTS_TAC THENL
       [FIRST_ASSUM ACCEPT_TAC;
        DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN CONJ_TAC THENL
         [FIRST_ASSUM ACCEPT_TAC;
          EXISTS_TAC `y':A` THEN REPEAT CONJ_TAC THEN
          FIRST_ASSUM ACCEPT_TAC]]];
    DISCH_TAC THEN
    USE_THEN "fc" (MP_TAC o SPEC `p:A`) THEN ANTS_TAC THENL
     [FIRST_ASSUM ACCEPT_TAC;
      DISCH_THEN(fun th ->
        MP_TAC(EQ_MP th (ASSUME `(E:A->A->bool) p fam'`)))] THEN
    DISCH_THEN(CONJUNCTS_THEN2 (K ALL_TAC)
      (X_CHOOSE_THEN `w0:A` STRIP_ASSUME_TAC)) THEN
    MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`p:A`;`q:A`;`w0:A`;`pq:A`]
      EBUNION_UNIQUE) THEN
    ANTS_TAC THENL
     [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
      DISCH_THEN SUBST_ALL_TAC] THEN
    FIRST_ASSUM ACCEPT_TAC]);;

let intfam_form = new_definition
  `intfam_form =
     ?? 21 ((!! 22 ((22 %% 21) <-> ((22 %% 20) && (22 %% 18)))) &&
            (21 %% 19))`;;

let INTFAM_HOLDS = prove
 (`!D (E:A->A->bool) v w.
      model D E ZF_AX /\ valuation D v /\ w IN D
      ==> (holds D E ((20 |-> w) v) intfam_form <=>
           ?w'. w' IN D /\
                (!m. m IN D ==> (E m w' <=> E m w /\ E m (v 18))) /\
                E w' (v 19))`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[intfam_form] THEN
  SUBGOAL_THEN `valuation D ((20 |-> (w:A)) v)` ASSUME_TAC THENL
   [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
  REWRITE_TAC[HOLDS_EX] THEN
  SUBGOAL_THEN
   `!w':A. w' IN D
      ==> (holds D E ((21 |-> w') ((20 |-> (w:A)) v))
             ((!! 22 ((22 %% 21) <-> ((22 %% 20) && (22 %% 18)))) &&
              (21 %% 19)) <=>
           (!m. m IN D ==> (E m w' <=> E m w /\ E m (v 18))) /\
           E w' (v 19))`
   (LABEL_TAC "body") THENL
   [X_GEN_TAC `w':A` THEN DISCH_TAC THEN
    SUBGOAL_THEN `valuation D ((21 |-> (w':A)) ((20 |-> (w:A)) v))`
     ASSUME_TAC THENL [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
    ASM_SIMP_TAC[HOLDS_AND; HOLDS_ALL] THEN
    SUBGOAL_THEN
     `!m:A. m IN D
        ==> (holds D E ((22 |-> m) ((21 |-> (w':A)) ((20 |-> (w:A)) v)))
               ((22 %% 21) <-> ((22 %% 20) && (22 %% 18))) <=>
             (E m w' <=> E m w /\ E m (v 18)))`
     (LABEL_TAC "inner") THENL
     [X_GEN_TAC `m:A` THEN DISCH_TAC THEN
      REWRITE_TAC[HOLDS_IFF; HOLDS_AND; HOLDS_MEM] THEN
      REWRITE_TAC[VALMOD; ARITH_EQ];
      ALL_TAC] THEN
    SUBGOAL_THEN
     `holds D E ((21 |-> (w':A)) ((20 |-> (w:A)) v)) (21 %% 19) <=>
      E w' (v 19)` SUBST1_TAC THENL
     [REWRITE_TAC[HOLDS_MEM] THEN REWRITE_TAC[VALMOD; ARITH_EQ];
      ALL_TAC] THEN
    ASM_SIMP_TAC[];
    ALL_TAC] THEN
  EQ_TAC THENL
   [DISCH_THEN(X_CHOOSE_THEN `w':A` STRIP_ASSUME_TAC) THEN
    EXISTS_TAC `w':A` THEN ASM_REWRITE_TAC[] THEN
    USE_THEN "body" (MP_TAC o SPEC `w':A`) THEN ANTS_TAC THENL
     [FIRST_ASSUM ACCEPT_TAC;
      DISCH_THEN(fun th -> ASM_MESON_TAC[th])];
    DISCH_THEN(X_CHOOSE_THEN `w':A` STRIP_ASSUME_TAC) THEN
    EXISTS_TAC `w':A` THEN ASM_REWRITE_TAC[] THEN
    USE_THEN "body" (MP_TAC o SPEC `w':A`) THEN ANTS_TAC THENL
     [FIRST_ASSUM ACCEPT_TAC;
      DISCH_THEN(fun th -> ASM_MESON_TAC[th])]]);;

let EINTER_CHAR = prove
 (`!D (E:A->A->bool) x y z.
      model D E ZF_AX /\ x IN D /\ y IN D /\ z IN D
      ==> (einter D E x y z <=>
           !m. m IN D ==> (E m z <=> E m x /\ E m y))`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[einter] THEN ASM_REWRITE_TAC[]);;

(* Subsets of a K-finite set are K-finite.  Family surgery with the      *)
(* intersection map w |-> w INTER s; the adjoin step case-splits on      *)
(* whether the new element lies in s.                                    *)
let EFIN_SUBSET = prove
 (`!D (E:A->A->bool) p s.
      model D E ZF_AX /\ efin D E p /\ s IN D /\ esubset D E s p
      ==> efin D E s`,
  REPEAT GEN_TAC THEN
  DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC
   (CONJUNCTS_THEN2 (CONJUNCTS_THEN2 ASSUME_TAC (LABEL_TAC "kp") o
                     REWRITE_RULE[efin])
    (CONJUNCTS_THEN2 ASSUME_TAC (LABEL_TAC "sp")))) THEN
  REWRITE_TAC[efin] THEN CONJ_TAC THENL
   [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  X_GEN_TAC `fam:A` THEN
  DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC
   (CONJUNCTS_THEN2 (LABEL_TAC "fsub")
    (CONJUNCTS_THEN2 (X_CHOOSE_THEN `z0:A` STRIP_ASSUME_TAC)
     (LABEL_TAC "fadj")))) THEN
  SUBGOAL_THEN `?pp. epow D (E:A->A->bool) p pp`
   (X_CHOOSE_THEN `pp:A` (LABEL_TAC "pw")) THENL
   [ASM_MESON_TAC[EPOW_EXISTS]; ALL_TAC] THEN
  SUBGOAL_THEN `(pp:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[EPOW_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `valuation D ((18 |-> (s:A)) ((19 |-> (fam:A)) (\n. s)))`
   ASSUME_TAC THENL
   [REPEAT(MATCH_MP_TAC VALUATION_VALMOD THEN CONJ_TAC THENL
      [ALL_TAC; FIRST_ASSUM ACCEPT_TAC]) THEN
    REWRITE_TAC[valuation] THEN FIRST_ASSUM ACCEPT_TAC;
    ALL_TAC] THEN
  MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`] ZF_SEPARATION) THEN
  ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  DISCH_THEN(MP_TAC o ISPECL
    [`intfam_form`; `20`;
     `(18 |-> (s:A)) ((19 |-> (fam:A)) (\n. s))`; `pp:A`]) THEN
  ANTS_TAC THENL
   [CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
    DISCH_THEN(X_CHOOSE_THEN `fam':A`
      (CONJUNCTS_THEN2 ASSUME_TAC (LABEL_TAC "sep")))] THEN
  SUBGOAL_THEN
   `!z:A. z IN D
      ==> ((E:A->A->bool) z fam' <=>
           esubset D E z p /\
           ?w'. w' IN D /\ einter D E z s w' /\ E w' fam)`
   (LABEL_TAC "fc") THENL
   [X_GEN_TAC `z:A` THEN DISCH_TAC THEN
    USE_THEN "sep" (MP_TAC o SPEC `z:A`) THEN ANTS_TAC THENL
     [FIRST_ASSUM ACCEPT_TAC; DISCH_THEN(fun th -> REWRITE_TAC[th])] THEN
    MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;
      `(18 |-> (s:A)) ((19 |-> (fam:A)) (\n. s))`;`z:A`] INTFAM_HOLDS) THEN
    ANTS_TAC THENL
     [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
      DISCH_THEN(fun th -> REWRITE_TAC[th])] THEN
    REWRITE_TAC[VALMOD; ARITH_EQ] THEN
    USE_THEN "pw" (MP_TAC o REWRITE_RULE[epow]) THEN
    DISCH_THEN(MP_TAC o SPEC `z:A` o CONJUNCT2) THEN ANTS_TAC THENL
     [FIRST_ASSUM ACCEPT_TAC; DISCH_THEN(fun th -> REWRITE_TAC[th])] THEN
    MATCH_MP_TAC(TAUT `(b <=> c) ==> ((a /\ b) <=> (a /\ c))`) THEN
    MATCH_MP_TAC EXISTS_AND_CONG THEN
    X_GEN_TAC `w':A` THEN DISCH_TAC THEN
    MATCH_MP_TAC(TAUT `(p <=> q) ==> ((p /\ r) <=> (q /\ r))`) THEN
    MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`z:A`;`s:A`;`w':A`]
      EINTER_CHAR) THEN
    ANTS_TAC THENL
     [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
      DISCH_THEN(fun th -> REWRITE_TAC[GSYM th])];
    ALL_TAC] THEN
  USE_THEN "kp" (MP_TAC o SPEC `fam':A`) THEN ANTS_TAC THENL
   [CONJ_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    CONJ_TAC THENL
     [X_GEN_TAC `x:A` THEN STRIP_TAC THEN
      USE_THEN "fc" (MP_TAC o SPEC `x:A`) THEN ANTS_TAC THENL
       [FIRST_ASSUM ACCEPT_TAC;
        DISCH_THEN(fun th ->
          MP_TAC(EQ_MP th (ASSUME `(E:A->A->bool) x fam'`)))] THEN
      DISCH_THEN(ACCEPT_TAC o CONJUNCT1);
      ALL_TAC] THEN
    CONJ_TAC THENL
     [SUBGOAL_THEN `einter D (E:A->A->bool) z0 s z0` ASSUME_TAC THENL
       [REWRITE_TAC[einter] THEN CONJ_TAC THENL
         [FIRST_ASSUM ACCEPT_TAC;
          X_GEN_TAC `m:A` THEN DISCH_TAC THEN EQ_TAC THENL
           [DISCH_TAC THEN ASM_MESON_TAC[eempty];
            DISCH_THEN(ACCEPT_TAC o CONJUNCT1)]];
        ALL_TAC] THEN
      EXISTS_TAC `z0:A` THEN REPEAT CONJ_TAC THENL
       [FIRST_ASSUM ACCEPT_TAC;
        FIRST_ASSUM ACCEPT_TAC;
        USE_THEN "fc" (MP_TAC o SPEC `z0:A`) THEN ANTS_TAC THENL
         [FIRST_ASSUM ACCEPT_TAC;
          DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN CONJ_TAC THENL
           [MATCH_MP_TAC EEMPTY_SUBSET THEN FIRST_ASSUM ACCEPT_TAC;
            EXISTS_TAC `z0:A` THEN REPEAT CONJ_TAC THEN
            FIRST_ASSUM ACCEPT_TAC]]];
      MAP_EVERY X_GEN_TAC [`x:A`;`v:A`;`y:A`] THEN STRIP_TAC THEN
      USE_THEN "fc" (MP_TAC o SPEC `x:A`) THEN ANTS_TAC THENL
       [FIRST_ASSUM ACCEPT_TAC;
        DISCH_THEN(fun th ->
          MP_TAC(EQ_MP th (ASSUME `(E:A->A->bool) x fam'`)))] THEN
      DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "xsub")
        (X_CHOOSE_THEN `w':A` STRIP_ASSUME_TAC)) THEN
      SUBGOAL_THEN
       `!m:A. m IN D ==> ((E:A->A->bool) m y <=> E m x \/ m = v)`
       (LABEL_TAC "ym") THENL
       [MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`x:A`;`v:A`;`y:A`]
          EADJOIN_MEM) THEN ASM_REWRITE_TAC[] THEN MESON_TAC[];
        ALL_TAC] THEN
      SUBGOAL_THEN
       `!m:A. m IN D ==> ((E:A->A->bool) m w' <=> E m x /\ E m s)`
       (LABEL_TAC "wm") THENL
       [MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`x:A`;`s:A`;`w':A`]
          EINTER_CHAR) THEN
        ANTS_TAC THENL
         [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
          DISCH_THEN(fun th ->
            MP_TAC(EQ_MP th
              (ASSUME `einter D (E:A->A->bool) x s w'`))) THEN
          DISCH_THEN ACCEPT_TAC];
        ALL_TAC] THEN
      SUBGOAL_THEN `esubset D (E:A->A->bool) y p` ASSUME_TAC THENL
       [REWRITE_TAC[esubset] THEN X_GEN_TAC `m:A` THEN STRIP_TAC THEN
        USE_THEN "ym" (MP_TAC o SPEC `m:A`) THEN ANTS_TAC THENL
         [FIRST_ASSUM ACCEPT_TAC;
          DISCH_THEN(fun th ->
            MP_TAC(EQ_MP th (ASSUME `(E:A->A->bool) m y`)))] THEN
        STRIP_TAC THENL
         [USE_THEN "xsub" (MP_TAC o REWRITE_RULE[esubset]) THEN
          DISCH_THEN(MP_TAC o SPEC `m:A`) THEN ASM_REWRITE_TAC[];
          ASM_REWRITE_TAC[]];
        ALL_TAC] THEN
      ASM_CASES_TAC `(E:A->A->bool) v s` THENL
       [SUBGOAL_THEN `?y'. eadjoin D (E:A->A->bool) w' v y'`
         (X_CHOOSE_TAC `y':A`) THENL
         [ASM_MESON_TAC[EADJOIN_EXISTS]; ALL_TAC] THEN
        SUBGOAL_THEN `(y':A) IN D` ASSUME_TAC THENL
         [ASM_MESON_TAC[EADJOIN_IN]; ALL_TAC] THEN
        SUBGOAL_THEN
         `!m:A. m IN D ==> ((E:A->A->bool) m y' <=> E m w' \/ m = v)`
         (LABEL_TAC "y'm") THENL
         [MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`w':A`;`v:A`;`y':A`]
            EADJOIN_MEM) THEN ASM_REWRITE_TAC[] THEN MESON_TAC[];
          ALL_TAC] THEN
        SUBGOAL_THEN `einter D (E:A->A->bool) y s y'` ASSUME_TAC THENL
         [MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`y:A`;`s:A`;`y':A`]
            EINTER_CHAR) THEN
          ANTS_TAC THENL
           [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
            DISCH_THEN(fun th -> REWRITE_TAC[th])] THEN
          X_GEN_TAC `m:A` THEN DISCH_TAC THEN
          USE_THEN "y'm" (MP_TAC o SPEC `m:A`) THEN ANTS_TAC THENL
           [FIRST_ASSUM ACCEPT_TAC;
            DISCH_THEN(fun th -> REWRITE_TAC[th])] THEN
          USE_THEN "wm" (MP_TAC o SPEC `m:A`) THEN ANTS_TAC THENL
           [FIRST_ASSUM ACCEPT_TAC;
            DISCH_THEN(fun th -> REWRITE_TAC[th])] THEN
          USE_THEN "ym" (MP_TAC o SPEC `m:A`) THEN ANTS_TAC THENL
           [FIRST_ASSUM ACCEPT_TAC;
            DISCH_THEN(fun th -> REWRITE_TAC[th])] THEN
          MP_TAC(ASSUME `(E:A->A->bool) v s`) THEN MESON_TAC[];
          ALL_TAC] THEN
        SUBGOAL_THEN `(E:A->A->bool) y' fam` ASSUME_TAC THENL
         [USE_THEN "fadj" (MP_TAC o SPECL[`w':A`;`v:A`;`y':A`]) THEN
          ANTS_TAC THENL
           [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
            DISCH_THEN ACCEPT_TAC];
          ALL_TAC] THEN
        USE_THEN "fc" (MP_TAC o SPEC `y:A`) THEN ANTS_TAC THENL
         [FIRST_ASSUM ACCEPT_TAC;
          DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN CONJ_TAC THENL
           [FIRST_ASSUM ACCEPT_TAC;
            EXISTS_TAC `y':A` THEN REPEAT CONJ_TAC THEN
            FIRST_ASSUM ACCEPT_TAC]];
        SUBGOAL_THEN `einter D (E:A->A->bool) y s w'` ASSUME_TAC THENL
         [MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`y:A`;`s:A`;`w':A`]
            EINTER_CHAR) THEN
          ANTS_TAC THENL
           [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
            DISCH_THEN(fun th -> REWRITE_TAC[th])] THEN
          X_GEN_TAC `m:A` THEN DISCH_TAC THEN
          USE_THEN "wm" (MP_TAC o SPEC `m:A`) THEN ANTS_TAC THENL
           [FIRST_ASSUM ACCEPT_TAC;
            DISCH_THEN(fun th -> REWRITE_TAC[th])] THEN
          USE_THEN "ym" (MP_TAC o SPEC `m:A`) THEN ANTS_TAC THENL
           [FIRST_ASSUM ACCEPT_TAC;
            DISCH_THEN(fun th -> REWRITE_TAC[th])] THEN
          MP_TAC(ASSUME `~((E:A->A->bool) v s)`) THEN MESON_TAC[];
          ALL_TAC] THEN
        USE_THEN "fc" (MP_TAC o SPEC `y:A`) THEN ANTS_TAC THENL
         [FIRST_ASSUM ACCEPT_TAC;
          DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN CONJ_TAC THENL
           [FIRST_ASSUM ACCEPT_TAC;
            EXISTS_TAC `w':A` THEN REPEAT CONJ_TAC THEN
            FIRST_ASSUM ACCEPT_TAC]]]];
    DISCH_TAC THEN
    USE_THEN "fc" (MP_TAC o SPEC `p:A`) THEN ANTS_TAC THENL
     [FIRST_ASSUM ACCEPT_TAC;
      DISCH_THEN(fun th ->
        MP_TAC(EQ_MP th (ASSUME `(E:A->A->bool) p fam'`)))] THEN
    DISCH_THEN(CONJUNCTS_THEN2 (K ALL_TAC)
      (X_CHOOSE_THEN `w0:A` STRIP_ASSUME_TAC)) THEN
    SUBGOAL_THEN `w0:A = s` SUBST_ALL_TAC THENL
     [FIRST_ASSUM(MATCH_MP_TAC o MATCH_MP ZF_EXTENSIONALITY) THEN
      ASM_REWRITE_TAC[] THEN X_GEN_TAC `m:A` THEN DISCH_TAC THEN
      SUBGOAL_THEN
       `!mm:A. mm IN D ==> ((E:A->A->bool) mm w0 <=> E mm p /\ E mm s)`
       (MP_TAC o SPEC `m:A`) THENL
       [MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`p:A`;`s:A`;`w0:A`]
          EINTER_CHAR) THEN
        ANTS_TAC THENL
         [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
          DISCH_THEN(fun th ->
            MP_TAC(EQ_MP th
              (ASSUME `einter D (E:A->A->bool) p s w0`))) THEN
          DISCH_THEN ACCEPT_TAC];
        ALL_TAC] THEN
      ANTS_TAC THENL
       [FIRST_ASSUM ACCEPT_TAC; DISCH_THEN(fun th -> REWRITE_TAC[th])] THEN
      USE_THEN "sp" (MP_TAC o REWRITE_RULE[esubset]) THEN
      DISCH_THEN(MP_TAC o SPEC `m:A`) THEN ASM_REWRITE_TAC[] THEN
      MESON_TAC[];
      FIRST_ASSUM ACCEPT_TAC]]);;

(* ===================================================================== *)
(* F2.0 finale: EFIN_TO_NAT -- an internally finite (Kuratowski) set is   *)
(* in bijection with an internal natural.                                *)
(*                                                                        *)
(* Supporting results, in dependency order:                              *)
(*   EADJOIN_ABSORB : E u x ==> x adjoin u = x.                           *)
(*   EAPPLY_ADJOIN  : eapply of f adjoin <n,v> = eapply f, plus <n,v>.    *)
(*                    (FIXED version FN_APA3: DISJ2 then SUBST_ALL before  *)
(*                    EOPAIR_INJ; the k=n/\t=v branch double-SUBST then    *)
(*                    EXISTS pr.  The earlier draft mis-shaped EOPAIR_INJ  *)
(*                    ANTS and is NOT used.)                               *)
(*   EBIJ_ADJOIN    : extend a bijection f:n~w by one pair to f':n'~y      *)
(*                    where n'=esuc n, y=w adjoin v, given ~(E v w).       *)
(*                    (E_IRREFL used via MP_TAC(ISPECL[...]) -- NOT        *)
(*                    MATCH_MP_TAC, whose ~(E x x) conclusion omits D.)    *)
(*   bijfam_form + BIJFAM_HOLDS : object formula "?n. n in om /\ ?f.       *)
(*                    ebij f n x" for the EFIN_TO_NAT separation family.   *)
(*                                                                        *)
(* EFIN_TO_NAT proof = the K-family { x SUBSET p : ?n in om. ?f. ebij     *)
(* f n x } instantiated into efin's forall-families quantifier: empty is  *)
(* in it (EBIJ_EMPTY_ANY); adjoin-closed by extending the bijection with  *)
(* one pair = esuc (NO internal induction); so p itself is in it.         *)
(* ===================================================================== *)

let EADJOIN_ABSORB = prove
 (`!D (E:A->A->bool) x u y.
      model D E ZF_AX /\ x IN D /\ u IN D /\ E u x /\ eadjoin D E x u y
      ==> y = x`,
  REPEAT STRIP_TAC THEN
  FIRST_ASSUM(MATCH_MP_TAC o MATCH_MP ZF_EXTENSIONALITY) THEN
  SUBGOAL_THEN `(y:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[EADJOIN_IN]; ALL_TAC] THEN
  ASM_REWRITE_TAC[] THEN
  MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`x:A`;`u:A`;`y:A`]
    EADJOIN_MEM) THEN
  ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[]);;

let EAPPLY_ADJOIN = prove
 (`!D (E:A->A->bool) f n v pr f'.
      model D E ZF_AX /\ f IN D /\ n IN D /\ v IN D /\
      eopair D E n v pr /\ eadjoin D E f pr f'
      ==> !k t. k IN D /\ t IN D
                ==> (eapply D E f' k t <=>
                     eapply D E f k t \/ k = n /\ t = v)`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `(pr:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[EOPAIR_IN]; ALL_TAC] THEN
  SUBGOAL_THEN
   `!z:A. z IN D ==> ((E:A->A->bool) z f' <=> E z f \/ z = pr)`
   (LABEL_TAC "fm") THENL
   [MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`f:A`;`pr:A`;`f':A`]
      EADJOIN_MEM) THEN ASM_REWRITE_TAC[] THEN MESON_TAC[];
    ALL_TAC] THEN
  MAP_EVERY X_GEN_TAC [`k:A`;`t:A`] THEN STRIP_TAC THEN
  REWRITE_TAC[eapply] THEN EQ_TAC THENL
   [DISCH_THEN(X_CHOOSE_THEN `z:A` STRIP_ASSUME_TAC) THEN
    SUBGOAL_THEN `(z:A) IN D` ASSUME_TAC THENL
     [ASM_MESON_TAC[EOPAIR_IN]; ALL_TAC] THEN
    USE_THEN "fm" (MP_TAC o SPEC `z:A`) THEN ANTS_TAC THENL
     [FIRST_ASSUM ACCEPT_TAC;
      DISCH_THEN(fun th ->
        MP_TAC(EQ_MP th (ASSUME `(E:A->A->bool) z f'`)))] THEN
    STRIP_TAC THENL
     [DISJ1_TAC THEN EXISTS_TAC `z:A` THEN ASM_REWRITE_TAC[];
      DISJ2_TAC THEN FIRST_X_ASSUM SUBST_ALL_TAC THEN
      MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`k:A`;`t:A`;`n:A`;`v:A`;
        `pr:A`] EOPAIR_INJ) THEN
      ANTS_TAC THENL
       [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
        DISCH_THEN ACCEPT_TAC]];
    STRIP_TAC THENL
     [EXISTS_TAC `z:A` THEN CONJ_TAC THENL
       [FIRST_ASSUM ACCEPT_TAC;
        SUBGOAL_THEN `(z:A) IN D` ASSUME_TAC THENL
         [ASM_MESON_TAC[EOPAIR_IN]; ALL_TAC] THEN
        USE_THEN "fm" (MP_TAC o SPEC `z:A`) THEN ANTS_TAC THENL
         [FIRST_ASSUM ACCEPT_TAC;
          DISCH_THEN(fun th -> REWRITE_TAC[th])] THEN
        DISJ1_TAC THEN FIRST_ASSUM ACCEPT_TAC];
      FIRST_X_ASSUM SUBST_ALL_TAC THEN FIRST_X_ASSUM SUBST_ALL_TAC THEN
      EXISTS_TAC `pr:A` THEN CONJ_TAC THENL
       [FIRST_ASSUM ACCEPT_TAC;
        USE_THEN "fm" (MP_TAC o SPEC `pr:A`) THEN ANTS_TAC THENL
         [FIRST_ASSUM ACCEPT_TAC;
          DISCH_THEN(fun th -> REWRITE_TAC[th])] THEN
        DISJ2_TAC THEN REFL_TAC]]]);;

let EBIJ_ADJOIN = prove
 (`!D (E:A->A->bool) f n w v pr f' n' y.
      model D E ZF_AX /\ n IN D /\ w IN D /\ v IN D /\
      ebij D E f n w /\ ~(E v w) /\
      eopair D E n v pr /\ eadjoin D E f pr f' /\
      esuc D E n n' /\ eadjoin D E w v y
      ==> ebij D E f' n' y`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "zf nD wD vD + vnw oppr h h2 h3" THEN
  REWRITE_TAC[ebij] THEN
  INTRO_TAC "fD cl1 cl2 cl3 cl4 cl5" THEN
  SUBGOAL_THEN
   `!m:A. m IN D ==> ((E:A->A->bool) m n' <=> E m n \/ m = n)`
   (LABEL_TAC "n'm") THENL
   [MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`n:A`;`n':A`] ESUC_ALT) THEN
    ASM_REWRITE_TAC[] THEN MESON_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!m:A. m IN D ==> ((E:A->A->bool) m y <=> E m w \/ m = v)`
   (LABEL_TAC "ym") THENL
   [MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`w:A`;`v:A`;`y:A`]
      EADJOIN_MEM) THEN ASM_REWRITE_TAC[] THEN MESON_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!k t. k IN D /\ t IN D
          ==> (eapply D (E:A->A->bool) f' k t <=>
               eapply D E f k t \/ k = n /\ t = v)`
   (LABEL_TAC "ap") THENL
   [MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`f:A`;`n:A`;`v:A`;`pr:A`;
      `f':A`] EAPPLY_ADJOIN) THEN
    ANTS_TAC THENL
     [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
      DISCH_THEN ACCEPT_TAC];
    ALL_TAC] THEN
  SUBGOAL_THEN `~((E:A->A->bool) n n)` (LABEL_TAC "irr") THENL
   [MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`n:A`] E_IRREFL) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(f':A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[EADJOIN_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `(n':A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[ESUC_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `(y:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[EADJOIN_IN]; ALL_TAC] THEN
  REWRITE_TAC[ebij] THEN CONJ_TAC THENL
   [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  CONJ_TAC THENL [ASM_MESON_TAC[]; ALL_TAC] THEN
  CONJ_TAC THENL
   [X_GEN_TAC `k:A` THEN STRIP_TAC THEN
    USE_THEN "n'm" (MP_TAC o SPEC `k:A`) THEN ANTS_TAC THENL
     [FIRST_ASSUM ACCEPT_TAC;
      DISCH_THEN(fun th ->
        MP_TAC(EQ_MP th (ASSUME `(E:A->A->bool) k n'`)))] THEN
    STRIP_TAC THENL
     [USE_THEN "cl2" (MP_TAC o SPEC `k:A`) THEN ANTS_TAC THENL
       [CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
        DISCH_THEN(X_CHOOSE_THEN `t:A` STRIP_ASSUME_TAC)] THEN
      EXISTS_TAC `t:A` THEN REPEAT CONJ_TAC THENL
       [FIRST_ASSUM ACCEPT_TAC;
        USE_THEN "ym" (MP_TAC o SPEC `t:A`) THEN ANTS_TAC THENL
         [FIRST_ASSUM ACCEPT_TAC;
          DISCH_THEN(fun th -> REWRITE_TAC[th])] THEN
        DISJ1_TAC THEN FIRST_ASSUM ACCEPT_TAC;
        USE_THEN "ap" (MP_TAC o SPECL[`k:A`;`t:A`]) THEN ANTS_TAC THENL
         [CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
          DISCH_THEN(fun th -> REWRITE_TAC[th])] THEN
        DISJ1_TAC THEN FIRST_ASSUM ACCEPT_TAC];
      FIRST_X_ASSUM SUBST_ALL_TAC THEN
      EXISTS_TAC `v:A` THEN REPEAT CONJ_TAC THENL
       [FIRST_ASSUM ACCEPT_TAC;
        USE_THEN "ym" (MP_TAC o SPEC `v:A`) THEN ANTS_TAC THENL
         [FIRST_ASSUM ACCEPT_TAC;
          DISCH_THEN(fun th -> REWRITE_TAC[th])] THEN
        DISJ2_TAC THEN REFL_TAC;
        USE_THEN "ap" (MP_TAC o SPECL[`n:A`;`v:A`]) THEN ANTS_TAC THENL
         [CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
          DISCH_THEN(fun th -> REWRITE_TAC[th])] THEN
        DISJ2_TAC THEN CONJ_TAC THEN REFL_TAC]];
    ALL_TAC] THEN
  CONJ_TAC THENL
   [MAP_EVERY X_GEN_TAC [`k:A`;`t:A`;`t':A`] THEN STRIP_TAC THEN
    SUBGOAL_THEN `eapply D (E:A->A->bool) f k t \/ k = n /\ t = v`
     MP_TAC THENL
     [USE_THEN "ap" (MP_TAC o SPECL[`k:A`;`t:A`]) THEN ANTS_TAC THENL
       [CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
        DISCH_THEN(fun th -> REWRITE_TAC[GSYM th]) THEN
        FIRST_ASSUM ACCEPT_TAC];
      ALL_TAC] THEN
    SUBGOAL_THEN `eapply D (E:A->A->bool) f k t' \/ k = n /\ t' = v`
     MP_TAC THENL
     [USE_THEN "ap" (MP_TAC o SPECL[`k:A`;`t':A`]) THEN ANTS_TAC THENL
       [CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
        DISCH_THEN(fun th -> REWRITE_TAC[GSYM th]) THEN
        FIRST_ASSUM ACCEPT_TAC];
      ALL_TAC] THEN
    DISCH_THEN(DISJ_CASES_THEN2 (LABEL_TAC "ea2")
      (CONJUNCTS_THEN2 (LABEL_TAC "kn2") (LABEL_TAC "tv2"))) THENL
     [DISCH_THEN(DISJ_CASES_THEN2 (LABEL_TAC "ea1")
        (CONJUNCTS_THEN2 (LABEL_TAC "kn1") (LABEL_TAC "tv1"))) THENL
       [USE_THEN "cl3" (MP_TAC o SPECL[`k:A`;`t:A`;`t':A`]) THEN
        ANTS_TAC THENL
         [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
          DISCH_THEN ACCEPT_TAC];
        REMOVE_THEN "kn1" SUBST_ALL_TAC THEN
        USE_THEN "cl1" (MP_TAC o SPECL[`n:A`;`t':A`]) THEN ANTS_TAC THENL
         [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
          DISCH_THEN(MP_TAC o CONJUNCT1) THEN
          USE_THEN "irr" MP_TAC THEN MESON_TAC[]]];
      DISCH_THEN(DISJ_CASES_THEN2 (LABEL_TAC "ea1")
        (CONJUNCTS_THEN2 (LABEL_TAC "kn1") (LABEL_TAC "tv1"))) THENL
       [REMOVE_THEN "kn2" SUBST_ALL_TAC THEN
        USE_THEN "cl1" (MP_TAC o SPECL[`n:A`;`t:A`]) THEN ANTS_TAC THENL
         [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
          DISCH_THEN(MP_TAC o CONJUNCT1) THEN
          USE_THEN "irr" MP_TAC THEN MESON_TAC[]];
        REMOVE_THEN "tv1" SUBST_ALL_TAC THEN
        REMOVE_THEN "tv2" SUBST_ALL_TAC THEN REFL_TAC]];
    ALL_TAC] THEN
  CONJ_TAC THENL
   [MAP_EVERY X_GEN_TAC [`k:A`;`k':A`;`t:A`] THEN STRIP_TAC THEN
    SUBGOAL_THEN `eapply D (E:A->A->bool) f k t \/ k = n /\ t = v`
     MP_TAC THENL
     [USE_THEN "ap" (MP_TAC o SPECL[`k:A`;`t:A`]) THEN ANTS_TAC THENL
       [CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
        DISCH_THEN(fun th -> REWRITE_TAC[GSYM th]) THEN
        FIRST_ASSUM ACCEPT_TAC];
      ALL_TAC] THEN
    SUBGOAL_THEN `eapply D (E:A->A->bool) f k' t \/ k' = n /\ t = v`
     MP_TAC THENL
     [USE_THEN "ap" (MP_TAC o SPECL[`k':A`;`t:A`]) THEN ANTS_TAC THENL
       [CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
        DISCH_THEN(fun th -> REWRITE_TAC[GSYM th]) THEN
        FIRST_ASSUM ACCEPT_TAC];
      ALL_TAC] THEN
    DISCH_THEN(DISJ_CASES_THEN2 (LABEL_TAC "ea2")
      (CONJUNCTS_THEN2 (LABEL_TAC "kn2") (LABEL_TAC "tv2"))) THENL
     [DISCH_THEN(DISJ_CASES_THEN2 (LABEL_TAC "ea1")
        (CONJUNCTS_THEN2 (LABEL_TAC "kn1") (LABEL_TAC "tv1"))) THENL
       [USE_THEN "cl4" (MP_TAC o SPECL[`k:A`;`k':A`;`t:A`]) THEN
        ANTS_TAC THENL
         [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
          DISCH_THEN ACCEPT_TAC];
        REMOVE_THEN "tv1" SUBST_ALL_TAC THEN
        USE_THEN "cl1" (MP_TAC o SPECL[`k':A`;`v:A`]) THEN ANTS_TAC THENL
         [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
          DISCH_THEN(MP_TAC o CONJUNCT2) THEN
          USE_THEN "vnw" MP_TAC THEN MESON_TAC[]]];
      DISCH_THEN(DISJ_CASES_THEN2 (LABEL_TAC "ea1")
        (CONJUNCTS_THEN2 (LABEL_TAC "kn1") (LABEL_TAC "tv1"))) THENL
       [REMOVE_THEN "tv2" SUBST_ALL_TAC THEN
        USE_THEN "cl1" (MP_TAC o SPECL[`k:A`;`v:A`]) THEN ANTS_TAC THENL
         [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
          DISCH_THEN(MP_TAC o CONJUNCT2) THEN
          USE_THEN "vnw" MP_TAC THEN MESON_TAC[]];
        REMOVE_THEN "kn1" SUBST_ALL_TAC THEN
        REMOVE_THEN "kn2" SUBST_ALL_TAC THEN REFL_TAC]];
    ALL_TAC] THEN
  X_GEN_TAC `t:A` THEN STRIP_TAC THEN
  USE_THEN "ym" (MP_TAC o SPEC `t:A`) THEN ANTS_TAC THENL
   [FIRST_ASSUM ACCEPT_TAC;
    DISCH_THEN(fun th ->
      MP_TAC(EQ_MP th (ASSUME `(E:A->A->bool) t y`)))] THEN
  STRIP_TAC THENL
   [USE_THEN "cl5" (MP_TAC o SPEC `t:A`) THEN ANTS_TAC THENL
     [CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
      DISCH_THEN(X_CHOOSE_THEN `k:A` STRIP_ASSUME_TAC)] THEN
    EXISTS_TAC `k:A` THEN REPEAT CONJ_TAC THENL
     [FIRST_ASSUM ACCEPT_TAC;
      USE_THEN "n'm" (MP_TAC o SPEC `k:A`) THEN ANTS_TAC THENL
       [FIRST_ASSUM ACCEPT_TAC;
        DISCH_THEN(fun th -> REWRITE_TAC[th])] THEN
      DISJ1_TAC THEN FIRST_ASSUM ACCEPT_TAC;
      USE_THEN "ap" (MP_TAC o SPECL[`k:A`;`t:A`]) THEN ANTS_TAC THENL
       [CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
        DISCH_THEN(fun th -> REWRITE_TAC[th])] THEN
      DISJ1_TAC THEN FIRST_ASSUM ACCEPT_TAC];
    FIRST_X_ASSUM SUBST_ALL_TAC THEN
    EXISTS_TAC `n:A` THEN REPEAT CONJ_TAC THENL
     [FIRST_ASSUM ACCEPT_TAC;
      USE_THEN "n'm" (MP_TAC o SPEC `n:A`) THEN ANTS_TAC THENL
       [FIRST_ASSUM ACCEPT_TAC;
        DISCH_THEN(fun th -> REWRITE_TAC[th])] THEN
      DISJ2_TAC THEN REFL_TAC;
      USE_THEN "ap" (MP_TAC o SPECL[`n:A`;`v:A`]) THEN ANTS_TAC THENL
       [CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
        DISCH_THEN(fun th -> REWRITE_TAC[th])] THEN
      DISJ2_TAC THEN CONJ_TAC THEN REFL_TAC]]);;

(* Separation formula for EFIN_TO_NAT: slot 20 = separation variable x,   *)
(* parameter 18 = om; says ?n. n IN om /\ ?f. ebij f n x  (n a natural,   *)
(* x equinumerous with n).  bijform 21 20 has f existentially bound       *)
(* inside (uses slots MAX 21 20 + 1..5 = 22..26; no clash with 18,20,21). *)
let bijfam_form = new_definition
  `bijfam_form = ?? 21 ((21 %% 18) && bijform 21 20)`;;

let BIJFAM_HOLDS = prove
 (`!D (E:A->A->bool) v w.
      model D E ZF_AX /\ valuation D v /\ w IN D
      ==> (holds D E ((20 |-> w) v) bijfam_form <=>
           ?n. n IN D /\ E n (v 18) /\ ?f. ebij D E f n w)`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[bijfam_form] THEN
  SUBGOAL_THEN `valuation D ((20 |-> (w:A)) v)` ASSUME_TAC THENL
   [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
  REWRITE_TAC[HOLDS_EX] THEN
  SUBGOAL_THEN
   `!n:A. n IN D
      ==> (holds D E ((21 |-> n) ((20 |-> (w:A)) v))
             ((21 %% 18) && bijform 21 20) <=>
           E n (v 18) /\ ?f. ebij D E f n w)`
   (LABEL_TAC "body") THENL
   [X_GEN_TAC `n:A` THEN DISCH_TAC THEN
    SUBGOAL_THEN `valuation D ((21 |-> (n:A)) ((20 |-> (w:A)) v))`
     ASSUME_TAC THENL [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
    ASM_SIMP_TAC[HOLDS_AND] THEN
    SUBGOAL_THEN
     `holds D E ((21 |-> (n:A)) ((20 |-> (w:A)) v)) (21 %% 18) <=>
      E n (v 18)` SUBST1_TAC THENL
     [REWRITE_TAC[HOLDS_MEM] THEN REWRITE_TAC[VALMOD; ARITH_EQ];
      ALL_TAC] THEN
    MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;
      `(21 |-> (n:A)) ((20 |-> (w:A)) v)`;`21`;`20`] HOLDS_BIJFORM_EBIJ) THEN
    ANTS_TAC THENL
     [CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
      DISCH_THEN(fun th -> REWRITE_TAC[th])] THEN
    REWRITE_TAC[VALMOD; ARITH_EQ];
    ALL_TAC] THEN
  EQ_TAC THENL
   [DISCH_THEN(X_CHOOSE_THEN `n:A` STRIP_ASSUME_TAC) THEN
    EXISTS_TAC `n:A` THEN ASM_REWRITE_TAC[] THEN
    USE_THEN "body" (MP_TAC o SPEC `n:A`) THEN ANTS_TAC THENL
     [FIRST_ASSUM ACCEPT_TAC; DISCH_THEN(fun th -> ASM_MESON_TAC[th])];
    DISCH_THEN(X_CHOOSE_THEN `n:A` STRIP_ASSUME_TAC) THEN
    EXISTS_TAC `n:A` THEN ASM_REWRITE_TAC[] THEN
    USE_THEN "body" (MP_TAC o SPEC `n:A`) THEN ANTS_TAC THENL
     [FIRST_ASSUM ACCEPT_TAC; DISCH_THEN(fun th -> ASM_MESON_TAC[th])]]);;

(* EFIN_TO_NAT.  Assembled from interactive chunks TN_1..TN_6B, joined by  *)
(* THEN (at each chunk boundary exactly one goal remained, so e(t1);e(t2)  *)
(* = e(t1 THEN t2)).  TN_1 setup/omega; TN_2 pow+separation family fam;    *)
(* TN_3 "fc" membership char of fam; TN_4 K-property @ fam (ANTS leaves    *)
(* the 4-conjunct family antecedent, conclusion branch reads p off fc);    *)
(* TN_5 fam IN D + subset-closure + empty-member; TN_6 adjoin-closure      *)
(* (destructure fc@x; ASM_CASES E u x: absorb=EADJOIN_ABSORB gives y=x;    *)
(* else ym + esubset y p); TN_6B extend: n'=esuc n, pr=<n,u>, f'=f adj pr, *)
(* EBIJ_ADJOIN gives ebij f' n' y, conclude E y fam via fc.                *)
let EFIN_TO_NAT = prove
 (`!D (E:A->A->bool) om p.
      model D E ZF_AX /\ eomega D E om /\ efin D E p
      ==> ?n f. n IN D /\ f IN D /\ E n om /\ ebij D E f n p`,
  REPEAT GEN_TAC THEN
  DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC
   (CONJUNCTS_THEN2 ASSUME_TAC
    ((CONJUNCTS_THEN2 ASSUME_TAC (LABEL_TAC "kp")) o REWRITE_RULE[efin]))) THEN
  SUBGOAL_THEN `(om:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[eomega; einductive]; ALL_TAC] THEN
  SUBGOAL_THEN `einductive D (E:A->A->bool) om` ASSUME_TAC THENL
   [ASM_MESON_TAC[eomega]; ALL_TAC] THEN
  SUBGOAL_THEN
   `!u:A. u IN D /\ E u om ==> ?s. esuc D (E:A->A->bool) u s /\ E s om`
   (LABEL_TAC "omsuc") THENL
   [ASM_MESON_TAC[einductive]; ALL_TAC] THEN
  SUBGOAL_THEN `?e0:A. eempty D (E:A->A->bool) e0 /\ E e0 om`
   (X_CHOOSE_THEN `e0:A` STRIP_ASSUME_TAC) THENL
   [ASM_MESON_TAC[einductive]; ALL_TAC] THEN
  SUBGOAL_THEN `(e0:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[eempty]; ALL_TAC] THEN
  SUBGOAL_THEN `?pp. epow D (E:A->A->bool) p pp`
   (X_CHOOSE_THEN `pp:A` (LABEL_TAC "pw")) THENL
   [ASM_MESON_TAC[EPOW_EXISTS]; ALL_TAC] THEN
  SUBGOAL_THEN `(pp:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[EPOW_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `valuation D ((18 |-> (om:A)) (\n:num. om:A))`
   ASSUME_TAC THENL
   [MATCH_MP_TAC VALUATION_VALMOD THEN CONJ_TAC THENL
     [REWRITE_TAC[valuation] THEN FIRST_ASSUM ACCEPT_TAC;
      FIRST_ASSUM ACCEPT_TAC];
    ALL_TAC] THEN
  MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`] ZF_SEPARATION) THEN
  ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  DISCH_THEN(MP_TAC o ISPECL
    [`bijfam_form`; `20`; `(18 |-> (om:A)) (\n:num. om:A)`; `pp:A`]) THEN
  ANTS_TAC THENL
   [CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
    DISCH_THEN(X_CHOOSE_THEN `fam:A`
      (CONJUNCTS_THEN2 ASSUME_TAC (LABEL_TAC "sep")))] THEN
  SUBGOAL_THEN
   `!z:A. z IN D
      ==> (E z fam <=>
           esubset D (E:A->A->bool) z p /\
           ?n. n IN D /\ E n om /\ ?f. ebij D E f n z)`
   (LABEL_TAC "fc") THENL
   [X_GEN_TAC `z:A` THEN DISCH_TAC THEN
    USE_THEN "sep" (MP_TAC o SPEC `z:A`) THEN ANTS_TAC THENL
     [FIRST_ASSUM ACCEPT_TAC; DISCH_THEN(fun th -> REWRITE_TAC[th])] THEN
    MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;
      `(18 |-> (om:A)) (\n:num. om:A)`;`z:A`] BIJFAM_HOLDS) THEN
    ANTS_TAC THENL
     [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
      DISCH_THEN(fun th -> REWRITE_TAC[th])] THEN
    REWRITE_TAC[VALMOD; ARITH_EQ] THEN
    USE_THEN "pw" (MP_TAC o REWRITE_RULE[epow]) THEN
    DISCH_THEN(MP_TAC o SPEC `z:A` o CONJUNCT2) THEN ANTS_TAC THENL
     [FIRST_ASSUM ACCEPT_TAC; DISCH_THEN(fun th -> REWRITE_TAC[th])];
    ALL_TAC] THEN
  USE_THEN "kp" (MP_TAC o SPEC `fam:A`) THEN ANTS_TAC THENL
   [ALL_TAC;
    DISCH_TAC THEN
    USE_THEN "fc" (MP_TAC o SPEC `p:A`) THEN ANTS_TAC THENL
     [FIRST_ASSUM ACCEPT_TAC;
      DISCH_THEN(fun th ->
        MP_TAC(EQ_MP th (ASSUME `(E:A->A->bool) p fam`)))] THEN
    DISCH_THEN(CONJUNCTS_THEN2 (K ALL_TAC)
      (X_CHOOSE_THEN `n:A` (CONJUNCTS_THEN2 ASSUME_TAC
        (CONJUNCTS_THEN2 ASSUME_TAC (X_CHOOSE_THEN `f:A` ASSUME_TAC))))) THEN
    MAP_EVERY EXISTS_TAC [`n:A`;`f:A`] THEN
    SUBGOAL_THEN `(f:A) IN D` ASSUME_TAC THENL
     [ASM_MESON_TAC[ebij]; ALL_TAC] THEN
    ASM_REWRITE_TAC[]] THEN
  CONJ_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  CONJ_TAC THENL
   [X_GEN_TAC `x:A` THEN STRIP_TAC THEN
    USE_THEN "fc" (MP_TAC o SPEC `x:A`) THEN ANTS_TAC THENL
     [FIRST_ASSUM ACCEPT_TAC;
      DISCH_THEN(fun th ->
        MP_TAC(EQ_MP th (ASSUME `(E:A->A->bool) x fam`)))] THEN
    DISCH_THEN(ACCEPT_TAC o CONJUNCT1);
    ALL_TAC] THEN
  CONJ_TAC THENL
   [EXISTS_TAC `e0:A` THEN REPEAT CONJ_TAC THENL
     [FIRST_ASSUM ACCEPT_TAC;
      FIRST_ASSUM ACCEPT_TAC;
      USE_THEN "fc" (MP_TAC o SPEC `e0:A`) THEN ANTS_TAC THENL
       [FIRST_ASSUM ACCEPT_TAC;
        DISCH_THEN(fun th -> REWRITE_TAC[th])] THEN
      CONJ_TAC THENL
       [MATCH_MP_TAC EEMPTY_SUBSET THEN FIRST_ASSUM ACCEPT_TAC;
        EXISTS_TAC `e0:A` THEN REPEAT CONJ_TAC THENL
         [FIRST_ASSUM ACCEPT_TAC;
          FIRST_ASSUM ACCEPT_TAC;
          EXISTS_TAC `e0:A` THEN
          MATCH_MP_TAC EBIJ_EMPTY_ANY THEN
          REPEAT CONJ_TAC THEN TRY(FIRST_ASSUM ACCEPT_TAC) THEN
          ASM_MESON_TAC[eempty]]]];
    ALL_TAC] THEN
  MAP_EVERY X_GEN_TAC [`x:A`;`u:A`;`y:A`] THEN STRIP_TAC THEN
  USE_THEN "fc" (MP_TAC o SPEC `x:A`) THEN ANTS_TAC THENL
   [FIRST_ASSUM ACCEPT_TAC;
    DISCH_THEN(fun th ->
      MP_TAC(EQ_MP th (ASSUME `(E:A->A->bool) x fam`)))] THEN
  INTRO_TAC "xsub @n. nD nom @f. bijx" THEN
  ASM_CASES_TAC `(E:A->A->bool) u x` THENL
   [SUBGOAL_THEN `y:A = x` SUBST1_TAC THENL
     [MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`x:A`;`u:A`;`y:A`]
        EADJOIN_ABSORB) THEN
      ANTS_TAC THENL
       [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
        DISCH_THEN ACCEPT_TAC];
      FIRST_ASSUM ACCEPT_TAC];
    SUBGOAL_THEN `!m:A. m IN D ==> ((E:A->A->bool) m y <=> E m x \/ m = u)`
     (LABEL_TAC "ym") THENL
     [MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`x:A`;`u:A`;`y:A`]
        EADJOIN_MEM) THEN ASM_REWRITE_TAC[] THEN MESON_TAC[];
      ALL_TAC] THEN
    SUBGOAL_THEN `esubset D (E:A->A->bool) y p` (LABEL_TAC "ysub") THENL
     [REWRITE_TAC[esubset] THEN X_GEN_TAC `m:A` THEN STRIP_TAC THEN
      USE_THEN "ym" (MP_TAC o SPEC `m:A`) THEN ANTS_TAC THENL
       [FIRST_ASSUM ACCEPT_TAC;
        DISCH_THEN(fun th ->
          MP_TAC(EQ_MP th (ASSUME `(E:A->A->bool) m y`)))] THEN
      STRIP_TAC THENL
       [USE_THEN "xsub" (MP_TAC o REWRITE_RULE[esubset]) THEN
        DISCH_THEN(MP_TAC o SPEC `m:A`) THEN ASM_REWRITE_TAC[];
        ASM_REWRITE_TAC[]];
      ALL_TAC] THEN
    SUBGOAL_THEN `?s. esuc D (E:A->A->bool) n s /\ E s om`
     (X_CHOOSE_THEN `n':A` STRIP_ASSUME_TAC) THENL
     [USE_THEN "omsuc" (MP_TAC o SPEC `n:A`) THEN ANTS_TAC THENL
       [CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; DISCH_THEN ACCEPT_TAC];
      ALL_TAC] THEN
    SUBGOAL_THEN `(n':A) IN D` ASSUME_TAC THENL
     [ASM_MESON_TAC[ESUC_IN]; ALL_TAC] THEN
    SUBGOAL_THEN `?pr. eopair D (E:A->A->bool) n u pr`
     (X_CHOOSE_THEN `pr:A` ASSUME_TAC) THENL
     [ASM_MESON_TAC[EOPAIR_EXISTS]; ALL_TAC] THEN
    SUBGOAL_THEN `(pr:A) IN D` ASSUME_TAC THENL
     [ASM_MESON_TAC[EOPAIR_IN]; ALL_TAC] THEN
    SUBGOAL_THEN `(f:A) IN D` ASSUME_TAC THENL
     [ASM_MESON_TAC[ebij]; ALL_TAC] THEN
    SUBGOAL_THEN `?f'. eadjoin D (E:A->A->bool) f pr f'`
     (X_CHOOSE_THEN `f':A` ASSUME_TAC) THENL
     [ASM_MESON_TAC[EADJOIN_EXISTS]; ALL_TAC] THEN
    SUBGOAL_THEN `(f':A) IN D` ASSUME_TAC THENL
     [ASM_MESON_TAC[EADJOIN_IN]; ALL_TAC] THEN
    SUBGOAL_THEN `ebij D (E:A->A->bool) f' n' y` ASSUME_TAC THENL
     [MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`f:A`;`n:A`;`x:A`;`u:A`;
        `pr:A`;`f':A`;`n':A`;`y:A`] EBIJ_ADJOIN) THEN
      ANTS_TAC THENL
       [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
        DISCH_THEN ACCEPT_TAC];
      ALL_TAC] THEN
    USE_THEN "fc" (MP_TAC o SPEC `y:A`) THEN ANTS_TAC THENL
     [FIRST_ASSUM ACCEPT_TAC; DISCH_THEN(fun th -> REWRITE_TAC[th])] THEN
    CONJ_TAC THENL
     [FIRST_ASSUM ACCEPT_TAC;
      EXISTS_TAC `n':A` THEN REPEAT CONJ_TAC THENL
       [FIRST_ASSUM ACCEPT_TAC;
        FIRST_ASSUM ACCEPT_TAC;
        EXISTS_TAC `f':A` THEN FIRST_ASSUM ACCEPT_TAC]]]);;

(* ==================================================================== *)
(* F2.2  Cohen poset carrier.  ecohenp D E ci om P : P is the set of     *)
(* finite partial functions p SUBSET ci = I x two (om,kappa params live  *)
(* in ci and om). cohen_form REUSES bijfam_form so BIJFAM_HOLDS applies   *)
(* verbatim for the finiteness conjunct.  ECOHENP_EXISTS builds ci (via   *)
(* ECROSS_EXISTS) and P (via ZF_SEPARATION over pow ci).                  *)
(* ==================================================================== *)

let ecohenp = new_definition
  `ecohenp D (E:A->A->bool) ci om P <=>
     P IN D /\
     !p. p IN D
         ==> (E p P <=>
              esubset D E p ci /\
              efunctional D E p /\
              (?n. n IN D /\ E n om /\ ?f. ebij D E f n p))`;;

let cohen_form = new_definition
  `cohen_form = subset_form 20 19 && functional_form 20 && bijfam_form`;;

let ECOHENP_EXISTS = prove
 (`!D (E:A->A->bool) ii tw om.
      model D E ZF_AX /\ ii IN D /\ tw IN D /\ om IN D
      ==> ?ci P. ecross D E ii tw ci /\ ecohenp D E ci om P`,
  REPEAT STRIP_TAC THEN
  MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`ii:A`;`tw:A`] ECROSS_EXISTS) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `ci:A` (LABEL_TAC "cr")) THEN
  SUBGOAL_THEN `(ci:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[ecross]; ALL_TAC] THEN
  MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`ci:A`] EPOW_EXISTS) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `pw:A` (LABEL_TAC "pw")) THEN
  SUBGOAL_THEN `(pw:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[EPOW_IN]; ALL_TAC] THEN
  SUBGOAL_THEN
   `valuation D ((19 |-> (ci:A)) ((18 |-> (om:A)) (\n:num. ci:A)))`
   (LABEL_TAC "val") THENL
   [MATCH_MP_TAC VALUATION_VALMOD THEN CONJ_TAC THENL
     [MATCH_MP_TAC VALUATION_VALMOD THEN CONJ_TAC THENL
       [REWRITE_TAC[valuation] THEN FIRST_ASSUM ACCEPT_TAC;
        FIRST_ASSUM ACCEPT_TAC];
      FIRST_ASSUM ACCEPT_TAC];
    ALL_TAC] THEN
  MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`] ZF_SEPARATION) THEN
  ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  DISCH_THEN(MP_TAC o ISPECL
    [`cohen_form`; `20`;
     `(19 |-> (ci:A)) ((18 |-> (om:A)) (\n:num. ci:A))`; `pw:A`]) THEN
  ANTS_TAC THENL
   [CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
    DISCH_THEN(X_CHOOSE_THEN `P:A`
      (CONJUNCTS_THEN2 ASSUME_TAC (LABEL_TAC "sep")))] THEN
  EXISTS_TAC `ci:A` THEN EXISTS_TAC `P:A` THEN CONJ_TAC THENL
   [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  REWRITE_TAC[ecohenp] THEN CONJ_TAC THENL
   [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  X_GEN_TAC `p:A` THEN DISCH_TAC THEN
  SUBGOAL_THEN
   `valuation D
    ((20 |-> (p:A)) ((19 |-> (ci:A)) ((18 |-> (om:A)) (\n:num. ci:A))))`
   (LABEL_TAC "valV") THENL
   [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `E (p:A) pw <=> esubset D E p ci` (LABEL_TAC "pwm") THENL
   [ASM_MESON_TAC[epow]; ALL_TAC] THEN
  SUBGOAL_THEN
   `holds D E
    ((20 |-> (p:A)) ((19 |-> (ci:A)) ((18 |-> (om:A)) (\n:num. ci:A))))
      cohen_form <=>
    esubset D E p ci /\ efunctional D E p /\
    (?n. n IN D /\ E n om /\ ?f. ebij D E f n p)`
   (LABEL_TAC "hc") THENL
   [REWRITE_TAC[cohen_form; HOLDS_AND] THEN
    REWRITE_TAC[HOLDS_SUBSET_FORM] THEN
    ASM_SIMP_TAC[HOLDS_FUNCTIONAL_FORM] THEN
    MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;
      `(19 |-> (ci:A)) ((18 |-> (om:A)) (\n:num. ci:A))`;`p:A`]
        BIJFAM_HOLDS) THEN
    ANTS_TAC THENL
    [ASM_REWRITE_TAC[]; DISCH_THEN(fun th -> REWRITE_TAC[th])] THEN
    REWRITE_TAC[VALMOD; ARITH_EQ];
    ALL_TAC] THEN
  USE_THEN "sep" (MP_TAC o SPEC `p:A`) THEN
  ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  USE_THEN "pwm" (fun t1 -> USE_THEN "hc" (fun t2 -> REWRITE_TAC[t1;t2])) THEN
  CONV_TAC TAUT);;

(* Non-emptiness: the empty set is a Cohen condition (esubset ci vacuously, *)
(* efunctional vacuously, finite via n=f=empty: 0 IN om by EOMEGA_EMPTY and *)
(* ebij empty empty empty by EBIJ_EMPTY_ANY).  Needed at F2.5 for ~(bot=top).*)
let ECOHENP_HAS_EMPTY = prove
 (`!D (E:A->A->bool) ci om P z.
      model D E ZF_AX /\ eomega D E om /\ ecohenp D E ci om P /\
      eempty D E z /\ z IN D
      ==> E z P`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  FIRST_ASSUM(MP_TAC o SPEC `z:A` o CONJUNCT2 o REWRITE_RULE[ecohenp]) THEN
  ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  REPEAT CONJ_TAC THENL
   [MATCH_MP_TAC EEMPTY_SUBSET THEN FIRST_ASSUM ACCEPT_TAC;
    ASM_MESON_TAC[efunctional; eempty];
    EXISTS_TAC `z:A` THEN REPEAT CONJ_TAC THENL
     [FIRST_ASSUM ACCEPT_TAC;
      MATCH_MP_TAC EOMEGA_EMPTY THEN ASM_MESON_TAC[];
      EXISTS_TAC `z:A` THEN MATCH_MP_TAC EBIJ_EMPTY_ANY THEN
      ASM_MESON_TAC[eempty]]]);;

(* ==================================================================== *)
(* F2.3  Cohen order.  q leq p <=> p SUBSET q (reverse inclusion:        *)
(* stronger condition = bigger partial function).  The order SET is      *)
(* leqp = { <q,p> IN P x P : esubset p q } by separation (leqp_form over *)
(* ecross P P).  eleqp characterizes it; ELEQP_EXISTS builds it.         *)
(* ==================================================================== *)

let eleqp = new_definition
  `eleqp D (E:A->A->bool) P leqp <=>
     leqp IN D /\
     !pr. pr IN D
          ==> (E pr leqp <=>
               ?q p. q IN D /\ p IN D /\ E q P /\ E p P /\
                     eopair D E q p pr /\ esubset D E p q)`;;

let leqp_form = new_definition
  `leqp_form = ?? 3 (?? 4 (opair_form 3 4 0 && subset_form 4 3))`;;

let LEQP_FORM_HOLDS = prove
 (`!D (E:A->A->bool) v.
      valuation D v
      ==> (holds D E v leqp_form <=>
           ?q p. q IN D /\ p IN D /\ eopair D E q p (v 0) /\ esubset D E p q)`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[leqp_form] THEN
  REWRITE_TAC[HOLDS_EX] THEN
  SUBGOAL_THEN
   `!a b:A. a IN D /\ b IN D
      ==> (holds D E ((4 |-> b) ((3 |-> a) v))
             (opair_form 3 4 0 && subset_form 4 3) <=>
           eopair D E a b (v 0) /\ esubset D E b a)`
   (LABEL_TAC "body") THENL
   [REPEAT STRIP_TAC THEN
    SUBGOAL_THEN `valuation D ((4 |-> (b:A)) ((3 |-> (a:A)) v))`
      ASSUME_TAC THENL
      [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
    ASM_SIMP_TAC[HOLDS_AND; HOLDS_OPAIR_FORM] THEN
    REWRITE_TAC[HOLDS_SUBSET_FORM; VALMOD; ARITH_EQ];
    ALL_TAC] THEN
  EQ_TAC THENL
   [DISCH_THEN(X_CHOOSE_THEN `a:A` (CONJUNCTS_THEN2 ASSUME_TAC
      (X_CHOOSE_THEN `b:A` (CONJUNCTS_THEN2 ASSUME_TAC MP_TAC)))) THEN
    USE_THEN "body" (MP_TAC o SPECL [`a:A`;`b:A`]) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN STRIP_TAC THEN
    MAP_EVERY EXISTS_TAC [`a:A`;`b:A`] THEN ASM_REWRITE_TAC[];
    DISCH_THEN(X_CHOOSE_THEN `q:A` (X_CHOOSE_THEN `p:A` STRIP_ASSUME_TAC)) THEN
    EXISTS_TAC `q:A` THEN CONJ_TAC THENL
     [FIRST_ASSUM ACCEPT_TAC;
      EXISTS_TAC `p:A` THEN CONJ_TAC THENL
       [FIRST_ASSUM ACCEPT_TAC;
        USE_THEN "body" (MP_TAC o SPECL [`q:A`;`p:A`]) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
        DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN ASM_REWRITE_TAC[]]]]);;

let ELEQP_EXISTS = prove
 (`!D (E:A->A->bool) ci om P.
      model D E ZF_AX /\ ecohenp D E ci om P ==> ?leqp. eleqp D E P leqp`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `(P:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[ecohenp]; ALL_TAC] THEN
  MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`P:A`;`P:A`] ECROSS_EXISTS) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `PP:A` (LABEL_TAC "cr")) THEN
  SUBGOAL_THEN `(PP:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[ecross]; ALL_TAC] THEN
  SUBGOAL_THEN `?v:num->A. valuation D v` (X_CHOOSE_TAC `v0:num->A`) THENL
   [MATCH_MP_TAC VALUATION_EXISTS THEN ASM_MESON_TAC[MODEL_NONEMPTY];
    ALL_TAC] THEN
  MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`] ZF_SEPARATION) THEN
  ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  DISCH_THEN(MP_TAC o ISPECL [`leqp_form`; `0`; `v0:num->A`; `PP:A`]) THEN
  ANTS_TAC THENL
   [CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
    DISCH_THEN(X_CHOOSE_THEN `leqp:A`
      (CONJUNCTS_THEN2 ASSUME_TAC (LABEL_TAC "sep")))] THEN
  EXISTS_TAC `leqp:A` THEN REWRITE_TAC[eleqp] THEN
  CONJ_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  X_GEN_TAC `pr:A` THEN DISCH_TAC THEN
  MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`P:A`;`P:A`;`PP:A`;`pr:A`]
    ECROSS_MEMBER) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN DISCH_TAC THEN
  SUBGOAL_THEN `valuation D ((0 |-> (pr:A)) v0)` ASSUME_TAC THENL
   [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`(0 |-> (pr:A)) v0`]
         LEQP_FORM_HOLDS) THEN
  ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  REWRITE_TAC[VALMOD; ARITH_EQ] THEN DISCH_TAC THEN
  USE_THEN "sep" (MP_TAC o SPEC `pr:A`) THEN
  ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  DISCH_THEN SUBST1_TAC THEN
  ASM_MESON_TAC[EOPAIR_INJ]);;

(* -- erel destructor/constructor for eleqp.  The destructor needs u,v   *)
(* IN D so that EOPAIR_INJ can pin the pair components.                  *)

let ELEQP_EREL = prove
 (`!D (E:A->A->bool) P leqp u v.
      model D E ZF_AX /\ eleqp D E P leqp /\ u IN D /\ v IN D /\
      erel D E leqp u v
      ==> E u P /\ E v P /\ esubset D E v u`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  UNDISCH_TAC `erel D (E:A->A->bool) leqp u v` THEN REWRITE_TAC[erel] THEN
  DISCH_THEN(X_CHOOSE_THEN `pr:A` STRIP_ASSUME_TAC o CONJUNCT2 o
             CONJUNCT2) THEN
  FIRST_ASSUM(MP_TAC o SPEC `pr:A` o CONJUNCT2 o REWRITE_RULE[eleqp]) THEN
  ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  DISCH_THEN(fun th -> MP_TAC(EQ_MP th (ASSUME `(E:A->A->bool) pr leqp`))) THEN
  DISCH_THEN(X_CHOOSE_THEN `q:A` (X_CHOOSE_THEN `p:A` STRIP_ASSUME_TAC)) THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`u:A`;`v:A`;`q:A`;`p:A`;`pr:A`]
    EOPAIR_INJ) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[];
    DISCH_THEN(CONJUNCTS_THEN SUBST1_TAC) THEN ASM_REWRITE_TAC[]]);;

let ELEQP_EREL_INTRO = prove
 (`!D (E:A->A->bool) P leqp u v.
      model D E ZF_AX /\ eleqp D E P leqp /\
      u IN D /\ v IN D /\ E u P /\ E v P /\ esubset D E v u
      ==> erel D E leqp u v`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`u:A`;`v:A`] EOPAIR_EXISTS) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_TAC `pr:A`) THEN
  SUBGOAL_THEN `(pr:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[EOPAIR_IN]; ALL_TAC] THEN
  REWRITE_TAC[erel] THEN ASM_REWRITE_TAC[] THEN EXISTS_TAC `pr:A` THEN
  ASM_REWRITE_TAC[] THEN
  FIRST_ASSUM(MP_TAC o SPEC `pr:A` o CONJUNCT2 o REWRITE_RULE[eleqp]) THEN
  ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  MAP_EVERY EXISTS_TAC [`u:A`;`v:A`] THEN ASM_REWRITE_TAC[]);;

(* ==================================================================== *)
(* Internal table-lookup functions for the F6.5a fiber construction.     *)
(* Given internal sets u (a function                                    *)
(* graph), a fixed vv, and an internal table sIN, the graph               *)
(*   h = { <xi,z> IN a x bb : sIN(<u(xi),vv>) = z }                       *)
(* is an internal set, by SEPARATION over a x bb with u,vv,sIN as         *)
(* PARAMETERS (they are sets in D, hence legal valuation parameters).    *)
(* This is the separation-with-table-parameters route used for F6.5a's   *)
(* fiber internality. Slot plan: sep var 0 = the pair; params 16=u,      *)
(* 17=vv,                                                                *)
(* 18=sIN; bound 3=xi, 4=z, 5=w(=u(xi)), 6=pr(=<w,vv>).  Macro-internal  *)
(* bound slots shadow 17/18 inside single conjuncts -- local, harmless   *)
(* (FV(apply_form i j k)={i,j,k}, bridges hold for ANY valuation).       *)
(* ==================================================================== *)

(* ==================================================================== *)
(* F2.4  Regular-open sets over the Cohen poset (P, leqp).               *)
(* eopen: down-closure in the forcing order (q leqp p, p in u ==> q in   *)
(* u); ereg: density forcing (every q below p has an extension in u ==>  *)
(* p in u); B := { u in pow P : open /\ regular } by separation.         *)
(* rel_form (HOLDS_REL_FORM needs model+val) supplies the                *)
(* "q leqp p" atom.  Bridges are built LEVEL BY LEVEL (inner ??5, then   *)
(* !!4, then !!3) -- each level a 1-quantifier lemma, no big MESON.      *)
(* Slot plan: sep var 0 = u; params 1 = P, 2 = leqp; bound 3=p,4=q,5=r.  *)
(* rel_form 2 4 3 binds slot 5 internally -- local, harmless.            *)
(* ==================================================================== *)

let eopen = new_definition
  `eopen D (E:A->A->bool) leqp u <=>
     !p q. p IN D /\ q IN D /\ E p u /\ erel D E leqp q p ==> E q u`;;

let ereg = new_definition
  `ereg D (E:A->A->bool) P leqp u <=>
     !p. p IN D /\ E p P /\
         (!q. q IN D /\ erel D E leqp q p
              ==> ?r. r IN D /\ erel D E leqp r q /\ E r u)
         ==> E p u`;;

let eroset = new_definition
  `eroset D (E:A->A->bool) P leqp B <=>
     B IN D /\
     !u. u IN D
         ==> (E u B <=>
              esubset D E u P /\ eopen D E leqp u /\ ereg D E P leqp u)`;;

let open_form = new_definition
  `open_form = !! 3 (!! 4 (((3 %% 0) && rel_form 2 4 3) --> (4 %% 0)))`;;

let reg_form = new_definition
  `reg_form =
     !! 3 (((3 %% 1) &&
            !! 4 (rel_form 2 4 3
                  --> ?? 5 (rel_form 2 5 4 && (5 %% 0))))
           --> (3 %% 0))`;;

let roset_form = new_definition
  `roset_form = subset_form 0 1 && open_form && reg_form`;;

let OPEN_FORM_HOLDS = prove
 (`!D (E:A->A->bool) v.
      model D E ZF_AX /\ valuation D v
      ==> (holds D E v open_form <=>
           !p q. p IN D /\ q IN D /\ E p (v 0) /\ erel D E (v 2) q p
                 ==> E q (v 0))`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[open_form; HOLDS_ALL] THEN
  SUBGOAL_THEN
   `!p q:A. p IN D /\ q IN D
      ==> (holds D E ((4 |-> q) ((3 |-> p) v))
             (((3 %% 0) && rel_form 2 4 3) --> (4 %% 0)) <=>
           (E p (v 0) /\ erel D E (v 2) q p ==> E q (v 0)))`
   (LABEL_TAC "body") THENL
   [REPEAT STRIP_TAC THEN
    SUBGOAL_THEN `valuation D ((4 |-> (q:A)) ((3 |-> (p:A)) v))`
      ASSUME_TAC THENL
      [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
    REWRITE_TAC[HOLDS_IMP; HOLDS_AND; HOLDS_MEM] THEN
    MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;
      `(4 |-> (q:A)) ((3 |-> (p:A)) v)`;`2`;`4`;`3`] HOLDS_REL_FORM) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    REWRITE_TAC[VALMOD; ARITH_EQ];
    ALL_TAC] THEN
  EQ_TAC THENL
   [DISCH_THEN(LABEL_TAC "lhs") THEN
    MAP_EVERY X_GEN_TAC [`p:A`;`q:A`] THEN STRIP_TAC THEN
    USE_THEN "lhs" (MP_TAC o SPEC `p:A`) THEN
    ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN(MP_TAC o SPEC `q:A`) THEN
    ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    USE_THEN "body" (MP_TAC o SPECL [`p:A`;`q:A`]) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    DISCH_THEN MATCH_MP_TAC THEN ASM_REWRITE_TAC[];
    DISCH_THEN(LABEL_TAC "sem") THEN
    X_GEN_TAC `p:A` THEN DISCH_TAC THEN
    X_GEN_TAC `q:A` THEN DISCH_TAC THEN
    USE_THEN "body" (MP_TAC o SPECL [`p:A`;`q:A`]) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    STRIP_TAC THEN
    USE_THEN "sem" (MP_TAC o SPECL [`p:A`;`q:A`]) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC]]);;

let REG_INNER_HOLDS = prove
 (`!D (E:A->A->bool) v.
      model D E ZF_AX /\ valuation D v
      ==> (holds D E v (?? 5 (rel_form 2 5 4 && (5 %% 0))) <=>
           ?r. r IN D /\ erel D E (v 2) r (v 4) /\ E r (v 0))`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[HOLDS_EX] THEN
  SUBGOAL_THEN
   `!r:A. r IN D
      ==> (holds D E ((5 |-> r) v) (rel_form 2 5 4 && (5 %% 0)) <=>
           erel D E (v 2) r (v 4) /\ E r (v 0))`
   (LABEL_TAC "body") THENL
   [REPEAT STRIP_TAC THEN
    SUBGOAL_THEN `valuation D ((5 |-> (r:A)) v)` ASSUME_TAC THENL
     [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
    REWRITE_TAC[HOLDS_AND; HOLDS_MEM] THEN
    MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`(5 |-> (r:A)) v`;`2`;`5`;`4`]
      HOLDS_REL_FORM) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    REWRITE_TAC[VALMOD; ARITH_EQ];
    ALL_TAC] THEN
  EQ_TAC THENL
   [DISCH_THEN(X_CHOOSE_THEN `r:A` (CONJUNCTS_THEN2 ASSUME_TAC MP_TAC)) THEN
    USE_THEN "body" (MP_TAC o SPEC `r:A`) THEN
    ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN STRIP_TAC THEN
    EXISTS_TAC `r:A` THEN ASM_REWRITE_TAC[];
    DISCH_THEN(X_CHOOSE_THEN `r:A` STRIP_ASSUME_TAC) THEN
    EXISTS_TAC `r:A` THEN CONJ_TAC THENL
     [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    USE_THEN "body" (MP_TAC o SPEC `r:A`) THEN
    ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN ASM_REWRITE_TAC[]]);;

let REG_DENSE_HOLDS = prove
 (`!D (E:A->A->bool) v.
      model D E ZF_AX /\ valuation D v
      ==> (holds D E v (!! 4 (rel_form 2 4 3
                              --> ?? 5 (rel_form 2 5 4 && (5 %% 0)))) <=>
           !q. q IN D /\ erel D E (v 2) q (v 3)
               ==> ?r. r IN D /\ erel D E (v 2) r q /\ E r (v 0))`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[HOLDS_ALL] THEN
  SUBGOAL_THEN
   `!q:A. q IN D
      ==> (holds D E ((4 |-> q) v)
             (rel_form 2 4 3 --> ?? 5 (rel_form 2 5 4 && (5 %% 0))) <=>
           (erel D E (v 2) q (v 3)
            ==> ?r. r IN D /\ erel D E (v 2) r q /\ E r (v 0)))`
   (LABEL_TAC "body") THENL
   [REPEAT STRIP_TAC THEN
    SUBGOAL_THEN `valuation D ((4 |-> (q:A)) v)` ASSUME_TAC THENL
     [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
    REWRITE_TAC[HOLDS_IMP] THEN
    MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`(4 |-> (q:A)) v`;`2`;`4`;`3`]
      HOLDS_REL_FORM) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`(4 |-> (q:A)) v`]
      REG_INNER_HOLDS) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    REWRITE_TAC[VALMOD; ARITH_EQ];
    ALL_TAC] THEN
  EQ_TAC THENL
   [DISCH_THEN(LABEL_TAC "lhs") THEN
    X_GEN_TAC `q:A` THEN STRIP_TAC THEN
    USE_THEN "lhs" (MP_TAC o SPEC `q:A`) THEN
    ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    USE_THEN "body" (MP_TAC o SPEC `q:A`) THEN
    ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    DISCH_THEN MATCH_MP_TAC THEN FIRST_ASSUM ACCEPT_TAC;
    DISCH_THEN(LABEL_TAC "sem") THEN
    X_GEN_TAC `q:A` THEN DISCH_TAC THEN
    USE_THEN "body" (MP_TAC o SPEC `q:A`) THEN
    ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    DISCH_TAC THEN
    USE_THEN "sem" (MP_TAC o SPEC `q:A`) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC]]);;

let REG_FORM_HOLDS = prove
 (`!D (E:A->A->bool) v.
      model D E ZF_AX /\ valuation D v
      ==> (holds D E v reg_form <=>
           !p. p IN D /\ E p (v 1) /\
               (!q. q IN D /\ erel D E (v 2) q p
                    ==> ?r. r IN D /\ erel D E (v 2) r q /\ E r (v 0))
               ==> E p (v 0))`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[reg_form; HOLDS_ALL] THEN
  SUBGOAL_THEN
   `!p:A. p IN D
      ==> (holds D E ((3 |-> p) v)
             (((3 %% 1) &&
               !! 4 (rel_form 2 4 3 --> ?? 5 (rel_form 2 5 4 && (5 %% 0))))
              --> (3 %% 0)) <=>
           (E p (v 1) /\
            (!q. q IN D /\ erel D E (v 2) q p
                 ==> ?r. r IN D /\ erel D E (v 2) r q /\ E r (v 0))
            ==> E p (v 0)))`
   (LABEL_TAC "body") THENL
   [REPEAT STRIP_TAC THEN
    SUBGOAL_THEN `valuation D ((3 |-> (p:A)) v)` ASSUME_TAC THENL
     [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
    REWRITE_TAC[HOLDS_IMP; HOLDS_AND; HOLDS_MEM] THEN
    MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`(3 |-> (p:A)) v`]
      REG_DENSE_HOLDS) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    REWRITE_TAC[VALMOD; ARITH_EQ];
    ALL_TAC] THEN
  EQ_TAC THENL
   [DISCH_THEN(LABEL_TAC "lhs") THEN
    X_GEN_TAC `p:A` THEN STRIP_TAC THEN
    USE_THEN "lhs" (MP_TAC o SPEC `p:A`) THEN
    ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    USE_THEN "body" (MP_TAC o SPEC `p:A`) THEN
    ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    DISCH_THEN MATCH_MP_TAC THEN CONJ_TAC THENL
     [FIRST_ASSUM ACCEPT_TAC; FIRST_ASSUM ACCEPT_TAC];
    DISCH_THEN(LABEL_TAC "sem") THEN
    X_GEN_TAC `p:A` THEN DISCH_TAC THEN
    USE_THEN "body" (MP_TAC o SPEC `p:A`) THEN
    ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    STRIP_TAC THEN
    USE_THEN "sem" (MP_TAC o SPEC `p:A`) THEN
    ANTS_TAC THENL [ASM_MESON_TAC[]; DISCH_THEN ACCEPT_TAC]]);;

let EROSET_EXISTS = prove
 (`!D (E:A->A->bool) P leqp.
      model D E ZF_AX /\ P IN D /\ leqp IN D
      ==> ?B. eroset D E P leqp B`,
  REPEAT STRIP_TAC THEN
  MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`P:A`] EPOW_EXISTS) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `pw:A` (LABEL_TAC "pw")) THEN
  SUBGOAL_THEN `(pw:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[EPOW_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `valuation D ((1 |-> (P:A)) ((2 |-> (leqp:A)) (\n:num. P:A)))`
   (LABEL_TAC "val") THENL
   [MATCH_MP_TAC VALUATION_VALMOD THEN CONJ_TAC THENL
     [MATCH_MP_TAC VALUATION_VALMOD THEN CONJ_TAC THENL
       [REWRITE_TAC[valuation] THEN FIRST_ASSUM ACCEPT_TAC;
        FIRST_ASSUM ACCEPT_TAC];
      FIRST_ASSUM ACCEPT_TAC];
    ALL_TAC] THEN
  MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`] ZF_SEPARATION) THEN
  ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  DISCH_THEN(MP_TAC o ISPECL
    [`roset_form`; `0`;
     `(1 |-> (P:A)) ((2 |-> (leqp:A)) (\n:num. P:A))`; `pw:A`]) THEN
  ANTS_TAC THENL
   [CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
    DISCH_THEN(X_CHOOSE_THEN `B:A`
      (CONJUNCTS_THEN2 ASSUME_TAC (LABEL_TAC "sep")))] THEN
  EXISTS_TAC `B:A` THEN REWRITE_TAC[eroset] THEN
  CONJ_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  X_GEN_TAC `u:A` THEN DISCH_TAC THEN
  SUBGOAL_THEN
   `valuation D
    ((0 |-> (u:A)) ((1 |-> (P:A)) ((2 |-> (leqp:A)) (\n:num. P:A))))`
   (LABEL_TAC "valV") THENL
   [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `E (u:A) pw <=> esubset D E u P` (LABEL_TAC "pwm") THENL
   [ASM_MESON_TAC[epow]; ALL_TAC] THEN
  SUBGOAL_THEN
   `holds D E ((0 |-> (u:A)) ((1 |-> (P:A)) ((2 |-> (leqp:A)) (\n:num. P:A))))
      roset_form <=>
    esubset D E u P /\ eopen D E leqp u /\ ereg D E P leqp u`
   (LABEL_TAC "hc") THENL
   [REWRITE_TAC[roset_form; HOLDS_AND] THEN
    REWRITE_TAC[HOLDS_SUBSET_FORM; eopen; ereg] THEN
    MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;
      `(0 |-> (u:A)) ((1 |-> (P:A)) ((2 |-> (leqp:A)) (\n:num. P:A)))`]
      OPEN_FORM_HOLDS) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;
      `(0 |-> (u:A)) ((1 |-> (P:A)) ((2 |-> (leqp:A)) (\n:num. P:A)))`]
      REG_FORM_HOLDS) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    REWRITE_TAC[VALMOD; ARITH_EQ];
    ALL_TAC] THEN
  USE_THEN "sep" (MP_TAC o SPEC `u:A`) THEN
  ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  USE_THEN "pwm" (fun t1 -> USE_THEN "hc" (fun t2 -> REWRITE_TAC[t1;t2])) THEN
  CONV_TAC TAUT);;

(* ==================================================================== *)
(* F2.5a  Straight-INCLUSION order set on an arbitrary carrier X:        *)
(*   eincl X r :  E pr r <=> pr = <u,v> with u,v in X and u SUBSET v.    *)
(* (The Cohen-poset order eleqp is the CONVERSE -- q leqp p <=> p SUBSET *)
(* q, "stronger = bigger".  The RO algebra B is ordered by STRAIGHT      *)
(* inclusion, bot = empty set, top = P, so it needs this second order.)  *)
(* Same lemma ladder as F2.3: def / form / bridge / EXISTS (separation   *)
(* over X x X) / erel destructor+constructor / eporder.                  *)
(* incl_form = leqp_form with the subset direction flipped (3 4, not    *)
(* 4 3); slots: sep var 0 = pair, bound 3 = u(first), 4 = v(second).     *)
(* ==================================================================== *)

let eincl = new_definition
  `eincl D (E:A->A->bool) X r <=>
     r IN D /\
     !pr. pr IN D
          ==> (E pr r <=>
               ?u v. u IN D /\ v IN D /\ E u X /\ E v X /\
                     eopair D E u v pr /\ esubset D E u v)`;;

let incl_form = new_definition
  `incl_form = ?? 3 (?? 4 (opair_form 3 4 0 && subset_form 3 4))`;;

let INCL_FORM_HOLDS = prove
 (`!D (E:A->A->bool) v.
      valuation D v
      ==> (holds D E v incl_form <=>
           ?u w. u IN D /\ w IN D /\ eopair D E u w (v 0) /\ esubset D E u w)`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[incl_form] THEN
  REWRITE_TAC[HOLDS_EX] THEN
  SUBGOAL_THEN
   `!a b:A. a IN D /\ b IN D
      ==> (holds D E ((4 |-> b) ((3 |-> a) v))
             (opair_form 3 4 0 && subset_form 3 4) <=>
           eopair D E a b (v 0) /\ esubset D E a b)`
   (LABEL_TAC "body") THENL
   [REPEAT STRIP_TAC THEN
    SUBGOAL_THEN `valuation D ((4 |-> (b:A)) ((3 |-> (a:A)) v))`
      ASSUME_TAC THENL
      [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
    ASM_SIMP_TAC[HOLDS_AND; HOLDS_OPAIR_FORM] THEN
    REWRITE_TAC[HOLDS_SUBSET_FORM; VALMOD; ARITH_EQ];
    ALL_TAC] THEN
  EQ_TAC THENL
   [DISCH_THEN(X_CHOOSE_THEN `a:A` (CONJUNCTS_THEN2 ASSUME_TAC
      (X_CHOOSE_THEN `b:A` (CONJUNCTS_THEN2 ASSUME_TAC MP_TAC)))) THEN
    USE_THEN "body" (MP_TAC o SPECL [`a:A`;`b:A`]) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN STRIP_TAC THEN
    MAP_EVERY EXISTS_TAC [`a:A`;`b:A`] THEN ASM_REWRITE_TAC[];
    DISCH_THEN(X_CHOOSE_THEN `u:A` (X_CHOOSE_THEN `w:A` STRIP_ASSUME_TAC)) THEN
    EXISTS_TAC `u:A` THEN CONJ_TAC THENL
     [FIRST_ASSUM ACCEPT_TAC;
      EXISTS_TAC `w:A` THEN CONJ_TAC THENL
       [FIRST_ASSUM ACCEPT_TAC;
        USE_THEN "body" (MP_TAC o SPECL [`u:A`;`w:A`]) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
        DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN ASM_REWRITE_TAC[]]]]);;

let EINCL_EXISTS = prove
 (`!D (E:A->A->bool) X.
      model D E ZF_AX /\ X IN D ==> ?r. eincl D E X r`,
  REPEAT STRIP_TAC THEN
  MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`X:A`;`X:A`] ECROSS_EXISTS) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `XX:A` (LABEL_TAC "cr")) THEN
  SUBGOAL_THEN `(XX:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[ecross]; ALL_TAC] THEN
  SUBGOAL_THEN `?v:num->A. valuation D v` (X_CHOOSE_TAC `v0:num->A`) THENL
   [MATCH_MP_TAC VALUATION_EXISTS THEN ASM_MESON_TAC[MODEL_NONEMPTY];
    ALL_TAC] THEN
  MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`] ZF_SEPARATION) THEN
  ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  DISCH_THEN(MP_TAC o ISPECL [`incl_form`; `0`; `v0:num->A`; `XX:A`]) THEN
  ANTS_TAC THENL
   [CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
    DISCH_THEN(X_CHOOSE_THEN `r:A`
      (CONJUNCTS_THEN2 ASSUME_TAC (LABEL_TAC "sep")))] THEN
  EXISTS_TAC `r:A` THEN REWRITE_TAC[eincl] THEN
  CONJ_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  X_GEN_TAC `pr:A` THEN DISCH_TAC THEN
  MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`X:A`;`X:A`;`XX:A`;`pr:A`]
    ECROSS_MEMBER) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN DISCH_TAC THEN
  SUBGOAL_THEN `valuation D ((0 |-> (pr:A)) v0)` ASSUME_TAC THENL
   [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`(0 |-> (pr:A)) v0`]
         INCL_FORM_HOLDS) THEN
  ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  REWRITE_TAC[VALMOD; ARITH_EQ] THEN DISCH_TAC THEN
  USE_THEN "sep" (MP_TAC o SPEC `pr:A`) THEN
  ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  DISCH_THEN SUBST1_TAC THEN
  ASM_MESON_TAC[EOPAIR_INJ]);;

(* -- erel destructor / constructor (the destructor needs u,v IN D so    *)
(* that EOPAIR_INJ can pin components).                                  *)

let EINCL_EREL = prove
 (`!D (E:A->A->bool) X r u v.
      model D E ZF_AX /\ eincl D E X r /\ u IN D /\ v IN D /\
      erel D E r u v
      ==> E u X /\ E v X /\ esubset D E u v`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  UNDISCH_TAC `erel D (E:A->A->bool) r u v` THEN REWRITE_TAC[erel] THEN
  DISCH_THEN(X_CHOOSE_THEN `pr:A` STRIP_ASSUME_TAC o CONJUNCT2 o
             CONJUNCT2) THEN
  FIRST_ASSUM(MP_TAC o SPEC `pr:A` o CONJUNCT2 o REWRITE_RULE[eincl]) THEN
  ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  DISCH_THEN(fun th -> MP_TAC(EQ_MP th (ASSUME `(E:A->A->bool) pr r`))) THEN
  DISCH_THEN(X_CHOOSE_THEN `u':A` (X_CHOOSE_THEN `v':A` STRIP_ASSUME_TAC)) THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`u:A`;`v:A`;`u':A`;`v':A`;`pr:A`]
    EOPAIR_INJ) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[];
    DISCH_THEN(CONJUNCTS_THEN SUBST1_TAC) THEN ASM_REWRITE_TAC[]]);;

let EINCL_EREL_INTRO = prove
 (`!D (E:A->A->bool) X r u v.
      model D E ZF_AX /\ eincl D E X r /\
      u IN D /\ v IN D /\ E u X /\ E v X /\ esubset D E u v
      ==> erel D E r u v`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`u:A`;`v:A`] EOPAIR_EXISTS) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_TAC `pr:A`) THEN
  SUBGOAL_THEN `(pr:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[EOPAIR_IN]; ALL_TAC] THEN
  REWRITE_TAC[erel] THEN ASM_REWRITE_TAC[] THEN EXISTS_TAC `pr:A` THEN
  ASM_REWRITE_TAC[] THEN
  FIRST_ASSUM(MP_TAC o SPEC `pr:A` o CONJUNCT2 o REWRITE_RULE[eincl]) THEN
  ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  MAP_EVERY EXISTS_TAC [`u:A`;`v:A`] THEN ASM_REWRITE_TAC[]);;

(* -- eincl X is a partial order on X.                                   *)
let EPORDER_INCL = prove
 (`!D (E:A->A->bool) X r.
      model D E ZF_AX /\ X IN D /\ eincl D E X r
      ==> eporder D E X r`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  FIRST_ASSUM(ASSUME_TAC o CONJUNCT1 o REWRITE_RULE[eincl]) THEN
  REWRITE_TAC[eporder] THEN REPEAT CONJ_TAC THENL
   [ASM_REWRITE_TAC[];
    ASM_REWRITE_TAC[];
    MAP_EVERY X_GEN_TAC [`u:A`;`v:A`] THEN DISCH_TAC THEN
    FIRST_ASSUM(STRIP_ASSUME_TAC o GEN_REWRITE_RULE I [erel]) THEN
    ASM_REWRITE_TAC[] THEN
    MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`X:A`;`r:A`;`u:A`;`v:A`]
      EINCL_EREL) THEN
    ASM_REWRITE_TAC[] THEN STRIP_TAC THEN ASM_REWRITE_TAC[];
    X_GEN_TAC `u:A` THEN STRIP_TAC THEN
    MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`X:A`;`r:A`;`u:A`;`u:A`]
      EINCL_EREL_INTRO) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[ESUBSET_REFL]; DISCH_THEN ACCEPT_TAC];
    MAP_EVERY X_GEN_TAC [`u:A`;`v:A`] THEN STRIP_TAC THEN
    MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`X:A`;`r:A`;`u:A`;`v:A`]
      EINCL_EREL) THEN
    ASM_REWRITE_TAC[] THEN STRIP_TAC THEN
    MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`X:A`;`r:A`;`v:A`;`u:A`]
      EINCL_EREL) THEN
    ASM_REWRITE_TAC[] THEN STRIP_TAC THEN
    MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`u:A`;`v:A`] ESUBSET_ANTISYM) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC];
    MAP_EVERY X_GEN_TAC [`u:A`;`v:A`;`w:A`] THEN STRIP_TAC THEN
    MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`X:A`;`r:A`;`u:A`;`v:A`]
      EINCL_EREL) THEN
    ASM_REWRITE_TAC[] THEN STRIP_TAC THEN
    MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`X:A`;`r:A`;`v:A`;`w:A`]
      EINCL_EREL) THEN
    ASM_REWRITE_TAC[] THEN STRIP_TAC THEN
    MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`X:A`;`r:A`;`u:A`;`w:A`]
      EINCL_EREL_INTRO) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[] THEN
      UNDISCH_TAC `esubset D (E:A->A->bool) v w` THEN
      UNDISCH_TAC `esubset D (E:A->A->bool) u v` THEN
      REWRITE_TAC[esubset] THEN MESON_TAC[];
      DISCH_THEN ACCEPT_TAC]]);;

(* ==================================================================== *)
(* F2.5b  Bottom and top of the RO carrier: the empty set and P itself   *)
(* are regular open; they are ebot/etop of (B, eincl B); and bot <> top  *)
(* because the empty CONDITION lies in P (ECOHENP_HAS_EMPTY) while the   *)
(* empty set has no members.                                             *)
(* ==================================================================== *)

let EROSET_TOP = prove
 (`!D (E:A->A->bool) P leqp B.
      model D E ZF_AX /\ P IN D /\ eleqp D E P leqp /\ eroset D E P leqp B
      ==> E P B`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  FIRST_ASSUM(MP_TAC o SPEC `P:A` o CONJUNCT2 o REWRITE_RULE[eroset]) THEN
  ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  REPEAT CONJ_TAC THENL
   [REWRITE_TAC[ESUBSET_REFL];
    REWRITE_TAC[eopen] THEN
    MAP_EVERY X_GEN_TAC [`p:A`;`q:A`] THEN STRIP_TAC THEN
    MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`P:A`;`leqp:A`;`q:A`;`p:A`]
      ELEQP_EREL) THEN
    ASM_REWRITE_TAC[] THEN STRIP_TAC THEN FIRST_ASSUM ACCEPT_TAC;
    REWRITE_TAC[ereg] THEN REPEAT STRIP_TAC THEN FIRST_ASSUM ACCEPT_TAC]);;

let EROSET_BOT = prove
 (`!D (E:A->A->bool) P leqp B z.
      model D E ZF_AX /\ eleqp D E P leqp /\ eroset D E P leqp B /\
      eempty D E z /\ z IN D
      ==> E z B`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  FIRST_ASSUM(MP_TAC o SPEC `z:A` o CONJUNCT2 o REWRITE_RULE[eroset]) THEN
  ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  REPEAT CONJ_TAC THENL
   [MATCH_MP_TAC EEMPTY_SUBSET THEN FIRST_ASSUM ACCEPT_TAC;
    REWRITE_TAC[eopen] THEN REPEAT STRIP_TAC THEN ASM_MESON_TAC[eempty];
    REWRITE_TAC[ereg] THEN X_GEN_TAC `p:A` THEN STRIP_TAC THEN
    FIRST_X_ASSUM(MP_TAC o SPEC `p:A`) THEN
    ANTS_TAC THENL
     [CONJ_TAC THENL
       [FIRST_ASSUM ACCEPT_TAC;
        MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`P:A`;`leqp:A`;`p:A`;`p:A`]
          ELEQP_EREL_INTRO) THEN
        ANTS_TAC THENL
         [ASM_REWRITE_TAC[ESUBSET_REFL]; DISCH_THEN ACCEPT_TAC]];
      DISCH_THEN(X_CHOOSE_THEN `r:A` STRIP_ASSUME_TAC) THEN
      ASM_MESON_TAC[eempty]]]);;

let ECOHENP_NE = prove
 (`!D (E:A->A->bool) ci om P z.
      model D E ZF_AX /\ eomega D E om /\ ecohenp D E ci om P /\
      eempty D E z /\ z IN D
      ==> ~(z = P)`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`ci:A`;`om:A`;`P:A`;`z:A`]
    ECOHENP_HAS_EMPTY) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_TAC THEN ASM_MESON_TAC[eempty]);;

let EBOT_ROSET = prove
 (`!D (E:A->A->bool) P leqp B inclB z.
      model D E ZF_AX /\ eleqp D E P leqp /\ eroset D E P leqp B /\
      eincl D E B inclB /\ eempty D E z /\ z IN D
      ==> ebot D E B inclB z`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `(E:A->A->bool) z B` ASSUME_TAC THENL
   [MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`P:A`;`leqp:A`;`B:A`;`z:A`]
      EROSET_BOT) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC];
    ALL_TAC] THEN
  REWRITE_TAC[ebot] THEN ASM_REWRITE_TAC[] THEN
  X_GEN_TAC `x:A` THEN STRIP_TAC THEN
  MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`inclB:A`;`z:A`;`x:A`]
    EINCL_EREL_INTRO) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[] THEN MATCH_MP_TAC EEMPTY_SUBSET THEN
    FIRST_ASSUM ACCEPT_TAC;
    DISCH_THEN ACCEPT_TAC]);;

let ETOP_ROSET = prove
 (`!D (E:A->A->bool) P leqp B inclB.
      model D E ZF_AX /\ P IN D /\ eleqp D E P leqp /\
      eroset D E P leqp B /\ eincl D E B inclB
      ==> etop D E B inclB P`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `(E:A->A->bool) P B` ASSUME_TAC THENL
   [MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`P:A`;`leqp:A`;`B:A`]
      EROSET_TOP) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC];
    ALL_TAC] THEN
  REWRITE_TAC[etop] THEN ASM_REWRITE_TAC[] THEN
  X_GEN_TAC `x:A` THEN STRIP_TAC THEN
  SUBGOAL_THEN `esubset D (E:A->A->bool) x P` ASSUME_TAC THENL
   [FIRST_ASSUM(MP_TAC o SPEC `x:A` o CONJUNCT2 o REWRITE_RULE[eroset]) THEN
    ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN(fun th -> MP_TAC(EQ_MP th (ASSUME `(E:A->A->bool) x B`))) THEN
    STRIP_TAC THEN FIRST_ASSUM ACCEPT_TAC;
    ALL_TAC] THEN
  MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`inclB:A`;`x:A`;`P:A`]
    EINCL_EREL_INTRO) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC]);;

(* ==================================================================== *)
(* F2.6a  The interior-of-closure operator intcl and its RO facts.       *)
(*   eintcl P leqp w ic :  ic = { p in P : !q<=p. ?r<=q. r in w }.       *)
(* intcl w is ALWAYS regular open; for open u SUBSET P, u SUBSET intcl   *)
(* u; intcl w is the LEAST regular set above w.  Plus: down-closure of   *)
(* binary unions/intersections.  The order facts come from              *)
(* ELEQP_EREL/_INTRO + the two helpers below.                            *)
(* Separation reuses the reg_form inner block, whose bridge is           *)
(* REG_DENSE_HOLDS verbatim: sep var 3, params 0=w, 2=leqp.              *)
(* ==================================================================== *)

let LEQP_REFL_E = prove
 (`!D (E:A->A->bool) P leqp p.
      model D E ZF_AX /\ eleqp D E P leqp /\ p IN D /\ E p P
      ==> erel D E leqp p p`,
  REPEAT STRIP_TAC THEN
  MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`P:A`;`leqp:A`;`p:A`;`p:A`]
    ELEQP_EREL_INTRO) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[ESUBSET_REFL]; DISCH_THEN ACCEPT_TAC]);;

let LEQP_TRANS_E = prove
 (`!D (E:A->A->bool) P leqp u v w.
      model D E ZF_AX /\ eleqp D E P leqp /\ u IN D /\ v IN D /\ w IN D /\
      erel D E leqp u v /\ erel D E leqp v w
      ==> erel D E leqp u w`,
  REPEAT STRIP_TAC THEN
  MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`P:A`;`leqp:A`;`u:A`;`v:A`]
    ELEQP_EREL) THEN
  ASM_REWRITE_TAC[] THEN STRIP_TAC THEN
  MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`P:A`;`leqp:A`;`v:A`;`w:A`]
    ELEQP_EREL) THEN
  ASM_REWRITE_TAC[] THEN STRIP_TAC THEN
  MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`P:A`;`leqp:A`;`u:A`;`w:A`]
    ELEQP_EREL_INTRO) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[] THEN
    UNDISCH_TAC `esubset D (E:A->A->bool) w v` THEN
    UNDISCH_TAC `esubset D (E:A->A->bool) v u` THEN
    REWRITE_TAC[esubset] THEN MESON_TAC[];
    DISCH_THEN ACCEPT_TAC]);;

let eintcl = new_definition
  `eintcl D (E:A->A->bool) P leqp w ic <=>
     ic IN D /\
     !p. p IN D
         ==> (E p ic <=>
              E p P /\
              !q. q IN D /\ erel D E leqp q p
                  ==> ?r. r IN D /\ erel D E leqp r q /\ E r w)`;;

let EINTCL_EXISTS = prove
 (`!D (E:A->A->bool) P leqp w.
      model D E ZF_AX /\ P IN D /\ leqp IN D /\ w IN D
      ==> ?ic. eintcl D E P leqp w ic`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `valuation D ((0 |-> (w:A)) ((2 |-> (leqp:A)) (\n:num. P:A)))`
   (LABEL_TAC "val") THENL
   [MATCH_MP_TAC VALUATION_VALMOD THEN CONJ_TAC THENL
     [MATCH_MP_TAC VALUATION_VALMOD THEN CONJ_TAC THENL
       [REWRITE_TAC[valuation] THEN FIRST_ASSUM ACCEPT_TAC;
        FIRST_ASSUM ACCEPT_TAC];
      FIRST_ASSUM ACCEPT_TAC];
    ALL_TAC] THEN
  MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`] ZF_SEPARATION) THEN
  ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  DISCH_THEN(MP_TAC o ISPECL
    [`!! 4 (rel_form 2 4 3 --> ?? 5 (rel_form 2 5 4 && (5 %% 0)))`; `3`;
     `(0 |-> (w:A)) ((2 |-> (leqp:A)) (\n:num. P:A))`; `P:A`]) THEN
  ANTS_TAC THENL
   [CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
    DISCH_THEN(X_CHOOSE_THEN `ic:A`
      (CONJUNCTS_THEN2 ASSUME_TAC (LABEL_TAC "sep")))] THEN
  EXISTS_TAC `ic:A` THEN REWRITE_TAC[eintcl] THEN
  CONJ_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  X_GEN_TAC `p:A` THEN DISCH_TAC THEN
  USE_THEN "sep" (MP_TAC o SPEC `p:A`) THEN
  ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  DISCH_THEN SUBST1_TAC THEN
  SUBGOAL_THEN
   `valuation D
    ((3 |-> (p:A)) ((0 |-> (w:A)) ((2 |-> (leqp:A)) (\n:num. P:A))))`
   ASSUME_TAC THENL
   [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;
    `(3 |-> (p:A)) ((0 |-> (w:A)) ((2 |-> (leqp:A)) (\n:num. P:A)))`]
    REG_DENSE_HOLDS) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  REWRITE_TAC[VALMOD; ARITH_EQ] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]));;

let EINTCL_OPEN = prove
 (`!D (E:A->A->bool) P leqp w ic.
      model D E ZF_AX /\ eleqp D E P leqp /\ eintcl D E P leqp w ic
      ==> eopen D E leqp ic`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[eopen] THEN
  MAP_EVERY X_GEN_TAC [`p:A`;`q:A`] THEN STRIP_TAC THEN
  FIRST_ASSUM(MP_TAC o SPEC `p:A` o CONJUNCT2 o REWRITE_RULE[eintcl]) THEN
  ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  DISCH_THEN(fun th -> MP_TAC(EQ_MP th (ASSUME `(E:A->A->bool) p ic`))) THEN
  DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "pP") (LABEL_TAC "dns")) THEN
  FIRST_ASSUM(MP_TAC o SPEC `q:A` o CONJUNCT2 o REWRITE_RULE[eintcl]) THEN
  ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  CONJ_TAC THENL
   [MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`P:A`;`leqp:A`;`q:A`;`p:A`]
      ELEQP_EREL) THEN
    ASM_REWRITE_TAC[] THEN DISCH_THEN(ACCEPT_TAC o CONJUNCT1);
    X_GEN_TAC `q':A` THEN STRIP_TAC THEN
    USE_THEN "dns" (MP_TAC o SPEC `q':A`) THEN
    ANTS_TAC THENL
     [CONJ_TAC THENL
       [FIRST_ASSUM ACCEPT_TAC;
        MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`P:A`;`leqp:A`;
          `q':A`;`q:A`;`p:A`] LEQP_TRANS_E) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC]];
      DISCH_THEN ACCEPT_TAC]]);;

let EINTCL_REG = prove
 (`!D (E:A->A->bool) P leqp w ic.
      model D E ZF_AX /\ eleqp D E P leqp /\ eintcl D E P leqp w ic
      ==> ereg D E P leqp ic`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[ereg] THEN
  X_GEN_TAC `p:A` THEN
  DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC
    (CONJUNCTS_THEN2 ASSUME_TAC (LABEL_TAC "dic"))) THEN
  FIRST_ASSUM(MP_TAC o SPEC `p:A` o CONJUNCT2 o REWRITE_RULE[eintcl]) THEN
  ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  ASM_REWRITE_TAC[] THEN
  X_GEN_TAC `q:A` THEN STRIP_TAC THEN
  USE_THEN "dic" (MP_TAC o SPEC `q:A`) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `r:A` STRIP_ASSUME_TAC) THEN
  SUBGOAL_THEN `(E:A->A->bool) r P` ASSUME_TAC THENL
   [MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`P:A`;`leqp:A`;`r:A`;`q:A`]
      ELEQP_EREL) THEN
    ASM_REWRITE_TAC[] THEN DISCH_THEN(ACCEPT_TAC o CONJUNCT1);
    ALL_TAC] THEN
  FIRST_ASSUM(MP_TAC o SPEC `r:A` o CONJUNCT2 o REWRITE_RULE[eintcl]) THEN
  ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  DISCH_THEN(fun th -> MP_TAC(EQ_MP th (ASSUME `(E:A->A->bool) r ic`))) THEN
  DISCH_THEN(CONJUNCTS_THEN2 (K ALL_TAC) (LABEL_TAC "dwr")) THEN
  USE_THEN "dwr" (MP_TAC o SPEC `r:A`) THEN
  ANTS_TAC THENL
   [CONJ_TAC THENL
     [FIRST_ASSUM ACCEPT_TAC;
      MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`P:A`;`leqp:A`;`r:A`]
        LEQP_REFL_E) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC]];
    ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `t:A` STRIP_ASSUME_TAC) THEN
  EXISTS_TAC `t:A` THEN ASM_REWRITE_TAC[] THEN
  MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`P:A`;`leqp:A`;`t:A`;`r:A`;`q:A`]
    LEQP_TRANS_E) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC]);;

let EINTCL_RO = prove
 (`!D (E:A->A->bool) P leqp w ic B.
      model D E ZF_AX /\ eleqp D E P leqp /\ eroset D E P leqp B /\
      eintcl D E P leqp w ic
      ==> E ic B`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `(ic:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[eintcl]; ALL_TAC] THEN
  FIRST_ASSUM(MP_TAC o SPEC `ic:A` o CONJUNCT2 o REWRITE_RULE[eroset]) THEN
  ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  REPEAT CONJ_TAC THENL
   [REWRITE_TAC[esubset] THEN X_GEN_TAC `m:A` THEN STRIP_TAC THEN
    FIRST_ASSUM(MP_TAC o SPEC `m:A` o CONJUNCT2 o REWRITE_RULE[eintcl]) THEN
    ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN(fun th -> MP_TAC(EQ_MP th (ASSUME `(E:A->A->bool) m ic`))) THEN
    DISCH_THEN(CONJUNCTS_THEN2 ACCEPT_TAC (K ALL_TAC));
    MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`P:A`;`leqp:A`;`w:A`;`ic:A`]
      EINTCL_OPEN) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC];
    MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`P:A`;`leqp:A`;`w:A`;`ic:A`]
      EINTCL_REG) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC]]);;

let EINTCL_EXPAND = prove
 (`!D (E:A->A->bool) P leqp u ic.
      model D E ZF_AX /\ eleqp D E P leqp /\ esubset D E u P /\
      eopen D E leqp u /\ eintcl D E P leqp u ic
      ==> esubset D E u ic`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[esubset] THEN
  X_GEN_TAC `p:A` THEN STRIP_TAC THEN
  SUBGOAL_THEN `(E:A->A->bool) p P` ASSUME_TAC THENL
   [UNDISCH_TAC `esubset D (E:A->A->bool) u P` THEN REWRITE_TAC[esubset] THEN
    DISCH_THEN MATCH_MP_TAC THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  FIRST_ASSUM(MP_TAC o SPEC `p:A` o CONJUNCT2 o REWRITE_RULE[eintcl]) THEN
  ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  ASM_REWRITE_TAC[] THEN
  X_GEN_TAC `q:A` THEN STRIP_TAC THEN
  SUBGOAL_THEN `(E:A->A->bool) q u` ASSUME_TAC THENL
   [UNDISCH_TAC `eopen D (E:A->A->bool) leqp u` THEN REWRITE_TAC[eopen] THEN
    DISCH_THEN(MP_TAC o SPECL [`p:A`;`q:A`]) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC];
    ALL_TAC] THEN
  EXISTS_TAC `q:A` THEN ASM_REWRITE_TAC[] THEN
  MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`P:A`;`leqp:A`;`q:A`]
    LEQP_REFL_E) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[] THEN
    MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`P:A`;`leqp:A`;`q:A`;`p:A`]
      ELEQP_EREL) THEN
    ASM_REWRITE_TAC[] THEN DISCH_THEN(ACCEPT_TAC o CONJUNCT1);
    DISCH_THEN ACCEPT_TAC]);;

let EINTCL_MIN = prove
 (`!D (E:A->A->bool) P leqp w ic x.
      model D E ZF_AX /\ eleqp D E P leqp /\ eintcl D E P leqp w ic /\
      x IN D /\ esubset D E w x /\ ereg D E P leqp x
      ==> esubset D E ic x`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[esubset] THEN
  X_GEN_TAC `p:A` THEN STRIP_TAC THEN
  FIRST_ASSUM(MP_TAC o SPEC `p:A` o CONJUNCT2 o REWRITE_RULE[eintcl]) THEN
  ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  DISCH_THEN(fun th -> MP_TAC(EQ_MP th (ASSUME `(E:A->A->bool) p ic`))) THEN
  DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC (LABEL_TAC "dns")) THEN
  UNDISCH_TAC `ereg D (E:A->A->bool) P leqp x` THEN REWRITE_TAC[ereg] THEN
  DISCH_THEN(MP_TAC o SPEC `p:A`) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[] THEN
    X_GEN_TAC `q:A` THEN STRIP_TAC THEN
    USE_THEN "dns" (MP_TAC o SPEC `q:A`) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(X_CHOOSE_THEN `r:A` STRIP_ASSUME_TAC) THEN
    EXISTS_TAC `r:A` THEN ASM_REWRITE_TAC[] THEN
    UNDISCH_TAC `esubset D (E:A->A->bool) w x` THEN REWRITE_TAC[esubset] THEN
    DISCH_THEN MATCH_MP_TAC THEN ASM_REWRITE_TAC[];
    DISCH_THEN ACCEPT_TAC]);;

let EBUNION_OPEN = prove
 (`!D (E:A->A->bool) leqp u v w.
      model D E ZF_AX /\ u IN D /\ v IN D /\ w IN D /\
      eopen D E leqp u /\ eopen D E leqp v /\ ebunion D E u v w
      ==> eopen D E leqp w`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[eopen] THEN
  MAP_EVERY X_GEN_TAC [`p:A`;`q:A`] THEN STRIP_TAC THEN
  MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`u:A`;`v:A`;`w:A`]
         EBUNION_CHAR) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(fun th ->
    MP_TAC(EQ_MP th (ASSUME `ebunion D (E:A->A->bool) u v w`))) THEN
  DISCH_THEN(LABEL_TAC "ch") THEN
  SUBGOAL_THEN `(E:A->A->bool) p u \/ (E:A->A->bool) p v` MP_TAC THENL
   [USE_THEN "ch" (MP_TAC o SPEC `p:A`) THEN
    ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[GSYM th]) THEN FIRST_ASSUM ACCEPT_TAC;
    ALL_TAC] THEN
  USE_THEN "ch" (MP_TAC o SPEC `q:A`) THEN
  ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  STRIP_TAC THENL
   [DISJ1_TAC THEN
    UNDISCH_TAC `eopen D (E:A->A->bool) leqp u` THEN REWRITE_TAC[eopen] THEN
    DISCH_THEN(MP_TAC o SPECL [`p:A`;`q:A`]) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC];
    DISJ2_TAC THEN
    UNDISCH_TAC `eopen D (E:A->A->bool) leqp v` THEN REWRITE_TAC[eopen] THEN
    DISCH_THEN(MP_TAC o SPECL [`p:A`;`q:A`]) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC]]);;

let EINTER_OPEN = prove
 (`!D (E:A->A->bool) leqp u v z.
      model D E ZF_AX /\ u IN D /\ v IN D /\ z IN D /\
      eopen D E leqp u /\ eopen D E leqp v /\ einter D E u v z
      ==> eopen D E leqp z`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[eopen] THEN
  MAP_EVERY X_GEN_TAC [`p:A`;`q:A`] THEN STRIP_TAC THEN
  MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`u:A`;`v:A`;`z:A`] EINTER_CHAR) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(fun th ->
    MP_TAC(EQ_MP th (ASSUME `einter D (E:A->A->bool) u v z`))) THEN
  DISCH_THEN(LABEL_TAC "ch") THEN
  SUBGOAL_THEN `(E:A->A->bool) p u /\ (E:A->A->bool) p v`
    STRIP_ASSUME_TAC THENL
   [USE_THEN "ch" (MP_TAC o SPEC `p:A`) THEN
    ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[GSYM th]) THEN FIRST_ASSUM ACCEPT_TAC;
    ALL_TAC] THEN
  USE_THEN "ch" (MP_TAC o SPEC `q:A`) THEN
  ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  CONJ_TAC THENL
   [UNDISCH_TAC `eopen D (E:A->A->bool) leqp u` THEN REWRITE_TAC[eopen] THEN
    DISCH_THEN(MP_TAC o SPECL [`p:A`;`q:A`]) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC];
    UNDISCH_TAC `eopen D (E:A->A->bool) leqp v` THEN REWRITE_TAC[eopen] THEN
    DISCH_THEN(MP_TAC o SPECL [`p:A`;`q:A`]) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC]]);;

(* ==================================================================== *)
(* F2.6b  Meet = intersection on the RO algebra; the complement set      *)
(*   ecomplro P leqp u c :  c = { p in P : !q<=p. ~(q in u) }            *)
(* with its RO-membership.                                               *)
(* ==================================================================== *)

let EMEET_ROSET = prove
 (`!D (E:A->A->bool) P leqp B inclB u v z.
      model D E ZF_AX /\ eleqp D E P leqp /\ eroset D E P leqp B /\
      eincl D E B inclB /\
      u IN D /\ v IN D /\ z IN D /\ E u B /\ E v B /\
      einter D E u v z
      ==> emeet D E B inclB u v z`,
  REPEAT STRIP_TAC THEN
  FIRST_ASSUM(MP_TAC o SPEC `u:A` o CONJUNCT2 o REWRITE_RULE[eroset]) THEN
  ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  DISCH_THEN(fun th -> MP_TAC(EQ_MP th (ASSUME `(E:A->A->bool) u B`))) THEN
  DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "uP")
    (CONJUNCTS_THEN2 (LABEL_TAC "uo") (LABEL_TAC "ur"))) THEN
  FIRST_ASSUM(MP_TAC o SPEC `v:A` o CONJUNCT2 o REWRITE_RULE[eroset]) THEN
  ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  DISCH_THEN(fun th -> MP_TAC(EQ_MP th (ASSUME `(E:A->A->bool) v B`))) THEN
  DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "vP")
    (CONJUNCTS_THEN2 (LABEL_TAC "vo") (LABEL_TAC "vr"))) THEN
  MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`u:A`;`v:A`;`z:A`] EINTER_CHAR) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(fun th ->
    MP_TAC(EQ_MP th (ASSUME `einter D (E:A->A->bool) u v z`))) THEN
  DISCH_THEN(LABEL_TAC "ch") THEN
  SUBGOAL_THEN `esubset D (E:A->A->bool) z u` (LABEL_TAC "zu") THENL
   [REWRITE_TAC[esubset] THEN X_GEN_TAC `m:A` THEN STRIP_TAC THEN
    USE_THEN "ch" (MP_TAC o SPEC `m:A`) THEN
    ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN(fun th -> MP_TAC(EQ_MP th (ASSUME `(E:A->A->bool) m z`))) THEN
    DISCH_THEN(CONJUNCTS_THEN2 ACCEPT_TAC (K ALL_TAC));
    ALL_TAC] THEN
  SUBGOAL_THEN `esubset D (E:A->A->bool) z v` (LABEL_TAC "zv") THENL
   [REWRITE_TAC[esubset] THEN X_GEN_TAC `m:A` THEN STRIP_TAC THEN
    USE_THEN "ch" (MP_TAC o SPEC `m:A`) THEN
    ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN(fun th -> MP_TAC(EQ_MP th (ASSUME `(E:A->A->bool) m z`))) THEN
    DISCH_THEN(CONJUNCTS_THEN2 (K ALL_TAC) ACCEPT_TAC);
    ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) z B` (LABEL_TAC "zB") THENL
   [FIRST_ASSUM(MP_TAC o SPEC `z:A` o CONJUNCT2 o REWRITE_RULE[eroset]) THEN
    ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    REPEAT CONJ_TAC THENL
     [REWRITE_TAC[esubset] THEN X_GEN_TAC `m:A` THEN STRIP_TAC THEN
      USE_THEN "zu" (MP_TAC o SPEC `m:A` o REWRITE_RULE[esubset]) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN DISCH_TAC THEN
      USE_THEN "uP" (MP_TAC o SPEC `m:A` o REWRITE_RULE[esubset]) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC];
      MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`leqp:A`;`u:A`;`v:A`;`z:A`]
        EINTER_OPEN) THEN
      ANTS_TAC THENL
       [ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
         [USE_THEN "uo" ACCEPT_TAC; USE_THEN "vo" ACCEPT_TAC];
        DISCH_THEN ACCEPT_TAC];
      REWRITE_TAC[ereg] THEN X_GEN_TAC `p:A` THEN
      DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC
        (CONJUNCTS_THEN2 ASSUME_TAC (LABEL_TAC "dz"))) THEN
      SUBGOAL_THEN `(E:A->A->bool) p u` ASSUME_TAC THENL
       [USE_THEN "ur" (MP_TAC o SPEC `p:A` o REWRITE_RULE[ereg]) THEN
        ANTS_TAC THENL
         [ASM_REWRITE_TAC[] THEN X_GEN_TAC `q:A` THEN STRIP_TAC THEN
          USE_THEN "dz" (MP_TAC o SPEC `q:A`) THEN
          ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
          DISCH_THEN(X_CHOOSE_THEN `r:A` STRIP_ASSUME_TAC) THEN
          EXISTS_TAC `r:A` THEN ASM_REWRITE_TAC[] THEN
          USE_THEN "zu" (MP_TAC o SPEC `r:A` o REWRITE_RULE[esubset]) THEN
          ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC];
          DISCH_THEN ACCEPT_TAC];
        ALL_TAC] THEN
      SUBGOAL_THEN `(E:A->A->bool) p v` ASSUME_TAC THENL
       [USE_THEN "vr" (MP_TAC o SPEC `p:A` o REWRITE_RULE[ereg]) THEN
        ANTS_TAC THENL
         [ASM_REWRITE_TAC[] THEN X_GEN_TAC `q:A` THEN STRIP_TAC THEN
          USE_THEN "dz" (MP_TAC o SPEC `q:A`) THEN
          ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
          DISCH_THEN(X_CHOOSE_THEN `r:A` STRIP_ASSUME_TAC) THEN
          EXISTS_TAC `r:A` THEN ASM_REWRITE_TAC[] THEN
          USE_THEN "zv" (MP_TAC o SPEC `r:A` o REWRITE_RULE[esubset]) THEN
          ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC];
          DISCH_THEN ACCEPT_TAC];
        ALL_TAC] THEN
      USE_THEN "ch" (MP_TAC o SPEC `p:A`) THEN
      ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
      CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC];
    ALL_TAC] THEN
  REWRITE_TAC[emeet] THEN ASM_REWRITE_TAC[] THEN
  REPEAT CONJ_TAC THENL
   [MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`inclB:A`;`z:A`;`u:A`]
      EINCL_EREL_INTRO) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[] THEN USE_THEN "zu" ACCEPT_TAC;
      DISCH_THEN ACCEPT_TAC];
    MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`inclB:A`;`z:A`;`v:A`]
      EINCL_EREL_INTRO) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[] THEN USE_THEN "zv" ACCEPT_TAC;
      DISCH_THEN ACCEPT_TAC];
    X_GEN_TAC `w:A` THEN STRIP_TAC THEN
    MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`inclB:A`;`w:A`;`u:A`]
      EINCL_EREL) THEN
    ASM_REWRITE_TAC[] THEN STRIP_TAC THEN
    MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`inclB:A`;`w:A`;`v:A`]
      EINCL_EREL) THEN
    ASM_REWRITE_TAC[] THEN STRIP_TAC THEN
    MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`inclB:A`;`w:A`;`z:A`]
      EINCL_EREL_INTRO) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[] THEN REWRITE_TAC[esubset] THEN
      X_GEN_TAC `m:A` THEN STRIP_TAC THEN
      USE_THEN "ch" (MP_TAC o SPEC `m:A`) THEN
      ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
      CONJ_TAC THENL
       [UNDISCH_TAC `esubset D (E:A->A->bool) w u` THEN
        REWRITE_TAC[esubset] THEN
        DISCH_THEN MATCH_MP_TAC THEN ASM_REWRITE_TAC[];
        UNDISCH_TAC `esubset D (E:A->A->bool) w v` THEN
        REWRITE_TAC[esubset] THEN
        DISCH_THEN MATCH_MP_TAC THEN ASM_REWRITE_TAC[]];
      DISCH_THEN ACCEPT_TAC]]);;

let ecomplro = new_definition
  `ecomplro D (E:A->A->bool) P leqp u c <=>
     c IN D /\
     !p. p IN D
         ==> (E p c <=>
              E p P /\
              !q. q IN D /\ erel D E leqp q p ==> ~E q u)`;;

let COMPL_DENSE_HOLDS = prove
 (`!D (E:A->A->bool) v.
      model D E ZF_AX /\ valuation D v
      ==> (holds D E v (!! 4 (rel_form 2 4 3 --> Not (4 %% 0))) <=>
           !q. q IN D /\ erel D E (v 2) q (v 3) ==> ~E q (v 0))`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[HOLDS_ALL] THEN
  SUBGOAL_THEN
   `!q:A. q IN D
      ==> (holds D E ((4 |-> q) v) (rel_form 2 4 3 --> Not (4 %% 0)) <=>
           (erel D E (v 2) q (v 3) ==> ~E q (v 0)))`
   (LABEL_TAC "body") THENL
   [REPEAT STRIP_TAC THEN
    SUBGOAL_THEN `valuation D ((4 |-> (q:A)) v)` ASSUME_TAC THENL
     [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
    REWRITE_TAC[HOLDS_IMP; HOLDS_NOT; HOLDS_MEM] THEN
    MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`(4 |-> (q:A)) v`;`2`;`4`;`3`]
      HOLDS_REL_FORM) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    REWRITE_TAC[VALMOD; ARITH_EQ];
    ALL_TAC] THEN
  EQ_TAC THENL
   [DISCH_THEN(LABEL_TAC "lhs") THEN
    X_GEN_TAC `q:A` THEN STRIP_TAC THEN
    USE_THEN "lhs" (MP_TAC o SPEC `q:A`) THEN
    ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    USE_THEN "body" (MP_TAC o SPEC `q:A`) THEN
    ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    DISCH_THEN MATCH_MP_TAC THEN FIRST_ASSUM ACCEPT_TAC;
    DISCH_THEN(LABEL_TAC "sem") THEN
    X_GEN_TAC `q:A` THEN DISCH_TAC THEN
    USE_THEN "body" (MP_TAC o SPEC `q:A`) THEN
    ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    DISCH_TAC THEN
    USE_THEN "sem" (MP_TAC o SPEC `q:A`) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC]]);;

let ECOMPLRO_EXISTS = prove
 (`!D (E:A->A->bool) P leqp u.
      model D E ZF_AX /\ P IN D /\ leqp IN D /\ u IN D
      ==> ?c. ecomplro D E P leqp u c`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `valuation D ((0 |-> (u:A)) ((2 |-> (leqp:A)) (\n:num. P:A)))`
   (LABEL_TAC "val") THENL
   [MATCH_MP_TAC VALUATION_VALMOD THEN CONJ_TAC THENL
     [MATCH_MP_TAC VALUATION_VALMOD THEN CONJ_TAC THENL
       [REWRITE_TAC[valuation] THEN FIRST_ASSUM ACCEPT_TAC;
        FIRST_ASSUM ACCEPT_TAC];
      FIRST_ASSUM ACCEPT_TAC];
    ALL_TAC] THEN
  MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`] ZF_SEPARATION) THEN
  ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  DISCH_THEN(MP_TAC o ISPECL
    [`!! 4 (rel_form 2 4 3 --> Not (4 %% 0))`; `3`;
     `(0 |-> (u:A)) ((2 |-> (leqp:A)) (\n:num. P:A))`; `P:A`]) THEN
  ANTS_TAC THENL
   [CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
    DISCH_THEN(X_CHOOSE_THEN `c:A`
      (CONJUNCTS_THEN2 ASSUME_TAC (LABEL_TAC "sep")))] THEN
  EXISTS_TAC `c:A` THEN REWRITE_TAC[ecomplro] THEN
  CONJ_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  X_GEN_TAC `p:A` THEN DISCH_TAC THEN
  USE_THEN "sep" (MP_TAC o SPEC `p:A`) THEN
  ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  DISCH_THEN SUBST1_TAC THEN
  SUBGOAL_THEN
   `valuation D
    ((3 |-> (p:A)) ((0 |-> (u:A)) ((2 |-> (leqp:A)) (\n:num. P:A))))`
   ASSUME_TAC THENL
   [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;
    `(3 |-> (p:A)) ((0 |-> (u:A)) ((2 |-> (leqp:A)) (\n:num. P:A)))`]
    COMPL_DENSE_HOLDS) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  REWRITE_TAC[VALMOD; ARITH_EQ] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]));;

let ECOMPLRO_RO = prove
 (`!D (E:A->A->bool) P leqp u c B.
      model D E ZF_AX /\ eleqp D E P leqp /\ eroset D E P leqp B /\
      u IN D /\ eopen D E leqp u /\ ecomplro D E P leqp u c
      ==> E c B`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `(c:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[ecomplro]; ALL_TAC] THEN
  FIRST_ASSUM(MP_TAC o SPEC `c:A` o CONJUNCT2 o REWRITE_RULE[eroset]) THEN
  ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  REPEAT CONJ_TAC THENL
   [REWRITE_TAC[esubset] THEN X_GEN_TAC `m:A` THEN STRIP_TAC THEN
    FIRST_ASSUM(MP_TAC o SPEC `m:A` o CONJUNCT2 o REWRITE_RULE[ecomplro]) THEN
    ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN(fun th -> MP_TAC(EQ_MP th (ASSUME `(E:A->A->bool) m c`))) THEN
    DISCH_THEN(CONJUNCTS_THEN2 ACCEPT_TAC (K ALL_TAC));
    (* eopen c *)
    REWRITE_TAC[eopen] THEN
    MAP_EVERY X_GEN_TAC [`p:A`;`q:A`] THEN STRIP_TAC THEN
    FIRST_ASSUM(MP_TAC o SPEC `p:A` o CONJUNCT2 o REWRITE_RULE[ecomplro]) THEN
    ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN(fun th -> MP_TAC(EQ_MP th (ASSUME `(E:A->A->bool) p c`))) THEN
    DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "pP") (LABEL_TAC "avoid")) THEN
    FIRST_ASSUM(MP_TAC o SPEC `q:A` o CONJUNCT2 o REWRITE_RULE[ecomplro]) THEN
    ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    CONJ_TAC THENL
     [MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`P:A`;`leqp:A`;`q:A`;`p:A`]
        ELEQP_EREL) THEN
      ASM_REWRITE_TAC[] THEN DISCH_THEN(ACCEPT_TAC o CONJUNCT1);
      X_GEN_TAC `q':A` THEN STRIP_TAC THEN
      USE_THEN "avoid" (MP_TAC o SPEC `q':A`) THEN
      ANTS_TAC THENL
       [CONJ_TAC THENL
         [FIRST_ASSUM ACCEPT_TAC;
          MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`P:A`;`leqp:A`;
            `q':A`;`q:A`;`p:A`] LEQP_TRANS_E) THEN
          ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC]];
        DISCH_THEN ACCEPT_TAC]];
    (* ereg c *)
    REWRITE_TAC[ereg] THEN X_GEN_TAC `p:A` THEN
    DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC
      (CONJUNCTS_THEN2 ASSUME_TAC (LABEL_TAC "dc"))) THEN
    FIRST_ASSUM(MP_TAC o SPEC `p:A` o CONJUNCT2 o REWRITE_RULE[ecomplro]) THEN
    ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    ASM_REWRITE_TAC[] THEN
    X_GEN_TAC `q:A` THEN STRIP_TAC THEN
    USE_THEN "dc" (MP_TAC o SPEC `q:A`) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(X_CHOOSE_THEN `r:A` STRIP_ASSUME_TAC) THEN
    SUBGOAL_THEN `(E:A->A->bool) r P` ASSUME_TAC THENL
     [MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`P:A`;`leqp:A`;`r:A`;`q:A`]
        ELEQP_EREL) THEN
      ASM_REWRITE_TAC[] THEN DISCH_THEN(ACCEPT_TAC o CONJUNCT1);
      ALL_TAC] THEN
    SUBGOAL_THEN `~((E:A->A->bool) r u)` ASSUME_TAC THENL
     [FIRST_ASSUM(MP_TAC o SPEC `r:A` o CONJUNCT2 o
                  REWRITE_RULE[ecomplro]) THEN
      ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
      DISCH_THEN(fun th -> MP_TAC(EQ_MP th (ASSUME `(E:A->A->bool) r c`))) THEN
      DISCH_THEN(CONJUNCTS_THEN2 (K ALL_TAC) (MP_TAC o SPEC `r:A`)) THEN
      ANTS_TAC THENL
       [CONJ_TAC THENL
         [FIRST_ASSUM ACCEPT_TAC;
          MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`P:A`;`leqp:A`;`r:A`]
            LEQP_REFL_E) THEN
          ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC]];
        DISCH_THEN ACCEPT_TAC];
      ALL_TAC] THEN
    UNDISCH_TAC `eopen D (E:A->A->bool) leqp u` THEN REWRITE_TAC[eopen] THEN
    DISCH_THEN(MP_TAC o SPECL [`q:A`;`r:A`]) THEN
    ASM_MESON_TAC[]]);;

(* ==================================================================== *)
(* F2.6c  Join = intcl of union on the RO algebra; complement laws       *)
(* (meet with complement = bot, join with complement = top -- the        *)
(* latter is the density/excluded-middle argument); ecompl assembly.     *)
(* ==================================================================== *)

let EJOIN_ROSET = prove
 (`!D (E:A->A->bool) P leqp B inclB u v w j.
      model D E ZF_AX /\ eleqp D E P leqp /\ eroset D E P leqp B /\
      eincl D E B inclB /\
      u IN D /\ v IN D /\ w IN D /\ j IN D /\ E u B /\ E v B /\
      ebunion D E u v w /\ eintcl D E P leqp w j
      ==> ejoin D E B inclB u v j`,
  REPEAT STRIP_TAC THEN
  FIRST_ASSUM(MP_TAC o SPEC `u:A` o CONJUNCT2 o REWRITE_RULE[eroset]) THEN
  ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  DISCH_THEN(fun th -> MP_TAC(EQ_MP th (ASSUME `(E:A->A->bool) u B`))) THEN
  DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "uP")
    (CONJUNCTS_THEN2 (LABEL_TAC "uo") (LABEL_TAC "ur"))) THEN
  FIRST_ASSUM(MP_TAC o SPEC `v:A` o CONJUNCT2 o REWRITE_RULE[eroset]) THEN
  ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  DISCH_THEN(fun th -> MP_TAC(EQ_MP th (ASSUME `(E:A->A->bool) v B`))) THEN
  DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "vP")
    (CONJUNCTS_THEN2 (LABEL_TAC "vo") (LABEL_TAC "vr"))) THEN
  MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`u:A`;`v:A`;`w:A`]
         EBUNION_CHAR) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(fun th ->
    MP_TAC(EQ_MP th (ASSUME `ebunion D (E:A->A->bool) u v w`))) THEN
  DISCH_THEN(LABEL_TAC "ch") THEN
  SUBGOAL_THEN `esubset D (E:A->A->bool) w P` (LABEL_TAC "wP") THENL
   [REWRITE_TAC[esubset] THEN X_GEN_TAC `m:A` THEN STRIP_TAC THEN
    SUBGOAL_THEN `(E:A->A->bool) m u \/ (E:A->A->bool) m v` MP_TAC THENL
     [USE_THEN "ch" (MP_TAC o SPEC `m:A`) THEN
      ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[GSYM th]) THEN FIRST_ASSUM ACCEPT_TAC;
      ALL_TAC] THEN
    STRIP_TAC THENL
     [USE_THEN "uP" (MP_TAC o SPEC `m:A` o REWRITE_RULE[esubset]) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC];
      USE_THEN "vP" (MP_TAC o SPEC `m:A` o REWRITE_RULE[esubset]) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC]];
    ALL_TAC] THEN
  SUBGOAL_THEN `eopen D (E:A->A->bool) leqp w` (LABEL_TAC "wo") THENL
   [MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`leqp:A`;`u:A`;`v:A`;`w:A`]
      EBUNION_OPEN) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
       [USE_THEN "uo" ACCEPT_TAC; USE_THEN "vo" ACCEPT_TAC];
      DISCH_THEN ACCEPT_TAC];
    ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) j B` (LABEL_TAC "jB") THENL
   [MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`P:A`;`leqp:A`;`w:A`;`j:A`;`B:A`]
      EINTCL_RO) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC];
    ALL_TAC] THEN
  SUBGOAL_THEN `esubset D (E:A->A->bool) w j` (LABEL_TAC "wj") THENL
   [MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`P:A`;`leqp:A`;`w:A`;`j:A`]
      EINTCL_EXPAND) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
       [USE_THEN "wP" ACCEPT_TAC; USE_THEN "wo" ACCEPT_TAC];
      DISCH_THEN ACCEPT_TAC];
    ALL_TAC] THEN
  REWRITE_TAC[ejoin] THEN ASM_REWRITE_TAC[] THEN
  REPEAT CONJ_TAC THENL
   [(* erel u j *)
    MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`inclB:A`;`u:A`;`j:A`]
      EINCL_EREL_INTRO) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[] THEN REWRITE_TAC[esubset] THEN
      X_GEN_TAC `m:A` THEN STRIP_TAC THEN
      USE_THEN "wj" (MP_TAC o SPEC `m:A` o REWRITE_RULE[esubset]) THEN
      ANTS_TAC THENL
       [ASM_REWRITE_TAC[] THEN
        USE_THEN "ch" (MP_TAC o SPEC `m:A`) THEN
        ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
        DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN DISJ1_TAC THEN
        FIRST_ASSUM ACCEPT_TAC;
        DISCH_THEN ACCEPT_TAC];
      DISCH_THEN ACCEPT_TAC];
    (* erel v j *)
    MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`inclB:A`;`v:A`;`j:A`]
      EINCL_EREL_INTRO) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[] THEN REWRITE_TAC[esubset] THEN
      X_GEN_TAC `m:A` THEN STRIP_TAC THEN
      USE_THEN "wj" (MP_TAC o SPEC `m:A` o REWRITE_RULE[esubset]) THEN
      ANTS_TAC THENL
       [ASM_REWRITE_TAC[] THEN
        USE_THEN "ch" (MP_TAC o SPEC `m:A`) THEN
        ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
        DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN DISJ2_TAC THEN
        FIRST_ASSUM ACCEPT_TAC;
        DISCH_THEN ACCEPT_TAC];
      DISCH_THEN ACCEPT_TAC];
    (* least upper bound *)
    X_GEN_TAC `x:A` THEN STRIP_TAC THEN
    MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`inclB:A`;`u:A`;`x:A`]
      EINCL_EREL) THEN
    ASM_REWRITE_TAC[] THEN STRIP_TAC THEN
    MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`inclB:A`;`v:A`;`x:A`]
      EINCL_EREL) THEN
    ASM_REWRITE_TAC[] THEN STRIP_TAC THEN
    SUBGOAL_THEN `ereg D (E:A->A->bool) P leqp x` ASSUME_TAC THENL
     [FIRST_ASSUM(MP_TAC o SPEC `x:A` o CONJUNCT2 o REWRITE_RULE[eroset]) THEN
      ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
      DISCH_THEN(fun th -> MP_TAC(EQ_MP th (ASSUME `(E:A->A->bool) x B`))) THEN
      STRIP_TAC THEN FIRST_ASSUM ACCEPT_TAC;
      ALL_TAC] THEN
    MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`inclB:A`;`j:A`;`x:A`]
      EINCL_EREL_INTRO) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[] THEN
      MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`P:A`;`leqp:A`;`w:A`;
                    `j:A`;`x:A`]
             EINTCL_MIN) THEN
      ANTS_TAC THENL
       [ASM_REWRITE_TAC[] THEN REWRITE_TAC[esubset] THEN
        X_GEN_TAC `m:A` THEN STRIP_TAC THEN
        SUBGOAL_THEN `(E:A->A->bool) m u \/ (E:A->A->bool) m v` MP_TAC THENL
         [USE_THEN "ch" (MP_TAC o SPEC `m:A`) THEN
          ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
          DISCH_THEN(fun th -> REWRITE_TAC[GSYM th]) THEN
          FIRST_ASSUM ACCEPT_TAC;
          ALL_TAC] THEN
        STRIP_TAC THENL
         [UNDISCH_TAC `esubset D (E:A->A->bool) u x` THEN
          REWRITE_TAC[esubset] THEN
          DISCH_THEN MATCH_MP_TAC THEN ASM_REWRITE_TAC[];
          UNDISCH_TAC `esubset D (E:A->A->bool) v x` THEN
          REWRITE_TAC[esubset] THEN
          DISCH_THEN MATCH_MP_TAC THEN ASM_REWRITE_TAC[]];
        DISCH_THEN ACCEPT_TAC];
      DISCH_THEN ACCEPT_TAC]]);;

let EMEET_COMPL_BOT = prove
 (`!D (E:A->A->bool) P leqp B inclB u c z.
      model D E ZF_AX /\ eleqp D E P leqp /\ eroset D E P leqp B /\
      eincl D E B inclB /\
      u IN D /\ c IN D /\ z IN D /\ E u B /\ E c B /\
      ecomplro D E P leqp u c /\ eempty D E z
      ==> emeet D E B inclB u c z`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `(E:A->A->bool) z B` (LABEL_TAC "zB") THENL
   [MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`P:A`;`leqp:A`;`B:A`;`z:A`]
      EROSET_BOT) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC];
    ALL_TAC] THEN
  REWRITE_TAC[emeet] THEN ASM_REWRITE_TAC[] THEN
  REPEAT CONJ_TAC THENL
   [MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`inclB:A`;`z:A`;`u:A`]
      EINCL_EREL_INTRO) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[] THEN MATCH_MP_TAC EEMPTY_SUBSET THEN
      FIRST_ASSUM ACCEPT_TAC;
      DISCH_THEN ACCEPT_TAC];
    MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`inclB:A`;`z:A`;`c:A`]
      EINCL_EREL_INTRO) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[] THEN MATCH_MP_TAC EEMPTY_SUBSET THEN
      FIRST_ASSUM ACCEPT_TAC;
      DISCH_THEN ACCEPT_TAC];
    X_GEN_TAC `w:A` THEN STRIP_TAC THEN
    MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`inclB:A`;`w:A`;`u:A`]
      EINCL_EREL) THEN
    ASM_REWRITE_TAC[] THEN STRIP_TAC THEN
    MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`inclB:A`;`w:A`;`c:A`]
      EINCL_EREL) THEN
    ASM_REWRITE_TAC[] THEN STRIP_TAC THEN
    MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`inclB:A`;`w:A`;`z:A`]
      EINCL_EREL_INTRO) THEN
    ANTS_TAC THENL [ALL_TAC; DISCH_THEN ACCEPT_TAC] THEN
    ASM_REWRITE_TAC[] THEN REWRITE_TAC[esubset] THEN
    X_GEN_TAC `m:A` THEN STRIP_TAC THEN
    SUBGOAL_THEN `(E:A->A->bool) m u` ASSUME_TAC THENL
     [UNDISCH_TAC `esubset D (E:A->A->bool) w u` THEN REWRITE_TAC[esubset] THEN
      DISCH_THEN MATCH_MP_TAC THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN `(E:A->A->bool) m c` ASSUME_TAC THENL
     [UNDISCH_TAC `esubset D (E:A->A->bool) w c` THEN REWRITE_TAC[esubset] THEN
      DISCH_THEN MATCH_MP_TAC THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    FIRST_ASSUM(MP_TAC o SPEC `m:A` o CONJUNCT2 o REWRITE_RULE[ecomplro]) THEN
    ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN(fun th -> MP_TAC(EQ_MP th (ASSUME `(E:A->A->bool) m c`))) THEN
    DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC (MP_TAC o SPEC `m:A`)) THEN
    ANTS_TAC THENL
     [CONJ_TAC THENL
       [FIRST_ASSUM ACCEPT_TAC;
        MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`P:A`;`leqp:A`;`m:A`]
          LEQP_REFL_E) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC]];
      ALL_TAC] THEN
    ASM_MESON_TAC[]]);;

let EJOIN_COMPL_TOP = prove
 (`!D (E:A->A->bool) P leqp B inclB u c.
      model D E ZF_AX /\ P IN D /\ eleqp D E P leqp /\
      eroset D E P leqp B /\ eincl D E B inclB /\
      u IN D /\ c IN D /\ E u B /\ E c B /\
      ecomplro D E P leqp u c
