   [MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`P:A`;`leqp:A`;`B:A`]
      EROSET_TOP) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC];
    ALL_TAC] THEN
  SUBGOAL_THEN `esubset D (E:A->A->bool) u P` (LABEL_TAC "uP") THENL
   [FIRST_ASSUM(MP_TAC o SPEC `u:A` o CONJUNCT2 o REWRITE_RULE[eroset]) THEN
    ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN(fun th -> MP_TAC(EQ_MP th (ASSUME `(E:A->A->bool) u B`))) THEN
    STRIP_TAC THEN FIRST_ASSUM ACCEPT_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN `esubset D (E:A->A->bool) c P` (LABEL_TAC "cP") THENL
   [REWRITE_TAC[esubset] THEN X_GEN_TAC `m:A` THEN STRIP_TAC THEN
    FIRST_ASSUM(MP_TAC o SPEC `m:A` o CONJUNCT2 o REWRITE_RULE[ecomplro]) THEN
    ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN(fun th -> MP_TAC(EQ_MP th (ASSUME `(E:A->A->bool) m c`))) THEN
    DISCH_THEN(CONJUNCTS_THEN2 ACCEPT_TAC (K ALL_TAC));
    ALL_TAC] THEN
  REWRITE_TAC[ejoin] THEN ASM_REWRITE_TAC[] THEN
  REPEAT CONJ_TAC THENL
   [MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`inclB:A`;`u:A`;`P:A`]
      EINCL_EREL_INTRO) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[] THEN USE_THEN "uP" ACCEPT_TAC;
      DISCH_THEN ACCEPT_TAC];
    MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`inclB:A`;`c:A`;`P:A`]
      EINCL_EREL_INTRO) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[] THEN USE_THEN "cP" ACCEPT_TAC;
      DISCH_THEN ACCEPT_TAC];
    X_GEN_TAC `x:A` THEN STRIP_TAC THEN
    MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`inclB:A`;`u:A`;`x:A`]
      EINCL_EREL) THEN
    ASM_REWRITE_TAC[] THEN STRIP_TAC THEN
    MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`inclB:A`;`c:A`;`x:A`]
      EINCL_EREL) THEN
    ASM_REWRITE_TAC[] THEN STRIP_TAC THEN
    SUBGOAL_THEN `ereg D (E:A->A->bool) P leqp x` (LABEL_TAC "xr") THENL
     [FIRST_ASSUM(MP_TAC o SPEC `x:A` o CONJUNCT2 o REWRITE_RULE[eroset]) THEN
      ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
      DISCH_THEN(fun th -> MP_TAC(EQ_MP th (ASSUME `(E:A->A->bool) x B`))) THEN
      STRIP_TAC THEN FIRST_ASSUM ACCEPT_TAC;
      ALL_TAC] THEN
    MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`inclB:A`;`P:A`;`x:A`]
      EINCL_EREL_INTRO) THEN
    ANTS_TAC THENL [ALL_TAC; DISCH_THEN ACCEPT_TAC] THEN
    ASM_REWRITE_TAC[] THEN REWRITE_TAC[esubset] THEN
    X_GEN_TAC `p:A` THEN STRIP_TAC THEN
    USE_THEN "xr" (MP_TAC o SPEC `p:A` o REWRITE_RULE[ereg]) THEN
    ANTS_TAC THENL [ALL_TAC; DISCH_THEN ACCEPT_TAC] THEN
    ASM_REWRITE_TAC[] THEN
    X_GEN_TAC `q:A` THEN STRIP_TAC THEN
    SUBGOAL_THEN `(E:A->A->bool) q P` ASSUME_TAC THENL
     [MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`P:A`;`leqp:A`;`q:A`;`p:A`]
        ELEQP_EREL) THEN
      ASM_REWRITE_TAC[] THEN DISCH_THEN(ACCEPT_TAC o CONJUNCT1);
      ALL_TAC] THEN
    ASM_CASES_TAC `?r:A. r IN D /\ erel D E leqp r q /\ E r u` THENL
     [FIRST_X_ASSUM(X_CHOOSE_THEN `r:A` STRIP_ASSUME_TAC) THEN
      EXISTS_TAC `r:A` THEN ASM_REWRITE_TAC[] THEN
      UNDISCH_TAC `esubset D (E:A->A->bool) u x` THEN REWRITE_TAC[esubset] THEN
      DISCH_THEN MATCH_MP_TAC THEN ASM_REWRITE_TAC[];
      SUBGOAL_THEN `(E:A->A->bool) q c` ASSUME_TAC THENL
       [FIRST_ASSUM(MP_TAC o SPEC `q:A` o CONJUNCT2 o
          REWRITE_RULE[ecomplro]) THEN
        ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
        DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
        ASM_REWRITE_TAC[] THEN
        X_GEN_TAC `s:A` THEN STRIP_TAC THEN ASM_MESON_TAC[];
        ALL_TAC] THEN
      EXISTS_TAC `q:A` THEN ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
       [MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`P:A`;`leqp:A`;`q:A`]
          LEQP_REFL_E) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC];
        UNDISCH_TAC `esubset D (E:A->A->bool) c x` THEN
        REWRITE_TAC[esubset] THEN
        DISCH_THEN MATCH_MP_TAC THEN ASM_REWRITE_TAC[]]]]);;

let ECOMPL_ROSET = prove
 (`!D (E:A->A->bool) P leqp B inclB u.
      model D E ZF_AX /\ P IN D /\ leqp IN D /\ eleqp D E P leqp /\
      eroset D E P leqp B /\ eincl D E B inclB /\
      u IN D /\ E u B
      ==> ?y. ecompl D E B inclB u y`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `eopen D (E:A->A->bool) leqp u` ASSUME_TAC THENL
   [FIRST_ASSUM(MP_TAC o SPEC `u:A` o CONJUNCT2 o REWRITE_RULE[eroset]) THEN
    ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN(fun th -> MP_TAC(EQ_MP th (ASSUME `(E:A->A->bool) u B`))) THEN
    STRIP_TAC THEN FIRST_ASSUM ACCEPT_TAC;
    ALL_TAC] THEN
  MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`P:A`;`leqp:A`;`u:A`]
    ECOMPLRO_EXISTS) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_TAC `c:A`) THEN
  SUBGOAL_THEN `(c:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[ecomplro]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) c B` ASSUME_TAC THENL
   [MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`P:A`;`leqp:A`;`u:A`;`c:A`;`B:A`]
      ECOMPLRO_RO) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC];
    ALL_TAC] THEN
  MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`] EEMPTY_EXISTS) THEN
  ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_TAC `z:A`) THEN
  SUBGOAL_THEN `(z:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[eempty]; ALL_TAC] THEN
  EXISTS_TAC `c:A` THEN REWRITE_TAC[ecompl] THEN
  ASM_REWRITE_TAC[] THEN
  MAP_EVERY EXISTS_TAC [`z:A`;`P:A`] THEN
  REPEAT CONJ_TAC THENL
   [MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`P:A`;`leqp:A`;`B:A`;`inclB:A`;
      `z:A`] EBOT_ROSET) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC];
    MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`P:A`;`leqp:A`;`B:A`;`inclB:A`]
      ETOP_ROSET) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC];
    MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`P:A`;`leqp:A`;`B:A`;`inclB:A`;
      `u:A`;`c:A`;`z:A`] EMEET_COMPL_BOT) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC];
    MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`P:A`;`leqp:A`;`B:A`;`inclB:A`;
      `u:A`;`c:A`] EJOIN_COMPL_TOP) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC]]);;

(* ==================================================================== *)
(* F2.6d  RO distributivity as a SET equality:                           *)
(*   x /\ intcl(y U w)  =  intcl((x /\ y) U (x /\ w))                    *)
(* Both sides have the same members: p in P with the set                 *)
(*   { r : r in x /\ (r in y \/ r in w) }  dense below p.                *)
(* LHS->middle uses x OPEN (pull r's into x); middle->LHS uses x REGULAR *)
(* (dense x-elements force p in x).  RHS = middle literally by chars.    *)
(* ==================================================================== *)

let RO_DISTRIB_EQ = prove
 (`!D (E:A->A->bool) P leqp B x y w uw j b c d cd e.
      model D E ZF_AX /\ eleqp D E P leqp /\ eroset D E P leqp B /\
      x IN D /\ y IN D /\ w IN D /\ uw IN D /\ j IN D /\ b IN D /\
      c IN D /\ d IN D /\ cd IN D /\ e IN D /\
      E x B /\ E y B /\ E w B /\
      ebunion D E y w uw /\ eintcl D E P leqp uw j /\ einter D E x j b /\
      einter D E x y c /\ einter D E x w d /\
      ebunion D E c d cd /\ eintcl D E P leqp cd e
      ==> b = e`,
  REPEAT STRIP_TAC THEN
  FIRST_ASSUM(MP_TAC o SPEC `x:A` o CONJUNCT2 o REWRITE_RULE[eroset]) THEN
  ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  DISCH_THEN(fun th -> MP_TAC(EQ_MP th (ASSUME `(E:A->A->bool) x B`))) THEN
  DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "xP")
    (CONJUNCTS_THEN2 (LABEL_TAC "xo") (LABEL_TAC "xr"))) THEN
  MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`y:A`;`w:A`;`uw:A`]
         EBUNION_CHAR) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(fun th ->
    MP_TAC(EQ_MP th (ASSUME `ebunion D (E:A->A->bool) y w uw`))) THEN
  DISCH_THEN(LABEL_TAC "chuw") THEN
  MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`x:A`;`j:A`;`b:A`] EINTER_CHAR) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(fun th ->
    MP_TAC(EQ_MP th (ASSUME `einter D (E:A->A->bool) x j b`))) THEN
  DISCH_THEN(LABEL_TAC "chb") THEN
  MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`x:A`;`y:A`;`c:A`] EINTER_CHAR) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(fun th ->
    MP_TAC(EQ_MP th (ASSUME `einter D (E:A->A->bool) x y c`))) THEN
  DISCH_THEN(LABEL_TAC "chc") THEN
  MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`x:A`;`w:A`;`d:A`] EINTER_CHAR) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(fun th ->
    MP_TAC(EQ_MP th (ASSUME `einter D (E:A->A->bool) x w d`))) THEN
  DISCH_THEN(LABEL_TAC "chd") THEN
  MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`c:A`;`d:A`;`cd:A`]
         EBUNION_CHAR) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(fun th ->
    MP_TAC(EQ_MP th (ASSUME `ebunion D (E:A->A->bool) c d cd`))) THEN
  DISCH_THEN(LABEL_TAC "chcd") THEN
  MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`] ZF_EXTENSIONALITY) THEN
  ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  DISCH_THEN MATCH_MP_TAC THEN
  ASM_REWRITE_TAC[] THEN
  X_GEN_TAC `m:A` THEN DISCH_TAC THEN
  USE_THEN "chb" (MP_TAC o SPEC `m:A`) THEN
  ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  UNDISCH_TAC `eintcl D (E:A->A->bool) P leqp uw j` THEN
  REWRITE_TAC[eintcl] THEN
  DISCH_THEN(CONJUNCTS_THEN2 (K ALL_TAC) (MP_TAC o SPEC `m:A`)) THEN
  ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  UNDISCH_TAC `eintcl D (E:A->A->bool) P leqp cd e` THEN
  REWRITE_TAC[eintcl] THEN
  DISCH_THEN(CONJUNCTS_THEN2 (K ALL_TAC) (MP_TAC o SPEC `m:A`)) THEN
  ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  EQ_TAC THENL
   [DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "mx")
      (CONJUNCTS_THEN2 (LABEL_TAC "mP") (LABEL_TAC "duw"))) THEN
    ASM_REWRITE_TAC[] THEN
    X_GEN_TAC `q:A` THEN STRIP_TAC THEN
    USE_THEN "duw" (MP_TAC o SPEC `q:A`) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(X_CHOOSE_THEN `r:A` STRIP_ASSUME_TAC) THEN
    SUBGOAL_THEN `erel D (E:A->A->bool) leqp r m` ASSUME_TAC THENL
     [MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`P:A`;`leqp:A`;
        `r:A`;`q:A`;`m:A`] LEQP_TRANS_E) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC];
      ALL_TAC] THEN
    SUBGOAL_THEN `(E:A->A->bool) r x` ASSUME_TAC THENL
     [USE_THEN "xo" (MP_TAC o SPECL [`m:A`;`r:A`] o REWRITE_RULE[eopen]) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC];
      ALL_TAC] THEN
    EXISTS_TAC `r:A` THEN ASM_REWRITE_TAC[] THEN
    USE_THEN "chcd" (MP_TAC o SPEC `r:A`) THEN
    ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    SUBGOAL_THEN `(E:A->A->bool) r y \/ (E:A->A->bool) r w` MP_TAC THENL
     [USE_THEN "chuw" (MP_TAC o SPEC `r:A`) THEN
      ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[GSYM th]) THEN FIRST_ASSUM ACCEPT_TAC;
      ALL_TAC] THEN
    STRIP_TAC THENL
     [DISJ1_TAC THEN
      USE_THEN "chc" (MP_TAC o SPEC `r:A`) THEN
      ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
      CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
      DISJ2_TAC THEN
      USE_THEN "chd" (MP_TAC o SPEC `r:A`) THEN
      ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
      CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC];
    DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "mP") (LABEL_TAC "dcd")) THEN
    ASM_REWRITE_TAC[] THEN
    CONJ_TAC THENL
     [USE_THEN "xr" (MP_TAC o SPEC `m:A` o REWRITE_RULE[ereg]) THEN
      ANTS_TAC THENL [ALL_TAC; DISCH_THEN ACCEPT_TAC] THEN
      ASM_REWRITE_TAC[] THEN
      X_GEN_TAC `q:A` THEN STRIP_TAC THEN
      USE_THEN "dcd" (MP_TAC o SPEC `q:A`) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(X_CHOOSE_THEN `r:A` STRIP_ASSUME_TAC) THEN
      EXISTS_TAC `r:A` THEN ASM_REWRITE_TAC[] THEN
      SUBGOAL_THEN `(E:A->A->bool) r c \/ (E:A->A->bool) r d` MP_TAC THENL
       [USE_THEN "chcd" (MP_TAC o SPEC `r:A`) THEN
        ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
        DISCH_THEN(fun th -> REWRITE_TAC[GSYM th]) THEN
        FIRST_ASSUM ACCEPT_TAC;
        ALL_TAC] THEN
      STRIP_TAC THENL
       [USE_THEN "chc" (MP_TAC o SPEC `r:A`) THEN
        ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
        DISCH_THEN(fun th ->
          MP_TAC(EQ_MP th (ASSUME `(E:A->A->bool) r c`))) THEN
        DISCH_THEN(CONJUNCTS_THEN2 ACCEPT_TAC (K ALL_TAC));
        USE_THEN "chd" (MP_TAC o SPEC `r:A`) THEN
        ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
        DISCH_THEN(fun th ->
          MP_TAC(EQ_MP th (ASSUME `(E:A->A->bool) r d`))) THEN
        DISCH_THEN(CONJUNCTS_THEN2 ACCEPT_TAC (K ALL_TAC))];
      X_GEN_TAC `q:A` THEN STRIP_TAC THEN
      USE_THEN "dcd" (MP_TAC o SPEC `q:A`) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(X_CHOOSE_THEN `r:A` STRIP_ASSUME_TAC) THEN
      EXISTS_TAC `r:A` THEN ASM_REWRITE_TAC[] THEN
      USE_THEN "chuw" (MP_TAC o SPEC `r:A`) THEN
      ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
      SUBGOAL_THEN `(E:A->A->bool) r c \/ (E:A->A->bool) r d` MP_TAC THENL
       [USE_THEN "chcd" (MP_TAC o SPEC `r:A`) THEN
        ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
        DISCH_THEN(fun th -> REWRITE_TAC[GSYM th]) THEN
        FIRST_ASSUM ACCEPT_TAC;
        ALL_TAC] THEN
      STRIP_TAC THENL
       [DISJ1_TAC THEN
        USE_THEN "chc" (MP_TAC o SPEC `r:A`) THEN
        ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
        DISCH_THEN(fun th ->
          MP_TAC(EQ_MP th (ASSUME `(E:A->A->bool) r c`))) THEN
        DISCH_THEN(CONJUNCTS_THEN2 (K ALL_TAC) ACCEPT_TAC);
        DISJ2_TAC THEN
        USE_THEN "chd" (MP_TAC o SPEC `r:A`) THEN
        ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
        DISCH_THEN(fun th ->
          MP_TAC(EQ_MP th (ASSUME `(E:A->A->bool) r d`))) THEN
        DISCH_THEN(CONJUNCTS_THEN2 (K ALL_TAC) ACCEPT_TAC)]]]);;

(* ==================================================================== *)
(* F2.6e/F2.7  ASSEMBLIES: the RO carrier with the inclusion             *)
(* order is a complete Boolean algebra.                                  *)
(*   EBALG_ROSET: ebalg D E B inclB   (lattice via EMEET/EJOIN_ROSET;   *)
(*     distributivity by uniqueness transfer onto RO_DISTRIB_EQ;         *)
(*     complements via ECOMPL_ROSET).                                    *)
(*   ECBA_ROSET: ecba -- lub of an internal s SUBSET B is intcl(Un s).   *)
(* ==================================================================== *)

let EBALG_ROSET = prove
 (`!D (E:A->A->bool) P leqp B inclB.
      model D E ZF_AX /\
      P IN D /\ leqp IN D /\ eleqp D E P leqp /\
      eroset D E P leqp B /\ eincl D E B inclB
      ==> ebalg D E B inclB`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `(B:A) IN D` ASSUME_TAC THENL
   [FIRST_ASSUM(ACCEPT_TAC o CONJUNCT1 o GEN_REWRITE_RULE I [eroset]);
    ALL_TAC] THEN
  SUBGOAL_THEN `eporder D (E:A->A->bool) B inclB` (LABEL_TAC "epo") THENL
   [MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`inclB:A`]
           EPORDER_INCL) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!u v:A. u IN D /\ v IN D /\ E u B /\ E v B
            ==> ?z. z IN D /\ einter D E u v z /\ emeet D E B inclB u v z`
   (LABEL_TAC "mex") THENL
   [REPEAT STRIP_TAC THEN
    MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`u:A`;`v:A`] EINTER_EXISTS) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(X_CHOOSE_TAC `z:A`) THEN
    SUBGOAL_THEN `(z:A) IN D` ASSUME_TAC THENL
     [FIRST_ASSUM(ACCEPT_TAC o CONJUNCT1 o GEN_REWRITE_RULE I [einter]);
      ALL_TAC] THEN
    EXISTS_TAC `z:A` THEN ASM_REWRITE_TAC[] THEN
    MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`P:A`;`leqp:A`;`B:A`;`inclB:A`;
      `u:A`;`v:A`;`z:A`] EMEET_ROSET) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!u v:A. u IN D /\ v IN D /\ E u B /\ E v B
            ==> ?uv j. uv IN D /\ j IN D /\ ebunion D E u v uv /\
                       eintcl D E P leqp uv j /\ ejoin D E B inclB u v j`
   (LABEL_TAC "jex") THENL
   [REPEAT STRIP_TAC THEN
    MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`u:A`;`v:A`] EBUNION_EXISTS) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(X_CHOOSE_TAC `uv:A`) THEN
    SUBGOAL_THEN `(uv:A) IN D` ASSUME_TAC THENL
     [FIRST_ASSUM(ACCEPT_TAC o MATCH_MP EBUNION_IN); ALL_TAC] THEN
    MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`P:A`;`leqp:A`;`uv:A`]
      EINTCL_EXISTS) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(X_CHOOSE_TAC `j:A`) THEN
    SUBGOAL_THEN `(j:A) IN D` ASSUME_TAC THENL
     [FIRST_ASSUM(ACCEPT_TAC o CONJUNCT1 o GEN_REWRITE_RULE I [eintcl]);
      ALL_TAC] THEN
    MAP_EVERY EXISTS_TAC [`uv:A`;`j:A`] THEN ASM_REWRITE_TAC[] THEN
    MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`P:A`;`leqp:A`;`B:A`;`inclB:A`;
      `u:A`;`v:A`;`uv:A`;`j:A`] EJOIN_ROSET) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC];
    ALL_TAC] THEN
  REWRITE_TAC[ebalg] THEN REPEAT CONJ_TAC THENL
   [REWRITE_TAC[elattice] THEN REPEAT CONJ_TAC THENL
     [USE_THEN "epo" ACCEPT_TAC;
      MAP_EVERY X_GEN_TAC [`u:A`;`v:A`] THEN STRIP_TAC THEN
      USE_THEN "mex" (MP_TAC o SPECL [`u:A`;`v:A`]) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(X_CHOOSE_THEN `z:A` STRIP_ASSUME_TAC) THEN
      EXISTS_TAC `z:A` THEN FIRST_ASSUM ACCEPT_TAC;
      MAP_EVERY X_GEN_TAC [`u:A`;`v:A`] THEN STRIP_TAC THEN
      USE_THEN "jex" (MP_TAC o SPECL [`u:A`;`v:A`]) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(X_CHOOSE_THEN `uv:A` (X_CHOOSE_THEN `j:A`
        STRIP_ASSUME_TAC)) THEN
      EXISTS_TAC `j:A` THEN FIRST_ASSUM ACCEPT_TAC];
    MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`] EEMPTY_EXISTS) THEN
    ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN(X_CHOOSE_TAC `z:A`) THEN
    SUBGOAL_THEN `(z:A) IN D` ASSUME_TAC THENL
     [FIRST_ASSUM(ACCEPT_TAC o CONJUNCT1 o GEN_REWRITE_RULE I [eempty]);
      ALL_TAC] THEN
    EXISTS_TAC `z:A` THEN
    MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`P:A`;`leqp:A`;`B:A`;`inclB:A`;
      `z:A`] EBOT_ROSET) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC];
    EXISTS_TAC `P:A` THEN
    MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`P:A`;`leqp:A`;`B:A`;`inclB:A`]
      ETOP_ROSET) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC];
    MAP_EVERY X_GEN_TAC
      [`x:A`;`y:A`;`w:A`;`a:A`;`b:A`;`c:A`;`d:A`;`e:A`] THEN
    STRIP_TAC THEN
    USE_THEN "jex" (MP_TAC o SPECL [`y:A`;`w:A`]) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(X_CHOOSE_THEN `uw:A` (X_CHOOSE_THEN `j0:A`
      STRIP_ASSUME_TAC)) THEN
    SUBGOAL_THEN `(E:A->A->bool) j0 B` ASSUME_TAC THENL
     [MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`inclB:A`;`y:A`;`w:A`;
        `j0:A`] EJOIN_IN) THEN
      ANTS_TAC THENL
       [FIRST_ASSUM ACCEPT_TAC; DISCH_THEN(ACCEPT_TAC o CONJUNCT2)];
      ALL_TAC] THEN
    SUBGOAL_THEN `a:A = j0` SUBST_ALL_TAC THENL
     [MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`inclB:A`;
        `y:A`;`w:A`;`a:A`;`j0:A`] EJOIN_UNIQUE) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC];
      ALL_TAC] THEN
    USE_THEN "mex" (MP_TAC o SPECL [`x:A`;`j0:A`]) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(X_CHOOSE_THEN `b0:A` STRIP_ASSUME_TAC) THEN
    SUBGOAL_THEN `b:A = b0` SUBST_ALL_TAC THENL
     [MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`inclB:A`;
        `x:A`;`j0:A`;`b:A`;`b0:A`] EMEET_UNIQUE) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC];
      ALL_TAC] THEN
    USE_THEN "mex" (MP_TAC o SPECL [`x:A`;`y:A`]) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(X_CHOOSE_THEN `c0:A` STRIP_ASSUME_TAC) THEN
    SUBGOAL_THEN `c:A = c0` SUBST_ALL_TAC THENL
     [MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`inclB:A`;
        `x:A`;`y:A`;`c:A`;`c0:A`] EMEET_UNIQUE) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC];
      ALL_TAC] THEN
    USE_THEN "mex" (MP_TAC o SPECL [`x:A`;`w:A`]) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(X_CHOOSE_THEN `d0:A` STRIP_ASSUME_TAC) THEN
    SUBGOAL_THEN `d:A = d0` SUBST_ALL_TAC THENL
     [MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`inclB:A`;
        `x:A`;`w:A`;`d:A`;`d0:A`] EMEET_UNIQUE) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC];
      ALL_TAC] THEN
    SUBGOAL_THEN `(E:A->A->bool) c0 B /\ (E:A->A->bool) d0 B`
      STRIP_ASSUME_TAC THENL
     [CONJ_TAC THENL
       [MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`inclB:A`;
          `x:A`;`y:A`;`c0:A`] EMEET_IN) THEN
        ANTS_TAC THENL
         [FIRST_ASSUM ACCEPT_TAC; DISCH_THEN(ACCEPT_TAC o CONJUNCT2)];
        MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`inclB:A`;
          `x:A`;`w:A`;`d0:A`] EMEET_IN) THEN
        ANTS_TAC THENL
         [FIRST_ASSUM ACCEPT_TAC; DISCH_THEN(ACCEPT_TAC o CONJUNCT2)]];
      ALL_TAC] THEN
    USE_THEN "jex" (MP_TAC o SPECL [`c0:A`;`d0:A`]) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(X_CHOOSE_THEN `cd:A` (X_CHOOSE_THEN `e0:A`
      STRIP_ASSUME_TAC)) THEN
    SUBGOAL_THEN `e:A = e0` SUBST_ALL_TAC THENL
     [MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`inclB:A`;
        `c0:A`;`d0:A`;`e:A`;`e0:A`] EJOIN_UNIQUE) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC];
      ALL_TAC] THEN
    MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`P:A`;`leqp:A`;`B:A`;
      `x:A`;`y:A`;`w:A`;`uw:A`;`j0:A`;`b0:A`;`c0:A`;`d0:A`;`cd:A`;`e0:A`]
      RO_DISTRIB_EQ) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC];
    X_GEN_TAC `u:A` THEN STRIP_TAC THEN
    MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`P:A`;`leqp:A`;`B:A`;`inclB:A`;
      `u:A`] ECOMPL_ROSET) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC]]);;

let ECBA_ROSET = prove
 (`!D (E:A->A->bool) P leqp B inclB.
      model D E ZF_AX /\
      P IN D /\ leqp IN D /\ eleqp D E P leqp /\
      eroset D E P leqp B /\ eincl D E B inclB
      ==> ecba D E B inclB`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[ecba] THEN CONJ_TAC THENL
   [MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`P:A`;`leqp:A`;`B:A`;`inclB:A`]
      EBALG_ROSET) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC];
    ALL_TAC] THEN
  X_GEN_TAC `s:A` THEN STRIP_TAC THEN
  MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`s:A`] EUNION_EXISTS) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_TAC `us:A`) THEN
  SUBGOAL_THEN `(us:A) IN D` ASSUME_TAC THENL
   [FIRST_ASSUM(ACCEPT_TAC o MATCH_MP EUNION_IN); ALL_TAC] THEN
  MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`P:A`;`leqp:A`;`us:A`]
    EINTCL_EXISTS) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_TAC `l:A`) THEN
  SUBGOAL_THEN `(l:A) IN D` ASSUME_TAC THENL
   [FIRST_ASSUM(ACCEPT_TAC o CONJUNCT1 o GEN_REWRITE_RULE I [eintcl]);
    ALL_TAC] THEN
  UNDISCH_TAC `eunion D (E:A->A->bool) s us` THEN REWRITE_TAC[eunion] THEN
  DISCH_THEN(CONJUNCTS_THEN2 (K ALL_TAC) (LABEL_TAC "chus")) THEN
  SUBGOAL_THEN `(E:A->A->bool) l B` (LABEL_TAC "lB") THENL
   [MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`P:A`;`leqp:A`;`us:A`;`l:A`;
      `B:A`] EINTCL_RO) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC];
    ALL_TAC] THEN
  SUBGOAL_THEN `esubset D (E:A->A->bool) us P` (LABEL_TAC "usP") THENL
   [REWRITE_TAC[esubset] THEN X_GEN_TAC `m:A` THEN STRIP_TAC THEN
    USE_THEN "chus" (MP_TAC o SPEC `m:A`) THEN
    ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN(fun th -> MP_TAC(EQ_MP th (ASSUME `(E:A->A->bool) m us`))) THEN
    DISCH_THEN(X_CHOOSE_THEN `u:A` STRIP_ASSUME_TAC) THEN
    SUBGOAL_THEN `(E:A->A->bool) u B` ASSUME_TAC THENL
     [UNDISCH_TAC `esubset D (E:A->A->bool) s B` THEN REWRITE_TAC[esubset] THEN
      DISCH_THEN MATCH_MP_TAC THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    FIRST_ASSUM(MP_TAC o SPEC `u:A` o CONJUNCT2 o REWRITE_RULE[eroset]) THEN
    ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN(fun th -> MP_TAC(EQ_MP th (ASSUME `(E:A->A->bool) u B`))) THEN
    DISCH_THEN(CONJUNCTS_THEN2 MP_TAC (K ALL_TAC)) THEN
    REWRITE_TAC[esubset] THEN DISCH_THEN MATCH_MP_TAC THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `eopen D (E:A->A->bool) leqp us` (LABEL_TAC "uso") THENL
   [REWRITE_TAC[eopen] THEN
    MAP_EVERY X_GEN_TAC [`p:A`;`q:A`] THEN STRIP_TAC THEN
    USE_THEN "chus" (MP_TAC o SPEC `p:A`) THEN
    ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN(fun th -> MP_TAC(EQ_MP th (ASSUME `(E:A->A->bool) p us`))) THEN
    DISCH_THEN(X_CHOOSE_THEN `u:A` STRIP_ASSUME_TAC) THEN
    SUBGOAL_THEN `(E:A->A->bool) u B` ASSUME_TAC THENL
     [UNDISCH_TAC `esubset D (E:A->A->bool) s B` THEN REWRITE_TAC[esubset] THEN
      DISCH_THEN MATCH_MP_TAC THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN `(E:A->A->bool) q u` ASSUME_TAC THENL
     [FIRST_ASSUM(MP_TAC o SPEC `u:A` o CONJUNCT2 o REWRITE_RULE[eroset]) THEN
      ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
      DISCH_THEN(fun th -> MP_TAC(EQ_MP th (ASSUME `(E:A->A->bool) u B`))) THEN
      DISCH_THEN(CONJUNCTS_THEN2 (K ALL_TAC)
        (CONJUNCTS_THEN2 MP_TAC (K ALL_TAC))) THEN
      REWRITE_TAC[eopen] THEN
      DISCH_THEN(MP_TAC o SPECL [`p:A`;`q:A`]) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC];
      ALL_TAC] THEN
    USE_THEN "chus" (MP_TAC o SPEC `q:A`) THEN
    ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    EXISTS_TAC `u:A` THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  EXISTS_TAC `l:A` THEN REWRITE_TAC[elub; eubound] THEN
  REPEAT CONJ_TAC THENL
   [ASM_REWRITE_TAC[];
    USE_THEN "lB" ACCEPT_TAC;
    X_GEN_TAC `xx:A` THEN STRIP_TAC THEN
    SUBGOAL_THEN `(E:A->A->bool) xx B` ASSUME_TAC THENL
     [UNDISCH_TAC `esubset D (E:A->A->bool) s B` THEN REWRITE_TAC[esubset] THEN
      DISCH_THEN MATCH_MP_TAC THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`inclB:A`;`xx:A`;`l:A`]
      EINCL_EREL_INTRO) THEN
    ANTS_TAC THENL [ALL_TAC; DISCH_THEN ACCEPT_TAC] THEN
    ASM_REWRITE_TAC[] THEN
    SUBGOAL_THEN `esubset D (E:A->A->bool) us l` MP_TAC THENL
     [MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`P:A`;`leqp:A`;`us:A`;`l:A`]
        EINTCL_EXPAND) THEN
      ANTS_TAC THENL
       [ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
         [USE_THEN "usP" ACCEPT_TAC; USE_THEN "uso" ACCEPT_TAC];
        DISCH_THEN ACCEPT_TAC];
      ALL_TAC] THEN
    REWRITE_TAC[esubset] THEN DISCH_THEN(LABEL_TAC "usl") THEN
    X_GEN_TAC `m:A` THEN STRIP_TAC THEN
    USE_THEN "usl" MATCH_MP_TAC THEN ASM_REWRITE_TAC[] THEN
    USE_THEN "chus" (MP_TAC o SPEC `m:A`) THEN
    ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    EXISTS_TAC `xx:A` THEN ASM_REWRITE_TAC[];
    X_GEN_TAC `wb:A` THEN
    DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC
      (CONJUNCTS_THEN2 ASSUME_TAC (LABEL_TAC "ub"))) THEN
    SUBGOAL_THEN `ereg D (E:A->A->bool) P leqp wb` ASSUME_TAC THENL
     [FIRST_ASSUM(MP_TAC o SPEC `wb:A` o CONJUNCT2 o REWRITE_RULE[eroset]) THEN
      ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
      DISCH_THEN(fun th ->
                 MP_TAC(EQ_MP th (ASSUME `(E:A->A->bool) wb B`))) THEN
      STRIP_TAC THEN FIRST_ASSUM ACCEPT_TAC;
      ALL_TAC] THEN
    MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`inclB:A`;`l:A`;`wb:A`]
      EINCL_EREL_INTRO) THEN
    ANTS_TAC THENL [ALL_TAC; DISCH_THEN ACCEPT_TAC] THEN
    ASM_REWRITE_TAC[] THEN
    MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`P:A`;`leqp:A`;`us:A`;`l:A`;
      `wb:A`] EINTCL_MIN) THEN
    ANTS_TAC THENL [ALL_TAC; DISCH_THEN ACCEPT_TAC] THEN
    ASM_REWRITE_TAC[] THEN
    REWRITE_TAC[esubset] THEN X_GEN_TAC `m:A` THEN STRIP_TAC THEN
    USE_THEN "chus" (MP_TAC o SPEC `m:A`) THEN
    ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN(fun th -> MP_TAC(EQ_MP th (ASSUME `(E:A->A->bool) m us`))) THEN
    DISCH_THEN(X_CHOOSE_THEN `u:A` STRIP_ASSUME_TAC) THEN
    USE_THEN "ub" (MP_TAC o SPEC `u:A`) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_TAC THEN
    MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`inclB:A`;`u:A`;`wb:A`]
      EINCL_EREL) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    STRIP_TAC THEN
    UNDISCH_TAC `esubset D (E:A->A->bool) u wb` THEN REWRITE_TAC[esubset] THEN
    DISCH_THEN MATCH_MP_TAC THEN ASM_REWRITE_TAC[]]);;

(* ==================================================================== *)
(* F2 CAPSTONE.  COHEN_CBA_EXISTS: in any model of ZF, the whole        *)
(* concrete tower exists -- Cohen carrier P (finite partial functions    *)
(* into ii x tw), its order leqp, the regular-open carrier B, the        *)
(* inclusion order inclB -- and (B, inclB) is a NONTRIVIAL internal      *)
(* complete Boolean algebra (bot = empty set, top = P, distinct via the  *)
(* empty condition).                                                     *)
(* ==================================================================== *)

let COHEN_CBA_EXISTS = prove
 (`!D (E:A->A->bool) ii tw om.
      model D E ZF_AX /\ ii IN D /\ tw IN D /\ eomega D E om
      ==> ?ci P leqp B inclB z.
            ecross D E ii tw ci /\ ecohenp D E ci om P /\
            eleqp D E P leqp /\ eroset D E P leqp B /\
            eincl D E B inclB /\
            ecba D E B inclB /\
            ebot D E B inclB z /\ etop D E B inclB P /\ ~(z = P)`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `(om:A) IN D` ASSUME_TAC THENL
   [FIRST_ASSUM(ACCEPT_TAC o MATCH_MP EOMEGA_IN); ALL_TAC] THEN
  MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`ii:A`;`tw:A`;`om:A`]
    ECOHENP_EXISTS) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `ci:A` (X_CHOOSE_THEN `P:A` STRIP_ASSUME_TAC)) THEN
  SUBGOAL_THEN `(P:A) IN D` ASSUME_TAC THENL
   [FIRST_ASSUM(ACCEPT_TAC o CONJUNCT1 o GEN_REWRITE_RULE I [ecohenp]);
    ALL_TAC] THEN
  MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`ci:A`;`om:A`;`P:A`]
    ELEQP_EXISTS) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_TAC `leqp:A`) THEN
  SUBGOAL_THEN `(leqp:A) IN D` ASSUME_TAC THENL
   [FIRST_ASSUM(ACCEPT_TAC o CONJUNCT1 o GEN_REWRITE_RULE I [eleqp]);
    ALL_TAC] THEN
  MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`P:A`;`leqp:A`] EROSET_EXISTS) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_TAC `B:A`) THEN
  SUBGOAL_THEN `(B:A) IN D` ASSUME_TAC THENL
   [FIRST_ASSUM(ACCEPT_TAC o CONJUNCT1 o GEN_REWRITE_RULE I [eroset]);
    ALL_TAC] THEN
  MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`] EINCL_EXISTS) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_TAC `inclB:A`) THEN
  MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`] EEMPTY_EXISTS) THEN
  ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_TAC `z:A`) THEN
  SUBGOAL_THEN `(z:A) IN D` ASSUME_TAC THENL
   [FIRST_ASSUM(ACCEPT_TAC o CONJUNCT1 o GEN_REWRITE_RULE I [eempty]);
    ALL_TAC] THEN
  MAP_EVERY EXISTS_TAC
    [`ci:A`;`P:A`;`leqp:A`;`B:A`;`inclB:A`;`z:A`] THEN
  ASM_REWRITE_TAC[] THEN REPEAT CONJ_TAC THENL
   [MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`P:A`;`leqp:A`;`B:A`;`inclB:A`]
      ECBA_ROSET) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC];
    MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`P:A`;`leqp:A`;`B:A`;`inclB:A`;
      `z:A`] EBOT_ROSET) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC];
    MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`P:A`;`leqp:A`;`B:A`;`inclB:A`]
      ETOP_ROSET) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC];
    MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`ci:A`;`om:A`;`P:A`;`z:A`]
      ECOHENP_NE) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC]]);;

(* ==================================================================== *)
(* F2.8  Density bridges P -> B: e(p) := intcl(downset p).               *)
(* edownset p dp = { q in P : q leqp p }; the pair (dp, ep) with         *)
(* eintcl dp ep plays e(p).  Kit: downset is open and contains p; e(p)   *)
(* is RO; p IN e(p) (so e(p) is NONBOT); e monotone; and the COMPAT      *)
(* bridge both ways (r <= p,q  <->  common member of e(p), e(q)) --      *)
(* exactly what F6.4's ccc transfer consumes.                            *)
(* ==================================================================== *)

let edownset = new_definition
  `edownset D (E:A->A->bool) P leqp p dp <=>
     dp IN D /\
     !q. q IN D ==> (E q dp <=> E q P /\ erel D E leqp q p)`;;

let EDOWNSET_EXISTS = prove
 (`!D (E:A->A->bool) P leqp p.
      model D E ZF_AX /\ P IN D /\ leqp IN D /\ p IN D
      ==> ?dp. edownset D E P leqp p dp`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `valuation D ((1 |-> (p:A)) ((2 |-> (leqp:A)) (\n:num. P:A)))`
   (LABEL_TAC "val") THENL
   [MATCH_MP_TAC VALUATION_VALMOD THEN CONJ_TAC THENL
     [MATCH_MP_TAC VALUATION_VALMOD THEN CONJ_TAC THENL
       [REWRITE_TAC[valuation] THEN FIRST_ASSUM ACCEPT_TAC;
        FIRST_ASSUM ACCEPT_TAC];
      FIRST_ASSUM ACCEPT_TAC];
    ALL_TAC] THEN
  MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`] ZF_SEPARATION) THEN
  ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  DISCH_THEN(MP_TAC o ISPECL
    [`rel_form 2 3 1`; `3`;
     `(1 |-> (p:A)) ((2 |-> (leqp:A)) (\n:num. P:A))`; `P:A`]) THEN
  ANTS_TAC THENL
   [CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
    DISCH_THEN(X_CHOOSE_THEN `dp:A`
      (CONJUNCTS_THEN2 ASSUME_TAC (LABEL_TAC "sep")))] THEN
  EXISTS_TAC `dp:A` THEN REWRITE_TAC[edownset] THEN
  CONJ_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  X_GEN_TAC `q:A` THEN DISCH_TAC THEN
  USE_THEN "sep" (MP_TAC o SPEC `q:A`) THEN
  ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  DISCH_THEN SUBST1_TAC THEN
  SUBGOAL_THEN
   `valuation D
    ((3 |-> (q:A)) ((1 |-> (p:A)) ((2 |-> (leqp:A)) (\n:num. P:A))))`
   ASSUME_TAC THENL
   [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;
    `(3 |-> (q:A)) ((1 |-> (p:A)) ((2 |-> (leqp:A)) (\n:num. P:A)))`;
    `2`;`3`;`1`] HOLDS_REL_FORM) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  REWRITE_TAC[VALMOD; ARITH_EQ] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]));;

let EDOWNSET_OPEN = prove
 (`!D (E:A->A->bool) P leqp p dp.
      model D E ZF_AX /\ eleqp D E P leqp /\ p IN D /\
      edownset D E P leqp p dp
      ==> eopen D E leqp dp`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[eopen] THEN
  MAP_EVERY X_GEN_TAC [`m:A`;`q:A`] THEN STRIP_TAC THEN
  FIRST_ASSUM(MP_TAC o SPEC `m:A` o CONJUNCT2 o REWRITE_RULE[edownset]) THEN
  ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  DISCH_THEN(fun th -> MP_TAC(EQ_MP th (ASSUME `(E:A->A->bool) m dp`))) THEN
  STRIP_TAC THEN
  FIRST_ASSUM(MP_TAC o SPEC `q:A` o CONJUNCT2 o REWRITE_RULE[edownset]) THEN
  ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  CONJ_TAC THENL
   [MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`P:A`;`leqp:A`;`q:A`;`m:A`]
      ELEQP_EREL) THEN
    ASM_REWRITE_TAC[] THEN DISCH_THEN(ACCEPT_TAC o CONJUNCT1);
    MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`P:A`;`leqp:A`;`q:A`;`m:A`;`p:A`]
      LEQP_TRANS_E) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC]]);;

let EDOWNSET_SUB = prove
 (`!D (E:A->A->bool) P leqp p dp.
      edownset D E P leqp p dp ==> esubset D E dp P`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[esubset] THEN
  X_GEN_TAC `m:A` THEN STRIP_TAC THEN
  FIRST_ASSUM(MP_TAC o SPEC `m:A` o CONJUNCT2 o REWRITE_RULE[edownset]) THEN
  ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  DISCH_THEN(fun th -> MP_TAC(EQ_MP th (ASSUME `(E:A->A->bool) m dp`))) THEN
  DISCH_THEN(CONJUNCTS_THEN2 ACCEPT_TAC (K ALL_TAC)));;

let EDOWNSET_MEMSELF = prove
 (`!D (E:A->A->bool) P leqp p dp.
      model D E ZF_AX /\ eleqp D E P leqp /\ p IN D /\ E p P /\
      edownset D E P leqp p dp
      ==> E p dp`,
  REPEAT STRIP_TAC THEN
  FIRST_ASSUM(MP_TAC o SPEC `p:A` o CONJUNCT2 o REWRITE_RULE[edownset]) THEN
  ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  ASM_REWRITE_TAC[] THEN
  MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`P:A`;`leqp:A`;`p:A`]
    LEQP_REFL_E) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC]);;

let EMB_SUB = prove
 (`!D (E:A->A->bool) P leqp p dp ep.
      model D E ZF_AX /\ eleqp D E P leqp /\ p IN D /\
      edownset D E P leqp p dp /\ eintcl D E P leqp dp ep
      ==> esubset D E dp ep`,
  REPEAT STRIP_TAC THEN
  MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`P:A`;`leqp:A`;`dp:A`;`ep:A`]
    EINTCL_EXPAND) THEN
  ANTS_TAC THENL [ALL_TAC; DISCH_THEN ACCEPT_TAC] THEN
  ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
   [MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`P:A`;`leqp:A`;`p:A`;`dp:A`]
      EDOWNSET_SUB) THEN
    ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; DISCH_THEN ACCEPT_TAC];
    MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`P:A`;`leqp:A`;`p:A`;`dp:A`]
      EDOWNSET_OPEN) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC]]);;

let EMB_NONBOT = prove
 (`!D (E:A->A->bool) P leqp p dp ep.
      model D E ZF_AX /\ eleqp D E P leqp /\ p IN D /\ E p P /\
      edownset D E P leqp p dp /\ eintcl D E P leqp dp ep
      ==> E p ep`,
  REPEAT STRIP_TAC THEN
  MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`P:A`;`leqp:A`;`p:A`;`dp:A`;`ep:A`]
    EMB_SUB) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  REWRITE_TAC[esubset] THEN DISCH_THEN MATCH_MP_TAC THEN
  ASM_REWRITE_TAC[] THEN
  MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`P:A`;`leqp:A`;`p:A`;`dp:A`]
    EDOWNSET_MEMSELF) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC]);;

let EMB_MONO = prove
 (`!D (E:A->A->bool) P leqp q p dp ep dq eq2.
      model D E ZF_AX /\ eleqp D E P leqp /\ q IN D /\ p IN D /\
      erel D E leqp q p /\
      edownset D E P leqp p dp /\ eintcl D E P leqp dp ep /\
      edownset D E P leqp q dq /\ eintcl D E P leqp dq eq2
      ==> esubset D E eq2 ep`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `(ep:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[eintcl]; ALL_TAC] THEN
  SUBGOAL_THEN `esubset D (E:A->A->bool) dp ep` (LABEL_TAC "dpep") THENL
   [MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`P:A`;`leqp:A`;`p:A`;`dp:A`;
      `ep:A`] EMB_SUB) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC];
    ALL_TAC] THEN
  MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`P:A`;`leqp:A`;`dq:A`;`eq2:A`;
    `ep:A`] EINTCL_MIN) THEN
  ANTS_TAC THENL [ALL_TAC; DISCH_THEN ACCEPT_TAC] THEN
  ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
   [REWRITE_TAC[esubset] THEN X_GEN_TAC `m:A` THEN STRIP_TAC THEN
    UNDISCH_TAC `edownset D (E:A->A->bool) P leqp q dq` THEN
    REWRITE_TAC[edownset] THEN
    DISCH_THEN(CONJUNCTS_THEN2 (K ALL_TAC) (MP_TAC o SPEC `m:A`)) THEN
    ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN(fun th -> MP_TAC(EQ_MP th (ASSUME `(E:A->A->bool) m dq`))) THEN
    STRIP_TAC THEN
    USE_THEN "dpep" (MP_TAC o REWRITE_RULE[esubset]) THEN
    DISCH_THEN MATCH_MP_TAC THEN ASM_REWRITE_TAC[] THEN
    UNDISCH_TAC `edownset D (E:A->A->bool) P leqp p dp` THEN
    REWRITE_TAC[edownset] THEN
    DISCH_THEN(CONJUNCTS_THEN2 (K ALL_TAC) (MP_TAC o SPEC `m:A`)) THEN
    ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    ASM_REWRITE_TAC[] THEN
    MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`P:A`;`leqp:A`;`m:A`;`q:A`;`p:A`]
      LEQP_TRANS_E) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC];
    MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`P:A`;`leqp:A`;`dp:A`;`ep:A`]
      EINTCL_REG) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC]]);;

let EMB_MEET_FWD = prove
 (`!D (E:A->A->bool) P leqp r p q dp ep dq eq2.
      model D E ZF_AX /\ eleqp D E P leqp /\
      r IN D /\ p IN D /\ q IN D /\
      erel D E leqp r p /\ erel D E leqp r q /\
      edownset D E P leqp p dp /\ eintcl D E P leqp dp ep /\
      edownset D E P leqp q dq /\ eintcl D E P leqp dq eq2
      ==> E r ep /\ E r eq2`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `(E:A->A->bool) r P` ASSUME_TAC THENL
   [MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`P:A`;`leqp:A`;`r:A`;`p:A`]
      ELEQP_EREL) THEN
    ASM_REWRITE_TAC[] THEN DISCH_THEN(ACCEPT_TAC o CONJUNCT1);
    ALL_TAC] THEN
  CONJ_TAC THENL
   [MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`P:A`;`leqp:A`;`p:A`;`dp:A`;
      `ep:A`] EMB_SUB) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    REWRITE_TAC[esubset] THEN DISCH_THEN MATCH_MP_TAC THEN
    ASM_REWRITE_TAC[] THEN
    UNDISCH_TAC `edownset D (E:A->A->bool) P leqp p dp` THEN
    REWRITE_TAC[edownset] THEN
    DISCH_THEN(CONJUNCTS_THEN2 (K ALL_TAC) (MP_TAC o SPEC `r:A`)) THEN
    ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN ASM_REWRITE_TAC[];
    MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`P:A`;`leqp:A`;`q:A`;`dq:A`;
      `eq2:A`] EMB_SUB) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    REWRITE_TAC[esubset] THEN DISCH_THEN MATCH_MP_TAC THEN
    ASM_REWRITE_TAC[] THEN
    UNDISCH_TAC `edownset D (E:A->A->bool) P leqp q dq` THEN
    REWRITE_TAC[edownset] THEN
    DISCH_THEN(CONJUNCTS_THEN2 (K ALL_TAC) (MP_TAC o SPEC `r:A`)) THEN
    ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN ASM_REWRITE_TAC[]]);;

let EMB_MEET_BWD = prove
 (`!D (E:A->A->bool) P leqp p q dp ep dq eq2 m.
      model D E ZF_AX /\ eleqp D E P leqp /\
      p IN D /\ q IN D /\ m IN D /\
      edownset D E P leqp p dp /\ eintcl D E P leqp dp ep /\
      edownset D E P leqp q dq /\ eintcl D E P leqp dq eq2 /\
      E m ep /\ E m eq2
      ==> ?r. r IN D /\ erel D E leqp r p /\ erel D E leqp r q`,
  REPEAT STRIP_TAC THEN
  UNDISCH_TAC `eintcl D (E:A->A->bool) P leqp dp ep` THEN
  REWRITE_TAC[eintcl] THEN
  DISCH_THEN(CONJUNCTS_THEN2 (K ALL_TAC) (MP_TAC o SPEC `m:A`)) THEN
  ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  DISCH_THEN(fun th -> MP_TAC(EQ_MP th (ASSUME `(E:A->A->bool) m ep`))) THEN
  DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "mP") (LABEL_TAC "d1")) THEN
  USE_THEN "d1" (MP_TAC o SPEC `m:A`) THEN
  ANTS_TAC THENL
   [CONJ_TAC THENL
     [FIRST_ASSUM ACCEPT_TAC;
      MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`P:A`;`leqp:A`;`m:A`]
        LEQP_REFL_E) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC]];
    ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `r1:A` STRIP_ASSUME_TAC) THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leqp r1 p` ASSUME_TAC THENL
   [UNDISCH_TAC `edownset D (E:A->A->bool) P leqp p dp` THEN
    REWRITE_TAC[edownset] THEN
    DISCH_THEN(CONJUNCTS_THEN2 (K ALL_TAC) (MP_TAC o SPEC `r1:A`)) THEN
    ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN(fun th -> MP_TAC(EQ_MP th (ASSUME `(E:A->A->bool) r1 dp`))) THEN
    DISCH_THEN(CONJUNCTS_THEN2 (K ALL_TAC) ACCEPT_TAC);
    ALL_TAC] THEN
  UNDISCH_TAC `eintcl D (E:A->A->bool) P leqp dq eq2` THEN
  REWRITE_TAC[eintcl] THEN
  DISCH_THEN(CONJUNCTS_THEN2 (K ALL_TAC) (MP_TAC o SPEC `m:A`)) THEN
  ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  DISCH_THEN(fun th -> MP_TAC(EQ_MP th (ASSUME `(E:A->A->bool) m eq2`))) THEN
  DISCH_THEN(CONJUNCTS_THEN2 (K ALL_TAC) (LABEL_TAC "d2")) THEN
  USE_THEN "d2" (MP_TAC o SPEC `r1:A`) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `r2:A` STRIP_ASSUME_TAC) THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leqp r2 q` ASSUME_TAC THENL
   [UNDISCH_TAC `edownset D (E:A->A->bool) P leqp q dq` THEN
    REWRITE_TAC[edownset] THEN
    DISCH_THEN(CONJUNCTS_THEN2 (K ALL_TAC) (MP_TAC o SPEC `r2:A`)) THEN
    ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN(fun th -> MP_TAC(EQ_MP th (ASSUME `(E:A->A->bool) r2 dq`))) THEN
    DISCH_THEN(CONJUNCTS_THEN2 (K ALL_TAC) ACCEPT_TAC);
    ALL_TAC] THEN
  EXISTS_TAC `r2:A` THEN ASM_REWRITE_TAC[] THEN
  MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`P:A`;`leqp:A`;`r2:A`;`r1:A`;`p:A`]
    LEQP_TRANS_E) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC]);;

(* ==================================================================== *)
(* F6.0/F6.1a  ccc definition + the no-induction bounded-max trick.      *)
(* eccc: every internal antichain injects into omega.                    *)
(* ENAT_BOUNDED_MAX: a nonempty internal s SUBSET om, bounded by b IN    *)
(* om, contains its own union (= its max).  NO meta-induction: the one   *)
(* induction is EOMEGA_CASES ("0 or successor"), already internal.       *)
(* ==================================================================== *)

let eccc = new_definition
  `eccc D (E:A->A->bool) P leq <=>
     !a. a IN D /\ eantichain D E P leq a
         ==> ?om f. eomega D E om /\ f IN D /\ einj D E f a om`;;

(* ==================================================================== *)
(* F6.1b L2: EUNCOUNTABLE_SUCCARD_INJ.                                    *)
(* If X is uncountable (~(X >-> om)) and a1 is the successor cardinal of  *)
(* om (least cardinal > om, in the ESUCCARD_EXISTS packaging), then a1    *)
(* injects into X.  Needs V=L (elmem) for ECARDOF_EXISTS.                 *)
(*                                                                        *)
(* Proof: cX := |X| (ECARDOF_EXISTS).  ecardof X cX gives eordinal cX +   *)
(* a bijection fb : cX <-> X.  Trichotomy om vs cX kills cX <= om (would  *)
(* give X >-> om via fb^-1, contra), so E om cX; ECARDOF_CARDINAL gives   *)
(* cX a cardinal.  a1-minimality forbids E cX a1 (cX is a cardinal > om), *)
(* so a1 <= cX (trichotomy).  Then id : a1 >-> cX (EINJ_WEAKEN over the   *)
(* transitive cX) composed with fb : cX >-> X gives a1 >-> X.             *)
(* ==================================================================== *)

let EUNCOUNTABLE_SUCCARD_INJ = prove
 (`!D (E:A->A->bool) om a1 X.
          model D E ZF_AX /\ (!u. u IN D ==> elmem D E u) /\
          eomega D E om /\ X IN D /\
          ~(?e. einj D E e X om) /\
          a1 IN D /\ ecardinal D E a1 /\ E om a1 /\
          (!c'. c' IN D /\ E c' a1
                ==> ~(ecardinal D E c' /\ E om c'))
          ==> ?e. einj D E e a1 X`,
      REPEAT GEN_TAC THEN
      INTRO_TAC "zf h omom XD noinj a1D carda1 oma1 a1min" THEN
      (* om, a1 are ordinals *)
      SUBGOAL_THEN `eordinal D (E:A->A->bool) om` ASSUME_TAC THENL
       [ASM_MESON_TAC[EOMEGA_ORDINAL]; ALL_TAC] THEN
      SUBGOAL_THEN `eordinal D (E:A->A->bool) a1` ASSUME_TAC THENL
       [MP_TAC(ASSUME `ecardinal D (E:A->A->bool) a1`) THEN
        REWRITE_TAC[ecardinal; ecardof] THEN STRIP_TAC THEN ASM_REWRITE_TAC[];
        ALL_TAC] THEN
      (* cardinality cX of X, with bijection fb : cX <-> X *)
      MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `X:A`] ECARDOF_EXISTS) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(X_CHOOSE_THEN `cX:A` (LABEL_TAC "cof")) THEN
      USE_THEN "cof" (MP_TAC o REWRITE_RULE[ecardof]) THEN
      DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC
        (CONJUNCTS_THEN2 ASSUME_TAC
        (CONJUNCTS_THEN2 (X_CHOOSE_TAC `fb:A`) (K ALL_TAC)))) THEN
      (* Step: E om cX (X uncountable) via trichotomy om vs cX *)
      SUBGOAL_THEN `(E:A->A->bool) om cX` ASSUME_TAC THENL
       [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `om:A`; `cX:A`]
          EORDINAL_TRICHOTOMY) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
        STRIP_TAC THENL
         [(* E om cX (1st disjunct) EQUALS this subgoal,
          so STRIP_TAC's       *)
          (* CHECK_ASSUME_TAC auto-discharges it; only om = cX and E cX om   *)
          (* survive -- supply exactly TWO branch tactics, not three.        *)
          (* om = cX: X bijects om, so X >-> om, contra noinj                *)
          FIRST_ASSUM(SUBST_ALL_TAC o SYM) THEN
          MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `fb:A`; `om:A`; `X:A`]
            EBIJ_SYM) THEN
          ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
          DISCH_THEN(X_CHOOSE_TAC `g:A`) THEN
          SUBGOAL_THEN `einj D (E:A->A->bool) g X om` ASSUME_TAC THENL
           [ASM_MESON_TAC[EBIJ_EINJ]; ALL_TAC] THEN
          ASM_MESON_TAC[];
          (* E cX om: X bijects cX SUBSET om, so X >-> om, contra noinj *)
          MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `fb:A`; `cX:A`; `X:A`]
            EBIJ_SYM) THEN
          ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
          DISCH_THEN(X_CHOOSE_TAC `g:A`) THEN
          SUBGOAL_THEN `einj D (E:A->A->bool) g X om` ASSUME_TAC THENL
           [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `g:A`; `X:A`; `cX:A`;
              `om:A`] EINJ_WEAKEN) THEN
            ANTS_TAC THENL
             [CONJ_TAC THENL
               [ASM_MESON_TAC[EBIJ_EINJ];
                X_GEN_TAC `t:A` THEN STRIP_TAC THEN
                SUBGOAL_THEN `etransitive D (E:A->A->bool) om` MP_TAC THENL
                 [ASM_MESON_TAC[eordinal]; ALL_TAC] THEN
                REWRITE_TAC[etransitive] THEN
                DISCH_THEN(MP_TAC o SPEC `cX:A`) THEN
                ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
                REWRITE_TAC[esubset] THEN DISCH_THEN MATCH_MP_TAC THEN
                ASM_REWRITE_TAC[]];
              DISCH_THEN ACCEPT_TAC];
            ALL_TAC] THEN
          ASM_MESON_TAC[]];
        ALL_TAC] THEN
      (* cX is a cardinal *)
      SUBGOAL_THEN `ecardinal D (E:A->A->bool) cX` ASSUME_TAC THENL
       [ASM_MESON_TAC[ECARDOF_CARDINAL]; ALL_TAC] THEN
      (* a1-minimality forbids E cX a1 *)
      SUBGOAL_THEN `~((E:A->A->bool) cX a1)` ASSUME_TAC THENL
       [DISCH_TAC THEN
        SUBGOAL_THEN `~(ecardinal D (E:A->A->bool) cX /\ E om cX)` MP_TAC THENL
         [USE_THEN "a1min" MATCH_MP_TAC THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
        ASM_REWRITE_TAC[];
        ALL_TAC] THEN
      (* a1 SUBSET cX (pointwise), from trichotomy a1 vs cX minus E cX a1 *)
      SUBGOAL_THEN `!t:A. t IN D /\ (E:A->A->bool) t a1 ==> E t cX`
        (LABEL_TAC "a1sub") THENL
       [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `a1:A`; `cX:A`]
          EORDINAL_TRICHOTOMY) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
        STRIP_TAC THENL
         [X_GEN_TAC `t:A` THEN STRIP_TAC THEN
          SUBGOAL_THEN `etransitive D (E:A->A->bool) cX` MP_TAC THENL
           [ASM_MESON_TAC[eordinal]; ALL_TAC] THEN
          REWRITE_TAC[etransitive] THEN DISCH_THEN(MP_TAC o SPEC `a1:A`) THEN
          ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
          REWRITE_TAC[esubset] THEN DISCH_THEN MATCH_MP_TAC THEN
          ASM_REWRITE_TAC[];
          ASM_REWRITE_TAC[] THEN MESON_TAC[];
          ASM_MESON_TAC[]];
        ALL_TAC] THEN
      (* id : a1 >-> cX *)
      SUBGOAL_THEN `?i:A. einj D (E:A->A->bool) i a1 cX`
        (X_CHOOSE_TAC `ii:A`) THENL
       [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `a1:A`] EBIJ_ID) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
        DISCH_THEN(X_CHOOSE_TAC `h:A`) THEN EXISTS_TAC `h:A` THEN
        MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `h:A`; `a1:A`; `a1:A`;
          `cX:A`] EINJ_WEAKEN) THEN
        ANTS_TAC THENL
         [CONJ_TAC THENL
           [ASM_MESON_TAC[EBIJ_EINJ]; USE_THEN "a1sub" ACCEPT_TAC];
          DISCH_THEN ACCEPT_TAC];
        ALL_TAC] THEN
      (* fb : cX >-> X *)
      SUBGOAL_THEN `einj D (E:A->A->bool) fb cX X` ASSUME_TAC THENL
       [ASM_MESON_TAC[EBIJ_EINJ]; ALL_TAC] THEN
      (* compose ii then fb : a1 >-> X *)
      MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `ii:A`; `fb:A`; `a1:A`;
        `cX:A`; `X:A`] EINJ_COMPOSE) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(X_CHOOSE_TAC `hh:A`) THEN
      EXISTS_TAC `hh:A` THEN FIRST_ASSUM ACCEPT_TAC);;

(* ==================================================================== *)
(* F2.1  Cardinal packaging: the two successor cardinals above omega.     *)
(* Given omega (eomega) in a V=L model, produce a1 := ESUCCARD om (the    *)
(* least cardinal > om, i.e. aleph_1) and kk := ESUCCARD a1 (aleph_2).    *)
(* Just chains ESUCCARD_EXISTS twice; the second application needs        *)
(* eordinal a1, which holds because cardinals are ordinals (ecardof       *)
(* unfold gives eordinal).  Reusable witness bundle for F6.3/F6.4/F7.     *)
(* ==================================================================== *)

let ESUCCARD2_EXISTS = prove
 (`!D (E:A->A->bool) om.
          model D E ZF_AX /\ (!u. u IN D ==> elmem D E u) /\ eomega D E om
          ==> ?a1 kk.
                a1 IN D /\ ecardinal D E a1 /\ E om a1 /\
                (!c'. c' IN D /\ E c' a1
                      ==> ~(ecardinal D E c' /\ E om c')) /\
                kk IN D /\ ecardinal D E kk /\ E a1 kk /\
                (!c'. c' IN D /\ E c' kk
                      ==> ~(ecardinal D E c' /\ E a1 c'))`,
      REPEAT GEN_TAC THEN STRIP_TAC THEN
      (* om is an ordinal *)
      SUBGOAL_THEN `eordinal D (E:A->A->bool) om` ASSUME_TAC THENL
       [ASM_MESON_TAC[EOMEGA_ORDINAL]; ALL_TAC] THEN
      (* a1 := least cardinal > om *)
      MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `om:A`] ESUCCARD_EXISTS) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(X_CHOOSE_THEN `a1:A` STRIP_ASSUME_TAC) THEN
      (* a1 is an ordinal (cardinals are ordinals) *)
      SUBGOAL_THEN `eordinal D (E:A->A->bool) a1` ASSUME_TAC THENL
       [MP_TAC(ASSUME `ecardinal D (E:A->A->bool) a1`) THEN
        REWRITE_TAC[ecardinal; ecardof] THEN STRIP_TAC THEN ASM_REWRITE_TAC[];
        ALL_TAC] THEN
      (* kk := least cardinal > a1 *)
      MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `a1:A`] ESUCCARD_EXISTS) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(X_CHOOSE_THEN `kk:A` STRIP_ASSUME_TAC) THEN
      MAP_EVERY EXISTS_TAC [`a1:A`; `kk:A`] THEN ASM_REWRITE_TAC[]);;

(* ==================================================================== *)
(* F6.1b foundation: SIZE-FIBER FAMILY builder (sfib_*/ESFIB_*/EFAM_WUN).*)
(* ff : a -> P(X), ff(n) = { m IN X : eapply g m n }, via ZF_REPLACEMENT  *)
(* over sfib_form (functionality = SFIB_FUN); EFAM_WUN is a generic union *)
(* of any a-indexed-pair family (reused later by F6.2/F6.3).  Distinct    *)
(* from the R1 efiberfun composite-graph kit.                             *)
(* ==================================================================== *)
let sfib_form = new_definition
  `sfib_form =
     ?? 62 ((!! 2 ((2 %% 62) <-> ((2 %% 6) && apply_form 5 2 11))) &&
            opair_form 11 62 63)`;;

let HOLDS_SFIB = prove
 (`!D (E:A->A->bool) v n out.
     valuation D v /\ n IN D /\ out IN D
     ==> (holds D E ((63 |-> out) ((11 |-> n) v)) sfib_form <=>
          ?W. W IN D /\
              (!m. m IN D ==> (E m W <=> E m (v 6) /\ eapply D E (v 5) m n)) /\
              eopair D E n W out)`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[sfib_form; HOLDS_EX] THEN
  MATCH_MP_TAC(MESON[]
    `(!W:A. W IN D ==> (P W <=> Q W))
     ==> ((?W. W IN D /\ P W) <=> (?W. W IN D /\ Q W))`) THEN
  X_GEN_TAC `W:A` THEN DISCH_TAC THEN
  SUBGOAL_THEN
   `valuation D ((62 |-> (W:A)) ((63 |-> (out:A)) ((11 |-> (n:A)) v)))`
   ASSUME_TAC THENL
   [REPEAT(MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[]); ALL_TAC] THEN
  REWRITE_TAC[HOLDS_AND] THEN
  MATCH_MP_TAC(TAUT `(a <=> b) /\ (c <=> d) ==> (a /\ c <=> b /\ d)`) THEN
  CONJ_TAC THENL
   [(* ---- value-set (forall) part ---- *)
    SUBGOAL_THEN
     `!m:A. m IN D
        ==> (holds D E
             ((2 |-> m) ((62 |-> (W:A)) ((63 |-> out) ((11 |-> n) v))))
             ((2 %% 62) <-> ((2 %% 6) && apply_form 5 2 11)) <=>
             (E m W <=> E m (v 6) /\ eapply D E (v 5) m n))`
     (LABEL_TAC "bodyeq") THENL
     [X_GEN_TAC `m:A` THEN DISCH_TAC THEN
      SUBGOAL_THEN
       `valuation D
        ((2 |-> (m:A)) ((62 |-> (W:A)) ((63 |-> out) ((11 |-> n) v))))`
       ASSUME_TAC THENL
       [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
      ASM_SIMP_TAC[HOLDS_IFF; HOLDS_AND; HOLDS_APPLY_FORM] THEN
      REWRITE_TAC[holds] THEN REWRITE_TAC[VALMOD; ARITH_EQ];
      ALL_TAC] THEN
    REWRITE_TAC[holds] THEN ASM_SIMP_TAC[];
    (* ---- opair part ---- *)
    ASM_SIMP_TAC[HOLDS_OPAIR_FORM] THEN REWRITE_TAC[VALMOD; ARITH_EQ]]);;

(* -- SFIB_FUN: functionality of sfib_form (for ZF_REPLACEMENT).  For a  *)
(*    fixed index n, the output pair out = <n,W> is unique.              *)
let SFIB_FUN = prove
 (`!D (E:A->A->bool) v n.
     model D E ZF_AX /\ valuation D v /\ (v 5) IN D /\ (v 6) IN D /\ n IN D
     ==> ?out. out IN D /\
               !out'. out' IN D /\
                      holds D E ((63 |-> out') ((11 |-> n) v)) sfib_form
                      ==> out' = out`,
  REPEAT STRIP_TAC THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`] ZF_SEPARATION) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(MP_TAC o SPECL
    [`apply_form 5 2 11`; `2`; `(11 |-> (n:A)) v`; `(v:num->A) 6`]) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[] THEN MATCH_MP_TAC VALUATION_VALMOD THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `W:A`
             (CONJUNCTS_THEN2 ASSUME_TAC (LABEL_TAC "wsep"))) THEN
  SUBGOAL_THEN
   `!m:A. m IN D ==> (E m W <=> E m (v 6) /\ eapply D E (v 5) m n)`
   (LABEL_TAC "wd") THENL
   [X_GEN_TAC `m:A` THEN DISCH_TAC THEN
    USE_THEN "wsep" (MP_TAC o SPEC `m:A`) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    SUBGOAL_THEN `valuation D ((2 |-> (m:A)) ((11 |-> (n:A)) v))`
      ASSUME_TAC THENL
      [REPEAT(MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[]);
       ALL_TAC] THEN
    ASM_SIMP_TAC[HOLDS_APPLY_FORM] THEN REWRITE_TAC[VALMOD; ARITH_EQ];
    ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `n:A`; `W:A`] EOPAIR_EXISTS) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `out:A`) THEN
  SUBGOAL_THEN `(out:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[EOPAIR_IN]; ALL_TAC] THEN
  EXISTS_TAC `out:A` THEN CONJ_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  X_GEN_TAC `out':A` THEN
  DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC (LABEL_TAC "hs")) THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `v:num->A`; `n:A`; `out':A`]
         HOLDS_SFIB) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(fun th -> USE_THEN "hs" (fun h -> MP_TAC(EQ_MP th h))) THEN
  DISCH_THEN(X_CHOOSE_THEN `W':A` (CONJUNCTS_THEN2 ASSUME_TAC
    (CONJUNCTS_THEN2 (LABEL_TAC "wd'") (LABEL_TAC "eop'")))) THEN
  SUBGOAL_THEN `(W':A) = W` SUBST_ALL_TAC THENL
   [FIRST_ASSUM(fun mth -> MATCH_MP_TAC(MATCH_MP ZF_EXTENSIONALITY mth)) THEN
    ASM_REWRITE_TAC[] THEN X_GEN_TAC `m:A` THEN DISCH_TAC THEN
    USE_THEN "wd'" (fun th -> MP_TAC(SPEC `m:A` th)) THEN
    ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    USE_THEN "wd" (fun th -> MP_TAC(SPEC `m:A` th)) THEN
    ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN(fun a -> DISCH_THEN(fun b -> ACCEPT_TAC(TRANS b (SYM a))));
    ALL_TAC] THEN
  ASM_MESON_TAC[EOPAIR_UNIQUE]);;

(* -- ESFIB_FAMILY: ff = {<b, {m IN X : g m = b}> : b IN a} via           *)
(*    ZF_REPLACEMENT[sfib_form;11;63;v;a] (functionality = SFIB_FUN).      *)
(*    Delivers ff IN D, the replacement membership, single-valuedness     *)
(*    (eapply form for EGEN_UNION_CARD_LE), and the per-b characterization.*)
let ESFIB_FAMILY = prove
 (`!D (E:A->A->bool) v a.
     model D E ZF_AX /\ valuation D v /\ (v 5) IN D /\ (v 6) IN D /\ a IN D
     ==> ?ff. ff IN D /\
              (!w. w IN D
                   ==> (E w ff <=>
                        ?u. u IN D /\ E u a /\
                            holds D E ((63 |-> w) ((11 |-> u) v))
                              sfib_form)) /\
              (!n z z'. n IN D /\ z IN D /\ z' IN D /\
                        eapply D E ff n z /\ eapply D E ff n z' ==> z = z') /\
              (!b. b IN D /\ E b a
                   ==> ?W. W IN D /\
                           (!m. m IN D
                                ==> (E m W <=> E m (v 6) /\
                                     eapply D E (v 5) m b)) /\
                           eapply D E ff b W)`,
  REPEAT STRIP_TAC THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`] ZF_REPLACEMENT) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(MP_TAC o SPECL [`sfib_form`; `11`; `63`; `v:num->A`; `a:A`]) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
     [CONV_TAC NUM_REDUCE_CONV;
      X_GEN_TAC `u:A` THEN STRIP_TAC THEN
      MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `v:num->A`; `u:A`]
             SFIB_FUN) THEN
      ASM_REWRITE_TAC[]];
    ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `ff:A`
    (CONJUNCTS_THEN2 (LABEL_TAC "ffD") (LABEL_TAC "ffmem"))) THEN
  EXISTS_TAC `ff:A` THEN REPEAT CONJ_TAC THENL
   [USE_THEN "ffD" ACCEPT_TAC;
    USE_THEN "ffmem" ACCEPT_TAC;
    (* ---- single-valued ---- *)
    MAP_EVERY X_GEN_TAC [`n:A`; `z:A`; `z':A`] THEN
    REWRITE_TAC[eapply] THEN
    DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC (CONJUNCTS_THEN2 ASSUME_TAC
      (CONJUNCTS_THEN2 ASSUME_TAC (CONJUNCTS_THEN2
        (X_CHOOSE_THEN `q:A` STRIP_ASSUME_TAC)
        (X_CHOOSE_THEN `q':A` STRIP_ASSUME_TAC))))) THEN
    SUBGOAL_THEN `(q:A) IN D` ASSUME_TAC THENL
     [ASM_MESON_TAC[EOPAIR_IN]; ALL_TAC] THEN
    SUBGOAL_THEN `(q':A) IN D` ASSUME_TAC THENL
     [ASM_MESON_TAC[EOPAIR_IN]; ALL_TAC] THEN
    SUBGOAL_THEN
     `?u. u IN D /\ E u a /\
          holds D E ((63 |-> (q:A)) ((11 |-> u) v)) sfib_form`
     (X_CHOOSE_THEN `u:A` STRIP_ASSUME_TAC) THENL
     [USE_THEN "ffmem" (fun bmem ->
        ONCE_REWRITE_TAC[GSYM(MATCH_MP bmem (ASSUME `(q:A) IN D`))]) THEN
      FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `v:num->A`; `u:A`; `q:A`]
           HOLDS_SFIB) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    ASM_REWRITE_TAC[] THEN
    DISCH_THEN(X_CHOOSE_THEN `W:A` (CONJUNCTS_THEN2 ASSUME_TAC
      (CONJUNCTS_THEN2 (LABEL_TAC "wc") (LABEL_TAC "eopq")))) THEN
    SUBGOAL_THEN `(u:A) = n /\ (W:A) = z` (CONJUNCTS_THEN SUBST_ALL_TAC) THENL
     [MATCH_MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `u:A`; `W:A`; `n:A`;
        `z:A`; `q:A`] EOPAIR_INJ) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN
     `?u'. u' IN D /\ E u' a /\
           holds D E ((63 |-> (q':A)) ((11 |-> u') v)) sfib_form`
     (X_CHOOSE_THEN `u':A` STRIP_ASSUME_TAC) THENL
     [USE_THEN "ffmem" (fun bmem ->
        ONCE_REWRITE_TAC[GSYM(MATCH_MP bmem (ASSUME `(q':A) IN D`))]) THEN
      FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `v:num->A`; `u':A`; `q':A`]
           HOLDS_SFIB) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    ASM_REWRITE_TAC[] THEN
    DISCH_THEN(X_CHOOSE_THEN `W':A` (CONJUNCTS_THEN2 ASSUME_TAC
      (CONJUNCTS_THEN2 (LABEL_TAC "wc'") (LABEL_TAC "eopq'")))) THEN
    SUBGOAL_THEN `(u':A) = n /\ (W':A) = z'`
      (CONJUNCTS_THEN SUBST_ALL_TAC) THENL
      [MATCH_MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `u':A`; `W':A`; `n:A`;
        `z':A`; `q':A`] EOPAIR_INJ) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    FIRST_ASSUM(fun mth -> MATCH_MP_TAC(MATCH_MP ZF_EXTENSIONALITY mth)) THEN
    ASM_REWRITE_TAC[] THEN X_GEN_TAC `m:A` THEN DISCH_TAC THEN
    USE_THEN "wc" (fun th -> MP_TAC(SPEC `m:A` th)) THEN
    ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    USE_THEN "wc'" (fun th -> MP_TAC(SPEC `m:A` th)) THEN
    ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN(fun a -> DISCH_THEN(fun b -> ACCEPT_TAC(TRANS b (SYM a))));
    (* ---- per-b characterization ---- *)
    X_GEN_TAC `b:A` THEN STRIP_TAC THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`] ZF_SEPARATION) THEN
    ASM_REWRITE_TAC[] THEN
    DISCH_THEN(MP_TAC o SPECL
      [`apply_form 5 2 11`; `2`; `(11 |-> (b:A)) v`; `(v:num->A) 6`]) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[] THEN MATCH_MP_TAC VALUATION_VALMOD THEN
      ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    DISCH_THEN(X_CHOOSE_THEN `W:A`
               (CONJUNCTS_THEN2 ASSUME_TAC (LABEL_TAC "wsep"))) THEN
    SUBGOAL_THEN
     `!m:A. m IN D ==> (E m W <=> E m (v 6) /\ eapply D E (v 5) m b)`
     (LABEL_TAC "wd") THENL
     [X_GEN_TAC `m:A` THEN DISCH_TAC THEN
      USE_THEN "wsep" (MP_TAC o SPEC `m:A`) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
      SUBGOAL_THEN `valuation D ((2 |-> (m:A)) ((11 |-> (b:A)) v))`
        ASSUME_TAC THENL
        [REPEAT(MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[]);
         ALL_TAC] THEN
      ASM_SIMP_TAC[HOLDS_APPLY_FORM] THEN REWRITE_TAC[VALMOD; ARITH_EQ];
      ALL_TAC] THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `b:A`; `W:A`]
           EOPAIR_EXISTS) THEN
    ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `out:A`) THEN
    SUBGOAL_THEN `(out:A) IN D` ASSUME_TAC THENL
     [ASM_MESON_TAC[EOPAIR_IN]; ALL_TAC] THEN
    EXISTS_TAC `W:A` THEN
    CONJ_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    CONJ_TAC THENL [USE_THEN "wd" ACCEPT_TAC; ALL_TAC] THEN
    REWRITE_TAC[eapply] THEN EXISTS_TAC `out:A` THEN
    CONJ_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    USE_THEN "ffmem" (fun th -> MP_TAC(SPEC `out:A` th)) THEN
    ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    EXISTS_TAC `b:A` THEN ASM_REWRITE_TAC[] THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `v:num->A`; `b:A`; `out:A`]
           HOLDS_SFIB) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    EXISTS_TAC `W:A` THEN
    REPEAT CONJ_TAC THENL
     [FIRST_ASSUM ACCEPT_TAC; USE_THEN "wd" ACCEPT_TAC;
      FIRST_ASSUM ACCEPT_TAC]]);;

(* -- EFAM_WUN (GENERIC, reusable): given ff IN D whose members are all    *)
(*    a-indexed pairs <b,z> (one-directional hyp), build the union of the  *)
(*    ff-values with exactly the EGEN_UNION_CARD_LE union characterization.*)
let EFAM_WUN = prove
 (`!D (E:A->A->bool) a ff.
     model D E ZF_AX /\ a IN D /\ ff IN D /\
     (!p. p IN D /\ E p ff
          ==> ?b z. b IN D /\ z IN D /\ E b a /\ eopair D E b z p)
     ==> ?wun. wun IN D /\
               !u. u IN D
                   ==> (E u wun <=>
                        ?b z. b IN D /\ z IN D /\
                              E b a /\ eapply D E ff b z /\ E u z)`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "zf aD ffD absh" THEN
  SUBGOAL_THEN
   `!w:A. w IN D
          ==> (einran (D:A->bool) (E:A->A->bool) w ff <=>
               ?b:A. b IN D /\ E b a /\ eapply D E ff b w)`
   (LABEL_TAC "rc") THENL
   [X_GEN_TAC `w:A` THEN DISCH_TAC THEN EQ_TAC THENL
     [REWRITE_TAC[einran] THEN
      DISCH_THEN(X_CHOOSE_THEN `pr:A`
                 (X_CHOOSE_THEN `oo:A` STRIP_ASSUME_TAC)) THEN
      USE_THEN "absh" (MP_TAC o SPEC `pr:A`) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(X_CHOOSE_THEN `b:A`
                 (X_CHOOSE_THEN `z:A` STRIP_ASSUME_TAC)) THEN
      SUBGOAL_THEN `(oo:A) = b /\ (w:A) = z`
        (CONJUNCTS_THEN SUBST_ALL_TAC) THENL
        [MATCH_MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `oo:A`; `w:A`; `b:A`;
          `z:A`; `pr:A`] EOPAIR_INJ) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
      EXISTS_TAC `b:A` THEN ASM_REWRITE_TAC[] THEN
      REWRITE_TAC[eapply] THEN EXISTS_TAC `pr:A` THEN ASM_REWRITE_TAC[];
      DISCH_THEN(X_CHOOSE_THEN `b:A` STRIP_ASSUME_TAC) THEN
      SUBGOAL_THEN `?p:A. eopair (D:A->bool) (E:A->A->bool) b w p /\ E p ff`
       (X_CHOOSE_THEN `p:A` STRIP_ASSUME_TAC) THENL
       [UNDISCH_TAC `eapply (D:A->bool) (E:A->A->bool) ff b w` THEN
        REWRITE_TAC[eapply]; ALL_TAC] THEN
      SUBGOAL_THEN `(p:A) IN D` ASSUME_TAC THENL
       [ASM_MESON_TAC[EOPAIR_IN]; ALL_TAC] THEN
      REWRITE_TAC[einran] THEN MAP_EVERY EXISTS_TAC [`p:A`; `b:A`] THEN
      ASM_REWRITE_TAC[]]; ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `ff:A`] EINRAN_SET_EXISTS) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `r:A`
    (CONJUNCTS_THEN2 ASSUME_TAC (LABEL_TAC "rmem"))) THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `r:A`] EUNION_EXISTS) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `wun:A`
    (CONJUNCTS_THEN2 ASSUME_TAC (LABEL_TAC "wmem") o
     REWRITE_RULE[eunion])) THEN
  EXISTS_TAC `wun:A` THEN ASM_REWRITE_TAC[] THEN
  X_GEN_TAC `u:A` THEN DISCH_TAC THEN
  USE_THEN "wmem" (fun th -> MP_TAC(SPEC `u:A` th)) THEN
  ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN EQ_TAC THENL
   [DISCH_THEN(X_CHOOSE_THEN `s:A` STRIP_ASSUME_TAC) THEN
    SUBGOAL_THEN
      `?b:A. b IN D /\ E b a /\ eapply (D:A->bool) (E:A->A->bool) ff b s`
      (X_CHOOSE_THEN `b:A` STRIP_ASSUME_TAC) THENL
     [USE_THEN "rc" (fun th -> MP_TAC(SPEC `s:A` th)) THEN
      ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[GSYM th]) THEN
      USE_THEN "rmem" (fun th -> MP_TAC(SPEC `s:A` th)) THEN
      ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[GSYM th]) THEN
      FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    MAP_EVERY EXISTS_TAC [`b:A`; `s:A`] THEN ASM_REWRITE_TAC[];
    DISCH_THEN(X_CHOOSE_THEN `b:A` (X_CHOOSE_THEN `z:A` STRIP_ASSUME_TAC)) THEN
    EXISTS_TAC `z:A` THEN
    CONJ_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    CONJ_TAC THENL
     [USE_THEN "rmem"
      (fun th -> ONCE_REWRITE_TAC[MATCH_MP th (ASSUME `(z:A) IN D`)]) THEN
      USE_THEN "rc"
        (fun th -> ONCE_REWRITE_TAC[MATCH_MP th (ASSUME `(z:A) IN D`)]) THEN
        EXISTS_TAC `b:A` THEN ASM_REWRITE_TAC[];
      FIRST_ASSUM ACCEPT_TAC]]);;

(* ==================================================================== *)
(* F6.1b L1: EUNCOUNTABLE_FIBER_RAW.                                     *)
(* Pigeonhole: an uncountable X, split by g:X->om into om-many fibers,   *)
(* has an uncountable fiber.  Contrapositive of EGEN_UNION_CARD_LE with   *)
(* a=kk=om, ea=identity om>->om, ya=X, wun=X (by extensionality).         *)
(* Consumes the F6.1b size-fiber kit (ESFIB_FAMILY, EFAM_WUN, HOLDS_SFIB).*)
(* ==================================================================== *)

let EUNCOUNTABLE_FIBER_RAW = prove
 (`!D (E:A->A->bool) om g X.
     model D E ZF_AX /\ (!u. u IN D ==> elmem D E u) /\
     eomega D E om /\ X IN D /\ g IN D /\
     ~(?e. einj D E e X om) /\
     (!m. m IN D /\ E m X ==> ?n. n IN D /\ E n om /\ eapply D E g m n)
     ==> ?n W. n IN D /\ E n om /\ W IN D /\
               (!m. m IN D ==> (E m W <=> E m X /\ eapply D E g m n)) /\
               ~(?e. einj D E e W om)`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "zf lm omom XD gD noinj gtot" THEN
  (* --- om IN D, eordinal om, ecardinal om --- *)
  SUBGOAL_THEN `(om:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[EOMEGA_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `eordinal D (E:A->A->bool) om` (LABEL_TAC "omord") THENL
   [ASM_MESON_TAC[EOMEGA_ORDINAL]; ALL_TAC] THEN
  SUBGOAL_THEN `ecardinal D (E:A->A->bool) om` (LABEL_TAC "omcard") THENL
   [REWRITE_TAC[ecardinal] THEN MATCH_MP_TAC EOMEGA_CARDINAL THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* --- identity injection om >-> om --- *)
  SUBGOAL_THEN `?ea:A. einj D (E:A->A->bool) ea om om`
   (X_CHOOSE_THEN `ea:A` (LABEL_TAC "eainj")) THENL
   [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `om:A`] EBIJ_ID) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(X_CHOOSE_TAC `h:A`) THEN EXISTS_TAC `h:A` THEN
    MATCH_MP_TAC EBIJ_EINJ THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  (* --- valuation vv with vv 5 = g, vv 6 = X --- *)
  ABBREV_TAC `vv = (5 |-> (g:A))((6 |-> (X:A))(\n:num. X))` THEN
  SUBGOAL_THEN `valuation D (vv:num->A)` ASSUME_TAC THENL
   [EXPAND_TAC "vv" THEN
    REPEAT(MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[]) THEN
    REWRITE_TAC[valuation] THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(vv:num->A) 5 = g /\ (vv:num->A) 6 = X`
   (CONJUNCTS_THEN2 (LABEL_TAC "v5") (LABEL_TAC "v6")) THENL
   [EXPAND_TAC "vv" THEN REWRITE_TAC[VALMOD] THEN
    CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN REWRITE_TAC[]; ALL_TAC] THEN
  (* --- ff = size-fiber family via ESFIB_FAMILY --- *)
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `vv:num->A`; `om:A`]
         ESFIB_FAMILY) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  INTRO_TAC "@ff. ffD ffmem sv perb" THEN
  (* --- wun = union of ff-values via EFAM_WUN --- *)
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `om:A`; `ff:A`] EFAM_WUN) THEN
  ANTS_TAC THENL
   [CONJ_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    CONJ_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    CONJ_TAC THENL [USE_THEN "ffD" ACCEPT_TAC; ALL_TAC] THEN
    X_GEN_TAC `p:A` THEN STRIP_TAC THEN
    USE_THEN "ffmem" (fun th -> MP_TAC(SPEC `p:A` th)) THEN
    ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN(fun iff -> FIRST_ASSUM(fun eff -> MP_TAC(EQ_MP iff eff))) THEN
    DISCH_THEN(X_CHOOSE_THEN `u:A` (CONJUNCTS_THEN2 ASSUME_TAC
      (CONJUNCTS_THEN2 (LABEL_TAC "euom") (LABEL_TAC "hp")))) THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `vv:num->A`; `u:A`; `p:A`]
      HOLDS_SFIB) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> USE_THEN "hp" (fun h -> MP_TAC(EQ_MP th h))) THEN
    DISCH_THEN(X_CHOOSE_THEN `W:A` (CONJUNCTS_THEN2 (LABEL_TAC "WD")
      (CONJUNCTS_THEN2 (LABEL_TAC "Wchar") (LABEL_TAC "eop")))) THEN
    MAP_EVERY EXISTS_TAC [`u:A`; `W:A`] THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `wun:A` (CONJUNCTS_THEN2 (LABEL_TAC "wunD")
    (LABEL_TAC "wunmem"))) THEN
  (* --- wun = X by extensionality --- *)
  SUBGOAL_THEN `wun:A = X` SUBST_ALL_TAC THENL
   [FIRST_ASSUM(fun mth -> MATCH_MP_TAC(MATCH_MP ZF_EXTENSIONALITY mth)) THEN
    ASM_REWRITE_TAC[] THEN X_GEN_TAC `t:A` THEN DISCH_TAC THEN
    USE_THEN "wunmem" (fun th -> MP_TAC(SPEC `t:A` th)) THEN
    ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN EQ_TAC THENL
     [(* wun-side ==> X *)
      DISCH_THEN(X_CHOOSE_THEN `b:A`
                 (X_CHOOSE_THEN `z:A` STRIP_ASSUME_TAC)) THEN
      USE_THEN "perb" (fun th -> MP_TAC(SPEC `b:A` th)) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(X_CHOOSE_THEN `Wb:A` (CONJUNCTS_THEN2 (LABEL_TAC "WbD")
        (CONJUNCTS_THEN2 (LABEL_TAC "Wbchar") (LABEL_TAC "ffbWb")))) THEN
      SUBGOAL_THEN `(z:A) = Wb` SUBST_ALL_TAC THENL
       [USE_THEN "sv" (MP_TAC o SPECL [`b:A`; `z:A`; `Wb:A`]) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC];
        ALL_TAC] THEN
      USE_THEN "Wbchar" (fun th -> MP_TAC(SPEC `t:A` th)) THEN
      ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
      USE_THEN "v6" (fun th -> REWRITE_TAC[th]) THEN ASM_MESON_TAC[];
      (* X ==> wun-side *)
      DISCH_TAC THEN
      USE_THEN "gtot" (fun th -> MP_TAC(SPEC `t:A` th)) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(X_CHOOSE_THEN `n:A` STRIP_ASSUME_TAC) THEN
      USE_THEN "perb" (fun th -> MP_TAC(SPEC `n:A` th)) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(X_CHOOSE_THEN `Wn:A` (CONJUNCTS_THEN2 (LABEL_TAC "WnD")
        (CONJUNCTS_THEN2 (LABEL_TAC "Wnchar") (LABEL_TAC "ffnWn")))) THEN
      MAP_EVERY EXISTS_TAC [`n:A`; `Wn:A`] THEN ASM_REWRITE_TAC[] THEN
      USE_THEN "Wnchar" (fun th -> MP_TAC(SPEC `t:A` th)) THEN
      ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
      USE_THEN "v6"
        (fun t6 -> USE_THEN "v5" (fun t5 -> REWRITE_TAC[t6; t5])) THEN
        ASM_MESON_TAC[]];
    ALL_TAC] THEN
  (* --- contradiction: if every fiber countable, X countable --- *)
  MATCH_MP_TAC(TAUT `(~P ==> F) ==> P`) THEN
  DISCH_THEN(MP_TAC o REWRITE_RULE[NOT_EXISTS_THM;
    TAUT `~(a /\ b /\ c /\ d /\ ~e) <=> (a /\ b /\ c /\ d ==> e)`]) THEN
  DISCH_THEN(LABEL_TAC "allcnt") THEN
  (* --- per-b clause for EGEN_UNION_CARD_LE --- *)
  SUBGOAL_THEN
   `!b:A. b IN D /\ E b om
      ==> ?z. z IN D /\ eapply D E ff b z /\
              (!u. u IN D /\ E u z ==> E u X) /\
              (?e. e IN D /\ einj D (E:A->A->bool) e z om)`
   (LABEL_TAC "egenperb") THENL
   [X_GEN_TAC `b:A` THEN STRIP_TAC THEN
    USE_THEN "perb" (fun th -> MP_TAC(SPEC `b:A` th)) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(X_CHOOSE_THEN `Wb:A` (CONJUNCTS_THEN2 (LABEL_TAC "WbD")
      (CONJUNCTS_THEN2 (LABEL_TAC "Wbchar") (LABEL_TAC "ffbWb")))) THEN
    EXISTS_TAC `Wb:A` THEN ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
     [X_GEN_TAC `u:A` THEN STRIP_TAC THEN
      USE_THEN "Wbchar" (fun th -> MP_TAC(SPEC `u:A` th)) THEN
      ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
      USE_THEN "v6" (fun th -> REWRITE_TAC[th]) THEN ASM_MESON_TAC[];
      USE_THEN "allcnt" (MP_TAC o SPECL [`b:A`; `Wb:A`]) THEN
      ANTS_TAC THENL
       [ASM_REWRITE_TAC[] THEN X_GEN_TAC `m:A` THEN DISCH_TAC THEN
        USE_THEN "Wbchar" (fun th -> MP_TAC(SPEC `m:A` th)) THEN
        ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
        USE_THEN "v6" (fun t6 -> USE_THEN "v5" (fun t5 ->
          REWRITE_TAC[t6; t5]));
        DISCH_THEN(X_CHOOSE_THEN `einjw:A` (fun th ->
          EXISTS_TAC `einjw:A` THEN CONJ_TAC THENL
           [ACCEPT_TAC(CONJUNCT1(REWRITE_RULE[einj] th)); ACCEPT_TAC th]))]];
    ALL_TAC] THEN
  (* --- apply EGEN_UNION_CARD_LE (a=kk=om, ea=id, ya=X, wun=X) --- *)
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `om:A`; `om:A`; `om:A`;
     `ea:A`; `X:A`; `ff:A`; `X:A`] EGEN_UNION_CARD_LE) THEN
  ANTS_TAC THENL
   [CONJ_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    CONJ_TAC THENL [USE_THEN "lm" ACCEPT_TAC; ALL_TAC] THEN
    CONJ_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    CONJ_TAC THENL [USE_THEN "omcard" ACCEPT_TAC; ALL_TAC] THEN
    CONJ_TAC THENL [DISJ2_TAC THEN REFL_TAC; ALL_TAC] THEN
    CONJ_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    CONJ_TAC THENL [USE_THEN "omord" ACCEPT_TAC; ALL_TAC] THEN
    CONJ_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    CONJ_TAC THENL [USE_THEN "eainj" ACCEPT_TAC; ALL_TAC] THEN
    CONJ_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    CONJ_TAC THENL [USE_THEN "ffD" ACCEPT_TAC; ALL_TAC] THEN
    CONJ_TAC THENL [USE_THEN "sv" ACCEPT_TAC; ALL_TAC] THEN
    CONJ_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    CONJ_TAC THENL [USE_THEN "wunmem" ACCEPT_TAC; ALL_TAC] THEN
    USE_THEN "egenperb" ACCEPT_TAC;
    ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_TAC `e0:A`) THEN
  UNDISCH_TAC `~(?e:A. einj D (E:A->A->bool) e X om)` THEN
  ASM_MESON_TAC[]);;

(* ==================================================================== *)
(* F6.4 prerequisites -- two additions to the F2.8 emb family (edownset/ *)
(* eintcl).  e(p) = eintcl(edownset p) is the canonical                  *)
(* regular-open embedding of a condition p into the RO Boolean algebra   *)
(* B = eroset.                                                           *)
(*                                                                        *)
(*   EMB_INTO_OPEN : p IN u, u regular-open (u IN B) ==> e(p) SUBSET u.   *)
(*     Density direction of F6.4's ccc transfer B -> P: downset p SUBSET  *)
(*     u (u open, p IN u), then EINTCL_MIN (u regular) => e(p) SUBSET u.  *)
(*   EMB_COMPAT_MEET : p, q compatible in P ==> e(p) INTER e(q) inhabited.*)
(*     Incompatibility bridge: contrapositively e(p) INTER e(q) SUBSET    *)
(*     bot forces p # q.  Repackage of EMB_MEET_FWD via ecompat's common  *)
(*     lower bound.                                                       *)
(* ==================================================================== *)

let EMB_INTO_OPEN = prove
 (`!D (E:A->A->bool) P leqp p dp ep u.
      model D E ZF_AX /\ eleqp D E P leqp /\
      p IN D /\ u IN D /\ E p u /\
      eopen D E leqp u /\ ereg D E P leqp u /\
      edownset D E P leqp p dp /\ eintcl D E P leqp dp ep
      ==> esubset D E ep u`,
  REPEAT STRIP_TAC THEN
  MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`P:A`;`leqp:A`;`dp:A`;`ep:A`;`u:A`]
    EINTCL_MIN) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[] THEN
    REWRITE_TAC[esubset] THEN X_GEN_TAC `q:A` THEN STRIP_TAC THEN
    UNDISCH_TAC `edownset D (E:A->A->bool) P leqp p dp` THEN
    REWRITE_TAC[edownset] THEN
    DISCH_THEN(MP_TAC o SPEC `q:A` o CONJUNCT2) THEN
    ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN(fun th -> MP_TAC(EQ_MP th (ASSUME `(E:A->A->bool) q dp`))) THEN
    DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC ASSUME_TAC) THEN
    UNDISCH_TAC `eopen D (E:A->A->bool) leqp u` THEN REWRITE_TAC[eopen] THEN
    DISCH_THEN(MATCH_MP_TAC o SPECL [`p:A`;`q:A`]) THEN
    ASM_REWRITE_TAC[];
    DISCH_THEN ACCEPT_TAC]);;

let EMB_COMPAT_MEET = prove
 (`!D (E:A->A->bool) P leqp p q dp ep dq eq2.
      model D E ZF_AX /\ eleqp D E P leqp /\ p IN D /\ q IN D /\
      edownset D E P leqp p dp /\ eintcl D E P leqp dp ep /\
      edownset D E P leqp q dq /\ eintcl D E P leqp dq eq2 /\
      ecompat D E P leqp p q
      ==> ?r. r IN D /\ E r ep /\ E r eq2`,
  REPEAT STRIP_TAC THEN
  UNDISCH_TAC `ecompat D (E:A->A->bool) P leqp p q` THEN
  REWRITE_TAC[ecompat] THEN
  DISCH_THEN(X_CHOOSE_THEN `w:A` STRIP_ASSUME_TAC) THEN
  EXISTS_TAC `w:A` THEN ASM_REWRITE_TAC[] THEN
  MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`P:A`;`leqp:A`;`w:A`;`p:A`;`q:A`;
    `dp:A`;`ep:A`;`dq:A`;`eq2:A`] EMB_MEET_FWD) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC]);;

(* ==================================================================== *)
(* EIMG_FAMILY (GENERIC image-family builder).  Abstracts ESFIB_FAMILY  *)
(* over an arbitrary graph form-code g with input slot ix,               *)
(* output slot ox.  Given                                               *)
(*   FUNC*  : for each u IN a, EXACTLY one out satisfies g(u,out)        *)
(*            (existence + uniqueness -- "the graph is a total function" *)
(*            on a; ZF_REPLACEMENT's own antecedent gives uniqueness     *)
(*            only, so existence is supplied here);                      *)
(*   HFAITH : every output out at index u is an index-headed pair <u,z>, *)
(* builds ff = { <u, val(u)> : u IN a } IN D via ZF_REPLACEMENT and      *)
(* delivers: (1) ff IN D; (2) the raw replacement membership; (3) head- *)
(* faithfulness of ff (every member is an a-indexed pair == EFAM_WUN's   *)
(* "absh" hypothesis); (4) single-valuedness of the eapply               *)
(* graph; (5) a per-index existence characterization (index b |-> its    *)
(* output pair out, value z, with eapply ff b z).                        *)
(*                                                                       *)
(* This reusable foundation has four consumers, each of which              *)
(* instantiates g/ix/ox to its own map -- F6.4 selection-image u|->p_u,   *)
(* F6.3 N1 domain-image, F6.3 N3 restriction-image, F6.2 s1 -- while the *)
(* ff-IN-D / single-valued / per-index scaffolding is proved once here.  *)
(* Interface is choice-mechanism-independent (only g differs).           *)
(* ==================================================================== *)

let EIMG_FAMILY = prove
 (`!D (E:A->A->bool) g ix ox v a.
     model D E ZF_AX /\ valuation D v /\ a IN D /\ ~(ix = ox) /\
     (!u. u IN D /\ E u a
          ==> ?out. out IN D /\
                    holds D E ((ox |-> out) ((ix |-> u) v)) g /\
                    (!out'. out' IN D /\
                            holds D E ((ox |-> out') ((ix |-> u) v)) g
                            ==> out' = out)) /\
     (!u out. u IN D /\ E u a /\ out IN D /\
              holds D E ((ox |-> out) ((ix |-> u) v)) g
              ==> ?z. z IN D /\ eopair D E u z out)
     ==> ?ff. ff IN D /\
              (!w. w IN D
                   ==> (E w ff <=>
                        ?u. u IN D /\ E u a /\
                            holds D E ((ox |-> w) ((ix |-> u) v)) g)) /\
              (!q. q IN D /\ E q ff
                   ==> ?b z. b IN D /\ z IN D /\ E b a /\ eopair D E b z q) /\
              (!n z z'. n IN D /\ z IN D /\ z' IN D /\
                        eapply D E ff n z /\ eapply D E ff n z' ==> z = z') /\
              (!b. b IN D /\ E b a
                   ==> ?out z. out IN D /\ z IN D /\
                               holds D E ((ox |-> out) ((ix |-> b) v)) g /\
                               eopair D E b z out /\
                               eapply D E ff b z)`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "zf val aD ixneox func hf" THEN
  (* ---- obtain ff from ZF_REPLACEMENT ---- *)
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`] ZF_REPLACEMENT) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(MP_TAC o SPECL
             [`g:form`; `ix:num`; `ox:num`; `v:num->A`; `a:A`]) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[] THEN
    X_GEN_TAC `u:A` THEN STRIP_TAC THEN
    USE_THEN "func" (MP_TAC o SPEC `u:A`) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(X_CHOOSE_THEN `out:A` STRIP_ASSUME_TAC) THEN
    EXISTS_TAC `out:A` THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `ff:A`
    (CONJUNCTS_THEN2 (LABEL_TAC "ffD") (LABEL_TAC "ffmem"))) THEN
  EXISTS_TAC `ff:A` THEN REPEAT CONJ_TAC THENL
   [(* ---- 1: ff IN D ---- *)
    USE_THEN "ffD" ACCEPT_TAC;
    (* ---- 2: membership ---- *)
    USE_THEN "ffmem" ACCEPT_TAC;
    (* ---- 3: head-faithfulness (absh for EFAM_WUN) ---- *)
    X_GEN_TAC `q:A` THEN STRIP_TAC THEN
    USE_THEN "ffmem" (MP_TAC o SPEC `q:A`) THEN
    ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN(fun th -> MP_TAC(EQ_MP th (ASSUME `(E:A->A->bool) q ff`))) THEN
    DISCH_THEN(X_CHOOSE_THEN `u:A` STRIP_ASSUME_TAC) THEN
    USE_THEN "hf" (MP_TAC o SPECL [`u:A`; `q:A`]) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(X_CHOOSE_THEN `z:A` STRIP_ASSUME_TAC) THEN
    MAP_EVERY EXISTS_TAC [`u:A`; `z:A`] THEN ASM_REWRITE_TAC[];
    (* ---- 4: single-valued ---- *)
    MAP_EVERY X_GEN_TAC [`n:A`; `z:A`; `z':A`] THEN
    REWRITE_TAC[eapply] THEN
    DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC (CONJUNCTS_THEN2 ASSUME_TAC
      (CONJUNCTS_THEN2 ASSUME_TAC (CONJUNCTS_THEN2
        (X_CHOOSE_THEN `q:A` STRIP_ASSUME_TAC)
        (X_CHOOSE_THEN `q':A` STRIP_ASSUME_TAC))))) THEN
    SUBGOAL_THEN `(q:A) IN D` ASSUME_TAC THENL
     [ASM_MESON_TAC[EOPAIR_IN]; ALL_TAC] THEN
    SUBGOAL_THEN `(q':A) IN D` ASSUME_TAC THENL
     [ASM_MESON_TAC[EOPAIR_IN]; ALL_TAC] THEN
    (* q side: recover index u with u = n *)
    SUBGOAL_THEN
     `?u. u IN D /\ E u a /\ holds D E ((ox |-> (q:A)) ((ix |-> u) v)) g`
     (X_CHOOSE_THEN `u:A` STRIP_ASSUME_TAC) THENL
     [USE_THEN "ffmem" (fun bmem ->
        ONCE_REWRITE_TAC[GSYM(MATCH_MP bmem (ASSUME `(q:A) IN D`))]) THEN
      FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    USE_THEN "hf" (MP_TAC o SPECL [`u:A`; `q:A`]) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(X_CHOOSE_THEN `zz:A` STRIP_ASSUME_TAC) THEN
    SUBGOAL_THEN `(u:A) = n /\ (zz:A) = z` (CONJUNCTS_THEN SUBST_ALL_TAC) THENL
     [MATCH_MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `u:A`; `zz:A`; `n:A`;
        `z:A`; `q:A`] EOPAIR_INJ) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    (* q' side: recover index u' with u' = n *)
    SUBGOAL_THEN
     `?u'. u' IN D /\ E u' a /\ holds D E ((ox |-> (q':A)) ((ix |-> u') v)) g`
     (X_CHOOSE_THEN `u':A` STRIP_ASSUME_TAC) THENL
     [USE_THEN "ffmem" (fun bmem ->
        ONCE_REWRITE_TAC[GSYM(MATCH_MP bmem (ASSUME `(q':A) IN D`))]) THEN
      FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    USE_THEN "hf" (MP_TAC o SPECL [`u':A`; `q':A`]) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(X_CHOOSE_THEN `zz':A` STRIP_ASSUME_TAC) THEN
    SUBGOAL_THEN `(u':A) = n /\ (zz':A) = z'`
      (CONJUNCTS_THEN SUBST_ALL_TAC) THENL
      [MATCH_MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `u':A`; `zz':A`; `n:A`;
        `z':A`; `q':A`] EOPAIR_INJ) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    (* both q, q' satisfy g at index n; FUNC* uniqueness => q = q' *)
    USE_THEN "func" (MP_TAC o SPEC `n:A`) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(X_CHOOSE_THEN `w:A` STRIP_ASSUME_TAC) THEN
    SUBGOAL_THEN `(q:A) = w /\ (q':A) = w` STRIP_ASSUME_TAC THENL
     [CONJ_TAC THEN FIRST_ASSUM MATCH_MP_TAC THEN ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    SUBGOAL_THEN `(q':A) = q` SUBST_ALL_TAC THENL
     [ASM_MESON_TAC[]; ALL_TAC] THEN
    ASM_MESON_TAC[EOPAIR_INJ];
    (* ---- 5: per-index characterization ---- *)
    X_GEN_TAC `b:A` THEN STRIP_TAC THEN
    USE_THEN "func" (MP_TAC o SPEC `b:A`) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(X_CHOOSE_THEN `out:A` STRIP_ASSUME_TAC) THEN
    USE_THEN "hf" (MP_TAC o SPECL [`b:A`; `out:A`]) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(X_CHOOSE_THEN `z:A` STRIP_ASSUME_TAC) THEN
    MAP_EVERY EXISTS_TAC [`out:A`; `z:A`] THEN ASM_REWRITE_TAC[] THEN
    REWRITE_TAC[eapply] THEN EXISTS_TAC `out:A` THEN ASM_REWRITE_TAC[] THEN
    USE_THEN "ffmem" (fun bmem ->
      REWRITE_TAC[MATCH_MP bmem (ASSUME `(out:A) IN D`)]) THEN
    EXISTS_TAC `b:A` THEN ASM_REWRITE_TAC[]]);;

(* ==================================================================== *)
(* F6.4: leastmem_form -- the definable selection form-code.             *)
(* "v0 is the (v2)-least member of the set v1."  This is the inner       *)
(* clause of chsel_form with the outer ?y family layer dropped:          *)
(* select the ra-least element of a SINGLE set v1 directly, rather than  *)
(* of a member of a family.  Slots match chsel_form (result=0, set=1,    *)
(* relation=2, bound=6) so it threads through ZF_REPLACEMENT exactly as  *)
(* ELMEM_CHOICE threads chsel_form.                                      *)
(* ==================================================================== *)

let leastmem_form = new_definition
  `leastmem_form =
     (0 %% 1) &&
     !! 6 (((6 %% 1) && Not(Eq 6 0)) --> rel_form 2 0 6)`;;

let HOLDS_LEASTMEM_FORM = prove
 (`!D (E:A->A->bool) v.
        model D E ZF_AX /\ valuation D v
        ==> (holds D E v leastmem_form <=>
             E (v 0) (v 1) /\
             !z'. z' IN D /\ E z' (v 1) /\ ~(z' = v 0)
                  ==> erel D E (v 2) (v 0) z')`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `!x. (v:num->A) x IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[valuation]; ALL_TAC] THEN
  SUBGOAL_THEN
   `!z':A. z' IN D
      ==> (holds D E ((6 |-> z') v) (rel_form 2 0 6) <=>
           erel D (E:A->A->bool) (v 2) (v 0) z')`
  (LABEL_TAC "r1") THENL
   [REPEAT STRIP_TAC THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
      `(6 |-> (z':A)) v`; `2`; `0`; `6`]
      HOLDS_REL_FORM) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[VALUATION_VALMOD];
      ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    REWRITE_TAC[VALMOD] THEN
    CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN REWRITE_TAC[];
    ALL_TAC] THEN
  REWRITE_TAC[leastmem_form; HOLDS_AND; HOLDS_NOT; holds] THEN
  REWRITE_TAC[VALMOD] THEN
  CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN REWRITE_TAC[] THEN
  ASM_MESON_TAC[]);;

(* ==================================================================== *)
(* F6.4 lemmas 2-3: the ra-least member of a set is UNIQUE and EXISTS.    *)
(* Both project the wellorder-invariant packaging ELWOINVU_NORM:          *)
(*   clause 3 = asymmetry (=> uniqueness), clause 7 = least element of a  *)
(*   nonempty subset of the stage (=> existence).  These are exactly the  *)
(*   functionality and totality facts the ZF_REPLACEMENT image-family     *)
(*   builder (leastimg_form, next) needs for the selection u |-> p_u.     *)
(* ==================================================================== *)

(* Uniqueness: at most one ra-least member of u (asymmetry of the order). *)
let LEASTMEM_UNIQUE = prove
 (`!D (E:A->A->bool) a ra ya u m m'.
      model D E ZF_AX /\ a IN D /\ ra IN D /\ ya IN D /\
      elwoinvu D E a /\ elwou D E a ra /\ elstage D E a ya /\
      u IN D /\
      m IN D /\ E m u /\
      (!t. t IN D /\ E t u /\ ~(t = m) ==> erel D E ra m t) /\
      m' IN D /\ E m' u /\
      (!t. t IN D /\ E t u /\ ~(t = m') ==> erel D E ra m' t)
      ==> m = m'`,
  REPEAT STRIP_TAC THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `a:A`; `ra:A`; `ya:A`]
    ELWOINVU_NORM) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(ASSUME_TAC o CONJUNCT1 o CONJUNCT2 o CONJUNCT2) THEN
  ASM_MESON_TAC[]);;

(* Existence: a nonempty subset of the stage has a ra-least member.       *)
let LEASTMEM_EXISTS = prove
 (`!D (E:A->A->bool) a ra ya u.
      model D E ZF_AX /\ a IN D /\ ra IN D /\ ya IN D /\
      elwoinvu D E a /\ elwou D E a ra /\ elstage D E a ya /\
      u IN D /\ (!t. t IN D /\ E t u ==> E t ya) /\ (?t. t IN D /\ E t u)
      ==> ?m. m IN D /\ E m u /\
              !t. t IN D /\ E t u /\ ~(t = m) ==> erel D E ra m t`,
  REPEAT STRIP_TAC THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `a:A`; `ra:A`; `ya:A`]
    ELWOINVU_NORM) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(fun th ->
    MP_TAC(SPEC `u:A`
      (CONJUNCT2(CONJUNCT2(CONJUNCT2(CONJUNCT2(CONJUNCT2(CONJUNCT2
                th)))))))) THEN
  ANTS_TAC THENL [ASM_MESON_TAC[]; DISCH_THEN ACCEPT_TAC]);;

(* ==================================================================== *)
(* F6.4 leastimg: the SELECTION FAMILY  u |-> ra-least member of u.      *)
(* leastimg_form is the pairing graph  out = <u, least(u)>  built from   *)
(* leastmem_form (slot 0 = the least member, bound by ??) and            *)
(* opair_form 1 0 63 (out at slot 63 = <input u at 1, least at 0>).      *)
(* Slots: input u = 1, output pair = 63, wellorder relation = v 2.       *)
(* opair_form 1 0 63 has internal bound vars 64,65 (= MAX 1 0 63 + 1/2)  *)
(* and FV {0,1,63}: disjoint from leastmem_form's bound var 6.           *)
(*                                                                       *)
(* LEASTIMG_SELECT then instantiates the GENERIC image-family builder    *)
(* EIMG_FAMILY at g := leastimg_form, discharging its FUNC* (existence   *)
(* via LEASTMEM_EXISTS, uniqueness via LEASTMEM_UNIQUE + EOPAIR_UNIQUE)   *)
(* and HFAITH (every output is an index-headed pair) obligations, and    *)
(* delivers a single-valued set ff IN D assigning to each b IN a its     *)
(* (v 2)-least member.  This is the u |-> p_u selector F6.4 CCC_RO needs. *)
(* The wellorder relation is carried as v 2 throughout (caller sets      *)
(* v 2 := ra), so no v2/ra bridge is needed.                             *)
(* ==================================================================== *)

let leastimg_form = new_definition
  `leastimg_form = ?? 0 (leastmem_form && opair_form 1 0 63)`;;

let HOLDS_LEASTIMG = prove
 (`!D (E:A->A->bool) v u out.
        model D E ZF_AX /\ valuation D v /\ u IN D /\ out IN D
        ==> (holds D E ((63 |-> out) ((1 |-> u) v)) leastimg_form <=>
             ?m. m IN D /\ E m u /\
                 (!z'. z' IN D /\ E z' u /\ ~(z' = m)
                       ==> erel D E (v 2) m z') /\
                 eopair D E u m out)`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `valuation D ((63 |-> out) ((1 |-> (u:A)) v))` ASSUME_TAC THENL
   [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
  (* pointwise: leastmem_form clause at (0|->m)(...) *)
  SUBGOAL_THEN
   `!m:A. m IN D
          ==> (holds D E ((0 |-> m) ((63 |-> out) ((1 |-> (u:A)) v)))
                     leastmem_form <=>
               E m u /\
               (!z'. z' IN D /\ E z' u /\ ~(z' = m)
                     ==> erel D E (v 2) m z'))`
   (LABEL_TAC "lm") THENL
   [REPEAT STRIP_TAC THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
      `(0 |-> (m:A)) ((63 |-> out) ((1 |-> (u:A)) v))`]
                 HOLDS_LEASTMEM_FORM) THEN
    ANTS_TAC THENL [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    REWRITE_TAC[VALMOD] THEN
    CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN REWRITE_TAC[];
    ALL_TAC] THEN
  (* pointwise: opair_form 1 0 63 clause at (0|->m)(...) *)
  SUBGOAL_THEN
   `!m:A. m IN D
          ==> (holds D E ((0 |-> m) ((63 |-> out) ((1 |-> (u:A)) v)))
                     (opair_form 1 0 63) <=>
               eopair D E u m out)`
   (LABEL_TAC "op") THENL
   [REPEAT STRIP_TAC THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
      `(0 |-> (m:A)) ((63 |-> out) ((1 |-> (u:A)) v))`; `1`; `0`; `63`]
      HOLDS_OPAIR_FORM) THEN
    ANTS_TAC THENL [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    REWRITE_TAC[VALMOD] THEN
    CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN REWRITE_TAC[];
    ALL_TAC] THEN
  REWRITE_TAC[leastimg_form; HOLDS_EX; HOLDS_AND] THEN
  EQ_TAC THEN DISCH_THEN(X_CHOOSE_THEN `m:A` STRIP_ASSUME_TAC) THEN
  EXISTS_TAC `m:A` THEN ASM_MESON_TAC[]);;

(* ==================================================================== *)
(* F6.4 field and compatibility bridge.                                  *)
(* Two forced, packaging-independent sub-builders for CCC_RO:            *)
(*   (1) ebplus / EBPLUS_EXISTS : the forcing field B+ = B \ {bot}       *)
(*       (nonzero regular-open sets).  eccc is applied to (B+, inclB):    *)
(*       restricting the ecompat witness to B+ excludes the trivial       *)
(*       witness w = bot = empty, giving the genuine forcing notion of    *)
(*       compatibility ("common NONZERO lower bound").                    *)
(*   (2) RO_COMPAT_INTER : the compatibility bridge.  If u,v IN B share   *)
(*       a member r, then w = e(r) = eintcl(edownset r) is a common       *)
(*       nonzero regular-open lower bound (E r w /\ w SUBSET u /\ w SUB v).*)
(*       CONTRAPOSITIVE (the CCC_RO use): incompatible ==> u INTER v = 0. *)
(* ==================================================================== *)

let ebplus = new_definition
  `ebplus D (E:A->A->bool) B bp <=>
     bp IN D /\
     !u. u IN D ==> (E u bp <=> E u B /\ ~(eempty D E u))`;;

let EBPLUS_EXISTS = prove
 (`!D (E:A->A->bool) B.
      model D E ZF_AX /\ B IN D ==> ?bp. ebplus D E B bp`,
  REPEAT STRIP_TAC THEN
  MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`] ZF_SEPARATION) THEN
  ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  DISCH_THEN(MP_TAC o ISPECL
    [`?? 1 (1 %% 0)`; `0`; `(\n:num. B:A)`; `B:A`]) THEN
  ANTS_TAC THENL
   [CONJ_TAC THENL
     [REWRITE_TAC[valuation] THEN FIRST_ASSUM ACCEPT_TAC;
      FIRST_ASSUM ACCEPT_TAC];
    DISCH_THEN(X_CHOOSE_THEN `bp:A`
      (CONJUNCTS_THEN2 ASSUME_TAC (LABEL_TAC "sep")))] THEN
  EXISTS_TAC `bp:A` THEN REWRITE_TAC[ebplus] THEN
  CONJ_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  X_GEN_TAC `u:A` THEN DISCH_TAC THEN
  USE_THEN "sep" (MP_TAC o SPEC `u:A`) THEN
  ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  DISCH_THEN SUBST1_TAC THEN
  REWRITE_TAC[HOLDS_EX] THEN
  SUBGOAL_THEN
   `!b:A. holds D E ((1 |-> b) ((0 |-> (u:A)) (\n:num. B:A))) (1 %% 0) <=>
          E b u`
   (fun th -> REWRITE_TAC[th]) THENL
   [GEN_TAC THEN REWRITE_TAC[holds; VALMOD] THEN
    CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN REWRITE_TAC[];
    ALL_TAC] THEN
  REWRITE_TAC[eempty] THEN ASM_MESON_TAC[]);;

let RO_COMPAT_INTER = prove
 (`!D (E:A->A->bool) P leqp B u v r.
      model D E ZF_AX /\ eleqp D E P leqp /\ P IN D /\ eroset D E P leqp B /\
      u IN D /\ v IN D /\ r IN D /\ E u B /\ E v B /\ E r u /\ E r v
      ==> ?w. w IN D /\ E w B /\ E r w /\
              esubset D E w u /\ esubset D E w v`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `(leqp:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[eleqp]; ALL_TAC] THEN
  SUBGOAL_THEN
   `esubset D (E:A->A->bool) u P /\ eopen D E leqp u /\ ereg D E P leqp u`
   STRIP_ASSUME_TAC THENL
   [FIRST_ASSUM(MP_TAC o SPEC `u:A` o CONJUNCT2 o REWRITE_RULE[eroset]) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN
   `esubset D (E:A->A->bool) v P /\ eopen D E leqp v /\ ereg D E P leqp v`
   STRIP_ASSUME_TAC THENL
   [FIRST_ASSUM(MP_TAC o SPEC `v:A` o CONJUNCT2 o REWRITE_RULE[eroset]) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) (r:A) (P:A)` ASSUME_TAC THENL
   [ASM_MESON_TAC[esubset]; ALL_TAC] THEN
  MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`P:A`;`leqp:A`;`r:A`]
    EDOWNSET_EXISTS) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `dr:A` ASSUME_TAC) THEN
  SUBGOAL_THEN `(dr:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[edownset]; ALL_TAC] THEN
  MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`P:A`;`leqp:A`;`dr:A`]
    EINTCL_EXISTS) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `er:A` ASSUME_TAC) THEN
  SUBGOAL_THEN `(er:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[eintcl]; ALL_TAC] THEN
  EXISTS_TAC `er:A` THEN ASM_REWRITE_TAC[] THEN REPEAT CONJ_TAC THENL
   [MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`P:A`;`leqp:A`;`dr:A`;`er:A`;
      `B:A`] EINTCL_RO) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC];
    MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`P:A`;`leqp:A`;`r:A`;
      `dr:A`;`er:A`] EMB_NONBOT) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC];
    MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`P:A`;`leqp:A`;`r:A`;
      `dr:A`;`er:A`;`u:A`] EMB_INTO_OPEN) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC];
    MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`P:A`;`leqp:A`;`r:A`;
      `dr:A`;`er:A`;`v:A`] EMB_INTO_OPEN) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC]]);;

(* ==================================================================== *)
(* F6.4: EAPPLY_HEADFAITH and LEASTIMG_APPLY.                             *)
(* Bridges the selection stack (LEASTIMG_SELECT) to the                  *)
(* einj interface needed by the CCC_RO capstone.  LEASTIMG_SELECT hides  *)
(* head-faithfulness (EIMG_FAMILY clause 3), so an arbitrary application  *)
(* fact `eapply ff k t` cannot be turned into DOMAIN-membership `E k a`  *)
(* -- exactly what einj's conjunct 2 (`eapply f k t ==> E k x /\ E t y`) *)
(* and conjunct 5 (injectivity) require.  We (1) prove the generic       *)
(* domain-membership lemma from head-faithfulness, then (2) repackage the *)
(* selector, re-invoking EIMG_FAMILY so a SINGLE ff carries head-faith +  *)
(* per-index-least + single-valued, exposing the full einj-ready data.    *)
(* ==================================================================== *)

(* (1) Generic: head-faithfulness of a family ff over index set a gives   *)
(*     domain-membership for every application fact.                      *)
let EAPPLY_HEADFAITH = prove
 (`!D (E:A->A->bool) ff a k t.
      (!q. q IN D /\ E q ff
           ==> ?b z. b IN D /\ z IN D /\ E b a /\ eopair D E b z q) /\
      model D E ZF_AX /\ k IN D /\ t IN D /\ eapply D E ff k t
      ==> E k a`,
  REPEAT GEN_TAC THEN
  DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "hf") STRIP_ASSUME_TAC) THEN
  UNDISCH_TAC `eapply D (E:A->A->bool) ff k t` THEN REWRITE_TAC[eapply] THEN
  DISCH_THEN(X_CHOOSE_THEN `z:A` STRIP_ASSUME_TAC) THEN
  SUBGOAL_THEN `(z:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[EOPAIR_IN]; ALL_TAC] THEN
  USE_THEN "hf" (MP_TAC o SPEC `z:A`) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `b:A` (X_CHOOSE_THEN `z':A` STRIP_ASSUME_TAC)) THEN
  SUBGOAL_THEN `(k:A) = b /\ (t:A) = z'` STRIP_ASSUME_TAC THENL
   [MATCH_MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `k:A`; `t:A`; `b:A`;
      `z':A`; `z:A`] EOPAIR_INJ) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  ASM_MESON_TAC[]);;

(* (2) The einj-ready selector package.  Same hypotheses as LEASTIMG_SELECT *)
(*     and the same EIMG_FAMILY discharge at leastimg_form.                  *)
(*     is copied verbatim from LEASTIMG_SELECT.  New first output conjunct:  *)
(*     domain-membership + value-in-index for arbitrary applications.        *)
let LEASTIMG_APPLY = prove
 (`!D (E:A->A->bool) v a s ya.
        model D E ZF_AX /\ valuation D v /\
        s IN D /\ (v 2) IN D /\ ya IN D /\
        elwoinvu D E s /\ elwou D E s (v 2) /\ elstage D E s ya /\
        a IN D /\
        (!u. u IN D /\ E u a
             ==> (!t. t IN D /\ E t u ==> E t ya) /\
                 (?t. t IN D /\ E t u))
        ==> ?ff. ff IN D /\
                 (!k t. k IN D /\ t IN D /\ eapply D E ff k t
                        ==> E k a /\ E t k) /\
                 (!n z z'. n IN D /\ z IN D /\ z' IN D /\
                           eapply D E ff n z /\
                             eapply D E ff n z' ==> z = z') /\
                 (!b. b IN D /\ E b a
                      ==> ?m. m IN D /\ E m b /\ eapply D E ff b m /\
                              (!t. t IN D /\ E t b /\ ~(t = m)
                                   ==> erel D E (v 2) m t))`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `leastimg_form`; `1`; `63`;
    `v:num->A`; `a:A`] EIMG_FAMILY) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[ARITH_RULE `~(1 = 63)`] THEN CONJ_TAC THENL
     [(* ---- FUNC*: exactly one output per u IN a ---- *)
      X_GEN_TAC `u:A` THEN STRIP_TAC THEN
      SUBGOAL_THEN
       `(!t. t IN D /\ E t (u:A) ==> E t ya) /\ (?t:A. t IN D /\ E t u)`
       STRIP_ASSUME_TAC THENL
       [FIRST_ASSUM MATCH_MP_TAC THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
      MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `s:A`; `(v:num->A) 2`;
        `ya:A`; `u:A`] LEASTMEM_EXISTS) THEN
      ANTS_TAC THENL [ASM_MESON_TAC[]; ALL_TAC] THEN
      DISCH_THEN(X_CHOOSE_THEN `m:A` STRIP_ASSUME_TAC) THEN
      MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `u:A`; `m:A`]
        EOPAIR_EXISTS) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(X_CHOOSE_THEN `out:A` ASSUME_TAC) THEN
      SUBGOAL_THEN `(out:A) IN D` ASSUME_TAC THENL
       [ASM_MESON_TAC[EOPAIR_IN]; ALL_TAC] THEN
      EXISTS_TAC `out:A` THEN ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
       [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `v:num->A`; `u:A`;
          `out:A`] HOLDS_LEASTIMG) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
        DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
        EXISTS_TAC `m:A` THEN ASM_REWRITE_TAC[];
        X_GEN_TAC `out':A` THEN STRIP_TAC THEN
        MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `v:num->A`; `u:A`;
          `out':A`] HOLDS_LEASTIMG) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
        DISCH_THEN(fun th ->
          UNDISCH_TAC
            `holds D E ((63 |-> (out':A)) ((1 |-> (u:A)) v))
             leastimg_form` THEN
          REWRITE_TAC[th]) THEN
        DISCH_THEN(X_CHOOSE_THEN `m':A` STRIP_ASSUME_TAC) THEN
        SUBGOAL_THEN `(m:A) = m'` SUBST_ALL_TAC THENL
         [MATCH_MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `s:A`;
            `(v:num->A) 2`; `ya:A`; `u:A`; `m:A`; `m':A`] LEASTMEM_UNIQUE) THEN
          ASM_REWRITE_TAC[]; ALL_TAC] THEN
        MATCH_MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `u:A`; `m':A`;
          `out':A`; `out:A`] EOPAIR_UNIQUE) THEN
        ASM_REWRITE_TAC[]];
      (* ---- HFAITH: every output is an index-headed pair ---- *)
      MAP_EVERY X_GEN_TAC [`u:A`; `out:A`] THEN STRIP_TAC THEN
      MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `v:num->A`; `u:A`;
        `out:A`] HOLDS_LEASTIMG) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> POP_ASSUM MP_TAC THEN REWRITE_TAC[th]) THEN
      DISCH_THEN(X_CHOOSE_THEN `m:A` STRIP_ASSUME_TAC) THEN
      EXISTS_TAC `m:A` THEN ASM_REWRITE_TAC[]];
    (* ---- consume EIMG_FAMILY output ---- *)
    INTRO_TAC "@ff. ffD ffmem ffhf ffsv ffidx" THEN
    EXISTS_TAC `ff:A` THEN REPEAT CONJ_TAC THENL
     [(* ff IN D *)
      USE_THEN "ffD" ACCEPT_TAC;
      (* domain-membership + value-in-index *)
      MAP_EVERY X_GEN_TAC [`k:A`; `t:A`] THEN STRIP_TAC THEN
      SUBGOAL_THEN `(E:A->A->bool) (k:A) (a:A)` ASSUME_TAC THENL
       [MATCH_MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `ff:A`; `a:A`;
          `k:A`; `t:A`] EAPPLY_HEADFAITH) THEN
        CONJ_TAC THENL [USE_THEN "ffhf" ACCEPT_TAC; ASM_REWRITE_TAC[]];
        ALL_TAC] THEN
      CONJ_TAC THENL
       [FIRST_ASSUM ACCEPT_TAC;
        USE_THEN "ffidx" (MP_TAC o SPEC `k:A`) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
        DISCH_THEN(X_CHOOSE_THEN `out:A` (X_CHOOSE_THEN `zc:A`
          STRIP_ASSUME_TAC)) THEN
        MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `v:num->A`; `k:A`;
          `out:A`] HOLDS_LEASTIMG) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
        DISCH_THEN(fun th -> RULE_ASSUM_TAC(REWRITE_RULE[th])) THEN
        FIRST_X_ASSUM(X_CHOOSE_THEN `m:A` STRIP_ASSUME_TAC) THEN
        SUBGOAL_THEN `(zc:A) = m` SUBST_ALL_TAC THENL
         [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `k:A`; `zc:A`; `k:A`;
            `m:A`; `out:A`] EOPAIR_INJ) THEN ASM_REWRITE_TAC[] THEN
          ASM_MESON_TAC[]; ALL_TAC] THEN
        SUBGOAL_THEN `(t:A) = m` SUBST1_TAC THENL
         [USE_THEN "ffsv" (MP_TAC o SPECL [`k:A`; `t:A`; `m:A`]) THEN
          ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC];
          FIRST_ASSUM ACCEPT_TAC]];
      (* single-valued *)
      USE_THEN "ffsv" ACCEPT_TAC;
      (* per-index: recover the least member from ffidx + HOLDS_LEASTIMG *)
      X_GEN_TAC `b:A` THEN STRIP_TAC THEN
      USE_THEN "ffidx" (MP_TAC o SPEC `b:A`) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(X_CHOOSE_THEN `out:A` (X_CHOOSE_THEN `z:A`
        STRIP_ASSUME_TAC)) THEN
      MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `v:num->A`; `b:A`;
        `out:A`] HOLDS_LEASTIMG) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> RULE_ASSUM_TAC(REWRITE_RULE[th])) THEN
      FIRST_X_ASSUM(X_CHOOSE_THEN `m:A` STRIP_ASSUME_TAC) THEN
      SUBGOAL_THEN `(z:A) = m` SUBST_ALL_TAC THENL
       [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `b:A`; `z:A`; `b:A`;
          `m:A`; `out:A`] EOPAIR_INJ) THEN ASM_REWRITE_TAC[] THEN
        ASM_MESON_TAC[]; ALL_TAC] THEN
      EXISTS_TAC `m:A` THEN ASM_REWRITE_TAC[]]]);;

(* ==================================================================== *)
(* ==================== F6.4 CCC preservation ========================== *)
(* Cohen-poset ccc  ==>  ccc of its regular-open Boolean completion.     *)
(* Lemmas, in dependency order:                                          *)
(*   STAGE_PIN       -- pin the V=L wellorder data for an arbitrary set   *)
(*   CCC_RO_SELINJ   -- least-member selector injects B+-antichain -> P   *)
(*   IMG_INCOMPAT    -- P-compatible fibers force B-compatible sets       *)
(*   CCC_RO_IMGANTI  -- selector image of a B+-antichain is a P-antichain *)
(*   CCC_RO          -- capstone: eccc P leqp ==> eccc bp inclB           *)
(* ==================================================================== *)

(* ==================================================================== *)
(* F6.4: STAGE_PIN, used before the CCC_RO capstone.                     *)
(* Factors the stage-pinning prefix of ELMEM_CHOICE (godel_gch.ml)       *)
(* into a reusable lemma that EXPOSES the wellorder data instead of       *)
(* building chsel.  Given V=L (every set is an L-member) and any a IN D,  *)
(* returns the ordinal seed s, its L-stage ya (with a IN ya), the         *)
(* canonical wellorder ra of that stage, a valuation v with v 2 = ra, and *)
(* the two-level transitivity fact (members of members of a lie in ya).   *)
(* This is EXACTLY the packet CCC_RO_SELINJ / LEASTIMG_APPLY consume as    *)
(* their elwoinvu/elwou/elstage + subset-of-stage hypotheses.             *)
(* Depends: elmem, ELWOU_EXISTS, ELWOU_INVARIANT, ELSTAGE_TRANSITIVE,      *)
(*   etransitive/esubset, VALUATION_EXISTS/VALMOD/VALUATION_VALMOD.        *)
(* ==================================================================== *)

let STAGE_PIN = prove
 (`!D (E:A->A->bool) a.
      model D E ZF_AX /\ (!u. u IN D ==> elmem D E u) /\ a IN D
      ==> ?s ya ra v.
              valuation D v /\ (v:num->A) 2 = ra /\
              s IN D /\ ya IN D /\ ra IN D /\
              elwoinvu D E s /\ elwou D E s ra /\ elstage D E s ya /\
              (!u. u IN D /\ E u a
                   ==> (!t. t IN D /\ E t u ==> E t ya))`,
  REPEAT GEN_TAC THEN
  DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC (CONJUNCTS_THEN2
    (LABEL_TAC "vl") ASSUME_TAC)) THEN
  SUBGOAL_THEN `elmem D (E:A->A->bool) a` MP_TAC THENL
   [USE_THEN "vl" MATCH_MP_TAC THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  REWRITE_TAC[elmem] THEN
  DISCH_THEN(X_CHOOSE_THEN `s:A` (X_CHOOSE_THEN `ya:A`
    STRIP_ASSUME_TAC)) THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `s:A`] ELWOU_EXISTS) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `ra:A` STRIP_ASSUME_TAC) THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `s:A`] ELWOU_INVARIANT) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN DISCH_TAC THEN
  SUBGOAL_THEN `etransitive D (E:A->A->bool) ya` MP_TAC THENL
   [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `s:A`; `ya:A`]
      ELSTAGE_TRANSITIVE) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN ACCEPT_TAC; ALL_TAC] THEN
  REWRITE_TAC[etransitive; esubset] THEN
  DISCH_THEN(LABEL_TAC "ytr") THEN
  SUBGOAL_THEN `?v0:num->A. valuation D v0` (X_CHOOSE_TAC `v0:num->A`) THENL
   [ASM_MESON_TAC[VALUATION_EXISTS; MODEL_NONEMPTY]; ALL_TAC] THEN
  MAP_EVERY EXISTS_TAC [`s:A`; `ya:A`; `ra:A`; `(2 |-> (ra:A)) v0`] THEN
  ASM_REWRITE_TAC[] THEN
  SUBGOAL_THEN `valuation D ((2 |-> (ra:A)) v0)` ASSUME_TAC THENL
   [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
  ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
   [REWRITE_TAC[VALMOD] THEN CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN
    REWRITE_TAC[];
    (* two-level transitivity: u IN a, t IN u ==> t IN ya *)
    X_GEN_TAC `u:A` THEN STRIP_TAC THEN X_GEN_TAC `t:A` THEN STRIP_TAC THEN
    SUBGOAL_THEN `(E:A->A->bool) u ya` ASSUME_TAC THENL
     [USE_THEN "ytr" (fun th -> MP_TAC(SPEC `a:A` th)) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(MP_TAC o SPEC `u:A`) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN ACCEPT_TAC; ALL_TAC] THEN
    USE_THEN "ytr" (fun th -> MP_TAC(SPEC `u:A` th)) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(MP_TAC o SPEC `t:A`) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN ACCEPT_TAC]);;

(* ==================================================================== *)
(* F6.4 CCC_RO core: CCC_RO_SELINJ.                                      *)
(* "The least-member selector injects the B+-antichain into the poset    *)
(*  P."  Given an antichain a of (bp,inclB) [bp = B+ = B\{bot}], the      *)
(*  LEASTIMG_APPLY selector ff : u |-> p_u (v2-least member of u) is an   *)
(*  einj D E ff a P.  Injectivity is the crux: if ff(k)=ff(k')=t then t   *)
(*  is a shared member of k,k' IN B, so RO_COMPAT_INTER yields a common   *)
(*  NONZERO regular-open lower bound w (w IN B+, w SUBSET k, w SUBSET k'),*)
(*  i.e. k,k' are compatible in (bp,inclB) -- forcing k=k' by antichain.  *)
(*  Stage-pin data (v,s,ya with v2=ra the V=L wellorder) is passed as     *)
(*  hypotheses; the final eccc-transfer discharges them via ELMEM_CHOICE. *)
(* Depends: LEASTIMG_APPLY, RO_COMPAT_INTER, ebplus, EINCL_EREL_INTRO,    *)
(*   eroset/esubset/eempty/ecompat/eantichain.                            *)
(* ==================================================================== *)

let CCC_RO_SELINJ = prove
 (`!D (E:A->A->bool) P leqp B bp inclB v a s ya.
      model D E ZF_AX /\ valuation D v /\
      eleqp D E P leqp /\ P IN D /\ eroset D E P leqp B /\
      ebplus D E B bp /\ eincl D E B inclB /\
      s IN D /\ (v 2) IN D /\ ya IN D /\
      elwoinvu D E s /\ elwou D E s (v 2) /\ elstage D E s ya /\
      a IN D /\ eantichain D E bp inclB a /\
      (!u. u IN D /\ E u a
           ==> (!t. t IN D /\ E t u ==> E t ya) /\
               (?t. t IN D /\ E t u))
      ==> ?ff. einj D E ff a P /\
               (!b. b IN D /\ E b a
                    ==> ?m. m IN D /\ E m b /\ eapply D E ff b m)`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  (* -- antichain projections -- *)
  SUBGOAL_THEN `esubset D (E:A->A->bool) a bp` ASSUME_TAC THENL
   [FIRST_ASSUM(ACCEPT_TAC o CONJUNCT1 o CONJUNCT2 o REWRITE_RULE[eantichain]);
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!x y:A. x IN D /\ y IN D /\ E x a /\ E y a /\ ~(x = y)
            ==> ~(ecompat D E bp inclB x y)`
   (LABEL_TAC "anti") THENL
   [FIRST_ASSUM(ACCEPT_TAC o CONJUNCT2 o CONJUNCT2 o REWRITE_RULE[eantichain]);
    ALL_TAC] THEN
  (* -- members of a are nonempty regular-open subsets of P -- *)
  SUBGOAL_THEN
   `!u:A. u IN D /\ E u a
          ==> E u B /\ esubset D E u P /\ ~(eempty D E u)`
   (LABEL_TAC "aBP") THENL
   [X_GEN_TAC `u:A` THEN STRIP_TAC THEN
    SUBGOAL_THEN `(E:A->A->bool) (u:A) bp` ASSUME_TAC THENL
     [UNDISCH_TAC `esubset D (E:A->A->bool) a bp` THEN
      REWRITE_TAC[esubset] THEN
      DISCH_THEN MATCH_MP_TAC THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN `(E:A->A->bool) (u:A) B /\ ~(eempty D (E:A->A->bool) u)`
     STRIP_ASSUME_TAC THENL
     [FIRST_ASSUM(MP_TAC o SPEC `u:A` o CONJUNCT2 o REWRITE_RULE[ebplus]) THEN
      ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[GSYM th]) THEN FIRST_ASSUM ACCEPT_TAC;
      ALL_TAC] THEN
    ASM_REWRITE_TAC[] THEN
    FIRST_ASSUM(MP_TAC o SPEC `u:A` o CONJUNCT2 o REWRITE_RULE[eroset]) THEN
    ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    ASM_REWRITE_TAC[] THEN STRIP_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  (* -- obtain the selector ff -- *)
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `v:num->A`; `a:A`; `s:A`; `ya:A`]
    LEASTIMG_APPLY) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  INTRO_TAC "@ff. ffD ffdv ffsv ffidx" THEN
  EXISTS_TAC `ff:A` THEN CONJ_TAC THENL
   [(* ============ einj D E ff a P ============ *)
    REWRITE_TAC[einj] THEN REPEAT CONJ_TAC THENL
     [(* C1: ff IN D *)
      USE_THEN "ffD" ACCEPT_TAC;
      (* C2: eapply ff k t ==> E k a /\ E t P *)
      MAP_EVERY X_GEN_TAC [`k:A`; `t:A`] THEN STRIP_TAC THEN
      USE_THEN "ffdv" (MP_TAC o SPECL [`k:A`; `t:A`]) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN STRIP_TAC THEN
      CONJ_TAC THENL
       [FIRST_ASSUM ACCEPT_TAC;
        USE_THEN "aBP" (MP_TAC o SPEC `k:A`) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN STRIP_TAC THEN
        UNDISCH_TAC `esubset D (E:A->A->bool) k P` THEN
        REWRITE_TAC[esubset] THEN
        DISCH_THEN MATCH_MP_TAC THEN ASM_REWRITE_TAC[]];
      (* C3: total *)
      X_GEN_TAC `k:A` THEN STRIP_TAC THEN
      USE_THEN "ffidx" (MP_TAC o SPEC `k:A`) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(X_CHOOSE_THEN `m:A` STRIP_ASSUME_TAC) THEN
      EXISTS_TAC `m:A` THEN ASM_REWRITE_TAC[] THEN
      USE_THEN "aBP" (MP_TAC o SPEC `k:A`) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN STRIP_TAC THEN
      UNDISCH_TAC `esubset D (E:A->A->bool) k P` THEN REWRITE_TAC[esubset] THEN
      DISCH_THEN MATCH_MP_TAC THEN ASM_REWRITE_TAC[];
      (* C4: single-valued *)
      USE_THEN "ffsv" ACCEPT_TAC;
      (* C5: injective -- the crux, via RO_COMPAT_INTER *)
      MAP_EVERY X_GEN_TAC [`k:A`; `k':A`; `t:A`] THEN STRIP_TAC THEN
      ASM_CASES_TAC `(k:A) = k'` THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
      USE_THEN "ffdv" (MP_TAC o SPECL [`k:A`; `t:A`]) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN STRIP_TAC THEN
      USE_THEN "ffdv" (MP_TAC o SPECL [`k':A`; `t:A`]) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN STRIP_TAC THEN
      (* E k B, E k' B *)
      SUBGOAL_THEN `(E:A->A->bool) (k:A) B /\ E (k':A) B`
        STRIP_ASSUME_TAC THENL
        [CONJ_TAC THENL
         [USE_THEN "aBP" (MP_TAC o SPEC `k:A`);
          USE_THEN "aBP" (MP_TAC o SPEC `k':A`)] THEN
        (ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
         STRIP_TAC THEN FIRST_ASSUM ACCEPT_TAC);
        ALL_TAC] THEN
      (* common nonzero regular-open lower bound w *)
      MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `P:A`; `leqp:A`; `B:A`;
        `k:A`; `k':A`; `t:A`] RO_COMPAT_INTER) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(X_CHOOSE_THEN `w:A` STRIP_ASSUME_TAC) THEN
      (* w nonempty (t in w) hence w IN bp *)
      SUBGOAL_THEN `~(eempty D (E:A->A->bool) w)` ASSUME_TAC THENL
       [REWRITE_TAC[eempty] THEN ASM_MESON_TAC[]; ALL_TAC] THEN
      SUBGOAL_THEN `(E:A->A->bool) (w:A) bp` ASSUME_TAC THENL
       [FIRST_ASSUM(MP_TAC o SPEC `w:A` o CONJUNCT2 o
                    REWRITE_RULE[ebplus]) THEN
        ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
        DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN ASM_REWRITE_TAC[];
        ALL_TAC] THEN
      (* k,k' compatible in (bp,inclB) -- contradiction with anti *)
      SUBGOAL_THEN `ecompat D (E:A->A->bool) bp inclB k k'` ASSUME_TAC THENL
       [REWRITE_TAC[ecompat] THEN EXISTS_TAC `w:A` THEN ASM_REWRITE_TAC[] THEN
        CONJ_TAC THEN
        (MATCH_MP_TAC EINCL_EREL_INTRO THEN
         MAP_EVERY EXISTS_TAC [`B:A`] THEN ASM_REWRITE_TAC[]);
        ALL_TAC] THEN
      USE_THEN "anti" (MP_TAC o SPECL [`k:A`; `k':A`]) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ASM_MESON_TAC[]]];
    (* ============ per-index value existence (for image antichain) ==== *)
    X_GEN_TAC `b:A` THEN STRIP_TAC THEN
    USE_THEN "ffidx" (MP_TAC o SPEC `b:A`) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(X_CHOOSE_THEN `m:A` STRIP_ASSUME_TAC) THEN
    EXISTS_TAC `m:A` THEN ASM_REWRITE_TAC[]]);;

(* ==================================================================== *)
(* F6.4: IMG_INCOMPAT, the geometric core.                                *)
(* If x IN u and y IN v with u,v IN bp (=B+), and x,y are COMPATIBLE in    *)
(* the poset P, then u,v are COMPATIBLE in (bp,inclB).  Contrapositive:    *)
(* incompatible u,v have P-incompatible selected members -- which is what  *)
(* makes the image of a B+-antichain under the least-member selector a     *)
(* genuine P-antichain.  Bundles EMB_COMPAT_MEET (RO-meet of e(x),e(y)     *)
(* inhabited by r), EMB_INTO_OPEN twice (e(x) SUBSET u, e(y) SUBSET v, so   *)
(* r is a shared member of u,v), and RO_COMPAT_INTER (shared member => a    *)
(* common nonzero RO lower bound w IN bp witnessing ecompat bp inclB u v).  *)
(* Downsets/interiors dx,ex,dy,ey are passed in (built by the caller with  *)
(* EDOWNSET_EXISTS + EINTCL_EXISTS).                                        *)
(* ==================================================================== *)

let IMG_INCOMPAT = prove
 (`!D (E:A->A->bool) P leqp B bp inclB u v x y dx ex dy ey.
      model D E ZF_AX /\ eleqp D E P leqp /\ P IN D /\ leqp IN D /\
      eroset D E P leqp B /\ ebplus D E B bp /\ eincl D E B inclB /\
      u IN D /\ v IN D /\ x IN D /\ y IN D /\
      E u bp /\ E v bp /\ E x u /\ E y v /\
      edownset D E P leqp x dx /\ eintcl D E P leqp dx ex /\
      edownset D E P leqp y dy /\ eintcl D E P leqp dy ey /\
      ecompat D E P leqp x y
      ==> ecompat D E bp inclB u v`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  (* u,v IN B (and nonempty) via ebplus *)
  SUBGOAL_THEN `(E:A->A->bool) u B /\ ~(eempty D (E:A->A->bool) u)`
   STRIP_ASSUME_TAC THENL
   [FIRST_ASSUM(MP_TAC o SPEC `u:A` o CONJUNCT2 o REWRITE_RULE[ebplus]) THEN
    ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[GSYM th]) THEN FIRST_ASSUM ACCEPT_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) v B /\ ~(eempty D (E:A->A->bool) v)`
   STRIP_ASSUME_TAC THENL
   [FIRST_ASSUM(MP_TAC o SPEC `v:A` o CONJUNCT2 o REWRITE_RULE[ebplus]) THEN
    ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[GSYM th]) THEN FIRST_ASSUM ACCEPT_TAC;
    ALL_TAC] THEN
  (* u,v regular-open via eroset *)
  SUBGOAL_THEN
   `esubset D (E:A->A->bool) u P /\ eopen D E leqp u /\ ereg D E P leqp u`
   STRIP_ASSUME_TAC THENL
   [FIRST_ASSUM(MP_TAC o SPEC `u:A` o CONJUNCT2 o REWRITE_RULE[eroset]) THEN
    ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[GSYM th]) THEN FIRST_ASSUM ACCEPT_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN
   `esubset D (E:A->A->bool) v P /\ eopen D E leqp v /\ ereg D E P leqp v`
   STRIP_ASSUME_TAC THENL
   [FIRST_ASSUM(MP_TAC o SPEC `v:A` o CONJUNCT2 o REWRITE_RULE[eroset]) THEN
    ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[GSYM th]) THEN FIRST_ASSUM ACCEPT_TAC;
    ALL_TAC] THEN
  (* RO meet e(x) ^ e(y) inhabited by r *)
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `P:A`; `leqp:A`; `x:A`; `y:A`;
    `dx:A`; `ex:A`; `dy:A`; `ey:A`] EMB_COMPAT_MEET) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `r:A` STRIP_ASSUME_TAC) THEN
  (* e(x) SUBSET u, e(y) SUBSET v *)
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `P:A`; `leqp:A`; `x:A`;
    `dx:A`; `ex:A`; `u:A`] EMB_INTO_OPEN) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN DISCH_TAC THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `P:A`; `leqp:A`; `y:A`;
    `dy:A`; `ey:A`; `v:A`] EMB_INTO_OPEN) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN DISCH_TAC THEN
  (* r is a shared member of u,v *)
  SUBGOAL_THEN `(E:A->A->bool) r u /\ E r v` STRIP_ASSUME_TAC THENL
   [CONJ_TAC THENL
     [UNDISCH_TAC `esubset D (E:A->A->bool) ex u`;
      UNDISCH_TAC `esubset D (E:A->A->bool) ey v`] THEN
    (REWRITE_TAC[esubset] THEN DISCH_THEN MATCH_MP_TAC THEN ASM_REWRITE_TAC[]);
    ALL_TAC] THEN
  (* common nonzero RO lower bound w *)
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `P:A`; `leqp:A`; `B:A`;
    `u:A`; `v:A`; `r:A`] RO_COMPAT_INTER) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `w:A` STRIP_ASSUME_TAC) THEN
  SUBGOAL_THEN `~(eempty D (E:A->A->bool) w)` ASSUME_TAC THENL
   [REWRITE_TAC[eempty] THEN ASM_MESON_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) w bp` ASSUME_TAC THENL
   [FIRST_ASSUM(MP_TAC o SPEC `w:A` o CONJUNCT2 o REWRITE_RULE[ebplus]) THEN
    ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* ecompat bp inclB u v, witnessed by w *)
  REWRITE_TAC[ecompat] THEN EXISTS_TAC `w:A` THEN ASM_REWRITE_TAC[] THEN
  CONJ_TAC THEN
  (MATCH_MP_TAC EINCL_EREL_INTRO THEN
   MAP_EVERY EXISTS_TAC [`B:A`] THEN ASM_REWRITE_TAC[]));;

(* ==================================================================== *)
(* F6.4: CCC_RO_IMGANTI.                                                  *)
(* The image S of a (bp,inclB)-antichain a under the least-member         *)
(* selector ff is a genuine antichain of the poset (P,leqp).              *)
(* Given: ff injects a into P (einj), ff is a selector (ff(b) IN b for     *)
(* every b IN a), and S = ff[a] as a definable image (membership char).   *)
(* For distinct x,y IN S pick their preimages u,v IN a; the selector puts  *)
(* x IN u and y IN v (single-valuedness pins ff(u)=x etc.), and u<>v       *)
(* (else ff(u)=x and ff(u)=y force x=y).  If x,y were P-compatible then    *)
(* IMG_INCOMPAT would make u,v (bp,inclB)-compatible -- impossible for     *)
(* distinct members of the antichain a.  Hence ~ecompat P leqp x y.        *)
(* Downsets/interiors dx,ex,dy,ey built here via EDOWNSET/EINTCL_EXISTS.   *)
(* Depends: IMG_INCOMPAT, EDOWNSET_EXISTS, EINTCL_EXISTS, einj, eapply,    *)
(*   eantichain, edownset, esubset.                                        *)
(* ==================================================================== *)

let CCC_RO_IMGANTI = prove
 (`!D (E:A->A->bool) P leqp B bp inclB ff a S.
      model D E ZF_AX /\ eleqp D E P leqp /\ P IN D /\ leqp IN D /\
      eroset D E P leqp B /\ ebplus D E B bp /\ eincl D E B inclB /\
      a IN D /\ eantichain D E bp inclB a /\
      ff IN D /\ einj D E ff a P /\
      (!b. b IN D /\ E b a ==> ?m. m IN D /\ E m b /\ eapply D E ff b m) /\
      S IN D /\
      (!t. t IN D ==> (E t S <=> ?k. k IN D /\ E k a /\ eapply D E ff k t)) /\
      esubset D E S P
      ==> eantichain D E P leqp S`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "mdl leqp PD leqpD ros ebp einc aD antibp ffD inj idx SD \
             Smem SsubP" THEN
  REWRITE_TAC[eantichain] THEN REPEAT CONJ_TAC THENL
   [USE_THEN "SD" ACCEPT_TAC;
    USE_THEN "SsubP" ACCEPT_TAC;
    ALL_TAC] THEN
  MAP_EVERY X_GEN_TAC [`x:A`; `y:A`] THEN STRIP_TAC THEN
  (* preimages u,v of x,y under ff *)
  SUBGOAL_THEN `?u. u IN D /\ E u a /\ eapply D (E:A->A->bool) ff u x`
   (X_CHOOSE_THEN `u:A` STRIP_ASSUME_TAC) THENL
   [USE_THEN "Smem" (MP_TAC o SPEC `x:A`) THEN
    ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN(fun th -> ASM_MESON_TAC[th]); ALL_TAC] THEN
  SUBGOAL_THEN `?v. v IN D /\ E v a /\ eapply D (E:A->A->bool) ff v y`
   (X_CHOOSE_THEN `v2:A` STRIP_ASSUME_TAC) THENL
   [USE_THEN "Smem" (MP_TAC o SPEC `y:A`) THEN
    ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN(fun th -> ASM_MESON_TAC[th]); ALL_TAC] THEN
  (* selector puts x IN u, y IN v2 *)
  SUBGOAL_THEN `(E:A->A->bool) x u` ASSUME_TAC THENL
   [USE_THEN "idx" (MP_TAC o SPEC `u:A`) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(X_CHOOSE_THEN `m:A` STRIP_ASSUME_TAC) THEN
    SUBGOAL_THEN `(x:A) = m` (fun th -> REWRITE_TAC[th]) THENL
     [USE_THEN "inj" (MP_TAC o SPECL [`u:A`; `x:A`; `m:A`] o
        CONJUNCT1 o CONJUNCT2 o CONJUNCT2 o CONJUNCT2 o
          REWRITE_RULE[einj]) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN DISCH_THEN ACCEPT_TAC;
      FIRST_ASSUM ACCEPT_TAC];
    ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) y v2` ASSUME_TAC THENL
   [USE_THEN "idx" (MP_TAC o SPEC `v2:A`) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(X_CHOOSE_THEN `m:A` STRIP_ASSUME_TAC) THEN
    SUBGOAL_THEN `(y:A) = m` (fun th -> REWRITE_TAC[th]) THENL
     [USE_THEN "inj" (MP_TAC o SPECL [`v2:A`; `y:A`; `m:A`] o
        CONJUNCT1 o CONJUNCT2 o CONJUNCT2 o CONJUNCT2 o
          REWRITE_RULE[einj]) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN DISCH_THEN ACCEPT_TAC;
      FIRST_ASSUM ACCEPT_TAC];
    ALL_TAC] THEN
  (* u <> v2 (else ff(u)=x and ff(u)=y force x=y) *)
  SUBGOAL_THEN `~((u:A) = v2)` ASSUME_TAC THENL
   [DISCH_TAC THEN
    SUBGOAL_THEN `(x:A) = y` ASSUME_TAC THENL
     [USE_THEN "inj" (MP_TAC o SPECL [`u:A`; `x:A`; `y:A`] o
        CONJUNCT1 o CONJUNCT2 o CONJUNCT2 o CONJUNCT2 o
          REWRITE_RULE[einj]) THEN
      ANTS_TAC THENL [ASM_MESON_TAC[]; ALL_TAC] THEN DISCH_THEN ACCEPT_TAC;
      ALL_TAC] THEN
    ASM_MESON_TAC[]; ALL_TAC] THEN
  (* u,v2 IN bp (via esubset a bp from the antichain) *)
  SUBGOAL_THEN `(E:A->A->bool) u bp /\ E v2 bp` STRIP_ASSUME_TAC THENL
   [CONJ_TAC THEN
    (USE_THEN "antibp"
     (MP_TAC o CONJUNCT1 o CONJUNCT2 o REWRITE_RULE[eantichain]) THEN
     REWRITE_TAC[esubset] THEN DISCH_THEN MATCH_MP_TAC THEN ASM_REWRITE_TAC[]);
    ALL_TAC] THEN
  (* build downsets/interiors of x and y *)
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `P:A`; `leqp:A`; `x:A`]
    EDOWNSET_EXISTS) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `dx:A` (LABEL_TAC "dxd")) THEN
  SUBGOAL_THEN `(dx:A) IN D` ASSUME_TAC THENL
   [USE_THEN "dxd" (ACCEPT_TAC o CONJUNCT1 o REWRITE_RULE[edownset]);
    ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `P:A`; `leqp:A`; `dx:A`]
    EINTCL_EXISTS) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `ex:A` (LABEL_TAC "exd")) THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `P:A`; `leqp:A`; `y:A`]
    EDOWNSET_EXISTS) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `dy:A` (LABEL_TAC "dyd")) THEN
  SUBGOAL_THEN `(dy:A) IN D` ASSUME_TAC THENL
   [USE_THEN "dyd" (ACCEPT_TAC o CONJUNCT1 o REWRITE_RULE[edownset]);
    ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `P:A`; `leqp:A`; `dy:A`]
    EINTCL_EXISTS) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `ey:A` (LABEL_TAC "eyd")) THEN
  (* the incompatibility, by contradiction via IMG_INCOMPAT *)
  DISCH_TAC THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `P:A`; `leqp:A`; `B:A`;
    `bp:A`; `inclB:A`; `u:A`; `v2:A`; `x:A`; `y:A`; `dx:A`; `ex:A`;
    `dy:A`; `ey:A`] IMG_INCOMPAT) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_TAC THEN
  USE_THEN "antibp" (MP_TAC o SPECL [`u:A`; `v2:A`] o
    CONJUNCT2 o CONJUNCT2 o REWRITE_RULE[eantichain]) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN ASM_MESON_TAC[]);;

(* ==================================================================== *)
(* F6.4 capstone: CCC_RO.                                                 *)
(* The regular-open (Boolean) completion of a ccc poset is ccc.           *)
(*   model /\ V=L /\ (P,leqp) a poset /\ B = RO(P) /\ bp = B+ = B\{bot}    *)
(*   /\ inclB = straight inclusion on B /\ eccc P leqp                     *)
(*     ==> eccc bp inclB.                                                  *)
(* Proof: let a be a (bp,inclB)-antichain.  STAGE_PIN fixes the V=L        *)
(* wellorder data (v with v2 = ra); every member of a is a nonempty       *)
(* regular-open set, so CCC_RO_SELINJ produces the least-member selector  *)
(* ff : a >-> P (an einj) with ff(b) IN b.  EINJ_IMAGE realises the image  *)
(* S = ff[a] as a set (with ebij ff a S).  CCC_RO_IMGANTI shows S is a     *)
(* (P,leqp)-antichain, so ccc-ness of P gives an injection g : S >-> om    *)
(* into omega; composing ff (as an einj a >-> S) with g yields h : a >-> om*)
(* -- i.e. a is countable, establishing eccc bp inclB.                     *)
(* Depends: STAGE_PIN, CCC_RO_SELINJ, EINJ_IMAGE, CCC_RO_IMGANTI, eccc,    *)
(*   EBIJ_EINJ, EINJ_COMPOSE, EOMEGA_IN, eantichain/esubset/ebplus/eempty. *)
(* ==================================================================== *)

let CCC_RO = prove
 (`!D (E:A->A->bool) P leqp B bp inclB.
      model D E ZF_AX /\ (!u. u IN D ==> elmem D E u) /\
      eleqp D E P leqp /\ P IN D /\
      eroset D E P leqp B /\ ebplus D E B bp /\ eincl D E B inclB /\
      eccc D E P leqp
      ==> eccc D E bp inclB`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "mdl vl elq PD ros ebp einc ccc" THEN
  (* leqp IN D from eleqp *)
  SUBGOAL_THEN `(leqp:A) IN D` (LABEL_TAC "leqpD") THENL
   [USE_THEN "elq" (ACCEPT_TAC o CONJUNCT1 o REWRITE_RULE[eleqp]);
    ALL_TAC] THEN
  REWRITE_TAC[eccc] THEN X_GEN_TAC `a:A` THEN
  DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "aD") (LABEL_TAC "antibp")) THEN
  (* -- STAGE_PIN: V=L wellorder data -- *)
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `a:A`] STAGE_PIN) THEN
  ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `s:A` (X_CHOOSE_THEN `ya:A` (X_CHOOSE_THEN `ra:A`
    (X_CHOOSE_THEN `v:num->A` STRIP_ASSUME_TAC)))) THEN
  (* rewrite v2 = ra into the two facts SELINJ wants *)
  SUBGOAL_THEN `(v:num->A) 2 IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `elwou D (E:A->A->bool) s ((v:num->A) 2)` ASSUME_TAC THENL
   [ASM_MESON_TAC[]; ALL_TAC] THEN
  (* -- SELINJ hypothesis: members of a are nonempty, all members lie in ya *)
  (* -- *)
  SUBGOAL_THEN
   `!u:A. u IN D /\ E u a
          ==> (!t. t IN D /\ E t u ==> E t ya) /\ (?t. t IN D /\ E t u)`
   ASSUME_TAC THENL
   [X_GEN_TAC `u:A` THEN STRIP_TAC THEN CONJ_TAC THENL
     [ASM_MESON_TAC[];
      SUBGOAL_THEN `(E:A->A->bool) u bp` ASSUME_TAC THENL
       [USE_THEN "antibp" (MP_TAC o CONJUNCT1 o CONJUNCT2 o
          REWRITE_RULE[eantichain]) THEN
        REWRITE_TAC[esubset] THEN DISCH_THEN MATCH_MP_TAC THEN
        ASM_REWRITE_TAC[]; ALL_TAC] THEN
      SUBGOAL_THEN `~(eempty D (E:A->A->bool) u)` ASSUME_TAC THENL
       [FIRST_ASSUM(MP_TAC o SPEC `u:A` o CONJUNCT2 o
                    REWRITE_RULE[ebplus]) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
        ASM_REWRITE_TAC[] THEN STRIP_TAC THEN FIRST_ASSUM ACCEPT_TAC;
        ALL_TAC] THEN
      UNDISCH_TAC `~(eempty D (E:A->A->bool) u)` THEN REWRITE_TAC[eempty] THEN
      ASM_REWRITE_TAC[NOT_FORALL_THM; NOT_IMP] THEN MESON_TAC[]];
    ALL_TAC] THEN
  (* -- obtain the selector ff : a >-> P -- *)
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `P:A`; `leqp:A`; `B:A`;
    `bp:A`; `inclB:A`; `v:num->A`; `a:A`; `s:A`; `ya:A`] CCC_RO_SELINJ) THEN
  ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `ff:A` STRIP_ASSUME_TAC) THEN
  SUBGOAL_THEN `(ff:A) IN D` ASSUME_TAC THENL
   [FIRST_ASSUM(ACCEPT_TAC o CONJUNCT1 o REWRITE_RULE[einj]); ALL_TAC] THEN
  (* -- realise the image S = ff[a] -- *)
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `ff:A`; `a:A`; `P:A`]
    EINJ_IMAGE) THEN
  ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `S:A` STRIP_ASSUME_TAC) THEN
  SUBGOAL_THEN `esubset D (E:A->A->bool) S P` ASSUME_TAC THENL
   [REWRITE_TAC[esubset] THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  (* -- S is a (P,leqp)-antichain -- *)
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `P:A`; `leqp:A`; `B:A`;
    `bp:A`; `inclB:A`; `ff:A`; `a:A`; `S:A`] CCC_RO_IMGANTI) THEN
  ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  DISCH_TAC THEN
  (* -- ccc of P gives an injection g : S >-> omega -- *)
  USE_THEN "ccc" (MP_TAC o SPEC `S:A` o REWRITE_RULE[eccc]) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `om:A` (X_CHOOSE_THEN `g:A` STRIP_ASSUME_TAC)) THEN
  (* -- compose ff (a >-> S) with g (S >-> om) -- *)
  SUBGOAL_THEN `einj D (E:A->A->bool) ff a S` ASSUME_TAC THENL
   [MATCH_MP_TAC EBIJ_EINJ THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  SUBGOAL_THEN `(om:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[EOMEGA_IN]; ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `ff:A`; `g:A`; `a:A`; `S:A`;
    `om:A`] EINJ_COMPOSE) THEN
  ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `h:A` ASSUME_TAC) THEN
  MAP_EVERY EXISTS_TAC [`om:A`; `h:A`] THEN ASM_REWRITE_TAC[] THEN
  FIRST_ASSUM(ACCEPT_TAC o CONJUNCT1 o REWRITE_RULE[einj]));;

(* ==================================================================== *)
(* F6.3: EFUN_UNION_AGREE.                                               *)
(* The union of two FUNCTIONAL sets that AGREE wherever their domains     *)
(* overlap is itself functional.  This is the compatibility crux of       *)
(* CCC_COHEN step 5: two Cohen conditions p,q with dom p INTER dom q = r   *)
(* and p|_r = q|_r have p UNION q functional (=> a condition => a common   *)
(* extension => p,q compatible).                                          *)
(*                                                                        *)
(* The AGREE hypothesis is stated pointwise on the overlap (p-member as   *)
(* the first pair, q-member as the second), which decouples N4 from the   *)
(* Delta-system: the caller derives it from dom INTER = r + p|_r = q|_r.   *)
(*                                                                        *)
(* Proof: unfold efunctional pq; take two graph pairs z,z' of pq sharing  *)
(* domain point u (eopair u w z, eopair u w' z'); EBUNION_MEM splits each  *)
(* into p or q; the four cases close by efunctional p / efunctional q /    *)
(* the agree hypothesis (twice, once with p,q roles swapped => SYM).       *)
(* Depends: efunctional, ebunion, EBUNION_MEM, eopair (as an atom).        *)
(* ==================================================================== *)

let EFUN_UNION_AGREE = prove
 (`!D (E:A->A->bool) p q pq.
      model D E ZF_AX /\ p IN D /\ q IN D /\
      efunctional D E p /\ efunctional D E q /\ ebunion D E p q pq /\
      (!u w w' z z'.
          u IN D /\ w IN D /\ w' IN D /\ z IN D /\ z' IN D /\
          eopair D E u w z /\ E z p /\ eopair D E u w' z' /\ E z' q
          ==> w = w')
      ==> efunctional D E pq`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "mdl pD qD fp fq bun agree" THEN
  (* membership characterization of pq = p UNION q *)
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `p:A`; `q:A`; `pq:A`]
         EBUNION_MEM) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(LABEL_TAC "mem" o CONJUNCT2) THEN
  REWRITE_TAC[efunctional] THEN
  MAP_EVERY X_GEN_TAC [`z:A`; `z':A`; `u:A`; `w:A`; `w':A`] THEN STRIP_TAC THEN
  (* each of z, z' lies in p or in q *)
  SUBGOAL_THEN `(E:A->A->bool) z p \/ E z q` (LABEL_TAC "dz") THENL
   [USE_THEN "mem" (MP_TAC o SPEC `z:A`) THEN
    ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[GSYM th]) THEN FIRST_ASSUM ACCEPT_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) z' p \/ E z' q` (LABEL_TAC "dz'") THENL
   [USE_THEN "mem" (MP_TAC o SPEC `z':A`) THEN
    ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[GSYM th]) THEN FIRST_ASSUM ACCEPT_TAC;
    ALL_TAC] THEN
  (* four cases *)
  USE_THEN "dz" DISJ_CASES_TAC THENL
   [USE_THEN "dz'" DISJ_CASES_TAC THENL
     [(* z IN p, z' IN p: functional p *)
      USE_THEN "fp" (MP_TAC o SPECL [`z:A`; `z':A`; `u:A`; `w:A`; `w':A`] o
        REWRITE_RULE[efunctional]) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC];
      (* z IN p, z' IN q: agree (u,w,w',z,z') *)
      USE_THEN "agree"
        (MP_TAC o SPECL [`u:A`; `w:A`; `w':A`; `z:A`; `z':A`]) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC]];
    USE_THEN "dz'" DISJ_CASES_TAC THENL
     [(* z IN q, z' IN p: agree (u,w',w,z',z) -> w'=w, then SYM *)
      USE_THEN "agree"
        (MP_TAC o SPECL [`u:A`; `w':A`; `w:A`; `z':A`; `z:A`]) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN(ACCEPT_TAC o SYM)];
      (* z IN q, z' IN q: functional q *)
      USE_THEN "fq" (MP_TAC o SPECL [`z:A`; `z':A`; `u:A`; `w:A`; `w':A`] o
        REWRITE_RULE[efunctional]) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC]]]);;

(* ==================================================================== *)
(* F6.3 lemma (step-5 packaging, easy half): ELEQP_UNION_COMPAT.         *)
(* In a reverse-inclusion poset (eleqp: erel leqp u v <=> u,v in P and   *)
(* v SUBSET u), if p,q are conditions whose union pq = p UNION q is ALSO *)
(* a condition (E pq P), then p and q are COMPATIBLE: pq is a common     *)
(* lower bound (=stronger extension) of both.                            *)
(*                                                                       *)
(* This is the half of CCC_COHEN step 5 that needs NO finiteness bridge  *)
(* -- it takes "pq is a condition" as a hypothesis.  The companion       *)
(* COHEN_UNION_IS_CONDITION (pq functional + both finite ==> E pq P)     *)
(* will discharge that hypothesis once the efin<->bij-to-finite-ordinal  *)
(* converse bridge is built.                                             *)
(*                                                                       *)
(* Proof: pq IN D (EBUNION_IN); membership char E w pq <=> E w p \/ E w q*)
(* (EBUNION_MEM); hence esubset p pq and esubset q pq; then w:=pq        *)
(* witnesses ecompat via ELEQP_EREL_INTRO twice (E pq P + p SUBSET pq).  *)
(* Fully general -- ci/om/ecohenp not needed, only eleqp.                *)
(* ==================================================================== *)

(* ==================================================================== *)
(* Converse-finiteness prerequisite, piece 1: EOMEGA_MEM_FIN.            *)
(* Every element of omega is Kuratowski-finite (efin).                  *)
(*                                                                       *)
(* efin is a HOL predicate, not an object formula, so we cannot feed it  *)
(* to EOMEGA_INDUCT directly.  Instead, unfold efin, fix an arbitrary    *)
(* good family `fam` for n, and prove n IN fam by a BOUNDED omega        *)
(* induction: EOMEGA_INDUCT on the object formula                        *)
(*      phi(k)  =  subset_form 0 1 --> (0 %% 3)                          *)
(* under valuation (1|->n)((3|->fam)w), whose meaning is                 *)
(*      holds((0|->k)v) phi  <=>  (esubset k n ==> E k fam).             *)
(* Base k=0: the empty set is in fam (goodness).  Step k->k+1: if        *)
(* succ k SUBSET n then k SUBSET n (so k IN fam by IH) and k IN n, and   *)
(* succ k = k adjoin k, so adjoin-closure of fam gives succ k IN fam.    *)
(* Finally instantiate the induction conclusion at n itself (n IN om,    *)
(* n SUBSET n by ESUBSET_REFL) to get n IN fam.                          *)
(*                                                                       *)
(* Key facts used: esuc D E u s and eadjoin D E u u s are DEFINITIONALLY *)
(* identical (both ?t. epair u u t /\ ebunion u t s), so REWRITE with    *)
(* [esuc; eadjoin] converts between them.  The valuation is INLINED      *)
(* (no ABBREV_TAC) so the holds-reduction closes in one shot.  Terminal  *)
(* membership/subset closers use ASM_MESON_TAC[] (ASM_REWRITE_TAC[]      *)
(* leaves a `t ==> t` residue it will not discharge).                    *)
(* ==================================================================== *)

let EOMEGA_MEM_FIN = prove
 (`!D (E:A->A->bool) om n.
      model D E ZF_AX /\ eomega D E om /\ n IN D /\ E n om ==> efin D E n`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "mdl om nD nom" THEN
  REWRITE_TAC[efin] THEN CONJ_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  X_GEN_TAC `fam:A` THEN
  INTRO_TAC "famD sub emp clo" THEN
  (* base valuation w *)
  SUBGOAL_THEN `?w:num->A. valuation D w` (X_CHOOSE_TAC `w:num->A`) THENL
   [MATCH_MP_TAC VALUATION_EXISTS THEN
    USE_THEN "mdl" (MP_TAC o REWRITE_RULE[model]) THEN SIMP_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `valuation D ((1 |-> (n:A)) ((3 |-> (fam:A)) (w:num->A)))`
   (LABEL_TAC "val") THENL
   [MATCH_MP_TAC VALUATION_VALMOD THEN CONJ_TAC THENL
     [MATCH_MP_TAC VALUATION_VALMOD THEN CONJ_TAC THENL
       [FIRST_ASSUM ACCEPT_TAC; FIRST_ASSUM ACCEPT_TAC];
      FIRST_ASSUM ACCEPT_TAC];
    ALL_TAC] THEN
  (* meaning of phi under (0|->k)v *)
  SUBGOAL_THEN
   `!k:A. holds D E ((0 |-> k) ((1 |-> (n:A)) ((3 |-> (fam:A)) (w:num->A))))
              (subset_form 0 1 --> (0 %% 3)) <=>
          (esubset D E k n ==> E k fam)`
   (LABEL_TAC "hv") THENL
   [GEN_TAC THEN REWRITE_TAC[HOLDS_IMP; HOLDS_SUBSET_FORM; HOLDS_MEM] THEN
    REWRITE_TAC[VALMOD; ARITH_EQ];
    ALL_TAC] THEN
  (* the bounded omega induction *)
  MP_TAC(ISPECL
   [`D:A->bool`; `E:A->A->bool`; `om:A`;
    `subset_form 0 1 --> (0 %% 3)`; `0`;
    `(1 |-> (n:A)) ((3 |-> (fam:A)) (w:num->A))`] EOMEGA_INDUCT) THEN
  ANTS_TAC THENL
   [REPEAT CONJ_TAC THENL
     [FIRST_ASSUM ACCEPT_TAC;
      FIRST_ASSUM ACCEPT_TAC;
      FIRST_ASSUM ACCEPT_TAC;
      (* base *)
      X_GEN_TAC `e:A` THEN DISCH_TAC THEN
      USE_THEN "hv" (fun th -> REWRITE_TAC[th]) THEN DISCH_TAC THEN
      USE_THEN "emp" (X_CHOOSE_THEN `z:A` STRIP_ASSUME_TAC) THEN
      SUBGOAL_THEN `(e:A) = z` SUBST1_TAC THENL
       [MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`e:A`;`z:A`]
               EEMPTY_UNIQUE) THEN
        ASM_REWRITE_TAC[];
        FIRST_ASSUM ACCEPT_TAC];
      (* step *)
      MAP_EVERY X_GEN_TAC [`u:A`; `s:A`] THEN
      INTRO_TAC "uD uom ihh suc" THEN
      USE_THEN "hv" (fun hvth ->
        USE_THEN "ihh" (LABEL_TAC "ihv" o REWRITE_RULE[hvth])) THEN
      USE_THEN "hv" (fun th -> REWRITE_TAC[th]) THEN
      DISCH_THEN(LABEL_TAC "ssubn") THEN
      SUBGOAL_THEN `!w:A. w IN D ==> ((E:A->A->bool) w s <=> E w u \/ w = u)`
       (LABEL_TAC "sm") THENL
       [MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`u:A`;`u:A`;`s:A`]
               EADJOIN_MEM) THEN
        ANTS_TAC THENL
         [ASM_REWRITE_TAC[] THEN USE_THEN "suc" MP_TAC THEN
          REWRITE_TAC[esuc; eadjoin];
          DISCH_THEN(ACCEPT_TAC o CONJUNCT2)];
        ALL_TAC] THEN
      SUBGOAL_THEN `(E:A->A->bool) u s` (LABEL_TAC "uIns") THENL
       [USE_THEN "sm" (MP_TAC o SPEC `u:A`) THEN ASM_MESON_TAC[];
        ALL_TAC] THEN
      SUBGOAL_THEN `esubset D (E:A->A->bool) u n` (LABEL_TAC "usubn") THENL
       [REWRITE_TAC[esubset] THEN X_GEN_TAC `w:A` THEN
        DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "wD") (LABEL_TAC "wu")) THEN
        SUBGOAL_THEN `(E:A->A->bool) w s` (LABEL_TAC "ws") THENL
         [USE_THEN "sm" (MP_TAC o SPEC `w:A`) THEN ASM_MESON_TAC[];
          ALL_TAC] THEN
        USE_THEN "ssubn" (MP_TAC o REWRITE_RULE[esubset]) THEN
        DISCH_THEN(MP_TAC o SPEC `w:A`) THEN ASM_MESON_TAC[];
        ALL_TAC] THEN
      SUBGOAL_THEN `(E:A->A->bool) u n` (LABEL_TAC "uInn") THENL
       [USE_THEN "ssubn" (MP_TAC o REWRITE_RULE[esubset]) THEN
        DISCH_THEN(MP_TAC o SPEC `u:A`) THEN ASM_MESON_TAC[];
        ALL_TAC] THEN
      SUBGOAL_THEN `(E:A->A->bool) u fam` (LABEL_TAC "uInfam") THENL
       [USE_THEN "ihv" MATCH_MP_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
      SUBGOAL_THEN `(s:A) IN D` (LABEL_TAC "sD") THENL
       [MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`u:A`;`s:A`] ESUC_IN) THEN
        ASM_MESON_TAC[]; ALL_TAC] THEN
      SUBGOAL_THEN `eadjoin D (E:A->A->bool) u u s` (LABEL_TAC "adj") THENL
       [USE_THEN "suc" MP_TAC THEN REWRITE_TAC[esuc; eadjoin]; ALL_TAC] THEN
      USE_THEN "clo" (MP_TAC o SPECL [`u:A`; `u:A`; `s:A`]) THEN
      ASM_MESON_TAC[]];
    (* conclusion: specialize at n *)
    DISCH_THEN(MP_TAC o SPEC `n:A`) THEN ASM_REWRITE_TAC[] THEN
    USE_THEN "hv" (fun th -> REWRITE_TAC[th]) THEN
    DISCH_THEN MATCH_MP_TAC THEN REWRITE_TAC[ESUBSET_REFL]]);;

(* ==================================================================== *)
(* Converse-finiteness prerequisite, piece 2: imgfam_form + IMGFAM_HOLDS *)
(*                                                                       *)
(* The pull-back family for EBIJ_TO_FIN.  Over the powerset of the       *)
(* finite ordinal n, separation with imgfam_form carves out             *)
(*    gam = { v SUBSET n : (image of v under f) IN fam }.                *)
(* imgfam_form is the separation predicate on the separation variable    *)
(* slot 20 (= v), with parameters slot 18 (= f) and slot 19 (= fam):     *)
(*    ?w. (!m. m IN w <-> ?x. x IN v /\ apply f x m) /\ w IN fam         *)
(* i.e. "the image of v under f is a member of fam".  The inner image    *)
(* predicate uses apply_form 18 23 22 (f = 18, x = 23, m = 22), whose    *)
(* own internal binders are slots 24,25,26 -- fresh above the bound      *)
(* vars 21 (w), 22 (m), 23 (x), so no capture.                           *)
(* Structure mirrors ADJFAM_HOLDS with one extra existential (x) layer.  *)
(* ==================================================================== *)

let imgfam_form = new_definition
  `imgfam_form =
     ?? 21 ((!! 22 ((22 %% 21) <->
                     (?? 23 ((23 %% 20) && apply_form 18 23 22)))) &&
            (21 %% 19))`;;

let IMGFAM_HOLDS = prove
 (`!D (E:A->A->bool) v vv.
      model D E ZF_AX /\ valuation D v /\ vv IN D
      ==> (holds D E ((20 |-> vv) v) imgfam_form <=>
           ?w. w IN D /\
               (!m. m IN D
                    ==> (E m w <=>
                         ?x. x IN D /\ E x vv /\ eapply D E (v 18) x m)) /\
               E w (v 19))`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[imgfam_form] THEN
  SUBGOAL_THEN `valuation D ((20 |-> (vv:A)) v)` ASSUME_TAC THENL
   [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
  REWRITE_TAC[HOLDS_EX] THEN
  SUBGOAL_THEN
   `!w':A. w' IN D
      ==> (holds D E ((21 |-> w') ((20 |-> (vv:A)) v))
             ((!! 22 ((22 %% 21) <->
                      (?? 23 ((23 %% 20) && apply_form 18 23 22)))) &&
              (21 %% 19)) <=>
           (!m. m IN D
                ==> (E m w' <=>
                     ?x. x IN D /\ E x vv /\ eapply D E (v 18) x m)) /\
           E w' (v 19))`
   (LABEL_TAC "body") THENL
   [X_GEN_TAC `w':A` THEN DISCH_TAC THEN
    SUBGOAL_THEN `valuation D ((21 |-> (w':A)) ((20 |-> (vv:A)) v))`
     ASSUME_TAC THENL [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
    ASM_SIMP_TAC[HOLDS_AND; HOLDS_ALL] THEN
    SUBGOAL_THEN
     `!m:A. m IN D
        ==> (holds D E ((22 |-> m) ((21 |-> (w':A)) ((20 |-> (vv:A)) v)))
               ((22 %% 21) <->
                (?? 23 ((23 %% 20) && apply_form 18 23 22))) <=>
             (E m w' <=>
              ?x. x IN D /\ E x vv /\ eapply D E (v 18) x m))`
     (LABEL_TAC "inner") THENL
     [X_GEN_TAC `m:A` THEN DISCH_TAC THEN
      SUBGOAL_THEN
       `valuation D ((22 |-> (m:A)) ((21 |-> (w':A)) ((20 |-> (vv:A)) v)))`
       ASSUME_TAC THENL [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
      REWRITE_TAC[HOLDS_IFF] THEN
      SUBGOAL_THEN
       `holds D E ((22 |-> (m:A)) ((21 |-> (w':A)) ((20 |-> (vv:A)) v)))
          (22 %% 21) <=> E m w'` SUBST1_TAC THENL
       [REWRITE_TAC[HOLDS_MEM] THEN REWRITE_TAC[VALMOD; ARITH_EQ];
        ALL_TAC] THEN
      REWRITE_TAC[HOLDS_EX] THEN
      SUBGOAL_THEN
       `!x:A. x IN D
          ==> (holds D E ((23 |-> x) ((22 |-> (m:A)) ((21 |-> (w':A))
                        ((20 |-> (vv:A)) v))))
                 ((23 %% 20) && apply_form 18 23 22) <=>
               E x vv /\ eapply D E (v 18) x m)`
       (LABEL_TAC "xbody") THENL
       [X_GEN_TAC `x:A` THEN DISCH_TAC THEN
        SUBGOAL_THEN
         `valuation D ((23 |-> (x:A)) ((22 |-> (m:A)) ((21 |-> (w':A))
                      ((20 |-> (vv:A)) v))))` ASSUME_TAC THENL
         [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
        REWRITE_TAC[HOLDS_AND] THEN
        SUBGOAL_THEN
         `holds D E ((23 |-> (x:A)) ((22 |-> (m:A)) ((21 |-> (w':A))
                    ((20 |-> (vv:A)) v)))) (23 %% 20) <=> E x vv`
         SUBST1_TAC THENL
         [REWRITE_TAC[HOLDS_MEM] THEN REWRITE_TAC[VALMOD; ARITH_EQ];
          ALL_TAC] THEN
        MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;
          `(23 |-> (x:A))
           ((22 |-> (m:A)) ((21 |-> (w':A)) ((20 |-> (vv:A)) v)))`;
          `18`;`23`;`22`] HOLDS_APPLY_FORM) THEN
        ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
        DISCH_THEN SUBST1_TAC THEN
        REWRITE_TAC[VALMOD; ARITH_EQ];
        ALL_TAC] THEN
      AP_TERM_TAC THEN ASM_MESON_TAC[];
      ALL_TAC] THEN
    SUBGOAL_THEN
     `holds D E ((21 |-> (w':A)) ((20 |-> (vv:A)) v)) (21 %% 19) <=>
      E w' (v 19)` SUBST1_TAC THENL
     [REWRITE_TAC[HOLDS_MEM] THEN REWRITE_TAC[VALMOD; ARITH_EQ]; ALL_TAC] THEN
    ASM_SIMP_TAC[];
    ALL_TAC] THEN
  EQ_TAC THENL
   [DISCH_THEN(X_CHOOSE_THEN `w':A` STRIP_ASSUME_TAC) THEN
    EXISTS_TAC `w':A` THEN ASM_REWRITE_TAC[] THEN
    USE_THEN "body" (MP_TAC o SPEC `w':A`) THEN ANTS_TAC THENL
     [FIRST_ASSUM ACCEPT_TAC; DISCH_THEN(fun th -> ASM_MESON_TAC[th])];
    DISCH_THEN(X_CHOOSE_THEN `w':A` STRIP_ASSUME_TAC) THEN
    EXISTS_TAC `w':A` THEN ASM_REWRITE_TAC[] THEN
    USE_THEN "body" (MP_TAC o SPEC `w':A`) THEN ANTS_TAC THENL
     [FIRST_ASSUM ACCEPT_TAC; DISCH_THEN(fun th -> ASM_MESON_TAC[th])]]);;

(* ==================================================================== *)
(* Converse-finiteness prerequisite, piece 3: EIMAGE_ADJOIN.             *)
(*                                                                       *)
(* The image operator commutes with adjoining a point:                   *)
(*   if  w  is the image of v under f  (w = f"v),                        *)
(*       b = f(a),  v' = v adjoin a,  w' = w adjoin b,                   *)
(*   then w' is the image of v' under f  (w' = f"v').                    *)
(* Only single-valuedness of f (at a) is needed, supplied as the         *)
(* generic sv clause.  Pure membership reasoning:                        *)
(*   E m w' <=> E m w \/ m = b               [EADJOIN_MEM on w,b,w']     *)
(*          <=> (?x IN v. f x = m) \/ m = b   [w = image v]              *)
(* and on the image side                                                 *)
(*   ?x IN v'. f x = m <=> (?x IN v. f x = m) \/ f a = m  [E x v' char]  *)
(* so the two agree once  m = b <=> eapply f a m  (lemma "ab", from      *)
(* eapply f a b + single-valuedness).                                    *)
(* ==================================================================== *)

let EIMAGE_ADJOIN = prove
 (`!D (E:A->A->bool) f v a b w v' w'.
      model D E ZF_AX /\ f IN D /\ v IN D /\ a IN D /\ b IN D /\
      w IN D /\ w' IN D /\
      eapply D E f a b /\
      (!m t t'. m IN D /\ t IN D /\ t' IN D /\
                eapply D E f m t /\ eapply D E f m t' ==> t = t') /\
      (!m. m IN D ==> (E m w <=> ?x. x IN D /\ E x v /\ eapply D E f x m)) /\
      eadjoin D E v a v' /\ eadjoin D E w b w'
      ==> (!m. m IN D
              ==> (E m w' <=> ?x. x IN D /\ E x v' /\ eapply D E f x m))`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `!x:A. x IN D ==> ((E:A->A->bool) x v' <=> E x v \/ x = a)`
   (LABEL_TAC "v'm") THENL
   [MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`v:A`;`a:A`;`v':A`]
           EADJOIN_MEM) THEN
    ASM_REWRITE_TAC[] THEN MESON_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `!x:A. x IN D ==> ((E:A->A->bool) x w' <=> E x w \/ x = b)`
   (LABEL_TAC "w'm") THENL
   [MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`w:A`;`b:A`;`w':A`]
           EADJOIN_MEM) THEN
    ASM_REWRITE_TAC[] THEN MESON_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `!m:A. m IN D ==> (m = b <=> eapply D E f a m)`
   (LABEL_TAC "ab") THENL
   [X_GEN_TAC `mm:A` THEN DISCH_TAC THEN ASM_MESON_TAC[]; ALL_TAC] THEN
  X_GEN_TAC `m:A` THEN DISCH_TAC THEN ASM_MESON_TAC[]);;

(* ==================================================================== *)
(* Converse finiteness bridge (capstone):  EBIJ_TO_FIN                    *)
(*                                                                       *)
(*   ?n IN om. ebij f n p  ==>  efin p                                   *)
(*                                                                       *)
(* If p is in internal bijection with a finite ordinal n IN om, then p   *)
(* is finite.  Pull-back-family route (avoids all bijection surgery):    *)
(* from the finiteness of n (EOMEGA_MEM_FIN) and an arbitrary good       *)
(* family fam of subsets of p, separate                                  *)
(*    gam = { v SUBSET n : (image of v under f) IN fam }                 *)
(* (imgfam_form / IMGFAM_HOLDS).  gam is a good family for n:             *)
(*   - contains the empty set (image of empty = empty IN fam);           *)
(*   - closed under adjoining a point u IN n (image commutes with        *)
(*     adjoining via EIMAGE_ADJOIN; f(u) IN p by the total clause, so    *)
(*     fam's adjoin-closure applies).                                    *)
(* EFIN_ABSFAM at q=c=n gives n IN gam, i.e. (image of n) IN fam; and     *)
(* image of n = p by surjectivity + containment + extensionality.  Hence *)
(* p IN fam for every good fam, i.e. efin p.                             *)
(*                                                                       *)
(* NB the membership characterization GAM and the raw separation clause  *)
(* gamch are kept as BOUND theorems (not assumptions): both are of shape *)
(* !z. z IN D ==> (E z gam <=> ...), which ASM_REWRITE_TAC would fire as  *)
(* a conditional rewrite on E _ gam, collapsing MP_TAC'd implications and *)
(* breaking downstream DISCH.  The z IN D guards are discharged by        *)
(* ANTS_TAC instead.                                                     *)
(* ==================================================================== *)

let EBIJ_TO_FIN = prove
 (`!D (E:A->A->bool) om n p f.
      model D E ZF_AX /\ eomega D E om /\ n IN D /\ E n om /\ p IN D /\
      ebij D E f n p
      ==> efin D E p`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "mdl omega nD nom pD bij" THEN
  (* unpack the six ebij clauses *)
  USE_THEN "bij" (CONJUNCTS_THEN2 (LABEL_TAC "fD")
    (CONJUNCTS_THEN2 (LABEL_TAC "cont")
     (CONJUNCTS_THEN2 (LABEL_TAC "total")
      (CONJUNCTS_THEN2 (LABEL_TAC "sv")
       (CONJUNCTS_THEN2 (LABEL_TAC "inj") (LABEL_TAC "surj")))))
    o REWRITE_RULE[ebij]) THEN
  (* n is finite *)
  SUBGOAL_THEN `efin D (E:A->A->bool) n` (LABEL_TAC "finn") THENL
   [ASM_MESON_TAC[EOMEGA_MEM_FIN]; ALL_TAC] THEN
  (* reduce to: for an arbitrary good family fam of subsets of p, p IN fam *)
  REWRITE_TAC[efin] THEN CONJ_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  X_GEN_TAC `fam:A` THEN
  DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "famD")
    (CONJUNCTS_THEN2 (K ALL_TAC)
     (CONJUNCTS_THEN2 (LABEL_TAC "emp") (LABEL_TAC "fadj")))) THEN
  (* base valuation carrying f at slot 18 and fam at slot 19 *)
  ABBREV_TAC `v0 = (18 |-> (f:A)) ((19 |-> (fam:A)) (\k:num. (f:A)))` THEN
  SUBGOAL_THEN `valuation D (v0:num->A)` (LABEL_TAC "valv0") THENL
   [EXPAND_TAC "v0" THEN
    MATCH_MP_TAC VALUATION_VALMOD THEN CONJ_TAC THENL
     [MATCH_MP_TAC VALUATION_VALMOD THEN CONJ_TAC THENL
       [REWRITE_TAC[valuation] THEN FIRST_ASSUM ACCEPT_TAC;
        FIRST_ASSUM ACCEPT_TAC];
      FIRST_ASSUM ACCEPT_TAC];
    ALL_TAC] THEN
  SUBGOAL_THEN `(v0:num->A) 18 = f /\ (v0:num->A) 19 = fam`
    (CONJUNCTS_THEN2 (LABEL_TAC "v18") (LABEL_TAC "v19")) THENL
   [EXPAND_TAC "v0" THEN CONJ_TAC THEN REWRITE_TAC[VALMOD; ARITH_EQ];
    ALL_TAC] THEN
  (* powerset of n as the separation source *)
  MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`n:A`] EPOW_EXISTS) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `pown:A` (LABEL_TAC "pow")) THEN
  SUBGOAL_THEN `(pown:A) IN D` (LABEL_TAC "pownD") THENL
   [ASM_MESON_TAC[epow]; ALL_TAC] THEN
  (* separate gam = { v SUBSET n : image of v under f IN fam } *)
  MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`] ZF_SEPARATION) THEN
  ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  DISCH_THEN(MP_TAC o ISPECL[`imgfam_form`;`20`;`v0:num->A`;`pown:A`]) THEN
  ANTS_TAC THENL
   [CONJ_TAC THENL [FIRST_ASSUM ACCEPT_TAC; FIRST_ASSUM ACCEPT_TAC];
    ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `gam:A`
   (CONJUNCTS_THEN2 (LABEL_TAC "gamD") (fun gamch ->
    (* clean characterization of membership in gam (kept as bound thm GAM) *)
    SUBGOAL_THEN
     `!z. z IN D
          ==> ((E:A->A->bool) z gam <=>
               esubset D E z n /\
               (?w. w IN D /\
                    (!m. m IN D
                         ==> (E m w <=> ?x. x IN D /\ E x z /\
                              eapply D E f x m)) /\
                    E w fam))`
     MP_TAC THENL
     [X_GEN_TAC `z:A` THEN DISCH_TAC THEN
      MP_TAC(SPEC `z:A` gamch) THEN
      ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
      DISCH_THEN SUBST1_TAC THEN
      SUBGOAL_THEN `E (z:A) pown <=> esubset D E z n` SUBST1_TAC THENL
       [ASM_MESON_TAC[epow]; ALL_TAC] THEN
      MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`v0:num->A`;`z:A`]
             IMGFAM_HOLDS) THEN
      ASM_REWRITE_TAC[] THEN DISCH_THEN SUBST1_TAC THEN
      ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    DISCH_THEN(fun gth ->
     (* gam contains the empty set *)
     SUBGOAL_THEN `?z. z IN D /\ eempty D (E:A->A->bool) z /\ E z gam`
       (LABEL_TAC "base") THENL
      [USE_THEN "emp" (X_CHOOSE_THEN `e0:A` STRIP_ASSUME_TAC) THEN
       EXISTS_TAC `e0:A` THEN ASM_REWRITE_TAC[] THEN
       MP_TAC(SPEC `e0:A` gth) THEN
       ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
       DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN CONJ_TAC THENL
        [MATCH_MP_TAC EEMPTY_SUBSET THEN FIRST_ASSUM ACCEPT_TAC;
         EXISTS_TAC `e0:A` THEN ASM_REWRITE_TAC[] THEN
         X_GEN_TAC `m:A` THEN DISCH_TAC THEN ASM_MESON_TAC[eempty]];
       ALL_TAC] THEN
     (* gam is closed under adjoining a point of n *)
     SUBGOAL_THEN
      `!x u y. x IN D /\ u IN D /\ y IN D /\ (E:A->A->bool) x gam /\ E u n /\
               eadjoin D E x u y
               ==> E y gam`
      (LABEL_TAC "adjcl") THENL
      [MAP_EVERY X_GEN_TAC [`xx:A`;`uu:A`;`yy:A`] THEN STRIP_TAC THEN
       (* decode E xx gam via GAM *)
       SUBGOAL_THEN
        `esubset D E (xx:A) n /\
         (?w. w IN D /\
              (!m. m IN D
                   ==> (E m w <=> ?x. x IN D /\ E x xx /\ eapply D E f x m)) /\
              E w fam)`
        MP_TAC THENL
        [MP_TAC(SPEC `xx:A` gth) THEN
         ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
         DISCH_THEN(fun th -> REWRITE_TAC[GSYM th]) THEN
         FIRST_ASSUM ACCEPT_TAC;
         ALL_TAC] THEN
       DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "subxn")
         (X_CHOOSE_THEN `wx:A` STRIP_ASSUME_TAC)) THEN
       (* b := f(uu), the image of the new point.  Extract via MATCH_MP_TAC
          on total, NOT MP_TAC+ASM_REWRITE: total's own conclusion is the
          existential we want, so ASM_REWRITE would prove it and collapse the
          MP_TAC'd implication, leaving nothing for DISCH_THEN. *)
       SUBGOAL_THEN `?t. t IN D /\ (E:A->A->bool) t p /\ eapply D E f uu t`
         (X_CHOOSE_THEN `b:A` STRIP_ASSUME_TAC) THENL
        [USE_THEN "total" MATCH_MP_TAC THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
       (* wy := wx adjoin b, the image of yy *)
       MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`wx:A`;`b:A`]
              EADJOIN_EXISTS) THEN
       ASM_REWRITE_TAC[] THEN
       DISCH_THEN(X_CHOOSE_THEN `wy:A` (LABEL_TAC "adjwy")) THEN
       SUBGOAL_THEN `(wy:A) IN D` (LABEL_TAC "wyD") THENL
        [ASM_MESON_TAC[EADJOIN_IN]; ALL_TAC] THEN
       (* image of yy under f is wy *)
       SUBGOAL_THEN
        `!m. m IN D
             ==> ((E:A->A->bool) m wy <=> ?x. x IN D /\ E x yy /\
                  eapply D E f x m)`
        (LABEL_TAC "imgy") THENL
        [MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`f:A`;`xx:A`;
                             `uu:A`;`b:A`;
                             `wx:A`;`yy:A`;`wy:A`] EIMAGE_ADJOIN) THEN
         REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
         ALL_TAC] THEN
       (* yy SUBSET n *)
       SUBGOAL_THEN `esubset D E (yy:A) n` (LABEL_TAC "subyn") THENL
        [MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`xx:A`;`uu:A`;`yy:A`]
           EADJOIN_MEM) THEN
         ASM_REWRITE_TAC[] THEN STRIP_TAC THEN
         REWRITE_TAC[esubset] THEN X_GEN_TAC `mm:A` THEN STRIP_TAC THEN
         ASM_MESON_TAC[esubset];
         ALL_TAC] THEN
       (* conclude E yy gam *)
       MP_TAC(SPEC `yy:A` gth) THEN
       ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
       DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN CONJ_TAC THENL
        [FIRST_ASSUM ACCEPT_TAC;
         EXISTS_TAC `wy:A` THEN REPEAT CONJ_TAC THENL
          [FIRST_ASSUM ACCEPT_TAC;
           FIRST_ASSUM ACCEPT_TAC;
           ASM_MESON_TAC[]]];
       ALL_TAC] THEN
     (* absoluteness: n IN gam *)
     SUBGOAL_THEN `(E:A->A->bool) n gam` (LABEL_TAC "nGam") THENL
      [MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`n:A`;`n:A`;`gam:A`]
         EFIN_ABSFAM) THEN
       ASM_REWRITE_TAC[ESUBSET_REFL];
       ALL_TAC] THEN
     (* decode: the image W of n under f satisfies E W fam *)
     MP_TAC(SPEC `n:A` gth) THEN
     ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
     ASM_REWRITE_TAC[ESUBSET_REFL] THEN
     DISCH_THEN(X_CHOOSE_THEN `W:A`
       (CONJUNCTS_THEN2 (LABEL_TAC "WD")
        (CONJUNCTS_THEN2 (LABEL_TAC "imgW") (LABEL_TAC "WfamW")))) THEN
     (* W = p by surjectivity + containment + extensionality *)
     SUBGOAL_THEN `(W:A) = p` SUBST_ALL_TAC THENL
      [FIRST_ASSUM(MATCH_MP_TAC o MATCH_MP ZF_EXTENSIONALITY) THEN
       ASM_REWRITE_TAC[] THEN X_GEN_TAC `m:A` THEN DISCH_TAC THEN
       USE_THEN "imgW" (MP_TAC o SPEC `m:A`) THEN
       ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
       DISCH_THEN SUBST1_TAC THEN EQ_TAC THENL
        [DISCH_THEN(X_CHOOSE_THEN `k:A` STRIP_ASSUME_TAC) THEN ASM_MESON_TAC[];
         DISCH_TAC THEN ASM_MESON_TAC[]];
       FIRST_ASSUM ACCEPT_TAC])))));;

(* ==================================================================== *)
(* F6.3 CCC_COHEN step 5 core:  COHEN_UNION_IS_CONDITION                  *)
(*                                                                       *)
(*   p, q Cohen conditions (E p P, E q P) whose graph-union pq = p U q    *)
(*   is functional  ==>  pq is again a condition (E pq P).                *)
(*                                                                       *)
(* ecohenp states finiteness of a condition as "bijects some n IN om"     *)
(* (the ebij form), so the finiteness round-trip needs BOTH bridges:      *)
(*   E p P, E q P  --(EBIJ_TO_FIN)-->  efin p, efin q                     *)
(*                 --(EFIN_UNION2)-->  efin pq                            *)
(*                 --(EFIN_TO_NAT)-->  ?n IN om. ?f. ebij f n pq.         *)
(* esubset pq ci from EBUNION_MEM + the two esubset _ ci; efunctional pq   *)
(* is supplied (by EFUN_UNION_AGREE at the call site).                    *)
(*                                                                       *)
(* The ecohenp membership characterization is kept as the BOUND theorem   *)
(* cohch (via `fun cohch -> ...`), never LABEL_TAC'd: as an assumption    *)
(* its  !r. r IN D ==> (E r P <=> ...)  shape would let ASM_REWRITE fire  *)
(* on  E _ P  and collapse things (gotcha family B/D/R/T).                *)
(* ==================================================================== *)

let COHEN_UNION_IS_CONDITION = prove
 (`!D (E:A->A->bool) ci om P p q pq.
      model D E ZF_AX /\ eomega D E om /\ ecohenp D E ci om P /\
      p IN D /\ q IN D /\ E p P /\ E q P /\
      ebunion D E p q pq /\ efunctional D E pq
      ==> E pq P`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "mdl om coh pD qD EpP EqP un fpq" THEN
  (* pq IN D *)
  SUBGOAL_THEN `(pq:A) IN D` (LABEL_TAC "pqD") THENL
   [ASM_MESON_TAC[EBUNION_IN]; ALL_TAC] THEN
  (* ecohenp membership characterization, kept BOUND (cohch) *)
  USE_THEN "coh" (MP_TAC o REWRITE_RULE[ecohenp]) THEN
  DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "PD") (fun cohch ->
    (* strip the RHS-triple of E p P into atomic assumptions *)
    USE_THEN "EpP" (fun ep -> MP_TAC(SPEC `p:A` cohch) THEN
      ANTS_TAC THENL
       [FIRST_ASSUM ACCEPT_TAC;
        DISCH_THEN(fun bic -> STRIP_ASSUME_TAC(EQ_MP bic ep))]) THEN
    (* likewise for E q P *)
    USE_THEN "EqP" (fun eq -> MP_TAC(SPEC `q:A` cohch) THEN
      ANTS_TAC THENL
       [FIRST_ASSUM ACCEPT_TAC;
        DISCH_THEN(fun bic -> STRIP_ASSUME_TAC(EQ_MP bic eq))]) THEN
    (* p, q finite via the converse bridge *)
    SUBGOAL_THEN `efin D (E:A->A->bool) p` (LABEL_TAC "finp") THENL
     [ASM_MESON_TAC[EBIJ_TO_FIN]; ALL_TAC] THEN
    SUBGOAL_THEN `efin D (E:A->A->bool) q` (LABEL_TAC "finq") THENL
     [ASM_MESON_TAC[EBIJ_TO_FIN]; ALL_TAC] THEN
    (* union of two finite sets is finite *)
    SUBGOAL_THEN `efin D (E:A->A->bool) pq` (LABEL_TAC "finpq") THENL
     [MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`p:A`;`q:A`;`pq:A`]
        EFIN_UNION2) THEN ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    (* now prove E pq P by the characterization at pq *)
    MP_TAC(SPEC `pq:A` cohch) THEN
    ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN(fun bic -> REWRITE_TAC[bic]) THEN
    REPEAT CONJ_TAC THENL
     [(* esubset pq ci *)
      REWRITE_TAC[esubset] THEN X_GEN_TAC `w:A` THEN STRIP_TAC THEN
      MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`p:A`;`q:A`;`pq:A`]
             EBUNION_MEM) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(MP_TAC o SPEC `w:A` o CONJUNCT2) THEN
      ASM_REWRITE_TAC[] THEN STRIP_TAC THEN ASM_MESON_TAC[esubset];
      (* efunctional pq -- supplied *)
      FIRST_ASSUM ACCEPT_TAC;
      (* ?n IN om. ?f. ebij f n pq -- via EFIN_TO_NAT on efin pq *)
      MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`om:A`;`pq:A`] EFIN_TO_NAT) THEN
      ASM_REWRITE_TAC[] THEN
      DISCH_THEN(X_CHOOSE_THEN `nu:A`
                 (X_CHOOSE_THEN `fu:A` STRIP_ASSUME_TAC)) THEN
      EXISTS_TAC `nu:A` THEN ASM_REWRITE_TAC[] THEN
      EXISTS_TAC `fu:A` THEN FIRST_ASSUM ACCEPT_TAC])));;

(* ==================================================================== *)
(* N2 foundation:  EFIN_IMAGE                                            *)
(*                                                                       *)
(*   The image of a finite set p under an internal single-valued map g   *)
(*   (total on p, with image set img) is finite.                         *)
(*                                                                       *)
(* This is the pull-back-family argument of EBIJ_TO_FIN with the roles   *)
(*   domain  n  |-> p   (a finite set, efin p direct -- no EOMEGA needed) *)
(*   codomain p |-> img (the image, given by its membership char)        *)
(*   bijection f |-> g  (only single-valuedness + totality-into-img used;*)
(*                       no injectivity/surjectivity)                    *)
(* For an arbitrary good family fam of subsets of img, separate           *)
(*    gam = { v SUBSET p : (image of v under g) IN fam }                 *)
(* (imgfam_form / IMGFAM_HOLDS).  gam is a good family for p:             *)
(*   - empty IN gam (image of empty = empty IN fam);                     *)
(*   - adjoin-closed over points u IN p (EIMAGE_ADJOIN; g(u) IN img by    *)
(*     the total clause, so fam's img-adjoin-closure applies).           *)
(* EFIN_ABSFAM at q=c=p gives p IN gam, i.e. (image of p) IN fam; the     *)
(* image of p equals img (both share img's membership char), so img IN    *)
(* fam.  fam arbitrary ==> efin img.                                     *)
(* ==================================================================== *)

let EFIN_IMAGE = prove
 (`!D (E:A->A->bool) g p img.
      model D E ZF_AX /\ efin D E p /\ g IN D /\ img IN D /\
      (!m t t'. m IN D /\ t IN D /\ t' IN D /\
                eapply D E g m t /\ eapply D E g m t' ==> t = t') /\
      (!x. x IN D /\ E x p ==> ?y. y IN D /\ E y img /\ eapply D E g x y) /\
      (!m. m IN D ==> (E m img <=> ?x. x IN D /\ E x p /\ eapply D E g x m))
      ==> efin D E img`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "mdl finp gD imgD sv total imgch" THEN
  (* p IN D from efin p *)
  SUBGOAL_THEN `(p:A) IN D` (LABEL_TAC "pD") THENL
   [ASM_MESON_TAC[efin]; ALL_TAC] THEN
  (* reduce to: for an arbitrary good family fam of subsets of img, img IN *)
  (* fam *)
  REWRITE_TAC[efin] THEN CONJ_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  X_GEN_TAC `fam:A` THEN
  DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "famD")
    (CONJUNCTS_THEN2 (K ALL_TAC)
     (CONJUNCTS_THEN2 (LABEL_TAC "emp") (LABEL_TAC "fadj")))) THEN
  (* base valuation carrying g at slot 18 and fam at slot 19 *)
  ABBREV_TAC `v0 = (18 |-> (g:A)) ((19 |-> (fam:A)) (\k:num. (g:A)))` THEN
  SUBGOAL_THEN `valuation D (v0:num->A)` (LABEL_TAC "valv0") THENL
   [EXPAND_TAC "v0" THEN
    MATCH_MP_TAC VALUATION_VALMOD THEN CONJ_TAC THENL
     [MATCH_MP_TAC VALUATION_VALMOD THEN CONJ_TAC THENL
       [REWRITE_TAC[valuation] THEN FIRST_ASSUM ACCEPT_TAC;
        FIRST_ASSUM ACCEPT_TAC];
      FIRST_ASSUM ACCEPT_TAC];
    ALL_TAC] THEN
  SUBGOAL_THEN `(v0:num->A) 18 = g /\ (v0:num->A) 19 = fam`
    (CONJUNCTS_THEN2 (LABEL_TAC "v18") (LABEL_TAC "v19")) THENL
   [EXPAND_TAC "v0" THEN CONJ_TAC THEN REWRITE_TAC[VALMOD; ARITH_EQ];
    ALL_TAC] THEN
  (* powerset of p as the separation source *)
  MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`p:A`] EPOW_EXISTS) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `powp:A` (LABEL_TAC "pow")) THEN
  SUBGOAL_THEN `(powp:A) IN D` (LABEL_TAC "powpD") THENL
   [ASM_MESON_TAC[epow]; ALL_TAC] THEN
  (* separate gam = { v SUBSET p : image of v under g IN fam } *)
  MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`] ZF_SEPARATION) THEN
  ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  DISCH_THEN(MP_TAC o ISPECL[`imgfam_form`;`20`;`v0:num->A`;`powp:A`]) THEN
  ANTS_TAC THENL
   [CONJ_TAC THENL [FIRST_ASSUM ACCEPT_TAC; FIRST_ASSUM ACCEPT_TAC];
    ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `gam:A`
   (CONJUNCTS_THEN2 (LABEL_TAC "gamD") (fun gamch ->
    (* clean characterization of membership in gam (kept as bound thm GAM) *)
    SUBGOAL_THEN
     `!z. z IN D
          ==> ((E:A->A->bool) z gam <=>
               esubset D E z p /\
               (?w. w IN D /\
                    (!m. m IN D
                         ==> (E m w <=> ?x. x IN D /\ E x z /\
                              eapply D E g x m)) /\
                    E w fam))`
     MP_TAC THENL
     [X_GEN_TAC `z:A` THEN DISCH_TAC THEN
      MP_TAC(SPEC `z:A` gamch) THEN
      ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
      DISCH_THEN SUBST1_TAC THEN
      SUBGOAL_THEN `E (z:A) powp <=> esubset D E z p` SUBST1_TAC THENL
       [ASM_MESON_TAC[epow]; ALL_TAC] THEN
      MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`v0:num->A`;`z:A`]
             IMGFAM_HOLDS) THEN
      ASM_REWRITE_TAC[] THEN DISCH_THEN SUBST1_TAC THEN
      ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    DISCH_THEN(fun gth ->
     (* gam contains the empty set *)
     SUBGOAL_THEN `?z. z IN D /\ eempty D (E:A->A->bool) z /\ E z gam`
       (LABEL_TAC "base") THENL
      [USE_THEN "emp" (X_CHOOSE_THEN `e0:A` STRIP_ASSUME_TAC) THEN
       EXISTS_TAC `e0:A` THEN ASM_REWRITE_TAC[] THEN
       MP_TAC(SPEC `e0:A` gth) THEN
       ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
       DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN CONJ_TAC THENL
        [MATCH_MP_TAC EEMPTY_SUBSET THEN FIRST_ASSUM ACCEPT_TAC;
         EXISTS_TAC `e0:A` THEN ASM_REWRITE_TAC[] THEN
         X_GEN_TAC `m:A` THEN DISCH_TAC THEN ASM_MESON_TAC[eempty]];
       ALL_TAC] THEN
     (* gam is closed under adjoining a point of p *)
     SUBGOAL_THEN
      `!x u y. x IN D /\ u IN D /\ y IN D /\ (E:A->A->bool) x gam /\ E u p /\
               eadjoin D E x u y
               ==> E y gam`
      (LABEL_TAC "adjcl") THENL
      [MAP_EVERY X_GEN_TAC [`xx:A`;`uu:A`;`yy:A`] THEN STRIP_TAC THEN
       (* decode E xx gam via GAM *)
       SUBGOAL_THEN
        `esubset D E (xx:A) p /\
         (?w. w IN D /\
              (!m. m IN D
                   ==> (E m w <=> ?x. x IN D /\ E x xx /\ eapply D E g x m)) /\
              E w fam)`
        MP_TAC THENL
        [MP_TAC(SPEC `xx:A` gth) THEN
         ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
         DISCH_THEN(fun th -> REWRITE_TAC[GSYM th]) THEN
         FIRST_ASSUM ACCEPT_TAC;
         ALL_TAC] THEN
       DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "subxp")
         (X_CHOOSE_THEN `wx:A` STRIP_ASSUME_TAC)) THEN
       (* b := g(uu), the image of the new point, IN img.  Extract via
          MATCH_MP_TAC on total (its conclusion is the existential itself). *)
       SUBGOAL_THEN `?t. t IN D /\ (E:A->A->bool) t img /\ eapply D E g uu t`
         (X_CHOOSE_THEN `b:A` STRIP_ASSUME_TAC) THENL
        [USE_THEN "total" MATCH_MP_TAC THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
       (* wy := wx adjoin b, the image of yy *)
       MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`wx:A`;`b:A`]
              EADJOIN_EXISTS) THEN
       ASM_REWRITE_TAC[] THEN
       DISCH_THEN(X_CHOOSE_THEN `wy:A` (LABEL_TAC "adjwy")) THEN
       SUBGOAL_THEN `(wy:A) IN D` (LABEL_TAC "wyD") THENL
        [ASM_MESON_TAC[EADJOIN_IN]; ALL_TAC] THEN
       (* image of yy under g is wy *)
       SUBGOAL_THEN
        `!m. m IN D
             ==> ((E:A->A->bool) m wy <=> ?x. x IN D /\ E x yy /\
                  eapply D E g x m)`
        (LABEL_TAC "imgy") THENL
        [MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`g:A`;`xx:A`;
                             `uu:A`;`b:A`;
                             `wx:A`;`yy:A`;`wy:A`] EIMAGE_ADJOIN) THEN
         REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
         ALL_TAC] THEN
       (* yy SUBSET p *)
       SUBGOAL_THEN `esubset D E (yy:A) p` (LABEL_TAC "subyp") THENL
        [MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`xx:A`;`uu:A`;`yy:A`]
           EADJOIN_MEM) THEN
         ASM_REWRITE_TAC[] THEN STRIP_TAC THEN
         REWRITE_TAC[esubset] THEN X_GEN_TAC `mm:A` THEN STRIP_TAC THEN
         ASM_MESON_TAC[esubset];
         ALL_TAC] THEN
       (* conclude E yy gam *)
       MP_TAC(SPEC `yy:A` gth) THEN
       ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
       DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN CONJ_TAC THENL
        [FIRST_ASSUM ACCEPT_TAC;
         EXISTS_TAC `wy:A` THEN REPEAT CONJ_TAC THENL
          [FIRST_ASSUM ACCEPT_TAC;
           FIRST_ASSUM ACCEPT_TAC;
           ASM_MESON_TAC[]]];
       ALL_TAC] THEN
     (* absoluteness: p IN gam *)
     SUBGOAL_THEN `(E:A->A->bool) p gam` (LABEL_TAC "pGam") THENL
      [MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`p:A`;`p:A`;`gam:A`]
         EFIN_ABSFAM) THEN
       ASM_REWRITE_TAC[ESUBSET_REFL];
       ALL_TAC] THEN
     (* decode: the image W of p under g satisfies E W fam *)
     MP_TAC(SPEC `p:A` gth) THEN
     ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
     ASM_REWRITE_TAC[ESUBSET_REFL] THEN
     DISCH_THEN(X_CHOOSE_THEN `W:A`
       (CONJUNCTS_THEN2 (LABEL_TAC "WD")
        (CONJUNCTS_THEN2 (LABEL_TAC "imgW") (LABEL_TAC "WfamW")))) THEN
     (* W = img: both are the image of p under g *)
     SUBGOAL_THEN `(W:A) = img` SUBST_ALL_TAC THENL
      [FIRST_ASSUM(MATCH_MP_TAC o MATCH_MP ZF_EXTENSIONALITY) THEN
       ASM_REWRITE_TAC[] THEN X_GEN_TAC `m:A` THEN DISCH_TAC THEN
       USE_THEN "imgW" (MP_TAC o SPEC `m:A`) THEN
       ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
       DISCH_THEN SUBST1_TAC THEN
       USE_THEN "imgch" (MP_TAC o SPEC `m:A`) THEN
       ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
       DISCH_THEN SUBST1_TAC THEN REFL_TAC;
       FIRST_ASSUM ACCEPT_TAC])))));;

(* ==================================================================== *)
(* N2.2  EPOW_ADJOIN  (membership characterization / set identity)       *)
(*                                                                       *)
(*   epow(u adjoin a) = epow(u)  UNION  { t adjoin a : t IN epow u }.     *)
(*                                                                       *)
(* Stated as the membership characterization of the powerset of the      *)
(* adjoin (pua = epow(u+{a})): for w IN D,                               *)
(*    E w pua  <=>  E w pu  \/  (?t. t IN D /\ E t pu /\ eadjoin t a w). *)
(* Purely set-theoretic (no finiteness).  Split on a IN w:               *)
(*   a NOTIN w:  w SUBSET u+{a} with a NOTIN w forces w SUBSET u.         *)
(*   a IN w   :  t := w \ {a} (ediff w {a}) is SUBSET u, and             *)
(*               w = t adjoin a (EADJOIN_CHAR).                          *)
(* Reuses ediff/EDIFF_EXISTS, epair singleton {a}, eadjoin/EADJOIN_MEM/   *)
(* EADJOIN_CHAR, epow membership (= esubset).                            *)
(* ==================================================================== *)

let EPOW_ADJOIN = prove
 (`!D (E:A->A->bool) u a ua pu pua.
      model D E ZF_AX /\ u IN D /\ a IN D /\
      eadjoin D E u a ua /\ epow D E u pu /\ epow D E ua pua
      ==> !w. w IN D
              ==> (E w pua <=>
                   E w pu \/
                   (?t. t IN D /\ E t pu /\ eadjoin D E t a w))`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "mdl uD aD adj epu epua" THEN
  SUBGOAL_THEN `(ua:A) IN D` (LABEL_TAC "uaD") THENL
   [ASM_MESON_TAC[EADJOIN_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `(pu:A) IN D` (LABEL_TAC "puD") THENL
   [ASM_MESON_TAC[EPOW_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `(pua:A) IN D` (LABEL_TAC "puaD") THENL
   [ASM_MESON_TAC[EPOW_IN]; ALL_TAC] THEN
  SUBGOAL_THEN
    `!z. z IN D ==> ((E:A->A->bool) z pu <=> esubset D E z u)`
    (LABEL_TAC "mpu") THENL
   [ASM_MESON_TAC[epow]; ALL_TAC] THEN
  SUBGOAL_THEN
    `!z. z IN D ==> ((E:A->A->bool) z pua <=> esubset D E z ua)`
    (LABEL_TAC "mpua") THENL
   [ASM_MESON_TAC[epow]; ALL_TAC] THEN
  SUBGOAL_THEN
    `!z. z IN D ==> ((E:A->A->bool) z ua <=> E z u \/ z = a)`
    (LABEL_TAC "mua") THENL
   [MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`u:A`;`a:A`;`ua:A`]
           EADJOIN_MEM) THEN
    ASM_REWRITE_TAC[] THEN MESON_TAC[];
    ALL_TAC] THEN
  X_GEN_TAC `w:A` THEN DISCH_TAC THEN
  (* substitute the two top-level epow-memberships by esubset.  Do NOT use
     ASM_REWRITE here: mpu/mpua are labeled assumptions and would fire as
     conditional rewrites, collapsing the T ==> _ residue and breaking the
     following DISCH (gotcha family B/D/R/T). *)
  SUBGOAL_THEN `(E:A->A->bool) w pua <=> esubset D E w ua` SUBST1_TAC THENL
   [ASM_MESON_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) w pu <=> esubset D E w u` SUBST1_TAC THENL
   [ASM_MESON_TAC[]; ALL_TAC] THEN
  EQ_TAC THENL
   [(* -------- forward: esubset w ua ==> ... -------- *)
    DISCH_TAC THEN ASM_CASES_TAC `(E:A->A->bool) a w` THENL
     [(* a IN w: right disjunct with t = w \ {a} *)
      DISJ2_TAC THEN
      SUBGOAL_THEN `?sa. epair D (E:A->A->bool) a a sa`
        (X_CHOOSE_THEN `sa:A` (LABEL_TAC "esa")) THENL
       [ASM_MESON_TAC[EPAIR_EXISTS]; ALL_TAC] THEN
      SUBGOAL_THEN `(sa:A) IN D` (LABEL_TAC "saD") THENL
       [ASM_MESON_TAC[EPAIR_IN]; ALL_TAC] THEN
      SUBGOAL_THEN `?t. ediff D (E:A->A->bool) w sa t`
        (X_CHOOSE_THEN `t:A` (LABEL_TAC "edt")) THENL
       [ASM_MESON_TAC[EDIFF_EXISTS]; ALL_TAC] THEN
      SUBGOAL_THEN `(t:A) IN D` (LABEL_TAC "tD") THENL
       [ASM_MESON_TAC[ediff]; ALL_TAC] THEN
      SUBGOAL_THEN
        `!m. m IN D ==> ((E:A->A->bool) m t <=> E m w /\ ~(m = a))`
        (LABEL_TAC "mt") THENL
       [USE_THEN "edt" MP_TAC THEN USE_THEN "esa" MP_TAC THEN
        REWRITE_TAC[ediff; epair] THEN MESON_TAC[];
        ALL_TAC] THEN
      SUBGOAL_THEN `esubset D (E:A->A->bool) t u` (LABEL_TAC "subtu") THENL
       [REWRITE_TAC[esubset] THEN X_GEN_TAC `m:A` THEN STRIP_TAC THEN
        SUBGOAL_THEN `(E:A->A->bool) m w /\ ~(m = a)` STRIP_ASSUME_TAC THENL
         [ASM_MESON_TAC[]; ALL_TAC] THEN
        ASM_MESON_TAC[esubset];
        ALL_TAC] THEN
      EXISTS_TAC `t:A` THEN REPEAT CONJ_TAC THENL
       [FIRST_ASSUM ACCEPT_TAC;
        ASM_MESON_TAC[];
        MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`t:A`;`a:A`;`w:A`]
          EADJOIN_CHAR) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
        DISCH_THEN SUBST1_TAC THEN
        X_GEN_TAC `m:A` THEN DISCH_TAC THEN ASM_MESON_TAC[]];
      (* ~(a IN w): left disjunct esubset w u *)
      DISJ1_TAC THEN REWRITE_TAC[esubset] THEN
      X_GEN_TAC `m:A` THEN STRIP_TAC THEN
      SUBGOAL_THEN `(E:A->A->bool) m ua` MP_TAC THENL
       [ASM_MESON_TAC[esubset]; ALL_TAC] THEN
      ASM_MESON_TAC[]];
    (* -------- backward: ... ==> esubset w ua -------- *)
    STRIP_TAC THENL
     [(* esubset w u *)
      REWRITE_TAC[esubset] THEN X_GEN_TAC `m:A` THEN STRIP_TAC THEN
      ASM_MESON_TAC[esubset];
      (* witness t: E t pu /\ eadjoin t a w *)
      MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`t:A`;`a:A`;`w:A`]
             EADJOIN_MEM) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(MP_TAC o CONJUNCT2) THEN STRIP_TAC THEN
      SUBGOAL_THEN `esubset D (E:A->A->bool) t u` MP_TAC THENL
       [ASM_MESON_TAC[]; ALL_TAC] THEN
      REWRITE_TAC[esubset] THEN DISCH_TAC THEN
      X_GEN_TAC `m:A` THEN STRIP_TAC THEN
      ASM_MESON_TAC[]]]);;

(* ==================================================================== *)
(* N2.3  powfin_form + POWFIN_HOLDS                                       *)
(*                                                                       *)
(* Separation predicate on slot 20 (= u, the separation variable) with   *)
(* parameter slot 18 (= om):  "the powerset of u is internally finite",  *)
(* i.e. "?P. (P = powerset u) /\ (P bijects some n IN om)".              *)
(*                                                                       *)
(*   powfin_form =                                                       *)
(*     ?? 21 ( (!! 22 ((22 %% 21) <-> subset_form 22 20))     [P = pow u]*)
(*          && (?? 24 ((24 %% 18) && bijform 24 21)) )   [P ~ some n<om] *)
(*                                                                       *)
(* Slots: 21 = P, 22 = w (subset_form 22 20 uses 23 internally),         *)
(*        24 = n (bijform 24 21 uses 25..29 internally).  No clashes     *)
(*        with the free 18, 20.                                          *)
(* HOLDS bridge assembled exactly as BIJFAM_HOLDS: HOLDS_EX/HOLDS_AND,    *)
(* HOLDS_IFF+HOLDS_MEM+HOLDS_SUBSET_FORM (left), HOLDS_MEM+               *)
(* HOLDS_BIJFORM_EBIJ (right); fold the outer ?P into epow.              *)
(*                                                                       *)
(* ** Two tactic gotchas root-caused while proving this (both recur      *)
(*    across the HOLDS_* bridge family):                                 *)
(*  (1) The pointwise congruence used under !!/?? MUST be the GUARDED     *)
(*      form  (!x. x IN D ==> (R x <=> S x)) ==> ...  -- NOT the          *)
(*      unguarded (!x. R x <=> S x) ==> ...  The right conjunct needs     *)
(*      `n IN D` (via DISCH_TAC after X_GEN) to discharge the            *)
(*      valuation D ((24|->n)...) subgoal feeding HOLDS_BIJFORM_EBIJ;     *)
(*      with the unguarded congruence there is no n IN D, so             *)
(*      ASM_MESON_TAC[VALUATION_VALMOD] cannot prove valuation and       *)
(*      searches to the ceiling ("solve_goal: Too deep").                *)
(*  (2) The outer ?P-fold is done MESON-FREE (explicit EQ_MP + CONJUNCT   *)
(*      + ACCEPT_TAC): an ASM_MESON there pulls the labeled "body" (a     *)
(*      !P-quantified holds-iff) into the search and also blows up.       *)
(* ==================================================================== *)

let powfin_form = new_definition
  `powfin_form =
     ?? 21 ((!! 22 ((22 %% 21) <-> subset_form 22 20)) &&
            (?? 24 ((24 %% 18) && bijform 24 21)))`;;

let POWFIN_HOLDS = prove
 (`!D (E:A->A->bool) v u.
      model D E ZF_AX /\ valuation D v /\ u IN D
      ==> (holds D E ((20 |-> u) v) powfin_form <=>
           ?P. epow D E u P /\
               (?n. n IN D /\ E n (v 18) /\ ?f. ebij D E f n P))`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[powfin_form] THEN
  SUBGOAL_THEN `valuation D ((20 |-> (u:A)) v)` (LABEL_TAC "vu") THENL
   [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
  REWRITE_TAC[HOLDS_EX] THEN
  SUBGOAL_THEN
   `!P:A. P IN D
      ==> (holds D E ((21 |-> P) ((20 |-> (u:A)) v))
             ((!! 22 ((22 %% 21) <-> subset_form 22 20)) &&
              (?? 24 ((24 %% 18) && bijform 24 21))) <=>
           (!w. w IN D ==> (E w P <=> esubset D E w u)) /\
           (?n. n IN D /\ E n (v 18) /\ ?f. ebij D E f n P))`
   (LABEL_TAC "body") THENL
   [X_GEN_TAC `P:A` THEN DISCH_TAC THEN
    SUBGOAL_THEN `valuation D ((21 |-> (P:A)) ((20 |-> (u:A)) v))`
     (LABEL_TAC "vP") THENL [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
    REWRITE_TAC[HOLDS_AND] THEN BINOP_TAC THENL
     [(* LEFT: P = powerset u *)
      REWRITE_TAC[holds] THEN
      MATCH_MP_TAC(MESON[]
        `(!a:A. a IN D ==> (R a <=> S a))
         ==> ((!a. a IN D ==> R a) <=> (!a. a IN D ==> S a))`) THEN
      X_GEN_TAC `a:A` THEN DISCH_TAC THEN
      REWRITE_TAC[HOLDS_IFF; HOLDS_MEM; HOLDS_SUBSET_FORM] THEN
      REWRITE_TAC[VALMOD; ARITH_EQ];
      (* RIGHT: P bijects some n IN om *)
      REWRITE_TAC[HOLDS_EX] THEN
      MATCH_MP_TAC(MESON[]
        `(!n:A. n IN D ==> (R n <=> S n))
         ==> ((?n. n IN D /\ R n) <=> (?n. n IN D /\ S n))`) THEN
      X_GEN_TAC `n:A` THEN DISCH_TAC THEN
      SUBGOAL_THEN
        `valuation D ((24 |-> (n:A)) ((21 |-> (P:A)) ((20 |-> (u:A)) v)))`
        ASSUME_TAC THENL [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
      REWRITE_TAC[HOLDS_AND; HOLDS_MEM] THEN
      MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;
        `(24 |-> (n:A)) ((21 |-> (P:A)) ((20 |-> (u:A)) v))`;`24`;`21`]
        HOLDS_BIJFORM_EBIJ) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
      REWRITE_TAC[VALMOD; ARITH_EQ]];
    ALL_TAC] THEN
  (* Fold the outer ?P into epow -- MESON-FREE (see header gotcha (2)). *)
  EQ_TAC THENL
   [DISCH_THEN(X_CHOOSE_THEN `P:A`
       (CONJUNCTS_THEN2 (LABEL_TAC "PD") (LABEL_TAC "hb"))) THEN
    EXISTS_TAC `P:A` THEN
    USE_THEN "body" (MP_TAC o SPEC `P:A`) THEN ANTS_TAC THENL
     [USE_THEN "PD" ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN(fun th ->
      USE_THEN "hb" (fun hb ->
        let rhs' = EQ_MP th hb in
        CONJ_TAC THENL
         [REWRITE_TAC[epow] THEN CONJ_TAC THENL
           [USE_THEN "PD" ACCEPT_TAC; ACCEPT_TAC(CONJUNCT1 rhs')];
          ACCEPT_TAC(CONJUNCT2 rhs')]));
    DISCH_THEN(X_CHOOSE_THEN `P:A`
       (CONJUNCTS_THEN2 (LABEL_TAC "ep") (LABEL_TAC "rest"))) THEN
    EXISTS_TAC `P:A` THEN
    USE_THEN "ep" (fun e -> MP_TAC(REWRITE_RULE[epow] e)) THEN
    DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "PD") (LABEL_TAC "wsub")) THEN
    CONJ_TAC THENL
     [USE_THEN "PD" ACCEPT_TAC;
      USE_THEN "body" (fun bth -> USE_THEN "PD" (fun pd ->
        MP_TAC(MP (SPEC `P:A` bth) pd))) THEN
      DISCH_THEN(fun iff ->
        USE_THEN "wsub" (fun ws -> USE_THEN "rest" (fun rs ->
          ACCEPT_TAC(EQ_MP (SYM iff) (CONJ ws rs)))))]]);;

(* dblpair_form + HOLDS_DBLPAIR.
   Object formula coding  w = <t, t adjoin x>  for the doubling map used to
   build the graph  gx = {<t, t+{x}> : t IN epow u}  via ZF_REPLACEMENT.
   Slot convention (matches the ZF_REPLACEMENT application x-slot=0,y-slot=1):
     slot 0 = t (domain elt),  slot 1 = w (the pair value),
     slot 2 = x (adjoin parameter);  scratch: 7 = sing = {x}, 9 = b = t+{x}.
   HOLDS char left in RAW epair/ebunion/eopair form -- purely mechanical
   (HOLDS_EX/HOLDS_AND + HOLDS_PAIR_FORM/BUNION_FORM/OPAIR_FORM); the fold
   into eadjoin happens later in EDBLMAP_EXISTS (eadjoin def is exactly
   ?s. epair u u s /\ ebunion x s y). *)

let dblpair_form = new_definition
  `dblpair_form =
     ?? 7 (?? 9 (pair_form 2 2 7 && bunion_form 0 7 9 && opair_form 0 9 1))`;;

let HOLDS_DBLPAIR = prove
 (`!D (E:A->A->bool) v.
      model D E ZF_AX /\ valuation D v
      ==> (holds D E v dblpair_form <=>
           ?sing. sing IN D /\ ?b. b IN D /\
                  epair D E (v 2) (v 2) sing /\
                  ebunion D E (v 0) sing b /\
                  eopair D E (v 0) b (v 1))`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[dblpair_form; HOLDS_EX] THEN
  MATCH_MP_TAC(MESON[]
    `(!sing:A. sing IN D ==> (R sing <=> S sing))
     ==> ((?sing. sing IN D /\ R sing) <=> (?sing. sing IN D /\ S sing))`) THEN
  X_GEN_TAC `sing:A` THEN DISCH_TAC THEN
  SUBGOAL_THEN `valuation D ((7 |-> (sing:A)) v)` (LABEL_TAC "v7") THENL
   [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
  MATCH_MP_TAC(MESON[]
    `(!b:A. b IN D ==> (R b <=> S b))
     ==> ((?b. b IN D /\ R b) <=> (?b. b IN D /\ S b))`) THEN
  X_GEN_TAC `b:A` THEN DISCH_TAC THEN
  SUBGOAL_THEN `valuation D ((9 |-> (b:A)) ((7 |-> (sing:A)) v))`
    (LABEL_TAC "v9") THENL [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
  REWRITE_TAC[HOLDS_AND] THEN
  ASM_SIMP_TAC[HOLDS_PAIR_FORM; HOLDS_BUNION_FORM; HOLDS_OPAIR_FORM] THEN
  REWRITE_TAC[VALMOD; ARITH_EQ]);;

(* EDBLGRAPH_EXISTS -- build the doubling-map graph
     gx = { <t, t adjoin x> : t IN dm }
   via ZF_REPLACEMENT + dblpair_form, exactly mirroring EGRAPH_EXISTS.
   Membership char given in eadjoin/eopair form (ready for EGRAPH_APPLY). *)

let EDBLGRAPH_EXISTS = prove
 (`!D (E:A->A->bool) dm x.
     model D E ZF_AX /\ dm IN D /\ x IN D
     ==> ?g. g IN D /\
             !w. w IN D
                 ==> (E w g <=>
                      ?t b. t IN D /\ b IN D /\ E t dm /\
                            eadjoin D E t x b /\ eopair D E t b w)`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `valuation D (\i:num. x:A)` (LABEL_TAC "v0") THENL
   [REWRITE_TAC[valuation] THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN
   `!t w:A. t IN D /\ w IN D
      ==> (holds D E ((1 |-> w) ((0 |-> t) (\i:num. x:A))) dblpair_form <=>
           ?b. b IN D /\ eadjoin D E t x b /\ eopair D E t b w)`
   (LABEL_TAC "gr") THENL
   [REPEAT STRIP_TAC THEN
    MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`;
      `(1 |-> (w:A)) ((0 |-> (t:A)) (\i:num. x:A))`] HOLDS_DBLPAIR) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[] THEN MATCH_MP_TAC VALUATION_VALMOD THEN
      ASM_REWRITE_TAC[] THEN MATCH_MP_TAC VALUATION_VALMOD THEN
      ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    REWRITE_TAC[VALMOD] THEN CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN
    REWRITE_TAC[] THEN REWRITE_TAC[eadjoin] THEN
    EQ_TAC THENL
     [DISCH_THEN(X_CHOOSE_THEN `sing:A` (CONJUNCTS_THEN2 ASSUME_TAC
        (X_CHOOSE_THEN `b:A` STRIP_ASSUME_TAC))) THEN
      EXISTS_TAC `b:A` THEN ASM_REWRITE_TAC[] THEN
      EXISTS_TAC `sing:A` THEN ASM_REWRITE_TAC[];
      DISCH_THEN(X_CHOOSE_THEN `b:A` (CONJUNCTS_THEN2 ASSUME_TAC
        (CONJUNCTS_THEN2 (X_CHOOSE_THEN `sing:A` STRIP_ASSUME_TAC)
                         ASSUME_TAC))) THEN
      EXISTS_TAC `sing:A` THEN
      SUBGOAL_THEN `(sing:A) IN D` ASSUME_TAC THENL
       [ASM_MESON_TAC[EPAIR_IN]; ALL_TAC] THEN
      ASM_REWRITE_TAC[] THEN EXISTS_TAC `b:A` THEN ASM_REWRITE_TAC[]];
    ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`] ZF_REPLACEMENT) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(MP_TAC o SPECL
    [`dblpair_form`; `0`; `1`; `(\i:num. x:A)`; `dm:A`]) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[ARITH_EQ] THEN
    X_GEN_TAC `t:A` THEN STRIP_TAC THEN
    SUBGOAL_THEN `?b. eadjoin D (E:A->A->bool) t x b`
      (X_CHOOSE_TAC `b:A`) THENL
     [ASM_MESON_TAC[EADJOIN_EXISTS]; ALL_TAC] THEN
    SUBGOAL_THEN `(b:A) IN D` ASSUME_TAC THENL
     [ASM_MESON_TAC[EADJOIN_IN]; ALL_TAC] THEN
    SUBGOAL_THEN `?w. eopair D (E:A->A->bool) t b w`
      (X_CHOOSE_TAC `w:A`) THENL
     [ASM_MESON_TAC[EOPAIR_EXISTS]; ALL_TAC] THEN
    SUBGOAL_THEN `(w:A) IN D` ASSUME_TAC THENL
     [ASM_MESON_TAC[EOPAIR_IN]; ALL_TAC] THEN
    EXISTS_TAC `w:A` THEN ASM_REWRITE_TAC[] THEN
    X_GEN_TAC `w':A` THEN
    DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC MP_TAC) THEN
    USE_THEN "gr" (MP_TAC o SPECL [`t:A`; `w':A`]) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    DISCH_THEN(X_CHOOSE_THEN `b':A` STRIP_ASSUME_TAC) THEN
    SUBGOAL_THEN `b':A = b` SUBST_ALL_TAC THENL
     [ASM_MESON_TAC[EADJOIN_UNIQUE]; ALL_TAC] THEN
    ASM_MESON_TAC[EOPAIR_UNIQUE];
    ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `g:A` (CONJUNCTS_THEN2 ASSUME_TAC
    (LABEL_TAC "gg"))) THEN
  EXISTS_TAC `g:A` THEN ASM_REWRITE_TAC[] THEN
  X_GEN_TAC `w:A` THEN DISCH_TAC THEN
  USE_THEN "gg" (MP_TAC o SPEC `w:A`) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  EQ_TAC THENL
   [DISCH_THEN(X_CHOOSE_THEN `u:A` STRIP_ASSUME_TAC) THEN
    UNDISCH_TAC
     `holds D E ((1 |-> (w:A)) ((0 |-> (u:A)) (\i:num. x:A)))
      dblpair_form` THEN
    USE_THEN "gr" (MP_TAC o SPECL [`u:A`; `w:A`]) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    DISCH_THEN(X_CHOOSE_THEN `b:A` STRIP_ASSUME_TAC) THEN
    MAP_EVERY EXISTS_TAC [`u:A`; `b:A`] THEN ASM_REWRITE_TAC[];
    DISCH_THEN(X_CHOOSE_THEN `t:A`
      (X_CHOOSE_THEN `b:A` STRIP_ASSUME_TAC)) THEN
    EXISTS_TAC `t:A` THEN ASM_REWRITE_TAC[] THEN
    USE_THEN "gr" (MP_TAC o SPECL [`t:A`; `w:A`]) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    EXISTS_TAC `b:A` THEN ASM_REWRITE_TAC[]]);;

(* EDBLMAP_EXISTS -- package the doubling map for
   EFIN_IMAGE: graph g + image img, with eapply char, single-valuedness,
   totality-into-img, and the image membership characterization.
   Uses EDBLGRAPH_EXISTS (graph), EGRAPH_APPLY (apply char), ECOLLRANGE_EXISTS
   (range = image). *)

let EDBLMAP_EXISTS = prove
 (`!D (E:A->A->bool) dm x.
     model D E ZF_AX /\ dm IN D /\ x IN D
     ==> ?g img.
           g IN D /\ img IN D /\
           (!t s. t IN D /\ s IN D
                  ==> (eapply D E g t s <=> E t dm /\ eadjoin D E t x s)) /\
           (!m t t'. m IN D /\ t IN D /\ t' IN D /\
                     eapply D E g m t /\ eapply D E g m t' ==> t = t') /\
           (!t. t IN D /\ E t dm
                ==> ?s. s IN D /\ E s img /\ eapply D E g t s) /\
           (!m. m IN D
                ==> (E m img <=> ?t. t IN D /\ E t dm /\ eapply D E g t m))`,
  REPEAT STRIP_TAC THEN
  MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `dm:A`; `x:A`]
    EDBLGRAPH_EXISTS) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `g:A` (CONJUNCTS_THEN2 ASSUME_TAC
    (LABEL_TAC "gc"))) THEN
  (* --- eapply characterization via EGRAPH_APPLY --- *)
  SUBGOAL_THEN
   `!t s:A. t IN D /\ s IN D
      ==> (eapply D E g t s <=> E t dm /\ eadjoin D E t x s)`
   (LABEL_TAC "ac") THENL
   [REPEAT STRIP_TAC THEN
    MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`;
      `\a c:A. eadjoin D E a x c`; `dm:A`; `g:A`; `t:A`; `s:A`]
      EGRAPH_APPLY) THEN
    BETA_TAC THEN ANTS_TAC THENL
     [ASM_REWRITE_TAC[] THEN X_GEN_TAC `pp:A` THEN DISCH_TAC THEN
      USE_THEN "gc" (MP_TAC o SPEC `pp:A`) THEN ANTS_TAC THENL
       [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]);
      DISCH_THEN(fun th -> REWRITE_TAC[th])];
    ALL_TAC] THEN
  (* --- single-valuedness --- *)
  SUBGOAL_THEN
   `!m t t':A. m IN D /\ t IN D /\ t' IN D /\
               eapply D E g m t /\ eapply D E g m t' ==> t = t'`
   (LABEL_TAC "sv") THENL
   [REPEAT STRIP_TAC THEN
    MATCH_MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `m:A`; `x:A`;
      `t:A`; `t':A`] EADJOIN_UNIQUE) THEN
    ASM_REWRITE_TAC[] THEN CONJ_TAC THEN ASM_MESON_TAC[];
    ALL_TAC] THEN
  (* --- image via ECOLLRANGE_EXISTS --- *)
  MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `g:A`] ECOLLRANGE_EXISTS) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `img:A` (CONJUNCTS_THEN2 ASSUME_TAC
    (LABEL_TAC "rng"))) THEN
  MAP_EVERY EXISTS_TAC [`g:A`; `img:A`] THEN ASM_REWRITE_TAC[] THEN
  CONJ_TAC THENL
   [(* --- totality: t IN dm ==> ?s IN img. eapply g t s --- *)
    X_GEN_TAC `t:A` THEN STRIP_TAC THEN
    SUBGOAL_THEN `?b. eadjoin D (E:A->A->bool) t x b`
      (X_CHOOSE_TAC `b:A`) THENL
     [ASM_MESON_TAC[EADJOIN_EXISTS]; ALL_TAC] THEN
    SUBGOAL_THEN `(b:A) IN D` ASSUME_TAC THENL
     [ASM_MESON_TAC[EADJOIN_IN]; ALL_TAC] THEN
    SUBGOAL_THEN `eapply D (E:A->A->bool) g t b` ASSUME_TAC THENL
     [USE_THEN "ac" (MP_TAC o SPECL [`t:A`; `b:A`]) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    EXISTS_TAC `b:A` THEN REPEAT CONJ_TAC THENL
     [FIRST_ASSUM ACCEPT_TAC; ALL_TAC; FIRST_ASSUM ACCEPT_TAC] THEN
    USE_THEN "rng" (MP_TAC o SPEC `b:A`) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    UNDISCH_TAC `eapply D (E:A->A->bool) g t b` THEN REWRITE_TAC[eapply] THEN
    DISCH_THEN(X_CHOOSE_THEN `z:A` STRIP_ASSUME_TAC) THEN
    ASM_MESON_TAC[EOPAIR_IN];
    (* --- image membership characterization --- *)
    X_GEN_TAC `m:A` THEN DISCH_TAC THEN
    USE_THEN "rng" (MP_TAC o SPEC `m:A`) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    EQ_TAC THENL
     [DISCH_THEN(X_CHOOSE_THEN `p:A`
         (CONJUNCTS_THEN2 ASSUME_TAC
            (X_CHOOSE_THEN `u:A` STRIP_ASSUME_TAC))) THEN
      SUBGOAL_THEN `eapply D (E:A->A->bool) g u m` ASSUME_TAC THENL
       [REWRITE_TAC[eapply] THEN EXISTS_TAC `p:A` THEN ASM_REWRITE_TAC[];
        ALL_TAC] THEN
      EXISTS_TAC `u:A` THEN REPEAT CONJ_TAC THENL
       [FIRST_ASSUM ACCEPT_TAC; ALL_TAC; FIRST_ASSUM ACCEPT_TAC] THEN
      USE_THEN "ac" (MP_TAC o SPECL [`u:A`; `m:A`]) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      ASM_MESON_TAC[];
      DISCH_THEN(X_CHOOSE_THEN `t:A` STRIP_ASSUME_TAC) THEN
      UNDISCH_TAC `eapply D (E:A->A->bool) g t m` THEN REWRITE_TAC[eapply] THEN
      DISCH_THEN(X_CHOOSE_THEN `z:A` STRIP_ASSUME_TAC) THEN
      ASM_MESON_TAC[EOPAIR_IN]]]);;

(* EFIN_POW -- the powerset of an internally-finite
   set is internally finite.
   Route: EFIN_ABSFAM induction on p, separation family
     gam = { u SUBSET p : powfin(u) }   (powfin_form / POWFIN_HOLDS)
   Base: epow(0) = {0} bijects some n IN om  (EFIN_EMPTY + EFIN_ADJOIN +
         EFIN_TO_NAT).
   Adjoin step u |-> u+{x}: epow(u+{x}) = epow(u) UNION {t+{x}:t IN epow u}
         (EPOW_ADJOIN); epow(u) finite (EBIJ_TO_FIN), image finite
         (EDBLMAP_EXISTS + EFIN_IMAGE), union finite (EFIN_UNION2); back to
         powfin via EFIN_TO_NAT.
   Decode: powfin(p) gives P = epow p, P bijects n IN om, so efin(pp)
         (EPOW_UNIQUE + EBIJ_TO_FIN). *)

let EFIN_POW = prove
 (`!D (E:A->A->bool) om p pp.
      model D E ZF_AX /\ eomega D E om /\ efin D E p /\ epow D E p pp
      ==> efin D E pp`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "mdl omega finp powpp" THEN
  SUBGOAL_THEN `(p:A) IN D` (LABEL_TAC "pD") THENL
   [ASM_MESON_TAC[efin]; ALL_TAC] THEN
  SUBGOAL_THEN `(pp:A) IN D` (LABEL_TAC "ppD") THENL
   [ASM_MESON_TAC[EPOW_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `(om:A) IN D` (LABEL_TAC "omD") THENL
   [ASM_MESON_TAC[EOMEGA_IN]; ALL_TAC] THEN
  (* base valuation carrying om at slot 18 *)
  ABBREV_TAC `v0 = (18 |-> (om:A)) (\k:num. (om:A))` THEN
  SUBGOAL_THEN `valuation D (v0:num->A)` (LABEL_TAC "valv0") THENL
   [EXPAND_TAC "v0" THEN REWRITE_TAC[valuation; VALMOD] THEN
    GEN_TAC THEN COND_CASES_TAC THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(v0:num->A) 18 = om` (LABEL_TAC "v18") THENL
   [EXPAND_TAC "v0" THEN REWRITE_TAC[VALMOD; ARITH_EQ]; ALL_TAC] THEN
  (* separate gam = { u SUBSET p : powfin(u) } over source pp = epow p *)
  MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`] ZF_SEPARATION) THEN
  ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  DISCH_THEN(MP_TAC o ISPECL[`powfin_form`;`20`;`v0:num->A`;`pp:A`]) THEN
  ANTS_TAC THENL
   [CONJ_TAC THENL [FIRST_ASSUM ACCEPT_TAC; FIRST_ASSUM ACCEPT_TAC];
    ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `gam:A`
   (CONJUNCTS_THEN2 (LABEL_TAC "gamD") (fun gamch ->
    (* clean characterization of membership in gam *)
    SUBGOAL_THEN
     `!z. z IN D
          ==> ((E:A->A->bool) z gam <=>
               esubset D E z p /\
               (?P. epow D E z P /\
                    (?n. n IN D /\ E n om /\ ?f. ebij D E f n P)))`
     MP_TAC THENL
     [X_GEN_TAC `z:A` THEN DISCH_TAC THEN
      MP_TAC(SPEC `z:A` gamch) THEN
      ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
      DISCH_THEN SUBST1_TAC THEN
      SUBGOAL_THEN `E (z:A) pp <=> esubset D E z p` SUBST1_TAC THENL
       [ASM_MESON_TAC[epow]; ALL_TAC] THEN
      MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`v0:num->A`;`z:A`]
             POWFIN_HOLDS) THEN
      ASM_REWRITE_TAC[] THEN DISCH_THEN SUBST1_TAC THEN
      ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    DISCH_THEN(fun gth ->
     (* ---- base: empty set IN gam ---- *)
     SUBGOAL_THEN `?z. z IN D /\ eempty D (E:A->A->bool) z /\ E z gam`
       (LABEL_TAC "base") THENL
      [MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`] EEMPTY_EXISTS) THEN
       ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
       DISCH_THEN(X_CHOOSE_THEN `e0:A` (LABEL_TAC "emp0")) THEN
       SUBGOAL_THEN `(e0:A) IN D` (LABEL_TAC "e0D") THENL
        [ASM_MESON_TAC[EEMPTY_IN]; ALL_TAC] THEN
       EXISTS_TAC `e0:A` THEN ASM_REWRITE_TAC[] THEN
       MP_TAC(SPEC `e0:A` gth) THEN
       ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
       DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN CONJ_TAC THENL
        [MATCH_MP_TAC EEMPTY_SUBSET THEN FIRST_ASSUM ACCEPT_TAC;
         (* powfin(e0): epow e0 = {e0}, finite *)
         MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`e0:A`] EPOW_EXISTS) THEN
         ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
         DISCH_THEN(X_CHOOSE_THEN `P0:A` (LABEL_TAC "powe0")) THEN
         SUBGOAL_THEN `(P0:A) IN D` (LABEL_TAC "P0D") THENL
          [ASM_MESON_TAC[EPOW_IN]; ALL_TAC] THEN
         (* eadjoin e0 e0 P0 : {e0} is the powerset of the empty set *)
         SUBGOAL_THEN `eadjoin D (E:A->A->bool) e0 e0 P0`
           (LABEL_TAC "adjP0") THENL
           [MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`e0:A`;`e0:A`;`P0:A`]
             EADJOIN_CHAR) THEN
           ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
           DISCH_THEN SUBST1_TAC THEN
           X_GEN_TAC `m:A` THEN DISCH_TAC THEN
           SUBGOAL_THEN `E (m:A) P0 <=> esubset D E m e0` SUBST1_TAC THENL
            [ASM_MESON_TAC[epow]; ALL_TAC] THEN
           SUBGOAL_THEN `~((E:A->A->bool) m e0)` ASSUME_TAC THENL
            [ASM_MESON_TAC[eempty]; ALL_TAC] THEN
           ASM_REWRITE_TAC[] THEN EQ_TAC THENL
            [DISCH_TAC THEN
             SUBGOAL_THEN `eempty D (E:A->A->bool) m` ASSUME_TAC THENL
              [REWRITE_TAC[eempty] THEN CONJ_TAC THENL
                [FIRST_ASSUM ACCEPT_TAC;
                 X_GEN_TAC `w:A` THEN DISCH_TAC THEN
                 UNDISCH_TAC `esubset D (E:A->A->bool) m e0` THEN
                 REWRITE_TAC[esubset] THEN DISCH_THEN(MP_TAC o SPEC `w:A`) THEN
                 ASM_MESON_TAC[eempty]];
               ALL_TAC] THEN
             ASM_MESON_TAC[EEMPTY_UNIQUE];
             DISCH_THEN SUBST1_TAC THEN REWRITE_TAC[esubset] THEN
             ASM_MESON_TAC[eempty]];
           ALL_TAC] THEN
         (* efin P0 *)
         SUBGOAL_THEN `efin D (E:A->A->bool) P0` (LABEL_TAC "finP0") THENL
          [MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`e0:A`;`e0:A`;`P0:A`]
             EFIN_ADJOIN) THEN ASM_REWRITE_TAC[] THEN
           MATCH_MP_TAC EFIN_EMPTY THEN ASM_REWRITE_TAC[];
           ALL_TAC] THEN
         (* P0 bijects some n IN om *)
         MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`om:A`;`P0:A`]
                EFIN_TO_NAT) THEN
         ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
         DISCH_THEN(X_CHOOSE_THEN `n0:A`
           (X_CHOOSE_THEN `f0:A` STRIP_ASSUME_TAC)) THEN
         EXISTS_TAC `P0:A` THEN ASM_REWRITE_TAC[] THEN
         EXISTS_TAC `n0:A` THEN ASM_REWRITE_TAC[] THEN
         EXISTS_TAC `f0:A` THEN ASM_REWRITE_TAC[]];
       ALL_TAC] THEN
     (* ---- gam is closed under adjoining a point of p ---- *)
     SUBGOAL_THEN
      `!xx uu yy. xx IN D /\ uu IN D /\ yy IN D /\ (E:A->A->bool) xx gam /\
                  E uu p /\ eadjoin D E xx uu yy
                  ==> E yy gam`
      (LABEL_TAC "adjcl") THENL
      [MAP_EVERY X_GEN_TAC [`xx:A`;`uu:A`;`yy:A`] THEN STRIP_TAC THEN
       (* decode E xx gam *)
       SUBGOAL_THEN
        `esubset D E (xx:A) p /\
         (?P. epow D E xx P /\
              (?n. n IN D /\ E n om /\ ?f. ebij D E f n P))`
        MP_TAC THENL
        [MP_TAC(SPEC `xx:A` gth) THEN
         ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
         DISCH_THEN(fun th -> REWRITE_TAC[GSYM th]) THEN
         FIRST_ASSUM ACCEPT_TAC;
         ALL_TAC] THEN
       INTRO_TAC "subxp @Px. powxx @nx. nxD nxom @fx. bijx" THEN
       SUBGOAL_THEN `(Px:A) IN D` (LABEL_TAC "PxD") THENL
        [ASM_MESON_TAC[EPOW_IN]; ALL_TAC] THEN
       (* epow xx = Px is finite *)
       SUBGOAL_THEN `efin D (E:A->A->bool) Px` (LABEL_TAC "finPx") THENL
        [MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`om:A`;`nx:A`;`Px:A`;
           `fx:A`] EBIJ_TO_FIN) THEN ASM_REWRITE_TAC[];
         ALL_TAC] THEN
       (* doubling map t |-> t adjoin uu on Px *)
       MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`Px:A`;`uu:A`]
              EDBLMAP_EXISTS) THEN
       ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
       INTRO_TAC "@g img. gD imgD ac sv total imgch" THEN
       (* the image is finite *)
       SUBGOAL_THEN `efin D (E:A->A->bool) img` (LABEL_TAC "finimg") THENL
        [MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`g:A`;`Px:A`;`img:A`]
           EFIN_IMAGE) THEN ASM_REWRITE_TAC[];
         ALL_TAC] THEN
       (* pyy = epow yy *)
       MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`yy:A`] EPOW_EXISTS) THEN
       ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
       DISCH_THEN(X_CHOOSE_THEN `pyy:A` (LABEL_TAC "powyy")) THEN
       SUBGOAL_THEN `(pyy:A) IN D` (LABEL_TAC "pyyD") THENL
        [ASM_MESON_TAC[EPOW_IN]; ALL_TAC] THEN
       (* EPOW_ADJOIN characterization of E w pyy *)
       MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`xx:A`;`uu:A`;`yy:A`;`Px:A`;
         `pyy:A`] EPOW_ADJOIN) THEN
       ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
       DISCH_THEN(LABEL_TAC "epa") THEN
       (* pyy = Px UNION img *)
       SUBGOAL_THEN `ebunion D (E:A->A->bool) Px img pyy`
         (LABEL_TAC "bun") THENL
         [MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`Px:A`;`img:A`;`pyy:A`]
           EBUNION_CHAR) THEN
         ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
         DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
         X_GEN_TAC `m:A` THEN DISCH_TAC THEN
         USE_THEN "epa" (MP_TAC o SPEC `m:A`) THEN
         ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
         DISCH_THEN SUBST1_TAC THEN
         USE_THEN "imgch" (MP_TAC o SPEC `m:A`) THEN
         ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
         DISCH_THEN SUBST1_TAC THEN
         ASM_MESON_TAC[];
         ALL_TAC] THEN
       (* pyy finite *)
       SUBGOAL_THEN `efin D (E:A->A->bool) pyy` (LABEL_TAC "finpyy") THENL
        [MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`Px:A`;`img:A`;`pyy:A`]
           EFIN_UNION2) THEN ASM_REWRITE_TAC[];
         ALL_TAC] THEN
       (* pyy bijects some ny IN om *)
       MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`om:A`;`pyy:A`]
              EFIN_TO_NAT) THEN
       ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
       DISCH_THEN(X_CHOOSE_THEN `ny:A`
         (X_CHOOSE_THEN `fy:A` STRIP_ASSUME_TAC)) THEN
       (* yy SUBSET p *)
       SUBGOAL_THEN `esubset D E (yy:A) p` (LABEL_TAC "subyp") THENL
        [MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`xx:A`;`uu:A`;`yy:A`]
           EADJOIN_MEM) THEN
         ASM_REWRITE_TAC[] THEN STRIP_TAC THEN
         REWRITE_TAC[esubset] THEN X_GEN_TAC `mm:A` THEN STRIP_TAC THEN
         ASM_MESON_TAC[esubset];
         ALL_TAC] THEN
       (* conclude E yy gam *)
       MP_TAC(SPEC `yy:A` gth) THEN
       ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
       DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN CONJ_TAC THENL
        [FIRST_ASSUM ACCEPT_TAC;
         EXISTS_TAC `pyy:A` THEN ASM_REWRITE_TAC[] THEN
         EXISTS_TAC `ny:A` THEN ASM_REWRITE_TAC[] THEN
         EXISTS_TAC `fy:A` THEN ASM_REWRITE_TAC[]];
       ALL_TAC] THEN
     (* ---- absoluteness: p IN gam ---- *)
     SUBGOAL_THEN `(E:A->A->bool) p gam` (LABEL_TAC "pGam") THENL
      [MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`p:A`;`p:A`;`gam:A`]
         EFIN_ABSFAM) THEN
       ASM_REWRITE_TAC[ESUBSET_REFL];
       ALL_TAC] THEN
     (* decode: p bijects some n IN om, via its powerset P = pp *)
     MP_TAC(SPEC `p:A` gth) THEN
     ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
     ASM_REWRITE_TAC[ESUBSET_REFL] THEN
     INTRO_TAC "@P. powpP @n. nD nom @f. bijf" THEN
     SUBGOAL_THEN `(P:A) = pp` SUBST_ALL_TAC THENL
      [MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`p:A`;`P:A`;`pp:A`]
         EPOW_UNIQUE) THEN ASM_REWRITE_TAC[];
       ALL_TAC] THEN
     MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`om:A`;`n:A`;`pp:A`;`f:A`]
       EBIJ_TO_FIN) THEN
     ASM_REWRITE_TAC[])))));;

(* ===== F6.3 N1: EDOMIMG_FAMILY (al |-> dom(ea al)) ===== *)
(* EDOMIMG_FAMILY -- the INDEXED domain-image
   family  al |-> dom(ea al)  as an internal function object.
   ea = (v 12) is an internal function total+single-valued on a1; we build
   ff = { <al, dom(ea al)> : al IN a1 } via EIMG_FAMILY with the graph
   formula domimg_form coding  out = <u, dom(ea u)>  (mirrors dblpair_form /
   EDCLIMG_FAMILY_PAD; ix = 11, ox = 63 as in EDCLIMG).

   domimg_form = ?? 70 (?? 80 (
        apply_form 12 11 70    (* 70 = (v 12)(v 11) = ea(u) = p     *)
     && domain_form 70 80      (* 80 = dom(70) = dom(ea u) = d      *)
     && opair_form 11 80 63))  (* 63 = <v 11, 80> = <u, d> = out    *)
   slots read: 12(ea), 11(u=idx), 70(p), 80(d), 63(out) -- all distinct;
   sub-form internal bounds (71 / 81,82,83) are never read as slots. *)

let domimg_form = new_definition
  `domimg_form =
     ?? 70 (?? 80 (apply_form 12 11 70 &&
                   domain_form 70 80 &&
                   opair_form 11 80 63))`;;

(* HOLDS bridge: template = HOLDS_GOODF (2-deep ?? over 3-way &&).
   RHS written in nested `?p. p IN D /\ ?d. d IN D /\ ...` form so the
   HOLDS_EX output folds cleanly. *)
let HOLDS_DOMIMG = prove
 (`!D (E:A->A->bool) v u out.
     model D E ZF_AX /\ valuation D v /\ u IN D /\ out IN D
     ==> (holds D E ((63 |-> out) ((11 |-> u) v)) domimg_form <=>
          ?p. p IN D /\ ?d. d IN D /\
              eapply D E (v 12) u p /\ edomain D E p d /\
              eopair D E u d out)`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `valuation D ((63 |-> (out:A)) ((11 |-> (u:A)) v))`
    (LABEL_TAC "vw") THENL
   [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[] THEN
    MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  REWRITE_TAC[domimg_form; HOLDS_EX; HOLDS_AND] THEN
  SUBGOAL_THEN
   `!p d:A. p IN D /\ d IN D
      ==> (holds D E ((80 |-> d) ((70 |-> p)
             ((63 |-> (out:A)) ((11 |-> (u:A)) v)))) (apply_form 12 11 70) <=>
           eapply D E (v 12) u p) /\
          (holds D E ((80 |-> d) ((70 |-> p)
             ((63 |-> out) ((11 |-> u) v)))) (domain_form 70 80) <=>
           edomain D E p d) /\
          (holds D E ((80 |-> d) ((70 |-> p)
             ((63 |-> out) ((11 |-> u) v)))) (opair_form 11 80 63) <=>
           eopair D E u d out)`
   (LABEL_TAC "piles") THENL
   [REPEAT GEN_TAC THEN STRIP_TAC THEN
    SUBGOAL_THEN
     `valuation D ((80 |-> (d:A)) ((70 |-> (p:A))
        ((63 |-> (out:A)) ((11 |-> (u:A)) v))))` ASSUME_TAC THENL
     [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
    ASM_SIMP_TAC[HOLDS_APPLY_FORM; HOLDS_DOMAIN_FORM; HOLDS_OPAIR_FORM] THEN
    REWRITE_TAC[VALMOD] THEN CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN
    REWRITE_TAC[]; ALL_TAC] THEN
  MATCH_MP_TAC(MESON[]
    `(!s:A. s IN D ==> (P s <=> Q s))
     ==> ((?s. s IN D /\ P s) <=> (?s. s IN D /\ Q s))`) THEN
  X_GEN_TAC `p:A` THEN DISCH_TAC THEN
  MATCH_MP_TAC(MESON[]
    `(!s:A. s IN D ==> (P s <=> Q s))
     ==> ((?s. s IN D /\ P s) <=> (?s. s IN D /\ Q s))`) THEN
  X_GEN_TAC `d:A` THEN DISCH_TAC THEN
  USE_THEN "piles" (MP_TAC o SPECL [`p:A`; `d:A`]) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  STRIP_TAC THEN ASM_REWRITE_TAC[]);;

(* N1: build ff = { <al, dom(ea al)> : al IN a1 } via EIMG_FAMILY. *)
let EDOMIMG_FAMILY = prove
 (`!D (E:A->A->bool) v a1.
     model D E ZF_AX /\ valuation D v /\ a1 IN D /\
     (!u w w'. u IN D /\ w IN D /\ w' IN D /\
               eapply D E (v 12) u w /\ eapply D E (v 12) u w' ==> w = w') /\
     (!u. u IN D /\ E u a1 ==> ?p. p IN D /\ eapply D E (v 12) u p)
     ==> ?ff. ff IN D /\
              (!n z z'. n IN D /\ z IN D /\ z' IN D /\
                        eapply D E ff n z /\ eapply D E ff n z' ==> z = z') /\
              (!q. q IN D /\ E q ff
                   ==> ?b z. b IN D /\ z IN D /\ E b a1 /\ eopair D E b z q) /\
              (!b. b IN D /\ E b a1
                   ==> ?p d. p IN D /\ d IN D /\
                             eapply D E (v 12) b p /\ edomain D E p d /\
                             eapply D E ff b d)`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "mdl valv a1D svea tot" THEN
  MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `domimg_form`; `11`; `63`;
    `v:num->A`; `a1:A`] EIMG_FAMILY) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[] THEN REPEAT CONJ_TAC THENL
     [(* ~(11 = 63) *) CONV_TAC NUM_REDUCE_CONV;
      (* ---- FUNC: unique output pair per index ---- *)
      X_GEN_TAC `u:A` THEN STRIP_TAC THEN
      USE_THEN "tot" (MP_TAC o SPEC `u:A`) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(X_CHOOSE_THEN `p:A` STRIP_ASSUME_TAC) THEN
      MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `p:A`] EDOMAIN_EXISTS) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(X_CHOOSE_TAC `d:A`) THEN
      SUBGOAL_THEN `(d:A) IN D` ASSUME_TAC THENL
       [ASM_MESON_TAC[EDOMAIN_IN]; ALL_TAC] THEN
      MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `u:A`; `d:A`]
             EOPAIR_EXISTS) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(X_CHOOSE_TAC `out:A`) THEN
      SUBGOAL_THEN `(out:A) IN D` ASSUME_TAC THENL
       [ASM_MESON_TAC[EOPAIR_IN]; ALL_TAC] THEN
      EXISTS_TAC `out:A` THEN
      SUBGOAL_THEN
       `holds D E ((63 |-> (out:A)) ((11 |-> (u:A)) v)) domimg_form`
       ASSUME_TAC THENL
       [MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `v:num->A`; `u:A`; `out:A`]
          HOLDS_DOMIMG) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
        DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
        EXISTS_TAC `p:A` THEN ASM_REWRITE_TAC[] THEN
        EXISTS_TAC `d:A` THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
      ASM_REWRITE_TAC[] THEN
      X_GEN_TAC `out':A` THEN
      DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC MP_TAC) THEN
      MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `v:num->A`; `u:A`; `out':A`]
        HOLDS_DOMIMG) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
      DISCH_THEN(X_CHOOSE_THEN `p':A` (CONJUNCTS_THEN2 ASSUME_TAC
        (X_CHOOSE_THEN `d':A` STRIP_ASSUME_TAC))) THEN
      ASM_MESON_TAC[EDOMAIN_UNIQUE; EOPAIR_UNIQUE];
      (* ---- HF: every output is an ordered pair <u, z> ---- *)
      MAP_EVERY X_GEN_TAC [`u:A`; `out:A`] THEN STRIP_TAC THEN
      MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `v:num->A`; `u:A`; `out:A`]
        HOLDS_DOMIMG) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th ->
        UNDISCH_TAC
          `holds D E ((63 |-> (out:A)) ((11 |-> (u:A)) v)) domimg_form` THEN
        REWRITE_TAC[th]) THEN
      DISCH_THEN(X_CHOOSE_THEN `p:A` (CONJUNCTS_THEN2 ASSUME_TAC
        (X_CHOOSE_THEN `d:A` STRIP_ASSUME_TAC))) THEN
      EXISTS_TAC `d:A` THEN ASM_REWRITE_TAC[]];
    ALL_TAC] THEN
  INTRO_TAC "@ff. ffD mem rpairs sv peridx" THEN
  EXISTS_TAC `ff:A` THEN REPEAT CONJ_TAC THENL
   [USE_THEN "ffD" ACCEPT_TAC;
    USE_THEN "sv" ACCEPT_TAC;
    USE_THEN "rpairs" ACCEPT_TAC;
    (* ---- per-index reshape: value = dom(ea b) ---- *)
    X_GEN_TAC `b:A` THEN STRIP_TAC THEN
    USE_THEN "peridx" (MP_TAC o SPEC `b:A`) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(X_CHOOSE_THEN `out:A`
               (X_CHOOSE_THEN `z:A` STRIP_ASSUME_TAC)) THEN
    MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `v:num->A`; `b:A`; `out:A`]
      HOLDS_DOMIMG) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th ->
      UNDISCH_TAC
        `holds D E ((63 |-> (out:A)) ((11 |-> (b:A)) v)) domimg_form` THEN
      REWRITE_TAC[th]) THEN
    DISCH_THEN(X_CHOOSE_THEN `p:A` (CONJUNCTS_THEN2 ASSUME_TAC
      (X_CHOOSE_THEN `d:A` STRIP_ASSUME_TAC))) THEN
    SUBGOAL_THEN `(z:A) = d` SUBST_ALL_TAC THENL
     [MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `b:A`; `z:A`; `b:A`; `d:A`;
        `out:A`] EOPAIR_INJ) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(ACCEPT_TAC o CONJUNCT2); ALL_TAC] THEN
    MAP_EVERY EXISTS_TAC [`p:A`; `d:A`] THEN ASM_REWRITE_TAC[]]);;

(* ===== F6.3 N3: ERESTIMG_FAMILY (al |-> (ea al)|_r) ===== *)
(* ERESTIMG_FAMILY -- the restriction-image family
   al |-> (ea al)|_r  as an internal function object.  ea = (v 12), root
   r = (v 13); build g = { <al, (ea al)|_r> : al IN a1 } via EIMG_FAMILY,
   graph formula restimg_form coding  out = <u, restrict(ea u, r)>
   (exact mirror of domimg_form / EDOMIMG_FAMILY,
   domain_form -> restrict_form).

   restimg_form = ?? 70 (?? 80 (
        apply_form 12 11 70      (* 70 = (v 12)(v 11) = ea(u) = p        *)
     && restrict_form 70 13 80   (* 80 = restrict(p, v 13) = (ea u)|_r   *)
     && opair_form 11 80 63))    (* 63 = <v 11, 80> = <u, d> = out       *)
   slots read: 12(ea), 11(idx), 13(root r), 70(p), 80(d), 63(out) distinct;
   sub-form internal bounds (71 / 81,82,83) never read as slots. *)

let restimg_form = new_definition
  `restimg_form =
     ?? 70 (?? 80 (apply_form 12 11 70 &&
                   restrict_form 70 13 80 &&
                   opair_form 11 80 63))`;;

let HOLDS_RESTIMG = prove
 (`!D (E:A->A->bool) v u out.
     model D E ZF_AX /\ valuation D v /\ u IN D /\ out IN D
     ==> (holds D E ((63 |-> out) ((11 |-> u) v)) restimg_form <=>
          ?p. p IN D /\ ?d. d IN D /\
              eapply D E (v 12) u p /\ erestrict D E p (v 13) d /\
              eopair D E u d out)`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `valuation D ((63 |-> (out:A)) ((11 |-> (u:A)) v))`
    (LABEL_TAC "vw") THENL
   [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[] THEN
    MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  REWRITE_TAC[restimg_form; HOLDS_EX; HOLDS_AND] THEN
  SUBGOAL_THEN
   `!p d:A. p IN D /\ d IN D
      ==> (holds D E ((80 |-> d) ((70 |-> p)
             ((63 |-> (out:A)) ((11 |-> (u:A)) v)))) (apply_form 12 11 70) <=>
           eapply D E (v 12) u p) /\
          (holds D E ((80 |-> d) ((70 |-> p)
             ((63 |-> out) ((11 |-> u) v)))) (restrict_form 70 13 80) <=>
           erestrict D E p (v 13) d) /\
          (holds D E ((80 |-> d) ((70 |-> p)
             ((63 |-> out) ((11 |-> u) v)))) (opair_form 11 80 63) <=>
           eopair D E u d out)`
   (LABEL_TAC "piles") THENL
   [REPEAT GEN_TAC THEN STRIP_TAC THEN
    SUBGOAL_THEN
     `valuation D ((80 |-> (d:A)) ((70 |-> (p:A))
        ((63 |-> (out:A)) ((11 |-> (u:A)) v))))` ASSUME_TAC THENL
     [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
    ASM_SIMP_TAC[HOLDS_APPLY_FORM; HOLDS_RESTRICT_FORM; HOLDS_OPAIR_FORM] THEN
    REWRITE_TAC[VALMOD] THEN CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN
    REWRITE_TAC[]; ALL_TAC] THEN
  MATCH_MP_TAC(MESON[]
    `(!s:A. s IN D ==> (P s <=> Q s))
     ==> ((?s. s IN D /\ P s) <=> (?s. s IN D /\ Q s))`) THEN
  X_GEN_TAC `p:A` THEN DISCH_TAC THEN
  MATCH_MP_TAC(MESON[]
    `(!s:A. s IN D ==> (P s <=> Q s))
     ==> ((?s. s IN D /\ P s) <=> (?s. s IN D /\ Q s))`) THEN
  X_GEN_TAC `d:A` THEN DISCH_TAC THEN
  USE_THEN "piles" (MP_TAC o SPECL [`p:A`; `d:A`]) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  STRIP_TAC THEN ASM_REWRITE_TAC[]);;

(* N3: build g = { <al, (ea al)|_r> : al IN a1 } via EIMG_FAMILY. *)
let ERESTIMG_FAMILY = prove
 (`!D (E:A->A->bool) v a1.
     model D E ZF_AX /\ valuation D v /\ a1 IN D /\
     (!u w w'. u IN D /\ w IN D /\ w' IN D /\
               eapply D E (v 12) u w /\ eapply D E (v 12) u w' ==> w = w') /\
     (!u. u IN D /\ E u a1 ==> ?p. p IN D /\ eapply D E (v 12) u p)
     ==> ?ff. ff IN D /\
              (!n z z'. n IN D /\ z IN D /\ z' IN D /\
                        eapply D E ff n z /\ eapply D E ff n z' ==> z = z') /\
              (!q. q IN D /\ E q ff
                   ==> ?b z. b IN D /\ z IN D /\ E b a1 /\ eopair D E b z q) /\
              (!b. b IN D /\ E b a1
                   ==> ?p d. p IN D /\ d IN D /\
                             eapply D E (v 12) b p /\
                             erestrict D E p (v 13) d /\
                             eapply D E ff b d)`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "mdl valv a1D svea tot" THEN
  MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `restimg_form`; `11`; `63`;
    `v:num->A`; `a1:A`] EIMG_FAMILY) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[] THEN REPEAT CONJ_TAC THENL
     [(* ~(11 = 63) *) CONV_TAC NUM_REDUCE_CONV;
      (* ---- FUNC ---- *)
      X_GEN_TAC `u:A` THEN STRIP_TAC THEN
      USE_THEN "tot" (MP_TAC o SPEC `u:A`) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(X_CHOOSE_THEN `p:A` STRIP_ASSUME_TAC) THEN
      MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `p:A`; `(v:num->A) 13`]
        ERESTRICT_EXISTS) THEN
      ANTS_TAC THENL [ASM_MESON_TAC[valuation]; ALL_TAC] THEN
      DISCH_THEN(X_CHOOSE_TAC `d:A`) THEN
      SUBGOAL_THEN `(d:A) IN D` ASSUME_TAC THENL
       [ASM_MESON_TAC[erestrict]; ALL_TAC] THEN
      MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `u:A`; `d:A`]
             EOPAIR_EXISTS) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(X_CHOOSE_TAC `out:A`) THEN
      SUBGOAL_THEN `(out:A) IN D` ASSUME_TAC THENL
       [ASM_MESON_TAC[EOPAIR_IN]; ALL_TAC] THEN
      EXISTS_TAC `out:A` THEN
      SUBGOAL_THEN
       `holds D E ((63 |-> (out:A)) ((11 |-> (u:A)) v)) restimg_form`
       ASSUME_TAC THENL
       [MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `v:num->A`; `u:A`; `out:A`]
          HOLDS_RESTIMG) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
        DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
        EXISTS_TAC `p:A` THEN ASM_REWRITE_TAC[] THEN
        EXISTS_TAC `d:A` THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
      ASM_REWRITE_TAC[] THEN
      X_GEN_TAC `out':A` THEN
      DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC MP_TAC) THEN
      MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `v:num->A`; `u:A`; `out':A`]
        HOLDS_RESTIMG) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
      DISCH_THEN(X_CHOOSE_THEN `p':A` (CONJUNCTS_THEN2 ASSUME_TAC
        (X_CHOOSE_THEN `d':A` STRIP_ASSUME_TAC))) THEN
      ASM_MESON_TAC[ERESTRICT_UNIQUE; EOPAIR_UNIQUE];
      (* ---- HF ---- *)
      MAP_EVERY X_GEN_TAC [`u:A`; `out:A`] THEN STRIP_TAC THEN
      MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `v:num->A`; `u:A`; `out:A`]
        HOLDS_RESTIMG) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th ->
        UNDISCH_TAC
          `holds D E ((63 |-> (out:A)) ((11 |-> (u:A)) v)) restimg_form` THEN
        REWRITE_TAC[th]) THEN
      DISCH_THEN(X_CHOOSE_THEN `p:A` (CONJUNCTS_THEN2 ASSUME_TAC
        (X_CHOOSE_THEN `d:A` STRIP_ASSUME_TAC))) THEN
      EXISTS_TAC `d:A` THEN ASM_REWRITE_TAC[]];
    ALL_TAC] THEN
  INTRO_TAC "@ff. ffD mem rpairs sv peridx" THEN
  EXISTS_TAC `ff:A` THEN REPEAT CONJ_TAC THENL
   [USE_THEN "ffD" ACCEPT_TAC;
    USE_THEN "sv" ACCEPT_TAC;
    USE_THEN "rpairs" ACCEPT_TAC;
    X_GEN_TAC `b:A` THEN STRIP_TAC THEN
    USE_THEN "peridx" (MP_TAC o SPEC `b:A`) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(X_CHOOSE_THEN `out:A`
               (X_CHOOSE_THEN `z:A` STRIP_ASSUME_TAC)) THEN
    MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `v:num->A`; `b:A`; `out:A`]
      HOLDS_RESTIMG) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th ->
      UNDISCH_TAC
        `holds D E ((63 |-> (out:A)) ((11 |-> (b:A)) v)) restimg_form` THEN
      REWRITE_TAC[th]) THEN
    DISCH_THEN(X_CHOOSE_THEN `p:A` (CONJUNCTS_THEN2 ASSUME_TAC
      (X_CHOOSE_THEN `d:A` STRIP_ASSUME_TAC))) THEN
    SUBGOAL_THEN `(z:A) = d` SUBST_ALL_TAC THENL
     [MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `b:A`; `z:A`; `b:A`; `d:A`;
        `out:A`] EOPAIR_INJ) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(ACCEPT_TAC o CONJUNCT2); ALL_TAC] THEN
    MAP_EVERY EXISTS_TAC [`p:A`; `d:A`] THEN ASM_REWRITE_TAC[]]);;

(* ===== F6.3 prereq: EFIN_DOMAIN (dom of finite pairs-set is finite) ===== *)
(* EFIN_DOMAIN -- the domain of a finite set of
   ordered pairs is finite.  Route: build the first-projection map
       g = { <z, fst z> : z IN p }
   as an internal function via EIMG_FAMILY (graph formula projpair_form),
   then feed it to EFIN_IMAGE with img := dom(p): the image of p under
   first-projection IS dom(p) (edomain char), so efin(dom p).

   projpair_form = ?? 70 (?? 80 (
        opair_form 70 80 11    (* v 11 = <v 70, v 80>,
        i.e. z = <c,w>, c=fst z *)
     && opair_form 11 70 63))  (* v 63 = <v 11, v 70> = <z,
     c> = out           *)
   ix = 11 (index z), ox = 63 (output <z, fst z>), bound c = 70, w = 80.
   slots read 11/70/80/63 distinct;
   opair internal bounds (71,72 / 81,82) unread. *)

let projpair_form = new_definition
  `projpair_form =
     ?? 70 (?? 80 (opair_form 70 80 11 && opair_form 11 70 63))`;;

let HOLDS_PROJPAIR = prove
 (`!D (E:A->A->bool) v z out.
     model D E ZF_AX /\ valuation D v /\ z IN D /\ out IN D
     ==> (holds D E ((63 |-> out) ((11 |-> z) v)) projpair_form <=>
          ?c. c IN D /\ ?w. w IN D /\
              eopair D E c w z /\ eopair D E z c out)`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `valuation D ((63 |-> (out:A)) ((11 |-> (z:A)) v))`
    (LABEL_TAC "vw") THENL
   [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[] THEN
    MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  REWRITE_TAC[projpair_form; HOLDS_EX; HOLDS_AND] THEN
  SUBGOAL_THEN
   `!c w:A. c IN D /\ w IN D
      ==> (holds D E ((80 |-> w) ((70 |-> c)
             ((63 |-> (out:A)) ((11 |-> (z:A)) v)))) (opair_form 70 80 11) <=>
           eopair D E c w z) /\
          (holds D E ((80 |-> w) ((70 |-> c)
             ((63 |-> out) ((11 |-> z) v)))) (opair_form 11 70 63) <=>
           eopair D E z c out)`
   (LABEL_TAC "piles") THENL
   [REPEAT GEN_TAC THEN STRIP_TAC THEN
    SUBGOAL_THEN
     `valuation D ((80 |-> (w:A)) ((70 |-> (c:A))
        ((63 |-> (out:A)) ((11 |-> (z:A)) v))))` ASSUME_TAC THENL
     [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
    ASM_SIMP_TAC[HOLDS_OPAIR_FORM] THEN
    REWRITE_TAC[VALMOD] THEN CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN
    REWRITE_TAC[]; ALL_TAC] THEN
  MATCH_MP_TAC(MESON[]
    `(!s:A. s IN D ==> (P s <=> Q s))
     ==> ((?s. s IN D /\ P s) <=> (?s. s IN D /\ Q s))`) THEN
  X_GEN_TAC `c:A` THEN DISCH_TAC THEN
  MATCH_MP_TAC(MESON[]
    `(!s:A. s IN D ==> (P s <=> Q s))
     ==> ((?s. s IN D /\ P s) <=> (?s. s IN D /\ Q s))`) THEN
  X_GEN_TAC `w:A` THEN DISCH_TAC THEN
  USE_THEN "piles" (MP_TAC o SPECL [`c:A`; `w:A`]) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  STRIP_TAC THEN ASM_REWRITE_TAC[]);;

(* the first-projection map g = { <z, fst z> : z IN p } *)
let EPROJ_FAMILY = prove
 (`!D (E:A->A->bool) p.
     model D E ZF_AX /\ p IN D /\
     (!z. z IN D /\ E z p ==> ?u w. u IN D /\ w IN D /\ eopair D E u w z)
     ==> ?g. g IN D /\
             (!n z z'. n IN D /\ z IN D /\ z' IN D /\
                       eapply D E g n z /\ eapply D E g n z' ==> z = z') /\
             (!x. x IN D /\ E x p
                  ==> ?c w. c IN D /\ w IN D /\
                            eopair D E c w x /\ eapply D E g x c)`,
  REPEAT STRIP_TAC THEN
  FIRST_ASSUM(X_CHOOSE_TAC `v0:num->A` o MATCH_MP VALUATION_EXISTS o
    MATCH_MP MODEL_NONEMPTY) THEN
  MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `projpair_form`; `11`; `63`;
    `v0:num->A`; `p:A`] EIMG_FAMILY) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[] THEN REPEAT CONJ_TAC THENL
     [CONV_TAC NUM_REDUCE_CONV;
      (* ---- FUNC ---- *)
      X_GEN_TAC `x:A` THEN STRIP_TAC THEN
      FIRST_X_ASSUM(MP_TAC o SPEC `x:A`) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(X_CHOOSE_THEN `u:A`
                 (X_CHOOSE_THEN `w:A` STRIP_ASSUME_TAC)) THEN
      MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `x:A`; `u:A`]
             EOPAIR_EXISTS) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(X_CHOOSE_TAC `out:A`) THEN
      SUBGOAL_THEN `(out:A) IN D` ASSUME_TAC THENL
       [ASM_MESON_TAC[EOPAIR_IN]; ALL_TAC] THEN
      EXISTS_TAC `out:A` THEN
      SUBGOAL_THEN
       `holds D E ((63 |-> (out:A)) ((11 |-> (x:A)) v0)) projpair_form`
       ASSUME_TAC THENL
       [MP_TAC(ISPECL
               [`D:A->bool`; `E:A->A->bool`; `v0:num->A`; `x:A`; `out:A`]
               HOLDS_PROJPAIR) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
        DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
        EXISTS_TAC `u:A` THEN ASM_REWRITE_TAC[] THEN
        EXISTS_TAC `w:A` THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
      ASM_REWRITE_TAC[] THEN
      X_GEN_TAC `out':A` THEN
      DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC MP_TAC) THEN
      MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `v0:num->A`; `x:A`; `out':A`]
        HOLDS_PROJPAIR) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
      DISCH_THEN(X_CHOOSE_THEN `c':A` (CONJUNCTS_THEN2 ASSUME_TAC
        (X_CHOOSE_THEN `w':A` STRIP_ASSUME_TAC))) THEN
      (* c' = u from eopair c' w' x, eopair u w x *)
      SUBGOAL_THEN `(c':A) = u` SUBST_ALL_TAC THENL
       [MP_TAC(ISPECL
               [`D:A->bool`; `E:A->A->bool`; `c':A`; `w':A`; `u:A`; `w:A`;
                `x:A`] EOPAIR_INJ) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
        DISCH_THEN(ACCEPT_TAC o CONJUNCT1); ALL_TAC] THEN
      ASM_MESON_TAC[EOPAIR_UNIQUE];
      (* ---- HF ---- *)
      MAP_EVERY X_GEN_TAC [`x:A`; `out:A`] THEN STRIP_TAC THEN
      MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `v0:num->A`; `x:A`; `out:A`]
        HOLDS_PROJPAIR) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th ->
        UNDISCH_TAC
          `holds D E ((63 |-> (out:A)) ((11 |-> (x:A)) v0)) projpair_form` THEN
        REWRITE_TAC[th]) THEN
      DISCH_THEN(X_CHOOSE_THEN `c:A` (CONJUNCTS_THEN2 ASSUME_TAC
        (X_CHOOSE_THEN `w:A` STRIP_ASSUME_TAC))) THEN
      EXISTS_TAC `c:A` THEN ASM_REWRITE_TAC[]];
    ALL_TAC] THEN
  INTRO_TAC "@g. gD mem rpairs sv peridx" THEN
  EXISTS_TAC `g:A` THEN REPEAT CONJ_TAC THENL
   [USE_THEN "gD" ACCEPT_TAC;
    USE_THEN "sv" ACCEPT_TAC;
    X_GEN_TAC `x:A` THEN STRIP_TAC THEN
    USE_THEN "peridx" (MP_TAC o SPEC `x:A`) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(X_CHOOSE_THEN `out:A`
               (X_CHOOSE_THEN `s:A` STRIP_ASSUME_TAC)) THEN
    MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `v0:num->A`; `x:A`; `out:A`]
      HOLDS_PROJPAIR) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th ->
      UNDISCH_TAC
        `holds D E ((63 |-> (out:A)) ((11 |-> (x:A)) v0)) projpair_form` THEN
      REWRITE_TAC[th]) THEN
    DISCH_THEN(X_CHOOSE_THEN `c:A` (CONJUNCTS_THEN2 ASSUME_TAC
      (X_CHOOSE_THEN `w:A` STRIP_ASSUME_TAC))) THEN
    (* out = <x, s> and out = <x, c> ==> s = c *)
    SUBGOAL_THEN `(s:A) = c` SUBST_ALL_TAC THENL
     [MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `x:A`; `s:A`; `x:A`; `c:A`;
        `out:A`] EOPAIR_INJ) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(ACCEPT_TAC o CONJUNCT2); ALL_TAC] THEN
    MAP_EVERY EXISTS_TAC [`c:A`; `w:A`] THEN ASM_REWRITE_TAC[]]);;

(* EFIN_DOMAIN: domain of a finite set of ordered pairs is finite. *)
let EFIN_DOMAIN = prove
 (`!D (E:A->A->bool) p dp.
     model D E ZF_AX /\ efin D E p /\
     (!z. z IN D /\ E z p ==> ?u w. u IN D /\ w IN D /\ eopair D E u w z) /\
     edomain D E p dp
     ==> efin D E dp`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "mdl finp pairs dom" THEN
  SUBGOAL_THEN `(p:A) IN D` (LABEL_TAC "pD") THENL
   [ASM_MESON_TAC[efin]; ALL_TAC] THEN
  SUBGOAL_THEN `(dp:A) IN D` (LABEL_TAC "dpD") THENL
   [ASM_MESON_TAC[edomain]; ALL_TAC] THEN
  (* build the first-projection map g *)
  MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `p:A`] EPROJ_FAMILY) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `g:A` (CONJUNCTS_THEN2 (LABEL_TAC "gD")
    (CONJUNCTS_THEN2 (LABEL_TAC "gsv") (LABEL_TAC "gapp")))) THEN
  (* apply EFIN_IMAGE with img := dp *)
  MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `g:A`; `p:A`; `dp:A`]
         EFIN_IMAGE) THEN
  DISCH_THEN MATCH_MP_TAC THEN REPEAT CONJ_TAC THENL
   [(* model *) USE_THEN "mdl" ACCEPT_TAC;
    (* efin p *) USE_THEN "finp" ACCEPT_TAC;
    (* g IN D *) USE_THEN "gD" ACCEPT_TAC;
    (* dp IN D *) USE_THEN "dpD" ACCEPT_TAC;
    (* single-valued *) USE_THEN "gsv" ACCEPT_TAC;
    (* total on p into dp *)
    X_GEN_TAC `x:A` THEN STRIP_TAC THEN
    USE_THEN "gapp" (MP_TAC o SPEC `x:A`) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(X_CHOOSE_THEN `c:A` (X_CHOOSE_THEN `w:A` STRIP_ASSUME_TAC)) THEN
    EXISTS_TAC `c:A` THEN ASM_REWRITE_TAC[] THEN
    (* E c dp : c IN dom p since <c,w> = x IN p *)
    UNDISCH_TAC `edomain D (E:A->A->bool) p dp` THEN REWRITE_TAC[edomain] THEN
    DISCH_THEN(CONJUNCTS_THEN2 (K ALL_TAC) (MP_TAC o SPEC `c:A`)) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    REWRITE_TAC[eindom] THEN EXISTS_TAC `w:A` THEN ASM_REWRITE_TAC[] THEN
    REWRITE_TAC[eapply] THEN EXISTS_TAC `x:A` THEN ASM_REWRITE_TAC[];
    (* image char: E m dp <=> ?x. x IN p /\ eapply g x m *)
    X_GEN_TAC `m:A` THEN DISCH_TAC THEN
    UNDISCH_TAC `edomain D (E:A->A->bool) p dp` THEN REWRITE_TAC[edomain] THEN
    DISCH_THEN(CONJUNCTS_THEN2 (K ALL_TAC) (MP_TAC o SPEC `m:A`)) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN REWRITE_TAC[eindom] THEN
    EQ_TAC THENL
     [(* eindom p m ==> ?x IN p. eapply g x m *)
      DISCH_THEN(X_CHOOSE_THEN `w:A` (CONJUNCTS_THEN2 ASSUME_TAC MP_TAC)) THEN
      REWRITE_TAC[eapply] THEN
      DISCH_THEN(X_CHOOSE_THEN `x:A` STRIP_ASSUME_TAC) THEN
      SUBGOAL_THEN `(x:A) IN D` ASSUME_TAC THENL
       [ASM_MESON_TAC[EOPAIR_IN]; ALL_TAC] THEN
      EXISTS_TAC `x:A` THEN ASM_REWRITE_TAC[] THEN
      (* eapply g x m : g maps x to fst x = m *)
      USE_THEN "gapp" (MP_TAC o SPEC `x:A`) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(X_CHOOSE_THEN `c:A`
                 (X_CHOOSE_THEN `w2:A` STRIP_ASSUME_TAC)) THEN
      SUBGOAL_THEN `(c:A) = m` SUBST_ALL_TAC THENL
       [MP_TAC(ISPECL
               [`D:A->bool`; `E:A->A->bool`; `c:A`; `w2:A`; `m:A`; `w:A`;
                `x:A`] EOPAIR_INJ) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
        DISCH_THEN(ACCEPT_TAC o CONJUNCT1); ALL_TAC] THEN
      ASM_MESON_TAC[eapply];
      (* ?x IN p. eapply g x m ==> eindom p m *)
      DISCH_THEN(X_CHOOSE_THEN `x:A` STRIP_ASSUME_TAC) THEN
      USE_THEN "gapp" (MP_TAC o SPEC `x:A`) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(X_CHOOSE_THEN `c:A`
                 (X_CHOOSE_THEN `w:A` STRIP_ASSUME_TAC)) THEN
      (* eapply g x m and eapply g x c ==> m = c *)
      SUBGOAL_THEN `(m:A) = c` SUBST_ALL_TAC THENL
       [USE_THEN "gsv" MATCH_MP_TAC THEN
        MAP_EVERY EXISTS_TAC [`x:A`] THEN ASM_REWRITE_TAC[] THEN
        ASM_MESON_TAC[eapply]; ALL_TAC] THEN
      EXISTS_TAC `w:A` THEN ASM_REWRITE_TAC[] THEN
      REWRITE_TAC[eapply] THEN EXISTS_TAC `x:A` THEN ASM_REWRITE_TAC[]]]);;

(* ========================================================================= *)
(* F6.3  CCC of the Cohen poset (modulo the indexed Delta-system hypothesis) *)
(* ------------------------------------------------------------------------- *)
(* Dependency order: the five base-only lemmas first (EDOMAIN_SUBSET_II,     *)
(* RESTRICT_EQ_AGREE, EFIN_CROSS, UNCOUNTABLE_NOT_INJ_FIN,                   *)
(* ERESTRICT_IN_POW_CROSS), then COHEN_DOM_FIN_SUB (uses EDOMAIN_SUBSET_II), *)
(* COHEN_COMPAT_FROM_AGREE (uses RESTRICT_EQ_AGREE + base                    *)
(* COHEN_UNION_IS_CONDITION), FAMILY_COLLISION (uses                         *)
(* UNCOUNTABLE_NOT_INJ_FIN), and finally the capstone                        *)
(* CCC_COHEN_MODULO_DELTA.                                                   *)
(* ========================================================================= *)

(* F6.3 lemma: EDOMAIN_SUBSET_II -- domain of a Cohen condition lands in the
   index set.  If p SUBSET ci = ii x tw and dp = dom(p), then dp SUBSET ii.
   Every c IN dp has a witness pair z=<c,w> IN p SUBSET ci; ecross splits z as
   <u',w'> with u' IN ii; EOPAIR_INJ forces c=u', so c IN ii.
   Minimal hyps: ii/tw/dp IN D are all unused (esubset/edomain need no
   ambient-membership of the sub/dom object). *)
let EDOMAIN_SUBSET_II = prove
 (`!D (E:A->A->bool) ii tw ci p dp.
     model D E ZF_AX /\ ecross D E ii tw ci /\
     esubset D E p ci /\ edomain D E p dp
     ==> esubset D E dp ii`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "mdl cr sub dom" THEN
  REWRITE_TAC[esubset] THEN X_GEN_TAC `c:A` THEN STRIP_TAC THEN
  SUBGOAL_THEN `eindom D (E:A->A->bool) p c` MP_TAC THENL
   [ASM_MESON_TAC[edomain]; ALL_TAC] THEN
  REWRITE_TAC[eindom] THEN
  DISCH_THEN(X_CHOOSE_THEN `w:A`
             (CONJUNCTS_THEN2 (LABEL_TAC "wD") MP_TAC)) THEN
  REWRITE_TAC[eapply] THEN
  DISCH_THEN(X_CHOOSE_THEN `z:A`
    (CONJUNCTS_THEN2 (LABEL_TAC "pairz") (LABEL_TAC "zp"))) THEN
  SUBGOAL_THEN `(z:A) IN D` (LABEL_TAC "zD") THENL
   [ASM_MESON_TAC[EOPAIR_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) z ci` (LABEL_TAC "zci") THENL
   [UNDISCH_TAC `esubset D (E:A->A->bool) p ci` THEN REWRITE_TAC[esubset] THEN
    DISCH_THEN MATCH_MP_TAC THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  USE_THEN "cr" (MP_TAC o CONJUNCT2 o REWRITE_RULE[ecross]) THEN
  DISCH_THEN(MP_TAC o SPEC `z:A`) THEN
  ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  USE_THEN "zci" (fun zci -> DISCH_THEN(MP_TAC o C EQ_MP zci)) THEN
  DISCH_THEN(X_CHOOSE_THEN `u':A` (X_CHOOSE_THEN `w':A` STRIP_ASSUME_TAC)) THEN
  MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `c:A`; `w:A`; `u':A`; `w':A`;
    `z:A`] EOPAIR_INJ) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(CONJUNCTS_THEN2 SUBST1_TAC (K ALL_TAC)) THEN
  ASM_REWRITE_TAC[]);;

(* F6.3 bridge: RESTRICT_EQ_AGREE -- from equal restrictions to pointwise
   agreement.  If q is functional, p|_r = q|_r (as sets pr=qr), and every
   common domain point of p,q lies in r, then p and q agree wherever both are
   defined -- exactly the AGREE hypothesis N4 EFUN_UNION_AGREE consumes.
   Caller (CCC_COHEN_MODULO_DELTA step 5) supplies: dom p INTER dom q = r
   (=> common-domain point in r) from the Delta-system, and pr=qr from the
   pigeonhole g(al)=g(be).  Route: <u,w> IN p, <u,w'> IN q => u in both
   domains => u IN r => <u,w> IN p|_r = q|_r => <u,w> IN q; q functional with
   <u,w'> IN q forces w=w'. *)
let RESTRICT_EQ_AGREE = prove
 (`!D (E:A->A->bool) p q r pr qr.
     model D E ZF_AX /\ efunctional D E q /\
     erestrict D E p r pr /\ erestrict D E q r qr /\ pr = qr /\
     (!u. u IN D /\ eindom D E p u /\ eindom D E q u ==> E u r)
     ==> (!u w w' z z'.
            u IN D /\ w IN D /\ w' IN D /\ z IN D /\ z' IN D /\
            eopair D E u w z /\ E z p /\ eopair D E u w' z' /\ E z' q
            ==> w = w')`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "mdl fq rp rq eq dsub" THEN
  MAP_EVERY X_GEN_TAC [`u:A`; `w:A`; `w':A`; `z:A`; `z':A`] THEN
  STRIP_TAC THEN
  (* u lies in dom p and dom q *)
  SUBGOAL_THEN `eindom D (E:A->A->bool) p u` (LABEL_TAC "idp") THENL
   [REWRITE_TAC[eindom; eapply] THEN
    EXISTS_TAC `w:A` THEN ASM_REWRITE_TAC[] THEN
    EXISTS_TAC `z:A` THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `eindom D (E:A->A->bool) q u` (LABEL_TAC "idq") THENL
   [REWRITE_TAC[eindom; eapply] THEN
    EXISTS_TAC `w':A` THEN ASM_REWRITE_TAC[] THEN
    EXISTS_TAC `z':A` THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) u r` (LABEL_TAC "ur") THENL
   [USE_THEN "dsub" MATCH_MP_TAC THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* z=<u,w> is in the restriction p|_r *)
  SUBGOAL_THEN `(E:A->A->bool) z pr` (LABEL_TAC "zpr") THENL
   [UNDISCH_TAC `erestrict D (E:A->A->bool) p r pr` THEN
    REWRITE_TAC[erestrict] THEN
    DISCH_THEN(CONJUNCTS_THEN2 (K ALL_TAC) (MP_TAC o SPEC `z:A`)) THEN
    ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    ASM_REWRITE_TAC[] THEN
    MAP_EVERY EXISTS_TAC [`u:A`; `w:A`] THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* transport across pr = qr, then strip the restriction: z IN q *)
  SUBGOAL_THEN `(E:A->A->bool) z qr` (LABEL_TAC "zqr") THENL
   [ASM_MESON_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) z q` (LABEL_TAC "zq") THENL
   [UNDISCH_TAC `erestrict D (E:A->A->bool) q r qr` THEN
    REWRITE_TAC[erestrict] THEN
    DISCH_THEN(CONJUNCTS_THEN2 (K ALL_TAC) (MP_TAC o SPEC `z:A`)) THEN
    ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    USE_THEN "zqr" (fun zqr ->
      DISCH_THEN(ACCEPT_TAC o CONJUNCT1 o C EQ_MP zqr)); ALL_TAC] THEN
  (* q functional: <u,w> IN q and <u,w'> IN q share domain point u => w=w' *)
  USE_THEN "fq" (MP_TAC o SPECL [`z:A`; `z':A`; `u:A`; `w:A`; `w':A`] o
    REWRITE_RULE[efunctional]) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN ACCEPT_TAC);;

(* F6.3 prereq: EFIN_CROSS -- the product of two K-finite sets is K-finite.
   Route (self-contained, no product-bijection needed): every pair z=<u,w>
   in r x tw is a Kuratowski pair {{u},{u,w}} SUBSET epow(r UNION tw), so
   r x tw SUBSET epow(epow(r UNION tw)); r UNION tw finite (EFIN_UNION2),
   double EFIN_POW gives epow(epow(...)) finite, EFIN_SUBSET closes. *)
let EFIN_CROSS = prove
 (`!D (E:A->A->bool) om r tw q.
     model D E ZF_AX /\ eomega D E om /\ efin D E r /\ efin D E tw /\
     ecross D E r tw q
     ==> efin D E q`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "mdl omega finr fintw cr" THEN
  SUBGOAL_THEN `(r:A) IN D` (LABEL_TAC "rD") THENL
   [ASM_MESON_TAC[efin]; ALL_TAC] THEN
  SUBGOAL_THEN `(tw:A) IN D` (LABEL_TAC "twD") THENL
   [ASM_MESON_TAC[efin]; ALL_TAC] THEN
  SUBGOAL_THEN `(q:A) IN D` (LABEL_TAC "qD") THENL
   [ASM_MESON_TAC[ecross]; ALL_TAC] THEN
  (* rtw = r UNION tw, finite *)
  MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`r:A`;`tw:A`] EBUNION_EXISTS) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `rtw:A` (LABEL_TAC "brtw")) THEN
  SUBGOAL_THEN `(rtw:A) IN D` (LABEL_TAC "rtwD") THENL
   [ASM_MESON_TAC[EBUNION_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `efin D (E:A->A->bool) rtw` (LABEL_TAC "finrtw") THENL
   [MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`r:A`;`tw:A`;`rtw:A`]
      EFIN_UNION2) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* pr = epow rtw, finite *)
  MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`rtw:A`] EPOW_EXISTS) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `pr:A` (LABEL_TAC "epr")) THEN
  SUBGOAL_THEN `(pr:A) IN D` (LABEL_TAC "prD") THENL
   [ASM_MESON_TAC[epow]; ALL_TAC] THEN
  SUBGOAL_THEN `efin D (E:A->A->bool) pr` (LABEL_TAC "finpr") THENL
   [MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`om:A`;`rtw:A`;`pr:A`]
      EFIN_POW) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* pp = epow pr, finite *)
  MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`pr:A`] EPOW_EXISTS) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `pp:A` (LABEL_TAC "epp")) THEN
  SUBGOAL_THEN `(pp:A) IN D` (LABEL_TAC "ppD") THENL
   [ASM_MESON_TAC[epow]; ALL_TAC] THEN
  SUBGOAL_THEN `efin D (E:A->A->bool) pp` (LABEL_TAC "finpp") THENL
   [MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`om:A`;`pr:A`;`pp:A`]
      EFIN_POW) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* q SUBSET pp ==> q finite *)
  MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`pp:A`;`q:A`]
               EFIN_SUBSET) THEN
  ASM_REWRITE_TAC[] THEN
  REWRITE_TAC[esubset] THEN X_GEN_TAC `z:A` THEN STRIP_TAC THEN
  (* z in q: extract u in r, w in tw, eopair u w z *)
  USE_THEN "cr" (MP_TAC o CONJUNCT2 o REWRITE_RULE[ecross]) THEN
  DISCH_THEN(MP_TAC o SPEC `z:A`) THEN
  ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  DISCH_THEN(fun iff ->
             ASSUME_TAC(EQ_MP iff (ASSUME `(E:A->A->bool) z q`))) THEN
  FIRST_X_ASSUM(X_CHOOSE_THEN `u:A`
                (X_CHOOSE_THEN `w:A` STRIP_ASSUME_TAC)) THEN
  (* u,w land in rtw *)
  MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`r:A`;`tw:A`;`rtw:A`]
         EBUNION_MEM) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(CONJUNCTS_THEN2 (K ALL_TAC) (LABEL_TAC "bmem")) THEN
  SUBGOAL_THEN `(E:A->A->bool) u rtw` (LABEL_TAC "urtw") THENL
   [USE_THEN "bmem" (MP_TAC o SPEC `u:A`) THEN ASM_MESON_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) w rtw` (LABEL_TAC "wrtw") THENL
   [USE_THEN "bmem" (MP_TAC o SPEC `w:A`) THEN ASM_MESON_TAC[]; ALL_TAC] THEN
  (* z = {s0,p0}, s0={u}, p0={u,w} *)
  UNDISCH_TAC `eopair D (E:A->A->bool) u w z` THEN REWRITE_TAC[eopair] THEN
  DISCH_THEN(X_CHOOSE_THEN `s0:A` (X_CHOOSE_THEN `p0:A` STRIP_ASSUME_TAC)) THEN
  SUBGOAL_THEN `(s0:A) IN D /\ (p0:A) IN D` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[epair]; ALL_TAC] THEN
  (* goal E z pp <=> esubset z pr *)
  USE_THEN "epp" (MP_TAC o CONJUNCT2 o REWRITE_RULE[epow]) THEN
  DISCH_THEN(MP_TAC o SPEC `z:A`) THEN
  ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  (* esubset z pr *)
  REWRITE_TAC[esubset] THEN X_GEN_TAC `s:A` THEN STRIP_TAC THEN
  (* E s pr <=> esubset s rtw *)
  USE_THEN "epr" (MP_TAC o CONJUNCT2 o REWRITE_RULE[epow]) THEN
  DISCH_THEN(MP_TAC o SPEC `s:A`) THEN
  ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  (* s in z = {s0,p0}: s = s0 \/ s = p0 *)
  SUBGOAL_THEN `(s:A) = s0 \/ (s:A) = p0` DISJ_CASES_TAC THENL
   [MP_TAC(ASSUME `epair D (E:A->A->bool) s0 p0 z`) THEN
    REWRITE_TAC[epair] THEN
    ASM_MESON_TAC[];
    (* s = s0 = {u} *)
    FIRST_X_ASSUM SUBST_ALL_TAC THEN
    REWRITE_TAC[esubset] THEN X_GEN_TAC `t:A` THEN STRIP_TAC THEN
    SUBGOAL_THEN `(t:A) = u` SUBST_ALL_TAC THENL
     [MP_TAC(ASSUME `epair D (E:A->A->bool) u u s0`) THEN
      REWRITE_TAC[epair] THEN
      ASM_MESON_TAC[]; ALL_TAC] THEN
    USE_THEN "urtw" ACCEPT_TAC;
    (* s = p0 = {u,w} *)
    FIRST_X_ASSUM SUBST_ALL_TAC THEN
    REWRITE_TAC[esubset] THEN X_GEN_TAC `t:A` THEN STRIP_TAC THEN
    SUBGOAL_THEN `(t:A) = u \/ (t:A) = w` DISJ_CASES_TAC THENL
     [MP_TAC(ASSUME `epair D (E:A->A->bool) u w p0`) THEN
      REWRITE_TAC[epair] THEN
      ASM_MESON_TAC[];
      FIRST_X_ASSUM SUBST_ALL_TAC THEN USE_THEN "urtw" ACCEPT_TAC;
      FIRST_X_ASSUM SUBST_ALL_TAC THEN USE_THEN "wrtw" ACCEPT_TAC]]);;

(* F6.3 pigeonhole: UNCOUNTABLE_NOT_INJ_FIN -- an uncountable set cannot
   inject into a K-finite set.  sfin finite ==>
     bijects a natural n (EFIN_TO_NAT);
   invert (EBIJ_SYM) to einj sfin n; compose with the assumed einj II sfin
   (EINJ_COMPOSE) to einj II n; weaken n to om (EINJ_WEAKEN + EOMEGA_TRANS),
   contradicting II uncountable. *)
let UNCOUNTABLE_NOT_INJ_FIN = prove
 (`!D (E:A->A->bool) om II sfin g.
     model D E ZF_AX /\ eomega D E om /\ II IN D /\ sfin IN D /\
     efin D E sfin /\ einj D E g II sfin /\ ~(?e. einj D E e II om)
     ==> F`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "mdl omega iiD sD fins ginj noinj" THEN
  MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`om:A`;`sfin:A`] EFIN_TO_NAT) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  INTRO_TAC "@n f. nD fD nom bijf" THEN
  MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`f:A`;`n:A`;`sfin:A`] EBIJ_SYM) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `f':A` (LABEL_TAC "bijf'")) THEN
  SUBGOAL_THEN `einj D (E:A->A->bool) f' sfin n` (LABEL_TAC "injf'") THENL
   [MATCH_MP_TAC EBIJ_EINJ THEN USE_THEN "bijf'" ACCEPT_TAC; ALL_TAC] THEN
  MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`g:A`;`f':A`;`II:A`;`sfin:A`;`n:A`]
    EINJ_COMPOSE) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `h:A` (LABEL_TAC "injh")) THEN
  SUBGOAL_THEN `einj D (E:A->A->bool) h II om` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`h:A`;`II:A`;`n:A`;`om:A`]
      EINJ_WEAKEN) THEN
    CONJ_TAC THENL
     [USE_THEN "injh" ACCEPT_TAC;
      X_GEN_TAC `t:A` THEN STRIP_TAC THEN
      MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`om:A`;`n:A`;`t:A`]
        EOMEGA_TRANS) THEN ASM_REWRITE_TAC[]];
    ALL_TAC] THEN
  ASM_MESON_TAC[]);;

(* F6.3 geometric heart for the CCC_COHEN cod-clause: the restriction pr of a
   Cohen condition p (p SUBSET ci = ii x tw) to a root r is a subset of r x tw,
   hence a MEMBER of epow(r x tw)=S.  Every s IN pr is s IN p with first coord
   in r (erestrict);
   s IN p SUBSET ci splits as <u',w'> with w' IN tw (ecross ci);
   EOPAIR_INJ identifies the two decompositions,
   so s=<u,w'> with u IN r, w' IN tw,
   i.e. s IN r x tw; epow char then gives E pr S. *)
let ERESTRICT_IN_POW_CROSS = prove
 (`!D (E:A->A->bool) ii tw ci r rt S p pr.
     model D E ZF_AX /\ ecross D E ii tw ci /\ ecross D E r tw rt /\
       epow D E rt S /\
     esubset D E p ci /\ erestrict D E p r pr
     ==> E pr S`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "mdl crci crrt epowS subpci rest" THEN
  SUBGOAL_THEN `(pr:A) IN D` ASSUME_TAC THENL
   [USE_THEN "rest" (ACCEPT_TAC o CONJUNCT1 o GEN_REWRITE_RULE I [erestrict]);
    ALL_TAC] THEN
  SUBGOAL_THEN `esubset D (E:A->A->bool) pr rt` (LABEL_TAC "subprrt") THENL
   [REWRITE_TAC[esubset] THEN X_GEN_TAC `s:A` THEN STRIP_TAC THEN
    (* from erestrict: E s p /\ ?u w. E u r /\ eopair u w s *)
    USE_THEN "rest" (MP_TAC o CONJUNCT2 o REWRITE_RULE[erestrict]) THEN
    DISCH_THEN(MP_TAC o SPEC `s:A`) THEN
    ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN(fun iff ->
               MP_TAC(EQ_MP iff (ASSUME `(E:A->A->bool) s pr`))) THEN
    DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "sp")
      (X_CHOOSE_THEN `u:A` (X_CHOOSE_THEN `w:A` STRIP_ASSUME_TAC))) THEN
    (* E s ci *)
    SUBGOAL_THEN `(E:A->A->bool) s ci` (LABEL_TAC "sci") THENL
     [UNDISCH_TAC `esubset D (E:A->A->bool) p ci` THEN
      REWRITE_TAC[esubset] THEN
      DISCH_THEN MATCH_MP_TAC THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    (* ci char: ?u' w'. E u' ii /\ E w' tw /\ eopair u' w' s *)
    USE_THEN "crci" (MP_TAC o CONJUNCT2 o REWRITE_RULE[ecross]) THEN
    DISCH_THEN(MP_TAC o SPEC `s:A`) THEN
    ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    USE_THEN "sci" (fun sci -> DISCH_THEN(MP_TAC o C EQ_MP sci)) THEN
    DISCH_THEN(X_CHOOSE_THEN `u':A`
               (X_CHOOSE_THEN `w':A` STRIP_ASSUME_TAC)) THEN
    (* EOPAIR_INJ: u=u', w=w' *)
    MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`u:A`;`w:A`;`u':A`;`w':A`;`s:A`]
      EOPAIR_INJ) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(CONJUNCTS_THEN2 (K ALL_TAC) SUBST_ALL_TAC) THEN
    (* E s rt *)
    USE_THEN "crrt" (MP_TAC o CONJUNCT2 o REWRITE_RULE[ecross]) THEN
    DISCH_THEN(MP_TAC o SPEC `s:A`) THEN
    ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    MAP_EVERY EXISTS_TAC [`u:A`;`w':A`] THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* E pr S via epow char *)
  USE_THEN "epowS" (MP_TAC o CONJUNCT2 o REWRITE_RULE[epow]) THEN
  DISCH_THEN(MP_TAC o SPEC `pr:A`) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  USE_THEN "subprrt" ACCEPT_TAC);;

(* F6.3 helper: the domain of a Cohen condition p (E p P) is K-finite and a
   subset of the index set ii.  From ecohenp: p SUBSET ci, p efunctional, and p
   bijects a natural n < om -- so p is finite (EBIJ_TO_FIN); its members are
   pairs (p SUBSET ci = ii x tw); hence dom(p) finite (EFIN_DOMAIN) and
   dom(p) SUBSET ii (EDOMAIN_SUBSET_II).  This is exactly the per-index premise
   of the indexed Delta-system hypothesis. *)
let COHEN_DOM_FIN_SUB = prove
 (`!D (E:A->A->bool) ii tw ci om P p dp.
     model D E ZF_AX /\ eomega D E om /\
     ecross D E ii tw ci /\ ecohenp D E ci om P /\ p IN D /\ E p P /\
       edomain D E p dp
     ==> efin D E dp /\ esubset D E dp ii`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "mdl omega crci cp pD pP dom" THEN
  (* unpack ecohenp at p: esubset p ci, efunctional p, ?n<om. ?f. ebij f n p *)
  USE_THEN "cp" (MP_TAC o CONJUNCT2 o REWRITE_RULE[ecohenp]) THEN
  DISCH_THEN(MP_TAC o SPEC `p:A`) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  USE_THEN "pP" (fun pP -> DISCH_THEN(MP_TAC o C EQ_MP pP)) THEN
  DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "subpci")
    (CONJUNCTS_THEN2 (K ALL_TAC)
     (X_CHOOSE_THEN `n:A` (CONJUNCTS_THEN2 (LABEL_TAC "nD")
      (CONJUNCTS_THEN2 (LABEL_TAC "nom")
       (X_CHOOSE_THEN `f:A` (LABEL_TAC "bijf"))))))) THEN
  (* efin p via EBIJ_TO_FIN *)
  SUBGOAL_THEN `efin D (E:A->A->bool) p` (LABEL_TAC "finp") THENL
   [MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`om:A`;`n:A`;`p:A`;`f:A`]
      EBIJ_TO_FIN) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* members of p are ordered pairs (p SUBSET ci = ii x tw) *)
  SUBGOAL_THEN
   `!z:A. z IN D /\ E z p ==> ?u w. u IN D /\ w IN D /\ eopair D E u w z`
   (LABEL_TAC "pairs") THENL
   [X_GEN_TAC `z:A` THEN STRIP_TAC THEN
    SUBGOAL_THEN `(E:A->A->bool) z ci` (LABEL_TAC "zci") THENL
     [UNDISCH_TAC `esubset D (E:A->A->bool) p ci` THEN
      REWRITE_TAC[esubset] THEN
      DISCH_THEN MATCH_MP_TAC THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    USE_THEN "crci" (MP_TAC o CONJUNCT2 o REWRITE_RULE[ecross]) THEN
    DISCH_THEN(MP_TAC o SPEC `z:A`) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    ASM_REWRITE_TAC[] THEN
    DISCH_THEN(X_CHOOSE_THEN `u:A` (X_CHOOSE_THEN `w:A` STRIP_ASSUME_TAC)) THEN
    MAP_EVERY EXISTS_TAC [`u:A`;`w:A`] THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  CONJ_TAC THENL
   [MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`p:A`;`dp:A`]
                 EFIN_DOMAIN) THEN
    ASM_REWRITE_TAC[];
    MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`ii:A`;`tw:A`;`ci:A`;
                        `p:A`;`dp:A`]
                 EDOMAIN_SUBSET_II) THEN ASM_REWRITE_TAC[]]);;

(* F6.3 step-5 packaging: COHEN_COMPAT_FROM_AGREE.  Two Cohen conditions p,q
   whose domains meet in r (einter dp dq r) and which agree on r (pr=qr) are
   compatible in the poset (P,leqp): w = p UNION q is a common condition below
   both.  Chains: efunctional q (ecohenp) + dom-inter + pr=qr ->
     RESTRICT_EQ_AGREE
   pointwise-agreement -> COHEN_UNION_IS_CONDITION (E w P); p,q SUBSET w
   (EBUNION_MEM) -> <w,p>,<w,q> IN leqp (eleqp) -> ecompat. *)
let COHEN_COMPAT_FROM_AGREE = prove
 (`!D (E:A->A->bool) ci om P leqp p q dp dq r pr qr w.
     model D E ZF_AX /\ eomega D E om /\
     ecohenp D E ci om P /\ eleqp D E P leqp /\
     E p P /\ E q P /\ p IN D /\ q IN D /\
     edomain D E p dp /\ edomain D E q dq /\ einter D E dp dq r /\
     erestrict D E p r pr /\ erestrict D E q r qr /\ pr = qr /\
     ebunion D E p q w
     ==> ecompat D E P leqp p q`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "mdl omega cp leqpP pP qP pD qD domp domq intr rp rq eqr bun" THEN
  (* efunctional q from ecohenp characterization *)
  SUBGOAL_THEN `efunctional D (E:A->A->bool) q` (LABEL_TAC "fnq") THENL
   [USE_THEN "cp" (MP_TAC o CONJUNCT2 o REWRITE_RULE[ecohenp]) THEN
    DISCH_THEN(MP_TAC o SPEC `q:A`) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    USE_THEN "qP" (fun qp -> DISCH_THEN(MP_TAC o C EQ_MP qp)) THEN
    STRIP_TAC THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* common domain point lands in r *)
  SUBGOAL_THEN
   `!u:A. u IN D /\ eindom D (E:A->A->bool) p u /\ eindom D E q u ==> E u r`
   (LABEL_TAC "dsub") THENL
   [X_GEN_TAC `u:A` THEN STRIP_TAC THEN
    SUBGOAL_THEN `(E:A->A->bool) u dp` ASSUME_TAC THENL
     [ASM_MESON_TAC[edomain]; ALL_TAC] THEN
    SUBGOAL_THEN `(E:A->A->bool) u dq` ASSUME_TAC THENL
     [ASM_MESON_TAC[edomain]; ALL_TAC] THEN
    UNDISCH_TAC `einter D (E:A->A->bool) dp dq r` THEN REWRITE_TAC[einter] THEN
    DISCH_THEN(CONJUNCTS_THEN2 (K ALL_TAC) (MP_TAC o SPEC `u:A`)) THEN
    ASM_MESON_TAC[]; ALL_TAC] THEN
  (* pointwise agreement of p,q on their overlap *)
  MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`p:A`;`q:A`;`r:A`;`pr:A`;`qr:A`]
    RESTRICT_EQ_AGREE) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(LABEL_TAC "agree") THEN
  (* efunctional p (mirror fnq), then efunctional w = p UNION q via
     EFUN_UNION_AGREE -- the base COHEN_UNION_IS_CONDITION needs
       efunctional w *)
  SUBGOAL_THEN `efunctional D (E:A->A->bool) p` (LABEL_TAC "fnp") THENL
   [USE_THEN "cp" (MP_TAC o CONJUNCT2 o REWRITE_RULE[ecohenp]) THEN
    DISCH_THEN(MP_TAC o SPEC `p:A`) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    USE_THEN "pP" (fun pp -> DISCH_THEN(MP_TAC o C EQ_MP pp)) THEN
    STRIP_TAC THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `efunctional D (E:A->A->bool) w` (LABEL_TAC "fnw") THENL
   [MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`p:A`;`q:A`;`w:A`]
      EFUN_UNION_AGREE) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* w = p UNION q is a Cohen condition *)
  SUBGOAL_THEN `(E:A->A->bool) w P` (LABEL_TAC "wP") THENL
   [MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`ci:A`;`om:A`;`P:A`;`p:A`;
      `q:A`;`w:A`] COHEN_UNION_IS_CONDITION) THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  (* p,q SUBSET w *)
  MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`p:A`;`q:A`;`w:A`] EBUNION_MEM) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(CONJUNCTS_THEN2 (K ALL_TAC) (LABEL_TAC "wmem")) THEN
  SUBGOAL_THEN `esubset D (E:A->A->bool) p w` (LABEL_TAC "subpw") THENL
   [REWRITE_TAC[esubset] THEN X_GEN_TAC `t:A` THEN STRIP_TAC THEN
    USE_THEN "wmem" (MP_TAC o SPEC `t:A`) THEN ASM_MESON_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `esubset D (E:A->A->bool) q w` (LABEL_TAC "subqw") THENL
   [REWRITE_TAC[esubset] THEN X_GEN_TAC `t:A` THEN STRIP_TAC THEN
    USE_THEN "wmem" (MP_TAC o SPEC `t:A`) THEN ASM_MESON_TAC[]; ALL_TAC] THEN
  (* generic: any P-member x SUBSET w gives <w,x> IN leqp, i.e. erel leqp w *)
  (* x *)
  SUBGOAL_THEN `(w:A) IN D` (LABEL_TAC "wD") THENL
   [FIRST_ASSUM(ACCEPT_TAC o MATCH_MP EBUNION_IN); ALL_TAC] THEN
  SUBGOAL_THEN
   `!x:A. x IN D /\ E x P /\ esubset D (E:A->A->bool) x w ==>
    erel D E leqp w x`
   (LABEL_TAC "erelw") THENL
   [X_GEN_TAC `x:A` THEN STRIP_TAC THEN REWRITE_TAC[erel] THEN
    ASM_REWRITE_TAC[] THEN
    MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`w:A`;`x:A`] EOPAIR_EXISTS) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(X_CHOOSE_THEN `wx:A` (LABEL_TAC "pairwx")) THEN
    SUBGOAL_THEN `(wx:A) IN D` ASSUME_TAC THENL
     [USE_THEN "pairwx" (ACCEPT_TAC o MATCH_MP EOPAIR_IN); ALL_TAC] THEN
    EXISTS_TAC `wx:A` THEN ASM_REWRITE_TAC[] THEN
    USE_THEN "leqpP" (MP_TAC o CONJUNCT2 o REWRITE_RULE[eleqp]) THEN
    DISCH_THEN(MP_TAC o SPEC `wx:A`) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    MAP_EVERY EXISTS_TAC [`w:A`; `x:A`] THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leqp w p` (LABEL_TAC "erelp") THENL
   [USE_THEN "erelw" (MP_TAC o SPEC `p:A`) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN DISCH_THEN ACCEPT_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leqp w q` (LABEL_TAC "erelq") THENL
   [USE_THEN "erelw" (MP_TAC o SPEC `q:A`) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN DISCH_THEN ACCEPT_TAC;
    ALL_TAC] THEN
  REWRITE_TAC[ecompat] THEN EXISTS_TAC `w:A` THEN ASM_REWRITE_TAC[]);;

(* F6.3 pigeonhole core: FAMILY_COLLISION.  A single-valued family
  gg indexed by
   an uncountable set II, landing in a K-finite set ss, must repeat a value:
   two distinct indices al,be IN II with gg(al)=gg(be).  Contrapositive of
   UNCOUNTABLE_NOT_INJ_FIN: if gg NEVER repeats then gg is an
     injection II >-> ss
   of an uncountable set into a finite one -- impossible.  (ss/II/gg
     names chosen
   to dodge the S/I combinators; t is a value not a formula.) *)
let FAMILY_COLLISION = prove
 (`!D (E:A->A->bool) om II ss gg.
     model D E ZF_AX /\ eomega D E om /\
     II IN D /\ ss IN D /\ efin D E ss /\ gg IN D /\
     (!k t. k IN D /\ t IN D /\ eapply D E gg k t ==> E k II /\ E t ss) /\
     (!k. k IN D /\ E k II ==> ?t. t IN D /\ eapply D E gg k t) /\
     (!k t t'. k IN D /\ t IN D /\ t' IN D /\
               eapply D E gg k t /\ eapply D E gg k t' ==> t = t') /\
     ~(?e. einj D E e II om)
     ==> ?al be t. al IN D /\ be IN D /\ t IN D /\
                   E al II /\ E be II /\ ~(al = be) /\
                   eapply D E gg al t /\ eapply D E gg be t`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "mdl omega iiD ssD finss ggD cod tot svgg noinj" THEN
  (* by contradiction: no repeated value ==> gg is an injection II >-> ss *)
  MATCH_MP_TAC(TAUT `(~p ==> F) ==> p`) THEN
  DISCH_THEN(LABEL_TAC "noc") THEN
  MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`om:A`;`II:A`;`ss:A`;`gg:A`]
    UNCOUNTABLE_NOT_INJ_FIN) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[] THEN
    REWRITE_TAC[einj] THEN REPEAT CONJ_TAC THENL
     [(* gg IN D *) USE_THEN "ggD" ACCEPT_TAC;
      (* dom/cod *) USE_THEN "cod" ACCEPT_TAC;
      (* total into ss *)
      X_GEN_TAC `k:A` THEN STRIP_TAC THEN
      USE_THEN "tot" (MP_TAC o SPEC `k:A`) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(X_CHOOSE_THEN `t:A` STRIP_ASSUME_TAC) THEN
      EXISTS_TAC `t:A` THEN ASM_REWRITE_TAC[] THEN
      USE_THEN "cod" (MP_TAC o SPECL[`k:A`;`t:A`]) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(ACCEPT_TAC o CONJUNCT2);
      (* single-valued *) USE_THEN "svgg" ACCEPT_TAC;
      (* injective: distinct indices with same value contradict noc *)
      MAP_EVERY X_GEN_TAC [`k:A`; `k':A`; `t:A`] THEN STRIP_TAC THEN
      SUBGOAL_THEN `(E:A->A->bool) k (II:A) /\ E k' II` STRIP_ASSUME_TAC THENL
       [CONJ_TAC THENL
         [USE_THEN "cod" (MP_TAC o SPECL[`k:A`;`t:A`]) THEN
          ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
          DISCH_THEN(ACCEPT_TAC o CONJUNCT1);
          USE_THEN "cod" (MP_TAC o SPECL[`k':A`;`t:A`]) THEN
          ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
          DISCH_THEN(ACCEPT_TAC o CONJUNCT1)];
        ALL_TAC] THEN
      ASM_MESON_TAC[]];
    DISCH_THEN ACCEPT_TAC]);;

(* F6.3 CAPSTONE: CCC_COHEN_MODULO_DELTA.  The Cohen poset (P,leqp) over the
   index cross ci = ii x tw is ccc, GIVEN the indexed Delta-system hypothesis
   as an explicit premise (discharged later in F6.2).

   Proof (contradiction): let a be an antichain; if a injects into om we are
   done.  Otherwise a is uncountable, so (EUNCOUNTABLE_SUCCARD_INJ) the
   successor cardinal a1 injects into a by e.  Push the domain family
   ff : b |-> dom(ea b) (N1 EDOMIMG_FAMILY); each dom is finite and SUBSET ii
   (COHEN_DOM_FIN_SUB),
   so the Delta hypothesis yields an uncountable jj SUBSET a1
   and a finite root r with all pairwise domain-intersections EQUAL to r.  Push
   the restriction family gg : b |-> (ea b)|_r (N3 ERESTIMG_FAMILY); each value
   lands in S = epow(r x tw),
   which is finite (EFIN_CROSS + EFIN_POW).  gg indexed
   by the uncountable jj into the finite S must collide (FAMILY_COLLISION): two
   distinct al,be in jj with (ea al)|_r = (ea be)|_r.  Their domains
     meet exactly
   in r (Delta), they agree on r (equal restrictions), so p=ea al, q=ea be are
   compatible (COHEN_COMPAT_FROM_AGREE) -- contradicting the antichain, since
   e injective gives p<>q. *)
let CCC_COHEN_MODULO_DELTA = prove
 (`!D (E:A->A->bool) ii tw ci om P leqp a1.
     model D E ZF_AX /\ (!u. u IN D ==> elmem D E u) /\
     eomega D E om /\
     ecross D E ii tw ci /\ efin D E tw /\
     ecohenp D E ci om P /\ eleqp D E P leqp /\
     a1 IN D /\ ecardinal D E a1 /\ E om a1 /\
     (!c'. c' IN D /\ E c' a1 ==> ~(ecardinal D E c' /\ E om c')) /\
     (!ff. ff IN D /\
           (!n z z'. n IN D /\ z IN D /\ z' IN D /\
                     eapply D E ff n z /\ eapply D E ff n z' ==> z = z') /\
           (!b. b IN D /\ E b a1
                ==> ?d. d IN D /\ eapply D E ff b d /\
                        efin D E d /\ esubset D E d ii)
           ==> ?jj r. jj IN D /\ r IN D /\ esubset D E jj a1 /\ efin D E r /\
                      ~(?e. einj D E e jj om) /\
                      (!al be dal dbe.
                         al IN D /\ be IN D /\ dal IN D /\ dbe IN D /\
                         E al jj /\ E be jj /\ ~(al = be) /\
                         eapply D E ff al dal /\ eapply D E ff be dbe
                         ==> einter D E dal dbe r))
     ==> eccc D E P leqp`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "mdl elm omega cross fintw cp leqpP a1D carda1 oma1 a1min \
             delta" THEN
  SUBGOAL_THEN `(tw:A) IN D` (LABEL_TAC "twD") THENL
   [USE_THEN "fintw" (ACCEPT_TAC o CONJUNCT1 o REWRITE_RULE[efin]);
    ALL_TAC] THEN
  REWRITE_TAC[eccc] THEN
  X_GEN_TAC `a:A` THEN
  DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "aD") (LABEL_TAC "anti")) THEN
  (* esubset a P from the antichain *)
  SUBGOAL_THEN `esubset D (E:A->A->bool) a P` (LABEL_TAC "suba") THENL
   [ASM_MESON_TAC[eantichain]; ALL_TAC] THEN
  ASM_CASES_TAC `?e:A. einj D (E:A->A->bool) e a om` THENL
   [(* countable: a injects into om directly *)
    FIRST_X_ASSUM(X_CHOOSE_THEN `e0:A` (LABEL_TAC "e0")) THEN
    SUBGOAL_THEN `(e0:A) IN D` ASSUME_TAC THENL
     [USE_THEN "e0" (ACCEPT_TAC o CONJUNCT1 o REWRITE_RULE[einj]);
      ALL_TAC] THEN
    MAP_EVERY EXISTS_TAC [`om:A`; `e0:A`] THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* uncountable: derive a contradiction *)
  UNDISCH_TAC `~(?e:A. einj D (E:A->A->bool) e a om)` THEN
  DISCH_THEN(LABEL_TAC "noc") THEN
  (* Step 1: a1 injects into a *)
  MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`om:A`;`a1:A`;`a:A`]
    EUNCOUNTABLE_SUCCARD_INJ) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `e:A` (LABEL_TAC "einje")) THEN
  USE_THEN "einje" (MP_TAC o REWRITE_RULE[einj]) THEN
  INTRO_TAC "eD ecod etot esv einj5" THEN
  (* Step 2: N1 domain family ff, valuation v1 = (12|->e)(\n.e) *)
  SUBGOAL_THEN `((12 |-> (e:A)) (\n:num. e)) 12 = e` (LABEL_TAC "v1e") THENL
   [REWRITE_TAC[VALMOD_BASIC]; ALL_TAC] THEN
  MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`(12 |-> (e:A)) (\n:num. e)`;`a1:A`]
    EDOMIMG_FAMILY) THEN
  ANTS_TAC THENL
   [REPEAT CONJ_TAC THENL
     [USE_THEN "mdl" ACCEPT_TAC;
      REWRITE_TAC[valuation] THEN GEN_TAC THEN REWRITE_TAC[VALMOD] THEN
      REPEAT(COND_CASES_TAC THEN ASM_REWRITE_TAC[]) THEN ASM_REWRITE_TAC[];
      USE_THEN "a1D" ACCEPT_TAC;
      USE_THEN "v1e" (fun th -> REWRITE_TAC[th]) THEN
      USE_THEN "esv" ACCEPT_TAC;
      USE_THEN "v1e" (fun th -> REWRITE_TAC[th]) THEN
      X_GEN_TAC `u:A` THEN STRIP_TAC THEN
      USE_THEN "etot" (MP_TAC o SPEC `u:A`) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(X_CHOOSE_THEN `t:A` STRIP_ASSUME_TAC) THEN
      EXISTS_TAC `t:A` THEN ASM_REWRITE_TAC[]];
    ALL_TAC] THEN
  INTRO_TAC "@ff. ffD ffsv ffpair ffidx0" THEN
  USE_THEN "v1e" (fun v1e -> USE_THEN "ffidx0" (fun th ->
    LABEL_TAC "ffidx" (REWRITE_RULE[v1e] th))) THEN
  (* Step 3: apply the Delta hypothesis to ff *)
  USE_THEN "delta" (MP_TAC o SPEC `ff:A`) THEN
  ANTS_TAC THENL
   [CONJ_TAC THENL
     [USE_THEN "ffD" ACCEPT_TAC;
      CONJ_TAC THENL
       [USE_THEN "ffsv" ACCEPT_TAC;
        X_GEN_TAC `b:A` THEN STRIP_TAC THEN
        USE_THEN "ffidx" (MP_TAC o SPEC `b:A`) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
        DISCH_THEN(X_CHOOSE_THEN `pb:A`
                   (X_CHOOSE_THEN `db:A` STRIP_ASSUME_TAC)) THEN
        EXISTS_TAC `db:A` THEN ASM_REWRITE_TAC[] THEN
        SUBGOAL_THEN `(E:A->A->bool) pb a` (LABEL_TAC "pba") THENL
         [USE_THEN "ecod" (MP_TAC o SPECL[`b:A`;`pb:A`]) THEN
          ANTS_TAC THENL
           [ASM_REWRITE_TAC[]; DISCH_THEN(ACCEPT_TAC o CONJUNCT2)];
           ALL_TAC] THEN
        SUBGOAL_THEN `(E:A->A->bool) pb P` (LABEL_TAC "pbP") THENL
         [UNDISCH_TAC `esubset D (E:A->A->bool) a P` THEN
          REWRITE_TAC[esubset] THEN
          DISCH_THEN MATCH_MP_TAC THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
        MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`ii:A`;`tw:A`;
                            `ci:A`;`om:A`;
                            `P:A`;`pb:A`;`db:A`] COHEN_DOM_FIN_SUB) THEN
        ASM_REWRITE_TAC[]]];
    ALL_TAC] THEN
  INTRO_TAC "@jj r. jjD rD subjja1 finr jjunc dinter" THEN
  (* Step 4: build rt = r x tw and S = epow rt, finite *)
  MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`r:A`;`tw:A`] ECROSS_EXISTS) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `rt:A` (LABEL_TAC "crt")) THEN
  SUBGOAL_THEN `(rt:A) IN D` (LABEL_TAC "rtD") THENL
   [USE_THEN "crt" (ACCEPT_TAC o CONJUNCT1 o REWRITE_RULE[ecross]);
    ALL_TAC] THEN
  SUBGOAL_THEN `efin D (E:A->A->bool) rt` (LABEL_TAC "finrt") THENL
   [MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`om:A`;`r:A`;`tw:A`;`rt:A`]
      EFIN_CROSS) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`rt:A`] EPOW_EXISTS) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `S:A` (LABEL_TAC "epowS")) THEN
  SUBGOAL_THEN `(S:A) IN D` (LABEL_TAC "SD") THENL
   [USE_THEN "epowS" (ACCEPT_TAC o CONJUNCT1 o REWRITE_RULE[epow]);
    ALL_TAC] THEN
  SUBGOAL_THEN `efin D (E:A->A->bool) S` (LABEL_TAC "finS") THENL
   [MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`om:A`;`rt:A`;`S:A`]
      EFIN_POW) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* Step 5: N3 restriction family gg, valuation v2 = *)
  (* (13|->r)((12|->e)(\n.e)) *)
  SUBGOAL_THEN `((13 |-> (r:A)) ((12 |-> (e:A)) (\n:num. e))) 13 = r`
    (LABEL_TAC "v2r") THENL [REWRITE_TAC[VALMOD_BASIC]; ALL_TAC] THEN
  SUBGOAL_THEN `((13 |-> (r:A)) ((12 |-> (e:A)) (\n:num. e))) 12 = e`
    (LABEL_TAC "v2e") THENL
   [SUBGOAL_THEN
      `((13 |-> (r:A)) ((12 |-> (e:A)) (\n:num. e))) 12
       = ((12 |-> (e:A)) (\n:num. e)) 12` SUBST1_TAC THENL
     [MATCH_MP_TAC VALMOD_OTHER THEN CONV_TAC NUM_REDUCE_CONV;
      REWRITE_TAC[VALMOD_BASIC]]; ALL_TAC] THEN
  MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;
    `(13 |-> (r:A)) ((12 |-> (e:A)) (\n:num. e))`;`jj:A`] ERESTIMG_FAMILY) THEN
  ANTS_TAC THENL
   [REPEAT CONJ_TAC THENL
     [USE_THEN "mdl" ACCEPT_TAC;
      REWRITE_TAC[valuation] THEN GEN_TAC THEN REWRITE_TAC[VALMOD] THEN
      REPEAT(COND_CASES_TAC THEN ASM_REWRITE_TAC[]) THEN ASM_REWRITE_TAC[];
      USE_THEN "jjD" ACCEPT_TAC;
      USE_THEN "v2e" (fun th -> REWRITE_TAC[th]) THEN
      USE_THEN "esv" ACCEPT_TAC;
      USE_THEN "v2e" (fun th -> REWRITE_TAC[th]) THEN
      X_GEN_TAC `u:A` THEN STRIP_TAC THEN
      USE_THEN "etot" (MP_TAC o SPEC `u:A`) THEN
      ANTS_TAC THENL
       [ASM_REWRITE_TAC[] THEN
        UNDISCH_TAC `esubset D (E:A->A->bool) jj a1` THEN
        REWRITE_TAC[esubset] THEN
        DISCH_THEN MATCH_MP_TAC THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(X_CHOOSE_THEN `t:A` STRIP_ASSUME_TAC) THEN
      EXISTS_TAC `t:A` THEN ASM_REWRITE_TAC[]];
    ALL_TAC] THEN
  INTRO_TAC "@gg. ggD ggsv ggpair ggidx0" THEN
  USE_THEN "v2e"
    (fun v2e -> USE_THEN "v2r" (fun v2r -> USE_THEN "ggidx0" (fun th ->
    LABEL_TAC "ggidx" (REWRITE_RULE[v2e;v2r] th)))) THEN
  (* Step 6: gg maps jj into the finite S (cod clause for FAMILY_COLLISION) *)
  SUBGOAL_THEN
   `!k t. k IN D /\ t IN D /\ eapply D (E:A->A->bool) gg k t
          ==> E k jj /\ E t S`
   (LABEL_TAC "ggcod") THENL
   [MAP_EVERY X_GEN_TAC [`k:A`;`t:A`] THEN
    DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "kD")
      (CONJUNCTS_THEN2 (LABEL_TAC "tD") (LABEL_TAC "ekt"))) THEN
    SUBGOAL_THEN `(E:A->A->bool) k jj` (LABEL_TAC "kjj") THENL
     [USE_THEN "ekt" (MP_TAC o REWRITE_RULE[eapply]) THEN
      DISCH_THEN(X_CHOOSE_THEN `z:A` (CONJUNCTS_THEN2 (LABEL_TAC "pairz")
        (LABEL_TAC "zgg"))) THEN
      SUBGOAL_THEN `(z:A) IN D` ASSUME_TAC THENL
       [ASM_MESON_TAC[EOPAIR_IN]; ALL_TAC] THEN
      USE_THEN "ggpair" (MP_TAC o SPEC `z:A`) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(X_CHOOSE_THEN `b:A`
                 (X_CHOOSE_THEN `zz:A` STRIP_ASSUME_TAC)) THEN
      MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`k:A`;`t:A`;`b:A`;`zz:A`;`z:A`]
        EOPAIR_INJ) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(CONJUNCTS_THEN2 SUBST1_TAC (K ALL_TAC)) THEN
      ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    CONJ_TAC THENL
     [USE_THEN "kjj" ACCEPT_TAC;
      USE_THEN "ggidx" (MP_TAC o SPEC `k:A`) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(X_CHOOSE_THEN `pp:A`
                 (X_CHOOSE_THEN `dd:A` STRIP_ASSUME_TAC)) THEN
      SUBGOAL_THEN `t:A = dd` SUBST_ALL_TAC THENL
       [ASM_MESON_TAC[]; ALL_TAC] THEN
      (* esubset pp ci from ecohenp, then ERESTRICT_IN_POW_CROSS *)
      SUBGOAL_THEN `(E:A->A->bool) pp a` (LABEL_TAC "ppa") THENL
       [USE_THEN "ecod" (MP_TAC o SPECL[`k:A`;`pp:A`]) THEN
        ANTS_TAC THENL
         [ASM_REWRITE_TAC[]; DISCH_THEN(ACCEPT_TAC o CONJUNCT2)]; ALL_TAC] THEN
      SUBGOAL_THEN `(E:A->A->bool) pp P` (LABEL_TAC "ppP") THENL
       [UNDISCH_TAC `esubset D (E:A->A->bool) a P` THEN
        REWRITE_TAC[esubset] THEN
        DISCH_THEN MATCH_MP_TAC THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
      SUBGOAL_THEN `esubset D (E:A->A->bool) pp ci` (LABEL_TAC "subppci") THENL
       [USE_THEN "cp" (MP_TAC o CONJUNCT2 o REWRITE_RULE[ecohenp]) THEN
        DISCH_THEN(MP_TAC o SPEC `pp:A`) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
        USE_THEN "ppP" (fun ppP -> DISCH_THEN(MP_TAC o C EQ_MP ppP)) THEN
        DISCH_THEN(ACCEPT_TAC o CONJUNCT1); ALL_TAC] THEN
      MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`ii:A`;`tw:A`;
                          `ci:A`;`r:A`;
                          `rt:A`;`S:A`;`pp:A`;`dd:A`]
          ERESTRICT_IN_POW_CROSS) THEN
      ASM_REWRITE_TAC[]];
    ALL_TAC] THEN
  (* Step 7: gg total on jj *)
  SUBGOAL_THEN
   `!k. k IN D /\ E k jj ==> ?t. t IN D /\ eapply D (E:A->A->bool) gg k t`
   (LABEL_TAC "ggtot") THENL
   [X_GEN_TAC `k:A` THEN STRIP_TAC THEN
    USE_THEN "ggidx" (MP_TAC o SPEC `k:A`) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(X_CHOOSE_THEN `pp:A`
               (X_CHOOSE_THEN `dd:A` STRIP_ASSUME_TAC)) THEN
    EXISTS_TAC `dd:A` THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* Step 8: FAMILY_COLLISION -- two distinct indices with the same gg-value *)
  MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`om:A`;`jj:A`;`S:A`;`gg:A`]
    FAMILY_COLLISION) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  INTRO_TAC "@al be vcol. alD beD vcolD aljj bejj albe ggal ggbe" THEN
  (* al, be IN jj SUBSET a1 give E al a1 / E be a1 (ffidx is indexed by a1) *)
  SUBGOAL_THEN `(E:A->A->bool) al a1` (LABEL_TAC "ala1") THENL
   [UNDISCH_TAC `esubset D (E:A->A->bool) jj a1` THEN REWRITE_TAC[esubset] THEN
    DISCH_THEN MATCH_MP_TAC THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) be a1` (LABEL_TAC "bea1") THENL
   [UNDISCH_TAC `esubset D (E:A->A->bool) jj a1` THEN REWRITE_TAC[esubset] THEN
    DISCH_THEN MATCH_MP_TAC THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* Step 9: unpack al via N1 (domain) and N3 (restriction) *)
  USE_THEN "ffidx" (MP_TAC o SPEC `al:A`) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `pal:A`
             (X_CHOOSE_THEN `Dal:A` STRIP_ASSUME_TAC)) THEN
  USE_THEN "ffidx" (MP_TAC o SPEC `be:A`) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `pbe:A`
             (X_CHOOSE_THEN `Dbe:A` STRIP_ASSUME_TAC)) THEN
  USE_THEN "ggidx" (MP_TAC o SPEC `al:A`) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `qal:A`
             (X_CHOOSE_THEN `Ral:A` STRIP_ASSUME_TAC)) THEN
  USE_THEN "ggidx" (MP_TAC o SPEC `be:A`) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `qbe:A`
             (X_CHOOSE_THEN `Rbe:A` STRIP_ASSUME_TAC)) THEN
  (* pal = qal, pbe = qbe (e single-valued); Ral = vcol = Rbe (gg *)
  (* single-valued) *)
  SUBGOAL_THEN `qal:A = pal` SUBST_ALL_TAC THENL
  [ASM_MESON_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `qbe:A = pbe` SUBST_ALL_TAC THENL
  [ASM_MESON_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `Ral:A = vcol` SUBST_ALL_TAC THENL
   [USE_THEN "ggsv" (MP_TAC o SPECL[`al:A`;`Ral:A`;`vcol:A`]) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC]; ALL_TAC] THEN
  SUBGOAL_THEN `Rbe:A = vcol` SUBST_ALL_TAC THENL
   [USE_THEN "ggsv" (MP_TAC o SPECL[`be:A`;`Rbe:A`;`vcol:A`]) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC]; ALL_TAC] THEN
  (* now: edomain pal Dal, eapply ff al Dal; edomain pbe Dbe, eapply ff be Dbe;
          erestrict pal r vcol; erestrict pbe r vcol *)
  (* Step 10: domains meet exactly in r (Delta intersection clause) *)
  SUBGOAL_THEN `einter D (E:A->A->bool) Dal Dbe r` (LABEL_TAC "intr") THENL
   [USE_THEN "dinter"
    (MATCH_MP_TAC o SPECL[`al:A`;`be:A`;`Dal:A`;`Dbe:A`]) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* Step 11: pal, pbe are P-members; pal <> pbe (e injective) *)
  SUBGOAL_THEN `(E:A->A->bool) pal a` (LABEL_TAC "pala") THENL
   [USE_THEN "ecod" (MP_TAC o SPECL[`al:A`;`pal:A`]) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[]; DISCH_THEN(ACCEPT_TAC o CONJUNCT2)]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) pbe a` (LABEL_TAC "pbea") THENL
   [USE_THEN "ecod" (MP_TAC o SPECL[`be:A`;`pbe:A`]) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[]; DISCH_THEN(ACCEPT_TAC o CONJUNCT2)]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) pal P` (LABEL_TAC "palP") THENL
   [UNDISCH_TAC `esubset D (E:A->A->bool) a P` THEN REWRITE_TAC[esubset] THEN
    DISCH_THEN MATCH_MP_TAC THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) pbe P` (LABEL_TAC "pbeP") THENL
   [UNDISCH_TAC `esubset D (E:A->A->bool) a P` THEN REWRITE_TAC[esubset] THEN
    DISCH_THEN MATCH_MP_TAC THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `~(pal:A = pbe)` (LABEL_TAC "palpbe") THENL
   [DISCH_TAC THEN UNDISCH_TAC `~(al:A = be)` THEN REWRITE_TAC[] THEN
    ASM_MESON_TAC[]; ALL_TAC] THEN
  (* Step 12: build w = pal UNION pbe *)
  MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`pal:A`;`pbe:A`]
         EBUNION_EXISTS) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `w:A` (LABEL_TAC "bun")) THEN
  (* Step 13: pal, pbe are compatible *)
  SUBGOAL_THEN `ecompat D (E:A->A->bool) P leqp pal pbe`
    (LABEL_TAC "compat") THENL
   [MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`ci:A`;`om:A`;
                        `P:A`;`leqp:A`;
                        `pal:A`;`pbe:A`;`Dal:A`;`Dbe:A`;`r:A`;`vcol:A`;
                        `vcol:A`;`w:A`]
      COHEN_COMPAT_FROM_AGREE) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* Step 14: contradiction with the antichain *)
  UNDISCH_TAC `eantichain D (E:A->A->bool) P leqp a` THEN
  REWRITE_TAC[eantichain] THEN
  DISCH_THEN(MP_TAC o SPECL[`pal:A`;`pbe:A`] o CONJUNCT2 o CONJUNCT2) THEN
  ASM_REWRITE_TAC[]);;

(* ============================================================
   F6.2 batch s1 (Delta-system, uniform-size fibers): s1a s1c s1b.
   ENAT_CARD_UNIQUE (finite cardinality unique), EUNCOUNTABLE_CARD
   (successor cardinal does not inject into omega), and ESIZE_FAMILY
   (internal size map al |-> |fam(al)| via EIMG_FAMILY over sizegraph_form).
   ============================================================ *)

(* ==== F6.2 lemmas s1a and s1c ==== *)

(* s1a  ENAT_CARD_UNIQUE : finite cardinality is unique.
   If f: n -> p and f': n' -> p are bijections with n,n' IN omega, then n = n'.
   Proof: trichotomy on n,n'; in each strict case compose bijections to inject
   the larger into the smaller, contradicting EINJ_PIGEONHOLE. *)
let ENAT_CARD_UNIQUE = prove
 (`!D (E:A->A->bool) om n n' p f f'.
        model D E ZF_AX /\ eomega D E om /\
        n IN D /\ n' IN D /\ E n om /\ E n' om /\
        ebij D E f n p /\ ebij D E f' n' p
        ==> n = n'`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `eordinal D (E:A->A->bool) n /\ eordinal D (E:A->A->bool) n'`
    STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[EOMEGA_ORDINALS]; ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `n:A`; `n':A`]
    EORDINAL_TRICHOTOMY) THEN
  ASM_REWRITE_TAC[] THEN STRIP_TAC THENL
   [(* E n n' : n < n'; inject bigger n' into smaller n via f' then sym f *)
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `f:A`; `n:A`; `p:A`]
           EBIJ_SYM) THEN
    ASM_REWRITE_TAC[] THEN
    DISCH_THEN(X_CHOOSE_THEN `g:A` ASSUME_TAC) THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `f':A`; `g:A`;
                  `n':A`; `p:A`; `n:A`] EBIJ_COMPOSE) THEN
    ASM_REWRITE_TAC[] THEN
    DISCH_THEN(X_CHOOSE_THEN `h:A` ASSUME_TAC) THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `om:A`; `n':A`; `n:A`]
      EINJ_PIGEONHOLE) THEN
    ASM_REWRITE_TAC[] THEN DISCH_TAC THEN ASM_MESON_TAC[EBIJ_EINJ];
    (* E n' n : n' < n; inject bigger n into smaller n' via f then sym f'.
       NB the middle disjunct n=n' is auto-closed by STRIP_ASSUME_TAC's
       ACCEPT_TAC (goal is literally n=n'), so only 2 branches here. *)
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `f':A`; `n':A`; `p:A`]
           EBIJ_SYM) THEN
    ASM_REWRITE_TAC[] THEN
    DISCH_THEN(X_CHOOSE_THEN `g:A` ASSUME_TAC) THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `f:A`; `g:A`;
                  `n:A`; `p:A`; `n':A`] EBIJ_COMPOSE) THEN
    ASM_REWRITE_TAC[] THEN
    DISCH_THEN(X_CHOOSE_THEN `h:A` ASSUME_TAC) THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `om:A`; `n:A`; `n':A`]
      EINJ_PIGEONHOLE) THEN
    ASM_REWRITE_TAC[] THEN DISCH_TAC THEN ASM_MESON_TAC[EBIJ_EINJ]]);;

(* s1c  EUNCOUNTABLE_CARD : a successor cardinal a1 > om does not
  inject into om.
   ecardinal a1 = ecardof a1 a1;
   an injection a1 >-> om with EINJ_ORDINAL_CARD_LE
   forces E a1 om \/ a1 = om, either way contradicting E om a1 (E_NOCYCLE2). *)
let EUNCOUNTABLE_CARD = prove
 (`!D (E:A->A->bool) om a1.
        model D E ZF_AX /\ eomega D E om /\ a1 IN D /\
        ecardinal D E a1 /\ E om a1
        ==> ~(?e. einj D E e a1 om)`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  RULE_ASSUM_TAC(REWRITE_RULE[ecardinal]) THEN
  REWRITE_TAC[NOT_EXISTS_THM] THEN X_GEN_TAC `e:A` THEN DISCH_TAC THEN
  SUBGOAL_THEN `eordinal D (E:A->A->bool) om` ASSUME_TAC THENL
   [ASM_MESON_TAC[EOMEGA_ORDINAL]; ALL_TAC] THEN
  SUBGOAL_THEN `(om:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[EOMEGA_IN]; ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `e:A`; `a1:A`; `om:A`; `a1:A`]
    EINJ_ORDINAL_CARD_LE) THEN
  ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[E_NOCYCLE2]);;

(* ==== F6.2 lemma s1b : ESIZE_FAMILY (al |-> |fam(al)|) ====
   Mirrors N1 EDOMIMG_FAMILY exactly.  Graph out = <u, N> where
   N IN om and (?f. ebij f N (fam u)).  fam = v 12, om = v 13, ix=11, ox=63.
   bound slots: 70 = P = fam(u),
   80 = N.  bijform 80 70 uses internal 81..85. *)

let sizegraph_form = new_definition
  `sizegraph_form =
     ?? 70 (?? 80 (apply_form 12 11 70 &&
                   (80 %% 13) &&
                   bijform 80 70 &&
                   opair_form 11 80 63))`;;

let HOLDS_SIZEGRAPH = prove
 (`!D (E:A->A->bool) v u out.
     model D E ZF_AX /\ valuation D v /\ u IN D /\ out IN D
     ==> (holds D E ((63 |-> out) ((11 |-> u) v)) sizegraph_form <=>
          ?p. p IN D /\ ?n. n IN D /\
              eapply D E (v 12) u p /\ E n (v 13) /\ (?f. ebij D E f n p) /\
              eopair D E u n out)`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `valuation D ((63 |-> (out:A)) ((11 |-> (u:A)) v))`
    (LABEL_TAC "vw") THENL
   [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[] THEN
    MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  REWRITE_TAC[sizegraph_form; HOLDS_EX; HOLDS_AND] THEN
  SUBGOAL_THEN
   `!p n:A. p IN D /\ n IN D
      ==> (holds D E ((80 |-> n) ((70 |-> p)
             ((63 |-> (out:A)) ((11 |-> (u:A)) v)))) (apply_form 12 11 70) <=>
           eapply D E (v 12) u p) /\
          (holds D E ((80 |-> n) ((70 |-> p)
             ((63 |-> out) ((11 |-> u) v)))) (80 %% 13) <=>
           E n (v 13)) /\
          (holds D E ((80 |-> n) ((70 |-> p)
             ((63 |-> out) ((11 |-> u) v)))) (bijform 80 70) <=>
           (?f. ebij D E f n p)) /\
          (holds D E ((80 |-> n) ((70 |-> p)
             ((63 |-> out) ((11 |-> u) v)))) (opair_form 11 80 63) <=>
           eopair D E u n out)`
   (LABEL_TAC "piles") THENL
   [REPEAT GEN_TAC THEN STRIP_TAC THEN
    SUBGOAL_THEN
     `valuation D ((80 |-> (n:A)) ((70 |-> (p:A))
        ((63 |-> (out:A)) ((11 |-> (u:A)) v))))` ASSUME_TAC THENL
     [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
    REPEAT CONJ_TAC THENL
     [ASM_SIMP_TAC[HOLDS_APPLY_FORM] THEN
      REWRITE_TAC[VALMOD] THEN CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN
      REWRITE_TAC[];
      REWRITE_TAC[HOLDS_MEM; VALMOD] THEN
      CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN REWRITE_TAC[];
      MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`;
        `((80 |-> (n:A)) ((70 |-> (p:A))
          ((63 |-> (out:A)) ((11 |-> (u:A)) v))))`; `80`; `70`]
        HOLDS_BIJFORM_EBIJ) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
      REWRITE_TAC[VALMOD] THEN CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN
      REWRITE_TAC[];
      ASM_SIMP_TAC[HOLDS_OPAIR_FORM] THEN
      REWRITE_TAC[VALMOD] THEN CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN
      REWRITE_TAC[]];
    ALL_TAC] THEN
  MATCH_MP_TAC(MESON[]
    `(!s:A. s IN D ==> (P s <=> Q s))
     ==> ((?s. s IN D /\ P s) <=> (?s. s IN D /\ Q s))`) THEN
  X_GEN_TAC `p:A` THEN DISCH_TAC THEN
  MATCH_MP_TAC(MESON[]
    `(!s:A. s IN D ==> (P s <=> Q s))
     ==> ((?s. s IN D /\ P s) <=> (?s. s IN D /\ Q s))`) THEN
  X_GEN_TAC `n:A` THEN DISCH_TAC THEN
  USE_THEN "piles" (MP_TAC o SPECL [`p:A`; `n:A`]) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  STRIP_TAC THEN ASM_REWRITE_TAC[]);;

(* build sz = { <b, |fam b|> : b IN a1 } via EIMG_FAMILY. *)
let ESIZE_FAMILY = prove
 (`!D (E:A->A->bool) v a1.
     model D E ZF_AX /\ valuation D v /\ a1 IN D /\ eomega D E (v 13) /\
     (!u w w'. u IN D /\ w IN D /\ w' IN D /\
               eapply D E (v 12) u w /\ eapply D E (v 12) u w' ==> w = w') /\
     (!u. u IN D /\ E u a1
          ==> ?p. p IN D /\ eapply D E (v 12) u p /\ efin D E p)
     ==> ?sz. sz IN D /\
              (!n z z'. n IN D /\ z IN D /\ z' IN D /\
                        eapply D E sz n z /\ eapply D E sz n z' ==> z = z') /\
              (!q. q IN D /\ E q sz
                   ==> ?b z. b IN D /\ z IN D /\ E b a1 /\ eopair D E b z q) /\
              (!b. b IN D /\ E b a1
                   ==> ?p N. p IN D /\ N IN D /\
                             eapply D E (v 12) b p /\ E N (v 13) /\
                             (?f. ebij D E f N p) /\
                             eapply D E sz b N)`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "mdl valv a1D om svea tot" THEN
  MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `sizegraph_form`; `11`; `63`;
    `v:num->A`; `a1:A`] EIMG_FAMILY) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[] THEN REPEAT CONJ_TAC THENL
     [(* ~(11 = 63) *) CONV_TAC NUM_REDUCE_CONV;
      (* ---- FUNC: unique output pair per index ---- *)
      X_GEN_TAC `u:A` THEN STRIP_TAC THEN
      USE_THEN "tot" (MP_TAC o SPEC `u:A`) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(X_CHOOSE_THEN `p:A` STRIP_ASSUME_TAC) THEN
      MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `(v:num->A) 13`; `p:A`]
        EFIN_TO_NAT) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(X_CHOOSE_THEN `N:A`
                 (X_CHOOSE_THEN `f:A` STRIP_ASSUME_TAC)) THEN
      MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `u:A`; `N:A`]
             EOPAIR_EXISTS) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(X_CHOOSE_TAC `out:A`) THEN
      SUBGOAL_THEN `(out:A) IN D` ASSUME_TAC THENL
       [ASM_MESON_TAC[EOPAIR_IN]; ALL_TAC] THEN
      EXISTS_TAC `out:A` THEN
      SUBGOAL_THEN
       `holds D E ((63 |-> (out:A)) ((11 |-> (u:A)) v)) sizegraph_form`
       ASSUME_TAC THENL
       [MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `v:num->A`; `u:A`; `out:A`]
          HOLDS_SIZEGRAPH) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
        DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
        EXISTS_TAC `p:A` THEN ASM_REWRITE_TAC[] THEN
        EXISTS_TAC `N:A` THEN ASM_REWRITE_TAC[] THEN
        EXISTS_TAC `f:A` THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
      ASM_REWRITE_TAC[] THEN
      X_GEN_TAC `out':A` THEN
      DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC MP_TAC) THEN
      MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `v:num->A`; `u:A`; `out':A`]
        HOLDS_SIZEGRAPH) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
      INTRO_TAC "@pp. ppD @NN. NND eapp2 eNN (@gg. bij2) op2" THEN
      SUBGOAL_THEN `(pp:A) = p` SUBST_ALL_TAC THENL
       [ASM_MESON_TAC[]; ALL_TAC] THEN
      SUBGOAL_THEN `(NN:A) = N` SUBST_ALL_TAC THENL
       [ASM_MESON_TAC[ENAT_CARD_UNIQUE]; ALL_TAC] THEN
      ASM_MESON_TAC[EOPAIR_UNIQUE];
      (* ---- HF: every output is an ordered pair <u, N> ---- *)
      MAP_EVERY X_GEN_TAC [`u:A`; `out:A`] THEN STRIP_TAC THEN
      MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `v:num->A`; `u:A`; `out:A`]
        HOLDS_SIZEGRAPH) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th ->
        UNDISCH_TAC
          `holds D E ((63 |-> (out:A)) ((11 |-> (u:A)) v)) sizegraph_form` THEN
        REWRITE_TAC[th]) THEN
      DISCH_THEN(X_CHOOSE_THEN `p:A` (CONJUNCTS_THEN2 ASSUME_TAC
        (X_CHOOSE_THEN `N:A` STRIP_ASSUME_TAC))) THEN
      EXISTS_TAC `N:A` THEN ASM_REWRITE_TAC[]];
    ALL_TAC] THEN
  INTRO_TAC "@sz. szD mem rpairs sv peridx" THEN
  EXISTS_TAC `sz:A` THEN REPEAT CONJ_TAC THENL
   [USE_THEN "szD" ACCEPT_TAC;
    USE_THEN "sv" ACCEPT_TAC;
    USE_THEN "rpairs" ACCEPT_TAC;
    (* ---- per-index reshape: value = |fam b| ---- *)
    X_GEN_TAC `b:A` THEN STRIP_TAC THEN
    USE_THEN "peridx" (MP_TAC o SPEC `b:A`) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(X_CHOOSE_THEN `out:A`
               (X_CHOOSE_THEN `z:A` STRIP_ASSUME_TAC)) THEN
    MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `v:num->A`; `b:A`; `out:A`]
      HOLDS_SIZEGRAPH) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th ->
      UNDISCH_TAC
        `holds D E ((63 |-> (out:A)) ((11 |-> (b:A)) v)) sizegraph_form` THEN
      REWRITE_TAC[th]) THEN
    DISCH_THEN(X_CHOOSE_THEN `p:A` (CONJUNCTS_THEN2 ASSUME_TAC
      (X_CHOOSE_THEN `N:A` STRIP_ASSUME_TAC))) THEN
    SUBGOAL_THEN `(z:A) = N` SUBST_ALL_TAC THENL
     [MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `b:A`; `z:A`; `b:A`; `N:A`;
        `out:A`] EOPAIR_INJ) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(ACCEPT_TAC o CONJUNCT2); ALL_TAC] THEN
    (* ASM_REWRITE clears every conjunct except the existential
       `?f. ebij f N p` (a specific-witness assumption can't rewrite it);
       ASM_MESON supplies the witness f from the assumptions. *)
    MAP_EVERY EXISTS_TAC [`p:A`; `N:A`] THEN ASM_REWRITE_TAC[] THEN
    ASM_MESON_TAC[]]);;

(* ==== F6.2 lemma s2a : ENAT_BOUNDED_MAXEL ====
   A nonempty set s of naturals bounded below om (every member < b < om) has a
   maximum.  mx := eunion s (= sup); it is an ordinal <= b < om, so mx IN om;
   EOMEGA_CASES (mx empty or successor) forces mx IN s; the max property is
   EORDINAL_SUBSET_MEMBER applied to x SUBSET mx (each x IN s is contained in
   the union).  Member-in-D facts come from the explicit s IN D /
   E-guarded hypotheses. *)

let ENAT_BOUNDED_MAXEL = prove
 (`!D (E:A->A->bool) om s b.
        model D E ZF_AX /\ eomega D E om /\
        s IN D /\ (?m. m IN D /\ E m s) /\ b IN D /\ E b om /\
        (!x. x IN D /\ E x s ==> E x b)
        ==> ?mx. mx IN D /\ E mx s /\
                 (!x. x IN D /\ E x s ==> E x mx \/ x = mx)`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "mdl om sD (@m0. m0D m0s) bD bom bnd" THEN
  SUBGOAL_THEN `(om:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[EOMEGA_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `eordinal D (E:A->A->bool) om` (LABEL_TAC "omord") THENL
   [ASM_MESON_TAC[EOMEGA_ORDINAL]; ALL_TAC] THEN
  SUBGOAL_THEN `eordinal D (E:A->A->bool) b` (LABEL_TAC "bord") THENL
   [ASM_MESON_TAC[EOMEGA_ORDINALS]; ALL_TAC] THEN
  SUBGOAL_THEN `!x:A. x IN D /\ E x s ==> eordinal D (E:A->A->bool) x`
    (LABEL_TAC "sord") THENL
   [X_GEN_TAC `x:A` THEN STRIP_TAC THEN
    SUBGOAL_THEN `(E:A->A->bool) x om` ASSUME_TAC THENL
     [MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `x:A`; `b:A`; `om:A`]
        EORDINAL_MEM_TRANS) THEN
      ANTS_TAC THENL
       [ASM_REWRITE_TAC[] THEN USE_THEN "bnd" MATCH_MP_TAC THEN
        ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC];
      ALL_TAC] THEN
    ASM_MESON_TAC[EOMEGA_ORDINALS]; ALL_TAC] THEN
  MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `s:A`] EUNION_EXISTS) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `mx:A` (LABEL_TAC "un")) THEN
  SUBGOAL_THEN `(mx:A) IN D` (LABEL_TAC "mxD") THENL
   [ASM_MESON_TAC[EUNION_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `eordinal D (E:A->A->bool) mx` (LABEL_TAC "mxord") THENL
   [MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `s:A`; `mx:A`]
       EORDINAL_EUNION) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[] THEN X_GEN_TAC `c:A` THEN STRIP_TAC THEN
      USE_THEN "sord" MATCH_MP_TAC THEN ASM_REWRITE_TAC[];
      DISCH_THEN ACCEPT_TAC]; ALL_TAC] THEN
  (* reverse union decomposition : union witness carries IN D *)
  SUBGOAL_THEN `!w:A. w IN D ==> (E:A->A->bool) w mx
                      ==> ?u. u IN D /\ E u s /\ E w u`
    (LABEL_TAC "unrev") THENL
   [X_GEN_TAC `w:A` THEN DISCH_TAC THEN
    USE_THEN "un" (MP_TAC o SPEC `w:A` o CONJUNCT2 o REWRITE_RULE[eunion]) THEN
    ASM_REWRITE_TAC[] THEN MESON_TAC[]; ALL_TAC] THEN
  (* mx SUBSET b, hence E mx om *)
  SUBGOAL_THEN `esubset D (E:A->A->bool) mx b` (LABEL_TAC "mxsub") THENL
   [REWRITE_TAC[esubset] THEN X_GEN_TAC `w:A` THEN STRIP_TAC THEN
    USE_THEN "unrev" (fun uth ->
      X_CHOOSE_THEN `u:A` STRIP_ASSUME_TAC
        (MP (MP (SPEC `w:A` uth) (ASSUME `(w:A) IN D`))
            (ASSUME `(E:A->A->bool) w mx`))) THEN
    MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `w:A`; `u:A`; `b:A`]
      EORDINAL_MEM_TRANS) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[] THEN DISJ1_TAC THEN USE_THEN "bnd" MATCH_MP_TAC THEN
      ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC];
    ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) mx om` (LABEL_TAC "mxom") THENL
   [MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `mx:A`; `b:A`]
       EORDINAL_SUBSET_MEMBER) THEN
    ASM_REWRITE_TAC[] THEN STRIP_TAC THENL
     [MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `mx:A`; `b:A`; `om:A`]
        EORDINAL_MEM_TRANS) THEN
      ANTS_TAC THENL
       [ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[]; DISCH_THEN ACCEPT_TAC];
      ASM_MESON_TAC[]]; ALL_TAC] THEN
  (* mx IN s *)
  SUBGOAL_THEN `(E:A->A->bool) mx s` (LABEL_TAC "mxs") THENL
   [MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `om:A`; `mx:A`]
       EOMEGA_CASES) THEN
    ASM_REWRITE_TAC[] THEN STRIP_TAC THENL
     [(* eempty mx : then m0 SUBSET mx = empty, so m0 = mx IN s *)
      SUBGOAL_THEN `esubset D (E:A->A->bool) m0 mx` ASSUME_TAC THENL
       [REWRITE_TAC[esubset] THEN X_GEN_TAC `w:A` THEN STRIP_TAC THEN
        MATCH_MP_TAC(ISPECL
                     [`D:A->bool`; `E:A->A->bool`; `s:A`; `mx:A`; `m0:A`;
                      `w:A`] EUNION_MEM) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
      MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `m0:A`; `mx:A`]
        EORDINAL_SUBSET_MEMBER) THEN
      ANTS_TAC THENL
       [ASM_REWRITE_TAC[] THEN
        USE_THEN "sord" MATCH_MP_TAC THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
      STRIP_TAC THENL
       [UNDISCH_TAC `eempty D (E:A->A->bool) mx` THEN REWRITE_TAC[eempty] THEN
        DISCH_THEN(MP_TAC o SPEC `m0:A` o CONJUNCT2) THEN ASM_REWRITE_TAC[];
        FIRST_X_ASSUM(SUBST_ALL_TAC o check (is_eq o concl)) THEN
        USE_THEN "m0s" ACCEPT_TAC];
      (* successor mx = esuc m, m IN om : the union witness u = mx, so mx IN *)
      (* s *)
      SUBGOAL_THEN `(E:A->A->bool) m mx` (LABEL_TAC "mmx") THENL
       [MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `m:A`; `mx:A`]
          ESUC_MEMBER) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
      USE_THEN "unrev" (fun uth -> USE_THEN "mmx" (fun mth ->
        X_CHOOSE_THEN `u:A` STRIP_ASSUME_TAC
          (MP (MP (SPEC `m:A` uth) (ASSUME `(m:A) IN D`)) mth))) THEN
      SUBGOAL_THEN `esubset D (E:A->A->bool) u mx` ASSUME_TAC THENL
       [REWRITE_TAC[esubset] THEN X_GEN_TAC `w:A` THEN STRIP_TAC THEN
        MATCH_MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `s:A`; `mx:A`; `u:A`;
          `w:A`] EUNION_MEM) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
      SUBGOAL_THEN `eordinal D (E:A->A->bool) u` ASSUME_TAC THENL
       [USE_THEN "sord" MATCH_MP_TAC THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
      MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `u:A`; `mx:A`]
        EORDINAL_SUBSET_MEMBER) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      STRIP_TAC THENL
       [SUBGOAL_THEN `(E:A->A->bool) u m \/ u = m` STRIP_ASSUME_TAC THENL
         [MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `m:A`; `mx:A`; `u:A`]
            ESUC_E) THEN ASM_REWRITE_TAC[];
          ASM_MESON_TAC[E_NOCYCLE2];
          ASM_MESON_TAC[E_IRREFL]];
        FIRST_X_ASSUM(SUBST_ALL_TAC o check (is_eq o concl)) THEN
        FIRST_ASSUM ACCEPT_TAC]]; ALL_TAC] THEN
  (* assemble *)
  EXISTS_TAC `mx:A` THEN ASM_REWRITE_TAC[] THEN
  X_GEN_TAC `x:A` THEN STRIP_TAC THEN
  MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `x:A`; `mx:A`]
    EORDINAL_SUBSET_MEMBER) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
     [USE_THEN "sord" MATCH_MP_TAC THEN ASM_REWRITE_TAC[];
      REWRITE_TAC[esubset] THEN X_GEN_TAC `w:A` THEN STRIP_TAC THEN
      MATCH_MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `s:A`; `mx:A`;
        `x:A`; `w:A`] EUNION_MEM) THEN ASM_REWRITE_TAC[]];
    DISCH_THEN ACCEPT_TAC]);;

(* ==== F6.2 lemma s2b-1 : codom_form + HOLDS_CODOM ====
   Membership test  t IN Y_s  where Y_s = {al IN A1 : esubset s (ff al)}.
   Slots: v31 = A1, v32 = ff, v90 = s.  Parameter tv = the tested-element slot.
   Bound var 94 = p = ff(t).  Side condition ~(tv = 94) so the valmod (94|->a)
   does not shadow the tested slot.
     codom_form tv = (tv %% 31) && ?? 94 (apply_form 32 tv 94 &&
       subset_form 90 94)
   HOLDS: E (v tv)(v 31) /\ ?p. p IN D /\ eapply (v 32)(v tv) p /\
     esubset (v 90) p.
*)

let codom_form = new_definition
  `codom_form tv =
     (tv %% 31) && ?? 94 (apply_form 32 tv 94 && subset_form 90 94)`;;

let HOLDS_CODOM = prove
 (`!D (E:A->A->bool) v tv.
        model D E ZF_AX /\ valuation D v /\ ~(tv = 94)
        ==> (holds D E v (codom_form tv) <=>
             E (v tv) (v 31) /\
             ?p. p IN D /\ eapply D E (v 32) (v tv) p /\
               esubset D E (v 90) p)`,
  REPEAT STRIP_TAC THEN
  REWRITE_TAC[codom_form; HOLDS_AND; HOLDS_MEM; HOLDS_EX] THEN
  SUBGOAL_THEN
   `!a:A. a IN D
      ==> (holds D E ((94 |-> a) v) (apply_form 32 tv 94) /\
           holds D E ((94 |-> a) v) (subset_form 90 94) <=>
           eapply D E (v 32) (v tv) a /\ esubset D E (v 90) a)`
   (LABEL_TAC "pera") THENL
   [X_GEN_TAC `a:A` THEN DISCH_TAC THEN
    SUBGOAL_THEN `valuation D ((94 |-> (a:A)) v)` ASSUME_TAC THENL
     [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
    MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `(94 |-> (a:A)) v`;
      `32`; `tv:num`; `94`] HOLDS_APPLY_FORM) THEN
    ASM_REWRITE_TAC[] THEN DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    REWRITE_TAC[HOLDS_SUBSET_FORM] THEN
    REWRITE_TAC[VALMOD] THEN CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  AP_TERM_TAC THEN
  MATCH_MP_TAC(MESON[]
    `(!s:A. s IN D ==> (P s <=> Q s))
     ==> ((?s. s IN D /\ P s) <=> (?s. s IN D /\ Q s))`) THEN
  ASM_MESON_TAC[]);;

(* ==== F6.2 lemma s2b-2a : ufib_form + HOLDS_UFIB ====
   ufib_form = "?e. e injects a1 into Y_s", with the codomain test Y_s inlined
   as codom_form (NOT a slot).  Structurally = injex_form with the
     slot renaming
     5->91 (inj var e), 6->92 / 9->96 (domain args), 7->93 / 8->97 (images),
     0->30 (domain a1), and codomain test (7 %% 1) replaced by codom_form 93.
   HOLDS_UFIB mirrors HOLDS_INJEX_FORM: apply_form helpers a1/a2/a3 (= r1/r2/r3
   renamed) plus a new codom helper c1 folding holds(codom_form 93). *)

let ufib_form = new_definition
  `ufib_form =
     ?? 91 ((!! 92 (!! 93 (apply_form 91 92 93 -->
                           ((92 %% 30) && codom_form 93)))) &&
            ((!! 92 ((92 %% 30) -->
                     ?? 93 (codom_form 93 && apply_form 91 92 93))) &&
             ((!! 92 (!! 93 (!! 97 ((apply_form 91 92 93 &&
                                     apply_form 91 92 97) -->
                                    Eq 93 97)))) &&
              (!! 92 (!! 96 (!! 93 ((apply_form 91 92 93 &&
                                     apply_form 91 96 93) -->
                                    Eq 92 96)))))))`;;

let HOLDS_UFIB = prove
 (`!D (E:A->A->bool) v.
        model D E ZF_AX /\ valuation D v
        ==> (holds D E v ufib_form <=>
             ?e. e IN D /\
                 (!k. k IN D
                      ==> !t. t IN D
                              ==> eapply D E e k t
                                  ==> E k (v 30) /\
                                      (E t (v 31) /\
                                       ?p. p IN D /\ eapply D E (v 32) t p /\
                                           esubset D E (v 90) p)) /\
                 (!k. k IN D
                      ==> E k (v 30)
                          ==> ?t. t IN D /\
                                  (E t (v 31) /\
                                   ?p. p IN D /\ eapply D E (v 32) t p /\
                                       esubset D E (v 90) p) /\
                                  eapply D E e k t) /\
                 (!k. k IN D
                      ==> !t. t IN D
                              ==> !t'. t' IN D
                                       ==> eapply D E e k t /\
                                           eapply D E e k t'
                                           ==> t = t') /\
                 (!k. k IN D
                      ==> !k'. k' IN D
                               ==> !t. t IN D
                                       ==> eapply D E e k t /\
                                           eapply D E e k' t
                                           ==> k = k'))`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `!x. (v:num->A) x IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[valuation]; ALL_TAC] THEN
  (* a1 : apply_form 91 92 93 at the (93,92,91) tower *)
  SUBGOAL_THEN
   `!e k t:A. e IN D /\ k IN D /\ t IN D
      ==> (holds D E ((93 |-> t) ((92 |-> k) ((91 |-> e) v)))
             (apply_form 91 92 93) <=>
           eapply D (E:A->A->bool) e k t)`
  (LABEL_TAC "a1") THENL
   [REPEAT STRIP_TAC THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
      `(93 |-> (t:A)) ((92 |-> (k:A)) ((91 |-> (e:A)) v))`;
      `91`; `92`; `93`] HOLDS_APPLY_FORM) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[ARITH_EQ] THEN
      MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[] THEN
      MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[] THEN
      MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    REWRITE_TAC[VALMOD] THEN
    CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN REWRITE_TAC[];
    ALL_TAC] THEN
  (* a2 : two applies at the (97,93,92,91) tower *)
  SUBGOAL_THEN
   `!e k t t':A. e IN D /\ k IN D /\ t IN D /\ t' IN D
      ==> (holds D E ((97 |-> t') ((93 |-> t) ((92 |-> k)
             ((91 |-> e) v)))) (apply_form 91 92 93) <=>
           eapply D (E:A->A->bool) e k t) /\
          (holds D E ((97 |-> t') ((93 |-> t) ((92 |-> k)
             ((91 |-> e) v)))) (apply_form 91 92 97) <=>
           eapply D E e k t')`
  (LABEL_TAC "a2") THENL
   [REPEAT GEN_TAC THEN STRIP_TAC THEN CONJ_TAC THENL
     [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
        `(97 |-> (t':A)) ((93 |-> (t:A)) ((92 |-> (k:A))
           ((91 |-> (e:A)) v)))`; `91`; `92`; `93`] HOLDS_APPLY_FORM);
      MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
        `(97 |-> (t':A)) ((93 |-> (t:A)) ((92 |-> (k:A))
           ((91 |-> (e:A)) v)))`; `91`; `92`; `97`] HOLDS_APPLY_FORM)]
    THEN
    (ANTS_TAC THENL
      [ASM_REWRITE_TAC[ARITH_EQ] THEN
       MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[] THEN
       MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[] THEN
       MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[] THEN
       MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[];
       ALL_TAC] THEN
     DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
     REWRITE_TAC[VALMOD] THEN
     CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN
     REWRITE_TAC[]);
    ALL_TAC] THEN
  (* a3 : two applies at the (93,96,92,91) tower *)
  SUBGOAL_THEN
   `!e k k' t:A. e IN D /\ k IN D /\ k' IN D /\ t IN D
      ==> (holds D E ((93 |-> t) ((96 |-> k') ((92 |-> k)
             ((91 |-> e) v)))) (apply_form 91 92 93) <=>
           eapply D (E:A->A->bool) e k t) /\
          (holds D E ((93 |-> t) ((96 |-> k') ((92 |-> k)
             ((91 |-> e) v)))) (apply_form 91 96 93) <=>
           eapply D E e k' t)`
  (LABEL_TAC "a3") THENL
   [REPEAT GEN_TAC THEN STRIP_TAC THEN CONJ_TAC THENL
     [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
        `(93 |-> (t:A)) ((96 |-> (k':A)) ((92 |-> (k:A))
           ((91 |-> (e:A)) v)))`; `91`; `92`; `93`] HOLDS_APPLY_FORM);
      MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
        `(93 |-> (t:A)) ((96 |-> (k':A)) ((92 |-> (k:A))
           ((91 |-> (e:A)) v)))`; `91`; `96`; `93`] HOLDS_APPLY_FORM)]
    THEN
    (ANTS_TAC THENL
      [ASM_REWRITE_TAC[ARITH_EQ] THEN
       MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[] THEN
       MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[] THEN
       MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[] THEN
       MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[];
       ALL_TAC] THEN
     DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
     REWRITE_TAC[VALMOD] THEN
     CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN
     REWRITE_TAC[]);
    ALL_TAC] THEN
  (* c1 : codom_form 93 at the (93,92,91) tower *)
  SUBGOAL_THEN
   `!e k t:A. e IN D /\ k IN D /\ t IN D
      ==> (holds D E ((93 |-> t) ((92 |-> k) ((91 |-> e) v)))
             (codom_form 93) <=>
           E t (v 31) /\
           ?p. p IN D /\ eapply D (E:A->A->bool) (v 32) t p /\
               esubset D E (v 90) p)`
  (LABEL_TAC "c1") THENL
   [REPEAT STRIP_TAC THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
      `(93 |-> (t:A)) ((92 |-> (k:A)) ((91 |-> (e:A)) v))`; `93`]
      HOLDS_CODOM) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[ARITH_EQ] THEN
      MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[] THEN
      MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[] THEN
      MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    REWRITE_TAC[VALMOD] THEN
    CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN REWRITE_TAC[];
    ALL_TAC] THEN
  (* main assembly (mirrors HOLDS_INJEX_FORM) *)
  REWRITE_TAC[ufib_form; HOLDS_EX; HOLDS_AND; holds] THEN
  REWRITE_TAC[VALMOD] THEN
  CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN REWRITE_TAC[] THEN
  MATCH_MP_TAC(MESON[]
   `(!e:A. P e <=> Q e) ==> ((?e. P e) <=> (?e. Q e))`) THEN
  X_GEN_TAC `e:A` THEN
  MATCH_MP_TAC(TAUT
   `(a ==> (p <=> q)) ==> ((a /\ p) <=> (a /\ q))`) THEN
  DISCH_TAC THEN
  USE_THEN "a1" (fun th1 -> USE_THEN "a2" (fun th2 ->
    USE_THEN "a3" (fun th3 -> USE_THEN "c1" (fun th4 ->
      ASM_SIMP_TAC[th1; th2; th3; th4])))) THEN
  MATCH_MP_TAC(TAUT
   `(b <=> b')
    ==> ((a /\ b /\ c /\ d) <=> (a /\ b' /\ c /\ d))`) THEN
  MATCH_MP_TAC(MESON[]
     `(!k:A. P k <=> Q k) ==> ((!k:A. P k) <=> (!k:A. Q k))`) THEN
  X_GEN_TAC `k:A` THEN
  MATCH_MP_TAC(TAUT
   `(a ==> (p <=> q)) ==> ((a ==> p) <=> (a ==> q))`) THEN
  DISCH_TAC THEN
  MATCH_MP_TAC(TAUT
   `(a ==> (p <=> q)) ==> ((a ==> p) <=> (a ==> q))`) THEN
  DISCH_TAC THEN
  MATCH_MP_TAC(MESON[]
   `(!t:A. P t <=> Q t) ==> ((?t:A. P t) <=> (?t:A. Q t))`) THEN
  X_GEN_TAC `t:A` THEN
  MATCH_MP_TAC(TAUT
   `(a ==> (p <=> q)) ==> ((a /\ p) <=> (a /\ q))`) THEN
  DISCH_TAC THEN
  USE_THEN "a1" (fun th1 -> USE_THEN "c1" (fun th4 ->
    ASM_SIMP_TAC[th1; th4])));;

(* ==== F6.2 lemma s2b-2b : BRIDGE_UFIB ====
   Given the fiber set Yfib with membership characterization
     E t Yfib <=> codom(t)   (t IN D),
     codom(t) := t IN A1(=v31) and s(=v90) SUBSET ff(t),
   collapse the raw ufib clauses to the einj predicate:
     holds v ufib_form <=> ?e. einj e (v 30 = a1) Yfib.
   Mirrors HOLDS_INJEX_EINJ (REWRITE[einj; IMP_CONJ;
   RIGHT_IMP_FORALL_THM]); the
   codomain test codom is converted to E t Yfib via the membership
   characterization. *)

let BRIDGE_UFIB = prove
 (`!D (E:A->A->bool) v Yfib.
      model D E ZF_AX /\ valuation D v /\ Yfib IN D /\
      (!t. t IN D
           ==> (E t Yfib <=>
                E t (v 31) /\
                ?p. p IN D /\ eapply D E (v 32) t p /\ esubset D E (v 90) p))
      ==> (holds D E v ufib_form <=> ?e. einj D E e (v 30) Yfib)`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN
   `!t:A. t IN D ==> (E t Yfib <=>
          E t (v 31) /\
          ?p. p IN D /\ eapply D (E:A->A->bool) (v 32) t p /\
            esubset D E (v 90) p)`
   (LABEL_TAC "mc") THENL
   [GEN_TAC THEN DISCH_TAC THEN ASM_SIMP_TAC[]; ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `v:num->A`] HOLDS_UFIB) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  REWRITE_TAC[einj; IMP_CONJ; RIGHT_IMP_FORALL_THM] THEN
  ASM_SIMP_TAC[] THEN
  EQ_TAC THENL
   [MATCH_MP_TAC MONO_EXISTS THEN X_GEN_TAC `e:A` THEN
    STRIP_TAC THEN ASM_REWRITE_TAC[] THEN
    X_GEN_TAC `k:A` THEN DISCH_TAC THEN DISCH_TAC THEN
    FIRST_ASSUM(MP_TAC o SPEC `k:A` o check (fun th ->
       length(fst(strip_forall(concl th))) = 1 &&
         free_in `e:A` (concl th))) THEN
    ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN(X_CHOOSE_THEN `t:A` STRIP_ASSUME_TAC) THEN
    EXISTS_TAC `t:A` THEN ASM_REWRITE_TAC[] THEN
    USE_THEN "mc"
      (fun th -> MP_TAC(MP (SPEC `t:A` th) (ASSUME `(t:A) IN D`))) THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN ASM_REWRITE_TAC[] THEN
    EXISTS_TAC `p:A` THEN ASM_REWRITE_TAC[];
    MATCH_MP_TAC MONO_EXISTS THEN X_GEN_TAC `e:A` THEN
    STRIP_TAC THEN ASM_REWRITE_TAC[] THEN
    X_GEN_TAC `k:A` THEN DISCH_TAC THEN DISCH_TAC THEN
    FIRST_ASSUM(MP_TAC o SPEC `k:A` o check (fun th ->
       length(fst(strip_forall(concl th))) = 1 &&
         free_in `e:A` (concl th))) THEN
    ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN(X_CHOOSE_THEN `t:A` STRIP_ASSUME_TAC) THEN
    EXISTS_TAC `t:A` THEN ASM_REWRITE_TAC[] THEN
    USE_THEN "mc"
      (fun th -> MP_TAC(EQ_MP (MP (SPEC `t:A` th) (ASSUME `(t:A) IN D`))
                        (ASSUME `(E:A->A->bool) t Yfib`))) THEN
    DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC
      (X_CHOOSE_THEN `p:A` STRIP_ASSUME_TAC)) THEN
    ASM_REWRITE_TAC[] THEN EXISTS_TAC `p:A` THEN ASM_REWRITE_TAC[]]);;

(* ==== F6.2 lemma s2b-3 : psi_form + HOLDS_PSI ====
   The K-separation predicate.  Free var slot 35 = k (size).  Bound 90 = s.
     psi_form = ?? 90 (bijform 35 90 && subset_form 90 33 && ufib_form)
   "?s. |s| = k /\ s SUBSET ii(=v33) /\ phi(s)", phi(s) kept raw as
   holds ((90|->s)v) ufib_form (BRIDGE_UFIB converts it per-witness later).
   NB bijform 35 90 uses internal vars 91..95 and subset_form 90 33 uses 91,
   both bound in disjoint scopes from ufib_form's 91..97 -- holds is
   compositional so there is no capture; FV(psi_form) = {30,31,32,33,35}. *)

let psi_form = new_definition
  `psi_form =
     ?? 90 (bijform 35 90 && subset_form 90 33 && ufib_form)`;;

let HOLDS_PSI = prove
 (`!D (E:A->A->bool) v.
        model D E ZF_AX /\ valuation D v
        ==> (holds D E v psi_form <=>
             ?s. s IN D /\
                 (?f. ebij D E f (v 35) s) /\
                 esubset D E s (v 33) /\
                 holds D E ((90 |-> s) v) ufib_form)`,
  REPEAT STRIP_TAC THEN
  REWRITE_TAC[psi_form; HOLDS_EX] THEN
  MATCH_MP_TAC(MESON[]
    `(!s:A. s IN D ==> (P s <=> Q s))
     ==> ((?s. s IN D /\ P s) <=> (?s. s IN D /\ Q s))`) THEN
  X_GEN_TAC `s:A` THEN DISCH_TAC THEN
  SUBGOAL_THEN `valuation D ((90 |-> (s:A)) v)` ASSUME_TAC THENL
   [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
  REWRITE_TAC[HOLDS_AND] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `(90 |-> (s:A)) v`; `35`; `90`]
    HOLDS_BIJFORM_EBIJ) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  REWRITE_TAC[HOLDS_SUBSET_FORM] THEN
  REWRITE_TAC[VALMOD] THEN
  CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN REWRITE_TAC[]);;

(* ==== F6.2 lemma s2b-4 : EROOT_SIZESET ====
   K = { z IN rng : psi(z) }  via ZF_SEPARATION on slot 35 (the size var).
   ZF_SEPARATION is fully general (freshness handled internally by
   VARIANTS_EXIST), so NO FV side-condition on psi_form is needed.
   Memberchar keeps the ufib clause RAW (holds
     ((90|->s)((35|->z)v)) ufib_form);
   BRIDGE_UFIB converts it per-witness (at z=k0 / z=0) downstream in s2b-5/6.
   Reads slots v33 = ii;
   the ufib clause silently reads v30=a1,v31=A1,v32=ff. *)

let EROOT_SIZESET = prove
 (`!D (E:A->A->bool) v rng.
        model D E ZF_AX /\ valuation D v /\ rng IN D
        ==> ?K. K IN D /\
                (!z. z IN D
                     ==> (E z K <=>
                          E z rng /\
                          ?s. s IN D /\ (?f. ebij D E f z s) /\
                              esubset D E s (v 33) /\
                              holds D E ((90 |-> s) ((35 |-> z) v))
                                ufib_form))`,
  REPEAT STRIP_TAC THEN
  MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`] ZF_SEPARATION) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(MP_TAC o ISPECL [`psi_form`; `35`; `v:num->A`; `rng:A`]) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `K:A`
    (CONJUNCTS_THEN2 (LABEL_TAC "KD") (LABEL_TAC "sep"))) THEN
  EXISTS_TAC `K:A` THEN CONJ_TAC THENL
   [USE_THEN "KD" ACCEPT_TAC; ALL_TAC] THEN
  X_GEN_TAC `z:A` THEN DISCH_TAC THEN
  USE_THEN "sep" (MP_TAC o SPEC `z:A`) THEN
  ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  MATCH_MP_TAC(TAUT `(p <=> q) ==> ((a /\ p) <=> (a /\ q))`) THEN
  SUBGOAL_THEN `valuation D ((35 |-> (z:A)) v)` ASSUME_TAC THENL
   [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `(35 |-> (z:A)) v`]
         HOLDS_PSI) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  REWRITE_TAC[VALMOD] THEN
  CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN REWRITE_TAC[]);;

(* ==== F6.2 lemma s2b-5a : subfib_form + HOLDS_SUBFIB +
  EFIBER_MATERIALIZE ====
   Materialize the fiber  Y_s = { al IN A1(=v31) : s SUBSET ff(al) }
     as a set in D,
   with a clean memberchar (no duplicated membership test).  Reusable for
   s=eempty (Y=A1, the 0-in-K case) and s=r (A2, the root output) and s=r+{x}
   (maximality).  subfib_form is codom_form MINUS the leading
     (tv%%31) membership
   test, so separating (v31) by it yields  E t(v31) /\
     ?p. p=ff(t) /\ s SUBSET p
   with no  A /\ A /\
     B  redundancy.  Separation var slot = 96 (fresh vs 32,90,94). *)

let subfib_form = new_definition
  `subfib_form tv = ?? 94 (apply_form 32 tv 94 && subset_form 90 94)`;;

let HOLDS_SUBFIB = prove
 (`!D (E:A->A->bool) v tv.
        model D E ZF_AX /\ valuation D v /\ ~(tv = 94)
        ==> (holds D E v (subfib_form tv) <=>
             ?p. p IN D /\ eapply D E (v 32) (v tv) p /\
               esubset D E (v 90) p)`,
  REPEAT STRIP_TAC THEN
  REWRITE_TAC[subfib_form; HOLDS_EX] THEN
  MATCH_MP_TAC(MESON[]
    `(!a:A. a IN D ==> (P a <=> Q a))
     ==> ((?a. a IN D /\ P a) <=> (?a. a IN D /\ Q a))`) THEN
  X_GEN_TAC `a:A` THEN DISCH_TAC THEN
  SUBGOAL_THEN `valuation D ((94 |-> (a:A)) v)` ASSUME_TAC THENL
   [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
  REWRITE_TAC[HOLDS_AND] THEN
  MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `(94 |-> (a:A)) v`;
    `32`; `tv:num`; `94`] HOLDS_APPLY_FORM) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  REWRITE_TAC[HOLDS_SUBSET_FORM] THEN
  REWRITE_TAC[VALMOD] THEN CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN
  ASM_REWRITE_TAC[]);;

let EFIBER_MATERIALIZE = prove
 (`!D (E:A->A->bool) v s.
        model D E ZF_AX /\ valuation D v /\ s IN D
        ==> ?Y. Y IN D /\
                (!t. t IN D
                     ==> (E t Y <=>
                          E t (v 31) /\
                          ?p. p IN D /\ eapply D E (v 32) t p /\
                            esubset D E s p))`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `valuation D ((90 |-> (s:A)) v)` (LABEL_TAC "vw") THENL
   [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
  MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`] ZF_SEPARATION) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(MP_TAC o ISPECL
    [`subfib_form 96`; `96`; `(90 |-> (s:A)) v`; `(v:num->A) 31`]) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[valuation]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `Y:A`
    (CONJUNCTS_THEN2 (LABEL_TAC "YD") (LABEL_TAC "sep"))) THEN
  EXISTS_TAC `Y:A` THEN CONJ_TAC THENL
   [USE_THEN "YD" ACCEPT_TAC; ALL_TAC] THEN
  X_GEN_TAC `t:A` THEN DISCH_TAC THEN
  USE_THEN "sep" (MP_TAC o SPEC `t:A`) THEN
  ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  MATCH_MP_TAC(TAUT `(p <=> q) ==> ((a /\ p) <=> (a /\ q))`) THEN
  SUBGOAL_THEN `valuation D ((96 |-> (t:A)) ((90 |-> (s:A)) v))`
    ASSUME_TAC THENL [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
    `(96 |-> (t:A)) ((90 |-> (s:A)) v)`; `96`] HOLDS_SUBFIB) THEN
  ANTS_TAC THENL
  [ASM_REWRITE_TAC[] THEN CONV_TAC NUM_REDUCE_CONV; ALL_TAC] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  REWRITE_TAC[VALMOD] THEN CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN
  REWRITE_TAC[]);;

(* ============================================================
   F6.2 batch s2b-6a/5b0/5b : SIZELE + EROOT_SIZESET_PHI + EROOT_EXISTS
   (finite-size monotonicity; raw-ufib->phi K-memberchar; the
   achieved-size Delta-system root r with existence + maximality).
   ============================================================ *)

let SIZELE = prove
 (`!D (E:A->A->bool) om s t m n g h.
      model D E ZF_AX /\ eomega D E om /\
      m IN D /\ n IN D /\ t IN D /\ E m om /\ E n om /\
      ebij D E g m s /\ ebij D E h n t /\
      (!k. k IN D /\ E k s ==> E k t)
      ==> E m n \/ m = n`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `eordinal D (E:A->A->bool) m /\ eordinal D (E:A->A->bool) n`
    STRIP_ASSUME_TAC THENL [ASM_MESON_TAC[EOMEGA_ORDINALS]; ALL_TAC] THEN
  SUBGOAL_THEN `einj D (E:A->A->bool) g m s` (LABEL_TAC "gms") THENL
   [ASM_MESON_TAC[EBIJ_EINJ]; ALL_TAC] THEN
  SUBGOAL_THEN `einj D (E:A->A->bool) g m t` (LABEL_TAC "gmt") THENL
   [MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `g:A`; `m:A`; `s:A`; `t:A`]
      EINJ_WEAKEN) THEN
    ANTS_TAC THENL
     [CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; DISCH_THEN ACCEPT_TAC];
    ALL_TAC] THEN
  SUBGOAL_THEN `?hh:A. ebij D (E:A->A->bool) hh t n`
    (X_CHOOSE_TAC `hh:A`) THENL
   [ASM_MESON_TAC[EBIJ_SYM]; ALL_TAC] THEN
  SUBGOAL_THEN `einj D (E:A->A->bool) hh t n` (LABEL_TAC "htn") THENL
   [ASM_MESON_TAC[EBIJ_EINJ]; ALL_TAC] THEN
  SUBGOAL_THEN `?hc:A. einj D (E:A->A->bool) hc m n`
    (X_CHOOSE_TAC `hc:A`) THENL
   [MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `g:A`; `hh:A`; `m:A`; `t:A`;
      `n:A`] EINJ_COMPOSE) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC];
    ALL_TAC] THEN
  MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `m:A`; `n:A`]
    EORDINAL_TRICHOTOMY) THEN
  ASM_REWRITE_TAC[] THEN STRIP_TAC THENL
   [ASM_REWRITE_TAC[]; ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `om:A`; `m:A`; `n:A`]
    EINJ_PIGEONHOLE) THEN
  ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[]);;

let EROOT_SIZESET_PHI = prove
 (`!D (E:A->A->bool) a1 A1 ff ii rng v K.
     model D E ZF_AX /\ valuation D v /\
     v 30 = a1 /\ v 31 = A1 /\ v 32 = ff /\ v 33 = ii /\ K IN D /\
     (!z. z IN D
          ==> (E z K <=>
               E z rng /\
               ?s. s IN D /\ (?f. ebij D E f z s) /\ esubset D E s ii /\
                   holds D E ((90 |-> s) ((35 |-> z) v)) ufib_form))
     ==> (!z. z IN D
              ==> (E z K <=>
                   E z rng /\
                   ?s. s IN D /\ (?f. ebij D E f z s) /\ esubset D E s ii /\
                       ?Ys. Ys IN D /\
                            (!t. t IN D
                                 ==> (E t Ys <=>
                                      E t A1 /\
                                      ?p. p IN D /\ eapply D E ff t p /\
                                          esubset D E s p)) /\
                            (?e. einj D E e a1 Ys)))`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN X_GEN_TAC `z:A` THEN DISCH_TAC THEN
  FIRST_X_ASSUM(fun th -> MP_TAC(SPEC `z:A` th)) THEN
  ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  MATCH_MP_TAC(TAUT `(p <=> q) ==> ((a /\ p) <=> (a /\ q))`) THEN
  MATCH_MP_TAC(MESON[]
    `(!s:A. s IN D ==> (U s <=> P s))
     ==> ((?s. s IN D /\ U s) <=> (?s. s IN D /\ P s))`) THEN
  X_GEN_TAC `s:A` THEN DISCH_TAC THEN
  MATCH_MP_TAC(TAUT `(p <=> q) ==> ((a /\ b /\ p) <=> (a /\ b /\ q))`) THEN
  SUBGOAL_THEN `valuation D ((35 |-> (z:A)) v)` (LABEL_TAC "wv") THENL
   [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
  SUBGOAL_THEN `valuation D ((90 |-> (s:A)) ((35 |-> (z:A)) v))`
    (LABEL_TAC "valv") THENL [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
  SUBGOAL_THEN `((35 |-> (z:A)) v) 31 = A1` (LABEL_TAC "w31") THENL
   [REWRITE_TAC[VALMOD] THEN CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `((35 |-> (z:A)) v) 32 = ff` (LABEL_TAC "w32") THENL
   [REWRITE_TAC[VALMOD] THEN CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `((90 |-> (s:A)) ((35 |-> (z:A)) v)) 30 = a1` (LABEL_TAC "v30")
  THENL
   [REWRITE_TAC[VALMOD] THEN CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `((90 |-> (s:A)) ((35 |-> (z:A)) v)) 31 = A1` (LABEL_TAC "v31")
  THENL
   [REWRITE_TAC[VALMOD] THEN CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `((90 |-> (s:A)) ((35 |-> (z:A)) v)) 32 = ff` (LABEL_TAC "v32")
  THENL
   [REWRITE_TAC[VALMOD] THEN CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `((90 |-> (s:A)) ((35 |-> (z:A)) v)) 90 = s` (LABEL_TAC "v90")
  THENL
   [REWRITE_TAC[VALMOD] THEN CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN
    REWRITE_TAC[]; ALL_TAC] THEN
  MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `(35 |-> (z:A)) v`; `s:A`]
    EFIBER_MATERIALIZE) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `Ys0:A`
    (CONJUNCTS_THEN2 (LABEL_TAC "Ys0D") (LABEL_TAC "Ys0mc"))) THEN
  (* br0 : bridge for Ys0 -- (val 30) rewritten to a1 *)
  SUBGOAL_THEN
   `holds D E ((90 |-> (s:A)) ((35 |-> (z:A)) v)) ufib_form <=>
    ?e. einj D (E:A->A->bool) e a1 Ys0` (LABEL_TAC "br0") THENL
   [MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`;
      `(90 |-> (s:A)) ((35 |-> (z:A)) v)`; `Ys0:A`] BRIDGE_UFIB) THEN
    ANTS_TAC THENL
     [REPEAT CONJ_TAC THENL
