      ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[]]]);;

let EROOT_EXISTS = prove
 (`!D (E:A->A->bool) om a1 ff ii n0 A1.
     model D E ZF_AX /\ (!u. u IN D ==> elmem D E u) /\
     eomega D E om /\
     a1 IN D /\ ecardinal D E a1 /\ E om a1 /\
     (!c'. c' IN D /\ E c' a1 ==> ~(ecardinal D E c' /\ E om c')) /\
     ff IN D /\
     (!n z z'. n IN D /\ z IN D /\ z' IN D /\
               eapply D E ff n z /\ eapply D E ff n z' ==> z = z') /\
     ii IN D /\ n0 IN D /\ E n0 om /\
     A1 IN D /\ esubset D E A1 a1 /\ ~(?e. einj D E e A1 om) /\
     (!al. al IN D /\ E al A1
           ==> ?d. d IN D /\ eapply D E ff al d /\ esubset D E d ii /\
                   ?f. ebij D E f n0 d)
     ==> ?r A2. r IN D /\ A2 IN D /\ efin D E r /\ esubset D E r ii /\
                (!t. t IN D
                     ==> (E t A2 <=>
                          E t A1 /\ ?p. p IN D /\ eapply D E ff t p /\
                                        esubset D E r p)) /\
                (?e. einj D E e a1 A2) /\
                (!x q Yq. x IN D /\ E x ii /\ ~(E x r) /\ eadjoin D E r x q /\
                          Yq IN D /\
                          (!t. t IN D
                               ==> (E t Yq <=>
                                    E t A1 /\ ?p. p IN D /\
                                      eapply D E ff t p /\
                                                  esubset D E q p))
                          ==> ?e. einj D E e Yq om)`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `(om:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[EOMEGA_IN]; ALL_TAC] THEN
  (* A: fixed-slot valuation vv, emp, sn = esuc n0, empty IN sn *)
  SUBGOAL_THEN
   `?vv:num->A. valuation D vv /\
                vv 30 = a1 /\ vv 31 = A1 /\ vv 32 = ff /\ vv 33 = ii`
   STRIP_ASSUME_TAC THENL
   [EXISTS_TAC `(30 |-> (a1:A))((31 |-> (A1:A))((32 |-> (ff:A))
                ((33 |-> (ii:A))(\n:num. a1:A))))` THEN
    REPEAT CONJ_TAC THENL
     [REWRITE_TAC[valuation] THEN GEN_TAC THEN REWRITE_TAC[VALMOD] THEN
      REPEAT(COND_CASES_TAC THEN ASM_REWRITE_TAC[]) THEN ASM_REWRITE_TAC[];
      REWRITE_TAC[VALMOD] THEN CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN
      REWRITE_TAC[];
      REWRITE_TAC[VALMOD] THEN CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN
      REWRITE_TAC[];
      REWRITE_TAC[VALMOD] THEN CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN
      REWRITE_TAC[];
      REWRITE_TAC[VALMOD] THEN CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN
      REWRITE_TAC[]];
    ALL_TAC] THEN
  SUBGOAL_THEN `?emp:A. eempty D (E:A->A->bool) emp`
    (X_CHOOSE_TAC `emp:A`) THENL
   [ASM_MESON_TAC[EEMPTY_EXISTS]; ALL_TAC] THEN
  SUBGOAL_THEN `?sn:A. esuc D (E:A->A->bool) n0 sn` (X_CHOOSE_TAC `sn:A`) THENL
   [ASM_MESON_TAC[ESUC_EXISTS]; ALL_TAC] THEN
