(* ============================================================
   F6.2 lemma s1d-core : EUNIFORM_FIBER
   (EDELTA premise -> uniform-size uncountable fibre = EROOT hyp).
   ============================================================ *)

let EUNIFORM_FIBER = prove
 (`!D (E:A->A->bool) om ii a1 ff.
     model D E ZF_AX /\ (!u. u IN D ==> elmem D E u) /\
     eomega D E om /\
     a1 IN D /\ ecardinal D E a1 /\ E om a1 /\
     ff IN D /\
     (!n z z'. n IN D /\ z IN D /\ z' IN D /\
               eapply D E ff n z /\ eapply D E ff n z' ==> z = z') /\
     ii IN D /\
     (!b. b IN D /\ E b a1
          ==> ?d. d IN D /\ eapply D E ff b d /\ efin D E d /\
            esubset D E d ii)
     ==> ?n0 A1. n0 IN D /\ E n0 om /\ A1 IN D /\ esubset D E A1 a1 /\
                 ~(?e. einj D E e A1 om) /\
                 (!t. t IN D
                      ==> (E t A1 <=>
                           E t a1 /\ ?p. p IN D /\ eapply D E ff t p /\
                                         ?f. ebij D E f n0 p)) /\
                 (!al. al IN D /\ E al A1
                       ==> ?d. d IN D /\ eapply D E ff al d /\
                               esubset D E d ii /\ ?f. ebij D E f n0 d)`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `(om:A) IN D` ASSUME_TAC THENL
   [FIRST_ASSUM(ACCEPT_TAC o MATCH_MP EOMEGA_IN) ORELSE
    ASM_MESON_TAC[EOMEGA_IN]; ALL_TAC] THEN
  FIRST_ASSUM(LABEL_TAC "ffsv" o check (fun th ->
     length(fst(strip_forall(concl th))) = 3)) THEN
  SUBGOAL_THEN
   `?vff:num->A. valuation D vff /\ vff 12 = ff /\ vff 13 = om`
   STRIP_ASSUME_TAC THENL
   [EXISTS_TAC `(12 |-> (ff:A))((13 |-> (om:A))(\n:num. ff:A))` THEN
    REPEAT CONJ_TAC THENL
     [REWRITE_TAC[valuation] THEN GEN_TAC THEN REWRITE_TAC[VALMOD] THEN
      REPEAT(COND_CASES_TAC THEN ASM_REWRITE_TAC[]);
      REWRITE_TAC[VALMOD] THEN CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN
      REWRITE_TAC[];
      REWRITE_TAC[VALMOD] THEN CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN
      REWRITE_TAC[]];
    ALL_TAC] THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`vff:num->A`;`a1:A`]
         ESIZE_FAMILY) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[];
    INTRO_TAC "@sz. szD szsv szgraph szper"] THEN
  RULE_ASSUM_TAC(REWRITE_RULE[ASSUME `(vff:num->A) 12 = ff`;
                             ASSUME `(vff:num->A) 13 = om`]) THEN
  SUBGOAL_THEN
   `!m. m IN D /\ E m a1 ==> ?n. n IN D /\ E n om /\
    eapply D (E:A->A->bool) sz m n`
   (LABEL_TAC "sztot") THENL
   [X_GEN_TAC `m:A` THEN STRIP_TAC THEN
    USE_THEN "szper" (fun th -> MP_TAC(SPEC `m:A` th)) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    STRIP_TAC THEN EXISTS_TAC `N:A` THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `~(?e:A. einj D (E:A->A->bool) e a1 om)`
    (LABEL_TAC "a1unc") THENL
   [MATCH_MP_TAC EUNCOUNTABLE_CARD THEN ASM_MESON_TAC[]; ALL_TAC] THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`om:A`;`sz:A`;`a1:A`]
     EUNCOUNTABLE_FIBER_RAW) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[];
    INTRO_TAC "@n0 A1. n0D n0om A1D A1mc A1unc"] THEN
  SUBGOAL_THEN
    `!t. t IN D ==> ((E:A->A->bool) t A1 <=>
          E t a1 /\ ?p. p IN D /\ eapply D E ff t p /\ ?f. ebij D E f n0 p)`
    (LABEL_TAC "A1ff") THENL
   [X_GEN_TAC `t:A` THEN DISCH_TAC THEN
    USE_THEN "A1mc"
      (fun th -> ASSUME_TAC(MATCH_MP th (ASSUME `(t:A) IN D`))) THEN
      ASM_REWRITE_TAC[] THEN
    MATCH_MP_TAC(TAUT `(a ==> (b <=> c)) ==> ((a /\ b) <=> (a /\ c))`) THEN
    DISCH_TAC THEN
    USE_THEN "szper" (fun th -> MP_TAC(SPEC `t:A` th)) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    INTRO_TAC "@pp NN. ppD NND ffpp NNom (@gN. gNbij) szNN" THEN
    EQ_TAC THENL
     [DISCH_TAC THEN
      SUBGOAL_THEN `NN:A = n0` SUBST_ALL_TAC THENL
       [USE_THEN "szsv"
        (fun th -> MP_TAC(ISPECL [`t:A`;`NN:A`;`n0:A`] th)) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC];
        ALL_TAC] THEN
      EXISTS_TAC `pp:A` THEN ASM_REWRITE_TAC[] THEN
      EXISTS_TAC `gN:A` THEN USE_THEN "gNbij" ACCEPT_TAC;
      DISCH_THEN(X_CHOOSE_THEN `pb:A` (CONJUNCTS_THEN2 (LABEL_TAC "pbD")
        (CONJUNCTS_THEN2 (LABEL_TAC "ffpb")
          (X_CHOOSE_THEN `gb:A` (LABEL_TAC "gbbij"))))) THEN
      SUBGOAL_THEN `(pb:A) = pp` SUBST_ALL_TAC THENL
       [USE_THEN "ffsv"
        (fun th -> MP_TAC(ISPECL [`t:A`;`pb:A`;`pp:A`] th)) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC];
        ALL_TAC] THEN
      SUBGOAL_THEN `n0:A = NN` SUBST_ALL_TAC THENL
       [MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`om:A`;`n0:A`;`NN:A`;`pp:A`;
                       `gb:A`;`gN:A`] ENAT_CARD_UNIQUE) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC];
        ALL_TAC] THEN
      USE_THEN "szNN" ACCEPT_TAC];
    ALL_TAC] THEN
  SUBGOAL_THEN `esubset D (E:A->A->bool) A1 a1` (LABEL_TAC "A1sub") THENL
   [REWRITE_TAC[esubset] THEN X_GEN_TAC `w:A` THEN STRIP_TAC THEN
    USE_THEN "A1mc" (fun th ->
      ASSUME_TAC(MATCH_MP th (ASSUME `(w:A) IN D`))) THEN
    ASM_MESON_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN
   `!al. al IN D /\ (E:A->A->bool) al A1
         ==> ?d. d IN D /\ eapply D E ff al d /\
                 esubset D E d ii /\ ?f. ebij D E f n0 d`
   (LABEL_TAC "unifsz") THENL
   [X_GEN_TAC `al:A` THEN STRIP_TAC THEN
    USE_THEN "A1ff" (fun th ->
      MP_TAC(EQ_MP (MATCH_MP th (ASSUME `(al:A) IN D`))
                   (ASSUME `(E:A->A->bool) al A1`))) THEN
    INTRO_TAC "alA1a @p. pD ffalp @fw. fwbij" THEN
    SUBGOAL_THEN `?d:A. d IN D /\ eapply D E ff al d /\ efin D E d /\
                        esubset D E d ii`
      (X_CHOOSE_THEN `dd:A` STRIP_ASSUME_TAC) THENL
     [FIRST_X_ASSUM MATCH_MP_TAC THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN `(dd:A) = p` SUBST_ALL_TAC THENL
     [USE_THEN "ffsv" (fun th -> MP_TAC(ISPECL [`al:A`;`dd:A`;`p:A`] th)) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC]; ALL_TAC] THEN
    EXISTS_TAC `p:A` THEN ASM_REWRITE_TAC[] THEN
    EXISTS_TAC `fw:A` THEN USE_THEN "fwbij" ACCEPT_TAC;
    ALL_TAC] THEN
  MAP_EVERY EXISTS_TAC [`n0:A`;`A1:A`] THEN
  REPEAT CONJ_TAC THENL
   [USE_THEN "n0D" ACCEPT_TAC;
    USE_THEN "n0om" ACCEPT_TAC;
    USE_THEN "A1D" ACCEPT_TAC;
    USE_THEN "A1sub" ACCEPT_TAC;
    USE_THEN "A1unc" ACCEPT_TAC;
    USE_THEN "A1ff" ACCEPT_TAC;
    USE_THEN "unifsz" ACCEPT_TAC]);;

(* ============================================================
   F6.2 lemma s1d/s2 glue : EDELTA_ROOT
   (EUNIFORM_FIBER + EROOT_EXISTS, repackaged over A2; the whole
   s1+s2 half of F6.2 -- root r + uncountable A2 + x-fibre countability).
   ============================================================ *)

let EDELTA_ROOT = prove
 (`!D (E:A->A->bool) om ii a1 ff.
     model D E ZF_AX /\ (!u. u IN D ==> elmem D E u) /\
     eomega D E om /\
     a1 IN D /\ ecardinal D E a1 /\ E om a1 /\
     (!c'. c' IN D /\ E c' a1 ==> ~(ecardinal D E c' /\ E om c')) /\
     ff IN D /\
     (!n z z'. n IN D /\ z IN D /\ z' IN D /\
               eapply D E ff n z /\ eapply D E ff n z' ==> z = z') /\
     ii IN D /\
     (!b. b IN D /\ E b a1
          ==> ?d. d IN D /\ eapply D E ff b d /\ efin D E d /\
            esubset D E d ii)
     ==> ?r A2. r IN D /\ A2 IN D /\ efin D E r /\ esubset D E r ii /\
                esubset D E A2 a1 /\
                ~(?e. einj D E e A2 om) /\
                (!al. al IN D /\ E al A2
                      ==> ?d. d IN D /\ eapply D E ff al d /\
                        esubset D E r d) /\
                (!x Y. x IN D /\ E x ii /\ ~(E x r) /\ Y IN D /\
                       (!al. al IN D
                             ==> (E al Y <=>
                                  E al A2 /\ ?d. d IN D /\
                                    eapply D E ff al d /\
                                                 E x d))
                       ==> ?e. einj D E e Y om)`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  FIRST_ASSUM(LABEL_TAC "ffsv" o check (fun th ->
     length(fst(strip_forall(concl th))) = 3)) THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`om:A`;`ii:A`;`a1:A`;`ff:A`]
     EUNIFORM_FIBER) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[] THEN REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
    INTRO_TAC "@n0 A1. n0D n0om A1D A1sub A1unc A1ff unifsz"] THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`om:A`;`a1:A`;`ff:A`;
     `ii:A`;`n0:A`;`A1:A`] EROOT_EXISTS) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[] THEN REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
    INTRO_TAC "@r A2. rD A2D rfin rii A2mc A2inj R3"] THEN
  (* R4: A2 SUBSET a1 *)
  SUBGOAL_THEN `esubset D (E:A->A->bool) A2 a1` (LABEL_TAC "A2sub") THENL
   [REWRITE_TAC[esubset] THEN X_GEN_TAC `al:A` THEN STRIP_TAC THEN
    USE_THEN "A2mc"
      (fun th -> ASSUME_TAC(MATCH_MP th (ASSUME `(al:A) IN D`))) THEN
      ASM_MESON_TAC[esubset]; ALL_TAC] THEN
  (* R5: A2 uncountable *)
  SUBGOAL_THEN `~(?e:A. einj D (E:A->A->bool) e A2 om)`
    (LABEL_TAC "A2unc") THENL
   [SUBGOAL_THEN `~(?e:A. einj D (E:A->A->bool) e a1 om)`
    (LABEL_TAC "a1unc") THENL
    [MATCH_MP_TAC EUNCOUNTABLE_CARD THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN
      `(?e:A. einj D E e A2 om) ==> (?e:A. einj D (E:A->A->bool) e a1 om)`
      (fun th -> ASM_MESON_TAC[th]) THEN
    DISCH_THEN(X_CHOOSE_TAC `g:A`) THEN
    USE_THEN "A2inj" (X_CHOOSE_TAC `e0:A`) THEN
    MP_TAC(ISPECL
           [`D:A->bool`;`E:A->A->bool`;`e0:A`;`g:A`;`a1:A`;`A2:A`;`om:A`]
           EINJ_COMPOSE) THEN
    ANTS_TAC THENL
    [ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[EOMEGA_IN]; ALL_TAC] THEN
    STRIP_TAC THEN ASM_MESON_TAC[];
    ALL_TAC] THEN
  (* R6: petals contain root *)
  SUBGOAL_THEN
   `!al. al IN D /\ E al A2
         ==> ?d. d IN D /\ eapply D E ff al d /\ esubset D (E:A->A->bool) r d`
   (LABEL_TAC "petal") THENL
   [X_GEN_TAC `al:A` THEN STRIP_TAC THEN
    USE_THEN "A2mc" (fun th ->
      MP_TAC(EQ_MP (MATCH_MP th (ASSUME `(al:A) IN D`))
                   (ASSUME `(E:A->A->bool) al A2`))) THEN
    DISCH_THEN(fun th -> MP_TAC(CONJUNCT2 th)) THEN
    STRIP_TAC THEN EXISTS_TAC `p:A` THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* R7: maximality restated over A2 *)
  SUBGOAL_THEN
   `!x Y. x IN D /\ E x ii /\ ~((E:A->A->bool) x r) /\ Y IN D /\
          (!al. al IN D
                ==> (E al Y <=>
                     E al A2 /\ ?d. d IN D /\ eapply D E ff al d /\ E x d))
          ==> ?e. einj D E e Y om`
   (LABEL_TAC "R3rest") THENL
   [MAP_EVERY X_GEN_TAC [`x:A`;`Y:A`] THEN
    INTRO_TAC "xD xii xnr YD Ymc" THEN
    SUBGOAL_THEN `?q:A. eadjoin D (E:A->A->bool) r x q`
      (X_CHOOSE_TAC `q:A`) THENL
      [ASM_MESON_TAC[EADJOIN_EXISTS]; ALL_TAC] THEN
    SUBGOAL_THEN `!w:A. w IN D ==> ((E:A->A->bool) w q <=> E w r \/ w = x)`
      (LABEL_TAC "qmem") THENL
     [MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`r:A`;`x:A`;`q:A`]
             EADJOIN_MEM) THEN
      ASM_REWRITE_TAC[] THEN MESON_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN
      `!al. al IN D
            ==> (E al Y <=>
                 E al A1 /\ ?p. p IN D /\ eapply D E ff al p /\
                                esubset D (E:A->A->bool) q p)`
      (LABEL_TAC "Yqmc") THENL
     [X_GEN_TAC `al:A` THEN DISCH_TAC THEN
      USE_THEN "Ymc" (fun th ->
        ASSUME_TAC(MATCH_MP th (ASSUME `(al:A) IN D`))) THEN
      USE_THEN "A2mc" (fun th ->
        ASSUME_TAC(MATCH_MP th (ASSUME `(al:A) IN D`))) THEN
      ASM_REWRITE_TAC[] THEN EQ_TAC THENL
       [STRIP_TAC THEN
        SUBGOAL_THEN `(p:A) = d` SUBST_ALL_TAC THENL
         [USE_THEN "ffsv"
          (fun th -> MP_TAC(ISPECL [`al:A`;`p:A`;`d:A`] th)) THEN
          ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC];
          ALL_TAC] THEN
        CONJ_TAC THENL
         [FIRST_ASSUM ACCEPT_TAC;
          EXISTS_TAC `d:A` THEN ASM_REWRITE_TAC[] THEN
          REWRITE_TAC[esubset] THEN X_GEN_TAC `w:A` THEN STRIP_TAC THEN
          USE_THEN "qmem" (fun th ->
            ASSUME_TAC(MATCH_MP th (ASSUME `(w:A) IN D`))) THEN
          ASM_MESON_TAC[esubset]];
        STRIP_TAC THEN
        SUBGOAL_THEN `esubset D (E:A->A->bool) r p` ASSUME_TAC THENL
         [REWRITE_TAC[esubset] THEN X_GEN_TAC `w:A` THEN STRIP_TAC THEN
          USE_THEN "qmem" (fun th ->
            ASSUME_TAC(MATCH_MP th (ASSUME `(w:A) IN D`))) THEN
          ASM_MESON_TAC[esubset]; ALL_TAC] THEN
        SUBGOAL_THEN `(E:A->A->bool) x p` ASSUME_TAC THENL
         [USE_THEN "qmem" (fun th ->
            ASSUME_TAC(MATCH_MP th (ASSUME `(x:A) IN D`))) THEN
          ASM_MESON_TAC[esubset]; ALL_TAC] THEN
        CONJ_TAC THENL
         [CONJ_TAC THENL
           [FIRST_ASSUM ACCEPT_TAC; EXISTS_TAC `p:A` THEN ASM_REWRITE_TAC[]];
          EXISTS_TAC `p:A` THEN ASM_REWRITE_TAC[]]];
      ALL_TAC] THEN
    USE_THEN "R3" (fun th -> MP_TAC(ISPECL [`x:A`;`q:A`;`Y:A`] th)) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC];
    ALL_TAC] THEN
  MAP_EVERY EXISTS_TAC [`r:A`;`A2:A`] THEN
  REPEAT CONJ_TAC THENL
   [USE_THEN "rD" ACCEPT_TAC;
    USE_THEN "A2D" ACCEPT_TAC;
    USE_THEN "rfin" ACCEPT_TAC;
    USE_THEN "rii" ACCEPT_TAC;
    USE_THEN "A2sub" ACCEPT_TAC;
    USE_THEN "A2unc" ACCEPT_TAC;
    USE_THEN "petal" ACCEPT_TAC;
    USE_THEN "R3rest" ACCEPT_TAC]);;

(* ============================================================
   F6.2 s3 foundational lemmas: EFIN_INJ_OM + ECOUNTABLE_BELOW_A1 +
   EUNCOUNTABLE_AVOID (finite->countable; ordinal<aleph_1 countable;
   uncountable set not inside a countable one -> survivor exists).
   ============================================================ *)

let EFIN_INJ_OM = prove
 (`!D (E:A->A->bool) om p.
     model D E ZF_AX /\ eomega D E om /\ efin D E p ==> ?e. einj D E e p om`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`om:A`;`p:A`] EFIN_TO_NAT) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `n:A` (X_CHOOSE_THEN `f:A` STRIP_ASSUME_TAC)) THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`f:A`;`n:A`;`p:A`] EBIJ_SYM) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `g:A`) THEN
  SUBGOAL_THEN `einj D (E:A->A->bool) g p n` ASSUME_TAC THENL
   [ASM_MESON_TAC[EBIJ_EINJ]; ALL_TAC] THEN
  EXISTS_TAC `g:A` THEN MATCH_MP_TAC EINJ_WEAKEN THEN EXISTS_TAC `n:A` THEN
  CONJ_TAC THENL
   [FIRST_ASSUM ACCEPT_TAC;
    X_GEN_TAC `t:A` THEN STRIP_TAC THEN
    MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`t:A`;`n:A`;`om:A`]
      EORDINAL_MEM_TRANS) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[EOMEGA_ORDINAL];
      DISCH_THEN ACCEPT_TAC]]);;

let ECOUNTABLE_BELOW_A1 = prove
 (`!D (E:A->A->bool) om a1 xi.
     model D E ZF_AX /\ (!u. u IN D ==> elmem D E u) /\ eomega D E om /\
     a1 IN D /\ ecardinal D E a1 /\ E om a1 /\
     (!c'. c' IN D /\ E c' a1 ==> ~(ecardinal D E c' /\ E om c')) /\
     xi IN D /\ E xi a1
     ==> ?e. einj D E e xi om`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  ASM_CASES_TAC `?e:A. einj D (E:A->A->bool) e xi om` THENL
   [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  SUBGOAL_THEN `eordinal D (E:A->A->bool) a1` ASSUME_TAC THENL
   [ASM_MESON_TAC[ecardinal; ecardof]; ALL_TAC] THEN
  SUBGOAL_THEN `eordinal D (E:A->A->bool) xi` ASSUME_TAC THENL
   [ASM_MESON_TAC[EORDINAL_MEMBER]; ALL_TAC] THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`om:A`;`a1:A`;`xi:A`]
    EUNCOUNTABLE_SUCCARD_INJ) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_TAC `ee:A`) THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`ee:A`;`a1:A`;`xi:A`;`a1:A`]
    EINJ_ORDINAL_CARD_LE) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[ecardinal];
    STRIP_TAC THEN ASM_MESON_TAC[E_NOCYCLE2]]);;

let EUNCOUNTABLE_AVOID = prove
 (`!D (E:A->A->bool) om A2 S.
     model D E ZF_AX /\ om IN D /\ A2 IN D /\ S IN D /\
     ~(?e. einj D E e A2 om) /\ (?e. einj D E e S om)
     ==> ?al. al IN D /\ E al A2 /\ ~(E al S)`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "mdl omD A2D SD A2unc @es. esinj" THEN
  ASM_CASES_TAC `?al:A. al IN D /\ E al A2 /\ ~((E:A->A->bool) al S)` THENL
   [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  SUBGOAL_THEN `esubset D (E:A->A->bool) A2 S` (LABEL_TAC "sub") THENL
   [REWRITE_TAC[esubset] THEN ASM_MESON_TAC[]; ALL_TAC] THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`A2:A`] EIDF_EXISTS) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `idf:A` (CONJUNCTS_THEN2 (LABEL_TAC "idfD")
    (LABEL_TAC "idf"))) THEN
  SUBGOAL_THEN `einj D (E:A->A->bool) idf A2 S` (LABEL_TAC "idfinj") THENL
   [REWRITE_TAC[einj] THEN ASM_MESON_TAC[esubset]; ALL_TAC] THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`idf:A`;`es:A`;`A2:A`;`S:A`;`om:A`]
    EINJ_COMPOSE) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[];
    DISCH_THEN(X_CHOOSE_TAC `h:A`) THEN
    UNDISCH_TAC `~(?e:A. einj D (E:A->A->bool) e A2 om)` THEN
    REWRITE_TAC[NOT_EXISTS_THM] THEN DISCH_THEN(MP_TAC o SPEC `h:A`) THEN
    ASM_REWRITE_TAC[]]);;

(* ============================================================
   F6.2 s3 D1 batch: ECOMPIMG_FAMILY (composed family ff o g) +
   usedpt_form/HOLDS_USEDPT + EUSED_COUNTABLE (used-point union
   W = UNION_{eta<xi} ff(g eta) is countable).
   ============================================================ *)

let compimg_form = new_definition
  `compimg_form =
     ?? 70 (?? 80 (apply_form 12 11 70 &&
                   apply_form 13 70 80 &&
                   opair_form 11 80 63))`;;

let HOLDS_COMPIMG = prove
 (`!D (E:A->A->bool) v u out.
     model D E ZF_AX /\ valuation D v /\ u IN D /\ out IN D
     ==> (holds D E ((63 |-> out) ((11 |-> u) v)) compimg_form <=>
          ?m. m IN D /\ ?val. val IN D /\
              eapply D E (v 12) u m /\ eapply D E (v 13) m val /\
              eopair D E u val out)`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `valuation D ((63 |-> (out:A)) ((11 |-> (u:A)) v))`
    (LABEL_TAC "vw") THENL
   [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[] THEN
    MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  REWRITE_TAC[compimg_form; HOLDS_EX; HOLDS_AND] THEN
  SUBGOAL_THEN
   `!m val:A. m IN D /\ val IN D
      ==> (holds D E ((80 |-> val) ((70 |-> m)
             ((63 |-> (out:A)) ((11 |-> (u:A)) v)))) (apply_form 12 11 70) <=>
           eapply D E (v 12) u m) /\
          (holds D E ((80 |-> val) ((70 |-> m)
             ((63 |-> out) ((11 |-> u) v)))) (apply_form 13 70 80) <=>
           eapply D E (v 13) m val) /\
          (holds D E ((80 |-> val) ((70 |-> m)
             ((63 |-> out) ((11 |-> u) v)))) (opair_form 11 80 63) <=>
           eopair D E u val out)`
   (LABEL_TAC "piles") THENL
   [REPEAT GEN_TAC THEN STRIP_TAC THEN
    SUBGOAL_THEN
     `valuation D ((80 |-> (val:A)) ((70 |-> (m:A))
        ((63 |-> (out:A)) ((11 |-> (u:A)) v))))` ASSUME_TAC THENL
     [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
    ASM_SIMP_TAC[HOLDS_APPLY_FORM; HOLDS_OPAIR_FORM] THEN
    REWRITE_TAC[VALMOD] THEN CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN
    REWRITE_TAC[]; ALL_TAC] THEN
  MATCH_MP_TAC(MESON[]
    `(!s:A. s IN D ==> (P s <=> Q s))
     ==> ((?s. s IN D /\ P s) <=> (?s. s IN D /\ Q s))`) THEN
  X_GEN_TAC `m:A` THEN DISCH_TAC THEN
  MATCH_MP_TAC(MESON[]
    `(!s:A. s IN D ==> (P s <=> Q s))
     ==> ((?s. s IN D /\ P s) <=> (?s. s IN D /\ Q s))`) THEN
  X_GEN_TAC `val:A` THEN DISCH_TAC THEN
  USE_THEN "piles" (MP_TAC o SPECL [`m:A`; `val:A`]) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  STRIP_TAC THEN ASM_REWRITE_TAC[]);;

let ECOMPIMG_FAMILY = prove
 (`!D (E:A->A->bool) v a.
     model D E ZF_AX /\ valuation D v /\ a IN D /\
     (!n z z'. n IN D /\ z IN D /\ z' IN D /\
               eapply D E (v 12) n z /\ eapply D E (v 12) n z' ==> z = z') /\
     (!n z z'. n IN D /\ z IN D /\ z' IN D /\
               eapply D E (v 13) n z /\ eapply D E (v 13) n z' ==> z = z') /\
     (!u. u IN D /\ E u a
          ==> ?m p. m IN D /\ p IN D /\
                    eapply D E (v 12) u m /\ eapply D E (v 13) m p)
     ==> ?ffg. ffg IN D /\
               (!n z z'. n IN D /\ z IN D /\ z' IN D /\
                         eapply D E ffg n z /\
                           eapply D E ffg n z' ==> z = z') /\
               (!q. q IN D /\ E q ffg
                    ==> ?b z. b IN D /\ z IN D /\ E b a /\ eopair D E b z q) /\
               (!b. b IN D /\ E b a
                    ==> ?m p. m IN D /\ p IN D /\
                              eapply D E (v 12) b m /\ eapply D E (v 13) m p /\
                              eapply D E ffg b p)`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "mdl valv aD gsv ffsv tot" THEN
  MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `compimg_form`; `11`; `63`;
    `v:num->A`; `a:A`] EIMG_FAMILY) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[] THEN REPEAT CONJ_TAC THENL
     [CONV_TAC NUM_REDUCE_CONV;
      (* ---- FUNC: unique output pair per index ---- *)
      X_GEN_TAC `u:A` THEN STRIP_TAC THEN
      USE_THEN "tot" (MP_TAC o SPEC `u:A`) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(X_CHOOSE_THEN `m:A`
                 (X_CHOOSE_THEN `val:A` STRIP_ASSUME_TAC)) THEN
      MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `u:A`; `val:A`]
             EOPAIR_EXISTS) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(X_CHOOSE_TAC `out:A`) THEN
      SUBGOAL_THEN `(out:A) IN D` ASSUME_TAC THENL
       [ASM_MESON_TAC[EOPAIR_IN]; ALL_TAC] THEN
      EXISTS_TAC `out:A` THEN
      SUBGOAL_THEN
       `holds D E ((63 |-> (out:A)) ((11 |-> (u:A)) v)) compimg_form`
       ASSUME_TAC THENL
       [MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `v:num->A`; `u:A`; `out:A`]
          HOLDS_COMPIMG) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
        DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
        EXISTS_TAC `m:A` THEN ASM_REWRITE_TAC[] THEN
        EXISTS_TAC `val:A` THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
      ASM_REWRITE_TAC[] THEN
      X_GEN_TAC `out':A` THEN
      DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC MP_TAC) THEN
      MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `v:num->A`; `u:A`; `out':A`]
        HOLDS_COMPIMG) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
      DISCH_THEN(X_CHOOSE_THEN `m':A` (CONJUNCTS_THEN2 ASSUME_TAC
        (X_CHOOSE_THEN `val':A` STRIP_ASSUME_TAC))) THEN
      SUBGOAL_THEN `(m':A) = m` SUBST_ALL_TAC THENL
       [USE_THEN "gsv" (fun th -> MP_TAC(ISPECL [`u:A`;`m':A`;`m:A`] th)) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC];
        ALL_TAC] THEN
      SUBGOAL_THEN `(val':A) = val` SUBST_ALL_TAC THENL
       [USE_THEN "ffsv"
        (fun th -> MP_TAC(ISPECL [`m:A`;`val':A`;`val:A`] th)) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC];
        ALL_TAC] THEN
      ASM_MESON_TAC[EOPAIR_UNIQUE];
      (* ---- HF: every output is an ordered pair <u, z> ---- *)
      MAP_EVERY X_GEN_TAC [`u:A`; `out:A`] THEN STRIP_TAC THEN
      MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `v:num->A`; `u:A`; `out:A`]
        HOLDS_COMPIMG) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th ->
        UNDISCH_TAC
          `holds D E ((63 |-> (out:A)) ((11 |-> (u:A)) v)) compimg_form` THEN
        REWRITE_TAC[th]) THEN
      DISCH_THEN(X_CHOOSE_THEN `m:A` (CONJUNCTS_THEN2 ASSUME_TAC
        (X_CHOOSE_THEN `val:A` STRIP_ASSUME_TAC))) THEN
      EXISTS_TAC `val:A` THEN ASM_REWRITE_TAC[]];
    ALL_TAC] THEN
  INTRO_TAC "@ffg. ffgD mem rpairs sv peridx" THEN
  EXISTS_TAC `ffg:A` THEN REPEAT CONJ_TAC THENL
   [USE_THEN "ffgD" ACCEPT_TAC;
    USE_THEN "sv" ACCEPT_TAC;
    USE_THEN "rpairs" ACCEPT_TAC;
    X_GEN_TAC `b:A` THEN STRIP_TAC THEN
    USE_THEN "peridx" (MP_TAC o SPEC `b:A`) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(X_CHOOSE_THEN `out:A`
               (X_CHOOSE_THEN `z:A` STRIP_ASSUME_TAC)) THEN
    MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `v:num->A`; `b:A`; `out:A`]
      HOLDS_COMPIMG) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th ->
      UNDISCH_TAC
        `holds D E ((63 |-> (out:A)) ((11 |-> (b:A)) v)) compimg_form` THEN
      REWRITE_TAC[th]) THEN
    DISCH_THEN(X_CHOOSE_THEN `m:A` (CONJUNCTS_THEN2 ASSUME_TAC
      (X_CHOOSE_THEN `val:A` STRIP_ASSUME_TAC))) THEN
    SUBGOAL_THEN `(z:A) = val` SUBST_ALL_TAC THENL
     [MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `b:A`; `z:A`; `b:A`; `val:A`;
        `out:A`] EOPAIR_INJ) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(ACCEPT_TAC o CONJUNCT2); ALL_TAC] THEN
    MAP_EVERY EXISTS_TAC [`m:A`; `val:A`] THEN ASM_REWRITE_TAC[]]);;

let usedpt_form = new_definition
  `usedpt_form uv =
     ?? 40 ((40 %% 34) && ?? 41 (apply_form 35 40 41 && (uv %% 41)))`;;

let HOLDS_USEDPT = prove
 (`!D (E:A->A->bool) v uv.
     model D E ZF_AX /\ valuation D v /\ ~(uv = 40) /\ ~(uv = 41)
     ==> (holds D E v (usedpt_form uv) <=>
          ?et. et IN D /\ E et (v 34) /\
               ?z. z IN D /\ eapply D E (v 35) et z /\ E (v uv) z)`,
  REPEAT STRIP_TAC THEN
  REWRITE_TAC[usedpt_form; HOLDS_EX] THEN
  MATCH_MP_TAC(MESON[]
    `(!s:A. s IN D ==> (P s <=> Q s))
     ==> ((?s. s IN D /\ P s) <=> (?s. s IN D /\ Q s))`) THEN
  X_GEN_TAC `et:A` THEN DISCH_TAC THEN
  SUBGOAL_THEN `valuation D ((40 |-> (et:A)) v)` (LABEL_TAC "v40") THENL
   [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
  REWRITE_TAC[HOLDS_AND] THEN BINOP_TAC THENL
   [REWRITE_TAC[HOLDS_MEM; VALMOD] THEN
    CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN REWRITE_TAC[];
    REWRITE_TAC[HOLDS_EX] THEN
    MATCH_MP_TAC(MESON[]
      `(!s:A. s IN D ==> (P s <=> Q s))
       ==> ((?s. s IN D /\ P s) <=> (?s. s IN D /\ Q s))`) THEN
    X_GEN_TAC `z:A` THEN DISCH_TAC THEN
    SUBGOAL_THEN `valuation D ((41 |-> (z:A)) ((40 |-> (et:A)) v))`
      (LABEL_TAC "v41") THENL [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
    REWRITE_TAC[HOLDS_AND] THEN
    MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`;
      `(41 |-> (z:A)) ((40 |-> (et:A)) v)`; `35`; `40`; `41`]
        HOLDS_APPLY_FORM) THEN
    ASM_REWRITE_TAC[] THEN DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    REWRITE_TAC[HOLDS_MEM; VALMOD] THEN
    CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN ASM_REWRITE_TAC[]]);;

let EUSED_COUNTABLE = prove
 (`!D (E:A->A->bool) om a1 ii ff xi g.
     model D E ZF_AX /\ (!u. u IN D ==> elmem D E u) /\
     eomega D E om /\
     a1 IN D /\ ecardinal D E a1 /\ E om a1 /\
     (!c'. c' IN D /\ E c' a1 ==> ~(ecardinal D E c' /\ E om c')) /\
     ii IN D /\ ff IN D /\
     (!n z z'. n IN D /\ z IN D /\ z' IN D /\
               eapply D E ff n z /\ eapply D E ff n z' ==> z = z') /\
     (!b. b IN D /\ E b a1
          ==> ?d. d IN D /\ eapply D E ff b d /\ efin D E d /\
            esubset D E d ii) /\
     xi IN D /\ eordinal D E xi /\ E xi a1 /\ g IN D /\
     (!n z z'. n IN D /\ z IN D /\ z' IN D /\
               eapply D E g n z /\ eapply D E g n z' ==> z = z') /\
     (!et. et IN D /\ E et xi ==> ?al. al IN D /\
      eapply D E g et al /\ E al a1)
     ==> ?ffg W. ffg IN D /\ W IN D /\
             (!b. b IN D /\ E b xi
                  ==> ?m p. m IN D /\ p IN D /\
                            eapply D E g b m /\ eapply D E ff m p /\
                            eapply D E ffg b p) /\
             (!u. u IN D
                  ==> (E u W <=>
                       ?et z. et IN D /\ z IN D /\ E et xi /\
                              eapply D E ffg et z /\ E u z)) /\
             (?e. einj D E e W om)`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `(om:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[EOMEGA_IN]; ALL_TAC] THEN
  (* E1: materialise ffg = ff o g *)
  SUBGOAL_THEN
   `?ffg:A. ffg IN D /\
            (!n z z'. n IN D /\ z IN D /\ z' IN D /\
                      eapply D E ffg n z /\ eapply D E ffg n z' ==> z = z') /\
            (!q. q IN D /\ E q ffg
                 ==> ?b z. b IN D /\ z IN D /\ E b xi /\ eopair D E b z q) /\
            (!b. b IN D /\ E b xi
                 ==> ?m p. m IN D /\ p IN D /\
                           eapply D E g b m /\ eapply D E ff m p /\
                           eapply D E ffg b p)`
   STRIP_ASSUME_TAC THENL
   [MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;
      `(12 |-> (g:A)) ((13 |-> (ff:A)) (\n:num. g:A))`; `xi:A`]
                             ECOMPIMG_FAMILY) THEN
    REWRITE_TAC[VALMOD] THEN CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN
    ANTS_TAC THENL
     [REPEAT CONJ_TAC THENL
       [FIRST_ASSUM ACCEPT_TAC;
        REWRITE_TAC[valuation] THEN GEN_TAC THEN REWRITE_TAC[VALMOD] THEN
        REPEAT(COND_CASES_TAC THEN ASM_REWRITE_TAC[]);
        FIRST_ASSUM ACCEPT_TAC;
        FIRST_ASSUM ACCEPT_TAC;
        FIRST_ASSUM ACCEPT_TAC;
        X_GEN_TAC `et:A` THEN STRIP_TAC THEN
        SUBGOAL_THEN
          `?al. al IN D /\ eapply D (E:A->A->bool) g et al /\ E al a1`
          (X_CHOOSE_THEN `al:A` STRIP_ASSUME_TAC) THENL
         [FIRST_X_ASSUM MATCH_MP_TAC THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
        SUBGOAL_THEN `?d. d IN D /\ eapply D (E:A->A->bool) ff al d /\
                          efin D E d /\ esubset D E d ii`
          (X_CHOOSE_THEN `d:A` STRIP_ASSUME_TAC) THENL
         [FIRST_X_ASSUM MATCH_MP_TAC THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
        MAP_EVERY EXISTS_TAC [`al:A`;`d:A`] THEN ASM_REWRITE_TAC[]];
      DISCH_THEN ACCEPT_TAC];
    ALL_TAC] THEN
  (* E2: materialise W by separation over ii *)
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`] ZF_SEPARATION) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(MP_TAC o ISPECL [`usedpt_form 96`; `96`;
    `(34 |-> (xi:A)) ((35 |-> (ffg:A)) (\n:num. xi:A))`; `ii:A`]) THEN
  ANTS_TAC THENL
   [CONJ_TAC THENL
     [REWRITE_TAC[valuation] THEN GEN_TAC THEN REWRITE_TAC[VALMOD] THEN
      REPEAT(COND_CASES_TAC THEN ASM_REWRITE_TAC[]);
      ASM_REWRITE_TAC[]]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `W:A` (CONJUNCTS_THEN2 (LABEL_TAC "WD")
    (LABEL_TAC "Wsep"))) THEN
  (* E2b: ffgprop -- each ffg-value <= ii, finite, countable *)
  SUBGOAL_THEN
   `!et z. et IN D /\ z IN D /\ E et xi /\ eapply D (E:A->A->bool) ffg et z
           ==> esubset D E z ii /\ efin D E z /\ (?e. einj D E e z om)`
   (LABEL_TAC "ffgprop") THENL
   [MAP_EVERY X_GEN_TAC [`et:A`;`z:A`] THEN STRIP_TAC THEN
    SUBGOAL_THEN `?m p. m IN D /\ p IN D /\ eapply D E g et m /\
                        eapply D E ff m p /\ eapply D (E:A->A->bool) ffg et p`
      (X_CHOOSE_THEN `m:A` (X_CHOOSE_THEN `p:A` STRIP_ASSUME_TAC)) THENL
     [FIRST_X_ASSUM MATCH_MP_TAC THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN `(z:A) = p` SUBST_ALL_TAC THENL
     [ASM_MESON_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN `?al. al IN D /\ eapply D (E:A->A->bool) g et al /\ E al a1`
      (X_CHOOSE_THEN `al:A` STRIP_ASSUME_TAC) THENL
     [FIRST_X_ASSUM MATCH_MP_TAC THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN `(m:A) = al` SUBST_ALL_TAC THENL
     [ASM_MESON_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN
      `?d. d IN D /\ eapply D (E:A->A->bool) ff al d /\ efin D E d /\
           esubset D E d ii`
      (X_CHOOSE_THEN `d:A` STRIP_ASSUME_TAC) THENL
     [FIRST_X_ASSUM MATCH_MP_TAC THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN `(p:A) = d` SUBST_ALL_TAC THENL
     [ASM_MESON_TAC[]; ALL_TAC] THEN
    ASM_REWRITE_TAC[] THEN
    MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`om:A`;`d:A`] EFIN_INJ_OM) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC];
    ALL_TAC] THEN
  (* E3: W memberchar in ffg-form (guard dropped via ffgprop) *)
  SUBGOAL_THEN
   `!u. u IN D
        ==> (E u W <=>
             ?et z. et IN D /\ z IN D /\ E et xi /\
                    eapply D (E:A->A->bool) ffg et z /\ E u z)`
   (LABEL_TAC "Wffg") THENL
   [X_GEN_TAC `u:A` THEN DISCH_TAC THEN
    USE_THEN "Wsep" (fun th -> MP_TAC(SPEC `u:A` th)) THEN
    ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;
      `(96 |-> (u:A)) ((34 |-> (xi:A)) ((35 |-> (ffg:A)) (\n:num. xi:A)))`;
      `96`] HOLDS_USEDPT) THEN
    ANTS_TAC THENL
     [REPEAT CONJ_TAC THEN
      (FIRST_ASSUM ACCEPT_TAC ORELSE
       (REWRITE_TAC[ARITH_EQ] THEN NO_TAC) ORELSE
       (REWRITE_TAC[valuation] THEN GEN_TAC THEN REWRITE_TAC[VALMOD] THEN
        REPEAT(COND_CASES_TAC THEN ASM_REWRITE_TAC[]))); ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    REWRITE_TAC[VALMOD] THEN CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN
    REWRITE_TAC[] THEN EQ_TAC THENL
     [STRIP_TAC THEN ASM_MESON_TAC[];
      DISCH_THEN(X_CHOOSE_THEN `et:A`
                 (X_CHOOSE_THEN `z:A` STRIP_ASSUME_TAC)) THEN
      SUBGOAL_THEN `esubset D (E:A->A->bool) z ii` ASSUME_TAC THENL
       [USE_THEN "ffgprop" (fun th -> MP_TAC(ISPECL [`et:A`;`z:A`] th)) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN(ACCEPT_TAC o CONJUNCT1)];
        ALL_TAC] THEN
      CONJ_TAC THENL [ASM_MESON_TAC[esubset]; ASM_MESON_TAC[]]];
    ALL_TAC] THEN
  (* E4: xi injects om, then EGEN_UNION_CARD_LE => W countable *)
  SUBGOAL_THEN `?ea. einj D (E:A->A->bool) ea xi om`
    (X_CHOOSE_TAC `ea:A`) THENL
   [MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`om:A`;`a1:A`;`xi:A`]
      ECOUNTABLE_BELOW_A1) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`om:A`;`xi:A`;`om:A`;
     `ea:A`;`ii:A`;`ffg:A`;`W:A`] EGEN_UNION_CARD_LE) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
     [REWRITE_TAC[ecardinal] THEN MATCH_MP_TAC EOMEGA_CARDINAL THEN
      ASM_REWRITE_TAC[];
      X_GEN_TAC `b:A` THEN DISCH_TAC THEN
      SUBGOAL_THEN `?m p. m IN D /\ p IN D /\ eapply D E g b m /\
                          eapply D E ff m p /\ eapply D (E:A->A->bool) ffg b p`
        (X_CHOOSE_THEN `m:A` (X_CHOOSE_THEN `p:A` STRIP_ASSUME_TAC)) THENL
       [FIRST_X_ASSUM MATCH_MP_TAC THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
      SUBGOAL_THEN `esubset D E p ii /\ efin D E p /\
                    (?e. einj D (E:A->A->bool) e p om)`
        (CONJUNCTS_THEN2 (LABEL_TAC "psub")
          (CONJUNCTS_THEN2 (LABEL_TAC "pfin") (LABEL_TAC "pinj"))) THENL
       [USE_THEN "ffgprop" (fun th -> MP_TAC(ISPECL [`b:A`;`p:A`] th)) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC];
        ALL_TAC] THEN
      EXISTS_TAC `p:A` THEN REPEAT CONJ_TAC THENL
       [FIRST_ASSUM ACCEPT_TAC;
        FIRST_ASSUM ACCEPT_TAC;
        GEN_TAC THEN DISCH_TAC THEN
        USE_THEN "psub" (fun th -> MATCH_MP_TAC(REWRITE_RULE[esubset] th)) THEN
        ASM_REWRITE_TAC[];
        USE_THEN "pinj" (X_CHOOSE_THEN `einw:A` ASSUME_TAC) THEN
        EXISTS_TAC `einw:A` THEN CONJ_TAC THENL
         [FIRST_ASSUM(ACCEPT_TAC o CONJUNCT1 o GEN_REWRITE_RULE I [einj]);
          FIRST_ASSUM ACCEPT_TAC]]];
    (* E5: assemble *)
    DISCH_THEN(X_CHOOSE_TAC `ew:A`) THEN
    MAP_EVERY EXISTS_TAC [`ffg:A`;`W:A`] THEN REPEAT CONJ_TAC THENL
     [FIRST_ASSUM ACCEPT_TAC;
      USE_THEN "WD" ACCEPT_TAC;
      FIRST_ASSUM ACCEPT_TAC;
      USE_THEN "Wffg" ACCEPT_TAC;
      EXISTS_TAC `ew:A` THEN FIRST_ASSUM ACCEPT_TAC]]);;

(* ====================================================================
   F6.2 s3 D1: the FIBRE FAMILY + union apparatus.
   BAD_xi = UNION_{x in W\r} fibre(x) countability infrastructure.
   ==================================================================== *)
(* ==== F6.2 s3 lemma (D1) : ESUBSET_COUNTABLE =====================
   A subset of a countable set is countable.  On the s3 BAD-countability path:
   W\r SUBSET W countable => W\r countable (before enumerating W\r
     by an ordinal
   for the fibre-union bound).  Route: identity on X (EIDF_EXISTS)
     injects X into
   Y when X SUBSET Y; compose (EINJ_COMPOSE) with Y >-> om. *)

(* ==== F6.2 s3 lemma (D1, fibre-family building block) : fibmem_form ========
   The fibre-membership predicate: al IN fibre(x)  <=>  al IN A2 /\
     x IN ff(al),
   for the family i |-> fibre(h i) = {al IN A2 : h(i) IN ff al} feeding
   BAD = UNION_{x IN W\r} fibre(x).  Slots: tv = al (the tested member,
   parameter), 31 = A2, 32 = ff, 90 = x (the point), 94 = z (bound = ff(al)).
   Analog of codom_form with a MEMBERSHIP (90 %% 94) in place of the
   subset test.  HOLDS_FIBMEM done in the HOLDS_USEDPT nested/BINOP style. *)

let fibmem_form = new_definition
  `fibmem_form tv =
     (tv %% 31) && ?? 94 (apply_form 32 tv 94 && (90 %% 94))`;;

let HOLDS_FIBMEM = prove
 (`!D (E:A->A->bool) v tv.
        model D E ZF_AX /\ valuation D v /\ ~(tv = 94)
        ==> (holds D E v (fibmem_form tv) <=>
             E (v tv) (v 31) /\
             ?p. p IN D /\ eapply D E (v 32) (v tv) p /\ E (v 90) p)`,
  REPEAT STRIP_TAC THEN
  REWRITE_TAC[fibmem_form; HOLDS_AND] THEN BINOP_TAC THENL
   [REWRITE_TAC[HOLDS_MEM];
    REWRITE_TAC[HOLDS_EX] THEN
    MATCH_MP_TAC(MESON[]
      `(!s:A. s IN D ==> (P s <=> Q s))
       ==> ((?s. s IN D /\ P s) <=> (?s. s IN D /\ Q s))`) THEN
    X_GEN_TAC `p:A` THEN DISCH_TAC THEN
    SUBGOAL_THEN `valuation D ((94 |-> (p:A)) v)` (LABEL_TAC "vw") THENL
     [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
    REWRITE_TAC[HOLDS_AND] THEN
    MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `(94 |-> (p:A)) v`;
      `32`; `tv:num`; `94`] HOLDS_APPLY_FORM) THEN
    ASM_REWRITE_TAC[] THEN DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    REWRITE_TAC[HOLDS_MEM; VALMOD] THEN
    CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN ASM_REWRITE_TAC[]]);;

(* ==== F6.2 s3 crux (D1) : pfibimg_form + HOLDS_PFIBIMG =====================
   The FIBRE-FAMILY graph object-formula, mirroring pdclimg_form but with
   NO pdclstage (no rec_form/Eq): the point h(i) is computed directly by an
   apply_form.  pfibimg_form is the ZF_REPLACEMENT relation "out = <i,
   fibre(h i)>"
   where fibre(h i) = {al IN A2 : h(i) IN ff al},
   built as a comprehension-set by
   the bounded !!-biconditional  !! 2 (2 %% 62 <-> fibmem_form 2)  (fibmem_form
   reads member=slot2, A2=31, ff=32, point=90; here point 90 := h(i)).
   Slots: 11 = index i (input), 63 = output pair, 62 = section-set W (bound),
   90 = point h(i) (bound), 33 = h, 31 = A2, 32 = ff.
   HOLDS_PFIBIMG pushes through HOLDS_FIBMEM to the SEMANTIC fibre
     membership. *)

(* generic: raw !! satisfaction (absent as a named lemma; it is the holds *)
(* clause) *)

let pfibimg_form = new_definition
  `pfibimg_form =
     ?? 90 (?? 62 (apply_form 33 11 90 &&
       ((!! 2 (2 %% 62 <-> fibmem_form 2)) && opair_form 11 62 63)))`;;

let HOLDS_PFIBIMG = prove
 (`!D (E:A->A->bool) v i out.
     model D E ZF_AX /\ valuation D v /\ i IN D /\ out IN D
     ==> (holds D E ((63 |-> out) ((11 |-> i) v)) pfibimg_form <=>
          ?hpt. hpt IN D /\ eapply D E (v 33) i hpt /\
                ?W. W IN D /\
                    (!al. al IN D
                          ==> (E al W <=>
                               E al (v 31) /\
                               ?z. z IN D /\ eapply D E (v 32) al z /\
                                 E hpt z)) /\
                    eopair D E i W out)`,
  REPEAT STRIP_TAC THEN
  REWRITE_TAC[pfibimg_form; HOLDS_EX; HOLDS_AND] THEN
  (* peel the two existentials with an exists-congruence over hpt=slot90 *)
  MATCH_MP_TAC(MESON[]
    `(!a:A. a IN D ==> (P a <=> Q a))
     ==> ((?a. a IN D /\ P a) <=> (?a. a IN D /\ Q a))`) THEN
  X_GEN_TAC `hpt:A` THEN DISCH_TAC THEN
  (* now: holds ((90|->hpt)v0) (?? 62 (A && (B && C)))  <=>  eapply.. /\ ?W. *)
  (* ... *)
  REWRITE_TAC[HOLDS_EX; HOLDS_AND] THEN
  (* the apply-conjunct A is independent of the ?? 62 witness; pull it, then
     congruence over W=slot62 for B,C.  Do both directions by hand. *)
  SUBGOAL_THEN
   `!W:A. W IN D
          ==> valuation D ((62 |-> W) ((90 |-> (hpt:A))
                ((63 |-> (out:A)) ((11 |-> (i:A)) v))))`
   (LABEL_TAC "vaW") THENL
   [X_GEN_TAC `W:A` THEN DISCH_TAC THEN
    REPEAT(MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[]); ALL_TAC] THEN
  (* rewrite the three holds-conjuncts under the ?W binder via a congruence *)
  SUBGOAL_THEN
   `!W:A. W IN D
      ==> (holds D E ((62 |-> W) ((90 |-> hpt) ((63 |-> out) ((11 |-> i) v))))
                  (apply_form 33 11 90) /\
           holds D E ((62 |-> W) ((90 |-> hpt) ((63 |-> out) ((11 |-> i) v))))
                  (!! 2 (2 %% 62 <-> fibmem_form 2)) /\
           holds D E ((62 |-> W) ((90 |-> hpt) ((63 |-> out) ((11 |-> i) v))))
                  (opair_form 11 62 63)
           <=>
           eapply D E (v 33) i hpt /\
           (!al. al IN D
                 ==> (E al W <=>
                      E al (v 31) /\
                      ?z. z IN D /\ eapply D E (v 32) al z /\ E hpt z)) /\
           eopair D E i W out)`
   (LABEL_TAC "conv") THENL
   [X_GEN_TAC `W:A` THEN DISCH_TAC THEN
    USE_THEN "vaW"
      (fun th -> ASSUME_TAC(MATCH_MP th (ASSUME `(W:A) IN D`))) THEN
    (* conjunct A: apply_form *)
    MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`;
      `(62 |-> (W:A))
       ((90 |-> (hpt:A)) ((63 |-> (out:A)) ((11 |-> (i:A)) v)))`;
      `33`; `11`; `90`] HOLDS_APPLY_FORM) THEN
    ASM_REWRITE_TAC[] THEN DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    (* conjunct C: opair_form *)
    MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`;
      `(62 |-> (W:A))
       ((90 |-> (hpt:A)) ((63 |-> (out:A)) ((11 |-> (i:A)) v)))`;
      `11`; `62`; `63`] HOLDS_OPAIR_FORM) THEN
    ASM_REWRITE_TAC[] THEN DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    (* conjunct B: !! biconditional -> semantic fibre membership *)
    REWRITE_TAC[HOLDS_ALL] THEN
    REWRITE_TAC[VALMOD] THEN CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN
    (* reduce apply/opair slots and align the two conjunction shapes;
       the al-clause needs HOLDS_IFF/HOLDS_MEM/HOLDS_FIBMEM under !al *)
    MATCH_MP_TAC(MESON[]
      `(A1 <=> A2) /\ (C1 <=> C2) /\ (B1 <=> B2)
       ==> (A1 /\ B1 /\ C1 <=> A2 /\ B2 /\ C2)`) THEN
    REPEAT CONJ_TAC THENL
     [REWRITE_TAC[];
      REWRITE_TAC[];
      (* the !al biconditional *)
      MATCH_MP_TAC(MESON[]
        `(!al:A. al IN D ==> (P al <=> Q al))
         ==> ((!al. al IN D ==> P al) <=> (!al. al IN D ==> Q al))`) THEN
      X_GEN_TAC `al:A` THEN DISCH_TAC THEN
      SUBGOAL_THEN
       `valuation D ((2 |-> (al:A)) ((62 |-> (W:A)) ((90 |-> (hpt:A))
          ((63 |-> (out:A)) ((11 |-> (i:A)) v)))))` ASSUME_TAC THENL
       [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
      REWRITE_TAC[HOLDS_IFF; HOLDS_MEM] THEN
      MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`;
        `(2 |-> (al:A)) ((62 |-> (W:A)) ((90 |-> (hpt:A))
           ((63 |-> (out:A)) ((11 |-> (i:A)) v))))`; `2`] HOLDS_FIBMEM) THEN
      ASM_REWRITE_TAC[ARITH_EQ] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
      REWRITE_TAC[VALMOD] THEN CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN
      REWRITE_TAC[]];
    ALL_TAC] THEN
  (* convert each conjunct under the ?W binder (conv), then pull the
     W-independent eapply out of the existential *)
  MATCH_MP_TAC(MESON[]
    `(!W:A. W IN D ==> (L W <=> K /\ R W))
     ==> ((?W. W IN D /\ L W) <=> (K /\ (?W. W IN D /\ R W)))`) THEN
  X_GEN_TAC `W:A` THEN DISCH_TAC THEN
  USE_THEN "conv" (fun th -> ACCEPT_TAC(MATCH_MP th (ASSUME `(W:A) IN D`))));;

(* ==== F6.2 s3 crux (D1) : PFIBIMG_FUN =====================================
   Functionality of the fibre-graph relation: for each index i at which h is
   defined, there is a unique out satisfying pfibimg_form.  Mirrors
   DCLIMG_FUN_PAD but with NO pdclstage: the point hpt=h(i) is unique by
   h single-valued (not DCLSTAGE_UNIQUE), the section W by ZF_EXTENSIONALITY.
   Slots: 31=A2 (separation bound), 32=ff, 33=h.  Discharges ZF_REPLACEMENT's
   "at most one" ANTS in EFIBIMG_FAMILY. *)

let PFIBIMG_FUN = prove
 (`!D (E:A->A->bool) v i.
     model D E ZF_AX /\ valuation D v /\
     (v 31) IN D /\ (v 32) IN D /\ (v 33) IN D /\ i IN D /\
     (!n z z'. n IN D /\ z IN D /\ z' IN D /\
               eapply D E (v 33) n z /\ eapply D E (v 33) n z' ==> z = z') /\
     (?hpt. hpt IN D /\ eapply D E (v 33) i hpt)
     ==> ?out. out IN D /\
               !out'. out' IN D /\
                      holds D E ((63 |-> out') ((11 |-> i) v)) pfibimg_form
                      ==> out' = out`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  (* build W = fibre(hpt) by separation over (v 31)=A2 by fibmem_form *)
  MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`] ZF_SEPARATION) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(MP_TAC o ISPECL [`fibmem_form 2`; `2`;
    `(90 |-> (hpt:A)) v`; `(v:num->A) 31`]) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[] THEN MATCH_MP_TAC VALUATION_VALMOD THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `W:A` (CONJUNCTS_THEN2 (LABEL_TAC "WD")
    (LABEL_TAC "wsep"))) THEN
  (* semantic membership char of W (push through HOLDS_FIBMEM) *)
  SUBGOAL_THEN
   `!m. m IN D
        ==> (E m W <=>
             E m (v 31) /\
             ?z. z IN D /\ eapply D E (v 32) m z /\ E (hpt:A) z)`
   (LABEL_TAC "wsem") THENL
   [X_GEN_TAC `m:A` THEN DISCH_TAC THEN
    USE_THEN "wsep" (fun th -> MP_TAC(SPEC `m:A` th)) THEN
    ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`;
      `(2 |-> (m:A)) ((90 |-> (hpt:A)) v)`; `2`] HOLDS_FIBMEM) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[ARITH_EQ] THEN
      REPEAT(MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[]);
      ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    REWRITE_TAC[VALMOD] THEN CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN
    MESON_TAC[]; ALL_TAC] THEN
  (* out = <i, W> *)
  MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `i:A`; `W:A`] EOPAIR_EXISTS) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `out:A`) THEN
  SUBGOAL_THEN `(out:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[EOPAIR_IN]; ALL_TAC] THEN
  EXISTS_TAC `out:A` THEN ASM_REWRITE_TAC[] THEN
  X_GEN_TAC `out':A` THEN
  DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "out'D") (LABEL_TAC "hdi")) THEN
  (* extract hpt', W' via HOLDS_PFIBIMG *)
  MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `v:num->A`; `i:A`; `out':A`]
    HOLDS_PFIBIMG) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(fun th -> USE_THEN "hdi" (fun h -> MP_TAC(EQ_MP th h))) THEN
  INTRO_TAC "@hpt'. hpt'D heap' @W'. W'D wsem' eop'" THEN
  (* hpt' = hpt via h single-valued *)
  SUBGOAL_THEN `(hpt':A) = hpt` SUBST_ALL_TAC THENL
   [FIRST_X_ASSUM MATCH_MP_TAC THEN EXISTS_TAC `i:A` THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  (* W' = W via extensionality (same membership predicate) *)
  SUBGOAL_THEN `(W':A) = W` SUBST_ALL_TAC THENL
   [FIRST_ASSUM(fun mth -> MATCH_MP_TAC(MATCH_MP ZF_EXTENSIONALITY mth)) THEN
    CONJ_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    CONJ_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    X_GEN_TAC `m:A` THEN DISCH_TAC THEN
    USE_THEN "wsem" (fun th -> MP_TAC(SPEC `m:A` th)) THEN
    ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    USE_THEN "wsem'" (fun th -> MP_TAC(SPEC `m:A` th)) THEN
    ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN(fun w'E ->
               DISCH_THEN(fun wE -> ACCEPT_TAC(TRANS w'E (SYM wE))));
    ALL_TAC] THEN
  (* out' = <i,W'> = <i,W> = out *)
  ASM_MESON_TAC[EOPAIR_UNIQUE]);;

(* ==== F6.2 s3 crux (D1) : EFIBIMG_FAMILY ==================================
   THE fibre family: materialise ff = (i |-> fibre(h i)) over an ordinal a
   (a will be dd enumerating W\r; h = v 33), fibre(h i) = {al IN A2=v31 :
   h(i) IN ff32 al}, as an internal single-valued function.  Mirror
   EDCLIMG_FAMILY_PAD (ZF_REPLACEMENT + PFIBIMG_FUN functionality), but
   with the SEMANTIC HOLDS_PFIBIMG (no pdclstage; hpt=h(i) via apply_form). *)

let EFIBIMG_FAMILY = prove
 (`!D (E:A->A->bool) v a.
     model D E ZF_AX /\ valuation D v /\
     (v 31) IN D /\ (v 32) IN D /\ (v 33) IN D /\
     eordinal D E a /\ a IN D /\
     (!n z z'. n IN D /\ z IN D /\ z' IN D /\
               eapply D E (v 33) n z /\ eapply D E (v 33) n z' ==> z = z') /\
     (!u. u IN D /\ E u a ==> ?hpt. hpt IN D /\ eapply D E (v 33) u hpt)
     ==> ?ff. ff IN D /\
              (!w. w IN D
                   ==> (E w ff <=>
                        ?u. u IN D /\ E u a /\
                            holds D E ((63 |-> w) ((11 |-> u) v))
                              pfibimg_form)) /\
              (!n z z'. n IN D /\ z IN D /\ z' IN D /\
                        eapply D E ff n z /\ eapply D E ff n z' ==> z = z') /\
              (!b. b IN D /\ E b a
                   ==> ?hpt W. hpt IN D /\ W IN D /\
                             eapply D E (v 33) b hpt /\
                             (!m. m IN D
                                  ==> (E m W <=>
                                       E m (v 31) /\
                                       ?z. z IN D /\ eapply D E (v 32) m z /\
                                           E hpt z)) /\
                             eapply D E ff b W)`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  (* ZF_REPLACEMENT with pfibimg_form; functionality via PFIBIMG_FUN *)
  MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`] ZF_REPLACEMENT) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(MP_TAC o SPECL
             [`pfibimg_form`; `11`; `63`; `v:num->A`; `a:A`]) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
     [CONV_TAC NUM_REDUCE_CONV;
      X_GEN_TAC `u:A` THEN STRIP_TAC THEN
      MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `v:num->A`; `u:A`]
        PFIBIMG_FUN) THEN
      ANTS_TAC THENL
       [ASM_REWRITE_TAC[] THEN FIRST_X_ASSUM MATCH_MP_TAC THEN
        ASM_REWRITE_TAC[];
        DISCH_THEN ACCEPT_TAC]];
    ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `ff:A`
    (CONJUNCTS_THEN2 (LABEL_TAC "ffD") (LABEL_TAC "ffmem"))) THEN
  EXISTS_TAC `ff:A` THEN REPEAT CONJ_TAC THENL
   [USE_THEN "ffD" ACCEPT_TAC;
    USE_THEN "ffmem" ACCEPT_TAC;
    (* ---------------- single-valued ---------------- *)
    MAP_EVERY X_GEN_TAC [`n:A`; `z:A`; `z':A`] THEN
    REWRITE_TAC[eapply] THEN
    DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "nD")
               (CONJUNCTS_THEN2 (LABEL_TAC "zD")
                (CONJUNCTS_THEN2 (LABEL_TAC "z'D") (CONJUNCTS_THEN2
        (X_CHOOSE_THEN `q:A` STRIP_ASSUME_TAC)
        (X_CHOOSE_THEN `q':A` STRIP_ASSUME_TAC))))) THEN
    SUBGOAL_THEN `(q:A) IN D` ASSUME_TAC THENL
     [MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`n:A`;`z:A`;`q:A`]
             EOPAIR_IN) THEN
      ASM_REWRITE_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN `(q':A) IN D` ASSUME_TAC THENL
     [MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`n:A`;`z':A`;`q':A`]
             EOPAIR_IN) THEN
      ASM_REWRITE_TAC[]; ALL_TAC] THEN
    (* q in ff -> u with holds pfibimg *)
    SUBGOAL_THEN
     `?u. u IN D /\ E u a /\
          holds D E ((63 |-> (q:A)) ((11 |-> u) v)) pfibimg_form`
     (X_CHOOSE_THEN `u:A` STRIP_ASSUME_TAC) THENL
     [USE_THEN "ffmem" (fun bmem ->
        ONCE_REWRITE_TAC[GSYM(MATCH_MP bmem (ASSUME `(q:A) IN D`))]) THEN
      FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`v:num->A`;`u:A`;`q:A`]
      HOLDS_PFIBIMG) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    ASM_REWRITE_TAC[] THEN
    INTRO_TAC "@hpt. hptD heap @W. WD wc eopq" THEN
    SUBGOAL_THEN `(u:A) = n /\ (W:A) = z` (CONJUNCTS_THEN SUBST_ALL_TAC) THENL
     [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`u:A`;`W:A`;`n:A`;
        `z:A`;`q:A`] EOPAIR_INJ) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    (* q' in ff -> u' with holds pfibimg *)
    SUBGOAL_THEN
     `?u'. u' IN D /\ E u' a /\
           holds D E ((63 |-> (q':A)) ((11 |-> u') v)) pfibimg_form`
     (X_CHOOSE_THEN `u':A` STRIP_ASSUME_TAC) THENL
     [USE_THEN "ffmem" (fun bmem ->
        ONCE_REWRITE_TAC[GSYM(MATCH_MP bmem (ASSUME `(q':A) IN D`))]) THEN
      FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`v:num->A`;`u':A`;`q':A`]
      HOLDS_PFIBIMG) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    ASM_REWRITE_TAC[] THEN
    INTRO_TAC "@hpt'. hpt'D heap' @W'. W'D wc' eopq'" THEN
    SUBGOAL_THEN `(u':A) = n /\ (W':A) = z'`
      (CONJUNCTS_THEN SUBST_ALL_TAC) THENL
      [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`u':A`;`W':A`;`n:A`;
        `z':A`;`q':A`] EOPAIR_INJ) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    (* hpt' = hpt via h single-valued, then z = z' via extensionality *)
    SUBGOAL_THEN `(hpt':A) = hpt` SUBST_ALL_TAC THENL
     [FIRST_X_ASSUM MATCH_MP_TAC THEN EXISTS_TAC `n:A` THEN ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    FIRST_ASSUM(fun mth -> MATCH_MP_TAC(MATCH_MP ZF_EXTENSIONALITY mth)) THEN
    CONJ_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    CONJ_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    X_GEN_TAC `m:A` THEN DISCH_TAC THEN
    USE_THEN "wc'" (fun th -> MP_TAC(SPEC `m:A` th)) THEN
    ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    USE_THEN "wc" (fun th -> MP_TAC(SPEC `m:A` th)) THEN
    ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN(fun wcE ->
               DISCH_THEN(fun wc'E -> ACCEPT_TAC(TRANS wcE (SYM wc'E))));
    (* ---------------- per-b characterization ---------------- *)
    X_GEN_TAC `b:A` THEN STRIP_TAC THEN
    SUBGOAL_THEN `?hpt. hpt IN D /\ eapply D (E:A->A->bool) (v 33) b hpt`
      (X_CHOOSE_THEN `hpt:A` STRIP_ASSUME_TAC) THENL
     [FIRST_X_ASSUM MATCH_MP_TAC THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`] ZF_SEPARATION) THEN
    ASM_REWRITE_TAC[] THEN
    DISCH_THEN(MP_TAC o ISPECL [`fibmem_form 2`; `2`;
      `(90 |-> (hpt:A)) v`; `(v:num->A) 31`]) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[] THEN MATCH_MP_TAC VALUATION_VALMOD THEN
      ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    DISCH_THEN(X_CHOOSE_THEN `W:A` (CONJUNCTS_THEN2 (LABEL_TAC "WD")
      (LABEL_TAC "wsep"))) THEN
    SUBGOAL_THEN
     `!m. m IN D
          ==> (E m W <=>
               E m (v 31) /\
               ?z. z IN D /\ eapply D E (v 32) m z /\ E (hpt:A) z)`
     (LABEL_TAC "wsem") THENL
     [X_GEN_TAC `m:A` THEN DISCH_TAC THEN
      USE_THEN "wsep" (fun th -> MP_TAC(SPEC `m:A` th)) THEN
      ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
      MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;
        `(2 |-> (m:A)) ((90 |-> (hpt:A)) v)`; `2`] HOLDS_FIBMEM) THEN
      ANTS_TAC THENL
       [ASM_REWRITE_TAC[ARITH_EQ] THEN
        REPEAT(MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[]);
        ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
      REWRITE_TAC[VALMOD] THEN CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN
      MESON_TAC[]; ALL_TAC] THEN
    MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`b:A`;`W:A`] EOPAIR_EXISTS) THEN
    ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `out:A`) THEN
    SUBGOAL_THEN `(out:A) IN D` ASSUME_TAC THENL
     [ASM_MESON_TAC[EOPAIR_IN]; ALL_TAC] THEN
    MAP_EVERY EXISTS_TAC [`hpt:A`; `W:A`] THEN
    REPEAT CONJ_TAC THENL
     [FIRST_ASSUM ACCEPT_TAC;
      USE_THEN "WD" ACCEPT_TAC;
      FIRST_ASSUM ACCEPT_TAC;
      USE_THEN "wsem" ACCEPT_TAC;
      REWRITE_TAC[eapply] THEN EXISTS_TAC `out:A` THEN
      CONJ_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
      USE_THEN "ffmem" (fun th -> MP_TAC(SPEC `out:A` th)) THEN
      ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
      EXISTS_TAC `b:A` THEN ASM_REWRITE_TAC[] THEN
      MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`v:num->A`;`b:A`;`out:A`]
        HOLDS_PFIBIMG) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
      EXISTS_TAC `hpt:A` THEN
      CONJ_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
      CONJ_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
      EXISTS_TAC `W:A` THEN
      CONJ_TAC THENL [USE_THEN "WD" ACCEPT_TAC; ALL_TAC] THEN
      CONJ_TAC THENL [USE_THEN "wsem" ACCEPT_TAC; ALL_TAC] THEN
      FIRST_ASSUM ACCEPT_TAC]]);;

(* ==== F6.2 s3 crux (D1) : EFIBIMG_WUN =====================================
   The union of the fibre family: BAD = UNION over a of ff, with EXACTLY the
   memberchar EGEN_UNION_CARD_LE consumes.  Near-verbatim mirror of
   EDCLIMG_WUN_PAD (einran + EINRAN_SET_EXISTS + EUNION_EXISTS), with
   pfibimg_form/HOLDS_PFIBIMG (HOLDS_PFIBIMG needs only model/valuation/i/out
   in D, so no v5..v10 hyps). *)

let EFIBIMG_WUN = prove
 (`!D (E:A->A->bool) v a ff.
     model D E ZF_AX /\ valuation D v /\ eordinal D E a /\ a IN D /\ ff IN D /\
     (!w. w IN D
          ==> (E w ff <=>
               ?u. u IN D /\ E u a /\
                   holds D E ((63 |-> w) ((11 |-> u) v)) pfibimg_form))
     ==> ?wun. wun IN D /\
               !u. u IN D
                   ==> (E u wun <=>
                        ?b z. b IN D /\ z IN D /\
                              E b a /\ eapply D E ff b z /\ E u z)`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN
   `!w:A. w IN D
          ==> (einran (D:A->bool) (E:A->A->bool) w ff <=>
               ?b:A. b IN D /\ E b a /\ eapply D E ff b w)`
   (LABEL_TAC "rc") THENL
   [X_GEN_TAC `w:A` THEN DISCH_TAC THEN EQ_TAC THENL
     [REWRITE_TAC[einran] THEN
      DISCH_THEN(X_CHOOSE_THEN `pr:A`
                 (X_CHOOSE_THEN `oo:A` STRIP_ASSUME_TAC)) THEN
      SUBGOAL_THEN
       `?u. u IN D /\ E u a /\
            holds D E ((63 |-> (pr:A)) ((11 |-> u) v)) pfibimg_form`
       (X_CHOOSE_THEN `u:A` STRIP_ASSUME_TAC) THENL
       [FIRST_ASSUM(fun bmem ->
          ONCE_REWRITE_TAC[GSYM(MATCH_MP bmem (ASSUME `(pr:A) IN D`))]) THEN
        FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
      MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `v:num->A`; `u:A`; `pr:A`]
        HOLDS_PFIBIMG) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      ASM_REWRITE_TAC[] THEN
      DISCH_THEN(X_CHOOSE_THEN `hpt:A` (CONJUNCTS_THEN2 ASSUME_TAC
        (CONJUNCTS_THEN2 (K ALL_TAC)
         (X_CHOOSE_THEN `W:A` (CONJUNCTS_THEN2 ASSUME_TAC
          (CONJUNCTS_THEN2 (K ALL_TAC) ASSUME_TAC)))))) THEN
      SUBGOAL_THEN `(u:A) = oo /\ (W:A) = w`
        (CONJUNCTS_THEN SUBST_ALL_TAC) THENL
        [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`u:A`;`W:A`;`oo:A`;
          `w:A`;`pr:A`] EOPAIR_INJ) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
      EXISTS_TAC `oo:A` THEN ASM_REWRITE_TAC[] THEN
      REWRITE_TAC[eapply] THEN EXISTS_TAC `pr:A` THEN ASM_REWRITE_TAC[];
      DISCH_THEN(X_CHOOSE_THEN `b:A` STRIP_ASSUME_TAC) THEN
      SUBGOAL_THEN `?p:A. eopair (D:A->bool) (E:A->A->bool) b w p /\ E p ff`
       (X_CHOOSE_THEN `p:A` STRIP_ASSUME_TAC) THENL
       [UNDISCH_TAC `eapply (D:A->bool) (E:A->A->bool) ff b w` THEN
        REWRITE_TAC[eapply]; ALL_TAC] THEN
      SUBGOAL_THEN `(p:A) IN D` ASSUME_TAC THENL
       [MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`b:A`;`w:A`;`p:A`]
          EOPAIR_IN) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
      REWRITE_TAC[einran] THEN MAP_EVERY EXISTS_TAC [`p:A`; `b:A`] THEN
      ASM_REWRITE_TAC[]]; ALL_TAC] THEN
  MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `ff:A`] EINRAN_SET_EXISTS) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `r:A`
    (CONJUNCTS_THEN2 ASSUME_TAC (LABEL_TAC "rmem"))) THEN
  MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `r:A`] EUNION_EXISTS) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `wun:A`
    (CONJUNCTS_THEN2 ASSUME_TAC (LABEL_TAC "wmem") o
     REWRITE_RULE[eunion])) THEN
  EXISTS_TAC `wun:A` THEN ASM_REWRITE_TAC[] THEN
  X_GEN_TAC `u:A` THEN DISCH_TAC THEN
  USE_THEN "wmem" (fun th -> MP_TAC(SPEC `u:A` th)) THEN
  ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN EQ_TAC THENL
   [DISCH_THEN(X_CHOOSE_THEN `s:A` STRIP_ASSUME_TAC) THEN
    SUBGOAL_THEN
     `?b:A. b IN D /\ E b a /\ eapply (D:A->bool) (E:A->A->bool) ff b s`
     (X_CHOOSE_THEN `b:A` STRIP_ASSUME_TAC) THENL
     [USE_THEN "rc" (fun th -> MP_TAC(SPEC `s:A` th)) THEN
      ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[GSYM th]) THEN
      USE_THEN "rmem" (fun th -> MP_TAC(SPEC `s:A` th)) THEN
      ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[GSYM th]) THEN
      FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    MAP_EVERY EXISTS_TAC [`b:A`; `s:A`] THEN ASM_REWRITE_TAC[];
    DISCH_THEN(X_CHOOSE_THEN `b:A` (X_CHOOSE_THEN `z:A` STRIP_ASSUME_TAC)) THEN
    EXISTS_TAC `z:A` THEN
    CONJ_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    CONJ_TAC THENL
     [USE_THEN "rmem" (fun th ->
        ONCE_REWRITE_TAC[MATCH_MP th (ASSUME `(z:A) IN D`)]) THEN
      USE_THEN "rc" (fun th ->
        ONCE_REWRITE_TAC[MATCH_MP th (ASSUME `(z:A) IN D`)]) THEN
      EXISTS_TAC `b:A` THEN ASM_REWRITE_TAC[];
      FIRST_ASSUM ACCEPT_TAC]]);;

(* ==== F6.2 s3 D1 FINISH + D2 core ==== *)
(* ==== F6.2 s3 (D1 finish) : EBAD_COUNTABLE ================================
   BAD = {al IN A2 : ?x IN Wr. x IN ff al}  IN D and COUNTABLE, given Wr(=W\r)
   countable with elements in ii\r and the EDELTA_ROOT x-fibre bound.
   ESET_EBIJ Wr->dd,h ; EFIBIMG_FAMILY (fibfam over dd,
   tower slots 31=A2,32=ff,
   33=h) ; EFIBIMG_WUN (BAD=union) ;
   EGEN_UNION_CARD_LE (each fibre(h b) countable
   via x-fibre bound at x=h(b) IN Wr SUBSET ii\r). *)

let EBAD_COUNTABLE = prove
 (`!D (E:A->A->bool) om ii r A2 ff Wr.
     model D E ZF_AX /\ (!u. u IN D ==> elmem D E u) /\
     eomega D E om /\
     ii IN D /\ r IN D /\ A2 IN D /\ ff IN D /\ Wr IN D /\
     (!n z z'. n IN D /\ z IN D /\ z' IN D /\
               eapply D E ff n z /\ eapply D E ff n z' ==> z = z') /\
     (!x. x IN D /\ E x Wr ==> E x ii /\ ~(E x r)) /\
     (?e. einj D E e Wr om) /\
     (!x Y. x IN D /\ E x ii /\ ~(E x r) /\ Y IN D /\
            (!al. al IN D
                  ==> (E al Y <=>
                       E al A2 /\ ?d. d IN D /\ eapply D E ff al d /\ E x d))
            ==> ?e. einj D E e Y om)
     ==> ?BAD. BAD IN D /\
               (!al. al IN D
                     ==> (E al BAD <=>
                          E al A2 /\
                          ?x. x IN D /\ E x Wr /\
                              ?d. d IN D /\ eapply D E ff al d /\ E x d)) /\
               (?e. einj D E e BAD om)`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `(om:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[EOMEGA_IN]; ALL_TAC] THEN
  (* --- enumerate Wr by an ordinal dd via bijection h --- *)
  MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `Wr:A`] ESET_EBIJ) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `dd:A` (X_CHOOSE_THEN `h:A`
    (CONJUNCTS_THEN2 (LABEL_TAC "ddD") (CONJUNCTS_THEN2 (LABEL_TAC "ddord")
      (LABEL_TAC "hbij"))))) THEN
  USE_THEN "hbij" (CONJUNCTS_THEN2 (LABEL_TAC "hD")
    (CONJUNCTS_THEN2 (LABEL_TAC "hran")
      (CONJUNCTS_THEN2 (LABEL_TAC "htot0")
        (CONJUNCTS_THEN2 (LABEL_TAC "hsv")
          (CONJUNCTS_THEN2 (LABEL_TAC "hinj") (LABEL_TAC "hsurj"))))) o
    REWRITE_RULE[ebij]) THEN
  (* --- dd countable --- *)
  SUBGOAL_THEN `?ea. einj D (E:A->A->bool) ea dd om`
    (X_CHOOSE_TAC `ea:A`) THENL
   [MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`h:A`;`dd:A`;`Wr:A`]
           EBIJ_EINJ) THEN
    ANTS_TAC THENL [USE_THEN "hbij" ACCEPT_TAC; ALL_TAC] THEN DISCH_TAC THEN
    MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`h:A`;`e:A`;`dd:A`;`Wr:A`;`om:A`]
      EINJ_COMPOSE) THEN ASM_REWRITE_TAC[] THEN DISCH_THEN ACCEPT_TAC;
    ALL_TAC] THEN
  (* --- valuation tower slots 31=A2,32=ff,33=h --- *)
  SUBGOAL_THEN
   `valuation D
    ((31 |-> (A2:A)) ((32 |-> (ff:A)) ((33 |-> (h:A)) (\n:num. A2))))`
   (LABEL_TAC "Tval") THENL
   [REPEAT(MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[]) THEN
    REWRITE_TAC[valuation] THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* --- fibre family over dd --- *)
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;
    `(31 |-> (A2:A)) ((32 |-> (ff:A)) ((33 |-> (h:A)) (\n:num. A2)))`; `dd:A`]
    EFIBIMG_FAMILY) THEN
  REWRITE_TAC[VALMOD] THEN CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN
  ANTS_TAC THENL
   [REPEAT CONJ_TAC THENL
     [FIRST_ASSUM ACCEPT_TAC;
      USE_THEN "Tval" ACCEPT_TAC;
      ASM_REWRITE_TAC[];
      ASM_REWRITE_TAC[];
      USE_THEN "hD" ACCEPT_TAC;
      USE_THEN "ddord" ACCEPT_TAC;
      USE_THEN "ddD" ACCEPT_TAC;
      USE_THEN "hsv" ACCEPT_TAC;
      X_GEN_TAC `u:A` THEN STRIP_TAC THEN
      USE_THEN "htot0" (fun th -> MP_TAC(SPEC `u:A` th)) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(X_CHOOSE_THEN `t:A` STRIP_ASSUME_TAC) THEN
      EXISTS_TAC `t:A` THEN ASM_REWRITE_TAC[]];
    ALL_TAC] THEN
  INTRO_TAC "@fibfam. ffamD ffamran ffamsv ffamper" THEN
  (* --- BAD = union of the family --- *)
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;
    `(31 |-> (A2:A)) ((32 |-> (ff:A)) ((33 |-> (h:A)) (\n:num. A2)))`;
    `dd:A`; `fibfam:A`] EFIBIMG_WUN) THEN
  ANTS_TAC THENL
   [REPEAT CONJ_TAC THENL
     [FIRST_ASSUM ACCEPT_TAC;
      USE_THEN "Tval" ACCEPT_TAC;
      USE_THEN "ddord" ACCEPT_TAC;
      USE_THEN "ddD" ACCEPT_TAC;
      USE_THEN "ffamD" ACCEPT_TAC;
      USE_THEN "ffamran" ACCEPT_TAC];
    ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `BAD:A` (CONJUNCTS_THEN2 (LABEL_TAC "BADD")
    (LABEL_TAC "BADun"))) THEN
  (* --- per-b: each fibre(h b) SUBSET A2, countable --- *)
  SUBGOAL_THEN
   `!b. b IN D /\ (E:A->A->bool) b dd
        ==> ?z. z IN D /\ eapply D E fibfam b z /\
                (!u. u IN D /\ E u z ==> E u A2) /\
                (?e. e IN D /\ einj D E e z om)`
   (LABEL_TAC "perb") THENL
   [X_GEN_TAC `b:A` THEN STRIP_TAC THEN
    USE_THEN "ffamper" (fun th -> MP_TAC(SPEC `b:A` th)) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    INTRO_TAC "@hpt W. hptD WD hpteap Wmc Weap" THEN
    SUBGOAL_THEN `(E:A->A->bool) hpt Wr` (LABEL_TAC "hptWr") THENL
     [USE_THEN "hran" (fun th -> MP_TAC(ISPECL [`b:A`;`hpt:A`] th)) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> ACCEPT_TAC(CONJUNCT2 th)); ALL_TAC] THEN
    SUBGOAL_THEN `(E:A->A->bool) hpt ii /\ ~(E hpt r)` STRIP_ASSUME_TAC THENL
     [FIRST_X_ASSUM(fun th -> MATCH_MP_TAC th) THEN CONJ_TAC THENL
       [USE_THEN "hptD" ACCEPT_TAC; USE_THEN "hptWr" ACCEPT_TAC]; ALL_TAC] THEN
    EXISTS_TAC `W:A` THEN REPEAT CONJ_TAC THENL
     [USE_THEN "WD" ACCEPT_TAC;
      USE_THEN "Weap" ACCEPT_TAC;
      X_GEN_TAC `u:A` THEN STRIP_TAC THEN
      USE_THEN "Wmc" (fun th -> MP_TAC(SPEC `u:A` th)) THEN
      ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
      DISCH_THEN(fun bic ->
        ACCEPT_TAC(CONJUNCT1(EQ_MP bic (ASSUME `(E:A->A->bool) u W`))));
      SUBGOAL_THEN `?e. einj D (E:A->A->bool) e W om`
        (X_CHOOSE_TAC `ef:A`) THENL
        [FIRST_X_ASSUM(fun bnd -> MATCH_MP_TAC bnd) THEN
        EXISTS_TAC `hpt:A` THEN REPEAT CONJ_TAC THENL
         [FIRST_ASSUM ACCEPT_TAC;
          FIRST_ASSUM ACCEPT_TAC;
          FIRST_ASSUM ACCEPT_TAC;
          USE_THEN "WD" ACCEPT_TAC;
          USE_THEN "Wmc" ACCEPT_TAC]; ALL_TAC] THEN
      EXISTS_TAC `ef:A` THEN CONJ_TAC THENL
       [UNDISCH_TAC `einj D (E:A->A->bool) ef W om` THEN
        REWRITE_TAC[einj] THEN STRIP_TAC THEN FIRST_ASSUM ACCEPT_TAC;
        FIRST_ASSUM ACCEPT_TAC]]; ALL_TAC] THEN
  (* --- BAD countable via EGEN_UNION_CARD_LE --- *)
  SUBGOAL_THEN `?e. einj D (E:A->A->bool) e BAD om` (LABEL_TAC "BADcnt") THENL
   [MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`om:A`;`dd:A`;`om:A`;`ea:A`;
      `A2:A`;`fibfam:A`;`BAD:A`] EGEN_UNION_CARD_LE) THEN
    DISCH_THEN MATCH_MP_TAC THEN
    REPEAT CONJ_TAC THENL
     [FIRST_ASSUM ACCEPT_TAC;
      FIRST_ASSUM ACCEPT_TAC;
      FIRST_ASSUM ACCEPT_TAC;
      REWRITE_TAC[ecardinal] THEN MATCH_MP_TAC EOMEGA_CARDINAL THEN
      ASM_REWRITE_TAC[];
      DISJ2_TAC THEN REFL_TAC;
      ASM_REWRITE_TAC[];
      USE_THEN "ddord" ACCEPT_TAC;
      USE_THEN "ddD" ACCEPT_TAC;
      FIRST_ASSUM ACCEPT_TAC;
      ASM_REWRITE_TAC[];
      USE_THEN "ffamD" ACCEPT_TAC;
      USE_THEN "ffamsv" ACCEPT_TAC;
      USE_THEN "BADD" ACCEPT_TAC;
      USE_THEN "BADun" ACCEPT_TAC;
      USE_THEN "perb" ACCEPT_TAC]; ALL_TAC] THEN
  (* --- semantic memberchar of BAD --- *)
  EXISTS_TAC `BAD:A` THEN
  CONJ_TAC THENL [USE_THEN "BADD" ACCEPT_TAC; ALL_TAC] THEN
  CONJ_TAC THENL [ALL_TAC; USE_THEN "BADcnt" ACCEPT_TAC] THEN
  X_GEN_TAC `al:A` THEN DISCH_TAC THEN
  USE_THEN "BADun" (fun th -> MP_TAC(SPEC `al:A` th)) THEN
  ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  EQ_TAC THENL
   [(* union -> semantic *)
    DISCH_THEN(X_CHOOSE_THEN `b:A` (X_CHOOSE_THEN `z:A` STRIP_ASSUME_TAC)) THEN
    USE_THEN "ffamper" (fun th -> MP_TAC(SPEC `b:A` th)) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    INTRO_TAC "@hpt Wb. hptD WbD hpteap Wbmc Wbeap" THEN
    SUBGOAL_THEN `(z:A) = Wb` SUBST_ALL_TAC THENL
     [USE_THEN "ffamsv" (fun th ->
        MATCH_MP_TAC(ISPECL [`b:A`;`z:A`;`Wb:A`] th)) THEN ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    SUBGOAL_THEN `(E:A->A->bool) hpt Wr` (LABEL_TAC "hptWr") THENL
     [USE_THEN "hran" (fun th -> MP_TAC(ISPECL [`b:A`;`hpt:A`] th)) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> ACCEPT_TAC(CONJUNCT2 th)); ALL_TAC] THEN
    SUBGOAL_THEN
     `E (al:A) A2 /\ ?d. d IN D /\ eapply D E ff al d /\ E (hpt:A) d`
     STRIP_ASSUME_TAC THENL
     [USE_THEN "Wbmc" (fun th -> MP_TAC(SPEC `al:A` th)) THEN
      ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
      DISCH_THEN(fun bic ->
                 ACCEPT_TAC(EQ_MP bic (ASSUME `(E:A->A->bool) al Wb`)));
      ALL_TAC] THEN
    ASM_REWRITE_TAC[] THEN EXISTS_TAC `hpt:A` THEN ASM_REWRITE_TAC[] THEN
    EXISTS_TAC `d:A` THEN ASM_REWRITE_TAC[];
    (* semantic -> union *)
    STRIP_TAC THEN
    SUBGOAL_THEN `?b. b IN D /\ E b dd /\ eapply D (E:A->A->bool) h b x`
      (X_CHOOSE_THEN `b:A` STRIP_ASSUME_TAC) THENL
     [USE_THEN "hsurj" MATCH_MP_TAC THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    USE_THEN "ffamper" (fun th -> MP_TAC(SPEC `b:A` th)) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    INTRO_TAC "@hpt Wb. hptD WbD hpteap Wbmc Wbeap" THEN
    SUBGOAL_THEN `(hpt:A) = x` SUBST_ALL_TAC THENL
     [USE_THEN "hsv" (fun th ->
        MATCH_MP_TAC(ISPECL [`b:A`;`hpt:A`;`x:A`] th)) THEN ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    SUBGOAL_THEN `(E:A->A->bool) al Wb` ASSUME_TAC THENL
     [USE_THEN "Wbmc" (fun th -> MP_TAC(SPEC `al:A` th)) THEN
      ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
      CONJ_TAC THENL
       [FIRST_ASSUM ACCEPT_TAC;
        EXISTS_TAC `d:A` THEN ASM_REWRITE_TAC[]]; ALL_TAC] THEN
    MAP_EVERY EXISTS_TAC [`b:A`; `Wb:A`] THEN ASM_REWRITE_TAC[]]);;

(* ==== F6.2 s3 (D2, survivor existence) : ESURVIVOR =======================
   A2 uncountable minus (BAD UNION chosen) [both countable] is nonempty.
   Feeds the recursion step: at stage xi, chosen = g-image(xi) countable and
   BAD_xi countable (EBAD_COUNTABLE),
   so a fresh sunflower survivor exists in A2.
   Route: un = BAD U chosen (EBUNION_EXISTS); un countable via EINJ_UNION2 with
   kk=om, zr=empty, on=suc(empty) (two distinct elts of om); then
   EUNCOUNTABLE_AVOID (A2 vs un); split ~(E al un) into ~BAD /\ ~chosen.
   NEVER ASM_MESON (einj witnesses in scope). *)

let ESURVIVOR = prove
 (`!D (E:A->A->bool) om A2 BAD chosen.
     model D E ZF_AX /\ (!w. w IN D ==> elmem D E w) /\ eomega D E om /\
     A2 IN D /\ BAD IN D /\ chosen IN D /\
     ~(?e. einj D E e A2 om) /\
     (?e. einj D E e BAD om) /\ (?e. einj D E e chosen om)
     ==> ?al. al IN D /\ E al A2 /\ ~(E al BAD) /\ ~(E al chosen)`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "mdl elm eom A2D BADD chD A2unc (@eb. injom) @ec. injom2" THEN
  SUBGOAL_THEN `(om:A) IN D` (LABEL_TAC "omD") THENL
   [MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`om:A`] EOMEGA_IN) THEN
    DISCH_THEN MATCH_MP_TAC THEN USE_THEN "eom" ACCEPT_TAC; ALL_TAC] THEN
  (* zr = empty set, on = suc(empty): two distinct elements of om *)
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`] EEMPTY_EXISTS) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `e0:A`) THEN
  SUBGOAL_THEN `(e0:A) IN D` (LABEL_TAC "e0D") THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`e0:A`] EEMPTY_IN) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) e0 om` (LABEL_TAC "e0om") THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`om:A`;`e0:A`]
                 EOMEGA_EMPTY) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`e0:A`] ESUC_EXISTS) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `s0:A`) THEN
  SUBGOAL_THEN `(s0:A) IN D` (LABEL_TAC "s0D") THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`e0:A`;`s0:A`]
                 ESUC_IN) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) s0 om` (LABEL_TAC "s0om") THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`om:A`;`e0:A`;`s0:A`]
                 EOMEGA_SUC) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) e0 s0` (LABEL_TAC "e0s0") THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`e0:A`;`s0:A`]
                 ESUC_MEMBER) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `~((E:A->A->bool) e0 e0)` (LABEL_TAC "ne0e0") THENL
   [UNDISCH_TAC `eempty D (E:A->A->bool) e0` THEN REWRITE_TAC[eempty] THEN
    STRIP_TAC THEN FIRST_X_ASSUM MATCH_MP_TAC THEN USE_THEN "e0D" ACCEPT_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN `~(e0:A = s0)` (LABEL_TAC "e0ns0") THENL
   [DISCH_THEN(SUBST_ALL_TAC o SYM) THEN
    USE_THEN "e0s0" (fun th -> MP_TAC th) THEN
    USE_THEN "ne0e0" (fun th -> REWRITE_TAC[th]); ALL_TAC] THEN
  SUBGOAL_THEN `ecardinal D (E:A->A->bool) om` (LABEL_TAC "omcard") THENL
   [REWRITE_TAC[ecardinal] THEN MATCH_MP_TAC EOMEGA_CARDINAL THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* un = BAD UNION chosen *)
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`BAD:A`;`chosen:A`]
         EBUNION_EXISTS) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `un:A`) THEN
  SUBGOAL_THEN
   `(un:A) IN D /\
    (!w. w IN D ==> ((E:A->A->bool) w un <=> E w BAD \/ E w chosen))`
   (CONJUNCTS_THEN2 (LABEL_TAC "unD") (LABEL_TAC "unch")) THENL
   [MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`BAD:A`;`chosen:A`;`un:A`]
      EBUNION_ALT) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* un countable via EINJ_UNION2 *)
  SUBGOAL_THEN `?e. einj D (E:A->A->bool) e un om`
    (X_CHOOSE_THEN `eu:A` (LABEL_TAC "euinj")) THENL
   [MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`om:A`;`om:A`;`BAD:A`;`chosen:A`;
      `eb:A`;`ec:A`;`un:A`;`e0:A`;`s0:A`] EINJ_UNION2) THEN
    DISCH_THEN MATCH_MP_TAC THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* avoid: A2 uncountable vs un countable *)
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`om:A`;`A2:A`;`un:A`]
    EUNCOUNTABLE_AVOID) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[] THEN EXISTS_TAC `eu:A` THEN USE_THEN "euinj" ACCEPT_TAC;
    ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `al:A` (CONJUNCTS_THEN2 (LABEL_TAC "alD")
    (CONJUNCTS_THEN2 (LABEL_TAC "alA2") (LABEL_TAC "nalun")))) THEN
  EXISTS_TAC `al:A` THEN
  USE_THEN "alD" (fun th -> REWRITE_TAC[th]) THEN
  USE_THEN "alA2" (fun th -> REWRITE_TAC[th]) THEN
  USE_THEN "unch" (fun th -> MP_TAC(SPEC `al:A` th)) THEN
  ANTS_TAC THENL [USE_THEN "alD" ACCEPT_TAC; ALL_TAC] THEN
  DISCH_THEN(fun bic ->
    MP_TAC(REWRITE_RULE[bic] (ASSUME `~((E:A->A->bool) al un)`))) THEN
  REWRITE_TAC[DE_MORGAN_THM] THEN DISCH_THEN ACCEPT_TAC);;

(* ==== F6.2 s3 D3 object-formula/step layer ==== *)
(* ==== F6.2 s3 (D3 lemma) : interseq_form + HOLDS_INTERSEQ ==================
   The intersection-equation object formula (ABSENT from the file;
   needed for the
   sunflower condition  einter (ff al) (ff (g eta)) r  inside deltastep_form).
   interseq_form a b c  asserts  slot c = slot a INTER slot b, i.e.
   !m. m IN (slot c) <=> m IN (slot a) /\ m IN (slot b).  Bound var = slot 95.
   HOLDS bridge to the semantic `einter` via EINTER_CHAR (mirror
     HOLDS_FIBMEM). *)

let interseq_form = new_definition
  `interseq_form a b c =
     !! 95 ((95 %% c) <-> ((95 %% a) && (95 %% b)))`;;

let HOLDS_INTERSEQ = prove
 (`!D (E:A->A->bool) v a b c.
     model D E ZF_AX /\ valuation D v /\
     ~(a = 95) /\ ~(b = 95) /\ ~(c = 95)
     ==> (holds D E v (interseq_form a b c) <=>
          einter D E (v a) (v b) (v c))`,
  REPEAT STRIP_TAC THEN
  REWRITE_TAC[interseq_form; HOLDS_ALL] THEN
  MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `(v:num->A) a`; `(v:num->A) b`;
    `(v:num->A) c`] EINTER_CHAR) THEN
  ANTS_TAC THENL [ASM_MESON_TAC[valuation]; ALL_TAC] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  MATCH_MP_TAC(MESON[]
    `(!m:A. m IN D ==> (P m <=> Q m))
     ==> ((!m. m IN D ==> P m) <=> (!m. m IN D ==> Q m))`) THEN
  X_GEN_TAC `m:A` THEN DISCH_TAC THEN
  SUBGOAL_THEN `valuation D ((95 |-> (m:A)) v)` ASSUME_TAC THENL
   [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  REWRITE_TAC[HOLDS_IFF; HOLDS_AND; HOLDS_MEM; VALMOD] THEN
  CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN ASM_REWRITE_TAC[]);;

(* ==== F6.2 s3 (D3 lemma) : sunf_form + HOLDS_SUNF =========================
   The per-pair sunflower predicate: sunf_form a b asserts ff(a)
     INTER ff(b) = r,
   i.e. ?fx fc. fx=ff(a) /\ fc=ff(b) /\ einter fx fc r.  Slots: 3=ff, 5=r,
   bound 32=ff(a), 33=ff(b); interseq_form uses bound 95.  Building block of
   goodpred_form (the good-candidate predicate for deltastep_form). *)

let sunf_form = new_definition
  `sunf_form a b =
     ?? 32 (?? 33 (apply_form 3 a 32 &&
                   (apply_form 3 b 33 && interseq_form 32 33 5)))`;;

let HOLDS_SUNF = prove
 (`!D (E:A->A->bool) v a b.
     model D E ZF_AX /\ valuation D v /\
     ~(a = 32) /\ ~(a = 33) /\ ~(b = 32) /\ ~(b = 33)
     ==> (holds D E v (sunf_form a b) <=>
          ?fx. fx IN D /\ ?fc. fc IN D /\
               eapply D E (v 3) (v a) fx /\ eapply D E (v 3) (v b) fc /\
               einter D E fx fc (v 5))`,
  REPEAT STRIP_TAC THEN
  REWRITE_TAC[sunf_form; HOLDS_EX] THEN
  MATCH_MP_TAC(MESON[]
    `(!fx:A. fx IN D ==> (P fx <=> Q fx))
     ==> ((?fx. fx IN D /\ P fx) <=> (?fx. fx IN D /\ Q fx))`) THEN
  X_GEN_TAC `fx:A` THEN DISCH_TAC THEN
  REWRITE_TAC[HOLDS_EX] THEN
  MATCH_MP_TAC(MESON[]
    `(!fc:A. fc IN D ==> (P fc <=> Q fc))
     ==> ((?fc. fc IN D /\ P fc) <=> (?fc. fc IN D /\ Q fc))`) THEN
  X_GEN_TAC `fc:A` THEN DISCH_TAC THEN
  SUBGOAL_THEN `valuation D ((33 |-> (fc:A)) ((32 |-> (fx:A)) v))`
    (LABEL_TAC "vv") THENL
   [REPEAT(MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[]); ALL_TAC] THEN
  REWRITE_TAC[HOLDS_AND] THEN
  MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`;
    `(33 |-> (fc:A)) ((32 |-> (fx:A)) v)`; `3`; `a:num`; `32`]
      HOLDS_APPLY_FORM) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`;
    `(33 |-> (fc:A)) ((32 |-> (fx:A)) v)`; `3`; `b:num`; `33`]
        HOLDS_APPLY_FORM) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`;
    `(33 |-> (fc:A)) ((32 |-> (fx:A)) v)`; `32`; `33`; `5`]
          HOLDS_INTERSEQ) THEN
  ASM_REWRITE_TAC[ARITH_EQ] THEN DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  REWRITE_TAC[VALMOD] THEN CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN
  ASM_REWRITE_TAC[]);;

(* ==== F6.2 s3 (D3 lemma) : goodpred_form + HOLDS_GOODPRED =================
   The good-candidate predicate for the Delta recursion step:
     goodpred_form tv  =  tv IN A2  /\  !c IN range(g). ~(tv=c) /\
       ff(tv) INTER ff(c) = r
   i.e. tv is a fresh sunflower-compatible candidate given the prev-results
   graph g (slot 0).  Slots: tv=candidate, 0=g(prev-graph), 3=ff, 4=A2, 5=r;
   bound 30=c, 31=eta (c IN range(g) <=>
     ?eta. g(eta)=c).  Uses sunf_form (32,33
   bound; interseq 95).  HOLDS bridge in the HOLDS_FIBMEM BINOP-peel style. *)

let goodpred_form = new_definition
  `goodpred_form tv =
     (tv %% 4) &&
     !! 30 ((?? 31 (apply_form 0 31 30)) -->
            (Not(Eq tv 30) && sunf_form tv 30))`;;

let HOLDS_GOODPRED = prove
 (`!D (E:A->A->bool) v tv.
     model D E ZF_AX /\ valuation D v /\
     ~(tv = 0) /\ ~(tv = 4) /\ ~(tv = 30) /\ ~(tv = 31) /\
     ~(tv = 32) /\ ~(tv = 33)
     ==> (holds D E v (goodpred_form tv) <=>
          E (v tv) (v 4) /\
          (!c. c IN D
               ==> ((?eta. eta IN D /\ eapply D E (v 0) eta c)
                    ==> ~(v tv = c) /\
                        (?fx. fx IN D /\ ?fc. fc IN D /\
                              eapply D E (v 3) (v tv) fx /\
                              eapply D E (v 3) c fc /\
                              einter D E fx fc (v 5)))))`,
  REPEAT STRIP_TAC THEN
  REWRITE_TAC[goodpred_form; HOLDS_AND] THEN BINOP_TAC THENL
   [REWRITE_TAC[HOLDS_MEM];
    REWRITE_TAC[HOLDS_ALL] THEN
    MATCH_MP_TAC(MESON[]
      `(!c:A. c IN D ==> (P c <=> Q c))
       ==> ((!c. c IN D ==> P c) <=> (!c. c IN D ==> Q c))`) THEN
    X_GEN_TAC `c:A` THEN DISCH_TAC THEN
    SUBGOAL_THEN `valuation D ((30 |-> (c:A)) v)` (LABEL_TAC "v30") THENL
     [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    REWRITE_TAC[HOLDS_IMP] THEN BINOP_TAC THENL
     [(* guard: c IN range(g) *)
      REWRITE_TAC[HOLDS_EX] THEN
      MATCH_MP_TAC(MESON[]
        `(!eta:A. eta IN D ==> (P eta <=> Q eta))
         ==> ((?eta. eta IN D /\ P eta) <=> (?eta. eta IN D /\ Q eta))`) THEN
      X_GEN_TAC `eta:A` THEN DISCH_TAC THEN
      SUBGOAL_THEN `valuation D ((31 |-> (eta:A)) ((30 |-> (c:A)) v))`
        ASSUME_TAC THENL
       [REPEAT(MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[]);
        ALL_TAC] THEN
      MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`;
        `(31 |-> (eta:A)) ((30 |-> (c:A)) v)`; `0`; `31`; `30`]
        HOLDS_APPLY_FORM) THEN
      ASM_REWRITE_TAC[] THEN DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
      REWRITE_TAC[VALMOD] THEN CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN
      REWRITE_TAC[];
      (* body: fresh /\ sunflower *)
      REWRITE_TAC[HOLDS_AND] THEN BINOP_TAC THENL
       [REWRITE_TAC[HOLDS_NOT; holds] THEN REWRITE_TAC[VALMOD] THEN
        CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN ASM_REWRITE_TAC[];
        MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `(30 |-> (c:A)) v`;
          `tv:num`; `30`] HOLDS_SUNF) THEN
        ASM_REWRITE_TAC[ARITH_EQ] THEN
        DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
        REWRITE_TAC[VALMOD] THEN CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN
        ASM_REWRITE_TAC[]]]]);;

(* ==== F6.2 s3 (D3) : deltastep_form + DELTASTEP_HOLDS (TOTAL) =============
   Recursion STEP (erec slots 0=prev-graph g,
   1=value w): w = (slot2=ra)-LEAST of
   GG = {x IN A2 : goodpred(x) \/
     (no z is good)} = goodset if nonempty else A2.
   The NO-GOOD disjunct makes the step TOTAL (GG always nonempty),
   so EREC_EXISTS's
   unconditional QTOTAL holds;
   the invariant later shows goodset nonempty at legit
   stages so w is a genuine good choice.  rel_form 2 1 21 binds slot 22
     => GG=slot24.
   NB: The nogood `!! 25 (Not(goodpred 25))` is peeled by a
     forall-CONG over z (NOT
   ASM_REWRITE, which cannot discharge the bound z's z IN D). *)

let deltastep_form = new_definition
  `deltastep_form =
     ?? 24 ((!! 20 ((20 %% 24) <->
                    (goodpred_form 20 ||
                     ((20 %% 4) && !! 25 (Not(goodpred_form 25)))))) &&
            ((1 %% 24) &&
             !! 21 (((21 %% 24) && Not(Eq 21 1)) --> rel_form 2 1 21)))`;;

let DELTASTEP_HOLDS = prove
 (`!D (E:A->A->bool) v r w.
     model D E ZF_AX /\ valuation D v /\ r IN D /\ w IN D
     ==> (holds D E ((1 |-> w) ((0 |-> r) v)) deltastep_form <=>
          ?G. G IN D /\
              (!x. x IN D
                   ==> (E x G <=>
                        (E x (v 4) /\
                         (!c. c IN D
                              ==> ((?eta. eta IN D /\ eapply D E r eta c)
                                   ==> ~(x = c) /\
                                       (?fx. fx IN D /\ ?fc. fc IN D /\
                                             eapply D E (v 3) x fx /\
                                             eapply D E (v 3) c fc /\
                                             einter D E fx fc (v 5))))) \/
                        (E x (v 4) /\
                         (!z. z IN D
                              ==> ~(E z (v 4) /\
                                    (!c. c IN D
                                         ==> ((?eta. eta IN D /\
                                                     eapply D E r eta c)
                                              ==> ~(z = c) /\
                                                  (?fx. fx IN D /\
                                                ?fc. fc IN D /\
                                                        eapply D E
                                                          (v 3) z fx /\
                                                        eapply D E
                                                          (v 3) c fc /\
                                                        einter D E fx fc
                                                          (v 5))))))))) /\
              E w G /\
              (!al. al IN D
                    ==> (E al G /\ ~(al = w) ==> erel D E (v 2) w al)))`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `valuation D ((1 |-> (w:A)) ((0 |-> (r:A)) v))`
    (LABEL_TAC "v0") THENL
   [REPEAT(MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[]); ALL_TAC] THEN
  REWRITE_TAC[deltastep_form; HOLDS_EX] THEN
  MATCH_MP_TAC(MESON[]
    `(!G:A. G IN D ==> (P G <=> Q G))
     ==> ((?G. G IN D /\ P G) <=> (?G. G IN D /\ Q G))`) THEN
  X_GEN_TAC `G:A` THEN DISCH_TAC THEN
  SUBGOAL_THEN
   `valuation D ((24 |-> (G:A)) ((1 |-> (w:A)) ((0 |-> (r:A)) v)))`
   (LABEL_TAC "vG") THENL
   [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  REWRITE_TAC[HOLDS_AND] THEN
  MATCH_MP_TAC(MESON[]
    `(A1 <=> A2) /\ (B1 <=> B2) /\ (C1 <=> C2)
     ==> (A1 /\ B1 /\ C1 <=> A2 /\ B2 /\ C2)`) THEN
  REPEAT CONJ_TAC THENL
   [(* comprehension: !! 20 ((20 %% 24) <-> GGpred 20) *)
    REWRITE_TAC[HOLDS_ALL] THEN
    MATCH_MP_TAC(MESON[]
      `(!x:A. x IN D ==> (P x <=> Q x))
       ==> ((!x. x IN D ==> P x) <=> (!x. x IN D ==> Q x))`) THEN
    X_GEN_TAC `x:A` THEN DISCH_TAC THEN
    SUBGOAL_THEN
     `valuation D
      ((20 |-> (x:A)) ((24 |-> (G:A)) ((1 |-> (w:A)) ((0 |-> (r:A)) v))))`
     (LABEL_TAC "vx") THENL
     [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN
     `holds D E
      ((20 |-> (x:A)) ((24 |-> (G:A)) ((1 |-> (w:A)) ((0 |-> (r:A)) v))))
        (goodpred_form 20 || ((20 %% 4) && !! 25 (Not(goodpred_form 25)))) <=>
      (E x (v 4) /\
       (!c. c IN D
            ==> ((?eta. eta IN D /\ eapply D E r eta c)
                 ==> ~(x = c) /\
                     (?fx. fx IN D /\ ?fc. fc IN D /\
                           eapply D E (v 3) x fx /\ eapply D E (v 3) c fc /\
                           einter D E fx fc (v 5))))) \/
      (E x (v 4) /\
       (!z. z IN D
            ==> ~(E z (v 4) /\
                  (!c. c IN D
                       ==> ((?eta. eta IN D /\ eapply D E r eta c)
                            ==> ~(z = c) /\
                                (?fx. fx IN D /\ ?fc. fc IN D /\
                                      eapply D E (v 3) z fx /\
                                      eapply D E (v 3) c fc /\
                                      einter D E fx fc (v 5)))))))`
     (LABEL_TAC "hgg") THENL
     [REWRITE_TAC[HOLDS_OR] THEN
      MATCH_MP_TAC(TAUT `(a <=> c) /\ (b <=> d) ==> (a \/ b <=> c \/ d)`) THEN
      CONJ_TAC THENL
       [MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`;
          `(20 |-> (x:A))
           ((24 |-> (G:A)) ((1 |-> (w:A)) ((0 |-> (r:A)) v)))`; `20`]
          HOLDS_GOODPRED) THEN
        ASM_REWRITE_TAC[ARITH_EQ] THEN
        DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
        REWRITE_TAC[VALMOD] THEN CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN
        REWRITE_TAC[];
        REWRITE_TAC[HOLDS_AND] THEN
        MATCH_MP_TAC(TAUT
                     `(a <=> c) /\ (b <=> d) ==> (a /\ b <=> c /\ d)`) THEN
        CONJ_TAC THENL
         [REWRITE_TAC[HOLDS_MEM; VALMOD] THEN
          CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN REWRITE_TAC[];
          REWRITE_TAC[HOLDS_ALL] THEN
          MATCH_MP_TAC(MESON[]
            `(!z:A. z IN D ==> (P z <=> Q z))
             ==> ((!z. z IN D ==> P z) <=> (!z. z IN D ==> Q z))`) THEN
          X_GEN_TAC `z:A` THEN DISCH_TAC THEN
          SUBGOAL_THEN
           `valuation D ((25 |-> (z:A)) ((20 |-> (x:A)) ((24 |-> (G:A))
              ((1 |-> (w:A)) ((0 |-> (r:A)) v)))))` ASSUME_TAC THENL
           [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
          REWRITE_TAC[HOLDS_NOT] THEN AP_TERM_TAC THEN
          MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`;
            `(25 |-> (z:A)) ((20 |-> (x:A)) ((24 |-> (G:A))
               ((1 |-> (w:A)) ((0 |-> (r:A)) v))))`; `25`] HOLDS_GOODPRED) THEN
          ASM_REWRITE_TAC[ARITH_EQ] THEN
          DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
          REWRITE_TAC[VALMOD] THEN
          CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN
          REWRITE_TAC[]]]; ALL_TAC] THEN
    REWRITE_TAC[HOLDS_IFF; HOLDS_MEM] THEN
    REWRITE_TAC[VALMOD] THEN CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN
    ASM_REWRITE_TAC[];
    (* w IN G:  (1 %% 24) *)
    REWRITE_TAC[HOLDS_MEM; VALMOD] THEN
    CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN REWRITE_TAC[];
    (* leastcond *)
    REWRITE_TAC[HOLDS_ALL] THEN
    MATCH_MP_TAC(MESON[]
      `(!al:A. al IN D ==> (P al <=> Q al))
       ==> ((!al. al IN D ==> P al) <=> (!al. al IN D ==> Q al))`) THEN
    X_GEN_TAC `al:A` THEN DISCH_TAC THEN
    SUBGOAL_THEN
     `valuation D
      ((21 |-> (al:A)) ((24 |-> (G:A)) ((1 |-> (w:A)) ((0 |-> (r:A)) v))))`
     (LABEL_TAC "val") THENL
     [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    REWRITE_TAC[HOLDS_IMP; HOLDS_AND; HOLDS_NOT; HOLDS_MEM] THEN
    MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`;
      `(21 |-> (al:A)) ((24 |-> (G:A)) ((1 |-> (w:A)) ((0 |-> (r:A)) v)))`;
      `2`; `1`; `21`] HOLDS_REL_FORM) THEN
    ASM_REWRITE_TAC[] THEN DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    REWRITE_TAC[holds; VALMOD] THEN
    CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN REWRITE_TAC[]]);;

(* ==== F6.2 s3 D3 QFUN/QTOTAL ==== *)
(* ==== F6.2 s3 (D3) : ggpred_form + HOLDS_GGPRED ==========================
   The total good-set membership predicate (deltastep's comprehension body):
     ggpred_form tv = goodpred_form tv || ((tv %% 4) &&
       !! 25 (Not(goodpred_form 25)))
   = "tv is good, OR tv IN A2 and no z is good".  HOLDS_GGPRED = the GGMEM char
   (factored from DELTASTEP_HOLDS's comprehension branch).  Used by
     EDELTASTEP_QTOTAL
   to materialise GG by ZF_SEPARATION on A2.  Note goodpred_form tv
     unfolds to the
   same term deltastep_form uses inline,
   so `REWRITE[ggpred_form]` connects them. *)

let ggpred_form = new_definition
  `ggpred_form tv =
     goodpred_form tv || ((tv %% 4) && !! 25 (Not(goodpred_form 25)))`;;

let HOLDS_GGPRED = prove
 (`!D (E:A->A->bool) v tv.
     model D E ZF_AX /\ valuation D v /\
     ~(tv = 0) /\ ~(tv = 4) /\ ~(tv = 25) /\ ~(tv = 30) /\ ~(tv = 31) /\
     ~(tv = 32) /\ ~(tv = 33)
     ==> (holds D E v (ggpred_form tv) <=>
          (E (v tv) (v 4) /\
           (!c. c IN D
                ==> ((?eta. eta IN D /\ eapply D E (v 0) eta c)
                     ==> ~(v tv = c) /\
                         (?fx. fx IN D /\ ?fc. fc IN D /\
                               eapply D E (v 3) (v tv) fx /\
                               eapply D E (v 3) c fc /\
                               einter D E fx fc (v 5))))) \/
          (E (v tv) (v 4) /\
           (!z. z IN D
                ==> ~(E z (v 4) /\
                      (!c. c IN D
                           ==> ((?eta. eta IN D /\ eapply D E (v 0) eta c)
                                ==> ~(z = c) /\
                                    (?fx. fx IN D /\ ?fc. fc IN D /\
                                          eapply D E (v 3) z fx /\
                                          eapply D E (v 3) c fc /\
                                          einter D E fx fc (v 5))))))))`,
  REPEAT STRIP_TAC THEN
  REWRITE_TAC[ggpred_form; HOLDS_OR] THEN
  MATCH_MP_TAC(TAUT `(a <=> c) /\ (b <=> d) ==> (a \/ b <=> c \/ d)`) THEN
  CONJ_TAC THENL
   [MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `v:num->A`; `tv:num`]
      HOLDS_GOODPRED) THEN ASM_REWRITE_TAC[] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]);
    REWRITE_TAC[HOLDS_AND] THEN
    MATCH_MP_TAC(TAUT `(a <=> c) /\ (b <=> d) ==> (a /\ b <=> c /\ d)`) THEN
    CONJ_TAC THENL
     [REWRITE_TAC[HOLDS_MEM];
      REWRITE_TAC[HOLDS_ALL] THEN
      MATCH_MP_TAC(MESON[]
        `(!z:A. z IN D ==> (P z <=> Q z))
         ==> ((!z. z IN D ==> P z) <=> (!z. z IN D ==> Q z))`) THEN
      X_GEN_TAC `z:A` THEN DISCH_TAC THEN
      SUBGOAL_THEN `valuation D ((25 |-> (z:A)) v)` ASSUME_TAC THENL
       [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
      REWRITE_TAC[HOLDS_NOT] THEN AP_TERM_TAC THEN
      MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `(25 |-> (z:A)) v`; `25`]
        HOLDS_GOODPRED) THEN
      ASM_REWRITE_TAC[ARITH_EQ] THEN DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
      REWRITE_TAC[VALMOD] THEN CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN
      REWRITE_TAC[]]]);;

(* ==== F6.2 s3 (D3) : EDELTASTEP_QFUN =====================================
   Functionality of the deltastep: two values w,w' at the same prev-graph r are
   equal.  Both are ra-least of the good set (GG);
   the two good sets G,G' have the
   SAME (G-free) membership predicate GGMEM => G=G' by ZF_EXTENSIONALITY; then
   w=w' by LEASTMEM_UNIQUE.  Matches EREC_EXISTS's QFUN hypothesis shape.
   Needs only the L-wellorder hyps (elwoinvu s / elwou s (v2) /
     elstage s ya). *)

let EDELTASTEP_QFUN = prove
 (`!D (E:A->A->bool) v s ya.
     model D E ZF_AX /\ valuation D v /\
     s IN D /\ (v 2) IN D /\ ya IN D /\
     elwoinvu D E s /\ elwou D E s (v 2) /\ elstage D E s ya
     ==> (!r w w'. r IN D /\ w IN D /\ w' IN D /\
                   holds D E ((1 |-> w) ((0 |-> r) v)) deltastep_form /\
                   holds D E ((1 |-> w') ((0 |-> r) v)) deltastep_form
                   ==> w = w')`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  REPEAT GEN_TAC THEN
  INTRO_TAC "rD wD w'D hw hw'" THEN
  MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `v:num->A`; `r:A`; `w:A`]
    DELTASTEP_HOLDS) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(fun th -> USE_THEN "hw" (fun h -> MP_TAC(EQ_MP th h))) THEN
  INTRO_TAC "@G. GD mcG EwG lcw" THEN
  MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `v:num->A`; `r:A`; `w':A`]
    DELTASTEP_HOLDS) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(fun th -> USE_THEN "hw'" (fun h -> MP_TAC(EQ_MP th h))) THEN
  INTRO_TAC "@G'. G'D mcG' Ew'G' lcw'" THEN
  (* G = G' by extensionality (same G-free membership predicate GGMEM) *)
  SUBGOAL_THEN `(G:A) = G'` SUBST_ALL_TAC THENL
   [FIRST_ASSUM(MATCH_MP_TAC o MATCH_MP ZF_EXTENSIONALITY) THEN
    CONJ_TAC THENL [USE_THEN "GD" ACCEPT_TAC; ALL_TAC] THEN
    CONJ_TAC THENL [USE_THEN "G'D" ACCEPT_TAC; ALL_TAC] THEN
    X_GEN_TAC `x:A` THEN DISCH_TAC THEN
    USE_THEN "mcG" (fun th -> MP_TAC(SPEC `x:A` th)) THEN
    ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    USE_THEN "mcG'" (fun th -> MP_TAC(SPEC `x:A` th)) THEN
    ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]); ALL_TAC] THEN
  (* w = w' by LEASTMEM_UNIQUE on G *)
  MATCH_MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `s:A`; `(v:num->A) 2`;
    `ya:A`; `G':A`; `w:A`; `w':A`] LEASTMEM_UNIQUE) THEN
  ASM_REWRITE_TAC[] THEN
  CONJ_TAC THEN REPEAT STRIP_TAC THEN ASM_MESON_TAC[]);;

(* ==== F6.2 s3 (D3) : EDELTASTEP_QTOTAL ===================================
   Totality of the deltastep: for EVERY prev-graph x, a value y exists.  y =
   ra-least of GG = {z IN A2 : ggpred(z)}.  GG is always nonempty (goodset if
   nonempty, else A2 via the no-good disjunct) -- pure case-split,
   NO ESURVIVOR.
   Needs A2=(v4) nonempty + A2 SUBSET ya + wellorder hyps.  Matches
     EREC_EXISTS's
   QTOTAL shape. *)

let EDELTASTEP_QTOTAL = prove
 (`!D (E:A->A->bool) v s ya.
     model D E ZF_AX /\ valuation D v /\
     s IN D /\ (v 2) IN D /\ ya IN D /\
     elwoinvu D E s /\ elwou D E s (v 2) /\ elstage D E s ya /\
     (v 4) IN D /\ (!t. t IN D /\ E t (v 4) ==> E t ya) /\
     (?a. a IN D /\ E a (v 4))
     ==> (!x. x IN D
              ==> ?y. y IN D /\
                holds D E ((1 |-> y) ((0 |-> x) v)) deltastep_form)`,
  REPEAT GEN_TAC THEN
  DISCH_THEN(REPEAT_TCL CONJUNCTS_THEN ASSUME_TAC) THEN
  FIRST_X_ASSUM(X_CHOOSE_THEN `a0:A` STRIP_ASSUME_TAC o
    check (fun th -> is_exists(concl th))) THEN
  X_GEN_TAC `x:A` THEN DISCH_TAC THEN
  SUBGOAL_THEN `valuation D ((0 |-> (x:A)) v)` (LABEL_TAC "v0x") THENL
   [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* materialise GG = {z IN A2 : ggpred(z)} *)
  MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`] ZF_SEPARATION) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(MP_TAC o ISPECL [`ggpred_form 20`; `20`; `(0 |-> (x:A)) v`;
    `(v:num->A) 4`]) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `GG:A` (CONJUNCTS_THEN2 (LABEL_TAC "GGD")
    (LABEL_TAC "GGsep"))) THEN
  (* GG char: E z GG <=> GGMEM z  (absorb the E z A2 bound via TAUT) *)
  SUBGOAL_THEN
   `!z. z IN D
        ==> ((E:A->A->bool) z GG <=>
             (E z (v 4) /\
              (!c. c IN D
                   ==> ((?eta. eta IN D /\ eapply D E x eta c)
                        ==> ~(z = c) /\
                            (?fx. fx IN D /\ ?fc. fc IN D /\
                                  eapply D E (v 3) z fx /\
                                    eapply D E (v 3) c fc /\
                                  einter D E fx fc (v 5))))) \/
             (E z (v 4) /\
              (!z'. z' IN D
                    ==> ~(E z' (v 4) /\
                          (!c. c IN D
                               ==> ((?eta. eta IN D /\ eapply D E x eta c)
                                    ==> ~(z' = c) /\
                                        (?fx. fx IN D /\ ?fc. fc IN D /\
                                              eapply D E (v 3) z' fx /\
                                              eapply D E (v 3) c fc /\
                                              einter D E fx fc (v 5))))))))`
   (LABEL_TAC "GGchar") THENL
   [X_GEN_TAC `z:A` THEN DISCH_TAC THEN
    USE_THEN "GGsep" (fun th -> MP_TAC(SPEC `z:A` th)) THEN
    ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    SUBGOAL_THEN `valuation D ((20 |-> (z:A)) ((0 |-> (x:A)) v))`
      ASSUME_TAC THENL
      [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`;
      `(20 |-> (z:A)) ((0 |-> (x:A)) v)`; `20`] HOLDS_GGPRED) THEN
    ASM_REWRITE_TAC[ARITH_EQ] THEN DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    REWRITE_TAC[VALMOD] THEN CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN
    CONV_TAC TAUT; ALL_TAC] THEN
  (* GG nonempty: case-split on whether some z is good *)
  SUBGOAL_THEN `?g0. g0 IN D /\ (E:A->A->bool) g0 GG`
    (X_CHOOSE_THEN `g0:A` STRIP_ASSUME_TAC) THENL
   [ASM_CASES_TAC
     `?z. z IN D /\ (E:A->A->bool) z (v 4) /\
          (!c. c IN D
               ==> ((?eta. eta IN D /\ eapply D E x eta c)
                    ==> ~(z = c) /\
                        (?fx. fx IN D /\ ?fc. fc IN D /\
                              eapply D E (v 3) z fx /\ eapply D E (v 3) c fc /\
                              einter D E fx fc (v 5))))`
     THENL
     [FIRST_X_ASSUM(X_CHOOSE_THEN `z0:A` STRIP_ASSUME_TAC) THEN
      EXISTS_TAC `z0:A` THEN ASM_REWRITE_TAC[] THEN
      USE_THEN "GGchar" (fun th -> MP_TAC(SPEC `z0:A` th)) THEN
      ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN DISJ1_TAC THEN
      ASM_REWRITE_TAC[];
      EXISTS_TAC `a0:A` THEN ASM_REWRITE_TAC[] THEN
      USE_THEN "GGchar" (fun th -> MP_TAC(SPEC `a0:A` th)) THEN
      ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN DISJ2_TAC THEN
      ASM_REWRITE_TAC[] THEN X_GEN_TAC `z':A` THEN
      DISCH_TAC THEN DISCH_TAC THEN
      FIRST_X_ASSUM(MP_TAC o check(is_neg o concl)) THEN
      REWRITE_TAC[] THEN EXISTS_TAC `z':A` THEN ASM_REWRITE_TAC[]];
     ALL_TAC] THEN
  (* GG SUBSET ya *)
  SUBGOAL_THEN `!t. t IN D /\ (E:A->A->bool) t GG ==> E t ya`
    (LABEL_TAC "GGsub") THENL
   [X_GEN_TAC `t:A` THEN STRIP_TAC THEN
    FIRST_X_ASSUM(fun sub -> MATCH_MP_TAC sub) THEN
    USE_THEN "GGchar" (fun th -> MP_TAC(SPEC `t:A` th)) THEN
    ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    ASM_REWRITE_TAC[] THEN STRIP_TAC THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* LEASTMEM_EXISTS => y *)
  MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `s:A`; `(v:num->A) 2`; `ya:A`;
    `GG:A`] LEASTMEM_EXISTS) THEN
  ANTS_TAC THENL
   [REPEAT CONJ_TAC THENL
     [FIRST_ASSUM ACCEPT_TAC; FIRST_ASSUM ACCEPT_TAC; FIRST_ASSUM ACCEPT_TAC;
      FIRST_ASSUM ACCEPT_TAC; FIRST_ASSUM ACCEPT_TAC; FIRST_ASSUM ACCEPT_TAC;
      FIRST_ASSUM ACCEPT_TAC; USE_THEN "GGD" ACCEPT_TAC;
      USE_THEN "GGsub" ACCEPT_TAC;
      EXISTS_TAC `g0:A` THEN ASM_REWRITE_TAC[]]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `y:A` (CONJUNCTS_THEN2 (LABEL_TAC "yD")
    (CONJUNCTS_THEN2 (LABEL_TAC "EyGG") (LABEL_TAC "ylc")))) THEN
  (* provide y; DELTASTEP_HOLDS backward with G := GG *)
  EXISTS_TAC `y:A` THEN
  USE_THEN "yD" (fun th -> REWRITE_TAC[th]) THEN
  MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `v:num->A`; `x:A`; `y:A`]
    DELTASTEP_HOLDS) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  EXISTS_TAC `GG:A` THEN
  REPEAT CONJ_TAC THENL
   [USE_THEN "GGD" ACCEPT_TAC;
    USE_THEN "GGchar" ACCEPT_TAC;
    USE_THEN "EyGG" ACCEPT_TAC;
    X_GEN_TAC `al:A` THEN DISCH_TAC THEN STRIP_TAC THEN
    USE_THEN "ylc" (fun th -> MATCH_MP_TAC th) THEN ASM_REWRITE_TAC[]]);;

(* ======================================================================== *)
(* F6.2 s3 : D4 recursion-run + helpers (EUNCOUNTABLE_NONEMPTY, FV_DELTASTEP *)
(* _LT, EDELTAREC_EXISTS, EDELTAREC_RESEXISTS).                              *)
(* ======================================================================== *)

(* ==== F6.2 s3 (D4 helper) : EUNCOUNTABLE_NONEMPTY ========================
   An uncountable set is nonempty (needed to run the recursion / feed QTOTAL's
   A2-nonempty hyp).  If A2 had no element it would be empty, hence finite,
   hence inject into om (EFIN_INJ_OM) -- contradicting uncountability. *)

let EUNCOUNTABLE_NONEMPTY = prove
 (`!D (E:A->A->bool) om A2.
     model D E ZF_AX /\ eomega D E om /\ A2 IN D /\ ~(?e. einj D E e A2 om)
     ==> ?a. a IN D /\ E a A2`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  ASM_CASES_TAC `?a. a IN D /\ (E:A->A->bool) a A2` THENL
   [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  SUBGOAL_THEN `eempty D (E:A->A->bool) A2` ASSUME_TAC THENL
   [REWRITE_TAC[eempty] THEN CONJ_TAC THENL
     [FIRST_ASSUM ACCEPT_TAC;
      X_GEN_TAC `w:A` THEN REPEAT DISCH_TAC THEN
      UNDISCH_TAC `~(?a. a IN D /\ (E:A->A->bool) a A2)` THEN
      REWRITE_TAC[] THEN EXISTS_TAC `w:A` THEN ASM_REWRITE_TAC[]];
    ALL_TAC] THEN
  SUBGOAL_THEN `?e. einj D (E:A->A->bool) e A2 om` MP_TAC THENL
   [MATCH_MP_TAC EFIN_INJ_OM THEN ASM_REWRITE_TAC[] THEN
    MATCH_MP_TAC EFIN_EMPTY THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  ASM_REWRITE_TAC[]);;

(* ==== F6.2 s3 (D5 helper) : FV_DELTASTEP_LT ==============================
   Free-variable bound for deltastep_form, needed by HOLDS_REC_FORM to form
   deltaval_form = rec_form deltastep_form 96.  FV(deltastep_form) =
     {0,1,2,3,4,5}
   (all bound slots 20,21,24,25,30-33,95 cancel via DELETE);
   96 leaves rec_form's
   added slots 96..100 clear of every deltastep slot.  Clone of
     FV_ULTRASTEP_LT. *)

(* ==== F6.2 s3 (D4) : EDELTAREC_EXISTS ====================================
   The delta recursion runs: at every ordinal a the erec value h(a) exists.
   Discharges EREC_EXISTS's QFUN/QTOTAL via EDELTASTEP_QFUN /
     EDELTASTEP_QTOTAL,
   which need the L-wellorder hyps (elwoinvu s / elwou s (v2) / elstage s ya)
   plus A2=(v4) SUBSET ya and A2 nonempty.  Mirror of EULTRAREC_EXISTS.
   NOTE: the A2-nonempty hyp is kept as `?a. a IN D /\ E a (v 4)` (ASSUME_TAC,
   not STRIP) so ASM_REWRITE can discharge QTOTAL's identical premise. *)

let EDELTAREC_EXISTS = prove
 (`!D (E:A->A->bool) v s ya.
      model D E ZF_AX /\ valuation D v /\
      s IN D /\ (v 2) IN D /\ ya IN D /\
      elwoinvu D E s /\ elwou D E s (v 2) /\ elstage D E s ya /\
      (v 4) IN D /\ (!t. t IN D /\ E t (v 4) ==> E t ya) /\
      (?a. a IN D /\ E a (v 4))
      ==> !a. eordinal D E a ==> ?y. y IN D /\ erec D E deltastep_form v a y`,
  REPEAT GEN_TAC THEN DISCH_THEN(REPEAT_TCL CONJUNCTS_THEN ASSUME_TAC) THEN
  X_GEN_TAC `a:A` THEN DISCH_TAC THEN
  MATCH_MP_TAC EREC_EXISTS THEN ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`; `E:A->A->bool`; `v:num->A`; `s:A`; `ya:A`]
                 EDELTASTEP_QFUN);
    MATCH_MP_TAC(ISPECL
                 [`D:A->bool`; `E:A->A->bool`; `v:num->A`; `s:A`; `ya:A`]
                 EDELTASTEP_QTOTAL)] THEN
  ASM_REWRITE_TAC[]);;

(* D4 graph: the erecres graph r_a = {<b,h(b)> : b<a} exists at every ordinal,
   used in D6 to form jj = range(r_a1).  Same discharge as EDELTAREC_EXISTS. *)
let EDELTAREC_RESEXISTS = prove
 (`!D (E:A->A->bool) v s ya.
      model D E ZF_AX /\ valuation D v /\
      s IN D /\ (v 2) IN D /\ ya IN D /\
      elwoinvu D E s /\ elwou D E s (v 2) /\ elstage D E s ya /\
      (v 4) IN D /\ (!t. t IN D /\ E t (v 4) ==> E t ya) /\
      (?a. a IN D /\ E a (v 4))
      ==> !a. eordinal D E a ==> ?r. erecres D E deltastep_form v a r`,
  REPEAT GEN_TAC THEN DISCH_THEN(REPEAT_TCL CONJUNCTS_THEN ASSUME_TAC) THEN
  X_GEN_TAC `a:A` THEN DISCH_TAC THEN
  MATCH_MP_TAC ERECRES_EXISTS THEN ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`; `E:A->A->bool`; `v:num->A`; `s:A`; `ya:A`]
                 EDELTASTEP_QFUN);
    MATCH_MP_TAC(ISPECL
                 [`D:A->bool`; `E:A->A->bool`; `v:num->A`; `s:A`; `ya:A`]
                 EDELTASTEP_QTOTAL)] THEN
  ASM_REWRITE_TAC[]);;

(* ======================================================================== *)
(* F6.2 s3 (D5/D6 CRUX): GOODSET_NONEMPTY -- a good survivor point exists.   *)
(* ======================================================================== *)

(* ==== F6.2 s3 (D5/D6 crux) : GOODSET_NONEMPTY ============================
   Given the graph g (et|->prior) over ordinal xi<a1 with each prior in A2, a
   GOOD point al exists: al IN A2, al fresh (=/= every prior g(et)),
   and al forms
   a sunflower with every prior (einter (ff al) (ff (g et)) r).
     Chains the three
   banked lemmas EUSED_COUNTABLE / EBAD_COUNTABLE / ESURVIVOR + petals +
     EINTER_CHAR. *)

let GOODSET_NONEMPTY = prove
 (`!D (E:A->A->bool) om a1 ii ff r A2 xi g.
     model D E ZF_AX /\ (!u. u IN D ==> elmem D E u) /\
     eomega D E om /\
     a1 IN D /\ ecardinal D E a1 /\ E om a1 /\
     (!c'. c' IN D /\ E c' a1 ==> ~(ecardinal D E c' /\ E om c')) /\
     ii IN D /\ ff IN D /\ r IN D /\ A2 IN D /\
     (!n z z'. n IN D /\ z IN D /\ z' IN D /\
               eapply D E ff n z /\ eapply D E ff n z' ==> z = z') /\
     (!b. b IN D /\ E b a1
          ==> ?d. d IN D /\ eapply D E ff b d /\ efin D E d /\
            esubset D E d ii) /\
     esubset D E r ii /\ esubset D E A2 a1 /\ ~(?e. einj D E e A2 om) /\
     (!al. al IN D /\ E al A2 ==> ?d. d IN D /\ eapply D E ff al d /\
      esubset D E r d) /\
     (!x Y. x IN D /\ E x ii /\ ~(E x r) /\ Y IN D /\
            (!al. al IN D
                  ==> (E al Y <=>
                       E al A2 /\ ?d. d IN D /\ eapply D E ff al d /\ E x d))
            ==> ?e. einj D E e Y om) /\
     xi IN D /\ eordinal D E xi /\ E xi a1 /\ g IN D /\ eisfun D E g /\
     (!n z z'. n IN D /\ z IN D /\ z' IN D /\
               eapply D E g n z /\ eapply D E g n z' ==> z = z') /\
     (!k z. k IN D /\ z IN D /\ eapply D E g k z ==> E k xi) /\
     (!et. et IN D /\ E et xi ==> ?al. al IN D /\
      eapply D E g et al /\ E al A2)
     ==> ?al. al IN D /\ E al A2 /\
              (!et c. et IN D /\ c IN D /\ E et xi /\ eapply D E g et c ==>
               ~(c = al)) /\
              (!et c dal dc. et IN D /\ c IN D /\ dal IN D /\
               dc IN D /\ E et xi /\
               eapply D E g et c /\ eapply D E ff al dal /\
                             eapply D E ff c dc
                             ==> einter D E dal dc r)`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `(om:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[EOMEGA_IN]; ALL_TAC] THEN
  (* --- priors in a1 (from priors in A2 + A2 SUBSET a1) for EUSED --- *)
  SUBGOAL_THEN
   `!et. et IN D /\ E et xi ==> ?al:A. al IN D /\
    eapply D E g et al /\ E al a1`
   (LABEL_TAC "priorsA1") THENL
   [X_GEN_TAC `et:A` THEN STRIP_TAC THEN
    UNDISCH_TAC
     `!et. et IN D /\ (E:A->A->bool) et xi
           ==> ?al. al IN D /\ eapply D E g et al /\ E al A2` THEN
    DISCH_THEN(MP_TAC o SPEC `et:A`) THEN ASM_REWRITE_TAC[] THEN
    DISCH_THEN(X_CHOOSE_THEN `al:A` STRIP_ASSUME_TAC) THEN
    EXISTS_TAC `al:A` THEN ASM_REWRITE_TAC[] THEN
    UNDISCH_TAC `esubset D (E:A->A->bool) A2 a1` THEN REWRITE_TAC[esubset] THEN
    DISCH_THEN MATCH_MP_TAC THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* --- STEP 1: EUSED_COUNTABLE --- *)
  MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `om:A`; `a1:A`; `ii:A`; `ff:A`;
    `xi:A`; `g:A`] EUSED_COUNTABLE) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  INTRO_TAC "@ffg W. ffgD WD ffgprop Wchar Wcount" THEN
  (* --- ff(c) SUBSET W for priors c=g(et) --- *)
  SUBGOAL_THEN
   `!et c d. et IN D /\ c IN D /\ d IN D /\ (E:A->A->bool) et xi /\
             eapply D E g et c /\ eapply D E ff c d ==> esubset D E d W`
   (LABEL_TAC "ffcW") THENL
   [MAP_EVERY X_GEN_TAC [`et:A`; `c:A`; `d:A`] THEN STRIP_TAC THEN
    USE_THEN "ffgprop" (MP_TAC o SPEC `et:A`) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(X_CHOOSE_THEN `m:A` (X_CHOOSE_THEN `p:A` STRIP_ASSUME_TAC)) THEN
    SUBGOAL_THEN `(m:A) = c` SUBST_ALL_TAC THENL
    [ASM_MESON_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN `(p:A) = d` SUBST_ALL_TAC THENL
    [ASM_MESON_TAC[]; ALL_TAC] THEN
    REWRITE_TAC[esubset] THEN X_GEN_TAC `u:A` THEN STRIP_TAC THEN
    USE_THEN "Wchar" (MP_TAC o SPEC `u:A`) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    MAP_EVERY EXISTS_TAC [`et:A`; `d:A`] THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* --- STEP 2: Wr = (W INTER ii) \ r --- *)
  MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `W:A`; `ii:A`]
         EINTER_EXISTS) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_TAC `Wii:A`) THEN
  SUBGOAL_THEN `(Wii:A) IN D` (LABEL_TAC "WiiD") THENL
   [ASM_MESON_TAC[einter]; ALL_TAC] THEN
  MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `Wii:A`; `r:A`]
         EDIFF_EXISTS) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_TAC `Wr:A`) THEN
  SUBGOAL_THEN `(Wr:A) IN D` (LABEL_TAC "WrD") THENL
   [ASM_MESON_TAC[ediff]; ALL_TAC] THEN
  (* Wr char: E x Wr <=> E x W /\ E x ii /\ ~E x r *)
  SUBGOAL_THEN
   `!x. x IN D ==> ((E:A->A->bool) x Wr <=> E x W /\ E x ii /\ ~(E x r))`
   (LABEL_TAC "Wrchar") THENL
   [X_GEN_TAC `x:A` THEN DISCH_TAC THEN
    SUBGOAL_THEN `(E:A->A->bool) x Wr <=> E x Wii /\ ~(E x r)` SUBST1_TAC THENL
     [UNDISCH_TAC `ediff D (E:A->A->bool) Wii r Wr` THEN
      REWRITE_TAC[ediff] THEN ASM_MESON_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN `(E:A->A->bool) x Wii <=> E x W /\ E x ii` SUBST1_TAC THENL
     [UNDISCH_TAC `einter D (E:A->A->bool) W ii Wii` THEN
      ASM_SIMP_TAC[EINTER_CHAR]; ALL_TAC] THEN
    REWRITE_TAC[CONJ_ASSOC]; ALL_TAC] THEN
  (* --- STEP 3: Wr countable (restrict the W-injection to Wr SUBSET W) --- *)
  USE_THEN "Wcount" (X_CHOOSE_TAC `ew:A`) THEN
  SUBGOAL_THEN `!k. k IN D /\ (E:A->A->bool) k Wr ==> E k W`
    (LABEL_TAC "WrsubW") THENL
   [X_GEN_TAC `k:A` THEN STRIP_TAC THEN
    USE_THEN "Wrchar" (MP_TAC o SPEC `k:A`) THEN
    ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN(fun th -> MP_TAC(EQ_MP th (ASSUME `(E:A->A->bool) k Wr`))) THEN
    STRIP_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  SUBGOAL_THEN `?e. einj D (E:A->A->bool) e Wr om` (LABEL_TAC "Wrcount") THENL
   [MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `ew:A`; `W:A`; `om:A`; `Wr:A`;
      `om:A`] EINJ_RESTRICT_DOM) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
       [UNDISCH_TAC `einj D (E:A->A->bool) ew W om` THEN
        REWRITE_TAC[einj] THEN STRIP_TAC THEN FIRST_ASSUM ACCEPT_TAC;
        MAP_EVERY X_GEN_TAC [`k:A`; `t:A`] THEN STRIP_TAC THEN
        UNDISCH_TAC `einj D (E:A->A->bool) ew W om` THEN REWRITE_TAC[einj] THEN
        DISCH_THEN(MP_TAC o SPECL [`k:A`; `t:A`] o CONJUNCT1 o CONJUNCT2) THEN
        ASM_REWRITE_TAC[] THEN STRIP_TAC THEN FIRST_ASSUM ACCEPT_TAC];
      DISCH_THEN ACCEPT_TAC]; ALL_TAC] THEN
  (* Wr's members are in ii and not in r (clean lemma, avoids *)
  (* Wrchar-collapse) *)
  SUBGOAL_THEN `!x. x IN D /\ (E:A->A->bool) x Wr ==> E x ii /\ ~(E x r)`
   (LABEL_TAC "Wriir") THENL
   [X_GEN_TAC `x:A` THEN STRIP_TAC THEN
    USE_THEN "Wrchar" (fun wc ->
      MP_TAC(EQ_MP (MP (SPEC `x:A` wc) (ASSUME `(x:A) IN D`))
                   (ASSUME `(E:A->A->bool) x Wr`))) THEN
    STRIP_TAC THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* --- STEP 4: EBAD_COUNTABLE --- *)
  MP_TAC(MATCH_MP (ISPECL [`D:A->bool`; `E:A->A->bool`; `om:A`; `ii:A`; `r:A`;
            `A2:A`; `ff:A`; `Wr:A`] EBAD_COUNTABLE)
          (end_itlist CONJ
            [ASSUME `model D (E:A->A->bool) ZF_AX`;
             ASSUME `!u. u IN D ==> elmem D (E:A->A->bool) u`;
             ASSUME `eomega D (E:A->A->bool) om`;
             ASSUME `(ii:A) IN D`;
             ASSUME `(r:A) IN D`;
             ASSUME `(A2:A) IN D`;
             ASSUME `(ff:A) IN D`;
             ASSUME `(Wr:A) IN D`;
             ASSUME `!n z z'. n IN D /\ z IN D /\ z' IN D /\
                       eapply D (E:A->A->bool) ff n z /\ eapply D E ff n z'
                       ==> z = z'`;
             ASSUME `!x. x IN D /\ (E:A->A->bool) x Wr ==> E x ii /\ ~(E x r)`;
             ASSUME `?e. einj D (E:A->A->bool) e Wr om`;
             ASSUME `!x Y. x IN D /\ (E:A->A->bool) x ii /\
                     ~(E x r) /\ Y IN D /\
                       (!al. al IN D
                             ==> (E al Y <=>
                                  E al A2 /\ ?d. d IN D /\
                                    eapply D E ff al d /\ E x d))
                       ==> ?e. einj D E e Y om`])) THEN
  DISCH_THEN(X_CHOOSE_THEN `BAD:A` (CONJUNCTS_THEN2 (LABEL_TAC "BADD")
    (CONJUNCTS_THEN2 (LABEL_TAC "BADchar") (LABEL_TAC "BADcount")))) THEN
  (* --- STEP 5: chosen = range-set of g, countable --- *)
  MP_TAC(MATCH_MP (ISPECL [`D:A->bool`; `E:A->A->bool`; `om:A`; `a1:A`; `xi:A`]
            ECOUNTABLE_BELOW_A1)
          (end_itlist CONJ
            [ASSUME `model D (E:A->A->bool) ZF_AX`;
             ASSUME `!u. u IN D ==> elmem D (E:A->A->bool) u`;
             ASSUME `eomega D (E:A->A->bool) om`;
             ASSUME `(a1:A) IN D`;
             ASSUME `ecardinal D (E:A->A->bool) a1`;
             ASSUME `(E:A->A->bool) om a1`;
             ASSUME `!c'. c' IN D /\ (E:A->A->bool) c' a1
                          ==> ~(ecardinal D E c' /\ E om c')`;
             ASSUME `(xi:A) IN D`;
             ASSUME `(E:A->A->bool) xi a1`])) THEN
  DISCH_THEN(X_CHOOSE_TAC `exi:A`) THEN
  MP_TAC(MATCH_MP
         (ISPECL [`D:A->bool`; `E:A->A->bool`; `g:A`] EINRAN_SET_EXISTS)
         (CONJ (ASSUME `model D (E:A->A->bool) ZF_AX`)
                (ASSUME `(g:A) IN D`))) THEN
  DISCH_THEN(X_CHOOSE_THEN `chosen:A` STRIP_ASSUME_TAC) THEN
  SUBGOAL_THEN
   `!z. z IN D ==>
    ((E:A->A->bool) z chosen <=> ?k. k IN D /\ E k xi /\ eapply D E g k z)`
   (LABEL_TAC "chosenchar") THENL
   [X_GEN_TAC `z:A` THEN DISCH_TAC THEN
    MP_TAC(MP (SPEC `z:A` (ASSUME
                `!w. w IN D ==> ((E:A->A->bool) w chosen <=> einran D E w g)`))
              (ASSUME `(z:A) IN D`)) THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    REWRITE_TAC[einran] THEN EQ_TAC THENL
     [DISCH_THEN(X_CHOOSE_THEN `pr:A`
                 (X_CHOOSE_THEN `oo:A` STRIP_ASSUME_TAC)) THEN
      EXISTS_TAC `oo:A` THEN
      SUBGOAL_THEN `eapply D (E:A->A->bool) g oo z` ASSUME_TAC THENL
       [REWRITE_TAC[eapply] THEN EXISTS_TAC `pr:A` THEN ASM_REWRITE_TAC[];
        ALL_TAC] THEN
      ASM_REWRITE_TAC[] THEN
      ACCEPT_TAC(MP (SPECL [`oo:A`; `z:A`] (ASSUME
                  `!k z. k IN D /\ z IN D /\
                   eapply D (E:A->A->bool) g k z ==> E k xi`))
                (CONJ (ASSUME `(oo:A) IN D`)
                      (CONJ (ASSUME `(z:A) IN D`)
                            (ASSUME `eapply D (E:A->A->bool) g oo z`))));
      DISCH_THEN(X_CHOOSE_THEN `k:A` STRIP_ASSUME_TAC) THEN
      UNDISCH_TAC `eapply D (E:A->A->bool) g k z` THEN REWRITE_TAC[eapply] THEN
      DISCH_THEN(X_CHOOSE_THEN `zz:A` STRIP_ASSUME_TAC) THEN
      SUBGOAL_THEN `(zz:A) IN D` ASSUME_TAC THENL
       [FIRST_ASSUM(ACCEPT_TAC o MATCH_MP EOPAIR_IN); ALL_TAC] THEN
      MAP_EVERY EXISTS_TAC [`zz:A`; `k:A`] THEN ASM_REWRITE_TAC[]];
     ALL_TAC] THEN
  SUBGOAL_THEN `?e. einj D (E:A->A->bool) e chosen om`
    (LABEL_TAC "chosencount") THENL
   [MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `om:A`; `xi:A`; `exi:A`; `g:A`;
      `chosen:A`] EFUNIMAGE_CARD_LE) THEN
    ANTS_TAC THENL
     [REPEAT CONJ_TAC THEN TRY(MATCH_MP_TAC EOMEGA_ORDINAL) THEN
      ASM_REWRITE_TAC[];
      DISCH_THEN ACCEPT_TAC]; ALL_TAC] THEN
  (* --- STEP 6: ESURVIVOR -> good survivor al --- *)
  MP_TAC(ISPECL
         [`D:A->bool`; `E:A->A->bool`; `om:A`; `A2:A`; `BAD:A`; `chosen:A`]
         ESURVIVOR) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  INTRO_TAC "@al. alD alA2 alnBAD alnchosen" THEN
  EXISTS_TAC `al:A` THEN REPEAT CONJ_TAC THENL
   [USE_THEN "alD" ACCEPT_TAC;
    USE_THEN "alA2" ACCEPT_TAC;
    (* fresh: al =/= every prior g(et) *)
    MAP_EVERY X_GEN_TAC [`et:A`; `c:A`] THEN STRIP_TAC THEN
    DISCH_THEN SUBST_ALL_TAC THEN
    UNDISCH_TAC `~((E:A->A->bool) al chosen)` THEN REWRITE_TAC[] THEN
    USE_THEN "chosenchar" (fun cc ->
      MP_TAC(MP (SPEC `al:A` cc) (ASSUME `(al:A) IN D`))) THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    EXISTS_TAC `et:A` THEN ASM_REWRITE_TAC[];
    (* sunflower: einter (ff al) (ff (g et)) r *)
    MAP_EVERY X_GEN_TAC [`et:A`; `c:A`; `dal:A`; `dc:A`] THEN STRIP_TAC THEN
    (* c IN A2 (c=g(et), prior) *)
    SUBGOAL_THEN `(E:A->A->bool) c A2` (LABEL_TAC "cA2") THENL
     [UNDISCH_TAC `!et. et IN D /\ E et xi
                        ==> ?al. al IN D /\ eapply D (E:A->A->bool) g et al /\
                          E al A2` THEN
      DISCH_THEN(MP_TAC o SPEC `et:A`) THEN ASM_REWRITE_TAC[] THEN
      DISCH_THEN(X_CHOOSE_THEN `al':A` STRIP_ASSUME_TAC) THEN
      SUBGOAL_THEN `(al':A) = c` SUBST_ALL_TAC THENL
       [UNDISCH_TAC `!n z z'. n IN D /\ z IN D /\ z' IN D /\
                       eapply D (E:A->A->bool) g n z /\ eapply D E g n z' ==>
                         z = z'` THEN
        DISCH_THEN MATCH_MP_TAC THEN EXISTS_TAC `et:A` THEN ASM_REWRITE_TAC[];
        FIRST_ASSUM ACCEPT_TAC]; ALL_TAC] THEN
    (* r SUBSET dal (=ff al), r SUBSET dc (=ff c) via petals *)
    SUBGOAL_THEN `esubset D (E:A->A->bool) r dal` (LABEL_TAC "rdal") THENL
     [UNDISCH_TAC `!al. al IN D /\ E al A2
                        ==> ?d. d IN D /\ eapply D (E:A->A->bool) ff al d /\
                          esubset D E r d` THEN
      DISCH_THEN(MP_TAC o SPEC `al:A`) THEN ASM_REWRITE_TAC[] THEN
      DISCH_THEN(X_CHOOSE_THEN `d:A` STRIP_ASSUME_TAC) THEN
      SUBGOAL_THEN `(d:A) = dal` (fun th -> ASM_MESON_TAC[th]) THEN
      UNDISCH_TAC `!n z z'. n IN D /\ z IN D /\ z' IN D /\
                    eapply D (E:A->A->bool) ff n z /\ eapply D E ff n z' ==>
                      z = z'` THEN
      DISCH_THEN MATCH_MP_TAC THEN EXISTS_TAC `al:A` THEN ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    SUBGOAL_THEN `esubset D (E:A->A->bool) r dc` (LABEL_TAC "rdc") THENL
     [UNDISCH_TAC `!al. al IN D /\ E al A2
                        ==> ?d. d IN D /\ eapply D (E:A->A->bool) ff al d /\
                          esubset D E r d` THEN
      DISCH_THEN(MP_TAC o SPEC `c:A`) THEN ASM_REWRITE_TAC[] THEN
      DISCH_THEN(X_CHOOSE_THEN `d:A` STRIP_ASSUME_TAC) THEN
      SUBGOAL_THEN `(d:A) = dc` (fun th -> ASM_MESON_TAC[th]) THEN
      UNDISCH_TAC `!n z z'. n IN D /\ z IN D /\ z' IN D /\
                    eapply D (E:A->A->bool) ff n z /\ eapply D E ff n z' ==>
                      z = z'` THEN
      DISCH_THEN MATCH_MP_TAC THEN EXISTS_TAC `c:A` THEN ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    (* dc SUBSET W (=ffcW) *)
    SUBGOAL_THEN `esubset D (E:A->A->bool) dc W` (LABEL_TAC "dcW") THENL
     [USE_THEN "ffcW" (fun th ->
        MATCH_MP_TAC(ISPECL [`et:A`; `c:A`; `dc:A`] th)) THEN
      ASM_REWRITE_TAC[]; ALL_TAC] THEN
    (* dc SUBSET ii (ff-premise, c IN a1) *)
    SUBGOAL_THEN `esubset D (E:A->A->bool) dc ii` (LABEL_TAC "dcii") THENL
     [UNDISCH_TAC `!b. b IN D /\ E b a1
                       ==> ?d. d IN D /\ eapply D (E:A->A->bool) ff b d /\
                               efin D E d /\ esubset D E d ii` THEN
      DISCH_THEN(MP_TAC o SPEC `c:A`) THEN
      SUBGOAL_THEN `(E:A->A->bool) c a1` ASSUME_TAC THENL
       [UNDISCH_TAC `esubset D (E:A->A->bool) A2 a1` THEN
        REWRITE_TAC[esubset] THEN
        DISCH_THEN MATCH_MP_TAC THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
      ASM_REWRITE_TAC[] THEN
      DISCH_THEN(X_CHOOSE_THEN `d:A` STRIP_ASSUME_TAC) THEN
      SUBGOAL_THEN `(d:A) = dc` SUBST_ALL_TAC THENL
       [UNDISCH_TAC `!n z z'. n IN D /\ z IN D /\ z' IN D /\
                      eapply D (E:A->A->bool) ff n z /\ eapply D E ff n z' ==>
                        z = z'` THEN
        DISCH_THEN MATCH_MP_TAC THEN EXISTS_TAC `c:A` THEN ASM_REWRITE_TAC[];
        ALL_TAC] THEN
      FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    (* now einter dal dc r via EINTER_CHAR *)
    MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `dal:A`; `dc:A`; `r:A`]
      EINTER_CHAR) THEN ASM_REWRITE_TAC[] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    X_GEN_TAC `m:A` THEN DISCH_TAC THEN EQ_TAC THENL
     [DISCH_TAC THEN CONJ_TAC THENL
       [UNDISCH_TAC `esubset D (E:A->A->bool) r dal` THEN
        REWRITE_TAC[esubset] THEN
        DISCH_THEN MATCH_MP_TAC THEN ASM_REWRITE_TAC[];
        UNDISCH_TAC `esubset D (E:A->A->bool) r dc` THEN
        REWRITE_TAC[esubset] THEN
        DISCH_THEN MATCH_MP_TAC THEN ASM_REWRITE_TAC[]];
      STRIP_TAC THEN
      (* ~E m r ==> m IN Wr /\ m IN dal ==> al IN BAD, contra alnBAD *)
      ASM_CASES_TAC `(E:A->A->bool) m r` THENL
      [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      SUBGOAL_THEN `(E:A->A->bool) m Wr` (LABEL_TAC "mWr") THENL
       [USE_THEN "Wrchar" (fun wc ->
          MP_TAC(MP (SPEC `m:A` wc) (ASSUME `(m:A) IN D`))) THEN
        DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
        REPEAT CONJ_TAC THENL
         [UNDISCH_TAC `esubset D (E:A->A->bool) dc W` THEN
          REWRITE_TAC[esubset] THEN
          DISCH_THEN MATCH_MP_TAC THEN ASM_REWRITE_TAC[];
          UNDISCH_TAC `esubset D (E:A->A->bool) dc ii` THEN
          REWRITE_TAC[esubset] THEN
          DISCH_THEN MATCH_MP_TAC THEN ASM_REWRITE_TAC[];
          FIRST_ASSUM ACCEPT_TAC]; ALL_TAC] THEN
      SUBGOAL_THEN `(E:A->A->bool) al BAD`
       (fun th -> UNDISCH_TAC `~((E:A->A->bool) al BAD)` THEN
        REWRITE_TAC[th]) THEN
      USE_THEN "BADchar" (fun bc ->
        MP_TAC(MP (SPEC `al:A` bc) (ASSUME `(al:A) IN D`))) THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
      USE_THEN "alA2" (fun th -> REWRITE_TAC[th]) THEN
      EXISTS_TAC `m:A` THEN REPEAT CONJ_TAC THENL
       [ASM_REWRITE_TAC[]; USE_THEN "mWr" ACCEPT_TAC; ALL_TAC] THEN
      EXISTS_TAC `dal:A` THEN ASM_REWRITE_TAC[]]]);;

(* ==== F6.2 s3 (D5) : EDELTAREC_INA2 =====================================
   The delta recursion value always lands in A2=(v 4): h(a) IN A2 for every
   ordinal a.  Trivial -- by DELTASTEP_HOLDS the value y is the ra-least member
   of G, and every G-member satisfies the ggpred, whose BOTH disjuncts require
   E _ (v 4).  So E y (v 4).  No induction,
   no GOODSET_NONEMPTY (that is consumed
   later in D6 to show h is GOOD, not merely in A2). *)

let EDELTAREC_INA2 = prove
 (`!D (E:A->A->bool) v s ya.
      model D E ZF_AX /\ valuation D v /\
      s IN D /\ (v 2) IN D /\ ya IN D /\
      elwoinvu D E s /\ elwou D E s (v 2) /\ elstage D E s ya /\
      (v 4) IN D /\ (!t. t IN D /\ E t (v 4) ==> E t ya) /\
      (?a. a IN D /\ E a (v 4))
      ==> !a y. eordinal D E a /\ y IN D /\ erec D E deltastep_form v a y
                ==> E y (v 4)`,
  REPEAT GEN_TAC THEN DISCH_THEN(REPEAT_TCL CONJUNCTS_THEN ASSUME_TAC) THEN
  MAP_EVERY X_GEN_TAC [`a:A`; `y:A`] THEN STRIP_TAC THEN
  (* graph r_a *)
  MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `v:num->A`; `s:A`; `ya:A`]
    EDELTAREC_RESEXISTS) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(MP_TAC o SPEC `a:A`) THEN
  ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_TAC `r:A`) THEN
  SUBGOAL_THEN `(r:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[erecres]; ALL_TAC] THEN
  (* holds((1|->y)((0|->r)v)) deltastep via EREC_EQUATION *)
  (* (QFUN=EDELTASTEP_QFUN) *)
  SUBGOAL_THEN
   `holds D (E:A->A->bool) ((1 |-> y) ((0 |-> r) v)) deltastep_form`
     ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`; `E:A->A->bool`; `deltastep_form`; `v:num->A`;
                  `a:A`; `y:A`; `r:A`] EREC_EQUATION) THEN
    ASM_REWRITE_TAC[] THEN
    MATCH_MP_TAC(ISPECL
                 [`D:A->bool`; `E:A->A->bool`; `v:num->A`; `s:A`; `ya:A`]
                 EDELTASTEP_QFUN) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* DELTASTEP_HOLDS -> ?G. ... E y G ... *)
  MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `v:num->A`; `r:A`; `y:A`]
    DELTASTEP_HOLDS) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(fun th ->
    MP_TAC(EQ_MP th (ASSUME
      `holds D (E:A->A->bool) ((1 |-> y) ((0 |-> r) v)) deltastep_form`))) THEN
  DISCH_THEN(X_CHOOSE_THEN `G:A` (CONJUNCTS_THEN2 (LABEL_TAC "GD")
    (CONJUNCTS_THEN2 (LABEL_TAC "Gchar") (CONJUNCTS_THEN2 (LABEL_TAC "EyG")
      (K ALL_TAC))))) THEN
  (* Gchar y + E y G ==> disjunction, both disjuncts give E y (v 4) *)
  USE_THEN "Gchar" (MP_TAC o SPEC `y:A`) THEN
  ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  USE_THEN "EyG" (fun eyg -> DISCH_THEN(fun iff -> MP_TAC(EQ_MP iff eyg))) THEN
  MESON_TAC[]);;

(* ==== F6.2 s3 (D6 helper) : ERECRES_ISFUN ================================
   The erecres graph r = {<b,F(b)> : b<a} is a functional set (eisfun): every
   member is an opair (from erecres's char) and it is single-valued (EOPAIR_INJ
   pins the first component, EREC_UNIQUE pins the value).  Needed to feed
   GOODSET_NONEMPTY (which wants eisfun g) with g := r_xi in EDELTAREC_GOOD. *)

let ERECRES_ISFUN = prove
 (`!D (E:A->A->bool) q v a r.
     model D E ZF_AX /\ valuation D v /\
     (!rr w w'. rr IN D /\ w IN D /\ w' IN D /\
                holds D E ((1 |-> w) ((0 |-> rr) v)) q /\
                holds D E ((1 |-> w') ((0 |-> rr) v)) q ==> w = w') /\
     erecres D E q v a r
     ==> eisfun D E r`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  FIRST_ASSUM(MP_TAC o GEN_REWRITE_RULE I [erecres]) THEN
  DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "rD") (LABEL_TAC "rchar")) THEN
  REWRITE_TAC[eisfun] THEN
  CONJ_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN CONJ_TAC THENL
   [(* every member of r is an opair *)
    X_GEN_TAC `z:A` THEN STRIP_TAC THEN
    USE_THEN "rchar" (MP_TAC o SPEC `z:A`) THEN
    ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN(fun iff -> MP_TAC(EQ_MP iff (ASSUME `(E:A->A->bool) z r`))) THEN
    DISCH_THEN(X_CHOOSE_THEN `b:A` (X_CHOOSE_THEN `y:A` STRIP_ASSUME_TAC)) THEN
    MAP_EVERY EXISTS_TAC [`b:A`; `y:A`] THEN ASM_REWRITE_TAC[];
    (* single-valued: eapply r u w /\ eapply r u w' ==>
      erec v u w /\ erec v u w'
      (ERECRES_APPLY) ==> w = w' (EREC_UNIQUE) *)
    MAP_EVERY X_GEN_TAC [`u:A`; `w:A`; `w':A`; `z:A`; `z':A`] THEN
    STRIP_TAC THEN
    SUBGOAL_THEN `eapply D (E:A->A->bool) r u w` (LABEL_TAC "eapw") THENL
     [REWRITE_TAC[eapply] THEN EXISTS_TAC `z:A` THEN ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    SUBGOAL_THEN `eapply D (E:A->A->bool) r u w'` (LABEL_TAC "eapw'") THENL
     [REWRITE_TAC[eapply] THEN EXISTS_TAC `z':A` THEN ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    MP_TAC(ISPECL
           [`D:A->bool`; `E:A->A->bool`; `q:form`; `v:num->A`; `a:A`; `r:A`;
            `u:A`; `w:A`] ERECRES_APPLY) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    USE_THEN "eapw"
      (fun ea -> DISCH_THEN(fun iff -> MP_TAC(EQ_MP iff ea))) THEN
      STRIP_TAC THEN
    MP_TAC(ISPECL
           [`D:A->bool`; `E:A->A->bool`; `q:form`; `v:num->A`; `a:A`; `r:A`;
            `u:A`; `w':A`] ERECRES_APPLY) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    USE_THEN "eapw'"
      (fun ea -> DISCH_THEN(fun iff -> MP_TAC(EQ_MP iff ea))) THEN
      STRIP_TAC THEN
    MATCH_MP_TAC(ISPECL
                 [`D:A->bool`; `E:A->A->bool`; `q:form`; `v:num->A`; `u:A`;
                  `w:A`; `w':A`] EREC_UNIQUE) THEN ASM_REWRITE_TAC[]]);;

(* ==== F6.2 s3 (D6 CRUX) : EDELTAREC_GOOD =================================
   For xi<a1,
   the recursion value h(xi) is GOOD: distinct from every prior h(eta)
   (eta<xi) and forming a sunflower einter (ff h(xi)) (ff h(eta)) r with it.
   PROOF: graph r_xi; DELTASTEP_HOLDS gives h(xi) IN G;
   GOODSET_NONEMPTY (eisfun
   r_xi via ERECRES_ISFUN, priors IN A2 via EDELTAREC_INA2, graph<->erec via
   ERECRES_APPLY) yields a GOOD witness al, which refutes G's no-good disjunct,
   so h(xi) itself is good; instantiate good(h(xi)) at c:=h(eta).
   The proof below follows this decomposition directly. *)

let EDELTAREC_GOOD = prove
 (`!D (E:A->A->bool) v s ya om a1 ii ff r A2 xi eta hxi heta.
     model D E ZF_AX /\ (!u. u IN D ==> elmem D E u) /\
     valuation D v /\
     eomega D E om /\ a1 IN D /\ ecardinal D E a1 /\ E om a1 /\
     (!c'. c' IN D /\ E c' a1 ==> ~(ecardinal D E c' /\ E om c')) /\
     ii IN D /\ ff IN D /\ r IN D /\ A2 IN D /\
     (!n z z'. n IN D /\ z IN D /\ z' IN D /\
               eapply D E ff n z /\ eapply D E ff n z' ==> z = z') /\
     (!b. b IN D /\ E b a1
          ==> ?d. d IN D /\ eapply D E ff b d /\ efin D E d /\
            esubset D E d ii) /\
     esubset D E r ii /\ esubset D E A2 a1 /\ ~(?e. einj D E e A2 om) /\
     (!al. al IN D /\ E al A2 ==> ?d. d IN D /\ eapply D E ff al d /\
      esubset D E r d) /\
     (!x Y. x IN D /\ E x ii /\ ~(E x r) /\ Y IN D /\
            (!al. al IN D
                  ==> (E al Y <=>
                       E al A2 /\ ?d. d IN D /\ eapply D E ff al d /\ E x d))
            ==> ?e. einj D E e Y om) /\
     s IN D /\ (v 2) IN D /\ ya IN D /\
     elwoinvu D E s /\ elwou D E s (v 2) /\ elstage D E s ya /\
     (!t. t IN D /\ E t A2 ==> E t ya) /\
     v 3 = ff /\ v 4 = A2 /\ v 5 = r /\
     eordinal D E xi /\ E xi a1 /\ eordinal D E eta /\ E eta xi /\
     hxi IN D /\ heta IN D /\
     erec D E deltastep_form v xi hxi /\ erec D E deltastep_form v eta heta
     ==> ~(hxi = heta) /\
         (!dx de. dx IN D /\ de IN D /\
                  eapply D E ff hxi dx /\ eapply D E ff heta de
                  ==> einter D E dx de r)`,
  REPEAT GEN_TAC THEN DISCH_THEN(REPEAT_TCL CONJUNCTS_THEN ASSUME_TAC) THEN
  (* labelled copies of the two unlabelled hyps used in C+D *)
  SUBGOAL_THEN
   `!n z z'. n IN D /\ z IN D /\ z' IN D /\
             eapply D (E:A->A->bool) ff n z /\ eapply D E ff n z' ==> z = z'`
   (LABEL_TAC "ffsv") THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  SUBGOAL_THEN
   `!al. al IN D /\ E al A2
         ==> ?d. d IN D /\ eapply D (E:A->A->bool) ff al d /\ esubset D E r d`
   (LABEL_TAC "petals") THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  (* QFUN *)
  SUBGOAL_THEN
   `!rr w w'. rr IN D /\ w IN D /\ w' IN D /\
              holds D (E:A->A->bool) ((1 |-> w) ((0 |-> rr) v))
                deltastep_form /\
              holds D E ((1 |-> w') ((0 |-> rr) v)) deltastep_form ==> w = w'`
   (LABEL_TAC "QFUN") THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`; `E:A->A->bool`; `v:num->A`; `s:A`; `ya:A`]
                 EDELTASTEP_QFUN) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* A2 nonempty *)
  SUBGOAL_THEN `?aa. aa IN D /\ (E:A->A->bool) aa A2` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `om:A`; `A2:A`]
      EUNCOUNTABLE_NONEMPTY) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* graph r_xi *)
  SUBGOAL_THEN `?rxi. erecres D (E:A->A->bool) deltastep_form v xi rxi`
   (X_CHOOSE_TAC `rxi:A`) THENL
   [MP_TAC(REWRITE_RULE [ASSUME `(v:num->A) 4 = A2`]
       (ISPECL [`D:A->bool`; `E:A->A->bool`; `v:num->A`; `s:A`; `ya:A`]
          EDELTAREC_RESEXISTS)) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN MATCH_MP_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  SUBGOAL_THEN `(rxi:A) IN D` ASSUME_TAC THENL
   [FIRST_ASSUM(ACCEPT_TAC o CONJUNCT1 o REWRITE_RULE[erecres]); ALL_TAC] THEN
  (* holds hxi at graph *)
  SUBGOAL_THEN
   `holds D (E:A->A->bool) ((1 |-> hxi) ((0 |-> rxi) v)) deltastep_form`
   ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`; `E:A->A->bool`; `deltastep_form`; `v:num->A`;
                  `xi:A`; `hxi:A`; `rxi:A`] EREC_EQUATION) THEN
    ASM_REWRITE_TAC[] THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  (* DELTASTEP_HOLDS -> G, Gchar, E hxi G *)
  MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `v:num->A`; `rxi:A`; `hxi:A`]
    DELTASTEP_HOLDS) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(fun th ->
    MP_TAC(EQ_MP th (ASSUME
      `holds D (E:A->A->bool) ((1 |-> hxi) ((0 |-> rxi) v))
       deltastep_form`))) THEN
  DISCH_THEN(X_CHOOSE_THEN `G:A` (CONJUNCTS_THEN2 (LABEL_TAC "GD")
    (CONJUNCTS_THEN2 (LABEL_TAC "Gchar") (CONJUNCTS_THEN2 (LABEL_TAC "EhxiG")
      (K ALL_TAC))))) THEN
  (* r_xi single-valued / domain / priors (for GOODSET_NONEMPTY) *)
  SUBGOAL_THEN
   `!n z z'. n IN D /\ z IN D /\ z' IN D /\
             eapply D (E:A->A->bool) rxi n z /\ eapply D E rxi n z' ==> z = z'`
   (LABEL_TAC "rxisv") THENL
   [MAP_EVERY X_GEN_TAC [`n:A`; `z:A`; `z':A`] THEN STRIP_TAC THEN
    MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `deltastep_form`; `v:num->A`;
      `xi:A`; `rxi:A`; `n:A`; `z:A`] ERECRES_APPLY) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun iff ->
               MP_TAC(EQ_MP iff
                      (ASSUME `eapply D (E:A->A->bool) rxi n z`))) THEN
    STRIP_TAC THEN
    MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `deltastep_form`; `v:num->A`;
      `xi:A`; `rxi:A`; `n:A`; `z':A`] ERECRES_APPLY) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun iff ->
               MP_TAC(EQ_MP iff
                      (ASSUME `eapply D (E:A->A->bool) rxi n z'`))) THEN
    STRIP_TAC THEN
    MATCH_MP_TAC(ISPECL
                 [`D:A->bool`; `E:A->A->bool`; `deltastep_form`; `v:num->A`;
                  `n:A`; `z:A`; `z':A`] EREC_UNIQUE) THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
    `!k z. k IN D /\ z IN D /\ eapply D (E:A->A->bool) rxi k z ==> E k xi`
   (LABEL_TAC "rxidom") THENL
   [MAP_EVERY X_GEN_TAC [`k:A`; `z:A`] THEN STRIP_TAC THEN
    MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `deltastep_form`; `v:num->A`;
      `xi:A`; `rxi:A`; `k:A`; `z:A`] ERECRES_APPLY) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun iff ->
               MP_TAC(EQ_MP iff
                      (ASSUME `eapply D (E:A->A->bool) rxi k z`))) THEN
    STRIP_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  SUBGOAL_THEN
   `!et. et IN D /\ (E:A->A->bool) et xi
         ==> ?al. al IN D /\ eapply D E rxi et al /\ E al A2`
   (LABEL_TAC "rxipriors") THENL
   [X_GEN_TAC `et:A` THEN STRIP_TAC THEN
    SUBGOAL_THEN `eordinal D (E:A->A->bool) et` ASSUME_TAC THENL
     [MATCH_MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `xi:A`; `et:A`]
        EORDINAL_MEMBER) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN `?y. y IN D /\ erec D (E:A->A->bool) deltastep_form v et y`
     (X_CHOOSE_THEN `yet:A` STRIP_ASSUME_TAC) THENL
     [MP_TAC(REWRITE_RULE [ASSUME `(v:num->A) 4 = A2`]
         (ISPECL [`D:A->bool`; `E:A->A->bool`; `v:num->A`; `s:A`; `ya:A`]
            EDELTAREC_EXISTS)) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN MATCH_MP_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    EXISTS_TAC `yet:A` THEN ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
     [MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `deltastep_form`; `v:num->A`;
        `xi:A`; `rxi:A`; `et:A`; `yet:A`] ERECRES_APPLY) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN ASM_REWRITE_TAC[];
      MP_TAC(REWRITE_RULE [ASSUME `(v:num->A) 4 = A2`]
          (ISPECL [`D:A->bool`; `E:A->A->bool`; `v:num->A`; `s:A`; `ya:A`]
             EDELTAREC_INA2)) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(MP_TAC o SPECL [`et:A`; `yet:A`]) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC]]; ALL_TAC] THEN
  (* GOODSET_NONEMPTY(r_xi) -> good witness al *)
  MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `om:A`; `a1:A`; `ii:A`; `ff:A`;
    `r:A`; `A2:A`; `xi:A`; `rxi:A`] GOODSET_NONEMPTY) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
     [FIRST_ASSUM(ACCEPT_TAC o MATCH_MP EORDINAL_IN);
      MATCH_MP_TAC(ISPECL
                   [`D:A->bool`; `E:A->A->bool`; `deltastep_form`; `v:num->A`;
                    `xi:A`; `rxi:A`] ERECRES_ISFUN) THEN ASM_REWRITE_TAC[]];
     ALL_TAC] THEN
  INTRO_TAC "@al. alD alA2 alfresh alsun" THEN
  (* --- Phase C: normalise Gchar to ff/A2/r; build good(al); refute no-good *)
  (* --- *)
  RULE_ASSUM_TAC(REWRITE_RULE [ASSUME `(v:num->A) 3 = ff`;
    ASSUME `(v:num->A) 4 = A2`; ASSUME `(v:num->A) 5 = r`]) THEN
  SUBGOAL_THEN
   `!c. c IN D
        ==> ((?et. et IN D /\ eapply D (E:A->A->bool) rxi et c)
             ==> ~(al = c) /\
                 (?fx. fx IN D /\ ?fc. fc IN D /\
                       eapply D E ff al fx /\ eapply D E ff c fc /\
                         einter D E fx fc r))`
   (LABEL_TAC "goodal") THENL
   [X_GEN_TAC `c:A` THEN DISCH_TAC THEN
    DISCH_THEN(X_CHOOSE_THEN `et:A` STRIP_ASSUME_TAC) THEN
    SUBGOAL_THEN `(E:A->A->bool) et xi` ASSUME_TAC THENL
     [USE_THEN "rxidom" (MP_TAC o SPECL [`et:A`; `c:A`]) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC]; ALL_TAC] THEN
    SUBGOAL_THEN `(E:A->A->bool) c A2` ASSUME_TAC THENL
     [USE_THEN "rxipriors" (MP_TAC o SPEC `et:A`) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(X_CHOOSE_THEN `cc:A` STRIP_ASSUME_TAC) THEN
      SUBGOAL_THEN `(cc:A) = c` SUBST_ALL_TAC THENL
       [USE_THEN "rxisv" (MP_TAC o SPECL [`et:A`; `cc:A`; `c:A`]) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC];
        ALL_TAC] THEN
      FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    SUBGOAL_THEN
      `?d. d IN D /\ eapply D (E:A->A->bool) ff al d /\ esubset D E r d`
      (X_CHOOSE_THEN `dal:A` STRIP_ASSUME_TAC) THENL
     [USE_THEN "petals" MATCH_MP_TAC THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN
      `?d. d IN D /\ eapply D (E:A->A->bool) ff c d /\ esubset D E r d`
      (X_CHOOSE_THEN `dc:A` STRIP_ASSUME_TAC) THENL
     [USE_THEN "petals" MATCH_MP_TAC THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    CONJ_TAC THENL
     [USE_THEN "alfresh" (MP_TAC o SPECL [`et:A`; `c:A`]) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_TAC THEN ONCE_REWRITE_TAC[EQ_SYM_EQ] THEN FIRST_ASSUM ACCEPT_TAC;
      EXISTS_TAC `dal:A` THEN ASM_REWRITE_TAC[] THEN
      EXISTS_TAC `dc:A` THEN ASM_REWRITE_TAC[] THEN
      USE_THEN "alsun" (MP_TAC o SPECL [`et:A`; `c:A`; `dal:A`; `dc:A`]) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC]]; ALL_TAC] THEN
  (* Gchar@hxi + E hxi G -> disjunction; DISJ_CASES *)
  USE_THEN "Gchar" (MP_TAC o SPEC `hxi:A`) THEN
  ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  USE_THEN "EhxiG" (fun eh -> DISCH_THEN(fun iff -> MP_TAC(EQ_MP iff eh))) THEN
  DISCH_THEN(DISJ_CASES_THEN2
    (CONJUNCTS_THEN2 (K ALL_TAC) (LABEL_TAC "goodhxi"))
    (CONJUNCTS_THEN2 (K ALL_TAC) (LABEL_TAC "nogood"))) THENL
   [(* --- Phase D: apply good(hxi) at c := heta --- *)
    USE_THEN "goodhxi" (MP_TAC o SPEC `heta:A`) THEN
    ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    ANTS_TAC THENL
     [EXISTS_TAC `eta:A` THEN CONJ_TAC THENL
       [FIRST_ASSUM(ACCEPT_TAC o MATCH_MP EORDINAL_IN o
          check(fun th -> rand(concl th) = `eta:A`)); ALL_TAC] THEN
      MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `deltastep_form`; `v:num->A`;
        `xi:A`; `rxi:A`; `eta:A`; `heta:A`] ERECRES_APPLY) THEN
      ANTS_TAC THENL
       [ASM_REWRITE_TAC[] THEN REPEAT CONJ_TAC THEN
        TRY(FIRST_ASSUM(ACCEPT_TAC o MATCH_MP EORDINAL_IN o
              check(fun th -> rand(concl th) = `xi:A`))) THEN
        TRY(FIRST_ASSUM(ACCEPT_TAC o MATCH_MP EORDINAL_IN o
              check(fun th -> rand(concl th) = `eta:A`))) THEN
        FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "hne")
      (X_CHOOSE_THEN `fx:A` (CONJUNCTS_THEN2 ASSUME_TAC
         (X_CHOOSE_THEN `fc:A` STRIP_ASSUME_TAC)))) THEN
    CONJ_TAC THENL
     [USE_THEN "hne" ACCEPT_TAC;
      MAP_EVERY X_GEN_TAC [`dx:A`; `de:A`] THEN STRIP_TAC THEN
      SUBGOAL_THEN `(fx:A) = dx` SUBST_ALL_TAC THENL
       [USE_THEN "ffsv" (MP_TAC o SPECL [`hxi:A`; `fx:A`; `dx:A`]) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC];
        ALL_TAC] THEN
      SUBGOAL_THEN `(fc:A) = de` SUBST_ALL_TAC THENL
       [USE_THEN "ffsv" (MP_TAC o SPECL [`heta:A`; `fc:A`; `de:A`]) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC];
        ALL_TAC] THEN
      FIRST_ASSUM ACCEPT_TAC];
    (* case no-good: contradiction via good(al) *)
    USE_THEN "nogood" (MP_TAC o SPEC `al:A`) THEN
    ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    USE_THEN "alA2" (fun a2 -> USE_THEN "goodal" (fun gl ->
      DISCH_THEN(fun neg -> MP_TAC(MP (NOT_ELIM neg) (CONJ a2 gl))))) THEN
    REWRITE_TAC[]]);;

(* ==== F6.2 s3 (D6 ASSEMBLY) : EDELTA_RECURSION =========================
   Given r,A2 (from EDELTA_ROOT), run the delta recursion over a1 and take
   jj = range of the graph = {h(xi):xi<a1}: jj SUBSET A2, jj uncountable
   (h injective), pairwise einter (ff .)(ff .) = r.  Sets up the L-wellorder
   internally (STAGE_PIN at {A2}) + valmod tower vv[2=ra,3=ff,4=A2,5=r].
   COMPLETE: setup+graph+jj+jjSUBSETA2; einj r_a1 a1 jj + ~einj jj om
   (rinj+EINJ_COMPOSE+EUNCOUNTABLE_CARD); pairwise einter=r
   (jjelt+EORDINAL_TRICHOTOMY+GOOD, einter symmetry via EINTER_CHAR twice). *)

let EDELTA_RECURSION = prove
 (`!D (E:A->A->bool) om a1 ii ff r A2.
     model D E ZF_AX /\ (!u. u IN D ==> elmem D E u) /\
     eomega D E om /\ a1 IN D /\ ecardinal D E a1 /\ E om a1 /\
     (!c'. c' IN D /\ E c' a1 ==> ~(ecardinal D E c' /\ E om c')) /\
     ii IN D /\ ff IN D /\
     (!n z z'. n IN D /\ z IN D /\ z' IN D /\
               eapply D E ff n z /\ eapply D E ff n z' ==> z = z') /\
     (!b. b IN D /\ E b a1
          ==> ?d. d IN D /\ eapply D E ff b d /\ efin D E d /\
            esubset D E d ii) /\
     r IN D /\ A2 IN D /\ efin D E r /\ esubset D E r ii /\
       esubset D E A2 a1 /\
     ~(?e. einj D E e A2 om) /\
     (!al. al IN D /\ E al A2 ==> ?d. d IN D /\ eapply D E ff al d /\
      esubset D E r d) /\
     (!x Y. x IN D /\ E x ii /\ ~(E x r) /\ Y IN D /\
            (!al. al IN D
                  ==> (E al Y <=>
                       E al A2 /\ ?d. d IN D /\ eapply D E ff al d /\ E x d))
            ==> ?e. einj D E e Y om)
     ==> ?jj. jj IN D /\ esubset D E jj A2 /\ ~(?e. einj D E e jj om) /\
              (!al be dal dbe.
                 al IN D /\ be IN D /\ dal IN D /\ dbe IN D /\
                 E al jj /\ E be jj /\ ~(al = be) /\
                 eapply D E ff al dal /\ eapply D E ff be dbe
                 ==> einter D E dal dbe r)`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `(om:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[EOMEGA_IN]; ALL_TAC] THEN
  (* eordinal a1 *)
  SUBGOAL_THEN `eordinal D (E:A->A->bool) a1` ASSUME_TAC THENL
   [MP_TAC(REWRITE_RULE [ecardinal; ecardof]
      (ASSUME `ecardinal D (E:A->A->bool) a1`)) THEN
    STRIP_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  (* A2 nonempty *)
  SUBGOAL_THEN `?aa. aa IN D /\ (E:A->A->bool) aa A2` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `om:A`; `A2:A`]
      EUNCOUNTABLE_NONEMPTY) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* {A2} = epair A2 A2 *)
  MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `A2:A`; `A2:A`]
         EPAIR_EXISTS) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `aset:A`) THEN
  SUBGOAL_THEN `(aset:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[EPAIR_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) A2 aset` ASSUME_TAC THENL
   [MP_TAC(MP (SPEC `A2:A` (CONJUNCT2 (REWRITE_RULE [epair]
      (ASSUME `epair D (E:A->A->bool) A2 A2 aset`))))
      (ASSUME `(A2:A) IN D`)) THEN
    REWRITE_TAC[]; ALL_TAC] THEN
  (* STAGE_PIN at {A2} *)
  MP_TAC(MATCH_MP (ISPECL [`D:A->bool`; `E:A->A->bool`; `aset:A`] STAGE_PIN)
          (CONJ (ASSUME `model D (E:A->A->bool) ZF_AX`)
                (CONJ (ASSUME `!u. u IN D ==> elmem D (E:A->A->bool) u`)
                      (ASSUME `(aset:A) IN D`)))) THEN
  DISCH_THEN(X_CHOOSE_THEN `s:A` (X_CHOOSE_THEN `ya:A` (X_CHOOSE_THEN `ra:A`
    (X_CHOOSE_THEN `v0:num->A` STRIP_ASSUME_TAC)))) THEN
  (* A2 SUBSET ya *)
  SUBGOAL_THEN `!tt. tt IN D /\ (E:A->A->bool) tt A2 ==> E tt ya`
    (LABEL_TAC "A2ya") THENL
   [X_GEN_TAC `tt:A` THEN STRIP_TAC THEN
    MATCH_MP_TAC(MP (SPEC `A2:A` (ASSUME
        `!u. u IN D /\ (E:A->A->bool) u aset
             ==> (!t. t IN D /\ E t u ==> E t ya)`))
        (CONJ (ASSUME `(A2:A) IN D`)
              (ASSUME `(E:A->A->bool) A2 aset`))) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* valmod tower vv *)
  ABBREV_TAC `vv = (3 |-> ff) ((4 |-> A2) ((5 |-> r) (v0:num->A)))` THEN
  SUBGOAL_THEN
   `valuation D vv /\ (vv:num->A) 2 = ra /\ vv 3 = ff /\ vv 4 = A2 /\ vv 5 = r`
   STRIP_ASSUME_TAC THENL
   [EXPAND_TAC "vv" THEN REPEAT CONJ_TAC THENL
     [REPEAT(MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[]);
      REWRITE_TAC[VALMOD] THEN CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN
      ASM_REWRITE_TAC[];
      REWRITE_TAC[VALMOD];
      REWRITE_TAC[VALMOD] THEN CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN
      REWRITE_TAC[];
      REWRITE_TAC[VALMOD] THEN CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN
      REWRITE_TAC[]];
    ALL_TAC] THEN
  (* graph r_a1 = erecres deltastep vv a1 *)
  SUBGOAL_THEN `?ra1. erecres D (E:A->A->bool) deltastep_form vv a1 ra1`
   (X_CHOOSE_TAC `ra1:A`) THENL
   [MP_TAC(REWRITE_RULE [ASSUME `(vv:num->A) 4 = A2`]
       (ISPECL [`D:A->bool`; `E:A->A->bool`; `vv:num->A`; `s:A`; `ya:A`]
          EDELTAREC_RESEXISTS)) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN MATCH_MP_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  SUBGOAL_THEN `(ra1:A) IN D` ASSUME_TAC THENL
   [FIRST_ASSUM(ACCEPT_TAC o CONJUNCT1 o REWRITE_RULE[erecres]); ALL_TAC] THEN
  (* jj = einran-set(ra1) *)
  SUBGOAL_THEN
   `?jj. jj IN D /\ !w. w IN D ==> ((E:A->A->bool) w jj <=> einran D E w ra1)`
   (X_CHOOSE_THEN `jj:A`
    (CONJUNCTS_THEN2 (LABEL_TAC "jjD") (LABEL_TAC "jjchar"))) THENL
   [MATCH_MP_TAC EINRAN_SET_EXISTS THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* jj SUBSET A2 : each jj-elt = h(oo) IN A2 *)
  SUBGOAL_THEN `esubset D (E:A->A->bool) jj A2` (LABEL_TAC "jjA2") THENL
   [REWRITE_TAC[esubset] THEN X_GEN_TAC `w:A` THEN STRIP_TAC THEN
    USE_THEN "jjchar" (MP_TAC o SPEC `w:A`) THEN
    ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN(fun th -> MP_TAC(EQ_MP th (ASSUME `(E:A->A->bool) w jj`))) THEN
    REWRITE_TAC[einran] THEN
    DISCH_THEN(X_CHOOSE_THEN `pr:A`
               (X_CHOOSE_THEN `oo:A` STRIP_ASSUME_TAC)) THEN
    SUBGOAL_THEN `eapply D (E:A->A->bool) ra1 oo w` ASSUME_TAC THENL
     [REWRITE_TAC[eapply] THEN EXISTS_TAC `pr:A` THEN ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `deltastep_form`; `vv:num->A`;
      `a1:A`; `ra1:A`; `oo:A`; `w:A`] ERECRES_APPLY) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun iff ->
               MP_TAC(EQ_MP iff
                      (ASSUME `eapply D (E:A->A->bool) ra1 oo w`))) THEN
    STRIP_TAC THEN
    MP_TAC(REWRITE_RULE [ASSUME `(vv:num->A) 4 = A2`]
        (ISPECL [`D:A->bool`; `E:A->A->bool`; `vv:num->A`; `s:A`; `ya:A`]
           EDELTAREC_INA2)) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(MP_TAC o SPECL [`oo:A`; `w:A`]) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[] THEN MATCH_MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`;
        `a1:A`; `oo:A`] EORDINAL_MEMBER) THEN ASM_REWRITE_TAC[];
      DISCH_THEN ACCEPT_TAC]; ALL_TAC] THEN
  (* --- chunk 2: specialized EDELTAREC_GOOD, then einj ra1 a1 jj --- *)
  SUBGOAL_THEN
   `!xi eta hxi heta.
       eordinal D (E:A->A->bool) xi /\ E xi a1 /\
         eordinal D E eta /\ E eta xi /\
       hxi IN D /\ heta IN D /\
       erec D E deltastep_form vv xi hxi /\ erec D E deltastep_form vv eta heta
       ==> ~(hxi = heta) /\
           (!dx de. dx IN D /\ de IN D /\ eapply D E ff hxi dx /\
            eapply D E ff heta de
            ==> einter D E dx de r)`
   (LABEL_TAC "GOOD") THENL
   [MAP_EVERY X_GEN_TAC [`xi:A`; `eta:A`; `hxi:A`; `heta:A`] THEN
    STRIP_TAC THEN
    MP_TAC(REWRITE_RULE
           [ASSUME `(vv:num->A) 2 = ra`; ASSUME `(vv:num->A) 3 = ff`;
            ASSUME `(vv:num->A) 4 = A2`; ASSUME `(vv:num->A) 5 = r`]
      (ISPECL [`D:A->bool`; `E:A->A->bool`; `vv:num->A`; `s:A`; `ya:A`; `om:A`;
        `a1:A`; `ii:A`; `ff:A`; `r:A`; `A2:A`; `xi:A`; `eta:A`;
        `hxi:A`; `heta:A`]
        EDELTAREC_GOOD)) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC]; ALL_TAC] THEN
  (* eapply ra1 k t => E k a1 /\ erec vv k t *)
  SUBGOAL_THEN
   `!k t. k IN D /\ t IN D /\ eapply D (E:A->A->bool) ra1 k t
          ==> E k a1 /\ erec D E deltastep_form vv k t`
   (LABEL_TAC "rapp") THENL
   [MAP_EVERY X_GEN_TAC [`k:A`; `t:A`] THEN STRIP_TAC THEN
    MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `deltastep_form`; `vv:num->A`;
      `a1:A`; `ra1:A`; `k:A`; `t:A`] ERECRES_APPLY) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun iff ->
      ACCEPT_TAC(EQ_MP iff (ASSUME `eapply D (E:A->A->bool) ra1 k t`)));
    ALL_TAC] THEN
  (* eapply ra1 k t => E t jj *)
  SUBGOAL_THEN
    `!k t. k IN D /\ t IN D /\ eapply D (E:A->A->bool) ra1 k t ==> E t jj`
   (LABEL_TAC "injj") THENL
   [MAP_EVERY X_GEN_TAC [`k:A`; `t:A`] THEN STRIP_TAC THEN
    USE_THEN "jjchar" (MP_TAC o SPEC `t:A`) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN REWRITE_TAC[einran] THEN
    UNDISCH_TAC `eapply D (E:A->A->bool) ra1 k t` THEN REWRITE_TAC[eapply] THEN
    DISCH_THEN(X_CHOOSE_THEN `pr:A` STRIP_ASSUME_TAC) THEN
    SUBGOAL_THEN `(pr:A) IN D` ASSUME_TAC THENL
     [FIRST_ASSUM(ACCEPT_TAC o MATCH_MP EOPAIR_IN); ALL_TAC] THEN
    MAP_EVERY EXISTS_TAC [`pr:A`; `k:A`] THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* einj ra1 a1 jj *)
  SUBGOAL_THEN `einj D (E:A->A->bool) ra1 a1 jj` (LABEL_TAC "rinj") THENL
   [REWRITE_TAC[einj] THEN REPEAT CONJ_TAC THENL
     [FIRST_ASSUM ACCEPT_TAC;
      MAP_EVERY X_GEN_TAC [`k:A`; `t:A`] THEN STRIP_TAC THEN CONJ_TAC THENL
       [USE_THEN "rapp" (fun th -> MP_TAC(MP (SPECL [`k:A`; `t:A`] th)
          (CONJ (ASSUME `(k:A) IN D`) (CONJ (ASSUME `(t:A) IN D`)
            (ASSUME `eapply D (E:A->A->bool) ra1 k t`))))) THEN STRIP_TAC THEN
        FIRST_ASSUM ACCEPT_TAC;
        USE_THEN "injj"
          (fun th -> MATCH_ACCEPT_TAC(MP (SPECL [`k:A`; `t:A`] th)
                                      (CONJ (ASSUME `(k:A) IN D`)
                                       (CONJ (ASSUME `(t:A) IN D`)
                                        (ASSUME `eapply D (E:A->A->bool)
                                                ra1 k t`)))))];
      X_GEN_TAC `k:A` THEN STRIP_TAC THEN
      SUBGOAL_THEN `eordinal D (E:A->A->bool) k` ASSUME_TAC THENL
       [MATCH_MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `a1:A`; `k:A`]
          EORDINAL_MEMBER) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
      SUBGOAL_THEN
        `?tk. tk IN D /\ erec D (E:A->A->bool) deltastep_form vv k tk`
        (X_CHOOSE_THEN `tk:A` STRIP_ASSUME_TAC) THENL
       [MP_TAC(REWRITE_RULE [ASSUME `(vv:num->A) 4 = A2`]
           (ISPECL [`D:A->bool`; `E:A->A->bool`; `vv:num->A`; `s:A`; `ya:A`]
              EDELTAREC_EXISTS)) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
        DISCH_THEN MATCH_MP_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
      SUBGOAL_THEN `eapply D (E:A->A->bool) ra1 k tk` ASSUME_TAC THENL
       [MP_TAC(ISPECL
               [`D:A->bool`; `E:A->A->bool`; `deltastep_form`; `vv:num->A`;
                `a1:A`; `ra1:A`; `k:A`; `tk:A`] ERECRES_APPLY) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
        DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN ASM_REWRITE_TAC[];
        ALL_TAC] THEN
      EXISTS_TAC `tk:A` THEN ASM_REWRITE_TAC[] THEN
      USE_THEN "injj" (fun th -> MATCH_ACCEPT_TAC(MP (SPECL [`k:A`; `tk:A`] th)
        (CONJ (ASSUME `(k:A) IN D`) (CONJ (ASSUME `(tk:A) IN D`)
          (ASSUME `eapply D (E:A->A->bool) ra1 k tk`)))));
      MAP_EVERY X_GEN_TAC [`k:A`; `t:A`; `t':A`] THEN STRIP_TAC THEN
      USE_THEN "rapp" (fun th -> MP_TAC(MP (SPECL [`k:A`; `t:A`] th)
        (CONJ (ASSUME `(k:A) IN D`) (CONJ (ASSUME `(t:A) IN D`)
          (ASSUME `eapply D (E:A->A->bool) ra1 k t`))))) THEN STRIP_TAC THEN
      USE_THEN "rapp" (fun th -> MP_TAC(MP (SPECL [`k:A`; `t':A`] th)
        (CONJ (ASSUME `(k:A) IN D`) (CONJ (ASSUME `(t':A) IN D`)
          (ASSUME `eapply D (E:A->A->bool) ra1 k t'`))))) THEN STRIP_TAC THEN
      MATCH_MP_TAC(ISPECL
                   [`D:A->bool`; `E:A->A->bool`; `deltastep_form`; `vv:num->A`;
                    `k:A`; `t:A`; `t':A`] EREC_UNIQUE) THEN
      REPEAT CONJ_TAC THEN
      TRY(FIRST_ASSUM ACCEPT_TAC) THEN
      TRY(MATCH_MP_TAC(ISPECL
                       [`D:A->bool`; `E:A->A->bool`; `vv:num->A`;
                        `s:A`; `ya:A`]
                       EDELTASTEP_QFUN)) THEN
      ASM_REWRITE_TAC[];
      MAP_EVERY X_GEN_TAC [`k:A`; `k':A`; `t:A`] THEN STRIP_TAC THEN
      USE_THEN "rapp" (fun th -> MP_TAC(MP (SPECL [`k:A`; `t:A`] th)
        (CONJ (ASSUME `(k:A) IN D`) (CONJ (ASSUME `(t:A) IN D`)
          (ASSUME `eapply D (E:A->A->bool) ra1 k t`))))) THEN STRIP_TAC THEN
      USE_THEN "rapp" (fun th -> MP_TAC(MP (SPECL [`k':A`; `t:A`] th)
        (CONJ (ASSUME `(k':A) IN D`) (CONJ (ASSUME `(t:A) IN D`)
          (ASSUME `eapply D (E:A->A->bool) ra1 k' t`))))) THEN STRIP_TAC THEN
      SUBGOAL_THEN `eordinal D (E:A->A->bool) k /\ eordinal D E k'`
        STRIP_ASSUME_TAC THENL
        [CONJ_TAC THEN
         MATCH_MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `a1:A`]
                      EORDINAL_MEMBER) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
      MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `k:A`; `k':A`]
             EORDINAL_TRICHOTOMY) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(REPEAT_TCL DISJ_CASES_THEN ASSUME_TAC) THENL
       [USE_THEN "GOOD"
        (fun th -> MP_TAC(SPECL [`k':A`; `k:A`; `t:A`; `t:A`] th)) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
        DISCH_THEN(fun th ->
                   MP_TAC(MP (NOT_ELIM(CONJUNCT1 th)) (REFL `t:A`))) THEN
        REWRITE_TAC[];
        ASM_REWRITE_TAC[];
        USE_THEN "GOOD"
          (fun th -> MP_TAC(SPECL [`k:A`; `k':A`; `t:A`; `t:A`] th)) THEN
          ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
        DISCH_THEN(fun th ->
                   MP_TAC(MP (NOT_ELIM(CONJUNCT1 th)) (REFL `t:A`))) THEN
        REWRITE_TAC[]]]; ALL_TAC] THEN
  (* jj-element = h(xi) for some ordinal xi<a1 *)
  SUBGOAL_THEN
   `!w. w IN D /\ (E:A->A->bool) w jj
        ==> ?xi. E xi a1 /\ eordinal D E xi /\ erec D E deltastep_form vv xi w`
   (LABEL_TAC "jjelt") THENL
   [X_GEN_TAC `w:A` THEN STRIP_TAC THEN
    USE_THEN "jjchar" (MP_TAC o SPEC `w:A`) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> MP_TAC(EQ_MP th (ASSUME `(E:A->A->bool) w jj`))) THEN
    REWRITE_TAC[einran] THEN
    DISCH_THEN(X_CHOOSE_THEN `pr:A`
               (X_CHOOSE_THEN `xi:A` STRIP_ASSUME_TAC)) THEN
    SUBGOAL_THEN `eapply D (E:A->A->bool) ra1 xi w` ASSUME_TAC THENL
     [REWRITE_TAC[eapply] THEN EXISTS_TAC `pr:A` THEN ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    EXISTS_TAC `xi:A` THEN
    USE_THEN "rapp" (fun th -> MP_TAC(MP (SPECL [`xi:A`; `w:A`] th)
      (CONJ (ASSUME `(xi:A) IN D`) (CONJ (ASSUME `(w:A) IN D`)
        (ASSUME `eapply D (E:A->A->bool) ra1 xi w`))))) THEN STRIP_TAC THEN
    ASM_REWRITE_TAC[] THEN
    MATCH_MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `a1:A`; `xi:A`]
      EORDINAL_MEMBER) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  EXISTS_TAC `jj:A` THEN REPEAT CONJ_TAC THENL
   [FIRST_ASSUM ACCEPT_TAC;
    USE_THEN "jjA2" ACCEPT_TAC;
    (* ~einj jj om : suppose e:jj>->om;
    compose with rinj:a1>->jj gives a1>->om,
    contra EUNCOUNTABLE_CARD. *)
    REWRITE_TAC[NOT_EXISTS_THM] THEN X_GEN_TAC `e:A` THEN DISCH_TAC THEN
    MP_TAC(MATCH_MP
      (ISPECL [`D:A->bool`; `E:A->A->bool`; `ra1:A`; `e:A`; `a1:A`;
               `jj:A`; `om:A`]
       EINJ_COMPOSE)
      (end_itlist CONJ
        [ASSUME `model D (E:A->A->bool) ZF_AX`;
         ASSUME `(a1:A) IN D`;
         ASSUME `(jj:A) IN D`;
         ASSUME `(om:A) IN D`;
         ASSUME `einj D (E:A->A->bool) ra1 a1 jj`;
         ASSUME `einj D (E:A->A->bool) e jj om`])) THEN
    DISCH_THEN(X_CHOOSE_TAC `hh:A`) THEN
    MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `om:A`; `a1:A`]
           EUNCOUNTABLE_CARD) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(MP_TAC o SPEC `hh:A` o REWRITE_RULE[NOT_EXISTS_THM]) THEN
    ASM_REWRITE_TAC[];
    (* pairwise: al=h(xi), be=h(eta) via jjelt; trichotomy on xi,eta + GOOD *)
    MAP_EVERY X_GEN_TAC [`al:A`; `be:A`; `dal:A`; `dbe:A`] THEN STRIP_TAC THEN
    USE_THEN "jjelt" (fun th -> MP_TAC(MP (SPEC `al:A` th)
      (CONJ (ASSUME `(al:A) IN D`) (ASSUME `(E:A->A->bool) al jj`)))) THEN
    DISCH_THEN(X_CHOOSE_THEN `xi:A` STRIP_ASSUME_TAC) THEN
    USE_THEN "jjelt" (fun th -> MP_TAC(MP (SPEC `be:A` th)
      (CONJ (ASSUME `(be:A) IN D`) (ASSUME `(E:A->A->bool) be jj`)))) THEN
    DISCH_THEN(X_CHOOSE_THEN `eta:A` STRIP_ASSUME_TAC) THEN
    SUBGOAL_THEN `(xi:A) IN D` ASSUME_TAC THENL
     [FIRST_ASSUM(ACCEPT_TAC o MATCH_MP EORDINAL_IN o
        check(fun th -> rand(concl th) = `xi:A`)); ALL_TAC] THEN
    SUBGOAL_THEN `(eta:A) IN D` ASSUME_TAC THENL
     [FIRST_ASSUM(ACCEPT_TAC o MATCH_MP EORDINAL_IN o
        check(fun th -> rand(concl th) = `eta:A`)); ALL_TAC] THEN
    MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `xi:A`; `eta:A`]
           EORDINAL_TRICHOTOMY) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(REPEAT_TCL DISJ_CASES_THEN (LABEL_TAC "tri")) THENL
     [(* E xi eta : GOOD(eta,xi,be,al) -> einter dbe dal r, swap to dal dbe *)
      SUBGOAL_THEN `einter D (E:A->A->bool) dbe dal r` (LABEL_TAC "swp") THENL
       [USE_THEN "GOOD"
        (fun th -> MP_TAC(SPECL [`eta:A`; `xi:A`; `be:A`; `al:A`] th)) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
        DISCH_THEN(MATCH_MP_TAC o CONJUNCT2) THEN ASM_REWRITE_TAC[];
        ALL_TAC] THEN
      MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `dal:A`; `dbe:A`; `r:A`]
             EINTER_CHAR) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
      MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `dbe:A`; `dal:A`; `r:A`]
             EINTER_CHAR) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      USE_THEN "swp" (fun sw -> DISCH_THEN(fun ec -> MP_TAC(EQ_MP ec sw))) THEN
      MESON_TAC[];
      (* xi = eta : al=be by EREC_UNIQUE, contra ~(al=be) *)
      USE_THEN "tri" SUBST_ALL_TAC THEN
      SUBGOAL_THEN `(al:A) = be` ASSUME_TAC THENL
       [MATCH_MP_TAC(ISPECL
                     [`D:A->bool`; `E:A->A->bool`; `deltastep_form`;
                      `vv:num->A`;
                      `eta:A`; `al:A`; `be:A`] EREC_UNIQUE) THEN
             REPEAT CONJ_TAC THEN
             TRY(FIRST_ASSUM ACCEPT_TAC) THEN
        TRY(MATCH_MP_TAC(ISPECL
                         [`D:A->bool`; `E:A->A->bool`; `vv:num->A`;
                          `s:A`; `ya:A`]
                         EDELTASTEP_QFUN)) THEN ASM_REWRITE_TAC[];
        ALL_TAC] THEN
      UNDISCH_TAC `~(al:A = be)` THEN ASM_REWRITE_TAC[];
      (* E eta xi : GOOD(xi,eta,al,be) -> einter dal dbe r directly *)
      USE_THEN "GOOD"
        (fun th -> MP_TAC(SPECL [`xi:A`; `eta:A`; `al:A`; `be:A`] th)) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(MATCH_MP_TAC o CONJUNCT2) THEN ASM_REWRITE_TAC[]]]);;

(* ==== F6.2 s3 CAPSTONE : EDELTA_SYSTEM ==================================
   The indexed Delta-system at aleph_1: for ANY single-valued ff sending each
   b<a1 to a finite subset of ii, there is an uncountable jj SUBSET a1 and a
   finite root r such that {ff(al):al IN jj} forms a sunflower with core r.
   PROOF = EDELTA_ROOT (finite root r + uncountable A2 SUBSET a1 with r SUBSET
   every ff(al), al in A2, and the bad-set-countable predicate) THEN
   EDELTA_RECURSION (the omega_1 recursion, r,A2 as inputs, yields jj SUBSET A2
   uncountable with pairwise einter (ff .)(ff .) = r).  esubset jj a1 by
   transitivity of esubset through A2.  This is exactly the !ff premise of
   CCC_COHEN_MODULO_DELTA, so discharging it makes CCC_COHEN
   unconditional. *)

let EDELTA_SYSTEM = prove
 (`!D (E:A->A->bool) om a1 ii.
     model D E ZF_AX /\ (!u. u IN D ==> elmem D E u) /\
     eomega D E om /\ a1 IN D /\ ecardinal D E a1 /\ E om a1 /\
     (!c'. c' IN D /\ E c' a1 ==> ~(ecardinal D E c' /\ E om c')) /\
     ii IN D
     ==> !ff. ff IN D /\
              (!n z z'. n IN D /\ z IN D /\ z' IN D /\
                        eapply D E ff n z /\ eapply D E ff n z' ==> z = z') /\
              (!b. b IN D /\ E b a1
                   ==> ?d. d IN D /\ eapply D E ff b d /\ efin D E d /\
                           esubset D E d ii)
              ==> ?jj r. jj IN D /\ r IN D /\ esubset D E jj a1 /\
                efin D E r /\
                         ~(?e. einj D E e jj om) /\
                         (!al be dal dbe.
                            al IN D /\ be IN D /\ dal IN D /\ dbe IN D /\
                            E al jj /\ E be jj /\ ~(al = be) /\
                            eapply D E ff al dal /\ eapply D E ff be dbe
                            ==> einter D E dal dbe r)`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN X_GEN_TAC `ff:A` THEN STRIP_TAC THEN
  (* EDELTA_ROOT -> finite r, uncountable A2 SUBSET a1 with root/bad *)
  (* properties *)
  MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `om:A`; `ii:A`; `a1:A`; `ff:A`]
    EDELTA_ROOT) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  INTRO_TAC "@r A2. rD A2D efinr rii A2a1 A2inj petals badc" THEN
  (* EDELTA_RECURSION with these r, A2 -> jj SUBSET A2 uncountable, *)
  (* sunflower *)
  MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `om:A`; `a1:A`; `ii:A`; `ff:A`;
    `r:A`; `A2:A`] EDELTA_RECURSION) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  INTRO_TAC "@jj. jjD jjA2 jjinj pw" THEN
  MAP_EVERY EXISTS_TAC [`jj:A`; `r:A`] THEN ASM_REWRITE_TAC[] THEN
  (* esubset jj a1 by transitivity through A2 *)
  UNDISCH_TAC `esubset D (E:A->A->bool) A2 a1` THEN
  UNDISCH_TAC `esubset D (E:A->A->bool) jj A2` THEN
  REWRITE_TAC[esubset] THEN MESON_TAC[]);;

(* ==== F6.3 : CCC_COHEN (unconditional) =================================
   The Cohen forcing poset P (finite partial functions ci -> om, ci = ii x tw
   the index set) is ccc, UNCONDITIONALLY: CCC_COHEN_MODULO_DELTA reduced the
   ccc-ness to the indexed Delta-system premise at aleph_1, which EDELTA_SYSTEM
   now discharges (over any ground model of ZF).  This kills the last
   hypothesis,
   giving eccc D E P leqp outright -- the input CCC_RO needs to lift
   to the Cohen algebra (regular-open completion). *)

let CCC_COHEN = prove
 (`!D (E:A->A->bool) ii tw ci om P leqp a1.
     model D E ZF_AX /\ ii IN D /\ (!u. u IN D ==> elmem D E u) /\
     eomega D E om /\
     ecross D E ii tw ci /\ efin D E tw /\
     ecohenp D E ci om P /\ eleqp D E P leqp /\
     a1 IN D /\ ecardinal D E a1 /\ E om a1 /\
     (!c'. c' IN D /\ E c' a1 ==> ~(ecardinal D E c' /\ E om c'))
     ==> eccc D E P leqp`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  (* establish the Delta-system premise as an assumption via EDELTA_SYSTEM
     BEFORE MATCH_MP so the ASM_REWRITE cannot strip its `_ IN D` *)
  MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `om:A`; `a1:A`; `ii:A`]
    EDELTA_SYSTEM) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN DISCH_TAC THEN
  MATCH_MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `ii:A`; `tw:A`; `ci:A`;
    `om:A`; `P:A`; `leqp:A`; `a1:A`] CCC_COHEN_MODULO_DELTA) THEN
  REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC);;

(* ==== F6 FINISH : COHEN_CBA_CCC ========================================
   The Cohen ALGEBRA (regular-open / Boolean completion bp of the
     Cohen poset P)
   is ccc, unconditionally: chain the now-unconditional CCC_COHEN
     (Cohen poset P
   is ccc) through CCC_RO (F6.4: regular-open completion of a ccc
     poset is ccc).
   This `eccc bp inclB` is exactly the hypothesis the F6.5 preservation step
   needs. *)

let COHEN_CBA_CCC = prove
 (`!D (E:A->A->bool) ii tw ci om P leqp B bp inclB a1.
     model D E ZF_AX /\ ii IN D /\ (!u. u IN D ==> elmem D E u) /\
     eomega D E om /\
     ecross D E ii tw ci /\ efin D E tw /\
     ecohenp D E ci om P /\ eleqp D E P leqp /\
     eroset D E P leqp B /\ ebplus D E B bp /\ eincl D E B inclB /\
     a1 IN D /\ ecardinal D E a1 /\ E om a1 /\
     (!c'. c' IN D /\ E c' a1 ==> ~(ecardinal D E c' /\ E om c'))
     ==> eccc D E bp inclB`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  (* CCC_COHEN : Cohen poset P is ccc *)
  SUBGOAL_THEN `eccc D (E:A->A->bool) P leqp` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `ii:A`; `tw:A`; `ci:A`;
      `om:A`; `P:A`; `leqp:A`; `a1:A`] CCC_COHEN) THEN ASM_REWRITE_TAC[];
     ALL_TAC] THEN
  (* P IN D from ecohenp (CONJUNCT1) *)
  SUBGOAL_THEN `(P:A) IN D` ASSUME_TAC THENL
   [FIRST_ASSUM(ACCEPT_TAC o CONJUNCT1 o REWRITE_RULE[ecohenp]); ALL_TAC] THEN
  (* CCC_RO : completion of a ccc poset is ccc *)
  MATCH_MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `P:A`; `leqp:A`; `B:A`;
    `bp:A`; `inclB:A`] CCC_RO) THEN ASM_REWRITE_TAC[]);;

(* ==== F6.5 (preservation core) : CCC_ANTICHAIN_DOM =====================
   The reusable ccc consequence behind the covering lemma: if an internal set X
   injects (via c) into an antichain a of the ccc algebra (bp,inclB), then X is
   countable (injects into omega).  Directly: eccc gives a >-> om; compose with
   c : X >-> a.  In the preservation argument X will be a fibre
   {beta<a1 : [[ g(xi-check) = beta-check ]] =/= bot} and c the
     value map, whose
   image is an antichain because a name forced to be a function sends distinct
   values to incompatible conditions. *)

let CCC_ANTICHAIN_DOM = prove
 (`!D (E:A->A->bool) bp inclB X a c.
     model D E ZF_AX /\ eccc D E bp inclB /\ X IN D /\ a IN D /\
     einj D E c X a /\ eantichain D E bp inclB a
     ==> ?om e. eomega D E om /\ einj D E e X om`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  UNDISCH_TAC `eccc D (E:A->A->bool) bp inclB` THEN REWRITE_TAC[eccc] THEN
  DISCH_THEN(MP_TAC o SPEC `a:A`) THEN ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `om:A` (X_CHOOSE_THEN `f:A` STRIP_ASSUME_TAC)) THEN
  MP_TAC(ISPECL
         [`D:A->bool`; `E:A->A->bool`; `c:A`; `f:A`; `X:A`; `a:A`; `om:A`]
         EINJ_COMPOSE) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[MATCH_MP EOMEGA_IN (ASSUME `eomega D (E:A->A->bool) om`)];
    ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_TAC `h:A`) THEN
  MAP_EVERY EXISTS_TAC [`om:A`; `h:A`] THEN ASM_REWRITE_TAC[]);;

(* ==== F6.5 (ECHECK_EQ_BOT prereq) : EBV_EQ_LE_STAGE ====================
   The equality-value UPPER bound (dual of EBV_EQ_GLB_STAGE): the stage
   equality value z = [[u=v]] lies BELOW each left implication factor
   u(x) => [[x IN v]]  (x IN dom u).  Because z = emeet gL gR with
     gL = eglb SL,
   SL = the bveqcombset of those implications: z <= gL <= (that comb).  This is
   the "z <= factor" direction that ECHECK_EQ_LE_MEM (hence
     ECHECK_EQ_BOT) needs
   and that was previously missing (only the greatest-lower-bound direction was
   banked). *)

let EBV_EQ_LE_STAGE = prove
 (`!D (E:A->A->bool) B leq a w sIN sEQ u v z x qx exv c.
      model D E ZF_AX /\ ecba D E B leq /\ B IN D /\
      a IN D /\ eordinal D E a /\ ebnstage D E B a w /\ w IN D /\
      u IN D /\ v IN D /\ E u w /\ E v w /\ ebvatt D E B leq w sIN sEQ /\
      ebveq D E B leq sIN u v z /\
      x IN D /\ qx IN D /\ exv IN D /\ c IN D /\
      eapply D E u x qx /\ ebv_in D E B leq x v exv /\ ebimp D E B leq qx exv c
      ==> erel D E leq z c`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `eporder D (E:A->A->bool) B leq` ASSUME_TAC THENL
   [ASM_MESON_TAC[ECBA_IMP_BALG; EBALG_IMP_PORDER]; ALL_TAC] THEN
  UNDISCH_TAC `ebveq D (E:A->A->bool) B leq sIN u v z` THEN
  REWRITE_TAC[ebveq] THEN
  INTRO_TAC "@SL SR gL gR. csL csR glL glR mt" THEN
  (* pr = <x,v>, x IN w *)
  SUBGOAL_THEN `?pr:A. eopair D (E:A->A->bool) x v pr`
    (X_CHOOSE_TAC `pr:A`) THENL
   [MATCH_MP_TAC EOPAIR_EXISTS THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(pr:A) IN D` ASSUME_TAC THENL
   [FIRST_ASSUM(ACCEPT_TAC o MATCH_MP EOPAIR_IN); ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) x w` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`B:A`;`a:A`;`w:A`;`u:A`;`x:A`;
                  `qx:A`] STAGE_DOM_CLOSED) THEN ASM_REWRITE_TAC[];
      ALL_TAC] THEN
  (* table entry sIN(<x,v>) = exv *)
  MP_TAC(ISPECL
         [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`w:A`;`sIN:A`;`sEQ:A`;
          `x:A`;`v:A`;`pr:A`] EBVATT_VAL) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(CONJUNCTS_THEN2 (X_CHOOSE_THEN `vi:A` STRIP_ASSUME_TAC)
             (K ALL_TAC)) THEN
  SUBGOAL_THEN `ebv_in D (E:A->A->bool) B leq x v vi` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`a:A`;`w:A`;`sIN:A`;
                  `sEQ:A`;`x:A`;`v:A`;`pr:A`;`vi:A`] EBV_IN_TABLE_ENTRY) THEN
             ASM_REWRITE_TAC[];
             ALL_TAC] THEN
  SUBGOAL_THEN `(vi:A) = exv` SUBST_ALL_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`x:A`;`v:A`;`vi:A`;
                  `exv:A`] EBV_IN_UNIQUE) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* c is the comb for x -> E c SL *)
  SUBGOAL_THEN `(E:A->A->bool) c SL` ASSUME_TAC THENL
   [USE_THEN "csL" (fun th -> MP_TAC(MP (SPEC `c:A` (CONJUNCT2
       (REWRITE_RULE[bveqcombset] th))) (ASSUME `(c:A) IN D`))) THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN REWRITE_TAC[bveqcomb] THEN
    MAP_EVERY EXISTS_TAC [`x:A`; `qx:A`; `exv:A`; `pr:A`] THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  (* z <= gL <= c *)
  SUBGOAL_THEN `erel D (E:A->A->bool) leq gL c` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`SL:A`;`gL:A`;`c:A`]
                 EGLB_LB) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq z gL` ASSUME_TAC THENL
   [FIRST_ASSUM(ACCEPT_TAC o CONJUNCT1 o MATCH_MP EMEET_LE); ALL_TAC] THEN
  (* all field/domain facts from the two erel's via EPORDER_FIELD *)
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`z:A`;`gL:A`]
    EPORDER_FIELD) THEN ASM_REWRITE_TAC[] THEN STRIP_TAC THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`gL:A`;`c:A`]
    EPORDER_FIELD) THEN ASM_REWRITE_TAC[] THEN STRIP_TAC THEN
  MATCH_MP_TAC(ISPECL
               [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`z:A`;`gL:A`;`c:A`]
               EPORDER_TRANS) THEN ASM_REWRITE_TAC[]);;

(* ==== F6.5 (ECHECK_EQ_BOT prereq) : EBV_EQ_LE_TERM_V ===================
   Value-level form of EBV_EQ_LE_STAGE (mirrors EBV_IN_LE_V): from the
   tabled value z = [[u=v]] extract a common stage (unfold ebv_eq), read the
   ebveq value off the sEQ table (EBVATT_VAL, EAPPLY_UNIQUE), then apply the
   stage-level bound.  Gives z <= (u(x) => [[x IN v]]) for x IN dom u. *)

let EBV_EQ_LE_TERM_V = prove
 (`!D (E:A->A->bool) B leq u v z x qx exv c.
      model D E ZF_AX /\ ecba D E B leq /\ B IN D /\
      u IN D /\ v IN D /\ z IN D /\ ebv_eq D E B leq u v z /\
      x IN D /\ qx IN D /\ exv IN D /\ c IN D /\
      eapply D E u x qx /\ ebv_in D E B leq x v exv /\ ebimp D E B leq qx exv c
      ==> erel D E leq z c`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  UNDISCH_TAC `ebv_eq D (E:A->A->bool) B leq u v z` THEN
  REWRITE_TAC[ebv_eq] THEN
  DISCH_THEN(X_CHOOSE_THEN `aa:A` (X_CHOOSE_THEN `ww:A` (X_CHOOSE_THEN `sI:A`
    (X_CHOOSE_THEN `sE:A` (X_CHOOSE_THEN `pr0:A` STRIP_ASSUME_TAC))))) THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`ww:A`;`sI:A`;`sE:A`;
    `u:A`;`v:A`;`pr0:A`] EBVATT_VAL) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(CONJUNCTS_THEN2 (K ALL_TAC)
             (X_CHOOSE_THEN `ve:A` STRIP_ASSUME_TAC)) THEN
  SUBGOAL_THEN `eisfun D (E:A->A->bool) sE` ASSUME_TAC THENL
   [FIRST_ASSUM(ACCEPT_TAC o CONJUNCT1 o CONJUNCT2 o REWRITE_RULE[ebvatt]);
    ALL_TAC] THEN
  SUBGOAL_THEN `(pr0:A) IN D` ASSUME_TAC THENL
   [FIRST_ASSUM(ACCEPT_TAC o MATCH_MP EOPAIR_IN); ALL_TAC] THEN
  SUBGOAL_THEN `(z:A) = ve` SUBST_ALL_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`sE:A`;`pr0:A`;`z:A`;`ve:A`]
                 EAPPLY_UNIQUE) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MATCH_MP_TAC(ISPECL
               [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`aa:A`;`ww:A`;`sI:A`;
                `sE:A`;`u:A`;`v:A`;`ve:A`;`x:A`;`qx:A`;`exv:A`;`c:A`]
                 EBV_EQ_LE_STAGE) THEN
  ASM_REWRITE_TAC[]);;

(* ==== helper : EBIMP_TOP_ANT  (top ==> y = y) ==========================
   With a top antecedent the Boolean implication is the identity: onebee => y
   collapses to y, because ~onebee = bot and bot \/ y = y. *)

let EBIMP_TOP_ANT = prove
 (`!D (E:A->A->bool) p leq onebee y z.
      ebalg D E p leq /\ etop D E p leq onebee /\ onebee IN D /\ E onebee p /\
      y IN D /\ E y p /\ ebimp D E p leq onebee y z
      ==> z = y`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `eporder D (E:A->A->bool) p leq` ASSUME_TAC THENL
   [ASM_MESON_TAC[EBALG_IMP_PORDER]; ALL_TAC] THEN
  UNDISCH_TAC `ebimp D (E:A->A->bool) p leq onebee y z` THEN
  REWRITE_TAC[ebimp] THEN
  DISCH_THEN(X_CHOOSE_THEN `c:A` (CONJUNCTS_THEN2 (LABEL_TAC "cmp")
    (LABEL_TAC "jn"))) THEN
  SUBGOAL_THEN `(c:A) IN D /\ (E:A->A->bool) c p` STRIP_ASSUME_TAC THENL
   [USE_THEN "cmp" (MP_TAC o REWRITE_RULE[ecompl]) THEN STRIP_TAC THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `ecompl D (E:A->A->bool) p leq c onebee` ASSUME_TAC THENL
   [MATCH_MP_TAC ECOMPL_SYM THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `ebot D (E:A->A->bool) p leq c` ASSUME_TAC THENL
   [MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`p:A`;`leq:A`;`c:A`;`onebee:A`]
      ECOMPL_TOP_BOT) THEN ASM_REWRITE_TAC[] THEN
    DISCH_THEN(fun th ->
               MP_TAC(EQ_MP th (ASSUME `etop D (E:A->A->bool) p leq onebee`)))
    THEN REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `ejoin D (E:A->A->bool) p leq c y y` ASSUME_TAC THENL
   [MATCH_MP_TAC EJOIN_BOT THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MATCH_MP_TAC(ISPECL
               [`D:A->bool`;`E:A->A->bool`;`p:A`;`leq:A`;`c:A`;`y:A`;
                `z:A`;`y:A`]
               EJOIN_UNIQUE) THEN ASM_REWRITE_TAC[]);;

(* ==== F6.5 (ECHECK_EQ_BOT prereq) : ECHECK_EQ_LE_MEM ===================
   Equality forces membership of every domain element: for s IN a,
     [[ va = vb ]] <= [[ vs IN vb ]]   (vs = s-check).
   The check assigns onebee(=top) to vs in dom(va), so the value-level bound
   EBV_EQ_LE_TERM_V gives [[va=vb]] <= (onebee => [[vs IN vb]]) = [[vs IN vb]]
   (EBIMP_TOP_ANT collapses the top implication). *)

let ECHECK_EQ_LE_MEM = prove
 (`!D (E:A->A->bool) B leq onebee a va b vb s vs ee zi.
      model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
      onebee IN D /\ E onebee B /\ etop D E B leq onebee /\
      echeck D E onebee a va /\ echeck D E onebee b vb /\
      E s a /\ echeck D E onebee s vs /\
      ee IN D /\ ebv_eq D E B leq va vb ee /\
      zi IN D /\ ebv_in D E B leq vs vb zi
      ==> erel D E leq ee zi`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `ebalg D (E:A->A->bool) B leq` ASSUME_TAC THENL
   [ASM_MESON_TAC[ECBA_IMP_BALG]; ALL_TAC] THEN
  SUBGOAL_THEN `(va:A) IN D /\ (vb:A) IN D /\ (vs:A) IN D /\ (s:A) IN D`
   STRIP_ASSUME_TAC THENL [ASM_MESON_TAC[ECHECK_IMP]; ALL_TAC] THEN
  (* eapply va vs onebee : vs in dom va with value onebee *)
  SUBGOAL_THEN `?pr:A. eopair D (E:A->A->bool) vs onebee pr`
    (X_CHOOSE_TAC `pr:A`) THENL
   [MATCH_MP_TAC EOPAIR_EXISTS THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(pr:A) IN D` ASSUME_TAC THENL
   [FIRST_ASSUM(ACCEPT_TAC o MATCH_MP EOPAIR_IN); ALL_TAC] THEN
  SUBGOAL_THEN `eapply D (E:A->A->bool) va vs onebee` ASSUME_TAC THENL
   [REWRITE_TAC[eapply] THEN EXISTS_TAC `pr:A` THEN ASM_REWRITE_TAC[] THEN
    MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`onebee:A`;`a:A`;`va:A`;`pr:A`]
      ECHECK_MEM) THEN ASM_REWRITE_TAC[] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    MAP_EVERY EXISTS_TAC [`s:A`;`vs:A`] THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) zi B` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`vs:A`;
                  `vb:A`;`zi:A`]
                 EBV_IN_IN_B) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* c = onebee => zi *)
  SUBGOAL_THEN `?c:A. ebimp D (E:A->A->bool) B leq onebee zi c`
    (X_CHOOSE_TAC `c:A`) THENL
   [MATCH_MP_TAC EBIMP_EXISTS THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(c:A) IN D /\ (E:A->A->bool) c B` STRIP_ASSUME_TAC THENL
   [FIRST_ASSUM(ACCEPT_TAC o MATCH_MP EBIMP_IN); ALL_TAC] THEN
  (* c = zi *)
  SUBGOAL_THEN `(c:A) = zi` SUBST_ALL_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`onebee:A`;`zi:A`;
                  `c:A`] EBIMP_TOP_ANT) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MATCH_MP_TAC(ISPECL
               [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`va:A`;`vb:A`;`ee:A`;
                `vs:A`;`onebee:A`;`zi:A`;`zi:A`] EBV_EQ_LE_TERM_V) THEN
  ASM_REWRITE_TAC[]);;

(* ==== F6.5 (ECHECK_EQ_BOT prereq) : ECHECK_IN_NONMEM ===================
   If every c IN b has [[ vs = c-check ]] = bot (the induction hypothesis of
   check rigidity),
   then [[ vs IN b-check ]] = bot.  Because [[vs IN vb]] is the
   sup of the [[vs = c-check]] (ECHECK_IN_LE_SUP with w0 := bot):
     each is <= bot
   (EBOT_LE), so the sup is <= bot, hence = bot (ELE_BOT). *)

let ECHECK_IN_NONMEM = prove
 (`!D (E:A->A->bool) B leq onebee b vb vs zi.
      model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
      onebee IN D /\ E onebee B /\
      echeck D E onebee b vb /\ bname D E B vs /\ vs IN D /\
      zi IN D /\ ebv_in D E B leq vs vb zi /\
      (!c vc ec. E c b /\ echeck D E onebee c vc /\ ec IN D /\
                 ebv_eq D E B leq vs vc ec ==> ebot D E B leq ec)
      ==> ebot D E B leq zi`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `eporder D (E:A->A->bool) B leq` ASSUME_TAC THENL
   [ASM_MESON_TAC[ECBA_IMP_BALG; EBALG_IMP_PORDER]; ALL_TAC] THEN
  SUBGOAL_THEN `(vb:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[ECHECK_IMP]; ALL_TAC] THEN
  SUBGOAL_THEN `?bot:A. ebot D (E:A->A->bool) B leq bot`
    (X_CHOOSE_TAC `bot:A`) THENL
   [MATCH_MP_TAC EBALG_BOT THEN ASM_MESON_TAC[ECBA_IMP_BALG]; ALL_TAC] THEN
  SUBGOAL_THEN `(bot:A) IN D /\ (E:A->A->bool) bot B` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[EBOT_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) zi B` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`vs:A`;
                  `vb:A`;`zi:A`]
                 EBV_IN_IN_B) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq zi bot` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`onebee:A`;`b:A`;
                  `vb:A`;`vs:A`;`zi:A`;`bot:A`] ECHECK_IN_LE_SUP) THEN
      ASM_REWRITE_TAC[] THEN
      MAP_EVERY X_GEN_TAC [`c:A`;`vc:A`;`ec:A`] THEN STRIP_TAC THEN
    SUBGOAL_THEN `ebot D (E:A->A->bool) B leq ec` ASSUME_TAC THENL
     [FIRST_X_ASSUM MATCH_MP_TAC THEN
      MAP_EVERY EXISTS_TAC [`c:A`;`vc:A`] THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`ec:A`;`bot:A`]
                 EBOT_LE) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(zi:A) = bot` SUBST_ALL_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`zi:A`;`bot:A`]
                 ELE_BOT) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  ASM_REWRITE_TAC[]);;

(* ==== F6.5 capstone core : erigid_at + RIGBAD_HALF ====================
   The SEMANTIC content of check-rigidity's transfinite-induction step (pure
   semantics, no object formula -- mirrors GOODCHECK_STEP).
   erigid_at d : "any two checks va,vb with bnrank <= d, of DISTINCT sets, have
   [[va=vb]] = bot".  RIGBAD_HALF: given the IH (erigid_at d' for
     all d'<d) and a
   distinguishing element s IN a \ b, [[va=vb]] = bot -- via [[vs IN vb]]=bot
   (ECHECK_IN_NONMEM,
   its per-c hypothesis [[vs=c-check]]=bot discharged by the IH
   at a rank-bound below d from EORDINAL_MAX2) and [[va=vb]] <= [[vs IN vb]]
   (ECHECK_EQ_LE_MEM), then ELE_BOT. *)

let erigid_at = new_definition
  `erigid_at D (E:A->A->bool) B leq onebee d <=>
     !a b va vb ee.
        echeck D E onebee a va /\ echeck D E onebee b vb /\
        (?ra. ebnrank D E B va ra /\ (E ra d \/ ra = d)) /\
        (?rb. ebnrank D E B vb rb /\ (E rb d \/ rb = d)) /\
        ~(a = b) /\ ee IN D /\ ebv_eq D E B leq va vb ee
        ==> ebot D E B leq ee`;;

let RIGBAD_HALF = prove
 (`!D (E:A->A->bool) B leq onebee d a b va vb s ee.
     model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
     (!u. u IN D ==> elmem D E u) /\
     onebee IN D /\ E onebee B /\ etop D E B leq onebee /\
     eordinal D E d /\
     (!d'. d' IN D /\ E d' d ==> erigid_at D E B leq onebee d') /\
     echeck D E onebee a va /\ echeck D E onebee b vb /\
     (?ra. ebnrank D E B va ra /\ (E ra d \/ ra = d)) /\
     (?rb. ebnrank D E B vb rb /\ (E rb d \/ rb = d)) /\
     s IN D /\ E s a /\ ~(E s b) /\
     ee IN D /\ ebv_eq D E B leq va vb ee
     ==> ebot D E B leq ee`,
  REPEAT GEN_TAC THEN DISCH_THEN(REPEAT_TCL CONJUNCTS_THEN ASSUME_TAC) THEN
  (* extract ra = bnrank va, rb = bnrank vb (keep the <= d disjunction *)
  (* intact) *)
  UNDISCH_TAC
    `?ra. ebnrank D (E:A->A->bool) B va ra /\ (E ra d \/ ra = d)` THEN
  DISCH_THEN(X_CHOOSE_THEN `ra:A` (CONJUNCTS_THEN ASSUME_TAC)) THEN
  UNDISCH_TAC
    `?rb. ebnrank D (E:A->A->bool) B vb rb /\ (E rb d \/ rb = d)` THEN
  DISCH_THEN(X_CHOOSE_THEN `rb:A` (CONJUNCTS_THEN ASSUME_TAC)) THEN
  SUBGOAL_THEN `(ra:A) IN D` ASSUME_TAC THENL
   [FIRST_ASSUM(ACCEPT_TAC o MATCH_MP EBNRANK_IN); ALL_TAC] THEN
  SUBGOAL_THEN `(rb:A) IN D` ASSUME_TAC THENL
   [FIRST_ASSUM(ACCEPT_TAC o MATCH_MP EBNRANK_IN); ALL_TAC] THEN
  (* vs = check of s ; bname, IN D *)
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`onebee:A`;`s:A`]
         ECHECK_EXHAUSTION) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `vs:A`) THEN
  SUBGOAL_THEN `(vs:A) IN D` ASSUME_TAC THENL
   [FIRST_ASSUM(ACCEPT_TAC o CONJUNCT2 o MATCH_MP ECHECK_IMP); ALL_TAC] THEN
  SUBGOAL_THEN `(va:A) IN D` ASSUME_TAC THENL
   [FIRST_ASSUM(ACCEPT_TAC o CONJUNCT2 o MATCH_MP ECHECK_IMP); ALL_TAC] THEN
  SUBGOAL_THEN `(vb:A) IN D` ASSUME_TAC THENL
   [FIRST_ASSUM(ACCEPT_TAC o CONJUNCT2 o MATCH_MP ECHECK_IMP); ALL_TAC] THEN
  SUBGOAL_THEN `(b:A) IN D` ASSUME_TAC THENL
   [FIRST_ASSUM(ACCEPT_TAC o CONJUNCT1 o MATCH_MP ECHECK_IMP); ALL_TAC] THEN
  SUBGOAL_THEN `bname D (E:A->A->bool) B vs` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`onebee:A`;`B:A`;`s:A`;`vs:A`]
                 ECHECK_IS_BNAME) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `bname D (E:A->A->bool) B vb` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`onebee:A`;`B:A`;`b:A`;`vb:A`]
                 ECHECK_IS_BNAME) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `?zi:A. zi IN D /\ E zi B /\ ebv_in D E B leq vs vb zi`
   (X_CHOOSE_THEN `zi:A` STRIP_ASSUME_TAC) THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`vs:A`;`vb:A`]
                 EBV_IN_VAL_EXISTS) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* ebot zi  via ECHECK_IN_NONMEM with the IH discharging each *)
  (* [[vs=c-check]]=bot *)
  SUBGOAL_THEN `ebot D (E:A->A->bool) B leq zi` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`onebee:A`;`b:A`;
                  `vb:A`;`vs:A`;`zi:A`] ECHECK_IN_NONMEM) THEN
         ASM_REWRITE_TAC[] THEN
         MAP_EVERY X_GEN_TAC [`c:A`; `vc:A`; `ec:A`] THEN STRIP_TAC THEN
    SUBGOAL_THEN `~(s:A = c)` ASSUME_TAC THENL
     [UNDISCH_TAC `~((E:A->A->bool) s b)` THEN
      UNDISCH_TAC `(E:A->A->bool) c b` THEN MESON_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN `(c:A) IN D /\ (vc:A) IN D` STRIP_ASSUME_TAC THENL
     [FIRST_ASSUM(ACCEPT_TAC o MATCH_MP ECHECK_IMP); ALL_TAC] THEN
    (* eapply va vs onebee *)
    SUBGOAL_THEN `?p:A. eopair D (E:A->A->bool) vs onebee p`
      (X_CHOOSE_TAC `p:A`) THENL
      [MATCH_MP_TAC EOPAIR_EXISTS THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN `(p:A) IN D` ASSUME_TAC THENL
     [FIRST_ASSUM(ACCEPT_TAC o MATCH_MP EOPAIR_IN); ALL_TAC] THEN
    SUBGOAL_THEN `eapply D (E:A->A->bool) va vs onebee` ASSUME_TAC THENL
     [REWRITE_TAC[eapply] THEN EXISTS_TAC `p:A` THEN ASM_REWRITE_TAC[] THEN
      MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`onebee:A`;`a:A`;`va:A`;`p:A`]
        ECHECK_MEM) THEN ASM_REWRITE_TAC[] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
      MAP_EVERY EXISTS_TAC [`s:A`;`vs:A`] THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    (* eapply vb vc onebee *)
    SUBGOAL_THEN `?q:A. eopair D (E:A->A->bool) vc onebee q`
      (X_CHOOSE_TAC `q:A`) THENL
      [MATCH_MP_TAC EOPAIR_EXISTS THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN `(q:A) IN D` ASSUME_TAC THENL
     [FIRST_ASSUM(ACCEPT_TAC o MATCH_MP EOPAIR_IN); ALL_TAC] THEN
    SUBGOAL_THEN `eapply D (E:A->A->bool) vb vc onebee` ASSUME_TAC THENL
     [REWRITE_TAC[eapply] THEN EXISTS_TAC `q:A` THEN ASM_REWRITE_TAC[] THEN
      MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`onebee:A`;`b:A`;`vb:A`;`q:A`]
        ECHECK_MEM) THEN ASM_REWRITE_TAC[] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
      MAP_EVERY EXISTS_TAC [`c:A`;`vc:A`] THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    (* rvs = bnrank vs < ra, rvc = bnrank vc < rb *)
    MP_TAC(ISPECL
           [`D:A->bool`;`E:A->A->bool`;`B:A`;`va:A`;`vs:A`;`onebee:A`;`ra:A`]
           EBNRANK_APPLY_LT) THEN ANTS_TAC THENL
    [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(CONJUNCTS_THEN2 (K ALL_TAC)
      (X_CHOOSE_THEN `rvs:A` STRIP_ASSUME_TAC)) THEN
    MP_TAC(ISPECL
           [`D:A->bool`;`E:A->A->bool`;`B:A`;`vb:A`;`vc:A`;`onebee:A`;`rb:A`]
           EBNRANK_APPLY_LT) THEN ANTS_TAC THENL
    [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(CONJUNCTS_THEN2 (K ALL_TAC)
      (X_CHOOSE_THEN `rvc:A` STRIP_ASSUME_TAC)) THEN
    SUBGOAL_THEN `(rvs:A) IN D /\ (rvc:A) IN D` STRIP_ASSUME_TAC THENL
     [CONJ_TAC THEN FIRST_ASSUM(ACCEPT_TAC o MATCH_MP EBNRANK_IN);
      ALL_TAC] THEN
    (* E rvs d, E rvc d *)
    SUBGOAL_THEN `(E:A->A->bool) rvs d` ASSUME_TAC THENL
     [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`rvs:A`;`ra:A`;`d:A`]
        EORDINAL_MEM_TRANS) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN `(E:A->A->bool) rvc d` ASSUME_TAC THENL
     [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`rvc:A`;`rb:A`;`d:A`]
        EORDINAL_MEM_TRANS) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    (* d' = bound of rvs, rvc below d *)
    SUBGOAL_THEN
     `?dd. dd IN D /\ (E:A->A->bool) dd d /\ (E rvs dd \/ rvs = dd) /\
           (E rvc dd \/ rvc = dd)`
     (X_CHOOSE_THEN `dm:A` (CONJUNCTS_THEN ASSUME_TAC)) THENL
     [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`d:A`;`rvs:A`;`rvc:A`]
        EORDINAL_MAX2) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    (* apply the IH at d' to (s,c,vs,vc,ec) *)
    UNDISCH_TAC
      `!d'. d' IN D /\ E d' d ==>
       erigid_at D (E:A->A->bool) B leq onebee d'` THEN
    DISCH_THEN(MP_TAC o SPEC `dm:A`) THEN ASM_REWRITE_TAC[erigid_at] THEN
    DISCH_THEN(MP_TAC o SPECL [`s:A`;`c:A`;`vs:A`;`vc:A`;`ec:A`]) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
       [EXISTS_TAC `rvs:A` THEN ASM_REWRITE_TAC[];
        EXISTS_TAC `rvc:A` THEN ASM_REWRITE_TAC[]];
      DISCH_THEN ACCEPT_TAC]; ALL_TAC] THEN
  (* [[va=vb]] = ee <= [[vs IN vb]] = zi *)
  SUBGOAL_THEN `erel D (E:A->A->bool) leq ee zi` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`onebee:A`;`a:A`;
                  `va:A`;`b:A`;`vb:A`;`s:A`;`vs:A`;`ee:A`;`zi:A`]
                   ECHECK_EQ_LE_MEM) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* ee <= zi = bot ==> ebot ee *)
  SUBGOAL_THEN `eporder D (E:A->A->bool) B leq` ASSUME_TAC THENL
   [FIRST_ASSUM(ACCEPT_TAC o MATCH_MP EBALG_IMP_PORDER o MATCH_MP
                ECBA_IMP_BALG);
    ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) ee B` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`va:A`;
                  `vb:A`;`ee:A`]
                 EBV_EQ_IN_B) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(ee:A) = zi` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`ee:A`;`zi:A`]
                 ELE_BOT) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  UNDISCH_TAC `(ee:A) = zi` THEN DISCH_THEN SUBST1_TAC THEN
  FIRST_ASSUM ACCEPT_TAC);;

(* ==== RIGBAD_STEP : the transfinite-induction step for erigid_at ========
   a=/=b splits (ESUBSET_ANTISYM) into ~esubset a b (distinguishing s IN a\b ->
   RIGBAD_HALF directly) or ~esubset b a (s IN b\a -> RIGBAD_HALF on
     (b,a,vb,va),
   then EBV_EQ_SYM flips [[vb=va]]=bot to [[va=vb]]=bot). *)

let RIGBAD_STEP = prove
 (`!D (E:A->A->bool) B leq onebee d.
     model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
     (!u. u IN D ==> elmem D E u) /\
     onebee IN D /\ E onebee B /\ etop D E B leq onebee /\
     eordinal D E d /\
     (!d'. d' IN D /\ E d' d ==> erigid_at D E B leq onebee d')
     ==> erigid_at D E B leq onebee d`,
  REPEAT GEN_TAC THEN DISCH_THEN(REPEAT_TCL CONJUNCTS_THEN ASSUME_TAC) THEN
  REWRITE_TAC[erigid_at] THEN
  MAP_EVERY X_GEN_TAC [`a:A`; `b:A`; `va:A`; `vb:A`; `ee:A`] THEN
  DISCH_THEN(REPEAT_TCL CONJUNCTS_THEN ASSUME_TAC) THEN
  SUBGOAL_THEN `(a:A) IN D /\ (b:A) IN D` STRIP_ASSUME_TAC THENL
   [CONJ_TAC THEN FIRST_ASSUM(ACCEPT_TAC o CONJUNCT1 o MATCH_MP ECHECK_IMP);
    ALL_TAC] THEN
  SUBGOAL_THEN `(va:A) IN D /\ (vb:A) IN D` STRIP_ASSUME_TAC THENL
   [CONJ_TAC THEN FIRST_ASSUM(ACCEPT_TAC o CONJUNCT2 o MATCH_MP ECHECK_IMP);
    ALL_TAC] THEN
  SUBGOAL_THEN `~(esubset D (E:A->A->bool) a b) \/ ~(esubset D E b a)`
    MP_TAC THENL
   [MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`a:A`;`b:A`]
           ESUBSET_ANTISYM) THEN
    ASM_REWRITE_TAC[] THEN UNDISCH_TAC `~(a:A = b)` THEN MESON_TAC[];
    ALL_TAC] THEN
  DISCH_THEN(DISJ_CASES_THEN MP_TAC) THENL
   [REWRITE_TAC[esubset; NOT_FORALL_THM; NOT_IMP] THEN
    DISCH_THEN(X_CHOOSE_THEN `s:A` STRIP_ASSUME_TAC) THEN
    MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`onebee:A`;`d:A`;
      `a:A`;`b:A`;`va:A`;`vb:A`;`s:A`;`ee:A`] RIGBAD_HALF) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[]; DISCH_TAC THEN FIRST_ASSUM ACCEPT_TAC];
    REWRITE_TAC[esubset; NOT_FORALL_THM; NOT_IMP] THEN
    DISCH_THEN(X_CHOOSE_THEN `s:A` STRIP_ASSUME_TAC) THEN
    SUBGOAL_THEN `ebv_eq D (E:A->A->bool) B leq vb va ee` ASSUME_TAC THENL
     [MATCH_MP_TAC(ISPECL
                   [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`va:A`;`vb:A`;
                    `ee:A`] EBV_EQ_SYM) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`onebee:A`;`d:A`;
      `b:A`;`a:A`;`vb:A`;`va:A`;`s:A`;`ee:A`] RIGBAD_HALF) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[]; DISCH_TAC THEN FIRST_ASSUM ACCEPT_TAC]]);;

(* ==== F6.5 ECHECK_EQ_BOT wrapper: inline check-tower + echeck encoding ====
   HOLDS_RECAPP3_CHKSTEP: recapp3 of the check recursion at slots i,j is
   echecktower at (v 2 = onebee) (v i) (v j).  Verbatim mirror of
   HOLDS_RECAPP3_BNSTEP.  Then checkstage_form (slot-2 rebind exposing
   set/value slots) and echeck_form (stage + pair-membership = echeck). *)

let HOLDS_RECAPP3_CHKSTEP = prove
 (`!D (E:A->A->bool) v i j.
        model D E ZF_AX /\ valuation D v /\
        ~(i = 3) /\ ~(i = 4) /\ ~(j = 3) /\ ~(j = 4)
        ==> (holds D E v (recapp3_form (rec_form check_step_form 3) i j) <=>
             echecktower D E (v 2) (v i) (v j))`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `!x. (v:num->A) x IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[valuation]; ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `v:num->A`;
                `rec_form check_step_form 3`; `i:num`; `j:num`]
        HOLDS_RECAPP3_FORM) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `v:num->A`;
                `check_step_form`; `3`; `(v:num->A) i`; `(v:num->A) j`]
        HOLDS_REC_FORM) THEN
  ASM_REWRITE_TAC[FVLT_CHECK_STEP_FORM; ARITH_RULE `1 < 3`;
                  ARITH_RULE `3 + 1 = 4`] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `(v:num->A) 2`;
                `(v:num->A) i`; `(v:num->A) j`; `v:num->A`]
        ECHECKTOWER_EREC) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]));;

(* checkstage_form vON A V : echecktower onebee (v A) (v V) with slot-2 rebound
   to onebee (Eq 2 vON) for the check recursion; A,V exposed as slots. *)
let checkstage_form = new_definition
  `checkstage_form vON A V =
     ?? 2 (Eq 2 vON && recapp3_form (rec_form check_step_form 3) A V)`;;

let HOLDS_CHECKSTAGE_FORM = prove
 (`!D (E:A->A->bool) v vON A V.
      model D E ZF_AX /\ valuation D v /\
      ~(vON = 2) /\ ~(vON = 3) /\ ~(vON = 4) /\
      ~(A = 2) /\ ~(A = 3) /\ ~(A = 4) /\
      ~(V = 2) /\ ~(V = 3) /\ ~(V = 4)
      ==> (holds D E v (checkstage_form vON A V) <=>
           echecktower D E (v vON) (v A) (v V))`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `!x. (v:num->A) x IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[valuation]; ALL_TAC] THEN
  REWRITE_TAC[checkstage_form] THEN
  SUBGOAL_THEN
   `!w:A. w IN D
      ==> (holds D E ((2 |-> w) v)
             (recapp3_form (rec_form check_step_form 3) A V) <=>
           echecktower D E w (v A) (v V))`
  (LABEL_TAC "inner") THENL
   [X_GEN_TAC `w:A` THEN DISCH_TAC THEN
    SUBGOAL_THEN `valuation D ((2 |-> (w:A)) v)` ASSUME_TAC THENL
     [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
    MP_TAC(SPECL
           [`D:A->bool`; `E:A->A->bool`; `(2 |-> (w:A)) v`; `A:num`; `V:num`]
           HOLDS_RECAPP3_CHKSTEP) THEN
    ASM_REWRITE_TAC[] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER; ARITH_EQ];
    ALL_TAC] THEN
  REWRITE_TAC[HOLDS_EX; HOLDS_AND; holds] THEN
  ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER; ARITH_EQ] THEN
  CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN
  ASM_SIMP_TAC[MESON[]
   `t IN D ==> ((?w:A. w IN D /\ w = t /\ P w) <=> P t)`] THEN
  USE_THEN "inner" (fun th -> MP_TAC(SPEC `(v:num->A) vON` th)) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN(fun th -> REWRITE_TAC[th])]);;

(* echeck_form vON A V : encodes echeck onebee (v A) (v V) -- <v A, v V> is a
   pair in the check-stage at some ordinal.  49=aa(ordinal), 50=cd(stage),
   51=pp(pair).  checkstage_form does the slot-2 rebind internally. *)
let echeck_form = new_definition
  `echeck_form vON A V =
     ?? 49 (?? 50 (?? 51
        (ordinal_form 49 && checkstage_form vON 49 50 &&
         opair_form A V 51 && 51 %% 50)))`;;

let HOLDS_ECHECK_FORM = prove
 (`!D (E:A->A->bool) v vON A V.
      model D E ZF_AX /\ valuation D v /\
      ~(vON = 2) /\ ~(vON = 3) /\ ~(vON = 4) /\
      ~(vON = 49) /\ ~(vON = 50) /\ ~(vON = 51) /\
      ~(A = 2) /\ ~(A = 3) /\ ~(A = 4) /\
      ~(A = 49) /\ ~(A = 50) /\ ~(A = 51) /\
      ~(V = 2) /\ ~(V = 3) /\ ~(V = 4) /\
      ~(V = 49) /\ ~(V = 50) /\ ~(V = 51)
      ==> (holds D E v (echeck_form vON A V) <=>
           echeck D E (v vON) (v A) (v V))`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `!x. (v:num->A) x IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[valuation]; ALL_TAC] THEN
  REWRITE_TAC[echeck_form] THEN
  SUBGOAL_THEN
   `!aa cd pp:A. aa IN D /\ cd IN D /\ pp IN D
      ==> (holds D E ((51 |-> pp) ((50 |-> cd) ((49 |-> aa) v)))
             (ordinal_form 49 && checkstage_form vON 49 50 &&
              opair_form A V 51 && 51 %% 50) <=>
           eordinal D E aa /\ echecktower D E (v vON) aa cd /\
           eopair D E (v A) (v V) pp /\ E pp cd)`
  (LABEL_TAC "blk") THENL
   [REPEAT GEN_TAC THEN STRIP_TAC THEN
    SUBGOAL_THEN
     `valuation D ((51 |-> (pp:A)) ((50 |-> (cd:A)) ((49 |-> (aa:A)) v)))`
    ASSUME_TAC THENL [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
    REWRITE_TAC[HOLDS_AND] THEN
    SUBGOAL_THEN
     `holds D E ((51 |-> (pp:A)) ((50 |-> (cd:A)) ((49 |-> (aa:A)) v)))
        (ordinal_form 49) <=> eordinal D E aa`
    (fun th -> REWRITE_TAC[th]) THENL
     [ASM_SIMP_TAC[HOLDS_ORDINAL_FORM] THEN
      ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER; ARITH_EQ]; ALL_TAC] THEN
    SUBGOAL_THEN
     `holds D E ((51 |-> (pp:A)) ((50 |-> (cd:A)) ((49 |-> (aa:A)) v)))
        (checkstage_form vON 49 50) <=> echecktower D E (v vON) aa cd`
    (fun th -> REWRITE_TAC[th]) THENL
     [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
        `(51 |-> (pp:A)) ((50 |-> (cd:A)) ((49 |-> (aa:A)) v))`;
        `vON:num`; `49`; `50`] HOLDS_CHECKSTAGE_FORM) THEN
      ASM_REWRITE_TAC[ARITH_RULE
        `~(49 = 2) /\ ~(49 = 3) /\ ~(49 = 4) /\
         ~(50 = 2) /\ ~(50 = 3) /\ ~(50 = 4)`] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
      ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER; ARITH_EQ]; ALL_TAC] THEN
    SUBGOAL_THEN
     `holds D E ((51 |-> (pp:A)) ((50 |-> (cd:A)) ((49 |-> (aa:A)) v)))
        (opair_form A V 51) <=> eopair D E (v A) (v V) pp`
    (fun th -> REWRITE_TAC[th]) THENL
     [ASM_SIMP_TAC[HOLDS_OPAIR_FORM] THEN
      ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER; ARITH_EQ]; ALL_TAC] THEN
    REWRITE_TAC[holds] THEN
    ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER; ARITH_EQ];
    ALL_TAC] THEN
  REWRITE_TAC[echeck] THEN ASM_REWRITE_TAC[] THEN
  REWRITE_TAC[HOLDS_EX] THEN
  USE_THEN "blk" (fun bl -> ASM_MESON_TAC[bl]));;

(* ==== F6.5 rigid_form : object-formula encoding of erigid_at ============
   rigid_form vON at index (v 0): "any two checks va,vb (of distinct sets a,b)
   with bnrank <= (v 0) have [[va=vb]] = bot".  Slots: a=52,b=53,va=57,vb=58,
   ee=59,ra=54,rb=55,vON=onebee,d=0,B=2,leq=5.  Composes echeck_form,
   bnrankp_form, ebv_eq_form, bbot_form; bridged to erigid_at. *)

let rigid_form = new_definition
  `rigid_form vON =
     !! 52 (!! 53 (!! 57 (!! 58 (!! 59 (
       ( echeck_form vON 52 57 && echeck_form vON 53 58 &&
         (?? 54 (bnrankp_form 57 54 && ((54 %% 0) || Eq 54 0))) &&
         (?? 55 (bnrankp_form 58 55 && ((55 %% 0) || Eq 55 0))) &&
         Not(Eq 52 53) && ebv_eq_form 59 57 58 5 )
       --> bbot_form 5 2 59 )))))`;;

let HOLDS_RIGID_FORM = prove
 (`!D (E:A->A->bool) v vON.
      model D E ZF_AX /\ valuation D v /\
      ~(vON = 0) /\ ~(vON = 2) /\ ~(vON = 3) /\ ~(vON = 4) /\
      ~(vON = 49) /\ ~(vON = 50) /\ ~(vON = 51) /\ ~(vON = 52) /\
      ~(vON = 53) /\ ~(vON = 54) /\ ~(vON = 55) /\ ~(vON = 57) /\
      ~(vON = 58) /\ ~(vON = 59)
      ==> (holds D E v (rigid_form vON) <=>
           erigid_at D E (v 2) (v 5) (v vON) (v 0))`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `!x. (v:num->A) x IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[valuation]; ALL_TAC] THEN
  REWRITE_TAC[rigid_form] THEN
  SUBGOAL_THEN
   `!(a:A) (b:A) (va:A) (vb:A) (ee:A).
      a IN D /\ b IN D /\ va IN D /\ vb IN D /\ ee IN D
      ==> (holds D (E:A->A->bool)
             ((59 |-> ee)
              ((58 |-> vb) ((57 |-> va) ((53 |-> b) ((52 |-> a) (v:num->A))))))
             (echeck_form vON 52 57 && echeck_form vON 53 58 &&
              (?? 54 (bnrankp_form 57 54 && ((54 %% 0) || Eq 54 0))) &&
              (?? 55 (bnrankp_form 58 55 && ((55 %% 0) || Eq 55 0))) &&
              Not(Eq 52 53) && ebv_eq_form 59 57 58 5 --> bbot_form 5 2 59) <=>
           (echeck D E (v vON) a va /\ echeck D E (v vON) b vb /\
            (?ra. ebnrank D E (v 2) va ra /\ (E ra (v 0) \/ ra = v 0)) /\
            (?rb. ebnrank D E (v 2) vb rb /\ (E rb (v 0) \/ rb = v 0)) /\
            ~((a:A) = b) /\ ebv_eq D E (v 2) (v 5) va vb ee
            ==> ebot D E (v 2) (v 5) ee))`
  (LABEL_TAC "blk") THENL
   [REPEAT GEN_TAC THEN STRIP_TAC THEN
    ABBREV_TAC
     `vv = (59 |-> (ee:A))
      ((58 |-> vb) ((57 |-> va) ((53 |-> b) ((52 |-> a) v))))` THEN
    SUBGOAL_THEN `valuation D (vv:num->A)` ASSUME_TAC THENL
     [EXPAND_TAC "vv" THEN ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
    SUBGOAL_THEN
     `(vv:num->A) 0 = v 0 /\ vv 2 = v 2 /\ vv 5 = v 5 /\ vv vON = v vON /\
      vv 52 = a /\ vv 53 = b /\ vv 57 = va /\ vv 58 = vb /\ vv 59 = ee`
    STRIP_ASSUME_TAC THENL
     [EXPAND_TAC "vv" THEN
      ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER; ARITH_EQ]; ALL_TAC] THEN
    REWRITE_TAC[holds; HOLDS_AND] THEN
    (* echeck_form vON 52 57 -> echeck (v vON) a va *)
    SUBGOAL_THEN
     `holds D E (vv:num->A) (echeck_form vON 52 57) <=>
      echeck D E (v vON) a va`
    (fun th -> REWRITE_TAC[th]) THENL
     [MP_TAC(SPECL
             [`D:A->bool`; `E:A->A->bool`; `vv:num->A`; `vON:num`; `52`; `57`]
             HOLDS_ECHECK_FORM) THEN
      ASM_REWRITE_TAC[ARITH_RULE
       `~(52 = 2) /\ ~(52 = 3) /\ ~(52 = 4) /\ ~(52 = 49) /\ ~(52 = 50) /\
        ~(52 = 51) /\ ~(57 = 2) /\ ~(57 = 3) /\ ~(57 = 4) /\ ~(57 = 49) /\
        ~(57 = 50) /\ ~(57 = 51)`] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    SUBGOAL_THEN
     `holds D E (vv:num->A) (echeck_form vON 53 58) <=>
      echeck D E (v vON) b vb`
    (fun th -> REWRITE_TAC[th]) THENL
     [MP_TAC(SPECL
             [`D:A->bool`; `E:A->A->bool`; `vv:num->A`; `vON:num`; `53`; `58`]
             HOLDS_ECHECK_FORM) THEN
      ASM_REWRITE_TAC[ARITH_RULE
       `~(53 = 2) /\ ~(53 = 3) /\ ~(53 = 4) /\ ~(53 = 49) /\ ~(53 = 50) /\
        ~(53 = 51) /\ ~(58 = 2) /\ ~(58 = 3) /\ ~(58 = 4) /\ ~(58 = 49) /\
        ~(58 = 50) /\ ~(58 = 51)`] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    (* ebv_eq_form 59 57 58 5 -> ebv_eq (v2)(v5) va vb ee *)
    SUBGOAL_THEN
     `holds D E (vv:num->A) (ebv_eq_form 59 57 58 5) <=>
      ebv_eq D E (v 2) (v 5) va vb ee`
    (fun th -> REWRITE_TAC[th]) THENL
     [MP_TAC(SPECL
             [`D:A->bool`; `E:A->A->bool`; `vv:num->A`; `59`; `57`; `58`; `5`]
             HOLDS_EBV_EQ_FORM) THEN
      ASM_REWRITE_TAC[] THEN DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
      ASM_REWRITE_TAC[]; ALL_TAC] THEN
    (* bbot_form 5 2 59 -> ebot (v2)(v5) ee *)
    SUBGOAL_THEN
     `holds D E (vv:num->A) (bbot_form 5 2 59) <=> ebot D E (v 2) (v 5) ee`
    (fun th -> REWRITE_TAC[th]) THENL
     [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `vv:num->A`; `5`; `2`; `59`]
        HOLDS_BBOT_FORM) THEN
      ASM_REWRITE_TAC[] THEN DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
      ASM_REWRITE_TAC[]; ALL_TAC] THEN
    (* Not(Eq 52 53) -> ~(a=b) *)
    SUBGOAL_THEN `holds D E (vv:num->A) (Not(Eq 52 53)) <=> ~((a:A) = b)`
    (fun th -> REWRITE_TAC[th]) THENL
     [REWRITE_TAC[HOLDS_NOT; holds] THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    (* the two bnrank existentials *)
    SUBGOAL_THEN
     `(holds D E (vv:num->A)
       (?? 54 (bnrankp_form 57 54 && ((54 %% 0) || Eq 54 0))) <=>
       (?ra. ebnrank D E (v 2) va ra /\ (E ra (v 0) \/ ra = v 0))) /\
      (holds D E (vv:num->A)
       (?? 55 (bnrankp_form 58 55 && ((55 %% 0) || Eq 55 0))) <=>
       (?rb. ebnrank D E (v 2) vb rb /\ (E rb (v 0) \/ rb = v 0)))`
    MP_TAC THENL
     [CONJ_TAC THENL
       [REWRITE_TAC[HOLDS_EX] THEN EQ_TAC THENL
         [DISCH_THEN(X_CHOOSE_THEN `r:A`
                     (CONJUNCTS_THEN2 ASSUME_TAC MP_TAC)) THEN
          SUBGOAL_THEN `valuation D ((54 |-> (r:A)) vv)` ASSUME_TAC THENL
           [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
          REWRITE_TAC[HOLDS_AND; HOLDS_OR; holds] THEN
          MP_TAC(SPECL
                 [`D:A->bool`; `E:A->A->bool`; `(54 |-> (r:A)) vv`; `57`; `54`]
                 HOLDS_BNRANKP_FORM) THEN
          ASM_REWRITE_TAC[ARITH_RULE
            `~(54 = 3) /\ ~(54 = 4) /\ ~(54 = 11) /\ ~(54 = 12) /\
             ~(57 = 11) /\ ~(57 = 12) /\ ~(57 = 13)`] THEN
          DISCH_THEN(fun th -> REWRITE_TAC[GSYM ebnrank; th]) THEN
          ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER; ARITH_EQ] THEN
          DISCH_THEN(CONJUNCTS_THEN ASSUME_TAC) THEN
          EXISTS_TAC `r:A` THEN ASM_REWRITE_TAC[];
          DISCH_THEN(X_CHOOSE_THEN `r:A` (CONJUNCTS_THEN ASSUME_TAC)) THEN
          SUBGOAL_THEN `(r:A) IN D` ASSUME_TAC THENL
           [FIRST_ASSUM(ACCEPT_TAC o MATCH_MP EBNRANK_IN); ALL_TAC] THEN
          EXISTS_TAC `r:A` THEN ASM_REWRITE_TAC[] THEN
          SUBGOAL_THEN `valuation D ((54 |-> (r:A)) vv)` ASSUME_TAC THENL
           [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
          REWRITE_TAC[HOLDS_AND; HOLDS_OR; holds] THEN
          MP_TAC(SPECL
                 [`D:A->bool`; `E:A->A->bool`; `(54 |-> (r:A)) vv`; `57`; `54`]
                 HOLDS_BNRANKP_FORM) THEN
          ASM_REWRITE_TAC[ARITH_RULE
            `~(54 = 3) /\ ~(54 = 4) /\ ~(54 = 11) /\ ~(54 = 12) /\
             ~(57 = 11) /\ ~(57 = 12) /\ ~(57 = 13)`] THEN
          DISCH_THEN(fun th -> REWRITE_TAC[GSYM ebnrank; th]) THEN
          ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER; ARITH_EQ]];
        REWRITE_TAC[HOLDS_EX] THEN EQ_TAC THENL
         [DISCH_THEN(X_CHOOSE_THEN `r:A`
                     (CONJUNCTS_THEN2 ASSUME_TAC MP_TAC)) THEN
          SUBGOAL_THEN `valuation D ((55 |-> (r:A)) vv)` ASSUME_TAC THENL
           [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
          REWRITE_TAC[HOLDS_AND; HOLDS_OR; holds] THEN
          MP_TAC(SPECL
                 [`D:A->bool`; `E:A->A->bool`; `(55 |-> (r:A)) vv`; `58`; `55`]
                 HOLDS_BNRANKP_FORM) THEN
          ASM_REWRITE_TAC[ARITH_RULE
            `~(55 = 3) /\ ~(55 = 4) /\ ~(55 = 11) /\ ~(55 = 12) /\
             ~(58 = 11) /\ ~(58 = 12) /\ ~(58 = 13)`] THEN
          DISCH_THEN(fun th -> REWRITE_TAC[GSYM ebnrank; th]) THEN
          ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER; ARITH_EQ] THEN
          DISCH_THEN(CONJUNCTS_THEN ASSUME_TAC) THEN
          EXISTS_TAC `r:A` THEN ASM_REWRITE_TAC[];
          DISCH_THEN(X_CHOOSE_THEN `r:A` (CONJUNCTS_THEN ASSUME_TAC)) THEN
          SUBGOAL_THEN `(r:A) IN D` ASSUME_TAC THENL
           [FIRST_ASSUM(ACCEPT_TAC o MATCH_MP EBNRANK_IN); ALL_TAC] THEN
          EXISTS_TAC `r:A` THEN ASM_REWRITE_TAC[] THEN
          SUBGOAL_THEN `valuation D ((55 |-> (r:A)) vv)` ASSUME_TAC THENL
           [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
          REWRITE_TAC[HOLDS_AND; HOLDS_OR; holds] THEN
          MP_TAC(SPECL
                 [`D:A->bool`; `E:A->A->bool`; `(55 |-> (r:A)) vv`; `58`; `55`]
                 HOLDS_BNRANKP_FORM) THEN
          ASM_REWRITE_TAC[ARITH_RULE
            `~(55 = 3) /\ ~(55 = 4) /\ ~(55 = 11) /\ ~(55 = 12) /\
             ~(58 = 11) /\ ~(58 = 12) /\ ~(58 = 13)`] THEN
          DISCH_THEN(fun th -> REWRITE_TAC[GSYM ebnrank; th]) THEN
          ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER; ARITH_EQ]]];
      DISCH_THEN(fun th -> REWRITE_TAC[th])];
    ALL_TAC] THEN
  REWRITE_TAC[erigid_at] THEN
  REWRITE_TAC[HOLDS_ALL] THEN
  USE_THEN "blk" (fun bl -> SIMP_TAC[bl]) THEN
  EQ_TAC THENL
   [DISCH_THEN(LABEL_TAC "lhs") THEN
    MAP_EVERY X_GEN_TAC [`a:A`; `b:A`; `va:A`; `vb:A`; `ee:A`] THEN
    DISCH_THEN(REPEAT_TCL CONJUNCTS_THEN ASSUME_TAC) THEN
    SUBGOAL_THEN `(a:A) IN D /\ (b:A) IN D /\ (va:A) IN D /\ (vb:A) IN D`
    STRIP_ASSUME_TAC THENL
     [REPEAT CONJ_TAC THEN
      FIRST_ASSUM(fun th ->
                  ACCEPT_TAC(CONJUNCT1(MATCH_MP ECHECK_IMP th)) ORELSE
                  ACCEPT_TAC(CONJUNCT2(MATCH_MP ECHECK_IMP th)));
      ALL_TAC] THEN
    USE_THEN "lhs" (MP_TAC o SPEC `a:A`) THEN
    ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN (MP_TAC o SPEC `b:A`) THEN
    ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN (MP_TAC o SPEC `va:A`) THEN
    ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN (MP_TAC o SPEC `vb:A`) THEN
    ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN (MP_TAC o SPEC `ee:A`) THEN
    ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_TAC THEN FIRST_ASSUM ACCEPT_TAC];
    DISCH_THEN(LABEL_TAC "rhs") THEN
    X_GEN_TAC `a:A` THEN DISCH_TAC THEN
    X_GEN_TAC `b:A` THEN DISCH_TAC THEN
    X_GEN_TAC `va:A` THEN DISCH_TAC THEN
    X_GEN_TAC `vb:A` THEN DISCH_TAC THEN
    X_GEN_TAC `ee:A` THEN DISCH_TAC THEN
    DISCH_THEN(REPEAT_TCL CONJUNCTS_THEN ASSUME_TAC) THEN
    USE_THEN "rhs" (MP_TAC o SPECL [`a:A`; `b:A`; `va:A`; `vb:A`; `ee:A`]) THEN
    ANTS_TAC THENL
    [ASM_REWRITE_TAC[]; DISCH_TAC THEN FIRST_ASSUM ACCEPT_TAC]]);;

(* ==== F6.5 capstone: ERIGID_ALL + ECHECK_EQ_BOT ========================
   ERIGID_ALL: !d. eordinal d ==> erigid_at ... d, by EORDINAL_INDUCT on the
   object formula rigid_form (bridge HOLDS_RIGID_FORM) with step RIGBAD_STEP.
   Then ECHECK_EQ_BOT:
   distinct checks have [[va=vb]] = bot. *)

let ERIGID_ALL = prove
 (`!D (E:A->A->bool) B leq onebee.
     model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
     (!u. u IN D ==> elmem D E u) /\
     onebee IN D /\ E onebee B /\ etop D E B leq onebee
     ==> !d. eordinal D E d ==> erigid_at D E B leq onebee d`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  FIRST_ASSUM(X_CHOOSE_TAC `v0:num->A` o MATCH_MP VALUATION_EXISTS o
              MATCH_MP MODEL_NONEMPTY) THEN
  ABBREV_TAC `v = (60 |-> (onebee:A)) ((5 |-> leq) ((2 |-> (B:A)) v0))` THEN
  SUBGOAL_THEN
   `valuation D (v:num->A) /\ v 2 = B /\ v 5 = leq /\ v 60 = onebee`
  STRIP_ASSUME_TAC THENL
   [EXPAND_TAC "v" THEN
    ASM_SIMP_TAC[VALUATION_VALMOD; VALMOD_BASIC; VALMOD_OTHER; ARITH_EQ];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!a:A. a IN D
      ==> (holds D E ((0 |-> a) v) (rigid_form 60) <=>
           erigid_at D E B leq onebee a)`
  (LABEL_TAC "bridge") THENL
   [X_GEN_TAC `a:A` THEN DISCH_TAC THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `(0 |-> (a:A)) v`; `60`]
      HOLDS_RIGID_FORM) THEN
    ASM_SIMP_TAC[VALUATION_VALMOD; ARITH_RULE
      `~(60 = 0) /\ ~(60 = 2) /\ ~(60 = 3) /\ ~(60 = 4) /\ ~(60 = 49) /\
       ~(60 = 50) /\ ~(60 = 51) /\ ~(60 = 52) /\ ~(60 = 53) /\ ~(60 = 54) /\
       ~(60 = 55) /\ ~(60 = 57) /\ ~(60 = 58) /\ ~(60 = 59)`] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER; ARITH_EQ]; ALL_TAC] THEN
  MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `rigid_form 60`; `0`; `v:num->A`]
    EORDINAL_INDUCT) THEN
  ANTS_TAC THENL
   [CONJ_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    CONJ_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    X_GEN_TAC `a:A` THEN STRIP_TAC THEN
    SUBGOAL_THEN `(a:A) IN D` ASSUME_TAC THENL
    [ASM_MESON_TAC[EORDINAL_IN]; ALL_TAC] THEN
    USE_THEN "bridge"
      (fun th -> REWRITE_TAC[MATCH_MP th (ASSUME `(a:A) IN D`)]) THEN
      MATCH_MP_TAC(ISPECL
                   [`D:A->bool`; `E:A->A->bool`; `B:A`; `leq:A`;
                    `onebee:A`; `a:A`]
                   RIGBAD_STEP) THEN
    ASM_REWRITE_TAC[] THEN
    X_GEN_TAC `d':A` THEN STRIP_TAC THEN
    SUBGOAL_THEN `(d':A) IN D` ASSUME_TAC THENL
    [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    USE_THEN "bridge"
      (fun th ->
       ONCE_REWRITE_TAC[GSYM(MATCH_MP th (ASSUME `(d':A) IN D`))]) THEN
    FIRST_X_ASSUM MATCH_MP_TAC THEN ASM_REWRITE_TAC[];
    DISCH_TAC THEN X_GEN_TAC `d:A` THEN DISCH_TAC THEN
    SUBGOAL_THEN `(d:A) IN D` ASSUME_TAC THENL
    [ASM_MESON_TAC[EORDINAL_IN]; ALL_TAC] THEN
    USE_THEN "bridge"
      (fun th ->
       ONCE_REWRITE_TAC[GSYM(MATCH_MP th (ASSUME `(d:A) IN D`))]) THEN
    FIRST_X_ASSUM MATCH_MP_TAC THEN ASM_REWRITE_TAC[]]);;

(* ECHECK_EQ_BOT : distinct checks va,vb have [[ va = vb ]] = bot.  Apply
   ERIGID_ALL at d = the larger of bnrank(va), bnrank(vb) (trichotomy). *)
let ECHECK_EQ_BOT = prove
 (`!D (E:A->A->bool) B leq onebee a b va vb ee.
     model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
     (!u. u IN D ==> elmem D E u) /\
     onebee IN D /\ E onebee B /\ etop D E B leq onebee /\
     echeck D E onebee a va /\ echeck D E onebee b vb /\ ~(a = b) /\
     ee IN D /\ ebv_eq D E B leq va vb ee
     ==> ebot D E B leq ee`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `(a:A) IN D /\ (va:A) IN D /\ (b:A) IN D /\ (vb:A) IN D`
  STRIP_ASSUME_TAC THENL [ASM_MESON_TAC[ECHECK_IMP]; ALL_TAC] THEN
  SUBGOAL_THEN `bname D (E:A->A->bool) B va /\ bname D E B vb`
  STRIP_ASSUME_TAC THENL
   [CONJ_TAC THENL
     [MATCH_MP_TAC(ISPECL
                   [`D:A->bool`;`E:A->A->bool`;`onebee:A`;`B:A`;`a:A`;`va:A`]
                   ECHECK_IS_BNAME) THEN ASM_REWRITE_TAC[];
      MATCH_MP_TAC(ISPECL
                   [`D:A->bool`;`E:A->A->bool`;`onebee:A`;`B:A`;`b:A`;`vb:A`]
                   ECHECK_IS_BNAME) THEN ASM_REWRITE_TAC[]]; ALL_TAC] THEN
  SUBGOAL_THEN `?rva. rva IN D /\ ebnrank D E (B:A) va rva`
  (X_CHOOSE_THEN `rva:A` STRIP_ASSUME_TAC) THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`va:A`]
                 EBNRANK_EXISTS) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `?rvb. rvb IN D /\ ebnrank D E (B:A) vb rvb`
  (X_CHOOSE_THEN `rvb:A` STRIP_ASSUME_TAC) THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`vb:A`]
                 EBNRANK_EXISTS) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `eordinal D (E:A->A->bool) rva /\ eordinal D E rvb`
  STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[EBNRANK_ORDINAL]; ALL_TAC] THEN
  SUBGOAL_THEN
   `?d. eordinal D (E:A->A->bool) d /\ (E rva d \/ rva = d) /\
    (E rvb d \/ rvb = d)`
  (X_CHOOSE_THEN `d:A` (CONJUNCTS_THEN ASSUME_TAC)) THENL
   [MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`rva:A`;`rvb:A`]
           EORDINAL_TRICHOTOMY) THEN
    ASM_REWRITE_TAC[] THEN STRIP_TAC THENL
     [EXISTS_TAC `rvb:A` THEN ASM_REWRITE_TAC[];
      EXISTS_TAC `rvb:A` THEN ASM_REWRITE_TAC[];
      EXISTS_TAC `rva:A` THEN ASM_REWRITE_TAC[]]; ALL_TAC] THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`onebee:A`]
         ERIGID_ALL) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(MP_TAC o SPEC `d:A`) THEN
  ASM_REWRITE_TAC[erigid_at] THEN
  DISCH_THEN(MP_TAC o SPECL [`a:A`;`b:A`;`va:A`;`vb:A`;`ee:A`]) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
     [EXISTS_TAC `rva:A` THEN ASM_REWRITE_TAC[];
      EXISTS_TAC `rvb:A` THEN ASM_REWRITE_TAC[]];
    DISCH_TAC THEN FIRST_ASSUM ACCEPT_TAC]);;

(* ==== F6.5 b2 core: VALUE_INCOMPAT ====================================
   For a name g and DISTINCT sets b1,b2 with checks vb1,vb2:
     [[ g = vb1 ]] MEET [[ g = vb2 ]]  =  bot.
   Because [[vb1=g]] meet [[g=vb2]] <= [[vb1=vb2]] (EBV_EQ_CONG, transitivity)
   and [[vb1=vb2]] = bot (ECHECK_EQ_BOT, b1=/=b2).  Foundation for the value-
   antichain: the fibre value map beta |-> [[ g(xi) = beta-check ]] has
   pairwise-incompatible values. *)

let VALUE_INCOMPAT = prove
 (`!D (E:A->A->bool) B leq onebee g b1 b2 vb1 vb2 zg1 zg2 zm.
     model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
     (!u. u IN D ==> elmem D E u) /\
     onebee IN D /\ E onebee B /\ etop D E B leq onebee /\
     bname D E B g /\ g IN D /\
     echeck D E onebee b1 vb1 /\ echeck D E onebee b2 vb2 /\ ~(b1 = b2) /\
     zg1 IN D /\ ebv_eq D E B leq g vb1 zg1 /\
     zg2 IN D /\ ebv_eq D E B leq g vb2 zg2 /\
     zm IN D /\ emeet D E B leq zg1 zg2 zm
     ==> ebot D E B leq zm`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `(b1:A) IN D /\ (vb1:A) IN D /\ (b2:A) IN D /\ (vb2:A) IN D`
  STRIP_ASSUME_TAC THENL [ASM_MESON_TAC[ECHECK_IMP]; ALL_TAC] THEN
  SUBGOAL_THEN `eporder D (E:A->A->bool) B leq` ASSUME_TAC THENL
   [ASM_MESON_TAC[ECBA_IMP_BALG; EBALG_IMP_PORDER]; ALL_TAC] THEN
  SUBGOAL_THEN `bname D (E:A->A->bool) B vb1 /\ bname D E B vb2`
  STRIP_ASSUME_TAC THENL
   [CONJ_TAC THENL
     [MATCH_MP_TAC(ISPECL
                   [`D:A->bool`;`E:A->A->bool`;`onebee:A`;`B:A`;`b1:A`;`vb1:A`]
                   ECHECK_IS_BNAME) THEN ASM_REWRITE_TAC[];
      MATCH_MP_TAC(ISPECL
                   [`D:A->bool`;`E:A->A->bool`;`onebee:A`;`B:A`;`b2:A`;`vb2:A`]
                   ECHECK_IS_BNAME) THEN ASM_REWRITE_TAC[]]; ALL_TAC] THEN
  (* ee = [[ vb1 = vb2 ]] *)
  SUBGOAL_THEN
    `?ee. ee IN D /\ (E:A->A->bool) ee B /\ ebv_eq D E B leq vb1 vb2 ee`
  (X_CHOOSE_THEN `ee:A` STRIP_ASSUME_TAC) THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`vb1:A`;`vb2:A`]
                 EBV_EQ_VAL_EXISTS) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `ebot D (E:A->A->bool) B leq ee` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`onebee:A`;
      `b1:A`;`b2:A`;`vb1:A`;`vb2:A`;`ee:A`] ECHECK_EQ_BOT) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* [[ vb1 = g ]] = zg1  by symmetry *)
  SUBGOAL_THEN `ebv_eq D (E:A->A->bool) B leq vb1 g zg1` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`g:A`;
                  `vb1:A`;`zg1:A`]
                 EBV_EQ_SYM) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* zm = meet zg1 zg2 <= ee  by transitivity congruence *)
  SUBGOAL_THEN `erel D (E:A->A->bool) leq zm ee` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`vb1:A`;
                  `g:A`;`vb2:A`;
                  `zg1:A`;`zg2:A`;`ee:A`;`zm:A`] EBV_EQ_CONG) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* zm <= ee = bot ==> zm = ee ==> ebot zm *)
  SUBGOAL_THEN `(E:A->A->bool) zm B` ASSUME_TAC THENL
   [ASM_MESON_TAC[EMEET_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `(zm:A) = ee` (fun th -> ASM_MESON_TAC[th]) THEN
  MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`zm:A`;`ee:A`]
    ELE_BOT) THEN ASM_REWRITE_TAC[]);;

(* ==== F6.5 b3 algebra bridge: INCOMPAT_FROM_MEETBOT ===================
   In the RO-algebra (B, inclB=eincl B, order = inclusion), if x MEET y = bot
   then x,y are INCOMPATIBLE in the ccc poset (bp = B\{empty}, inclB): any
   common lower bound w in bp would satisfy w <= x MEET y = bot = empty, so
   w = empty, contradicting w IN bp.  Bridges VALUE_INCOMPAT (meet = bot) to
   eantichain's ~ecompat. *)

let INCOMPAT_FROM_MEETBOT = prove
 (`!D (E:A->A->bool) P leqp B inclB bp x y zm.
     model D E ZF_AX /\ eleqp D E P leqp /\ eroset D E P leqp B /\
     eincl D E B inclB /\ ebplus D E B bp /\ ecba D E B inclB /\
     x IN D /\ y IN D /\ E x B /\ E y B /\
     zm IN D /\ emeet D E B inclB x y zm /\ ebot D E B inclB zm
     ==> ~ecompat D E bp inclB x y`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `eporder D (E:A->A->bool) B inclB` ASSUME_TAC THENL
   [ASM_MESON_TAC[ECBA_IMP_BALG; EBALG_IMP_PORDER]; ALL_TAC] THEN
  (* zm = empty: the empty set is a bot; ebot is unique *)
  MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`] EEMPTY_EXISTS) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `e0:A`) THEN
  SUBGOAL_THEN `(e0:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[eempty]; ALL_TAC] THEN
  SUBGOAL_THEN `ebot D (E:A->A->bool) B inclB e0` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `P:A`; `leqp:A`; `B:A`;
      `inclB:A`; `e0:A`] EBOT_ROSET) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `eempty D (E:A->A->bool) zm` ASSUME_TAC THENL
   [SUBGOAL_THEN `(zm:A) = e0` (fun th -> ASM_MESON_TAC[th]) THEN
    MATCH_MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `B:A`; `inclB:A`; `zm:A`;
      `e0:A`] EBOT_UNIQUE) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  REWRITE_TAC[ecompat; NOT_EXISTS_THM] THEN X_GEN_TAC `w:A` THEN STRIP_TAC THEN
  SUBGOAL_THEN `(E:A->A->bool) w B /\ ~(eempty D E w)` STRIP_ASSUME_TAC THENL
   [FIRST_ASSUM(MP_TAC o SPEC `w:A` o CONJUNCT2 o REWRITE_RULE[ebplus]) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) inclB w zm` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `B:A`; `inclB:A`; `x:A`;
      `y:A`; `zm:A`; `w:A`] EMEET_GREATEST) THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `(w:A) = zm` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `B:A`; `inclB:A`; `w:A`;
      `zm:A`] ELE_BOT) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  UNDISCH_TAC `~(eempty D (E:A->A->bool) w)` THEN
  ASM_REWRITE_TAC[]);;

(* ==== F6.5 b3: VALUE_ANTICHAIN_PAIR ==================================
   Distinct ordinal-checks give INCOMPATIBLE g-values: [[g=vb1]], [[g=vb2]]
   are ~ecompat in the ccc poset (bp,inclB).  = VALUE_INCOMPAT (meet=bot) +
   INCOMPAT_FROM_MEETBOT.  This is the pairwise-incompatibility feeding
   eantichain for the value-map image. *)

let VALUE_ANTICHAIN_PAIR = prove
 (`!D (E:A->A->bool) P leqp B inclB bp onebee g b1 b2 vb1 vb2 zg1 zg2.
     model D E ZF_AX /\ eleqp D E P leqp /\ eroset D E P leqp B /\
     eincl D E B inclB /\ ebplus D E B bp /\ ecba D E B inclB /\ B IN D /\
     (!u. u IN D ==> elmem D E u) /\
     onebee IN D /\ E onebee B /\ etop D E B inclB onebee /\
     bname D E B g /\ g IN D /\
     echeck D E onebee b1 vb1 /\ echeck D E onebee b2 vb2 /\ ~(b1 = b2) /\
     zg1 IN D /\ ebv_eq D E B inclB g vb1 zg1 /\
     zg2 IN D /\ ebv_eq D E B inclB g vb2 zg2
     ==> ~ecompat D E bp inclB zg1 zg2`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `(b1:A) IN D /\ (vb1:A) IN D /\ (b2:A) IN D /\ (vb2:A) IN D`
  STRIP_ASSUME_TAC THENL [ASM_MESON_TAC[ECHECK_IMP]; ALL_TAC] THEN
  SUBGOAL_THEN `(inclB:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[eincl]; ALL_TAC] THEN
  SUBGOAL_THEN `ebalg D (E:A->A->bool) B inclB` ASSUME_TAC THENL
   [ASM_MESON_TAC[ECBA_IMP_BALG]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) zg1 B /\ (E:A->A->bool) zg2 B`
  STRIP_ASSUME_TAC THENL
   [CONJ_TAC THENL
     [MATCH_MP_TAC(ISPECL
                   [`D:A->bool`;`E:A->A->bool`;`B:A`;`inclB:A`;`g:A`;`vb1:A`;
                    `zg1:A`] EBV_EQ_IN_B) THEN ASM_REWRITE_TAC[];
      MATCH_MP_TAC(ISPECL
                   [`D:A->bool`;`E:A->A->bool`;`B:A`;`inclB:A`;`g:A`;`vb2:A`;
                    `zg2:A`] EBV_EQ_IN_B) THEN ASM_REWRITE_TAC[]];
     ALL_TAC] THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`inclB:A`;`zg1:A`;`zg2:A`]
    EBALG_MEET) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `zm:A`) THEN
  SUBGOAL_THEN `(zm:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[EMEET_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `ebot D (E:A->A->bool) B inclB zm` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`inclB:A`;`onebee:A`;
      `g:A`;`b1:A`;`b2:A`;`vb1:A`;`vb2:A`;`zg1:A`;`zg2:A`;`zm:A`]
        VALUE_INCOMPAT) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MATCH_MP_TAC(ISPECL
               [`D:A->bool`;`E:A->A->bool`;`P:A`;`leqp:A`;`B:A`;`inclB:A`;
                `bp:A`;`zg1:A`;`zg2:A`;`zm:A`] INCOMPAT_FROM_MEETBOT) THEN
  ASM_REWRITE_TAC[]);;

(* ==== F6.5 b3 FIBRE_COUNTABLE: nonzero value-map + antichain + CCC ======
   valuemapnz_form = valuemap_form-body && Not(bbot_form 5 2 63) : the value-
   map restricted to nonzero values z = [[G=beta^]] =/= bot.  Mirror
   HOLDS_VALUEMAP_FORM + EVALMAP_EXISTS with the extra ~ebot conjunct. *)

let valuemapnz_form = new_definition
  `valuemapnz_form Gs vON =
     ?? 62 (?? 63 (?? 80
       (opair_form 62 63 0 && echeck_form vON 62 80 &&
        ebv_eq_form 63 Gs 80 5 &&
        Not(bbot_form 5 2 63))))`;;

let HOLDS_VALUEMAPNZ_FORM = prove
 (`!D (E:A->A->bool) v Gs vON.
      model D E ZF_AX /\ valuation D v /\
      ~(vON = 2) /\ ~(vON = 3) /\ ~(vON = 4) /\ ~(vON = 49) /\ ~(vON = 50) /\
      ~(vON = 51) /\ ~(vON = 62) /\ ~(vON = 63) /\ ~(vON = 80) /\
      ~(Gs = 62) /\ ~(Gs = 63) /\ ~(Gs = 80)
      ==> (holds D E v (valuemapnz_form Gs vON) <=>
           ?bb z vbc. bb IN D /\ z IN D /\ vbc IN D /\
                      eopair D E bb z (v 0) /\ echeck D E (v vON) bb vbc /\
                      ebv_eq D E (v 2) (v 5) (v Gs) vbc z /\
                      ~ebot D E (v 2) (v 5) z)`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `!x. (v:num->A) x IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[valuation]; ALL_TAC] THEN
  REWRITE_TAC[valuemapnz_form] THEN
  SUBGOAL_THEN
   `!bb z vbc:A. bb IN D /\ z IN D /\ vbc IN D
      ==> (holds D E ((80 |-> vbc) ((63 |-> z) ((62 |-> bb) v)))
             (opair_form 62 63 0 && echeck_form vON 62 80 &&
              ebv_eq_form 63 Gs 80 5 && Not(bbot_form 5 2 63)) <=>
           eopair D E bb z (v 0) /\ echeck D E (v vON) bb vbc /\
           ebv_eq D E (v 2) (v 5) (v Gs) vbc z /\ ~ebot D E (v 2) (v 5) z)`
  (LABEL_TAC "body") THENL
   [REPEAT GEN_TAC THEN STRIP_TAC THEN
    SUBGOAL_THEN
     `valuation D ((80 |-> (vbc:A)) ((63 |-> (z:A)) ((62 |-> (bb:A)) v)))`
    ASSUME_TAC THENL [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
    REWRITE_TAC[HOLDS_AND] THEN
    SUBGOAL_THEN
     `holds D E ((80 |-> (vbc:A)) ((63 |-> (z:A)) ((62 |-> (bb:A)) v)))
        (opair_form 62 63 0) <=> eopair D E bb z (v 0)`
    (fun th -> REWRITE_TAC[th]) THENL
     [ASM_SIMP_TAC[HOLDS_OPAIR_FORM] THEN
      ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER; ARITH_EQ]; ALL_TAC] THEN
    SUBGOAL_THEN
     `holds D E ((80 |-> (vbc:A)) ((63 |-> (z:A)) ((62 |-> (bb:A)) v)))
        (echeck_form vON 62 80) <=> echeck D E (v vON) bb vbc`
    (fun th -> REWRITE_TAC[th]) THENL
     [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
        `(80 |-> (vbc:A)) ((63 |-> (z:A)) ((62 |-> (bb:A)) v))`; `vON:num`;
        `62`; `80`] HOLDS_ECHECK_FORM) THEN
      ASM_REWRITE_TAC[ARITH_RULE
        `~(62 = 2) /\ ~(62 = 3) /\ ~(62 = 4) /\ ~(62 = 49) /\ ~(62 = 50) /\
         ~(62 = 51) /\ ~(80 = 2) /\ ~(80 = 3) /\ ~(80 = 4) /\ ~(80 = 49) /\
         ~(80 = 50) /\ ~(80 = 51)`] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
      ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER; ARITH_EQ]; ALL_TAC] THEN
    SUBGOAL_THEN
     `holds D E ((80 |-> (vbc:A)) ((63 |-> (z:A)) ((62 |-> (bb:A)) v)))
        (ebv_eq_form 63 Gs 80 5) <=> ebv_eq D E (v 2) (v 5) (v Gs) vbc z`
    (fun th -> REWRITE_TAC[th]) THENL
     [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
        `(80 |-> (vbc:A)) ((63 |-> (z:A)) ((62 |-> (bb:A)) v))`;
        `63`; `Gs:num`;
        `80`; `5`] HOLDS_EBV_EQ_FORM) THEN
      ASM_REWRITE_TAC[] THEN DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
      ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER; ARITH_EQ]; ALL_TAC] THEN
    REWRITE_TAC[HOLDS_NOT] THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
      `(80 |-> (vbc:A)) ((63 |-> (z:A)) ((62 |-> (bb:A)) v))`; `5`; `2`; `63`]
      HOLDS_BBOT_FORM) THEN
    ASM_REWRITE_TAC[] THEN DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER; ARITH_EQ]; ALL_TAC] THEN
  REWRITE_TAC[HOLDS_EX] THEN EQ_TAC THENL
   [INTRO_TAC "@bb. bbD @z. zD @vbc. vbcD h" THEN
    SUBGOAL_THEN
     `eopair D (E:A->A->bool) bb z ((v:num->A) 0) /\
      echeck D E (v vON) bb vbc /\ ebv_eq D E (v 2) (v 5) (v Gs) vbc z /\
      ~ebot D E (v 2) (v 5) z`
    STRIP_ASSUME_TAC THENL
     [USE_THEN "body" (MP_TAC o SPECL [`bb:A`; `z:A`; `vbc:A`]) THEN
      ANTS_TAC THENL
       [ASM_REWRITE_TAC[];
        DISCH_THEN(fun th -> REWRITE_TAC[GSYM th]) THEN
        FIRST_ASSUM ACCEPT_TAC];
      ALL_TAC] THEN
    MAP_EVERY EXISTS_TAC [`bb:A`; `z:A`; `vbc:A`] THEN ASM_REWRITE_TAC[];
    DISCH_THEN(X_CHOOSE_THEN `bb:A` (X_CHOOSE_THEN `z:A`
      (X_CHOOSE_THEN `vbc:A` STRIP_ASSUME_TAC))) THEN
    EXISTS_TAC `bb:A` THEN CONJ_TAC THENL
    [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    EXISTS_TAC `z:A` THEN CONJ_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    EXISTS_TAC `vbc:A` THEN CONJ_TAC THENL
    [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    USE_THEN "body" (MP_TAC o SPECL [`bb:A`; `z:A`; `vbc:A`]) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[];
      DISCH_THEN(fun th -> ONCE_REWRITE_TAC[th]) THEN ASM_REWRITE_TAC[]]]);;

(* EVALMAPNZ_EXISTS: nonzero value-map c' = { <beta,[[G=beta^]]> : beta<a1,
   [[G=beta^]]=/=bot }.  Mirror EVALMAP_EXISTS with valuemapnz_form. *)
let EVALMAPNZ_EXISTS = prove
 (`!D (E:A->A->bool) a1 B leq G onebee.
     model D E ZF_AX /\ a1 IN D /\ B IN D /\ leq IN D /\ G IN D /\ onebee IN D
     ==> ?h. h IN D /\
             !q. q IN D
                 ==> (E q h <=>
                      ?bb z vbc. bb IN D /\ z IN D /\ vbc IN D /\
                                 E bb a1 /\ E z B /\ eopair D E bb z q /\
                                 echeck D E onebee bb vbc /\
                                 ebv_eq D E B leq G vbc z /\
                                 ~ebot D E B leq z)`,
  REPEAT STRIP_TAC THEN
  MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `a1:A`; `B:A`]
         ECROSS_EXISTS) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `cr:A` (LABEL_TAC "cr")) THEN
  SUBGOAL_THEN `(cr:A) IN D` ASSUME_TAC THENL
  [ASM_MESON_TAC[ecross]; ALL_TAC] THEN
  ABBREV_TAC
   `v0 = (81 |-> (G:A)) ((90 |-> (onebee:A))
           ((5 |-> (leq:A)) ((2 |-> (B:A)) (\n:num. a1:A))))` THEN
  SUBGOAL_THEN `valuation D (v0:num->A)` ASSUME_TAC THENL
   [EXPAND_TAC "v0" THEN
    REPEAT(MATCH_MP_TAC VALUATION_VALMOD THEN
           CONJ_TAC THENL [ALL_TAC; FIRST_ASSUM ACCEPT_TAC]) THEN
    REWRITE_TAC[valuation] THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN
   `v0 2 = B /\ v0 5 = leq /\ v0 81 = G /\ v0 90 = (onebee:A)`
  STRIP_ASSUME_TAC THENL
   [EXPAND_TAC "v0" THEN REPEAT CONJ_TAC THEN
    ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER; ARITH_EQ]; ALL_TAC] THEN
  MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`] ZF_SEPARATION) THEN
  ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  DISCH_THEN(MP_TAC o ISPECL
    [`valuemapnz_form 81 90`; `0`; `v0:num->A`; `cr:A`]) THEN
  ANTS_TAC THENL
   [CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
    DISCH_THEN(X_CHOOSE_THEN `h:A`
      (CONJUNCTS_THEN2 ASSUME_TAC (LABEL_TAC "sep")))] THEN
  EXISTS_TAC `h:A` THEN ASM_REWRITE_TAC[] THEN
  X_GEN_TAC `q:A` THEN DISCH_TAC THEN
  MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `a1:A`; `B:A`; `cr:A`; `q:A`]
    ECROSS_MEMBER) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(LABEL_TAC "crm") THEN
  SUBGOAL_THEN `valuation D ((0 |-> (q:A)) v0)` ASSUME_TAC THENL
   [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `(0 |-> (q:A)) v0`; `81`; `90`]
    HOLDS_VALUEMAPNZ_FORM) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[ARITH_RULE
     `~(90 = 2) /\ ~(90 = 3) /\ ~(90 = 4) /\ ~(90 = 49) /\ ~(90 = 50) /\
      ~(90 = 51) /\ ~(90 = 62) /\ ~(90 = 63) /\ ~(90 = 80) /\
      ~(81 = 62) /\ ~(81 = 63) /\ ~(81 = 80)`]; ALL_TAC] THEN
  ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER; ARITH_EQ] THEN
  DISCH_THEN(LABEL_TAC "hc") THEN
  USE_THEN "sep" (MP_TAC o SPEC `q:A`) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN DISCH_THEN SUBST1_TAC THEN
  USE_THEN "crm" (fun t1 -> USE_THEN "hc" (fun t2 -> REWRITE_TAC[t1; t2])) THEN
  EQ_TAC THENL
   [DISCH_THEN(CONJUNCTS_THEN2
      (X_CHOOSE_THEN `u:A` (X_CHOOSE_THEN `w:A` STRIP_ASSUME_TAC))
      (X_CHOOSE_THEN `bb:A` (X_CHOOSE_THEN `z:A` (X_CHOOSE_THEN `vbc:A`
        STRIP_ASSUME_TAC)))) THEN
    MP_TAC(ISPECL
           [`D:A->bool`; `E:A->A->bool`; `bb:A`; `z:A`; `u:A`; `w:A`; `q:A`]
           EOPAIR_INJ) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(CONJUNCTS_THEN SUBST_ALL_TAC) THEN
    MAP_EVERY EXISTS_TAC [`u:A`; `w:A`; `vbc:A`] THEN ASM_REWRITE_TAC[];
    DISCH_THEN(X_CHOOSE_THEN `bb:A` (X_CHOOSE_THEN `z:A` (X_CHOOSE_THEN `vbc:A`
      STRIP_ASSUME_TAC))) THEN
    CONJ_TAC THENL
     [MAP_EVERY EXISTS_TAC [`bb:A`; `z:A`] THEN ASM_REWRITE_TAC[];
      MAP_EVERY EXISTS_TAC [`bb:A`; `z:A`; `vbc:A`] THEN ASM_REWRITE_TAC[]]]);;

(* aproj_form Cs = ?? 62 (apply_form Cs 62 0) : t is in the 2nd-projection
   (range) of c'.  Slot 0 = t, 62 = beta, Cs = c'-slot. *)
let aproj_form = new_definition
  `aproj_form Cs = ?? 62 (apply_form Cs 62 0)`;;

let HOLDS_APROJ_FORM = prove
 (`!D (E:A->A->bool) v Cs.
      valuation D v /\ ~(Cs = 62) /\ ~(Cs = 0)
      ==> (holds D E v (aproj_form Cs) <=>
           ?bet. bet IN D /\ eapply D E (v Cs) bet (v 0))`,
  REPEAT GEN_TAC THEN DISCH_THEN STRIP_ASSUME_TAC THEN
  SUBGOAL_THEN `!x. (v:num->A) x IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[valuation]; ALL_TAC] THEN
  REWRITE_TAC[aproj_form] THEN
  GEN_REWRITE_TAC LAND_CONV [HOLDS_EX] THEN
  MATCH_MP_TAC(MESON[]
    `(!bet:A. bet IN D ==> (P bet <=> Q bet))
     ==> ((?bet. bet IN D /\ P bet) <=> (?bet. bet IN D /\ Q bet))`) THEN
  X_GEN_TAC `bet:A` THEN DISCH_TAC THEN
  SUBGOAL_THEN `valuation D ((62 |-> (bet:A)) v)` ASSUME_TAC THENL
   [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
  MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `(62 |-> (bet:A)) v`; `Cs:num`;
    `62`; `0`] HOLDS_APPLY_FORM) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER; ARITH_EQ]);;

let EAPROJ_EXISTS = prove
 (`!D (E:A->A->bool) B cp.
     model D E ZF_AX /\ B IN D /\ cp IN D
     ==> ?a. a IN D /\
             !t. t IN D
                 ==> (E t a <=> E t B /\ ?bet. bet IN D /\
                      eapply D E cp bet t)`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  FIRST_ASSUM(X_CHOOSE_TAC `v00:num->A` o MATCH_MP VALUATION_EXISTS o
    MATCH_MP MODEL_NONEMPTY) THEN
  ABBREV_TAC `v0 = (91 |-> (cp:A)) v00` THEN
  SUBGOAL_THEN `valuation D (v0:num->A)` ASSUME_TAC THENL
   [EXPAND_TAC "v0" THEN MATCH_MP_TAC VALUATION_VALMOD THEN
    CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  SUBGOAL_THEN `(v0:num->A) 91 = cp` ASSUME_TAC THENL
   [EXPAND_TAC "v0" THEN REWRITE_TAC[VALMOD_BASIC]; ALL_TAC] THEN
  MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`] ZF_SEPARATION) THEN
  ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  DISCH_THEN(MP_TAC o ISPECL [`aproj_form 91`; `0`; `v0:num->A`; `B:A`]) THEN
  ANTS_TAC THENL
   [CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
    DISCH_THEN(X_CHOOSE_THEN `a:A`
      (CONJUNCTS_THEN2 ASSUME_TAC (LABEL_TAC "sep")))] THEN
  EXISTS_TAC `a:A` THEN
  CONJ_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  X_GEN_TAC `t:A` THEN DISCH_TAC THEN
  USE_THEN "sep" (MP_TAC o SPEC `t:A`) THEN
  ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  DISCH_THEN SUBST1_TAC THEN
  MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `(0 |-> (t:A)) v0`; `91`]
    HOLDS_APROJ_FORM) THEN
  ANTS_TAC THENL
   [ASM_SIMP_TAC[VALUATION_VALMOD; ARITH_RULE `~(91 = 62) /\ ~(91 = 0)`];
    ALL_TAC] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER; ARITH_EQ]);;

(* ==== F6.5 b3 CAPSTONE: FIBRE_COUNTABLE ================================
   For a name G in the Cohen RO-ccc algebra (bp,inclB), the "fibre"
     X = { beta < a1 : [[ G = beta-check ]] =/= bot }
   is COUNTABLE (injects into omega).  Proof: the nonzero value-map
   c' = { <beta,[[G=beta^]]> : beta<a1, value=/=bot } (EVALMAPNZ_EXISTS)
   is an INJECTION of X = dom(c') into a = ran(c') (2nd-projection,
   EAPROJ_EXISTS), and a is an ANTICHAIN in (bp,inclB) (VALUE_ANTICHAIN_PAIR),
   so by ccc (CCC_ANTICHAIN_DOM) X injects into omega. *)

let FIBRE_COUNTABLE = prove
 (`!D (E:A->A->bool) P leqp B inclB bp onebee a1 G.
     model D E ZF_AX /\ eleqp D E P leqp /\ eroset D E P leqp B /\
     eincl D E B inclB /\ ebplus D E B bp /\ ecba D E B inclB /\
     eccc D E bp inclB /\ B IN D /\
     (!u. u IN D ==> elmem D E u) /\
     onebee IN D /\ E onebee B /\ etop D E B inclB onebee /\
     a1 IN D /\ G IN D /\ bname D E B G
     ==> ?X. X IN D /\
             (!bet. bet IN D
                    ==> (E bet X <=>
                         E bet a1 /\
                         ?vbc z. z IN D /\
                                 echeck D E onebee bet vbc /\
                                 ebv_eq D E B inclB G vbc z /\
                                 ~ebot D E B inclB z)) /\
             (?om e. eomega D E om /\ einj D E e X om)`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `(inclB:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[eincl]; ALL_TAC] THEN
  SUBGOAL_THEN `(bp:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[ebplus]; ALL_TAC] THEN
  SUBGOAL_THEN `eporder D (E:A->A->bool) B inclB` ASSUME_TAC THENL
   [ASM_MESON_TAC[ECBA_IMP_BALG; EBALG_IMP_PORDER]; ALL_TAC] THEN
  (* ---- c' = nonzero value-map, with characterization "cprop" ---- *)
  MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `a1:A`; `B:A`; `inclB:A`; `G:A`;
    `onebee:A`] EVALMAPNZ_EXISTS) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `cp:A`
    (CONJUNCTS_THEN2 ASSUME_TAC (LABEL_TAC "cprop"))) THEN
  (* ---- app: eapply cp characterization (guarded by k,t IN D) ---- *)
  SUBGOAL_THEN
   `!k t:A. k IN D /\ t IN D
            ==> (eapply D E cp k t <=>
                 E k a1 /\ E t B /\
                 ?vbc. echeck D E onebee k vbc /\
                       ebv_eq D E B inclB G vbc t /\ ~ebot D E B inclB t)`
  (LABEL_TAC "app") THENL
   [REPEAT GEN_TAC THEN STRIP_TAC THEN REWRITE_TAC[eapply] THEN EQ_TAC THENL
     [DISCH_THEN(X_CHOOSE_THEN `q:A` STRIP_ASSUME_TAC) THEN
      SUBGOAL_THEN `(q:A) IN D` ASSUME_TAC THENL
       [ASM_MESON_TAC[EOPAIR_IN]; ALL_TAC] THEN
      USE_THEN "cprop" (MP_TAC o SPEC `q:A`) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun bic ->
                 MP_TAC(EQ_MP bic (ASSUME `(E:A->A->bool) q cp`))) THEN
      DISCH_THEN(X_CHOOSE_THEN `bb:A` (X_CHOOSE_THEN `z:A`
        (X_CHOOSE_THEN `vbc:A` STRIP_ASSUME_TAC))) THEN
      MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `k:A`; `t:A`; `bb:A`; `z:A`;
        `q:A`] EOPAIR_INJ) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(CONJUNCTS_THEN(SUBST_ALL_TAC o SYM)) THEN
      ASM_REWRITE_TAC[] THEN EXISTS_TAC `vbc:A` THEN ASM_REWRITE_TAC[];
      STRIP_TAC THEN
      SUBGOAL_THEN `(vbc:A) IN D` ASSUME_TAC THENL
       [ASM_MESON_TAC[ECHECK_IMP]; ALL_TAC] THEN
      MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `k:A`; `t:A`]
             EOPAIR_EXISTS) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(X_CHOOSE_THEN `q:A` ASSUME_TAC) THEN
      SUBGOAL_THEN `(q:A) IN D` ASSUME_TAC THENL
       [ASM_MESON_TAC[EOPAIR_IN]; ALL_TAC] THEN
      EXISTS_TAC `q:A` THEN ASM_REWRITE_TAC[] THEN
      USE_THEN "cprop" (MP_TAC o SPEC `q:A`) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
      MAP_EVERY EXISTS_TAC [`k:A`; `t:A`; `vbc:A`] THEN ASM_REWRITE_TAC[]];
    ALL_TAC] THEN
  (* ---- X = dom(c') ---- *)
  MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `cp:A`] EDOMAIN_EXISTS) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `X:A` (MP_TAC o REWRITE_RULE[edomain])) THEN
  DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC (LABEL_TAC "Xdom")) THEN
  (* ---- a = ran(c') (2nd projection) ---- *)
  MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `B:A`; `cp:A`]
         EAPROJ_EXISTS) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `a:A`
    (CONJUNCTS_THEN2 ASSUME_TAC (LABEL_TAC "aprop"))) THEN
  (* ---- X-membership characterization (guarded, for the conclusion) ---- *)
  SUBGOAL_THEN
   `!bet:A. bet IN D
            ==> (E bet X <=>
                 E bet a1 /\
                 ?vbc z. z IN D /\
                         echeck D E onebee bet vbc /\
                         ebv_eq D E B inclB G vbc z /\ ~ebot D E B inclB z)`
  (LABEL_TAC "Xchar") THENL
   [X_GEN_TAC `bet:A` THEN DISCH_TAC THEN
    SUBGOAL_THEN `(E:A->A->bool) bet X <=> eindom D E cp bet` SUBST1_TAC THENL
     [USE_THEN "Xdom" (fun th -> MATCH_MP_TAC(SPEC `bet:A` th)) THEN
      ASM_REWRITE_TAC[]; ALL_TAC] THEN
    REWRITE_TAC[eindom] THEN EQ_TAC THENL
     [DISCH_THEN(X_CHOOSE_THEN `w:A` STRIP_ASSUME_TAC) THEN
      USE_THEN "app" (fun th -> MP_TAC(SPECL [`bet:A`; `w:A`] th)) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th ->
        MP_TAC(EQ_MP th (ASSUME `eapply D (E:A->A->bool) cp bet w`))) THEN
      STRIP_TAC THEN ASM_REWRITE_TAC[] THEN
      MAP_EVERY EXISTS_TAC [`vbc:A`; `w:A`] THEN ASM_REWRITE_TAC[];
      DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC
        (X_CHOOSE_THEN `vbc:A` (X_CHOOSE_THEN `z:A` STRIP_ASSUME_TAC))) THEN
      EXISTS_TAC `z:A` THEN ASM_REWRITE_TAC[] THEN
      USE_THEN "app" (fun th -> MP_TAC(SPECL [`bet:A`; `z:A`] th)) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
      SUBGOAL_THEN `(vbc:A) IN D` ASSUME_TAC THENL
       [ASM_MESON_TAC[ECHECK_IMP]; ALL_TAC] THEN
      SUBGOAL_THEN `(E:A->A->bool) z B` ASSUME_TAC THENL
       [MATCH_MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `B:A`; `inclB:A`;
          `G:A`; `vbc:A`; `z:A`] EBV_EQ_IN_B) THEN ASM_REWRITE_TAC[];
        ALL_TAC] THEN
      ASM_REWRITE_TAC[] THEN EXISTS_TAC `vbc:A` THEN ASM_REWRITE_TAC[]];
    ALL_TAC] THEN
  EXISTS_TAC `X:A` THEN
  CONJ_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  CONJ_TAC THENL [USE_THEN "Xchar" ACCEPT_TAC; ALL_TAC] THEN
  (* ======================= the countability ======================= *)
  MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `bp:A`; `inclB:A`; `X:A`; `a:A`;
    `cp:A`] CCC_ANTICHAIN_DOM) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN MATCH_MP_TAC THEN
  (* ---- einj cp X a ---- *)
  CONJ_TAC THENL
   [REWRITE_TAC[einj] THEN REPEAT CONJ_TAC THENL
     [(* f IN D *) ASM_REWRITE_TAC[];
      (* maps-into *)
      MAP_EVERY X_GEN_TAC [`k:A`; `t:A`] THEN STRIP_TAC THEN
      SUBGOAL_THEN
       `(E:A->A->bool) k a1 /\ E t B /\
        ?vbc. echeck D E onebee k vbc /\
              ebv_eq D E B inclB G vbc t /\ ~ebot D E B inclB t`
      MP_TAC THENL
       [USE_THEN "app" (fun th -> MP_TAC(SPECL [`k:A`; `t:A`] th)) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
        DISCH_THEN(fun th -> REWRITE_TAC[GSYM th]) THEN ASM_REWRITE_TAC[];
        ALL_TAC] THEN
      STRIP_TAC THEN CONJ_TAC THENL
       [USE_THEN "Xchar" (fun th -> MP_TAC(SPEC `k:A` th)) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
        DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
        ASM_REWRITE_TAC[] THEN MAP_EVERY EXISTS_TAC [`vbc:A`; `t:A`] THEN
        ASM_REWRITE_TAC[];
        USE_THEN "aprop" (MP_TAC o SPEC `t:A`) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
        DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
        CONJ_TAC THENL
         [FIRST_ASSUM ACCEPT_TAC;
          EXISTS_TAC `k:A` THEN CONJ_TAC THENL
           [ASM_REWRITE_TAC[]; FIRST_ASSUM ACCEPT_TAC]]];
      (* total *)
      X_GEN_TAC `k:A` THEN STRIP_TAC THEN
      USE_THEN "Xchar" (fun th -> MP_TAC(SPEC `k:A` th)) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> MP_TAC(EQ_MP th (ASSUME `(E:A->A->bool) k X`))) THEN
      STRIP_TAC THEN
      SUBGOAL_THEN `(vbc:A) IN D` ASSUME_TAC THENL
       [ASM_MESON_TAC[ECHECK_IMP]; ALL_TAC] THEN
      SUBGOAL_THEN `(E:A->A->bool) z B` ASSUME_TAC THENL
       [MATCH_MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `B:A`; `inclB:A`;
          `G:A`; `vbc:A`; `z:A`] EBV_EQ_IN_B) THEN ASM_REWRITE_TAC[];
         ALL_TAC] THEN
      SUBGOAL_THEN `eapply D (E:A->A->bool) cp k z` ASSUME_TAC THENL
       [USE_THEN "app" (fun th -> MP_TAC(SPECL [`k:A`; `z:A`] th)) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
        DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
        ASM_REWRITE_TAC[] THEN EXISTS_TAC `vbc:A` THEN ASM_REWRITE_TAC[];
        ALL_TAC] THEN
      EXISTS_TAC `z:A` THEN REPEAT CONJ_TAC THENL
       [ASM_REWRITE_TAC[];
        USE_THEN "aprop" (MP_TAC o SPEC `z:A`) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
        DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
        CONJ_TAC THENL
         [FIRST_ASSUM ACCEPT_TAC;
          EXISTS_TAC `k:A` THEN CONJ_TAC THENL
           [ASM_REWRITE_TAC[]; FIRST_ASSUM ACCEPT_TAC]];
        FIRST_ASSUM ACCEPT_TAC];
      (* functional *)
      MAP_EVERY X_GEN_TAC [`k:A`; `t:A`; `t':A`] THEN STRIP_TAC THEN
      SUBGOAL_THEN
       `(?vbc. echeck D (E:A->A->bool) onebee k vbc /\
                ebv_eq D E B inclB G vbc t) /\
        (?vbc. echeck D E onebee k vbc /\ ebv_eq D E B inclB G vbc t')`
      MP_TAC THENL
       [CONJ_TAC THEN ASM_MESON_TAC[]; ALL_TAC] THEN
      DISCH_THEN(CONJUNCTS_THEN2
        (X_CHOOSE_THEN `vc:A` STRIP_ASSUME_TAC)
        (X_CHOOSE_THEN `vc':A` STRIP_ASSUME_TAC)) THEN
      SUBGOAL_THEN `(vc:A) = vc'` SUBST_ALL_TAC THENL
       [MATCH_MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `onebee:A`; `k:A`;
          `vc:A`; `vc':A`] ECHECK_SV) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
      SUBGOAL_THEN `(vc':A) IN D` ASSUME_TAC THENL
       [ASM_MESON_TAC[ECHECK_IMP]; ALL_TAC] THEN
      MATCH_MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `B:A`; `inclB:A`;
        `G:A`; `vc':A`; `t:A`; `t':A`] EBV_EQ_UNIQUE) THEN ASM_REWRITE_TAC[];
      (* injective *)
      MAP_EVERY X_GEN_TAC [`k:A`; `k':A`; `t:A`] THEN STRIP_TAC THEN
      SUBGOAL_THEN
       `(?vbc. echeck D (E:A->A->bool) onebee k vbc /\
                ebv_eq D E B inclB G vbc t /\ ~ebot D E B inclB t) /\
        (?vbc. echeck D E onebee k' vbc /\ ebv_eq D E B inclB G vbc t)`
      MP_TAC THENL
       [CONJ_TAC THEN ASM_MESON_TAC[]; ALL_TAC] THEN
      DISCH_THEN(CONJUNCTS_THEN2
        (X_CHOOSE_THEN `vc:A` STRIP_ASSUME_TAC)
        (X_CHOOSE_THEN `vc':A` STRIP_ASSUME_TAC)) THEN
      SUBGOAL_THEN `(vc:A) IN D` ASSUME_TAC THENL
       [ASM_MESON_TAC[ECHECK_IMP]; ALL_TAC] THEN
      SUBGOAL_THEN `(E:A->A->bool) t B` ASSUME_TAC THENL
       [MATCH_MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `B:A`; `inclB:A`;
          `G:A`; `vc:A`; `t:A`] EBV_EQ_IN_B) THEN ASM_REWRITE_TAC[];
        ALL_TAC] THEN
      ASM_CASES_TAC `(k:A) = k'` THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
      SUBGOAL_THEN `~ecompat D (E:A->A->bool) bp inclB t t` ASSUME_TAC THENL
       [MATCH_MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `P:A`; `leqp:A`;
          `B:A`; `inclB:A`; `bp:A`; `onebee:A`; `G:A`; `k:A`; `k':A`; `vc:A`;
          `vc':A`; `t:A`; `t:A`] VALUE_ANTICHAIN_PAIR) THEN ASM_REWRITE_TAC[];
        ALL_TAC] THEN
      SUBGOAL_THEN `~eempty D (E:A->A->bool) t` ASSUME_TAC THENL
       [STRIP_TAC THEN
        SUBGOAL_THEN `ebot D (E:A->A->bool) B inclB t` MP_TAC THENL
         [MATCH_MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `P:A`; `leqp:A`;
            `B:A`; `inclB:A`; `t:A`] EBOT_ROSET) THEN ASM_REWRITE_TAC[];
          ASM_REWRITE_TAC[]];
        ALL_TAC] THEN
      SUBGOAL_THEN `(E:A->A->bool) t bp` ASSUME_TAC THENL
       [UNDISCH_TAC `ebplus D (E:A->A->bool) B bp` THEN
        REWRITE_TAC[ebplus] THEN
        DISCH_THEN(MP_TAC o SPEC `t:A` o CONJUNCT2) THEN ASM_REWRITE_TAC[];
        ALL_TAC] THEN
      SUBGOAL_THEN `erel D (E:A->A->bool) inclB t t` ASSUME_TAC THENL
       [MATCH_MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `B:A`; `inclB:A`;
          `t:A`] EPORDER_REFL) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
      SUBGOAL_THEN `ecompat D (E:A->A->bool) bp inclB t t` ASSUME_TAC THENL
       [REWRITE_TAC[ecompat] THEN EXISTS_TAC `t:A` THEN ASM_REWRITE_TAC[];
        ASM_MESON_TAC[]]];
    (* ---- eantichain bp inclB a ---- *)
    REWRITE_TAC[eantichain] THEN REPEAT CONJ_TAC THENL
     [(* a IN D *) ASM_REWRITE_TAC[];
      (* esubset a bp *)
      REWRITE_TAC[esubset] THEN X_GEN_TAC `t:A` THEN STRIP_TAC THEN
      SUBGOAL_THEN
       `(E:A->A->bool) t B /\ ?bet. E bet a1 /\ eapply D E cp bet t`
      MP_TAC THENL [ASM_MESON_TAC[]; ALL_TAC] THEN
      DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC
        (X_CHOOSE_THEN `bet:A` STRIP_ASSUME_TAC)) THEN
      SUBGOAL_THEN `~ebot D (E:A->A->bool) B inclB t` ASSUME_TAC THENL
       [ASM_MESON_TAC[]; ALL_TAC] THEN
      SUBGOAL_THEN `~eempty D (E:A->A->bool) t` ASSUME_TAC THENL
       [STRIP_TAC THEN
        SUBGOAL_THEN `ebot D (E:A->A->bool) B inclB t` MP_TAC THENL
         [MATCH_MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `P:A`; `leqp:A`;
            `B:A`; `inclB:A`; `t:A`] EBOT_ROSET) THEN ASM_REWRITE_TAC[];
          ASM_REWRITE_TAC[]];
        ALL_TAC] THEN
      UNDISCH_TAC `ebplus D (E:A->A->bool) B bp` THEN REWRITE_TAC[ebplus] THEN
      DISCH_THEN(MP_TAC o SPEC `t:A` o CONJUNCT2) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
      CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
      (* pairwise incompatible *)
      MAP_EVERY X_GEN_TAC [`t1:A`; `t2:A`] THEN STRIP_TAC THEN
      SUBGOAL_THEN
       `(?bet vbc. echeck D (E:A->A->bool) onebee bet vbc /\
                   ebv_eq D E B inclB G vbc t1 /\ eapply D E cp bet t1) /\
        (?bet vbc. echeck D E onebee bet vbc /\
                   ebv_eq D E B inclB G vbc t2 /\ eapply D E cp bet t2)`
      MP_TAC THENL [CONJ_TAC THEN ASM_MESON_TAC[]; ALL_TAC] THEN
      DISCH_THEN(CONJUNCTS_THEN2
        (X_CHOOSE_THEN `b1:A` (X_CHOOSE_THEN `vc1:A` STRIP_ASSUME_TAC))
        (X_CHOOSE_THEN `b2:A` (X_CHOOSE_THEN `vc2:A` STRIP_ASSUME_TAC))) THEN
      SUBGOAL_THEN `~(b1:A = b2)` ASSUME_TAC THENL
       [DISCH_THEN SUBST_ALL_TAC THEN
        UNDISCH_TAC `~(t1:A = t2)` THEN REWRITE_TAC[] THEN
        SUBGOAL_THEN `(vc1:A) = vc2` SUBST_ALL_TAC THENL
         [MATCH_MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `onebee:A`; `b2:A`;
            `vc1:A`; `vc2:A`] ECHECK_SV) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
        SUBGOAL_THEN `(vc2:A) IN D` ASSUME_TAC THENL
         [ASM_MESON_TAC[ECHECK_IMP]; ALL_TAC] THEN
        MATCH_MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `B:A`; `inclB:A`;
          `G:A`; `vc2:A`; `t1:A`; `t2:A`] EBV_EQ_UNIQUE) THEN
        ASM_REWRITE_TAC[]; ALL_TAC] THEN
      MATCH_MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `P:A`; `leqp:A`;
        `B:A`; `inclB:A`; `bp:A`; `onebee:A`; `G:A`; `b1:A`; `b2:A`; `vc1:A`;
        `vc2:A`; `t1:A`; `t2:A`] VALUE_ANTICHAIN_PAIR) THEN
      ASM_REWRITE_TAC[]]]);;

(* ==== F7.2-a: existential Boolean value is the sup; positivity ==========
   [[ ?? n p ]]_v is the least upper bound of { [[ p[a/n] ]]_v : a bname }
   (BVALF_EX_UB / BVALF_EX_LEAST).  Hence:
     ALLBOT: every disjunct value = bot  ==>  [[ ?? n p ]] = bot.
     POS   : [[ ?? n p ]] =/= bot  ==>  some disjunct value =/= bot.
   These drive the onto ==> covering step of F7.2. *)

(* ==== F7.2-b core: VALNAME_COVER_STEP ==================================
   The functionality-positivity heart of the value-name lemma, isolated from
   the MAXPRIN plumbing.  If a condition d (=/= bot) forces
     (i)  p is single-valued in y   ( ?? z !! y. p --> y=z )
     (ii) p(Gn)      ( [[ p[Gn/y] ]] )
     (iii)p(betc)    ( [[ p[betc/y] ]] )
   then  [[ Gn = betc ]]  is =/= bot.
   (With p(y) := "<n^,y> IN f":  d forces f single-valued at n^, <n^,Gn> IN f,
   <n^,betc> IN f  ==>
     [[Gn = betc]] =/= bot.  This is the covering positivity.)
   PROOF: FUNC_EQ_FULL gives d <= [[Gn=betc]] = e; if ebot e then e=bot
   (EBOT_UNIQUE), so d <= bot,
   so d = bot (ELE_BOT) -- contradicts d =/= bot. *)

let VALNAME_COVER_STEP = prove
 (`!D (E:A->A->bool) B leq v0 p y z Gn betc d e bot.
      model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
      valuation D v0 /\ (!i. bname D E B (v0 i)) /\
      bname D E B Gn /\ bname D E B betc /\ Gn IN D /\ betc IN D /\
      ~(z IN FV p) /\ ~(y = z) /\
      d IN D /\ E d B /\ e IN D /\
      ebot D E B leq bot /\ ~(d = bot) /\
      ebv_eq D E B leq Gn betc e /\
      erel D E leq d (bvalf D E B leq v0 (?? z (!! y (p --> Eq y z)))) /\
      erel D E leq d (bvalf D E B leq ((y |-> Gn) v0) p) /\
      erel D E leq d (bvalf D E B leq ((y |-> betc) v0) p)
      ==> ~ebot D E B leq e`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `eporder D (E:A->A->bool) B leq` ASSUME_TAC THENL
   [ASM_MESON_TAC[ECBA_IMP_BALG; EBALG_IMP_PORDER]; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq d e` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL
      [`D:A->bool`; `E:A->A->bool`; `B:A`; `leq:A`; `v0:num->A`; `p:form`;
       `y:num`; `z:num`; `Gn:A`; `betc:A`; `d:A`; `e:A`] FUNC_EQ_FULL) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MATCH_MP_TAC(TAUT `(q ==> F) ==> ~q`) THEN DISCH_TAC THEN
  SUBGOAL_THEN `(e:A) = bot` SUBST_ALL_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`; `E:A->A->bool`; `B:A`; `leq:A`; `e:A`; `bot:A`]
                 EBOT_UNIQUE) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(d:A) = bot` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`; `E:A->A->bool`; `B:A`; `leq:A`; `d:A`; `bot:A`]
                 ELE_BOT) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  ASM_MESON_TAC[]);;

(* ==== F7.2-b existence: VALNAME_EXISTS =================================
   The value-name of f at the argument in slot 70, via the maximum principle.
   pmem := ?? 73 (opair_form 70 71 73 && (73 %% 72))  =  "<v 70, v 71> IN v 72"
   [ slot 70 = argument aa, 71 = value y, 72 = function f,
   73 = the pair (bound) ].
   MAXPRIN_EX at (n:=71, p:=pmem) yields a bname Gn = f(aa) with
     [[ <aa,Gn> IN f ]] = bvalf ((71|->Gn)v0) pmem
                        = bvalf v0 (?? 71 pmem) = [[ ?y. <aa,y> IN f ]] =
                          [[aa IN dom f]].
   No BVALF interpretation of pmem needed: VALNAME_COVER_STEP consumes the pmem
   values symbolically.  This is a thin MAXPRIN wrapper fixing the
     slot layout. *)

let VALNAME_EXISTS = prove
 (`!D (E:A->A->bool) B leq v0.
      model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
      valuation D v0 /\ (!i. bname D E B (v0 i)) /\
        (!u. u IN D ==> elmem D E u)
      ==> ?Gn. Gn IN D /\ bname D E B Gn /\
          bvalf D E B leq ((71 |-> Gn) v0)
                          (?? 73 (opair_form 70 71 73 && (73 %% 72))) =
          bvalf D E B leq v0
                (?? 71 (?? 73 (opair_form 70 71 73 && (73 %% 72))))`,
  REPEAT STRIP_TAC THEN
  MATCH_MP_TAC(ISPECL
    [`71`; `?? 73 (opair_form 70 71 73 && (73 %% 72))`;
     `D:A->bool`; `E:A->A->bool`; `B:A`; `leq:A`; `v0:num->A`] MAXPRIN_EX) THEN
  ASM_REWRITE_TAC[]);;

(* ==== F7.2-c core: VALNAME_COVER_ONE ==================================
   Per-hit covering positivity.  pm := ?? 73 (opair_form 70 71 73
     && (73 %% 72))
   [ = "<v70,v71> IN v72" ; slot 70=arg aa, 71=value,
   72=f ].  Given the value-name
   equation ([[pm[Gn]]] = [[?? 71 pm]] from VALNAME_EXISTS),
   a condition d =/= bot
   with d <= [[pm single-valued]] and d <= [[pm[betc]]] (betc hit at aa), then
   [[Gn = betc]] =/= bot.  KEY: d <= [[pm[Gn]]] is DERIVED, not assumed --
   d <= [[pm[betc]]] <= [[?? 71 pm]] (BVALF_EX_UB) = [[pm[Gn]]]
     (value-name eqn).
   Then VALNAME_COVER_STEP.  Packages the caller away from proving
     d<=[[pm[Gn]]]. *)

let VALNAME_COVER_ONE = prove
 (`!D (E:A->A->bool) B leq v0 Gn betc d e bot.
      model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
      valuation D v0 /\ (!i. bname D E B (v0 i)) /\
      bname D E B Gn /\ bname D E B betc /\ Gn IN D /\ betc IN D /\
      d IN D /\ E d B /\ e IN D /\ ebot D E B leq bot /\ ~(d = bot) /\
      ebv_eq D E B leq Gn betc e /\
      bvalf D E B leq ((71 |-> Gn) v0)
            (?? 73 (opair_form 70 71 73 && (73 %% 72))) =
      bvalf D E B leq v0
            (?? 71 (?? 73 (opair_form 70 71 73 && (73 %% 72)))) /\
      erel D E leq d (bvalf D E B leq v0
            (?? 74 (!! 71
                    ((?? 73 (opair_form 70 71 73 && (73 %% 72))) -->
                     Eq 71 74)))) /\
      erel D E leq d (bvalf D E B leq ((71 |-> betc) v0)
            (?? 73 (opair_form 70 71 73 && (73 %% 72))))
      ==> ~ebot D E B leq e`,
  REPEAT GEN_TAC THEN
  ABBREV_TAC `pm = ?? 73 (opair_form 70 71 73 && (73 %% 72))` THEN
  STRIP_TAC THEN
  SUBGOAL_THEN `eporder D (E:A->A->bool) B leq` ASSUME_TAC THENL
   [ASM_MESON_TAC[ECBA_IMP_BALG; EBALG_IMP_PORDER]; ALL_TAC] THEN
  (* valuation + bname for (71|->betc)v0 *)
  SUBGOAL_THEN
   `valuation D ((71 |-> betc) (v0:num->A)) /\
    (!i. bname D E B (((71 |-> betc) (v0:num->A)) i))`
  STRIP_ASSUME_TAC THENL
   [CONJ_TAC THENL
     [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[];
      MATCH_MP_TAC BNAMEVAL_VALMOD THEN ASM_REWRITE_TAC[]];
    ALL_TAC] THEN
  (* the two bvalf values in D and in B *)
  SUBGOAL_THEN
   `(bvalf D (E:A->A->bool) B leq ((71 |-> betc) v0) pm) IN D /\
    (E:A->A->bool)(bvalf D E B leq ((71 |-> betc) v0) pm) B /\
    (bvalf D (E:A->A->bool) B leq v0 (?? 71 pm)) IN D /\
    (E:A->A->bool)(bvalf D E B leq v0 (?? 71 pm)) B`
  STRIP_ASSUME_TAC THENL
   [REPEAT CONJ_TAC THENL
     [MP_TAC(ISPECL [`pm:form`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
        `(71 |-> (betc:A)) v0`] BVALF_SPEC) THEN ASM_SIMP_TAC[];
      MP_TAC(ISPECL [`pm:form`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
        `(71 |-> (betc:A)) v0`] BVALF_IN_B) THEN ASM_SIMP_TAC[];
      MP_TAC(ISPECL [`?? 71 pm`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
        `v0:num->A`] BVALF_SPEC) THEN ASM_SIMP_TAC[];
      MP_TAC(ISPECL [`?? 71 pm`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
        `v0:num->A`] BVALF_IN_B) THEN ASM_SIMP_TAC[]];
    ALL_TAC] THEN
  (* [[pm[betc]]] <= [[?? 71 pm]] *)
  SUBGOAL_THEN
   `erel D (E:A->A->bool) leq
      (bvalf D E B leq ((71 |-> betc) v0) pm) (bvalf D E B leq v0 (?? 71 pm))`
  ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`71`;`pm:form`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
                  `v0:num->A`;`betc:A`] BVALF_EX_UB) THEN ASM_REWRITE_TAC[];
      ALL_TAC] THEN
  (* d <= [[?? 71 pm]] (= [[pm[Gn]]]) *)
  SUBGOAL_THEN `erel D (E:A->A->bool) leq d (bvalf D E B leq v0 (?? 71 pm))`
  ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`d:A`;
      `bvalf D (E:A->A->bool) B leq ((71 |-> betc) v0) pm`;
      `bvalf D (E:A->A->bool) B leq v0 (?? 71 pm)`]
      EPORDER_TRANS) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* freshness *)
  SUBGOAL_THEN `~(74 IN FV pm) /\ ~(71 = 74)` STRIP_ASSUME_TAC THENL
   [CONJ_TAC THENL
     [EXPAND_TAC "pm" THEN
      REWRITE_TAC[FV; FV_CLAUSES; FV_OPAIR_FORM; IN_DELETE; IN_UNION;
                  IN_INSERT; NOT_IN_EMPTY] THEN ARITH_TAC;
      ARITH_TAC];
    ALL_TAC] THEN
  (* apply VALNAME_COVER_STEP; the [[pm[Gn]]] bound comes from the eqn + *)
  (* [[?? 71 pm]] *)
  MP_TAC(ISPECL
         [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`v0:num->A`;`pm:form`;
          `71`;`74`;`Gn:A`;`betc:A`;`d:A`;`e:A`;`bot:A`]
           VALNAME_COVER_STEP) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC]);;

(* ==== BVALF_PAIRFORM_TOP: [[pair_form ia ib ic]] = top when v ic is the V^B
   unordered pair-name of (v ia, v ib).  Generalizes BVALF_PAIRING's core
   to arbitrary slots.  Foundation of the V^B-Kuratowski bvalf ladder (the TOP
   half that BVALF_PMEM's >= direction needs -- avoids the hard
     LE/extensionality
   half).  Uses EBV_IN_UPAIR ([[w in up]] = [[w=a]] JOIN [[w=b]]). *)

let BVALF_PAIRFORM_TOP = prove
 (`!D (E:A->A->bool) B leq (v:num->A) (ia:num) (ib:num) (ic:num) up top.
      model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
      valuation D v /\ (!k. bname D E B (v k)) /\
      up IN D /\ bname D E B up /\ top IN D /\ etop D E B leq top /\
      v ic = up /\
      eapply D E up (v ia) top /\ eapply D E up (v ib) top /\
      (!t q. t IN D /\ q IN D /\ eapply D E up t q ==> t = v ia \/ t = v ib)
      ==> etop D E B leq (bvalf D E B leq v (pair_form ia ib ic))`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `!x. (v:num->A) x IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[valuation]; ALL_TAC] THEN
  REWRITE_TAC[pair_form] THEN
  ABBREV_TAC `mp = MAX (MAX ia ib) ic + 1` THEN
  SUBGOAL_THEN `~((mp:num) = ia) /\ ~(mp = ib) /\ ~(mp = ic)`
    STRIP_ASSUME_TAC THENL
   [EXPAND_TAC "mp" THEN ARITH_TAC; ALL_TAC] THEN
  MP_TAC(ISPECL [`mp:num`; `((mp %% ic) <-> Eq mp ia || Eq mp ib)`;
    `D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`v:num->A`] BVALF_ALL_TOP) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  X_GEN_TAC `w:A` THEN STRIP_TAC THEN
  SUBGOAL_THEN
   `valuation D ((mp |-> (w:A)) (v:num->A)) /\
    (!i. bname D E B (((mp |-> (w:A)) (v:num->A)) i))`
  STRIP_ASSUME_TAC THENL
   [CONJ_TAC THENL
     [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[];
      MATCH_MP_TAC BNAMEVAL_VALMOD THEN ASM_REWRITE_TAC[]]; ALL_TAC] THEN
  ABBREV_TAC `vv = (mp |-> (w:A)) (v:num->A)` THEN
  SUBGOAL_THEN
   `(vv:num->A) mp = w /\ vv ia = (v:num->A) ia /\ vv ib = (v:num->A) ib /\
    vv ic = (v:num->A) ic`
  STRIP_ASSUME_TAC THENL
   [EXPAND_TAC "vv" THEN ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER; ARITH_EQ];
    ALL_TAC] THEN
  MP_TAC(ISPECL [`mp %% ic`; `Eq mp ia || Eq mp ib`;
    `D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`vv:num->A`] BVALF_IFF_TOP) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  ABBREV_TAC `zin = bvalf D (E:A->A->bool) B leq (vv:num->A) (mp %% ic)` THEN
  ABBREV_TAC `za = bvalf D (E:A->A->bool) B leq (vv:num->A) (Eq mp ia)` THEN
  ABBREV_TAC `zb = bvalf D (E:A->A->bool) B leq (vv:num->A) (Eq mp ib)` THEN
  ABBREV_TAC
    `zj = bvalf D (E:A->A->bool) B leq (vv:num->A) (Eq mp ia || Eq mp ib)` THEN
  SUBGOAL_THEN `ebv_in D (E:A->A->bool) B leq w up zin` ASSUME_TAC THENL
   [EXPAND_TAC "zin" THEN
    MP_TAC(ISPECL [`mp:num`;`ic:num`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
      `vv:num->A`] BVALF_MEM) THEN ASM_SIMP_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `ebv_eq D (E:A->A->bool) B leq w ((v:num->A) ia) za`
    ASSUME_TAC THENL
   [EXPAND_TAC "za" THEN
    MP_TAC(ISPECL [`mp:num`;`ia:num`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
      `vv:num->A`] BVALF_EQ2) THEN ASM_SIMP_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `ebv_eq D (E:A->A->bool) B leq w ((v:num->A) ib) zb`
    ASSUME_TAC THENL
   [EXPAND_TAC "zb" THEN
    MP_TAC(ISPECL [`mp:num`;`ib:num`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
      `vv:num->A`] BVALF_EQ2) THEN ASM_SIMP_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `ejoin D (E:A->A->bool) B leq za zb zj` ASSUME_TAC THENL
   [MAP_EVERY EXPAND_TAC ["za";"zb";"zj"] THEN
    MP_TAC(ISPECL
           [`Eq mp ia`;`Eq mp ib`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
            `vv:num->A`] BVALF_OR) THEN ASM_SIMP_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(zin:A) IN D /\ (za:A) IN D /\ (zb:A) IN D`
    STRIP_ASSUME_TAC THENL
   [REPEAT CONJ_TAC THENL
     [EXPAND_TAC "zin" THEN
      MP_TAC(ISPECL [`mp %% ic`;`D:A->bool`;`E:A->A->bool`;
                     `B:A`;`leq:A`;`vv:num->A`] BVALF_SPEC) THEN
      ASM_SIMP_TAC[];
      EXPAND_TAC "za" THEN
      MP_TAC(ISPECL [`Eq mp ia`;`D:A->bool`;`E:A->A->bool`;
                     `B:A`;`leq:A`;`vv:num->A`] BVALF_SPEC) THEN
      ASM_SIMP_TAC[];
      EXPAND_TAC "zb" THEN
      MP_TAC(ISPECL [`Eq mp ib`;`D:A->bool`;`E:A->A->bool`;
                     `B:A`;`leq:A`;`vv:num->A`] BVALF_SPEC) THEN
      ASM_SIMP_TAC[]];
    ALL_TAC] THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`(v:num->A) ia`;
    `(v:num->A) ib`; `up:A`;`top:A`;`w:A`;`zin:A`;`za:A`;`zb:A`;`zj:A`]
    EBV_IN_UPAIR) THEN
  ASM_REWRITE_TAC[]);;

(* ==== BVALF_OPAIRFORM_TOP: [[opair_form ia ib ic]] = top when v ic is the V^B
   Kuratowski pair of (v ia, v ib).  Composes BVALF_PAIRFORM_TOP 3x (for s={a},
   p={a,b}, v ic={s,p}) via BVALF_EX_TOP (witness the two internal binders) +
   BVALF_AND_TOP.  This is the TOP half feeding BVALF_PMEM's >= direction. *)

let BVALF_OPAIRFORM_TOP = prove
 (`!D (E:A->A->bool) B leq (v:num->A) (ia:num) (ib:num) (ic:num) s p top.
      model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
      valuation D v /\ (!k. bname D E B (v k)) /\
      top IN D /\ etop D E B leq top /\
      s IN D /\ bname D E B s /\ p IN D /\ bname D E B p /\
      eapply D E s (v ia) top /\
      (!t q. t IN D /\ q IN D /\ eapply D E s t q ==> t = v ia \/ t = v ia) /\
      eapply D E p (v ia) top /\ eapply D E p (v ib) top /\
      (!t q. t IN D /\ q IN D /\ eapply D E p t q ==> t = v ia \/ t = v ib) /\
      eapply D E (v ic) s top /\ eapply D E (v ic) p top /\
      (!t q. t IN D /\ q IN D /\ eapply D E (v ic) t q ==> t = s \/ t = p)
      ==> etop D E B leq (bvalf D E B leq v (opair_form ia ib ic))`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `!x. (v:num->A) x IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[valuation]; ALL_TAC] THEN
  REWRITE_TAC[opair_form] THEN
  ABBREV_TAC `M = MAX (MAX ia ib) ic` THEN
  SUBGOAL_THEN
    `~((M:num) + 1 = ia) /\ ~((M:num) + 1 = ib) /\ ~((M:num) + 1 = ic) /\
     ~((M:num) + 2 = ia) /\ ~((M:num) + 2 = ib) /\ ~((M:num) + 2 = ic) /\
                ~((M:num) + 1 = (M:num) + 2)`
    STRIP_ASSUME_TAC THENL [EXPAND_TAC "M" THEN ARITH_TAC; ALL_TAC] THEN
  (* valuations v1 = (M+1|->s)v ; v2 = (M+2|->p)v1 *)
  SUBGOAL_THEN
   `valuation D ((((M:num) + 1) |-> s) (v:num->A)) /\
    (!k. bname D E B (((((M:num) + 1) |-> s) (v:num->A)) k))`
  STRIP_ASSUME_TAC THENL
   [CONJ_TAC THENL
     [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[];
      MATCH_MP_TAC BNAMEVAL_VALMOD THEN ASM_REWRITE_TAC[]]; ALL_TAC] THEN
  SUBGOAL_THEN
   `valuation D ((((M:num) + 2) |-> p) ((((M:num) + 1) |-> s) (v:num->A))) /\
    (!k. bname D E B
     (((((M:num) + 2) |-> p) ((((M:num) + 1) |-> s) (v:num->A))) k))`
  STRIP_ASSUME_TAC THENL
   [CONJ_TAC THENL
     [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[];
      MATCH_MP_TAC BNAMEVAL_VALMOD THEN ASM_REWRITE_TAC[]]; ALL_TAC] THEN
  (* witness M+1 := s *)
  MATCH_MP_TAC BVALF_EX_TOP THEN EXISTS_TAC `s:A` THEN ASM_REWRITE_TAC[] THEN
  (* witness M+2 := p *)
  MATCH_MP_TAC BVALF_EX_TOP THEN EXISTS_TAC `p:A` THEN ASM_REWRITE_TAC[] THEN
  ABBREV_TAC
    `vv = (((M:num) + 2) |-> p) ((((M:num) + 1) |-> s) (v:num->A))` THEN
  SUBGOAL_THEN
   `(vv:num->A) ia = v ia /\ vv ib = v ib /\ vv ic = v ic /\
    vv ((M:num) + 1) = s /\ vv ((M:num) + 2) = p`
  STRIP_ASSUME_TAC THENL
   [EXPAND_TAC "vv" THEN ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER; ARITH_EQ];
    ALL_TAC] THEN
  (* split the 3 conjuncts *)
  MP_TAC(ISPECL [`pair_form ia ia ((M:num) + 1)`;
    `pair_form ia ib ((M:num) + 2) &&
     pair_form ((M:num) + 1) ((M:num) + 2) ic`;
    `D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`vv:num->A`] BVALF_AND_TOP) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN CONJ_TAC THENL
   [(* pair_form ia ia (M+1) : up = s *)
    MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`vv:num->A`;
      `ia:num`;`ia:num`;`(M:num) + 1`;`s:A`;`top:A`] BVALF_PAIRFORM_TOP) THEN
    ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[];
    MP_TAC(ISPECL
           [`pair_form ia ib ((M:num) + 2)`;
            `pair_form ((M:num) + 1) ((M:num) + 2) ic`;
            `D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`vv:num->A`]
             BVALF_AND_TOP) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN CONJ_TAC THENL
     [(* pair_form ia ib (M+2) : up = p *)
      MATCH_MP_TAC(ISPECL
                   [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`vv:num->A`;
                    `ia:num`;`ib:num`;`(M:num) + 2`;`p:A`;`top:A`]
                     BVALF_PAIRFORM_TOP) THEN
      ASM_REWRITE_TAC[];
      (* pair_form (M+1)(M+2) ic : up = v ic *)
      MATCH_MP_TAC(ISPECL
                   [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`vv:num->A`;
                    `(M:num) + 1`;`(M:num) + 2`;`ic:num`;`(v:num->A) ic`;
                    `top:A`] BVALF_PAIRFORM_TOP) THEN
      ASM_REWRITE_TAC[]]]);;

(* ==== BVALF_PMEM_GE: ebv_in(V^B-Kuratowski(v70,v71), v72) <= [[pm]], where
   pm = ?? 73 (opair_form 70 71 73 && (73 %% 72)).  The >= direction of the
   pair-membership value bridge: the V^B-Kuratowski name pr is a witness of the
   existential ([[opair 70 71 pr]] = top by BVALF_OPAIRFORM_TOP),
   so [[pr IN f]]
   = mvpr <= [[pm]] by BVALF_EX_UB.  This is exactly what W_n SUBSET X_n needs
   (via VALNAME_COVER_ONE): mvpr = [[<n^,bet^> IN f]] <= [[pm[bet^]]]. *)

let BVALF_PMEM_GE = prove
 (`!D (E:A->A->bool) B leq (v0:num->A) s p pr top mvpr.
      model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
      valuation D v0 /\ (!k. bname D E B (v0 k)) /\
      top IN D /\ etop D E B leq top /\
      s IN D /\ bname D E B s /\ p IN D /\ bname D E B p /\
      pr IN D /\ bname D E B pr /\
      eapply D E s (v0 70) top /\
      (!t q. t IN D /\ q IN D /\ eapply D E s t q ==> t = v0 70 \/
       t = v0 70) /\
      eapply D E p (v0 70) top /\ eapply D E p (v0 71) top /\
      (!t q. t IN D /\ q IN D /\ eapply D E p t q ==> t = v0 70 \/
       t = v0 71) /\
      eapply D E pr s top /\ eapply D E pr p top /\
      (!t q. t IN D /\ q IN D /\ eapply D E pr t q ==> t = s \/ t = p) /\
      mvpr IN D /\ ebv_in D E B leq pr (v0 72) mvpr
      ==> erel D E leq mvpr
            (bvalf D E B leq v0 (?? 73 (opair_form 70 71 73 && (73 %% 72))))`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `eporder D (E:A->A->bool) B leq` ASSUME_TAC THENL
   [ASM_MESON_TAC[ECBA_IMP_BALG; EBALG_IMP_PORDER]; ALL_TAC] THEN
  SUBGOAL_THEN `!x. (v0:num->A) x IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[valuation]; ALL_TAC] THEN
  SUBGOAL_THEN
   `valuation D ((73 |-> pr) (v0:num->A)) /\
    (!k. bname D E B (((73 |-> pr) (v0:num->A)) k))`
  STRIP_ASSUME_TAC THENL
   [CONJ_TAC THENL
     [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[];
      MATCH_MP_TAC BNAMEVAL_VALMOD THEN ASM_REWRITE_TAC[]]; ALL_TAC] THEN
  ABBREV_TAC `vp = (73 |-> pr) (v0:num->A)` THEN
  SUBGOAL_THEN
   `(vp:num->A) 70 = v0 70 /\ vp 71 = v0 71 /\ vp 72 = v0 72 /\ vp 73 = pr`
  STRIP_ASSUME_TAC THENL
   [EXPAND_TAC "vp" THEN ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER; ARITH_EQ];
    ALL_TAC] THEN
  (* X := [[opair_form 70 71 73]]_vp is top *)
  SUBGOAL_THEN
    `etop D (E:A->A->bool) B leq
     (bvalf D E B leq (vp:num->A) (opair_form 70 71 73))`
  ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`vp:num->A`;
      `70`;`71`;`73`;`s:A`;`p:A`;`top:A`] BVALF_OPAIRFORM_TOP) THEN
    ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[]; ALL_TAC] THEN
  (* Y := [[73%%72]]_vp = mvpr *)
  SUBGOAL_THEN `bvalf D (E:A->A->bool) B leq (vp:num->A) (73 %% 72) = mvpr`
  ASSUME_TAC THENL
   [MP_TAC(ISPECL
           [`73`;`72`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`vp:num->A`]
           BVALF_MEM) THEN ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    ASM_REWRITE_TAC[] THEN DISCH_TAC THEN
    MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`pr:A`;
      `(v0:num->A) 72`;
      `bvalf D (E:A->A->bool) B leq (vp:num->A) (73 %% 72)`;`mvpr:A`]
             EBV_IN_UNIQUE) THEN
    ASM_REWRITE_TAC[] THEN
    MP_TAC(ISPECL
           [`73 %% 72`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`vp:num->A`]
           BVALF_SPEC) THEN ASM_SIMP_TAC[]; ALL_TAC] THEN
  (* Z := [[opair && mem]]_vp = mvpr *)
  SUBGOAL_THEN
   `bvalf D (E:A->A->bool) B leq (vp:num->A)
    (opair_form 70 71 73 && (73 %% 72)) = mvpr`
  ASSUME_TAC THENL
   [MP_TAC(ISPECL [`opair_form 70 71 73`;`73 %% 72`;`D:A->bool`;`E:A->A->bool`;
      `B:A`;`leq:A`;`vp:num->A`] BVALF_AND_MEET) THEN
    ASM_REWRITE_TAC[] THEN
    ABBREV_TAC
      `X = bvalf D (E:A->A->bool) B leq (vp:num->A) (opair_form 70 71 73)` THEN
      ABBREV_TAC
        `Z = bvalf D (E:A->A->bool) B leq (vp:num->A)
         (opair_form 70 71 73 && (73 %% 72))` THEN
    DISCH_TAC THEN
    SUBGOAL_THEN `(E:A->A->bool) (mvpr:A) B` ASSUME_TAC THENL
     [ASM_MESON_TAC[EBV_IN_IN_B]; ALL_TAC] THEN
    ASM_MESON_TAC[EMEET_TOP; EMEET_SYM; EMEET_UNIQUE; EMEET_IN]; ALL_TAC] THEN
  MP_TAC(ISPECL [`73`; `opair_form 70 71 73 && (73 %% 72)`;
    `D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`v0:num->A`;`pr:A`]
      BVALF_EX_UB) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  EXPAND_TAC "vp" THEN ASM_REWRITE_TAC[]);;
(* ==== ECHECK_APPLY / ECHECK_DOM : the eapply structure of a check-name.
   These two thin ECHECK_MEM wrappers say the members of x^ (as an
     eapply-graph)
   are exactly < y^, onebee > for y IN x.  They discharge the EUPAIRNAME-bundle
   hypotheses of BVALF_PMEM_GE for the V^B-Kuratowski (n,bet)^ = check of the
   ground pair (checks commute with pairing), letting the membership-route gg
   reuse echeck_form and still feed BVALF_PMEM_GE.

   ECHECK_APPLY (forward): y IN x, cy = y^  ==>  eapply x^ cy onebee.
   ECHECK_DOM   (backward): eapply x^ t q  ==>  ?y. y IN x /\
     t = y^ /\ q = onebee.
   Pattern for ECHECK_APPLY copied from ECHECK_EQ_LE_MEM (EOPAIR_EXISTS +
   ECHECK_MEM backward). *)

let ECHECK_APPLY = prove
 (`!D (E:A->A->bool) onebee x v y cy.
      model D E ZF_AX /\ onebee IN D /\
      echeck D E onebee x v /\ E y x /\ echeck D E onebee y cy
      ==> eapply D E v cy onebee`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `(x:A) IN D /\ (v:A) IN D /\ (y:A) IN D /\ (cy:A) IN D`
  STRIP_ASSUME_TAC THENL [ASM_MESON_TAC[ECHECK_IMP]; ALL_TAC] THEN
  SUBGOAL_THEN `?z:A. eopair D (E:A->A->bool) cy onebee z`
    (X_CHOOSE_TAC `z:A`) THENL
   [MATCH_MP_TAC EOPAIR_EXISTS THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(z:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[EOPAIR_IN]; ALL_TAC] THEN
  REWRITE_TAC[eapply] THEN EXISTS_TAC `z:A` THEN ASM_REWRITE_TAC[] THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`onebee:A`;`x:A`;`v:A`;`z:A`]
         ECHECK_MEM) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  MAP_EVERY EXISTS_TAC [`y:A`;`cy:A`] THEN ASM_REWRITE_TAC[]);;

let ECHECK_DOM = prove
 (`!D (E:A->A->bool) onebee x v t q.
      model D E ZF_AX /\ onebee IN D /\ echeck D E onebee x v /\
      t IN D /\ q IN D /\ eapply D E v t q
      ==> ?y. E y x /\ echeck D E onebee y t /\ q = onebee`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `(x:A) IN D /\ (v:A) IN D` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[ECHECK_IMP]; ALL_TAC] THEN
  UNDISCH_TAC `eapply (D:A->bool) (E:A->A->bool) (v:A) (t:A) (q:A)` THEN
  REWRITE_TAC[eapply] THEN
  DISCH_THEN(X_CHOOSE_THEN `z:A` STRIP_ASSUME_TAC) THEN
  SUBGOAL_THEN `(z:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[EOPAIR_IN]; ALL_TAC] THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`onebee:A`;`x:A`;`v:A`;`z:A`]
         ECHECK_MEM) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `yy:A` (X_CHOOSE_THEN `vy:A` STRIP_ASSUME_TAC)) THEN
  SUBGOAL_THEN `(t:A) = vy /\ (q:A) = onebee` STRIP_ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`t:A`;`q:A`;`vy:A`;
                  `onebee:A`;`z:A`]
                 EOPAIR_INJ) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  EXISTS_TAC `yy:A` THEN ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[]);;

(* ==== ECHECK_KUR_BUNDLE: the check of the ground Kuratowski pair (n,bet) is
   the V^B-Kuratowski of (n^, bet^), satisfying EXACTLY the EUPAIRNAME-bundle
   hypotheses of BVALF_PMEM_GE.  Pure consequence of ECHECK_APPLY (forward) +
   ECHECK_DOM (backward) + ECHECK_SV.  With v0 70 := cn = n^, v0 71 := cb =
   bet^, top := onebee, this hands BVALF_PMEM_GE its s,p,pr bundle directly, so
   the membership-route gg (built with echeck_form of the ground pair) plugs
   into the pair-membership value bridge. *)

let ECHECK_KUR_BUNDLE = prove
 (`!D (E:A->A->bool) onebee n bet cn cb sing pair kur s p pr.
      model D E ZF_AX /\ onebee IN D /\ n IN D /\ bet IN D /\
      echeck D E onebee n cn /\ echeck D E onebee bet cb /\
      sing IN D /\ (!y. y IN D ==> (E y sing <=> y = n)) /\
      pair IN D /\ (!y. y IN D ==> (E y pair <=> y = n \/ y = bet)) /\
      kur IN D /\ (!y. y IN D ==> (E y kur <=> y = sing \/ y = pair)) /\
      echeck D E onebee sing s /\ echeck D E onebee pair p /\
      echeck D E onebee kur pr
      ==> eapply D E s cn onebee /\
          (!t q. t IN D /\ q IN D /\ eapply D E s t q ==> t = cn \/ t = cn) /\
          eapply D E p cn onebee /\ eapply D E p cb onebee /\
          (!t q. t IN D /\ q IN D /\ eapply D E p t q ==> t = cn \/ t = cb) /\
          eapply D E pr s onebee /\ eapply D E pr p onebee /\
          (!t q. t IN D /\ q IN D /\ eapply D E pr t q ==> t = s \/ t = p)`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN
   `(E:A->A->bool) n sing /\ E n pair /\ E bet pair /\
    E sing kur /\ E pair kur`
  STRIP_ASSUME_TAC THENL [ASM_MESON_TAC[]; ALL_TAC] THEN
  REPEAT CONJ_TAC THENL
   [(* eapply s cn onebee : s = {n}^, n IN {n}, cn = n^ *)
    MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`onebee:A`;`sing:A`;`s:A`;
      `n:A`;`cn:A`] ECHECK_APPLY) THEN ASM_REWRITE_TAC[];
    (* dom s : eapply s t q ==> t = cn *)
    REPEAT GEN_TAC THEN STRIP_TAC THEN
    MP_TAC(ISPECL
           [`D:A->bool`;`E:A->A->bool`;`onebee:A`;`sing:A`;`s:A`;`t:A`;`q:A`]
           ECHECK_DOM) THEN ASM_REWRITE_TAC[] THEN
    ASM_MESON_TAC[ECHECK_SV; ECHECK_IMP];
    (* eapply p cn onebee : p = {n,bet}^, n IN {n,bet} *)
    MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`onebee:A`;`pair:A`;`p:A`;
      `n:A`;`cn:A`] ECHECK_APPLY) THEN ASM_REWRITE_TAC[];
    (* eapply p cb onebee : bet IN {n,bet} *)
    MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`onebee:A`;`pair:A`;`p:A`;
      `bet:A`;`cb:A`] ECHECK_APPLY) THEN ASM_REWRITE_TAC[];
    (* dom p : eapply p t q ==> t = cn \/ t = cb *)
    REPEAT GEN_TAC THEN STRIP_TAC THEN
    MP_TAC(ISPECL
           [`D:A->bool`;`E:A->A->bool`;`onebee:A`;`pair:A`;`p:A`;`t:A`;`q:A`]
           ECHECK_DOM) THEN ASM_REWRITE_TAC[] THEN
    ASM_MESON_TAC[ECHECK_SV; ECHECK_IMP];
    (* eapply pr s onebee : pr = (n,bet)^, sing IN kur, s = sing^ *)
    MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`onebee:A`;`kur:A`;`pr:A`;
      `sing:A`;`s:A`] ECHECK_APPLY) THEN ASM_REWRITE_TAC[];
    (* eapply pr p onebee : pair IN kur, p = pair^ *)
    MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`onebee:A`;`kur:A`;`pr:A`;
      `pair:A`;`p:A`] ECHECK_APPLY) THEN ASM_REWRITE_TAC[];
    (* dom pr : eapply pr t q ==> t = s \/ t = p *)
    REPEAT GEN_TAC THEN STRIP_TAC THEN
    MP_TAC(ISPECL
           [`D:A->bool`;`E:A->A->bool`;`onebee:A`;`kur:A`;`pr:A`;`t:A`;`q:A`]
           ECHECK_DOM) THEN ASM_REWRITE_TAC[] THEN
    ASM_MESON_TAC[ECHECK_SV; ECHECK_IMP]]);;

(* ==== m3'-gg : the MEMBERSHIP collapse relation
       gg = { <bet,n> : bet<a1, n<om, [[ <n^,bet^> IN f ]] MEET b0 =/= bot }
   via ZF_SEPARATION over ECROSS a1 om by memcollapse_form.  Mirror of
   collapse_form / HOLDS_COLLAPSE_FORM / ECOLLAPSE_EXISTS, swapping
   the value-name clause (apply_form Gfs 64 81; ebv_eq_form) for the membership
   clause: the GROUND pair (n,bet) at slot 81 (opair_form 64 62 81), its check
   ckp = (n,bet)^ = <n^,bet^> at slot 80 (echeck_form 98 81 80), the membership
   value mv = [[ ckp IN f ]] at slot 63 (ebv_in_form 63 80 90 5), the meet
   d = b0 MEET mv at slot 100 (bmeet_form 5 2 96 63 100), and d =/= bot.
   Concrete slots (nf=90, b0s=96, vON=98, d=100) so ARITH discharges every
   VALMOD side-condition -- sidesteps the collapse_form ~(vON=63) trap.
   NB: d-slot = 100 (NOT 82!): opair_form 64 62 81 internally binds
     MAX(64,62,81)
   +1 = 82, which would collide with the tower if d=82 (the k-binder-tower
   trap that caused ECOLLAPSE's Length-mismatch). *)

let memcollapse_form = new_definition
  `memcollapse_form =
     ?? 62 (?? 64 (?? 81 (?? 80 (?? 63 (?? 100
       (opair_form 62 64 0 && opair_form 64 62 81 &&
        echeck_form 98 81 80 && ebv_in_form 63 80 90 5 &&
        bmeet_form 5 2 96 63 100 && Not(bbot_form 5 2 100)))))))`;;

let HOLDS_MEMCOLLAPSE_FORM = prove
 (`!D (E:A->A->bool) v.
      model D E ZF_AX /\ valuation D v
      ==> (holds D E v memcollapse_form <=>
           ?bet nn pnb ckp mv d.
              bet IN D /\ nn IN D /\ pnb IN D /\ ckp IN D /\
                mv IN D /\ d IN D /\
              eopair D E bet nn (v 0) /\ eopair D E nn bet pnb /\
              echeck D E (v 98) pnb ckp /\
              ebv_in D E (v 2) (v 5) ckp (v 90) mv /\
              emeet D E (v 2) (v 5) (v 96) mv d /\
              ~ebot D E (v 2) (v 5) d)`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `!x. (v:num->A) x IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[valuation]; ALL_TAC] THEN
  REWRITE_TAC[memcollapse_form] THEN
  SUBGOAL_THEN
   `!bet nn pnb ckp mv d:A.
      bet IN D /\ nn IN D /\ pnb IN D /\ ckp IN D /\ mv IN D /\ d IN D
      ==> (holds D E
             ((100 |-> (d:A))
              ((63 |-> (mv:A)) ((80 |-> (ckp:A)) ((81 |-> (pnb:A))
               ((64 |-> (nn:A)) ((62 |-> (bet:A)) v))))))
             (opair_form 62 64 0 && opair_form 64 62 81 &&
              echeck_form 98 81 80 && ebv_in_form 63 80 90 5 &&
              bmeet_form 5 2 96 63 100 && Not(bbot_form 5 2 100)) <=>
           eopair D E bet nn (v 0) /\ eopair D E nn bet pnb /\
           echeck D E (v 98) pnb ckp /\
           ebv_in D E (v 2) (v 5) ckp (v 90) mv /\
           emeet D E (v 2) (v 5) (v 96) mv d /\
           ~ebot D E (v 2) (v 5) d)`
  (LABEL_TAC "body") THENL
   [REPEAT GEN_TAC THEN STRIP_TAC THEN
    SUBGOAL_THEN
     `valuation D
      ((100 |-> (d:A)) ((63 |-> (mv:A)) ((80 |-> (ckp:A)) ((81 |-> (pnb:A))
        ((64 |-> (nn:A)) ((62 |-> (bet:A)) v))))))` ASSUME_TAC THENL
     [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
    SUBGOAL_THEN
     `holds D E
      ((100 |-> (d:A)) ((63 |-> (mv:A)) ((80 |-> (ckp:A)) ((81 |-> (pnb:A))
        ((64 |-> (nn:A)) ((62 |-> (bet:A)) v)))))) (opair_form 62 64 0) <=>
      eopair D E bet nn (v 0)`
    ASSUME_TAC THENL
     [ASM_SIMP_TAC[HOLDS_OPAIR_FORM] THEN
      ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER; ARITH_EQ]; ALL_TAC] THEN
    SUBGOAL_THEN
     `holds D E
      ((100 |-> (d:A)) ((63 |-> (mv:A)) ((80 |-> (ckp:A)) ((81 |-> (pnb:A))
        ((64 |-> (nn:A)) ((62 |-> (bet:A)) v)))))) (opair_form 64 62 81) <=>
      eopair D E nn bet pnb`
    ASSUME_TAC THENL
     [ASM_SIMP_TAC[HOLDS_OPAIR_FORM] THEN
      ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER; ARITH_EQ]; ALL_TAC] THEN
    SUBGOAL_THEN
     `holds D E
      ((100 |-> (d:A)) ((63 |-> (mv:A)) ((80 |-> (ckp:A)) ((81 |-> (pnb:A))
        ((64 |-> (nn:A)) ((62 |-> (bet:A)) v)))))) (echeck_form 98 81 80) <=>
      echeck D E (v 98) pnb ckp`
    ASSUME_TAC THENL
     [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
        `((100 |-> (d:A)) ((63 |-> (mv:A)) ((80 |-> (ckp:A)) ((81 |-> (pnb:A))
          ((64 |-> (nn:A)) ((62 |-> (bet:A)) v))))))`; `98`; `81`; `80`]
        HOLDS_ECHECK_FORM) THEN
      ASM_REWRITE_TAC[ARITH_RULE
        `~(98 = 2) /\ ~(98 = 3) /\ ~(98 = 4) /\ ~(98 = 49) /\ ~(98 = 50) /\
         ~(98 = 51) /\ ~(81 = 2) /\ ~(81 = 3) /\ ~(81 = 4) /\ ~(81 = 49) /\
         ~(81 = 50) /\ ~(81 = 51) /\ ~(80 = 2) /\ ~(80 = 3) /\ ~(80 = 4) /\
         ~(80 = 49) /\ ~(80 = 50) /\ ~(80 = 51)`] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
      ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER; ARITH_EQ]; ALL_TAC] THEN
    SUBGOAL_THEN
     `holds D E
      ((100 |-> (d:A)) ((63 |-> (mv:A)) ((80 |-> (ckp:A)) ((81 |-> (pnb:A))
        ((64 |-> (nn:A)) ((62 |-> (bet:A)) v)))))) (ebv_in_form 63 80 90 5) <=>
      ebv_in D E (v 2) (v 5) ckp (v 90) mv`
    ASSUME_TAC THENL
     [ASM_SIMP_TAC[HOLDS_EBV_IN_FORM] THEN
      ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER; ARITH_EQ]; ALL_TAC] THEN
    SUBGOAL_THEN
     `holds D E
      ((100 |-> (d:A)) ((63 |-> (mv:A)) ((80 |-> (ckp:A)) ((81 |-> (pnb:A))
        ((64 |-> (nn:A)) ((62 |-> (bet:A)) v))))))
        (bmeet_form 5 2 96 63 100) <=>
      emeet D E (v 2) (v 5) (v 96) mv d`
    ASSUME_TAC THENL
     [ASM_SIMP_TAC[HOLDS_BMEET_FORM] THEN
      ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER; ARITH_EQ]; ALL_TAC] THEN
    SUBGOAL_THEN
     `holds D E
      ((100 |-> (d:A)) ((63 |-> (mv:A)) ((80 |-> (ckp:A)) ((81 |-> (pnb:A))
        ((64 |-> (nn:A)) ((62 |-> (bet:A)) v)))))) (Not(bbot_form 5 2 100)) <=>
      ~ebot D E (v 2) (v 5) d`
    ASSUME_TAC THENL
     [REWRITE_TAC[HOLDS_NOT] THEN
      MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
        `((100 |-> (d:A)) ((63 |-> (mv:A)) ((80 |-> (ckp:A)) ((81 |-> (pnb:A))
          ((64 |-> (nn:A)) ((62 |-> (bet:A)) v))))))`; `5`; `2`; `100`]
        HOLDS_BBOT_FORM) THEN
      ASM_REWRITE_TAC[] THEN DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
      ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER; ARITH_EQ]; ALL_TAC] THEN
    REWRITE_TAC[HOLDS_AND] THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  REWRITE_TAC[HOLDS_EX] THEN EQ_TAC THENL
   [INTRO_TAC "@bet. betD @nn. nnD @pnb. pnbD @ckp. ckpD @mv. mvD @d. \
               dD h" THEN
    SUBGOAL_THEN
     `eopair D (E:A->A->bool) bet nn ((v:num->A) 0) /\ eopair D E nn bet pnb /\
      echeck D E (v 98) pnb ckp /\ ebv_in D E (v 2) (v 5) ckp (v 90) mv /\
      emeet D E (v 2) (v 5) (v 96) mv d /\ ~ebot D E (v 2) (v 5) d`
    STRIP_ASSUME_TAC THENL
     [USE_THEN "body"
      (MP_TAC o SPECL [`bet:A`;`nn:A`;`pnb:A`;`ckp:A`;`mv:A`;`d:A`]) THEN
      ANTS_TAC THENL
       [ASM_REWRITE_TAC[];
        DISCH_THEN(fun th -> REWRITE_TAC[GSYM th]) THEN
        FIRST_ASSUM ACCEPT_TAC];
      ALL_TAC] THEN
    MAP_EVERY EXISTS_TAC [`bet:A`;`nn:A`;`pnb:A`;`ckp:A`;`mv:A`;`d:A`] THEN
    ASM_REWRITE_TAC[];
    DISCH_THEN(X_CHOOSE_THEN `bet:A` (X_CHOOSE_THEN `nn:A`
      (X_CHOOSE_THEN `pnb:A` (X_CHOOSE_THEN `ckp:A`
        (X_CHOOSE_THEN `mv:A` (X_CHOOSE_THEN `d:A` STRIP_ASSUME_TAC)))))) THEN
    EXISTS_TAC `bet:A` THEN CONJ_TAC THENL
    [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    EXISTS_TAC `nn:A` THEN CONJ_TAC THENL
    [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    EXISTS_TAC `pnb:A` THEN CONJ_TAC THENL
    [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    EXISTS_TAC `ckp:A` THEN CONJ_TAC THENL
    [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    EXISTS_TAC `mv:A` THEN CONJ_TAC THENL
    [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    EXISTS_TAC `d:A` THEN CONJ_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    USE_THEN "body"
      (MP_TAC o SPECL [`bet:A`;`nn:A`;`pnb:A`;`ckp:A`;`mv:A`;`d:A`]) THEN
      ANTS_TAC THENL
     [ASM_REWRITE_TAC[];
      DISCH_THEN(fun th -> ONCE_REWRITE_TAC[th]) THEN ASM_REWRITE_TAC[]]]);;

(* EMEMCOLLAPSE_EXISTS: gg = { <bet,n> : bet<a1, n<om, [[<n^,bet^> IN f]] MEET
   b0 =/= bot } exists,
   via ZF_SEPARATION over ECROSS a1 om by memcollapse_form.
   Mirror ECOLLAPSE_EXISTS; concrete slots => HOLDS_MEMCOLLAPSE_FORM has
   NO freshness ANTS (unlike collapse's 90/91 ARITH_RULE).  Slots 90=f, 96=b0,
   98=onebee, 2=B, 5=leq. *)

let EMEMCOLLAPSE_EXISTS = prove
 (`!D (E:A->A->bool) a1 om B leq f b0 onebee.
     model D E ZF_AX /\ a1 IN D /\ om IN D /\ B IN D /\ leq IN D /\
     f IN D /\ b0 IN D /\ onebee IN D
     ==> ?gg. gg IN D /\
             !q. q IN D
                 ==> (E q gg <=>
                      ?bet nn pnb ckp mv d.
                         bet IN D /\ nn IN D /\ pnb IN D /\ ckp IN D /\
                         mv IN D /\ d IN D /\
                         E bet a1 /\ E nn om /\ eopair D E bet nn q /\
                         eopair D E nn bet pnb /\ echeck D E onebee pnb ckp /\
                         ebv_in D E B leq ckp f mv /\
                           emeet D E B leq b0 mv d /\
                         ~ebot D E B leq d)`,
  REPEAT STRIP_TAC THEN
  MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `a1:A`; `om:A`]
         ECROSS_EXISTS) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `cr:A` (LABEL_TAC "cr")) THEN
  SUBGOAL_THEN `(cr:A) IN D` ASSUME_TAC THENL
  [ASM_MESON_TAC[ecross]; ALL_TAC] THEN
  ABBREV_TAC
   `v0 = (90 |-> (f:A)) ((96 |-> (b0:A))
           ((98 |-> (onebee:A))
            ((5 |-> (leq:A)) ((2 |-> (B:A)) (\n:num. a1:A)))))` THEN
  SUBGOAL_THEN `valuation D (v0:num->A)` ASSUME_TAC THENL
   [EXPAND_TAC "v0" THEN
    REPEAT(MATCH_MP_TAC VALUATION_VALMOD THEN
           CONJ_TAC THENL [ALL_TAC; FIRST_ASSUM ACCEPT_TAC]) THEN
    REWRITE_TAC[valuation] THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN
   `v0 2 = B /\ v0 5 = leq /\ v0 90 = f /\ v0 96 = b0 /\ v0 98 = (onebee:A)`
  STRIP_ASSUME_TAC THENL
   [EXPAND_TAC "v0" THEN REPEAT CONJ_TAC THEN
    ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER; ARITH_EQ]; ALL_TAC] THEN
  MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`] ZF_SEPARATION) THEN
  ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  DISCH_THEN(MP_TAC o ISPECL
    [`memcollapse_form`; `0`; `v0:num->A`; `cr:A`]) THEN
  ANTS_TAC THENL
   [CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
    DISCH_THEN(X_CHOOSE_THEN `h:A`
      (CONJUNCTS_THEN2 ASSUME_TAC (LABEL_TAC "sep")))] THEN
  EXISTS_TAC `h:A` THEN ASM_REWRITE_TAC[] THEN
  X_GEN_TAC `q:A` THEN DISCH_TAC THEN
  MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `a1:A`; `om:A`; `cr:A`; `q:A`]
    ECROSS_MEMBER) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(LABEL_TAC "crm") THEN
  SUBGOAL_THEN `valuation D ((0 |-> (q:A)) v0)` ASSUME_TAC THENL
   [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `(0 |-> (q:A)) v0`]
    HOLDS_MEMCOLLAPSE_FORM) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER; ARITH_EQ] THEN
  DISCH_THEN(LABEL_TAC "hc") THEN
  USE_THEN "sep" (MP_TAC o SPEC `q:A`) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN DISCH_THEN SUBST1_TAC THEN
  USE_THEN "crm" (fun t1 -> USE_THEN "hc" (fun t2 -> REWRITE_TAC[t1; t2])) THEN
  EQ_TAC THENL
   [DISCH_THEN(CONJUNCTS_THEN2
      (X_CHOOSE_THEN `u:A` (X_CHOOSE_THEN `w:A` STRIP_ASSUME_TAC))
      (X_CHOOSE_THEN `bet:A` (X_CHOOSE_THEN `nn:A` (X_CHOOSE_THEN `pnb:A`
        (X_CHOOSE_THEN `ckp:A` (X_CHOOSE_THEN `mv:A`
          (X_CHOOSE_THEN `d:A` STRIP_ASSUME_TAC))))))) THEN
    MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `bet:A`; `nn:A`; `u:A`; `w:A`;
      `q:A`] EOPAIR_INJ) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(CONJUNCTS_THEN SUBST_ALL_TAC) THEN
    MAP_EVERY EXISTS_TAC [`u:A`; `w:A`; `pnb:A`; `ckp:A`; `mv:A`; `d:A`] THEN
    ASM_REWRITE_TAC[];
    DISCH_THEN(X_CHOOSE_THEN `bet:A`
               (X_CHOOSE_THEN `nn:A` (X_CHOOSE_THEN `pnb:A`
                                      (X_CHOOSE_THEN `ckp:A`
                                       (X_CHOOSE_THEN `mv:A`
                                        (X_CHOOSE_THEN `d:A`
                                         STRIP_ASSUME_TAC)))))) THEN
    CONJ_TAC THENL
     [MAP_EVERY EXISTS_TAC [`bet:A`; `nn:A`] THEN ASM_REWRITE_TAC[];
      MAP_EVERY EXISTS_TAC
        [`bet:A`; `nn:A`; `pnb:A`; `ckp:A`; `mv:A`; `d:A`] THEN
        ASM_REWRITE_TAC[]]]);;

(* ==== ECHECK_KUR_AUTO: from pnb = eopair(n,bet) (the GROUND Kuratowski pair,
   as EMEMCOLLAPSE hands it) and ckp = pnb^, BUILD the sub-checks s = ({n})^,
   p = ({n,bet})^ (via ECHECK_EXHAUSTION) and emit ECHECK_KUR_BUNDLE's 8
   EUPAIRNAME-bundle facts.  Turns the per-fibre data of EMEMCOLLAPSE directly
   into BVALF_PMEM_GE's hypotheses. *)

let ECHECK_KUR_AUTO = prove
 (`!D (E:A->A->bool) B onebee n bet cn cb pnb ckp.
      model D E ZF_AX /\ B IN D /\ onebee IN D /\ E onebee B /\
      (!u. u IN D ==> elmem D E u) /\
      echeck D E onebee n cn /\ echeck D E onebee bet cb /\
      eopair D E n bet pnb /\ echeck D E onebee pnb ckp
      ==> ?s p. s IN D /\ p IN D /\ bname D E B s /\ bname D E B p /\
          eapply D E s cn onebee /\
          (!t q. t IN D /\ q IN D /\ eapply D E s t q ==> t = cn \/ t = cn) /\
          eapply D E p cn onebee /\ eapply D E p cb onebee /\
          (!t q. t IN D /\ q IN D /\ eapply D E p t q ==> t = cn \/ t = cb) /\
          eapply D E ckp s onebee /\ eapply D E ckp p onebee /\
          (!t q. t IN D /\ q IN D /\ eapply D E ckp t q ==> t = s \/ t = p)`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  (* unfold eopair n bet pnb into the two members sing={n}, pair={n,bet} *)
  UNDISCH_TAC `eopair D (E:A->A->bool) n bet pnb` THEN REWRITE_TAC[eopair] THEN
  DISCH_THEN(X_CHOOSE_THEN `sing:A`
             (X_CHOOSE_THEN `pair:A` STRIP_ASSUME_TAC)) THEN
  (* the component sets are in D (D-confined epair pins only its 3rd arg) *)
  SUBGOAL_THEN `(sing:A) IN D /\ (pair:A) IN D /\ (pnb:A) IN D`
  STRIP_ASSUME_TAC THENL
   [REPEAT CONJ_TAC THENL
     [UNDISCH_TAC `epair D (E:A->A->bool) n n sing`;
      UNDISCH_TAC `epair D (E:A->A->bool) n bet pair`;
      UNDISCH_TAC `epair D (E:A->A->bool) sing pair pnb`] THEN
    REWRITE_TAC[epair] THEN STRIP_TAC THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  (* the sub-checks exist (ECHECK_EXHAUSTION) *)
  SUBGOAL_THEN `?s. echeck D (E:A->A->bool) onebee sing s`
    (X_CHOOSE_TAC `s:A`) THENL
   [ASM_MESON_TAC[ECHECK_EXHAUSTION]; ALL_TAC] THEN
  SUBGOAL_THEN `?p. echeck D (E:A->A->bool) onebee pair p`
    (X_CHOOSE_TAC `p:A`) THENL
   [ASM_MESON_TAC[ECHECK_EXHAUSTION]; ALL_TAC] THEN
  SUBGOAL_THEN `(s:A) IN D /\ (p:A) IN D` STRIP_ASSUME_TAC THENL
   [CONJ_TAC THENL
     [UNDISCH_TAC `echeck D (E:A->A->bool) onebee sing s`;
      UNDISCH_TAC `echeck D (E:A->A->bool) onebee pair p`] THEN
    REWRITE_TAC[echeck] THEN STRIP_TAC THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* GUARDED membership iffs from the epair defs *)
  SUBGOAL_THEN `!y:A. y IN D ==> ((E:A->A->bool) y sing <=> y = n)`
    ASSUME_TAC THENL
   [UNDISCH_TAC `epair D (E:A->A->bool) n n sing` THEN REWRITE_TAC[epair] THEN
    ASM_MESON_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `!y:A. y IN D ==> ((E:A->A->bool) y pair <=> y = n \/ y = bet)`
  ASSUME_TAC THENL
   [UNDISCH_TAC `epair D (E:A->A->bool) n bet pair` THEN
    REWRITE_TAC[epair] THEN
    ASM_MESON_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN
    `!y:A. y IN D ==> ((E:A->A->bool) y pnb <=> y = sing \/ y = pair)`
  ASSUME_TAC THENL
   [UNDISCH_TAC `epair D (E:A->A->bool) sing pair pnb` THEN
    REWRITE_TAC[epair] THEN
    ASM_MESON_TAC[]; ALL_TAC] THEN
  EXISTS_TAC `s:A` THEN EXISTS_TAC `p:A` THEN
  (* bname s, bname p *)
  SUBGOAL_THEN `bname D (E:A->A->bool) B s /\ bname D (E:A->A->bool) B p`
  STRIP_ASSUME_TAC THENL
   [CONJ_TAC THEN MATCH_MP_TAC ECHECK_IS_BNAME THENL
     [MAP_EVERY EXISTS_TAC [`onebee:A`; `sing:A`];
      MAP_EVERY EXISTS_TAC [`onebee:A`; `pair:A`]] THEN
    ASM_MESON_TAC[ECHECK_IMP]; ALL_TAC] THEN
  (* the 8 bundle facts via (generalized, guarded) ECHECK_KUR_BUNDLE *)
  MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `onebee:A`; `n:A`; `bet:A`;
    `cn:A`; `cb:A`; `sing:A`; `pair:A`; `pnb:A`; `s:A`; `p:A`; `ckp:A`]
    ECHECK_KUR_BUNDLE) THEN
  ANTS_TAC THENL
   [REPEAT CONJ_TAC THEN TRY(FIRST_ASSUM ACCEPT_TAC) THEN
    ASM_MESON_TAC[ECHECK_IMP]; ALL_TAC] THEN
  STRIP_TAC THEN REPEAT CONJ_TAC THEN TRY(FIRST_ASSUM ACCEPT_TAC) THEN
  ASM_MESON_TAC[]);;

(* ==== MEMVAL_COVER (m3a, the per-beta core): the membership condition at
   (n,bet) forces the value-name fibre.  Given ckp = (n,bet)^ with mv =
   [[ ckp IN f ]], b0 MEET mv =/= bot, b0 <= [[pm single-valued]], and Gn the
   value-name of f at n^ (= v0 70), conclude [[ Gn = bet^ ]] =/= bot.
   Chain: ECHECK_KUR_AUTO (ckp = V^B-Kuratowski bundle) -> BVALF_PMEM_GE
   (mv <= [[pm[bet^]]]) -> d = b0 MEET mv <= mv, <= b0 -> VALNAME_COVER_ONE. *)

let MEMVAL_COVER = prove
 (`!D (E:A->A->bool) B leq onebee v0 n bet cn cb pnb ckp f b0 mv d bot Gn.
      model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
      (!u. u IN D ==> elmem D E u) /\
      onebee IN D /\ E onebee B /\ etop D E B leq onebee /\
      valuation D v0 /\ (!i. bname D E B (v0 i)) /\
      v0 70 = cn /\ v0 72 = f /\
      echeck D E onebee n cn /\ echeck D E onebee bet cb /\
      eopair D E n bet pnb /\ echeck D E onebee pnb ckp /\
      mv IN D /\ ebv_in D E B leq ckp f mv /\
      b0 IN D /\ E b0 B /\
      erel D E leq b0 (bvalf D E B leq v0
            (?? 74 (!! 71
                    ((?? 73 (opair_form 70 71 73 && (73 %% 72))) -->
                     Eq 71 74)))) /\
      d IN D /\ E d B /\ emeet D E B leq b0 mv d /\
      ebot D E B leq bot /\ ~(d = bot) /\
      Gn IN D /\ bname D E B Gn /\
      bvalf D E B leq ((71 |-> Gn) v0)
        (?? 73 (opair_form 70 71 73 && (73 %% 72))) =
      bvalf D E B leq v0 (?? 71 (?? 73 (opair_form 70 71 73 && (73 %% 72))))
      ==> ?e. e IN D /\ ebv_eq D E B leq Gn cb e /\ ~ebot D E B leq e`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `eporder D (E:A->A->bool) B leq` ASSUME_TAC THENL
   [ASM_MESON_TAC[ECBA_IMP_BALG; EBALG_IMP_PORDER]; ALL_TAC] THEN
  SUBGOAL_THEN `(ckp:A) IN D /\ (cb:A) IN D` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[ECHECK_IMP]; ALL_TAC] THEN
  SUBGOAL_THEN `bname D (E:A->A->bool) B cb /\ bname D (E:A->A->bool) B ckp`
  STRIP_ASSUME_TAC THENL
   [CONJ_TAC THEN MATCH_MP_TAC ECHECK_IS_BNAME THENL
     [MAP_EVERY EXISTS_TAC [`onebee:A`; `bet:A`];
      MAP_EVERY EXISTS_TAC [`onebee:A`; `pnb:A`]] THEN
    ASM_MESON_TAC[ECHECK_IMP]; ALL_TAC] THEN
  (* --- ECHECK_KUR_AUTO : s,p + 8 bundle facts --- *)
  MP_TAC(ISPECL
         [`D:A->bool`; `E:A->A->bool`; `B:A`; `onebee:A`; `n:A`; `bet:A`;
          `cn:A`; `cb:A`; `pnb:A`; `ckp:A`] ECHECK_KUR_AUTO) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `s:A` (X_CHOOSE_THEN `p:A` STRIP_ASSUME_TAC)) THEN
  (* --- v1 = (71|->cb) v0 : valuation/bname/slot facts --- *)
  ABBREV_TAC `v1 = (71 |-> cb) (v0:num->A)` THEN
  SUBGOAL_THEN `valuation D (v1:num->A) /\ (!k. bname D E B ((v1:num->A) k))`
  STRIP_ASSUME_TAC THENL
   [EXPAND_TAC "v1" THEN CONJ_TAC THENL
     [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[];
      MATCH_MP_TAC BNAMEVAL_VALMOD THEN ASM_REWRITE_TAC[]]; ALL_TAC] THEN
  SUBGOAL_THEN `(v1:num->A) 70 = cn /\ v1 71 = cb /\ v1 72 = f`
  STRIP_ASSUME_TAC THENL
   [EXPAND_TAC "v1" THEN
    ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER; ARITH_EQ]; ALL_TAC] THEN
  (* --- BVALF_PMEM_GE : mv <= [[ pm[cb] ]] --- *)
  MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `B:A`; `leq:A`; `v1:num->A`;
    `s:A`; `p:A`; `ckp:A`; `onebee:A`; `mv:A`] BVALF_PMEM_GE) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[] THEN
    REPEAT CONJ_TAC THEN TRY(FIRST_ASSUM ACCEPT_TAC) THEN
    FIRST_X_ASSUM(fun th -> MATCH_ACCEPT_TAC(REWRITE_RULE[] th)); ALL_TAC] THEN
  DISCH_TAC THEN
  (* mv <= [[pm[cb]]], and the goal pm abbreviation *)
  ABBREV_TAC `pm = ?? 73 (opair_form 70 71 73 && (73 %% 72))` THEN
  (* d <= mv (EMEET_LE) and d <= b0 *)
  SUBGOAL_THEN `erel D (E:A->A->bool) leq d mv /\ erel D E leq d b0`
  STRIP_ASSUME_TAC THENL [ASM_MESON_TAC[EMEET_LE]; ALL_TAC] THEN
  (* field facts (IN D + E _ B) for both transitivity steps, read off the two
     erels mv<=[[pm[cb]]] and b0<=[[pm sv]] by EPORDER_FIELD.  This supplies
     E mv B together with both bvalf-IN-D facts, with no EBV_IN_IN_B /
     BVALF_IN_B. *)
  MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `B:A`; `leq:A`; `mv:A`;
    `bvalf D (E:A->A->bool) B leq v1 pm`] EPORDER_FIELD) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN STRIP_TAC THEN
  MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `B:A`; `leq:A`; `b0:A`;
    `bvalf D (E:A->A->bool) B leq v0 (?? 74 (!! 71 (pm --> Eq 71 74)))`]
    EPORDER_FIELD) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN STRIP_TAC THEN
  (* d <= [[pm[cb]]] : d <= mv <= bvalf v1 pm *)
  SUBGOAL_THEN `erel D (E:A->A->bool) leq d (bvalf D E B leq v1 pm)`
    ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `B:A`; `leq:A`;
      `d:A`; `mv:A`; `bvalf D (E:A->A->bool) B leq v1 pm`] EPORDER_TRANS) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* d <= [[pm sv]] : d <= b0 <= [[pm sv]] *)
  SUBGOAL_THEN
   `erel D (E:A->A->bool) leq d
    (bvalf D E B leq v0 (?? 74 (!! 71 (pm --> Eq 71 74))))`
  ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `B:A`; `leq:A`;
      `d:A`; `b0:A`;
      `bvalf D (E:A->A->bool) B leq v0 (?? 74 (!! 71 (pm --> Eq 71 74)))`]
      EPORDER_TRANS) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* --- produce e = [[Gn=cb]] and apply VALNAME_COVER_ONE --- *)
  MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `B:A`; `leq:A`; `Gn:A`; `cb:A`]
    EBV_EQ_VAL_EXISTS) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `e:A` STRIP_ASSUME_TAC) THEN
  EXISTS_TAC `e:A` THEN ASM_REWRITE_TAC[] THEN
  MATCH_MP_TAC(ISPECL
               [`D:A->bool`; `E:A->A->bool`; `B:A`; `leq:A`; `v0:num->A`;
                `Gn:A`; `cb:A`; `d:A`; `e:A`; `bot:A`] VALNAME_COVER_ONE) THEN
  ASM_REWRITE_TAC[] THEN
  MAP_EVERY EXPAND_TAC ["v1"] THEN ASM_REWRITE_TAC[]);;

(* ==== EGGFIBRE_EXISTS: the n-fibre of a relation gg over a1, as a set:
   Wn = { u IN a1 : eapply gg u n } IN D, via ZF_SEPARATION over a1 by
   apply_form 90 0 91 (slots: 90=gg, 0=separation var u, 91=n).  Its char is
   exactly COVER_ABSTRACT's fibre form.  Simple separation (cf.
     ECOLLAPSE_EXISTS
   but one apply_form clause, no cross/echeck). *)

let EGGFIBRE_EXISTS = prove
 (`!D (E:A->A->bool) a1 gg n.
     model D E ZF_AX /\ a1 IN D /\ gg IN D /\ n IN D
     ==> ?Wn. Wn IN D /\
             !u. u IN D ==> (E u Wn <=> E u a1 /\ eapply D E gg u n)`,
  REPEAT STRIP_TAC THEN
  ABBREV_TAC `v0 = (90 |-> (gg:A)) ((91 |-> (n:A)) (\k:num. a1:A))` THEN
  SUBGOAL_THEN `valuation D (v0:num->A)` ASSUME_TAC THENL
   [EXPAND_TAC "v0" THEN
    REPEAT(MATCH_MP_TAC VALUATION_VALMOD THEN
           CONJ_TAC THENL [ALL_TAC; FIRST_ASSUM ACCEPT_TAC]) THEN
    REWRITE_TAC[valuation] THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `v0 90 = gg /\ v0 91 = (n:A)` STRIP_ASSUME_TAC THENL
   [EXPAND_TAC "v0" THEN
    ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER; ARITH_EQ]; ALL_TAC] THEN
  MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`] ZF_SEPARATION) THEN
  ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  DISCH_THEN(MP_TAC o ISPECL
    [`apply_form 90 0 91`; `0`; `v0:num->A`; `a1:A`]) THEN
  ANTS_TAC THENL
   [CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
    DISCH_THEN(X_CHOOSE_THEN `h:A`
      (CONJUNCTS_THEN2 ASSUME_TAC (LABEL_TAC "sep")))] THEN
  EXISTS_TAC `h:A` THEN ASM_REWRITE_TAC[] THEN
  X_GEN_TAC `u:A` THEN DISCH_TAC THEN
  SUBGOAL_THEN `valuation D ((0 |-> (u:A)) v0)` ASSUME_TAC THENL
   [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MP_TAC(SPECL
         [`D:A->bool`; `E:A->A->bool`; `(0 |-> (u:A)) v0`; `90`; `0`; `91`]
         HOLDS_APPLY_FORM) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER; ARITH_EQ] THEN
  DISCH_THEN(LABEL_TAC "hc") THEN
  USE_THEN "sep" (MP_TAC o SPEC `u:A`) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN DISCH_THEN SUBST1_TAC THEN
  USE_THEN "hc" (fun th -> REWRITE_TAC[th]));;

(* ==== MEMVAL_FUNC_UNIFORM (m5-func): "f is a function below b0" gives the
   uniform per-argument functionality that NO_SURJ_NAME needs.
   b0 <= [[ !! 70 sv ]] (sv = single-valued-at-slot-70) ==> for every valuation
   v with v 72 = f, b0 <= [[ sv ]]_v (= f single-valued at v 70).
   Via BVALF_ALL_LB (instantiate the internal forall at v 70) + BVALF_FV_CONG
   (FV sv = {70,72}, so (70|->v 70)v0 and v agree there) + EPORDER_TRANS. *)

let MEMVAL_FUNC_UNIFORM = prove
 (`!D (E:A->A->bool) B leq v0 f b0.
     model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
     valuation D v0 /\ (!i. bname D E B (v0 i)) /\ v0 72 = f /\
     b0 IN D /\ E b0 B /\
     erel D E leq b0 (bvalf D E B leq v0
        (!! 70 (?? 74
                (!! 71 ((?? 73 (opair_form 70 71 73 && (73 %% 72))) -->
                        Eq 71 74)))))
     ==> !v. valuation D v /\ (!i. bname D E B (v i)) /\ v 72 = f
             ==> erel D E leq b0 (bvalf D E B leq v
                   (?? 74 (!! 71
                           ((?? 73 (opair_form 70 71 73 && (73 %% 72))) -->
                            Eq 71 74))))`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  ABBREV_TAC
   `sv = ?? 74
    (!! 71 ((?? 73 (opair_form 70 71 73 && (73 %% 72))) --> Eq 71 74))` THEN
  X_GEN_TAC `v:num->A` THEN STRIP_TAC THEN
  SUBGOAL_THEN `eporder D (E:A->A->bool) B leq` ASSUME_TAC THENL
   [ASM_MESON_TAC[ECBA_IMP_BALG; EBALG_IMP_PORDER]; ALL_TAC] THEN
  SUBGOAL_THEN `bname D (E:A->A->bool) B ((v:num->A) 70)` ASSUME_TAC THENL
   [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(v:num->A) 70 IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[valuation]; ALL_TAC] THEN
  (* BVALF_ALL_LB : bvalf v0 (!! 70 sv) <= bvalf ((70|->v70)v0) sv *)
  MP_TAC(ISPECL [`70`; `sv:form`; `D:A->bool`; `E:A->A->bool`; `B:A`; `leq:A`;
    `v0:num->A`; `(v:num->A) 70`] BVALF_ALL_LB) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN DISCH_TAC THEN
  (* valuation + bname for (70|->v70)v0 *)
  SUBGOAL_THEN
   `valuation D ((70 |-> (v:num->A) 70) v0) /\
    (!i. bname D E B (((70 |-> (v:num->A) 70) v0) i))`
  STRIP_ASSUME_TAC THENL
   [CONJ_TAC THENL
     [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[];
      MATCH_MP_TAC BNAMEVAL_VALMOD THEN ASM_REWRITE_TAC[]]; ALL_TAC] THEN
  (* bvalf ((70|->v70)v0) sv = bvalf v sv  via BVALF_FV_CONG (FV sv = *)
  (* {70,72}) *)
  SUBGOAL_THEN
   `bvalf D (E:A->A->bool) B leq ((70 |-> (v:num->A) 70) v0) sv =
    bvalf D E B leq v sv`
  ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`sv:form`; `D:A->bool`; `E:A->A->bool`; `B:A`; `leq:A`;
                  `(70 |-> (v:num->A) 70) v0`; `v:num->A`] BVALF_FV_CONG) THEN
    ASM_REWRITE_TAC[] THEN
    X_GEN_TAC `i:num` THEN EXPAND_TAC "sv" THEN
    REWRITE_TAC[FV; FV_CLAUSES; FV_OPAIR_FORM; IN_DELETE; IN_UNION; IN_INSERT;
                NOT_IN_EMPTY] THEN
    DISCH_TAC THEN SUBGOAL_THEN `(i:num) = 70 \/ i = 72` MP_TAC THENL
     [ASM_ARITH_TAC; ALL_TAC] THEN
    STRIP_TAC THEN ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER; ARITH_EQ];
    ALL_TAC] THEN
  (* assemble: b0 <= bvalf v0 (!! 70 sv) <= bvalf ((70|->v70)v0) sv = bvalf *)
  (* v sv *)
  SUBGOAL_THEN
   `E (bvalf D (E:A->A->bool) B leq v0 (!! 70 sv)) B /\
    E (bvalf D (E:A->A->bool) B leq v sv) B`
  STRIP_ASSUME_TAC THENL
   [CONJ_TAC THEN MATCH_MP_TAC BVALF_IN_B THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN
   `erel D (E:A->A->bool) leq (bvalf D E B leq v0 (!! 70 sv))
    (bvalf D E B leq v sv)`
  ASSUME_TAC THENL [ASM_MESON_TAC[]; ALL_TAC] THEN
  (* both bvalf endpoints IN D, read off the erel by EPORDER_FIELD *)
  MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `B:A`; `leq:A`;
    `bvalf D (E:A->A->bool) B leq v0 (!! 70 sv)`;
    `bvalf D (E:A->A->bool) B leq v sv`] EPORDER_FIELD) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN STRIP_TAC THEN
  MATCH_MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `B:A`; `leq:A`;
    `b0:A`; `bvalf D (E:A->A->bool) B leq v0 (!! 70 sv)`;
    `bvalf D (E:A->A->bool) B leq v sv`] EPORDER_TRANS) THEN
  ASM_REWRITE_TAC[]);;

(* ==== BVALF_EX_POS_MEET (m5-cover helper): b0-relative
  existential positivity.
   If b0 MEET [[?? n p]] =/= bot then some bname-instance a has b0
     MEET [[p[a]]]
   =/= bot.  Contrapositive: if all b0 MEET [[p[a]]] = bot then [[p[a]]] <= ~b0
   (EMEET_BOT_COMPL), so [[?? n p]] <= ~b0 (BVALF_EX_LEAST),
   so b0 MEET [[?? n p]]
   <= b0 MEET ~b0 = bot (EMEET_MONO + ECOMPL_MEET_JOIN).  Drives
     onto => covering
   (the meta-witness) over the b0 condition. *)

let BVALF_EX_POS_MEET = prove
 (`!n p D (E:A->A->bool) B leq v b0 bot m.
      model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
      valuation D v /\ (!i. bname D E B (v i)) /\
      b0 IN D /\ E b0 B /\ ebot D E B leq bot /\
      m IN D /\ emeet D E B leq b0 (bvalf D E B leq v (?? n p)) m /\
      ~ebot D E B leq m
      ==> ?a mm. a IN D /\ bname D E B a /\ mm IN D /\
                 emeet D E B leq b0 (bvalf D E B leq ((n |-> a) v) p) mm /\
                 ~ebot D E B leq mm`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `ebalg D (E:A->A->bool) B leq /\ eporder D E B leq`
    STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[ECBA_IMP_BALG; EBALG_IMP_PORDER]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) (m:A) B` ASSUME_TAC THENL
   [MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`b0:A`;
      `bvalf D (E:A->A->bool) B leq v (?? n p)`;`m:A`] EMEET_IN) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `?top:A. etop D (E:A->A->bool) B leq top`
    (X_CHOOSE_TAC `top:A`) THENL
   [MATCH_MP_TAC EBALG_TOP THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN
    `(bot:A) IN D /\ (E:A->A->bool) (bot:A) B /\ (top:A) IN D /\ E (top:A) B`
    STRIP_ASSUME_TAC THENL [ASM_MESON_TAC[EBOT_IN; ETOP_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `?cb0:A. ecompl D (E:A->A->bool) B leq b0 cb0`
    (X_CHOOSE_TAC `cb0:A`) THENL
   [MATCH_MP_TAC EBALG_COMPL THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(cb0:A) IN D /\ (E:A->A->bool) (cb0:A) B`
    STRIP_ASSUME_TAC THENL
   [MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`b0:A`;`cb0:A`]
           ECOMPL_IN) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `emeet D (E:A->A->bool) B leq b0 cb0 bot` ASSUME_TAC THENL
   [MP_TAC(ISPECL
           [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`b0:A`;`cb0:A`;`bot:A`;
            `top:A`] ECOMPL_MEET_JOIN) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN STRIP_TAC THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(bvalf D (E:A->A->bool) B leq v (?? n p)) IN D /\
                (E:A->A->bool) (bvalf D E B leq v (?? n p)) B`
  STRIP_ASSUME_TAC THENL
   [CONJ_TAC THENL
     [MP_TAC(ISPECL
             [`(?? n p):form`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
              `v:num->A`] BVALF_SPEC) THEN ASM_SIMP_TAC[];
      MP_TAC(ISPECL
             [`(?? n p):form`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
              `v:num->A`] BVALF_IN_B) THEN ASM_SIMP_TAC[]]; ALL_TAC] THEN
  (* by contradiction *)
  MATCH_MP_TAC(TAUT `(~t ==> F) ==> t`) THEN
  DISCH_THEN(MP_TAC o REWRITE_RULE[NOT_EXISTS_THM]) THEN
  REWRITE_TAC[TAUT
              `~(a /\ b /\ c /\ d /\ ~e) <=> (a /\ b /\ c /\ d ==> e)`] THEN
  DISCH_TAC THEN
  (* [[?? n p]] <= cb0 *)
  SUBGOAL_THEN `erel D (E:A->A->bool) leq (bvalf D E B leq v (?? n p)) cb0`
    ASSUME_TAC THENL
   [MATCH_MP_TAC BVALF_EX_LEAST THEN ASM_REWRITE_TAC[] THEN
    X_GEN_TAC `a:A` THEN STRIP_TAC THEN
    SUBGOAL_THEN `valuation D ((n |-> (a:A)) v) /\
                  (!i. bname D E B (((n |-> (a:A)) v) i))`
      STRIP_ASSUME_TAC THENL
      [CONJ_TAC THENL
       [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[];
        MATCH_MP_TAC BNAMEVAL_VALMOD THEN ASM_REWRITE_TAC[]]; ALL_TAC] THEN
    SUBGOAL_THEN `(bvalf D (E:A->A->bool) B leq ((n |-> (a:A)) v) p) IN D /\
                  (E:A->A->bool) (bvalf D E B leq ((n |-> (a:A)) v) p) B`
      STRIP_ASSUME_TAC THENL
     [CONJ_TAC THENL
       [MP_TAC(ISPECL
               [`p:form`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
                `((n:num) |-> (a:A)) (v:num->A)`] BVALF_SPEC) THEN
        ASM_SIMP_TAC[];
        MP_TAC(ISPECL
               [`p:form`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
                `((n:num) |-> (a:A)) (v:num->A)`] BVALF_IN_B) THEN
        ASM_SIMP_TAC[]]; ALL_TAC] THEN
    SUBGOAL_THEN
     `?mm:A. emeet D (E:A->A->bool) B leq b0
      (bvalf D E B leq ((n |-> (a:A)) v) p) mm`
      (X_CHOOSE_TAC `mm:A`) THENL
     [MATCH_MP_TAC EBALG_MEET THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN `(mm:A) IN D /\ (E:A->A->bool) (mm:A) B`
      STRIP_ASSUME_TAC THENL
      [MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`b0:A`;
        `bvalf D (E:A->A->bool) B leq ((n |-> (a:A)) v) p`;`mm:A`]
          EMEET_IN) THEN
      ASM_REWRITE_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN `ebot D (E:A->A->bool) B leq mm` ASSUME_TAC THENL
     [FIRST_X_ASSUM(MP_TAC o SPECL [`a:A`; `mm:A`]) THEN ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    (* [[p[a]]] <= cb0 via EMEET_BOT_COMPL *)
    MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
       `bvalf D (E:A->A->bool) B leq ((n |-> (a:A)) v) p`;`b0:A`;`cb0:A`;
       `mm:A`;`bot:A`]
       EMEET_BOT_COMPL) THEN
    ASM_REWRITE_TAC[] THEN REPEAT CONJ_TAC THENL
     [MATCH_MP_TAC EMEET_SYM THEN ASM_REWRITE_TAC[];
      MATCH_MP_TAC EBOT_LE THEN EXISTS_TAC `B:A` THEN ASM_REWRITE_TAC[]];
    ALL_TAC] THEN
  (* m = b0 MEET [[?? n p]] <= b0 MEET cb0 = bot, so ebot m, contra *)
  SUBGOAL_THEN `erel D (E:A->A->bool) leq m bot` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
      `b0:A`;`bvalf D (E:A->A->bool) B leq v (?? n p)`;`b0:A`;`cb0:A`;
      `m:A`;`bot:A`]
      EMEET_MONO) THEN
    ASM_REWRITE_TAC[] THEN MATCH_MP_TAC EPORDER_REFL THEN
    EXISTS_TAC `B:A` THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(m:A) = bot` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`m:A`;`bot:A`]
                 ELE_BOT) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  UNDISCH_TAC `~ebot D (E:A->A->bool) B leq m` THEN ASM_REWRITE_TAC[]);;

(* ===================================================================== *)
(* F7.2 m5-cover LE ladder (part 1): extensionality-LE foundation.       *)
(*   BVALF_IFF_CONG (connective congruence) + BVALF_MEMEXT_LE: the        *)
(*   Boolean mutual-membership value [[!! k ((k%%i)<->(k%%j))]] is below    *)
(*   the Boolean equality value ebv_eq(v i, v j), at arbitrary slots.     *)
(*   Reuses the PROVEN extensionality axiom (no EBV_EQ_GLB_STAGE machinery)*)
(* ===================================================================== *)
(* ==== BVALF_IFF_CONG: equal side-values give equal iff-values.
   If [[p1]]_v1=[[p2]]_v2 and [[q1]]_v1=[[q2]]_v2 then
     [[p1<->q1]]_v1=[[p2<->q2]]_v2.
   The connective-congruence lemma for the cross-binder match in the LE ladder:
   <-> = (p-->q)&&(q-->p); --> is ebimp (BVALF_IMP, unique via EBIMP_UNIQUE),
   && is emeet (BVALF_AND_MEET, unique via EMEET_UNIQUE). *)

let BVALF_IFF_CONG = prove
 (`!p1 q1 p2 q2 D (E:A->A->bool) B leq v1 v2.
      model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
      valuation D v1 /\ (!i. bname D E B (v1 i)) /\
      valuation D v2 /\ (!i. bname D E B (v2 i)) /\
      bvalf D E B leq v1 p1 = bvalf D E B leq v2 p2 /\
      bvalf D E B leq v1 q1 = bvalf D E B leq v2 q2
      ==> bvalf D E B leq v1 (p1 <-> q1) = bvalf D E B leq v2 (p2 <-> q2)`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `ebalg D (E:A->A->bool) B leq /\ eporder D E B leq`
    STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[ECBA_IMP_BALG; EBALG_IMP_PORDER]; ALL_TAC] THEN
  (* antecedent values IN D / E .. B (for EBIMP_UNIQUE's x IN D /\ E x B) *)
  SUBGOAL_THEN
    `(bvalf D (E:A->A->bool) B leq v2 p2) IN D /\
     (E:A->A->bool) (bvalf D E B leq v2 p2) B /\
     (bvalf D (E:A->A->bool) B leq v2 q2) IN D /\
     (E:A->A->bool) (bvalf D E B leq v2 q2) B`
    STRIP_ASSUME_TAC THENL
   [REPEAT CONJ_TAC THENL
     [MP_TAC(ISPECL
             [`p2:form`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`v2:num->A`]
             BVALF_SPEC) THEN ASM_SIMP_TAC[];
      MP_TAC(ISPECL
             [`p2:form`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`v2:num->A`]
             BVALF_IN_B) THEN ASM_SIMP_TAC[];
      MP_TAC(ISPECL
             [`q2:form`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`v2:num->A`]
             BVALF_SPEC) THEN ASM_SIMP_TAC[];
      MP_TAC(ISPECL
             [`q2:form`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`v2:num->A`]
             BVALF_IN_B) THEN ASM_SIMP_TAC[]];
    ALL_TAC] THEN
  (* bvalf v1 (p1-->q1) = bvalf v2 (p2-->q2) *)
  SUBGOAL_THEN
    `bvalf D (E:A->A->bool) B leq v1 (p1 --> q1) = bvalf D E B leq v2
     (p2 --> q2)`
    ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
       `bvalf D (E:A->A->bool) B leq v2 p2`;
       `bvalf D (E:A->A->bool) B leq v2 q2`;
       `bvalf D (E:A->A->bool) B leq v1 (p1 --> q1)`;
       `bvalf D (E:A->A->bool) B leq v2 (p2 --> q2)`] EBIMP_UNIQUE) THEN
    ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
     [SUBST1_TAC(SYM(ASSUME
        `bvalf D (E:A->A->bool) B leq v1 p1 = bvalf D E B leq v2 p2`)) THEN
      SUBST1_TAC(SYM(ASSUME
        `bvalf D (E:A->A->bool) B leq v1 q1 = bvalf D E B leq v2 q2`)) THEN
      MP_TAC(ISPECL
             [`p1:form`;`q1:form`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
              `v1:num->A`] BVALF_IMP) THEN ASM_SIMP_TAC[];
      MP_TAC(ISPECL
             [`p2:form`;`q2:form`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
              `v2:num->A`] BVALF_IMP) THEN ASM_SIMP_TAC[]];
    ALL_TAC] THEN
  (* bvalf v1 (q1-->p1) = bvalf v2 (q2-->p2) *)
  SUBGOAL_THEN
    `bvalf D (E:A->A->bool) B leq v1 (q1 --> p1) = bvalf D E B leq v2
     (q2 --> p2)`
    ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
       `bvalf D (E:A->A->bool) B leq v2 q2`;
       `bvalf D (E:A->A->bool) B leq v2 p2`;
       `bvalf D (E:A->A->bool) B leq v1 (q1 --> p1)`;
       `bvalf D (E:A->A->bool) B leq v2 (q2 --> p2)`] EBIMP_UNIQUE) THEN
    ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
     [SUBST1_TAC(SYM(ASSUME
        `bvalf D (E:A->A->bool) B leq v1 q1 = bvalf D E B leq v2 q2`)) THEN
      SUBST1_TAC(SYM(ASSUME
        `bvalf D (E:A->A->bool) B leq v1 p1 = bvalf D E B leq v2 p2`)) THEN
      MP_TAC(ISPECL
             [`q1:form`;`p1:form`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
              `v1:num->A`] BVALF_IMP) THEN ASM_SIMP_TAC[];
      MP_TAC(ISPECL
             [`q2:form`;`p2:form`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
              `v2:num->A`] BVALF_IMP) THEN ASM_SIMP_TAC[]];
    ALL_TAC] THEN
  (* assemble via && = emeet *)
  REWRITE_TAC[Iff_DEF] THEN
  MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
     `bvalf D (E:A->A->bool) B leq v2 (p2 --> q2)`;
     `bvalf D (E:A->A->bool) B leq v2 (q2 --> p2)`;
     `bvalf D (E:A->A->bool) B leq v1 ((p1 --> q1) && (q1 --> p1))`;
     `bvalf D (E:A->A->bool) B leq v2 ((p2 --> q2) && (q2 --> p2))`]
      EMEET_UNIQUE) THEN
  ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
   [SUBST1_TAC(SYM(ASSUME
      `bvalf D (E:A->A->bool) B leq v1 (p1 --> q1) = bvalf D E B leq v2
       (p2 --> q2)`)) THEN
    SUBST1_TAC(SYM(ASSUME
      `bvalf D (E:A->A->bool) B leq v1 (q1 --> p1) = bvalf D E B leq v2
       (q2 --> p2)`)) THEN
    MP_TAC(ISPECL
           [`p1 --> q1`;`q1 --> p1`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
            `v1:num->A`] BVALF_AND_MEET) THEN ASM_SIMP_TAC[];
    MP_TAC(ISPECL
           [`p2 --> q2`;`q2 --> p2`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
            `v2:num->A`] BVALF_AND_MEET) THEN ASM_SIMP_TAC[]]);;

(* ==== BVALF_MEMEXT_LE: the reusable extensionality-LE core.
   [[!! k ((k%%i) <-> (k%%j))]]_v <= ebv_eq(v i, v j).  "Boolean mutual
   membership value is below the Boolean equality value", at ARBITRARY slots
   i,j and fresh binder k.  Proof reuses the PROVEN extensionality AXIOM
   (BVALF_EXTENSIONALITY) instantiated at (0:=v i, 1:=v j) + BVALF_IMP_TOP
   residuation + a cross-binder glb match (BVALF_ALL_GLB on the ext side,
   BVALF_ALL_LB on the pair side, per-instance via BVALF_IFF_CONG + EBV_IN_
   UNIQUE).  NO stage machinery (EBV_EQ_GLB_STAGE avoided). *)

let BVALF_MEMEXT_LE = prove
 (`!D (E:A->A->bool) B leq v i j k e.
      model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
      valuation D v /\ (!m. bname D E B (v m)) /\
      ~(k = i) /\ ~(k = j) /\
      e IN D /\ ebv_eq D E B leq (v i) (v j) e
      ==> erel D E leq (bvalf D E B leq v (!! k ((k %% i) <-> (k %% j)))) e`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `ebalg D (E:A->A->bool) B leq /\ eporder D E B leq`
    STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[ECBA_IMP_BALG; EBALG_IMP_PORDER]; ALL_TAC] THEN
  SUBGOAL_THEN `!m. (v:num->A) m IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[valuation]; ALL_TAC] THEN
  (* base1 = (0|->v i) v *)
  SUBGOAL_THEN
    `valuation D ((0 |-> (v:num->A) i) v) /\
     (!m. bname D E B (((0 |-> (v:num->A) i) v) m))`
    STRIP_ASSUME_TAC THENL
   [CONJ_TAC THENL
     [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[];
      MATCH_MP_TAC BNAMEVAL_VALMOD THEN ASM_REWRITE_TAC[]]; ALL_TAC] THEN
  (* w3 = (1|->v j)((0|->v i) v) : valuation + bname + slot values *)
  SUBGOAL_THEN
    `valuation D ((1 |-> (v:num->A) j) ((0 |-> (v:num->A) i) v)) /\
     (!m. bname D E B (((1 |-> (v:num->A) j) ((0 |-> (v:num->A) i) v)) m))`
    STRIP_ASSUME_TAC THENL
   [CONJ_TAC THENL
     [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[];
      MATCH_MP_TAC BNAMEVAL_VALMOD THEN ASM_REWRITE_TAC[]]; ALL_TAC] THEN
  SUBGOAL_THEN
    `((1 |-> (v:num->A) j) ((0 |-> (v:num->A) i) v)) 0 = (v:num->A) i /\
     ((1 |-> (v:num->A) j) ((0 |-> (v:num->A) i) v)) 1 = (v:num->A) j`
    STRIP_ASSUME_TAC THENL
   [SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER; ARITH_EQ]; ALL_TAC] THEN
  (* the extensionality axiom at v, instantiated 0:=v i, 1:=v j *)
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`v:num->A`]
    BVALF_EXTENSIONALITY) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  REWRITE_TAC[extensionality_ax] THEN
  MP_TAC(ISPECL [`0`; `!! 1 ((!! 2 ((2 %% 0) <-> (2 %% 1))) --> Eq 0 1)`;
    `D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`v:num->A`] BVALF_ALL_TOP) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  DISCH_THEN(MP_TAC o SPEC `(v:num->A) i`) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MP_TAC(ISPECL [`1`; `(!! 2 ((2 %% 0) <-> (2 %% 1))) --> Eq 0 1`;
    `D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`(0 |-> (v:num->A) i) v`]
      BVALF_ALL_TOP) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  DISCH_THEN(MP_TAC o SPEC `(v:num->A) j`) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_TAC THEN
  (* turn etop(bvalf w3 (P-->Q)) into erel leq (bvalf w3 P)(bvalf w3 Q) *)
  MP_TAC(ISPECL [`!! 2 ((2 %% 0) <-> (2 %% 1))`; `Eq 0 1`;
    `D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
    `(1 |-> (v:num->A) j) ((0 |-> (v:num->A) i) v)`] BVALF_IMP_TOP) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(fun th -> RULE_ASSUM_TAC(REWRITE_RULE[th])) THEN
  (* [[Eq 0 1]]_w3 = e *)
  SUBGOAL_THEN
    `bvalf D (E:A->A->bool) B leq
       ((1 |-> (v:num->A) j) ((0 |-> (v:num->A) i) v)) (Eq 0 1) = e`
    ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`(v:num->A) i`;
                  `(v:num->A) j`;
      `bvalf D (E:A->A->bool) B leq
       ((1 |-> (v:num->A) j) ((0 |-> (v:num->A) i) v)) (Eq 0 1)`;
      `e:A`] EBV_EQ_UNIQUE) THEN
    ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
     [MP_TAC(ISPECL [`Eq 0 1`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
        `(1 |-> (v:num->A) j) ((0 |-> (v:num->A) i) v)`] BVALF_SPEC) THEN
                 ASM_SIMP_TAC[];
                 MP_TAC(ISPECL
                        [`0`;`1`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
                         `(1 |-> (v:num->A) j) ((0 |-> (v:num->A) i) v)`]
                          BVALF_EQ2) THEN ASM_SIMP_TAC[]];
    ALL_TAC] THEN
  (* erel leq (bvalf v (!! k ...)) (bvalf w3 (!! 2 ...)) by cross-binder glb *)
  (* match *)
  SUBGOAL_THEN
    `erel D (E:A->A->bool) leq
       (bvalf D E B leq v (!! k ((k %% i) <-> (k %% j))))
       (bvalf D E B leq ((1 |-> (v:num->A) j) ((0 |-> (v:num->A) i) v))
          (!! 2 ((2 %% 0) <-> (2 %% 1))))`
    ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`2`;`(2 %% 0) <-> (2 %% 1)`;`D:A->bool`;`E:A->A->bool`;
                  `B:A`;`leq:A`;
                  `(1 |-> (v:num->A) j) ((0 |-> (v:num->A) i) v)`;
                  `bvalf D (E:A->A->bool) B leq v
                   (!! k ((k %% i) <-> (k %% j)))`] BVALF_ALL_GLB) THEN
    ASM_REWRITE_TAC[] THEN REPEAT CONJ_TAC THENL
     [MP_TAC(ISPECL [`!! k ((k %% i) <-> (k %% j))`;`D:A->bool`;`E:A->A->bool`;
        `B:A`;`leq:A`;`v:num->A`] BVALF_SPEC) THEN ASM_SIMP_TAC[];
      MP_TAC(ISPECL [`!! k ((k %% i) <-> (k %% j))`;`D:A->bool`;`E:A->A->bool`;
        `B:A`;`leq:A`;`v:num->A`] BVALF_IN_B) THEN ASM_SIMP_TAC[];
      X_GEN_TAC `c:A` THEN STRIP_TAC THEN
      SUBGOAL_THEN
        `valuation D (((k:num) |-> (c:A)) (v:num->A)) /\
         (!m. bname D E B ((((k:num) |-> (c:A)) (v:num->A)) m))`
        STRIP_ASSUME_TAC THENL
       [CONJ_TAC THENL
         [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[];
          MATCH_MP_TAC BNAMEVAL_VALMOD THEN ASM_REWRITE_TAC[]]; ALL_TAC] THEN
      SUBGOAL_THEN
        `valuation D
         ((2 |-> (c:A)) ((1 |-> (v:num->A) j) ((0 |-> (v:num->A) i) v))) /\
         (!m. bname D E B
          (((2 |-> (c:A)) ((1 |-> (v:num->A) j) ((0 |-> (v:num->A) i) v))) m))`
        STRIP_ASSUME_TAC THENL
       [CONJ_TAC THENL
         [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[];
          MATCH_MP_TAC BNAMEVAL_VALMOD THEN ASM_REWRITE_TAC[]]; ALL_TAC] THEN
      SUBGOAL_THEN
        `(((k:num) |-> (c:A)) (v:num->A)) k = c /\
         (((k:num) |-> (c:A)) (v:num->A)) i = (v:num->A) i /\
         (((k:num) |-> (c:A)) (v:num->A)) j = (v:num->A) j /\
         ((2 |-> (c:A))
          ((1 |-> (v:num->A) j) ((0 |-> (v:num->A) i) v))) 2 = c /\
         ((2 |-> (c:A)) ((1 |-> (v:num->A) j) ((0 |-> (v:num->A) i) v))) 0 =
           (v:num->A) i /\
         ((2 |-> (c:A)) ((1 |-> (v:num->A) j) ((0 |-> (v:num->A) i) v))) 1 =
           (v:num->A) j`
        STRIP_ASSUME_TAC THENL
       [ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER; ARITH_EQ]; ALL_TAC] THEN
      SUBGOAL_THEN
        `bvalf D (E:A->A->bool) B leq (((k:num) |-> (c:A)) (v:num->A))
           ((k %% i) <-> (k %% j)) =
         bvalf D E B leq
           ((2 |-> (c:A)) ((1 |-> (v:num->A) j) ((0 |-> (v:num->A) i) v)))
           ((2 %% 0) <-> (2 %% 1))`
        ASSUME_TAC THENL
       [MATCH_MP_TAC(ISPECL
                     [`(k:num) %% i`;`(k:num) %% j`;`(2:num) %% 0`;
                      `(2:num) %% 1`;
                      `D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
                      `((k:num) |-> (c:A)) (v:num->A)`;
                      `(2 |-> (c:A))
                       ((1 |-> (v:num->A) j) ((0 |-> (v:num->A) i) v))`]
                       BVALF_IFF_CONG) THEN
        ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
         [MATCH_MP_TAC(ISPECL
                       [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`c:A`;
                        `(v:num->A) i`;
                        `bvalf D (E:A->A->bool) B leq
                         (((k:num) |-> (c:A)) (v:num->A)) (k %% i)`;
            `bvalf D (E:A->A->bool) B leq
               ((2 |-> (c:A))
                ((1 |-> (v:num->A) j) ((0 |-> (v:num->A) i) v))) (2 %% 0)`]
            EBV_IN_UNIQUE) THEN
          ASM_REWRITE_TAC[] THEN REPEAT CONJ_TAC THENL
           [MP_TAC(ISPECL
                   [`(k:num) %% i`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
                    `((k:num) |-> (c:A)) (v:num->A)`] BVALF_SPEC) THEN
            ASM_SIMP_TAC[];
            MP_TAC(ISPECL
                   [`(2:num) %% 0`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
                    `(2 |-> (c:A))
                     ((1 |-> (v:num->A) j) ((0 |-> (v:num->A) i) v))`]
                     BVALF_SPEC) THEN
              ASM_SIMP_TAC[];
            MP_TAC(ISPECL
                   [`k:num`;`i:num`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
                    `((k:num) |-> (c:A)) (v:num->A)`] BVALF_MEM) THEN
            ASM_SIMP_TAC[];
            MP_TAC(ISPECL [`2`;`0`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
              `(2 |-> (c:A)) ((1 |-> (v:num->A) j) ((0 |-> (v:num->A) i) v))`]
                     BVALF_MEM) THEN
              ASM_SIMP_TAC[]];
          MATCH_MP_TAC(ISPECL
                       [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`c:A`;
                        `(v:num->A) j`;
                        `bvalf D (E:A->A->bool) B leq
                         (((k:num) |-> (c:A)) (v:num->A)) (k %% j)`;
            `bvalf D (E:A->A->bool) B leq
               ((2 |-> (c:A))
                ((1 |-> (v:num->A) j) ((0 |-> (v:num->A) i) v))) (2 %% 1)`]
            EBV_IN_UNIQUE) THEN
          ASM_REWRITE_TAC[] THEN REPEAT CONJ_TAC THENL
           [MP_TAC(ISPECL
                   [`(k:num) %% j`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
                    `((k:num) |-> (c:A)) (v:num->A)`] BVALF_SPEC) THEN
            ASM_SIMP_TAC[];
            MP_TAC(ISPECL
                   [`(2:num) %% 1`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
                    `(2 |-> (c:A))
                     ((1 |-> (v:num->A) j) ((0 |-> (v:num->A) i) v))`]
                     BVALF_SPEC) THEN
              ASM_SIMP_TAC[];
            MP_TAC(ISPECL
                   [`k:num`;`j:num`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
                    `((k:num) |-> (c:A)) (v:num->A)`] BVALF_MEM) THEN
            ASM_SIMP_TAC[];
            MP_TAC(ISPECL [`2`;`1`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
              `(2 |-> (c:A)) ((1 |-> (v:num->A) j) ((0 |-> (v:num->A) i) v))`]
                     BVALF_MEM) THEN
              ASM_SIMP_TAC[]]];
        ALL_TAC] THEN
      SUBGOAL_THEN
        `erel D (E:A->A->bool) leq
         (bvalf D E B leq v (!! k ((k %% i) <-> (k %% j))))
           (bvalf D E B leq (((k:num) |-> (c:A)) (v:num->A))
            ((k %% i) <-> (k %% j)))` MP_TAC THENL
       [MATCH_MP_TAC(ISPECL
                     [`k:num`;`(k %% i) <-> (k %% j)`;`D:A->bool`;
                      `E:A->A->bool`;
                      `B:A`;`leq:A`;`v:num->A`;`c:A`] BVALF_ALL_LB) THEN
           ASM_REWRITE_TAC[]; ALL_TAC] THEN
      ASM_REWRITE_TAC[]];
    ALL_TAC] THEN
  (* field facts for the three bvalf terms *)
  SUBGOAL_THEN
    `(bvalf D (E:A->A->bool) B leq v (!! k ((k %% i) <-> (k %% j)))) IN D /\
     (E:A->A->bool) (bvalf D E B leq v (!! k ((k %% i) <-> (k %% j)))) B /\
     (bvalf D (E:A->A->bool) B leq
      ((1 |-> (v:num->A) j) ((0 |-> (v:num->A) i) v))
      (!! 2 ((2 %% 0) <-> (2 %% 1)))) IN D /\
     (E:A->A->bool)
       (bvalf D E B leq ((1 |-> (v:num->A) j) ((0 |-> (v:num->A) i) v))
        (!! 2 ((2 %% 0) <-> (2 %% 1)))) B /\
     (bvalf D (E:A->A->bool) B leq
      ((1 |-> (v:num->A) j) ((0 |-> (v:num->A) i) v))
      (Eq 0 1)) IN D /\
     (E:A->A->bool)
       (bvalf D E B leq ((1 |-> (v:num->A) j) ((0 |-> (v:num->A) i) v))
        (Eq 0 1)) B`
    STRIP_ASSUME_TAC THENL
   [REPEAT CONJ_TAC THENL
     [MP_TAC(ISPECL [`!! k ((k %% i) <-> (k %% j))`;`D:A->bool`;`E:A->A->bool`;
        `B:A`;`leq:A`;`v:num->A`] BVALF_SPEC) THEN ASM_SIMP_TAC[];
      MP_TAC(ISPECL [`!! k ((k %% i) <-> (k %% j))`;`D:A->bool`;`E:A->A->bool`;
        `B:A`;`leq:A`;`v:num->A`] BVALF_IN_B) THEN ASM_SIMP_TAC[];
      MP_TAC(ISPECL [`!! 2 ((2 %% 0) <-> (2 %% 1))`;`D:A->bool`;`E:A->A->bool`;
        `B:A`;`leq:A`;`(1 |-> (v:num->A) j) ((0 |-> (v:num->A) i) v)`]
             BVALF_SPEC) THEN
        ASM_SIMP_TAC[];
      MP_TAC(ISPECL [`!! 2 ((2 %% 0) <-> (2 %% 1))`;`D:A->bool`;`E:A->A->bool`;
        `B:A`;`leq:A`;`(1 |-> (v:num->A) j) ((0 |-> (v:num->A) i) v)`]
               BVALF_IN_B) THEN
        ASM_SIMP_TAC[];
      MP_TAC(ISPECL [`Eq 0 1`;`D:A->bool`;`E:A->A->bool`;
        `B:A`;`leq:A`;`(1 |-> (v:num->A) j) ((0 |-> (v:num->A) i) v)`]
                 BVALF_SPEC) THEN
        ASM_SIMP_TAC[];
      MP_TAC(ISPECL [`Eq 0 1`;`D:A->bool`;`E:A->A->bool`;
        `B:A`;`leq:A`;`(1 |-> (v:num->A) j) ((0 |-> (v:num->A) i) v)`]
                   BVALF_IN_B) THEN
        ASM_SIMP_TAC[]];
    ALL_TAC] THEN
  (* LHS <= [[Eq 0 1]]_w3 by transitivity through [[!! 2 ..]]_w3; then = e *)
  SUBGOAL_THEN
    `erel D (E:A->A->bool) leq
     (bvalf D E B leq v (!! k ((k %% i) <-> (k %% j))))
       (bvalf D E B leq
        ((1 |-> (v:num->A) j) ((0 |-> (v:num->A) i) v)) (Eq 0 1))`
    MP_TAC THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
      `bvalf D (E:A->A->bool) B leq v (!! k ((k %% i) <-> (k %% j)))`;
      `bvalf D (E:A->A->bool) B leq
       ((1 |-> (v:num->A) j) ((0 |-> (v:num->A) i) v))
         (!! 2 ((2 %% 0) <-> (2 %% 1)))`;
      `bvalf D (E:A->A->bool) B leq
       ((1 |-> (v:num->A) j) ((0 |-> (v:num->A) i) v))
         (Eq 0 1)`] EPORDER_TRANS) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  ASM_REWRITE_TAC[]);;

(* ===================================================================== *)
(* F7.2 m5-cover LE ladder (part 2): BVALF_PAIRFORM_LE.                   *)
(*   [[pair_form ia ib ic]]_v <= ebv_eq(v ic, up) for the V^B pair-name   *)
(*   up of (v ia, v ib).  LE companion of BVALF_PAIRFORM_TOP.             *)
(* ===================================================================== *)
(* ==== BVALF_PAIRFORM_LE: [[pair_form ia ib ic]]_v <= ebv_eq(v ic, up), where
   up is the V^B unordered pair-name of (v ia, v ib).  The LE companion of
   BVALF_PAIRFORM_TOP.  Move v -> (jup|->up)v (jup = MAX..+2 fresh)
     by BVALF_FV_
   CONG; swap the body Eq||Eq -> (mp %% jup) via BVALF_ALL_CONG +
     BVALF_IFF_CONG
   + EBV_IN_UPAIR (mirroring BVALF_PAIRFORM_TOP's core);
   then BVALF_MEMEXT_LE. *)

let BVALF_PAIRFORM_LE = prove
 (`!D (E:A->A->bool) B leq (v:num->A) ia ib ic up top ee.
      model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
      valuation D v /\ (!k. bname D E B (v k)) /\
      up IN D /\ bname D E B up /\ top IN D /\ etop D E B leq top /\
      eapply D E up (v ia) top /\ eapply D E up (v ib) top /\
      (!t q. t IN D /\ q IN D /\ eapply D E up t q ==> t = v ia \/ t = v ib) /\
      ee IN D /\ ebv_eq D E B leq (v ic) up ee
      ==> erel D E leq (bvalf D E B leq v (pair_form ia ib ic)) ee`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `!x. (v:num->A) x IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[valuation]; ALL_TAC] THEN
  SUBGOAL_THEN
    `~(MAX (MAX ia ib) ic + 2 = ia) /\ ~(MAX (MAX ia ib) ic + 2 = ib) /\
     ~(MAX (MAX ia ib) ic + 2 = ic) /\ ~(MAX (MAX ia ib) ic + 1 = ia) /\
     ~(MAX (MAX ia ib) ic + 1 = ib) /\ ~(MAX (MAX ia ib) ic + 1 = ic) /\
     ~(MAX (MAX ia ib) ic + 1 = MAX (MAX ia ib) ic + 2)`
    STRIP_ASSUME_TAC THENL [ARITH_TAC; ALL_TAC] THEN
  (* v' = (jup|->up) v, jup = MAX..+2 *)
  SUBGOAL_THEN
    `valuation D (((MAX (MAX ia ib) ic + 2) |-> up) (v:num->A)) /\
     (!k. bname D E B ((((MAX (MAX ia ib) ic + 2) |-> up) (v:num->A)) k))`
    STRIP_ASSUME_TAC THENL
   [CONJ_TAC THENL
     [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[];
      MATCH_MP_TAC BNAMEVAL_VALMOD THEN ASM_REWRITE_TAC[]]; ALL_TAC] THEN
  SUBGOAL_THEN
    `(((MAX (MAX ia ib) ic + 2) |-> up) (v:num->A)) ia = (v:num->A) ia /\
     (((MAX (MAX ia ib) ic + 2) |-> up) (v:num->A)) ib = (v:num->A) ib /\
     (((MAX (MAX ia ib) ic + 2) |-> up) (v:num->A)) ic = (v:num->A) ic /\
     (((MAX (MAX ia ib) ic + 2) |-> up) (v:num->A))
       (MAX (MAX ia ib) ic + 2) = up`
    STRIP_ASSUME_TAC THENL
   [ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER]; ALL_TAC] THEN
  (* [[pair_form]]_v = [[pair_form]]_v' (jup not free in pair_form) *)
  SUBGOAL_THEN
    `bvalf D (E:A->A->bool) B leq v (pair_form ia ib ic) =
     bvalf D E B leq (((MAX (MAX ia ib) ic + 2) |-> up) (v:num->A))
       (pair_form ia ib ic)`
    SUBST1_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`pair_form ia ib ic`;`D:A->bool`;`E:A->A->bool`;
                  `B:A`;`leq:A`;
                  `v:num->A`;`((MAX (MAX ia ib) ic + 2) |-> up) (v:num->A)`]
                   BVALF_FV_CONG) THEN
    ASM_REWRITE_TAC[FV_PAIR_FORM; IN_INSERT; NOT_IN_EMPTY] THEN
    REPEAT STRIP_TAC THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  REWRITE_TAC[pair_form] THEN
  (* swap body Eq||Eq -> (mp %% jup) via BVALF_ALL_CONG *)
  SUBGOAL_THEN
    `bvalf D (E:A->A->bool) B leq
     (((MAX (MAX ia ib) ic + 2) |-> up) (v:num->A))
       (!! (MAX (MAX ia ib) ic + 1)
           (((MAX (MAX ia ib) ic + 1) %% ic) <->
            Eq (MAX (MAX ia ib) ic + 1) ia ||
              Eq (MAX (MAX ia ib) ic + 1) ib)) =
     bvalf D E B leq (((MAX (MAX ia ib) ic + 2) |-> up) (v:num->A))
       (!! (MAX (MAX ia ib) ic + 1)
           (((MAX (MAX ia ib) ic + 1) %% ic) <->
            ((MAX (MAX ia ib) ic + 1) %% (MAX (MAX ia ib) ic + 2))))`
    SUBST1_TAC THENL
   [MATCH_MP_TAC(ISPECL [`MAX (MAX ia ib) ic + 1`;
      `((MAX (MAX ia ib) ic + 1) %% ic) <->
       Eq (MAX (MAX ia ib) ic + 1) ia || Eq (MAX (MAX ia ib) ic + 1) ib`;
      `((MAX (MAX ia ib) ic + 1) %% ic) <->
       ((MAX (MAX ia ib) ic + 1) %% (MAX (MAX ia ib) ic + 2))`;
      `D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
      `((MAX (MAX ia ib) ic + 2) |-> up) (v:num->A)`] BVALF_ALL_CONG) THEN
    ASM_REWRITE_TAC[] THEN
    X_GEN_TAC `c:A` THEN STRIP_TAC THEN
    SUBGOAL_THEN
      `valuation D (((MAX (MAX ia ib) ic + 1) |-> (c:A))
          (((MAX (MAX ia ib) ic + 2) |-> up) (v:num->A))) /\
       (!k. bname D E B ((((MAX (MAX ia ib) ic + 1) |-> (c:A))
          (((MAX (MAX ia ib) ic + 2) |-> up) (v:num->A))) k))`
      STRIP_ASSUME_TAC THENL
     [CONJ_TAC THENL
       [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[];
        MATCH_MP_TAC BNAMEVAL_VALMOD THEN ASM_REWRITE_TAC[]]; ALL_TAC] THEN
    MATCH_MP_TAC(ISPECL [
      `(MAX (MAX ia ib) ic + 1) %% ic`;
      `Eq (MAX (MAX ia ib) ic + 1) ia || Eq (MAX (MAX ia ib) ic + 1) ib`;
      `(MAX (MAX ia ib) ic + 1) %% ic`;
      `(MAX (MAX ia ib) ic + 1) %% (MAX (MAX ia ib) ic + 2)`;
      `D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
      `((MAX (MAX ia ib) ic + 1) |-> (c:A))
       (((MAX (MAX ia ib) ic + 2) |-> up) (v:num->A))`;
      `((MAX (MAX ia ib) ic + 1) |-> (c:A))
       (((MAX (MAX ia ib) ic + 2) |-> up) (v:num->A))`]
      BVALF_IFF_CONG) THEN
    ASM_REWRITE_TAC[] THEN
    (* reflexive conjunct auto-closes; remaining: bvalf vc (Eq||Eq) = bvalf *)
    (* vc (mp%%jup) vc = (mp|->c)v' slot values *)
    SUBGOAL_THEN
      `(((MAX (MAX ia ib) ic + 1) |-> (c:A))
        (((MAX (MAX ia ib) ic + 2) |-> up) (v:num->A)))
         (MAX (MAX ia ib) ic + 1) = c /\
       (((MAX (MAX ia ib) ic + 1) |-> (c:A))
        (((MAX (MAX ia ib) ic + 2) |-> up) (v:num->A)))
         ia = (v:num->A) ia /\
       (((MAX (MAX ia ib) ic + 1) |-> (c:A))
        (((MAX (MAX ia ib) ic + 2) |-> up) (v:num->A)))
         ib = (v:num->A) ib /\
       (((MAX (MAX ia ib) ic + 1) |-> (c:A))
        (((MAX (MAX ia ib) ic + 2) |-> up) (v:num->A)))
         (MAX (MAX ia ib) ic + 2) = up`
      STRIP_ASSUME_TAC THENL
     [ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER]; ALL_TAC] THEN
    (* zin,za,zb,zj and EBV_IN_UPAIR : [[mp%%jup]] = [[Eq||Eq]] *)
    MP_TAC(ISPECL
           [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`(v:num->A) ia`;
            `(v:num->A) ib`;
            `up:A`;`top:A`;`c:A`;
      `bvalf D (E:A->A->bool) B leq
         (((MAX (MAX ia ib) ic + 1) |-> (c:A))
          (((MAX (MAX ia ib) ic + 2) |-> up) (v:num->A)))
         ((MAX (MAX ia ib) ic + 1) %% (MAX (MAX ia ib) ic + 2))`;
      `bvalf D (E:A->A->bool) B leq
         (((MAX (MAX ia ib) ic + 1) |-> (c:A))
          (((MAX (MAX ia ib) ic + 2) |-> up) (v:num->A)))
         (Eq (MAX (MAX ia ib) ic + 1) ia)`;
      `bvalf D (E:A->A->bool) B leq
         (((MAX (MAX ia ib) ic + 1) |-> (c:A))
          (((MAX (MAX ia ib) ic + 2) |-> up) (v:num->A)))
         (Eq (MAX (MAX ia ib) ic + 1) ib)`;
      `bvalf D (E:A->A->bool) B leq
         (((MAX (MAX ia ib) ic + 1) |-> (c:A))
          (((MAX (MAX ia ib) ic + 2) |-> up) (v:num->A)))
         (Eq (MAX (MAX ia ib) ic + 1) ia || Eq (MAX (MAX ia ib) ic + 1) ib)`]
      EBV_IN_UPAIR) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[] THEN REPEAT CONJ_TAC THENL
       [MP_TAC(ISPECL [`(MAX (MAX ia ib) ic + 1) %% (MAX (MAX ia ib) ic + 2)`;
          `D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
          `((MAX (MAX ia ib) ic + 1) |-> (c:A))
           (((MAX (MAX ia ib) ic + 2) |-> up) (v:num->A))`]
          BVALF_SPEC) THEN ASM_SIMP_TAC[];
        MP_TAC(ISPECL [`Eq (MAX (MAX ia ib) ic + 1) ia`;
          `D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
          `((MAX (MAX ia ib) ic + 1) |-> (c:A))
           (((MAX (MAX ia ib) ic + 2) |-> up) (v:num->A))`]
          BVALF_SPEC) THEN ASM_SIMP_TAC[];
        MP_TAC(ISPECL [`Eq (MAX (MAX ia ib) ic + 1) ib`;
          `D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
          `((MAX (MAX ia ib) ic + 1) |-> (c:A))
           (((MAX (MAX ia ib) ic + 2) |-> up) (v:num->A))`]
          BVALF_SPEC) THEN ASM_SIMP_TAC[];
        (* ebv_in c up [[mp%%jup]] *)
        MP_TAC(ISPECL [`MAX (MAX ia ib) ic + 1`;`MAX (MAX ia ib) ic + 2`;
          `D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
          `((MAX (MAX ia ib) ic + 1) |-> (c:A))
           (((MAX (MAX ia ib) ic + 2) |-> up) (v:num->A))`]
          BVALF_MEM) THEN ASM_SIMP_TAC[];
        (* ebv_eq c (v ia) [[Eq mp ia]] *)
        MP_TAC(ISPECL [`MAX (MAX ia ib) ic + 1`;`ia:num`;
          `D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
          `((MAX (MAX ia ib) ic + 1) |-> (c:A))
           (((MAX (MAX ia ib) ic + 2) |-> up) (v:num->A))`]
          BVALF_EQ2) THEN ASM_SIMP_TAC[];
        (* ebv_eq c (v ib) [[Eq mp ib]] *)
        MP_TAC(ISPECL [`MAX (MAX ia ib) ic + 1`;`ib:num`;
          `D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
          `((MAX (MAX ia ib) ic + 1) |-> (c:A))
           (((MAX (MAX ia ib) ic + 2) |-> up) (v:num->A))`]
          BVALF_EQ2) THEN ASM_SIMP_TAC[];
        (* ejoin [[Eq mp ia]] [[Eq mp ib]] [[Eq||Eq]] *)
        MP_TAC(ISPECL
               [`Eq (MAX (MAX ia ib) ic + 1) ia`;
                `Eq (MAX (MAX ia ib) ic + 1) ib`;
                `D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
          `((MAX (MAX ia ib) ic + 1) |-> (c:A))
           (((MAX (MAX ia ib) ic + 2) |-> up) (v:num->A))`]
          BVALF_OR) THEN ASM_SIMP_TAC[]];
      DISCH_THEN(ACCEPT_TAC o SYM)]; ALL_TAC] THEN
  (* conclude via BVALF_MEMEXT_LE at v', i:=ic, j:=jup, k:=mp *)
  MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
    `((MAX (MAX ia ib) ic + 2) |-> up) (v:num->A)`;`ic:num`;
    `MAX (MAX ia ib) ic + 2`;
    `MAX (MAX ia ib) ic + 1`;`ee:A`] BVALF_MEMEXT_LE) THEN
  ASM_REWRITE_TAC[]);;

(* ===================================================================== *)
(* F7.2 m5-cover LE ladder (part 3): the V^B-pairing congruence.          *)
(*   EBV_EQ_CONG_MEET_LE -> EBV_UPMEM_CONG_LE -> EBV_EQ_UPAIR_CONG:        *)
(*   emeet([[s=a]],[[p=b]]) <= ebv_eq({s,p},{a,b}) for V^B pairs.          *)
(*   Via BVALF_MEMEXT_LE + BVALF_ALL_GLB + EBALG_DISTRIB + EBV_EQ_CONG.    *)
(* ===================================================================== *)
(* ==== EBV_EQ_CONG_MEET_LE: m MEET [[c=s]] <= [[c=a]] when m <= [[s=a]].
   The per-component congruence step for the V^B-pairing congruence.
   Via EBV_EQ_CONG (ecs MEET e1 <= eca) + EMEET_GREATEST (mcs <= ecs,
   mcs <= e1). *)

let EBV_EQ_CONG_MEET_LE = prove
 (`!D (E:A->A->bool) B leq c s a e1 ecs eca m mcs.
      model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
      c IN D /\ s IN D /\ a IN D /\ e1 IN D /\ ecs IN D /\
        eca IN D /\ m IN D /\
      bname D E B c /\ bname D E B s /\ bname D E B a /\
      E m B /\ ebv_eq D E B leq s a e1 /\ erel D E leq m e1 /\
      ebv_eq D E B leq c s ecs /\ ebv_eq D E B leq c a eca /\
      emeet D E B leq m ecs mcs
      ==> erel D E leq mcs eca`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `ebalg D (E:A->A->bool) B leq /\ eporder D E B leq`
    STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[ECBA_IMP_BALG; EBALG_IMP_PORDER]; ALL_TAC] THEN
  SUBGOAL_THEN
    `(mcs:A) IN D /\ (E:A->A->bool) e1 B /\ E (ecs:A) B /\ E (eca:A) B /\
     E (mcs:A) B`
    STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[EBV_EQ_IN_B; EMEET_IN]; ALL_TAC] THEN
  (* mcse = emeet(ecs, e1) *)
  SUBGOAL_THEN `?mcse:A. emeet D (E:A->A->bool) B leq ecs e1 mcse`
    (X_CHOOSE_TAC `mcse:A`) THENL
   [MATCH_MP_TAC EBALG_MEET THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(mcse:A) IN D /\ (E:A->A->bool) (mcse:A) B`
    STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[EMEET_IN]; ALL_TAC] THEN
  (* mcse <= eca via EBV_EQ_CONG (u:=c, v:=s, w:=a) *)
  SUBGOAL_THEN `erel D (E:A->A->bool) leq mcse eca` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`c:A`;`s:A`;`a:A`;
                  `ecs:A`;`e1:A`;`eca:A`;`mcse:A`] EBV_EQ_CONG) THEN
     ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* mcs <= ecs and mcs <= m *)
  MP_TAC(ISPECL
         [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`m:A`;`ecs:A`;`mcs:A`]
         EMEET_LE) THEN ASM_REWRITE_TAC[] THEN STRIP_TAC THEN
  (* mcs <= e1 (trans through m) *)
  SUBGOAL_THEN `erel D (E:A->A->bool) leq mcs e1` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`mcs:A`;
                  `m:A`;`e1:A`]
                 EPORDER_TRANS) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* mcs <= mcse (greatest lower bound of ecs, e1) *)
  SUBGOAL_THEN `erel D (E:A->A->bool) leq mcs mcse` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`ecs:A`;`e1:A`;
                  `mcse:A`;`mcs:A`] EMEET_GREATEST) THEN ASM_REWRITE_TAC[];
         ALL_TAC] THEN
  (* mcs <= mcse <= eca *)
  MATCH_MP_TAC(ISPECL
               [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`mcs:A`;
                `mcse:A`;`eca:A`]
               EPORDER_TRANS) THEN ASM_REWRITE_TAC[]);;

(* ==== EBV_UPMEM_CONG_LE: m MEET [[c IN {s,p}]] <= [[c IN {a,b}]], given
   m <= [[s=a]] and m <= [[p=b]], where {s,p}=sp and {a,b}=ab are V^B pairs.
   EBV_IN_UPAIR turns [[c in sp]] into ejoin([[c=s]],[[c=p]]); EBALG_DISTRIB
   pushes m inside; EBV_EQ_CONG_MEET_LE bounds each disjunct; EJOIN bounds. *)

let EBV_UPMEM_CONG_LE = prove
 (`!D (E:A->A->bool) B leq s p a b sp ab top c m e1 e2 J1 J2 mm.
      model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
      s IN D /\ p IN D /\ a IN D /\ b IN D /\ sp IN D /\ ab IN D /\ c IN D /\
      e1 IN D /\ e2 IN D /\ m IN D /\ J1 IN D /\ J2 IN D /\
      bname D E B s /\ bname D E B p /\ bname D E B a /\ bname D E B b /\
      bname D E B sp /\ bname D E B ab /\ bname D E B c /\
      top IN D /\ etop D E B leq top /\
      eapply D E sp s top /\ eapply D E sp p top /\
      (!t q. t IN D /\ q IN D /\ eapply D E sp t q ==> t = s \/ t = p) /\
      eapply D E ab a top /\ eapply D E ab b top /\
      (!t q. t IN D /\ q IN D /\ eapply D E ab t q ==> t = a \/ t = b) /\
      E m B /\ ebv_eq D E B leq s a e1 /\ ebv_eq D E B leq p b e2 /\
      erel D E leq m e1 /\ erel D E leq m e2 /\
      ebv_in D E B leq c sp J1 /\ ebv_in D E B leq c ab J2 /\
      emeet D E B leq m J1 mm
      ==> erel D E leq mm J2`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `ebalg D (E:A->A->bool) B leq /\ eporder D E B leq`
    STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[ECBA_IMP_BALG; EBALG_IMP_PORDER]; ALL_TAC] THEN
  (* the four equality values [[c=s]],[[c=p]],[[c=a]],[[c=b]] *)
  SUBGOAL_THEN
    `?ecs:A. ecs IN D /\ (E:A->A->bool) ecs B /\ ebv_eq D E B leq c s ecs`
    (X_CHOOSE_THEN `ecs:A` STRIP_ASSUME_TAC) THENL
   [MATCH_MP_TAC EBV_EQ_VAL_EXISTS THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN
    `?ecp:A. ecp IN D /\ (E:A->A->bool) ecp B /\ ebv_eq D E B leq c p ecp`
    (X_CHOOSE_THEN `ecp:A` STRIP_ASSUME_TAC) THENL
   [MATCH_MP_TAC EBV_EQ_VAL_EXISTS THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN
    `?eca:A. eca IN D /\ (E:A->A->bool) eca B /\ ebv_eq D E B leq c a eca`
    (X_CHOOSE_THEN `eca:A` STRIP_ASSUME_TAC) THENL
   [MATCH_MP_TAC EBV_EQ_VAL_EXISTS THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN
    `?ecb:A. ecb IN D /\ (E:A->A->bool) ecb B /\ ebv_eq D E B leq c b ecb`
    (X_CHOOSE_THEN `ecb:A` STRIP_ASSUME_TAC) THENL
   [MATCH_MP_TAC EBV_EQ_VAL_EXISTS THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* the joins jsp=[[c=s]]v[[c=p]], jab=[[c=a]]v[[c=b]] *)
  SUBGOAL_THEN `?jsp:A. ejoin D (E:A->A->bool) B leq ecs ecp jsp`
    (X_CHOOSE_TAC `jsp:A`) THENL
   [MATCH_MP_TAC EBALG_JOIN THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `?jab:A. ejoin D (E:A->A->bool) B leq eca ecb jab`
    (X_CHOOSE_TAC `jab:A`) THENL
   [MATCH_MP_TAC EBALG_JOIN THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN
    `(jsp:A) IN D /\ (E:A->A->bool) jsp B /\ (jab:A) IN D /\ E (jab:A) B`
    STRIP_ASSUME_TAC THENL [ASM_MESON_TAC[EJOIN_IN]; ALL_TAC] THEN
  (* J1 = jsp, J2 = jab via EBV_IN_UPAIR *)
  SUBGOAL_THEN `(J1:A) = jsp` SUBST_ALL_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`s:A`;`p:A`;`sp:A`;
                  `top:A`;`c:A`;`J1:A`;`ecs:A`;`ecp:A`;`jsp:A`]
                   EBV_IN_UPAIR) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(J2:A) = jab` SUBST_ALL_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`a:A`;`b:A`;`ab:A`;
                  `top:A`;`c:A`;`J2:A`;`eca:A`;`ecb:A`;`jab:A`]
                   EBV_IN_UPAIR) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* mcs = m MEET [[c=s]], mcp = m MEET [[c=p]] *)
  SUBGOAL_THEN `?mcs:A. emeet D (E:A->A->bool) B leq m ecs mcs`
    (X_CHOOSE_TAC `mcs:A`) THENL
   [MATCH_MP_TAC EBALG_MEET THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `?mcp:A. emeet D (E:A->A->bool) B leq m ecp mcp`
    (X_CHOOSE_TAC `mcp:A`) THENL
   [MATCH_MP_TAC EBALG_MEET THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN
    `(mcs:A) IN D /\ (E:A->A->bool) mcs B /\ (mcp:A) IN D /\ E (mcp:A) B`
    STRIP_ASSUME_TAC THENL [ASM_MESON_TAC[EMEET_IN]; ALL_TAC] THEN
  (* jmm = mcs v mcp ; mm = jmm by distributivity *)
  SUBGOAL_THEN `?jmm:A. ejoin D (E:A->A->bool) B leq mcs mcp jmm`
    (X_CHOOSE_TAC `jmm:A`) THENL
   [MATCH_MP_TAC EBALG_JOIN THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(mm:A) = jmm` SUBST_ALL_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`m:A`;
                  `ecs:A`;`ecp:A`;
                  `jsp:A`;`mm:A`;`mcs:A`;`mcp:A`;`jmm:A`] EBALG_DISTRIB) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* mcs <= eca, mcp <= ecb via EBV_EQ_CONG_MEET_LE *)
  SUBGOAL_THEN `erel D (E:A->A->bool) leq mcs eca` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`c:A`;`s:A`;`a:A`;
                  `e1:A`;`ecs:A`;`eca:A`;`m:A`;`mcs:A`]
                   EBV_EQ_CONG_MEET_LE) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq mcp ecb` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`c:A`;`p:A`;`b:A`;
                  `e2:A`;`ecp:A`;`ecb:A`;`m:A`;`mcp:A`]
                   EBV_EQ_CONG_MEET_LE) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* eca <= jab, ecb <= jab *)
  MP_TAC(ISPECL
         [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`eca:A`;`ecb:A`;`jab:A`]
         EJOIN_GE) THEN ASM_REWRITE_TAC[] THEN STRIP_TAC THEN
  (* mcs <= jab, mcp <= jab *)
  SUBGOAL_THEN `erel D (E:A->A->bool) leq mcs jab /\ erel D E leq mcp jab`
    STRIP_ASSUME_TAC THENL
   [CONJ_TAC THENL
     [MATCH_MP_TAC(ISPECL
                   [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`mcs:A`;
                    `eca:A`;`jab:A`]
                   EPORDER_TRANS) THEN ASM_REWRITE_TAC[];
      MATCH_MP_TAC(ISPECL
                   [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`mcp:A`;
                    `ecb:A`;`jab:A`]
                   EPORDER_TRANS) THEN ASM_REWRITE_TAC[]]; ALL_TAC] THEN
  (* jmm = mcs v mcp <= jab *)
  MATCH_MP_TAC(ISPECL
               [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`mcs:A`;`mcp:A`;
                `jmm:A`;`jab:A`] EJOIN_LEAST) THEN ASM_REWRITE_TAC[]);;

(* ==== EBV_EQ_UPAIR_CONG: the V^B-pairing congruence.
   emeet([[s=a]],[[p=b]]) <= ebv_eq({s,p}, {a,b})  for V^B pairs sp={s,p},
   ab={a,b}.  Via BVALF_MEMEXT_LE (slots 0:=sp,1:=ab,binder 2) reduced by
   BVALF_ALL_GLB to per-c:  m <= ([[c in sp]] <-> [[c in ab]]); each iff
   direction by EBV_UPMEM_CONG_LE + EBIMP_LE_IMP residuation. *)

let EBV_EQ_UPAIR_CONG = prove
 (`!D (E:A->A->bool) B leq s p a b sp ab top e1 e2 m e3.
      model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
      s IN D /\ p IN D /\ a IN D /\ b IN D /\ sp IN D /\ ab IN D /\
      e1 IN D /\ e2 IN D /\ e3 IN D /\
      bname D E B s /\ bname D E B p /\ bname D E B a /\ bname D E B b /\
      bname D E B sp /\ bname D E B ab /\
      top IN D /\ etop D E B leq top /\
      eapply D E sp s top /\ eapply D E sp p top /\
      (!t q. t IN D /\ q IN D /\ eapply D E sp t q ==> t = s \/ t = p) /\
      eapply D E ab a top /\ eapply D E ab b top /\
      (!t q. t IN D /\ q IN D /\ eapply D E ab t q ==> t = a \/ t = b) /\
      ebv_eq D E B leq s a e1 /\ ebv_eq D E B leq p b e2 /\
      emeet D E B leq e1 e2 m /\ ebv_eq D E B leq sp ab e3
      ==> erel D E leq m e3`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `ebalg D (E:A->A->bool) B leq /\ eporder D E B leq`
    STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[ECBA_IMP_BALG; EBALG_IMP_PORDER]; ALL_TAC] THEN
  SUBGOAL_THEN
    `(m:A) IN D /\ (E:A->A->bool) e1 B /\ E (e2:A) B /\
     E (m:A) B /\ E (e3:A) B`
    STRIP_ASSUME_TAC THENL [ASM_MESON_TAC[EBV_EQ_IN_B; EMEET_IN]; ALL_TAC] THEN
  (* m <= e1, m <= e2 ; and the SYMs ebv_eq a s e1, ebv_eq b p e2 *)
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`e1:A`;`e2:A`;`m:A`]
         EMEET_LE) THEN
  ASM_REWRITE_TAC[] THEN STRIP_TAC THEN
  SUBGOAL_THEN
    `ebv_eq D (E:A->A->bool) B leq a s e1 /\ ebv_eq D E B leq b p e2`
    STRIP_ASSUME_TAC THENL
   [CONJ_TAC THEN MATCH_MP_TAC EBV_EQ_SYM THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* base valuation v0 = (0|->sp)((1|->ab)(\n. s)) *)
  ABBREV_TAC `v0 = (0 |-> sp) ((1 |-> ab) (\n:num. s:A))` THEN
  SUBGOAL_THEN `valuation D (v0:num->A) /\ (!k. bname D E B ((v0:num->A) k))`
    STRIP_ASSUME_TAC THENL
   [EXPAND_TAC "v0" THEN CONJ_TAC THENL
     [REWRITE_TAC[valuation] THEN GEN_TAC THEN REWRITE_TAC[VALMOD] THEN
      REPEAT(COND_CASES_TAC THEN ASM_REWRITE_TAC[]) THEN ASM_REWRITE_TAC[];
      GEN_TAC THEN REWRITE_TAC[VALMOD] THEN
      REPEAT(COND_CASES_TAC THEN ASM_REWRITE_TAC[]) THEN ASM_REWRITE_TAC[]];
    ALL_TAC] THEN
  SUBGOAL_THEN `(v0:num->A) 0 = sp /\ (v0:num->A) 1 = ab`
    STRIP_ASSUME_TAC THENL
   [EXPAND_TAC "v0" THEN REWRITE_TAC[VALMOD] THEN REWRITE_TAC[ARITH_EQ];
    ALL_TAC] THEN
  (* MEMEXT_LE : [[!! 2 ((2%%0)<->(2%%1))]]_v0 <= e3 *)
  SUBGOAL_THEN
    `erel D (E:A->A->bool) leq
     (bvalf D E B leq v0 (!! 2 ((2 %% 0) <-> (2 %% 1)))) e3`
    ASSUME_TAC THENL
   [MP_TAC(ISPECL
           [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`v0:num->A`;`0`;
            `1`;`2`;`e3:A`]
           BVALF_MEMEXT_LE) THEN ASM_REWRITE_TAC[ARITH_EQ]; ALL_TAC] THEN
  (* m <= [[!! 2 ..]]_v0 by BVALF_ALL_GLB *)
  SUBGOAL_THEN
    `erel D (E:A->A->bool) leq m
     (bvalf D E B leq v0 (!! 2 ((2 %% 0) <-> (2 %% 1))))`
    ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`2`;`(2 %% 0) <-> (2 %% 1)`;`D:A->bool`;`E:A->A->bool`;`B:A`;
                  `leq:A`;`v0:num->A`;`m:A`] BVALF_ALL_GLB) THEN
    ASM_REWRITE_TAC[] THEN X_GEN_TAC `c:A` THEN STRIP_TAC THEN
    (* vc = (2|->c)v0 *)
    SUBGOAL_THEN
      `valuation D ((2 |-> (c:A)) v0) /\
       (!k. bname D E B (((2 |-> (c:A)) v0) k))`
      STRIP_ASSUME_TAC THENL
     [CONJ_TAC THENL
       [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[];
        MATCH_MP_TAC BNAMEVAL_VALMOD THEN ASM_REWRITE_TAC[]]; ALL_TAC] THEN
    SUBGOAL_THEN
      `((2 |-> (c:A)) v0) 0 = sp /\ ((2 |-> (c:A)) v0) 1 = ab /\
       ((2 |-> (c:A)) v0) 2 = c`
      STRIP_ASSUME_TAC THENL
     [ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER; ARITH_EQ]; ALL_TAC] THEN
    (* J1 = [[c in sp]], J2 = [[c in ab]] *)
    ABBREV_TAC
      `J1 = bvalf D (E:A->A->bool) B leq ((2 |-> (c:A)) v0) (2 %% 0)` THEN
      ABBREV_TAC
        `J2 = bvalf D (E:A->A->bool) B leq ((2 |-> (c:A)) v0) (2 %% 1)` THEN
        SUBGOAL_THEN
          `ebv_in D (E:A->A->bool) B leq c sp J1 /\ ebv_in D E B leq c ab J2`
          STRIP_ASSUME_TAC THENL
     [CONJ_TAC THENL
       [MAP_EVERY EXPAND_TAC ["J1"] THEN
        MP_TAC(ISPECL
               [`2`;`0`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
                `(2 |-> (c:A)) v0`]
               BVALF_MEM) THEN ASM_SIMP_TAC[];
        MAP_EVERY EXPAND_TAC ["J2"] THEN
        MP_TAC(ISPECL
               [`2`;`1`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
                `(2 |-> (c:A)) v0`]
               BVALF_MEM) THEN ASM_SIMP_TAC[]]; ALL_TAC] THEN
    (* J1 IN D, J2 IN D via BVALF_SPEC *)
    SUBGOAL_THEN `(J1:A) IN D /\ (J2:A) IN D` STRIP_ASSUME_TAC THENL
     [MAP_EVERY EXPAND_TAC ["J1";"J2"] THEN CONJ_TAC THENL
       [MP_TAC(ISPECL [`(2:num) %% 0`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
          `(2 |-> (c:A)) v0`] BVALF_SPEC) THEN ASM_SIMP_TAC[];
        MP_TAC(ISPECL [`(2:num) %% 1`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
          `(2 |-> (c:A)) v0`] BVALF_SPEC) THEN ASM_SIMP_TAC[]]; ALL_TAC] THEN
    SUBGOAL_THEN `(E:A->A->bool) J1 B /\ E (J2:A) B`
      STRIP_ASSUME_TAC THENL [ASM_MESON_TAC[EBV_IN_IN_B]; ALL_TAC] THEN
    (* imp1 = [[c in sp --> c in ab]], imp2 the reverse *)
    ABBREV_TAC
      `imp1 = bvalf D (E:A->A->bool) B leq ((2 |-> (c:A)) v0)
       ((2 %% 0) --> (2 %% 1))` THEN
    ABBREV_TAC
      `imp2 = bvalf D (E:A->A->bool) B leq ((2 |-> (c:A)) v0)
       ((2 %% 1) --> (2 %% 0))` THEN
    SUBGOAL_THEN
      `ebimp D (E:A->A->bool) B leq J1 J2 imp1 /\ ebimp D E B leq J2 J1 imp2`
      STRIP_ASSUME_TAC THENL
     [CONJ_TAC THENL
       [MAP_EVERY EXPAND_TAC ["imp1";"J1";"J2"] THEN
        MP_TAC(ISPECL
               [`2 %% 0`;`2 %% 1`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
                `(2 |-> (c:A)) v0`] BVALF_IMP) THEN ASM_SIMP_TAC[];
        MAP_EVERY EXPAND_TAC ["imp2";"J1";"J2"] THEN
        MP_TAC(ISPECL
               [`2 %% 1`;`2 %% 0`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
                `(2 |-> (c:A)) v0`] BVALF_IMP) THEN ASM_SIMP_TAC[]];
       ALL_TAC] THEN
    SUBGOAL_THEN
      `(imp1:A) IN D /\ (E:A->A->bool) imp1 B /\ (imp2:A) IN D /\ E (imp2:A) B`
      STRIP_ASSUME_TAC THENL [ASM_MESON_TAC[EBIMP_IN]; ALL_TAC] THEN
    (* m <= imp1 : via emeet(m,J1) <= J2 (EBV_UPMEM_CONG_LE) + EBIMP_LE_IMP *)
    SUBGOAL_THEN `?mm1:A. emeet D (E:A->A->bool) B leq m J1 mm1`
      (X_CHOOSE_TAC `mm1:A`) THENL
      [MATCH_MP_TAC EBALG_MEET THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN `erel D (E:A->A->bool) leq mm1 J2` ASSUME_TAC THENL
     [MATCH_MP_TAC(ISPECL
                   [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`s:A`;`p:A`;
                    `a:A`;`b:A`;
                    `sp:A`;`ab:A`;`top:A`;`c:A`;`m:A`;`e1:A`;`e2:A`;`J1:A`;
                    `J2:A`;`mm1:A`]
        EBV_UPMEM_CONG_LE) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN `erel D (E:A->A->bool) leq m imp1` ASSUME_TAC THENL
     [MATCH_MP_TAC(ISPECL
                   [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`m:A`;
                    `J1:A`;`J2:A`;
                    `imp1:A`;`mm1:A`] EBIMP_LE_IMP) THEN ASM_REWRITE_TAC[];
       ALL_TAC] THEN
    (* m <= imp2 : via emeet(m,J2) <= J1 (EBV_UPMEM_CONG_LE swapped) + *)
    (* EBIMP_LE_IMP *)
    SUBGOAL_THEN `?mm2:A. emeet D (E:A->A->bool) B leq m J2 mm2`
      (X_CHOOSE_TAC `mm2:A`) THENL
      [MATCH_MP_TAC EBALG_MEET THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN `erel D (E:A->A->bool) leq mm2 J1` ASSUME_TAC THENL
     [MATCH_MP_TAC(ISPECL
                   [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`a:A`;`b:A`;
                    `s:A`;`p:A`;
                    `ab:A`;`sp:A`;`top:A`;`c:A`;`m:A`;`e1:A`;`e2:A`;`J2:A`;
                    `J1:A`;`mm2:A`]
        EBV_UPMEM_CONG_LE) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN `erel D (E:A->A->bool) leq m imp2` ASSUME_TAC THENL
     [MATCH_MP_TAC(ISPECL
                   [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`m:A`;
                    `J2:A`;`J1:A`;
                    `imp2:A`;`mm2:A`] EBIMP_LE_IMP) THEN ASM_REWRITE_TAC[];
       ALL_TAC] THEN
    (* m <= iff = emeet(imp1,imp2) *)
    REWRITE_TAC[Iff_DEF] THEN
    MP_TAC(ISPECL [`(2 %% 0) --> (2 %% 1)`;`(2 %% 1) --> (2 %% 0)`;`D:A->bool`;
      `E:A->A->bool`;`B:A`;`leq:A`;`(2 |-> (c:A)) v0`] BVALF_AND_MEET) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    ASM_REWRITE_TAC[] THEN DISCH_TAC THEN
    MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`imp1:A`;`imp2:A`;
                  `bvalf D (E:A->A->bool) B leq ((2 |-> (c:A)) v0)
         (((2 %% 0) --> (2 %% 1)) && ((2 %% 1) --> (2 %% 0)))`;`m:A`]
                   EMEET_GREATEST) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* transitivity m <= [[!! 2..]]_v0 <= e3 *)
  SUBGOAL_THEN
    `(bvalf D (E:A->A->bool) B leq v0 (!! 2 ((2 %% 0) <-> (2 %% 1)))) IN D /\
     (E:A->A->bool) (bvalf D E B leq v0 (!! 2 ((2 %% 0) <-> (2 %% 1)))) B`
    STRIP_ASSUME_TAC THENL
   [CONJ_TAC THENL
     [MP_TAC(ISPECL
             [`!! 2 ((2 %% 0) <-> (2 %% 1))`;`D:A->bool`;`E:A->A->bool`;`B:A`;
              `leq:A`;`v0:num->A`] BVALF_SPEC) THEN ASM_SIMP_TAC[];
      MP_TAC(ISPECL
             [`!! 2 ((2 %% 0) <-> (2 %% 1))`;`D:A->bool`;`E:A->A->bool`;`B:A`;
              `leq:A`;`v0:num->A`] BVALF_IN_B) THEN ASM_SIMP_TAC[]];
     ALL_TAC] THEN
  MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`m:A`;
    `bvalf D (E:A->A->bool) B leq v0 (!! 2 ((2 %% 0) <-> (2 %% 1)))`;`e3:A`]
       EPORDER_TRANS) THEN
  ASM_REWRITE_TAC[]);;

(* ===================================================================== *)
(* F7.2 m5-cover LE ladder (part 4): BVALF_OPAIRFORM_LE + BVALF_PMEM_LE.  *)
(*   [[opair_form 70 71 73]] <= ebv_eq(v73, V^B-Kuratowski); hence         *)
(*   [[pm]] <= ebv_in(ckp, f).  LE companions of BVALF_OPAIRFORM_TOP /     *)
(*   BVALF_PMEM_GE; the LE/extensionality half the m5-cover covering needs.*)
(* ===================================================================== *)
(* ==== BVALF_OPAIRFORM_LE: [[opair_form ia ib ic]]_v <= ebv_eq(v ic, ckp),
   where ckp = V^B-Kuratowski pair {sing, pr}, sing = {v ia},
   pr = {v ia, v ib}.
   LE companion of BVALF_OPAIRFORM_TOP.  Peel the two ??
     (BVALF_EX_LEAST), split
   the conjunction (BVALF_AND_MEET),
   bound the 3 pairs (BVALF_PAIRFORM_LE), then
   compose via EBV_EQ_UPAIR_CONG (pairing congruence) + EBV_EQ_CONG
     (transitivity). *)

let BVALF_OPAIRFORM_LE = prove
 (`!D (E:A->A->bool) B leq (v:num->A) ia ib ic sing pr ckp top ee.
      model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
      valuation D v /\ (!k. bname D E B (v k)) /\
      sing IN D /\ pr IN D /\ ckp IN D /\
      bname D E B sing /\ bname D E B pr /\ bname D E B ckp /\
      top IN D /\ etop D E B leq top /\
      eapply D E sing (v ia) top /\
      (!t q. t IN D /\ q IN D /\ eapply D E sing t q ==> t = v ia \/
       t = v ia) /\
      eapply D E pr (v ia) top /\ eapply D E pr (v ib) top /\
      (!t q. t IN D /\ q IN D /\ eapply D E pr t q ==> t = v ia \/ t = v ib) /\
      eapply D E ckp sing top /\ eapply D E ckp pr top /\
      (!t q. t IN D /\ q IN D /\ eapply D E ckp t q ==> t = sing \/ t = pr) /\
      ee IN D /\ ebv_eq D E B leq (v ic) ckp ee
      ==> erel D E leq (bvalf D E B leq v (opair_form ia ib ic)) ee`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `ebalg D (E:A->A->bool) B leq /\ eporder D E B leq`
    STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[ECBA_IMP_BALG; EBALG_IMP_PORDER]; ALL_TAC] THEN
  SUBGOAL_THEN `!x. (v:num->A) x IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[valuation]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) ee B` ASSUME_TAC THENL
   [ASM_MESON_TAC[EBV_EQ_IN_B]; ALL_TAC] THEN
  REWRITE_TAC[opair_form] THEN
  SUBGOAL_THEN
    `~(MAX (MAX ia ib) ic + 1 = ia) /\ ~(MAX (MAX ia ib) ic + 1 = ib) /\
     ~(MAX (MAX ia ib) ic + 1 = ic) /\ ~(MAX (MAX ia ib) ic + 2 = ia) /\
     ~(MAX (MAX ia ib) ic + 2 = ib) /\ ~(MAX (MAX ia ib) ic + 2 = ic) /\
     ~(MAX (MAX ia ib) ic + 1 = MAX (MAX ia ib) ic + 2)`
    STRIP_ASSUME_TAC THENL [ARITH_TAC; ALL_TAC] THEN
  (* outer ?? (M+1) *)
  MATCH_MP_TAC(ISPECL [`MAX (MAX ia ib) ic + 1`;
    `?? (MAX (MAX ia ib) ic + 2)
        (pair_form ia ia (MAX (MAX ia ib) ic + 1) &&
         pair_form ia ib (MAX (MAX ia ib) ic + 2) &&
         pair_form (MAX (MAX ia ib) ic + 1) (MAX (MAX ia ib) ic + 2) ic)`;
    `D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`v:num->A`;`ee:A`]
       BVALF_EX_LEAST) THEN
  ASM_REWRITE_TAC[] THEN X_GEN_TAC `s:A` THEN STRIP_TAC THEN
  SUBGOAL_THEN
    `valuation D (((MAX (MAX ia ib) ic + 1) |-> s) (v:num->A)) /\
     (!k. bname D E B ((((MAX (MAX ia ib) ic + 1) |-> s) (v:num->A)) k))`
    STRIP_ASSUME_TAC THENL
   [CONJ_TAC THENL
     [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[];
      MATCH_MP_TAC BNAMEVAL_VALMOD THEN ASM_REWRITE_TAC[]]; ALL_TAC] THEN
  (* inner ?? (M+2) *)
  MATCH_MP_TAC(ISPECL [`MAX (MAX ia ib) ic + 2`;
    `pair_form ia ia (MAX (MAX ia ib) ic + 1) &&
     pair_form ia ib (MAX (MAX ia ib) ic + 2) &&
     pair_form (MAX (MAX ia ib) ic + 1) (MAX (MAX ia ib) ic + 2) ic`;
    `D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
    `((MAX (MAX ia ib) ic + 1) |-> s) (v:num->A)`;`ee:A`] BVALF_EX_LEAST) THEN
  ASM_REWRITE_TAC[] THEN X_GEN_TAC `p:A` THEN STRIP_TAC THEN
  (* vsp = (M+2|->p)(M+1|->s)v *)
  SUBGOAL_THEN
    `valuation D (((MAX (MAX ia ib) ic + 2) |-> p)
          (((MAX (MAX ia ib) ic + 1) |-> s) (v:num->A))) /\
     (!k. bname D E B ((((MAX (MAX ia ib) ic + 2) |-> p)
          (((MAX (MAX ia ib) ic + 1) |-> s) (v:num->A))) k))`
    STRIP_ASSUME_TAC THENL
   [CONJ_TAC THENL
     [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[];
      MATCH_MP_TAC BNAMEVAL_VALMOD THEN ASM_REWRITE_TAC[]]; ALL_TAC] THEN
  ABBREV_TAC `vsp = ((MAX (MAX ia ib) ic + 2) |-> p)
          (((MAX (MAX ia ib) ic + 1) |-> s) (v:num->A))` THEN
  SUBGOAL_THEN
    `(vsp:num->A) ia = v ia /\ (vsp:num->A) ib = v ib /\
     (vsp:num->A) ic = v ic /\
     (vsp:num->A) (MAX (MAX ia ib) ic + 1) = s /\
       (vsp:num->A) (MAX (MAX ia ib) ic + 2) = p`
    STRIP_ASSUME_TAC THENL
   [EXPAND_TAC "vsp" THEN ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER; ARITH_EQ];
    ALL_TAC] THEN
  (* up_sp = V^B pair of (s,p) *)
  SUBGOAL_THEN
    `?upsp top2. upsp IN D /\ bname D (E:A->A->bool) B upsp /\
                 top2 IN D /\ etop D E B leq top2 /\
                 eapply D E upsp s top2 /\ eapply D E upsp p top2 /\
                 (!t q. t IN D /\ q IN D /\ eapply D E upsp t q ==>
                  t = s \/ t = p)`
    STRIP_ASSUME_TAC THENL
   [MATCH_MP_TAC EUPAIRNAME_EXISTS THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `top2:A = top` SUBST_ALL_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`top2:A`;`top:A`]
                 ETOP_UNIQUE) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* the three equality values ea=[[s=sing]], eb=[[p=pr]], ec=[[v ic=upsp]] *)
  SUBGOAL_THEN
    `?ea:A. ea IN D /\ (E:A->A->bool) ea B /\ ebv_eq D E B leq s sing ea`
    (X_CHOOSE_THEN `ea:A` STRIP_ASSUME_TAC) THENL
   [MATCH_MP_TAC EBV_EQ_VAL_EXISTS THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN
    `?eb:A. eb IN D /\ (E:A->A->bool) eb B /\ ebv_eq D E B leq p pr eb`
    (X_CHOOSE_THEN `eb:A` STRIP_ASSUME_TAC) THENL
   [MATCH_MP_TAC EBV_EQ_VAL_EXISTS THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN
    `?ec:A. ec IN D /\ (E:A->A->bool) ec B /\
     ebv_eq D E B leq ((v:num->A) ic) upsp ec`
    (X_CHOOSE_THEN `ec:A` STRIP_ASSUME_TAC) THENL
   [MATCH_MP_TAC EBV_EQ_VAL_EXISTS THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* V1 <= ea, V2 <= eb, V3 <= ec *)
  ABBREV_TAC `V1 = bvalf D (E:A->A->bool) B leq (vsp:num->A)
                     (pair_form ia ia (MAX (MAX ia ib) ic + 1))` THEN
  ABBREV_TAC `V2 = bvalf D (E:A->A->bool) B leq (vsp:num->A)
                     (pair_form ia ib (MAX (MAX ia ib) ic + 2))` THEN
  ABBREV_TAC `V3 = bvalf D (E:A->A->bool) B leq (vsp:num->A)
                     (pair_form (MAX (MAX ia ib) ic + 1)
                      (MAX (MAX ia ib) ic + 2) ic)` THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq V1 ea` ASSUME_TAC THENL
   [EXPAND_TAC "V1" THEN
    MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`vsp:num->A`;
      `ia:num`;`ia:num`;`MAX (MAX ia ib) ic + 1`;`sing:A`;`top:A`;`ea:A`]
                        BVALF_PAIRFORM_LE) THEN
    ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq V2 eb` ASSUME_TAC THENL
   [EXPAND_TAC "V2" THEN
    MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`vsp:num->A`;
      `ia:num`;`ib:num`;`MAX (MAX ia ib) ic + 2`;`pr:A`;`top:A`;`eb:A`]
                          BVALF_PAIRFORM_LE) THEN
    ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq V3 ec` ASSUME_TAC THENL
   [EXPAND_TAC "V3" THEN
    MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`vsp:num->A`;
      `MAX (MAX ia ib) ic + 1`;`MAX (MAX ia ib) ic + 2`;`ic:num`;`upsp:A`;
      `top:A`;`ec:A`]
      BVALF_PAIRFORM_LE) THEN ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[];
    ALL_TAC] THEN
  (* W = [[conj]]_vsp = meet(V1, meet(V2,V3)) *)
  SUBGOAL_THEN
    `(V1:A) IN D /\ (E:A->A->bool) V1 B /\ (V2:A) IN D /\ E (V2:A) B /\
     (V3:A) IN D /\ E (V3:A) B`
    STRIP_ASSUME_TAC THENL
   [MAP_EVERY EXPAND_TAC ["V1";"V2";"V3"] THEN
    ASM_MESON_TAC[BVALF_SPEC; BVALF_IN_B]; ALL_TAC] THEN
  ABBREV_TAC `WBC = bvalf D (E:A->A->bool) B leq (vsp:num->A)
       (pair_form ia ib (MAX (MAX ia ib) ic + 2) &&
        pair_form (MAX (MAX ia ib) ic + 1) (MAX (MAX ia ib) ic + 2) ic)` THEN
  ABBREV_TAC `W = bvalf D (E:A->A->bool) B leq (vsp:num->A)
       (pair_form ia ia (MAX (MAX ia ib) ic + 1) &&
        pair_form ia ib (MAX (MAX ia ib) ic + 2) &&
        pair_form (MAX (MAX ia ib) ic + 1) (MAX (MAX ia ib) ic + 2) ic)` THEN
  SUBGOAL_THEN
    `(W:A) IN D /\ (E:A->A->bool) W B /\ (WBC:A) IN D /\ E (WBC:A) B`
    STRIP_ASSUME_TAC THENL
   [MAP_EVERY EXPAND_TAC ["W";"WBC"] THEN
    ASM_MESON_TAC[BVALF_SPEC; BVALF_IN_B]; ALL_TAC] THEN
  (* W <= V1 (AND_LE_L), W <= WBC (AND_LE_R), WBC <= V2/V3 (AND_LE_L/R) *)
  SUBGOAL_THEN `erel D (E:A->A->bool) leq W V1` ASSUME_TAC THENL
   [MAP_EVERY EXPAND_TAC ["W";"V1"] THEN
    MATCH_MP_TAC(ISPECL [`pair_form ia ia (MAX (MAX ia ib) ic + 1)`;
      `pair_form ia ib (MAX (MAX ia ib) ic + 2) &&
       pair_form (MAX (MAX ia ib) ic + 1) (MAX (MAX ia ib) ic + 2) ic`;
      `D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`vsp:num->A`]
          BVALF_AND_LE_L) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq W WBC` ASSUME_TAC THENL
   [MAP_EVERY EXPAND_TAC ["W";"WBC"] THEN
    MATCH_MP_TAC(ISPECL [`pair_form ia ia (MAX (MAX ia ib) ic + 1)`;
      `pair_form ia ib (MAX (MAX ia ib) ic + 2) &&
       pair_form (MAX (MAX ia ib) ic + 1) (MAX (MAX ia ib) ic + 2) ic`;
      `D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`vsp:num->A`]
            BVALF_AND_LE_R) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq WBC V2 /\ erel D E leq WBC V3`
    STRIP_ASSUME_TAC THENL
   [CONJ_TAC THENL
     [MAP_EVERY EXPAND_TAC ["WBC";"V2"] THEN
      MATCH_MP_TAC(ISPECL [`pair_form ia ib (MAX (MAX ia ib) ic + 2)`;
        `pair_form (MAX (MAX ia ib) ic + 1) (MAX (MAX ia ib) ic + 2) ic`;
        `D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`vsp:num->A`]
        BVALF_AND_LE_L) THEN
      ASM_REWRITE_TAC[];
      MAP_EVERY EXPAND_TAC ["WBC";"V3"] THEN
      MATCH_MP_TAC(ISPECL [`pair_form ia ib (MAX (MAX ia ib) ic + 2)`;
        `pair_form (MAX (MAX ia ib) ic + 1) (MAX (MAX ia ib) ic + 2) ic`;
        `D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`vsp:num->A`]
        BVALF_AND_LE_R) THEN
      ASM_REWRITE_TAC[]]; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq W V2 /\ erel D E leq W V3`
    STRIP_ASSUME_TAC THENL
   [CONJ_TAC THENL
     [MATCH_MP_TAC(ISPECL
                   [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`W:A`;
                    `WBC:A`;`V2:A`]
                   EPORDER_TRANS) THEN ASM_REWRITE_TAC[];
      MATCH_MP_TAC(ISPECL
                   [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`W:A`;
                    `WBC:A`;`V3:A`]
                   EPORDER_TRANS) THEN ASM_REWRITE_TAC[]]; ALL_TAC] THEN
  (* W <= ea, W <= eb, W <= ec *)
  SUBGOAL_THEN
    `erel D (E:A->A->bool) leq W ea /\ erel D E leq W eb /\ erel D E leq W ec`
    STRIP_ASSUME_TAC THENL
   [REPEAT CONJ_TAC THENL
     [MATCH_MP_TAC(ISPECL
                   [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`W:A`;
                    `V1:A`;`ea:A`]
                   EPORDER_TRANS) THEN ASM_REWRITE_TAC[];
      MATCH_MP_TAC(ISPECL
                   [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`W:A`;
                    `V2:A`;`eb:A`]
                   EPORDER_TRANS) THEN ASM_REWRITE_TAC[];
      MATCH_MP_TAC(ISPECL
                   [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`W:A`;
                    `V3:A`;`ec:A`]
                   EPORDER_TRANS) THEN ASM_REWRITE_TAC[]]; ALL_TAC] THEN
  (* meb = emeet(ea,eb); W <= meb *)
  SUBGOAL_THEN `?meb:A. emeet D (E:A->A->bool) B leq ea eb meb`
    (X_CHOOSE_TAC `meb:A`) THENL
   [MATCH_MP_TAC EBALG_MEET THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(meb:A) IN D /\ (E:A->A->bool) meb B` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[EMEET_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq W meb` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`ea:A`;`eb:A`;
                  `meb:A`;`W:A`]
                 EMEET_GREATEST) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* euc = ebv_eq(upsp,ckp); meb <= euc by pairing congruence *)
  SUBGOAL_THEN
    `?euc:A. euc IN D /\ (E:A->A->bool) euc B /\ ebv_eq D E B leq upsp ckp euc`
    (X_CHOOSE_THEN `euc:A` STRIP_ASSUME_TAC) THENL
   [MATCH_MP_TAC EBV_EQ_VAL_EXISTS THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq meb euc` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`s:A`;`p:A`;
                  `sing:A`;`pr:A`;
                  `upsp:A`;`ckp:A`;`top:A`;`ea:A`;`eb:A`;`meb:A`;`euc:A`]
                   EBV_EQ_UPAIR_CONG) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq W euc` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`W:A`;
                  `meb:A`;`euc:A`]
                 EPORDER_TRANS) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* mce = emeet(ec,euc); W <= mce; mce <= ee by EBV_EQ_CONG (v ic, upsp, *)
  (* ckp) *)
  SUBGOAL_THEN `?mce:A. emeet D (E:A->A->bool) B leq ec euc mce`
    (X_CHOOSE_TAC `mce:A`) THENL
   [MATCH_MP_TAC EBALG_MEET THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(mce:A) IN D /\ (E:A->A->bool) mce B` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[EMEET_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq W mce` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`ec:A`;`euc:A`;
                  `mce:A`;`W:A`]
                 EMEET_GREATEST) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq mce ee` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
                  `(v:num->A) ic`;`upsp:A`;
                  `ckp:A`;`ec:A`;`euc:A`;`ee:A`;`mce:A`] EBV_EQ_CONG) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MATCH_MP_TAC(ISPECL
               [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`W:A`;`mce:A`;`ee:A`]
               EPORDER_TRANS) THEN ASM_REWRITE_TAC[]);;

(* ==== BVALF_PMEM_LE: [[pm]]_v0 <= ebv_in(pr, v0 72), pm = ?? 73 (opair_form
   70 71 73 && (73 %% 72)), pr = V^B-Kuratowski{s,p}, s={v0 70},
   p={v0 70,v0 71}.
   The LE companion of BVALF_PMEM_GE.  BVALF_EX_LEAST (over 73, w0:=mvpr):
   per w, [[opair 70 71 73]]_{73:=w} <= ebv_eq(w,pr) (BVALF_OPAIRFORM_LE), and
   [[73%%72]] = ebv_in(w, v0 72); the meet <= ebv_in(pr,
   v0 72) by EBV_IN_CONG_L. *)

let BVALF_PMEM_LE = prove
 (`!D (E:A->A->bool) B leq (v0:num->A) s p pr top mvpr.
      model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
      valuation D v0 /\ (!k. bname D E B (v0 k)) /\
      top IN D /\ etop D E B leq top /\
      s IN D /\ bname D E B s /\ p IN D /\ bname D E B p /\
      pr IN D /\ bname D E B pr /\
      eapply D E s (v0 70) top /\
      (!t q. t IN D /\ q IN D /\ eapply D E s t q ==> t = v0 70 \/
       t = v0 70) /\
      eapply D E p (v0 70) top /\ eapply D E p (v0 71) top /\
      (!t q. t IN D /\ q IN D /\ eapply D E p t q ==> t = v0 70 \/
       t = v0 71) /\
      eapply D E pr s top /\ eapply D E pr p top /\
      (!t q. t IN D /\ q IN D /\ eapply D E pr t q ==> t = s \/ t = p) /\
      mvpr IN D /\ ebv_in D E B leq pr (v0 72) mvpr
      ==> erel D E leq
        (bvalf D E B leq v0 (?? 73 (opair_form 70 71 73 && (73 %% 72)))) mvpr`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `ebalg D (E:A->A->bool) B leq /\ eporder D E B leq`
    STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[ECBA_IMP_BALG; EBALG_IMP_PORDER]; ALL_TAC] THEN
  SUBGOAL_THEN `!x. (v0:num->A) x IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[valuation]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) mvpr B` ASSUME_TAC THENL
   [ASM_MESON_TAC[EBV_IN_IN_B]; ALL_TAC] THEN
  MATCH_MP_TAC(ISPECL
               [`73`;`opair_form 70 71 73 && (73 %% 72)`;`D:A->bool`;
                `E:A->A->bool`;
                `B:A`;`leq:A`;`v0:num->A`;`mvpr:A`] BVALF_EX_LEAST) THEN
  ASM_REWRITE_TAC[] THEN X_GEN_TAC `w:A` THEN STRIP_TAC THEN
  SUBGOAL_THEN `valuation D ((73 |-> w) (v0:num->A)) /\
                (!k. bname D E B (((73 |-> w) (v0:num->A)) k))`
    STRIP_ASSUME_TAC THENL
   [CONJ_TAC THENL
     [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[];
      MATCH_MP_TAC BNAMEVAL_VALMOD THEN ASM_REWRITE_TAC[]]; ALL_TAC] THEN
  ABBREV_TAC `vw = (73 |-> w) (v0:num->A)` THEN
  SUBGOAL_THEN `(vw:num->A) 70 = v0 70 /\ (vw:num->A) 71 = v0 71 /\
                (vw:num->A) 72 = v0 72 /\ (vw:num->A) 73 = w`
    STRIP_ASSUME_TAC THENL
   [EXPAND_TAC "vw" THEN SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER; ARITH_EQ];
    ALL_TAC] THEN
  (* ewp = ebv_eq(w, pr) *)
  SUBGOAL_THEN
    `?ewp:A. ewp IN D /\ (E:A->A->bool) ewp B /\ ebv_eq D E B leq w pr ewp`
    (X_CHOOSE_THEN `ewp:A` STRIP_ASSUME_TAC) THENL
   [MATCH_MP_TAC EBV_EQ_VAL_EXISTS THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* Opv = [[opair 70 71 73]]_vw <= ewp *)
  ABBREV_TAC
    `Opv = bvalf D (E:A->A->bool) B leq (vw:num->A) (opair_form 70 71 73)` THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq Opv ewp` ASSUME_TAC THENL
   [EXPAND_TAC "Opv" THEN
    MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`vw:num->A`;
                  `70`;`71`;`73`;
                  `s:A`;`p:A`;`pr:A`;`top:A`;`ewp:A`] BVALF_OPAIRFORM_LE) THEN
    ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[]; ALL_TAC] THEN
  (* Memv = [[73%%72]]_vw = ebv_in(w, v0 72) *)
  ABBREV_TAC `Memv = bvalf D (E:A->A->bool) B leq (vw:num->A) (73 %% 72)` THEN
  SUBGOAL_THEN `ebv_in D (E:A->A->bool) B leq w (v0 72) Memv` ASSUME_TAC THENL
   [EXPAND_TAC "Memv" THEN
    MP_TAC(ISPECL
           [`73`;`72`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`vw:num->A`]
           BVALF_MEM) THEN
    ASM_SIMP_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN
    `(Opv:A) IN D /\ (E:A->A->bool) Opv B /\ (Memv:A) IN D /\ E (Memv:A) B`
    STRIP_ASSUME_TAC THENL
   [MAP_EVERY EXPAND_TAC ["Opv";"Memv"] THEN
    ASM_MESON_TAC[BVALF_SPEC; BVALF_IN_B]; ALL_TAC] THEN
  (* W' = [[opair && mem]]_vw = emeet(Opv, Memv) *)
  ABBREV_TAC `Wp = bvalf D (E:A->A->bool) B leq (vw:num->A)
                     (opair_form 70 71 73 && (73 %% 72))` THEN
  SUBGOAL_THEN `emeet D (E:A->A->bool) B leq Opv Memv Wp` ASSUME_TAC THENL
   [MAP_EVERY EXPAND_TAC ["Wp";"Opv";"Memv"] THEN
    MATCH_MP_TAC(ISPECL
                 [`opair_form 70 71 73`;`73 %% 72`;`D:A->bool`;
                  `E:A->A->bool`;`B:A`;
                  `leq:A`;`vw:num->A`] BVALF_AND_MEET) THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `(Wp:A) IN D /\ (E:A->A->bool) Wp B` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[EMEET_IN]; ALL_TAC] THEN
  (* Wp <= Opv, Wp <= Memv *)
  MP_TAC(ISPECL
         [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`Opv:A`;`Memv:A`;`Wp:A`]
         EMEET_LE) THEN
  ASM_REWRITE_TAC[] THEN STRIP_TAC THEN
  (* Wp <= ewp (trans through Opv) *)
  SUBGOAL_THEN `erel D (E:A->A->bool) leq Wp ewp` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`Wp:A`;
                  `Opv:A`;`ewp:A`]
                 EPORDER_TRANS) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* z23 = emeet(ewp, Memv); Wp <= z23 *)
  SUBGOAL_THEN `?z23:A. emeet D (E:A->A->bool) B leq ewp Memv z23`
    (X_CHOOSE_TAC `z23:A`) THENL
   [MATCH_MP_TAC EBALG_MEET THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(z23:A) IN D /\ (E:A->A->bool) z23 B` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[EMEET_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq Wp z23` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`ewp:A`;`Memv:A`;
                  `z23:A`;`Wp:A`]
                 EMEET_GREATEST) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* z23 <= mvpr by EBV_IN_CONG_L (u:=w, v:=pr, set:=v0 72) *)
  SUBGOAL_THEN `erel D (E:A->A->bool) leq z23 mvpr` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`w:A`;`pr:A`;
                  `(v0:num->A) 72`;
                  `ewp:A`;`Memv:A`;`mvpr:A`;`z23:A`] EBV_IN_CONG_L) THEN
         ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* Wp <= z23 <= mvpr *)
  MATCH_MP_TAC(ISPECL
               [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`Wp:A`;
                `z23:A`;`mvpr:A`]
               EPORDER_TRANS) THEN ASM_REWRITE_TAC[]);;

(* ===================================================================== *)
(* F7.2 m5-cover (part 1): the slot-substitution congruence for pm.       *)
(*   EBV_EQ_KUR_CONG (nested V^B-Kuratowski pairing congruence) +         *)
(*   EBV_PM_SUBST_LE ([[pm]]_v0 MEET [[ss=cn]] <= ebv_in(<cn,cb>-Kur, f)). *)
(* ===================================================================== *)
(* ==== EBV_EQ_KUR_CONG: nested V^B-Kuratowski pairing congruence.
   emeet([[a1=a2]],[[b1=b2]]) <= ebv_eq(<a1,b1>, <a2,b2>), where <x,y> is the
   Kuratowski pair {{x},{x,y}}: ckp1={sing1,pr1}, sing1={a1},
   pr1={a1,b1} (and 2).
   Three applications of EBV_EQ_UPAIR_CONG (singletons, the pairs,
   the Kuratowski). *)

let EBV_EQ_KUR_CONG = prove
 (`!D (E:A->A->bool) B leq a1 b1 a2 b2 sing1 pr1 ckp1 sing2 pr2 ckp2 top
      ea eb m e3.
      model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
      a1 IN D /\ b1 IN D /\ a2 IN D /\ b2 IN D /\
      sing1 IN D /\ pr1 IN D /\ ckp1 IN D /\ sing2 IN D /\ pr2 IN D /\
        ckp2 IN D /\
      ea IN D /\ eb IN D /\ e3 IN D /\
      bname D E B a1 /\ bname D E B b1 /\ bname D E B a2 /\ bname D E B b2 /\
      bname D E B sing1 /\ bname D E B pr1 /\ bname D E B ckp1 /\
      bname D E B sing2 /\ bname D E B pr2 /\ bname D E B ckp2 /\
      top IN D /\ etop D E B leq top /\
      eapply D E sing1 a1 top /\
      (!t q. t IN D /\ q IN D /\ eapply D E sing1 t q ==> t = a1 \/ t = a1) /\
      eapply D E pr1 a1 top /\ eapply D E pr1 b1 top /\
      (!t q. t IN D /\ q IN D /\ eapply D E pr1 t q ==> t = a1 \/ t = b1) /\
      eapply D E ckp1 sing1 top /\ eapply D E ckp1 pr1 top /\
      (!t q. t IN D /\ q IN D /\ eapply D E ckp1 t q ==>
       t = sing1 \/ t = pr1) /\
      eapply D E sing2 a2 top /\
      (!t q. t IN D /\ q IN D /\ eapply D E sing2 t q ==> t = a2 \/ t = a2) /\
      eapply D E pr2 a2 top /\ eapply D E pr2 b2 top /\
      (!t q. t IN D /\ q IN D /\ eapply D E pr2 t q ==> t = a2 \/ t = b2) /\
      eapply D E ckp2 sing2 top /\ eapply D E ckp2 pr2 top /\
      (!t q. t IN D /\ q IN D /\ eapply D E ckp2 t q ==>
       t = sing2 \/ t = pr2) /\
      ebv_eq D E B leq a1 a2 ea /\ ebv_eq D E B leq b1 b2 eb /\
      emeet D E B leq ea eb m /\ ebv_eq D E B leq ckp1 ckp2 e3
      ==> erel D E leq m e3`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `ebalg D (E:A->A->bool) B leq /\ eporder D E B leq`
    STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[ECBA_IMP_BALG; EBALG_IMP_PORDER]; ALL_TAC] THEN
  SUBGOAL_THEN
    `(m:A) IN D /\ (E:A->A->bool) ea B /\ E (eb:A) B /\
     E (m:A) B /\ E (e3:A) B`
    STRIP_ASSUME_TAC THENL [ASM_MESON_TAC[EBV_EQ_IN_B; EMEET_IN]; ALL_TAC] THEN
  (* m <= ea, m <= eb *)
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`ea:A`;`eb:A`;`m:A`]
         EMEET_LE) THEN
  ASM_REWRITE_TAC[] THEN STRIP_TAC THEN
  (* esa = ebv_eq(sing1,sing2), esp = ebv_eq(pr1,pr2) *)
  SUBGOAL_THEN
    `?esa:A. esa IN D /\ (E:A->A->bool) esa B /\
     ebv_eq D E B leq sing1 sing2 esa`
    (X_CHOOSE_THEN `esa:A` STRIP_ASSUME_TAC) THENL
   [MATCH_MP_TAC EBV_EQ_VAL_EXISTS THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN
    `?esp:A. esp IN D /\ (E:A->A->bool) esp B /\ ebv_eq D E B leq pr1 pr2 esp`
    (X_CHOOSE_THEN `esp:A` STRIP_ASSUME_TAC) THENL
   [MATCH_MP_TAC EBV_EQ_VAL_EXISTS THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* m <= esa : via EBV_EQ_UPAIR_CONG on singletons with maa=emeet(ea,ea) *)
  SUBGOAL_THEN `?maa:A. emeet D (E:A->A->bool) B leq ea ea maa`
    (X_CHOOSE_TAC `maa:A`) THENL
   [MATCH_MP_TAC EBALG_MEET THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(maa:A) IN D /\ (E:A->A->bool) maa B` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[EMEET_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq maa esa` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`a1:A`;`a1:A`;
                  `a2:A`;`a2:A`;
                  `sing1:A`;`sing2:A`;`top:A`;`ea:A`;`ea:A`;`maa:A`;`esa:A`]
                   EBV_EQ_UPAIR_CONG) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq m maa` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`ea:A`;`ea:A`;
                  `maa:A`;`m:A`]
                 EMEET_GREATEST) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq m esa` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`m:A`;
                  `maa:A`;`esa:A`]
                 EPORDER_TRANS) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* m <= esp : EBV_EQ_UPAIR_CONG on the pairs, directly (m = emeet(ea,eb)) *)
  SUBGOAL_THEN `erel D (E:A->A->bool) leq m esp` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`a1:A`;`b1:A`;
                  `a2:A`;`b2:A`;
                  `pr1:A`;`pr2:A`;`top:A`;`ea:A`;`eb:A`;`m:A`;`esp:A`]
                   EBV_EQ_UPAIR_CONG) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* mss = emeet(esa,esp); m <= mss; mss <= e3 *)
  SUBGOAL_THEN `?mss:A. emeet D (E:A->A->bool) B leq esa esp mss`
    (X_CHOOSE_TAC `mss:A`) THENL
   [MATCH_MP_TAC EBALG_MEET THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(mss:A) IN D /\ (E:A->A->bool) mss B` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[EMEET_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq m mss` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`esa:A`;`esp:A`;
                  `mss:A`;`m:A`]
                 EMEET_GREATEST) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq mss e3` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`sing1:A`;
                  `pr1:A`;`sing2:A`;
                  `pr2:A`;`ckp1:A`;`ckp2:A`;`top:A`;`esa:A`;`esp:A`;`mss:A`;
                  `e3:A`] EBV_EQ_UPAIR_CONG) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MATCH_MP_TAC(ISPECL
               [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`m:A`;`mss:A`;`e3:A`]
               EPORDER_TRANS) THEN ASM_REWRITE_TAC[]);;

(* ==== EBV_PM_SUBST_LE: slot-70 substitution for pm,
landing on ebv_in(ckp_c,f).
   v0: slots 70=ss, 71=cb, 72=f.  ckp_c = V^B-Kuratowski<cn,cb> (bundle given,
   e.g. from ECHECK_KUR_AUTO for a ground pair).  Then
     [[pm]]_v0 MEET [[ss=cn]]  <=  ebv_in(ckp_c, f).
   Build ckp_ss = <ss,cb> by EUPAIRNAME nesting; [[pm]]_v0 <= ebv_in(ckp_ss,f)
   (BVALF_PMEM_LE); [[ss=cn]] <= ebv_eq(ckp_ss,ckp_c) (EBV_EQ_KUR_CONG, 2nd
   component cb shared so [[cb=cb]]=top); EBV_IN_CONG_L transfers the meet. *)

let EBV_PM_SUBST_LE = prove
 (`!D (E:A->A->bool) B leq (v0:num->A) ss cn cb f sing_c pr_c ckp_c
   top ec mv z.
      model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
      valuation D v0 /\ (!i. bname D E B (v0 i)) /\
      v0 70 = ss /\ v0 71 = cb /\ v0 72 = f /\
      ss IN D /\ cn IN D /\ cb IN D /\ f IN D /\
      sing_c IN D /\ pr_c IN D /\ ckp_c IN D /\
      bname D E B ss /\ bname D E B cn /\ bname D E B cb /\ bname D E B f /\
      top IN D /\ etop D E B leq top /\
      bname D E B sing_c /\ bname D E B pr_c /\ bname D E B ckp_c /\
      eapply D E sing_c cn top /\
      (!t q. t IN D /\ q IN D /\ eapply D E sing_c t q ==> t = cn \/ t = cn) /\
      eapply D E pr_c cn top /\ eapply D E pr_c cb top /\
      (!t q. t IN D /\ q IN D /\ eapply D E pr_c t q ==> t = cn \/ t = cb) /\
      eapply D E ckp_c sing_c top /\ eapply D E ckp_c pr_c top /\
      (!t q. t IN D /\ q IN D /\ eapply D E ckp_c t q ==> t = sing_c \/
       t = pr_c) /\
      ec IN D /\ ebv_eq D E B leq ss cn ec /\
      mv IN D /\ ebv_in D E B leq ckp_c f mv /\
      z IN D /\
      emeet D E B leq
        (bvalf D E B leq v0 (?? 73 (opair_form 70 71 73 && (73 %% 72)))) ec z
      ==> erel D E leq z mv`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `ebalg D (E:A->A->bool) B leq /\ eporder D E B leq`
    STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[ECBA_IMP_BALG; EBALG_IMP_PORDER]; ALL_TAC] THEN
  (* [[pm]]_v0 is in the carrier *)
  SUBGOAL_THEN
    `(bvalf D (E:A->A->bool) B leq v0
      (?? 73 (opair_form 70 71 73 && (73 %% 72)))) IN D /\
     (E:A->A->bool)
       (bvalf D E B leq v0 (?? 73 (opair_form 70 71 73 && (73 %% 72)))) B`
    STRIP_ASSUME_TAC THENL
   [CONJ_TAC THENL
     [MP_TAC(ISPECL
             [`?? 73 (opair_form 70 71 73 && (73 %% 72))`;`D:A->bool`;
              `E:A->A->bool`;
              `B:A`;`leq:A`;`v0:num->A`] BVALF_SPEC) THEN ASM_SIMP_TAC[];
      MP_TAC(ISPECL
             [`?? 73 (opair_form 70 71 73 && (73 %% 72))`;`D:A->bool`;
              `E:A->A->bool`;
              `B:A`;`leq:A`;`v0:num->A`] BVALF_IN_B) THEN ASM_SIMP_TAC[]];
     ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) mv B` ASSUME_TAC THENL
   [ASM_MESON_TAC[EBV_IN_IN_B]; ALL_TAC] THEN
  (* ---- ckp_ss = V^B-Kuratowski<ss,cb> via EUPAIRNAME nesting (tops *)
  (* unified) ---- *)
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`ss:A`;`ss:A`]
         EUPAIRNAME_EXISTS) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `sing_ss:A`
             (X_CHOOSE_THEN `tp1:A` STRIP_ASSUME_TAC)) THEN
  SUBGOAL_THEN `tp1:A = top` SUBST_ALL_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`tp1:A`;`top:A`]
                 ETOP_UNIQUE) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`ss:A`;`cb:A`]
         EUPAIRNAME_EXISTS) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `pr_ss:A`
             (X_CHOOSE_THEN `tp2:A` STRIP_ASSUME_TAC)) THEN
  SUBGOAL_THEN `tp2:A = top` SUBST_ALL_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`tp2:A`;`top:A`]
                 ETOP_UNIQUE) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MP_TAC(ISPECL
         [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`sing_ss:A`;`pr_ss:A`]
         EUPAIRNAME_EXISTS) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `ckp_ss:A`
             (X_CHOOSE_THEN `tp3:A` STRIP_ASSUME_TAC)) THEN
  SUBGOAL_THEN `tp3:A = top` SUBST_ALL_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`tp3:A`;`top:A`]
                 ETOP_UNIQUE) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* mvss = ebv_in(ckp_ss, f) *)
  SUBGOAL_THEN
    `?mvss:A. mvss IN D /\ (E:A->A->bool) mvss B /\
     ebv_in D E B leq ckp_ss f mvss`
    (X_CHOOSE_THEN `mvss:A` STRIP_ASSUME_TAC) THENL
   [MATCH_MP_TAC EBV_IN_VAL_EXISTS THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* [[pm]]_v0 <= mvss  (BVALF_PMEM_LE on ckp_ss) *)
  SUBGOAL_THEN
    `erel D (E:A->A->bool) leq
       (bvalf D E B leq v0 (?? 73 (opair_form 70 71 73 && (73 %% 72)))) mvss`
    ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`v0:num->A`;
                  `sing_ss:A`;
                  `pr_ss:A`;`ckp_ss:A`;`top:A`;`mvss:A`] BVALF_PMEM_LE) THEN
    ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[]; ALL_TAC] THEN
  (* [[cb=cb]] = top *)
  SUBGOAL_THEN
    `?ebcc:A. ebcc IN D /\ (E:A->A->bool) ebcc B /\
     ebv_eq D E B leq cb cb ebcc`
    (X_CHOOSE_THEN `ebcc:A` STRIP_ASSUME_TAC) THENL
   [MATCH_MP_TAC EBV_EQ_VAL_EXISTS THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `etop D (E:A->A->bool) B leq ebcc` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`cb:A`;`ebcc:A`]
                 EBV_EQ_REFL) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* ekk = ebv_eq(ckp_ss, ckp_c) ; ec <= ekk via EBV_EQ_KUR_CONG *)
  SUBGOAL_THEN
    `?ekk:A. ekk IN D /\ (E:A->A->bool) ekk B /\
     ebv_eq D E B leq ckp_ss ckp_c ekk`
    (X_CHOOSE_THEN `ekk:A` STRIP_ASSUME_TAC) THENL
   [MATCH_MP_TAC EBV_EQ_VAL_EXISTS THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) ec B` ASSUME_TAC THENL
   [ASM_MESON_TAC[EBV_EQ_IN_B]; ALL_TAC] THEN
  SUBGOAL_THEN `emeet D (E:A->A->bool) B leq ec ebcc ec` ASSUME_TAC THENL
   [MATCH_MP_TAC EMEET_TOP THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq ec ekk` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`ss:A`;`cb:A`;
                  `cn:A`;`cb:A`;
                  `sing_ss:A`;`pr_ss:A`;`ckp_ss:A`;`sing_c:A`;`pr_c:A`;
                  `ckp_c:A`;`top:A`;
                  `ec:A`;`ebcc:A`;`ec:A`;`ekk:A`] EBV_EQ_KUR_CONG) THEN
     ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* z <= [[pm]] and z <= ec *)
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
    `bvalf D (E:A->A->bool) B leq v0
     (?? 73 (opair_form 70 71 73 && (73 %% 72)))`;`ec:A`;`z:A`]
    EMEET_LE) THEN ASM_REWRITE_TAC[] THEN STRIP_TAC THEN
  SUBGOAL_THEN `(E:A->A->bool) z B` ASSUME_TAC THENL
  [ASM_MESON_TAC[EMEET_IN]; ALL_TAC] THEN
  (* z <= mvss, z <= ekk *)
  SUBGOAL_THEN `erel D (E:A->A->bool) leq z mvss /\ erel D E leq z ekk`
    STRIP_ASSUME_TAC THENL
   [CONJ_TAC THENL
     [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`z:A`;
        `bvalf D (E:A->A->bool) B leq v0
         (?? 73 (opair_form 70 71 73 && (73 %% 72)))`;`mvss:A`]
        EPORDER_TRANS) THEN ASM_REWRITE_TAC[];
      MATCH_MP_TAC(ISPECL
                   [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`z:A`;
                    `ec:A`;`ekk:A`]
                   EPORDER_TRANS) THEN ASM_REWRITE_TAC[]]; ALL_TAC] THEN
  (* zm = emeet(ekk,mvss); z <= zm; zm <= mv by EBV_IN_CONG_L *)
  SUBGOAL_THEN `?zm:A. emeet D (E:A->A->bool) B leq ekk mvss zm`
    (X_CHOOSE_TAC `zm:A`) THENL
   [MATCH_MP_TAC EBALG_MEET THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(zm:A) IN D /\ (E:A->A->bool) zm B` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[EMEET_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq z zm` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`ekk:A`;`mvss:A`;
                  `zm:A`;`z:A`]
                 EMEET_GREATEST) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq zm mv` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`ckp_ss:A`;
                  `ckp_c:A`;`f:A`;
                  `ekk:A`;`mvss:A`;`mv:A`;`zm:A`] EBV_IN_CONG_L) THEN
     ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MATCH_MP_TAC(ISPECL
               [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`z:A`;`zm:A`;`mv:A`]
               EPORDER_TRANS) THEN ASM_REWRITE_TAC[]);;

(* ===================================================================== *)
(* F7.2 m5-cover (part 2): small meet helpers for the assembly.          *)
(*   ELE_MEET_ABSORB (x<=y => emeet x y x) + EMEET_ASSOC.                 *)
(* ===================================================================== *)
(* ==== small meet helpers for the m5-cover assembly ==== *)

(* x <= y  ==>  emeet x y x  (absorption). *)
let ELE_MEET_ABSORB = prove
 (`!D (E:A->A->bool) p leq x y.
      eporder D E p leq /\ x IN D /\ y IN D /\ E x p /\ E y p /\
        erel D E leq x y
      ==> emeet D E p leq x y x`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN REWRITE_TAC[emeet] THEN
  ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[EPORDER_REFL]);;

(* associativity of meet (value form): emeet(emeet(x,y),z) = *)
(* emeet(x,emeet(y,z)). *)
let EMEET_ASSOC = prove
 (`!D (E:A->A->bool) p leq x y z xy yz l r.
      eporder D E p leq /\
      x IN D /\ y IN D /\ z IN D /\ E x p /\ E y p /\ E z p /\
      emeet D E p leq x y xy /\ emeet D E p leq xy z l /\
      emeet D E p leq y z yz /\ emeet D E p leq x yz r
      ==> l = r`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN
    `(xy:A) IN D /\ (E:A->A->bool) xy p /\ (yz:A) IN D /\ E yz p /\
     (l:A) IN D /\ E l p /\ (r:A) IN D /\ E r p`
    STRIP_ASSUME_TAC THENL [ASM_MESON_TAC[EMEET_IN]; ALL_TAC] THEN
  (* l <= x, l <= y, l <= z *)
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`p:A`;`leq:A`;`xy:A`;`z:A`;`l:A`]
         EMEET_LE) THEN
  ASM_REWRITE_TAC[] THEN STRIP_TAC THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`p:A`;`leq:A`;`x:A`;`y:A`;`xy:A`]
         EMEET_LE) THEN
  ASM_REWRITE_TAC[] THEN STRIP_TAC THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`p:A`;`leq:A`;`y:A`;`z:A`;`yz:A`]
         EMEET_LE) THEN
  ASM_REWRITE_TAC[] THEN STRIP_TAC THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`p:A`;`leq:A`;`x:A`;`yz:A`;`r:A`]
         EMEET_LE) THEN
  ASM_REWRITE_TAC[] THEN STRIP_TAC THEN
  SUBGOAL_THEN
    `erel D (E:A->A->bool) leq l x /\ erel D E leq l y /\ erel D E leq l z`
    STRIP_ASSUME_TAC THENL
   [REPEAT CONJ_TAC THENL
     [MATCH_MP_TAC(ISPECL
                   [`D:A->bool`;`E:A->A->bool`;`p:A`;`leq:A`;`l:A`;
                    `xy:A`;`x:A`]
                   EPORDER_TRANS) THEN ASM_REWRITE_TAC[];
      MATCH_MP_TAC(ISPECL
                   [`D:A->bool`;`E:A->A->bool`;`p:A`;`leq:A`;`l:A`;
                    `xy:A`;`y:A`]
                   EPORDER_TRANS) THEN ASM_REWRITE_TAC[];
      ASM_REWRITE_TAC[]]; ALL_TAC] THEN
  SUBGOAL_THEN
    `erel D (E:A->A->bool) leq r x /\ erel D E leq r y /\ erel D E leq r z`
    STRIP_ASSUME_TAC THENL
   [REPEAT CONJ_TAC THENL
     [ASM_REWRITE_TAC[];
      MATCH_MP_TAC(ISPECL
                   [`D:A->bool`;`E:A->A->bool`;`p:A`;`leq:A`;`r:A`;
                    `yz:A`;`y:A`]
                   EPORDER_TRANS) THEN ASM_REWRITE_TAC[];
      MATCH_MP_TAC(ISPECL
                   [`D:A->bool`;`E:A->A->bool`;`p:A`;`leq:A`;`r:A`;
                    `yz:A`;`z:A`]
                   EPORDER_TRANS) THEN ASM_REWRITE_TAC[]]; ALL_TAC] THEN
  (* l <= yz, l <= r *)
  SUBGOAL_THEN `erel D (E:A->A->bool) leq l yz` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`p:A`;`leq:A`;`y:A`;`z:A`;
                  `yz:A`;`l:A`]
                 EMEET_GREATEST) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq l r` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`p:A`;`leq:A`;`x:A`;`yz:A`;
                  `r:A`;`l:A`]
                 EMEET_GREATEST) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* r <= xy, r <= l *)
  SUBGOAL_THEN `erel D (E:A->A->bool) leq r xy` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`p:A`;`leq:A`;`x:A`;`y:A`;
                  `xy:A`;`r:A`]
                 EMEET_GREATEST) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq r l` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`p:A`;`leq:A`;`xy:A`;`z:A`;
                  `l:A`;`r:A`]
                 EMEET_GREATEST) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`p:A`;`leq:A`;`l:A`;`r:A`]
               EPORDER_ANTISYM) THEN
  ASM_REWRITE_TAC[]);;

(* ===================================================================== *)
(* F7 / aleph_2-preservation foundation: generalized fiber pigeonhole.   *)
(*   EUNCOUNTABLE_FIBER (X total-> lam, ~inj(X,lam) ==> some lam-     *)
(*   fiber not >-> om) + COVER_ABSTRACT (gg total a1->lam, every lam- *)
(*   fiber >-> om, ~inj(a1,lam) ==> F).  om->lam at index/kk/non-inj;     *)
(*   fibers stay countable (>-> om), weakened to >-> lam via EINJ_WEAKEN. *)
(* ===================================================================== *)
(* ==== F7 / aleph_2-preservation lemma: generalize the omega->omega_1 fiber
   pigeonhole to arbitrary infinite cardinal domain lam.
     EUNCOUNTABLE_FIBER: X maps total into lam, ~inj(X,lam), each lam-fiber
       potentially countable => SOME lam-fiber does NOT inject into om.
     COVER_ABSTRACT: gg total a1->lam, EVERY lam-fiber injects into om
       (countable), ~inj(a1,lam) => F.
   Compared with EUNCOUNTABLE_FIBER_RAW: (om -> lam) at the fiber-
   INDEX / kk / non-injection positions; KEEP om at the fiber-BOUND position
   (fibers are countable = inject into om);
   add one EINJ_WEAKEN step (fiber>->om
   + om SUBSET lam => fiber>->lam=kk) via omsublam.  EGEN_UNION_CARD_LE is
   already fully general (a>->kk, each member>->kk,
   kk cardinal>=om => union>->kk);
   ESFIB_FAMILY/EFAM_WUN are index-generic. *)

let EUNCOUNTABLE_FIBER = prove
 (`!D (E:A->A->bool) om lam g X.
     model D E ZF_AX /\ (!u. u IN D ==> elmem D E u) /\
     eomega D E om /\ ecardinal D E lam /\ E om lam /\ lam IN D /\
     X IN D /\ g IN D /\
     ~(?e. einj D E e X lam) /\
     (!m. m IN D /\ E m X ==> ?n. n IN D /\ E n lam /\ eapply D E g m n)
     ==> ?n W. n IN D /\ E n lam /\ W IN D /\
               (!m. m IN D ==> (E m W <=> E m X /\ eapply D E g m n)) /\
               ~(?e. einj D E e W om)`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "zf lm omom lamc omlam lamD XD gD noinj gtot" THEN
  (* --- om IN D, eordinal om, ecardinal om; lam ordinal; om SUBSET lam --- *)
  SUBGOAL_THEN `(om:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[EOMEGA_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `eordinal D (E:A->A->bool) om` (LABEL_TAC "omord") THENL
   [ASM_MESON_TAC[EOMEGA_ORDINAL]; ALL_TAC] THEN
  SUBGOAL_THEN `ecardinal D (E:A->A->bool) om` (LABEL_TAC "omcard") THENL
   [REWRITE_TAC[ecardinal] THEN MATCH_MP_TAC EOMEGA_CARDINAL THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `eordinal D (E:A->A->bool) lam` (LABEL_TAC "lamord") THENL
   [ASM_MESON_TAC[ecardinal; ecardof]; ALL_TAC] THEN
  SUBGOAL_THEN `!t:A. t IN D /\ (E:A->A->bool) t om ==> E t lam`
   (LABEL_TAC "omsublam") THENL
   [REPEAT STRIP_TAC THEN
    ASM_MESON_TAC[EORDINAL_MEM_TRANS; EORDINAL_TRANS_SUBSET]; ALL_TAC] THEN
  (* --- identity injection lam >-> lam --- *)
  SUBGOAL_THEN `?ea:A. einj D (E:A->A->bool) ea lam lam`
   (X_CHOOSE_THEN `ea:A` (LABEL_TAC "eainj")) THENL
   [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `lam:A`] EBIJ_ID) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(X_CHOOSE_TAC `h:A`) THEN EXISTS_TAC `h:A` THEN
    MATCH_MP_TAC EBIJ_EINJ THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  (* --- valuation vv with vv 5 = g, vv 6 = X --- *)
  ABBREV_TAC `vv = (5 |-> (g:A))((6 |-> (X:A))(\n:num. X))` THEN
  SUBGOAL_THEN `valuation D (vv:num->A)` ASSUME_TAC THENL
   [EXPAND_TAC "vv" THEN
    REPEAT(MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[]) THEN
    REWRITE_TAC[valuation] THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(vv:num->A) 5 = g /\ (vv:num->A) 6 = X`
   (CONJUNCTS_THEN2 (LABEL_TAC "v5") (LABEL_TAC "v6")) THENL
   [EXPAND_TAC "vv" THEN REWRITE_TAC[VALMOD] THEN
    CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN REWRITE_TAC[]; ALL_TAC] THEN
  (* --- ff = fiber family over lam via ESFIB_FAMILY --- *)
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `vv:num->A`; `lam:A`]
         ESFIB_FAMILY) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  INTRO_TAC "@ff. ffD ffmem sv perb" THEN
  (* --- wun = union of ff-values via EFAM_WUN (index lam) --- *)
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `lam:A`; `ff:A`] EFAM_WUN) THEN
  ANTS_TAC THENL
   [CONJ_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    CONJ_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    CONJ_TAC THENL [USE_THEN "ffD" ACCEPT_TAC; ALL_TAC] THEN
    X_GEN_TAC `p:A` THEN STRIP_TAC THEN
    USE_THEN "ffmem" (fun th -> MP_TAC(SPEC `p:A` th)) THEN
    ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN(fun iff -> FIRST_ASSUM(fun eff -> MP_TAC(EQ_MP iff eff))) THEN
    DISCH_THEN(X_CHOOSE_THEN `u:A` (CONJUNCTS_THEN2 ASSUME_TAC
      (CONJUNCTS_THEN2 (LABEL_TAC "euom") (LABEL_TAC "hp")))) THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `vv:num->A`; `u:A`; `p:A`]
      HOLDS_SFIB) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> USE_THEN "hp" (fun h -> MP_TAC(EQ_MP th h))) THEN
    DISCH_THEN(X_CHOOSE_THEN `W:A` (CONJUNCTS_THEN2 (LABEL_TAC "WD")
      (CONJUNCTS_THEN2 (LABEL_TAC "Wchar") (LABEL_TAC "eop")))) THEN
    MAP_EVERY EXISTS_TAC [`u:A`; `W:A`] THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `wun:A` (CONJUNCTS_THEN2 (LABEL_TAC "wunD")
    (LABEL_TAC "wunmem"))) THEN
  (* --- wun = X by extensionality --- *)
  SUBGOAL_THEN `wun:A = X` SUBST_ALL_TAC THENL
   [FIRST_ASSUM(fun mth -> MATCH_MP_TAC(MATCH_MP ZF_EXTENSIONALITY mth)) THEN
    ASM_REWRITE_TAC[] THEN X_GEN_TAC `t:A` THEN DISCH_TAC THEN
    USE_THEN "wunmem" (fun th -> MP_TAC(SPEC `t:A` th)) THEN
    ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN EQ_TAC THENL
     [DISCH_THEN(X_CHOOSE_THEN `b:A`
                 (X_CHOOSE_THEN `z:A` STRIP_ASSUME_TAC)) THEN
      USE_THEN "perb" (fun th -> MP_TAC(SPEC `b:A` th)) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(X_CHOOSE_THEN `Wb:A` (CONJUNCTS_THEN2 (LABEL_TAC "WbD")
        (CONJUNCTS_THEN2 (LABEL_TAC "Wbchar") (LABEL_TAC "ffbWb")))) THEN
      SUBGOAL_THEN `(z:A) = Wb` SUBST_ALL_TAC THENL
       [USE_THEN "sv" (MP_TAC o SPECL [`b:A`; `z:A`; `Wb:A`]) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC];
        ALL_TAC] THEN
      USE_THEN "Wbchar" (fun th -> MP_TAC(SPEC `t:A` th)) THEN
      ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
      USE_THEN "v6" (fun th -> REWRITE_TAC[th]) THEN ASM_MESON_TAC[];
      DISCH_TAC THEN
      USE_THEN "gtot" (fun th -> MP_TAC(SPEC `t:A` th)) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(X_CHOOSE_THEN `n:A` STRIP_ASSUME_TAC) THEN
      USE_THEN "perb" (fun th -> MP_TAC(SPEC `n:A` th)) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(X_CHOOSE_THEN `Wn:A` (CONJUNCTS_THEN2 (LABEL_TAC "WnD")
        (CONJUNCTS_THEN2 (LABEL_TAC "Wnchar") (LABEL_TAC "ffnWn")))) THEN
      MAP_EVERY EXISTS_TAC [`n:A`; `Wn:A`] THEN ASM_REWRITE_TAC[] THEN
      USE_THEN "Wnchar" (fun th -> MP_TAC(SPEC `t:A` th)) THEN
      ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
      USE_THEN "v6"
        (fun t6 -> USE_THEN "v5" (fun t5 -> REWRITE_TAC[t6; t5])) THEN
        ASM_MESON_TAC[]];
    ALL_TAC] THEN
  (* --- contradiction: if every fiber injects into om, X injects into lam *)
  (* --- *)
  MATCH_MP_TAC(TAUT `(~P ==> F) ==> P`) THEN
  DISCH_THEN(MP_TAC o REWRITE_RULE[NOT_EXISTS_THM;
    TAUT `~(a /\ b /\ c /\ d /\ ~e) <=> (a /\ b /\ c /\ d ==> e)`]) THEN
  DISCH_THEN(LABEL_TAC "allcnt") THEN
  (* --- per-b clause for EGEN_UNION_CARD_LE (fiber >-> om weakened to >-> *)
  (* lam) --- *)
  SUBGOAL_THEN
   `!b:A. b IN D /\ E b lam
      ==> ?z. z IN D /\ eapply D E ff b z /\
              (!u. u IN D /\ E u z ==> E u X) /\
              (?e. e IN D /\ einj D (E:A->A->bool) e z lam)`
   (LABEL_TAC "egenperb") THENL
   [X_GEN_TAC `b:A` THEN STRIP_TAC THEN
    USE_THEN "perb" (fun th -> MP_TAC(SPEC `b:A` th)) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(X_CHOOSE_THEN `Wb:A` (CONJUNCTS_THEN2 (LABEL_TAC "WbD")
      (CONJUNCTS_THEN2 (LABEL_TAC "Wbchar") (LABEL_TAC "ffbWb")))) THEN
    EXISTS_TAC `Wb:A` THEN ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
     [X_GEN_TAC `u:A` THEN STRIP_TAC THEN
      USE_THEN "Wbchar" (fun th -> MP_TAC(SPEC `u:A` th)) THEN
      ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
      USE_THEN "v6" (fun th -> REWRITE_TAC[th]) THEN ASM_MESON_TAC[];
      USE_THEN "allcnt" (MP_TAC o SPECL [`b:A`; `Wb:A`]) THEN
      ANTS_TAC THENL
       [ASM_REWRITE_TAC[] THEN X_GEN_TAC `m:A` THEN DISCH_TAC THEN
        USE_THEN "Wbchar" (fun th -> MP_TAC(SPEC `m:A` th)) THEN
        ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
        USE_THEN "v6" (fun t6 -> USE_THEN "v5" (fun t5 ->
          REWRITE_TAC[t6; t5]));
        DISCH_THEN(X_CHOOSE_THEN `einjw:A` ASSUME_TAC) THEN
        EXISTS_TAC `einjw:A` THEN CONJ_TAC THENL
         [ACCEPT_TAC(CONJUNCT1(REWRITE_RULE[einj] (ASSUME
            `einj D (E:A->A->bool) einjw Wb om`)));
          MATCH_MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `einjw:A`;
            `Wb:A`; `om:A`; `lam:A`] EINJ_WEAKEN) THEN
          CONJ_TAC THENL
           [FIRST_ASSUM ACCEPT_TAC;
            USE_THEN "omsublam" ACCEPT_TAC]]]];
    ALL_TAC] THEN
  (* --- apply EGEN_UNION_CARD_LE (a=lam, kk=lam, ea=id, ya=X, wun=X) --- *)
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `om:A`; `lam:A`; `lam:A`;
     `ea:A`; `X:A`; `ff:A`; `X:A`] EGEN_UNION_CARD_LE) THEN
  ANTS_TAC THENL
   [CONJ_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    CONJ_TAC THENL [USE_THEN "lm" ACCEPT_TAC; ALL_TAC] THEN
    CONJ_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    CONJ_TAC THENL [USE_THEN "lamc" ACCEPT_TAC; ALL_TAC] THEN
    CONJ_TAC THENL [DISJ1_TAC THEN USE_THEN "omlam" ACCEPT_TAC; ALL_TAC] THEN
    CONJ_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    CONJ_TAC THENL [USE_THEN "lamord" ACCEPT_TAC; ALL_TAC] THEN
    CONJ_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    CONJ_TAC THENL [USE_THEN "eainj" ACCEPT_TAC; ALL_TAC] THEN
    CONJ_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    CONJ_TAC THENL [USE_THEN "ffD" ACCEPT_TAC; ALL_TAC] THEN
    CONJ_TAC THENL [USE_THEN "sv" ACCEPT_TAC; ALL_TAC] THEN
    CONJ_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    CONJ_TAC THENL [USE_THEN "wunmem" ACCEPT_TAC; ALL_TAC] THEN
    USE_THEN "egenperb" ACCEPT_TAC;
    ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_TAC `e0:A`) THEN
  UNDISCH_TAC `~(?e:A. einj D (E:A->A->bool) e X lam)` THEN
  ASM_MESON_TAC[]);;

(* ==== COVER_ABSTRACT: gg total a1->lam, every lam-fiber injects into om
   (countable), ~inj(a1,lam) ==> F.  Wrapper over EUNCOUNTABLE_FIBER. *)

let COVER_ABSTRACT = prove
 (`!D (E:A->A->bool) om lam a1 gg.
     model D E ZF_AX /\ (!u. u IN D ==> elmem D E u) /\
     eomega D E om /\ ecardinal D E lam /\ E om lam /\ lam IN D /\
     a1 IN D /\ gg IN D /\
     ~(?e. einj D E e a1 lam) /\
     (!bet. bet IN D /\ E bet a1
            ==> ?n. n IN D /\ E n lam /\ eapply D E gg bet n) /\
     (!n. n IN D /\ E n lam
          ==> ?Wn e. Wn IN D /\
                     (!u. u IN D ==>
                      (E u Wn <=> E u a1 /\ eapply D E gg u n)) /\
                     einj D E e Wn om)
     ==> F`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `om:A`; `lam:A`; `gg:A`; `a1:A`]
    EUNCOUNTABLE_FIBER) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `n:A` (X_CHOOSE_THEN `W:A` STRIP_ASSUME_TAC)) THEN
  SUBGOAL_THEN
   `?Wn e. Wn IN D /\
           (!u. u IN D ==>
            (E u Wn <=> E u a1 /\ eapply D (E:A->A->bool) gg u n)) /\
           einj D E e Wn om`
  STRIP_ASSUME_TAC THENL
   [FIRST_X_ASSUM MATCH_MP_TAC THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(W:A) = Wn` SUBST_ALL_TAC THENL
   [FIRST_ASSUM(MP_TAC o MATCH_MP ZF_EXTENSIONALITY) THEN
    DISCH_THEN MATCH_MP_TAC THEN ASM_REWRITE_TAC[] THEN
    X_GEN_TAC `z:A` THEN DISCH_TAC THEN ASM_MESON_TAC[]; ALL_TAC] THEN
  UNDISCH_TAC `~(?e. einj D (E:A->A->bool) e Wn om)` THEN
  REWRITE_TAC[] THEN EXISTS_TAC `e:A` THEN FIRST_ASSUM ACCEPT_TAC);;

(* ===================================================================== *)
(* F7 / aleph_2-preservation: cardinal-arithmetic setup.                 *)
(*   ECARD_NO_INJ_DOWN: a cardinal a1 does not inject into a strictly     *)
(*   smaller ordinal lam (lam IN a1).  = aleph_2^ not collapsed below     *)
(*   aleph_1^.  EINJ_ORDINAL_CARD_LE + E_NOCYCLE2.                         *)
(* ===================================================================== *)
(* ==== F7 / aleph_2-preservation: cardinal-arithmetic setup lemmas. ==== *)

(* A cardinal does not inject into any strictly smaller ordinal:
   ecardinal a1 /\ eordinal lam /\ lam IN a1  ==>  ~(a1 >-> lam).
   (= "a1 is not collapsed below lam"; here a1 = aleph_2^, lam = aleph_1^.)
   Via EINJ_ORDINAL_CARD_LE (einj a1 lam + ecardof a1 a1 => a1 IN
     lam \/ a1=lam)
   then E_NOCYCLE2 against E lam a1. *)
let ECARD_NO_INJ_DOWN = prove
 (`!D (E:A->A->bool) lam a1.
     model D E ZF_AX /\ ecardinal D E a1 /\ eordinal D E lam /\
     a1 IN D /\ lam IN D /\ E lam a1
     ==> ~(?e. einj D E e a1 lam)`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `ecardof D (E:A->A->bool) a1 a1` ASSUME_TAC THENL
   [ASM_MESON_TAC[ecardinal]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_TAC `e:A`) THEN
  MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `e:A`; `a1:A`; `lam:A`; `a1:A`]
    EINJ_ORDINAL_CARD_LE) THEN
  ASM_REWRITE_TAC[] THEN
  ASM_MESON_TAC[E_NOCYCLE2]);;

(* ===================================================================== *)
(* F7 / aleph_2-preservation forcing chain (1): meta-extraction + cover. *)
(*   EXMEM_META_N (om = an arbitrary set with a check; no eomega         *)
(*   hypothesis, since ECHECK_IN_LE_SUP is generic) and M5_COVER (inner  *)
(*   ?? bound dm (= aleph_1^): onto a1^ from dm^ ==> covering clause).   *)
(* ===================================================================== *)
(* ==== EXMEM_META_N: om is an arbitrary set with a check omc (no eomega
   hypothesis: the proof uses only ECHECK_IN_LE_SUP, which is domain-generic,
   and Boolean algebra).  This is the meta-extraction core for M5_COVER
   (inner-?? bound dm = aleph_1^). *)

let EXMEM_META_N = prove
 (`!D (E:A->A->bool) B leq onebee om omc ss bm z w.
      model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
      onebee IN D /\ E onebee B /\
      echeck D E onebee om omc /\
      bname D E B ss /\ ss IN D /\ bm IN D /\ E bm B /\
      z IN D /\ ebv_in D E B leq ss omc z /\
      w IN D /\ emeet D E B leq bm z w /\ ~ebot D E B leq w
      ==> ?c vc ec wc. E c om /\ echeck D E onebee c vc /\ ec IN D /\
                       ebv_eq D E B leq ss vc ec /\ wc IN D /\
                       emeet D E B leq bm ec wc /\ ~ebot D E B leq wc`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `ebalg D (E:A->A->bool) B leq /\ eporder D E B leq`
    STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[ECBA_IMP_BALG; EBALG_IMP_PORDER]; ALL_TAC] THEN
  SUBGOAL_THEN `(om:A) IN D /\ (omc:A) IN D` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[ECHECK_IMP]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) z B` ASSUME_TAC THENL
   [MP_TAC(ISPECL
           [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`ss:A`;`omc:A`;`z:A`]
           EBV_IN_IN_B) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) w B` ASSUME_TAC THENL
   [MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`bm:A`;`z:A`;`w:A`]
      EMEET_IN) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `?bot:A. ebot D (E:A->A->bool) B leq bot`
    (X_CHOOSE_TAC `bot:A`) THENL
   [MATCH_MP_TAC EBALG_BOT THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `?top:A. etop D (E:A->A->bool) B leq top`
    (X_CHOOSE_TAC `top:A`) THENL
   [MATCH_MP_TAC EBALG_TOP THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN
    `(bot:A) IN D /\ (E:A->A->bool) (bot:A) B /\ (top:A) IN D /\ E (top:A) B`
    STRIP_ASSUME_TAC THENL [ASM_MESON_TAC[EBOT_IN; ETOP_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `?cbm:A. ecompl D (E:A->A->bool) B leq bm cbm`
    (X_CHOOSE_TAC `cbm:A`) THENL
   [MATCH_MP_TAC EBALG_COMPL THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(cbm:A) IN D /\ (E:A->A->bool) (cbm:A) B`
    STRIP_ASSUME_TAC THENL
   [MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`bm:A`;`cbm:A`]
           ECOMPL_IN) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `emeet D (E:A->A->bool) B leq bm cbm bot` ASSUME_TAC THENL
   [MP_TAC(ISPECL
           [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`bm:A`;`cbm:A`;`bot:A`;
            `top:A`] ECOMPL_MEET_JOIN) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN STRIP_TAC THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MATCH_MP_TAC(TAUT `(~t ==> F) ==> t`) THEN
  DISCH_THEN(MP_TAC o REWRITE_RULE[NOT_EXISTS_THM]) THEN
  REWRITE_TAC[TAUT
    `~(a /\ b /\ c /\ d /\ e /\ f /\ ~g) <=>
     (a /\ b /\ c /\ d /\ e /\ f ==> g)`] THEN
  DISCH_TAC THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq z cbm` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`onebee:A`;`om:A`;
                  `omc:A`;`ss:A`;`z:A`;`cbm:A`] ECHECK_IN_LE_SUP) THEN
    ASM_REWRITE_TAC[] THEN
    MAP_EVERY X_GEN_TAC [`c:A`;`vc:A`;`ec:A`] THEN STRIP_TAC THEN
    SUBGOAL_THEN `(vc:A) IN D` ASSUME_TAC THENL
     [ASM_MESON_TAC[ECHECK_IMP]; ALL_TAC] THEN
    SUBGOAL_THEN `(ec:A) IN D /\ (E:A->A->bool) (ec:A) B`
      STRIP_ASSUME_TAC THENL
      [CONJ_TAC THENL
       [ASM_REWRITE_TAC[];
        MP_TAC(ISPECL
               [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`ss:A`;`vc:A`;`ec:A`]
               EBV_EQ_IN_B) THEN ASM_REWRITE_TAC[]]; ALL_TAC] THEN
    SUBGOAL_THEN `?wc:A. emeet D (E:A->A->bool) B leq bm ec wc`
      (X_CHOOSE_TAC `wc:A`) THENL
      [MATCH_MP_TAC EBALG_MEET THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN `(wc:A) IN D /\ (E:A->A->bool) (wc:A) B`
      STRIP_ASSUME_TAC THENL
      [MP_TAC(ISPECL
              [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`bm:A`;`ec:A`;`wc:A`]
              EMEET_IN) THEN
       ASM_REWRITE_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN `ebot D (E:A->A->bool) B leq wc` ASSUME_TAC THENL
     [FIRST_X_ASSUM(MP_TAC o SPECL [`c:A`;`vc:A`;`ec:A`;`wc:A`]) THEN
      ASM_REWRITE_TAC[]; ALL_TAC] THEN
    MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
       `ec:A`;`bm:A`;`cbm:A`;`wc:A`;`bot:A`] EMEET_BOT_COMPL) THEN
    ASM_REWRITE_TAC[] THEN REPEAT CONJ_TAC THENL
     [MATCH_MP_TAC EMEET_SYM THEN ASM_REWRITE_TAC[];
      MATCH_MP_TAC EBOT_LE THEN EXISTS_TAC `B:A` THEN ASM_REWRITE_TAC[]];
     ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq w bot` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
      `bm:A`;`z:A`;`bm:A`;`cbm:A`;`w:A`;`bot:A`] EMEET_MONO) THEN
    ASM_REWRITE_TAC[] THEN MATCH_MP_TAC EPORDER_REFL THEN
    EXISTS_TAC `B:A` THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(w:A) = bot` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`w:A`;`bot:A`]
                 ELE_BOT) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  UNDISCH_TAC `~ebot D (E:A->A->bool) B leq w` THEN ASM_REWRITE_TAC[]);;

(* ==== M5_COVER: onto ==>
  covering.  From "b0 forces f onto a1^ from dm^", i.e.
   b0 <= [[ !!- 71 68 (??- 70 69 pm) ]]_v0  (v0: 68=a1c=a1^, 69=dmc=dm^, 72=f),
   derive NO_SURJ_NAME's covering clause: for each META bet IN a1, a META n<dm
   with b0 MEET [[<n^,bet^> IN f]] =/= bot.  Chain: EBVALF_ALLMEM_LE
     (inst bet^) +
   [[bet^ in a1^]]=top (ECHECK_IN_GE_ELT+EBV_EQ_REFL) + EBIMP_MEET_LE -> b0 <=
   [[??n. n in dm^ && pm]];
   ELE_MEET_ABSORB + BVALF_EX_POS_MEET -> bname ss with
   b0 MEET [[ss in dm^]] MEET [[pm(ss)]] =/= bot; EMEET_ASSOC + EXMEM_META_N ->
   META c with (b0 MEET [[pm(ss)]]) MEET [[ss=c^]] =/= bot;
   ECHECK_KUR_AUTO builds
   ckp=<c,bet>^ bundle;
   EBV_PM_SUBST_LE: [[pm(ss)]] MEET [[ss=c^]] <= ebv_in(ckp,f);
   EMEET_ASSOC + EMEET_MONO -> b0 MEET ebv_in(ckp,f) =/= bot. *)

let M5_COVER = prove
 (`!D (E:A->A->bool) B leq onebee a1 a1c dm dmc f b0 v0.
      model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
      (!u. u IN D ==> elmem D E u) /\
      onebee IN D /\ E onebee B /\ etop D E B leq onebee /\
      a1 IN D /\ dm IN D /\
      echeck D E onebee a1 a1c /\ echeck D E onebee dm dmc /\
      f IN D /\ bname D E B f /\ b0 IN D /\ E b0 B /\ ~ebot D E B leq b0 /\
      valuation D v0 /\ (!i. bname D E B (v0 i)) /\
      v0 68 = a1c /\ v0 69 = dmc /\ v0 72 = f /\
      erel D E leq b0 (bvalf D E B leq v0
         (!!- 71 68 (??- 70 69 (?? 73 (opair_form 70 71 73 && (73 %% 72))))))
      ==> !bet. bet IN D /\ E bet a1
                ==> ?n pnb ckp mv dd. n IN D /\ E n dm /\
                  pnb IN D /\ ckp IN D /\
                       mv IN D /\ dd IN D /\
                       eopair D E n bet pnb /\ echeck D E onebee pnb ckp /\
                       ebv_in D E B leq ckp f mv /\ emeet D E B leq b0 mv dd /\
                       ~ebot D E B leq dd`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `ebalg D (E:A->A->bool) B leq /\ eporder D E B leq`
    STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[ECBA_IMP_BALG; EBALG_IMP_PORDER]; ALL_TAC] THEN
  SUBGOAL_THEN `a1c IN D /\ (dmc:A) IN D` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[ECHECK_IMP]; ALL_TAC] THEN
  SUBGOAL_THEN `bname D (E:A->A->bool) B a1c /\ bname D E B dmc`
    STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[ECHECK_IS_BNAME]; ALL_TAC] THEN
  X_GEN_TAC `bet:A` THEN STRIP_TAC THEN
  (* cb = bet^ *)
  SUBGOAL_THEN `?cb. echeck D (E:A->A->bool) onebee bet cb`
    (X_CHOOSE_TAC `cb:A`) THENL
   [ASM_MESON_TAC[ECHECK_EXHAUSTION]; ALL_TAC] THEN
  SUBGOAL_THEN `(cb:A) IN D /\ bname D (E:A->A->bool) B cb`
    STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[ECHECK_IMP; ECHECK_IS_BNAME]; ALL_TAC] THEN
  ABBREV_TAC `v1 = (71 |-> cb) (v0:num->A)` THEN
  SUBGOAL_THEN `valuation D (v1:num->A) /\ (!i. bname D E B ((v1:num->A) i))`
    STRIP_ASSUME_TAC THENL
   [EXPAND_TAC "v1" THEN CONJ_TAC THENL
     [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[];
      MATCH_MP_TAC BNAMEVAL_VALMOD THEN ASM_REWRITE_TAC[]]; ALL_TAC] THEN
  SUBGOAL_THEN
    `(v1:num->A) 71 = cb /\ (v1:num->A) 68 = a1c /\ (v1:num->A) 69 = dmc /\
     (v1:num->A) 72 = f`
    STRIP_ASSUME_TAC THENL
   [EXPAND_TAC "v1" THEN ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER; ARITH_EQ];
    ALL_TAC] THEN
  (* bvalf endpoints IN D (for EBV_IN_IN_B and EPORDER_TRANS) *)
  SUBGOAL_THEN
    `(bvalf D (E:A->A->bool) B leq v1 (71 %% 68)) IN D /\
     (bvalf D (E:A->A->bool) B leq v0
        (!!- 71 68
         (??- 70 69 (?? 73 (opair_form 70 71 73 && (73 %% 72)))))) IN D /\
     (bvalf D (E:A->A->bool) B leq v1
        ((71 %% 68) -->
         (??- 70 69 (?? 73 (opair_form 70 71 73 && (73 %% 72)))))) IN D`
    STRIP_ASSUME_TAC THENL
   [REPEAT CONJ_TAC THENL
     [MP_TAC(ISPECL
             [`(71 %% 68):form`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
              `v1:num->A`] BVALF_SPEC) THEN ASM_SIMP_TAC[];
      MP_TAC(ISPECL
             [`!!- 71 68
               (??- 70 69 (?? 73 (opair_form 70 71 73 && (73 %% 72))))`;
              `D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`v0:num->A`]
               BVALF_SPEC) THEN ASM_SIMP_TAC[];
      MP_TAC(ISPECL
             [`(71 %% 68) -->
               (??- 70 69 (?? 73 (opair_form 70 71 73 && (73 %% 72))))`;
              `D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`v1:num->A`]
               BVALF_SPEC) THEN ASM_SIMP_TAC[]];
    ALL_TAC] THEN
  (* EBVALF_ALLMEM_LE: [[onto]] <= [[71%%68 --> P]]_v1 *)
  MP_TAC(ISPECL
         [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`v0:num->A`;`71`;`68`;
          `??- 70 69 (?? 73 (opair_form 70 71 73 && (73 %% 72)))`;`cb:A`]
           EBVALF_ALLMEM_LE) THEN
  ASM_REWRITE_TAC[] THEN DISCH_TAC THEN
  (* b0 <= [[71%%68 --> P]]_v1 by transitivity *)
  SUBGOAL_THEN
    `erel D (E:A->A->bool) leq b0
       (bvalf D E B leq v1
        ((71 %% 68) -->
         (??- 70 69 (?? 73 (opair_form 70 71 73 && (73 %% 72))))))`
    ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`b0:A`;
      `bvalf D (E:A->A->bool) B leq v0
         (!!- 71 68 (??- 70 69 (?? 73 (opair_form 70 71 73 && (73 %% 72)))))`;
      `bvalf D (E:A->A->bool) B leq v1
         ((71 %% 68) -->
          (??- 70 69 (?? 73 (opair_form 70 71 73 && (73 %% 72)))))`]
      EPORDER_TRANS) THEN ASM_REWRITE_TAC[] THEN
    CONJ_TAC THENL
     [MP_TAC(ISPECL
             [`!!- 71 68
               (??- 70 69 (?? 73 (opair_form 70 71 73 && (73 %% 72))))`;
              `D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`v0:num->A`]
               BVALF_IN_B) THEN ASM_SIMP_TAC[];
      MP_TAC(ISPECL
             [`(71 %% 68) -->
               (??- 70 69 (?? 73 (opair_form 70 71 73 && (73 %% 72))))`;
              `D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`v1:num->A`]
               BVALF_IN_B) THEN ASM_SIMP_TAC[]];
    ALL_TAC] THEN
  (* [[71%%68]]_v1 = ebv_in(cb,a1c) = top (member-check) *)
  SUBGOAL_THEN
    `ebv_in D (E:A->A->bool) B leq cb a1c (bvalf D E B leq v1 (71 %% 68))`
    ASSUME_TAC THENL
   [MP_TAC(ISPECL
           [`71`;`68`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`v1:num->A`]
           BVALF_MEM) THEN
    ASM_SIMP_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN
    `?ecaa. ecaa IN D /\ (E:A->A->bool) ecaa B /\ ebv_eq D E B leq cb cb ecaa`
    (X_CHOOSE_THEN `ecaa:A` STRIP_ASSUME_TAC) THENL
   [MATCH_MP_TAC EBV_EQ_VAL_EXISTS THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `etop D (E:A->A->bool) B leq (bvalf D E B leq v1 (71 %% 68))`
    ASSUME_TAC THENL
   [SUBGOAL_THEN `etop D (E:A->A->bool) B leq ecaa` ASSUME_TAC THENL
     [MATCH_MP_TAC(ISPECL
                   [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`cb:A`;`ecaa:A`]
                   EBV_EQ_REFL) THEN
      ASM_REWRITE_TAC[]; ALL_TAC] THEN
    (* ecaa <= [[cb in a1c]] by ECHECK_IN_GE_ELT (c:=bet in a1), so [[cb in *)
    (* a1c]]=top *)
    SUBGOAL_THEN
      `erel D (E:A->A->bool) leq ecaa (bvalf D E B leq v1 (71 %% 68))`
      ASSUME_TAC THENL
      [MATCH_MP_TAC(ISPECL
                    [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`onebee:A`;
                     `a1:A`;`a1c:A`;
                     `bet:A`;`cb:A`;`cb:A`;
                     `bvalf D (E:A->A->bool) B leq v1 (71 %% 68)`;`ecaa:A`]
        ECHECK_IN_GE_ELT) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    (* top = ecaa <= [[..]] <= top, so [[..]] = top *)
    SUBGOAL_THEN `(E:A->A->bool) (bvalf D E B leq v1 (71 %% 68)) B`
      ASSUME_TAC THENL
      [ASM_MESON_TAC[EBV_IN_IN_B]; ALL_TAC] THEN
    ASM_MESON_TAC[ETOP_GE; EPORDER_ANTISYM; ETOP_IN; ETOP_UNIQUE];
    ALL_TAC] THEN
  (* b0 <= [[P]]_v1  via EBIMP_MEET_LE (71%%68 is top) *)
  ABBREV_TAC `Pv = bvalf D (E:A->A->bool) B leq v1
                     (??- 70 69
                      (?? 73 (opair_form 70 71 73 && (73 %% 72))))` THEN
  SUBGOAL_THEN `(bvalf D (E:A->A->bool) B leq v1 (71 %% 68)) IN D /\
                (E:A->A->bool) (bvalf D E B leq v1 (71 %% 68)) B /\
                (Pv:A) IN D /\ (E:A->A->bool) Pv B`
    STRIP_ASSUME_TAC THENL
   [REPEAT CONJ_TAC THENL
     [ASM_MESON_TAC[EBV_IN_IN_B];
      ASM_MESON_TAC[EBV_IN_IN_B];
      EXPAND_TAC "Pv" THEN
      MP_TAC(ISPECL [`??- 70 69 (?? 73 (opair_form 70 71 73 && (73 %% 72)))`;
                     `D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`v1:num->A`]
          BVALF_SPEC) THEN ASM_SIMP_TAC[];
      EXPAND_TAC "Pv" THEN
      MP_TAC(ISPECL [`??- 70 69 (?? 73 (opair_form 70 71 73 && (73 %% 72)))`;
                     `D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`v1:num->A`]
            BVALF_IN_B) THEN ASM_SIMP_TAC[]];
    ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq b0 Pv` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`b0:A`;
      `bvalf D (E:A->A->bool) B leq v1 (71 %% 68)`;`Pv:A`;
      `bvalf D (E:A->A->bool) B leq v1
         ((71 %% 68) -->
          (??- 70 69 (?? 73 (opair_form 70 71 73 && (73 %% 72)))))`;`b0:A`]
      EBIMP_MEET_LE) THEN
    ASM_REWRITE_TAC[] THEN REPEAT CONJ_TAC THENL
     [EXPAND_TAC "Pv" THEN
      MP_TAC(ISPECL
             [`71 %% 68`;
              `??- 70 69 (?? 73 (opair_form 70 71 73 && (73 %% 72)))`;
              `D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`v1:num->A`]
               BVALF_IMP) THEN ASM_SIMP_TAC[];
      MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
        `bvalf D (E:A->A->bool) B leq v1 (71 %% 68)`;`b0:A`] EMEET_TOP) THEN
      ASM_REWRITE_TAC[]]; ALL_TAC] THEN
  (* unfold Existsmem: Pv = [[?? 70 (70%%69 && pm)]]_v1 *)
  SUBGOAL_THEN `Pv = bvalf D (E:A->A->bool) B leq v1
       (?? 70 ((70 %% 69) && (?? 73 (opair_form 70 71 73 && (73 %% 72)))))`
    SUBST_ALL_TAC THENL
   [EXPAND_TAC "Pv" THEN REWRITE_TAC[Existsmem_DEF]; ALL_TAC] THEN
  (* emeet b0 Pv b0 (absorb), then BVALF_EX_POS_MEET *)
  SUBGOAL_THEN
    `emeet D (E:A->A->bool) B leq b0
       (bvalf D E B leq v1
        (?? 70 ((70 %% 69) &&
                (?? 73 (opair_form 70 71 73 && (73 %% 72)))))) b0`
    ASSUME_TAC THENL
   [MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`b0:A`;
      `bvalf D (E:A->A->bool) B leq v1
         (?? 70 ((70 %% 69) && (?? 73 (opair_form 70 71 73 && (73 %% 72)))))`]
          ELE_MEET_ABSORB) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`] EBALG_BOT) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `bot:A`) THEN
  MP_TAC(ISPECL
         [`70`;`(70 %% 69) && (?? 73 (opair_form 70 71 73 && (73 %% 72)))`;
          `D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`v1:num->A`;`b0:A`;
          `bot:A`;`b0:A`]
    BVALF_EX_POS_MEET) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `ss:A` (X_CHOOSE_THEN `mm:A` STRIP_ASSUME_TAC)) THEN
  (* ---------- SECOND HALF: extraction -> covering clause ---------- *)
  SUBGOAL_THEN `valuation D ((70 |-> ss) (v1:num->A)) /\
                (!i. bname D E B (((70 |-> ss) (v1:num->A)) i))`
    STRIP_ASSUME_TAC THENL
   [CONJ_TAC THENL [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[];
     MATCH_MP_TAC BNAMEVAL_VALMOD THEN ASM_REWRITE_TAC[]]; ALL_TAC] THEN
  ABBREV_TAC `v2 = (70 |-> ss) (v1:num->A)` THEN
  SUBGOAL_THEN
    `(v2:num->A) 70 = ss /\ (v2:num->A) 71 = cb /\ (v2:num->A) 72 = f /\
     (v2:num->A) 69 = dmc`
    STRIP_ASSUME_TAC THENL
   [EXPAND_TAC "v2" THEN ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER; ARITH_EQ];
    ALL_TAC] THEN
  ABBREV_TAC `pmv = bvalf D (E:A->A->bool) B leq v2
                      (?? 73 (opair_form 70 71 73 && (73 %% 72)))` THEN
  ABBREV_TAC `memv = bvalf D (E:A->A->bool) B leq v2 (70 %% 69)` THEN
  SUBGOAL_THEN `ebv_in D (E:A->A->bool) B leq ss dmc memv` ASSUME_TAC THENL
   [EXPAND_TAC "memv" THEN
    MP_TAC(ISPECL
           [`70`;`69`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`v2:num->A`]
           BVALF_MEM) THEN
    ASM_SIMP_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `emeet D (E:A->A->bool) B leq memv pmv
       (bvalf D E B leq v2
        ((70 %% 69) && (?? 73 (opair_form 70 71 73 && (73 %% 72)))))`
    ASSUME_TAC THENL
   [MAP_EVERY EXPAND_TAC ["memv";"pmv"] THEN
    MP_TAC(ISPECL [`70 %% 69`;`?? 73 (opair_form 70 71 73 && (73 %% 72))`;
      `D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`v2:num->A`]
          BVALF_AND_MEET) THEN ASM_SIMP_TAC[];
    ALL_TAC] THEN
  ABBREV_TAC `cj = bvalf D (E:A->A->bool) B leq v2
                     ((70 %% 69) &&
                      (?? 73 (opair_form 70 71 73 && (73 %% 72))))` THEN
  SUBGOAL_THEN
    `(memv:A) IN D /\ (E:A->A->bool) memv B /\ (pmv:A) IN D /\ E (pmv:A) B /\
     (cj:A) IN D /\ (E:A->A->bool) cj B`
    STRIP_ASSUME_TAC THENL
   [MAP_EVERY EXPAND_TAC ["memv";"pmv";"cj"] THEN
    ASM_MESON_TAC[BVALF_SPEC; BVALF_IN_B]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) mm B` ASSUME_TAC THENL
  [ASM_MESON_TAC[EMEET_IN]; ALL_TAC] THEN
  (* emeet bm memv mm by EMEET_ASSOC(b0,pmv,memv) with yz:=cj, r:=mm *)
  SUBGOAL_THEN `emeet D (E:A->A->bool) B leq pmv memv cj` ASSUME_TAC THENL
   [MATCH_MP_TAC EMEET_SYM THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `?bm. emeet D (E:A->A->bool) B leq b0 pmv bm`
    (X_CHOOSE_TAC `bm:A`) THENL
   [MATCH_MP_TAC EBALG_MEET THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(bm:A) IN D /\ (E:A->A->bool) bm B` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[EMEET_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `?Lm. emeet D (E:A->A->bool) B leq bm memv Lm`
    (X_CHOOSE_TAC `Lm:A`) THENL
   [MATCH_MP_TAC EBALG_MEET THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(Lm:A) = mm` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`b0:A`;
                  `pmv:A`;`memv:A`;
                  `bm:A`;`cj:A`;`Lm:A`;`mm:A`] EMEET_ASSOC) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBST_ALL_TAC(ASSUME `(Lm:A) = mm`) THEN
  (* now emeet bm memv mm is an assumption *)
  (* EXMEM_META_N: META c with (b0 MEET pmv) MEET [[ss=c^]] =/= bot *)
  MP_TAC(ISPECL
         [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`onebee:A`;`dm:A`;
          `dmc:A`;`ss:A`;
          `bm:A`;`memv:A`;`mm:A`] EXMEM_META_N) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `c:A` (X_CHOOSE_THEN `vc:A` (X_CHOOSE_THEN `ec:A`
    (X_CHOOSE_THEN `wc:A` STRIP_ASSUME_TAC)))) THEN
  SUBGOAL_THEN `(c:A) IN D /\ (vc:A) IN D /\ bname D (E:A->A->bool) B vc`
    STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[ECHECK_IMP; ECHECK_IS_BNAME]; ALL_TAC] THEN
  (* pnb = <c,bet>, ckp = pnb^ *)
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`c:A`;`bet:A`] EOPAIR_EXISTS) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `pnb:A`) THEN
  SUBGOAL_THEN `(pnb:A) IN D` ASSUME_TAC THENL
  [ASM_MESON_TAC[eopair; EOPAIR_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `?ckp. echeck D (E:A->A->bool) onebee pnb ckp`
    (X_CHOOSE_TAC `ckp:A`) THENL
   [ASM_MESON_TAC[ECHECK_EXHAUSTION]; ALL_TAC] THEN
  SUBGOAL_THEN `(ckp:A) IN D /\ bname D (E:A->A->bool) B ckp`
    STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[ECHECK_IMP; ECHECK_IS_BNAME]; ALL_TAC] THEN
  (* ECHECK_KUR_AUTO: bundle for ckp = <c,bet>^ *)
  MP_TAC(ISPECL
         [`D:A->bool`;`E:A->A->bool`;`B:A`;`onebee:A`;`c:A`;`bet:A`;
          `vc:A`;`cb:A`;
          `pnb:A`;`ckp:A`] ECHECK_KUR_AUTO) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `sing_c:A`
             (X_CHOOSE_THEN `pr_c:A` STRIP_ASSUME_TAC)) THEN
  SUBGOAL_THEN `bname D (E:A->A->bool) B sing_c /\ bname D E B pr_c`
    STRIP_ASSUME_TAC THENL
   [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* mv = ebv_in(ckp, f) *)
  SUBGOAL_THEN
    `?mv. mv IN D /\ (E:A->A->bool) mv B /\ ebv_in D E B leq ckp f mv`
    (X_CHOOSE_THEN `mv:A` STRIP_ASSUME_TAC) THENL
   [MATCH_MP_TAC EBV_IN_VAL_EXISTS THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* z' = emeet(pmv, ec) ; EBV_PM_SUBST_LE: z' <= mv *)
  SUBGOAL_THEN `(ec:A) IN D /\ (E:A->A->bool) ec B` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[EBV_EQ_IN_B]; ALL_TAC] THEN
  SUBGOAL_THEN `?zp. emeet D (E:A->A->bool) B leq pmv ec zp`
    (X_CHOOSE_TAC `zp:A`) THENL
   [MATCH_MP_TAC EBALG_MEET THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(zp:A) IN D /\ (E:A->A->bool) zp B` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[EMEET_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq zp mv` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`v2:num->A`;
                  `ss:A`;`vc:A`;
                  `cb:A`;`f:A`;`sing_c:A`;`pr_c:A`;`ckp:A`;`onebee:A`;`ec:A`;
                  `mv:A`;`zp:A`] EBV_PM_SUBST_LE) THEN
    ASM_REWRITE_TAC[] THEN EXPAND_TAC "pmv" THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  (* wc = emeet(b0, zp) by EMEET_ASSOC (b0,pmv,ec) *)
  SUBGOAL_THEN `?Rd. emeet D (E:A->A->bool) B leq b0 zp Rd`
    (X_CHOOSE_TAC `Rd:A`) THENL
   [MATCH_MP_TAC EBALG_MEET THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(Rd:A) IN D /\ (E:A->A->bool) Rd B` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[EMEET_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `(wc:A) = Rd` SUBST_ALL_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`b0:A`;
                  `pmv:A`;`ec:A`;
                  `bm:A`;`zp:A`;`wc:A`;`Rd:A`] EMEET_ASSOC) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* dd = emeet(b0,mv) ; Rd = emeet(b0,zp) <= dd by EMEET_MONO *)
  SUBGOAL_THEN `?dd. emeet D (E:A->A->bool) B leq b0 mv dd`
    (X_CHOOSE_TAC `dd:A`) THENL
   [MATCH_MP_TAC EBALG_MEET THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(dd:A) IN D /\ (E:A->A->bool) dd B` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[EMEET_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq Rd dd` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`b0:A`;`zp:A`;
                  `b0:A`;`mv:A`;
                  `Rd:A`;`dd:A`] EMEET_MONO) THEN ASM_REWRITE_TAC[] THEN
    MATCH_MP_TAC EPORDER_REFL THEN EXISTS_TAC `B:A` THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  (* ~ebot dd : from Rd <= dd and ~ebot Rd *)
  SUBGOAL_THEN `~ebot D (E:A->A->bool) B leq dd` ASSUME_TAC THENL
   [DISCH_TAC THEN
    SUBGOAL_THEN `(Rd:A) = dd` ASSUME_TAC THENL
     [MATCH_MP_TAC(ISPECL
                   [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`Rd:A`;`dd:A`]
                   ELE_BOT) THEN
      ASM_REWRITE_TAC[]; ALL_TAC] THEN
    UNDISCH_TAC `~ebot D (E:A->A->bool) B leq Rd` THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  (* covering clause *)
  MAP_EVERY EXISTS_TAC [`c:A`;`pnb:A`;`ckp:A`;`mv:A`;`dd:A`] THEN
  ASM_REWRITE_TAC[]);;

(* ===================================================================== *)
(* F7 / aleph_2-preservation forcing chain (2): fiber + no-surj + capstone. *)
(*   MEM_FIBRE_INJ (role-split: fiber INDEX om->dm, countability stays *)
(*   om; body verbatim) + NO_SURJ_NAME (keystone: a1 total->dm, each    *)
(*   dm-fiber >-> om, ~inj(a1,dm) ==> F; EMEMCOLLAPSE_EXISTS[om:=dm] +       *)
(*   MEM_FIBRE_INJ + COVER_ABSTRACT) + NO_ONTO_FUNC_NAME         *)
(*   (MEMVAL_FUNC_UNIFORM + M5_COVER + NO_SURJ_NAME) +               *)
(*   OMEGA2_NOT_COLLAPSED ([[ ?f. f : dm^(=aleph_1^) ->> a1^(=aleph_2^) ]]   *)
(*   = bot).  aleph_2 preserved: aleph_2^ not collapsed to aleph_1^.         *)
(* ===================================================================== *)
let MEM_FIBRE_INJ = prove
 (`!D (E:A->A->bool) P leqp B inclB bp onebee a1 om dm f b0 gg n.
     model D E ZF_AX /\ eleqp D E P leqp /\ eroset D E P leqp B /\
     eincl D E B inclB /\ ebplus D E B bp /\ ecba D E B inclB /\
     eccc D E bp inclB /\ B IN D /\
     (!u. u IN D ==> elmem D E u) /\
     onebee IN D /\ E onebee B /\ etop D E B inclB onebee /\
     a1 IN D /\ dm IN D /\ eomega D E om /\
     f IN D /\ bname D E B f /\ b0 IN D /\ E b0 B /\
     (!v. valuation D v /\ (!i. bname D E B (v i)) /\ v 72 = f
          ==> erel D E inclB b0 (bvalf D E B inclB v
                (?? 74 (!! 71
                        ((?? 73 (opair_form 70 71 73 && (73 %% 72))) -->
                         Eq 71 74))))) /\
     gg IN D /\
     (!u k. u IN D /\ k IN D
            ==> (eapply D E gg u k <=>
                 E u a1 /\ E k dm /\
                 ?pnb ckp mv dd. pnb IN D /\ ckp IN D /\ mv IN D /\ dd IN D /\
                    eopair D E k u pnb /\ echeck D E onebee pnb ckp /\
                    ebv_in D E B inclB ckp f mv /\
                      emeet D E B inclB b0 mv dd /\
                    ~ebot D E B inclB dd)) /\
     n IN D /\ E n dm
     ==> ?Wn e. Wn IN D /\
                (!u. u IN D ==> (E u Wn <=> E u a1 /\ eapply D E gg u n)) /\
                einj D E e Wn om`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `(inclB:A) IN D /\ (bp:A) IN D` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[eincl; ebplus]; ALL_TAC] THEN
  SUBGOAL_THEN `eporder D (E:A->A->bool) B inclB` ASSUME_TAC THENL
   [ASM_MESON_TAC[ECBA_IMP_BALG; EBALG_IMP_PORDER]; ALL_TAC] THEN
  SUBGOAL_THEN `(om:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[eomega; einductive]; ALL_TAC] THEN
  SUBGOAL_THEN `?bot:A. ebot D (E:A->A->bool) B inclB bot`
    (X_CHOOSE_TAC `bot:A`) THENL
   [MATCH_MP_TAC EBALG_BOT THEN ASM_MESON_TAC[ECBA_IMP_BALG]; ALL_TAC] THEN
  (* cn = n^ *)
  SUBGOAL_THEN `?cn. echeck D (E:A->A->bool) onebee n cn`
    (X_CHOOSE_TAC `cn:A`) THENL
   [ASM_MESON_TAC[ECHECK_EXHAUSTION]; ALL_TAC] THEN
  SUBGOAL_THEN `(cn:A) IN D /\ bname D (E:A->A->bool) B cn`
    STRIP_ASSUME_TAC THENL
   [CONJ_TAC THENL [ASM_MESON_TAC[ECHECK_IMP]; ALL_TAC] THEN
    MATCH_MP_TAC ECHECK_IS_BNAME THEN
    MAP_EVERY EXISTS_TAC [`onebee:A`; `n:A`] THEN ASM_MESON_TAC[ECHECK_IMP];
    ALL_TAC] THEN
  (* vn = (70|->cn)(\k. f) : all-bname, vn 70 = cn, vn 72 = f *)
  ABBREV_TAC `vn = (70 |-> (cn:A)) (\k:num. f:A)` THEN
  SUBGOAL_THEN
    `valuation D (vn:num->A) /\ (!i. bname D (E:A->A->bool) B ((vn:num->A) i))`
  STRIP_ASSUME_TAC THENL
   [EXPAND_TAC "vn" THEN CONJ_TAC THENL
     [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[valuation];
      MATCH_MP_TAC BNAMEVAL_VALMOD THEN ASM_REWRITE_TAC[]]; ALL_TAC] THEN
  SUBGOAL_THEN `(vn:num->A) 70 = cn /\ (vn:num->A) 72 = f`
  STRIP_ASSUME_TAC THENL
   [EXPAND_TAC "vn" THEN ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER; ARITH_EQ];
    ALL_TAC] THEN
  (* functionality at vn *)
  SUBGOAL_THEN
   `erel D (E:A->A->bool) inclB b0 (bvalf D E B inclB vn
      (?? 74 (!! 71
              ((?? 73 (opair_form 70 71 73 && (73 %% 72))) --> Eq 71 74))))`
  ASSUME_TAC THENL
  [FIRST_X_ASSUM MATCH_MP_TAC THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* Gn = value-name of f at cn *)
  MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `B:A`; `inclB:A`; `vn:num->A`]
    VALNAME_EXISTS) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `Gn:A` (CONJUNCTS_THEN2 ASSUME_TAC
    (CONJUNCTS_THEN2 (LABEL_TAC "Gbn") (LABEL_TAC "veq")))) THEN
  (* X = value-name fibre of Gn *)
  MP_TAC(ISPECL
         [`D:A->bool`; `E:A->A->bool`; `P:A`; `leqp:A`; `B:A`; `inclB:A`;
          `bp:A`; `onebee:A`; `a1:A`; `Gn:A`] FIBRE_COUNTABLE) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `X:A` (CONJUNCTS_THEN2 ASSUME_TAC
    (CONJUNCTS_THEN2 (LABEL_TAC "Xchar")
      (X_CHOOSE_THEN `om2:A` (X_CHOOSE_THEN `ee:A` STRIP_ASSUME_TAC))))) THEN
  SUBGOAL_THEN `om2:A = om` SUBST_ALL_TAC THENL
   [MATCH_MP_TAC EOMEGA_UNIQUE THEN
    MAP_EVERY EXISTS_TAC [`D:A->bool`; `E:A->A->bool`] THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  (* Wn = gg-fibre at n *)
  MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `a1:A`; `gg:A`; `n:A`]
         EGGFIBRE_EXISTS) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `Wn:A`
             (CONJUNCTS_THEN2 ASSUME_TAC (LABEL_TAC "Wchar"))) THEN
  (* Wn SUBSET X *)
  SUBGOAL_THEN `!u. u IN D /\ (E:A->A->bool) u Wn ==> E u X`
    (LABEL_TAC "sub") THENL
   [X_GEN_TAC `u:A` THEN STRIP_TAC THEN
    SUBGOAL_THEN `(E:A->A->bool) u a1 /\ eapply D E gg u n`
      STRIP_ASSUME_TAC THENL
      [ASM_MESON_TAC[]; ALL_TAC] THEN
    (* app-char at (u,n) : collapse data *)
    SUBGOAL_THEN
     `?pnb ckp mv dd. pnb IN D /\ ckp IN D /\ mv IN D /\ dd IN D /\
        eopair D (E:A->A->bool) n u pnb /\ echeck D E onebee pnb ckp /\
        ebv_in D E B inclB ckp f mv /\ emeet D E B inclB b0 mv dd /\
        ~ebot D E B inclB dd`
    STRIP_ASSUME_TAC THENL
     [FIRST_X_ASSUM(MP_TAC o SPECL [`u:A`; `n:A`]) THEN ASM_REWRITE_TAC[] THEN
      ASM_MESON_TAC[]; ALL_TAC] THEN
    (* cu = u^ *)
    SUBGOAL_THEN `?cu. echeck D (E:A->A->bool) onebee u cu`
      (X_CHOOSE_TAC `cu:A`) THENL
      [ASM_MESON_TAC[ECHECK_EXHAUSTION]; ALL_TAC] THEN
    (* ~(dd = bot) from ~ebot dd + ebot bot *)
    SUBGOAL_THEN `~(dd:A = bot)` ASSUME_TAC THENL
     [DISCH_THEN SUBST_ALL_TAC THEN ASM_MESON_TAC[]; ALL_TAC] THEN
    (* MEMVAL_COVER : [[Gn = cu]] =/= bot *)
    MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `B:A`; `inclB:A`; `onebee:A`;
      `vn:num->A`; `n:A`; `u:A`; `cn:A`; `cu:A`; `pnb:A`; `ckp:A`;
      `f:A`; `b0:A`;
      `mv:A`; `dd:A`; `bot:A`; `Gn:A`] MEMVAL_COVER) THEN
    ANTS_TAC THENL
     [REPEAT CONJ_TAC THEN TRY(FIRST_ASSUM ACCEPT_TAC) THEN
      ASM_MESON_TAC[EMEET_IN]; ALL_TAC] THEN
    DISCH_THEN(X_CHOOSE_THEN `zz:A` STRIP_ASSUME_TAC) THEN
    USE_THEN "Xchar" (fun th -> MP_TAC(SPEC `u:A` th)) THEN
    ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    CONJ_TAC THENL
     [FIRST_ASSUM ACCEPT_TAC;
      MAP_EVERY EXISTS_TAC [`cu:A`; `zz:A`] THEN ASM_REWRITE_TAC[]];
     ALL_TAC] THEN
  (* inject Wn into om by restricting ee -- extract ee IN D + the edge property
     from einj EXPLICITLY (ASM_MESON[einj] explodes on the
       injectivity clause) *)
  SUBGOAL_THEN `(ee:A) IN D` ASSUME_TAC THENL
   [UNDISCH_TAC `einj D (E:A->A->bool) ee X om` THEN
    REWRITE_TAC[einj] THEN STRIP_TAC THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN
   `!k t. k IN D /\ t IN D /\ E k Wn /\
    eapply D (E:A->A->bool) ee k t ==> E t om`
  ASSUME_TAC THENL
   [REPEAT GEN_TAC THEN STRIP_TAC THEN
    UNDISCH_TAC `einj D (E:A->A->bool) ee X om` THEN
    DISCH_THEN(MP_TAC o SPECL [`k:A`; `t:A`] o CONJUNCT1 o CONJUNCT2 o
              REWRITE_RULE[einj]) THEN
    ASM_REWRITE_TAC[] THEN STRIP_TAC THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MP_TAC(ISPECL
         [`D:A->bool`; `E:A->A->bool`; `ee:A`; `X:A`; `om:A`; `Wn:A`; `om:A`]
         EINJ_RESTRICT_DOM) THEN
  ANTS_TAC THENL
   [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `e2:A` ASSUME_TAC) THEN
  MAP_EVERY EXISTS_TAC [`Wn:A`; `e2:A`] THEN ASM_REWRITE_TAC[]);;

let NO_SURJ_NAME = prove
 (`!D (E:A->A->bool) P leqp B inclB bp onebee a1 om dm f b0.
     model D E ZF_AX /\ eleqp D E P leqp /\ eroset D E P leqp B /\
     eincl D E B inclB /\ ebplus D E B bp /\ ecba D E B inclB /\
     eccc D E bp inclB /\ B IN D /\
     (!u. u IN D ==> elmem D E u) /\
     onebee IN D /\ E onebee B /\ etop D E B inclB onebee /\
     a1 IN D /\ eomega D E om /\
     ecardinal D E dm /\ E om dm /\ dm IN D /\ ~(?e. einj D E e a1 dm) /\
     f IN D /\ bname D E B f /\ b0 IN D /\ E b0 B /\
     (!v. valuation D v /\ (!i. bname D E B (v i)) /\ v 72 = f
          ==> erel D E inclB b0 (bvalf D E B inclB v
                (?? 74 (!! 71
                        ((?? 73 (opair_form 70 71 73 && (73 %% 72))) -->
                         Eq 71 74))))) /\
     (!bet. bet IN D /\ E bet a1
            ==> ?n pnb ckp mv dd. n IN D /\ E n dm /\ pnb IN D /\ ckp IN D /\
                   mv IN D /\ dd IN D /\
                   eopair D E n bet pnb /\ echeck D E onebee pnb ckp /\
                   ebv_in D E B inclB ckp f mv /\ emeet D E B inclB b0 mv dd /\
                   ~ebot D E B inclB dd)
     ==> F`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `(inclB:A) IN D /\ (bp:A) IN D` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[eincl; ebplus]; ALL_TAC] THEN
  SUBGOAL_THEN `(om:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[eomega; einductive]; ALL_TAC] THEN
  (* gg = membership collapse relation *)
  MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `a1:A`; `dm:A`; `B:A`; `inclB:A`;
    `f:A`; `b0:A`; `onebee:A`] EMEMCOLLAPSE_EXISTS) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `gg:A`
             (CONJUNCTS_THEN2 ASSUME_TAC (LABEL_TAC "gg"))) THEN
  (* app-char *)
  SUBGOAL_THEN
   `!u k. u IN D /\ k IN D
          ==> (eapply D (E:A->A->bool) gg u k <=>
               E u a1 /\ E k dm /\
               ?pnb ckp mv dd. pnb IN D /\ ckp IN D /\ mv IN D /\ dd IN D /\
                  eopair D E k u pnb /\ echeck D E onebee pnb ckp /\
                  ebv_in D E B inclB ckp f mv /\ emeet D E B inclB b0 mv dd /\
                  ~ebot D E B inclB dd)`
  (LABEL_TAC "app") THENL
   [REPEAT GEN_TAC THEN STRIP_TAC THEN
    GEN_REWRITE_TAC LAND_CONV [eapply] THEN EQ_TAC THENL
     [DISCH_THEN(X_CHOOSE_THEN `q:A` STRIP_ASSUME_TAC) THEN
      SUBGOAL_THEN `(q:A) IN D` ASSUME_TAC THENL
       [ASM_MESON_TAC[EOPAIR_IN]; ALL_TAC] THEN
      USE_THEN "gg" (MP_TAC o SPEC `q:A`) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun bic ->
                 MP_TAC(EQ_MP bic (ASSUME `(E:A->A->bool) q gg`))) THEN
      DISCH_THEN(X_CHOOSE_THEN `bet:A` (X_CHOOSE_THEN `nn:A`
        (X_CHOOSE_THEN `pnb:A` (X_CHOOSE_THEN `ckp:A`
          (X_CHOOSE_THEN `mv:A`
           (X_CHOOSE_THEN `dd:A` STRIP_ASSUME_TAC)))))) THEN
      MP_TAC(ISPECL
             [`D:A->bool`; `E:A->A->bool`; `bet:A`; `nn:A`; `u:A`; `k:A`;
              `q:A`] EOPAIR_INJ) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(CONJUNCTS_THEN(SUBST_ALL_TAC o SYM)) THEN
      ASM_REWRITE_TAC[] THEN
      MAP_EVERY EXISTS_TAC [`pnb:A`; `ckp:A`; `mv:A`; `dd:A`] THEN
      ASM_REWRITE_TAC[];
      STRIP_TAC THEN
      MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `u:A`; `k:A`]
             EOPAIR_EXISTS) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(X_CHOOSE_THEN `q:A` ASSUME_TAC) THEN
      SUBGOAL_THEN `(q:A) IN D` ASSUME_TAC THENL
       [ASM_MESON_TAC[EOPAIR_IN]; ALL_TAC] THEN
      EXISTS_TAC `q:A` THEN ASM_REWRITE_TAC[] THEN
      USE_THEN "gg" (MP_TAC o SPEC `q:A`) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
      MAP_EVERY EXISTS_TAC
        [`u:A`; `k:A`; `pnb:A`; `ckp:A`; `mv:A`; `dd:A`] THEN
        ASM_REWRITE_TAC[]];
    ALL_TAC] THEN
  (* totality from covering *)
  SUBGOAL_THEN
   `!bet. bet IN D /\ E bet a1
          ==> ?n. n IN D /\ E n dm /\ eapply D (E:A->A->bool) gg bet n`
  ASSUME_TAC THENL
   [X_GEN_TAC `bt:A` THEN STRIP_TAC THEN
    SUBGOAL_THEN
     `?n pnb ckp mv dd. n IN D /\ E n dm /\ pnb IN D /\ ckp IN D /\
         mv IN D /\ dd IN D /\
         eopair D (E:A->A->bool) n bt pnb /\ echeck D E onebee pnb ckp /\
         ebv_in D E B inclB ckp f mv /\ emeet D E B inclB b0 mv dd /\
         ~ebot D E B inclB dd`
    STRIP_ASSUME_TAC THENL
     [FIRST_X_ASSUM MATCH_MP_TAC THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    EXISTS_TAC `n:A` THEN ASM_REWRITE_TAC[] THEN
    USE_THEN "app" (MP_TAC o SPECL [`bt:A`; `n:A`]) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN ASM_REWRITE_TAC[] THEN
    MAP_EVERY EXISTS_TAC [`pnb:A`; `ckp:A`; `mv:A`; `dd:A`] THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  (* per-n fibre via MEM_FIBRE_INJ *)
  SUBGOAL_THEN
   `!n. n IN D /\ E n dm
        ==> ?Wn e. Wn IN D /\
                   (!u. u IN D ==>
                    (E u Wn <=> E u a1 /\ eapply D (E:A->A->bool) gg u n)) /\
                   einj D E e Wn om`
  ASSUME_TAC THENL
   [X_GEN_TAC `n:A` THEN STRIP_TAC THEN
    MATCH_MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `P:A`; `leqp:A`; `B:A`;
      `inclB:A`; `bp:A`; `onebee:A`; `a1:A`; `om:A`; `dm:A`; `f:A`; `b0:A`;
      `gg:A`; `n:A`]
      MEM_FIBRE_INJ) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `om:A`; `dm:A`; `a1:A`; `gg:A`]
    COVER_ABSTRACT) THEN
  ASM_REWRITE_TAC[]);;

(* ==== NO_ONTO_FUNC_NAME (cardinal preservation core): no NONZERO condition b0
   forces a name f to be an ONTO FUNCTION from dm^ to a1^, when a1 does not
   inject into dm in the ground model.  Pure assembly of three lemmas:
     MEMVAL_FUNC_UNIFORM (m5-func): "b0 forces f a function" (b0 <=
       [[!! 70 sv]])
         ==> the per-valuation single-valuedness clause NO_SURJ_NAME wants.
     M5_COVER (m5-cover): "b0 forces f onto a1^ from dm^"
         (b0 <= [[!!- 71 68 (??- 70 69 pm)]]) ==>
           NO_SURJ_NAME's covering clause.
     NO_SURJ_NAME: functionality clause + covering clause ==> F (ccc counting).
   Order used throughout = inclB (the regular-open / Boolean
     inclusion order). *)

let NO_ONTO_FUNC_NAME = prove
 (`!D (E:A->A->bool) P leqp B inclB bp onebee a1 a1c om dm dmc f b0 v0.
      model D E ZF_AX /\ eleqp D E P leqp /\ eroset D E P leqp B /\
      eincl D E B inclB /\ ebplus D E B bp /\ ecba D E B inclB /\
      eccc D E bp inclB /\ B IN D /\
      (!u. u IN D ==> elmem D E u) /\
      onebee IN D /\ E onebee B /\ etop D E B inclB onebee /\
      a1 IN D /\ eomega D E om /\
      ecardinal D E dm /\ E om dm /\ dm IN D /\ ~(?e. einj D E e a1 dm) /\
      echeck D E onebee a1 a1c /\ echeck D E onebee dm dmc /\
      f IN D /\ bname D E B f /\ b0 IN D /\ E b0 B /\ ~ebot D E B inclB b0 /\
      valuation D v0 /\ (!i. bname D E B (v0 i)) /\
      v0 68 = a1c /\ v0 69 = dmc /\ v0 72 = f /\
      erel D E inclB b0 (bvalf D E B inclB v0
         (!! 70 (?? 74
                 (!! 71 ((?? 73 (opair_form 70 71 73 && (73 %% 72))) -->
                         Eq 71 74))))) /\
      erel D E inclB b0 (bvalf D E B inclB v0
         (!!- 71 68 (??- 70 69 (?? 73 (opair_form 70 71 73 && (73 %% 72))))))
      ==> F`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `(om:A) IN D /\ (inclB:A) IN D` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[eomega; einductive; eincl]; ALL_TAC] THEN
  (* functionality clause via MEMVAL_FUNC_UNIFORM *)
  MP_TAC(ISPECL
         [`D:A->bool`;`E:A->A->bool`;`B:A`;`inclB:A`;`v0:num->A`;`f:A`;`b0:A`]
         MEMVAL_FUNC_UNIFORM) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN DISCH_TAC THEN
  (* covering clause via M5_COVER *)
  MP_TAC(ISPECL
         [`D:A->bool`;`E:A->A->bool`;`B:A`;`inclB:A`;`onebee:A`;`a1:A`;`a1c:A`;
          `dm:A`;`dmc:A`;`f:A`;`b0:A`;`v0:num->A`] M5_COVER) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN DISCH_TAC THEN
  (* NO_SURJ_NAME closes it *)
  MP_TAC(ISPECL
         [`D:A->bool`;`E:A->A->bool`;`P:A`;`leqp:A`;`B:A`;`inclB:A`;`bp:A`;
          `onebee:A`;`a1:A`;`om:A`;`dm:A`;`f:A`;`b0:A`] NO_SURJ_NAME) THEN
  ASM_REWRITE_TAC[]);;

(* ==== OMEGA2_NOT_COLLAPSED: no collapse, as a BOOLEAN VALUE.  For a cardinal
   dm containing om into which a1 does not inject, the Boolean value of
     "?? f. (f is a function) /\ (f maps dm^ onto a1^)"
   is bot (v: slot 68 = a1^, 69 = dm^; 72 ranges over the existential).
   For each bname f the body-value b0 = emeet([[f fn]],[[f onto]])
   (BVALF_AND_MEET) is bot by NO_ONTO_FUNC_NAME; BVALF_EX_LEAST lifts this
   to [[?? 72 body]] <= bot. *)
let OMEGA2_NOT_COLLAPSED = prove
 (`!D (E:A->A->bool) P leqp B inclB bp onebee a1 a1c om dm dmc v bot.
      model D E ZF_AX /\ eleqp D E P leqp /\ eroset D E P leqp B /\
      eincl D E B inclB /\ ebplus D E B bp /\ ecba D E B inclB /\
      eccc D E bp inclB /\ B IN D /\
      (!u. u IN D ==> elmem D E u) /\
      onebee IN D /\ E onebee B /\ etop D E B inclB onebee /\
      a1 IN D /\ eomega D E om /\
      ecardinal D E dm /\ E om dm /\ dm IN D /\ ~(?e. einj D E e a1 dm) /\
      echeck D E onebee a1 a1c /\ echeck D E onebee dm dmc /\
      valuation D v /\ (!i. bname D E B (v i)) /\
      v 68 = a1c /\ v 69 = dmc /\
      ebot D E B inclB bot
      ==> bvalf D E B inclB v
            (?? 72 ((!! 70
                     (?? 74 (!! 71
                             ((?? 73 (opair_form 70 71 73 && (73 %% 72))) -->
                              Eq 71 74))))
                    && (!!- 71 68
                        (??- 70 69
                         (?? 73 (opair_form 70 71 73 && (73 %% 72)))))))
          = bot`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  ABBREV_TAC
   `body = (!! 70
            (?? 74 (!! 71
                    ((?? 73 (opair_form 70 71 73 && (73 %% 72))) -->
                     Eq 71 74))))
           && (!!- 71 68
               (??- 70 69 (?? 73 (opair_form 70 71 73 && (73 %% 72)))))` THEN
  SUBGOAL_THEN `ebalg D (E:A->A->bool) B inclB /\ eporder D E B inclB`
    STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[ECBA_IMP_BALG; EBALG_IMP_PORDER]; ALL_TAC] THEN
  SUBGOAL_THEN `(inclB:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[eincl]; ALL_TAC] THEN
  SUBGOAL_THEN `(bot:A) IN D /\ (E:A->A->bool) bot B` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[EBOT_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `(bvalf D (E:A->A->bool) B inclB v (?? 72 body)) IN D /\
                (E:A->A->bool) (bvalf D E B inclB v (?? 72 body)) B`
    STRIP_ASSUME_TAC THENL
   [CONJ_TAC THENL
     [MP_TAC(ISPECL
             [`?? 72 body`;`D:A->bool`;`E:A->A->bool`;`B:A`;
              `inclB:A`;`v:num->A`]
             BVALF_SPEC) THEN ASM_SIMP_TAC[];
      MP_TAC(ISPECL
             [`?? 72 body`;`D:A->bool`;`E:A->A->bool`;`B:A`;
              `inclB:A`;`v:num->A`]
             BVALF_IN_B) THEN ASM_SIMP_TAC[]]; ALL_TAC] THEN
  (* [[?? 72 body]] = bot via ELE_BOT + BVALF_EX_LEAST(w0:=bot) *)
  MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`inclB:A`;
    `bvalf D (E:A->A->bool) B inclB v (?? 72 body)`;`bot:A`] ELE_BOT) THEN
  ASM_REWRITE_TAC[] THEN
  MP_TAC(ISPECL
         [`72`;`body:form`;`D:A->bool`;`E:A->A->bool`;`B:A`;`inclB:A`;
          `v:num->A`;`bot:A`]
         BVALF_EX_LEAST) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN MATCH_MP_TAC THEN
  (* inner: !f bname. [[body]]_{(72|->f)v} <= bot *)
  X_GEN_TAC `f:A` THEN STRIP_TAC THEN
  ABBREV_TAC `v0 = (72 |-> f) (v:num->A)` THEN
  SUBGOAL_THEN `valuation D (v0:num->A) /\ (!i. bname D E B ((v0:num->A) i))`
    STRIP_ASSUME_TAC THENL
   [EXPAND_TAC "v0" THEN CONJ_TAC THENL
     [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[];
      MATCH_MP_TAC BNAMEVAL_VALMOD THEN ASM_REWRITE_TAC[]]; ALL_TAC] THEN
  SUBGOAL_THEN
    `(v0:num->A) 72 = f /\ (v0:num->A) 68 = a1c /\ (v0:num->A) 69 = dmc`
    STRIP_ASSUME_TAC THENL
   [EXPAND_TAC "v0" THEN ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER; ARITH_EQ];
    ALL_TAC] THEN
  (* emeet([[f fn]],[[f onto]]) (bvalf v0 body) *)
  SUBGOAL_THEN
   `emeet D (E:A->A->bool) B inclB
      (bvalf D E B inclB v0
         (!! 70 (?? 74
                 (!! 71 ((?? 73 (opair_form 70 71 73 && (73 %% 72))) -->
                         Eq 71 74)))))
      (bvalf D E B inclB v0
         (!!- 71 68 (??- 70 69 (?? 73 (opair_form 70 71 73 && (73 %% 72))))))
      (bvalf D E B inclB v0 body)`
    ASSUME_TAC THENL
   [EXPAND_TAC "body" THEN
    MP_TAC(ISPECL
           [`!! 70 (?? 74
                    (!! 71 ((?? 73 (opair_form 70 71 73 && (73 %% 72))) -->
                            Eq 71 74)))`;
            `!!- 71 68
             (??- 70 69 (?? 73 (opair_form 70 71 73 && (73 %% 72))))`;
      `D:A->bool`;`E:A->A->bool`;`B:A`;`inclB:A`;`v0:num->A`]
             BVALF_AND_MEET) THEN
    ASM_SIMP_TAC[]; ALL_TAC] THEN
  ABBREV_TAC `b0 = bvalf D (E:A->A->bool) B inclB v0 body` THEN
  SUBGOAL_THEN `(b0:A) IN D /\ (E:A->A->bool) b0 B` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[EMEET_IN]; ALL_TAC] THEN
  (* b0 = bot *)
  SUBGOAL_THEN `(b0:A) = bot` ASSUME_TAC THENL
   [ASM_CASES_TAC `(b0:A) = bot` THENL
     [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    SUBGOAL_THEN `~ebot D (E:A->A->bool) B inclB b0` ASSUME_TAC THENL
     [DISCH_TAC THEN
      SUBGOAL_THEN `(b0:A) = bot` ASSUME_TAC THENL
       [MATCH_MP_TAC(ISPECL
                     [`D:A->bool`;`E:A->A->bool`;`B:A`;`inclB:A`;
                      `b0:A`;`bot:A`]
                     EBOT_UNIQUE) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
      UNDISCH_TAC `~((b0:A) = bot)` THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN
     `erel D (E:A->A->bool) inclB b0
        (bvalf D E B inclB v0
           (!! 70 (?? 74
                   (!! 71 ((?? 73 (opair_form 70 71 73 && (73 %% 72))) -->
                           Eq 71 74))))) /\
      erel D (E:A->A->bool) inclB b0
        (bvalf D E B inclB v0
           (!!- 71 68
            (??- 70 69 (?? 73 (opair_form 70 71 73 && (73 %% 72))))))`
      STRIP_ASSUME_TAC THENL
     [ASM_MESON_TAC[EMEET_LE]; ALL_TAC] THEN
    MP_TAC(ISPECL
           [`D:A->bool`;`E:A->A->bool`;`P:A`;`leqp:A`;`B:A`;`inclB:A`;`bp:A`;
            `onebee:A`;`a1:A`;`a1c:A`;`om:A`;`dm:A`;`dmc:A`;`f:A`;`b0:A`;
            `v0:num->A`] NO_ONTO_FUNC_NAME) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* goal: erel inclB (bvalf v0 body) bot = erel inclB b0 bot ; b0=bot, refl *)
  ASM_REWRITE_TAC[] THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`inclB:A`;`bot:A`]
         EPORDER_REFL) THEN
  ASM_REWRITE_TAC[]);;

(* ===================================================================== *)
(* F7 (II) start: Cohen-real infrastructure.                             *)
(*   RO_POS_HAS_EMB (inhabited RO set w contains e(r0) SUBSET w -- the     *)
(*   distinctness glue) + ESING_BIJ_ONE (singleton {m} ~ 1 IN om, the     *)
(*   ecohenp-finiteness core) + COHEN_COORD_COND (II.1: {<c,v>} for        *)
(*   c IN ii, v IN tw is a Cohen condition E p1 P).                        *)
(* ===================================================================== *)
(* ==== F7 (II) infrastructure: RO_POS_HAS_EMB.
   An inhabited regular-open set w (w IN B, r0 IN w) CONTAINS the embedding of
   one of its conditions: e(r0) = eintcl(edownset r0) SUBSET w.  (=
     "positive RO
   element is above a basic embedding".)  This is the glue for the Cohen-real
   distinctness crux (II.4): if [[r_a=r_b]] =/= bot it contains
     e(r0); extend r0
   to split => contradiction.  w IN B = eroset => w SUBSET P /\
     open /\ regular,
   so r0 IN P and EMB_INTO_OPEN gives e(r0) SUBSET w. *)

let RO_POS_HAS_EMB = prove
 (`!D (E:A->A->bool) P leqp B w r0.
      model D E ZF_AX /\ P IN D /\ eleqp D E P leqp /\ eroset D E P leqp B /\
      w IN D /\ E w B /\ r0 IN D /\ E r0 w
      ==> ?dr er. E r0 P /\
                  edownset D E P leqp r0 dr /\ eintcl D E P leqp dr er /\
                  esubset D E er w`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `(leqp:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[eleqp]; ALL_TAC] THEN
  SUBGOAL_THEN
    `esubset D (E:A->A->bool) w P /\ eopen D E leqp w /\ ereg D E P leqp w`
    STRIP_ASSUME_TAC THENL
   [FIRST_ASSUM(fun th ->
                MP_TAC(SPEC `w:A` (CONJUNCT2 (REWRITE_RULE[eroset] th)))) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) (r0:A) (P:A)` ASSUME_TAC THENL
   [ASM_MESON_TAC[esubset]; ALL_TAC] THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`P:A`;`leqp:A`;`r0:A`]
         EDOWNSET_EXISTS) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `dr:A`) THEN
  SUBGOAL_THEN `(dr:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[edownset]; ALL_TAC] THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`P:A`;`leqp:A`;`dr:A`]
         EINTCL_EXISTS) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `er:A`) THEN
  MAP_EVERY EXISTS_TAC [`dr:A`;`er:A`] THEN ASM_REWRITE_TAC[] THEN
  MATCH_MP_TAC(ISPECL
               [`D:A->bool`;`E:A->A->bool`;`P:A`;`leqp:A`;`r0:A`;`dr:A`;
                `er:A`;`w:A`]
               EMB_INTO_OPEN) THEN ASM_REWRITE_TAC[]);;

(* ==== F7 (II.1): single-coordinate Cohen conditions. ====
   ESING_BIJ_ONE: a singleton {m} is equinumerous with 1 = suc(empty) IN om
   (EBIJ_EMPTY_ANY + EBIJ_ADJOIN).  The finiteness core for ecohenp membership.
   COHEN_COORD_COND: for c IN ii, v IN tw, the singleton {<c,v>} is a Cohen
   condition (E p1 P): SUBSET ci (ECROSS_MEMBER), efunctional (single pair,
   EOPAIR_INJ), finite (ESING_BIJ_ONE). *)

let ESING_BIJ_ONE = prove
 (`!D (E:A->A->bool) om m sm.
      model D E ZF_AX /\ eomega D E om /\ m IN D /\
      sm IN D /\ (!u. u IN D ==> (E u sm <=> u = m))
      ==> ?n g. n IN D /\ E n om /\ ebij D E g n sm`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `?z:A. eempty D (E:A->A->bool) z` (X_CHOOSE_TAC `z:A`) THENL
   [ASM_MESON_TAC[EEMPTY_EXISTS]; ALL_TAC] THEN
  SUBGOAL_THEN `(z:A) IN D /\ (!w. w IN D ==> ~((E:A->A->bool) w z))`
    STRIP_ASSUME_TAC THENL [ASM_MESON_TAC[eempty]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) z om` ASSUME_TAC THENL
   [ASM_MESON_TAC[EOMEGA_EMPTY]; ALL_TAC] THEN
  SUBGOAL_THEN `ebij D (E:A->A->bool) z z z` ASSUME_TAC THENL
   [MATCH_MP_TAC EBIJ_EMPTY_ANY THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `?n1:A. esuc D (E:A->A->bool) z n1` (X_CHOOSE_TAC `n1:A`) THENL
   [ASM_MESON_TAC[ESUC_EXISTS]; ALL_TAC] THEN
  SUBGOAL_THEN `(n1:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[ESUC_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) n1 om` ASSUME_TAC THENL
   [ASM_MESON_TAC[EOMEGA_SUC]; ALL_TAC] THEN
  SUBGOAL_THEN `?pr:A. eopair D (E:A->A->bool) z m pr`
    (X_CHOOSE_TAC `pr:A`) THENL
   [ASM_MESON_TAC[EOPAIR_EXISTS]; ALL_TAC] THEN
  SUBGOAL_THEN `(pr:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[EOPAIR_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `?f':A. eadjoin D (E:A->A->bool) z pr f'`
    (X_CHOOSE_TAC `f':A`) THENL
   [ASM_MESON_TAC[EADJOIN_EXISTS]; ALL_TAC] THEN
  SUBGOAL_THEN `(f':A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[EADJOIN_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `?y:A. eadjoin D (E:A->A->bool) z m y`
    (X_CHOOSE_TAC `y:A`) THENL
   [ASM_MESON_TAC[EADJOIN_EXISTS]; ALL_TAC] THEN
  SUBGOAL_THEN `(y:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[EADJOIN_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `ebij D (E:A->A->bool) f' n1 y` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`z:A`;`z:A`;`z:A`;`m:A`;`pr:A`;
                  `f':A`;`n1:A`;`y:A`] EBIJ_ADJOIN) THEN ASM_REWRITE_TAC[] THEN
    ASM_MESON_TAC[]; ALL_TAC] THEN
  (* y = sm by extensionality: both have single member m *)
  SUBGOAL_THEN `(y:A) = sm` SUBST_ALL_TAC THENL
   [FIRST_ASSUM(fun mth -> MATCH_MP_TAC(MATCH_MP ZF_EXTENSIONALITY mth)) THEN
    ASM_REWRITE_TAC[] THEN X_GEN_TAC `u:A` THEN DISCH_TAC THEN
    SUBGOAL_THEN `(E:A->A->bool) u y <=> u = m`
      (fun th -> ASM_MESON_TAC[th]) THEN
      MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`z:A`;`m:A`;`y:A`]
             EADJOIN_CHAR) THEN
    ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[]; ALL_TAC] THEN
  MAP_EVERY EXISTS_TAC [`n1:A`;`f':A`] THEN ASM_REWRITE_TAC[]);;

let COHEN_COORD_COND = prove
 (`!D (E:A->A->bool) ii tw ci om P c v.
      model D E ZF_AX /\ eomega D E om /\
      ecross D E ii tw ci /\ ecohenp D E ci om P /\
      c IN D /\ v IN D /\ E c ii /\ E v tw
      ==> ?cv p1. eopair D E c v cv /\ p1 IN D /\
                  (!u. u IN D ==> (E u p1 <=> u = cv)) /\ E p1 P`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `?cv:A. eopair D (E:A->A->bool) c v cv`
    (X_CHOOSE_TAC `cv:A`) THENL
   [ASM_MESON_TAC[EOPAIR_EXISTS]; ALL_TAC] THEN
  SUBGOAL_THEN `(cv:A) IN D` ASSUME_TAC THENL
  [ASM_MESON_TAC[EOPAIR_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) cv ci` ASSUME_TAC THENL
   [MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`ii:A`;`tw:A`;`ci:A`;`cv:A`]
           ECROSS_MEMBER) THEN
    ASM_REWRITE_TAC[] THEN DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    MAP_EVERY EXISTS_TAC [`c:A`;`v:A`] THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* p1 = {cv} via epair cv cv *)
  SUBGOAL_THEN `?p1:A. epair D (E:A->A->bool) cv cv p1`
    (X_CHOOSE_TAC `p1:A`) THENL
   [ASM_MESON_TAC[EPAIR_EXISTS]; ALL_TAC] THEN
  SUBGOAL_THEN `(p1:A) IN D` ASSUME_TAC THENL
  [ASM_MESON_TAC[EPAIR_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `!u. u IN D ==> ((E:A->A->bool) u p1 <=> u = cv)`
    (LABEL_TAC "p1ch") THENL
   [ASM_MESON_TAC[epair]; ALL_TAC] THEN
  MAP_EVERY EXISTS_TAC [`cv:A`;`p1:A`] THEN ASM_REWRITE_TAC[] THEN
  (* E p1 P via ecohenp: SUBSET ci, efunctional, finite *)
  FIRST_ASSUM(MP_TAC o SPEC `p1:A` o CONJUNCT2 o REWRITE_RULE[ecohenp]) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  REPEAT CONJ_TAC THENL
   [(* esubset p1 ci *)
    REWRITE_TAC[esubset] THEN X_GEN_TAC `u:A` THEN STRIP_TAC THEN
    SUBGOAL_THEN `u:A = cv` SUBST_ALL_TAC THENL
     [ASM_MESON_TAC[]; ALL_TAC] THEN FIRST_ASSUM ACCEPT_TAC;
    (* efunctional p1 *)
    REWRITE_TAC[efunctional] THEN
    MAP_EVERY X_GEN_TAC [`z:A`;`z':A`;`u:A`;`w:A`;`w':A`] THEN STRIP_TAC THEN
    SUBGOAL_THEN `z:A = cv /\ z':A = cv` STRIP_ASSUME_TAC THENL
     [ASM_MESON_TAC[]; ALL_TAC] THEN
    MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`u:A`;`w:A`;`c:A`;`v:A`;`cv:A`]
           EOPAIR_INJ) THEN
    MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`u:A`;`w':A`;`c:A`;`v:A`;`cv:A`]
           EOPAIR_INJ) THEN
    ASM_MESON_TAC[];
    (* finite: ESING_BIJ_ONE *)
    MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`om:A`;`cv:A`;`p1:A`]
           ESING_BIJ_ONE) THEN
    ASM_REWRITE_TAC[] THEN
    DISCH_THEN(X_CHOOSE_THEN `n:A` (X_CHOOSE_THEN `g:A` STRIP_ASSUME_TAC)) THEN
    EXISTS_TAC `n:A` THEN ASM_REWRITE_TAC[] THEN EXISTS_TAC `g:A` THEN
    ASM_REWRITE_TAC[]]);;

(* ===================================================================== *)
(* F7 (II) embedding infrastructure (toward II.2 COHEN_REALNAME).        *)
(*   COHEN_COORD_EMB (per-coord embedding value b=e(p1) IN B, p1 IN b) +  *)
(*   coordemb_form + COORDEMB_INNER_HOLDS + COORDEMB_HOLDS (the embedding- *)
(*   membership OBJECT FORM: q IN e({cv}) <=> !r<=q ?s<=r. cv IN s;        *)
(*   adapted from REG_INNER_HOLDS/REG_DENSE_HOLDS with membership reversed).*)
(* ===================================================================== *)
(* ==== F7 (II) toward II.2/II.3: COHEN_COORD_EMB.
   For a Cohen condition p1 (E p1 P), its regular-open embedding
   b = e(p1) = eintcl(edownset p1) is in B,
   contains p1 (so b =/= bot), and comes
   with its downset dp.  This is the per-entry VALUE b_{alpha,n} of
     the Cohen real
   name rdot_alpha = {<n^, b_{alpha,n}>}.  EDOWNSET_EXISTS + EINTCL_EXISTS
   + EINTCL_RO + EMB_NONBOT. *)

let COHEN_COORD_EMB = prove
 (`!D (E:A->A->bool) P leqp B p1.
      model D E ZF_AX /\ P IN D /\ eleqp D E P leqp /\ eroset D E P leqp B /\
      p1 IN D /\ E p1 P
      ==> ?dp ep. edownset D E P leqp p1 dp /\ eintcl D E P leqp dp ep /\
                  ep IN D /\ E ep B /\ E p1 ep`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `(leqp:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[eleqp]; ALL_TAC] THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`P:A`;`leqp:A`;`p1:A`]
         EDOWNSET_EXISTS) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `dp:A`) THEN
  SUBGOAL_THEN `(dp:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[edownset]; ALL_TAC] THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`P:A`;`leqp:A`;`dp:A`]
         EINTCL_EXISTS) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `ep:A`) THEN
  SUBGOAL_THEN `(ep:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[eintcl]; ALL_TAC] THEN
  MAP_EVERY EXISTS_TAC [`dp:A`;`ep:A`] THEN ASM_REWRITE_TAC[] THEN
  REPEAT CONJ_TAC THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`P:A`;`leqp:A`;
                         `dp:A`;`ep:A`;`B:A`] EINTCL_RO) THEN
    ASM_REWRITE_TAC[];
    MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`P:A`;`leqp:A`;`p1:A`;
                  `dp:A`;`ep:A`]
                 EMB_NONBOT) THEN ASM_REWRITE_TAC[]]);;

(* ==== F7 (II.2): the embedding-membership OBJECT FORM. ====
   coordemb_form (slots: 2=leqp order, 3=q tested elt, 0=cv coordinate pair):
     !! 4 (rel_form 2 4 3 --> ?? 5 (rel_form 2 5 4 && (0 %% 5)))
   holds  <=>  !r<=q. ?s<=r. cv IN s   ==   q IN e({cv}) (eintcl of the downset
   {s : cv IN s} = downset of the singleton condition {cv}).  Adapted from
   REG_INNER_HOLDS/REG_DENSE_HOLDS with the membership atom reversed
   (0 %% 5  i.e.  E (v 0) (v 5) = cv IN s, vs REG's 5 %% 0). *)

let coordemb_form = new_definition
  `coordemb_form = !! 4
   (rel_form 2 4 3 --> ?? 5 (rel_form 2 5 4 && (0 %% 5)))`;;

let COORDEMB_INNER_HOLDS = prove
 (`!D (E:A->A->bool) v.
      model D E ZF_AX /\ valuation D v
      ==> (holds D E v (?? 5 (rel_form 2 5 4 && (0 %% 5))) <=>
           ?s. s IN D /\ erel D E (v 2) s (v 4) /\ E (v 0) s)`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[HOLDS_EX] THEN
  SUBGOAL_THEN
   `!s:A. s IN D
      ==> (holds D E ((5 |-> s) v) (rel_form 2 5 4 && (0 %% 5)) <=>
           erel D E (v 2) s (v 4) /\ E (v 0) s)`
   (LABEL_TAC "body") THENL
   [REPEAT STRIP_TAC THEN
    SUBGOAL_THEN `valuation D ((5 |-> (s:A)) v)` ASSUME_TAC THENL
     [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
    REWRITE_TAC[HOLDS_AND; HOLDS_MEM] THEN
    MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`(5 |-> (s:A)) v`;`2`;`5`;`4`]
      HOLDS_REL_FORM) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    REWRITE_TAC[VALMOD; ARITH_EQ];
    ALL_TAC] THEN
  EQ_TAC THENL
   [DISCH_THEN(X_CHOOSE_THEN `s:A` (CONJUNCTS_THEN2 ASSUME_TAC MP_TAC)) THEN
    USE_THEN "body" (MP_TAC o SPEC `s:A`) THEN
    ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN STRIP_TAC THEN
    EXISTS_TAC `s:A` THEN ASM_REWRITE_TAC[];
    DISCH_THEN(X_CHOOSE_THEN `s:A` STRIP_ASSUME_TAC) THEN
    EXISTS_TAC `s:A` THEN CONJ_TAC THENL
     [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    USE_THEN "body" (MP_TAC o SPEC `s:A`) THEN
    ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN ASM_REWRITE_TAC[]]);;

let COORDEMB_HOLDS = prove
 (`!D (E:A->A->bool) v.
      model D E ZF_AX /\ valuation D v
      ==> (holds D E v coordemb_form <=>
           !q. q IN D /\ erel D E (v 2) q (v 3)
               ==> ?s. s IN D /\ erel D E (v 2) s q /\ E (v 0) s)`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[coordemb_form; HOLDS_ALL] THEN
  SUBGOAL_THEN
   `!q:A. q IN D
      ==> (holds D E ((4 |-> q) v)
             (rel_form 2 4 3 --> ?? 5 (rel_form 2 5 4 && (0 %% 5))) <=>
           (erel D E (v 2) q (v 3)
            ==> ?s. s IN D /\ erel D E (v 2) s q /\ E (v 0) s))`
   (LABEL_TAC "body") THENL
   [REPEAT STRIP_TAC THEN
    SUBGOAL_THEN `valuation D ((4 |-> (q:A)) v)` ASSUME_TAC THENL
     [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
    REWRITE_TAC[HOLDS_IMP] THEN
    MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`(4 |-> (q:A)) v`;`2`;`4`;`3`]
      HOLDS_REL_FORM) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`(4 |-> (q:A)) v`]
      COORDEMB_INNER_HOLDS) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    REWRITE_TAC[VALMOD; ARITH_EQ];
    ALL_TAC] THEN
  EQ_TAC THENL
   [DISCH_THEN(LABEL_TAC "lhs") THEN
    X_GEN_TAC `q:A` THEN STRIP_TAC THEN
    USE_THEN "lhs" (MP_TAC o SPEC `q:A`) THEN
    ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    USE_THEN "body" (MP_TAC o SPEC `q:A`) THEN
    ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    DISCH_THEN MATCH_MP_TAC THEN FIRST_ASSUM ACCEPT_TAC;
    DISCH_THEN(LABEL_TAC "sem") THEN
    X_GEN_TAC `q:A` THEN DISCH_TAC THEN
    USE_THEN "body" (MP_TAC o SPEC `q:A`) THEN
    ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    DISCH_TAC THEN
    USE_THEN "sem" (MP_TAC o SPEC `q:A`) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC]]);;

(* ===================================================================== *)
(* F7 (II.2) (C,D1-core): embedding connection + embedding-function       *)
(*   object form.  COORDEMB_EQ_EMB (E q (e(p1)) <=> coordemb, p1={cv}) +   *)
(*   + embfun_form + HOLDS_EMBFUN_FORM (holds <=> ?b. z=<cv,b> /\ b-is-the- *)
(*   coord-embedding; the nested !! q(q IN b<->coordemb) pin).             *)
(* ===================================================================== *)
(* ==== F7 (II.2)(C): COORDEMB_EQ_EMB -- the embedding e(p1) of the Cohen
   singleton p1={cv} satisfies the coordemb membership characterization:
     E q (eintcl(edownset p1))  <=>  !r<=q ?s<=r. cv IN s   (for q IN P).
   eintcl + edownset defs + ELEQP_EREL (s<=p1 => p1 SUBSET s)
   + ELEQP_EREL_INTRO (converse) + p1={cv} => (p1 SUBSET s <=> cv IN s). *)

let COORDEMB_EQ_EMB = prove
 (`!D (E:A->A->bool) P leqp cv p1 dp b q.
      model D E ZF_AX /\ eleqp D E P leqp /\
      cv IN D /\ p1 IN D /\ E p1 P /\ (!u. u IN D ==> (E u p1 <=> u = cv)) /\
      dp IN D /\ edownset D E P leqp p1 dp /\
      b IN D /\ eintcl D E P leqp dp b /\
      q IN D /\ E q P
      ==> (E q b <=>
           !r. r IN D /\ erel D E leqp r q
               ==> ?s. s IN D /\ erel D E leqp s r /\ E cv s)`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  (* dc: for s with s <= (anything), E s dp <=> cv IN s *)
  SUBGOAL_THEN
    `!s r:A. s IN D /\ erel D E leqp s r ==> ((E:A->A->bool) s dp <=> E cv s)`
    (LABEL_TAC "dc") THENL
   [REPEAT STRIP_TAC THEN
    SUBGOAL_THEN `(r:A) IN D` ASSUME_TAC THENL
     [ASM_MESON_TAC[EREL_IN]; ALL_TAC] THEN
    SUBGOAL_THEN `(E:A->A->bool) s P` ASSUME_TAC THENL
     [ASM_MESON_TAC[ELEQP_EREL]; ALL_TAC] THEN
    FIRST_ASSUM(MP_TAC o SPEC `s:A` o CONJUNCT2 o REWRITE_RULE[edownset]) THEN
    ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN ASM_REWRITE_TAC[] THEN
    EQ_TAC THENL
     [DISCH_TAC THEN
      MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`P:A`;`leqp:A`;`s:A`;`p1:A`]
             ELEQP_EREL) THEN
      ASM_REWRITE_TAC[] THEN STRIP_TAC THEN
      UNDISCH_TAC `esubset D (E:A->A->bool) p1 s` THEN
      REWRITE_TAC[esubset] THEN
      DISCH_THEN(MP_TAC o SPEC `cv:A`) THEN ASM_MESON_TAC[];
      DISCH_TAC THEN
      MATCH_MP_TAC(ISPECL
                   [`D:A->bool`;`E:A->A->bool`;`P:A`;`leqp:A`;`s:A`;`p1:A`]
                   ELEQP_EREL_INTRO) THEN
      ASM_REWRITE_TAC[] THEN REWRITE_TAC[esubset] THEN
      X_GEN_TAC `u:A` THEN STRIP_TAC THEN
      SUBGOAL_THEN `u:A = cv` SUBST_ALL_TAC THENL
       [ASM_MESON_TAC[]; ALL_TAC] THEN FIRST_ASSUM ACCEPT_TAC];
    ALL_TAC] THEN
  FIRST_ASSUM(MP_TAC o SPEC `q:A` o CONJUNCT2 o REWRITE_RULE[eintcl]) THEN
  ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN ASM_REWRITE_TAC[] THEN
  EQ_TAC THENL
   [DISCH_THEN(LABEL_TAC "main") THEN X_GEN_TAC `t:A` THEN STRIP_TAC THEN
    USE_THEN "main" (MP_TAC o SPEC `t:A`) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[];
      DISCH_THEN(X_CHOOSE_THEN `w:A` STRIP_ASSUME_TAC) THEN
      EXISTS_TAC `w:A` THEN ASM_REWRITE_TAC[] THEN
      USE_THEN "dc" (MP_TAC o SPECL [`w:A`;`t:A`]) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ASM_MESON_TAC[]]];
    DISCH_THEN(LABEL_TAC "main") THEN X_GEN_TAC `t:A` THEN STRIP_TAC THEN
    USE_THEN "main" (MP_TAC o SPEC `t:A`) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[];
      DISCH_THEN(X_CHOOSE_THEN `w:A` STRIP_ASSUME_TAC) THEN
      EXISTS_TAC `w:A` THEN ASM_REWRITE_TAC[] THEN
      USE_THEN "dc" (MP_TAC o SPECL [`w:A`;`t:A`]) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ASM_MESON_TAC[]]]]);;

(* ==== F7 (II.2)(D1): the embedding-function object form (P-GUARDED). ====
   embfun_form (slots 0=cv, 1=z, 2=leqp, 20=P; 9=b existential; coordemb 0-8):
     ?? 9 (opair_form 0 9 1 && !! 3 ((3 %% 9) <-> ((3 %% 20) &&
       coordemb_form)))
   holds <=> ?b. z=<cv,b> /\ (!q. q IN b <=> q IN P /\
     q IN e({cv})).  The q IN P
   GUARD is ESSENTIAL: without it, coordemb(q) is vacuously true for q NOTIN P
   (no r<=q), so b would be a proper class (all q NOTIN P), not a set -- making
   the form unsatisfiable.  With the guard b = {q IN P : coordemb} =
     e({cv}) IN B. *)

let embfun_form = new_definition
  `embfun_form =
     ?? 9 (opair_form 0 9 1 &&
           !! 3 ((3 %% 9) <-> ((3 %% 20) && coordemb_form)))`;;

let HOLDS_EMBFUN_FORM = prove
 (`!D (E:A->A->bool) v.
      model D E ZF_AX /\ valuation D v
      ==> (holds D E v embfun_form <=>
           ?b. b IN D /\ eopair D E (v 0) b (v 1) /\
               (!q. q IN D
                    ==> (E q b <=>
                         E q (v 20) /\
                         (!r. r IN D /\ erel D E (v 2) r q
                              ==> ?s. s IN D /\ erel D E (v 2) s r /\
                                E (v 0) s))))`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `!x. (v:num->A) x IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[valuation]; ALL_TAC] THEN
  REWRITE_TAC[embfun_form; HOLDS_EX] THEN
  SUBGOAL_THEN
   `!b:A. b IN D
      ==> (holds D E ((9 |-> b) v)
             (opair_form 0 9 1 &&
              !! 3 ((3 %% 9) <-> ((3 %% 20) && coordemb_form))) <=>
           eopair D E (v 0) b (v 1) /\
           (!q. q IN D
                ==> (E q b <=>
                     E q (v 20) /\
                     (!r. r IN D /\ erel D E (v 2) r q
                          ==> ?s. s IN D /\ erel D E (v 2) s r /\
                            E (v 0) s))))`
   (LABEL_TAC "body") THENL
   [X_GEN_TAC `b:A` THEN DISCH_TAC THEN
    SUBGOAL_THEN `valuation D ((9 |-> (b:A)) v)` ASSUME_TAC THENL
     [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
    SUBGOAL_THEN
     `holds D E ((9 |-> (b:A)) v) (opair_form 0 9 1) <=>
      eopair D E (v 0) b (v 1)`
     ASSUME_TAC THENL
     [ASM_SIMP_TAC[HOLDS_OPAIR_FORM] THEN
      ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER; ARITH_EQ]; ALL_TAC] THEN
    SUBGOAL_THEN
     `holds D E ((9 |-> (b:A)) v)
      (!! 3 ((3 %% 9) <-> ((3 %% 20) && coordemb_form))) <=>
      (!q. q IN D
           ==> (E q b <=>
                E q (v 20) /\
                (!r. r IN D /\ erel D E (v 2) r q
                     ==> ?s. s IN D /\ erel D E (v 2) s r /\ E (v 0) s)))`
     ASSUME_TAC THENL
     [REWRITE_TAC[HOLDS_ALL] THEN
      MATCH_MP_TAC FORALL_IMP_CONG THEN
      X_GEN_TAC `q:A` THEN DISCH_TAC THEN
      SUBGOAL_THEN `valuation D ((3 |-> (q:A)) ((9 |-> (b:A)) v))`
        ASSUME_TAC THENL
        [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
      REWRITE_TAC[HOLDS_IFF; HOLDS_AND; HOLDS_MEM] THEN
      MP_TAC(ISPECL
             [`D:A->bool`;`E:A->A->bool`;`(3 |-> (q:A)) ((9 |-> (b:A)) v)`]
             COORDEMB_HOLDS) THEN
      ASM_REWRITE_TAC[] THEN DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
      ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER; ARITH_EQ]; ALL_TAC] THEN
    REWRITE_TAC[HOLDS_AND] THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  EQ_TAC THENL
   [DISCH_THEN(X_CHOOSE_THEN `b:A` (CONJUNCTS_THEN2 ASSUME_TAC MP_TAC)) THEN
    USE_THEN "body" (MP_TAC o SPEC `b:A`) THEN
    ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN STRIP_TAC THEN
    EXISTS_TAC `b:A` THEN ASM_REWRITE_TAC[];
    DISCH_THEN(X_CHOOSE_THEN `b:A` STRIP_ASSUME_TAC) THEN
    EXISTS_TAC `b:A` THEN
    USE_THEN "body" (MP_TAC o SPEC `b:A`) THEN
    ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN ASM_REWRITE_TAC[]]);;

(* ==== F7 (II.2)(D1 finish): EMBFUN_EXISTS.  The coordinate->embedding
   function embf = {<cv, e({cv})> : cv IN ci} IN D, via ZF_REPLACEMENT over ci.
   embf's graph relates cv IN ci to b = e({cv}) = eintcl(edownset {cv}), the
   regular-open embedding of the Cohen singleton condition {cv};
   characterized by
   coordemb-membership (q IN b <=> q IN P /\ q IN e({cv})). *)

let EMBFUN_EXISTS = prove
 (`!D (E:A->A->bool) P leqp B ci om ii tw.
     model D E ZF_AX /\ eomega D E om /\
     ecross D E ii tw ci /\ ecohenp D E ci om P /\
     eleqp D E P leqp /\ eroset D E P leqp B /\
     leqp IN D /\ B IN D /\ ci IN D /\ P IN D
     ==> ?embf. embf IN D /\
                (!z. z IN D
                     ==> (E z embf <=>
                          ?cv b. cv IN D /\ b IN D /\
                            (E:A->A->bool) cv (ci:A) /\ eopair D E cv b z /\
                                 (!q. q IN D
                                      ==> (E q b <=>
                                           (E:A->A->bool) q (P:A) /\
                                           (!r. r IN D /\ erel D E leqp r q
                                                ==> ?s. s IN D /\
                                                  erel D E leqp s r /\
                                                        E cv s)))))`,
  REPEAT STRIP_TAC THEN
  ABBREV_TAC `vv = (2 |-> (leqp:A)) (\n:num. P:A)` THEN
  SUBGOAL_THEN `valuation D (vv:num->A)` ASSUME_TAC THENL
   [EXPAND_TAC "vv" THEN MATCH_MP_TAC VALUATION_VALMOD THEN CONJ_TAC THENL
     [REWRITE_TAC[valuation] THEN FIRST_ASSUM ACCEPT_TAC;
      FIRST_ASSUM ACCEPT_TAC];
    ALL_TAC] THEN
  SUBGOAL_THEN
    `(vv:num->A) 2 = leqp /\ (vv:num->A) 20 = P /\ (vv:num->A) 0 = P`
    STRIP_ASSUME_TAC THENL
   [EXPAND_TAC "vv" THEN REWRITE_TAC[VALMOD] THEN
    CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN REWRITE_TAC[]; ALL_TAC] THEN
  (* hc: the HOLDS_EMBFUN_FORM characterization at (1|->z)(0|->cv)vv *)
  SUBGOAL_THEN
   `!cv z:A. cv IN D /\ z IN D
      ==> (holds D E ((1 |-> z) ((0 |-> cv) vv)) embfun_form <=>
           ?b. b IN D /\ eopair D E cv b z /\
               (!q. q IN D
                    ==> (E q b <=>
                         (E:A->A->bool) q (P:A) /\
                         (!r. r IN D /\ erel D E leqp r q
                              ==> ?s. s IN D /\
                                erel D E leqp s r /\ E cv s))))`
   (LABEL_TAC "hc") THENL
   [MAP_EVERY X_GEN_TAC [`cv:A`; `z:A`] THEN STRIP_TAC THEN
    SUBGOAL_THEN `valuation D ((1 |-> (z:A)) ((0 |-> (cv:A)) vv))`
      ASSUME_TAC THENL
      [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
    MP_TAC(ISPECL
           [`D:A->bool`; `E:A->A->bool`; `(1 |-> (z:A)) ((0 |-> (cv:A)) vv)`]
           HOLDS_EMBFUN_FORM) THEN
    ASM_REWRITE_TAC[] THEN DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER; ARITH_EQ]; ALL_TAC] THEN
  (* the embedding value for cv IN ci : b0 = e({cv}), with the char *)
  SUBGOAL_THEN
   `!cv:A. cv IN D /\ (E:A->A->bool) cv (ci:A)
      ==> ?b. b IN D /\
              (!q. q IN D
                   ==> (E q b <=>
                        (E:A->A->bool) q (P:A) /\
                        (!r. r IN D /\ erel D E leqp r q
                             ==> ?s. s IN D /\ erel D E leqp s r /\ E cv s)))`
   (LABEL_TAC "val") THENL
   [X_GEN_TAC `cv:A` THEN STRIP_TAC THEN
    MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `ii:A`; `tw:A`; `ci:A`; `cv:A`]
      ECROSS_MEMBER) THEN
    ASM_REWRITE_TAC[] THEN
    DISCH_THEN(X_CHOOSE_THEN `c:A` (X_CHOOSE_THEN `w:A` STRIP_ASSUME_TAC)) THEN
    MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `ii:A`; `tw:A`; `ci:A`; `om:A`;
      `P:A`; `c:A`; `w:A`] COHEN_COORD_COND) THEN
    ASM_REWRITE_TAC[] THEN
    DISCH_THEN(X_CHOOSE_THEN `cv2:A`
               (X_CHOOSE_THEN `p1:A` STRIP_ASSUME_TAC)) THEN
    SUBGOAL_THEN `cv2:A = cv` SUBST_ALL_TAC THENL
     [ASM_MESON_TAC[EOPAIR_UNIQUE]; ALL_TAC] THEN
    MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `P:A`; `leqp:A`; `B:A`; `p1:A`]
      COHEN_COORD_EMB) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(X_CHOOSE_THEN `dp:A`
               (X_CHOOSE_THEN `b0:A` STRIP_ASSUME_TAC)) THEN
    SUBGOAL_THEN `(dp:A) IN D` ASSUME_TAC THENL
     [ASM_MESON_TAC[edownset]; ALL_TAC] THEN
    EXISTS_TAC `b0:A` THEN ASM_REWRITE_TAC[] THEN
    (* b0 SUBSET P (and open, regular) from eroset membership *)
    SUBGOAL_THEN `esubset D (E:A->A->bool) (b0:A) (P:A) /\
                  eopen D E leqp b0 /\ ereg D E P leqp b0`
      STRIP_ASSUME_TAC THENL
     [FIRST_ASSUM(fun th ->
                  MP_TAC(SPEC `b0:A`
                         (CONJUNCT2 (REWRITE_RULE[eroset] th)))) THEN
      ASM_REWRITE_TAC[]; ALL_TAC] THEN
    X_GEN_TAC `q:A` THEN DISCH_TAC THEN
    ASM_CASES_TAC `(E:A->A->bool) (q:A) (P:A)` THENL
     [MP_TAC(ISPECL
             [`D:A->bool`; `E:A->A->bool`; `P:A`; `leqp:A`; `cv:A`; `p1:A`;
              `dp:A`; `b0:A`; `q:A`] COORDEMB_EQ_EMB) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> ASM_REWRITE_TAC[th]);
      SUBGOAL_THEN `~((E:A->A->bool) (q:A) (b0:A))`
        (fun th -> ASM_REWRITE_TAC[th]) THEN
        ASM_MESON_TAC[esubset]];
    ALL_TAC] THEN
  (* apply ZF_REPLACEMENT with p = embfun_form, x=0, y=1, v=vv, a=ci *)
  FIRST_ASSUM(MP_TAC o SPECL
    [`embfun_form`; `0`; `1`; `vv:num->A`; `ci:A`] o MATCH_MP
      ZF_REPLACEMENT) THEN
  ANTS_TAC THENL
   [REWRITE_TAC[ARITH_EQ] THEN ASM_REWRITE_TAC[] THEN
    X_GEN_TAC `cv:A` THEN STRIP_TAC THEN
    USE_THEN "val" (MP_TAC o SPEC `cv:A`) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(X_CHOOSE_THEN `b0:A` STRIP_ASSUME_TAC) THEN
    SUBGOAL_THEN `?w0. eopair D (E:A->A->bool) cv b0 w0`
      (X_CHOOSE_TAC `w0:A`) THENL
      [MATCH_MP_TAC EOPAIR_EXISTS THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN `(w0:A) IN D` ASSUME_TAC THENL
    [ASM_MESON_TAC[EOPAIR_IN]; ALL_TAC] THEN
    EXISTS_TAC `w0:A` THEN ASM_REWRITE_TAC[] THEN X_GEN_TAC `w':A` THEN
    STRIP_TAC THEN
    USE_THEN "hc" (MP_TAC o SPECL [`cv:A`; `w':A`]) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(MP_TAC o C EQ_MP
               (ASSUME `holds D E ((1 |-> (w':A)) ((0 |-> (cv:A)) vv))
                        embfun_form`)) THEN
    DISCH_THEN(X_CHOOSE_THEN `b':A` STRIP_ASSUME_TAC) THEN
    SUBGOAL_THEN `b':A = b0` SUBST_ALL_TAC THENL
     [FIRST_ASSUM(MATCH_MP_TAC o MATCH_MP ZF_EXTENSIONALITY) THEN
      ASM_SIMP_TAC[]; ALL_TAC] THEN
    MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `cv:A`; `b0:A`; `w':A`; `w0:A`]
      EOPAIR_UNIQUE) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `embf:A`
             (CONJUNCTS_THEN2 ASSUME_TAC (LABEL_TAC "out"))) THEN
  EXISTS_TAC `embf:A` THEN ASM_REWRITE_TAC[] THEN
  X_GEN_TAC `z:A` THEN DISCH_TAC THEN
  USE_THEN "out" (MP_TAC o SPEC `z:A`) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  AP_TERM_TAC THEN ABS_TAC THEN
  ASM_CASES_TAC `(u:A) IN D` THENL
   [USE_THEN "hc" (MP_TAC o SPECL [`u:A`; `z:A`]) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    ASM_CASES_TAC `(E:A->A->bool) (u:A) (ci:A)` THEN ASM_REWRITE_TAC[];
    ASM_REWRITE_TAC[]]);;

(* ==== F7 (II.2)(D2): realname_form -- the object form of the canonical
   Cohen real name's membership relation.  rdot_alpha = {<n^,
   embf(<<alpha,n>,1>)>
   : n<om}.  Flat compound (opair x3 + echeck + apply), mirrors collapse_form.
   HARDCODED slots: n=0 (REPL domain), z=1 (REPL image); existentials sig=6,
   b=7, p15=<alpha,n>=8, cvs=<<alpha,n>,1>=9; params vON=10, sA(alpha)=11,
   s1(the "1" value)=12, embfs(embf)=13.  (All param slots clear of echeck's
   {2,3,4,49,50,51} and the existentials, so NO freshness hyps.) *)

let realname_form = new_definition
  `realname_form =
     ?? 6 (?? 7 (?? 8 (?? 9
        (opair_form 6 7 1 &&
         echeck_form 10 0 6 &&
         opair_form 11 0 8 &&
         opair_form 8 12 9 &&
         apply_form 13 9 7))))`;;

let HOLDS_REALNAME_FORM = prove
 (`!D (E:A->A->bool) v.
      model D E ZF_AX /\ valuation D v
      ==> (holds D E v realname_form <=>
           ?sig b p15 cvs.
                sig IN D /\ b IN D /\ p15 IN D /\ cvs IN D /\
                eopair D E sig b (v 1) /\
                echeck D E (v 10) (v 0) sig /\
                eopair D E (v 11) (v 0) p15 /\
                eopair D E p15 (v 12) cvs /\
                eapply D E (v 13) cvs b)`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `!x. (v:num->A) x IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[valuation]; ALL_TAC] THEN
  REWRITE_TAC[realname_form] THEN
  SUBGOAL_THEN
   `!sig b p15 cvs:A.
      sig IN D /\ b IN D /\ p15 IN D /\ cvs IN D
      ==> (holds D E
           ((9 |-> (cvs:A))
            ((8 |-> (p15:A)) ((7 |-> (b:A)) ((6 |-> (sig:A)) v))))
           (opair_form 6 7 1 && echeck_form 10 0 6 && opair_form 11 0 8 &&
              opair_form 8 12 9 && apply_form 13 9 7) <=>
           eopair D E sig b (v 1) /\
           echeck D E (v 10) (v 0) sig /\
           eopair D E (v 11) (v 0) p15 /\
           eopair D E p15 (v 12) cvs /\
           eapply D E (v 13) cvs b)`
  (LABEL_TAC "body") THENL
   [REPEAT GEN_TAC THEN STRIP_TAC THEN
    SUBGOAL_THEN
      `valuation D
       ((9 |-> (cvs:A)) ((8 |-> (p15:A)) ((7 |-> (b:A)) ((6 |-> (sig:A)) v))))`
    ASSUME_TAC THENL [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
    SUBGOAL_THEN
     `holds D E
      ((9 |-> (cvs:A)) ((8 |-> (p15:A)) ((7 |-> (b:A)) ((6 |-> (sig:A)) v))))
        (opair_form 6 7 1) <=> eopair D E sig b (v 1)`
    ASSUME_TAC THENL
     [ASM_SIMP_TAC[HOLDS_OPAIR_FORM] THEN
      ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER; ARITH_EQ]; ALL_TAC] THEN
    SUBGOAL_THEN
     `holds D E
      ((9 |-> (cvs:A)) ((8 |-> (p15:A)) ((7 |-> (b:A)) ((6 |-> (sig:A)) v))))
        (echeck_form 10 0 6) <=> echeck D E (v 10) (v 0) sig`
    ASSUME_TAC THENL
     [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
        `((9 |-> (cvs:A))
          ((8 |-> (p15:A)) ((7 |-> (b:A)) ((6 |-> (sig:A)) v))))`;
        `10`; `0`; `6`] HOLDS_ECHECK_FORM) THEN
      ASM_REWRITE_TAC[ARITH_RULE
        `~(10 = 2) /\ ~(10 = 3) /\ ~(10 = 4) /\ ~(10 = 49) /\ ~(10 = 50) /\
         ~(10 = 51) /\ ~(0 = 2) /\ ~(0 = 3) /\ ~(0 = 4) /\ ~(0 = 49) /\
         ~(0 = 50) /\ ~(0 = 51) /\ ~(6 = 2) /\ ~(6 = 3) /\ ~(6 = 4) /\
         ~(6 = 49) /\ ~(6 = 50) /\ ~(6 = 51)`] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
      ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER; ARITH_EQ]; ALL_TAC] THEN
    SUBGOAL_THEN
     `holds D E
      ((9 |-> (cvs:A)) ((8 |-> (p15:A)) ((7 |-> (b:A)) ((6 |-> (sig:A)) v))))
        (opair_form 11 0 8) <=> eopair D E (v 11) (v 0) p15`
    ASSUME_TAC THENL
     [ASM_SIMP_TAC[HOLDS_OPAIR_FORM] THEN
      ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER; ARITH_EQ]; ALL_TAC] THEN
    SUBGOAL_THEN
     `holds D E
      ((9 |-> (cvs:A)) ((8 |-> (p15:A)) ((7 |-> (b:A)) ((6 |-> (sig:A)) v))))
        (opair_form 8 12 9) <=> eopair D E p15 (v 12) cvs`
    ASSUME_TAC THENL
     [ASM_SIMP_TAC[HOLDS_OPAIR_FORM] THEN
      ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER; ARITH_EQ]; ALL_TAC] THEN
    SUBGOAL_THEN
     `holds D E
      ((9 |-> (cvs:A)) ((8 |-> (p15:A)) ((7 |-> (b:A)) ((6 |-> (sig:A)) v))))
        (apply_form 13 9 7) <=> eapply D E (v 13) cvs b`
    ASSUME_TAC THENL
     [ASM_SIMP_TAC[HOLDS_APPLY_FORM] THEN
      ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER; ARITH_EQ]; ALL_TAC] THEN
    REWRITE_TAC[HOLDS_AND] THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  REWRITE_TAC[HOLDS_EX] THEN EQ_TAC THENL
   [INTRO_TAC "@sig. sigD @b. bD @p15. p15D @cvs. cvsD h" THEN
    SUBGOAL_THEN
     `eopair D (E:A->A->bool) sig b (v 1) /\
      echeck D E (v 10) (v 0) sig /\
      eopair D E (v 11) (v 0) p15 /\
      eopair D E p15 (v 12) cvs /\
      eapply D E (v 13) cvs b`
    STRIP_ASSUME_TAC THENL
     [USE_THEN "body" (MP_TAC o SPECL [`sig:A`; `b:A`; `p15:A`; `cvs:A`]) THEN
      ANTS_TAC THENL
       [ASM_REWRITE_TAC[];
        DISCH_THEN(fun th -> REWRITE_TAC[GSYM th]) THEN
        FIRST_ASSUM ACCEPT_TAC];
      ALL_TAC] THEN
    MAP_EVERY EXISTS_TAC [`sig:A`; `b:A`; `p15:A`; `cvs:A`] THEN
    ASM_REWRITE_TAC[];
    DISCH_THEN(X_CHOOSE_THEN `sig:A` (X_CHOOSE_THEN `b:A`
      (X_CHOOSE_THEN `p15:A` (X_CHOOSE_THEN `cvs:A` STRIP_ASSUME_TAC)))) THEN
    EXISTS_TAC `sig:A` THEN CONJ_TAC THENL
    [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    EXISTS_TAC `b:A` THEN CONJ_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    EXISTS_TAC `p15:A` THEN CONJ_TAC THENL
    [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    EXISTS_TAC `cvs:A` THEN CONJ_TAC THENL
    [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    USE_THEN "body" (MP_TAC o SPECL [`sig:A`; `b:A`; `p15:A`; `cvs:A`]) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[];
      DISCH_THEN(fun th -> ONCE_REWRITE_TAC[th]) THEN ASM_REWRITE_TAC[]]]);;

(* ==== F7 (II.5) helper: EMEM_CHAR_UNIQUE -- two sets with the SAME membership
   characterization are equal (extensionality from a shared predicate R).  This
   discharges the UNIQUENESS half of the REPLACEMENT that builds the internal
   function realfn = {<alpha,
   rdot_alpha> : alpha < aleph2} (COHEN_REALNAME_EXISTS
   gives existence; this gives y-uniqueness, since rdot_alpha is pinned by its
   membership char).  General-purpose. *)

let EMEM_CHAR_UNIQUE = prove
 (`!D (E:A->A->bool) a b R.
      model D E ZF_AX /\ a IN D /\ b IN D /\
      (!z. z IN D ==> (E z a <=> R z)) /\
      (!z. z IN D ==> (E z b <=> R z))
      ==> a = b`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`a:A`;`b:A`]
               ESUBSET_ANTISYM) THEN
  ASM_REWRITE_TAC[esubset] THEN ASM_MESON_TAC[]);;

(* ==== F7 (II.5 / F-build F3) REALFN_ISFUN -- the internal function realfn
   (char from REALFN_EXISTS) is single-valued (eisfun).  Every
     element is a pair
   <a,Y>; single-valued because Y is pinned by its membership char
     (EMEM_CHAR_UNIQUE).
   Stated abstractly over the value-predicate R a z. *)

let REALFN_ISFUN = prove
 (`!D (E:A->A->bool) realfn iibase R.
     model D E ZF_AX /\ realfn IN D /\
     (!w. w IN D ==>
          (E w realfn <=>
           ?a Y. a IN D /\ Y IN D /\ (E:A->A->bool) a iibase /\
             eopair D E a Y w /\
                 (!z. z IN D ==> (E z Y <=> R a z))))
     ==> eisfun D E realfn`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  FIRST_X_ASSUM(LABEL_TAC "ch" o check
                (fun th -> is_forall(concl th) &&
                 vfree_in `realfn:A` (concl th))) THEN
  REWRITE_TAC[eisfun] THEN REPEAT CONJ_TAC THENL
   [FIRST_ASSUM ACCEPT_TAC;
    X_GEN_TAC `z:A` THEN STRIP_TAC THEN
    USE_THEN "ch" (MP_TAC o SPEC `z:A`) THEN ANTS_TAC THENL
    [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun eq ->
               MP_TAC(EQ_MP eq (ASSUME `(E:A->A->bool) z realfn`))) THEN
    DISCH_THEN(X_CHOOSE_THEN `a:A` (X_CHOOSE_THEN `Y:A` STRIP_ASSUME_TAC)) THEN
    MAP_EVERY EXISTS_TAC [`a:A`;`Y:A`] THEN ASM_REWRITE_TAC[];
    MAP_EVERY X_GEN_TAC [`u:A`;`w:A`;`w':A`;`z:A`;`z':A`] THEN STRIP_TAC THEN
    SUBGOAL_THEN `(z:A) IN D /\ (z':A) IN D` STRIP_ASSUME_TAC THENL
     [ASM_MESON_TAC[EOPAIR_IN]; ALL_TAC] THEN
    USE_THEN "ch" (MP_TAC o SPEC `z:A`) THEN ANTS_TAC THENL
    [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun eq ->
               MP_TAC(EQ_MP eq (ASSUME `(E:A->A->bool) z realfn`))) THEN
    DISCH_THEN(X_CHOOSE_THEN `a1:A`
               (X_CHOOSE_THEN `Y1:A` STRIP_ASSUME_TAC)) THEN
    USE_THEN "ch" (MP_TAC o SPEC `z':A`) THEN ANTS_TAC THENL
    [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun eq ->
               MP_TAC(EQ_MP eq (ASSUME `(E:A->A->bool) z' realfn`))) THEN
    DISCH_THEN(X_CHOOSE_THEN `a2:A`
               (X_CHOOSE_THEN `Y2:A` STRIP_ASSUME_TAC)) THEN
    (* u = a1, w = Y1 from eopair u w z & eopair a1 Y1 z *)
    MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`u:A`;`w:A`;`a1:A`;`Y1:A`;`z:A`]
           EOPAIR_INJ) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(CONJUNCTS_THEN SUBST_ALL_TAC) THEN
    MP_TAC(ISPECL
           [`D:A->bool`;`E:A->A->bool`;`a1:A`;`w':A`;`a2:A`;`Y2:A`;`z':A`]
           EOPAIR_INJ) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(CONJUNCTS_THEN SUBST_ALL_TAC) THEN
    (* now goal Y1 = Y2 (w=Y1, w'=Y2), both have char R a1 *)
    MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`Y1:A`;`Y2:A`;`(R:A->A->bool) a2`]
                 EMEM_CHAR_UNIQUE) THEN
    REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC]);;

(* ==== EMBF_ISFUN: the embedding-function graph embf is a function
   (eisfun), from its membership characterization; an instance of
   REALFN_ISFUN.  Needed for EAPPLY_UNIQUE in COHEN_REALNAME_EXISTS. *)

let EMBF_ISFUN = prove
 (`!D (E:A->A->bool) P leqp ci embf.
     model D E ZF_AX /\ embf IN D /\
     (!z. z IN D
          ==> (E z embf <=>
               ?cv b. cv IN D /\ b IN D /\ (E:A->A->bool) cv (ci:A) /\
                      eopair D E cv b z /\
                      (!q. q IN D
                           ==> (E q b <=>
                                (E:A->A->bool) q (P:A) /\
                                (!r. r IN D /\ erel D E leqp r q
                                     ==> ?s. s IN D /\
                                       erel D E leqp s r /\ E cv s)))))
     ==> eisfun D E embf`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  MATCH_MP_TAC(ISPECL
   [`D:A->bool`; `E:A->A->bool`; `embf:A`; `ci:A`;
    `\cv q:A. (E:A->A->bool) q P /\
              (!r. r IN D /\ erel D E leqp r q
                   ==> ?s. s IN D /\ erel D E leqp s r /\ E cv s)`]
   REALFN_ISFUN) THEN
  ASM_REWRITE_TAC[] THEN FIRST_ASSUM ACCEPT_TAC);;

(* ==== F7 (II.2)(D2 collection): COHEN_REALNAME_EXISTS.  The canonical
   Cohen real name rdot_alpha = {<n^, embf(<<alpha,n>,1>)> : n<om} IN D, via
   ZF_REPLACEMENT over om with realname_form.  Abstract embf (graph
     char + eapply-
   totality as hyps; eisfun via EMBF_ISFUN).  V=L hyp (!u. elmem u) for echeck
   existence.  Mirror of EMBFUN_EXISTS. *)

let COHEN_REALNAME_EXISTS = prove
 (`!D (E:A->A->bool) P leqp ci om ON embf iibase ii tw alpha onetw.
     model D E ZF_AX /\ (!u:A. u IN D ==> elmem D E u) /\
     eomega D E om /\ ON IN D /\ embf IN D /\
     (!z. z IN D
          ==> (E z embf <=>
               ?cv b. cv IN D /\ b IN D /\ (E:A->A->bool) cv (ci:A) /\
                      eopair D E cv b z /\
                      (!q. q IN D
                           ==> (E q b <=>
                                (E:A->A->bool) q (P:A) /\
                                (!r. r IN D /\ erel D E leqp r q
                                     ==> ?s. s IN D /\ erel D E leqp s r /\
                                       E cv s))))) /\
     (!cvs. cvs IN D /\ (E:A->A->bool) cvs (ci:A) ==> ?b. b IN D /\
      eapply D E embf cvs b) /\
     ecross D E iibase om ii /\ ecross D E ii tw ci /\
     alpha IN D /\ (E:A->A->bool) alpha iibase /\ onetw IN D /\
       (E:A->A->bool) onetw tw
     ==> ?rdot. rdot IN D /\
                (!z. z IN D
                     ==> (E z rdot <=>
                          ?n sig b p15 cvs. n IN D /\ sig IN D /\
                            b IN D /\ p15 IN D /\
                              cvs IN D /\ (E:A->A->bool) n (om:A) /\
                              echeck D E ON n sig /\ eopair D E alpha n p15 /\
                              eopair D E p15 onetw cvs /\
                                eapply D E embf cvs b /\
                              eopair D E sig b z))`,
  REPEAT GEN_TAC THEN
  (* break the 14-conjunct hyp WITHOUT REWRITE[IMP_CONJ] -- the
    latter would also
     curry the inner `r IN D /\ erel ... ==>` inside the graph char,
     breaking the
     ACCEPT/match of "graph" against EMBF_ISFUN's hyp. *)
  INTRO_TAC "zf h omom OND embfD graph etot crossii crossci alphaD \
             alphaiibase onetwD onetwtw" THEN
  SUBGOAL_THEN `(om:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[EOMEGA_IN]; ALL_TAC] THEN
  (* eisfun embf, for apply-uniqueness *)
  SUBGOAL_THEN `eisfun D (E:A->A->bool) embf` ASSUME_TAC THENL
   [MP_TAC(ISPECL
           [`D:A->bool`; `E:A->A->bool`; `P:A`; `leqp:A`; `ci:A`; `embf:A`]
           EMBF_ISFUN) THEN ANTS_TAC THENL
     [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; DISCH_THEN ACCEPT_TAC];
    ALL_TAC] THEN
  ABBREV_TAC `vv = (13 |-> (embf:A)) ((12 |-> (onetw:A))
                     ((11 |-> (alpha:A))
                      ((10 |-> (ON:A)) (\k:num. ON:A))))` THEN
  SUBGOAL_THEN `valuation D (vv:num->A)` ASSUME_TAC THENL
   [EXPAND_TAC "vv" THEN
    REPEAT(MATCH_MP_TAC VALUATION_VALMOD THEN
           CONJ_TAC THENL [ALL_TAC; FIRST_ASSUM ACCEPT_TAC]) THEN
    REWRITE_TAC[valuation] THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN
   `(vv:num->A) 10 = ON /\ (vv:num->A) 11 = alpha /\
    (vv:num->A) 12 = onetw /\ (vv:num->A) 13 = embf`
    STRIP_ASSUME_TAC THENL
   [EXPAND_TAC "vv" THEN REPEAT CONJ_TAC THEN
    ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER; ARITH_EQ]; ALL_TAC] THEN
  (* hc: HOLDS_REALNAME_FORM at (1|->z)((0|->n)vv) *)
  SUBGOAL_THEN
   `!n z:A. n IN D /\ z IN D
      ==> (holds D E ((1 |-> z) ((0 |-> n) vv)) realname_form <=>
           ?sig b p15 cvs. sig IN D /\ b IN D /\ p15 IN D /\ cvs IN D /\
              eopair D E sig b z /\ echeck D E ON n sig /\
              eopair D E alpha n p15 /\ eopair D E p15 onetw cvs /\
              eapply D E embf cvs b)`
   (LABEL_TAC "hc") THENL
   [MAP_EVERY X_GEN_TAC [`n:A`; `z:A`] THEN STRIP_TAC THEN
    SUBGOAL_THEN `valuation D ((1 |-> (z:A)) ((0 |-> (n:A)) vv))`
      ASSUME_TAC THENL
      [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
    MP_TAC(ISPECL
           [`D:A->bool`; `E:A->A->bool`; `(1 |-> (z:A)) ((0 |-> (n:A)) vv)`]
           HOLDS_REALNAME_FORM) THEN
    ASM_REWRITE_TAC[] THEN DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER; ARITH_EQ]; ALL_TAC] THEN
  (* val: for n IN om, the witness pair z = <n^, embf(<<alpha,n>,1>)> exists *)
  SUBGOAL_THEN
   `!n:A. n IN D /\ (E:A->A->bool) n (om:A)
      ==> ?z. z IN D /\
              ?sig b p15 cvs. sig IN D /\ b IN D /\ p15 IN D /\ cvs IN D /\
                 eopair D E sig b z /\ echeck D E ON n sig /\
                 eopair D E alpha n p15 /\ eopair D E p15 onetw cvs /\
                 eapply D E embf cvs b`
   (LABEL_TAC "val") THENL
   [X_GEN_TAC `n:A` THEN STRIP_TAC THEN
    (* n^ *)
    MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `ON:A`; `n:A`]
           ECHECK_EXHAUSTION) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(X_CHOOSE_THEN `sig:A` (LABEL_TAC "sg")) THEN
    SUBGOAL_THEN `(sig:A) IN D` ASSUME_TAC THENL
     [ASM_MESON_TAC[ECHECK_IMP]; ALL_TAC] THEN
    (* p15 = <alpha,n> *)
    MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `alpha:A`; `n:A`]
           EOPAIR_EXISTS) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(X_CHOOSE_THEN `p15:A` (LABEL_TAC "p15")) THEN
    SUBGOAL_THEN `(p15:A) IN D` ASSUME_TAC THENL
     [ASM_MESON_TAC[EOPAIR_IN]; ALL_TAC] THEN
    (* cvs = <p15,onetw> *)
    MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `p15:A`; `onetw:A`]
           EOPAIR_EXISTS) THEN
    ANTS_TAC THENL [ASM_MESON_TAC[EOPAIR_IN]; ALL_TAC] THEN
    DISCH_THEN(X_CHOOSE_THEN `cvs:A` (LABEL_TAC "cvs")) THEN
    SUBGOAL_THEN `(cvs:A) IN D` ASSUME_TAC THENL
     [ASM_MESON_TAC[EOPAIR_IN]; ALL_TAC] THEN
    (* E p15 ii, E cvs ci via ecross *)
    SUBGOAL_THEN `(E:A->A->bool) p15 ii` ASSUME_TAC THENL
     [MP_TAC(ISPECL
             [`D:A->bool`; `E:A->A->bool`; `iibase:A`; `om:A`; `ii:A`; `p15:A`]
             ECROSS_MEMBER) THEN
      ASM_SIMP_TAC[EOPAIR_IN] THEN DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
      MAP_EVERY EXISTS_TAC [`alpha:A`; `n:A`] THEN
      ASM_MESON_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN `(E:A->A->bool) cvs ci` ASSUME_TAC THENL
     [MP_TAC(ISPECL
             [`D:A->bool`; `E:A->A->bool`; `ii:A`; `tw:A`; `ci:A`; `cvs:A`]
             ECROSS_MEMBER) THEN
      ASM_SIMP_TAC[EOPAIR_IN] THEN DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
      MAP_EVERY EXISTS_TAC [`p15:A`; `onetw:A`] THEN
      ASM_MESON_TAC[]; ALL_TAC] THEN
    (* b = embf(cvs) via eapply-totality *)
    USE_THEN "etot" (MP_TAC o SPEC `cvs:A`) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(X_CHOOSE_THEN `b:A` (LABEL_TAC "bb")) THEN
    (* z = <sig,b> *)
    MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `sig:A`; `b:A`]
           EOPAIR_EXISTS) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(X_CHOOSE_THEN `z:A` (LABEL_TAC "zz")) THEN
    SUBGOAL_THEN `(z:A) IN D` ASSUME_TAC THENL
     [ASM_MESON_TAC[EOPAIR_IN]; ALL_TAC] THEN
    EXISTS_TAC `z:A` THEN ASM_REWRITE_TAC[] THEN
    MAP_EVERY EXISTS_TAC [`sig:A`; `b:A`; `p15:A`; `cvs:A`] THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* ZF_REPLACEMENT *)
  FIRST_ASSUM(MP_TAC o SPECL
    [`realname_form`; `0`; `1`; `vv:num->A`; `om:A`] o MATCH_MP
      ZF_REPLACEMENT) THEN
  ANTS_TAC THENL
   [REWRITE_TAC[ARITH_EQ] THEN ASM_REWRITE_TAC[] THEN
    X_GEN_TAC `n:A` THEN STRIP_TAC THEN
    USE_THEN "val" (MP_TAC o SPEC `n:A`) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(X_CHOOSE_THEN `w0:A` (CONJUNCTS_THEN2 ASSUME_TAC
      (X_CHOOSE_THEN `sig0:A` (X_CHOOSE_THEN `b0:A`
        (X_CHOOSE_THEN `p0:A` (X_CHOOSE_THEN `c0:A` STRIP_ASSUME_TAC)))))) THEN
    EXISTS_TAC `w0:A` THEN ASM_REWRITE_TAC[] THEN
    X_GEN_TAC `w':A` THEN STRIP_TAC THEN
    USE_THEN "hc" (MP_TAC o SPECL [`n:A`; `w':A`]) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(MP_TAC o C EQ_MP
               (ASSUME `holds D E ((1 |-> (w':A)) ((0 |-> (n:A)) vv))
                        realname_form`)) THEN
    DISCH_THEN(X_CHOOSE_THEN `sig':A` (X_CHOOSE_THEN `b':A`
      (X_CHOOSE_THEN `p':A` (X_CHOOSE_THEN `c':A` STRIP_ASSUME_TAC)))) THEN
    (* sig'=sig0 (ECHECK_SV), p'=p0 (EOPAIR_UNIQUE), c'=c0, b'=b0 *)
    (* (EAPPLY_UNIQUE), w'=w0 *)
    SUBGOAL_THEN `sig':A = sig0` SUBST_ALL_TAC THENL
     [MP_TAC(ISPECL
             [`D:A->bool`; `E:A->A->bool`; `ON:A`; `n:A`; `sig':A`; `sig0:A`]
             ECHECK_SV) THEN ANTS_TAC THENL
               [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC];
               ALL_TAC] THEN
    SUBGOAL_THEN `p':A = p0` SUBST_ALL_TAC THENL
     [MP_TAC(ISPECL
             [`D:A->bool`; `E:A->A->bool`; `alpha:A`; `n:A`; `p':A`; `p0:A`]
             EOPAIR_UNIQUE) THEN ANTS_TAC THENL
               [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC];
               ALL_TAC] THEN
    SUBGOAL_THEN `c':A = c0` SUBST_ALL_TAC THENL
     [MP_TAC(ISPECL
             [`D:A->bool`; `E:A->A->bool`; `p0:A`; `onetw:A`; `c':A`; `c0:A`]
             EOPAIR_UNIQUE) THEN ANTS_TAC THENL
               [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC];
               ALL_TAC] THEN
    SUBGOAL_THEN `b':A = b0` SUBST_ALL_TAC THENL
     [MP_TAC(ISPECL
             [`D:A->bool`; `E:A->A->bool`; `embf:A`; `c0:A`; `b':A`; `b0:A`]
             EAPPLY_UNIQUE) THEN ANTS_TAC THENL
               [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC];
               ALL_TAC] THEN
    MP_TAC(ISPECL
           [`D:A->bool`; `E:A->A->bool`; `sig0:A`; `b0:A`; `w':A`; `w0:A`]
           EOPAIR_UNIQUE) THEN ANTS_TAC THENL
    [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC];
    ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `rdot:A`
             (CONJUNCTS_THEN2 ASSUME_TAC (LABEL_TAC "out"))) THEN
  EXISTS_TAC `rdot:A` THEN ASM_REWRITE_TAC[] THEN
  X_GEN_TAC `z:A` THEN DISCH_TAC THEN
  USE_THEN "out" (MP_TAC o SPEC `z:A`) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  EQ_TAC THENL
   [DISCH_THEN(X_CHOOSE_THEN `n:A` (CONJUNCTS_THEN2 ASSUME_TAC
      (CONJUNCTS_THEN2 ASSUME_TAC MP_TAC))) THEN
    USE_THEN "hc" (MP_TAC o SPECL [`n:A`; `z:A`]) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    DISCH_THEN(X_CHOOSE_THEN `sig:A` (X_CHOOSE_THEN `b:A`
      (X_CHOOSE_THEN `p15:A` (X_CHOOSE_THEN `cvs:A` STRIP_ASSUME_TAC)))) THEN
    MAP_EVERY EXISTS_TAC [`n:A`; `sig:A`; `b:A`; `p15:A`; `cvs:A`] THEN
    ASM_REWRITE_TAC[];
    DISCH_THEN(X_CHOOSE_THEN `n:A` (X_CHOOSE_THEN `sig:A` (X_CHOOSE_THEN `b:A`
      (X_CHOOSE_THEN `p15:A` (X_CHOOSE_THEN `cvs:A` STRIP_ASSUME_TAC))))) THEN
    EXISTS_TAC `n:A` THEN ASM_REWRITE_TAC[] THEN
    USE_THEN "hc" (MP_TAC o SPECL [`n:A`; `z:A`]) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    MAP_EVERY EXISTS_TAC [`sig:A`; `b:A`; `p15:A`; `cvs:A`] THEN
    ASM_REWRITE_TAC[]]);;

(* ==== F7 (II.3) helper: EBV_IN_DIAG -- the Boolean membership value
   [[u IN v]] = bb when <u,bb> IN v (the diagonal pair) AND every table term
   qy meet [[u=y]] <= bb (off-diagonal terms vanish, diagonal = bb).  Generic;
   discharged for rdot_alpha via ECHECK_EQ_TOP/BOT in COHEN_MEM_VALUE. *)

let EBV_IN_DIAG = prove
 (`!D (E:A->A->bool) B leq u v bb e0 z.
     model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
     u IN D /\ v IN D /\ bb IN D /\ E bb B /\
     eapply D E v u bb /\
     ebv_eq D E B leq u u e0 /\ etop D E B leq e0 /\
     (!y qy ey c. y IN D /\ qy IN D /\ ey IN D /\ c IN D /\
         eapply D E v y qy /\ ebv_eq D E B leq u y ey /\
           emeet D E B leq qy ey c
         ==> erel D E leq c bb) /\
     z IN D /\ ebv_in D E B leq u v z
     ==> z = bb`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `eporder D (E:A->A->bool) (B:A) (leq:A)` ASSUME_TAC THENL
   [ASM_MESON_TAC[ECBA_IMP_PORDER]; ALL_TAC] THEN
  SUBGOAL_THEN `(e0:A) IN D /\ (E:A->A->bool) (e0:A) (B:A)`
    STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[ETOP_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) (z:A) (B:A)` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`; `E:A->A->bool`; `B:A`; `leq:A`; `u:A`;
                  `v:A`; `z:A`]
                 EBV_IN_IN_B) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* z <= bb via EBV_IN_LE_V (upper bound: bb bounds all terms) *)
  SUBGOAL_THEN `erel D (E:A->A->bool) (leq:A) (z:A) (bb:A)` ASSUME_TAC THENL
   [MP_TAC(ISPECL
           [`D:A->bool`; `E:A->A->bool`; `B:A`; `leq:A`; `u:A`; `v:A`;
            `z:A`; `bb:A`]
           EBV_IN_LE_V) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC]; ALL_TAC] THEN
  (* bb <= z via EBV_IN_GE_TERM_V with the diagonal term y=u, qy=bb, ey=e0, *)
  (* c=bb *)
  SUBGOAL_THEN `emeet D (E:A->A->bool) (B:A) (leq:A) (bb:A) (e0:A) (bb:A)`
    ASSUME_TAC THENL
   [MATCH_MP_TAC EMEET_TOP THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) (leq:A) (bb:A) (z:A)` ASSUME_TAC THENL
   [MP_TAC(ISPECL
           [`D:A->bool`; `E:A->A->bool`; `B:A`; `leq:A`; `u:A`; `v:A`; `z:A`;
            `u:A`; `bb:A`; `e0:A`; `bb:A`] EBV_IN_GE_TERM_V) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MATCH_MP_TAC(ISPECL
               [`D:A->bool`; `E:A->A->bool`; `B:A`; `leq:A`; `z:A`; `bb:A`]
               EPORDER_ANTISYM) THEN
  ASM_REWRITE_TAC[]);;

(* ==== F7 (II.3): COHEN_MEM_VALUE -- [[ n^ IN rdot_alpha ]] = b_{alpha,n}.
   Abstract: rdot's pairs decompose as <n'^,
   embf(<<alpha,n'>,1>)> (decomp hyp),
   with the diagonal pair <n^, bb> IN rdot.  Off-diagonal terms vanish
   (ECHECK_EQ_BOT), diagonal = bb (ECHECK_EQ_TOP); EBV_IN_DIAG finishes. *)

let COHEN_MEM_VALUE = prove
 (`!D (E:A->A->bool) B leq onebee embf rdot alpha onetw n nch p15 cvs bb z.
     model D E ZF_AX /\ (!u:A. u IN D ==> elmem D E u) /\
     ecba D E B leq /\ B IN D /\ leq IN D /\ onebee IN D /\ E onebee B /\
     etop D E B leq onebee /\
     embf IN D /\ eisfun D E embf /\
     rdot IN D /\ bname D E B rdot /\
     n IN D /\ alpha IN D /\ onetw IN D /\
     (!y qy. y IN D /\ qy IN D /\ eapply D E rdot y qy
             ==> ?n' p' cvs'. n' IN D /\ p' IN D /\ cvs' IN D /\
                    echeck D E onebee n' y /\ eopair D E alpha n' p' /\
                    eopair D E p' onetw cvs' /\ eapply D E embf cvs' qy) /\
     nch IN D /\ echeck D E onebee n nch /\
     p15 IN D /\ cvs IN D /\ eopair D E alpha n p15 /\
       eopair D E p15 onetw cvs /\
     eapply D E embf cvs bb /\ bb IN D /\ E bb B /\
     eapply D E rdot nch bb /\
     z IN D /\ ebv_in D E B leq nch rdot z
     ==> z = bb`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `eporder D (E:A->A->bool) (B:A) (leq:A)` ASSUME_TAC THENL
   [ASM_MESON_TAC[ECBA_IMP_PORDER]; ALL_TAC] THEN
  SUBGOAL_THEN `bname D (E:A->A->bool) (B:A) (nch:A)` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`; `E:A->A->bool`; `onebee:A`; `B:A`;
                  `n:A`; `nch:A`]
                 ECHECK_IS_BNAME) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* e0 = [[nch=nch]] exists, and is top *)
  MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `B:A`; `leq:A`; `nch:A`; `nch:A`]
    EBV_EQ_VAL_EXISTS) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `e0:A` STRIP_ASSUME_TAC) THEN
  SUBGOAL_THEN `etop D (E:A->A->bool) (B:A) (leq:A) (e0:A)` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`; `E:A->A->bool`; `B:A`; `leq:A`; `onebee:A`;
                  `n:A`; `n:A`; `nch:A`; `nch:A`; `e0:A`] ECHECK_EQ_TOP) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* diagonal dominance: every table term <= bb *)
  SUBGOAL_THEN
   `!y qy ey c. y IN D /\ qy IN D /\ ey IN D /\ c IN D /\
       eapply D (E:A->A->bool) rdot y qy /\ ebv_eq D E B leq nch y ey /\
       emeet D E B leq qy ey c ==> erel D E leq c bb`
   ASSUME_TAC THENL
   [MAP_EVERY X_GEN_TAC [`y:A`; `qy:A`; `ey:A`; `c:A`] THEN STRIP_TAC THEN
    FIRST_X_ASSUM(MP_TAC o SPECL [`y:A`; `qy:A`]) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(X_CHOOSE_THEN `n':A` (X_CHOOSE_THEN `p':A`
      (X_CHOOSE_THEN `cvs':A` STRIP_ASSUME_TAC))) THEN
    ASM_CASES_TAC `(n:A) = n'` THENL
     [(* diagonal: y=nch, qy=bb, ey top, c=bb *)
      FIRST_X_ASSUM SUBST_ALL_TAC THEN
      SUBGOAL_THEN `(y:A) = nch` SUBST_ALL_TAC THENL
       [MP_TAC(ISPECL
               [`D:A->bool`; `E:A->A->bool`; `onebee:A`; `n':A`;
                `y:A`; `nch:A`]
               ECHECK_SV) THEN ANTS_TAC THENL
      [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC];
      ALL_TAC] THEN
      SUBGOAL_THEN `(p':A) = p15` SUBST_ALL_TAC THENL
       [MP_TAC(ISPECL
               [`D:A->bool`; `E:A->A->bool`; `alpha:A`; `n':A`;
                `p':A`; `p15:A`]
               EOPAIR_UNIQUE) THEN ANTS_TAC THENL
      [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC];
      ALL_TAC] THEN
      SUBGOAL_THEN `(cvs':A) = cvs` SUBST_ALL_TAC THENL
       [MP_TAC(ISPECL
               [`D:A->bool`; `E:A->A->bool`; `p15:A`; `onetw:A`;
                `cvs':A`; `cvs:A`]
               EOPAIR_UNIQUE) THEN ANTS_TAC THENL
      [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC];
      ALL_TAC] THEN
      SUBGOAL_THEN `(qy:A) = bb` SUBST_ALL_TAC THENL
       [MP_TAC(ISPECL
               [`D:A->bool`; `E:A->A->bool`; `embf:A`; `cvs:A`; `qy:A`; `bb:A`]
               EAPPLY_UNIQUE) THEN ANTS_TAC THENL
      [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC];
      ALL_TAC] THEN
      (* ey = [[nch=nch]] is top; c = meet bb ey = bb *)
      SUBGOAL_THEN `etop D (E:A->A->bool) (B:A) (leq:A) (ey:A)`
        ASSUME_TAC THENL
        [MATCH_MP_TAC(ISPECL
                      [`D:A->bool`; `E:A->A->bool`; `B:A`; `leq:A`; `onebee:A`;
                       `n':A`; `n':A`; `nch:A`; `nch:A`; `ey:A`]
                        ECHECK_EQ_TOP) THEN
        ASM_REWRITE_TAC[]; ALL_TAC] THEN
      SUBGOAL_THEN `(c:A) = bb` SUBST_ALL_TAC THENL
       [MP_TAC(ISPECL
               [`D:A->bool`; `E:A->A->bool`; `B:A`; `leq:A`; `ey:A`; `bb:A`]
               EMEET_TOP) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
        ASM_MESON_TAC[EMEET_UNIQUE]; ALL_TAC] THEN
      MATCH_MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `B:A`; `leq:A`; `bb:A`]
        EPORDER_REFL) THEN ASM_REWRITE_TAC[];
      (* off-diagonal: ey = bot, c <= ey <= bb *)
      SUBGOAL_THEN `ebot D (E:A->A->bool) (B:A) (leq:A) (ey:A)`
        ASSUME_TAC THENL
        [MATCH_MP_TAC(ISPECL
                      [`D:A->bool`; `E:A->A->bool`; `B:A`; `leq:A`; `onebee:A`;
                       `n:A`; `n':A`; `nch:A`; `y:A`; `ey:A`]
                        ECHECK_EQ_BOT) THEN
        ASM_REWRITE_TAC[]; ALL_TAC] THEN
      SUBGOAL_THEN `E (ey:A) (B:A) /\ E (c:A) (B:A)` STRIP_ASSUME_TAC THENL
       [CONJ_TAC THENL
         [MATCH_MP_TAC(ISPECL
                       [`D:A->bool`; `E:A->A->bool`; `B:A`; `leq:A`; `nch:A`;
                        `y:A`; `ey:A`]
                       EBV_EQ_IN_B) THEN ASM_REWRITE_TAC[];
          ASM_MESON_TAC[EMEET_IN]]; ALL_TAC] THEN
      MATCH_MP_TAC(ISPECL
                   [`D:A->bool`; `E:A->A->bool`; `B:A`; `leq:A`; `c:A`;
                    `ey:A`; `bb:A`]
                   EPORDER_TRANS) THEN
      ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
       [ASM_MESON_TAC[EMEET_LE];
        MATCH_MP_TAC(ISPECL
                     [`D:A->bool`; `E:A->A->bool`; `B:A`; `leq:A`;
                      `ey:A`; `bb:A`]
                     EBOT_LE) THEN ASM_REWRITE_TAC[]]];
    ALL_TAC] THEN
  (* apply EBV_IN_DIAG *)
  MP_TAC(ISPECL
         [`D:A->bool`; `E:A->A->bool`; `B:A`; `leq:A`; `nch:A`; `rdot:A`;
          `bb:A`; `e0:A`; `z:A`] EBV_IN_DIAG) THEN
  ANTS_TAC THENL
  [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; DISCH_THEN ACCEPT_TAC]);;

(* ==== F7 (II.4) lemma S1: ENONBOT_INHAB -- a non-bot regular-open set is
   inhabited.  RO bot = empty set (EBOT_ROSET);
   contrapositive: not inhabited =>
   empty => bot.  Feeds RO_POS_HAS_EMB in COHEN_REAL_DISTINCT. *)

let ENONBOT_INHAB = prove
 (`!D (E:A->A->bool) P leqp B inclB m.
     model D E ZF_AX /\ eleqp D E P leqp /\ eroset D E P leqp B /\
     eincl D E B inclB /\ m IN D /\ E m B /\ ~ebot D E B inclB m
     ==> ?r. r IN D /\ E r m`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  ASM_CASES_TAC `?r:A. r IN D /\ (E:A->A->bool) r m` THENL
   [FIRST_ASSUM ACCEPT_TAC;
    SUBGOAL_THEN `eempty D (E:A->A->bool) m` ASSUME_TAC THENL
     [REWRITE_TAC[eempty] THEN ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[];
      ALL_TAC] THEN
    SUBGOAL_THEN `ebot D (E:A->A->bool) (B:A) (inclB:A) (m:A)` ASSUME_TAC THENL
     [MP_TAC(ISPECL
             [`D:A->bool`; `E:A->A->bool`; `P:A`; `leqp:A`; `B:A`;
              `inclB:A`; `m:A`]
             EBOT_ROSET) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    ASM_MESON_TAC[]]);;

(* ==== F7 (II.4) lemma S2: COHEN_DISAGREE_INCOMPAT -- Cohen conditions p,q
   that disagree at a coordinate (<c,v0> IN p, <c,v1> IN q, v0=/=v1) are
   incompatible.  A common lower bound w would contain both pairs (ELEQP_EREL:
   <= means superset) and be functional (ecohenp) => v0=v1, absurd. *)

let COHEN_DISAGREE_INCOMPAT = prove
 (`!D (E:A->A->bool) ci om P leqp p q c v0 v1 cv0 cv1.
     model D E ZF_AX /\ eleqp D E P leqp /\ ecohenp D E ci om P /\
     E p P /\ E q P /\
     c IN D /\ v0 IN D /\ v1 IN D /\ ~(v0 = v1) /\
     cv0 IN D /\ cv1 IN D /\ eopair D E c v0 cv0 /\ eopair D E c v1 cv1 /\
     E cv0 p /\ E cv1 q
     ==> ~ecompat D E P leqp p q`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN REWRITE_TAC[ecompat] THEN
  DISCH_THEN(X_CHOOSE_THEN `w:A` STRIP_ASSUME_TAC) THEN
  SUBGOAL_THEN `(p:A) IN D /\ (q:A) IN D` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[EREL_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `esubset D (E:A->A->bool) p w` ASSUME_TAC THENL
   [MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `P:A`; `leqp:A`; `w:A`; `p:A`]
      ELEQP_EREL) THEN ASM_REWRITE_TAC[] THEN STRIP_TAC THEN ASM_REWRITE_TAC[];
     ALL_TAC] THEN
  SUBGOAL_THEN `esubset D (E:A->A->bool) q w` ASSUME_TAC THENL
   [MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `P:A`; `leqp:A`; `w:A`; `q:A`]
      ELEQP_EREL) THEN ASM_REWRITE_TAC[] THEN STRIP_TAC THEN ASM_REWRITE_TAC[];
     ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) cv0 w` ASSUME_TAC THENL
   [UNDISCH_TAC `esubset D (E:A->A->bool) p w` THEN REWRITE_TAC[esubset] THEN
    DISCH_THEN MATCH_MP_TAC THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) cv1 w` ASSUME_TAC THENL
   [UNDISCH_TAC `esubset D (E:A->A->bool) q w` THEN REWRITE_TAC[esubset] THEN
    DISCH_THEN MATCH_MP_TAC THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `efunctional D (E:A->A->bool) w` ASSUME_TAC THENL
   [UNDISCH_TAC `ecohenp D (E:A->A->bool) ci om P` THEN
    REWRITE_TAC[ecohenp] THEN
    DISCH_THEN(MP_TAC o SPEC `w:A` o CONJUNCT2) THEN ASM_REWRITE_TAC[] THEN
    STRIP_TAC THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  UNDISCH_TAC `~((v0:A) = v1)` THEN REWRITE_TAC[] THEN
  FIRST_X_ASSUM(MP_TAC o REWRITE_RULE[efunctional]) THEN
  DISCH_THEN(MP_TAC o SPECL [`cv0:A`; `cv1:A`; `c:A`; `v0:A`; `v1:A`]) THEN
  ASM_REWRITE_TAC[]);;

(* ==== F7 (II.4) lemma S3: EMB_INCOMPAT_MEET_BOT -- incompatible conditions
   p,q have embedding-meet = bot.  If ~ebot(meet),
   S1 gives an inhabitant r of the
   meet, which lies in both e(p),e(q) (EINCL_EREL subset),
   so EMB_MEET_BWD yields a
   common lower bound => ecompat, contradiction. *)

let EMB_INCOMPAT_MEET_BOT = prove
 (`!D (E:A->A->bool) P leqp B inclB p q dp ep dq eq2 m.
     model D E ZF_AX /\ eleqp D E P leqp /\
     eroset D E P leqp B /\ eincl D E B inclB /\
     p IN D /\ q IN D /\ ~ecompat D E P leqp p q /\
     edownset D E P leqp p dp /\ eintcl D E P leqp dp ep /\ E ep B /\
     edownset D E P leqp q dq /\ eintcl D E P leqp dq eq2 /\ E eq2 B /\
     m IN D /\ emeet D E B inclB ep eq2 m
     ==> ebot D E B inclB m`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `(E:A->A->bool) m B` ASSUME_TAC THENL
   [MP_TAC(ISPECL
           [`D:A->bool`; `E:A->A->bool`; `B:A`; `inclB:A`; `ep:A`;
            `eq2:A`; `m:A`]
           EMEET_IN) THEN ASM_REWRITE_TAC[] THEN STRIP_TAC THEN
     ASM_REWRITE_TAC[]; ALL_TAC] THEN
  ASM_CASES_TAC `ebot D (E:A->A->bool) (B:A) (inclB:A) (m:A)` THENL
   [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  SUBGOAL_THEN `?r:A. r IN D /\ (E:A->A->bool) r m` STRIP_ASSUME_TAC THENL
   [MP_TAC(ISPECL
           [`D:A->bool`; `E:A->A->bool`; `P:A`; `leqp:A`; `B:A`;
            `inclB:A`; `m:A`]
           ENONBOT_INHAB) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC]; ALL_TAC] THEN
  MP_TAC(ISPECL
         [`D:A->bool`; `E:A->A->bool`; `B:A`; `inclB:A`; `ep:A`;
          `eq2:A`; `m:A`]
         EMEET_LE) THEN ASM_REWRITE_TAC[] THEN STRIP_TAC THEN
  SUBGOAL_THEN `(ep:A) IN D /\ (eq2:A) IN D` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[EREL_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `esubset D (E:A->A->bool) m ep` ASSUME_TAC THENL
   [MP_TAC(ISPECL
           [`D:A->bool`; `E:A->A->bool`; `B:A`; `inclB:A`; `m:A`; `ep:A`]
           EINCL_EREL) THEN ASM_REWRITE_TAC[] THEN STRIP_TAC THEN
         ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `esubset D (E:A->A->bool) m eq2` ASSUME_TAC THENL
   [MP_TAC(ISPECL
           [`D:A->bool`; `E:A->A->bool`; `B:A`; `inclB:A`; `m:A`; `eq2:A`]
           EINCL_EREL) THEN ASM_REWRITE_TAC[] THEN STRIP_TAC THEN
         ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) r ep` ASSUME_TAC THENL
   [UNDISCH_TAC `esubset D (E:A->A->bool) m ep` THEN REWRITE_TAC[esubset] THEN
    DISCH_THEN MATCH_MP_TAC THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) r eq2` ASSUME_TAC THENL
   [UNDISCH_TAC `esubset D (E:A->A->bool) m eq2` THEN REWRITE_TAC[esubset] THEN
    DISCH_THEN MATCH_MP_TAC THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MP_TAC(ISPECL
         [`D:A->bool`; `E:A->A->bool`; `P:A`; `leqp:A`; `p:A`; `q:A`; `dp:A`;
          `ep:A`; `dq:A`; `eq2:A`; `r:A`] EMB_MEET_BWD) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `s:A` STRIP_ASSUME_TAC) THEN
  SUBGOAL_THEN `ecompat D (E:A->A->bool) P leqp p q` ASSUME_TAC THENL
   [REWRITE_TAC[ecompat] THEN EXISTS_TAC `s:A` THEN ASM_REWRITE_TAC[] THEN
    MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `P:A`; `leqp:A`; `s:A`; `p:A`]
      ELEQP_EREL) THEN ASM_REWRITE_TAC[] THEN MESON_TAC[]; ALL_TAC] THEN
  ASM_MESON_TAC[]);;

(* ==== F7 (II.4) lemma S4c: EFIN_OM_MISS -- a finite subset of om misses a
   point.  If img = om then om is finite (EFIN_TO_NAT: om ~ n<om),
   so om injects
   into n, contradicting that om is a cardinal (ECARD_NO_INJ_DOWN). *)

let EFIN_OM_MISS = prove
 (`!D (E:A->A->bool) om img.
     model D E ZF_AX /\ eomega D E om /\ img IN D /\ efin D E img /\
     esubset D E img om
     ==> ?x. x IN D /\ E x om /\ ~(E x img)`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `(om:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[EOMEGA_IN]; ALL_TAC] THEN
  ASM_CASES_TAC `?x:A. x IN D /\ (E:A->A->bool) x om /\ ~(E x img)` THENL
   [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  SUBGOAL_THEN `esubset D (E:A->A->bool) om img` ASSUME_TAC THENL
   [REWRITE_TAC[esubset] THEN ASM_MESON_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(img:A) = om` SUBST_ALL_TAC THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `img:A`; `om:A`]
                 ESUBSET_ANTISYM) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `om:A`; `om:A`] EFIN_TO_NAT) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `n:A` (X_CHOOSE_THEN `f:A` STRIP_ASSUME_TAC)) THEN
  MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `f:A`; `n:A`; `om:A`]
         EBIJ_SYM) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `g:A` ASSUME_TAC) THEN
  SUBGOAL_THEN `einj D (E:A->A->bool) g om n` ASSUME_TAC THENL
   [MATCH_MP_TAC EBIJ_EINJ THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `n:A`; `om:A`]
         ECARD_NO_INJ_DOWN) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
     [REWRITE_TAC[ecardinal] THEN
      MATCH_MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `om:A`]
                   EOMEGA_CARDINAL) THEN
      ASM_REWRITE_TAC[];
      ASM_MESON_TAC[EOMEGA_ORDINALS]];
    ASM_MESON_TAC[]]);;

(* ================================================================= *)
(* F7 (II.4): a Cohen condition uses only finitely                    *)
(* many second-coordinates, so SOME n IN om is unused.  Infrastructure:*)
(* projpair2_form/HOLDS_PROJPAIR2 (second-projection object form),     *)
(* ESNDPROJ_FAMILY (the second-projection map as an M-set function),   *)
(* COHEN_UNUSED_COORD (the fresh-coordinate statement itself).         *)
(* ================================================================= *)

(* ---- S4a-i: the SECOND-projection object form, mirroring            *)
(*   projpair_form/HOLDS_PROJPAIR with output coord 70->80             *)
(*   (maps x=<c,w> to <x,w> instead of <x,c>).                         *)

let projpair2_form = new_definition
  `projpair2_form =
     ?? 70 (?? 80 (opair_form 70 80 11 && opair_form 11 80 63))`;;

let HOLDS_PROJPAIR2 = prove
 (`!D (E:A->A->bool) v z out.
     model D E ZF_AX /\ valuation D v /\ z IN D /\ out IN D
     ==> (holds D E ((63 |-> out) ((11 |-> z) v)) projpair2_form <=>
          ?c. c IN D /\ ?w. w IN D /\
              eopair D E c w z /\ eopair D E z w out)`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `valuation D ((63 |-> (out:A)) ((11 |-> (z:A)) v))`
    (LABEL_TAC "vw") THENL
   [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[] THEN
    MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  REWRITE_TAC[projpair2_form; HOLDS_EX; HOLDS_AND] THEN
  SUBGOAL_THEN
   `!c w:A. c IN D /\ w IN D
      ==> (holds D E ((80 |-> w) ((70 |-> c)
             ((63 |-> (out:A)) ((11 |-> (z:A)) v)))) (opair_form 70 80 11) <=>
           eopair D E c w z) /\
          (holds D E ((80 |-> w) ((70 |-> c)
             ((63 |-> out) ((11 |-> z) v)))) (opair_form 11 80 63) <=>
           eopair D E z w out)`
   (LABEL_TAC "piles") THENL
   [REPEAT GEN_TAC THEN STRIP_TAC THEN
    SUBGOAL_THEN
     `valuation D ((80 |-> (w:A)) ((70 |-> (c:A))
        ((63 |-> (out:A)) ((11 |-> (z:A)) v))))` ASSUME_TAC THENL
     [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
    ASM_SIMP_TAC[HOLDS_OPAIR_FORM] THEN
    REWRITE_TAC[VALMOD] THEN CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN
    REWRITE_TAC[]; ALL_TAC] THEN
  MATCH_MP_TAC(MESON[]
    `(!s:A. s IN D ==> (P s <=> Q s))
     ==> ((?s. s IN D /\ P s) <=> (?s. s IN D /\ Q s))`) THEN
  X_GEN_TAC `c:A` THEN DISCH_TAC THEN
  MATCH_MP_TAC(MESON[]
    `(!s:A. s IN D ==> (P s <=> Q s))
     ==> ((?s. s IN D /\ P s) <=> (?s. s IN D /\ Q s))`) THEN
  X_GEN_TAC `w:A` THEN DISCH_TAC THEN
  USE_THEN "piles" (MP_TAC o SPECL [`c:A`; `w:A`]) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  STRIP_TAC THEN ASM_REWRITE_TAC[]);;

(* ---- S4a-ii: the second-projection map exists (mirror of            *)
(*   EPROJ_FAMILY with projpair2_form; maps x=<c,w> to w).             *)

let ESNDPROJ_FAMILY = prove
 (`!D (E:A->A->bool) p.
     model D E ZF_AX /\ p IN D /\
     (!z. z IN D /\ E z p ==> ?u w. u IN D /\ w IN D /\ eopair D E u w z)
     ==> ?g. g IN D /\
             (!n z z'. n IN D /\ z IN D /\ z' IN D /\
                       eapply D E g n z /\ eapply D E g n z' ==> z = z') /\
             (!x. x IN D /\ E x p
                  ==> ?c w. c IN D /\ w IN D /\
                            eopair D E c w x /\ eapply D E g x w)`,
  REPEAT STRIP_TAC THEN
  FIRST_ASSUM(X_CHOOSE_TAC `v0:num->A` o MATCH_MP VALUATION_EXISTS o
    MATCH_MP MODEL_NONEMPTY) THEN
  MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `projpair2_form`; `11`; `63`;
    `v0:num->A`; `p:A`] EIMG_FAMILY) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[] THEN REPEAT CONJ_TAC THENL
     [CONV_TAC NUM_REDUCE_CONV;
      (* ---- FUNC ---- *)
      X_GEN_TAC `x:A` THEN STRIP_TAC THEN
      FIRST_X_ASSUM(MP_TAC o SPEC `x:A`) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(X_CHOOSE_THEN `u:A`
                 (X_CHOOSE_THEN `w:A` STRIP_ASSUME_TAC)) THEN
      MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `x:A`; `w:A`]
             EOPAIR_EXISTS) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(X_CHOOSE_TAC `out:A`) THEN
      SUBGOAL_THEN `(out:A) IN D` ASSUME_TAC THENL
       [ASM_MESON_TAC[EOPAIR_IN]; ALL_TAC] THEN
      EXISTS_TAC `out:A` THEN
      SUBGOAL_THEN
       `holds D E ((63 |-> (out:A)) ((11 |-> (x:A)) v0)) projpair2_form`
       ASSUME_TAC THENL
       [MP_TAC(ISPECL
               [`D:A->bool`; `E:A->A->bool`; `v0:num->A`; `x:A`; `out:A`]
               HOLDS_PROJPAIR2) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
        DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
        EXISTS_TAC `u:A` THEN ASM_REWRITE_TAC[] THEN
        EXISTS_TAC `w:A` THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
      ASM_REWRITE_TAC[] THEN
      X_GEN_TAC `out':A` THEN
      DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC MP_TAC) THEN
      MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `v0:num->A`; `x:A`; `out':A`]
        HOLDS_PROJPAIR2) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
      DISCH_THEN(X_CHOOSE_THEN `c':A` (CONJUNCTS_THEN2 ASSUME_TAC
        (X_CHOOSE_THEN `w':A` STRIP_ASSUME_TAC))) THEN
      SUBGOAL_THEN `(w':A) = w` SUBST_ALL_TAC THENL
       [MP_TAC(ISPECL
               [`D:A->bool`; `E:A->A->bool`; `c':A`; `w':A`; `u:A`; `w:A`;
                `x:A`] EOPAIR_INJ) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
        DISCH_THEN(ACCEPT_TAC o CONJUNCT2); ALL_TAC] THEN
      ASM_MESON_TAC[EOPAIR_UNIQUE];
      (* ---- HF ---- *)
      MAP_EVERY X_GEN_TAC [`x:A`; `out:A`] THEN STRIP_TAC THEN
      MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `v0:num->A`; `x:A`; `out:A`]
        HOLDS_PROJPAIR2) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th ->
        UNDISCH_TAC
          `holds D E ((63 |-> (out:A)) ((11 |-> (x:A)) v0))
           projpair2_form` THEN
        REWRITE_TAC[th]) THEN
      DISCH_THEN(X_CHOOSE_THEN `c:A` (CONJUNCTS_THEN2 ASSUME_TAC
        (X_CHOOSE_THEN `w:A` STRIP_ASSUME_TAC))) THEN
      EXISTS_TAC `w:A` THEN ASM_REWRITE_TAC[]];
    ALL_TAC] THEN
  INTRO_TAC "@g. gD mem rpairs sv peridx" THEN
  EXISTS_TAC `g:A` THEN REPEAT CONJ_TAC THENL
   [USE_THEN "gD" ACCEPT_TAC;
    USE_THEN "sv" ACCEPT_TAC;
    X_GEN_TAC `x:A` THEN STRIP_TAC THEN
    USE_THEN "peridx" (MP_TAC o SPEC `x:A`) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(X_CHOOSE_THEN `out:A`
               (X_CHOOSE_THEN `s:A` STRIP_ASSUME_TAC)) THEN
    MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `v0:num->A`; `x:A`; `out:A`]
      HOLDS_PROJPAIR2) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th ->
      UNDISCH_TAC
        `holds D E ((63 |-> (out:A)) ((11 |-> (x:A)) v0)) projpair2_form` THEN
      REWRITE_TAC[th]) THEN
    DISCH_THEN(X_CHOOSE_THEN `c:A` (CONJUNCTS_THEN2 ASSUME_TAC
      (X_CHOOSE_THEN `w:A` STRIP_ASSUME_TAC))) THEN
    SUBGOAL_THEN `(s:A) = w` SUBST_ALL_TAC THENL
     [MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `x:A`; `s:A`; `x:A`; `w:A`;
        `out:A`] EOPAIR_INJ) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(ACCEPT_TAC o CONJUNCT2); ALL_TAC] THEN
    MAP_EVERY EXISTS_TAC [`c:A`; `w:A`] THEN ASM_REWRITE_TAC[]]);;

(* ---- S4: for a Cohen condition r0, there is a fresh second-coordinate*)
(*   n IN om: no <a,n> is in dom(r0).  Assembles COHEN_DOM_FIN_SUB      *)
(*   (dom finite SUBSET ii=iibase x om) + ESNDPROJ_FAMILY + EIMGSET/    *)
(*   EFIN_IMAGE (used-coordinate set finite) + EFIN_OM_MISS.            *)

let COHEN_UNUSED_COORD = prove
 (`!D (E:A->A->bool) iibase om ii tw ci P r0 dr0.
     model D E ZF_AX /\ eomega D E om /\
     ecross D E iibase om ii /\ ecross D E ii tw ci /\ ecohenp D E ci om P /\
     E r0 P /\ r0 IN D /\ edomain D E r0 dr0 /\ dr0 IN D
     ==> ?n. n IN D /\ E n om /\
             (!a coord. a IN D /\ coord IN D /\ eopair D E a n coord
                        ==> ~(E coord dr0))`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  (* dom finite, SUBSET ii *)
  MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `ii:A`; `tw:A`; `ci:A`; `om:A`;
    `P:A`; `r0:A`; `dr0:A`] COHEN_DOM_FIN_SUB) THEN
  ASM_REWRITE_TAC[] THEN STRIP_TAC THEN
  (* every x IN dr0 is a pair <u,w>, u IN iibase, w IN om *)
  SUBGOAL_THEN
   `!x. x IN D /\ (E:A->A->bool) x dr0
        ==> ?u w. u IN D /\ w IN D /\ (E:A->A->bool) u iibase /\ E w om /\
                  eopair D E u w x`
   (LABEL_TAC "pairs") THENL
   [X_GEN_TAC `x:A` THEN STRIP_TAC THEN
    MP_TAC(ISPECL
           [`D:A->bool`; `E:A->A->bool`; `iibase:A`; `om:A`; `ii:A`; `x:A`]
           ECROSS_MEMBER) THEN ASM_REWRITE_TAC[] THEN
    SUBGOAL_THEN `(E:A->A->bool) x ii` ASSUME_TAC THENL
     [UNDISCH_TAC `esubset D (E:A->A->bool) dr0 ii` THEN
      REWRITE_TAC[esubset] THEN
      DISCH_THEN MATCH_MP_TAC THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    ASM_REWRITE_TAC[] THEN DISCH_THEN(fun th -> MP_TAC th) THEN MESON_TAC[];
    ALL_TAC] THEN
  (* second-projection map g *)
  MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `dr0:A`] ESNDPROJ_FAMILY) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `g:A` (CONJUNCTS_THEN2 (LABEL_TAC "gD")
    (CONJUNCTS_THEN2 (LABEL_TAC "gsv") (LABEL_TAC "gapp")))) THEN
  (* image set img = {m : ?y IN dr0. eapply g y m} *)
  MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `dr0:A`; `dr0:A`; `g:A`]
    EIMGSET_EXISTS) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `img:A` (CONJUNCTS_THEN2 (LABEL_TAC "imgD")
    (LABEL_TAC "imgmem"))) THEN
  (* img finite via EFIN_IMAGE *)
  SUBGOAL_THEN `efin D (E:A->A->bool) (img:A)` ASSUME_TAC THENL
   [MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `g:A`; `dr0:A`; `img:A`]
           EFIN_IMAGE) THEN
    DISCH_THEN MATCH_MP_TAC THEN REPEAT CONJ_TAC THENL
     [FIRST_ASSUM ACCEPT_TAC;
      FIRST_ASSUM ACCEPT_TAC;
      USE_THEN "gD" ACCEPT_TAC;
      USE_THEN "imgD" ACCEPT_TAC;
      USE_THEN "gsv" ACCEPT_TAC;
      X_GEN_TAC `x:A` THEN STRIP_TAC THEN
      USE_THEN "gapp" (MP_TAC o SPEC `x:A`) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(X_CHOOSE_THEN `c:A`
                 (X_CHOOSE_THEN `w:A` STRIP_ASSUME_TAC)) THEN
      EXISTS_TAC `w:A` THEN ASM_REWRITE_TAC[] THEN
      USE_THEN "imgmem" (MP_TAC o SPEC `w:A`) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
      EXISTS_TAC `x:A` THEN ASM_REWRITE_TAC[];
      X_GEN_TAC `m:A` THEN DISCH_TAC THEN
      USE_THEN "imgmem" (MP_TAC o SPEC `m:A`) THEN
      ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN MESON_TAC[]];
    ALL_TAC] THEN
  (* img SUBSET om *)
  SUBGOAL_THEN `esubset D (E:A->A->bool) (img:A) om` ASSUME_TAC THENL
   [REWRITE_TAC[esubset] THEN X_GEN_TAC `z:A` THEN STRIP_TAC THEN
    SUBGOAL_THEN
      `?y:A. y IN D /\ (E:A->A->bool) y dr0 /\ E y dr0 /\ eapply D E g y z`
      (X_CHOOSE_THEN `y:A` STRIP_ASSUME_TAC) THENL
     [USE_THEN "imgmem" (MP_TAC o SPEC `z:A`) THEN
      ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
      DISCH_TAC THEN ASM_MESON_TAC[]; ALL_TAC] THEN
    USE_THEN "pairs" (MP_TAC o SPEC `y:A`) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(X_CHOOSE_THEN `u:A` (X_CHOOSE_THEN `w:A` STRIP_ASSUME_TAC)) THEN
    USE_THEN "gapp" (MP_TAC o SPEC `y:A`) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(X_CHOOSE_THEN `c2:A`
               (X_CHOOSE_THEN `w2:A` STRIP_ASSUME_TAC)) THEN
    SUBGOAL_THEN `(w2:A) = w` SUBST_ALL_TAC THENL
     [MP_TAC(ISPECL
             [`D:A->bool`; `E:A->A->bool`; `c2:A`; `w2:A`; `u:A`; `w:A`; `y:A`]
             EOPAIR_INJ) THEN ASM_REWRITE_TAC[] THEN MESON_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN `(z:A) = w` SUBST_ALL_TAC THENL
     [USE_THEN "gsv" MATCH_MP_TAC THEN MAP_EVERY EXISTS_TAC [`y:A`] THEN
      ASM_REWRITE_TAC[]; ALL_TAC] THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* miss a point *)
  MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `om:A`; `img:A`]
         EFIN_OM_MISS) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `n:A` STRIP_ASSUME_TAC) THEN
  EXISTS_TAC `n:A` THEN ASM_REWRITE_TAC[] THEN
  MAP_EVERY X_GEN_TAC [`a:A`; `coord:A`] THEN REPEAT STRIP_TAC THEN
  (* coord IN dr0, coord = <a,n> => eapply g coord n => n IN img, contra *)
  USE_THEN "gapp" (MP_TAC o SPEC `coord:A`) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `c3:A` (X_CHOOSE_THEN `w3:A` STRIP_ASSUME_TAC)) THEN
  SUBGOAL_THEN `(w3:A) = n` SUBST_ALL_TAC THENL
   [MP_TAC(ISPECL
           [`D:A->bool`; `E:A->A->bool`; `c3:A`; `w3:A`; `a:A`;
            `n:A`; `coord:A`]
           EOPAIR_INJ) THEN ASM_REWRITE_TAC[] THEN MESON_TAC[]; ALL_TAC] THEN
  UNDISCH_TAC `~((E:A->A->bool) n img)` THEN REWRITE_TAC[] THEN
  USE_THEN "imgmem" (MP_TAC o SPEC `n:A`) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  EXISTS_TAC `coord:A` THEN ASM_REWRITE_TAC[]);;

(* ================================================================= *)
(* F7 (II.4) MAIN sub-lemmas: BRIDGE (embf(cv)=e({cv})), L1            *)
(* (Cohen real name's eapply-graph), L-CONTRA (BA contradiction cap).  *)
(* ================================================================= *)

(* ==== F7 (II.4) MAIN sub-lemma BRIDGE: EMBF_VAL_IS_EMB -- the embedding
   function's value embf(cv) at a coordinate-value pair cv EQUALS the
     regular-open
   embedding e({cv}) = eintcl(edownset {cv}) of the singleton condition {cv}.
   Both satisfy the SAME coordemb characterization (COORDEMB_EQ_EMB for
     e({cv}); the
   embf-value char is a hypothesis),
   so ZF-extensionally (ESUBSET_ANTISYM) equal.
   NB: the embf b-char is GUARDED (q IN D ==> ...),
   so it does NOT auto-fire under
   ASM_REWRITE -- it is labelled "bchar" and fired explicitly with USE_THEN. *)

let EMBF_VAL_IS_EMB = prove
 (`!D (E:A->A->bool) P leqp cv p1 dp b ep.
     model D E ZF_AX /\ eleqp D E P leqp /\
     cv IN D /\ p1 IN D /\ E p1 P /\ (!u. u IN D ==> (E u p1 <=> u = cv)) /\
     edownset D E P leqp p1 dp /\
     ep IN D /\ eintcl D E P leqp dp ep /\ b IN D /\
     (!q. q IN D
          ==> (E q b <=>
               E q P /\
               (!r. r IN D /\ erel D E leqp r q
                    ==> ?s. s IN D /\ erel D E leqp s r /\ E cv s)))
     ==> b = ep`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `(dp:A) IN D` ASSUME_TAC THENL
   [FIRST_ASSUM(fun th -> ACCEPT_TAC(CONJUNCT1(REWRITE_RULE[edownset] th)));
    ALL_TAC] THEN
  FIRST_X_ASSUM(LABEL_TAC "bchar" o
    check (fun th -> is_forall(concl th) && vfree_in `b:A` (concl th))) THEN
  SUBGOAL_THEN `!w:A. w IN D ==> ((E:A->A->bool) w b <=> E w ep)`
    ASSUME_TAC THENL
   [X_GEN_TAC `w:A` THEN DISCH_TAC THEN
    (* bchar instance:  E w b <=> E w P /\ coordemb   (as asm) *)
    USE_THEN "bchar" (MP_TAC o SPEC `w:A`) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN DISCH_TAC THEN
    ASM_CASES_TAC `(E:A->A->bool) (w:A) (P:A)` THENL
     [(* E w P: both reduce to coordemb via COORDEMB_EQ_EMB *)
      MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `P:A`; `leqp:A`; `cv:A`;
        `p1:A`; `dp:A`; `ep:A`; `w:A`] COORDEMB_EQ_EMB) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN DISCH_TAC THEN
      ASM_REWRITE_TAC[];
      (* ~E w P: eintcl gives E w ep <=> E w P /\ ...; both reduce to F *)
      UNDISCH_TAC `eintcl D E P leqp dp (ep:A)` THEN REWRITE_TAC[eintcl] THEN
      DISCH_THEN(MP_TAC o SPEC `w:A` o CONJUNCT2) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN DISCH_TAC THEN
      ASM_REWRITE_TAC[]];
    ALL_TAC] THEN
  SUBGOAL_THEN `esubset D (E:A->A->bool) b ep /\ esubset D E ep b`
    STRIP_ASSUME_TAC THENL
   [REWRITE_TAC[esubset] THEN ASM_MESON_TAC[]; ALL_TAC] THEN
  MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `b:A`; `ep:A`]
         ESUBSET_ANTISYM) THEN
  ASM_REWRITE_TAC[]);;

(* ==== F7 (II.4) MAIN sub-lemma L1: COHEN_REALNAME_GRAPH -- from the Cohen
   real name's MEMBERSHIP characterization (COHEN_REALNAME_EXISTS
     output) derive the
   eapply-GRAPH property that COHEN_MEM_VALUE needs as a hypothesis.
     Just unfolds
   eapply (pair in rdot) + the char + EOPAIR_INJ (sig=y, b=qy). *)

let COHEN_REALNAME_GRAPH = prove
 (`!D (E:A->A->bool) om ON embf alpha onetw rdot.
     model D E ZF_AX /\ rdot IN D /\
     (!z. z IN D
          ==> (E z rdot <=>
               ?n sig b p15 cvs. n IN D /\ sig IN D /\ b IN D /\ p15 IN D /\
                   cvs IN D /\ (E:A->A->bool) n (om:A) /\
                   echeck D E ON n sig /\ eopair D E alpha n p15 /\
                   eopair D E p15 onetw cvs /\ eapply D E embf cvs b /\
                   eopair D E sig b z))
     ==> (!y qy. y IN D /\ qy IN D /\ eapply D E rdot y qy
                 ==> ?n' p' cvs'. n' IN D /\ p' IN D /\ cvs' IN D /\
                        echeck D E ON n' y /\ eopair D E alpha n' p' /\
                        eopair D E p' onetw cvs' /\ eapply D E embf cvs' qy)`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  FIRST_X_ASSUM(LABEL_TAC "rchar" o
    check (fun th -> is_forall(concl th) && vfree_in `rdot:A` (concl th))) THEN
  MAP_EVERY X_GEN_TAC [`y:A`; `qy:A`] THEN STRIP_TAC THEN
  UNDISCH_TAC `eapply D (E:A->A->bool) rdot y qy` THEN
  DISCH_THEN(MP_TAC o REWRITE_RULE[eapply]) THEN
  DISCH_THEN(X_CHOOSE_THEN `pp:A` STRIP_ASSUME_TAC) THEN
  SUBGOAL_THEN `(pp:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[EOPAIR_IN]; ALL_TAC] THEN
  USE_THEN "rchar" (MP_TAC o SPEC `pp:A`) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(fun th ->
             MP_TAC(EQ_MP th (ASSUME `(E:A->A->bool) (pp:A) rdot`))) THEN
  DISCH_THEN(X_CHOOSE_THEN `n:A` (X_CHOOSE_THEN `sig:A` (X_CHOOSE_THEN `bb:A`
    (X_CHOOSE_THEN `p15:A` (X_CHOOSE_THEN `cvs:A` STRIP_ASSUME_TAC))))) THEN
  MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `sig:A`; `bb:A`; `y:A`; `qy:A`;
    `pp:A`] EOPAIR_INJ) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(CONJUNCTS_THEN SUBST_ALL_TAC) THEN
  MAP_EVERY EXISTS_TAC [`n:A`; `p15:A`; `cvs:A`] THEN ASM_REWRITE_TAC[]);;

(* ==== F7 (II.4) MAIN sub-lemma L-CONTRA: EMB_FORCING_CONTRA -- the pure
   Boolean-algebra contradiction that caps COHEN_REAL_DISTINCT.  If eq=e(q') is
   below both u=[[ra=rb]] and ba=[[n^ IN ra]], and u (+) ba <= bb=[[n^ IN rb]]
   (the congruence, uba=u(+)ba), while eq (+) bb = bot (mb), yet eq =/= bot, we
   get a contradiction: eq <= uba <= bb so eq (+) bb = eq = bot.
     Forcing-free. *)

let EMB_FORCING_CONTRA = prove
 (`!D (E:A->A->bool) B leq eq u ba bb uba mb.
     model D E ZF_AX /\ eporder D E B leq /\
     eq IN D /\ u IN D /\ ba IN D /\ bb IN D /\
     E eq B /\ E u B /\ E ba B /\ E bb B /\
     erel D E leq eq u /\ erel D E leq eq ba /\
     emeet D E B leq u ba uba /\ erel D E leq uba bb /\
     emeet D E B leq eq bb mb /\ ebot D E B leq mb /\
     ~(ebot D E B leq eq)
     ==> F`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `(uba:A) IN D /\ (E:A->A->bool) uba B` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[EMEET_IN]; ALL_TAC] THEN
  (* eq <= uba  (glb property of emeet u ba uba) *)
  SUBGOAL_THEN `erel D (E:A->A->bool) leq (eq:A) uba` ASSUME_TAC THENL
   [UNDISCH_TAC `emeet D (E:A->A->bool) B leq u ba uba` THEN
    REWRITE_TAC[emeet] THEN
    STRIP_TAC THEN FIRST_X_ASSUM MATCH_MP_TAC THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  (* eq <= bb  (transitivity eq <= uba <= bb) *)
  SUBGOAL_THEN `erel D (E:A->A->bool) leq (eq:A) bb` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `B:A`; `leq:A`;
      `eq:A`; `uba:A`; `bb:A`] EPORDER_TRANS) THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  (* eq <= mb  (glb property of emeet eq bb mb; eq<=eq, eq<=bb) *)
  SUBGOAL_THEN `erel D (E:A->A->bool) leq (eq:A) mb` ASSUME_TAC THENL
   [UNDISCH_TAC `emeet D (E:A->A->bool) B leq eq bb mb` THEN
    REWRITE_TAC[emeet] THEN
    STRIP_TAC THEN FIRST_X_ASSUM MATCH_MP_TAC THEN ASM_REWRITE_TAC[] THEN
    MATCH_MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `B:A`; `leq:A`; `eq:A`]
      EPORDER_REFL) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* mb = eq  (antisym: mb<=eq from EMEET_LE, eq<=mb above) *)
  SUBGOAL_THEN `(mb:A) = eq` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `B:A`; `leq:A`;
      `mb:A`; `eq:A`] EPORDER_ANTISYM) THEN ASM_REWRITE_TAC[] THEN
    ASM_MESON_TAC[EMEET_IN; EMEET_LE]; ALL_TAC] THEN
  UNDISCH_TAC `~(ebot D (E:A->A->bool) B leq (eq:A))` THEN
  UNDISCH_TAC `ebot D (E:A->A->bool) B leq (mb:A)` THEN ASM_REWRITE_TAC[]);;

(* ================================================================= *)
(* F7 (II.4) MAIN: bname(ra) CHAIN -- the Cohen real name ra IS a       *)
(* B-name.  EBNMEM_GENERAL + ECHECK_INDOM + ECHECK_INJ + COHEN_REALNAME_*)
(* ISFUN + COHEN_REALNAME_BNAME.                                        *)
(* ================================================================= *)

(* ==== F7 (II.4) MAIN sub-lemma: EBNMEM_GENERAL -- a function f whose graph
   consists of pairs <u,ww> with u IN w and ww IN B is a bname-at-stage-w
   (ebnmem).  Generalizes ECHECK_EBNMEM (which is check-specific) by
     taking eisfun
   and the pair-decomposition (incl. ww IN B) as hypotheses.  Feeds
     COHEN_REALNAME_
   BNAME (ra = {<n^,b>:n<om} is a function into w x B => a bname). *)

let EBNMEM_GENERAL = prove
 (`!D (E:A->A->bool) B f w.
     model D E ZF_AX /\ B IN D /\ f IN D /\ w IN D /\ eisfun D E f /\
     (!z. z IN D /\ E z f
          ==> ?u ww. u IN D /\ ww IN D /\ E u w /\ E ww B /\ eopair D E u ww z)
     ==> ebnmem D E B w f`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  REWRITE_TAC[ebnmem] THEN ASM_REWRITE_TAC[] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `w:A`; `B:A`] ECROSS_EXISTS) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `cr:A` (LABEL_TAC "cross")) THEN
  SUBGOAL_THEN `(cr:A) IN D` ASSUME_TAC THENL
   [USE_THEN "cross" (MP_TAC o REWRITE_RULE[ecross]) THEN SIMP_TAC[];
    ALL_TAC] THEN
  EXISTS_TAC `cr:A` THEN ASM_REWRITE_TAC[esubset] THEN
  X_GEN_TAC `z:A` THEN STRIP_TAC THEN
  FIRST_X_ASSUM(MP_TAC o SPEC `z:A`) THEN ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `u:A` (X_CHOOSE_THEN `ww:A` STRIP_ASSUME_TAC)) THEN
  USE_THEN "cross"
    (MP_TAC o SPEC `z:A` o CONJUNCT2 o REWRITE_RULE[ecross]) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  MAP_EVERY EXISTS_TAC [`u:A`; `ww:A`] THEN ASM_REWRITE_TAC[]);;

(* ==== F7 (II.4) MAIN base-dependency: ECHECK_INDOM -- m IN x ==>
  m^ IN dom(x^).
   The check-name x^ has <m^,
   onebee> as an element for every m IN x (ECHECK_MEM
   backward), so m^ is in the domain of x^.  Base step for ECHECK_INJ (check
   injectivity), which feeds eisfun(ra) and hence bname(ra). *)

let ECHECK_INDOM = prove
 (`!D (E:A->A->bool) onebee x v m vm.
     model D E ZF_AX /\ onebee IN D /\ echeck D E onebee x v /\
     m IN D /\ E m x /\ echeck D E onebee m vm /\ vm IN D
     ==> eindom D E v vm`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `(v:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[ECHECK_IMP]; ALL_TAC] THEN
  REWRITE_TAC[eindom] THEN EXISTS_TAC `onebee:A` THEN
  ASM_REWRITE_TAC[eapply] THEN
  MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `vm:A`; `onebee:A`]
         EOPAIR_EXISTS) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_TAC `z:A`) THEN
  SUBGOAL_THEN `(z:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[EOPAIR_IN]; ALL_TAC] THEN
  EXISTS_TAC `z:A` THEN ASM_REWRITE_TAC[] THEN
  MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `onebee:A`; `x:A`; `v:A`; `z:A`]
    ECHECK_MEM) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  MAP_EVERY EXISTS_TAC [`m:A`; `vm:A`] THEN ASM_REWRITE_TAC[]);;

(* ==== F7 (II.4) MAIN base-dependency: ECHECK_INJ -- check-names are
  injective on
   ordinals: echeck ON n v /\ echeck ON n' v ==>
     n = n'.  Via EORDINAL_TRICHOTOMY:
   if n IN n' (or n' IN n) then ECHECK_INDOM gives n^=v IN dom(n'^=v), i.e.
   eindom v v, so eapply v v w for some w;
   but v is a bname and EBNRANK_APPLY_LT
   makes the bn-rank strictly decrease,
   giving E rv rv -- impossible (E_IRREFL).
   Feeds COHEN_REALNAME_ISFUN (eisfun ra) and hence COHEN_REALNAME_BNAME. *)

let ECHECK_INJ = prove
 (`!D (E:A->A->bool) B onebee n n' v.
     model D E ZF_AX /\ B IN D /\ onebee IN D /\ E onebee B /\
     eordinal D E n /\ eordinal D E n' /\ n IN D /\ n' IN D /\
     echeck D E onebee n v /\ echeck D E onebee n' v
     ==> n = n'`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `(v:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[ECHECK_IMP]; ALL_TAC] THEN
  SUBGOAL_THEN `bname D (E:A->A->bool) B v` ASSUME_TAC THENL
   [ASM_MESON_TAC[ECHECK_IS_BNAME]; ALL_TAC] THEN
  SUBGOAL_THEN `!w:A. w IN D /\ eapply D (E:A->A->bool) v v w ==> F`
    (LABEL_TAC "noself") THENL
   [X_GEN_TAC `w:A` THEN STRIP_TAC THEN
    MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `B:A`; `v:A`]
           EBNRANK_EXISTS) THEN
    ASM_REWRITE_TAC[] THEN
    DISCH_THEN(X_CHOOSE_THEN `rv:A` STRIP_ASSUME_TAC) THEN
    MP_TAC(ISPECL
           [`D:A->bool`; `E:A->A->bool`; `B:A`; `v:A`; `v:A`; `w:A`; `rv:A`]
           EBNRANK_APPLY_LT) THEN ASM_REWRITE_TAC[] THEN
    DISCH_THEN(X_CHOOSE_THEN `ry:A` STRIP_ASSUME_TAC) THEN
    SUBGOAL_THEN `(ry:A) = rv` SUBST_ALL_TAC THENL
     [ASM_MESON_TAC[EBNRANK_UNIQUE]; ALL_TAC] THEN
    ASM_MESON_TAC[E_IRREFL; EBNRANK_IN]; ALL_TAC] THEN
  MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `n:A`; `n':A`]
         EORDINAL_TRICHOTOMY) THEN
  ASM_REWRITE_TAC[] THEN STRIP_TAC THENL
   [MP_TAC(ISPECL
           [`D:A->bool`; `E:A->A->bool`; `onebee:A`; `n':A`; `v:A`; `n:A`;
            `v:A`] ECHECK_INDOM) THEN ASM_REWRITE_TAC[] THEN
    REWRITE_TAC[eindom] THEN
    DISCH_THEN(X_CHOOSE_THEN `w:A` STRIP_ASSUME_TAC) THEN
    ASM_MESON_TAC[];
    MP_TAC(ISPECL
           [`D:A->bool`; `E:A->A->bool`; `onebee:A`; `n:A`; `v:A`; `n':A`;
            `v:A`] ECHECK_INDOM) THEN ASM_REWRITE_TAC[] THEN
    REWRITE_TAC[eindom] THEN
    DISCH_THEN(X_CHOOSE_THEN `w:A` STRIP_ASSUME_TAC) THEN
    ASM_MESON_TAC[]]);;

(* ==== F7 (II.4) MAIN sub-lemma: COHEN_REALNAME_ISFUN -- the Cohen
  real name ra is
   a FUNCTION (eisfun), from its membership char.  Every element is a pair
   <sig,b>; single-valued because <u,w>,<u,w'> in ra give
     (EOPAIR_INJ) sig=u=sig',
   so echeck ON n sig /\ echeck ON n' sig => n=n' (ECHECK_INJ; n,n' ordinals by
   EOMEGA_ORDINALS) => p15=p15' => cvs=cvs' (EOPAIR_UNIQUE) => w=b=b'=w'
   (EAPPLY_UNIQUE, eisfun embf).  Feeds COHEN_REALNAME_BNAME.
   NB rchar is a GUARDED iff asm -> extract via ANTS + EQ_MP (NOT
     MP_TAC+ASM_REWRITE,
   which collapses the implication since rchar proves its own just-MP'd
     instance). *)

let COHEN_REALNAME_ISFUN = prove
 (`!D (E:A->A->bool) B onebee om embf alpha onetw ra.
     model D E ZF_AX /\ B IN D /\ onebee IN D /\ E onebee B /\
     eomega D E om /\ embf IN D /\ eisfun D E embf /\ ra IN D /\
     (!z. z IN D
          ==> (E z ra <=>
               ?n sig b p15 cvs. n IN D /\ sig IN D /\ b IN D /\ p15 IN D /\
                   cvs IN D /\ (E:A->A->bool) n (om:A) /\
                   echeck D E onebee n sig /\ eopair D E alpha n p15 /\
                   eopair D E p15 onetw cvs /\ eapply D E embf cvs b /\
                   eopair D E sig b z))
     ==> eisfun D E ra`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  FIRST_X_ASSUM(LABEL_TAC "rchar" o
    check (fun th -> is_forall(concl th) && vfree_in `ra:A` (concl th))) THEN
  REWRITE_TAC[eisfun] THEN ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
   [(* every element of ra is a pair *)
    X_GEN_TAC `z:A` THEN STRIP_TAC THEN
    USE_THEN "rchar" (MP_TAC o SPEC `z:A`) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> MP_TAC(EQ_MP th (ASSUME `(E:A->A->bool) z ra`))) THEN
    DISCH_THEN(X_CHOOSE_THEN `n:A` (X_CHOOSE_THEN `sig:A` (X_CHOOSE_THEN `b:A`
      (X_CHOOSE_THEN `p15:A` (X_CHOOSE_THEN `cvs:A` STRIP_ASSUME_TAC))))) THEN
    MAP_EVERY EXISTS_TAC [`sig:A`; `b:A`] THEN ASM_REWRITE_TAC[];
    (* single-valued *)
    MAP_EVERY X_GEN_TAC [`u:A`; `w:A`; `w':A`; `z:A`; `z':A`] THEN
    STRIP_TAC THEN
    SUBGOAL_THEN `(z:A) IN D /\ (z':A) IN D` STRIP_ASSUME_TAC THENL
     [ASM_MESON_TAC[EOPAIR_IN]; ALL_TAC] THEN
    USE_THEN "rchar" (MP_TAC o SPEC `z:A`) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> MP_TAC(EQ_MP th (ASSUME `(E:A->A->bool) z ra`))) THEN
    DISCH_THEN(X_CHOOSE_THEN `n1:A`
               (X_CHOOSE_THEN `sig1:A` (X_CHOOSE_THEN `b1:A`
                                        (X_CHOOSE_THEN `p1:A`
                                         (X_CHOOSE_THEN `cvs1:A`
                                          STRIP_ASSUME_TAC))))) THEN
    USE_THEN "rchar" (MP_TAC o SPEC `z':A`) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> MP_TAC(EQ_MP th (ASSUME `(E:A->A->bool) z' ra`))) THEN
    DISCH_THEN(X_CHOOSE_THEN `n2:A`
               (X_CHOOSE_THEN `sig2:A` (X_CHOOSE_THEN `b2:A`
                                        (X_CHOOSE_THEN `p2:A`
                                         (X_CHOOSE_THEN `cvs2:A`
                                          STRIP_ASSUME_TAC))))) THEN
    MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `u:A`; `w:A`; `sig1:A`; `b1:A`;
      `z:A`] EOPAIR_INJ) THEN ASM_REWRITE_TAC[] THEN STRIP_TAC THEN
    MP_TAC(ISPECL
           [`D:A->bool`; `E:A->A->bool`; `u:A`; `w':A`; `sig2:A`; `b2:A`;
            `z':A`] EOPAIR_INJ) THEN ASM_REWRITE_TAC[] THEN STRIP_TAC THEN
    SUBGOAL_THEN `(n1:A) = n2` SUBST_ALL_TAC THENL
     [MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `B:A`; `onebee:A`; `n1:A`;
        `n2:A`; `sig1:A`] ECHECK_INJ) THEN ASM_REWRITE_TAC[] THEN
      DISCH_THEN MATCH_MP_TAC THEN ASM_MESON_TAC[EOMEGA_ORDINALS];
      ALL_TAC] THEN
    SUBGOAL_THEN `(p1:A) = p2` SUBST_ALL_TAC THENL
     [ASM_MESON_TAC[EOPAIR_UNIQUE]; ALL_TAC] THEN
    SUBGOAL_THEN `(cvs1:A) = cvs2` SUBST_ALL_TAC THENL
     [ASM_MESON_TAC[EOPAIR_UNIQUE]; ALL_TAC] THEN
    SUBGOAL_THEN `(b1:A) = b2` SUBST_ALL_TAC THENL
     [ASM_MESON_TAC[EAPPLY_UNIQUE]; ALL_TAC] THEN
    ASM_REWRITE_TAC[]]);;

(* ==== F7 (II.4) MAIN sub-lemma: COHEN_REALNAME_BNAME -- the Cohen
  real name ra is
   a B-NAME.  ra = {<n^,b>:n<om}: a function (COHEN_REALNAME_ISFUN)
     whose domain
   elements are check-names hence bnames (COHEN_REALNAME_GRAPH +
     ECHECK_IS_BNAME),
   bounded in a common stage (BNAME_BOUND); then ra sits in the next stage
   (EBNMEM_GENERAL into w1 x B + EBNSTAGE_CHAR/ebnfuns +
     BNAME_STAGE).  Mirror of
   ESEPNAME_BNAME.  Needs embf-into-B.
   NB: NEVER ASM_MESON with rchar/graph (nested-forall-exists) in context
     -> diverges;
   extract the edomain membership char explicitly (domch) instead. *)

let COHEN_REALNAME_BNAME = prove
 (`!D (E:A->A->bool) B onebee om embf alpha onetw ra.
     model D E ZF_AX /\ B IN D /\ onebee IN D /\ E onebee B /\
     eomega D E om /\ embf IN D /\ eisfun D E embf /\ ra IN D /\
     (!z. z IN D
          ==> (E z ra <=>
               ?n sig b p15 cvs. n IN D /\ sig IN D /\ b IN D /\ p15 IN D /\
                   cvs IN D /\ (E:A->A->bool) n (om:A) /\
                   echeck D E onebee n sig /\ eopair D E alpha n p15 /\
                   eopair D E p15 onetw cvs /\ eapply D E embf cvs b /\
                   eopair D E sig b z)) /\
     (!cvs bb. cvs IN D /\ bb IN D /\ eapply D E embf cvs bb ==> E bb B)
     ==> bname D E B ra`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  FIRST_X_ASSUM(LABEL_TAC "embfB" o
    check (fun th -> is_forall(concl th) &&
                     not(vfree_in `ra:A` (concl th)) &&
                       vfree_in `embf:A` (concl th))) THEN
  FIRST_X_ASSUM(LABEL_TAC "rchar" o
    check (fun th -> is_forall(concl th) && vfree_in `ra:A` (concl th))) THEN
  SUBGOAL_THEN `eisfun D (E:A->A->bool) ra` ASSUME_TAC THENL
   [MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `B:A`; `onebee:A`; `om:A`;
      `embf:A`; `alpha:A`; `onetw:A`; `ra:A`] COHEN_REALNAME_ISFUN) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `om:A`; `onebee:A`; `embf:A`;
    `alpha:A`; `onetw:A`; `ra:A`] COHEN_REALNAME_GRAPH) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(LABEL_TAC "graph") THEN
  MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `ra:A`] EDOMAIN_EXISTS) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `dra:A` (CONJUNCTS_THEN2 (LABEL_TAC "draD")
    (LABEL_TAC "domch") o REWRITE_RULE[edomain])) THEN
  (* every element of dra is a bname *)
  SUBGOAL_THEN `!u:A. u IN D /\ E u dra ==> bname D (E:A->A->bool) B u`
    (LABEL_TAC "drabn") THENL
   [X_GEN_TAC `u:A` THEN STRIP_TAC THEN
    USE_THEN "domch" (MP_TAC o SPEC `u:A`) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> MP_TAC(EQ_MP th (ASSUME `(E:A->A->bool) u dra`))) THEN
    REWRITE_TAC[eindom] THEN
    DISCH_THEN(X_CHOOSE_THEN `q:A` STRIP_ASSUME_TAC) THEN
    USE_THEN "graph" (MP_TAC o SPECL [`u:A`; `q:A`]) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(X_CHOOSE_THEN `n':A` (X_CHOOSE_THEN `p':A`
      (X_CHOOSE_THEN `cvs':A` STRIP_ASSUME_TAC))) THEN
    MATCH_MP_TAC(ISPECL
                 [`D:A->bool`; `E:A->A->bool`; `onebee:A`; `B:A`; `n':A`;
                  `u:A`] ECHECK_IS_BNAME) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `B:A`; `dra:A`] BNAME_BOUND) THEN
  ASM_REWRITE_TAC[] THEN
  INTRO_TAC "@c yc. cD ycD cord ycstage ycsub" THEN
  MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `c:A`] ESUC_EXISTS) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `sa:A`) THEN
  SUBGOAL_THEN
    `(sa:A) IN D /\ eordinal D (E:A->A->bool) sa /\ (E:A->A->bool) c sa`
    STRIP_ASSUME_TAC THENL
   [REPEAT CONJ_TAC THENL
     [MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `c:A`; `sa:A`] ESUC_IN) THEN
      ASM_REWRITE_TAC[];
      MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `c:A`; `sa:A`]
             EORDINAL_ESUC) THEN
      ASM_REWRITE_TAC[];
      MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `c:A`; `sa:A`]
             ESUC_MEMBER) THEN
      ASM_REWRITE_TAC[]]; ALL_TAC] THEN
  MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `B:A`; `sa:A`]
         EBNSTAGE_EXISTS) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `ysa:A` STRIP_ASSUME_TAC) THEN
  MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `B:A`; `sa:A`; `ysa:A`]
         EBNSTAGE_CHAR) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `w1:A` (CONJUNCTS_THEN2 (LABEL_TAC "w1D")
    (CONJUNCTS_THEN2 (LABEL_TAC "w1ch") (LABEL_TAC "funs")))) THEN
  SUBGOAL_THEN `!u:A. u IN D /\ (E:A->A->bool) u yc ==> E u w1`
    (LABEL_TAC "Ysub") THENL
   [X_GEN_TAC `u:A` THEN STRIP_TAC THEN
    USE_THEN "w1ch" (MP_TAC o SPEC `u:A`) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    MAP_EVERY EXISTS_TAC [`c:A`; `yc:A`] THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  REMOVE_THEN "w1ch" (K ALL_TAC) THEN
  SUBGOAL_THEN `ebnmem D (E:A->A->bool) B w1 ra` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `B:A`; `ra:A`; `w1:A`]
      EBNMEM_GENERAL) THEN ASM_REWRITE_TAC[] THEN
    X_GEN_TAC `z:A` THEN STRIP_TAC THEN
    USE_THEN "rchar" (MP_TAC o SPEC `z:A`) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> MP_TAC(EQ_MP th (ASSUME `(E:A->A->bool) z ra`))) THEN
    DISCH_THEN(X_CHOOSE_THEN `n:A` (X_CHOOSE_THEN `sig:A` (X_CHOOSE_THEN `b:A`
      (X_CHOOSE_THEN `p15:A` (X_CHOOSE_THEN `cvs:A` STRIP_ASSUME_TAC))))) THEN
    MAP_EVERY EXISTS_TAC [`sig:A`; `b:A`] THEN ASM_REWRITE_TAC[] THEN
    CONJ_TAC THENL
     [USE_THEN "Ysub" MATCH_MP_TAC THEN ASM_REWRITE_TAC[] THEN
      USE_THEN "ycsub" MATCH_MP_TAC THEN ASM_REWRITE_TAC[] THEN
      USE_THEN "domch" (MP_TAC o SPEC `sig:A`) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
      REWRITE_TAC[eindom] THEN EXISTS_TAC `b:A` THEN
      ASM_REWRITE_TAC[eapply] THEN EXISTS_TAC `z:A` THEN ASM_REWRITE_TAC[];
      USE_THEN "embfB" MATCH_MP_TAC THEN EXISTS_TAC `cvs:A` THEN
      ASM_REWRITE_TAC[]];
    ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) ra ysa` ASSUME_TAC THENL
   [UNDISCH_TAC `ebnfuns D (E:A->A->bool) B w1 ysa` THEN
    REWRITE_TAC[ebnfuns] THEN
    DISCH_THEN(MP_TAC o SPEC `ra:A` o CONJUNCT2) THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  REWRITE_TAC[bname] THEN MAP_EVERY EXISTS_TAC [`sa:A`; `ysa:A`] THEN
  ASM_REWRITE_TAC[]);;

(* ==== F7 (II.4) MAIN sub-lemma M-MEMVAL: COHEN_MEM_VALUE_REAL -- for n IN om,
   the Boolean value [[ n^ IN ra ]] = embf(<<alpha,n>,onetw>) = bb.  Packages
   COHEN_MEM_VALUE with its prerequisites (bname ra via COHEN_REALNAME_BNAME,
   the eapply-graph via COHEN_REALNAME_GRAPH, and eapply ra nch bb derived from
   ra's membership char) discharged internally.  Reusable for both
     ra and rb. *)

let COHEN_MEM_VALUE_REAL = prove
 (`!D (E:A->A->bool) B leq onebee embf alpha onetw om ra n nch p15 cvs bb z.
     model D E ZF_AX /\ (!u:A. u IN D ==> elmem D E u) /\
     ecba D E B leq /\ B IN D /\ leq IN D /\ onebee IN D /\ E onebee B /\
     etop D E B leq onebee /\
     embf IN D /\ eisfun D E embf /\
     (!cvs' bb'. cvs' IN D /\ bb' IN D /\
      eapply D E embf cvs' bb' ==> E bb' B) /\
     eomega D E om /\ ra IN D /\
     (!zz. zz IN D
          ==> (E zz ra <=>
               ?nn sig bq p pc. nn IN D /\ sig IN D /\ bq IN D /\ p IN D /\
                   pc IN D /\ (E:A->A->bool) nn (om:A) /\
                   echeck D E onebee nn sig /\ eopair D E alpha nn p /\
                   eopair D E p onetw pc /\ eapply D E embf pc bq /\
                   eopair D E sig bq zz)) /\
     n IN D /\ (E:A->A->bool) n om /\ alpha IN D /\ onetw IN D /\
     nch IN D /\ echeck D E onebee n nch /\ p15 IN D /\ cvs IN D /\
     eopair D E alpha n p15 /\ eopair D E p15 onetw cvs /\
     eapply D E embf cvs bb /\ bb IN D /\ E bb B /\
     z IN D /\ ebv_in D E B leq nch ra z
     ==> z = bb`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  FIRST_X_ASSUM(LABEL_TAC "rchar" o
    check (fun th -> is_forall(concl th) && vfree_in `ra:A` (concl th))) THEN
  FIRST_X_ASSUM(LABEL_TAC "embfB" o
    check (fun th -> is_forall(concl th) &&
                     not(vfree_in `ra:A` (concl th)) &&
                       vfree_in `embf:A` (concl th))) THEN
  (* bname ra *)
  SUBGOAL_THEN `bname D (E:A->A->bool) B ra` ASSUME_TAC THENL
   [MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `B:A`; `onebee:A`; `om:A`;
      `embf:A`; `alpha:A`; `onetw:A`; `ra:A`] COHEN_REALNAME_BNAME) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* eapply-graph of ra *)
  MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `om:A`; `onebee:A`; `embf:A`;
    `alpha:A`; `onetw:A`; `ra:A`] COHEN_REALNAME_GRAPH) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(LABEL_TAC "graph") THEN
  (* eapply ra nch bb : <nch,bb> IN ra via rchar *)
  SUBGOAL_THEN `eapply D (E:A->A->bool) ra nch bb` ASSUME_TAC THENL
   [REWRITE_TAC[eapply] THEN
    MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `nch:A`; `bb:A`]
           EOPAIR_EXISTS) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(X_CHOOSE_TAC `pr:A`) THEN
    SUBGOAL_THEN `(pr:A) IN D` ASSUME_TAC THENL
     [ASM_MESON_TAC[EOPAIR_IN]; ALL_TAC] THEN
    EXISTS_TAC `pr:A` THEN ASM_REWRITE_TAC[] THEN
    USE_THEN "rchar" (MP_TAC o SPEC `pr:A`) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    MAP_EVERY EXISTS_TAC [`n:A`; `nch:A`; `bb:A`; `p15:A`; `cvs:A`] THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* now COHEN_MEM_VALUE *)
  MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `B:A`; `leq:A`; `onebee:A`;
    `embf:A`; `ra:A`; `alpha:A`; `onetw:A`; `n:A`; `nch:A`; `p15:A`; `cvs:A`;
    `bb:A`; `z:A`] COHEN_MEM_VALUE) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN MATCH_MP_TAC THEN
  USE_THEN "graph" (fun th -> MP_TAC th) THEN
  REWRITE_TAC[] THEN DISCH_TAC THEN ASM_REWRITE_TAC[]);;

(* ==== F7 (II.4 tie) helper: COHEN_EXTEND1_FUNCTIONAL -- extend
  functional r0 by
   ONE coord cva=<pa,va> with pa not in dom(r0).  4-case (template:
     EXTEND2). *)
let COHEN_EXTEND1_FUNCTIONAL = prove
 (`!D (E:A->A->bool) r0 pa va cva p1 q1.
     model D E ZF_AX /\ efunctional D E r0 /\ r0 IN D /\
     pa IN D /\ va IN D /\
     eopair D E pa va cva /\
     (!ww zz. ww IN D /\ zz IN D /\ eopair D E pa ww zz ==> ~E zz r0) /\
     p1 IN D /\ (!uu. uu IN D ==> (E uu p1 <=> uu = cva)) /\
     ebunion D E r0 p1 q1
     ==> efunctional D E q1`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  FIRST_X_ASSUM(LABEL_TAC "pad" o check (fun t ->
     is_forall(concl t) && vfree_in `pa:A` (concl t))) THEN
  SUBGOAL_THEN `(q1:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[EBUNION_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `!z z' u w w':A.
       z IN D /\ z' IN D /\ u IN D /\ w IN D /\ w' IN D /\
       E z r0 /\ E z' r0 /\ eopair D E u w z /\ eopair D E u w' z' ==> w = w'`
   (LABEL_TAC "fr0") THENL
   [REPEAT STRIP_TAC THEN UNDISCH_TAC `efunctional D (E:A->A->bool) r0` THEN
    REWRITE_TAC[efunctional] THEN DISCH_THEN MATCH_MP_TAC THEN
    MAP_EVERY EXISTS_TAC [`z:A`; `z':A`; `u:A`] THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
    `!zz:A. zz IN D ==> ((E:A->A->bool) zz q1 <=> E zz r0 \/ zz = cva)`
   (LABEL_TAC "qmem") THENL
   [X_GEN_TAC `zz:A` THEN DISCH_TAC THEN
    MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `r0:A`; `p1:A`; `q1:A`]
           EBUNION_ALT) THEN
    ASM_REWRITE_TAC[] THEN DISCH_THEN(MP_TAC o SPEC `zz:A`) THEN
    ASM_REWRITE_TAC[] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    FIRST_X_ASSUM(MP_TAC o SPEC `zz:A` o check (fun t -> is_forall(concl t) &&
       vfree_in `p1:A` (concl t))) THEN ASM_REWRITE_TAC[] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]); ALL_TAC] THEN
  REWRITE_TAC[efunctional] THEN
  MAP_EVERY X_GEN_TAC [`z:A`; `z':A`; `u:A`; `w:A`; `w':A`] THEN STRIP_TAC THEN
  SUBGOAL_THEN `(E:A->A->bool) z r0 \/ z = cva` (LABEL_TAC "dz") THENL
   [ASM_MESON_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) z' r0 \/ z' = cva` (LABEL_TAC "dz2") THENL
   [ASM_MESON_TAC[]; ALL_TAC] THEN
  USE_THEN "dz"
    (DISJ_CASES_THEN (fun th -> SUBST_ALL_TAC th ORELSE ASSUME_TAC th)) THEN
  USE_THEN "dz2"
    (DISJ_CASES_THEN (fun th -> SUBST_ALL_TAC th ORELSE ASSUME_TAC th)) THEN
  TRY(USE_THEN "fr0" MATCH_MP_TAC THEN
      MAP_EVERY EXISTS_TAC [`z:A`; `z':A`; `u:A`] THEN
      ASM_REWRITE_TAC[] THEN NO_TAC) THEN
  ASM_MESON_TAC[EOPAIR_INJ]);;
(* ============================================================= *)
(* F7 (II.4) MAIN tie-together: COHEN_REAL_DISTINCT.              *)
(* alpha =/= beta  ==>  [[ rdot_alpha = rdot_beta ]] = bot.       *)
(* Helper EINHAB_NONBOT (inhabited regular-open set is not bot).  *)
(* ============================================================= *)

(* ==== F7 (II.4 tie) helper: EINHAB_NONBOT -- a regular-open set m that has a
   member r is NOT the bottom of B.  (The bottom is the empty set: EBOT_ROSET
   makes the empty set a bottom, EBOT_UNIQUE forces m = empty if m were bottom,
   contradicting E r m.)  Used to discharge the `~ebot e(q')` hypothesis of
   EMB_FORCING_CONTRA, with E q' e(q') supplied by EMB_NONBOT. *)

let EINHAB_NONBOT = prove
 (`!D (E:A->A->bool) P leqp B inclB m r.
     model D E ZF_AX /\ eleqp D E P leqp /\ eroset D E P leqp B /\
     eincl D E B inclB /\ ecba D E B inclB /\
     m IN D /\ r IN D /\ E r m
     ==> ~ebot D E B inclB m`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN DISCH_TAC THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`] EEMPTY_EXISTS) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_THEN `ze:A` (LABEL_TAC "mt")) THEN
  SUBGOAL_THEN `(ze:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[EEMPTY_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `ebot D (E:A->A->bool) B inclB ze` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`P:A`;`leqp:A`;`B:A`;
                  `inclB:A`;`ze:A`]
                 EBOT_ROSET) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(m:A) = ze` SUBST_ALL_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`B:A`;`inclB:A`;`m:A`;`ze:A`]
                 EBOT_UNIQUE) THEN ASM_REWRITE_TAC[] THEN
    MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`inclB:A`]
                 ECBA_IMP_PORDER) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  UNDISCH_TAC `eempty D (E:A->A->bool) ze` THEN REWRITE_TAC[eempty] THEN
  DISCH_THEN(MP_TAC o SPEC `r:A` o CONJUNCT2) THEN ASM_REWRITE_TAC[]);;

let COHEN_REAL_DISTINCT =
  let etotchk t =
    is_forall(concl t) && vfree_in `ci:A`(concl t) &&
    not(vfree_in `B:A`(concl t)) && not(vfree_in `P:A`(concl t)) in
  prove
 (`!D (E:A->A->bool) P leqp ci om iibase ii tw onebee embf B leq
      alpha beta onetw ztw ra rb u.
     model D E ZF_AX /\ (!v:A. v IN D ==> elmem D E v) /\
     eomega D E om /\
     embf IN D /\ eisfun D E embf /\
     (!cvs bb. cvs IN D /\ bb IN D /\ eapply D E embf cvs bb ==> E bb B) /\
     (!cvs. cvs IN D /\ (E:A->A->bool) cvs ci ==> ?bq. bq IN D /\
      eapply D E embf cvs bq) /\
     (!z. z IN D
          ==> (E z embf <=>
               ?cv bq. cv IN D /\ bq IN D /\ (E:A->A->bool) cv ci /\
                   eopair D E cv bq z /\
                   (!q. q IN D
                        ==> (E q bq <=>
                             E q P /\
                             (!r. r IN D /\ erel D E leqp r q
                                  ==> ?s. s IN D /\ erel D E leqp s r /\
                                    E cv s))))) /\
     ecross D E iibase om ii /\ ecross D E ii tw ci /\
     eleqp D E P leqp /\ ecohenp D E ci om P /\
     eroset D E P leqp B /\ eincl D E B leq /\ ecba D E B leq /\
     B IN D /\ leq IN D /\ onebee IN D /\ E onebee B /\
       etop D E B leq onebee /\
     alpha IN D /\ beta IN D /\ E alpha iibase /\ E beta iibase /\
       ~(alpha = beta) /\
     onetw IN D /\ E onetw tw /\ ztw IN D /\ E ztw tw /\ ~(onetw = ztw) /\
     ra IN D /\
     (!zz. zz IN D ==>
      (E zz ra <=> ?n sig b p pc. n IN D /\ sig IN D /\ b IN D /\
       p IN D /\ pc IN D /\ (E:A->A->bool) n om /\ echeck D E onebee n sig /\
         eopair D E alpha n p /\ eopair D E p onetw pc /\
           eapply D E embf pc b /\
         eopair D E sig b zz)) /\
     rb IN D /\
     (!zz. zz IN D ==>
      (E zz rb <=> ?n sig b p pc. n IN D /\ sig IN D /\ b IN D /\
       p IN D /\ pc IN D /\ (E:A->A->bool) n om /\ echeck D E onebee n sig /\
         eopair D E beta n p /\ eopair D E p onetw pc /\
           eapply D E embf pc b /\
         eopair D E sig b zz)) /\
     u IN D /\ E u B /\ ebv_eq D E B leq ra rb u
     ==> ebot D E B leq u`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN
    `(P:A) IN D /\ (leqp:A) IN D /\ (om:A) IN D /\ (ii:A) IN D /\ (ci:A) IN D`
    STRIP_ASSUME_TAC THENL
   [REPEAT CONJ_TAC THENL
     [ASM_MESON_TAC[ecohenp]; ASM_MESON_TAC[eleqp];
      ASM_MESON_TAC[eomega; einductive];
      ASM_MESON_TAC[ecross]; ASM_MESON_TAC[ecross]]; ALL_TAC] THEN
  ASM_CASES_TAC `ebot D (E:A->A->bool) B leq u` THENL
  [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`P:A`;`leqp:A`;`B:A`;`leq:A`;`u:A`]
         ENONBOT_INHAB) THEN ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `r0:A` STRIP_ASSUME_TAC) THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`P:A`;`leqp:A`;`B:A`;`u:A`;`r0:A`]
         RO_POS_HAS_EMB) THEN ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `dr0e:A`
             (X_CHOOSE_THEN `er0:A` STRIP_ASSUME_TAC)) THEN
