  [ASM_MESON_TAC[edomain]; ALL_TAC] THEN
  MP_TAC(ISPECL
         [`D:A->bool`;`E:A->A->bool`;`iibase:A`;`om:A`;`ii:A`;`tw:A`;`ci:A`;
