(* ==== F7 (II.5) lemma: COHEN_REAL_SUBSET_OMEGA -- [[ ra SUBSET om^ ]] = top.
   Every domain elt of ra is a check n^ (n IN om) and [[n^ IN om^]]=top
   (ECHECK_IN_TOP), so every subset-combiner is top; glb (esubval) = top
   (ESUBVAL_GREATEST).  II.5: alpha|->ra lands in P(om^). *)

let COHEN_REAL_SUBSET_OMEGA = prove
 (`!D (E:A->A->bool) B leq onebee embf alpha onetw om ra omch z.
     model D E ZF_AX /\
     ecba D E B leq /\ B IN D /\ leq IN D /\ onebee IN D /\ E onebee B /\
     etop D E B leq onebee /\
     embf IN D /\ eisfun D E embf /\
     (!cvs' bb'. cvs' IN D /\ bb' IN D /\
      eapply D E embf cvs' bb' ==> E bb' B) /\
     eomega D E om /\ ra IN D /\
     (!zz. zz IN D
          ==> (E zz ra <=>
               ?nn sig bq p pc. nn IN D /\ sig IN D /\ bq IN D /\ p IN D /\
                   pc IN D /\ (E:A->A->bool) nn (om:A) /\
                   echeck D E onebee nn sig /\ eopair D E alpha nn p /\
                   eopair D E p onetw pc /\ eapply D E embf pc bq /\
                   eopair D E sig bq zz)) /\
     alpha IN D /\ onetw IN D /\ om IN D /\
     echeck D E onebee om omch /\ omch IN D /\
     esubval D E B leq omch ra z /\ z IN D
     ==> etop D E B leq z`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  FIRST_X_ASSUM(LABEL_TAC "rchar" o
   check (fun th -> is_forall(concl th) && vfree_in `ra:A` (concl th))) THEN
  SUBGOAL_THEN `ebalg D (E:A->A->bool) B leq` ASSUME_TAC THENL
   [ASM_MESON_TAC[ECBA_IMP_BALG]; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq onebee z` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`omch:A`;`ra:A`;
                  `z:A`;`onebee:A`] ESUBVAL_GREATEST) THEN
    ASM_REWRITE_TAC[] THEN X_GEN_TAC `c:A` THEN REWRITE_TAC[esubcomb] THEN
    DISCH_THEN(X_CHOOSE_THEN `v:A`
               (X_CHOOSE_THEN `qv:A`
                (X_CHOOSE_THEN `z2:A` STRIP_ASSUME_TAC))) THEN
    UNDISCH_TAC `eapply D (E:A->A->bool) ra v qv` THEN REWRITE_TAC[eapply] THEN
    DISCH_THEN(X_CHOOSE_THEN `pr:A`
               (CONJUNCTS_THEN2 (LABEL_TAC "propair") (LABEL_TAC "prra"))) THEN
    SUBGOAL_THEN `(pr:A) IN D` ASSUME_TAC THENL
    [ASM_MESON_TAC[EOPAIR_IN]; ALL_TAC] THEN
    USE_THEN "rchar" (MP_TAC o SPEC `pr:A`) THEN ANTS_TAC THENL
    [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> MP_TAC(EQ_MP th (ASSUME `(E:A->A->bool) pr ra`))) THEN
    DISCH_THEN(X_CHOOSE_THEN `nn:A`
               (X_CHOOSE_THEN `sig:A` (X_CHOOSE_THEN `bb:A`
                                       (X_CHOOSE_THEN `p15:A`
                                        (X_CHOOSE_THEN `cvs:A`
                                         STRIP_ASSUME_TAC))))) THEN
    MP_TAC(ISPECL
           [`D:A->bool`;`E:A->A->bool`;`v:A`;`qv:A`;`sig:A`;`bb:A`;`pr:A`]
           EOPAIR_INJ) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(CONJUNCTS_THEN SUBST_ALL_TAC) THEN
    SUBGOAL_THEN `etop D (E:A->A->bool) B leq z2` ASSUME_TAC THENL
     [MATCH_MP_TAC(ISPECL
                   [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`onebee:A`;`nn:A`;
                    `om:A`;`sig:A`;`omch:A`;`z2:A`] ECHECK_IN_TOP) THEN
      ASM_REWRITE_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN `(E:A->A->bool) bb B` ASSUME_TAC THENL
     [FIRST_X_ASSUM(MATCH_MP_TAC o check
                    (fun th -> is_forall(concl th) &&
                     vfree_in `embf:A` (concl th) &&
                     vfree_in `B:A` (concl th))) THEN
      EXISTS_TAC `cvs:A` THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN `(E:A->A->bool) z2 B` ASSUME_TAC THENL
     [MATCH_MP_TAC(ISPECL
                   [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`sig:A`;`omch:A`;
                    `z2:A`] EBV_IN_IN_B) THEN
      ASM_REWRITE_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN `etop D (E:A->A->bool) B leq c` ASSUME_TAC THENL
     [MP_TAC(ISPECL
             [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`bb:A`;`z2:A`;`c:A`]
             EBIMP_TOP) THEN
      ASM_REWRITE_TAC[] THEN DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
      UNDISCH_TAC `etop D (E:A->A->bool) B leq z2` THEN REWRITE_TAC[etop] THEN
      STRIP_TAC THEN
      FIRST_X_ASSUM MATCH_MP_TAC THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    UNDISCH_TAC `etop D (E:A->A->bool) B leq c` THEN REWRITE_TAC[etop] THEN
    STRIP_TAC THEN
    FIRST_X_ASSUM MATCH_MP_TAC THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) z B` ASSUME_TAC THENL
  [ASM_MESON_TAC[ESUBVAL_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq z onebee` ASSUME_TAC THENL
   [UNDISCH_TAC `etop D (E:A->A->bool) B leq onebee` THEN
    REWRITE_TAC[etop] THEN STRIP_TAC THEN
    FIRST_X_ASSUM MATCH_MP_TAC THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(z:A) = onebee` SUBST_ALL_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`z:A`;`onebee:A`]
                 EPORDER_ANTISYM) THEN
    ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[ECBA_IMP_PORDER]; ALL_TAC] THEN
  ASM_REWRITE_TAC[]);;

(* ==== F7 (II.5 / F-build F1a) realname_set_form -- object form for "z
  IN rdot_alpha"
   = ?n. n IN om /\ z = <n^, b_{alpha,n}>.  Slot 1 = z (tested elt), 22 = om,
   10 = ON, 11 = alpha, 12 = onetw,
   13 = embf (realname_form's params); slot 0 = n
   (bound).  Reuses realname_form (slot 0 = n, 1 = z).  First piece of the
   realfn graph form. *)

let realname_set_form = new_definition
  `realname_set_form = ?? 0 ((0 %% 22) && realname_form)`;;

let HOLDS_REALNAME_SET_FORM = prove
 (`!D (E:A->A->bool) v.
      model D E ZF_AX /\ valuation D v
      ==> (holds D E v realname_set_form <=>
           ?n sig b p15 cvs.
                n IN D /\ sig IN D /\ b IN D /\ p15 IN D /\ cvs IN D /\
                E n (v 22) /\ eopair D E sig b (v 1) /\
                echeck D E (v 10) n sig /\ eopair D E (v 11) n p15 /\
                eopair D E p15 (v 12) cvs /\ eapply D E (v 13) cvs b)`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `!x:num. (v:num->A) x IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[valuation]; ALL_TAC] THEN
  SUBGOAL_THEN
   `!a:A. a IN D ==>
      (holds D E ((0 |-> a) v) ((0 %% 22) && realname_form) <=>
       E a (v 22) /\
       (?sig b p15 cvs. sig IN D /\ b IN D /\ p15 IN D /\ cvs IN D /\
          eopair D E sig b (v 1) /\ echeck D E (v 10) a sig /\
          eopair D E (v 11) a p15 /\ eopair D E p15 (v 12) cvs /\
          eapply D E (v 13) cvs b))`
   (LABEL_TAC "body") THENL
   [X_GEN_TAC `a:A` THEN DISCH_TAC THEN
    SUBGOAL_THEN `valuation D ((0 |-> (a:A)) v)` ASSUME_TAC THENL
     [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    REWRITE_TAC[HOLDS_AND; HOLDS_MEM] THEN
    MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`(0 |-> (a:A)) v`]
           HOLDS_REALNAME_FORM) THEN
    ASM_REWRITE_TAC[] THEN DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER; ARITH_EQ]; ALL_TAC] THEN
  REWRITE_TAC[realname_set_form; HOLDS_EX] THEN EQ_TAC THENL
   [DISCH_THEN(X_CHOOSE_THEN `n:A` STRIP_ASSUME_TAC) THEN
    USE_THEN "body" (MP_TAC o SPEC `n:A`) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun eq -> MP_TAC(EQ_MP eq (ASSUME
      `holds D E ((0 |-> (n:A)) v) ((0 %% 22) && realname_form)`))) THEN
    STRIP_TAC THEN
    MAP_EVERY EXISTS_TAC [`n:A`;`sig:A`;`b:A`;`p15:A`;`cvs:A`] THEN
    ASM_REWRITE_TAC[];
    DISCH_THEN(X_CHOOSE_THEN `n:A` (X_CHOOSE_THEN `sig:A` (X_CHOOSE_THEN `b:A`
      (X_CHOOSE_THEN `p15:A` (X_CHOOSE_THEN `cvs:A` STRIP_ASSUME_TAC))))) THEN
    EXISTS_TAC `n:A` THEN CONJ_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    USE_THEN "body" (MP_TAC o SPEC `n:A`) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN ASM_REWRITE_TAC[] THEN
    MAP_EVERY EXISTS_TAC [`sig:A`;`b:A`;`p15:A`;`cvs:A`] THEN
    ASM_REWRITE_TAC[]]);;

(* ==== F7 (II.5 / F-build F1b) realname_graph_form -- object form for
   "w = <alpha, rdot_alpha>" (alpha = slot 11, w = slot 31,
   rdot_alpha = Y bound
   slot 30, membership via realname_set_form).  REPLACEMENT relation for realfn
   (x=11, y=31, a=iibase).  Monolithic (hand-nested THENL from the validated
   stepper f7_graphform_step.ml). *)

let realname_graph_form = new_definition
  `realname_graph_form =
     ?? 30 (opair_form 11 30 31 && (!! 1 ((1 %% 30) <-> realname_set_form)))`;;

let HOLDS_REALNAME_GRAPH_FORM = prove
 (`!D (E:A->A->bool) v.
      model D E ZF_AX /\ valuation D v
      ==> (holds D E v realname_graph_form <=>
           ?Y. Y IN D /\ eopair D E (v 11) Y (v 31) /\
               (!z. z IN D ==>
                    (E z Y <=>
                     ?n sig b p15 cvs. n IN D /\ sig IN D /\
                       b IN D /\ p15 IN D /\
                        cvs IN D /\ E n (v 22) /\ eopair D E sig b z /\
                        echeck D E (v 10) n sig /\ eopair D E (v 11) n p15 /\
                        eopair D E p15 (v 12) cvs /\
                          eapply D E (v 13) cvs b)))`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `!x:num. (v:num->A) x IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[valuation]; ALL_TAC] THEN
  SUBGOAL_THEN
   `!Y:A. Y IN D ==>
      (holds D E ((30 |-> Y) v)
       (opair_form 11 30 31 && (!! 1 ((1 %% 30) <-> realname_set_form))) <=>
       eopair D E (v 11) Y (v 31) /\
       (!z. z IN D ==>
            (E z Y <=>
             ?n sig b p15 cvs. n IN D /\ sig IN D /\ b IN D /\ p15 IN D /\
                cvs IN D /\ E n (v 22) /\ eopair D E sig b z /\
                echeck D E (v 10) n sig /\ eopair D E (v 11) n p15 /\
                eopair D E p15 (v 12) cvs /\ eapply D E (v 13) cvs b)))`
   (LABEL_TAC "body") THENL
   [X_GEN_TAC `Y:A` THEN DISCH_TAC THEN
    SUBGOAL_THEN `valuation D ((30 |-> (Y:A)) v)` ASSUME_TAC THENL
     [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN
      `holds D E ((30 |-> (Y:A)) v) (opair_form 11 30 31) <=>
       eopair D E (v 11) Y (v 31)` (LABEL_TAC "opaireq") THENL
     [MP_TAC(ISPECL
             [`D:A->bool`;`E:A->A->bool`;`(30 |-> (Y:A)) v`;`11`;`30`;`31`]
             HOLDS_OPAIR_FORM) THEN
      ASM_REWRITE_TAC[] THEN DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
      ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER; ARITH_EQ]; ALL_TAC] THEN
    SUBGOAL_THEN
     `!z:A. z IN D ==>
        (holds D E ((1 |-> z) ((30 |-> (Y:A)) v))
         ((1 %% 30) <-> realname_set_form) <=>
         (E z Y <=>
          ?n sig b p15 cvs. n IN D /\ sig IN D /\ b IN D /\
            p15 IN D /\ cvs IN D /\
             E n (v 22) /\ eopair D E sig b z /\ echeck D E (v 10) n sig /\
             eopair D E (v 11) n p15 /\ eopair D E p15 (v 12) cvs /\
               eapply D E (v 13) cvs b))`
     (LABEL_TAC "pz") THENL
     [X_GEN_TAC `z:A` THEN DISCH_TAC THEN
      SUBGOAL_THEN `valuation D ((1 |-> (z:A)) ((30 |-> (Y:A)) v))`
        ASSUME_TAC THENL
        [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
      REWRITE_TAC[HOLDS_IFF] THEN
      SUBGOAL_THEN
        `holds D E ((1 |-> (z:A)) ((30 |-> (Y:A)) v)) (1 %% 30) <=> E z Y`
        (LABEL_TAC "pzmem") THENL
        [REWRITE_TAC[HOLDS_MEM] THEN
         ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER; ARITH_EQ]; ALL_TAC] THEN
      SUBGOAL_THEN
       `holds D E ((1 |-> (z:A)) ((30 |-> (Y:A)) v)) realname_set_form <=>
        ?n sig b p15 cvs. n IN D /\ sig IN D /\ b IN D /\
          p15 IN D /\ cvs IN D /\
           E n (v 22) /\ eopair D E sig b z /\ echeck D E (v 10) n sig /\
           eopair D E (v 11) n p15 /\ eopair D E p15 (v 12) cvs /\
             eapply D E (v 13) cvs b`
       (LABEL_TAC "pzset") THENL
       [MP_TAC(ISPECL
               [`D:A->bool`;`E:A->A->bool`;`(1 |-> (z:A)) ((30 |-> (Y:A)) v)`]
               HOLDS_REALNAME_SET_FORM) THEN
        ASM_REWRITE_TAC[] THEN DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
        ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER; ARITH_EQ]; ALL_TAC] THEN
      ASM_REWRITE_TAC[];
      SUBGOAL_THEN
       `holds D E ((30 |-> (Y:A)) v)
        (!! 1 ((1 %% 30) <-> realname_set_form)) <=>
        (!z. z IN D ==>
             (E z Y <=>
              ?n sig b p15 cvs. n IN D /\ sig IN D /\ b IN D /\
                p15 IN D /\ cvs IN D /\
                 E n (v 22) /\ eopair D E sig b z /\ echeck D E (v 10) n sig /\
                 eopair D E (v 11) n p15 /\ eopair D E p15 (v 12) cvs /\
                   eapply D E (v 13) cvs b))`
       (LABEL_TAC "forall") THENL
       [REWRITE_TAC[HOLDS_ALL] THEN USE_THEN "pz" (fun p -> SIMP_TAC[p]);
        ALL_TAC] THEN
      USE_THEN "opaireq" (fun oe -> USE_THEN "forall" (fun fe ->
        REWRITE_TAC[HOLDS_AND; oe; fe]))];
    REWRITE_TAC[realname_graph_form; HOLDS_EX] THEN EQ_TAC THENL
     [DISCH_THEN(X_CHOOSE_THEN `Y:A` STRIP_ASSUME_TAC) THEN
      USE_THEN "body" (MP_TAC o SPEC `Y:A`) THEN ANTS_TAC THENL
      [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun eq -> MP_TAC(EQ_MP eq (ASSUME
        `holds D E ((30 |-> (Y:A)) v)
         (opair_form 11 30 31 &&
          (!! 1 ((1 %% 30) <-> realname_set_form)))`))) THEN
      STRIP_TAC THEN EXISTS_TAC `Y:A` THEN ASM_REWRITE_TAC[];
      DISCH_THEN(X_CHOOSE_THEN `Y:A` STRIP_ASSUME_TAC) THEN
      EXISTS_TAC `Y:A` THEN
      ASM_REWRITE_TAC[] THEN
      USE_THEN "body" (MP_TAC o SPEC `Y:A`) THEN ANTS_TAC THENL
      [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun eq -> REWRITE_TAC[eq]) THEN ASM_REWRITE_TAC[]]]);;
(* ==== F7 (II.5 / F-build F2) REALFN_EXISTS -- internal function
   realfn = {<alpha, rdot_alpha> : alpha < iibase} IN D, via ZF_REPLACEMENT
   over iibase with realname_graph_form (x=11,y=31).  Existence per alpha =
   COHEN_REALNAME_EXISTS, uniqueness = EMEM_CHAR_UNIQUE.  Monolithic. *)

let REALFN_EXISTS = prove
 (`!D (E:A->A->bool) P leqp ci om ON embf iibase ii tw onetw.
     model D E ZF_AX /\ (!u:A. u IN D ==> elmem D E u) /\
     eomega D E om /\ ON IN D /\ om IN D /\ iibase IN D /\ embf IN D /\
     (!z. z IN D
          ==> (E z embf <=>
               ?cv b. cv IN D /\ b IN D /\ (E:A->A->bool) cv (ci:A) /\
                      eopair D E cv b z /\
                      (!q. q IN D
                           ==> (E q b <=>
                                (E:A->A->bool) q (P:A) /\
                                (!r. r IN D /\ erel D E leqp r q
                                     ==> ?s. s IN D /\ erel D E leqp s r /\
                                       E cv s))))) /\
     (!cvs. cvs IN D /\ (E:A->A->bool) cvs (ci:A) ==> ?b. b IN D /\
      eapply D E embf cvs b) /\
     ecross D E iibase om ii /\ ecross D E ii tw ci /\
     onetw IN D /\ (E:A->A->bool) onetw tw
     ==> ?realfn. realfn IN D /\
                (!w. w IN D ==>
                     (E w realfn <=>
                      ?a Y. a IN D /\ Y IN D /\ (E:A->A->bool) a iibase /\
                            eopair D E a Y w /\
                            (!z. z IN D ==>
                                 (E z Y <=>
                                  ?n sig b p15 cvs. n IN D /\
                                    sig IN D /\ b IN D /\
                                     p15 IN D /\ cvs IN D /\
                                       (E:A->A->bool) n om /\
                                     eopair D E sig b z /\
                                       echeck D E ON n sig /\
                                     eopair D E a n p15 /\
                                       eopair D E p15 onetw cvs /\
                                     eapply D E embf cvs b))))`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  ABBREV_TAC
    `vv = (22 |-> (om:A))
     ((13 |-> (embf:A))
      ((12 |-> (onetw:A)) ((10 |-> (ON:A)) (\k:num. ON:A))))` THEN
  SUBGOAL_THEN `valuation D (vv:num->A)` ASSUME_TAC THENL
   [EXPAND_TAC "vv" THEN
    REPEAT(MATCH_MP_TAC VALUATION_VALMOD THEN CONJ_TAC THENL
           [ALL_TAC; FIRST_ASSUM ACCEPT_TAC]) THEN
    REWRITE_TAC[valuation] THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN
    `(vv:num->A) 10 = ON /\ (vv:num->A) 12 = onetw /\ (vv:num->A) 13 = embf /\
     (vv:num->A) 22 = om` STRIP_ASSUME_TAC THENL
   [EXPAND_TAC "vv" THEN REPEAT CONJ_TAC THEN
    ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER; ARITH_EQ]; ALL_TAC] THEN
  SUBGOAL_THEN
   `!a w:A. a IN D /\ w IN D
      ==> (holds D E ((31 |-> w) ((11 |-> a) vv)) realname_graph_form <=>
           ?Y. Y IN D /\ eopair D E a Y w /\
               (!z. z IN D ==>
                    (E z Y <=>
                     ?n sig b p15 cvs. n IN D /\ sig IN D /\
                       b IN D /\ p15 IN D /\
                        cvs IN D /\ (E:A->A->bool) n om /\
                          eopair D E sig b z /\
                        echeck D E ON n sig /\ eopair D E a n p15 /\
                        eopair D E p15 onetw cvs /\ eapply D E embf cvs b)))`
   (LABEL_TAC "hc") THENL
   [MAP_EVERY X_GEN_TAC [`a:A`;`w:A`] THEN STRIP_TAC THEN
    SUBGOAL_THEN `valuation D ((31 |-> (w:A)) ((11 |-> (a:A)) vv))`
      ASSUME_TAC THENL
      [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
    MP_TAC(ISPECL
           [`D:A->bool`;`E:A->A->bool`;`(31 |-> (w:A)) ((11 |-> (a:A)) vv)`]
           HOLDS_REALNAME_GRAPH_FORM) THEN
    ASM_REWRITE_TAC[] THEN DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER; ARITH_EQ]; ALL_TAC] THEN
  SUBGOAL_THEN
   `!a:A. a IN D /\ (E:A->A->bool) a iibase
      ==> ?w. w IN D /\
              ?Y. Y IN D /\ eopair D E a Y w /\
                  (!z. z IN D ==>
                       (E z Y <=>
                        ?n sig b p15 cvs. n IN D /\ sig IN D /\
                          b IN D /\ p15 IN D /\
                           cvs IN D /\ (E:A->A->bool) n om /\
                             eopair D E sig b z /\
                           echeck D E ON n sig /\ eopair D E a n p15 /\
                           eopair D E p15 onetw cvs /\ eapply D E embf cvs b))`
   (LABEL_TAC "val") THENL
   [X_GEN_TAC `a:A` THEN STRIP_TAC THEN
    MP_TAC(ISPECL
           [`D:A->bool`;`E:A->A->bool`;`P:A`;`leqp:A`;`ci:A`;`om:A`;`ON:A`;
            `embf:A`;`iibase:A`;`ii:A`;`tw:A`;`a:A`;`onetw:A`]
           COHEN_REALNAME_EXISTS) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(X_CHOOSE_THEN `Y:A`
               (CONJUNCTS_THEN2 (LABEL_TAC "YD") (LABEL_TAC "Ych"))) THEN
    MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`a:A`;`Y:A`] EOPAIR_EXISTS) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(X_CHOOSE_THEN `w:A` (LABEL_TAC "wop")) THEN
    SUBGOAL_THEN `(w:A) IN D` ASSUME_TAC THENL
    [ASM_MESON_TAC[EOPAIR_IN]; ALL_TAC] THEN
    EXISTS_TAC `w:A` THEN CONJ_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    EXISTS_TAC `Y:A` THEN REPEAT CONJ_TAC THENL
     [FIRST_ASSUM ACCEPT_TAC;
      FIRST_ASSUM ACCEPT_TAC;
      X_GEN_TAC `z:A` THEN DISCH_TAC THEN
      USE_THEN "Ych" (MP_TAC o SPEC `z:A`) THEN ANTS_TAC THENL
      [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun ch -> REWRITE_TAC[ch]) THEN
      EQ_TAC THEN
      DISCH_THEN(X_CHOOSE_THEN `n:A`
                 (X_CHOOSE_THEN `sig:A` (X_CHOOSE_THEN `b:A`
                                         (X_CHOOSE_THEN `p15:A`
                                          (X_CHOOSE_THEN `cvs:A`
                                           STRIP_ASSUME_TAC))))) THEN
      MAP_EVERY EXISTS_TAC [`n:A`;`sig:A`;`b:A`;`p15:A`;`cvs:A`] THEN
      ASM_REWRITE_TAC[]]; ALL_TAC] THEN
  FIRST_ASSUM(MP_TAC o SPECL
   [`realname_graph_form`; `11`; `31`; `vv:num->A`; `iibase:A`] o MATCH_MP
     ZF_REPLACEMENT) THEN
  ANTS_TAC THENL
   [REWRITE_TAC[ARITH_EQ] THEN ASM_REWRITE_TAC[] THEN
    X_GEN_TAC `a:A` THEN STRIP_TAC THEN
    USE_THEN "val" (MP_TAC o SPEC `a:A`) THEN ANTS_TAC THENL
    [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    INTRO_TAC "@w0. w0D @Y0. Y0D op0 mem0" THEN
    EXISTS_TAC `w0:A` THEN ASM_REWRITE_TAC[] THEN
    X_GEN_TAC `w':A` THEN STRIP_TAC THEN
    USE_THEN "hc" (MP_TAC o SPECL [`a:A`; `w':A`]) THEN ANTS_TAC THENL
    [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(MP_TAC o C EQ_MP
               (ASSUME `holds D E ((31 |-> (w':A)) ((11 |-> (a:A)) vv))
                        realname_graph_form`)) THEN
    DISCH_THEN(X_CHOOSE_THEN `Y':A` (CONJUNCTS_THEN2 (LABEL_TAC "Y'D")
      (CONJUNCTS_THEN2 (LABEL_TAC "op'") (LABEL_TAC "mem'")))) THEN
    SUBGOAL_THEN `(Y':A) = Y0` SUBST_ALL_TAC THENL
     [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`Y':A`;`Y0:A`;
        `\z:A. ?n sig b p15 cvs. n IN D /\ sig IN D /\ b IN D /\
         p15 IN D /\ cvs IN D /\
           (E:A->A->bool) n om /\ eopair D E sig b z /\ echeck D E ON n sig /\
           eopair D E a n p15 /\ eopair D E p15 onetw cvs /\
             eapply D E embf cvs b`]
        EMEM_CHAR_UNIQUE) THEN
      BETA_TAC THEN REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`a:A`;`Y0:A`;`w':A`;`w0:A`]
           EOPAIR_UNIQUE) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `realfn:A`
             (CONJUNCTS_THEN2 ASSUME_TAC (LABEL_TAC "out"))) THEN
  EXISTS_TAC `realfn:A` THEN CONJ_TAC THENL
  [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
   X_GEN_TAC `w:A` THEN DISCH_TAC THEN
   USE_THEN "out" (MP_TAC o SPEC `w:A`) THEN ANTS_TAC THENL
   [ASM_REWRITE_TAC[]; ALL_TAC] THEN
   DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  EQ_TAC THENL
   [DISCH_THEN(X_CHOOSE_THEN `a:A` STRIP_ASSUME_TAC) THEN
    USE_THEN "hc" (MP_TAC o SPECL [`a:A`; `w:A`]) THEN ANTS_TAC THENL
    [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun eq -> MP_TAC(EQ_MP eq (ASSUME
      `holds D E ((31 |-> (w:A)) ((11 |-> (a:A)) vv))
       realname_graph_form`))) THEN
    DISCH_THEN(X_CHOOSE_THEN `Y:A` STRIP_ASSUME_TAC) THEN
    MAP_EVERY EXISTS_TAC [`a:A`;`Y:A`] THEN ASM_REWRITE_TAC[];
    DISCH_THEN(X_CHOOSE_THEN `a:A` (X_CHOOSE_THEN `Y:A` STRIP_ASSUME_TAC)) THEN
    EXISTS_TAC `a:A` THEN ASM_REWRITE_TAC[] THEN
    USE_THEN "hc" (MP_TAC o SPECL [`a:A`; `w:A`]) THEN ANTS_TAC THENL
    [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun eq -> REWRITE_TAC[eq]) THEN EXISTS_TAC `Y:A` THEN
    ASM_REWRITE_TAC[]]);;

(* ==== F7 (II.5 / F-build F3b) REALFN_APPLY -- realfn applied to a IN
  iibase yields
   the real name Y (the one with membership-char R a).  <a,Y> IN realfn
     via the char
   backward.  Abstract over R; III supplies Y via COHEN_REALNAME_EXISTS. *)

let REALFN_APPLY = prove
 (`!D (E:A->A->bool) realfn iibase R a Y.
     model D E ZF_AX /\ realfn IN D /\
     (!w. w IN D ==>
          (E w realfn <=>
           ?a' Y'. a' IN D /\ Y' IN D /\ (E:A->A->bool) a' iibase /\
             eopair D E a' Y' w /\
                   (!z. z IN D ==> (E z Y' <=> R a' z)))) /\
     a IN D /\ (E:A->A->bool) a iibase /\ Y IN D /\
     (!z. z IN D ==> (E z Y <=> R a z))
     ==> eapply D E realfn a Y`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  FIRST_X_ASSUM(LABEL_TAC "ch" o check (fun th ->
    is_forall(concl th) && vfree_in `realfn:A` (concl th) &&
      vfree_in `iibase:A` (concl th))) THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`a:A`;`Y:A`] EOPAIR_EXISTS) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `w:A` (LABEL_TAC "wop")) THEN
  SUBGOAL_THEN `(w:A) IN D` ASSUME_TAC THENL
  [ASM_MESON_TAC[EOPAIR_IN]; ALL_TAC] THEN
  REWRITE_TAC[eapply] THEN EXISTS_TAC `w:A` THEN ASM_REWRITE_TAC[] THEN
  USE_THEN "ch" (MP_TAC o SPEC `w:A`) THEN ANTS_TAC THENL
  [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(fun eq -> REWRITE_TAC[eq]) THEN
  MAP_EVERY EXISTS_TAC [`a:A`;`Y:A`] THEN ASM_REWRITE_TAC[]);;

(* ==== F7 (III) lemma: EUPAIRNAME_CANON -- EUPAIRNAME_EXISTS replayed with the
   CANONICAL structure exported: up = {pa,pb}, pa=<a,top>,
   pb=<b,top>, including
   the pairing MEMBERSHIP CHAR (!z. z IN D ==> (E z up <=> z=pa \/ z=pb)).  The
   h-construction's REPLACEMENT needs the char to pin the opn cells. *)

let EUPAIRNAME_CANON = prove
 (`!D (E:A->A->bool) B leq a b.
      model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ a IN D /\ b IN D /\
      bname D E B a /\ bname D E B b
      ==> ?up top pa pb.
                   up IN D /\ bname D E B up /\
                   top IN D /\ etop D E B leq top /\
                   pa IN D /\ pb IN D /\
                   eopair D E a top pa /\ eopair D E b top pb /\
                   (!z. z IN D ==> (E z up <=> z = pa \/ z = pb)) /\
                   eapply D E up a top /\ eapply D E up b top /\
                   (!t q. t IN D /\ q IN D /\ eapply D E up t q ==>
                    t = a \/ t = b)`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `ebalg D (E:A->A->bool) B leq` ASSUME_TAC THENL
   [ASM_MESON_TAC[ECBA_IMP_BALG]; ALL_TAC] THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`] EBALG_TOP) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `top:A`) THEN
  SUBGOAL_THEN `(top:A) IN D /\ (E:A->A->bool) top B` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[ETOP_IN]; ALL_TAC] THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`a:A`;`top:A`] EOPAIR_EXISTS) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `pa:A`) THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`b:A`;`top:A`] EOPAIR_EXISTS) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `pb:A`) THEN
  SUBGOAL_THEN `(pa:A) IN D /\ (pb:A) IN D` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[EOPAIR_IN]; ALL_TAC] THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`] ZF_PAIRING) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(MP_TAC o SPECL [`pa:A`;`pb:A`]) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `up:A`
             (CONJUNCTS_THEN2 ASSUME_TAC (LABEL_TAC "upmem"))) THEN
  (* common stage for a,b, then its successor stage *)
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`a:A`;`b:A`]
         BNAME_DIRECTED) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `ao:A` (X_CHOOSE_THEN `y0:A` STRIP_ASSUME_TAC)) THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`ao:A`] ESUC_EXISTS) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `sao:A`) THEN
  SUBGOAL_THEN
    `(sao:A) IN D /\ eordinal D (E:A->A->bool) sao /\ (E:A->A->bool) ao sao`
  STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[ESUC_IN; EORDINAL_ESUC; ESUC_MEMBER]; ALL_TAC] THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`sao:A`]
         EBNSTAGE_EXISTS) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `ysao:A` STRIP_ASSUME_TAC) THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`sao:A`;`ysao:A`]
         EBNSTAGE_CHAR) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `w:A` (CONJUNCTS_THEN2 ASSUME_TAC
    (CONJUNCTS_THEN2 (LABEL_TAC "wch") ASSUME_TAC))) THEN
  SUBGOAL_THEN `(E:A->A->bool) a w` ASSUME_TAC THENL
   [USE_THEN "wch" (MP_TAC o SPEC `a:A`) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    MAP_EVERY EXISTS_TAC [`ao:A`;`y0:A`] THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) b w` ASSUME_TAC THENL
   [USE_THEN "wch" (MP_TAC o SPEC `b:A`) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    MAP_EVERY EXISTS_TAC [`ao:A`;`y0:A`] THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* cross w B *)
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`w:A`;`B:A`] ECROSS_EXISTS) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `cr:A` (LABEL_TAC "cr")) THEN
  SUBGOAL_THEN `(cr:A) IN D` ASSUME_TAC THENL
   [USE_THEN "cr" (MP_TAC o REWRITE_RULE[ecross]) THEN SIMP_TAC[];
    ALL_TAC] THEN
  (* "all values are top" helper *)
  SUBGOAL_THEN
   `!uu ww zz. uu IN D /\ ww IN D /\ eopair D (E:A->A->bool) uu ww zz /\
    E zz up ==> ww = top`
  (LABEL_TAC "vtop") THENL
   [REPEAT STRIP_TAC THEN
    SUBGOAL_THEN `(zz:A) IN D` ASSUME_TAC THENL
    [ASM_MESON_TAC[EOPAIR_IN]; ALL_TAC] THEN
    SUBGOAL_THEN `(zz:A) = pa \/ zz = pb` MP_TAC THENL
     [USE_THEN "upmem" (MP_TAC o SPEC `zz:A`) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[GSYM th]) THEN ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    DISCH_THEN(DISJ_CASES_THEN SUBST_ALL_TAC) THENL
     [MP_TAC(ISPECL
             [`D:A->bool`;`E:A->A->bool`;`uu:A`;`ww:A`;`a:A`;`top:A`;`pa:A`]
             EOPAIR_INJ) THEN ASM_REWRITE_TAC[] THEN STRIP_TAC THEN
      ASM_REWRITE_TAC[];
      MP_TAC(ISPECL
             [`D:A->bool`;`E:A->A->bool`;`uu:A`;`ww:A`;`b:A`;`top:A`;`pb:A`]
             EOPAIR_INJ) THEN ASM_REWRITE_TAC[] THEN STRIP_TAC THEN
      ASM_REWRITE_TAC[]]; ALL_TAC] THEN
  (* eisfun up *)
  SUBGOAL_THEN `eisfun D (E:A->A->bool) up` ASSUME_TAC THENL
   [REWRITE_TAC[eisfun] THEN ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
     [X_GEN_TAC `z:A` THEN STRIP_TAC THEN
      SUBGOAL_THEN `(z:A) = pa \/ z = pb` MP_TAC THENL
       [USE_THEN "upmem" (MP_TAC o SPEC `z:A`) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
        DISCH_THEN(fun th -> REWRITE_TAC[GSYM th]) THEN ASM_REWRITE_TAC[];
        ALL_TAC] THEN
      DISCH_THEN(DISJ_CASES_THEN SUBST_ALL_TAC) THENL
       [MAP_EVERY EXISTS_TAC [`a:A`;`top:A`] THEN ASM_REWRITE_TAC[];
        MAP_EVERY EXISTS_TAC [`b:A`;`top:A`] THEN ASM_REWRITE_TAC[]];
      MAP_EVERY X_GEN_TAC [`uu:A`;`ww:A`;`ww':A`;`zz:A`;`zz':A`] THEN
      STRIP_TAC THEN
      SUBGOAL_THEN `ww:A = top /\ ww':A = top` (fun th -> MESON_TAC[th]) THEN
      CONJ_TAC THEN USE_THEN "vtop" MATCH_MP_TAC THENL
       [MAP_EVERY EXISTS_TAC [`uu:A`;`zz:A`];
        MAP_EVERY EXISTS_TAC [`uu:A`;`zz':A`]] THEN
      ASM_REWRITE_TAC[]]; ALL_TAC] THEN
  (* up SUBSET cross w B *)
  SUBGOAL_THEN `esubset D (E:A->A->bool) up cr` ASSUME_TAC THENL
   [REWRITE_TAC[esubset] THEN X_GEN_TAC `z:A` THEN STRIP_TAC THEN
    USE_THEN "cr" (MP_TAC o SPEC `z:A` o CONJUNCT2 o REWRITE_RULE[ecross]) THEN
    ASM_REWRITE_TAC[] THEN DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    SUBGOAL_THEN `(z:A) = pa \/ z = pb` MP_TAC THENL
     [USE_THEN "upmem" (MP_TAC o SPEC `z:A`) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[GSYM th]) THEN ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    DISCH_THEN(DISJ_CASES_THEN SUBST_ALL_TAC) THENL
     [MAP_EVERY EXISTS_TAC [`a:A`;`top:A`] THEN ASM_REWRITE_TAC[];
      MAP_EVERY EXISTS_TAC [`b:A`;`top:A`] THEN ASM_REWRITE_TAC[]];
     ALL_TAC] THEN
  (* ebnmem, then E up ysao, then bname up *)
  SUBGOAL_THEN `ebnmem D (E:A->A->bool) B w up` ASSUME_TAC THENL
   [REWRITE_TAC[ebnmem] THEN ASM_REWRITE_TAC[] THEN
    EXISTS_TAC `cr:A` THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) up ysao` ASSUME_TAC THENL
   [UNDISCH_TAC `ebnfuns D (E:A->A->bool) B w ysao` THEN
    REWRITE_TAC[ebnfuns] THEN
    DISCH_THEN(MP_TAC o SPEC `up:A` o CONJUNCT2) THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `bname D (E:A->A->bool) B up` ASSUME_TAC THENL
   [REWRITE_TAC[bname] THEN MAP_EVERY EXISTS_TAC [`sao:A`;`ysao:A`] THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* assemble *)
  MAP_EVERY EXISTS_TAC [`up:A`;`top:A`;`pa:A`;`pb:A`] THEN
  ASM_REWRITE_TAC[] THEN
  REPEAT CONJ_TAC THENL
   [REWRITE_TAC[eapply] THEN EXISTS_TAC `pa:A` THEN ASM_REWRITE_TAC[] THEN
    USE_THEN "upmem" (MP_TAC o SPEC `pa:A`) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]);
    REWRITE_TAC[eapply] THEN EXISTS_TAC `pb:A` THEN ASM_REWRITE_TAC[] THEN
    USE_THEN "upmem" (MP_TAC o SPEC `pb:A`) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]);
    MAP_EVERY X_GEN_TAC [`t:A`;`q:A`] THEN REWRITE_TAC[eapply] THEN
    DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC (CONJUNCTS_THEN2 ASSUME_TAC
      (X_CHOOSE_THEN `p:A` STRIP_ASSUME_TAC))) THEN
    SUBGOAL_THEN `(p:A) IN D` ASSUME_TAC THENL
    [ASM_MESON_TAC[EOPAIR_IN]; ALL_TAC] THEN
    SUBGOAL_THEN `(p:A) = pa \/ p = pb` MP_TAC THENL
     [USE_THEN "upmem" (MP_TAC o SPEC `p:A`) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[GSYM th]) THEN ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    DISCH_THEN(DISJ_CASES_THEN SUBST_ALL_TAC) THENL
     [DISJ1_TAC THEN
      MP_TAC(ISPECL
             [`D:A->bool`;`E:A->A->bool`;`t:A`;`q:A`;`a:A`;`top:A`;`pa:A`]
             EOPAIR_INJ) THEN ASM_REWRITE_TAC[] THEN STRIP_TAC THEN
      ASM_REWRITE_TAC[];
      DISJ2_TAC THEN
      MP_TAC(ISPECL
             [`D:A->bool`;`E:A->A->bool`;`t:A`;`q:A`;`b:A`;`top:A`;`pb:A`]
             EOPAIR_INJ) THEN ASM_REWRITE_TAC[] THEN STRIP_TAC THEN
      ASM_REWRITE_TAC[]]]);;

(* ==== F7 (III) lemma: EOPAIRNAME_CANON -- the CANONICAL ordered-pair-name
   op = {sa,sab}, sa = {<a,top>}, sab = {<a,top>,<b,top>}, with the MEMBERSHIP
   CHAR at every level (pins op structurally for the h-REPLACEMENT) plus all
   the eapply/every-elt clauses in BVALF_OPAIRFORM_TOP/LE shape.  Via
   EUPAIRNAME_CANON x3 + ETOP_UNIQUE + EOPAIR_UNIQUE merges. *)

let EOPAIRNAME_CANON = prove
 (`!D (E:A->A->bool) B leq a b.
     model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
     a IN D /\ b IN D /\ bname D E B a /\ bname D E B b
     ==> ?op sa sab top paa pab psa psab.
             op IN D /\ bname D E B op /\ sa IN D /\ bname D E B sa /\
             sab IN D /\ bname D E B sab /\ top IN D /\ etop D E B leq top /\
             paa IN D /\ pab IN D /\ psa IN D /\ psab IN D /\
             eopair D E a top paa /\ eopair D E b top pab /\
             eopair D E sa top psa /\ eopair D E sab top psab /\
             (!z. z IN D ==> (E z sa <=> z = paa)) /\
             (!z. z IN D ==> (E z sab <=> z = paa \/ z = pab)) /\
             (!z. z IN D ==> (E z op <=> z = psa \/ z = psab)) /\
             eapply D E sa a top /\
             (!t q. t IN D /\ q IN D /\ eapply D E sa t q ==>
              t = a \/ t = a) /\
             eapply D E sab a top /\ eapply D E sab b top /\
             (!t q. t IN D /\ q IN D /\ eapply D E sab t q ==>
              t = a \/ t = b) /\
             eapply D E op sa top /\ eapply D E op sab top /\
             (!t q. t IN D /\ q IN D /\ eapply D E op t q ==>
              t = sa \/ t = sab)`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `eporder D (E:A->A->bool) B leq` ASSUME_TAC THENL
   [ASM_MESON_TAC[ECBA_IMP_PORDER]; ALL_TAC] THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`a:A`;`a:A`]
         EUPAIRNAME_CANON) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `sa:A`
             (X_CHOOSE_THEN `topa:A` (X_CHOOSE_THEN `pa1:A`
                                      (X_CHOOSE_THEN `pb1:A`
                                       STRIP_ASSUME_TAC)))) THEN
  SUBGOAL_THEN `(pb1:A) = pa1` SUBST_ALL_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`a:A`;`topa:A`;`pb1:A`;`pa1:A`]
                 EOPAIR_UNIQUE) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`a:A`;`b:A`]
         EUPAIRNAME_CANON) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `sab:A`
             (X_CHOOSE_THEN `topb:A` (X_CHOOSE_THEN `pa2:A`
                                      (X_CHOOSE_THEN `pb2:A`
                                       STRIP_ASSUME_TAC)))) THEN
  SUBGOAL_THEN `(topb:A) = topa` SUBST_ALL_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`topb:A`;`topa:A`]
                 ETOP_UNIQUE) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(pa2:A) = pa1` SUBST_ALL_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`a:A`;`topa:A`;`pa2:A`;`pa1:A`]
                 EOPAIR_UNIQUE) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`sa:A`;`sab:A`]
         EUPAIRNAME_CANON) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `op:A`
             (X_CHOOSE_THEN `topo:A` (X_CHOOSE_THEN `pa3:A`
                                      (X_CHOOSE_THEN `pb3:A`
                                       STRIP_ASSUME_TAC)))) THEN
  SUBGOAL_THEN `(topo:A) = topa` SUBST_ALL_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`topo:A`;`topa:A`]
                 ETOP_UNIQUE) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MAP_EVERY EXISTS_TAC
   [`op:A`;`sa:A`;`sab:A`;`topa:A`;`pa1:A`;`pb2:A`;`pa3:A`;`pb3:A`] THEN
  ASM_REWRITE_TAC[] THEN
  X_GEN_TAC `z:A` THEN DISCH_TAC THEN
  FIRST_X_ASSUM(MP_TAC o SPEC `z:A` o
    check (fun th -> is_forall(concl th) && vfree_in `sa:A` (concl th) &&
                     not(vfree_in `a:A` (concl th)) &&
                       not(vfree_in `op:A` (concl th)))) THEN
  ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN CONV_TAC TAUT);;
