(* F7 (III) H2: the Cohen CH-refuting nice-name h over the index         *)
(* set cr = aleph1^ x aleph2^.  Object forms opncell_form (opn-NAME cell) *)
(* and hname_form (h-cell), their HOLDS characterizations, the functional *)
(* lemma OPNCELL_FUNCTIONAL, and HNAME_EXISTS (ZF_REPLACEMENT).           *)
(* ===================================================================== *)

(* ==== F7 (III / h-build H1a) opncell_form -- object form for "(v 38) is the
   canonical ordered-pair-NAME of (v 24),(v 26) with top (v 10)", in B-name
   normal form (matches EOPAIRNAME_CANON exactly):
     paa = <(v 24),(v 10)>,  pab = <(v 26),(v 10)>,
     sa  = {paa},            sab = {paa,pab},
     psa = <sa,(v 10)>,      psab= <sab,(v 10)>,
     op  = {psa,psab} = (v 38).
   The two extra <.,top> layers (psa,psab) make op a PROPER B-name whose
   elements are <child,bool> pairs -- so ebv_in op g computes the intended
   forcing value [[<a,b> IN g]], and BVALF_OPAIRFORM_TOP/LE apply.
   Fixed slots a=24, b=26, op=38, top=10; binders 60(paa),63(pab),66(sa),
   69(sab),72(psa),75(psab) (gapped so sub-form internal binders -- each
   > MAX of its args -- never capture a sibling's free slot). *)

let opncell_form = new_definition
  `opncell_form =
     ?? 60 (?? 63 (?? 66 (?? 69 (?? 72 (?? 75
        (opair_form 24 10 60 && opair_form 26 10 63 &&
         pair_form 60 60 66 && pair_form 60 63 69 &&
         opair_form 66 10 72 && opair_form 69 10 75 &&
         pair_form 72 75 38))))))`;;

let HOLDS_OPNCELL_FORM = prove
 (`!D (E:A->A->bool) v.
      model D E ZF_AX /\ valuation D v
      ==> (holds D E v opncell_form <=>
           ?paa pab sa sab psa psab.
                paa IN D /\ pab IN D /\ sa IN D /\ sab IN D /\
                psa IN D /\ psab IN D /\
                eopair D E (v 24) (v 10) paa /\ eopair D E (v 26) (v 10) pab /\
                epair D E paa paa sa /\ epair D E paa pab sab /\
                eopair D E sa (v 10) psa /\ eopair D E sab (v 10) psab /\
                epair D E psa psab (v 38))`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `!x:num. (v:num->A) x IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[valuation]; ALL_TAC] THEN
  SUBGOAL_THEN
   `!paa pab sa sab psa psab:A.
      paa IN D /\ pab IN D /\ sa IN D /\ sab IN D /\ psa IN D /\ psab IN D
      ==> (holds D E ((75 |-> (psab:A)) ((72 |-> (psa:A)) ((69 |-> (sab:A))
             ((66 |-> (sa:A)) ((63 |-> (pab:A)) ((60 |-> (paa:A)) v))))))
             (opair_form 24 10 60 && opair_form 26 10 63 &&
              pair_form 60 60 66 && pair_form 60 63 69 &&
              opair_form 66 10 72 && opair_form 69 10 75 &&
              pair_form 72 75 38) <=>
           eopair D E (v 24) (v 10) paa /\ eopair D E (v 26) (v 10) pab /\
           epair D E paa paa sa /\ epair D E paa pab sab /\
           eopair D E sa (v 10) psa /\ eopair D E sab (v 10) psab /\
           epair D E psa psab (v 38))`
   (LABEL_TAC "body") THENL
   [REPEAT GEN_TAC THEN STRIP_TAC THEN
    SUBGOAL_THEN
      `valuation D ((75 |-> (psab:A)) ((72 |-> (psa:A)) ((69 |-> (sab:A))
             ((66 |-> (sa:A)) ((63 |-> (pab:A)) ((60 |-> (paa:A)) v))))))`
        ASSUME_TAC THENL
        [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
    ASM_SIMP_TAC[HOLDS_AND; HOLDS_OPAIR_FORM; HOLDS_PAIR_FORM] THEN
    ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER; ARITH_EQ]; ALL_TAC] THEN
  REWRITE_TAC[opncell_form; HOLDS_EX] THEN EQ_TAC THENL
   [INTRO_TAC "@paa. paaD @pab. pabD @sa. saD @sab. sabD @psa. psaD \
               @psab. psabD +" THEN
    USE_THEN "body" (fun th -> MP_TAC(SPECL
      [`paa:A`;`pab:A`;`sa:A`;`sab:A`;`psa:A`;`psab:A`] th)) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN STRIP_TAC THEN
    MAP_EVERY EXISTS_TAC [`paa:A`;`pab:A`;`sa:A`;`sab:A`;`psa:A`;`psab:A`] THEN
    ASM_REWRITE_TAC[];
    DISCH_THEN(X_CHOOSE_THEN `paa:A` (X_CHOOSE_THEN `pab:A`
      (X_CHOOSE_THEN `sa:A` (X_CHOOSE_THEN `sab:A`
        (X_CHOOSE_THEN `psa:A`
         (X_CHOOSE_THEN `psab:A` STRIP_ASSUME_TAC)))))) THEN
    EXISTS_TAC `paa:A` THEN CONJ_TAC THENL
    [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    EXISTS_TAC `pab:A` THEN CONJ_TAC THENL
    [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    EXISTS_TAC `sa:A` THEN CONJ_TAC THENL
    [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    EXISTS_TAC `sab:A` THEN CONJ_TAC THENL
    [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    EXISTS_TAC `psa:A` THEN CONJ_TAC THENL
    [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    EXISTS_TAC `psab:A` THEN CONJ_TAC THENL
    [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    USE_THEN "body" (fun th -> MP_TAC(SPECL
      [`paa:A`;`pab:A`;`sa:A`;`sab:A`;`psa:A`;`psab:A`] th)) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN ASM_REWRITE_TAC[]]);;

(* ==== F7 (III / h-build H1b) hname_form -- the h-cell object
  form.  For ground
   pair cp = (v 0) = <xi,alpha> (xi in aleph1=(v 15), alpha in aleph2=(v 16)),
   z = (v 1) is the h-cell <cp^, w> where w = [[ opn(xi^,
   realfn(alpha)) IN g ]]:
     xi^ = check (ON=(v 10)) of xi;  rdot = (v 13)=realfn applied at alpha;
     op = canonical opn-NAME (opncell_form, slots a=24,b=26,op=38,top=10) =
          {<{<xic,top>},top>,<{<xic,top>,<rdot,top>},top>};
     w = ebv_in (v 2)=B (v 5)=leq op (v 14)=g;  cpc = check of cp;
     z = <cpc,w>.
   Binders 18,19,24,26,38,52,58 (gapped: opair 18 19 0 -> 20,21; apply 13 19 26
   -> 27,28; ebv_in 52 38 14 5 -> 53..57; opair 58 52 1 -> 59,60; echeck args
   avoid {2,3,4,49,50,51}). *)

let hname_form = new_definition
  `hname_form =
     ?? 18 (?? 19 (?? 24 (?? 26 (?? 38 (?? 52 (?? 58
        (opair_form 18 19 0 && (18 %% 15) && (19 %% 16) &&
         echeck_form 10 18 24 && apply_form 13 19 26 &&
         opncell_form && ebv_in_form 52 38 14 5 &&
         echeck_form 10 0 58 && opair_form 58 52 1)))))))`;;

let HOLDS_HNAME_FORM = prove
 (`!D (E:A->A->bool) v.
      model D E ZF_AX /\ valuation D v
      ==> (holds D E v hname_form <=>
           ?xi alpha xic rdot op w cpc.
                xi IN D /\ alpha IN D /\ xic IN D /\ rdot IN D /\
                op IN D /\ w IN D /\ cpc IN D /\
                eopair D E xi alpha (v 0) /\ E xi (v 15) /\ E alpha (v 16) /\
                echeck D E (v 10) xi xic /\ eapply D E (v 13) alpha rdot /\
                (?paa pab sa sab psa psab.
                     paa IN D /\ pab IN D /\ sa IN D /\ sab IN D /\
                     psa IN D /\ psab IN D /\
                     eopair D E xic (v 10) paa /\ eopair D E rdot (v 10) pab /\
                     epair D E paa paa sa /\ epair D E paa pab sab /\
                     eopair D E sa (v 10) psa /\ eopair D E sab (v 10) psab /\
                     epair D E psa psab op) /\
                ebv_in D E (v 2) (v 5) op (v 14) w /\
                echeck D E (v 10) (v 0) cpc /\ eopair D E cpc w (v 1))`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `!x:num. (v:num->A) x IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[valuation]; ALL_TAC] THEN
  SUBGOAL_THEN
   `!xi alpha xic rdot op w cpc:A.
      xi IN D /\ alpha IN D /\ xic IN D /\ rdot IN D /\ op IN D /\
        w IN D /\ cpc IN D
      ==> (holds D E
           ((58 |-> (cpc:A))
            ((52 |-> (w:A)) ((38 |-> (op:A)) ((26 |-> (rdot:A))
                                              ((24 |-> (xic:A))
                                                ((19 |-> (alpha:A))
                                                ((18 |-> (xi:A)) v)))))))
             (opair_form 18 19 0 && (18 %% 15) && (19 %% 16) &&
              echeck_form 10 18 24 && apply_form 13 19 26 &&
              opncell_form && ebv_in_form 52 38 14 5 &&
              echeck_form 10 0 58 && opair_form 58 52 1) <=>
           eopair D E xi alpha (v 0) /\ E xi (v 15) /\ E alpha (v 16) /\
           echeck D E (v 10) xi xic /\ eapply D E (v 13) alpha rdot /\
           (?paa pab sa sab psa psab.
                paa IN D /\ pab IN D /\ sa IN D /\ sab IN D /\
                psa IN D /\ psab IN D /\
                eopair D E xic (v 10) paa /\ eopair D E rdot (v 10) pab /\
                epair D E paa paa sa /\ epair D E paa pab sab /\
                eopair D E sa (v 10) psa /\ eopair D E sab (v 10) psab /\
                epair D E psa psab op) /\
           ebv_in D E (v 2) (v 5) op (v 14) w /\
           echeck D E (v 10) (v 0) cpc /\ eopair D E cpc w (v 1))`
   (LABEL_TAC "body") THENL
   [REPEAT GEN_TAC THEN STRIP_TAC THEN
    SUBGOAL_THEN
      `valuation D
       ((58 |-> (cpc:A)) ((52 |-> (w:A)) ((38 |-> (op:A)) ((26 |-> (rdot:A))
             ((24 |-> (xic:A)) ((19 |-> (alpha:A)) ((18 |-> (xi:A)) v)))))))`
        ASSUME_TAC THENL
        [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
    ASM_SIMP_TAC[HOLDS_AND; HOLDS_MEM; HOLDS_OPAIR_FORM; HOLDS_ECHECK_FORM;
                 HOLDS_APPLY_FORM; HOLDS_EBV_IN_FORM; HOLDS_OPNCELL_FORM;
                 ARITH_EQ] THEN
    ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER; ARITH_EQ]; ALL_TAC] THEN
  REWRITE_TAC[hname_form; HOLDS_EX] THEN EQ_TAC THENL
   [INTRO_TAC "@xi. xiD @alpha. alphaD @xic. xicD @rdot. rdotD @op. opD \
               @w. wD @cpc. cpcD +" THEN
    USE_THEN "body" (fun th -> MP_TAC(SPECL
      [`xi:A`;`alpha:A`;`xic:A`;`rdot:A`;`op:A`;`w:A`;`cpc:A`] th)) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN STRIP_TAC THEN
    MAP_EVERY EXISTS_TAC
      [`xi:A`;`alpha:A`;`xic:A`;`rdot:A`;`op:A`;`w:A`;`cpc:A`] THEN
      ASM_REWRITE_TAC[] THEN
    MAP_EVERY EXISTS_TAC [`paa:A`;`pab:A`;`sa:A`;`sab:A`;`psa:A`;`psab:A`] THEN
    ASM_REWRITE_TAC[];
    DISCH_THEN(X_CHOOSE_THEN `xi:A` (X_CHOOSE_THEN `alpha:A`
      (X_CHOOSE_THEN `xic:A` (X_CHOOSE_THEN `rdot:A`
        (X_CHOOSE_THEN `op:A` (X_CHOOSE_THEN `w:A`
          (X_CHOOSE_THEN `cpc:A` STRIP_ASSUME_TAC))))))) THEN
    EXISTS_TAC `xi:A` THEN CONJ_TAC THENL
    [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    EXISTS_TAC `alpha:A` THEN CONJ_TAC THENL
    [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    EXISTS_TAC `xic:A` THEN CONJ_TAC THENL
    [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    EXISTS_TAC `rdot:A` THEN CONJ_TAC THENL
    [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    EXISTS_TAC `op:A` THEN CONJ_TAC THENL
    [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    EXISTS_TAC `w:A` THEN CONJ_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    EXISTS_TAC `cpc:A` THEN CONJ_TAC THENL
    [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    USE_THEN "body" (fun th -> MP_TAC(SPECL
      [`xi:A`;`alpha:A`;`xic:A`;`rdot:A`;`op:A`;`w:A`;`cpc:A`] th)) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN ASM_REWRITE_TAC[] THEN
    MAP_EVERY EXISTS_TAC [`paa:A`;`pab:A`;`sa:A`;`sab:A`;`psa:A`;`psab:A`] THEN
    ASM_REWRITE_TAC[]]);;

(* ==== F7 (III / h-build H2 helper) OPNCELL_FUNCTIONAL -- the
  canonical opn-name
   relation is functional: given a, b, top, the op built as
   {<{<a,top>},top>,<{<a,top>,<b,top>},top>} is unique.  Packages the 7-step
   EOPAIR_UNIQUE/EPAIR_UNIQUE chain so HNAME_EXISTS's REPLACEMENT uniqueness
   branch stays readable.  Clause order matches hname_form's opncell block. *)

let OPNCELL_FUNCTIONAL = prove
 (`!D (E:A->A->bool) a b top op op'.
     model D E ZF_AX /\
     (?paa pab sa sab psa psab.
          paa IN D /\ pab IN D /\ sa IN D /\ sab IN D /\ psa IN D /\
            psab IN D /\
          eopair D E a top paa /\ eopair D E b top pab /\
          epair D E paa paa sa /\ epair D E paa pab sab /\
          eopair D E sa top psa /\ eopair D E sab top psab /\
          epair D E psa psab op) /\
     (?paa pab sa sab psa psab.
          paa IN D /\ pab IN D /\ sa IN D /\ sab IN D /\ psa IN D /\
            psab IN D /\
          eopair D E a top paa /\ eopair D E b top pab /\
          epair D E paa paa sa /\ epair D E paa pab sab /\
          eopair D E sa top psa /\ eopair D E sab top psab /\
          epair D E psa psab op')
     ==> op = op'`,
  REPEAT GEN_TAC THEN
  DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC (CONJUNCTS_THEN2
    (X_CHOOSE_THEN `paa:A` (X_CHOOSE_THEN `pab:A` (X_CHOOSE_THEN `sa:A`
     (X_CHOOSE_THEN `sab:A` (X_CHOOSE_THEN `psa:A` (X_CHOOSE_THEN `psab:A`
       STRIP_ASSUME_TAC))))))
    (X_CHOOSE_THEN `paa':A` (X_CHOOSE_THEN `pab':A` (X_CHOOSE_THEN `sa':A`
     (X_CHOOSE_THEN `sab':A` (X_CHOOSE_THEN `psa':A` (X_CHOOSE_THEN `psab':A`
       STRIP_ASSUME_TAC)))))))) THEN
  SUBGOAL_THEN `paa':A = paa` SUBST_ALL_TAC THENL
   [MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`a:A`;`top:A`;`paa':A`;`paa:A`]
           EOPAIR_UNIQUE) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC]; ALL_TAC] THEN
  SUBGOAL_THEN `pab':A = pab` SUBST_ALL_TAC THENL
   [MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`b:A`;`top:A`;`pab':A`;`pab:A`]
           EOPAIR_UNIQUE) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC]; ALL_TAC] THEN
  SUBGOAL_THEN `sa':A = sa` SUBST_ALL_TAC THENL
   [MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`paa:A`;`paa:A`;`sa':A`;`sa:A`]
           EPAIR_UNIQUE) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC]; ALL_TAC] THEN
  SUBGOAL_THEN `sab':A = sab` SUBST_ALL_TAC THENL
   [MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`paa:A`;`pab:A`;`sab':A`;`sab:A`]
           EPAIR_UNIQUE) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC]; ALL_TAC] THEN
  SUBGOAL_THEN `psa':A = psa` SUBST_ALL_TAC THENL
   [MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`sa:A`;`top:A`;`psa':A`;`psa:A`]
           EOPAIR_UNIQUE) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC]; ALL_TAC] THEN
  SUBGOAL_THEN `psab':A = psab` SUBST_ALL_TAC THENL
   [MP_TAC(ISPECL
           [`D:A->bool`;`E:A->A->bool`;`sab:A`;`top:A`;`psab':A`;`psab:A`]
           EOPAIR_UNIQUE) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC]; ALL_TAC] THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`psa:A`;`psab:A`;`op:A`;`op':A`]
         EPAIR_UNIQUE) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC]);;

(* ==== F7 (III / H2) HNAME_EXISTS -- the h nice-name over cr =
  aleph1 x aleph2:
   h = { <cp^, [[ opn(xi^, realfn(alpha)) IN g ]]> : cp = <xi,alpha> IN cr },
   built by ZF_REPLACEMENT.  Cell existence from "val";
   replacement functionality
   from the uniqueness chain EOPAIR_INJ / ECHECK_SV / EAPPLY_UNIQUE /
   OPNCELL_FUNCTIONAL / EBV_IN_UNIQUE / EOPAIR_UNIQUE.  Mirrors
   COHEN_REALNAME_EXISTS structurally. *)

let HNAME_EXISTS = prove
 (`!D (E:A->A->bool) B leq onebee realfn g a1 a2 cr.
     model D E ZF_AX /\ (!u:A. u IN D ==> elmem D E u) /\
     ecba D E B leq /\ B IN D /\ leq IN D /\
     onebee IN D /\ E onebee B /\ etop D E B leq onebee /\
     realfn IN D /\ eisfun D E realfn /\
     (!a. a IN D /\ (E:A->A->bool) a a2
          ==> ?rd. rd IN D /\ eapply D E realfn a rd /\ bname D E B rd) /\
     g IN D /\ bname D E B g /\
     a1 IN D /\ a2 IN D /\ cr IN D /\ ecross D E a1 a2 cr
     ==> ?h. h IN D /\
             (!zz. zz IN D ==>
                  (E zz h <=>
                   ?cp xi alpha xic rdot op w cpc.
                        cp IN D /\ xi IN D /\ alpha IN D /\ xic IN D /\
                        rdot IN D /\ op IN D /\ w IN D /\ cpc IN D /\
                        (E:A->A->bool) cp cr /\
                        eopair D E xi alpha cp /\ E xi a1 /\ E alpha a2 /\
                        echeck D E onebee xi xic /\
                          eapply D E realfn alpha rdot /\
                        (?paa pab sa sab psa psab.
                             paa IN D /\ pab IN D /\ sa IN D /\ sab IN D /\
                             psa IN D /\ psab IN D /\
                             eopair D E xic onebee paa /\
                               eopair D E rdot onebee pab /\
                             epair D E paa paa sa /\ epair D E paa pab sab /\
                             eopair D E sa onebee psa /\
                               eopair D E sab onebee psab /\
                             epair D E psa psab op) /\
                        ebv_in D E B leq op g w /\
                        echeck D E onebee cp cpc /\ eopair D E cpc w zz))`,
  (* strip *)
  REPEAT GEN_TAC THEN STRIP_TAC THEN
   FIRST_X_ASSUM(LABEL_TAC "rtot" o check (fun th ->
     is_forall(concl th) && vfree_in `realfn:A` (concl th) &&
       vfree_in `a2:A` (concl th))) THEN
  (* vv *)
  ABBREV_TAC
    `vv = (16 |-> (a2:A))
     ((15 |-> (a1:A))
      ((14 |-> (g:A))
       ((13 |-> (realfn:A))
        ((10 |-> (onebee:A))
         ((5 |-> (leq:A)) ((2 |-> (B:A)) (\k:num. onebee:A)))))))` THEN
  (* vvval *)
  SUBGOAL_THEN `valuation D (vv:num->A)` ASSUME_TAC THENL
   [EXPAND_TAC "vv" THEN
    REPEAT(MATCH_MP_TAC VALUATION_VALMOD THEN CONJ_TAC THENL
      [ALL_TAC; FIRST_ASSUM ACCEPT_TAC]) THEN
    REWRITE_TAC[valuation] THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* vvslots *)
  SUBGOAL_THEN
   `(vv:num->A) 2 = B /\ (vv:num->A) 5 = leq /\ (vv:num->A) 10 = onebee /\
    (vv:num->A) 13 = realfn /\ (vv:num->A) 14 = g /\ (vv:num->A) 15 = a1 /\
    (vv:num->A) 16 = a2` STRIP_ASSUME_TAC THENL
   [EXPAND_TAC "vv" THEN REPEAT CONJ_TAC THEN
    ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER; ARITH_EQ]; ALL_TAC] THEN
  (* hc *)
  SUBGOAL_THEN
   `!cp z:A. cp IN D /\ z IN D
      ==> (holds D E ((1 |-> z) ((0 |-> cp) vv)) hname_form <=>
           ?xi alpha xic rdot op w cpc.
                xi IN D /\ alpha IN D /\ xic IN D /\ rdot IN D /\
                op IN D /\ w IN D /\ cpc IN D /\
                eopair D E xi alpha cp /\ (E:A->A->bool) xi a1 /\ E alpha a2 /\
                echeck D E onebee xi xic /\ eapply D E realfn alpha rdot /\
                (?paa pab sa sab psa psab.
                     paa IN D /\ pab IN D /\ sa IN D /\ sab IN D /\
                     psa IN D /\ psab IN D /\
                     eopair D E xic onebee paa /\ eopair D E rdot onebee pab /\
                     epair D E paa paa sa /\ epair D E paa pab sab /\
                     eopair D E sa onebee psa /\ eopair D E sab onebee psab /\
                     epair D E psa psab op) /\
                ebv_in D E B leq op g w /\
                echeck D E onebee cp cpc /\ eopair D E cpc w z)`
   (LABEL_TAC "hc") THENL
   [MAP_EVERY X_GEN_TAC [`cp:A`;`z:A`] THEN STRIP_TAC THEN
    SUBGOAL_THEN `valuation D ((1 |-> (z:A)) ((0 |-> (cp:A)) vv))`
      ASSUME_TAC THENL
      [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
    MP_TAC(ISPECL
           [`D:A->bool`;`E:A->A->bool`;`(1 |-> (z:A)) ((0 |-> (cp:A)) vv)`]
           HOLDS_HNAME_FORM) THEN
    ASM_REWRITE_TAC[] THEN DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER; ARITH_EQ]; ALL_TAC] THEN
  (* ep1 *)
  SUBGOAL_THEN
   `!paa sa:A. sa IN D /\ (!z. z IN D ==> ((E:A->A->bool) z sa <=> z = paa))
       ==> epair D E paa paa sa` (LABEL_TAC "ep1") THENL
   [REPEAT GEN_TAC THEN STRIP_TAC THEN REWRITE_TAC[epair] THEN
    ASM_REWRITE_TAC[] THEN X_GEN_TAC `u:A` THEN DISCH_TAC THEN
    FIRST_X_ASSUM(MP_TAC o SPEC `u:A` o check
                  (fun th -> is_forall(concl th))) THEN
    ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN CONV_TAC TAUT; ALL_TAC] THEN
  (* ep2 *)
  SUBGOAL_THEN
   `!paa pab sab:A. sab IN D /\
    (!z. z IN D ==> ((E:A->A->bool) z sab <=> z = paa \/ z = pab))
       ==> epair D E paa pab sab` (LABEL_TAC "ep2") THENL
   [REPEAT GEN_TAC THEN STRIP_TAC THEN REWRITE_TAC[epair] THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* val *)
  SUBGOAL_THEN
   `!cp:A. cp IN D /\ (E:A->A->bool) cp cr
      ==> ?z. z IN D /\
              ?xi alpha xic rdot op w cpc.
                xi IN D /\ alpha IN D /\ xic IN D /\ rdot IN D /\
                op IN D /\ w IN D /\ cpc IN D /\
                eopair D E xi alpha cp /\ (E:A->A->bool) xi a1 /\ E alpha a2 /\
                echeck D E onebee xi xic /\ eapply D E realfn alpha rdot /\
                (?paa pab sa sab psa psab.
                     paa IN D /\ pab IN D /\ sa IN D /\ sab IN D /\
                     psa IN D /\ psab IN D /\
                     eopair D E xic onebee paa /\ eopair D E rdot onebee pab /\
                     epair D E paa paa sa /\ epair D E paa pab sab /\
                     eopair D E sa onebee psa /\ eopair D E sab onebee psab /\
                     epair D E psa psab op) /\
                ebv_in D E B leq op g w /\
                echeck D E onebee cp cpc /\ eopair D E cpc w z`
   (LABEL_TAC "val") THENL
   [X_GEN_TAC `cp:A` THEN STRIP_TAC THEN
    MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`a1:A`;`a2:A`;`cr:A`;`cp:A`]
           ECROSS_MEMBER) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> MP_TAC(EQ_MP th (ASSUME `(E:A->A->bool) cp cr`))) THEN
    DISCH_THEN(X_CHOOSE_THEN `xi:A`
               (X_CHOOSE_THEN `alpha:A` STRIP_ASSUME_TAC)) THEN
    MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`onebee:A`;`xi:A`]
           ECHECK_EXHAUSTION) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(X_CHOOSE_THEN `xic:A` (LABEL_TAC "xick")) THEN
    SUBGOAL_THEN `(xic:A) IN D` ASSUME_TAC THENL
    [ASM_MESON_TAC[ECHECK_IMP]; ALL_TAC] THEN
    SUBGOAL_THEN `bname D (E:A->A->bool) B xic` ASSUME_TAC THENL
     [MATCH_MP_TAC(ISPECL
                   [`D:A->bool`;`E:A->A->bool`;`onebee:A`;`B:A`;`xi:A`;`xic:A`]
                   ECHECK_IS_BNAME) THEN
      ASM_REWRITE_TAC[]; ALL_TAC] THEN
    USE_THEN "rtot" (MP_TAC o SPEC `alpha:A`) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(X_CHOOSE_THEN `rdot:A` STRIP_ASSUME_TAC) THEN
    MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`xic:A`;`rdot:A`]
           EOPAIRNAME_CANON) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(X_CHOOSE_THEN `op:A`
               (X_CHOOSE_THEN `sa:A` (X_CHOOSE_THEN `sab:A`
                                      (X_CHOOSE_THEN `top':A`
                                       (X_CHOOSE_THEN `paa:A`
                                        (X_CHOOSE_THEN `pab:A`
                                         (X_CHOOSE_THEN `psa:A`
                                          (X_CHOOSE_THEN `psab:A`
                                           STRIP_ASSUME_TAC)))))))) THEN
    SUBGOAL_THEN `(top':A) = onebee` SUBST_ALL_TAC THENL
     [MATCH_MP_TAC(ISPECL
                   [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`top':A`;
                    `onebee:A`] ETOP_UNIQUE) THEN
      ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[ECBA_IMP_PORDER]; ALL_TAC] THEN
    MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`op:A`;`g:A`]
           EBV_IN_VAL_EXISTS) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(X_CHOOSE_THEN `w:A` STRIP_ASSUME_TAC) THEN
    MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`onebee:A`;`cp:A`]
           ECHECK_EXHAUSTION) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(X_CHOOSE_THEN `cpc:A` (LABEL_TAC "cpck")) THEN
    SUBGOAL_THEN `(cpc:A) IN D` ASSUME_TAC THENL
    [ASM_MESON_TAC[ECHECK_IMP]; ALL_TAC] THEN
    MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`cpc:A`;`w:A`]
           EOPAIR_EXISTS) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(X_CHOOSE_THEN `z:A` (LABEL_TAC "zop")) THEN
    SUBGOAL_THEN `(z:A) IN D` ASSUME_TAC THENL
    [ASM_MESON_TAC[EOPAIR_IN]; ALL_TAC] THEN
    EXISTS_TAC `z:A` THEN CONJ_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    MAP_EVERY EXISTS_TAC
      [`xi:A`;`alpha:A`;`xic:A`;`rdot:A`;`op:A`;`w:A`;`cpc:A`] THEN
      ASM_REWRITE_TAC[] THEN
    MAP_EVERY EXISTS_TAC [`paa:A`;`pab:A`;`sa:A`;`sab:A`;`psa:A`;`psab:A`] THEN
    ASM_REWRITE_TAC[] THEN REPEAT CONJ_TAC THENL
     [USE_THEN "ep1" MATCH_MP_TAC THEN ASM_REWRITE_TAC[];
      USE_THEN "ep2" MATCH_MP_TAC THEN ASM_REWRITE_TAC[];
      USE_THEN "ep2" MATCH_MP_TAC THEN ASM_REWRITE_TAC[]]; ALL_TAC] THEN
  (* repl-apply *)
  FIRST_ASSUM(MP_TAC o SPECL
   [`hname_form`; `0`; `1`; `vv:num->A`; `cr:A`] o MATCH_MP
     ZF_REPLACEMENT) THEN
  (* ants-open *)
  ANTS_TAC THENL
   [REWRITE_TAC[ARITH_EQ] THEN ASM_REWRITE_TAC[] THEN
    X_GEN_TAC `cp:A` THEN STRIP_TAC THEN
    USE_THEN "val" (MP_TAC o SPEC `cp:A`) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(X_CHOOSE_THEN `w0:A` (CONJUNCTS_THEN2 ASSUME_TAC
      (X_CHOOSE_THEN `xi0:A` (X_CHOOSE_THEN `alpha0:A` (X_CHOOSE_THEN `xic0:A`
       (X_CHOOSE_THEN `rdot0:A` (X_CHOOSE_THEN `op0:A` (X_CHOOSE_THEN `win0:A`
        (X_CHOOSE_THEN `cpc0:A`
         (REPEAT_TCL CONJUNCTS_THEN ASSUME_TAC)))))))))) THEN
    EXISTS_TAC `w0:A` THEN ASM_REWRITE_TAC[] THEN
    X_GEN_TAC `w':A` THEN STRIP_TAC THEN
    USE_THEN "hc" (MP_TAC o SPECL [`cp:A`; `w':A`]) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(MP_TAC o C EQ_MP (ASSUME
      `holds D E ((1 |-> (w':A)) ((0 |-> (cp:A)) vv)) hname_form`)) THEN
    DISCH_THEN(X_CHOOSE_THEN `xi':A`
               (X_CHOOSE_THEN `alpha':A` (X_CHOOSE_THEN `xic':A`
                                          (X_CHOOSE_THEN `rdot':A`
                                           (X_CHOOSE_THEN `op':A`
                                            (X_CHOOSE_THEN `win':A`
                                             (X_CHOOSE_THEN `cpc':A`
                                                (REPEAT_TCL CONJUNCTS_THEN
                                                ASSUME_TAC)))))))) THEN
    (* xi'=xi0 /\ alpha'=alpha0 via EOPAIR_INJ on eopair . . cp *)
    MP_TAC(ISPECL
           [`D:A->bool`;`E:A->A->bool`;`xi':A`;`alpha':A`;`xi0:A`;
            `alpha0:A`;`cp:A`]
           EOPAIR_INJ) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(CONJUNCTS_THEN SUBST_ALL_TAC) THEN
    (* xic'=xic0 *)
    SUBGOAL_THEN `xic':A = xic0` SUBST_ALL_TAC THENL
     [MP_TAC(ISPECL
             [`D:A->bool`;`E:A->A->bool`;`onebee:A`;`xi0:A`;`xic':A`;`xic0:A`]
             ECHECK_SV) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC]; ALL_TAC] THEN
    (* rdot'=rdot0 *)
    SUBGOAL_THEN `rdot':A = rdot0` SUBST_ALL_TAC THENL
     [MP_TAC(ISPECL
             [`D:A->bool`;`E:A->A->bool`;`realfn:A`;`alpha0:A`;`rdot':A`;
              `rdot0:A`] EAPPLY_UNIQUE) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC]; ALL_TAC] THEN
    (* op'=op0 via OPNCELL_FUNCTIONAL *)
    SUBGOAL_THEN `op':A = op0` SUBST_ALL_TAC THENL
     [MP_TAC(ISPECL
             [`D:A->bool`;`E:A->A->bool`;`xic0:A`;`rdot0:A`;`onebee:A`;
              `op':A`;`op0:A`]
             OPNCELL_FUNCTIONAL) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC]; ALL_TAC] THEN
    (* win'=win0 via EBV_IN_UNIQUE *)
    SUBGOAL_THEN `win':A = win0` SUBST_ALL_TAC THENL
     [MP_TAC(ISPECL
             [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`op0:A`;`g:A`;
              `win':A`;`win0:A`]
             EBV_IN_UNIQUE) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC]; ALL_TAC] THEN
    (* cpc'=cpc0 *)
    SUBGOAL_THEN `cpc':A = cpc0` SUBST_ALL_TAC THENL
     [MP_TAC(ISPECL
             [`D:A->bool`;`E:A->A->bool`;`onebee:A`;`cp:A`;`cpc':A`;`cpc0:A`]
             ECHECK_SV) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC]; ALL_TAC] THEN
    (* w'=w0 via EOPAIR_UNIQUE *)
    MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`cpc0:A`;`win0:A`;`w':A`;`w0:A`]
           EOPAIR_UNIQUE) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC];
    ALL_TAC] THEN
  (* out-extract *)
  DISCH_THEN(X_CHOOSE_THEN `h:A`
             (CONJUNCTS_THEN2 ASSUME_TAC (LABEL_TAC "out"))) THEN
   EXISTS_TAC `h:A` THEN ASM_REWRITE_TAC[] THEN
   X_GEN_TAC `zz:A` THEN DISCH_TAC THEN
   USE_THEN "out" (MP_TAC o SPEC `zz:A`) THEN
   ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
   DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
   EQ_TAC THENL
    [DISCH_THEN(X_CHOOSE_THEN `cp:A` (CONJUNCTS_THEN2 ASSUME_TAC
       (CONJUNCTS_THEN2 ASSUME_TAC MP_TAC))) THEN
     USE_THEN "hc" (MP_TAC o SPECL [`cp:A`; `zz:A`]) THEN
     ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
     DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
     DISCH_THEN(X_CHOOSE_THEN `xi:A`
                (X_CHOOSE_THEN `alpha:A` (X_CHOOSE_THEN `xic:A`
                                          (X_CHOOSE_THEN `rdot:A`
                                           (X_CHOOSE_THEN `op:A`
                                            (X_CHOOSE_THEN `w:A`
                                             (X_CHOOSE_THEN `cpc:A`
                                                STRIP_ASSUME_TAC))))))) THEN
     MAP_EVERY EXISTS_TAC
       [`cp:A`;`xi:A`;`alpha:A`;`xic:A`;`rdot:A`;`op:A`;`w:A`;`cpc:A`] THEN
     ASM_REWRITE_TAC[] THEN
     MAP_EVERY EXISTS_TAC
       [`paa:A`;`pab:A`;`sa:A`;`sab:A`;`psa:A`;`psab:A`] THEN
       ASM_REWRITE_TAC[];
     DISCH_THEN(X_CHOOSE_THEN `cp:A`
                (X_CHOOSE_THEN `xi:A` (X_CHOOSE_THEN `alpha:A`
                                       (X_CHOOSE_THEN `xic:A`
                                        (X_CHOOSE_THEN `rdot:A`
                                         (X_CHOOSE_THEN `op:A`
                                          (X_CHOOSE_THEN `w:A`
                                           (X_CHOOSE_THEN `cpc:A`
                                            STRIP_ASSUME_TAC)))))))) THEN
     EXISTS_TAC `cp:A` THEN ASM_REWRITE_TAC[] THEN
     USE_THEN "hc" (MP_TAC o SPECL [`cp:A`; `zz:A`]) THEN
     ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
     DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
     MAP_EVERY EXISTS_TAC
       [`xi:A`;`alpha:A`;`xic:A`;`rdot:A`;`op:A`;`w:A`;`cpc:A`] THEN
     ASM_REWRITE_TAC[] THEN
     MAP_EVERY EXISTS_TAC
       [`paa:A`;`pab:A`;`sa:A`;`sab:A`;`psa:A`;`psab:A`] THEN
       ASM_REWRITE_TAC[]]);;

(* ============================================================================
   F7 (III / h-build H3): the h nice-name is a FUNCTION and a B-NAME.

   H2 built the SYNTAX/EXISTENCE of the CH-refuting nice name
       h = { <cp^, [[ opn(xi^, realfn alpha) IN g ]]> : cp = <xi,alpha> IN cr }
   over the index set cr = aleph1^ x aleph2^ (HNAME_EXISTS).  H3 proves the two
   semantic facts CH_CORE needs: `eisfun D E h` (HNAME_ISFUN) and
   `bname D E B h` (HNAME_BNAME).

   The index check-names cp^ are checks of Kuratowski PAIRS of ordinals, so
   single-valuedness of h cannot reuse the ordinal-only ECHECK_INJ
   directly.  The induction-free ladder below lifts check-injectivity two
   Kuratowski levels:
       ECHECK_INJ_STEP     common check value + element-injectivity => x = y
       ECHECK_INJ_ORDSET   x,y sets of ORDINALS                     => inj
       ECHECK_INJ_OPAIRORD x,y whose elements' elements are ordinals => inj
       CROSS_EE_ORD        elements-of-elements of a cross member are ordinals
       ECHECK_INJ_CROSS    cp,cq IN a1 x a2 share a check value      => cp = cq
   No meta-level membership induction is used; each level is pure
   extensionality + the banked ordinal ECHECK_INJ at the base.
   ========================================================================= *)
(* ============================================================================
   ECHECK injectivity ladder (induction-free) for check-names of PAIRS of
   ordinals.  Needed so the h-name's index check-names cp^ are injective
   (cp = <xi,alpha> a Kuratowski pair in a cross product a1 x a2), hence
   HNAME_ISFUN.  The banked ECHECK_INJ is ordinal-ONLY; this lifts it
   two Kuratowski levels with NO meta-level membership induction.

     STEP     : common check value + element-injectivity  => x = y   (extens.)
     ORDSET   : x,y sets of ORDINALS                        => inj
       (via ECHECK_INJ)
     OPAIRORD : x,y whose elements' elements are ordinals   => inj
       (via ORDSET)
     CROSS    : x,y in a1 x a2 (a1,a2 ordinals)             => inj
       (via OPAIRORD)
   ========================================================================= *)

let ECHECK_INJ_STEP = prove
 (`!D (E:A->A->bool) onebee x y v.
     model D E ZF_AX /\ onebee IN D /\ (!u:A. u IN D ==> elmem D E u) /\
     x IN D /\ y IN D /\
     echeck D E onebee x v /\ echeck D E onebee y v /\
     (!m n vm:A. m IN D /\ n IN D /\ E m x /\ E n y /\
                 echeck D E onebee m vm /\ echeck D E onebee n vm ==> m = n)
     ==> x = y`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  FIRST_X_ASSUM(LABEL_TAC "einj" o check (fun th ->
    is_forall(concl th) &&
    (let b = snd(strip_forall(concl th)) in is_imp b &&
     is_eq(snd(dest_imp b))))) THEN
  SUBGOAL_THEN `(v:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[ECHECK_IMP]; ALL_TAC] THEN
  FIRST_ASSUM(MATCH_MP_TAC o MATCH_MP ZF_EXTENSIONALITY) THEN
  ASM_REWRITE_TAC[] THEN X_GEN_TAC `w:A` THEN DISCH_TAC THEN EQ_TAC THEN
  DISCH_TAC THENL
   [MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`onebee:A`;`w:A`]
           ECHECK_EXHAUSTION) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(X_CHOOSE_TAC `vw:A`) THEN
    SUBGOAL_THEN `(vw:A) IN D` ASSUME_TAC THENL
    [ASM_MESON_TAC[ECHECK_IMP]; ALL_TAC] THEN
    MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`vw:A`;`onebee:A`]
           EOPAIR_EXISTS) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(X_CHOOSE_TAC `zw:A`) THEN
    SUBGOAL_THEN `(zw:A) IN D` ASSUME_TAC THENL
    [ASM_MESON_TAC[EOPAIR_IN]; ALL_TAC] THEN
    SUBGOAL_THEN `(E:A->A->bool) zw v` ASSUME_TAC THENL
     [MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`onebee:A`;`x:A`;`v:A`;`zw:A`]
             ECHECK_MEM) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
      MAP_EVERY EXISTS_TAC [`w:A`;`vw:A`] THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`onebee:A`;`y:A`;`v:A`;`zw:A`]
           ECHECK_MEM) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(MP_TAC o C EQ_MP (ASSUME `(E:A->A->bool) zw v`)) THEN
    DISCH_THEN(X_CHOOSE_THEN `n:A`
               (X_CHOOSE_THEN `vn:A` STRIP_ASSUME_TAC)) THEN
    MP_TAC(ISPECL
           [`D:A->bool`;`E:A->A->bool`;`vw:A`;`onebee:A`;`vn:A`;`onebee:A`;
            `zw:A`] EOPAIR_INJ) THEN
    ASM_REWRITE_TAC[] THEN STRIP_TAC THEN
    UNDISCH_TAC `vw:A = vn` THEN DISCH_THEN(SUBST_ALL_TAC o SYM) THEN
    USE_THEN "einj" (MP_TAC o SPECL [`w:A`;`n:A`;`vw:A`]) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN SUBST1_TAC THEN FIRST_ASSUM ACCEPT_TAC;
    MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`onebee:A`;`w:A`]
           ECHECK_EXHAUSTION) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(X_CHOOSE_TAC `vw:A`) THEN
    SUBGOAL_THEN `(vw:A) IN D` ASSUME_TAC THENL
    [ASM_MESON_TAC[ECHECK_IMP]; ALL_TAC] THEN
    MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`vw:A`;`onebee:A`]
           EOPAIR_EXISTS) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(X_CHOOSE_TAC `zw:A`) THEN
    SUBGOAL_THEN `(zw:A) IN D` ASSUME_TAC THENL
    [ASM_MESON_TAC[EOPAIR_IN]; ALL_TAC] THEN
    SUBGOAL_THEN `(E:A->A->bool) zw v` ASSUME_TAC THENL
     [MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`onebee:A`;`y:A`;`v:A`;`zw:A`]
             ECHECK_MEM) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
      MAP_EVERY EXISTS_TAC [`w:A`;`vw:A`] THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`onebee:A`;`x:A`;`v:A`;`zw:A`]
           ECHECK_MEM) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(MP_TAC o C EQ_MP (ASSUME `(E:A->A->bool) zw v`)) THEN
    DISCH_THEN(X_CHOOSE_THEN `m:A`
               (X_CHOOSE_THEN `vm:A` STRIP_ASSUME_TAC)) THEN
    MP_TAC(ISPECL
           [`D:A->bool`;`E:A->A->bool`;`vw:A`;`onebee:A`;`vm:A`;`onebee:A`;
            `zw:A`] EOPAIR_INJ) THEN
    ASM_REWRITE_TAC[] THEN STRIP_TAC THEN
    UNDISCH_TAC `vw:A = vm` THEN DISCH_THEN(SUBST_ALL_TAC o SYM) THEN
    USE_THEN "einj" (MP_TAC o SPECL [`m:A`;`w:A`;`vw:A`]) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(SUBST1_TAC o SYM) THEN FIRST_ASSUM ACCEPT_TAC]);;

let ECHECK_INJ_ORDSET = prove
 (`!D (E:A->A->bool) B onebee x y v.
     model D E ZF_AX /\ B IN D /\ onebee IN D /\ E onebee B /\
     (!u:A. u IN D ==> elmem D E u) /\
     x IN D /\ y IN D /\
     (!m. m IN D /\ (E:A->A->bool) m x ==> eordinal D E m) /\
     (!n. n IN D /\ (E:A->A->bool) n y ==> eordinal D E n) /\
     echeck D E onebee x v /\ echeck D E onebee y v
     ==> x = y`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  FIRST_X_ASSUM(LABEL_TAC "ordx" o check (fun th ->
    is_forall(concl th) && vfree_in `x:A` (concl th) &&
      not(vfree_in `y:A` (concl th)))) THEN
  FIRST_X_ASSUM(LABEL_TAC "ordy" o check (fun th ->
    is_forall(concl th) && vfree_in `y:A` (concl th))) THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`onebee:A`;`x:A`;`y:A`;`v:A`]
         ECHECK_INJ_STEP) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[] THEN
    MAP_EVERY X_GEN_TAC [`m:A`;`n:A`;`vm:A`] THEN STRIP_TAC THEN
    MP_TAC(ISPECL
           [`D:A->bool`;`E:A->A->bool`;`B:A`;`onebee:A`;`m:A`;`n:A`;`vm:A`]
           ECHECK_INJ) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
       [USE_THEN "ordx" (MATCH_MP_TAC o SPEC `m:A`) THEN ASM_REWRITE_TAC[];
        USE_THEN "ordy" (MATCH_MP_TAC o SPEC `n:A`) THEN ASM_REWRITE_TAC[]];
      DISCH_THEN ACCEPT_TAC];
    DISCH_THEN ACCEPT_TAC]);;

let ECHECK_INJ_OPAIRORD = prove
 (`!D (E:A->A->bool) B onebee cp cq v.
     model D E ZF_AX /\ B IN D /\ onebee IN D /\ E onebee B /\
     (!u:A. u IN D ==> elmem D E u) /\
     cp IN D /\ cq IN D /\
     (!s t:A. s IN D /\ t IN D /\ (E:A->A->bool) s cp /\ E t s ==>
      eordinal D E t) /\
     (!s t:A. s IN D /\ t IN D /\ (E:A->A->bool) s cq /\ E t s ==>
      eordinal D E t) /\
     echeck D E onebee cp v /\ echeck D E onebee cq v
     ==> cp = cq`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  FIRST_X_ASSUM(LABEL_TAC "eecp" o check (fun th ->
    is_forall(concl th) && vfree_in `cp:A` (concl th) &&
      not(vfree_in `cq:A` (concl th)))) THEN
  FIRST_X_ASSUM(LABEL_TAC "eecq" o check (fun th ->
    is_forall(concl th) && vfree_in `cq:A` (concl th))) THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`onebee:A`;`cp:A`;`cq:A`;`v:A`]
         ECHECK_INJ_STEP) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[] THEN
    MAP_EVERY X_GEN_TAC [`s:A`;`s':A`;`vs:A`] THEN STRIP_TAC THEN
    MP_TAC(ISPECL
           [`D:A->bool`;`E:A->A->bool`;`B:A`;`onebee:A`;`s:A`;`s':A`;`vs:A`]
           ECHECK_INJ_ORDSET) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
       [X_GEN_TAC `t:A` THEN STRIP_TAC THEN
        USE_THEN "eecp" (MATCH_MP_TAC o SPECL [`s:A`;`t:A`]) THEN
        ASM_REWRITE_TAC[];
        X_GEN_TAC `t:A` THEN STRIP_TAC THEN
        USE_THEN "eecq" (MATCH_MP_TAC o SPECL [`s':A`;`t:A`]) THEN
        ASM_REWRITE_TAC[]];
      DISCH_THEN ACCEPT_TAC];
    DISCH_THEN ACCEPT_TAC]);;

(* elements-of-elements of a cross-product member are ordinals: the reusable
   core of the two CONJ branches,
   parameterized on the member cc (= cp or cq). *)
let CROSS_EE_ORD = prove
 (`!D (E:A->A->bool) a1 a2 cr cc.
     model D E ZF_AX /\ eordinal D E a1 /\ eordinal D E a2 /\
     ecross D E a1 a2 cr /\ cc IN D /\ (E:A->A->bool) cc cr
     ==> !s t:A. s IN D /\ t IN D /\ E s cc /\ E t s ==> eordinal D E t`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  MAP_EVERY X_GEN_TAC [`s:A`;`t:A`] THEN STRIP_TAC THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`a1:A`;`a2:A`;`cr:A`;`cc:A`]
         ECROSS_MEMBER) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(MP_TAC o C EQ_MP (ASSUME `(E:A->A->bool) cc cr`)) THEN
  DISCH_THEN(X_CHOOSE_THEN `xi:A`
             (X_CHOOSE_THEN `alpha:A` STRIP_ASSUME_TAC)) THEN
  SUBGOAL_THEN `eordinal D (E:A->A->bool) xi` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`a1:A`;`xi:A`]
                 EORDINAL_MEMBER) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `eordinal D (E:A->A->bool) alpha` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`a2:A`;`alpha:A`]
                 EORDINAL_MEMBER) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(t:A) = xi \/ t = alpha` ASSUME_TAC THENL
   [UNDISCH_TAC `eopair D (E:A->A->bool) xi alpha cc` THEN
    REWRITE_TAC[eopair; epair] THEN
    DISCH_THEN(X_CHOOSE_THEN `sp:A`
               (X_CHOOSE_THEN `pp:A` STRIP_ASSUME_TAC)) THEN
    ASM_MESON_TAC[]; ALL_TAC] THEN
  ASM_MESON_TAC[]);;

let ECHECK_INJ_CROSS = prove
 (`!D (E:A->A->bool) B onebee a1 a2 cr cp cq v.
     model D E ZF_AX /\ B IN D /\ onebee IN D /\ E onebee B /\
     (!u:A. u IN D ==> elmem D E u) /\
     eordinal D E a1 /\ eordinal D E a2 /\ ecross D E a1 a2 cr /\
     cp IN D /\ cq IN D /\ (E:A->A->bool) cp cr /\ E cq cr /\
     echeck D E onebee cp v /\ echeck D E onebee cq v
     ==> cp = cq`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  MP_TAC(ISPECL
         [`D:A->bool`;`E:A->A->bool`;`B:A`;`onebee:A`;`cp:A`;`cq:A`;`v:A`]
         ECHECK_INJ_OPAIRORD) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
     [MATCH_MP_TAC(ISPECL
                   [`D:A->bool`;`E:A->A->bool`;`a1:A`;`a2:A`;`cr:A`;`cp:A`]
                   CROSS_EE_ORD) THEN
      ASM_REWRITE_TAC[];
      MATCH_MP_TAC(ISPECL
                   [`D:A->bool`;`E:A->A->bool`;`a1:A`;`a2:A`;`cr:A`;`cq:A`]
                   CROSS_EE_ORD) THEN
      ASM_REWRITE_TAC[]];
    DISCH_THEN ACCEPT_TAC]);;

(* ============================================================================
   HNAME_ISFUN + HNAME_BNAME : the h nice-name (h = {<cp^,[[opn(xi^,realfn a)
   IN g]]> : cp=<xi,alpha> IN cr=a1 x a2}) is a FUNCTION and a B-NAME.
   Mirror of COHEN_REALNAME_ISFUN / COHEN_REALNAME_BNAME, but the index check-
   names cp^ are checks of PAIRS of ordinals, so single-valuedness uses the new
   ECHECK_INJ_CROSS (not the ordinal-only ECHECK_INJ).  Load AFTER the ladder
   (ECHECK_INJ_STEP/ORDSET/OPAIRORD/CROSS_EE_ORD/ECHECK_INJ_CROSS).
   ========================================================================= *)

let HNAME_ISFUN = prove
 (`!D (E:A->A->bool) B leq onebee realfn g a1 a2 cr h.
     model D E ZF_AX /\ (!u:A. u IN D ==> elmem D E u) /\
     ecba D E B leq /\ B IN D /\ leq IN D /\
     onebee IN D /\ E onebee B /\
     realfn IN D /\ eisfun D E realfn /\ g IN D /\
     eordinal D E a1 /\ eordinal D E a2 /\
     a1 IN D /\ a2 IN D /\ cr IN D /\ ecross D E a1 a2 cr /\ h IN D /\
     (!zz. zz IN D ==>
          (E zz h <=>
           ?cp xi alpha xic rdot op w cpc.
                cp IN D /\ xi IN D /\ alpha IN D /\ xic IN D /\
                rdot IN D /\ op IN D /\ w IN D /\ cpc IN D /\
                (E:A->A->bool) cp cr /\
                eopair D E xi alpha cp /\ E xi a1 /\ E alpha a2 /\
                echeck D E onebee xi xic /\ eapply D E realfn alpha rdot /\
                (?paa pab sa sab psa psab.
                     paa IN D /\ pab IN D /\ sa IN D /\ sab IN D /\
                     psa IN D /\ psab IN D /\
                     eopair D E xic onebee paa /\ eopair D E rdot onebee pab /\
                     epair D E paa paa sa /\ epair D E paa pab sab /\
                     eopair D E sa onebee psa /\ eopair D E sab onebee psab /\
                     epair D E psa psab op) /\
                ebv_in D E B leq op g w /\
                echeck D E onebee cp cpc /\ eopair D E cpc w zz))
     ==> eisfun D E h`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  FIRST_X_ASSUM(LABEL_TAC "hchar" o
    check (fun th -> is_forall(concl th) && vfree_in `h:A` (concl th))) THEN
  REWRITE_TAC[eisfun] THEN ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
   [(* every element of h is a pair *)
    X_GEN_TAC `z:A` THEN STRIP_TAC THEN
    USE_THEN "hchar" (MP_TAC o SPEC `z:A`) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> MP_TAC(EQ_MP th (ASSUME `(E:A->A->bool) z h`))) THEN
    DISCH_THEN(X_CHOOSE_THEN `cp:A`
               (X_CHOOSE_THEN `xi:A` (X_CHOOSE_THEN `alpha:A`
                                      (X_CHOOSE_THEN `xic:A`
                                       (X_CHOOSE_THEN `rdot:A`
                                        (X_CHOOSE_THEN `op:A`
                                         (X_CHOOSE_THEN `w:A`
                                          (X_CHOOSE_THEN `cpc:A`
                                           STRIP_ASSUME_TAC)))))))) THEN
    MAP_EVERY EXISTS_TAC [`cpc:A`; `w:A`] THEN ASM_REWRITE_TAC[];
    (* single-valued *)
    MAP_EVERY X_GEN_TAC [`u:A`; `w0:A`; `w0':A`; `z:A`; `z':A`] THEN
    STRIP_TAC THEN
    SUBGOAL_THEN `(z:A) IN D /\ (z':A) IN D` STRIP_ASSUME_TAC THENL
     [ASM_MESON_TAC[EOPAIR_IN]; ALL_TAC] THEN
    USE_THEN "hchar" (MP_TAC o SPEC `z:A`) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> MP_TAC(EQ_MP th (ASSUME `(E:A->A->bool) z h`))) THEN
    DISCH_THEN(X_CHOOSE_THEN `cp1:A`
               (X_CHOOSE_THEN `xi1:A` (X_CHOOSE_THEN `alpha1:A`
                                       (X_CHOOSE_THEN `xic1:A`
                                        (X_CHOOSE_THEN `rdot1:A`
                                         (X_CHOOSE_THEN `op1:A`
                                          (X_CHOOSE_THEN `win1:A`
                                           (X_CHOOSE_THEN `cpc1:A`
                                            (REPEAT_TCL CONJUNCTS_THEN
                                                ASSUME_TAC))))))))) THEN
    USE_THEN "hchar" (MP_TAC o SPEC `z':A`) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> MP_TAC(EQ_MP th (ASSUME `(E:A->A->bool) z' h`))) THEN
    DISCH_THEN(X_CHOOSE_THEN `cp2:A`
               (X_CHOOSE_THEN `xi2:A` (X_CHOOSE_THEN `alpha2:A`
                                       (X_CHOOSE_THEN `xic2:A`
                                        (X_CHOOSE_THEN `rdot2:A`
                                         (X_CHOOSE_THEN `op2:A`
                                          (X_CHOOSE_THEN `win2:A`
                                           (X_CHOOSE_THEN `cpc2:A`
                                            (REPEAT_TCL CONJUNCTS_THEN
                                                ASSUME_TAC))))))))) THEN
    (* u = cpc1, w0 = win1 *)
    MP_TAC(ISPECL
           [`D:A->bool`;`E:A->A->bool`;`u:A`;`w0:A`;`cpc1:A`;`win1:A`;`z:A`]
           EOPAIR_INJ) THEN ASM_REWRITE_TAC[] THEN STRIP_TAC THEN
    (* u = cpc2, w0' = win2 *)
    MP_TAC(ISPECL
           [`D:A->bool`;`E:A->A->bool`;`u:A`;`w0':A`;`cpc2:A`;`win2:A`;`z':A`]
           EOPAIR_INJ) THEN ASM_REWRITE_TAC[] THEN STRIP_TAC THEN
    (* cpc2 = cpc1 (both equal u) *)
    SUBGOAL_THEN `(cpc2:A) = cpc1` SUBST_ALL_TAC THENL
     [ASM_MESON_TAC[]; ALL_TAC] THEN
    (* cp1 = cp2 via ECHECK_INJ_CROSS (shared check value cpc1) *)
    SUBGOAL_THEN `(cp1:A) = cp2` SUBST_ALL_TAC THENL
     [MATCH_MP_TAC(ISPECL
                   [`D:A->bool`;`E:A->A->bool`;`B:A`;`onebee:A`;`a1:A`;`a2:A`;
                    `cr:A`;`cp1:A`;`cp2:A`;`cpc1:A`] ECHECK_INJ_CROSS) THEN
      ASM_REWRITE_TAC[]; ALL_TAC] THEN
    (* xi1 = xi2, alpha1 = alpha2 via EOPAIR_INJ on eopair .. cp2 *)
    MP_TAC(ISPECL
           [`D:A->bool`;`E:A->A->bool`;`xi1:A`;`alpha1:A`;`xi2:A`;`alpha2:A`;
            `cp2:A`] EOPAIR_INJ) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(CONJUNCTS_THEN SUBST_ALL_TAC) THEN
    (* xic1 = xic2 *)
    SUBGOAL_THEN `xic1:A = xic2` SUBST_ALL_TAC THENL
     [MP_TAC(ISPECL
             [`D:A->bool`;`E:A->A->bool`;`onebee:A`;`xi2:A`;`xic1:A`;`xic2:A`]
             ECHECK_SV) THEN ANTS_TAC THENL
           [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC];
           ALL_TAC] THEN
    (* rdot1 = rdot2 *)
    SUBGOAL_THEN `rdot1:A = rdot2` SUBST_ALL_TAC THENL
     [MP_TAC(ISPECL
             [`D:A->bool`;`E:A->A->bool`;`realfn:A`;`alpha2:A`;
              `rdot1:A`;`rdot2:A`]
             EAPPLY_UNIQUE) THEN ANTS_TAC THENL
           [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC];
           ALL_TAC] THEN
    (* op1 = op2 via OPNCELL_FUNCTIONAL *)
    SUBGOAL_THEN `op1:A = op2` SUBST_ALL_TAC THENL
     [MP_TAC(ISPECL
             [`D:A->bool`;`E:A->A->bool`;`xic2:A`;`rdot2:A`;`onebee:A`;
              `op1:A`;`op2:A`]
             OPNCELL_FUNCTIONAL) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC]; ALL_TAC] THEN
    (* win1 = win2 via EBV_IN_UNIQUE *)
    SUBGOAL_THEN `win1:A = win2` SUBST_ALL_TAC THENL
     [MP_TAC(ISPECL
             [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`op2:A`;`g:A`;
              `win1:A`;`win2:A`]
             EBV_IN_UNIQUE) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC]; ALL_TAC] THEN
    ASM_REWRITE_TAC[]]);;

let HNAME_BNAME = prove
 (`!D (E:A->A->bool) B leq onebee realfn g a1 a2 cr h.
     model D E ZF_AX /\ (!u:A. u IN D ==> elmem D E u) /\
     ecba D E B leq /\ B IN D /\ leq IN D /\
     onebee IN D /\ E onebee B /\
     realfn IN D /\ eisfun D E realfn /\ g IN D /\
     eordinal D E a1 /\ eordinal D E a2 /\
     a1 IN D /\ a2 IN D /\ cr IN D /\ ecross D E a1 a2 cr /\ h IN D /\
     (!zz. zz IN D ==>
          (E zz h <=>
           ?cp xi alpha xic rdot op w cpc.
                cp IN D /\ xi IN D /\ alpha IN D /\ xic IN D /\
                rdot IN D /\ op IN D /\ w IN D /\ cpc IN D /\
                (E:A->A->bool) cp cr /\
                eopair D E xi alpha cp /\ E xi a1 /\ E alpha a2 /\
                echeck D E onebee xi xic /\ eapply D E realfn alpha rdot /\
                (?paa pab sa sab psa psab.
                     paa IN D /\ pab IN D /\ sa IN D /\ sab IN D /\
                     psa IN D /\ psab IN D /\
                     eopair D E xic onebee paa /\ eopair D E rdot onebee pab /\
                     epair D E paa paa sa /\ epair D E paa pab sab /\
                     eopair D E sa onebee psa /\ eopair D E sab onebee psab /\
                     epair D E psa psab op) /\
                ebv_in D E B leq op g w /\
                echeck D E onebee cp cpc /\ eopair D E cpc w zz))
     ==> bname D E B h`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  FIRST_X_ASSUM(LABEL_TAC "hchar" o
    check (fun th -> is_forall(concl th) && vfree_in `h:A` (concl th))) THEN
  SUBGOAL_THEN `eisfun D (E:A->A->bool) h` ASSUME_TAC THENL
   [MP_TAC(ISPECL
           [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`onebee:A`;`realfn:A`;
            `g:A`;`a1:A`;`a2:A`;`cr:A`;`h:A`] HNAME_ISFUN) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`h:A`] EDOMAIN_EXISTS) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `dh:A` (CONJUNCTS_THEN2 (LABEL_TAC "dhD")
    (LABEL_TAC "domch") o REWRITE_RULE[edomain])) THEN
  (* every element of dh is a bname: it is a check-name cp^ *)
  SUBGOAL_THEN `!u:A. u IN D /\ E u dh ==> bname D (E:A->A->bool) B u`
    (LABEL_TAC "dhbn") THENL
   [X_GEN_TAC `u:A` THEN STRIP_TAC THEN
    USE_THEN "domch" (MP_TAC o SPEC `u:A`) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> MP_TAC(EQ_MP th (ASSUME `(E:A->A->bool) u dh`))) THEN
    REWRITE_TAC[eindom] THEN
    DISCH_THEN(X_CHOOSE_THEN `q:A` STRIP_ASSUME_TAC) THEN
    UNDISCH_TAC `eapply D (E:A->A->bool) h u q` THEN
    DISCH_THEN(MP_TAC o REWRITE_RULE[eapply]) THEN
    DISCH_THEN(X_CHOOSE_THEN `zz:A` STRIP_ASSUME_TAC) THEN
    SUBGOAL_THEN `(zz:A) IN D` ASSUME_TAC THENL
    [ASM_MESON_TAC[EOPAIR_IN]; ALL_TAC] THEN
    USE_THEN "hchar" (MP_TAC o SPEC `zz:A`) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> MP_TAC(EQ_MP th (ASSUME `(E:A->A->bool) zz h`))) THEN
    DISCH_THEN(X_CHOOSE_THEN `cp:A`
               (X_CHOOSE_THEN `xi:A` (X_CHOOSE_THEN `alpha:A`
                                      (X_CHOOSE_THEN `xic:A`
                                       (X_CHOOSE_THEN `rdot:A`
                                        (X_CHOOSE_THEN `op:A`
                                         (X_CHOOSE_THEN `w:A`
                                          (X_CHOOSE_THEN `cpc:A`
                                           STRIP_ASSUME_TAC)))))))) THEN
    MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`cpc:A`;`w:A`;`u:A`;`q:A`;`zz:A`]
      EOPAIR_INJ) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(CONJUNCTS_THEN SUBST_ALL_TAC) THEN
    MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`onebee:A`;`B:A`;`cp:A`;`u:A`]
                 ECHECK_IS_BNAME) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`dh:A`] BNAME_BOUND) THEN
  ASM_REWRITE_TAC[] THEN
  INTRO_TAC "@c yc. cD ycD cord ycstage ycsub" THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`c:A`] ESUC_EXISTS) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `sa:A`) THEN
  SUBGOAL_THEN
    `(sa:A) IN D /\ eordinal D (E:A->A->bool) sa /\ (E:A->A->bool) c sa`
    STRIP_ASSUME_TAC THENL
   [REPEAT CONJ_TAC THENL
     [MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`c:A`;`sa:A`] ESUC_IN) THEN
      ASM_REWRITE_TAC[];
      MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`c:A`;`sa:A`]
             EORDINAL_ESUC) THEN
      ASM_REWRITE_TAC[];
      MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`c:A`;`sa:A`] ESUC_MEMBER) THEN
      ASM_REWRITE_TAC[]]; ALL_TAC] THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`sa:A`] EBNSTAGE_EXISTS) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `ysa:A` STRIP_ASSUME_TAC) THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`sa:A`;`ysa:A`]
         EBNSTAGE_CHAR) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `w1:A` (CONJUNCTS_THEN2 (LABEL_TAC "w1D")
    (CONJUNCTS_THEN2 (LABEL_TAC "w1ch") (LABEL_TAC "funs")))) THEN
  SUBGOAL_THEN `!u:A. u IN D /\ (E:A->A->bool) u yc ==> E u w1`
    (LABEL_TAC "Ysub") THENL
   [X_GEN_TAC `u:A` THEN STRIP_TAC THEN
    USE_THEN "w1ch" (fun th ->
      REWRITE_TAC[MP (SPEC `u:A` th) (ASSUME `(u:A) IN D`)]) THEN
    MAP_EVERY EXISTS_TAC [`c:A`; `yc:A`] THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  REMOVE_THEN "w1ch" (K ALL_TAC) THEN
  SUBGOAL_THEN `ebnmem D (E:A->A->bool) B w1 h` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`h:A`;`w1:A`]
      EBNMEM_GENERAL) THEN ASM_REWRITE_TAC[] THEN
    X_GEN_TAC `z:A` THEN STRIP_TAC THEN
    USE_THEN "hchar" (MP_TAC o SPEC `z:A`) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> MP_TAC(EQ_MP th (ASSUME `(E:A->A->bool) z h`))) THEN
    DISCH_THEN(X_CHOOSE_THEN `cp:A`
               (X_CHOOSE_THEN `xi:A` (X_CHOOSE_THEN `alpha:A`
                                      (X_CHOOSE_THEN `xic:A`
                                       (X_CHOOSE_THEN `rdot:A`
                                        (X_CHOOSE_THEN `op:A`
                                         (X_CHOOSE_THEN `w:A`
                                          (X_CHOOSE_THEN `cpc:A`
                                           STRIP_ASSUME_TAC)))))))) THEN
    MAP_EVERY EXISTS_TAC [`cpc:A`; `w:A`] THEN ASM_REWRITE_TAC[] THEN
    CONJ_TAC THENL
     [USE_THEN "Ysub" MATCH_MP_TAC THEN ASM_REWRITE_TAC[] THEN
      USE_THEN "ycsub" MATCH_MP_TAC THEN ASM_REWRITE_TAC[] THEN
      USE_THEN "domch" (MP_TAC o SPEC `cpc:A`) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
      REWRITE_TAC[eindom] THEN EXISTS_TAC `w:A` THEN
      ASM_REWRITE_TAC[eapply] THEN EXISTS_TAC `z:A` THEN ASM_REWRITE_TAC[];
      MATCH_MP_TAC(ISPECL
                   [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`op:A`;
                    `g:A`;`w:A`]
                   EBV_IN_IN_B) THEN ASM_REWRITE_TAC[]];
    ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) h ysa` ASSUME_TAC THENL
   [UNDISCH_TAC `ebnfuns D (E:A->A->bool) B w1 ysa` THEN
    REWRITE_TAC[ebnfuns] THEN
    DISCH_THEN(MP_TAC o SPEC `h:A` o CONJUNCT2) THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  REWRITE_TAC[bname] THEN MAP_EVERY EXISTS_TAC [`sa:A`; `ysa:A`] THEN
  ASM_REWRITE_TAC[]);;

(* ============================================================================
   F7 (III / h-build H4): HNAME_MEM_VALUE -- the diagonal
     membership value of h.

   For the fixed index pair cp0 (with check cpc0) whose h-cell is <cpc0, bb>
   (bb = [[ opn(xi0^, realfn alpha0) IN g ]], supplied as `eapply h cpc0 bb`),
       [[ cpc0 IN h ]]  =  bb.
   Mirror of COHEN_MEM_VALUE (EBV_IN_DIAG diagonal argument),
   but SIMPLER: since
   `eisfun h` is available (HNAME_ISFUN), the diagonal value is pinned by
   EAPPLY_UNIQUE (y = cpc0 ==> qy = bb) with no OPNCELL_FUNCTIONAL needed, and
   the graph decomposition only has to project out `echeck onebee cp y`.  The
   off-diagonal (cp0 =/= cp) vanishes by ECHECK_EQ_BOT exactly as in COHEN.
   ========================================================================= *)

let HNAME_MEM_VALUE = prove
 (`!D (E:A->A->bool) B leq onebee realfn g a1 a2 cr h cp0 cpc0 bb z.
     model D E ZF_AX /\ (!u:A. u IN D ==> elmem D E u) /\
     ecba D E B leq /\ B IN D /\ leq IN D /\ onebee IN D /\ E onebee B /\
     etop D E B leq onebee /\
     h IN D /\ eisfun D E h /\
     (!zz. zz IN D ==>
          (E zz h <=>
           ?cp xi alpha xic rdot op w cpc.
                cp IN D /\ xi IN D /\ alpha IN D /\ xic IN D /\
                rdot IN D /\ op IN D /\ w IN D /\ cpc IN D /\
                (E:A->A->bool) cp cr /\
                eopair D E xi alpha cp /\ E xi a1 /\ E alpha a2 /\
                echeck D E onebee xi xic /\ eapply D E realfn alpha rdot /\
                (?paa pab sa sab psa psab.
                     paa IN D /\ pab IN D /\ sa IN D /\ sab IN D /\
                     psa IN D /\ psab IN D /\
                     eopair D E xic onebee paa /\ eopair D E rdot onebee pab /\
                     epair D E paa paa sa /\ epair D E paa pab sab /\
                     eopair D E sa onebee psa /\ eopair D E sab onebee psab /\
                     epair D E psa psab op) /\
                ebv_in D E B leq op g w /\
                echeck D E onebee cp cpc /\ eopair D E cpc w zz)) /\
     cp0 IN D /\ cpc0 IN D /\ bb IN D /\ E bb B /\
     echeck D E onebee cp0 cpc0 /\
     eapply D E h cpc0 bb /\
     z IN D /\ ebv_in D E B leq cpc0 h z
     ==> z = bb`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  FIRST_X_ASSUM(LABEL_TAC "hchar" o
    check (fun th -> is_forall(concl th) && vfree_in `h:A` (concl th))) THEN
  SUBGOAL_THEN `eporder D (E:A->A->bool) (B:A) (leq:A)` ASSUME_TAC THENL
   [ASM_MESON_TAC[ECBA_IMP_PORDER]; ALL_TAC] THEN
  (* ---- slim graph: eapply h y qy ==> y is the check of some cp ---- *)
  SUBGOAL_THEN
   `!y qy. y IN D /\ qy IN D /\ eapply D (E:A->A->bool) h y qy
           ==> ?cp. cp IN D /\ echeck D E onebee cp y`
   (LABEL_TAC "hgraph") THENL
   [MAP_EVERY X_GEN_TAC [`y:A`;`qy:A`] THEN STRIP_TAC THEN
    UNDISCH_TAC `eapply D (E:A->A->bool) h y qy` THEN
    DISCH_THEN(MP_TAC o REWRITE_RULE[eapply]) THEN
    DISCH_THEN(X_CHOOSE_THEN `pp:A` STRIP_ASSUME_TAC) THEN
    SUBGOAL_THEN `(pp:A) IN D` ASSUME_TAC THENL
     [ASM_MESON_TAC[EOPAIR_IN]; ALL_TAC] THEN
    USE_THEN "hchar" (MP_TAC o SPEC `pp:A`) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th ->
               MP_TAC(EQ_MP th (ASSUME `(E:A->A->bool) (pp:A) h`))) THEN
    DISCH_THEN(X_CHOOSE_THEN `cp:A`
               (X_CHOOSE_THEN `xi:A` (X_CHOOSE_THEN `alpha:A`
                                      (X_CHOOSE_THEN `xic:A`
                                       (X_CHOOSE_THEN `rdot:A`
                                        (X_CHOOSE_THEN `op:A`
                                         (X_CHOOSE_THEN `w:A`
                                          (X_CHOOSE_THEN `cpc:A`
                                           STRIP_ASSUME_TAC)))))))) THEN
    MP_TAC(ISPECL
           [`D:A->bool`;`E:A->A->bool`;`cpc:A`;`w:A`;`y:A`;`qy:A`;`pp:A`]
           EOPAIR_INJ) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(CONJUNCTS_THEN SUBST_ALL_TAC) THEN
    EXISTS_TAC `cp:A` THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* ---- bname cpc0 and e0 = [[cpc0 = cpc0]] = top ---- *)
  SUBGOAL_THEN `bname D (E:A->A->bool) B cpc0` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`onebee:A`;`B:A`;`cp0:A`;`cpc0:A`]
                 ECHECK_IS_BNAME) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`cpc0:A`;`cpc0:A`]
    EBV_EQ_VAL_EXISTS) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `e0:A` STRIP_ASSUME_TAC) THEN
  SUBGOAL_THEN `etop D (E:A->A->bool) (B:A) (leq:A) (e0:A)` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`onebee:A`;
      `cp0:A`;`cp0:A`;`cpc0:A`;`cpc0:A`;`e0:A`] ECHECK_EQ_TOP) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* ---- diagonal dominance ---- *)
  SUBGOAL_THEN
   `!y qy ey c. y IN D /\ qy IN D /\ ey IN D /\ c IN D /\
       eapply D (E:A->A->bool) h y qy /\ ebv_eq D E B leq cpc0 y ey /\
       emeet D E B leq qy ey c ==> erel D E leq c bb`
   ASSUME_TAC THENL
   [MAP_EVERY X_GEN_TAC [`y:A`; `qy:A`; `ey:A`; `c:A`] THEN STRIP_TAC THEN
    USE_THEN "hgraph" (MP_TAC o SPECL [`y:A`; `qy:A`]) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(X_CHOOSE_THEN `cp:A` STRIP_ASSUME_TAC) THEN
    ASM_CASES_TAC `(cp0:A) = cp` THENL
     [(* diagonal: y = cpc0, qy = bb, ey top, c = bb *)
      UNDISCH_TAC `(cp0:A) = cp` THEN DISCH_THEN(SUBST_ALL_TAC o SYM) THEN
      SUBGOAL_THEN `(y:A) = cpc0` SUBST_ALL_TAC THENL
       [MP_TAC(ISPECL
               [`D:A->bool`;`E:A->A->bool`;`onebee:A`;`cp0:A`;`y:A`;`cpc0:A`]
               ECHECK_SV) THEN ANTS_TAC THENL
      [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC];
      ALL_TAC] THEN
      SUBGOAL_THEN `(qy:A) = bb` SUBST_ALL_TAC THENL
       [MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`h:A`;`cpc0:A`;`qy:A`;`bb:A`]
          EAPPLY_UNIQUE) THEN ANTS_TAC THENL
      [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC];
      ALL_TAC] THEN
      SUBGOAL_THEN `etop D (E:A->A->bool) (B:A) (leq:A) (ey:A)`
        ASSUME_TAC THENL
        [MATCH_MP_TAC(ISPECL
                      [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`onebee:A`;
                       `cp0:A`;`cp0:A`;`cpc0:A`;`cpc0:A`;`ey:A`]
                        ECHECK_EQ_TOP) THEN
        ASM_REWRITE_TAC[]; ALL_TAC] THEN
      SUBGOAL_THEN `emeet D (E:A->A->bool) (B:A) (leq:A) (bb:A) (ey:A) (bb:A)`
        ASSUME_TAC THENL
        [MATCH_MP_TAC EMEET_TOP THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
      SUBGOAL_THEN `(c:A) = bb` SUBST_ALL_TAC THENL
       [MP_TAC(ISPECL
               [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`bb:A`;`ey:A`;
                `c:A`;`bb:A`]
               EMEET_UNIQUE) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
      MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`bb:A`]
                   EPORDER_REFL) THEN
      ASM_REWRITE_TAC[];
      (* off-diagonal: ey = bot, c <= ey <= bb *)
      SUBGOAL_THEN `ebot D (E:A->A->bool) (B:A) (leq:A) (ey:A)`
        ASSUME_TAC THENL
        [MATCH_MP_TAC(ISPECL
                      [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`onebee:A`;
                       `cp0:A`;`cp:A`;`cpc0:A`;`y:A`;`ey:A`]
                        ECHECK_EQ_BOT) THEN
        ASM_REWRITE_TAC[]; ALL_TAC] THEN
      SUBGOAL_THEN `E (ey:A) (B:A) /\ E (c:A) (B:A)` STRIP_ASSUME_TAC THENL
       [CONJ_TAC THENL
         [MATCH_MP_TAC(ISPECL
                       [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`cpc0:A`;
                        `y:A`;`ey:A`]
                       EBV_EQ_IN_B) THEN ASM_REWRITE_TAC[];
          ASM_MESON_TAC[EMEET_IN]]; ALL_TAC] THEN
      MATCH_MP_TAC(ISPECL
                   [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`c:A`;
                    `ey:A`;`bb:A`]
                   EPORDER_TRANS) THEN
      ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
       [ASM_MESON_TAC[EMEET_LE];
        MATCH_MP_TAC(ISPECL
                     [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`ey:A`;`bb:A`]
                     EBOT_LE) THEN ASM_REWRITE_TAC[]]];
    ALL_TAC] THEN
  (* ---- EBV_IN_DIAG ---- *)
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`cpc0:A`;`h:A`;
    `bb:A`;`e0:A`;`z:A`] EBV_IN_DIAG) THEN
  ANTS_TAC THENL
  [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; DISCH_THEN ACCEPT_TAC]);;

(* ############################################################################
   F7 (III) CH_CORE value-plumbing -- PIECE (A3):  [[ pow_form pw om^ ]] = top.
   Three lemmas:
     SUBSETFORM_VAL      [[subset_form i j]]_vv = esubval (vv j) (vv
       i)   (any i,j)
     BVALF_POW_FORM_TOP  [[pow_form 2 0]]_v = top   when v2=pn a
       power-name of v0=x
     POWNAME_OF          x a bname  ==>  a power-name pn of x exists with the
                         full EBV_IN_POW clause bundle (FS = x's own
                           bname stage).
   SUBSETFORM_VAL is a slot-abstracted version of POW_RHS_SUBVAL;
   BVALF_POW_FORM_TOP and POWNAME_OF factor BVALF_POWERSET into a value
   equation and a name constructor.
   ######################################################################### *)

(* ============================================================================
   (A3) lemma 1 -- SUBSETFORM_VAL : the Boolean value of subset_form.
     [[ subset_form i j ]]_vv  =  esubval (vv j) (vv i)   ( = [[ vv_i
       SUBSET vv_j ]] )
   Slot-abstracted clone of POW_RHS_SUBVAL (hardcoded to slots 3/2/0 of
   !!- 3 2 (3%%0)); here the ranging var = MAX i j + 1,
   subset-candidate slot = i,
   superset slot = j.  Reused by (A3) [i=3,j=0] and (A1b) [i=0,j=1].
   ========================================================================= *)

let SUBSETFORM_VAL = prove
 (`!D (E:A->A->bool) B leq vv i j tt xx zr.
      model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
      valuation D vv /\ (!n. bname D E B (vv n)) /\
      vv i = tt /\ vv j = xx /\
      xx IN D /\ bname D E B xx /\ tt IN D /\ bname D E B tt /\
      esubval D E B leq xx tt zr /\ zr IN D
      ==> bvalf D E B leq vv (subset_form i j) = zr`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  REWRITE_TAC[subset_form] THEN
  SUBGOAL_THEN `ebalg D (E:A->A->bool) B leq` ASSUME_TAC THENL
   [ASM_MESON_TAC[ECBA_IMP_BALG]; ALL_TAC] THEN
  SUBGOAL_THEN `eporder D (E:A->A->bool) B leq` ASSUME_TAC THENL
   [ASM_MESON_TAC[EBALG_IMP_PORDER]; ALL_TAC] THEN
  REWRITE_TAC[Forallmem_DEF] THEN
  SUBGOAL_THEN
   `bvalf D (E:A->A->bool) B leq vv
       (!! (MAX i j + 1)
        (((MAX i j + 1) %% i) --> ((MAX i j + 1) %% j))) IN D /\
    (E:A->A->bool) (bvalf D E B leq vv
       (!! (MAX i j + 1) (((MAX i j + 1) %% i) --> ((MAX i j + 1) %% j)))) B`
  STRIP_ASSUME_TAC THENL
   [CONJ_TAC THENL
     [MP_TAC(ISPECL
             [`!! (MAX i j + 1)
               (((MAX i j + 1) %% i) --> ((MAX i j + 1) %% j))`;
              `D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`vv:num->A`]
               BVALF_SPEC) THEN
      ASM_SIMP_TAC[];
      MP_TAC(ISPECL
             [`!! (MAX i j + 1)
               (((MAX i j + 1) %% i) --> ((MAX i j + 1) %% j))`;
              `D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`vv:num->A`]
               BVALF_IN_B) THEN
      ASM_SIMP_TAC[]];
    ALL_TAC] THEN
  (* per-bname body-value characterization used by both GLB directions *)
  SUBGOAL_THEN
   `!c zwf zwx ii.
        c IN D /\ bname D E B c /\ zwf IN D /\ zwx IN D /\ ii IN D /\
        ebv_in D E B leq c tt zwf /\ ebv_in D E B leq c xx zwx /\
        ebimp D E B leq zwf zwx ii
        ==> bvalf D (E:A->A->bool) B leq (((MAX i j + 1) |-> c) vv)
              (((MAX i j + 1) %% i) --> ((MAX i j + 1) %% j)) = ii`
  (LABEL_TAC "body") THENL
   [REPEAT GEN_TAC THEN STRIP_TAC THEN
    SUBGOAL_THEN `valuation D (((MAX i j + 1) |-> (c:A)) (vv:num->A)) /\
                  (!n. bname D E B
                   ((((MAX i j + 1) |-> (c:A)) (vv:num->A)) n))`
    STRIP_ASSUME_TAC THENL
     [CONJ_TAC THENL
       [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[];
        MATCH_MP_TAC BNAMEVAL_VALMOD THEN ASM_REWRITE_TAC[]]; ALL_TAC] THEN
    SUBGOAL_THEN `(((MAX i j + 1) |-> (c:A)) (vv:num->A)) (MAX i j + 1) = c /\
                  (((MAX i j + 1) |-> (c:A)) (vv:num->A)) i = tt /\
                  (((MAX i j + 1) |-> (c:A)) (vv:num->A)) j = xx`
    STRIP_ASSUME_TAC THENL
     [ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER;
        ARITH_RULE `~(i = MAX i j + 1) /\ ~(j = MAX i j + 1) /\
                    ~(MAX i j + 1 = i) /\ ~(MAX i j + 1 = j)`]; ALL_TAC] THEN
    SUBGOAL_THEN `(E:A->A->bool) zwf B` ASSUME_TAC THENL
     [MATCH_MP_TAC(ISPECL
                   [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`c:A`;`tt:A`;
                    `zwf:A`] EBV_IN_IN_B) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN
      `bvalf D (E:A->A->bool) B leq (((MAX i j + 1) |-> (c:A)) (vv:num->A))
       ((MAX i j + 1) %% i) IN D /\
       bvalf D (E:A->A->bool) B leq (((MAX i j + 1) |-> (c:A)) (vv:num->A))
         ((MAX i j + 1) %% j) IN D`
    STRIP_ASSUME_TAC THENL
     [CONJ_TAC THENL
       [MP_TAC(ISPECL
               [`(MAX i j + 1) %% i`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
                `((MAX i j + 1) |-> (c:A)) (vv:num->A)`] BVALF_SPEC) THEN
                   ASM_SIMP_TAC[];
                   MP_TAC(ISPECL
                          [`(MAX i j + 1) %% j`;`D:A->bool`;`E:A->A->bool`;
                           `B:A`;`leq:A`;
                           `((MAX i j + 1) |-> (c:A)) (vv:num->A)`]
                            BVALF_SPEC) THEN ASM_SIMP_TAC[]];
      ALL_TAC] THEN
    SUBGOAL_THEN
      `ebv_in D (E:A->A->bool) B leq c tt
          (bvalf D E B leq (((MAX i j + 1) |-> (c:A)) (vv:num->A))
           ((MAX i j + 1) %% i)) /\
       ebv_in D (E:A->A->bool) B leq c xx
          (bvalf D E B leq (((MAX i j + 1) |-> (c:A)) (vv:num->A))
           ((MAX i j + 1) %% j))`
    STRIP_ASSUME_TAC THENL
     [CONJ_TAC THENL
       [MP_TAC(ISPECL
               [`MAX i j + 1`;`i:num`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
                `((MAX i j + 1) |-> (c:A)) (vv:num->A)`] BVALF_MEM) THEN
           ASM_REWRITE_TAC[];
           MP_TAC(ISPECL
                  [`MAX i j + 1`;`j:num`;`D:A->bool`;`E:A->A->bool`;
                   `B:A`;`leq:A`;
                   `((MAX i j + 1) |-> (c:A)) (vv:num->A)`] BVALF_MEM) THEN
           ASM_REWRITE_TAC[]];
      ALL_TAC] THEN
    SUBGOAL_THEN
      `bvalf D (E:A->A->bool) B leq (((MAX i j + 1) |-> (c:A)) (vv:num->A))
       ((MAX i j + 1) %% i) = zwf /\
       bvalf D (E:A->A->bool) B leq (((MAX i j + 1) |-> (c:A)) (vv:num->A))
         ((MAX i j + 1) %% j) = zwx`
    STRIP_ASSUME_TAC THENL
     [CONJ_TAC THENL
       [MATCH_MP_TAC(ISPECL
                     [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`c:A`;`tt:A`;
                      `bvalf D (E:A->A->bool) B leq
                       (((MAX i j + 1) |-> (c:A)) (vv:num->A))
                       ((MAX i j + 1) %% i)`;
          `zwf:A`] EBV_IN_UNIQUE) THEN ASM_REWRITE_TAC[];
        MATCH_MP_TAC(ISPECL
                     [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`c:A`;`xx:A`;
                      `bvalf D (E:A->A->bool) B leq
                       (((MAX i j + 1) |-> (c:A)) (vv:num->A))
                       ((MAX i j + 1) %% j)`;
          `zwx:A`] EBV_IN_UNIQUE) THEN ASM_REWRITE_TAC[]];
      ALL_TAC] THEN
    MP_TAC(ISPECL
           [`(MAX i j + 1) %% i`;`(MAX i j + 1) %% j`;`D:A->bool`;
            `E:A->A->bool`;`B:A`;
            `leq:A`;`((MAX i j + 1) |-> (c:A)) (vv:num->A)`] BVALF_IMP) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    ASM_REWRITE_TAC[] THEN DISCH_TAC THEN
    MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`zwf:A`;`zwx:A`;
                  `bvalf D (E:A->A->bool) B leq
                   (((MAX i j + 1) |-> (c:A)) (vv:num->A))
             (((MAX i j + 1) %% i) --> ((MAX i j + 1) %% j))`;
      `ii:A`] EBIMP_UNIQUE) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  (* reduce to ESUBVAL_EQ_SUBSETVAL with candidate = the LHS bvalf *)
  CONV_TAC SYM_CONV THEN
  MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`xx:A`;`tt:A`;
    `zr:A`;
    `bvalf D (E:A->A->bool) B leq vv
     (!! (MAX i j + 1) (((MAX i j + 1) %% i) --> ((MAX i j + 1) %% j)))`]
    ESUBVAL_EQ_SUBSETVAL) THEN
  ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
   [(* lower-bound clause: candidate <= each combiner *)
    MAP_EVERY X_GEN_TAC [`w:A`;`zwf:A`;`zwx:A`;`ii:A`] THEN STRIP_TAC THEN
    SUBGOAL_THEN
      `bvalf D (E:A->A->bool) B leq (((MAX i j + 1) |-> (w:A)) (vv:num->A))
             (((MAX i j + 1) %% i) --> ((MAX i j + 1) %% j)) = ii`
    ASSUME_TAC THENL
     [USE_THEN "body"
      (fun th -> MATCH_MP_TAC(SPECL [`w:A`;`zwf:A`;`zwx:A`;`ii:A`] th)) THEN
      ASM_REWRITE_TAC[]; ALL_TAC] THEN
    MP_TAC(ISPECL
           [`MAX i j + 1`;`((MAX i j + 1) %% i) --> ((MAX i j + 1) %% j)`;
            `D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`vv:num->A`;`w:A`]
             BVALF_ALL_LB) THEN
    ASM_REWRITE_TAC[];
    (* greatest clause: any common lower bound <= candidate *)
    X_GEN_TAC `lb:A` THEN
    DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC (CONJUNCTS_THEN2 ASSUME_TAC
      (LABEL_TAC "lbh"))) THEN
    MATCH_MP_TAC(ISPECL
                 [`MAX i j + 1`;
                  `((MAX i j + 1) %% i) --> ((MAX i j + 1) %% j)`;
                  `D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`vv:num->A`;`lb:A`]
                   BVALF_ALL_GLB) THEN
    ASM_REWRITE_TAC[] THEN
    X_GEN_TAC `c:A` THEN STRIP_TAC THEN
    MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`c:A`;`tt:A`]
      EBV_IN_VAL_EXISTS) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(X_CHOOSE_THEN `zwf:A` STRIP_ASSUME_TAC) THEN
    MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`c:A`;`xx:A`]
      EBV_IN_VAL_EXISTS) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(X_CHOOSE_THEN `zwx:A` STRIP_ASSUME_TAC) THEN
    MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`zwf:A`;`zwx:A`]
      EBIMP_EXISTS) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(X_CHOOSE_TAC `ii:A`) THEN
    SUBGOAL_THEN `(ii:A) IN D /\ (E:A->A->bool) ii B` STRIP_ASSUME_TAC THENL
     [ASM_MESON_TAC[EBIMP_IN]; ALL_TAC] THEN
    SUBGOAL_THEN
      `bvalf D (E:A->A->bool) B leq (((MAX i j + 1) |-> (c:A)) (vv:num->A))
             (((MAX i j + 1) %% i) --> ((MAX i j + 1) %% j)) = ii`
    ASSUME_TAC THENL
     [USE_THEN "body"
      (fun th -> MATCH_MP_TAC(SPECL [`c:A`;`zwf:A`;`zwx:A`;`ii:A`] th)) THEN
      ASM_REWRITE_TAC[]; ALL_TAC] THEN
    ASM_REWRITE_TAC[] THEN
    USE_THEN "lbh"
      (fun th -> MATCH_MP_TAC(SPECL [`c:A`;`zwf:A`;`zwx:A`;`ii:A`] th)) THEN
      ASM_REWRITE_TAC[]]);;

(* ============================================================================
   (A3) lemma 2 -- BVALF_POW_FORM_TOP :  [[ pow_form 2 0 ]]_v = top
   when  v 0 = x  (the set being power'd)  and  v 2 = pn  (a power NAME of x,
   given via the EBV_IN_POW clause bundle, as built by POWNAME_OF).
   pow_form 2 0 = !! 3 ((3%%2) <-> subset_form 3 0); peel !!3 -> a, IFF_TOP ->
   [[a IN pn]] = [[subset_form 3 0]],
   both = esubval x a (EBV_IN_POW / SUBSETFORM_VAL).
   ========================================================================= *)

let BVALF_POW_FORM_TOP = prove
 (`!D (E:A->A->bool) B leq v x FS pn.
      model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
      valuation D v /\ (!n. bname D E B (v n)) /\
      v 0 = x /\ v 2 = pn /\
      x IN D /\ bname D E B x /\
      FS IN D /\ pn IN D /\ eisfun D E pn /\
      (!f. f IN D /\ E f FS ==> bname D E B f) /\
      (!f q. f IN D /\ E f FS /\ esubval D E B leq x f q ==>
       eapply D E pn f q) /\
      (!f. f IN D ==> (eindom D E pn f <=> E f FS)) /\
      (!f. f IN D /\ bname D E B f /\ eisfun D E f /\
           (!w. w IN D ==> (eindom D E f w <=> eindom D E x w)) ==> E f FS)
      ==> etop D E B leq (bvalf D E B leq v (pow_form 2 0))`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `eporder D (E:A->A->bool) B leq` ASSUME_TAC THENL
   [ASM_MESON_TAC[ECBA_IMP_BALG; EBALG_IMP_PORDER]; ALL_TAC] THEN
  REWRITE_TAC[pow_form; ARITH_RULE `MAX 2 0 + 1 = 3`] THEN
  MP_TAC(ISPECL [`3`; `(3 %% 2) <-> subset_form 3 0`;
    `D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`v:num->A`] BVALF_ALL_TOP) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  X_GEN_TAC `a:A` THEN STRIP_TAC THEN
  SUBGOAL_THEN `valuation D ((3 |-> (a:A)) (v:num->A)) /\
                (!n. bname D E B (((3 |-> (a:A)) (v:num->A)) n))`
  STRIP_ASSUME_TAC THENL
   [CONJ_TAC THENL
     [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[];
      MATCH_MP_TAC BNAMEVAL_VALMOD THEN ASM_REWRITE_TAC[]]; ALL_TAC] THEN
  ABBREV_TAC `vv = (3 |-> (a:A)) (v:num->A)` THEN
  SUBGOAL_THEN `(vv:num->A) 0 = x /\ (vv:num->A) 2 = pn /\ (vv:num->A) 3 = a`
  STRIP_ASSUME_TAC THENL
   [EXPAND_TAC "vv" THEN
    ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER; ARITH_EQ]; ALL_TAC] THEN
  MP_TAC(ISPECL [`3 %% 2`; `subset_form 3 0`;
    `D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`vv:num->A`] BVALF_IFF_TOP) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`x:A`;`a:A`]
    ESUBVAL_EXISTS) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_TAC `ztx:A`) THEN
  SUBGOAL_THEN `(ztx:A) IN D /\ (E:A->A->bool) ztx B` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[ESUBVAL_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `bvalf D (E:A->A->bool) B leq vv (subset_form 3 0) = ztx`
  SUBST1_TAC THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`vv:num->A`;
      `3`;`0`;`a:A`;`x:A`;`ztx:A`] SUBSETFORM_VAL) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  ABBREV_TAC `zin = bvalf D (E:A->A->bool) B leq (vv:num->A) (3 %% 2)` THEN
  SUBGOAL_THEN `ebv_in D (E:A->A->bool) B leq a pn zin` ASSUME_TAC THENL
   [EXPAND_TAC "zin" THEN
    MP_TAC(ISPECL
           [`3`;`2`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`vv:num->A`]
           BVALF_MEM) THEN ASM_SIMP_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(zin:A) IN D` ASSUME_TAC THENL
   [EXPAND_TAC "zin" THEN
    MP_TAC(ISPECL
           [`3 %% 2`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`vv:num->A`]
           BVALF_SPEC) THEN ASM_SIMP_TAC[]; ALL_TAC] THEN
  MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`x:A`;`FS:A`;
    `a:A`;`pn:A`;`zin:A`;`ztx:A`] EBV_IN_POW) THEN
  ASM_REWRITE_TAC[]);;

(* ============================================================================
   (A3) lemma 3 -- POWNAME_OF : the power NAME of x exists with the full
   EBV_IN_POW clause bundle.  Extracted from BVALF_POWERSET's
   FS := x's-own-bname-stage (yax) construction, with the
   peeled xx renamed to x and an existential conclusion.  CH_CORE
     calls this once
   at x := omc to obtain pw, then feeds pw to BVALF_POW_FORM_TOP (A3) and (B).
   ========================================================================= *)

let POWNAME_OF = prove
 (`!D (E:A->A->bool) B leq x.
      model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
      x IN D /\ bname D E B x
      ==> ?pn FS. FS IN D /\ pn IN D /\ bname D E B pn /\ eisfun D E pn /\
                  (!f. f IN D /\ E f FS ==> bname D E B f) /\
                  (!f q. f IN D /\ E f FS /\ esubval D E B leq x f q
                         ==> eapply D E pn f q) /\
                  (!f. f IN D ==> (eindom D E pn f <=> E f FS)) /\
                  (!f. f IN D /\ bname D E B f /\ eisfun D E f /\
                       (!w. w IN D ==> (eindom D E f w <=> eindom D E x w))
                       ==> E f FS)`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `eporder D (E:A->A->bool) B leq` ASSUME_TAC THENL
   [ASM_MESON_TAC[ECBA_IMP_BALG; EBALG_IMP_PORDER]; ALL_TAC] THEN
  FIRST_ASSUM(X_CHOOSE_THEN `ax:A` (X_CHOOSE_THEN `yax:A` STRIP_ASSUME_TAC) o
    REWRITE_RULE[bname]) THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`ax:A`;`yax:A`]
         EBNSTAGE_CHAR) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `W:A` (CONJUNCTS_THEN2 ASSUME_TAC
    (CONJUNCTS_THEN2 (LABEL_TAC "Wch") ASSUME_TAC))) THEN
  SUBGOAL_THEN `!f:A. f IN D /\ E f yax ==> bname D E B f`
    (LABEL_TAC "cl1") THENL
   [REPEAT STRIP_TAC THEN
    MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`ax:A`;`yax:A`;`f:A`]
      BNAME_STAGE) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `ebnmem D (E:A->A->bool) B W x` ASSUME_TAC THENL
   [UNDISCH_TAC `ebnfuns D (E:A->A->bool) B W yax` THEN
    REWRITE_TAC[ebnfuns] THEN
    DISCH_THEN(MP_TAC o SPEC `x:A` o CONJUNCT2) THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `?crx. crx IN D /\ ecross D (E:A->A->bool) W B crx /\
                      esubset D E x crx`
  STRIP_ASSUME_TAC THENL
   [UNDISCH_TAC `ebnmem D (E:A->A->bool) B W x` THEN REWRITE_TAC[ebnmem] THEN
    MESON_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `!u:A. u IN D /\ eindom D (E:A->A->bool) x u ==> E u W`
  (LABEL_TAC "domxxW") THENL
   [X_GEN_TAC `u:A` THEN STRIP_TAC THEN
    UNDISCH_TAC `eindom D (E:A->A->bool) x u` THEN
    REWRITE_TAC[eindom; eapply] THEN
    DISCH_THEN(X_CHOOSE_THEN `vu:A` (CONJUNCTS_THEN2 ASSUME_TAC
      (X_CHOOSE_THEN `zu:A` STRIP_ASSUME_TAC))) THEN
    SUBGOAL_THEN `(zu:A) IN D` ASSUME_TAC THENL
     [ASM_MESON_TAC[EOPAIR_IN]; ALL_TAC] THEN
    SUBGOAL_THEN `(E:A->A->bool) zu crx` ASSUME_TAC THENL
     [UNDISCH_TAC `esubset D (E:A->A->bool) x crx` THEN
      REWRITE_TAC[esubset] THEN
      DISCH_THEN(MP_TAC o SPEC `zu:A`) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`W:A`;`B:A`;`crx:A`;`zu:A`]
      ECROSS_MEMBER) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    ASM_REWRITE_TAC[] THEN
    DISCH_THEN(X_CHOOSE_THEN `u2:A`
               (X_CHOOSE_THEN `w2:A` STRIP_ASSUME_TAC)) THEN
    SUBGOAL_THEN `(u:A) = u2` ASSUME_TAC THENL
     [MP_TAC(ISPECL
             [`D:A->bool`;`E:A->A->bool`;`u:A`;`vu:A`;`u2:A`;`w2:A`;`zu:A`]
             EOPAIR_INJ) THEN ASM_REWRITE_TAC[] THEN SIMP_TAC[]; ALL_TAC] THEN
    ASM_MESON_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN
    `!f:A. f IN D /\ bname D E B f /\ eisfun D E f /\
           (!w. w IN D ==> (eindom D E f w <=> eindom D E x w)) ==> E f yax`
  (LABEL_TAC "cl4") THENL
   [X_GEN_TAC `f:A` THEN
    INTRO_TAC "fD bnf funf domeq" THEN
    SUBGOAL_THEN `ebnmem D (E:A->A->bool) B W f` MP_TAC THENL
     [REWRITE_TAC[ebnmem] THEN ASM_REWRITE_TAC[] THEN
      MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`W:A`;`B:A`]
             ECROSS_EXISTS) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(X_CHOOSE_THEN `crf:A` ASSUME_TAC) THEN
      SUBGOAL_THEN `(crf:A) IN D` ASSUME_TAC THENL
       [ASM_MESON_TAC[ecross]; ALL_TAC] THEN
      EXISTS_TAC `crf:A` THEN ASM_REWRITE_TAC[] THEN
      REWRITE_TAC[esubset] THEN X_GEN_TAC `z:A` THEN STRIP_TAC THEN
      MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`f:A`;`z:A`]
        BNAME_MEM_PAIR) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(X_CHOOSE_THEN `w:A`
                 (X_CHOOSE_THEN `q:A` STRIP_ASSUME_TAC)) THEN
      SUBGOAL_THEN `eindom D (E:A->A->bool) f w` ASSUME_TAC THENL
       [REWRITE_TAC[eindom; eapply] THEN EXISTS_TAC `q:A` THEN
        ASM_REWRITE_TAC[] THEN EXISTS_TAC `z:A` THEN ASM_REWRITE_TAC[];
        ALL_TAC] THEN
      SUBGOAL_THEN `eindom D (E:A->A->bool) x w` ASSUME_TAC THENL
       [REMOVE_THEN "domeq" (MP_TAC o SPEC `w:A`) THEN ASM_REWRITE_TAC[];
        ALL_TAC] THEN
      SUBGOAL_THEN `(E:A->A->bool) w W` ASSUME_TAC THENL
       [USE_THEN "domxxW" MATCH_MP_TAC THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
      MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`W:A`;`B:A`;`crf:A`;`z:A`]
        ECROSS_MEMBER) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
      MAP_EVERY EXISTS_TAC [`w:A`;`q:A`] THEN ASM_REWRITE_TAC[];
      DISCH_TAC THEN
      UNDISCH_TAC `ebnfuns D (E:A->A->bool) B W yax` THEN
      REWRITE_TAC[ebnfuns] THEN
      DISCH_THEN(MP_TAC o SPEC `f:A` o CONJUNCT2) THEN ASM_REWRITE_TAC[]];
    ALL_TAC] THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`x:A`;`yax:A`]
    EPOWERNAME_EXISTS) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `pn:A` STRIP_ASSUME_TAC) THEN
  SUBGOAL_THEN `bname D (E:A->A->bool) B pn` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`x:A`;`yax:A`;
                  `ax:A`;`yax:A`;`pn:A`] EPOWERNAME_BNAME) THEN
    ASM_REWRITE_TAC[] THEN MESON_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `!f:A. f IN D ==> (eindom D (E:A->A->bool) pn f <=> E f yax)`
  (LABEL_TAC "cl3") THENL
   [UNDISCH_TAC `edomain D (E:A->A->bool) pn yax` THEN
    REWRITE_TAC[edomain] THEN
    MESON_TAC[]; ALL_TAC] THEN
  MAP_EVERY EXISTS_TAC [`pn:A`;`yax:A`] THEN
  ASM_REWRITE_TAC[]);;
(* ************************************************************************* *)
(* (A1)  [[ omega_form 0 ]]_{0:=om^} = top : om^ is the Boolean omega.       *)
(*                                                                           *)
(* Ladder for the CH-core antecedent:                                        *)
(*   EBV_EQ_GLB        slot-free greatest-lower-bound extensionality engine  *)
(*   EMPTY_LE_EQ (L1)  [[a empty]] <= [[a = 0^]]                             *)
(*   INDUCTIVE_LE_EMPTYMEM (L2)  base: [[inductive]] <= [[0^ in ss]]         *)
(*   SUCFORM_LE_EQ (L3)  [[suc_form]] <= [[s = (suc c)^]]                    *)
(*   INDUCTIVE_LE_SUCMEM (L4)  step: [[inductive]] <= [[(suc c)^ in ss]]     *)
(*   nmemss_form/HOLDS_NMEMSS_FORM/NMEMSS_INDUCT (L5)  internal om-induction *)
(*   INDUCTIVE_FORM_CHECK_TOP (A1a)  [[inductive_form 0]]_{0:=om^} = top     *)
(*   BVALF_OMEGA_LEAST_IND (A1b/L6)  om^ a Boolean subset of every inductive *)
(*   BVALF_OMEGA_FORM_CHECK_TOP (A1)  the two halves combined                *)
(* ************************************************************************* *)

(* ############################################################################
   EBV_EQ_GLB : membership-level, SLOT-FREE greatest-lower-bound form of
   extensionality.  If w0 is below every membership-implication
     [[x in u]] => [[x in v]]   (hu)   and   [[y in v]] => [[y in u]]   (hv)
   then w0 <= [[u = v]].  This is the value-level engine that
     BVALF_EXTENSIONALITY
   packages for the fixed slots 0,1,2; here it is abstracted away from slots so
   it can consume an empty-/successor-form bound directly.

   Proof mirrors BVALF_EXTENSIONALITY's stage setup (BNAME_DIRECTED +
     EBVATT_EXISTS
   + EOPAIR + EBVATT_VAL + EBV_EQ_AT_STAGE + EBV_EQ_UNIQUE),
   then EBV_EQ_GLB_STAGE;
   the per-element obligations are discharged by EBV_IN_VAL_EXISTS (compute
   [[x in u]]) + EBIMP_EXISTS + the clean hypothesis + EBV_IN_MEMBER
   (stored value qx <= [[x in u]]) + EBIMP_ANT + EPORDER_TRANS.
   ######################################################################### *)

let EBV_EQ_GLB = prove
 (`!D (E:A->A->bool) B leq u v z w0.
      model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
      u IN D /\ v IN D /\ bname D E B u /\ bname D E B v /\
      ebv_eq D E B leq u v z /\ z IN D /\ w0 IN D /\ E w0 B /\
      (!x inx0 inx1 c.
          bname D E B x /\ x IN D /\ inx0 IN D /\ inx1 IN D /\ c IN D /\
          ebv_in D E B leq x u inx0 /\ ebv_in D E B leq x v inx1 /\
          ebimp D E B leq inx0 inx1 c
          ==> erel D E leq w0 c) /\
      (!y iny0 iny1 c.
          bname D E B y /\ y IN D /\ iny0 IN D /\ iny1 IN D /\ c IN D /\
          ebv_in D E B leq y v iny0 /\ ebv_in D E B leq y u iny1 /\
          ebimp D E B leq iny0 iny1 c
          ==> erel D E leq w0 c)
      ==> erel D E leq w0 z`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "zf cba BD leqD uD vD bnu bnv beqz zD w0D w0B hu hv" THEN
  SUBGOAL_THEN `ebalg D (E:A->A->bool) B leq /\ eporder D E B leq`
    STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[ECBA_IMP_BALG; EBALG_IMP_PORDER]; ALL_TAC] THEN
  (* --- common stage for u,v --- *)
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`u:A`;`v:A`]
         BNAME_DIRECTED) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `ao:A` (X_CHOOSE_THEN `w:A` STRIP_ASSUME_TAC)) THEN
  SUBGOAL_THEN `!zt. zt IN D /\ E zt w ==> bname D (E:A->A->bool) B zt`
    ASSUME_TAC THENL
   [REPEAT STRIP_TAC THEN
    MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;
                         `ao:A`;`w:A`;`zt:A`] BNAME_STAGE) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`w:A`]
         EBVATT_EXISTS) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[] THEN EXISTS_TAC `u:A` THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `sIN:A` (X_CHOOSE_THEN `sEQ:A` ASSUME_TAC)) THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`u:A`;`v:A`] EOPAIR_EXISTS) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `pruv:A`) THEN
  MP_TAC(ISPECL
         [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`w:A`;`sIN:A`;`sEQ:A`;
          `u:A`;`v:A`;`pruv:A`] EBVATT_VAL) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(CONJUNCTS_THEN2 (K ALL_TAC)
    (X_CHOOSE_THEN `zc:A` STRIP_ASSUME_TAC)) THEN
  (* z = zc *)
  SUBGOAL_THEN `ebv_eq D (E:A->A->bool) B leq u v zc` ASSUME_TAC THENL
   [MP_TAC(ISPECL
           [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`ao:A`;`w:A`;`sIN:A`;
            `sEQ:A`;`u:A`;`v:A`;`zc:A`] EBV_EQ_AT_STAGE) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `z:A = zc` SUBST_ALL_TAC THENL
   [MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`u:A`;`v:A`;`z:A`;
      `zc:A`] EBV_EQ_UNIQUE) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* --- EBV_EQ_GLB_STAGE --- *)
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`ao:A`;`w:A`;`sIN:A`;
    `sEQ:A`;`u:A`;`v:A`;`zc:A`;`w0:A`] EBV_EQ_GLB_STAGE) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
     [ (* ===== hu : x in dom u ===== *)
      MAP_EVERY X_GEN_TAC [`x:A`;`qx:A`;`exv:A`;`c:A`] THEN STRIP_TAC THEN
      SUBGOAL_THEN `(E:A->A->bool) x w` ASSUME_TAC THENL
       [MATCH_MP_TAC(ISPECL
                     [`D:A->bool`;`E:A->A->bool`;`B:A`;`ao:A`;`w:A`;`u:A`;
                      `x:A`;`qx:A`] STAGE_DOM_CLOSED) THEN ASM_REWRITE_TAC[];
      ALL_TAC] THEN
      SUBGOAL_THEN `bname D (E:A->A->bool) B x` ASSUME_TAC THENL
       [FIRST_ASSUM MATCH_MP_TAC THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
      (* E exv B : exv = [[x in v]] stored by the stage obligation *)
      SUBGOAL_THEN `(E:A->A->bool) exv B` ASSUME_TAC THENL
       [MP_TAC(ISPECL
               [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`x:A`;`v:A`;`exv:A`]
               EBV_IN_IN_B) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
      (* E c B : c = ebimp qx exv c stored by the stage obligation *)
      SUBGOAL_THEN `(E:A->A->bool) c B` ASSUME_TAC THENL
       [ASM_MESON_TAC[EBIMP_IN]; ALL_TAC] THEN
      (* inx0 = [[x in u]] *)
      MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`x:A`;`u:A`]
        EBV_IN_VAL_EXISTS) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(X_CHOOSE_THEN `inx0:A` STRIP_ASSUME_TAC) THEN
      (* impval = ebimp inx0 exv *)
      MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`inx0:A`;`exv:A`]
        EBIMP_EXISTS) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(X_CHOOSE_TAC `impval:A`) THEN
      SUBGOAL_THEN `(impval:A) IN D /\ (E:A->A->bool) impval B`
        STRIP_ASSUME_TAC THENL
        [ASM_MESON_TAC[EBIMP_IN]; ALL_TAC] THEN
      (* clean hyp hu : erel w0 impval *)
      SUBGOAL_THEN `erel D (E:A->A->bool) leq w0 impval` ASSUME_TAC THENL
       [USE_THEN "hu" (fun th -> MATCH_MP_TAC(ISPECL
          [`x:A`;`inx0:A`;`exv:A`;`impval:A`] th)) THEN ASM_REWRITE_TAC[];
        ALL_TAC] THEN
      (* erel qx inx0 : stored value <= computed membership (EBV_IN_MEMBER) *)
      MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`x:A`;`u:A`]
             EOPAIR_EXISTS) THEN
      ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `prx0:A`) THEN
      MP_TAC(ISPECL
             [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`w:A`;`sIN:A`;`sEQ:A`;
              `x:A`;`u:A`;`prx0:A`] EBVATT_VAL) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(CONJUNCTS_THEN2
        (X_CHOOSE_THEN `s0:A` STRIP_ASSUME_TAC) (K ALL_TAC)) THEN
      SUBGOAL_THEN `ebv_in D (E:A->A->bool) B leq x u s0` ASSUME_TAC THENL
       [MP_TAC(ISPECL
               [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`ao:A`;`w:A`;`sIN:A`;
                `sEQ:A`;`x:A`;`u:A`;`s0:A`] EBV_IN_AT_STAGE) THEN
        ASM_REWRITE_TAC[]; ALL_TAC] THEN
      SUBGOAL_THEN `s0:A = inx0` SUBST_ALL_TAC THENL
       [MP_TAC(ISPECL
               [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`x:A`;`u:A`;`s0:A`;
                `inx0:A`] EBV_IN_UNIQUE) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
      SUBGOAL_THEN `erel D (E:A->A->bool) leq qx inx0` ASSUME_TAC THENL
       [MP_TAC(ISPECL
               [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`ao:A`;`w:A`;`sIN:A`;
                `sEQ:A`;`x:A`;`u:A`;`qx:A`;`inx0:A`] EBV_IN_MEMBER) THEN
        ASM_REWRITE_TAC[]; ALL_TAC] THEN
      SUBGOAL_THEN `(E:A->A->bool) qx B` ASSUME_TAC THENL
       [MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`u:A`;`x:A`;`qx:A`]
          BNAME_APPLY_IN_B) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
      (* EBIMP_ANT : erel impval c  (qx <= inx0 shrinks the implication) *)
      SUBGOAL_THEN `erel D (E:A->A->bool) leq impval c` ASSUME_TAC THENL
       [MP_TAC(ISPECL
               [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`qx:A`;`inx0:A`;
                `exv:A`;`c:A`;`impval:A`] EBIMP_ANT) THEN ASM_REWRITE_TAC[];
        ALL_TAC] THEN
      MP_TAC(ISPECL
             [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`w0:A`;`impval:A`;
              `c:A`] EPORDER_TRANS) THEN ASM_REWRITE_TAC[];
      (* ===== hv : y in dom v (mirror) ===== *)
      MAP_EVERY X_GEN_TAC [`y:A`;`qy:A`;`eyu:A`;`c:A`] THEN STRIP_TAC THEN
      SUBGOAL_THEN `(E:A->A->bool) y w` ASSUME_TAC THENL
       [MATCH_MP_TAC(ISPECL
                     [`D:A->bool`;`E:A->A->bool`;`B:A`;`ao:A`;`w:A`;`v:A`;
                      `y:A`;`qy:A`] STAGE_DOM_CLOSED) THEN ASM_REWRITE_TAC[];
             ALL_TAC] THEN
      SUBGOAL_THEN `bname D (E:A->A->bool) B y` ASSUME_TAC THENL
       [FIRST_ASSUM MATCH_MP_TAC THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
      (* E eyu B : eyu = [[y in u]] stored by the stage obligation *)
      SUBGOAL_THEN `(E:A->A->bool) eyu B` ASSUME_TAC THENL
       [MP_TAC(ISPECL
               [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`y:A`;`u:A`;`eyu:A`]
               EBV_IN_IN_B) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
      (* E c B : c = ebimp qy eyu c stored by the stage obligation *)
      SUBGOAL_THEN `(E:A->A->bool) c B` ASSUME_TAC THENL
       [ASM_MESON_TAC[EBIMP_IN]; ALL_TAC] THEN
      (* iny0 = [[y in v]] *)
      MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`y:A`;`v:A`]
        EBV_IN_VAL_EXISTS) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(X_CHOOSE_THEN `iny0:A` STRIP_ASSUME_TAC) THEN
      (* impvy = ebimp iny0 eyu *)
      MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`iny0:A`;`eyu:A`]
        EBIMP_EXISTS) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(X_CHOOSE_TAC `impvy:A`) THEN
      SUBGOAL_THEN `(impvy:A) IN D /\ (E:A->A->bool) impvy B`
        STRIP_ASSUME_TAC THENL
        [ASM_MESON_TAC[EBIMP_IN]; ALL_TAC] THEN
      SUBGOAL_THEN `erel D (E:A->A->bool) leq w0 impvy` ASSUME_TAC THENL
       [USE_THEN "hv" (fun th -> MATCH_MP_TAC(ISPECL
          [`y:A`;`iny0:A`;`eyu:A`;`impvy:A`] th)) THEN ASM_REWRITE_TAC[];
        ALL_TAC] THEN
      MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`y:A`;`v:A`]
             EOPAIR_EXISTS) THEN
      ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `pry0:A`) THEN
      MP_TAC(ISPECL
             [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`w:A`;`sIN:A`;`sEQ:A`;
              `y:A`;`v:A`;`pry0:A`] EBVATT_VAL) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(CONJUNCTS_THEN2
        (X_CHOOSE_THEN `t0:A` STRIP_ASSUME_TAC) (K ALL_TAC)) THEN
      SUBGOAL_THEN `ebv_in D (E:A->A->bool) B leq y v t0` ASSUME_TAC THENL
       [MP_TAC(ISPECL
               [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`ao:A`;`w:A`;`sIN:A`;
                `sEQ:A`;`y:A`;`v:A`;`t0:A`] EBV_IN_AT_STAGE) THEN
        ASM_REWRITE_TAC[]; ALL_TAC] THEN
      SUBGOAL_THEN `t0:A = iny0` SUBST_ALL_TAC THENL
       [MP_TAC(ISPECL
               [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`y:A`;`v:A`;`t0:A`;
                `iny0:A`] EBV_IN_UNIQUE) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
      SUBGOAL_THEN `erel D (E:A->A->bool) leq qy iny0` ASSUME_TAC THENL
       [MP_TAC(ISPECL
               [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`ao:A`;`w:A`;`sIN:A`;
                `sEQ:A`;`y:A`;`v:A`;`qy:A`;`iny0:A`] EBV_IN_MEMBER) THEN
        ASM_REWRITE_TAC[]; ALL_TAC] THEN
      SUBGOAL_THEN `(E:A->A->bool) qy B` ASSUME_TAC THENL
       [MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`v:A`;`y:A`;`qy:A`]
          BNAME_APPLY_IN_B) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
      SUBGOAL_THEN `erel D (E:A->A->bool) leq impvy c` ASSUME_TAC THENL
       [MP_TAC(ISPECL
               [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`qy:A`;`iny0:A`;
                `eyu:A`;`c:A`;`impvy:A`] EBIMP_ANT) THEN ASM_REWRITE_TAC[];
        ALL_TAC] THEN
      MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`w0:A`;`impvy:A`;
        `c:A`] EPORDER_TRANS) THEN ASM_REWRITE_TAC[]];
    DISCH_THEN ACCEPT_TAC]);;

(* ############################################################################
   L1  EMPTY_LE_EQ :  [[ a empty ]]_v  <=  [[ a = vemp ]].
   i.e. if a is (Boolean-)empty then a equals the canonical empty name vemp.
   Via EBV_EQ_GLB with w0 := [[empty_form i]]_v (a = v i):
     hu : for every x,  w0 <= ([[x in a]] => [[x in vemp]]).
          [[x in vemp]] = bot (ECHECK_IN_EMPTY),
          so the implication is compl([[x in a]]);
          w0 = [[!!(i+1) Not((i+1)%%i)]] <= [[Not((i+1)%%i)]]_{(i+1|->x)v} =
            compl([[x in a]]).
     hv : for every y,  w0 <= ([[y in vemp]] => [[y in a]]) = top  (bot => _).
   ######################################################################### *)

let EMPTY_LE_EQ = prove
 (`!D (E:A->A->bool) B leq onebee emp vemp v i a zeq.
      model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
      onebee IN D /\ E onebee B /\
      echeck D E onebee emp vemp /\ (!c. c IN D ==> ~(E c emp)) /\
      valuation D v /\ (!j. bname D E B (v j)) /\
      v i = a /\ a IN D /\ bname D E B a /\
      zeq IN D /\ ebv_eq D E B leq a vemp zeq
      ==> erel D E leq (bvalf D E B leq v (empty_form i)) zeq`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `ebalg D (E:A->A->bool) B leq /\ eporder D E B leq`
    STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[ECBA_IMP_BALG; EBALG_IMP_PORDER]; ALL_TAC] THEN
  (* vemp is a bname in D *)
  SUBGOAL_THEN `emp IN D /\ (vemp:A) IN D` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[ECHECK_IMP]; ALL_TAC] THEN
  SUBGOAL_THEN `bname D (E:A->A->bool) B vemp` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`onebee:A`;`B:A`;`emp:A`;`vemp:A`]
                 ECHECK_IS_BNAME) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* field facts for w0 = [[empty_form i]] *)
  SUBGOAL_THEN `(bvalf D (E:A->A->bool) B leq v (empty_form i)) IN D /\
                (E:A->A->bool) (bvalf D E B leq v (empty_form i)) B`
  STRIP_ASSUME_TAC THENL
   [CONJ_TAC THENL
     [MP_TAC(ISPECL
             [`empty_form i`;`D:A->bool`;`E:A->A->bool`;`B:A`;
              `leq:A`;`v:num->A`]
             BVALF_SPEC) THEN ASM_SIMP_TAC[];
      MP_TAC(ISPECL
             [`empty_form i`;`D:A->bool`;`E:A->A->bool`;`B:A`;
              `leq:A`;`v:num->A`]
             BVALF_IN_B) THEN ASM_SIMP_TAC[]]; ALL_TAC] THEN
  (* MAIN : EBV_EQ_GLB *)
  MP_TAC(ISPECL
         [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`a:A`;`vemp:A`;`zeq:A`;
          `bvalf D (E:A->A->bool) B leq v (empty_form i)`] EBV_EQ_GLB) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
     [ (* ===== hu ===== *)
      MAP_EVERY X_GEN_TAC [`x:A`;`inx0:A`;`inx1:A`;`c:A`] THEN STRIP_TAC THEN
      (* inx1 = [[x in vemp]] = bot *)
      SUBGOAL_THEN `ebot D (E:A->A->bool) B leq inx1` ASSUME_TAC THENL
       [MP_TAC(ISPECL
               [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`onebee:A`;`emp:A`;
                `vemp:A`;`x:A`;`inx1:A`] ECHECK_IN_EMPTY) THEN
             ASM_REWRITE_TAC[]; ALL_TAC] THEN
      (* E inx0 B *)
      SUBGOAL_THEN `(E:A->A->bool) inx0 B` ASSUME_TAC THENL
       [MP_TAC(ISPECL
               [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`x:A`;`a:A`;`inx0:A`]
               EBV_IN_IN_B) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
      (* ecompl inx0 c : c = (inx0 => bot) = compl inx0 *)
      SUBGOAL_THEN `ecompl D (E:A->A->bool) B leq inx0 c` ASSUME_TAC THENL
       [UNDISCH_TAC `ebimp D (E:A->A->bool) B leq inx0 inx1 c` THEN
        REWRITE_TAC[ebimp] THEN
        DISCH_THEN(X_CHOOSE_THEN `c':A` STRIP_ASSUME_TAC) THEN
        SUBGOAL_THEN `(c':A) IN D /\ (E:A->A->bool) c' B`
          STRIP_ASSUME_TAC THENL
          [ASM_MESON_TAC[ECOMPL_IN]; ALL_TAC] THEN
        SUBGOAL_THEN `ejoin D (E:A->A->bool) B leq inx1 c' c'` ASSUME_TAC THENL
         [MATCH_MP_TAC EJOIN_BOT THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
        SUBGOAL_THEN `ejoin D (E:A->A->bool) B leq c' inx1 c'` ASSUME_TAC THENL
         [MATCH_MP_TAC EJOIN_SYM THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
        SUBGOAL_THEN `c:A = c'` SUBST_ALL_TAC THENL
         [MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`c':A`;`inx1:A`;
                  `c:A`;`c':A`] EJOIN_UNIQUE) THEN ASM_REWRITE_TAC[];
               ALL_TAC] THEN
        ASM_REWRITE_TAC[]; ALL_TAC] THEN
      (* c = [[Not((i+1)%%i)]]_{(i+1|->x)v} *)
      SUBGOAL_THEN
        `bvalf D (E:A->A->bool) B leq (((i + 1) |-> (x:A)) v)
         (Not((i+1) %% i)) = c`
      (SUBST1_TAC o SYM) THENL
       [SUBGOAL_THEN `valuation D (((i + 1) |-> (x:A)) v) /\
                      (!j. bname D (E:A->A->bool) B
                       ((((i + 1) |-> (x:A)) v) j))`
        STRIP_ASSUME_TAC THENL
         [CONJ_TAC THENL
           [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[];
            MATCH_MP_TAC BNAMEVAL_VALMOD THEN ASM_REWRITE_TAC[]]; ALL_TAC] THEN
        (* field fact: the membership value is in D (needed by *)
        (* EBV_IN_UNIQUE) *)
        SUBGOAL_THEN
          `(bvalf D (E:A->A->bool) B leq (((i + 1) |-> (x:A)) v)
            ((i+1) %% i)) IN D`
        ASSUME_TAC THENL
         [MP_TAC(ISPECL [`(i+1) %% i`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
            `((i + 1) |-> (x:A)) v`] BVALF_SPEC) THEN ASM_SIMP_TAC[];
           ALL_TAC] THEN
        SUBGOAL_THEN `ebv_in D (E:A->A->bool) B leq x a
                        (bvalf D E B leq (((i + 1) |-> (x:A)) v) ((i+1) %% i))`
          ASSUME_TAC THENL
          [MP_TAC(ISPECL
                  [`i + 1`;`i:num`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
                   `((i + 1) |-> (x:A)) v`] BVALF_MEM) THEN
          ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
          ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER; ARITH_RULE `~(i = i + 1)`];
          ALL_TAC] THEN
        (* keep the equation (ASSUME, not SUBST): BVALF_NOT below rewrites *)
        (* memf->inx0 *)
        SUBGOAL_THEN
          `bvalf D (E:A->A->bool) B leq (((i + 1) |-> (x:A)) v)
           ((i+1) %% i) = inx0`
        ASSUME_TAC THENL
         [MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`x:A`;`a:A`;
            `bvalf D (E:A->A->bool) B leq (((i + 1) |-> (x:A)) v)
             ((i+1) %% i)`;`inx0:A`]
            EBV_IN_UNIQUE) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
        (* ecompl inx0 [[Not]] via BVALF_NOT *)
        SUBGOAL_THEN `ecompl D (E:A->A->bool) B leq inx0
                        (bvalf D E B leq (((i + 1) |-> (x:A)) v)
                         (Not((i+1) %% i)))`
        ASSUME_TAC THENL
         [MP_TAC(ISPECL [`(i+1) %% i`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
            `((i + 1) |-> (x:A)) v`] BVALF_NOT) THEN ASM_REWRITE_TAC[];
                        ALL_TAC] THEN
        MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`inx0:A`;
          `bvalf D (E:A->A->bool) B leq (((i + 1) |-> (x:A)) v)
           (Not((i+1) %% i))`;`c:A`]
          ECOMPL_UNIQUE) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
      REWRITE_TAC[empty_form] THEN
      MATCH_MP_TAC(ISPECL
                   [`i + 1`;`Not((i+1) %% i)`;`D:A->bool`;`E:A->A->bool`;`B:A`;
                    `leq:A`;`v:num->A`;`x:A`] BVALF_ALL_LB) THEN
      ASM_REWRITE_TAC[];
      (* ===== hv ===== *)
      MAP_EVERY X_GEN_TAC [`y:A`;`iny0:A`;`iny1:A`;`c:A`] THEN STRIP_TAC THEN
      (* iny0 = [[y in vemp]] = bot *)
      SUBGOAL_THEN `ebot D (E:A->A->bool) B leq iny0` ASSUME_TAC THENL
       [MP_TAC(ISPECL
               [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`onebee:A`;`emp:A`;
                `vemp:A`;`y:A`;`iny0:A`] ECHECK_IN_EMPTY) THEN
                   ASM_REWRITE_TAC[]; ALL_TAC] THEN
      (* E iny0 B, E iny1 B *)
      SUBGOAL_THEN `(E:A->A->bool) iny0 B` ASSUME_TAC THENL
       [ASM_MESON_TAC[EBOT_IN]; ALL_TAC] THEN
      SUBGOAL_THEN `(E:A->A->bool) iny1 B` ASSUME_TAC THENL
       [MP_TAC(ISPECL
               [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`y:A`;`a:A`;`iny1:A`]
               EBV_IN_IN_B) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
      (* erel iny0 iny1 (bot <= anything) *)
      SUBGOAL_THEN `erel D (E:A->A->bool) leq iny0 iny1` ASSUME_TAC THENL
       [MATCH_MP_TAC(ISPECL
                     [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
                      `iny0:A`;`iny1:A`]
                     EBOT_LE) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
      (* etop c via EBIMP_TOP *)
      SUBGOAL_THEN `etop D (E:A->A->bool) B leq c` ASSUME_TAC THENL
       [MP_TAC(ISPECL
               [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`iny0:A`;
                `iny1:A`;`c:A`]
               EBIMP_TOP) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
      MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`c:A`;
        `bvalf D (E:A->A->bool) B leq v (empty_form i)`] ETOP_GE) THEN
      ASM_REWRITE_TAC[]];
    DISCH_THEN ACCEPT_TAC]);;

(* ############################################################################
   L2  INDUCTIVE_LE_EMPTYMEM :  [[ inductive_form i ]]_{i:=ss}  <=  [[
     vemp in ss ]].
   The base case of the omega-induction for (A1b): the inductive-set value
   lies below the membership value of the canonical empty name (= 0-check).

   c0 := [[inductive_form i]] = [[ (??- (i+1) i (empty_form(i+1))) && SUCC ]].
     c0 <= [[??- (i+1) i (empty_form(i+1))]]           (BVALF_AND_LE_L)
         = [[?? (i+1) ((i+1)%%i && empty_form(i+1))]]   (Existsmem_DEF)
         <= zin   iff for every bname x,
            [[x in ss]] MEET [[x empty]]  <=  zin        (BVALF_EX_LEAST)
     per witness x:  conj := [[ (i+1)%%i && empty_form(i+1) ]]_{(i+1|->x)}
       conj <= [[x in ss]] = memf
         (BVALF_AND_MEET/EMEET_LE)
       conj <= [[x empty]] = emptyf <= [[x=vemp]] = ea    (EMPTY_LE_EQ, L1)
       conj <= meet(ea,memf) = m                          (EMEET_GREATEST)
       m <= [[vemp in ss]] = zin                          (EBV_IN_CONG_L,
       u:=x,v:=vemp,w:=ss)
   ######################################################################### *)

let INDUCTIVE_LE_EMPTYMEM = prove
 (`!D (E:A->A->bool) B leq onebee emp vemp v i ss zin.
      model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
      onebee IN D /\ E onebee B /\
      echeck D E onebee emp vemp /\ (!c. c IN D ==> ~(E c emp)) /\
      valuation D v /\ (!j. bname D E B (v j)) /\
      v i = ss /\ ss IN D /\ bname D E B ss /\
      zin IN D /\ ebv_in D E B leq vemp ss zin
      ==> erel D E leq (bvalf D E B leq v (inductive_form i)) zin`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `ebalg D (E:A->A->bool) B leq /\ eporder D E B leq`
    STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[ECBA_IMP_BALG; EBALG_IMP_PORDER]; ALL_TAC] THEN
  (* emp, vemp in D ; bname vemp *)
  SUBGOAL_THEN `emp IN D /\ (vemp:A) IN D` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[ECHECK_IMP]; ALL_TAC] THEN
  SUBGOAL_THEN `bname D (E:A->A->bool) B vemp` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`onebee:A`;`B:A`;`emp:A`;`vemp:A`]
                 ECHECK_IS_BNAME) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* E zin B *)
  SUBGOAL_THEN `(E:A->A->bool) zin B` ASSUME_TAC THENL
   [MP_TAC(ISPECL
           [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`vemp:A`;`ss:A`;`zin:A`]
           EBV_IN_IN_B) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* field facts : c0 = [[inductive_form i]] *)
  SUBGOAL_THEN `(bvalf D (E:A->A->bool) B leq v (inductive_form i)) IN D /\
                (E:A->A->bool) (bvalf D E B leq v (inductive_form i)) B`
  STRIP_ASSUME_TAC THENL
   [CONJ_TAC THENL
     [MP_TAC(ISPECL
             [`inductive_form i`;`D:A->bool`;`E:A->A->bool`;`B:A`;
              `leq:A`;`v:num->A`]
             BVALF_SPEC) THEN ASM_SIMP_TAC[];
      MP_TAC(ISPECL
             [`inductive_form i`;`D:A->bool`;`E:A->A->bool`;`B:A`;
              `leq:A`;`v:num->A`]
             BVALF_IN_B) THEN ASM_SIMP_TAC[]]; ALL_TAC] THEN
  (* field facts : aav = [[??- (i+1) i (empty_form(i+1))]] *)
  SUBGOAL_THEN
    `(bvalf D (E:A->A->bool) B leq v (??- (i+1) i (empty_form (i+1)))) IN D /\
     (E:A->A->bool) (bvalf D E B leq v (??- (i+1) i (empty_form (i+1)))) B`
  STRIP_ASSUME_TAC THENL
   [CONJ_TAC THENL
     [MP_TAC(ISPECL
             [`??- (i+1) i (empty_form (i+1))`;`D:A->bool`;
              `E:A->A->bool`;`B:A`;
              `leq:A`;`v:num->A`] BVALF_SPEC) THEN ASM_SIMP_TAC[];
      MP_TAC(ISPECL
             [`??- (i+1) i (empty_form (i+1))`;`D:A->bool`;
              `E:A->A->bool`;`B:A`;
              `leq:A`;`v:num->A`] BVALF_IN_B) THEN ASM_SIMP_TAC[]];
     ALL_TAC] THEN
  (* ===== main chain : c0 <= aav <= zin ===== *)
  MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
    `bvalf D (E:A->A->bool) B leq v (inductive_form i)`;
    `bvalf D (E:A->A->bool) B leq v (??- (i+1) i (empty_form (i+1)))`;
    `zin:A`] EPORDER_TRANS) THEN
  ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
   [ (* ----- c0 <= aav : BVALF_AND_LE_L ----- *)
    REWRITE_TAC[inductive_form] THEN
    MATCH_MP_TAC BVALF_AND_LE_L THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  (* ----- aav <= zin : Existsmem + BVALF_EX_LEAST ----- *)
  REWRITE_TAC[Existsmem_DEF] THEN
  MATCH_MP_TAC BVALF_EX_LEAST THEN ASM_REWRITE_TAC[] THEN
  X_GEN_TAC `x:A` THEN STRIP_TAC THEN
  (* valuation / bnames of the extended valuation *)
  SUBGOAL_THEN `valuation D (((i + 1) |-> (x:A)) v) /\
                (!j. bname D (E:A->A->bool) B ((((i + 1) |-> (x:A)) v) j))`
  STRIP_ASSUME_TAC THENL
   [CONJ_TAC THENL
     [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[];
      MATCH_MP_TAC BNAMEVAL_VALMOD THEN ASM_REWRITE_TAC[]]; ALL_TAC] THEN
  (* field facts : memf = [[x in ss]] *)
  SUBGOAL_THEN
    `(bvalf D (E:A->A->bool) B leq (((i + 1) |-> (x:A)) v)
      ((i+1) %% i)) IN D /\
     (E:A->A->bool) (bvalf D E B leq (((i + 1) |-> (x:A)) v) ((i+1) %% i)) B`
  STRIP_ASSUME_TAC THENL
   [CONJ_TAC THENL
     [MP_TAC(ISPECL [`(i+1) %% i`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
        `((i + 1) |-> (x:A)) v`] BVALF_SPEC) THEN ASM_SIMP_TAC[];
      MP_TAC(ISPECL [`(i+1) %% i`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
        `((i + 1) |-> (x:A)) v`] BVALF_IN_B) THEN ASM_SIMP_TAC[]];
     ALL_TAC] THEN
  SUBGOAL_THEN `ebv_in D (E:A->A->bool) B leq x ss
                  (bvalf D E B leq (((i + 1) |-> (x:A)) v) ((i+1) %% i))`
    ASSUME_TAC THENL
   [MP_TAC(ISPECL [`i + 1`;`i:num`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
      `((i + 1) |-> (x:A)) v`] BVALF_MEM) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER; ARITH_RULE `~(i = i + 1)`];
    ALL_TAC] THEN
  (* field facts : emptyf = [[x empty]] *)
  SUBGOAL_THEN
    `(bvalf D (E:A->A->bool) B leq (((i + 1) |-> (x:A)) v)
      (empty_form (i+1))) IN D /\
     (E:A->A->bool)
       (bvalf D E B leq (((i + 1) |-> (x:A)) v) (empty_form (i+1))) B`
  STRIP_ASSUME_TAC THENL
   [CONJ_TAC THENL
     [MP_TAC(ISPECL
             [`empty_form (i+1)`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
              `((i + 1) |-> (x:A)) v`] BVALF_SPEC) THEN ASM_SIMP_TAC[];
      MP_TAC(ISPECL
             [`empty_form (i+1)`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
              `((i + 1) |-> (x:A)) v`] BVALF_IN_B) THEN ASM_SIMP_TAC[]];
     ALL_TAC] THEN
  (* field facts : conj = [[ (i+1)%%i && empty_form(i+1) ]] *)
  SUBGOAL_THEN
    `(bvalf D (E:A->A->bool) B leq (((i + 1) |-> (x:A)) v)
        (((i+1) %% i) && empty_form (i+1))) IN D /\
     (E:A->A->bool) (bvalf D E B leq (((i + 1) |-> (x:A)) v)
        (((i+1) %% i) && empty_form (i+1))) B`
  STRIP_ASSUME_TAC THENL
   [CONJ_TAC THENL
     [MP_TAC(ISPECL
             [`((i+1) %% i) && empty_form (i+1)`;`D:A->bool`;
              `E:A->A->bool`;`B:A`;
              `leq:A`;`((i + 1) |-> (x:A)) v`] BVALF_SPEC) THEN ASM_SIMP_TAC[];
      MP_TAC(ISPECL
             [`((i+1) %% i) && empty_form (i+1)`;`D:A->bool`;
              `E:A->A->bool`;`B:A`;
              `leq:A`;`((i + 1) |-> (x:A)) v`] BVALF_IN_B) THEN
      ASM_SIMP_TAC[]]; ALL_TAC] THEN
  (* ea : [[x = vemp]] value *)
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`x:A`;`vemp:A`]
    EBV_EQ_VAL_EXISTS) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `ea:A` STRIP_ASSUME_TAC) THEN
  (* emptyf <= ea  (L1 at index i+1) *)
  SUBGOAL_THEN `erel D (E:A->A->bool) leq
                  (bvalf D E B leq (((i + 1) |-> (x:A)) v)
                   (empty_form (i+1))) ea`
  ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`onebee:A`;`emp:A`;
                  `vemp:A`;`((i + 1) |-> (x:A)) v`;`i + 1`;`x:A`;`ea:A`]
                   EMPTY_LE_EQ) THEN
    ASM_SIMP_TAC[VALMOD_BASIC]; ALL_TAC] THEN
  (* emeet memf emptyf conj *)
  SUBGOAL_THEN `emeet D (E:A->A->bool) B leq
                  (bvalf D E B leq (((i + 1) |-> (x:A)) v) ((i+1) %% i))
                  (bvalf D E B leq (((i + 1) |-> (x:A)) v) (empty_form (i+1)))
                  (bvalf D E B leq (((i + 1) |-> (x:A)) v)
                     (((i+1) %% i) && empty_form (i+1)))`
  ASSUME_TAC THENL
   [MATCH_MP_TAC BVALF_AND_MEET THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* conj <= memf, conj <= emptyf *)
  FIRST_ASSUM(STRIP_ASSUME_TAC o MATCH_MP EMEET_LE) THEN
  (* conj <= ea  (via emptyf) *)
  SUBGOAL_THEN `erel D (E:A->A->bool) leq
                  (bvalf D E B leq (((i + 1) |-> (x:A)) v)
                     (((i+1) %% i) && empty_form (i+1))) ea`
  ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
      `bvalf D (E:A->A->bool) B leq (((i + 1) |-> (x:A)) v)
         (((i+1) %% i) && empty_form (i+1))`;
      `bvalf D (E:A->A->bool) B leq (((i + 1) |-> (x:A)) v)
       (empty_form (i+1))`;
      `ea:A`] EPORDER_TRANS) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* m = meet(ea, memf) *)
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`ea:A`;
    `bvalf D (E:A->A->bool) B leq (((i + 1) |-> (x:A)) v) ((i+1) %% i)`]
    EBALG_MEET) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_TAC `m:A`) THEN
  SUBGOAL_THEN `(m:A) IN D /\ (E:A->A->bool) m B` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[EMEET_IN]; ALL_TAC] THEN
  (* conj <= m  (EMEET_GREATEST) *)
  SUBGOAL_THEN `erel D (E:A->A->bool) leq
                  (bvalf D E B leq (((i + 1) |-> (x:A)) v)
                     (((i+1) %% i) && empty_form (i+1))) m`
  ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`ea:A`;
      `bvalf D (E:A->A->bool) B leq (((i + 1) |-> (x:A)) v)
       ((i+1) %% i)`;`m:A`;
      `bvalf D (E:A->A->bool) B leq (((i + 1) |-> (x:A)) v)
         (((i+1) %% i) && empty_form (i+1))`] EMEET_GREATEST) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* m <= zin  (EBV_IN_CONG_L : u:=x, v:=vemp, w:=ss) *)
  SUBGOAL_THEN `erel D (E:A->A->bool) leq m zin` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`x:A`;
                  `vemp:A`;`ss:A`;
                  `ea:A`;
      `bvalf D (E:A->A->bool) B leq (((i + 1) |-> (x:A)) v) ((i+1) %% i)`;
      `zin:A`;`m:A`] EBV_IN_CONG_L) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* conj <= zin  (via m) *)
  MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
    `bvalf D (E:A->A->bool) B leq (((i + 1) |-> (x:A)) v)
       (((i+1) %% i) && empty_form (i+1))`;
    `m:A`;`zin:A`] EPORDER_TRANS) THEN
  ASM_REWRITE_TAC[]);;

(* ############################################################################
   L3  SUCFORM_LE_EQ :  [[ suc_form i j ]]_{i:=cv, j:=s}  <=  [[ s = scv ]].
   If s "is the successor of cv" (= c-check) then s equals scv (=
     (suc c)-check).
   Here cv = c^, scv = (suc c)^.  Via EBV_EQ_GLB with w0 := [[suc_form i j]]_v,
   u := s, v := scv:
     hu : for every x, w0 <= ([[x in s]] => [[x in scv]]).
     hv : for every x, w0 <= ([[x in scv]] => [[x in s]]).
   For each x, instantiate the suc_form binder at x (BVALF_ALL_LB), split the
   biconditional (Iff_DEF + BVALF_AND_LE_L/R), and identify
     [[(x in cv) || x = cv]] = [[x in cv]] |_| [[x = cv]] = [[x in scv]]
   (BVALF_OR + ECHECK_IN_SUCC), so the kept implication value equals the
   obligation's ebimp (EBIMP_UNIQUE).
   ######################################################################### *)

let SUCFORM_LE_EQ = prove
 (`!D (E:A->A->bool) B leq onebee c cv sc scv v i j s zeq.
      model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
      onebee IN D /\ E onebee B /\ etop D E B leq onebee /\
      c IN D /\ sc IN D /\ esuc D E c sc /\
      echeck D E onebee c cv /\ echeck D E onebee sc scv /\
      cv IN D /\ scv IN D /\ bname D E B cv /\ bname D E B scv /\
      valuation D v /\ (!k. bname D E B (v k)) /\
      v i = cv /\ v j = s /\ s IN D /\ bname D E B s /\
      zeq IN D /\ ebv_eq D E B leq s scv zeq
      ==> erel D E leq (bvalf D E B leq v (suc_form i j)) zeq`,
  let vvx = `((MAX i j + 1) |-> (x:A)) v`
  and vvy = `((MAX i j + 1) |-> (y:A)) v` in
  let insimp vv p =
    MP_TAC(ISPECL [p;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;vv]
           BVALF_SPEC) THEN
    ASM_SIMP_TAC[] in
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `ebalg D (E:A->A->bool) B leq /\ eporder D E B leq`
    STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[ECBA_IMP_BALG; EBALG_IMP_PORDER]; ALL_TAC] THEN
  (* successor characterization for ECHECK_IN_SUCC *)
  SUBGOAL_THEN `!dd:A. dd IN D ==> ((E:A->A->bool) dd sc <=> E dd c \/ dd = c)`
  ASSUME_TAC THENL
   [UNDISCH_TAC `esuc D (E:A->A->bool) c sc` THEN ASM_SIMP_TAC[ESUC_ALT] THEN
    STRIP_TAC THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* field facts : w0 = [[suc_form i j]] *)
  SUBGOAL_THEN `(bvalf D (E:A->A->bool) B leq v (suc_form i j)) IN D /\
                (E:A->A->bool) (bvalf D E B leq v (suc_form i j)) B`
  STRIP_ASSUME_TAC THENL
   [CONJ_TAC THENL
     [MP_TAC(ISPECL
             [`suc_form i j`;`D:A->bool`;`E:A->A->bool`;`B:A`;
              `leq:A`;`v:num->A`]
             BVALF_SPEC) THEN ASM_SIMP_TAC[];
      MP_TAC(ISPECL
             [`suc_form i j`;`D:A->bool`;`E:A->A->bool`;`B:A`;
              `leq:A`;`v:num->A`]
             BVALF_IN_B) THEN ASM_SIMP_TAC[]]; ALL_TAC] THEN
  (* ===== MAIN : EBV_EQ_GLB (u:=s, v:=scv, z:=zeq, w0:=[[suc_form i j]]) *)
  (* ===== *)
  MP_TAC(ISPECL
         [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`s:A`;`scv:A`;`zeq:A`;
          `bvalf D (E:A->A->bool) B leq v (suc_form i j)`] EBV_EQ_GLB) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
     [ (* =============================== hu =============================== *)
      MAP_EVERY X_GEN_TAC [`x:A`;`inx0:A`;`inx1:A`;`cc:A`] THEN STRIP_TAC THEN
      (* vvx valuation + bnames *)
      SUBGOAL_THEN `valuation D (((MAX i j + 1) |-> (x:A)) v) /\
                    (!k. bname D (E:A->A->bool) B
                     ((((MAX i j + 1) |-> (x:A)) v) k))`
      STRIP_ASSUME_TAC THENL
       [CONJ_TAC THENL
         [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[];
          MATCH_MP_TAC BNAMEVAL_VALMOD THEN ASM_REWRITE_TAC[]]; ALL_TAC] THEN
      (* IN D for all the sub-formula values *)
      SUBGOAL_THEN
       `(bvalf D (E:A->A->bool) B leq (((MAX i j + 1)|->(x:A))v)
