                         ((((MAX i j + 1) %% i) || Eq (MAX i j + 1) i) -->
                          ((MAX i j + 1) %% j)))`
      ASSUME_TAC THENL
       [UNDISCH_TAC `ebimp D (E:A->A->bool) B leq
          (bvalf D E B leq (((MAX i j + 1)|->(y:A))v)
             (((MAX i j + 1) %% i) || Eq (MAX i j + 1) i))
          (bvalf D E B leq (((MAX i j + 1)|->(y:A))v) ((MAX i j + 1) %% j))
          (bvalf D E B leq (((MAX i j + 1)|->(y:A))v)
             ((((MAX i j + 1) %% i) || Eq (MAX i j + 1) i) -->
              ((MAX i j + 1) %% j)))` THEN
        ASM_REWRITE_TAC[]; ALL_TAC] THEN
      (* [[impr]] = cc  (EBIMP_UNIQUE) *)
      SUBGOAL_THEN `bvalf D (E:A->A->bool) B leq (((MAX i j + 1)|->(y:A))v)
                      ((((MAX i j + 1) %% i) || Eq (MAX i j + 1) i) -->
                       ((MAX i j + 1) %% j)) = cc`
      ASSUME_TAC THENL
       [MATCH_MP_TAC(ISPECL
                     [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
                      `iny0:A`;`iny1:A`;
                      `bvalf D (E:A->A->bool) B leq (((MAX i j + 1)|->(y:A))v)
             ((((MAX i j + 1) %% i) || Eq (MAX i j + 1) i) -->
              ((MAX i j + 1) %% j))`;`cc:A`]
          EBIMP_UNIQUE) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
      (* w0 <= [[iff]]  (BVALF_ALL_LB) *)
      SUBGOAL_THEN
        `erel D (E:A->A->bool) leq (bvalf D E B leq v (suc_form i j))
           (bvalf D E B leq (((MAX i j + 1)|->(y:A))v)
                         (((MAX i j + 1) %% j) <-> ((MAX i j + 1) %% i) ||
                          Eq (MAX i j + 1) i))`
      ASSUME_TAC THENL
       [REWRITE_TAC[suc_form] THEN
        MATCH_MP_TAC(ISPECL [`MAX i j + 1`;
          `((MAX i j + 1) %% j) <-> ((MAX i j + 1) %% i) ||
           Eq (MAX i j + 1) i`;
          `D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`v:num->A`;`y:A`]
                           BVALF_ALL_LB) THEN
        ASM_REWRITE_TAC[]; ALL_TAC] THEN
      (* [[iff]] <= [[impr]]  (Iff_DEF + BVALF_AND_LE_R) *)
      SUBGOAL_THEN `erel D (E:A->A->bool) leq
                      (bvalf D E B leq (((MAX i j + 1)|->(y:A))v)
                         (((MAX i j + 1) %% j) <-> ((MAX i j + 1) %% i) ||
                          Eq (MAX i j + 1) i))
                      (bvalf D E B leq (((MAX i j + 1)|->(y:A))v)
                         ((((MAX i j + 1) %% i) || Eq (MAX i j + 1) i) -->
                          ((MAX i j + 1) %% j)))`
      ASSUME_TAC THENL
       [REWRITE_TAC[Iff_DEF] THEN MATCH_MP_TAC BVALF_AND_LE_R THEN
        ASM_REWRITE_TAC[]; ALL_TAC] THEN
      (* finish : w0 <= cc *)
      UNDISCH_TAC `bvalf D (E:A->A->bool) B leq (((MAX i j + 1)|->(y:A))v)
                     ((((MAX i j + 1) %% i) || Eq (MAX i j + 1) i) -->
                      ((MAX i j + 1) %% j)) = cc` THEN
      DISCH_THEN(SUBST1_TAC o SYM) THEN
      MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
        `bvalf D (E:A->A->bool) B leq v (suc_form i j)`;
        `bvalf D (E:A->A->bool) B leq (((MAX i j + 1)|->(y:A))v)
           (((MAX i j + 1) %% j) <-> ((MAX i j + 1) %% i) ||
            Eq (MAX i j + 1) i)`;
        `bvalf D (E:A->A->bool) B leq (((MAX i j + 1)|->(y:A))v)
           ((((MAX i j + 1) %% i) || Eq (MAX i j + 1) i) -->
            ((MAX i j + 1) %% j))`]
        EPORDER_TRANS) THEN ASM_REWRITE_TAC[]];
    DISCH_THEN ACCEPT_TAC]);;

(* ############################################################################
   L4  INDUCTIVE_LE_SUCMEM : the omega-induction STEP (folded with the IH).
   Given c0 = [[inductive_form i]]_{i:=ss},
   and the check cv of an ordinal c and
   the check scv of its successor sc,
   if  c0 <= [[cv in ss]] = zc  (the IH), then
   c0 <= [[scv in ss]] = zsc.

   c0 <= 2nd conjunct of inductive_form (ss closed under successor)  [AND_LE_R]
       = [[ !w in ss. ?z in ss. z = suc w ]]
       <= [[ (cv in ss) --> ?z in ss. z = suc cv ]]_{(i+1):=cv}  [ALL_LB]
       = ebimp zc cons
         (BVALF_IMP, zc id)
   so (residuation EBIMP_MEET_LE with m0 = c0 MEET zc,
   using c0<=ebimp and IH c0<=zc):
       c0 <= m0 <= cons = [[ ?z in ss. z = suc cv ]]
   and  cons <= zsc  by BVALF_EX_LEAST: per witness s,
       [[s in ss]] MEET [[suc_form(i+1)(i+2)]] <= [[s=scv]] MEET [[s in ss]] <=
         [[scv in ss]]
       (SUCFORM_LE_EQ = L3, then EBV_IN_CONG_L : u:=s, v:=scv, w:=ss).
   ######################################################################### *)

let INDUCTIVE_LE_SUCMEM = prove
 (`!D (E:A->A->bool) B leq onebee c sc cv scv v i ss zc zsc.
      model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
      onebee IN D /\ E onebee B /\ etop D E B leq onebee /\
      c IN D /\ sc IN D /\ esuc D E c sc /\
      echeck D E onebee c cv /\ echeck D E onebee sc scv /\
      valuation D v /\ (!k. bname D E B (v k)) /\
      v i = ss /\ ss IN D /\ bname D E B ss /\
      zc IN D /\ ebv_in D E B leq cv ss zc /\
      zsc IN D /\ ebv_in D E B leq scv ss zsc /\
      erel D E leq (bvalf D E B leq v (inductive_form i)) zc
      ==> erel D E leq (bvalf D E B leq v (inductive_form i)) zsc`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `ebalg D (E:A->A->bool) B leq /\ eporder D E B leq`
    STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[ECBA_IMP_BALG; EBALG_IMP_PORDER]; ALL_TAC] THEN
  (* cv, scv in D ; bnames *)
  SUBGOAL_THEN `(cv:A) IN D /\ (scv:A) IN D` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[ECHECK_IMP]; ALL_TAC] THEN
  SUBGOAL_THEN `bname D (E:A->A->bool) B cv` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`onebee:A`;`B:A`;`c:A`;`cv:A`]
                 ECHECK_IS_BNAME) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `bname D (E:A->A->bool) B scv` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`onebee:A`;`B:A`;`sc:A`;`scv:A`]
                 ECHECK_IS_BNAME) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* E zc B, E zsc B *)
  SUBGOAL_THEN `(E:A->A->bool) zc B /\ (E:A->A->bool) zsc B`
    STRIP_ASSUME_TAC THENL
   [CONJ_TAC THENL
     [MP_TAC(ISPECL
             [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`cv:A`;`ss:A`;`zc:A`]
             EBV_IN_IN_B) THEN ASM_REWRITE_TAC[];
      MP_TAC(ISPECL
             [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`scv:A`;`ss:A`;`zsc:A`]
             EBV_IN_IN_B) THEN ASM_REWRITE_TAC[]]; ALL_TAC] THEN
  (* field facts : c0 = [[inductive_form i]] *)
  SUBGOAL_THEN `(bvalf D (E:A->A->bool) B leq v (inductive_form i)) IN D /\
                (E:A->A->bool) (bvalf D E B leq v (inductive_form i)) B`
  STRIP_ASSUME_TAC THENL
   [CONJ_TAC THENL
     [MP_TAC(ISPECL
             [`inductive_form i`;`D:A->bool`;`E:A->A->bool`;`B:A`;
              `leq:A`;`v:num->A`]
             BVALF_SPEC) THEN ASM_SIMP_TAC[];
      MP_TAC(ISPECL
             [`inductive_form i`;`D:A->bool`;`E:A->A->bool`;`B:A`;
              `leq:A`;`v:num->A`]
             BVALF_IN_B) THEN ASM_SIMP_TAC[]]; ALL_TAC] THEN
  (* field facts : aav2 = [[!!- (i+1) i (??- (i+2) i (suc_form (i+1) *)
  (* (i+2)))]] *)
  SUBGOAL_THEN
    `(bvalf D (E:A->A->bool) B leq v
        (!!- (i+1) i (??- (i+2) i (suc_form (i+1) (i+2))))) IN D /\
     (E:A->A->bool) (bvalf D E B leq v
        (!!- (i+1) i (??- (i+2) i (suc_form (i+1) (i+2))))) B`
  STRIP_ASSUME_TAC THENL
   [CONJ_TAC THENL
     [MP_TAC(ISPECL [`!!- (i+1) i (??- (i+2) i (suc_form (i+1) (i+2)))`;
        `D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`v:num->A`] BVALF_SPEC) THEN
        ASM_SIMP_TAC[];
        MP_TAC(ISPECL [`!!- (i+1) i (??- (i+2) i (suc_form (i+1) (i+2)))`;
        `D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`v:num->A`] BVALF_IN_B) THEN
        ASM_SIMP_TAC[]];
    ALL_TAC] THEN
  (* w1 = ((i+1)|->cv) v : valuation + bnames *)
  SUBGOAL_THEN `valuation D (((i + 1) |-> (cv:A)) v) /\
                (!k. bname D (E:A->A->bool) B ((((i + 1) |-> (cv:A)) v) k))`
  STRIP_ASSUME_TAC THENL
   [CONJ_TAC THENL
     [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[];
      MATCH_MP_TAC BNAMEVAL_VALMOD THEN ASM_REWRITE_TAC[]]; ALL_TAC] THEN
  (* field facts on w1 : memf1, consval, bodyval *)
  SUBGOAL_THEN
    `(bvalf D (E:A->A->bool) B leq (((i + 1) |-> (cv:A)) v)
      ((i+1) %% i)) IN D /\
     (bvalf D (E:A->A->bool) B leq (((i + 1) |-> (cv:A)) v)
        (??- (i+2) i (suc_form (i+1) (i+2)))) IN D /\
     (E:A->A->bool) (bvalf D E B leq (((i + 1) |-> (cv:A)) v)
        (??- (i+2) i (suc_form (i+1) (i+2)))) B /\
     (bvalf D (E:A->A->bool) B leq (((i + 1) |-> (cv:A)) v)
        (((i+1) %% i) --> ??- (i+2) i (suc_form (i+1) (i+2)))) IN D /\
     (E:A->A->bool) (bvalf D E B leq (((i + 1) |-> (cv:A)) v)
        (((i+1) %% i) --> ??- (i+2) i (suc_form (i+1) (i+2)))) B`
  STRIP_ASSUME_TAC THENL
   [REPEAT CONJ_TAC THENL
     [MP_TAC(ISPECL [`(i+1) %% i`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
        `((i + 1) |-> (cv:A)) v`] BVALF_SPEC) THEN ASM_SIMP_TAC[];
      MP_TAC(ISPECL
             [`??- (i+2) i (suc_form (i+1) (i+2))`;`D:A->bool`;
              `E:A->A->bool`;`B:A`;
              `leq:A`;`((i + 1) |-> (cv:A)) v`] BVALF_SPEC) THEN
      ASM_SIMP_TAC[];
      MP_TAC(ISPECL
             [`??- (i+2) i (suc_form (i+1) (i+2))`;`D:A->bool`;
              `E:A->A->bool`;`B:A`;
              `leq:A`;`((i + 1) |-> (cv:A)) v`] BVALF_IN_B) THEN
      ASM_SIMP_TAC[];
      MP_TAC(ISPECL [`((i+1) %% i) --> ??- (i+2) i (suc_form (i+1) (i+2))`;
        `D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
        `((i + 1) |-> (cv:A)) v`] BVALF_SPEC)
        THEN ASM_SIMP_TAC[];
      MP_TAC(ISPECL [`((i+1) %% i) --> ??- (i+2) i (suc_form (i+1) (i+2))`;
        `D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
        `((i + 1) |-> (cv:A)) v`] BVALF_IN_B)
        THEN ASM_SIMP_TAC[]]; ALL_TAC] THEN
  (* memf1 = [[cv in ss]] = zc *)
  SUBGOAL_THEN `ebv_in D (E:A->A->bool) B leq cv ss
                  (bvalf D E B leq (((i + 1) |-> (cv:A)) v) ((i+1) %% i))`
    ASSUME_TAC THENL
   [MP_TAC(ISPECL [`i + 1`;`i:num`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
      `((i + 1) |-> (cv:A)) v`] BVALF_MEM) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER; ARITH_RULE `~(i = i + 1)`];
    ALL_TAC] THEN
  SUBGOAL_THEN
    `bvalf D (E:A->A->bool) B leq (((i + 1) |-> (cv:A)) v) ((i+1) %% i) = zc`
  ASSUME_TAC THENL
   [MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`cv:A`;`ss:A`;
      `bvalf D (E:A->A->bool) B leq (((i + 1) |-> (cv:A)) v)
       ((i+1) %% i)`;`zc:A`]
      EBV_IN_UNIQUE) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* ebimp zc consval bodyval  (BVALF_IMP + fold) *)
  SUBGOAL_THEN `ebimp D (E:A->A->bool) B leq zc
                  (bvalf D E B leq (((i + 1) |-> (cv:A)) v)
                     (??- (i+2) i (suc_form (i+1) (i+2))))
                  (bvalf D E B leq (((i + 1) |-> (cv:A)) v)
                     (((i+1) %% i) --> ??- (i+2) i (suc_form (i+1) (i+2))))`
  ASSUME_TAC THENL
   [MP_TAC(ISPECL [`(i+1) %% i`;`??- (i+2) i (suc_form (i+1) (i+2))`;
      `D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`((i + 1) |-> (cv:A)) v`]
                       BVALF_IMP) THEN
    ASM_SIMP_TAC[]; ALL_TAC] THEN
  (* c0 <= aav2  (AND_LE_R) *)
  SUBGOAL_THEN
    `erel D (E:A->A->bool) leq (bvalf D E B leq v (inductive_form i))
       (bvalf D E B leq v (!!- (i+1) i (??- (i+2) i (suc_form (i+1) (i+2)))))`
  ASSUME_TAC THENL
   [REWRITE_TAC[inductive_form] THEN MATCH_MP_TAC BVALF_AND_LE_R THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  (* aav2 <= bodyval  (Forallmem + ALL_LB at (i+1):=cv) *)
  SUBGOAL_THEN `erel D (E:A->A->bool) leq
                  (bvalf D E B leq v
                   (!!- (i+1) i (??- (i+2) i (suc_form (i+1) (i+2)))))
                  (bvalf D E B leq (((i + 1) |-> (cv:A)) v)
                     (((i+1) %% i) --> ??- (i+2) i (suc_form (i+1) (i+2))))`
  ASSUME_TAC THENL
   [REWRITE_TAC[Forallmem_DEF] THEN
    MATCH_MP_TAC(ISPECL [`i + 1`;
      `((i+1) %% i) --> ??- (i+2) i (suc_form (i+1) (i+2))`;
      `D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`v:num->A`;`cv:A`]
                       BVALF_ALL_LB) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* c0 <= bodyval  (TRANS) *)
  SUBGOAL_THEN
    `erel D (E:A->A->bool) leq (bvalf D E B leq v (inductive_form i))
       (bvalf D E B leq (((i + 1) |-> (cv:A)) v)
                     (((i+1) %% i) --> ??- (i+2) i (suc_form (i+1) (i+2))))`
  ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
      `bvalf D (E:A->A->bool) B leq v (inductive_form i)`;
      `bvalf D (E:A->A->bool) B leq v
       (!!- (i+1) i (??- (i+2) i (suc_form (i+1) (i+2))))`;
      `bvalf D (E:A->A->bool) B leq (((i + 1) |-> (cv:A)) v)
         (((i+1) %% i) --> ??- (i+2) i (suc_form (i+1) (i+2)))`]
                       EPORDER_TRANS) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* m0 = meet(c0, zc) *)
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
    `bvalf D (E:A->A->bool) B leq v (inductive_form i)`;`zc:A`]
      EBALG_MEET) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_TAC `m0:A`) THEN
  SUBGOAL_THEN `(m0:A) IN D /\ (E:A->A->bool) m0 B` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[EMEET_IN]; ALL_TAC] THEN
  (* c0 <= m0  (EMEET_GREATEST : c0<=c0 refl, c0<=zc IH) *)
  SUBGOAL_THEN
    `erel D (E:A->A->bool) leq (bvalf D E B leq v (inductive_form i)) m0`
  ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
      `bvalf D (E:A->A->bool) B leq v (inductive_form i)`;`zc:A`;`m0:A`;
      `bvalf D (E:A->A->bool) B leq v (inductive_form i)`] EMEET_GREATEST) THEN
    ASM_REWRITE_TAC[] THEN
    MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
      `bvalf D (E:A->A->bool) B leq v (inductive_form i)`] EPORDER_REFL) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* m0 <= consval  (EBIMP_MEET_LE) *)
  SUBGOAL_THEN `erel D (E:A->A->bool) leq m0
                  (bvalf D E B leq (((i + 1) |-> (cv:A)) v)
                     (??- (i+2) i (suc_form (i+1) (i+2))))`
  ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
      `bvalf D (E:A->A->bool) B leq v (inductive_form i)`;`zc:A`;
      `bvalf D (E:A->A->bool) B leq (((i + 1) |-> (cv:A)) v)
         (??- (i+2) i (suc_form (i+1) (i+2)))`;
      `bvalf D (E:A->A->bool) B leq (((i + 1) |-> (cv:A)) v)
         (((i+1) %% i) --> ??- (i+2) i (suc_form (i+1) (i+2)))`;`m0:A`]
                       EBIMP_MEET_LE) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* c0 <= consval  (TRANS c0 m0 consval) *)
  SUBGOAL_THEN
    `erel D (E:A->A->bool) leq (bvalf D E B leq v (inductive_form i))
       (bvalf D E B leq (((i + 1) |-> (cv:A)) v)
                     (??- (i+2) i (suc_form (i+1) (i+2))))`
  ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
      `bvalf D (E:A->A->bool) B leq v (inductive_form i)`;`m0:A`;
      `bvalf D (E:A->A->bool) B leq (((i + 1) |-> (cv:A)) v)
         (??- (i+2) i (suc_form (i+1) (i+2)))`] EPORDER_TRANS) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* final : c0 <= zsc  via  c0 <= consval <= zsc *)
  MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
    `bvalf D (E:A->A->bool) B leq v (inductive_form i)`;
    `bvalf D (E:A->A->bool) B leq (((i + 1) |-> (cv:A)) v)
       (??- (i+2) i (suc_form (i+1) (i+2)))`;`zsc:A`] EPORDER_TRANS) THEN
  ASM_REWRITE_TAC[] THEN
  (* ===== consval <= zsc : Existsmem + BVALF_EX_LEAST ===== *)
  REWRITE_TAC[Existsmem_DEF] THEN
  MATCH_MP_TAC BVALF_EX_LEAST THEN ASM_REWRITE_TAC[] THEN
  X_GEN_TAC `s:A` THEN STRIP_TAC THEN
  (* w2 = ((i+2)|->s) w1 : valuation + bnames *)
  SUBGOAL_THEN
    `valuation D (((i + 2) |-> (s:A)) (((i + 1) |-> (cv:A)) v)) /\
     (!k. bname D (E:A->A->bool) B
      ((((i + 2) |-> (s:A)) (((i + 1) |-> (cv:A)) v)) k))`
  STRIP_ASSUME_TAC THENL
   [CONJ_TAC THENL
     [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[];
      MATCH_MP_TAC BNAMEVAL_VALMOD THEN ASM_REWRITE_TAC[]]; ALL_TAC] THEN
  (* field facts : memf = [[s in ss]], sucf, conj *)
  SUBGOAL_THEN
    `(bvalf D (E:A->A->bool) B leq
      (((i + 2) |-> (s:A)) (((i + 1) |-> (cv:A)) v))
      ((i+2) %% i)) IN D /\
     (E:A->A->bool)
       (bvalf D E B leq (((i + 2) |-> (s:A)) (((i + 1) |-> (cv:A)) v))
        ((i+2) %% i)) B /\
     (bvalf D (E:A->A->bool) B leq
      (((i + 2) |-> (s:A)) (((i + 1) |-> (cv:A)) v))
      (suc_form (i+1) (i+2))) IN D /\
     (E:A->A->bool)
       (bvalf D E B leq (((i + 2) |-> (s:A)) (((i + 1) |-> (cv:A)) v))
        (suc_form (i+1) (i+2))) B /\
     (bvalf D (E:A->A->bool) B leq
      (((i + 2) |-> (s:A)) (((i + 1) |-> (cv:A)) v))
      (((i+2) %% i) && suc_form (i+1) (i+2))) IN D /\
     (E:A->A->bool)
       (bvalf D E B leq (((i + 2) |-> (s:A)) (((i + 1) |-> (cv:A)) v))
        (((i+2) %% i) && suc_form (i+1) (i+2))) B`
  STRIP_ASSUME_TAC THENL
   [REPEAT CONJ_TAC THENL
     [MP_TAC(ISPECL [`(i+2) %% i`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
        `((i + 2) |-> (s:A)) (((i + 1) |-> (cv:A)) v)`] BVALF_SPEC) THEN
        ASM_SIMP_TAC[];
        MP_TAC(ISPECL [`(i+2) %% i`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
        `((i + 2) |-> (s:A)) (((i + 1) |-> (cv:A)) v)`] BVALF_IN_B) THEN
        ASM_SIMP_TAC[];
        MP_TAC(ISPECL
               [`suc_form (i+1) (i+2)`;`D:A->bool`;`E:A->A->bool`;
                `B:A`;`leq:A`;
                `((i + 2) |-> (s:A)) (((i + 1) |-> (cv:A)) v)`]
                 BVALF_SPEC) THEN ASM_SIMP_TAC[];
      MP_TAC(ISPECL
             [`suc_form (i+1) (i+2)`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
              `((i + 2) |-> (s:A)) (((i + 1) |-> (cv:A)) v)`] BVALF_IN_B) THEN
      ASM_SIMP_TAC[];
      MP_TAC(ISPECL
             [`((i+2) %% i) && suc_form (i+1) (i+2)`;`D:A->bool`;
              `E:A->A->bool`;`B:A`;
              `leq:A`;`((i + 2) |-> (s:A)) (((i + 1) |-> (cv:A)) v)`]
               BVALF_SPEC) THEN ASM_SIMP_TAC[];
      MP_TAC(ISPECL
             [`((i+2) %% i) && suc_form (i+1) (i+2)`;`D:A->bool`;
              `E:A->A->bool`;`B:A`;
              `leq:A`;`((i + 2) |-> (s:A)) (((i + 1) |-> (cv:A)) v)`]
               BVALF_IN_B) THEN ASM_SIMP_TAC[]];
    ALL_TAC] THEN
  (* ebv_in s ss memf *)
  SUBGOAL_THEN `ebv_in D (E:A->A->bool) B leq s ss
                  (bvalf D E B leq
                   (((i + 2) |-> (s:A)) (((i + 1) |-> (cv:A)) v))
                   ((i+2) %% i))` ASSUME_TAC THENL
   [MP_TAC(ISPECL [`i + 2`;`i:num`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
      `((i + 2) |-> (s:A)) (((i + 1) |-> (cv:A)) v)`] BVALF_MEM) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER; ARITH_RULE `~(i = i + 2)`;
      ARITH_RULE `~(i = i + 1)`]; ALL_TAC] THEN
  (* ea = [[s = scv]] *)
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`s:A`;`scv:A`]
    EBV_EQ_VAL_EXISTS) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `ea:A` STRIP_ASSUME_TAC) THEN
  (* sucf <= ea  (L3 : SUCFORM_LE_EQ, indices i+1, i+2) *)
  SUBGOAL_THEN `erel D (E:A->A->bool) leq
                  (bvalf D E B leq
                   (((i + 2) |-> (s:A)) (((i + 1) |-> (cv:A)) v))
                   (suc_form (i+1) (i+2))) ea`
  ASSUME_TAC THENL
   [MP_TAC(ISPECL
           [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`onebee:A`;`c:A`;`cv:A`;
            `sc:A`;`scv:A`;`((i + 2) |-> (s:A)) (((i + 1) |-> (cv:A)) v)`;
            `i + 1`;`i + 2`;
            `s:A`;`ea:A`] SUCFORM_LE_EQ) THEN
    ANTS_TAC THENL
     [ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER;
                   ARITH_RULE `~(i + 1 = i + 2)`] THEN
      ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC]; ALL_TAC] THEN
  (* emeet memf sucf conj *)
  SUBGOAL_THEN `emeet D (E:A->A->bool) B leq
                  (bvalf D E B leq
                   (((i + 2) |-> (s:A)) (((i + 1) |-> (cv:A)) v)) ((i+2) %% i))
                  (bvalf D E B leq
                   (((i + 2) |-> (s:A)) (((i + 1) |-> (cv:A)) v))
                   (suc_form (i+1) (i+2)))
                  (bvalf D E B leq
                   (((i + 2) |-> (s:A)) (((i + 1) |-> (cv:A)) v))
                   (((i+2) %% i) && suc_form (i+1) (i+2)))`
  ASSUME_TAC THENL
   [MATCH_MP_TAC BVALF_AND_MEET THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* conj <= memf, conj <= sucf *)
  FIRST_ASSUM(STRIP_ASSUME_TAC o MATCH_MP EMEET_LE) THEN
  (* conj <= ea  (via sucf) *)
  SUBGOAL_THEN `erel D (E:A->A->bool) leq
                  (bvalf D E B leq
                   (((i + 2) |-> (s:A)) (((i + 1) |-> (cv:A)) v))
                   (((i+2) %% i) && suc_form (i+1) (i+2))) ea`
  ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
      `bvalf D (E:A->A->bool) B leq
       (((i + 2) |-> (s:A)) (((i + 1) |-> (cv:A)) v))
         (((i+2) %% i) && suc_form (i+1) (i+2))`;
      `bvalf D (E:A->A->bool) B leq
       (((i + 2) |-> (s:A)) (((i + 1) |-> (cv:A)) v))
         (suc_form (i+1) (i+2))`;`ea:A`] EPORDER_TRANS) THEN ASM_REWRITE_TAC[];
                  ALL_TAC] THEN
  (* m2 = meet(ea, memf) *)
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`ea:A`;
    `bvalf D (E:A->A->bool) B leq
     (((i + 2) |-> (s:A)) (((i + 1) |-> (cv:A)) v)) ((i+2) %% i)`]
    EBALG_MEET) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_TAC `m2:A`) THEN
  SUBGOAL_THEN `(m2:A) IN D /\ (E:A->A->bool) m2 B` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[EMEET_IN]; ALL_TAC] THEN
  (* conj <= m2  (EMEET_GREATEST) *)
  SUBGOAL_THEN `erel D (E:A->A->bool) leq
                  (bvalf D E B leq
                   (((i + 2) |-> (s:A)) (((i + 1) |-> (cv:A)) v))
                   (((i+2) %% i) && suc_form (i+1) (i+2))) m2`
  ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`ea:A`;
      `bvalf D (E:A->A->bool) B leq
       (((i + 2) |-> (s:A)) (((i + 1) |-> (cv:A)) v)) ((i+2) %% i)`;
      `m2:A`;
      `bvalf D (E:A->A->bool) B leq
       (((i + 2) |-> (s:A)) (((i + 1) |-> (cv:A)) v))
         (((i+2) %% i) && suc_form (i+1) (i+2))`] EMEET_GREATEST) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* m2 <= zsc  (EBV_IN_CONG_L : u:=s, v:=scv, w:=ss) *)
  SUBGOAL_THEN `erel D (E:A->A->bool) leq m2 zsc` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`s:A`;
                  `scv:A`;`ss:A`;
                  `ea:A`;
      `bvalf D (E:A->A->bool) B leq
       (((i + 2) |-> (s:A)) (((i + 1) |-> (cv:A)) v)) ((i+2) %% i)`;
      `zsc:A`;`m2:A`] EBV_IN_CONG_L) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* conj <= zsc  (via m2) *)
  MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
    `bvalf D (E:A->A->bool) B leq
     (((i + 2) |-> (s:A)) (((i + 1) |-> (cv:A)) v))
       (((i+2) %% i) && suc_form (i+1) (i+2))`;`m2:A`;`zsc:A`]
      EPORDER_TRANS) THEN
  ASM_REWRITE_TAC[]);;

(* ############################################################################
   L5  nmemss_form + HOLDS_NMEMSS_FORM + NMEMSS_INDUCT.

   The internal omega-induction that drives (A1b):  for a FIXED Boolean element
   c0 and a fixed bname ss,
   if c0 bounds the empty-membership value (BASE) and is
   closed under the successor step (STEP), then for every n in omega and every
   check nch of n with membership value zn = [[nch in ss]],  c0 <= zn.

   The induction is INTERNAL (EOMEGA_INDUCT), so it is valid in an arbitrary
   (possibly nonstandard) model.  nmemss_form is the object formula whose value
   under (0|->n) says "for all checks nch of n and all zn=[[nch in
     ss]], c0<=zn".
   Slots:  0 = induction var n ;  1 = onebee ;  2 = B (pinned by ebv_in_form) ;
           5 = leq ;  6 = ss ;  7 = c0 ;  52,53 = the bound nch, zn.

   NMEMSS_INDUCT is stated with ABSTRACT BASE/STEP hypotheses (it does NOT call
   L2/L4) : L6 will discharge BASE from L2 (INDUCTIVE_LE_EMPTYMEM)
     and STEP from
   L4 (INDUCTIVE_LE_SUCMEM) after instantiating c0 := [[inductive_form i]].
   ######################################################################### *)

let nmemss_form = new_definition
  `nmemss_form =
     !! 52 (!! 53 ((echeck_form 1 0 52 && ebv_in_form 53 52 6 5) -->
                   rel_form 5 7 53))`;;

let HOLDS_NMEMSS_FORM = prove
 (`!D (E:A->A->bool) v.
      model D E ZF_AX /\ valuation D v
      ==> (holds D E v nmemss_form <=>
           (!nch zn. nch IN D /\ zn IN D
                     ==> echeck D E (v 1) (v 0) nch /\
                         ebv_in D E (v 2) (v 5) nch (v 6) zn
                     ==> erel D E (v 5) (v 7) zn))`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN
    `!a b. a IN D /\ b IN D
           ==> (holds D E ((53 |-> (b:A)) ((52 |-> (a:A)) v))
                  ((echeck_form 1 0 52 && ebv_in_form 53 52 6 5) -->
                   rel_form 5 7 53) <=>
                (echeck D E (v 1) (v 0) a /\
                 ebv_in D E (v 2) (v 5) a (v 6) b
                 ==> erel D E (v 5) (v 7) b))`
    (LABEL_TAC "body") THENL
   [MAP_EVERY X_GEN_TAC [`a:A`;`b:A`] THEN STRIP_TAC THEN
    SUBGOAL_THEN `valuation D ((53 |-> (b:A)) ((52 |-> (a:A)) v))`
      ASSUME_TAC THENL
      [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
    REWRITE_TAC[HOLDS_IMP; HOLDS_AND] THEN
    (* component 1 : echeck_form 1 0 52  (ASSUME_TAC : never collapses main *)
    (* goal) *)
    SUBGOAL_THEN
      `holds D E ((53 |-> (b:A)) ((52 |-> (a:A)) v)) (echeck_form 1 0 52) <=>
       echeck D E (v 1) (v 0) a`
     ASSUME_TAC THENL
     [MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;
        `(53 |-> (b:A)) ((52 |-> (a:A)) v)`;`1`;`0`;`52`]
                   HOLDS_ECHECK_FORM) THEN
      ASM_REWRITE_TAC[ARITH_RULE
        `~(1 = 2) /\ ~(1 = 3) /\ ~(1 = 4) /\ ~(1 = 49) /\ ~(1 = 50) /\
         ~(1 = 51) /\
         ~(0 = 2) /\ ~(0 = 3) /\ ~(0 = 4) /\ ~(0 = 49) /\ ~(0 = 50) /\
           ~(0 = 51) /\
         ~(52 = 2) /\ ~(52 = 3) /\ ~(52 = 4) /\
         ~(52 = 49) /\ ~(52 = 50) /\ ~(52 = 51)`] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
      REWRITE_TAC[VALMOD; ARITH_EQ]; ALL_TAC] THEN
    (* component 2 : ebv_in_form 53 52 6 5 *)
    SUBGOAL_THEN
      `holds D E ((53 |-> (b:A)) ((52 |-> (a:A)) v))
       (ebv_in_form 53 52 6 5) <=>
       ebv_in D E (v 2) (v 5) a (v 6) b`
     ASSUME_TAC THENL
     [MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;
        `(53 |-> (b:A)) ((52 |-> (a:A)) v)`;`53`;`52`;`6`;`5`]
          HOLDS_EBV_IN_FORM) THEN
      ASM_REWRITE_TAC[] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
      REWRITE_TAC[VALMOD; ARITH_EQ]; ALL_TAC] THEN
    (* component 3 : rel_form 5 7 53 *)
    SUBGOAL_THEN
      `holds D E ((53 |-> (b:A)) ((52 |-> (a:A)) v)) (rel_form 5 7 53) <=>
       erel D E (v 5) (v 7) b`
     ASSUME_TAC THENL
     [MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;
        `(53 |-> (b:A)) ((52 |-> (a:A)) v)`;`5`;`7`;`53`] HOLDS_REL_FORM) THEN
      ASM_REWRITE_TAC[] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
      REWRITE_TAC[VALMOD; ARITH_EQ]; ALL_TAC] THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  REWRITE_TAC[nmemss_form; HOLDS_ALL] THEN
  USE_THEN "body" (fun th -> SIMP_TAC[th]) THEN
  MESON_TAC[]);;

(* ---------------------------------------------------------------------------
   L5b  NMEMSS_INDUCT : the omega-induction itself (abstract BASE/STEP).
   ------------------------------------------------------------------------- *)

let NMEMSS_INDUCT = prove
 (`!D (E:A->A->bool) B leq onebee om ss c0.
      (!emp vemp zn.
          eempty D E emp /\ echeck D E onebee emp vemp /\
          zn IN D /\ ebv_in D E B leq vemp ss zn
          ==> erel D E leq c0 zn) /\
      (!c sc cv scv zc zsc.
          c IN D /\ sc IN D /\ E c om /\ esuc D E c sc /\
          echeck D E onebee c cv /\ echeck D E onebee sc scv /\
          zc IN D /\ ebv_in D E B leq cv ss zc /\
          zsc IN D /\ ebv_in D E B leq scv ss zsc /\
          erel D E leq c0 zc
          ==> erel D E leq c0 zsc) /\
      model D E ZF_AX /\ (!u. u IN D ==> elmem D E u) /\
      ecba D E B leq /\ B IN D /\ leq IN D /\
      onebee IN D /\ E onebee B /\ eomega D E om /\
      ss IN D /\ bname D E B ss /\ c0 IN D
      ==> !n. n IN D /\ E n om
              ==> !nch zn. nch IN D /\ zn IN D
                           ==> echeck D E onebee n nch /\
                               ebv_in D E B leq nch ss zn
                           ==> erel D E leq c0 zn`,
  REPEAT GEN_TAC THEN
  DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "base")
             (CONJUNCTS_THEN2 (LABEL_TAC "step")
              (CONJUNCTS_THEN2 (LABEL_TAC "mdl")
               (REPEAT_TCL CONJUNCTS_THEN ASSUME_TAC)))) THEN
  (* base valuation w *)
  SUBGOAL_THEN `?w:num->A. valuation D w` (X_CHOOSE_TAC `w:num->A`) THENL
   [MATCH_MP_TAC VALUATION_EXISTS THEN
    USE_THEN "mdl" (MP_TAC o REWRITE_RULE[model]) THEN SIMP_TAC[];
    ALL_TAC] THEN
  (* pv : parameter valuation, slots 1:=onebee 2:=B 5:=leq 6:=ss 7:=c0 *)
  ABBREV_TAC
    `pv = (7 |-> (c0:A)) ((6 |-> (ss:A)) ((5 |-> (leq:A))
            ((2 |-> (B:A)) ((1 |-> (onebee:A)) (w:num->A)))))` THEN
  SUBGOAL_THEN
    `(pv:num->A) 1 = onebee /\ pv 2 = B /\ pv 5 = leq /\
     pv 6 = ss /\ pv 7 = c0`
    (LABEL_TAC "slots") THENL
   [EXPAND_TAC "pv" THEN REWRITE_TAC[VALMOD; ARITH_EQ]; ALL_TAC] THEN
  SUBGOAL_THEN `valuation D (pv:num->A)` (LABEL_TAC "valpv") THENL
   [EXPAND_TAC "pv" THEN ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
  (* hv : meaning of nmemss_form under (0|->m)pv *)
  SUBGOAL_THEN
    `!m:A. m IN D
           ==> (holds D E ((0 |-> m) (pv:num->A)) nmemss_form <=>
                (!nch zn. nch IN D /\ zn IN D
                          ==> echeck D E onebee m nch /\
                              ebv_in D E B leq nch ss zn
                          ==> erel D E leq c0 zn))`
    (LABEL_TAC "hv") THENL
   [GEN_TAC THEN DISCH_TAC THEN
    MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`(0 |-> (m:A)) (pv:num->A)`]
      HOLDS_NMEMSS_FORM) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[] THEN MATCH_MP_TAC VALUATION_VALMOD THEN
      ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    REWRITE_TAC[VALMOD; ARITH_EQ] THEN
    USE_THEN "slots" (fun th -> REWRITE_TAC(CONJUNCTS th)); ALL_TAC] THEN
  (* the internal omega induction *)
  MP_TAC(ISPECL
   [`D:A->bool`;`E:A->A->bool`;`om:A`;`nmemss_form`;`0`;`pv:num->A`]
     EOMEGA_INDUCT) THEN
  ANTS_TAC THENL
   [REPEAT CONJ_TAC THENL
     [FIRST_ASSUM ACCEPT_TAC;
      FIRST_ASSUM ACCEPT_TAC;
      FIRST_ASSUM ACCEPT_TAC;
      (* ===== base ===== *)
      X_GEN_TAC `e:A` THEN DISCH_TAC THEN
      USE_THEN "hv" (MP_TAC o SPEC `e:A`) THEN
      ANTS_TAC THENL [ASM_MESON_TAC[EEMPTY_IN]; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
      MAP_EVERY X_GEN_TAC [`nch:A`;`zn:A`] THEN
      DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "nchD") (LABEL_TAC "znD")) THEN
      DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "nchck") (LABEL_TAC "znin")) THEN
      USE_THEN "base" (MP_TAC o SPECL [`e:A`;`nch:A`;`zn:A`]) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC];
      (* ===== step ===== *)
      MAP_EVERY X_GEN_TAC [`u:A`;`s:A`] THEN
      INTRO_TAC "uD uom ih suc" THEN
      SUBGOAL_THEN `(s:A) IN D` (LABEL_TAC "sD") THENL
       [ASM_MESON_TAC[ESUC_IN]; ALL_TAC] THEN
      USE_THEN "hv" (MP_TAC o SPEC `u:A`) THEN
      ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
      DISCH_THEN(fun hvu -> USE_THEN "ih"
                 (LABEL_TAC "ihv" o REWRITE_RULE[hvu])) THEN
      USE_THEN "hv" (MP_TAC o SPEC `s:A`) THEN
      ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
      MAP_EVERY X_GEN_TAC [`sch:A`;`zsn:A`] THEN
      DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "schD") (LABEL_TAC "zsnD")) THEN
      DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "schck") (LABEL_TAC "zsnin")) THEN
      (* cv = check of u *)
      SUBGOAL_THEN `?cv:A. echeck D E onebee u cv` (X_CHOOSE_TAC `cv:A`) THENL
       [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`onebee:A`;`u:A`]
          ECHECK_EXHAUSTION) THEN REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
        ALL_TAC] THEN
      SUBGOAL_THEN `(cv:A) IN D` (LABEL_TAC "cvD") THENL
       [ASM_MESON_TAC[ECHECK_IMP]; ALL_TAC] THEN
      SUBGOAL_THEN `bname D (E:A->A->bool) B cv` (LABEL_TAC "cvbn") THENL
       [MATCH_MP_TAC(ISPECL
                     [`D:A->bool`;`E:A->A->bool`;`onebee:A`;`B:A`;`u:A`;`cv:A`]
                     ECHECK_IS_BNAME) THEN REPEAT CONJ_TAC THEN
        FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
      (* zc = [[cv in ss]] *)
      SUBGOAL_THEN `?zc:A. zc IN D /\ E zc B /\ ebv_in D E B leq cv ss zc`
        (X_CHOOSE_THEN `zc:A` STRIP_ASSUME_TAC) THENL
       [MATCH_MP_TAC(ISPECL
                     [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`cv:A`;`ss:A`]
                     EBV_IN_VAL_EXISTS) THEN REPEAT CONJ_TAC THEN
        FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
      (* erel c0 zc via the IH *)
      SUBGOAL_THEN `erel D (E:A->A->bool) leq c0 zc` (LABEL_TAC "c0zc") THENL
       [USE_THEN "ihv" (MP_TAC o SPECL [`cv:A`;`zc:A`]) THEN
        ANTS_TAC THENL
         [ASM_REWRITE_TAC[];
          DISCH_THEN MATCH_MP_TAC THEN ASM_REWRITE_TAC[]]; ALL_TAC] THEN
      (* apply STEP *)
      USE_THEN "step" (MP_TAC o
        SPECL [`u:A`;`s:A`;`cv:A`;`sch:A`;`zc:A`;`zsn:A`]) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC]];
    (* ===== conclusion : specialize at n ===== *)
    DISCH_THEN(LABEL_TAC "ind") THEN
    X_GEN_TAC `n:A` THEN
    DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "nD") (LABEL_TAC "nom")) THEN
    USE_THEN "ind" (MP_TAC o SPEC `n:A`) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    USE_THEN "hv" (MP_TAC o SPEC `n:A`) THEN
    ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN SUBST1_TAC THEN DISCH_THEN ACCEPT_TAC]);;

(* ============================================================================
   (A1) lemma a -- INDUCTIVE_FORM_CHECK_TOP : [[ inductive_form 0 ]]_v = top
   when v 0 = vom = om^ (check of the ground omega).  inductive_form 0 unfolds
   (after NUM_REDUCE) to EXACTLY (empty-clause) && (succ-clause) that
   BVALF_INF_EMPTY and BVALF_INF_SUCC prove = top.  So this is a
   pure reuse: BVALF_AND_TOP + the two INF lemmas.
   ========================================================================= *)

let INDUCTIVE_FORM_CHECK_TOP = prove
 (`!D (E:A->A->bool) B leq onebee om vom v.
      model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
      onebee IN D /\ E onebee B /\ etop D E B leq onebee /\
      (!u. u IN D ==> elmem D E u) /\
      eomega D E om /\ echeck D E onebee om vom /\
      valuation D v /\ (!i. bname D E B (v i)) /\ v 0 = vom
      ==> etop D E B leq (bvalf D E B leq v (inductive_form 0))`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  REWRITE_TAC[inductive_form; empty_form; suc_form] THEN
  CONV_TAC NUM_REDUCE_CONV THEN
  MP_TAC(ISPECL [`??- 1 0 (!! 2 (Not(2 %% 1)))`;
    `!!- 1 0 (??- 2 0 (!! 3 ((3 %% 2) <-> (3 %% 1) || Eq 3 1)))`;
    `D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`v:num->A`] BVALF_AND_TOP) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  CONJ_TAC THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`onebee:A`;
      `om:A`;`vom:A`;`v:num->A`] BVALF_INF_EMPTY) THEN ASM_REWRITE_TAC[];
    MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`onebee:A`;
      `om:A`;`vom:A`;`v:num->A`] BVALF_INF_SUCC) THEN ASM_REWRITE_TAC[]]);;

(* ############################################################################
   L6  BVALF_OMEGA_LEAST_IND  =  (A1b) :
     [[ !! 1 (inductive_form 1 --> subset_form 0 1) ]]_{0:=vom}  =  top,
   i.e. om^ is a (Boolean-)subset of every (Boolean-)inductive ss.

   Peel the leading !! 1 (BVALF_ALL_TOP) : for every bname ss,
     [[ inductive_form 1 --> subset_form 0 1 ]]_{1:=ss} = top,
   i.e. (BVALF_IMP_TOP)  c0 := [[inductive_form 1]]_{1:=ss}  <=
     [[subset_form 0 1]].
   [[subset_form 0 1]] = esubval ss vom = [[ vom SUBSET ss ]]
     (SUBSETFORM_VAL).
   ESUBVAL_GREATEST reduces  c0 <= esubval ss vom  to  c0 <= c  for every
   subset-combiner c = (vom(vv) IMP [[vv in ss]]).  By ECHECK_DOM every such vv
   is a check  y^  (y IN om) with vom(y^) = onebee = top, so (EBIMP_TOP_ANT)
   c = [[y^ in ss]].  The per-n bound  c0 <= [[y^ in ss]]  is exactly
   NMEMSS_INDUCT (BASE from L2 INDUCTIVE_LE_EMPTYMEM, STEP from L4
   INDUCTIVE_LE_SUCMEM), instantiated at c0 := [[inductive_form 1]]_{1:=ss}.
   ######################################################################### *)

let BVALF_OMEGA_LEAST_IND = prove
 (`!D (E:A->A->bool) B leq onebee om vom v.
      model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
      onebee IN D /\ E onebee B /\ etop D E B leq onebee /\
      (!u. u IN D ==> elmem D E u) /\
      eomega D E om /\ echeck D E onebee om vom /\
      valuation D v /\ (!i. bname D E B (v i)) /\ v 0 = vom
      ==> etop D E B leq
            (bvalf D E B leq v (!! 1 (inductive_form 1 --> subset_form 0 1)))`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  (* om, vom in D ; bname vom *)
  SUBGOAL_THEN `(om:A) IN D /\ (vom:A) IN D` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[ECHECK_IMP]; ALL_TAC] THEN
  SUBGOAL_THEN `bname D (E:A->A->bool) B vom` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`onebee:A`;`B:A`;`om:A`;`vom:A`]
                 ECHECK_IS_BNAME) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* peel !! 1 : reduce to  !ss. bname ss ==> etop [[ind 1 --> sub 0 *)
  (* 1]]_{1:=ss} *)
  MP_TAC(ISPECL [`1`;`inductive_form 1 --> subset_form 0 1`;
    `D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`v:num->A`] BVALF_ALL_TOP) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  X_GEN_TAC `ss:A` THEN STRIP_TAC THEN
  (* w1 = (1|->ss)v : valuation + bnames *)
  SUBGOAL_THEN `valuation D ((1 |-> (ss:A)) v) /\
                (!i. bname D E B (((1 |-> (ss:A)) v) i))`
  STRIP_ASSUME_TAC THENL
   [CONJ_TAC THENL
     [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[];
      MATCH_MP_TAC BNAMEVAL_VALMOD THEN ASM_REWRITE_TAC[]]; ALL_TAC] THEN
  (* w1 slots : w1 0 = vom, w1 1 = ss *)
  SUBGOAL_THEN `((1 |-> (ss:A)) v) 0 = vom /\ ((1 |-> (ss:A)) v) 1 = ss`
  STRIP_ASSUME_TAC THENL
   [REWRITE_TAC[VALMOD; ARITH_EQ] THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* convert the --> top to an erel (BVALF_IMP_TOP) *)
  MP_TAC(ISPECL [`inductive_form 1`;`subset_form 0 1`;
    `D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`(1 |-> (ss:A)) v`]
       BVALF_IMP_TOP) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  (* c0 = [[inductive_form 1]]_{w1} : in D, in B *)
  SUBGOAL_THEN
    `(bvalf D (E:A->A->bool) B leq ((1 |-> (ss:A)) v)
      (inductive_form 1)) IN D /\
     (E:A->A->bool) (bvalf D E B leq ((1 |-> (ss:A)) v) (inductive_form 1)) B`
  STRIP_ASSUME_TAC THENL
   [CONJ_TAC THENL
     [MP_TAC(ISPECL
             [`inductive_form 1`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
              `(1 |-> (ss:A)) v`] BVALF_SPEC) THEN ASM_SIMP_TAC[];
      MP_TAC(ISPECL
             [`inductive_form 1`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
              `(1 |-> (ss:A)) v`] BVALF_IN_B) THEN ASM_SIMP_TAC[]];
     ALL_TAC] THEN
  (* basef : the BASE hypothesis of NMEMSS_INDUCT, from L2 *)
  SUBGOAL_THEN
    `!emp vemp zn.
         eempty D E emp /\ echeck D E onebee emp vemp /\
         zn IN D /\ ebv_in D E B leq vemp ss zn
         ==> erel D E leq
               (bvalf D E B leq ((1 |-> (ss:A)) v) (inductive_form 1)) zn`
  (LABEL_TAC "basef") THENL
   [MAP_EVERY X_GEN_TAC [`emp:A`;`vemp:A`;`zn:A`] THEN STRIP_TAC THEN
    MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`onebee:A`;`emp:A`;
                  `vemp:A`;`(1 |-> (ss:A)) v`;`1`;`ss:A`;`zn:A`]
                   INDUCTIVE_LE_EMPTYMEM) THEN
    ASM_REWRITE_TAC[] THEN
    FIRST_ASSUM(ACCEPT_TAC o CONJUNCT2 o REWRITE_RULE[eempty]); ALL_TAC] THEN
  (* stepf : the STEP hypothesis of NMEMSS_INDUCT, from L4 *)
  SUBGOAL_THEN
    `!c sc cv scv zc zsc.
         c IN D /\ sc IN D /\ E c om /\ esuc D E c sc /\
         echeck D E onebee c cv /\ echeck D E onebee sc scv /\
         zc IN D /\ ebv_in D E B leq cv ss zc /\
         zsc IN D /\ ebv_in D E B leq scv ss zsc /\
         erel D E leq
           (bvalf D E B leq ((1 |-> (ss:A)) v) (inductive_form 1)) zc
         ==> erel D E leq
               (bvalf D E B leq ((1 |-> (ss:A)) v) (inductive_form 1)) zsc`
  (LABEL_TAC "stepf") THENL
   [MAP_EVERY X_GEN_TAC [`c:A`;`sc:A`;`cv:A`;`scv:A`;`zc:A`;`zsc:A`] THEN
    STRIP_TAC THEN
    MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`onebee:A`;
                  `c:A`;`sc:A`;
                  `cv:A`;`scv:A`;`(1 |-> (ss:A)) v`;`1`;`ss:A`;`zc:A`;`zsc:A`]
                   INDUCTIVE_LE_SUCMEM) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* key : the omega-induction conclusion from NMEMSS_INDUCT *)
  MP_TAC(ISPECL
         [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`onebee:A`;`om:A`;`ss:A`;
          `bvalf D (E:A->A->bool) B leq ((1 |-> (ss:A)) v) (inductive_form 1)`]
           NMEMSS_INDUCT) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(LABEL_TAC "key") THEN
  (* subset value zr = esubval ss vom = [[subset_form 0 1]]_{w1} *)
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`ss:A`;`vom:A`]
    ESUBVAL_EXISTS) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_TAC `zr:A`) THEN
  SUBGOAL_THEN `(zr:A) IN D /\ (E:A->A->bool) zr B` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[ESUBVAL_IN]; ALL_TAC] THEN
  SUBGOAL_THEN
    `bvalf D (E:A->A->bool) B leq ((1 |-> (ss:A)) v) (subset_form 0 1) = zr`
  SUBST1_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`(1 |-> (ss:A)) v`;
                  `0`;`1`;`vom:A`;`ss:A`;`zr:A`] SUBSETFORM_VAL) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* ESUBVAL_GREATEST : reduce to per-combiner  c0 <= c *)
  MATCH_MP_TAC(ISPECL
               [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`ss:A`;`vom:A`;`zr:A`;
                `bvalf D (E:A->A->bool) B leq ((1 |-> (ss:A)) v)
                 (inductive_form 1)`]
    ESUBVAL_GREATEST) THEN
  ASM_REWRITE_TAC[] THEN
  (* per subset-combiner c : esubcomb ss vom c ==> c0 <= c *)
  X_GEN_TAC `cc:A` THEN REWRITE_TAC[esubcomb] THEN
  DISCH_THEN(X_CHOOSE_THEN `vv:A` (X_CHOOSE_THEN `qv:A`
    (X_CHOOSE_THEN `z2:A` STRIP_ASSUME_TAC))) THEN
  (* vv is a check  y^  (y IN om), qv = onebee  (ECHECK_DOM) *)
  MP_TAC(ISPECL
         [`D:A->bool`;`E:A->A->bool`;`onebee:A`;`om:A`;`vom:A`;`vv:A`;`qv:A`]
         ECHECK_DOM) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `y:A` (CONJUNCTS_THEN2 (LABEL_TAC "yom")
    (CONJUNCTS_THEN2 (LABEL_TAC "ycheck") SUBST_ALL_TAC))) THEN
  SUBGOAL_THEN `(y:A) IN D` (LABEL_TAC "yD") THENL
   [ASM_MESON_TAC[ECHECK_IMP]; ALL_TAC] THEN
  (* z2 in B ; ebalg ; c = z2  (EBIMP_TOP_ANT, onebee = top) *)
  SUBGOAL_THEN `(E:A->A->bool) z2 B` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`vv:A`;
                  `ss:A`;`z2:A`]
                 EBV_IN_IN_B) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `ebalg D (E:A->A->bool) B leq` ASSUME_TAC THENL
   [ASM_MESON_TAC[ECBA_IMP_BALG]; ALL_TAC] THEN
  SUBGOAL_THEN `(cc:A) = z2` SUBST1_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`onebee:A`;
                  `z2:A`;`cc:A`]
                 EBIMP_TOP_ANT) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* finish : c0 <= z2 = [[vv in ss]] = [[y^ in ss]]  via key at y, vv, z2 *)
  USE_THEN "key" (MP_TAC o SPEC `y:A`) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(MP_TAC o SPECL [`vv:A`;`z2:A`]) THEN
  ASM_REWRITE_TAC[]);;

(* ############################################################################
   (A1)  BVALF_OMEGA_FORM_CHECK_TOP : [[ omega_form 0 ]]_{0:=vom} = top.
     omega_form 0 = inductive_form 0 && !! 1 (inductive_form 1 -->
       subset_form 0 1)
   so (BVALF_AND_TOP) its value is top iff BOTH conjuncts are top:
     - inductive_form 0 : A1a  INDUCTIVE_FORM_CHECK_TOP
     - !! 1 (ind 1 --> sub 0 1) : A1b  BVALF_OMEGA_LEAST_IND
   i.e. om^ is (Boolean-)inductive and a subset of every inductive set, so om^
   is a (Boolean-)omega.
   ######################################################################### *)

let BVALF_OMEGA_FORM_CHECK_TOP = prove
 (`!D (E:A->A->bool) B leq onebee om vom v.
      model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
      onebee IN D /\ E onebee B /\ etop D E B leq onebee /\
      (!u. u IN D ==> elmem D E u) /\
      eomega D E om /\ echeck D E onebee om vom /\
      valuation D v /\ (!i. bname D E B (v i)) /\ v 0 = vom
      ==> etop D E B leq (bvalf D E B leq v (omega_form 0))`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  REWRITE_TAC[omega_form] THEN
  REWRITE_TAC[ARITH_RULE `0 + 1 = 1`] THEN
  MP_TAC(ISPECL [`inductive_form 0`;
    `!! 1 (inductive_form 1 --> subset_form 0 1)`;
    `D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`v:num->A`] BVALF_AND_TOP) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  CONJ_TAC THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`onebee:A`;
      `om:A`;`vom:A`;`v:num->A`] INDUCTIVE_FORM_CHECK_TOP) THEN
      ASM_REWRITE_TAC[];
      MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`onebee:A`;
      `om:A`;`vom:A`;`v:num->A`] BVALF_OMEGA_LEAST_IND) THEN
      ASM_REWRITE_TAC[]]);;

(* ===================================================================== *)
(* B6: part (B) of CH_CORE  --  [[bijform 1 2]] = bot                    *)
(*                                                                       *)
(* B3 ladder (SVh side): SV-apply bounds, Kuratowski projections, the     *)
(* STEP-7 coverage/real diagonal, and the SVH_MAIN capstone.             *)
(* B4 ladder (ONTOh side): apply/check bounds, sup/per-alpha/outer, and    *)
(* the ONTOH_MAIN capstone.  B5: combine via OMEGA2_NOT_COLLAPSED.        *)
(* ===================================================================== *)

(* =======================================================================
   BVALF_APPLY_GE   -- the GE twin of BVALF_APPLY_LE.

   Member-weight lower bound on an apply-form value:
       mvop  <=  [[ apply_form i j k ]]_v0
   where op is the V^B-Kuratowski pair name of < v0 j , v0 k > (top weights,
   exhaustivity) and mvop = [[ op IN (v0 i) ]] = ebv_in op (v0 i) mvop.

   Needed by Gap 3: after peeling SVf = !!4!!5!!6((apply 3 4 5 && apply 3 4 6)
   --> Eq 5 6) and residuating, we must push the two f-membership weights w_a,
   w_a' INTO the apply antecedents -- i.e. w <= [[apply]].
   (BVALF_APPLY_LE is the OTHER direction, [[apply]] <= w, so it does
   not serve here.)

   Generic over slots i,j,k; binder n := MAX(MAX i j)k+1 (apply_form's own).
   For (i,j,k)=(3,4,5) n=6; for (3,4,6) n=7.  All binder-vs-slot disequalities
   are ARITH truths (n > i,j,k), so one lemma covers both apply-form instances.

   TEMPLATE: BVALF_PMEM_GE (same `?? n (mem && opair)` shape, concrete
   slots 70/71/72/73, conjunction order flipped).  Proof is a faithful mirror.
   ======================================================================= *)

let BVALF_APPLY_GE = prove
 (`!D (E:A->A->bool) B leq (v0:num->A) i j k s p op top mvop.
      model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
      valuation D v0 /\ (!m. bname D E B (v0 m)) /\
      top IN D /\ etop D E B leq top /\
      s IN D /\ bname D E B s /\ p IN D /\ bname D E B p /\
      op IN D /\ bname D E B op /\
      eapply D E s (v0 j) top /\
      (!t q. t IN D /\ q IN D /\ eapply D E s t q ==> t = v0 j \/ t = v0 j) /\
      eapply D E p (v0 j) top /\ eapply D E p (v0 k) top /\
      (!t q. t IN D /\ q IN D /\ eapply D E p t q ==> t = v0 j \/ t = v0 k) /\
      eapply D E op s top /\ eapply D E op p top /\
      (!t q. t IN D /\ q IN D /\ eapply D E op t q ==> t = s \/ t = p) /\
      mvop IN D /\ ebv_in D E B leq op (v0 i) mvop
      ==> erel D E leq mvop
            (bvalf D E B leq v0 (apply_form i j k))`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `eporder D (E:A->A->bool) B leq` ASSUME_TAC THENL
   [ASM_MESON_TAC[ECBA_IMP_BALG; EBALG_IMP_PORDER]; ALL_TAC] THEN
  SUBGOAL_THEN `!x. (v0:num->A) x IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[valuation]; ALL_TAC] THEN
  REWRITE_TAC[apply_form] THEN
  ABBREV_TAC `n = MAX (MAX i j) k + 1` THEN
  SUBGOAL_THEN
   `~((i:num) = n) /\ ~((j:num) = n) /\ ~((k:num) = n) /\
    ~((n:num) = i) /\ ~((n:num) = j) /\ ~((n:num) = k)`
    STRIP_ASSUME_TAC THENL [EXPAND_TAC "n" THEN ARITH_TAC; ALL_TAC] THEN
  SUBGOAL_THEN
   `valuation D (((n:num) |-> op) (v0:num->A)) /\
    (!m. bname D E B ((((n:num) |-> op) (v0:num->A)) m))`
  STRIP_ASSUME_TAC THENL
   [CONJ_TAC THENL
     [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[];
      MATCH_MP_TAC BNAMEVAL_VALMOD THEN ASM_REWRITE_TAC[]]; ALL_TAC] THEN
  ABBREV_TAC `vp = ((n:num) |-> op) (v0:num->A)` THEN
  SUBGOAL_THEN
   `(vp:num->A) i = v0 i /\ vp j = v0 j /\ vp k = v0 k /\ vp (n:num) = op`
  STRIP_ASSUME_TAC THENL
   [EXPAND_TAC "vp" THEN ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER; ARITH_EQ];
    ALL_TAC] THEN
  (* X := [[opair_form j k n]]_vp is top *)
  SUBGOAL_THEN
   `etop D (E:A->A->bool) B leq
    (bvalf D E B leq (vp:num->A) (opair_form j k n))`
  ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`vp:num->A`;
      `j:num`;`k:num`;`n:num`;`s:A`;`p:A`;`top:A`] BVALF_OPAIRFORM_TOP) THEN
    ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[]; ALL_TAC] THEN
  (* Y := [[n%%i]]_vp = mvop *)
  SUBGOAL_THEN `bvalf D (E:A->A->bool) B leq (vp:num->A) (n %% i) = mvop`
  ASSUME_TAC THENL
   [MP_TAC(ISPECL
           [`n:num`;`i:num`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
            `vp:num->A`]
           BVALF_MEM) THEN ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    ASM_REWRITE_TAC[] THEN DISCH_TAC THEN
    MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`op:A`;
      `(v0:num->A) i`;
      `bvalf D (E:A->A->bool) B leq (vp:num->A) (n %% i)`;`mvop:A`]
             EBV_IN_UNIQUE) THEN
    ASM_REWRITE_TAC[] THEN
    MP_TAC(ISPECL
           [`n %% i`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`vp:num->A`]
           BVALF_SPEC) THEN ASM_SIMP_TAC[]; ALL_TAC] THEN
  (* Z := [[(n%%i) && opair]]_vp = mvop *)
  SUBGOAL_THEN
   `bvalf D (E:A->A->bool) B leq (vp:num->A)
    ((n %% i) && opair_form j k n) = mvop`
  ASSUME_TAC THENL
   [MP_TAC(ISPECL [`n %% i`;`opair_form j k n`;`D:A->bool`;`E:A->A->bool`;
      `B:A`;`leq:A`;`vp:num->A`] BVALF_AND_MEET) THEN
    ASM_REWRITE_TAC[] THEN
    ABBREV_TAC
      `X = bvalf D (E:A->A->bool) B leq (vp:num->A) (opair_form j k n)` THEN
      ABBREV_TAC
        `Z = bvalf D (E:A->A->bool) B leq (vp:num->A)
         ((n %% i) && opair_form j k n)` THEN
    DISCH_TAC THEN
    SUBGOAL_THEN `(E:A->A->bool) (mvop:A) B` ASSUME_TAC THENL
     [ASM_MESON_TAC[EBV_IN_IN_B]; ALL_TAC] THEN
    ASM_MESON_TAC[EMEET_TOP; EMEET_SYM; EMEET_UNIQUE; EMEET_IN]; ALL_TAC] THEN
  MP_TAC(ISPECL [`n:num`; `(n %% i) && opair_form j k n`;
    `D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`v0:num->A`;`op:A`]
      BVALF_EX_UB) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  EXPAND_TAC "vp" THEN ASM_REWRITE_TAC[]);;

(* =======================================================================
   COV_INVERT  (B3 STEP-7 coverage: member inversion)

   From `eapply h y qy` and the HNAME membership-iff (hchar, g:=f), recover
   the member structure of y as an h-cell:
     y = cpc = <xi,alpha>^   (echeck onebee cp y, cp = <xi,alpha>)
     qy = w = [[ op IN f ]]   (ebv_in op f qy, op = opn-name <xic,rdot>)
   via eapply-def + hchar@p + EOPAIR_INJ (y,qy vs cpc,w share the pair p).
   ======================================================================= *)

let COV_INVERT = prove
 (`!D (E:A->A->bool) B leq onebee realfn f a1 a2 cr h y qy.
     model D E ZF_AX /\
     B IN D /\ leq IN D /\ onebee IN D /\
     realfn IN D /\ f IN D /\ a1 IN D /\ a2 IN D /\ cr IN D /\ h IN D /\
     (!zz. zz IN D ==>
          (E zz h <=>
           ?cp xi alpha xic rdot op w cpc.
                cp IN D /\ xi IN D /\ alpha IN D /\ xic IN D /\
                rdot IN D /\ op IN D /\ w IN D /\ cpc IN D /\
                (E:A->A->bool) cp cr /\
                eopair D E xi alpha cp /\ E xi a1 /\ E alpha a2 /\
                echeck D E onebee xi xic /\ eapply D E realfn alpha rdot /\
                (?paa pab sa sab psa psab.
                     paa IN D /\ pab IN D /\ sa IN D /\ sab IN D /\
                     psa IN D /\ psab IN D /\
                     eopair D E xic onebee paa /\ eopair D E rdot onebee pab /\
                     epair D E paa paa sa /\ epair D E paa pab sab /\
                     eopair D E sa onebee psa /\ eopair D E sab onebee psab /\
                     epair D E psa psab op) /\
                ebv_in D E B leq op f w /\
                echeck D E onebee cp cpc /\ eopair D E cpc w zz)) /\
     y IN D /\ qy IN D /\ eapply D E h y qy
     ==> ?cp xi alpha xic rdot op paa pab sa sab psa psab.
             cp IN D /\ xi IN D /\ alpha IN D /\ xic IN D /\
             rdot IN D /\ op IN D /\
             paa IN D /\ pab IN D /\ sa IN D /\ sab IN D /\
             psa IN D /\ psab IN D /\
             (E:A->A->bool) cp cr /\
             eopair D E xi alpha cp /\ E xi a1 /\ E alpha a2 /\
             echeck D E onebee xi xic /\ eapply D E realfn alpha rdot /\
             eopair D E xic onebee paa /\ eopair D E rdot onebee pab /\
             epair D E paa paa sa /\ epair D E paa pab sab /\
             eopair D E sa onebee psa /\ eopair D E sab onebee psab /\
             epair D E psa psab op /\
             ebv_in D E B leq op f qy /\
             echeck D E onebee cp y`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  FIRST_X_ASSUM(LABEL_TAC "hchar" o
     check (fun th -> is_forall(concl th) && vfree_in `h:A` (concl th) &&
                      vfree_in `cr:A` (concl th))) THEN
  (* unfold eapply h y qy -> pair p *)
  UNDISCH_TAC `eapply D (E:A->A->bool) h y qy` THEN
  GEN_REWRITE_TAC LAND_CONV [eapply] THEN
  DISCH_THEN(X_CHOOSE_THEN `p:A` STRIP_ASSUME_TAC) THEN
  (* instantiate hchar at p, extract the RHS structure *)
  SUBGOAL_THEN `(p:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[EOPAIR_IN]; ALL_TAC] THEN
  USE_THEN "hchar" (fun hc ->
    MP_TAC(EQ_MP (MP (SPEC `p:A` hc) (ASSUME `(p:A) IN D`))
                 (ASSUME `(E:A->A->bool) p h`))) THEN
  DISCH_THEN(X_CHOOSE_THEN `cp:A`
             (X_CHOOSE_THEN `xi:A` (X_CHOOSE_THEN `alpha:A`
                                    (X_CHOOSE_THEN `xic:A`
                                     (X_CHOOSE_THEN `rdot:A`
                                      (X_CHOOSE_THEN `op:A`
                                       (X_CHOOSE_THEN `w:A`
                                        (X_CHOOSE_THEN `cpc:A`
                                         STRIP_ASSUME_TAC)))))))) THEN
  (* EOPAIR_INJ:  y=cpc, qy=w  (shared pair p) *)
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`y:A`;`qy:A`;`cpc:A`;`w:A`;`p:A`]
     EOPAIR_INJ) THEN
  ANTS_TAC THENL
   [REPEAT CONJ_TAC THEN
    (FIRST_ASSUM ACCEPT_TAC ORELSE FIRST_ASSUM MATCH_ACCEPT_TAC);
    ALL_TAC] THEN
  STRIP_TAC THEN
  MAP_EVERY EXISTS_TAC
   [`cp:A`;`xi:A`;`alpha:A`;`xic:A`;`rdot:A`;`op:A`;
    `paa:A`;`pab:A`;`sa:A`;`sab:A`;`psa:A`;`psab:A`] THEN
  ASM_REWRITE_TAC[]);;

(* =======================================================================
   BVALF_SVF_INCOMPAT

   f-single-valuedness, pushed below the forcing condition cf, forces the two
   second-coordinates equal:

     cf <= [[SVf]]_wf   (SVf = f is single-valued, as a sub-formula of bijform)
     wa = [[ <xi^,rda> IN f ]] = ebv_in opa f wa    (opa =
       Kuratowski <xic,rda>)
     wb = [[ <xi^,rdb> IN f ]] = ebv_in opb f wb    (opb =
       Kuratowski <xic,rdb>)
     ==>  anything d below cf, wa, wb is below [[rda = rdb]] (= eqv).

   At the call site COHEN_REAL_DISTINCT collapses eqv = [[rda=rdb]] to bot
   (when the two reals are distinct), so d <= bot -- exactly the OFF-DIAGONAL
   `?z. emeet cc s z /\ ebot z` disjunct of the STEP-7 coverage.

   SVf (from bijform 1 2, M=MAX 1 2=2, slots 3=f,4=arg,5/6=values):
     !! 4 (!! 5 (!! 6 ((apply_form 3 4 5 && apply_form 3 4 6) --> Eq 5 6))).

   ROUTE: peel !!4,!!5,!!6 at xic,rda,rdb (BVALF_ALL_LB + EPORDER_TRANS);
   recognise the implication value (BVALF_IMP) and the &&
     value (BVALF_AND_MEET);
   residuate (EBIMP_MEET_LE: cf /\ [[app&&app]] <= [[Eq 5 6]]); push wa,wb into
   the two apply antecedents (BVALF_APPLY_GE, the GE twin built just now);
   identify [[Eq 5 6]] = eqv (BVALF_EQ2 + EBV_EQ_UNIQUE).  Then d<=cf,wa,wb
   gives d<=cf/\[[app&&app]]<=[[Eq 5 6]]=eqv by meet-monotonicity.

   NB this HOL Light has NO `^` antiquotation -- composite goal terms are built
   with the vsubst helpers below (genuine terms, so MATCH_MP_TAC still peels).

   DISCHARGE DISCIPLINE (v3): the context carries TWO Kuratowski bundles (opa,
   opb) + 6 universally-quantified disjunctive `eapply` exhaustivity clauses.
   A bare ASM_MESON_TAC[] over that context DIVERGES ("solve_goal: Too deep",
   depth counter into the millions -- v2 died here).  So EVERY leaf is closed
   deterministically: CLOSE = FIRST_ASSUM ACCEPT_TAC ORELSE FIRST_ASSUM
   MATCH_ACCEPT_TAC,
   and the projection / EMEET_IN / eqvv=eqv steps are done by explicit MP.
   ======================================================================= *)

let BVALF_SVF_INCOMPAT =
  (* deterministic leaf-closer: an assumption or an instance of one *)
  let CLOSE = FIRST_ASSUM ACCEPT_TAC ORELSE FIRST_ASSUM MATCH_ACCEPT_TAC in
  (* ---- term builders (no antiquotation available) ---- *)
  let vwf   = `wf:num->A` in
  let v4t   = `(4 |-> (xic:A)) (wf:num->A)` in
  let v45t  = `(5 |-> (rda:A)) ((4 |-> (xic:A)) (wf:num->A))` in
  let v6t   = `(6 |-> (rdb:A)) ((5 |-> (rda:A))
               ((4 |-> (xic:A)) (wf:num->A)))` in
  let fsvf  = `!! 4 (!! 5 (!! 6 ((apply_form 3 4 5 && apply_form 3 4 6)
                                --> Eq 5 6)))` in
  let fin56 = `!! 5 (!! 6 ((apply_form 3 4 5 && apply_form 3 4 6)
                           --> Eq 5 6))` in
  let fin6  = `!! 6 ((apply_form 3 4 5 && apply_form 3 4 6) --> Eq 5 6)` in
  let fbody = `(apply_form 3 4 5 && apply_form 3 4 6) --> Eq 5 6` in
  let f345  = `apply_form 3 4 5` in
  let f346  = `apply_form 3 4 6` in
  let fand  = `apply_form 3 4 5 && apply_form 3 4 6` in
  let feq   = `Eq 5 6` in
  let bv v p = vsubst [v,`vv:num->A`; p,`pp:form`]
                 `bvalf D (E:A->A->bool) B leq (vv:num->A) (pp:form)` in
  let svfv    = bv vwf fsvf in
  let in56v   = bv v4t fin56 in
  let in6v    = bv v45t fin6 in
  let body6v  = bv v6t fbody in
  let app345v = bv v6t f345 in
  let app346v = bv v6t f346 in
  let andv    = bv v6t fand in
  let eqvv    = bv v6t feq in
  let erl a b =
    vsubst [a,`e1:A`; b,`e2:A`] `erel D (E:A->A->bool) leq (e1:A) (e2:A)` in
  let einb x  = vsubst [x,`e1:A`] `(E:A->A->bool) (e1:A) B` in
  let emt x y z = vsubst [x,`e1:A`;y,`e2:A`;z,`e3:A`]
                    `emeet D (E:A->A->bool) B leq (e1:A) (e2:A) (e3:A)` in
  let ebi x y z = vsubst [x,`e1:A`;y,`e2:A`;z,`e3:A`]
                    `ebimp D (E:A->A->bool) B leq (e1:A) (e2:A) (e3:A)` in
  let ebq x y z = vsubst [x,`e1:A`;y,`e2:A`;z,`e3:A`]
                    `ebv_eq D (E:A->A->bool) B leq (e1:A) (e2:A) (e3:A)` in
  let valg v  = vsubst [v,`vv:num->A`]
                  `valuation D (vv:num->A) /\
                   (!m. bname D (E:A->A->bool) B ((vv:num->A) m))` in
  let einb8   = end_itlist (fun a b -> mk_conj(a,b))
                  [einb svfv; einb in56v; einb in6v; einb body6v;
                   einb app345v; einb app346v; einb andv; einb eqvv] in
  (* IN-D companions of the einb/einb8 E-in-B helpers, used by the
     `SUBGOAL_THEN einD8` membership-closure block of BVALF_SVF_INCOMPAT. *)
  let einD x  = vsubst [x,`e1:A`] `(e1:A) IN D` in
  let einD8   = end_itlist (fun a b -> mk_conj(a,b))
                  [einD svfv; einD in56v; einD in6v; einD body6v;
                   einD app345v; einD app346v; einD andv; einD eqvv] in
  prove
 (`!D (E:A->A->bool) B leq wf cf f xic rda rdb top
      sa pa opa wa sb pb opb wb eqv d.
     ecba D E B leq /\ model D E ZF_AX /\
     B IN D /\ leq IN D /\
     xic IN D /\ rda IN D /\ rdb IN D /\
     sa IN D /\ pa IN D /\ opa IN D /\
     sb IN D /\ pb IN D /\ opb IN D /\ eqv IN D /\
     valuation D wf /\ (!m. bname D E B (wf m)) /\
     wf 3 = f /\
     bname D E B xic /\ bname D E B rda /\ bname D E B rdb /\
     bname D E B f /\
     top IN D /\ etop D E B leq top /\
     bname D E B sa /\ bname D E B pa /\ bname D E B opa /\
     bname D E B sb /\ bname D E B pb /\ bname D E B opb /\
     eapply D E sa xic top /\
     (!t q. t IN D /\ q IN D /\ eapply D E sa t q ==> t = xic \/ t = xic) /\
     eapply D E pa xic top /\ eapply D E pa rda top /\
     (!t q. t IN D /\ q IN D /\ eapply D E pa t q ==> t = xic \/ t = rda) /\
     eapply D E opa sa top /\ eapply D E opa pa top /\
     (!t q. t IN D /\ q IN D /\ eapply D E opa t q ==> t = sa \/ t = pa) /\
     eapply D E sb xic top /\
     (!t q. t IN D /\ q IN D /\ eapply D E sb t q ==> t = xic \/ t = xic) /\
     eapply D E pb xic top /\ eapply D E pb rdb top /\
     (!t q. t IN D /\ q IN D /\ eapply D E pb t q ==> t = xic \/ t = rdb) /\
     eapply D E opb sb top /\ eapply D E opb pb top /\
     (!t q. t IN D /\ q IN D /\ eapply D E opb t q ==> t = sb \/ t = pb) /\
     ebv_in D E B leq opa f wa /\ ebv_in D E B leq opb f wb /\
     ebv_eq D E B leq rda rdb eqv /\ E eqv B /\
     E cf B /\
     erel D E leq cf
       (bvalf D E B leq wf
          (!! 4 (!! 5
                 (!! 6 ((apply_form 3 4 5 && apply_form 3 4 6) -->
                        Eq 5 6))))) /\
     E d B /\ erel D E leq d cf /\ erel D E leq d wa /\ erel D E leq d wb
     ==> erel D E leq d eqv`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  (* ---- domain-closure facts ---- *)
  MAP_EVERY (fun t -> STRIP_ASSUME_TAC(MATCH_MP EREL_IN (ASSUME t)))
   [erl `d:A` `cf:A`; erl `d:A` `wa:A`; erl `d:A` `wb:A`] THEN
  SUBGOAL_THEN `(f:A) IN D` ASSUME_TAC THENL
   [SUBST1_TAC(SYM(ASSUME `(wf:num->A) 3 = f`)) THEN
    ACCEPT_TAC(SPEC `3` (REWRITE_RULE[valuation]
      (ASSUME `valuation D (wf:num->A)`))); ALL_TAC] THEN
  (* ---- order/algebra projection (explicit, no MESON) ---- *)
  SUBGOAL_THEN `ebalg D (E:A->A->bool) B leq /\ eporder D E B leq`
    STRIP_ASSUME_TAC THENL
   [CONJ_TAC THENL
     [MATCH_MP_TAC ECBA_IMP_BALG THEN FIRST_ASSUM ACCEPT_TAC;
      MATCH_MP_TAC EBALG_IMP_PORDER THEN MATCH_MP_TAC ECBA_IMP_BALG THEN
      FIRST_ASSUM ACCEPT_TAC];
    ALL_TAC] THEN
  (* ---- E wa B, E wb B (membership-weight field, via EBV_IN_IN_B) ---- *)
  SUBGOAL_THEN `(E:A->A->bool) wa B` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
       `opa:A`;`f:A`;`wa:A`] EBV_IN_IN_B) THEN
    REPEAT CONJ_TAC THEN CLOSE; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) wb B` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
       `opb:A`;`f:A`;`wb:A`] EBV_IN_IN_B) THEN
    REPEAT CONJ_TAC THEN CLOSE; ALL_TAC] THEN
  (* ---- valuations v4, v45, v456 ---- *)
  SUBGOAL_THEN (valg v4t) STRIP_ASSUME_TAC THENL
   [CONJ_TAC THENL
     [MATCH_MP_TAC VALUATION_VALMOD THEN CONJ_TAC THEN CLOSE;
      MATCH_MP_TAC BNAMEVAL_VALMOD THEN CONJ_TAC THEN CLOSE]; ALL_TAC] THEN
  SUBGOAL_THEN (valg v45t) STRIP_ASSUME_TAC THENL
   [CONJ_TAC THENL
     [MATCH_MP_TAC VALUATION_VALMOD THEN CONJ_TAC THEN CLOSE;
      MATCH_MP_TAC BNAMEVAL_VALMOD THEN CONJ_TAC THEN CLOSE]; ALL_TAC] THEN
  SUBGOAL_THEN (valg v6t) STRIP_ASSUME_TAC THENL
   [CONJ_TAC THENL
     [MATCH_MP_TAC VALUATION_VALMOD THEN CONJ_TAC THEN CLOSE;
      MATCH_MP_TAC BNAMEVAL_VALMOD THEN CONJ_TAC THEN CLOSE]; ALL_TAC] THEN
  (* ---- slot equations under v456 (LABEL: used by the two BVALF_APPLY_GE
         discharges via a PURE_REWRITE_TAC -- NOT
           ASM_REWRITE/REWRITE.  The s/sb
         exhaustivity conjunct is `t = v0 j \/ t = v0 j` (duplicated disjunct);
         plain REWRITE's basic rewrites collapse `a \/ a` to `a` in the GOAL
         while the matching ASSUMPTION keeps `t = xic \/ t = xic`, so CLOSE's
         ACCEPT fails with tryfind.  PURE_REWRITE[slots] bridges
           v6t-slots WITHOUT
         that collapse) ---- *)
  SUBGOAL_THEN
   (vsubst [v6t,`vv:num->A`]
      `(vv:num->A) 3 = f /\ vv 4 = xic /\ vv 5 = rda /\ vv 6 = rdb`)
    (LABEL_TAC "slots") THENL
   [ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER; ARITH_EQ]; ALL_TAC] THEN
  (* ---- E-in-B of all the bvalf terms we touch ---- *)
  SUBGOAL_THEN einb8 STRIP_ASSUME_TAC THENL
   [REPEAT CONJ_TAC THEN MATCH_MP_TAC BVALF_IN_B THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  (* ---- IN-D of all the bvalf terms we touch ---- *)
  SUBGOAL_THEN einD8 STRIP_ASSUME_TAC THENL
   [REPEAT CONJ_TAC THEN MATCH_MP_TAC BVALF_IND THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  (* ---- peel !!4,!!5,!!6 : three BVALF_ALL_LB facts ---- *)
  SUBGOAL_THEN (erl svfv in56v) ASSUME_TAC THENL
   [MP_TAC(ISPECL [`4`; fin56; `D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
       `wf:num->A`;`xic:A`] BVALF_ALL_LB) THEN
    ANTS_TAC THENL
    [ASM_REWRITE_TAC[] THEN REPEAT CONJ_TAC THEN CLOSE; ALL_TAC] THEN
    DISCH_THEN ACCEPT_TAC; ALL_TAC] THEN
  SUBGOAL_THEN (erl in56v in6v) ASSUME_TAC THENL
   [MP_TAC(ISPECL [`5`; fin6; `D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
       v4t;`rda:A`] BVALF_ALL_LB) THEN
    ANTS_TAC THENL
    [ASM_REWRITE_TAC[] THEN REPEAT CONJ_TAC THEN CLOSE; ALL_TAC] THEN
    DISCH_THEN ACCEPT_TAC; ALL_TAC] THEN
  SUBGOAL_THEN (erl in6v body6v) ASSUME_TAC THENL
   [MP_TAC(ISPECL [`6`; fbody; `D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
       v45t;`rdb:A`] BVALF_ALL_LB) THEN
    ANTS_TAC THENL
    [ASM_REWRITE_TAC[] THEN REPEAT CONJ_TAC THEN CLOSE; ALL_TAC] THEN
    DISCH_THEN ACCEPT_TAC; ALL_TAC] THEN
  (* ---- TRANS tower: cf <= [[body6]]_v456 ---- *)
  SUBGOAL_THEN (erl `cf:A` in56v) ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
       `cf:A`; svfv; in56v] EPORDER_TRANS) THEN
    REPEAT CONJ_TAC THEN CLOSE; ALL_TAC] THEN
  SUBGOAL_THEN (erl `cf:A` in6v) ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
       `cf:A`; in56v; in6v] EPORDER_TRANS) THEN
    REPEAT CONJ_TAC THEN CLOSE; ALL_TAC] THEN
  SUBGOAL_THEN (erl `cf:A` body6v) ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
       `cf:A`; in6v; body6v] EPORDER_TRANS) THEN
    REPEAT CONJ_TAC THEN CLOSE; ALL_TAC] THEN
  (* ---- recognise the && value and the --> value ---- *)
  SUBGOAL_THEN (emt app345v app346v andv) ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL [f345; f346;
       `D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`; v6t] BVALF_AND_MEET) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN (ebi andv eqvv body6v) ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL [fand; feq;
       `D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`; v6t] BVALF_IMP) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* ---- residuate: cf /\ [[app&&app]] <= [[Eq 5 6]] ---- *)
  SUBGOAL_THEN (mk_exists(`cfMA:A`, emt `cf:A` andv `cfMA:A`))
    (X_CHOOSE_TAC `cfMA:A`) THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`cf:A`; andv]
       EBALG_MEET) THEN
    REPEAT CONJ_TAC THEN CLOSE; ALL_TAC] THEN
  SUBGOAL_THEN `(cfMA:A) IN D /\ (E:A->A->bool) cfMA B` STRIP_ASSUME_TAC THENL
   [MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
       `cf:A`; andv; `cfMA:A`] EMEET_IN) THEN
    ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN ACCEPT_TAC; ALL_TAC] THEN
  SUBGOAL_THEN (erl `cfMA:A` eqvv) ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
       `cf:A`; andv; eqvv; body6v; `cfMA:A`] EBIMP_MEET_LE) THEN
    REPEAT CONJ_TAC THEN CLOSE; ALL_TAC] THEN
  (* ---- identify [[Eq 5 6]]_v456 = eqv ---- *)
  SUBGOAL_THEN (ebq `rda:A` `rdb:A` eqvv) ASSUME_TAC THENL
   [MP_TAC(ISPECL [`5`;`6`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`; v6t]
       BVALF_EQ2) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN (mk_eq(eqvv,`eqv:A`)) (LABEL_TAC "eqid") THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`rda:A`;`rdb:A`;
                  eqvv; `eqv:A`] EBV_EQ_UNIQUE) THEN
    REPEAT CONJ_TAC THEN CLOSE; ALL_TAC] THEN
  (* ---- push wa, wb into the apply antecedents (BVALF_APPLY_GE) ---- *)
  SUBGOAL_THEN (erl `wa:A` app345v) ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`; v6t;
       `3`;`4`;`5`;`sa:A`;`pa:A`;`opa:A`;`top:A`;`wa:A`] BVALF_APPLY_GE) THEN
    USE_THEN "slots" (fun th -> PURE_REWRITE_TAC[th]) THEN
    REPEAT CONJ_TAC THEN CLOSE; ALL_TAC] THEN
  SUBGOAL_THEN (erl `wb:A` app346v) ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`; v6t;
       `3`;`4`;`6`;`sb:A`;`pb:A`;`opb:A`;`top:A`;`wb:A`] BVALF_APPLY_GE) THEN
    USE_THEN "slots" (fun th -> PURE_REWRITE_TAC[th]) THEN
    REPEAT CONJ_TAC THEN CLOSE; ALL_TAC] THEN
  (* ---- meet-monotonicity: d <= app345, d <= app346, d <= andv, d <= cfMA *)
  (* ---- *)
  SUBGOAL_THEN (erl `d:A` app345v) ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
       `d:A`;`wa:A`; app345v] EPORDER_TRANS) THEN
    REPEAT CONJ_TAC THEN CLOSE; ALL_TAC] THEN
  SUBGOAL_THEN (erl `d:A` app346v) ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
       `d:A`;`wb:A`; app346v] EPORDER_TRANS) THEN
    REPEAT CONJ_TAC THEN CLOSE; ALL_TAC] THEN
  SUBGOAL_THEN (erl `d:A` andv) ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
       app345v; app346v; andv; `d:A`] EMEET_GREATEST) THEN
    REPEAT CONJ_TAC THEN CLOSE; ALL_TAC] THEN
  SUBGOAL_THEN (erl `d:A` `cfMA:A`) ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
       `cf:A`; andv; `cfMA:A`; `d:A`] EMEET_GREATEST) THEN
    REPEAT CONJ_TAC THEN CLOSE; ALL_TAC] THEN
  (* ---- final: d <= cfMA <= eqvv, then eqvv = eqv ---- *)
  SUBGOAL_THEN (erl `d:A` eqvv) ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
       `d:A`;`cfMA:A`; eqvv] EPORDER_TRANS) THEN
    REPEAT CONJ_TAC THEN CLOSE; ALL_TAC] THEN
  USE_THEN "eqid" (SUBST1_TAC o SYM) THEN FIRST_ASSUM ACCEPT_TAC);;

(* ======================================================================= *)
(* GAP 1  (B3 prerequisite):  Kuratowski pair-equality PROJECTION onto a    *)
(* CHECK-sided codomain.   [[<a,b> = <xi^,al^>]]  <=  [[a=xi^]]  and         *)
(*                                                 <=  [[b=al^]].            *)
(*                                                                           *)
(* L0  EBV_EQ_LE_MEM_TOP : descent atom.  If u = ... has x as a TOP-weighted *)
(*     member (eapply u x top), then  [[u=v]] <= [[x IN v]].                 *)
(*       (residuation collapses because the weight is top: EBIMP_TOP_ANT.)   *)
(* ======================================================================= *)

let EBV_EQ_LE_MEM_TOP = prove
 (`!D (E:A->A->bool) B leq u v z x top exv.
     model D E ZF_AX /\ ecba D E B leq /\ B IN D /\
     u IN D /\ v IN D /\ z IN D /\ x IN D /\ top IN D /\ exv IN D /\
     etop D E B leq top /\
     ebv_eq D E B leq u v z /\ eapply D E u x top /\
     ebv_in D E B leq x v exv
     ==> erel D E leq z exv`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `ebalg D (E:A->A->bool) B leq` ASSUME_TAC THENL
   [ASM_MESON_TAC[ECBA_IMP_BALG]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) top B` ASSUME_TAC THENL
   [ASM_MESON_TAC[ETOP_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) exv B` ASSUME_TAC THENL
   [ASM_MESON_TAC[EBV_IN_IN_B]; ALL_TAC] THEN
  SUBGOAL_THEN `?cc:A. ebimp D (E:A->A->bool) B leq top exv cc`
    (X_CHOOSE_TAC `cc:A`) THENL
   [ASM_MESON_TAC[EBIMP_EXISTS]; ALL_TAC] THEN
  SUBGOAL_THEN `(cc:A) IN D /\ (E:A->A->bool) cc B` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[EBIMP_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq z cc` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`u:A`;`v:A`;
       `z:A`;`x:A`;`top:A`;`exv:A`;`cc:A`] EBV_EQ_LE_TERM_V) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(cc:A) = exv` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`top:A`;
       `exv:A`;`cc:A`] EBIMP_TOP_ANT) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  ASM_MESON_TAC[]);;

(* ----------------------------------------------------------------------- *)
(* L0c  EBV_IN_SING_VAL : a TOP-weighted singleton name s = {c} has         *)
(*   [[w IN s]] = [[w = c]].   (EBV_IN_UPAIR with the two members equal,     *)
(*   then join-idempotence.)                                                 *)
(* ----------------------------------------------------------------------- *)

let EBV_IN_SING_VAL = prove
 (`!D (E:A->A->bool) B leq s c top w win eqv.
     model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
     c IN D /\ top IN D /\ w IN D /\ win IN D /\ eqv IN D /\
     bname D E B c /\ bname D E B w /\ bname D E B s /\ s IN D /\
     etop D E B leq top /\ eapply D E s c top /\
     (!t q. t IN D /\ q IN D /\ eapply D E s t q ==> t = c \/ t = c) /\
     ebv_in D E B leq w s win /\ ebv_eq D E B leq w c eqv
     ==> win = eqv`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `ebalg D (E:A->A->bool) B leq /\ eporder D E B leq`
    STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[ECBA_IMP_BALG; EBALG_IMP_PORDER]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) eqv B` ASSUME_TAC THENL
   [ASM_MESON_TAC[EBV_EQ_IN_B]; ALL_TAC] THEN
  SUBGOAL_THEN `?zj:A. ejoin D (E:A->A->bool) B leq eqv eqv zj`
    (X_CHOOSE_TAC `zj:A`) THENL
   [ASM_MESON_TAC[EBALG_JOIN]; ALL_TAC] THEN
  SUBGOAL_THEN `(zj:A) IN D /\ (E:A->A->bool) zj B` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[EJOIN_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `(win:A) = zj` SUBST_ALL_TAC THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`c:A`;`c:A`;
       `s:A`;`top:A`;`w:A`;`win:A`;`eqv:A`;`eqv:A`;`zj:A`] EBV_IN_UPAIR) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`zj:A`;`eqv:A`]
     EPORDER_ANTISYM) THEN
  ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
   [ASM_MESON_TAC[EJOIN_LEAST; EPORDER_REFL];
    ASM_MESON_TAC[EJOIN_GE]]);;

(* =======================================================================
   OPNCELL_BNAME_BUNDLE   (epair-cell -> bname + eapply-bundle, one step)

   The hname member (COV_INVERT) delivers op as an epair-CELL built from
   xic,rdot over top=onebee:
     paa=<xic,top>, pab=<rdot,top>, sa={paa}, sab={paa,pab},
     psa=<sa,top>, psab=<sab,top>, op={psa,psab}.
   Gap3 (BVALF_SVF_INCOMPAT) needs that op (as opb) to be a B-NAME and to
   come with the eapply-exhaust BUNDLE.  This lemma supplies both at once:
   build the canonical bnamed op0 via EOPAIRNAME_CANON, collapse top0=top,
   recover op0's epair-cell from CANON's membership-iffs, then identify
   op0=op (and sa0=sa, sab0=sab) by the EOPAIR/EPAIR_UNIQUE chain, so
   CANON's bname + bundle transfer to the member's own op/sa/sab.
   Supersedes OPNCELL_BUNDLE (which gave the bundle only, no bnames).
   ======================================================================= *)

let OPNCELL_BNAME_BUNDLE = prove
 (`!D (E:A->A->bool) B leq xic rdot top paa pab sa sab psa psab op.
     model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
     etop D E B leq top /\ top IN D /\
     xic IN D /\ rdot IN D /\ bname D E B xic /\ bname D E B rdot /\
     eopair D E xic top paa /\ eopair D E rdot top pab /\
     epair D E paa paa sa /\ epair D E paa pab sab /\
     eopair D E sa top psa /\ eopair D E sab top psab /\
     epair D E psa psab op
     ==> bname D E B op /\ bname D E B sa /\ bname D E B sab /\
         eapply D E sa xic top /\
         (!t q. t IN D /\ q IN D /\ eapply D E sa t q ==>
          t = xic \/ t = xic) /\
         eapply D E sab xic top /\ eapply D E sab rdot top /\
         (!t q. t IN D /\ q IN D /\ eapply D E sab t q ==> t = xic \/
          t = rdot) /\
         eapply D E op sa top /\ eapply D E op sab top /\
         (!t q. t IN D /\ q IN D /\ eapply D E op t q ==> t = sa \/ t = sab)`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `eporder D (E:A->A->bool) B leq` ASSUME_TAC THENL
   [ASM_MESON_TAC[ECBA_IMP_PORDER]; ALL_TAC] THEN
  (* ---- build the canonical bnamed opn-name of (xic,rdot) ---- *)
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`xic:A`;`rdot:A`]
     EOPAIRNAME_CANON) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `op0:A`
             (X_CHOOSE_THEN `sa0:A` (X_CHOOSE_THEN `sab0:A`
                                     (X_CHOOSE_THEN `top0:A`
                                      (X_CHOOSE_THEN `paa0:A`
                                       (X_CHOOSE_THEN `pab0:A`
                                        (X_CHOOSE_THEN `psa0:A`
                                         (X_CHOOSE_THEN `psab0:A`
                                          STRIP_ASSUME_TAC)))))))) THEN
  (* ---- collapse top0 = top ---- *)
  SUBGOAL_THEN `top0:A = top` SUBST_ALL_TAC THENL
   [MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`top0:A`;`top:A`]
       ETOP_UNIQUE) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC]; ALL_TAC] THEN
  (* ---- collapse the two eopair <_,top> layers paa0=paa, pab0=pab ---- *)
  SUBGOAL_THEN `paa0:A = paa` SUBST_ALL_TAC THENL
   [MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`xic:A`;`top:A`;`paa0:A`;`paa:A`]
       EOPAIR_UNIQUE) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC]; ALL_TAC] THEN
  SUBGOAL_THEN `pab0:A = pab` SUBST_ALL_TAC THENL
   [MP_TAC(ISPECL
           [`D:A->bool`;`E:A->A->bool`;`rdot:A`;`top:A`;`pab0:A`;`pab:A`]
           EOPAIR_UNIQUE) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC]; ALL_TAC] THEN
  (* ---- recover sa0's epair cell from CANON's membership-iff ---- *)
  SUBGOAL_THEN `epair D (E:A->A->bool) paa paa sa0` ASSUME_TAC THENL
   [REWRITE_TAC[epair] THEN CONJ_TAC THENL
     [FIRST_ASSUM ACCEPT_TAC;
      X_GEN_TAC `zz:A` THEN DISCH_TAC THEN
      FIRST_X_ASSUM(MP_TAC o SPEC `zz:A` o
        check (fun th -> is_forall(concl th) && vfree_in `sa0:A` (concl th) &&
                         vfree_in `paa:A` (concl th) &&
                         not(vfree_in `sab0:A` (concl th)))) THEN
      ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN CONV_TAC TAUT];
    ALL_TAC] THEN
  (* ---- recover sab0's epair cell (exact match, no collapse) ---- *)
  SUBGOAL_THEN `epair D (E:A->A->bool) paa pab sab0` ASSUME_TAC THENL
   [REWRITE_TAC[epair] THEN CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  (* ---- collapse sa0=sa, sab0=sab ---- *)
  SUBGOAL_THEN `sa0:A = sa` SUBST_ALL_TAC THENL
   [MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`paa:A`;`paa:A`;`sa0:A`;`sa:A`]
       EPAIR_UNIQUE) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC]; ALL_TAC] THEN
  SUBGOAL_THEN `sab0:A = sab` SUBST_ALL_TAC THENL
   [MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`paa:A`;`pab:A`;`sab0:A`;`sab:A`]
       EPAIR_UNIQUE) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC]; ALL_TAC] THEN
  (* ---- collapse the two eopair <_,top> layers psa0=psa, psab0=psab ---- *)
  SUBGOAL_THEN `psa0:A = psa` SUBST_ALL_TAC THENL
   [MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`sa:A`;`top:A`;`psa0:A`;`psa:A`]
       EOPAIR_UNIQUE) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC]; ALL_TAC] THEN
  SUBGOAL_THEN `psab0:A = psab` SUBST_ALL_TAC THENL
   [MP_TAC(ISPECL
           [`D:A->bool`;`E:A->A->bool`;`sab:A`;`top:A`;`psab0:A`;`psab:A`]
           EOPAIR_UNIQUE) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC]; ALL_TAC] THEN
  (* ---- recover op0's epair cell (exact match) ---- *)
  SUBGOAL_THEN `epair D (E:A->A->bool) psa psab op0` ASSUME_TAC THENL
   [REWRITE_TAC[epair] THEN CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  (* ---- collapse op0=op ---- *)
  SUBGOAL_THEN `op0:A = op` SUBST_ALL_TAC THENL
   [MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`psa:A`;`psab:A`;`op0:A`;`op:A`]
       EPAIR_UNIQUE) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC]; ALL_TAC] THEN
  (* ---- CANON's bname + bundle now bear on op/sa/sab ---- *)
  ASM_REWRITE_TAC[]);;

(* ======================================================================= *)
(* PROJ1 = EBV_EQ_KURCHECK_PROJ1 : first-coordinate projection.             *)
(*   op  = Kuratowski <a,b>      (members sa={a}, sab={a,b}; weight top)     *)
(*   ckp = Kuratowski <cxi,cal>  (members s ={cxi}, p ={cxi,cal}; wt top)    *)
(*   ek  = [[op = ckp]],  e1 = [[a = cxi]].        ==>  erel leq ek e1.      *)
(*                                                                           *)
(*   sa IN ckp (top member) -> [[sa IN ckp]] = [[sa=s]] + [[sa=p]];          *)
(*   [[sa=s]] <= [[a IN s]]  = [[a=cxi]];                                    *)
(*   [[sa=p]] = [[p=sa]] <= [[cxi IN sa]] = [[cxi=a]] = [[a=cxi]].           *)
(*   (No check-decidability needed here; this half is fully general.)        *)
(* ======================================================================= *)

let EBV_EQ_KURCHECK_PROJ1 = prove
 (`!D (E:A->A->bool) B leq top a b cxi cal op sa sab s p ckp ek e1.
     model D E ZF_AX /\
     ecba D E B leq /\ B IN D /\ leq IN D /\ top IN D /\ etop D E B leq top /\
     a IN D /\ b IN D /\ cxi IN D /\ cal IN D /\ op IN D /\
     sa IN D /\ sab IN D /\ s IN D /\ p IN D /\ ckp IN D /\
     ek IN D /\ e1 IN D /\
     bname D E B a /\ bname D E B b /\ bname D E B cxi /\ bname D E B cal /\
     bname D E B op /\ bname D E B sa /\ bname D E B sab /\
     bname D E B s /\ bname D E B p /\ bname D E B ckp /\
     eapply D E op sa top /\ eapply D E op sab top /\
     (!t q. t IN D /\ q IN D /\ eapply D E op t q ==> t = sa \/ t = sab) /\
     eapply D E sa a top /\
     (!t q. t IN D /\ q IN D /\ eapply D E sa t q ==> t = a \/ t = a) /\
     eapply D E sab a top /\ eapply D E sab b top /\
     (!t q. t IN D /\ q IN D /\ eapply D E sab t q ==> t = a \/ t = b) /\
     eapply D E ckp s top /\ eapply D E ckp p top /\
     (!t q. t IN D /\ q IN D /\ eapply D E ckp t q ==> t = s \/ t = p) /\
     eapply D E s cxi top /\
     (!t q. t IN D /\ q IN D /\ eapply D E s t q ==> t = cxi \/ t = cxi) /\
     eapply D E p cxi top /\ eapply D E p cal top /\
     (!t q. t IN D /\ q IN D /\ eapply D E p t q ==> t = cxi \/ t = cal) /\
     ebv_eq D E B leq op ckp ek /\ ebv_eq D E B leq a cxi e1
     ==> erel D E leq ek e1`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `ebalg D (E:A->A->bool) B leq /\ eporder D E B leq`
    STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[ECBA_IMP_BALG; EBALG_IMP_PORDER]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) ek B` ASSUME_TAC THENL
   [ASM_MESON_TAC[EBV_EQ_IN_B]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) e1 B /\ (e1:A) IN D` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[EBV_EQ_IN_B]; ALL_TAC] THEN
  (* ---- materialize the member values ---- *)
  SUBGOAL_THEN `?msc:A. msc IN D /\ E msc B /\ ebv_in D E B leq sa ckp msc`
    (X_CHOOSE_THEN `msc:A` STRIP_ASSUME_TAC) THENL
   [MATCH_MP_TAC EBV_IN_VAL_EXISTS THEN REPEAT CONJ_TAC THEN
    TRY(FIRST_ASSUM ACCEPT_TAC) THEN ASM_MESON_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `?vss:A. vss IN D /\ E vss B /\ ebv_eq D E B leq sa s vss`
    (X_CHOOSE_THEN `vss:A` STRIP_ASSUME_TAC) THENL
   [MATCH_MP_TAC EBV_EQ_VAL_EXISTS THEN REPEAT CONJ_TAC THEN
    TRY(FIRST_ASSUM ACCEPT_TAC) THEN ASM_MESON_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `?vsp:A. vsp IN D /\ E vsp B /\ ebv_eq D E B leq sa p vsp`
    (X_CHOOSE_THEN `vsp:A` STRIP_ASSUME_TAC) THENL
   [MATCH_MP_TAC EBV_EQ_VAL_EXISTS THEN REPEAT CONJ_TAC THEN
    TRY(FIRST_ASSUM ACCEPT_TAC) THEN ASM_MESON_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `?mas:A. mas IN D /\ E mas B /\ ebv_in D E B leq a s mas`
    (X_CHOOSE_THEN `mas:A` STRIP_ASSUME_TAC) THENL
   [MATCH_MP_TAC EBV_IN_VAL_EXISTS THEN REPEAT CONJ_TAC THEN
    TRY(FIRST_ASSUM ACCEPT_TAC) THEN ASM_MESON_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `?mcsa:A. mcsa IN D /\ E mcsa B /\ ebv_in D E B leq cxi sa mcsa`
    (X_CHOOSE_THEN `mcsa:A` STRIP_ASSUME_TAC) THENL
   [MATCH_MP_TAC EBV_IN_VAL_EXISTS THEN REPEAT CONJ_TAC THEN
    TRY(FIRST_ASSUM ACCEPT_TAC) THEN ASM_MESON_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `?vca:A. vca IN D /\ E vca B /\ ebv_eq D E B leq cxi a vca`
    (X_CHOOSE_THEN `vca:A` STRIP_ASSUME_TAC) THENL
   [MATCH_MP_TAC EBV_EQ_VAL_EXISTS THEN REPEAT CONJ_TAC THEN
    TRY(FIRST_ASSUM ACCEPT_TAC) THEN ASM_MESON_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `?zj:A. ejoin D (E:A->A->bool) B leq vss vsp zj`
    (X_CHOOSE_TAC `zj:A`) THENL
   [ASM_MESON_TAC[EBALG_JOIN]; ALL_TAC] THEN
  SUBGOAL_THEN `(zj:A) IN D /\ (E:A->A->bool) zj B` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[EJOIN_IN]; ALL_TAC] THEN
  (* ---- F1: erel ek msc  (descent through op's member sa) ---- *)
  SUBGOAL_THEN `erel D (E:A->A->bool) leq ek msc` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`op:A`;`ckp:A`;
                  `ek:A`;`sa:A`;`top:A`;`msc:A`] EBV_EQ_LE_MEM_TOP) THEN
    REPEAT CONJ_TAC THEN TRY(FIRST_ASSUM ACCEPT_TAC) THEN ASM_MESON_TAC[];
    ALL_TAC] THEN
  (* ---- F2: msc = vss ++ vsp ---- *)
  SUBGOAL_THEN `(msc:A) = zj` SUBST_ALL_TAC THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`s:A`;`p:A`;
       `ckp:A`;`top:A`;`sa:A`;`msc:A`;`vss:A`;`vsp:A`;`zj:A`]
                   EBV_IN_UPAIR) THEN
    REPEAT CONJ_TAC THEN TRY(FIRST_ASSUM ACCEPT_TAC) THEN ASM_MESON_TAC[];
    ALL_TAC] THEN
  (* ---- F3: erel vss e1   (vss <= mas = e1) ---- *)
  SUBGOAL_THEN `erel D (E:A->A->bool) leq vss e1` ASSUME_TAC THENL
   [SUBGOAL_THEN `erel D (E:A->A->bool) leq vss mas` ASSUME_TAC THENL
     [MATCH_MP_TAC(ISPECL
                   [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`sa:A`;`s:A`;
                    `vss:A`;`a:A`;`top:A`;`mas:A`] EBV_EQ_LE_MEM_TOP) THEN
      REPEAT CONJ_TAC THEN TRY(FIRST_ASSUM ACCEPT_TAC) THEN ASM_MESON_TAC[];
      ALL_TAC] THEN
    SUBGOAL_THEN `(mas:A) = e1` ASSUME_TAC THENL
     [MATCH_MP_TAC(ISPECL
                   [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`s:A`;`cxi:A`;
                    `top:A`;`a:A`;`mas:A`;`e1:A`] EBV_IN_SING_VAL) THEN
      REPEAT CONJ_TAC THEN TRY(FIRST_ASSUM ACCEPT_TAC) THEN ASM_MESON_TAC[];
      ALL_TAC] THEN
    ASM_MESON_TAC[]; ALL_TAC] THEN
  (* ---- F4: erel vsp e1   (vsp=[[p=sa]] <= mcsa = vca = e1) ---- *)
  SUBGOAL_THEN `erel D (E:A->A->bool) leq vsp e1` ASSUME_TAC THENL
   [SUBGOAL_THEN `ebv_eq D (E:A->A->bool) B leq p sa vsp` ASSUME_TAC THENL
     [MATCH_MP_TAC(ISPECL
                   [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`sa:A`;`p:A`;
                    `vsp:A`] EBV_EQ_SYM) THEN REPEAT CONJ_TAC THEN
         TRY(FIRST_ASSUM ACCEPT_TAC) THEN ASM_MESON_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN `erel D (E:A->A->bool) leq vsp mcsa` ASSUME_TAC THENL
     [MATCH_MP_TAC(ISPECL
                   [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`p:A`;`sa:A`;
                    `vsp:A`;`cxi:A`;`top:A`;`mcsa:A`] EBV_EQ_LE_MEM_TOP) THEN
      REPEAT CONJ_TAC THEN TRY(FIRST_ASSUM ACCEPT_TAC) THEN ASM_MESON_TAC[];
      ALL_TAC] THEN
    SUBGOAL_THEN `(mcsa:A) = vca` ASSUME_TAC THENL
     [MATCH_MP_TAC(ISPECL
                   [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`sa:A`;`a:A`;
                    `top:A`;`cxi:A`;`mcsa:A`;`vca:A`] EBV_IN_SING_VAL) THEN
      REPEAT CONJ_TAC THEN TRY(FIRST_ASSUM ACCEPT_TAC) THEN ASM_MESON_TAC[];
      ALL_TAC] THEN
    SUBGOAL_THEN `ebv_eq D (E:A->A->bool) B leq a cxi vca` ASSUME_TAC THENL
     [MATCH_MP_TAC(ISPECL
                   [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`cxi:A`;`a:A`;
                    `vca:A`] EBV_EQ_SYM) THEN REPEAT CONJ_TAC THEN
         TRY(FIRST_ASSUM ACCEPT_TAC) THEN ASM_MESON_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN `(vca:A) = e1` ASSUME_TAC THENL
     [MATCH_MP_TAC(ISPECL
                   [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`a:A`;`cxi:A`;
                    `vca:A`;`e1:A`] EBV_EQ_UNIQUE) THEN
      REPEAT CONJ_TAC THEN TRY(FIRST_ASSUM ACCEPT_TAC) THEN ASM_MESON_TAC[];
      ALL_TAC] THEN
    ASM_MESON_TAC[]; ALL_TAC] THEN
  (* ---- F5: erel zj e1  (join is a lower bound of e1) ---- *)
  SUBGOAL_THEN `erel D (E:A->A->bool) leq zj e1` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`vss:A`;`vsp:A`;
                  `zj:A`;`e1:A`] EJOIN_LEAST) THEN
    REPEAT CONJ_TAC THEN TRY(FIRST_ASSUM ACCEPT_TAC) THEN ASM_MESON_TAC[];
    ALL_TAC] THEN
  (* ---- F6: erel ek e1  (ek <= zj <= e1) ---- *)
  MATCH_MP_TAC(ISPECL
               [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`ek:A`;`zj:A`;`e1:A`]
               EPORDER_TRANS) THEN
  REPEAT CONJ_TAC THEN TRY(FIRST_ASSUM ACCEPT_TAC) THEN ASM_MESON_TAC[]);;

(* ----------------------------------------------------------------------- *)
(* EREL_RELCOMP : relative complement in a Boolean algebra.                  *)
(*   p <= x ++ y  and  p /\ x = bot   ==>   p <= y.                          *)
(*   (p = p/\(x++y) = (p/\x)++(p/\y) = bot++(p/\y) = p/\y <= y.)             *)
(* ----------------------------------------------------------------------- *)

let EREL_RELCOMP = prove
 (`!D (E:A->A->bool) B leq x y jj p mpx bott.
     ecba D E B leq /\
     x IN D /\ y IN D /\ jj IN D /\ p IN D /\ mpx IN D /\ bott IN D /\
     E x B /\ E y B /\ E p B /\ E jj B /\ E mpx B /\ E bott B /\
     ejoin D E B leq x y jj /\ emeet D E B leq p x mpx /\
     ebot D E B leq bott /\ erel D E leq mpx bott /\ erel D E leq p jj
     ==> erel D E leq p y`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `ebalg D (E:A->A->bool) B leq /\ eporder D E B leq`
    STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[ECBA_IMP_BALG; EBALG_IMP_PORDER]; ALL_TAC] THEN
  SUBGOAL_THEN `?mpy:A. emeet D (E:A->A->bool) B leq p y mpy`
    (X_CHOOSE_TAC `mpy:A`) THENL [ASM_MESON_TAC[EBALG_MEET]; ALL_TAC] THEN
  SUBGOAL_THEN `(mpy:A) IN D /\ (E:A->A->bool) mpy B` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[EMEET_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `?mpj:A. emeet D (E:A->A->bool) B leq p jj mpj`
    (X_CHOOSE_TAC `mpj:A`) THENL [ASM_MESON_TAC[EBALG_MEET]; ALL_TAC] THEN
  SUBGOAL_THEN `(mpj:A) IN D /\ (E:A->A->bool) mpj B` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[EMEET_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `?ejn:A. ejoin D (E:A->A->bool) B leq mpx mpy ejn`
    (X_CHOOSE_TAC `ejn:A`) THENL [ASM_MESON_TAC[EBALG_JOIN]; ALL_TAC] THEN
  SUBGOAL_THEN `(ejn:A) IN D /\ (E:A->A->bool) ejn B` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[EJOIN_IN]; ALL_TAC] THEN
  (* DISTRIB:  emeet p jj = ejoin (emeet p x) (emeet p y),  i.e. mpj = ejn *)
  SUBGOAL_THEN `(mpj:A) = ejn` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`p:A`;`x:A`;
       `y:A`;`jj:A`;`mpj:A`;`mpx:A`;`mpy:A`;`ejn:A`] EBALG_DISTRIB) THEN
    REPEAT CONJ_TAC THEN TRY(FIRST_ASSUM ACCEPT_TAC) THEN ASM_MESON_TAC[];
    ALL_TAC] THEN
  (* mpx = bott *)
  SUBGOAL_THEN `(mpx:A) = bott` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`mpx:A`;`bott:A`]
                 EPORDER_ANTISYM) THEN
    REPEAT CONJ_TAC THEN TRY(FIRST_ASSUM ACCEPT_TAC) THEN
    ASM_MESON_TAC[EBOT_LE]; ALL_TAC] THEN
  (* ejoin bott mpy mpy, and ejoin mpx mpy ejn with mpx=bott -> ejn = mpy *)
  SUBGOAL_THEN `(ejn:A) = mpy` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`bott:A`;`mpy:A`;
                  `ejn:A`;`mpy:A`] EJOIN_UNIQUE) THEN
    CONJ_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    CONJ_TAC THENL
     [UNDISCH_TAC `ejoin D (E:A->A->bool) B leq mpx mpy ejn` THEN
      ASM_REWRITE_TAC[];
      MATCH_MP_TAC(ISPECL
                   [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`bott:A`;`mpy:A`]
                   EJOIN_BOT) THEN
      REPEAT CONJ_TAC THEN TRY(FIRST_ASSUM ACCEPT_TAC) THEN ASM_MESON_TAC[]];
     ALL_TAC] THEN
  (* p = mpj : via erel p mpj (EMEET_GREATEST) and erel mpj p (EMEET_LE) *)
  SUBGOAL_THEN `erel D (E:A->A->bool) leq p mpj` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`p:A`;`jj:A`;
       `mpj:A`] EMEET_GREATEST) THEN
    REPEAT CONJ_TAC THEN TRY(FIRST_ASSUM ACCEPT_TAC) THEN
    ASM_MESON_TAC[EPORDER_REFL]; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq mpj p` ASSUME_TAC THENL
   [ASM_MESON_TAC[EMEET_LE]; ALL_TAC] THEN
  SUBGOAL_THEN `(p:A) = mpj` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`p:A`;`mpj:A`]
                 EPORDER_ANTISYM) THEN
    REPEAT CONJ_TAC THEN TRY(FIRST_ASSUM ACCEPT_TAC) THEN
    ASM_MESON_TAC[]; ALL_TAC] THEN
  (* p = mpj = ejn = mpy = emeet p y <= y *)
  SUBGOAL_THEN `(p:A) = mpy` ASSUME_TAC THENL
   [ASM_MESON_TAC[]; ALL_TAC] THEN
  ASM_MESON_TAC[EMEET_LE]);;

(* ========================================================================= *)
(* PROJ2 : second-coordinate projection  [[<a,b>=<cxi,cal>]] <= [[b=cal]].   *)
(*                                                                           *)
(* Built as three sub-lemmas:                                                *)
(*   PROJ2_EQ   (cal = cxi, i.e. index components equal): p = {cxi,cxi}      *)
(*              collapses to a singleton; mirror of PROJ1 on the SECOND      *)
(*              Kuratowski member sab = {a,b} and the point b.               *)
(*   PROJ2_NEQ  ([[cxi=cal]] = bot): the [[p IN op]] member collapses        *)
(*              ([[p=sa]] <= [[cxi=cal]] = bot), leaving [[p=sab]] <=        *)
(*              [[cal IN sab]] = [[cal=a]]++[[cal=b]]; relative complement   *)
(*              (ek /\ [[cal=a]] <= [[cxi=cal]] = bot) gives ek <=           *)
(* [[cal=b]].                                                                *)
(*   PROJ2      wrapper: ASM_CASES on xi = al; ECHECK_SV / ECHECK_EQ_BOT.    *)
(* ========================================================================= *)

(* ----- PROJ2_EQ : the case cal = cxi (singleton collapse) --------------- *)

let EBV_EQ_KURCHECK_PROJ2_EQ = prove
 (`!D (E:A->A->bool) B leq top a b cxi cal op sa sab s p ckp ek e2.
     model D E ZF_AX /\
     ecba D E B leq /\ B IN D /\ leq IN D /\ top IN D /\ etop D E B leq top /\
     a IN D /\ b IN D /\ cxi IN D /\ cal IN D /\ op IN D /\
     sa IN D /\ sab IN D /\ s IN D /\ p IN D /\ ckp IN D /\
     ek IN D /\ e2 IN D /\
     bname D E B a /\ bname D E B b /\ bname D E B cxi /\ bname D E B cal /\
     bname D E B op /\ bname D E B sa /\ bname D E B sab /\
     bname D E B s /\ bname D E B p /\ bname D E B ckp /\
     eapply D E op sa top /\ eapply D E op sab top /\
     (!t q. t IN D /\ q IN D /\ eapply D E op t q ==> t = sa \/ t = sab) /\
     eapply D E sa a top /\
     (!t q. t IN D /\ q IN D /\ eapply D E sa t q ==> t = a \/ t = a) /\
     eapply D E sab a top /\ eapply D E sab b top /\
     (!t q. t IN D /\ q IN D /\ eapply D E sab t q ==> t = a \/ t = b) /\
     eapply D E ckp s top /\ eapply D E ckp p top /\
     (!t q. t IN D /\ q IN D /\ eapply D E ckp t q ==> t = s \/ t = p) /\
     eapply D E s cxi top /\
     (!t q. t IN D /\ q IN D /\ eapply D E s t q ==> t = cxi \/ t = cxi) /\
     eapply D E p cxi top /\ eapply D E p cal top /\
     (!t q. t IN D /\ q IN D /\ eapply D E p t q ==> t = cxi \/ t = cal) /\
     ebv_eq D E B leq op ckp ek /\ ebv_eq D E B leq b cal e2 /\ cal = cxi
     ==> erel D E leq ek e2`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  UNDISCH_TAC `cal:A = cxi` THEN DISCH_THEN SUBST_ALL_TAC THEN
  SUBGOAL_THEN `ebalg D (E:A->A->bool) B leq /\ eporder D E B leq`
    STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[ECBA_IMP_BALG; EBALG_IMP_PORDER]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) ek B` ASSUME_TAC THENL
   [ASM_MESON_TAC[EBV_EQ_IN_B]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) e2 B /\ (e2:A) IN D` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[EBV_EQ_IN_B]; ALL_TAC] THEN
  (* ---- materialize member values ---- *)
  SUBGOAL_THEN
    `?msab:A. msab IN D /\ E msab B /\ ebv_in D E B leq sab ckp msab`
    (X_CHOOSE_THEN `msab:A` STRIP_ASSUME_TAC) THENL
   [MATCH_MP_TAC EBV_IN_VAL_EXISTS THEN REPEAT CONJ_TAC THEN
    TRY(FIRST_ASSUM ACCEPT_TAC) THEN ASM_MESON_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `?vss2:A. vss2 IN D /\ E vss2 B /\ ebv_eq D E B leq sab s vss2`
    (X_CHOOSE_THEN `vss2:A` STRIP_ASSUME_TAC) THENL
   [MATCH_MP_TAC EBV_EQ_VAL_EXISTS THEN REPEAT CONJ_TAC THEN
    TRY(FIRST_ASSUM ACCEPT_TAC) THEN ASM_MESON_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `?vsp2:A. vsp2 IN D /\ E vsp2 B /\ ebv_eq D E B leq sab p vsp2`
    (X_CHOOSE_THEN `vsp2:A` STRIP_ASSUME_TAC) THENL
   [MATCH_MP_TAC EBV_EQ_VAL_EXISTS THEN REPEAT CONJ_TAC THEN
    TRY(FIRST_ASSUM ACCEPT_TAC) THEN ASM_MESON_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `?mbs:A. mbs IN D /\ E mbs B /\ ebv_in D E B leq b s mbs`
    (X_CHOOSE_THEN `mbs:A` STRIP_ASSUME_TAC) THENL
   [MATCH_MP_TAC EBV_IN_VAL_EXISTS THEN REPEAT CONJ_TAC THEN
    TRY(FIRST_ASSUM ACCEPT_TAC) THEN ASM_MESON_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `?mbp:A. mbp IN D /\ E mbp B /\ ebv_in D E B leq b p mbp`
    (X_CHOOSE_THEN `mbp:A` STRIP_ASSUME_TAC) THENL
   [MATCH_MP_TAC EBV_IN_VAL_EXISTS THEN REPEAT CONJ_TAC THEN
    TRY(FIRST_ASSUM ACCEPT_TAC) THEN ASM_MESON_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `?zj2:A. ejoin D (E:A->A->bool) B leq vss2 vsp2 zj2`
    (X_CHOOSE_TAC `zj2:A`) THENL
   [ASM_MESON_TAC[EBALG_JOIN]; ALL_TAC] THEN
  SUBGOAL_THEN `(zj2:A) IN D /\ (E:A->A->bool) zj2 B` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[EJOIN_IN]; ALL_TAC] THEN
  (* ---- F1: erel ek msab ---- *)
  SUBGOAL_THEN `erel D (E:A->A->bool) leq ek msab` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`op:A`;`ckp:A`;
                  `ek:A`;`sab:A`;`top:A`;`msab:A`] EBV_EQ_LE_MEM_TOP) THEN
    REPEAT CONJ_TAC THEN TRY(FIRST_ASSUM ACCEPT_TAC) THEN ASM_MESON_TAC[];
    ALL_TAC] THEN
  (* ---- F2: msab = vss2 ++ vsp2 ---- *)
  SUBGOAL_THEN `(msab:A) = zj2` SUBST_ALL_TAC THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`s:A`;`p:A`;
       `ckp:A`;`top:A`;`sab:A`;`msab:A`;`vss2:A`;`vsp2:A`;`zj2:A`]
                   EBV_IN_UPAIR) THEN
    REPEAT CONJ_TAC THEN TRY(FIRST_ASSUM ACCEPT_TAC) THEN ASM_MESON_TAC[];
    ALL_TAC] THEN
  (* ---- F3: erel vss2 e2  (vss2 <= [[b IN s]] = [[b=cxi]] = e2) ---- *)
  SUBGOAL_THEN `erel D (E:A->A->bool) leq vss2 e2` ASSUME_TAC THENL
   [SUBGOAL_THEN `erel D (E:A->A->bool) leq vss2 mbs` ASSUME_TAC THENL
     [MATCH_MP_TAC(ISPECL
                   [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`sab:A`;`s:A`;
                    `vss2:A`;`b:A`;`top:A`;`mbs:A`] EBV_EQ_LE_MEM_TOP) THEN
      REPEAT CONJ_TAC THEN TRY(FIRST_ASSUM ACCEPT_TAC) THEN ASM_MESON_TAC[];
      ALL_TAC] THEN
    SUBGOAL_THEN `(mbs:A) = e2` ASSUME_TAC THENL
     [MATCH_MP_TAC(ISPECL
                   [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`s:A`;`cxi:A`;
                    `top:A`;`b:A`;`mbs:A`;`e2:A`] EBV_IN_SING_VAL) THEN
      REPEAT CONJ_TAC THEN TRY(FIRST_ASSUM ACCEPT_TAC) THEN ASM_MESON_TAC[];
      ALL_TAC] THEN
    ASM_MESON_TAC[]; ALL_TAC] THEN
  (* ---- F4: erel vsp2 e2  (vsp2 <= [[b IN p]] = [[b=cxi]] = e2) ---- *)
  SUBGOAL_THEN `erel D (E:A->A->bool) leq vsp2 e2` ASSUME_TAC THENL
   [SUBGOAL_THEN `erel D (E:A->A->bool) leq vsp2 mbp` ASSUME_TAC THENL
     [MATCH_MP_TAC(ISPECL
                   [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`sab:A`;`p:A`;
                    `vsp2:A`;`b:A`;`top:A`;`mbp:A`] EBV_EQ_LE_MEM_TOP) THEN
      REPEAT CONJ_TAC THEN TRY(FIRST_ASSUM ACCEPT_TAC) THEN ASM_MESON_TAC[];
      ALL_TAC] THEN
    SUBGOAL_THEN `(mbp:A) = e2` ASSUME_TAC THENL
     [MATCH_MP_TAC(ISPECL
                   [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`p:A`;`cxi:A`;
                    `top:A`;`b:A`;`mbp:A`;`e2:A`] EBV_IN_SING_VAL) THEN
      REPEAT CONJ_TAC THEN TRY(FIRST_ASSUM ACCEPT_TAC) THEN ASM_MESON_TAC[];
      ALL_TAC] THEN
    ASM_MESON_TAC[]; ALL_TAC] THEN
  (* ---- F5: erel zj2 e2 ---- *)
  SUBGOAL_THEN `erel D (E:A->A->bool) leq zj2 e2` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`vss2:A`;`vsp2:A`;
                  `zj2:A`;`e2:A`] EJOIN_LEAST) THEN
    REPEAT CONJ_TAC THEN TRY(FIRST_ASSUM ACCEPT_TAC) THEN ASM_MESON_TAC[];
    ALL_TAC] THEN
  (* ---- F6: erel ek e2 ---- *)
  MATCH_MP_TAC(ISPECL
               [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`ek:A`;`zj2:A`;`e2:A`]
               EPORDER_TRANS) THEN
  REPEAT CONJ_TAC THEN TRY(FIRST_ASSUM ACCEPT_TAC) THEN ASM_MESON_TAC[]);;

(* ----- PROJ2_NEQ : the case [[cxi=cal]] = bot (relative complement) -----  *)
(* [[p=sa]] <= [[cxi IN sa]] /\ [[cal IN sa]] = [[cxi=a]]/\[[cal=a]]         *)
(*           <= [[cxi=cal]] = bot,  so [[p IN op]] = [[p=sab]];              *)
(* [[p=sab]] <= [[cal IN sab]] = [[cal=a]]++[[cal=b]];                       *)
(* ek /\ [[cal=a]] <= [[cxi=a]]/\[[a=cal]] <= [[cxi=cal]] = bot;             *)
(* relative complement => ek <= [[cal=b]] = [[b=cal]] = e2.                  *)

let EBV_EQ_KURCHECK_PROJ2_NEQ = prove
 (`!D (E:A->A->bool) B leq top a b cxi cal op sa sab s p ckp ek e1 e2 vcc.
     model D E ZF_AX /\
     ecba D E B leq /\ B IN D /\ leq IN D /\ top IN D /\ etop D E B leq top /\
     a IN D /\ b IN D /\ cxi IN D /\ cal IN D /\ op IN D /\
     sa IN D /\ sab IN D /\ s IN D /\ p IN D /\ ckp IN D /\
     ek IN D /\ e1 IN D /\ e2 IN D /\ vcc IN D /\
     bname D E B a /\ bname D E B b /\ bname D E B cxi /\ bname D E B cal /\
     bname D E B op /\ bname D E B sa /\ bname D E B sab /\
     bname D E B s /\ bname D E B p /\ bname D E B ckp /\
     eapply D E op sa top /\ eapply D E op sab top /\
     (!t q. t IN D /\ q IN D /\ eapply D E op t q ==> t = sa \/ t = sab) /\
     eapply D E sa a top /\
     (!t q. t IN D /\ q IN D /\ eapply D E sa t q ==> t = a \/ t = a) /\
     eapply D E sab a top /\ eapply D E sab b top /\
     (!t q. t IN D /\ q IN D /\ eapply D E sab t q ==> t = a \/ t = b) /\
     eapply D E ckp s top /\ eapply D E ckp p top /\
     (!t q. t IN D /\ q IN D /\ eapply D E ckp t q ==> t = s \/ t = p) /\
     eapply D E s cxi top /\
     (!t q. t IN D /\ q IN D /\ eapply D E s t q ==> t = cxi \/ t = cxi) /\
     eapply D E p cxi top /\ eapply D E p cal top /\
     (!t q. t IN D /\ q IN D /\ eapply D E p t q ==> t = cxi \/ t = cal) /\
     ebv_eq D E B leq op ckp ek /\
     ebv_eq D E B leq a cxi e1 /\ erel D E leq ek e1 /\
     ebv_eq D E B leq b cal e2 /\
     ebv_eq D E B leq cxi cal vcc /\ ebot D E B leq vcc
     ==> erel D E leq ek e2`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `ebalg D (E:A->A->bool) B leq /\ eporder D E B leq`
    STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[ECBA_IMP_BALG; EBALG_IMP_PORDER]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) ek B` ASSUME_TAC THENL
   [ASM_MESON_TAC[EBV_EQ_IN_B]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) e1 B` ASSUME_TAC THENL
   [ASM_MESON_TAC[EBV_EQ_IN_B]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) e2 B /\ (e2:A) IN D` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[EBV_EQ_IN_B]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) vcc B` ASSUME_TAC THENL
   [ASM_MESON_TAC[EBV_EQ_IN_B]; ALL_TAC] THEN
  (* ---- materialize values ---- *)
  SUBGOAL_THEN `?msp:A. msp IN D /\ E msp B /\ ebv_in D E B leq p op msp`
    (X_CHOOSE_THEN `msp:A` STRIP_ASSUME_TAC) THENL
   [MATCH_MP_TAC EBV_IN_VAL_EXISTS THEN REPEAT CONJ_TAC THEN
    TRY(FIRST_ASSUM ACCEPT_TAC) THEN ASM_MESON_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `?vpsa:A. vpsa IN D /\ E vpsa B /\ ebv_eq D E B leq p sa vpsa`
    (X_CHOOSE_THEN `vpsa:A` STRIP_ASSUME_TAC) THENL
   [MATCH_MP_TAC EBV_EQ_VAL_EXISTS THEN REPEAT CONJ_TAC THEN
    TRY(FIRST_ASSUM ACCEPT_TAC) THEN ASM_MESON_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN
    `?vpsab:A. vpsab IN D /\ E vpsab B /\ ebv_eq D E B leq p sab vpsab`
    (X_CHOOSE_THEN `vpsab:A` STRIP_ASSUME_TAC) THENL
   [MATCH_MP_TAC EBV_EQ_VAL_EXISTS THEN REPEAT CONJ_TAC THEN
    TRY(FIRST_ASSUM ACCEPT_TAC) THEN ASM_MESON_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `?zjp:A. ejoin D (E:A->A->bool) B leq vpsa vpsab zjp`
    (X_CHOOSE_TAC `zjp:A`) THENL [ASM_MESON_TAC[EBALG_JOIN]; ALL_TAC] THEN
  SUBGOAL_THEN `(zjp:A) IN D /\ (E:A->A->bool) zjp B` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[EJOIN_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `?mcsa:A. mcsa IN D /\ E mcsa B /\ ebv_in D E B leq cxi sa mcsa`
    (X_CHOOSE_THEN `mcsa:A` STRIP_ASSUME_TAC) THENL
   [MATCH_MP_TAC EBV_IN_VAL_EXISTS THEN REPEAT CONJ_TAC THEN
    TRY(FIRST_ASSUM ACCEPT_TAC) THEN ASM_MESON_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `?mcla:A. mcla IN D /\ E mcla B /\ ebv_in D E B leq cal sa mcla`
    (X_CHOOSE_THEN `mcla:A` STRIP_ASSUME_TAC) THENL
   [MATCH_MP_TAC EBV_IN_VAL_EXISTS THEN REPEAT CONJ_TAC THEN
    TRY(FIRST_ASSUM ACCEPT_TAC) THEN ASM_MESON_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `?vxa:A. vxa IN D /\ E vxa B /\ ebv_eq D E B leq cxi a vxa`
    (X_CHOOSE_THEN `vxa:A` STRIP_ASSUME_TAC) THENL
   [MATCH_MP_TAC EBV_EQ_VAL_EXISTS THEN REPEAT CONJ_TAC THEN
    TRY(FIRST_ASSUM ACCEPT_TAC) THEN ASM_MESON_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `?vca:A. vca IN D /\ E vca B /\ ebv_eq D E B leq cal a vca`
    (X_CHOOSE_THEN `vca:A` STRIP_ASSUME_TAC) THENL
   [MATCH_MP_TAC EBV_EQ_VAL_EXISTS THEN REPEAT CONJ_TAC THEN
    TRY(FIRST_ASSUM ACCEPT_TAC) THEN ASM_MESON_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN
    `?mclsab:A. mclsab IN D /\ E mclsab B /\ ebv_in D E B leq cal sab mclsab`
    (X_CHOOSE_THEN `mclsab:A` STRIP_ASSUME_TAC) THENL
   [MATCH_MP_TAC EBV_IN_VAL_EXISTS THEN REPEAT CONJ_TAC THEN
    TRY(FIRST_ASSUM ACCEPT_TAC) THEN ASM_MESON_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `?vlb:A. vlb IN D /\ E vlb B /\ ebv_eq D E B leq cal b vlb`
    (X_CHOOSE_THEN `vlb:A` STRIP_ASSUME_TAC) THENL
   [MATCH_MP_TAC EBV_EQ_VAL_EXISTS THEN REPEAT CONJ_TAC THEN
    TRY(FIRST_ASSUM ACCEPT_TAC) THEN ASM_MESON_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `?zjcl:A. ejoin D (E:A->A->bool) B leq vca vlb zjcl`
    (X_CHOOSE_TAC `zjcl:A`) THENL [ASM_MESON_TAC[EBALG_JOIN]; ALL_TAC] THEN
  SUBGOAL_THEN `(zjcl:A) IN D /\ (E:A->A->bool) zjcl B` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[EJOIN_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `?mca:A. emeet D (E:A->A->bool) B leq vxa vca mca`
    (X_CHOOSE_TAC `mca:A`) THENL [ASM_MESON_TAC[EBALG_MEET]; ALL_TAC] THEN
  SUBGOAL_THEN `(mca:A) IN D /\ (E:A->A->bool) mca B` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[EMEET_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `?mev:A. emeet D (E:A->A->bool) B leq ek vca mev`
    (X_CHOOSE_TAC `mev:A`) THENL [ASM_MESON_TAC[EBALG_MEET]; ALL_TAC] THEN
  SUBGOAL_THEN `(mev:A) IN D /\ (E:A->A->bool) mev B` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[EMEET_IN]; ALL_TAC] THEN
  (* ---- I1: [[ckp=op]] = ek ---- *)
  SUBGOAL_THEN `ebv_eq D (E:A->A->bool) B leq ckp op ek` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`op:A`;`ckp:A`;
                  `ek:A`] EBV_EQ_SYM) THEN
    REPEAT CONJ_TAC THEN TRY(FIRST_ASSUM ACCEPT_TAC) THEN ASM_MESON_TAC[];
    ALL_TAC] THEN
  (* ---- I2/I3: identify singleton membership values  mcsa=vxa, mcla=vca *)
  (* --- *)
  SUBGOAL_THEN `(mcsa:A) = vxa` SUBST_ALL_TAC THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`sa:A`;`a:A`;
       `top:A`;`cxi:A`;`mcsa:A`;`vxa:A`] EBV_IN_SING_VAL) THEN
    REPEAT CONJ_TAC THEN TRY(FIRST_ASSUM ACCEPT_TAC) THEN ASM_MESON_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `(mcla:A) = vca` SUBST_ALL_TAC THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`sa:A`;`a:A`;
       `top:A`;`cal:A`;`mcla:A`;`vca:A`] EBV_IN_SING_VAL) THEN
    REPEAT CONJ_TAC THEN TRY(FIRST_ASSUM ACCEPT_TAC) THEN ASM_MESON_TAC[];
    ALL_TAC] THEN
  (* ---- I5: e1 = vxa  (so  ek <= vxa) ---- *)
  SUBGOAL_THEN `ebv_eq D (E:A->A->bool) B leq cxi a e1` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`a:A`;`cxi:A`;
                  `e1:A`] EBV_EQ_SYM) THEN
    REPEAT CONJ_TAC THEN TRY(FIRST_ASSUM ACCEPT_TAC) THEN ASM_MESON_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `(e1:A) = vxa` SUBST_ALL_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`cxi:A`;`a:A`;
                  `e1:A`;`vxa:A`] EBV_EQ_UNIQUE) THEN
    REPEAT CONJ_TAC THEN TRY(FIRST_ASSUM ACCEPT_TAC) THEN ASM_MESON_TAC[];
    ALL_TAC] THEN
  (* ---- I6: mca <= vcc  (CONG: [[cxi=a]]/\[[a=cal]] <= [[cxi=cal]]) ---- *)
  SUBGOAL_THEN `ebv_eq D (E:A->A->bool) B leq a cal vca` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`cal:A`;`a:A`;
                  `vca:A`] EBV_EQ_SYM) THEN
    REPEAT CONJ_TAC THEN TRY(FIRST_ASSUM ACCEPT_TAC) THEN ASM_MESON_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq mca vcc` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`cxi:A`;`a:A`;
                  `cal:A`;`vxa:A`;`vca:A`;`vcc:A`;`mca:A`] EBV_EQ_CONG) THEN
    REPEAT CONJ_TAC THEN TRY(FIRST_ASSUM ACCEPT_TAC) THEN ASM_MESON_TAC[];
    ALL_TAC] THEN
  (* ---- I7/I8: vpsa <= vxa,  vpsa <= vca ---- *)
  SUBGOAL_THEN `erel D (E:A->A->bool) leq vpsa vxa` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`p:A`;`sa:A`;
       `vpsa:A`;`cxi:A`;`top:A`;`vxa:A`] EBV_EQ_LE_MEM_TOP) THEN
    REPEAT CONJ_TAC THEN TRY(FIRST_ASSUM ACCEPT_TAC) THEN ASM_MESON_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq vpsa vca` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`p:A`;`sa:A`;
       `vpsa:A`;`cal:A`;`top:A`;`vca:A`] EBV_EQ_LE_MEM_TOP) THEN
    REPEAT CONJ_TAC THEN TRY(FIRST_ASSUM ACCEPT_TAC) THEN ASM_MESON_TAC[];
    ALL_TAC] THEN
  (* ---- I9: vpsa <= mca ---- *)
  SUBGOAL_THEN `erel D (E:A->A->bool) leq vpsa mca` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`vxa:A`;`vca:A`;
                  `mca:A`;`vpsa:A`] EMEET_GREATEST) THEN
    REPEAT CONJ_TAC THEN TRY(FIRST_ASSUM ACCEPT_TAC) THEN ASM_MESON_TAC[];
    ALL_TAC] THEN
  (* ---- I10/I11/I12: vpsa = vcc  (both bottom) ---- *)
  SUBGOAL_THEN `erel D (E:A->A->bool) leq vpsa vcc` ASSUME_TAC THENL
   [ASM_MESON_TAC[EPORDER_TRANS]; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq vcc vpsa` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`vcc:A`;`vpsa:A`]
                 EBOT_LE) THEN
    REPEAT CONJ_TAC THEN TRY(FIRST_ASSUM ACCEPT_TAC) THEN ASM_MESON_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `(vpsa:A) = vcc` SUBST_ALL_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`vpsa:A`;`vcc:A`]
                 EPORDER_ANTISYM) THEN
    REPEAT CONJ_TAC THEN TRY(FIRST_ASSUM ACCEPT_TAC) THEN ASM_MESON_TAC[];
    ALL_TAC] THEN
  (* ---- I13: ek <= msp ---- *)
  SUBGOAL_THEN `erel D (E:A->A->bool) leq ek msp` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`ckp:A`;`op:A`;
                  `ek:A`;`p:A`;`top:A`;`msp:A`] EBV_EQ_LE_MEM_TOP) THEN
    REPEAT CONJ_TAC THEN TRY(FIRST_ASSUM ACCEPT_TAC) THEN ASM_MESON_TAC[];
    ALL_TAC] THEN
  (* ---- I14: msp = vcc ++ vpsab ---- *)
  SUBGOAL_THEN `(msp:A) = zjp` SUBST_ALL_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`sa:A`;`sab:A`;
                  `op:A`;`top:A`;`p:A`;`msp:A`;`vcc:A`;`vpsab:A`;`zjp:A`]
                   EBV_IN_UPAIR) THEN
    REPEAT CONJ_TAC THEN TRY(FIRST_ASSUM ACCEPT_TAC) THEN ASM_MESON_TAC[];
    ALL_TAC] THEN
  (* ---- I15: zjp = vpsab  (vcc is bottom) ---- *)
  SUBGOAL_THEN `ejoin D (E:A->A->bool) B leq vcc vpsab vpsab` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`vcc:A`;`vpsab:A`]
                 EJOIN_BOT) THEN
    REPEAT CONJ_TAC THEN TRY(FIRST_ASSUM ACCEPT_TAC) THEN ASM_MESON_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `(zjp:A) = vpsab` SUBST_ALL_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`vcc:A`;`vpsab:A`;
                  `zjp:A`;`vpsab:A`] EJOIN_UNIQUE) THEN
    REPEAT CONJ_TAC THEN TRY(FIRST_ASSUM ACCEPT_TAC) THEN ASM_MESON_TAC[];
    ALL_TAC] THEN
  (* ---- I16: vpsab <= [[cal IN sab]] = mclsab ---- *)
  SUBGOAL_THEN `erel D (E:A->A->bool) leq vpsab mclsab` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`p:A`;`sab:A`;
                  `vpsab:A`;`cal:A`;`top:A`;`mclsab:A`] EBV_EQ_LE_MEM_TOP) THEN
    REPEAT CONJ_TAC THEN TRY(FIRST_ASSUM ACCEPT_TAC) THEN ASM_MESON_TAC[];
    ALL_TAC] THEN
  (* ---- I17: mclsab = vca ++ vlb ---- *)
  SUBGOAL_THEN `(mclsab:A) = zjcl` SUBST_ALL_TAC THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`a:A`;`b:A`;
       `sab:A`;`top:A`;`cal:A`;`mclsab:A`;`vca:A`;`vlb:A`;`zjcl:A`]
                   EBV_IN_UPAIR) THEN
    REPEAT CONJ_TAC THEN TRY(FIRST_ASSUM ACCEPT_TAC) THEN ASM_MESON_TAC[];
    ALL_TAC] THEN
  (* ---- I18: ek <= zjcl ---- *)
  SUBGOAL_THEN `erel D (E:A->A->bool) leq ek zjcl` ASSUME_TAC THENL
   [ASM_MESON_TAC[EPORDER_TRANS]; ALL_TAC] THEN
  (* ---- I19: mev = ek /\ vca <= vcc  (bottom) ---- *)
  SUBGOAL_THEN `erel D (E:A->A->bool) leq mev ek /\ erel D E leq mev vca`
    STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[EMEET_LE]; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq mev vxa` ASSUME_TAC THENL
   [ASM_MESON_TAC[EPORDER_TRANS]; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq mev mca` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`vxa:A`;`vca:A`;
                  `mca:A`;`mev:A`] EMEET_GREATEST) THEN
    REPEAT CONJ_TAC THEN TRY(FIRST_ASSUM ACCEPT_TAC) THEN ASM_MESON_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq mev vcc` ASSUME_TAC THENL
   [ASM_MESON_TAC[EPORDER_TRANS]; ALL_TAC] THEN
  (* ---- I20: relative complement  ek <= vlb ---- *)
  SUBGOAL_THEN `erel D (E:A->A->bool) leq ek vlb` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`vca:A`;`vlb:A`;
                  `zjcl:A`;`ek:A`;`mev:A`;`vcc:A`] EREL_RELCOMP) THEN
    REPEAT CONJ_TAC THEN TRY(FIRST_ASSUM ACCEPT_TAC) THEN ASM_MESON_TAC[];
    ALL_TAC] THEN
  (* ---- I21: vlb = e2 ---- *)
  SUBGOAL_THEN `ebv_eq D (E:A->A->bool) B leq cal b e2` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`b:A`;`cal:A`;
                  `e2:A`] EBV_EQ_SYM) THEN
    REPEAT CONJ_TAC THEN TRY(FIRST_ASSUM ACCEPT_TAC) THEN ASM_MESON_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `(vlb:A) = e2` SUBST_ALL_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`cal:A`;`b:A`;
                  `vlb:A`;`e2:A`] EBV_EQ_UNIQUE) THEN
    REPEAT CONJ_TAC THEN TRY(FIRST_ASSUM ACCEPT_TAC) THEN ASM_MESON_TAC[];
    ALL_TAC] THEN
  FIRST_ASSUM ACCEPT_TAC);;

(* ----- PROJ2 wrapper : dispatch on whether the check-elements agree -----  *)
(* top plays the ultrafilter top 1^; xip/alp are the pre-check elements with *)
(* echeck top xip cxi, echeck top alp cal.  xip=alp => cxi=cal (ECHECK_SV)   *)
(* => PROJ2_EQ;  xip<>alp => [[cxi=cal]]=bot (ECHECK_EQ_BOT) => PROJ2_NEQ.   *)
(* erel ek e1 is supplied internally by PROJ1 (needed only in the NEQ arm).  *)

let EBV_EQ_KURCHECK_PROJ2 = prove
 (`!D (E:A->A->bool) B leq top a b cxi cal op sa sab s p ckp ek e1 e2 xip alp.
     model D E ZF_AX /\ (!u:A. u IN D ==> elmem D E u) /\
     ecba D E B leq /\ B IN D /\ leq IN D /\ top IN D /\ etop D E B leq top /\
     a IN D /\ b IN D /\ cxi IN D /\ cal IN D /\ op IN D /\
     sa IN D /\ sab IN D /\ s IN D /\ p IN D /\ ckp IN D /\
     ek IN D /\ e1 IN D /\ e2 IN D /\
     bname D E B a /\ bname D E B b /\ bname D E B cxi /\ bname D E B cal /\
     bname D E B op /\ bname D E B sa /\ bname D E B sab /\
     bname D E B s /\ bname D E B p /\ bname D E B ckp /\
     eapply D E op sa top /\ eapply D E op sab top /\
     (!t q. t IN D /\ q IN D /\ eapply D E op t q ==> t = sa \/ t = sab) /\
     eapply D E sa a top /\
     (!t q. t IN D /\ q IN D /\ eapply D E sa t q ==> t = a \/ t = a) /\
     eapply D E sab a top /\ eapply D E sab b top /\
     (!t q. t IN D /\ q IN D /\ eapply D E sab t q ==> t = a \/ t = b) /\
     eapply D E ckp s top /\ eapply D E ckp p top /\
     (!t q. t IN D /\ q IN D /\ eapply D E ckp t q ==> t = s \/ t = p) /\
     eapply D E s cxi top /\
     (!t q. t IN D /\ q IN D /\ eapply D E s t q ==> t = cxi \/ t = cxi) /\
     eapply D E p cxi top /\ eapply D E p cal top /\
     (!t q. t IN D /\ q IN D /\ eapply D E p t q ==> t = cxi \/ t = cal) /\
     echeck D E top xip cxi /\ echeck D E top alp cal /\
     xip IN D /\ alp IN D /\
     ebv_eq D E B leq op ckp ek /\ ebv_eq D E B leq a cxi e1 /\
     ebv_eq D E B leq b cal e2
     ==> erel D E leq ek e2`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `(E:A->A->bool) top B` ASSUME_TAC THENL
   [ASM_MESON_TAC[ETOP_IN]; ALL_TAC] THEN
  (* PROJ1 gives  ek <= [[a=cxi]] = e1  *)
  SUBGOAL_THEN `erel D (E:A->A->bool) leq ek e1` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`top:A`;`a:A`;
                  `b:A`;`cxi:A`;`cal:A`;`op:A`;`sa:A`;`sab:A`;`s:A`;`p:A`;
                  `ckp:A`;`ek:A`;
                  `e1:A`] EBV_EQ_KURCHECK_PROJ1) THEN
    REPEAT CONJ_TAC THEN TRY(FIRST_ASSUM ACCEPT_TAC) THEN ASM_MESON_TAC[];
    ALL_TAC] THEN
  ASM_CASES_TAC `(xip:A) = alp` THENL
   [(* ---- EQ branch:  cxi = cal  (p = {cxi,cal} collapses to {cxi}) ---- *)
    (* xip = alp: convert echeck top alp cal into echeck top xip cal, so that
       ECHECK_SV's two antecedents become direct assumptions (keeps every leaf
       below deterministic -- bare ASM_MESON diverges in this enlarged, full-
       type-free context). *)
    SUBGOAL_THEN `echeck D (E:A->A->bool) top xip cal` ASSUME_TAC THENL
     [SUBST1_TAC(ASSUME `xip:A = alp`) THEN FIRST_ASSUM ACCEPT_TAC;
      ALL_TAC] THEN
    SUBGOAL_THEN `(cxi:A) = cal` ASSUME_TAC THENL
     [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`top:A`;`xip:A`;`cxi:A`;
         `cal:A`] ECHECK_SV) THEN
      REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    SUBGOAL_THEN `(cal:A) = cxi` ASSUME_TAC THENL
     [FIRST_ASSUM(ACCEPT_TAC o SYM); ALL_TAC] THEN
    MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`top:A`;`a:A`;
                  `b:A`;`cxi:A`;`cal:A`;`op:A`;`sa:A`;`sab:A`;`s:A`;`p:A`;
                  `ckp:A`;`ek:A`;
                  `e2:A`] EBV_EQ_KURCHECK_PROJ2_EQ) THEN
    REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC;
    (* ---- NEQ branch:  [[cxi = cal]] = bot ---- *)
    SUBGOAL_THEN `?vcc:A. vcc IN D /\ E vcc B /\ ebv_eq D E B leq cxi cal vcc`
      (X_CHOOSE_THEN `vcc:A` STRIP_ASSUME_TAC) THENL
     [MATCH_MP_TAC EBV_EQ_VAL_EXISTS THEN REPEAT CONJ_TAC THEN
      TRY(FIRST_ASSUM ACCEPT_TAC) THEN ASM_MESON_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN `ebot D (E:A->A->bool) B leq vcc` ASSUME_TAC THENL
     [MATCH_MP_TAC(ISPECL
                   [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`top:A`;`xip:A`;
                    `alp:A`;`cxi:A`;`cal:A`;`vcc:A`] ECHECK_EQ_BOT) THEN
      REPEAT CONJ_TAC THEN TRY(FIRST_ASSUM ACCEPT_TAC) THEN ASM_MESON_TAC[];
      ALL_TAC] THEN
    MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`top:A`;`a:A`;
                  `b:A`;`cxi:A`;`cal:A`;`op:A`;`sa:A`;`sab:A`;`s:A`;`p:A`;
                  `ckp:A`;`ek:A`;
                  `e1:A`;`e2:A`;`vcc:A`] EBV_EQ_KURCHECK_PROJ2_NEQ) THEN
    REPEAT CONJ_TAC THEN TRY(FIRST_ASSUM ACCEPT_TAC) THEN ASM_MESON_TAC[]]);;

(* =======================================================================
   B3_STEP7_COVERAGE   (monolithic; coverage hypothesis of B3_STEP7_TEST)

   For every member <y,qy> of the candidate injection name h (y an h-cell
   <xi2,alpha2>^, qy = [[ opn-cell(xic2,rdot2) IN f ]]), the member either
     (DISJ1) carries Gn=ca up to ey   (the diagonal column alpha2=a hits),  or
     (DISJ2) meets cc,s to BOT.
   Three arms after inverting the member via COV_INVERT:
     xi2=xi & alpha2=a : DIAG  (DISJ1 with ea := [[Gn=ca]])
     xi2=xi & alpha2<>a: OFF_AL (Gap3 BVALF_SVF_INCOMPAT -> [[r_a=r_a']]=BOT)
     xi2<>xi           : OFF_XI (ECHECK_EQ_BOT -> [[xic2=xic]]=BOT)
   Uses the preceding results:
     COV_INVERT, OPNCELL_BNAME_BUNDLE, BVALF_SVF_INCOMPAT (Gap3),
     EBV_EQ_KURCHECK_PROJ1/2 (PROJ1/PROJ2).
   ======================================================================= *)

let B3_STEP7_COVERAGE =
  let CLOSE = FIRST_ASSUM ACCEPT_TAC ORELSE FIRST_ASSUM MATCH_ACCEPT_TAC in
  prove
 (`!D (E:A->A->bool) B leq onebee realfn f a1 a2 cr h
     xi a xic rdota ca xx Gn prG sG pG sda pda opa wf c s exi wdia.
      ecba D E B leq /\ (!u:A. u IN D ==> elmem D E u) /\
      model D E ZF_AX /\ B IN D /\ leq IN D /\ onebee IN D /\ E onebee B /\
      etop D E B leq onebee /\
      realfn IN D /\ f IN D /\ a1 IN D /\ a2 IN D /\ cr IN D /\ h IN D /\
      xic IN D /\ rdota IN D /\ xx IN D /\ Gn IN D /\ prG IN D /\
      sG IN D /\ pG IN D /\ sda IN D /\ pda IN D /\ opa IN D /\
      wdia IN D /\ c IN D /\ exi IN D /\
      bname D E B f /\ eisfun D E realfn /\
      (!aa. aa IN D /\ (E:A->A->bool) aa a2
            ==> ?rd. rd IN D /\ eapply D E realfn aa rd /\ bname D E B rd) /\
      (!zz. zz IN D ==>
           (E zz h <=>
            ?cp xi alpha xic rdot op w cpc.
                 cp IN D /\ xi IN D /\ alpha IN D /\ xic IN D /\
                 rdot IN D /\ op IN D /\ w IN D /\ cpc IN D /\
                 (E:A->A->bool) cp cr /\
                 eopair D E xi alpha cp /\ E xi a1 /\ E alpha a2 /\
                 echeck D E onebee xi xic /\ eapply D E realfn alpha rdot /\
                 (?paa pab sa sab psa psab.
                      paa IN D /\ pab IN D /\ sa IN D /\ sab IN D /\
                      psa IN D /\ psab IN D /\
                      eopair D E xic onebee paa /\
                        eopair D E rdot onebee pab /\
                      epair D E paa paa sa /\ epair D E paa pab sab /\
                      eopair D E sa onebee psa /\ eopair D E sab onebee psab /\
                      epair D E psa psab op) /\
                 ebv_in D E B leq op f w /\
                 echeck D E onebee cp cpc /\ eopair D E cpc w zz)) /\
      xi IN D /\ E xi a1 /\ a IN D /\ E a a2 /\ ca IN D /\
      echeck D E onebee xi xic /\ eapply D E realfn a rdota /\
        bname D E B rdota /\
      echeck D E onebee a ca /\
      bname D E B sda /\ bname D E B pda /\ bname D E B opa /\
      eapply D E sda xic onebee /\
      (!t q. t IN D /\ q IN D /\ eapply D E sda t q ==> t = xic \/ t = xic) /\
      eapply D E pda xic onebee /\ eapply D E pda rdota onebee /\
      (!t q. t IN D /\ q IN D /\ eapply D E pda t q ==> t = xic \/
       t = rdota) /\
      eapply D E opa sda onebee /\ eapply D E opa pda onebee /\
      (!t q. t IN D /\ q IN D /\ eapply D E opa t q ==> t = sda \/ t = pda) /\
      ebv_in D E B leq opa f wdia /\
      bname D E B xx /\ bname D E B Gn /\ bname D E B prG /\
      bname D E B sG /\ bname D E B pG /\
      eapply D E sG xx onebee /\
      (!t q. t IN D /\ q IN D /\ eapply D E sG t q ==> t = xx \/ t = xx) /\
      eapply D E pG xx onebee /\ eapply D E pG Gn onebee /\
      (!t q. t IN D /\ q IN D /\ eapply D E pG t q ==> t = xx \/ t = Gn) /\
      eapply D E prG sG onebee /\ eapply D E prG pG onebee /\
      (!t q. t IN D /\ q IN D /\ eapply D E prG t q ==> t = sG \/ t = pG) /\
      valuation D wf /\ (!m. bname D E B ((wf:num->A) m)) /\ wf 3 = f /\
      E c B /\
      erel D E leq c
        (bvalf D E B leq wf
           (!! 4 (!! 5
                  (!! 6 ((apply_form 3 4 5 && apply_form 3 4 6) -->
                         Eq 5 6))))) /\
      s IN D /\ E s B /\ erel D E leq s c /\ erel D E leq s wdia /\
      ebv_eq D E B leq xx xic exi /\ E exi B /\ erel D E leq s exi /\
      (!a' rda rdx e. a' IN D /\ rda IN D /\ rdx IN D /\ e IN D /\
           (E:A->A->bool) a' a2 /\ ~(a' = a) /\
           eapply D E realfn a rda /\ eapply D E realfn a' rdx /\
           ebv_eq D E B leq rda rdx e ==> ebot D E B leq e)
      ==> !y qy ey cc.
              y IN D /\ qy IN D /\ ey IN D /\ cc IN D /\
              eapply D E h y qy /\ ebv_eq D E B leq prG y ey /\
              emeet D E B leq qy ey cc
              ==> (?ea. ea IN D /\ E ea B /\ ebv_eq D E B leq Gn ca ea /\
                        erel D E leq ey ea) \/
                  (?z. z IN D /\ E z B /\ emeet D E B leq cc s z /\
                       ebot D E B leq z)`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  FIRST_X_ASSUM(LABEL_TAC "hchar" o check (fun th ->
     is_forall(concl th) && vfree_in `h:A` (concl th) &&
       vfree_in `cr:A` (concl th))) THEN
  FIRST_X_ASSUM(LABEL_TAC "rtot" o check (fun th ->
     is_forall(concl th) && vfree_in `realfn:A` (concl th) &&
       vfree_in `a2:A` (concl th) &&
     not(vfree_in `a:A` (concl th)) && not(vfree_in `cr:A` (concl th)) &&
     not(vfree_in `h:A` (concl th)))) THEN
  FIRST_X_ASSUM(LABEL_TAC "distinct" o check (fun th ->
     is_forall(concl th) && vfree_in `realfn:A` (concl th) &&
       vfree_in `a:A` (concl th))) THEN
  MAP_EVERY X_GEN_TAC [`y:A`;`qy:A`;`ey:A`;`cc:A`] THEN STRIP_TAC THEN
  MP_TAC(ISPECL
         [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`onebee:A`;`realfn:A`;
          `f:A`;`a1:A`;`a2:A`;`cr:A`;`h:A`;`y:A`;`qy:A`] COV_INVERT) THEN
  ANTS_TAC THENL
   [REPEAT CONJ_TAC THEN
    (FIRST_ASSUM ACCEPT_TAC ORELSE FIRST_ASSUM MATCH_ACCEPT_TAC);
    ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `cp2:A`
             (X_CHOOSE_THEN `xi2:A` (X_CHOOSE_THEN `al2:A`
                                     (X_CHOOSE_THEN `xic2:A`
                                      (X_CHOOSE_THEN `rdot2:A`
                                       (X_CHOOSE_THEN `op2:A`
                                        (X_CHOOSE_THEN `paa2:A`
                                         (X_CHOOSE_THEN `pab2:A`
                                          (X_CHOOSE_THEN `sa2:A`
                                           (X_CHOOSE_THEN `sab2:A`
                                            (X_CHOOSE_THEN `psa2:A`
                                                (X_CHOOSE_THEN `psab2:A`
        STRIP_ASSUME_TAC)))))))))))) THEN
  (* ---- B-memberships of qy, ey, cc ---- *)
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`op2:A`;`f:A`;`qy:A`]
     EBV_IN_IN_B) THEN ANTS_TAC THENL
  [REPEAT CONJ_TAC THEN CLOSE; DISCH_TAC] THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`prG:A`;`y:A`;`ey:A`]
     EBV_EQ_IN_B) THEN ANTS_TAC THENL
  [REPEAT CONJ_TAC THEN CLOSE; DISCH_TAC] THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`qy:A`;`ey:A`;`cc:A`]
     EMEET_IN) THEN ANTS_TAC THENL [CLOSE; STRIP_TAC] THEN
  (* ---- calp2 = echeck(alpha2) ---- *)
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`onebee:A`;`al2:A`]
         ECHECK_EXHAUSTION) THEN
  ANTS_TAC THENL
  [REPEAT CONJ_TAC THEN CLOSE; DISCH_THEN(X_CHOOSE_TAC `calp2:A`)] THEN
  SUBGOAL_THEN `(calp2:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[ECHECK_IMP]; ALL_TAC] THEN
  (* ---- bnames xic, xic2, calp2, y ---- *)
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`onebee:A`;`B:A`;`xi:A`;`xic:A`]
     ECHECK_IS_BNAME) THEN ANTS_TAC THENL
  [REPEAT CONJ_TAC THEN CLOSE; DISCH_TAC] THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`onebee:A`;`B:A`;`xi2:A`;`xic2:A`]
     ECHECK_IS_BNAME) THEN ANTS_TAC THENL
  [REPEAT CONJ_TAC THEN CLOSE; DISCH_TAC] THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`onebee:A`;`B:A`;`al2:A`;`calp2:A`]
     ECHECK_IS_BNAME) THEN ANTS_TAC THENL
  [REPEAT CONJ_TAC THEN CLOSE; DISCH_TAC] THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`onebee:A`;`B:A`;`cp2:A`;`y:A`]
     ECHECK_IS_BNAME) THEN ANTS_TAC THENL
  [REPEAT CONJ_TAC THEN CLOSE; DISCH_TAC] THEN
  (* ---- bname rdot2 (rtot at alpha2 + EAPPLY_UNIQUE) ---- *)
  USE_THEN "rtot" (MP_TAC o SPEC `al2:A`) THEN
  ANTS_TAC THENL [CONJ_TAC THEN CLOSE; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `rd3:A` STRIP_ASSUME_TAC) THEN
  SUBGOAL_THEN `rd3:A = rdot2` SUBST_ALL_TAC THENL
   [MP_TAC(ISPECL
           [`D:A->bool`;`E:A->A->bool`;`realfn:A`;`al2:A`;`rd3:A`;`rdot2:A`]
           EAPPLY_UNIQUE) THEN
    ANTS_TAC THENL [REPEAT CONJ_TAC THEN CLOSE; DISCH_THEN ACCEPT_TAC];
    ALL_TAC] THEN
  (* ---- OPNCELL_BNAME_BUNDLE : bname op2/sa2/sab2 + eapply bundle ---- *)
  MP_TAC(ISPECL
         [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`xic2:A`;
          `rdot2:A`;`onebee:A`;
          `paa2:A`;`pab2:A`;`sa2:A`;`sab2:A`;`psa2:A`;`psab2:A`;`op2:A`]
     OPNCELL_BNAME_BUNDLE) THEN
  ANTS_TAC THENL [REPEAT CONJ_TAC THEN CLOSE; STRIP_TAC] THEN
  (* ---- ECHECK_KUR_AUTO : sk,pk + y-ckp bundle ---- *)
  MP_TAC(ISPECL
         [`D:A->bool`;`E:A->A->bool`;`B:A`;`onebee:A`;`xi2:A`;`al2:A`;`xic2:A`;
          `calp2:A`;`cp2:A`;`y:A`] ECHECK_KUR_AUTO) THEN
  ANTS_TAC THENL [REPEAT CONJ_TAC THEN CLOSE;
    DISCH_THEN(X_CHOOSE_THEN `sk:A`
               (X_CHOOSE_THEN `pk:A` STRIP_ASSUME_TAC))] THEN
  (* ---- e1v = [[xx=xic2]], e2v = [[Gn=calp2]] ---- *)
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`xx:A`;`xic2:A`]
     EBV_EQ_VAL_EXISTS) THEN
  ANTS_TAC THENL [REPEAT CONJ_TAC THEN CLOSE;
    DISCH_THEN(X_CHOOSE_THEN `e1v:A` STRIP_ASSUME_TAC)] THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`Gn:A`;`calp2:A`]
     EBV_EQ_VAL_EXISTS) THEN
  ANTS_TAC THENL [REPEAT CONJ_TAC THEN CLOSE;
    DISCH_THEN(X_CHOOSE_THEN `e2v:A` STRIP_ASSUME_TAC)] THEN
  (* ---- PROJ1 -> erel ey e1v ; PROJ2 -> erel ey e2v ---- *)
  MP_TAC(ISPECL
         [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`onebee:A`;`xx:A`;`Gn:A`;
          `xic2:A`;`calp2:A`;`prG:A`;`sG:A`;`pG:A`;`sk:A`;`pk:A`;`y:A`;
          `ey:A`;`e1v:A`]
     EBV_EQ_KURCHECK_PROJ1) THEN
  ANTS_TAC THENL [REPEAT CONJ_TAC THEN CLOSE; DISCH_TAC] THEN
  MP_TAC(ISPECL
         [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`onebee:A`;`xx:A`;`Gn:A`;
          `xic2:A`;`calp2:A`;`prG:A`;`sG:A`;`pG:A`;`sk:A`;`pk:A`;`y:A`;`ey:A`;
                 `e1v:A`;`e2v:A`;`xi2:A`;`al2:A`] EBV_EQ_KURCHECK_PROJ2) THEN
  ANTS_TAC THENL [REPEAT CONJ_TAC THEN CLOSE; DISCH_TAC] THEN
  (* ---- prep (branch-independent): ebalg, eporder, E wdia B, zc=meet(cc,s),
          the zc<=... chain, eqv=[[rdota=rdot2]] ---- *)
  SUBGOAL_THEN `ebalg D (E:A->A->bool) B leq` ASSUME_TAC THENL
   [ASM_MESON_TAC[ECBA_IMP_BALG]; ALL_TAC] THEN
  SUBGOAL_THEN `eporder D (E:A->A->bool) B leq` ASSUME_TAC THENL
   [ASM_MESON_TAC[ECBA_IMP_PORDER]; ALL_TAC] THEN
  MP_TAC(ISPECL
         [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`opa:A`;`f:A`;`wdia:A`]
         EBV_IN_IN_B) THEN ANTS_TAC THENL
  [REPEAT CONJ_TAC THEN CLOSE; DISCH_TAC] THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`cc:A`;`s:A`]
         EBALG_MEET) THEN
  ANTS_TAC THENL
  [REPEAT CONJ_TAC THEN CLOSE; DISCH_THEN(X_CHOOSE_TAC `zc:A`)] THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`cc:A`;`s:A`;`zc:A`]
         EMEET_IN) THEN
  ANTS_TAC THENL [CLOSE; STRIP_TAC] THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`cc:A`;`s:A`;`zc:A`]
         EMEET_LE) THEN
  ANTS_TAC THENL [CLOSE; STRIP_TAC] THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`qy:A`;`ey:A`;`cc:A`]
         EMEET_LE) THEN
  ANTS_TAC THENL [CLOSE; STRIP_TAC] THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`zc:A`;`cc:A`;`qy:A`]
     EPORDER_TRANS) THEN ANTS_TAC THENL
  [REPEAT CONJ_TAC THEN CLOSE; DISCH_TAC] THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`zc:A`;`s:A`;`c:A`]
     EPORDER_TRANS) THEN ANTS_TAC THENL
  [REPEAT CONJ_TAC THEN CLOSE; DISCH_TAC] THEN
  MP_TAC(ISPECL
         [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`zc:A`;`s:A`;`wdia:A`]
         EPORDER_TRANS) THEN ANTS_TAC THENL
  [REPEAT CONJ_TAC THEN CLOSE; DISCH_TAC] THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`zc:A`;`cc:A`;`ey:A`]
     EPORDER_TRANS) THEN ANTS_TAC THENL
  [REPEAT CONJ_TAC THEN CLOSE; DISCH_TAC] THEN
  MP_TAC(ISPECL
         [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`zc:A`;`ey:A`;`e1v:A`]
         EPORDER_TRANS) THEN ANTS_TAC THENL
  [REPEAT CONJ_TAC THEN CLOSE; DISCH_TAC] THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`zc:A`;`s:A`;`exi:A`]
     EPORDER_TRANS) THEN ANTS_TAC THENL
  [REPEAT CONJ_TAC THEN CLOSE; DISCH_TAC] THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`rdota:A`;`rdot2:A`]
     EBV_EQ_VAL_EXISTS) THEN
  ANTS_TAC THENL [REPEAT CONJ_TAC THEN CLOSE;
    DISCH_THEN(X_CHOOSE_THEN `eqv:A` STRIP_ASSUME_TAC)] THEN
  (* ================= case split ================= *)
  ASM_CASES_TAC `xi2:A = xi` THENL
   [ (* ===== xi2 = xi ===== *)
    POP_ASSUM SUBST_ALL_TAC THEN
    MP_TAC(ISPECL
           [`D:A->bool`;`E:A->A->bool`;`onebee:A`;`xi:A`;`xic2:A`;`xic:A`]
           ECHECK_SV) THEN
    ANTS_TAC THENL [REPEAT CONJ_TAC THEN CLOSE; DISCH_THEN SUBST_ALL_TAC] THEN
    ASM_CASES_TAC `al2:A = a` THENL
     [ (* --- DIAG : alpha2 = a --- *)
      POP_ASSUM SUBST_ALL_TAC THEN
      MP_TAC(ISPECL
             [`D:A->bool`;`E:A->A->bool`;`onebee:A`;`a:A`;`calp2:A`;`ca:A`]
             ECHECK_SV) THEN
      ANTS_TAC THENL
      [REPEAT CONJ_TAC THEN CLOSE; DISCH_THEN SUBST_ALL_TAC] THEN
      DISJ1_TAC THEN EXISTS_TAC `e2v:A` THEN REPEAT CONJ_TAC THEN CLOSE;
      (* --- OFF_AL : alpha2 <> a (Gap3) --- *)
      MP_TAC(ISPECL
             [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`wf:num->A`;`c:A`;`f:A`;
              `xic:A`;`rdota:A`;`rdot2:A`;`onebee:A`;`sda:A`;`pda:A`;`opa:A`;
                     `wdia:A`;`sa2:A`;`sab2:A`;`op2:A`;`qy:A`;`eqv:A`;`zc:A`]
         BVALF_SVF_INCOMPAT) THEN
      ANTS_TAC THENL [REPEAT CONJ_TAC THEN CLOSE; DISCH_TAC] THEN
      USE_THEN "distinct"
        (MP_TAC o SPECL [`al2:A`;`rdota:A`;`rdot2:A`;`eqv:A`]) THEN
        ANTS_TAC THENL [REPEAT CONJ_TAC THEN CLOSE; DISCH_TAC] THEN
      MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`zc:A`;`eqv:A`]
             ELE_BOT) THEN
      ANTS_TAC THENL [REPEAT CONJ_TAC THEN CLOSE; DISCH_TAC] THEN
      DISJ2_TAC THEN EXISTS_TAC `zc:A` THEN REPEAT CONJ_TAC THENL
       [CLOSE; CLOSE; CLOSE; ASM_MESON_TAC[]]];
    (* ===== OFF_XI : xi2 <> xi ===== *)
    MP_TAC(ISPECL
           [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`xx:A`;`xic2:A`;`e1v:A`]
           EBV_EQ_SYM) THEN ANTS_TAC THENL
    [REPEAT CONJ_TAC THEN CLOSE; DISCH_TAC] THEN
    MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`xic2:A`;`xic:A`]
       EBV_EQ_VAL_EXISTS) THEN
    ANTS_TAC THENL [REPEAT CONJ_TAC THEN CLOSE;
      DISCH_THEN(X_CHOOSE_THEN `vcc:A` STRIP_ASSUME_TAC)] THEN
    MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`e1v:A`;`exi:A`]
           EBALG_MEET) THEN
    ANTS_TAC THENL
    [REPEAT CONJ_TAC THEN CLOSE; DISCH_THEN(X_CHOOSE_TAC `me:A`)] THEN
    MP_TAC(ISPECL
           [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`e1v:A`;`exi:A`;`me:A`]
           EMEET_IN) THEN ANTS_TAC THENL [CLOSE; STRIP_TAC] THEN
    MP_TAC(ISPECL
           [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`e1v:A`;`exi:A`;
            `me:A`;`zc:A`]
           EMEET_GREATEST) THEN ANTS_TAC THENL
    [REPEAT CONJ_TAC THEN CLOSE; DISCH_TAC] THEN
    MP_TAC(ISPECL
           [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`xic2:A`;`xx:A`;`xic:A`;
            `e1v:A`;`exi:A`;`vcc:A`;`me:A`] EBV_EQ_CONG) THEN
    ANTS_TAC THENL [REPEAT CONJ_TAC THEN CLOSE; DISCH_TAC] THEN
    MP_TAC(ISPECL
           [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`zc:A`;`me:A`;`vcc:A`]
           EPORDER_TRANS) THEN ANTS_TAC THENL
    [REPEAT CONJ_TAC THEN CLOSE; DISCH_TAC] THEN
    MP_TAC(ISPECL
           [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`onebee:A`;`xi2:A`;`xi:A`;
            `xic2:A`;`xic:A`;`vcc:A`] ECHECK_EQ_BOT) THEN
    ANTS_TAC THENL [REPEAT CONJ_TAC THEN CLOSE; DISCH_TAC] THEN
    MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`zc:A`;`vcc:A`]
           ELE_BOT) THEN
    ANTS_TAC THENL [REPEAT CONJ_TAC THEN CLOSE; DISCH_TAC] THEN
    DISJ2_TAC THEN EXISTS_TAC `zc:A` THEN REPEAT CONJ_TAC THENL
     [CLOSE; CLOSE; CLOSE; ASM_MESON_TAC[]]]);;

(* =======================================================================
   B3_STEP7_TEST2 : slimmed B3_STEP7_TEST.
   Drops the 4 spurious `E _ B` hyps for the B-NAMES Gn, ca, prA, prG
   (ebv_in / ebv_eq take B-names in slot u; EBV_IN_LE_V/GE_TERM_V need only
   `u IN D` -- NOT `E u B`).  In the real setting
   Gn/ca/prA/prG are echeck / Kuratowski names, NOT Boolean values, so
   `E prA B` etc. are unprovable; they must not be hyps.  Proof body identical.
   ======================================================================= *)

let B3_STEP7_TEST2 = prove
 (`!D (E:A->A->bool) B leq s agn Gn h prA prG mA mG ydia wdia eyA ca.
     ecba D E B leq /\ model D E ZF_AX /\
     B IN D /\ leq IN D /\
     s IN D /\ agn IN D /\ Gn IN D /\ h IN D /\ prA IN D /\ prG IN D /\
     mA IN D /\ mG IN D /\ ydia IN D /\ wdia IN D /\ eyA IN D /\ ca IN D /\
     E s B /\ E agn B /\ E mA B /\ E mG B /\
     E wdia B /\ E eyA B /\
     ebv_in D E B leq prA h mA /\ ebv_in D E B leq prG h mG /\
     eapply D E h ydia wdia /\ ebv_eq D E B leq prA ydia eyA /\
     erel D E leq s wdia /\ erel D E leq s eyA /\
     erel D E leq mA mG /\
     ebv_eq D E B leq ca Gn agn /\
     (!y qy ey cc.
          y IN D /\ qy IN D /\ ey IN D /\ cc IN D /\
          eapply D E h y qy /\ ebv_eq D E B leq prG y ey /\
          emeet D E B leq qy ey cc
          ==> (?ea. ea IN D /\ E ea B /\ ebv_eq D E B leq Gn ca ea /\
                    erel D E leq ey ea) \/
              (?z. z IN D /\ E z B /\ emeet D E B leq cc s z /\
                   ebot D E B leq z))
     ==> erel D E leq s agn`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `ebalg D (E:A->A->bool) B leq /\ eporder D E B leq`
    STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[ECBA_IMP_BALG; EBALG_IMP_PORDER]; ALL_TAC] THEN
  SUBGOAL_THEN `?w0:A. ebimp D (E:A->A->bool) B leq s agn w0`
    (X_CHOOSE_TAC `w0:A`) THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`s:A`;`agn:A`]
                 EBIMP_EXISTS) THEN ASM_MESON_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(w0:A) IN D /\ (E:A->A->bool) w0 B` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[EBIMP_IN]; ALL_TAC] THEN
  SUBGOAL_THEN
   `!y qy ey cc.
        y IN D /\ qy IN D /\ ey IN D /\ cc IN D /\
        eapply D (E:A->A->bool) h y qy /\ ebv_eq D E B leq prG y ey /\
        emeet D E B leq qy ey cc
        ==> erel D E leq cc w0`
   (LABEL_TAC "per") THENL
   [MAP_EVERY X_GEN_TAC [`y:A`;`qy:A`;`ey:A`;`cc:A`] THEN STRIP_TAC THEN
    SUBGOAL_THEN `(E:A->A->bool) cc B` ASSUME_TAC THENL
     [ASM_MESON_TAC[EMEET_IN]; ALL_TAC] THEN
    SUBGOAL_THEN `?mcs:A. emeet D (E:A->A->bool) B leq cc s mcs`
      (X_CHOOSE_TAC `mcs:A`) THENL
     [MATCH_MP_TAC(ISPECL
                   [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`cc:A`;`s:A`]
                   EBALG_MEET) THEN ASM_MESON_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN `(mcs:A) IN D /\ (E:A->A->bool) mcs B` STRIP_ASSUME_TAC THENL
     [ASM_MESON_TAC[EMEET_IN]; ALL_TAC] THEN
    SUBGOAL_THEN `erel D (E:A->A->bool) leq mcs agn` ASSUME_TAC THENL
     [FIRST_X_ASSUM(MP_TAC o ISPECL [`y:A`;`qy:A`;`ey:A`;`cc:A`] o
         check (fun th -> is_forall(concl th) &&
                vfree_in `prG:A` (concl th))) THEN
      ANTS_TAC THENL [ASM_MESON_TAC[]; ALL_TAC] THEN
      DISCH_THEN STRIP_ASSUME_TAC THENL
       [SUBGOAL_THEN `ebv_eq D (E:A->A->bool) B leq ca Gn ea` ASSUME_TAC THENL
         [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`Gn:A`;
             `ca:A`;`ea:A`] EBV_EQ_SYM) THEN ASM_MESON_TAC[]; ALL_TAC] THEN
        SUBGOAL_THEN `(ea:A) = agn` SUBST_ALL_TAC THENL
         [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`ca:A`;
             `Gn:A`;`ea:A`;`agn:A`] EBV_EQ_UNIQUE) THEN ASM_MESON_TAC[];
                ALL_TAC] THEN
        SUBGOAL_THEN `erel D (E:A->A->bool) leq cc ey` ASSUME_TAC THENL
         [ASM_MESON_TAC[EMEET_LE]; ALL_TAC] THEN
        SUBGOAL_THEN `(E:A->A->bool) ey B` ASSUME_TAC THENL
         [ASM_MESON_TAC[EBV_EQ_IN_B]; ALL_TAC] THEN
        SUBGOAL_THEN `erel D (E:A->A->bool) leq cc agn` ASSUME_TAC THENL
         [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`cc:A`;
             `ey:A`;`agn:A`] EPORDER_TRANS) THEN ASM_MESON_TAC[]; ALL_TAC] THEN
        SUBGOAL_THEN `erel D (E:A->A->bool) leq mcs cc` ASSUME_TAC THENL
         [ASM_MESON_TAC[EMEET_LE]; ALL_TAC] THEN
        MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`mcs:A`;
            `cc:A`;`agn:A`] EPORDER_TRANS) THEN ASM_MESON_TAC[];
        SUBGOAL_THEN `(mcs:A) = z` SUBST_ALL_TAC THENL
         [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`cc:A`;
             `s:A`;`mcs:A`;`z:A`] EMEET_UNIQUE) THEN ASM_MESON_TAC[];
                ALL_TAC] THEN
        MATCH_MP_TAC(ISPECL
                     [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`z:A`;`agn:A`]
                     EBOT_LE) THEN ASM_MESON_TAC[]];
      ALL_TAC] THEN
    MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`cc:A`;`s:A`;
        `agn:A`;`w0:A`;`mcs:A`] EBIMP_LE_IMP) THEN ASM_MESON_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq mG w0` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`prG:A`;`h:A`;
                  `mG:A`;`w0:A`] EBV_IN_LE_V) THEN
    REPEAT CONJ_TAC THEN TRY(FIRST_ASSUM ACCEPT_TAC) THEN ASM_MESON_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `?cdia:A. emeet D (E:A->A->bool) B leq wdia eyA cdia`
    (X_CHOOSE_TAC `cdia:A`) THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`wdia:A`;`eyA:A`]
                 EBALG_MEET) THEN ASM_MESON_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(cdia:A) IN D /\ (E:A->A->bool) cdia B` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[EMEET_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq s cdia` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`wdia:A`;`eyA:A`;
                  `cdia:A`;`s:A`] EMEET_GREATEST) THEN ASM_MESON_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq cdia mA` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`prA:A`;`h:A`;
                  `mA:A`;`ydia:A`;`wdia:A`;`eyA:A`;`cdia:A`]
                   EBV_IN_GE_TERM_V) THEN
    ASM_MESON_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq s mA` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`s:A`;`cdia:A`;
                  `mA:A`] EPORDER_TRANS) THEN ASM_MESON_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq s mG` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`s:A`;`mA:A`;
       `mG:A`] EPORDER_TRANS) THEN ASM_MESON_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `?mgs:A. emeet D (E:A->A->bool) B leq mG s mgs`
    (X_CHOOSE_TAC `mgs:A`) THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`mG:A`;`s:A`]
       EBALG_MEET) THEN ASM_MESON_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(mgs:A) IN D /\ (E:A->A->bool) mgs B` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[EMEET_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq mgs agn` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`mG:A`;`s:A`;
       `agn:A`;`w0:A`;`mgs:A`] EBIMP_MEET_LE) THEN ASM_MESON_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq s mgs` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`mG:A`;`s:A`;
       `mgs:A`;`s:A`] EMEET_GREATEST) THEN ASM_MESON_TAC[EPORDER_REFL];
    ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq mgs s` ASSUME_TAC THENL
   [ASM_MESON_TAC[EMEET_LE]; ALL_TAC] THEN
  SUBGOAL_THEN `(mgs:A) = s` SUBST_ALL_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`mgs:A`;`s:A`]
                 EPORDER_ANTISYM) THEN ASM_MESON_TAC[]; ALL_TAC] THEN
  FIRST_ASSUM ACCEPT_TAC);;

(* =======================================================================
   B3_STEP7_REAL : the REAL-setting instance of the B3 step-7 obligation.

   erel s agn  (i.e. s <= [[ <xi>^ , Gn >  IN  SVbody ]] )  under the real
   coverage antecedent (= B3_STEP7_COVERAGE's hypotheses) plus the "extras":
     - h is a B-name whose cells are opn-cell pairs,
     - ydia = <xi,a>^ , wdia = h(ydia),
     - the two slot facts wf 70 = xx, wf 72 = h,
     - the valname equation  [[ pm ]]_{(71|->Gn)wf} = [[ ??71 pm ]]_wf,
     - agn = [[ ca = Gn ]].

   Proof = assemble COVERAGE (-> coverage impl) with TEST2 (-> erel s agn),
   discharging TEST2's two residual obligations:
     7a  erel s eyA   (EBV_EQ_REFL + EMEET_TOP + EBV_EQ_KUR_CONG +
       EPORDER_TRANS)
     7b  erel mA mG   (PMEM_GE at (71|->ca)wf -> EX_UB -> valname eqn
                        -> PMEM_LE at (71|->Gn)wf, chained by EPORDER_TRANS).

   The goal is built programmatically from B3_STEP7_COVERAGE's antecedent so
   the coverage discharge is an exact assumption match.  Uses
   B3_STEP7_COVERAGE, B3_STEP7_TEST2, and
   the @-lemmas EOPAIRNAME_CANON / ECHECK_KUR_AUTO / EBV_*_VAL_EXISTS /
   EBV_EQ_REFL / EMEET_TOP / EBV_EQ_KUR_CONG / BVALF_PMEM_GE / BVALF_EX_UB /
   BVALF_PMEM_LE / BVALF_IN_B / EPORDER_TRANS / EBV_IN_IN_B / EBV_EQ_IN_B /
   ECHECK_IS_BNAME / ETOP_UNIQUE / VALUATION_VALMOD / BNAMEVAL_VALMOD.
   ======================================================================= *)

let B3_STEP7_REAL =
  let CLOSE = FIRST_ASSUM ACCEPT_TAC ORELSE FIRST_ASSUM MATCH_ACCEPT_TAC in
  let b3r_cov_ante =
    fst(dest_imp(snd(strip_forall(concl B3_STEP7_COVERAGE)))) in
  let b3r_extras =
    `bname D (E:A->A->bool) B h /\
     eopair D E xi a cp /\ echeck D E onebee cp ydia /\
     eapply D E h ydia wdia /\
     (wf:num->A) 70 = xx /\ wf 72 = h /\
     bvalf D E B leq ((71 |-> Gn) wf)
       (?? 73 (opair_form 70 71 73 && (73 %% 72))) =
     bvalf D E B leq wf
       (?? 71 (?? 73 (opair_form 70 71 73 && (73 %% 72)))) /\
     ebv_eq D E B leq ca Gn agn /\ agn IN D` in
  let b3r_imp =
    mk_imp(mk_conj(b3r_cov_ante, b3r_extras),
           `erel D (E:A->A->bool) leq s agn`) in
  prove
 (b3r_imp,
  STRIP_TAC THEN
  SUBGOAL_THEN `(cp:A) IN D /\ (ydia:A) IN D` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[ECHECK_IMP]; ALL_TAC] THEN
  (* ---- C2 : ebalg/eporder + bnames ca, xic, ydia ---- *)
  SUBGOAL_THEN `ebalg D (E:A->A->bool) B leq /\ eporder D E B leq`
    STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[ECBA_IMP_BALG; EBALG_IMP_PORDER]; ALL_TAC] THEN
  SUBGOAL_THEN `bname D (E:A->A->bool) B ca` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`onebee:A`;`B:A`;`a:A`;`ca:A`]
                 ECHECK_IS_BNAME) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `bname D (E:A->A->bool) B xic` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`onebee:A`;`B:A`;`xi:A`;`xic:A`]
                 ECHECK_IS_BNAME) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `bname D (E:A->A->bool) B ydia` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`onebee:A`;`B:A`;`cp:A`;`ydia:A`]
                 ECHECK_IS_BNAME) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* ---- C3 : EOPAIRNAME_CANON(xx,ca) -> prA bundle; mA = [[prA IN h]] ---- *)
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`xx:A`;`ca:A`]
     EOPAIRNAME_CANON) THEN
  ANTS_TAC THENL [REPEAT CONJ_TAC THEN CLOSE; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `prA:A` (X_CHOOSE_THEN `sA:A` (X_CHOOSE_THEN `sAB:A`
      (X_CHOOSE_THEN `tpA:A` (X_CHOOSE_THEN `paa:A` (X_CHOOSE_THEN `pab:A`
       (X_CHOOSE_THEN `psa:A`
        (X_CHOOSE_THEN `psab:A` STRIP_ASSUME_TAC)))))))) THEN
  SUBGOAL_THEN `tpA:A = onebee` SUBST_ALL_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`tpA:A`;`onebee:A`]
                 ETOP_UNIQUE) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`prA:A`;`h:A`]
     EBV_IN_VAL_EXISTS) THEN
  ANTS_TAC THENL [REPEAT CONJ_TAC THEN CLOSE; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `mA:A` STRIP_ASSUME_TAC) THEN
  (* ---- C4 : ECHECK_KUR_AUTO(ydia) -> sk,pk; eyA = [[prA=ydia]]; mG = *)
  (* [[prG IN h]] ---- *)
  MP_TAC(ISPECL
         [`D:A->bool`;`E:A->A->bool`;`B:A`;`onebee:A`;`xi:A`;`a:A`;`xic:A`;
          `ca:A`;`cp:A`;`ydia:A`] ECHECK_KUR_AUTO) THEN
  ANTS_TAC THENL [REPEAT CONJ_TAC THEN CLOSE; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `sk:A` (X_CHOOSE_THEN `pk:A` STRIP_ASSUME_TAC)) THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`prA:A`;`ydia:A`]
     EBV_EQ_VAL_EXISTS) THEN
  ANTS_TAC THENL [REPEAT CONJ_TAC THEN CLOSE; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `eyA:A` STRIP_ASSUME_TAC) THEN
