  SUBGOAL_THEN `erel D (E:A->A->bool) leq s eyA` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`s:A`;
                  `exi:A`;`eyA:A`]
                 EPORDER_TRANS) THEN REPEAT CONJ_TAC THEN CLOSE; ALL_TAC] THEN
  (* ---- C6a : v1 = (71|->ca)wf  valuation / bname / slots ---- *)
  ABBREV_TAC `v1 = (71 |-> ca) (wf:num->A)` THEN
  SUBGOAL_THEN `valuation D (v1:num->A) /\ (!k. bname D E B ((v1:num->A) k))`
