      MATCH_MP_TAC BNAMEVAL_VALMOD THEN ASM_REWRITE_TAC[]]; ALL_TAC] THEN
  SUBGOAL_THEN
    `(v1:num->A) 70 = xx /\ (v1:num->A) 71 = ca /\ (v1:num->A) 72 = h`
    STRIP_ASSUME_TAC THENL
   [EXPAND_TAC "v1" THEN ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER; ARITH_EQ];
    ALL_TAC] THEN
  (* ---- C6b : BVALF_PMEM_GE at v1  ->  erel mA [[v1,pm]] ---- *)
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`v1:num->A`;
     `sA:A`;`sAB:A`;`prA:A`;`onebee:A`;`mA:A`] BVALF_PMEM_GE) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[] THEN REPEAT CONJ_TAC THEN
    TRY(FIRST_ASSUM ACCEPT_TAC) THEN ASM_MESON_TAC[]; ALL_TAC] THEN
  DISCH_TAC THEN
  (* ---- C7i : BVALF_EX_UB(71,pm,wf,ca)  ->  erel [[v1,pm]] [[??71 pm]] *)
  (* ---- *)
  MP_TAC(ISPECL [`71`; `?? 73 (opair_form 70 71 73 && (73 %% 72))`;
     `D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`wf:num->A`;`ca:A`]
      BVALF_EX_UB) THEN
  ANTS_TAC THENL [REPEAT CONJ_TAC THEN CLOSE; ALL_TAC] THEN
  ASM_REWRITE_TAC[] THEN DISCH_TAC THEN
  (* ---- C7ii : v2 = (71|->Gn)wf  valuation / bname / slots ---- *)
  SUBGOAL_THEN
    `valuation D ((71 |-> Gn) (wf:num->A)) /\
     (!k. bname D E B (((71 |-> Gn) (wf:num->A)) k))` STRIP_ASSUME_TAC THENL
   [CONJ_TAC THENL
     [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[];
      MATCH_MP_TAC BNAMEVAL_VALMOD THEN ASM_REWRITE_TAC[]]; ALL_TAC] THEN
