     ((71 |-> Gn) (wf:num->A)) 72 = h` STRIP_ASSUME_TAC THENL
   [ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER; ARITH_EQ]; ALL_TAC] THEN
  (* ---- C7iv : BVALF_PMEM_LE at v2 ; fold via valname eqn -> erel [[??71 *)
  (* pm]] mG ---- *)
  MP_TAC(ISPECL
         [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`(71 |-> Gn) (wf:num->A)`;
          `sG:A`;`pG:A`;`prG:A`;`onebee:A`;`mG:A`] BVALF_PMEM_LE) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[] THEN REPEAT CONJ_TAC THEN
    TRY(FIRST_ASSUM ACCEPT_TAC) THEN ASM_MESON_TAC[];
    ASM_REWRITE_TAC[] THEN DISCH_TAC] THEN
  (* ---- C8 : bvalf carrier facts + EPORDER_TRANS x2  ->  erel mA mG (7b) *)
  (* ---- *)
  MP_TAC(ISPECL [`?? 73 (opair_form 70 71 73 && (73 %% 72))`;
     `D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`v1:num->A`] BVALF_IN_B) THEN
  ANTS_TAC THENL [REPEAT CONJ_TAC THEN CLOSE; DISCH_TAC] THEN
  MP_TAC(ISPECL [`?? 73 (opair_form 70 71 73 && (73 %% 72))`;
     `D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`v1:num->A`] BVALF_IND) THEN
  ANTS_TAC THENL [REPEAT CONJ_TAC THEN CLOSE; DISCH_TAC] THEN
  MP_TAC(ISPECL [`?? 71 (?? 73 (opair_form 70 71 73 && (73 %% 72)))`;
     `D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`wf:num->A`] BVALF_IN_B) THEN
  ANTS_TAC THENL [REPEAT CONJ_TAC THEN CLOSE; DISCH_TAC] THEN
  MP_TAC(ISPECL [`?? 71 (?? 73 (opair_form 70 71 73 && (73 %% 72)))`;
     `D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`wf:num->A`] BVALF_IND) THEN
  ANTS_TAC THENL [REPEAT CONJ_TAC THEN CLOSE; DISCH_TAC] THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`mA:A`;
     `bvalf D (E:A->A->bool) B leq v1
      (?? 73 (opair_form 70 71 73 && (73 %% 72)))`;
     `bvalf D (E:A->A->bool) B leq wf
      (?? 71 (?? 73 (opair_form 70 71 73 && (73 %% 72))))`]
     EPORDER_TRANS) THEN
  ANTS_TAC THENL [REPEAT CONJ_TAC THEN CLOSE; DISCH_TAC] THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`mA:A`;
     `bvalf D (E:A->A->bool) B leq wf
      (?? 71 (?? 73 (opair_form 70 71 73 && (73 %% 72))))`;
     `mG:A`] EPORDER_TRANS) THEN
  ANTS_TAC THENL [REPEAT CONJ_TAC THEN CLOSE; DISCH_TAC] THEN
  (* ---- C9 : discharge B3_STEP7_COVERAGE -> coverage impl ---- *)
  MP_TAC(ISPECL
         [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`onebee:A`;`realfn:A`;
          `f:A`;`a1:A`;`a2:A`;`cr:A`;`h:A`;`xi:A`;`a:A`;`xic:A`;
          `rdota:A`;`ca:A`;
          `xx:A`;`Gn:A`;`prG:A`;`sG:A`;`pG:A`;`sda:A`;`pda:A`;`opa:A`;
          `wf:num->A`;
          `c:A`;`s:A`;`exi:A`;`wdia:A`] B3_STEP7_COVERAGE) THEN
  ANTS_TAC THENL [REPEAT CONJ_TAC THEN CLOSE; DISCH_TAC] THEN
  (* ---- C10 : carriers E wdia B, E agn B ; close via B3_STEP7_TEST2 ---- *)
  MP_TAC(ISPECL
         [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`opa:A`;`f:A`;`wdia:A`]
         EBV_IN_IN_B) THEN
  ANTS_TAC THENL [REPEAT CONJ_TAC THEN CLOSE; DISCH_TAC] THEN
