         [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`s:A`;`agn:A`;`Gn:A`;`h:A`;
          `prA:A`;`prG:A`;`mA:A`;`mG:A`;`ydia:A`;`wdia:A`;`eyA:A`;`ca:A`]
