  ANTS_TAC THENL [REPEAT CONJ_TAC THEN CLOSE; ALL_TAC] THEN
  DISCH_THEN ACCEPT_TAC);;

(* ===================================================================== *)
(*  SVH_MAIN : single-valuedness of the Kuratowski-encoded relation h.   *)
(*  If c forces  !!4!!5!!6((apply 3 4 5 && apply 3 4 6) --> Eq 5 6)       *)
(*  ("h is single-valued as a function on slot 3"), then c forces        *)
(*  !!70 ??74 !!71 ((??73(opair 70 71 73 && 73%%72)) --> Eq 71 74)        *)
(*  (Kuratowski single-valuedness of h).  Monolithic replay of the       *)
(*  interactive ladder svh_s0..svh_s8.                                   *)
(* ===================================================================== *)

let FVSV3 = prove
 (`FV (!! 4
       (!! 5 (!! 6
              ((apply_form 3 4 5 && apply_form 3 4 6) --> Eq 5 6)))) = {3}`,
  REWRITE_TAC[FV; FV_CLAUSES; FV_APPLY_FORM] THEN
  REWRITE_TAC[EXTENSION; IN_INSERT; NOT_IN_EMPTY; IN_UNION; IN_DELETE] THEN
  ARITH_TAC);;

let SVH_MAIN =
  let CLOSE = FIRST_ASSUM ACCEPT_TAC ORELSE FIRST_ASSUM MATCH_ACCEPT_TAC in
  prove
 (`!D (E:A->A->bool) B leq onebee realfn f a1 a2 cr a1c a2c h c v.
    model D E ZF_AX /\ (!u:A. u IN D ==> elmem D E u) /\
    ecba D E B leq /\ B IN D /\ leq IN D /\ onebee IN D /\ E onebee B /\
    etop D E B leq onebee /\
    realfn IN D /\ eisfun D E realfn /\ f IN D /\ bname D E B f /\
    h IN D /\ eisfun D E h /\ bname D E B h /\
    (!zz. zz IN D
         ==> (E zz h <=>
              ?cp xi alpha xic rdot op w cpc.
                   cp IN D /\ xi IN D /\ alpha IN D /\ xic IN D /\
                   rdot IN D /\ op IN D /\ w IN D /\ cpc IN D /\
                   E cp cr /\
                   eopair D E xi alpha cp /\ E xi a1 /\ E alpha a2 /\
                   echeck D E onebee xi xic /\ eapply D E realfn alpha rdot /\
                   (?paa pab sa sab psa psab.
                        paa IN D /\ pab IN D /\ sa IN D /\ sab IN D /\
                        psa IN D /\ psab IN D /\
                        eopair D E xic onebee paa /\
                          eopair D E rdot onebee pab /\
                        epair D E paa paa sa /\ epair D E paa pab sab /\
                        eopair D E sa onebee psa /\
                          eopair D E sab onebee psab /\
                        epair D E psa psab op) /\
                   ebv_in D E B leq op f w /\
                   echeck D E onebee cp cpc /\ eopair D E cpc w zz)) /\
    a1 IN D /\ a2 IN D /\ cr IN D /\ a1c IN D /\ a2c IN D /\
    ecross D E a1 a2 cr /\ echeck D E onebee a1 a1c /\
      echeck D E onebee a2 a2c /\
    (!aa. aa IN D /\ (E:A->A->bool) aa a2
          ==> ?rd. rd IN D /\ eapply D E realfn aa rd /\ bname D E B rd) /\
    (!b1 b2 rd1 rd2 e. b1 IN D /\ b2 IN D /\ rd1 IN D /\ rd2 IN D /\ e IN D /\
         (E:A->A->bool) b1 a2 /\ E b2 a2 /\ ~(b1 = b2) /\
         eapply D E realfn b1 rd1 /\ eapply D E realfn b2 rd2 /\
         ebv_eq D E B leq rd1 rd2 e
         ==> ebot D E B leq e) /\
    c IN D /\ E c B /\
    valuation D v /\ (!k. bname D E B (v k)) /\
    v 1 = a1c /\ v 3 = f /\ v 68 = a2c /\ v 69 = a1c /\ v 72 = h /\
    erel D E leq c
       (bvalf D E B leq v
          (!! 4 (!! 5
                 (!! 6 ((apply_form 3 4 5 && apply_form 3 4 6) --> Eq 5 6)))))
    ==> erel D E leq c
          (bvalf D E B leq v
             (!! 70 (?? 74 (!! 71 ((?? 73 (opair_form 70 71 73 && (73 %% 72)))
                                   --> Eq 71 74)))))`,
  EVERY
 [(* ---- S0 ---- *)
  REPEAT GEN_TAC THEN STRIP_TAC;
  FIRST_X_ASSUM(LABEL_TAC "hchar" o check (fun th ->
    is_forall(concl th) && vfree_in `h:A` (concl th) &&
      vfree_in `cr:A` (concl th)));
  FIRST_X_ASSUM(LABEL_TAC "rtot" o check (fun th ->
    is_forall(concl th) && vfree_in `realfn:A` (concl th) &&
    not(vfree_in `h:A` (concl th)) &&
      length(fst(strip_forall(concl th))) = 1));
  FIRST_X_ASSUM(LABEL_TAC "distinct" o check (fun th ->
    is_forall(concl th) && vfree_in `realfn:A` (concl th) &&
    length(fst(strip_forall(concl th))) = 5));
  SUBGOAL_THEN `ebalg D (E:A->A->bool) B leq /\ eporder D E B leq`
    STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[ECBA_IMP_BALG; EBALG_IMP_PORDER]; ALL_TAC];
  MATCH_MP_TAC(ISPECL [`70`;
    `?? 74 (!! 71 ((?? 73 (opair_form 70 71 73 && (73 %% 72))) --> Eq 71 74))`;
    `D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`v:num->A`;`c:A`]
               BVALF_ALL_GLB) THEN
  ASM_REWRITE_TAC[];
  X_GEN_TAC `xx:A` THEN STRIP_TAC;
  SUBGOAL_THEN `(xx:A) IN D` ASSUME_TAC THENL [ASM_MESON_TAC[]; ALL_TAC];
  (* ---- S1 ---- *)
  ABBREV_TAC `v70 = (70 |-> xx)(v:num->A)`;
  SUBGOAL_THEN `valuation D (v70:num->A) /\ (!k. bname D E B ((v70:num->A) k))`
    STRIP_ASSUME_TAC THENL
   [EXPAND_TAC "v70" THEN CONJ_TAC THENL
     [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[];
      MATCH_MP_TAC BNAMEVAL_VALMOD THEN ASM_REWRITE_TAC[]]; ALL_TAC];
  SUBGOAL_THEN
    `(v70:num->A) 70 = xx /\ (v70:num->A) 72 = h /\ (v70:num->A) 3 = f`
    STRIP_ASSUME_TAC THENL
   [EXPAND_TAC "v70" THEN
    ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER; ARITH_EQ]; ALL_TAC];
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`v70:num->A`]
         VALNAME_EXISTS) THEN
  ANTS_TAC THENL [REPEAT CONJ_TAC THEN CLOSE; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `Gn:A` STRIP_ASSUME_TAC);
  (* ---- S2 ---- *)
  SUBGOAL_THEN `valuation D ((74 |-> Gn) (v70:num->A)) /\
                (!k. bname D E B (((74 |-> Gn) (v70:num->A)) k))`
    STRIP_ASSUME_TAC THENL
   [CONJ_TAC THENL
     [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[];
      MATCH_MP_TAC BNAMEVAL_VALMOD THEN ASM_REWRITE_TAC[]]; ALL_TAC];
  SUBGOAL_THEN
    `((74 |-> Gn) (v70:num->A)) 70 = xx /\ ((74 |-> Gn) (v70:num->A)) 72 = h /\
     ((74 |-> Gn) (v70:num->A)) 74 = Gn /\ ((74 |-> Gn) (v70:num->A)) 3 = f`
    STRIP_ASSUME_TAC THENL
   [ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER; ARITH_EQ]; ALL_TAC];
  MP_TAC(ISPECL [`74`;
    `!! 71 ((?? 73 (opair_form 70 71 73 && (73 %% 72))) --> Eq 71 74)`;
    `D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`v70:num->A`;`Gn:A`]
       BVALF_EX_UB) THEN
  ANTS_TAC THENL [REPEAT CONJ_TAC THEN CLOSE; ALL_TAC] THEN DISCH_TAC;
  SUBGOAL_THEN `(E:A->A->bool) (bvalf D E B leq ((74 |-> Gn) (v70:num->A))
      (!! 71 ((?? 73 (opair_form 70 71 73 && (73 %% 72))) --> Eq 71 74))) B`
    ASSUME_TAC THENL
    [MATCH_MP_TAC(ISPECL
                  [`!! 71 ((?? 73 (opair_form 70 71 73 && (73 %% 72)))
                           --> Eq 71 74)`;
                   `D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
                   `(74 |-> Gn) (v70:num->A)`] BVALF_IN_B) THEN
    ASM_REWRITE_TAC[]; ALL_TAC];
  SUBGOAL_THEN `(bvalf D (E:A->A->bool) B leq ((74 |-> Gn) (v70:num->A))
      (!! 71 ((?? 73 (opair_form 70 71 73 && (73 %% 72))) --> Eq 71 74))) IN D`
    ASSUME_TAC THENL
    [MATCH_MP_TAC(ISPECL
                  [`!! 71 ((?? 73 (opair_form 70 71 73 && (73 %% 72)))
                           --> Eq 71 74)`;
                   `D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
                   `(74 |-> Gn) (v70:num->A)`] BVALF_IND) THEN
    ASM_REWRITE_TAC[]; ALL_TAC];
  SUBGOAL_THEN `(E:A->A->bool) (bvalf D E B leq (v70:num->A)
      (?? 74 (!! 71
              ((?? 73 (opair_form 70 71 73 && (73 %% 72))) --> Eq 71 74)))) B`
    ASSUME_TAC THENL
    [MATCH_MP_TAC(ISPECL
                  [`?? 74 (!! 71
                           ((?? 73 (opair_form 70 71 73 && (73 %% 72))) -->
                            Eq 71 74))`;
                   `D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`v70:num->A`]
                    BVALF_IN_B) THEN
    ASM_REWRITE_TAC[]; ALL_TAC];
  SUBGOAL_THEN `(bvalf D (E:A->A->bool) B leq (v70:num->A)
      (?? 74 (!! 71
              ((?? 73 (opair_form 70 71 73 && (73 %% 72))) --> Eq 71 74)))) IN
      D` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`?? 74 (!! 71
                          ((?? 73 (opair_form 70 71 73 && (73 %% 72))) -->
                           Eq 71 74))`;
                  `D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`v70:num->A`]
                   BVALF_IND) THEN
    ASM_REWRITE_TAC[]; ALL_TAC];
  MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`c:A`;
    `bvalf D E B leq ((74 |-> Gn) (v70:num->A))
       (!! 71 ((?? 73 (opair_form 70 71 73 && (73 %% 72))) --> Eq 71 74))`;
    `bvalf D E B leq (v70:num->A)
       (?? 74 (!! 71
               ((?? 73 (opair_form 70 71 73 && (73 %% 72))) --> Eq 71 74)))`]
    EPORDER_TRANS) THEN ASM_REWRITE_TAC[];
  (* ---- S3 ---- *)
  ABBREV_TAC `v74 = (74 |-> Gn)(v70:num->A)`;
  MATCH_MP_TAC(ISPECL [`71`;
    `(?? 73 (opair_form 70 71 73 && (73 %% 72))) --> Eq 71 74`;
    `D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`v74:num->A`;`c:A`]
      BVALF_ALL_GLB) THEN
  ASM_REWRITE_TAC[];
  X_GEN_TAC `yy:A` THEN STRIP_TAC;
  SUBGOAL_THEN `(yy:A) IN D` ASSUME_TAC THENL [ASM_MESON_TAC[]; ALL_TAC];
  ABBREV_TAC `v71 = (71 |-> yy)(v74:num->A)`;
  SUBGOAL_THEN `valuation D (v71:num->A) /\ (!k. bname D E B ((v71:num->A) k))`
    STRIP_ASSUME_TAC THENL
   [EXPAND_TAC "v71" THEN CONJ_TAC THENL
     [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[];
      MATCH_MP_TAC BNAMEVAL_VALMOD THEN ASM_REWRITE_TAC[]]; ALL_TAC];
  SUBGOAL_THEN
    `(v71:num->A) 70 = xx /\ (v71:num->A) 71 = yy /\ (v71:num->A) 72 = h /\
     (v71:num->A) 74 = Gn /\ (v71:num->A) 3 = f`
    STRIP_ASSUME_TAC THENL
   [EXPAND_TAC "v71" THEN
    ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER; ARITH_EQ]; ALL_TAC];
  (* ---- S4 ---- *)
  SUBGOAL_THEN `ebimp D (E:A->A->bool) B leq
      (bvalf D E B leq (v71:num->A)
       (?? 73 (opair_form 70 71 73 && (73 %% 72))))
      (bvalf D E B leq (v71:num->A) (Eq 71 74))
      (bvalf D E B leq (v71:num->A)
         ((?? 73 (opair_form 70 71 73 && (73 %% 72))) --> Eq 71 74))`
    ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`?? 73 (opair_form 70 71 73 && (73 %% 72))`;`Eq 71 74`;
                  `D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`v71:num->A`]
                   BVALF_IMP) THEN
    ASM_REWRITE_TAC[]; ALL_TAC];
  MP_TAC(ISPECL
         [`71`;`74`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`v71:num->A`]
