         [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`e2v:A`;`agn2:A`;
          `m6:A`;`s2:A`]
         EMEET_GREATEST) THEN ANTS_TAC THENL
  [REPEAT CONJ_TAC THEN CLOSE; DISCH_TAC];
  MP_TAC(ISPECL
         [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`s2:A`;`m6:A`;`eyG:A`]
         EPORDER_TRANS) THEN ANTS_TAC THENL
  [REPEAT CONJ_TAC THEN CLOSE; DISCH_TAC];
  MATCH_MP_TAC(ISPECL
               [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`cc2:A`;`c:A`;`eyG:A`;
                `w0:A`;`s2:A`]
               EBIMP_LE_IMP) THEN REPEAT CONJ_TAC THEN CLOSE]);;

(* ============================================================================
   BVALF_APPLY_LE  (B4 helper):  apply <= pmem, at generic slots i,j,k.
     [[ apply_form i j k ]]_v0  <=  ebv_in op (v0 i)
   where op is the canonical V^B Kuratowski pair name of (v0 j, v0 k), given
   via its standard eapply bundle (s = {v0 j}, p = {v0 j, v0 k}, op = {s,p}).
   This is BVALF_PMEM_LE with the slots relabelled and the conjunction
   reversed ( (n%%i) && opair_form j k n ), matching
       apply_form i j k = ?? n ((n%%i) && opair_form j k n).
   ========================================================================= *)
let BVALF_APPLY_LE = prove
 (`!D (E:A->A->bool) B leq (v0:num->A) i j k s p op top mvop.
      model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
      valuation D v0 /\ (!m. bname D E B (v0 m)) /\
      top IN D /\ etop D E B leq top /\
      s IN D /\ bname D E B s /\ p IN D /\ bname D E B p /\
      op IN D /\ bname D E B op /\
      eapply D E s (v0 j) top /\
      (!t q. t IN D /\ q IN D /\ eapply D E s t q ==> t = v0 j \/ t = v0 j) /\
      eapply D E p (v0 j) top /\ eapply D E p (v0 k) top /\
      (!t q. t IN D /\ q IN D /\ eapply D E p t q ==> t = v0 j \/ t = v0 k) /\
      eapply D E op s top /\ eapply D E op p top /\
      (!t q. t IN D /\ q IN D /\ eapply D E op t q ==> t = s \/ t = p) /\
      mvop IN D /\ ebv_in D E B leq op (v0 i) mvop
      ==> erel D E leq (bvalf D E B leq v0 (apply_form i j k)) mvop`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  REWRITE_TAC[apply_form] THEN
  ABBREV_TAC `n = MAX (MAX i j) k + 1` THEN
  SUBGOAL_THEN `~((n:num) = i) /\ ~(n = j) /\ ~(n = k)` STRIP_ASSUME_TAC THENL
   [EXPAND_TAC "n" THEN ARITH_TAC; ALL_TAC] THEN
  SUBGOAL_THEN `ebalg D (E:A->A->bool) B leq /\ eporder D E B leq`
    STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[ECBA_IMP_BALG; EBALG_IMP_PORDER]; ALL_TAC] THEN
  SUBGOAL_THEN `!x. (v0:num->A) x IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[valuation]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) mvop B` ASSUME_TAC THENL
   [ASM_MESON_TAC[EBV_IN_IN_B]; ALL_TAC] THEN
  MATCH_MP_TAC(ISPECL
               [`n:num`;`(n %% i) && opair_form j k n`;`D:A->bool`;
                `E:A->A->bool`;
                `B:A`;`leq:A`;`v0:num->A`;`mvop:A`] BVALF_EX_LEAST) THEN
  ASM_REWRITE_TAC[] THEN X_GEN_TAC `w:A` THEN STRIP_TAC THEN
  SUBGOAL_THEN `valuation D ((n |-> w) (v0:num->A)) /\
                (!m. bname D E B (((n |-> w) (v0:num->A)) m))`
    STRIP_ASSUME_TAC THENL
   [CONJ_TAC THENL
     [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[];
      MATCH_MP_TAC BNAMEVAL_VALMOD THEN ASM_REWRITE_TAC[]]; ALL_TAC] THEN
  ABBREV_TAC `vw = (n |-> w) (v0:num->A)` THEN
  SUBGOAL_THEN `(vw:num->A) i = v0 i /\ (vw:num->A) j = v0 j /\
                (vw:num->A) k = v0 k /\ (vw:num->A) n = w`
    STRIP_ASSUME_TAC THENL
   [EXPAND_TAC "vw" THEN ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER];
    ALL_TAC] THEN
  (* ewp = ebv_eq(w, op) *)
  SUBGOAL_THEN
    `?ewp:A. ewp IN D /\ (E:A->A->bool) ewp B /\ ebv_eq D E B leq w op ewp`
    (X_CHOOSE_THEN `ewp:A` STRIP_ASSUME_TAC) THENL
   [MATCH_MP_TAC EBV_EQ_VAL_EXISTS THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* Opv = [[opair j k n]]_vw <= ewp *)
  ABBREV_TAC
    `Opv = bvalf D (E:A->A->bool) B leq (vw:num->A) (opair_form j k n)` THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq Opv ewp` ASSUME_TAC THENL
   [EXPAND_TAC "Opv" THEN
    MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`vw:num->A`;`j:num`;
                  `k:num`;`n:num`;
                  `s:A`;`p:A`;`op:A`;`top:A`;`ewp:A`] BVALF_OPAIRFORM_LE) THEN
    ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[]; ALL_TAC] THEN
  (* Memv = [[n%%i]]_vw = ebv_in(w, v0 i) *)
  ABBREV_TAC `Memv = bvalf D (E:A->A->bool) B leq (vw:num->A) (n %% i)` THEN
  SUBGOAL_THEN `ebv_in D (E:A->A->bool) B leq w ((v0:num->A) i) Memv`
    ASSUME_TAC THENL
   [EXPAND_TAC "Memv" THEN
    MP_TAC(ISPECL
           [`n:num`;`i:num`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
            `vw:num->A`] BVALF_MEM) THEN
    ASM_SIMP_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN
    `(Opv:A) IN D /\ (E:A->A->bool) Opv B /\ (Memv:A) IN D /\ E (Memv:A) B`
    STRIP_ASSUME_TAC THENL
   [MAP_EVERY EXPAND_TAC ["Opv";"Memv"] THEN
    ASM_MESON_TAC[BVALF_SPEC; BVALF_IN_B]; ALL_TAC] THEN
  (* W' = [[(n%%i) && opair j k n]]_vw = emeet(Memv, Opv) *)
  ABBREV_TAC `Wp = bvalf D (E:A->A->bool) B leq (vw:num->A)
                     ((n %% i) && opair_form j k n)` THEN
  SUBGOAL_THEN `emeet D (E:A->A->bool) B leq Memv Opv Wp` ASSUME_TAC THENL
   [MAP_EVERY EXPAND_TAC ["Wp";"Opv";"Memv"] THEN
    MATCH_MP_TAC(ISPECL
                 [`n %% i`;`opair_form j k n`;`D:A->bool`;`E:A->A->bool`;`B:A`;
                  `leq:A`;`vw:num->A`] BVALF_AND_MEET) THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `(Wp:A) IN D /\ (E:A->A->bool) Wp B` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[EMEET_IN]; ALL_TAC] THEN
  MP_TAC(ISPECL
         [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`Memv:A`;`Opv:A`;`Wp:A`]
         EMEET_LE) THEN
  ASM_REWRITE_TAC[] THEN STRIP_TAC THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq Wp ewp` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`Wp:A`;
                  `Opv:A`;`ewp:A`]
                 EPORDER_TRANS) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `?z23:A. emeet D (E:A->A->bool) B leq ewp Memv z23`
    (X_CHOOSE_TAC `z23:A`) THENL
   [MATCH_MP_TAC EBALG_MEET THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(z23:A) IN D /\ (E:A->A->bool) z23 B` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[EMEET_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq Wp z23` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`ewp:A`;`Memv:A`;
                  `z23:A`;`Wp:A`]
                 EMEET_GREATEST) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq z23 mvop` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`w:A`;`op:A`;
                  `(v0:num->A) i`;
                  `ewp:A`;`Memv:A`;`mvop:A`;`z23:A`] EBV_IN_CONG_L) THEN
         ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MATCH_MP_TAC(ISPECL
               [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`Wp:A`;
                `z23:A`;`mvop:A`]
               EPORDER_TRANS) THEN ASM_REWRITE_TAC[]);;

(* ============================================================================
   HFVAL  (crux bridge for (B) B3/B4):
     The h-cell value at <xi,alpha>^ equals the f-membership value at the
     canonical V^B ordered-pair name op of (xi^, r_alpha).  I.e.
          [[ <xi,alpha>^ IN h ]]  =  ebv_in op f .
   Exports op (= pair name of (xi^, r_alpha)) with its full eapply-char so
   B4 can feed it to BVALF_OPAIRFORM_LE / BVALF_PMEM_GE.

   Construction (no extraction of h's internal op): build the cell <cpc, w>
   with a FRESH EOPAIRNAME_CANON op, w := ebv_in op f; show it is in h via
   h-char; then HNAME_MEM_VALUE equates the membership value wh to w.
   ========================================================================= *)

let HFVAL = prove
 (`!D (E:A->A->bool) B leq onebee realfn f a1 a2 cr h
     xi alpha cp xic rdot cpc wh.
     model D E ZF_AX /\ (!u:A. u IN D ==> elmem D E u) /\
     ecba D E B leq /\ B IN D /\ leq IN D /\ onebee IN D /\ E onebee B /\
     etop D E B leq onebee /\
     realfn IN D /\ eisfun D E realfn /\ f IN D /\ bname D E B f /\
     h IN D /\ eisfun D E h /\
     (!zz. zz IN D
          ==> (E zz h <=>
               ?cp xi alpha xic rdot op w cpc.
                    cp IN D /\ xi IN D /\ alpha IN D /\ xic IN D /\
                    rdot IN D /\ op IN D /\ w IN D /\ cpc IN D /\
                    E cp cr /\
                    eopair D E xi alpha cp /\ E xi a1 /\ E alpha a2 /\
                    echeck D E onebee xi xic /\ eapply D E realfn alpha rdot /\
                    (?paa pab sa sab psa psab.
                         paa IN D /\ pab IN D /\ sa IN D /\ sab IN D /\
                         psa IN D /\ psab IN D /\
                         eopair D E xic onebee paa /\
                           eopair D E rdot onebee pab /\
                         epair D E paa paa sa /\ epair D E paa pab sab /\
                         eopair D E sa onebee psa /\
                           eopair D E sab onebee psab /\
                         epair D E psa psab op) /\
                    ebv_in D E B leq op f w /\
                    echeck D E onebee cp cpc /\ eopair D E cpc w zz)) /\
     xi IN D /\ alpha IN D /\ cp IN D /\ xic IN D /\ rdot IN D /\ cpc IN D /\
     E cp cr /\ eopair D E xi alpha cp /\ E xi a1 /\ E alpha a2 /\
     echeck D E onebee xi xic /\ eapply D E realfn alpha rdot /\
     bname D E B rdot /\
     echeck D E onebee cp cpc /\
     wh IN D /\ ebv_in D E B leq cpc h wh
     ==> ?op sa sab w.
            op IN D /\ bname D E B op /\ sa IN D /\ bname D E B sa /\
            sab IN D /\ bname D E B sab /\
            eapply D E sa xic onebee /\
            (!t q. t IN D /\ q IN D /\ eapply D E sa t q ==>
             t = xic \/ t = xic) /\
            eapply D E sab xic onebee /\ eapply D E sab rdot onebee /\
            (!t q. t IN D /\ q IN D /\ eapply D E sab t q ==> t = xic \/
             t = rdot) /\
            eapply D E op sa onebee /\ eapply D E op sab onebee /\
            (!t q. t IN D /\ q IN D /\ eapply D E op t q ==>
             t = sa \/ t = sab) /\
            w IN D /\ E w B /\ ebv_in D E B leq op f w /\ wh = w`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  FIRST_X_ASSUM(LABEL_TAC "hchar" o
    check (fun th -> is_forall(concl th) && vfree_in `h:A` (concl th))) THEN
  SUBGOAL_THEN `eporder D (E:A->A->bool) (B:A) (leq:A)` ASSUME_TAC THENL
   [ASM_MESON_TAC[ECBA_IMP_PORDER]; ALL_TAC] THEN
  (* ---- bname xic ---- *)
  SUBGOAL_THEN `bname D (E:A->A->bool) B xic` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`onebee:A`;`B:A`;`xi:A`;`xic:A`]
                 ECHECK_IS_BNAME) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* ---- canonical pair name op of (xic, rdot) ---- *)
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`xic:A`;`rdot:A`]
    EOPAIRNAME_CANON) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `op:A` (X_CHOOSE_THEN `sa:A` (X_CHOOSE_THEN `sab:A`
    (X_CHOOSE_THEN `topc:A` (X_CHOOSE_THEN `paa:A` (X_CHOOSE_THEN `pab:A`
      (X_CHOOSE_THEN `psa:A`
       (X_CHOOSE_THEN `psab:A` STRIP_ASSUME_TAC)))))))) THEN
  (* ---- topc = onebee ---- *)
  SUBGOAL_THEN `(topc:A) = onebee` SUBST_ALL_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`topc:A`;`onebee:A`]
                 ETOP_UNIQUE) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* ---- bridge CANON's membership chars to the epair conjuncts the h-char
          witnesses require (CANON exposes sa/sab/op only via `E z _ <=>
            ...`) ---- *)
  SUBGOAL_THEN `epair D (E:A->A->bool) paa paa sa` ASSUME_TAC THENL
   [REWRITE_TAC[epair] THEN ASM_MESON_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `epair D (E:A->A->bool) paa pab sab` ASSUME_TAC THENL
   [REWRITE_TAC[epair] THEN ASM_MESON_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `epair D (E:A->A->bool) psa psab op` ASSUME_TAC THENL
   [REWRITE_TAC[epair] THEN ASM_MESON_TAC[]; ALL_TAC] THEN
  (* ---- w := [[ op IN f ]] ---- *)
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`op:A`;`f:A`]
    EBV_IN_VAL_EXISTS) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `w:A` STRIP_ASSUME_TAC) THEN
  (* ---- zz0 := < cpc, w > ---- *)
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`cpc:A`;`w:A`] EOPAIR_EXISTS) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `zz0:A` ASSUME_TAC) THEN
  SUBGOAL_THEN `(zz0:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[EOPAIR_IN]; ALL_TAC] THEN
  (* ---- the cell < cpc, w > is in h ---- *)
  SUBGOAL_THEN `(E:A->A->bool) zz0 h` ASSUME_TAC THENL
   [USE_THEN "hchar" (MP_TAC o SPEC `zz0:A`) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    MAP_EVERY EXISTS_TAC
     [`cp:A`;`xi:A`;`alpha:A`;`xic:A`;`rdot:A`;`op:A`;`w:A`;`cpc:A`] THEN
    ASM_REWRITE_TAC[] THEN
    MAP_EVERY EXISTS_TAC
     [`paa:A`;`pab:A`;`sa:A`;`sab:A`;`psa:A`;`psab:A`] THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* ---- eapply h cpc w ---- *)
  SUBGOAL_THEN `eapply D (E:A->A->bool) h cpc w` ASSUME_TAC THENL
   [REWRITE_TAC[eapply] THEN EXISTS_TAC `zz0:A` THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  (* ---- wh = w via HNAME_MEM_VALUE ---- *)
  SUBGOAL_THEN `(wh:A) = w` ASSUME_TAC THENL
   [MP_TAC(ISPECL
           [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`onebee:A`;`realfn:A`;
            `f:A`;`a1:A`;`a2:A`;`cr:A`;`h:A`;`cp:A`;`cpc:A`;`w:A`;`wh:A`]
      HNAME_MEM_VALUE) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[] THEN USE_THEN "hchar" ACCEPT_TAC;
      DISCH_THEN ACCEPT_TAC]; ALL_TAC] THEN
  MAP_EVERY EXISTS_TAC [`op:A`;`sa:A`;`sab:A`;`w:A`] THEN
  ASM_REWRITE_TAC[]);;

(* ============================================================================
   ONTO_CHECK_LE  (B4 novel core):  at a CHECK, apply <= h-membership.
       [[ apply_form 3 4 5 ]]_vck  <=  [[ ?? 73 (opair_form 70 71 73 &&
         73%%72) ]]_vck
   where vck 3=f, 4=xi0^, 5=rdot(=r_alpha), 70=xi0^, 71=alpha^, 72=h.
   I.e.  [[ f(xi0^) = r_alpha ]]  <=  [[ <xi0^,alpha^> IN h ]].

   Chain:  LHS <= ebv_in op f   (BVALF_APPLY_LE, op=pairname(xi0^,rdot))
              = wh = ebv_in cpc h        (HFVAL: w = wh, cpc=<xi0,alpha>^)
              <= RHS                      (BVALF_PMEM_GE,
              pr:=cpc via ECHECK_KUR_AUTO).
   ========================================================================= *)

let ONTO_CHECK_LE = prove
 (`!D (E:A->A->bool) B leq onebee realfn f a1 a2 cr h
     xi0 alpha xi0c alphac cp cpc rdot vck.
     model D E ZF_AX /\ (!u:A. u IN D ==> elmem D E u) /\
     ecba D E B leq /\ B IN D /\ leq IN D /\ onebee IN D /\ E onebee B /\
     etop D E B leq onebee /\
     realfn IN D /\ eisfun D E realfn /\ f IN D /\ bname D E B f /\
     h IN D /\ eisfun D E h /\ bname D E B h /\
     (!zz. zz IN D
          ==> (E zz h <=>
               ?cp xi alpha xic rdot op w cpc.
                    cp IN D /\ xi IN D /\ alpha IN D /\ xic IN D /\
                    rdot IN D /\ op IN D /\ w IN D /\ cpc IN D /\
                    E cp cr /\
                    eopair D E xi alpha cp /\ E xi a1 /\ E alpha a2 /\
                    echeck D E onebee xi xic /\ eapply D E realfn alpha rdot /\
                    (?paa pab sa sab psa psab.
                         paa IN D /\ pab IN D /\ sa IN D /\ sab IN D /\
                         psa IN D /\ psab IN D /\
                         eopair D E xic onebee paa /\
                           eopair D E rdot onebee pab /\
                         epair D E paa paa sa /\ epair D E paa pab sab /\
                         eopair D E sa onebee psa /\
                           eopair D E sab onebee psab /\
                         epair D E psa psab op) /\
                    ebv_in D E B leq op f w /\
                    echeck D E onebee cp cpc /\ eopair D E cpc w zz)) /\
     xi0 IN D /\ alpha IN D /\ E xi0 a1 /\ E alpha a2 /\
     echeck D E onebee xi0 xi0c /\ echeck D E onebee alpha alphac /\
     eopair D E xi0 alpha cp /\ echeck D E onebee cp cpc /\ E cp cr /\
     eapply D E realfn alpha rdot /\ bname D E B rdot /\ rdot IN D /\
     valuation D vck /\ (!k. bname D E B (vck k)) /\
     vck 3 = f /\ vck 4 = xi0c /\ vck 5 = rdot /\
     vck 70 = xi0c /\ vck 71 = alphac /\ vck 72 = h
     ==> erel D E leq (bvalf D E B leq vck (apply_form 3 4 5))
                      (bvalf D E B leq vck
                       (?? 73 (opair_form 70 71 73 && (73 %% 72))))`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  FIRST_X_ASSUM(LABEL_TAC "hchar" o
    check (fun th -> is_forall(concl th) && vfree_in `h:A` (concl th))) THEN
  SUBGOAL_THEN `eporder D (E:A->A->bool) (B:A) (leq:A)` ASSUME_TAC THENL
   [ASM_MESON_TAC[ECBA_IMP_PORDER]; ALL_TAC] THEN
  (* ---- derived domain / bname facts ---- *)
  SUBGOAL_THEN `(cp:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[EOPAIR_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `(xi0c:A) IN D /\ (cpc:A) IN D /\ (alphac:A) IN D`
    STRIP_ASSUME_TAC THENL [ASM_MESON_TAC[ECHECK_IMP]; ALL_TAC] THEN
  SUBGOAL_THEN `bname D (E:A->A->bool) B cpc` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`onebee:A`;`B:A`;`cp:A`;`cpc:A`]
                 ECHECK_IS_BNAME) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* ---- wh := [[ cpc IN h ]] ---- *)
  SUBGOAL_THEN
    `?wh:A. wh IN D /\ (E:A->A->bool) wh B /\ ebv_in D E B leq cpc h wh`
    (X_CHOOSE_THEN `wh:A` STRIP_ASSUME_TAC) THENL
   [MATCH_MP_TAC EBV_IN_VAL_EXISTS THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* ---- HFVAL: op (= pairname(xi0^,rdot)) bundle + w = [[op IN f]] + wh = *)
  (* w ---- *)
  MP_TAC(ISPECL
         [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`onebee:A`;`realfn:A`;`f:A`;
          `a1:A`;`a2:A`;`cr:A`;`h:A`;`xi0:A`;`alpha:A`;`cp:A`;`xi0c:A`;
          `rdot:A`;`cpc:A`;`wh:A`]
    HFVAL) THEN
  ANTS_TAC THENL
   [REPEAT CONJ_TAC THEN
    TRY(FIRST_ASSUM ACCEPT_TAC) THEN USE_THEN "hchar" ACCEPT_TAC;
    ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `op:A` (X_CHOOSE_THEN `sa:A` (X_CHOOSE_THEN `sab:A`
    (X_CHOOSE_THEN `w:A` STRIP_ASSUME_TAC)))) THEN
  (* hchar no longer needed; drop it so the trailing ASM_MESONs can't *)
  (* diverge *)
  REMOVE_THEN "hchar" (K ALL_TAC) THEN
  (* ---- LHS = [[apply 3 4 5]]_vck <= w = ebv_in op f ---- *)
  SUBGOAL_THEN
   `erel D (E:A->A->bool) leq (bvalf D E B leq vck (apply_form 3 4 5)) w`
    ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`vck:num->A`;
      `3`;`4`;`5`;`sa:A`;`sab:A`;`op:A`;`onebee:A`;`w:A`]
      BVALF_APPLY_LE) THEN
    ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[]; ALL_TAC] THEN
  (* ---- w = wh ; so ebv_in cpc h w ---- *)
  SUBGOAL_THEN `ebv_in D (E:A->A->bool) B leq cpc h w` ASSUME_TAC THENL
   [SUBGOAL_THEN `(w:A) = wh` SUBST1_TAC THENL
     [ASM_MESON_TAC[]; ASM_REWRITE_TAC[]]; ALL_TAC] THEN
  (* ---- ECHECK_KUR_AUTO: Kuratowski bundle s',p',cpc for <xi0^,alpha^> *)
  (* ---- *)
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`onebee:A`;`xi0:A`;`alpha:A`;
    `xi0c:A`;`alphac:A`;`cp:A`;`cpc:A`] ECHECK_KUR_AUTO) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `s2:A` (X_CHOOSE_THEN `p2:A` STRIP_ASSUME_TAC)) THEN
  (* ---- w <= RHS = [[?? 73 (opair_form 70 71 73 && 73%%72)]]_vck ---- *)
  SUBGOAL_THEN
   `erel D (E:A->A->bool) leq w
      (bvalf D E B leq vck (?? 73 (opair_form 70 71 73 && (73 %% 72))))`
    ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`vck:num->A`;
      `s2:A`;`p2:A`;`cpc:A`;`onebee:A`;`w:A`] BVALF_PMEM_GE) THEN
    ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[]; ALL_TAC] THEN
  (* ---- LHS <= w <= RHS ---- *)
  MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
    `bvalf (D:A->bool) (E:A->A->bool) (B:A) (leq:A) (vck:num->A)
     (apply_form 3 4 5)`;`w:A`;
    `bvalf (D:A->bool) (E:A->A->bool) (B:A) (leq:A) (vck:num->A)
           (?? 73 (opair_form 70 71 73 && (73 %% 72)))`] EPORDER_TRANS) THEN
  ASM_REWRITE_TAC[] THEN
  ASM_MESON_TAC[BVALF_SPEC; BVALF_IN_B]);;

(* ============================================================================
   ONTOH_SUPLE  (B4 LAYER 3 -- the novel, c-free heart):
       [[ ?? 4 ((4%%1) && apply_form 3 4 5) ]]_{v0}
         <=  [[ ??- 70 69 (?? 73 (opair_form 70 71 73 &&
           73%%72)) ]]_{(71|->alphac)v0}
   i.e.  sup_tau [[tau in a1c]] /\ [[f(tau) = r_alpha]]
          <=  sup_tau [[tau in a1c]] /\ [[<tau,alpha^> in h]].
   For every witness name tau at a CHECK xi0^ (via ECHECK_IN_LE_SUP), the apply
   value transfers to the h-membership value by ONTO_CHECK_LE; off-diagonal the
   meet with [[tau=xi0^]] collapses by Leibniz (MAXPRIN_LEIBNIZ_STEP).
   Replays the fully verified interactive derivation (steps 01-52d).
   ========================================================================= *)

let ONTOH_SUPLE = prove
 (`!D (E:A->A->bool) B leq onebee realfn f a1 a2 cr a1c h alpha alphac rdot v0.
     model D E ZF_AX /\ (!u:A. u IN D ==> elmem D E u) /\
     ecba D E B leq /\ B IN D /\ leq IN D /\ onebee IN D /\ E onebee B /\
     etop D E B leq onebee /\
     realfn IN D /\ eisfun D E realfn /\ f IN D /\ bname D E B f /\
     h IN D /\ eisfun D E h /\ bname D E B h /\
     (!zz. zz IN D
          ==> (E zz h <=>
               ?cp xi alpha xic rdot op w cpc.
                    cp IN D /\ xi IN D /\ alpha IN D /\ xic IN D /\
                    rdot IN D /\ op IN D /\ w IN D /\ cpc IN D /\
                    E cp cr /\
                    eopair D E xi alpha cp /\ E xi a1 /\ E alpha a2 /\
                    echeck D E onebee xi xic /\ eapply D E realfn alpha rdot /\
                    (?paa pab sa sab psa psab.
                         paa IN D /\ pab IN D /\ sa IN D /\ sab IN D /\
                         psa IN D /\ psab IN D /\
                         eopair D E xic onebee paa /\
                           eopair D E rdot onebee pab /\
                         epair D E paa paa sa /\ epair D E paa pab sab /\
                         eopair D E sa onebee psa /\
                           eopair D E sab onebee psab /\
                         epair D E psa psab op) /\
                    ebv_in D E B leq op f w /\
                    echeck D E onebee cp cpc /\ eopair D E cpc w zz)) /\
     a1 IN D /\ a2 IN D /\ cr IN D /\ a1c IN D /\
     ecross D E a1 a2 cr /\ echeck D E onebee a1 a1c /\
     alpha IN D /\ E alpha a2 /\ alphac IN D /\
       echeck D E onebee alpha alphac /\
     eapply D E realfn alpha rdot /\ bname D E B rdot /\ rdot IN D /\
     valuation D v0 /\ (!k. bname D E B (v0 k)) /\
     v0 1 = a1c /\ v0 3 = f /\ v0 5 = rdot /\ v0 69 = a1c /\ v0 72 = h
     ==> erel D E leq
           (bvalf D E B leq v0 (?? 4 ((4 %% 1) && apply_form 3 4 5)))
           (bvalf D E B leq ((71 |-> alphac) v0)
              (??- 70 69 (?? 73 (opair_form 70 71 73 && (73 %% 72)))))`,
  (* ---- 01 strip ---- *)
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  (* ---- 02 label hchar ---- *)
  FIRST_X_ASSUM(LABEL_TAC "hchar" o
    check (fun th -> is_forall(concl th) && vfree_in `h:A` (concl th))) THEN
  (* ---- 03 ebalg / eporder ---- *)
  SUBGOAL_THEN `ebalg D (E:A->A->bool) B leq /\ eporder D E B leq`
    STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[ECBA_IMP_BALG; EBALG_IMP_PORDER]; ALL_TAC] THEN
  (* ---- 04 v0 valuation range ---- *)
  SUBGOAL_THEN `!x. (v0:num->A) x IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[valuation]; ALL_TAC] THEN
  (* ---- 05 bname alphac ---- *)
  SUBGOAL_THEN `bname D (E:A->A->bool) B alphac` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`onebee:A`;`B:A`;
                  `alpha:A`;`alphac:A`]
                 ECHECK_IS_BNAME) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* ---- 06 abbrev RHS ---- *)
  ABBREV_TAC `RHS = bvalf D (E:A->A->bool) B leq ((71 |-> alphac) (v0:num->A))
      (??- 70 69 (?? 73 (opair_form 70 71 73 && (73 %% 72))))` THEN
  (* ---- 07 valuation (71|->alphac)v0 ---- *)
  SUBGOAL_THEN `valuation D ((71 |-> alphac)(v0:num->A)) /\
                (!k. bname D E B (((71 |-> alphac)(v0:num->A)) k))`
    STRIP_ASSUME_TAC THENL
   [CONJ_TAC THENL
     [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[];
      MATCH_MP_TAC BNAMEVAL_VALMOD THEN ASM_REWRITE_TAC[]]; ALL_TAC] THEN
  (* ---- 08 RHS in D / E RHS B ---- *)
  SUBGOAL_THEN `(RHS:A) IN D /\ (E:A->A->bool) RHS B` STRIP_ASSUME_TAC THENL
   [EXPAND_TAC "RHS" THEN ASM_MESON_TAC[BVALF_SPEC; BVALF_IN_B]; ALL_TAC] THEN
  (* ---- 09 BVALF_EX_LEAST ---- *)
  MATCH_MP_TAC(ISPECL
               [`4`;`(4 %% 1) && apply_form 3 4 5`;`D:A->bool`;`E:A->A->bool`;
                `B:A`;`leq:A`;`v0:num->A`;`RHS:A`] BVALF_EX_LEAST) THEN
  ASM_REWRITE_TAC[] THEN
  (* ---- 10 X_GEN tau ---- *)
  X_GEN_TAC `tau:A` THEN STRIP_TAC THEN
  (* ---- 11 valuation (4|->tau)v0 ---- *)
  SUBGOAL_THEN `valuation D ((4 |-> tau)(v0:num->A)) /\
                (!k. bname D E B (((4 |-> tau)(v0:num->A)) k))`
    STRIP_ASSUME_TAC THENL
   [CONJ_TAC THENL
     [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[];
      MATCH_MP_TAC BNAMEVAL_VALMOD THEN ASM_REWRITE_TAC[]]; ALL_TAC] THEN
  (* ---- 12 abbrev vt ---- *)
  ABBREV_TAC `vt = (4 |-> tau)(v0:num->A)` THEN
  (* ---- 13 vt slots ---- *)
  SUBGOAL_THEN `(vt:num->A) 1 = a1c /\ (vt:num->A) 3 = f /\
                (vt:num->A) 4 = tau /\ (vt:num->A) 5 = rdot`
    STRIP_ASSUME_TAC THENL
   [EXPAND_TAC "vt" THEN ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER; ARITH_EQ];
    ALL_TAC] THEN
  (* ---- 14 abbrev zmem ---- *)
  ABBREV_TAC `zmem = bvalf D (E:A->A->bool) B leq (vt:num->A) (4 %% 1)` THEN
  (* ---- 15 zmem value ---- *)
  SUBGOAL_THEN `ebv_in D (E:A->A->bool) B leq tau a1c zmem` ASSUME_TAC THENL
   [EXPAND_TAC "zmem" THEN
    MP_TAC(ISPECL
           [`4`;`1`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`vt:num->A`]
           BVALF_MEM) THEN
    ASM_SIMP_TAC[]; ALL_TAC] THEN
  (* ---- 16 abbrev zap ---- *)
  ABBREV_TAC
    `zap = bvalf D (E:A->A->bool) B leq (vt:num->A) (apply_form 3 4 5)` THEN
  (* ---- 17 abbrev bodyval ---- *)
  ABBREV_TAC
    `bodyval = bvalf D (E:A->A->bool) B leq (vt:num->A)
     ((4 %% 1) && apply_form 3 4 5)` THEN
  (* ---- 18 bodyval meet ---- *)
  SUBGOAL_THEN `emeet D (E:A->A->bool) B leq zmem zap bodyval` ASSUME_TAC THENL
   [MAP_EVERY EXPAND_TAC ["bodyval";"zmem";"zap"] THEN
    MATCH_MP_TAC(ISPECL
                 [`4 %% 1`;`apply_form 3 4 5`;`D:A->bool`;`E:A->A->bool`;`B:A`;
                  `leq:A`;`vt:num->A`] BVALF_AND_MEET) THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  (* ---- 19 zmem,zap in D ---- *)
  SUBGOAL_THEN `(zmem:A) IN D /\ (E:A->A->bool) zmem B /\
                (zap:A) IN D /\ (E:A->A->bool) zap B`
    STRIP_ASSUME_TAC THENL
   [MAP_EVERY EXPAND_TAC ["zmem";"zap"] THEN
    ASM_MESON_TAC[BVALF_SPEC; BVALF_IN_B]; ALL_TAC] THEN
  (* ---- 20 i2 = ebimp zap RHS ---- *)
  SUBGOAL_THEN `?i2:A. ebimp D (E:A->A->bool) B leq zap RHS i2`
    (X_CHOOSE_TAC `i2:A`) THENL
   [MATCH_MP_TAC EBIMP_EXISTS THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* ---- 21 i2 in D ---- *)
  SUBGOAL_THEN `(i2:A) IN D /\ (E:A->A->bool) i2 B` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[EBIMP_IN]; ALL_TAC] THEN
  (* ---- 22 reduce bodyval<=RHS to zmem<=i2 ---- *)
  SUBGOAL_THEN `erel D (E:A->A->bool) leq zmem i2` ASSUME_TAC THENL
   [ALL_TAC;
    MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`zmem:A`;
                  `zap:A`;`RHS:A`;
                  `i2:A`;`bodyval:A`] EBIMP_MEET_LE) THEN
    ASM_REWRITE_TAC[]] THEN
  (* ---- 23 ECHECK_IN_LE_SUP ---- *)
  MATCH_MP_TAC(ISPECL
               [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`onebee:A`;
                `a1:A`;`a1c:A`;
                `tau:A`;`zmem:A`;`i2:A`] ECHECK_IN_LE_SUP) THEN
  ASM_REWRITE_TAC[] THEN
  (* ---- 24 contributor gen ---- *)
  MAP_EVERY X_GEN_TAC [`xi0:A`;`xi0c:A`;`ec2:A`] THEN STRIP_TAC THEN
  (* ---- 25 xi0c in D ---- *)
  SUBGOAL_THEN `(xi0:A) IN D /\ (xi0c:A) IN D` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[ECHECK_IMP]; ALL_TAC] THEN
  (* ---- 26 bname xi0c ---- *)
  SUBGOAL_THEN `bname D (E:A->A->bool) B xi0c` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`onebee:A`;`B:A`;`xi0:A`;`xi0c:A`]
                 ECHECK_IS_BNAME) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* ---- 27 E ec2 B ---- *)
  SUBGOAL_THEN `(E:A->A->bool) ec2 B` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`tau:A`;
                  `xi0c:A`;`ec2:A`]
                 EBV_EQ_IN_B) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* ---- 28 cp = <xi0,alpha> ---- *)
  SUBGOAL_THEN `?cp:A. eopair D (E:A->A->bool) xi0 alpha cp`
    (X_CHOOSE_TAC `cp:A`) THENL
   [MATCH_MP_TAC EOPAIR_EXISTS THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* ---- 29 cp in D ---- *)
  SUBGOAL_THEN `(cp:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[EOPAIR_IN]; ALL_TAC] THEN
  (* ---- 30 E cp cr ---- *)
  SUBGOAL_THEN `(E:A->A->bool) cp cr` ASSUME_TAC THENL
   [MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`a1:A`;`a2:A`;`cr:A`;`cp:A`]
           ECROSS_MEMBER) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    MAP_EVERY EXISTS_TAC [`xi0:A`;`alpha:A`] THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  (* ---- 31 cpc = check cp ---- *)
  SUBGOAL_THEN `?cpc:A. echeck D (E:A->A->bool) onebee cp cpc`
    (X_CHOOSE_TAC `cpc:A`) THENL
   [MATCH_MP_TAC ECHECK_EXHAUSTION THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* ---- 32 cpc in D ---- *)
  SUBGOAL_THEN `(cpc:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[ECHECK_IMP]; ALL_TAC] THEN
  (* ---- 33 mc2 = meet ec2 zap ---- *)
  SUBGOAL_THEN `?mc2:A. emeet D (E:A->A->bool) B leq ec2 zap mc2`
    (X_CHOOSE_TAC `mc2:A`) THENL
   [MATCH_MP_TAC EBALG_MEET THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* ---- 34 mc2 in D ---- *)
  SUBGOAL_THEN `(mc2:A) IN D /\ (E:A->A->bool) mc2 B` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[EMEET_IN]; ALL_TAC] THEN
  (* ---- 35 mc2 <= ec2, mc2 <= zap ---- *)
  SUBGOAL_THEN
    `erel D (E:A->A->bool) leq mc2 ec2 /\ erel D (E:A->A->bool) leq mc2 zap`
    STRIP_ASSUME_TAC THENL [ASM_MESON_TAC[EMEET_LE]; ALL_TAC] THEN
  (* ---- 36 reduce ec2<=i2 to mc2<=RHS ---- *)
  SUBGOAL_THEN `erel D (E:A->A->bool) leq mc2 RHS` ASSUME_TAC THENL
   [ALL_TAC;
    MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`ec2:A`;
                  `zap:A`;`RHS:A`;
                  `i2:A`;`mc2:A`] EBIMP_LE_IMP) THEN ASM_REWRITE_TAC[]] THEN
  (* ---- 37 Leibniz: mc2 <= [[apply]]_{(4|->xi0c)v0} ---- *)
  SUBGOAL_THEN `erel D (E:A->A->bool) leq mc2
       (bvalf D E B leq ((4|->xi0c)(v0:num->A)) (apply_form 3 4 5))`
    ASSUME_TAC THENL
   [MP_TAC(ISPECL
           [`4`;`apply_form 3 4 5`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
            `v0:num->A`;
            `tau:A`;`xi0c:A`;`mc2:A`;`ec2:A`] MAXPRIN_LEIBNIZ_STEP) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* ---- 38 valuation (4|->xi0c)v0 ---- *)
  SUBGOAL_THEN `valuation D ((4 |-> xi0c)(v0:num->A)) /\
     (!k. bname D E B (((4 |-> xi0c)(v0:num->A)) k))`
    STRIP_ASSUME_TAC THENL
   [CONJ_TAC THENL
     [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[];
      MATCH_MP_TAC BNAMEVAL_VALMOD THEN ASM_REWRITE_TAC[]];
    ALL_TAC] THEN
  (* ---- 39 valuation (70|->xi0c)((71|->alphac)v0) ---- *)
  SUBGOAL_THEN `valuation D ((70 |-> xi0c)((71 |-> alphac)(v0:num->A))) /\
     (!k. bname D E B (((70 |-> xi0c)((71 |-> alphac)(v0:num->A))) k))`
    STRIP_ASSUME_TAC THENL
   [CONJ_TAC THENL
     [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[];
      MATCH_MP_TAC BNAMEVAL_VALMOD THEN ASM_REWRITE_TAC[]];
    ALL_TAC] THEN
  (* ---- 40 valuation (4|->xi0c)((70|->xi0c)((71|->alphac)v0)) ---- *)
  SUBGOAL_THEN
    `valuation D ((4 |-> xi0c)((70 |-> xi0c)((71 |-> alphac)(v0:num->A)))) /\
     (!k. bname D E B
      (((4 |-> xi0c)((70 |-> xi0c)((71 |-> alphac)(v0:num->A)))) k))`
    STRIP_ASSUME_TAC THENL
   [CONJ_TAC THENL
     [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[];
      MATCH_MP_TAC BNAMEVAL_VALMOD THEN ASM_REWRITE_TAC[]];
    ALL_TAC] THEN
  (* ---- 41 CONG1: [[apply]]_{(4|->xi0c)v0} = [[apply]]_{vck} ---- *)
  SUBGOAL_THEN
   `bvalf D (E:A->A->bool) B leq ((4|->xi0c)(v0:num->A)) (apply_form 3 4 5) =
    bvalf D E B leq ((4|->xi0c)((70|->xi0c)((71|->alphac)(v0:num->A))))
      (apply_form 3 4 5)`
    ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`apply_form 3 4 5`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
                  `(4|->xi0c)(v0:num->A)`;
                  `(4|->xi0c)((70|->xi0c)((71|->alphac)(v0:num->A)))`]
      BVALF_FV_CONG) THEN
    ASM_REWRITE_TAC[] THEN
    REWRITE_TAC[FV_APPLY_FORM; IN_INSERT; NOT_IN_EMPTY] THEN
    REPEAT STRIP_TAC THEN ASM_REWRITE_TAC[] THEN
    ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER; ARITH_EQ];
    ALL_TAC] THEN
  (* ---- 42 vck slots ---- *)
  SUBGOAL_THEN
   `((4|->xi0c)((70|->xi0c)((71|->alphac)(v0:num->A)))) 3 = f /\
    ((4|->xi0c)((70|->xi0c)((71|->alphac)(v0:num->A)))) 4 = xi0c /\
    ((4|->xi0c)((70|->xi0c)((71|->alphac)(v0:num->A)))) 5 = rdot /\
    ((4|->xi0c)((70|->xi0c)((71|->alphac)(v0:num->A)))) 70 = xi0c /\
    ((4|->xi0c)((70|->xi0c)((71|->alphac)(v0:num->A)))) 71 = alphac /\
    ((4|->xi0c)((70|->xi0c)((71|->alphac)(v0:num->A)))) 72 = h`
    STRIP_ASSUME_TAC THENL
   [ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER; ARITH_EQ];
    ALL_TAC] THEN
  (* ---- 42b xi0 in D ---- *)
  SUBGOAL_THEN `(xi0:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[ECHECK_IMP]; ALL_TAC] THEN
  (* ---- 43 ONTO_CHECK_LE ---- *)
  SUBGOAL_THEN
   `erel D (E:A->A->bool) leq
      (bvalf D E B leq ((4|->xi0c)((70|->xi0c)((71|->alphac)(v0:num->A))))
       (apply_form 3 4 5))
      (bvalf D E B leq ((4|->xi0c)((70|->xi0c)((71|->alphac)(v0:num->A))))
            (?? 73 (opair_form 70 71 73 && (73 %% 72))))`
    ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`onebee:A`;
                  `realfn:A`;`f:A`;
                  `a1:A`;`a2:A`;`cr:A`;`h:A`;`xi0:A`;`alpha:A`;`xi0c:A`;
                  `alphac:A`;`cp:A`;`cpc:A`;`rdot:A`;
                  `(4|->xi0c)((70|->xi0c)((71|->alphac)(v0:num->A)))`]
                   ONTO_CHECK_LE) THEN
    REPEAT CONJ_TAC THEN TRY(FIRST_ASSUM ACCEPT_TAC) THEN
    USE_THEN "hchar" ACCEPT_TAC;
    ALL_TAC] THEN
  (* ---- 44 CONG2: [[ANTEQ0]]_{vck} = [[ANTEQ0]]_{vb} ---- *)
  SUBGOAL_THEN
   `bvalf D (E:A->A->bool) B leq
    ((4|->xi0c)((70|->xi0c)((71|->alphac)(v0:num->A))))
          (?? 73 (opair_form 70 71 73 && (73 %% 72))) =
    bvalf D E B leq ((70|->xi0c)((71|->alphac)(v0:num->A)))
          (?? 73 (opair_form 70 71 73 && (73 %% 72)))`
    ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL [`?? 73 (opair_form 70 71 73 && (73 %% 72))`;
      `D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
      `(4|->xi0c)((70|->xi0c)((71|->alphac)(v0:num->A)))`;
      `(70|->xi0c)((71|->alphac)(v0:num->A))`] BVALF_FV_CONG) THEN
    ASM_REWRITE_TAC[] THEN
    REWRITE_TAC[FV; FV_CLAUSES; FV_OPAIR_FORM; IN_DELETE; IN_UNION; IN_INSERT;
      NOT_IN_EMPTY] THEN
    REPEAT STRIP_TAC THEN ASM_SIMP_TAC[VALMOD_OTHER; ARITH_EQ];
    ALL_TAC] THEN
  (* ---- 44b remove hchar (nested-forall-exists; prevent trailing MESON *)
  (* divergence) ---- *)
  REMOVE_THEN "hchar" (K ALL_TAC) THEN
  (* ---- 45 vb slots ---- *)
  SUBGOAL_THEN
   `((70|->xi0c)((71|->alphac)(v0:num->A))) 70 = xi0c /\
    ((70|->xi0c)((71|->alphac)(v0:num->A))) 69 = a1c`
    STRIP_ASSUME_TAC THENL
   [ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER; ARITH_EQ];
    ALL_TAC] THEN
  (* ---- 46 abbrev zin70 = [[70%%69]]_{vb} ---- *)
  ABBREV_TAC `zin70 = bvalf D (E:A->A->bool) B leq
     ((70|->xi0c)((71|->alphac)(v0:num->A))) (70 %% 69)` THEN
  (* ---- 47 zin70 value ---- *)
  SUBGOAL_THEN `ebv_in D (E:A->A->bool) B leq xi0c a1c zin70` ASSUME_TAC THENL
   [EXPAND_TAC "zin70" THEN
    MP_TAC(ISPECL [`70`;`69`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
      `(70|->xi0c)((71|->alphac)(v0:num->A))`] BVALF_MEM) THEN
    ASM_SIMP_TAC[];
    ALL_TAC] THEN
  (* ---- 48 zin70 in D ---- *)
  SUBGOAL_THEN `(zin70:A) IN D /\ (E:A->A->bool) zin70 B`
    STRIP_ASSUME_TAC THENL
   [EXPAND_TAC "zin70" THEN ASM_MESON_TAC[BVALF_SPEC; BVALF_IN_B];
    ALL_TAC] THEN
  (* ---- 49 etop zin70 (xi0 in a1 ==> [[xi0^ in a1c]] = top) ---- *)
  SUBGOAL_THEN `etop D (E:A->A->bool) B leq zin70` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`onebee:A`;
                  `xi0:A`;`a1:A`;
                  `xi0c:A`;`a1c:A`;`zin70:A`] ECHECK_IN_TOP) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  (* ---- 50a emeet [[ANTEQ0]] zin70 = [[ANTEQ0]] ---- *)
  SUBGOAL_THEN `emeet D (E:A->A->bool) B leq
      (bvalf D E B leq ((70|->xi0c)((71|->alphac)(v0:num->A)))
            (?? 73 (opair_form 70 71 73 && (73 %% 72)))) zin70
      (bvalf D E B leq ((70|->xi0c)((71|->alphac)(v0:num->A)))
            (?? 73 (opair_form 70 71 73 && (73 %% 72))))`
    ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`zin70:A`;
      `bvalf D (E:A->A->bool) B leq ((70|->xi0c)((71|->alphac)(v0:num->A)))
            (?? 73 (opair_form 70 71 73 && (73 %% 72)))`] EMEET_TOP) THEN
    ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[BVALF_SPEC; BVALF_IN_B];
    ALL_TAC] THEN
  (* ---- 50b emeet zin70 [[ANTEQ0]] = [[ANTEQ0]] (symmetrize) ---- *)
  SUBGOAL_THEN `emeet D (E:A->A->bool) B leq zin70
      (bvalf D E B leq ((70|->xi0c)((71|->alphac)(v0:num->A)))
            (?? 73 (opair_form 70 71 73 && (73 %% 72))))
      (bvalf D E B leq ((70|->xi0c)((71|->alphac)(v0:num->A)))
            (?? 73 (opair_form 70 71 73 && (73 %% 72))))`
    ASSUME_TAC THENL
   [MATCH_MP_TAC EMEET_SYM THEN ASM_REWRITE_TAC[] THEN
    ASM_MESON_TAC[BVALF_SPEC; BVALF_IN_B];
    ALL_TAC] THEN
  (* ---- 51 EBVALF_EXMEM_GE: [[ANTEQ0]]_{vb} <= RHS ---- *)
  SUBGOAL_THEN `erel D (E:A->A->bool) leq
      (bvalf D E B leq ((70|->xi0c)((71|->alphac)(v0:num->A)))
            (?? 73 (opair_form 70 71 73 && (73 %% 72)))) RHS`
    ASSUME_TAC THENL
   [EXPAND_TAC "RHS" THEN
    MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
      `(71|->alphac)(v0:num->A)`;`70`;`69`;
      `?? 73 (opair_form 70 71 73 && (73 %% 72))`;`xi0c:A`;
      `bvalf D (E:A->A->bool) B leq ((70|->xi0c)((71|->alphac)(v0:num->A)))
            (?? 73 (opair_form 70 71 73 && (73 %% 72)))`] EBVALF_EXMEM_GE) THEN
    ASM_REWRITE_TAC[ARITH_EQ] THEN ASM_MESON_TAC[];
    ALL_TAC] THEN
  (* ---- 52a mc2 <= [[apply]]_{vck} ---- *)
  SUBGOAL_THEN `erel D (E:A->A->bool) leq mc2
     (bvalf D E B leq ((4|->xi0c)((70|->xi0c)((71|->alphac)(v0:num->A))))
      (apply_form 3 4 5))`
    ASSUME_TAC THENL
   [SUBGOAL_THEN
      `bvalf D (E:A->A->bool) B leq
       ((4|->xi0c)((70|->xi0c)((71|->alphac)(v0:num->A)))) (apply_form 3 4 5)
       = bvalf D E B leq ((4|->xi0c)(v0:num->A)) (apply_form 3 4 5)`
      SUBST1_TAC THENL
     [ASM_MESON_TAC[]; FIRST_ASSUM ACCEPT_TAC];
    ALL_TAC] THEN
  (* ---- 52b mc2 <= [[ANTEQ0]]_{vck} ---- *)
  SUBGOAL_THEN `erel D (E:A->A->bool) leq mc2
     (bvalf D E B leq ((4|->xi0c)((70|->xi0c)((71|->alphac)(v0:num->A))))
           (?? 73 (opair_form 70 71 73 && (73 %% 72))))`
    ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`mc2:A`;
      `bvalf D (E:A->A->bool) B leq
       ((4|->xi0c)((70|->xi0c)((71|->alphac)(v0:num->A)))) (apply_form 3 4 5)`;
      `bvalf D (E:A->A->bool) B leq
       ((4|->xi0c)((70|->xi0c)((71|->alphac)(v0:num->A))))
            (?? 73 (opair_form 70 71 73 && (73 %% 72)))`] EPORDER_TRANS) THEN
    ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[BVALF_SPEC; BVALF_IN_B];
    ALL_TAC] THEN
  (* ---- 52c mc2 <= [[ANTEQ0]]_{vb} ---- *)
  SUBGOAL_THEN `erel D (E:A->A->bool) leq mc2
     (bvalf D E B leq ((70|->xi0c)((71|->alphac)(v0:num->A)))
           (?? 73 (opair_form 70 71 73 && (73 %% 72))))`
    ASSUME_TAC THENL
   [SUBGOAL_THEN
      `bvalf D (E:A->A->bool) B leq ((70|->xi0c)((71|->alphac)(v0:num->A)))
            (?? 73 (opair_form 70 71 73 && (73 %% 72)))
       = bvalf D E B leq ((4|->xi0c)((70|->xi0c)((71|->alphac)(v0:num->A))))
            (?? 73 (opair_form 70 71 73 && (73 %% 72)))`
      SUBST1_TAC THENL
     [ASM_MESON_TAC[]; FIRST_ASSUM ACCEPT_TAC];
    ALL_TAC] THEN
  (* ---- 52d final: mc2 <= [[ANTEQ0]]_{vb} <= RHS ---- *)
  MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`mc2:A`;
    `bvalf D (E:A->A->bool) B leq ((70|->xi0c)((71|->alphac)(v0:num->A)))
          (?? 73 (opair_form 70 71 73 && (73 %% 72)))`;
    `RHS:A`] EPORDER_TRANS) THEN
  ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[BVALF_SPEC; BVALF_IN_B]);;

(* ============================================================================
   ONTOH_PERALPHA  (B4 LAYER 2.5):  fix a column alpha in a2.  From
       c <= [[ !! 5 ((5 in 2) --> ?E tau. tau in a1c /\ f(tau)=r_5) ]]_v
   (i.e. c forces "r_alpha is onto" at the pw-coordinate 2, slot 5 the fibre
   variable) together with the abstract clause [[r_alpha in pw]] = top, derive
       c <= [[ ??- 70 69 ANTEQ ]]_{(71|->alpha^) v}
   i.e. c forces "<some tau in a1c, alpha^> in h".  Peels the leading !!5 with
   BVALF_ALL_LB at the real name r_alpha, residuates past the top-valued
   membership premise, applies the c-free heart ONTOH_SUPLE, then transports
   the valuation (5|->rdot)v back to v by FV-congruence (slot 5 is not free in
   the h-side formula ??- 70 69 ANTEQ, whose FV = {69,71,72}).
   Replays the verified interactive derivation (steps P01-P13).
   ========================================================================= *)

let ONTOH_PERALPHA = prove
 (`!D (E:A->A->bool) B leq onebee realfn f a1 a2 cr a1c h alpha
   alphac rdot c v.
     model D E ZF_AX /\ (!u:A. u IN D ==> elmem D E u) /\
     ecba D E B leq /\ B IN D /\ leq IN D /\ onebee IN D /\ E onebee B /\
     etop D E B leq onebee /\
     realfn IN D /\ eisfun D E realfn /\ f IN D /\ bname D E B f /\
     h IN D /\ eisfun D E h /\ bname D E B h /\
     (!zz. zz IN D
          ==> (E zz h <=>
               ?cp xi alpha xic rdot op w cpc.
                    cp IN D /\ xi IN D /\ alpha IN D /\ xic IN D /\
                    rdot IN D /\ op IN D /\ w IN D /\ cpc IN D /\
                    E cp cr /\
                    eopair D E xi alpha cp /\ E xi a1 /\ E alpha a2 /\
                    echeck D E onebee xi xic /\ eapply D E realfn alpha rdot /\
                    (?paa pab sa sab psa psab.
                         paa IN D /\ pab IN D /\ sa IN D /\ sab IN D /\
                         psa IN D /\ psab IN D /\
                         eopair D E xic onebee paa /\
                           eopair D E rdot onebee pab /\
                         epair D E paa paa sa /\ epair D E paa pab sab /\
                         eopair D E sa onebee psa /\
                           eopair D E sab onebee psab /\
                         epair D E psa psab op) /\
                    ebv_in D E B leq op f w /\
                    echeck D E onebee cp cpc /\ eopair D E cpc w zz)) /\
     a1 IN D /\ a2 IN D /\ cr IN D /\ a1c IN D /\
     ecross D E a1 a2 cr /\ echeck D E onebee a1 a1c /\
     alpha IN D /\ E alpha a2 /\ alphac IN D /\
       echeck D E onebee alpha alphac /\
     eapply D E realfn alpha rdot /\ bname D E B rdot /\ rdot IN D /\
     c IN D /\ E c B /\
     valuation D v /\ (!k. bname D E B (v k)) /\
     v 1 = a1c /\ v 3 = f /\ v 69 = a1c /\ v 72 = h /\
     erel D E leq c
        (bvalf D E B leq v
           (!! 5 ((5 %% 2) --> ?? 4 ((4 %% 1) && apply_form 3 4 5)))) /\
     etop D E B leq (bvalf D E B leq ((5 |-> rdot) (v:num->A)) (5 %% 2))
     ==> erel D E leq c
           (bvalf D E B leq ((71 |-> alphac) (v:num->A))
              (??- 70 69 (?? 73 (opair_form 70 71 73 && (73 %% 72)))))`,
  (* ---- P01 strip ---- *)
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  (* ---- P02 label hchar ---- *)
  FIRST_X_ASSUM(LABEL_TAC "hchar" o
    check (fun th -> is_forall(concl th) && vfree_in `h:A` (concl th))) THEN
  (* ---- P03 ebalg/eporder ---- *)
  SUBGOAL_THEN `ebalg D (E:A->A->bool) B leq /\ eporder D E B leq`
    STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[ECBA_IMP_BALG; EBALG_IMP_PORDER]; ALL_TAC] THEN
  (* ---- P04 v range ---- *)
  SUBGOAL_THEN `!x. (v:num->A) x IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[valuation]; ALL_TAC] THEN
  (* ---- P05 bname alphac ---- *)
  SUBGOAL_THEN `bname D (E:A->A->bool) B alphac` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`onebee:A`;`B:A`;
                  `alpha:A`;`alphac:A`]
                 ECHECK_IS_BNAME) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* ---- P06 valuation (5|->rdot)v ---- *)
  SUBGOAL_THEN `valuation D ((5 |-> rdot)(v:num->A)) /\
                (!k. bname D E B (((5 |-> rdot)(v:num->A)) k))`
    STRIP_ASSUME_TAC THENL
   [CONJ_TAC THENL
     [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[];
      MATCH_MP_TAC BNAMEVAL_VALMOD THEN ASM_REWRITE_TAC[]]; ALL_TAC] THEN
  (* ---- P07 slots of (5|->rdot)v ---- *)
  SUBGOAL_THEN
    `((5 |-> rdot)(v:num->A)) 1 = a1c /\ ((5 |-> rdot)(v:num->A)) 3 = f /\
     ((5 |-> rdot)(v:num->A)) 5 = rdot /\ ((5 |-> rdot)(v:num->A)) 69 = a1c /\
                ((5 |-> rdot)(v:num->A)) 72 = h`
    STRIP_ASSUME_TAC THENL
   [ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER; ARITH_EQ]; ALL_TAC] THEN
  (* ---- P07b valuation (71|->alphac)((5|->rdot)v) ---- *)
  SUBGOAL_THEN `valuation D ((71 |-> alphac)((5 |-> rdot)(v:num->A))) /\
                (!k. bname D E B
                 (((71 |-> alphac)((5 |-> rdot)(v:num->A))) k))`
    STRIP_ASSUME_TAC THENL
   [CONJ_TAC THENL
     [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[];
      MATCH_MP_TAC BNAMEVAL_VALMOD THEN ASM_REWRITE_TAC[]]; ALL_TAC] THEN
  (* ---- P07c valuation (71|->alphac)v ---- *)
  SUBGOAL_THEN `valuation D ((71 |-> alphac)(v:num->A)) /\
                (!k. bname D E B (((71 |-> alphac)(v:num->A)) k))`
    STRIP_ASSUME_TAC THENL
   [CONJ_TAC THENL
     [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[];
      MATCH_MP_TAC BNAMEVAL_VALMOD THEN ASM_REWRITE_TAC[]]; ALL_TAC] THEN
  (* ---- P08 BVALF_ALL_LB peels !!5 at the real name rdot ---- *)
  SUBGOAL_THEN `erel D (E:A->A->bool) leq
      (bvalf D E B leq v
       (!! 5 ((5 %% 2) --> ?? 4 ((4 %% 1) && apply_form 3 4 5))))
      (bvalf D E B leq ((5 |-> rdot)(v:num->A))
            ((5 %% 2) --> ?? 4 ((4 %% 1) && apply_form 3 4 5)))`
    ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`5`;`(5 %% 2) --> ?? 4 ((4 %% 1) && apply_form 3 4 5)`;
                  `D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`v:num->A`;`rdot:A`]
                   BVALF_ALL_LB) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* ---- P09 c <= [[bodyf]]_{(5|->rdot)v} (transitivity through ONTOf) ---- *)
  SUBGOAL_THEN `erel D (E:A->A->bool) leq c
      (bvalf D E B leq ((5 |-> rdot)(v:num->A))
            ((5 %% 2) --> ?? 4 ((4 %% 1) && apply_form 3 4 5)))`
    ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`c:A`;
      `bvalf D (E:A->A->bool) B leq v
       (!! 5 ((5 %% 2) --> ?? 4 ((4 %% 1) && apply_form 3 4 5)))`;
      `bvalf D (E:A->A->bool) B leq ((5 |-> rdot)(v:num->A))
            ((5 %% 2) --> ?? 4 ((4 %% 1) && apply_form 3 4 5))`]
              EPORDER_TRANS) THEN
    ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[BVALF_SPEC; BVALF_IN_B]; ALL_TAC] THEN
  (* ---- P10a BVALF_IMP ---- *)
  SUBGOAL_THEN `ebimp D (E:A->A->bool) B leq
      (bvalf D E B leq ((5 |-> rdot)(v:num->A)) (5 %% 2))
      (bvalf D E B leq ((5 |-> rdot)(v:num->A))
       (?? 4 ((4 %% 1) && apply_form 3 4 5)))
      (bvalf D E B leq ((5 |-> rdot)(v:num->A))
            ((5 %% 2) --> ?? 4 ((4 %% 1) && apply_form 3 4 5)))`
    ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL [`5 %% 2`;`?? 4 ((4 %% 1) && apply_form 3 4 5)`;
      `D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`(5 |-> rdot)(v:num->A)`]
              BVALF_IMP) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* ---- P10b EMEET_TOP: emeet c [[5%%2]] c (membership premise is top) *)
  (* ---- *)
  SUBGOAL_THEN `emeet D (E:A->A->bool) B leq c
      (bvalf D E B leq ((5 |-> rdot)(v:num->A)) (5 %% 2)) c`
    ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
      `bvalf D (E:A->A->bool) B leq ((5 |-> rdot)(v:num->A)) (5 %% 2)`;`c:A`]
                EMEET_TOP) THEN
    ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[BVALF_SPEC; BVALF_IN_B]; ALL_TAC] THEN
  (* ---- P10c EBIMP_MEET_LE: c <= [[EX4]]_{(5|->rdot)v} ---- *)
  SUBGOAL_THEN `erel D (E:A->A->bool) leq c
      (bvalf D E B leq ((5 |-> rdot)(v:num->A))
       (?? 4 ((4 %% 1) && apply_form 3 4 5)))`
    ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`c:A`;
      `bvalf D (E:A->A->bool) B leq ((5 |-> rdot)(v:num->A)) (5 %% 2)`;
      `bvalf D (E:A->A->bool) B leq ((5 |-> rdot)(v:num->A))
       (?? 4 ((4 %% 1) && apply_form 3 4 5))`;
      `bvalf D (E:A->A->bool) B leq ((5 |-> rdot)(v:num->A))
            ((5 %% 2) --> ?? 4 ((4 %% 1) && apply_form 3 4 5))`;`c:A`]
         EBIMP_MEET_LE) THEN
    ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[BVALF_SPEC; BVALF_IN_B]; ALL_TAC] THEN
  (* ---- P11 ONTOH_SUPLE (the c-free heart) ---- *)
  SUBGOAL_THEN `erel D (E:A->A->bool) leq
      (bvalf D E B leq ((5 |-> rdot)(v:num->A))
       (?? 4 ((4 %% 1) && apply_form 3 4 5)))
      (bvalf D E B leq ((71 |-> alphac)((5 |-> rdot)(v:num->A)))
            (??- 70 69 (?? 73 (opair_form 70 71 73 && (73 %% 72)))))`
    ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`onebee:A`;
                  `realfn:A`;`f:A`;
                  `a1:A`;`a2:A`;`cr:A`;`a1c:A`;`h:A`;`alpha:A`;
                  `alphac:A`;`rdot:A`;
                  `(5 |-> rdot)(v:num->A)`] ONTOH_SUPLE) THEN
    REPEAT CONJ_TAC THEN TRY(FIRST_ASSUM ACCEPT_TAC) THEN
    USE_THEN "hchar" ACCEPT_TAC; ALL_TAC] THEN
  (* ---- P12 FV-congruence: swap (5|->rdot)v -> v in the h-side (slot 5 *)
  (* free-free) ---- *)
  SUBGOAL_THEN
   `bvalf D (E:A->A->bool) B leq ((71 |-> alphac)((5 |-> rdot)(v:num->A)))
          (??- 70 69 (?? 73 (opair_form 70 71 73 && (73 %% 72)))) =
    bvalf D E B leq ((71 |-> alphac)(v:num->A))
          (??- 70 69 (?? 73 (opair_form 70 71 73 && (73 %% 72))))`
    (LABEL_TAC "cong") THENL
   [MATCH_MP_TAC(ISPECL
                 [`??- 70 69 (?? 73 (opair_form 70 71 73 && (73 %% 72)))`;
                  `D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
      `(71 |-> alphac)((5 |-> rdot)(v:num->A))`;`(71 |-> alphac)(v:num->A)`]
                   BVALF_FV_CONG) THEN
    ASM_REWRITE_TAC[] THEN
    REWRITE_TAC[FV; FV_CLAUSES; FV_OPAIR_FORM; IN_DELETE; IN_UNION; IN_INSERT;
      NOT_IN_EMPTY] THEN
    REPEAT STRIP_TAC THEN ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER; ARITH_EQ];
    ALL_TAC] THEN
  (* ---- P13 final: swap RHS by cong then EPORDER_TRANS(P10c, P11) ---- *)
  USE_THEN "cong" (SUBST1_TAC o SYM) THEN
  MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`c:A`;
    `bvalf D (E:A->A->bool) B leq ((5 |-> rdot)(v:num->A))
     (?? 4 ((4 %% 1) && apply_form 3 4 5))`;
    `bvalf D (E:A->A->bool) B leq ((71 |-> alphac)((5 |-> rdot)(v:num->A)))
          (??- 70 69 (?? 73 (opair_form 70 71 73 && (73 %% 72))))`]
      EPORDER_TRANS) THEN
  ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[BVALF_SPEC; BVALF_IN_B]);;

(* ============================================================================
   ONTOH_OUTER  (B4 LAYER 2):  totalize ONTOH_PERALPHA over the a2-sup.  Fix a
   B-name ss (a candidate fibre tag).  From
       c <= [[ !! 5 ((5 in 2) --> ?E tau. tau in a1c /\ f(tau)=r_5) ]]_v
   (c forces "r is onto") together with the per-column REALCLAUSE (every
   alpha in a2 has a real name r_alpha with [[r_alpha in pw]] = top), derive
       emeet c (ebv_in ss a2c) m  ==>  m <= [[ ??- 70 69 ANTEQ ]]_{(71|->ss)v}.
   The sup over columns alpha of a2 of the PERALPHA contributions dominates
   [[71 in 68]] = ebv_in ss a2c (= msval), so c meets msval below the h-value.
   Residuation: i := ebimp c RHSss; main closes by EBIMP_MEET_LE once
   erel msval i; that sup-bound is ECHECK_IN_LE_SUP over the columns of a2,
   each contributor discharged by ONTOH_PERALPHA + Leibniz(aac->ss).
   Replays the verified interactive derivation (steps O01-O27); O02b's realcl
   label-check is made exclusive (not(vfree_in h)) so it cannot steal hchar,
   and O24's membership side-conditions are discharged deterministically via
   BVALF_SPEC/BVALF_IN_B (ASM_MESON diverges in this large context).
   ========================================================================= *)

let ONTOH_OUTER = prove
 (`!D (E:A->A->bool) B leq onebee realfn f a1 a2 cr a1c a2c h ss m msval c v.
     model D E ZF_AX /\ (!u:A. u IN D ==> elmem D E u) /\
     ecba D E B leq /\ B IN D /\ leq IN D /\ onebee IN D /\ E onebee B /\
     etop D E B leq onebee /\
     realfn IN D /\ eisfun D E realfn /\ f IN D /\ bname D E B f /\
     h IN D /\ eisfun D E h /\ bname D E B h /\
     (!zz. zz IN D
          ==> (E zz h <=>
               ?cp xi alpha xic rdot op w cpc.
                    cp IN D /\ xi IN D /\ alpha IN D /\ xic IN D /\
                    rdot IN D /\ op IN D /\ w IN D /\ cpc IN D /\
                    E cp cr /\
                    eopair D E xi alpha cp /\ E xi a1 /\ E alpha a2 /\
                    echeck D E onebee xi xic /\ eapply D E realfn alpha rdot /\
                    (?paa pab sa sab psa psab.
                         paa IN D /\ pab IN D /\ sa IN D /\ sab IN D /\
                         psa IN D /\ psab IN D /\
                         eopair D E xic onebee paa /\
                           eopair D E rdot onebee pab /\
                         epair D E paa paa sa /\ epair D E paa pab sab /\
                         eopair D E sa onebee psa /\
                           eopair D E sab onebee psab /\
                         epair D E psa psab op) /\
                    ebv_in D E B leq op f w /\
                    echeck D E onebee cp cpc /\ eopair D E cpc w zz)) /\
     a1 IN D /\ a2 IN D /\ cr IN D /\ a1c IN D /\ a2c IN D /\
     ecross D E a1 a2 cr /\ echeck D E onebee a1 a1c /\
       echeck D E onebee a2 a2c /\
     ss IN D /\ bname D E B ss /\
     (!a. a IN D /\ E a a2
          ==> ?rd. eapply D E realfn a rd /\ bname D E B rd /\ rd IN D /\
                   etop D E B leq
                     (bvalf D E B leq ((5 |-> rd)(v:num->A)) (5 %% 2))) /\
     c IN D /\ E c B /\
     valuation D v /\ (!k. bname D E B (v k)) /\
     v 1 = a1c /\ v 3 = f /\ v 69 = a1c /\ v 72 = h /\
     erel D E leq c
        (bvalf D E B leq v
           (!! 5 ((5 %% 2) --> ?? 4 ((4 %% 1) && apply_form 3 4 5)))) /\
     msval IN D /\ m IN D /\
     ebv_in D E B leq ss a2c msval /\ emeet D E B leq c msval m
     ==> erel D E leq m
           (bvalf D E B leq ((71 |-> ss) (v:num->A))
              (??- 70 69 (?? 73 (opair_form 70 71 73 && (73 %% 72)))))`,
  (* ---- O01 strip ---- *)
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  (* ---- O02 label hchar ---- *)
  FIRST_X_ASSUM(LABEL_TAC "hchar" o
    check (fun th -> is_forall(concl th) && vfree_in `h:A` (concl th))) THEN
  (* ---- O02b label realcl (exclusive: realfn but NOT h, so it cannot steal *)
  (* hchar) ---- *)
  FIRST_X_ASSUM(LABEL_TAC "realcl" o
    check (fun th -> is_forall(concl th) && vfree_in `realfn:A` (concl th) &&
                     not(vfree_in `h:A` (concl th)))) THEN
  (* ---- O03 ebalg/eporder ---- *)
  SUBGOAL_THEN `ebalg D (E:A->A->bool) B leq /\ eporder D E B leq`
    STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[ECBA_IMP_BALG; EBALG_IMP_PORDER]; ALL_TAC] THEN
  (* ---- O05 abbrev RHSss ---- *)
  ABBREV_TAC `RHSss = bvalf D (E:A->A->bool) B leq ((71 |-> ss)(v:num->A))
      (??- 70 69 (?? 73 (opair_form 70 71 73 && (73 %% 72))))` THEN
  (* ---- O06 valuation (71|->ss)v ---- *)
  SUBGOAL_THEN `valuation D ((71 |-> ss)(v:num->A)) /\
                (!k. bname D E B (((71 |-> ss)(v:num->A)) k))`
    STRIP_ASSUME_TAC THENL
   [CONJ_TAC THENL
     [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[];
      MATCH_MP_TAC BNAMEVAL_VALMOD THEN ASM_REWRITE_TAC[]]; ALL_TAC] THEN
  (* ---- O07 RHSss in D / E RHSss B ---- *)
  SUBGOAL_THEN `(RHSss:A) IN D /\ (E:A->A->bool) RHSss B`
    STRIP_ASSUME_TAC THENL
   [EXPAND_TAC "RHSss" THEN ASM_MESON_TAC[BVALF_SPEC; BVALF_IN_B];
    ALL_TAC] THEN
  (* ---- O08 msval in D / E msval B ---- *)
  SUBGOAL_THEN `(msval:A) IN D /\ (E:A->A->bool) msval B`
    STRIP_ASSUME_TAC THENL
   [CONJ_TAC THENL
     [ASM_MESON_TAC[];
      MATCH_MP_TAC(ISPECL
                   [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`ss:A`;
                    `a2c:A`;`msval:A`]
                   EBV_IN_IN_B) THEN ASM_MESON_TAC[]]; ALL_TAC] THEN
  (* ---- O09 i = ebimp c RHSss ---- *)
  SUBGOAL_THEN `?i:A. ebimp D (E:A->A->bool) B leq c RHSss i`
    (X_CHOOSE_TAC `i:A`) THENL
   [MATCH_MP_TAC EBIMP_EXISTS THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* ---- O10 i in D / E i B ---- *)
  SUBGOAL_THEN `(i:A) IN D /\ (E:A->A->bool) i B` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[EBIMP_IN]; ALL_TAC] THEN
  (* ---- O11 emeet msval c m (symmetrize given emeet c msval m) ---- *)
  SUBGOAL_THEN `emeet D (E:A->A->bool) B leq msval c m` ASSUME_TAC THENL
   [MATCH_MP_TAC EMEET_SYM THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* ---- O12 open: prove erel msval i (contributor), then close main ---- *)
  SUBGOAL_THEN `erel D (E:A->A->bool) leq msval i` ASSUME_TAC THENL
   [(* ====== proving  erel msval i  ====== *)
    (* ---- O13 ECHECK_IN_LE_SUP over columns of a2 ---- *)
    MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`onebee:A`;
                  `a2:A`;`a2c:A`;
                  `ss:A`;`msval:A`;`i:A`] ECHECK_IN_LE_SUP) THEN
    ASM_REWRITE_TAC[] THEN
    (* ---- O14 contributor gen ---- *)
    MAP_EVERY X_GEN_TAC [`aa:A`;`aac:A`;`eqc:A`] THEN STRIP_TAC THEN
    (* ---- O15 aa,aac in D (ECHECK_IMP) then bname aac ---- *)
    SUBGOAL_THEN `(aa:A) IN D /\ (aac:A) IN D` STRIP_ASSUME_TAC THENL
     [ASM_MESON_TAC[ECHECK_IMP]; ALL_TAC] THEN
    SUBGOAL_THEN `bname D (E:A->A->bool) B aac` ASSUME_TAC THENL
     [MATCH_MP_TAC(ISPECL
                   [`D:A->bool`;`E:A->A->bool`;`onebee:A`;`B:A`;`aa:A`;`aac:A`]
                   ECHECK_IS_BNAME) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    (* ---- O17 E eqc B ---- *)
    SUBGOAL_THEN `(E:A->A->bool) eqc B` ASSUME_TAC THENL
     [MATCH_MP_TAC(ISPECL
                   [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`ss:A`;
                    `aac:A`;`eqc:A`]
                   EBV_EQ_IN_B) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    (* ---- O18 real name rd for aa (REALCLAUSE via MATCH_MP against the E *)
    (* aa a2 asm) ---- *)
    USE_THEN "realcl" (MP_TAC o SPEC `aa:A`) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(X_CHOOSE_THEN `rd:A` STRIP_ASSUME_TAC) THEN
    (* ---- O19 PERALPHA for column aa ---- *)
    SUBGOAL_THEN `erel D (E:A->A->bool) leq c
        (bvalf D E B leq ((71 |-> aac)(v:num->A))
              (??- 70 69 (?? 73 (opair_form 70 71 73 && (73 %% 72)))))`
      ASSUME_TAC THENL
     [MATCH_MP_TAC(ISPECL
                   [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`onebee:A`;
                    `realfn:A`;`f:A`;
                    `a1:A`;`a2:A`;`cr:A`;`a1c:A`;`h:A`;`aa:A`;`aac:A`;`rd:A`;
                    `c:A`;`v:num->A`] ONTOH_PERALPHA) THEN
      REPEAT CONJ_TAC THEN TRY(FIRST_ASSUM ACCEPT_TAC) THEN
      USE_THEN "hchar" ACCEPT_TAC; ALL_TAC] THEN
    (* ---- O20 mal = emeet eqc c ---- *)
    SUBGOAL_THEN `?mal:A. emeet D (E:A->A->bool) B leq eqc c mal`
      (X_CHOOSE_TAC `mal:A`) THENL
      [MATCH_MP_TAC EBALG_MEET THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    (* ---- O21 mal in D / E mal B ---- *)
    SUBGOAL_THEN `(mal:A) IN D /\ (E:A->A->bool) mal B` STRIP_ASSUME_TAC THENL
     [ASM_MESON_TAC[EMEET_IN]; ALL_TAC] THEN
    (* ---- O22 mal<=eqc, mal<=c ---- *)
    SUBGOAL_THEN
      `erel D (E:A->A->bool) leq mal eqc /\ erel D (E:A->A->bool) leq mal c`
      STRIP_ASSUME_TAC THENL [ASM_MESON_TAC[EMEET_LE]; ALL_TAC] THEN
    (* ---- O23 ebv_eq aac ss eqc (flip) ---- *)
    SUBGOAL_THEN `ebv_eq D (E:A->A->bool) B leq aac ss eqc` ASSUME_TAC THENL
     [MATCH_MP_TAC(ISPECL
                   [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`ss:A`;
                    `aac:A`;`eqc:A`]
                   EBV_EQ_SYM) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    (* ---- O23b valuation (71|->aac)v ---- *)
    SUBGOAL_THEN `valuation D ((71 |-> aac)(v:num->A)) /\
                  (!k. bname D E B (((71 |-> aac)(v:num->A)) k))`
      STRIP_ASSUME_TAC THENL
     [CONJ_TAC THENL
       [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[];
        MATCH_MP_TAC BNAMEVAL_VALMOD THEN ASM_REWRITE_TAC[]]; ALL_TAC] THEN
    (* ---- O23c that-term in D (deterministic via BVALF_SPEC; ASM_MESON *)
    (* diverges here) ---- *)
    SUBGOAL_THEN
     `bvalf D (E:A->A->bool) B leq ((71 |-> aac)(v:num->A))
            (??- 70 69 (?? 73 (opair_form 70 71 73 && (73 %% 72)))) IN D`
      ASSUME_TAC THENL
     [MP_TAC(ISPECL [`??- 70 69 (?? 73 (opair_form 70 71 73 && (73 %% 72)))`;
        `D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`(71 |-> aac)(v:num->A)`]
          BVALF_SPEC) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN(ACCEPT_TAC o CONJUNCT1)];
      ALL_TAC] THEN
    (* ---- O23d E that-term B (deterministic via BVALF_IN_B) ---- *)
    SUBGOAL_THEN
     `(E:A->A->bool) (bvalf D E B leq ((71 |-> aac)(v:num->A))
            (??- 70 69 (?? 73 (opair_form 70 71 73 && (73 %% 72))))) B`
      ASSUME_TAC THENL
     [MATCH_MP_TAC(ISPECL
                   [`??- 70 69 (?? 73 (opair_form 70 71 73 && (73 %% 72)))`;
                    `D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
                    `(71 |-> aac)(v:num->A)`] BVALF_IN_B) THEN
      ASM_REWRITE_TAC[]; ALL_TAC] THEN
    (* ---- O24 mal <= [[??- 70 69 ANTEQ]]_{(71|->aac)v} (through c, *)
    (* PERALPHA); pure ASM_REWRITE ---- *)
    SUBGOAL_THEN `erel D (E:A->A->bool) leq mal
        (bvalf D E B leq ((71 |-> aac)(v:num->A))
              (??- 70 69 (?? 73 (opair_form 70 71 73 && (73 %% 72)))))`
      ASSUME_TAC THENL
     [MATCH_MP_TAC(ISPECL
                   [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`mal:A`;`c:A`;
                    `bvalf D (E:A->A->bool) B leq ((71 |-> aac)(v:num->A))
              (??- 70 69 (?? 73 (opair_form 70 71 73 && (73 %% 72))))`]
                     EPORDER_TRANS) THEN
      ASM_REWRITE_TAC[]; ALL_TAC] THEN
    (* ---- O25 mal <= RHSss via Leibniz at slot 71 (aac -> ss) ---- *)
    SUBGOAL_THEN `erel D (E:A->A->bool) leq mal RHSss` ASSUME_TAC THENL
     [EXPAND_TAC "RHSss" THEN
      MP_TAC(ISPECL
             [`71`;`??- 70 69 (?? 73 (opair_form 70 71 73 && (73 %% 72)))`;
              `D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`v:num->A`;`aac:A`;
              `ss:A`;`mal:A`;`eqc:A`]
        MAXPRIN_LEIBNIZ_STEP) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC]; ALL_TAC] THEN
    (* ---- O26 close contributor: erel eqc i via EBIMP_LE_IMP ---- *)
    MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`eqc:A`;
                  `c:A`;`RHSss:A`;
                  `i:A`;`mal:A`] EBIMP_LE_IMP) THEN ASM_REWRITE_TAC[];
    (* ====== back at main goal: erel m RHSss ====== *)
    (* ---- O27 EBIMP_MEET_LE closes main ---- *)
    MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`msval:A`;
                  `c:A`;`RHSss:A`;
                  `i:A`;`m:A`] EBIMP_MEET_LE) THEN ASM_REWRITE_TAC[]]);;

(* ======================================================================= *)
(* ONTOH_MAIN  (B4 LAYER 1):                                                 *)
(*   If c forces ONTOf (the "f is onto from omega to aleph1"-style body in   *)
(*   the raw bijform setup), then c forces the Kuratowski-encoded h-graph    *)
(*   outer formula  !!- 71 68 (??- 70 69 (?? 73 (opair_form 70 71 73 &&      *)
(*   (73 %% 72)))).  Peels the outer bounded-forall with EBVALF_ALLMEM_GE,   *)
(*   builds the per-ss membership/implication lemmas, and discharges the     *)
(*   per-ss step through ONTOH_OUTER + EBIMP_LE_IMP.                         *)
(*                                                                           *)
(*   Slots under v:  1=a1c, 3=f, 68=a2c, 69=a1c, 72=h.                       *)
(* ======================================================================= *)

let ONTOH_MAIN = prove
 (`!D (E:A->A->bool) B leq onebee realfn f a1 a2 cr a1c a2c h c v.
     model D E ZF_AX /\ (!u:A. u IN D ==> elmem D E u) /\
     ecba D E B leq /\ B IN D /\ leq IN D /\ onebee IN D /\ E onebee B /\
     etop D E B leq onebee /\
     realfn IN D /\ eisfun D E realfn /\ f IN D /\ bname D E B f /\
     h IN D /\ eisfun D E h /\ bname D E B h /\
     (!zz. zz IN D
          ==> (E zz h <=>
               ?cp xi alpha xic rdot op w cpc.
                    cp IN D /\ xi IN D /\ alpha IN D /\ xic IN D /\
                    rdot IN D /\ op IN D /\ w IN D /\ cpc IN D /\
                    E cp cr /\
                    eopair D E xi alpha cp /\ E xi a1 /\ E alpha a2 /\
                    echeck D E onebee xi xic /\ eapply D E realfn alpha rdot /\
                    (?paa pab sa sab psa psab.
                         paa IN D /\ pab IN D /\ sa IN D /\ sab IN D /\
                         psa IN D /\ psab IN D /\
                         eopair D E xic onebee paa /\
                           eopair D E rdot onebee pab /\
                         epair D E paa paa sa /\ epair D E paa pab sab /\
                         eopair D E sa onebee psa /\
                           eopair D E sab onebee psab /\
                         epair D E psa psab op) /\
                    ebv_in D E B leq op f w /\
                    echeck D E onebee cp cpc /\ eopair D E cpc w zz)) /\
     a1 IN D /\ a2 IN D /\ cr IN D /\ a1c IN D /\ a2c IN D /\
     ecross D E a1 a2 cr /\ echeck D E onebee a1 a1c /\
       echeck D E onebee a2 a2c /\
     (!a. a IN D /\ E a a2
          ==> ?rd. eapply D E realfn a rd /\ bname D E B rd /\ rd IN D /\
                   etop D E B leq
                     (bvalf D E B leq ((5 |-> rd)(v:num->A)) (5 %% 2))) /\
     c IN D /\ E c B /\
     valuation D v /\ (!k. bname D E B (v k)) /\
     v 1 = a1c /\ v 3 = f /\ v 68 = a2c /\ v 69 = a1c /\ v 72 = h /\
     erel D E leq c
        (bvalf D E B leq v
           (!! 5 ((5 %% 2) --> ?? 4 ((4 %% 1) && apply_form 3 4 5))))
     ==> erel D E leq c
           (bvalf D E B leq v
              (!!- 71 68
               (??- 70 69 (?? 73 (opair_form 70 71 73 && (73 %% 72))))))`,
  (* ---- M01 strip ---- *)
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  (* ---- M02 label hchar ---- *)
  FIRST_X_ASSUM(LABEL_TAC "hchar" o
    check (fun th -> is_forall(concl th) && vfree_in `h:A` (concl th))) THEN
  (* ---- M03 ebalg/eporder ---- *)
  SUBGOAL_THEN `ebalg D (E:A->A->bool) B leq /\ eporder D E B leq`
    STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[ECBA_IMP_BALG; EBALG_IMP_PORDER]; ALL_TAC] THEN
  (* ---- M04 peel !!- 71 68 with EBVALF_ALLMEM_GE ---- *)
  MATCH_MP_TAC(ISPECL
               [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`v:num->A`;`71`;`68`;
                `??- 70 69 (?? 73 (opair_form 70 71 73 && (73 %% 72)))`;`c:A`]
                 EBVALF_ALLMEM_GE) THEN
  ASM_REWRITE_TAC[] THEN
  (* ---- M05 fix ss ---- *)
  X_GEN_TAC `ss:A` THEN STRIP_TAC THEN
  (* ---- M05b ss IN D (now stripped by M05 from EBVALF_ALLMEM_GE's ss IN D *)
  (* obligation) ---- *)
  SUBGOAL_THEN `(ss:A) IN D` ASSUME_TAC THENL [ASM_MESON_TAC[]; ALL_TAC] THEN
  (* ---- M06 valuation (71|->ss)v ---- *)
  SUBGOAL_THEN `valuation D ((71 |-> ss)(v:num->A)) /\
                (!k. bname D E B (((71 |-> ss)(v:num->A)) k))`
    STRIP_ASSUME_TAC THENL
   [CONJ_TAC THENL
     [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[];
      MATCH_MP_TAC BNAMEVAL_VALMOD THEN ASM_REWRITE_TAC[]]; ALL_TAC] THEN
  (* ---- M07 ebv_in ss a2c msval  (msval = [[71%%68]]_{(71|->ss)v}) ---- *)
  SUBGOAL_THEN `ebv_in D (E:A->A->bool) B leq ss a2c
      (bvalf D E B leq ((71 |-> ss)(v:num->A)) (71 %% 68))` ASSUME_TAC THENL
   [MP_TAC(ISPECL
           [`71`;`68`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
            `(71 |-> ss)(v:num->A)`]
           BVALF_MEM) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[]; ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER; ARITH_EQ]];
     ALL_TAC] THEN
  (* ---- M08 msval IN D ---- *)
  SUBGOAL_THEN
    `bvalf D (E:A->A->bool) B leq ((71 |-> ss)(v:num->A)) (71 %% 68) IN D`
    ASSUME_TAC THENL
   [MP_TAC(ISPECL
           [`71 %% 68`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
            `(71 |-> ss)(v:num->A)`]
           BVALF_SPEC) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN(ACCEPT_TAC o CONJUNCT1)];
    ALL_TAC] THEN
  (* ---- M09 E msval B ---- *)
  SUBGOAL_THEN
    `(E:A->A->bool) (bvalf D E B leq ((71 |-> ss)(v:num->A)) (71 %% 68)) B`
    ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL [`71 %% 68`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
      `(71 |-> ss)(v:num->A)`] BVALF_IN_B) THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  (* ---- M10 RHSss IN D ---- *)
  SUBGOAL_THEN `bvalf D (E:A->A->bool) B leq ((71 |-> ss)(v:num->A))
      (??- 70 69 (?? 73 (opair_form 70 71 73 && (73 %% 72)))) IN D`
    ASSUME_TAC THENL
   [MP_TAC(ISPECL [`??- 70 69 (?? 73 (opair_form 70 71 73 && (73 %% 72)))`;
      `D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`(71 |-> ss)(v:num->A)`]
             BVALF_SPEC) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN(ACCEPT_TAC o CONJUNCT1)];
    ALL_TAC] THEN
  (* ---- M11 E RHSss B ---- *)
  SUBGOAL_THEN `(E:A->A->bool) (bvalf D E B leq ((71 |-> ss)(v:num->A))
      (??- 70 69 (?? 73 (opair_form 70 71 73 && (73 %% 72))))) B`
    ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`??- 70 69 (?? 73 (opair_form 70 71 73 && (73 %% 72)))`;
                  `D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
                  `(71 |-> ss)(v:num->A)`] BVALF_IN_B) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* ---- M12 ebimp msval RHSss iss  (iss = goal RHS) ---- *)
  SUBGOAL_THEN `ebimp D (E:A->A->bool) B leq
      (bvalf D E B leq ((71 |-> ss)(v:num->A)) (71 %% 68))
      (bvalf D E B leq ((71 |-> ss)(v:num->A))
            (??- 70 69 (?? 73 (opair_form 70 71 73 && (73 %% 72)))))
      (bvalf D E B leq ((71 |-> ss)(v:num->A))
            (71 %% 68 -->
             ??- 70 69 (?? 73 (opair_form 70 71 73 && (73 %% 72)))))`
    ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`71 %% 68`;
                  `??- 70 69 (?? 73 (opair_form 70 71 73 && (73 %% 72)))`;
                  `D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
                  `(71 |-> ss)(v:num->A)`] BVALF_IMP) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* ---- M13 m = emeet c msval ---- *)
  SUBGOAL_THEN `?m:A. emeet D (E:A->A->bool) B leq c
      (bvalf D E B leq ((71 |-> ss)(v:num->A)) (71 %% 68)) m`
    (X_CHOOSE_TAC `m:A`) THENL
   [MATCH_MP_TAC EBALG_MEET THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* ---- M14 m IN D / E m B ---- *)
  SUBGOAL_THEN `(m:A) IN D /\ (E:A->A->bool) m B` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[EMEET_IN]; ALL_TAC] THEN
  (* ---- M15 erel m RHSss via ONTOH_OUTER ---- *)
  SUBGOAL_THEN `erel D (E:A->A->bool) leq m
      (bvalf D E B leq ((71 |-> ss)(v:num->A))
            (??- 70 69 (?? 73 (opair_form 70 71 73 && (73 %% 72)))))`
    ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL
                 [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`onebee:A`;
                  `realfn:A`;`f:A`;
                  `a1:A`;`a2:A`;`cr:A`;`a1c:A`;`a2c:A`;`h:A`;`ss:A`;`m:A`;
      `bvalf D (E:A->A->bool) B leq ((71 |-> ss)(v:num->A)) (71 %% 68)`;
      `c:A`;`v:num->A`]
      ONTOH_OUTER) THEN
    REPEAT CONJ_TAC THEN TRY(FIRST_ASSUM ACCEPT_TAC) THEN
    USE_THEN "hchar" ACCEPT_TAC;
    ALL_TAC] THEN
  (* ---- M16 close per-ss via EBIMP_LE_IMP ---- *)
  MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`c:A`;
    `bvalf D (E:A->A->bool) B leq ((71 |-> ss)(v:num->A)) (71 %% 68)`;
    `bvalf D (E:A->A->bool) B leq ((71 |-> ss)(v:num->A))
          (??- 70 69 (?? 73 (opair_form 70 71 73 && (73 %% 72))))`;
    `bvalf D (E:A->A->bool) B leq ((71 |-> ss)(v:num->A))
          (71 %% 68 -->
           ??- 70 69 (?? 73 (opair_form 70 71 73 && (73 %% 72))))`;`m:A`]
    EBIMP_LE_IMP) THEN ASM_REWRITE_TAC[]);;

(* ############################################################################
   (B)-WRAP  BIJFORM_BOT_FROM_BODY :
     if for every B-name f the bijform BODY has value bot under (3|->f)v, then
     [[ bijform 1 2 ]]_v = bot.
     bijform 1 2 = ?? 3 BODY ;
     BVALF_EX_LEAST (w0:=bot) gives [[?? 3 BODY]] <= bot,
     then ELE_BOT (bot is least) closes = bot.
   perf hypothesis is placed FIRST so CONJUNCTS_THEN2 can LABEL it cleanly.
   ######################################################################### *)

let BIJFORM_BOT_FROM_BODY = prove
 (`!D (E:A->A->bool) B leq v bot.
      (!f. f IN D /\ bname D E B f
           ==> bvalf D E B leq ((3 |-> f) v)
                 (!! 4 (!! 5 (apply_form 3 4 5 --> 4 %% 1 && 5 %% 2)) &&
                  !! 4 (4 %% 1 --> ?? 5 (5 %% 2 && apply_form 3 4 5)) &&
                  !! 4 (!! 5
                        (!! 6 (apply_form 3 4 5 && apply_form 3 4 6 -->
                               Eq 5 6))) &&
                  !! 4 (!! 7
                        (!! 5 (apply_form 3 4 5 && apply_form 3 7 5 -->
                               Eq 4 7))) &&
                  !! 5 (5 %% 2 -->
                        ?? 4 (4 %% 1 && apply_form 3 4 5))) = bot) /\
      model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
      valuation D v /\ (!i. bname D E B (v i)) /\
      bot IN D /\ ebot D E B leq bot
      ==> bvalf D E B leq v (bijform 1 2) = bot`,
  REPEAT GEN_TAC THEN
  DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "perf") STRIP_ASSUME_TAC) THEN
  SUBGOAL_THEN `ebalg D (E:A->A->bool) B leq /\ eporder D E B leq`
  STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[ECBA_IMP_BALG; ECBA_IMP_PORDER]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) bot B` ASSUME_TAC THENL
   [ASM_MESON_TAC[ebot]; ALL_TAC] THEN
  SUBGOAL_THEN `(bvalf D (E:A->A->bool) B leq v (bijform 1 2)) IN D /\
                (E:A->A->bool) (bvalf D E B leq v (bijform 1 2)) B`
  STRIP_ASSUME_TAC THENL
   [CONJ_TAC THENL
     [MP_TAC(ISPECL
             [`bijform 1 2`;`D:A->bool`;`E:A->A->bool`;`B:A`;
              `leq:A`;`v:num->A`]
             BVALF_SPEC) THEN ASM_SIMP_TAC[];
      MP_TAC(ISPECL
             [`bijform 1 2`;`D:A->bool`;`E:A->A->bool`;`B:A`;
              `leq:A`;`v:num->A`]
             BVALF_IN_B) THEN ASM_SIMP_TAC[]];
    ALL_TAC] THEN
  SUBGOAL_THEN
    `erel D (E:A->A->bool) leq (bvalf D E B leq v (bijform 1 2)) bot`
  ASSUME_TAC THENL
   [REWRITE_TAC[bijform] THEN CONV_TAC NUM_REDUCE_CONV THEN
    MATCH_MP_TAC BVALF_EX_LEAST THEN ASM_REWRITE_TAC[] THEN
    X_GEN_TAC `a:A` THEN STRIP_TAC THEN
    ASM_REWRITE_TAC[] THEN
    ASM_MESON_TAC[ebot];
    ALL_TAC] THEN
  MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
      `bvalf (D:A->bool) (E:A->A->bool) (B:A) (leq:A) (v:num->A)
       (bijform 1 2)`;
      `bot:A`] ELE_BOT) THEN
  ASM_REWRITE_TAC[]);;

(* ===================================================================== *)
(* B5 : BIJFORM_12_BOT  --  [[bijform 1 2]] = bot  (part (B) of CH_CORE)  *)
(* Monolithic prove, linearized from the verified interactive sequence    *)
(* b5_s0..b5_s5.  All OCaml term/tactic helpers are local `let ... in`.    *)
(* ===================================================================== *)

let BIJFORM_12_BOT = prove
 (`!D (E:A->A->bool) P leqp om bp onebee B leq realfn a1 a2 cr a1c a2c bot v.
      model D E ZF_AX /\ (!u:A. u IN D ==> elmem D E u) /\
      eleqp D E P leqp /\ eroset D E P leqp B /\ eincl D E B leq /\
        ebplus D E B bp /\
      ecba D E B leq /\ eccc D E bp leq /\
      B IN D /\ leq IN D /\ onebee IN D /\ E onebee B /\
        etop D E B leq onebee /\
      realfn IN D /\ eisfun D E realfn /\
      a1 IN D /\ a2 IN D /\ cr IN D /\ a1c IN D /\ a2c IN D /\
      eordinal D E a1 /\ eordinal D E a2 /\ ecardinal D E a1 /\
      ecross D E a1 a2 cr /\ echeck D E onebee a1 a1c /\
        echeck D E onebee a2 a2c /\
      eomega D E om /\ E om a1 /\ ~(?e. einj D E e a2 a1) /\
      (!a. a IN D /\ E a a2 ==> ?rd. rd IN D /\ eapply D E realfn a rd /\
       bname D E B rd) /\
      (!a. a IN D /\ E a a2 ==> ?rd. eapply D E realfn a rd /\
       bname D E B rd /\ rd IN D /\
       etop D E B leq (bvalf D E B leq ((5 |-> rd) v) (5 %% 2))) /\
      (!b1 b2 rd1 rd2 e. b1 IN D /\ b2 IN D /\ rd1 IN D /\
       rd2 IN D /\ e IN D /\
       E b1 a2 /\ E b2 a2 /\ ~(b1 = b2) /\ eapply D E realfn b1 rd1 /\
           eapply D E realfn b2 rd2 /\ ebv_eq D E B leq rd1 rd2 e ==>
             ebot D E B leq e) /\
      valuation D v /\ (!i. bname D E B (v i)) /\
      v 1 = a1c /\
      bot IN D /\ ebot D E B leq bot
      ==> bvalf D E B leq v (bijform 1 2) = bot`,
  (* ---- local helpers ---- *)
  let CLOSE = FIRST_ASSUM ACCEPT_TAC ORELSE FIRST_ASSUM MATCH_ACCEPT_TAC in
  (* body term and its binary-&&-spine projections *)
  let body_tm =
   `!! 4 (!! 5 (apply_form 3 4 5 --> 4 %% 1 && 5 %% 2)) &&
    !! 4 (4 %% 1 --> ?? 5 (5 %% 2 && apply_form 3 4 5)) &&
    !! 4 (!! 5 (!! 6 (apply_form 3 4 5 && apply_form 3 4 6 --> Eq 5 6))) &&
    !! 4 (!! 7 (!! 5 (apply_form 3 4 5 && apply_form 3 7 5 --> Eq 4 7))) &&
    !! 5 (5 %% 2 --> ?? 4 (4 %% 1 && apply_form 3 4 5))` in
  let c1_tm   = lhand body_tm and r1_tm = rand body_tm in
  let c2_tm   = lhand r1_tm   and r2_tm = rand r1_tm in
  let svf_tm  = lhand r2_tm   and r3_tm = rand r2_tm in
  let c4_tm   = lhand r3_tm   and ontof_tm = rand r3_tm in
  let bw q = subst [q,`p:form`]
               `bvalf (D:A->bool) (E:A->A->bool) (B:A) (leq:A) (wf:num->A)
                (p:form)` in
  let c_tm = bw body_tm in
  (* membership-of-bvalf tactic at wf *)
  let memw p =
    (MP_TAC(ISPECL [p;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`wf:num->A`]
            BVALF_SPEC) THEN
     ANTS_TAC THENL [REPEAT CONJ_TAC THEN CLOSE; STRIP_TAC]) THEN
    (MP_TAC(ISPECL [p;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`wf:num->A`]
            BVALF_IN_B) THEN
     ANTS_TAC THENL [REPEAT CONJ_TAC THEN CLOSE; DISCH_TAC]) in
  let andle lem p q =
    MP_TAC(ISPECL
           [p;q;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`wf:num->A`] lem) THEN
       ANTS_TAC THENL [REPEAT CONJ_TAC THEN CLOSE; DISCH_TAC] in
  let tr u v w =
    MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;u;v;w]
           EPORDER_TRANS) THEN
       ANTS_TAC THENL [REPEAT CONJ_TAC THEN CLOSE; DISCH_TAC] in
  (* FV computations for the two congruence transports *)
  let FVSVF = prove
   (`FV (!! 4
         (!! 5 (!! 6
                (apply_form 3 4 5 && apply_form 3 4 6 --> Eq 5 6)))) = {3}`,
    REWRITE_TAC[FV; FV_CLAUSES; FV_APPLY_FORM] THEN
    REWRITE_TAC[EXTENSION; IN_INSERT; NOT_IN_EMPTY; IN_UNION; IN_DELETE] THEN
    ARITH_TAC) in
  let FVONTOF = prove
   (`FV (!! 5 (5 %% 2 --> ?? 4 (4 %% 1 && apply_form 3 4 5))) = {1,2,3}`,
    REWRITE_TAC[FV; FV_CLAUSES; FV_APPLY_FORM] THEN
    REWRITE_TAC[EXTENSION; IN_INSERT; NOT_IN_EMPTY; IN_UNION; IN_DELETE] THEN
    ARITH_TAC) in
  (* s5 term bindings from OMEGA2_NOT_COLLAPSED *)
  let ex72_tm =
    rand(lhand(snd(dest_imp(snd(strip_forall(concl
            OMEGA2_NOT_COLLAPSED)))))) in
  let andbody = rand ex72_tm in
  let svh_tm  = lhand andbody in
  let ontoh_tm = rand andbody in
  let bvp q = subst [q,`p:form`]
                `bvalf (D:A->bool) (E:A->A->bool) (B:A) (leq:A) (vp:num->A)
                 (p:form)` in
  let svh_vp = bvp svh_tm and ontoh_vp = bvp ontoh_tm in
  let and_vp = bvp andbody and ex72_vp = bvp ex72_tm in
  let mk_erel u w =
    subst [u,`uu:A`; w,`ww:A`]
      `erel (D:A->bool) (E:A->A->bool) (leq:A) (uu:A) (ww:A)` in
  let memvp p =
    (MP_TAC(ISPECL [p;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`vp:num->A`]
            BVALF_SPEC) THEN
     ANTS_TAC THENL [REPEAT CONJ_TAC THEN CLOSE; STRIP_TAC]) THEN
    (MP_TAC(ISPECL [p;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`vp:num->A`]
            BVALF_IN_B) THEN
     ANTS_TAC THENL [REPEAT CONJ_TAC THEN CLOSE; DISCH_TAC]) in
  EVERY
   [ (* ---- s0 opening ---- *)
     REPEAT GEN_TAC THEN STRIP_TAC;
     MATCH_MP_TAC BIJFORM_BOT_FROM_BODY;
     REPEAT CONJ_TAC THENL
       [ALL_TAC; CLOSE; CLOSE; CLOSE; CLOSE; CLOSE; CLOSE; CLOSE; CLOSE];
     X_GEN_TAC `f:A` THEN STRIP_TAC;
     (* ---- s1 : bnames, h, abbreviations, valuations, slots ---- *)
     MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`onebee:A`;`B:A`;`a2:A`;`a2c:A`]
            ECHECK_IS_BNAME) THEN
       ANTS_TAC THENL [REPEAT CONJ_TAC THEN CLOSE; DISCH_TAC];
     MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`onebee:A`;`B:A`;`a1:A`;`a1c:A`]
            ECHECK_IS_BNAME) THEN
       ANTS_TAC THENL [REPEAT CONJ_TAC THEN CLOSE; DISCH_TAC];
     MP_TAC(ISPECL
            [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`onebee:A`;`realfn:A`;
             `f:A`;`a1:A`;`a2:A`;`cr:A`] HNAME_EXISTS) THEN
       ANTS_TAC THENL [REPEAT CONJ_TAC THEN CLOSE;
         DISCH_THEN(X_CHOOSE_THEN `h:A` STRIP_ASSUME_TAC)];
     MP_TAC(ISPECL
            [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`onebee:A`;`realfn:A`;
             `f:A`;`a1:A`;`a2:A`;`cr:A`;`h:A`] HNAME_ISFUN) THEN
       ANTS_TAC THENL [REPEAT CONJ_TAC THEN CLOSE; DISCH_TAC];
     MP_TAC(ISPECL
            [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`onebee:A`;`realfn:A`;
             `f:A`;`a1:A`;`a2:A`;`cr:A`;`h:A`] HNAME_BNAME) THEN
       ANTS_TAC THENL [REPEAT CONJ_TAC THEN CLOSE; DISCH_TAC];
     ABBREV_TAC `wf = (3 |-> f) (v:num->A)`;
     ABBREV_TAC `vp = (68 |-> a2c) ((69 |-> a1c) ((72 |-> h) (wf:num->A)))`;
     SUBGOAL_THEN `valuation D (wf:num->A)` ASSUME_TAC THENL
       [EXPAND_TAC "wf" THEN MATCH_MP_TAC VALUATION_VALMOD THEN
        ASM_REWRITE_TAC[]; ALL_TAC];
     SUBGOAL_THEN `!i. bname D E B ((wf:num->A) i)` ASSUME_TAC THENL
       [EXPAND_TAC "wf" THEN MATCH_MP_TAC BNAMEVAL_VALMOD THEN
        ASM_REWRITE_TAC[]; ALL_TAC];
     SUBGOAL_THEN `valuation D (vp:num->A)` ASSUME_TAC THENL
       [EXPAND_TAC "vp" THEN
        REPEAT(MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[]); ALL_TAC];
     SUBGOAL_THEN `!i. bname D E B ((vp:num->A) i)` ASSUME_TAC THENL
       [EXPAND_TAC "vp" THEN
        REPEAT(MATCH_MP_TAC BNAMEVAL_VALMOD THEN ASM_REWRITE_TAC[]); ALL_TAC];
     SUBGOAL_THEN `(wf:num->A) 1 = a1c` ASSUME_TAC THENL
       [EXPAND_TAC "wf" THEN REWRITE_TAC[VALMOD] THEN
        CONV_TAC NUM_REDUCE_CONV THEN
        ASM_REWRITE_TAC[]; ALL_TAC];
     SUBGOAL_THEN `(wf:num->A) 3 = f` ASSUME_TAC THENL
       [EXPAND_TAC "wf" THEN REWRITE_TAC[VALMOD] THEN
        CONV_TAC NUM_REDUCE_CONV; ALL_TAC];
     SUBGOAL_THEN `(vp:num->A) 68 = a2c` ASSUME_TAC THENL
       [EXPAND_TAC "vp" THEN REWRITE_TAC[VALMOD] THEN
        CONV_TAC NUM_REDUCE_CONV; ALL_TAC];
     SUBGOAL_THEN `(vp:num->A) 69 = a1c` ASSUME_TAC THENL
       [EXPAND_TAC "vp" THEN REWRITE_TAC[VALMOD] THEN
        CONV_TAC NUM_REDUCE_CONV; ALL_TAC];
     SUBGOAL_THEN `(vp:num->A) 72 = h` ASSUME_TAC THENL
       [EXPAND_TAC "vp" THEN REWRITE_TAC[VALMOD] THEN
        CONV_TAC NUM_REDUCE_CONV; ALL_TAC];
     SUBGOAL_THEN `(vp:num->A) 1 = a1c` ASSUME_TAC THENL
       [EXPAND_TAC "vp" THEN REWRITE_TAC[VALMOD] THEN
        CONV_TAC NUM_REDUCE_CONV THEN
        ASM_REWRITE_TAC[]; ALL_TAC];
     SUBGOAL_THEN `(vp:num->A) 3 = f` ASSUME_TAC THENL
       [EXPAND_TAC "vp" THEN REWRITE_TAC[VALMOD] THEN
        CONV_TAC NUM_REDUCE_CONV THEN
        ASM_REWRITE_TAC[]; ALL_TAC];
     (* ---- s2 : eporder, memberships, AND_LE, transitivity (F1/F2 at wf) *)
     (* ---- *)
     MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`]
            ECBA_IMP_PORDER) THEN
       ASM_REWRITE_TAC[] THEN DISCH_TAC;
     memw body_tm; memw r1_tm; memw r2_tm; memw r3_tm; memw svf_tm;
     memw ontof_tm;
     andle BVALF_AND_LE_R c1_tm r1_tm;
     andle BVALF_AND_LE_R c2_tm r2_tm;
     andle BVALF_AND_LE_L svf_tm r3_tm;
     andle BVALF_AND_LE_R svf_tm r3_tm;
     andle BVALF_AND_LE_R c4_tm ontof_tm;
     tr (bw body_tm) (bw r1_tm) (bw r2_tm);
     tr (bw body_tm) (bw r2_tm) (bw svf_tm);
     tr (bw body_tm) (bw r2_tm) (bw r3_tm);
     tr (bw body_tm) (bw r3_tm) (bw ontof_tm);
     (* ---- s3 : slot2, eqSVf/eqONTOf transports, SVH_MAIN ---- *)
     SUBGOAL_THEN `(wf:num->A) 2 = v 2` ASSUME_TAC THENL
       [EXPAND_TAC "wf" THEN REWRITE_TAC[VALMOD] THEN
        CONV_TAC NUM_REDUCE_CONV; ALL_TAC];
     SUBGOAL_THEN `(vp:num->A) 2 = v 2` ASSUME_TAC THENL
       [EXPAND_TAC "vp" THEN EXPAND_TAC "wf" THEN REWRITE_TAC[VALMOD] THEN
        CONV_TAC NUM_REDUCE_CONV; ALL_TAC];
     SUBGOAL_THEN
      `bvalf D E B leq (vp:num->A)
         (!! 4 (!! 5
                (!! 6 (apply_form 3 4 5 && apply_form 3 4 6 --> Eq 5 6)))) =
       bvalf D E B leq (wf:num->A)
         (!! 4 (!! 5
                (!! 6 (apply_form 3 4 5 && apply_form 3 4 6 --> Eq 5 6))))`
      ASSUME_TAC THENL
      [MATCH_MP_TAC BVALF_FV_CONG THEN REPEAT CONJ_TAC THEN TRY CLOSE THEN
       X_GEN_TAC `i:num` THEN REWRITE_TAC[FVSVF; IN_INSERT; NOT_IN_EMPTY] THEN
       STRIP_TAC THEN ASM_REWRITE_TAC[]; ALL_TAC];
     SUBGOAL_THEN
      `bvalf D E B leq (vp:num->A)
       (!! 5 (5 %% 2 --> ?? 4 (4 %% 1 && apply_form 3 4 5))) =
       bvalf D E B leq (wf:num->A)
         (!! 5 (5 %% 2 --> ?? 4 (4 %% 1 && apply_form 3 4 5)))`
      ASSUME_TAC THENL
      [MATCH_MP_TAC BVALF_FV_CONG THEN REPEAT CONJ_TAC THEN TRY CLOSE THEN
       X_GEN_TAC `i:num` THEN
       REWRITE_TAC[FVONTOF; IN_INSERT; NOT_IN_EMPTY] THEN
       STRIP_TAC THEN ASM_REWRITE_TAC[]; ALL_TAC];
     MP_TAC(ISPECL
            [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`onebee:A`;`realfn:A`;
             `f:A`;`a1:A`;`a2:A`;`cr:A`;`a1c:A`;`a2c:A`;`h:A`;c_tm;`vp:num->A`]
        SVH_MAIN) THEN
       ANTS_TAC THENL
       [REPEAT CONJ_TAC THEN TRY CLOSE THEN ASM_REWRITE_TAC[]; DISCH_TAC];
     (* ---- s4 : rtot-F9 transport v->vp, ONTOH_MAIN ---- *)
     SUBGOAL_THEN
      `!a. a IN D /\ E a a2 ==> ?rd. eapply D E realfn a rd /\
       bname D E B rd /\ rd IN D /\
          etop D E B leq (bvalf D E B leq ((5 |-> rd) (vp:num->A)) (5 %% 2))`
      ASSUME_TAC THENL
      [X_GEN_TAC `aa:A` THEN STRIP_TAC THEN
       SUBGOAL_THEN
        `?rd. eapply D E realfn aa rd /\ bname D E B rd /\ rd IN D /\
           etop D E B leq (bvalf D E B leq ((5 |-> rd) (v:num->A)) (5 %% 2))`
         (X_CHOOSE_THEN `rd:A` STRIP_ASSUME_TAC) THENL
        [FIRST_ASSUM MATCH_MP_TAC THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
       EXISTS_TAC `rd:A` THEN ASM_REWRITE_TAC[] THEN
       SUBGOAL_THEN `valuation D ((5 |-> rd) (vp:num->A))` ASSUME_TAC THENL
        [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
       SUBGOAL_THEN `!i. bname D E B ((5 |-> rd) (vp:num->A) i)`
         ASSUME_TAC THENL
         [MATCH_MP_TAC BNAMEVAL_VALMOD THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
       SUBGOAL_THEN `valuation D ((5 |-> rd) (v:num->A))` ASSUME_TAC THENL
        [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
       SUBGOAL_THEN `!i. bname D E B ((5 |-> rd) (v:num->A) i)`
         ASSUME_TAC THENL
         [MATCH_MP_TAC BNAMEVAL_VALMOD THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
       SUBGOAL_THEN
        `bvalf D E B leq ((5 |-> rd) (vp:num->A)) (5 %% 2) =
         bvalf D E B leq ((5 |-> rd) (v:num->A)) (5 %% 2)` SUBST1_TAC THENL
        [MATCH_MP_TAC BVALF_FV_CONG THEN REPEAT CONJ_TAC THEN TRY CLOSE THEN
         X_GEN_TAC `i:num` THEN
         REWRITE_TAC[FV; FV_CLAUSES; FV_APPLY_FORM; IN_INSERT; IN_UNION;
                     NOT_IN_EMPTY] THEN
         STRIP_TAC THEN ASM_REWRITE_TAC[VALMOD] THEN
         CONV_TAC NUM_REDUCE_CONV THEN
         ASM_REWRITE_TAC[];
         FIRST_ASSUM ACCEPT_TAC];
       ALL_TAC];
     MP_TAC(ISPECL
            [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`onebee:A`;`realfn:A`;
             `f:A`;`a1:A`;`a2:A`;`cr:A`;`a1c:A`;`a2c:A`;`h:A`;c_tm;`vp:num->A`]
        ONTOH_MAIN) THEN
       ANTS_TAC THENL
       [REPEAT CONJ_TAC THEN TRY CLOSE THEN ASM_REWRITE_TAC[]; DISCH_TAC];
     (* ---- s5 : combine SVh & ONTOh, OMEGA2, ELE_BOT ---- *)
     memvp andbody; memvp ex72_tm;
     MP_TAC(ISPECL
            [svh_tm; ontoh_tm; `D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
             `vp:num->A`]
            BVALF_AND_MEET) THEN
       ANTS_TAC THENL [REPEAT CONJ_TAC THEN CLOSE; DISCH_TAC];
     MP_TAC(ISPECL
            [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
             svh_vp;ontoh_vp;and_vp;c_tm]
            EMEET_GREATEST) THEN
       ANTS_TAC THENL [REPEAT CONJ_TAC THEN CLOSE; DISCH_TAC];
     SUBGOAL_THEN `(72 |-> h) (vp:num->A) = vp` ASSUME_TAC THENL
       [REWRITE_TAC[FUN_EQ_THM] THEN X_GEN_TAC `i:num` THEN
        REWRITE_TAC[VALMOD] THEN
        COND_CASES_TAC THEN ASM_REWRITE_TAC[]; ALL_TAC];
     MP_TAC(ISPECL
            [`72`; andbody; `D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
             `vp:num->A`;`h:A`]
            BVALF_EX_UB) THEN
       ASM_REWRITE_TAC[] THEN DISCH_TAC;
     tr c_tm and_vp ex72_vp;
     MP_TAC(ISPECL
            [`D:A->bool`;`E:A->A->bool`;`P:A`;`leqp:A`;`B:A`;`leq:A`;`bp:A`;
             `onebee:A`;`a2:A`;`a2c:A`;`om:A`;`a1:A`;`a1c:A`;
             `vp:num->A`;`bot:A`]
        OMEGA2_NOT_COLLAPSED) THEN
       ANTS_TAC THENL [REPEAT CONJ_TAC THEN CLOSE; DISCH_TAC];
     SUBGOAL_THEN (mk_erel c_tm `bot:A`) ASSUME_TAC THENL
       [UNDISCH_TAC (mk_eq(ex72_vp,`bot:A`)) THEN
        DISCH_THEN(SUBST1_TAC o SYM) THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC];
     MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;c_tm;`bot:A`]
            ELE_BOT) THEN
       ANTS_TAC THENL [REPEAT CONJ_TAC THEN CLOSE; DISCH_THEN ACCEPT_TAC] ]);;

(* ============================================================= *)
(* F7 (A2) batch 1: ordinal-check-is-top machinery.              *)
(*   [[ordinal_form a^]] = top for any ground ordinal a with      *)
(*   check a^ = ac.  Reused later at a1^ (= aleph_1 check) and at *)
(*   d^ for the iscard_form-2 ordinal part.                        *)
(* ============================================================= *)

(* A2b : [[ 0 %% 1 ]]_{0:=omc,1:=a1c} = top   i.e. [[om^ IN a1^]] = top *)
let A2B_MEMTOP = prove
 (`!D (E:A->A->bool) B leq onebee om omc a1 a1c v.
      model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
      onebee IN D /\ E onebee B /\ etop D E B leq onebee /\
      (!u:A. u IN D ==> elmem D E u) /\
      eomega D E om /\ echeck D E onebee om omc /\
      a1 IN D /\ E om a1 /\ echeck D E onebee a1 a1c /\
      valuation D v /\ (!i. bname D E B (v i)) /\ v 0 = omc /\ v 1 = a1c
      ==> etop D E B leq (bvalf D E B leq v (0 %% 1))`,
  let CLOSE = FIRST_ASSUM ACCEPT_TAC ORELSE FIRST_ASSUM MATCH_ACCEPT_TAC in
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  MP_TAC(ISPECL [`0`;`1`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`v:num->A`]
     BVALF_MEM) THEN
    ANTS_TAC THENL [REPEAT CONJ_TAC THEN CLOSE; ALL_TAC] THEN
  ASM_REWRITE_TAC[] THEN DISCH_TAC THEN
  MP_TAC(ISPECL [`0 %% 1`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`v:num->A`]
     BVALF_SPEC) THEN
    ANTS_TAC THENL
    [REPEAT CONJ_TAC THEN CLOSE; DISCH_THEN STRIP_ASSUME_TAC] THEN
  MP_TAC(ISPECL
         [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`onebee:A`;`om:A`;`a1:A`;
          `omc:A`;`a1c:A`;
                 `bvalf (D:A->bool) (E:A->A->bool) (B:A) (leq:A)
                  (v:num->A) (0 %% 1)`]
     ECHECK_IN_TOP) THEN
    ANTS_TAC THENL [REPEAT CONJ_TAC THEN CLOSE; DISCH_THEN ACCEPT_TAC]);;

(* ECHECK_IN_MONO : d SUBSET a1 (ground) ==> [[w IN d^]] <= [[w IN a1^]]
   for any bname w.  The reusable membership-monotonicity core. *)
let ECHECK_IN_MONO = prove
 (`!D (E:A->A->bool) B leq onebee d dc a1 a1c w zwd zwa.
      model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
      onebee IN D /\ E onebee B /\ etop D E B leq onebee /\

      d IN D /\ a1 IN D /\ (!c:A. c IN D /\ E c d ==> E c a1) /\
      echeck D E onebee d dc /\ echeck D E onebee a1 a1c /\
      bname D E B w /\ w IN D /\
      zwd IN D /\ ebv_in D E B leq w dc zwd /\
      zwa IN D /\ ebv_in D E B leq w a1c zwa
      ==> erel D E leq zwd zwa`,
  let CLOSE = FIRST_ASSUM ACCEPT_TAC ORELSE FIRST_ASSUM MATCH_ACCEPT_TAC in
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  (* check-names dc, a1c IN D *)
  SUBGOAL_THEN `(dc:A) IN D /\ (a1c:A) IN D` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[ECHECK_IMP]; ALL_TAC] THEN
  (* eporder from ecba *)
  MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`] ECBA_IMP_PORDER) THEN
    ASM_REWRITE_TAC[] THEN DISCH_TAC THEN
  (* bname a1c *)
  MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`onebee:A`;`B:A`;`a1:A`;`a1c:A`]
     ECHECK_IS_BNAME) THEN
    ANTS_TAC THENL [REPEAT CONJ_TAC THEN CLOSE; DISCH_TAC] THEN
  (* E zwa B *)
  MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`w:A`;`a1c:A`;`zwa:A`]
     EBV_IN_IN_B) THEN
    ANTS_TAC THENL [REPEAT CONJ_TAC THEN CLOSE; DISCH_TAC] THEN
  (* per-check obligation, as a standing fact *)
  SUBGOAL_THEN
   `!c vc ec. E (c:A) d /\ echeck D E onebee c vc /\ ec IN D /\
              ebv_eq D E B leq w vc ec
              ==> erel D E leq ec zwa`
   ASSUME_TAC THENL
   [MAP_EVERY X_GEN_TAC [`c:A`;`vc:A`;`ec:A`] THEN STRIP_TAC THEN
    (* c, vc IN D *)
    SUBGOAL_THEN `(c:A) IN D /\ (vc:A) IN D` STRIP_ASSUME_TAC THENL
     [ASM_MESON_TAC[ECHECK_IMP]; ALL_TAC] THEN
    (* E c a1 *)
    SUBGOAL_THEN `(E:A->A->bool) (c:A) (a1:A)` ASSUME_TAC THENL
     [ASM_MESON_TAC[]; ALL_TAC] THEN
    (* bname vc *)
    MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`onebee:A`;`B:A`;`c:A`;`vc:A`]
       ECHECK_IS_BNAME) THEN
      ANTS_TAC THENL [REPEAT CONJ_TAC THEN CLOSE; DISCH_TAC] THEN
    (* zca = [[vc IN a1c]] exists *)
    MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`vc:A`;`a1c:A`]
       EBV_IN_VAL_EXISTS) THEN
      ANTS_TAC THENL [REPEAT CONJ_TAC THEN CLOSE; ALL_TAC] THEN
      DISCH_THEN(X_CHOOSE_THEN `zca:A` STRIP_ASSUME_TAC) THEN
    (* etop zca  (c IN a1 so [[vc IN a1c]] = top) *)
    MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`onebee:A`;
                  `c:A`;`a1:A`;
                  `vc:A`;`a1c:A`;`zca:A`] ECHECK_IN_TOP) THEN
      ANTS_TAC THENL [REPEAT CONJ_TAC THEN CLOSE; DISCH_TAC] THEN
    (* ebv_eq vc w ec (symmetry) *)
    MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`w:A`;`vc:A`;`ec:A`]
       EBV_EQ_SYM) THEN
      ANTS_TAC THENL [REPEAT CONJ_TAC THEN CLOSE; DISCH_TAC] THEN
    (* E ec B *)
    MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`w:A`;`vc:A`;`ec:A`]
       EBV_EQ_IN_B) THEN
      ANTS_TAC THENL [REPEAT CONJ_TAC THEN CLOSE; DISCH_TAC] THEN
    (* emeet ec zca ec *)
    MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`zca:A`;`ec:A`]
       EMEET_TOP) THEN
      ANTS_TAC THENL [REPEAT CONJ_TAC THEN CLOSE; DISCH_TAC] THEN
    (* EBV_IN_CONG_L : erel ec zwa *)
    MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`vc:A`;
                  `w:A`;`a1c:A`;
                  `ec:A`;`zca:A`;`zwa:A`;`ec:A`] EBV_IN_CONG_L) THEN
      ANTS_TAC THENL [REPEAT CONJ_TAC THEN CLOSE; DISCH_THEN ACCEPT_TAC];
    ALL_TAC] THEN
  (* main : ECHECK_IN_LE_SUP *)
  MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`onebee:A`;
                `d:A`;`dc:A`;
                `w:A`;`zwd:A`;`zwa:A`] ECHECK_IN_LE_SUP) THEN
    ANTS_TAC THENL [REPEAT CONJ_TAC THEN CLOSE; DISCH_THEN ACCEPT_TAC]);;

(* ECHECK_SUBSET_TOP : d SUBSET a1 (ground) ==> [[ d^ SUBSET a1^ ]] = top.
   The subset-value is esubval a1c dc (superset a1c first).  Via
   ESUBVAL_EQ_SUBSETVAL with zsub := onebee, reducing to ECHECK_IN_MONO. *)
let ECHECK_SUBSET_TOP = prove
 (`!D (E:A->A->bool) B leq onebee d dc a1 a1c z.
      model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
      onebee IN D /\ E onebee B /\ etop D E B leq onebee /\
      d IN D /\ a1 IN D /\ (!c:A. c IN D /\ E c d ==> E c a1) /\
      echeck D E onebee d dc /\ echeck D E onebee a1 a1c /\
      esubval D E B leq a1c dc z /\ z IN D
      ==> etop D E B leq z`,
  let CLOSE = FIRST_ASSUM ACCEPT_TAC ORELSE FIRST_ASSUM MATCH_ACCEPT_TAC in
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  (* check-names dc, a1c IN D *)
  SUBGOAL_THEN `(dc:A) IN D /\ (a1c:A) IN D` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[ECHECK_IMP]; ALL_TAC] THEN
  MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`] ECBA_IMP_BALG) THEN
    ASM_REWRITE_TAC[] THEN DISCH_TAC THEN
  (* bname a1c, bname dc *)
  MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`onebee:A`;`B:A`;`a1:A`;`a1c:A`]
     ECHECK_IS_BNAME) THEN
    ANTS_TAC THENL [REPEAT CONJ_TAC THEN CLOSE; DISCH_TAC] THEN
  MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`onebee:A`;`B:A`;`d:A`;`dc:A`]
     ECHECK_IS_BNAME) THEN
    ANTS_TAC THENL [REPEAT CONJ_TAC THEN CLOSE; DISCH_TAC] THEN
  (* z = onebee via ESUBVAL_EQ_SUBSETVAL *)
  MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`a1c:A`;`dc:A`;`z:A`;
                `onebee:A`] ESUBVAL_EQ_SUBSETVAL) THEN
    ANTS_TAC THENL
     [REPEAT CONJ_TAC THEN TRY CLOSE THENL
       [ (* bullet 1 : lower bound - erel onebee ii *)
         MAP_EVERY X_GEN_TAC [`w:A`;`zwf:A`;`zwx:A`;`ii:A`] THEN STRIP_TAC THEN
         (* [[w IN dc]] <= [[w IN a1c]] *)
         MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
                       `onebee:A`;`d:A`;
                       `dc:A`;`a1:A`;`a1c:A`;`w:A`;`zwf:A`;`zwx:A`]
                    ECHECK_IN_MONO) THEN
           ANTS_TAC THENL [REPEAT CONJ_TAC THEN CLOSE; DISCH_TAC] THEN
         (* E zwf B, E zwx B *)
         MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`w:A`;
                       `dc:A`;`zwf:A`]
                EBV_IN_IN_B) THEN
           ANTS_TAC THENL [REPEAT CONJ_TAC THEN CLOSE; DISCH_TAC] THEN
         MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`w:A`;
                       `a1c:A`;`zwx:A`]
                EBV_IN_IN_B) THEN
           ANTS_TAC THENL [REPEAT CONJ_TAC THEN CLOSE; DISCH_TAC] THEN
         (* etop ii *)
         SUBGOAL_THEN `etop D E B leq (ii:A)` ASSUME_TAC THENL
          [MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
                         `zwf:A`;`zwx:A`;
                         `ii:A`] EBIMP_TOP) THEN
             ANTS_TAC THENL
              [REPEAT CONJ_TAC THEN CLOSE;
               DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN CLOSE];
           ALL_TAC] THEN
         (* erel onebee ii *)
         MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
                       `ii:A`;`onebee:A`]
                ETOP_GE) THEN
           ANTS_TAC THENL [REPEAT CONJ_TAC THEN CLOSE; DISCH_THEN ACCEPT_TAC];
         (* bullet 2 : greatest - erel lb onebee, trivial by top *)
         X_GEN_TAC `lb:A` THEN STRIP_TAC THEN
         MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
                       `onebee:A`;`lb:A`]
                ETOP_GE) THEN
           ANTS_TAC THENL
           [REPEAT CONJ_TAC THEN CLOSE; DISCH_THEN ACCEPT_TAC] ];
      DISCH_THEN(fun th -> ASM_REWRITE_TAC[th])]);;

(* ETRANS_CHECK : for a ground ORDINAL a with check ac, every member value is
   below the subset value:  [[ a' IN a^ ]] <= [[ a' SUBSET a^ ]] =
     esubval ac a'.
   The V^B transitivity of a check-of-ordinal.  Per-check via ESUBVAL_CONG +
   ECHECK_SUBSET_TOP (c SUBSET a from ordinal transitivity). *)
let ETRANS_CHECK = prove
 (`!D (E:A->A->bool) B leq onebee a ac a' zin w0.
      model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
      onebee IN D /\ E onebee B /\ etop D E B leq onebee /\
      a IN D /\ eordinal D E a /\ echeck D E onebee a ac /\
      bname D E B a' /\ a' IN D /\
      zin IN D /\ ebv_in D E B leq a' ac zin /\
      w0 IN D /\ esubval D E B leq ac a' w0
      ==> erel D E leq zin w0`,
  let CLOSE = FIRST_ASSUM ACCEPT_TAC ORELSE FIRST_ASSUM MATCH_ACCEPT_TAC in
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  (* check-name ac IN D *)
  SUBGOAL_THEN `(ac:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[ECHECK_IMP]; ALL_TAC] THEN
  (* eporder *)
  MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`] ECBA_IMP_PORDER) THEN
    ASM_REWRITE_TAC[] THEN DISCH_TAC THEN
  (* bname ac *)
  MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`onebee:A`;`B:A`;`a:A`;`ac:A`]
     ECHECK_IS_BNAME) THEN
    ANTS_TAC THENL [REPEAT CONJ_TAC THEN CLOSE; DISCH_TAC] THEN
  (* E w0 B *)
  MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`ac:A`;`a':A`;`w0:A`]
     ESUBVAL_IN) THEN
    ASM_REWRITE_TAC[] THEN STRIP_TAC THEN
  (* per-check obligation as a standing fact *)
  SUBGOAL_THEN
   `!c vc ec. E (c:A) a /\ echeck D E onebee c vc /\ ec IN D /\
              ebv_eq D E B leq a' vc ec
              ==> erel D E leq ec w0`
   ASSUME_TAC THENL
   [MAP_EVERY X_GEN_TAC [`c:A`;`vc:A`;`ec:A`] THEN STRIP_TAC THEN
    (* c, vc IN D *)
    SUBGOAL_THEN `(c:A) IN D /\ (vc:A) IN D` STRIP_ASSUME_TAC THENL
     [ASM_MESON_TAC[ECHECK_IMP]; ALL_TAC] THEN
    (* bname vc *)
    MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`onebee:A`;`B:A`;`c:A`;`vc:A`]
       ECHECK_IS_BNAME) THEN
      ANTS_TAC THENL [REPEAT CONJ_TAC THEN CLOSE; DISCH_TAC] THEN
    (* c SUBSET a (D-confined) *)
    SUBGOAL_THEN `!y:A. y IN D /\ (E:A->A->bool) y (c:A) ==> E y (a:A)`
      ASSUME_TAC THENL
      [ASM_MESON_TAC[EORDINAL_TRANS_MEM]; ALL_TAC] THEN
    (* esubval ac vc exists *)
    MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`ac:A`;`vc:A`]
       ESUBVAL_EXISTS) THEN
      ANTS_TAC THENL [REPEAT CONJ_TAC THEN CLOSE; ALL_TAC] THEN
      DISCH_THEN(X_CHOOSE_THEN `zvx:A` ASSUME_TAC) THEN
    (* zvx IN D, E zvx B *)
    MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`ac:A`;
                  `vc:A`;`zvx:A`]
           ESUBVAL_IN) THEN
      ASM_REWRITE_TAC[] THEN STRIP_TAC THEN
    (* etop zvx  (A2s : c SUBSET a) *)
    MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`onebee:A`;
                  `c:A`;`vc:A`;
                  `a:A`;`ac:A`;`zvx:A`] ECHECK_SUBSET_TOP) THEN
      ANTS_TAC THENL [REPEAT CONJ_TAC THEN CLOSE; DISCH_TAC] THEN
    (* E ec B *)
    MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`a':A`;
                  `vc:A`;`ec:A`]
           EBV_EQ_IN_B) THEN
      ANTS_TAC THENL [REPEAT CONJ_TAC THEN CLOSE; DISCH_TAC] THEN
    (* emeet ec zvx ec *)
    MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`zvx:A`;`ec:A`]
       EMEET_TOP) THEN
      ANTS_TAC THENL [REPEAT CONJ_TAC THEN CLOSE; DISCH_TAC] THEN
    (* ESUBVAL_CONG : erel ec w0 *)
    MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`ac:A`;
                  `a':A`;`vc:A`;
                  `ec:A`;`zvx:A`;`w0:A`;`ec:A`] ESUBVAL_CONG) THEN
      ANTS_TAC THENL [REPEAT CONJ_TAC THEN CLOSE; DISCH_THEN ACCEPT_TAC];
    ALL_TAC] THEN
  (* main : ECHECK_IN_LE_SUP *)
  MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`onebee:A`;
                `a:A`;`ac:A`;
                `a':A`;`zin:A`;`w0:A`] ECHECK_IN_LE_SUP) THEN
    ANTS_TAC THENL [REPEAT CONJ_TAC THEN CLOSE; DISCH_THEN ACCEPT_TAC]);;

(* TRANSFORM_CHECK_TOP : [[ transitive_form i ]]_v = top  when v i = ac is the
   check of a ground ordinal a.  Peel !!- (i+1) i (subset_form (i+1) i) by
   BVALF_FORALLMEM_TOP, evaluate the atoms (BVALF_MEM, SUBSETFORM_VAL), and
   discharge the per-member inequality by ETRANS_CHECK.  General in slot i. *)
let TRANSFORM_CHECK_TOP = prove
 (`!D (E:A->A->bool) B leq onebee a ac i v.
      model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
      onebee IN D /\ E onebee B /\ etop D E B leq onebee /\
      a IN D /\ eordinal D E a /\ echeck D E onebee a ac /\
      valuation D v /\ (!n. bname D E B (v n)) /\ v i = ac
      ==> etop D E B leq (bvalf D E B leq v (transitive_form i))`,
  let CLOSE = FIRST_ASSUM ACCEPT_TAC ORELSE FIRST_ASSUM MATCH_ACCEPT_TAC in
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  (* check-name ac IN D *)
  SUBGOAL_THEN `(ac:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[ECHECK_IMP]; ALL_TAC] THEN
  REWRITE_TAC[transitive_form] THEN
  (* bname ac *)
  MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`onebee:A`;`B:A`;`a:A`;`ac:A`]
     ECHECK_IS_BNAME) THEN
    ANTS_TAC THENL [REPEAT CONJ_TAC THEN CLOSE; DISCH_TAC] THEN
  (* arithmetic disequalities for valmod *)
  SUBGOAL_THEN `~((i:num) + 1 = i) /\ ~((i:num) = i + 1)`
    STRIP_ASSUME_TAC THENL
   [ARITH_TAC; ALL_TAC] THEN
  (* peel the bounded forall *)
  MP_TAC(ISPECL[`(i:num)+1`;`i:num`;`subset_form ((i:num)+1) i`;
                `D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`v:num->A`]
     BVALF_FORALLMEM_TOP) THEN
    ANTS_TAC THENL [REPEAT CONJ_TAC THEN CLOSE; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  X_GEN_TAC `a':A` THEN STRIP_TAC THEN
  (* vv = ((i+1)|->a') v : valuation, all bname, slot values *)
  ABBREV_TAC `vv = (((i:num)+1) |-> (a':A)) v` THEN
  SUBGOAL_THEN `valuation D (vv:num->A) /\ (!n. bname D E B ((vv:num->A) n))`
    STRIP_ASSUME_TAC THENL
   [EXPAND_TAC "vv" THEN CONJ_TAC THENL
     [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[];
      MATCH_MP_TAC BNAMEVAL_VALMOD THEN ASM_REWRITE_TAC[]]; ALL_TAC] THEN
  SUBGOAL_THEN `(vv:num->A) ((i:num)+1) = a' /\ (vv:num->A) i = ac`
    STRIP_ASSUME_TAC THENL
   [EXPAND_TAC "vv" THEN ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER];
    ALL_TAC] THEN
  (* zin = [[ (i+1)%%i ]]_vv : ebv_in a' ac zin  (keep full term, no abbrev) *)
  MP_TAC(ISPECL[`(i:num)+1`;`i:num`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
                `vv:num->A`] BVALF_MEM) THEN
    ANTS_TAC THENL [REPEAT CONJ_TAC THEN CLOSE; ALL_TAC] THEN
    ASM_REWRITE_TAC[] THEN DISCH_TAC THEN
  SUBGOAL_THEN
   `(bvalf D (E:A->A->bool) B leq (vv:num->A) (((i:num)+1) %% i)) IN D`
   ASSUME_TAC THENL
   [MP_TAC(ISPECL[`((i:num)+1) %% i`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
                  `vv:num->A`] BVALF_SPEC) THEN
      ANTS_TAC THENL [REPEAT CONJ_TAC THEN CLOSE; SIMP_TAC[]]; ALL_TAC] THEN
  (* w0 = esubval ac a' *)
  MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`ac:A`;`a':A`]
     ESUBVAL_EXISTS) THEN
    ANTS_TAC THENL [REPEAT CONJ_TAC THEN CLOSE; ALL_TAC] THEN
    DISCH_THEN(X_CHOOSE_THEN `w0:A` ASSUME_TAC) THEN
  MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`ac:A`;`a':A`;`w0:A`]
     ESUBVAL_IN) THEN
    ASM_REWRITE_TAC[] THEN STRIP_TAC THEN
  (* [[subset_form (i+1) i]]_vv = w0 *)
  SUBGOAL_THEN
   `bvalf D (E:A->A->bool) B leq (vv:num->A) (subset_form ((i:num)+1) i) = w0`
   ASSUME_TAC THENL
   [MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`vv:num->A`;
                  `(i:num)+1`;`i:num`;`a':A`;`ac:A`;`w0:A`]
                  SUBSETFORM_VAL) THEN
      ANTS_TAC THENL [REPEAT CONJ_TAC THEN CLOSE; DISCH_THEN ACCEPT_TAC];
    ALL_TAC] THEN
  ASM_REWRITE_TAC[] THEN
  (* goal now: erel [[(i+1)%%i]]_vv w0  via ETRANS_CHECK *)
  MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`onebee:A`;
                `a:A`;`ac:A`;
                `a':A`;
                `bvalf D (E:A->A->bool) B leq (vv:num->A) (((i:num)+1) %% i)`;
                `w0:A`] ETRANS_CHECK) THEN
    ANTS_TAC THENL [REPEAT CONJ_TAC THEN CLOSE; DISCH_THEN ACCEPT_TAC]);;

(* ELINEAR_CELL : the per-(d1,d2) trichotomy cell for the linear lemma.
   For a ground ordinal a with members d1,d2 (checks vd1,vd2) and arbitrary
   bnames a1',a2', the meet of the two "name=check" weights is below any ztr
   that dominates all three trichotomy disjunct values
     [[a1' IN a2']] , [[a1' = a2']] , [[a2' IN a1']].
   Ground trichotomy on d1,d2 (ordinals) picks the disjunct;
   two Boolean-equality
   congruences (EBV_IN_CONG_R then _L, or EBV_EQ_CONG twice) transport the
   check-top witness to the name level. *)
let ELINEAR_CELL = prove
 (`!D (E:A->A->bool) B leq onebee a d1 d2 vd1 vd2 a1' a2'
       z11 z22 m zin12 zeq12 zin21 ztr.
      model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
      onebee IN D /\ E onebee B /\ etop D E B leq onebee /\
      a IN D /\ eordinal D E a /\
      d1 IN D /\ d2 IN D /\ E d1 a /\ E d2 a /\
      echeck D E onebee d1 vd1 /\ echeck D E onebee d2 vd2 /\
      bname D E B a1' /\ a1' IN D /\ bname D E B a2' /\ a2' IN D /\
      z11 IN D /\ ebv_eq D E B leq a1' vd1 z11 /\
      z22 IN D /\ ebv_eq D E B leq a2' vd2 z22 /\
      m IN D /\ emeet D E B leq z11 z22 m /\
      zin12 IN D /\ ebv_in D E B leq a1' a2' zin12 /\
      zeq12 IN D /\ ebv_eq D E B leq a1' a2' zeq12 /\
      zin21 IN D /\ ebv_in D E B leq a2' a1' zin21 /\
      ztr IN D /\ E ztr B /\
      erel D E leq zin12 ztr /\ erel D E leq zeq12 ztr /\
        erel D E leq zin21 ztr
      ==> erel D E leq m ztr`,
  let CLOSE = FIRST_ASSUM ACCEPT_TAC ORELSE FIRST_ASSUM MATCH_ACCEPT_TAC in
  let exmeet tx ty nm =
    MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;tx;ty]
           EBALG_MEET) THEN
    ANTS_TAC THENL [REPEAT CONJ_TAC THEN CLOSE; ALL_TAC] THEN
    DISCH_THEN(X_CHOOSE_THEN nm ASSUME_TAC) THEN
    MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;tx;ty;nm]
           EMEET_IN) THEN
    ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; STRIP_TAC] in
  let great tx ty tz =
    MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;tx;ty;tz;`m:A`]
      EMEET_GREATEST) THEN
    ANTS_TAC THENL [REPEAT CONJ_TAC THEN CLOSE; DISCH_TAC] in
  let tr tu tv tw =
    MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;tu;tv;tw]
           EPORDER_TRANS) THEN
    ANTS_TAC THENL [REPEAT CONJ_TAC THEN CLOSE; DISCH_TAC] in
  let fin tu tv tw =
    MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;tu;tv;tw]
           EPORDER_TRANS) THEN
    ANTS_TAC THENL [REPEAT CONJ_TAC THEN CLOSE; DISCH_THEN ACCEPT_TAC] in
  let exin tu tv nm =
    MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;tu;tv]
           EBV_IN_VAL_EXISTS) THEN
    ANTS_TAC THENL [REPEAT CONJ_TAC THEN CLOSE; ALL_TAC] THEN
    DISCH_THEN(X_CHOOSE_THEN nm STRIP_ASSUME_TAC) in
  let exeq tu tv nm =
    MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;tu;tv]
           EBV_EQ_VAL_EXISTS) THEN
    ANTS_TAC THENL [REPEAT CONJ_TAC THEN CLOSE; ALL_TAC] THEN
    DISCH_THEN(X_CHOOSE_THEN nm STRIP_ASSUME_TAC) in
  let eqsym tu tv tz =
    MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;tu;tv;tz]
           EBV_EQ_SYM) THEN
    ANTS_TAC THENL [REPEAT CONJ_TAC THEN CLOSE; DISCH_TAC] in
  let etopge tu =
    MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;tu;`m:A`]
           ETOP_GE) THEN
    ANTS_TAC THENL [REPEAT CONJ_TAC THEN CLOSE; DISCH_TAC] in
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  (* check-names vd1, vd2 IN D *)
  SUBGOAL_THEN `(vd1:A) IN D /\ (vd2:A) IN D` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[ECHECK_IMP]; ALL_TAC] THEN
  SUBGOAL_THEN `ebalg D (E:A->A->bool) B leq` ASSUME_TAC THENL
   [ASM_MESON_TAC[ECBA_IMP_BALG]; ALL_TAC] THEN
  SUBGOAL_THEN `eporder D (E:A->A->bool) B leq` ASSUME_TAC THENL
   [ASM_MESON_TAC[ECBA_IMP_PORDER]; ALL_TAC] THEN
  (* bname vd1, vd2 *)
  MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`onebee:A`;`B:A`;`d1:A`;`vd1:A`]
     ECHECK_IS_BNAME) THEN ANTS_TAC THENL
  [REPEAT CONJ_TAC THEN CLOSE; DISCH_TAC] THEN
  MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`onebee:A`;`B:A`;`d2:A`;`vd2:A`]
     ECHECK_IS_BNAME) THEN ANTS_TAC THENL
  [REPEAT CONJ_TAC THEN CLOSE; DISCH_TAC] THEN
  (* d1,d2 ordinals *)
  MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`a:A`;`d1:A`] EORDINAL_MEMBER) THEN
    ANTS_TAC THENL [REPEAT CONJ_TAC THEN CLOSE; DISCH_TAC] THEN
  MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`a:A`;`d2:A`] EORDINAL_MEMBER) THEN
    ANTS_TAC THENL [REPEAT CONJ_TAC THEN CLOSE; DISCH_TAC] THEN
  (* E z11 B, E z22 B, E m B, erel m z11, erel m z22 *)
  MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`a1':A`;
                `vd1:A`;`z11:A`]
         EBV_EQ_IN_B) THEN ANTS_TAC THENL
  [REPEAT CONJ_TAC THEN CLOSE; DISCH_TAC] THEN
  MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`a2':A`;
                `vd2:A`;`z22:A`]
         EBV_EQ_IN_B) THEN ANTS_TAC THENL
  [REPEAT CONJ_TAC THEN CLOSE; DISCH_TAC] THEN
  MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`a1':A`;
                `a2':A`;`zin12:A`]
         EBV_IN_IN_B) THEN ANTS_TAC THENL
  [REPEAT CONJ_TAC THEN CLOSE; DISCH_TAC] THEN
  MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`a1':A`;
                `a2':A`;`zeq12:A`]
         EBV_EQ_IN_B) THEN ANTS_TAC THENL
  [REPEAT CONJ_TAC THEN CLOSE; DISCH_TAC] THEN
  MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`a2':A`;
                `a1':A`;`zin21:A`]
         EBV_IN_IN_B) THEN ANTS_TAC THENL
  [REPEAT CONJ_TAC THEN CLOSE; DISCH_TAC] THEN
  MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`z11:A`;`z22:A`;`m:A`]
     EMEET_IN) THEN ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; STRIP_TAC] THEN
  MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`z11:A`;`z22:A`;`m:A`]
     EMEET_LE) THEN ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; STRIP_TAC] THEN
  (* ground trichotomy on d1,d2 *)
  MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`d1:A`;`d2:A`]
         EORDINAL_TRICHOTOMY) THEN
    ANTS_TAC THENL [REPEAT CONJ_TAC THEN CLOSE; ALL_TAC] THEN
  STRIP_TAC THENL
   [ (* ===== case E d1 d2 : m <= zin12 <= ztr ===== *)
    exin `vd1:A` `vd2:A` `zdd:A` THEN
    MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`onebee:A`;
                  `d1:A`;`d2:A`;
                  `vd1:A`;`vd2:A`;`zdd:A`] ECHECK_IN_TOP) THEN
      ANTS_TAC THENL [REPEAT CONJ_TAC THEN CLOSE; DISCH_TAC] THEN
    exin `vd1:A` `a2':A` `zd2:A` THEN
    eqsym `a2':A` `vd2:A` `z22:A` THEN
    exmeet `z22:A` `zdd:A` `m1:A` THEN
    MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`vd2:A`;
                  `a2':A`;`vd1:A`;
                  `z22:A`;`zdd:A`;`zd2:A`;`m1:A`] EBV_IN_CONG_R) THEN
      ANTS_TAC THENL [REPEAT CONJ_TAC THEN CLOSE; DISCH_TAC] THEN
    eqsym `a1':A` `vd1:A` `z11:A` THEN
    exmeet `z11:A` `zd2:A` `m2:A` THEN
    MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`vd1:A`;
                  `a1':A`;`a2':A`;
                  `z11:A`;`zd2:A`;`zin12:A`;`m2:A`] EBV_IN_CONG_L) THEN
      ANTS_TAC THENL [REPEAT CONJ_TAC THEN CLOSE; DISCH_TAC] THEN
    etopge `zdd:A` THEN
    great `z22:A` `zdd:A` `m1:A` THEN
    tr `m:A` `m1:A` `zd2:A` THEN
    great `z11:A` `zd2:A` `m2:A` THEN
    tr `m:A` `m2:A` `zin12:A` THEN
    fin `m:A` `zin12:A` `ztr:A`;
    (* ===== case d1 = d2 : m <= zeq12 <= ztr ===== *)
    exeq `vd1:A` `vd2:A` `zee:A` THEN
    MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`onebee:A`;
                  `d1:A`;`d2:A`;
                  `vd1:A`;`vd2:A`;`zee:A`] ECHECK_EQ_TOP) THEN
      ANTS_TAC THENL [REPEAT CONJ_TAC THEN CLOSE; DISCH_TAC] THEN
    exeq `a1':A` `vd2:A` `zx:A` THEN
    exmeet `z11:A` `zee:A` `m1:A` THEN
    MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`a1':A`;
                  `vd1:A`;`vd2:A`;
                  `z11:A`;`zee:A`;`zx:A`;`m1:A`] EBV_EQ_CONG) THEN
      ANTS_TAC THENL [REPEAT CONJ_TAC THEN CLOSE; DISCH_TAC] THEN
    eqsym `a2':A` `vd2:A` `z22:A` THEN
    exmeet `zx:A` `z22:A` `m2:A` THEN
    MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`a1':A`;
                  `vd2:A`;`a2':A`;
                  `zx:A`;`z22:A`;`zeq12:A`;`m2:A`] EBV_EQ_CONG) THEN
      ANTS_TAC THENL [REPEAT CONJ_TAC THEN CLOSE; DISCH_TAC] THEN
    etopge `zee:A` THEN
    great `z11:A` `zee:A` `m1:A` THEN
    tr `m:A` `m1:A` `zx:A` THEN
    great `zx:A` `z22:A` `m2:A` THEN
    tr `m:A` `m2:A` `zeq12:A` THEN
    fin `m:A` `zeq12:A` `ztr:A`;
    (* ===== case E d2 d1 : m <= zin21 <= ztr ===== *)
    exin `vd2:A` `vd1:A` `zdd:A` THEN
    MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`onebee:A`;
                  `d2:A`;`d1:A`;
                  `vd2:A`;`vd1:A`;`zdd:A`] ECHECK_IN_TOP) THEN
      ANTS_TAC THENL [REPEAT CONJ_TAC THEN CLOSE; DISCH_TAC] THEN
    exin `vd2:A` `a1':A` `zd1:A` THEN
    eqsym `a1':A` `vd1:A` `z11:A` THEN
    exmeet `z11:A` `zdd:A` `m1:A` THEN
    MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`vd1:A`;
                  `a1':A`;`vd2:A`;
                  `z11:A`;`zdd:A`;`zd1:A`;`m1:A`] EBV_IN_CONG_R) THEN
      ANTS_TAC THENL [REPEAT CONJ_TAC THEN CLOSE; DISCH_TAC] THEN
    eqsym `a2':A` `vd2:A` `z22:A` THEN
    exmeet `z22:A` `zd1:A` `m2:A` THEN
    MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`vd2:A`;
                  `a2':A`;`a1':A`;
                  `z22:A`;`zd1:A`;`zin21:A`;`m2:A`] EBV_IN_CONG_L) THEN
      ANTS_TAC THENL [REPEAT CONJ_TAC THEN CLOSE; DISCH_TAC] THEN
    etopge `zdd:A` THEN
    great `z11:A` `zdd:A` `m1:A` THEN
    tr `m:A` `m1:A` `zd1:A` THEN
    great `z22:A` `zd1:A` `m2:A` THEN
    tr `m:A` `m2:A` `zin21:A` THEN
    fin `m:A` `zin21:A` `ztr:A`]);;

(* ELINEAR_CORE : the double-supremum core of the linear lemma.
     meet [[a1' IN ac]] [[a2' IN ac]]  <=  tval
   for a ground ordinal a with check ac and any tval dominating the three
   trichotomy disjunct values.  Prove by residuating twice (EBIMP_LE/MEET) so
   each supremum ECHECK_IN_LE_SUP reduces to the per-member check weight, with
   ELINEAR_CELL discharging the innermost per-(d1,d2) obligation. *)
let ELINEAR_CORE = prove
 (`!D (E:A->A->bool) B leq onebee a ac a1' a2' w1 w2 tval mm zin12 zeq12 zin21.
      model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
      onebee IN D /\ E onebee B /\ etop D E B leq onebee /\
      a IN D /\ eordinal D E a /\ echeck D E onebee a ac /\
      bname D E B a1' /\ a1' IN D /\ bname D E B a2' /\ a2' IN D /\
      w1 IN D /\ ebv_in D E B leq a1' ac w1 /\
      w2 IN D /\ ebv_in D E B leq a2' ac w2 /\
      zin12 IN D /\ ebv_in D E B leq a1' a2' zin12 /\
      zeq12 IN D /\ ebv_eq D E B leq a1' a2' zeq12 /\
      zin21 IN D /\ ebv_in D E B leq a2' a1' zin21 /\
      tval IN D /\ E tval B /\
      erel D E leq zin12 tval /\ erel D E leq zeq12 tval /\
        erel D E leq zin21 tval /\
      mm IN D /\ emeet D E B leq w1 w2 mm
      ==> erel D E leq mm tval`,
  let CLOSE = FIRST_ASSUM ACCEPT_TAC ORELSE FIRST_ASSUM MATCH_ACCEPT_TAC in
  let exmeet tx ty nm =
    MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;tx;ty]
           EBALG_MEET) THEN
    ANTS_TAC THENL [REPEAT CONJ_TAC THEN CLOSE; ALL_TAC] THEN
    DISCH_THEN(X_CHOOSE_THEN nm ASSUME_TAC) THEN
    MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;tx;ty;nm]
           EMEET_IN) THEN
    ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; STRIP_TAC] in
  let eximp tx ty nm =
    MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;tx;ty]
           EBIMP_EXISTS) THEN
    ANTS_TAC THENL [REPEAT CONJ_TAC THEN CLOSE; ALL_TAC] THEN
    DISCH_THEN(X_CHOOSE_THEN nm ASSUME_TAC) THEN
    MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;tx;ty;nm]
           EBIMP_IN) THEN
    ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; STRIP_TAC] in
  let meetsym tx ty tz =
    MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;tx;ty;tz]
           EMEET_SYM) THEN
    ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; DISCH_TAC] in
  let einb tu tv tz =
    MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;tu;tv;tz]
           EBV_IN_IN_B) THEN
    ANTS_TAC THENL [REPEAT CONJ_TAC THEN CLOSE; DISCH_TAC] in
  let eqinb tu tv tz =
    MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;tu;tv;tz]
           EBV_EQ_IN_B) THEN
    ANTS_TAC THENL [REPEAT CONJ_TAC THEN CLOSE; DISCH_TAC] in
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  (* check-name ac IN D *)
  SUBGOAL_THEN `(ac:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[ECHECK_IMP]; ALL_TAC] THEN
  SUBGOAL_THEN `ebalg D (E:A->A->bool) B leq` ASSUME_TAC THENL
   [ASM_MESON_TAC[ECBA_IMP_BALG]; ALL_TAC] THEN
  SUBGOAL_THEN `eporder D (E:A->A->bool) B leq` ASSUME_TAC THENL
   [ASM_MESON_TAC[ECBA_IMP_PORDER]; ALL_TAC] THEN
  einb `a1':A` `ac:A` `w1:A` THEN
  einb `a2':A` `ac:A` `w2:A` THEN
  (* imp0 = ebimp w2 tval *)
  eximp `w2:A` `tval:A` `imp0:A` THEN
  (* perd1 : outer-member obligation of the a1'-supremum *)
  SUBGOAL_THEN
   `!d1 vd1 e1. E (d1:A) a /\ echeck D E onebee d1 vd1 /\ e1 IN D /\
                ebv_eq D E B leq a1' vd1 e1
                ==> erel D E leq e1 imp0`
   (LABEL_TAC "perd1") THENL
   [MAP_EVERY X_GEN_TAC [`d1:A`;`vd1:A`;`e1:A`] THEN STRIP_TAC THEN
    (* d1, vd1 IN D *)
    SUBGOAL_THEN `(d1:A) IN D /\ (vd1:A) IN D` STRIP_ASSUME_TAC THENL
     [ASM_MESON_TAC[ECHECK_IMP]; ALL_TAC] THEN
    MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`onebee:A`;`B:A`;`d1:A`;`vd1:A`]
       ECHECK_IS_BNAME) THEN
      ANTS_TAC THENL [REPEAT CONJ_TAC THEN CLOSE; DISCH_TAC] THEN
    eqinb `a1':A` `vd1:A` `e1:A` THEN
    (* imp1 = ebimp e1 tval *)
    eximp `e1:A` `tval:A` `imp1:A` THEN
    (* perd2 : inner-member obligation of the a2'-supremum *)
    SUBGOAL_THEN
     `!d2 vd2 e2. E (d2:A) a /\ echeck D E onebee d2 vd2 /\ e2 IN D /\
                  ebv_eq D E B leq a2' vd2 e2
                  ==> erel D E leq e2 imp1`
     (LABEL_TAC "perd2") THENL
     [MAP_EVERY X_GEN_TAC [`d2:A`;`vd2:A`;`e2:A`] THEN STRIP_TAC THEN
      (* d2, vd2 IN D *)
      SUBGOAL_THEN `(d2:A) IN D /\ (vd2:A) IN D` STRIP_ASSUME_TAC THENL
       [ASM_MESON_TAC[ECHECK_IMP]; ALL_TAC] THEN
      MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`onebee:A`;`B:A`;`d2:A`;`vd2:A`]
         ECHECK_IS_BNAME) THEN
        ANTS_TAC THENL [REPEAT CONJ_TAC THEN CLOSE; DISCH_TAC] THEN
      eqinb `a2':A` `vd2:A` `e2:A` THEN
      exmeet `e2:A` `e1:A` `me2e1:A` THEN
      meetsym `e2:A` `e1:A` `me2e1:A` THEN
      MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`onebee:A`;`a:A`;
                    `d1:A`;`d2:A`;`vd1:A`;`vd2:A`;`a1':A`;`a2':A`;
                    `e1:A`;`e2:A`;
                    `me2e1:A`;`zin12:A`;`zeq12:A`;`zin21:A`;`tval:A`]
           ELINEAR_CELL) THEN
        ANTS_TAC THENL [REPEAT CONJ_TAC THEN CLOSE; DISCH_TAC] THEN
      MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`e2:A`;
                    `e1:A`;`tval:A`;
                    `imp1:A`;`me2e1:A`] EBIMP_LE_IMP) THEN
        ANTS_TAC THENL [REPEAT CONJ_TAC THEN CLOSE; DISCH_THEN ACCEPT_TAC];
      ALL_TAC] THEN
    (* erel w2 imp1 by the a2'-supremum *)
    MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`onebee:A`;
                  `a:A`;`ac:A`;
                  `a2':A`;`w2:A`;`imp1:A`] ECHECK_IN_LE_SUP) THEN
      ANTS_TAC THENL [REPEAT CONJ_TAC THEN CLOSE; DISCH_TAC] THEN
    exmeet `e1:A` `w2:A` `me1w2:A` THEN
    meetsym `e1:A` `w2:A` `me1w2:A` THEN
    MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`w2:A`;
                  `e1:A`;`tval:A`;
                  `imp1:A`;`me1w2:A`] EBIMP_MEET_LE) THEN
      ANTS_TAC THENL [REPEAT CONJ_TAC THEN CLOSE; DISCH_TAC] THEN
    MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`e1:A`;
                  `w2:A`;`tval:A`;
                  `imp0:A`;`me1w2:A`] EBIMP_LE_IMP) THEN
      ANTS_TAC THENL [REPEAT CONJ_TAC THEN CLOSE; DISCH_THEN ACCEPT_TAC];
    ALL_TAC] THEN
  (* erel w1 imp0 by the a1'-supremum *)
  MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`onebee:A`;
                `a:A`;`ac:A`;
                `a1':A`;`w1:A`;`imp0:A`] ECHECK_IN_LE_SUP) THEN
    ANTS_TAC THENL [REPEAT CONJ_TAC THEN CLOSE; DISCH_TAC] THEN
  (* final residuation : meet w1 w2 = mm <= tval *)
  MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`w1:A`;
                `w2:A`;`tval:A`;
                `imp0:A`;`mm:A`] EBIMP_MEET_LE) THEN
    ANTS_TAC THENL [REPEAT CONJ_TAC THEN CLOSE; DISCH_THEN ACCEPT_TAC]);;

(* LINFORM_CHECK_TOP : [[ linear_form i ]]_v = top  when v i = ac is the check
   of a ground ordinal a.  Peel the two bounded foralls (BVALF_FORALLMEM_TOP
   outer, EBVALF_ALLMEM_GE inner), evaluate the atoms of the trichotomy body
   (BVALF_MEM/BVALF_EQ2/BVALF_OR), then residuate (EBIMP_LE_IMP) to the double
   supremum ELINEAR_CORE.  General in slot i.
   NB antiquotation is unavailable here, so the trichotomy body is written out
   in full at every in-quotation site; the OCaml values trich/pOr (same surface
   syntax) are reused only as bare ISPECL arguments. *)
let LINFORM_CHECK_TOP = prove
 (`!D (E:A->A->bool) B leq onebee a ac i v.
      model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
      onebee IN D /\ E onebee B /\ etop D E B leq onebee /\
      a IN D /\ eordinal D E a /\ echeck D E onebee a ac /\
      valuation D v /\ (!n. bname D E B (v n)) /\ v i = ac
      ==> etop D E B leq (bvalf D E B leq v (linear_form i))`,
  let CLOSE = FIRST_ASSUM ACCEPT_TAC ORELSE FIRST_ASSUM MATCH_ACCEPT_TAC in
  let trich =
    `((i:num) + 1) %% (i + 2) || Eq (i + 1) (i + 2) || (i + 2) %% (i + 1)` in
  let pOr = `Eq ((i:num) + 1) (i + 2) || (i + 2) %% (i + 1)` in
  let dnb t vvt =
    MP_TAC(ISPECL[t;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;vvt]
           BVALF_SPEC) THEN
    ANTS_TAC THENL [REPEAT CONJ_TAC THEN CLOSE; ALL_TAC] THEN
    DISCH_THEN(ASSUME_TAC o CONJUNCT1) THEN
    MP_TAC(ISPECL[t;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;vvt]
           BVALF_IN_B) THEN
    ANTS_TAC THENL [REPEAT CONJ_TAC THEN CLOSE; DISCH_TAC] in
  let memf ti tj vvt =
    MP_TAC(ISPECL[ti;tj;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;vvt]
           BVALF_MEM) THEN
    ANTS_TAC THENL [REPEAT CONJ_TAC THEN CLOSE; ALL_TAC] THEN
    ASM_REWRITE_TAC[] THEN DISCH_TAC in
  let eqf ti tj vvt =
    MP_TAC(ISPECL[ti;tj;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;vvt]
           BVALF_EQ2) THEN
    ANTS_TAC THENL [REPEAT CONJ_TAC THEN CLOSE; ALL_TAC] THEN
    ASM_REWRITE_TAC[] THEN DISCH_TAC in
  let orf tp tq vvt =
    MP_TAC(ISPECL[tp;tq;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;vvt]
           BVALF_OR) THEN
    ANTS_TAC THENL [REPEAT CONJ_TAC THEN CLOSE; DISCH_TAC] in
  let joinge tx ty tz =
    MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;tx;ty;tz]
           EJOIN_GE) THEN
    ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; STRIP_TAC] in
  let tr tu tv tw =
    MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;tu;tv;tw]
           EPORDER_TRANS) THEN
    ANTS_TAC THENL [REPEAT CONJ_TAC THEN CLOSE; DISCH_TAC] in
  let exmeet tx ty nm =
    MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;tx;ty]
           EBALG_MEET) THEN
    ANTS_TAC THENL [REPEAT CONJ_TAC THEN CLOSE; ALL_TAC] THEN
    DISCH_THEN(X_CHOOSE_THEN nm ASSUME_TAC) THEN
    MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;tx;ty;nm]
           EMEET_IN) THEN
    ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; STRIP_TAC] in
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  (* check-name ac IN D *)
  SUBGOAL_THEN `(ac:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[ECHECK_IMP]; ALL_TAC] THEN
  REWRITE_TAC[linear_form] THEN
  SUBGOAL_THEN `ebalg D (E:A->A->bool) B leq` ASSUME_TAC THENL
   [ASM_MESON_TAC[ECBA_IMP_BALG]; ALL_TAC] THEN
  SUBGOAL_THEN `eporder D (E:A->A->bool) B leq` ASSUME_TAC THENL
   [ASM_MESON_TAC[ECBA_IMP_PORDER]; ALL_TAC] THEN
  MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`onebee:A`;`B:A`;`a:A`;`ac:A`]
     ECHECK_IS_BNAME) THEN ANTS_TAC THENL
  [REPEAT CONJ_TAC THEN CLOSE; DISCH_TAC] THEN
  SUBGOAL_THEN
   `~((i:num)+1=i) /\ ~((i:num)=i+1) /\ ~((i:num)+2=i) /\ ~((i:num)=i+2) /\
    ~((i:num)+2=i+1) /\ ~((i:num)+1=i+2)` STRIP_ASSUME_TAC THENL
   [REPEAT CONJ_TAC THEN ARITH_TAC; ALL_TAC] THEN
  (* ---- outer peel : !!- (i+1) i (!!- (i+2) i trich) ---- *)
  MP_TAC(ISPECL[`(i:num)+1`;`i:num`;
                `!!- ((i:num)+2) i
                   ((i + 1) %% (i + 2) || Eq (i + 1) (i + 2) ||
                    (i + 2) %% (i + 1))`;
                `D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`v:num->A`]
     BVALF_FORALLMEM_TOP) THEN
    ANTS_TAC THENL [REPEAT CONJ_TAC THEN CLOSE; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  X_GEN_TAC `a1':A` THEN STRIP_TAC THEN
  ABBREV_TAC `vv1 = (((i:num)+1) |-> (a1':A)) v` THEN
  SUBGOAL_THEN `valuation D (vv1:num->A) /\ (!n. bname D E B ((vv1:num->A) n))`
    STRIP_ASSUME_TAC THENL
   [EXPAND_TAC "vv1" THEN CONJ_TAC THENL
     [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[];
      MATCH_MP_TAC BNAMEVAL_VALMOD THEN ASM_REWRITE_TAC[]]; ALL_TAC] THEN
  SUBGOAL_THEN `(vv1:num->A) ((i:num)+1) = a1' /\ (vv1:num->A) i = ac`
    STRIP_ASSUME_TAC THENL
   [EXPAND_TAC "vv1" THEN ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER];
    ALL_TAC] THEN
  (* w1 = [[a1' IN ac]] : ebv_in, in D, in B *)
  memf `(i:num)+1` `i:num` `vv1:num->A` THEN
  dnb `((i:num)+1) %% i` `vv1:num->A` THEN
  (* ---- inner obligation : per a2' ---- *)
  SUBGOAL_THEN
   `!ss:A. ss IN D /\ bname (D:A->bool) (E:A->A->bool) B ss
         ==> erel D E leq (bvalf D E B leq (vv1:num->A) (((i:num)+1) %% i))
               (bvalf D E B leq ((((i:num)+2) |-> ss) vv1)
                  ((i+2) %% i -->
                   ((i + 1) %% (i + 2) || Eq (i + 1) (i + 2) ||
                    (i + 2) %% (i + 1))))`
   ASSUME_TAC THENL
   [X_GEN_TAC `a2':A` THEN STRIP_TAC THEN
    ABBREV_TAC `vv2 = (((i:num)+2) |-> (a2':A)) vv1` THEN
    SUBGOAL_THEN
      `valuation D (vv2:num->A) /\ (!n. bname D E B ((vv2:num->A) n))`
      STRIP_ASSUME_TAC THENL
     [EXPAND_TAC "vv2" THEN CONJ_TAC THENL
       [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[];
        MATCH_MP_TAC BNAMEVAL_VALMOD THEN ASM_REWRITE_TAC[]]; ALL_TAC] THEN
    SUBGOAL_THEN `(vv2:num->A) ((i:num)+2) = a2' /\ (vv2:num->A) (i+1) = a1' /\
                  (vv2:num->A) i = ac` STRIP_ASSUME_TAC THENL
     [EXPAND_TAC "vv2" THEN ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER];
      ALL_TAC] THEN
    (* evaluate atoms under vv2 *)
    memf `(i:num)+2` `i:num` `vv2:num->A` THEN
    memf `(i:num)+1` `(i:num)+2` `vv2:num->A` THEN
    eqf `(i:num)+1` `(i:num)+2` `vv2:num->A` THEN
    memf `(i:num)+2` `(i:num)+1` `vv2:num->A` THEN
    (* in-D / in-B for all value terms *)
    dnb `((i:num)+2) %% i` `vv2:num->A` THEN
    dnb `((i:num)+1) %% (i+2)` `vv2:num->A` THEN
    dnb `Eq ((i:num)+1) (i+2)` `vv2:num->A` THEN
    dnb `((i:num)+2) %% (i+1)` `vv2:num->A` THEN
    dnb pOr `vv2:num->A` THEN
    dnb trich `vv2:num->A` THEN
    (* ejoins : trich = p1 || (p2 || p3) *)
    orf `((i:num)+1) %% (i+2)` pOr `vv2:num->A` THEN
    orf `Eq ((i:num)+1) (i+2)` `((i:num)+2) %% (i+1)` `vv2:num->A` THEN
    (* dominance of tval over the three disjunct values *)
    joinge `bvalf D (E:A->A->bool) B leq vv2 (((i:num)+1) %% (i+2))`
           `bvalf D (E:A->A->bool) B leq vv2
            (Eq ((i:num)+1) (i+2) || (i+2) %% (i+1))`
           `bvalf D (E:A->A->bool) B leq vv2
              ((i + 1) %% (i + 2) || Eq (i + 1) (i + 2) ||
               (i + 2) %% (i + 1))` THEN
    joinge `bvalf D (E:A->A->bool) B leq vv2 (Eq ((i:num)+1) (i+2))`
           `bvalf D (E:A->A->bool) B leq vv2 (((i:num)+2) %% (i+1))`
           `bvalf D (E:A->A->bool) B leq vv2
            (Eq ((i:num)+1) (i+2) || (i+2) %% (i+1))` THEN
    tr `bvalf D (E:A->A->bool) B leq vv2 (Eq ((i:num)+1) (i+2))`
       `bvalf D (E:A->A->bool) B leq vv2
        (Eq ((i:num)+1) (i+2) || (i+2) %% (i+1))`
       `bvalf D (E:A->A->bool) B leq vv2
          ((i + 1) %% (i + 2) || Eq (i + 1) (i + 2) ||
           (i + 2) %% (i + 1))` THEN
    tr `bvalf D (E:A->A->bool) B leq vv2 (((i:num)+2) %% (i+1))`
       `bvalf D (E:A->A->bool) B leq vv2
        (Eq ((i:num)+1) (i+2) || (i+2) %% (i+1))`
       `bvalf D (E:A->A->bool) B leq vv2
          ((i + 1) %% (i + 2) || Eq (i + 1) (i + 2) ||
           (i + 2) %% (i + 1))` THEN
    (* ebimp for the body ; meet of the two in-weights *)
    MP_TAC(ISPECL[`((i:num)+2) %% i`;trich;`D:A->bool`;`E:A->A->bool`;
                  `B:A`;`leq:A`;
                  `vv2:num->A`] BVALF_IMP) THEN
      ANTS_TAC THENL [REPEAT CONJ_TAC THEN CLOSE; DISCH_TAC] THEN
    exmeet `bvalf D (E:A->A->bool) B leq vv1 (((i:num)+1) %% i)`
           `bvalf D (E:A->A->bool) B leq vv2 (((i:num)+2) %% i)` `mm:A` THEN
    (* double supremum core *)
    MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`onebee:A`;
                  `a:A`;`ac:A`;
                  `a1':A`;`a2':A`;
       `bvalf D (E:A->A->bool) B leq vv1 (((i:num)+1) %% i)`;
       `bvalf D (E:A->A->bool) B leq vv2 (((i:num)+2) %% i)`;
       `bvalf D (E:A->A->bool) B leq vv2
          ((i + 1) %% (i + 2) || Eq (i + 1) (i + 2) ||
           (i + 2) %% (i + 1))`; `mm:A`;
       `bvalf D (E:A->A->bool) B leq vv2 (((i:num)+1) %% (i+2))`;
       `bvalf D (E:A->A->bool) B leq vv2 (Eq ((i:num)+1) (i+2))`;
       `bvalf D (E:A->A->bool) B leq vv2 (((i:num)+2) %% (i+1))`]
            ELINEAR_CORE) THEN
      ANTS_TAC THENL [REPEAT CONJ_TAC THEN CLOSE; DISCH_TAC] THEN
    (* residuate : erel w1 [[ (i+2)%%i --> trich ]] *)
    MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
       `bvalf D (E:A->A->bool) B leq vv1 (((i:num)+1) %% i)`;
       `bvalf D (E:A->A->bool) B leq vv2 (((i:num)+2) %% i)`;
       `bvalf D (E:A->A->bool) B leq vv2
          ((i + 1) %% (i + 2) || Eq (i + 1) (i + 2) || (i + 2) %% (i + 1))`;
       `bvalf D (E:A->A->bool) B leq vv2
          ((i+2) %% i -->
           ((i + 1) %% (i + 2) || Eq (i + 1) (i + 2) || (i + 2) %% (i + 1)))`;
       `mm:A`] EBIMP_LE_IMP) THEN
      ANTS_TAC THENL [REPEAT CONJ_TAC THEN CLOSE; DISCH_THEN ACCEPT_TAC];
    ALL_TAC] THEN
  (* ---- inner peel : EBVALF_ALLMEM_GE closes the a2'-forall ---- *)
  MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`vv1:num->A`;
                `(i:num)+2`;
                `i:num`;trich;
                `bvalf D (E:A->A->bool) B leq vv1 (((i:num)+1) %% i)`]
     EBVALF_ALLMEM_GE) THEN
    ANTS_TAC THENL [REPEAT CONJ_TAC THEN CLOSE; DISCH_THEN ACCEPT_TAC]);;

(* ORDFORM_CHECK_TOP : [[ ordinal_form i ]]_v = top  when v i = ac is the check
   of a ground ordinal a.  ordinal_form i = transitive_form i && linear_form i,
   so split by BVALF_AND_TOP and discharge each conjunct by TRANSFORM_CHECK_TOP
   / LINFORM_CHECK_TOP.  Same signature as its two components. *)
let ORDFORM_CHECK_TOP = prove
 (`!D (E:A->A->bool) B leq onebee a ac i v.
      model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
      onebee IN D /\ E onebee B /\ etop D E B leq onebee /\
      a IN D /\ eordinal D E a /\ echeck D E onebee a ac /\
      valuation D v /\ (!n. bname D E B (v n)) /\ v i = ac
      ==> etop D E B leq (bvalf D E B leq v (ordinal_form i))`,
  let CLOSE = FIRST_ASSUM ACCEPT_TAC ORELSE FIRST_ASSUM MATCH_ACCEPT_TAC in
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  REWRITE_TAC[ordinal_form] THEN
  MP_TAC(ISPECL[`transitive_form i`;`linear_form i`;`D:A->bool`;`E:A->A->bool`;
                `B:A`;`leq:A`;`v:num->A`] BVALF_AND_TOP) THEN
    ANTS_TAC THENL [REPEAT CONJ_TAC THEN CLOSE; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  CONJ_TAC THENL
   [MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`onebee:A`;
                  `a:A`;`ac:A`;
                  `i:num`;`v:num->A`] TRANSFORM_CHECK_TOP) THEN
      ANTS_TAC THENL [REPEAT CONJ_TAC THEN CLOSE; DISCH_THEN ACCEPT_TAC];
    MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`onebee:A`;
                  `a:A`;`ac:A`;
                  `i:num`;`v:num->A`] LINFORM_CHECK_TOP) THEN
      ANTS_TAC THENL [REPEAT CONJ_TAC THEN CLOSE; DISCH_THEN ACCEPT_TAC]]);;

(* ===== A2bij-TOP ladder -- [[bijform 3^ 2^]] = top =====
   BVALF_APPLY_LE, OPIN_PROJ1/2_CHECK, BIJFORM_C1..C5_TOP,
   APPLY_FUNC_CRUX, C3_RESID, APPLY_INJ_CRUX, C4_RESID, BIJFORM_CHECK_TOP. *)

(* OPIN_PROJ1_CHECK : for the canonical opair name op = <X,Y> (bundle sa,sab)
   and the check gc = g^ of a ground function g whose every member is an opair
   <u,w> with u in gam and w in d, the Boolean value [[op in g^]] is below
   [[X in gam^]].  First projection of the apply-relation clause.
   Proof: ECHECK_IN_LE_SUP over members c of g; each c = <u,w>, build c^ 's
   Kuratowski bundle by ECHECK_KUR_AUTO, PROJ1 gives [[op=c^]] <= [[X=u^]],
   ECHECK_IN_GE_ELT gives [[X=u^]] <= [[X in gam^]]; transitivity. *)
let OPIN_PROJ1_CHECK = prove
 (`!D (E:A->A->bool) B leq onebee X Y gam d g gc gamc op sa sab z zin.
      model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
      onebee IN D /\ E onebee B /\ etop D E B leq onebee /\
      (!u:A. u IN D ==> elmem D E u) /\
      X IN D /\ Y IN D /\ bname D E B X /\ bname D E B Y /\
      echeck D E onebee g gc /\ echeck D E onebee gam gamc /\
      op IN D /\ bname D E B op /\ sa IN D /\ bname D E B sa /\
      sab IN D /\ bname D E B sab /\
      eapply D E op sa onebee /\ eapply D E op sab onebee /\
      (!t q. t IN D /\ q IN D /\ eapply D E op t q ==> t = sa \/ t = sab) /\
      eapply D E sa X onebee /\
      (!t q. t IN D /\ q IN D /\ eapply D E sa t q ==> t = X \/ t = X) /\
      eapply D E sab X onebee /\ eapply D E sab Y onebee /\
      (!t q. t IN D /\ q IN D /\ eapply D E sab t q ==> t = X \/ t = Y) /\
      (!c:A. c IN D /\ E c g ==> ?u w. u IN D /\ w IN D /\ E u gam /\ E w d /\
       eopair D E u w c) /\
      z IN D /\ ebv_in D E B leq op gc z /\
      zin IN D /\ ebv_in D E B leq X gamc zin
      ==> erel D E leq z zin`,
  let CLOSE = FIRST_ASSUM ACCEPT_TAC ORELSE FIRST_ASSUM MATCH_ACCEPT_TAC in
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  (* check-name gamc IN D *)
  SUBGOAL_THEN `(gamc:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[ECHECK_IMP]; ALL_TAC] THEN
  SUBGOAL_THEN `ebalg D (E:A->A->bool) B leq /\ eporder D E B leq`
    STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[ECBA_IMP_BALG; EBALG_IMP_PORDER]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) zin B` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`X:A`;
                        `gamc:A`;`zin:A`]
                 EBV_IN_IN_B) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* z = [[op in gc]] <= zin via sup over members of g *)
  MATCH_MP_TAC(ISPECL
    [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`onebee:A`;`g:A`;`gc:A`;
     `op:A`;`z:A`;`zin:A`] ECHECK_IN_LE_SUP) THEN
  ASM_REWRITE_TAC[] THEN
  MAP_EVERY X_GEN_TAC [`c:A`;`vc:A`;`ec:A`] THEN STRIP_TAC THEN
  SUBGOAL_THEN `(c:A) IN D /\ (vc:A) IN D` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[ECHECK_IMP]; ALL_TAC] THEN
  (* c = <u,w>, u in gam, w in d *)
  SUBGOAL_THEN
    `?u w. u IN D /\ w IN D /\ E u gam /\ E w d /\
     eopair D (E:A->A->bool) u w c`
    STRIP_ASSUME_TAC THENL
   [FIRST_X_ASSUM(fun th -> MATCH_MP_TAC th) THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  (* checks cu = u^, cw = w^ *)
  SUBGOAL_THEN `?cu. echeck D (E:A->A->bool) onebee u cu`
    (X_CHOOSE_TAC `cu:A`) THENL
   [ASM_MESON_TAC[ECHECK_EXHAUSTION]; ALL_TAC] THEN
  SUBGOAL_THEN `?cw. echeck D (E:A->A->bool) onebee w cw`
    (X_CHOOSE_TAC `cw:A`) THENL
   [ASM_MESON_TAC[ECHECK_EXHAUSTION]; ALL_TAC] THEN
  SUBGOAL_THEN `(c:A) IN D /\ (cu:A) IN D /\ (cw:A) IN D /\ (vc:A) IN D`
    STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[ECHECK_IMP]; ALL_TAC] THEN
  SUBGOAL_THEN `bname D (E:A->A->bool) B cu` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`onebee:A`;`B:A`;
                        `u:A`;`cu:A`]
                 ECHECK_IS_BNAME) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `bname D (E:A->A->bool) B cw` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`onebee:A`;`B:A`;
                        `w:A`;`cw:A`]
                 ECHECK_IS_BNAME) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `bname D (E:A->A->bool) B vc` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`onebee:A`;`B:A`;
                        `c:A`;`vc:A`]
                 ECHECK_IS_BNAME) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* ckp = vc = c^ Kuratowski bundle s,p *)
  MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`onebee:A`;`u:A`;`w:A`;
    `cu:A`;`cw:A`;`c:A`;`vc:A`] ECHECK_KUR_AUTO) THEN
  ANTS_TAC THENL [REPEAT CONJ_TAC THEN CLOSE; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `s:A` (X_CHOOSE_THEN `p:A` STRIP_ASSUME_TAC)) THEN
  (* e1 = [[X = cu]] *)
  SUBGOAL_THEN
    `?e1:A. e1 IN D /\ (E:A->A->bool) e1 B /\ ebv_eq D E B leq X cu e1`
    (X_CHOOSE_THEN `e1:A` STRIP_ASSUME_TAC) THENL
   [MATCH_MP_TAC EBV_EQ_VAL_EXISTS THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) ec B` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`op:A`;
                        `vc:A`;`ec:A`]
                 EBV_EQ_IN_B) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* PROJ1 : ec = [[op=vc]] <= e1 = [[X=cu]] *)
  MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`onebee:A`;
    `X:A`;`Y:A`;`cu:A`;`cw:A`;`op:A`;`sa:A`;`sab:A`;`s:A`;`p:A`;`vc:A`;
    `ec:A`;`e1:A`]
    EBV_EQ_KURCHECK_PROJ1) THEN
  ANTS_TAC THENL [REPEAT CONJ_TAC THEN CLOSE; ALL_TAC] THEN
  DISCH_TAC THEN
  (* CHECKEQ : e1 = [[X=cu]] <= zin = [[X in gamc]] *)
  MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`onebee:A`;
    `gam:A`;`gamc:A`;`u:A`;`cu:A`;`X:A`;`zin:A`;`e1:A`] ECHECK_IN_GE_ELT) THEN
  ANTS_TAC THENL [REPEAT CONJ_TAC THEN CLOSE; ALL_TAC] THEN
  DISCH_TAC THEN
  (* transitivity ec <= e1 <= zin *)
  MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`ec:A`;
                      `e1:A`;`zin:A`]
               EPORDER_TRANS) THEN
  ASM_REWRITE_TAC[]);;

(* OPIN_PROJ2_CHECK : companion of OPIN_PROJ1_CHECK for the SECOND coordinate.
   [[op in g^]] <= [[Y in d^]], op = <X,Y>, every member of g an opair <u,w>
   with u in gam, w in d.  Uses EBV_EQ_KURCHECK_PROJ2 ([[op=c^]] <= [[Y=w^]])
   then ECHECK_IN_GE_ELT ([[Y=w^]] <= [[Y in d^]], w in d). *)
let OPIN_PROJ2_CHECK = prove
 (`!D (E:A->A->bool) B leq onebee X Y gam d g gc dc op sa sab z zin.
      model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
      onebee IN D /\ E onebee B /\ etop D E B leq onebee /\
      (!u:A. u IN D ==> elmem D E u) /\
      X IN D /\ Y IN D /\ bname D E B X /\ bname D E B Y /\
      echeck D E onebee g gc /\ echeck D E onebee d dc /\
      op IN D /\ bname D E B op /\ sa IN D /\ bname D E B sa /\
      sab IN D /\ bname D E B sab /\
      eapply D E op sa onebee /\ eapply D E op sab onebee /\
      (!t q. t IN D /\ q IN D /\ eapply D E op t q ==> t = sa \/ t = sab) /\
      eapply D E sa X onebee /\
      (!t q. t IN D /\ q IN D /\ eapply D E sa t q ==> t = X \/ t = X) /\
      eapply D E sab X onebee /\ eapply D E sab Y onebee /\
      (!t q. t IN D /\ q IN D /\ eapply D E sab t q ==> t = X \/ t = Y) /\
      (!c:A. c IN D /\ E c g ==> ?u w. u IN D /\ w IN D /\ E u gam /\ E w d /\
       eopair D E u w c) /\
      z IN D /\ ebv_in D E B leq op gc z /\
      zin IN D /\ ebv_in D E B leq Y dc zin
      ==> erel D E leq z zin`,
  let CLOSE = FIRST_ASSUM ACCEPT_TAC ORELSE FIRST_ASSUM MATCH_ACCEPT_TAC in
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  (* check-name dc IN D *)
  SUBGOAL_THEN `(dc:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[ECHECK_IMP]; ALL_TAC] THEN
  SUBGOAL_THEN `ebalg D (E:A->A->bool) B leq /\ eporder D E B leq`
    STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[ECBA_IMP_BALG; EBALG_IMP_PORDER]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) zin B` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`Y:A`;
                        `dc:A`;`zin:A`]
                 EBV_IN_IN_B) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MATCH_MP_TAC(ISPECL
    [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`onebee:A`;`g:A`;`gc:A`;
     `op:A`;`z:A`;`zin:A`] ECHECK_IN_LE_SUP) THEN
  ASM_REWRITE_TAC[] THEN
  MAP_EVERY X_GEN_TAC [`c:A`;`vc:A`;`ec:A`] THEN STRIP_TAC THEN
  SUBGOAL_THEN `(c:A) IN D /\ (vc:A) IN D` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[ECHECK_IMP]; ALL_TAC] THEN
  SUBGOAL_THEN
    `?u w. u IN D /\ w IN D /\ E u gam /\ E w d /\
     eopair D (E:A->A->bool) u w c`
    STRIP_ASSUME_TAC THENL
   [FIRST_X_ASSUM(fun th -> MATCH_MP_TAC th) THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `?cu. echeck D (E:A->A->bool) onebee u cu`
    (X_CHOOSE_TAC `cu:A`) THENL
   [ASM_MESON_TAC[ECHECK_EXHAUSTION]; ALL_TAC] THEN
  SUBGOAL_THEN `?cw. echeck D (E:A->A->bool) onebee w cw`
    (X_CHOOSE_TAC `cw:A`) THENL
   [ASM_MESON_TAC[ECHECK_EXHAUSTION]; ALL_TAC] THEN
  SUBGOAL_THEN `(c:A) IN D /\ (cu:A) IN D /\ (cw:A) IN D /\ (vc:A) IN D`
    STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[ECHECK_IMP]; ALL_TAC] THEN
  SUBGOAL_THEN `bname D (E:A->A->bool) B cu` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`onebee:A`;`B:A`;
                        `u:A`;`cu:A`]
                 ECHECK_IS_BNAME) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `bname D (E:A->A->bool) B cw` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`onebee:A`;`B:A`;
                        `w:A`;`cw:A`]
                 ECHECK_IS_BNAME) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `bname D (E:A->A->bool) B vc` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`onebee:A`;`B:A`;
                        `c:A`;`vc:A`]
                 ECHECK_IS_BNAME) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`onebee:A`;`u:A`;`w:A`;
    `cu:A`;`cw:A`;`c:A`;`vc:A`] ECHECK_KUR_AUTO) THEN
  ANTS_TAC THENL [REPEAT CONJ_TAC THEN CLOSE; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `s:A` (X_CHOOSE_THEN `p:A` STRIP_ASSUME_TAC)) THEN
  (* e1 = [[X=cu]], e2 = [[Y=cw]] *)
  SUBGOAL_THEN
    `?e1:A. e1 IN D /\ (E:A->A->bool) e1 B /\ ebv_eq D E B leq X cu e1`
    (X_CHOOSE_THEN `e1:A` STRIP_ASSUME_TAC) THENL
   [MATCH_MP_TAC EBV_EQ_VAL_EXISTS THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN
    `?e2:A. e2 IN D /\ (E:A->A->bool) e2 B /\ ebv_eq D E B leq Y cw e2`
    (X_CHOOSE_THEN `e2:A` STRIP_ASSUME_TAC) THENL
   [MATCH_MP_TAC EBV_EQ_VAL_EXISTS THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) ec B` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`op:A`;
                        `vc:A`;`ec:A`]
                 EBV_EQ_IN_B) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* PROJ2 : ec = [[op=vc]] <= e2 = [[Y=cw]] *)
  MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`onebee:A`;
    `X:A`;`Y:A`;`cu:A`;`cw:A`;`op:A`;`sa:A`;`sab:A`;`s:A`;`p:A`;`vc:A`;
    `ec:A`;`e1:A`;
    `e2:A`;`u:A`;`w:A`] EBV_EQ_KURCHECK_PROJ2) THEN
  ANTS_TAC THENL [REPEAT CONJ_TAC THEN CLOSE; ALL_TAC] THEN
  DISCH_TAC THEN
  (* CHECKEQ : e2 = [[Y=cw]] <= zin = [[Y in dc]] *)
  MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`onebee:A`;
                `d:A`;`dc:A`;
                `w:A`;`cw:A`;`Y:A`;`zin:A`;`e2:A`] ECHECK_IN_GE_ELT) THEN
  ANTS_TAC THENL [REPEAT CONJ_TAC THEN CLOSE; ALL_TAC] THEN
  DISCH_TAC THEN
  MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`ec:A`;
                      `e2:A`;`zin:A`]
               EPORDER_TRANS) THEN
  ASM_REWRITE_TAC[]);;

(* BIJFORM_C1_TOP : relation clause of bijform 3 2 is top.
   For valuation vv with vv 2 = d^, vv 3 = gam^, vv 4 = g^ (g a function
   gam->d, clean opair graph), [[!!5 !!6 (apply 4 5 6 --> 5%%3 &&
     6%%2)]] = top.
   apply gc X Y <= <X,Y> in g^ (BVALF_APPLY_LE) <= X in gam^ (OPIN_PROJ1)
   and <= Y in d^ (OPIN_PROJ2); meet via EMEET_GREATEST. *)
let BIJFORM_C1_TOP = prove
 (`!D (E:A->A->bool) B leq onebee vv gam d g gc gamc dc.
      model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
      onebee IN D /\ E onebee B /\ etop D E B leq onebee /\
      (!u:A. u IN D ==> elmem D E u) /\
      valuation D vv /\ (!i. bname D E B (vv i)) /\
      echeck D E onebee g gc /\ echeck D E onebee gam gamc /\
      echeck D E onebee d dc /\
      vv 2 = dc /\ vv 3 = gamc /\ vv 4 = gc /\
      (!c:A. c IN D /\ E c g ==> ?u w. u IN D /\ w IN D /\ E u gam /\ E w d /\
       eopair D E u w c)
      ==> etop D E B leq
            (bvalf D E B leq vv
               (!! 5 (!! 6 (apply_form 4 5 6 --> ((5 %% 3) && (6 %% 2))))))`,
  let CLOSE = FIRST_ASSUM ACCEPT_TAC ORELSE FIRST_ASSUM MATCH_ACCEPT_TAC in
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  (* check-names gc, gamc, dc IN D *)
  SUBGOAL_THEN `(gc:A) IN D /\ (gamc:A) IN D /\ (dc:A) IN D`
    STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[ECHECK_IMP]; ALL_TAC] THEN
  SUBGOAL_THEN `ebalg D (E:A->A->bool) B leq /\ eporder D E B leq`
    STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[ECBA_IMP_BALG; EBALG_IMP_PORDER]; ALL_TAC] THEN
  SUBGOAL_THEN
    `bname D (E:A->A->bool) B gc /\ bname D E B gamc /\ bname D E B dc`
    STRIP_ASSUME_TAC THENL [ASM_MESON_TAC[]; ALL_TAC] THEN
  (* peel outer !! 5 *)
  MP_TAC(ISPECL[`5`; `!! 6 (apply_form 4 5 6 --> ((5 %% 3) && (6 %% 2)))`;
    `D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`vv:num->A`] BVALF_ALL_TOP) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  X_GEN_TAC `X:A` THEN STRIP_TAC THEN
  SUBGOAL_THEN `valuation D ((5 |-> (X:A)) vv) /\
                (!i. bname D (E:A->A->bool) B (((5 |-> X) vv) i))`
    STRIP_ASSUME_TAC THENL
   [CONJ_TAC THENL
    [MATCH_MP_TAC VALUATION_VALMOD; MATCH_MP_TAC BNAMEVAL_VALMOD] THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* peel inner !! 6 *)
  MP_TAC(ISPECL[`6`; `apply_form 4 5 6 --> ((5 %% 3) && (6 %% 2))`;
    `D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`(5 |-> (X:A)) vv`]
      BVALF_ALL_TOP) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  X_GEN_TAC `Y:A` THEN STRIP_TAC THEN
  ABBREV_TAC `vv2 = (6 |-> (Y:A)) ((5 |-> X) vv)` THEN
  SUBGOAL_THEN
    `valuation D (vv2:num->A) /\ (!i. bname D (E:A->A->bool) B (vv2 i))`
    STRIP_ASSUME_TAC THENL
   [EXPAND_TAC "vv2" THEN
    CONJ_TAC THENL
    [MATCH_MP_TAC VALUATION_VALMOD; MATCH_MP_TAC BNAMEVAL_VALMOD] THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(vv2:num->A) 2 = dc /\ vv2 3 = gamc /\ vv2 4 = gc /\
                vv2 5 = X /\ vv2 6 = Y` STRIP_ASSUME_TAC THENL
   [EXPAND_TAC "vv2" THEN ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER; ARITH_EQ];
    ALL_TAC] THEN
  (* peel --> *)
  MP_TAC(ISPECL[`apply_form 4 5 6`; `(5 %% 3) && (6 %% 2)`;
    `D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`vv2:num->A`] BVALF_IMP_TOP) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  (* build op = <X,Y> canonical opair name *)
  MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`X:A`;`Y:A`]
    EOPAIRNAME_CANON) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `op:A` (X_CHOOSE_THEN `sa:A` (X_CHOOSE_THEN `sab:A`
    (X_CHOOSE_THEN `top0:A` (X_CHOOSE_THEN `paa:A` (X_CHOOSE_THEN `pab:A`
    (X_CHOOSE_THEN `psa:A`
     (X_CHOOSE_THEN `psab:A` STRIP_ASSUME_TAC)))))))) THEN
  SUBGOAL_THEN `top0:A = onebee` SUBST_ALL_TAC THENL
   [MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
                        `top0:A`;`onebee:A`]
                 ETOP_UNIQUE) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* mvop = [[op in gc]] *)
  SUBGOAL_THEN `?mvop:A. mvop IN D /\ (E:A->A->bool) mvop B /\
                ebv_in D E B leq op gc mvop`
    (X_CHOOSE_THEN `mvop:A` STRIP_ASSUME_TAC) THENL
   [MATCH_MP_TAC EBV_IN_VAL_EXISTS THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* [[apply 4 5 6]]_vv2 <= mvop *)
  MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`vv2:num->A`;
                `4`;`5`;`6`;
                `sa:A`;`sab:A`;`op:A`;`onebee:A`;`mvop:A`] BVALF_APPLY_LE) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[] THEN REPEAT CONJ_TAC THEN ASM_MESON_TAC[]; ALL_TAC] THEN
  DISCH_TAC THEN
  (* MX = [[X in gam^]], MY = [[Y in d^]] *)
  ABBREV_TAC `MX = bvalf D (E:A->A->bool) B leq vv2 (5 %% 3)` THEN
  ABBREV_TAC `MY = bvalf D (E:A->A->bool) B leq vv2 (6 %% 2)` THEN
  SUBGOAL_THEN `ebv_in D (E:A->A->bool) B leq X gamc MX` ASSUME_TAC THENL
   [EXPAND_TAC "MX" THEN
    MP_TAC(ISPECL[`5`;`3`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
                  `vv2:num->A`]
           BVALF_MEM) THEN ASM_SIMP_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `ebv_in D (E:A->A->bool) B leq Y dc MY` ASSUME_TAC THENL
   [EXPAND_TAC "MY" THEN
    MP_TAC(ISPECL[`6`;`2`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
                  `vv2:num->A`]
           BVALF_MEM) THEN ASM_SIMP_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(MX:A) IN D /\ (E:A->A->bool) MX B /\ (MY:A) IN D /\ E MY B`
    STRIP_ASSUME_TAC THENL
   [MAP_EVERY EXPAND_TAC ["MX";"MY"] THEN
    ASM_MESON_TAC[BVALF_SPEC; BVALF_IN_B]; ALL_TAC] THEN
  (* mvop <= MX via OPIN_PROJ1, mvop <= MY via OPIN_PROJ2 *)
  SUBGOAL_THEN `erel D (E:A->A->bool) leq mvop MX` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`onebee:A`;
                        `X:A`;`Y:A`;
                        `gam:A`;`d:A`;`g:A`;`gc:A`;`gamc:A`;`op:A`;`sa:A`;
                        `sab:A`;`mvop:A`;`MX:A`]
      OPIN_PROJ1_CHECK) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq mvop MY` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`onebee:A`;
                        `X:A`;`Y:A`;
                        `gam:A`;`d:A`;`g:A`;`gc:A`;`dc:A`;`op:A`;`sa:A`;
                        `sab:A`;`mvop:A`;`MY:A`]
      OPIN_PROJ2_CHECK) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* [[apply]] IN D, E [[apply]] B *)
  ABBREV_TAC `AP = bvalf D (E:A->A->bool) B leq vv2 (apply_form 4 5 6)` THEN
  SUBGOAL_THEN `(AP:A) IN D /\ (E:A->A->bool) AP B` STRIP_ASSUME_TAC THENL
   [EXPAND_TAC "AP" THEN ASM_MESON_TAC[BVALF_SPEC; BVALF_IN_B]; ALL_TAC] THEN
  (* [[apply]] <= MX and <= MY by transitivity through mvop *)
  SUBGOAL_THEN `erel D (E:A->A->bool) leq AP MX` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`AP:A`;
                        `mvop:A`;`MX:A`]
                 EPORDER_TRANS) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq AP MY` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`AP:A`;
                        `mvop:A`;`MY:A`]
                 EPORDER_TRANS) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* RHS = emeet MX MY *)
  SUBGOAL_THEN `emeet D (E:A->A->bool) B leq MX MY
                  (bvalf D E B leq vv2 ((5 %% 3) && (6 %% 2)))`
    ASSUME_TAC THENL
   [MAP_EVERY EXPAND_TAC ["MX";"MY"] THEN
    MATCH_MP_TAC(ISPECL[`5 %% 3`;`6 %% 2`;`D:A->bool`;`E:A->A->bool`;
                        `B:A`;`leq:A`;
                        `vv2:num->A`] BVALF_AND_MEET) THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  (* conclude via EMEET_GREATEST *)
  SUBGOAL_THEN
   `erel D (E:A->A->bool) leq AP (bvalf D E B leq vv2 ((5 %% 3) && (6 %% 2)))`
    MP_TAC THENL
   [MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`MX:A`;`MY:A`;
      `bvalf D (E:A->A->bool) B leq vv2 ((5 %% 3) && (6 %% 2))`;`AP:A`]
                   EMEET_GREATEST) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  EXPAND_TAC "AP" THEN REWRITE_TAC[]);;

(* BIJFORM_C2_TOP : totality clause of bijform 3 2 is top.
   For valuation vv with vv 2 = d^, vv 3 = gam^, vv 4 = g^ (g total on gam:
   every u in gam has image w in d with <u,w> in g), the Boolean value of
   [[!!5 ((5%%3) --> ??6 ((6%%2) && apply 4 5 6))]] is top.
   For each X: reduce [[X in gam^]] by sup over members c=u of gam
     (ECHECK_IN_LE_SUP);
   witness y := w^ in the existential (BVALF_EX_UB); the body value is
   [[w^ in d^]] (= top, ECHECK_IN_TOP) meet [[apply gc X w^]], and
   [[X=u^]] <= [[<X,w^> = <u,w>^]] (EBV_EQ_KUR_CONG, with [[w^=w^]]=top)
          <= [[<X,w^> in g^]] (ECHECK_IN_GE_ELT)
          <= [[apply gc X w^]]  (BVALF_APPLY_GE). *)
let BIJFORM_C2_TOP = prove
 (`!D (E:A->A->bool) B leq onebee vv gam d g gc gamc dc.
      model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
      onebee IN D /\ E onebee B /\ etop D E B leq onebee /\
      (!u:A. u IN D ==> elmem D E u) /\
      valuation D vv /\ (!i. bname D E B (vv i)) /\
      echeck D E onebee g gc /\ echeck D E onebee gam gamc /\
      echeck D E onebee d dc /\
      vv 2 = dc /\ vv 3 = gamc /\ vv 4 = gc /\
      (!u:A. u IN D /\ E u gam ==> ?w c. w IN D /\ c IN D /\ E w d /\ E c g /\
       eopair D E u w c)
      ==> etop D E B leq
            (bvalf D E B leq vv
               (!! 5 ((5 %% 3) --> ?? 6 ((6 %% 2) && apply_form 4 5 6))))`,
  let CLOSE = FIRST_ASSUM ACCEPT_TAC ORELSE FIRST_ASSUM MATCH_ACCEPT_TAC in
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  (* source sets + check-names IN D *)
  SUBGOAL_THEN `(g:A) IN D /\ (gam:A) IN D /\ (d:A) IN D /\
                (gc:A) IN D /\ (gamc:A) IN D /\ (dc:A) IN D`
    STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[ECHECK_IMP]; ALL_TAC] THEN
  SUBGOAL_THEN `ebalg D (E:A->A->bool) B leq /\ eporder D E B leq`
    STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[ECBA_IMP_BALG; EBALG_IMP_PORDER]; ALL_TAC] THEN
  SUBGOAL_THEN
    `bname D (E:A->A->bool) B gc /\ bname D E B gamc /\ bname D E B dc`
    STRIP_ASSUME_TAC THENL [ASM_MESON_TAC[]; ALL_TAC] THEN
  (* peel outer !! 5 *)
  MP_TAC(ISPECL[`5`; `(5 %% 3) --> ?? 6 ((6 %% 2) && apply_form 4 5 6)`;
    `D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`vv:num->A`] BVALF_ALL_TOP) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  X_GEN_TAC `X:A` THEN STRIP_TAC THEN
  ABBREV_TAC `vv1 = (5 |-> (X:A)) vv` THEN
  SUBGOAL_THEN
    `valuation D (vv1:num->A) /\ (!i. bname D (E:A->A->bool) B (vv1 i))`
    STRIP_ASSUME_TAC THENL
   [EXPAND_TAC "vv1" THEN
    CONJ_TAC THENL
    [MATCH_MP_TAC VALUATION_VALMOD; MATCH_MP_TAC BNAMEVAL_VALMOD] THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(vv1:num->A) 2 = dc /\ vv1 3 = gamc /\ vv1 4 = gc /\ vv1 5 = X`
    STRIP_ASSUME_TAC THENL
   [EXPAND_TAC "vv1" THEN ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER; ARITH_EQ];
    ALL_TAC] THEN
  (* peel --> *)
  MP_TAC(ISPECL[`5 %% 3`; `?? 6 ((6 %% 2) && apply_form 4 5 6)`;
    `D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`vv1:num->A`] BVALF_IMP_TOP) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  (* MX = [[X in gamc]], RHS = [[?? 6 ...]] *)
  ABBREV_TAC `MX = bvalf D (E:A->A->bool) B leq vv1 (5 %% 3)` THEN
  ABBREV_TAC
    `RHS = bvalf D (E:A->A->bool) B leq vv1
     (?? 6 ((6 %% 2) && apply_form 4 5 6))` THEN
  SUBGOAL_THEN `ebv_in D (E:A->A->bool) B leq X gamc MX` ASSUME_TAC THENL
   [EXPAND_TAC "MX" THEN
    MP_TAC(ISPECL[`5`;`3`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
                  `vv1:num->A`]
           BVALF_MEM) THEN ASM_SIMP_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(MX:A) IN D /\ (RHS:A) IN D /\ (E:A->A->bool) RHS B`
    STRIP_ASSUME_TAC THENL
   [MAP_EVERY EXPAND_TAC ["MX";"RHS"] THEN
    ASM_MESON_TAC[BVALF_SPEC; BVALF_IN_B]; ALL_TAC] THEN
  (* reduce MX by sup over members c of gam *)
  MATCH_MP_TAC(ISPECL
    [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`onebee:A`;`gam:A`;`gamc:A`;
     `X:A`;`MX:A`;`RHS:A`] ECHECK_IN_LE_SUP) THEN
  ASM_REWRITE_TAC[] THEN
  MAP_EVERY X_GEN_TAC [`c:A`;`vc:A`;`ec:A`] THEN STRIP_TAC THEN
  SUBGOAL_THEN `(c:A) IN D /\ (vc:A) IN D` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[ECHECK_IMP]; ALL_TAC] THEN
  (* totality : c in gam ==> w, cc with E w d, E cc g, eopair c w cc *)
  SUBGOAL_THEN
    `?w cc. w IN D /\ cc IN D /\ E w d /\ E cc g /\
     eopair D (E:A->A->bool) c w cc`
    STRIP_ASSUME_TAC THENL [ASM_MESON_TAC[]; ALL_TAC] THEN
  (* checks cw = w^, ccc = cc^ *)
  SUBGOAL_THEN `?cw. echeck D (E:A->A->bool) onebee w cw`
    (X_CHOOSE_TAC `cw:A`) THENL
   [ASM_MESON_TAC[ECHECK_EXHAUSTION]; ALL_TAC] THEN
  SUBGOAL_THEN `?ccc. echeck D (E:A->A->bool) onebee cc ccc`
    (X_CHOOSE_TAC `ccc:A`) THENL
   [ASM_MESON_TAC[ECHECK_EXHAUSTION]; ALL_TAC] THEN
  SUBGOAL_THEN `(c:A) IN D /\ (cw:A) IN D /\ (ccc:A) IN D /\ (vc:A) IN D`
    STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[ECHECK_IMP]; ALL_TAC] THEN
  SUBGOAL_THEN `bname D (E:A->A->bool) B cw` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`onebee:A`;`B:A`;
                        `w:A`;`cw:A`]
                 ECHECK_IS_BNAME) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `bname D (E:A->A->bool) B ccc` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`onebee:A`;`B:A`;
                        `cc:A`;`ccc:A`]
                 ECHECK_IS_BNAME) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `bname D (E:A->A->bool) B vc` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`onebee:A`;`B:A`;
                        `c:A`;`vc:A`]
                 ECHECK_IS_BNAME) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* build op = <X,cw> canonical opair name *)
  MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`X:A`;`cw:A`]
    EOPAIRNAME_CANON) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `op:A` (X_CHOOSE_THEN `sa:A` (X_CHOOSE_THEN `sab:A`
    (X_CHOOSE_THEN `top0:A` (X_CHOOSE_THEN `paa:A` (X_CHOOSE_THEN `pab:A`
    (X_CHOOSE_THEN `psa:A`
     (X_CHOOSE_THEN `psab:A` STRIP_ASSUME_TAC)))))))) THEN
  SUBGOAL_THEN `top0:A = onebee` SUBST_ALL_TAC THENL
   [MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
                        `top0:A`;`onebee:A`]
                 ETOP_UNIQUE) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* mvop = [[op in gc]] *)
  SUBGOAL_THEN `?mvop:A. mvop IN D /\ (E:A->A->bool) mvop B /\
                ebv_in D E B leq op gc mvop`
    (X_CHOOSE_THEN `mvop:A` STRIP_ASSUME_TAC) THENL
   [MATCH_MP_TAC EBV_IN_VAL_EXISTS THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* ccc 's Kuratowski bundle s,p *)
  MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`onebee:A`;`c:A`;`w:A`;
    `vc:A`;`cw:A`;`cc:A`;`ccc:A`] ECHECK_KUR_AUTO) THEN
  ANTS_TAC THENL [REPEAT CONJ_TAC THEN CLOSE; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `s:A` (X_CHOOSE_THEN `p:A` STRIP_ASSUME_TAC)) THEN
  (* ekp = [[op = ccc]] *)
  SUBGOAL_THEN
    `?ekp:A. ekp IN D /\ (E:A->A->bool) ekp B /\ ebv_eq D E B leq op ccc ekp`
    (X_CHOOSE_THEN `ekp:A` STRIP_ASSUME_TAC) THENL
   [MATCH_MP_TAC EBV_EQ_VAL_EXISTS THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* rz = [[cw = cw]] = top *)
  SUBGOAL_THEN
    `?rz:A. rz IN D /\ (E:A->A->bool) rz B /\ ebv_eq D E B leq cw cw rz`
    (X_CHOOSE_THEN `rz:A` STRIP_ASSUME_TAC) THENL
   [MATCH_MP_TAC EBV_EQ_VAL_EXISTS THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `etop D (E:A->A->bool) B leq rz` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`cw:A`;`rz:A`]
      EBV_EQ_REFL) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) ec B` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`X:A`;
                        `vc:A`;`ec:A`]
                 EBV_EQ_IN_B) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* emeet ec rz ec  (rz top) *)
  SUBGOAL_THEN `emeet D (E:A->A->bool) B leq ec rz ec` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`rz:A`;`ec:A`]
      EMEET_TOP) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* ec = [[X=vc]] <= ekp = [[op=ccc]]  via KUR_CONG *)
  SUBGOAL_THEN `erel D (E:A->A->bool) leq ec ekp` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
      `X:A`;`cw:A`;`vc:A`;`cw:A`;`sa:A`;`sab:A`;`op:A`;`s:A`;`p:A`;
      `ccc:A`;`onebee:A`;
      `ec:A`;`rz:A`;`ec:A`;`ekp:A`] EBV_EQ_KUR_CONG) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* ekp = [[op=ccc]] <= mvop = [[op in gc]]  via GE_ELT (cc in g) *)
  SUBGOAL_THEN `erel D (E:A->A->bool) leq ekp mvop` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`onebee:A`;
      `g:A`;`gc:A`;`cc:A`;`ccc:A`;`op:A`;`mvop:A`;`ekp:A`]
        ECHECK_IN_GE_ELT) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* vw = (6|->cw) vv1 *)
  ABBREV_TAC `vw = (6 |-> (cw:A)) vv1` THEN
  SUBGOAL_THEN
    `valuation D (vw:num->A) /\ (!i. bname D (E:A->A->bool) B (vw i))`
    STRIP_ASSUME_TAC THENL
   [EXPAND_TAC "vw" THEN
    CONJ_TAC THENL
    [MATCH_MP_TAC VALUATION_VALMOD; MATCH_MP_TAC BNAMEVAL_VALMOD] THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN
    `(vw:num->A) 2 = dc /\ vw 3 = gamc /\ vw 4 = gc /\ vw 5 = X /\ vw 6 = cw`
    STRIP_ASSUME_TAC THENL
   [EXPAND_TAC "vw" THEN ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER; ARITH_EQ];
    ALL_TAC] THEN
  (* AP = [[apply gc X cw]], mvop <= AP via APPLY_GE *)
  ABBREV_TAC `AP = bvalf D (E:A->A->bool) B leq vw (apply_form 4 5 6)` THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq mvop AP` ASSUME_TAC THENL
   [EXPAND_TAC "AP" THEN
    MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`vw:num->A`;
                        `4`;`5`;`6`;
                        `sa:A`;`sab:A`;`op:A`;`onebee:A`;`mvop:A`]
          BVALF_APPLY_GE) THEN
    ASM_REWRITE_TAC[] THEN REPEAT CONJ_TAC THEN ASM_MESON_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(AP:A) IN D /\ (E:A->A->bool) AP B` STRIP_ASSUME_TAC THENL
   [EXPAND_TAC "AP" THEN ASM_MESON_TAC[BVALF_SPEC; BVALF_IN_B]; ALL_TAC] THEN
  (* DT = [[cw in dc]] = top *)
  ABBREV_TAC `DT = bvalf D (E:A->A->bool) B leq vw (6 %% 2)` THEN
  SUBGOAL_THEN `ebv_in D (E:A->A->bool) B leq cw dc DT` ASSUME_TAC THENL
   [EXPAND_TAC "DT" THEN
    MP_TAC(ISPECL[`6`;`2`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`vw:num->A`]
      BVALF_MEM) THEN ASM_SIMP_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(DT:A) IN D` ASSUME_TAC THENL
   [EXPAND_TAC "DT" THEN ASM_MESON_TAC[BVALF_SPEC; BVALF_IN_B]; ALL_TAC] THEN
  SUBGOAL_THEN `etop D (E:A->A->bool) B leq DT` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`onebee:A`;
      `w:A`;`d:A`;`cw:A`;`dc:A`;`DT:A`] ECHECK_IN_TOP) THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  (* BODY = emeet DT AP *)
  SUBGOAL_THEN `emeet D (E:A->A->bool) B leq DT AP
                  (bvalf D E B leq vw ((6 %% 2) && apply_form 4 5 6))`
    ASSUME_TAC THENL
   [MAP_EVERY EXPAND_TAC ["DT";"AP"] THEN
    MATCH_MP_TAC(ISPECL[`6 %% 2`;`apply_form 4 5 6`;`D:A->bool`;`E:A->A->bool`;
                        `B:A`;`leq:A`;
                        `vw:num->A`] BVALF_AND_MEET) THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
    `(bvalf D (E:A->A->bool) B leq vw ((6 %% 2) && apply_form 4 5 6)) IN D /\
     (E:A->A->bool) (bvalf D E B leq vw ((6 %% 2) && apply_form 4 5 6)) B`
    STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[BVALF_SPEC; BVALF_IN_B]; ALL_TAC] THEN
  (* BODY <= RHS via EX_UB (witness cw) *)
  SUBGOAL_THEN `erel D (E:A->A->bool) leq
                  (bvalf D E B leq vw ((6 %% 2) && apply_form 4 5 6)) RHS`
    ASSUME_TAC THENL
   [EXPAND_TAC "RHS" THEN EXPAND_TAC "vw" THEN
    MATCH_MP_TAC(ISPECL[`6`;`(6 %% 2) && apply_form 4 5 6`;
      `D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`vv1:num->A`;`cw:A`]
        BVALF_EX_UB) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* ec <= DT (DT top), ec <= AP (chain), ec <= BODY (meet greatest), ec <= *)
  (* RHS *)
  SUBGOAL_THEN `erel D (E:A->A->bool) leq ec DT` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`DT:A`;`ec:A`]
                 ETOP_GE) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq ec mvop` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`ec:A`;
                        `ekp:A`;`mvop:A`]
                 EPORDER_TRANS) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq ec AP` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`ec:A`;
                        `mvop:A`;`AP:A`]
                 EPORDER_TRANS) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq ec
                  (bvalf D E B leq vw ((6 %% 2) && apply_form 4 5 6))`
    ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`DT:A`;`AP:A`;
      `bvalf D (E:A->A->bool) B leq vw ((6 %% 2) && apply_form 4 5 6)`;`ec:A`]
      EMEET_GREATEST) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`ec:A`;
    `bvalf D (E:A->A->bool) B leq vw ((6 %% 2) && apply_form 4 5 6)`;`RHS:A`]
    EPORDER_TRANS) THEN ASM_REWRITE_TAC[]);;

(* BIJFORM_C5_TOP : onto clause of bijform 3 2 is top.
   g surjective onto d: every w in d has preimage u in gam with <u,w> in g.
   [[!!6 ((6%%2) --> ??5 ((5%%3) && apply 4 5 6))]] = top.
   Mirror of C2 with the sup over members of d (second coordinate); the
   top-factor [[u^=u^]] is the LEFT meet-argument in KUR_CONG so EMEET_SYM. *)
let BIJFORM_C5_TOP = prove
 (`!D (E:A->A->bool) B leq onebee vv gam d g gc gamc dc.
      model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
      onebee IN D /\ E onebee B /\ etop D E B leq onebee /\
      (!u:A. u IN D ==> elmem D E u) /\
      valuation D vv /\ (!i. bname D E B (vv i)) /\
      echeck D E onebee g gc /\ echeck D E onebee gam gamc /\
      echeck D E onebee d dc /\
      vv 2 = dc /\ vv 3 = gamc /\ vv 4 = gc /\
      (!w:A. w IN D /\ E w d ==> ?u c. u IN D /\ c IN D /\ E u gam /\ E c g /\
       eopair D E u w c)
      ==> etop D E B leq
            (bvalf D E B leq vv
               (!! 6 ((6 %% 2) --> ?? 5 ((5 %% 3) && apply_form 4 5 6))))`,
  let CLOSE = FIRST_ASSUM ACCEPT_TAC ORELSE FIRST_ASSUM MATCH_ACCEPT_TAC in
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `(g:A) IN D /\ (gam:A) IN D /\ (d:A) IN D /\
                (gc:A) IN D /\ (gamc:A) IN D /\ (dc:A) IN D`
    STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[ECHECK_IMP]; ALL_TAC] THEN
  SUBGOAL_THEN `ebalg D (E:A->A->bool) B leq /\ eporder D E B leq`
    STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[ECBA_IMP_BALG; EBALG_IMP_PORDER]; ALL_TAC] THEN
  SUBGOAL_THEN
    `bname D (E:A->A->bool) B gc /\ bname D E B gamc /\ bname D E B dc`
    STRIP_ASSUME_TAC THENL [ASM_MESON_TAC[]; ALL_TAC] THEN
  (* peel outer !! 6 *)
  MP_TAC(ISPECL[`6`; `(6 %% 2) --> ?? 5 ((5 %% 3) && apply_form 4 5 6)`;
    `D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`vv:num->A`] BVALF_ALL_TOP) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  X_GEN_TAC `Y:A` THEN STRIP_TAC THEN
  ABBREV_TAC `vv1 = (6 |-> (Y:A)) vv` THEN
  SUBGOAL_THEN
    `valuation D (vv1:num->A) /\ (!i. bname D (E:A->A->bool) B (vv1 i))`
    STRIP_ASSUME_TAC THENL
   [EXPAND_TAC "vv1" THEN
    CONJ_TAC THENL
    [MATCH_MP_TAC VALUATION_VALMOD; MATCH_MP_TAC BNAMEVAL_VALMOD] THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(vv1:num->A) 2 = dc /\ vv1 3 = gamc /\ vv1 4 = gc /\ vv1 6 = Y`
    STRIP_ASSUME_TAC THENL
   [EXPAND_TAC "vv1" THEN ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER; ARITH_EQ];
    ALL_TAC] THEN
  (* peel --> *)
  MP_TAC(ISPECL[`6 %% 2`; `?? 5 ((5 %% 3) && apply_form 4 5 6)`;
    `D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`vv1:num->A`] BVALF_IMP_TOP) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  (* MY = [[Y in dc]], RHS = [[?? 5 ...]] *)
  ABBREV_TAC `MY = bvalf D (E:A->A->bool) B leq vv1 (6 %% 2)` THEN
  ABBREV_TAC
    `RHS = bvalf D (E:A->A->bool) B leq vv1
     (?? 5 ((5 %% 3) && apply_form 4 5 6))` THEN
  SUBGOAL_THEN `ebv_in D (E:A->A->bool) B leq Y dc MY` ASSUME_TAC THENL
   [EXPAND_TAC "MY" THEN
    MP_TAC(ISPECL[`6`;`2`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
                  `vv1:num->A`]
           BVALF_MEM) THEN ASM_SIMP_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(MY:A) IN D /\ (RHS:A) IN D /\ (E:A->A->bool) RHS B`
    STRIP_ASSUME_TAC THENL
   [MAP_EVERY EXPAND_TAC ["MY";"RHS"] THEN
    ASM_MESON_TAC[BVALF_SPEC; BVALF_IN_B]; ALL_TAC] THEN
  (* reduce MY by sup over members c of d *)
  MATCH_MP_TAC(ISPECL
    [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`onebee:A`;`d:A`;`dc:A`;
     `Y:A`;`MY:A`;`RHS:A`] ECHECK_IN_LE_SUP) THEN
  ASM_REWRITE_TAC[] THEN
  MAP_EVERY X_GEN_TAC [`c:A`;`vc:A`;`ec:A`] THEN STRIP_TAC THEN
  SUBGOAL_THEN `(c:A) IN D /\ (vc:A) IN D` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[ECHECK_IMP]; ALL_TAC] THEN
  (* surjectivity : c in d ==> u, cc with E u gam, E cc g, eopair u c cc *)
  SUBGOAL_THEN
    `?u cc. u IN D /\ cc IN D /\ E u gam /\ E cc g /\
     eopair D (E:A->A->bool) u c cc`
    STRIP_ASSUME_TAC THENL [ASM_MESON_TAC[]; ALL_TAC] THEN
  (* checks cu = u^, ccc = cc^ *)
  SUBGOAL_THEN `?cu. echeck D (E:A->A->bool) onebee u cu`
    (X_CHOOSE_TAC `cu:A`) THENL
   [ASM_MESON_TAC[ECHECK_EXHAUSTION]; ALL_TAC] THEN
  SUBGOAL_THEN `?ccc. echeck D (E:A->A->bool) onebee cc ccc`
    (X_CHOOSE_TAC `ccc:A`) THENL
   [ASM_MESON_TAC[ECHECK_EXHAUSTION]; ALL_TAC] THEN
  SUBGOAL_THEN `(c:A) IN D /\ (cu:A) IN D /\ (ccc:A) IN D /\ (vc:A) IN D`
    STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[ECHECK_IMP]; ALL_TAC] THEN
  SUBGOAL_THEN `bname D (E:A->A->bool) B cu` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`onebee:A`;`B:A`;
                        `u:A`;`cu:A`]
                 ECHECK_IS_BNAME) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `bname D (E:A->A->bool) B ccc` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`onebee:A`;`B:A`;
                        `cc:A`;`ccc:A`]
                 ECHECK_IS_BNAME) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `bname D (E:A->A->bool) B vc` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`onebee:A`;`B:A`;
                        `c:A`;`vc:A`]
                 ECHECK_IS_BNAME) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* build op = <cu,Y> canonical opair name *)
  MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`cu:A`;`Y:A`]
    EOPAIRNAME_CANON) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `op:A` (X_CHOOSE_THEN `sa:A` (X_CHOOSE_THEN `sab:A`
    (X_CHOOSE_THEN `top0:A` (X_CHOOSE_THEN `paa:A` (X_CHOOSE_THEN `pab:A`
    (X_CHOOSE_THEN `psa:A`
     (X_CHOOSE_THEN `psab:A` STRIP_ASSUME_TAC)))))))) THEN
  SUBGOAL_THEN `top0:A = onebee` SUBST_ALL_TAC THENL
   [MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
                        `top0:A`;`onebee:A`]
                 ETOP_UNIQUE) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* mvop = [[op in gc]] *)
  SUBGOAL_THEN `?mvop:A. mvop IN D /\ (E:A->A->bool) mvop B /\
                ebv_in D E B leq op gc mvop`
    (X_CHOOSE_THEN `mvop:A` STRIP_ASSUME_TAC) THENL
   [MATCH_MP_TAC EBV_IN_VAL_EXISTS THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* ccc 's Kuratowski bundle s,p  (ccc = <u,c>^ = Kur(cu,vc)) *)
  MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`onebee:A`;`u:A`;`c:A`;
    `cu:A`;`vc:A`;`cc:A`;`ccc:A`] ECHECK_KUR_AUTO) THEN
  ANTS_TAC THENL [REPEAT CONJ_TAC THEN CLOSE; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `s:A` (X_CHOOSE_THEN `p:A` STRIP_ASSUME_TAC)) THEN
  (* ekp = [[op = ccc]] *)
  SUBGOAL_THEN
    `?ekp:A. ekp IN D /\ (E:A->A->bool) ekp B /\ ebv_eq D E B leq op ccc ekp`
    (X_CHOOSE_THEN `ekp:A` STRIP_ASSUME_TAC) THENL
   [MATCH_MP_TAC EBV_EQ_VAL_EXISTS THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* rz = [[cu = cu]] = top *)
  SUBGOAL_THEN
    `?rz:A. rz IN D /\ (E:A->A->bool) rz B /\ ebv_eq D E B leq cu cu rz`
    (X_CHOOSE_THEN `rz:A` STRIP_ASSUME_TAC) THENL
   [MATCH_MP_TAC EBV_EQ_VAL_EXISTS THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `etop D (E:A->A->bool) B leq rz` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`cu:A`;`rz:A`]
      EBV_EQ_REFL) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) ec B` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`Y:A`;
                        `vc:A`;`ec:A`]
                 EBV_EQ_IN_B) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* emeet rz ec ec  (rz top, LEFT factor -> EMEET_SYM) *)
  SUBGOAL_THEN `emeet D (E:A->A->bool) B leq ec rz ec` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`rz:A`;`ec:A`]
      EMEET_TOP) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `emeet D (E:A->A->bool) B leq rz ec ec` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`ec:A`;
                        `rz:A`;`ec:A`]
                 EMEET_SYM) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* ec = [[Y=vc]] <= ekp = [[op=ccc]]  via KUR_CONG *)
  SUBGOAL_THEN `erel D (E:A->A->bool) leq ec ekp` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
      `cu:A`;`Y:A`;`cu:A`;`vc:A`;`sa:A`;`sab:A`;`op:A`;`s:A`;`p:A`;
      `ccc:A`;`onebee:A`;
      `rz:A`;`ec:A`;`ec:A`;`ekp:A`] EBV_EQ_KUR_CONG) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* ekp <= mvop  via GE_ELT (cc in g) *)
  SUBGOAL_THEN `erel D (E:A->A->bool) leq ekp mvop` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`onebee:A`;
      `g:A`;`gc:A`;`cc:A`;`ccc:A`;`op:A`;`mvop:A`;`ekp:A`]
                   ECHECK_IN_GE_ELT) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* vw = (5|->cu) vv1 *)
  ABBREV_TAC `vw = (5 |-> (cu:A)) vv1` THEN
  SUBGOAL_THEN
    `valuation D (vw:num->A) /\ (!i. bname D (E:A->A->bool) B (vw i))`
    STRIP_ASSUME_TAC THENL
   [EXPAND_TAC "vw" THEN
    CONJ_TAC THENL
    [MATCH_MP_TAC VALUATION_VALMOD; MATCH_MP_TAC BNAMEVAL_VALMOD] THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN
    `(vw:num->A) 2 = dc /\ vw 3 = gamc /\ vw 4 = gc /\ vw 5 = cu /\ vw 6 = Y`
    STRIP_ASSUME_TAC THENL
   [EXPAND_TAC "vw" THEN ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER; ARITH_EQ];
    ALL_TAC] THEN
  (* AP = [[apply gc cu Y]], mvop <= AP via APPLY_GE *)
  ABBREV_TAC `AP = bvalf D (E:A->A->bool) B leq vw (apply_form 4 5 6)` THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq mvop AP` ASSUME_TAC THENL
   [EXPAND_TAC "AP" THEN
    MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`vw:num->A`;
                        `4`;`5`;`6`;
                        `sa:A`;`sab:A`;`op:A`;`onebee:A`;`mvop:A`]
                     BVALF_APPLY_GE) THEN
    ASM_REWRITE_TAC[] THEN REPEAT CONJ_TAC THEN ASM_MESON_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(AP:A) IN D /\ (E:A->A->bool) AP B` STRIP_ASSUME_TAC THENL
   [EXPAND_TAC "AP" THEN ASM_MESON_TAC[BVALF_SPEC; BVALF_IN_B]; ALL_TAC] THEN
  (* DT = [[cu in gam^]] = top *)
  ABBREV_TAC `DT = bvalf D (E:A->A->bool) B leq vw (5 %% 3)` THEN
  SUBGOAL_THEN `ebv_in D (E:A->A->bool) B leq cu gamc DT` ASSUME_TAC THENL
   [EXPAND_TAC "DT" THEN
    MP_TAC(ISPECL[`5`;`3`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`vw:num->A`]
      BVALF_MEM) THEN ASM_SIMP_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(DT:A) IN D` ASSUME_TAC THENL
   [EXPAND_TAC "DT" THEN ASM_MESON_TAC[BVALF_SPEC; BVALF_IN_B]; ALL_TAC] THEN
  SUBGOAL_THEN `etop D (E:A->A->bool) B leq DT` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`onebee:A`;
      `u:A`;`gam:A`;`cu:A`;`gamc:A`;`DT:A`] ECHECK_IN_TOP) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* BODY = emeet DT AP *)
  SUBGOAL_THEN `emeet D (E:A->A->bool) B leq DT AP
                  (bvalf D E B leq vw ((5 %% 3) && apply_form 4 5 6))`
    ASSUME_TAC THENL
   [MAP_EVERY EXPAND_TAC ["DT";"AP"] THEN
    MATCH_MP_TAC(ISPECL[`5 %% 3`;`apply_form 4 5 6`;`D:A->bool`;`E:A->A->bool`;
                        `B:A`;`leq:A`;
                        `vw:num->A`] BVALF_AND_MEET) THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
    `(bvalf D (E:A->A->bool) B leq vw ((5 %% 3) && apply_form 4 5 6)) IN D /\
     (E:A->A->bool) (bvalf D E B leq vw ((5 %% 3) && apply_form 4 5 6)) B`
    STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[BVALF_SPEC; BVALF_IN_B]; ALL_TAC] THEN
  (* BODY <= RHS via EX_UB (witness cu) *)
  SUBGOAL_THEN `erel D (E:A->A->bool) leq
                  (bvalf D E B leq vw ((5 %% 3) && apply_form 4 5 6)) RHS`
    ASSUME_TAC THENL
   [EXPAND_TAC "RHS" THEN EXPAND_TAC "vw" THEN
    MATCH_MP_TAC(ISPECL[`5`;`(5 %% 3) && apply_form 4 5 6`;
      `D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`vv1:num->A`;`cu:A`]
        BVALF_EX_UB) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* ec <= DT, ec <= AP (chain), ec <= BODY, ec <= RHS *)
  SUBGOAL_THEN `erel D (E:A->A->bool) leq ec DT` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`DT:A`;`ec:A`]
                 ETOP_GE) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq ec mvop` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`ec:A`;
                        `ekp:A`;`mvop:A`]
                 EPORDER_TRANS) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq ec AP` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`ec:A`;
                        `mvop:A`;`AP:A`]
                 EPORDER_TRANS) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq ec
                  (bvalf D E B leq vw ((5 %% 3) && apply_form 4 5 6))`
    ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`DT:A`;`AP:A`;
      `bvalf D (E:A->A->bool) B leq vw ((5 %% 3) && apply_form 4 5 6)`;`ec:A`]
      EMEET_GREATEST) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`ec:A`;
    `bvalf D (E:A->A->bool) B leq vw ((5 %% 3) && apply_form 4 5 6)`;`RHS:A`]
    EPORDER_TRANS) THEN ASM_REWRITE_TAC[]);;

(* APPLY_FUNC_CRUX : the per-(c,c') heart of the functional clause C3.
   c = <u,w>, c' = <u',w'> both in g; g single-valued (u=u' ==> w=w').
   op1 = <X,Y>, op2 = <X,Z>.  ec = [[op1 = c^]], ec' = [[op2 = c'^]].
   Claim: emeet ec' ec <= [[Y=Z]].
   PROJ1/PROJ2 give ec <= [[X=cu]],[[Y=cw]] and ec' <= [[X=cu']],[[Z=cw']].
   Case u=u': g s.v. => w=w' => cw=cw' (ECHECK_SV); EBV_EQ_CONG on
     [[Y=cw]],[[cw=Z]] gives meet <= [[Y=Z]].
   Case u<>u': ECHECK_EQ_BOT makes [[cu=cu']]=bot; EBV_EQ_CONG on
     [[cu=X]],[[X=cu']] gives meet <= bot, so m = bot <= [[Y=Z]] (EBOT_LE). *)
let APPLY_FUNC_CRUX = prove
 (`!D (E:A->A->bool) B leq onebee X Y Z u w u' w' cu cw cu' cw' c c' vc vc'
      op1 sa1 sab1 op2 sa2 sab2 ec ec' eq m.
    model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
    onebee IN D /\ E onebee B /\ etop D E B leq onebee /\
    (!uu:A. uu IN D ==> elmem D E uu) /\
    X IN D /\ Y IN D /\ Z IN D /\
    bname D E B X /\ bname D E B Y /\ bname D E B Z /\
    echeck D E onebee u cu /\ echeck D E onebee w cw /\
    echeck D E onebee u' cu' /\ echeck D E onebee w' cw' /\
    echeck D E onebee c vc /\ echeck D E onebee c' vc' /\
    eopair D E u w c /\ eopair D E u' w' c' /\
    (u = u' ==> w = w') /\
    op1 IN D /\ bname D E B op1 /\ sa1 IN D /\ bname D E B sa1 /\
    sab1 IN D /\ bname D E B sab1 /\
    eapply D E op1 sa1 onebee /\ eapply D E op1 sab1 onebee /\
    (!t q. t IN D /\ q IN D /\ eapply D E op1 t q ==> t = sa1 \/ t = sab1) /\
    eapply D E sa1 X onebee /\
    (!t q. t IN D /\ q IN D /\ eapply D E sa1 t q ==> t = X \/ t = X) /\
    eapply D E sab1 X onebee /\ eapply D E sab1 Y onebee /\
    (!t q. t IN D /\ q IN D /\ eapply D E sab1 t q ==> t = X \/ t = Y) /\
    op2 IN D /\ bname D E B op2 /\ sa2 IN D /\ bname D E B sa2 /\
    sab2 IN D /\ bname D E B sab2 /\
    eapply D E op2 sa2 onebee /\ eapply D E op2 sab2 onebee /\
    (!t q. t IN D /\ q IN D /\ eapply D E op2 t q ==> t = sa2 \/ t = sab2) /\
    eapply D E sa2 X onebee /\
    (!t q. t IN D /\ q IN D /\ eapply D E sa2 t q ==> t = X \/ t = X) /\
    eapply D E sab2 X onebee /\ eapply D E sab2 Z onebee /\
    (!t q. t IN D /\ q IN D /\ eapply D E sab2 t q ==> t = X \/ t = Z) /\
    ec IN D /\ E ec B /\ ebv_eq D E B leq op1 vc ec /\
    ec' IN D /\ E ec' B /\ ebv_eq D E B leq op2 vc' ec' /\
    eq IN D /\ E eq B /\ ebv_eq D E B leq Y Z eq /\
    m IN D /\ emeet D E B leq ec' ec m
    ==> erel D E leq m eq`,
  let CLOSE = FIRST_ASSUM ACCEPT_TAC ORELSE FIRST_ASSUM MATCH_ACCEPT_TAC in
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `(u:A) IN D /\ (w:A) IN D /\ (u':A) IN D /\ (w':A) IN D /\
                (c:A) IN D /\ (c':A) IN D /\
                (cu:A) IN D /\ (cw:A) IN D /\ (cu':A) IN D /\ (cw':A) IN D /\
                (vc:A) IN D /\ (vc':A) IN D` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[ECHECK_IMP]; ALL_TAC] THEN
  SUBGOAL_THEN `ebalg D (E:A->A->bool) B leq /\ eporder D E B leq`
    STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[ECBA_IMP_BALG; EBALG_IMP_PORDER]; ALL_TAC] THEN
  (* bnames of the member checks *)
  SUBGOAL_THEN `bname D (E:A->A->bool) B cu` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`onebee:A`;`B:A`;
                        `u:A`;`cu:A`]
                 ECHECK_IS_BNAME) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `bname D (E:A->A->bool) B cw` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`onebee:A`;`B:A`;
                        `w:A`;`cw:A`]
                 ECHECK_IS_BNAME) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `bname D (E:A->A->bool) B cu'` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`onebee:A`;`B:A`;
                        `u':A`;`cu':A`]
                 ECHECK_IS_BNAME) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `bname D (E:A->A->bool) B cw'` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`onebee:A`;`B:A`;
                        `w':A`;`cw':A`]
                 ECHECK_IS_BNAME) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `bname D (E:A->A->bool) B vc` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`onebee:A`;`B:A`;
                        `c:A`;`vc:A`]
                 ECHECK_IS_BNAME) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `bname D (E:A->A->bool) B vc'` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`onebee:A`;`B:A`;
                        `c':A`;`vc':A`]
                 ECHECK_IS_BNAME) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* Kuratowski bundles s1,p1 of vc=<u,w>^ and s2,p2 of vc'=<u',w'>^ *)
  MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`onebee:A`;`u:A`;`w:A`;
    `cu:A`;`cw:A`;`c:A`;`vc:A`] ECHECK_KUR_AUTO) THEN
  ANTS_TAC THENL [REPEAT CONJ_TAC THEN CLOSE; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `s1:A` (X_CHOOSE_THEN `p1:A` STRIP_ASSUME_TAC)) THEN
  MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`onebee:A`;`u':A`;`w':A`;
    `cu':A`;`cw':A`;`c':A`;`vc':A`] ECHECK_KUR_AUTO) THEN
  ANTS_TAC THENL [REPEAT CONJ_TAC THEN CLOSE; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `s2:A` (X_CHOOSE_THEN `p2:A` STRIP_ASSUME_TAC)) THEN
  (* equality values eXu=[[X=cu]], eYw=[[Y=cw]], eXu'=[[X=cu']], *)
  (* eZw'=[[Z=cw']] *)
  SUBGOAL_THEN
    `?eXu:A. eXu IN D /\ (E:A->A->bool) eXu B /\ ebv_eq D E B leq X cu eXu`
    (X_CHOOSE_THEN `eXu:A` STRIP_ASSUME_TAC) THENL
   [MATCH_MP_TAC EBV_EQ_VAL_EXISTS THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN
    `?eYw:A. eYw IN D /\ (E:A->A->bool) eYw B /\ ebv_eq D E B leq Y cw eYw`
    (X_CHOOSE_THEN `eYw:A` STRIP_ASSUME_TAC) THENL
   [MATCH_MP_TAC EBV_EQ_VAL_EXISTS THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN
    `?eXu':A. eXu' IN D /\ (E:A->A->bool) eXu' B /\
     ebv_eq D E B leq X cu' eXu'`
    (X_CHOOSE_THEN `eXu':A` STRIP_ASSUME_TAC) THENL
   [MATCH_MP_TAC EBV_EQ_VAL_EXISTS THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN
    `?eZw':A. eZw' IN D /\ (E:A->A->bool) eZw' B /\
     ebv_eq D E B leq Z cw' eZw'`
    (X_CHOOSE_THEN `eZw':A` STRIP_ASSUME_TAC) THENL
   [MATCH_MP_TAC EBV_EQ_VAL_EXISTS THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* projections: ec <= eXu, ec <= eYw (op1,vc) ; ec' <= eXu', ec' <= eZw' *)
  (* (op2,vc') *)
  SUBGOAL_THEN `erel D (E:A->A->bool) leq ec eXu` ASSUME_TAC THENL
   [MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`onebee:A`;
      `X:A`;`Y:A`;`cu:A`;`cw:A`;`op1:A`;`sa1:A`;`sab1:A`;`s1:A`;`p1:A`;`vc:A`;
      `ec:A`;`eXu:A`]
      EBV_EQ_KURCHECK_PROJ1) THEN
    ANTS_TAC THENL [REPEAT CONJ_TAC THEN CLOSE; ALL_TAC] THEN
    DISCH_THEN ACCEPT_TAC; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq ec eYw` ASSUME_TAC THENL
   [MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`onebee:A`;
      `X:A`;`Y:A`;`cu:A`;`cw:A`;`op1:A`;`sa1:A`;`sab1:A`;`s1:A`;`p1:A`;`vc:A`;
      `ec:A`;`eXu:A`;
      `eYw:A`;`u:A`;`w:A`] EBV_EQ_KURCHECK_PROJ2) THEN
    ANTS_TAC THENL [REPEAT CONJ_TAC THEN CLOSE; ALL_TAC] THEN
    DISCH_THEN ACCEPT_TAC; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq ec' eXu'` ASSUME_TAC THENL
   [MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`onebee:A`;
      `X:A`;`Z:A`;`cu':A`;`cw':A`;`op2:A`;`sa2:A`;`sab2:A`;`s2:A`;`p2:A`;
      `vc':A`;`ec':A`;`eXu':A`]
      EBV_EQ_KURCHECK_PROJ1) THEN
    ANTS_TAC THENL [REPEAT CONJ_TAC THEN CLOSE; ALL_TAC] THEN
    DISCH_THEN ACCEPT_TAC; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq ec' eZw'` ASSUME_TAC THENL
   [MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`onebee:A`;
      `X:A`;`Z:A`;`cu':A`;`cw':A`;`op2:A`;`sa2:A`;`sab2:A`;`s2:A`;`p2:A`;
      `vc':A`;`ec':A`;`eXu':A`;
      `eZw':A`;`u':A`;`w':A`] EBV_EQ_KURCHECK_PROJ2) THEN
    ANTS_TAC THENL [REPEAT CONJ_TAC THEN CLOSE; ALL_TAC] THEN
    DISCH_THEN ACCEPT_TAC; ALL_TAC] THEN
  (* m <= ec', m <= ec *)
  SUBGOAL_THEN `(E:A->A->bool) m B /\ erel D E leq m ec' /\ erel D E leq m ec`
    STRIP_ASSUME_TAC THENL
   [UNDISCH_TAC `emeet D (E:A->A->bool) B leq ec' ec m` THEN
    REWRITE_TAC[emeet] THEN MESON_TAC[]; ALL_TAC] THEN
  (* ---- case split on u = u' ---- *)
  ASM_CASES_TAC `u:A = u'` THENL
   [(* u = u' : single-valued gives w = w', hence cw' = cw *)
    SUBGOAL_THEN `w:A = w'` ASSUME_TAC THENL [ASM_MESON_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN `cw':A = cw` SUBST_ALL_TAC THENL
     [MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`onebee:A`;`w:A`;
                          `cw':A`;`cw:A`]
                   ECHECK_SV) THEN ASM_MESON_TAC[]; ALL_TAC] THEN
    (* [[cw=Z]] from eZw' by symmetry *)
    SUBGOAL_THEN `ebv_eq D (E:A->A->bool) B leq cw Z eZw'` ASSUME_TAC THENL
     [MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`Z:A`;
                          `cw:A`;`eZw':A`]
                   EBV_EQ_SYM) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN `?z23:A. emeet D (E:A->A->bool) B leq eYw eZw' z23`
      (X_CHOOSE_TAC `z23:A`) THENL
     [MATCH_MP_TAC EBALG_MEET THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN `(z23:A) IN D /\ (E:A->A->bool) z23 B` STRIP_ASSUME_TAC THENL
     [ASM_MESON_TAC[EMEET_IN]; ALL_TAC] THEN
    SUBGOAL_THEN `erel D (E:A->A->bool) leq z23 eq` ASSUME_TAC THENL
     [MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`Y:A`;
                          `cw:A`;`Z:A`;
                          `eYw:A`;`eZw':A`;`eq:A`;`z23:A`] EBV_EQ_CONG) THEN
      ASM_REWRITE_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN `erel D (E:A->A->bool) leq m eYw` ASSUME_TAC THENL
     [MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`m:A`;
                          `ec:A`;`eYw:A`]
                   EPORDER_TRANS) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN `erel D (E:A->A->bool) leq m eZw'` ASSUME_TAC THENL
     [MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`m:A`;
                          `ec':A`;`eZw':A`]
                   EPORDER_TRANS) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN `erel D (E:A->A->bool) leq m z23` ASSUME_TAC THENL
     [MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
                          `eYw:A`;`eZw':A`;
                          `z23:A`;`m:A`] EMEET_GREATEST) THEN
      ASM_REWRITE_TAC[]; ALL_TAC] THEN
    MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`m:A`;
                        `z23:A`;`eq:A`]
                 EPORDER_TRANS) THEN ASM_REWRITE_TAC[];
    (* u <> u' : [[cu=cu']] = bot *)
    SUBGOAL_THEN `ebv_eq D (E:A->A->bool) B leq cu X eXu` ASSUME_TAC THENL
     [MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`X:A`;
                          `cu:A`;`eXu:A`]
                   EBV_EQ_SYM) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN
      `?zcc:A. zcc IN D /\ (E:A->A->bool) zcc B /\ ebv_eq D E B leq cu cu' zcc`
      (X_CHOOSE_THEN `zcc:A` STRIP_ASSUME_TAC) THENL
     [MATCH_MP_TAC EBV_EQ_VAL_EXISTS THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN `ebot D (E:A->A->bool) B leq zcc` ASSUME_TAC THENL
     [MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`onebee:A`;
                          `u:A`;`u':A`;
                          `cu:A`;`cu':A`;`zcc:A`] ECHECK_EQ_BOT) THEN
                 ASM_REWRITE_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN `?z23:A. emeet D (E:A->A->bool) B leq eXu eXu' z23`
      (X_CHOOSE_TAC `z23:A`) THENL
     [MATCH_MP_TAC EBALG_MEET THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN `(z23:A) IN D /\ (E:A->A->bool) z23 B` STRIP_ASSUME_TAC THENL
     [ASM_MESON_TAC[EMEET_IN]; ALL_TAC] THEN
    SUBGOAL_THEN `erel D (E:A->A->bool) leq z23 zcc` ASSUME_TAC THENL
     [MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`cu:A`;
                          `X:A`;`cu':A`;
                          `eXu:A`;`eXu':A`;`zcc:A`;`z23:A`] EBV_EQ_CONG) THEN
                 ASM_REWRITE_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN `erel D (E:A->A->bool) leq m eXu` ASSUME_TAC THENL
     [MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`m:A`;
                          `ec:A`;`eXu:A`]
                   EPORDER_TRANS) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN `erel D (E:A->A->bool) leq m eXu'` ASSUME_TAC THENL
     [MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`m:A`;
                          `ec':A`;`eXu':A`]
                   EPORDER_TRANS) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN `erel D (E:A->A->bool) leq m z23` ASSUME_TAC THENL
     [MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
                          `eXu:A`;`eXu':A`;
                          `z23:A`;`m:A`] EMEET_GREATEST) THEN
                 ASM_REWRITE_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN `erel D (E:A->A->bool) leq m zcc` ASSUME_TAC THENL
     [MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`m:A`;
                          `z23:A`;`zcc:A`]
                   EPORDER_TRANS) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN `m:A = zcc` SUBST_ALL_TAC THENL
     [MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`m:A`;
                          `zcc:A`] ELE_BOT) THEN
      ASM_REWRITE_TAC[]; ALL_TAC] THEN
    MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`zcc:A`;
                        `eq:A`] EBOT_LE) THEN
    ASM_REWRITE_TAC[]]);;

(* C3_RESID : the double-residuation core of the functional clause.
   mvY = [[<X,Y> in g^]], mvZ = [[<X,Z> in g^]], MM = emeet mvY mvZ,
   eq = [[Y=Z]].  Claim MM <= eq.
   Outer: MM <= eq  <==  mvY <= (mvZ ==> eq)         (EBIMP_MEET_LE)
          mvY <= (mvZ ==> eq)  by sup over c in g: per c, ec <= (mvZ==>eq)
            ec <= (mvZ==>eq)  <==  emeet ec mvZ <= eq (EBIMP_LE_IMP)
   Inner: emeet ec mvZ <= eq  <==  mvZ <= (ec ==> eq)  (EBIMP_MEET_LE, sym)
          mvZ <= (ec ==> eq)  by sup over c' in g: per c', ec' <= (ec==>eq)
            ec' <= (ec==>eq)  <==  emeet ec' ec <= eq (EBIMP_LE_IMP)
   and emeet ec' ec <= eq is APPLY_FUNC_CRUX. *)
let C3_RESID = prove
 (`!D (E:A->A->bool) B leq onebee X Y Z gam d g gc
      op1 sa1 sab1 op2 sa2 sab2 mvY mvZ eq MM.
    model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
    onebee IN D /\ E onebee B /\ etop D E B leq onebee /\
    (!uu:A. uu IN D ==> elmem D E uu) /\
    X IN D /\ Y IN D /\ Z IN D /\
    bname D E B X /\ bname D E B Y /\ bname D E B Z /\
    echeck D E onebee g gc /\
    (!c:A. c IN D /\ E c g ==> ?u w. u IN D /\ w IN D /\ E u gam /\ E w d /\
     eopair D E u w c) /\
    (!(u:A) (w:A) (u':A) (w':A) c c'. u IN D /\ w IN D /\ u' IN D /\ w' IN D /\
         E c g /\ E c' g /\
         eopair D E u w c /\ eopair D E u' w' c' /\ u = u' ==> w = w') /\
    op1 IN D /\ bname D E B op1 /\ sa1 IN D /\ bname D E B sa1 /\
    sab1 IN D /\ bname D E B sab1 /\
    eapply D E op1 sa1 onebee /\ eapply D E op1 sab1 onebee /\
    (!t q. t IN D /\ q IN D /\ eapply D E op1 t q ==> t = sa1 \/ t = sab1) /\
    eapply D E sa1 X onebee /\
    (!t q. t IN D /\ q IN D /\ eapply D E sa1 t q ==> t = X \/ t = X) /\
    eapply D E sab1 X onebee /\ eapply D E sab1 Y onebee /\
    (!t q. t IN D /\ q IN D /\ eapply D E sab1 t q ==> t = X \/ t = Y) /\
    op2 IN D /\ bname D E B op2 /\ sa2 IN D /\ bname D E B sa2 /\
    sab2 IN D /\ bname D E B sab2 /\
    eapply D E op2 sa2 onebee /\ eapply D E op2 sab2 onebee /\
    (!t q. t IN D /\ q IN D /\ eapply D E op2 t q ==> t = sa2 \/ t = sab2) /\
    eapply D E sa2 X onebee /\
    (!t q. t IN D /\ q IN D /\ eapply D E sa2 t q ==> t = X \/ t = X) /\
    eapply D E sab2 X onebee /\ eapply D E sab2 Z onebee /\
    (!t q. t IN D /\ q IN D /\ eapply D E sab2 t q ==> t = X \/ t = Z) /\
    mvY IN D /\ E mvY B /\ ebv_in D E B leq op1 gc mvY /\
    mvZ IN D /\ E mvZ B /\ ebv_in D E B leq op2 gc mvZ /\
    eq IN D /\ E eq B /\ ebv_eq D E B leq Y Z eq /\
    MM IN D /\ emeet D E B leq mvY mvZ MM
    ==> erel D E leq MM eq`,
  let CLOSE = FIRST_ASSUM ACCEPT_TAC ORELSE FIRST_ASSUM MATCH_ACCEPT_TAC in
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `ebalg D (E:A->A->bool) B leq /\ eporder D E B leq`
    STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[ECBA_IMP_BALG; EBALG_IMP_PORDER]; ALL_TAC] THEN
  (* IY = ebimp mvZ eq *)
  SUBGOAL_THEN `?IY:A. ebimp D E B leq mvZ eq IY` (X_CHOOSE_TAC `IY:A`) THENL
   [MATCH_MP_TAC EBIMP_EXISTS THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(IY:A) IN D /\ (E:A->A->bool) IY B` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[EBIMP_IN]; ALL_TAC] THEN
  (* ---- OUTER sup : erel mvY IY ---- *)
  SUBGOAL_THEN `erel D (E:A->A->bool) leq mvY IY` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`onebee:A`;
                        `g:A`;`gc:A`;
                        `op1:A`;`mvY:A`;`IY:A`] ECHECK_IN_LE_SUP) THEN
    ASM_REWRITE_TAC[] THEN
    MAP_EVERY X_GEN_TAC [`c:A`;`vc:A`;`ec:A`] THEN STRIP_TAC THEN
    SUBGOAL_THEN `(c:A) IN D /\ (vc:A) IN D` STRIP_ASSUME_TAC THENL
     [MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`onebee:A`;`c:A`;`vc:A`]
        ECHECK_IMP) THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    SUBGOAL_THEN
      `?u w. u IN D /\ w IN D /\ E u gam /\ E w d /\
       eopair D (E:A->A->bool) u w c`
      STRIP_ASSUME_TAC THENL
      [FIRST_ASSUM MATCH_MP_TAC THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
      SUBGOAL_THEN `?cu. echeck D (E:A->A->bool) onebee u cu`
        (X_CHOOSE_TAC `cu:A`) THENL
        [ASM_MESON_TAC[ECHECK_EXHAUSTION]; ALL_TAC] THEN
    SUBGOAL_THEN `?cw. echeck D (E:A->A->bool) onebee w cw`
      (X_CHOOSE_TAC `cw:A`) THENL
      [ASM_MESON_TAC[ECHECK_EXHAUSTION]; ALL_TAC] THEN
    SUBGOAL_THEN `(E:A->A->bool) ec B` ASSUME_TAC THENL
     [MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`op1:A`;
                          `vc:A`;`ec:A`]
                   EBV_EQ_IN_B) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN `?m1:A. emeet D (E:A->A->bool) B leq ec mvZ m1`
      (X_CHOOSE_TAC `m1:A`) THENL
      [MATCH_MP_TAC EBALG_MEET THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN `(m1:A) IN D /\ (E:A->A->bool) m1 B` STRIP_ASSUME_TAC THENL
     [ASM_MESON_TAC[EMEET_IN]; ALL_TAC] THEN
    SUBGOAL_THEN `?IZ:A. ebimp D E B leq ec eq IZ` (X_CHOOSE_TAC `IZ:A`) THENL
     [MATCH_MP_TAC EBIMP_EXISTS THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN `(IZ:A) IN D /\ (E:A->A->bool) IZ B` STRIP_ASSUME_TAC THENL
     [ASM_MESON_TAC[EBIMP_IN]; ALL_TAC] THEN
    SUBGOAL_THEN `emeet D (E:A->A->bool) B leq mvZ ec m1` ASSUME_TAC THENL
     [MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`ec:A`;
                          `mvZ:A`;`m1:A`]
                   EMEET_SYM) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    (* ---- INNER sup : erel mvZ IZ ---- *)
    SUBGOAL_THEN `erel D (E:A->A->bool) leq mvZ IZ` ASSUME_TAC THENL
     [MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`onebee:A`;
                          `g:A`;`gc:A`;
                          `op2:A`;`mvZ:A`;`IZ:A`] ECHECK_IN_LE_SUP) THEN
      ASM_REWRITE_TAC[] THEN
      MAP_EVERY X_GEN_TAC [`c':A`;`vc':A`;`ec':A`] THEN STRIP_TAC THEN
      SUBGOAL_THEN `(c':A) IN D /\ (vc':A) IN D` STRIP_ASSUME_TAC THENL
       [MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`onebee:A`;
                            `c':A`;`vc':A`]
                     ECHECK_IMP) THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
      SUBGOAL_THEN
        `?u' w'. u' IN D /\ w' IN D /\ E u' gam /\ E w' d /\
         eopair D (E:A->A->bool) u' w' c'`
        STRIP_ASSUME_TAC THENL
        [FIRST_ASSUM MATCH_MP_TAC THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
        SUBGOAL_THEN `?cu'. echeck D (E:A->A->bool) onebee u' cu'`
          (X_CHOOSE_TAC `cu':A`) THENL
          [ASM_MESON_TAC[ECHECK_EXHAUSTION]; ALL_TAC] THEN
      SUBGOAL_THEN `?cw'. echeck D (E:A->A->bool) onebee w' cw'`
        (X_CHOOSE_TAC `cw':A`) THENL
        [ASM_MESON_TAC[ECHECK_EXHAUSTION]; ALL_TAC] THEN
      SUBGOAL_THEN `(E:A->A->bool) ec' B` ASSUME_TAC THENL
       [MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`op2:A`;
                            `vc':A`;`ec':A`]
                     EBV_EQ_IN_B) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
      SUBGOAL_THEN `?m2:A. emeet D (E:A->A->bool) B leq ec' ec m2`
        (X_CHOOSE_TAC `m2:A`) THENL
        [MATCH_MP_TAC EBALG_MEET THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
      SUBGOAL_THEN `(m2:A) IN D /\ (E:A->A->bool) m2 B` STRIP_ASSUME_TAC THENL
       [ASM_MESON_TAC[EMEET_IN]; ALL_TAC] THEN
      SUBGOAL_THEN `(u:A) = u' ==> (w:A) = w'` ASSUME_TAC THENL
       [DISCH_TAC THEN
        FIRST_ASSUM(MATCH_MP_TAC o
          SPECL[`u:A`;`w:A`;`u':A`;`w':A`;`c:A`;`c':A`]) THEN
        REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
      SUBGOAL_THEN `erel D (E:A->A->bool) leq m2 eq` ASSUME_TAC THENL
       [MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`onebee:A`;
                      `X:A`;`Y:A`;`Z:A`;
                      `u:A`;`w:A`;`u':A`;`w':A`;`cu:A`;`cw:A`;`cu':A`;`cw':A`;
                      `c:A`;`c':A`;`vc:A`;`vc':A`;
                      `op1:A`;`sa1:A`;`sab1:A`;`op2:A`;`sa2:A`;`sab2:A`;`ec:A`;
                      `ec':A`;`eq:A`;`m2:A`]
          APPLY_FUNC_CRUX) THEN
        ANTS_TAC THENL [REPEAT CONJ_TAC THEN CLOSE; ALL_TAC] THEN
        DISCH_THEN ACCEPT_TAC; ALL_TAC] THEN
      MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`ec':A`;`ec:A`;
                    `eq:A`;`IZ:A`;`m2:A`]
             EBIMP_LE_IMP) THEN
      ANTS_TAC THENL [REPEAT CONJ_TAC THEN CLOSE; ALL_TAC] THEN
      DISCH_THEN ACCEPT_TAC; ALL_TAC] THEN
    (* emeet ec mvZ = m1 <= eq *)
    SUBGOAL_THEN `erel D (E:A->A->bool) leq m1 eq` ASSUME_TAC THENL
     [MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`mvZ:A`;`ec:A`;
                    `eq:A`;`IZ:A`;`m1:A`]
             EBIMP_MEET_LE) THEN
      ANTS_TAC THENL [REPEAT CONJ_TAC THEN CLOSE; ALL_TAC] THEN
      DISCH_THEN ACCEPT_TAC; ALL_TAC] THEN
    MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`ec:A`;`mvZ:A`;
                  `eq:A`;`IY:A`;`m1:A`]
           EBIMP_LE_IMP) THEN
    ANTS_TAC THENL [REPEAT CONJ_TAC THEN CLOSE; ALL_TAC] THEN
    DISCH_THEN ACCEPT_TAC; ALL_TAC] THEN
  (* conclude : erel MM eq *)
  MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`mvY:A`;`mvZ:A`;
                `eq:A`;`IY:A`;`MM:A`]
         EBIMP_MEET_LE) THEN
  ANTS_TAC THENL [REPEAT CONJ_TAC THEN CLOSE; ALL_TAC] THEN
  DISCH_THEN ACCEPT_TAC);;

(* BIJFORM_C3_TOP : functional clause of bijform 3 2 is top.
   [[!!5 !!6 !!7 ((apply 4 5 6 && apply 4 5 7) --> Eq 6 7)]] = top.
   For X,Y,Z : LHS = [[apply gc X Y]] meet [[apply gc X Z]] = emeet AY AZ = M.
   AY <= [[<X,Y> in gc]] = mvY, AZ <= [[<X,Z> in gc]] = mvZ (BVALF_APPLY_LE);
   so M <= mvY, M <= mvZ, hence M <= emeet mvY mvZ = MM (EMEET_GREATEST).
   MM <= [[Y=Z]] = EQ by C3_RESID (double residuation + APPLY_FUNC_CRUX).
   M <= EQ by transitivity. *)
let BIJFORM_C3_TOP = prove
 (`!D (E:A->A->bool) B leq onebee vv gam d g gc gamc dc.
      model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
      onebee IN D /\ E onebee B /\ etop D E B leq onebee /\
      (!u:A. u IN D ==> elmem D E u) /\
      valuation D vv /\ (!i. bname D E B (vv i)) /\
      echeck D E onebee g gc /\ echeck D E onebee gam gamc /\
      echeck D E onebee d dc /\
      vv 2 = dc /\ vv 3 = gamc /\ vv 4 = gc /\
      (!c:A. c IN D /\ E c g ==> ?u w. u IN D /\ w IN D /\ E u gam /\ E w d /\
       eopair D E u w c) /\
      (!(u:A) (w:A) (u':A) (w':A) c c'. u IN D /\ w IN D /\
       u' IN D /\ w' IN D /\
       E c g /\ E c' g /\
           eopair D E u w c /\ eopair D E u' w' c' /\ u = u' ==> w = w')
      ==> etop D E B leq
            (bvalf D E B leq vv
               (!! 5 (!! 6 (!! 7 ((apply_form 4 5 6 && apply_form 4 5 7)
                                   --> Eq 6 7)))))`,
  let CLOSE = FIRST_ASSUM ACCEPT_TAC ORELSE FIRST_ASSUM MATCH_ACCEPT_TAC in
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `ebalg D (E:A->A->bool) B leq /\ eporder D E B leq`
    STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[ECBA_IMP_BALG; EBALG_IMP_PORDER]; ALL_TAC] THEN
  SUBGOAL_THEN
    `bname D (E:A->A->bool) B gc /\ bname D E B gamc /\ bname D E B dc`
    STRIP_ASSUME_TAC THENL [ASM_MESON_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(gc:A) IN D /\ (gamc:A) IN D /\ (dc:A) IN D`
    STRIP_ASSUME_TAC THENL [ASM_MESON_TAC[ECHECK_IMP]; ALL_TAC] THEN
  (* peel !! 5 *)
  MP_TAC(ISPECL[`5`;
                `!! 6 (!! 7
                       ((apply_form 4 5 6 && apply_form 4 5 7) --> Eq 6 7))`;
                `D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`vv:num->A`]
              BVALF_ALL_TOP) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  X_GEN_TAC `X:A` THEN STRIP_TAC THEN
  ABBREV_TAC `vv1 = (5 |-> (X:A)) vv` THEN
  SUBGOAL_THEN
    `valuation D (vv1:num->A) /\ (!i. bname D (E:A->A->bool) B (vv1 i))`
    STRIP_ASSUME_TAC THENL
   [EXPAND_TAC "vv1" THEN
    CONJ_TAC THENL
    [MATCH_MP_TAC VALUATION_VALMOD; MATCH_MP_TAC BNAMEVAL_VALMOD] THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(vv1:num->A) 2 = dc /\ vv1 3 = gamc /\ vv1 4 = gc /\ vv1 5 = X`
    STRIP_ASSUME_TAC THENL
   [EXPAND_TAC "vv1" THEN ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER; ARITH_EQ];
    ALL_TAC] THEN
  (* peel !! 6 *)
  MP_TAC(ISPECL[`6`;
                `!! 7 ((apply_form 4 5 6 && apply_form 4 5 7) --> Eq 6 7)`;
                `D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`vv1:num->A`]
      BVALF_ALL_TOP) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  X_GEN_TAC `Y:A` THEN STRIP_TAC THEN
  ABBREV_TAC `vv2 = (6 |-> (Y:A)) vv1` THEN
  SUBGOAL_THEN
    `valuation D (vv2:num->A) /\ (!i. bname D (E:A->A->bool) B (vv2 i))`
    STRIP_ASSUME_TAC THENL
   [EXPAND_TAC "vv2" THEN
    CONJ_TAC THENL
    [MATCH_MP_TAC VALUATION_VALMOD; MATCH_MP_TAC BNAMEVAL_VALMOD] THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN
    `(vv2:num->A) 2 = dc /\ vv2 3 = gamc /\ vv2 4 = gc /\
     vv2 5 = X /\ vv2 6 = Y`
    STRIP_ASSUME_TAC THENL
   [EXPAND_TAC "vv2" THEN ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER; ARITH_EQ];
    ALL_TAC] THEN
  (* peel !! 7 *)
  MP_TAC(ISPECL[`7`; `(apply_form 4 5 6 && apply_form 4 5 7) --> Eq 6 7`;
    `D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`vv2:num->A`] BVALF_ALL_TOP) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  X_GEN_TAC `Z:A` THEN STRIP_TAC THEN
  ABBREV_TAC `vv3 = (7 |-> (Z:A)) vv2` THEN
  SUBGOAL_THEN
    `valuation D (vv3:num->A) /\ (!i. bname D (E:A->A->bool) B (vv3 i))`
    STRIP_ASSUME_TAC THENL
   [EXPAND_TAC "vv3" THEN
    CONJ_TAC THENL
    [MATCH_MP_TAC VALUATION_VALMOD; MATCH_MP_TAC BNAMEVAL_VALMOD] THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(vv3:num->A) 2 = dc /\ vv3 3 = gamc /\ vv3 4 = gc /\
                vv3 5 = X /\ vv3 6 = Y /\ vv3 7 = Z`
    STRIP_ASSUME_TAC THENL
   [EXPAND_TAC "vv3" THEN ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER; ARITH_EQ];
    ALL_TAC] THEN
  (* peel --> *)
  MP_TAC(ISPECL[`apply_form 4 5 6 && apply_form 4 5 7`; `Eq 6 7`;
    `D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`vv3:num->A`] BVALF_IMP_TOP) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  (* build op1 = <X,Y> *)
  MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`X:A`;`Y:A`]
    EOPAIRNAME_CANON) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `op1:A`
             (X_CHOOSE_THEN `sa1:A` (X_CHOOSE_THEN `sab1:A`
                                     (X_CHOOSE_THEN `top0a:A`
                                      (X_CHOOSE_THEN `paa1:A`
                                       (X_CHOOSE_THEN `pab1:A`
                                        (X_CHOOSE_THEN `psa1:A`
                                         (X_CHOOSE_THEN `psab1:A`
                                          STRIP_ASSUME_TAC)))))))) THEN
  SUBGOAL_THEN `top0a:A = onebee` SUBST_ALL_TAC THENL
   [MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
                        `top0a:A`;`onebee:A`]
                 ETOP_UNIQUE) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* build op2 = <X,Z> *)
  MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`X:A`;`Z:A`]
    EOPAIRNAME_CANON) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `op2:A`
             (X_CHOOSE_THEN `sa2:A` (X_CHOOSE_THEN `sab2:A`
                                     (X_CHOOSE_THEN `top0b:A`
                                      (X_CHOOSE_THEN `paa2:A`
                                       (X_CHOOSE_THEN `pab2:A`
                                        (X_CHOOSE_THEN `psa2:A`
                                         (X_CHOOSE_THEN `psab2:A`
                                          STRIP_ASSUME_TAC)))))))) THEN
  SUBGOAL_THEN `top0b:A = onebee` SUBST_ALL_TAC THENL
   [MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
                        `top0b:A`;`onebee:A`]
                 ETOP_UNIQUE) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* mvY = [[op1 in gc]], mvZ = [[op2 in gc]] *)
  SUBGOAL_THEN
    `?mvY:A. mvY IN D /\ (E:A->A->bool) mvY B /\ ebv_in D E B leq op1 gc mvY`
    (X_CHOOSE_THEN `mvY:A` STRIP_ASSUME_TAC) THENL
   [MATCH_MP_TAC EBV_IN_VAL_EXISTS THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN
    `?mvZ:A. mvZ IN D /\ (E:A->A->bool) mvZ B /\ ebv_in D E B leq op2 gc mvZ`
    (X_CHOOSE_THEN `mvZ:A` STRIP_ASSUME_TAC) THENL
   [MATCH_MP_TAC EBV_IN_VAL_EXISTS THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* AY, AZ, M (LHS), EQ (RHS) *)
  ABBREV_TAC `AY = bvalf D (E:A->A->bool) B leq vv3 (apply_form 4 5 6)` THEN
  ABBREV_TAC `AZ = bvalf D (E:A->A->bool) B leq vv3 (apply_form 4 5 7)` THEN
  ABBREV_TAC
    `M = bvalf D (E:A->A->bool) B leq vv3
     (apply_form 4 5 6 && apply_form 4 5 7)` THEN
  ABBREV_TAC `EQ = bvalf D (E:A->A->bool) B leq vv3 (Eq 6 7)` THEN
  SUBGOAL_THEN `(AY:A) IN D /\ (E:A->A->bool) AY B` STRIP_ASSUME_TAC THENL
   [EXPAND_TAC "AY" THEN ASM_MESON_TAC[BVALF_SPEC; BVALF_IN_B]; ALL_TAC] THEN
  SUBGOAL_THEN `(AZ:A) IN D /\ (E:A->A->bool) AZ B` STRIP_ASSUME_TAC THENL
   [EXPAND_TAC "AZ" THEN ASM_MESON_TAC[BVALF_SPEC; BVALF_IN_B]; ALL_TAC] THEN
  (* AY <= mvY *)
  SUBGOAL_THEN `erel D (E:A->A->bool) leq AY mvY` ASSUME_TAC THENL
   [EXPAND_TAC "AY" THEN
    MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`vv3:num->A`;
                  `4`;`5`;`6`;
                  `sa1:A`;`sab1:A`;`op1:A`;`onebee:A`;`mvY:A`]
                   BVALF_APPLY_LE) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[] THEN REPEAT CONJ_TAC THEN ASM_MESON_TAC[];
      ALL_TAC] THEN
    DISCH_THEN ACCEPT_TAC; ALL_TAC] THEN
  (* AZ <= mvZ *)
  SUBGOAL_THEN `erel D (E:A->A->bool) leq AZ mvZ` ASSUME_TAC THENL
   [EXPAND_TAC "AZ" THEN
    MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`vv3:num->A`;
                  `4`;`5`;`7`;
                  `sa2:A`;`sab2:A`;`op2:A`;`onebee:A`;`mvZ:A`]
        BVALF_APPLY_LE) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[] THEN REPEAT CONJ_TAC THEN ASM_MESON_TAC[];
      ALL_TAC] THEN
    DISCH_THEN ACCEPT_TAC; ALL_TAC] THEN
  (* M = emeet AY AZ *)
  SUBGOAL_THEN `emeet D (E:A->A->bool) B leq AY AZ M` ASSUME_TAC THENL
   [MAP_EVERY EXPAND_TAC ["AY";"AZ";"M"] THEN
    MATCH_MP_TAC(ISPECL[`apply_form 4 5 6`;`apply_form 4 5 7`;`D:A->bool`;
                        `E:A->A->bool`;
                        `B:A`;`leq:A`;`vv3:num->A`] BVALF_AND_MEET) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(M:A) IN D /\ (E:A->A->bool) M B` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[EMEET_IN]; ALL_TAC] THEN
  (* ebv_eq Y Z EQ *)
  SUBGOAL_THEN `ebv_eq D (E:A->A->bool) B leq Y Z EQ` ASSUME_TAC THENL
   [EXPAND_TAC "EQ" THEN
    MP_TAC(ISPECL[`6`;`7`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
                  `vv3:num->A`]
           BVALF_EQ2) THEN ASM_SIMP_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(EQ:A) IN D /\ (E:A->A->bool) EQ B` STRIP_ASSUME_TAC THENL
   [EXPAND_TAC "EQ" THEN ASM_MESON_TAC[BVALF_SPEC; BVALF_IN_B]; ALL_TAC] THEN
  (* MM = emeet mvY mvZ *)
  SUBGOAL_THEN `?MM:A. emeet D (E:A->A->bool) B leq mvY mvZ MM`
    (X_CHOOSE_TAC `MM:A`) THENL
   [MATCH_MP_TAC EBALG_MEET THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(MM:A) IN D /\ (E:A->A->bool) MM B` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[EMEET_IN]; ALL_TAC] THEN
  (* MM <= EQ via C3_RESID *)
  SUBGOAL_THEN `erel D (E:A->A->bool) leq MM EQ` ASSUME_TAC THENL
   [MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`onebee:A`;`X:A`;
                  `Y:A`;`Z:A`;
                  `gam:A`;`d:A`;`g:A`;`gc:A`;`op1:A`;`sa1:A`;`sab1:A`;`op2:A`;
                  `sa2:A`;`sab2:A`;
                  `mvY:A`;`mvZ:A`;`EQ:A`;`MM:A`] C3_RESID) THEN
    ANTS_TAC THENL [REPEAT CONJ_TAC THEN CLOSE; ALL_TAC] THEN
    DISCH_THEN ACCEPT_TAC; ALL_TAC] THEN
  (* M <= AY, M <= AZ *)
  MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`AY:A`;`AZ:A`;`M:A`]
         EMEET_LE) THEN
  ASM_REWRITE_TAC[] THEN STRIP_TAC THEN
  (* M <= mvY, M <= mvZ *)
  SUBGOAL_THEN `erel D (E:A->A->bool) leq M mvY` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`M:A`;
                        `AY:A`;`mvY:A`]
                 EPORDER_TRANS) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq M mvZ` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`M:A`;
                        `AZ:A`;`mvZ:A`]
                 EPORDER_TRANS) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* M <= MM *)
  SUBGOAL_THEN `erel D (E:A->A->bool) leq M MM` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`mvY:A`;
                        `mvZ:A`;`MM:A`;`M:A`]
                 EMEET_GREATEST) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* M <= EQ ; goal is erel M EQ *)
  SUBGOAL_THEN `erel D (E:A->A->bool) leq M EQ` MP_TAC THENL
   [MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`M:A`;
                        `MM:A`;`EQ:A`]
                 EPORDER_TRANS) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MAP_EVERY EXPAND_TAC ["M";"EQ"] THEN REWRITE_TAC[]);;

(* APPLY_INJ_CRUX : the per-(c,c') heart of the injective clause C4.
   c = <u,w>, c' = <u',w'> both in g; g injective (w=w' ==> u=u').
   op1 = <X,Y>, op2 = <W,Y>.  ec = [[op1 = c^]], ec' = [[op2 = c'^]].
   Claim: emeet ec' ec <= [[X=W]].
   PROJ1/PROJ2 give ec <= [[X=cu]],[[Y=cw]] and ec' <= [[W=cu']],[[Y=cw']].
   Case w=w': g inj => u=u' => cu=cu' (ECHECK_SV); EBV_EQ_CONG on
     [[X=cu]],[[cu=W]] gives meet <= [[X=W]].
   Case w<>w': ECHECK_EQ_BOT makes [[cw=cw']]=bot; EBV_EQ_CONG on
     [[cw=Y]],[[Y=cw']] gives meet <= bot, so m = bot <= [[X=W]] (EBOT_LE). *)
let APPLY_INJ_CRUX = prove
 (`!D (E:A->A->bool) B leq onebee X Y W u w u' w' cu cw cu' cw' c c' vc vc'
      op1 sa1 sab1 op2 sa2 sab2 ec ec' eq m.
    model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
    onebee IN D /\ E onebee B /\ etop D E B leq onebee /\
    (!uu:A. uu IN D ==> elmem D E uu) /\
    X IN D /\ Y IN D /\ W IN D /\
    bname D E B X /\ bname D E B Y /\ bname D E B W /\
    echeck D E onebee u cu /\ echeck D E onebee w cw /\
    echeck D E onebee u' cu' /\ echeck D E onebee w' cw' /\
    echeck D E onebee c vc /\ echeck D E onebee c' vc' /\
    eopair D E u w c /\ eopair D E u' w' c' /\
    (w = w' ==> u = u') /\
    op1 IN D /\ bname D E B op1 /\ sa1 IN D /\ bname D E B sa1 /\
    sab1 IN D /\ bname D E B sab1 /\
    eapply D E op1 sa1 onebee /\ eapply D E op1 sab1 onebee /\
    (!t q. t IN D /\ q IN D /\ eapply D E op1 t q ==> t = sa1 \/ t = sab1) /\
    eapply D E sa1 X onebee /\
    (!t q. t IN D /\ q IN D /\ eapply D E sa1 t q ==> t = X \/ t = X) /\
    eapply D E sab1 X onebee /\ eapply D E sab1 Y onebee /\
    (!t q. t IN D /\ q IN D /\ eapply D E sab1 t q ==> t = X \/ t = Y) /\
    op2 IN D /\ bname D E B op2 /\ sa2 IN D /\ bname D E B sa2 /\
    sab2 IN D /\ bname D E B sab2 /\
    eapply D E op2 sa2 onebee /\ eapply D E op2 sab2 onebee /\
    (!t q. t IN D /\ q IN D /\ eapply D E op2 t q ==> t = sa2 \/ t = sab2) /\
    eapply D E sa2 W onebee /\
    (!t q. t IN D /\ q IN D /\ eapply D E sa2 t q ==> t = W \/ t = W) /\
    eapply D E sab2 W onebee /\ eapply D E sab2 Y onebee /\
    (!t q. t IN D /\ q IN D /\ eapply D E sab2 t q ==> t = W \/ t = Y) /\
    ec IN D /\ E ec B /\ ebv_eq D E B leq op1 vc ec /\
    ec' IN D /\ E ec' B /\ ebv_eq D E B leq op2 vc' ec' /\
    eq IN D /\ E eq B /\ ebv_eq D E B leq X W eq /\
    m IN D /\ emeet D E B leq ec' ec m
    ==> erel D E leq m eq`,
  let CLOSE = FIRST_ASSUM ACCEPT_TAC ORELSE FIRST_ASSUM MATCH_ACCEPT_TAC in
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `(u:A) IN D /\ (w:A) IN D /\ (u':A) IN D /\ (w':A) IN D /\
                (c:A) IN D /\ (c':A) IN D /\
                (cu:A) IN D /\ (cw:A) IN D /\ (cu':A) IN D /\ (cw':A) IN D /\
                (vc:A) IN D /\ (vc':A) IN D` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[ECHECK_IMP]; ALL_TAC] THEN
  SUBGOAL_THEN `ebalg D (E:A->A->bool) B leq /\ eporder D E B leq`
    STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[ECBA_IMP_BALG; EBALG_IMP_PORDER]; ALL_TAC] THEN
  (* bnames of the member checks *)
  SUBGOAL_THEN `bname D (E:A->A->bool) B cu` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`onebee:A`;`B:A`;
                        `u:A`;`cu:A`]
                 ECHECK_IS_BNAME) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `bname D (E:A->A->bool) B cw` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`onebee:A`;`B:A`;
                        `w:A`;`cw:A`]
                 ECHECK_IS_BNAME) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `bname D (E:A->A->bool) B cu'` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`onebee:A`;`B:A`;
                        `u':A`;`cu':A`]
                 ECHECK_IS_BNAME) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `bname D (E:A->A->bool) B cw'` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`onebee:A`;`B:A`;
                        `w':A`;`cw':A`]
                 ECHECK_IS_BNAME) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `bname D (E:A->A->bool) B vc` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`onebee:A`;`B:A`;
                        `c:A`;`vc:A`]
                 ECHECK_IS_BNAME) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `bname D (E:A->A->bool) B vc'` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`onebee:A`;`B:A`;
                        `c':A`;`vc':A`]
                 ECHECK_IS_BNAME) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* Kuratowski bundles s1,p1 of vc=<u,w>^ and s2,p2 of vc'=<u',w'>^ *)
  MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`onebee:A`;`u:A`;`w:A`;
    `cu:A`;`cw:A`;`c:A`;`vc:A`] ECHECK_KUR_AUTO) THEN
  ANTS_TAC THENL [REPEAT CONJ_TAC THEN CLOSE; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `s1:A` (X_CHOOSE_THEN `p1:A` STRIP_ASSUME_TAC)) THEN
  MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`onebee:A`;`u':A`;`w':A`;
    `cu':A`;`cw':A`;`c':A`;`vc':A`] ECHECK_KUR_AUTO) THEN
  ANTS_TAC THENL [REPEAT CONJ_TAC THEN CLOSE; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `s2:A` (X_CHOOSE_THEN `p2:A` STRIP_ASSUME_TAC)) THEN
  (* equality values eXu=[[X=cu]], eYw=[[Y=cw]], eWu'=[[W=cu']], *)
  (* eYw'=[[Y=cw']] *)
  SUBGOAL_THEN
    `?eXu:A. eXu IN D /\ (E:A->A->bool) eXu B /\ ebv_eq D E B leq X cu eXu`
    (X_CHOOSE_THEN `eXu:A` STRIP_ASSUME_TAC) THENL
   [MATCH_MP_TAC EBV_EQ_VAL_EXISTS THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN
    `?eYw:A. eYw IN D /\ (E:A->A->bool) eYw B /\ ebv_eq D E B leq Y cw eYw`
    (X_CHOOSE_THEN `eYw:A` STRIP_ASSUME_TAC) THENL
   [MATCH_MP_TAC EBV_EQ_VAL_EXISTS THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN
    `?eWu':A. eWu' IN D /\ (E:A->A->bool) eWu' B /\
     ebv_eq D E B leq W cu' eWu'`
    (X_CHOOSE_THEN `eWu':A` STRIP_ASSUME_TAC) THENL
   [MATCH_MP_TAC EBV_EQ_VAL_EXISTS THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN
    `?eYw':A. eYw' IN D /\ (E:A->A->bool) eYw' B /\
     ebv_eq D E B leq Y cw' eYw'`
    (X_CHOOSE_THEN `eYw':A` STRIP_ASSUME_TAC) THENL
   [MATCH_MP_TAC EBV_EQ_VAL_EXISTS THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* projections: ec <= eXu, ec <= eYw (op1,vc) ; ec' <= eWu', ec' <= eYw' *)
  (* (op2,vc') *)
  SUBGOAL_THEN `erel D (E:A->A->bool) leq ec eXu` ASSUME_TAC THENL
   [MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`onebee:A`;
      `X:A`;`Y:A`;`cu:A`;`cw:A`;`op1:A`;`sa1:A`;`sab1:A`;`s1:A`;`p1:A`;`vc:A`;
      `ec:A`;`eXu:A`]
      EBV_EQ_KURCHECK_PROJ1) THEN
    ANTS_TAC THENL [REPEAT CONJ_TAC THEN CLOSE; ALL_TAC] THEN
    DISCH_THEN ACCEPT_TAC; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq ec eYw` ASSUME_TAC THENL
   [MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`onebee:A`;
      `X:A`;`Y:A`;`cu:A`;`cw:A`;`op1:A`;`sa1:A`;`sab1:A`;`s1:A`;`p1:A`;`vc:A`;
      `ec:A`;`eXu:A`;
      `eYw:A`;`u:A`;`w:A`] EBV_EQ_KURCHECK_PROJ2) THEN
    ANTS_TAC THENL [REPEAT CONJ_TAC THEN CLOSE; ALL_TAC] THEN
    DISCH_THEN ACCEPT_TAC; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq ec' eWu'` ASSUME_TAC THENL
   [MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`onebee:A`;
      `W:A`;`Y:A`;`cu':A`;`cw':A`;`op2:A`;`sa2:A`;`sab2:A`;`s2:A`;`p2:A`;
      `vc':A`;`ec':A`;`eWu':A`]
      EBV_EQ_KURCHECK_PROJ1) THEN
    ANTS_TAC THENL [REPEAT CONJ_TAC THEN CLOSE; ALL_TAC] THEN
    DISCH_THEN ACCEPT_TAC; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq ec' eYw'` ASSUME_TAC THENL
   [MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`onebee:A`;
      `W:A`;`Y:A`;`cu':A`;`cw':A`;`op2:A`;`sa2:A`;`sab2:A`;`s2:A`;`p2:A`;
      `vc':A`;`ec':A`;`eWu':A`;
      `eYw':A`;`u':A`;`w':A`] EBV_EQ_KURCHECK_PROJ2) THEN
    ANTS_TAC THENL [REPEAT CONJ_TAC THEN CLOSE; ALL_TAC] THEN
    DISCH_THEN ACCEPT_TAC; ALL_TAC] THEN
  (* m <= ec', m <= ec *)
  SUBGOAL_THEN `(E:A->A->bool) m B /\ erel D E leq m ec' /\ erel D E leq m ec`
    STRIP_ASSUME_TAC THENL
   [UNDISCH_TAC `emeet D (E:A->A->bool) B leq ec' ec m` THEN
    REWRITE_TAC[emeet] THEN MESON_TAC[]; ALL_TAC] THEN
  (* ---- case split on w = w' ---- *)
  ASM_CASES_TAC `w:A = w'` THENL
   [(* w = w' : injective gives u = u', hence cu' = cu *)
    SUBGOAL_THEN `u:A = u'` ASSUME_TAC THENL [ASM_MESON_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN `cu':A = cu` SUBST_ALL_TAC THENL
     [MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`onebee:A`;`u:A`;
                          `cu':A`;`cu:A`]
                   ECHECK_SV) THEN ASM_MESON_TAC[]; ALL_TAC] THEN
    (* [[cu=W]] from eWu' by symmetry *)
    SUBGOAL_THEN `ebv_eq D (E:A->A->bool) B leq cu W eWu'` ASSUME_TAC THENL
     [MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`W:A`;
                          `cu:A`;`eWu':A`]
                   EBV_EQ_SYM) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN `?z23:A. emeet D (E:A->A->bool) B leq eXu eWu' z23`
      (X_CHOOSE_TAC `z23:A`) THENL
     [MATCH_MP_TAC EBALG_MEET THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN `(z23:A) IN D /\ (E:A->A->bool) z23 B` STRIP_ASSUME_TAC THENL
     [ASM_MESON_TAC[EMEET_IN]; ALL_TAC] THEN
    SUBGOAL_THEN `erel D (E:A->A->bool) leq z23 eq` ASSUME_TAC THENL
     [MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`X:A`;
                          `cu:A`;`W:A`;
                          `eXu:A`;`eWu':A`;`eq:A`;`z23:A`] EBV_EQ_CONG) THEN
      ASM_REWRITE_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN `erel D (E:A->A->bool) leq m eXu` ASSUME_TAC THENL
     [MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`m:A`;
                          `ec:A`;`eXu:A`]
                   EPORDER_TRANS) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN `erel D (E:A->A->bool) leq m eWu'` ASSUME_TAC THENL
     [MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`m:A`;
                          `ec':A`;`eWu':A`]
                   EPORDER_TRANS) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN `erel D (E:A->A->bool) leq m z23` ASSUME_TAC THENL
     [MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
                          `eXu:A`;`eWu':A`;
                          `z23:A`;`m:A`] EMEET_GREATEST) THEN
      ASM_REWRITE_TAC[]; ALL_TAC] THEN
    MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`m:A`;
                        `z23:A`;`eq:A`]
                 EPORDER_TRANS) THEN ASM_REWRITE_TAC[];
    (* w <> w' : [[cw=cw']] = bot *)
    SUBGOAL_THEN `ebv_eq D (E:A->A->bool) B leq cw Y eYw` ASSUME_TAC THENL
     [MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`Y:A`;
                          `cw:A`;`eYw:A`]
                   EBV_EQ_SYM) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN
      `?zcc:A. zcc IN D /\ (E:A->A->bool) zcc B /\ ebv_eq D E B leq cw cw' zcc`
      (X_CHOOSE_THEN `zcc:A` STRIP_ASSUME_TAC) THENL
     [MATCH_MP_TAC EBV_EQ_VAL_EXISTS THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN `ebot D (E:A->A->bool) B leq zcc` ASSUME_TAC THENL
     [MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`onebee:A`;
                          `w:A`;`w':A`;
                          `cw:A`;`cw':A`;`zcc:A`] ECHECK_EQ_BOT) THEN
                 ASM_REWRITE_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN `?z23:A. emeet D (E:A->A->bool) B leq eYw eYw' z23`
      (X_CHOOSE_TAC `z23:A`) THENL
     [MATCH_MP_TAC EBALG_MEET THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN `(z23:A) IN D /\ (E:A->A->bool) z23 B` STRIP_ASSUME_TAC THENL
     [ASM_MESON_TAC[EMEET_IN]; ALL_TAC] THEN
    SUBGOAL_THEN `erel D (E:A->A->bool) leq z23 zcc` ASSUME_TAC THENL
     [MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`cw:A`;
                          `Y:A`;`cw':A`;
                          `eYw:A`;`eYw':A`;`zcc:A`;`z23:A`] EBV_EQ_CONG) THEN
                 ASM_REWRITE_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN `erel D (E:A->A->bool) leq m eYw` ASSUME_TAC THENL
     [MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`m:A`;
                          `ec:A`;`eYw:A`]
                   EPORDER_TRANS) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN `erel D (E:A->A->bool) leq m eYw'` ASSUME_TAC THENL
     [MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`m:A`;
                          `ec':A`;`eYw':A`]
                   EPORDER_TRANS) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN `erel D (E:A->A->bool) leq m z23` ASSUME_TAC THENL
     [MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
                          `eYw:A`;`eYw':A`;
                          `z23:A`;`m:A`] EMEET_GREATEST) THEN
                 ASM_REWRITE_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN `erel D (E:A->A->bool) leq m zcc` ASSUME_TAC THENL
     [MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`m:A`;
                          `z23:A`;`zcc:A`]
                   EPORDER_TRANS) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN `m:A = zcc` SUBST_ALL_TAC THENL
     [MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`m:A`;
                          `zcc:A`] ELE_BOT) THEN
      ASM_REWRITE_TAC[]; ALL_TAC] THEN
    MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`zcc:A`;
                        `eq:A`] EBOT_LE) THEN
    ASM_REWRITE_TAC[]]);;

(* C4_RESID : the double-residuation core of the injective clause.
   mvY = [[<X,Y> in g^]], mvZ = [[<W,Y> in g^]], MM = emeet mvY mvZ,
   eq = [[X=W]].  Claim MM <= eq.  Same residuation skeleton as C3_RESID,
   per-(c,c') crux is APPLY_INJ_CRUX; g injective (w=w' ==> u=u'). *)
let C4_RESID = prove
 (`!D (E:A->A->bool) B leq onebee X Y W gam d g gc
      op1 sa1 sab1 op2 sa2 sab2 mvY mvZ eq MM.
    model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
    onebee IN D /\ E onebee B /\ etop D E B leq onebee /\
    (!uu:A. uu IN D ==> elmem D E uu) /\
    X IN D /\ Y IN D /\ W IN D /\
    bname D E B X /\ bname D E B Y /\ bname D E B W /\
    echeck D E onebee g gc /\
    (!c:A. c IN D /\ E c g ==> ?u w. u IN D /\ w IN D /\ E u gam /\ E w d /\
     eopair D E u w c) /\
    (!(u:A) (w:A) (u':A) (w':A) c c'. u IN D /\ w IN D /\ u' IN D /\ w' IN D /\
         E c g /\ E c' g /\
         eopair D E u w c /\ eopair D E u' w' c' /\ w = w' ==> u = u') /\
    op1 IN D /\ bname D E B op1 /\ sa1 IN D /\ bname D E B sa1 /\
    sab1 IN D /\ bname D E B sab1 /\
    eapply D E op1 sa1 onebee /\ eapply D E op1 sab1 onebee /\
    (!t q. t IN D /\ q IN D /\ eapply D E op1 t q ==> t = sa1 \/ t = sab1) /\
    eapply D E sa1 X onebee /\
    (!t q. t IN D /\ q IN D /\ eapply D E sa1 t q ==> t = X \/ t = X) /\
    eapply D E sab1 X onebee /\ eapply D E sab1 Y onebee /\
    (!t q. t IN D /\ q IN D /\ eapply D E sab1 t q ==> t = X \/ t = Y) /\
    op2 IN D /\ bname D E B op2 /\ sa2 IN D /\ bname D E B sa2 /\
    sab2 IN D /\ bname D E B sab2 /\
    eapply D E op2 sa2 onebee /\ eapply D E op2 sab2 onebee /\
    (!t q. t IN D /\ q IN D /\ eapply D E op2 t q ==> t = sa2 \/ t = sab2) /\
    eapply D E sa2 W onebee /\
    (!t q. t IN D /\ q IN D /\ eapply D E sa2 t q ==> t = W \/ t = W) /\
    eapply D E sab2 W onebee /\ eapply D E sab2 Y onebee /\
    (!t q. t IN D /\ q IN D /\ eapply D E sab2 t q ==> t = W \/ t = Y) /\
    mvY IN D /\ E mvY B /\ ebv_in D E B leq op1 gc mvY /\
    mvZ IN D /\ E mvZ B /\ ebv_in D E B leq op2 gc mvZ /\
    eq IN D /\ E eq B /\ ebv_eq D E B leq X W eq /\
    MM IN D /\ emeet D E B leq mvY mvZ MM
    ==> erel D E leq MM eq`,
  let CLOSE = FIRST_ASSUM ACCEPT_TAC ORELSE FIRST_ASSUM MATCH_ACCEPT_TAC in
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `ebalg D (E:A->A->bool) B leq /\ eporder D E B leq`
    STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[ECBA_IMP_BALG; EBALG_IMP_PORDER]; ALL_TAC] THEN
  (* IY = ebimp mvZ eq *)
  SUBGOAL_THEN `?IY:A. ebimp D E B leq mvZ eq IY` (X_CHOOSE_TAC `IY:A`) THENL
   [MATCH_MP_TAC EBIMP_EXISTS THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(IY:A) IN D /\ (E:A->A->bool) IY B` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[EBIMP_IN]; ALL_TAC] THEN
  (* ---- OUTER sup : erel mvY IY ---- *)
  SUBGOAL_THEN `erel D (E:A->A->bool) leq mvY IY` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`onebee:A`;
                        `g:A`;`gc:A`;
                        `op1:A`;`mvY:A`;`IY:A`] ECHECK_IN_LE_SUP) THEN
    ASM_REWRITE_TAC[] THEN
    MAP_EVERY X_GEN_TAC [`c:A`;`vc:A`;`ec:A`] THEN STRIP_TAC THEN
    SUBGOAL_THEN `(c:A) IN D /\ (vc:A) IN D` STRIP_ASSUME_TAC THENL
     [MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`onebee:A`;`c:A`;`vc:A`]
        ECHECK_IMP) THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    SUBGOAL_THEN
      `?u w. u IN D /\ w IN D /\ E u gam /\ E w d /\
       eopair D (E:A->A->bool) u w c`
      STRIP_ASSUME_TAC THENL
      [FIRST_ASSUM MATCH_MP_TAC THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
      SUBGOAL_THEN `?cu. echeck D (E:A->A->bool) onebee u cu`
        (X_CHOOSE_TAC `cu:A`) THENL
        [ASM_MESON_TAC[ECHECK_EXHAUSTION]; ALL_TAC] THEN
    SUBGOAL_THEN `?cw. echeck D (E:A->A->bool) onebee w cw`
      (X_CHOOSE_TAC `cw:A`) THENL
      [ASM_MESON_TAC[ECHECK_EXHAUSTION]; ALL_TAC] THEN
    SUBGOAL_THEN `(E:A->A->bool) ec B` ASSUME_TAC THENL
     [MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`op1:A`;
                          `vc:A`;`ec:A`]
                   EBV_EQ_IN_B) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN `?m1:A. emeet D (E:A->A->bool) B leq ec mvZ m1`
      (X_CHOOSE_TAC `m1:A`) THENL
      [MATCH_MP_TAC EBALG_MEET THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN `(m1:A) IN D /\ (E:A->A->bool) m1 B` STRIP_ASSUME_TAC THENL
     [ASM_MESON_TAC[EMEET_IN]; ALL_TAC] THEN
    SUBGOAL_THEN `?IZ:A. ebimp D E B leq ec eq IZ` (X_CHOOSE_TAC `IZ:A`) THENL
     [MATCH_MP_TAC EBIMP_EXISTS THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN `(IZ:A) IN D /\ (E:A->A->bool) IZ B` STRIP_ASSUME_TAC THENL
     [ASM_MESON_TAC[EBIMP_IN]; ALL_TAC] THEN
    SUBGOAL_THEN `emeet D (E:A->A->bool) B leq mvZ ec m1` ASSUME_TAC THENL
     [MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`ec:A`;
                          `mvZ:A`;`m1:A`]
                   EMEET_SYM) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    (* ---- INNER sup : erel mvZ IZ ---- *)
    SUBGOAL_THEN `erel D (E:A->A->bool) leq mvZ IZ` ASSUME_TAC THENL
     [MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`onebee:A`;
                          `g:A`;`gc:A`;
                          `op2:A`;`mvZ:A`;`IZ:A`] ECHECK_IN_LE_SUP) THEN
      ASM_REWRITE_TAC[] THEN
      MAP_EVERY X_GEN_TAC [`c':A`;`vc':A`;`ec':A`] THEN STRIP_TAC THEN
      SUBGOAL_THEN `(c':A) IN D /\ (vc':A) IN D` STRIP_ASSUME_TAC THENL
       [MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`onebee:A`;
                            `c':A`;`vc':A`]
                     ECHECK_IMP) THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
      SUBGOAL_THEN
        `?u' w'. u' IN D /\ w' IN D /\ E u' gam /\ E w' d /\
         eopair D (E:A->A->bool) u' w' c'`
        STRIP_ASSUME_TAC THENL
        [FIRST_ASSUM MATCH_MP_TAC THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
        SUBGOAL_THEN `?cu'. echeck D (E:A->A->bool) onebee u' cu'`
          (X_CHOOSE_TAC `cu':A`) THENL
          [ASM_MESON_TAC[ECHECK_EXHAUSTION]; ALL_TAC] THEN
      SUBGOAL_THEN `?cw'. echeck D (E:A->A->bool) onebee w' cw'`
        (X_CHOOSE_TAC `cw':A`) THENL
        [ASM_MESON_TAC[ECHECK_EXHAUSTION]; ALL_TAC] THEN
      SUBGOAL_THEN `(E:A->A->bool) ec' B` ASSUME_TAC THENL
       [MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`op2:A`;
                            `vc':A`;`ec':A`]
                     EBV_EQ_IN_B) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
      SUBGOAL_THEN `?m2:A. emeet D (E:A->A->bool) B leq ec' ec m2`
        (X_CHOOSE_TAC `m2:A`) THENL
        [MATCH_MP_TAC EBALG_MEET THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
      SUBGOAL_THEN `(m2:A) IN D /\ (E:A->A->bool) m2 B` STRIP_ASSUME_TAC THENL
       [ASM_MESON_TAC[EMEET_IN]; ALL_TAC] THEN
      SUBGOAL_THEN `(w:A) = w' ==> (u:A) = u'` ASSUME_TAC THENL
       [DISCH_TAC THEN
        FIRST_ASSUM(MATCH_MP_TAC o
          SPECL[`u:A`;`w:A`;`u':A`;`w':A`;`c:A`;`c':A`]) THEN
        REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
      SUBGOAL_THEN `erel D (E:A->A->bool) leq m2 eq` ASSUME_TAC THENL
       [MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`onebee:A`;
                      `X:A`;`Y:A`;`W:A`;
                      `u:A`;`w:A`;`u':A`;`w':A`;`cu:A`;`cw:A`;`cu':A`;`cw':A`;
                      `c:A`;`c':A`;`vc:A`;`vc':A`;
                      `op1:A`;`sa1:A`;`sab1:A`;`op2:A`;`sa2:A`;`sab2:A`;`ec:A`;
                      `ec':A`;`eq:A`;`m2:A`]
          APPLY_INJ_CRUX) THEN
        ANTS_TAC THENL [REPEAT CONJ_TAC THEN CLOSE; ALL_TAC] THEN
        DISCH_THEN ACCEPT_TAC; ALL_TAC] THEN
      MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`ec':A`;`ec:A`;
                    `eq:A`;`IZ:A`;`m2:A`]
             EBIMP_LE_IMP) THEN
      ANTS_TAC THENL [REPEAT CONJ_TAC THEN CLOSE; ALL_TAC] THEN
      DISCH_THEN ACCEPT_TAC; ALL_TAC] THEN
    (* emeet ec mvZ = m1 <= eq *)
    SUBGOAL_THEN `erel D (E:A->A->bool) leq m1 eq` ASSUME_TAC THENL
     [MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`mvZ:A`;`ec:A`;
                    `eq:A`;`IZ:A`;`m1:A`]
             EBIMP_MEET_LE) THEN
      ANTS_TAC THENL [REPEAT CONJ_TAC THEN CLOSE; ALL_TAC] THEN
      DISCH_THEN ACCEPT_TAC; ALL_TAC] THEN
    MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`ec:A`;`mvZ:A`;
                  `eq:A`;`IY:A`;`m1:A`]
           EBIMP_LE_IMP) THEN
    ANTS_TAC THENL [REPEAT CONJ_TAC THEN CLOSE; ALL_TAC] THEN
    DISCH_THEN ACCEPT_TAC; ALL_TAC] THEN
  (* conclude : erel MM eq *)
  MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`mvY:A`;`mvZ:A`;
                `eq:A`;`IY:A`;`MM:A`]
         EBIMP_MEET_LE) THEN
  ANTS_TAC THENL [REPEAT CONJ_TAC THEN CLOSE; ALL_TAC] THEN
  DISCH_THEN ACCEPT_TAC);;

(* BIJFORM_C4_TOP : injective clause of bijform 3 2 is top.
   [[!!5 !!8 !!6 ((apply 4 5 6 && apply 4 8 6) --> Eq 5 8)]] = top.
   For X,W,Y : LHS = [[apply gc X Y]] meet [[apply gc W Y]] = emeet AY AZ = M.
   AY <= [[<X,Y> in gc]] = mvY, AZ <= [[<W,Y> in gc]] = mvZ (BVALF_APPLY_LE);
   so M <= mvY, M <= mvZ, hence M <= emeet mvY mvZ = MM (EMEET_GREATEST).
   MM <= [[X=W]] = EQ by C4_RESID (double residuation + APPLY_INJ_CRUX).
   M <= EQ by transitivity. *)
let BIJFORM_C4_TOP = prove
 (`!D (E:A->A->bool) B leq onebee vv gam d g gc gamc dc.
      model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
      onebee IN D /\ E onebee B /\ etop D E B leq onebee /\
      (!u:A. u IN D ==> elmem D E u) /\
      valuation D vv /\ (!i. bname D E B (vv i)) /\
      echeck D E onebee g gc /\ echeck D E onebee gam gamc /\
      echeck D E onebee d dc /\
      vv 2 = dc /\ vv 3 = gamc /\ vv 4 = gc /\
      (!c:A. c IN D /\ E c g ==> ?u w. u IN D /\ w IN D /\ E u gam /\ E w d /\
       eopair D E u w c) /\
      (!(u:A) (w:A) (u':A) (w':A) c c'. u IN D /\ w IN D /\
       u' IN D /\ w' IN D /\
       E c g /\ E c' g /\
           eopair D E u w c /\ eopair D E u' w' c' /\ w = w' ==> u = u')
      ==> etop D E B leq
            (bvalf D E B leq vv
               (!! 5 (!! 8 (!! 6 ((apply_form 4 5 6 && apply_form 4 8 6)
                                   --> Eq 5 8)))))`,
  let CLOSE = FIRST_ASSUM ACCEPT_TAC ORELSE FIRST_ASSUM MATCH_ACCEPT_TAC in
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `ebalg D (E:A->A->bool) B leq /\ eporder D E B leq`
    STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[ECBA_IMP_BALG; EBALG_IMP_PORDER]; ALL_TAC] THEN
  SUBGOAL_THEN
    `bname D (E:A->A->bool) B gc /\ bname D E B gamc /\ bname D E B dc`
    STRIP_ASSUME_TAC THENL [ASM_MESON_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(gc:A) IN D /\ (gamc:A) IN D /\ (dc:A) IN D`
    STRIP_ASSUME_TAC THENL [ASM_MESON_TAC[ECHECK_IMP]; ALL_TAC] THEN
  (* peel !! 5 -> X *)
  MP_TAC(ISPECL[`5`;
                `!! 8 (!! 6
                       ((apply_form 4 5 6 && apply_form 4 8 6) --> Eq 5 8))`;
                `D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`vv:num->A`]
              BVALF_ALL_TOP) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  X_GEN_TAC `X:A` THEN STRIP_TAC THEN
  ABBREV_TAC `vv1 = (5 |-> (X:A)) vv` THEN
  SUBGOAL_THEN
    `valuation D (vv1:num->A) /\ (!i. bname D (E:A->A->bool) B (vv1 i))`
    STRIP_ASSUME_TAC THENL
   [EXPAND_TAC "vv1" THEN
    CONJ_TAC THENL
    [MATCH_MP_TAC VALUATION_VALMOD; MATCH_MP_TAC BNAMEVAL_VALMOD] THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(vv1:num->A) 2 = dc /\ vv1 3 = gamc /\ vv1 4 = gc /\ vv1 5 = X`
    STRIP_ASSUME_TAC THENL
   [EXPAND_TAC "vv1" THEN ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER; ARITH_EQ];
    ALL_TAC] THEN
  (* peel !! 8 -> W *)
  MP_TAC(ISPECL[`8`;
                `!! 6 ((apply_form 4 5 6 && apply_form 4 8 6) --> Eq 5 8)`;
                `D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`vv1:num->A`]
      BVALF_ALL_TOP) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  X_GEN_TAC `W:A` THEN STRIP_TAC THEN
  ABBREV_TAC `vv2 = (8 |-> (W:A)) vv1` THEN
  SUBGOAL_THEN
    `valuation D (vv2:num->A) /\ (!i. bname D (E:A->A->bool) B (vv2 i))`
    STRIP_ASSUME_TAC THENL
   [EXPAND_TAC "vv2" THEN
    CONJ_TAC THENL
    [MATCH_MP_TAC VALUATION_VALMOD; MATCH_MP_TAC BNAMEVAL_VALMOD] THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN
    `(vv2:num->A) 2 = dc /\ vv2 3 = gamc /\ vv2 4 = gc /\
     vv2 5 = X /\ vv2 8 = W`
    STRIP_ASSUME_TAC THENL
   [EXPAND_TAC "vv2" THEN ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER; ARITH_EQ];
    ALL_TAC] THEN
  (* peel !! 6 -> Y *)
  MP_TAC(ISPECL[`6`; `(apply_form 4 5 6 && apply_form 4 8 6) --> Eq 5 8`;
    `D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`vv2:num->A`] BVALF_ALL_TOP) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  X_GEN_TAC `Y:A` THEN STRIP_TAC THEN
  ABBREV_TAC `vv3 = (6 |-> (Y:A)) vv2` THEN
  SUBGOAL_THEN
    `valuation D (vv3:num->A) /\ (!i. bname D (E:A->A->bool) B (vv3 i))`
    STRIP_ASSUME_TAC THENL
   [EXPAND_TAC "vv3" THEN
    CONJ_TAC THENL
    [MATCH_MP_TAC VALUATION_VALMOD; MATCH_MP_TAC BNAMEVAL_VALMOD] THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(vv3:num->A) 2 = dc /\ vv3 3 = gamc /\ vv3 4 = gc /\
                vv3 5 = X /\ vv3 8 = W /\ vv3 6 = Y`
    STRIP_ASSUME_TAC THENL
   [EXPAND_TAC "vv3" THEN ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER; ARITH_EQ];
    ALL_TAC] THEN
  (* peel --> *)
  MP_TAC(ISPECL[`apply_form 4 5 6 && apply_form 4 8 6`; `Eq 5 8`;
    `D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`vv3:num->A`] BVALF_IMP_TOP) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  (* build op1 = <X,Y> *)
  MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`X:A`;`Y:A`]
    EOPAIRNAME_CANON) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `op1:A`
             (X_CHOOSE_THEN `sa1:A` (X_CHOOSE_THEN `sab1:A`
                                     (X_CHOOSE_THEN `top0a:A`
                                      (X_CHOOSE_THEN `paa1:A`
                                       (X_CHOOSE_THEN `pab1:A`
                                        (X_CHOOSE_THEN `psa1:A`
                                         (X_CHOOSE_THEN `psab1:A`
                                          STRIP_ASSUME_TAC)))))))) THEN
  SUBGOAL_THEN `top0a:A = onebee` SUBST_ALL_TAC THENL
   [MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
                        `top0a:A`;`onebee:A`]
                 ETOP_UNIQUE) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* build op2 = <W,Y> *)
  MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`W:A`;`Y:A`]
    EOPAIRNAME_CANON) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `op2:A`
             (X_CHOOSE_THEN `sa2:A` (X_CHOOSE_THEN `sab2:A`
                                     (X_CHOOSE_THEN `top0b:A`
                                      (X_CHOOSE_THEN `paa2:A`
                                       (X_CHOOSE_THEN `pab2:A`
                                        (X_CHOOSE_THEN `psa2:A`
                                         (X_CHOOSE_THEN `psab2:A`
                                          STRIP_ASSUME_TAC)))))))) THEN
  SUBGOAL_THEN `top0b:A = onebee` SUBST_ALL_TAC THENL
   [MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
                        `top0b:A`;`onebee:A`]
                 ETOP_UNIQUE) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* mvY = [[op1 in gc]], mvZ = [[op2 in gc]] *)
  SUBGOAL_THEN
    `?mvY:A. mvY IN D /\ (E:A->A->bool) mvY B /\ ebv_in D E B leq op1 gc mvY`
    (X_CHOOSE_THEN `mvY:A` STRIP_ASSUME_TAC) THENL
   [MATCH_MP_TAC EBV_IN_VAL_EXISTS THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN
    `?mvZ:A. mvZ IN D /\ (E:A->A->bool) mvZ B /\ ebv_in D E B leq op2 gc mvZ`
    (X_CHOOSE_THEN `mvZ:A` STRIP_ASSUME_TAC) THENL
   [MATCH_MP_TAC EBV_IN_VAL_EXISTS THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* AY, AZ, M (LHS), EQ (RHS) *)
  ABBREV_TAC `AY = bvalf D (E:A->A->bool) B leq vv3 (apply_form 4 5 6)` THEN
  ABBREV_TAC `AZ = bvalf D (E:A->A->bool) B leq vv3 (apply_form 4 8 6)` THEN
  ABBREV_TAC
    `M = bvalf D (E:A->A->bool) B leq vv3
     (apply_form 4 5 6 && apply_form 4 8 6)` THEN
  ABBREV_TAC `EQ = bvalf D (E:A->A->bool) B leq vv3 (Eq 5 8)` THEN
  SUBGOAL_THEN `(AY:A) IN D /\ (E:A->A->bool) AY B` STRIP_ASSUME_TAC THENL
   [EXPAND_TAC "AY" THEN ASM_MESON_TAC[BVALF_SPEC; BVALF_IN_B]; ALL_TAC] THEN
  SUBGOAL_THEN `(AZ:A) IN D /\ (E:A->A->bool) AZ B` STRIP_ASSUME_TAC THENL
   [EXPAND_TAC "AZ" THEN ASM_MESON_TAC[BVALF_SPEC; BVALF_IN_B]; ALL_TAC] THEN
  (* AY <= mvY *)
  SUBGOAL_THEN `erel D (E:A->A->bool) leq AY mvY` ASSUME_TAC THENL
   [EXPAND_TAC "AY" THEN
    MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`vv3:num->A`;
                  `4`;`5`;`6`;
                  `sa1:A`;`sab1:A`;`op1:A`;`onebee:A`;`mvY:A`]
                   BVALF_APPLY_LE) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[] THEN REPEAT CONJ_TAC THEN ASM_MESON_TAC[];
      ALL_TAC] THEN
    DISCH_THEN ACCEPT_TAC; ALL_TAC] THEN
  (* AZ <= mvZ *)
  SUBGOAL_THEN `erel D (E:A->A->bool) leq AZ mvZ` ASSUME_TAC THENL
   [EXPAND_TAC "AZ" THEN
    MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`vv3:num->A`;
                  `4`;`8`;`6`;
                  `sa2:A`;`sab2:A`;`op2:A`;`onebee:A`;`mvZ:A`]
        BVALF_APPLY_LE) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[] THEN REPEAT CONJ_TAC THEN ASM_MESON_TAC[];
      ALL_TAC] THEN
    DISCH_THEN ACCEPT_TAC; ALL_TAC] THEN
  (* M = emeet AY AZ *)
  SUBGOAL_THEN `emeet D (E:A->A->bool) B leq AY AZ M` ASSUME_TAC THENL
   [MAP_EVERY EXPAND_TAC ["AY";"AZ";"M"] THEN
    MATCH_MP_TAC(ISPECL[`apply_form 4 5 6`;`apply_form 4 8 6`;`D:A->bool`;
                        `E:A->A->bool`;
                        `B:A`;`leq:A`;`vv3:num->A`] BVALF_AND_MEET) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(M:A) IN D /\ (E:A->A->bool) M B` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[EMEET_IN]; ALL_TAC] THEN
  (* ebv_eq X W EQ *)
  SUBGOAL_THEN `ebv_eq D (E:A->A->bool) B leq X W EQ` ASSUME_TAC THENL
   [EXPAND_TAC "EQ" THEN
    MP_TAC(ISPECL[`5`;`8`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
                  `vv3:num->A`]
           BVALF_EQ2) THEN ASM_SIMP_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(EQ:A) IN D /\ (E:A->A->bool) EQ B` STRIP_ASSUME_TAC THENL
   [EXPAND_TAC "EQ" THEN ASM_MESON_TAC[BVALF_SPEC; BVALF_IN_B]; ALL_TAC] THEN
  (* MM = emeet mvY mvZ *)
  SUBGOAL_THEN `?MM:A. emeet D (E:A->A->bool) B leq mvY mvZ MM`
    (X_CHOOSE_TAC `MM:A`) THENL
   [MATCH_MP_TAC EBALG_MEET THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(MM:A) IN D /\ (E:A->A->bool) MM B` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[EMEET_IN]; ALL_TAC] THEN
  (* MM <= EQ via C4_RESID *)
  SUBGOAL_THEN `erel D (E:A->A->bool) leq MM EQ` ASSUME_TAC THENL
   [MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`onebee:A`;`X:A`;
                  `Y:A`;`W:A`;
                  `gam:A`;`d:A`;`g:A`;`gc:A`;`op1:A`;`sa1:A`;`sab1:A`;`op2:A`;
                  `sa2:A`;`sab2:A`;
                  `mvY:A`;`mvZ:A`;`EQ:A`;`MM:A`] C4_RESID) THEN
    ANTS_TAC THENL [REPEAT CONJ_TAC THEN CLOSE; ALL_TAC] THEN
    DISCH_THEN ACCEPT_TAC; ALL_TAC] THEN
  (* M <= AY, M <= AZ *)
  MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`AY:A`;`AZ:A`;`M:A`]
         EMEET_LE) THEN
  ASM_REWRITE_TAC[] THEN STRIP_TAC THEN
  (* M <= mvY, M <= mvZ *)
  SUBGOAL_THEN `erel D (E:A->A->bool) leq M mvY` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`M:A`;
                        `AY:A`;`mvY:A`]
                 EPORDER_TRANS) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq M mvZ` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`M:A`;
                        `AZ:A`;`mvZ:A`]
                 EPORDER_TRANS) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* M <= MM *)
  SUBGOAL_THEN `erel D (E:A->A->bool) leq M MM` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`mvY:A`;
                        `mvZ:A`;`MM:A`;`M:A`]
                 EMEET_GREATEST) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* M <= EQ ; goal is erel M EQ *)
  SUBGOAL_THEN `erel D (E:A->A->bool) leq M EQ` MP_TAC THENL
   [MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`M:A`;
                        `MM:A`;`EQ:A`]
                 EPORDER_TRANS) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MAP_EVERY EXPAND_TAC ["M";"EQ"] THEN REWRITE_TAC[]);;

(* BIJFORM_CHECK_TOP : if g is (the check of) a ground bijection gam -> d,
   then [[bijform 3^ 2^]] = top.  Slots: domain index 3 (gamc, vv 3),
   codomain index 2 (dc, vv 2); bound function slot 4 witnessed by gc.
   bijform 3 2 = ?? 4 (C1 && (C2 && (C3 && (C4 && C5)))); witness the ??4 by
   gc (BVALF_EX_TOP), split the body (BVALF_AND_TOP), and discharge the five
   clauses by BIJFORM_C1_TOP..C5_TOP.  The body is never retyped: BVALF_EX_TOP
   reads p off the goal,
   and the clause lemmas carry their own clause formula. *)
let BIJFORM_CHECK_TOP = prove
 (`!D (E:A->A->bool) B leq onebee vv gam d g gc gamc dc.
      model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
      onebee IN D /\ E onebee B /\ etop D E B leq onebee /\
      (!u:A. u IN D ==> elmem D E u) /\
      valuation D vv /\ (!i. bname D E B (vv i)) /\
      echeck D E onebee g gc /\ echeck D E onebee gam gamc /\
      echeck D E onebee d dc /\
      vv 2 = dc /\ vv 3 = gamc /\
      (!c:A. c IN D /\ E c g ==> ?u w. u IN D /\ w IN D /\ E u gam /\ E w d /\
       eopair D E u w c) /\
      (!u:A. u IN D /\ E u gam ==> ?w c. w IN D /\ c IN D /\ E w d /\ E c g /\
       eopair D E u w c) /\
      (!(u:A) (w:A) (u':A) (w':A) c c'. u IN D /\ w IN D /\
       u' IN D /\ w' IN D /\
       E c g /\ E c' g /\
           eopair D E u w c /\ eopair D E u' w' c' /\ u = u' ==> w = w') /\
      (!(u:A) (w:A) (u':A) (w':A) c c'. u IN D /\ w IN D /\
       u' IN D /\ w' IN D /\
       E c g /\ E c' g /\
           eopair D E u w c /\ eopair D E u' w' c' /\ w = w' ==> u = u') /\
      (!w:A. w IN D /\ E w d ==> ?u c. u IN D /\ c IN D /\ E u gam /\ E c g /\
       eopair D E u w c)
      ==> etop D E B leq (bvalf D E B leq vv (bijform 3 2))`,
  let CLOSE = FIRST_ASSUM ACCEPT_TAC ORELSE FIRST_ASSUM MATCH_ACCEPT_TAC in
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `ebalg D (E:A->A->bool) B leq /\ eporder D E B leq`
    STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[ECBA_IMP_BALG; EBALG_IMP_PORDER]; ALL_TAC] THEN
  SUBGOAL_THEN `(g:A) IN D /\ (gc:A) IN D`
    STRIP_ASSUME_TAC THENL [ASM_MESON_TAC[ECHECK_IMP]; ALL_TAC] THEN
  SUBGOAL_THEN `bname D (E:A->A->bool) B gc` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`onebee:A`;`B:A`;
                        `g:A`;`gc:A`]
                 ECHECK_IS_BNAME) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  REWRITE_TAC[bijform] THEN
  REWRITE_TAC[ARITH_RULE
    `MAX 3 2 + 1 = 4 /\ MAX 3 2 + 2 = 5 /\ MAX 3 2 + 3 = 6 /\
     MAX 3 2 + 4 = 7 /\ MAX 3 2 + 5 = 8`] THEN
  (* witness the leading ?? 4 by gc; body p read from the goal by *)
  (* MATCH_MP_TAC *)
  MATCH_MP_TAC BVALF_EX_TOP THEN EXISTS_TAC `gc:A` THEN ASM_REWRITE_TAC[] THEN
  ABBREV_TAC `vv4 = (4 |-> (gc:A)) vv` THEN
  SUBGOAL_THEN
    `valuation D (vv4:num->A) /\ (!i. bname D (E:A->A->bool) B (vv4 i))`
    STRIP_ASSUME_TAC THENL
   [EXPAND_TAC "vv4" THEN
    CONJ_TAC THENL
    [MATCH_MP_TAC VALUATION_VALMOD; MATCH_MP_TAC BNAMEVAL_VALMOD] THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(vv4:num->A) 2 = dc /\ vv4 3 = gamc /\ vv4 4 = gc`
    STRIP_ASSUME_TAC THENL
   [EXPAND_TAC "vv4" THEN ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER; ARITH_EQ];
    ALL_TAC] THEN
  (* split the five clauses *)
  ASM_SIMP_TAC[BVALF_AND_TOP] THEN REPEAT CONJ_TAC THENL
   [MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`onebee:A`;
                  `vv4:num->A`;
                  `gam:A`;`d:A`;`g:A`;`gc:A`;`gamc:A`;`dc:A`]
       BIJFORM_C1_TOP) THEN
    ANTS_TAC THENL [REPEAT CONJ_TAC THEN CLOSE; ALL_TAC] THEN
    DISCH_THEN ACCEPT_TAC;
    MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`onebee:A`;
                  `vv4:num->A`;
                  `gam:A`;`d:A`;`g:A`;`gc:A`;`gamc:A`;`dc:A`]
         BIJFORM_C2_TOP) THEN
    ANTS_TAC THENL [REPEAT CONJ_TAC THEN CLOSE; ALL_TAC] THEN
    DISCH_THEN ACCEPT_TAC;
    MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`onebee:A`;
                  `vv4:num->A`;
                  `gam:A`;`d:A`;`g:A`;`gc:A`;`gamc:A`;`dc:A`]
           BIJFORM_C3_TOP) THEN
    ANTS_TAC THENL [REPEAT CONJ_TAC THEN CLOSE; ALL_TAC] THEN
    DISCH_THEN ACCEPT_TAC;
    MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`onebee:A`;
                  `vv4:num->A`;
                  `gam:A`;`d:A`;`g:A`;`gc:A`;`gamc:A`;`dc:A`]
             BIJFORM_C4_TOP) THEN
    ANTS_TAC THENL [REPEAT CONJ_TAC THEN CLOSE; ALL_TAC] THEN
    DISCH_THEN ACCEPT_TAC;
    MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`onebee:A`;
                  `vv4:num->A`;
                  `gam:A`;`d:A`;`g:A`;`gc:A`;`gamc:A`;`dc:A`]
               BIJFORM_C5_TOP) THEN
    ANTS_TAC THENL [REPEAT CONJ_TAC THEN CLOSE; ALL_TAC] THEN
    DISCH_THEN ACCEPT_TAC]);;

(* ===================================================================== *)
(* A2c-NC : for a ground NON-cardinal ordinal d, [[iscard_form d^]] = bot. *)
(* Three lemmas: EBIJ_CLEAN (cleanliness bridge), EBIJ_BIJFORM_CHECK_TOP   *)
(* (raw ground bijection forces [[bijform]]=top), ISCARD_CHECK_BOT.        *)
(* ===================================================================== *)

(* EBIJ_CLEAN : a ground apply-level bijection f:gam->d can be replaced by a
   "clean" bijection g whose every element is literally a Kuratowski pair with
   first coord in gam and second in d.  g = f INTER (gam CROSS d).  The pair-
   level cleanliness is exactly BIJFORM_CHECK_TOP's clause C1, which ebij alone
   does not supply. *)
let EBIJ_CLEAN = prove
 (`!D (E:A->A->bool) f gam d.
      model D E ZF_AX /\ gam IN D /\ d IN D /\ ebij D E f gam d
      ==> ?g. ebij D E g gam d /\
              (!c:A. c IN D /\ E c g
                     ==> ?u w. u IN D /\ w IN D /\ E u gam /\ E w d /\
                               eopair D E u w c)`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `(f:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[ebij]; ALL_TAC] THEN
  (* cr = gam CROSS d *)
  MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`gam:A`;`d:A`] ECROSS_EXISTS) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `cr:A` (LABEL_TAC "crcross")) THEN
  SUBGOAL_THEN `(cr:A) IN D` ASSUME_TAC THENL
   [USE_THEN "crcross" (ACCEPT_TAC o CONJUNCT1 o REWRITE_RULE[ecross]);
    ALL_TAC] THEN
  (* g = f INTER cr *)
  MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`f:A`;`cr:A`] EINTER_EXISTS) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `g:A` (LABEL_TAC "ginter")) THEN
  SUBGOAL_THEN `(g:A) IN D` ASSUME_TAC THENL
   [USE_THEN "ginter" (ACCEPT_TAC o CONJUNCT1 o REWRITE_RULE[einter]);
    ALL_TAC] THEN
  (* Hcr : membership in the cross product (D-guarded) *)
  SUBGOAL_THEN
    `!z:A. z IN D
           ==> ((E:A->A->bool) z cr <=>
                ?u w. u IN D /\ w IN D /\ E u gam /\ E w d /\
                  eopair D E u w z)`
    (LABEL_TAC "Hcr") THENL
   [GEN_TAC THEN DISCH_TAC THEN
    MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`gam:A`;`d:A`;`cr:A`;`z:A`]
      ECROSS_MEMBER) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN ACCEPT_TAC; ALL_TAC] THEN
  (* Hg : membership in the intersection (D-guarded) *)
  SUBGOAL_THEN
    `!z:A. z IN D ==> ((E:A->A->bool) z g <=> E z f /\ E z cr)`
      (LABEL_TAC "Hg") THENL
   [GEN_TAC THEN DISCH_TAC THEN
    USE_THEN "ginter"
      (MP_TAC o SPEC `z:A` o CONJUNCT2 o REWRITE_RULE[einter]) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN DISCH_THEN ACCEPT_TAC;
      ALL_TAC] THEN
  (* BR : eapply g = eapply f restricted to gam x d (D-guarded) *)
  SUBGOAL_THEN
    `!k t:A. k IN D /\ t IN D
             ==> (eapply D (E:A->A->bool) g k t <=>
                  eapply D E f k t /\ E k gam /\ E t d)` (LABEL_TAC "BR") THENL
   [REPEAT GEN_TAC THEN STRIP_TAC THEN REWRITE_TAC[eapply] THEN
    EQ_TAC THEN STRIP_TAC THENL
     [(* forward: z, eopair k t z, E z g *)
      SUBGOAL_THEN `(z:A) IN D` ASSUME_TAC THENL
       [ASM_MESON_TAC[EOPAIR_IN]; ALL_TAC] THEN
      SUBGOAL_THEN `(E:A->A->bool) z f /\ E z cr` STRIP_ASSUME_TAC THENL
       [ASM_MESON_TAC[]; ALL_TAC] THEN
      SUBGOAL_THEN
        `?u w:A. u IN D /\ w IN D /\ E u gam /\ E w d /\
                 eopair D (E:A->A->bool) u w z`
        STRIP_ASSUME_TAC THENL [ASM_MESON_TAC[]; ALL_TAC] THEN
      SUBGOAL_THEN `(k:A) = u /\ (t:A) = w` STRIP_ASSUME_TAC THENL
       [ASM_MESON_TAC[EOPAIR_INJ]; ALL_TAC] THEN
      CONJ_TAC THENL
       [EXISTS_TAC `z:A` THEN ASM_REWRITE_TAC[]; ASM_MESON_TAC[]];
      (* backward: z, eopair k t z, E z f, E k gam, E t d *)
      SUBGOAL_THEN `(z:A) IN D` ASSUME_TAC THENL
       [ASM_MESON_TAC[EOPAIR_IN]; ALL_TAC] THEN
      EXISTS_TAC `z:A` THEN ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[]];
     ALL_TAC] THEN
  (* assemble g *)
  EXISTS_TAC `g:A` THEN CONJ_TAC THENL
   [REWRITE_TAC[ebij] THEN
    UNDISCH_TAC `ebij D (E:A->A->bool) f gam d` THEN REWRITE_TAC[ebij] THEN
    STRIP_TAC THEN REPEAT CONJ_TAC THEN ASM_MESON_TAC[];
    GEN_TAC THEN STRIP_TAC THEN ASM_MESON_TAC[]]);;

(* EBIJ_BIJFORM_CHECK_TOP : a RAW ground bijection f:gam->d (apply-level, no
   cleanliness) forces [[bijform 3 2]] = top, provided vv 3 = gam^ and
   vv 2 = d^.  Internally: clean f to g (EBIJ_CLEAN), check g (ECHECK_
   EXHAUSTION), reconstruct BIJFORM_CHECK_TOP's five pair-level graph clauses
   from ebij g (apply-level) + cleanliness, then invoke BIJFORM_CHECK_TOP. *)
let EBIJ_BIJFORM_CHECK_TOP = prove
 (`!D (E:A->A->bool) B leq onebee vv f gam d gamc dc.
      model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
      onebee IN D /\ E onebee B /\ etop D E B leq onebee /\
      (!u:A. u IN D ==> elmem D E u) /\
      valuation D vv /\ (!i. bname D E B (vv i)) /\
      ebij D E f gam d /\
      echeck D E onebee gam gamc /\ echeck D E onebee d dc /\
      vv 2 = dc /\ vv 3 = gamc
      ==> etop D E B leq (bvalf D E B leq vv (bijform 3 2))`,
  let CLOSE = FIRST_ASSUM ACCEPT_TAC ORELSE FIRST_ASSUM MATCH_ACCEPT_TAC in
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  (* clean g : its totality conjunct is already D-guarded *)
  MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`f:A`;`gam:A`;`d:A`]
         EBIJ_CLEAN) THEN
  ANTS_TAC THENL [ASM_MESON_TAC[ECHECK_IMP]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `g:A`
    (CONJUNCTS_THEN2 (LABEL_TAC "ebg") (LABEL_TAC "C1"))) THEN
  (* gc = check of g *)
  SUBGOAL_THEN `(g:A) IN D` ASSUME_TAC THENL
   [USE_THEN "ebg" (ACCEPT_TAC o CONJUNCT1 o REWRITE_RULE[ebij]); ALL_TAC] THEN
  MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`onebee:A`;`g:A`]
         ECHECK_EXHAUSTION) THEN
  ANTS_TAC THENL [ASM_MESON_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `gc:A` (LABEL_TAC "gcheck")) THEN
  (* unfold ebij g into labelled clauses *)
  USE_THEN "ebg" (MP_TAC o REWRITE_RULE[ebij]) THEN
  INTRO_TAC "gD gcl1 gcl2 gcl3 gcl4 gcl5" THEN
  (* reusable: a pair in g with coords u,w gives an apply g u w *)
  SUBGOAL_THEN
    `!u w c:A. E c g /\ eopair D (E:A->A->bool) u w c ==> eapply D E g u w`
    (LABEL_TAC "mkap") THENL
   [REWRITE_TAC[eapply] THEN MESON_TAC[]; ALL_TAC] THEN
  (* C2 : totality at pair level (D-guarded) *)
  SUBGOAL_THEN
    `!u:A. u IN D /\ E u gam
           ==> ?w c. w IN D /\ c IN D /\ E w d /\ E c g /\ eopair D E u w c`
    (LABEL_TAC "C2") THENL
   [REPEAT GEN_TAC THEN STRIP_TAC THEN
    USE_THEN "gcl2" (MP_TAC o SPEC `u:A`) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    REWRITE_TAC[eapply] THEN STRIP_TAC THEN ASM_MESON_TAC[EOPAIR_IN];
    ALL_TAC] THEN
  (* C3 : functionality at pair level (D-guarded) *)
  SUBGOAL_THEN
    `!(u:A) (w:A) (u':A) (w':A) c c'. u IN D /\ w IN D /\ u' IN D /\ w' IN D /\
         E c g /\ E c' g /\
         eopair D E u w c /\ eopair D E u' w' c' /\ u = u' ==> w = w'`
    (LABEL_TAC "C3") THENL
   [REPEAT STRIP_TAC THEN ASM_MESON_TAC[]; ALL_TAC] THEN
  (* C4 : injectivity at pair level (D-guarded) *)
  SUBGOAL_THEN
    `!(u:A) (w:A) (u':A) (w':A) c c'. u IN D /\ w IN D /\ u' IN D /\ w' IN D /\
         E c g /\ E c' g /\
         eopair D E u w c /\ eopair D E u' w' c' /\ w = w' ==> u = u'`
    (LABEL_TAC "C4") THENL
   [REPEAT STRIP_TAC THEN ASM_MESON_TAC[]; ALL_TAC] THEN
  (* C5 : surjectivity at pair level (D-guarded) *)
  SUBGOAL_THEN
    `!w:A. w IN D /\ E w d
           ==> ?u c. u IN D /\ c IN D /\ E u gam /\ E c g /\ eopair D E u w c`
    (LABEL_TAC "C5") THENL
   [REPEAT GEN_TAC THEN STRIP_TAC THEN
    USE_THEN "gcl5" (MP_TAC o SPEC `w:A`) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    REWRITE_TAC[eapply] THEN STRIP_TAC THEN ASM_MESON_TAC[EOPAIR_IN];
    ALL_TAC] THEN
  (* invoke BIJFORM_CHECK_TOP *)
  MP_TAC(ISPECL
    [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`onebee:A`;`vv:num->A`;
     `gam:A`;`d:A`;`g:A`;`gc:A`;`gamc:A`;`dc:A`] BIJFORM_CHECK_TOP) THEN
  ANTS_TAC THENL [REPEAT CONJ_TAC THEN CLOSE; ALL_TAC] THEN
  DISCH_THEN ACCEPT_TAC);;

(* ISCARD_CHECK_BOT (A2c-NC) : for a ground NON-cardinal ordinal d (slot 2 =
   d^), [[iscard_form 2]] = bot.  No ORDFORM_CHECK_TOP needed: iscard_form 2 =
   ordinal_form 2 && (!!- 3 2 (Not(bijform 3 2))), and the second conjunct's
   value is bot (a smaller gam<d bijects with d, so [[bijform gam^ d^]]=top,
   [[Not..]]=bot,
   the guarded body (3%%2)-->Not.. = ebimp top bot = bot, and the
   universal GLB <= that body-instance = bot); then emeet _ bot = bot. *)
let ISCARD_CHECK_BOT = prove
 (`!D (E:A->A->bool) B leq onebee vv d dc.
      model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
      onebee IN D /\ E onebee B /\ etop D E B leq onebee /\
      (!u:A. u IN D ==> elmem D E u) /\
      valuation D vv /\ (!i. bname D E B (vv i)) /\
      eordinal D E d /\ ~ecardinal D E d /\
      echeck D E onebee d dc /\ vv 2 = dc
      ==> ebot D E B leq (bvalf D E B leq vv (iscard_form 2))`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  REWRITE_TAC[iscard_form] THEN
  REWRITE_TAC[ARITH_RULE `2 + 1 = 3`] THEN REWRITE_TAC[Forallmem_DEF] THEN
  SUBGOAL_THEN `ebalg D (E:A->A->bool) B leq /\ eporder D E B leq`
    STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[ECBA_IMP_BALG; EBALG_IMP_PORDER]; ALL_TAC] THEN
  SUBGOAL_THEN `(d:A) IN D` ASSUME_TAC THENL
  [ASM_MESON_TAC[EORDINAL_IN]; ALL_TAC] THEN
  (* non-cardinal ordinal => some gam with E gam d and a bijection gam -> d *)
  SUBGOAL_THEN `?h:A. ebij D (E:A->A->bool) h d d` (LABEL_TAC "idbij") THENL
   [MATCH_MP_TAC EBIJ_ID THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN
    `?gam:A. gam IN D /\ E gam d /\ ?ff. ebij D (E:A->A->bool) ff gam d`
    STRIP_ASSUME_TAC THENL
   [UNDISCH_TAC `~ecardinal D (E:A->A->bool) d` THEN
    REWRITE_TAC[ecardinal; ecardof] THEN ASM_REWRITE_TAC[] THEN
    ASM_MESON_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `(gam:A) IN D` ASSUME_TAC THENL [ASM_MESON_TAC[]; ALL_TAC] THEN
  (* gamc = check of gam *)
  MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`onebee:A`;`gam:A`]
         ECHECK_EXHAUSTION) THEN
  ANTS_TAC THENL [ASM_MESON_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `gamc:A` (LABEL_TAC "gamcheck")) THEN
  SUBGOAL_THEN `(gamc:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[ECHECK_IMP]; ALL_TAC] THEN
  SUBGOAL_THEN `bname D (E:A->A->bool) B gamc` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`onebee:A`;`B:A`;
                        `gam:A`;`gamc:A`]
                 ECHECK_IS_BNAME) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* vvg = (3 |-> gamc) vv *)
  ABBREV_TAC `vvg = (3 |-> (gamc:A)) vv` THEN
  SUBGOAL_THEN
    `valuation D (vvg:num->A) /\ (!i. bname D (E:A->A->bool) B (vvg i))`
    STRIP_ASSUME_TAC THENL
   [EXPAND_TAC "vvg" THEN
    CONJ_TAC THENL
    [MATCH_MP_TAC VALUATION_VALMOD; MATCH_MP_TAC BNAMEVAL_VALMOD] THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(vvg:num->A) 2 = dc /\ vvg 3 = gamc` STRIP_ASSUME_TAC THENL
   [EXPAND_TAC "vvg" THEN ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER; ARITH_EQ];
    ALL_TAC] THEN
  (* [[bijform 3 2]]_vvg = top *)
  SUBGOAL_THEN
    `etop D (E:A->A->bool) B leq (bvalf D E B leq vvg (bijform 3 2))`
    ASSUME_TAC THENL
   [MP_TAC(ISPECL
      [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`onebee:A`;`vvg:num->A`;
       `ff:A`;`gam:A`;`d:A`;`gamc:A`;`dc:A`] EBIJ_BIJFORM_CHECK_TOP) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN DISCH_THEN ACCEPT_TAC;
    ALL_TAC] THEN
  (* ebot [[Not(bijform 3 2)]]_vvg *)
  SUBGOAL_THEN
    `ebot D (E:A->A->bool) B leq (bvalf D E B leq vvg (Not (bijform 3 2)))`
    ASSUME_TAC THENL
   [MP_TAC(ISPECL[`bijform 3 2`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
                  `vvg:num->A`]
           BVALF_NOT_BOT) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* etop [[3 %% 2]]_vvg  (via ECHECK_IN_TOP, E gam d) *)
  SUBGOAL_THEN `etop D (E:A->A->bool) B leq (bvalf D E B leq vvg (3 %% 2))`
    ASSUME_TAC THENL
   [MP_TAC(ISPECL[`3`;`2`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
                  `vvg:num->A`]
           BVALF_MEM) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    ASM_REWRITE_TAC[] THEN DISCH_TAC THEN
    MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`onebee:A`;
      `gam:A`;`d:A`;`gamc:A`;`dc:A`;
      `bvalf D (E:A->A->bool) B leq vvg (3 %% 2)`]
      ECHECK_IN_TOP) THEN
    REPEAT CONJ_TAC THEN TRY(FIRST_ASSUM ACCEPT_TAC) THEN
    ASM_MESON_TAC[BVALF_SPEC]; ALL_TAC] THEN
  (* ebot [[(3%%2) --> Not(bijform 3 2)]]_vvg  (ebimp top y = y) *)
  SUBGOAL_THEN
    `ebot D (E:A->A->bool) B leq
          (bvalf D E B leq vvg ((3 %% 2) --> Not (bijform 3 2)))`
      ASSUME_TAC THENL
   [MP_TAC(ISPECL[`3 %% 2`;`Not (bijform 3 2)`;`D:A->bool`;`E:A->A->bool`;
                  `B:A`;`leq:A`;
                  `vvg:num->A`] BVALF_IMP) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN DISCH_TAC THEN
    MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
       `bvalf D (E:A->A->bool) B leq vvg (3 %% 2)`;
       `bvalf D (E:A->A->bool) B leq vvg (Not (bijform 3 2))`;
       `bvalf D (E:A->A->bool) B leq vvg ((3 %% 2) --> Not (bijform 3 2))`]
       EBIMP_TOP_ANT) THEN
    ANTS_TAC THENL
     [REPEAT CONJ_TAC THEN TRY(FIRST_ASSUM ACCEPT_TAC) THEN
      ASM_MESON_TAC[BVALF_SPEC; BVALF_IN_B]; ALL_TAC] THEN
    DISCH_THEN SUBST1_TAC THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* STEP B : ebot [[!! 3 body]]_vv *)
  SUBGOAL_THEN `ebot D (E:A->A->bool) B leq
     (bvalf D E B leq vv (!! 3 ((3 %% 2) --> Not (bijform 3 2))))`
    ASSUME_TAC THENL
   [MP_TAC(ISPECL[`3`;`(3 %% 2) --> Not (bijform 3 2)`;`D:A->bool`;
                  `E:A->A->bool`;
                  `B:A`;`leq:A`;`vv:num->A`;`gamc:A`] BVALF_ALL_LB) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    ASM_REWRITE_TAC[] THEN DISCH_TAC THEN
    SUBGOAL_THEN
      `bvalf D (E:A->A->bool) B leq vv
       (!! 3 ((3 %% 2) --> Not (bijform 3 2))) =
       bvalf D E B leq vvg ((3 %% 2) --> Not (bijform 3 2))` ASSUME_TAC THENL
     [MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
        `bvalf D (E:A->A->bool) B leq vv
         (!! 3 ((3 %% 2) --> Not (bijform 3 2)))`;
        `bvalf D (E:A->A->bool) B leq vvg ((3 %% 2) --> Not (bijform 3 2))`]
                    ELE_BOT) THEN
      REPEAT CONJ_TAC THEN TRY(FIRST_ASSUM ACCEPT_TAC) THEN
      ASM_MESON_TAC[BVALF_SPEC; BVALF_IN_B]; ALL_TAC] THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* STEP C : emeet [[ord]] bot = bot *)
  MP_TAC(ISPECL[`ordinal_form 2`;`!! 3 ((3 %% 2) --> Not (bijform 3 2))`;
    `D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`vv:num->A`] BVALF_AND_MEET) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN DISCH_TAC THEN
  MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
     `bvalf D (E:A->A->bool) B leq vv (ordinal_form 2)`;
     `bvalf D (E:A->A->bool) B leq vv (!! 3 ((3 %% 2) --> Not (bijform 3 2)))`;
     `bvalf D (E:A->A->bool) B leq vv
        (ordinal_form 2 && !! 3 ((3 %% 2) --> Not (bijform 3 2)))`]
      EMEET_LE) THEN
  ASM_REWRITE_TAC[] THEN STRIP_TAC THEN
  SUBGOAL_THEN
    `bvalf D (E:A->A->bool) B leq vv
        (ordinal_form 2 && !! 3 ((3 %% 2) --> Not (bijform 3 2))) =
     bvalf D E B leq vv (!! 3 ((3 %% 2) --> Not (bijform 3 2)))`
      ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
      `bvalf D (E:A->A->bool) B leq vv
         (ordinal_form 2 && !! 3 ((3 %% 2) --> Not (bijform 3 2)))`;
      `bvalf D (E:A->A->bool) B leq vv
       (!! 3 ((3 %% 2) --> Not (bijform 3 2)))`] ELE_BOT) THEN
    REPEAT CONJ_TAC THEN TRY(FIRST_ASSUM ACCEPT_TAC) THEN
    ASM_MESON_TAC[BVALF_SPEC; BVALF_IN_B]; ALL_TAC] THEN
  ASM_REWRITE_TAC[]);;

(* ===================================================================== *)
(* FORCING F7 / A2bij-BOT infrastructure (SVUNIFORM ladder).               *)
(* The apply_form single-valuedness bridge SVUNIFORM, its local           *)
(* membership helper BVALF_IND, and the four value-identification lemmas    *)
(* (KURBUNDLE / EMEET_ABSORB_LE / PMEM_VAL_EQ / APPLY_VAL_EQ) it rests on.  *)
(* ===================================================================== *)

(* ===================================================================== *)
(* KURBUNDLE : for bnames arg,val,f, package the V^B-Kuratowski pair name *)
(* op = {{arg},{arg,val}} of (arg,val) with its full eapply-exhaust       *)
(* bundle (sa={arg}, sab={arg,val}) over a common top, plus the           *)
(* membership value mv = ebv_in(op,f).  This is the one object through    *)
(* which both apply_form and the opair-inner membership value factor       *)
(* (via BVALF_APPLY GEN and BVALF_PMEM): with v i=f, v j=arg, v k=val and   *)
(* v 70=arg, v 71=val, v 72=f, both equal mv.  Built from EOPAIRNAME_CANON  *)
(* (bundle) + EBV_IN_VAL_EXISTS (value).  REUSABLE.                        *)
(* ===================================================================== *)

let KURBUNDLE = prove
 (`!D (E:A->A->bool) B leq arg val f.
     model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
     arg IN D /\ val IN D /\ f IN D /\
     bname D E B arg /\ bname D E B val /\ bname D E B f
     ==> ?op sa sab top mv.
          op IN D /\ bname D E B op /\ sa IN D /\ bname D E B sa /\
          sab IN D /\ bname D E B sab /\ top IN D /\ etop D E B leq top /\
          eapply D E sa arg top /\
          (!t q. t IN D /\ q IN D /\ eapply D E sa t q ==>
           t = arg \/ t = arg) /\
          eapply D E sab arg top /\ eapply D E sab val top /\
          (!t q. t IN D /\ q IN D /\ eapply D E sab t q ==>
           t = arg \/ t = val) /\
          eapply D E op sa top /\ eapply D E op sab top /\
          (!t q. t IN D /\ q IN D /\ eapply D E op t q ==>
           t = sa \/ t = sab) /\
          mv IN D /\ E mv B /\ ebv_in D E B leq op f mv`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`arg:A`;`val:A`]
     EOPAIRNAME_CANON) THEN
  ANTS_TAC THENL [ASM_MESON_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `op:A` (X_CHOOSE_THEN `sa:A` (X_CHOOSE_THEN `sab:A`
   (X_CHOOSE_THEN `top:A` (X_CHOOSE_THEN `paa:A` (X_CHOOSE_THEN `pab:A`
    (X_CHOOSE_THEN `psa:A`
     (X_CHOOSE_THEN `psab:A` STRIP_ASSUME_TAC)))))))) THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`op:A`;`f:A`]
     EBV_IN_VAL_EXISTS) THEN
  ANTS_TAC THENL [ASM_MESON_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `mv:A` STRIP_ASSUME_TAC) THEN
  MAP_EVERY EXISTS_TAC [`op:A`;`sa:A`;`sab:A`;`top:A`;`mv:A`] THEN
  ASM_REWRITE_TAC[]);;

(* EMEET_ABSORB_LE : meet absorption from the order -- if a <= b then a is   *)
(* itself the meet of a and b.  Used by SVUNIFORM to collapse                *)
(* [[apply345 && apply346]] = emeet(mv_xy,mv_xG) back to mv_xy once the      *)
(* sup-witness Gn forces mv_xy <= mv_xG.  REUSABLE.                          *)
let EMEET_ABSORB_LE = prove
 (`!D (E:A->A->bool) p leq a b.
      ebalg D E p leq /\ a IN D /\ b IN D /\ E a p /\ E b p /\ erel D E leq a b
      ==> emeet D E p leq a b a`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `eporder D (E:A->A->bool) p leq` ASSUME_TAC THENL
   [ASM_MESON_TAC[EBALG_IMP_PORDER]; ALL_TAC] THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`p:A`;`leq:A`;`a:A`;`b:A`]
         EBALG_MEET) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[];
    DISCH_THEN(X_CHOOSE_THEN `z:A` ASSUME_TAC)] THEN
  SUBGOAL_THEN `(z:A) IN D /\ (E:A->A->bool) z p` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[EMEET_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `(z:A) = a` SUBST_ALL_TAC THENL
   [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`p:A`;`leq:A`;`z:A`;`a:A`]
       EPORDER_ANTISYM) THEN
    ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
     [ASM_MESON_TAC[EMEET_LE];
      MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`p:A`;`leq:A`;
         `a:A`;`b:A`;`z:A`;`a:A`] EMEET_GREATEST) THEN
      ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[EPORDER_REFL]];
    FIRST_ASSUM ACCEPT_TAC]);;

(* ===================================================================== *)
(* PMEM_VAL_EQ / APPLY_VAL_EQ : collapse the opair-inner membership value *)
(* and the apply_form value to the SAME Kuratowski membership value mv =  *)
(* ebv_in(op,f), given the KURBUNDLE bundle for (arg,val) over f.  These  *)
(* are the two faces through which SVUNIFORM identifies bijform's         *)
(* apply_form single-valuedness with the opair-inner fn-form.             *)
(*   PMEM_VAL_EQ : [[?? 73(opair 70 71 73 && 73%%72)]]_V = mv  (V 70=arg,  *)
(*                 V 71=val, V 72=f).                                      *)
(*   APPLY_VAL_EQ: [[apply_form i j k]]_V = mv  (V i=f, V j=arg, V k=val). *)
(* Each is EPORDER_ANTISYM of the GE and LE companion.  REUSABLE.         *)
(* ===================================================================== *)

let PMEM_VAL_EQ = prove
 (`!D (E:A->A->bool) B leq V arg val f op sa sab top mv.
     model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
     valuation D V /\ (!k. bname D E B (V k)) /\
     V 70 = arg /\ V 71 = val /\ V 72 = f /\
     op IN D /\ bname D E B op /\ sa IN D /\ bname D E B sa /\
     sab IN D /\ bname D E B sab /\ top IN D /\ etop D E B leq top /\
     eapply D E sa arg top /\
     (!t q. t IN D /\ q IN D /\ eapply D E sa t q ==> t = arg \/ t = arg) /\
     eapply D E sab arg top /\ eapply D E sab val top /\
     (!t q. t IN D /\ q IN D /\ eapply D E sab t q ==> t = arg \/ t = val) /\
     eapply D E op sa top /\ eapply D E op sab top /\
     (!t q. t IN D /\ q IN D /\ eapply D E op t q ==> t = sa \/ t = sab) /\
     mv IN D /\ E mv B /\ ebv_in D E B leq op f mv
     ==> bvalf D E B leq V (?? 73 (opair_form 70 71 73 && (73 %% 72))) = mv`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `eporder D (E:A->A->bool) B leq` ASSUME_TAC THENL
   [ASM_MESON_TAC[ECBA_IMP_PORDER]; ALL_TAC] THEN
  SUBGOAL_THEN
   `(bvalf D E B leq V (?? 73 (opair_form 70 71 73 && (73 %% 72)))) IN D /\
    (E:A->A->bool)
      (bvalf D E B leq V (?? 73 (opair_form 70 71 73 && (73 %% 72)))) B`
   STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[BVALF_SPEC; BVALF_IN_B]; ALL_TAC] THEN
  SUBGOAL_THEN
   `erel D (E:A->A->bool) leq mv
    (bvalf D E B leq V (?? 73 (opair_form 70 71 73 && (73 %% 72))))`
   ASSUME_TAC THENL
   [MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`V:num->A`;
       `sa:A`;`sab:A`;`op:A`;`top:A`;`mv:A`] BVALF_PMEM_GE) THEN
    ANTS_TAC THENL
    [ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[]; DISCH_THEN ACCEPT_TAC];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `erel D (E:A->A->bool) leq
    (bvalf D E B leq V (?? 73 (opair_form 70 71 73 && (73 %% 72)))) mv`
   ASSUME_TAC THENL
   [MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`V:num->A`;
       `sa:A`;`sab:A`;`op:A`;`top:A`;`mv:A`] BVALF_PMEM_LE) THEN
    ANTS_TAC THENL
    [ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[]; DISCH_THEN ACCEPT_TAC];
    ALL_TAC] THEN
  MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`]
               EPORDER_ANTISYM) THEN
  ASM_REWRITE_TAC[]);;

let APPLY_VAL_EQ = prove
 (`!D (E:A->A->bool) B leq V i j k arg val f op sa sab top mv.
     model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
     valuation D V /\ (!m. bname D E B (V m)) /\
     V i = f /\ V j = arg /\ V k = val /\
     op IN D /\ bname D E B op /\ sa IN D /\ bname D E B sa /\
     sab IN D /\ bname D E B sab /\ top IN D /\ etop D E B leq top /\
     eapply D E sa arg top /\
     (!t q. t IN D /\ q IN D /\ eapply D E sa t q ==> t = arg \/ t = arg) /\
     eapply D E sab arg top /\ eapply D E sab val top /\
     (!t q. t IN D /\ q IN D /\ eapply D E sab t q ==> t = arg \/ t = val) /\
     eapply D E op sa top /\ eapply D E op sab top /\
     (!t q. t IN D /\ q IN D /\ eapply D E op t q ==> t = sa \/ t = sab) /\
     mv IN D /\ E mv B /\ ebv_in D E B leq op f mv
     ==> bvalf D E B leq V (apply_form i j k) = mv`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `eporder D (E:A->A->bool) B leq` ASSUME_TAC THENL
   [ASM_MESON_TAC[ECBA_IMP_PORDER]; ALL_TAC] THEN
  SUBGOAL_THEN
   `(bvalf D E B leq V (apply_form i j k)) IN D /\
    (E:A->A->bool)(bvalf D E B leq V (apply_form i j k)) B`
   STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[BVALF_SPEC; BVALF_IN_B]; ALL_TAC] THEN
  SUBGOAL_THEN
    `erel D (E:A->A->bool) leq mv (bvalf D E B leq V (apply_form i j k))`
   ASSUME_TAC THENL
   [MP_TAC(ISPECL
           [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`V:num->A`;`i:num`;
            `j:num`;`k:num`;
            `sa:A`;`sab:A`;`op:A`;`top:A`;`mv:A`] BVALF_APPLY_GE) THEN
    ANTS_TAC THENL
    [ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[]; DISCH_THEN ACCEPT_TAC];
    ALL_TAC] THEN
  SUBGOAL_THEN
    `erel D (E:A->A->bool) leq (bvalf D E B leq V (apply_form i j k)) mv`
   ASSUME_TAC THENL
   [MP_TAC(ISPECL
           [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`V:num->A`;`i:num`;
            `j:num`;`k:num`;
            `sa:A`;`sab:A`;`op:A`;`top:A`;`mv:A`] BVALF_APPLY_LE) THEN
    ANTS_TAC THENL
    [ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[]; DISCH_THEN ACCEPT_TAC];
    ALL_TAC] THEN
  MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`]
               EPORDER_ANTISYM) THEN
  ASM_REWRITE_TAC[]);;

(* ===================================================================== *)
(* SVUNIFORM : apply_form single-valuedness ==> the ??74 opair fn-form.    *)
(* Feeds the DOWN-route BIJFORM_CHECK_BOT ladder (A2bij-BOT).  REUSABLE.   *)
(* ===================================================================== *)
let SVUNIFORM = prove
 (`!D (E:A->A->bool) B leq f v c.
   model D E ZF_AX /\ (!u. u IN D ==> elmem D E u) /\
