                  `E:A->A->bool`;
                  `B:A`;`leq:A`;
                  `(6 |-> (Gn:A))
                   ((5 |-> (yy:A)) ((4 |-> (xx:A)) (v:num->A)))`]
         BVALF_AND_MEET) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `emeet D (E:A->A->bool) B leq mvY mvG mvY` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
                        `mvY:A`;`mvG:A`]
                 EMEET_ABSORB_LE) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN
    `bvalf D (E:A->A->bool) B leq ((6 |-> Gn) ((5 |-> yy) ((4 |-> xx) v)))
     (apply_form 3 4 5 && apply_form 3 4 6) = mvY`
   ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
                        `mvY:A`;`mvG:A`;
                        `bvalf D (E:A->A->bool) B leq
                         ((6 |-> (Gn:A))
                          ((5 |-> (yy:A)) ((4 |-> (xx:A)) (v:num->A))))
                         (apply_form 3 4 5 && apply_form 3 4 6)`;`mvY:A`]
      EMEET_UNIQUE) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN
    `ebv_eq D (E:A->A->bool) B leq yy Gn
     (bvalf D E B leq ((6 |-> Gn) ((5 |-> yy) ((4 |-> xx) v))) (Eq 5 6))`
   ASSUME_TAC THENL
   [MP_TAC(ISPECL[`5`;`6`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
                  `(6 |-> (Gn:A))
                   ((5 |-> (yy:A)) ((4 |-> (xx:A)) (v:num->A)))`]
           BVALF_EQ2) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN
    `(bvalf D (E:A->A->bool) B leq ((6 |-> Gn) ((5 |-> yy) ((4 |-> xx) v)))
      (Eq 5 6)) IN D /\
    E (bvalf D E B leq ((6 |-> Gn) ((5 |-> yy) ((4 |-> xx) v))) (Eq 5 6)) B`
      STRIP_ASSUME_TAC THENL
   [CONJ_TAC THENL [MATCH_MP_TAC BVALF_IND; MATCH_MP_TAC BVALF_IN_B] THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(bvalf D (E:A->A->bool) B leq w (Eq 71 74)) IN D /\
    E (bvalf D E B leq w (Eq 71 74)) B` STRIP_ASSUME_TAC THENL
   [CONJ_TAC THENL [MATCH_MP_TAC BVALF_IND; MATCH_MP_TAC BVALF_IN_B] THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN
    `(bvalf D (E:A->A->bool) B leq w
      ((?? 73 (opair_form 70 71 73 && (73 %% 72))) --> Eq 71 74)) IN D /\
    E (bvalf D E B leq w
       ((?? 73 (opair_form 70 71 73 && (73 %% 72))) --> Eq 71 74)) B`
      STRIP_ASSUME_TAC THENL
   [CONJ_TAC THENL [MATCH_MP_TAC BVALF_IND; MATCH_MP_TAC BVALF_IN_B] THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN
    `ebimp D (E:A->A->bool) B leq mvY
     (bvalf D E B leq ((6 |-> Gn) ((5 |-> yy) ((4 |-> xx) v))) (Eq 5 6))
      (bvalf D E B leq ((6 |-> Gn) ((5 |-> yy) ((4 |-> xx) v)))
       (apply_form 3 4 5 && apply_form 3 4 6 --> Eq 5 6))` ASSUME_TAC THENL
   [MP_TAC(ISPECL[`apply_form 3 4 5 && apply_form 3 4 6`;`Eq 5 6`;
       `D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
       `(6 |-> (Gn:A)) ((5 |-> (yy:A)) ((4 |-> (xx:A)) (v:num->A)))`]
         BVALF_IMP) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `ebimp D (E:A->A->bool) B leq mvY (bvalf D E B leq w (Eq 71 74))
      (bvalf D E B leq w
       ((?? 73 (opair_form 70 71 73 && (73 %% 72))) --> Eq 71 74))`
    ASSUME_TAC THENL
   [MP_TAC(ISPECL[`?? 73 (opair_form 70 71 73 && (73 %% 72))`;`Eq 71 74`;
                  `D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`w:num->A`]
           BVALF_IMP) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN
    `ebv_eq D (E:A->A->bool) B leq yy Gn (bvalf D E B leq w (Eq 71 74))`
   ASSUME_TAC THENL
   [MP_TAC(ISPECL[`71`;`74`;`D:A->bool`;`E:A->A->bool`;`B:A`;
                  `leq:A`;`w:num->A`]
           BVALF_EQ2) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN
    `bvalf D (E:A->A->bool) B leq ((6 |-> Gn) ((5 |-> yy) ((4 |-> xx) v)))
     (Eq 5 6) = bvalf D E B leq w (Eq 71 74)`
   ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`yy:A`;`Gn:A`;
       `bvalf D (E:A->A->bool) B leq
        ((6 |-> (Gn:A)) ((5 |-> (yy:A)) ((4 |-> (xx:A)) (v:num->A))))
        (Eq 5 6)`;`bvalf D (E:A->A->bool) B leq w (Eq 71 74)`]
      EBV_EQ_UNIQUE) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`c:A`;`mvY:A`]
         EBALG_MEET) THEN
  ANTS_TAC THENL
  [ASM_REWRITE_TAC[]; DISCH_THEN(X_CHOOSE_THEN `m:A` ASSUME_TAC)] THEN
  SUBGOAL_THEN
    `erel D (E:A->A->bool) leq m
     (bvalf D E B leq ((6 |-> Gn) ((5 |-> yy) ((4 |-> xx) v))) (Eq 5 6))`
   (LABEL_TAC "res1") THENL
   [MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`c:A`;`mvY:A`;
       `bvalf D (E:A->A->bool) B leq
        ((6 |-> (Gn:A))
         ((5 |-> (yy:A)) ((4 |-> (xx:A)) (v:num->A)))) (Eq 5 6)`;
       `bvalf D (E:A->A->bool) B leq
        ((6 |-> (Gn:A)) ((5 |-> (yy:A)) ((4 |-> (xx:A)) (v:num->A))))
        (apply_form 3 4 5 && apply_form 3 4 6 --> Eq 5 6)`;`m:A`]
        EBIMP_MEET_LE) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN
    `bvalf D (E:A->A->bool) B leq ((6 |-> Gn) ((5 |-> yy) ((4 |-> xx) v)))
     (Eq 5 6) = bvalf D E B leq w (Eq 71 74)`
   (LABEL_TAC "eqeq2") THENL
   [MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`yy:A`;`Gn:A`;
       `bvalf D (E:A->A->bool) B leq
        ((6 |-> (Gn:A))
         ((5 |-> (yy:A)) ((4 |-> (xx:A)) (v:num->A)))) (Eq 5 6)`;
       `bvalf D (E:A->A->bool) B leq w (Eq 71 74)`] EBV_EQ_UNIQUE) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq m (bvalf D E B leq w (Eq 71 74))`
    ASSUME_TAC THENL
   [USE_THEN "eqeq2"
    (fun th -> USE_THEN "res1" (fun r -> ACCEPT_TAC(SUBS[th] r)));
    ALL_TAC] THEN
  MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`c:A`;`mvY:A`;
     `bvalf D (E:A->A->bool) B leq w (Eq 71 74)`;
     `bvalf D (E:A->A->bool) B leq w
      ((?? 73 (opair_form 70 71 73 && (73 %% 72))) --> Eq 71 74)`;`m:A`]
      EBIMP_LE_IMP) THEN
  ASM_REWRITE_TAC[]);;

(* ===================================================================== *)
(* A2bij-BOT countable no-onto ladder (DOWN route).                      *)
(* Thin countable mirrors of the _GEN no-surjection ladder, with a named *)
(* injection iota: d >-> om replacing the (cardinal dm, E om dm) hyp.     *)
(*   EUNCOUNTABLE_FIBER_COUNTABLE  <- EUNCOUNTABLE_FIBER               *)
(*   COVER_ABSTRACT_COUNTABLE      <- COVER_ABSTRACT                   *)
(*   NO_SURJ_NAME_COUNTABLE        <- NO_SURJ_NAME                     *)
(*   NO_ONTO_FUNC_NAME_COUNTABLE   <- NO_ONTO_FUNC_NAME                *)
(* ===================================================================== *)
(* ================= EUNCOUNTABLE_FIBER_COUNTABLE =================
   Mirror of EUNCOUNTABLE_FIBER with (index lam -> d, target om).
   Index d: an ordinal with a named injection iota: d >-> om (countable).
   Fibers inject into om directly (kk=om) so NO EINJ_WEAKEN. *)
let EUNCOUNTABLE_FIBER_COUNTABLE = prove
 (`!D (E:A->A->bool) om d iota g X.
     model D E ZF_AX /\ (!u. u IN D ==> elmem D E u) /\
     eomega D E om /\ eordinal D E d /\ einj D E iota d om /\ d IN D /\
     X IN D /\ g IN D /\
     ~(?e. einj D E e X om) /\
     (!m. m IN D /\ E m X ==> ?n. n IN D /\ E n d /\ eapply D E g m n)
     ==> ?n W. n IN D /\ E n d /\ W IN D /\
               (!m. m IN D ==> (E m W <=> E m X /\ eapply D E g m n)) /\
               ~(?e. einj D E e W om)`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "zf lm omom dord eainj dD XD gD noinj gtot" THEN
  SUBGOAL_THEN `(om:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[EOMEGA_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `eordinal D (E:A->A->bool) om` (LABEL_TAC "omord") THENL
   [ASM_MESON_TAC[EOMEGA_ORDINAL]; ALL_TAC] THEN
  SUBGOAL_THEN `ecardinal D (E:A->A->bool) om` (LABEL_TAC "omcard") THENL
   [REWRITE_TAC[ecardinal] THEN MATCH_MP_TAC EOMEGA_CARDINAL THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* --- valuation vv with vv 5 = g, vv 6 = X --- *)
  ABBREV_TAC `vv = (5 |-> (g:A))((6 |-> (X:A))(\n:num. X))` THEN
  SUBGOAL_THEN `valuation D (vv:num->A)` ASSUME_TAC THENL
   [EXPAND_TAC "vv" THEN
    REPEAT(MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[]) THEN
    REWRITE_TAC[valuation] THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(vv:num->A) 5 = g /\ (vv:num->A) 6 = X`
   (CONJUNCTS_THEN2 (LABEL_TAC "v5") (LABEL_TAC "v6")) THENL
   [EXPAND_TAC "vv" THEN REWRITE_TAC[VALMOD] THEN
    CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN REWRITE_TAC[]; ALL_TAC] THEN
  (* --- ff = fiber family over d via ESFIB_FAMILY --- *)
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `vv:num->A`; `d:A`]
         ESFIB_FAMILY) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  INTRO_TAC "@ff. ffD ffmem sv perb" THEN
  (* --- wun = union of ff-values via EFAM_WUN (index d) --- *)
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `d:A`; `ff:A`] EFAM_WUN) THEN
  ANTS_TAC THENL
   [CONJ_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    CONJ_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    CONJ_TAC THENL [USE_THEN "ffD" ACCEPT_TAC; ALL_TAC] THEN
    X_GEN_TAC `p:A` THEN STRIP_TAC THEN
    USE_THEN "ffmem" (fun th -> MP_TAC(SPEC `p:A` th)) THEN
    ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN(fun iff -> FIRST_ASSUM(fun eff -> MP_TAC(EQ_MP iff eff))) THEN
    DISCH_THEN(X_CHOOSE_THEN `u:A` (CONJUNCTS_THEN2 ASSUME_TAC
      (CONJUNCTS_THEN2 (LABEL_TAC "euom") (LABEL_TAC "hp")))) THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `vv:num->A`; `u:A`; `p:A`]
      HOLDS_SFIB) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> USE_THEN "hp" (fun h -> MP_TAC(EQ_MP th h))) THEN
    DISCH_THEN(X_CHOOSE_THEN `W:A` (CONJUNCTS_THEN2 (LABEL_TAC "WD")
      (CONJUNCTS_THEN2 (LABEL_TAC "Wchar") (LABEL_TAC "eop")))) THEN
    MAP_EVERY EXISTS_TAC [`u:A`; `W:A`] THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `wun:A` (CONJUNCTS_THEN2 (LABEL_TAC "wunD")
    (LABEL_TAC "wunmem"))) THEN
  (* --- wun = X by extensionality --- *)
  SUBGOAL_THEN `wun:A = X` SUBST_ALL_TAC THENL
   [FIRST_ASSUM(fun mth -> MATCH_MP_TAC(MATCH_MP ZF_EXTENSIONALITY mth)) THEN
    ASM_REWRITE_TAC[] THEN X_GEN_TAC `t:A` THEN DISCH_TAC THEN
    USE_THEN "wunmem" (fun th -> MP_TAC(SPEC `t:A` th)) THEN
    ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN EQ_TAC THENL
     [DISCH_THEN(X_CHOOSE_THEN `b:A`
                 (X_CHOOSE_THEN `z:A` STRIP_ASSUME_TAC)) THEN
      USE_THEN "perb" (fun th -> MP_TAC(SPEC `b:A` th)) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(X_CHOOSE_THEN `Wb:A` (CONJUNCTS_THEN2 (LABEL_TAC "WbD")
        (CONJUNCTS_THEN2 (LABEL_TAC "Wbchar") (LABEL_TAC "ffbWb")))) THEN
      SUBGOAL_THEN `(z:A) = Wb` SUBST_ALL_TAC THENL
       [USE_THEN "sv" (MP_TAC o SPECL [`b:A`; `z:A`; `Wb:A`]) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC];
        ALL_TAC] THEN
      USE_THEN "Wbchar" (fun th -> MP_TAC(SPEC `t:A` th)) THEN
      ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
      USE_THEN "v6" (fun th -> REWRITE_TAC[th]) THEN ASM_MESON_TAC[];
      DISCH_TAC THEN
      USE_THEN "gtot" (fun th -> MP_TAC(SPEC `t:A` th)) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(X_CHOOSE_THEN `n:A` STRIP_ASSUME_TAC) THEN
      USE_THEN "perb" (fun th -> MP_TAC(SPEC `n:A` th)) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(X_CHOOSE_THEN `Wn:A` (CONJUNCTS_THEN2 (LABEL_TAC "WnD")
        (CONJUNCTS_THEN2 (LABEL_TAC "Wnchar") (LABEL_TAC "ffnWn")))) THEN
      MAP_EVERY EXISTS_TAC [`n:A`; `Wn:A`] THEN ASM_REWRITE_TAC[] THEN
      USE_THEN "Wnchar" (fun th -> MP_TAC(SPEC `t:A` th)) THEN
      ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
      USE_THEN "v6"
        (fun t6 -> USE_THEN "v5" (fun t5 -> REWRITE_TAC[t6; t5])) THEN
        ASM_MESON_TAC[]];
    ALL_TAC] THEN
  (* --- contradiction: if every fiber injects into om, X injects into om *)
  (* --- *)
  MATCH_MP_TAC(TAUT `(~P ==> F) ==> P`) THEN
  DISCH_THEN(MP_TAC o REWRITE_RULE[NOT_EXISTS_THM;
    TAUT `~(a /\ b /\ c /\ d /\ ~e) <=> (a /\ b /\ c /\ d ==> e)`]) THEN
  DISCH_THEN(LABEL_TAC "allcnt") THEN
  (* --- per-b clause for EGEN_UNION_CARD_LE (fiber >-> om = kk directly) *)
  (* --- *)
  SUBGOAL_THEN
   `!b:A. b IN D /\ E b d
      ==> ?z. z IN D /\ eapply D E ff b z /\
              (!u. u IN D /\ E u z ==> E u X) /\
              (?e. e IN D /\ einj D (E:A->A->bool) e z om)`
   (LABEL_TAC "egenperb") THENL
   [X_GEN_TAC `b:A` THEN STRIP_TAC THEN
    USE_THEN "perb" (fun th -> MP_TAC(SPEC `b:A` th)) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(X_CHOOSE_THEN `Wb:A` (CONJUNCTS_THEN2 (LABEL_TAC "WbD")
      (CONJUNCTS_THEN2 (LABEL_TAC "Wbchar") (LABEL_TAC "ffbWb")))) THEN
    EXISTS_TAC `Wb:A` THEN ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
     [X_GEN_TAC `u:A` THEN STRIP_TAC THEN
      USE_THEN "Wbchar" (fun th -> MP_TAC(SPEC `u:A` th)) THEN
      ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
      USE_THEN "v6" (fun th -> REWRITE_TAC[th]) THEN ASM_MESON_TAC[];
      USE_THEN "allcnt" (MP_TAC o SPECL [`b:A`; `Wb:A`]) THEN
      ANTS_TAC THENL
       [ASM_REWRITE_TAC[] THEN X_GEN_TAC `m:A` THEN DISCH_TAC THEN
        USE_THEN "Wbchar" (fun th -> MP_TAC(SPEC `m:A` th)) THEN
        ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
        USE_THEN "v6" (fun t6 -> USE_THEN "v5" (fun t5 ->
          REWRITE_TAC[t6; t5]));
        DISCH_THEN(X_CHOOSE_THEN `einjw:A` ASSUME_TAC) THEN
        EXISTS_TAC `einjw:A` THEN CONJ_TAC THENL
         [ACCEPT_TAC(CONJUNCT1(REWRITE_RULE[einj] (ASSUME
            `einj D (E:A->A->bool) einjw Wb om`)));
          FIRST_ASSUM ACCEPT_TAC]]];
    ALL_TAC] THEN
  (* --- apply EGEN_UNION_CARD_LE (a=d, kk=om, ea=iota, ya=X, wun=X) --- *)
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `om:A`; `d:A`; `om:A`;
     `iota:A`; `X:A`; `ff:A`; `X:A`] EGEN_UNION_CARD_LE) THEN
  ANTS_TAC THENL
   [CONJ_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    CONJ_TAC THENL [USE_THEN "lm" ACCEPT_TAC; ALL_TAC] THEN
    CONJ_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    CONJ_TAC THENL [USE_THEN "omcard" ACCEPT_TAC; ALL_TAC] THEN
    CONJ_TAC THENL [DISJ2_TAC THEN REFL_TAC; ALL_TAC] THEN
    CONJ_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    CONJ_TAC THENL [USE_THEN "dord" ACCEPT_TAC; ALL_TAC] THEN
    CONJ_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    CONJ_TAC THENL [USE_THEN "eainj" ACCEPT_TAC; ALL_TAC] THEN
    CONJ_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    CONJ_TAC THENL [USE_THEN "ffD" ACCEPT_TAC; ALL_TAC] THEN
    CONJ_TAC THENL [USE_THEN "sv" ACCEPT_TAC; ALL_TAC] THEN
    CONJ_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    CONJ_TAC THENL [USE_THEN "wunmem" ACCEPT_TAC; ALL_TAC] THEN
    USE_THEN "egenperb" ACCEPT_TAC;
    ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_TAC `e0:A`) THEN
  UNDISCH_TAC `~(?e:A. einj D (E:A->A->bool) e X om)` THEN
  ASM_MESON_TAC[]);;

(* ================= COVER_ABSTRACT_COUNTABLE =================
   Mirror of COVER_ABSTRACT with (om lam -> om d), named iota. *)
let COVER_ABSTRACT_COUNTABLE = prove
 (`!D (E:A->A->bool) om d iota a1 gg.
     model D E ZF_AX /\ (!u. u IN D ==> elmem D E u) /\
     eomega D E om /\ eordinal D E d /\ einj D E iota d om /\ d IN D /\
     a1 IN D /\ gg IN D /\
     ~(?e. einj D E e a1 om) /\
     (!bet. bet IN D /\ E bet a1
            ==> ?n. n IN D /\ E n d /\ eapply D E gg bet n) /\
     (!n. n IN D /\ E n d
          ==> ?Wn e. Wn IN D /\
                     (!u. u IN D ==>
                      (E u Wn <=> E u a1 /\ eapply D E gg u n)) /\
                     einj D E e Wn om)
     ==> F`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  MP_TAC(ISPECL
         [`D:A->bool`; `E:A->A->bool`; `om:A`; `d:A`; `iota:A`; `gg:A`; `a1:A`]
         EUNCOUNTABLE_FIBER_COUNTABLE) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `n:A` (X_CHOOSE_THEN `W:A` STRIP_ASSUME_TAC)) THEN
  SUBGOAL_THEN
   `?Wn e. Wn IN D /\
           (!u. u IN D ==>
            (E u Wn <=> E u a1 /\ eapply D (E:A->A->bool) gg u n)) /\
           einj D E e Wn om`
  STRIP_ASSUME_TAC THENL
   [FIRST_X_ASSUM MATCH_MP_TAC THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(W:A) = Wn` SUBST_ALL_TAC THENL
   [FIRST_ASSUM(MP_TAC o MATCH_MP ZF_EXTENSIONALITY) THEN
    DISCH_THEN MATCH_MP_TAC THEN ASM_REWRITE_TAC[] THEN
    X_GEN_TAC `z:A` THEN DISCH_TAC THEN ASM_MESON_TAC[]; ALL_TAC] THEN
  UNDISCH_TAC `~(?e. einj D (E:A->A->bool) e Wn om)` THEN
  REWRITE_TAC[] THEN EXISTS_TAC `e:A` THEN FIRST_ASSUM ACCEPT_TAC);;

(* ================= NO_SURJ_NAME_COUNTABLE =================
   Mirror of NO_SURJ_NAME.  dm is now a COUNTABLE ordinal (eordinal dm
   + named injection iota: dm >-> om), a1 is uncountable (~inj a1 om).  Body
   VERBATIM except: (hyp) ecardinal dm /\ E om dm -> eordinal dm /\
     einj iota dm om,
   and ~inj(a1,dm) -> ~inj(a1,om);
   (final) COVER_ABSTRACT -> COVER_ABSTRACT_COUNTABLE
   with iota threaded. *)
let NO_SURJ_NAME_COUNTABLE = prove
 (`!D (E:A->A->bool) P leqp B inclB bp onebee a1 om dm iota f b0.
     model D E ZF_AX /\ eleqp D E P leqp /\ eroset D E P leqp B /\
     eincl D E B inclB /\ ebplus D E B bp /\ ecba D E B inclB /\
     eccc D E bp inclB /\ B IN D /\
     (!u. u IN D ==> elmem D E u) /\
     onebee IN D /\ E onebee B /\ etop D E B inclB onebee /\
     a1 IN D /\ eomega D E om /\
     eordinal D E dm /\ einj D E iota dm om /\ dm IN D /\
       ~(?e. einj D E e a1 om) /\
     f IN D /\ bname D E B f /\ b0 IN D /\ E b0 B /\
     (!v. valuation D v /\ (!i. bname D E B (v i)) /\ v 72 = f
          ==> erel D E inclB b0 (bvalf D E B inclB v
                (?? 74 (!! 71
                        ((?? 73 (opair_form 70 71 73 && (73 %% 72))) -->
                         Eq 71 74))))) /\
     (!bet. bet IN D /\ E bet a1
            ==> ?n pnb ckp mv dd. n IN D /\ E n dm /\ pnb IN D /\ ckp IN D /\
                   mv IN D /\ dd IN D /\
                   eopair D E n bet pnb /\ echeck D E onebee pnb ckp /\
                   ebv_in D E B inclB ckp f mv /\ emeet D E B inclB b0 mv dd /\
                   ~ebot D E B inclB dd)
     ==> F`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `(inclB:A) IN D /\ (bp:A) IN D` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[eincl; ebplus]; ALL_TAC] THEN
  SUBGOAL_THEN `(om:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[eomega; einductive]; ALL_TAC] THEN
  (* gg = membership collapse relation *)
  MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `a1:A`; `dm:A`; `B:A`; `inclB:A`;
    `f:A`; `b0:A`; `onebee:A`] EMEMCOLLAPSE_EXISTS) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `gg:A`
             (CONJUNCTS_THEN2 ASSUME_TAC (LABEL_TAC "gg"))) THEN
  (* app-char *)
  SUBGOAL_THEN
   `!u k. u IN D /\ k IN D
          ==> (eapply D (E:A->A->bool) gg u k <=>
               E u a1 /\ E k dm /\
               ?pnb ckp mv dd. pnb IN D /\ ckp IN D /\ mv IN D /\ dd IN D /\
                  eopair D E k u pnb /\ echeck D E onebee pnb ckp /\
                  ebv_in D E B inclB ckp f mv /\ emeet D E B inclB b0 mv dd /\
                  ~ebot D E B inclB dd)`
  (LABEL_TAC "app") THENL
   [REPEAT GEN_TAC THEN STRIP_TAC THEN
    GEN_REWRITE_TAC LAND_CONV [eapply] THEN EQ_TAC THENL
     [DISCH_THEN(X_CHOOSE_THEN `q:A` STRIP_ASSUME_TAC) THEN
      USE_THEN "gg" (MP_TAC o SPEC `q:A`) THEN
      ANTS_TAC THENL [ASM_MESON_TAC[EOPAIR_IN]; ALL_TAC] THEN
      DISCH_THEN(fun bic ->
                 MP_TAC(EQ_MP bic (ASSUME `(E:A->A->bool) q gg`))) THEN
      DISCH_THEN(X_CHOOSE_THEN `bet:A` (X_CHOOSE_THEN `nn:A`
        (X_CHOOSE_THEN `pnb:A` (X_CHOOSE_THEN `ckp:A`
          (X_CHOOSE_THEN `mv:A`
           (X_CHOOSE_THEN `dd:A` STRIP_ASSUME_TAC)))))) THEN
      MP_TAC(ISPECL
             [`D:A->bool`; `E:A->A->bool`; `bet:A`; `nn:A`; `u:A`; `k:A`;
              `q:A`] EOPAIR_INJ) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(CONJUNCTS_THEN(SUBST_ALL_TAC o SYM)) THEN
      ASM_REWRITE_TAC[] THEN
      MAP_EVERY EXISTS_TAC [`pnb:A`; `ckp:A`; `mv:A`; `dd:A`] THEN
      ASM_REWRITE_TAC[];
      STRIP_TAC THEN
      MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `u:A`; `k:A`]
             EOPAIR_EXISTS) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(X_CHOOSE_THEN `q:A` ASSUME_TAC) THEN
      EXISTS_TAC `q:A` THEN ASM_REWRITE_TAC[] THEN
      USE_THEN "gg" (MP_TAC o SPEC `q:A`) THEN
      ANTS_TAC THENL [ASM_MESON_TAC[EOPAIR_IN]; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
      MAP_EVERY EXISTS_TAC
        [`u:A`; `k:A`; `pnb:A`; `ckp:A`; `mv:A`; `dd:A`] THEN
        ASM_REWRITE_TAC[]];
    ALL_TAC] THEN
  (* totality from covering *)
  SUBGOAL_THEN
   `!bet. bet IN D /\ E bet a1
          ==> ?n. n IN D /\ E n dm /\ eapply D (E:A->A->bool) gg bet n`
  ASSUME_TAC THENL
   [X_GEN_TAC `bt:A` THEN STRIP_TAC THEN
    SUBGOAL_THEN
     `?n pnb ckp mv dd. n IN D /\ E n dm /\ pnb IN D /\ ckp IN D /\
         mv IN D /\ dd IN D /\
         eopair D (E:A->A->bool) n bt pnb /\ echeck D E onebee pnb ckp /\
         ebv_in D E B inclB ckp f mv /\ emeet D E B inclB b0 mv dd /\
         ~ebot D E B inclB dd`
    STRIP_ASSUME_TAC THENL
     [FIRST_X_ASSUM MATCH_MP_TAC THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    EXISTS_TAC `n:A` THEN ASM_REWRITE_TAC[] THEN
    USE_THEN "app" (MP_TAC o SPECL [`bt:A`; `n:A`]) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN ASM_REWRITE_TAC[] THEN
    MAP_EVERY EXISTS_TAC [`pnb:A`; `ckp:A`; `mv:A`; `dd:A`] THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  (* per-n fibre via MEM_FIBRE_INJ *)
  SUBGOAL_THEN
   `!n. n IN D /\ E n dm
        ==> ?Wn e. Wn IN D /\
                   (!u. u IN D ==>
                    (E u Wn <=> E u a1 /\ eapply D (E:A->A->bool) gg u n)) /\
                   einj D E e Wn om`
  ASSUME_TAC THENL
   [X_GEN_TAC `n:A` THEN STRIP_TAC THEN
    MATCH_MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `P:A`; `leqp:A`; `B:A`;
      `inclB:A`; `bp:A`; `onebee:A`; `a1:A`; `om:A`; `dm:A`; `f:A`; `b0:A`;
      `gg:A`; `n:A`]
      MEM_FIBRE_INJ) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  MP_TAC(ISPECL
         [`D:A->bool`; `E:A->A->bool`; `om:A`; `dm:A`; `iota:A`;
          `a1:A`; `gg:A`]
         COVER_ABSTRACT_COUNTABLE) THEN
  ASM_REWRITE_TAC[]);;

(* ================= NO_ONTO_FUNC_NAME_COUNTABLE =================
   Mirror of NO_ONTO_FUNC_NAME.  Same countable hyp swap; final
   NO_SURJ_NAME -> NO_SURJ_NAME_COUNTABLE (iota threaded). *)
let NO_ONTO_FUNC_NAME_COUNTABLE = prove
 (`!D (E:A->A->bool) P leqp B inclB bp onebee a1 a1c om dm dmc iota f b0 v0.
      model D E ZF_AX /\ eleqp D E P leqp /\ eroset D E P leqp B /\
      eincl D E B inclB /\ ebplus D E B bp /\ ecba D E B inclB /\
      eccc D E bp inclB /\ B IN D /\
      (!u. u IN D ==> elmem D E u) /\
      onebee IN D /\ E onebee B /\ etop D E B inclB onebee /\
      a1 IN D /\ eomega D E om /\
      eordinal D E dm /\ einj D E iota dm om /\ dm IN D /\
        ~(?e. einj D E e a1 om) /\
      echeck D E onebee a1 a1c /\ echeck D E onebee dm dmc /\
      f IN D /\ bname D E B f /\ b0 IN D /\ E b0 B /\ ~ebot D E B inclB b0 /\
      valuation D v0 /\ (!i. bname D E B (v0 i)) /\
      v0 68 = a1c /\ v0 69 = dmc /\ v0 72 = f /\
      erel D E inclB b0 (bvalf D E B inclB v0
         (!! 70 (?? 74
                 (!! 71 ((?? 73 (opair_form 70 71 73 && (73 %% 72))) -->
                         Eq 71 74))))) /\
      erel D E inclB b0 (bvalf D E B inclB v0
         (!!- 71 68 (??- 70 69 (?? 73 (opair_form 70 71 73 && (73 %% 72))))))
      ==> F`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `(om:A) IN D /\ (inclB:A) IN D` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[eomega; einductive; eincl]; ALL_TAC] THEN
  (* functionality clause via MEMVAL_FUNC_UNIFORM *)
  MP_TAC(ISPECL
         [`D:A->bool`;`E:A->A->bool`;`B:A`;`inclB:A`;`v0:num->A`;`f:A`;`b0:A`]
         MEMVAL_FUNC_UNIFORM) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN DISCH_TAC THEN
  (* covering clause via M5_COVER *)
  MP_TAC(ISPECL
         [`D:A->bool`;`E:A->A->bool`;`B:A`;`inclB:A`;`onebee:A`;`a1:A`;`a1c:A`;
          `dm:A`;`dmc:A`;`f:A`;`b0:A`;`v0:num->A`] M5_COVER) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN DISCH_TAC THEN
  (* NO_SURJ_NAME_COUNTABLE closes it *)
  MP_TAC(ISPECL
         [`D:A->bool`;`E:A->A->bool`;`P:A`;`leqp:A`;`B:A`;`inclB:A`;`bp:A`;
          `onebee:A`;`a1:A`;`om:A`;`dm:A`;`iota:A`;`f:A`;`b0:A`]
           NO_SURJ_NAME_COUNTABLE) THEN
  ASM_REWRITE_TAC[]);;

(* ===================================================================== *)
(* ONTOUNIFORM : the onto analog of SVUNIFORM.  From the bijform onto     *)
(* conjunct [[!! 5 (5%%1 --> ?? 4 (4%%2 && apply_form 3 4 5))]] (above c)  *)
(* derive the NO_ONTO opair onto-form                                      *)
(* [[!!- 71 68 (??- 70 69 (?? 73 (opair_form 70 71 73 && 73%%72)))]].      *)
(* Codomain slot 1=68, domain slot 2=69, function slot 3=72=f.  Mirrors    *)
(* SVUNIFORM but is forall-exists (no single-valuedness), hence simpler.   *)
(* Feeds BIJFORM_CHECK_BOT (A2bij-BOT).  REUSABLE.                         *)
(* ===================================================================== *)
let ONTOUNIFORM = prove
 (`!D (E:A->A->bool) B leq f v c.
   model D E ZF_AX /\ (!u. u IN D ==> elmem D E u) /\
   ecba D E B leq /\ B IN D /\ leq IN D /\
   f IN D /\ bname D E B f /\ c IN D /\ E c B /\
   valuation D v /\ (!k. bname D E B (v k)) /\
   v 1 = v 68 /\ v 2 = v 69 /\ v 3 = f /\ v 72 = f /\
   erel D E leq c
     (bvalf D E B leq v
       (!! 5 (5 %% 1 --> ?? 4 (4 %% 2 && apply_form 3 4 5))))
   ==> erel D E leq c
     (bvalf D E B leq v
       (!!- 71 68 (??- 70 69 (?? 73 (opair_form 70 71 73 && (73 %% 72))))))`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `ebalg D (E:A->A->bool) B leq /\ eporder D E B leq`
    STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[ECBA_IMP_BALG; EBALG_IMP_PORDER]; ALL_TAC] THEN
  SUBGOAL_THEN `(v:num->A) 68 IN D /\ (v:num->A) 2 IN D /\ (v:num->A) 69 IN D`
    STRIP_ASSUME_TAC THENL [ASM_MESON_TAC[valuation]; ALL_TAC] THEN
  REWRITE_TAC[Forallmem_DEF; Existsmem_DEF] THEN
  MATCH_MP_TAC BVALF_ALL_GLB THEN ASM_REWRITE_TAC[] THEN
  X_GEN_TAC `yy:A` THEN STRIP_TAC THEN
  SUBGOAL_THEN `(yy:A) IN D` ASSUME_TAC THENL [ASM_MESON_TAC[]; ALL_TAC] THEN
  ABBREV_TAC `w1 = (71 |-> (yy:A)) v` THEN
  SUBGOAL_THEN
    `valuation D (w1:num->A) /\ (!k. bname D (E:A->A->bool) B (w1 k))`
    STRIP_ASSUME_TAC THENL
   [EXPAND_TAC "w1" THEN CONJ_TAC THENL
     [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[];
      MATCH_MP_TAC BNAMEVAL_VALMOD THEN ASM_REWRITE_TAC[]]; ALL_TAC] THEN
  SUBGOAL_THEN `(w1:num->A) 71 = yy /\ (w1:num->A) 68 = v 68 /\
                (w1:num->A) 69 = v 69 /\ (w1:num->A) 72 = f`
    STRIP_ASSUME_TAC THENL
   [EXPAND_TAC "w1" THEN SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER; ARITH_EQ] THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `valuation D ((5 |-> (yy:A)) v) /\
                (!k. bname D (E:A->A->bool) B (((5 |-> (yy:A)) v) k))`
    STRIP_ASSUME_TAC THENL
   [CONJ_TAC THENL
     [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[];
      MATCH_MP_TAC BNAMEVAL_VALMOD THEN ASM_REWRITE_TAC[]]; ALL_TAC] THEN
  (* --- memberships of the recurring value-terms --- *)
  SUBGOAL_THEN `(bvalf D (E:A->A->bool) B leq w1 (71 %% 68)) IN D /\
                E (bvalf D E B leq w1 (71 %% 68)) B`
    STRIP_ASSUME_TAC THENL
   [CONJ_TAC THENL [MATCH_MP_TAC BVALF_IND; MATCH_MP_TAC BVALF_IN_B] THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(bvalf D (E:A->A->bool) B leq ((5 |-> yy) v) (5 %% 1)) IN D /\
                E (bvalf D E B leq ((5 |-> yy) v) (5 %% 1)) B`
    STRIP_ASSUME_TAC THENL
   [CONJ_TAC THENL [MATCH_MP_TAC BVALF_IND; MATCH_MP_TAC BVALF_IN_B] THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN
   `(bvalf D (E:A->A->bool) B leq ((5 |-> yy) v)
     (?? 4 (4 %% 2 && apply_form 3 4 5))) IN D /\
    E (bvalf D E B leq ((5 |-> yy) v) (?? 4 (4 %% 2 && apply_form 3 4 5))) B`
    STRIP_ASSUME_TAC THENL
   [CONJ_TAC THENL [MATCH_MP_TAC BVALF_IND; MATCH_MP_TAC BVALF_IN_B] THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN
   `(bvalf D (E:A->A->bool) B leq w1
       (?? 70 ((70 %% 69) &&
               (?? 73 (opair_form 70 71 73 && (73 %% 72)))))) IN D /\
    E (bvalf D E B leq w1
       (?? 70 ((70 %% 69) && (?? 73 (opair_form 70 71 73 && (73 %% 72)))))) B`
    STRIP_ASSUME_TAC THENL
   [CONJ_TAC THENL [MATCH_MP_TAC BVALF_IND; MATCH_MP_TAC BVALF_IN_B] THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN
   `(bvalf D (E:A->A->bool) B leq v
       (!! 5 (5 %% 1 --> ?? 4 (4 %% 2 && apply_form 3 4 5)))) IN D /\
    E (bvalf D E B leq v
       (!! 5 (5 %% 1 --> ?? 4 (4 %% 2 && apply_form 3 4 5)))) B`
    STRIP_ASSUME_TAC THENL
   [CONJ_TAC THENL [MATCH_MP_TAC BVALF_IND; MATCH_MP_TAC BVALF_IN_B] THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN
   `(bvalf D (E:A->A->bool) B leq ((5 |-> yy) v)
       (5 %% 1 --> ?? 4 (4 %% 2 && apply_form 3 4 5))) IN D /\
    E (bvalf D E B leq ((5 |-> yy) v)
       (5 %% 1 --> ?? 4 (4 %% 2 && apply_form 3 4 5))) B`
    STRIP_ASSUME_TAC THENL
   [CONJ_TAC THENL [MATCH_MP_TAC BVALF_IND; MATCH_MP_TAC BVALF_IN_B] THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* --- pm = [[71%%68]]_w1 = ebv_in yy (v 68) --- *)
  SUBGOAL_THEN
    `ebv_in D (E:A->A->bool) B leq yy (v 68) (bvalf D E B leq w1 (71 %% 68))`
    ASSUME_TAC THENL
   [SUBGOAL_THEN `yy:A = (w1:num->A) 71 /\ (v:num->A) 68 = (w1:num->A) 68`
      (CONJUNCTS_THEN SUBST1_TAC) THENL
     [ASM_REWRITE_TAC[];
      MATCH_MP_TAC BVALF_MEM THEN ASM_REWRITE_TAC[]]; ALL_TAC] THEN
  (* --- pm1 = [[5%%1]]_s1 = ebv_in yy (v 68) --- *)
  SUBGOAL_THEN `ebv_in D (E:A->A->bool) B leq yy (v 68)
                  (bvalf D E B leq ((5 |-> yy) v) (5 %% 1))` ASSUME_TAC THENL
   [SUBGOAL_THEN `ebv_in D (E:A->A->bool) B leq
        (((5 |-> (yy:A)) v) 5) (((5 |-> (yy:A)) v) 1)
        (bvalf D E B leq ((5 |-> yy) v) (5 %% 1))` MP_TAC THENL
     [MATCH_MP_TAC BVALF_MEM THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN `((5 |-> (yy:A)) v) 5 = yy /\ ((5 |-> (yy:A)) v) 1 = v 68`
      (CONJUNCTS_THEN SUBST1_TAC) THENL
     [SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER; ARITH_EQ] THEN ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    DISCH_THEN ACCEPT_TAC; ALL_TAC] THEN
  (* --- PMEQ : pm1 = pm --- *)
  SUBGOAL_THEN `bvalf D (E:A->A->bool) B leq ((5 |-> yy) v) (5 %% 1) =
                bvalf D E B leq w1 (71 %% 68)` (LABEL_TAC "pmeq") THENL
   [MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`yy:A`;
                        `(v:num->A) 68`;
                        `bvalf D (E:A->A->bool) B leq ((5 |-> yy) v) (5 %% 1)`;
       `bvalf D (E:A->A->bool) B leq w1 (71 %% 68)`] EBV_IN_UNIQUE) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* --- hyp down to s1 : erel c [[5%%1 --> LEXP]]_s1 --- *)
  SUBGOAL_THEN `erel D (E:A->A->bool) leq
     (bvalf D E B leq v (!! 5 (5 %% 1 --> ?? 4 (4 %% 2 && apply_form 3 4 5))))
     (bvalf D E B leq ((5 |-> yy) v)
      (5 %% 1 --> ?? 4 (4 %% 2 && apply_form 3 4 5)))`
    ASSUME_TAC THENL
   [MP_TAC(ISPECL[`5`;`5 %% 1 --> ?? 4 (4 %% 2 && apply_form 3 4 5)`;
       `D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`v:num->A`;`yy:A`]
        BVALF_ALL_LB) THEN
    ANTS_TAC THENL
    [ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[]; DISCH_THEN ACCEPT_TAC];
    ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq c
     (bvalf D E B leq ((5 |-> yy) v)
      (5 %% 1 --> ?? 4 (4 %% 2 && apply_form 3 4 5)))`
    ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`]
                 EPORDER_TRANS) THEN
    EXISTS_TAC `bvalf D (E:A->A->bool) B leq v
       (!! 5 (5 %% 1 --> ?? 4 (4 %% 2 && apply_form 3 4 5)))` THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* --- the meet m = c /\ pm --- *)
  MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`c:A`;
     `bvalf D (E:A->A->bool) B leq w1 (71 %% 68)`] EBALG_MEET) THEN
  ANTS_TAC THENL
  [ASM_REWRITE_TAC[]; DISCH_THEN(X_CHOOSE_THEN `m:A` ASSUME_TAC)] THEN
  SUBGOAL_THEN `(m:A) IN D /\ (E:A->A->bool) m B` STRIP_ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`c:A`;
       `bvalf D (E:A->A->bool) B leq w1 (71 %% 68)`;`m:A`] EMEET_IN) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* --- ebimp pm lhsex imp_s1 --- *)
  SUBGOAL_THEN `ebimp D (E:A->A->bool) B leq
     (bvalf D E B leq w1 (71 %% 68))
     (bvalf D E B leq ((5 |-> yy) v) (?? 4 (4 %% 2 && apply_form 3 4 5)))
     (bvalf D E B leq ((5 |-> yy) v)
      (5 %% 1 --> ?? 4 (4 %% 2 && apply_form 3 4 5)))`
    ASSUME_TAC THENL
   [USE_THEN "pmeq" (SUBST1_TAC o SYM) THEN
    MATCH_MP_TAC(ISPECL[`5 %% 1`;`?? 4 (4 %% 2 && apply_form 3 4 5)`;
       `D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`(5 |-> (yy:A)) v`]
        BVALF_IMP) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* --- erel m lhsex (residuate the hyp implication) --- *)
  SUBGOAL_THEN `erel D (E:A->A->bool) leq m
     (bvalf D E B leq ((5 |-> yy) v) (?? 4 (4 %% 2 && apply_form 3 4 5)))`
    ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`c:A`;
       `bvalf D (E:A->A->bool) B leq w1 (71 %% 68)`;
       `bvalf D (E:A->A->bool) B leq ((5 |-> yy) v)
        (?? 4 (4 %% 2 && apply_form 3 4 5))`;
       `bvalf D (E:A->A->bool) B leq ((5 |-> yy) v)
        (5 %% 1 --> ?? 4 (4 %% 2 && apply_form 3 4 5))`;
       `m:A`] EBIMP_MEET_LE) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* --- lhsex <= rhsex --- *)
  SUBGOAL_THEN `erel D (E:A->A->bool) leq
     (bvalf D E B leq ((5 |-> yy) v) (?? 4 (4 %% 2 && apply_form 3 4 5)))
     (bvalf D E B leq w1
        (?? 70 ((70 %% 69) && (?? 73 (opair_form 70 71 73 && (73 %% 72))))))`
    ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL[`4`;`4 %% 2 && apply_form 3 4 5`;
       `D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`(5 |-> (yy:A)) v`;
       `bvalf D (E:A->A->bool) B leq w1
          (?? 70 ((70 %% 69) && (?? 73 (opair_form 70 71 73 && (73 %% 72)))))`]
      BVALF_EX_LEAST) THEN
    ASM_REWRITE_TAC[] THEN X_GEN_TAC `a:A` THEN STRIP_TAC THEN
    SUBGOAL_THEN `(a:A) IN D` ASSUME_TAC THENL [ASM_MESON_TAC[]; ALL_TAC] THEN
    (* valuations sv_a, tv_a *)
    SUBGOAL_THEN `valuation D ((4 |-> a) ((5 |-> yy) v)) /\
      (!k. bname D (E:A->A->bool) B (((4 |-> a) ((5 |-> (yy:A)) v)) k))`
      STRIP_ASSUME_TAC THENL
     [CONJ_TAC THENL
       [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[] THEN
        ASM_MESON_TAC[];
        MATCH_MP_TAC BNAMEVAL_VALMOD THEN ASM_REWRITE_TAC[]]; ALL_TAC] THEN
    SUBGOAL_THEN `valuation D ((70 |-> a) w1) /\
      (!k. bname D (E:A->A->bool) B (((70 |-> a) w1) k))`
      STRIP_ASSUME_TAC THENL
     [CONJ_TAC THENL
       [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[] THEN
        ASM_MESON_TAC[];
        MATCH_MP_TAC BNAMEVAL_VALMOD THEN ASM_REWRITE_TAC[]]; ALL_TAC] THEN
    SUBGOAL_THEN `((4 |-> a) ((5 |-> (yy:A)) v)) 2 = v 2 /\
                  ((4 |-> a) ((5 |-> (yy:A)) v)) 3 = f /\
                  ((4 |-> a) ((5 |-> (yy:A)) v)) 4 = a /\
                  ((4 |-> a) ((5 |-> (yy:A)) v)) 5 = yy`
      STRIP_ASSUME_TAC THENL
     [SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER; ARITH_EQ] THEN ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    SUBGOAL_THEN
      `((70 |-> (a:A)) (w1:num->A)) 69 = v 69 /\ ((70 |-> a) w1) 70 = a /\
       ((70 |-> a) w1) 71 = yy /\ ((70 |-> a) w1) 72 = f`
      STRIP_ASSUME_TAC THENL
     [SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER; ARITH_EQ] THEN ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    (* KURBUNDLE (a, yy, f) *)
    MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`a:A`;`yy:A`;`f:A`]
           KURBUNDLE) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(X_CHOOSE_THEN `opA:A`
               (X_CHOOSE_THEN `saA:A` (X_CHOOSE_THEN `sabA:A`
                                       (X_CHOOSE_THEN `topA:A`
                                        (X_CHOOSE_THEN `mvA:A`
                                         STRIP_ASSUME_TAC))))) THEN
    SUBGOAL_THEN
      `bvalf D (E:A->A->bool) B leq ((4 |-> a) ((5 |-> yy) v))
       (apply_form 3 4 5) = mvA`
      ASSUME_TAC THENL
     [MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
         `(4 |-> (a:A)) ((5 |-> (yy:A)) v)`;`3`;`4`;`5`;`a:A`;`yy:A`;`f:A`;
         `opA:A`;`saA:A`;`sabA:A`;`topA:A`;`mvA:A`] APPLY_VAL_EQ) THEN
      ANTS_TAC THENL
      [ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[]; DISCH_THEN ACCEPT_TAC];
      ALL_TAC] THEN
    SUBGOAL_THEN `bvalf D (E:A->A->bool) B leq ((70 |-> a) w1)
       (?? 73 (opair_form 70 71 73 && (73 %% 72))) = mvA` ASSUME_TAC THENL
     [MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
         `(70 |-> (a:A)) w1`;`a:A`;`yy:A`;`f:A`;
         `opA:A`;`saA:A`;`sabA:A`;`topA:A`;`mvA:A`] PMEM_VAL_EQ) THEN
      ANTS_TAC THENL
      [ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[]; DISCH_THEN ACCEPT_TAC];
      ALL_TAC] THEN
    (* [[4%%2]]_sv = ebv_in a (v 2) ; [[70%%69]]_tv = ebv_in a (v 2) *)
    SUBGOAL_THEN `ebv_in D (E:A->A->bool) B leq a (v 2)
       (bvalf D E B leq ((4 |-> a) ((5 |-> yy) v)) (4 %% 2))` ASSUME_TAC THENL
     [SUBGOAL_THEN `ebv_in D (E:A->A->bool) B leq
          (((4 |-> (a:A)) ((5 |-> (yy:A)) v)) 4)
            (((4 |-> (a:A)) ((5 |-> (yy:A)) v)) 2)
          (bvalf D E B leq ((4 |-> a) ((5 |-> yy) v)) (4 %% 2))` MP_TAC THENL
       [MATCH_MP_TAC BVALF_MEM THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
      SUBGOAL_THEN `((4 |-> (a:A)) ((5 |-> (yy:A)) v)) 4 = a /\
                    ((4 |-> (a:A)) ((5 |-> (yy:A)) v)) 2 = v 2`
        (CONJUNCTS_THEN SUBST1_TAC) THENL
       [SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER; ARITH_EQ] THEN ASM_REWRITE_TAC[];
        ALL_TAC] THEN
      DISCH_THEN ACCEPT_TAC; ALL_TAC] THEN
    SUBGOAL_THEN `ebv_in D (E:A->A->bool) B leq a (v 2)
       (bvalf D E B leq ((70 |-> a) w1) (70 %% 69))` ASSUME_TAC THENL
     [SUBGOAL_THEN `ebv_in D (E:A->A->bool) B leq
          (((70 |-> (a:A)) w1) 70) (((70 |-> (a:A)) w1) 69)
          (bvalf D E B leq ((70 |-> a) w1) (70 %% 69))` MP_TAC THENL
       [MATCH_MP_TAC BVALF_MEM THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
      SUBGOAL_THEN `((70 |-> (a:A)) w1) 70 = a /\ ((70 |-> (a:A)) w1) 69 = v 2`
        (CONJUNCTS_THEN SUBST1_TAC) THENL
       [SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER; ARITH_EQ] THEN ASM_REWRITE_TAC[];
        ALL_TAC] THEN
      DISCH_THEN ACCEPT_TAC; ALL_TAC] THEN
    SUBGOAL_THEN
      `(bvalf D (E:A->A->bool) B leq ((4 |-> a) ((5 |-> yy) v))
        (4 %% 2)) IN D /\
      (bvalf D (E:A->A->bool) B leq ((70 |-> a) w1) (70 %% 69)) IN D`
      STRIP_ASSUME_TAC THENL
     [CONJ_TAC THEN MATCH_MP_TAC BVALF_IND THEN ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    (* MEET_EQ : [[70%%69]]_tv = [[4%%2]]_sv *)
    SUBGOAL_THEN `bvalf D (E:A->A->bool) B leq ((70 |-> a) w1) (70 %% 69) =
                  bvalf D E B leq ((4 |-> a) ((5 |-> yy) v)) (4 %% 2)`
      (LABEL_TAC "meeteq") THENL
     [MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`a:A`;
                          `(v:num->A) 2`;
                          `bvalf D (E:A->A->bool) B leq ((70 |-> a) w1)
                           (70 %% 69)`;
         `bvalf D (E:A->A->bool) B leq ((4 |-> a) ((5 |-> yy) v)) (4 %% 2)`]
          EBV_IN_UNIQUE) THEN
      ASM_REWRITE_TAC[]; ALL_TAC] THEN
    (* AND-MEET on both sides, collapsed through mvA *)
    SUBGOAL_THEN `emeet D (E:A->A->bool) B leq
       (bvalf D E B leq ((4 |-> a) ((5 |-> yy) v)) (4 %% 2)) mvA
       (bvalf D E B leq ((4 |-> a) ((5 |-> yy) v))
        (4 %% 2 && apply_form 3 4 5))`
      ASSUME_TAC THENL
     [SUBST1_TAC(SYM(ASSUME
                     `bvalf D (E:A->A->bool) B leq ((4 |-> a) ((5 |-> yy) v))
                      (apply_form 3 4 5) = mvA`)) THEN
      MATCH_MP_TAC(ISPECL[`4 %% 2`;`apply_form 3 4 5`;`D:A->bool`;
                          `E:A->A->bool`;`B:A`;`leq:A`;
                          `(4 |-> (a:A)) ((5 |-> (yy:A)) v)`]
          BVALF_AND_MEET) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN `emeet D (E:A->A->bool) B leq
       (bvalf D E B leq ((4 |-> a) ((5 |-> yy) v)) (4 %% 2)) mvA
       (bvalf D E B leq ((70 |-> a) w1)
          ((70 %% 69) && (?? 73 (opair_form 70 71 73 && (73 %% 72)))))`
      ASSUME_TAC THENL
     [USE_THEN "meeteq" (SUBST1_TAC o SYM) THEN
      SUBST1_TAC(SYM(ASSUME `bvalf D (E:A->A->bool) B leq ((70 |-> a) w1)
         (?? 73 (opair_form 70 71 73 && (73 %% 72))) = mvA`)) THEN
      MATCH_MP_TAC(ISPECL[`70 %% 69`;
                          `?? 73 (opair_form 70 71 73 && (73 %% 72))`;
                          `D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
                          `(70 |-> (a:A)) w1`] BVALF_AND_MEET) THEN
      ASM_REWRITE_TAC[]; ALL_TAC] THEN
    (* SUMMAND_EQ *)
    SUBGOAL_THEN
      `bvalf D (E:A->A->bool) B leq ((4 |-> a) ((5 |-> yy) v))
       (4 %% 2 && apply_form 3 4 5) =
       bvalf D E B leq ((70 |-> a) w1)
                    ((70 %% 69) &&
                     (?? 73 (opair_form 70 71 73 && (73 %% 72))))`
      ASSUME_TAC THENL
     [MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
         `bvalf D (E:A->A->bool) B leq ((4 |-> a) ((5 |-> yy) v))
          (4 %% 2)`;`mvA:A`;
         `bvalf D (E:A->A->bool) B leq ((4 |-> a) ((5 |-> yy) v))
          (4 %% 2 && apply_form 3 4 5)`;
         `bvalf D (E:A->A->bool) B leq ((70 |-> a) w1)
            ((70 %% 69) && (?? 73 (opair_form 70 71 73 && (73 %% 72))))`]
                       EMEET_UNIQUE) THEN
      ASM_REWRITE_TAC[]; ALL_TAC] THEN
    (* EX_UB : summand <= rhsex *)
    SUBGOAL_THEN `erel D (E:A->A->bool) leq
       (bvalf D E B leq ((70 |-> a) w1)
          ((70 %% 69) && (?? 73 (opair_form 70 71 73 && (73 %% 72)))))
       (bvalf D E B leq w1
          (?? 70 ((70 %% 69) && (?? 73 (opair_form 70 71 73 && (73 %% 72))))))`
      ASSUME_TAC THENL
     [MP_TAC(ISPECL[`70`;
                    `(70 %% 69) &&
                     (?? 73 (opair_form 70 71 73 && (73 %% 72)))`;
                    `D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`w1:num->A`;`a:A`]
            BVALF_EX_UB) THEN
      ANTS_TAC THENL
      [ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[]; DISCH_THEN ACCEPT_TAC];
      ALL_TAC] THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* --- erel m rhsex --- *)
  SUBGOAL_THEN `erel D (E:A->A->bool) leq m
     (bvalf D E B leq w1
        (?? 70 ((70 %% 69) && (?? 73 (opair_form 70 71 73 && (73 %% 72))))))`
    ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`]
                 EPORDER_TRANS) THEN
    EXISTS_TAC
      `bvalf D (E:A->A->bool) B leq ((5 |-> yy) v)
       (?? 4 (4 %% 2 && apply_form 3 4 5))` THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* --- ebimp pm rhsex imp_w1 --- *)
  SUBGOAL_THEN `ebimp D (E:A->A->bool) B leq
     (bvalf D E B leq w1 (71 %% 68))
     (bvalf D E B leq w1
      (?? 70 ((70 %% 69) && (?? 73 (opair_form 70 71 73 && (73 %% 72))))))
     (bvalf D E B leq w1
      (71 %% 68 -->
       ?? 70 ((70 %% 69) && (?? 73 (opair_form 70 71 73 && (73 %% 72))))))`
    ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL[`71 %% 68`;
       `?? 70 ((70 %% 69) && (?? 73 (opair_form 70 71 73 && (73 %% 72))))`;
       `D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`w1:num->A`] BVALF_IMP) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* --- close via EBIMP_LE_IMP --- *)
  MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`c:A`;
     `bvalf D (E:A->A->bool) B leq w1 (71 %% 68)`;
     `bvalf D (E:A->A->bool) B leq w1
      (?? 70 ((70 %% 69) && (?? 73 (opair_form 70 71 73 && (73 %% 72)))))`;
     `bvalf D (E:A->A->bool) B leq w1
      (71 %% 68 -->
       ?? 70 ((70 %% 69) && (?? 73 (opair_form 70 71 73 && (73 %% 72)))))`;
     `m:A`] EBIMP_LE_IMP) THEN
  ASM_REWRITE_TAC[]);;

(* ===================================================================== *)
(* BIJFORM_21_BOT_FROM_BODY : verbatim mirror of BIJFORM_BOT_FROM_BODY,   *)
(* with bijform 1 2 -> bijform 2 1 (domain slot 2, codomain slot 1).      *)
(* Body clauses 1,2,5 swap %% 1 <-> %% 2; clauses 3,4 identical.          *)
(* ===================================================================== *)
let BIJFORM_21_BOT_FROM_BODY = prove
 (`!D (E:A->A->bool) B leq v bot.
      (!f. f IN D /\ bname D E B f
           ==> bvalf D E B leq ((3 |-> f) v)
                 (!! 4 (!! 5 (apply_form 3 4 5 --> 4 %% 2 && 5 %% 1)) &&
                  !! 4 (4 %% 2 --> ?? 5 (5 %% 1 && apply_form 3 4 5)) &&
                  !! 4 (!! 5
                        (!! 6 (apply_form 3 4 5 && apply_form 3 4 6 -->
                               Eq 5 6))) &&
                  !! 4 (!! 7
                        (!! 5 (apply_form 3 4 5 && apply_form 3 7 5 -->
                               Eq 4 7))) &&
                  !! 5 (5 %% 1 -->
                        ?? 4 (4 %% 2 && apply_form 3 4 5))) = bot) /\
      model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
      valuation D v /\ (!i. bname D E B (v i)) /\
      bot IN D /\ ebot D E B leq bot
      ==> bvalf D E B leq v (bijform 2 1) = bot`,
  REPEAT GEN_TAC THEN
  DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "perf") STRIP_ASSUME_TAC) THEN
  SUBGOAL_THEN `ebalg D (E:A->A->bool) B leq /\ eporder D E B leq`
  STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[ECBA_IMP_BALG; ECBA_IMP_PORDER]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) bot B` ASSUME_TAC THENL
   [ASM_MESON_TAC[ebot]; ALL_TAC] THEN
  SUBGOAL_THEN `(bvalf D (E:A->A->bool) B leq v (bijform 2 1)) IN D /\
                (E:A->A->bool) (bvalf D E B leq v (bijform 2 1)) B`
  STRIP_ASSUME_TAC THENL
   [CONJ_TAC THENL
     [MP_TAC(ISPECL
             [`bijform 2 1`;`D:A->bool`;`E:A->A->bool`;`B:A`;
              `leq:A`;`v:num->A`]
             BVALF_SPEC) THEN ASM_SIMP_TAC[];
      MP_TAC(ISPECL
             [`bijform 2 1`;`D:A->bool`;`E:A->A->bool`;`B:A`;
              `leq:A`;`v:num->A`]
             BVALF_IN_B) THEN ASM_SIMP_TAC[]];
    ALL_TAC] THEN
  SUBGOAL_THEN
    `erel D (E:A->A->bool) leq (bvalf D E B leq v (bijform 2 1)) bot`
  ASSUME_TAC THENL
   [REWRITE_TAC[bijform] THEN CONV_TAC NUM_REDUCE_CONV THEN
    MATCH_MP_TAC BVALF_EX_LEAST THEN ASM_REWRITE_TAC[] THEN
    X_GEN_TAC `a:A` THEN STRIP_TAC THEN
    ASM_REWRITE_TAC[] THEN
    ASM_MESON_TAC[ebot];
    ALL_TAC] THEN
  MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
      `bvalf (D:A->bool) (E:A->A->bool) (B:A) (leq:A) (v:num->A)
       (bijform 2 1)`;
      `bot:A`] ELE_BOT) THEN
  ASM_REWRITE_TAC[]);;

(* ===================================================================== *)
(* BIJFORM_CHECK_BOT : for d countable (einj iota d om), a1 uncountable,  *)
(* [[bijform 2 1]] = bot at valuation with slot 2 = dc (domain d^), slot  *)
(* 1 = a1c (codomain a1^).  Routes clause-3 (functional)-->SVUNIFORM-->    *)
(* fn-form and clause-5 (surj)-->ONTOUNIFORM-->onto-form, then            *)
(* NO_ONTO_FUNC_NAME_COUNTABLE gives the contradiction.                   *)
(* ===================================================================== *)
let BIJFORM_CHECK_BOT = prove
 (`!D (E:A->A->bool) P leqp B leq bp onebee om d dc a1 a1c iota v bot.
      model D E ZF_AX /\ (!u:A. u IN D ==> elmem D E u) /\
      eleqp D E P leqp /\ eroset D E P leqp B /\ eincl D E B leq /\
        ebplus D E B bp /\
      ecba D E B leq /\ eccc D E bp leq /\
      B IN D /\ leq IN D /\ onebee IN D /\ E onebee B /\
        etop D E B leq onebee /\
      eomega D E om /\
      d IN D /\ eordinal D E d /\ einj D E iota d om /\
      a1 IN D /\ ~(?e. einj D E e a1 om) /\
      echeck D E onebee d dc /\ echeck D E onebee a1 a1c /\
        dc IN D /\ a1c IN D /\
      valuation D v /\ (!i. bname D E B (v i)) /\
      v 1 = a1c /\ v 2 = dc /\ v 68 = a1c /\ v 69 = dc /\
      bot IN D /\ ebot D E B leq bot
      ==> bvalf D E B leq v (bijform 2 1) = bot`,
  let CLOSE = FIRST_ASSUM ACCEPT_TAC ORELSE FIRST_ASSUM MATCH_ACCEPT_TAC in
  let body_tm =
   `!! 4 (!! 5 (apply_form 3 4 5 --> 4 %% 2 && 5 %% 1)) &&
    !! 4 (4 %% 2 --> ?? 5 (5 %% 1 && apply_form 3 4 5)) &&
    !! 4 (!! 5 (!! 6 (apply_form 3 4 5 && apply_form 3 4 6 --> Eq 5 6))) &&
    !! 4 (!! 7 (!! 5 (apply_form 3 4 5 && apply_form 3 7 5 --> Eq 4 7))) &&
    !! 5 (5 %% 1 --> ?? 4 (4 %% 2 && apply_form 3 4 5))` in
  let c1_tm   = lhand body_tm and r1_tm = rand body_tm in
  let c2_tm   = lhand r1_tm   and r2_tm = rand r1_tm in
  let svf_tm  = lhand r2_tm   and r3_tm = rand r2_tm in
  let c4_tm   = lhand r3_tm   and ontof_tm = rand r3_tm in
  let bw q = subst [q,`p:form`]
               `bvalf (D:A->bool) (E:A->A->bool) (B:A) (leq:A) (wf:num->A)
                (p:form)` in
  let bvv q = subst [q,`p:form`]
               `bvalf (D:A->bool) (E:A->A->bool) (B:A) (leq:A) (vv:num->A)
                (p:form)` in
  let mkerel u w =
    subst [u,`uu:A`; w,`ww:A`]
      `erel (D:A->bool) (E:A->A->bool) (leq:A) (uu:A) (ww:A)` in
  let c_tm = bw body_tm in
  let memw p =
    (MP_TAC(ISPECL [p;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`wf:num->A`]
            BVALF_SPEC) THEN
     ANTS_TAC THENL [REPEAT CONJ_TAC THEN CLOSE; STRIP_TAC]) THEN
    (MP_TAC(ISPECL [p;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`wf:num->A`]
            BVALF_IN_B) THEN
     ANTS_TAC THENL [REPEAT CONJ_TAC THEN CLOSE; DISCH_TAC]) in
  let andle lem p q =
    MP_TAC(ISPECL
           [p;q;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`wf:num->A`] lem) THEN
       ANTS_TAC THENL [REPEAT CONJ_TAC THEN CLOSE; DISCH_TAC] in
  let tr u v w =
    MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;u;v;w]
           EPORDER_TRANS) THEN
       ANTS_TAC THENL [REPEAT CONJ_TAC THEN CLOSE; DISCH_TAC] in
  let FVSVF = prove
   (`FV (!! 4
         (!! 5 (!! 6
                (apply_form 3 4 5 && apply_form 3 4 6 --> Eq 5 6)))) = {3}`,
    REWRITE_TAC[FV; FV_CLAUSES; FV_APPLY_FORM] THEN
    REWRITE_TAC[EXTENSION; IN_INSERT; NOT_IN_EMPTY; IN_UNION; IN_DELETE] THEN
    ARITH_TAC) in
  let FVONTOF = prove
   (`FV (!! 5 (5 %% 1 --> ?? 4 (4 %% 2 && apply_form 3 4 5))) = {1,2,3}`,
    REWRITE_TAC[FV; FV_CLAUSES; FV_APPLY_FORM] THEN
    REWRITE_TAC[EXTENSION; IN_INSERT; NOT_IN_EMPTY; IN_UNION; IN_DELETE] THEN
    ARITH_TAC) in
  EVERY
   [ (* ---- open; reduce to body=bot via BIJFORM_21_BOT_FROM_BODY ---- *)
     REPEAT GEN_TAC THEN STRIP_TAC;
     MATCH_MP_TAC BIJFORM_21_BOT_FROM_BODY;
     REPEAT CONJ_TAC THENL
       [ALL_TAC; CLOSE; CLOSE; CLOSE; CLOSE; CLOSE; CLOSE; CLOSE; CLOSE];
     X_GEN_TAC `f:A` THEN STRIP_TAC;
     MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`]
            ECBA_IMP_PORDER) THEN
       ASM_REWRITE_TAC[] THEN DISCH_TAC;
     (* ---- valuations wf = (3|->f)v, vv = (72|->f)wf ---- *)
     ABBREV_TAC `wf = (3 |-> f) (v:num->A)`;
     ABBREV_TAC `vv = (72 |-> f) (wf:num->A)`;
     SUBGOAL_THEN `valuation D (wf:num->A)` ASSUME_TAC THENL
       [EXPAND_TAC "wf" THEN MATCH_MP_TAC VALUATION_VALMOD THEN
        ASM_REWRITE_TAC[]; ALL_TAC];
     SUBGOAL_THEN `!i. bname D E B ((wf:num->A) i)` ASSUME_TAC THENL
       [EXPAND_TAC "wf" THEN MATCH_MP_TAC BNAMEVAL_VALMOD THEN
        ASM_REWRITE_TAC[]; ALL_TAC];
     SUBGOAL_THEN `valuation D (vv:num->A)` ASSUME_TAC THENL
       [EXPAND_TAC "vv" THEN MATCH_MP_TAC VALUATION_VALMOD THEN
        ASM_REWRITE_TAC[]; ALL_TAC];
     SUBGOAL_THEN `!i. bname D E B ((vv:num->A) i)` ASSUME_TAC THENL
       [EXPAND_TAC "vv" THEN MATCH_MP_TAC BNAMEVAL_VALMOD THEN
        ASM_REWRITE_TAC[]; ALL_TAC];
     (* slot equalities at wf then vv *)
     SUBGOAL_THEN
       `(wf:num->A) 1 = a1c /\ (wf:num->A) 2 = dc /\ (wf:num->A) 3 = f /\
        (wf:num->A) 68 = a1c /\ (wf:num->A) 69 = dc` STRIP_ASSUME_TAC THENL
       [EXPAND_TAC "wf" THEN REWRITE_TAC[VALMOD] THEN
        CONV_TAC NUM_REDUCE_CONV THEN
        ASM_REWRITE_TAC[]; ALL_TAC];
     SUBGOAL_THEN
       `(vv:num->A) 1 = a1c /\ (vv:num->A) 2 = dc /\ (vv:num->A) 3 = f /\
        (vv:num->A) 68 = a1c /\ (vv:num->A) 69 = dc /\ (vv:num->A) 72 = f`
       STRIP_ASSUME_TAC THENL
       [EXPAND_TAC "vv" THEN REWRITE_TAC[VALMOD] THEN
        CONV_TAC NUM_REDUCE_CONV THEN
        ASM_REWRITE_TAC[]; ALL_TAC];
     (* ---- residuation: b0 <= [[svf]]_wf and b0 <= [[ontof]]_wf ---- *)
     memw body_tm; memw r1_tm; memw r2_tm; memw r3_tm; memw svf_tm;
     memw ontof_tm;
     andle BVALF_AND_LE_R c1_tm r1_tm;
     andle BVALF_AND_LE_R c2_tm r2_tm;
     andle BVALF_AND_LE_L svf_tm r3_tm;
     andle BVALF_AND_LE_R svf_tm r3_tm;
     andle BVALF_AND_LE_R c4_tm ontof_tm;
     tr (bw body_tm) (bw r1_tm) (bw r2_tm);
     tr (bw body_tm) (bw r2_tm) (bw svf_tm);
     tr (bw body_tm) (bw r2_tm) (bw r3_tm);
     tr (bw body_tm) (bw r3_tm) (bw ontof_tm);
     (* ---- FV-cong lift wf -> vv for svf, ontof ---- *)
     SUBGOAL_THEN (mk_eq(bvv svf_tm, bw svf_tm)) ASSUME_TAC THENL
       [MATCH_MP_TAC BVALF_FV_CONG THEN REPEAT CONJ_TAC THEN TRY CLOSE THEN
        X_GEN_TAC `i:num` THEN REWRITE_TAC[FVSVF; IN_INSERT; NOT_IN_EMPTY] THEN
        STRIP_TAC THEN ASM_REWRITE_TAC[]; ALL_TAC];
     SUBGOAL_THEN (mk_eq(bvv ontof_tm, bw ontof_tm)) ASSUME_TAC THENL
       [MATCH_MP_TAC BVALF_FV_CONG THEN REPEAT CONJ_TAC THEN TRY CLOSE THEN
        X_GEN_TAC `i:num` THEN
        REWRITE_TAC[FVONTOF; IN_INSERT; NOT_IN_EMPTY] THEN
        STRIP_TAC THEN ASM_REWRITE_TAC[]; ALL_TAC];
     SUBGOAL_THEN (mkerel c_tm (bvv svf_tm)) ASSUME_TAC THENL
       [ASM_REWRITE_TAC[]; ALL_TAC];
     SUBGOAL_THEN (mkerel c_tm (bvv ontof_tm)) ASSUME_TAC THENL
       [ASM_REWRITE_TAC[]; ALL_TAC];
     (* ---- SVUNIFORM: b0 <= [[fn-form]]_vv ---- *)
     MP_TAC(ISPECL
            [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`f:A`;`vv:num->A`;c_tm]
            SVUNIFORM) THEN
       ANTS_TAC THENL
       [REPEAT CONJ_TAC THEN TRY CLOSE THEN ASM_REWRITE_TAC[]; DISCH_TAC];
     (* ---- ONTOUNIFORM: b0 <= [[onto-form]]_vv ---- *)
     MP_TAC(ISPECL
            [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`f:A`;`vv:num->A`;c_tm]
            ONTOUNIFORM) THEN
       ANTS_TAC THENL
       [REPEAT CONJ_TAC THEN TRY CLOSE THEN ASM_REWRITE_TAC[]; DISCH_TAC];
     (* ---- ebot b0 by contradiction via NO_ONTO_FUNC_NAME_COUNTABLE ---- *)
     SUBGOAL_THEN (subst [c_tm,`z:A`] `ebot D (E:A->A->bool) B leq (z:A)`)
       ASSUME_TAC THENL
       [MATCH_MP_TAC(TAUT `(~p ==> F) ==> p`) THEN DISCH_TAC THEN
        MATCH_MP_TAC(ISPECL
                     [`D:A->bool`;`E:A->A->bool`;`P:A`;`leqp:A`;`B:A`;`leq:A`;
                      `bp:A`;`onebee:A`;`a1:A`;`a1c:A`;`om:A`;`d:A`;`dc:A`;
                      `iota:A`;`f:A`;c_tm;
                      `vv:num->A`] NO_ONTO_FUNC_NAME_COUNTABLE) THEN
        REPEAT CONJ_TAC THEN CLOSE;
        ALL_TAC];
     (* ---- b0 = bot via EBOT_UNIQUE ---- *)
     MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;c_tm;`bot:A`]
            EBOT_UNIQUE) THEN
       ANTS_TAC THENL [REPEAT CONJ_TAC THEN CLOSE; DISCH_THEN ACCEPT_TAC] ]);;

(* ===================================================================== *)
(* FV_BIJFORM_21_6869 : slots 68,69 are NOT free in bijform 2 1 (its FVs  *)
(* are among {1..7}).  A concrete membership check -- fast, no Presburger. *)
(* This is all the FV info ISCARD_NOBIJ_TOP's FV-congruence needs: the two *)
(* valuations (2|->vc)v and wp differ only at slots 68,69.                 *)
(* ===================================================================== *)
let FV_BIJFORM_21_6869 = prove
 (`~(68 IN FV(bijform 2 1)) /\ ~(69 IN FV(bijform 2 1))`,
  REWRITE_TAC[bijform] THEN REWRITE_TAC[ARITH_RULE `MAX 2 1 = 2`] THEN
  CONV_TAC NUM_REDUCE_CONV THEN
  REWRITE_TAC[FV; FV_CLAUSES; FV_APPLY_FORM] THEN
  REWRITE_TAC[IN_INSERT; NOT_IN_EMPTY; IN_UNION; IN_DELETE] THEN
  CONV_TAC NUM_REDUCE_CONV THEN REWRITE_TAC[]);;

(* ===================================================================== *)
(* ISCARD_NOBIJ_TOP  (A2a-ii) :                                           *)
(*   [[!!- 2 1 (Not (bijform 2 1))]]_{1:=a1c} = top                       *)
(* "no element of aleph_1^ bijects with aleph_1^ (which is a cardinal)".  *)
(* Route: BVALF_FORALLMEM_TOP -> per name a: erel [[a IN a1^]]            *)
(*   [[Not(bijform a a1^)]].  ECHECK_IN_LE_SUP collapses [[a IN a1^]] to a *)
(*   sup over checks c^ (c in a1); per check, BVAL_SUBST_CONG transports   *)
(*   bijform along [[a=c^]] to a fresh valuation wp (slots 68/69 set) and  *)
(*   BIJFORM_CHECK_BOT (c countable via ECOUNTABLE_BELOW_A1) kills it; the  *)
(*   residuation Not p = p-->False is closed by BVALF_IMP + EBIMP_LE_IMP.  *)
(* ===================================================================== *)
let ISCARD_NOBIJ_TOP = prove
 (`!D (E:A->A->bool) P leqp B leq bp onebee om a1 a1c v bot.
      model D E ZF_AX /\ (!u:A. u IN D ==> elmem D E u) /\
      eleqp D E P leqp /\ eroset D E P leqp B /\ eincl D E B leq /\
        ebplus D E B bp /\
      ecba D E B leq /\ eccc D E bp leq /\
      B IN D /\ leq IN D /\ onebee IN D /\ E onebee B /\
        etop D E B leq onebee /\
      eomega D E om /\
      a1 IN D /\ eordinal D E a1 /\ ecardinal D E a1 /\ E om a1 /\
      ~(?e. einj D E e a1 om) /\
      (!c'. c' IN D /\ E c' a1 ==> ~(ecardinal D E c' /\ E om c')) /\
      echeck D E onebee a1 a1c /\ a1c IN D /\
      valuation D v /\ (!i. bname D E B (v i)) /\ v 1 = a1c /\
      bot IN D /\ ebot D E B leq bot
      ==> etop D E B leq (bvalf D E B leq v (!!- 2 1 (Not (bijform 2 1))))`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `ebalg D (E:A->A->bool) B leq /\ eporder D E B leq`
    STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[ECBA_IMP_BALG; ECBA_IMP_PORDER]; ALL_TAC] THEN
  SUBGOAL_THEN `bname D (E:A->A->bool) B a1c` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`onebee:A`;`B:A`;
                        `a1:A`;`a1c:A`]
                 ECHECK_IS_BNAME) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* ---- reduce the universal via BVALF_FORALLMEM_TOP ---- *)
  MP_TAC(ISPECL[`2`;`1`;`Not (bijform 2 1)`;`D:A->bool`;`E:A->A->bool`;`B:A`;
                `leq:A`;`v:num->A`]
         BVALF_FORALLMEM_TOP) THEN
  ANTS_TAC THENL
  [ASM_REWRITE_TAC[]; DISCH_THEN(fun th -> REWRITE_TAC[th])] THEN
  X_GEN_TAC `a:A` THEN STRIP_TAC THEN
  (* ---- valuation (2|->a)v ---- *)
  SUBGOAL_THEN `valuation D ((2|->a) (v:num->A)) /\
                (!i. bname D (E:A->A->bool) B (((2|->a)v) i))`
    STRIP_ASSUME_TAC THENL
   [CONJ_TAC THENL
     [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[];
      MATCH_MP_TAC BNAMEVAL_VALMOD THEN ASM_REWRITE_TAC[]]; ALL_TAC] THEN
  SUBGOAL_THEN `((2|->a) (v:num->A)) 1 = a1c /\ ((2|->a) v) 2 = a`
    STRIP_ASSUME_TAC THENL
   [SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER; ARITH_EQ] THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  (* ---- z = [[2 %% 1]]_{(2|->a)v} : membership + value ebv_in a a1c ---- *)
  SUBGOAL_THEN `(bvalf D (E:A->A->bool) B leq ((2|->a)v) (2 %% 1)) IN D /\
                E (bvalf D E B leq ((2|->a)v) (2 %% 1)) B`
    STRIP_ASSUME_TAC THENL
   [CONJ_TAC THENL [MATCH_MP_TAC BVALF_IND; MATCH_MP_TAC BVALF_IN_B] THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN
    `ebv_in D (E:A->A->bool) B leq a a1c (bvalf D E B leq ((2|->a)v) (2 %% 1))`
    ASSUME_TAC THENL
   [SUBGOAL_THEN `ebv_in D (E:A->A->bool) B leq (((2|->a)v) 2) (((2|->a)v) 1)
        (bvalf D E B leq ((2|->a)v) (2 %% 1))` MP_TAC THENL
     [MATCH_MP_TAC BVALF_MEM THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN `((2|->a)(v:num->A)) 2 = (a:A) /\ ((2|->a)v) 1 = a1c`
      (CONJUNCTS_THEN SUBST1_TAC) THENL
     [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC]; ALL_TAC] THEN
  (* ---- w0 = [[Not (bijform 2 1)]]_{(2|->a)v} : membership ---- *)
  SUBGOAL_THEN
    `(bvalf D (E:A->A->bool) B leq ((2|->a)v) (Not (bijform 2 1))) IN D /\
     E (bvalf D E B leq ((2|->a)v) (Not (bijform 2 1))) B`
      STRIP_ASSUME_TAC THENL
   [CONJ_TAC THENL [MATCH_MP_TAC BVALF_IND; MATCH_MP_TAC BVALF_IN_B] THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* ---- the sup-collapse: ECHECK_IN_LE_SUP ---- *)
  MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`onebee:A`;`a1:A`;
                `a1c:A`;`a:A`;
                `bvalf D (E:A->A->bool) B leq ((2|->a)v) (2 %% 1)`;
     `bvalf D (E:A->A->bool) B leq ((2|->a)v) (Not (bijform 2 1))`]
      ECHECK_IN_LE_SUP) THEN
  ANTS_TAC THENL
   [REPEAT CONJ_TAC THEN TRY(FIRST_ASSUM ACCEPT_TAC) THEN
    (* ===================== per check c ===================== *)
    MAP_EVERY X_GEN_TAC [`c:A`;`vc:A`;`ec:A`] THEN STRIP_TAC THEN
    SUBGOAL_THEN `(c:A) IN D /\ (vc:A) IN D` STRIP_ASSUME_TAC THENL
     [ASM_MESON_TAC[ECHECK_IMP]; ALL_TAC] THEN
    SUBGOAL_THEN `eordinal D (E:A->A->bool) c` ASSUME_TAC THENL
     [MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`a1:A`;`c:A`]
                   EORDINAL_MEMBER) THEN
      ASM_REWRITE_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN `?e. einj D (E:A->A->bool) e c om`
      (X_CHOOSE_THEN `io:A` ASSUME_TAC) THENL
      [MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`om:A`;`a1:A`;`c:A`]
                    ECOUNTABLE_BELOW_A1) THEN
       REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    SUBGOAL_THEN `bname D (E:A->A->bool) B vc` ASSUME_TAC THENL
     [MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`onebee:A`;`B:A`;
                          `c:A`;`vc:A`]
                   ECHECK_IS_BNAME) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN `(E:A->A->bool) (ec:A) (B:A)` ASSUME_TAC THENL
     [MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`a:A`;
                          `vc:A`;`ec:A`]
                   EBV_EQ_IN_B) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    (* ---- build wp with slots 1,2,68,69 = a1c,vc,a1c,vc ---- *)
    ABBREV_TAC `wp = (2 |-> vc) ((68 |-> a1c) ((69 |-> vc) (v:num->A)))` THEN
    SUBGOAL_THEN `valuation D (wp:num->A)` ASSUME_TAC THENL
     [EXPAND_TAC "wp" THEN
      MATCH_MP_TAC VALUATION_VALMOD THEN CONJ_TAC THENL
       [MATCH_MP_TAC VALUATION_VALMOD THEN CONJ_TAC THENL
         [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[];
          ASM_REWRITE_TAC[]];
        ASM_REWRITE_TAC[]]; ALL_TAC] THEN
    SUBGOAL_THEN `!i. bname D (E:A->A->bool) B ((wp:num->A) i)`
      ASSUME_TAC THENL
      [EXPAND_TAC "wp" THEN
      MATCH_MP_TAC BNAMEVAL_VALMOD THEN CONJ_TAC THENL
       [ASM_REWRITE_TAC[];
        MATCH_MP_TAC BNAMEVAL_VALMOD THEN CONJ_TAC THENL
         [ASM_REWRITE_TAC[];
          MATCH_MP_TAC BNAMEVAL_VALMOD THEN ASM_REWRITE_TAC[]]]; ALL_TAC] THEN
    SUBGOAL_THEN `(wp:num->A) 1 = a1c /\ (wp:num->A) 2 = vc /\
                  (wp:num->A) 68 = a1c /\ (wp:num->A) 69 = vc`
      STRIP_ASSUME_TAC THENL
      [EXPAND_TAC "wp" THEN SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER; ARITH_EQ] THEN
      ASM_REWRITE_TAC[]; ALL_TAC] THEN
    (* ---- BIJFORM_CHECK_BOT at wp : [[bijform 2 1]]_wp = bot ---- *)
    SUBGOAL_THEN `bvalf D (E:A->A->bool) B leq wp (bijform 2 1) = bot`
      ASSUME_TAC THENL
      [MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`P:A`;`leqp:A`;`B:A`;
                           `leq:A`;`bp:A`;
                           `onebee:A`;`om:A`;`c:A`;`vc:A`;`a1:A`;`a1c:A`;
                           `io:A`;`wp:num->A`;`bot:A`]
         BIJFORM_CHECK_BOT) THEN
      REPEAT CONJ_TAC THEN TRY(FIRST_ASSUM ACCEPT_TAC) THEN ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    (* ---- FV-cong lift to (2|->vc)v : [[bijform 2 1]]_{(2|->vc)v} = bot *)
    (* ---- *)
    SUBGOAL_THEN `bvalf D (E:A->A->bool) B leq ((2|->vc)v) (bijform 2 1) = bot`
      ASSUME_TAC THENL
      [SUBGOAL_THEN `bvalf D (E:A->A->bool) B leq ((2|->vc)v) (bijform 2 1) =
                    bvalf D E B leq wp (bijform 2 1)` SUBST1_TAC THENL
       [MATCH_MP_TAC BVALF_FV_CONG THEN REPEAT CONJ_TAC THEN
        TRY(FIRST_ASSUM ACCEPT_TAC) THENL
         [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[];
          MATCH_MP_TAC BNAMEVAL_VALMOD THEN ASM_REWRITE_TAC[];
          X_GEN_TAC `i:num` THEN DISCH_TAC THEN
          SUBGOAL_THEN `~(i = 68) /\ ~(i = 69)` STRIP_ASSUME_TAC THENL
           [CONJ_TAC THENL
             [DISCH_THEN SUBST_ALL_TAC THEN
              UNDISCH_TAC `68 IN FV(bijform 2 1)` THEN
              REWRITE_TAC[FV_BIJFORM_21_6869];
              DISCH_THEN SUBST_ALL_TAC THEN
              UNDISCH_TAC `69 IN FV(bijform 2 1)` THEN
              REWRITE_TAC[FV_BIJFORM_21_6869]];
            ALL_TAC] THEN
          EXPAND_TAC "wp" THEN ASM_CASES_TAC `i = 2` THEN
          ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER; ARITH_EQ]];
        ASM_REWRITE_TAC[]]; ALL_TAC] THEN
    (* ---- meet m = ec /\ [[bijform 2 1]]_{(2|->a)v} ---- *)
    MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`ec:A`;
       `bvalf D (E:A->A->bool) B leq ((2|->a)v) (bijform 2 1)`]
         EBALG_MEET) THEN
    ANTS_TAC THENL
     [REPEAT CONJ_TAC THEN TRY(FIRST_ASSUM ACCEPT_TAC) THENL
       [MATCH_MP_TAC BVALF_IND THEN ASM_REWRITE_TAC[];
        MATCH_MP_TAC BVALF_IN_B THEN ASM_REWRITE_TAC[]]; ALL_TAC] THEN
    DISCH_THEN(X_CHOOSE_THEN `m:A` ASSUME_TAC) THEN
    (* ---- BVAL_SUBST_CONG : erel m [[bijform 2 1]]_{(2|->vc)v} ---- *)
    SUBGOAL_THEN
      `erel D (E:A->A->bool) leq m (bvalf D E B leq ((2|->vc)v) (bijform 2 1))`
      ASSUME_TAC THENL
     [MATCH_MP_TAC(ISPECL[`bijform 2 1`;`D:A->bool`;`E:A->A->bool`;`B:A`;
                          `leq:A`;`v:num->A`;
                          `2`;`a:A`;`vc:A`;`ec:A`;`m:A`] BVAL_SUBST_CONG) THEN
       ASM_REWRITE_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN `erel D (E:A->A->bool) leq m bot` ASSUME_TAC THENL
     [SUBST1_TAC(SYM(ASSUME
        `bvalf D (E:A->A->bool) B leq ((2|->vc)v) (bijform 2 1) = bot`)) THEN
      FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    (* ---- [[False]]_{(2|->a)v} = bot ---- *)
    SUBGOAL_THEN `bvalf D (E:A->A->bool) B leq ((2|->a)v) False = bot`
      ASSUME_TAC THENL
      [MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
         `bvalf D (E:A->A->bool) B leq ((2|->a)v) False`;`bot:A`]
          EBOT_UNIQUE) THEN
      REPEAT CONJ_TAC THENL
       [FIRST_ASSUM ACCEPT_TAC;
        MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
                            `(2|->a)(v:num->A)`]BVALF_FALSE) THEN
          ASM_REWRITE_TAC[];
        FIRST_ASSUM ACCEPT_TAC]; ALL_TAC] THEN
    (* ---- ebimp [[bijform]] [[False]] [[bijform-->False]] ---- *)
    MP_TAC(ISPECL[`bijform 2 1`;`False`;`D:A->bool`;`E:A->A->bool`;
                  `B:A`;`leq:A`;
                  `(2|->a)(v:num->A)`] BVALF_IMP) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_TAC] THEN
    (* ---- close via EBIMP_LE_IMP (Not = (-->False)) ---- *)
    REWRITE_TAC[Not_DEF] THEN
    MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`ec:A`;
       `bvalf D (E:A->A->bool) B leq ((2|->a)v) (bijform 2 1)`;
       `bvalf D (E:A->A->bool) B leq ((2|->a)v) False`;
       `bvalf D (E:A->A->bool) B leq ((2|->a)v) (bijform 2 1 --> False)`;`m:A`]
       EBIMP_LE_IMP) THEN
    REPEAT CONJ_TAC THENL
     [FIRST_ASSUM ACCEPT_TAC;                          (* ebalg *)
      FIRST_ASSUM ACCEPT_TAC;                          (* ec IN D *)
      MATCH_MP_TAC BVALF_IND THEN ASM_REWRITE_TAC[];   (* [[bijform]] IN D *)
      MATCH_MP_TAC BVALF_IND THEN ASM_REWRITE_TAC[];   (* [[False]] IN D *)
      FIRST_ASSUM ACCEPT_TAC;                          (* E ec B *)
      MATCH_MP_TAC BVALF_IN_B THEN ASM_REWRITE_TAC[];  (* E [[bijform]] B *)
      MATCH_MP_TAC BVALF_IN_B THEN ASM_REWRITE_TAC[];  (* E [[False]] B *)
      FIRST_ASSUM ACCEPT_TAC;                          (* ebimp *)
      FIRST_ASSUM ACCEPT_TAC;
      (* emeet ec [[bijform]] m *)
      ASM_REWRITE_TAC[]];
     (* erel m [[False]] = erel m bot *)
    (* ===================== end per check ===================== *)
    DISCH_THEN ACCEPT_TAC]);;

(* ISCARD_CHECK_TOP (A2a): [[iscard_form 1]]_{1:=a1c} = top.
   Wrap of ORDFORM_CHECK_TOP (ordinality of a1^) and ISCARD_NOBIJ_TOP
     (no bijection
   from a member) via BVALF_AND_TOP.  Same forcing CTX as ISCARD_NOBIJ_TOP. *)
let ISCARD_CHECK_TOP = prove
 (`!D (E:A->A->bool) P leqp B leq bp onebee om a1 a1c v bot.
      model D E ZF_AX /\ (!u:A. u IN D ==> elmem D E u) /\
      eleqp D E P leqp /\ eroset D E P leqp B /\ eincl D E B leq /\
        ebplus D E B bp /\
      ecba D E B leq /\ eccc D E bp leq /\
      B IN D /\ leq IN D /\ onebee IN D /\ E onebee B /\
        etop D E B leq onebee /\
      eomega D E om /\
      a1 IN D /\ eordinal D E a1 /\ ecardinal D E a1 /\ E om a1 /\
      ~(?e. einj D E e a1 om) /\
      (!c'. c' IN D /\ E c' a1 ==> ~(ecardinal D E c' /\ E om c')) /\
      echeck D E onebee a1 a1c /\ a1c IN D /\
      valuation D v /\ (!i. bname D E B (v i)) /\ v 1 = a1c /\
      bot IN D /\ ebot D E B leq bot
      ==> etop D E B leq (bvalf D E B leq v (iscard_form 1))`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  REWRITE_TAC[iscard_form] THEN CONV_TAC NUM_REDUCE_CONV THEN
  MP_TAC(ISPECL[`ordinal_form 1`;`!!- 2 1 (Not (bijform 2 1))`;
     `D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`v:num->A`] BVALF_AND_TOP) THEN
  ANTS_TAC THENL
  [ASM_REWRITE_TAC[]; DISCH_THEN(fun th -> REWRITE_TAC[th])] THEN
  CONJ_TAC THENL
   [MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`onebee:A`;
                        `a1:A`;`a1c:A`;
                        `1`;`v:num->A`] ORDFORM_CHECK_TOP) THEN
      ASM_REWRITE_TAC[];
      MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`P:A`;`leqp:A`;`B:A`;
                          `leq:A`;`bp:A`;
                          `onebee:A`;`om:A`;`a1:A`;`a1c:A`;`v:num->A`;`bot:A`]
       ISCARD_NOBIJ_TOP) THEN
    ASM_REWRITE_TAC[]]);;

(* CHECK_NOTIN_BOT: a NOT a member of b (ground) ==> [[a^ IN b^]] = bot.
   Derived: [[a^ IN b^]] <= bot via ECHECK_IN_LE_SUP (every c in b has c<>a so
   [[a^=c^]]=bot by ECHECK_EQ_BOT); then = bot by ELE_BOT. *)
let CHECK_NOTIN_BOT = prove
 (`!D (E:A->A->bool) B leq onebee a b va vb z bot.
      model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
      (!u:A. u IN D ==> elmem D E u) /\
      onebee IN D /\ E onebee B /\ etop D E B leq onebee /\
      echeck D E onebee a va /\ echeck D E onebee b vb /\ ~(E a b) /\
      va IN D /\ vb IN D /\ z IN D /\ ebv_in D E B leq va vb z /\
      bot IN D /\ ebot D E B leq bot
      ==> ebot D E B leq z`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `(a:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[ECHECK_IMP]; ALL_TAC] THEN
  SUBGOAL_THEN `eporder D (E:A->A->bool) B leq` ASSUME_TAC THENL
   [ASM_MESON_TAC[ECBA_IMP_PORDER]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) bot B` ASSUME_TAC THENL
   [ASM_MESON_TAC[ebot]; ALL_TAC] THEN
  SUBGOAL_THEN `bname D (E:A->A->bool) B va` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`onebee:A`;`B:A`;
                        `a:A`;`va:A`]
                 ECHECK_IS_BNAME) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) z B` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`va:A`;
                        `vb:A`;`z:A`]
                 EBV_IN_IN_B) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq z bot` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`onebee:A`;
                        `b:A`;`vb:A`;
                        `va:A`;`z:A`;`bot:A`] ECHECK_IN_LE_SUP) THEN
    REPEAT CONJ_TAC THEN TRY(FIRST_ASSUM ACCEPT_TAC) THEN
    MAP_EVERY X_GEN_TAC [`c:A`;`vc:A`;`ec:A`] THEN STRIP_TAC THEN
    SUBGOAL_THEN `~(a:A = c)` ASSUME_TAC THENL
     [DISCH_THEN SUBST_ALL_TAC THEN ASM_MESON_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN `ebot D (E:A->A->bool) B leq ec` ASSUME_TAC THENL
     [MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`onebee:A`;
                          `a:A`;`c:A`;
                          `va:A`;`vc:A`;`ec:A`] ECHECK_EQ_BOT) THEN
                 ASM_REWRITE_TAC[]; ALL_TAC] THEN
    MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`ec:A`;
                        `bot:A`] EBOT_LE) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `z:A = bot` SUBST1_TAC THENL
   [MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`z:A`;`bot:A`]
                 ELE_BOT) THEN
    ASM_REWRITE_TAC[]; ASM_REWRITE_TAC[]]);;

(* IMPL_OMNC_TOP: for d an ordinal member of a1 (= aleph_1), the implication
   [[om^ IN d^ --> Not(iscard_form d^)]] = top.  Dichotomy on om IN d:
     om IN d  : d is a non-cardinal (succ-card property), so [[iscard d^]]=bot,
                [[Not(iscard d^)]]=top, erel _ top (ETOP_GE);
     ~om IN d : [[om^ IN d^]]=bot (CHECK_NOTIN_BOT),
     erel bot _ (EBOT_LE).            *)
let IMPL_OMNC_TOP = prove
 (`!D (E:A->A->bool) B leq onebee om omc a1 d dc vv bot.
      model D E ZF_AX /\ ecba D E B leq /\ B IN D /\ leq IN D /\
      (!u:A. u IN D ==> elmem D E u) /\
      onebee IN D /\ E onebee B /\ etop D E B leq onebee /\
      eomega D E om /\ echeck D E onebee om omc /\
      a1 IN D /\
        (!c'. c' IN D /\ E c' a1 ==> ~(ecardinal D E c' /\ E om c')) /\
      d IN D /\ eordinal D E d /\ E d a1 /\ echeck D E onebee d dc /\
      omc IN D /\ dc IN D /\
      valuation D vv /\ (!i. bname D E B (vv i)) /\ vv 0 = omc /\ vv 2 = dc /\
      bot IN D /\ ebot D E B leq bot
      ==> etop D E B leq
        (bvalf D E B leq vv (0 %% 2 --> Not (iscard_form 2)))`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  MP_TAC(ISPECL[`0 %% 2`;`Not (iscard_form 2)`;`D:A->bool`;`E:A->A->bool`;
                `B:A`;`leq:A`;
                `vv:num->A`] BVALF_IMP_TOP) THEN
  ANTS_TAC THENL
  [ASM_REWRITE_TAC[]; DISCH_THEN(fun th -> REWRITE_TAC[th])] THEN
  SUBGOAL_THEN `(bvalf D (E:A->A->bool) B leq vv (0 %% 2)) IN D /\
                E (bvalf D E B leq vv (0 %% 2)) B` STRIP_ASSUME_TAC THENL
   [CONJ_TAC THENL [MATCH_MP_TAC BVALF_IND; MATCH_MP_TAC BVALF_IN_B] THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(bvalf D (E:A->A->bool) B leq vv (Not (iscard_form 2))) IN D /\
                E (bvalf D E B leq vv (Not (iscard_form 2))) B`
    STRIP_ASSUME_TAC THENL
   [CONJ_TAC THENL [MATCH_MP_TAC BVALF_IND; MATCH_MP_TAC BVALF_IN_B] THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN
    `ebv_in D (E:A->A->bool) B leq omc dc (bvalf D E B leq vv (0 %% 2))`
    ASSUME_TAC THENL
   [SUBST1_TAC(SYM(ASSUME `(vv:num->A) 0 = omc`)) THEN
    SUBST1_TAC(SYM(ASSUME `(vv:num->A) 2 = dc`)) THEN
    MATCH_MP_TAC BVALF_MEM THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  ASM_CASES_TAC `(E:A->A->bool) om d` THENL
   [SUBGOAL_THEN `~ecardinal D (E:A->A->bool) d` ASSUME_TAC THENL
     [UNDISCH_TAC `!c'. c' IN D /\ E c' a1
                        ==> ~(ecardinal D (E:A->A->bool) c' /\ E om c')` THEN
      DISCH_THEN(MP_TAC o SPEC `d:A`) THEN ASM_REWRITE_TAC[] THEN
      ASM_MESON_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN
      `ebot D (E:A->A->bool) B leq (bvalf D E B leq vv (iscard_form 2))`
      ASSUME_TAC THENL
     [MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`onebee:A`;
                          `vv:num->A`;
                          `d:A`;`dc:A`] ISCARD_CHECK_BOT) THEN
      ASM_REWRITE_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN
      `etop D (E:A->A->bool) B leq (bvalf D E B leq vv (Not (iscard_form 2)))`
      ASSUME_TAC THENL
     [MP_TAC(ISPECL[`iscard_form 2`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
                    `vv:num->A`]
             BVALF_NOT_TOP) THEN
      ANTS_TAC THENL
      [ASM_REWRITE_TAC[]; DISCH_THEN(fun th -> REWRITE_TAC[th])] THEN
      FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
       `bvalf D (E:A->A->bool) B leq vv (Not (iscard_form 2))`;
       `bvalf D (E:A->A->bool) B leq vv (0 %% 2)`] ETOP_GE) THEN
    ASM_REWRITE_TAC[];
    SUBGOAL_THEN `ebot D (E:A->A->bool) B leq (bvalf D E B leq vv (0 %% 2))`
      ASSUME_TAC THENL
      [MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`onebee:A`;
                           `om:A`;`d:A`;
                           `omc:A`;`dc:A`;
                           `bvalf D (E:A->A->bool) B leq vv (0 %% 2)`;`bot:A`]
         CHECK_NOTIN_BOT) THEN
      ASM_REWRITE_TAC[]; ALL_TAC] THEN
    MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
       `bvalf D (E:A->A->bool) B leq vv (0 %% 2)`;
       `bvalf D (E:A->A->bool) B leq vv (Not (iscard_form 2))`] EBOT_LE) THEN
    ASM_REWRITE_TAC[]]);;

(* SUCCARD_NC_TOP (A2c): [[!!- 2 1 (0%%2 -->
  Not(iscard_form 2))]]_{0:=omc,1:=a1c}=top.
   "every ordinal a in aleph_1 with om in a is a non-cardinal".
   BVALF_FORALLMEM_TOP -> per a: erel [[a IN a1^]] [[P]]_va  (P =
     0%%2-->Not iscard 2).
   ECHECK_IN_LE_SUP -> per check c (c in a1): erel [[a=c^]] [[P]]_va.
   IMPL_OMNC_TOP gives [[P]]_{(2|->c^)v}=top (ground dichotomy);
   EMEET_TOP makes the
   subst-cong meet = ec;
   BVAL_SUBST_CONG transports to [[P]]_va.  No FV-cong needed. *)
let SUCCARD_NC_TOP = prove
 (`!D (E:A->A->bool) B leq onebee om omc a1 a1c v bot.
      model D E ZF_AX /\ (!u:A. u IN D ==> elmem D E u) /\
      ecba D E B leq /\
      B IN D /\ leq IN D /\ onebee IN D /\ E onebee B /\
        etop D E B leq onebee /\
      eomega D E om /\ echeck D E onebee om omc /\ omc IN D /\
      a1 IN D /\ eordinal D E a1 /\
      (!c'. c' IN D /\ E c' a1 ==> ~(ecardinal D E c' /\ E om c')) /\
      echeck D E onebee a1 a1c /\ a1c IN D /\
      valuation D v /\ (!i. bname D E B (v i)) /\ v 0 = omc /\ v 1 = a1c /\
      bot IN D /\ ebot D E B leq bot
      ==> etop D E B leq
            (bvalf D E B leq v (!!- 2 1 (0 %% 2 --> Not (iscard_form 2))))`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `ebalg D (E:A->A->bool) B leq /\ eporder D E B leq`
    STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[ECBA_IMP_BALG; ECBA_IMP_PORDER]; ALL_TAC] THEN
  SUBGOAL_THEN `bname D (E:A->A->bool) B a1c` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`onebee:A`;`B:A`;
                        `a1:A`;`a1c:A`]
                 ECHECK_IS_BNAME) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MP_TAC(ISPECL[`2`;`1`;`0 %% 2 --> Not (iscard_form 2)`;
     `D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`v:num->A`]
              BVALF_FORALLMEM_TOP) THEN
  ANTS_TAC THENL
  [ASM_REWRITE_TAC[]; DISCH_THEN(fun th -> REWRITE_TAC[th])] THEN
  X_GEN_TAC `a:A` THEN STRIP_TAC THEN
  SUBGOAL_THEN `valuation D ((2|->a) (v:num->A)) /\
                (!i. bname D (E:A->A->bool) B (((2|->a)v) i))`
    STRIP_ASSUME_TAC THENL
   [CONJ_TAC THENL
     [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[];
      MATCH_MP_TAC BNAMEVAL_VALMOD THEN ASM_REWRITE_TAC[]]; ALL_TAC] THEN
  SUBGOAL_THEN `((2|->a) (v:num->A)) 1 = a1c /\ ((2|->a) v) 2 = a`
    STRIP_ASSUME_TAC THENL
   [SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER; ARITH_EQ] THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `(bvalf D (E:A->A->bool) B leq ((2|->a)v) (2 %% 1)) IN D /\
                E (bvalf D E B leq ((2|->a)v) (2 %% 1)) B`
    STRIP_ASSUME_TAC THENL
   [CONJ_TAC THENL [MATCH_MP_TAC BVALF_IND; MATCH_MP_TAC BVALF_IN_B] THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN
    `ebv_in D (E:A->A->bool) B leq a a1c (bvalf D E B leq ((2|->a)v) (2 %% 1))`
    ASSUME_TAC THENL
   [SUBGOAL_THEN `ebv_in D (E:A->A->bool) B leq (((2|->a)v) 2) (((2|->a)v) 1)
        (bvalf D E B leq ((2|->a)v) (2 %% 1))` MP_TAC THENL
     [MATCH_MP_TAC BVALF_MEM THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN `((2|->a)(v:num->A)) 2 = (a:A) /\ ((2|->a)v) 1 = a1c`
      (CONJUNCTS_THEN SUBST1_TAC) THENL
     [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC]; ALL_TAC] THEN
  SUBGOAL_THEN
    `(bvalf D (E:A->A->bool) B leq ((2|->a)v)
      (0 %% 2 --> Not (iscard_form 2))) IN D /\
     E (bvalf D E B leq ((2|->a)v) (0 %% 2 --> Not (iscard_form 2))) B`
    STRIP_ASSUME_TAC THENL
   [CONJ_TAC THENL [MATCH_MP_TAC BVALF_IND; MATCH_MP_TAC BVALF_IN_B] THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`onebee:A`;`a1:A`;
                `a1c:A`;`a:A`;
                `bvalf D (E:A->A->bool) B leq ((2|->a)v) (2 %% 1)`;
     `bvalf D (E:A->A->bool) B leq ((2|->a)v)
      (0 %% 2 --> Not (iscard_form 2))`]
     ECHECK_IN_LE_SUP) THEN
  ANTS_TAC THENL
   [REPEAT CONJ_TAC THEN TRY(FIRST_ASSUM ACCEPT_TAC) THEN
    MAP_EVERY X_GEN_TAC [`c:A`;`vc:A`;`ec:A`] THEN STRIP_TAC THEN
    SUBGOAL_THEN `(c:A) IN D /\ (vc:A) IN D` STRIP_ASSUME_TAC THENL
     [ASM_MESON_TAC[ECHECK_IMP]; ALL_TAC] THEN
    SUBGOAL_THEN `eordinal D (E:A->A->bool) c` ASSUME_TAC THENL
     [MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`a1:A`;`c:A`]
                   EORDINAL_MEMBER) THEN
      ASM_REWRITE_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN `bname D (E:A->A->bool) B vc` ASSUME_TAC THENL
     [MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`onebee:A`;`B:A`;
                          `c:A`;`vc:A`]
                   ECHECK_IS_BNAME) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN `(E:A->A->bool) (ec:A) (B:A)` ASSUME_TAC THENL
     [MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`a:A`;
                          `vc:A`;`ec:A`]
                   EBV_EQ_IN_B) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN `valuation D ((2|->vc) (v:num->A)) /\
                  (!i. bname D (E:A->A->bool) B (((2|->vc)v) i))`
      STRIP_ASSUME_TAC THENL
      [CONJ_TAC THENL
       [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[];
        MATCH_MP_TAC BNAMEVAL_VALMOD THEN ASM_REWRITE_TAC[]]; ALL_TAC] THEN
    SUBGOAL_THEN `((2|->vc)(v:num->A)) 0 = omc /\ ((2|->vc)v) 2 = vc`
      STRIP_ASSUME_TAC THENL
      [SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER; ARITH_EQ] THEN ASM_REWRITE_TAC[];
       ALL_TAC] THEN
    SUBGOAL_THEN `etop D (E:A->A->bool) B leq
       (bvalf D E B leq ((2|->vc)v) (0 %% 2 --> Not (iscard_form 2)))`
      ASSUME_TAC THENL
      [MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`onebee:A`;
                           `om:A`;`omc:A`;
                           `a1:A`;`c:A`;`vc:A`;`(2|->vc)(v:num->A)`;`bot:A`]
          IMPL_OMNC_TOP) THEN
      REPEAT CONJ_TAC THEN TRY(FIRST_ASSUM ACCEPT_TAC) THEN ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    SUBGOAL_THEN `emeet D (E:A->A->bool) B leq ec
       (bvalf D E B leq ((2|->vc)v) (0 %% 2 --> Not (iscard_form 2))) ec`
      ASSUME_TAC THENL
      [MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
         `bvalf D (E:A->A->bool) B leq ((2|->vc)v)
          (0 %% 2 --> Not (iscard_form 2))`;`ec:A`]
         EMEET_TOP) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN `ebv_eq D (E:A->A->bool) B leq vc a ec` ASSUME_TAC THENL
     [MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`a:A`;
                          `vc:A`;`ec:A`]
                   EBV_EQ_SYM) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    MATCH_MP_TAC(ISPECL[`0 %% 2 --> Not (iscard_form 2)`;`D:A->bool`;
                        `E:A->A->bool`;`B:A`;
                        `leq:A`;`v:num->A`;`2`;`vc:A`;`a:A`;`ec:A`;`ec:A`]
         BVAL_SUBST_CONG) THEN
    ASM_REWRITE_TAC[];
    DISCH_THEN ACCEPT_TAC]);;

(* SUCCARD_CHECK_TOP (A2): [[succard_form 1 0]]_{0:=omc,1:=a1c} = top.
   succard_form 1 0 = iscard_form 1 && 0%%1 && !!- 2 1 (0%%2 -->
     Not(iscard_form 2)).
   Wrap: BVALF_AND_TOP x2 over ISCARD_CHECK_TOP (A2a), A2B_MEMTOP (A2b),
   SUCCARD_NC_TOP (A2c). *)
let SUCCARD_CHECK_TOP = prove
 (`!D (E:A->A->bool) P leqp B leq bp onebee om omc a1 a1c v bot.
      model D E ZF_AX /\ (!u:A. u IN D ==> elmem D E u) /\
      eleqp D E P leqp /\ eroset D E P leqp B /\ eincl D E B leq /\
        ebplus D E B bp /\
      ecba D E B leq /\ eccc D E bp leq /\
      B IN D /\ leq IN D /\ onebee IN D /\ E onebee B /\
        etop D E B leq onebee /\
      eomega D E om /\ echeck D E onebee om omc /\ omc IN D /\
      a1 IN D /\ eordinal D E a1 /\ ecardinal D E a1 /\ E om a1 /\
      ~(?e. einj D E e a1 om) /\
      (!c'. c' IN D /\ E c' a1 ==> ~(ecardinal D E c' /\ E om c')) /\
      echeck D E onebee a1 a1c /\ a1c IN D /\
      valuation D v /\ (!i. bname D E B (v i)) /\ v 0 = omc /\ v 1 = a1c /\
      bot IN D /\ ebot D E B leq bot
      ==> etop D E B leq (bvalf D E B leq v (succard_form 1 0))`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  REWRITE_TAC[succard_form] THEN REWRITE_TAC[ARITH_RULE `MAX 1 0 = 1`] THEN
  CONV_TAC NUM_REDUCE_CONV THEN
  MP_TAC(ISPECL[`iscard_form 1`;
                `(0 %% 1) && !!- 2 1 (0 %% 2 --> Not (iscard_form 2))`;
                `D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`v:num->A`]
        BVALF_AND_TOP) THEN
  ANTS_TAC THENL
  [ASM_REWRITE_TAC[]; DISCH_THEN(fun th -> REWRITE_TAC[th])] THEN
  CONJ_TAC THENL
   [MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`P:A`;`leqp:A`;`B:A`;
                        `leq:A`;`bp:A`;
                        `onebee:A`;`om:A`;`a1:A`;`a1c:A`;`v:num->A`;`bot:A`]
                  ISCARD_CHECK_TOP) THEN
    REPEAT CONJ_TAC THEN TRY(FIRST_ASSUM ACCEPT_TAC) THEN ASM_REWRITE_TAC[];
    MP_TAC(ISPECL[`0 %% 1`;`!!- 2 1 (0 %% 2 --> Not (iscard_form 2))`;
       `D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`v:num->A`] BVALF_AND_TOP) THEN
    ANTS_TAC THENL
    [ASM_REWRITE_TAC[]; DISCH_THEN(fun th -> REWRITE_TAC[th])] THEN
    CONJ_TAC THENL
     [MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`onebee:A`;
                          `om:A`;`omc:A`;
                          `a1:A`;`a1c:A`;`v:num->A`] A2B_MEMTOP) THEN
      REPEAT CONJ_TAC THEN TRY(FIRST_ASSUM ACCEPT_TAC) THEN ASM_REWRITE_TAC[];
      MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`onebee:A`;
                          `om:A`;`omc:A`;
                          `a1:A`;`a1c:A`;`v:num->A`;`bot:A`]
         SUCCARD_NC_TOP) THEN
      REPEAT CONJ_TAC THEN TRY(FIRST_ASSUM ACCEPT_TAC) THEN
      ASM_REWRITE_TAC[]]]);;

(* ===================================================================== *)
(* CH_CORE : [[ch_ax]] = bot.  Final F7 assembly.                          *)
(*   ch_ax = !! 0 (!! 1 (!! 2 (omega_form 0 && succard_form 1 0 &&         *)
(*                             pow_form 2 0 --> bijform 1 2))).            *)
(*   Pin v 0=omc, v 1=a1c, v 2=pw; apply A1 (omega), A2 (succard),         *)
(*   A3 (pow) at v -> [[ANT]]=top=onebee; B (bijform 1 2)=bot; EBIMP_TOP_ANT*)
(*   collapses [[ANT-->bijform]] to bot; the three !! peel to the body via  *)
(*   BVALF_ALL_LB as no-op valmods (v already has slots 0,1,2); ELE_BOT.   *)
(* ===================================================================== *)
let CH_CORE = prove
 (`!D (E:A->A->bool) P leqp B leq bp onebee om omc a1 a1c a2 a2c pw FS
   realfn cr v bot.
      model D E ZF_AX /\ (!u:A. u IN D ==> elmem D E u) /\
      eleqp D E P leqp /\ eroset D E P leqp B /\ eincl D E B leq /\
        ebplus D E B bp /\
      ecba D E B leq /\ eccc D E bp leq /\
      B IN D /\ leq IN D /\ onebee IN D /\ E onebee B /\
        etop D E B leq onebee /\
      eomega D E om /\ echeck D E onebee om omc /\ omc IN D /\
      a1 IN D /\ eordinal D E a1 /\ ecardinal D E a1 /\ E om a1 /\
      echeck D E onebee a1 a1c /\ a1c IN D /\
      ~(?e. einj D E e a1 om) /\
      (!c'. c' IN D /\ E c' a1 ==> ~(ecardinal D E c' /\ E om c')) /\
      a2 IN D /\ eordinal D E a2 /\ echeck D E onebee a2 a2c /\ a2c IN D /\
      ~(?e. einj D E e a2 a1) /\
      cr IN D /\ ecross D E a1 a2 cr /\
      realfn IN D /\ eisfun D E realfn /\
      (!a. a IN D /\ E a a2
           ==> ?rd. rd IN D /\ eapply D E realfn a rd /\ bname D E B rd) /\
      (!a. a IN D /\ E a a2
           ==> ?rd. eapply D E realfn a rd /\ bname D E B rd /\ rd IN D /\
                    etop D E B leq
                      (bvalf D E B leq ((5 |-> rd) v) (5 %% 2))) /\
      (!b1 b2 rd1 rd2 e.
           b1 IN D /\ b2 IN D /\ rd1 IN D /\ rd2 IN D /\ e IN D /\
           E b1 a2 /\ E b2 a2 /\ ~(b1 = b2) /\
           eapply D E realfn b1 rd1 /\ eapply D E realfn b2 rd2 /\
           ebv_eq D E B leq rd1 rd2 e ==> ebot D E B leq e) /\
      pw IN D /\ bname D E B pw /\ eisfun D E pw /\ FS IN D /\
      (!f. f IN D /\ E f FS ==> bname D E B f) /\
      (!f q. f IN D /\ E f FS /\ esubval D E B leq omc f q ==>
       eapply D E pw f q) /\
      (!f. f IN D ==> (eindom D E pw f <=> E f FS)) /\
      (!f. f IN D /\ bname D E B f /\ eisfun D E f /\
           (!w. w IN D ==>
            (eindom D E f w <=> eindom D E omc w)) ==> E f FS) /\
      valuation D v /\ (!i. bname D E B (v i)) /\
      v 0 = omc /\ v 1 = a1c /\ v 2 = pw /\
      bot IN D /\ ebot D E B leq bot
      ==> bvalf D E B leq v ch_ax = bot`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `(om:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[ECHECK_IMP]; ALL_TAC] THEN
  SUBGOAL_THEN `ebalg D (E:A->A->bool) B leq /\ eporder D E B leq`
    STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[ECBA_IMP_BALG; ECBA_IMP_PORDER]; ALL_TAC] THEN
  SUBGOAL_THEN `bname D (E:A->A->bool) B omc` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`onebee:A`;`B:A`;
                        `om:A`;`omc:A`]
                 ECHECK_IS_BNAME) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `bname D (E:A->A->bool) B a1c` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`onebee:A`;`B:A`;
                        `a1:A`;`a1c:A`]
                 ECHECK_IS_BNAME) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* ---- A1 : [[omega_form 0]] = top ---- *)
  SUBGOAL_THEN `etop D (E:A->A->bool) B leq (bvalf D E B leq v (omega_form 0))`
    ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`onebee:A`;
                        `om:A`;`omc:A`;
                        `v:num->A`] BVALF_OMEGA_FORM_CHECK_TOP) THEN
    REPEAT CONJ_TAC THEN TRY(FIRST_ASSUM ACCEPT_TAC) THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  (* ---- A2 : [[succard_form 1 0]] = top ---- *)
  SUBGOAL_THEN
    `etop D (E:A->A->bool) B leq (bvalf D E B leq v (succard_form 1 0))`
    ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`P:A`;`leqp:A`;`B:A`;
                        `leq:A`;`bp:A`;
                        `onebee:A`;`om:A`;`omc:A`;`a1:A`;`a1c:A`;`v:num->A`;
                        `bot:A`] SUCCARD_CHECK_TOP) THEN
    REPEAT CONJ_TAC THEN TRY(FIRST_ASSUM ACCEPT_TAC) THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  (* ---- A3 : [[pow_form 2 0]] = top ---- *)
  SUBGOAL_THEN `etop D (E:A->A->bool) B leq (bvalf D E B leq v (pow_form 2 0))`
    ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`v:num->A`;
                        `omc:A`;`FS:A`;
                        `pw:A`] BVALF_POW_FORM_TOP) THEN
    REPEAT CONJ_TAC THEN TRY(FIRST_ASSUM ACCEPT_TAC) THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) bot B` ASSUME_TAC THENL
   [ASM_MESON_TAC[ebot]; ALL_TAC] THEN
  (* ---- [[ANT]] = top ---- *)
  SUBGOAL_THEN `etop D (E:A->A->bool) B leq
     (bvalf D E B leq v (succard_form 1 0 && pow_form 2 0))` ASSUME_TAC THENL
   [MP_TAC(ISPECL[`succard_form 1 0`;`pow_form 2 0`;`D:A->bool`;`E:A->A->bool`;
                  `B:A`;`leq:A`;
                  `v:num->A`] BVALF_AND_TOP) THEN
    ANTS_TAC THENL
    [ASM_REWRITE_TAC[]; DISCH_THEN(fun th -> REWRITE_TAC[th])] THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `etop D (E:A->A->bool) B leq
     (bvalf D E B leq v (omega_form 0 && succard_form 1 0 && pow_form 2 0))`
    ASSUME_TAC THENL
   [MP_TAC(ISPECL[`omega_form 0`;`succard_form 1 0 && pow_form 2 0`;
                  `D:A->bool`;`E:A->A->bool`;
                  `B:A`;`leq:A`;`v:num->A`] BVALF_AND_TOP) THEN
    ANTS_TAC THENL
    [ASM_REWRITE_TAC[]; DISCH_THEN(fun th -> REWRITE_TAC[th])] THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* ---- [[ANT]] = onebee ---- *)
  SUBGOAL_THEN `bvalf D (E:A->A->bool) B leq v
     (omega_form 0 && succard_form 1 0 && pow_form 2 0) = onebee`
    ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
       `bvalf D (E:A->A->bool) B leq v
        (omega_form 0 && succard_form 1 0 && pow_form 2 0)`;
       `onebee:A`] ETOP_UNIQUE) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* ---- [[bijform 1 2]] = bot : B ---- *)
  SUBGOAL_THEN `bvalf D (E:A->A->bool) B leq v (bijform 1 2) = bot`
    ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`P:A`;`leqp:A`;`om:A`;
                        `bp:A`;`onebee:A`;
                        `B:A`;`leq:A`;`realfn:A`;`a1:A`;`a2:A`;`cr:A`;`a1c:A`;
                        `a2c:A`;`bot:A`;`v:num->A`]
       BIJFORM_12_BOT) THEN
    REPEAT CONJ_TAC THEN TRY(FIRST_ASSUM ACCEPT_TAC) THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  (* ---- memberships for the body value ---- *)
  SUBGOAL_THEN `(bvalf D (E:A->A->bool) B leq v (bijform 1 2)) IN D /\
                E (bvalf D E B leq v (bijform 1 2)) B` STRIP_ASSUME_TAC THENL
   [CONJ_TAC THENL [MATCH_MP_TAC BVALF_IND; MATCH_MP_TAC BVALF_IN_B] THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* ---- ebimp onebee [[bijform]] [[ANT-->bijform]] ---- *)
  SUBGOAL_THEN
    `ebimp D (E:A->A->bool) B leq onebee (bvalf D E B leq v (bijform 1 2))
     (bvalf D E B leq v
        (omega_form 0 && succard_form 1 0 && pow_form 2 0 --> bijform 1 2))`
      ASSUME_TAC THENL
   [UNDISCH_TAC `bvalf D (E:A->A->bool) B leq v
       (omega_form 0 && succard_form 1 0 && pow_form 2 0) = onebee` THEN
    DISCH_THEN(SUBST1_TAC o SYM) THEN
    MATCH_MP_TAC(ISPECL[`omega_form 0 && succard_form 1 0 && pow_form 2 0`;
                        `bijform 1 2`;
                        `D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`v:num->A`]
         BVALF_IMP) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* ---- [[ANT --> bijform 1 2]] = bot (EBIMP_TOP_ANT) ---- *)
  SUBGOAL_THEN `bvalf D (E:A->A->bool) B leq v
     (omega_form 0 && succard_form 1 0 && pow_form 2 0 --> bijform 1 2) = bot`
    ASSUME_TAC THENL
   [SUBGOAL_THEN `bvalf D (E:A->A->bool) B leq v
       (omega_form 0 && succard_form 1 0 && pow_form 2 0 --> bijform 1 2) =
       bvalf D E B leq v (bijform 1 2)` SUBST1_TAC THENL
     [MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`onebee:A`;
         `bvalf D (E:A->A->bool) B leq v (bijform 1 2)`;
         `bvalf D (E:A->A->bool) B leq v
            (omega_form 0 && succard_form 1 0 && pow_form 2 0 -->
             bijform 1 2)`]
         EBIMP_TOP_ANT) THEN ASM_REWRITE_TAC[];
      FIRST_ASSUM ACCEPT_TAC]; ALL_TAC] THEN
  (* ---- no-op valmods for the peel ---- *)
  SUBGOAL_THEN
    `(0 |-> omc) (v:num->A) = v /\ (1 |-> a1c) v = v /\ (2 |-> pw) v = v`
    STRIP_ASSUME_TAC THENL
   [REWRITE_TAC[FUN_EQ_THM; VALMOD] THEN REPEAT CONJ_TAC THEN GEN_TAC THEN
    COND_CASES_TAC THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* ---- peel ch_ax to the body IMPL via BVALF_ALL_LB x3 (no-op valmods) *)
  (* ---- *)
  REWRITE_TAC[ch_ax] THEN
  (* memberships of the four peel values *)
  SUBGOAL_THEN
   `(bvalf D (E:A->A->bool) B leq v (!! 0 (!! 1 (!! 2
       (omega_form 0 && succard_form 1 0 && pow_form 2 0 -->
        bijform 1 2))))) IN D /\
    (bvalf D E B leq v (!! 1 (!! 2
       (omega_form 0 && succard_form 1 0 && pow_form 2 0 -->
        bijform 1 2)))) IN D /\
    (bvalf D E B leq v (!! 2
       (omega_form 0 && succard_form 1 0 && pow_form 2 0 -->
        bijform 1 2))) IN D /\
    (bvalf D E B leq v
       (omega_form 0 && succard_form 1 0 && pow_form 2 0 -->
        bijform 1 2)) IN D`
    STRIP_ASSUME_TAC THENL
   [REPEAT CONJ_TAC THEN MATCH_MP_TAC BVALF_IND THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `E (bvalf D (E:A->A->bool) B leq v (!! 0 (!! 1 (!! 2
       (omega_form 0 && succard_form 1 0 && pow_form 2 0 -->
        bijform 1 2))))) B /\
    E (bvalf D E B leq v (!! 1 (!! 2
       (omega_form 0 && succard_form 1 0 && pow_form 2 0 -->
        bijform 1 2)))) B /\
    E (bvalf D E B leq v (!! 2
       (omega_form 0 && succard_form 1 0 && pow_form 2 0 -->
        bijform 1 2))) B /\
    E (bvalf D E B leq v
       (omega_form 0 && succard_form 1 0 && pow_form 2 0 --> bijform 1 2)) B`
    STRIP_ASSUME_TAC THENL
   [REPEAT CONJ_TAC THEN MATCH_MP_TAC BVALF_IN_B THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  (* three single-level peels (no-op valmods) *)
  SUBGOAL_THEN `erel D (E:A->A->bool) leq
     (bvalf D E B leq v (!! 0 (!! 1 (!! 2
        (omega_form 0 && succard_form 1 0 && pow_form 2 0 --> bijform 1 2)))))
     (bvalf D E B leq v (!! 1 (!! 2
        (omega_form 0 && succard_form 1 0 && pow_form 2 0 --> bijform 1 2))))`
    ASSUME_TAC THENL
   [MP_TAC(ISPECL[`0`;
       `!! 1 (!! 2
              (omega_form 0 && succard_form 1 0 && pow_form 2 0 -->
               bijform 1 2))`;
       `D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`v:num->A`;`omc:A`]
         BVALF_ALL_LB) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq
     (bvalf D E B leq v (!! 1 (!! 2
        (omega_form 0 && succard_form 1 0 && pow_form 2 0 --> bijform 1 2))))
     (bvalf D E B leq v (!! 2
        (omega_form 0 && succard_form 1 0 && pow_form 2 0 --> bijform 1 2)))`
    ASSUME_TAC THENL
   [MP_TAC(ISPECL[`1`;
       `!! 2 (omega_form 0 && succard_form 1 0 && pow_form 2 0 -->
              bijform 1 2)`;
       `D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`v:num->A`;`a1c:A`]
           BVALF_ALL_LB) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq
     (bvalf D E B leq v (!! 2
        (omega_form 0 && succard_form 1 0 && pow_form 2 0 --> bijform 1 2)))
     (bvalf D E B leq v
        (omega_form 0 && succard_form 1 0 && pow_form 2 0 --> bijform 1 2))`
    ASSUME_TAC THENL
   [MP_TAC(ISPECL[`2`;
       `omega_form 0 && succard_form 1 0 && pow_form 2 0 --> bijform 1 2`;
       `D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`v:num->A`;`pw:A`]
          BVALF_ALL_LB) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* chain to bot: [[F2]]<=bot, then [[F1]]<=bot, then [[F0=ch_ax]]<=bot *)
  SUBGOAL_THEN `erel D (E:A->A->bool) leq
     (bvalf D E B leq v (!! 2
        (omega_form 0 && succard_form 1 0 && pow_form 2 0 --> bijform 1 2)))
       bot` ASSUME_TAC THENL
   [SUBST1_TAC(SYM(ASSUME `bvalf D (E:A->A->bool) B leq v
       (omega_form 0 && succard_form 1 0 && pow_form 2 0 -->
        bijform 1 2) = bot`)) THEN
    FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq
     (bvalf D E B leq v (!! 1 (!! 2
        (omega_form 0 && succard_form 1 0 && pow_form 2 0 --> bijform 1 2))))
       bot` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`]
                 EPORDER_TRANS) THEN
    EXISTS_TAC `bvalf D (E:A->A->bool) B leq v (!! 2
       (omega_form 0 && succard_form 1 0 && pow_form 2 0 -->
        bijform 1 2))` THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) leq
     (bvalf D E B leq v (!! 0 (!! 1 (!! 2
        (omega_form 0 && succard_form 1 0 && pow_form 2 0 --> bijform 1 2)))))
       bot` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`]
                 EPORDER_TRANS) THEN
    EXISTS_TAC `bvalf D (E:A->A->bool) B leq v (!! 1 (!! 2
       (omega_form 0 && succard_form 1 0 && pow_form 2 0 -->
        bijform 1 2)))` THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;
     `bvalf D (E:A->A->bool) B leq v (!! 0 (!! 1 (!! 2
        (omega_form 0 && succard_form 1 0 && pow_form 2 0 -->
         bijform 1 2))))`;`bot:A`]
     ELE_BOT) THEN
  ASM_REWRITE_TAC[]);;

(* NOT_CH_TOP : [[not_ch_ax]] = top.  not_ch_ax = Not ch_ax;
BVALF_NOT_TOP + CH_CORE
   ([[ch_ax]]=bot,
   i.e. ebot) give etop [[not_ch_ax]].  Same ~43-hyp Cohen-over-L CTX
   as CH_CORE; consumed by F9 (top in U via LOS). *)
let NOT_CH_TOP = prove
 (`!D (E:A->A->bool) P leqp B leq bp onebee om omc a1 a1c a2 a2c pw FS
   realfn cr v bot.
      model D E ZF_AX /\ (!u:A. u IN D ==> elmem D E u) /\
      eleqp D E P leqp /\ eroset D E P leqp B /\ eincl D E B leq /\
        ebplus D E B bp /\
      ecba D E B leq /\ eccc D E bp leq /\
      B IN D /\ leq IN D /\ onebee IN D /\ E onebee B /\
        etop D E B leq onebee /\
      eomega D E om /\ echeck D E onebee om omc /\ omc IN D /\
      a1 IN D /\ eordinal D E a1 /\ ecardinal D E a1 /\ E om a1 /\
      echeck D E onebee a1 a1c /\ a1c IN D /\
      ~(?e. einj D E e a1 om) /\
      (!c'. c' IN D /\ E c' a1 ==> ~(ecardinal D E c' /\ E om c')) /\
      a2 IN D /\ eordinal D E a2 /\ echeck D E onebee a2 a2c /\ a2c IN D /\
      ~(?e. einj D E e a2 a1) /\
      cr IN D /\ ecross D E a1 a2 cr /\
      realfn IN D /\ eisfun D E realfn /\
      (!a. a IN D /\ E a a2
           ==> ?rd. rd IN D /\ eapply D E realfn a rd /\ bname D E B rd) /\
      (!a. a IN D /\ E a a2
           ==> ?rd. eapply D E realfn a rd /\ bname D E B rd /\ rd IN D /\
                    etop D E B leq
                      (bvalf D E B leq ((5 |-> rd) v) (5 %% 2))) /\
      (!b1 b2 rd1 rd2 e.
           b1 IN D /\ b2 IN D /\ rd1 IN D /\ rd2 IN D /\ e IN D /\
           E b1 a2 /\ E b2 a2 /\ ~(b1 = b2) /\
           eapply D E realfn b1 rd1 /\ eapply D E realfn b2 rd2 /\
           ebv_eq D E B leq rd1 rd2 e ==> ebot D E B leq e) /\
      pw IN D /\ bname D E B pw /\ eisfun D E pw /\ FS IN D /\
      (!f. f IN D /\ E f FS ==> bname D E B f) /\
      (!f q. f IN D /\ E f FS /\ esubval D E B leq omc f q ==>
       eapply D E pw f q) /\
      (!f. f IN D ==> (eindom D E pw f <=> E f FS)) /\
      (!f. f IN D /\ bname D E B f /\ eisfun D E f /\
           (!w. w IN D ==>
            (eindom D E f w <=> eindom D E omc w)) ==> E f FS) /\
      valuation D v /\ (!i. bname D E B (v i)) /\
      v 0 = omc /\ v 1 = a1c /\ v 2 = pw /\
      bot IN D /\ ebot D E B leq bot
      ==> etop D E B leq (bvalf D E B leq v not_ch_ax)`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  REWRITE_TAC[not_ch_ax] THEN
  MP_TAC(ISPECL[`ch_ax`;`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`v:num->A`]
         BVALF_NOT_TOP) THEN
  ANTS_TAC THENL
  [ASM_REWRITE_TAC[]; DISCH_THEN(fun th -> REWRITE_TAC[th])] THEN
  SUBGOAL_THEN `bvalf D (E:A->A->bool) B leq v ch_ax = bot` SUBST1_TAC THENL
   [MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`P:A`;`leqp:A`;`B:A`;
                        `leq:A`;`bp:A`;
                        `onebee:A`;`om:A`;`omc:A`;`a1:A`;`a1c:A`;`a2:A`;
                        `a2c:A`;`pw:A`;`FS:A`;`realfn:A`;
                        `cr:A`;`v:num->A`;`bot:A`] CH_CORE) THEN
    REPEAT CONJ_TAC THEN TRY(FIRST_ASSUM ACCEPT_TAC) THEN ASM_REWRITE_TAC[];
    ASM_REWRITE_TAC[]]);;

(* FORCE_NOT_CH_FROM_FORCED (F9b): given a Cohen cba B/leq with an
  ultrafilter U and
   [[not_ch_ax]]=top at every bname valuation,
   the quotient models not_ch_ax on top of ZFC.
   Reuses FORCE_ZFC_OVER_VL_U (ZFC) + QSAT_AX[not_ch_ax] (the extra axiom). *)
let FORCE_NOT_CH_FROM_FORCED = prove
 (`!D (E:A->A->bool) B leq U.
      model D E ZF_AX /\ (!u:A. u IN D ==> elmem D E u) /\
      B IN D /\ leq IN D /\ ecba D E B leq /\ U IN D /\ eultra D E B leq U /\
      (!c. valuation D c /\ (!i. bname D E B (c i))
           ==> etop D E B leq (bvalf D E B leq c not_ch_ax))
      ==> model (qdom D E B leq U) (qmem D E B leq U)
            (not_ch_ax INSERT (choice_ax INSERT ZF_AX))`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `!v. valuation (qdom D (E:A->A->bool) B leq U) v
                    ==> holds (qdom D E B leq U) (qmem D E B leq U)
                      v not_ch_ax`
    ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`U:A`;
                        `not_ch_ax`] QSAT_AX) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`U:A`]
         FORCE_ZFC_OVER_VL_U) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  REWRITE_TAC[model; satisfies; IN_INSERT] THEN STRIP_TAC THEN
  CONJ_TAC THENL
   [FIRST_ASSUM ACCEPT_TAC;
    MAP_EVERY X_GEN_TAC [`w:num->A`;`p:form`] THEN STRIP_TAC THEN
    ASM_MESON_TAC[]]);;

(* COHEN_CBA_FULL_EXISTS (F9 phase A): construct the full Cohen
   algebra at codomain aleph_2 with a 2-element value set tw -- the
     cba B/inclB,
   its bp, bot/top, ccc, plus om, a1=aleph_1, a2=aleph_2 (succ cards) and the
   cross structures ii=a2xom, ci=iixtw that realfn will need. *)
let COHEN_CBA_FULL_EXISTS = prove
 (`!D (E:A->A->bool).
     model D E ZF_AX /\ (!u:A. u IN D ==> elmem D E u)
     ==> ?om a1 a2 tw onetw ztw ii ci P leqp B inclB bp bot.
           eomega D E om /\
           ecardinal D E a1 /\ ecardinal D E a2 /\
           eordinal D E a1 /\ eordinal D E a2 /\
           E om a1 /\ E a1 a2 /\
           (!c'. c' IN D /\ E c' a1 ==> ~(ecardinal D E c' /\ E om c')) /\
           efin D E tw /\ E onetw tw /\ E ztw tw /\ ~(onetw = ztw) /\
           ecross D E a2 om ii /\ ecross D E ii tw ci /\ ecohenp D E ci om P /\
           eleqp D E P leqp /\ eroset D E P leqp B /\ eincl D E B inclB /\
           ebplus D E B bp /\ ecba D E B inclB /\ eccc D E bp inclB /\
           ebot D E B inclB bot /\ etop D E B inclB P /\ ~(bot = P) /\
           B IN D /\ inclB IN D /\ P IN D /\ om IN D /\
           onetw IN D /\ ztw IN D`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  (* om *)
  MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`] EOMEGA_EXISTS) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `om:A`) THEN
  SUBGOAL_THEN `(om:A) IN D` ASSUME_TAC THENL
   [FIRST_ASSUM(ACCEPT_TAC o MATCH_MP EOMEGA_IN); ALL_TAC] THEN
  (* a1, a2 = successor cardinals *)
  MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`om:A`] ESUCCARD2_EXISTS) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `a1:A` (X_CHOOSE_THEN `a2:A` STRIP_ASSUME_TAC)) THEN
  SUBGOAL_THEN `eordinal D (E:A->A->bool) a1` ASSUME_TAC THENL
   [MP_TAC(ASSUME `ecardinal D (E:A->A->bool) a1`) THEN
    REWRITE_TAC[ecardinal; ecardof] THEN STRIP_TAC THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `eordinal D (E:A->A->bool) a2` ASSUME_TAC THENL
   [MP_TAC(ASSUME `ecardinal D (E:A->A->bool) a2`) THEN
    REWRITE_TAC[ecardinal; ecardof] THEN STRIP_TAC THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  (* tw = {e0, {e0}} : 2-element finite set *)
  MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`] EEMPTY_EXISTS) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `e0:A`) THEN
  SUBGOAL_THEN `(e0:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[EEMPTY_IN]; ALL_TAC] THEN
  MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`e0:A`;`e0:A`] EADJOIN_EXISTS) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_TAC `q1:A`) THEN
  SUBGOAL_THEN `(q1:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[EADJOIN_IN]; ALL_TAC] THEN
  MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`q1:A`;`q1:A`] EADJOIN_EXISTS) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_TAC `q2:A`) THEN
  SUBGOAL_THEN `(q2:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[EADJOIN_IN]; ALL_TAC] THEN
  (* membership facts for tw:=q2, onetw:=q1, ztw:=e0 *)
  MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`e0:A`;`e0:A`;`q1:A`]
         EADJOIN_MEM) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC (LABEL_TAC "q1mem")) THEN
  MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`q1:A`;`q1:A`;`q2:A`]
         EADJOIN_MEM) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC (LABEL_TAC "q2mem")) THEN
  SUBGOAL_THEN `(E:A->A->bool) e0 q1` ASSUME_TAC THENL
   [USE_THEN "q1mem" (MP_TAC o SPEC `e0:A`) THEN ASM_MESON_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) q1 q2` ASSUME_TAC THENL
   [USE_THEN "q2mem" (MP_TAC o SPEC `q1:A`) THEN ASM_MESON_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) e0 q2` ASSUME_TAC THENL
   [USE_THEN "q2mem" (MP_TAC o SPEC `e0:A`) THEN ASM_MESON_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `~(q1:A = e0)` ASSUME_TAC THENL
   [DISCH_TAC THEN UNDISCH_TAC `eempty D (E:A->A->bool) e0` THEN
    REWRITE_TAC[eempty] THEN ASM_MESON_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `efin D (E:A->A->bool) (q2:A)` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`q1:A`;`q1:A`;`q2:A`]
                 EFIN_ADJOIN) THEN
    ASM_REWRITE_TAC[] THEN
    MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`e0:A`;`e0:A`;`q1:A`]
                 EFIN_ADJOIN) THEN
    ASM_REWRITE_TAC[] THEN
    MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`e0:A`] EFIN_EMPTY) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* ii = a2 x om *)
  MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`a2:A`;`om:A`] ECROSS_EXISTS) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_TAC `ii:A`) THEN
  SUBGOAL_THEN `(ii:A) IN D` ASSUME_TAC THENL
   [FIRST_ASSUM(ACCEPT_TAC o CONJUNCT1 o GEN_REWRITE_RULE I [ecross]);
    ALL_TAC] THEN
  (* Cohen cba at (ii, tw, om) *)
  MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`ii:A`;`q2:A`;`om:A`]
         COHEN_CBA_EXISTS) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `ci:A` (X_CHOOSE_THEN `P:A` (X_CHOOSE_THEN `leqp:A`
    (X_CHOOSE_THEN `B:A` (X_CHOOSE_THEN `inclB:A` (X_CHOOSE_THEN `z:A`
    STRIP_ASSUME_TAC)))))) THEN
  SUBGOAL_THEN `(P:A) IN D` ASSUME_TAC THENL
   [FIRST_ASSUM(ACCEPT_TAC o CONJUNCT1 o GEN_REWRITE_RULE I [ecohenp]);
    ALL_TAC] THEN
  SUBGOAL_THEN `(B:A) IN D` ASSUME_TAC THENL
   [FIRST_ASSUM(ACCEPT_TAC o CONJUNCT1 o GEN_REWRITE_RULE I [eroset]);
    ALL_TAC] THEN
  SUBGOAL_THEN `(inclB:A) IN D` ASSUME_TAC THENL
   [FIRST_ASSUM(ACCEPT_TAC o CONJUNCT1 o GEN_REWRITE_RULE I [eincl]);
    ALL_TAC] THEN
  (* bp *)
  MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`] EBPLUS_EXISTS) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_TAC `bp:A`) THEN
  (* IN D facts *)
  SUBGOAL_THEN `(B:A) IN D /\ (inclB:A) IN D /\ (P:A) IN D`
    STRIP_ASSUME_TAC THENL
   [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* eccc *)
  SUBGOAL_THEN `eccc D (E:A->A->bool) bp inclB` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`ii:A`;`q2:A`;`ci:A`;
                        `om:A`;`P:A`;
                        `leqp:A`;`B:A`;`bp:A`;`inclB:A`;`a1:A`]
                   COHEN_CBA_CCC) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* assemble *)
  MAP_EVERY EXISTS_TAC
    [`om:A`;`a1:A`;`a2:A`;`q2:A`;`q1:A`;`e0:A`;`ii:A`;`ci:A`;`P:A`;
     `leqp:A`;`B:A`;`inclB:A`;`bp:A`;`z:A`] THEN
  REPEAT CONJ_TAC THEN TRY(FIRST_ASSUM ACCEPT_TAC) THEN ASM_MESON_TAC[]);;

(* EMBF_TOTAL (F9 phase B helper): embf (RO-embedding function over the
  Cohen poset)
   is TOTAL on ci.  This is the hypothesis
     COHEN_REALNAME_EXISTS/REALFN_EXISTS take
   but nothing discharges; proved by mirroring EMBFUN_EXISTS's internal "val"
   (per cv in ci build b0 = e({cv}) via
     ECROSS_MEMBER/COHEN_COORD_COND/COHEN_COORD_EMB,
   b0 satisfies the embf graph b-char by COORDEMB_EQ_EMB) then
     eopair+graph-char. *)
let EMBF_TOTAL = prove
 (`!D (E:A->A->bool) P leqp B ci om ii tw embf.
     model D E ZF_AX /\ eomega D E om /\
     ecross D E ii tw ci /\ ecohenp D E ci om P /\
     eleqp D E P leqp /\ eroset D E P leqp B /\
     leqp IN D /\ B IN D /\ ci IN D /\ P IN D /\ embf IN D /\
     (!z. z IN D
          ==> (E z embf <=>
               ?cv b. cv IN D /\ b IN D /\ E cv ci /\ eopair D E cv b z /\
                      (!q. q IN D
                           ==> (E q b <=>
                                E q P /\
                                (!r. r IN D /\ erel D E leqp r q
                                     ==> ?s. s IN D /\
                                       erel D E leqp s r /\ E cv s)))))
     ==> !cvs. cvs IN D /\ E cvs ci ==> ?b. b IN D /\ eapply D E embf cvs b`,
  REPEAT GEN_TAC THEN
  DISCH_THEN(fun th ->
    MAP_EVERY (fun c -> if is_forall(concl c) && vfree_in `embf:A` (concl c)
                        then LABEL_TAC "gc" c else ASSUME_TAC c)
      (CONJUNCTS th)) THEN
  X_GEN_TAC `cvs:A` THEN STRIP_TAC THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`ii:A`;`tw:A`;`ci:A`;`cvs:A`]
         ECROSS_MEMBER) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `c:A` (X_CHOOSE_THEN `w:A` STRIP_ASSUME_TAC)) THEN
  MP_TAC(ISPECL
         [`D:A->bool`;`E:A->A->bool`;`ii:A`;`tw:A`;`ci:A`;`om:A`;`P:A`;
          `c:A`;`w:A`]
         COHEN_COORD_COND) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `cv2:A`
             (X_CHOOSE_THEN `p1:A` STRIP_ASSUME_TAC)) THEN
  SUBGOAL_THEN `cv2:A = cvs` SUBST_ALL_TAC THENL
   [ASM_MESON_TAC[EOPAIR_UNIQUE]; ALL_TAC] THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`P:A`;`leqp:A`;`B:A`;`p1:A`]
         COHEN_COORD_EMB) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `dp:A` (X_CHOOSE_THEN `b0:A` STRIP_ASSUME_TAC)) THEN
  SUBGOAL_THEN `(dp:A) IN D` ASSUME_TAC THENL
  [ASM_MESON_TAC[edownset]; ALL_TAC] THEN
  SUBGOAL_THEN
   `!q. q IN D
        ==> ((E:A->A->bool) q b0 <=>
             E q P /\
             (!r. r IN D /\ erel D E leqp r q
                  ==> ?s. s IN D /\ erel D E leqp s r /\ E cvs s))`
     ASSUME_TAC THENL
   [SUBGOAL_THEN `esubset D (E:A->A->bool) (b0:A) (P:A) /\
                  eopen D E leqp b0 /\ ereg D E P leqp b0`
      STRIP_ASSUME_TAC THENL
     [FIRST_ASSUM(fun th ->
                  MP_TAC(SPEC `b0:A`
                         (CONJUNCT2 (REWRITE_RULE[eroset] th)))) THEN
      ASM_REWRITE_TAC[]; ALL_TAC] THEN
    X_GEN_TAC `q:A` THEN DISCH_TAC THEN
    ASM_CASES_TAC `(E:A->A->bool) (q:A) (P:A)` THENL
     [MP_TAC(ISPECL
             [`D:A->bool`;`E:A->A->bool`;`P:A`;`leqp:A`;`cvs:A`;`p1:A`;`dp:A`;
              `b0:A`;`q:A`]
             COORDEMB_EQ_EMB) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> ASM_REWRITE_TAC[th]);
      SUBGOAL_THEN `~((E:A->A->bool) (q:A) (b0:A))`
        (fun th -> ASM_REWRITE_TAC[th]) THEN
        ASM_MESON_TAC[esubset]]; ALL_TAC] THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`cvs:A`;`b0:A`] EOPAIR_EXISTS) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `zp:A` ASSUME_TAC) THEN
  SUBGOAL_THEN `(zp:A) IN D` ASSUME_TAC THENL
  [ASM_MESON_TAC[EOPAIR_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) (zp:A) (embf:A)` ASSUME_TAC THENL
   [USE_THEN "gc" (MP_TAC o SPEC `zp:A`) THEN ANTS_TAC THENL
    [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    MAP_EVERY EXISTS_TAC [`cvs:A`;`b0:A`] THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  EXISTS_TAC `b0:A` THEN ASM_REWRITE_TAC[eapply] THEN
  EXISTS_TAC `zp:A` THEN ASM_REWRITE_TAC[]);;

(* EMBF_VAL_IN_B (F9 phase B helper): every embf-value lands in B.
   eapply embf cvs bb -> (graph) bb satisfies the embedding char -> bb = ep
   (EMBF_VAL_IS_EMB) with E ep B (COHEN_COORD_EMB).  Discharges the
     embf-value-in-B
   hyp of COHEN_REALNAME_BNAME / COHEN_REAL_SUBSET_OMEGA. *)
let EMBF_VAL_IN_B = prove
 (`!D (E:A->A->bool) P leqp B ci om ii tw embf.
     model D E ZF_AX /\ eomega D E om /\
     ecross D E ii tw ci /\ ecohenp D E ci om P /\
     eleqp D E P leqp /\ eroset D E P leqp B /\
     leqp IN D /\ B IN D /\ ci IN D /\ P IN D /\ embf IN D /\
     (!z. z IN D
          ==> (E z embf <=>
               ?cv b. cv IN D /\ b IN D /\ E cv ci /\ eopair D E cv b z /\
                      (!q. q IN D
                           ==> (E q b <=>
                                E q P /\
                                (!r. r IN D /\ erel D E leqp r q
                                     ==> ?s. s IN D /\
                                       erel D E leqp s r /\ E cv s)))))
     ==> !cvs bb. cvs IN D /\ bb IN D /\ eapply D E embf cvs bb ==> E bb B`,
  REPEAT GEN_TAC THEN
  DISCH_THEN(fun th ->
    MAP_EVERY (fun c -> if is_forall(concl c) && vfree_in `embf:A` (concl c)
                        then LABEL_TAC "gc" c else ASSUME_TAC c)
      (CONJUNCTS th)) THEN
  MAP_EVERY X_GEN_TAC [`cvs:A`;`bb:A`] THEN STRIP_TAC THEN
  UNDISCH_TAC `eapply D (E:A->A->bool) embf cvs bb` THEN
  REWRITE_TAC[eapply] THEN
  DISCH_THEN(X_CHOOSE_THEN `zp:A` STRIP_ASSUME_TAC) THEN
  SUBGOAL_THEN `(zp:A) IN D` ASSUME_TAC THENL
  [ASM_MESON_TAC[EOPAIR_IN]; ALL_TAC] THEN
  USE_THEN "gc" (MP_TAC o SPEC `zp:A`) THEN ANTS_TAC THENL
  [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(fun th -> MP_TAC(EQ_MP th (ASSUME `(E:A->A->bool) zp embf`))) THEN
  DISCH_THEN(X_CHOOSE_THEN `cv:A` (X_CHOOSE_THEN `b':A` STRIP_ASSUME_TAC)) THEN
  MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`cvs:A`;`bb:A`;`cv:A`;`b':A`;`zp:A`]
         EOPAIR_INJ) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(CONJUNCTS_THEN(SUBST_ALL_TAC o SYM)) THEN
  MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`ii:A`;`tw:A`;`ci:A`;`cvs:A`]
         ECROSS_MEMBER) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `c:A` (X_CHOOSE_THEN `w:A` STRIP_ASSUME_TAC)) THEN
  MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`ii:A`;`tw:A`;`ci:A`;`om:A`;`P:A`;
                `c:A`;`w:A`]
         COHEN_COORD_COND) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `cv2:A`
             (X_CHOOSE_THEN `p1:A` STRIP_ASSUME_TAC)) THEN
  SUBGOAL_THEN `cv2:A = cvs` SUBST_ALL_TAC THENL
   [ASM_MESON_TAC[EOPAIR_UNIQUE]; ALL_TAC] THEN
  MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`P:A`;`leqp:A`;`B:A`;`p1:A`]
         COHEN_COORD_EMB) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `dp:A` (X_CHOOSE_THEN `ep:A` STRIP_ASSUME_TAC)) THEN
  MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`P:A`;`leqp:A`;`cvs:A`;`p1:A`;
                `dp:A`;`bb:A`;`ep:A`]
         EMBF_VAL_IS_EMB) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN SUBST1_TAC THEN ASM_REWRITE_TAC[]);;

let PERALPHA = prove
 (`!D (E:A->A->bool) P leqp ci om embf iibase ii tw onetw B realfn.
     model D E ZF_AX /\ (!u:A. u IN D ==> elmem D E u) /\
     B IN D /\ P IN D /\ E P B /\
     eomega D E om /\ embf IN D /\ eisfun D E embf /\
     ecross D E iibase om ii /\ ecross D E ii tw ci /\
     (!z. z IN D
          ==> (E z embf <=>
               ?cv b. cv IN D /\ b IN D /\ E cv ci /\ eopair D E cv b z /\
                      (!q. q IN D
                           ==> (E q b <=>
                                E q P /\
                                (!r. r IN D /\ erel D E leqp r q
                                     ==> ?s. s IN D /\ erel D E leqp s r /\
                                       E cv s))))) /\
     (!cvs. cvs IN D /\ E cvs ci ==> ?b. b IN D /\ eapply D E embf cvs b) /\
     (!cvs bb. cvs IN D /\ bb IN D /\ eapply D E embf cvs bb ==> E bb B) /\
     onetw IN D /\ E onetw tw /\
     realfn IN D /\
     (!w. w IN D
          ==> (E w realfn <=>
               ?a Y. a IN D /\ Y IN D /\ E a iibase /\ eopair D E a Y w /\
                     (!z. z IN D
                          ==> (E z Y <=>
                               ?n sig b p15 cvs. n IN D /\
                                 sig IN D /\ b IN D /\
                                  p15 IN D /\ cvs IN D /\ E n om /\
                                  eopair D E sig b z /\ echeck D E P n sig /\
                                  eopair D E a n p15 /\
                                    eopair D E p15 onetw cvs /\
                                  eapply D E embf cvs b))))
     ==> !alpha. alpha IN D /\ E alpha iibase
                 ==> ?rd. rd IN D /\ bname D E B rd /\
                   eapply D E realfn alpha rd /\
                          (!z. z IN D
                               ==> (E z rd <=>
                                    ?n sig b p15 cvs. n IN D /\
                                      sig IN D /\ b IN D /\
                                       p15 IN D /\ cvs IN D /\ E n om /\
                                       echeck D E P n sig /\
                                         eopair D E alpha n p15 /\
                                       eopair D E p15 onetw cvs /\
                                         eapply D E embf cvs b /\
                                       eopair D E sig b z))`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN X_GEN_TAC `alpha:A` THEN STRIP_TAC THEN
  MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`P:A`;`leqp:A`;`ci:A`;`om:A`;
                `P:A`;`embf:A`;
                `iibase:A`;`ii:A`;`tw:A`;`alpha:A`;`onetw:A`]
                            COHEN_REALNAME_EXISTS) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `rd:A` STRIP_ASSUME_TAC) THEN
  EXISTS_TAC `rd:A` THEN
  SUBGOAL_THEN `(rd:A) IN D` ASSUME_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  ASM_REWRITE_TAC[] THEN
  SUBGOAL_THEN `bname D (E:A->A->bool) B rd` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`P:A`;`om:A`;
                        `embf:A`;`alpha:A`;
                        `onetw:A`;`rd:A`] COHEN_REALNAME_BNAME) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  ASM_REWRITE_TAC[] THEN
  MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`realfn:A`;`iibase:A`;
     `\a z:A. ?n sig b p15 cvs. n IN D /\ sig IN D /\ b IN D /\
      p15 IN D /\ cvs IN D /\
              E n om /\ eopair D E sig b z /\ echeck D E P n sig /\
                eopair D E a n p15 /\
              eopair D E p15 onetw cvs /\ eapply D E embf cvs b`;
     `alpha:A`;`rd:A`] REALFN_APPLY) THEN
  CONV_TAC(DEPTH_CONV BETA_CONV) THEN
  REPEAT CONJ_TAC THEN TRY(FIRST_ASSUM MATCH_ACCEPT_TAC) THEN
  X_GEN_TAC `z:A` THEN STRIP_TAC THEN
  FIRST_X_ASSUM(fun th -> if is_forall(concl th) && vfree_in `rd:A` (concl th)
                          then MP_TAC(SPEC `z:A` th) else NO_TAC) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  MESON_TAC[]);;

(* REAL_IN_POW (F9 cond2 glue): a Cohen real name rd (subset of om^)
  is a member of
   the power-name pw = P(om^) at Boolean value top.
     COHEN_REAL_SUBSET_OMEGA gives
   [[rd SUBSET om^]] = esubval omc rd = top;
   EBV_IN_POW gives [[rd IN pw]] = esubval omc rd. *)
let REAL_IN_POW = prove
 (`!D (E:A->A->bool) B leq onebee embf alpha onetw om omc rd pw FS.
     model D E ZF_AX /\ ecba D E B leq /\
     B IN D /\ leq IN D /\ onebee IN D /\ E onebee B /\
       etop D E B leq onebee /\
     embf IN D /\ eisfun D E embf /\
     (!cvs' bb'. cvs' IN D /\ bb' IN D /\
      eapply D E embf cvs' bb' ==> E bb' B) /\
     eomega D E om /\ echeck D E onebee om omc /\ omc IN D /\
       bname D E B omc /\
     alpha IN D /\ onetw IN D /\ rd IN D /\ bname D E B rd /\
     (!zz. zz IN D
           ==> (E zz rd <=>
                ?nn sig bq p pc. nn IN D /\ sig IN D /\ bq IN D /\
                  p IN D /\ pc IN D /\
                   E nn om /\ echeck D E onebee nn sig /\
                     eopair D E alpha nn p /\
                   eopair D E p onetw pc /\ eapply D E embf pc bq /\
                     eopair D E sig bq zz)) /\
     pw IN D /\ eisfun D E pw /\ FS IN D /\
     (!f. f IN D /\ E f FS ==> bname D E B f) /\
     (!f q. f IN D /\ E f FS /\ esubval D E B leq omc f q ==>
      eapply D E pw f q) /\
     (!f. f IN D ==> (eindom D E pw f <=> E f FS)) /\
     (!f. f IN D /\ bname D E B f /\ eisfun D E f /\
          (!w. w IN D ==> (eindom D E f w <=> eindom D E omc w)) ==> E f FS)
     ==> !zin. zin IN D /\ ebv_in D E B leq rd pw zin ==> etop D E B leq zin`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN X_GEN_TAC `zin:A` THEN STRIP_TAC THEN
  SUBGOAL_THEN `(om:A) IN D` ASSUME_TAC THENL
   [FIRST_ASSUM(ACCEPT_TAC o MATCH_MP EOMEGA_IN); ALL_TAC] THEN
  MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`omc:A`;`rd:A`]
         ESUBVAL_EXISTS) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `ztx:A` ASSUME_TAC) THEN
  SUBGOAL_THEN `(ztx:A) IN D` ASSUME_TAC THENL
  [ASM_MESON_TAC[ESUBVAL_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `zin:A = ztx` SUBST1_TAC THENL
   [MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`omc:A`;
                        `FS:A`;`rd:A`;
                        `pw:A`;`zin:A`;`ztx:A`] EBV_IN_POW) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`onebee:A`;
                      `embf:A`;`alpha:A`;
                      `onetw:A`;`om:A`;`rd:A`;`omc:A`;`ztx:A`]
      COHEN_REAL_SUBSET_OMEGA) THEN
  ASM_REWRITE_TAC[]);;

(* FV_NOT_CH_012: slots 0,1,2 are not free in not_ch_ax (ch_ax binds them
  with !! 0/1/2).
   All F9 needs for the FV-congruence that generalizes NOT_CH_TOP to any bname
     valuation. *)
let FV_NOT_CH_012 = prove
 (`~(0 IN FV not_ch_ax) /\ ~(1 IN FV not_ch_ax) /\ ~(2 IN FV not_ch_ax)`,
  REWRITE_TAC[not_ch_ax; ch_ax; Not_DEF; omega_form; inductive_form;
              succard_form;
              iscard_form; ordinal_form; transitive_form; linear_form;
              pow_form; subset_form;
              bijform; Forallmem_DEF; Existsmem_DEF] THEN
  REWRITE_TAC[MAX] THEN CONV_TAC NUM_REDUCE_CONV THEN
  REWRITE_TAC[FV; FV_CLAUSES; FV_APPLY_FORM] THEN
  REWRITE_TAC[IN_INSERT; NOT_IN_EMPTY; IN_UNION; IN_DELETE] THEN
  CONV_TAC NUM_REDUCE_CONV THEN REWRITE_TAC[]);;

let NOT_CH_FORCED = prove
 (`!D (E:A->A->bool).
     model D E ZF_AX /\ (!u:A. u IN D ==> elmem D E u)
     ==> ?B leq bot top. B IN D /\ leq IN D /\ ecba D E B leq /\
           bot IN D /\ ebot D E B leq bot /\ top IN D /\ etop D E B leq top /\
           ~(bot = top) /\
           (!c. valuation D c /\ (!i. bname D E B (c i))
                ==> etop D E B leq (bvalf D E B leq c not_ch_ax))`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`] COHEN_CBA_FULL_EXISTS) THEN
  ANTS_TAC THENL
   [REPEAT CONJ_TAC THEN TRY(FIRST_ASSUM ACCEPT_TAC) THEN
    TRY(ASM_REWRITE_TAC[]); ALL_TAC] THEN
  DISCH_THEN(DESTRUCT_TAC
    "@om a1 a2 tw onetw ztw ii ci P leqp B inclB bp z. ctx") THEN
  REMOVE_THEN "ctx" STRIP_ASSUME_TAC THEN
  SUBGOAL_THEN `(a1:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[EORDINAL_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `(a2:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[EORDINAL_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `(tw:A) IN D` ASSUME_TAC THENL
   [FIRST_ASSUM(ACCEPT_TAC o CONJUNCT1 o GEN_REWRITE_RULE I [efin]);
    ALL_TAC] THEN
  SUBGOAL_THEN `(ii:A) IN D` ASSUME_TAC THENL
   [FIRST_ASSUM(ACCEPT_TAC o CONJUNCT1 o GEN_REWRITE_RULE I [ecross]);
    ALL_TAC] THEN
  SUBGOAL_THEN `(ci:A) IN D` ASSUME_TAC THENL
   [FIRST_ASSUM(ACCEPT_TAC o CONJUNCT1 o GEN_REWRITE_RULE I [ecross]);
    ALL_TAC] THEN
  SUBGOAL_THEN `(leqp:A) IN D` ASSUME_TAC THENL
   [FIRST_ASSUM(ACCEPT_TAC o CONJUNCT1 o GEN_REWRITE_RULE I [eleqp]);
    ALL_TAC] THEN
  SUBGOAL_THEN `(bp:A) IN D` ASSUME_TAC THENL
   [FIRST_ASSUM(ACCEPT_TAC o CONJUNCT1 o GEN_REWRITE_RULE I [ebplus]);
    ALL_TAC] THEN
  SUBGOAL_THEN `(z:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[EBOT_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) P B` ASSUME_TAC THENL
  [ASM_MESON_TAC[ETOP_IN]; ALL_TAC] THEN
  MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`P:A`;`om:A`]
         ECHECK_EXHAUSTION) THEN
  ANTS_TAC THENL
   [REPEAT CONJ_TAC THEN TRY(FIRST_ASSUM ACCEPT_TAC) THEN
    TRY(ASM_REWRITE_TAC[]); ALL_TAC] THEN DISCH_THEN(X_CHOOSE_TAC `omc:A`) THEN
  MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`P:A`;`a1:A`]
         ECHECK_EXHAUSTION) THEN
  ANTS_TAC THENL
   [REPEAT CONJ_TAC THEN TRY(FIRST_ASSUM ACCEPT_TAC) THEN
    TRY(ASM_REWRITE_TAC[]); ALL_TAC] THEN DISCH_THEN(X_CHOOSE_TAC `a1c:A`) THEN
  MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`P:A`;`a2:A`]
         ECHECK_EXHAUSTION) THEN
  ANTS_TAC THENL
   [REPEAT CONJ_TAC THEN TRY(FIRST_ASSUM ACCEPT_TAC) THEN
    TRY(ASM_REWRITE_TAC[]); ALL_TAC] THEN DISCH_THEN(X_CHOOSE_TAC `a2c:A`) THEN
  SUBGOAL_THEN `omc IN (D:A->bool) /\ a1c IN D /\ a2c IN D`
    STRIP_ASSUME_TAC THENL
   [REPEAT CONJ_TAC THEN ASM_MESON_TAC[echeck]; ALL_TAC] THEN
  SUBGOAL_THEN
    `bname D (E:A->A->bool) B omc /\ bname D E B a1c /\ bname D E B a2c`
    STRIP_ASSUME_TAC THENL
   [REPEAT CONJ_TAC THEN
    MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`P:A`;`B:A`]
                 ECHECK_IS_BNAME) THEN ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[];
    ALL_TAC] THEN
  MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`P:A`;`leqp:A`;`B:A`;`ci:A`;`om:A`;
                `ii:A`;`tw:A`]
         EMBFUN_EXISTS) THEN
  ANTS_TAC THENL
   [REPEAT CONJ_TAC THEN TRY(FIRST_ASSUM ACCEPT_TAC) THEN
    TRY(ASM_REWRITE_TAC[]); ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `embf:A` STRIP_ASSUME_TAC) THEN
  SUBGOAL_THEN `eisfun D (E:A->A->bool) embf` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`P:A`;`leqp:A`;`ci:A`;
                        `embf:A`] EMBF_ISFUN) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN
    `!cvs. cvs IN D /\ E cvs ci ==> ?b. b IN D /\
     eapply D (E:A->A->bool) embf cvs b`
    ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`P:A`;`leqp:A`;`B:A`;`ci:A`;
                        `om:A`;`ii:A`;
                        `tw:A`;`embf:A`] EMBF_TOTAL) THEN ASM_REWRITE_TAC[];
     ALL_TAC] THEN
  SUBGOAL_THEN
    `!cvs bb. cvs IN D /\ bb IN D /\
     eapply D (E:A->A->bool) embf cvs bb ==> E bb B`
    ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`P:A`;`leqp:A`;`B:A`;`ci:A`;
                        `om:A`;`ii:A`;
                        `tw:A`;`embf:A`] EMBF_VAL_IN_B) THEN ASM_REWRITE_TAC[];
     ALL_TAC] THEN
  MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`P:A`;`leqp:A`;`ci:A`;`om:A`;
                `P:A`;`embf:A`;
                `a2:A`;`ii:A`;`tw:A`;`onetw:A`] REALFN_EXISTS) THEN
  ANTS_TAC THENL
   [REPEAT CONJ_TAC THEN TRY(FIRST_ASSUM ACCEPT_TAC) THEN
    TRY(ASM_REWRITE_TAC[]); ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `realfn:A` STRIP_ASSUME_TAC) THEN
  SUBGOAL_THEN `eisfun D (E:A->A->bool) realfn` ASSUME_TAC THENL
   [MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`realfn:A`;`a2:A`;
      `\a z:A. ?n sig b p15 cvs. n IN D /\ sig IN D /\ b IN D /\
       p15 IN D /\ cvs IN D /\
               E n om /\ eopair D E sig b z /\ echeck D E P n sig /\
                 eopair D E a n p15 /\
               eopair D E p15 onetw cvs /\ eapply D E embf cvs b`]
                  REALFN_ISFUN) THEN
    CONV_TAC(DEPTH_CONV BETA_CONV) THEN
    REPEAT CONJ_TAC THEN TRY(FIRST_ASSUM MATCH_ACCEPT_TAC) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`inclB:A`;`omc:A`]
         POWNAME_OF) THEN
  ANTS_TAC THENL
   [REPEAT CONJ_TAC THEN TRY(FIRST_ASSUM ACCEPT_TAC) THEN
    TRY(ASM_REWRITE_TAC[]); ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `pw:A` (X_CHOOSE_THEN `FS:A` STRIP_ASSUME_TAC)) THEN
  MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`P:A`;`leqp:A`;`ci:A`;`om:A`;
                `embf:A`;`a2:A`;
                `ii:A`;`tw:A`;`onetw:A`;`B:A`;`realfn:A`] PERALPHA) THEN
  ANTS_TAC THENL
   [REPEAT CONJ_TAC THEN TRY(FIRST_ASSUM ACCEPT_TAC) THEN
    TRY(ASM_REWRITE_TAC[]); ALL_TAC] THEN
  DISCH_THEN(LABEL_TAC "pera") THEN
  SUBGOAL_THEN `eordinal D (E:A->A->bool) om` ASSUME_TAC THENL
   [MATCH_MP_TAC EOMEGA_ORDINAL THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `~(?e. einj D (E:A->A->bool) e a1 om)` ASSUME_TAC THENL
   [MATCH_MP_TAC ECARD_NO_INJ_DOWN THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `~(?e. einj D (E:A->A->bool) e a2 a1)` ASSUME_TAC THENL
   [MATCH_MP_TAC ECARD_NO_INJ_DOWN THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`a1:A`;`a2:A`] ECROSS_EXISTS) THEN
  ANTS_TAC THENL
   [REPEAT CONJ_TAC THEN TRY(FIRST_ASSUM ACCEPT_TAC) THEN
    TRY(ASM_REWRITE_TAC[]); ALL_TAC] THEN DISCH_THEN(X_CHOOSE_TAC `cr:A`) THEN
  SUBGOAL_THEN `(cr:A) IN D` ASSUME_TAC THENL
   [FIRST_ASSUM(ACCEPT_TAC o CONJUNCT1 o GEN_REWRITE_RULE I [ecross]);
    ALL_TAC] THEN
  SUBGOAL_THEN `!a. a IN D /\ E a a2
                    ==> ?rd. rd IN D /\ eapply D (E:A->A->bool) realfn a rd /\
                      bname D E B rd`
    (LABEL_TAC "cond1") THENL
   [X_GEN_TAC `a:A` THEN STRIP_TAC THEN
    USE_THEN "pera" (MP_TAC o SPEC `a:A`) THEN ANTS_TAC THENL
   [REPEAT CONJ_TAC THEN TRY(FIRST_ASSUM ACCEPT_TAC) THEN
    TRY(ASM_REWRITE_TAC[]); ALL_TAC] THEN
    DISCH_THEN(X_CHOOSE_THEN `rd:A` STRIP_ASSUME_TAC) THEN
    EXISTS_TAC `rd:A` THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `!b1 b2 rd1 rd2 e.
       b1 IN D /\ b2 IN D /\ rd1 IN D /\ rd2 IN D /\ e IN D /\
       E b1 a2 /\ E b2 a2 /\ ~(b1 = b2) /\
       eapply D (E:A->A->bool) realfn b1 rd1 /\ eapply D E realfn b2 rd2 /\
       ebv_eq D E B inclB rd1 rd2 e ==> ebot D E B inclB e`
    (LABEL_TAC "cond3") THENL
   [MAP_EVERY X_GEN_TAC [`b1:A`;`b2:A`;`rd1:A`;`rd2:A`;`e:A`] THEN
    STRIP_TAC THEN
    USE_THEN "pera" (MP_TAC o SPEC `b1:A`) THEN
    ANTS_TAC THENL
    [CONJ_TAC THEN TRY(FIRST_ASSUM ACCEPT_TAC) THEN
     FIRST_ASSUM MATCH_ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN(X_CHOOSE_THEN `r1:A` STRIP_ASSUME_TAC) THEN
    USE_THEN "pera" (MP_TAC o SPEC `b2:A`) THEN
    ANTS_TAC THENL
    [CONJ_TAC THEN TRY(FIRST_ASSUM ACCEPT_TAC) THEN
     FIRST_ASSUM MATCH_ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN(X_CHOOSE_THEN `r2:A` STRIP_ASSUME_TAC) THEN
    SUBGOAL_THEN `rd1:A = r1` SUBST_ALL_TAC THENL
     [MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`realfn:A`]
                   EAPPLY_UNIQUE) THEN
      EXISTS_TAC `b1:A` THEN
      REPEAT CONJ_TAC THEN TRY(FIRST_ASSUM ACCEPT_TAC) THEN
      TRY(FIRST_ASSUM MATCH_ACCEPT_TAC) THEN
      ASM_REWRITE_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN `rd2:A = r2` SUBST_ALL_TAC THENL
     [MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`realfn:A`]
                   EAPPLY_UNIQUE) THEN
      EXISTS_TAC `b2:A` THEN
      REPEAT CONJ_TAC THEN TRY(FIRST_ASSUM ACCEPT_TAC) THEN
      TRY(FIRST_ASSUM MATCH_ACCEPT_TAC) THEN
      ASM_REWRITE_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN `(E:A->A->bool) e B` ASSUME_TAC THENL
     [MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`inclB:A`;`r1:A`;
                          `r2:A`;`e:A`]
                   EBV_EQ_IN_B) THEN
      REPEAT CONJ_TAC THEN TRY(FIRST_ASSUM ACCEPT_TAC) THEN
      TRY(FIRST_ASSUM MATCH_ACCEPT_TAC) THEN
      ASM_REWRITE_TAC[]; ALL_TAC] THEN
    MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`P:A`;`leqp:A`;`ci:A`;
                        `om:A`;`a2:A`;`ii:A`;
                        `tw:A`;`P:A`;`embf:A`;`B:A`;`inclB:A`;`b1:A`;`b2:A`;
                        `onetw:A`;`ztw:A`;`r1:A`;`r2:A`;`e:A`]
      COHEN_REAL_DISTINCT) THEN
    REPEAT CONJ_TAC THEN TRY(FIRST_ASSUM ACCEPT_TAC) THEN
    TRY(FIRST_ASSUM MATCH_ACCEPT_TAC) THEN
    TRY(ASM_REWRITE_TAC[]); ALL_TAC] THEN
  SUBGOAL_THEN `!c. valuation D c /\ (!i. bname D (E:A->A->bool) B (c i))
                   ==> etop D E B inclB (bvalf D E B inclB c not_ch_ax)`
    ASSUME_TAC THENL
   [X_GEN_TAC `c:num->A` THEN STRIP_TAC THEN
    ABBREV_TAC `cp = (2 |-> pw) ((1 |-> a1c) ((0 |-> omc) (c:num->A)))` THEN
  SUBGOAL_THEN
    `valuation D (cp:num->A) /\ (!i. bname D (E:A->A->bool) B (cp i)) /\
     (cp:num->A) 0 = omc /\ cp 1 = a1c /\ cp 2 = pw` STRIP_ASSUME_TAC THENL
   [EXPAND_TAC "cp" THEN REPEAT CONJ_TAC THENL
     [REPEAT(MATCH_MP_TAC VALUATION_VALMOD THEN CONJ_TAC THENL
             [ALL_TAC; ASM_REWRITE_TAC[]]) THEN
      ASM_REWRITE_TAC[];
      REPEAT(MATCH_MP_TAC BNAMEVAL_VALMOD THEN CONJ_TAC THENL
             [ASM_REWRITE_TAC[]; ALL_TAC]) THEN
      ASM_REWRITE_TAC[];
      SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER; ARITH_EQ];
      SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER; ARITH_EQ];
      SIMP_TAC[VALMOD_BASIC]]; ALL_TAC] THEN
  SUBGOAL_THEN
    `!a. a IN D /\ E a a2 ==> ?rd. eapply D (E:A->A->bool) realfn a rd /\
     bname D E B rd /\
        rd IN D /\
          etop D E B inclB (bvalf D E B inclB ((5 |-> rd) cp) (5 %% 2))`
    (LABEL_TAC "cond2") THENL
   [X_GEN_TAC `a:A` THEN STRIP_TAC THEN
    USE_THEN "pera" (MP_TAC o SPEC `a:A`) THEN ANTS_TAC THENL
   [REPEAT CONJ_TAC THEN TRY(FIRST_ASSUM ACCEPT_TAC) THEN
    TRY(ASM_REWRITE_TAC[]); ALL_TAC] THEN
    DISCH_THEN(X_CHOOSE_THEN `rd:A` STRIP_ASSUME_TAC) THEN
    EXISTS_TAC `rd:A` THEN ASM_REWRITE_TAC[] THEN
    SUBGOAL_THEN
      `valuation D ((5|->rd)cp:num->A) /\
       (!i. bname D (E:A->A->bool) B (((5|->rd)cp:num->A) i))`
      STRIP_ASSUME_TAC THENL
     [CONJ_TAC THENL
       [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[];
        MATCH_MP_TAC BNAMEVAL_VALMOD THEN ASM_REWRITE_TAC[]]; ALL_TAC] THEN
    SUBGOAL_THEN `((5|->rd)cp:num->A) 5 = rd /\ ((5|->rd)cp:num->A) 2 = pw`
      STRIP_ASSUME_TAC THENL
      [CONJ_TAC THENL
       [REWRITE_TAC[VALMOD_BASIC];
        SUBGOAL_THEN `((5|->rd)cp:num->A) 2 = (cp:num->A) 2` SUBST1_TAC THENL
         [MATCH_MP_TAC VALMOD_OTHER THEN ARITH_TAC; ASM_REWRITE_TAC[]]];
       ALL_TAC] THEN
    SUBGOAL_THEN `ebv_in D (E:A->A->bool) B inclB rd pw
                    (bvalf D E B inclB ((5|->rd)cp) (5 %% 2))` ASSUME_TAC THENL
     [MP_TAC(ISPECL[`5`;`2`;`D:A->bool`;`E:A->A->bool`;`B:A`;`inclB:A`;
                    `(5|->rd)cp:num->A`]
             BVALF_MEM) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`inclB:A`;`P:A`;`embf:A`;
                  `a:A`;`onetw:A`;
                  `om:A`;`omc:A`;`rd:A`;`pw:A`;`FS:A`] REAL_IN_POW) THEN
    ANTS_TAC THENL
     [REPEAT CONJ_TAC THEN TRY(FIRST_ASSUM ACCEPT_TAC) THEN
      TRY(FIRST_ASSUM MATCH_ACCEPT_TAC) THEN
      TRY(ASM_REWRITE_TAC[]); ALL_TAC] THEN
    DISCH_THEN MATCH_MP_TAC THEN ASM_REWRITE_TAC[] THEN
    MATCH_MP_TAC BVALF_IND THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `etop D (E:A->A->bool) B inclB (bvalf D E B inclB cp not_ch_ax)`
    ASSUME_TAC THENL
    [MATCH_MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`P:A`;`leqp:A`;`B:A`;
                         `inclB:A`;`bp:A`;
                         `P:A`;`om:A`;`omc:A`;`a1:A`;`a1c:A`;`a2:A`;`a2c:A`;
                         `pw:A`;`FS:A`;`realfn:A`;`cr:A`;
      `cp:num->A`;`z:A`] NOT_CH_TOP) THEN
    REPEAT CONJ_TAC THEN TRY(FIRST_ASSUM ACCEPT_TAC) THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
    `bvalf D (E:A->A->bool) B inclB c not_ch_ax = bvalf D E B inclB
     cp not_ch_ax`
    SUBST1_TAC THENL
   [MATCH_MP_TAC BVALF_FV_CONG THEN
    ASM_REWRITE_TAC[] THEN X_GEN_TAC `i:num` THEN DISCH_TAC THEN
    SUBGOAL_THEN `~(i = 0) /\ ~(i = 1) /\ ~(i = 2)` STRIP_ASSUME_TAC THENL
     [MP_TAC FV_NOT_CH_012 THEN ASM_MESON_TAC[]; ALL_TAC] THEN
    EXPAND_TAC "cp" THEN ASM_SIMP_TAC[VALMOD_OTHER]; ALL_TAC] THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MAP_EVERY EXISTS_TAC [`B:A`;`inclB:A`;`z:A`;`P:A`] THEN
  ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[]);;

(* ================================================================= *)
(* VL_MODEL_NOT_CH_MODEL : the forcing step.  From any model of ZF   *)
(* + V=L (every element internally constructible, i.e. elmem-closed) *)
(* the Cohen-over-L Boolean construction (NOT_CH_FORCED) + any ultra-   *)
(* filter (EULTRA_EXISTS) + the quotient transfer                    *)
(* (FORCE_NOT_CH_FROM_FORCED) yield a quotient model of                 *)
(* not_ch_ax INSERT choice_ax INSERT ZF_AX.                             *)
(* ================================================================= *)
let VL_MODEL_NOT_CH_MODEL = prove
 (`!D (E:A->A->bool).
     model D E ZF_AX /\ (!u:A. u IN D ==> elmem D E u)
     ==> ?B leq U. model (qdom D E B leq U) (qmem D E B leq U)
                         (not_ch_ax INSERT choice_ax INSERT ZF_AX)`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`] NOT_CH_FORCED) THEN
  ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  DISCH_THEN(DESTRUCT_TAC "@B leq bot top. ctx") THEN
  REMOVE_THEN "ctx" STRIP_ASSUME_TAC THEN
  MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`B:A`;`leq:A`;`bot:A`;`top:A`]
         EULTRA_EXISTS) THEN
  ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `U:A` STRIP_ASSUME_TAC) THEN
  MAP_EVERY EXISTS_TAC [`B:A`;`leq:A`;`U:A`] THEN
  MATCH_MP_TAC FORCE_NOT_CH_FROM_FORCED THEN
  REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC);;

(* ================================================================= *)
(* ZF_MODEL_VL_MODEL : pass to the constructible inner model L.      *)
(* From ANY model of ZF, its L = lclass D E is a submodel that is    *)
(* itself a model of ZF and satisfies V=L (every element is          *)
(* internally constructible: elmem-closed).  This is exactly the     *)
(* V=L hypothesis the forcing step VL_MODEL_NOT_CH_MODEL needs,      *)
(* discharged here internally (L^L = L, LCLASS_IDEMPOTENT).          *)
(* ================================================================= *)
let ZF_MODEL_VL_MODEL = prove
 (`!D (E:A->A->bool).
     model D E ZF_AX
     ==> ?D'. D' SUBSET D /\ model D' E ZF_AX /\
              (!u:A. u IN D' ==> elmem D' E u)`,
  REPEAT GEN_TAC THEN DISCH_TAC THEN
  EXISTS_TAC `lclass D (E:A->A->bool)` THEN
  REPEAT CONJ_TAC THENL
   [REWRITE_TAC[LCLASS_SUBSET];
    MATCH_MP_TAC MODEL_LCLASS THEN ASM_REWRITE_TAC[];
    X_GEN_TAC `u:A` THEN DISCH_TAC THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`] LCLASS_IDEMPOTENT) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun eq ->
      SUBGOAL_THEN `(u:A) IN lclass (lclass D E) (E:A->A->bool)` MP_TAC THENL
       [ASM_REWRITE_TAC[eq]; ALL_TAC]) THEN
    REWRITE_TAC[IN_LCLASS] THEN
    DISCH_THEN(MP_TAC o CONJUNCT2) THEN DISCH_THEN ACCEPT_TAC]);;

(* ================================================================= *)
(* ZF_MODEL_NOT_CH_MODEL : the main theorem, in semantic form.        *)
(* From ANY model of ZF, with no V=L or constructibility hypothesis  *)
(* on the ambient M, a model of not_ch_ax INSERT choice_ax INSERT    *)
(* ZF_AX exists.                                                     *)
(*                                                                   *)
(* Pure composition, no new mathematics:  pass to the inner model    *)
(* L (ZF_MODEL_VL_MODEL) -- a submodel of M that models ZF and in    *)
(* which V=L holds -- then run Cohen forcing over L adjoining aleph2 *)
(* reals (VL_MODEL_NOT_CH_MODEL).  L furnishes the V=L hypothesis,   *)
(* so the ambient M need only be a model of ZF.  Same ambient type   *)
(* A throughout: L is a submodel over A, the forcing quotient is     *)
(* realized over A (ANY-ultrafilter, no Lowenheim-Skolem).           *)
(* ================================================================= *)
let ZF_MODEL_NOT_CH_MODEL = prove
 (`!D (E:A->A->bool).
     model D E ZF_AX
     ==> ?D'' (E'':A->A->bool).
             model D'' E'' (not_ch_ax INSERT choice_ax INSERT ZF_AX)`,
  REPEAT GEN_TAC THEN DISCH_TAC THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`] ZF_MODEL_VL_MODEL) THEN
  ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `D':A->bool` STRIP_ASSUME_TAC) THEN
  MP_TAC(ISPECL [`D':A->bool`; `E:A->A->bool`] VL_MODEL_NOT_CH_MODEL) THEN
  ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `B:A` (X_CHOOSE_THEN `leq:A`
    (X_CHOOSE_THEN `U:A` ASSUME_TAC))) THEN
  MAP_EVERY EXISTS_TAC
   [`qdom D' (E:A->A->bool) B leq U`; `qmem D' (E:A->A->bool) B leq U`] THEN
  FIRST_ASSUM ACCEPT_TAC);;

(* ------------------------------------------------------------------------- *)
(* Since GCH implies CH in any model of ZF (HOLDS_GCH_IMP_CH), the same      *)
(* models refute GCH. With ZF_MODEL_GCH_MODEL this gives the independence of *)
(* GCH as well as of CH.                                                     *)
(* ------------------------------------------------------------------------- *)

let ZF_MODEL_NOT_GCH_MODEL = prove
 (`!D (E:A->A->bool).
        model D E ZF_AX
        ==> ?D'' (E'':A->A->bool).
              model D'' E'' (Not gch_ax INSERT choice_ax INSERT ZF_AX)`,
  REPEAT GEN_TAC THEN
  DISCH_THEN(MP_TAC o MATCH_MP ZF_MODEL_NOT_CH_MODEL) THEN
  REPEAT(MATCH_MP_TAC MONO_EXISTS THEN GEN_TAC) THEN
  REWRITE_TAC[model; satisfies; IN_INSERT] THEN
  STRIP_TAC THEN ASM_REWRITE_TAC[] THEN
  MAP_EVERY X_GEN_TAC [`v:num->A`; `p:form`] THEN
  DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC
   (DISJ_CASES_THEN2 SUBST1_TAC ASSUME_TAC)) THEN
  ASM_SIMP_TAC[] THEN REWRITE_TAC[HOLDS_NOT] THEN DISCH_TAC THEN
  FIRST_ASSUM(MP_TAC o SPECL [`v:num->A`; `not_ch_ax`]) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; REWRITE_TAC[not_ch_ax; HOLDS_NOT]] THEN
  MATCH_MP_TAC HOLDS_GCH_IMP_CH THEN ASM_SIMP_TAC[model; satisfies]);;
